__reload_all = true
local System = require("System.System")
local readonly = System.readonly
local Text_AvgDialog = readonly({
  AvgDialog_100303_Content_1 = {
    Text = "Huff... huff... No, non è questo... qualcosa ancora non va..."
  },
  AvgDialog_100303_Content_10 = {
    Text = "Perché è proprio davanti a me, eppure non riesco a trovarla..."
  },
  AvgDialog_100303_Content_11 = {
    Text = "Non preoccuparti, Pickman. Se la Musa te l'ha già rivelato, allora la risposta dev'essere vicinissima a te. Rifletti bene su cosa potresti aver tralasciato."
  },
  AvgDialog_100303_Content_12 = {
    Text = "Prima di tutto, lascia che ti aiuti ad alzarti... Ahi..."
  },
  AvgDialog_100303_Content_13 = {
    Text = "Ritrai la mano di scatto. Nel suo corpo rovente scorre qualcosa che sembra lava."
  },
  AvgDialog_100303_Content_14 = {
    Text = "Come previsto, è di nuovo Thais a causare problemi..."
  },
  AvgDialog_100303_Content_15 = {
    Text = "Thais... Ah! Giusto! Come ho potuto non pensarci! Come ho potuto trascurarlo!!"
  },
  AvgDialog_100303_Content_16 = {
    Text = "Si raddrizza di colpo, il suo sguardo, quasi incandescente, si fissa direttamente su di te."
  },
  AvgDialog_100303_Content_17 = {
    Text = "Il desiderio più folle... esatto! Vedo, vedo..."
  },
  AvgDialog_100303_Content_18 = {
    Text = "È così eccitato che dimentica di alzarsi, strisciando verso di te a quattro zampe."
  },
  AvgDialog_100303_Content_19 = {
    Text = "Custode, puoi posare per me ancora una volta? Ti prego! È l'ultima volta!"
  },
  AvgDialog_100303_Content_2 = {Text = "Pickman?"},
  AvgDialog_100303_Content_20 = {
    Text = "So cosa vuoi fare, assolutamente no..."
  },
  AvgDialog_100303_Content_21 = {
    Text = "Gli occhi rossi di Pickman, ansiosi e imploranti, tremolano appena nella luce fioca. Le tue parole di rifiuto non riescono più a uscire."
  },
  AvgDialog_100303_Content_22 = {
    Text = "...Va bene. Se devo solo fare da modello. Devo sedermi di nuovo su quel divano?"
  },
  AvgDialog_100303_Content_23 = {
    Text = "No, no, Custode! Un dipinto come questo non può essere creato in uno studio!"
  },
  AvgDialog_100303_Content_24 = {Text = "..."},
  AvgDialog_100303_Content_25 = {
    Text = "Questo è... il mondo nel tuo dipinto?"
  },
  AvgDialog_100303_Content_26 = {
    Text = "Esatto! È il rito carnevalesco dei ghoul!"
  },
  AvgDialog_100303_Content_27 = {
    Text = "L'ho creato, ma non l'ho mai terminato. Manca una coppia di protagonisti al centro. Rappresentano i desideri più primitivi e selvaggi di questo universo, i desideri che ho dimenticato..."
  },
  AvgDialog_100303_Content_28 = {
    Text = "Non avevo trovato un modello degno di diventare il protagonista fino ad ora..."
  },
  AvgDialog_100303_Content_29 = {
    Text = "Pickman resta in ginocchio, trascinando il ginocchio più vicino a te."
  },
  AvgDialog_100303_Content_3 = {
    Text = "Il tetro studio di Pickman è più disordinato del solito, con innumerevoli fogli di pelle coperti di colori e linee sparsi a caso in ogni angolo, come se vi si fosse consumata una guerra bizzarra."
  },
  AvgDialog_100303_Content_30 = {
    Text = "Ti prego, Custode... concedimi la Musa!"
  },
  AvgDialog_100303_Content_31 = {
    Text = "Puoi chiedermi qualsiasi cosa! TI PREGO! Per favore, aiutami a completare questo dipinto..."
  },
  AvgDialog_100303_Content_32 = {
    Text = "Senza esitare a lungo, sospiri dolcemente e ti avvicini a lui."
  },
  AvgDialog_100303_Content_33 = {
    Text = "Alza il capo e ti guarda con occhi spalancati. Quegli occhi appartengono a una creatura al tempo stesso bramosa, anelante, obbediente e devota — una bestia o un animale fedele. Sta implorando, supplicando un comando che lo conduca alla Musa."
  },
  AvgDialog_100303_Content_34 = {
    Text = "Qualsiasi cosa, eh... Allora, devo pensarci bene..."
  },
  AvgDialog_100303_Content_35 = {
    Text = "La tua mano si posa delicatamente sul volto di Pickman. Il suo respiro caldo indugia, ma il suo corpo diventa istantaneamente docile. Non sai se lo stai domando o se è lui a scioglierti."
  },
  AvgDialog_100303_Content_36 = {
    Text = "I suoni dei ghoul iniziano a svanire, sostituiti dalle voci ruvide e primordiali dei protagonisti, che risuonano in tutto il mondo all'interno del dipinto."
  },
  AvgDialog_100303_Content_37 = {
    Text = "Quella è la Voce della Musa."
  },
  AvgDialog_100303_Content_4 = {
    Text = "Lui, con gli abiti in disordine, è in ginocchio, e imbratta freneticamente un foglio bianco, quasi lacerandolo. La vernice schizzata gli ricopre il corpo, facendolo somigliare a un devoto nel mezzo di un rito selvaggio."
  },
  AvgDialog_100303_Content_5 = {
    Text = "Cosa sta succedendo..."
  },
  AvgDialog_100303_Content_6 = {
    Text = "L'ho udita, Custode! Ho udito la Voce della Musa chiamare! Proprio nel mio orecchio!"
  },
  AvgDialog_100303_Content_7 = {
    Text = "I miei Occhi, le mie Mani, il mio cuore, ogni cellula del mio corpo trema al suo richiamo!"
  },
  AvgDialog_100303_Content_8 = {
    Text = "Così vicino! Sono a un solo passo dall'arte suprema!"
  },
  AvgDialog_100303_Content_9 = {
    Text = "Ma non riesco a trovarla... massacro, conquista, gola, bramosia, spreco, vuoto... Ho raffigurato ogni follia, eppure ancora non l'ho trovata..."
  },
  AvgDialog_100588_Content_1 = {
    Text = "Una figura nera come la pece appare gradualmente davanti a te."
  },
  AvgDialog_100588_Content_2 = {
    Text = "[Attack]???"
  },
  AvgDialog_100588_Content_3 = {
    Text = "Hai inflitto 677 danni! Senti di averGli inflitto un totale di 27.188 danni.\nTutti insieme Gli hanno inflitto un totale di 14.636.643.707 danni, ma Lui non è ancora caduto."
  },
  AvgDialog_100588_Content_4 = {Text = "[Continue]"},
  AvgDialog_100588_Content_5 = {
    Text = "Hai avuto la sensazione di essere già stato qui...\nSotto lo sguardo vigile della figura oscura, la tua coscienza si è offuscata gradualmente."
  },
  AvgDialog_100588_Content_6 = {Text = "[Sleep]"},
  AvgDialog_100629_Content_1 = {
    Text = "Non molto tempo dopo, questo mondo non fu più afflitto dall'erosione; l'umanità si sviluppò rapidamente, e in seguito l'Università di Masagog intercettò un treno nel cielo stellato..."
  },
  AvgDialog_10120_Content_1 = {
    Text = "Proteggi il dispositivo di comando nella tua mano e guardati dalla Dissoluzione! Sarà essenziale nella battaglia imminente!"
  },
  AvgDialog_10120_Content_2 = {
    Text = "Tieni premuta una <Yellow:Carta di Comando>, trascinala verso l'alto e poi rilasciala per comandarmi in combattimento."
  },
  AvgDialog_10121_Content_1 = {
    Text = "<Yellow:Argento>? Non mi aspettavo di trovarne qui..."
  },
  AvgDialog_10121_Content_2 = {
    Text = "Che si tratti di forgiare Chiavi d'argento, collegare Risvegliatori o fornire energia spirituale... tutto dipende dall'<Yellow:Argento>."
  },
  AvgDialog_10121_Content_3 = {
    Text = "Anche quantità minime di <Yellow:Argento> hanno un valore straordinario per la ricerca di Mythag. Raccogline il più possibile."
  },
  AvgDialog_10122_Content_1 = {
    Text = "Indugiare è pericoloso. Dobbiamo finire in fretta."
  },
  AvgDialog_10122_Content_2 = {
    Text = "Questa è la <Yellow:\"Spada della Regina\">, una tecnica che pratico fin dall'infanzia. Possa abbattere il nostro nemico!"
  },
  AvgDialog_10123_Content_1 = {
    Text = "Scivoli attraverso una porta nascosta sotto la Torre dell'Orologio, entrando in un passaggio celato."
  },
  AvgDialog_10123_Content_10 = {Text = "..."},
  AvgDialog_10123_Content_11 = {
    Text = "Il grande portale si apre lentamente, offrendoti il primo sguardo nel sancta sanctorum proibito."
  },
  AvgDialog_10123_Content_13 = {
    Text = "La Loro parte superiore luminosa fluttua sopra la melma nera, l'Oscurità inchiostrata non fa che accentuare la Loro purezza accecante."
  },
  AvgDialog_10123_Content_14 = {
    Text = "Ipnotizzato, fissi l'entità inumana; i Suoi contorni si sovrappongono per un istante a quelli della giovane donna che hai visto durante la trance al Keygrave."
  },
  AvgDialog_10123_Content_15 = {
    Text = "Non hanno volto, eppure il Loro portamento irradia una compassione profonda."
  },
  AvgDialog_10123_Content_16 = {
    Text = "Il Supremo. Il Più Puro. Il Più Nobile. Il Più Bello."
  },
  AvgDialog_10123_Content_17 = {
    Text = "<Shake:Tu... sei arrivato...>"
  },
  AvgDialog_10123_Content_18 = {
    Text = "Il pallido mostro emette un grido rauco; ruggito e lamento intrecciati."
  },
  AvgDialog_10123_Content_19 = {
    Text = "Non era assolutamente linguaggio umano, eppure comprendi perfettamente il Suo significato."
  },
  AvgDialog_10123_Content_2 = {
    Text = "Doll avanza, i suoi passi risuonano metallici sulla passerella a ogni falcata."
  },
  AvgDialog_10123_Content_20 = {
    Text = "La tua visuale si offusca e inaspettatamente, gli occhi ti bruciano. Caldi rivoli tracciano sentieri lungo le tue guance."
  },
  AvgDialog_10123_Content_21 = {
    Text = "Sono lacrime? Ma perché? Cos'è questo dolore che ti stringe il petto?"
  },
  AvgDialog_10123_Content_22 = {
    Text = "...<Yellow:Tawil>?"
  },
  AvgDialog_10123_Content_23 = {
    Text = "Il nome mormorato da Doll fa mutare l'Espressione di Ramona."
  },
  AvgDialog_10123_Content_24 = {
    Text = "Tawil? Il Risvegliatore Tawil, uno dei fondatori?"
  },
  AvgDialog_10123_Content_25 = {
    Text = "Lo ricordi anche tu. <Blue:La Storia di Mythag> elenca questo nome insieme ad altri due."
  },
  AvgDialog_10123_Content_26 = {
    Text = "Nell'anno AF 90, <Blue:Ward Philips>, <Blue:Khlarcus> e <Blue:Tawil> fondarono il <Blue:Collegio di Mythag>."
  },
  AvgDialog_10123_Content_27 = {
    Text = "Era lì che ti trovavi ora. Il predecessore dell'odierna <Blue:Università di Mythag>."
  },
  AvgDialog_10123_Content_28 = {Text = "Custode."},
  AvgDialog_10123_Content_29 = {Text = "Sono qui."},
  AvgDialog_10123_Content_3 = {
    Text = "Un Passaggio segreto sotto la torre dell'Orologio? Non ne avevo mai sentito parlare..."
  },
  AvgDialog_10123_Content_30 = {
    Text = "Il fatto che Tawil non ti abbia ancora espulso... può significare solo che il tuo destino è ormai legato a quello di Mythag."
  },
  AvgDialog_10123_Content_31 = {
    Text = "Pertanto, hai guadagnato il diritto di ascoltare questo."
  },
  AvgDialog_10123_Content_32 = {
    Text = "Questo è il segreto più profondo dell'Università di Mythag. Tawil, uno dei nostri tre fondatori, non è né umano né Risvegliatore."
  },
  AvgDialog_10123_Content_33 = {
    Text = "È un'entità extradimensionale, percepita inizialmente come semplici Sussurri da Phillips, il primo Rettore."
  },
  AvgDialog_10123_Content_34 = {
    Text = "Contrariamente a quanto si crede, Tawil non è un Risvegliato. La raffinazione dell'Argento e il <Yellow:Risveglio post-mortem degli individui in risonanza con la Volontà Superiore> furono sviluppati sotto la Loro guida."
  },
  AvgDialog_10123_Content_35 = {
    Text = "Predissero l'imminente Dissoluzione, condivisero la prima \"Verità,\" poi caddero in uno stato dormiente dopo aver fondato il Collegio di Mythag."
  },
  AvgDialog_10123_Content_36 = {
    Text = "I documenti di Phillips suggeriscono che \"Tawil\" abbia scelto questo stato di \"Inesistenza\" per eludere l'osservazione."
  },
  AvgDialog_10123_Content_37 = {
    Text = "Solo quando La Variabile emergerà, Essi si risveglieranno—"
  },
  AvgDialog_10123_Content_38 = {Text = "Guardate!"},
  AvgDialog_10123_Content_39 = {
    Text = "Come a presagire il disastro, \"Tawil\" emise uno Strido lacerante per i timpani."
  },
  AvgDialog_10123_Content_4 = {
    Text = "Se fosse di dominio pubblico, difficilmente si qualificherebbe come passaggio segreto. Questo tunnel conduce alla <Yellow:Pozza Nera>... le fondamenta di Mythag."
  },
  AvgDialog_10123_Content_40 = {
    Text = "Con il tremito di un pulcino che rompe il proprio guscio, sei magnifiche ali d'Argento eruppero dal Loro corpo."
  },
  AvgDialog_10123_Content_41 = {
    Text = "Un liquido simile all'Argento gocciola incessantemente da ogni punta d'ala, creando una lieve percussione nell'impattare la Pozza nera sottostante."
  },
  AvgDialog_10123_Content_42 = {
    Text = "Quando la sostanza scintillante incontra il nero pece della pozza, questa ribolle violentemente. Dalle sue profondità emergono grottesche creature della Dissoluzione."
  },
  AvgDialog_10123_Content_43 = {
    Text = "Le abominazioni incomprensibili si disperdono; alcune caricano il vostro gruppo, mentre le restanti dilagano verso la piazza della Torre dell'Orologio."
  },
  AvgDialog_10123_Content_44 = {
    Text = "<Shake:Finalmente... trovato... te...>"
  },
  AvgDialog_10123_Content_45 = {
    Text = "Dobbiamo fermarLi! È l'unico modo per impedire che altri Mostri emergano!"
  },
  AvgDialog_10123_Content_5 = {
    Text = "Senza il gigantesco artefatto d'Argento noto come il <Yellow:Nucleo> sul fondo della Pozza nera, la nostra tecnologia dei Risvegliatori regredrebbe di decenni. Gli spiriti umani da soli sono troppo fragili per sostenerla."
  },
  AvgDialog_10123_Content_6 = {
    Text = "Quindi la restrizione sui Risvegliati non legati... serve a proteggerci dal soccombere alla Follia?"
  },
  AvgDialog_10123_Content_7 = {
    Text = "Non è del tutto vero. Se tutti i Risvegliatori fossero gestibili come te, Ogier, il mio lavoro sarebbe molto più semplice."
  },
  AvgDialog_10123_Content_8 = {
    Text = "Bene, siamo arrivati."
  },
  AvgDialog_10123_Content_9 = {
    Text = "Mentre parla, Doll preme un pulsante poco appariscente sulla parete. Un suono acuto risuona mentre la porta scorre, rivelando una camera angusta e scarsamente illuminata oltre di essa."
  },
  AvgDialog_10124_Content_1 = {
    Text = "Sembra che tu abbia trovato il tuo ritmo. Il comando è tuo, Custode!"
  },
  AvgDialog_10125_Content_1 = {
    Text = "Uff. Mi dispiace, non c'è tempo perché tu possa abituarti a tutto questo come si deve."
  },
  AvgDialog_10125_Content_10 = {
    Text = "Ramona sembra terrorizzata; non l'hai mai vista così sconvolta."
  },
  AvgDialog_10125_Content_11 = {
    Text = "La ragazza, bombardata di domande, parla con voce tremante, la sua fatica evidente."
  },
  AvgDialog_10125_Content_12 = {
    Text = "La riconosci: la Professoressa Doll, appartenente all'<Blue:Istituto di Ricerca sul Risveglio> e notoriamente difficile con cui comunicare. In altre parole, una non combattente."
  },
  AvgDialog_10125_Content_13 = {
    Text = "Ovviamente. Pensavi che fossi venuta qui per una passeggiata di piacere?"
  },
  AvgDialog_10125_Content_14 = {
    Text = "Chiude gli occhi, ricomponendosi in fretta."
  },
  AvgDialog_10125_Content_15 = {
    Text = "Anche il Keygrave è compromesso? Siamo vicini all'uscita posteriore. Voi due dovreste evacuare immediatamente."
  },
  AvgDialog_10125_Content_16 = {
    Text = "Possiamo aiutare! %player% può stabilire un collegamento con noi e prendere il comando—"
  },
  AvgDialog_10125_Content_17 = {
    Text = "Ramona. Questo è il nostro dovere. %player% è ancora una matricola, appena diplomata dalla scuola preparatoria."
  },
  AvgDialog_10125_Content_18 = {
    Text = "%player% si è già collegato con me, e so che {Male=è,Female=è} all'altezza del compito. Credo in {Male=lui,Female=lei}!"
  },
  AvgDialog_10125_Content_19 = {
    Text = "Doll ti scruta attentamente, poi si volta verso Ramona con un'espressione severa."
  },
  AvgDialog_10125_Content_2 = {
    Text = "Questi Mutanti hanno raggiunto il Keygrave prima che l'allarme suonasse. La <Blue:Barriera di Nebbia> attorno al Mythag dev'essere caduta."
  },
  AvgDialog_10125_Content_20 = {
    Text = [[
Se non mi sbaglio, la cerimonia del giuramento dovrebbe essere ancora incompleta.
{Male=He,Female=She} non ha ancora ricevuto la Chiave d'argento, giusto?]]
  },
  AvgDialog_10125_Content_21 = {
    Text = "Ci addentreremo in un'area <Bold:ristretta>. Mi aspetterei che qualcuno cresciuto al Mythag comprenda cosa significhi."
  },
  AvgDialog_10125_Content_22 = {
    Text = "È un'emergenza! Non abbiamo scelta, no? Inoltre, %player% non è una matricola qualunque. {Male=He's,Female=She's} il nostro unico Custode."
  },
  AvgDialog_10125_Content_23 = {
    Text = "Non ricordi l'<Yellow:Esplosione di Yakutsk> di un anno fa? Se non fosse stato per {Male=lui,Female=lei}, che da solo collegò tutti i Risvegliati, io non sarei qui a discutere con te in questo momento."
  },
  AvgDialog_10125_Content_24 = {
    Text = "La ragazza dai capelli rosa non risponde e, invece, si volta verso di te."
  },
  AvgDialog_10125_Content_25 = {
    Text = "So che hai intravisto ciò che giace oltre il <Yellow:Portale>; ma la realtà, che si tratti delle fondamenta del Mythag o del Fato del mondo, potrebbe non essere come la idealizzi."
  },
  AvgDialog_10125_Content_26 = {
    Text = "Stiamo combattendo un fenomeno che disfa l'esistenza stessa. Una volta contaminati dalla <Yellow:Dissoluzione>, tutto ciò che è <Bold:te> svanirà interamente da questo mondo."
  },
  AvgDialog_10125_Content_27 = {
    Text = "L'iscrizione sulla tua lapide e la tua eredità saranno ridotte a una melma di nulla, dimenticate da tutti."
  },
  AvgDialog_10125_Content_28 = {
    Text = "Rispondimi. Sei davvero pronto per questo?"
  },
  AvgDialog_10125_Content_29 = {
    Text = "Lo Sguardo gelido di Doll incontra il tuo, la sua Voce piatta."
  },
  AvgDialog_10125_Content_3 = {
    Text = "Abbiamo informato <Blue:William> della cerimonia odierna, ma nessun rinforzo è giunto in nostro aiuto. La campana... dovremmo riorganizzarci ed <Yellow:eliminare la fonte dell'anomalia>!"
  },
  AvgDialog_10125_Content_30 = {
    Text = "Il suo volto non tradisce nulla, ma nel profondo delle sue gelide pupille, intravedi un fuoco ardente."
  },
  AvgDialog_10125_Content_31 = {
    Text = "La tua risposta è—"
  },
  AvgDialog_10125_Content_32 = {
    Text = "La mia lapide ora si erge come parte del Keygrave."
  },
  AvgDialog_10125_Content_33 = {
    Text = "Sei un membro del Mythag. Forse lo eri già a Yakutsk."
  },
  AvgDialog_10125_Content_34 = {
    Text = "Ci sono cose che solo io posso compiere."
  },
  AvgDialog_10125_Content_35 = {
    Text = "La decisione può essere affrettata, ma si può mai essere davvero preparati a tutto nella vita?"
  },
  AvgDialog_10125_Content_36 = {Text = "Bene."},
  AvgDialog_10125_Content_37 = {
    Text = "Per l'Autorità del Sesto Preside del Mythag, <Blue:Oliver Elsie>, con la presente ti conferisco la Chiave d'Argento K-0617."
  },
  AvgDialog_10125_Content_39 = {
    Text = "Doll recupera la Chiave d'Argento da un cofanetto ornato e la posa sul tuo petto. Emana un debole bagliore, inondandoti di una vaga sensazione di familiarità."
  },
  AvgDialog_10125_Content_4 = {
    Text = "Quello è...?!"
  },
  AvgDialog_10125_Content_40 = {
    Text = "D'ora in avanti, ti ergi come Custode tra i molti studenti e studiosi di Mythag."
  },
  AvgDialog_10125_Content_41 = {Text = "..."},
  AvgDialog_10125_Content_42 = {
    Text = "Ora, stabilisci un Legame con me."
  },
  AvgDialog_10125_Content_43 = {
    Text = "Segui il tuo addestramento e attivi con cautela la Chiave d'argento. Una luce argentea tremola mentre fili invisibili legano i tuoi sensi a quelli di Doll."
  },
  AvgDialog_10125_Content_44 = {
    Text = "Innumerevoli immagini si riversano attraverso la connessione, elettriche e travolgenti. Il tuo cuore batte violentemente mentre lotti per restare in piedi."
  },
  AvgDialog_10125_Content_45 = {
    Text = "Doll, tu..."
  },
  AvgDialog_10125_Content_46 = {
    Text = "Il tuo tempismo è adeguato, Custode. Ogier e io... eravamo al limite."
  },
  AvgDialog_10125_Content_47 = {
    Text = "Resta qui e riposati. Ramona e io ci uniremo alla Battaglia e supporteremo Ogier."
  },
  AvgDialog_10125_Content_48 = {
    Text = "Compostezza, per favore. Non puoi compensare le ferite di Ramona con l'avventatezza. Al momento non è in condizioni di combattere."
  },
  AvgDialog_10125_Content_49 = {
    Text = "Quel ragazzo, Ogier, può resistere ancora un po'. Seguimi, prima."
  },
  AvgDialog_10125_Content_6 = {
    Text = "Ai margini della tua Visuale, un giovane biondo solleva un enorme scudo nero, respingendo a malapena l'Assalto di una spadaccina con due lame."
  },
  AvgDialog_10125_Content_7 = {
    Text = "Protegge una ragazza dai capelli rosa dietro di sé; ogni colpo deviato lo costringe a indietreggiare di un altro passo."
  },
  AvgDialog_10125_Content_8 = {
    Text = "Aspetta, l'assalitrice... è la <Yellow:Risvegliatrice> Lotan?!"
  },
  AvgDialog_10125_Content_9 = {
    Text = "Doll? La <Blue:Torre dell'Orologio> è stata compromessa?!"
  },
  AvgDialog_10126_Content_1 = {
    Text = "Quando i tuoi HP scendono a 0, la tua mente faticherà a proseguire l'indagine in un <Yellow:Dominio>. Per la tua sicurezza, verrai evacuato."
  },
  AvgDialog_10126_Content_2 = {
    Text = "La situazione è critica! Ho regolato la potenza del dispositivo in base ai tuoi parametri vitali, caricando al massimo il nostro Aliemus!"
  },
  AvgDialog_10126_Content_3 = {
    Text = "Così come stanno le cose, ci resta un solo ricorso... potrebbe essere pericoloso, ma non abbiamo alternative. Ora, scatena la mia Esaltazione per porre fine a questa Battaglia!"
  },
  AvgDialog_10127_Content_1 = {
    Text = "Che calore... la connessione è perfetta. Il tuo spirito e la tua forza vitale non hanno mai brillato così intensamente."
  },
  AvgDialog_10127_Content_2 = {
    Text = [[
Non puoi cadere facilmente, <Yellow:unico al mondo> Custode.
Contiamo su di te per indagare e documentare tutta la storia cancellata dalla Dissoluzione.]]
  },
  AvgDialog_10127_Content_3 = {
    Text = "La preoccupazione nei suoi occhi svanisce mentre Ramona accenna un rassicurante mezzo sorriso."
  },
  AvgDialog_10127_Content_4 = {
    Text = "Il suono della pioggia sottile riempie il mondo."
  },
  AvgDialog_10127_Content_5 = {
    Text = "Eppure, con la caduta di una singola goccia di pioggia, <Red:inquietudine, dolore e soffocamento> ti invadono improvvisamente il petto."
  },
  AvgDialog_10127_Content_7 = {Text = "Ramona!"},
  AvgDialog_10127_Content_9 = {
    Text = "La campana rintocca."
  },
  AvgDialog_10128_Content_1 = {
    Text = "Attenzione, il nemico sta passando all'offensiva!"
  },
  AvgDialog_10128_Content_2 = {
    Text = "Che cos'è tutto questo trambusto? Sono qui con te. Custode, lasciami eseguire la <Yellow:\"Chirurgia Esterna\">."
  },
  AvgDialog_10129_Content_1 = {
    Text = "Attiva la Chiave d'argento, %player%."
  },
  AvgDialog_10129_Content_2 = {
    Text = "La Chiave d'Argento tremola. Una scena illusoria si condensa nell'esistenza, sovrapponendosi alla realtà davanti ai tuoi occhi."
  },
  AvgDialog_10129_Content_3 = {
    Text = "Stordito, i tuoi pensieri rallentano fino a trascinarsi. Una sirena ulula dentro il tuo cranio. La voce di Doll svanisce in lontananza..."
  },
  AvgDialog_10129_Content_4 = {
    Text = "Lotti per stabilizzare i tuoi pensieri, sforzandoti al massimo di concentrarti sulle parole di Doll nonostante il rumore che riecheggia nella tua mente."
  },
  AvgDialog_10129_Content_5 = {
    Text = "Riesci a percepirlo? Davanti a te c'è quello che chiamiamo Dominio. Un amalgama di <Yellow:Sogno> e <Yellow:Realtà>."
  },
  AvgDialog_10129_Content_6 = {
    Text = "Mythag ha proiettato delle <Blue:Giunzioni> per stabilizzare le menti logore degli Investigatori e curare le ferite dei Risvegliati."
  },
  AvgDialog_10129_Content_7 = {
    Text = "Tuttavia, l'influenza umana vacilla all'interno di un Dominio. Non possiamo essere certi di dove si trovino quelle <Blue:Giunzioni>. Adattarsi o perire."
  },
  AvgDialog_10129_Content_8 = {
    Text = "Ora, dirigiti verso la <Blue:Giunzione> più vicina per poter curare le ferite di Ramona."
  },
  AvgDialog_10130_Content_10 = {
    Text = "Finché le nostre lapidi restano in piedi, siamo protetti dalla Dissoluzione di @2."
  },
  AvgDialog_10130_Content_11 = {
    Text = "La sua voce gentile, intrecciata a stridii distorti, riecheggia nella tua mente."
  },
  AvgDialog_10130_Content_12 = {
    Text = "Come tua assistente, sarò con te fino alla fine... <Yellow:Che la Chiave d'Argento Illumini il Cammino.>"
  },
  AvgDialog_10130_Content_13 = {
    Text = "Tutto bene, %player%? Sei un po' pallido/a. Dovremmo fare un salto in infermeria?"
  },
  AvgDialog_10130_Content_14 = {
    Text = "La sua voce cristallina ti schiarisce la mente, e il capogiro svanisce."
  },
  AvgDialog_10130_Content_15 = {
    Text = "Non preoccuparti, ero solo un po' stordito... ma mi sento già meglio."
  },
  AvgDialog_10130_Content_16 = {
    Text = "Davvero? Per sicurezza, perché non stabilisci un collegamento con me? Come tua assistente e partner, è mia responsabilità monitorare le tue condizioni."
  },
  AvgDialog_10130_Content_17 = {
    Text = "Proprio adesso? Qui fuori?"
  },
  AvgDialog_10130_Content_18 = {
    Text = "Forse è un po' prima del previsto, ma non dovrebbe fare differenza, giusto?"
  },
  AvgDialog_10130_Content_19 = {
    Text = "Del resto, aspetto questo giorno da più di un anno ormai."
  },
  AvgDialog_10130_Content_2 = {
    Text = "Benvenuto all'Università di Mythag, %player%."
  },
  AvgDialog_10130_Content_21 = {
    Text = "Le gocce di pioggia scivolano nei tuoi guanti, bagnandoti la punta delle dita, mentre una debole corrente filtra attraverso il tessuto, fluendo segretamente tra la tua pelle e la sua."
  },
  AvgDialog_10130_Content_22 = {
    Text = "Emozioni inspiegabili ti percorrono i nervi — gioia, eccitazione, inquietudine, e..."
  },
  AvgDialog_10130_Content_23 = {
    Text = "...<Yellow:Speranza>."
  },
  AvgDialog_10130_Content_3 = {
    Text = "O meglio, bentornato nel mondo al di là del velo."
  },
  AvgDialog_10130_Content_4 = {
    Text = "Sono a casa."
  },
  AvgDialog_10130_Content_5 = {
    Text = "Tutti ti stavano aspettando. Tra un paio di giorni, William ci assegnerà la nostra prima <Yellow:Missione di Indagine sul Cataclisma>."
  },
  AvgDialog_10130_Content_6 = {
    Text = "Non sarà indulgente con te, nemmeno se sei il nostro Custode che si presenta una volta ogni cent'anni."
  },
  AvgDialog_10130_Content_7 = {
    Text = "Promettimi solo che il tuo lavoro sul campo @1 non dipenderà troppo da me come tua <Blue:assistente>; o almeno, non quanto hai fatto per il corso di Calcolo."
  },
  AvgDialog_10130_Content_8 = {
    Text = "Non mi sarei mai aspettato di assistere al mio stesso funerale."
  },
  AvgDialog_10130_Content_9 = {
    Text = "Abbracciare la nostra mortalità scaccia la paura della morte."
  },
  AvgDialog_10131_Content_1 = {
    Text = "Ogier e io ci uniamo alla Battaglia."
  },
  AvgDialog_10131_Content_2 = {
    Text = "Attraverso il legame, percepisco che nessuno di voi due è in buone condizioni."
  },
  AvgDialog_10131_Content_3 = {
    Text = "Va tutto bene, Custode. È dovere di un cavaliere proteggere gli altri. Posso ancora resistere!"
  },
  AvgDialog_10131_Content_4 = {
    Text = "Non temere. Con la tua assistenza, non perderemo il controllo e potremo sfruttare al meglio il nostro Aliemus."
  },
  AvgDialog_10131_Content_5 = {
    Text = "Una volta accumulato abbastanza Aliemus, sarò in grado di recuperare pienamente le mie forze."
  },
  AvgDialog_10131_Content_6 = {
    Text = "La tua esitazione è fuori luogo, Custode. Contiamo su di te per sfondare il blocco."
  },
  AvgDialog_10131_Content_7 = {
    Text = "Lascia che constati di persona il valore di questo Prodigio su cui Mythag scommette il proprio futuro!"
  },
  AvgDialog_10132_Content_1 = {
    Text = "Hmph, credi di avere ciò che serve per distruggere questo pianeta?"
  },
  AvgDialog_10132_Content_2 = {
    Text = "Non è abbastanza! Avanti! Combattimi con tutto ciò che hai!"
  },
  AvgDialog_10133_Content_1 = {
    Text = "È... finita...?"
  },
  AvgDialog_10133_Content_10 = {
    Text = "Tawil allunga la mano e tocca leggermente la Chiave d'argento sul tuo petto."
  },
  AvgDialog_10133_Content_11 = {
    Text = "La Chiave d'argento emette un bagliore in risposta."
  },
  AvgDialog_10133_Content_12 = {
    Text = "Tu sei la Variabile, la risposta sia all'inizio che alla fine."
  },
  AvgDialog_10133_Content_13 = {
    Text = "Si spera che diventerai il punto di svolta..."
  },
  AvgDialog_10133_Content_15 = {
    Text = "Il pallido Mostro dalle sei ali. Le creature di fango. I Risvegliati deformi..."
  },
  AvgDialog_10133_Content_16 = {
    Text = "Tutti si dissolvono in acqua nera e svaniscono senza lasciare traccia."
  },
  AvgDialog_10133_Content_17 = {
    Text = "Sordo ai richiami di Ramona e di Doll, stringi la Chiave d'Argento e fissi lo sguardo verso \"Tawil,\" già inghiottito dal \"Portale\" in alto."
  },
  AvgDialog_10133_Content_18 = {
    Text = "Conosci quel volto. L'indifferenza. Le sopracciglia. Le labbra. Rispecchiano tutti l'aspetto di Ramona."
  },
  AvgDialog_10133_Content_19 = {
    Text = "Sono esattamente identici."
  },
  AvgDialog_10133_Content_2 = {
    Text = "Tawil rimase in piedi, sebbene la Sua compostezza si fosse incrinata."
  },
  AvgDialog_10133_Content_20 = {
    Text = [[
Due giorni dopo

Keygrave]]
  },
  AvgDialog_10133_Content_21 = {
    Text = "...L'Università di Mythag è un'avanguardia nella lotta contro la Dissoluzione, e costituisce una linea di difesa cruciale per il futuro dell'Umanità."
  },
  AvgDialog_10133_Content_22 = {
    Text = "Per 300 anni, l'Università di Mythag ha pagato un prezzo altissimo per proteggere la pace dell'Umanità dalla Dissoluzione."
  },
  AvgDialog_10133_Content_23 = {
    Text = "Questo cimitero è il luogo di Riposo che abbiamo preparato, e anche la Determinazione degli insegnanti e degli studenti di Mythag di Sacrificare le proprie vite per la sopravvivenza dell'Umanità."
  },
  AvgDialog_10133_Content_24 = {
    Text = "Il discorso prosegue. Czort chiude gli occhi e sospira, il suo respiro una nebbia bianca che si dissolve Sotto la pioggia."
  },
  AvgDialog_10133_Content_25 = {
    Text = "...Credo che, tra tutti i nuovi studenti, nessuno possa comprendere il peso di queste parole meglio di te."
  },
  AvgDialog_10133_Content_26 = {
    Text = "Nel corso dei secoli, la Pozza nera ha generato Nuclei d'Argento e Mutanti molte volte... ma quest'ultimo incidente li sovrasta tutti."
  },
  AvgDialog_10133_Content_27 = {
    Text = "Troppi non hanno mai fatto ritorno al Focolare."
  },
  AvgDialog_10133_Content_28 = {
    Text = "La Sig.ra Czort è la Preside Reggente del Dipartimento di Studi Biologici di Mythag. Secondo la leggenda, era in grado di vedere esseri ultraterreni. L'allieva prediletta del precedente preside."
  },
  AvgDialog_10133_Content_29 = {
    Text = "Gli Eventi legati alla Dissoluzione portano sempre con sé sorprese, Follia e morte. È un'esperienza inevitabile lungo il nostro cammino."
  },
  AvgDialog_10133_Content_3 = {
    Text = "Prima che chiunque possa reagire, dispiegano le ali e si avventano su Ramona."
  },
  AvgDialog_10133_Content_30 = {
    Text = "Comprendi il significato dietro le parole di Czort. Non c'è nessuno sepolto nella tomba davanti a te."
  },
  AvgDialog_10133_Content_31 = {
    Text = "Melma nera cola lentamente lungo la lapide."
  },
  AvgDialog_10133_Content_32 = {Text = "..."},
  AvgDialog_10133_Content_33 = {
    Text = "Dopo la cerimonia, Lord Dexter ti invita nel suo ufficio."
  },
  AvgDialog_10133_Content_34 = {
    Text = "\"Dexter\" ti suona familiare; è il cognome di Ramona. È il tuo professore e il suo padre adottivo."
  },
  AvgDialog_10133_Content_35 = {
    Text = "Riguardo a questa sezione del tuo rapporto... avrei un Favore da chiederti."
  },
  AvgDialog_10133_Content_36 = {
    Text = "Per quanto riguarda l'apparizione di Tawil... potresti non parlarne a Ramona, per il momento?"
  },
  AvgDialog_10133_Content_37 = {Text = "Perché?"},
  AvgDialog_10133_Content_38 = {
    Text = "Come dire... le causalità coinvolte sono piuttosto complesse. Non è qualcosa che si possa riassumere in fretta."
  },
  AvgDialog_10133_Content_39 = {
    Text = "Ma glielo dirò, prima o poi; solo non ancora."
  },
  AvgDialog_10133_Content_4 = {
    Text = "Il tempo si arresta."
  },
  AvgDialog_10133_Content_40 = {
    Text = "Questo non ha nulla a che fare con i protocolli di riservatezza di Mythag, ma è piuttosto la richiesta di un padre che desidera proteggere sua figlia."
  },
  AvgDialog_10133_Content_41 = {
    Text = "Per favore, concedimi un po' di tempo, d'accordo?"
  },
  AvgDialog_10133_Content_42 = {
    Text = "Sebbene desideri conoscere la verità, annuisci docilmente in segno di assenso."
  },
  AvgDialog_10133_Content_43 = {
    Text = "Grazie per la comprensione. A proposito... ho appena messo le mani su un paio di bottiglie di whiskey royal blend."
  },
  AvgDialog_10133_Content_44 = {
    Text = "Tieni, prendine una. Invita Ramona a bere qualcosa e assaporate il gusto dell'età adulta. Consideralo il vostro Rito di iniziazione speciale, eh?"
  },
  AvgDialog_10133_Content_45 = {
    Text = "Con tutto il rispetto, Lord Dexter, il riposo è un lusso che non possiamo permetterci. La Dissoluzione non si fermerà per la nostra comodità."
  },
  AvgDialog_10133_Content_46 = {
    Text = "Ahimè, William ci ha trovati. Mi spiace ragazzo, ora sei da solo."
  },
  AvgDialog_10133_Content_47 = {
    Text = "Il tuo Fascicolo è pronto. È giunto il momento, nuovo Custode. Presentati in servizio."
  },
  AvgDialog_10133_Content_48 = {
    Text = "Che la Chiave d'Argento Illumini il Cammino."
  },
  AvgDialog_10133_Content_5 = {
    Text = "Scatenasti ogni briciolo di velocità che possedevi, riuscendo a malapena a intercettare il Loro cammino."
  },
  AvgDialog_10133_Content_6 = {
    Text = "Il mostro bianco ti fissa dritto negli occhi."
  },
  AvgDialog_10133_Content_7 = {
    Text = "Ti osserva in silenzio con la sua forma pallida e priva di volto."
  },
  AvgDialog_10133_Content_9 = {
    Text = "Un volto femminile e indifferente appare davanti a te."
  },
  AvgDialog_10134_Content_1 = {
    Text = "Ehi, tu! Smettila di tergiversare e usa la mia <Yellow:\"Lama della Sfida\">, una buona volta."
  },
  AvgDialog_10134_Content_2 = {
    Text = "Se posso intervenire, Custode. Prima, utilizza le Carte di comando \"Attacco\" per ridurre il Costo di Arithmetica della <Yellow:\"Lama della Sfida\">."
  },
  AvgDialog_10134_Content_3 = {
    Text = "La giusta sequenza di comandi può ottimizzare la nostra efficacia in battaglia. Ogni scelta conta. Pensa in modo tattico."
  },
  AvgDialog_10135_Content_1 = {
    Text = "State indietro! Vi prego... il mio scudo del personaggio comincia a cedere!"
  },
  AvgDialog_10135_Content_10 = {
    Text = "Sai che sono l'unico che può farlo."
  },
  AvgDialog_10135_Content_11 = {
    Text = "Quando mi elogiate, mi definite un \"prodigio che nasce una volta al secolo\", ma nei momenti di crisi vengo relegata a mera figura rappresentativa. Non è certo appropriato."
  },
  AvgDialog_10135_Content_12 = {
    Text = "Certi rischi non possono essere evitati."
  },
  AvgDialog_10135_Content_13 = {
    Text = "Non abbiamo scelta. Con così tanti che perdono il controllo, o combattiamo quelli colpiti dalla follia o ne veniamo consumati."
  },
  AvgDialog_10135_Content_14 = {
    Text = "Inoltre, non possiamo sfondare il blocco intorno alla Torre dell'Orologio da soli. Avremo bisogno di tutto l'aiuto possibile... dobbiamo trovare un modo per comandare i Risvegliatori."
  },
  AvgDialog_10135_Content_15 = {
    Text = "Ramona, ho bisogno del tuo supporto."
  },
  AvgDialog_10135_Content_16 = {
    Text = "Dato che hai preso la tua decisione... come tuo compagno, non cercherò di fermarti."
  },
  AvgDialog_10135_Content_17 = {
    Text = "Ramona, pronta alla Battaglia!"
  },
  AvgDialog_10135_Content_2 = {
    Text = "Con un clangore, le spade gemelle di Lotan frantumano ancora una volta il suo scudo di melma nera."
  },
  AvgDialog_10135_Content_3 = {
    Text = "Patetico! Assolutamente patetico! Combattere questo debole non mi soddisfa! Datemi un vero combattimento!"
  },
  AvgDialog_10135_Content_4 = {
    Text = "La Risvegliatrice Lotan brandisce le sue lame gemelle, assaltando Ogier senza sosta. La pura potenza dietro ogni colpo non lascia dubbi: ha perso il controllo."
  },
  AvgDialog_10135_Content_5 = {
    Text = "Data la situazione, dobbiamo..."
  },
  AvgDialog_10135_Content_6 = {
    Text = "Ramona, aiutami a sottomettere Lotan!"
  },
  AvgDialog_10135_Content_7 = {
    Text = "Non puoi davvero voler..."
  },
  AvgDialog_10135_Content_8 = {
    Text = "Stabilirò un Legame con lei!"
  },
  AvgDialog_10135_Content_9 = {
    Text = "Non siate sciocchi! Il crollo di un Risvegliato risuona attraverso il legame! Persino voi—"
  },
  AvgDialog_10136_Content_1 = {
    Text = "Questa è... la tecnica d'orgoglio di Lotan, <Yellow:\"Lama della Sfida\">, capace di sferrare attacchi multipli in un istante!"
  },
  AvgDialog_10136_Content_2 = {
    Text = "Per contrastare la sua mossa... impiega la mia <Yellow:\"Tesi d'Assalto\">. Meglio prevenire che curare."
  },
  AvgDialog_10137_Content_1 = {
    Text = "Non potete fermarmi! Umani senza vergogna..."
  },
  AvgDialog_10137_Content_2 = {
    Text = "Le tue dita sfiorano la Chiave d'Argento. Vibra debolmente, esortandoti a entrare in risonanza con Lotan."
  },
  AvgDialog_10137_Content_4 = {
    Text = "<Shake:Se avessi saputo che sarebbe finita così... non avrei mai stretto quel patto...>"
  },
  AvgDialog_10137_Content_5 = {
    Text = "Ramona si avvicina a Lotan, tendendo la Mano."
  },
  AvgDialog_10137_Content_6 = {
    Text = "So che dopo il tuo risveglio, Mythag ha promesso di combattere al tuo fianco. Di combattere insieme fino alla fine del pianeta."
  },
  AvgDialog_10137_Content_7 = {
    Text = "Non abbiamo mai avuto intenzione di infrangere la nostra promessa. Non nei trecento anni passati, né nei trecento a venire."
  },
  AvgDialog_10137_Content_8 = {
    Text = "Lotan, la feroce battaglia che brami è a portata di mano."
  },
  AvgDialog_10138_Content_1 = {
    Text = "Resta all'erta, il nemico sta per attaccare. Un danno simile potrebbe uccidermi!"
  },
  AvgDialog_10138_Content_2 = {
    Text = "Confido che prenderai la decisione giusta. Per questo turno, ti suggerisco di giocare la carta <Yellow:\"Difesa\">."
  },
  AvgDialog_10139_Content_1 = {
    Text = "Grazie, Custode. Mi hai salvata di nuovo. Se non fosse per questo Legame, ora sarei in punto di morte."
  },
  AvgDialog_10139_Content_2 = {
    Text = "Conservalo per dopo. Non è il momento!"
  },
  AvgDialog_10139_Content_3 = {
    Text = "L'anomalia nera come la pece si espande intorno a te. Le urla dei tuoi compagni di classe risuonano nelle tue orecchie, mentre si dissolvono in fanghiglia nera uno dopo l'altro."
  },
  AvgDialog_10139_Content_4 = {
    Text = "La Chiave d'Argento ci sta comunicando l'<Yellow:intento> del nemico attraverso il nostro legame. Attenzione, sta per attaccare!"
  },
  AvgDialog_10140_Content_1 = {
    Text = "Percepisci l'Aliemus che scorre in me, Custode? Senza la tua guida, sarei impazzito come Lotan."
  },
  AvgDialog_10140_Content_2 = {
    Text = "Tuttavia, ora possiamo farne buon uso."
  },
  AvgDialog_10140_Content_3 = {
    Text = "Concentrati sul flusso di Aliemus... sì, dovrebbe trovarsi nell'<Blue:angolo in alto a sinistra> del Dispositivo di Comando."
  },
  AvgDialog_10140_Content_4 = {
    Text = "Scatena la mia Esaltazione e attua la mia <Yellow:\"Deduzione del mundus\">! Nella lotta contro la Dissoluzione, <Yellow:dobbiamo restare vigili per contrastare efficacemente il nemico>."
  },
  AvgDialog_10141_Content_1 = {
    Text = "Dannazione, Lotan sta per scatenare la sua <Yellow:Esaltazione>... queste Carte di comando non basteranno..."
  },
  AvgDialog_10141_Content_2 = {
    Text = "La Chiave d'argento è legata al tuo spirito; pertanto, le tue memorie e la tua intuizione ne plasmano il potere in modo unico."
  },
  AvgDialog_10141_Content_3 = {
    Text = "Guarda verso l'<Blue:angolo in basso a sinistra> del Dispositivo di Comando. La Chiave d'argento trabocca di energia... ora hai accesso alla tua <Yellow:Squadra>!"
  },
  AvgDialog_10141_Content_4 = {
    Text = "Afferra la Chiave d'argento e recita l'incantesimo... attiva la <Yellow:Squadra> e concedimi più spazio tattico!"
  },
  AvgDialog_10142_Content_2 = {
    Text = "Non distrarti durante una cerimonia così importante, <Yellow:Custode>, la Chiave d'argento ti sarà consegnata subito dopo."
  },
  AvgDialog_10142_Content_3 = {
    Text = "Erigete la vostra lapide per dimostrare la nostra Determinazione a combattere <Yellow:contro la Dissoluzione>—una tradizione di Mythag, che segna la fine del periodo preparatorio e l'ingresso come Investigatori ufficiali."
  },
  AvgDialog_10142_Content_4 = {
    Text = "Pronti? Allora incidete il vostro nome. Rendetelo ufficiale."
  },
  AvgDialog_116003_Content_1 = {
    Text = "Mentre il tuo disegno Casa-Albero-Persona si frantuma, tutto ciò che ti circonda si dissolve nella Distorsione."
  },
  AvgDialog_116003_Content_10 = {
    Text = "Ma non voglio che questo sia solo un sogno."
  },
  AvgDialog_116003_Content_11 = {
    Text = "Voglio tornare a Mythag e rivederli."
  },
  AvgDialog_116003_Content_12 = {
    Text = "...Una risposta prevedibile."
  },
  AvgDialog_116003_Content_13 = {
    Text = "Ma questa volta, dopo che hai mostrato la tua determinazione, posso finalmente stare tranquilla."
  },
  AvgDialog_116003_Content_14 = {
    Text = "%player%, la tua volontà è più tenace e più Forte di quanto immaginassi... abbastanza forte da affrontare Lui, il Caos e la Follia di questo mondo."
  },
  AvgDialog_116003_Content_15 = {
    Text = "Scuoti la testa, rivolgendo lo sguardo a Clementine nel Sogno bellissimo ormai sul punto di frantumarsi del tutto."
  },
  AvgDialog_116003_Content_16 = {
    Text = "No, ti sbagli. La volontà di una persona ha i suoi limiti."
  },
  AvgDialog_116003_Content_17 = {
    Text = "Il motivo per cui sono riuscito a resistere fino ad ora è che Tutti nel Mythag mi sostengono."
  },
  AvgDialog_116003_Content_18 = {
    Text = "Loro, da \"quel mondo\", hanno costruito insieme questo Sogno bellissimo per te, e tu sei determinato a trasformare questo Sogno in realtà in questo mondo."
  },
  AvgDialog_116003_Content_19 = {
    Text = "Udendo le tue parole e vedendo la tua Espressione seria, Clementine sorrise, lasciando trasparire un sorriso disteso."
  },
  AvgDialog_116003_Content_2 = {
    Text = "Hai infranto il tuo stesso bellissimo sogno."
  },
  AvgDialog_116003_Content_20 = {
    Text = "Sì, hai ancora \"loro\", e Tawil... e me."
  },
  AvgDialog_116003_Content_21 = {
    Text = "Esatto. Non sono mai stato solo."
  },
  AvgDialog_116003_Content_22 = {
    Text = "Nello scenario in costante dissoluzione, un grido acuto riecheggiò: era la risposta di Tawil.\n È sempre stata lì."
  },
  AvgDialog_116003_Content_23 = {
    Text = "E ora, %player%, il tuo Sogno bellissimo è giunto davvero alla fine."
  },
  AvgDialog_116003_Content_24 = {
    Text = "Come ringraziamento per la tua collaborazione in questa sessione di Guarigione, ti faccio un piccolo Dono. Spero che ti piaccia."
  },
  AvgDialog_116003_Content_25 = {
    Text = "Con le Ultime volontà di Clementine, il Sogno si frantumò completamente—"
  },
  AvgDialog_116003_Content_26 = {
    Text = "Il cielo con il sole nero incombe alto davanti a te, portando nebbia grigia e la crudeltà di questo mondo."
  },
  AvgDialog_116003_Content_27 = {
    Text = "E nel palmo della tua mano giace una foto.\nUna foto scattata nel \"falso bel sogno\", una che non dovrebbe esistere nella crudele realtà."
  },
  AvgDialog_116003_Content_28 = {
    Text = "In riva al mare, pallavolo, baldoria: l'unica cosa diversa dai miei ricordi è Ramona."
  },
  AvgDialog_116003_Content_29 = {
    Text = [[
Il volto familiare sorride serenamente, come se trascendesse il tempo e lo spazio per fissare il tuo sguardo.
 Sembra quasi che sia proprio davanti a te.]]
  },
  AvgDialog_116003_Content_3 = {
    Text = "Da quando ho deciso di usare la loro forza per costruire questo Sogno, sapevo che questo giorno sarebbe arrivato."
  },
  AvgDialog_116003_Content_30 = {
    Text = "<Small:Ramona...>"
  },
  AvgDialog_116003_Content_31 = {
    Text = "Posi la mano sulla foto, un groviglio di emozioni e confusione ti inonda il cuore."
  },
  AvgDialog_116003_Content_32 = {
    Text = "<Shake:Perché proprio Ramona...>"
  },
  AvgDialog_116003_Content_33 = {
    Text = [[
Le tue domande restano senza risposta.
Nel mondo avvolto dalla nebbia grigia, solo il silenzioso sole nero rimane immutato.]]
  },
  AvgDialog_116003_Content_34 = {
    Text = "Non importa cosa accada..."
  },
  AvgDialog_116003_Content_35 = {
    Text = "Posi la foto sul petto, là dove batte il cuore, e chiudi gli occhi."
  },
  AvgDialog_116003_Content_36 = {
    Text = "Non importa cosa accada, non sono solo."
  },
  AvgDialog_116003_Content_37 = {
    Text = "Poi apri gli occhi e guardi il sole nero appeso in alto, camminando con passo fermo verso di esso."
  },
  AvgDialog_116003_Content_38 = {
    Text = "Questo mondo sta ancora sgretolando, osservato da orrori indescrivibili, sull'orlo del collasso, eppure..."
  },
  AvgDialog_116003_Content_39 = {
    Text = "<Big:Alla fine troverai un modo per salvarlo>"
  },
  AvgDialog_116003_Content_4 = {
    Text = "Solo non mi aspettavo che arrivasse così presto, né che tu fossi così determinato."
  },
  AvgDialog_116003_Content_5 = {
    Text = "In realtà... ho esitato e mi sono tirata indietro. Quando ero in riva al mare."
  },
  AvgDialog_116003_Content_6 = {
    Text = "Allora perché non continuare a sprofondare in tutto questo? Non è abbastanza bello, non è abbastanza felice qui?"
  },
  AvgDialog_116003_Content_7 = {
    Text = "Rimani in silenzio, ripensando al tuo disegno Casa-Albero-Persona."
  },
  AvgDialog_116003_Content_8 = {
    Text = "È innegabile, questo è davvero un Sogno bellissimo. Ma..."
  },
  AvgDialog_116003_Content_9 = {
    Text = "A poco a poco, le scene nella tua mente non sono più dipinti, ma il vero Mythag, la vera Doll, Ramona, Lotan e Ogier."
  },
  AvgDialog_117499_Content_1 = {
    Text = "<Shake:Ce ne sono troppi...>"
  },
  AvgDialog_117499_Content_2 = {
    Text = "Sotto il cielo livido, la Frenesia di pesci vortica come una tempesta senza fine. Scorgi una scala di metallo arrugginito in un angolo e ti arrampichi rapidamente sulla seconda piattaforma."
  },
  AvgDialog_117499_Content_3 = {
    Text = "Dovrei essere al sicuro nascondendomi qui per un po'."
  },
  AvgDialog_117499_Content_4 = {
    Text = "Un odore sinistro, mescolato a un suono di attrito che fa stridere i denti, cattura la tua attenzione."
  },
  AvgDialog_117499_Content_5 = {
    Text = "Aspetta, quello laggiù è..."
  },
  AvgDialog_117500_Content_1 = {Text = "Catene"},
  AvgDialog_117500_Content_10 = {Text = "..."},
  AvgDialog_117500_Content_100 = {
    Text = "Murphy scuote la testa sconsolata, i suoi occhi vuoti cercano a tentoni la tua posizione. Ti si rivolge, serrando con forza le labbra screpolate e esangui per forzare un debole sorriso."
  },
  AvgDialog_117500_Content_101 = {
    Text = "Sei venuto per me... Pensavo... che sarebbe stato impossibile rivederti..."
  },
  AvgDialog_117500_Content_102 = {
    Text = "Lo scafo si inclina improvvisamente con violenza, e la marea salata e gelida irrompe nella cabina."
  },
  AvgDialog_117500_Content_103 = {
    Text = "Che cosa sta succedendo?!"
  },
  AvgDialog_117500_Content_104 = {
    Text = "La nave si è arenata?"
  },
  AvgDialog_117500_Content_105 = {
    Text = "Impossibile. Il pescaggio profondo della nave implica che una falla non potrebbe allagare il livello superiore così rapidamente..."
  },
  AvgDialog_117500_Content_106 = {
    Text = "A meno che..."
  },
  AvgDialog_117500_Content_107 = {
    Text = "William si precipita all'oblò. La scena bizzarra davanti a lui è come il più assurdo dei deliri: il Paradise affonda a una velocità incredibile."
  },
  AvgDialog_117500_Content_108 = {
    Text = "Una forza enorme, irresistibile, trascina la nave rapidamente verso il fondale con una potenza tremenda, come se fosse trascinata da una balena gigante."
  },
  AvgDialog_117500_Content_109 = {Text = "Ah—"},
  AvgDialog_117500_Content_11 = {
    Text = "Riapri gli occhi. Senti la biancheria sotto di te, morbida e calda. Tutto sembra stranamente familiare."
  },
  AvgDialog_117500_Content_110 = {
    Text = "Sotto i violenti tremori, la catena che trafigge il palmo di Murphy si spezza all'improvviso."
  },
  AvgDialog_117500_Content_111 = {
    Text = "Il suo palmo appiccicoso e umido esplora lo spazio, posandosi sul dorso della tua mano. Sopporta il dolore della ferita, stringendo delicatamente la tua mano e fissandoti negli occhi."
  },
  AvgDialog_117500_Content_112 = {
    Text = "Mormora, le sue parole impregnate dell'odore metallico di ruggine, se dall'acqua di mare o dal sangue, non riesci a distinguerlo."
  },
  AvgDialog_117500_Content_113 = {
    Text = "Aiutami... so che puoi..."
  },
  AvgDialog_117500_Content_114 = {
    Text = "Le sue ultime volontà, insieme all'acqua di mare che inonda la cabina, vengono divorate dall'oscurità."
  },
  AvgDialog_117500_Content_12 = {
    Text = "<Small:Tsk, dobbiamo davvero restare qui ad aspettare che si svegli?>"
  },
  AvgDialog_117500_Content_13 = {
    Text = "<Small:Golia, non mettere in discussione il decreto della Madre Divina.>"
  },
  AvgDialog_117500_Content_14 = {
    Text = "<Small:Teniamo la voce bassa, Lord Golia. Stamattina la Madre Divina ha convocato la nostra Somma Sacerdotessa per una bella ramanzina...>"
  },
  AvgDialog_117500_Content_15 = {
    Text = "La discussione soffocata giungeva da oltre il velo."
  },
  AvgDialog_117500_Content_16 = {
    Text = "*Coff, coff...*"
  },
  AvgDialog_117500_Content_17 = {
    Text = "Sei sveglio? Ti stiamo tutti aspettando."
  },
  AvgDialog_117500_Content_18 = {
    Text = "Faros solleva il baldacchino del letto."
  },
  AvgDialog_117500_Content_19 = {
    Text = "Sono stato... salvato dal mare, di nuovo?"
  },
  AvgDialog_117500_Content_2 = {
    Text = "...Un ragno?"
  },
  AvgDialog_117500_Content_20 = {
    Text = "Sei sopravvissuto, e questa è già una fortuna. Non abbiamo alcun obbligo di rispondere a tutte le tue domande."
  },
  AvgDialog_117500_Content_21 = {
    Text = "Per volere della Madre Divina, i Navigatori hanno atteso a lungo il tuo risveglio."
  },
  AvgDialog_117500_Content_22 = {
    Text = "Questo è il succo di limone che la Madre Divina mi ha ordinato di spremere. Bevilo con gratitudine, umano."
  },
  AvgDialog_117500_Content_23 = {
    Text = "Dato che il nostro Ospite è sano e salvo, tornerò al mio posto di navigatore. Il Reame Divino chiama."
  },
  AvgDialog_117500_Content_24 = {Text = "..."},
  AvgDialog_117500_Content_25 = {Text = "..."},
  AvgDialog_117500_Content_26 = {
    Text = "È accaduto davvero, o è stato un Incubo avuto mentre stavo annegando..."
  },
  AvgDialog_117500_Content_27 = {
    Text = "(Devo trovare un modo per verificarlo.)"
  },
  AvgDialog_117500_Content_28 = {
    Text = "Se ricordo bene, l'ultima persona che ho visto era..."
  },
  AvgDialog_117500_Content_29 = {
    Text = "Sali sul ponte."
  },
  AvgDialog_117500_Content_3 = {
    Text = "...Un ragno?"
  },
  AvgDialog_117500_Content_30 = {
    Text = "<Shake:Ehi! William—>"
  },
  AvgDialog_117500_Content_31 = {
    Text = "<Shake:Smettila di nasconderti—so che sei qui!>"
  },
  AvgDialog_117500_Content_32 = {
    Text = "L'unico suono sul ponte è la Marea quieta. Le tue grida si diffondono nella Nebbia del mattino."
  },
  AvgDialog_117500_Content_33 = {
    Text = "(Lascia perdere, era davvero solo un mio sogno...)"
  },
  AvgDialog_117500_Content_34 = {Text = "WHOAAAH!"},
  AvgDialog_117500_Content_35 = {
    Text = "Il ponte sotto i tuoi piedi si apre improvvisamente in una botola, e con un tonfo precipiti nell'Oscurità."
  },
  AvgDialog_117500_Content_36 = {
    Text = "Un fascio di paglia attutisce la tua caduta."
  },
  AvgDialog_117500_Content_37 = {
    Text = "È da molto che non ci vediamo, %player%."
  },
  AvgDialog_117500_Content_38 = {
    Text = "Tu mi conosci. Sei il mio Senior William, dal nostro mondo Primordiale..."
  },
  AvgDialog_117500_Content_39 = {
    Text = "William ignora la sorpresa nel tuo tono. La sua Espressione si fa cupa."
  },
  AvgDialog_117500_Content_4 = {
    Text = "Una donna vi fissa intensamente, le mani che reggono un arcolaio. Strati di tessuto diafano giacciono sotto di lei mentre si erge sul ponte arrugginito."
  },
  AvgDialog_117500_Content_40 = {
    Text = "Non ricordo di averti insegnato ad agire con tanta audacia nella roccaforte del nemico."
  },
  AvgDialog_117500_Content_41 = {
    Text = "Persino il Decano Czort, il più testardo tra noi, probabilmente non approverebbe la tua Scelta."
  },
  AvgDialog_117500_Content_42 = {
    Text = "Il familiare profumo di cedro. La familiare postura eretta. Il familiare tono severo."
  },
  AvgDialog_117500_Content_43 = {
    Text = "Senior William..."
  },
  AvgDialog_117500_Content_44 = {
    Text = "Non avevo intenzione di mostrarmi a te così presto. Non prima di aver affrontato la questione chiave."
  },
  AvgDialog_117500_Content_45 = {
    Text = "Tuttavia, la tua imprudenza mi ha costretto ad agire."
  },
  AvgDialog_117500_Content_46 = {
    Text = "Quindi sapevi che ti stavo cercando?"
  },
  AvgDialog_117500_Content_47 = {
    Text = "William non proferisce parola, solo uno sguardo tagliente che chiede chiaramente: <Italic:Mi prendi per un idiota?>"
  },
  AvgDialog_117500_Content_48 = {
    Text = "Siamo già sulla stessa nave. Tanto vale che ti racconti tutto, per evitare complicazioni inutili."
  },
  AvgDialog_117500_Content_49 = {
    Text = "Ma prima, ti dispiace condividere le informazioni che hai?"
  },
  AvgDialog_117500_Content_5 = {
    Text = "Questa volta non sospira né parla; resta semplicemente in silenzio."
  },
  AvgDialog_117500_Content_50 = {Text = "..."},
  AvgDialog_117500_Content_51 = {Text = "..."},
  AvgDialog_117500_Content_52 = {
    Text = "Da quando Doll: Inferno ti ha trasformato in un cervello in una vasca, alla prigionia nel Sanatorio di Clementine, poi attraverso le dogane di Necrovia, e infine l'\"Incubo\" che hai vissuto sulla nave da crociera Paradise."
  },
  AvgDialog_117500_Content_53 = {
    Text = "Racconti gli eventi di cui sei stato testimone, e William ascolta attentamente con il capo inclinato, annuendo di tanto in tanto per mostrare il suo interesse."
  },
  AvgDialog_117500_Content_54 = {
    Text = "Quando inizi a narrare del Giovane William che avevi visto, esiti per un istante, ma William alza semplicemente la mano per farti segno di continuare."
  },
  AvgDialog_117500_Content_55 = {
    Text = "Le informazioni che hai fornito sono molto utili."
  },
  AvgDialog_117500_Content_56 = {
    Text = "William, cosa stai inseguendo esattamente in questo momento?"
  },
  AvgDialog_117500_Content_57 = {
    Text = "William riflette per un istante."
  },
  AvgDialog_117500_Content_58 = {
    Text = "Lasciami pensare da dove cominciare."
  },
  AvgDialog_117500_Content_59 = {
    Text = "Da quando sono precipitato in questo mondo, ho indagato su due domande: perché sono finito qui, e come fare ritorno al mio mondo originario."
  },
  AvgDialog_117500_Content_6 = {
    Text = "Perché? Ricordo chiaramente di essere stato circondato da innumerevoli Navigatori, e poi..."
  },
  AvgDialog_117500_Content_60 = {
    Text = "William estrae solennemente una Chiave d'Argento che custodisce vicino al cuore, e un bagliore di Nostalgia risplende nel suo sguardo."
  },
  AvgDialog_117500_Content_61 = {
    Text = "Questa Chiave d'Argento un tempo era in frantumi. L'ho restaurata io stesso. Apparteneva a Fingal, il mio vecchio compagno... La gente mi chiama spesso l'Investigatore più Leggendario di Mythag, ma per me lo è solo perché lui è scomparso nel fiore degli anni."
  },
  AvgDialog_117500_Content_62 = {
    Text = "Solo quando sono precipitato in questo mondo ho compreso che lui aveva semplicemente ottenuto l'Intuizione sull'essenza del mondo prima degli altri, e aveva combattuto come pioniere in prima linea contro la Dissoluzione."
  },
  AvgDialog_117500_Content_63 = {
    Text = "Aveva seguito la traccia del Segreto che collega due mondi, lasciando dietro di sé un indizio cruciale: una Scultura d'Avorio."
  },
  AvgDialog_117500_Content_64 = {
    Text = "Come al solito, mi precede sempre."
  },
  AvgDialog_117500_Content_65 = {
    Text = "L'Espressione di William si fa malinconica. Scuote il capo e ripone la Chiave d'Argento nel petto."
  },
  AvgDialog_117500_Content_66 = {
    Text = "...Hai visto la Scultura d'Avorio in possesso di Miryam o Murphy?"
  },
  AvgDialog_117500_Content_67 = {Text = "Annuisci."},
  AvgDialog_117500_Content_68 = {
    Text = "Se tutto si sviluppa come l'ultima volta, Murphy sta officiando una cerimonia con questa Scultura sul ponte sopra di noi proprio in questo momento."
  },
  AvgDialog_117500_Content_69 = {
    Text = "Quella Scultura d'Avorio sembra essere collegata alla Verità celata dietro questo mondo."
  },
  AvgDialog_117500_Content_7 = {
    Text = "Controllate i vostri arti. Sebbene il dolore fantasma persista, non vi è traccia alcuna di ferita sul vostro corpo; la battaglia vissuta prima dello svenimento sembra non essere mai avvenuta."
  },
  AvgDialog_117500_Content_70 = {
    Text = "Quindi, se vogliamo tornare indietro, dobbiamo ottenere la Scultura d'Avorio e analizzarla."
  },
  AvgDialog_117500_Content_71 = {
    Text = "Il Rito è terminato. La Scultura d'Avorio dovrebbe trovarsi nella stanza di Murphy..."
  },
  AvgDialog_117500_Content_72 = {
    Text = "All'interno è molto silenzioso. Non dovrebbe esserci nessuno..."
  },
  AvgDialog_117500_Content_73 = {
    Text = "Meglio prevenire che curare. Dobbiamo cercare di evitare conflitti inutili."
  },
  AvgDialog_117500_Content_74 = {
    Text = "D'accordo, andiamo a dare un'occhiata prima."
  },
  AvgDialog_117500_Content_75 = {
    Text = "Spingi con cautela la porta, aprendola appena."
  },
  AvgDialog_117500_Content_76 = {Text = "..."},
  AvgDialog_117500_Content_77 = {
    Text = "L'aria, mista a un odore sgradevole, ti invade le narici mentre inspiri profondamente senza rendertene conto."
  },
  AvgDialog_117500_Content_78 = {
    Text = "Che succede?"
  },
  AvgDialog_117500_Content_79 = {Text = "Suono."},
  AvgDialog_117500_Content_8 = {
    Text = "Era... un incubo?"
  },
  AvgDialog_117500_Content_80 = {
    Text = "Un suono finalmente emerge nella stanza silenziosa."
  },
  AvgDialog_117500_Content_81 = {
    Text = "Il lento gocciolare di un liquido."
  },
  AvgDialog_117500_Content_82 = {
    Text = "Goccia dopo goccia. Il liquido confluisce in una piccola pozza appena formatasi."
  },
  AvgDialog_117500_Content_83 = {
    Text = "Otto catene di ferro tese si estendono dagli arti di Murphy, legandola saldamente. Una cavità spalancata e cremisi le segna il petto."
  },
  AvgDialog_117500_Content_84 = {
    Text = "Il sangue sgorga dalla ferita sconvolgente, gocciolando nella pozza, che è la fonte del persistente ticchettio."
  },
  AvgDialog_117500_Content_85 = {Text = "Murphy...!"},
  AvgDialog_117500_Content_86 = {
    Text = "Sei arrivato troppo tardi."
  },
  AvgDialog_117500_Content_87 = {
    Text = "Il tuo cuore duole, stretto nella morsa di una mano invisibile. Il dolore familiare e soffocante viene trafitto bruscamente da frammenti di memoria."
  },
  AvgDialog_117500_Content_88 = {
    Text = "La luce abbagliante ti ferisce gli occhi, provocando lacrime incontenibili."
  },
  AvgDialog_117500_Content_89 = {
    Text = "Il liquido torbido defluisce, e i tuoi occhi finalmente tornano a mettere a fuoco la bambina."
  },
  AvgDialog_117500_Content_9 = {
    Text = "La donna annuisce in silenzio, la sua figura si dissolve nella Nebbia lattiginosa."
  },
  AvgDialog_117500_Content_90 = {
    Text = "La lama affonda nel suo petto, e la bambina illuminata dalla luna apre gli occhi."
  },
  AvgDialog_117500_Content_91 = {
    Text = "La luna piena, simbolo di morte, incombe vicina, eppure non vi è traccia di terrore sul suo volto giovane."
  },
  AvgDialog_117500_Content_92 = {
    Text = "Ce l'ho fatta... Ce l'ho fatta davvero."
  },
  AvgDialog_117500_Content_93 = {
    Text = "L'ho... trafitto... Non nascerà..."
  },
  AvgDialog_117500_Content_94 = {
    Text = "Allora... Loro possono..."
  },
  AvgDialog_117500_Content_95 = {
    Text = "La mano che stringe il coltello cade debolmente, mentre un liquido cremisi, viscoso e scuro cola dalla lama, gocciolando tra le sue dita nel mare."
  },
  AvgDialog_117500_Content_96 = {
    Text = "*Coff, coff...*"
  },
  AvgDialog_117500_Content_97 = {
    Text = "Tu sei... la persona del mio sogno..."
  },
  AvgDialog_117500_Content_98 = {
    Text = "Non parlare ancora! Lascia che ti aiuti..."
  },
  AvgDialog_117500_Content_99 = {
    Text = "I tuoi tentativi ansiosi non producono risultati. Le catene emettono deboli cigolii mentre Murphy trema dal dolore."
  },
  AvgDialog_117501_Content_10 = {
    Text = "Perché lo chiedi, Madre Divina?"
  },
  AvgDialog_117501_Content_11 = {
    Text = "La scorsa notte, ho fatto un sogno."
  },
  AvgDialog_117501_Content_12 = {
    Text = "Nel sogno, con quel pugnale rituale..."
  },
  AvgDialog_117501_Content_13 = {
    Text = "Murphy alza la mano e indica il pugnale che Miryam porta sempre con sé.\nLa lama brilla di colori vivaci, emanando un bagliore sinistro e velenoso."
  },
  AvgDialog_117501_Content_14 = {
    Text = "Mi sono trafitta il petto."
  },
  AvgDialog_117501_Content_15 = {
    Text = "<ItalicRed:Non nascerà...>"
  },
  AvgDialog_117501_Content_16 = {
    Text = "Murphy mormora tra sé, le punte delle dita che sfiorano delicatamente la cicatrice intrisa di sangue sul suo petto."
  },
  AvgDialog_117501_Content_17 = {
    Text = "Era solo un incubo."
  },
  AvgDialog_117501_Content_18 = {
    Text = "Miryam avanza, si inginocchia davanti a Murphy e posa dolcemente il palmo sul dorso della sua mano per offrirle conforto."
  },
  AvgDialog_117501_Content_19 = {
    Text = "State tranquilla, il desiderio a lungo custodito di noi Navigatori si è avverato. Egli esiste. È giunto in questo mondo."
  },
  AvgDialog_117501_Content_2 = {Text = "Deliri"},
  AvgDialog_117501_Content_20 = {
    Text = "E voi e io giungeremo infine all'Eterno Reame Divino, condividendo la gloria del divino dinanzi al Suo trono."
  },
  AvgDialog_117501_Content_21 = {
    Text = "Le sue parole risuonano come preghiere offerte dinanzi a un altare, colme di reverenza e devozione."
  },
  AvgDialog_117501_Content_22 = {
    Text = "E se non riuscissimo a raggiungere il Reame Divino? Intendo, se..."
  },
  AvgDialog_117501_Content_23 = {
    Text = "Miryam interrompe immediatamente l'esitante domanda di Murphy."
  },
  AvgDialog_117501_Content_24 = {
    Text = "Tali questioni non sono mai state trasmesse nella profezia del Re-Dio.\nLa prossima volta che le stelle si allineeranno sarà domani, e il Suo sangue ci guiderà sicuramente alla terra promessa."
  },
  AvgDialog_117501_Content_25 = {
    Text = "Murphy aggrotta le sopracciglia."
  },
  AvgDialog_117501_Content_26 = {
    Text = "Ora vado a riposare, Miryam. Dovresti tornare a riposare anche tu."
  },
  AvgDialog_117501_Content_27 = {
    Text = "Pregherò per voi fino all'alba, affinché possiate avere un sonno sereno per tutta la notte."
  },
  AvgDialog_117501_Content_28 = {
    Text = "Murphy non risponde, il suo sguardo profondo segue la sagoma di Miryam finché lo scricchiolio della porta non si richiude."
  },
  AvgDialog_117501_Content_29 = {
    Text = "Si volge sconsolata verso l'altare nell'ombra, chiudendo gli occhi per pregare."
  },
  AvgDialog_117501_Content_3 = {
    Text = "Stimata Madre Divina, siete di nuovo qui a contemplare le luci."
  },
  AvgDialog_117501_Content_30 = {
    Text = "Domani, il Giorno dell'Allineamento Stellare..."
  },
  AvgDialog_117501_Content_31 = {
    Text = [[
Le strane offerte sull'altare non le danno alcuna risposta, silenziose come fossili sotto il ghiaccio.
Murphy apre finalmente gli occhi con determinazione.]]
  },
  AvgDialog_117501_Content_32 = {
    Text = "Per il proseguimento di questo sogno..."
  },
  AvgDialog_117501_Content_33 = {
    Text = "Tende le braccia esili, pesantemente velate di garza nera, sollevando in alto il pugnale cerimoniale—"
  },
  AvgDialog_117501_Content_34 = {
    Text = "La luce delle candele riflette l'ombra del pugnale, che si conficca con ferocia nelle fasce addormentate sull'altare."
  },
  AvgDialog_117501_Content_35 = {
    Text = "Un rivoltante suono viscido risuona mentre la lama perfora la carne spessa. Una melma scura trasuda dalla ferita, inzuppando le vistose rune del Navigatore sulla fascia di velluto."
  },
  AvgDialog_117501_Content_36 = {
    Text = "Un'altra notte sta per giungere..."
  },
  AvgDialog_117501_Content_37 = {
    Text = "Lascia sfuggire un sospiro di sollievo e chiude gli occhi, ma ciò che la avvolge non è un abisso di oscurità, bensì il sogno del passato ritrovato."
  },
  AvgDialog_117501_Content_38 = {Text = "..."},
  AvgDialog_117501_Content_39 = {
    Text = "(L'istante in cui il pugnale mi ha trafitta. C'era qualcuno lì...)"
  },
  AvgDialog_117501_Content_4 = {
    Text = "Riposatevi presto, poiché domani è Il Giorno dell'Allineamento Stellare, e dovrete ancora guidare i Navigatori sul loro cammino con il vostro sacro sangue."
  },
  AvgDialog_117501_Content_40 = {
    Text = "(Chi era? Non l'ho mai incontrato prima, eppure provo una strana nostalgia...)"
  },
  AvgDialog_117501_Content_41 = {
    Text = "...Un ragno?"
  },
  AvgDialog_117501_Content_42 = {
    Text = "Un minuscolo ragno viola scuro ti fissa dall'albero maestro. Vedendoti sveglio, alza la zampa anteriore e ti saluta."
  },
  AvgDialog_117501_Content_43 = {
    Text = "Nel sogno, ho udito qualcuno cantare..."
  },
  AvgDialog_117501_Content_44 = {
    Text = "Etereo, soave, come il canto di una sirena, indugia senza fine nelle tue orecchie."
  },
  AvgDialog_117501_Content_45 = {
    Text = "Tragici fanciulli, il tessuto del fato è già stato ordito, e inevitabilmente intraprenderete il viaggio che vi è destinato."
  },
  AvgDialog_117501_Content_46 = {
    Text = "E tu, l'ospite da un altro mondo—"
  },
  AvgDialog_117501_Content_47 = {
    Text = "Quando il momento dell'allineamento delle stelle farà ritorno, vi prego, ponete fine al ciclo della tragedia."
  },
  AvgDialog_117501_Content_48 = {
    Text = "Con un lungo e lugubre sospiro, il fantasma della donna svanisce."
  },
  AvgDialog_117501_Content_49 = {Text = "?!"},
  AvgDialog_117501_Content_5 = {
    Text = "Murphy fissa intensamente la fiamma tremolante della Lanterna. Il suo Velo Nero ondeggia con i suoi movimenti, proiettando ombre simili a cortine sulle pareti della cabina."
  },
  AvgDialog_117501_Content_50 = {
    Text = "Una volta dissipata la momentanea sensazione di terrore, finalmente ti calmi e osservi ciò che ti circonda."
  },
  AvgDialog_117501_Content_51 = {
    Text = "Dove mi trovo...?"
  },
  AvgDialog_117501_Content_52 = {
    Text = "Un materasso soffice. Uno spazio tranquillo avvolto da un baldacchino nero. Il tenue profumo di salvia e incenso aleggia nell'aria."
  },
  AvgDialog_117501_Content_53 = {
    Text = "Prima... io..."
  },
  AvgDialog_117501_Content_54 = {
    Text = "Doll! Mi senti? Doll?"
  },
  AvgDialog_117501_Content_55 = {
    Text = "Abbassa la voce. Stai disturbando il mio ricevitore di onde vocali."
  },
  AvgDialog_117501_Content_56 = {
    Text = "Ho raggiunto la nave su cui William si è imbarcato, secondo i pescatori! Ma quella nave ha fatto vela verso la tempesta!"
  },
  AvgDialog_117501_Content_57 = {
    Text = "Lascia che indovini. La tua prossima frase sarà..."
  },
  AvgDialog_117501_Content_58 = {
    Text = "LO INSEGUIRÒ!"
  },
  AvgDialog_117501_Content_59 = {
    Text = "Hai intenzione di lanciarti nella fossa delle Isole Bermuda con questa barchetta? Non temi di capovolgerti là dentro?"
  },
  AvgDialog_117501_Content_6 = {
    Text = "Miryam, hai mai fatto un sogno?"
  },
  AvgDialog_117501_Content_60 = {
    Text = "Non posso permettermi di perdere un altro indizio; questa è l'unica informazione reale e valida che abbiamo trovato in mesi!"
  },
  AvgDialog_117501_Content_61 = {
    Text = "Che la Chiave d'argento illumini il nostro cammino!"
  },
  AvgDialog_117501_Content_62 = {
    Text = "Non hai udito la frase attesa \"Che la Chiave d'Argento ci Guidi\", ma invece hai percepito il crepitio di un collegamento interrotto."
  },
  AvgDialog_117501_Content_63 = {
    Text = "Ciò che seguì fu un fragoroso ruggito di onde, seguito a breve dall'oscurità infinita che tutto inghiottì—"
  },
  AvgDialog_117501_Content_64 = {
    Text = "Tre mesi fa, seguendo la notizia di un misterioso uomo biondo salpato dal porto di Innsmouth, ti sei messo in viaggio per tracciare la posizione di William."
  },
  AvgDialog_117501_Content_65 = {
    Text = "Di recente, hai finalmente avvistato le bandiere dei pescatori descritte sulla superficie del mare, ma un'improvvisa tempesta ti ha fatto deviare dalla rotta."
  },
  AvgDialog_117501_Content_66 = {
    Text = "Quando hai riaperto gli occhi, ti sei ritrovato in questa stanza."
  },
  AvgDialog_117501_Content_67 = {
    Text = "Sei sveglio? Ti stiamo tutti aspettando."
  },
  AvgDialog_117501_Content_68 = {
    Text = "Il baldacchino nero del letto viene sollevato delicatamente, accompagnato da una voce femminile familiare eppure estranea."
  },
  AvgDialog_117501_Content_69 = {
    Text = "Noi...? Chi sei tu...?"
  },
  AvgDialog_117501_Content_7 = {
    Text = "Certamente, Madre Divina. In innumerevoli sogni, vedo la grande Lemuria ergersi, rinata sotto la luce del sole."
  },
  AvgDialog_117501_Content_70 = {
    Text = "Quattro volti familiari circondano il tuo letto, facendoti sentire profondamente a disagio."
  },
  AvgDialog_117501_Content_71 = {
    Text = "Per ordine della Madre Divina, i Navigatori attendono il tuo risveglio da lungo tempo. Bevi questa medicina. La nostra Madre Divina l'ha preparata personalmente."
  },
  AvgDialog_117501_Content_72 = {
    Text = "Caecus ti porge una coppa di vetro finemente lavorata; il liquido torbido, di un giallo acceso, è inquietante."
  },
  AvgDialog_117501_Content_73 = {
    Text = "Cos'è questo...?"
  },
  AvgDialog_117501_Content_74 = {
    Text = "Sei vivo, e questa è già una fortuna sufficiente. Basta con le domande."
  },
  AvgDialog_117501_Content_75 = {
    Text = "La Madre Divina mi ha ordinato di prepararla. Bevila, e sii grato, umano."
  },
  AvgDialog_117501_Content_76 = {
    Text = "Sotto i loro sguardi vigili, ne prendi un sorso esitante."
  },
  AvgDialog_117501_Content_77 = {
    Text = "BAH! È aspro! Ma è puro succo di limone?!"
  },
  AvgDialog_117501_Content_78 = {
    Text = "Ti raddrizzi di scatto, il volto contratto in una smorfia di dolore."
  },
  AvgDialog_117501_Content_79 = {
    Text = "Dato che Lui è sano e salvo, voglio andare in coperta a ricevere la chiamata. Il Reame Divino mi sta chiamando."
  },
  AvgDialog_117501_Content_8 = {
    Text = "L'eterna radiosità si estende sui mari lontani, guidando la nostra rotta verso una nuova era."
  },
  AvgDialog_117501_Content_80 = {
    Text = "(Questo mondo è folle, oppure lo sono io... Uno dei due deve esserlo.)"
  },
  AvgDialog_117501_Content_81 = {
    Text = "Ehm... dove mi trovo esattamente?..."
  },
  AvgDialog_117501_Content_82 = {
    Text = "Ti trovi a bordo del Paradise, il rifugio marittimo più caro ai Navigatori."
  },
  AvgDialog_117501_Content_83 = {
    Text = "Stiamo navigando verso Lemuria, l'Eterno Reame Divino."
  },
  AvgDialog_117501_Content_9 = {
    Text = "Miryam istintivamente fornisce la risposta, ma la domanda che segue rivela una sorpresa inconfondibile."
  },
  AvgDialog_117502_Content_1 = {Text = "..."},
  AvgDialog_117502_Content_10 = {
    Text = "Nell'ultimo bagliore di luce prima che la vostra visuale sprofondi nell'oscurità assoluta, una figura sfreccia davanti a voi."
  },
  AvgDialog_117502_Content_11 = {
    Text = "Una chioma di capelli dorati e splendenti, il suo braccio meccanico che riluce di riflessi metallici."
  },
  AvgDialog_117502_Content_12 = {
    Text = "William...?"
  },
  AvgDialog_117502_Content_2 = {Text = "..."},
  AvgDialog_117502_Content_3 = {
    Text = "Da quanto tempo combattete tra fetide cataste di pesci?"
  },
  AvgDialog_117502_Content_4 = {
    Text = "Un'ora? Un giorno? O una quantità di tempo incommensurabile?"
  },
  AvgDialog_117502_Content_5 = {
    Text = "(Irrompere nel momento in cui i Navigatori si mobilitano collettivamente per il rito... È stata davvero una decisione impulsiva e terribile.)"
  },
  AvgDialog_117502_Content_6 = {
    Text = "La sensazione viscida è divenuta così familiare da risultare ormai insensibile, e il fetore del muco appiccicoso non tormenta più le vostre narici congestionate."
  },
  AvgDialog_117502_Content_7 = {
    Text = "(Se solo potessi provare un'altra volta... Che peccato...)"
  },
  AvgDialog_117502_Content_8 = {
    Text = "Ti sforzi di sollevare la Chiave d'argento. Il nucleo che un tempo brillava di splendore inizia a tremare. Sei sull'orlo del collasso, sputando un fiotto di sangue."
  },
  AvgDialog_117502_Content_9 = {
    Text = "(Quindi... È finita... Mi dispiace... Non sono riuscito a uscirne...)"
  },
  AvgDialog_117503_Content_1 = {
    Text = "Un viaggiatore"
  },
  AvgDialog_117503_Content_10 = {
    Text = "Il tuo cuore martella con un ritmo improvviso e frenetico, e apri la bocca, già conoscendo l'identità di chi si cela Dietro il Velo."
  },
  AvgDialog_117503_Content_100 = {
    Text = "Un banco di pesci esplode fuori dall'acqua, in preda a spasmi e contorsioni nell'aria densa, prima di precipitare accanto a te in una pioggia fetida e appiccicosa."
  },
  AvgDialog_117503_Content_101 = {
    Text = "Accompagnati da un suono agghiacciante, i pesci semi-putrefatti rimbalzano inutilmente sul ponte, la melma in decomposizione nel punto d'Impatto sprigiona un tanfo soffocante."
  },
  AvgDialog_117503_Content_102 = {
    Text = "Teneri, fragili viticci si fanno strada attraverso i loro pallidi ventri, strisciando inquietantemente verso di te—"
  },
  AvgDialog_117503_Content_11 = {
    Text = "<Shake:Murphy...>"
  },
  AvgDialog_117503_Content_12 = {
    Text = "Tra le garze, la sua pelle pallida e bluastra è esposta, bianca come un cadavere alla deriva sul punto di disintegrarsi."
  },
  AvgDialog_117503_Content_13 = {
    Text = "Come osi pronunciare il nome della Madre Divina con tanta disinvoltura!"
  },
  AvgDialog_117503_Content_14 = {
    Text = "Va bene, Caecus. {Male=È un Ospite,Female=È un'Ospite} del Paradise e si unirà alla nostra grande Navigazione."
  },
  AvgDialog_117503_Content_15 = {
    Text = "Cinque paia di occhi si fissano su di te con insistenza, ricacciandoti in gola le parole che stavi per pronunciare."
  },
  AvgDialog_117503_Content_16 = {
    Text = "...Murphy, posso parlarti in privato?"
  },
  AvgDialog_117503_Content_17 = {Text = "..."},
  AvgDialog_117503_Content_18 = {Text = "..."},
  AvgDialog_117503_Content_19 = {Text = "Murphy..."},
  AvgDialog_117503_Content_2 = {
    Text = "La figura che parla siede in silenzio accanto al tuo letto, il volto celato da un torbido Velo Nero."
  },
  AvgDialog_117503_Content_20 = {
    Text = "Se le tue Domande non sono pronte, in realtà ne ho una per te."
  },
  AvgDialog_117503_Content_21 = {
    Text = "Perché sei venuto/a al Paradise? Per avvicinarsi, bisogna sopravvivere alla tempesta."
  },
  AvgDialog_117503_Content_22 = {
    Text = "Per correre un rischio simile, devi avere una richiesta."
  },
  AvgDialog_117503_Content_23 = {
    Text = "Quindi... hai visto un uomo più alto di me di mezza testa, con i capelli dorati?"
  },
  AvgDialog_117503_Content_24 = {
    Text = "Murphy ti lancia un'occhiata di traverso e sbuffa con disprezzo."
  },
  AvgDialog_117503_Content_25 = {
    Text = "Data la tua statura, quella descrizione corrisponde a parecchi Membri dell'Equipaggio."
  },
  AvgDialog_117503_Content_26 = {
    Text = "No, lo riconosceresti all'istante... Ha un Braccio meccanico, è molto bello, e ha un lieve profumo di cedro."
  },
  AvgDialog_117503_Content_27 = {
    Text = "...Allora posso confermare che non ho mai visto nessuno del genere. Quei membri dell'equipaggio emanano sempre un fetore di pesce sporco e disgustoso."
  },
  AvgDialog_117503_Content_28 = {
    Text = "Dunque, Murphy, c'è un'ultima cosa fondamentale."
  },
  AvgDialog_117503_Content_29 = {Text = "Hm?"},
  AvgDialog_117503_Content_3 = {
    Text = "(Una voce familiare... Chi è...)"
  },
  AvgDialog_117503_Content_30 = {
    Text = "Vuoi fuggire con me?"
  },
  AvgDialog_117503_Content_31 = {Text = "Eh?!"},
  AvgDialog_117503_Content_32 = {
    Text = "Murphy indietreggia, poi la rabbia le colora le guance. Lotta per riprendere il controllo, lasciando infine sfuggire uno sbuffo beffardo."
  },
  AvgDialog_117503_Content_33 = {
    Text = "Cosa intendi con \"fuga\"?"
  },
  AvgDialog_117503_Content_34 = {
    Text = "Letteralmente. Dobbiamo trovare un modo per lasciare questa nave e liberarci dal controllo dei Navigatori."
  },
  AvgDialog_117503_Content_35 = {
    Text = "Perché dovrei scappare con te?"
  },
  AvgDialog_117503_Content_36 = {
    Text = "Perché non ti piace la vita che conduci qui."
  },
  AvgDialog_117503_Content_37 = {
    Text = "Non ti piacciono le dottrine fabbricate di Miryam, il culto ipocrita dei seguaci, né quegli onori vuoti."
  },
  AvgDialog_117503_Content_38 = {
    Text = "Murphy abbassa lentamente lo sguardo."
  },
  AvgDialog_117503_Content_39 = {
    Text = "Vedendo il suo silenzio, incalzi rapidamente il tuo vantaggio."
  },
  AvgDialog_117503_Content_4 = {
    Text = "Le tue braccia doloranti si tendono mentre ti sollevi a fatica, cercando di comprendere la situazione."
  },
  AvgDialog_117503_Content_40 = {
    Text = "In un altro mondo ti ho incontrata, e ti ho riconosciuta all'istante. Abbiamo vissuto le stesse terribili circostanze, e tu hai trovato un modo per fuggire..."
  },
  AvgDialog_117503_Content_41 = {Text = "Hmph..."},
  AvgDialog_117503_Content_42 = {
    Text = "Sbagliato, sbagliato! Ti sbagli di grosso!"
  },
  AvgDialog_117503_Content_43 = {Text = "Murphy...?"},
  AvgDialog_117503_Content_44 = {
    Text = "La reazione di Murphy ti coglie completamente alla sprovvista."
  },
  AvgDialog_117503_Content_45 = {
    Text = "Comincia a ridacchiare, e il suono si avvita in una risata isterica che riempie la stanza."
  },
  AvgDialog_117503_Content_46 = {
    Text = "Dopo un po', sembra aver esaurito la sua ilarità, e la risata si spegne di colpo. Alza la testa e ti fissa con ferocia."
  },
  AvgDialog_117503_Content_47 = {
    Text = "Il sacro embrione del Dio è annidato nel mio petto. Sono la venerata Madre Divina, adorata da tutti. Perché dovrei dare ascolto alle vostre suppliche mortali di \"fuga\"?"
  },
  AvgDialog_117503_Content_48 = {
    Text = "Ma quando il Dio nascerà, tu morirai..."
  },
  AvgDialog_117503_Content_49 = {
    Text = "Non c'è bisogno di attendere quel momento, sciocco."
  },
  AvgDialog_117503_Content_5 = {
    Text = "Stai ferma, sciocca."
  },
  AvgDialog_117503_Content_50 = {
    Text = "Murphy ti presenta una sinistra fascia da neonato. Dove dovrebbe trovarsi la testa di un infante, si è rappreso un familiare grumo violaceo di carne gelatinosa."
  },
  AvgDialog_117503_Content_51 = {
    Text = "Il Feto Divino?!"
  },
  AvgDialog_117503_Content_52 = {
    Text = "Lo riconosci come il falso dio deforme che i Navigatori tentarono di evocare su Sona-Nyl."
  },
  AvgDialog_117503_Content_53 = {
    Text = "Il Feto Divino è già nato in questo mondo? Ma perché è... così piccolo?!"
  },
  AvgDialog_117503_Content_54 = {
    Text = "Perché è così piccolo... Che domanda ridicola da porre."
  },
  AvgDialog_117503_Content_55 = {
    Text = "Se fosse rimasto così piccolo, non sarebbe stato un pallone d'idrogeno gonfio, intento a sottrarre avidamente energia dalla madre, riempiendosi senza sosta, espandendosi e comprimendo il mio petto..."
  },
  AvgDialog_117503_Content_56 = {
    Text = "Poi, nell'istante in cui la madre muore, si sarebbe disgregato, frantumato e ridotto in cenere..."
  },
  AvgDialog_117503_Content_57 = {
    Text = "L'hai visto. Questo è il Feto Divino che ho partorito."
  },
  AvgDialog_117503_Content_58 = {
    Text = "Questo lo chiami... un dio?"
  },
  AvgDialog_117503_Content_59 = {
    Text = "E allora? Qualcuno ha mai assistito alla nascita del dio dei Navigatori?"
  },
  AvgDialog_117503_Content_6 = {
    Text = "La fanciulla si alza con ansia, la garza nera che la vela ondeggia inquieta."
  },
  AvgDialog_117503_Content_60 = {
    Text = "Chi può affermare che questa massa di carne maleodorante tra le nostre mani non sia un vero \"Dio\"?"
  },
  AvgDialog_117503_Content_61 = {
    Text = "La voce di sfida rimbomba come un tuono, echeggiando nella tua mente."
  },
  AvgDialog_117503_Content_62 = {
    Text = "Non sono la Murphy che conosci; sono la Madre Divina dei Navigatori, l'unica che condivide il Suo sangue."
  },
  AvgDialog_117503_Content_63 = {
    Text = "Non farmi pentire di averti portato in questo Paradiso. Ora, prendi i tuoi pensieri ridicoli e rotola fuori da questa stanza. Lasciami sola."
  },
  AvgDialog_117503_Content_64 = {
    Text = "Vaghi sulla nave da crociera del Paradise, seguendo memorie passate, mentre i bassi marinai dalla sembianza di pesce si affaccendano intorno, ignorandoti."
  },
  AvgDialog_117503_Content_65 = {
    Text = "Finché non scorgi due figure familiari accanto alla sala macchine."
  },
  AvgDialog_117503_Content_66 = {
    Text = "Ragazzo, vieni a prendermi! Dacci dentro con tutto quello che hai!"
  },
  AvgDialog_117503_Content_67 = {Text = "Sì!"},
  AvgDialog_117503_Content_68 = {Text = "CLANG!"},
  AvgDialog_117503_Content_69 = {
    Text = "Ancora bloccato, eh... Maledizione, sarò mai abbastanza forte da portare a termine il nostro piano..."
  },
  AvgDialog_117503_Content_7 = {
    Text = "Questa nave ospita molti sensibili al Mare profondo. Prima di adattarti al \"Paradise,\" resta immobile, o il tuo Spirito verrà ulteriormente turbato."
  },
  AvgDialog_117503_Content_70 = {
    Text = "Abbassa la voce, ragazzo. Le Orecchie Indiscrete sono ovunque. Se ci scoprono, nessuno dei due se la cava."
  },
  AvgDialog_117503_Content_71 = {
    Text = "Lord Golia, ma voi avete detto che la nostra stirpe discende dai forti, e che non dovremmo temere nulla..."
  },
  AvgDialog_117503_Content_72 = {
    Text = "Stupido ragazzo. Anche i forti devono cedere, talvolta. Su questa nave, fingiamo di obbedire a quelle donne folli."
  },
  AvgDialog_117503_Content_73 = {Text = "Ma..."},
  AvgDialog_117503_Content_74 = {
    Text = "Zitto, sta arrivando qualcuno."
  },
  AvgDialog_117503_Content_75 = {
    Text = "Il gigante emerge dall'Ombra della sala macchine; lo stridio della sua pesante lama trascinata sul pavimento quasi ti assorda, sovrastando il fragore della cabina."
  },
  AvgDialog_117503_Content_76 = {
    Text = "Ci rivediamo, piccolo."
  },
  AvgDialog_117503_Content_77 = {
    Text = "Golia... Come sono finito su questa nave?"
  },
  AvgDialog_117503_Content_78 = {
    Text = "Chiedilo a te stesso. I viaggiatori comuni non sono i benvenuti nel territorio di Miryam, figuriamoci una piccola imbarcazione che ci è piombata addosso."
  },
  AvgDialog_117503_Content_79 = {
    Text = "Non so quale fortuna tu possieda, ma quella bambina ha improvvisamente cambiato idea qualche giorno fa. Ci è severamente proibito toccarti."
  },
  AvgDialog_117503_Content_8 = {
    Text = "Ti ritrovi faccia a faccia con un paio di familiari occhi rossi."
  },
  AvgDialog_117503_Content_80 = {
    Text = "Altrimenti, quella donna avrebbe già estratto l'Argento dal tuo corpo. Dopotutto, in un mondo in cui la maggior parte degli esseri umani è morta, l'Argento è una risorsa che si esaurisce a ogni utilizzo."
  },
  AvgDialog_117503_Content_81 = {
    Text = "Dunque, qual è la tua posizione? Il Golia che conosco non è un debole che si lascia manipolare facilmente."
  },
  AvgDialog_117503_Content_82 = {
    Text = "Piccolo, sei appena salito su questa nave. C'è ancora molto che non sai."
  },
  AvgDialog_117503_Content_83 = {
    Text = "Devi ricordare solo una cosa: tutto su questo vascello è deciso da quella bambina, la Madre Divina. Non contrariarla — o almeno, non farti scoprire se lo fai."
  },
  AvgDialog_117503_Content_84 = {
    Text = "La pazza che dovrebbe essere al comando le obbedisce ciecamente."
  },
  AvgDialog_117503_Content_85 = {
    Text = "Quanto al resto, te lo dirò quando ci rivedremo altrove, se il Fato lo permetterà."
  },
  AvgDialog_117503_Content_86 = {
    Text = "Ho bisogno di schiarirmi le idee... Andrò in coperta a prendere un po' di brezza marina."
  },
  AvgDialog_117503_Content_87 = {
    Text = "Resti solo a prua, lo sguardo perso in lontananza."
  },
  AvgDialog_117503_Content_88 = {
    Text = "Il mare è avvolto in una leggera foschia bianca e pura. La nave da crociera procede placida, fendendo il clamore dell'oceano e il rombo dei macchinari."
  },
  AvgDialog_117503_Content_89 = {
    Text = "Inspiri profondamente l'aria salmastra, cercando di districare i tuoi pensieri caotici."
  },
  AvgDialog_117503_Content_9 = {Text = "Tum. Tum."},
  AvgDialog_117503_Content_90 = {
    Text = "Ho inseguito la nave di William nella tempesta, ho avuto un incidente e sono stato tratto in salvo dalla nave dei Navigatori..."
  },
  AvgDialog_117503_Content_91 = {
    Text = "Il Feto Divino è nato, Murphy è diventata la Madre Divina, Miryam sta raccogliendo Argento e Golia sta tramando qualcosa in segreto..."
  },
  AvgDialog_117503_Content_92 = {
    Text = "<Shake:Click—>"
  },
  AvgDialog_117503_Content_93 = {
    Text = "Eh, cos'era quel suono?"
  },
  AvgDialog_117503_Content_94 = {
    Text = "Ti volti per seguire il rumore, ma il ponte è inquietantemente silenzioso, senza anima viva in vista."
  },
  AvgDialog_117503_Content_95 = {
    Text = "(Era solo la mia immaginazione?)"
  },
  AvgDialog_117503_Content_96 = {
    Text = "<Shake:Plop, plop, plop...>"
  },
  AvgDialog_117503_Content_97 = {Text = "Eh?!"},
  AvgDialog_117503_Content_98 = {
    Text = "In profondità sotto la superficie, innumerevoli piccoli corpi si estendono fitti, i loro aloni torbidi e fluttuanti simili a un'eruzione purulenta sull'acqua."
  },
  AvgDialog_117503_Content_99 = {
    Text = "Questi sono... pesci?"
  },
  AvgDialog_117504_Content_1 = {
    Text = "Rito di Navigazione"
  },
  AvgDialog_117504_Content_10 = {
    Text = "Ci prepariamo per il Rito di Navigazione. Gli esseri spirituali sono naturalmente attratti dall'energia sacra, divenendo il nutrimento stesso del nostro Rito."
  },
  AvgDialog_117504_Content_100 = {
    Text = "Quella voce ti chiama—"
  },
  AvgDialog_117504_Content_101 = {
    Text = "<Italic:<Red:Aiutami.>>"
  },
  AvgDialog_117504_Content_102 = {
    Text = "Incapace di contenere l'impulso, ti lanci giù dall'albero maestro."
  },
  AvgDialog_117504_Content_103 = {
    Text = "Devi andare ad aiutarla. Liberarla da questo Rito sanguinario."
  },
  AvgDialog_117504_Content_104 = {
    Text = "Murphy, ferma il Rito! Morirai! Ce ne andiamo da qui!"
  },
  AvgDialog_117504_Content_105 = {
    Text = "Sei impazzito?! Come osi profanare la Madre Divina!"
  },
  AvgDialog_117504_Content_106 = {
    Text = "Non sono la Murphy che conosci, ho già fatto la mia Scelta!"
  },
  AvgDialog_117504_Content_107 = {
    Text = "So che non sei la mia Murphy, ma ho incontrato molti Risvegliati della Genesi prima d'ora — Ramona: Timeworn, Helot: Catena, Doll: Inferno..."
  },
  AvgDialog_117504_Content_108 = {
    Text = "Sprofondano nella Follia a causa delle sventure che sopportano. Le loro terribili esperienze non mutano la natura fondamentale dei loro cuori."
  },
  AvgDialog_117504_Content_109 = {
    Text = "Smetti di aggrapparti a questo Sentiero sbagliato. Fuggiamo insieme!"
  },
  AvgDialog_117504_Content_11 = {
    Text = "Rito di Navigazione?"
  },
  AvgDialog_117504_Content_110 = {
    Text = "Fuga...? Dove andiamo, allora?"
  },
  AvgDialog_117504_Content_111 = {
    Text = "Questo è il mondo perfetto. Ogni tentativo di Fuga non fa che sprofondarci in un ciclo più profondo e disperante."
  },
  AvgDialog_117504_Content_112 = {
    Text = "Guarda indietro verso le onde imponenti alle tue spalle."
  },
  AvgDialog_117504_Content_113 = {
    Text = "Accompagnato dal violento ribollire del mare, migliaia di Navigatori e serpenti si levano attorno alla pallida scultura d'avorio, irradiando un'infinita sensazione di minaccia."
  },
  AvgDialog_117504_Content_114 = {
    Text = "Madre Divina... perdonatemi, ma non posso più seguire le vostre istruzioni, né tollerare questa follia che profana il nostro Signore."
  },
  AvgDialog_117504_Content_115 = {
    Text = "Miryam si inginocchia a prua, offrendo un rito reverente in direzione del punto in cui l'orizzonte si divide."
  },
  AvgDialog_117504_Content_116 = {
    Text = "O Signore, vi prego, benedite noi fedeli. I profanatori che tentano di ostacolare il rito sono già apparsi."
  },
  AvgDialog_117504_Content_117 = {
    Text = "Vi prego, punite l'impudente canaglia che osa offendere la Madre Divina."
  },
  AvgDialog_117504_Content_118 = {
    Text = "Salgono sul ponte della nave da crociera con passi viscidi e sinistri, percorrendo scale invisibili tessute dalle onde impetuose."
  },
  AvgDialog_117504_Content_119 = {
    Text = "<Big:<Shake:Avanti! Schiacciàteli! Fateli a pezzi!>>"
  },
  AvgDialog_117504_Content_12 = {
    Text = "La Madre Divina ci guiderà verso la Lemuria ascendente."
  },
  AvgDialog_117504_Content_13 = {
    Text = "Vedendo la tua Confusione, Miryam si fa sorprendentemente gentile."
  },
  AvgDialog_117504_Content_14 = {
    Text = "Serbi molte domande. Non temere; per decreto della Madre Divina, risponderò con grazia a ciascuna di esse."
  },
  AvgDialog_117504_Content_15 = {
    Text = "...Onestamente, il tuo cambiamento di atteggiamento mi lascia già sotto Shock."
  },
  AvgDialog_117504_Content_16 = {
    Text = "A posteriori, il tuo precedente conflitto con i Navigatori si rivela del tutto superfluo."
  },
  AvgDialog_117504_Content_17 = {
    Text = "Impossibile. Ho assistito con i miei occhi a come voi Navigatori avete condotto un Rito sinistro..."
  },
  AvgDialog_117504_Content_18 = {
    Text = "Fu un malinteso. Celebravamo quei Riti unicamente per incanalare l'energia necessaria a mantenere questo vascello in navigazione."
  },
  AvgDialog_117504_Content_19 = {
    Text = "Ora che la maggior parte degli esseri umani è ridotta in cenere, Riti così intensivi non sono più necessari. L'Argento accumulato da vari luoghi è sufficiente per le nostre esigenze."
  },
  AvgDialog_117504_Content_2 = {
    Text = "Immersa nell'opprimente fetore di pesce, la Donna in veste purpurea aggrotta le sopracciglia e si volta verso Faros al suo fianco."
  },
  AvgDialog_117504_Content_20 = {
    Text = "Perciò, i Navigatori si diressero a Necrovia per raccogliere l'Argento dai defunti. Sfortunatamente, il nostro piano finì per confliggere con gli appetiti di Doresain, il Re di Necrovia."
  },
  AvgDialog_117504_Content_21 = {
    Text = "Stando a quanto sappiamo dell'Università di Mythag, anche voi utilizzate Argento raffinato come fonte di energia, non è così?"
  },
  AvgDialog_117504_Content_22 = {
    Text = "Quella Chiave d'Argento che portate al petto ne è la testimonianza."
  },
  AvgDialog_117504_Content_23 = {
    Text = "Istintivamente dissenti, ma non riesci a formulare una replica. Alla fine, cambi argomento."
  },
  AvgDialog_117504_Content_24 = {
    Text = "Miryam... qual è il tuo scopo?"
  },
  AvgDialog_117504_Content_25 = {
    Text = "Per ricostruire il Reame Divino e resuscitare Lemuria, naturalmente."
  },
  AvgDialog_117504_Content_26 = {
    Text = "Ora che il nostro Signore è disceso, nulla è più urgente del ritorno al Reame Divino e del vedere la gloriosa Lemuria rinascere."
  },
  AvgDialog_117504_Content_27 = {
    Text = "Il vostro Signore è disceso... Intendi dire, Tulu?"
  },
  AvgDialog_117504_Content_28 = {
    Text = "Sì. La Sua coscienza permane in uno stato tra il sogno e la veglia, ma Egli manterrà certamente la Sua promessa e ci ricondurrà al Reame Divino."
  },
  AvgDialog_117504_Content_29 = {
    Text = "Lemuria... dove si trova?"
  },
  AvgDialog_117504_Content_3 = {
    Text = "Raccogliete l'energia spirituale qui."
  },
  AvgDialog_117504_Content_30 = {
    Text = "Sopra i cieli, sotto il mare. L'oracolo non rivela altro."
  },
  AvgDialog_117504_Content_31 = {
    Text = "Miryam cade in silenzio dopo quelle parole."
  },
  AvgDialog_117504_Content_32 = {
    Text = "Dopo aver raccolto tutti i frammenti d'Argento, Faros si pone accanto a Miryam, reggendo una scatola di legno colma di perle argentee."
  },
  AvgDialog_117504_Content_33 = {
    Text = "Faros, perché ti sei unito ai Navigatori?"
  },
  AvgDialog_117504_Content_34 = {
    Text = "C'è forse bisogno di chiederlo? Perché Lemuria è proprio lì. La mia patria mi chiama."
  },
  AvgDialog_117504_Content_35 = {
    Text = "Ovunque io vada, odo il Suo richiamo, come l'incessante ondata della marea, giorno dopo giorno."
  },
  AvgDialog_117504_Content_36 = {
    Text = "Fissa l'orizzonte, e le sue parole risuonano come un'eco lontana."
  },
  AvgDialog_117504_Content_37 = {
    Text = "Sembra una giornata splendida, oggi. Guarda, il sole sta per emergere."
  },
  AvgDialog_117504_Content_38 = {Text = "Il sole..."},
  AvgDialog_117504_Content_39 = {
    Text = "Segui il suo sguardo—"
  },
  AvgDialog_117504_Content_4 = {
    Text = "Sì, Vostra Santità."
  },
  AvgDialog_117504_Content_40 = {
    Text = "Tum. Tum. Il battito del tuo cuore è quasi assordante."
  },
  AvgDialog_117504_Content_41 = {
    Text = "<Shake:Aspetta, e il... sole nel cielo?>"
  },
  AvgDialog_117504_Content_42 = {
    Text = "Il sole? Il sole non è proprio lì?"
  },
  AvgDialog_117504_Content_43 = {
    Text = "No, no, non è di quel sole che parlo!"
  },
  AvgDialog_117504_Content_44 = {
    Text = "Ciò che si leva sopra il livello del mare è una sfera di luce tenue e calda — un sole che avresti dovuto agognare."
  },
  AvgDialog_117504_Content_45 = {
    Text = "Non questo sole? Quale altro sole c'è?"
  },
  AvgDialog_117504_Content_46 = {
    Text = "Il calore insolito di quella luce tiepida ti lascia intorpidito e assetato, e le parole che sfuggono dalle tue labbra sono esitanti e confuse."
  },
  AvgDialog_117504_Content_47 = {
    Text = "Dovrebbe essere un sole nero pece, privo di luce!"
  },
  AvgDialog_117504_Content_48 = {
    Text = "Non ho mai sentito parlare né visto un sole nero..."
  },
  AvgDialog_117504_Content_49 = {
    Text = "Faros, in che anno siamo?"
  },
  AvgDialog_117504_Content_5 = {
    Text = "Faros si inginocchia, raccogliendo con cura le Spoglie insanguinate pezzo per pezzo."
  },
  AvgDialog_117504_Content_50 = {
    Text = "1920 d.C. C'è qualcosa che non va?"
  },
  AvgDialog_117504_Content_51 = {
    Text = "d.C... non \"Dopo il diluvio\"... Mi trovo davvero nel nuovo mondo..."
  },
  AvgDialog_117504_Content_52 = {
    Text = "Non distrarti. La Madre Divina è qui."
  },
  AvgDialog_117504_Content_53 = {
    Text = "In qualità di Ospite sanzionato da Lei, ti concedo il permesso di osservare la più sacra cerimonia di pilotaggio qui presente."
  },
  AvgDialog_117504_Content_54 = {
    Text = "Ma non lasciare questo luogo senza il mio permesso. I blasfemi saranno decapitati e le loro teste esposte al pubblico."
  },
  AvgDialog_117504_Content_55 = {
    Text = "Un piccolo gruppo in nero e porpora emerge dalla poppa, i loro passi bizzarramente sincronizzati mentre strisciano verso il ponte sotto i tuoi piedi."
  },
  AvgDialog_117504_Content_56 = {
    Text = "La ragazza in testa indossa una pallida veste bianca, stringendo al petto un fagotto voluminoso e gonfio. La sua espressione è indistinta e stordita sotto il velo di garza nera."
  },
  AvgDialog_117504_Content_57 = {Text = "..."},
  AvgDialog_117504_Content_58 = {
    Text = "La fila si compatta rapidamente a prua della nave, ogni figura vestita di nero già familiare con il proprio punto di sbarco."
  },
  AvgDialog_117504_Content_59 = {
    Text = "Un paio di piedi nudi avanza nel sentiero stretto lasciato per lei nella Formazione. Dietro di lei, innumerevoli piccoli Frammenti d'Argento precipitano verso il basso."
  },
  AvgDialog_117504_Content_6 = {
    Text = "Un tenue bagliore emana dalla sua fronte. Pochi secondi dopo, restano soltanto alcuni Frammenti Residui color Argento."
  },
  AvgDialog_117504_Content_60 = {
    Text = "Madre Divina, ricevi la nostra gratitudine per il sangue sacro! Ingoiamo le fiamme dello Spirito e beviamo la Preghiera Cremisi! Che mille Anime Devote ora si levino come luce del faro!"
  },
  AvgDialog_117504_Content_61 = {
    Text = "I Mostri strisciano sul pavimento, gareggiando per raccogliere le perle d'Argento sparse a terra."
  },
  AvgDialog_117504_Content_62 = {
    Text = "…Miryam…"
  },
  AvgDialog_117504_Content_63 = {
    Text = "Miryam si inginocchia umilmente, sollevando un vassoio d'Argento coperto di garza nera, sul quale giace un Pugnale scintillante."
  },
  AvgDialog_117504_Content_64 = {
    Text = "Stimata Madre Divina, guida la stirpe del Re Divino affinché conduca noi Navigatori smarriti, e rivela il sacro cammino verso Lemuria."
  },
  AvgDialog_117504_Content_65 = {
    Text = "La bambina prende il pugnale."
  },
  AvgDialog_117504_Content_66 = {
    Text = "O stimato Re Divino..."
  },
  AvgDialog_117504_Content_67 = {
    Text = "Il Pugnale perfora le fasce. Una goccia di plasma denso si raccoglie a mezz'aria, dotata di un'orrifica volontà propria."
  },
  AvgDialog_117504_Content_68 = {
    Text = "<Change>Io seguo il Vostro Sangue Divino."
  },
  AvgDialog_117504_Content_69 = {
    Text = "Tutti i Credenti si inginocchiano, le mani levate al cielo, usando lame sottili per incidere i polsi sinistri ricoperti di squame."
  },
  AvgDialog_117504_Content_7 = {
    Text = "Miryam... tu e Faros avete richiamato questi pesci volanti?"
  },
  AvgDialog_117504_Content_70 = {
    Text = "Innumerevoli fili d'Argento si avvolgono attorno alla goccia di sangue, propagandosi dai polsi di oltre cento Credenti, estendendosi lungo una traccia inafferrabile."
  },
  AvgDialog_117504_Content_71 = {
    Text = "<Change>Offrire gli spiriti della moltitudine in Sacrificio."
  },
  AvgDialog_117504_Content_72 = {
    Text = "La goccia di sangue color inchiostro ruota, si condensa e balza su una Scultura d'Avorio bianco latte, infiltrandosi in una fitta rete di sottili filamenti sanguigni."
  },
  AvgDialog_117504_Content_73 = {
    Text = "Infusa di vita, la Scultura d'Avorio si libra sopra il colosso d'acciaio e si tuffa dritta nell'oceano silente."
  },
  AvgDialog_117504_Content_74 = {
    Text = "<Change>Vi preghiamo, squarciate il falso Abisso e guidateci direttamente al Vostro Regno."
  },
  AvgDialog_117504_Content_75 = {
    Text = "In un istante, mare e cielo tremano. Il vasto oceano si gonfia di Onde Furiose, emettendo un lamento simile a quello di una bestia gigantesca in travaglio."
  },
  AvgDialog_117504_Content_76 = {
    Text = "Vento e onde danzano selvaggiamente, piangendo, formando una terrificante, tremante parete d'acqua."
  },
  AvgDialog_117504_Content_77 = {
    Text = "Madre Divina, la quantità di energia spirituale in questo gruppo potrebbe essere insufficiente..."
  },
  AvgDialog_117504_Content_78 = {
    Text = "Nessun problema."
  },
  AvgDialog_117504_Content_79 = {
    Text = "La fanciulla solleva il velo, volgendosi verso gli esseri inginocchiati."
  },
  AvgDialog_117504_Content_8 = {
    Text = "Miryam sembra accorgersi della tua presenza solo ora. Inclina leggermente il capo nella tua direzione."
  },
  AvgDialog_117504_Content_80 = {
    Text = "Madre Divina, donaci il tuo sangue!"
  },
  AvgDialog_117504_Content_81 = {
    Text = "<Big:<Shake:Madre Divina, donaci il Tuo sangue!>>"
  },
  AvgDialog_117504_Content_82 = {
    Text = "Le onde sonore si innalzano. Tra le grida, le dita della fanciulla si protendono verso il suo petto."
  },
  AvgDialog_117504_Content_83 = {
    Text = "Le sue unghie, affilate come Lame, squarciano il petto lungo la cicatrice purpurea, rivelando l'unico cuore rimasto."
  },
  AvgDialog_117504_Content_84 = {
    Text = "<Shake:Cacciate! Banchettate! Vi offro la carne e il sangue della Madre Divina, e voi forgerete per me la scala inversa verso il Reame Divino!>"
  },
  AvgDialog_117504_Content_85 = {
    Text = "La congregazione si riversa in avanti. Le loro pinne e le strane chele si protendono avide verso il fragile corpo della Madre Divina."
  },
  AvgDialog_117504_Content_86 = {
    Text = "Le prosciugano il sangue e si cibano della sua carne. Fili Cremisi proliferano poi con violenza, precipitandosi nel mare profondo."
  },
  AvgDialog_117504_Content_87 = {
    Text = "Onde cremisi di sangue si diffondono selvaggiamente dalla Scultura d'Avorio, solidificandosi in milioni di coralli di sangue nel tumulto."
  },
  AvgDialog_117504_Content_88 = {
    Text = "Il rito è completo! Indietro, tutti quanti!"
  },
  AvgDialog_117504_Content_89 = {
    Text = "Avanza, calpestando i corpi dei Navigatori ammassati davanti a Murphy, avvolgendo il corpo della fanciulla in una pesante veste nera. Sotto la veste, rivoli di sangue continuano a scorrere incessanti."
  },
  AvgDialog_117504_Content_9 = {
    Text = "Non dovresti trovarti nella camera della Madre Divina? Perché..."
  },
  AvgDialog_117504_Content_90 = {
    Text = "Lemuria! Lemuria! Il sangue di Sua Santità la Madre Divina ha rivelato Il Sentiero per Lemuria!"
  },
  AvgDialog_117504_Content_91 = {
    Text = "Tra le migliaia di linee di sangue, scorgi un insolito filo d'Argento. Quel filo emerge dal tuo stesso petto, estendendosi verso l'alto... estendendosi..."
  },
  AvgDialog_117504_Content_92 = {
    Text = "...finché non svanisce in un punto oltre i cieli."
  },
  AvgDialog_117504_Content_93 = {
    Text = "La fanciulla sembra percepire l'esistenza di quel filo d'Argento. Alza lo sguardo, le pupille improvvisamente tremanti, e il suo sguardo inorridito perfora direttamente il tuo nascondiglio."
  },
  AvgDialog_117504_Content_94 = {Text = "..."},
  AvgDialog_117504_Content_95 = {
    Text = "Nell'istante in cui i vostri sguardi si incrociano, una forza immensa e invisibile ti trascina, ignorando ogni tua Resistenza, precipitandoti in una terrificante Illusione da incubo."
  },
  AvgDialog_117504_Content_96 = {
    Text = "...Rivedi l'impuro sole nero."
  },
  AvgDialog_117504_Content_97 = {
    Text = "Un tamburo a mano?"
  },
  AvgDialog_117504_Content_98 = {
    Text = "No. Quello è il suono di un battito cardiaco."
  },
  AvgDialog_117504_Content_99 = {
    Text = "Lunga, soffocante, prossima alla morte; svanita da prima dei tempi antichi, eppure rianimata dopo il Lungo Sogno..."
  },
  AvgDialog_118123_Content_1 = {
    Text = "Cavaliere del Mulino a Vento"
  },
  AvgDialog_118123_Content_10 = {
    Text = "È proprio con tali speranze che gli ho perdonato {Male=la,Female=la} {Male=sua,Female=sua} scortesia."
  },
  AvgDialog_118123_Content_11 = {
    Text = "(Alla fine... non è cambiato nulla...)"
  },
  AvgDialog_118123_Content_12 = {
    Text = "Lo sapevo... Hai bisogno del mio aiuto."
  },
  AvgDialog_118123_Content_13 = {
    Text = "Corri in giro come un pollo senza testa! Dove diavolo stai andando!"
  },
  AvgDialog_118123_Content_14 = {
    Text = "Quello che ha detto William prima. Andiamo a prendere la scialuppa nella stiva!"
  },
  AvgDialog_118123_Content_15 = {
    Text = "La visuale dal ponte è completamente aperta! Stai cercando di darti in pasto agli uomini-pesce!"
  },
  AvgDialog_118123_Content_16 = {
    Text = "Nell'ultimo ciclo, sei stato tu a finire in pasto a loro!"
  },
  AvgDialog_118123_Content_17 = {
    Text = "Non osare ribattere alla Madre Divina! Corri verso la plancia! C'è una struttura che conduce alla capsula di fuga!"
  },
  AvgDialog_118123_Content_18 = {
    Text = "E mettimi giù! I miei capelli sono già un disastro!"
  },
  AvgDialog_118123_Content_19 = {
    Text = "Sei il mio ostaggio prezioso; non è il momento di preoccuparsi delle apparenze! La prego, cara Madre Divina, sopporti ancora un poco!"
  },
  AvgDialog_118123_Content_2 = {
    Text = "Ti lanci giù, sentendo il vento tagliente sferzarti le guance, poi la corda attorno alla vita si tende di colpo, arrestando la caduta."
  },
  AvgDialog_118123_Content_20 = {
    Text = "<Shake:Attento, i seguaci di Miryam ci stanno raggiungendo!>"
  },
  AvgDialog_118123_Content_3 = {
    Text = "Ehi! Che stai facendo!"
  },
  AvgDialog_118123_Content_4 = {
    Text = "Tagli la corda con un coltellino, poi salti a terra."
  },
  AvgDialog_118123_Content_5 = {
    Text = "Hai intenzione di scappare così, con me sulle spalle? Ci raggiungeranno presto!"
  },
  AvgDialog_118123_Content_6 = {
    Text = "Ahhh, sei così stupido, mi fai morire!"
  },
  AvgDialog_118123_Content_7 = {
    Text = "Ma a cosa stavo pensando, a nutrire persino un bagliore di speranza per questo idiota."
  },
  AvgDialog_118123_Content_8 = {
    Text = "Questa fuga è più scellerata di qualsiasi altra abbia tentato in passato."
  },
  AvgDialog_118123_Content_9 = {
    Text = "<Italic:Se <Yellow:%player%> esiste in questo mondo, la direzione della storia sarà diversa?>"
  },
  AvgDialog_118124_Content_1 = {
    Text = "Strappate il velo per legare Murphy, ignorando i suoi tentativi di divincolarsi."
  },
  AvgDialog_118124_Content_10 = {
    Text = "Se osservi bene noi tre, ti renderai conto che la vera principessa tra noi non sono io."
  },
  AvgDialog_118124_Content_11 = {
    Text = "William vi lega saldamente la corda attorno, a te e a Murphy."
  },
  AvgDialog_118124_Content_12 = {
    Text = "Prenditi cura della nostra principessa, non perderla! Ci sono scialuppe di salvataggio nel ponte inferiore. Ci vediamo là!"
  },
  AvgDialog_118124_Content_13 = {
    Text = "Tre, due, uno, salta!"
  },
  AvgDialog_118124_Content_2 = {
    Text = "Tutto pronto! Smetti di muoverti. Non farti del male!"
  },
  AvgDialog_118124_Content_3 = {
    Text = "Ugh! Ti morderò!"
  },
  AvgDialog_118124_Content_4 = {
    Text = "È più da te essere così, senza darti arie, Murphy."
  },
  AvgDialog_118124_Content_5 = {
    Text = "Smettete di perdere tempo! La vostra Punizione per aver insultato la Madre Divina sarà eseguita non appena riavrò la mia libertà!"
  },
  AvgDialog_118124_Content_6 = {
    Text = "I Passi là fuori... Si stanno facendo più frequenti?"
  },
  AvgDialog_118124_Content_7 = {
    Text = "Il suono di Passi frettolosi confluisce in un mare, mentre corpi bassi e tarchiati continuano a sbattere contro la porta del soggiorno, producendo tonfi sordi."
  },
  AvgDialog_118124_Content_8 = {
    Text = "Andiamo, sfonderemo la finestra e usciremo! Prendi questo, poi salta sul ponte!"
  },
  AvgDialog_118124_Content_9 = {
    Text = "Fare nodi con le lenzuola...? William, sembri una principessa in fuga da una fiaba."
  },
  AvgDialog_118125_Content_1 = {
    Text = "Principessa della Torre"
  },
  AvgDialog_118125_Content_10 = {
    Text = "Osservi attentamente: ci sono due fili spezzati, e quattro anelli di filo sono ancora avvolti sul filatoio."
  },
  AvgDialog_118125_Content_11 = {
    Text = "Ho... quattro possibilità rimaste?"
  },
  AvgDialog_118125_Content_12 = {
    Text = "Lei annuisce, e poi scuote la testa."
  },
  AvgDialog_118125_Content_13 = {
    Text = "Ho sentito il tuo canto. Non sei muta... Semplicemente non ti è permesso dire nulla...?"
  },
  AvgDialog_118125_Content_14 = {
    Text = "Apre la bocca, ma tutto ciò che ne esce è un silenzio eterno."
  },
  AvgDialog_118125_Content_15 = {
    Text = "Lei rivolge lo sguardo al cielo lontano. Tu segui il suo sguardo verso l'orizzonte."
  },
  AvgDialog_118125_Content_16 = {
    Text = "C'è solo un sole nero sommerso nell'acqua."
  },
  AvgDialog_118125_Content_17 = {
    Text = "Cough, cough...!"
  },
  AvgDialog_118125_Content_18 = {
    Text = "Ti risvegli di colpo nel letto, ansimando forte per il dolore dell'annegamento."
  },
  AvgDialog_118125_Content_19 = {
    Text = "Sono tornato... ancora una volta..."
  },
  AvgDialog_118125_Content_2 = {
    Text = "La brezza marina è salata e acre, porta un sapore amaro indelebile quando soffia nella tua bocca."
  },
  AvgDialog_118125_Content_20 = {
    Text = "Le quattro persone intorno a te — sorprese, indifferenti, sinceramente preoccupate o che fingono interesse — non riesci a curartene. L'unica cosa che indugia nella tua mente è il volto di Murphy prima che l'ultimo ciclo sia terminato."
  },
  AvgDialog_118125_Content_21 = {
    Text = "Aiutami... so che puoi..."
  },
  AvgDialog_118125_Content_22 = {
    Text = "Poi l'oscurità inghiotte ogni cosa, trasformandosi in un dubbio indelebile nella tua mente."
  },
  AvgDialog_118125_Content_23 = {
    Text = "In ogni caso, devi prima incontrarti con William."
  },
  AvgDialog_118125_Content_24 = {
    Text = "Golia e Miryam percorrono un corridoio vuoto, i loro passi riecheggiano davanti e dietro di loro."
  },
  AvgDialog_118125_Content_25 = {
    Text = "Oltrepassano il murale barocco della Madre Divina, le piccole lanterne che sostituiscono gli applique in ottone, e il dormitorio silenzioso e deserto."
  },
  AvgDialog_118125_Content_26 = {
    Text = "Non si sfiorano né parlano; un'atmosfera tesa aleggia tra i due."
  },
  AvgDialog_118125_Content_27 = {
    Text = "Miryam si ferma davanti alla porta della cabina del Capitano e si volta per aprirla."
  },
  AvgDialog_118125_Content_28 = {
    Text = "Golia la raggiunge con pochi passi e si ferma alle sue spalle."
  },
  AvgDialog_118125_Content_29 = {
    Text = "Ehi, Miryam. Quella bambina ti sta mentendo."
  },
  AvgDialog_118125_Content_3 = {Text = "..."},
  AvgDialog_118125_Content_30 = {
    Text = "Di cosa desideri parlare? Dovresti essere di guardia al ponte, non è così?"
  },
  AvgDialog_118125_Content_31 = {
    Text = "Se dovesse accadere qualcosa a quella donna che tiene in funzione la sala macchine, conosci le conseguenze."
  },
  AvgDialog_118125_Content_32 = {
    Text = "Smettila di dire sciocchezze. Abbiamo Caecus là. Quei Membri dell'Equipaggio senza cervello non possono creare alcun problema."
  },
  AvgDialog_118125_Content_33 = {
    Text = "L'unico nodo cruciale è questo: la ragazzina ti sta mentendo."
  },
  AvgDialog_118125_Content_34 = {
    Text = "Filistea. Calunniare la Madre Divina non è nel tuo solito comportamento."
  },
  AvgDialog_118125_Content_35 = {
    Text = "Lo sai che questa nave non raggiungerà mai quella Lemuria, vero?"
  },
  AvgDialog_118125_Content_36 = {Text = "...Golia."},
  AvgDialog_118125_Content_37 = {
    Text = "Non sei che un cane da me allevato. A meno che non ti ordini di brandire la tua Lama contro un nemico specifico, non ti è concesso parlare."
  },
  AvgDialog_118125_Content_38 = {
    Text = "Prima che raggiungiamo la riva, il vostro unico ordine è gestire quei marinai per me e assicurarvi che non disturbino il Dormiveglia della Madre Divina."
  },
  AvgDialog_118125_Content_39 = {
    Text = "Se c'è qualcosa che devi sapere..."
  },
  AvgDialog_118125_Content_4 = {
    Text = "La donna che regge un filatoio ti osserva con un'espressione addolorata."
  },
  AvgDialog_118125_Content_40 = {
    Text = "<Shake:Se questa nave ha anche la minima possibilità di raggiungere Lemuria, è unicamente grazie alla benedizione della nostra Madre Divina.>"
  },
  AvgDialog_118125_Content_41 = {
    Text = "Tsk, ostinata, vile donna..."
  },
  AvgDialog_118125_Content_42 = {
    Text = "Ho già detto tutto ciò che andava detto."
  },
  AvgDialog_118125_Content_43 = {
    Text = "Non incolpare me per quello che succederà dopo."
  },
  AvgDialog_118125_Content_44 = {
    Text = "Caecus, esegui il piano."
  },
  AvgDialog_118125_Content_45 = {Text = "Aye!"},
  AvgDialog_118125_Content_46 = {
    Text = "Prendete il controllo della nave prima che il Rito sia Completo."
  },
  AvgDialog_118125_Content_47 = {
    Text = "Vagate per il ponte, cercando affannosamente indizi che possano condurvi al nascondiglio di William."
  },
  AvgDialog_118125_Content_48 = {
    Text = "Se ricordo bene, è proprio qui..."
  },
  AvgDialog_118125_Content_49 = {
    Text = "Forzate la Schiusa lungo la fessura sul ponte, stringete i denti e vi lanciate giù con un Salto."
  },
  AvgDialog_118125_Content_5 = {
    Text = "C'è qualcosa che vuoi dirmi?"
  },
  AvgDialog_118125_Content_50 = {
    Text = "<Shake:Cough, bleh...>"
  },
  AvgDialog_118125_Content_51 = {
    Text = "Tossisci sputando la canna palustre che hai in bocca, pentendoti della scelta di atterrare a testa in giù."
  },
  AvgDialog_118125_Content_52 = {
    Text = "William, smettila di nasconderti! So che sei qui!"
  },
  AvgDialog_118125_Content_53 = {
    Text = "Dopo un po', alcuni fruscii provengono da dietro la catasta di paglia."
  },
  AvgDialog_118125_Content_54 = {
    Text = "Non ha senso."
  },
  AvgDialog_118125_Content_55 = {
    Text = "...Se aveste un'Abilità così precisa nel localizzarmi, mi avreste già raggiunto per le strade di Londra."
  },
  AvgDialog_118125_Content_56 = {
    Text = "Parliamone... Cosa avete vissuto da quando siete saliti su questa nave?"
  },
  AvgDialog_118125_Content_57 = {Text = "..."},
  AvgDialog_118125_Content_58 = {
    Text = "Avete riassunto brevemente ciò che avete vissuto nel Ciclo Temporale."
  },
  AvgDialog_118125_Content_59 = {
    Text = "Mi dispiace, non ci sarà abbastanza tempo una volta iniziata la cerimonia. William, dobbiamo rimuovere l'imboscata nel soggiorno dell'altra Murphy."
  },
  AvgDialog_118125_Content_6 = {
    Text = "La donna annuisce."
  },
  AvgDialog_118125_Content_60 = {
    Text = "Vai. Seguimi, so come evitare le guardie."
  },
  AvgDialog_118125_Content_61 = {
    Text = "Volete dire che Golia sta tramando una ribellione, e io devo venire a Nascondermi con voi..."
  },
  AvgDialog_118125_Content_62 = {
    Text = "E sapete tutto questo in anticipo perché avete vissuto un Ciclo Temporale?"
  },
  AvgDialog_118125_Content_63 = {
    Text = "Così assurdo, così ridicolo... a meno che non sia fuori di senno... <Shake:Mmpff!>"
  },
  AvgDialog_118125_Content_64 = {
    Text = "Mi dispiace, il tempo stringe. Venite con noi."
  },
  AvgDialog_118125_Content_65 = {Text = "William!"},
  AvgDialog_118125_Content_66 = {
    Text = "Non preoccupatevi, l'avevo previsto. Ho già bloccato i suoni provenienti dall'esterno del soggiorno."
  },
  AvgDialog_118125_Content_67 = {
    Text = "Portatela via prima!"
  },
  AvgDialog_118125_Content_7 = {
    Text = "È legato al ciclo temporale?"
  },
  AvgDialog_118125_Content_8 = {
    Text = "La donna scuote la testa. Le punte delle sue dita sfiorano il filo del filatoio, compiendo una rotazione in senso orario prima di fermarsi al punto di partenza."
  },
  AvgDialog_118125_Content_9 = {
    Text = "Mentre il filatoio gira, il filo originale si disintegra e si spezza."
  },
  AvgDialog_118699_Content_1 = {
    Text = "Il Nostro Desiderio"
  },
  AvgDialog_118699_Content_10 = {
    Text = "Un'energia spirituale più intensa, eh... Capisco. Avviserò tutti i Risvegliati."
  },
  AvgDialog_118699_Content_11 = {
    Text = "Nel cortile al crepuscolo, Ogier termina il suo allenamento quotidiano come al solito, senza saltare una singola ripetizione."
  },
  AvgDialog_118699_Content_12 = {
    Text = "Oggi ho battuto di nuovo un record precedente..."
  },
  AvgDialog_118699_Content_13 = {
    Text = "Asciugandosi il sudore che cola, si sostiene con la pesante lancia. Ogier si volta, ma la persona che gli avrebbe sorriso offrendogli incoraggiamento non c'è più. Solo la sua Ombra solitaria si allunga sul terreno."
  },
  AvgDialog_118699_Content_14 = {
    Text = "Lo stocco di Lotan para e scaglia via le armi di due Investigatori, ponendo fine all'ennesima Battaglia che dura appena un minuto."
  },
  AvgDialog_118699_Content_15 = {
    Text = "Ma cosa succede con le matricole di questi tempi? Avanti! Sono troppo deboli!"
  },
  AvgDialog_118699_Content_16 = {
    Text = "Prima che possa alzare la Spada per continuare a tormentarle, le due matricole ansimanti davanti a lei stanno già congiungendo le mani in segno di resa implorante."
  },
  AvgDialog_118699_Content_17 = {
    Text = "Tsk, che noia..."
  },
  AvgDialog_118699_Content_18 = {
    Text = "Lotan sospira al sole calante e si volta via svogliatamente, ricordando le battaglie esaltanti che un tempo aveva avuto con una certa persona."
  },
  AvgDialog_118699_Content_19 = {
    Text = "Aigis taglia l'ultimo filo di lana, spiega con cura il maglione appena lavorato a maglia, lo liscia, e poi si alza in punta di piedi per appenderlo nell'armadio colmo di capi in maglia."
  },
  AvgDialog_118699_Content_2 = {
    Text = [[
Mondo#Kadath
Ora]]
  },
  AvgDialog_118699_Content_20 = {
    Text = "Ho imparato molti più motivi, ormai. So fare il punto a treccia, il punto waffle, il punto ondulato, il punto conchiglia e i motivi fair isle."
  },
  AvgDialog_118699_Content_21 = {
    Text = "Mi chiedo che tipo ti piacerebbe, %player%..."
  },
  AvgDialog_118699_Content_22 = {
    Text = "Il furbo topolino grigio sgattaiola attraverso la fessura della porta, depositando fedelmente un anello luccicante nella mano della sua compagna."
  },
  AvgDialog_118699_Content_23 = {
    Text = "Ben fatto, Brown."
  },
  AvgDialog_118699_Content_24 = {
    Text = "Jenkin sbadiglia annoiata, getta distrattamente l'anello in una scatola di legno aperta lì accanto, che trabocca di un ammasso disordinato di \"tesori.\""
  },
  AvgDialog_118699_Content_25 = {Text = "Squeak..."},
  AvgDialog_118699_Content_26 = {
    Text = "Quella persona un tempo pretendeva che Jenkin restituisse tutti i tesori rubati uno per uno, ma {Male=lui,Female=lei} non si fa vedere da molto tempo. Allora perché si sente ancora così giù? Si chiede Brown."
  },
  AvgDialog_118699_Content_27 = {
    Text = "Lily siede composta alla scrivania e apre un altro libro di fiabe."
  },
  AvgDialog_118699_Content_28 = {
    Text = "Un'alta pila di libri per bambini già letti si è accumulata nell'angolo della scrivania, e la ragazza annota idee per storie nel quaderno accanto a lei."
  },
  AvgDialog_118699_Content_29 = {
    Text = "Quando un'idea la entusiasma, un tenue sorriso appare sul volto tranquillo della ragazza, e i suoi piedi cominciano a dondolare dolcemente sotto la scrivania."
  },
  AvgDialog_118699_Content_3 = {
    Text = "Il Tunnel sfocato e appena abbozzato crolla quando un'improvvisa, terrificante Corrosione colpisce. Ramona emette un gemito soffocato mentre la sua coscienza viene richiamata a forza dal sistema di emergenza."
  },
  AvgDialog_118699_Content_30 = {
    Text = "Sì, a tutti piacerà questa storia..."
  },
  AvgDialog_118699_Content_31 = {
    Text = "La matita danza mentre annota fantasie innocenti. Ma presto Lily smette di scrivere, lo sguardo perso nel vuoto oltre la finestra."
  },
  AvgDialog_118699_Content_32 = {
    Text = "Ma quando tornerai... a girare un altro film con me?"
  },
  AvgDialog_118699_Content_33 = {Text = "..."},
  AvgDialog_118699_Content_34 = {
    Text = "Helot inclina l'otre, versando il contenuto a terra davanti alla lapide."
  },
  AvgDialog_118699_Content_35 = {
    Text = "Dopo aver tracannato d'un fiato la mezza fiaschetta di vino rimasta, il guerriero se ne va in silenzio, lasciando solo una corona d'alloro appesa quietamente sulla pietra tombale."
  },
  AvgDialog_118699_Content_36 = {
    Text = "Sulla lussuosa tovaglia di velluto, il tè pomeridiano di Murphy è sontuoso come sempre."
  },
  AvgDialog_118699_Content_37 = {
    Text = "Le posate tintinnano contro il piatto mentre si porta alla bocca la ricca torta alla crema."
  },
  AvgDialog_118699_Content_38 = {
    Text = "Mangia la sua torta in un silenzio innaturale, lo sguardo fisso sulla sedia vuota di fronte a lei, dove sono disposti i servizi da tavola riservati a quella persona."
  },
  AvgDialog_118699_Content_39 = {
    Text = "Lasciare una signora come me tutta sola qui... che servitore incompetente che sei."
  },
  AvgDialog_118699_Content_4 = {
    Text = "Ramona! Pollux! State bene entrambi?"
  },
  AvgDialog_118699_Content_40 = {
    Text = "In una stanza del dormitorio appositamente riservata e vuota, gli arredi ordinati e nuovi di zecca sembrano disabitati; solo un alberello appena germogliato è posato accanto alla finestra."
  },
  AvgDialog_118699_Content_41 = {
    Text = "In rare occasioni, qualcuno potrebbe scorgere dietro quella finestra una donna dalla pelle ambrata, appoggiata al davanzale, che culla delicatamente l'alberello in vaso."
  },
  AvgDialog_118699_Content_42 = {
    Text = "Sebbene le attività del club siano ormai gradualmente riprese e tornate vivaci, quest'aula di musica appartenente al maestro esecutore resta un luogo che nessuno osa disturbare con leggerezza."
  },
  AvgDialog_118699_Content_43 = {Text = "..."},
  AvgDialog_118699_Content_44 = {
    Text = "La tenda è sollevata dolcemente dalla brezza notturna mentre Hameln sta in piedi davanti al pianoforte, lo sguardo rivolto alla torre dell'orologio."
  },
  AvgDialog_118699_Content_45 = {
    Text = "Il pianoforte che un tempo condividevano giace inutilizzato. Solo il suono del flauto di Hameln, ripetuto giorno dopo giorno, si diffonde sommesso sotto il chiaro di luna, inascoltato da chiunque."
  },
  AvgDialog_118699_Content_46 = {
    Text = "Nelle profondità della Pozza nera, l'eternamente solitario Prigioniero Oltre la Porta ha ora un compagno nel Dormiveglia."
  },
  AvgDialog_118699_Content_47 = {
    Text = "Gli occhi compassionevoli di Tawil si aprono in silenzio, contemplando l'involucro la cui anima vaga lontano."
  },
  AvgDialog_118699_Content_48 = {
    Text = "Nel laboratorio del Dipartimento di Ricerca, Ramona inzuppa di sudore la tuta da addestramento, conducendo instancabilmente l'allenamento mentale giorno e notte."
  },
  AvgDialog_118699_Content_49 = {
    Text = "Doll la osserva mentre sorseggia un'altra tazza di caffè forte, volta una nuova pagina del rapporto sperimentale e continua a calibrare i dati dello strumento."
  },
  AvgDialog_118699_Content_5 = {
    Text = "Cough... Sto bene. L'interruzione è stata tempestiva."
  },
  AvgDialog_118699_Content_50 = {
    Text = "<Small:Ah, il caffè di Winkle è davvero un po' troppo forte...>"
  },
  AvgDialog_118699_Content_51 = {
    Text = "Una notifica inviata a tutti i Risvegliati lampeggia sul Comunicatore che aveva appena posato."
  },
  AvgDialog_118699_Content_52 = {
    Text = "Ogni Risvegliato nel campus volge simultaneamente lo sguardo verso il proprio Comunicatore che squilla all'improvviso, gli occhi fissi sul nome che hanno atteso sullo schermo."
  },
  AvgDialog_118699_Content_53 = {
    Text = "A tutti i Risvegliatori di Mythag,\n\nNon molto tempo fa, eravamo uniti contro il disastro nero che tutto consuma. Ancora oggi, le lapidi nella Tomba delle Chiavi testimoniano innumerevoli sacrifici, inclusa la perdita del Custode, che ci ha garantito la pace definitiva.\n{Male=He,Female=She} è stato un compagno, un confidente, uno studente che aveva perfezionato l'arte di saltare le lezioni, un carissimo amico per molti, la nostra unica guida e l'eroe che ci ha salvati tutti."
  },
  AvgDialog_118699_Content_54 = {
    Text = "Mythag ha subito una perdita profonda con la scomparsa di {Male=his,Female=her}. Pur condividendo questo dolore collettivo, il Dipartimento di Ricerca ha mantenuto un impegno costante per localizzare tracce della coscienza del Custode.\nOriginariamente, intendevo trattenere queste informazioni fino al raggiungimento del successo, non volendo sottoporre la nostra comunità al peso aggiuntivo di una speranza prolungata e incerta. Tuttavia, abbiamo ora verificato una metodologia valida per localizzare <Yellow:%player%> e avvieremo a breve il tentativo finale di recupero."
  },
  AvgDialog_118699_Content_55 = {
    Text = [[
Questa operazione richiede la partecipazione di ogni Risvegliatore. Dobbiamo trasformare la dedizione concentrata di tutti noi per <Yellow:%player%> nell'energia spirituale necessaria a fungere da faro di navigazione che guidi {Male=him,Female=her} a casa.
A nome di Mythag, richiedo formalmente la vostra presenza davanti alla Pozza Nera. Vi invito tutti a stare insieme, come abbiamo fatto durante la battaglia finale, e a combattere fianco a fianco ancora una volta per <Yellow:%player%>.

Il vostro compagno,
Doll]]
  },
  AvgDialog_118699_Content_56 = {
    Text = [[
Mondo#Kadath
Il Giorno della Riunione]]
  },
  AvgDialog_118699_Content_57 = {
    Text = "Sotto l'area ristretta della torre dell'orologio, una folla silenziosa si erge dinanzi alla muta Pozza nera."
  },
  AvgDialog_118699_Content_58 = {
    Text = "Dopo che Doll spiega i principi del viaggio dimensionale, i Risvegliati che prima reclamavano a gran voce di partire ora restano in silenzio accanto al Dispositivo di Risonanza Spirituale."
  },
  AvgDialog_118699_Content_59 = {
    Text = "A causa delle caratteristiche spirituali dello spazio dimensionale, più spiriti appaiono insieme, maggiore sarà l'attenzione attratta dagli esseri superiori. Il Custode dall'altra parte troverà la {Male=sua,Female=sua} difesa ancora più ardua."
  },
  AvgDialog_118699_Content_6 = {
    Text = "Perché... Ho sentito chiaramente la {Male=sua,Female=sua} voce poco fa. Perché non riesco a trovarl{Male=o,Female=a}?"
  },
  AvgDialog_118699_Content_60 = {
    Text = "Davanti alla folla, Ramona tiene un bouquet di rose appassite, contemplando in silenzio la Pozza nera. Nell'altra mano, stringe con forza la Chiave d'argento numerata 0617."
  },
  AvgDialog_118699_Content_61 = {
    Text = "Lo strumento è pronto all'avvio. Tutti, concentrate le vostre menti."
  },
  AvgDialog_118699_Content_62 = {
    Text = "Doll preme il pulsante e un'onda di energia spirituale si propaga, intrecciando gli spiriti di tutti in fili sottili, formando una gigantesca rete connettiva."
  },
  AvgDialog_118699_Content_63 = {
    Text = "Ramona apre solennemente il palmo, e la Chiave d'argento si solleva lentamente in una strana attrazione gravitazionale, fluttuando al centro della rete invisibile, tremolando di un bagliore simile a un respiro."
  },
  AvgDialog_118699_Content_64 = {
    Text = "Tutti fissano la chiave, offrendo preghiere silenziose."
  },
  AvgDialog_118699_Content_65 = {
    Text = "Questa scuola, le persone qui, hanno tutte bisogno di te. Che sia un anno, due anni, dieci anni... finché la ricerca conserverà il suo significato, ti riporteremo indietro."
  },
  AvgDialog_118699_Content_66 = {
    Text = "Mio signore, ora riesco a resistere 40 secondi senza un collegamento. Posso proteggervi meglio adesso, e desidero davvero mostrarvi i risultati del mio addestramento..."
  },
  AvgDialog_118699_Content_67 = {
    Text = "Non ci sarà mai un altro studente di Mythag tenace quanto te. Quando mi farai vivere di nuovo una battaglia sotto il tuo comando?"
  },
  AvgDialog_118699_Content_68 = {
    Text = "Sono stata brava. Mangio le verdure in orario. Ho lavorato a maglia tante sciarpe, cappelli, guanti e maglioni di ogni tipo, tutti per te! Ti... piaceranno?"
  },
  AvgDialog_118699_Content_69 = {
    Text = "Tipo del Distretto Ovest, non hai ancora finito di imparare i segreti di sopravvivenza del Distretto Est che ti avevo promesso di insegnarti. Ho già incassato la retta, quindi sbrigati a tornare e non rovinare la reputazione commerciale di questa maestra ladra..."
  },
  AvgDialog_118699_Content_7 = {
    Text = "Lo stesso vale per me. Il mio \"Sacro Cuore\" riesce a percepire solo la direzione generale {Male=di lui,Female=di lei}, ma non dispongo di coordinate precise."
  },
  AvgDialog_118699_Content_70 = {
    Text = "{Male=Signor,Female=Signorina} Custode, credo che le persone gentili siano sempre benedette dalla buona sorte. Qualcuno come te avrà sicuramente un lieto fine."
  },
  AvgDialog_118699_Content_71 = {
    Text = "%player%, Lily ora sa leggere tanti libri di fiabe. Quando tornerai, possiamo fare di nuovo un film?"
  },
  AvgDialog_118699_Content_72 = {
    Text = "Un guerriero vittorioso dovrebbe fare ritorno alla {Male=sua,Female=sua} terra natale."
  },
  AvgDialog_118699_Content_73 = {
    Text = "Sbrigati a tornare, stupido servitore! Mi devi così tanti tè pomeridiani, e faresti bene a recuperarli tutti come si deve!"
  },
  AvgDialog_118699_Content_74 = {
    Text = "Una volta mi hai chiesto quale fosse il mio desiderio... Ora finalmente ho un desiderio tutto mio: spero che tu possa tornare sano e salvo."
  },
  AvgDialog_118699_Content_75 = {
    Text = "Mio inaffidabile germoglio... Mi avevi promesso un mondo rinnovato, e hai mantenuto la parola; ma non puoi lasciarmi qui da sola..."
  },
  AvgDialog_118699_Content_76 = {
    Text = "La nostra tribù non abbandonerà nessun membro."
  },
  AvgDialog_118699_Content_77 = {
    Text = "Il mio flauto veglierà per sempre su di te."
  },
  AvgDialog_118699_Content_78 = {
    Text = "Tutti i Risvegliati recitano in silenzio quel nome familiare. Rivoli di energia spirituale, fluenti come lucciole, confluiscono nella Chiave d'argento sospesa. Il centro della chiave inizia gradualmente a risplendere come una stella."
  },
  AvgDialog_118699_Content_79 = {
    Text = "Pollux e Castor si scambiano uno sguardo, annuendo l'uno all'altro. In un istante, il corpo di Castor si trasforma in una scia di luce e si fonde nel petto di Pollux."
  },
  AvgDialog_118699_Content_8 = {
    Text = "Tuttavia, l'intenso desiderio dell'ultimo istante della signorina Ramona ha reso la percezione del \"Sacro Cuore\" nei confronti di <Yellow:%player%> ancora più nitida."
  },
  AvgDialog_118699_Content_80 = {
    Text = "Un bagliore smeraldino vortica all'interno del <Blue:Sacro Cuore>. Dietro Pollux, un paio di magnifiche <Blue:Piume d'Onice> si dispiega. Egli punta il dito, e il cuore artificiale lampeggia in risposta allo splendore della Chiave d'Argento."
  },
  AvgDialog_118699_Content_81 = {
    Text = "Signorina Ramona."
  },
  AvgDialog_118699_Content_82 = {
    Text = "Incontrando lo sguardo solenne di Pollux, Ramona stringe con forza la rosa luminescente nella sua mano—il segnale concordato con il Custode."
  },
  AvgDialog_118699_Content_83 = {
    Text = "La forza spirituale, affinata attraverso innumerevoli prove generali, si condensa gradualmente seguendo la guida familiare. Alza il capo e fissa lo sguardo sulla Chiave d'Argento, riversando i propri desideri nel suo centro insieme a quelli di tutti gli altri."
  },
  AvgDialog_118699_Content_84 = {
    Text = "(<Yellow:%player%>, ti prego, aspettami. Vengo a riportarti a casa.)"
  },
  AvgDialog_118699_Content_9 = {
    Text = "Se raccogliessimo un'energia spirituale più intensa diretta verso <Yellow:%player%>, forse potrei individuare la posizione di %player% con maggiore precisione."
  },
  AvgDialog_118700_Content_1 = {
    Text = "Abbraccio fugace"
  },
  AvgDialog_118700_Content_10 = {
    Text = "Il rumore circostante svanisce. Nel profondo della sua mente, Ramona contempla quel sé lontano."
  },
  AvgDialog_118700_Content_11 = {
    Text = "Il tuo potere è più grande del mio... Forse questo compito dovrebbe essere intrapreso da te, per garantirne il successo..."
  },
  AvgDialog_118700_Content_12 = {
    Text = "Percependo i pensieri interiori di Ramona, Ramona: Consunta dal Tempo scuote il capo, sollevando gli occhi velati per osservare in silenzio l'abisso."
  },
  AvgDialog_118700_Content_13 = {
    Text = "Sono qui solo per vederti partire. In un viaggio così lontano attraverso le dimensioni, non c'è davvero differenza tra te e me. E inoltre..."
  },
  AvgDialog_118700_Content_14 = {
    Text = "Tu sei il {Male=suo,Female=suo} compagno. Questo è il vostro destino condiviso, non il mio."
  },
  AvgDialog_118700_Content_15 = {
    Text = "Va'. Va' a riportare {Male=lui,Female=lei} indietro, \"Ramona\"."
  },
  AvgDialog_118700_Content_16 = {
    Text = "La mano di Ramona si stringe attorno alla rosa. Dopo un lungo istante, annuisce solennemente e, sotto lo sguardo dell'altro sé, prende posto all'interno del Dispositivo di Separazione Spirituale."
  },
  AvgDialog_118700_Content_17 = {
    Text = "I suoi occhi fisici si serrano, mentre un altro paio di occhi si apre lentamente. Un'anima solidificata si distacca dal suo corpo, avvolta in una luce bianca nebbiosa, simile a un velo, dalla radiosità del \"Sacro Cuore\" di Pollux."
  },
  AvgDialog_118700_Content_18 = {
    Text = "Sotto lo sguardo di decine di occhi, Ramona si volta, incontrando uno a uno gli sguardi dei suoi compagni, caricandosi sulle spalle il peso di quelle gravose speranze."
  },
  AvgDialog_118700_Content_19 = {
    Text = "Guidata da quei desideri ardenti, si volta e si lancia nel vortice immenso. L'ingresso, simile a un portale dell'Inferno, inghiotte l'anima solitaria in un istante."
  },
  AvgDialog_118700_Content_2 = {
    Text = "Pollux si libra in alto come un angelo colmo di luce sacra, in attesa di guidare l'anima smarrita al cospetto di dio."
  },
  AvgDialog_118700_Content_3 = {
    Text = "Dopo essersi scambiati uno sguardo, Doll e Ramona attivano l'enorme dispositivo che copre quasi metà della Pozza Nera. Nella violenta turbolenza delle acque, il vortice colossale collassa con un fragore, creando un abisso che sembra pronto a divorare ogni cosa."
  },
  AvgDialog_118700_Content_4 = {
    Text = "Aspetta, quello è..."
  },
  AvgDialog_118700_Content_5 = {
    Text = "La maestosa distesa d'acqua defluisce in un altro mondo, e all'interno del vortice senza fondo, l'esistenza del mondo comincia a sfumare."
  },
  AvgDialog_118700_Content_6 = {
    Text = "Il confine di questo mondo, l'ingresso allo spazio dimensionale."
  },
  AvgDialog_118700_Content_7 = {
    Text = "Oltre l'abisso, {Male=lui,Female=lei} ti sta aspettando."
  },
  AvgDialog_118700_Content_8 = {
    Text = "Ramona annuisce. Un istante prima di varcare l'abisso, si ferma improvvisamente e si volta a guardare la folla."
  },
  AvgDialog_118700_Content_9 = {
    Text = "Una figura evanescente si erge in silenzio dietro la folla in preghiera. Una presenza celata nel profondo della sua coscienza, visibile solo a lei."
  },
  AvgDialog_118701_Content_1 = {Text = "Attesa"},
  AvgDialog_118701_Content_10 = {
    Text = "La nebbia si addensa e si dissolve, e un membro regolare dei Mythag appare all'ingresso della Pozza Nera, fermandosi in silenzio accanto a Doll, contemplando insieme la figura seduta immobile davanti al \"Portale\"."
  },
  AvgDialog_118701_Content_11 = {
    Text = "L'esposizione prolungata all'acqua della pozza non fa bene alla sua salute. Non hai intenzione di fermarla?"
  },
  AvgDialog_118701_Content_12 = {
    Text = "Le ho dato l'equipaggiamento protettivo di base. Il Danno fisico è qualcosa che posso ancora curare, ma il danno psicologico non è altrettanto facile da guarire."
  },
  AvgDialog_118701_Content_13 = {
    Text = "La razionale professoressa sospira e volta il capo con aria inquisitiva."
  },
  AvgDialog_118701_Content_14 = {
    Text = "Vieni qui di tua volontà di rado. Cosa hai portato questa volta?"
  },
  AvgDialog_118701_Content_15 = {
    Text = "Ah, una buona notizia che potrebbe proprio guarirle l'anima."
  },
  AvgDialog_118701_Content_16 = {
    Text = "Partner, grazie alla tua grande impresa, le D-fessure in tutto il mondo si sono ridotte significativamente di recente."
  },
  AvgDialog_118701_Content_17 = {
    Text = "Gli investigatori della scuola si sono rilassati. Tutti si limitano a frequentare le lezioni e sostenere esami ogni giorno. Mythag sta diventando sempre più simile a un'università ordinaria."
  },
  AvgDialog_118701_Content_18 = {
    Text = "Qualcuno ha proposto di erigere una statua in tuo onore, proprio accanto a quella del Preside Ward. La scuola sta ancora valutando la proposta."
  },
  AvgDialog_118701_Content_19 = {
    Text = "Ho presentato un parere contrario. Sei ancora qui, tra noi — perché mai dovresti essere ridotto a una statua come il preside?"
  },
  AvgDialog_118701_Content_2 = {
    Text = [[
Mondo#Kadath
Prima del funerale del Custode]]
  },
  AvgDialog_118701_Content_20 = {
    Text = "E poi, quando tornerai e vedrai il tuo enorme te stesso in piedi accanto al preside, resterai così imbarazzato da ammutolire."
  },
  AvgDialog_118701_Content_21 = {
    Text = "La tua espressione è così serena, non ci credo... Devi esserti perso in un altro mondo e aver dimenticato come fare ritorno..."
  },
  AvgDialog_118701_Content_22 = {
    Text = "Hai ragione, {Male=lui,Female=lei} è davvero entrato in un'altra Dimensione, una Dimensione molto lontana."
  },
  AvgDialog_118701_Content_23 = {
    Text = "Udendo la voce improvvisa di Daffodil alle sue spalle, Ramona si alza in piedi, quasi perdendo la compostezza, trattenendosi a stento dall'afferrare il braccio della bottegaia."
  },
  AvgDialog_118701_Content_24 = {
    Text = "Cosa hai detto? L'hai {Male=trovato,Female=trovata}? Dimensione... Ricordo che puoi viaggiare tra le Dimensioni!"
  },
  AvgDialog_118701_Content_25 = {
    Text = "Come posso riportar{Male=lo,Female=la} indietro? Pagherei qualsiasi prezzo!"
  },
  AvgDialog_118701_Content_26 = {
    Text = "Dopo questa supplica appassionata, Ramona nota finalmente l'espressione impassibile di Doll accanto a lei."
  },
  AvgDialog_118701_Content_27 = {Text = "...Cosa?"},
  AvgDialog_118701_Content_28 = {
    Text = "La tua determinazione è commovente, ma purtroppo quella dimensione non è collegata a questo mondo. Inoltre, non ho modo di condurre il Custode attraverso uno spazio dimensionale sconosciuto."
  },
  AvgDialog_118701_Content_29 = {
    Text = "Senza aver individuato una rotta certa, attraversare sconsideratamente le turbolenze dimensionali conduce a un solo esito: perdersi per sempre."
  },
  AvgDialog_118701_Content_3 = {
    Text = "Con un basso ronzio che segnala il completamento del test, gli strumenti mostrano ancora una volta un risultato nullo. Doll agita la mano in silenzio, e i Ricercatori si scambiano occhiate, iniziando tacitamente a smontare l'attrezzatura."
  },
  AvgDialog_118701_Content_30 = {
    Text = "Con la tecnologia attuale di Mythag, è impossibile riuscirci."
  },
  AvgDialog_118701_Content_31 = {
    Text = "Che significa... Abbiamo cercato così a lungo, e finalmente abbiamo notizie {Male=di lui,Female=di lei}—davvero vogliamo lasci{Male=arlo,Female=arla} là fuori, sol{Male=o,Female=a}?!"
  },
  AvgDialog_118701_Content_32 = {
    Text = "Potrei ancora discutere la tecnica del viaggio dimensionale con la Professoressa Doll — consideralo un regalo per una cliente fedele."
  },
  AvgDialog_118701_Content_33 = {
    Text = "Ma quando si tratta di recuperare <Yellow:%player%>, la parte più difficile è trovare il sentiero verso quel mondo specifico. Nemmeno la mia collezione contiene un tesoro segreto simile, capace di trascendere l'universo."
  },
  AvgDialog_118701_Content_34 = {
    Text = "Disporrò affinché il Dipartimento di Ricerca si dedichi interamente alla ricerca dimensionale a partire da oggi."
  },
  AvgDialog_118701_Content_35 = {
    Text = "Tra le dimensioni, talvolta non esiste alcuna intersezione, e non è possibile trovarla attraverso una ricerca esaustiva."
  },
  AvgDialog_118701_Content_36 = {
    Text = "Ciò che potresti affrontare è un lungo tentativo che sembra privo di speranza."
  },
  AvgDialog_118701_Content_37 = {
    Text = "Non rinunceremo."
  },
  AvgDialog_118701_Content_38 = {Text = "..."},
  AvgDialog_118701_Content_39 = {
    Text = "Capisco. Non importa quanto tempo ci vorrà, aspetterò {Male=lui,Female=lei}."
  },
  AvgDialog_118701_Content_4 = {
    Text = "Perché state mettendo via gli strumenti? Riprovate, devono esserci metodi di analisi a cui non abbiamo ancora pensato..."
  },
  AvgDialog_118701_Content_40 = {
    Text = [[
Mondo#Kadath
10 mesi dopo il funerale del Custode
Pozza Nera]]
  },
  AvgDialog_118701_Content_41 = {
    Text = "Passi vuoti riecheggiavano attraverso gli strati di cancelli bloccati, schizzando nell'acqua viscosa. La silenziosa Pozza nera dà il benvenuto al suo secondo visitatore della giornata."
  },
  AvgDialog_118701_Content_42 = {
    Text = "Sapevo che ti avrei trovata qui. Di nuovo."
  },
  AvgDialog_118701_Content_43 = {
    Text = "La persona a cui si rivolge non risponde. La sagoma immobile, come una statua che scruta lontano, resta rivolta verso la figura fluttuante davanti al \"Portale\"."
  },
  AvgDialog_118701_Content_44 = {
    Text = "Oggi ho ricevuto un'altra lettera di reclamo. Questa è la settima volta che rifiuti l'assegnazione di un partner per le missioni, insistendo nel condurre da sola l'indagine prevista per due persone."
  },
  AvgDialog_118701_Content_45 = {Text = "..."},
  AvgDialog_118701_Content_46 = {
    Text = "Va tutto bene. Non sono qui per criticarti o darti ordini, né per consigliarti—anche se Sylvia ha accennato a un lieve problema nel tuo profilo psicologico."
  },
  AvgDialog_118701_Content_47 = {
    Text = "Ma quante persone qui stanno perfettamente bene, in ogni caso?"
  },
  AvgDialog_118701_Content_48 = {
    Text = "Resta accanto a Ramona, contemplando insieme la figura che giace nel Riposo Eterno."
  },
  AvgDialog_118701_Content_49 = {
    Text = "C'è qualche compito speciale che devo svolgere?"
  },
  AvgDialog_118701_Content_5 = {
    Text = "Il numero e lo spettro di frequenza dei test sono stati più che sufficienti. Hai preso il massimo dei voti nel corso di Utilizzo degli Strumenti a Nucleo d'Argento, Ramona. Smettila di ingannare te stessa."
  },
  AvgDialog_118701_Content_50 = {
    Text = "Ramona, rimasta immobile come una statua fino a questo momento, finalmente parla, il tono piatto come quello di una macchina."
  },
  AvgDialog_118701_Content_51 = {Text = "Sì."},
  AvgDialog_118701_Content_52 = {
    Text = "Requisiti del compito?"
  },
  AvgDialog_118701_Content_53 = {
    Text = "Devi recarti in un luogo molto pericoloso per recuperare il tuo compagno."
  },
  AvgDialog_118701_Content_54 = {
    Text = "Non ho bisogno di un nuovo—"
  },
  AvgDialog_118701_Content_55 = {
    Text = "Intendo, il tuo partner PRIMORDIALE."
  },
  AvgDialog_118701_Content_56 = {
    Text = "Ramona volta bruscamente la testa per fissare gli occhi calmi di Doll."
  },
  AvgDialog_118701_Content_57 = {
    Text = "Questa missione è una scommessa, senza precedenti per livello di pericolosità. Temo che nessun supporto esterno all'interno della scuola possa accompagnarti..."
  },
  AvgDialog_118701_Content_58 = {
    Text = "Il Dipartimento di Ricerca ha ottenuto risultati? Quando?"
  },
  AvgDialog_118701_Content_59 = {
    Text = "Doll sorride, porgendo il rapporto di Ricerca appena stampato."
  },
  AvgDialog_118701_Content_6 = {
    Text = "Questo è soltanto un Guscio vuoto, privo di segni vitali. La coscienza del Custode... potrebbe essersi già dissolta."
  },
  AvgDialog_118701_Content_60 = {
    Text = "Da quando Daffodil ci ha informato riguardo al Custode, il Dipartimento di Ricerca ha tentato tutti i metodi tecnologici attualmente disponibili. Sorprendentemente, la svolta è arrivata dal Risvegliato."
  },
  AvgDialog_118701_Content_61 = {
    Text = "Abbiamo scoperto che il \"Sacro Cuore\" di Pollux è in grado di attrarre quell'esistenza. La Chiesa dei Portatori di Luce creò originariamente il \"Sacro Cuore\" per produrre anime pure e diffondere il \"sangue divino\"."
  },
  AvgDialog_118701_Content_62 = {
    Text = "Alla fine, progettarono di Sacrificare i loro Divi Gemelli per evocare la cosiddetta Terra Pura."
  },
  AvgDialog_118701_Content_63 = {
    Text = "Il Rito avrebbe dovuto attirare l'attenzione di Tohuwabohu e diffondere la Dissoluzione. Dopo una modifica mirata, il \"Sacro Cuore\" ha ottime probabilità di guidarci specificamente verso la posizione del Custode."
  },
  AvgDialog_118701_Content_64 = {
    Text = "Mythag intende inviare un Risvegliato eccezionalmente potente nello spazio dimensionale, seguendo la guida del \"Sacro Cuore\" per attraversare le Dimensioni e stabilire un tunnel che colleghi i due mondi."
  },
  AvgDialog_118701_Content_65 = {
    Text = "Se i dati dei test procederanno senza intoppi, potremo iniziare i tentativi in meno di un mese."
  },
  AvgDialog_118701_Content_66 = {
    Text = "Il tuo regime di addestramento includerà ora esercizi per la forza mentale. Spero che tu... non ti sforzi troppo, per non danneggiare il cervello."
  },
  AvgDialog_118701_Content_67 = {
    Text = [[
Mondo#Kadath
Un anno dopo il funerale del Custode
Pozza Nera]]
  },
  AvgDialog_118701_Content_68 = {
    Text = "Il dispositivo di Separazione Spirituale in rapido funzionamento emette un allarme rosso di sovraccarico. L'osservatore nelle vicinanze preme immediatamente il pulsante di arresto."
  },
  AvgDialog_118701_Content_69 = {
    Text = "Il portello della cabina dell'utilizzatore si apre di scatto. Ramona, ormai esausta, riesce a muovere appena un dito prima che i Ricercatori la sorreggano rapidamente per farla uscire."
  },
  AvgDialog_118701_Content_7 = {
    Text = "Il verdetto crudele cade infine dalle labbra di Doll. Vedendo le lacrime scorrere dagli occhi attoniti di Ramona, la professoressa, avvezza al Sacrificio, chiude gli occhi con pietà."
  },
  AvgDialog_118701_Content_70 = {
    Text = "Presto, immergetela nel Refrigerante Neurale!"
  },
  AvgDialog_118701_Content_71 = {
    Text = "L'acqua verde chiaro della vasca le sommerge il petto. Il calore febbrile che emana dal corpo di Ramona finalmente si attenua. I suoi occhi, un tempo razionali e ora al limite dell'ossessione, si aprono lentamente."
  },
  AvgDialog_118701_Content_72 = {
    Text = "Anche con il primo tentativo ufficiale previsto per dopodomani, non puoi rischiare il tuo corpo in questo modo."
  },
  AvgDialog_118701_Content_73 = {
    Text = "Va tutto bene, posso farcela..."
  },
  AvgDialog_118701_Content_74 = {
    Text = "Pollux, che è uscito dallo strumento vicino, si avvicina silenziosamente alle due e interrompe le ulteriori ammonizioni di Doll."
  },
  AvgDialog_118701_Content_75 = {
    Text = "Il dolore di perdere qualcuno senza cui non puoi vivere... l'odio verso te stessa per non aver avuto il potere di salvarlo... sono stato dove sei tu, signorina Ramona."
  },
  AvgDialog_118701_Content_76 = {
    Text = "Riesco già a percepire il richiamo di quella luce brillante. Castor e io faremo del nostro meglio per aiutarti a riportare indietro il nostro benefattore."
  },
  AvgDialog_118701_Content_8 = {
    Text = "Il funerale di <Yellow:%player%> è previsto per domani. Puoi leggere le ultime volontà di %player% per {Male=lui,Female=lei}."
  },
  AvgDialog_118701_Content_9 = {
    Text = [[
Mondo#Kadath
3 mesi dopo il funerale del Custode]]
  },
  AvgDialog_118702_Content_1 = {
    Text = "Messaggio da Lontano"
  },
  AvgDialog_118702_Content_10 = {
    Text = "Non vedendo nulla, agiti le mani e muovi passi disperati, come un viaggiatore che risale la corrente, lottando per avanzare e cercando a tentoni nell'oscurità viscosa."
  },
  AvgDialog_118702_Content_100 = {
    Text = "Nessun calore bruciante, qui. Solo un'Oscurità infinita e viscosa. A poco a poco, l'avanti e l'indietro si dissolvono nell'astrazione, e l'esistenza stessa si dissolve nel nulla."
  },
  AvgDialog_118702_Content_101 = {
    Text = "Continua a camminare. Non voltarti indietro."
  },
  AvgDialog_118702_Content_102 = {
    Text = "Fidandoti di quella voce, svuoti la mente e avanzi, finché un vortice di colori psichedelici ti precipita in una violenta vertigine."
  },
  AvgDialog_118702_Content_103 = {
    Text = "...Quella è...!"
  },
  AvgDialog_118702_Content_104 = {
    Text = "A parte essere il Mare dell'Essenza Primordiale di Daffodil, è la prima volta che ti trovi al di fuori dell'universo, a contemplare il mondo."
  },
  AvgDialog_118702_Content_105 = {
    Text = "È come entrare in un mondo microscopico sotto una lente: una sostanza spaziale gelatinosa, innumerevoli linee guizzanti, Spiriti dalle forme bizzarre e galassie lontane che tremolano ai confini estremi della Visuale..."
  },
  AvgDialog_118702_Content_106 = {
    Text = "...e la frontiera sconfinata dei mondi."
  },
  AvgDialog_118702_Content_107 = {
    Text = "Senza una salda Àncora spirituale, ci si perderebbe facilmente in uno spazio così caotico e sconfinato. Eppure non provi alcuna paura."
  },
  AvgDialog_118702_Content_108 = {
    Text = "Sei pronto? Una volta avviato il collegamento, farò più rumore possibile per attirare la Sua attenzione. Il resto sarà la tua Battaglia."
  },
  AvgDialog_118702_Content_109 = {
    Text = "Stringendo la Chiave d'Argento al petto, con solennità, quasi con tenerezza, protendi i tuoi filamenti spirituali verso la rosa sbocciata che tieni in mano."
  },
  AvgDialog_118702_Content_11 = {
    Text = "Finalmente... ti ho trovato! Noi @3... attraverso il @2 tunnel..."
  },
  AvgDialog_118702_Content_110 = {Text = "Inizio."},
  AvgDialog_118702_Content_111 = {
    Text = "Una grandiosa ondata di energia spirituale erutta nello spazio dimensionale, e all'estremità più remota del tuo filamento spirituale appare un'improvvisa fenditura, che squarcia il tessuto dello spazio."
  },
  AvgDialog_118702_Content_112 = {
    Text = "Dietro la crepa emerge una pupilla gigantesca, come l'occhio di un colosso che si spalanca all'improvviso."
  },
  AvgDialog_118702_Content_12 = {
    Text = "Non riesci a vederla, puoi solo udire la sua voce frammentata. La tua compagna è altrettanto agitata, ed esprime la gioia di un ricongiungimento a lungo atteso."
  },
  AvgDialog_118702_Content_13 = {
    Text = "Sembra che una corda reale ti leghi a Ramona, e seguendo quella corda potrai ritrovare la via di casa."
  },
  AvgDialog_118702_Content_14 = {
    Text = "Mentre avanzi seguendo la guida di quella corda, un fragore improvviso esplode. L'intero spazio trema violentemente per un tremore devastante."
  },
  AvgDialog_118702_Content_15 = {
    Text = "Qualcosa sta attaccando @2! Il Sacro Cuore non reggerà!"
  },
  AvgDialog_118702_Content_16 = {
    Text = "Ramona, disconnetti il collegamento!"
  },
  AvgDialog_118702_Content_17 = {Text = "Ma...!"},
  AvgDialog_118702_Content_18 = {
    Text = "Custode, vai a cercare Daffodil! Non rinunceremo—"
  },
  AvgDialog_118702_Content_19 = {
    Text = "Ogni luce svanisce. Nella distesa remota, un'entità colossale e sconosciuta cambia rotta e scompare gradualmente nel vuoto caotico."
  },
  AvgDialog_118702_Content_2 = {
    Text = "Custode@2... Custode..."
  },
  AvgDialog_118702_Content_20 = {Text = "!!!"},
  AvgDialog_118702_Content_21 = {
    Text = "Ti risvegli di soprassalto nel letto. Muri di mattoni rosso scuro... il tenue odore di disinfettante... Ti rendi conto di essere ancora nella base di Doll: Inferno."
  },
  AvgDialog_118702_Content_22 = {
    Text = "Che succede? Da quando il mio campo di ricerca si è esteso all'analisi dei sogni? Non dovresti parlarne con Clementine?"
  },
  AvgDialog_118702_Content_23 = {
    Text = "Ma hai ragione. Data l'unicità del tuo spirito, sono propensa a credere che non si tratti né di un'allucinazione né di un semplice sogno."
  },
  AvgDialog_118702_Content_24 = {
    Text = "Quanto alla verità, un'altra \"me\" nel tuo sogno te l'ha già rivelata, credo?"
  },
  AvgDialog_118702_Content_25 = {
    Text = "Prende un Nucleo d'Argento che un tempo avevi rubato e lo getta nel Dispositivo di risveglio. Una voluta di foschia viola si leva tra il ronzio dei meccanismi."
  },
  AvgDialog_118702_Content_26 = {
    Text = "Oh, ci rivediamo, miei vecchi clienti."
  },
  AvgDialog_118702_Content_27 = {
    Text = "Daffodil! Io..."
  },
  AvgDialog_118702_Content_28 = {
    Text = "Shh, non c'è bisogno di parlare. Un mercante qualificato comprende sempre i desideri del cliente."
  },
  AvgDialog_118702_Content_29 = {
    Text = "Ho davvero incontrato i tuoi amici."
  },
  AvgDialog_118702_Content_3 = {
    Text = "Ti senti soffocato e avvolto, come se strati di spesso velluto ti premessero addosso. Non riesci a vedere né a muoverti."
  },
  AvgDialog_118702_Content_30 = {Text = "?!"},
  AvgDialog_118702_Content_31 = {
    Text = "Vedendo la tua espressione scioccata, Doll: Inferno alza gli occhi al cielo."
  },
  AvgDialog_118702_Content_32 = {
    Text = "Non avrei dovuto presumere che fossi abbastanza sveglio da capire la chiave della sua forza."
  },
  AvgDialog_118702_Content_33 = {
    Text = "La chiave della sua forza... ?"
  },
  AvgDialog_118702_Content_34 = {
    Text = "Ricordi quel mare grigio colmo di teschi."
  },
  AvgDialog_118702_Content_35 = {
    Text = "Vuoi dire... uno spazio dimensionale? Daffodil può viaggiare tra mondi diversi... Quindi le due Daffodil che ho incontrato sono in realtà la stessa persona?"
  },
  AvgDialog_118702_Content_36 = {
    Text = "Ci sei molto vicino, bambino intelligente. Le due Daffodil sono effettivamente la stessa \"esistenza,\" ma hai dimenticato: noi non siamo umane."
  },
  AvgDialog_118702_Content_37 = {
    Text = "Gli occhi di Daffodil si incurvano con apprezzamento mentre ruota il polso, dando una leggera scossa alla canna fumante."
  },
  AvgDialog_118702_Content_38 = {
    Text = "Noi siamo soltanto volti che emergono sulla superficie del mare; quel Mare di Nebbia Grigia che scorre tra le fessure di tutte le dimensioni è la nostra vera essenza."
  },
  AvgDialog_118702_Content_39 = {
    Text = "Pertanto, le nostre coscienze sono connesse, eppure non siamo la stessa \"persona.\""
  },
  AvgDialog_118702_Content_4 = {
    Text = "In questo sogno di oscurità e vuoto, una voce flebile si increspa come acqua, per poi dissolversi rapidamente."
  },
  AvgDialog_118702_Content_40 = {
    Text = "Quindi, potete viaggiare tra mondi diversi attraverso il Mare dell'Essenza Primordiale? Nel sogno di poco fa, Doll mi ha chiesto di trovarti... Significa che ora hai un modo per riportarmi in quel mondo?"
  },
  AvgDialog_118702_Content_41 = {
    Text = "Non essere ansioso. Come ho già detto, nemmeno io posso compiere facilmente un viaggio dimensionale."
  },
  AvgDialog_118702_Content_42 = {
    Text = "Se davvero avessi un metodo così impeccabile, perché l'avrei tenuto nascosto fino ad ora?"
  },
  AvgDialog_118702_Content_43 = {
    Text = "Sei stordita, e abbassi lentamente il capo."
  },
  AvgDialog_118702_Content_44 = {
    Text = "Tuttavia, questa volta, i tuoi coraggiosi amici hanno trovato una nuova via."
  },
  AvgDialog_118702_Content_45 = {
    Text = "Alzi di scatto la testa, gli occhi che si riaccendono, strappando una dolce risata a Daffodil e uno sbuffo sprezzante a Doll: Inferno."
  },
  AvgDialog_118702_Content_46 = {
    Text = "Dall'ultima volta che ci siamo incontrate in questo mondo, ho parlato loro di te."
  },
  AvgDialog_118702_Content_47 = {
    Text = "Venuti a conoscenza della natura unica di questa dimensione, Doll e i ricercatori dei Mythag hanno lavorato giorno e notte, cercando di localizzare questo mondo. Di recente, hanno trovato un modo per collegare le due dimensioni."
  },
  AvgDialog_118702_Content_48 = {
    Text = "Ciò che hai appena percepito era il risultato del loro Legame riuscito."
  },
  AvgDialog_118702_Content_49 = {
    Text = "Quindi non era un sogno? Quel Legame spirituale è reale?!"
  },
  AvgDialog_118702_Content_5 = {
    Text = "Chi? Chi mi sta chiamando? Quella voce suona così familiare..."
  },
  AvgDialog_118702_Content_50 = {
    Text = "Sì, ma il collasso di quel Legame era altrettanto reale. Dovresti aver notato quell'Avvento improvviso."
  },
  AvgDialog_118702_Content_51 = {
    Text = "Il viaggio dimensionale è estremamente pericoloso. Anche se posso aiutarti a sfuggire ai Segugi infernali, ci sono fin troppi esseri superiori all'interno degli spazi dimensionali."
  },
  AvgDialog_118702_Content_52 = {
    Text = "Ciascuno di essi reclama il proprio Dominio, regnando come Monarca sui propri territori."
  },
  AvgDialog_118702_Content_53 = {
    Text = "Potresti averli evitati in vari modi, ma sfortunatamente, questa volta, colui che ha preso di mira il Tunnel è il tuo Rivale più familiare."
  },
  AvgDialog_118702_Content_54 = {
    Text = "Così familiare... Questa sensazione di essere osservati... Tohuwabohu? Si è risvegliato di nuovo?!"
  },
  AvgDialog_118702_Content_55 = {
    Text = "Non c'è bisogno di tanta tensione. I risultati che hai ottenuto con il tuo Sacrificio non svaniranno così facilmente. Resta immerso in un profondo Dormiveglia."
  },
  AvgDialog_118702_Content_56 = {
    Text = "Ma Tohuwabohu è potente. Tu e il \"Sacro Cuore\" di Pollux siete entrambi troppo appariscenti. Persino nel suo Dormiveglia, il suo subconscio ha preso nota di voi."
  },
  AvgDialog_118702_Content_57 = {
    Text = "L'Espressione di Daffodil si fa insolitamente grave. Resti in silenzio, rievocando la Battaglia che è costata ogni cosa."
  },
  AvgDialog_118702_Content_58 = {
    Text = "Per fortuna, il disturbo causato da questo viaggio dimensionale è molto più contenuto del trambusto provocato da Juliette l'ultima volta. Lo Sguardo proiettato dal suo subconscio non è sufficiente a Distruggere il mondo intero."
  },
  AvgDialog_118702_Content_59 = {
    Text = "Ciononostante, quel Potere è più di quanto l'Awakener inviato a fare Recupero possa Sopportare. Per forgiare un collegamento dimensionale Completo e stabile, affidarsi unicamente all'altro lato non basterà."
  },
  AvgDialog_118702_Content_6 = {
    Text = "Custode... %player%!"
  },
  AvgDialog_118702_Content_60 = {
    Text = "<Yellow:%player%>, abbiamo bisogno che tu attiri la sua attenzione qui e lo respinga, facendo così da Scudo del Personaggio ai tuoi amici nell'altro mondo mentre aprono un Tunnel."
  },
  AvgDialog_118702_Content_61 = {
    Text = "Lo Sguardo di Tohuwabohu... Dovrò affrontarlo... di nuovo..."
  },
  AvgDialog_118702_Content_62 = {
    Text = "La Battaglia sembra così lontana, come una Storia di una vita passata."
  },
  AvgDialog_118702_Content_63 = {
    Text = "Eppure, sembra anche così vicina — abbastanza da permetterti di ricordare ogni dettaglio con facilità."
  },
  AvgDialog_118702_Content_64 = {
    Text = "Ricordi ogni Ferita atroce, ogni vittoria conquistata a caro prezzo, ogni brivido di paura, ogni grido disperato sulla Soglia della Morte..."
  },
  AvgDialog_118702_Content_65 = {
    Text = "Contemplare la Volontà suprema ti costò un tempo tutto il tuo coraggio e la tua vita. Rievocando quegli sguardi che trascendono ogni regola, la tua voce inizia a tremare in modo incontrollabile."
  },
  AvgDialog_118702_Content_66 = {
    Text = "Anche un semplice sguardo proiettato dal suo subconscio... il suo Potere potrebbe ancora superare la mia capacità di resistere."
  },
  AvgDialog_118702_Content_67 = {
    Text = "Ora non posso sfruttare appieno il Potere dei tre Eoni, né dispongo dell'aiuto dei miei compagni da altre Dimensioni. Come posso fermarlo di nuovo..."
  },
  AvgDialog_118702_Content_68 = {
    Text = "Cosa, hai paura, nostra coraggiosa Custode?"
  },
  AvgDialog_118702_Content_69 = {
    Text = "Stringi i pugni, scuoti la testa e guardi Daffodil con serietà."
  },
  AvgDialog_118702_Content_7 = {Text = "Ramona?!"},
  AvgDialog_118702_Content_70 = {
    Text = "Finché potrò tornare indietro, nessuna paura potrà fermarmi. Temo solo che la mia Abilità attuale sia insufficiente."
  },
  AvgDialog_118702_Content_71 = {
    Text = "Se dovessi fallire, potrebbe risvegliarsi di nuovo... una catastrofe che nessuno avrebbe la capacità di Sopportare."
  },
  AvgDialog_118702_Content_72 = {
    Text = "Bene. Sembra che il nostro Custode non abbia ancora perso il coraggio di opporsi al dio."
  },
  AvgDialog_118702_Content_73 = {
    Text = "Non preoccuparti, <Yellow:%player%>. Questa volta ti aiuterò a eliminare le Barriere tra le Dimensioni, disperdendo il suo Potere in altri mondi."
  },
  AvgDialog_118702_Content_74 = {
    Text = "L'ultima volta, Custodi da altre Dimensioni hanno combattuto al tuo fianco. Questa volta, combatteranno ancora la stessa Battaglia con te — anche se non potrai vederli."
  },
  AvgDialog_118702_Content_75 = {
    Text = "Davvero?! Allora io... no, noi saremo sicuramente in grado di trattenerLa ancora una volta!"
  },
  AvgDialog_118702_Content_76 = {
    Text = "Ciononostante, una battaglia di tale portata devasterebbe l'intero mondo qui presente. Nessuno qui possiede la capacità di affrontarLa, a parte <Yellow:%player%>."
  },
  AvgDialog_118702_Content_77 = {
    Text = "Esattamente. Perciò questa battaglia deve avere luogo nello spazio dimensionale. Quanto a come trattenere <Yellow:%player%> là per un periodo prolungato... avremo bisogno dell'assistenza di un genio."
  },
  AvgDialog_118702_Content_78 = {
    Text = "Per favore! Doll: Inferno!"
  },
  AvgDialog_118702_Content_79 = {
    Text = "Hmph... Con quanta disinvoltura hai orchestrato ogni cosa."
  },
  AvgDialog_118702_Content_8 = {
    Text = "Non appena pronunci quel nome, una barriera invisibile si frantuma all'istante. Un legame caldo e intimo attraversa innumerevoli linee temporali, trasformandosi in un filo bianco e scintillante che ti sfiora il petto."
  },
  AvgDialog_118702_Content_80 = {
    Text = "Ma sia — ti ho promesso di riportarti a casa. Manterrò la mia promessa, mio piccolo cucciolo."
  },
  AvgDialog_118702_Content_81 = {Text = "Grazie!"},
  AvgDialog_118702_Content_82 = {
    Text = "Risparmia la gratitudine. Sia chiaro: posso solo ancorare la tua coscienza nello spazio dimensionale, e farò del mio meglio per riportarti qui ogni volta che avrai bisogno di me."
  },
  AvgDialog_118702_Content_83 = {
    Text = "Ricorda. Potresti comunque fallire, o persino morire combattendo contro di Lei."
  },
  AvgDialog_118702_Content_84 = {
    Text = "Non sono ottimista riguardo a questo piano impulsivo. Ciononostante, sei disposto a correre un tale rischio per un esito ignoto?"
  },
  AvgDialog_118702_Content_85 = {
    Text = "Lo sono. Loro hanno corso gli stessi rischi per me, e ho ogni ragione di ricambiare. Anche se siamo in mondi diversi, stiamo ancora combattendo fianco a fianco, come facevamo un tempo."
  },
  AvgDialog_118702_Content_86 = {
    Text = "Doll: Inferno annuisce senza sorpresa, e Daffodil ti guarda, sorridendo, come se non avesse mai contemplato la possibilità che tu potessi esitare."
  },
  AvgDialog_118702_Content_87 = {
    Text = "Capito. Un giuramento così sdolcinato è meglio riservarlo ai tuoi compagni. Ho bisogno di un po' di tempo per prepararmi, e presumo che abbiate già un metodo per coordinare il momento d'inizio dell'operazione?"
  },
  AvgDialog_118702_Content_88 = {
    Text = "In risposta alla domanda di Doll: Inferno, Daffodil volge lo sguardo verso di te."
  },
  AvgDialog_118702_Content_89 = {
    Text = "Certo, la tua compagna mi ha chiesto di consegnarti un dono."
  },
  AvgDialog_118702_Content_9 = {
    Text = "Questo è... un legame spirituale?! Ramona, sei tu? Dove sei?"
  },
  AvgDialog_118702_Content_90 = {
    Text = "Tra volute di nebbia, una rosa, apparentemente materializzata dal nulla, ti viene porta."
  },
  AvgDialog_118702_Content_91 = {
    Text = "Questa è... quella che mi ha dato Ramona...?!"
  },
  AvgDialog_118702_Content_92 = {
    Text = "Mi rammarico di non possedere ancora il potere di trasmettere oggetti fisici attraverso le dimensioni."
  },
  AvgDialog_118702_Content_93 = {
    Text = "Eppure in queste due realtà, ogni cosa ha la propria controparte."
  },
  AvgDialog_118702_Content_94 = {
    Text = "Questa rosa corrisponde a quella che Ramona ti ha donato in quel mondo."
  },
  AvgDialog_118702_Content_95 = {
    Text = "Ho apportato una piccola modifica a questo fiore. Quando sarai pronto, non dovrai far altro che collegare il tuo spirito ad esso. I nostri alleati dall'altra parte riceveranno il segnale."
  },
  AvgDialog_118702_Content_96 = {
    Text = "Ramona ha detto che appunterà questa rosa al tuo petto lei stessa, quando vi rincontrerete."
  },
  AvgDialog_118702_Content_97 = {Text = "..."},
  AvgDialog_118702_Content_98 = {
    Text = "Per la prima volta, ti rendi conto che il passaggio usato da Doll: Inferno per lasciare il mondo è il sole scomparso sospeso in alto."
  },
  AvgDialog_118702_Content_99 = {
    Text = "Il vuoto nero pece del sole somiglia a una ferita inguaribile del mondo. Mentre la tua coscienza vi si lascia trascinare, hai la sensazione di strisciare dentro il Petto Vuoto di un gigante."
  },
  AvgDialog_118703_Content_1 = {
    Text = "Punte delle dita ricurve"
  },
  AvgDialog_118703_Content_10 = {
    Text = "Uno strido lacerante, che non appartiene a nessuna creatura né dimensione, risuona direttamente dalle profondità della tua coscienza, quasi lacerandoti la mente."
  },
  AvgDialog_118703_Content_100 = {
    Text = "Ugh! La mia testa... fa così male..."
  },
  AvgDialog_118703_Content_101 = {
    Text = "Gli strumenti di collegamento sono quasi completamente danneggiati. È praticamente un Miracolo che tu sia tornato vivo."
  },
  AvgDialog_118703_Content_102 = {
    Text = "Ma questo luogo ha già assistito a troppi miracoli. Forse per la Pozza nera, la teoria della probabilità è di per sé una fallacia."
  },
  AvgDialog_118703_Content_103 = {
    Text = "Hai fatto bene, Ramona. Ma non farlo mai più."
  },
  AvgDialog_118703_Content_104 = {
    Text = "Stia tranquillo, Professor Doll... so cosa sto facendo."
  },
  AvgDialog_118703_Content_105 = {
    Text = "Per %player%, poter rivedere te è forse più importante di molte altre cose."
  },
  AvgDialog_118703_Content_106 = {
    Text = "Purtroppo, non hai udito le {Male=sue,Female=sue} ultime parole."
  },
  AvgDialog_118703_Content_107 = {
    Text = "No, Lady Daffodil. Ho già sentito ciò che {Male=lui,Female=lei} ha detto..."
  },
  AvgDialog_118703_Content_108 = {
    Text = "Ramona si alza debolmente e, con un sorriso, cammina verso il vuoto evanescente della Pozza nera."
  },
  AvgDialog_118703_Content_109 = {
    Text = "L'Abisso crolla nei Suoi Occhi — da un'entità immensa che divora ogni cosa, a un portale che separa le Dimensioni, poi a una fenditura simile al vuoto, finché non scompare del tutto."
  },
  AvgDialog_118703_Content_11 = {
    Text = "Crolli in ginocchio, stringendoti le orecchie con forza, sentendo il sangue colare incontrollabilmente dai tuoi occhi..."
  },
  AvgDialog_118703_Content_110 = {
    Text = "La Mano di Ramona sfiora delicatamente il punto in cui l'Abisso esisteva un tempo, quel corpo martoriato."
  },
  AvgDialog_118703_Content_111 = {
    Text = "Lei sorride, come se vedesse il proprietario di quel corpo stagliarsi davanti a lei in un futuro prossimo, proprio come in un qualsiasi giorno ordinario a Mythag."
  },
  AvgDialog_118703_Content_112 = {
    Text = "Ti ho sentito, Custode... Lo realizzeremo. <Blue:Ci Rincontreremo.>"
  },
  AvgDialog_118703_Content_113 = {
    Text = "Ti aspetto, %player%."
  },
  AvgDialog_118703_Content_12 = {
    Text = "<Shake:Huff... huff...>"
  },
  AvgDialog_118703_Content_13 = {
    Text = "È... finita?"
  },
  AvgDialog_118703_Content_14 = {
    Text = "Lo strido agonizzante è svanito senza che te ne accorgessi. Alzi la testa. Nella fragile dimensione illusoria, quella presenza terrificante e agghiacciante è scomparsa da tempo."
  },
  AvgDialog_118703_Content_15 = {
    Text = "Hai vinto. Il suo subconscio è stato reciso da questo luogo; l'ultimo occhio gigante si è dissolto nella dimensione."
  },
  AvgDialog_118703_Content_16 = {
    Text = "Sforzandoti di stabilizzare la tua mente completamente esaurita, quasi istintivamente ti volti indietro."
  },
  AvgDialog_118703_Content_17 = {Text = "Crack—"},
  AvgDialog_118703_Content_18 = {
    Text = "Un faint, cristallino frantumarsi giunge alle tue orecchie. Vedi il tunnel dimensionale incrinarsi come una ragnatela, e la forma spirituale di Ramona inizia a tremolare come un vecchio televisore."
  },
  AvgDialog_118703_Content_19 = {
    Text = "<Big:<Shake:Ramona!!!>>"
  },
  AvgDialog_118703_Content_2 = {
    Text = "Ancora... solo un po'...!"
  },
  AvgDialog_118703_Content_20 = {
    Text = "Il tuo corpo a lungo esaurito sembra guarire in un istante. Senza più curarti di nient'altro, voli al suo fianco, afferrandole le mani con un tremito."
  },
  AvgDialog_118703_Content_21 = {
    Text = "Io... sto bene..."
  },
  AvgDialog_118703_Content_22 = {
    Text = "La tua compagna sorride come al solito. Ti stringe la mano più forte, proseguendo con il piano originale come se nulla fosse accaduto."
  },
  AvgDialog_118703_Content_23 = {
    Text = "L'hai sconfitto. Vieni, seguimi. Ti riporterò indietro."
  },
  AvgDialog_118703_Content_24 = {
    Text = "Ti guida, proprio come fa sempre durante le missioni.\nTuttavia, una voce più razionale interviene, quasi freddamente."
  },
  AvgDialog_118703_Content_25 = {
    Text = "Ramona, il tunnel dimensionale è in frantumi. La tua forma spirituale non può più mantenere il tunnel. Se continui così, rischi la morte cerebrale."
  },
  AvgDialog_118703_Content_26 = {
    Text = "Questo salvataggio... è fallito. Devi tornare immediatamente. Attiverò la modalità di richiamo del dispositivo di separazione per riportare il tuo spirito nel tuo corpo."
  },
  AvgDialog_118703_Content_27 = {
    Text = "<Big:Non me ne vado!>"
  },
  AvgDialog_118703_Content_28 = {
    Text = "È la prima volta che vedi questa persona sempre calma gridare con tanta disperazione. Lei inspira profondamente, poi ti mostra un sorriso più naturale."
  },
  AvgDialog_118703_Content_29 = {
    Text = "Ce la posso ancora fare, <Yellow:%player%>. Ultimamente mi sono allenata così tanto; il mio potere spirituale è cresciuto. Doll non conosce i miei veri limiti."
  },
  AvgDialog_118703_Content_3 = {
    Text = "Quando il tuo spirito è sull'orlo dell'esaurimento, anche lo sguardo del Supremo inizia a vacillare per la debolezza."
  },
  AvgDialog_118703_Content_30 = {
    Text = "Non rinunciare, riproviamo, solo un piccolo tentativo, va bene?"
  },
  AvgDialog_118703_Content_31 = {
    Text = "Ti sta supplicando."
  },
  AvgDialog_118703_Content_32 = {Text = "..."},
  AvgDialog_118703_Content_33 = {
    Text = "Non riesci a parlare."
  },
  AvgDialog_118703_Content_34 = {
    Text = "Perché affannarsi tanto? Che ne dite se catturo il suo spirito e lo colloco in uno dei miei corpi meticolosamente forgiati? Così potrà restare di nuovo al fianco di <Yellow:%player%>."
  },
  AvgDialog_118703_Content_35 = {
    Text = "Doll: Inferno, che si era goduta lo spettacolo con immenso piacere, si inserisce anch'essa nel canale di comunicazione, lasciando sfuggire una risata cinica."
  },
  AvgDialog_118703_Content_36 = {
    Text = "Sciocchezze. Sappiamo entrambi che non tutti possono sostenere la Separazione Spirituale per lunghi periodi come <Yellow:%player%>. Altrimenti, non ci troveremmo a trasportare vasche di cervelli rosa ogni giorno."
  },
  AvgDialog_118703_Content_37 = {
    Text = "Va tutto bene, Ramona. La prossima volta, quando ti sarai riposata, aspetterò che tu venga a prendermi."
  },
  AvgDialog_118703_Content_38 = {
    Text = "Fissi la figura trasparente che sembra svanire, sorridi dolcemente e nascondi tutta la tua nostalgia per il Focolare."
  },
  AvgDialog_118703_Content_39 = {
    Text = "Non è così semplice. Questa \"via\" è già stata scoperta da Esso. Se venisse usata di nuovo, attirerebbe soltanto un controllo ancora più intenso."
  },
  AvgDialog_118703_Content_4 = {
    Text = "Questo è un campo di battaglia di volontà. Come una bestia morente, evochi ogni ultimo briciolo delle tue forze, spremendo le ultime gocce di potere dal tuo mondo mentale inaridito."
  },
  AvgDialog_118703_Content_40 = {
    Text = "Doll: Inferno frantuma spietatamente la tua Illusione, mentre Doll dall'altra parte resta in silenzio."
  },
  AvgDialog_118703_Content_41 = {
    Text = "<Shake:Siamo arrivati fin qui. Questa volta, adesso, voglio riportarti indietro.>"
  },
  AvgDialog_118703_Content_42 = {
    Text = "Anche le mani di Ramona cominciano a tremare. Inspiri lentamente e le dai un colpetto sulla Mano, fingendo di essere rilassato."
  },
  AvgDialog_118703_Content_43 = {
    Text = "Ramona, ricordi la prima volta che ci siamo incontrati?"
  },
  AvgDialog_118703_Content_44 = {
    Text = "Ramona annuisce, poi scuote la testa, guardandoti con uno Sguardo quasi implorante. Tu semplicemente chiudi gli occhi e continui a parlare con deliberata crudeltà."
  },
  AvgDialog_118703_Content_45 = {
    Text = "Fu davvero un disastro orribile. Dopo l'esplosione, riesco solo a ricordare vagamente che tutto intorno a me si trasformò in macerie con un boato assordante. Quando aprii gli occhi, credetti di essere arrivato in paradiso."
  },
  AvgDialog_118703_Content_46 = {
    Text = "La luce accecante del sole filtrava attraverso le Pietre scavate, e poi c'era la tua Mano, tesa verso di me."
  },
  AvgDialog_118703_Content_47 = {
    Text = "In quel momento mi chiedevo: l'abito dell'angelo è così strano? È un'uniforme così antiquata. Non avrei mai immaginato che presto avrei indossato la stessa uniforme anch'io."
  },
  AvgDialog_118703_Content_48 = {
    Text = "Ramona vorrebbe dire qualcos'altro, ma tu la interrompi. Cominci a divagare come un Anziano perso nelle Memorie."
  },
  AvgDialog_118703_Content_49 = {
    Text = "Dopo che mi hai tirato fuori, ti ho sempre considerata la persona più gentile del mondo, ma dopo essere arrivato a Mythag, ho capito di essere stato enormemente raggirato."
  },
  AvgDialog_118703_Content_5 = {
    Text = "Con mani tremanti, sollevi in alto la Chiave d'Argento."
  },
  AvgDialog_118703_Content_50 = {
    Text = "Quando iniziai il corso preparatorio, dicesti che eri la mia compagna e che mi avresti aiutato con tutti i problemi della vita e dello studio. Ti credetti."
  },
  AvgDialog_118703_Content_51 = {
    Text = "In effetti, risolvesti i miei problemi — risolvendo la fonte del problema: <Shake:me>."
  },
  AvgDialog_118703_Content_52 = {
    Text = "Si scoprì che la mia cosiddetta compagna era in realtà la mia più grande aguzzina. In quell'anno di corso preparatorio, fosti tu la più severa con me."
  },
  AvgDialog_118703_Content_53 = {
    Text = "Non solo mi sorvegliavi in classe come compagna di banco, ma mi controllavi anche quando facevo i compiti dopo le lezioni. A volte, dopo l'allenamento fisico, non mi concedevi nemmeno un piatto di fish and chips. Fu davvero spregevole."
  },
  AvgDialog_118703_Content_54 = {
    Text = "L'Espressione silenziosa e addolorata di Ramona si incrina per un istante, e l'angolo della sua bocca si curva involontariamente verso l'alto."
  },
  AvgDialog_118703_Content_55 = {
    Text = "Ma, mia cara compagna, sei stata anche tu quella che si è presa più cura di me."
  },
  AvgDialog_118703_Content_56 = {
    Text = "Il Leoniano che non riuscivo a parlare, la pressione degli esami che mi faceva impazzire, i compiti che non riuscivo a completare... ogni volta che ero triste, potevo sempre rivolgermi alla mia onnipotente compagna."
  },
  AvgDialog_118703_Content_57 = {
    Text = "Ti ricordi la prima volta che vidi uno studente sacrificarsi durante una missione? Quella notte non riuscii a dormire, mi rigiravo nel letto, e sgattaiolai fino alla tua porta per bussare."
  },
  AvgDialog_118703_Content_58 = {
    Text = "Poi mi trascinasti in cima alla torre dell'orologio. Faticai ad arrampicarmi sul tetto insieme a te, e restammo semplicemente seduti fianco a fianco a guardare le stelle."
  },
  AvgDialog_118703_Content_59 = {
    Text = "Tu e io parlammo a lungo, di tante cose. Fu la prima volta che capii che nemmeno tu sapevi com'erano tua madre e la tua infanzia."
  },
  AvgDialog_118703_Content_6 = {
    Text = "Questa sarà... la fine!"
  },
  AvgDialog_118703_Content_60 = {
    Text = "Il mio cuore, che si era sempre sentito un po' solo e smarrito, all'improvviso trovò pace."
  },
  AvgDialog_118703_Content_61 = {
    Text = "Pensai che, anche se non avevo una famiglia, questa potesse essere l'unica persona al mondo che mi trattava così bene e mi somigliava tanto, qualcuno che sembrava famiglia."
  },
  AvgDialog_118703_Content_62 = {
    Text = "Ti feci una promessa col mignolo: da quel momento in poi avrei fatto i compiti seriamente, seguito le lezioni seriamente e portato a termine le missioni seriamente."
  },
  AvgDialog_118703_Content_63 = {
    Text = "Da allora, iniziai a considerare Mythag il mio vero focolare. E così, missione dopo missione, incontrai tanti Risvegliati e un nuovo membro della famiglia dopo l'altro."
  },
  AvgDialog_118703_Content_65 = {
    Text = "Quindi grazie, grazie per essere venuti a prendermi, famiglia mia."
  },
  AvgDialog_118703_Content_66 = {
    Text = "So che devi aver provato per molto tempo e fatto enormi sforzi."
  },
  AvgDialog_118703_Content_67 = {
    Text = "Allora vieni con me, posso sicuramente riportarti indietro."
  },
  AvgDialog_118703_Content_68 = {
    Text = "Sorridi ancora guardando le lacrime che scorrono sulle guance di Ramona, ma un liquido rovente scivola incontrollabile anche sul tuo volto."
  },
  AvgDialog_118703_Content_69 = {
    Text = "Guardandola diventare traslucida e tremolare mentre il suo spirito raggiunge il limite, scuoti dolcemente la testa."
  },
  AvgDialog_118703_Content_7 = {
    Text = "Una luce argentea abbagliante sboccia nella tua mano, il suo fulgore argentato illumina l'intera dimensione illusoria."
  },
  AvgDialog_118703_Content_70 = {
    Text = "È ora, Ramona."
  },
  AvgDialog_118703_Content_71 = {Text = "No, no..."},
  AvgDialog_118703_Content_72 = {
    Text = "Ramona sapeva che questo momento sarebbe arrivato. Scuote la testa disperatamente, le sue mani evanescenti stringono con forza la tua forma spirituale."
  },
  AvgDialog_118703_Content_73 = {
    Text = "Tornerò da te. Te lo prometto."
  },
  AvgDialog_118703_Content_74 = {
    Text = "Ci rincontreremo... a qualunque costo."
  },
  AvgDialog_118703_Content_75 = {
    Text = "Ritiri dolcemente la mano da quella stretta familiare e lasci andare."
  },
  AvgDialog_118703_Content_76 = {
    Text = "Doll, dall'altro capo della comunicazione, riceve il segnale. Una sensazione familiare pervade lo spirito di Ramona — lo strumento la sta trascinando via. Sa che deve andarsene."
  },
  AvgDialog_118703_Content_77 = {
    Text = "\"Una promessa\", eh... Proprio come la prima volta, quando varcasti la Porta... Non ci credi nemmeno tu, vero?"
  },
  AvgDialog_118703_Content_78 = {
    Text = "Sei davvero una persona senza cuore..."
  },
  AvgDialog_118703_Content_79 = {
    Text = "Ramona, io..."
  },
  AvgDialog_118703_Content_8 = {
    Text = "<Shake:@2@4@3!!—>"
  },
  AvgDialog_118703_Content_80 = {
    Text = "Il Codice dell'Investigatore... le promesse fatte vanno mantenute."
  },
  AvgDialog_118703_Content_81 = {
    Text = "Io ti credo. Anche se mi mentirai innumerevoli volte, anche se nemmeno tu crederai a te stesso, io ti crederò sempre."
  },
  AvgDialog_118703_Content_82 = {
    Text = "Su quel volto dove lacrime e sorriso si intrecciano, le pupille di Ramona si fissano nelle tue, lottando per incidere il tuo viso nella sua memoria."
  },
  AvgDialog_118703_Content_83 = {
    Text = "Nell'ultimo istante in cui il suo spirito viene richiamato al corpo, tende la mano verso di te con tutte le forze ancora una volta."
  },
  AvgDialog_118703_Content_84 = {
    Text = "Proprio come in quel momento di tanto tempo fa sotto il cielo stellato, lei tese il mignolo e lo agganciò delicatamente alla punta del tuo dito."
  },
  AvgDialog_118703_Content_85 = {
    Text = "Manterrai la tua promessa, vero?"
  },
  AvgDialog_118703_Content_86 = {
    Text = "Non attende la tua risposta. L'istante successivo, la sua figura illusoria si dissolve insieme al Tunnel dimensionale, trasformandosi in frammenti residui dispersi che svaniscono lentamente, senza lasciare traccia."
  },
  AvgDialog_118703_Content_87 = {Text = "..."},
  AvgDialog_118703_Content_88 = {Text = "..."},
  AvgDialog_118703_Content_89 = {
    Text = "Respirazione normale. Frequenza cardiaca normale. Forza mentale sotto il livello di Allerta... in fase di recupero."
  },
  AvgDialog_118703_Content_9 = {Text = "Ah—"},
  AvgDialog_118703_Content_90 = {
    Text = "Sopravvivere dopo aver prosciugato la forza mentale a quel modo... sei davvero un cucciolo tenace."
  },
  AvgDialog_118703_Content_91 = {
    Text = "Che bello spettacolo. Peccato non aver potuto vedere il dio che hai richiamato distruggere questo mondo. Il finale non è stato abbastanza spettacolare."
  },
  AvgDialog_118703_Content_92 = {
    Text = "Non preoccuparti... ti ho detto che Lo avrei trattenuto in un'altra Dimensione. Non farò mai più una promessa non mantenuta."
  },
  AvgDialog_118703_Content_93 = {
    Text = "Conserva quelle parole per dirglielo di persona quando tornerai."
  },
  AvgDialog_118703_Content_94 = {
    Text = "Dato che ho scelto di percorrere questa strada con tutti voi, voglio vedere fin dove riuscirete ad arrivare."
  },
  AvgDialog_118703_Content_95 = {
    Text = "Riposati bene, e poi prosegui il tuo cammino, cucciolo."
  },
  AvgDialog_118703_Content_96 = {
    Text = "Sentendo il Calore Residuo sulla punta del dito, stringi lentamente il mignolo che poco prima era intrecciato al suo, premendolo con forza contro il petto."
  },
  AvgDialog_118703_Content_97 = {
    Text = "Verso quello spazio dimensionale vasto e solitario, verso quella figura svanita, sussurri la promessa che sei determinato a mantenere."
  },
  AvgDialog_118703_Content_98 = {
    Text = "Anche se ora non puoi sentirmi... manterrò la mia promessa. Aspettami, Ramona!"
  },
  AvgDialog_118703_Content_99 = {Text = "..."},
  AvgDialog_118944_Content_1 = {
    Text = "Dopo aver sconfitto l'ultimo Navigatore deforme, vi avvicinate con cautela alla bambina nell'angolo, combattendo per aprirvi un varco."
  },
  AvgDialog_118944_Content_10 = {
    Text = "William tenta di sollevare la schiusa che conduce alla cabina inferiore, ma per quanto si sforzi, la schiusa non si muove."
  },
  AvgDialog_118944_Content_11 = {
    Text = "No, è stata sigillata dal basso!"
  },
  AvgDialog_118944_Content_12 = {
    Text = "Lo scafo emette un gemito agghiacciante mentre lotta e, tenace, inizia a virare, lanciandosi verso le acque più oscure, dove le tempeste sono più fitte, tra le onde torreggianti."
  },
  AvgDialog_118944_Content_13 = {
    Text = "Miryam apre le braccia, abbracciando questa rotta distruttiva. Un sorriso di tenerezza quasi materna le appare sul volto."
  },
  AvgDialog_118944_Content_14 = {
    Text = "Il rito sta per giungere alla fine."
  },
  AvgDialog_118944_Content_15 = {
    Text = "Sei arrivato a una conclusione?"
  },
  AvgDialog_118944_Content_16 = {
    Text = "Nel mezzo della tempesta e del caos, nessuno riesce a discernere la posizione di tutti..."
  },
  AvgDialog_118944_Content_17 = {
    Text = "Se solo ci fosse un'altra piccola imbarcazione..."
  },
  AvgDialog_118944_Content_18 = {
    Text = "Innumerevoli indizi si accesero nella tua mente..."
  },
  AvgDialog_118944_Content_19 = {
    Text = "Le guardie negli alloggi."
  },
  AvgDialog_118944_Content_2 = {
    Text = "Murphy, vieni con me!"
  },
  AvgDialog_118944_Content_20 = {
    Text = "Il rito di navigazione sul ponte."
  },
  AvgDialog_118944_Content_21 = {
    Text = "L'esplosione nella sala macchine."
  },
  AvgDialog_118944_Content_22 = {
    Text = "La scialuppa di salvataggio nella cabina inferiore."
  },
  AvgDialog_118944_Content_23 = {
    Text = "I punti di luce si collegarono, si intrecciarono e si estesero... convergendo infine in una definitiva via di fuga."
  },
  AvgDialog_118944_Content_24 = {
    Text = "William annuisce."
  },
  AvgDialog_118944_Content_25 = {
    Text = "Dato che avete trovato la risposta, l'obiettivo di questo ciclo è raggiunto. Non c'è motivo di rimpianto."
  },
  AvgDialog_118944_Content_26 = {
    Text = "Secondo lo schema che avete descritto, la nave sta per iniziare ad affondare."
  },
  AvgDialog_118944_Content_27 = {
    Text = "Sei pronto?"
  },
  AvgDialog_118944_Content_28 = {
    Text = "La marea vi ha già divorato il petto. Stringete delicatamente la Chiave d'Argento al vostro petto, sussurrando parole d'addio."
  },
  AvgDialog_118944_Content_29 = {
    Text = "Ci vediamo nel prossimo ciclo, William."
  },
  AvgDialog_118944_Content_3 = {
    Text = "Sussulta. Il suo sguardo, sfocato, fatica a fissarsi sul vostro volto."
  },
  AvgDialog_118944_Content_30 = {
    Text = "Che la Chiave d'Argento Illumini il Cammino."
  },
  AvgDialog_118944_Content_4 = {
    Text = "No, è inutile, è tutto un'illusione... Che si avanzi o si arretri, è tutto..."
  },
  AvgDialog_118944_Content_5 = {
    Text = "Finché non sarà l'ultimo istante, non rinunciare a tentare! Anche se questa volta fallirò, ti prenderò per mano ancora una volta!"
  },
  AvgDialog_118944_Content_6 = {Text = "..."},
  AvgDialog_118944_Content_7 = {
    Text = "Murphy ti fissa con lo sguardo vuoto."
  },
  AvgDialog_118944_Content_8 = {
    Text = "Le afferrate il polso con presa salda ma gentile, trascinandola fuori da quell'angolo di disperazione."
  },
  AvgDialog_118944_Content_9 = {
    Text = "C'è una via di fuga, Senior William?"
  },
  AvgDialog_118945_Content_1 = {
    Text = "Piccola, ti sei trattenuta durante la Battaglia."
  },
  AvgDialog_118945_Content_10 = {
    Text = "Alcuni commettono atrocità per sopravvivere quando ogni altro Sentiero è precluso."
  },
  AvgDialog_118945_Content_11 = {
    Text = "Alcuni selezionano gli altri secondo le proprie convinzioni per costruire il nuovo mondo che immaginano."
  },
  AvgDialog_118945_Content_12 = {
    Text = "E alcuni, puramente per il loro crudele divertimento, sono disposti a capovolgere il mondo e creare tumulto senza fine."
  },
  AvgDialog_118945_Content_13 = {
    Text = "Attendi e aspetti con ansia la sua risposta, rievocando il Sogno lontano del Sentiero che lei ha percorso."
  },
  AvgDialog_118945_Content_14 = {
    Text = "Miryam, ora in preda alla follia, era un tempo una Bambina che, durante il Cataclisma, si dedicò alla Missione del Sacerdote per proteggere la sua unica famiglia."
  },
  AvgDialog_118945_Content_15 = {
    Text = "Miryam non risponde direttamente alla tua Domanda. Invece, congiunge le mani e prega rivolta verso l'orizzonte lontano."
  },
  AvgDialog_118945_Content_16 = {
    Text = "\"I perduti, Egli li guida...\""
  },
  AvgDialog_118945_Content_17 = {
    Text = "\"Gli anelanti, Egli risponde.\""
  },
  AvgDialog_118945_Content_18 = {
    Text = "Come se avesse ricevuto l'approvazione del mare, socchiude i suoi vacui Occhi nero-violacei."
  },
  AvgDialog_118945_Content_19 = {
    Text = "Sono venuta a rianimare il Reame Divino, per riportare la gloria di Dio nel mondo."
  },
  AvgDialog_118945_Content_2 = {
    Text = "Per me, questa conversazione con Miryam è ben più importante che vincere contro di te."
  },
  AvgDialog_118945_Content_20 = {
    Text = "Dunque, quando Lemuria sarà ricostituita nel mondo, che genere di mondo ti aspetti di vedere?"
  },
  AvgDialog_118945_Content_21 = {
    Text = "\"Nel Suo Lungo Sogno, condividiamo pace e felicità eterne.\""
  },
  AvgDialog_118945_Content_22 = {
    Text = "La gloria di Lemuria è tornata, proprio come ti fu inculcato durante la tua Vita."
  },
  AvgDialog_118945_Content_23 = {
    Text = "Non hai mai assistito a un giorno di tale prosperità. Sai davvero come crearlo?"
  },
  AvgDialog_118945_Content_24 = {
    Text = "\"La Sua Divina Volontà guiderà i fedeli sul Sentiero verso Lemuria.\""
  },
  AvgDialog_118945_Content_25 = {
    Text = "Il te di questo mondo non è davvero diverso da ciò che avevo percepito."
  },
  AvgDialog_118945_Content_26 = {
    Text = "Dunque, in questo momento in cui il tuo dio è già nato, perché ti aggrappi ancora a Murphy?"
  },
  AvgDialog_118945_Content_3 = {
    Text = "Se riuscissi a far emergere una momentanea vulnerabilità in Miryam, il Dominio potrebbe incrinarsi e rivelare il suo \"nucleo\" nascosto..."
  },
  AvgDialog_118945_Content_4 = {
    Text = "Avrai l'occasione di porre fine definitivamente a questo Sogno artificiale in cui sei Intrappolato."
  },
  AvgDialog_118945_Content_5 = {
    Text = "Molto bene. Hai dimostrato la tua Determinazione. Ora dichiara il tuo scopo."
  },
  AvgDialog_118945_Content_6 = {
    Text = "Ho una Domanda."
  },
  AvgDialog_118945_Content_7 = {
    Text = "Miryam, perché vuoi rianimare il Reame Divino?"
  },
  AvgDialog_118945_Content_8 = {
    Text = "Hai posto una Domanda molto interessante."
  },
  AvgDialog_118945_Content_9 = {
    Text = "Durante il mio viaggio per affrontare la Dissoluzione, ho incontrato molte persone."
  },
  AvgDialog_118946_Content_1 = {Text = "La Fuga"},
  AvgDialog_118946_Content_10 = {
    Text = "Solleva le dita pallide e fa girare nuovamente la ruota del filatoio."
  },
  AvgDialog_118946_Content_100 = {
    Text = "Finché l'Oscurità non inghiottirà il tuo mondo."
  },
  AvgDialog_118946_Content_11 = {
    Text = "Anche se ancora non conosco il tuo nome, ti prego, benedicimi, straniera."
  },
  AvgDialog_118946_Content_12 = {
    Text = "Uno stormo di uccelli sfreccia, sollevando ondate di piume bianche.\n\nDopo che le onde si ritirarono, anche la donna svanì."
  },
  AvgDialog_118946_Content_13 = {
    Text = "Esponi rapidamente a William il piano generale."
  },
  AvgDialog_118946_Content_14 = {
    Text = "Sembra un piano per vincere nel mezzo del caos."
  },
  AvgDialog_118946_Content_15 = {
    Text = "Quando il Rito terminerà e la ribellione esploderà, il culto dei Navigatori sarà al suo punto più debole."
  },
  AvgDialog_118946_Content_16 = {
    Text = "Secondo gli indizi forniti da Faros, forse tutto ciò che dobbiamo fare è impossessarci della Scultura d'Avorio per fuggire dal Dominio."
  },
  AvgDialog_118946_Content_17 = {
    Text = "Portare Murphy con noi complicherebbe ulteriormente la situazione?"
  },
  AvgDialog_118946_Content_18 = {
    Text = "Senior William, sei stato tu a dirmi che gli eventi nel Dominio potrebbero influenzare il mondo reale all'esterno."
  },
  AvgDialog_118946_Content_19 = {
    Text = "Non posso restare a guardare ciò che sta accadendo a Murphy..."
  },
  AvgDialog_118946_Content_2 = {
    Text = "Un altro ciclo."
  },
  AvgDialog_118946_Content_20 = {
    Text = "Golia intende impadronirsi della nave; non si curerà della Fuga di Murphy. Miryam è esausta per aver fronteggiato Golia e sarà troppo impegnata per inseguirci."
  },
  AvgDialog_118946_Content_21 = {
    Text = "È un'opportunità eccellente."
  },
  AvgDialog_118946_Content_22 = {
    Text = "William chiude gli Occhi, si sistema gli occhiali e lascia sfuggire un sospiro rassegnato."
  },
  AvgDialog_118946_Content_23 = {
    Text = "D'accordo. Decidi tu."
  },
  AvgDialog_118946_Content_24 = {
    Text = "Tu e William vi nascondete sulla piattaforma dell'albero maestro."
  },
  AvgDialog_118946_Content_25 = {
    Text = "Golia è impegnato a orchestrare la sua ribellione. Con un Salto scendi giù e afferri il polso di Murphy."
  },
  AvgDialog_118946_Content_26 = {
    Text = "Presto! Venite con noi!"
  },
  AvgDialog_118946_Content_27 = {
    Text = "Hai perso il senno? Perché sei tornato? Non possiamo fuggire. Non è meglio lasciare che tutto prosegua senza intoppi?"
  },
  AvgDialog_118946_Content_28 = {
    Text = "Murphy tenta di liberarsi dalla tua presa, ma la tua insistenza è impossibile da rifiutare. Un anello di luce rossa le appare sul polso."
  },
  AvgDialog_118946_Content_29 = {
    Text = "Murphy, la stabilità che desideravi ha cessato di esistere da tempo."
  },
  AvgDialog_118946_Content_3 = {
    Text = "Uccelli marini volteggiano sopra la donna misteriosa, i loro richiami lugubri simili a un canto."
  },
  AvgDialog_118946_Content_30 = {
    Text = "Golia e Caecus stanno tramando per impossessarsi della nave, Faros macchinando per ottenere il potere della Scultura d'Avorio, e l'intero gruppo dei Navigatori è già nel caos."
  },
  AvgDialog_118946_Content_31 = {
    Text = "Fidati di me, fidati ancora una volta. Ti porterò fuori di qui, te lo prometto."
  },
  AvgDialog_118946_Content_32 = {
    Text = "Usciremo di qui, e poi?"
  },
  AvgDialog_118946_Content_33 = {
    Text = "Poi troveremo un modo per tornare a Mythag, e diventerai parte di Mythag insieme a tutti."
  },
  AvgDialog_118946_Content_34 = {
    Text = "Dicono spesso che i miei sogni siano profetici; in sogni lontani, ho visto accadere quella cosa..."
  },
  AvgDialog_118946_Content_35 = {
    Text = "Senti che la forza per resistere si è in qualche modo indebolita."
  },
  AvgDialog_118946_Content_36 = {
    Text = "Forza, seguimi. Verso il lato destro della nave... Tre, due, uno, salta!"
  },
  AvgDialog_118946_Content_37 = {Text = "Splash!"},
  AvgDialog_118946_Content_38 = {
    Text = "Vi tuffate nell'oceano insieme, le mani strette l'una nell'altra."
  },
  AvgDialog_118946_Content_39 = {
    Text = "La luce del sole penetra la superficie del mare, illuminando i suoi capelli fluttuanti e il velo nell'acqua cristallina. Le sue pupille color rosa fissano le tue, come un sogno silenzioso."
  },
  AvgDialog_118946_Content_4 = {
    Text = "Non preoccuparti, questa volta i nostri preparativi sono infallibili."
  },
  AvgDialog_118946_Content_40 = {
    Text = "Ora siete liberi."
  },
  AvgDialog_118946_Content_41 = {Text = "Splash—"},
  AvgDialog_118946_Content_42 = {
    Text = "Un remo fende l'acqua cristallina del mare davanti a voi."
  },
  AvgDialog_118946_Content_43 = {
    Text = "Fai un cenno a Murphy, e insieme vi aggrappate ai remi."
  },
  AvgDialog_118946_Content_44 = {
    Text = "Ti tieni saldo?"
  },
  AvgDialog_118946_Content_45 = {
    Text = "Ti tira fuori dall'acqua, e ti arrampichi aggrappandoti al bordo della piccola imbarcazione."
  },
  AvgDialog_118946_Content_46 = {
    Text = "Ehi, dammi una mano!"
  },
  AvgDialog_118946_Content_47 = {
    Text = "Che succede? Non riesci ad alzarti da solo?"
  },
  AvgDialog_118946_Content_48 = {
    Text = "Smettila di sprecare parole; non ho ancora finito di punirti per aver lasciato cadere la Madre Divina in acqua!"
  },
  AvgDialog_118946_Content_49 = {
    Text = "Afferri delicatamente la spalla di Murphy mentre galleggia, allontanandola dalla superficie dell'acqua con la giusta dose di forza."
  },
  AvgDialog_118946_Content_5 = {
    Text = "Sappiamo che la nave si capovolgerà al termine del Rituale di Navigazione; sappiamo che la Scultura d'Avorio può manipolare i sogni."
  },
  AvgDialog_118946_Content_50 = {Text = "Phew—"},
  AvgDialog_118946_Content_51 = {
    Text = "Bene, ora possiamo parlare come si deve. Dove siamo diretti?"
  },
  AvgDialog_118946_Content_52 = {
    Text = "Mentre Golia e Miryam sono impegnati a combattere, noi tre piloteremo questa nave insieme e salperemo oltre i confini del Dominio."
  },
  AvgDialog_118946_Content_53 = {
    Text = "Troveremo la via del ritorno al mio mondo originale. Là incontrerai l'altra Murphy, e voi due vivrete una vita sicura, battibeccando per sciocchezze in mensa..."
  },
  AvgDialog_118946_Content_54 = {
    Text = "Pfft. Sembra che sarà un lungo viaggio."
  },
  AvgDialog_118946_Content_55 = {
    Text = "Allora... raccontami tutto di quel luogo che chiami Mythag."
  },
  AvgDialog_118946_Content_56 = {Text = "..."},
  AvgDialog_118946_Content_57 = {Text = "..."},
  AvgDialog_118946_Content_58 = {Text = "E poi?"},
  AvgDialog_118946_Content_59 = {
    Text = "Poi Ramona scoprì il vino che Lord Dexter aveva nascosto nell'angolo della sua libreria. Per occultare le bottiglie, aveva persino scavato dei buchi in alcuni dei suoi libri."
  },
  AvgDialog_118946_Content_6 = {
    Text = "Sappiamo anche che c'è solo una scialuppa di salvataggio nel ponte inferiore. Una volta lasciata questa nave da crociera, non saremo più sotto il controllo di Miryam."
  },
  AvgDialog_118946_Content_60 = {
    Text = "Scorgi William a capo chino, con la fronte aggrottata, mentre si massaggia le tempie."
  },
  AvgDialog_118946_Content_61 = {
    Text = "Ardente di rabbia, irruppe nel salotto di Lady Sorel con la spada sguainata!"
  },
  AvgDialog_118946_Content_62 = {Text = "E poi?"},
  AvgDialog_118946_Content_63 = {
    Text = "Murphy si aggrappa nervosamente alla tua manica, l'appetito stuzzicato dall'intrigante storia."
  },
  AvgDialog_118946_Content_64 = {
    Text = "Le risate e le chiacchiere nel salone si gelarono all'improvviso, e tutti fissarono con gli occhi spalancati l'Ospite Inatteso!"
  },
  AvgDialog_118946_Content_65 = {
    Text = "Esatto, proprio come l'espressione sul volto di William in questo momento!"
  },
  AvgDialog_118946_Content_66 = {
    Text = "%player%..."
  },
  AvgDialog_118946_Content_67 = {
    Text = "Assassino! È un Assassino! La gente cominciò a gridare tutt'intorno!"
  },
  AvgDialog_118946_Content_68 = {
    Text = "All'improvviso, il tuo sorriso si congela sul volto."
  },
  AvgDialog_118946_Content_69 = {
    Text = "Dietro Murphy, al bordo della piccola imbarcazione, un Mostro imponente composto da innumerevoli cadaveri fusi insieme emerge improvvisamente dal mare."
  },
  AvgDialog_118946_Content_7 = {
    Text = "Il nostro piano prevede che io faccia irruzione nel Rito di Navigazione e approfitti della Debolezza di Murphy per gettarmi in mare con lei."
  },
  AvgDialog_118946_Content_70 = {Text = "<Big:...>"},
  AvgDialog_118946_Content_71 = {
    Text = "Spalanca in silenzio le sue fauci gigantesche, formate da ossa contorte e un teschio—"
  },
  AvgDialog_118946_Content_72 = {
    Text = "<Red:E inghiotte Murphy per intero.>"
  },
  AvgDialog_118946_Content_73 = {
    Text = "<Shake:No... la Marionetta della Putrescenza... Non l'avevamo sconfitta a Necrovia...>"
  },
  AvgDialog_118946_Content_74 = {
    Text = "A questo punto di questo Dominio... Golia controlla ancora la Marionetta della Putrescenza."
  },
  AvgDialog_118946_Content_75 = {
    Text = "Le sue forze principali sono impegnate in combattimento con Miryam, perciò ha inviato questo schieramento esterno per inseguirci..."
  },
  AvgDialog_118946_Content_76 = {
    Text = "Noi... abbiamo sbagliato i calcoli."
  },
  AvgDialog_118946_Content_77 = {
    Text = "<Big:<Shake:...!!!>>"
  },
  AvgDialog_118946_Content_78 = {
    Text = "La creatura gigantesca che ha divorato Murphy solleva in alto la sua strana testa, emettendo dalla gola un gorgoglio soddisfatto."
  },
  AvgDialog_118946_Content_79 = {
    Text = "La foschia Corrotta e lurida si diffonde sul mare. Il Paradise è ormai scomparso alla vista in lontananza; solo l'imponente montagna di Scheletri incombe, oscurando la luce."
  },
  AvgDialog_118946_Content_8 = {
    Text = "William guiderà la scialuppa per recuperare me e Murphy. Una volta a bordo, svelerò rapidamente il mistero della Scultura d'Avorio e fuggiremo dal Dominio."
  },
  AvgDialog_118946_Content_80 = {Text = "Attento!"},
  AvgDialog_118946_Content_81 = {
    Text = "William ti stringe forte e rotola verso il fianco della nave, schivando per un soffio il Colpo iniziale dell'Artiglio d'osso."
  },
  AvgDialog_118946_Content_82 = {
    Text = "William, la tua schiena..."
  },
  AvgDialog_118946_Content_83 = {
    Text = "Tutto ciò che riesci a vedere è il suo Sangue. Sangue, che scorre lungo la sua spina dorsale."
  },
  AvgDialog_118946_Content_84 = {
    Text = "Non preoccuparti per me. Sali lassù! Recidigli la spina dorsale!"
  },
  AvgDialog_118946_Content_85 = {Text = "..."},
  AvgDialog_118946_Content_86 = {Text = "<Big:...>"},
  AvgDialog_118946_Content_87 = {
    Text = "La Marionetta della Putrescenza crolla come un'alta torre, precipitando nell'oceano infinito."
  },
  AvgDialog_118946_Content_88 = {
    Text = "Come dicevi... la forza di Golia era enormemente indebolita nel Dominio."
  },
  AvgDialog_118946_Content_89 = {
    Text = "Ecco perché siamo riusciti a sopravvivere al suo attacco..."
  },
  AvgDialog_118946_Content_9 = {
    Text = "La Donna china il capo, la frangia sottile a celarle l'Espressione."
  },
  AvgDialog_118946_Content_90 = {
    Text = "Forse perché la Ferita è troppo grave, non riesci più a udire le parole di William."
  },
  AvgDialog_118946_Content_91 = {
    Text = "Tra la Marea crollata di cadaveri e ossa, anche la figura dell'Ancella è scomparsa dalla vista."
  },
  AvgDialog_118946_Content_92 = {
    Text = "Murphy... Murphy!"
  },
  AvgDialog_118946_Content_93 = {
    Text = "Ti precipiti verso il cumulo galleggiante di Scheletri, scavando tra i teschi ammassati, uno dopo l'altro, nel punto in cui si trovava il ventre della creatura."
  },
  AvgDialog_118946_Content_95 = {
    Text = "Murphy non si trova da nessuna parte."
  },
  AvgDialog_118946_Content_96 = {
    Text = "In mezzo alle ossa sparse alla rinfusa, c'è soltanto un sottile e leggero velo di garza nera."
  },
  AvgDialog_118946_Content_97 = {
    Text = "Sollevi delicatamente il velo di garza nera, e un'ondata di dolore ti sale nel cuore."
  },
  AvgDialog_118946_Content_98 = {
    Text = "Pensavo che, questa volta, sarei riuscito di certo a portarla via da qui..."
  },
  AvgDialog_118946_Content_99 = {
    Text = "Emetti un singhiozzo sommesso e soffocato, che a poco a poco si fa pianto più forte."
  },
  AvgDialog_118947_Content_1 = {
    Text = "Il \"Paradise\""
  },
  AvgDialog_118947_Content_10 = {
    Text = "Estrai la teglia dal forno, e Murphy allunga subito avidamente la mano per afferrare un cupcake fumante."
  },
  AvgDialog_118947_Content_11 = {
    Text = "Non avere fretta, è troppo caldo!"
  },
  AvgDialog_118947_Content_12 = {
    Text = "Murphy sembra del tutto restia a lasciarla andare, passando la torta dalla mano sinistra alla destra e viceversa più volte, finché finalmente si raffredda a una temperatura adeguata."
  },
  AvgDialog_118947_Content_13 = {
    Text = "Dai un Morso... Non credo di dover aggiungere altro."
  },
  AvgDialog_118947_Content_14 = {
    Text = "Prima ancora che tu possa finire la frase, Murphy ha già dato un Morso."
  },
  AvgDialog_118947_Content_15 = {Text = "Ti piace?"},
  AvgDialog_118947_Content_16 = {
    Text = "La ricetta si basa interamente sulla tua Memoria. Per prenderti cura della giovane signora che piange per il cibo nel cuore della notte, hai preso in prestito la cucina sul retro di Mythag più volte."
  },
  AvgDialog_118947_Content_17 = {
    Text = "Hmph. Ingredienti così semplici. Una pallida Ombra di ciò che Miryam mi offre."
  },
  AvgDialog_118947_Content_18 = {
    Text = "Murphy deglutisce con cura i resti che ha in bocca e dice con serietà."
  },
  AvgDialog_118947_Content_19 = {
    Text = "Non importa... dimostra semplicemente che il mio Talento è abbastanza grande da apprezzare la miracolosa semplicità."
  },
  AvgDialog_118947_Content_2 = {Text = "..."},
  AvgDialog_118947_Content_20 = {
    Text = "Caldo e soffice... è il cibo più delizioso che abbia mai assaggiato."
  },
  AvgDialog_118947_Content_21 = {
    Text = "Ne assaggio un pezzo anch'io."
  },
  AvgDialog_118947_Content_22 = {
    Text = "William solleva con cura un pezzo con un bisturi d'Argento e lo porta alla bocca."
  },
  AvgDialog_118947_Content_23 = {
    Text = "William... Se non mi sbaglio, hai dissezionato cuccioli di Nubia con lo stesso bisturi, prima?"
  },
  AvgDialog_118947_Content_24 = {
    Text = "È stato accuratamente disinfettato. I rozzi coltelli e forchette usati da quei Marinai sono davvero Difficili da usare per mangiare."
  },
  AvgDialog_118947_Content_25 = {
    Text = "Avrei dovuto chiedere a Doresain due set di posate prima di lasciare Necrovia... Lascia perdere, ciò che le posate di Doresain hanno tagliato è ancora più preoccupante..."
  },
  AvgDialog_118947_Content_26 = {
    Text = "Banchettate di gusto, ridendo mentre vi spalmate la crema l'uno sul volto dell'altro."
  },
  AvgDialog_118947_Content_27 = {
    Text = "(Se questo sarà l'ultimo ricordo che conserverà, che sia almeno un ricordo felice...)"
  },
  AvgDialog_118947_Content_28 = {Text = "Bang—"},
  AvgDialog_118947_Content_29 = {
    Text = "Un boato fragoroso infrange la rara tranquillità, e la cucina in cui vi trovate inizia improvvisamente a tremare con violenza, in modo incontrollabile."
  },
  AvgDialog_118947_Content_3 = {
    Text = "Alcune decine di minuti dopo."
  },
  AvgDialog_118947_Content_30 = {
    Text = "Cosa sta succedendo?!"
  },
  AvgDialog_118947_Content_31 = {
    Text = "Golia saccheggia la sala macchine, Miryam oppone una feroce resistenza e un'esplosione devasta la sala macchine."
  },
  AvgDialog_118947_Content_32 = {
    Text = "Rispondi con calma."
  },
  AvgDialog_118947_Content_33 = {
    Text = "In altre parole, la nave sta per affondare."
  },
  AvgDialog_118947_Content_34 = {
    Text = "La nave sta affondando, non hai intenzione di reagire?"
  },
  AvgDialog_118947_Content_35 = {
    Text = "Murphy, devo dirti una cosa.\nQuesta nave è destinata ad affondare."
  },
  AvgDialog_118947_Content_36 = {
    Text = "Ho attraversato cinque cicli, e in ogni ciclo Golia organizza sempre un colpo."
  },
  AvgDialog_118947_Content_37 = {
    Text = "Questo processo innesca un'esplosione nella sala macchine, dopodiché la nave viene risucchiata sul fondo del mare da un vortice."
  },
  AvgDialog_118947_Content_38 = {Text = "Quindi...?"},
  AvgDialog_118947_Content_39 = {
    Text = "Ho cercato in tutti i modi di impedire la distruzione di questa nave, e questo ha generato una falla nel mio ragionamento."
  },
  AvgDialog_118947_Content_4 = {
    Text = "Fissi il forno mentre l'impasto lavorato si gonfia lentamente, e il tuo cuore, colmo di attesa, si solleva lievemente insieme a quella curva soffice."
  },
  AvgDialog_118947_Content_40 = {
    Text = "Questa nave deve affondare... Solo affondando potrà aprire un sentiero verso la libertà per te."
  },
  AvgDialog_118947_Content_41 = {Text = "BOOM!"},
  AvgDialog_118947_Content_42 = {
    Text = "Lo scafo si contorce e trema come colpito da un fulmine, simile a una Bestia gigantesca che perde il controllo e si dimena nell'agonia di un'esplosione."
  },
  AvgDialog_118947_Content_43 = {
    Text = "Va bene, non c'è bisogno di tante spiegazioni adesso. Sbrigati e seguimi."
  },
  AvgDialog_118947_Content_44 = {
    Text = "Ancora un po', e sarà troppo tardi per tutto."
  },
  AvgDialog_118947_Content_45 = {
    Text = "Trascini Murphy lungo il sentiero indicato da William."
  },
  AvgDialog_118947_Content_46 = {
    Text = "Ehi, devo davvero arrampicarmi su questa scala? È umiliante strisciare a quattro zampe davanti a un pubblico!"
  },
  AvgDialog_118947_Content_47 = {
    Text = "Allora scendi e aspettami laggiù. Ti prometto che non guarderò."
  },
  AvgDialog_118947_Content_48 = {
    Text = "I tuoi occhi si adattano all'oscurità. In un angolo della stiva, una piccola imbarcazione giace solitaria."
  },
  AvgDialog_118947_Content_49 = {
    Text = "Questa è la via di fuga che Golia aveva preparato per sé, e l'abbiamo trovata."
  },
  AvgDialog_118947_Content_5 = {
    Text = "L'aroma della crema pasticcera si diffonde ovunque, e le tue ghiandole salivari lo percepiscono prima del cervello, facendo brontolare lo stomaco per la fame."
  },
  AvgDialog_118947_Content_50 = {
    Text = "Quell'uomo scaltro ha distrutto tutte le scialuppe di salvataggio prima di dare inizio alla rivolta, assicurandosi che solo lui potesse fuggire."
  },
  AvgDialog_118947_Content_51 = {
    Text = "Ecco a te; questa è la chiave di riserva che il Senior William ha replicato. Ora, sali a bordo."
  },
  AvgDialog_118947_Content_52 = {
    Text = "Aspetta, di cosa stai parlando? Non ho mai accettato di fuggire con te—"
  },
  AvgDialog_118947_Content_53 = {
    Text = "Non ho mai detto che sarei salito sulla barca con te. Qui c'è una sola scialuppa, e una soltanto. Sali tu, da solo, e raggiungi la riva."
  },
  AvgDialog_118947_Content_54 = {Text = "!"},
  AvgDialog_118947_Content_55 = {
    Text = "Se ce ne andiamo così, Miryam non lascerà correre. Un giorno, le ombre dei Navigatori ti raggiungeranno."
  },
  AvgDialog_118947_Content_56 = {
    Text = "Devo restare qui per assicurarmi che i Navigatori e il Feto Divino vengano inghiottiti per sempre dal mare."
  },
  AvgDialog_118947_Content_57 = {
    Text = "Questo è anche ciò che sono lieti di vedere: tornare alla loro eterna patria e al Reame Divino, non è così?"
  },
  AvgDialog_118947_Content_58 = {Text = "Puff—"},
  AvgDialog_118947_Content_59 = {
    Text = "Murphy ride tra le lacrime."
  },
  AvgDialog_118947_Content_6 = {
    Text = "I Passi distorti, umidi e ansiosi del Navigatore echeggiano di tanto in tanto sul pavimento di legno, mentre il sottile varco separa due mondi. Questo piccolo spazio è colmo di una felicità e un calore fin troppo semplici, che ricordano un Fantasma."
  },
  AvgDialog_118947_Content_60 = {
    Text = "L'avevo pianificato prima di partire."
  },
  AvgDialog_118947_Content_61 = {
    Text = "Se posso aiutarti a fuggire, allora questo è già il miglior finale possibile."
  },
  AvgDialog_118947_Content_62 = {
    Text = "Se non ci riesco... almeno ho provato a ricreare un giorno che il Murphy che conosco avrebbe amato."
  },
  AvgDialog_118947_Content_63 = {
    Text = "Non ci conosciamo da molto, e la mia comprensione di te non è molto profonda. Spero che piaccia anche a te."
  },
  AvgDialog_118947_Content_64 = {
    Text = "Murphy si alza in punta di piedi e ti stringe in un dolce abbraccio."
  },
  AvgDialog_118947_Content_65 = {
    Text = "Ricordo che hai detto che avresti attraversato il ciclo ancora e ancora."
  },
  AvgDialog_118947_Content_66 = {
    Text = "Questa volta non sarà la fine."
  },
  AvgDialog_118947_Content_67 = {
    Text = "La prossima volta, portami con te a fuggire, d'accordo?"
  },
  AvgDialog_118947_Content_68 = {
    Text = "<Red:Non ci sarà una prossima volta.>\nUna sensazione aspra ti sale al naso."
  },
  AvgDialog_118947_Content_69 = {
    Text = "Te lo prometto. Usciremo di qui insieme."
  },
  AvgDialog_118947_Content_7 = {
    Text = "Guarda, la superficie ha cambiato Colore, è pronta per essere servita!"
  },
  AvgDialog_118947_Content_70 = {
    Text = "Con dense nuvole sopra le teste, sotto la polena della nave, Miryam e Golia si fronteggiano da lontano."
  },
  AvgDialog_118947_Content_71 = {
    Text = "Consegna quella bambina e la statua d'avorio. Allora potrei concederti una morte dignitosa, come tu un tempo minacciasti me."
  },
  AvgDialog_118947_Content_72 = {
    Text = "Smettila di blaterare sciocchezze. Non sei stato tu a rapire la Madre Divina e a provocare questa rivolta?"
  },
  AvgDialog_118947_Content_73 = {
    Text = "Inutile discutere. Murphy non è più su questa nave.\nÈ sfuggita alle tue grinfie e si è allontanata da questo caos."
  },
  AvgDialog_118947_Content_74 = {
    Text = "Un'inspiegabile ondata di dolce rivalsa ti inonda il cuore."
  },
  AvgDialog_118947_Content_75 = {
    Text = "Quindi sei stato <Italic:tu> a mandarla via? Hai un bel coraggio."
  },
  AvgDialog_118947_Content_76 = {
    Text = "Se hai intenzione di combatterla qui, non mi dispiacerebbe approfittare del caos."
  },
  AvgDialog_118947_Content_77 = {
    Text = "Sei davvero tu, un insignificante Estraneo..."
  },
  AvgDialog_118947_Content_78 = {
    Text = "Credi di poter fare ciò che vuoi con la Protezione della Madre Divina?"
  },
  AvgDialog_118947_Content_79 = {
    Text = "Miryam, voglio parlarti."
  },
  AvgDialog_118947_Content_8 = {Text = "Certo."},
  AvgDialog_118947_Content_80 = {
    Text = "Quindi vuoi una conversazione prima di dichiararci guerra?"
  },
  AvgDialog_118947_Content_81 = {
    Text = "Bene. Anch'io sono curioso di sapere che razza di persona scellerata tu sia, per essere stato richiamato dalla Madre Divina e agire ancora con tanta incoscienza e senza timore."
  },
  AvgDialog_118947_Content_82 = {
    Text = "Se cerchi sinceramente risposte dall'Apostolo di Dio, potrei anche concederti la Sua divina volontà."
  },
  AvgDialog_118947_Content_83 = {
    Text = "<Red:<Shake:Ma prima, dovrai sopportare l'ira dei Navigatori!>>"
  },
  AvgDialog_118947_Content_9 = {
    Text = "L'aroma di uovo e latte si sprigiona nell'aria."
  },
  AvgDialog_118948_Content_1 = {
    Text = "Moskstraumen"
  },
  AvgDialog_118948_Content_10 = {
    Text = "Il filo d'argento si spezza all'istante con uno schiocco."
  },
  AvgDialog_118948_Content_11 = {
    Text = "Caecus è del tutto ignaro di ciò che è appena accaduto. Si limita a scrutarti con diffidenza."
  },
  AvgDialog_118948_Content_12 = {
    Text = "Amici? Tu e io? Di che stai parlando?"
  },
  AvgDialog_118948_Content_13 = {
    Text = "Dev'essere un trucco per confonderti! Non {Male=dargli,Female=darle} ascolto, Lord Caecus!"
  },
  AvgDialog_118948_Content_14 = {
    Text = "Sì... Dovrei concentrarmi sull'ordine che ho ricevuto..."
  },
  AvgDialog_118948_Content_15 = {
    Text = "Caecus inspira profondamente, come se il coraggio gli venisse infuso nuovamente nel corpo, e solleva di colpo la testa."
  },
  AvgDialog_118948_Content_16 = {
    Text = "Tutto ciò che so è che i Navigatori ti hanno temporaneamente sistemato qui, ma questo non significa che tu possa andare e venire liberamente nelle aree critiche."
  },
  AvgDialog_118948_Content_17 = {
    Text = "Per ordine di Lord Golia, al personale non autorizzato è vietato l'accesso alla sala macchine!"
  },
  AvgDialog_118948_Content_2 = {
    Text = "Guarda, qualcuno sta sorvegliando la sala macchine."
  },
  AvgDialog_118948_Content_3 = {
    Text = "Diverse figure ricurve vagano qua e là. Tra loro, un giovane uomo dalla postura eretta stringe saldamente una lancia membranosa, cautamente in allerta verso i fruscii circostanti."
  },
  AvgDialog_118948_Content_4 = {
    Text = "Tenete gli Occhi Aperti! Questo è un incarico importante da parte di Lord Golia..."
  },
  AvgDialog_118948_Content_5 = {Text = "Caecus!"},
  AvgDialog_118948_Content_6 = {
    Text = "Hmm? Tu sei quel..."
  },
  AvgDialog_118948_Content_7 = {
    Text = "Cerchi di attivare la Chiave d'Argento, connettendoti alla sua coscienza per risvegliare le memorie condivise del vostro passato."
  },
  AvgDialog_118948_Content_8 = {
    Text = "Viticci fantasmali d'argento si estendono e strisciano lungo la superficie del suo corpo, ricoperto di squame, penetrando in profondità nel suo midollo spinale..."
  },
  AvgDialog_118948_Content_9 = {
    Text = "Caecus, siamo amici. Puoi farmi entrare in quella stanza..."
  },
  AvgDialog_118949_Content_1 = {
    Text = "Perdonatemi, Lord Golia..."
  },
  AvgDialog_118949_Content_10 = {
    Text = "Ma il mio piano è a un punto critico. Sei un'incognita che non posso permettermi."
  },
  AvgDialog_118949_Content_11 = {
    Text = "Adesso ti zittisco per sempre, ragazzino."
  },
  AvgDialog_118949_Content_12 = {
    Text = "Lord Golia, combatterò al vostro fianco!"
  },
  AvgDialog_118949_Content_13 = {
    Text = "Non ce n'è bisogno, debole creaturina. Questo posto è troppo angusto per entrambi."
  },
  AvgDialog_118949_Content_14 = {
    Text = "<Small:Ma io...>"
  },
  AvgDialog_118949_Content_15 = {
    Text = "Caecus mormora sommessamente, ma la recente sconfitta in battaglia gli fa capire che non ha motivo di continuare a lamentarsi, così tace e fa un passo indietro."
  },
  AvgDialog_118949_Content_16 = {Text = "Caecus."},
  AvgDialog_118949_Content_17 = {Text = "Hm?"},
  AvgDialog_118949_Content_18 = {
    Text = "Golia non si volta indietro."
  },
  AvgDialog_118949_Content_19 = {
    Text = "Non scoraggiatevi. Siete colui che ho scelto. Una volta risolta questa faccenda, farò altre cinquecento sessioni di addestramento con voi."
  },
  AvgDialog_118949_Content_2 = {
    Text = "Taci, Caecus."
  },
  AvgDialog_118949_Content_20 = {
    Text = "Ah... Sì, signore!"
  },
  AvgDialog_118949_Content_21 = {
    Text = "Faros, sei pronto?"
  },
  AvgDialog_118949_Content_22 = {
    Text = "Per costruire la scala verso il Reame Divino... Faros sarà sempre al vostro servizio."
  },
  AvgDialog_118949_Content_3 = {
    Text = "Golia avanza lentamente, impugnando la lama capovolta, il bordo seghettato che striscia sul pavimento producendo uno stridio lacerante."
  },
  AvgDialog_118949_Content_4 = {
    Text = "Non riesci nemmeno a gestire questo piccolo trambusto, eh? E vorresti definirti un Filistea? Riprova."
  },
  AvgDialog_118949_Content_5 = {
    Text = "Scusa, io..."
  },
  AvgDialog_118949_Content_6 = {
    Text = "Gorgoglio, Lord Golia, vi prego, non incolpate Lord Caecus! Quel {Male=uomo,Female=donna} può evocare mostri invisibili!"
  },
  AvgDialog_118949_Content_7 = {
    Text = "A proposito di quello... Tu. Sto parlando con te."
  },
  AvgDialog_118949_Content_8 = {
    Text = "Necrovia è un conto. Ma questa nave non è un posto dove puoi fare il bello e il cattivo tempo."
  },
  AvgDialog_118949_Content_9 = {
    Text = "In circostanze diverse, mi prenderei il tempo per capirti. Magari anche per scambiare due parole."
  },
  AvgDialog_118950_Content_1 = {
    Text = "Il cielo brucia."
  },
  AvgDialog_118950_Content_10 = {
    Text = "Una scia cremisi di sangue si trascina dietro di lui, impregnando il ponte."
  },
  AvgDialog_118950_Content_11 = {
    Text = "<Red:Muori! Maledetto eretico!>"
  },
  AvgDialog_118950_Content_12 = {
    Text = "Con gli occhi fuori dalle orbite, un sacerdote Navigatore solleva la lancia di Caecus e ne conficca senza pietà la punta affilata nella sua schiena, inchiodandolo al ponte."
  },
  AvgDialog_118950_Content_13 = {
    Text = "Caecus sussulta e infine smette di muoversi, il suo corpo a un passo da Golia."
  },
  AvgDialog_118950_Content_14 = {
    Text = "Haha! HAHAHAHA!"
  },
  AvgDialog_118950_Content_15 = {
    Text = "Oh Signore, Signore nostro, vedete? Questo è il Sacramento che io e la Madre Divina Vi offriamo!"
  },
  AvgDialog_118950_Content_16 = {
    Text = "Miryam, il volto intriso di sangue, fissa questa scena infernale, ridendo in modo maniacale verso il cielo, la veste lacerata che ondeggia tra le fiamme."
  },
  AvgDialog_118950_Content_17 = {
    Text = "<Shake:Possa il Vostro Reame Divino risorgere dall'Abisso! Possa la Vostra volontà compiersi sulla Terra!>"
  },
  AvgDialog_118950_Content_18 = {
    Text = "Lo sguardo trionfante della Sacerdotessa spazia sul suo territorio, scivola oltre il corpo di Faros, spaccato in due, oltre i due Investigatori gravemente feriti, per posarsi infine sulla giovane fanciulla, intrisa di sangue e veleno."
  },
  AvgDialog_118950_Content_19 = {
    Text = "Madre Divina, vieni al mio fianco. Ho sanzionato tutti gli eretici che hanno abbandonato la luce e i decaduti che hanno profanato il divino!"
  },
  AvgDialog_118950_Content_2 = {
    Text = "Il mare brucia."
  },
  AvgDialog_118950_Content_20 = {
    Text = "Lo scafo danneggiato della nave perde l'equilibrio a causa dell'infiltrazione d'acqua. Metà del corpo della nave è già sprofondata sotto la superficie, eppure lei ne resta completamente ignara."
  },
  AvgDialog_118950_Content_21 = {
    Text = "<Red:<Shake:Poi, noi due erediteremo l'immortalità del Reame Divino. Alla prossima vigilia dell'allineamento stellare, il Suo santo nome sarà proclamato in tutto l'universo!>>"
  },
  AvgDialog_118950_Content_22 = {
    Text = "La prua inclinata della nave pende come una ghigliottina. Miryam si erge sulla sua punta, protendendo dall'alto la mano insanguinata."
  },
  AvgDialog_118950_Content_23 = {
    Text = "<Shake:No, no... Non dovrebbe essere...>"
  },
  AvgDialog_118950_Content_24 = {
    Text = "Le gambe di Murphy cedono e si inginocchia a terra. Il suo corpo minuto ha completamente perso la sua antica eleganza, tremando alla luce delle fiamme."
  },
  AvgDialog_118950_Content_25 = {
    Text = "<Shake:Scusate, non avrei dovuto... Non avrei dovuto voler fuggire...>"
  },
  AvgDialog_118950_Content_26 = {
    Text = "Le lacrime scorrono, lasciando chiazze d'acqua sul ponte, solo per essere prosciugate dal calore delle fiamme."
  },
  AvgDialog_118950_Content_27 = {
    Text = "<Red:<Shake:Avrei dovuto saperlo. Questo è un Fato che non posso evitare. Non posso fuggire...>>"
  },
  AvgDialog_118950_Content_28 = {
    Text = "Murphy... No, Murphy, c'è ancora una possibilità..."
  },
  AvgDialog_118950_Content_29 = {
    Text = "Sei ansioso di fare un passo avanti e confortarla, ma il tuo corpo tradisce la tua volontà."
  },
  AvgDialog_118950_Content_3 = {
    Text = "Non letteralmente, forse — ma tutto ciò che vedi sta bruciando.\nMorte e disperazione avvolgono questo luogo senza legge, una cicatrice sul vasto mare."
  },
  AvgDialog_118950_Content_30 = {
    Text = "Il dolore lancinante alla caviglia. Le ferite subite nella recente Battaglia ti inchiodano al suolo, rendendo impossibile muovere anche un solo passo."
  },
  AvgDialog_118950_Content_31 = {
    Text = "Mi dispiace."
  },
  AvgDialog_118950_Content_32 = {
    Text = "Con calma, la Bambina si alza in piedi, incurante del Sangue che sgorga dalla Ferita al petto."
  },
  AvgDialog_118950_Content_33 = {
    Text = "Il dolore non può più trattenerla. Nei Suoi Occhi non c'è esitazione, nessun Delirio, e nulla di cui pentirsi."
  },
  AvgDialog_118950_Content_34 = {
    Text = [[
Attraversando montagne di cadaveri e mari di fuoco.
Camminava solennemente, passo dopo passo, verso la Sacerdotessa.]]
  },
  AvgDialog_118950_Content_35 = {
    Text = "No... non può finire qui..."
  },
  AvgDialog_118950_Content_36 = {
    Text = "William... William! Riesci ancora a muoverti?"
  },
  AvgDialog_118950_Content_37 = {
    Text = "Che... vuoi..."
  },
  AvgDialog_118950_Content_38 = {
    Text = "William giace in una pozza di Sangue, lottando per respirare."
  },
  AvgDialog_118950_Content_39 = {
    Text = "<Red:<Big:…Uccidimi, riavvia il ciclo.>>"
  },
  AvgDialog_118950_Content_4 = {
    Text = "Una catena di esplosioni squarcia la sala macchine; il ponte in fiamme si torce e si solleva."
  },
  AvgDialog_118950_Content_40 = {
    Text = "No... Perché..."
  },
  AvgDialog_118950_Content_41 = {
    Text = "Non posso permettere che finisca qui... Non posso accettare un simile esito..."
  },
  AvgDialog_118950_Content_42 = {
    Text = "Sbrigati! Non riesco più a muovermi..."
  },
  AvgDialog_118950_Content_43 = {
    Text = "Il Braccio meccanico di William giaceva reciso dal suo Corpo. A stento protende il braccio rimastogli, afferrando il Pugnale che Miryam aveva gettato via."
  },
  AvgDialog_118950_Content_44 = {
    Text = "Perdonami, non sopporto l'idea che tu veda il mio volto in questo momento..."
  },
  AvgDialog_118950_Content_45 = {
    Text = "Mentre si muove, un dolore lancinante si irradia dalla parte inferiore sinistra della schiena."
  },
  AvgDialog_118950_Content_46 = {
    Text = "Non se ne parla!"
  },
  AvgDialog_118950_Content_47 = {
    Text = "Sacerdote! Cattura{Male=lo,Female=la} vivo{Male=,Female=a}! Non lascia{Male=lo,Female=la} morire!"
  },
  AvgDialog_118950_Content_48 = {
    Text = "Al comando di Miryam, un altro Tridente trafigge il petto di William. Sconvolto, ti volti indietro solo per vedere i suoi capelli dorati afflosciarsi dolcemente."
  },
  AvgDialog_118950_Content_49 = {
    Text = "Il Sacerdote Navigatore ruota in un cerchio sinistro, scoppiando in una risata."
  },
  AvgDialog_118950_Content_5 = {
    Text = "Compagni e nemici giacciono ormai indistinguibili, uniti in un ultimo, rovente abbraccio cremisi."
  },
  AvgDialog_118950_Content_50 = {
    Text = "GORGOGLIO! Hehe, qualunque cosa volessi fare, ora non puoi più farla!"
  },
  AvgDialog_118950_Content_51 = {
    Text = "Il dolore ti dilania il cuore, sovrastando la sofferenza fisica. Le tue membra esangui sono gelide e doloranti."
  },
  AvgDialog_118950_Content_52 = {
    Text = "<Red:Devi morire.> Devi passare al ciclo successivo."
  },
  AvgDialog_118950_Content_53 = {
    Text = "<Red:<Shake:Io... Io posso farcela...>>"
  },
  AvgDialog_118950_Content_54 = {
    Text = "Premi il pugnale contro il ponte."
  },
  AvgDialog_118950_Content_55 = {
    Text = "Il Pugnale affonda lentamente nel tuo Corpo, seguito da un dolore che penetra fino alle Ossa."
  },
  AvgDialog_118950_Content_56 = {
    Text = "Ricadere sul pugnale."
  },
  AvgDialog_118950_Content_57 = {
    Text = "La Lama affilata ti trafigge il petto, e il Vuoto di una coscienza fugace avvolge la tua Visuale."
  },
  AvgDialog_118950_Content_58 = {
    Text = "<Shake:Murphy... William... Per favore, aspettatemi nel prossimo ciclo.>"
  },
  AvgDialog_118950_Content_59 = {
    Text = "<Yellow:Io... ci porterò fuori di qui.>"
  },
  AvgDialog_118950_Content_6 = {
    Text = "<Shake:Perdonatemi, Lord Golia... Se solo fossi stato un po' più forte...>"
  },
  AvgDialog_118950_Content_7 = {
    Text = "Gravemente ferito, Caecus trascina il corpo sul pavimento, graffiando il suolo con dita sanguinanti verso la forma esanime di Golia."
  },
  AvgDialog_118950_Content_8 = {
    Text = "<Shake:Lord... Golia...>"
  },
  AvgDialog_118950_Content_9 = {
    Text = "Per quanto chiami, l'uomo non risponde."
  },
  AvgDialog_118951_Content_1 = {
    Text = "Allora, per cosa esattamente mi hai attirato qui con l'inganno?"
  },
  AvgDialog_118951_Content_10 = {
    Text = "Facciamo qualcosa che non abbia nulla a che fare con dottrine e riti."
  },
  AvgDialog_118951_Content_11 = {
    Text = "So che in realtà non ti piace niente di tutto ciò, nonostante tu ne parli in continuazione."
  },
  AvgDialog_118951_Content_12 = {
    Text = "Basta parlare. Prendi, Murphy!"
  },
  AvgDialog_118951_Content_13 = {
    Text = "Q-Questo è?"
  },
  AvgDialog_118951_Content_14 = {
    Text = "Ora mescola! Mescola in fretta, in una sola direzione!"
  },
  AvgDialog_118951_Content_15 = {Text = "..."},
  AvgDialog_118951_Content_16 = {
    Text = "Ora, aggiungete la farina! Il lievito! Un pizzico di sale!"
  },
  AvgDialog_118951_Content_17 = {
    Text = "William, non restare lì impalato! Vai ad aiutare a sciogliere il burro!"
  },
  AvgDialog_118951_Content_18 = {
    Text = "...D'accordo."
  },
  AvgDialog_118951_Content_19 = {
    Text = "William si allontana, interpretando con pazienza il ruolo dell'aiuto cuoco agitato ma coscienzioso nella cucina caotica."
  },
  AvgDialog_118951_Content_2 = {
    Text = "Avvicinati. Il veterano William ha un trucco di magia per te!"
  },
  AvgDialog_118951_Content_20 = {
    Text = "Infine, metti l'impasto mescolato nel forno."
  },
  AvgDialog_118951_Content_21 = {
    Text = "Murphy fissa il forno con sguardo assente."
  },
  AvgDialog_118951_Content_22 = {
    Text = "Mi sono ricordata qualcosa... di molto tempo fa..."
  },
  AvgDialog_118951_Content_23 = {Text = "Hm?"},
  AvgDialog_118951_Content_24 = {
    Text = "Era quando ci trovavamo alla base antartica. Scoprii un altare in un passo di montagna, ornato di molte delicate incisioni nella pietra."
  },
  AvgDialog_118951_Content_25 = {
    Text = "Chiesi alla mamma... chiesi a Miryam di procurarmi un coltellino e dei blocchi di legno; volevo fare delle sculture in legno."
  },
  AvgDialog_118951_Content_26 = {
    Text = "Dopo molto tempo, mi diede soltanto un coltello smussato, dicendo che temeva che \"il corpo sacro della Madre Divina potesse essere danneggiato.\""
  },
  AvgDialog_118951_Content_27 = {
    Text = "Sentivo che il mio corpo non mi apparteneva. Non apparteneva nemmeno a lei. Sembrava che fossimo entrambe soltanto mattoni di quel cosiddetto Reame Divino, incastrate ciascuna al proprio posto, incapaci di muoverci."
  },
  AvgDialog_118951_Content_28 = {
    Text = "Ho visto delle sculture in legno sulla testata del tuo letto."
  },
  AvgDialog_118951_Content_29 = {
    Text = "Sì. Ho chiesto di nascosto a Golia di aiutarmi a trovare una pietra per affilare."
  },
  AvgDialog_118951_Content_3 = {
    Text = "Ho riportato tutto secondo la tua lista, %player%. Dai un'occhiata."
  },
  AvgDialog_118951_Content_30 = {
    Text = "Ho fatto un'enorme fatica solo per riuscire a malapena ad affilare la lama abbastanza da tagliare il legno."
  },
  AvgDialog_118951_Content_31 = {
    Text = "Ho intagliato per molti giorni, sforzandomi di ricreare ogni dettaglio che avevo immaginato."
  },
  AvgDialog_118951_Content_32 = {
    Text = "Quando finalmente mi sentii soddisfatta, la diedi a Miryam..."
  },
  AvgDialog_118951_Content_33 = {
    Text = "Sai cosa disse?"
  },
  AvgDialog_118951_Content_34 = {
    Text = "Miryam... ha detto che la tua scultura era brutta e che profanava il suo dio?"
  },
  AvgDialog_118951_Content_35 = {
    Text = "Ponderi attentamente la mentalità di Miryam e con cautela azzardi un'ipotesi."
  },
  AvgDialog_118951_Content_36 = {Text = "No."},
  AvgDialog_118951_Content_37 = {
    Text = "Non la guardò nemmeno. Disse soltanto che se desideravo una scultura di quel tipo, avrebbe potuto far sì che i migliori artigiani ne producessero una per me ogni singolo giorno."
  },
  AvgDialog_118951_Content_38 = {
    Text = "Murphy ride in modo maniacale. Un dolore e uno scherno indescrivibili traboccano dal suo sorriso rigido, stringendoti il cuore."
  },
  AvgDialog_118951_Content_39 = {
    Text = "Mi chiamava la Figlia del Dio e il Suo grembo-ricettacolo. Diceva che qualunque cosa volessi, potevo averla con un cenno della mano."
  },
  AvgDialog_118951_Content_4 = {
    Text = "William apre una dopo l'altra le varie tasche sul petto, sulla schiena e sulle braccia."
  },
  AvgDialog_118951_Content_40 = {
    Text = "Banale. Ecco cos'era. Solo una piccola cosa banale."
  },
  AvgDialog_118951_Content_41 = {
    Text = "Ride e ride, soffocata dalle lacrime. Le lacrime scivolano rapide lungo le guance distorte da quella risata maniacale."
  },
  AvgDialog_118951_Content_42 = {
    Text = "Ho visto l'opera che hai messo sulla testata del letto, la tua maestria è notevole."
  },
  AvgDialog_118951_Content_43 = {
    Text = "Sono brava? E allora? Non importa più ormai..."
  },
  AvgDialog_118951_Content_44 = {
    Text = "Murphy, d'ora in poi, intaglierai come vorrai tu."
  },
  AvgDialog_118951_Content_45 = {
    Text = "Poi potremo preparare dei cupcake insieme e studiare l'arte delle composizioni floreali."
  },
  AvgDialog_118951_Content_46 = {
    Text = "Troverò un modo per tornare nel mio mondo, e quando lo farò, ti presenterò il Murphy che conosco. Voi due potrete fare liberamente tutto ciò che desiderate fare insieme."
  },
  AvgDialog_118951_Content_47 = {
    Text = "Murphy si copre il volto per asciugarsi le lacrime, poi alza la testa e ti rivolge un sorriso radioso come non ne hai mai visti prima."
  },
  AvgDialog_118951_Content_48 = {
    Text = "Certo. Ricorda la tua promessa."
  },
  AvgDialog_118951_Content_49 = {
    Text = "Non tirarti indietro, d'accordo?"
  },
  AvgDialog_118951_Content_5 = {
    Text = "Ringraziamo il grande dio della magia, William, per le materie prime che ha sottratto dalla cucina per noi."
  },
  AvgDialog_118951_Content_50 = {
    Text = "La tua storia non aveva nulla a che fare con la Madre Divina."
  },
  AvgDialog_118951_Content_51 = {
    Text = "Eppure sembra che non sia mai stata più felice."
  },
  AvgDialog_118951_Content_6 = {
    Text = "Farina, uova, limone, miele, zucchero, lievito e burro..."
  },
  AvgDialog_118951_Content_7 = {
    Text = "Abbiamo tutto! Per fortuna l'uniforme da marinaio ha un sacco di tasche."
  },
  AvgDialog_118951_Content_8 = {
    Text = "Ancora non capisco... perché?"
  },
  AvgDialog_118951_Content_9 = {
    Text = "Non vorresti provare a preparare da sola le torte che mangi di solito?"
  },
  AvgDialog_118952_Content_1 = {
    Text = "Sette Giorni"
  },
  AvgDialog_118952_Content_10 = {
    Text = "Implorai una risposta dal dio."
  },
  AvgDialog_118952_Content_11 = {
    Text = "Ho chiesto del futuro del Reame Divino, del legame tra Lui e me, tutto ciò che volevo sapere, e tutto ciò che Miryam cercava di indagare."
  },
  AvgDialog_118952_Content_12 = {
    Text = "Il dio rimase in silenzio."
  },
  AvgDialog_118952_Content_13 = {
    Text = "<color=#E6E6E6>Quinto giorno dopo la Sua Nascita.</color>"
  },
  AvgDialog_118952_Content_14 = {
    Text = "Miryam mi chiese l'esito della mia udienza con il dio."
  },
  AvgDialog_118952_Content_15 = {
    Text = "In un momento di disperazione, inventai una risposta: \"Il Reame Divino sta per sorgere.\""
  },
  AvgDialog_118952_Content_16 = {
    Text = "Continuava a chiedere il momento esatto, e io potei solo rispondere: \"Quando le Stelle Sono Allineate.\""
  },
  AvgDialog_118952_Content_17 = {
    Text = "Miryam era estatica. Era una gioia frenetica che non avevo mai visto prima — non quando le regalai l'intaglio di legno, nemmeno quando concepii il Feto Divino."
  },
  AvgDialog_118952_Content_18 = {
    Text = "<color=#E1E1E1>Sesto giorno dopo la Sua Nascita.</color>"
  },
  AvgDialog_118952_Content_19 = {
    Text = "Miryam chiese dove si trovasse Lemuria, e io potei solo rispondere vagamente; la sua espressione era di scetticismo."
  },
  AvgDialog_118952_Content_2 = {
    Text = "Primo giorno dopo la Sua Nascita."
  },
  AvgDialog_118952_Content_20 = {
    Text = "Lei aveva visto il dio quand'era ancora vivo. Le mie menzogne potrebbero non funzionare con lei."
  },
  AvgDialog_118952_Content_21 = {
    Text = "<Shake:Dio, salvami, ti prego, una sola parola, rispondi alla mia preghiera.>"
  },
  AvgDialog_118952_Content_22 = {
    Text = "<Red:Settimo giorno dopo la Sua Nascita.>"
  },
  AvgDialog_118952_Content_23 = {
    Text = "Il dio era morto. Il dio non era mai nato."
  },
  AvgDialog_118952_Content_24 = {
    Text = "Sul mio petto giaceva soltanto una falsa effigie, un ammasso di carne morta erroneamente chiamato <Yellow:\"dio.\">"
  },
  AvgDialog_118952_Content_25 = {
    Text = "Miryam non ha mai amato nessuno. Non si è mai preoccupata di nessuno."
  },
  AvgDialog_118952_Content_26 = {
    Text = "Dopo aver padroneggiato l'Autorità della Madre Divina, ho letto tutti gli archivi dei Navigatori."
  },
  AvgDialog_118952_Content_27 = {
    Text = "Ogni sei decenni, le stelle si allineano — un fenomeno che si ripete da migliaia di anni."
  },
  AvgDialog_118952_Content_28 = {
    Text = "Non sono il primo ricettacolo che hai sacrificato, e non sarò l'ultimo."
  },
  AvgDialog_118952_Content_29 = {
    Text = "Per restare in vita... Per restare con te..."
  },
  AvgDialog_118952_Content_3 = {
    Text = "Il Feto Divino nacque entro un guscio cinereo."
  },
  AvgDialog_118952_Content_30 = {
    Text = "Devo uccidere il mio io passato..."
  },
  AvgDialog_118952_Content_31 = {
    Text = "Devo uccidere la mia ingenuità..."
  },
  AvgDialog_118952_Content_4 = {
    Text = "Ero esausta, spiritualmente svuotata, eppure il volto di tutti era acceso di gioia fanatica."
  },
  AvgDialog_118952_Content_5 = {
    Text = "<color=#F7F7F7>Secondo giorno dopo la Sua Nascita.</color>"
  },
  AvgDialog_118952_Content_6 = {
    Text = "Ho celebrato il battesimo per il feto. Dormiva profondamente nella sua culla."
  },
  AvgDialog_118952_Content_7 = {
    Text = "<color=#F2F2F2>Terzo giorno dopo la Sua Nascita.</color>"
  },
  AvgDialog_118952_Content_8 = {
    Text = "Il Feto Divino ancora non aveva aperto i Suoi occhi. Perché? Potevo persino sentire i Suoi battiti come fossero i miei."
  },
  AvgDialog_118952_Content_9 = {
    Text = "<color=#F0F0F0>Quarto giorno dopo la Sua Nascita.</color>"
  },
  AvgDialog_118953_Content_1 = {
    Text = "Il sipario nel cielo ondeggia e ribolle, simile a una tempesta furiosa."
  },
  AvgDialog_118953_Content_10 = {
    Text = "Il vento si leva, e il cielo cupo e coperto inizia a mutare."
  },
  AvgDialog_118953_Content_11 = {
    Text = "Il... sole nel cielo..."
  },
  AvgDialog_118953_Content_12 = {
    Text = "Il falso splendore svanisce, e sotto il cielo lontano, il Velo Nero che oscura il sole ondeggia dolcemente a ogni respiro."
  },
  AvgDialog_118953_Content_13 = {
    Text = "È un sole nero come la pece."
  },
  AvgDialog_118953_Content_2 = {
    Text = "Un soffio di brezza passeggera solleva il Velo Nero che oscura il volto di Murphy, sotto il quale si celano un paio di occhi rigati di lacrime ormai da tempo prosciugate."
  },
  AvgDialog_118953_Content_3 = {
    Text = "ORA! Proprio lì!"
  },
  AvgDialog_118953_Content_4 = {Text = "HAAHHH!"},
  AvgDialog_118953_Content_6 = {
    Text = "Nell'istante fugace del cielo tremante, l'immensa lama frastagliata fende con decisione la fenditura vacillante."
  },
  AvgDialog_118953_Content_7 = {
    Text = "La Scultura d'Avorio erutta una luce bianca feroce, simile a una disperata Resistenza alla morte."
  },
  AvgDialog_118953_Content_8 = {
    Text = "Pochi secondi dopo, la luce bianca si estingue d'improvviso e la Scultura d'Avorio si frantuma, generando una pioggia di Frammenti bianchi in un diametro di venti centimetri."
  },
  AvgDialog_118953_Content_9 = {
    Text = "È tutto finito..."
  },
  AvgDialog_118954_Content_1 = {
    Text = "Ciclo Temporale"
  },
  AvgDialog_118954_Content_10 = {Text = "Custode..."},
  AvgDialog_118954_Content_11 = {Text = "Ramona!"},
  AvgDialog_118954_Content_12 = {
    Text = "Calmati e ascoltami."
  },
  AvgDialog_118954_Content_13 = {
    Text = "Ho sperimentato innumerevoli salti temporali e sono regredita attraverso molti cicli."
  },
  AvgDialog_118954_Content_14 = {
    Text = "Sono piuttosto certa che ciò che ti è accaduto non sia un \"ciclo temporale.\""
  },
  AvgDialog_118954_Content_15 = {
    Text = "Il tempo che hai vissuto è ancora naturalmente trascorso."
  },
  AvgDialog_118954_Content_16 = {
    Text = "Non esiste nessun \"ciclo temporale\"..."
  },
  AvgDialog_118954_Content_17 = {
    Text = "Allora le strane visioni che incontro ogni volta che mi risveglio, la nave da crociera che affonda e salpa di nuovo, e Murphy che resuscita senza un graffio..."
  },
  AvgDialog_118954_Content_18 = {Text = "Come mai?"},
  AvgDialog_118954_Content_19 = {
    Text = "Non ho una risposta."
  },
  AvgDialog_118954_Content_2 = {
    Text = "Avverti la sensazione di stare sognando."
  },
  AvgDialog_118954_Content_20 = {
    Text = "E quel sole nel cielo..."
  },
  AvgDialog_118954_Content_21 = {
    Text = "Ramona ammutolisce. Non ha una risposta alla tua domanda."
  },
  AvgDialog_118954_Content_22 = {
    Text = "La superficie dell'acqua si fa gradualmente turbolenta, la sua ombra comincia a oscillare dal bordo, trasformandosi infine in elusivi frammenti di memoria, disperdendosi nella luce scintillante delle onde."
  },
  AvgDialog_118954_Content_23 = {
    Text = "Dolore bruciante. Le fiamme lambiscono ogni centimetro della tua pelle."
  },
  AvgDialog_118954_Content_24 = {
    Text = "Le tue terminazioni nervose si arricciano per il dolore lancinante, carbonizzate dalla disidratazione, e diventi leggero, così leggero da trasformarti in ossa annerite e rinsecchite."
  },
  AvgDialog_118954_Content_25 = {
    Text = "Tossisci violentemente."
  },
  AvgDialog_118954_Content_26 = {
    Text = "Sei sveglio?"
  },
  AvgDialog_118954_Content_27 = {
    Text = "<Shake:...Ancora una volta... si ricomincia dall'inizio?>"
  },
  AvgDialog_118954_Content_28 = {
    Text = "Se ti sei ripreso, vado a preparare la cerimonia."
  },
  AvgDialog_118954_Content_29 = {
    Text = "Aspetta, non andare, Murphy..."
  },
  AvgDialog_118954_Content_3 = {
    Text = "I sogni sono l'incarnazione dei desideri e delle paure interiori, mentre il reame onirico è composto da isole sospese nel vuoto."
  },
  AvgDialog_118954_Content_30 = {
    Text = "Loro... dove sono tutti?"
  },
  AvgDialog_118954_Content_31 = {
    Text = "Murphy inspira profondamente ed espira lentamente."
  },
  AvgDialog_118954_Content_32 = {
    Text = "Tutti hanno le proprie faccende da sbrigare. Dovresti riposare bene qui."
  },
  AvgDialog_118954_Content_33 = {
    Text = "Quando giungerà il prossimo momento di allineamento, questa nave raggiungerà Lemuria, e tutto andrà bene."
  },
  AvgDialog_118954_Content_34 = {
    Text = [[
Con uno scricchiolio, la porta si chiude.
Resti solo nel soggiorno.]]
  },
  AvgDialog_118954_Content_35 = {
    Text = "Non puoi restare a guardare senza far nulla. Decidi di agire."
  },
  AvgDialog_118954_Content_36 = {
    Text = "Qualche conclusione finora? Dopo aver attraversato tre cicli completi?"
  },
  AvgDialog_118954_Content_37 = {
    Text = "Dato che il numero di cicli è certo, raccogliere informazioni è di gran lunga più importante che tentare la fuga."
  },
  AvgDialog_118954_Content_38 = {
    Text = "Nel primo ciclo, ho acquisito una comprensione preliminare dei Navigatori. Il terzo ciclo si è concluso in un brutale fallimento, ma ho colto gli obiettivi fondamentali delle altre persone su questa nave."
  },
  AvgDialog_118954_Content_39 = {
    Text = "Al contrario, il tempo che ho trascorso durante il secondo ciclo è andato sprecato per nulla."
  },
  AvgDialog_118954_Content_4 = {
    Text = "In un sogno caotico colmo di frammenti dispersi, innumerevoli lame variopinte ti trafiggono il petto, rifrangendo le ombre l'una dell'altra come bolle di sapone."
  },
  AvgDialog_118954_Content_40 = {
    Text = "Ora, la nostra priorità immediata è raccogliere più informazioni sul Paradise e sui Navigatori."
  },
  AvgDialog_118954_Content_41 = {
    Text = "Sebbene quella persona misteriosa abbia lasciato intendere che i cicli siano in tutto sei..."
  },
  AvgDialog_118954_Content_42 = {
    Text = "Ma hai considerato che se questo fosse l'ultimo ciclo, potresti star sprecando un'ultima possibilità?"
  },
  AvgDialog_118954_Content_43 = {
    Text = "Se questo è l'ultimo ciclo..."
  },
  AvgDialog_118954_Content_44 = {
    Text = "Scuoti la testa, scacciando tutte le congetture minacciose."
  },
  AvgDialog_118954_Content_45 = {
    Text = "Nel sogno all'inizio di questo ciclo, l'altra Ramona mi ha fornito un'informazione: <Yellow:il tempo continuava a scorrere in modo sequenziale dentro di me.>"
  },
  AvgDialog_118954_Content_46 = {
    Text = "E tu hai detto di aver incontrato gli stessi eventi che si ripetevano in un ciclo..."
  },
  AvgDialog_118954_Content_47 = {Text = "!"},
  AvgDialog_118954_Content_48 = {
    Text = "Quindi l'hai capito anche tu, William."
  },
  AvgDialog_118954_Content_49 = {
    Text = "Questo non è un \"Ciclo Temporale\". Piuttosto, \"gli stessi eventi si sono ripetuti più volte\"..."
  },
  AvgDialog_118954_Content_5 = {
    Text = "Ti serve un modo per porre fine al sogno."
  },
  AvgDialog_118954_Content_50 = {
    Text = "A Mythag, mi sono trovata spesso costretta in situazioni simili."
  },
  AvgDialog_118954_Content_51 = {
    Text = "Il \"Dominio Artificiale\"..."
  },
  AvgDialog_118954_Content_52 = {
    Text = "Sì. Con ogni probabilità questo è un Dominio Artificiale."
  },
  AvgDialog_118954_Content_53 = {
    Text = "Il Dominio Artificiale è soltanto un contenitore di informazioni; nel mondo reale, potremmo essere intrappolati in un vortice di tempeste, trascinati a mezz'aria."
  },
  AvgDialog_118954_Content_54 = {
    Text = "Come è stato creato questo Dominio Artificiale? Perché il Dominio continua a riavviarsi? Qual è il Catalizzatore della sua fine?"
  },
  AvgDialog_118954_Content_55 = {
    Text = "Senza comprendere tutto questo, i nostri tentativi nel Dominio non sarebbero che un esercizio futile."
  },
  AvgDialog_118954_Content_56 = {
    Text = "Abbiamo bisogno della Ragione. Negli ultimi trecento anni, la Ragione ha aiutato Mythag a combattere la follia nota come Dissoluzione."
  },
  AvgDialog_118954_Content_57 = {
    Text = "Credo che anche tu l'abbia notato. Il sole che abbiamo fissato in questi giorni non è il sole nero oscurato dalla foschia nera, ma il sole puro del mondo normale."
  },
  AvgDialog_118954_Content_58 = {
    Text = "Questo Dominio è stato creato prima che la foschia nera avvolgesse il mondo."
  },
  AvgDialog_118954_Content_59 = {Text = "..."},
  AvgDialog_118954_Content_6 = {
    Text = "In quanto Tessitrice del Fato, devo restare in silenzio e non posso rivelare la verità."
  },
  AvgDialog_118954_Content_60 = {
    Text = "Ho detto qualcosa di sbagliato? Perché mi fissi in quel modo?"
  },
  AvgDialog_118954_Content_61 = {
    Text = "...No. Mi sono solo ricordato dei nostri giorni a Mythag. Durante gli Incarichi sul campo, tu e Ramona eravate sempre al mio fianco. Con il vostro aiuto, non dovevo pensare granché."
  },
  AvgDialog_118954_Content_62 = {
    Text = "Pensare è una parte essenziale dell'Indagine."
  },
  AvgDialog_118954_Content_63 = {
    Text = "Allora, William, chi pensi sia il padrone di questo Dominio?"
  },
  AvgDialog_118954_Content_64 = {
    Text = "Basandomi sui principi di formazione dei Domini e sulle informazioni note, la mia ipotesi attuale è che il Dominio appartenga a Miryam o a Faros."
  },
  AvgDialog_118954_Content_65 = {
    Text = "Il <Yellow:\"nucleo\"> del Dominio è il \"Rito di Navigazione\", e rintracciare la posizione di Lemuria dovrebbe essere l'Ossessione del padrone del Dominio."
  },
  AvgDialog_118954_Content_66 = {
    Text = "Secondo i resoconti di Mythag sull'indagine di Sona-Nyl, l'obiettivo di Goliath è impossessarsi di più potere. Caecus è ossessionato dal dimostrare il suo nobile lignaggio. Solo Miryam e Faros anelano alla gloria del Reame Divino."
  },
  AvgDialog_118954_Content_67 = {
    Text = "Quindi terremo sotto stretta osservazione i potenziali Padroni del Dominio. E poi?"
  },
  AvgDialog_118954_Content_68 = {
    Text = "Quando il Desiderio del Padrone del Dominio verso il proprio obiettivo — l'Ossessione che sostiene questa realtà — vacilla, appariranno delle crepe, e il Cataclisma si manifesterà attraverso di esse."
  },
  AvgDialog_118954_Content_69 = {
    Text = "Tuttavia, trattandosi di un Dominio Artificiale, l'incolumità dei nostri corpi fisici dovrebbe essere garantita."
  },
  AvgDialog_118954_Content_7 = {
    Text = "Pertanto, ho fatto giungere colei che può offrirti la rivelazione."
  },
  AvgDialog_118954_Content_70 = {
    Text = "Non abbassare la guardia. Senza contare che il Dominio Artificiale resta ancora soltanto un'ipotesi per noi..."
  },
  AvgDialog_118954_Content_71 = {
    Text = "AF 306, l'Investigatore Jude Bright si fratturò la gamba destra dopo essere finito in una trappola da Cacciatore mentre si trovava nel profondo di un Dominio. Al Ritorno alla realtà, la sua gamba destra iniziò gradualmente a necrotizzare."
  },
  AvgDialog_118954_Content_72 = {
    Text = "Il modo in cui il Dominio influenza la realtà è attualmente sconosciuto, ma la cautela è sempre saggia."
  },
  AvgDialog_118954_Content_73 = {Text = "Capito."},
  AvgDialog_118954_Content_74 = {
    Text = "Dopo il Rito, mi occuperò io di Miryam, e Faros sarà lasciato a te."
  },
  AvgDialog_118954_Content_75 = {
    Text = "Che la Chiave d'Argento Illumini il Cammino."
  },
  AvgDialog_118954_Content_76 = {
    Text = "Il tono familiare ti lascia per un istante in uno stato di stordimento, ma presto un sorriso genuino affiora sul tuo volto."
  },
  AvgDialog_118954_Content_77 = {
    Text = "Che la Chiave d'Argento ci Guidi."
  },
  AvgDialog_118954_Content_78 = {
    Text = "La Donna solenne occupa da sola un angolo della cabina del Capitano. La luce sopra di lei tremola impercettibilmente al ritmo del suo respiro."
  },
  AvgDialog_118954_Content_79 = {Text = "Faros..."},
  AvgDialog_118954_Content_8 = {
    Text = "Nel riflesso del sogno increspato, una figura solenne emerge."
  },
  AvgDialog_118954_Content_80 = {
    Text = "Nel momento in cui apri bocca, ti blocchi all'improvviso. Ti sforzi di richiamare alla mente le informazioni relative a Faros, solo per renderti conto che il Mythag possiede pochissime annotazioni su di lei."
  },
  AvgDialog_118954_Content_81 = {
    Text = "Anela a fare Ritorno al Reame Divino. Con la sua luce, svia le navi in mare dalla rotta."
  },
  AvgDialog_118954_Content_82 = {
    Text = "A parte questo, tutti gli altri fascicoli dei casi sono vuoti."
  },
  AvgDialog_118954_Content_83 = {
    Text = "Che succede? Sembri smarrita, ti senti persa?"
  },
  AvgDialog_118954_Content_84 = {
    Text = "Forse... posso offrirti un po' di orientamento?"
  },
  AvgDialog_118954_Content_85 = {
    Text = "Ho paura..."
  },
  AvgDialog_118954_Content_86 = {
    Text = "So chi è il padrone di questo Dominio."
  },
  AvgDialog_118954_Content_9 = {
    Text = "L'ombra ondeggia, si frammenta e si ricompone, stabilizzandosi gradualmente nel volto sereno e familiare della tua memoria."
  },
  AvgDialog_118955_Content_1 = {Text = "Estraneo"},
  AvgDialog_118955_Content_10 = {Text = "William..."},
  AvgDialog_118955_Content_11 = {
    Text = "Ma non puoi restare qui. Devi trovare il padrone di questo sogno per liberarlo finalmente da questo ciclo infinito di giorni."
  },
  AvgDialog_118955_Content_12 = {
    Text = "In fondo alla nave, trovi l'ancella."
  },
  AvgDialog_118955_Content_13 = {
    Text = "Innumerevoli Navigatori in vesti nere giacciono riversi intorno a lei, mentre lei si appoggia silenziosamente all'Altare, stringendo tra le mani una massa di carne putrefatta cremisi e maleodorante."
  },
  AvgDialog_118955_Content_14 = {Text = "Murphy..."},
  AvgDialog_118955_Content_15 = {
    Text = "Come avevi promesso, sei venuto."
  },
  AvgDialog_118955_Content_16 = {
    Text = "Il padrone di questo Dominio del Sogno sei tu."
  },
  AvgDialog_118955_Content_17 = {
    Text = "Già, tutto su questa nave è un sogno. Tutto ciò che vedi adesso è solo \"realtà in un sogno.\""
  },
  AvgDialog_118955_Content_18 = {Text = "Perché?"},
  AvgDialog_118955_Content_19 = {
    Text = "Perché ho creato un sogno simile? O perché sono diventata ciò che sono ora?"
  },
  AvgDialog_118955_Content_2 = {
    Text = "Coff, coff!"
  },
  AvgDialog_118955_Content_20 = {
    Text = "È stato molto tempo fa."
  },
  AvgDialog_118955_Content_21 = {
    Text = "Una piccola figura arrancava nella neve."
  },
  AvgDialog_118955_Content_22 = {
    Text = "Huff... Huff..."
  },
  AvgDialog_118955_Content_23 = {
    Text = "Da quando era arrivata in Antartide, Murphy aveva sperimentato una sorta di assurda libertà."
  },
  AvgDialog_118955_Content_24 = {
    Text = "Poteva andare ovunque da sola. Ma ovunque andasse, tutto ciò che vedeva era una pallida, interminabile distesa innevata."
  },
  AvgDialog_118955_Content_25 = {
    Text = "Non c'era nemmeno una traccia di attività umana, figurarsi un'altra persona."
  },
  AvgDialog_118955_Content_26 = {
    Text = "Mi sono... persa?"
  },
  AvgDialog_118955_Content_27 = {
    Text = "La bambina si voltò a guardare le impronte che aveva lasciato dietro di sé. Nella vasta distesa innevata, un sentiero quasi rettilineo conduceva verso una destinazione inconoscibile."
  },
  AvgDialog_118955_Content_28 = {
    Text = "Poco importa, finché continuo ad andare avanti, prima o poi arriverò da qualche parte."
  },
  AvgDialog_118955_Content_29 = {
    Text = "Contò le razioni che portava con sé, calcolando la distanza massima che poteva raggiungere risparmiando al massimo."
  },
  AvgDialog_118955_Content_3 = {
    Text = "Tossisci con forza, cercando di espellere l'acqua marina che ti riempie i polmoni."
  },
  AvgDialog_118955_Content_30 = {
    Text = "Forza, Murphy. Questo è un viaggio verso la libertà, e un po' di fame non è nulla di grave."
  },
  AvgDialog_118955_Content_31 = {Text = "..."},
  AvgDialog_118955_Content_32 = {Text = "..."},
  AvgDialog_118955_Content_33 = {
    Text = "No, è impossibile determinare la direzione in una tempesta di neve simile."
  },
  AvgDialog_118955_Content_34 = {
    Text = "Razioni e neve sciolta... Ha un sapore orribile."
  },
  AvgDialog_118955_Content_35 = {
    Text = "Si rifugiava in grotte di neve e poteva udire una bestia ululare là fuori. Non l'aveva mai vista, sapeva solo che era una specie di lupo bianco."
  },
  AvgDialog_118955_Content_36 = {Text = "Aiuto!"},
  AvgDialog_118955_Content_37 = {
    Text = "Murphy fuggì in preda al panico, abbandonando la grotta. Quegli occhi di un verde brillante rimasero nella caverna e non seguirono i suoi passi."
  },
  AvgDialog_118955_Content_38 = {
    Text = "In una situazione così disperata, vidi una fila di impronte."
  },
  AvgDialog_118955_Content_39 = {
    Text = "Queste sono... impronte umane!"
  },
  AvgDialog_118955_Content_4 = {
    Text = "Ma nulla fuoriesce quando tossisci; tutto ciò che resta nei tuoi polmoni sono nervi che si contraggono e il dolore fantasma dell'annegamento."
  },
  AvgDialog_118955_Content_40 = {
    Text = "Finché ci sono persone, c'è speranza. Le seguii senza esitazione."
  },
  AvgDialog_118955_Content_41 = {Text = "..."},
  AvgDialog_118955_Content_42 = {
    Text = "Poco dopo, le impronte si trasformarono in due file."
  },
  AvgDialog_118955_Content_43 = {Text = "Poi tre."},
  AvgDialog_118955_Content_44 = {
    Text = "Le impronte aumentavano, ma il loro proprietario restava inafferrabile."
  },
  AvgDialog_118955_Content_45 = {
    Text = "Esausta, alla fine svenni."
  },
  AvgDialog_118955_Content_46 = {
    Text = "In seguito appresi che, a causa della differenza di lunghezza tra il piede sinistro e il destro, tutti tendono a deviare leggermente in una certa direzione quando camminano senza poter determinare il proprio orientamento."
  },
  AvgDialog_118955_Content_47 = {
    Text = "In altre parole... in quel momento, stavo camminando in cerchio."
  },
  AvgDialog_118955_Content_48 = {
    Text = "Le impronte che credevo fossero la mia speranza provenivano dal me stesso del passato, conducendomi in un Ciclo senza fine."
  },
  AvgDialog_118955_Content_49 = {
    Text = "A causa di una deviazione lieve, quasi insignificante... la mia vita è stata intrappolata in un ciclo anomalo."
  },
  AvgDialog_118955_Content_5 = {
    Text = "Perché... non doveva essere questo l'ultimo ciclo?"
  },
  AvgDialog_118955_Content_50 = {
    Text = "Il centro di quel Ciclo si chiama Fato."
  },
  AvgDialog_118955_Content_51 = {
    Text = "Questo è il Ciclo che ho costruito e che intrappola me stessa."
  },
  AvgDialog_118955_Content_52 = {
    Text = "Quindi, intendi dire..."
  },
  AvgDialog_118955_Content_53 = {
    Text = "Il tempo si è fermato da quando Golia ha iniziato a preparare la ribellione."
  },
  AvgDialog_118955_Content_54 = {
    Text = [[
Tutti sono sprofondati in un sogno, dando inizio a un ciclo ripetitivo.
Il ciclo inizia con la nascita del Feto Divino e termina con l'affondamento della nave da crociera.]]
  },
  AvgDialog_118955_Content_55 = {
    Text = "Se Golia non avesse dato Inizio a una ribellione, tutto sarebbe potuto rimanere pacifico come prima."
  },
  AvgDialog_118955_Content_56 = {
    Text = "Ma una volta ho visto Golia a Necrovia..."
  },
  AvgDialog_118955_Content_57 = {
    Text = "Per mantenere il Dominio del Sogno, invio periodicamente un gruppo di persone a raccogliere energia per la Scultura d'Avorio."
  },
  AvgDialog_118955_Content_58 = {
    Text = "Una volta fatto Ritorno, dimenticheranno tutto e cadranno di nuovo nel mio Sogno."
  },
  AvgDialog_118955_Content_59 = {
    Text = "Sfortunatamente, da quando avete interferito con il nostro assorbimento di energia da Necrovia, il Dominio del Sogno è diventato sempre più instabile."
  },
  AvgDialog_118955_Content_6 = {
    Text = "Ti guardi intorno; il ponte scoperto è vuoto, senza ragni viola e senza Navigatori che ti circondano."
  },
  AvgDialog_118955_Content_60 = {
    Text = "Perché vuoi che ti veda?"
  },
  AvgDialog_118955_Content_61 = {
    Text = "In origine vi ho evocato qui, sperando di uccidervi..."
  },
  AvgDialog_118955_Content_62 = {
    Text = "Ma prima che potessi farlo, il mio Nucleo d'Argento ha sembrato risuonare con la vostra Chiave d'Argento, connettendomi al vostro Sogno, alla vostra Memoria."
  },
  AvgDialog_118955_Content_63 = {
    Text = "Ho visto un'altra possibilità in quel Sogno... un'altra versione di me stessa."
  },
  AvgDialog_118955_Content_64 = {
    Text = "L'ho vista competere con i suoi compagni di classe durante la lezione di Scultura;"
  },
  AvgDialog_118955_Content_65 = {
    Text = "L'ho vista lottare con un gatto randagio sotto la fontana."
  },
  AvgDialog_118955_Content_66 = {
    Text = "L'ho vista farsi convincere dalle amiche a indossare un costume da diavoletto, portando una Lanterna a forma di zucca e andando di porta in porta a distribuire caramelle..."
  },
  AvgDialog_118955_Content_67 = {
    Text = "In un mondo in cui il Feto Divino non è mai nato, lei sembrava davvero... felice."
  },
  AvgDialog_118955_Content_68 = {
    Text = "Che invidia. Che bellezza."
  },
  AvgDialog_118955_Content_69 = {
    Text = "Una vita che avrei voluto avere."
  },
  AvgDialog_118955_Content_7 = {
    Text = "Corri ovunque, cercando."
  },
  AvgDialog_118955_Content_70 = {
    Text = "<Yellow:%player%>, è stato solo quando vi ho incontrato che ho capito che esiste un modo di vivere così semplice e gioioso in questo mondo..."
  },
  AvgDialog_118955_Content_71 = {
    Text = "Nessun bisogno della vana Corona della Madre Divina, nessun bisogno dell'onore di essere venerata dalle masse, nessun bisogno di affrontare giorno dopo giorno i volti irritanti dei Seguaci..."
  },
  AvgDialog_118955_Content_72 = {
    Text = "Responsabilità? Eredità? Perché così tante persone devono Sacrificare le proprie vite per un ammasso di carne putrescente?"
  },
  AvgDialog_118955_Content_73 = {
    Text = "Resti in silenzio; non puoi fare altro che tacere."
  },
  AvgDialog_118955_Content_74 = {
    Text = "Murphy sta rinnegando il suo sé passato."
  },
  AvgDialog_118955_Content_75 = {
    Text = "Ho un'ultima domanda da farti."
  },
  AvgDialog_118955_Content_76 = {
    Text = "Nel vostro mondo, anche voi avete preparato cupcake con lei in quel modo?"
  },
  AvgDialog_118955_Content_77 = {
    Text = "Murphy... Là troverai molte persone disposte ad aiutarti. Non ci sarò solo io.\nSi uniranno a te in qualsiasi impresa folle o capricciosa tu desideri compiere."
  },
  AvgDialog_118955_Content_78 = {
    Text = "Perché ami il mondo e tutti coloro che lo abitano."
  },
  AvgDialog_118955_Content_79 = {
    Text = "Ti sei strappata il cuore con le tue stesse mani, e il mondo intero ne è stato testimone..."
  },
  AvgDialog_118955_Content_8 = {
    Text = "Addormentati, addormentati, sono tutti addormentati."
  },
  AvgDialog_118955_Content_80 = {
    Text = "....all'amore che pulsava dentro."
  },
  AvgDialog_118955_Content_81 = {
    Text = "Murphy sorride, il suo sorriso radioso come lo ricordavi."
  },
  AvgDialog_118955_Content_82 = {
    Text = "Sai, questa nave non è che un sogno."
  },
  AvgDialog_118955_Content_83 = {
    Text = "Un tempo pensavo fosse un bel sogno... \nIo sono la Madre Divina, e quella massa di carne contorta è il cosiddetto dio che ho partorito."
  },
  AvgDialog_118955_Content_84 = {
    Text = "Giorno e notte, vivo nel terrore, costantemente in preda all'ansia e al tormento."
  },
  AvgDialog_118955_Content_85 = {
    Text = "Si scopre che non è un dolce sogno, ma un incubo di panico di cui non ero nemmeno consapevole."
  },
  AvgDialog_118955_Content_86 = {
    Text = "Quindi ora è il momento di strappare il sipario di menzogne e porre fine al sogno."
  },
  AvgDialog_118955_Content_9 = {
    Text = "William giace sul ponte, la sua uniforme ridotta a un ammasso di stracci, come se fosse stata sferzata ripetutamente da tempeste e sole cocente, con grasso e sale incrostati in una mappa chiazzata."
  },
  AvgDialog_118956_Content_1 = {
    Text = "Ti ritiri combattendo contro di lui, dalla sala motori al corridoio, e infine sul ponte, finché solo la ringhiera della nave ti separa dall'oceano infinito alle tue spalle."
  },
  AvgDialog_118956_Content_10 = {
    Text = "Il gigante, respinto dal tuo Impatto, scivola rapidamente verso la parete della cabina."
  },
  AvgDialog_118956_Content_11 = {
    Text = "In un Bagliore, conficca la sua enorme Lama direttamente nel ponte, stabilizzando a malapena la sua posizione."
  },
  AvgDialog_118956_Content_12 = {
    Text = "Sei migliorato parecchio dall'ultima volta che ci siamo incontrati, ragazzo."
  },
  AvgDialog_118956_Content_13 = {
    Text = "No, non è così."
  },
  AvgDialog_118956_Content_14 = {
    Text = "Non è che tu sia diventato più forte; piuttosto, Golia si è indebolito."
  },
  AvgDialog_118956_Content_15 = {
    Text = "Anche con Faros ad assisterlo, la forza di Golia è di gran lunga inferiore a quella del vostro ultimo incontro."
  },
  AvgDialog_118956_Content_16 = {
    Text = "Ogni fendente è leggero e arioso, del tutto dissimile dall'opera di un gigante dalla forza bruta."
  },
  AvgDialog_118956_Content_17 = {
    Text = "Golia, la forza disumana dentro di te... sta svanendo. L'ho notato subito dopo l'inizio dello scontro."
  },
  AvgDialog_118956_Content_18 = {
    Text = "Ha. Anche se fossi dieci volte più debole, tu, moccioso, non saresti in grado di tenermi testa."
  },
  AvgDialog_118956_Content_19 = {
    Text = "Questo ha a che fare con la presenza di Faros qui?"
  },
  AvgDialog_118956_Content_2 = {
    Text = "Oh, che Perseveranza... Sei riuscito a combattermi fino a qui."
  },
  AvgDialog_118956_Content_20 = {
    Text = "Inoltre, è collegato alle visioni su questa nave?"
  },
  AvgDialog_118956_Content_21 = {
    Text = "Sei così ansioso di portare a termine questi cosiddetti preparativi perché il tuo stesso potere si sta indebolendo?"
  },
  AvgDialog_118956_Content_22 = {
    Text = "Ci sono cose che non dovresti sapere. Non aspettarti di cavarmi una sola parola, in qualunque modo tu chieda."
  },
  AvgDialog_118956_Content_23 = {
    Text = "Se i nostri obiettivi sono allineati, potresti non aver davvero bisogno di eliminarmi."
  },
  AvgDialog_118956_Content_24 = {
    Text = "Facciamo ciascuno un passo indietro. Io non interferirò con la tua intenzione di tradimento, e tu non dovresti rendere le cose difficili a me."
  },
  AvgDialog_118956_Content_25 = {
    Text = "Golia non ha ancora risposto quando due serpenti d'ombra saettano verso di te come fulmini!"
  },
  AvgDialog_118956_Content_27 = {
    Text = "Ti ritrai d'improvviso, e l'impatto d'ombra squarcia istantaneamente due terrificanti fori fumanti nel ponte."
  },
  AvgDialog_118956_Content_28 = {
    Text = "Due ingrati traditori. Questo non è un luogo dove ordire i vostri complotti."
  },
  AvgDialog_118956_Content_29 = {
    Text = "Quanto a {Male=voi, signor,Female=voi, signorina} estraneo... quando siete fuggito, sembra che abbiate dimenticato qualcosa di cruciale."
  },
  AvgDialog_118956_Content_3 = {
    Text = "Tuttavia, ora non avete via di scampo."
  },
  AvgDialog_118956_Content_30 = {
    Text = [[
La scultura d'avorio fluttua nella mano di Miryam. 
Prega devotamente, parole blasfeme che le colano dalla bocca come larve.]]
  },
  AvgDialog_118956_Content_31 = {
    Text = "<Change>I vostri corpi e le vostre anime avrebbero dovuto appartenere da tempo all'oscurità dell'abisso."
  },
  AvgDialog_118956_Content_32 = {
    Text = "Aspetta, Miryam, non—"
  },
  AvgDialog_118956_Content_33 = {
    Text = "Mi perdoni, Madre Divina, ma devo punire coloro che commettono profanazione in vece Sua."
  },
  AvgDialog_118956_Content_34 = {
    Text = "La Scultura d'Avorio emette uno stridio silente, innumerevoli fili d'argento si propagano, avvinghiandosi parassitariamente ai cuori dei seguaci di Lemuria come sinistri esseri viventi."
  },
  AvgDialog_118956_Content_35 = {
    Text = "Che... pazza maledetta, che stai facendo?!"
  },
  AvgDialog_118956_Content_36 = {
    Text = "Cosa sto facendo? Naturalmente, vi sto elargendo la misericordia del Signore, la Sua compassione e il Suo supremo potere."
  },
  AvgDialog_118956_Content_37 = {
    Text = "I fili intrecciati si stringono con violenza—"
  },
  AvgDialog_118956_Content_38 = {
    Text = "Lord Golia... non riesco a respirare..."
  },
  AvgDialog_118956_Content_39 = {
    Text = "<Shake:Ah... è lì... sento il Suo battito... ho toccato... la Sua Anima...>"
  },
  AvgDialog_118956_Content_4 = {
    Text = "Inspirando profondamente, stabilizzi la mente e affronti Golia mentre cala nuovamente la sua enorme Lama."
  },
  AvgDialog_118956_Content_40 = {Text = "SPLURGE."},
  AvgDialog_118956_Content_41 = {
    Text = "I cuori detonano in rapida successione. Il sangue erompe, sbocciando in onde cremisi sul ponte."
  },
  AvgDialog_118956_Content_42 = {
    Text = "Nessuna quantità di tempo potrà mutare la follia di voi miscredenti."
  },
  AvgDialog_118956_Content_43 = {
    Text = "<Shake:Il vostro sangue e il vostro spirito forgeranno la scalinata verso il Reame Divino!>"
  },
  AvgDialog_118956_Content_44 = {
    Text = "<Shake:Fermatela... <Big:Aiutatemi a fermarla!>>"
  },
  AvgDialog_118956_Content_6 = {
    Text = "Il Vicolo Cieco che vedi era già il campo di battaglia che avevo scelto per te."
  },
  AvgDialog_118956_Content_7 = {
    Text = "Hai dissipato le tue forze per tutto questo tempo, e ora è il momento del mio contrattacco."
  },
  AvgDialog_118956_Content_8 = {
    Text = "La luce argentea esplode all'improvviso, abbattendosi su Golia con forza travolgente. Golia alza immediatamente la sua lama, ma è troppo tardi."
  },
  AvgDialog_118957_Content_1 = {Text = "Epilogo"},
  AvgDialog_118957_Content_10 = {
    Text = "Che lungo, lungo sogno è stato."
  },
  AvgDialog_118957_Content_11 = {
    Text = "Morte, Tradimento, naufragio; più cerco di aggrapparmi a qualcosa, più inevitabilmente mi sfugge tra le dita."
  },
  AvgDialog_118957_Content_12 = {
    Text = "Forse è il destino. Non serve aggrapparsi a ciò che non si può trattenere."
  },
  AvgDialog_118957_Content_13 = {
    Text = "Lascia andare prima, e potresti incontrare più compagni che condividono il tuo cammino."
  },
  AvgDialog_118957_Content_14 = {
    Text = "Per esempio... Mythag?"
  },
  AvgDialog_118957_Content_15 = {
    Text = "La gente di Mythag sembra essere molto brava a essere inclusiva... o a smussare le stranezze di Tutti."
  },
  AvgDialog_118957_Content_16 = {
    Text = "Ricordo che un anno, la Murphy del nostro mondo insistette per provare ogni gusto di Caramella, e alla fine si ritrovò con il mal di denti."
  },
  AvgDialog_118957_Content_17 = {
    Text = "Alla fine, Sylvia fece Rubare a Jenkin tutta la sua scorta di dolciumi."
  },
  AvgDialog_118957_Content_18 = {
    Text = "Pfft. E poi?"
  },
  AvgDialog_118957_Content_19 = {
    Text = "Allora iniziò a fare un gran trambusto per acciuffare i ladri, dimenticandosi completamente della Caramella."
  },
  AvgDialog_118957_Content_2 = {
    Text = "Il Paradise ha attraccato, e ora..."
  },
  AvgDialog_118957_Content_20 = {
    Text = "E un'altra volta, lei..."
  },
  AvgDialog_118957_Content_21 = {
    Text = "D'accordo, quanto ancora vuoi farmi invidiare la sua vita?"
  },
  AvgDialog_118957_Content_22 = {
    Text = "Quando faremo Ritorno a Mythag, sarà anche la tua vita."
  },
  AvgDialog_118957_Content_23 = {
    Text = "Allora spero che un giorno ci incontreremo là."
  },
  AvgDialog_118957_Content_24 = {
    Text = "Murphy tende le mani verso il cielo lontano, come se cercasse di toccare il sole in alto."
  },
  AvgDialog_118957_Content_25 = {
    Text = "Il buco nero nel cielo giace tra le sue dita, pulsante."
  },
  AvgDialog_118957_Content_26 = {
    Text = "E c'è un'altra cosa che devo dirti."
  },
  AvgDialog_118957_Content_27 = {
    Text = "Murphy ti fissa con intensità."
  },
  AvgDialog_118957_Content_28 = {
    Text = "Questo mondo è ormai al di là di ogni salvezza, avvolto in una disperazione più profonda dei cicli che ho attraversato."
  },
  AvgDialog_118957_Content_29 = {
    Text = "Se possibile, potrei riuscire a rimandarti indietro."
  },
  AvgDialog_118957_Content_3 = {
    Text = "Sanno già tutto sugli dèi di questo mondo, e presto faranno la propria Scelta."
  },
  AvgDialog_118957_Content_30 = {
    Text = "Rimandarmi... indietro?"
  },
  AvgDialog_118957_Content_31 = {
    Text = "Conosci il modo per attraversare i confini tra due mondi?"
  },
  AvgDialog_118957_Content_32 = {
    Text = "Non esattamente, ma una volta che afferri l'essenza di questo mondo, comprendi naturalmente il nesso dimensionale."
  },
  AvgDialog_118957_Content_33 = {
    Text = "Questa nave è un sogno, ma quando il sipario di menzogne viene sollevato..."
  },
  AvgDialog_118957_Content_34 = {
    Text = "Ti renderai conto che anche questo intero mondo è il Sogno di Qualcuno, solo che quel sogno è più grande, più illusorio e più distante..."
  },
  AvgDialog_118957_Content_35 = {
    Text = "Persino il sole, la luna e le stelle hanno origine dalla Sua illusione; solo gli esseri intrecciati con il Suo spirito possono @3..."
  },
  AvgDialog_118957_Content_36 = {
    Text = "Il sole, la luna e le stelle..."
  },
  AvgDialog_118957_Content_37 = {
    Text = "Il Velo Nero trema, estendendosi in un sinuoso sentiero di tessuto che conduce al cielo."
  },
  AvgDialog_118957_Content_38 = {
    Text = "Va', torna indietro, fa' ritorno al mondo che ti appartiene! Non c'è bisogno di aggrapparti a questo mondo che è già morto."
  },
  AvgDialog_118957_Content_39 = {
    Text = "E tu, Murphy?"
  },
  AvgDialog_118957_Content_4 = {
    Text = "A mio parere, Miryam e Faros dovrebbero Spiega le Vele di nuovo per cercare il luogo in cui si trova Lemuria."
  },
  AvgDialog_118957_Content_40 = {
    Text = "Resisti all'impulso di saltare immediatamente sul sentiero di seta, voltandoti a interrogare il silenzioso Murphy."
  },
  AvgDialog_118957_Content_41 = {
    Text = "Chi lo sa? Questo è un mondo che è già stato distrutto."
  },
  AvgDialog_118957_Content_42 = {
    Text = "Prendilo. Forse un giorno, potrai percepire il mio Nucleo d'Argento in quel mondo."
  },
  AvgDialog_118957_Content_43 = {
    Text = "Una gemma formata da una goccia di sangue cade nel tuo palmo, originata dalla grottesca ferita che le perfora il petto."
  },
  AvgDialog_118957_Content_44 = {
    Text = "Il \"me\" che richiami potrebbe provenire da qualsiasi momento della mia vita."
  },
  AvgDialog_118957_Content_45 = {
    Text = "Ma quando mi invocherai, ricorda il mio aspetto di adesso..."
  },
  AvgDialog_118957_Content_46 = {
    Text = "La Sua \"nascita\" era un'illusione fin dall'inizio. Tutti i sogni sono falsi... Una falsa genesi."
  },
  AvgDialog_118957_Content_47 = {
    Text = "Mi chiamerete... <Yellow:Murphy il Falsonato>!"
  },
  AvgDialog_118957_Content_48 = {
    Text = "Passeggi lungo il sentiero di tessuto oscuro, e innumerevoli pensieri ti attraversano la mente."
  },
  AvgDialog_118957_Content_49 = {
    Text = "Il viaggio per affrontare la Dissoluzione, due mondi intrecciati da un nero incubo, molti volti simili o identici che si sovrappongono l'uno all'altro..."
  },
  AvgDialog_118957_Content_5 = {
    Text = "Golia e Caecus molto probabilmente partiranno; persino in un mondo così desolato, dovrebbero avere una missione tutta loro da intraprendere."
  },
  AvgDialog_118957_Content_50 = {
    Text = "Due Bambole..."
  },
  AvgDialog_118957_Content_51 = {
    Text = "Due Clementine..."
  },
  AvgDialog_118957_Content_52 = {
    Text = "Due Murphy..."
  },
  AvgDialog_118957_Content_53 = {
    Text = "E infine, ricordi il volto sorridente di Ramona."
  },
  AvgDialog_118957_Content_54 = {
    Text = "Posso... tornare indietro ora?"
  },
  AvgDialog_118957_Content_55 = {
    Text = "In uno stato onirico, ti trovi a un braccio di distanza dal sole nero, eppure non avverti alcun calore."
  },
  AvgDialog_118957_Content_56 = {
    Text = "Quel nero profondo e infinito divora ogni luce, bramando avidamente di inghiottirti completamente."
  },
  AvgDialog_118957_Content_57 = {
    Text = "Ramona... sei lì? Mi stai aspettando dietro tutto questo?"
  },
  AvgDialog_118957_Content_58 = {
    Text = "Chiudi gli occhi e sfiori delicatamente il nero passaggio."
  },
  AvgDialog_118957_Content_59 = {
    Text = "Se puoi, per favore... stringimi la mano."
  },
  AvgDialog_118957_Content_6 = {
    Text = "Quanto a \"questa\" Murphy..."
  },
  AvgDialog_118957_Content_60 = {
    Text = "Da sotto i tuoi piedi, da innumerevoli sogni profondi."
  },
  AvgDialog_118957_Content_61 = {
    Text = "A partire dal sole nero, i veli neri si disintegrano gradualmente, strato dopo strato."
  },
  AvgDialog_118957_Content_62 = {
    Text = "Cadi dal cielo...."
  },
  AvgDialog_118957_Content_63 = {
    Text = "<Yellow:Precipitare nel vortice chiamato \"Destino\".>"
  },
  AvgDialog_118957_Content_64 = {
    Text = "Ho intravisto l'esperienza di quella ragazza in un Sogno Profondo."
  },
  AvgDialog_118957_Content_65 = {
    Text = "Che sventura. L'ho mandata via da Lemuria, affidandole la Scultura d'Avorio in un sogno, non per un simile epilogo."
  },
  AvgDialog_118957_Content_66 = {
    Text = "Non dovresti ringraziarmi per il mio coinvolgimento in tutto questo?"
  },
  AvgDialog_118957_Content_67 = {
    Text = "La Luce della Speranza in questo mondo è stata annientata da tempo; lo sai, vero?"
  },
  AvgDialog_118957_Content_68 = {
    Text = "La Donna con la mano sulla ruota che fila resta in silenzio, lasciando semplicemente che il filo nella sua mano si estenda sotto i cieli, fra tutte le cose."
  },
  AvgDialog_118957_Content_69 = {
    Text = "Finché resterà anche un solo seme."
  },
  AvgDialog_118957_Content_7 = {
    Text = "Credo che abbia qualcosa da dirti."
  },
  AvgDialog_118957_Content_70 = {
    Text = "Non importa quanto a lungo duri il silenzio, non importa in quale terra si trovi, un giorno germoglierà."
  },
  AvgDialog_118957_Content_71 = {
    Text = "Quanto a me..."
  },
  AvgDialog_118957_Content_72 = {
    Text = "La donna abbassa lo sguardo."
  },
  AvgDialog_118957_Content_73 = {
    Text = "Non sono una seminatrice, non una Custode Premuroso, e nemmeno una mietitrice."
  },
  AvgDialog_118957_Content_74 = {
    Text = "Non faccio che tirare i fili, seguendo l'ordine prestabilito in qualità di Tessitrice del Fato."
  },
  AvgDialog_118957_Content_75 = {
    Text = "Tiro il filo del fuso per individuare il terreno più adatto a esso."
  },
  AvgDialog_118957_Content_76 = {
    Text = "Attenderò... in silenzio."
  },
  AvgDialog_118957_Content_8 = {Text = "Sei qui?"},
  AvgDialog_118957_Content_9 = {Text = "Certo."},
  AvgDialog_118958_Content_1 = {
    Text = "Nucleo Onirico"
  },
  AvgDialog_118958_Content_10 = {
    Text = "Un tempo mi sono alleata con Golia, ma un barbaro che comprende solo guerra e violenza chiaramente non sa onorare un Contratto, tantomeno indicare la via per Lemuria."
  },
  AvgDialog_118958_Content_11 = {
    Text = "Che ne dite? Collaborate con me, e vi rivelerò l'identità del Signore del Dominio."
  },
  AvgDialog_118958_Content_12 = {
    Text = "Ha il cuore in gola."
  },
  AvgDialog_118958_Content_13 = {
    Text = "Permettimi di rifiutare."
  },
  AvgDialog_118958_Content_14 = {
    Text = "Non posso acconsentire con leggerezza a togliere la vita a qualcuno senza nemmeno sapere chi sia."
  },
  AvgDialog_118958_Content_15 = {
    Text = "Inoltre, dal momento che avete avanzato una simile richiesta, è evidente che il Signore del Dominio non si trova tra voi, Golia e Caecus."
  },
  AvgDialog_118958_Content_16 = {
    Text = "E avete già rivelato che il potere di manipolazione onirica è legato a quella scultura d'avorio."
  },
  AvgDialog_118958_Content_17 = {
    Text = "Allora l'unica sospettata rimasta... sarebbe lei."
  },
  AvgDialog_118958_Content_18 = {
    Text = "Il vostro gusto nella scelta del punto d'osservazione è davvero encomiabile."
  },
  AvgDialog_118958_Content_19 = {
    Text = "Tendete la corda, lasciando che le vele sull'albero vi nascondano alla vista, voi e William."
  },
  AvgDialog_118958_Content_2 = {
    Text = "<Shake:Tac tac tac, tac tac tac.>"
  },
  AvgDialog_118958_Content_20 = {
    Text = "Durante l'ultima cerimonia ho notato che, rispetto alla Sona-Nyl, la Paradise conserva una struttura dell'albero maestro relativamente antica."
  },
  AvgDialog_118958_Content_21 = {
    Text = "Equivale a una torre di vedetta che offre una visuale sul luogo della cerimonia di pilotaggio."
  },
  AvgDialog_118958_Content_22 = {
    Text = "Quando il Rito di Navigazione avrà inizio, Miryam consegnerà la scultura d'avorio a Murphy, e quella sarà anche l'unica occasione in cui potremo accedervi."
  },
  AvgDialog_118958_Content_23 = {
    Text = "Prendete la scultura e analizzatela; forse riusciremo a comprendere il metodo per annullare il Dominio."
  },
  AvgDialog_118958_Content_24 = {
    Text = "Shh, stanno arrivando."
  },
  AvgDialog_118958_Content_25 = {
    Text = "William vi batte sulla spalla, facendovi segno di voltarvi."
  },
  AvgDialog_118958_Content_26 = {
    Text = "Tenete d'occhio la posizione della scultura d'avorio... è la nostra ancora di salvezza."
  },
  AvgDialog_118958_Content_27 = {
    Text = "Il Rito di Navigazione prosegue, esattamente come lo ricordavate."
  },
  AvgDialog_118958_Content_28 = {
    Text = "Venerata Madre Divina, guida la stirpe del re divino, conduci i Navigatori smarriti e mostraci la rotta verso Lemuria."
  },
  AvgDialog_118958_Content_29 = {
    Text = "Murphy si morde il labbro e prende il pugnale luminescente dalla mano di Miryam."
  },
  AvgDialog_118958_Content_3 = {
    Text = "Un'ancella sta correndo nel corridoio."
  },
  AvgDialog_118958_Content_30 = {
    Text = "Solleva il coltello in alto — poi non lo abbassa per lungo tempo."
  },
  AvgDialog_118958_Content_31 = {
    Text = "Madre Divina, non avete forse già preso la vostra decisione? Lemuria giace ancora in fondo all'Abisso, in attesa del vostro avvento."
  },
  AvgDialog_118958_Content_32 = {
    Text = "... Lo farò subito..."
  },
  AvgDialog_118958_Content_33 = {
    Text = "La seconda metà della frase viene divorata."
  },
  AvgDialog_118958_Content_34 = {
    Text = "Solleva la scultura d'avorio intrisa di sangue, permettendo al mostro deforme di prosciugare la sua essenza."
  },
  AvgDialog_118958_Content_35 = {
    Text = "Il fiume di sangue si propaga lungo la murata della nave, scorrendo verso sinistra."
  },
  AvgDialog_118958_Content_36 = {
    Text = "Virata! Timoniere dei Navigatori, ascolta l'Oracolo Divino, tutta a sinistra!"
  },
  AvgDialog_118958_Content_37 = {
    Text = "Una lama fende l'aria, come rispondendo alle sue parole."
  },
  AvgDialog_118958_Content_38 = {
    Text = "Non credo sia necessario."
  },
  AvgDialog_118958_Content_39 = {
    Text = "Un arpione affilato scocca dalla notte nera come pece, simile alle zanne di un gigantesco squalo, trafiggendo con precisione la gola del timoniere."
  },
  AvgDialog_118958_Content_4 = {
    Text = "Mentre passa davanti alla cabina del Capitano, una voce calma le fluisce nelle orecchie."
  },
  AvgDialog_118958_Content_40 = {
    Text = "Un'enorme lama pesante strappa scintille dal ponte mentre il gigante emerge dalle profondità della notte, fracassando il cranio del timoniere e rivelando un sorriso crudele alla strega dinanzi a lui."
  },
  AvgDialog_118958_Content_41 = {
    Text = "Alle sue spalle, un barbaro avvolto in un impermeabile cerato grigio-azzurro impugna una lama, attendendo avidamente l'ordine di uccidere."
  },
  AvgDialog_118958_Content_42 = {
    Text = "Golia... vedo che ancora ti rifiuti di rinunciare."
  },
  AvgDialog_118958_Content_43 = {
    Text = "Hai radunato questi marinai, orchestrato questo caos... credendo di poter infrangere la pace del nostro Paradise..."
  },
  AvgDialog_118958_Content_44 = {
    Text = "Purtroppo, non farò più parte della vostra pace. Questa volta, la prossima, e ogni volta a venire... i Filistei hanno smesso di inginocchiarsi."
  },
  AvgDialog_118958_Content_45 = {
    Text = "Ascoltatemi, Filistei!"
  },
  AvgDialog_118958_Content_46 = {
    Text = "Rispondendo al suo sinistro richiamo, le figure barbariche avvolte in impermeabili cerati emergono fitte dall'Oscurità dietro Golia, brandendo lame affilate."
  },
  AvgDialog_118958_Content_47 = {
    Text = "I loro profondi ringhi tremano di Euforia. Attendono assetati il momento di ricostituire la loro gloria, in attesa dell'ordine di massacrare ogni cosa."
  },
  AvgDialog_118958_Content_48 = {
    Text = "<Big:Uccideteli!>"
  },
  AvgDialog_118958_Content_49 = {
    Text = "Rozzi canti di guerra squarciano il cielo notturno sopra il mare, mentre le tribù selvagge fanno oscillare le loro corde, schiantandosi sulla Folla sul ponte con velocità accecante."
  },
  AvgDialog_118958_Content_5 = {
    Text = "So chi è il Padrone del Dominio, e posso guidarti a infrangere i confini del Dominio e fare Ritorno al mondo reale."
  },
  AvgDialog_118958_Content_50 = {
    Text = "I Filistei, da lungo tempo sopravvissuti grazie alle razzie costiere, sciamano verso la preda come squali che fiutano il sangue, affondando assetati e feroci le loro lame ricurve nei corpi dei nemici, come denti affilati."
  },
  AvgDialog_118958_Content_51 = {
    Text = "Mio Signore, ascolta le invocazioni dei Tuoi Credenti... Concedi la grazia al Tuo popolo..."
  },
  AvgDialog_118958_Content_52 = {
    Text = "Miryam apre le braccia, e la luce oscura si propaga gradualmente."
  },
  AvgDialog_118958_Content_53 = {
    Text = "I Navigatori in strane vesti nere non emettono alcun suono, simili a un gruppo di devoti fantasmi neri, bagnandosi in silenzio nella profonda Grazia Divina, conficcando in silenzio i loro pugnali nel petto dei nemici."
  },
  AvgDialog_118958_Content_54 = {
    Text = "Grigio-azzurro e viola scuro. Due fazioni nettamente distinte sono impegnate in una lotta mortale in questo inferno in movimento."
  },
  AvgDialog_118958_Content_55 = {
    Text = "Massacrate, miei consanguinei... Ricostituite la gloria dei Filistei!"
  },
  AvgDialog_118958_Content_56 = {
    Text = "La sua lama massiccia recide senza sforzo la testa di un Navigatore che gli sbarra il cammino. Il sangue salmastro che sgorga copioso tinge di Cremisi gran parte del volto di Golia."
  },
  AvgDialog_118958_Content_57 = {
    Text = "Si lecca il sangue dal volto, brandendo l'enorme lama sotto il bagliore dei fulmini, abbattendo ogni Navigatore sul suo cammino."
  },
  AvgDialog_118958_Content_58 = {
    Text = "Il sangue caldo che sgorga viene istantaneamente diluito dal diluvio, mescolandosi con l'acqua di mare, formando scivolosi rivoli cremisi sul ponte che si scuote violentemente."
  },
  AvgDialog_118958_Content_59 = {
    Text = "<Shake:Mio Signore, ho udito il Tuo decreto. I Tuoi Credenti faranno Ritorno nel Reame Divino con Te...>"
  },
  AvgDialog_118958_Content_6 = {
    Text = "Finge di essere calma e si avvicina in silenzio."
  },
  AvgDialog_118958_Content_60 = {
    Text = "Rito, tempesta, massacro..."
  },
  AvgDialog_118958_Content_61 = {
    Text = "Nel cuore di questo Caos, sotto la minacciosa Scultura d'Avorio a prua della nave, Miryam è in piedi, sussurrando devotamente nella tempesta."
  },
  AvgDialog_118958_Content_62 = {
    Text = "Ignora il massacro che la circonda. Un pugnale le sibila accanto all'orecchio, e le onde enormi la inzuppano completamente, eppure lei ne è del tutto inconsapevole."
  },
  AvgDialog_118958_Content_63 = {
    Text = "Che il tuo oracolo ci guidi, che il tuo corpo ci avvolga."
  },
  AvgDialog_118958_Content_64 = {
    Text = "Miryam... Rinuncia! Non possiamo raggiungere Lemuria!"
  },
  AvgDialog_118958_Content_65 = {
    Text = "No... Lui me l'ha promesso, e voi avete udito il Suo Oracolo Divino, non è vero?"
  },
  AvgDialog_118958_Content_66 = {
    Text = "Miryam contempla devotamente l'orizzonte."
  },
  AvgDialog_118958_Content_67 = {
    Text = "La tempesta è il Tuo respiro, il tuono è il Tuo tamburo di battaglia!"
  },
  AvgDialog_118958_Content_68 = {
    Text = "Per questo agnello smarrito, <Big:indica la rotta verso il Tuo regno!>"
  },
  AvgDialog_118958_Content_69 = {
    Text = "Un pallido fulmine squarcia i cieli, illuminando d'un tratto i suoi occhi ferventi e devoti."
  },
  AvgDialog_118958_Content_7 = {
    Text = "Ma la mia assistenza ha delle condizioni."
  },
  AvgDialog_118958_Content_70 = {
    Text = "La bambina avvolta in un velo nero si rannicchia in silenzio in un angolo della prua, il suo sguardo vuoto fissato senza speranza sul campo di battaglia del massacro, come una bambola di pezza gettata in un cumulo di rifiuti."
  },
  AvgDialog_118958_Content_71 = {Text = "Scendiamo!"},
  AvgDialog_118958_Content_72 = {
    Text = "Prendo la statua d'avorio!"
  },
  AvgDialog_118958_Content_73 = {
    Text = "Vado a prendere Murphy!"
  },
  AvgDialog_118958_Content_8 = {
    Text = "Qual è la tua condizione...?"
  },
  AvgDialog_118958_Content_9 = {
    Text = "Uccidi il Padrone del Dominio, impossessati della Scultura d'Avorio e trasferisci a me la proprietà di questo Dominio."
  },
  AvgDialog_118959_Content_1 = {
    Text = "Mi sono uccisa e ho raccolto la corona. Ho ottenuto tutto ciò che desideravo, tranne la libertà."
  },
  AvgDialog_118959_Content_10 = {
    Text = "Non ti abbandonerò, perché tu sei diversa."
  },
  AvgDialog_118959_Content_11 = {
    Text = "Cosa c'è di tanto diverso tra me e loro? Siamo semplici sacrifici ai tuoi occhi, solo cibo per questa carne marcia."
  },
  AvgDialog_118959_Content_12 = {
    Text = "Murphy solleva il grumo sporco tra le mani, il sangue che cola in un rivolo costante."
  },
  AvgDialog_118959_Content_13 = {
    Text = "No, tu SEI diversa."
  },
  AvgDialog_118959_Content_14 = {Text = "Perché..."},
  AvgDialog_118959_Content_15 = {
    Text = "Perché siamo arrivati fin qui insieme."
  },
  AvgDialog_118959_Content_16 = {
    Text = "Ricordo il giorno in cui ti abbiamo impiantato il Feto Divino nel petto; dicesti che volevi dei churros."
  },
  AvgDialog_118959_Content_17 = {
    Text = "Poi decidesti all'improvviso che erano troppo deliziosi per goderteli da sola, e così ne condividesti la metà con me, a malincuore."
  },
  AvgDialog_118959_Content_18 = {
    Text = "In seguito, il Feto Divino cominciò a crescere, e ti venne una febbre alta che non voleva scendere. Tentammo ogni mezzo possibile per abbassare la temperatura, ma alla fine non avemmo altra scelta che trasportarti nella cella glaciale in Antartide."
  },
  AvgDialog_118959_Content_19 = {
    Text = "Ci ha causato non pochi problemi."
  },
  AvgDialog_118959_Content_2 = {
    Text = "Ma io, che ho dato alla luce il Feto Divino, non sono stata in grado di ricevere la Sua benedizione. Non sono riuscita a guidare il sentiero verso Lemuria..."
  },
  AvgDialog_118959_Content_20 = {
    Text = "Anche in un ambiente così pericoloso, continuasti ad adempiere ai tuoi doveri di Madre Divina."
  },
  AvgDialog_118959_Content_21 = {
    Text = "La maggior parte dei sacerdoti sopportò il freddo pungente, accompagnando, attendendo e pregando all'altare in Antartide."
  },
  AvgDialog_118959_Content_22 = {
    Text = "E tu hai onorato le aspettative di tutti, divenendo il primo ricettacolo a dare alla luce il Feto Divino."
  },
  AvgDialog_118959_Content_23 = {
    Text = "Siamo giunti a quel momento insieme."
  },
  AvgDialog_118959_Content_24 = {
    Text = "E insieme salperemo verso l'Eterno Reame Divino."
  },
  AvgDialog_118959_Content_25 = {
    Text = "Lentamente e con fermezza, Miryam cammina davanti a Murphy, chinandosi."
  },
  AvgDialog_118959_Content_26 = {
    Text = "Tu sei la venerata Madre Divina, e io sono disposta a inginocchiarmi ai tuoi piedi per l'eternità, offrendoti la mia devozione di una vita intera."
  },
  AvgDialog_118959_Content_27 = {
    Text = "Sono disposta a guardarti per sempre dal basso con la reverenza riservata al mio Signore."
  },
  AvgDialog_118959_Content_28 = {
    Text = "Murphy fissa Miryam con sguardo vacuo."
  },
  AvgDialog_118959_Content_29 = {
    Text = "Miryam si inginocchia, prende la mano di Murphy e vi posa un bacio devoto."
  },
  AvgDialog_118959_Content_3 = {
    Text = "Così hai creato questo sogno senza fine..."
  },
  AvgDialog_118959_Content_30 = {
    Text = "Torna al mio fianco, vuoi? Nostra Madre Divina?"
  },
  AvgDialog_118959_Content_31 = {
    Text = "Murphy abbassa il capo. I venti si arrestano, e il silenzio regna sulla piccola fenditura cosmica."
  },
  AvgDialog_118959_Content_32 = {
    Text = [[
Le tue storie non hanno mai parlato di me. Parlavano del Feto Divino.
Le tue parole non erano mai rivolte a me. Erano rivolte alla Madre Divina.]]
  },
  AvgDialog_118959_Content_33 = {
    Text = "Ancora non capisci... e non capirai mai..."
  },
  AvgDialog_118959_Content_34 = {
    Text = "Qualche delirio sfugge dalle sue labbra tremanti."
  },
  AvgDialog_118959_Content_35 = {
    Text = "Tu che conosci soltanto preghiere, riti, il Reame Divino, Lemuria e la rinascita del tuo dio..."
  },
  AvgDialog_118959_Content_36 = {
    Text = "Non capirai mai, mai."
  },
  AvgDialog_118959_Content_37 = {
    Text = "Tutto ciò che ho costruito — questa destinazione finale che ho lottato tanto per raggiungere, questa illusione che mi sono sforzata tanto di mantenere... L'ho fatto tutto per un'unica ragione."
  },
  AvgDialog_118959_Content_38 = {
    Text = "Perché tu mi riconoscessi davvero, finalmente. Perché io potessi... finalmente chiamarti..."
  },
  AvgDialog_118959_Content_39 = {Text = "Madre..."},
  AvgDialog_118959_Content_4 = {
    Text = "Se non l'avessi fatto, mi avrebbe sicuramente strappato il cuore..."
  },
  AvgDialog_118959_Content_40 = {
    Text = "I venti furiosi sommergono i suoi sussurri già indistinti."
  },
  AvgDialog_118959_Content_41 = {
    Text = "Ha... Che peccato."
  },
  AvgDialog_118959_Content_42 = {
    Text = "Murphy ricaccia le lacrime con un morso."
  },
  AvgDialog_118959_Content_43 = {
    Text = "Le mie aspettative erano vane. L'equilibrio che ho creato è una menzogna, un'illusione eterna."
  },
  AvgDialog_118959_Content_44 = {
    Text = "Non sarai mai mia madre."
  },
  AvgDialog_118959_Content_45 = {
    Text = "La Murphy che conoscevi è morta. È morta il giorno in cui il tuo dio è nato."
  },
  AvgDialog_118959_Content_46 = {
    Text = "Ciò che ora ti sta dinanzi è una Risvegliatrice, forgiata dalle sue ceneri e da uno Spirito d'Argento."
  },
  AvgDialog_118959_Content_47 = {
    Text = "E la persona che mi ha risvegliata dal mio stesso cadavere... No, si può davvero chiamare persona?"
  },
  AvgDialog_118959_Content_48 = {
    Text = "Il mio <Blue:Connettore> è qui, proprio davanti a te."
  },
  AvgDialog_118959_Content_49 = {
    Text = "Solleva delicatamente il panno che avvolge il neonato. Sul suo volto, cogli un'espressione di insolita tenerezza — così profonda da risultare quasi terrificante."
  },
  AvgDialog_118959_Content_5 = {
    Text = "...e sacrificarmi al suo venerato re."
  },
  AvgDialog_118959_Content_50 = {
    Text = "L'ho portato in questo mondo... e lui ha riportato me indietro..."
  },
  AvgDialog_118959_Content_51 = {
    Text = "Un fato di deviazione, eternamente intrecciato. Un ciclo distorto che non ha mai fine."
  },
  AvgDialog_118959_Content_52 = {
    Text = "Il Padre genera una Figlia. La Figlia poi concepisce Suo Padre. E il Padre risveglia Sua Figlia ancora una volta..."
  },
  AvgDialog_118959_Content_53 = {
    Text = "Non c'è nessuno che possa recidere questo legame contorto. Nulla può spezzare l'eterno uroboro della nostra stirpe."
  },
  AvgDialog_118959_Content_54 = {
    Text = "Credi di essere la prima persona a restare intrappolata in questo Ciclo Temporale?"
  },
  AvgDialog_118959_Content_55 = {
    Text = "Ho vissuto i suoi orrori più volte di quante ne possa contare. Ogni Ciclo è Terminato in un Incubo indicibile."
  },
  AvgDialog_118959_Content_56 = {
    Text = "Una volta, Miryam mi ha pugnalata al petto perché avevo rifiutato il richiamo di Lemuria."
  },
  AvgDialog_118959_Content_57 = {
    Text = "Una volta, sono stata imprigionata da Golia, e la Scultura d'Avorio mi è stata sottratta, causando l'affondamento dell'intera nave."
  },
  AvgDialog_118959_Content_58 = {
    Text = "Una volta, in un certo Sogno, una persona fragile ma determinata ha aperto un varco per la mia Fuga."
  },
  AvgDialog_118959_Content_59 = {
    Text = [[
Ma ho sempre creduto che quelli non fossero i veri finali. 
Stavo aspettando quello che appartiene unicamente a <Italic:questa versione di me>.]]
  },
  AvgDialog_118959_Content_6 = {
    Text = "Così quando Golia disse che mi stava aspettando... non capii."
  },
  AvgDialog_118959_Content_60 = {
    Text = "L'Attesa è finita. Questo è il vero finale che scelgo."
  },
  AvgDialog_118959_Content_61 = {
    Text = "Lascia che questa nave si capovolga."
  },
  AvgDialog_118959_Content_62 = {
    Text = "Un sipario nero, come seta riversata dai cieli, discende dal sole nero privo di luce, avvolgendo la nave e isolandola dal mondo esterno."
  },
  AvgDialog_118959_Content_63 = {
    Text = "L'acqua marina si solleva in un'Ondata, seppellendo l'intera nave da crociera nell'Abisso oscuro."
  },
  AvgDialog_118959_Content_64 = {
    Text = "Sei, ancora una volta, intrappolato nell'Oscurità sconfinata."
  },
  AvgDialog_118959_Content_7 = {
    Text = "<Shake:Perché? Miryam, perché?>"
  },
  AvgDialog_118959_Content_8 = {
    Text = "Se non sono una Madre Divina all'altezza, perché non sbarazzarti di me come hai fatto con le altre?"
  },
  AvgDialog_118959_Content_9 = {
    Text = "<Red:Scartami... concedimi la libertà...>"
  },
  AvgDialog_118960_Content_1 = {
    Text = "Velo Eterno"
  },
  AvgDialog_118960_Content_10 = {
    Text = "No, sono sempre stata in grado di manipolare ogni cosa nel sogno. Posso decidere quando i cicli finiscono e iniziano, io..."
  },
  AvgDialog_118960_Content_11 = {
    Text = "Nostro Signore vi ha prestato il potere di sognare, eppure siete intrappolata nella vostra Ossessione, sperperando la Sua benevolenza."
  },
  AvgDialog_118960_Content_12 = {Text = "Lent...?"},
  AvgDialog_118960_Content_13 = {
    Text = "Ricordi da dove proveniva quella scultura?"
  },
  AvgDialog_118960_Content_14 = {
    Text = "La scultura... Il suo idolo..."
  },
  AvgDialog_118960_Content_15 = {
    Text = "Quando ha dato alla luce... il Feto Divino..."
  },
  AvgDialog_118960_Content_16 = {
    Text = "No, non ho mai visto questa Scultura durante la prima settimana dopo la nascita del Feto Divino."
  },
  AvgDialog_118960_Content_17 = {
    Text = "Il suo idolo... è..."
  },
  AvgDialog_118960_Content_18 = {
    Text = "Non c'è da stupirsi che abbia sempre avvertito un pezzo mancante nell'enigma."
  },
  AvgDialog_118960_Content_19 = {
    Text = [[
%player%, ricordi la nostra deduzione dell'ultima volta?
Questo Dominio dovrebbe essersi formato prima che la Dissoluzione consumasse questo mondo, prima che il sole diventasse nero.]]
  },
  AvgDialog_118960_Content_2 = {
    Text = "<Red:Non deve finire qui.>"
  },
  AvgDialog_118960_Content_20 = {
    Text = "Ma la Nascita del Feto Divino, e il Sacrificio e la Rinascita dalla Terra di Murphy, sono chiaramente avvenuti dopo."
  },
  AvgDialog_118960_Content_21 = {
    Text = "In altre parole, Murphy a quel tempo era solo un essere umano spiritualmente vibrante. Non era abbastanza Forte da costruire questo Sogno."
  },
  AvgDialog_118960_Content_22 = {
    Text = "Colui che deteneva l'Autorità prima di allora... Deve essere stato..."
  },
  AvgDialog_118960_Content_23 = {
    Text = "Il Re-Dio di questo mondo è nato da tempo... No, piuttosto, non è mai morto."
  },
  AvgDialog_118960_Content_24 = {
    Text = "Non siete riuscita a risvegliare la Sua coscienza perché Egli è ancora nel Sonno Profondo di un sogno."
  },
  AvgDialog_118960_Content_25 = {
    Text = "Non voleva che voi periste a causa del sacrificio, così ha appositamente separato un filo della Sua forza per creare un sogno dentro il sogno per voi."
  },
  AvgDialog_118960_Content_26 = {
    Text = "Ma voi desideravate troppo. Così il sogno continua a crollare e ricominciare; questa è l'essenza del Paradise."
  },
  AvgDialog_118960_Content_27 = {
    Text = "È nato dal vostro desiderio, ma non è il vostro Schiavo..."
  },
  AvgDialog_118960_Content_28 = {
    Text = "<Yellow:Ora, si appresta a compiere la missione che il Creatore Le ha affidato.>"
  },
  AvgDialog_118960_Content_29 = {
    Text = "Il cielo inizia a convulsare; un velo nero avvolge la Visuale, e un corpo mastodontico si erge come una montagna."
  },
  AvgDialog_118960_Content_3 = {Text = "?!"},
  AvgDialog_118960_Content_30 = {
    Text = "Non emerge dall'Abisso sottostante, ma piuttosto, la pura Volontà di un essere superiore squarcia il confine tra le Dimensioni."
  },
  AvgDialog_118960_Content_31 = {
    Text = "Sotto la cupola soffocante, i Suoi arti appaiono in silenzio: pallidi, esili, con le giunture contorte, come le ossa torturate e deformi di un Martire."
  },
  AvgDialog_118960_Content_32 = {
    Text = "<Big:<Shake:...!!!>>"
  },
  AvgDialog_118960_Content_33 = {Text = "Murphy..."},
  AvgDialog_118960_Content_34 = {
    Text = "Il volto di quell'immenso Mostro somiglia chiaramente alla fanciulla che conoscete così bene."
  },
  AvgDialog_118960_Content_35 = {
    Text = "<Red:Il sogno... deve... continuare...>"
  },
  AvgDialog_118960_Content_4 = {
    Text = "<Red:Non può finire qui.>"
  },
  AvgDialog_118960_Content_5 = {
    Text = "Il cielo comincia a ricucirsi, con una garza nera che oscura il sole e si raccoglie in un cielo fittizio."
  },
  AvgDialog_118960_Content_6 = {
    Text = "Clic. Clic. Senti di nuovo il suono della ruota che gira."
  },
  AvgDialog_118960_Content_7 = {
    Text = "Perché? Perché? Avevo già deciso di porre fine a questo sogno..."
  },
  AvgDialog_118960_Content_8 = {
    Text = "Perché... stimata Madre Divina, voi non siete la padrona di questo sogno."
  },
  AvgDialog_118960_Content_9 = {Text = "??!!"},
  AvgDialog_118961_Content_1 = {
    Text = "Il Falsonato"
  },
  AvgDialog_118961_Content_10 = {
    Text = "Sorpreso? L'unica via di fuga da questa nave è sempre stata sotto il mio controllo."
  },
  AvgDialog_118961_Content_11 = {
    Text = [[
Golia afferra Murphy, premendole la lama gigante contro la gola. 
Il sangue le scorre lungo il collo e si raccoglie nella cicatrice eternamente aperta sul suo petto.]]
  },
  AvgDialog_118961_Content_12 = {Text = "Murphy!"},
  AvgDialog_118961_Content_13 = {
    Text = "Madre Divina!"
  },
  AvgDialog_118961_Content_14 = {
    Text = "Scusa... Non riuscivo a smettere di preoccuparmi per te, così sono tornata..."
  },
  AvgDialog_118961_Content_15 = {
    Text = "Non è Miryam a non voler lasciar andare questa ragazza. È lei che tiene Miryam al suo posto."
  },
  AvgDialog_118961_Content_16 = {
    Text = "O si rifiuta di lasciar scoprire a Miryam la verità, o non riesce a permetterlo, o semplicemente ha troppa paura di ciò che potrebbe accadere."
  },
  AvgDialog_118961_Content_17 = {
    Text = "Qual è La Verità di cui parli?"
  },
  AvgDialog_118961_Content_18 = {
    Text = "Non sa nemmeno dove si trovi quella Lemuria; non ha mai visto la vera forma di Dio."
  },
  AvgDialog_118961_Content_19 = {
    Text = "Poiché lei non lo sa, questa nave può solo vagare per il mare, vagare così, per sempre."
  },
  AvgDialog_118961_Content_2 = {
    Text = "Dunque, in questo momento in cui il tuo dio è già nato, perché ti aggrappi ancora a Murphy?"
  },
  AvgDialog_118961_Content_20 = {
    Text = "Non so che genere di parole abbia usato questa ragazzina per incantare voi due..."
  },
  AvgDialog_118961_Content_21 = {
    Text = "Somma Sacerdotessa dei Navigatori. Una persona misteriosa apparsa dal nulla. Vi state facendo raggirare entrambi da una ragazzina."
  },
  AvgDialog_118961_Content_22 = {
    Text = "Ricordate cosa accadde quando tentò di fuggire? Non ditemi che l'avete dimenticato."
  },
  AvgDialog_118961_Content_23 = {Text = "Correre."},
  AvgDialog_118961_Content_24 = {
    Text = "Murphy stava correndo."
  },
  AvgDialog_118961_Content_25 = {
    Text = "Non conosceva la destinazione del viaggio, né sapeva se sarebbe riuscita a sfuggire alla vigilanza della sua Madrina."
  },
  AvgDialog_118961_Content_26 = {
    Text = "<Shake:Ahh, ahh...>"
  },
  AvgDialog_118961_Content_27 = {
    Text = "Nessuno l'attendeva più avanti. Alle sue spalle, il sinistro, eppure vagamente comico, suono di pinne che battevano il suolo si faceva fitto e insistente."
  },
  AvgDialog_118961_Content_28 = {
    Text = "La notizia della scomparsa della Fanciulla Divina si era propagata; i Navigatori si stavano radunando."
  },
  AvgDialog_118961_Content_29 = {
    Text = "Maledizione, questi fastidiosi bastardi."
  },
  AvgDialog_118961_Content_3 = {
    Text = "La interroghi con tenacia."
  },
  AvgDialog_118961_Content_30 = {
    Text = "Dietro il lampo di luce, la figura in veste purpurea, simbolo del suo fallimento, apparve con inquietante compostezza..."
  },
  AvgDialog_118961_Content_31 = {Text = "..."},
  AvgDialog_118961_Content_32 = {
    Text = "La Murphy di questo mondo non ce l'ha fatta."
  },
  AvgDialog_118961_Content_33 = {
    Text = "Perché la persona che l'aveva mandata dai Navigatori, e che poi si era pentita e l'aveva aiutata a fuggire..."
  },
  AvgDialog_118961_Content_34 = {
    Text = "Era già svanita per sempre nel disastro della Dissoluzione."
  },
  AvgDialog_118961_Content_35 = {
    Text = "Lei non è diventata la Madre Divina per sua volontà. Così come io non sono diventato il vostro schiavo per mia volontà."
  },
  AvgDialog_118961_Content_36 = {
    Text = "Siamo tutti in caccia di... ciò che desideriamo per noi stessi."
  },
  AvgDialog_118961_Content_37 = {
    Text = "<Shake:No, non voglio niente.> Io... non voglio assolutamente niente."
  },
  AvgDialog_118961_Content_38 = {
    Text = "Non vuoi nulla? No, vuoi TROPPE COSE."
  },
  AvgDialog_118961_Content_39 = {
    Text = "Vuoi la vita privilegiata della Madre Divina, ma non vuoi assumerti le responsabilità di essere una guida."
  },
  AvgDialog_118961_Content_4 = {
    Text = "Mi sto aggrappando a Murphy... Cosa intendi?"
  },
  AvgDialog_118961_Content_40 = {
    Text = "Hai paura di essere abbandonata, perciò tratti gli altri come marionette nella tua vita, come giocattoli per la tua casetta delle bambole."
  },
  AvgDialog_118961_Content_41 = {
    Text = "Di tanto in tanto, cancelli la memoria di tutti sulla nave e dai inizio a un nuovo ciclo."
  },
  AvgDialog_118961_Content_42 = {
    Text = "Ragazzina, lascia che ti dica una cosa: non fare la furba, ogni cosa in questo mondo ha un prezzo."
  },
  AvgDialog_118961_Content_43 = {
    Text = "Pensavi che nessuno avrebbe mai scoperto i tuoi trucchetti? Pensavi che con quella scultura d'avorio avresti potuto fare qualsiasi cosa?"
  },
  AvgDialog_118961_Content_44 = {
    Text = "Murphy stringe la Scultura d'Avorio nella Mano."
  },
  AvgDialog_118961_Content_45 = {
    Text = "Smettila di fare sciocchezze, bambina stolida."
  },
  AvgDialog_118961_Content_46 = {
    Text = "Credi che non sapessi nulla delle tue azioni? Semplicemente non ero pronta ad affrontarti allora."
  },
  AvgDialog_118961_Content_47 = {
    Text = "In ogni ciclo, ho cercato di cambiare il metodo del colpo. Minacciare te, minacciare Miryam, far saltare in aria la sala macchine..."
  },
  AvgDialog_118961_Content_48 = {
    Text = "In seguito, ho scoperto che finché quella maledetta scultura d'avorio era presente, non avevo alcuna possibilità di oppormi a te."
  },
  AvgDialog_118961_Content_49 = {
    Text = "La risatina di Golia riecheggia per il ponte."
  },
  AvgDialog_118961_Content_5 = {
    Text = "Sei tu che hai costruito questo Sogno e hai Intrappolato Murphy in un Ciclo, non è vero?"
  },
  AvgDialog_118961_Content_50 = {
    Text = "Fino a qualche mese fa. La nostra operazione a Necrovia è andata in rovina, tutto a causa di {Male=questo ragazzo,Female=questa ragazza} davanti a noi."
  },
  AvgDialog_118961_Content_51 = {
    Text = "Non siamo riusciti a catturare abbastanza Argento. Il potere di quella scultura d'avorio si è indebolito, e i Risvegliati su questa nave hanno cominciato a ricordare tutto."
  },
  AvgDialog_118961_Content_52 = {
    Text = "Ricordate tutto... Significa che tutti voi ricordate?"
  },
  AvgDialog_118961_Content_53 = {
    Text = "Quindi William non ricorda unicamente perché proviene da un altro mondo..."
  },
  AvgDialog_118961_Content_54 = {
    Text = "Gli altri Risvegliati non sono diversi da me... Sono consapevoli di ciò che è accaduto, degli stessi eventi che si ripetono in un ciclo senza fine..."
  },
  AvgDialog_118961_Content_55 = {
    Text = "<Small:<Shake:Il \"tutti\" che hai menzionato... include... lei?>>"
  },
  AvgDialog_118961_Content_56 = {
    Text = "Murphy abbassa lo sguardo, la voce così flebile da essere quasi inudibile. Il suo sguardo tremola incerto, spesso vagando verso la donna accanto a lei, ma si raccoglie prima di poter incontrare i suoi occhi."
  },
  AvgDialog_118961_Content_57 = {
    Text = "Sciocca Bambina, ho detto tutti i Risvegliati."
  },
  AvgDialog_118961_Content_58 = {
    Text = "Inclusa quella stupida Donna, Miryam, naturalmente."
  },
  AvgDialog_118961_Content_59 = {
    Text = "Quindi intendi dire..."
  },
  AvgDialog_118961_Content_6 = {
    Text = "Miryam pondera le tue parole. Prima che possa parlare, un profondo sbuffo di scherno riecheggia alle tue spalle."
  },
  AvgDialog_118961_Content_60 = {
    Text = "Miryam ricorda ogni ciclo. Tutto ciò che è mai accaduto. E in ognuno di essi, attende... che tu cambi idea."
  },
  AvgDialog_118961_Content_61 = {
    Text = "Sogno l'altro mondo da quando il nostro piccolo ospite è arrivato. Ho visto come finisce. E scommetto che anche Miryam l'ha visto."
  },
  AvgDialog_118961_Content_62 = {
    Text = "<Blue:Lei sa tutto ciò che fai.> Ma in ogni ciclo, non interviene mai. Si limita ad... aspettare. E aspettare."
  },
  AvgDialog_118961_Content_63 = {
    Text = "Golia inclina il capo verso la silenziosa Miryam al suo fianco."
  },
  AvgDialog_118961_Content_64 = {
    Text = "Credevi di averla intrappolata nella tua prigione? <Blue:Lei resta lì per scelta.>"
  },
  AvgDialog_118961_Content_65 = {
    Text = "Miryam risponde alle speculazioni di Golia con il silenzio."
  },
  AvgDialog_118961_Content_66 = {
    Text = "<Shake:Perché? Non capisco perché?>"
  },
  AvgDialog_118961_Content_67 = {
    Text = "Non dovrei essere un prodotto fallito, uno strumento usa e getta per te?"
  },
  AvgDialog_118961_Content_68 = {
    Text = "Non dovresti abbandonarmi come hai abbandonato loro?"
  },
  AvgDialog_118961_Content_7 = {
    Text = "Lascia che ti racconti."
  },
  AvgDialog_118961_Content_8 = {
    Text = "<Shake:Perché questa ragazzina di nome Murphy è una bugiarda.>"
  },
  AvgDialog_118961_Content_9 = {
    Text = "Guidata dai Filistei, la folla apre una piccola breccia attraverso cui un marinaio spinge fuori la Murphy assediata."
  },
  AvgDialog_118962_Content_1 = {
    Text = "Chiudi la porta della cabina di pilotaggio, assicuri il chiavistello e ascolti i passi degli inseguitori allontanarsi in un'altra direzione, prima di voltarti a osservare il tuo piccolo ostaggio."
  },
  AvgDialog_118962_Content_10 = {
    Text = "Se non sono ai loro posti... dove potrebbero essere?"
  },
  AvgDialog_118962_Content_11 = {
    Text = "Conoscendo il carattere di Golia, probabilmente non stanno a oziare al casinò sotterraneo."
  },
  AvgDialog_118962_Content_12 = {
    Text = "Deve star tramando qualcosa in segreto..."
  },
  AvgDialog_118962_Content_13 = {
    Text = "Nel frattempo, William si prepara allo scontro nella camera da letto di Murphy."
  },
  AvgDialog_118962_Content_14 = {
    Text = "Anche se sono solo io, posso almeno trattenerli per venti minuti... è sufficiente..."
  },
  AvgDialog_118962_Content_15 = {
    Text = "I passi si fanno improvvisamente radi."
  },
  AvgDialog_118962_Content_16 = {
    Text = "Vi salutiamo, Vostra Santità la Somma Sacerdotessa!"
  },
  AvgDialog_118962_Content_17 = {
    Text = "Abbiamo intrappolato gli intrusi nella camera della Madre Divina! Basta dare l'ordine..."
  },
  AvgDialog_118962_Content_18 = {
    Text = "Non c'è bisogno. La Madre Divina non è più qui."
  },
  AvgDialog_118962_Content_19 = {
    Text = "(Mi hanno trovato?!)"
  },
  AvgDialog_118962_Content_2 = {Text = "Hmph..."},
  AvgDialog_118962_Content_20 = {
    Text = "Ora, signore nascosto in questa stanza... perché non facciamo due chiacchiere?"
  },
  AvgDialog_118962_Content_21 = {
    Text = "Di cosa vuoi parlare?"
  },
  AvgDialog_118962_Content_22 = {
    Text = "Che si tratti di voi o dei vostri amici, da quando siete saliti a bordo, tutti i Navigatori vi hanno trattato con sacro rispetto."
  },
  AvgDialog_118962_Content_23 = {
    Text = "Eppure ripagate la gentilezza con l'ostilità, rapendo la Madre Divina, impedendo che il cruciale rito di navigazione si svolga nei tempi previsti."
  },
  AvgDialog_118962_Content_24 = {
    Text = "Se perdiamo questo Allineamento Stellare, la nostra grande ambizione dovrà attendere altri sessanta cicli stellari."
  },
  AvgDialog_118962_Content_25 = {
    Text = "Deve esserci una ragione per tale impudenza, e vorrei ascoltare le spiegazioni di entrambi."
  },
  AvgDialog_118962_Content_26 = {
    Text = "A causa del Ciclo Temporale vissuto dal Custode? Perché quella bambina era un tempo parte di Mythag?"
  },
  AvgDialog_118962_Content_27 = {
    Text = "William non ha ancora formulato una risposta quando un suono nauseante, viscido e strisciante giunge improvvisamente da dietro di lui."
  },
  AvgDialog_118962_Content_28 = {
    Text = "Si volta — le sue pupille si contraggono in un istante. Diversi uomini-pesce sfondano l'intera finestra come un'ondata di lordura."
  },
  AvgDialog_118962_Content_29 = {
    Text = "Arti contorti si accalcano gli uni sugli altri, facendosi largo nella stanza; una cascata di fluidi corporei fetidi e viscosi si riversa giù, inzuppando all'istante il tappeto in una palude scivolosa."
  },
  AvgDialog_118962_Content_3 = {
    Text = "Tira fuori da qualche parte un piccolo specchio e si sistema meticolosamente le ciocche ribelli sulla fronte."
  },
  AvgDialog_118962_Content_30 = {
    Text = "È inchiodato saldamente nel punto di morte in cui due maree furiose stanno per convergere."
  },
  AvgDialog_118962_Content_31 = {
    Text = "Come hai..."
  },
  AvgDialog_118962_Content_32 = {
    Text = "L'oblò si trova a oltre dieci metri di altezza dal ponte, e %player% hanno tagliato rapidamente la lunga fune dopo essere fuggiti."
  },
  AvgDialog_118962_Content_33 = {
    Text = "Come hanno fatto a scivolare silenziosamente lungo le pareti lisce fino alla finestra?"
  },
  AvgDialog_118962_Content_34 = {
    Text = "Il Reame Divino ci concede la forza per resistere al cataclisma, e ostacoli così insignificanti non possono certo fermare i Navigatori."
  },
  AvgDialog_118962_Content_35 = {
    Text = "Vita marina... Hanno ventose sugli arti?"
  },
  AvgDialog_118962_Content_36 = {
    Text = "Oltre ai Navigatori di stanza sulla nave da crociera, le creature marine che circondano questo vascello sono tutte attratte dal richiamo spirituale del nostro Signore, e obbediscono ai nostri comandi."
  },
  AvgDialog_118962_Content_37 = {
    Text = "Anche senza tutto questo, dovresti sapere che non puoi difenderti dall'intera Chiesa dei Navigatori da questa piccola stanza..."
  },
  AvgDialog_118962_Content_38 = {
    Text = "Un Investigatore del Mythag non dovrebbe essere così avventato... Dimmi, cos'altro sai?"
  },
  AvgDialog_118962_Content_39 = {
    Text = "<Big:<Shake:BOOM—>>"
  },
  AvgDialog_118962_Content_4 = {
    Text = "Dov'è quella struttura di cui parlavi...?"
  },
  AvgDialog_118962_Content_40 = {
    Text = "Un assordante stridio metallico di lamiere che si lacerano squarcia il cielo, accompagnato da un violento tremore, come se una mano gigantesca e invisibile afferrasse d'improvviso la nave e la torcesse senza pietà!"
  },
  AvgDialog_118962_Content_41 = {
    Text = "Che cosa sta succedendo?!"
  },
  AvgDialog_118962_Content_42 = {
    Text = "Qualcuno sta alterando la rotta con la forza!"
  },
  AvgDialog_118962_Content_43 = {
    Text = "La nave gigantesca si torce e rolla come una bestia inferocita e incontrollabile tra le onde mostruose del mare notturno, e ogni violento tremore sembra squarciare lo scafo!"
  },
  AvgDialog_118962_Content_44 = {
    Text = "La sala macchine... È la sala macchine!"
  },
  AvgDialog_118962_Content_45 = {
    Text = "Golia ha preso degli ostaggi e ha occupato quel luogo!"
  },
  AvgDialog_118962_Content_46 = {
    Text = "Sta succedendo di nuovo..."
  },
  AvgDialog_118962_Content_47 = {
    Text = "Tremori violenti arrivano a ondate."
  },
  AvgDialog_118962_Content_48 = {Text = "Murphy..."},
  AvgDialog_118962_Content_49 = {
    Text = "Lo so. Sei preoccupato per il tuo Senior William, vero?"
  },
  AvgDialog_118962_Content_5 = {
    Text = "Proprio sotto il sedile del capitano, qui."
  },
  AvgDialog_118962_Content_50 = {
    Text = "Certo che vuoi andare ad aiutarlo. Tutti mi dicono che sono la persona più importante... fino al momento in cui devono scegliere."
  },
  AvgDialog_118962_Content_51 = {Text = "Io..."},
  AvgDialog_118962_Content_52 = {
    Text = "Lascia perdere. Erano solo vaneggiamenti inutili. A malapena ci conosciamo, del resto, no?"
  },
  AvgDialog_118962_Content_53 = {
    Text = "Inoltre, se quella sala macchine esplode, si porterà dietro l'intero ponte inferiore."
  },
  AvgDialog_118962_Content_54 = {
    Text = "Non abbiamo più scelta. Andiamo."
  },
  AvgDialog_118962_Content_6 = {
    Text = "Calpesta la piastra di ferro sotto i suoi piedi."
  },
  AvgDialog_118962_Content_7 = {
    Text = "Tuttavia, questo posto sembra un po' strano..."
  },
  AvgDialog_118962_Content_8 = {
    Text = "A quest'ora, Golia e Caecus dovrebbero essere di guardia in cabina di pilotaggio."
  },
  AvgDialog_118962_Content_9 = {
    Text = "Prima del rito, le creature marine diventano irrequiete; dobbiamo impedire che i pesci disturbino la rotta della nave..."
  },
  AvgDialog_118963_Content_1 = {
    Text = "Il giorno libero della Deipara"
  },
  AvgDialog_118963_Content_10 = {
    Text = "Vuoi dire..."
  },
  AvgDialog_118963_Content_11 = {
    Text = "Sì, puoi ancora essere la Madre Divina. Ma anche la Madre Divina può prendersi un giorno di riposo."
  },
  AvgDialog_118963_Content_12 = {
    Text = "Menti senza battere ciglio."
  },
  AvgDialog_118963_Content_13 = {
    Text = "Un giorno libero?"
  },
  AvgDialog_118963_Content_14 = {
    Text = "Sì. Mi è stato detto di portarti in giro per la nave e farti rilassare per un giorno."
  },
  AvgDialog_118963_Content_15 = {
    Text = "Non hai mai sperimentato la Vita di un membro dell'equipaggio qualunque, vero?"
  },
  AvgDialog_118963_Content_16 = {
    Text = "Hai fermamente \"invitato\" Murphy fuori dalla camera da letto, senza lasciare spazio a rifiuti."
  },
  AvgDialog_118963_Content_17 = {
    Text = "Dobbiamo davvero arrampicarci fino a un posto del genere?"
  },
  AvgDialog_118963_Content_18 = {
    Text = "Sbrigati! La Visuale è buona quassù. Possiamo osservare i Navigatori di pattuglia."
  },
  AvgDialog_118963_Content_19 = {
    Text = "Se continui a essere così lento, ti prenderanno!"
  },
  AvgDialog_118963_Content_2 = {
    Text = "Apri gli occhi. Il Sole accecante li fa dolere."
  },
  AvgDialog_118963_Content_20 = {
    Text = "Ma che stai dicendo... metti tutto sottosopra!"
  },
  AvgDialog_118963_Content_21 = {
    Text = "Nonostante le lamentele, ti porge obbediente la Mano. Con un leggero strattone, la sollevi senza sforzo sulla piattaforma."
  },
  AvgDialog_118963_Content_22 = {Text = "Puff—"},
  AvgDialog_118963_Content_23 = {
    Text = "Murphy scoppia a ridere all'improvviso."
  },
  AvgDialog_118963_Content_24 = {
    Text = "Di cosa ridi?"
  },
  AvgDialog_118963_Content_25 = {
    Text = "Tu che ti arrampichi sulle sartie sembri proprio una scimmia!"
  },
  AvgDialog_118963_Content_26 = {
    Text = "Tu, se non fosse che adesso bisogna tenere il volume basso, ti farei sicuramente un bel bernoccolo sulla fronte..."
  },
  AvgDialog_118963_Content_27 = {
    Text = "Smettila di ridere! Vieni a nasconderti qui!"
  },
  AvgDialog_118963_Content_28 = {
    Text = "Afferri la Mano di Murphy e la tiri verso di te."
  },
  AvgDialog_118963_Content_29 = {
    Text = "Ehi, come osi!"
  },
  AvgDialog_118963_Content_3 = {
    Text = "Ma tu non distogli lo Sguardo."
  },
  AvgDialog_118963_Content_30 = {Text = "Shh!"},
  AvgDialog_118963_Content_31 = {
    Text = "Trattenete entrambi il respiro. Un gruppo di Navigatori avanza barcollando sul ponte, avvolti in mantelle di paglia logore e sudice."
  },
  AvgDialog_118963_Content_32 = {
    Text = "Sbrigatevi a trovare la Madre Divina! Dev'essere su questa nave!"
  },
  AvgDialog_118963_Content_33 = {
    Text = "Siamo proprio sopra di loro e non riescono a vederci affatto?"
  },
  AvgDialog_118963_Content_34 = {
    Text = "Chissà perché le ronde non guardano mai in alto. È quasi un cliché, o qualcosa del genere."
  },
  AvgDialog_118963_Content_35 = {
    Text = "Tranquilli, finché restiamo nascosti qui, nessuno ci troverà mai."
  },
  AvgDialog_118963_Content_36 = {
    Text = "Glu glu! Guardate lassù, ci sono delle persone!"
  },
  AvgDialog_118963_Content_37 = {
    Text = "La tua iella doveva proprio essere così precisa, vero!"
  },
  AvgDialog_118963_Content_38 = {
    Text = "Piano con la voce. Dopo che li avremo eliminati, sgattaioliamo verso gli alloggi dell'equipaggio!"
  },
  AvgDialog_118963_Content_4 = {
    Text = "Frusciare, frusciare, è il suono di un ragno che striscia. Sembra il dolce richiamo di una madre."
  },
  AvgDialog_118963_Content_5 = {
    Text = "Non c'è bisogno di ricordarmelo. So che questo è l'ultimo ciclo."
  },
  AvgDialog_118963_Content_6 = {
    Text = "Asciughi le lacrime che ti erano affiorate agli angoli degli occhi e ti volti verso la direzione da cui proviene il richiamo, senza più curarti di voltarti indietro a confermare l'origine del canto."
  },
  AvgDialog_118963_Content_7 = {
    Text = "Sai che la donna al telaio ti sta certamente osservando con compassione negli occhi."
  },
  AvgDialog_118963_Content_8 = {
    Text = "Che ci fai qui? Le loro Memorie sono state completamente cancellate da me. La Navigazione della nave riprende, e non c'è più posto per te qui."
  },
  AvgDialog_118963_Content_9 = {
    Text = "Non importa. Tu sei la Madre Divina dei Navigatori, il Capitano del Paradise e la padrona di questo Dominio. Questo non ha nulla a che fare con la Rottura che voglio concederti."
  },
  AvgDialog_119922_Content_1 = {
    Text = "Bentornato, partner."
  },
  AvgDialog_119922_Content_10 = {
    Text = "Va tutto bene, mio signore, non importa quanto a lungo fuggirete, Ogier sarà con voi. Spero solo che..."
  },
  AvgDialog_119922_Content_11 = {
    Text = "Il giovane cavaliere ti guarda con serietà, gli occhi colmi di sincerità e una preghiera nascosta sotto quella sincerità."
  },
  AvgDialog_119922_Content_12 = {
    Text = "Spero solo... che la prossima volta che il mio signore intenderà \"schiarirsi le idee\" e partire per così tanto tempo, si assicuri di portarmi con sé. Ogier giurerà di proteggervi fino alla morte."
  },
  AvgDialog_119922_Content_13 = {
    Text = "Forse potrei farlo anch'io."
  },
  AvgDialog_119922_Content_14 = {
    Text = "Anche Lotan ti guardava, i suoi occhi solitamente sgargianti colmi di solennità. In quel momento, non c'erano davvero pensieri di vittoria o sconfitta, nessuna battaglia, solo preoccupazione per te."
  },
  AvgDialog_119922_Content_15 = {
    Text = "……Lo sapevo che sarebbe finita così. Voi due, non dimenticate lo scopo di questo tè. Stiamo celebrando il \"ritorno\" di %player%."
  },
  AvgDialog_119922_Content_16 = {
    Text = "Spero che dopo il tuo \"ritorno\" questa volta, non te ne andrai più."
  },
  AvgDialog_119922_Content_17 = {
    Text = "È solo un po' di relax, non fatela sembrare una cosa così seria... E sono tornato, no?"
  },
  AvgDialog_119922_Content_18 = {
    Text = "Udendo le tue parole, Doll ti guardò. Sembrava voler dire qualcosa, ma alla fine si limitò a sospirare sommessamente."
  },
  AvgDialog_119922_Content_19 = {
    Text = "Sì, sei tornato. Coloro che cercavano la tua figura nel campus non potevano che restare delusi, e coloro che restavano in silenzio davanti alla tua porta senza osare bussare, anche quei momenti sono passati."
  },
  AvgDialog_119922_Content_2 = {
    Text = "Senza che te ne accorgessi, Piazza Misag era stata allestita per un piccolo tea party, e Ramona era in piedi accanto a un tavolino pieno di muffin, marmellate e tè, sorridente e con la mano tesa verso di te."
  },
  AvgDialog_119922_Content_20 = {
    Text = "%player%, l'ho detto innumerevoli volte prima, e continuerò a farlo in futuro: la tua esistenza è incredibilmente importante."
  },
  AvgDialog_119922_Content_21 = {
    Text = "Sia per questo mondo che per noi. Quindi..."
  },
  AvgDialog_119922_Content_22 = {
    Text = "Hai aspettato che Doll continuasse, ma Doll chiuse gli occhi e non disse altro."
  },
  AvgDialog_119922_Content_23 = {
    Text = "In quel momento, un paio di mani coprirono la tua con dolcezza ma fermezza: era Ramona."
  },
  AvgDialog_119922_Content_24 = {
    Text = "Partner, so che come custode porti sulle spalle molta pressione, lo capiamo tutti, e non ti chiederemo troppo."
  },
  AvgDialog_119922_Content_25 = {
    Text = "Voglio solo che tu sappia che non importa quante volte te ne vai, non importa quanto a lungo sei assente, noi saremo qui quando tornerai."
  },
  AvgDialog_119922_Content_26 = {
    Text = "Mentre diceva questo, la voce della ragazza si fermò per un istante, rivelandoti lentamente un sorriso."
  },
  AvgDialog_119922_Content_27 = {
    Text = "Bentornato ancora una volta, partner. Ora, goditi questo tè preparato per te."
  },
  AvgDialog_119922_Content_28 = {
    Text = "Esatto. Oggi niente valutazioni, niente compiti extra. Il tuo unico compito è renderti felice."
  },
  AvgDialog_119922_Content_29 = {
    Text = "Se non ti preoccupano le carie e l'eccesso di zuccheri, puoi mangiare tutti questi dolci. Dopotutto, sono stati preparati per te."
  },
  AvgDialog_119922_Content_3 = {
    Text = "Mi chiedo se ho l'onore di invitarti al tea party di bentornato che abbiamo preparato per te?"
  },
  AvgDialog_119922_Content_30 = {
    Text = "Non c'è davvero bisogno..."
  },
  AvgDialog_119922_Content_31 = {
    Text = "Pur dicendo questo, hai comunque dato un morso al panino al burro glassato. Il sapore era dolce proprio come immaginavi, eccessivamente dolce, eppure non sgradevole."
  },
  AvgDialog_119922_Content_32 = {
    Text = "Perché, negli sguardi premurosi degli altri, il tuo cuore ha trovato appagamento. Forse, la vita consiste nell'assaporare una dolcezza così commovente negli intervalli amari della realtà."
  },
  AvgDialog_119922_Content_4 = {
    Text = "Annuisci, e la ragazza prende delicatamente la tua mano, guidandoti verso il tavolo triangolare pieno di piatti, e verso i risvegliatori che aspettavano accanto al tavolo da molto tempo."
  },
  AvgDialog_119922_Content_5 = {
    Text = "Se volete il mio parere, un combattimento non è forse più \"eccitante\" di un tè? Ma in effetti... questa volta è un po' diverso."
  },
  AvgDialog_119922_Content_6 = {
    Text = "Questa volta, non ha nulla a che fare con vincere o perdere, nulla a che fare con la battaglia. Riguarda solo te."
  },
  AvgDialog_119922_Content_7 = {
    Text = "%player%, sei il protagonista assoluto di questo tea party."
  },
  AvgDialog_119922_Content_8 = {
    Text = [[
Lotan disse, spingendo un piatto di panini al burro glassati davanti a te.
Bastava uno sguardo per capire che erano spaventosamente calorici.]]
  },
  AvgDialog_119922_Content_9 = {
    Text = "Mi chiedo perché ho la sensazione che... basti un solo morso per richiedere un intero semestre per digerirlo..."
  },
  AvgDialog_119923_Content_1 = {
    Text = "Nella melma spirituale nera come la pece, giunge un dolore lancinante che raggiunge l'anima, accompagnato da una voce fredda."
  },
  AvgDialog_119923_Content_10 = {
    Text = "Ricordando la sensazione di avere il cranio aperto, il tuo cervello formicola, e per liberarti di questa sensazione, cambi attivamente argomento."
  },
  AvgDialog_119923_Content_11 = {
    Text = "Qual è lo stato di questo mondo... adesso?"
  },
  AvgDialog_119923_Content_12 = {
    Text = "Sempre lo stesso. Ogni momento vi avvicinate al collasso e alla distruzione. Ma almeno c'è una buona notizia per te."
  },
  AvgDialog_119923_Content_13 = {
    Text = "Mentre parlava, Doll: Inferno aprì il comunicatore, e presto una figura familiare apparve davanti a te. Era un messaggio di comunicazione registrato in precedenza."
  },
  AvgDialog_119923_Content_14 = {
    Text = "Doll: Inferno, se %player% ritorna con successo, o se ci sono notizie, ricordati di dirmelo. Inoltre, penso che il tuo suggerimento precedente riguardo l'impianto di suggestioni psicologiche sia molto ragionevole."
  },
  AvgDialog_119923_Content_15 = {
    Text = "Come psicologa professionista, nel chiedere a %player% di restare, non posso assecondare eccessivamente i desideri del paziente..."
  },
  AvgDialog_119923_Content_16 = {
    Text = "La comunicazione si interrompe bruscamente qui, chiusa da Doll: Inferno. Lei batte delicatamente sul tavolo, facendoti segno di concentrarti su di lei."
  },
  AvgDialog_119923_Content_17 = {
    Text = "Le inutili chiacchiere possono fermarsi qui. Ho Scatenato tutto questo Solo per mostrarti cosa hai perso durante il periodo in cui te ne sei \"andato\"."
  },
  AvgDialog_119923_Content_18 = {
    Text = "Soprattutto, il mio esperimento non è ancora finito..."
  },
  AvgDialog_119923_Content_19 = {
    Text = "Doll: Inferno si avvicina a te con un bisturi. La sua espressione è calma, eppure cela un tocco di follia."
  },
  AvgDialog_119923_Content_2 = {
    Text = "Ancora per quanto hai intenzione di fingere di dormire? Mio adorabile cagnolino."
  },
  AvgDialog_119923_Content_20 = {
    Text = "Cosa, cosa hai intenzione di fare?"
  },
  AvgDialog_119923_Content_21 = {
    Text = "Ho intenzione di fissare permanentemente il tuo spirito in questa mente, in questo corpo. In questo modo, non potrai più \"andartene\"."
  },
  AvgDialog_119923_Content_22 = {
    Text = "Hai fatto un passo indietro per lo spavento, ma presto hai ritrovato la calma ricordando che c'era ancora qualcosa che dovevi portare a termine—"
  },
  AvgDialog_119923_Content_23 = {
    Text = "Doll: Inferno, non deve essere per forza così. Finché questo mondo non sarà tornato alla normalità, non me ne andrò davvero."
  },
  AvgDialog_119923_Content_24 = {
    Text = "La figura che impugna il bisturi si ferma, osservandoti in silenzio, come a giudicare la veridicità delle tue parole."
  },
  AvgDialog_119923_Content_25 = {
    Text = "Sono serio. Come custode, non rinuncerò mai a salvare questo mondo, quindi non importa quanto a lungo \"me ne vada\", tornerò sempre."
  },
  AvgDialog_119923_Content_26 = {
    Text = "Doll: Inferno posa il bisturi. Cogliendo questa opportunità, porti la mano al petto.\nQuando le tue dita toccano la familiare chiave d'argento, il tuo cuore si tranquillizza davvero."
  },
  AvgDialog_119923_Content_27 = {
    Text = "Ora sono tornato. L'indagine interrotta può continuare."
  },
  AvgDialog_119923_Content_28 = {
    Text = "Mentre dicevi questo, ti sei diretto verso la porta. Doll: Inferno ti ha lanciato un'occhiata e ti ha seguito."
  },
  AvgDialog_119923_Content_29 = {
    Text = "Sembra che tu comprenda davvero l'importanza della tua esistenza per questo mondo."
  },
  AvgDialog_119923_Content_3 = {
    Text = "Doll: Inferno?"
  },
  AvgDialog_119923_Content_30 = {
    Text = "Certo, perché come ha detto una volta Tawil, io sono la variabile di questo mondo, il futuro di questo mondo."
  },
  AvgDialog_119923_Content_31 = {
    Text = "Mentre le tue parole risuonavano, la porta del laboratorio si aprì lentamente. L'aria esterna e la luce del sole ti avvolsero gradualmente, come un saluto silenzioso o una risposta."
  },
  AvgDialog_119923_Content_32 = {
    Text = "Questo mondo ti sta aspettando, in attesa dei cambiamenti che stai per portare, del futuro che stai per creare."
  },
  AvgDialog_119923_Content_4 = {
    Text = "Hai riconosciuto la proprietaria di quella voce e hai aperto lentamente gli occhi. Presto, l'oscurità svanì e la luce emerse——"
  },
  AvgDialog_119923_Content_5 = {
    Text = "Cosa si prova a \"lasciare\" questo mondo?"
  },
  AvgDialog_119923_Content_6 = {
    Text = "Forse la prossima volta dovrei anche confinare il tuo \"Spirito\", così non ci sarà bisogno di recuperarlo."
  },
  AvgDialog_119923_Content_7 = {
    Text = "Doll: Inferno socchiude gli occhi, rivelando un'espressione di mezzo sorriso mentre gioca lentamente con il bisturi scintillante di luce fredda nella sua mano."
  },
  AvgDialog_119923_Content_8 = {
    Text = "……Perché sono qui?"
  },
  AvgDialog_119923_Content_9 = {
    Text = "Ovviamente, perché quando il tuo \"Spirito\" se ne va, il recipiente perde la sua funzione, ed è per questo che ho dovuto eseguire nuovamente l'operazione per recuperare il tuo \"Spirito\"."
  },
  AvgDialog_120290_Content_1 = {
    Text = "Pentola Dorata di Carne"
  },
  AvgDialog_120290_Content_10 = {
    Text = "Ti abbandoni al suo abbraccio. Ti solleva sul letto, rimboccando gli angoli della trapunta con cura. Si china, premendo la fronte contro la tua, poi ti stringe al petto."
  },
  AvgDialog_120290_Content_11 = {
    Text = "Mūmā...? Mūmā!"
  },
  AvgDialog_120290_Content_12 = {
    Text = "Mūmā, papà non viene a vedermi da tanto tempo. Non c'è nessuno in casa che mi aiuti... niente acqua... Mi fa male la testa. Mi fa male tutto."
  },
  AvgDialog_120290_Content_13 = {
    Text = "...Non piangere, <Italic:Nānnān>."
  },
  AvgDialog_120290_Content_14 = {
    Text = "Stai tranquilla. Andrà tutto meglio, presto."
  },
  AvgDialog_120290_Content_15 = {
    Text = "Sprofondi nel tepore delle coperte. Nel tuo delirium, avverti la fragranza farsi più intensa. Non è più il leggero gelsomino che tua madre indossava sempre. Ha l'odore di..."
  },
  AvgDialog_120290_Content_16 = {
    Text = "Che odore ha? Come i vicoli più profondi e tortuosi di Shencheng, dove grandi fiori di magnolia cadono e fermentano nella calura soffocante — una dolcezza strana, stucchevole, malsana."
  },
  AvgDialog_120290_Content_17 = {
    Text = "Mūmā, indossi un profumo nuovo? È così forte... e... così strano."
  },
  AvgDialog_120290_Content_18 = {
    Text = "La voce gentile non offre risposta. Mentre ti batte ritmicamente la spalla, il profumo si addensa fino a sembrare quasi solido, un peso fisico."
  },
  AvgDialog_120290_Content_19 = {
    Text = "Ti sforzi di vedere il suo volto, ma una foschia senza fine turbina davanti ai tuoi occhi, inghiottendoti infine del tutto."
  },
  AvgDialog_120290_Content_2 = {
    Text = "Una sottile foschia, impregnata del profumo di gelsomino, si avvolge attorno alle tue membra, intrappolandoti in un abbraccio umido e invisibile."
  },
  AvgDialog_120290_Content_20 = {
    Text = "Dormi ora, bambina preziosa. Dormi. La tua Mūmā tornerà al tuo fianco tra poco."
  },
  AvgDialog_120290_Content_21 = {
    Text = "...Le ho già dato la mia parola."
  },
  AvgDialog_120290_Content_22 = {
    Text = "Nell'oscurità, la sete ti artigliava ancora la gola come un gatto. All'improvviso, un liquido caldo e viscoso comincia a fluirti in bocca — gocciolando dal naso, o forse dagli angoli delle labbra."
  },
  AvgDialog_120290_Content_23 = {
    Text = "Le palpebre si fanno pesanti. Tra il profumo greve e i deliri sommessi, scivoli nell'incoscienza totale."
  },
  AvgDialog_120290_Content_24 = {
    Text = "Un fruscio di passi si raccoglie fuori dalla porta, strappandoti dalla tua torpida sonnolenza pulsante con voci in conversazione."
  },
  AvgDialog_120290_Content_25 = {
    Text = "Aiyo! Questa Giovane Padrona... appena apre gli occhi vuole il suo tè. Farebbe perdere la pazienza a un santo! Crede davvero di essere ancora la piccola cocca di quando la Signora era in vita?"
  },
  AvgDialog_120290_Content_26 = {
    Text = "Abbassa la voce! ...Il Padrone non dedica nemmeno un pensiero alla propria figlia, del resto. Guarda quante belle concubine sono stipate in questo cortile ormai. E guardalo oggi — di nuovo ai bordelli della Quarta Strada."
  },
  AvgDialog_120290_Content_27 = {
    Text = "Aspetta e vedrai. Segna le mie parole, non passerà molto prima che tutte quelle concubine comincino a sfornare altri \"Padroncini\" e \"Signorine\"..."
  },
  AvgDialog_120290_Content_28 = {
    Text = "...Il Maestro?"
  },
  AvgDialog_120290_Content_29 = {
    Text = "In una bacinella di rame annerito sopra un supporto di legno, scorgi il riflesso sfocato di un volto delicato e giovane. Sbatti le palpebre in uno stordimento; la bambina nel riflesso ricambia lo sguardo."
  },
  AvgDialog_120290_Content_3 = {
    Text = "Il torpore di una febbre alta ti trascina verso il vapore..."
  },
  AvgDialog_120290_Content_30 = {
    Text = "La tua coscienza si schiarisce gradualmente, e ti sforzi di ricordare la tua identità."
  },
  AvgDialog_120290_Content_31 = {
    Text = "...Il Padrone, <Italic:Ho Fong>... Padre... Sono nella dimora della famiglia Ho, sono la figlia di Ho Fong, il mio nome è..."
  },
  AvgDialog_120290_Content_32 = {
    Text = "Aiyah! Che ci fai per terra? Il Padrone mi farà tagliare la testa se ti vede così!"
  },
  AvgDialog_120290_Content_33 = {
    Text = "La porta si spalanca. Una donna irrompe nella stanza e ti tira su con uno strattone brusco e impaziente."
  },
  AvgDialog_120290_Content_34 = {
    Text = "Perché ero a terra... dov'è Mūmā?"
  },
  AvgDialog_120290_Content_35 = {
    Text = "La tua Mūmā? Signorina, rimettiti in sesto. La Signora è \"andata via\" da più di un mese ormai."
  },
  AvgDialog_120290_Content_36 = {
    Text = "Si blocca. Vedendoti lì in piedi, piccola e assente, un lampo di pietà le attraversa il volto."
  },
  AvgDialog_120290_Content_37 = {
    Text = "<Small:<Italic:È solo una creaturina, no? Poverina, probabilmente non sa nemmeno cosa significhi \"andata via\".>>"
  },
  AvgDialog_120290_Content_38 = {
    Text = "<LightGray:<Italic:(Già. Un mese fa, Mūmā era già...)>>"
  },
  AvgDialog_120290_Content_39 = {
    Text = "Hai sognato di nuovo? Sigh. Tieni, ti ho portato dell'acqua."
  },
  AvgDialog_120290_Content_4 = {
    Text = "...e precipiti, rovinando a terra sulle assi del pavimento."
  },
  AvgDialog_120290_Content_40 = {
    Text = "Acqua... non hai più sete; il liquido che è fluito poco prima, accompagnato dalla sua fragranza."
  },
  AvgDialog_120290_Content_41 = {
    Text = "L'odore delle magnolie. Perseguita ancora il tuo palato e il tuo respiro.\nDolce fino alla putrefazione.\nÈ la fragranza <Italic:di quel sogno>! Scatti a sedere, la consapevolezza ti colpisce come un pugno. Ti lanci verso la porta."
  },
  AvgDialog_120290_Content_42 = {
    Text = "Ehi! Ehi! Dove credi di andare! Signorina!"
  },
  AvgDialog_120290_Content_43 = {
    Text = "La festa è cominciata. Le prime luci della sera tremolano accendendosi — lanterne rosse in competizione con il bagliore crudo del neon moderno. Ma la folla, che dovrebbe dirigersi a casa per la festività, si riversa tutta in un'unica direzione."
  },
  AvgDialog_120290_Content_44 = {
    Text = "L'aria è una zuppa densa di cipria, cherosene, fumo grasso di cucina, e quel crescente profumo di..."
  },
  AvgDialog_120290_Content_45 = {
    Text = "La mia Mūmā. È il suo profumo. Non era un sogno! Non lo era!"
  },
  AvgDialog_120290_Content_46 = {
    Text = "Segui la fonte di quell'aroma strano, potente, familiare, tenero e stucchevolmente dolce."
  },
  AvgDialog_120290_Content_47 = {
    Text = "L'insegna del Boudoir Dorato pende in alto su un cancello ornato."
  },
  AvgDialog_120290_Content_48 = {
    Text = "Signora Xu!"
  },
  AvgDialog_120290_Content_49 = {
    Text = "Fuori dai piedi, mi stai bloccando! Signora Xu! Guardi qui!"
  },
  AvgDialog_120290_Content_5 = {
    Text = "Ahi... <Italic:Mūmā>... acqua..."
  },
  AvgDialog_120290_Content_50 = {Text = "Tsk"},
  AvgDialog_120290_Content_51 = {
    Text = "In alto su una piattaforma, una figura gioca pigramente con un ventaglio nero, i lineamenti seminascosti dietro la seta."
  },
  AvgDialog_120290_Content_52 = {
    Text = "La calca dei corpi minaccia di sommergerti. Una fame febbrile e frenetica si insinua negli occhi degli uomini intorno a te, ma lei resta intoccata dal caos."
  },
  AvgDialog_120290_Content_53 = {
    Text = "Trovi la fonte del profumo — o piuttosto, un desiderio primordiale e incomprensibile ti afferra. Tendi il collo, fissando lo sguardo verso l'alto."
  },
  AvgDialog_120290_Content_54 = {Text = "...Ah."},
  AvgDialog_120290_Content_55 = {
    Text = "Come percependo il tuo sguardo, lei abbassa gli occhi. Vedi soltanto un paio di occhi molto, molto belli."
  },
  AvgDialog_120290_Content_56 = {
    Text = "Il ventaglio nero si sposta con un'eleganza predatoria che mozza il fiato."
  },
  AvgDialog_120290_Content_57 = {
    Text = [[
<color=#C6C4C6>NebbiaNEBBIAneBBia</color>
<color=#817D81>NEBBIAneBBia</color><color=#B9B7B9>Lei... QUELLA? QUELLA...Lei... Madre...</color>MADReI SUOI OCCHI
<color=#C6C4C6>NEBBIAneBBia</color><color=#B9B7B9>NEBBIA</color><color=#817D81>nEbBiaNEBBIAnEbBiaNEBBIAnEbBiaNEBBIA</color><color=#C6C4C6>NEBBIA</color> <color=#757175>NEBBIA</color>       <color=#817D81>LEILEILEILEILEI</color>                         <color=#757175>nEbBiaNEBBIAnEbBia</color><color=#C6C4C6>NEBBIANEBBIAMADREnEbBiaNEBBIA</color> <color=#C6C4C6>nEbBiaNEBBIAnEbBia</color>      <color=#B9B7B9>LEILEILEILEILEI</color>         <color=#817D81> nEbBiaNEBBIAnEbBia</color><color=#D7D7D7>NEBBIAnEbBiaNEBBIAnEbBiaNEBBIAnEbBiaNEBBIAnEbBia</color> <color=#D7D7D7>NEBBIAnEbBiaNEBBIAnEbBia</color><color=#B9B7B9>nEbBiaNEBBIA</color><color=#757175>nEbBiaNEBBIAnEbBia</color><color=#ACAAAC>NEBBIAnEbBiaNEBBIAnEbBiaNEBBIAnEbBiaNEBBIAnEbBiaNEBBIA</color> <color=#B9B7B9>OCCHInEbBiaNEBBIAnEbBia</color><color=#817D81>BELLISSIMOCCHI</color><color=#B9B7B9>nEbBiaNEBBIAnEbBiaNEBBIAnEbBia</color><color=#757175>BELLISSIMOCCHI</color><color=#D7D7D7>NEBBIAnEbBia NEBBIAnEbBiaNEBBIAnEbBiaNEBBIAnEbBiaNEBBIANEBBIAnEbBiaNEBBIAnEbBia</color> <color=#5F5D5F>MADREMADREnEbBia</color><color=#817D81>NEBBIAnEbBiaNEBBIAMAMMAMA</color><color=#757175>OCCHIOMAMMAOCCHIOCCHInEbBiaNEBBIAnEbBia</color><color=#B9B7B9>LEILEILEILEInEbBiaNEBBIA</color> <color=#757175>nEbBiaNEBBIAnEbBiaOCCHIBELLNEBBIA</color><color=#B9B7B9>nEbBiaNEBBIAnEbBiaNEBBIAnEbBiaNEBBIAMADRInEbBiaNEBBIAnEbBia</color> <color=#C6C4C6>MADRIMADREMADRI</color><color=#D7D7D7>MAMADRIMADRIDRE</color><color=#ACAAAC>MADRIDREBELLISSIMO</color>]]
  },
  AvgDialog_120290_Content_58 = {
    Text = "Urla e ululati esplodono nelle tue orecchie. Il mare di corpi crolla su se stesso!"
  },
  AvgDialog_120290_Content_59 = {
    Text = "Ho visto! Ho visto! Mi ha guardato!"
  },
  AvgDialog_120290_Content_6 = {
    Text = "Mentre parli, una sete bruciante ti assale. La Memoria non è ancora tornata; le tue membra sono come piombo, inutili e molli. D'istinto, gridi la parola più familiare che conosci."
  },
  AvgDialog_120290_Content_60 = {
    Text = "MI STA GUARDANDO!"
  },
  AvgDialog_120290_Content_61 = {
    Text = "<Change>Tanta bellezza... come può un volto essere così perfetto... così... divino... così terrificante.."
  },
  AvgDialog_120290_Content_62 = {
    Text = "Signora Xu! Signora Xu... La prego, la prego!!"
  },
  AvgDialog_120290_Content_63 = {Text = "GUARDAMI!"},
  AvgDialog_120290_Content_64 = {
    Text = "<Shake:<Red:AAAHHHHHHH!!!!>>"
  },
  AvgDialog_120290_Content_65 = {
    Text = "Il damerino improvvisamente stride e si avventa sull'uomo in abito, che fissa la piattaforma anche mentre gli occhi gli vengono strappati dalla testa."
  },
  AvgDialog_120290_Content_66 = {
    Text = "L'uomo accecato geme e ride al tempo stesso, le sfere umide che penzolano dalle orbite ormai vuote. Si deterge il sangue dal viso e protende le mani verso la piattaforma con ogni briciolo delle sue forze, le vene gonfie nelle braccia."
  },
  AvgDialog_120290_Content_67 = {
    Text = "Come se fosse stato dato un segnale, la folla si tramuta in una marea impazzita. Tra le risate e le urla, si riversa in avanti, disperata di toccare l'alto palco."
  },
  AvgDialog_120290_Content_68 = {
    Text = "<Change>Xu!! Xu!!!"
  },
  AvgDialog_120290_Content_69 = {
    Text = "<Change>XU——!!!!"
  },
  AvgDialog_120290_Content_7 = {
    Text = "Un canticchiare sommesso e frammentato si avvicina. La sagoma di una donna attraversa la porta — dolorosamente familiare, irradiante calore. Le tue gambe sembrano vuote, ma lotti per sollevarti..."
  },
  AvgDialog_120290_Content_70 = {
    Text = "La cacofonia minaccia di frantumarti i timpani. La folla ondeggia; le ossa fragili del tuo giovane corpo gemono sotto la pressione. Quel volto sotto il ventaglio sembra farsi più nitido, eppure più impossibile da afferrare."
  },
  AvgDialog_120290_Content_71 = {
    Text = "Alla fine, si condensa in una nebbia simile a un abisso che inghiotte ogni luce."
  },
  AvgDialog_120290_Content_72 = {
    Text = "E poi, un suono fende la nebbia — una risata lieve, melodica, gioiosa."
  },
  AvgDialog_120290_Content_73 = {
    Text = "Eccoti, mio Piccolo Gelsomino."
  },
  AvgDialog_120290_Content_74 = {
    Text = "Un istante prima che l'oscurità e il soffocamento ti prendano, scorgi una certa persona. È preda dello stesso fervore insensato, la dignità gettata via, mentre si fa largo a spintoni..."
  },
  AvgDialog_120290_Content_75 = {
    Text = "Un uomo il cui sguardo non si è mai posato su di te... Tuo padre."
  },
  AvgDialog_120290_Content_8 = {
    Text = "<Shake:Criiiiic—>"
  },
  AvgDialog_120290_Content_9 = {
    Text = "Oh, povera creatura. Perché sei disteso così sul pavimento?"
  },
  AvgDialog_120291_Content_1 = {
    Text = "Apparizione Improvvisa"
  },
  AvgDialog_120291_Content_10 = {
    Text = "Un pezzo di dolce secco vi viene ficcato in bocca. Non appena la pasta inizia a dissolversi, la saliva vi inonda la bocca."
  },
  AvgDialog_120291_Content_11 = {
    Text = "Seguite la donna masticando senza sosta. Proprio quando lo stomaco comincia a distendersi, una pressione ben più greve vi attanaglia il cuore."
  },
  AvgDialog_120291_Content_12 = {
    Text = "Non restate lì impalata, signorina. Entrate. Lady Xu aspetta da un'eternità."
  },
  AvgDialog_120291_Content_13 = {
    Text = "Vostro padre, Ho Fong, è circondato come sempre da concubine di cui non ricordate i volti. In questa dimora, le \"ziette\" vanno e vengono — alcune esili come rondini, altre floride e aggraziate."
  },
  AvgDialog_120291_Content_14 = {
    Text = "Ma ora, il suo sguardo è fisso con un'intensità delirante su una sola persona."
  },
  AvgDialog_120291_Content_15 = {
    Text = "La proprietaria di quegli occhi follemente belli sta recitando una parte con un'aria di cortesia distaccata e professionale. È visibilmente annoiata. Almeno, fino a quando il suo sguardo non si posa teneramente su di voi."
  },
  AvgDialog_120291_Content_16 = {
    Text = "Sapevo che sareste discesa dopo il rito, ma non avrei mai immaginato che foste così... incantevole."
  },
  AvgDialog_120291_Content_17 = {
    Text = "Non avrei dovuto mandarvi al Boudoir Dorato. Sì... dovrei tenervi al mio fianco. Nient'altro conta più. Nulla conta senza di voi!"
  },
  AvgDialog_120291_Content_18 = {
    Text = "Padron Ho, non perdete la compostezza. Rievocheremo i ricordi più tardi. Oggi sono venuta per porgere le mie scuse."
  },
  AvgDialog_120291_Content_19 = {
    Text = "Cosa può capire una sciocca bambina? Comincerò a preparare il prezzo nuziale per il Boudoir Dorato. Se vi piace, prendetela; tenetela al vostro fianco e crescetela voi stesso."
  },
  AvgDialog_120291_Content_2 = {Text = "..."},
  AvgDialog_120291_Content_20 = {
    Text = "Padron Ho, siete un uomo di così nobile carattere. Se il fato ci concedesse di unirci in matrimonio, ne sarei deliziata."
  },
  AvgDialog_120291_Content_21 = {
    Text = "Tuttavia, ho sentito un'affinità con questa bambina dal momento in cui ci siamo incontrate, nonostante il nostro... \"incidente\" di prima. Se voi e io dobbiamo avvicinarci, sarebbe meglio che il suo cuore fosse prima in pace."
  },
  AvgDialog_120291_Content_22 = {
    Text = "La donna che chiamano Lady Xu scivola verso di voi. Si china per guardarvi negli occhi."
  },
  AvgDialog_120291_Content_23 = {
    Text = "Non mi sono ancora presentata. Il mio nome è Xu. Dunque, che ne dici, Signorina della famiglia Ho?"
  },
  AvgDialog_120291_Content_24 = {
    Text = "D'istinto, stringi la mano della serva che ti ha accompagnata, cercando di nasconderti dietro la sua veste."
  },
  AvgDialog_120291_Content_25 = {
    Text = [[
Le sue dita, lisce come giada, ti sollevano il mento.
Rivedi quegli occhi.
Sono abbastanza belli da scatenare un terrore primordiale, eppure sono identici a quelli di tua madre.]]
  },
  AvgDialog_120291_Content_26 = {
    Text = "Io... Io..."
  },
  AvgDialog_120291_Content_27 = {
    Text = "<Shake:Tutti quelli che ti hanno visto per strada sono impazziti. Allo zio in giacca e cravatta hanno strappato gli occhi! H-ho paura!>"
  },
  AvgDialog_120291_Content_28 = {
    Text = "Il tuo sfogo infantile fa trasalire Lady Xu per la sorpresa. Poi scoppia a ridere con tale abbandono da rischiare di perdere il proprio contegno."
  },
  AvgDialog_120291_Content_29 = {
    Text = "Che coincidenza! Maestro Du, sareste così gentile da togliermi dall'imbarazzo? Piccola Jasmine, guarda meglio — è questo lo Zio che hai visto?"
  },
  AvgDialog_120291_Content_3 = {
    Text = "Lo shock di trovarsi nell'epicentro di una simile frenesia sconosciuta avrebbe dovuto frantumare la tua mente, o quantomeno la tua volontà."
  },
  AvgDialog_120291_Content_30 = {
    Text = "Segui il suo dito mentre si allontana dal tuo mento. Là, in piedi dietro il capannello delle concubine gelose, c'è l'uomo in abito di prima."
  },
  AvgDialog_120291_Content_31 = {
    Text = "È lui. Eh? Come ha riottenuto gli occhi?"
  },
  AvgDialog_120291_Content_32 = {
    Text = "Il suo volto non è più una maschera di sangue rappreso; i suoi occhi sono esattamente dove dovrebbero essere. Ora lo riconosci."
  },
  AvgDialog_120291_Content_33 = {
    Text = "Quando tua madre era ancora viva, tuo padre cercava di mettere all'angolo quest'uomo ai banchetti per parlare d'affari, solo per essere respinto ogni volta. Tuo padre tornava a casa furioso."
  },
  AvgDialog_120291_Content_34 = {
    Text = "È questa la bambina che era così spaventata? Non vale certo la pena di mandarmi fin laggiù solo per comprarle dei dolci."
  },
  AvgDialog_120291_Content_35 = {
    Text = "Se la famiglia Ho non riesce nemmeno a gestire una figlia isterica, non ha alcun diritto di immischiarsi nel commercio d'importazione della città. Ridicolo."
  },
  AvgDialog_120291_Content_36 = {
    Text = "Mia figlia è stata... indisposta dalla scomparsa di mia moglie. Le mie scuse, Maestro Du, io..."
  },
  AvgDialog_120291_Content_37 = {
    Text = "Vedendo il volto di tuo padre incupirsi, ti irrigidisci dal terrore. Ma poi, il profumo di magnolie ti avvolge. Lady Xu ti attira tra le sue braccia, impastando e accarezzando la tua spalla con disinvolta tenerezza."
  },
  AvgDialog_120291_Content_38 = {
    Text = "Maestro Du... ve l'ho detto, questa bambina mi è cara. Quando parlate di lei con tanta durezza, mi trovo alquanto contrariata. E quando sono contrariata... cosa siete disposto a fare?"
  },
  AvgDialog_120291_Content_39 = {
    Text = "Gli occhi dell'uomo, che ti avevano scrutata con assoluto disprezzo, perdono improvvisamente la messa a fuoco. Poi, porta il braccio all'indietro e comincia a schiaffeggiarsi da solo, <Italic:ancora e ancora.>"
  },
  AvgDialog_120291_Content_4 = {
    Text = "Ma tu sei troppo piccola. Il tuo cervello è semplice come quello di un'effimera. No — ancora più semplice. Un'ameba, un granello unicellulare. Conosci solo la fame, il freddo e l'impulso primordiale di cercare conforto."
  },
  AvgDialog_120291_Content_40 = {
    Text = "Le sue guance si gonfiano e arrossiscono all'istante, eppure sembra non provare alcun dolore. Sorride meccanicamente, scoprendo i denti in un ghigno simile a un manichino di legno in una fiera straniera."
  },
  AvgDialog_120291_Content_41 = {
    Text = "Scusate! Ho parlato a sproposito!"
  },
  AvgDialog_120291_Content_42 = {
    Text = "Ho parlato a sproposito! Ho parlato a sproposito!"
  },
  AvgDialog_120291_Content_43 = {
    Text = "Al suono ritmico degli schiaffi, Lady Xu ridacchia. Sfila un sacchetto di caramelle dalla mano inerte dell'uomo e te ne infila un pezzo in bocca."
  },
  AvgDialog_120291_Content_44 = {
    Text = "Questo sì che è uno spettacolo divertente. Ti piace, Signorina?"
  },
  AvgDialog_120291_Content_45 = {
    Text = "Un liquido dolce e denso si scioglie nella tua bocca. Fissi il vuoto prima di sollevare infine lo sguardo verso Xu."
  },
  AvgDialog_120291_Content_46 = {
    Text = "...Caramelle allo sciroppo di pera del Tempio del Dio della Città. Mūmā me le comprava sempre."
  },
  AvgDialog_120291_Content_47 = {
    Text = "Signora Xu... sei la mia Mūmā?"
  },
  AvgDialog_120291_Content_48 = {
    Text = "Lady Xu non risponde. Si limita a sorridere. Tuo padre e le sue concubine restano immobili come statue, rapiti e silenziosi."
  },
  AvgDialog_120291_Content_49 = {
    Text = "Oh, guardatevi, Maestro Du. Stavo solo facendo i capricci. Colpirvi con tanta forza... mi si spezza il cuore."
  },
  AvgDialog_120291_Content_5 = {
    Text = "E così, la gabbia di nebbia semplicemente ti cattura di nuovo. Apri gli occhi, fisicamente illesa."
  },
  AvgDialog_120291_Content_50 = {
    Text = "Nel momento in cui l'uomo si ferma, le concubine sembrano riscuotersi di colpo. Fissano il volto tumefatto e pesto del Padrone Du con espressioni sconvolte."
  },
  AvgDialog_120291_Content_51 = {
    Text = "Mi sono ricordato del Desiderio del Padrone Ho di scambiare una parola con il Padrone Du. Mi sono preso la libertà di scortarlo fin qui — consideratela una piccola cortesia da parte mia."
  },
  AvgDialog_120291_Content_52 = {
    Text = "Signorina, mentre loro parlano, vi andrebbe di fare una passeggiata con me?"
  },
  AvgDialog_120291_Content_53 = {
    Text = "Prima di uscire, non puoi fare a meno di voltarti a guardare tuo padre. Non porta la Visuale vacua e inquietante degli altri, eppure lascia che tutto accada in assoluto Silenzio."
  },
  AvgDialog_120291_Content_54 = {
    Text = "Signora Xu, voi..."
  },
  AvgDialog_120291_Content_55 = {
    Text = "Hai molte domande, vero?"
  },
  AvgDialog_120291_Content_56 = {
    Text = "Non c'è fretta, cara mia."
  },
  AvgDialog_120291_Content_57 = {
    Text = "Mio Piccolo Gelsomino... Vieni, guardami."
  },
  AvgDialog_120291_Content_58 = {
    Text = "La notte incombe, greve e soffocante. Nel caldo bagliore delle lanterne, Lady Xu sposta il ventaglio. Una Nebbia indistinta si avventa su di te, ti avvolge, ti inghiotte intera."
  },
  AvgDialog_120291_Content_59 = {
    Text = "Sfocata dal vapore, tua Madre è in piedi nella luce. Sorride, chinandosi verso di te con le braccia spalancate."
  },
  AvgDialog_120291_Content_6 = {
    Text = "La notte è calata del tutto. La luce delle candele tremola dalle finestre di stanze lontane, e quei passi leggeri e frettolosi si avvicinano ancora una volta."
  },
  AvgDialog_120291_Content_60 = {
    Text = "È come se una corda dentro di te finalmente si spezzasse. Il naso ti brucia, le lacrime ti offuscano la vista, e ti getti nel suo Abbraccio."
  },
  AvgDialog_120291_Content_61 = {
    Text = "Mūmā, non lasciarmi più, ti prego..."
  },
  AvgDialog_120291_Content_62 = {
    Text = "Sob... waaahhhh... Ho la testa così confusa. Ho così tanta paura. Mi sei mancata tanto! Mūmā..."
  },
  AvgDialog_120291_Content_63 = {
    Text = "Ti circonda con le braccia, accarezzandoti dolcemente la schiena."
  },
  AvgDialog_120291_Content_64 = {
    Text = "Mia preziosa bambina. La mia brava, dolce piccola."
  },
  AvgDialog_120291_Content_65 = {
    Text = "La mia piccola <Italic:bǎobèi>. La mia obbediente cara..."
  },
  AvgDialog_120291_Content_66 = {
    Text = "Cosa saresti disposto a dare... per restare con tua madre per sempre?"
  },
  AvgDialog_120291_Content_67 = {
    Text = "La nebbia si avvolge più stretta. Odi la tua stessa voce, un mormorio lontano."
  },
  AvgDialog_120291_Content_68 = {
    Text = "Qualsiasi cosa... Ti darò tutto."
  },
  AvgDialog_120291_Content_69 = {
    Text = "Anche l'intera magione?"
  },
  AvgDialog_120291_Content_7 = {
    Text = "Aiyo, signorina, ci avete fatto quasi morire di paura! Vagare sulla strada principale in trance a quel modo — sarete la rovina di noi servitori, ecco!"
  },
  AvgDialog_120291_Content_70 = {
    Text = "Non voglio la casa. Voglio solo Mūmā."
  },
  AvgDialog_120291_Content_71 = {
    Text = "Questa dimora, l'intera Shencheng, e persino tuo padre... posso avere tutto questo?"
  },
  AvgDialog_120291_Content_72 = {
    Text = "Padre... Papà..."
  },
  AvgDialog_120291_Content_73 = {
    Text = "Per un istante la tua mente vaga, persa nei pensieri. Ricordi le lunghe notti d'attesa con tua madre — e la mano pesante e calda che tuo padre ti posava sul capo quando finalmente tornava."
  },
  AvgDialog_120291_Content_74 = {
    Text = "Non avere fretta. Abbiamo tutto il tempo del mondo, mia Piccola Jasmine."
  },
  AvgDialog_120291_Content_75 = {
    Text = "Senti il tuo corpo sollevato, adagiato in morbide coltri soffici. Qualcosa di più caldo, di più umido e vellutato, ti avvolge in un abbraccio intimo."
  },
  AvgDialog_120291_Content_76 = {
    Text = "La notte è profonda. Dormi, ora. Sarò di nuovo al tuo fianco molto, molto presto."
  },
  AvgDialog_120291_Content_77 = {
    Text = "Per la prima volta dalla morte di tua Madre, provi un senso di pace assoluto, travolgente. Sprofondi negli abissi di un Sogno dolce e oscuro."
  },
  AvgDialog_120291_Content_8 = {
    Text = "<Shake:Gorgoglio—>"
  },
  AvgDialog_120291_Content_9 = {
    Text = "...Sigh. Mi fate davvero pena, sapete. Su, mangiate. Il Padrone è già in attesa nella sala. Non createci altri problemi, mi raccomando!"
  },
  AvgDialog_120296_Content_1 = {
    Text = "Oh, Mia Carissima"
  },
  AvgDialog_120296_Content_10 = {
    Text = "Basta con i vostri piccoli intrighi. Non sto solo cercando di spaventarvi, ma ogni Donna che il Padrone ama troppo... alla fine svaniscono tutte."
  },
  AvgDialog_120296_Content_11 = {
    Text = "Persino la sua prima moglie, l'amore della sua Infanzia — dicono che sia morta di malattia, ma chissà se lei—"
  },
  AvgDialog_120296_Content_12 = {
    Text = "Ahi! Perché mi spingi!"
  },
  AvgDialog_120296_Content_13 = {
    Text = "Signora, vi prego... perdonateci. Mia sorella parla senza riflettere. Non date ascolto alle sue sciocchezze; non abbiamo assolutamente alcuna Intenzione di competere con voi. Vi supplico, non ditelo al Padrone."
  },
  AvgDialog_120296_Content_14 = {
    Text = "Lo strattone violento della sorella la riporta in sé. La concubina vestita con cura meticolosa impallidisce d'un tratto, livida come la morte. Si preme la Mano sulla bocca, sprofondando in un Silenzio terrorizzato."
  },
  AvgDialog_120296_Content_15 = {
    Text = "Dato che questo luogo non è sicuro, perché non avete pensato di cercare una vita altrove?"
  },
  AvgDialog_120296_Content_16 = {
    Text = "...E dove andremmo? Se solo fossimo come voi — custodite come perle dai grandi signori — allora sì che potremmo andare dove ci pare."
  },
  AvgDialog_120296_Content_17 = {
    Text = "Hee-hee. Custodita come una perla?"
  },
  AvgDialog_120296_Content_18 = {
    Text = "Xu ride all'improvviso, e per un fugace istante, ogni donna nella galleria ode una risatina più spettrale, errante."
  },
  AvgDialog_120296_Content_19 = {
    Text = "I loro occhi cominciano a velarsi. Con espressioni vacue, si voltano verso la donna che si allontana nelle ombre del corridoio."
  },
  AvgDialog_120296_Content_2 = {
    Text = "Quella nuova volpicella... ne sa qualcuna, non è vero?"
  },
  AvgDialog_120296_Content_20 = {
    Text = "La mia Piccola Gelsomina sta dormendo; non svegliamola. Seguitemi."
  },
  AvgDialog_120296_Content_21 = {
    Text = "Vi mostrerò come quei \"grandi signori,\" al pari di ogni tesoro, danno piacere solo quando li si stringe tra la punta delle dita."
  },
  AvgDialog_120296_Content_22 = {
    Text = "Sorrisi sciocchi, ebeti, si propagano sui volti delle concubine. Poi la nebbia si leva a velarne le labbra, e i ventagli si muovono a mascherarne i visi."
  },
  AvgDialog_120296_Content_23 = {
    Text = "Un denso, stucchevole profumo di magnolia comincia a trasudare per tutta la Dimora Ho."
  },
  AvgDialog_120296_Content_24 = {Text = "..."},
  AvgDialog_120296_Content_25 = {
    Text = "Da quando Lady Xu è stata portata nella Dimora Ho come Seconda Moglie, non avete patito la fame nemmeno un giorno. Tutti vi trattano con una gentilezza ardente, improvvisa, come se foste ancora la preziosa Signorina che eravate quando vostra madre era in vita."
  },
  AvgDialog_120296_Content_26 = {
    Text = "Ma vostro padre non è uscito dalla sua stanza nemmeno una volta. Lady Xu non vi entra mai; al contrario, le concubine, come trascinate da invisibili fili di seta, frequentano i suoi appartamenti privati."
  },
  AvgDialog_120296_Content_27 = {
    Text = "Aiyah, Signorina, datemi tregua, volete? Il Padrone ha dato ordini tassativi che nessuno si avvicini alla sua stanza."
  },
  AvgDialog_120296_Content_28 = {
    Text = "Non vedo il Papà da così tanto tempo. Io... guarderò solo da lontano. Prometto di non disturbarlo."
  },
  AvgDialog_120296_Content_29 = {
    Text = "Eppure, prima ancora di avvicinarvi, udite dall'interno un ringhio frenetico, febbricitante in modo innaturale."
  },
  AvgDialog_120296_Content_3 = {
    Text = "Oh, tu e la tua lingua perfida. Quel ventaglio che ti ha regalato — non l'hai perso di vista nemmeno un istante, vero?"
  },
  AvgDialog_120296_Content_30 = {
    Text = "Xu... mia cara, mia salvatrice, cuore mio... Non posso permettere che ti portino via di nuovo. Sei mia. Puoi essere solo mia."
  },
  AvgDialog_120296_Content_31 = {
    Text = "Quelle donne, il loro sangue, le loro ossa... non significano nulla... A qualunque costo! AHH! Finché ho te... finché ho te, ne vale la pena!"
  },
  AvgDialog_120296_Content_32 = {
    Text = "Ora capisco! Lo vedo! Haha, HAHAHAHA!!!"
  },
  AvgDialog_120296_Content_33 = {
    Text = "Udite qualcosa di umido strisciare sul pavimento. Infine, il respiro di Ho Fong si trasforma in un rantolo breve, strozzato, come un mantice rotto, come se qualcosa lo stringesse impedendogli di respirare."
  },
  AvgDialog_120296_Content_34 = {Text = "Papà!"},
  AvgDialog_120296_Content_35 = {
    Text = "Terrorizzata da quel respiro simile a un rantolo di morte, vi slanciate in avanti e spalancate la porta."
  },
  AvgDialog_120296_Content_36 = {
    Text = "C'è solo Ho Fong. È accasciato freneticamente contro il bordo del letto, riverso su lenzuola scure. L'intera stanza è così umida che sembra essere stata sommersa dall'acqua."
  },
  AvgDialog_120296_Content_37 = {
    Text = "Ornamenti in frantumi e brandelli di stoffa strappata sono sparsi sul pavimento in un caos. Lui scatta verso di voi, il volto arrossato di un cremisi innaturale, malsano. Afferra un cuscino di legno e ve lo scaglia alla testa."
  },
  AvgDialog_120296_Content_38 = {
    Text = "Chi ti ha fatto entrare!"
  },
  AvgDialog_120296_Content_39 = {
    Text = "Nessuno può disturbare il nostro tempo insieme! Fuori! FUORI!"
  },
  AvgDialog_120296_Content_4 = {
    Text = "Be', ha bellezza, gusto, e i suoi doni hanno classe. Non darti tante arie; tu il tuo lo sventoli dall'alba al tramonto, come se ti fosse cresciuto sulla Mano."
  },
  AvgDialog_120296_Content_40 = {
    Text = "La serva ti raggiunge di corsa alle spalle, sbattendo la porta per soffocare le urla di Ho Fong."
  },
  AvgDialog_120296_Content_41 = {
    Text = "Ti avevo detto di non disturbare il Padrone. Se la prenderà con noi. Per favore, smetta di correre qua e là, Signorina!"
  },
  AvgDialog_120296_Content_42 = {
    Text = "Papà... Che cosa gli succede? Perché continua a chiamare il nome della Signora Xu?"
  },
  AvgDialog_120296_Content_43 = {
    Text = "<Shake:È uscita stamattina... Con chi sta parlando? Il suo volto... era così spaventoso...>"
  },
  AvgDialog_120296_Content_44 = {
    Text = "Eh. Mi perdoni, Signorina, ma gli affari del Padrone non spettano a noi servitori."
  },
  AvgDialog_120296_Content_45 = {
    Text = "Barcollando, corri verso il luogo che conosci meglio, in cerca d'aiuto."
  },
  AvgDialog_120296_Content_46 = {
    Text = "Gli alloggi della Signora — ora gli alloggi della Signora Xu. La stessa stanza in cui un tempo viveva tua madre."
  },
  AvgDialog_120296_Content_47 = {
    Text = "Quella porta, sbiadita e opaca dopo la morte di tua madre, ora è ricoperta di dorature fresche. Sembra l'ingresso di un altro mondo; ogni volta che si apre, ne trabocca una fragranza densa e inebriante."
  },
  AvgDialog_120296_Content_48 = {
    Text = "Haha, hehehe... Sob, wahhhh... Ho sbagliato tutto fin dall'inizio. Ho sbagliato TUTTO, TUTTO!"
  },
  AvgDialog_120296_Content_49 = {
    Text = "Fateli a pezzi! Tritateli! Spalancateli! Spalancate tutto finché è ancora fumante! Offritelo a LEI, e LEI ascolterà... Così non dovremo più soffrire!"
  },
  AvgDialog_120296_Content_5 = {
    Text = "State parlando di me?"
  },
  AvgDialog_120296_Content_50 = {
    Text = "<Change>Xu... nostro Salvatore... nostro @3!"
  },
  AvgDialog_120296_Content_51 = {
    Text = "Una nebbia invisibile riempie la stanza. Le concubine reggono devotamente i ventagli che la Signora Xu ha donato loro al suo avvento. Ridono, piangono, finché le loro grida si trasformano in lamenti bizzarri e ritmici."
  },
  AvgDialog_120296_Content_52 = {
    Text = "Non riesci a comprendere una sola parola di ciò che dicono. Le tue orecchie sono colme di un ronzio sordo e del battito frenetico del tuo cuore. Indietreggi barcollando, urtando per sbaglio la ringhiera con un secco clangore."
  },
  AvgDialog_120296_Content_53 = {
    Text = "...Oh. C'è un suono."
  },
  AvgDialog_120296_Content_54 = {
    Text = "<Shake:<Red:Altra carne tenera per l'Offerta?>>"
  },
  AvgDialog_120296_Content_55 = {
    Text = "Le loro voci sfumano in risatine giocose. I lamenti svaniscono all'istante. Un freddo inspiegabile e agghiacciante ti travolge!"
  },
  AvgDialog_120296_Content_56 = {Text = "CORRI!!!"},
  AvgDialog_120296_Content_57 = {
    Text = "È il terrore di fissare gli occhi di un predatore. È la paura primordiale sepolta nel sangue di ogni creatura vivente sin dall'alba dei tempi!"
  },
  AvgDialog_120296_Content_58 = {
    Text = "Oh? Un semplice scatolino di biscotti a farfalla, e la mia Piccola Jasmine mi corre tra le braccia con tanta gioia?"
  },
  AvgDialog_120296_Content_59 = {
    Text = "Braccia lisce come giada bianca ti afferrano prima che tu cada. Se guardassi attraverso le fessure della recinzione della tenuta, vedresti la celebre Ispettrice Huang di Shencheng chiudere di persona la portiera della sua carrozza."
  },
  AvgDialog_120296_Content_6 = {
    Text = "Ah! Le mie scuse, Signora!"
  },
  AvgDialog_120296_Content_60 = {
    Text = "Ti porge una scatola di dolci. I motivi simili a occhi sovrapposti sulla carta da imballaggio ti terrorizzano. Inspiri bruscamente, fai appello al tuo coraggio e la fai cadere dalle sue mani con uno schiaffo."
  },
  AvgDialog_120296_Content_61 = {
    Text = "Chi sei?! Perché sei nel mio focolare! Che cosa sta succedendo... Papà, le Ziette, quegli Zii... da quando sei arrivata, tutti sono diventati strani!"
  },
  AvgDialog_120296_Content_62 = {
    Text = "Oh, povera cara... una cosa così piccola, e guarda, la mia Piccola Jasmine sta già per piangere."
  },
  AvgDialog_120296_Content_63 = {
    Text = "Non sembra arrabbiata per i dolci rovinati. Anzi, si china verso di te con intimità, usando il ventaglio per tamponare le lacrime di spavento dagli angoli dei tuoi occhi."
  },
  AvgDialog_120296_Content_64 = {
    Text = "Piccola Jasmine... prima che arrivassi io, questo posto — dove non ti davano nemmeno l'acqua da bere — era davvero casa tua?"
  },
  AvgDialog_120296_Content_65 = {
    Text = "Signorina! Mi sono distratta un solo istante e lei... Signora, mi perdoni, è colpa mia, non l'ho sorvegliata."
  },
  AvgDialog_120296_Content_66 = {
    Text = "Lady Xu ignora la serva. Ti avvolge tra le braccia, accarezzandoti la schiena come si farebbe con un piccolo animale. La sua voce è dolce, eterea."
  },
  AvgDialog_120296_Content_67 = {
    Text = "Piccola Jasmine, pensaci bene. Perché questo dovrebbe importare? Perché quello dovrebbe importare? Cosa c'entra tutto questo con te?"
  },
  AvgDialog_120296_Content_68 = {
    Text = "Purché tu sia brava e faccia esattamente ciò che ti dico..."
  },
  AvgDialog_120296_Content_69 = {
    Text = "Tutto può essere tuo. Ogni persona può essere il tuo giocattolo."
  },
  AvgDialog_120296_Content_7 = {
    Text = "Tsk. \"Signora\" di qua, \"Signora\" di là... è solo una cortigiana appena uscita dalle case di piacere. Perché averne tanta paura? Non è che vi mangerà vive."
  },
  AvgDialog_120296_Content_70 = {
    Text = "Ti accarezza dalla spina dorsale fino ai capelli, concludendo il suo giocare con le tue ciocche prima di lasciarle andare. Emana una sensazione di pura gioia."
  },
  AvgDialog_120296_Content_71 = {
    Text = "Ecco, brava. Portate la mia Piccola Jasmine a letto... ha bisogno di riposare."
  },
  AvgDialog_120296_Content_72 = {
    Text = "Cammini a lungo nella nebbia. Dentro la grigia miasma, scorgi una vasta distesa d'acqua scura."
  },
  AvgDialog_120296_Content_73 = {
    Text = "Innumerevoli arti viscidi e guizzanti, ricoperti di ventose, si annidano al confine dove l'acqua incontra la nebbia. Un'Ombra gentile siede in riva all'acqua, dandoti le spalle."
  },
  AvgDialog_120296_Content_74 = {
    Text = "Mūmā? Sei tu?"
  },
  AvgDialog_120296_Content_75 = {
    Text = "<Shake:...Sbagliato... tutto... corri...>"
  },
  AvgDialog_120296_Content_76 = {
    Text = "Mūmā, cosa stai dicendo? Non ti sento."
  },
  AvgDialog_120296_Content_77 = {
    Text = "Ti avvicini, solo per renderti conto con un sussulto che non è \"seduta\" in riva all'acqua. La parte inferiore del suo Corpo si è dissolta in una massa di tentacoli, fondendosi nelle grigie profondità."
  },
  AvgDialog_120296_Content_78 = {
    Text = "<Shake:Sbagliato. Tutto quanto.>"
  },
  AvgDialog_120296_Content_79 = {
    Text = "<Shake:Lei non è... QUELLA COSA non è...>"
  },
  AvgDialog_120296_Content_8 = {
    Text = "Guardatevi, tutte a soffiare e sputare come gattine arruffate. Che spettacolo davvero delizioso."
  },
  AvgDialog_120296_Content_80 = {
    Text = "La Donna si volta. Il suo volto familiare è solcato da righe grigie di lacrime. Ti urla contro, la sua Voce uno Strido lacerante."
  },
  AvgDialog_120296_Content_81 = {
    Text = "<Red:Indossa il volto di tua madre.>"
  },
  AvgDialog_120296_Content_82 = {
    Text = "<Change>Non è vero NON È VERO NON È VERO!!!"
  },
  AvgDialog_120296_Content_83 = {
    Text = "<Red:<Shake:Sbagliato! È tutto sbagliato!! Nānnān!!! Scappa!! PRESTO!! SCAPPA!!!>>"
  },
  AvgDialog_120296_Content_9 = {
    Text = "Non temete. Sono soltanto una nuova arrivata qui. Vi ho viste chiacchierare con tale animazione e desideravo semplicemente unirmi a voi per condividere qualche Segreto."
  },
  AvgDialog_120297_Content_1 = {
    Text = "Sangue del Signore"
  },
  AvgDialog_120297_Content_10 = {
    Text = "A volte sono gli uomini in persona; a volte sono le loro mogli. Quando vengono le mogli, il sorriso sul volto della Signora Xu si allarga visibilmente. Quando tornano per una seconda visita, un ventaglio nero — identico a quelli delle concubine — è stretto saldamente nelle loro mani."
  },
  AvgDialog_120297_Content_100 = {
    Text = "Eppure, il sanguinario Ho Fong inizia davvero a calmarsi."
  },
  AvgDialog_120297_Content_101 = {
    Text = "Tu... lo pensi davvero?"
  },
  AvgDialog_120297_Content_102 = {
    Text = "Sai bene che, pur possedendo un potere divino, sono legata a colui che mi ha risvegliata. Posso fare solo ciò che tu mi ordini. Come potrei mai ingannarti?"
  },
  AvgDialog_120297_Content_103 = {
    Text = "Proprio come nel vicolo, ti ritrovi incapace di parlare o muoverti. È come se questa grottesca Dea fosse determinata a costringerti ad assistere a questa farsa."
  },
  AvgDialog_120297_Content_104 = {
    Text = "Ho Fong se ne va, il volto raggiante di gioia. Come quel giorno al Boudoir Dorato, se ne va senza rivolgere un solo sguardo verso di te."
  },
  AvgDialog_120297_Content_105 = {
    Text = "Nell'istante in cui riesci a muoverti, ti volti di scatto e ti avventi su Lady Xu, emettendo un lamento animalesco. Piedi, pugni, denti — usi ogni patetico metodo di attacco che conosci, pur sapendo che è futile."
  },
  AvgDialog_120297_Content_106 = {
    Text = "Ridammeli! Ridammi la mia Mūmā! Ridammi il mio Papà!"
  },
  AvgDialog_120297_Content_107 = {
    Text = "Lady Xu resta perfettamente immobile, ventaglio in mano, lasciandoti sfogare la tua rabbia. Il divertimento nei suoi occhi ti fa dimenticare il terrore; restano solo furia e disperazione."
  },
  AvgDialog_120297_Content_108 = {
    Text = "Tutto è successo per colpa tua! Non sei una Dea—sei un mostro!"
  },
  AvgDialog_120297_Content_109 = {
    Text = "La donna davanti a te... annuisce."
  },
  AvgDialog_120297_Content_11 = {
    Text = "Presto. Indugia ancora e la perderemo."
  },
  AvgDialog_120297_Content_110 = {
    Text = "È corretto, mia Piccola Gelsomina. Sono un mostro."
  },
  AvgDialog_120297_Content_111 = {
    Text = "Ma la morte di tua madre non aveva nulla a che fare con me. Ho Fong ha ucciso innumerevoli donne, inclusa lei, per evocarmi in cambio di ricchezza e potere."
  },
  AvgDialog_120297_Content_112 = {
    Text = "Poco fa, voleva ucciderti. Tu non volevi morire, e così ti ho risposto. Se ti avessi abbandonata, ora saresti morta."
  },
  AvgDialog_120297_Content_113 = {Text = "..."},
  AvgDialog_120297_Content_114 = {
    Text = "Non sai cosa dire. La sua voce è colma di oscuro interesse; i suoi begli occhi brillano di divertimento."
  },
  AvgDialog_120297_Content_115 = {
    Text = "Allora, mio Piccolo Gelsomino, cosa sceglierai?"
  },
  AvgDialog_120297_Content_116 = {
    Text = "Apri la bocca per parlare, ma le parole ti abbandonano; puoi solo fissarla in uno stupore ottuso. Un acufene acuto e penetrante ti scuote i nervi, sommergendo il mondo. Con un ultimo, lieve sfioramento della mano sulla tua schiena, si volta e inizia a camminare verso il cortile."
  },
  AvgDialog_120297_Content_117 = {
    Text = "Hehe... Presto. Molto, molto presto... verrà il momento in cui dovrai compiere la scelta finale."
  },
  AvgDialog_120297_Content_118 = {Text = "..."},
  AvgDialog_120297_Content_119 = {
    Text = "Gli eventi della giornata si ripetono nei tuoi sogni. Ti svegli urlando nel cuore della notte, ma la dimora è silenziosa come una tomba. Nessuno risponde. Quella voce stridula e familiare non esiste più."
  },
  AvgDialog_120297_Content_12 = {
    Text = "Il viaggio in risciò è sconnesso e traballante. Sebbene tu riesca a restare nascosta lungo le strade tortuose, perdi l'automobile proprio mentre svolta in un piccolo boschetto."
  },
  AvgDialog_120297_Content_120 = {
    Text = "La fame ti rode le viscere. Resti raggomitolata a lungo prima di alzarti finalmente in piedi. Guidata dalla memoria, trovi la scatola di crackers a farfalla in frantumi. Sola nel chiaro di luna, ne divori ogni ultima briciola in silenzio."
  },
  AvgDialog_120297_Content_121 = {
    Text = "Quando il sonno ti prende di nuovo, ritorni alla riva dell'acqua grigia. Tua madre protende braccia a forma di tentacolo, facendoti cenno. Dietro di lei, un enorme, mutevole groviglio di arti si staglia nella nebbia."
  },
  AvgDialog_120297_Content_122 = {
    Text = "Mūmā... è ancora qui?"
  },
  AvgDialog_120297_Content_123 = {
    Text = "Mūmā sarà con te per sempre."
  },
  AvgDialog_120297_Content_124 = {
    Text = "Resterò al fianco della mia Piccola Gelsomina... sempre, e per sempre."
  },
  AvgDialog_120297_Content_125 = {
    Text = "Due voci risuonano nelle tue orecchie all'unisono. Non fai più domande.\nSei semplicemente troppo stanca, e così, così spaventata."
  },
  AvgDialog_120297_Content_126 = {
    Text = "Senza esitazione, ti lanci in avanti, tuffandoti in quell'abbraccio terrificante, viscoso e inimmaginabilmente soffice."
  },
  AvgDialog_120297_Content_13 = {
    Text = "Vieni condotta più in profondità nel bosco. Per qualche ragione, il tuo cuore comincia a Martellare intensamente. Trovi un po' di conforto solo stringendo forte la Mano della Donna."
  },
  AvgDialog_120297_Content_14 = {
    Text = "Il cielo si tinge lentamente di un crepuscolo profondo, e la luna si insinua sopra la linea degli alberi senza che nessuno se ne accorga. All'improvviso, la donna fa cenno di tacere, il dito premuto con fermezza sulle labbra."
  },
  AvgDialog_120297_Content_15 = {Text = "Shh—"},
  AvgDialog_120297_Content_16 = {
    Text = "In lontananza appare Xu. L'automobile bianca sfreccia via, lasciando il Maestro Du in piedi accanto a lei in silenzio. Nell'angolo, diverse ombre lunghe si proiettano sulla terra battuta."
  },
  AvgDialog_120297_Content_17 = {
    Text = "Il Maestro Du, l'Ispettore Huang, il capo del Sindacato Navale del Nord, e quei boss della mafia... Oh-oh, Lady Xu è davvero qualcosa di speciale, non è vero..."
  },
  AvgDialog_120297_Content_18 = {
    Text = "In lontananza, i volti degli uomini sono arrossati di quello stesso cremisi innaturale che avevi visto su tuo padre. Dapprima mormorano a bassa voce, ma il suono si intensifica rapidamente in una cantilena frenetica e concitata."
  },
  AvgDialog_120297_Content_19 = {
    Text = "<Shake:Lei... restare... non può...>"
  },
  AvgDialog_120297_Content_2 = {
    Text = "Ogni concubina somiglia sempre di più alla Signora Xu. E tuo padre non ha più lasciato la sua Stanza da quel giorno."
  },
  AvgDialog_120297_Content_20 = {
    Text = "<Shake:Uccidere... solo allora...>"
  },
  AvgDialog_120297_Content_21 = {
    Text = "<Shake:Uccidere... Uccidere... UCCIDERE!! AMMAZZATELA—FATELA A PEZZI!!!>"
  },
  AvgDialog_120297_Content_22 = {
    Text = "<Change>Mia, mia, mia miaMIA! È MIA!!"
  },
  AvgDialog_120297_Content_23 = {
    Text = "Una luce pallida e nauseante ti ferisce gli occhi. Solo allora ti rendi conto che ogni uomo nasconde un falcetto dietro la schiena — e ora lo sollevano in alto, in un arco sincronizzato."
  },
  AvgDialog_120297_Content_24 = {
    Text = "Ha—ahahaha! AHAHAHAHAHA!"
  },
  AvgDialog_120297_Content_25 = {
    Text = "Mentre gli uomini si avvicinano, Xu esplode in una risata violenta e convulsa, come se avesse appena assistito alla barzelletta più divertente del mondo. Punta il dito verso i loro volti, uno per uno."
  },
  AvgDialog_120297_Content_26 = {
    Text = "Un istante dopo, i falcetti affilati calano da ogni direzione! Il tonfo sordo della carne che si scinde. Lo schiocco umido di osso e tendine recisi. Un braccio mozzato, bianco come giada, viene scagliato in alto nell'aria."
  },
  AvgDialog_120297_Content_27 = {
    Text = "SQUELCH. CRACK!"
  },
  AvgDialog_120297_Content_28 = {
    Text = "Mmmph! Mmmph-mmmph!!"
  },
  AvgDialog_120297_Content_29 = {
    Text = "Vieni trascinata in un abbraccio soffocante. La mano della donna ti serra la bocca, ricacciandoti in gola l'urlo di panico."
  },
  AvgDialog_120297_Content_3 = {
    Text = "La Madre non visita più i tuoi sogni. Al suo posto, sogni infiniti ventagli neri, e sotto ognuno di essi c'è il volto della Signora Xu. Sogni tuo padre divorato dai Mostri, per poi svegliarti in un sudore freddo e fradicio."
  },
  AvgDialog_120297_Content_30 = {
    Text = "<Change>Cranio. Collo. Petto. Braccia. Ventre..."
  },
  AvgDialog_120297_Content_31 = {
    Text = "<Shake:Dal cranio, dal collo, dal petto, dalle braccia, dal ventre...> Qualcosa striscia fuori."
  },
  AvgDialog_120297_Content_32 = {
    Text = "<Change>Fuori dal cranio. Fuori dal collo. Fuori dalla cavità toracica, fuori, fuori, erompendo..."
  },
  AvgDialog_120297_Content_33 = {
    Text = "Mio Signore."
  },
  AvgDialog_120297_Content_34 = {
    Text = "La sua voce è tenera. Civettuola. Dolce come il miele."
  },
  AvgDialog_120297_Content_35 = {
    Text = "Benché sia lontana, la voce si avvolge come nebbia attorno alle tue orecchie, insinuandosi nella tua mente."
  },
  AvgDialog_120297_Content_36 = {
    Text = "La nebbia, cremisi come sangue, si scurisce di colore. Una dopo l'altra, molte \"Lady Xu\" iniziano a strisciare fuori dai cumuli di carne macellata. Le loro braccia bianche come giada sono ricoperte di una melma nera e fluida mentre si protendono verso l'alto."
  },
  AvgDialog_120297_Content_37 = {
    Text = "Oh, fa così, così male... non vuoi darmi un bacio?"
  },
  AvgDialog_120297_Content_38 = {
    Text = "<Change>Fa così male... Dammi un bacio..."
  },
  AvgDialog_120297_Content_39 = {
    Text = "<Change>Fa male @3. Dammi un @4!"
  },
  AvgDialog_120297_Content_4 = {
    Text = "Signorina, smettila con questi capricci. La Signora Xu è così buona con te; ogni giorno ti porta dolci e giocattoli nuovi."
  },
  AvgDialog_120297_Content_40 = {
    Text = "<Change>FA COSÌ MALE. DAMMI UN BACIO!"
  },
  AvgDialog_120297_Content_41 = {
    Text = "Le Xu... mostri a sua immagine. La parte inferiore dei loro corpi è fusa negli ammassi straziati di carne, i volti imbrattati di una melma scura e viscosa che lascia intravedere soltanto il tenue contorno delle labbra."
  },
  AvgDialog_120297_Content_42 = {
    Text = "Sul volto di ogni \"Lady Xu\" sbocciano una dozzina di bocche lussureggianti, bellissime, simili a petali, che si avvinghiano agli uomini lì in piedi, ridacchiando in un'estasi insensata."
  },
  AvgDialog_120297_Content_43 = {
    Text = "<Change>Crac... Snap... SCRUNCH—"
  },
  AvgDialog_120297_Content_44 = {
    Text = "Il suono dei crani compressi. Il suono dei crani che si frantumano."
  },
  AvgDialog_120297_Content_45 = {
    Text = "<Change>Slurp... Squelch... Gulp—"
  },
  AvgDialog_120297_Content_46 = {
    Text = "Il suono della suzione. Il suono del nutrirsi."
  },
  AvgDialog_120297_Content_47 = {
    Text = "Osservi le loro teste esplodere, solo per essere ricomposte, intatte e perfette. Le \"Xu\" emettono sospiri di profonda soddisfazione, poi iniziano a fondersi nuovamente in un'unica forma tra gemiti sazi."
  },
  AvgDialog_120297_Content_48 = {
    Text = "Il Maestro Du, l'Ispettore Huang, il magnate delle spedizioni..."
  },
  AvgDialog_120297_Content_49 = {
    Text = "Si alzano in un silenzio sinistro. Come se nulla fosse mai accaduto, si disperdono con espressioni vuote e vacue. Lady Xu è già scomparsa, dissolta nell'aria."
  },
  AvgDialog_120297_Content_5 = {
    Text = "La Donna sospira, usando il suo fazzoletto per tamponare il sudore freddo dalla tua fronte."
  },
  AvgDialog_120297_Content_50 = {
    Text = "La mano che ti stringeva finalmente lascia la presa. Nel silenzio soffocante che segue, le tue lacrime scorrono incontenibili. Ti volti di scatto, e le tue pupille si contraggono in un violento tremore."
  },
  AvgDialog_120297_Content_51 = {Text = "Oops!..."},
  AvgDialog_120297_Content_52 = {
    Text = "Mi sono chiesta come fare a essere... <Italic:perfettamente sincera> con te, mia Piccola Jasmine."
  },
  AvgDialog_120297_Content_53 = {
    Text = "Il tuo mondo si restringe fino a non restare nulla se non la Donna davanti a te. Una scintilla incandescente di Pain divampa nel tuo cervello sovraccarico."
  },
  AvgDialog_120297_Content_54 = {
    Text = "Che aspetto aveva? Quella Donna dalla Voce stridula?"
  },
  AvgDialog_120297_Content_55 = {
    Text = "Tutti i servitori nella tua Stanza erano stati congedati quando tua Madre morì."
  },
  AvgDialog_120297_Content_56 = {
    Text = "A nessuno importava se vivevi o morivi. Non vedesti mai il suo volto nemmeno una volta — eppure perché Tutti, te compresa, trovavano la sua presenza così naturale?"
  },
  AvgDialog_120297_Content_57 = {
    Text = "Mi affezionai a quella pelle... Amavo il profumo di gelsomino che portava con sé. Fin dal principio, mi chiesi... che aspetto avrebbe avuto la sua \"Piccola Jasmine\" — la mia Piccola Jasmine?"
  },
  AvgDialog_120297_Content_58 = {
    Text = "Oh, non ho proprio saputo trattenermi. Venni a trovarti molto, molto presto."
  },
  AvgDialog_120297_Content_59 = {
    Text = "Scappi via. Lei non si muove per fermarti. Si limita a osservarti da dietro il ventaglio con un sorriso malizioso, come se stesse guardando un gattino terrorizzato dimenarsi per fuggire."
  },
  AvgDialog_120297_Content_6 = {
    Text = "Signorina, se sei davvero così spaventata, ho un'idea."
  },
  AvgDialog_120297_Content_60 = {
    Text = "Papà! Xu è un mostro, lei—"
  },
  AvgDialog_120297_Content_61 = {
    Text = "Non ricordi per quanto tempo hai corso, né quante svolte sbagliate hai preso. Ignorando gli sguardi attoniti dei portinai, fai irruzione negli alloggi di tuo padre, sbattendo la Porta e aggrappandoti alla sua manica."
  },
  AvgDialog_120297_Content_62 = {
    Text = "Ma nel momento in cui il nome di Xu lascia le tue labbra, un colpo pesante e bruciante ti fa barcollare."
  },
  AvgDialog_120297_Content_63 = {
    Text = "Te l'ho detto. La chiamerai <Red:\"Madre.\">"
  },
  AvgDialog_120297_Content_64 = {
    Text = "Il volto di tuo padre è terribilmente sobrio e cupo. La Follia delle ultime settimane è svanita. Ti afferra per il colletto e ti strappa via dal suo fianco."
  },
  AvgDialog_120297_Content_65 = {
    Text = "No, papà, lei si è trasformata in Tutti quelli intorno a me! Sta con tutti quegli uomini, e lei—"
  },
  AvgDialog_120297_Content_66 = {Text = "Basta!"},
  AvgDialog_120297_Content_67 = {
    Text = "Ti ho tenuta in questa Casa solo perché lei si era affezionata a te. Ma sei proprio come tua Madre dalla vita breve, del tutto ingrata."
  },
  AvgDialog_120297_Content_68 = {
    Text = "Sei un disastro, farnetichi senza senso, e osi parlare male di tua Madre! Vai nella sala e inginocchiati. Non ti muoverai fino all'ora del Gallo!"
  },
  AvgDialog_120297_Content_69 = {
    Text = "Non è mia madre! È un mostro mangia-uomini!"
  },
  AvgDialog_120297_Content_7 = {
    Text = "Se temi tanto la Signora Xu, perché non seguirla? Guarda cosa fa tutto il giorno. Se è davvero un Mostro, lo diremo insieme al Padrone e la faremo andare via da questa Casa. Che ne dici?"
  },
  AvgDialog_120297_Content_70 = {
    Text = "Urli con ogni briciolo delle tue forze. La Stanza sprofonda in un pesante Silenzio. Poi, lo senti..."
  },
  AvgDialog_120297_Content_71 = {
    Text = "<Red:La risata sommessa e gelida di tuo padre.>"
  },
  AvgDialog_120297_Content_72 = {
    Text = "<Shake:Un mostro?>"
  },
  AvgDialog_120297_Content_73 = {
    Text = "Xu è una <Red:Dea> che ho evocato attraverso innumerevoli sacrifici! Ho selezionato personalmente tutte quelle donne e le ho squarciate! Ho riversato ogni goccia della mia anima per portarla qui!"
  },
  AvgDialog_120297_Content_74 = {
    Text = "Ho provato così tante volte, ma quelle donne comuni non erano degne della sua grazia. Credi che il mio cuore non soffrisse? Mi addolorò separarmi da tua Madre."
  },
  AvgDialog_120297_Content_75 = {
    Text = "La consapevolezza ti colpisce come un fulmine. La tua mente è sommersa da un acuto ronzio nella testa; non riesci nemmeno a cominciare a elaborare le sue parole."
  },
  AvgDialog_120297_Content_76 = {
    Text = "<Shake:Dovresti sentirti onorata. La sua carne divenne il vascello affinché la Dea camminasse tra noi.>"
  },
  AvgDialog_120297_Content_77 = {
    Text = "La sua Voce è agghiacciante. Realizzi con Orrore che si è mosso, la sua Ombra che blocca la Porta, incombendo su di te mentre si avvicina."
  },
  AvgDialog_120297_Content_78 = {
    Text = "Dato che ormai sai tutto, non c'è più posto per te in questa Casa. Non permetterò che tu vada là fuori con quella tua lingua sciolta."
  },
  AvgDialog_120297_Content_79 = {
    Text = "Prima che tu possa urlare, le mani di tuo padre si serrano intorno alla tua gola. La tua Visuale inizia a ondeggiare in un mare rosso Sangue."
  },
  AvgDialog_120297_Content_8 = {
    Text = "Far andare via Lady Xu?"
  },
  AvgDialog_120297_Content_80 = {
    Text = "La <Red:Dea> è discesa. D'ora in poi, apparterrà <Red:per sempre> a me. Fama, fortuna... non significano più nulla. Finché la <Red:Dea> è con me, ogni sacrificio è valso la pena!"
  },
  AvgDialog_120297_Content_81 = {
    Text = "<Shake:Mūmā, aiuto...>"
  },
  AvgDialog_120297_Content_82 = {
    Text = "Io... non voglio morire. Voglio vivere. Mūmā..."
  },
  AvgDialog_120297_Content_83 = {
    Text = "<Change><Shake:Non voglio morire fa male fa male FA MALE Mūmā salvami SALVAMI SALVAMI AIUTO @4!!>"
  },
  AvgDialog_120297_Content_84 = {
    Text = "Qualcuno... per favore, salvatemi..."
  },
  AvgDialog_120297_Content_85 = {
    Text = "Nessuno risponde alla tua frenetica, muta preghiera."
  },
  AvgDialog_120297_Content_86 = {
    Text = "Confusione. Soffocamento. Agonia. Immobilità. E poi... quel familiare, metallico, nauseante profumo dolciastro di magnolia."
  },
  AvgDialog_120297_Content_87 = {
    Text = "<Red:<Shake:Criiiiic—>>"
  },
  AvgDialog_120297_Content_88 = {
    Text = "Attraverso la nebbia della tua coscienza che svanisce, un tentacolo nero irrompe dalla porta. Con una forza mostruosa, scaraventa Ho Fong dritto contro la spalliera del letto."
  },
  AvgDialog_120297_Content_89 = {
    Text = "Oh, mia cara... come puoi essere così crudele con una semplice bambina?"
  },
  AvgDialog_120297_Content_9 = {
    Text = "Il clacson di un'automobile risuona dal cancello principale. Ogni giorno, un volto diverso attende davanti alla Residenza Ho — uomini distinti, le Élite stesse che tuo padre cercava di blandire."
  },
  AvgDialog_120297_Content_90 = {
    Text = "Un paio di braccia delicate ti afferrano. L'aria finalmente torna a inondare i tuoi polmoni collassati. Lady Xu inclina leggermente il bordo del suo ventaglio, e una forza invisibile rimette Ho Fong in piedi."
  },
  AvgDialog_120297_Content_91 = {
    Text = "Ha semplicemente visto alcune cose che non avrebbe dovuto. Se non desidero che ricordi, allora, naturalmente, dimenticherà."
  },
  AvgDialog_120297_Content_92 = {
    Text = "Il suo tono è giocoso e disinvolto come sempre; persino la mano posata sulla tua testa sembra leggera, quasi affettuosa."
  },
  AvgDialog_120297_Content_93 = {
    Text = "Da oltre la porta, la voce di un servitore chiama."
  },
  AvgDialog_120297_Content_94 = {
    Text = "Padrone, diversi signori vi attendono nella sala principale."
  },
  AvgDialog_120297_Content_95 = {
    Text = "L'espressione di Ho Fong si contorce violentemente — ancor più orrenda di quando cercava di strangolarti."
  },
  AvgDialog_120297_Content_96 = {
    Text = "Mia adorata, perché devi ricominciare? Te l'ho detto, le cose mondane non significano più nulla per me! Solo tu — tu sei l'unica cosa che deve essere mia, e soltanto mia!"
  },
  AvgDialog_120297_Content_97 = {
    Text = "Da quando fui risvegliato da te, mia amata, gli altri non hanno alcun significato per me. Tuttavia, ricordo ancora le grandi ambizioni che nutri, e desidero offrirti quel poco di forza che possiedo."
  },
  AvgDialog_120297_Content_98 = {
    Text = "Faccio queste cose solo affinché possiamo avere più sostegno... mentre dimoriamo insieme in questo reame mortale."
  },
  AvgDialog_120297_Content_99 = {
    Text = "Non c'è la minima traccia di sincerità nei suoi occhi. Persino una bambina come te riesce a vederlo; specialmente dopo che ha appena sbattuto questo suo \"amato\" contro i mobili."
  },
  AvgDialog_120298_Content_1 = {
    Text = "Colei che Non Sogna"
  },
  AvgDialog_120298_Content_10 = {
    Text = "Ogni volta che parlo con loro, il tuo profumo mi striscia nelle narici. Il solo pensiero che tu sia intima con altri uomini... mi fa venire voglia di impazzire!"
  },
  AvgDialog_120298_Content_11 = {
    Text = "Te l'ho detto, ho solo bisogno che tu resti al mio fianco! Perché non vuoi appartenere a me soltanto? Perché continui a sedurre gli altri!"
  },
  AvgDialog_120298_Content_12 = {
    Text = "Mai prima d'ora hai visto un'espressione di così totale impotenza sul volto di Lady Xu. Sembra cercare freneticamente una fuga, i suoi occhi guizzano ovunque finché non si posano, sotto shock, su di te—nascosta dietro la finestra, inosservata da Ho Fong."
  },
  AvgDialog_120298_Content_13 = {
    Text = "D'istinto, ti abbassi sotto il davanzale. Ho Fong nota il suo sguardo e si volta brevemente, ma la sua attenzione torna su di lei quasi all'istante."
  },
  AvgDialog_120298_Content_14 = {
    Text = "Pensi ancora di fuggire? Rinuncia. Sono il tuo <Red:Connettore>. Il tuo potere è legato al mio; la tua divinità è inutile contro di me."
  },
  AvgDialog_120298_Content_15 = {
    Text = "<Red:<Shake:Ora comprendo tutto. Solo uccidendoti... solo annientandoti... potremo davvero stare insieme per sempre.>>"
  },
  AvgDialog_120298_Content_16 = {
    Text = "Con il fiato in gola, corri attraverso la dimora, stanza dopo stanza, cercando qualcuno che possa fermarlo."
  },
  AvgDialog_120298_Content_17 = {
    Text = "No. No. Non c'è nessuno. La vasta Dimora Ho è vuota. Persino i portinai sono svaniti."
  },
  AvgDialog_120298_Content_18 = {
    Text = "Un pesante lucchetto è stato calato sulla porta principale, e fuori, una nebbia grigia e senza fondo inghiotte il mondo."
  },
  AvgDialog_120298_Content_19 = {
    Text = "Se le cose continuano così, Lady Xu finirà proprio come Mūmā..."
  },
  AvgDialog_120298_Content_2 = {
    Text = "L'alba seguente non è ancora spuntata quando un urlo isterico erutta dal cortile."
  },
  AvgDialog_120298_Content_20 = {
    Text = "<Shake:Dovresti nasconderti. Dovresti restare nascosta finché non sarà tutto finito.>"
  },
  AvgDialog_120298_Content_21 = {
    Text = "Ma non c'è più nessun posto dove andare. Trovi l'oggetto che stavi cercando, lo nascondi dietro la schiena e cammini ancora una volta verso la stanza che un tempo apparteneva a tua madre."
  },
  AvgDialog_120298_Content_22 = {
    Text = "<Red:<Shake:Mia moglie... mia cara... puoi essere solo mia.>>"
  },
  AvgDialog_120298_Content_23 = {
    Text = "Nell'istante in cui alza il falcetto luccicante, i tuoi occhi incontrano quelli di Lady Xu. I Suoi Occhi si accendono per una frazione di secondo, balenando con uno sguardo di supplica disperata."
  },
  AvgDialog_120298_Content_24 = {
    Text = "Ma poi, scuote appena il capo—"
  },
  AvgDialog_120298_Content_25 = {
    Text = "<Red:Corri.>"
  },
  AvgDialog_120298_Content_26 = {
    Text = "Quegli occhi bellissimi si chiudono. La loro padrona offre il collo alla lama."
  },
  AvgDialog_120298_Content_27 = {Text = "..."},
  AvgDialog_120298_Content_28 = {Text = "ARGH!!"},
  AvgDialog_120298_Content_29 = {
    Text = "Moccioso! Come osi—"
  },
  AvgDialog_120298_Content_3 = {
    Text = "È un suono di malvagità contorta e velenosa. Prima ancora di poter pensare, un'ondata massiccia di terrore ti spinge a correre verso la fonte del rumore."
  },
  AvgDialog_120298_Content_30 = {
    Text = "Il falcetto colpisce il pavimento con un clangore. Ho Fong si stringe la parte bassa della schiena in agonia, dove il piccolo coltello che hai trovato è conficcato in profondità nella sua carne."
  },
  AvgDialog_120298_Content_31 = {
    Text = "In un impeto di furia, Ho Fong si volta per afferrarti, ma poi—all'improvviso—senti delle risatine. Non una sola voce, ma centinaia, che sciamano verso la stanza in un'ondata densa e soffocante."
  },
  AvgDialog_120298_Content_32 = {
    Text = "Le risatine esplodono in un fragore di risa incontrollabili. Dietro Ho Fong, Lady Xu è piegata in due, ride così forte che le lacrime le rigano il volto."
  },
  AvgDialog_120298_Content_33 = {
    Text = "AHAHA! AHAHAHAHAHAHA! Piccola Jasmine... la mia più cara, la mia più amata Piccola Jasmine. Non mi hai davvero delusa—sei esattamente tanto interessante quanto immaginavo!"
  },
  AvgDialog_120298_Content_34 = {
    Text = "Donne vestite in qipao gialli e neri entrano in fila nella stanza, i ventagli pieghevoli a mascherare naso e labbra. Ognuna di loro—ogni singola—possiede un paio di occhi molto, molto belli."
  },
  AvgDialog_120298_Content_35 = {
    Text = "Ho Fong è paralizzato dal terrore. Prima che possa urlare, un abbraccio freddo e morbido ti avvolge."
  },
  AvgDialog_120298_Content_36 = {
    Text = "<Red:Cosa disgustosa. Non contaminerai gli occhi della mia Piccola Jasmine.>"
  },
  AvgDialog_120298_Content_37 = {
    Text = "<Shake:Padrone...>"
  },
  AvgDialog_120298_Content_38 = {
    Text = "<Shake:Tesoro...>"
  },
  AvgDialog_120298_Content_39 = {
    Text = "Che cosa fate? Siete impazzite? Fuori! Tutte quante, FUORI!"
  },
  AvgDialog_120298_Content_4 = {
    Text = "In camera da letto, Lady Xu è messa all'angolo da Ho Fong. Gli occhi iniettati di sangue e i capelli un groviglio arruffato; sembra non aver dormito nemmeno un istante."
  },
  AvgDialog_120298_Content_40 = {
    Text = "Le concubine abbassano lentamente i ventagli. Sotto ogni singolo ventaglio c'è l'identico stesso volto."
  },
  AvgDialog_120298_Content_41 = {
    Text = "Tesoro, perché ci hai trasformate in sacrifici?"
  },
  AvgDialog_120298_Content_42 = {
    Text = "Tesoro, perché ci hai mozzato gli arti?"
  },
  AvgDialog_120298_Content_43 = {
    Text = "Innumerevoli \"Lady Xu\" ignorano la rabbia tremante di Ho Fong. Ridacchiano, circondandolo in un nodo sempre più stretto di ventagli neri e falcetti."
  },
  AvgDialog_120298_Content_44 = {
    Text = "<Change>Siamo abbastanza belle ora?"
  },
  AvgDialog_120298_Content_45 = {
    Text = "<Change>Possiamo restare con te... <RedItalic:per sempre?>"
  },
  AvgDialog_120298_Content_46 = {
    Text = "Un'ombra gargantuesca erutta da dietro Xu, levandosi verso il soffitto. Una, due, tre... innumerevoli labbra orlate di denti draconici esplodono da pelle gonfia e tumefatta, grondanti saliva, avide di divorare."
  },
  AvgDialog_120298_Content_47 = {
    Text = "Tentacoli simili a piume si espandono fino a riempire l'intera Dimora Ho. Ogni luce è soffocata; ogni rumore è soppresso."
  },
  AvgDialog_120298_Content_48 = {
    Text = "La nebbia offusca la tua visuale. Percepisci soltanto la strana fragranza di Lady Xu, e odi i suoni sinistri, lenti, soddisfatti di un festino."
  },
  AvgDialog_120298_Content_49 = {Text = "..."},
  AvgDialog_120298_Content_5 = {
    Text = "C'è una cosa su cui la mia stupida figlia aveva ragione... <Shake:Lo sento.>"
  },
  AvgDialog_120298_Content_50 = {
    Text = "Quando il risucchio ritmico finalmente cessa, un silenzioso Ho Fong si alza in piedi. Esce dalla casa e si unisce a un gruppo di uomini che attendono in eguale silenzio."
  },
  AvgDialog_120298_Content_51 = {
    Text = "L'Ispettore, il Presidente, il Direttore... le loro mogli stanno al loro fianco. Il sole nascente è abbagliante. Scorgi lo stesso misterioso, identico sorriso sul volto di ogni donna."
  },
  AvgDialog_120298_Content_52 = {Text = "..."},
  AvgDialog_120298_Content_53 = {
    Text = "Ho Fong diceva che il tuo potere era legato al suo. Ora che lui è... ridotto così, tu scomparirai?"
  },
  AvgDialog_120298_Content_54 = {
    Text = "È questa la prima cosa che chiede la mia Piccola Jasmine? Davvero... ne sono così commossa."
  },
  AvgDialog_120298_Content_55 = {
    Text = "Le sue dita tracciano lo spazio tra le tue sopracciglia, venendo a posarsi sulla punta del tuo naso."
  },
  AvgDialog_120298_Content_56 = {
    Text = "Forse scomparirò... o forse no. Ma dimmi... vorresti diventare la mia nuova Padrona, invece?"
  },
  AvgDialog_120298_Content_57 = {
    Text = "Lady Xu compie un delicato gesto nell'aria, come a cogliere qualcosa, estraendo un fazzoletto di seta sottile come un'ala di cicala. Un pennello appare, intinto d'inchiostro, e si posa dinanzi a te."
  },
  AvgDialog_120298_Content_58 = {
    Text = "Ti darò tutto ciò che Ho Fong non è riuscito a ottenere. Ti darò il meglio che questo mondo possa offrire."
  },
  AvgDialog_120298_Content_59 = {
    Text = "In una città sospesa tra antiche tradizioni e il \"Movimento della Nuova Cultura,\" tua madre si era assicurata che tu imparassi a leggere e scrivere — un raro privilegio per una figlia della tua condizione."
  },
  AvgDialog_120298_Content_6 = {
    Text = "<Shake:<Red:Quegli uomini...>>"
  },
  AvgDialog_120298_Content_60 = {
    Text = "Lady Xu prende la tua mano, in attesa che tu cominci. Il nome... come ti chiami, ancora?"
  },
  AvgDialog_120298_Content_61 = {
    Text = "Uno specchio di bronzo, macchiato di fresche gocce cremisi, riflette i lineamenti delicati e giovani di una fanciulla — simile a un grappolo di gelsomini pallidi e fragili."
  },
  AvgDialog_120298_Content_62 = {
    Text = "Sbatti le palpebre, lo sguardo vuoto. La bambina nel riflesso ricambia lo sguardo. Ora ricordi. Sul fazzoletto di seta appare la tua calligrafia infantile e incerta. Il tuo nome è—"
  },
  AvgDialog_120298_Content_63 = {
    Text = "Anch'essa Ho Fong, ma scritto con un carattere diverso, floreale."
  },
  AvgDialog_120298_Content_64 = {Text = "..."},
  AvgDialog_120298_Content_65 = {
    Text = "Quindi... la leader di quel culto sotterraneo apparso a Shencheng in seguito... era una bambina non più grande di Jenkin?!"
  },
  AvgDialog_120298_Content_66 = {
    Text = "La testa ti pulsa per i postumi del sogno, e l'apparizione improvvisa e silenziosa della donna al tuo risveglio ti provoca un violento sussulto."
  },
  AvgDialog_120298_Content_67 = {
    Text = "I dormitori dei Mythag hanno davvero bisogno di una sicurezza migliore, pensi, mentre cominci a chiederti se qualcosa potrebbe mai proteggerti da questa donna — una donna che non risparmia nemmeno i fanciulli."
  },
  AvgDialog_120298_Content_68 = {
    Text = "...Secondo i documenti, nell'Estremo Oriente esiste la leggenda di una divinità primordiale. La chiamano la <Red:\"Matriarca d'Ossidiana dai Mille Ventagli.\"> Si diletta a giocare con gli umani e si nutre della materia cerebrale di coloro che nutrono desiderio per Lei."
  },
  AvgDialog_120298_Content_69 = {
    Text = "Anche se riesci a vedere solo i suoi occhi, è dolorosamente ovvio che la donna davanti a te si sta divertendo. Si appoggia pigramente sulla mano; sospetti che potrebbe rivolgere quello stesso sguardo ardente persino a uno zerbino."
  },
  AvgDialog_120298_Content_7 = {
    Text = "Pensavi di poterlo nascondere a me? Non dimenticare, sono io quello che ti ha evocata con il <Red:cadavere> della propria moglie. Come potrei mai confondere quel profumo?"
  },
  AvgDialog_120298_Content_70 = {
    Text = "Oh, mi conosci così bene... davvero, ne sono colma di gioia."
  },
  AvgDialog_120298_Content_71 = {
    Text = "Quell'uomo stolto... trovò un antico rotolo e cercò di richiamarmi per compiere i suoi meschini inganni. Assassinò innumerevoli persone. Alla fine, non risparmiò nemmeno la moglie devota che lo amava con tutto il cuore."
  },
  AvgDialog_120298_Content_72 = {
    Text = "In origine, trovavo semplicemente divertente il risentimento della moglie. Pensai di assaggiare il cervello del suo assassino, in suo nome."
  },
  AvgDialog_120298_Content_73 = {
    Text = "Ma la Shencheng di quei giorni... era colma di un fetore torreggiante di marciume e malevolenza. Mi faceva davvero... riluttante ad andarmene."
  },
  AvgDialog_120298_Content_74 = {
    Text = "...Non hai davvero bisogno di un Connettore, vero?"
  },
  AvgDialog_120298_Content_75 = {
    Text = "Ho consultato i registri di stoccaggio del Nucleo d'Argento. Sei perfettamente in grado di completare un Rito di Risveglio da solo. Mantenere la lucidità e l'allerta senza un Connettore è per te una questione banale."
  },
  AvgDialog_120298_Content_76 = {
    Text = "Allora perché volevi legarti alla piccola Ho Fong laggiù a Shencheng? Qual era il tuo scopo?"
  },
  AvgDialog_120298_Content_77 = {
    Text = "Xu resta in silenzio. Un filo di nebbia si avvolge intorno a te, dissipando il dolore pulsante nella tua testa. Da dietro il suo ventaglio, ti fa l'occhiolino."
  },
  AvgDialog_120298_Content_78 = {
    Text = "Pensavo che in questo mondo gli adulti fossero tutti uguali, mentre ogni bambino fosse unico a modo suo."
  },
  AvgDialog_120298_Content_79 = {
    Text = "L'ho nutrita con la mia nebbia. L'ho irrigata con potere e desiderio. L'ho amata. Perché mi trattate come se avessi commesso un crimine?"
  },
  AvgDialog_120298_Content_8 = {
    Text = "Se non avessi giaciuto con loro, perché puzzerebbero della <Red:tua fragranza?>"
  },
  AvgDialog_120298_Content_80 = {
    Text = "Quello non è amore."
  },
  AvgDialog_120298_Content_81 = {Text = "..."},
  AvgDialog_120298_Content_82 = {
    Text = "Hehe. È vero, non comprendo ciò che gli umani chiamano \"amore\". Cibo, giocattoli, il potere di tramutare le menzogne in verità... Offro i doni più pregiati che questo mondo possa offrire."
  },
  AvgDialog_120298_Content_83 = {
    Text = "E naturalmente... riceverò il compenso che desidero in cambio. E il giorno in cui ti troverai nel bisogno, mio Piccolo Gelsomino... come sceglierai <Italic:tu>?"
  },
  AvgDialog_120298_Content_84 = {
    Text = "La mia Terra senza sogni ti attende. Sempre, sempre in attesa."
  },
  AvgDialog_120298_Content_85 = {
    Text = "Tra una risatina sommessa e civettuola, la nebbia si propaga — e un istante dopo, nella stanza del dormitorio non restano che le spoglie di una fragranza residua di magnolie bianche."
  },
  AvgDialog_120298_Content_9 = {
    Text = "Ride all'improvviso, un suono nevrotico e acuto. Si lancia in avanti, afferrando il polso di Xu—quello che regge il ventaglio."
  },
  AvgDialog_120313_Content_1 = {
    Text = [[
Nel frattempo
Oltre il Sole Nero]]
  },
  AvgDialog_120313_Content_10 = {
    Text = "Oltre i miliardi di mondi che brillano come stelle, quella figura familiare lotta per farsi strada attraverso le correnti tumultuose, correndo verso di te passo dopo passo."
  },
  AvgDialog_120313_Content_11 = {Text = "Ramona!!!"},
  AvgDialog_120313_Content_12 = {
    Text = "Puoi vedere la sua sagoma, il suo volto e i suoi occhi che brillano di gioia, non più una falsa illusione, non più soltanto una voce vaga."
  },
  AvgDialog_120313_Content_13 = {
    Text = "Le onde di energia della connessione del tunnel ruggiscono al loro passaggio, scompigliandoti i capelli. Finalmente, le punte delle vostre dita si toccano, e poi vi stringete in un abbraccio."
  },
  AvgDialog_120313_Content_14 = {
    Text = "La nostalgia proveniente da un altro mondo si trasforma in un alone bianco, che vortica e fluisce attraverso la tua anima."
  },
  AvgDialog_120313_Content_15 = {
    Text = "<Shake:<color=#DEDEDE>Finalmente... ti ho trovato.</color>>"
  },
  AvgDialog_120313_Content_16 = {
    Text = "Le vostre fronti si toccano, le sue mani avvolgono amorevolmente la tua schiena, la sua voce trema di gioia mentre piange."
  },
  AvgDialog_120313_Content_17 = {
    Text = "Tutta la fatica, la solitudine e il dolore si dissolvono in questo istante. Sai che la tua anima è tornata alla sua vera dimora."
  },
  AvgDialog_120313_Content_18 = {
    Text = "È pericoloso viaggiare tra le dimensioni, vero? Ti sei fatta male?"
  },
  AvgDialog_120313_Content_19 = {
    Text = "Controlli ripetutamente l'anima che ha percorso un cammino così lungo fino a te, notando soltanto la sua figura un po' più esile. Ramona scuote la testa, accarezzandoti dolcemente il viso."
  },
  AvgDialog_120313_Content_2 = {
    Text = "Discesa. Distruzione. Rinascita dalla Terra... Confronto. Combattimento. Perseveranza..."
  },
  AvgDialog_120313_Content_20 = {
    Text = "E tu? Sei rimasto solo in un mondo estraneo per così tanto tempo; dev'essere stato davvero duro per te."
  },
  AvgDialog_120313_Content_21 = {
    Text = "Una fitta di commozione ti colpisce il naso, e scuoti la testa anche tu. Nello sguardo che vi scambiate, tra le lacrime che affiorano ai vostri occhi, sorridete entrambi nello stesso istante."
  },
  AvgDialog_120313_Content_22 = {
    Text = "Pfft... Perché sorridi? Sembri stupida."
  },
  AvgDialog_120313_Content_23 = {
    Text = "Non stai sorridendo anche tu..."
  },
  AvgDialog_120313_Content_24 = {
    Text = "In un'immensa felicità, le prendi istintivamente la mano, impaziente di tornare a casa."
  },
  AvgDialog_120313_Content_25 = {Text = "!!!"},
  AvgDialog_120313_Content_26 = {
    Text = "All'improvviso, vedi le sue pupille dilatarsi bruscamente e, in un istante, lei si lancia su di te, spingendoti di lato con una forza immensa."
  },
  AvgDialog_120313_Content_27 = {
    Text = "Mentre vieni scaraventato all'indietro, vedi che una nuova Fenditura Dimensionale si è aperta dove ti trovavi un attimo prima. Un altro occhio colossale si volta e guarda Ramona, rimasta indietro."
  },
  AvgDialog_120313_Content_28 = {
    Text = "In un istante, la melma nerissima la inghiotte."
  },
  AvgDialog_120313_Content_29 = {
    Text = "<Shake:<Big:NO!!!>>"
  },
  AvgDialog_120313_Content_3 = {
    Text = "Sotto la pressione immane di quella Volontà Suprema, tutto appare così familiare."
  },
  AvgDialog_120313_Content_4 = {
    Text = "A uno a uno, gli occhi giganteschi e pallidi nella dimensione aliena si dissolvono con un boato. Il tuo spirito si avvicina gradualmente all'esaurimento. L'unica cosa che ti sostiene ora è la vibrante rosa rossa nella tua mano."
  },
  AvgDialog_120313_Content_5 = {
    Text = "Huff... Non posso cadere. Mi stanno ancora aspettando..."
  },
  AvgDialog_120313_Content_6 = {
    Text = "In uno stato confuso, il tuo cuore inizia improvvisamente a battere all'impazzata, e ti volti, seguendo questo istinto."
  },
  AvgDialog_120313_Content_7 = {
    Text = "Come una meteora che sfreccia nel cielo, o cristalli di ghiaccio che si condensano, un tunnel simile a un fascio di luce si estende verso di te, accompagnato da un suono strano ed etereo."
  },
  AvgDialog_120313_Content_8 = {
    Text = "Una voce che ha riecheggiato nella tua memoria migliaia di volte attraversa il distante spazio dimensionale alle tue spalle, risuonando nella tua mente attraverso il legame dei tuoi viticci spirituali."
  },
  AvgDialog_120313_Content_9 = {
    Text = "<Yellow:%player%>!!!"
  },
  AvgDialog_121232_Content_1 = {
    Text = "La gloria della mia terra natia brilla davanti ai miei occhi, Lord Golia, lascio il resto a voi..."
  },
  AvgDialog_121232_Content_2 = {
    Text = "Il potere divino impetuoso che brandisci... mi ricorda quella donna folle."
  },
  AvgDialog_121232_Content_3 = {
    Text = "Bene, piccolo. Preparati ad assistere al potere dei Filistea. Supera qualsiasi Benedizione divina!"
  },
  AvgDialog_121369_Content_1 = {
    Text = "Nella sala vuota, rimanevano solo gli echi dei tuoi e dei passi di Murphy."
  },
  AvgDialog_121369_Content_10 = {
    Text = "Prima che potessi elaborare l'ordine, tentacoli gelidi si serrarono attorno ai tuoi polpacci. La pressione schiacciante ti costrinse immediatamente a terra, sul freddo pavimento di pietra."
  },
  AvgDialog_121369_Content_11 = {
    Text = "Tentasti di resistere, ma una tossina paralizzante si infiltrò nei tuoi nervi, rendendoti impotente."
  },
  AvgDialog_121369_Content_12 = {
    Text = "Murphy, che stai facendo?!"
  },
  AvgDialog_121369_Content_13 = {
    Text = "Non so perché, mi sento semplicemente furioso."
  },
  AvgDialog_121369_Content_14 = {
    Text = "Un fuoco arde nel mio cuore, e vederti non fa che alimentarlo."
  },
  AvgDialog_121369_Content_15 = {
    Text = "<Italic:(Calmati, devo calmarmi... Non fare nulla che possa minare la mia dignità di Madre Divina...)>"
  },
  AvgDialog_121369_Content_16 = {
    Text = "Quindi... per cosa esattamente vuoi che mi inginocchi?"
  },
  AvgDialog_121369_Content_17 = {
    Text = "Inginocchiati e basta, non fare domande!"
  },
  AvgDialog_121369_Content_18 = {
    Text = "Il tono di Murphy era furioso. I tentacoli del polpo tamburellavano ansiosamente contro la tua gamba. Sembrava che persino lei stesse lottando per mantenere il controllo."
  },
  AvgDialog_121369_Content_19 = {
    Text = "Resistesti alla morsa della tossina paralizzante e sollevasti il capo, allungando la mano per sfiorare delicatamente la sua guancia arrossata."
  },
  AvgDialog_121369_Content_2 = {
    Text = "Da quando sei entrato, ti sei rifiutato di dire una sola parola."
  },
  AvgDialog_121369_Content_20 = {
    Text = "Murphy, stai... subendo l'influenza del potere del Fiume sacro?"
  },
  AvgDialog_121369_Content_21 = {
    Text = "Assurdità! In quanto madre di un dio, come potrei essere influenzata da simili stupide—"
  },
  AvgDialog_121369_Content_22 = {
    Text = "I tentacoli ad anelli blu risalirono lungo la tua spina dorsale, lasciando una sensazione di formicolio al loro passaggio."
  },
  AvgDialog_121369_Content_23 = {
    Text = "Prima dell'alba, devi restare qui senza muoverti."
  },
  AvgDialog_121369_Content_24 = {
    Text = "Non muoverti!"
  },
  AvgDialog_121369_Content_25 = {
    Text = "Eppure, sentisti i legami dei tentacoli allentarsi leggermente, come se una nuvola ti sostenesse. Quando tentasti di liberarti, tuttavia, la presa rimase salda, senza concederti di muoverti di un solo centimetro."
  },
  AvgDialog_121369_Content_26 = {
    Text = "Sii grato. Otterrai l'onore di accogliere l'alba con me."
  },
  AvgDialog_121369_Content_27 = {
    Text = "Come Ritorno..."
  },
  AvgDialog_121369_Content_28 = {
    Text = "Il suo respiro indugiò nel tuo orecchio. Poi, un bacio dolce e delicato si posò sulla tua fronte."
  },
  AvgDialog_121369_Content_29 = {
    Text = "Riceverai anche le benedizioni della Madre Divina."
  },
  AvgDialog_121369_Content_3 = {
    Text = "Che è successo, Murphy?"
  },
  AvgDialog_121369_Content_4 = {
    Text = "Murphy non rispose, camminando dritta verso la cima dei gradini dove si ergeva il trono."
  },
  AvgDialog_121369_Content_5 = {
    Text = "Avanzi con cautela finché lei finalmente si voltò, accomodandosi sul Trono. Il suo sguardo lievemente irato ti trafisse."
  },
  AvgDialog_121369_Content_6 = {
    Text = "Chi ti ha permesso di stare accanto a me? Stai più in basso. Non guardarmi dall'alto."
  },
  AvgDialog_121369_Content_7 = {
    Text = "Provasti confusione, ma indietreggiasti comunque di due passi, allineando il tuo sguardo con quello della giovane donna sul trono."
  },
  AvgDialog_121369_Content_8 = {
    Text = "In ginocchio."
  },
  AvgDialog_121369_Content_9 = {Text = "Eh?"},
  AvgDialog_121741_Content_1 = {
    Text = "Vasta, in Decomposizione, vuota... Questa Illusione al di sopra del \"Velo\" che ho cercato di mantenere con fantasie assurde..."
  },
  AvgDialog_121741_Content_2 = {
    Text = "Quanto sono stata sciocca e ridicola... a essermi abbandonata a questo <Italic:Paradise>..."
  },
  AvgDialog_121741_Content_3 = {
    Text = "%player%, aiutami a porre fine a questo Sogno una volta per tutte."
  },
  AvgDialog_121741_Content_4 = {
    Text = "Aiutami a reclamare... il mio fato."
  },
  AvgDialog_121742_Content_1 = {
    Text = "Pesanti catene tremano. Il mostro dietro il velo scruta l'intera nave, emettendo un lamento disperato."
  },
  AvgDialog_121742_Content_10 = {
    Text = "Addio, mio fragile e indifeso <Italic:Ieri>...!"
  },
  AvgDialog_121742_Content_2 = {
    Text = "Capisco... capisco perfettamente... il tuo attaccamento, ciò a cui non riesci a Rinunciare..."
  },
  AvgDialog_121742_Content_3 = {
    Text = "Ma ho preso la mia decisione."
  },
  AvgDialog_121742_Content_4 = {
    Text = "Murphy ricambia il Suo sguardo e, per un istante, assolutamente Tenace, vi rivolge un sorriso gentile."
  },
  AvgDialog_121742_Content_5 = {
    Text = "Per favore, guardate... il cuore dentro il mio petto..."
  },
  AvgDialog_121742_Content_6 = {
    Text = "Ancora oggi, pulsa di vita."
  },
  AvgDialog_121742_Content_7 = {
    Text = "Come durante il Rito della Navigazione, Murphy si squarcia nuovamente il petto."
  },
  AvgDialog_121742_Content_8 = {
    Text = "Questo serve per andarsene da qui. Per rincontrarvi a Mythag."
  },
  AvgDialog_121742_Content_9 = {
    Text = "Il sangue spirituale scorre dal petto di Murphy, con esili fili d'argento intrecciati, che tentano ostinatamente di lacerare il velo sopra il firmamento."
  },
  AvgDialog_121743_Content_1 = {
    Text = "Non sai da quanto tempo stai combattendo. Il cervello ti gira e le braccia sono pesanti, mentre il gigante pallido e sottile agita instancabilmente le sue braccia contro di te, rigenerandosi all'infinito ogni volta che vengono spezzate."
  },
  AvgDialog_121743_Content_10 = {
    Text = "La promessa di William è come uno scudo del personaggio invisibile che si erge davanti a te.\nLa fiducia forgiata nel corso degli anni permette alle tue forze vacillanti di risorgere dal profondo del tuo essere."
  },
  AvgDialog_121743_Content_11 = {
    Text = "È una promessa, allora. Torneremo indietro insieme."
  },
  AvgDialog_121743_Content_12 = {
    Text = "Che la Chiave d'Argento Illumini il Cammino."
  },
  AvgDialog_121743_Content_13 = {
    Text = "Che la Chiave d'Argento ci Guidi."
  },
  AvgDialog_121743_Content_2 = {
    Text = "Il sudore scivola lungo la tua fronte, offuscandoti la visuale. Non riesci nemmeno a sollevare la mano per asciugarlo."
  },
  AvgDialog_121743_Content_3 = {Text = "Merda..."},
  AvgDialog_121743_Content_4 = {
    Text = "%player%. Ti ho preso."
  },
  AvgDialog_121743_Content_5 = {
    Text = [[
Un mantello nero e rosso sventola davanti ai tuoi occhi.
Un preciso braccio meccanico ti protegge dall'assalto implacabile di ossa pallide.]]
  },
  AvgDialog_121743_Content_6 = {
    Text = "Gli arti sottili colpiscono di nuovo con furia, ma vengono bloccati ancora una volta. I detriti cadono accanto a te, sollevando nubi di fumo."
  },
  AvgDialog_121743_Content_7 = {Text = "William?"},
  AvgDialog_121743_Content_8 = {
    Text = [[
Concentrati. Tieni gli occhi su quella cosa.
Lascia le spalle a me.]]
  },
  AvgDialog_121743_Content_9 = {
    Text = "In questo nuovo mondo... assumerò temporaneamente il ruolo di tuo compagno.\nFino al giorno in cui torneremo a Mythag, fianco a fianco."
  },
  AvgDialog_121744_Content_1 = {
    Text = "Il mostro ruggisce. Piange. Il sipario celato si incrina, e il Suo corpo si solleva dalle profondità del mare."
  },
  AvgDialog_121744_Content_10 = {
    Text = "Non saper usare la forza con saggezza e affidare il proprio destino ad altri non è la via di Filistea."
  },
  AvgDialog_121744_Content_11 = {
    Text = "Il gigante agita la sua arma, puntandone l'estremità verso l'enorme massa di carne."
  },
  AvgDialog_121744_Content_12 = {
    Text = "Basta parlare. Preparazione alla battaglia!"
  },
  AvgDialog_121744_Content_13 = {
    Text = "Solo il vincitore ha il diritto di sopravvivere."
  },
  AvgDialog_121744_Content_2 = {
    Text = "No... Si sta ancora espandendo!"
  },
  AvgDialog_121744_Content_3 = {
    Text = "Un fulmine squarcia il cielo notturno nero come la pece. Nel frattempo, una lama gigantesca si abbatte con ferocia sugli arti pallidi e fragili del mostro, accompagnata da rapidi lampi di un viola cupo."
  },
  AvgDialog_121744_Content_4 = {
    Text = "...Miryam? Golia? Perché siete qui?"
  },
  AvgDialog_121744_Content_5 = {
    Text = "Madre Divina, poiché avete preso la vostra decisione... Recideremo questo pesante \"velo\" secondo la vostra volontà."
  },
  AvgDialog_121744_Content_6 = {Text = "Miryam..."},
  AvgDialog_121744_Content_7 = {
    Text = "State tranquilla, Madre Divina. Qualunque cosa abbiate intenzione di fare in futuro, i Navigatori saranno sempre il sostegno più irremovibile alle vostre spalle."
  },
  AvgDialog_121744_Content_8 = {
    Text = "Basta con le chiacchiere. Credete davvero che resteremo a guardare mentre voi due esserini cercate di combattere quel mostro?"
  },
  AvgDialog_121744_Content_9 = {
    Text = "Una Voce Familiare risuona, interrompendo le parole di Murphy. Golia si presenta insieme a Caecus."
  },
  AvgDialog_121745_Content_1 = {
    Text = "Il Mostro torreggiante alza il capo, <Italic:osservando> tutti voi da dietro il velo tenebroso."
  },
  AvgDialog_121745_Content_10 = {
    Text = "Ti prego... sii sepolta per sempre nel Mare profondo sconfinato, come la vecchia me!"
  },
  AvgDialog_121745_Content_2 = {Text = "...!!!"},
  AvgDialog_121745_Content_3 = {
    Text = "Un Legame invisibile connette Murphy e il Mostro, inevitabile, permettendole di vedere il Suo Trauma, il Suo singhiozzare, persino la Sua Confusione..."
  },
  AvgDialog_121745_Content_4 = {
    Text = "Come un bambino ferito, sta mettendo in Domanda il \"Tradimento\" della Madre."
  },
  AvgDialog_121745_Content_5 = {
    Text = "Non guardarmi, non giudicarmi, ti prego... Ho già preso la mia decisione. Questo sarà il mio ultimo <Italic:Tradimento>."
  },
  AvgDialog_121745_Content_6 = {
    Text = "Una volta, ho espresso un Desiderio al <Italic:Paradise.> Ho pregato per un <Italic:Sogno> che agognavo fin dalla giovinezza."
  },
  AvgDialog_121745_Content_7 = {
    Text = "Credevo che l'<Italic:Autorità> potesse aiutarmi a ottenere la felicità, ma alla fine non era che una vana fantasia..."
  },
  AvgDialog_121745_Content_8 = {
    Text = "Murphy sorride mentre asciuga le lacrime che le scorrono dagli angoli degli Occhi. Le asciuga lentamente, meticolosamente, finché l'ultima traccia di pianto svanisce. Alza il capo, fissando la versione gigantesca di <Italic:\"sé stessa\".>"
  },
  AvgDialog_121745_Content_9 = {
    Text = "Non ho bisogno di un Paradise. Non ho bisogno di un Sogno che inganni me stessa. Non più."
  },
  AvgDialog_121858_Content_1 = {
    Text = "Innumerevoli mostri emergono da sotto di Esso. Li ucciderai tutti.\n\nCon innumerevoli cadaveri sotto i piedi, hai raggiunto la base dell'enorme sagoma dell'entità."
  },
  AvgDialog_121858_Content_10 = {
    Text = "Questa volta, non permetterò che la vita di nessuno venga barattata per la vittoria."
  },
  AvgDialog_121858_Content_11 = {
    Text = "Preparazione alla Battaglia. Il \"Velo\" alla fine svanirà!"
  },
  AvgDialog_121858_Content_2 = {
    Text = "Questa è la mia volontà. La volontà di \"Paradise\"..."
  },
  AvgDialog_121858_Content_3 = {
    Text = "I \"Fanciulli\" non appartengono intrinsecamente alla \"Madre\" che li ha generati. Alla nascita, tuo figlio sviluppa una propria \"volontà.\""
  },
  AvgDialog_121858_Content_4 = {
    Text = "<Red:Il sogno... deve... continuare...>"
  },
  AvgDialog_121858_Content_5 = {
    Text = "Una volta dicesti che se avessimo ucciso il Signore del Dominio e trasferito l'Autorità a te..."
  },
  AvgDialog_121858_Content_6 = {
    Text = "Sì. La mia promessa è ancora valida. Hai preso la tua Determinazione?"
  },
  AvgDialog_121858_Content_7 = {
    Text = "No. Non dovrà fare un simile Sacrificio mai più."
  },
  AvgDialog_121858_Content_8 = {
    Text = "...%player%!"
  },
  AvgDialog_121858_Content_9 = {
    Text = "Il \"Nucleo\" di questo Dominio... il \"Cataclisma\" che affrontiamo... ho combattuto cose simili così tante volte da aver perso il conto."
  },
  AvgDialog_121859_Content_1 = {
    Text = "Il Potere che Esso esercita entro il velo... sta mutando..."
  },
  AvgDialog_121859_Content_2 = {
    Text = "Abbandonato, reietto... Si lamenta nella riluttanza, nella rabbia, nel pianto..."
  },
  AvgDialog_121859_Content_3 = {
    Text = "Il suo Risentimento si abbatterà su di te...!"
  },
  AvgDialog_121864_Content_1 = {
    Text = "Sorpresa? L'oracolo mi chiama, da oltre il velo..."
  },
  AvgDialog_121865_Content_1 = {
    Text = "Il mio sangue pulsa... e l'abisso intona un invito per me!"
  },
  AvgDialog_121866_Content_1 = {
    Text = "Oh Signore lontano, la Vostra devota serva offre quel poco di forza che può..."
  },
  AvgDialog_121867_Content_1 = {
    Text = "Ritieniti fortunato. Assisterai alla vera forza dei Filistei!"
  },
  AvgDialog_122640_Content_1 = {
    Text = "<Shake:Boom!—>"
  },
  AvgDialog_122640_Content_2 = {
    Text = "La dimensione inizia a tremare sotto lo Sguardo di Follia; il legame tra te e Ramona è avvolto dalla Dissoluzione, svanendo dalla vista."
  },
  AvgDialog_122640_Content_3 = {
    Text = "Inspiri bruscamente, ricacciando dentro la tempesta di agitazione che la follia suscita in te."
  },
  AvgDialog_122640_Content_4 = {
    Text = "Tieni per te questa follia... <Big:Non permetterò che la tua follia faccia del male a nessun altro!>"
  },
  AvgDialog_122641_Content_1 = {Text = "...@3!!..."},
  AvgDialog_122641_Content_2 = {
    Text = "La familiarità minacciosa. Lo sguardo familiare. Il dolore familiare che minaccia di spaccarti il cervello."
  },
  AvgDialog_122641_Content_3 = {
    Text = "Heh... Ci rivediamo, Tohuwabohu, la Volontà Suprema... Credo di doverti ringraziare, anche se non puoi sentire nulla..."
  },
  AvgDialog_122641_Content_4 = {
    Text = "Mi hai ucciso una volta, e questo mi ha insegnato una cosa..."
  },
  AvgDialog_122641_Content_5 = {
    Text = "Stringi forte la Chiave d'Argento, fissando lo sguardo proiettato dalla Sua volontà—e solo dopo ti renderai conto che stavi <Italic:sorridendo.>"
  },
  AvgDialog_122641_Content_6 = {
    Text = "In questo tuo grande sogno, nulla è immutabile e nulla è invincibile."
  },
  AvgDialog_122641_Content_7 = {
    Text = "Abbiamo atteso così a lungo questo ricongiungimento... Nemmeno tu potrai ostacolarci!"
  },
  AvgDialog_122642_Content_1 = {
    Text = "...@2... @2... @1@3...!!"
  },
  AvgDialog_122642_Content_2 = {
    Text = "Un violento impatto frantuma la dimensione. Apri i tuoi occhi iniettati di sangue, fissandoli su quella pupilla sempre più consistente."
  },
  AvgDialog_122642_Content_3 = {
    Text = "La tua coscienza ha raggiunto il limite, Tohuwabohu... Ora, torna al tuo dormiveglia!"
  },
  AvgDialog_122642_Content_4 = {
    Text = "Raccogli il tuo spirito quasi esaurito, infondendo le ultime forze mentali nella tua Chiave d'Argento."
  },
  AvgDialog_122642_Content_5 = {
    Text = "Afferrando la luce argentea come una lama, la conficchi nel dio che hai davanti—"
  },
  AvgDialog_122643_Content_1 = {
    Text = "<Big:<Shake:Ramona!!!>>"
  },
  AvgDialog_122643_Content_2 = {
    Text = "La figura familiare viene divorata dalla Dissoluzione del Suo Sguardo; rune antiche e sinistre appaiono debolmente in questo sguardo."
  },
  AvgDialog_122643_Content_3 = {
    Text = "Questi canti finiranno qui...!"
  },
  AvgDialog_122644_Content_1 = {
    Text = "Il mondo crolla e si ricostruisce davanti a te; i tuoi cari muoiono e rivivono davanti a te. Quello sguardo caotico riversa tutto il caos dell'universo nel tuo spirito."
  },
  AvgDialog_122644_Content_2 = {
    Text = "Caos, confusione, follia... Questo è ciò che il tuo potere porta da sempre."
  },
  AvgDialog_122644_Content_3 = {
    Text = "Ma non sei mai riuscito a confondermi, Tohuwabohu. Mai prima d'ora, e certamente non adesso."
  },
  AvgDialog_122644_Content_4 = {
    Text = "La luce argentea lampeggia. In mezzo a quelle illusioni senza fine, trovi il sentiero per affrontarlo—"
  },
  AvgDialog_122645_Content_1 = {
    Text = "Nella dimensione remota, un granello di luce tremola debolmente."
  },
  AvgDialog_122645_Content_2 = {
    Text = "Quello è... il \"Sacro Cuore\" di Pollux?"
  },
  AvgDialog_122645_Content_3 = {
    Text = "Mi stanno cercando... Anche loro devono essere in pericolo."
  },
  AvgDialog_122645_Content_4 = {
    Text = "Ricordo ancora quanto ero spaventata l'ultima volta, Tohuwabohu. Ma questa volta non li farò aspettare a lungo!"
  },
  AvgDialog_122646_Content_1 = {
    Text = "Un dolore acuto e lancinante assale ogni osso, ogni centimetro della tua carne. Sopporti questa pena atroce e riesci ad abbozzare un sorriso tirato."
  },
  AvgDialog_122646_Content_2 = {
    Text = "Dio Cieco e Idiota, questo non lo capirai mai: nel tuo sogno, certe sofferenze superano di gran lunga il mero dolore fisico..."
  },
  AvgDialog_122646_Content_3 = {
    Text = "Non permetterò che quelle sofferenze si ripetano!"
  },
  AvgDialog_122694_Content_1 = {
    Text = "La porta a metà del corridoio è già ricoperta di brina bianca, e sembra che si stia espandendo."
  },
  AvgDialog_122694_Content_10 = {
    Text = "Ti prego, Custode, tienimi — solo un po', ho bisogno solo di un po' di calore~ La Fata ricorderà la tua gentilezza per sempre."
  },
  AvgDialog_122694_Content_11 = {
    Text = "È la prima volta che vedi questa piccola impostora con un'espressione simile, ma una persistente diffidenza ti tiene inchiodato dove sei, col respiro che forma nuvole bianche, a muovere le membra solo per scaldarti."
  },
  AvgDialog_122694_Content_12 = {
    Text = "Ho già avvisato l'ufficio amministrativo. Arriveranno presto ad aiutarti. Resta dove sei, non muoverti, non fare nulla."
  },
  AvgDialog_122694_Content_13 = {
    Text = "Ma mi sento così male adesso... Il potere di quel fiume mi ha trascinata di nuovo in quel posto pallido... gelido... terribile..."
  },
  AvgDialog_122694_Content_14 = {
    Text = "Senza preavviso, le lacrime di Caraboo cadono dritte verso il basso, come se avesse davvero appena assistito a qualcosa di orribile."
  },
  AvgDialog_122694_Content_15 = {
    Text = "Non credo di resistere fino all'arrivo dei soccorsi, Custode. Mi dispiace... per averti sempre mentito prima..."
  },
  AvgDialog_122694_Content_16 = {
    Text = "Cristalli di ghiaccio si stanno espandendo con lei al centro, e sembra indifesa, fragile, gli occhi arrossati mentre ti fissa — barcollante, come se potesse crollare da un momento all'altro."
  },
  AvgDialog_122694_Content_17 = {Text = "Caraboo!"},
  AvgDialog_122694_Content_18 = {
    Text = "Nell'istante prima che tocchi il pavimento, ti lanci in avanti e la prendi comunque — e il secondo dopo, te ne penti."
  },
  AvgDialog_122694_Content_19 = {
    Text = "Quelle braccia gelide ti si avvolgono intorno con la disinvoltura senza ossa di qualche invertebrato, e un respiro cosparso di cristalli di neve si riversa nell'incavo del tuo collo e nel cavo del tuo orecchio."
  },
  AvgDialog_122694_Content_2 = {
    Text = "Ti fai forza e, combattendo un freddo così violento che i denti che battono potrebbero quasi morderti la lingua, spingi ad aprire la porta della stanza di Caraboo."
  },
  AvgDialog_122694_Content_20 = {
    Text = "Ih ih~ Oh no, lo sapevo. %player% è davvero un cuore tenero."
  },
  AvgDialog_122694_Content_21 = {
    Text = "Dietro di lei, qualcosa di più morbido e ancora più freddo ti avvolge pigro e stretto, trascinandoti giù attraverso strato dopo strato di neve profonda."
  },
  AvgDialog_122694_Content_22 = {
    Text = "Ti dibatti, suoni soffocati che ti si bloccano in gola, e proprio prima di perdere completamente i sensi, senti quella risatina maliziosa."
  },
  AvgDialog_122694_Content_23 = {
    Text = "Non preoccuparti. La tua Fata sarà molto, molto gentile con il suo agnellino più prezioso~"
  },
  AvgDialog_122694_Content_3 = {
    Text = "Caraboo, cosa hai fatto qu— sss, fa un freddo glaciale qui dentro."
  },
  AvgDialog_122694_Content_4 = {
    Text = "Ma quella piccola figura vispa e maliziosa non sbuca fuori in modo spettacolare per mostrare il suo ultimo scherzo, come fa sempre."
  },
  AvgDialog_122694_Content_5 = {
    Text = "Ha un insolito rossore sul viso. Ha un aspetto, beh, quasi... pietoso."
  },
  AvgDialog_122694_Content_6 = {
    Text = "Custode, cosa faccio~? Mi sento davvero strana. Il mio corpo si sente strano, anche la testa si sente strana."
  },
  AvgDialog_122694_Content_7 = {
    Text = "Ho così freddo. Quasi da morire assiderata qui."
  },
  AvgDialog_122694_Content_8 = {
    Text = "E ho anche così caldo — abbastanza da farmi cedere le gambe, non riesco a fare un solo passo."
  },
  AvgDialog_122694_Content_9 = {
    Text = "Si morde il labbro inferiore e, con gli occhi colmi di lacrime, apre le braccia verso di te — la postura di una bambina che implora di essere tenuta in braccio."
  },
  AvgDialog_122696_Content_1 = {
    Text = "Nella sala vuota, rimanevano solo gli echi dei tuoi e dei passi di Murphy."
  },
  AvgDialog_122697_Content_1 = {
    Text = "Oggi il cielo si oscura molto più in fretta del solito; pesante e plumbeo, una tempesta si sta chiaramente preparando."
  },
  AvgDialog_122697_Content_10 = {
    Text = "Alza lo sguardo, il volto arrossato da una febbre innaturale. Un sorriso si propaga sulle sue labbra — un misto inquietante di confusione e pura follia."
  },
  AvgDialog_122697_Content_11 = {
    Text = "Combatti con me. Qui e ora!"
  },
  AvgDialog_122697_Content_13 = {
    Text = "Prima che tu possa proferire parola, la sua ascia fende l'aria. Ti sfiora la guancia con una precisione terrificante, lasciando dietro di sé nient'altro che un sibilo d'aria gelida."
  },
  AvgDialog_122697_Content_14 = {
    Text = "Il bozzetto d'aria fredda s'insinua nel colletto e ti gela il petto, facendo correre un brivido istintivo lungo la schiena."
  },
  AvgDialog_122697_Content_15 = {
    Text = "Ma che ti prende?! Perché dovremmo combattere?"
  },
  AvgDialog_122697_Content_16 = {
    Text = "Le tue proteste cadono nel vuoto; sia l'arma che la sua padrona sono al di là di ogni parola."
  },
  AvgDialog_122697_Content_17 = {
    Text = "<Shake:Mouchette!?>"
  },
  AvgDialog_122697_Content_18 = {
    Text = "Mouchette! Guardami!"
  },
  AvgDialog_122697_Content_19 = {
    Text = "Sotto il peso delle tue grida insistenti, l'ascia finalmente si arresta. Si conficca nel muro, a pochi centimetri dalla tua spalla, affondando in profondità nella pietra."
  },
  AvgDialog_122697_Content_2 = {
    Text = "Per evitare di inzupparti, ti affretti verso i dormitori, ma una sagoma ti blocca il sentiero."
  },
  AvgDialog_122697_Content_20 = {
    Text = "La bambina è proprio di fronte a te. Il suo volto è rovente mentre stringe i pugni, afferrandoti con violenza per il colletto."
  },
  AvgDialog_122697_Content_21 = {
    Text = "<Shake:Taci... Fa male... Sto soffrendo... Solo un combattimento può farlo smettere...>"
  },
  AvgDialog_122697_Content_22 = {
    Text = "La sua presa si stringe fino a quando le dita diventano esangui e pallide — muta testimonianza della sua ostinata resistenza a cedere."
  },
  AvgDialog_122697_Content_23 = {
    Text = "Lo odio... Odio quando la gente mi impone la propria volontà..."
  },
  AvgDialog_122697_Content_24 = {
    Text = "Pensi che una cosetta come il Fiume sacro possa spezzarmi? <Shake:Mi stai... gravemente sottovalutando.>"
  },
  AvgDialog_122697_Content_25 = {
    Text = "Espira bruscamente, cercando di espellere la corruzione del Fiume. Ma lo senti — il calore che emana da lei, gli impulsi travolgenti e la disperata guerra interiore che sta perdendo."
  },
  AvgDialog_122697_Content_26 = {
    Text = "Percependo la sua disperazione, sospiri sommessamente. Le prendi la mano nella tua e guidi dolcemente le sue dita di nuovo sull'impugnatura dell'ascia."
  },
  AvgDialog_122697_Content_27 = {
    Text = "<Shake:Che stai facendo?>"
  },
  AvgDialog_122697_Content_28 = {
    Text = "Vuoi combattere? E sia."
  },
  AvgDialog_122697_Content_29 = {
    Text = "In qualunque modo tu voglia farlo, e per tutto il tempo necessario — io non me ne vado da nessuna parte."
  },
  AvgDialog_122697_Content_3 = {
    Text = "Mouchette? C'è qualcosa che non va?"
  },
  AvgDialog_122697_Content_30 = {Text = "..."},
  AvgDialog_122697_Content_31 = {
    Text = "I suoi occhi si spalancano per lo shock, scrutando i tuoi in cerca di un accenno di scherzo, senza trovarne alcuno."
  },
  AvgDialog_122697_Content_32 = {
    Text = "In quel momento, il cielo finalmente si spezza. Una goccia vagante atterra sulla guancia di Mouchette, scivola lungo il mento e svanisce nel tuo colletto, tracciando una linea fredda sulla tua pelle."
  },
  AvgDialog_122697_Content_33 = {
    Text = "Poi arriva il diluvio. La pioggia martella la terra con un ritmo selvaggio, pungendo i vostri volti e lavando via la tensione con un freddo, umido prurito."
  },
  AvgDialog_122697_Content_34 = {
    Text = "<Shake:Hahaha! QUESTA è la risposta che volevo.>"
  },
  AvgDialog_122697_Content_35 = {
    Text = "Le cose stanno finalmente iniziando a farsi interessanti, non è vero?"
  },
  AvgDialog_122697_Content_36 = {
    Text = "Strappa l'ascia dal muro. Ma invece di brandirla, resta semplicemente lì, fissando i suoi occhi nei tuoi."
  },
  AvgDialog_122697_Content_37 = {
    Text = "Di solito non faccio \"corpo a corpo,\" ma suppongo sia bene provare cose nuove ogni tanto, no?"
  },
  AvgDialog_122697_Content_38 = {
    Text = "La vita è lunga, dopotutto... e i migliori \"piaceri\" vanno assaporati lentamente, nella carne."
  },
  AvgDialog_122697_Content_39 = {
    Text = "Si avvicina a te, lasciandosi l'ascia alle spalle. L'arma si appoggia silenziosa al muro, arresa al freddo battesimo della pioggia scrosciante."
  },
  AvgDialog_122697_Content_4 = {
    Text = "Tiene il capo chino, in silenzio. Puoi intuire il suo tormento interiore solo dal modo in cui le nocche sono diventate bianche, stringendo l'ascia con forza tremante."
  },
  AvgDialog_122697_Content_5 = {
    Text = "<Shake:Mouchette!?>"
  },
  AvgDialog_122697_Content_6 = {
    Text = "Infine parla, la voce venata da un insolito tremolio di esitazione."
  },
  AvgDialog_122697_Content_7 = {
    Text = "%player%, io... Ho bisogno del tuo aiuto..."
  },
  AvgDialog_122697_Content_8 = {
    Text = "Aiuto? Certo. Di cosa hai bisogno?"
  },
  AvgDialog_122697_Content_9 = {
    Text = "<Shake:Ho bisogno che tu...>"
  },
  AvgDialog_122700_Content_1 = {
    Text = "Benvenuto/a nel mio teatro. Sei puntuale, {Male=Signor, Female=Signorina} Custode."
  },
  AvgDialog_122700_Content_10 = {
    Text = "Propagarsi... rinascere... non dirmi che anche tu sei—"
  },
  AvgDialog_122700_Content_11 = {
    Text = "Ah, in realtà... mi sono appena ricordato/a che il compito del Professor Dor non è ancora finito... credo sia meglio che io—"
  },
  AvgDialog_122700_Content_12 = {
    Text = "Ti volti per andartene. Ma i tuoi piedi ti portano avanti da soli, conducendoti a fermarti davanti ad Arachne."
  },
  AvgDialog_122700_Content_13 = {
    Text = "Sì, sono sotto l'influenza del fiume... e tu sei sotto la presa del destino. Questa è una notte che appartiene solo a noi due."
  },
  AvgDialog_122700_Content_14 = {
    Text = "Uno spettacolo che era sempre destinato a essere messo in scena—e finalmente, il suo protagonista predestinato è arrivato."
  },
  AvgDialog_122700_Content_15 = {
    Text = "Il respiro di Arachne è ora al tuo orecchio. Caldo, e appena percettibile."
  },
  AvgDialog_122700_Content_16 = {
    Text = "Il suo sorriso resta sereno come sempre. Ma nel profondo di quegli occhi insondabili, qualcosa arde: una fiamma che non hai mai visto prima, come se potesse consumare tutto ciò che tocca."
  },
  AvgDialog_122700_Content_17 = {
    Text = "N-No, non posso... Arachne, io..."
  },
  AvgDialog_122700_Content_18 = {
    Text = "Non c'è bisogno di fuggire, %player%. La tela ha intessuto ogni possibilità al suo posto. Ci guiderà entrambi attraverso lo spettacolo di questa notte."
  },
  AvgDialog_122700_Content_19 = {
    Text = "Una tela invisibile si chiude intorno a te, sottraendoti ogni ultima briciola di forza, inghiottendo ogni impulso di resistere."
  },
  AvgDialog_122700_Content_2 = {
    Text = "Spingi le pesanti porte del teatro. La luce lunare cade in fasci obliqui attraverso le alte finestre. L'aria fresca della notte e la voce gentile di Arachne proveniente da qualche parte all'interno ti risvegliano bruscamente."
  },
  AvgDialog_122700_Content_20 = {
    Text = "I fili si tendono. Guardi il volto così vicino al tuo, e il cuore ti sobbalza, il respiro si fa più rapido."
  },
  AvgDialog_122700_Content_21 = {
    Text = "Il destino impone che tu non abbia mai voluto fuggire. Hai voluto questo: <Italic:Tu> hai voluto venire qui, hai voluto vedere questo spettacolo fino alla fine, senza altro pubblico che voi due."
  },
  AvgDialog_122700_Content_22 = {
    Text = "Tu... hai riscritto il mio destino?!"
  },
  AvgDialog_122700_Content_23 = {
    Text = "Non ho mai riscritto nulla, {Male=Signor, Female=Signorina} Custode. Ho solo riportato il tuo destino sul sentiero che era sempre destinato a percorrere."
  },
  AvgDialog_122700_Content_24 = {
    Text = "Arachne... avresti potuto cambiare il corso delle cose. Avresti potuto impedire all'influenza del fiume di raggiungerti... Perché non l'hai fatto?"
  },
  AvgDialog_122700_Content_25 = {
    Text = "Perché avrei dovuto?"
  },
  AvgDialog_122700_Content_26 = {
    Text = "Per un'attrice che ha memorizzato il copione da tempo, l'imprevisto è il dono più raro che il destino abbia mai concesso..."
  },
  AvgDialog_122700_Content_27 = {
    Text = "Le dolci parole di Arachne si muovono al tuo orecchio. Non è più distante, non è più serena. Il suo respiro trema lievemente, il suo sorriso incredibilmente vicino."
  },
  AvgDialog_122700_Content_28 = {
    Text = "E a quanto pare... non ho nulla in contrario a un finale in cui nessuno viene ferito."
  },
  AvgDialog_122700_Content_29 = {
    Text = "La tela di fili è fredda, flessuosa, aderente con una vicinanza che non lascia spazio per respirare, si stringe sempre più, premendo attraverso il tessuto, contro la pelle."
  },
  AvgDialog_122700_Content_3 = {
    Text = "Aspetta! Dovrei essere addormentato/a nel mio dormitorio. Come sono finito/a qui... sei stata tu?"
  },
  AvgDialog_122700_Content_30 = {
    Text = "Poi i cheliceri si chiudono intorno a te, e freddi pedipalpi dischiudono le tue labbra, sigillando qualsiasi resistenza che non aveva ancora trovato le sue parole."
  },
  AvgDialog_122700_Content_31 = {
    Text = "I fili iniziano a guidare le tue membra. Dolcemente, e senza appello."
  },
  AvgDialog_122700_Content_32 = {
    Text = "Non preoccuparti, Custode. Non c'è bisogno di resistere a ciò che il destino ha scelto di donarti."
  },
  AvgDialog_122700_Content_33 = {
    Text = "Perché... è ciò che vuoi anche tu, non è vero?"
  },
  AvgDialog_122700_Content_34 = {
    Text = "...Sì, Arachne... questo è... ciò che voglio..."
  },
  AvgDialog_122700_Content_35 = {
    Text = "Naturalmente. Non sei mai stato una marionetta del destino. Sei il Custode di Mythag, colui che tiene il proprio destino nelle proprie mani."
  },
  AvgDialog_122700_Content_36 = {
    Text = "Questo è esattamente ciò che vuoi. È il destino che si piega alla tua volontà. È il tuo corpo che risponde al tuo stesso richiamo."
  },
  AvgDialog_122700_Content_37 = {
    Text = "I fili fremono, come il destino che tira un archetto sulle corde. Allunghi la mano, percorrendo le zampe di ragno che ondeggiano dolcemente nell'aria, percorrendo le mani che non hanno mai smesso di girare il fuso, percorrendo le linee di quel volto gentile."
  },
  AvgDialog_122700_Content_38 = {
    Text = "Quel volto familiare. La compassione che porta sempre con sé, la quiete che non lo abbandona mai. E ora, appena appena, qualcos'altro—un calore che affiora in superficie, senza difese, che non hai mai visto prima."
  },
  AvgDialog_122700_Content_39 = {
    Text = "Accogliamo ciò che il destino ci ha portato, insieme... {Male=Signor, Female=Signorina} Custode."
  },
  AvgDialog_122700_Content_4 = {
    Text = "Hai seguito la tua stessa volontà. <Italic:Volevi> venire qui. L'avevi dimenticato?"
  },
  AvgDialog_122700_Content_40 = {
    Text = "Due fili del destino si avvolgono l'uno intorno all'altro, tirando, cedendo, senza sosta. Le increspature tremanti si propagano lungo la tela invisibile, dissolvendosi verso un confine sconfinato e irraggiungibile."
  },
  AvgDialog_122700_Content_41 = {Text = "..."},
  AvgDialog_122700_Content_5 = {
    Text = "Ti sorride. Una pressione, come il peso del destino stesso, si chiude da ogni direzione."
  },
  AvgDialog_122700_Content_6 = {
    Text = "Il mondo ha sempre visto il destino come una catena ineluttabile, la fonte di tutte le sue sofferenze."
  },
  AvgDialog_122700_Content_7 = {
    Text = "Ma tu e io, che abbiamo toccato i fili del destino con le nostre stesse mani, sappiamo bene che è solo ciò che noi stessi abbiamo scelto di creare."
  },
  AvgDialog_122700_Content_8 = {
    Text = "Propagarsi, affinché possiamo essere distrutti. Essere distrutti, affinché possiamo rinascere."
  },
  AvgDialog_122700_Content_9 = {
    Text = "Ancora e ancora, senza fine... Il destino non è forse solo questo?"
  },
  AvgDialog_122780_Content_1 = {
    Text = "Messaggio da Lontano"
  },
  AvgDialog_122780_Content_2 = {
    Text = "Questo è un documento di prova"
  },
  AvgDialog_122780_Content_3 = {
    Text = "Questo è un documento di prova"
  },
  AvgDialog_122780_Content_4 = {
    Text = "Questo è un documento di prova"
  },
  AvgDialog_122780_Content_5 = {
    Text = "Questo è un documento di prova"
  },
  AvgDialog_122780_Content_6 = {
    Text = "Questo è un documento di prova"
  },
  AvgDialog_122780_Content_7 = {
    Text = "Fine della dichiarazione"
  },
  AvgDialog_123116_Content_1 = {
    Text = "L'agnello smarrito"
  },
  AvgDialog_123116_Content_10 = {
    Text = "Ma ogni sacerdote giunto a Howick — John, James, Anderson — è semplicemente svanito nel nulla poco dopo il suo arrivo."
  },
  AvgDialog_123116_Content_11 = {
    Text = "Sono anime gentili e devote... dopo il Cataclisma, hanno seguito gli insegnamenti del Padre di Tutto, offrendosi volontari per recarsi nelle parrocchie periferiche a diffondere il Suo Vangelo."
  },
  AvgDialog_123116_Content_12 = {
    Text = "Persino in una città grande come Londra, la gente comune riesce a malapena a badare a sé stessa dopo il disastro. La situazione a Howick dev'essere ancora peggiore. Perché mai dovrebbero..."
  },
  AvgDialog_123116_Content_13 = {
    Text = "Per la stessa ragione per cui fai ciò che fai per questo mondo, e per il mondo da cui provieni, Pallido Messaggero."
  },
  AvgDialog_123116_Content_14 = {
    Text = "Salvador congiunge le mani, la sua espressione devota e traboccante di compassione."
  },
  AvgDialog_123116_Content_15 = {
    Text = "Perché i nostri fratelli e le nostre sorelle soffrono."
  },
  AvgDialog_123116_Content_16 = {
    Text = "Sradicare tale miseria da questa terra è il dovere degli emissari del Padre di Tutto. Non possono abbandonare chi è nella disperazione solo perché il cammino è lungo."
  },
  AvgDialog_123116_Content_17 = {
    Text = "...Capisco."
  },
  AvgDialog_123116_Content_18 = {
    Text = "Padre Salvador, vi aiuterò a trovarli. Che siano vivi o morti."
  },
  AvgDialog_123116_Content_19 = {Text = "Ora"},
  AvgDialog_123116_Content_2 = {
    Text = "Howick, una cittadina remota alla periferia di Londra"
  },
  AvgDialog_123116_Content_20 = {
    Text = "Salvador, mi pare di vedere una luce più avanti..."
  },
  AvgDialog_123116_Content_21 = {
    Text = "La tua voce si spezza bruscamente di fronte a quella vista inaspettata: una gabbia rozza e improvvisata si staglia in modo stridente al centro della caverna vuota."
  },
  AvgDialog_123116_Content_22 = {
    Text = "Almeno una dozzina di persone vi sono stipate dentro. Appaiono sfinite; molte sono coperte di lividi e ferite aperte."
  },
  AvgDialog_123116_Content_23 = {
    Text = "<Shake:Henry... è morto? Gli hanno sparato. Hanno ammazzato Henry...!>"
  },
  AvgDialog_123116_Content_24 = {
    Text = "La donna si stringe la testa tra le mani e mormora tra sé, lo sguardo frenetico e i tremiti violenti tradiscono la sua psiche spezzata."
  },
  AvgDialog_123116_Content_25 = {
    Text = "D'un tratto, alza lo sguardo e nota il tuo avvicinarsi."
  },
  AvgDialog_123116_Content_26 = {
    Text = "<Shake:No, stanno arrivando! Vi prego, fateci uscire di qui!>"
  },
  AvgDialog_123116_Content_27 = {
    Text = "Il suo sfogo attira l'attenzione degli altri. Un uomo si lancia verso le sbarre e ti afferra il braccio con forza disperata."
  },
  AvgDialog_123116_Content_28 = {
    Text = "Salvatemi! Non voglio essere bestiame umano! Non voglio essere sacrificato!"
  },
  AvgDialog_123116_Content_29 = {
    Text = "Aaaaah—FATECI USCIRE DI QUI!"
  },
  AvgDialog_123116_Content_3 = {
    Text = "Se le informazioni fornite dalla \"Doll\" sono corrette, dovrebbero trovarsi proprio qui."
  },
  AvgDialog_123116_Content_30 = {
    Text = "Chiudi quella @4 bocca!"
  },
  AvgDialog_123116_Content_31 = {
    Text = "Un boato fragoroso riduce al silenzio le vittime. I prigionieri appaiono completamente pietrificati dal proprietario di quella voce, rannicchiati nel terrore."
  },
  AvgDialog_123116_Content_32 = {
    Text = "Il rito non è nemmeno ancora iniziato! Porci, siete così impazienti di morire?!"
  },
  AvgDialog_123116_Content_33 = {
    Text = "Segue il suono di passi affrettati."
  },
  AvgDialog_123116_Content_34 = {
    Text = "Devono essere i cultisti che tengono prigioniere queste persone. %player%, dovremmo..."
  },
  AvgDialog_123116_Content_35 = {
    Text = "Restiamo nascosti per ora. Troveremo un modo per salvarli dopo. Sono armati di fucili; se la situazione degenera, non potremo garantire l'incolumità dei prigionieri."
  },
  AvgDialog_123116_Content_36 = {
    Text = "Tuttavia, l'uomo si rifiuta ancora di lasciarti andare, stringendoti il braccio con una forza tale da quasi spezzarti l'osso."
  },
  AvgDialog_123116_Content_37 = {
    Text = "Salvateci! Salvateci adesso! Se non ci salverete, allora morirete con noi!!"
  },
  AvgDialog_123116_Content_38 = {
    Text = "I passi si avvicinano. L'uomo è chiaramente troppo fuori di sé per ascoltare la ragione."
  },
  AvgDialog_123116_Content_39 = {
    Text = "Stringi i denti e lo rendi incosciente con un colpo rapido."
  },
  AvgDialog_123116_Content_4 = {
    Text = "Mi fido del tuo giudizio, %player%."
  },
  AvgDialog_123116_Content_40 = {
    Text = "Hah... Hah..."
  },
  AvgDialog_123116_Content_41 = {
    Text = "Una risatina sommessa si leva dall'angolo della gabbia."
  },
  AvgDialog_123116_Content_42 = {
    Text = "Istintivamente volti il capo. Una bambina vestita in modo bizzarro ti osserva, il suo debole sorriso appare inquietantemente distaccato dalla follia circostante."
  },
  AvgDialog_123116_Content_43 = {
    Text = "Che affascinante. Un istante dici di essere qui per salvarli, e l'istante dopo li stendi a terra privi di sensi..."
  },
  AvgDialog_123116_Content_44 = {
    Text = "La sua totale mancanza di preoccupazione ti lascia momentaneamente attonito."
  },
  AvgDialog_123116_Content_45 = {
    Text = "Oh, non badare a me. Prego, continua pure."
  },
  AvgDialog_123116_Content_46 = {
    Text = "Ma faresti bene a sbrigarti; i cultisti sono quasi qui."
  },
  AvgDialog_123116_Content_47 = {Text = "...?"},
  AvgDialog_123116_Content_48 = {
    Text = "Il tempo stringe. Senza il lusso di chiacchiere oziose, lasci la bambina alle spalle e ti dilegui nelle ombre con Salvador."
  },
  AvgDialog_123116_Content_49 = {
    Text = "Pochi istanti dopo, due cultisti armati di fucili a pompa fanno la loro comparsa. Si dispongono ai lati della gabbia, puntando le armi sui prigionieri all'interno."
  },
  AvgDialog_123116_Content_5 = {
    Text = "Che il Padre di Tutto benedica i nostri fratelli e le nostre sorelle e li protegga dalle ombre. Che possano continuare a dimorare in pace."
  },
  AvgDialog_123116_Content_50 = {
    Text = "Chi stava facendo tutto quel baccano? Farsi avanti!"
  },
  AvgDialog_123116_Content_51 = {
    Text = "Nessuno risponde. I prigionieri si rannicchiano negli angoli tremando o fissano il vuoto in uno stato di torpore catatonico. Tutti—tranne quella strana ragazza."
  },
  AvgDialog_123116_Content_52 = {
    Text = "Mantiene il suo sorriso disinvolto e noncurante, osservando con aria svagata gli uomini armati."
  },
  AvgDialog_123116_Content_53 = {
    Text = "È impazzita? Sembra fin troppo rilassata per qualcuno che sta per incontrare la propria fine."
  },
  AvgDialog_123116_Content_54 = {
    Text = "C'è ancora qualcuno in questo mondo maledetto che non sia impazzito? Ah! Se <Italic:noi> fossimo pazzi, forse le cose sarebbero più facili."
  },
  AvgDialog_123116_Content_55 = {
    Text = "Spero solo che questo rito funzioni. Sono stufo marcio di questa strana nebbia..."
  },
  AvgDialog_123116_Content_56 = {
    Text = "Dunque, quando inizia esattamente il vostro rito?"
  },
  AvgDialog_123116_Content_57 = {
    Text = "I cultisti si immobilizzano in evidente confusione."
  },
  AvgDialog_123116_Content_58 = {
    Text = "Con chi stai parlando? Con noi?"
  },
  AvgDialog_123116_Content_59 = {
    Text = "Ma davvero? Smettila di perdere tempo e rispondi alla mia domanda."
  },
  AvgDialog_123116_Content_6 = {
    Text = "Salvador abbassa devotamente lo sguardo per sussurrare una preghiera, prima di aprire la strada verso le profondità della grotta."
  },
  AvgDialog_123116_Content_60 = {
    Text = "Infuriato dal suo tono, il cultista ghigna e le punta il fucile alla gamba."
  },
  AvgDialog_123116_Content_61 = {
    Text = "Pazza maledetta. Tutto quello che devi fare è stare seduta lì e aspettare di essere sacrificata. Non hai chiaramente idea di cosa stia succedendo qui."
  },
  AvgDialog_123116_Content_62 = {Text = "Bang—"},
  AvgDialog_123116_Content_63 = {
    Text = "Una Forza Invisibile devia il colpo, mandando il proiettile contro il soffitto della caverna dove colpisce con una debole scintilla."
  },
  AvgDialog_123116_Content_64 = {
    Text = "Tu e Salvador emergete dall'Oscurità, lanciando un'improvvisa imboscata."
  },
  AvgDialog_123116_Content_66 = {
    Text = "Buon tempismo. Suppongo che voi due non siate stupidi come sembrate."
  },
  AvgDialog_123116_Content_67 = {
    Text = "Grazie per averli distratti per noi, gentile signora."
  },
  AvgDialog_123116_Content_68 = {
    Text = "Che il Padre di Tutto vi benedica."
  },
  AvgDialog_123116_Content_69 = {
    Text = [[
Salvador traccia il Sacro Segno dell'Onnipotente nell'aria.
Nel frattempo, confischi le armi dei cultisti e li costringi in ginocchio davanti alla gabbia per iniziare l'interrogatorio.]]
  },
  AvgDialog_123116_Content_7 = {
    Text = "Tre giorni fa"
  },
  AvgDialog_123116_Content_70 = {
    Text = "Parlate. Quando si terrà il Rito? Dove si svolge? E avete qualcosa a che fare con la scomparsa dei Sacerdoti della Cattedrale della Vita?!"
  },
  AvgDialog_123116_Content_71 = {
    Text = "Cattedrale della Vita... sacerdoti...?"
  },
  AvgDialog_123116_Content_72 = {
    Text = "Avete sentito bene. John, James, Anderson. Dove sono?"
  },
  AvgDialog_123116_Content_73 = {
    Text = "Il cultista si ferma un istante, poi scoppia in una risata selvaggia e maniacale."
  },
  AvgDialog_123116_Content_74 = {
    Text = "<Shake:Ci redimeremo secondo la volontà del Padre Supremo! Sì, il Sereno Reame Libero dalla Dissoluzione è alle porte!>"
  },
  AvgDialog_123116_Content_75 = {
    Text = "<Shake:<Big:È disceso! Voi miserabili senza benedizione marcirete qui mentre il mondo precipita in rovina!>>"
  },
  AvgDialog_123116_Content_76 = {
    Text = "Dunque, il Rito sta per avere Inizio? <Small:Sembra che dovrò affrettarmi.>"
  },
  AvgDialog_123116_Content_77 = {
    Text = "Sbrigati... Cosa intendi? Cosa sai?"
  },
  AvgDialog_123116_Content_78 = {
    Text = "La ragazza non risponde. Ti lancia un'occhiata insieme a Salvador con un sorriso innocente e dolce, eppure percepisci una punta affilata di astuzia celata sotto di esso."
  },
  AvgDialog_123116_Content_79 = {
    Text = "Ah, giusto. Il mio nome è Mouchette. Quanto al vostro — non disturbatevi, non mi interessa."
  },
  AvgDialog_123116_Content_8 = {
    Text = "Tutti i sacerdoti inviati a Howick dalla Cattedrale della Vita sono scomparsi?"
  },
  AvgDialog_123116_Content_80 = {
    Text = "So dove si trova il luogo del rito, e posso condurti là. Ma..."
  },
  AvgDialog_123116_Content_81 = {
    Text = "Prima avrò bisogno di un piccolo favore."
  },
  AvgDialog_123116_Content_82 = {
    Text = "Che tipo di favore? Sii chiaro, per cortesia."
  },
  AvgDialog_123116_Content_83 = {
    Text = "Ancora una volta, non offre risposta. Canticchiando una melodia sporadica e spezzata, si allontana."
  },
  AvgDialog_123116_Content_84 = {
    Text = "Hehe☆! Prima ho una faccenda da sbrigare. Ci vediamo fuori tra dieci minuti~"
  },
  AvgDialog_123116_Content_85 = {Text = "..."},
  AvgDialog_123116_Content_86 = {
    Text = "Questo va bene comunque. Possiamo usare il tempo per contattare la Chantry e organizzare rinforzi per mettere in salvo queste povere anime."
  },
  AvgDialog_123116_Content_87 = {
    Text = "Suppongo che non abbiamo altra scelta."
  },
  AvgDialog_123116_Content_88 = {
    Text = "Mentre osservi la ragazza allontanarsi, un crescente senso di inquietudine ti risale lungo la schiena."
  },
  AvgDialog_123116_Content_89 = {
    Text = "L'origine è la stridente disconnessione celata sotto il suo aspetto giovanile: una personalità che sembra quasi umana, eppure risulta palesemente, innegabilmente... falsa."
  },
  AvgDialog_123116_Content_9 = {
    Text = "Sì. Dopo aver perso i contatti con Padre White, responsabile della parrocchia di Howick, la Cattedrale ha deciso di inviare rinforzi."
  },
  AvgDialog_123117_Content_1 = {
    Text = "In Argento e Sangue"
  },
  AvgDialog_123117_Content_10 = {
    Text = "...Non avrei proprio dovuto assecondarti."
  },
  AvgDialog_123117_Content_100 = {
    Text = "Mouchette... se riesci a sentirmi... ti prego. Te lo imploro."
  },
  AvgDialog_123117_Content_101 = {
    Text = "Eppure, il vuoto resta deserto. La ragazza di nome Mouchette non c'è più."
  },
  AvgDialog_123117_Content_102 = {Text = "..."},
  AvgDialog_123117_Content_103 = {
    Text = "Chiudi gli occhi, esalando un sospiro spezzato. Il tempo è scaduto. Salvador sta morendo là fuori, e il Varco si sta allargando. Devi muoverti."
  },
  AvgDialog_123117_Content_104 = {
    Text = "Mi dispiace di averti trascinata in questo incubo. Mi dispiace di non essere riuscito a riportarti a casa."
  },
  AvgDialog_123117_Content_105 = {
    Text = "Recidi la connessione al suo Reame dello Spirito."
  },
  AvgDialog_123117_Content_106 = {
    Text = "Un capogiro ti travolge mentre il tuo spirito si ricongiunge bruscamente al corpo. Sei tornato al punto di inizio."
  },
  AvgDialog_123117_Content_107 = {
    Text = "Il Portale invisibile geme nella sua agonia mortale, e l'ascia di Mouchette è pesante nelle tue mani."
  },
  AvgDialog_123117_Content_108 = {
    Text = "<Shake:Mouchette... io...>"
  },
  AvgDialog_123117_Content_109 = {
    Text = "Stringi l'impugnatura, guardando la ragazza silenziosa. Resta lì, tra le rovine della sua sanità mentale, in attesa del colpo di grazia."
  },
  AvgDialog_123117_Content_11 = {
    Text = "Lasci uscire un pesante sospiro, le spalle afflosciate. Salvador osserva lo scambio, e una risata sommessa e calda gli sfugge dalle labbra."
  },
  AvgDialog_123117_Content_110 = {
    Text = "La guardi negli occhi, cercando la ragazza che sorrideva, la ragazza che scherzava. Non riesci a credere che se ne sia andata."
  },
  AvgDialog_123117_Content_111 = {
    Text = "<Shake:Per quanto tempo... hai intenzione di... restare lì a fissarmi...?>"
  },
  AvgDialog_123117_Content_112 = {
    Text = "Mouchette! Sei tornata?!"
  },
  AvgDialog_123117_Content_113 = {
    Text = "<Shake:Non proprio... ma... vi ho sentito...>"
  },
  AvgDialog_123117_Content_114 = {
    Text = "Hai ragione... Non posso semplicemente... arrendermi senza lottare."
  },
  AvgDialog_123117_Content_115 = {
    Text = "Si lancia in avanti con l'ultima scintilla di vita, la mano che si chiude sulla Chiave d'Argento sul tuo petto."
  },
  AvgDialog_123117_Content_116 = {
    Text = "Qualunque cosa accada... la Porta muore con me."
  },
  AvgDialog_123117_Content_117 = {
    Text = "Non permetterò che questo posto... diventi un altro mondo di nebbia."
  },
  AvgDialog_123117_Content_118 = {
    Text = "Non dopo aver visto quanto duramente hai lottato per salvarlo."
  },
  AvgDialog_123117_Content_119 = {
    Text = "La Chiave d'Argento esplode, una supernova di luce bianca che cancella la tua visuale e inghiotte il mondo."
  },
  AvgDialog_123117_Content_12 = {
    Text = "Mouchette è... una bambina unica. Molto speciale, ma un'anima buona nonostante tutto."
  },
  AvgDialog_123117_Content_120 = {
    Text = "Un coro di urla riempie l'aria — il lamento del Portale, la distorsione del flauto, il suono di un mondo che si frantuma."
  },
  AvgDialog_123117_Content_121 = {
    Text = "O forse è tutta un'allucinazione. In quel mare di bianco, il tempo e i sensi non hanno alcun significato."
  },
  AvgDialog_123117_Content_122 = {
    Text = "Quando il ronzio finalmente cessa e i tuoi sensi ritornano, il mondo è silenzioso."
  },
  AvgDialog_123117_Content_123 = {
    Text = "La nebbia è svanita. Il Portale non c'è più. Restano solo l'altare macchiato di sangue, e Salvador, che ti osserva con occhi vuoti e preoccupati."
  },
  AvgDialog_123117_Content_124 = {
    Text = "Pallido Messaggero... abbiamo... abbiamo fallito?"
  },
  AvgDialog_123117_Content_125 = {Text = "..."},
  AvgDialog_123117_Content_126 = {
    Text = "Una risatina sommessa e familiare riecheggia alle tue spalle."
  },
  AvgDialog_123117_Content_127 = {
    Text = "%player%, Salvador. Perché quelle facce lunghe? La missione è finita."
  },
  AvgDialog_123117_Content_128 = {
    Text = "<Big:MOUCHETTE—!!>"
  },
  AvgDialog_123117_Content_129 = {
    Text = "Urli il suo nome in preda allo shock, e poi, nonostante il sangue e le rovine, cominci a ridere."
  },
  AvgDialog_123117_Content_13 = {
    Text = "Un'anima buona? Per favore, non usare quei— Aspetta. Lo senti?"
  },
  AvgDialog_123117_Content_130 = {
    Text = "Sono proprio qui, non c'è bisogno di gridare. La parte emozionante è finita. Ora si torna alle cose noiose."
  },
  AvgDialog_123117_Content_131 = {
    Text = "Ho davvero voglia di una tazza di Tè Kava alla Nocciola adesso. Oh, giusto... qui non ce l'avete. Allora cupcake."
  },
  AvgDialog_123117_Content_132 = {
    Text = "Mi racconterai tutto. Chi è Murphy, chi è Liz, chi è Doll... e tutte le avventure che hai vissuto."
  },
  AvgDialog_123117_Content_133 = {
    Text = "Visto che sono bloccata qui, tanto vale conoscere il vicinato."
  },
  AvgDialog_123117_Content_134 = {
    Text = "Non credo che %player% avrà obiezioni a riguardo."
  },
  AvgDialog_123117_Content_135 = {
    Text = "Salvador ti sorride, e ti ritrovi a sorriderle di rimando. La luce della luna squarcia le nuvole, avvolgendo tutti e tre in un tenue bagliore argenteo."
  },
  AvgDialog_123117_Content_136 = {
    Text = "Hai mille domande, ma le lasci riposare per ora."
  },
  AvgDialog_123117_Content_137 = {
    Text = "Forse è la luce della luna, o forse è il puro, vertiginoso sollievo di una fuga per un soffio. Sembra una rinascita."
  },
  AvgDialog_123117_Content_138 = {
    Text = "...I rapporti possono aspettare. Non capita spesso di poter dare il benvenuto a un viaggiatore verso una vita tutta nuova."
  },
  AvgDialog_123117_Content_139 = {
    Text = "Congratulazioni, Mouchette. Ora sei una Risvegliatrice. Questo non è più soltanto il nostro mondo: è anche il tuo."
  },
  AvgDialog_123117_Content_14 = {
    Text = "Qualcuno sta piangendo... e il suono si fa sempre più forte."
  },
  AvgDialog_123117_Content_140 = {
    Text = [[
Risvegliatrice Mouchette,
Benvenuta in questo mondo.]]
  },
  AvgDialog_123117_Content_15 = {
    Text = "Ti sforzi di ascoltare, ma solo il vento risponde. Salvador scuote dolcemente la testa; non sente altro che silenzio."
  },
  AvgDialog_123117_Content_16 = {
    Text = "All'improvviso, Mouchette lancia uno Strido. Si piega in due, le mani serrate sulle orecchie come per bloccare un urlo proveniente dal suo interno."
  },
  AvgDialog_123117_Content_17 = {
    Text = "<Shake:Aspettate... qualcuno, no, centinaia di loro... stanno urlando nella mia testa... ululando...>"
  },
  AvgDialog_123117_Content_18 = {
    Text = "Il panico divampa mentre ti precipiti al suo fianco. Il suo corpo è scosso da violenti Tremori, e le sue Pupille si dilatano in vuoti vacui e privi di messa a fuoco."
  },
  AvgDialog_123117_Content_19 = {
    Text = "Perdita di controllo? È l'Argento Liquefatto...?"
  },
  AvgDialog_123117_Content_2 = {
    Text = "Sotto un cielo soffocato d'Argento e Sangue, la nebbia infinita ribolle. Il Portale invisibile pulsa di luce, eppure la sua aura di invincibilità ha finalmente iniziato a incrinarsi."
  },
  AvgDialog_123117_Content_20 = {
    Text = "Argento Liquefatto!?"
  },
  AvgDialog_123117_Content_21 = {
    Text = "Scruti il sangue rappreso che le aderisce addosso. In mezzo al rosso cupo, l'argento pulsa, si muove come una specie parassita mentre filtra attraverso la pelle e penetra nelle vene."
  },
  AvgDialog_123117_Content_22 = {
    Text = "È giunta qui attraverso il loro sacrificio. Il rito l'ha reclamata — l'argento la sta trattando come parte dell'offerta stessa!"
  },
  AvgDialog_123117_Content_23 = {
    Text = "Dobbiamo agire! La contaminazione è troppo profonda. Se non la purghiamo adesso, la sua mente andrà in frantumi!"
  },
  AvgDialog_123117_Content_24 = {
    Text = "Tu e Salvador vi affrettate a rimuovere l'Argento da lei, ma la trasformazione ha già messo radici."
  },
  AvgDialog_123117_Content_25 = {
    Text = "<Red:<Shake:AAAAHHH—!>>"
  },
  AvgDialog_123117_Content_26 = {
    Text = "Un ultimo urlo le si strappa dalla gola mentre le pupille si frantumano in frammenti frastagliati. Il corpo si contorce, la carne si lacera e le ossa si spezzano mentre muta in un grottesco, innominabile orrore."
  },
  AvgDialog_123117_Content_27 = {
    Text = "Frammenti della sua carne schizzano su di te e su Salvador, colpendo il portale informe e provocando violente increspature sulla sua superficie oscura."
  },
  AvgDialog_123117_Content_28 = {
    Text = "Qualcosa non va. Il Portale... sta cambiando..."
  },
  AvgDialog_123117_Content_29 = {
    Text = "Prima che tu possa reagire, un contraccolpo psichico si abbatte attraverso il legame tra il Portale e la tua Chiave d'Argento, colpendo la tua mente con la forza di un maglio."
  },
  AvgDialog_123117_Content_3 = {
    Text = "Una luce Tenace divampa dalla Chiave d'Argento nella tua mano, il suo fulgore ricuce la Frattura Spazio-Temporale e purga le Distorsioni innaturali generate dal Rito."
  },
  AvgDialog_123117_Content_30 = {
    Text = "L'agonia ti acceca. Il sangue cola dal naso mentre le forze evaporano, lasciandoti accasciato su un ginocchio, ansimante."
  },
  AvgDialog_123117_Content_31 = {
    Text = "<Red:<Shake:Uccidere! Uccideteli tutti! Sterminateli!>>"
  },
  AvgDialog_123117_Content_32 = {
    Text = "<Red:<Shake:Hahaha! Guardate questo mondo bruciare!>>"
  },
  AvgDialog_123117_Content_33 = {
    Text = "L'ascia che un tempo ti apriva la strada è sollevata in alto, il filo della lama puntato al tuo cranio. Prosciugato dal legame spirituale, puoi solo guardare, paralizzato."
  },
  AvgDialog_123117_Content_34 = {
    Text = "<Shake:Mouchette...>"
  },
  AvgDialog_123117_Content_35 = {
    Text = "Cerchi di chiamarla per nome, ma la tua voce è un rantolo spezzato, incapace di raggiungere la mente sepolta sotto la mostruosità."
  },
  AvgDialog_123117_Content_37 = {
    Text = "L'ascia cala, avida di ossa. Nell'ultimo battito del cuore, Salvador si getta davanti a te, assorbendo l'impatto."
  },
  AvgDialog_123117_Content_38 = {
    Text = "Il sangue traccia un solco lungo la spalla di Salvador, eppure il suo volto resta una maschera di profonda misericordia e compassione sconfinata."
  },
  AvgDialog_123117_Content_39 = {
    Text = "Figlia mia, so che questo non è il tuo cuore. Sei semplicemente perduta nel buio."
  },
  AvgDialog_123117_Content_4 = {
    Text = "Dopo un lungo silenzio, l'Argento e il Sangue sospesi iniziano a piovere, macchiando la Terra e le tue spalle. La nebbia densa arretra visibilmente, ritirandosi nel vuoto. Le cose stanno cambiando."
  },
  AvgDialog_123117_Content_40 = {
    Text = "<Red:<Shake:UCCIDERE! DISTRUGGERE TUTTO!>>"
  },
  AvgDialog_123117_Content_41 = {
    Text = "La follia è assoluta. Mouchette non c'è più, sostituita da un impulso ferino di massacrare e cancellare."
  },
  AvgDialog_123117_Content_42 = {
    Text = "<Shake:Salvador, basta... se n'è andata...>"
  },
  AvgDialog_123117_Content_43 = {
    Text = "Guardi la creatura che un tempo era la tua amica, con la voce tremante. Solo pochi istanti fa, era piena di vita e arguzia."
  },
  AvgDialog_123117_Content_44 = {
    Text = "No, Pallido Messaggero. È soltanto smarrita."
  },
  AvgDialog_123117_Content_45 = {
    Text = "Salvador si alza, avanzando dritto nell'ombra dell'ascia sollevata."
  },
  AvgDialog_123117_Content_46 = {
    Text = "Il sangue dalla lama gli schizza sul volto, ma i suoi occhi non hanno il minimo tremolio di paura."
  },
  AvgDialog_123117_Content_47 = {
    Text = "Non ero presente quando la Setta ti ha evocata attraverso il sangue. Per questo, mi rammarico profondamente."
  },
  AvgDialog_123117_Content_48 = {
    Text = "Una singola goccia del sangue di Mouchette gli scivola lungo la guancia come una solitaria lacrima cremisi."
  },
  AvgDialog_123117_Content_49 = {
    Text = "Non la deterge. Invece, afferra con una mano il filo tagliente dell'ascia e solleva l'altra verso la fronte di lei."
  },
  AvgDialog_123117_Content_5 = {
    Text = "Le anomalie dimensionali stanno toccando il fondo, Mouchette. È il momento — la tua migliore occasione per tornare dall'altra parte."
  },
  AvgDialog_123117_Content_50 = {
    Text = "Ma ora sono qui. E ti redimerò."
  },
  AvgDialog_123117_Content_51 = {
    Text = "Il palmo insanguinato le tocca la fronte. Istantaneamente, una luce accecante e tenace erutta dal punto di contatto."
  },
  AvgDialog_123117_Content_52 = {
    Text = "È una Benedizione — un Sacerdote di questo mondo che fa scudo del personaggio a un Agnello smarrito di un altro."
  },
  AvgDialog_123117_Content_53 = {
    Text = "Mentre la luce si espande, il dolore lancinante nella tua mente svanisce. È come se un peso enorme fosse stato sollevato dalla tua anima e posto sulla sua."
  },
  AvgDialog_123117_Content_54 = {
    Text = "Salvador, fermati! Quel legame attraversa un'intera dimensione! Nessun essere umano può sopravvivere!"
  },
  AvgDialog_123117_Content_55 = {Text = "Lo so."},
  AvgDialog_123117_Content_56 = {
    Text = "La sua voce è un sussurro spezzato. Persino per lui, questa connessione psichica è un tormento che sfida ogni descrizione."
  },
  AvgDialog_123117_Content_57 = {
    Text = "In pochi secondi, lo sforzo lo spezza. Lacrime di sangue iniziano a tracciare solchi sul suo volto."
  },
  AvgDialog_123117_Content_58 = {
    Text = "Ma in quanto Emissario del Padre Supremo, darò tutto ciò che sono."
  },
  AvgDialog_123117_Content_59 = {
    Text = "Il sangue trasuda da sotto la benda che gli copre gli occhi, ma la luce dorata della Benedizione lo cattura, trasformando il rosso in oro fuso."
  },
  AvgDialog_123117_Content_6 = {
    Text = "Sto spingendo la Chiave d'Argento al suo limite. Manterrà Il Sentiero stabile finché non sarai al sicuro dall'altro lato."
  },
  AvgDialog_123117_Content_60 = {
    Text = "Quell'oro gocciola sulla mano di Mouchette, la luce si affievolisce rivelando il cremisi vivo sottostante mentre si fonde con il Sangue del Sacrificatore sulla sua pelle."
  },
  AvgDialog_123117_Content_61 = {
    Text = "Nel Suo nome, Mouchette, non ti lascerò cadere."
  },
  AvgDialog_123117_Content_62 = {
    Text = "Al suo comando, la luce sulla fronte di lei divampa con il calore di una stella morente, sommergendo il sangue, le ombre e il Portale stesso."
  },
  AvgDialog_123117_Content_63 = {
    Text = "È la radiosità di un uomo che riversa la propria forza vitale in un singolo istante di salvezza."
  },
  AvgDialog_123117_Content_64 = {
    Text = "<Shake:Ugh...>"
  },
  AvgDialog_123117_Content_65 = {
    Text = "In quel bagliore abbagliante come il sole, le pupille scisse di Mouchette tremolano con una scintilla di lucidità. La sua sanità morente si aggrappa alla vista della propria mano."
  },
  AvgDialog_123117_Content_66 = {
    Text = "Il sangue di Salvador non è più separato dal suo; sono diventati uno."
  },
  AvgDialog_123117_Content_67 = {
    Text = "Il sangue della vittima e dell'assassino, del peccatore e del santo, scorre insieme in un'unica, unificata marea."
  },
  AvgDialog_123117_Content_68 = {
    Text = "Io... ho detto..."
  },
  AvgDialog_123117_Content_69 = {
    Text = "<Shake:Lo odio... essere salvata dal... sacrificio degli altri...>"
  },
  AvgDialog_123117_Content_7 = {
    Text = "Vorrei potermi fare una doccia prima. Se torno con l'aspetto di una macelleria, farò venire un infarto all'Investigatore."
  },
  AvgDialog_123117_Content_70 = {
    Text = "Respingendo Salvador con le ultime forze, si volta verso di te, il volto una maschera di lacrime e agonia. Alza l'ascia un'ultima volta."
  },
  AvgDialog_123117_Content_71 = {
    Text = "Non permettergli... di farlo di nuovo. Persone come lui... sono loro che meritano di vivere."
  },
  AvgDialog_123117_Content_72 = {
    Text = "Il rito... il Portale mi ha intessuta in sé stesso. Ora sono parte di esso."
  },
  AvgDialog_123117_Content_73 = {
    Text = "<Shake:Uccidimi. Se muoio, svanisce. Saranno tutti... liberi.>"
  },
  AvgDialog_123117_Content_74 = {
    Text = "E... questo non è fuggire. È... trascinare il nemico con me."
  },
  AvgDialog_123117_Content_75 = {
    Text = "Con un ultimo, tremante sforzo, spinge il manico dell'ascia nelle tue mani. Resti lì, paralizzato dal suo peso."
  },
  AvgDialog_123117_Content_76 = {
    Text = "Onestamente... perché ho scelto questo? Non riesco nemmeno... a capire me stessa."
  },
  AvgDialog_123117_Content_77 = {
    Text = "Distruggere il mondo... doveva essere il mio stile..."
  },
  AvgDialog_123117_Content_78 = {
    Text = "Un singhiozzo le spezza la voce. Una singola lacrima scivola lungo la lama e si infrange contro il tuo palmo."
  },
  AvgDialog_123117_Content_79 = {
    Text = "La lucidità comincia a svanire. I suoi occhi si velano mentre la follia si fa strada di nuovo in superficie. Sta scivolando via un'altra volta."
  },
  AvgDialog_123117_Content_8 = {
    Text = "Prepariamo la tavola per te? Magari qualche cupcake per un vero tè pomeridiano?"
  },
  AvgDialog_123117_Content_80 = {
    Text = "Pallido Messaggero, ti prego... posso ancora salvarla..."
  },
  AvgDialog_123117_Content_81 = {
    Text = "Salvador lotta per rialzarsi, la sua voce una supplica disperata. Abbassi lo sguardo sulla scure, la mente in tempesta tra dolore e conflitto."
  },
  AvgDialog_123117_Content_82 = {
    Text = "Questa non è solo un'arma. È la sua fiducia. È il suo addio."
  },
  AvgDialog_123117_Content_83 = {
    Text = "<Shake:Dammi solo un momento... deve esserci un altro modo... deve esserci...>"
  },
  AvgDialog_123117_Content_84 = {
    Text = "All'improvviso, una soluzione disperata ti balena nella mente."
  },
  AvgDialog_123117_Content_85 = {
    Text = "Non ti fermi a pensare. Afferri la Chiave d'Argento e prendi la mano di Mouchette, tuffandoti a capofitto nelle torbide profondità della sua coscienza."
  },
  AvgDialog_123117_Content_86 = {
    Text = "Userai l'Argento nelle sue vene per forzare una trasformazione — trasformarla da umana in Risvegliatrice. È una scommessa disperata, suicida."
  },
  AvgDialog_123117_Content_87 = {
    Text = "Mentre ti immergi nella sua mente, vieni accecato da puntini di luce guizzanti e urlanti. Gemono in agonia, ma nessuno di essi è lei."
  },
  AvgDialog_123117_Content_88 = {
    Text = "Il suo mondo interiore è un vuoto. Non c'è alcuna Mouchette qui."
  },
  AvgDialog_123117_Content_89 = {
    Text = "Mouchette! Mouchette, dove sei?!"
  },
  AvgDialog_123117_Content_9 = {
    Text = "Perfetto. Onestamente, dopo aver visto che disastro è questo mondo noioso, quelle torte avranno il sapore di un Miracolo."
  },
  AvgDialog_123117_Content_90 = {
    Text = "Silenzio. Come essere umano, quell'ultima supplica di morte era il limite assoluto della sua volontà. Non le resta più nulla da dare."
  },
  AvgDialog_123117_Content_91 = {
    Text = "Ti sei arreso? Sei tu quello che scherzava sul fatto di avere giorni in cui voleva morire ogni settimana... parlavi sempre di farla finita..."
  },
  AvgDialog_123117_Content_92 = {
    Text = "Ma non così. Salvador, io, persino quell'Investigatore di cui parli — nessuno di noi vuole questo per te!"
  },
  AvgDialog_123117_Content_93 = {
    Text = "Ti prego, Mouchette... vieni fuori!"
  },
  AvgDialog_123117_Content_94 = {
    Text = "Non importa quanto forte gridi, solo gli echi della follia ti rispondono."
  },
  AvgDialog_123117_Content_95 = {
    Text = "È svanita nell'oscurità."
  },
  AvgDialog_123117_Content_96 = {
    Text = "...Ho un piano."
  },
  AvgDialog_123117_Content_97 = {
    Text = "Userò l'argento dentro di te per raffinarti... per fare di te una Risvegliatrice. Potrebbe ucciderti. Ma è tutto ciò che ho."
  },
  AvgDialog_123117_Content_98 = {
    Text = "<Small:Pensavo che la parte più difficile sarebbe stato il Risveglio in sé. Non credevo che avrei fallito perché non riuscivo nemmeno a trovare la tua anima...>"
  },
  AvgDialog_123117_Content_99 = {
    Text = "Cala il silenzio, pesante e soffocante. Come Custode, sai esattamente cosa accade a un cuore umano quando è sovrasaturato di Argento."
  },
  AvgDialog_123118_Content_1 = {
    Text = "Nella nebbia sconfinata, gli agghiaccianti lamenti di Agonia echeggiano senza sosta."
  },
  AvgDialog_123118_Content_10 = {
    Text = "La misericordia del Padre di Tutto non può salvare tutti, ma faremo tutto ciò che è in nostro potere per tendere una mano a ogni vittima che possiamo raggiungere."
  },
  AvgDialog_123118_Content_11 = {
    Text = "<Shake:Non... per favore, smettete di urlare...>"
  },
  AvgDialog_123118_Content_12 = {
    Text = "Sotto il peso del trauma psichico, il sangue inizia a sgorgare incontrollabile dal suo naso."
  },
  AvgDialog_123118_Content_13 = {
    Text = "<Shake:Ho detto, <Big:SMETTETE DI URLARE!>>"
  },
  AvgDialog_123118_Content_15 = {
    Text = "Mouchette grida di rabbia. Nell'agitazione, vibra la sua ascia con furia contro le nebbie umanoidi, solo per vederle scindersi e riformarsi all'istante."
  },
  AvgDialog_123118_Content_16 = {
    Text = "È inutile. Finché la nebbia persiste, questi mostri non svaniranno mai."
  },
  AvgDialog_123118_Content_17 = {
    Text = "Ecco perché prima volevate che vi \"aiutassimo\" facendo da esca, non è vero?"
  },
  AvgDialog_123118_Content_18 = {
    Text = "Stai cercando di regolare i conti adesso? Mettiti in fila — sei molto in fondo..."
  },
  AvgDialog_123118_Content_19 = {
    Text = "Mouchette si asciuga il sangue dal naso e riprende a menare l'ascia. L'ebbrezza della battaglia la infiamma; non riesce a fermarsi, e non vuole."
  },
  AvgDialog_123118_Content_2 = {
    Text = "@2 Io... salvare @2..."
  },
  AvgDialog_123118_Content_20 = {
    Text = "Ormai non c'è modo di ritirarsi. Tanto vale trattenerli qui!"
  },
  AvgDialog_123118_Content_21 = {
    Text = "Mouchette, calmati! Se continui così, tu..."
  },
  AvgDialog_123118_Content_22 = {
    Text = "Morirò? È così?"
  },
  AvgDialog_123118_Content_23 = {
    Text = "Ho già giorni ogni settimana in cui vorrei farla finita comunque. Ha, tanto vale..."
  },
  AvgDialog_123118_Content_24 = {
    Text = "Mouchette si interrompe. Una luce improvvisa divampa davanti a lei, seguita da un'ondata di calore che la avvolge, fluendo fin nel midollo."
  },
  AvgDialog_123118_Content_25 = {
    Text = "Salvador ha conferito la Benedizione su di lei."
  },
  AvgDialog_123118_Content_26 = {
    Text = "<Shake:Che cosa stai facendo?!>"
  },
  AvgDialog_123118_Content_27 = {
    Text = "Mouchette indietreggia istintivamente. La sensazione di calore è troppo estranea. Sembra sbagliata. Non dovrebbe appartenere a qualcuno come lei."
  },
  AvgDialog_123118_Content_28 = {
    Text = "Noi... noi siamo nemici. Perché..."
  },
  AvgDialog_123118_Content_29 = {
    Text = "Te l'ho detto. Non siamo nemici."
  },
  AvgDialog_123118_Content_3 = {
    Text = "Salvare @2... @2 me..."
  },
  AvgDialog_123118_Content_30 = {
    Text = "Non essere nemici non ci rende alleati!"
  },
  AvgDialog_123118_Content_31 = {
    Text = "Non sono così ingenua da considerare compagni delle persone che ho appena conosciuto..."
  },
  AvgDialog_123118_Content_32 = {
    Text = "Ma abbiamo già combattuto insieme contro quei cultisti, no? Chi si schiera fianco a fianco in battaglia è un alleato."
  },
  AvgDialog_123118_Content_33 = {
    Text = "E per la cronaca, non ho intenzione di ripetere qualche noiosa predica su \"amore e compassione.\" Preferisco vederla diversamente..."
  },
  AvgDialog_123118_Content_34 = {
    Text = "La considero una forma di saggezza per la sopravvivenza."
  },
  AvgDialog_123118_Content_35 = {
    Text = "La radiosità del Padre di Tutto si estende su tutta la terra. Persino nelle terre dell'annientamento, fratelli e sorelle devono sostenersi a vicenda."
  },
  AvgDialog_123118_Content_36 = {
    Text = "Mouchette serra le labbra in silenzio. I suoi occhi restano diffidenti e sospettosi, ma lentamente quell'ostilità si stempera in confusione... e in una tenue traccia di nostalgia."
  },
  AvgDialog_123118_Content_37 = {
    Text = "Le sue labbra si muovono come se stesse sussurrando qualcosa. Sebbene la sua voce sia troppo bassa, cogli di nuovo la parola \"Investigatore\"."
  },
  AvgDialog_123118_Content_38 = {
    Text = "Rimanderò tutta la faccenda del \"morire\" a un'altra volta. C'è ancora qualcuno che devo vedere, a casa."
  },
  AvgDialog_123118_Content_39 = {
    Text = "Intendi... quell'Investigatore di cui parlavi?"
  },
  AvgDialog_123118_Content_4 = {
    Text = "<Shake:Fatela smettere! Questa Nebbia... perché non smette di urlare?!>"
  },
  AvgDialog_123118_Content_40 = {
    Text = "Prima che Mouchette possa rispondere, un'onda d'urto invisibile investe l'area. I peli sulla nuca si drizzano mentre i mostri nella nebbia diventano ancora più frenetici."
  },
  AvgDialog_123118_Content_41 = {
    Text = "Questa sensazione... <Shake:<Big:Il rito è iniziato!>>"
  },
  AvgDialog_123118_Content_42 = {
    Text = "Il Rito? Ma abbiamo salvato i Sacrifici!"
  },
  AvgDialog_123118_Content_43 = {
    Text = "E Pallido Messaggero... i sacerdoti scomparsi non erano tra i prigionieri che abbiamo trovato."
  },
  AvgDialog_123118_Content_44 = {
    Text = "Le persone che abbiamo salvato erano solo riserve? O il momento del rito è prestabilito, costretto a procedere anche se i sacrifici sono insufficienti?"
  },
  AvgDialog_123118_Content_45 = {
    Text = "Non ho tempo per giocare a fare il Detective."
  },
  AvgDialog_123118_Content_46 = {
    Text = "Volete restare qui a chiacchierare, o venite con me? Decidetevi. In fretta."
  },
  AvgDialog_123118_Content_47 = {
    Text = "Mouchette vi lancia uno sguardo impaziente, poi volta le spalle e si addentra nel fitto della nebbia."
  },
  AvgDialog_123118_Content_48 = {Text = "Mouchette!"},
  AvgDialog_123118_Content_49 = {
    Text = "So cosa ti preoccupa. Non farò nessun trucco, questa volta."
  },
  AvgDialog_123118_Content_5 = {
    Text = "Perché questo non è il \"Disastro di Nebbia\" del vostro mondo. E questi mostri... non sono gli \"Antichi Mostri\" di cui parlavi."
  },
  AvgDialog_123118_Content_50 = {
    Text = "Mouchette risponde mentre brandisce la sua ascia per disperdere un umanoide di nebbia che tenta di tenderle un'imboscata."
  },
  AvgDialog_123118_Content_51 = {
    Text = "Il tuo ottimismo è stupido, e alcune di quelle idee sono così irrealisticamente idealiste che mi fanno venire il mal di testa, ma..."
  },
  AvgDialog_123118_Content_52 = {
    Text = "Ma ci sono sempre alcune persone che insistono nel tentare di salvare questo mondo noioso. <Small:Come te. Come il mio Investigatore...>"
  },
  AvgDialog_123118_Content_53 = {
    Text = "Forse voi due andreste davvero d'accordo?"
  },
  AvgDialog_123118_Content_54 = {
    Text = "Non stiamo andando un po' fuori tema...? Quelle persone ci stanno ancora aspettando..."
  },
  AvgDialog_123118_Content_55 = {
    Text = "Allora muoviti. Voglio che finisca il prima possibile. Torno a casa."
  },
  AvgDialog_123118_Content_56 = {
    Text = "Avanti, tenete il passo! Non restate indietro. Sono l'avanguardia più veloce dell'A.U.G.E!"
  },
  AvgDialog_123118_Content_57 = {
    Text = "La sagoma di Mouchette scatta in avanti nel cuore della nebbia. Tu e Salvador vi scambiate uno sguardo, poi la seguite."
  },
  AvgDialog_123118_Content_6 = {
    Text = "<Shake:Allora... cosa sono?>"
  },
  AvgDialog_123118_Content_7 = {
    Text = "Mouchette si copre istintivamente le orecchie, ma è inutile."
  },
  AvgDialog_123118_Content_8 = {
    Text = "Il dolore e la disperazione filtrano attraverso la nebbia nella carne e nelle ossa di chi ascolta, colpendo direttamente l'anima."
  },
  AvgDialog_123118_Content_9 = {
    Text = "Riesco a percepirli. Le loro anime... sono le persone che furono sacrificate nell'ultimo rito."
  },
  AvgDialog_123119_Content_1 = {
    Text = "Tra le Dimensioni"
  },
  AvgDialog_123119_Content_10 = {
    Text = "Mouchette scrolla le spalle, puntando il pollice verso la Porta Dimensionale che continua a vomitare Nebbia densa, erodendo il mondo."
  },
  AvgDialog_123119_Content_100 = {
    Text = "No, %player%, aspetta..."
  },
  AvgDialog_123119_Content_101 = {
    Text = "Allunga la mano per fermare il soccorso, la mente un groviglio frenetico di domande senza risposta."
  },
  AvgDialog_123119_Content_102 = {
    Text = "Ma il tempo è scaduto. Uno strattone violento alla sua stessa essenza la trascina via da questo reame colmo di luce ammaliante."
  },
  AvgDialog_123119_Content_103 = {
    Text = "La luce scintillante resta indietro — ferma, distante, irradiando un calore quieto e definitivo."
  },
  AvgDialog_123119_Content_104 = {
    Text = "Mostra le informazioni su @4 a @3 \"me\", e potrai @2 tornare a casa @1."
  },
  AvgDialog_123119_Content_105 = {
    Text = "@2, addio, Mouchette, @2... mio <Italic:altro me.>"
  },
  AvgDialog_123119_Content_106 = {
    Text = "Il ronzio psichico si contorce e si dissolve nel nulla, trascinando con sé i suoi sensi."
  },
  AvgDialog_123119_Content_107 = {
    Text = "Quando il mondo torna bruscamente a fuoco, sta fissando la stessa persona — quella che non riesce più a comprendere."
  },
  AvgDialog_123119_Content_108 = {
    Text = "Mouchette, lascia questo luogo. Salvador e io ci occuperemo del resto."
  },
  AvgDialog_123119_Content_109 = {
    Text = "La Corrosione del Varco si sta approfondendo. %player%, dobbiamo prepararci al peggio..."
  },
  AvgDialog_123119_Content_11 = {
    Text = "Quindi devo andare io. Solo io posso andare."
  },
  AvgDialog_123119_Content_110 = {Text = "..."},
  AvgDialog_123119_Content_111 = {
    Text = "Mouchette? Che stai a tergiversare? Devi andartene. Presto."
  },
  AvgDialog_123119_Content_112 = {
    Text = "Ti fissa, una tempesta di furia e di pietà appena scoperta che le ribolle nel petto, soffocandole le parole in gola."
  },
  AvgDialog_123119_Content_113 = {
    Text = "Infine, esala un respiro aspro e frastagliato e stringe i pugni in una riluttante resa."
  },
  AvgDialog_123119_Content_114 = {
    Text = "Avrei dovuto capirlo fin dall'inizio. Sei esattamente il tipo di \"Protagonista\" invadente che non capirò mai."
  },
  AvgDialog_123119_Content_115 = {
    Text = "Nemmeno tra cent'anni riuscirei a capire come funziona il tuo cervello. Perciò, rinuncio."
  },
  AvgDialog_123119_Content_116 = {Text = "Cosa?"},
  AvgDialog_123119_Content_117 = {
    Text = "Conosco la frequenza che ti serve. È l'altra @4@3..."
  },
  AvgDialog_123119_Content_118 = {
    Text = "Un dolore acuto distorce le sue parole in un groviglio di interferenze. Dopo diversi tentativi falliti di esprimere la verità che ha visto, Mouchette rinuncia alle parole."
  },
  AvgDialog_123119_Content_119 = {
    Text = "Ti prende la mano, gli occhi colmi di una Determinazione ormai assoluta."
  },
  AvgDialog_123119_Content_12 = {
    Text = "A modo vostro, si dice... ah, \"saggezza di sopravvivenza in un mondo crudele.\""
  },
  AvgDialog_123119_Content_120 = {
    Text = "Io resto. Ti aiuterò a risolvere questo caos."
  },
  AvgDialog_123119_Content_121 = {
    Text = "Io, Mouchette, avanguardia stellare di A.U.G.E., non concluderò questa Battaglia come una \"disertrice.\""
  },
  AvgDialog_123119_Content_13 = {
    Text = "Ascoltandola, tu e Salvador cadete in un breve silenzio, poi parlate simultaneamente—"
  },
  AvgDialog_123119_Content_14 = {
    Text = "Non sono d'accordo, bambina. Chi deve fare il Sacrificio sono io."
  },
  AvgDialog_123119_Content_15 = {
    Text = "Sono d'accordo. Ti prometto che ti riporterò indietro, o ti manderò a casa, a qualunque costo."
  },
  AvgDialog_123119_Content_16 = {
    Text = "Avendo espresso opinioni completamente opposte nello stesso istante, tu e Salvador vi fissate l'un l'altro."
  },
  AvgDialog_123119_Content_17 = {
    Text = "%player%, perché...?"
  },
  AvgDialog_123119_Content_18 = {
    Text = "Allora è deciso. Conto su di te per riportarmi a casa, %player%."
  },
  AvgDialog_123119_Content_19 = {
    Text = "Mouchette vi interrompe prima che tu o Salvador possiate reagire, dirigendosi dritta verso il Portale sconosciuto e minaccioso."
  },
  AvgDialog_123119_Content_2 = {
    Text = "Mouchette, stai dicendo che vuoi entrare in quella \"Porta\" sconosciuta...?"
  },
  AvgDialog_123119_Content_20 = {
    Text = "Stringi la Chiave d'Argento in una mano e afferri la manica di Salvador con l'altra, fissando lo sguardo su Mouchette—troppo concentrata persino per battere le palpebre."
  },
  AvgDialog_123119_Content_21 = {
    Text = "Salvador, ascolta. Forse... Mouchette è diversa."
  },
  AvgDialog_123119_Content_22 = {
    Text = "Questo è il portale verso un'altra dimensione, e lei proviene proprio da quella dimensione. È stata persino evocata qui dallo stesso rito."
  },
  AvgDialog_123119_Content_23 = {
    Text = "Ma... e se..."
  },
  AvgDialog_123119_Content_24 = {
    Text = "Se qualcosa dovesse andare storto, attiverò la Chiave d'Argento e trasferirò il legame su di me."
  },
  AvgDialog_123119_Content_25 = {
    Text = "Salvador ti guarda negli occhi—scorgendo una calma forzata sostenuta da una determinazione tremante—e poi osserva la Chiave d'Argento nella tua mano. Infine lascia sfuggire un lungo sospiro."
  },
  AvgDialog_123119_Content_26 = {
    Text = "Se quel momento dovesse arrivare, ti prego, lascia che condivida il fardello."
  },
  AvgDialog_123119_Content_27 = {
    Text = "Pallido Messaggero, non permetterò che tu cada prima di me."
  },
  AvgDialog_123119_Content_28 = {
    Text = "Rispondi con un sorriso di tacita comprensione."
  },
  AvgDialog_123119_Content_29 = {
    Text = "Nel frattempo, Mouchette alza la mano per toccare il Portale intangibile."
  },
  AvgDialog_123119_Content_3 = {
    Text = "Non solo tu, ma persino Salvador ammutolisce dallo stupore."
  },
  AvgDialog_123119_Content_30 = {
    Text = "<Shake:Questo è...>"
  },
  AvgDialog_123119_Content_31 = {
    Text = "Nell'istante in cui le dita di Mouchette sfiorano il Portale, esso erutta in una luce accecante e improvvisa."
  },
  AvgDialog_123119_Content_32 = {
    Text = "Allo stesso tempo, attivi la Chiave d'Argento."
  },
  AvgDialog_123119_Content_33 = {
    Text = "Lo splendore della Chiave risuona con il bagliore del Portale. In alto, l'argento e il sangue che oscurano il cielo iniziano a ribollire e a sollevarsi come guidati da una forza invisibile."
  },
  AvgDialog_123119_Content_34 = {
    Text = "Le due energie si fondono in un ronzio che corrode l'anima. È una risonanza che si mescola alla nebbia infinita, assalendo tutto ciò che la circonda e precipitando tutti i presenti in uno stato vertiginoso di dissociazione spirituale..."
  },
  AvgDialog_123119_Content_35 = {
    Text = "Il mondo@2 svanisce nel vuoto, come @2@1, come una nebbia densa, @3, qualcosa @2 si genera in questo vuoto @3."
  },
  AvgDialog_123119_Content_36 = {
    Text = "@1 non è che un @2 accidente del Sogno del Grande @4, eppure questo minuscolo @2 si contorce, si evolve e si trasforma in @4 stirpe."
  },
  AvgDialog_123119_Content_37 = {
    Text = "Dall'oscurità, una melodia di flauto caotica e distorta riecheggia, tormentando la volontà di Mouchette. Sebbene sia musica, ella intravede una verità terrificante celata tra le note."
  },
  AvgDialog_123119_Content_38 = {
    Text = "Umani, è così che @3 si definiscono. Rispetto all'infinito @1 universo, @2 è @4 minuscola ed effimera."
  },
  AvgDialog_123119_Content_39 = {
    Text = "@3 non ha lasciato @3 indietro; il sangue e l'argento di @1 scorrono attraverso le generazioni, le tracce di @4@2 @1 testimonianza."
  },
  AvgDialog_123119_Content_4 = {
    Text = "Esatto. Entrerò io e vi aiuterò a indagare su quella storia della \"frequenza\"."
  },
  AvgDialog_123119_Content_40 = {
    Text = "Lo stridio del flauto si fa più acuto, come una tortura psichica. Mouchette non riesce più a sopportarlo; spalanca gli occhi."
  },
  AvgDialog_123119_Content_41 = {
    Text = "Non c'è alcun flauto. Nessun musicista. Solo una surreale distesa di granelli di luce scintillanti che vorticano attorno a lei, mantenendo una rispettosa distanza. Poi, una voce—una che lei conosce—parla."
  },
  AvgDialog_123119_Content_42 = {
    Text = "Piacere di conoscerti, Mouchette, \"mia\" amica."
  },
  AvgDialog_123119_Content_43 = {
    Text = "Il puntino di luce vibra con un ronzio basso. Stranamente, lei lo comprende perfettamente. O forse... lei stessa è ora uno di quei puntini."
  },
  AvgDialog_123119_Content_44 = {
    Text = "Sono morta? Quindi è questa la sensazione della morte..."
  },
  AvgDialog_123119_Content_45 = {
    Text = "No, sei ancora viva. Ti ho semplicemente portata qui. Porti addosso il \"mio\" odore."
  },
  AvgDialog_123119_Content_46 = {
    Text = "Se non fossi intervenuto, il fallito attraversamento dimensionale ti avrebbe @4—perché sei già stata @3"
  },
  AvgDialog_123119_Content_47 = {
    Text = "Mouchette perde le parole finali; nel momento in cui le sillabe caotiche risuonano, la sua testa pulsa violentemente, quasi al punto di spaccarsi."
  },
  AvgDialog_123119_Content_48 = {
    Text = "<Shake:BASTA! BASTA! Di' qualcosa che possa capire... la mia testa sta per esplodere!>"
  },
  AvgDialog_123119_Content_49 = {
    Text = "Le sembra di udire un sospiro dalla luce—o forse è solo la sua immaginazione. All'improvviso, un fiume di informazioni si riversa nella sua coscienza, catturando tutta la sua attenzione."
  },
  AvgDialog_123119_Content_5 = {
    Text = "Bambina, non comprendi i pericoli che comporta. Il Trauma del Reame dello Spirito può influenzare il mondo reale. Tu—"
  },
  AvgDialog_123119_Content_50 = {
    Text = "Cos'è questo?"
  },
  AvgDialog_123119_Content_51 = {
    Text = "Ciò di cui hai bisogno adesso. Mostralo al \"me\" in questo mondo, %player% capirà."
  },
  AvgDialog_123119_Content_52 = {
    Text = "Non capisco tutto questo parlare di \"io\" e \"tu\"—"
  },
  AvgDialog_123119_Content_53 = {
    Text = "Aspetta, tu sei... %player%?"
  },
  AvgDialog_123119_Content_54 = {
    Text = "È impossibile! Ti ho appena visto un istante fa—in salute, pieno di vita, con l'aria di chi avrebbe vissuto altri cent'anni!"
  },
  AvgDialog_123119_Content_55 = {
    Text = "Il granello di luce emette un ronzio simile a una risatina sommessa. Mouchette non è sicura che sia una \"risata,\" poiché non porta alcuna gioia. Non porta alcuna emozione."
  },
  AvgDialog_123119_Content_56 = {
    Text = "Puoi intenderlo come il \"me\" in un'altra Dimensione. E io, il vero me—"
  },
  AvgDialog_123119_Content_57 = {
    Text = "Mentre la luce parla, un'ondata di informazioni si riversa nella mente di Mouchette. I Frammenti si fratturano e si fondono, tessendo immagini instabili e tremolanti."
  },
  AvgDialog_123119_Content_58 = {
    Text = "All'inizio, le visioni sono astratte e frastagliate, un confuso miscuglio di interferenze e ombre..."
  },
  AvgDialog_123119_Content_59 = {
    Text = "Ma presto, il caos si affina in un'unica, familiare sagoma."
  },
  AvgDialog_123119_Content_6 = {
    Text = "Sono l'unica adatta a questo compito. Forse non sarò la più brillante, ma non sono stupida."
  },
  AvgDialog_123119_Content_60 = {
    Text = "Lo osserva {Male=risvegliarsi,Female=risvegliarsi} nel cuore di un cratere, gli occhi spalancati e vacui tra la polvere che si posa."
  },
  AvgDialog_123119_Content_61 = {
    Text = "Anni dopo, la gente l'avrebbe chiamata l'\"Esplosione di Yakutsk.\""
  },
  AvgDialog_123119_Content_62 = {
    Text = "Lo segue mentre %player% varca le sale di Mythag, le dita che si stringono attorno alla Chiave d'Argento. Lo vede %player% diventare un \"Custode,\" guidando un gruppo di \"Risvegliati\" nelle fauci di un mondo da Incubo."
  },
  AvgDialog_123119_Content_63 = {
    Text = "È uno specchio della sua stessa vita—l'Investigatore, il team A.U.G.E., e la missione che non ha mai fine."
  },
  AvgDialog_123119_Content_64 = {Text = "..."},
  AvgDialog_123119_Content_65 = {
    Text = "Le Memorie del suo stesso mondo strappano un sospiro nostalgico dalle labbra di Mouchette, ma la visione della vita di %player% prosegue inesorabile."
  },
  AvgDialog_123119_Content_66 = {
    Text = "Cammina al fianco di %player% attraverso il gelo tagliente di una città morta. Si ritrova in un sanatorio soffocato dai segreti, faccia a faccia con i Segugi Dimensionali, testimone dell'Ostinata immortalità dei Legami Familiari."
  },
  AvgDialog_123119_Content_67 = {
    Text = "Vaga tra la poesia e i petali di Cité, ascoltando i sospiri sepolti in una fiamma, e l'appassire di una rosa."
  },
  AvgDialog_123119_Content_68 = {
    Text = "Poi giungono il sale e la putredine di Sona-Nyl, la nave fantasma. La Follia mascherata da fede, dèi famelici, e il sapore metallico del sacrificio. Attraverso gli occhi di %player%, assapora la Distorsione pura, concentrata, di un mondo impazzito."
  },
  AvgDialog_123119_Content_69 = {
    Text = "Per quanto profonda fosse l'Oscurità, %player% e i Risvegliati non si arresero mai."
  },
  AvgDialog_123119_Content_7 = {
    Text = "Mouchette interrompe Salvador, guardandovi entrambi con una gravità insolita per lei."
  },
  AvgDialog_123119_Content_70 = {
    Text = "Così come la Nebbia, i Griske e gli Artefatti non poterono mai spegnere davvero il fuoco in A.U.G.E."
  },
  AvgDialog_123119_Content_71 = {
    Text = "Ecco, così va meglio!"
  },
  AvgDialog_123119_Content_72 = {
    Text = "Chissà come se la cavano quei piccoli nella Nebbia?"
  },
  AvgDialog_123119_Content_73 = {
    Text = "Sigh... Adesso berrei davvero volentieri una bella tazza calda di Tè Kava alla Nocciola."
  },
  AvgDialog_123119_Content_74 = {
    Text = "Mouchette sorride. Osserva %player% e i Risvegliatori, certa che combatteranno fino alla fine dei tempi."
  },
  AvgDialog_123119_Content_75 = {
    Text = "È l'unico finale che abbia senso; lei non aveva mai avuto intenzione di lasciare A.U.G.E., quindi perché queste persone dovrebbero mai abbandonare il loro Custode?"
  },
  AvgDialog_123119_Content_76 = {
    Text = "Avrebbero lottato e sanguinato finché il mondo non fosse stato riparato, o finché non fossero diventati parte dello scenario. Proprio come gli eroi nei libri di fiabe."
  },
  AvgDialog_123119_Content_77 = {
    Text = "Ma questa realtà è molto più tagliente e fredda di quanto avesse immaginato."
  },
  AvgDialog_123119_Content_78 = {
    Text = "<Shake:Come è potuto succedere!!>"
  },
  AvgDialog_123119_Content_79 = {
    Text = "Quindi tu in realtà sei...!?"
  },
  AvgDialog_123119_Content_8 = {
    Text = "Salvador, il tuo Potere è l'unica cosa che ci tiene al sicuro in questa Nebbia. E %player%... è chiaro che sia tu che la tua Chiave d'Argento siete fondamentali in tutto questo."
  },
  AvgDialog_123119_Content_80 = {
    Text = "Idiota, non avrei dovuto aspettarmi che rinunciassi a fare il noioso salvatore!"
  },
  AvgDialog_123119_Content_81 = {
    Text = "Sacrificarti così... è..."
  },
  AvgDialog_123119_Content_82 = {
    Text = "Le parole le muoiono in gola. La rabbia e la frustrazione sono ormai pesi vuoti."
  },
  AvgDialog_123119_Content_83 = {
    Text = "%player% è un suo amico, ma Mouchette è solo una viaggiatrice di passaggio in questa linea temporale."
  },
  AvgDialog_123119_Content_84 = {
    Text = "La distanza tra loro non è più una semplice \"dimensione\". È il peso di due mondi completamente diversi."
  },
  AvgDialog_123119_Content_85 = {
    Text = "In realtà, il mio sogno è sedermi accanto a un fuoco accogliente con le persone che amo, sprecando le nostre inutili vite."
  },
  AvgDialog_123119_Content_86 = {
    Text = "La neve si poserà fuori dalla finestra, anno dopo anno, finché non ce ne andremo in pace.\n\nSulla mia lapide si leggerebbe: %player% è stato un longevo, felice sciocco."
  },
  AvgDialog_123119_Content_87 = {
    Text = "E ancora adesso... quel sogno non è cambiato."
  },
  AvgDialog_123119_Content_88 = {
    Text = "Allora vai a viverlo! Chi se ne importa se il mondo finisce? Che importa se questo noioso mondo crolla!?"
  },
  AvgDialog_123119_Content_89 = {
    Text = "È comunque meglio che restare intrappolati qui per sempre — soli, con rimpianti che non svaniscono mai!"
  },
  AvgDialog_123119_Content_9 = {
    Text = "Se dovesse succedervi qualcosa, nessun altro potrebbe rimediare a questo disastro."
  },
  AvgDialog_123119_Content_90 = {
    Text = "La figura composta da puntini di luce ridacchia di nuovo. Questa volta, il suono è filtrato dall'amarezza che sale nel cuore di Mouchette."
  },
  AvgDialog_123119_Content_91 = {
    Text = "Voglio realizzare quel sogno anch'io, davvero."
  },
  AvgDialog_123119_Content_92 = {
    Text = "Ma... in questo mondo crudele, facciamo sempre delle \"scelte\", scelte che forse nemmeno noi stessi comprendiamo."
  },
  AvgDialog_123119_Content_93 = {
    Text = "Forse non è poi così difficile da capire. Non ho mai assaggiato il Tè Kava alla Nocciola, ma anch'io ho cose che amo."
  },
  AvgDialog_123119_Content_94 = {
    Text = "Le torte di Murphy, le danze di Liz... persino i compiti extra assegnati da Doll ora sembrano interessanti..."
  },
  AvgDialog_123119_Content_95 = {
    Text = "Basta così. Smetti di parlare. Non sei altro che un caso disperato..."
  },
  AvgDialog_123119_Content_96 = {
    Text = "Mouchette! Mouchette!"
  },
  AvgDialog_123119_Content_97 = {
    Text = "All'improvviso, una voce perfora il silenzio della sua mente. La riconosce all'istante."
  },
  AvgDialog_123119_Content_98 = {
    Text = "Avendo assistito al peso della lotta di \"%player%\", sa che quella voce è ormai incisa nella sua anima."
  },
  AvgDialog_123119_Content_99 = {
    Text = "Resisti! Salvador e io ti tireremo fuori! L'ho promesso!"
  },
  AvgDialog_123120_Content_1 = {
    Text = "L'Auto-Oblazione"
  },
  AvgDialog_123120_Content_10 = {
    Text = "Padre Salvador...?"
  },
  AvgDialog_123120_Content_100 = {
    Text = "Non so quanto si propagherà questa cosa. Se è davvero come nel mio mondo..."
  },
  AvgDialog_123120_Content_101 = {
    Text = "Mouchette non finisce la frase, ma comprendi ciò che intende dire."
  },
  AvgDialog_123120_Content_102 = {
    Text = "Il Disastro di Nebbia è apparentemente una catastrofe capace di consumare un mondo intero."
  },
  AvgDialog_123120_Content_103 = {
    Text = "Dobbiamo porre fine a questo rito a ogni costo... <Shake:Salvador!>"
  },
  AvgDialog_123120_Content_104 = {
    Text = "Sono qui. Garantirò la vostra sicurezza... e porterò a queste anime perdute la vera salvezza..."
  },
  AvgDialog_123120_Content_105 = {
    Text = "Una luce calda e gentile si irradia da Salvador, propagandosi verso di te e Mouchette, proteggendovi dalla corruzione della nebbia."
  },
  AvgDialog_123120_Content_106 = {
    Text = "Mouchette, per chiudere questa frattura spaziale, devo misurare e determinare la frequenza vibrazionale della dimensione spirituale. Conto su di te per il combattimento."
  },
  AvgDialog_123120_Content_107 = {
    Text = "Combattere? Nessun problema. Con me qui, non perderai nemmeno un capello!"
  },
  AvgDialog_123120_Content_108 = {
    Text = "Mi sono trattenuta fin troppo a lungo, è ora di scatenarsi—"
  },
  AvgDialog_123120_Content_109 = {
    Text = "Ecco il preferito di tutti! <Big:SHINING☆TORNADO—!!>"
  },
  AvgDialog_123120_Content_11 = {
    Text = "Salvador inspira profondamente in silenzio, poi esala pesantemente."
  },
  AvgDialog_123120_Content_111 = {
    Text = "L'ascia vola via, frantumando una fila di nebbie umanoidi e aprendo un breve sentiero sicuro per avvicinarti al misterioso portale da cui sgorga la nebbia."
  },
  AvgDialog_123120_Content_112 = {
    Text = "Lavori freneticamente con gli strumenti di misurazione, cercando di catturare le frequenze delle diverse dimensioni."
  },
  AvgDialog_123120_Content_113 = {
    Text = [[
Passa un minuto.

Passano due minuti.]]
  },
  AvgDialog_123120_Content_114 = {
    Text = "Poi tre minuti, cinque, dieci..."
  },
  AvgDialog_123120_Content_115 = {
    Text = "Il sudore ti cola dalla fronte. Non hai mai sentito il tempo scorrere così lentamente."
  },
  AvgDialog_123120_Content_116 = {
    Text = "Quanto manca ancora? Questi mostri sembrano diventare sempre più forti. Ora servono diversi colpi anche solo per frantumarne uno..."
  },
  AvgDialog_123120_Content_117 = {
    Text = "È un segno che l'altra dimensione sta tentando di invadere e divorare il nostro mondo, non è vero, Pallido Messaggero?"
  },
  AvgDialog_123120_Content_118 = {
    Text = "Un'altra goccia di sudore cade. Nella tua estrema tensione mentale, dimentichi persino di annuire."
  },
  AvgDialog_123120_Content_119 = {
    Text = "La frequenza... continua a variare..."
  },
  AvgDialog_123120_Content_12 = {
    Text = "Non c'è bisogno di cercarlo. Padre White... è già qui."
  },
  AvgDialog_123120_Content_120 = {
    Text = "Potrebbe essere la nebbia stessa, o un'interferenza delle anime intrappolate al suo interno... Ho bisogno di più tempo per filtrarla."
  },
  AvgDialog_123120_Content_121 = {
    Text = "Alzi lo sguardo al cielo. Non ci sono più \"stelle\" da vedere."
  },
  AvgDialog_123120_Content_122 = {
    Text = "Il mondo intero sembra consistere soltanto nella fitta nebbia e nel portale dimensionale che la erutta senza sosta."
  },
  AvgDialog_123120_Content_123 = {
    Text = "...Hai ragione."
  },
  AvgDialog_123120_Content_124 = {
    Text = "Riponi gli strumenti e stringi la Chiave d'Argento."
  },
  AvgDialog_123120_Content_125 = {
    Text = "Sembra che dovremo rischiare il tutto per tutto..."
  },
  AvgDialog_123120_Content_126 = {
    Text = "Pallido Messaggero, hai intenzione di connettere...?"
  },
  AvgDialog_123120_Content_127 = {
    Text = "Salvador aggrotta le sopracciglia, guardandoti con disapprovazione. Tu resti in silenzio."
  },
  AvgDialog_123120_Content_128 = {
    Text = "Ehi, qui c'è un'\"Ultraterrena\", ricordate? Parlate in una lingua che possa davvero capire!"
  },
  AvgDialog_123120_Content_129 = {
    Text = "%player% intende... collegarsi direttamente a quella \"Porta\" sconosciuta per agganciare la frequenza dimensionale."
  },
  AvgDialog_123120_Content_13 = {
    Text = "Colei che si erge su quell'altare... è White."
  },
  AvgDialog_123120_Content_130 = {
    Text = "Cosa? Quella cosa è super sospetta! Chi sa cosa potrebbe farti? Non essere stupida."
  },
  AvgDialog_123120_Content_131 = {
    Text = "Stringi forte la Chiave d'Argento e avanzi verso il portale informe, l'espressione solenne. In questo istante, le azioni parlano più forte delle parole."
  },
  AvgDialog_123120_Content_132 = {
    Text = "Davvero non vi capisco... pensare che questo mondo noioso meriti ancora di essere salvato..."
  },
  AvgDialog_123120_Content_133 = {
    Text = "Inaspettatamente, Mouchette allunga la mano per fermarti. Ti guarda con un'espressione complessa—come se stesse guardando te, e al tempo stesso qualcun altro attraverso di te."
  },
  AvgDialog_123120_Content_134 = {
    Text = "Infine, il conflitto interiore si dissolve in un sorriso. Cerca di mantenere la voce leggera."
  },
  AvgDialog_123120_Content_135 = {
    Text = "Lascia stare. Dato che sono l'avanguardia stellare di A.U.G.E., è solo naturale che sia io a stare in prima linea—"
  },
  AvgDialog_123120_Content_136 = {
    Text = "Quindi, lascia andare me."
  },
  AvgDialog_123120_Content_137 = {
    Text = "Mouchette ti guarda, la sua espressione seria e irremovibile."
  },
  AvgDialog_123120_Content_138 = {
    Text = "Per la prima volta da quando l'hai incontrata in quella gabbia, appare davvero, profondamente sincera."
  },
  AvgDialog_123120_Content_14 = {Text = "Cosa?!"},
  AvgDialog_123120_Content_15 = {
    Text = "Sotto shock, ti volti a fissare White. L'uomo che un tempo era un sacerdote della Cattedrale della Vita — ora leader di una setta — prosegue il suo appassionato discorso."
  },
  AvgDialog_123120_Content_16 = {
    Text = "In questo momento, compiamo la nostra scelta al prezzo di argento e sangue, e non ce ne pentiremo mai."
  },
  AvgDialog_123120_Content_17 = {
    Text = "Per raggiungere il Sereno Reame Libero dalla Dissoluzione. Per redimere noi stessi in questo mondo in fiamme—"
  },
  AvgDialog_123120_Content_18 = {
    Text = "Per raggiungere il Sereno Reame Libero dalla Dissoluzione. Per redimere noi stessi in questo mondo in fiamme—"
  },
  AvgDialog_123120_Content_19 = {
    Text = "Una dozzina di cultisti pronunciano il giuramento all'unisono."
  },
  AvgDialog_123120_Content_2 = {
    Text = "<Shake:Questo mondo brucia. Questo mondo crolla. Questo mondo è destinato alla distruzione.>"
  },
  AvgDialog_123120_Content_20 = {
    Text = "Sollevano simultaneamente i loro pugnali placcati d'argento—"
  },
  AvgDialog_123120_Content_21 = {Text = "Basta!"},
  AvgDialog_123120_Content_22 = {
    Text = "Mentre ancora gridi, le lame d'argento affondano nei cuori dei sacrifici, penetrando in profondità e torcendosi con crudele violenza."
  },
  AvgDialog_123120_Content_23 = {
    Text = "Un cremisi accecante sprizza dai loro petti, tingendo di rosso l'altare."
  },
  AvgDialog_123120_Content_24 = {
    Text = "In mezzo al sangue, emergi dalle ombre per affrontare White — l'origine di questa intera tragedia."
  },
  AvgDialog_123120_Content_25 = {
    Text = "Altri sciocchi ignoranti vengono a interferire con il rito del Padre Supremo?"
  },
  AvgDialog_123120_Content_26 = {
    Text = "Ha! Siete rimasti indifferenti quando il Cataclisma ha colpito, eppure ora che sto guidando i miei fratelli e le mie sorelle alla salvezza, venite a fermarmi—"
  },
  AvgDialog_123120_Content_27 = {
    Text = "Il leader della Setta dell'Alba Astrale sogghigna guardando verso di te, ma poi le sue pupille si dilatano improvvisamente e si congela sul posto."
  },
  AvgDialog_123120_Content_28 = {
    Text = "<Shake:V-Vescovo Salvador?!>"
  },
  AvgDialog_123120_Content_29 = {
    Text = "Il volto di Salvador è avvolto nella penombra. Noti che sotto le sue pesanti vesti, la sua alta e snella figura trema leggermente."
  },
  AvgDialog_123120_Content_3 = {
    Text = "<Shake:L'unico sentiero verso la salvezza è raggiungere il <Yellow:Reame Sereno Libero dalla Dissoluzione>. Si trova sopra di noi, fra le stelle del cosmo.>"
  },
  AvgDialog_123120_Content_30 = {
    Text = "Bianco... figlio mio smarrito..."
  },
  AvgDialog_123120_Content_31 = {
    Text = "Oh, capisco. Questo \"figlio perduto\" che stai cercando di salvare è in realtà un leader di una setta! Haha!"
  },
  AvgDialog_123120_Content_32 = {Text = "Mouchette!"},
  AvgDialog_123120_Content_33 = {
    Text = "Va bene, va bene, starò zitto. Ma anche se non lo dico io, i fatti non cambieranno, giusto?"
  },
  AvgDialog_123120_Content_34 = {
    Text = "La scena piomba nel silenzio. L'unico suono è il lento gocciolare del sangue sull'altare, che si impregna nel pavimento di pietra."
  },
  AvgDialog_123120_Content_35 = {
    Text = "John, James, Anderson... erano tutti tuoi colleghi."
  },
  AvgDialog_123120_Content_36 = {
    Text = "Come ex sacerdote della Cattedrale della Vita, dovresti capire perché sono venuti a Howick."
  },
  AvgDialog_123120_Content_37 = {
    Text = "...Certo che capisco."
  },
  AvgDialog_123120_Content_38 = {
    Text = "Perché un tempo ero proprio come loro! Sono venuto qui colmo di nobili ideali!"
  },
  AvgDialog_123120_Content_39 = {
    Text = "La voce di White si fa improvvisamente frenetica. Guarda Salvador con un fervore disperato, come un bambino in cerca di approvazione."
  },
  AvgDialog_123120_Content_4 = {
    Text = "<Shake:<Big:Trovatelo! Convertitevi ad esso! Gettatevi in esso! Solo allora le nostre vite accoglieranno l'alba eterna—>>"
  },
  AvgDialog_123120_Content_40 = {
    Text = "E io ho mantenuto la mia promessa! Ho trovato l'unica via per salvare i nostri fratelli e le nostre sorelle!"
  },
  AvgDialog_123120_Content_41 = {Text = "..."},
  AvgDialog_123120_Content_42 = {
    Text = "La morte non è l'insegnamento del Padre Supremo, White. Ti sei allontanato dal Sentiero."
  },
  AvgDialog_123120_Content_43 = {
    Text = "<Shake:No! Sto ancora seguendo la Guida del Padre Supremo!>"
  },
  AvgDialog_123120_Content_44 = {
    Text = "Il Padre Supremo dice: <Italic:Siamo tutti Suoi figli, partecipi della Sua misericordia.> Dice: <Italic:Amatevi gli uni gli altri, così come amate voi stessi.>"
  },
  AvgDialog_123120_Content_45 = {
    Text = "Il Padre Supremo comanda: <Italic:I nobili tra voi saranno i miei emissari; agite in mia vece, affinché la sofferenza sia sradicata da questa terra.>"
  },
  AvgDialog_123120_Content_46 = {
    Text = "...È corretto. Quelle sono davvero le parole del Padre Supremo."
  },
  AvgDialog_123120_Content_47 = {
    Text = "E io l'ho fatto! Salverò i miei fratelli e le mie sorelle ed eliminerò la sofferenza che è stata loro inflitta!"
  },
  AvgDialog_123120_Content_48 = {
    Text = "Li condurrò lontano da questa terra di miseria! Li guiderò verso l'alba che risplende Tra le Stelle, verso il—"
  },
  AvgDialog_123120_Content_49 = {
    Text = "<Yellow:<Big:Sereno Reame Libero dalla Dissoluzione>>."
  },
  AvgDialog_123120_Content_5 = {
    Text = "All'interno della caverna colma di simboli blasfemi, il capo della Setta dell'Alba Astrale pronuncia un discorso fervente. Quando la sua voce tace, i prigionieri vengono trascinati al centro dell'altare."
  },
  AvgDialog_123120_Content_50 = {
    Text = "Per raggiungere il Sereno Reame Libero dalla Dissoluzione. Per redimere noi stessi in questo mondo in fiamme—"
  },
  AvgDialog_123120_Content_51 = {
    Text = "Per raggiungere il Sereno Reame Libero dalla Dissoluzione. Per redimere noi stessi in questo mondo in fiamme—"
  },
  AvgDialog_123120_Content_52 = {
    Text = "Proprio in quel momento, un freddo ghigno trafigge la pia Cantilena come un ago."
  },
  AvgDialog_123120_Content_53 = {
    Text = "Il Sereno Reame Libero dalla Dissoluzione? Stai parlando del mondo oltre quel portale?"
  },
  AvgDialog_123120_Content_54 = {
    Text = "Che scherzo. Il mio mondo non è neanche lontanamente così bello."
  },
  AvgDialog_123120_Content_55 = {
    Text = "Disastri di Nebbia, Mostri Ancestrali, la Legione Griske e ogni sorta di orrori mutati. Incontrarne anche solo uno è sufficiente a rovinarti la vita."
  },
  AvgDialog_123120_Content_56 = {
    Text = "Quindi smettila di blaterare di \"salvezza\". Non stai salvando nessuno — stai solo sacrificando gli altri per salvare la vostra pelle."
  },
  AvgDialog_123120_Content_57 = {
    Text = "<Shake:Non è vero! Perché—>"
  },
  AvgDialog_123120_Content_58 = {
    Text = "White avanza verso Mouchette, la mano tremante per l'emozione mentre solleva il Pugnale d'Argento."
  },
  AvgDialog_123120_Content_59 = {
    Text = "Istintivamente ti muovi per fare scudo a Mouchette, ma il Colpo che ti aspettavi non arriva mai."
  },
  AvgDialog_123120_Content_6 = {
    Text = "Ti nascondi tra le ombre lì vicino, verificando con cautela il numero dei sacrifici."
  },
  AvgDialog_123120_Content_60 = {
    Text = "White aveva intenzione di pugnalare se stesso fin dall'inizio."
  },
  AvgDialog_123120_Content_61 = {
    Text = "Il sangue sprizza dal cuore di White, scorrendo e fondendosi con il sangue dei sacrifici sull'Altare Cremisi."
  },
  AvgDialog_123120_Content_62 = {
    Text = "<Shake:Ora... abbiamo abbastanza Argento e sangue...>"
  },
  AvgDialog_123120_Content_63 = {
    Text = "Mentre White sussurra queste parole, un'onda d'urto invisibile erutta dall'altare."
  },
  AvgDialog_123120_Content_64 = {
    Text = "Il sangue che si raccoglie sulla superficie di pietra inizia a contorcersi e a sollevarsi nell'aria. I corpi dei sacrificati cominciano a fluttuare insieme ad esso."
  },
  AvgDialog_123120_Content_65 = {
    Text = "<Shake:AAAAHHH—Vescovo Salvador...>"
  },
  AvgDialog_123120_Content_66 = {
    Text = "<Shake:Vedete...? Non ho tradito... la mia promessa... al Padre Supremo...>"
  },
  AvgDialog_123120_Content_67 = {
    Text = "White urla in agonia, il suo corpo morente scosso da convulsioni. L'Argento e il sangue dentro di lui vengono estratti da una Forza Invisibile, dipingendo motivi grotteschi nell'aria."
  },
  AvgDialog_123120_Content_68 = {
    Text = "<Shake:Vescovo, so di aver peccato... Porterò la colpa... per me stesso e per loro.>"
  },
  AvgDialog_123120_Content_69 = {
    Text = "<Shake:Ma non me ne pentirò mai... perché ho salvato i miei fratelli e le mie sorelle... da questa terra di sofferenza...>"
  },
  AvgDialog_123120_Content_7 = {
    Text = "John, James, Anderson... sono tutti qui."
  },
  AvgDialog_123120_Content_70 = {
    Text = "Lo sguardo di White resta fisso su Salvador. E Salvador — il Vescovo che un tempo aveva dedicato anima e corpo a guidarlo — traccia lentamente nell'aria il Segno Sacro del Padre Supremo."
  },
  AvgDialog_123120_Content_71 = {
    Text = "La mano di Salvador trema mentre reprime l'impulso di concedere una \"Benedizione\". Il suo figlio perduto ha fatto la sua scelta finale."
  },
  AvgDialog_123120_Content_72 = {
    Text = "Non condivido ancora i tuoi metodi, White, ma hai davvero messo in pratica gli insegnamenti del Padre Supremo a modo tuo. Quindi..."
  },
  AvgDialog_123120_Content_73 = {
    Text = "Che il Padre Supremo ti perdoni. Che tu possa... tornare al Suo Abbraccio. Fuggire dalla miseria e trovare la tua Redenzione..."
  },
  AvgDialog_123120_Content_74 = {
    Text = "Salvador sospira, offrendo un'ultima preghiera."
  },
  AvgDialog_123120_Content_75 = {
    Text = "Ma White non può più sentirlo. La sua espressione è congelata tra un sorriso beato e un'agonia estrema mentre il suo cuore smette di battere."
  },
  AvgDialog_123120_Content_76 = {
    Text = "Poi, l'Argento e il sangue sospesi nell'aria si agitano con violenza, come innumerevoli \"stelle\" in ebollizione che illuminano l'Oscurità."
  },
  AvgDialog_123120_Content_77 = {
    Text = "In questa luce accecante e grandiosa, innumerevoli frammenti di radiosità sconosciuta si coalizzano, formando un portale informe che conduce verso una destinazione ignota."
  },
  AvgDialog_123120_Content_78 = {
    Text = "Questa è la \"Porta\" di cui parlavano?"
  },
  AvgDialog_123120_Content_79 = {
    Text = "Se la attraverso, posso tornare nel mio mondo?"
  },
  AvgDialog_123120_Content_8 = {
    Text = "Il che significa che ci manca solo Padre White...?"
  },
  AvgDialog_123120_Content_80 = {
    Text = "È difficile dirlo. In teoria, possiamo collegarci alla stessa Dimensione simulando la medesima frequenza vibrazionale, ma in pratica gli incidenti accadono facilmente."
  },
  AvgDialog_123120_Content_81 = {
    Text = "Specialmente con un Rito sacrificale come questo. Ci sono troppe variabili; le cose possono andare storte in un istante—"
  },
  AvgDialog_123120_Content_82 = {
    Text = "Aspetta, non avvicinarti!"
  },
  AvgDialog_123120_Content_83 = {
    Text = "Gridi per fermare i cultisti che marciano all'unisono verso il portale informe. Sembrano sordi al tuo avvertimento, e proseguono con un passo inquietante e costante."
  },
  AvgDialog_123120_Content_84 = {
    Text = "Per raggiungere il Sereno Reame Libero dalla Dissoluzione. Per redimere noi stessi in questo mondo in fiamme—"
  },
  AvgDialog_123120_Content_85 = {
    Text = "Per raggiungere il Sereno Reame Libero dalla Dissoluzione. Per redimere noi stessi in questo mondo in fiamme—"
  },
  AvgDialog_123120_Content_86 = {
    Text = "Finalmente, il primo credente allunga la mano e tocca il portale informe, varcando la soglia del nuovo mondo che tanto brama."
  },
  AvgDialog_123120_Content_87 = {
    Text = "<Shake:AAAAHHH—!>"
  },
  AvgDialog_123120_Content_88 = {
    Text = "In un urlo di pura disperazione, le mani del Credente iniziano a torcersi e a fondersi, dissolvendosi nell'improvvisa esplosione di luce intensa."
  },
  AvgDialog_123120_Content_89 = {
    Text = "Una nebbia densa e infinita sgorga dal portale, divorando la carne e le anime dei Seguaci, trasformando coloro che anelavano alle stelle in parte delle \"Stelle\" stesse."
  },
  AvgDialog_123120_Content_9 = {Text = "..."},
  AvgDialog_123120_Content_90 = {
    Text = "Il tuo Comunicatore specializzato gracchia di nuovo con scariche statiche, riproducendo quei familiari Deliri di morte:"
  },
  AvgDialog_123120_Content_91 = {
    Text = "@2 Io... salvare @2..."
  },
  AvgDialog_123120_Content_92 = {
    Text = "Salvare @2... @2 me..."
  },
  AvgDialog_123120_Content_93 = {
    Text = "Questo è... <Shake:Il rito è andato storto!>"
  },
  AvgDialog_123120_Content_94 = {
    Text = "Salvador, attento ai mostri nella nebbia!"
  },
  AvgDialog_123120_Content_95 = {
    Text = "Mentre parli, innumerevoli sagome Umanoidi si condensano dalla nebbia, ruggendo mentre caricano verso di te."
  },
  AvgDialog_123120_Content_96 = {
    Text = "Bene, finalmente le cose si fanno divertenti."
  },
  AvgDialog_123120_Content_97 = {
    Text = "Mouchette—"
  },
  AvgDialog_123120_Content_98 = {
    Text = "Va bene, smetto di parlare. Ma devo avvertirti, il Disastro di Nebbia si sta propagando rapidamente."
  },
  AvgDialog_123120_Content_99 = {
    Text = "...Messaggero Pallido, solo un momento fa riuscivo ancora a vedere ciò che ci circondava. Ora, tutto è svanito."
  },
  AvgDialog_123121_Content_1 = {
    Text = "Stelle spente"
  },
  AvgDialog_123121_Content_10 = {
    Text = "Con la tua forza, non avresti mai dovuto farti imprigionare da un pugno di cultisti patetici."
  },
  AvgDialog_123121_Content_11 = {
    Text = "Esatto. E credo che entrambi abbiamo notato quante volte hai chiesto informazioni sui tempi del rito. La tua espressione... era piuttosto eloquente, come se stessi anticipando qualcosa."
  },
  AvgDialog_123121_Content_12 = {
    Text = "Ah, ecco dove ho commesso l'errore. Che disattenzione."
  },
  AvgDialog_123121_Content_13 = {
    Text = "Quindi, chi sei davvero? Cos'è questo rito, e cosa ne sai?"
  },
  AvgDialog_123121_Content_14 = {
    Text = "Mouchette accenna un sorriso disinvolto e risponde con una domanda:"
  },
  AvgDialog_123121_Content_15 = {
    Text = "E voi due? Perché siete venuti in un posto come questo, dove l'ordine secolare è completamente crollato e non restano che tediose credenze?"
  },
  AvgDialog_123121_Content_16 = {
    Text = "Salvador non si offende per la sua osservazione. Al contrario, la guarda con genuina compassione."
  },
  AvgDialog_123121_Content_17 = {
    Text = "Vengo in nome della salvezza."
  },
  AvgDialog_123121_Content_18 = {
    Text = "Salvezza? Per chi? Per quel \"bestiame\" nella gabbia? Con tutto il rispetto, a volte una morte rapida è assai più clemente di una vita miserabile."
  },
  AvgDialog_123121_Content_19 = {
    Text = "Specialmente in un mondo così... hmm, emozionante e divertente come questo."
  },
  AvgDialog_123121_Content_2 = {
    Text = "Dopo aver inviato un segnale alla Cantilena, tu e Salvador attendete fuori dalla grotta la strana bambina che si fa chiamare Mouchette."
  },
  AvgDialog_123121_Content_20 = {
    Text = "La Benedizione del Padre di Tutto si riversa su ogni angolo che anela alla Redenzione."
  },
  AvgDialog_123121_Content_21 = {
    Text = "Quei prigionieri hanno invocato me e la Cantoria affinché li soccorressimo nella loro sofferenza, e noi risponderemo alle loro suppliche."
  },
  AvgDialog_123121_Content_22 = {
    Text = "Come emissario del Padre di Tutto, farò tutto ciò che è in mio potere per estirpare tale miseria da questa terra."
  },
  AvgDialog_123121_Content_23 = {
    Text = [[
Salvador abbassa il capo e congiunge le mani in devota preghiera.
In risposta, Mouchette emette una lieve risatina beffarda.]]
  },
  AvgDialog_123121_Content_24 = {
    Text = "Immagino che siate entrambi \"brave persone\" nel senso noioso e banale del termine, che credono in tutte quelle sciocchezze come \"ama il prossimo\" e \"tutti mi amano,\" giusto?"
  },
  AvgDialog_123121_Content_25 = {
    Text = "Ecco perché ti sei fidato di me così facilmente e mi hai seguita fin qui..."
  },
  AvgDialog_123121_Content_26 = {
    Text = "Onestamente, la vostra ingenuità è sufficiente a farmi venire il mal di testa."
  },
  AvgDialog_123121_Content_27 = {
    Text = "Non riesci a capire se la sua espressione sia di scherno o di malinconia, mentre un filo di nebbia giunto dal nulla le oscura improvvisamente il volto."
  },
  AvgDialog_123121_Content_28 = {
    Text = "Ti sbagli. Semplicemente scegliamo di non pensare il peggio di uno sconosciuto."
  },
  AvgDialog_123121_Content_29 = {
    Text = "Già, come volete. Non ha importanza comunque. Non potreste mai capire..."
  },
  AvgDialog_123121_Content_3 = {
    Text = "Con tua sorpresa, quando finalmente emerge dalle ombre, porta con sé un'ascia dal design elegante e raffinato."
  },
  AvgDialog_123121_Content_30 = {
    Text = "Un improvviso, acuto scatto meccanico interrompe le sue parole."
  },
  AvgDialog_123121_Content_31 = {
    Text = "Il Comunicatore sta captando fluttuazioni spirituali... la fonte è... la nebbia?!"
  },
  AvgDialog_123121_Content_32 = {
    Text = "Senza preavviso, quel filo di nebbia inizia a espandersi rapidamente. Inghiotte la figura di Mouchette e comincia ad avvolgere il paesaggio circostante in un fitto velo bianco."
  },
  AvgDialog_123121_Content_33 = {
    Text = "Fluttuazioni spirituali? Così spiegate il Disastro di Nebbia qui..."
  },
  AvgDialog_123121_Content_34 = {
    Text = "Il Disastro di Nebbia?"
  },
  AvgDialog_123121_Content_35 = {
    Text = "Ovviamente. Questo mondo morente non avrebbe qualcosa di così interessante da solo. Proviene da—"
  },
  AvgDialog_123121_Content_36 = {
    Text = "Dal <Yellow:mio mondo>."
  },
  AvgDialog_123121_Content_37 = {
    Text = "Il tuo mondo...?"
  },
  AvgDialog_123121_Content_38 = {
    Text = "Quegli stolti della Setta dell'Alba Astrale hanno aperto un portale proibito che non avrebbe mai dovuto essere toccato."
  },
  AvgDialog_123121_Content_39 = {
    Text = "Poi il Rito ha fatto <Italic:CRACK!> ed è fallito, lasciando solo me, la sfortunata, e queste cose persistenti—"
  },
  AvgDialog_123121_Content_4 = {
    Text = "Allora? Non è fantastico?"
  },
  AvgDialog_123121_Content_40 = {
    Text = "Solo un consiglio amichevole: forse dovreste iniziare a pensare a quando darvi alla fuga."
  },
  AvgDialog_123121_Content_41 = {
    Text = "In fuga da cosa?"
  },
  AvgDialog_123121_Content_42 = {
    Text = "Hehe☆... i piccoli nella nebbia stanno arrivando~"
  },
  AvgDialog_123121_Content_43 = {
    Text = "Divertitevi, ragazzi."
  },
  AvgDialog_123121_Content_44 = {
    Text = "Detto ciò, Mouchette arretra e svanisce nella fitta coltre di nebbia, la sua voce si dissolve nell'oscurità."
  },
  AvgDialog_123121_Content_45 = {
    Text = "Ah, e grazie per l'aiuto di prima. Una buona azione ne merita un'altra, giusto? Stavolta, voi due potete guadagnare un po' di tempo per me~"
  },
  AvgDialog_123121_Content_46 = {
    Text = "...Mouchette, aspetta!?"
  },
  AvgDialog_123121_Content_47 = {
    Text = "Vi muovete per fermarla, ma la nebbia è così densa che non avete idea di dove iniziare la Caccia."
  },
  AvgDialog_123121_Content_48 = {
    Text = "Afferrate la vostra Chiave d'Argento, preparandovi ad attivare il Tracciamento Spirituale, quando il Comunicatore stride di nuovo."
  },
  AvgDialog_123121_Content_49 = {
    Text = "È un suono aspro e distorto di Interferenza elettrica che cresce più forte e più straziante man mano che la nebbia avanza in un'Ondata."
  },
  AvgDialog_123121_Content_50 = {
    Text = "@2 Io... salvare @2..."
  },
  AvgDialog_123121_Content_51 = {Text = "...?!"},
  AvgDialog_123121_Content_52 = {
    Text = "Salvador, hai sentito?"
  },
  AvgDialog_123121_Content_53 = {
    Text = "Sembrava... una voce umana?"
  },
  AvgDialog_123121_Content_54 = {
    Text = "Alzate il Comunicatore, in Attesa che il suono si ripeta. Il dispositivo risponde con un grido lacerante di pura disperazione."
  },
  AvgDialog_123121_Content_55 = {
    Text = "È come una Lama frastagliata che si conficca nel vostro cervello, lasciandovi storditi e disorientati."
  },
  AvgDialog_123121_Content_56 = {
    Text = "Simultaneamente, innumerevoli sagome Umanoidi emergono ribollendo dalla nebbia, ruggendo mentre si avventano su di voi e Salvador."
  },
  AvgDialog_123121_Content_57 = {Text = "Attento!"},
  AvgDialog_123121_Content_58 = {
    Text = "Le Tavolette di Pietra di Salvador sfrecciamo nell'oscurità, frantumando i Mostri della nebbia, ma le urla strazianti persistono, aggredendo la vostra stessa anima."
  },
  AvgDialog_123121_Content_59 = {
    Text = "Il Sangue inizia a gocciolare dal vostro naso, schizzando a terra, ma la vostra Visuale è troppo offuscata dalla vertigine per vederlo chiaramente."
  },
  AvgDialog_123121_Content_6 = {
    Text = "Mouchette fa roteare l'ascia più volte con precisione netta e disinvolta, come se l'arma massiccia fosse un'estensione naturale del suo stesso corpo."
  },
  AvgDialog_123121_Content_60 = {
    Text = "Il vostro Spirito sembra staccarsi dalla carne, espandersi in uno Stato caotico e informe che percepisce l'intero villaggio in un solo istante."
  },
  AvgDialog_123121_Content_61 = {
    Text = "Lo sentite—la nebbia è ovunque, Divora senza ritegno la terra, gli edifici e ogni traccia di vita."
  },
  AvgDialog_123121_Content_62 = {
    Text = "E in questo vuoto bianco sconfinato, percepisci innumerevoli stelle che ardono di un fuoco freddo e silenzioso, morte da tempo e colme di dolore."
  },
  AvgDialog_123121_Content_63 = {Text = "%player%!"},
  AvgDialog_123121_Content_64 = {
    Text = "La voce di Salvador riecheggia nella tua mente, ma la disperazione che sgorga dalle profondità della tua anima ti paralizza."
  },
  AvgDialog_123121_Content_65 = {
    Text = "@2 Io... salvare @2..."
  },
  AvgDialog_123121_Content_66 = {
    Text = "Salvare @2... @2 me..."
  },
  AvgDialog_123121_Content_67 = {
    Text = "Quelle stelle morte ti circondano, grevi di un'agonia infinita. Tentano ostinatamente di fondere la tua coscienza e corrodere la tua volontà, trascinandoti in un dormiveglia eterno e gelido."
  },
  AvgDialog_123121_Content_68 = {
    Text = "...Non riesco a dormire... Sal..."
  },
  AvgDialog_123121_Content_69 = {
    Text = "Sal... vador... aiutami..."
  },
  AvgDialog_123121_Content_7 = {
    Text = "Avendo notato l'arma, decidi di incalzarla."
  },
  AvgDialog_123121_Content_70 = {
    Text = "Proprio in quel momento, una luce gentile divampa nel tuo mondo. Come un sole caldo, ti avvolge in un abbraccio costante, scacciando il freddo e il fetore della morte."
  },
  AvgDialog_123121_Content_71 = {
    Text = "È la radiosità di Salvador."
  },
  AvgDialog_123121_Content_72 = {
    Text = "Ha udito la tua supplica."
  },
  AvgDialog_123121_Content_73 = {
    Text = "Ha risposto."
  },
  AvgDialog_123121_Content_74 = {
    Text = "<Shake:Coff, coff...>"
  },
  AvgDialog_123121_Content_75 = {
    Text = "Con l'aiuto di Salvador, riesci finalmente a liberarti dalla foschia vertiginosa. Boccheggi in cerca d'aria, sentendo la lucidità tornare lentamente."
  },
  AvgDialog_123121_Content_76 = {
    Text = "Padre Salvador, potete interrompere la Benedizione ora. Io... sto molto meglio."
  },
  AvgDialog_123121_Content_77 = {
    Text = "Salvador annuisce, ma la sua attenzione resta rivolta alle minacce invisibili in agguato nella nebbia."
  },
  AvgDialog_123121_Content_78 = {
    Text = "Questi mostri nella nebbia non muoiono. Anche quando vengono frantumati, si ricompongono quasi istantaneamente."
  },
  AvgDialog_123121_Content_79 = {
    Text = "Temo che finché questa nebbia persisterà, queste creature non periranno mai davvero."
  },
  AvgDialog_123121_Content_8 = {
    Text = "Mouchette, ti sei fatta catturare dai cultisti di proposito."
  },
  AvgDialog_123121_Content_80 = {
    Text = "Padre Salvador, credete... che ciò che Mouchette ha detto sia vero?"
  },
  AvgDialog_123121_Content_81 = {
    Text = "Dal momento in cui ci siamo incontrati, la fiamma dell'anima della signorina Mouchette è rimasta costante. Ai miei occhi, non ha mostrato né il contegno né il movente di una bugiarda."
  },
  AvgDialog_123121_Content_82 = {
    Text = "Allora ho alcune teorie personali. Ma prima, dobbiamo trovarla."
  },
  AvgDialog_123121_Content_83 = {
    Text = "Rispetto la tua decisione, Pallido Messaggero."
  },
  AvgDialog_123121_Content_84 = {
    Text = "Non temete i mostri nella nebbia; garantirò la vostra incolumità."
  },
  AvgDialog_123121_Content_85 = {
    Text = "Guardi Salvador con gratitudine prima di afferrare la Chiave d'Argento."
  },
  AvgDialog_123121_Content_86 = {
    Text = "Il sangue ti cola di nuovo lungo la guancia, ma lo ignori. La terrificante consapevolezza intravista durante la vertigine ora occupa interamente la tua mente."
  },
  AvgDialog_123121_Content_87 = {
    Text = "@2 Io... salvare @2..."
  },
  AvgDialog_123121_Content_88 = {
    Text = "Salvare @2... @2 me..."
  },
  AvgDialog_123121_Content_89 = {
    Text = "Infine, mentre il comunicatore emette un altro strido, raggiungi attraverso le stelle fredde e morte lo spirito di Mouchette, stabilendo il contatto."
  },
  AvgDialog_123121_Content_9 = {
    Text = "Hmm? Stai scherzando? Le persone normali non si offrono volontarie per diventare prigioniere di un cultista, rinchiuse in una gabbia senza cibo né acqua."
  },
  AvgDialog_123122_Content_1 = {
    Text = "Attraverso il Tuo Sguardo"
  },
  AvgDialog_123122_Content_10 = {
    Text = "Sono occupata adesso. Non ho tempo per noiosi giochi di Casa, e non ho il minimo interesse a giocare il ruolo della \"figlia ribelle\" che si fa fare la predica."
  },
  AvgDialog_123122_Content_11 = {
    Text = "Non comprendi questo mondo, né conosci il vero pericolo del Rito di quei cultisti."
  },
  AvgDialog_123122_Content_12 = {
    Text = "I Prigionieri con cui eri rinchiusa sono tutti Sacrifici essenziali per il prossimo Rito."
  },
  AvgDialog_123122_Content_13 = {
    Text = "Inoltre, anche se il Rito venisse celebrato di nuovo, non hai modo di sapere se il portale tra i mondi si riaprirà davvero — o se potresti sopravvivere al Passaggio di ritorno verso il tuo mondo."
  },
  AvgDialog_123122_Content_14 = {
    Text = "Mouchette si blocca. Si morde il labbro con forza."
  },
  AvgDialog_123122_Content_15 = {Text = "..."},
  AvgDialog_123122_Content_16 = {
    Text = "Bambina, so che non sei giunta in questo mondo crudele per Scelta, e comprendo il tuo desiderio di tornare a casa."
  },
  AvgDialog_123122_Content_17 = {
    Text = "Desideriamo solo aiutarti... affinché tu non ti smarrisca su un Sentiero più oscuro."
  },
  AvgDialog_123122_Content_18 = {
    Text = "Stai dicendo che il mio piano di usare il loro Rito per tornare a casa... è il Sentiero sbagliato, quello \"più oscuro\"?"
  },
  AvgDialog_123122_Content_19 = {
    Text = "L'esitazione temporanea di Mouchette svanisce mentre il suo atteggiamento si indurisce nuovamente. Il suo tono apparentemente allegro è ora intriso di pungente sarcasmo."
  },
  AvgDialog_123122_Content_2 = {
    Text = "Come avete fatto a trovarmi?!"
  },
  AvgDialog_123122_Content_20 = {
    Text = "La nebbia circostante inizia a ribollire e a sollevarsi in un'Ondata."
  },
  AvgDialog_123122_Content_21 = {
    Text = "E qual è allora il Sentiero \"giusto\"? Chi ha il diritto di definirlo? Tu? O il tuo Dio?"
  },
  AvgDialog_123122_Content_22 = {
    Text = "La maschera è finalmente caduta. Mouchette non nasconde più il suo disprezzo e il suo sdegno verso Salvador."
  },
  AvgDialog_123122_Content_23 = {
    Text = "E anche se avessi giudicato cosa è giusto e cosa è sbagliato? Da quel che vedo, questo mondo è ancora più desolato e patetico di Temurahn."
  },
  AvgDialog_123122_Content_24 = {
    Text = "Quando quel \"bestiame\" soffriva, dov'era questo vostro \"Padre Supremo\"?"
  },
  AvgDialog_123122_Content_25 = {
    Text = "La Nebbia si agita con violenza, oscurando il volto di Mouchette e celando l'Espressione di Salvador."
  },
  AvgDialog_123122_Content_26 = {
    Text = "L'unica cosa che riesci a udire nell'oscurità è il pesante sospiro di Salvador e il sinistro, ritmico raschiare che annuncia l'avvicinarsi del pericolo."
  },
  AvgDialog_123122_Content_27 = {Text = "Io..."},
  AvgDialog_123122_Content_28 = {
    Text = "Parla pure, Padre. Non è che abbiamo altro da fare mentre aspettiamo."
  },
  AvgDialog_123122_Content_29 = {
    Text = "Non appena Mouchette finisce di parlare, innumerevoli sagome Umanoidi emergono dalla Nebbia circostante, caricando verso di voi."
  },
  AvgDialog_123122_Content_3 = {
    Text = "Qualcosa è andato storto con la Nebbia? Oppure anche voi possedete l'abilità di vedere attraverso la Nebbia, proprio come l'<Italic:Investigatore>?"
  },
  AvgDialog_123122_Content_30 = {
    Text = "Ma Mouchette è più veloce. Vedendo che sta per sgusciare via di nuovo, gridi."
  },
  AvgDialog_123122_Content_31 = {
    Text = "Salvador, fermala!"
  },
  AvgDialog_123122_Content_4 = {
    Text = "Lo stupore di Mouchette non dura a lungo; in un istante, la sua espressione si fa calma."
  },
  AvgDialog_123122_Content_5 = {
    Text = "Avete certamente i vostri modi per sfuggire agli Antichi Mostri nella Nebbia. Ma—"
  },
  AvgDialog_123122_Content_6 = {
    Text = "<Big:<Shake:Non osate mettervi sulla mia strada!>>"
  },
  AvgDialog_123122_Content_7 = {
    Text = "Mouchette stringe saldamente la sua ascia, lo sguardo colmo di vigilanza e ostilità."
  },
  AvgDialog_123122_Content_8 = {
    Text = "Mouchette, non devi farlo. Non siamo tuoi nemici. Almeno, non in questo momento."
  },
  AvgDialog_123122_Content_9 = {
    Text = "Ma prima che tu prenda la tua decisione, c'è qualcosa che devo dirti."
  },
  AvgDialog_125040_Content_1 = {
    Text = "L'inondazione del Fiume sacro ha portato guai senza precedenti a Mythag. Inaspettatamente, la stanza di Xu è diventata uno dei pochi luoghi in cui trovare rifugio."
  },
  AvgDialog_125040_Content_10 = {
    Text = "Posso essere una menzogna, un Desiderio fugace, ma quando sono soltanto me stessa... diventa terribilmente noioso."
  },
  AvgDialog_125040_Content_11 = {Text = "Ehm... Xu?"},
  AvgDialog_125040_Content_12 = {Text = "Nebbia."},
  AvgDialog_125040_Content_13 = {
    Text = "Delicata come seta, sottile come filo, la nebbia si avvolge attorno a te in strati."
  },
  AvgDialog_125040_Content_14 = {
    Text = "<LightGray:Non doveva essere senza conseguenze? Non dovevate solo chiacchierare e giocare a scacchi?! Voi Risvegliatori, perché dite sempre una cosa e ne fate un'altra!>"
  },
  AvgDialog_125040_Content_15 = {
    Text = "Un bagliore dorato e scintillante lampeggia ai margini della tua Visuale. Qualcosa di liscio come raso si avvolge attorno alle tue braccia e alla schiena, guidandoti dolcemente a sollevare la cortina tessuta di nebbia."
  },
  AvgDialog_125040_Content_16 = {
    Text = "Oh cielo, è solo che sono davvero, davvero curiosa."
  },
  AvgDialog_125040_Content_17 = {
    Text = "Quando mi toccano, toccano soltanto un'illusione. Quando mi guardano, stanno contemplando qualcun altro che \"credono\" di amare."
  },
  AvgDialog_125040_Content_18 = {
    Text = "Ma tu sei diverso. Stai proiettando l'ombra di qualcun altro su di me? Se ti addentrassi più a fondo, il volto di chi vedresti sotto il mio ventaglio...?"
  },
  AvgDialog_125040_Content_19 = {
    Text = "La nebbia si apre. Sotto il ventaglio, qualcosa di caldo sfiora delicatamente la punta del tuo naso. Le nappe piumate sulla sua spalla ricadono, accarezzando dolcemente la tua pelle tremante."
  },
  AvgDialog_125040_Content_2 = {
    Text = "Il Fiume sacro non ti ha influenzato affatto?"
  },
  AvgDialog_125040_Content_20 = {
    Text = "<LightGray:Ottimo, bollente, un altro ancora.>"
  },
  AvgDialog_125040_Content_21 = {
    Text = "Xu, se ricordo bene, hai appena detto di non avere \"pensieri impuri.\""
  },
  AvgDialog_125040_Content_22 = {
    Text = "Beh... Nell'estremo oriente, quando un monarca ha questioni importanti da discutere, invita il proprio ospite nella tenda di comando—da qui l'espressione <Italic:\"ospite ammesso oltre la tenda.\">"
  },
  AvgDialog_125040_Content_23 = {
    Text = "Sebbene, naturalmente, quando riferita a una donna, l'espressione assuma tutt'altro significato."
  },
  AvgDialog_125040_Content_24 = {
    Text = "<Shake:—Tac.>"
  },
  AvgDialog_125040_Content_25 = {
    Text = "Una goccia di cera fusa cade sul tavolo; le pietre del go si disperdono in disordine."
  },
  AvgDialog_125040_Content_26 = {
    Text = "La luce si spegne."
  },
  AvgDialog_125040_Content_27 = {
    Text = "Mi sono sempre tenuta al di fuori della mischia. Eppure potresti essere tu quello che finalmente mi vede."
  },
  AvgDialog_125040_Content_28 = {
    Text = "Solo per te mi siederei volentieri dietro queste tende, poiché sei l'ospite che potrebbe contare più di ogni altro nella mia vita. Come potrei mai avere \"pensieri impuri,\" dunque?"
  },
  AvgDialog_125040_Content_29 = {
    Text = "Le costrizioni svaniscono. Questa divinità antica e misteriosa ti ha chiaramente lasciato una via di ritirata."
  },
  AvgDialog_125040_Content_3 = {
    Text = "Forse è perché anche il mio Potere deriva dai tre grandi Eoni, o forse perché sono semplicemente troppo esperta nell'arte del piacere — sembro non avere pensieri vaganti."
  },
  AvgDialog_125040_Content_30 = {
    Text = "E con essa, un invito appena udibile, ambiguamente giocoso, colmo di delizia."
  },
  AvgDialog_125040_Content_31 = {
    Text = "Ricordi quel romanzo? <Italic:\"Sono decaduto nell'abisso, cercando una riva che non posso raggiungere...\">"
  },
  AvgDialog_125040_Content_4 = {
    Text = "I suoi begli occhi traboccano di sorrisi. Alcune pietre bianche di Weiqi si posano con un lieve ticchettio sulla tavola. Xu sembra piuttosto affezionata a questo antico gioco dell'estremo oriente."
  },
  AvgDialog_125040_Content_5 = {
    Text = "Gli esseri umani sono creature così bizzarre. Perdono ogni Compostezza per un fugace istante di beatitudine, solo per annoiarsi all'istante una volta che l'hanno ottenuta."
  },
  AvgDialog_125040_Content_6 = {
    Text = "Più si vedono, meno desiderano vedersi. Solo tessendo per loro illusioni, attirandoli a Sacrificare le proprie vite, a strapparsi il cuore per amore, posso lasciare un'impressione duratura."
  },
  AvgDialog_125040_Content_7 = {
    Text = "La luce tremolante delle candele traccia la sua tenue, umbratile silhouette mentre siede con grazia sul letto."
  },
  AvgDialog_125040_Content_8 = {
    Text = "Il cielo si è oscurato prima che tu potessi accorgertene. Lei lascia sfuggire una risata sommessa."
  },
  AvgDialog_125040_Content_9 = {
    Text = "Adorano tutti rovinare le vergini e \"salvare\" le sgualdrin@1e — oh, sono maestra consumata in questa piccola commedia. Offro loro la Storia perfetta — metà verità, metà menzogna, poi con un colpo di ventaglio... concedo loro uno scorcio: li farà struggere di senso di colpa, o ardere di amore non corrisposto."
  },
  AvgDialog_126907_Content_1 = {
    Text = "Scintille d'un Tempo Passato"
  },
  AvgDialog_126907_Content_10 = {
    Text = "Allora, prego, fate pure."
  },
  AvgDialog_126907_Content_11 = {
    Text = "Gli occhi di Elsa si illuminano. Ti afferra la mano e, prima ancora che tu possa assumere la posizione, si lancia nella danza con una velocità sorprendente."
  },
  AvgDialog_126907_Content_12 = {
    Text = "La sua forza è così travolgente che per poco non ti scaglia dall'altra parte della stanza. Nel panico, ti strattona indietro con forza bruta."
  },
  AvgDialog_126907_Content_13 = {
    Text = "<Shake:M-mi dispiace tanto,> Lord Dexter! La prossima volta farò meglio, lo prometto..."
  },
  AvgDialog_126907_Content_14 = {
    Text = "Ti senti come una trottola frustata in cerchi vorticosi e vertiginosi. I tuoi passi già maldestri diventano un disastro totale."
  },
  AvgDialog_126907_Content_15 = {Text = "Pfft."},
  AvgDialog_126907_Content_16 = {
    Text = "Assistendo alla tua disavventura, Ramona non riesce a trattenere una risatina sommessa."
  },
  AvgDialog_126907_Content_17 = {
    Text = "Incroci i suoi occhi, sentendo l'allegria nel suo sguardo sussurrarti—"
  },
  AvgDialog_126907_Content_18 = {
    Text = "Lord Dexter, avete finalmente trovato pane per i vostri denti."
  },
  AvgDialog_126907_Content_19 = {Text = "..."},
  AvgDialog_126907_Content_2 = {
    Text = "Nella sala da ballo, ragazzi e ragazze in uniforme scolastica danzano con grazia sulla pista. La musica scorre come acqua, accarezzando i palmi intrecciati, le gonne volteggianti e gli sguardi scambiati."
  },
  AvgDialog_126907_Content_20 = {
    Text = "La canzone finisce. Baci frettolosamente la mano della tua partner in segno di commiato e ti dirigi dritto verso Ramona."
  },
  AvgDialog_126907_Content_21 = {
    Text = "Ricordo che eravate noto come il più elegante ballerino da sala di tutto Mythag, Lord Dexter."
  },
  AvgDialog_126907_Content_22 = {
    Text = "Ti spremi le meningi, cercando di imitare la risposta fluida e melliflua di Lord Dexter."
  },
  AvgDialog_126907_Content_23 = {
    Text = "Beh, se esistesse un concorso \"Balla con Elsa\", vincerei comunque io."
  },
  AvgDialog_126907_Content_24 = {
    Text = "Ramona distoglie lo sguardo, facendo ruotare delicatamente il bicchiere che tiene in mano."
  },
  AvgDialog_126907_Content_25 = {
    Text = "Elsa vi ammira davvero. Anche se la danza non è stata perfetta, probabilmente ha esaudito il suo desiderio del Festival di Primavera."
  },
  AvgDialog_126907_Content_26 = {
    Text = "Peccato che chi ha danzato con lei non fosse il vero Lord Dexter."
  },
  AvgDialog_126907_Content_27 = {
    Text = "Peggio ancora, l'uomo che lei conosce non è mai stato il vero Lord Dexter, con o senza il vostro \"possesso\" del suo corpo oggi."
  },
  AvgDialog_126907_Content_28 = {
    Text = "Ma non è questo l'argomento che volete affrontare."
  },
  AvgDialog_126907_Content_29 = {
    Text = "Ramona, qual è il tuo desiderio per la Festa di Primavera?"
  },
  AvgDialog_126907_Content_3 = {
    Text = "Noti Ramona in piedi da sola accanto a un tavolino ai margini della pista da ballo, che sorseggia una bevanda sconosciuta."
  },
  AvgDialog_126907_Content_30 = {
    Text = "Già cambiate argomento? Saltate i saluti a questa o quella dama, e ora vi preoccupate per vostra figlia adottiva?"
  },
  AvgDialog_126907_Content_31 = {
    Text = "Ho notato che non avete ancora danzato. Nessuno attira il vostro sguardo?"
  },
  AvgDialog_126907_Content_32 = {
    Text = "Non c'è bisogno che vi disturbiate."
  },
  AvgDialog_126907_Content_33 = {
    Text = "Concedereste una danza a questo vecchio solitario?"
  },
  AvgDialog_126907_Content_34 = {
    Text = "Ramona ammutolisce. Riesci quasi a vederla frugare nella mente in cerca di una scusa per rifiutare."
  },
  AvgDialog_126907_Content_35 = {
    Text = "La persona che state aspettando... vorrebbe che accettaste questa danza."
  },
  AvgDialog_126907_Content_36 = {
    Text = "Come fate a saperlo?"
  },
  AvgDialog_126907_Content_37 = {
    Text = "Lo so e basta."
  },
  AvgDialog_126907_Content_38 = {
    Text = "Un silenzio ancora più lungo."
  },
  AvgDialog_126907_Content_39 = {
    Text = "E sia. Vi prenderò in parola. Solo per questa volta."
  },
  AvgDialog_126907_Content_4 = {
    Text = "Stai riflettendo su come iniziare una conversazione quando una voce timida si fa sentire accanto a te."
  },
  AvgDialog_126907_Content_40 = {
    Text = "Si muove con grazia sulla pista da ballo, le dita sottili posate sul tuo palmo."
  },
  AvgDialog_126907_Content_41 = {
    Text = "Su, avanti. Non ho mai danzato con voi."
  },
  AvgDialog_126907_Content_42 = {Text = "..."},
  AvgDialog_126907_Content_43 = {
    Text = "I passi di Ramona sono proprio come lei: razionali, misurati, precisi e meticolosi."
  },
  AvgDialog_126907_Content_44 = {
    Text = "Scioglietevi un po'. State trattando la pista da ballo come un campo di battaglia."
  },
  AvgDialog_126907_Content_45 = {
    Text = "E voi potreste concentrarvi un po' di più, mio signore. Mi avete quasi pestato i piedi già tre volte."
  },
  AvgDialog_126907_Content_46 = {
    Text = "Non sembra affatto il Lord Dexter, la farfalla mondana di decenni."
  },
  AvgDialog_126907_Content_47 = {
    Text = "Forse a volte... mi va di giocare un ruolo diverso?"
  },
  AvgDialog_126907_Content_48 = {Text = "Davvero?"},
  AvgDialog_126907_Content_49 = {
    Text = "Sapete, oggi siete stato insolitamente silenzioso."
  },
  AvgDialog_126907_Content_5 = {
    Text = "<Shake:<Small:Lord Dexter... Posso avere questo ballo con voi?>>"
  },
  AvgDialog_126907_Content_50 = {
    Text = "<LightGray:(Credevo di restare perfettamente nel personaggio...)>"
  },
  AvgDialog_126907_Content_51 = {
    Text = "Davvero? Sarà il freddo. Uccide ogni voglia di chiacchierare."
  },
  AvgDialog_126907_Content_52 = {
    Text = "Il vero Lord Dexter direbbe: \"Flirtare con la propria figlia adottiva è alquanto tabù, sai.\""
  },
  AvgDialog_126907_Content_53 = {
    Text = "<Yellow:Chi siete, in realtà?>"
  },
  AvgDialog_126907_Content_54 = {
    Text = "Ramona, il nostro tempo insieme è così breve. Non voglio..."
  },
  AvgDialog_126907_Content_55 = {
    Text = "Un colpo di tosse sommesso di Xu vi interrompe."
  },
  AvgDialog_126907_Content_56 = {
    Text = "Non importa — guardate!"
  },
  AvgDialog_126907_Content_59 = {
    Text = "In un istante, i fuochi d'artificio fischiano nel cielo notturno."
  },
  AvgDialog_126907_Content_6 = {
    Text = "Hmm? E perché mai?"
  },
  AvgDialog_126907_Content_62 = {
    Text = "Fiori di fuoco e d'oro sbocciano in alto in una catena ininterrotta."
  },
  AvgDialog_126907_Content_64 = {
    Text = "Proprio come quel giorno alla Cerimonia di consegna della chiave, prendi la mano di Ramona."
  },
  AvgDialog_126907_Content_66 = {
    Text = "Ignorando la sua espressione spaventata, chiudi gli occhi."
  },
  AvgDialog_126907_Content_68 = {
    Text = "Nell'oscurità, si leva un coro di voci gioiose e piene di speranza:"
  },
  AvgDialog_126907_Content_69 = {
    Text = "<Big:<Shake:\"Buona Festa di Primavera!\">>"
  },
  AvgDialog_126907_Content_7 = {
    Text = "Nessun altro vuole ballare con me... Dicono che è troppo pericoloso."
  },
  AvgDialog_126907_Content_70 = {
    Text = "Buon Festival di Primavera, Ramona."
  },
  AvgDialog_126907_Content_71 = {
    Text = "La mezzanotte è giunta, il vento ulula, e tutte le storie che avrebbero dovuto appartenerti si stanno allontanando da te."
  },
  AvgDialog_126907_Content_72 = {
    Text = "Ma lo sai, il giorno del ricongiungimento non è più lontano."
  },
  AvgDialog_126907_Content_8 = {
    Text = "Ma non preoccupatevi! Farò del mio meglio per controllare la mia forza!"
  },
  AvgDialog_126907_Content_9 = {
    Text = "Il tuo sguardo scorre sulla bambina nervosa che hai davanti."
  },
  AvgDialog_126908_Content_1 = {
    Text = "Cabina senza Luce"
  },
  AvgDialog_126908_Content_10 = {
    Text = "Il suo sorriso e la sua figura tremolano e si dissolvono, disperdendosi come cenere nel vento."
  },
  AvgDialog_126908_Content_11 = {
    Text = "Avanti. Reclama il tuo premio."
  },
  AvgDialog_126908_Content_12 = {
    Text = "Oltre la nebbia e la cenere, una porta emerge — la porta della cabina del conducente."
  },
  AvgDialog_126908_Content_13 = {
    Text = "Nessun trucco, nessun meccanismo nascosto, nulla di superfluo."
  },
  AvgDialog_126908_Content_14 = {
    Text = "È semplicemente una porta ordinaria, come qualsiasi altra del suo genere, che assolve la funzione di \"entrata e uscita\", in attesa per te alla fine dell'enigma."
  },
  AvgDialog_126908_Content_15 = {
    Text = "Fai un respiro profondo, stringi la Chiave d'Argento e spingi la porta aperta."
  },
  AvgDialog_126908_Content_16 = {Text = "..."},
  AvgDialog_126908_Content_17 = {
    Text = "<LightGray:(Niente più cadaveri, niente membri dell'equipaggio smembrati — questa quiete quasi mi inquieta.)>"
  },
  AvgDialog_126908_Content_18 = {Text = "Hm?"},
  AvgDialog_126908_Content_19 = {
    Text = "Un filo di nebbia si riversa dalla consolle, propagandosi dolcemente in un fazzoletto di seta che riluce di un tenue bagliore. Vi è scritto, in caratteri di Londinium dal tratto elegante e del tutto fuori luogo, un messaggio:"
  },
  AvgDialog_126908_Content_2 = {Text = "Carrozza 1"},
  AvgDialog_126908_Content_20 = {
    Text = "Mio carissimo Custode,\n\nSe sei arrivato fin qui, devi aver scoperto il segreto di questo treno: è un Dominio Artificiale creato da N. A questo punto, la \"me\" su questo treno è morta.\n\nHo osservato mentre ognuno di voi parlava della propria terra natale. Winkle e Tintura... le loro case sono state ridotte al nulla da tempo. Avevo considerato Miryam, ma a un esame più attento, la Lemuria che descriveva è un passato irrecuperabile."
  },
  AvgDialog_126908_Content_21 = {
    Text = "E dove desidero tornare io? Suppongo... sia la vera Terra Senza Sogni. Tutti loro, tutti noi... non abbiamo più da tempo una casa dove tornare.\n\nMa tu, solo tu, %player% — l'Università di Mythag che tanto desideri esiste ancora, e ci sono ancora persone là che aspettano il tuo ritorno.\n\nPerciò, devi diventare il vincitore finale di questo gioco.\n\nQuindi, ti offro questa vittoria, con la mia stessa morte come sua nota a piè di pagina.\nTira semplicemente la leva accanto a te, e ti porterà nel luogo dove quelle persone ti attendono."
  },
  AvgDialog_126908_Content_22 = {
    Text = "Che sia tu che io possiamo ottenere ciò che desideriamo.\n\n\n—Xu"
  },
  AvgDialog_126908_Content_23 = {
    Text = "Sembra uno scherzo contorto, degno della natura malevola di N..."
  },
  AvgDialog_126908_Content_24 = {
    Text = "Mormori sottovoce, cercando di scacciare quell'impulso dalla testa."
  },
  AvgDialog_126908_Content_25 = {
    Text = "Ma la tentazione è semplicemente troppo forte — volti familiari balenano nei tuoi pensieri, finché una figura non si staglia con chiarezza..."
  },
  AvgDialog_126908_Content_26 = {Text = "Ramona..."},
  AvgDialog_126908_Content_27 = {
    Text = "Il tuo cuore martella così forte da sopraffare ogni senso. Prima che la ragione possa raggiungerti, il tuo corpo si è già mosso. Spingi la leva in avanti con un affondo."
  },
  AvgDialog_126908_Content_28 = {
    Text = "Il treno sussulta violentemente, accelerando mentre si scaglia verso il vuoto nero davanti a sé."
  },
  AvgDialog_126908_Content_29 = {
    Text = "Pochi secondi dopo, alla fine del tunnel un centinaio di metri più avanti, una parete rocciosa a strapiombo si profila alla vista."
  },
  AvgDialog_126908_Content_3 = {
    Text = "All'estremità della Carrozza 1, una figura esile attende in silenzio, il volto celato da un ventaglio."
  },
  AvgDialog_126908_Content_30 = {
    Text = "Non puoi essere serio..."
  },
  AvgDialog_126908_Content_31 = {
    Text = "In preda al panico, tiri la leva all'indietro con tutte le tue forze, ma è bloccata, si rifiuta di muoversi. La parete ti si precipita addosso a oltre cento chilometri all'ora."
  },
  AvgDialog_126908_Content_32 = {
    Text = "<Red:Sto per schiantarmi...>"
  },
  AvgDialog_126908_Content_33 = {
    Text = "Chiudi gli occhi, inerme, in attesa dell'impatto."
  },
  AvgDialog_126908_Content_34 = {
    Text = "<Shake:Che trucco meschino... Perché sono stato così stupido da fidarmi di un qualsiasi avatar di N...?>"
  },
  AvgDialog_126908_Content_35 = {Text = "BOOM—!!!"},
  AvgDialog_126908_Content_36 = {
    Text = "Nell'istante in cui il treno si schianta, l'assenza di gravità ti afferra e ti trascina verso il basso."
  },
  AvgDialog_126908_Content_37 = {Text = "!!! Ugh!!"},
  AvgDialog_126908_Content_38 = {
    Text = "Il tempo passa. Non sai per quanto."
  },
  AvgDialog_126908_Content_39 = {Text = "..."},
  AvgDialog_126908_Content_4 = {
    Text = "Permettimi di presentarmi. Sono la Thais di questo treno, oppure puoi chiamarmi la talpa di N."
  },
  AvgDialog_126908_Content_40 = {
    Text = "Questo è... <Shake:Mythag?!>"
  },
  AvgDialog_126908_Content_41 = {
    Text = "L'architettura fuori dal finestrino è inconfondibilmente familiare. Una gioia travolgente ti acceca di fronte alle sottili stranezze della scena — per poco non balzi dalla costosa poltrona."
  },
  AvgDialog_126908_Content_42 = {
    Text = "Finché il tuo sguardo non cade su uno specchio posizionato con un'angolazione estremamente deliberata e calcolata."
  },
  AvgDialog_126908_Content_43 = {
    Text = "Riflesso al suo interno vi è il volto di Lord Dexter."
  },
  AvgDialog_126908_Content_44 = {Text = "???"},
  AvgDialog_126908_Content_45 = {
    Text = "Ti tocchi il viso incredulo: le dita del riflesso tracciano la sua mascella scolpita in perfetta sincronia."
  },
  AvgDialog_126908_Content_46 = {
    Text = "Oh, oh! La ricompensa per essere uscito vivo era un \"ritorno a Mythag,\" ma non ho mai promesso come saresti tornato, vero?"
  },
  AvgDialog_126908_Content_47 = {
    Text = "Il massimo che ho potuto fare è stato lasciarti prendere in prestito uno dei miei avatar per un po'."
  },
  AvgDialog_126908_Content_48 = {
    Text = "Ciononostante, questo sfida le leggi dell'universo. Devi esercitare moderazione: non permettere a nessuno di scoprire che non sei il vero Lord Dexter, d'accordo~?"
  },
  AvgDialog_126908_Content_49 = {
    Text = "Immagino tu stia per dire: \"Altrimenti...\""
  },
  AvgDialog_126908_Content_5 = {
    Text = "Nei lunghi millenni della mia vita, mi sono abituata soprattutto al nome \"Xu.\" È abbastanza ordinario, abbastanza comune, abbastanza familiare da poter essere scambiato per chiunque."
  },
  AvgDialog_126908_Content_50 = {
    Text = "Altrimenti—ta-da! La campana di mezzanotte suonerà in anticipo, e la carrozza di zucca e le scarpette di cristallo torneranno alle loro forme originali."
  },
  AvgDialog_126908_Content_51 = {
    Text = "Quindi assapora i momenti prima che l'orologio scocchi la mezzanotte. Dopotutto, hai pagato questo tempo con le vite dei tuoi compagni."
  },
  AvgDialog_126908_Content_6 = {
    Text = "Ho ancora così tanto che vorrei dirti, ma non qui."
  },
  AvgDialog_126908_Content_7 = {
    Text = "Se il fato lo permetterà, forse le nostre strade si incroceranno di nuovo, in un altro tempo e in un altro luogo."
  },
  AvgDialog_126908_Content_8 = {
    Text = "Alza la Mano e frantuma il Nucleo d'Argento."
  },
  AvgDialog_126908_Content_9 = {
    Text = "Sei il vincitore finale, Custode."
  },
  AvgDialog_126909_Content_1 = {
    Text = "Treno di Ritorno"
  },
  AvgDialog_126909_Content_10 = {
    Text = "<Shake:Clang — clang — clang —>"
  },
  AvgDialog_126909_Content_11 = {
    Text = "<Shake:Hmm... che sonno...> Non importa quanto dorma su questo treno, non è mai abbastanza."
  },
  AvgDialog_126909_Content_12 = {
    Text = "<LightGray:(Mi sembra di avere il cervello in un groviglio... Ho dimenticato qualcosa di importante?)>"
  },
  AvgDialog_126909_Content_13 = {
    Text = "<LightGray:<Shake:(Vabbè. Le vacanze della Festa di Primavera sono la scusa perfetta — e tornerò dritta al dormitorio a fare la morta. Anche se Doll mi pressa per i compiti o Ramona mi tormenta per i rapporti, resisterò fino all'ultimo respiro...)>>"
  },
  AvgDialog_126909_Content_14 = {
    Text = "Oh, che alberello assonnato~ Puoi appoggiarti alla mia spalla finché il treno non raggiunge il capolinea, sai?"
  },
  AvgDialog_126909_Content_15 = {Text = "Cosa?!"},
  AvgDialog_126909_Content_16 = {
    Text = "Ti guardi intorno e conti i passeggeri."
  },
  AvgDialog_126909_Content_17 = {
    Text = "Wanda fa roteare mezzo bicchiere di vino rosso, ammirando le sue unghie curate e affilate."
  },
  AvgDialog_126909_Content_18 = {
    Text = "Tintura tiene in silenzio uno spartito musicale, muovendo le labbra mentre si esercita senza emettere suono."
  },
  AvgDialog_126909_Content_19 = {
    Text = "Winkle si rannicchia vicino a una lampada fioca, gli occhi incollati allo stoppino tremolante come se temesse che la luce possa fuggire."
  },
  AvgDialog_126909_Content_2 = {
    Text = "Ta-daaan! Signore e signori del pubblico, buona Festa di Primavera! Finalmente, finalmente — è il momento di brillare della Piccola N!"
  },
  AvgDialog_126909_Content_20 = {
    Text = "Miryam tiene la testa reclinata all'indietro, gli occhi chiusi, apparentemente ignara di ciò che la circonda."
  },
  AvgDialog_126909_Content_21 = {
    Text = "<LightGray:(Tutti badano ai fatti propri... un'atmosfera così pacifica...)>"
  },
  AvgDialog_126909_Content_22 = {Text = "..."},
  AvgDialog_126909_Content_23 = {Text = "..."},
  AvgDialog_126909_Content_24 = {
    Text = "<LightGray:(Ma... questo viaggio in treno non sta durando fin troppo?)>"
  },
  AvgDialog_126909_Content_25 = {
    Text = "Il Mythag Express è un treno a tratta breve progettato per attraversare la Barriera di Nebbia. Ma da quando ti sei svegliata, è passata almeno un'ora."
  },
  AvgDialog_126909_Content_26 = {
    Text = "Dopo aver riflettuto un momento, ti avvicini all'unico membro del corpo docente a bordo."
  },
  AvgDialog_126909_Content_27 = {
    Text = "Winkle… perché oggi il <Yellow:treno speciale per Mythag> è così lento?"
  },
  AvgDialog_126909_Content_28 = {
    Text = "Winkle balza in piedi come una lepre spaventata."
  },
  AvgDialog_126909_Content_29 = {
    Text = "C-che Mythag Express? Questo treno non è diretto al pianeta natale @1?"
  },
  AvgDialog_126909_Content_3 = {
    Text = "Anche se sei il mio avatar, devo ammettere che la tua idea di intrattenimento, questa volta, è di una volgarità imbarazzante. Francamente, rasenta l'assurdo."
  },
  AvgDialog_126909_Content_30 = {
    Text = "Tutti gli sguardi si rivolgono verso Winkle come riflettori."
  },
  AvgDialog_126909_Content_31 = {
    Text = "Non dire sciocchezze, bambina. Questo non è il treno per Aram?"
  },
  AvgDialog_126909_Content_32 = {
    Text = "Eh? Eh? Ma Aram si trova nel profondo del deserto—nessun binario potrebbe mai raggiungerla..."
  },
  AvgDialog_126909_Content_33 = {
    Text = "Per quanto ne so, la destinazione di questo treno dovrebbe essere Isarawu."
  },
  AvgDialog_126909_Content_34 = {
    Text = "Ancora più assurdo. Isarawu non è in rovina da secoli?"
  },
  AvgDialog_126909_Content_35 = {
    Text = "Le parole non bastano. Ho delle prove."
  },
  AvgDialog_126909_Content_36 = {
    Text = "Wanda estrae un biglietto di metallo e lo mostra a tutti."
  },
  AvgDialog_126909_Content_37 = {
    Text = "La destinazione indica chiaramente \"Isarawu\"."
  },
  AvgDialog_126909_Content_38 = {
    Text = "Miryam, Tinct, e voi due...?"
  },
  AvgDialog_126909_Content_39 = {
    Text = "Non servono parole. La sua volontà mi guiderà fino a Lemuria."
  },
  AvgDialog_126909_Content_4 = {
    Text = "Ma è la Festa di Primavera! Bisogna offrire al nostro caro pubblico qualcosa di fresco e festoso, non credi?"
  },
  AvgDialog_126909_Content_40 = {
    Text = "Io... voglio passare le feste con mia sorella... sulla Desolata, a casa nostra..."
  },
  AvgDialog_126909_Content_41 = {
    Text = "<LightGray:(La Desolata... Tinct ha impiegato innumerevoli eoni di peregrinazioni per raggiungere Kadath. Quella distanza è inimmaginabile per un semplice treno...)>"
  },
  AvgDialog_126909_Content_42 = {
    Text = "Lemuria è sprofondata sotto l'oceano migliaia di anni fa."
  },
  AvgDialog_126909_Content_43 = {
    Text = "E Isarawu... è stata distrutta da tempo."
  },
  AvgDialog_126909_Content_44 = {
    Text = "Piccola, hai fatto la sapientona sulle faccende di tutti gli altri. E tu? Come si chiama questo \"pianeta natale\", e dov'è?"
  },
  AvgDialog_126909_Content_45 = {
    Text = "Winkle impallidisce."
  },
  AvgDialog_126909_Content_46 = {
    Text = "<Shake:Il pianeta natale... è semplicemente il pianeta natale! Il suo nome è... <Small:@1...>>"
  },
  AvgDialog_126909_Content_47 = {
    Text = "Hmm? Ho sentito bene? Non riesci nemmeno a ricordare il nome del tuo Focolare?"
  },
  AvgDialog_126909_Content_48 = {
    Text = "Tutti, calmatevi e ascoltatemi."
  },
  AvgDialog_126909_Content_49 = {
    Text = "Le vostre destinazioni sembrano tutte... irrealistiche. Eppure ciascuno di voi possiede un biglietto per la propria terra natale."
  },
  AvgDialog_126909_Content_5 = {
    Text = "Anche così, non è un po' esagerato avere una sola scena dall'inizio alla fine?"
  },
  AvgDialog_126909_Content_50 = {
    Text = "Quindi, ciò di cui abbiamo più bisogno è trovare il <Yellow:personale di bordo> sul treno per ottenere informazioni su questo convoglio, invece di litigare inutilmente qui."
  },
  AvgDialog_126909_Content_51 = {Text = "Ehm."},
  AvgDialog_126909_Content_52 = {
    Text = "Una voce comica e bizzarra si leva dalle ombre."
  },
  AvgDialog_126909_Content_53 = {
    Text = "Avete già finito di bisticciare? Speravo in uno spettacolo più lungo~"
  },
  AvgDialog_126909_Content_54 = {
    Text = "Piccola N？!"
  },
  AvgDialog_126909_Content_55 = {
    Text = "Che sguardo è quello? Non sono il benvenuto? Dopo tutto il disturbo che mi sono preso per preparare un meraviglioso dono per la Festa di Primavera per tutti voi!"
  },
  AvgDialog_126909_Content_56 = {
    Text = "La mente dietro le quinte avanza gioiosamente sotto i riflettori. Le sue intenzioni malevole sono evidenti—deve star tramando qualcosa di ancora più grande."
  },
  AvgDialog_126909_Content_57 = {
    Text = "Che ci fai qui?"
  },
  AvgDialog_126909_Content_58 = {
    Text = "Non è forse ovvio? Nello spirito della festa, la vostra premurosa, altruista e caritatevole Piccola N ha inaugurato questo \"Espresso del Focolare\", affinché ogni anima nostalgica possa assaporare il calore del ricongiungimento!"
  },
  AvgDialog_126909_Content_59 = {
    Text = "Non sei così generosa. Sputa il rospo: cosa stai nascondendo?"
  },
  AvgDialog_126909_Content_6 = {
    Text = "<Shake:Sob... I tempi sono cambiati da quando gestivi il teatro e ti scontravi con quella Signora... Il budget per questo festival è una miseria! Questo palcoscenico ridotto all'osso è tutto ciò che possiamo permetterci...>"
  },
  AvgDialog_126909_Content_60 = {
    Text = "Ah-ah! Pazienza! Lasciatemi finire un pezzo alla volta."
  },
  AvgDialog_126909_Content_61 = {
    Text = "In molti desiderano tornare a casa, ma c'è un solo treno. Quindi, naturalmente... solo una persona potrà fare ritorno nell'amata terra natia~"
  },
  AvgDialog_126909_Content_62 = {
    Text = "Ahimè, da premurosa, altruista e caritatevole N quale sono, è ovvio che debba ricorrere al metodo più equo per decidere chi avrà tale privilegio, giusto?"
  },
  AvgDialog_126909_Content_63 = {Text = "Quindi..."},
  AvgDialog_126909_Content_64 = {
    Text = "<Big:Quindi, <Shake:<Red:iniziate ad ammazzarvi a vicenda>>!>"
  },
  AvgDialog_126909_Content_65 = {
    Text = "Uccidete tutti, chi sopravvive fino alla fine potrà decidere la destinazione di questo treno e ottenere la possibilità di una <Yellow:gita di un giorno in patria>!"
  },
  AvgDialog_126909_Content_66 = {
    Text = "Impossibile! Nessuno... nessuno toglierebbe davvero la vita a qualcuno per una cosa simile!"
  },
  AvgDialog_126909_Content_67 = {
    Text = "Esatto... Per quanto mi manchi Faint terribilmente, non potrei mai prendere parte a un gioco così crudele..."
  },
  AvgDialog_126909_Content_68 = {
    Text = "Hmph. Restare qui con vino pregiato e servitori non è poi una cattiva alternativa. Isarawu per me non è che un ricordo sbiadito, ormai."
  },
  AvgDialog_126909_Content_69 = {
    Text = "Per quanto mi piacerebbe tornare... il mio piccolo germoglio è qui con me, e il popolo di Aram non ha più bisogno della mia guida. Non ho alcun motivo per partecipare a un bagno di sangue."
  },
  AvgDialog_126909_Content_7 = {
    Text = "Allora non mi resta che... aspettare e vedere."
  },
  AvgDialog_126909_Content_70 = {
    Text = "Tutti gli occhi si volgono ora verso l'ultima persona."
  },
  AvgDialog_126909_Content_71 = {Text = "..."},
  AvgDialog_126909_Content_72 = {
    Text = "Gli sguardi non la turbano. Miryam resta in silenzio."
  },
  AvgDialog_126909_Content_73 = {
    Text = "Conosci la sua Ossessione; sai cosa significa \"Lemuria\" per lei."
  },
  AvgDialog_126909_Content_74 = {
    Text = "Sigh... sapevo che non sarebbe stato così facile..."
  },
  AvgDialog_126909_Content_75 = {
    Text = "Per evitare questa situazione di stallo imbarazzante, ho perfezionato le Regole: dovrete presentarmi cinque cadaveri in cambio del biglietto finale."
  },
  AvgDialog_126909_Content_76 = {
    Text = "Vi servono sette biglietti in totale per avviare il treno!"
  },
  AvgDialog_126909_Content_77 = {
    Text = "In altre parole, nessuno partirà finché non resterà una sola persona in vita."
  },
  AvgDialog_126909_Content_78 = {
    Text = "Inoltre, tra di voi c'è una <Yellow:spia> che ho piazzato io, creata da un alter ego del mio trasformista N!"
  },
  AvgDialog_126909_Content_79 = {
    Text = "Se non farete nulla, vi eliminerà uno a uno a uno! E poi? Nessuno tornerà a casa!"
  },
  AvgDialog_126909_Content_8 = {
    Text = "Senza tanti giri di parole, la piccola N vi porta subito <Shake:il nuovissimo e attesissimo <Red:teatro dell'Emulazione esclusivo della Festa di primavera>>!"
  },
  AvgDialog_126909_Content_81 = {
    Text = "Prima che la Piccola N possa finire, un viticcio trafigge all'improvviso la nebbia nera."
  },
  AvgDialog_126909_Content_82 = {
    Text = "Bene, tutti quanti. Smettetela di ascoltare le sue sciocchezze."
  },
  AvgDialog_126909_Content_83 = {
    Text = "Siamo in sei, e tra noi c'è il miglior Custode di Mythag. Credete davvero che non riusciamo a fuggire da questa minuscola carrozza?"
  },
  AvgDialog_126909_Content_9 = {
    Text = "Forza, pubblico! Fate un po' di rumore — è l'inizio dello spettacolo!"
  },
  AvgDialog_126910_Content_1 = {
    Text = "Seconda vittima"
  },
  AvgDialog_126910_Content_10 = {
    Text = "La priorità non dovrebbe essere trovare l'assassino tra noi?"
  },
  AvgDialog_126910_Content_11 = {
    Text = "Non sono d'accordo. Siamo rimasti in così pochi; rivoltarci gli uni contro gli altri non farà che giocare a favore dell'assassino."
  },
  AvgDialog_126910_Content_12 = {
    Text = "La cosa più importante è tenere al sicuro chi resta. Che ne dite se ci riunissimo tutti nella Carrozza 2?"
  },
  AvgDialog_126910_Content_13 = {
    Text = "Lanci un'occhiata al volto emaciato di Winkle e annuisci."
  },
  AvgDialog_126910_Content_14 = {
    Text = "Dato che il piccolo germoglio ha preso la sua decisione, non mi opporrò."
  },
  AvgDialog_126910_Content_15 = {
    Text = "...Secondo l'insegnamento del nostro Signore, devo cercare un angolo tranquillo per la preghiera solitaria a intervalli regolari."
  },
  AvgDialog_126910_Content_16 = {
    Text = "Neanche per sogno! Chi sa cosa potresti fare mentre \"preghi\"?"
  },
  AvgDialog_126910_Content_17 = {
    Text = "Inoltre, sei stata l'unica a restare in silenzio quando abbiamo concordato una tregua. Come facciamo a sapere che non sei una sottoposta di N?"
  },
  AvgDialog_126910_Content_18 = {
    Text = "L'unico Signore che servo è la divinità di Lemuria."
  },
  AvgDialog_126910_Content_19 = {
    Text = "Tuttavia, se oserai pronunciare un'altra parola blasfema, non esiterei a impartire la punizione divina per Suo conto."
  },
  AvgDialog_126910_Content_2 = {
    Text = "<Italic:Tre ore dopo, all'interno del vagone>"
  },
  AvgDialog_126910_Content_20 = {
    Text = "Vedendo che Miryam ha già estratto il suo pugnale, ti affretti a intervenire per mediare."
  },
  AvgDialog_126910_Content_21 = {
    Text = "Non abbiamo ancora prove contro nessuno. Quando Tintura... è morta, tutti dormivano."
  },
  AvgDialog_126910_Content_22 = {
    Text = "Inoltre, questa storia della \"talpa\" potrebbe essere solo un altro stratagemma di N per spingerci a massacrarci a vicenda."
  },
  AvgDialog_126910_Content_23 = {
    Text = "Che crudeltà! Sob... Ero così sincera nel mio avvertimento—"
  },
  AvgDialog_126910_Content_24 = {
    Text = "<LightGray:<Italic:(Sguardo assassino)...>>"
  },
  AvgDialog_126910_Content_25 = {
    Text = "Va bene, va bene! Sparisco! Uaaah..."
  },
  AvgDialog_126910_Content_26 = {
    Text = "PUF!—Il piccolo N svanisce nel nulla."
  },
  AvgDialog_126910_Content_27 = {
    Text = "In tal caso... Miryam, ti dispiacerebbe andare a pregare da sola nella Carrozza 1? Per favore, resta lì a meno che non si tratti di un'emergenza assoluta."
  },
  AvgDialog_126910_Content_28 = {
    Text = "Chiuderemo a chiave la porta di collegamento con la Carrozza 1. Con tutti noi riuniti in un'unica stanza, potremo garantire la sicurezza di tutti."
  },
  AvgDialog_126910_Content_29 = {
    Text = "Non è un po'... eccessivo per Miryam?"
  },
  AvgDialog_126910_Content_3 = {
    Text = "<Shake:<Italic: Glug, glug, glug—>>"
  },
  AvgDialog_126910_Content_30 = {
    Text = "Non ho obiezioni."
  },
  AvgDialog_126910_Content_31 = {
    Text = "Ignorando le tue proteste, Miryam si alza e lascia la Carrozza 2 senza esitazione, chiudendo con cura a chiave la porta di collegamento dietro di sé."
  },
  AvgDialog_126910_Content_32 = {
    Text = "Adesso il resto di noi dovrebbe poter respirare tranquillo, no?"
  },
  AvgDialog_126910_Content_33 = {
    Text = "Ho la sensazione che non sarà così semplice..."
  },
  AvgDialog_126910_Content_34 = {
    Text = "Un'ora dopo, all'interno del Vagone 2"
  },
  AvgDialog_126910_Content_35 = {Text = "Urgh..."},
  AvgDialog_126910_Content_36 = {
    Text = "Io... ho bisogno di un momento..."
  },
  AvgDialog_126910_Content_37 = {
    Text = "Winkle avanza barcollando verso il punto di giunzione tra le due carrozze."
  },
  AvgDialog_126910_Content_38 = {
    Text = "<LightGray:(Troppa caffeina, suppongo...)>"
  },
  AvgDialog_126910_Content_39 = {
    Text = "Un'ora dopo, all'interno del Vagone 2"
  },
  AvgDialog_126910_Content_4 = {
    Text = "Smettila di bere, ormai."
  },
  AvgDialog_126910_Content_40 = {
    Text = "<LightGray:(Strano... Winkle sta impiegando un tempo terribilmente lungo...)>"
  },
  AvgDialog_126910_Content_41 = {
    Text = "Preoccupato? Vuoi che ti accompagni a controllare come sta?"
  },
  AvgDialog_126910_Content_42 = {Text = "Andiamo."},
  AvgDialog_126910_Content_43 = {
    Text = "L'inquietudine si insinua nel tuo cuore. Passi vuoti echeggiano insieme alle ombre, riempiendo l'intera carrozza."
  },
  AvgDialog_126910_Content_44 = {
    Text = "Riconosci il nome di questo terrore—"
  },
  AvgDialog_126910_Content_45 = {Text = "Morte."},
  AvgDialog_126910_Content_46 = {
    Text = "Martelli sulla porta, gridando il nome di Winkle. Silenzio."
  },
  AvgDialog_126910_Content_47 = {
    Text = "Cominci a tentare di forzare la porta."
  },
  AvgDialog_126910_Content_48 = {
    Text = "Bang, bang, bang!"
  },
  AvgDialog_126910_Content_49 = {
    Text = "Che è successo?"
  },
  AvgDialog_126910_Content_5 = {
    Text = "<Shake:<Italic: Glug, glug, glug—>>"
  },
  AvgDialog_126910_Content_50 = {
    Text = "Anche Wanda è attirata dal rumore."
  },
  AvgDialog_126910_Content_51 = {
    Text = "Winkle è là dentro da un'ora. Abbiamo bussato, ma non c'è risposta."
  },
  AvgDialog_126910_Content_52 = {
    Text = "La porta non si muove. È assurdo! Abbiamo un gruppo di Risvegliati qui... persone capaci di evocare tempeste e combattere creature mitiche... eppure siamo sconfitti da una semplice porta?!"
  },
  AvgDialog_126910_Content_53 = {
    Text = "Hai mai sentito parlare dello <Italic:\"Shin Honkaku,\">— la Nuova Ortodossia del giallo deduttivo?"
  },
  AvgDialog_126910_Content_54 = {
    Text = "Per parlare di Shin Honkaku, bisogna prima rendere omaggio all'Ortodossia."
  },
  AvgDialog_126910_Content_56 = {
    Text = [[
Nel mondo del calcolo deduttivo, Honkaku indica un'opera con un enigma chiaramente definito e una logica rigorosa...
Lo Shin Honkaku prende quelle fondamenta e vi costruisce sopra una visione del mondo unica.]]
  },
  AvgDialog_126910_Content_57 = {
    Text = "Ciononostante, la Nuova Ortodossia deve rispettare il lettore e attenersi alle regole del \"Fair Play\". Il mistero deve essere risolvibile con le informazioni già fornite — niente elementi soprannaturali aggiunti a capriccio."
  },
  AvgDialog_126910_Content_58 = {
    Text = "In breve, se non possiedi abilità di scasso, non puoi aprire per magia una porta chiusa dall'interno."
  },
  AvgDialog_126910_Content_59 = {
    Text = "Little N rimbalza tra i portabagagli e si nasconde dietro i sedili, schivando spine e rampicanti mentre conclude la sua lezione."
  },
  AvgDialog_126910_Content_6 = {Text = "Winkle..."},
  AvgDialog_126910_Content_60 = {
    Text = "Quindi... stai dicendo che questo è un classico \"omicidio nella stanza chiusa\"? E la scena del crimine è proprio là dentro?"
  },
  AvgDialog_126910_Content_61 = {
    Text = "Chi lo sa! Forse Winkle è fuggito in preda ai sensi di colpa, gettandosi dalla finestra del bagno durante il transito!"
  },
  AvgDialog_126910_Content_62 = {
    Text = "Ma non avevi detto che non possiamo lasciare il treno?"
  },
  AvgDialog_126910_Content_63 = {
    Text = "Aha! Uno smarrimento nella logica!"
  },
  AvgDialog_126910_Content_64 = {
    Text = "Prima che il grande Detective faccia {Male=la sua,Female=la sua} entrata trionfale, deve sempre esserci la \"spalla sprovveduta\" che propone la teoria sbagliata."
  },
  AvgDialog_126910_Content_65 = {
    Text = "Dato che nessuno di voi è disposto a giocare il ruolo del buffone, io, il sempre magnanimo Little N, mi presterò graziosamente a salire sul palco!"
  },
  AvgDialog_126910_Content_66 = {
    Text = "Smettila di sprecare fiato con lui."
  },
  AvgDialog_126910_Content_67 = {
    Text = "È un po' rozzo, lo so... ma c'è una griglia a lamelle sulla porta del bagno. La struttura è piuttosto fragile."
  },
  AvgDialog_126910_Content_68 = {
    Text = "Wanda solleva le sue spine."
  },
  AvgDialog_126910_Content_69 = {
    Text = "Scrack, crac... le assi vengono divelte."
  },
  AvgDialog_126910_Content_7 = {
    Text = "Anche se vi annegaste nel caffè, non riporterebbe indietro Tintura, vero?"
  },
  AvgDialog_126910_Content_70 = {
    Text = "Lascia il resto a me."
  },
  AvgDialog_126910_Content_71 = {
    Text = "I rampicanti si insinuano attraverso l'apertura e fanno scattare il lucchetto. Spingi la porta per aprirla."
  },
  AvgDialog_126910_Content_72 = {
    Text = "Non c'è tempo."
  },
  AvgDialog_126910_Content_73 = {
    Text = "Winkle è rannicchiata in un angolo del bagno, in silenzio."
  },
  AvgDialog_126910_Content_74 = {Text = "Winkle!"},
  AvgDialog_126910_Content_75 = {
    Text = "Ti precipiti verso di lei, ma del sangue cremisi scuro le è già colato dall'angolo delle labbra. Non le resta più un filo di respiro."
  },
  AvgDialog_126910_Content_76 = {
    Text = "Per essere diretti: quando Winkle è morta, tu, Wanda e io non abbiamo mai lasciato il Vagone 2."
  },
  AvgDialog_126910_Content_77 = {
    Text = "L'unico possibile assassino... deve essere Miryam."
  },
  AvgDialog_126910_Content_78 = {
    Text = "Il mio Signore non mi ha guidato a compiere un simile atto. Ma se insisti, sono disposta a pronunciare il giudizio in Suo nome."
  },
  AvgDialog_126910_Content_79 = {
    Text = "Oh cielo, che bello stallo!"
  },
  AvgDialog_126910_Content_8 = {
    Text = "<Shake:Tu—!>"
  },
  AvgDialog_126910_Content_80 = {
    Text = "Dal momento che si parla del giudizio della Divinità, voglio darvi <Yellow:una possibilità di vincere facilmente>!"
  },
  AvgDialog_126910_Content_81 = {
    Text = "Votiamo subito! Chi riceverà più voti verrà espulso dal treno da me e perderà la possibilità di tornare a casa!"
  },
  AvgDialog_126910_Content_82 = {
    Text = "Senza alcun dubbio, il mio voto va a Miryam."
  },
  AvgDialog_126910_Content_83 = {Text = "Thais."},
  AvgDialog_126910_Content_84 = {
    Text = "Piccola, e tu? Date le prove circostanziali, anch'io sono propensa a votare per Miryam."
  },
  AvgDialog_126910_Content_85 = {
    Text = "Miryam: 2 voti! Thais: 1 voto!"
  },
  AvgDialog_126910_Content_86 = {
    Text = "N, cosa succede in caso di pareggio?"
  },
  AvgDialog_126910_Content_87 = {
    Text = "Se c'è un pareggio, nessuno viene eliminato~"
  },
  AvgDialog_126910_Content_88 = {
    Text = "Ma pensaci bene! Siete rimasti solo in quattro. Se lasci passare questa occasione e la talpa colpisce ancora, le tue probabilità di sopravvivenza crolleranno!"
  },
  AvgDialog_126910_Content_89 = {
    Text = "Non voglio condannare una persona innocente. Voto per Thais."
  },
  AvgDialog_126910_Content_9 = {
    Text = "Ha ragione. Trovare un modo per scendere da questo treno è la nostra priorità adesso."
  },
  AvgDialog_126910_Content_90 = {
    Text = "Davvero? Non vuoi ripensarci? Questa è la tua unica occasione per votare!"
  },
  AvgDialog_126910_Content_91 = {
    Text = "No. Più insisti, più sono certa di aver fatto la scelta giusta."
  },
  AvgDialog_126910_Content_92 = {
    Text = "Molto bene! Conteggio finale: pareggio. Nessuno è eliminato!"
  },
  AvgDialog_126910_Content_93 = {
    Text = "Sigh... Che delusione. Anche la Piccola N ha bisogno di un po' di tempo da sola per riprendersi. Ci si vede!"
  },
  AvgDialog_126911_Content_1 = {
    Text = "Che il gioco abbia inizio"
  },
  AvgDialog_126911_Content_10 = {
    Text = "Continua a parlare, e non mi dispiacerà farti assaggiare di nuovo cosa si prova con un cuore trafitto."
  },
  AvgDialog_126911_Content_11 = {
    Text = "Wanda giocherella pigramente con gli spuntoni affilati sulle sue dita."
  },
  AvgDialog_126911_Content_12 = {
    Text = "Ohhh, che crudeltà! Davvero straziante!"
  },
  AvgDialog_126911_Content_13 = {
    Text = "Lo spettacolo della Festa di primavera che la piccola N ha preparato con cura è davvero così impopolare? <Shake:Uh uh……>"
  },
  AvgDialog_126911_Content_14 = {
    Text = "I singhiozzi finti durarono meno di un secondo prima che un sorriso radioso sbocciasse di nuovo sul suo volto."
  },
  AvgDialog_126911_Content_15 = {
    Text = "Comunque... buona caccia! Il Piccolo N non vede l'ora di assistere alle vostre esibizioni!"
  },
  AvgDialog_126911_Content_16 = {
    Text = "Whoosh! In un battito di ciglia, la Piccola N svanisce di nuovo.\nIl silenzio torna sul treno — teso e soffocante."
  },
  AvgDialog_126911_Content_17 = {
    Text = "Segue una lunga pausa. L'oscurità sui binari davanti a loro sembra non avere fine."
  },
  AvgDialog_126911_Content_18 = {
    Text = "Quanto ancora correrà questo treno? Dove è diretto?"
  },
  AvgDialog_126911_Content_19 = {
    Text = "Alcuni non hanno risposta; altri ne custodiscono una che non osano pronunciare ad alta voce."
  },
  AvgDialog_126911_Content_2 = {
    Text = "...Non riesco a uscire."
  },
  AvgDialog_126911_Content_20 = {
    Text = "Ehm... tutti...?"
  },
  AvgDialog_126911_Content_21 = {
    Text = "Una voce limpida e piacevole spezza la quiete."
  },
  AvgDialog_126911_Content_22 = {
    Text = "È un po' noioso starsene qui seduti... Se non vi dispiace, posso cantarvi una canzone?"
  },
  AvgDialog_126911_Content_23 = {
    Text = "Ooh?! Adoro gli spettacoli! Posso chiedere una canzone?"
  },
  AvgDialog_126911_Content_24 = {
    Text = "Via, via! Nessuno ti ha chiesto nulla!"
  },
  AvgDialog_126911_Content_25 = {
    Text = "Dato che è la Festa di Primavera dell'Impero Panlong... ricordo un motivo popolare orientale. Una volta ho sentito il Coro delle Ombre eseguirlo."
  },
  AvgDialog_126911_Content_26 = {
    Text = "Non sono sicura di conoscere abbastanza brani orientali..."
  },
  AvgDialog_126911_Content_27 = {
    Text = "La canzone si chiama \"Mo Li Hua\", <Italic:il Fiore di Gelsomino>."
  },
  AvgDialog_126911_Content_28 = {
    Text = "Oh? Quella lì?"
  },
  AvgDialog_126911_Content_29 = {
    Text = "Che coincidenza. Anch'io ero tra il pubblico a quella esibizione del Coro delle Ombre."
  },
  AvgDialog_126911_Content_3 = {
    Text = "Winkle mormora la conclusione con disperazione."
  },
  AvgDialog_126911_Content_30 = {
    Text = "Se ricordo bene, ho persino notato..."
  },
  AvgDialog_126911_Content_31 = {
    Text = "Gli occhi di Wanda si fissano su Miryam, che annuisce semplicemente in silenzio."
  },
  AvgDialog_126911_Content_32 = {
    Text = "Bene... se nessuno ha obiezioni... comincerò."
  },
  AvgDialog_126911_Content_33 = {
    Text = "Tintura si schiarisce la voce sommessamente."
  },
  AvgDialog_126911_Content_34 = {
    Text = "<Shake:Che bel fiore di gelsomino~ Che bel fiore di gelsomino♪~ Nessun bocciolo nel giardino può competere con lei♪~>"
  },
  AvgDialog_126911_Content_35 = {
    Text = "<Shake:La la la~ La la la~ La la la♪~>"
  },
  AvgDialog_126911_Content_36 = {
    Text = "La sua voce eterea riecheggia attraverso la carrozza vuota."
  },
  AvgDialog_126911_Content_37 = {
    Text = "Sotto il canto rassicurante, la tensione nella tua mente inizia ad allentarsi. Senti un'ondata di sonnolenza travolgerti."
  },
  AvgDialog_126911_Content_38 = {
    Text = "Sono tutti esausti, vero? Io sono abituata a stare senza dormire—farò la guardia."
  },
  AvgDialog_126911_Content_39 = {
    Text = "Annuisci, poi sprofondi nel tanto atteso abbraccio del sonno."
  },
  AvgDialog_126911_Content_4 = {
    Text = "A parte la cabina del Conducente, questo treno ha tre carrozze in tutto. Noi siamo nella Carrozza 2, quella centrale."
  },
  AvgDialog_126911_Content_40 = {Text = "..."},
  AvgDialog_126911_Content_41 = {
    Text = "Dopo un lungo momento, Tintura termina la sua canzone."
  },
  AvgDialog_126911_Content_42 = {
    Text = "Ora dormono tutti. Perché non ti riposi anche tu?"
  },
  AvgDialog_126911_Content_43 = {
    Text = "Sei sicura che vada bene?"
  },
  AvgDialog_126911_Content_44 = {
    Text = "Cosa, temi che io possa essere la talpa?"
  },
  AvgDialog_126911_Content_45 = {
    Text = "Per niente. È solo che... a quei tempi, aspettavo sempre che Faint si addormentasse prima di riposarmi..."
  },
  AvgDialog_126911_Content_46 = {
    Text = "Allora oggi tocca a te dormire come si deve! Vai."
  },
  AvgDialog_126911_Content_47 = {
    Text = "Dietro l'insistenza di Winkle, Tintura prende una coperta, si appoggia allo schienale e chiude gli occhi."
  },
  AvgDialog_126911_Content_48 = {
    Text = "Non c'è da stupirsi che si siano addormentati tutti così in fretta... È un'atmosfera così tranquilla..."
  },
  AvgDialog_126911_Content_49 = {Text = "..."},
  AvgDialog_126911_Content_5 = {
    Text = "Le carrozze 1 e 3 sono vuote. Ogni finestra e porta è sigillata ermeticamente: né la forza bruta né la Tecnologia d'Argento riescono ad aprirle."
  },
  AvgDialog_126911_Content_50 = {Text = "..."},
  AvgDialog_126911_Content_51 = {Text = "...Hmm?"},
  AvgDialog_126911_Content_52 = {
    Text = "La prima cosa che vedi è il volto sereno e addormentato di Winkle."
  },
  AvgDialog_126911_Content_53 = {
    Text = "A un certo punto, le luci sono state spente. L'Oscurità riempie la carrozza, fatta eccezione per un tenue bagliore che filtra dal corridoio di collegamento."
  },
  AvgDialog_126911_Content_54 = {
    Text = "Winkle... perché ti sei addormentata?"
  },
  AvgDialog_126911_Content_55 = {
    Text = "Winkle emette un lieve sospiro."
  },
  AvgDialog_126911_Content_56 = {
    Text = "Eh...? Mi... sono addormentata?"
  },
  AvgDialog_126911_Content_57 = {
    Text = "EHHH?!?! MI SONO ADDORMENTATA?!?!"
  },
  AvgDialog_126911_Content_58 = {
    Text = "Il suo Grido di panico squarcia la notte come una tempesta, strappando gli altri dal sonno."
  },
  AvgDialog_126911_Content_59 = {
    Text = "Le luci si riaccendono di colpo, inondando l'intera carrozza di una luce cruda e abbagliante."
  },
  AvgDialog_126911_Content_6 = {
    Text = "Ve l'avevo detto! Inutile sprecare energie! Nessuno scende finché non resta un solo vincitore!"
  },
  AvgDialog_126911_Content_60 = {
    Text = "Cari passeggeri, avete riposato bene sul Focolare Express?"
  },
  AvgDialog_126911_Content_61 = {
    Text = "Non appena ho rilevato che tutti i passeggeri dormivano, ho gentilmente predisposto un ambiente silenzioso e buio per voi!"
  },
  AvgDialog_126911_Content_62 = {
    Text = "Mi dispiace tanto... di solito mi affido a enormi quantità di caffè per restare sveglia..."
  },
  AvgDialog_126911_Content_63 = {
    Text = "Aspettate. Manca qualcuno?"
  },
  AvgDialog_126911_Content_64 = {Text = "..."},
  AvgDialog_126911_Content_65 = {
    Text = "Hmm? Mi stai cercando, piccolo germoglio? Sono proprio qui."
  },
  AvgDialog_126911_Content_66 = {
    Text = "Allora la persona mancante è..."
  },
  AvgDialog_126911_Content_67 = {
    Text = "Tutti si voltano verso il fondo della carrozza—"
  },
  AvgDialog_126911_Content_68 = {
    Text = "La gola di Tintura è stata trapassata da qualcosa di affilato. Il Sangue scorre lungo il suo collo aggraziato, tingendo il suo Vestito di Cremisi."
  },
  AvgDialog_126911_Content_69 = {
    Text = "L'usignolo macchiato di sangue non avrebbe mai più cantato."
  },
  AvgDialog_126911_Content_7 = {
    Text = "Come hai...? Thais non aveva appena...?"
  },
  AvgDialog_126911_Content_70 = {
    Text = "<Shake:AAAAAAH—!!!>"
  },
  AvgDialog_126911_Content_71 = {
    Text = "Winkle emette uno Strido—un suono capace di frantumare il vetro—poi scivola lungo il muro in un angolo, le braccia strette attorno a sé, tremando in modo incontrollabile."
  },
  AvgDialog_126911_Content_72 = {
    Text = "<Shake:Mi dispiace... Non avrei dovuto essere così sicura di me... Non avrei dovuto fare la guardia da sola... Non avrei dovuto pensare di riuscire a restare sveglia senza caffè...>"
  },
  AvgDialog_126911_Content_73 = {
    Text = "Si morde le unghie freneticamente; le lacrime sgorgano copiose, gocciolando sul tappeto."
  },
  AvgDialog_126911_Content_74 = {
    Text = "Ta-da! Cos'ha sentito la premurosa Piccola N? <Shake:Il bisogno di un passeggero!>"
  },
  AvgDialog_126911_Content_75 = {
    Text = "Un servizio dal cuore, in arrivo — una <Yellow:macchina del caffè illimitata!>"
  },
  AvgDialog_126911_Content_76 = {
    Text = "Basta premere questo pulsante rosso, e fiumi inesauribili di Americano scuro e bollente sgorgheranno a fiotti!"
  },
  AvgDialog_126911_Content_77 = {
    Text = "Avanzi in silenzio e alzi la mano—"
  },
  AvgDialog_126911_Content_78 = {
    Text = "Poi schiacci la fastidiosa Piccola N？ con un colpo secco."
  },
  AvgDialog_126911_Content_79 = {
    Text = "<Shake:Mi dispiace... mi dispiace tanto, tanto...>"
  },
  AvgDialog_126911_Content_8 = {
    Text = "Hehe! Se fosse così facile uccidermi, non sarei il Piccolo N, no?"
  },
  AvgDialog_126911_Content_80 = {
    Text = "I singhiozzi spezzati di Winkle echeggiano nella carrozza."
  },
  AvgDialog_126911_Content_81 = {
    Text = "Per quanto vi opponiate, con la morte di Tintura come atto d'apertura—"
  },
  AvgDialog_126911_Content_82 = {
    Text = "Il gioco della morte... è iniziato."
  },
  AvgDialog_126911_Content_9 = {
    Text = "Allora? Avete tutti scelto il vostro bersaglio per la notte?"
  },
  AvgDialog_126912_Content_1 = {
    Text = "L'Uccisione Silenziosa"
  },
  AvgDialog_126912_Content_10 = {
    Text = "Per qualche ragione, avverti qualcosa di celato dietro quel sorriso—un'emozione che non hai ancora afferrato."
  },
  AvgDialog_126912_Content_11 = {
    Text = "Andiamo, Miryam. Alla Carrozza 1."
  },
  AvgDialog_126912_Content_12 = {
    Text = "Proprio mentre la porta di collegamento inizia a chiudersi, Wanda si ferma e si volta a guardare oltre la spalla."
  },
  AvgDialog_126912_Content_13 = {
    Text = "Buona Festa di Primavera, %player%."
  },
  AvgDialog_126912_Content_14 = {Text = "..."},
  AvgDialog_126912_Content_15 = {Text = "Vagone 2"},
  AvgDialog_126912_Content_16 = {
    Text = "Con Wanda e Miryam andate via, solo tu e Thais rimanete nella carrozza."
  },
  AvgDialog_126912_Content_17 = {
    Text = "Bene allora, dato che finalmente abbiamo un po' di tempo prezioso da soli, che facciamo, mio piccolo germoglio?"
  },
  AvgDialog_126912_Content_18 = {
    Text = "Thais si avvicina d'improvviso con un luccichio malizioso. Spaventato, ti ritrai di scatto, mantenendo una distanza di sicurezza."
  },
  AvgDialog_126912_Content_19 = {
    Text = "Potrei... lavorare al mio rapporto..."
  },
  AvgDialog_126912_Content_2 = {Text = "Vagone 2"},
  AvgDialog_126912_Content_20 = {
    Text = "È già la Festa di Primavera! Rilassati un po'—smettila di ossessionarti con quei rapporti."
  },
  AvgDialog_126912_Content_21 = {
    Text = "Il suo braccio dal tono ambrato si posa dolcemente sulla tua spalla. Il suo respiro, caldo e intimo, ti avvolge come una <Italic:Foschia Notturna.>"
  },
  AvgDialog_126912_Content_22 = {Text = "Questo..."},
  AvgDialog_126912_Content_23 = {
    Text = "In quell'istante, visioni balenano davanti ai tuoi occhi: il volto severo di Doll, i sospiri di Ramona e la bacchetta di Czort."
  },
  AvgDialog_126912_Content_24 = {
    Text = "Meglio di no..."
  },
  AvgDialog_126912_Content_25 = {
    Text = "Abbozzi un sorriso imbarazzato e scivoli via con discrezione dalla sua portata."
  },
  AvgDialog_126912_Content_26 = {
    Text = "Va bene. Allora sediamoci in silenzio e chiacchieriamo un po', che ne dici?"
  },
  AvgDialog_126912_Content_27 = {
    Text = "Dimmi, Custode... in quell'istante in cui i tuoi occhi sono sfuggiti via—a chi stavi pensando?"
  },
  AvgDialog_126912_Content_28 = {Text = "..."},
  AvgDialog_126912_Content_29 = {Text = "..."},
  AvgDialog_126912_Content_3 = {
    Text = "Nel rombo del treno, Wanda è la prima a rompere il silenzio."
  },
  AvgDialog_126912_Content_30 = {
    Text = "Non ricordi da quanto tempo stai parlando—solo che ogni memoria ti torna alla mente con vivida chiarezza."
  },
  AvgDialog_126912_Content_31 = {
    Text = "E la mensa al Mythag? Molto più affollata di qualsiasi laboratorio."
  },
  AvgDialog_126912_Content_32 = {
    Text = "Soprattutto quando quelle tortine sono disponibili... i ragazzi dimenticano ogni grazia e buona maniera..."
  },
  AvgDialog_126912_Content_33 = {
    Text = "Alcuni sfacciati barano persino—fanno tenere il posto al contatore dai loro compagni animali con un buono pasto, poi danno le tortine che arraffano ai loro amici più timidi."
  },
  AvgDialog_126912_Content_34 = {
    Text = "<Shake:E... eh?>"
  },
  AvgDialog_126912_Content_35 = {
    Text = "Ti accorgi che la voce ti si spezza in gola. Le lacrime iniziano a scorrere sulle tue guance senza controllo."
  },
  AvgDialog_126912_Content_36 = {
    Text = "C'è dell'altro..."
  },
  AvgDialog_126912_Content_37 = {
    Text = "Le lacrime affiorano, offuscandoti la vista."
  },
  AvgDialog_126912_Content_38 = {
    Text = "<Shake:Mi manca così tanto il Mythag. Voglio tornare... tornare al loro fianco...>"
  },
  AvgDialog_126912_Content_39 = {
    Text = "È strano... sono partito solo <Yellow:tre giorni fa> per il lavoro sul campo. Non dovrei sentirmi così..."
  },
  AvgDialog_126912_Content_4 = {
    Text = "Ho una proposta."
  },
  AvgDialog_126912_Content_40 = {
    Text = "Ma il dolore della nostalgia ti brucia il naso, e una tensione dentro di te sembra sul punto di spezzarsi."
  },
  AvgDialog_126912_Content_41 = {
    Text = "Shh... Va tutto bene, Custode. Va tutto bene."
  },
  AvgDialog_126912_Content_42 = {
    Text = "Sprofondi in un Abbraccio morbido. L'Abbraccio di una Madre."
  },
  AvgDialog_126912_Content_43 = {
    Text = "@1 ti prometto, tornerai nel luogo che ti manca così tanto."
  },
  AvgDialog_126912_Content_44 = {
    Text = "I lineamenti di Thais cominciano a sfumare."
  },
  AvgDialog_126912_Content_45 = {
    Text = "Una nebbia gentile vi avvolge entrambi, e tu ti rannicchi in silenzio tra le sue braccia, sentendoti piccolo — così incredibilmente piccolo."
  },
  AvgDialog_126912_Content_46 = {
    Text = "Avverti un profumo. La fragranza delle <Yellow:magnolie.>"
  },
  AvgDialog_126912_Content_47 = {
    Text = "<Red:Grandi magnolie in fiore.>"
  },
  AvgDialog_126912_Content_48 = {
    Text = "Avvolta in quella ricca fragranza, scivoli in un sonno profondo e sereno. È un sonno da neonato che lava via ogni preoccupazione e paura."
  },
  AvgDialog_126912_Content_49 = {
    Text = "Prima che la coscienza svanisca, l'ultima cosa che ricordi è <Yellow:un paio di occhi dorati> — gli occhi incantevoli e amorevoli di una madre."
  },
  AvgDialog_126912_Content_5 = {
    Text = "Possiamo dividerci in coppie e restare nei Vagoni 1 e 2 separatamente. Così potremo tenerci d'occhio a vicenda."
  },
  AvgDialog_126912_Content_50 = {Text = "..."},
  AvgDialog_126912_Content_51 = {Text = "Finché—"},
  AvgDialog_126912_Content_52 = {
    Text = "Un forte SCHIANTO esplode dalla Carrozza 1."
  },
  AvgDialog_126912_Content_53 = {
    Text = "In quell'istante, lo sai: il gioco mortale non è finito. È ora di svegliarsi."
  },
  AvgDialog_126912_Content_54 = {Text = "Carrozza 1"},
  AvgDialog_126912_Content_55 = {
    Text = "All'interno della Carrozza 1, Wanda e Miryam giacciono aggrovigliate, gravemente ferite. Un pugnale è conficcato nel petto di Wanda; Miryam è trafitta da innumerevoli spine."
  },
  AvgDialog_126912_Content_56 = {
    Text = "Gli occhi di Wanda si socchiudono appena, la sua voce roca e sempre più flebile."
  },
  AvgDialog_126912_Content_57 = {
    Text = "Lo sapevo... che Miryam avrebbe colpito per prima... così ho preparato... il mio \"contatore\"..."
  },
  AvgDialog_126912_Content_58 = {
    Text = "Ora... N non potrà mai ottenere la sua vittoria..."
  },
  AvgDialog_126912_Content_59 = {
    Text = "Voi due... dovete..."
  },
  AvgDialog_126912_Content_6 = {
    Text = "Ma chi resta da solo con l'assassino non sarebbe in grave pericolo?"
  },
  AvgDialog_126912_Content_60 = {
    Text = "La sua voce si spegne. La sua ultima benedizione si dissolve nel silenzio."
  },
  AvgDialog_126912_Content_61 = {
    Text = "Dopo una lunga, greve pausa, Thais finalmente parla, con la voce tremante."
  },
  AvgDialog_126912_Content_62 = {
    Text = "Quindi... Miryam era davvero l'assassina. Sapeva che sotto la regola della sorveglianza reciproca, doveva eliminare Wanda per prima — altrimenti le sue azioni successive avrebbero unito tutti gli altri contro di lei. Così ha fatto la sua mossa."
  },
  AvgDialog_126912_Content_63 = {
    Text = "Wanda... sapeva di essere brava nel \"contatore\", così si è offerta volontaria per restare sola con la talpa, Miryam."
  },
  AvgDialog_126912_Content_64 = {
    Text = "Si è sacrificata... per assicurare la vittoria agli \"innocenti.\""
  },
  AvgDialog_126912_Content_65 = {
    Text = "Il suo tono è grave, con una traccia di rispetto. Se solo quel rispetto fosse sincero..."
  },
  AvgDialog_126912_Content_66 = {
    Text = "<Italic:Ma non lo è.>"
  },
  AvgDialog_126912_Content_67 = {
    Text = "No... Miryam non era la talpa che N aveva infiltrato tra noi."
  },
  AvgDialog_126912_Content_68 = {
    Text = "<Shake:Non lei? E allora perché...?>"
  },
  AvgDialog_126912_Content_69 = {
    Text = "La Miryam che conosco non esiterebbe a sporcarsi le mani per la vittoria... per il ritorno a \"Lemuria\", come promesso da N."
  },
  AvgDialog_126912_Content_7 = {
    Text = "Forse, ma è l'unico modo per assicurarci che N non ottenga la vittoria definitiva."
  },
  AvgDialog_126912_Content_70 = {
    Text = "Allora... perché tu..."
  },
  AvgDialog_126912_Content_71 = {
    Text = "Ma la vera talpa... sei tu. \"Thais\" — o meglio, <Yellow:chiunque stia impersonando lei.>"
  },
  AvgDialog_126912_Content_72 = {
    Text = "Forse la tua preparazione è stata sufficiente; Thais mostra poca sorpresa. Si limita a fissarti negli occhi con un sorriso calmo e consapevole."
  },
  AvgDialog_126912_Content_73 = {
    Text = "Oh? E quando l'hai capito, <ItalicYellow:mio Piccolo Gelsomino>? Mi piacerebbe sentire il tuo calcolo deduttivo."
  },
  AvgDialog_126912_Content_74 = {
    Text = "Dopo che Winkle se n'è andato... prima che Wanda suggerisse di spostarci in carrozze diverse."
  },
  AvgDialog_126912_Content_75 = {
    Text = "Così presto? Credevo che il mio modus operandi fosse abbastanza discreto da non lasciare tracce."
  },
  AvgDialog_126912_Content_76 = {
    Text = "Le ferite perforanti di Tintura potrebbero essere state causate dai tuoi rampicanti, dalle spine di Wanda o dal pugnale di Miryam."
  },
  AvgDialog_126912_Content_77 = {
    Text = "Quanto alla morte di Winkle... ognuna di voi tre—Thais, Wanda o Miryam—è in grado di usare il veleno."
  },
  AvgDialog_126912_Content_78 = {
    Text = "Considerando quanto caffè beveva, avvelenare la macchina del caffè avrebbe garantito la sua morte, prima o poi."
  },
  AvgDialog_126912_Content_79 = {
    Text = "Quindi, sì. In termini di esecuzione, il tuo travestimento era perfetto."
  },
  AvgDialog_126912_Content_8 = {
    Text = "Terrò d'occhio Miryam. Non preoccuparti: ho un asso nella manica che non si aspetterebbe mai."
  },
  AvgDialog_126912_Content_80 = {
    Text = "Allora cos'è che mi ha tradito?"
  },
  AvgDialog_126912_Content_81 = {
    Text = "Hai mai giocato a un gioco di società chiamato \"Lupo Mannaro\"? A ogni luna di sangue, i lupi mannari aprono gli occhi per cacciare, poi all'alba si nascondono tra gli abitanti del villaggio."
  },
  AvgDialog_126912_Content_82 = {
    Text = "Per identificare il lupo mannaro, devi scoprire le vere motivazioni di tutti durante la fase di discussione. I lupi mannari sanno chi sono gli innocenti, perciò le loro accuse tendono a essere più sicure."
  },
  AvgDialog_126912_Content_83 = {
    Text = "Ma la vera Thais, la regina capace di restare sotto copertura ad Aram per un millennio, non punterebbe mai il dito della diffidenza contro gli altri con tanta facilità. È cauta, ponderata."
  },
  AvgDialog_126912_Content_84 = {
    Text = "Ecco perché hai votato per me... invece di seguire gli altri contro Miryam."
  },
  AvgDialog_126912_Content_85 = {
    Text = "Ho scelto di restare da sola con l'assassino."
  },
  AvgDialog_126912_Content_86 = {
    Text = "Avevo pianificato di coglierti in flagrante quando avessi agito, ma Miryam si è mossa prima di te."
  },
  AvgDialog_126912_Content_87 = {
    Text = "Ha colpito Wanda prima che tu potessi finire di ipnotizzarmi."
  },
  AvgDialog_126912_Content_88 = {
    Text = "Bravo. Calcolo deduttivo davvero brillante. Mi hai impressionata."
  },
  AvgDialog_126912_Content_89 = {
    Text = "No... Non basta. Non ho mai avuto intenzione di fare il \"detective\" nella piccola storia di N."
  },
  AvgDialog_126912_Content_9 = {
    Text = "Wanda socchiude gli occhi, offrendo un sorriso rassicurante."
  },
  AvgDialog_126912_Content_90 = {
    Text = "Volevo fermare i tuoi piani prima che avvenisse qualsiasi omicidio. Ma ormai è troppo tardi."
  },
  AvgDialog_126912_Content_91 = {
    Text = "Ora, tutto ciò che chiedo è questo: chi sei davvero?"
  },
  AvgDialog_126912_Content_92 = {
    Text = "Una luce argentea erutta dalla Chiave d'Argento sul tuo petto, come a voler perforare ogni illusione e travestimento."
  },
  AvgDialog_126912_Content_93 = {
    Text = "Hehe... hehehe~"
  },
  AvgDialog_126912_Content_94 = {
    Text = "Il tuo Attacco sembra Colpire soltanto l'aria."
  },
  AvgDialog_126912_Content_95 = {
    Text = "Si dissolve in un filo di fumo, un velo di nebbia, una presenza intangibile e senza nome."
  },
  AvgDialog_126912_Content_96 = {
    Text = "Seguimi, <Italic:mio Piccolo Gelsomino...>"
  },
  AvgDialog_126912_Content_97 = {
    Text = "La nebbia ridacchia, la sua voce grondante di fascino enigmatico."
  },
  AvgDialog_126912_Content_98 = {
    Text = "Vieni con me, e scopri la verità dietro questa storia."
  },
  AvgDialog_128696_Content_1 = {
    Text = "BANG! BANG! BANG!"
  },
  AvgDialog_128696_Content_10 = {Text = "Nautila!"},
  AvgDialog_128696_Content_11 = {
    Text = "Vortice accorre in preda al panico, premendo l'orecchio sul petto di Nautila — solo per scoprire che Nautila è semplicemente svenuta per il puro esaurimento."
  },
  AvgDialog_128696_Content_12 = {
    Text = "Vortice tira un sospiro di sollievo, poi scoppia a ridere."
  },
  AvgDialog_128696_Content_13 = {
    Text = "Pfft—hahahahaha!"
  },
  AvgDialog_128696_Content_14 = {
    Text = "Porta Nautila a letto, poi ti afferra e, ignorando completamente le tue proteste, rotola gioiosamente sul pavimento con te diverse volte."
  },
  AvgDialog_128696_Content_15 = {
    Text = "Fuga, noi, non separati!"
  },
  AvgDialog_128696_Content_16 = {
    Text = "È la prima volta che Vortice è così rilassata da quel giorno. I suoi occhi brillano di speranza, il naso che si strofina felice nel soffice pelo sul tuo petto."
  },
  AvgDialog_128696_Content_17 = {
    Text = "Dormire… solo un po'… domani mattina… domani mattina…"
  },
  AvgDialog_128696_Content_18 = {
    Text = "Sveglia da giorni, Vortice ti stringe forte, appoggiata all'angolo del letto di Nautila, e sprofonda in un sonno profondo."
  },
  AvgDialog_128696_Content_19 = {Text = "..."},
  AvgDialog_128696_Content_2 = {
    Text = "ROAR—ROARROAR—ROAR!"
  },
  AvgDialog_128696_Content_20 = {
    Text = "@2, Vortice, @4..."
  },
  AvgDialog_128696_Content_21 = {
    Text = "@4... è qui..."
  },
  AvgDialog_128696_Content_22 = {Text = "..."},
  AvgDialog_128696_Content_23 = {
    Text = "La nave naviga da appena mezza giornata quando, senza alcun preavviso, una tempesta devastante si abbatte su di loro."
  },
  AvgDialog_128696_Content_24 = {
    Text = "La rotta è completamente perduta. La pioggia sferza da ogni lato, senza concedere alcuna ritirata a questi sfidanti troppo sicuri di sé."
  },
  AvgDialog_128696_Content_25 = {
    Text = "Il timone resta sinistrosamente bloccato, deviando ostinatamente verso il vortice. Qualunque cosa Nautila e Vortice tentino, arrivando quasi a romperlo, si rifiuta di girare."
  },
  AvgDialog_128696_Content_26 = {
    Text = "Com'è possibile, non dovrebbe essere così! Nessun segnale d'avvertimento, la pressione atmosferica era del tutto normale… non c'era alcun problema fino a quando non ci siamo avvicinati a queste acque."
  },
  AvgDialog_128696_Content_27 = {
    Text = "È solo che... È come se questo vortice avesse evocato la tempesta appositamente per tenderci una trappola."
  },
  AvgDialog_128696_Content_28 = {
    Text = "Una Trappola?"
  },
  AvgDialog_128696_Content_29 = {
    Text = "E deve succedere proprio quando siamo più vicini al vortice. Se fossimo anche solo cinque—no, anche solo tre miglia nautiche più al largo, saremmo del tutto fuori dalla sua presa."
  },
  AvgDialog_128696_Content_3 = {
    Text = "Il colosso di ferro dormiente emise un ruggito rauco. Il fischio a vapore risuona e, tra il battito d'ali dei gabbiani, l'intera nave sembra lentamente prendere vita."
  },
  AvgDialog_128696_Content_30 = {
    Text = "Il tuo cervello è un caos, e stai cercando disperatamente di gridare—ma cosa stai cercando di dire...?"
  },
  AvgDialog_128696_Content_31 = {
    Text = "SQUEAK, SQUEEEAKKK!"
  },
  AvgDialog_128696_Content_32 = {
    Text = "Riesci solo a emettere uno strido impotente. Non capisci—non lo sentono anche loro?"
  },
  AvgDialog_128696_Content_33 = {
    Text = "(Non avvicinarti al vortice, Grandicella, non andarci vicino!)"
  },
  AvgDialog_128696_Content_34 = {
    Text = "Quella presenza immensa, terrificante—Ha visto Vortice."
  },
  AvgDialog_128696_Content_35 = {
    Text = "<Red:Non ha alcuna intenzione di lasciar andare nessuno.>"
  },
  AvgDialog_128696_Content_36 = {Text = "..."},
  AvgDialog_128696_Content_37 = {
    Text = "Tutto bene, Coalsie, Vortice, è qui."
  },
  AvgDialog_128696_Content_38 = {
    Text = "Sì, fidatevi di me, Carboncina, Vortice. C'è ancora una via d'uscita, troverò qualcosa!"
  },
  AvgDialog_128696_Content_39 = {Text = "Nautila..."},
  AvgDialog_128696_Content_4 = {
    Text = "Il motore. Ultimo passo..."
  },
  AvgDialog_128696_Content_40 = {
    Text = "Sono stata io a insistere per spiegare le vele. Sono stata io a portarvi qui. Troverò qualcosa. Vi porterò entrambe in salvo!"
  },
  AvgDialog_128696_Content_41 = {
    Text = "<Change>Sfondare lo scafo qui e far entrare acqua come zavorra..."
  },
  AvgDialog_128696_Content_42 = {
    Text = "<Change>Non si può… @2la propulsione, sì, se, Purché si sovraccarichi uno dei motori, sfuggire alla forza d'attrazione di @1"
  },
  AvgDialog_128696_Content_43 = {
    Text = "La bambina trascina te e Vortice attraverso i compartimenti, tentando di tutto mentre il bianco dei suoi occhi comincia a sanguinare di un rosso frenetico."
  },
  AvgDialog_128696_Content_44 = {
    Text = "Clang—Bang!"
  },
  AvgDialog_128696_Content_45 = {Text = "Nautila..."},
  AvgDialog_128696_Content_46 = {
    Text = "La chiave inglese le scivola dalla presa esausta, colpisce la parete, poi si schianta con forza sul piede di Nautila. Eppure, come se non provasse alcun dolore, si china stordita per raccoglierla di nuovo."
  },
  AvgDialog_128696_Content_47 = {
    Text = "<Change>È troppo tardi, il vortice si avvicina... Perché, perché, perché, PERCHÉ!! Devo salvarvi entrambe, devo... devo...!"
  },
  AvgDialog_128696_Content_48 = {
    Text = "Crack—Boom—!"
  },
  AvgDialog_128696_Content_49 = {
    Text = "La tempesta e i colpi incessanti spingono infine la cabina oltre i suoi limiti. Con uno schianto secco, un'asse marcita precipita dall'alto, diretta contro Nautila—"
  },
  AvgDialog_128696_Content_5 = {
    Text = "Bene! Vortice, Coalsie, ce l'abbiamo fatta!"
  },
  AvgDialog_128696_Content_50 = {
    Text = "<Big:Nautila! Fermati!>"
  },
  AvgDialog_128696_Content_51 = {
    Text = "Quando Nautila apre gli occhi—occhi che aveva serrato per il terrore—vede qualcosa che non si sarebbe mai aspettata."
  },
  AvgDialog_128696_Content_52 = {
    Text = "Vortice si è puntellata contro la parete con un braccio, facendo scudo a Nautila sotto di sé, mentre con l'altra mano sorregge l'intero soffitto."
  },
  AvgDialog_128696_Content_53 = {Text = "Ugh..."},
  AvgDialog_128696_Content_54 = {Text = "Ha!"},
  AvgDialog_128696_Content_55 = {
    Text = "Con una poderosa spinta, Vortice scaglia via il soffitto, poi afferra Nautila quasi in delirio e le prende il viso tra le mani, costringendo i loro occhi a incontrarsi."
  },
  AvgDialog_128696_Content_56 = {
    Text = "Va bene, torniamo, la prossima volta."
  },
  AvgDialog_128696_Content_57 = {
    Text = "Tornare... Ma..."
  },
  AvgDialog_128696_Content_58 = {
    Text = "Nautila si guarda intorno con sguardo vuoto, lasciando che la pioggia torrenziale le si riversi addosso."
  },
  AvgDialog_128696_Content_59 = {
    Text = "La tempesta infuria tra tuoni e fulmini, colpendo ogni nervo come una musica implacabile al festino di un demone."
  },
  AvgDialog_128696_Content_6 = {
    Text = "Nautila si è consumata fino all'osso, dormendo a malapena per rattoppare lo scafo. A tre giorni dalla tempesta prevista, tutti i componenti chiave erano tornati al loro posto."
  },
  AvgDialog_128696_Content_60 = {
    Text = "La corrente del vortice è troppo forte... non possiamo più tornare indietro..."
  },
  AvgDialog_128696_Content_61 = {
    Text = "Senza proferire parola, Vortice trascina la muta da immersione fuori dalla cabina e, senza avere la minima idea di come funzioni, cerca comunque di infilarla a Nautila con la forza."
  },
  AvgDialog_128696_Content_62 = {
    Text = "La muta? Non se ne parla—se la indosso io, tu come fai?"
  },
  AvgDialog_128696_Content_63 = {
    Text = "Ormai la nave si inclina completamente e senza controllo verso il vortice."
  },
  AvgDialog_128696_Content_64 = {
    Text = "<Shake:Criiiiic—>"
  },
  AvgDialog_128696_Content_7 = {
    Text = "Purché riesca ad ancorare ancora… uff… ho tanto sonno…"
  },
  AvgDialog_128696_Content_8 = {Text = "Thud."},
  AvgDialog_128696_Content_9 = {
    Text = "Chirp?! Chirp—? (Umano?! Umano?!!!)"
  },
  AvgDialog_128697_Content_1 = {
    Text = "Bene. Meglio. Perfetto!"
  },
  AvgDialog_128697_Content_10 = {Text = "..."},
  AvgDialog_128697_Content_11 = {
    Text = "<Italic:*versetti felici*>"
  },
  AvgDialog_128697_Content_12 = {
    Text = "Anche se, sì, è forse un po' distruttiva."
  },
  AvgDialog_128697_Content_13 = {
    Text = "Custode! Vortice! Sconfiggere compiti malvagi! Forte!"
  },
  AvgDialog_128697_Content_14 = {
    Text = "Ehi… Guardiano dei Segreti… Coalsie?!"
  },
  AvgDialog_128697_Content_15 = {
    Text = "L'istinto bestiale di Vortice coglie la differenza all'istante. Scatta come una catapulta e si lancia in avanti, avvolgendoti in un abbraccio travolgente."
  },
  AvgDialog_128697_Content_16 = {
    Text = "Ahi! Vortice, fa male!"
  },
  AvgDialog_128697_Content_17 = {
    Text = "Allo stesso tempo, la museruola che indossa assesta un colpo deciso al tuo povero naso."
  },
  AvgDialog_128697_Content_18 = {
    Text = "Museruola, restrizioni, acciaio di Vortice, bene! Heh heh, Vortice, al sicuro."
  },
  AvgDialog_128697_Content_19 = {
    Text = "Il dispositivo che Mythag ha sviluppato appositamente per lei contiene efficacemente il Traboccamento del suo Potere. Ora, la potenza distruttiva massima di Vortice equivale soltanto a quella di un essere umano leggermente più Forte della media."
  },
  AvgDialog_128697_Content_2 = {
    Text = "Ciao, Custode. Riguardo alla Risvegliatrice N. O-1841: data la sua recente fase di Risveglio, gli occasionali accessi di ferocia e il controllo incompleto sulle sue abilità, consigliamo di esercitare cautela in ogni interazione con lei."
  },
  AvgDialog_128697_Content_20 = {
    Text = "Amici, dopo quello, avventura perfetta? Sì? No?"
  },
  AvgDialog_128697_Content_21 = {
    Text = "Ci vuole un notevole sforzo per staccarti di dosso l'esuberante Bambina simile a un Cucciolo. Finalmente disposta a stare ferma, si appollaia di fronte alla tua scrivania, fissandoti con quegli occhi luminosi e scintillanti."
  },
  AvgDialog_128697_Content_22 = {Text = "Hmm..."},
  AvgDialog_128697_Content_23 = {
    Text = "In realtà..."
  },
  AvgDialog_128697_Content_24 = {
    Text = "Sotto il Vortice Moskstraumen esiste un'enorme D-fessura; Nautila e io, pur essendo sfuggiti all'influenza del Vortice, abbiamo entrambi mostrato segni di amnesia."
  },
  AvgDialog_128697_Content_25 = {
    Text = "Ti sei fermato solo per un breve istante prima di scegliere di usare \"io\" — adottando la coscienza di quel Sogno come tua."
  },
  AvgDialog_128697_Content_26 = {
    Text = "Nautila ti ha cercato da allora. Ha fondato un gruppo di avventurieri, ma ha incontrato un altro disastro durante la Navigazione di Ritorno..."
  },
  AvgDialog_128697_Content_27 = {
    Text = "Probabilmente non ricorda più, ma... ha fatto la tua stessa Scelta."
  },
  AvgDialog_128697_Content_28 = {
    Text = "Oh... Capisco..."
  },
  AvgDialog_128697_Content_29 = {
    Text = "Ma, è fantastico."
  },
  AvgDialog_128697_Content_3 = {
    Text = "Grazie, Erica. Ma va bene, credo di conoscere la mia... amica abbastanza bene."
  },
  AvgDialog_128697_Content_30 = {Text = "Certo"},
  AvgDialog_128697_Content_31 = {
    Text = "Certo che sì! Dopo, Nautila e io..."
  },
  AvgDialog_128697_Content_32 = {
    Text = "In breve, finché Nautila e io non siamo diventati troppo vecchi per muoverci, abbiamo vissuto ogni genere di avventura."
  },
  AvgDialog_128697_Content_33 = {
    Text = "Ti spremi le meningi e intrecci ogni Storia di avventura che tu abbia mai sentito nel tuo breve, cosciente anno di vita nel racconto che tessi per Vortice."
  },
  AvgDialog_128697_Content_34 = {
    Text = "Dopotutto, cielo, non c'è semplicemente modo che tu possa dire qualcosa di crudele a quegli occhi Innocenti."
  },
  AvgDialog_128697_Content_35 = {
    Text = "Storia di Robin@2, Vortice, ha sentito."
  },
  AvgDialog_128697_Content_36 = {
    Text = "<Gray:Oh no, ho dimenticato che quello era materiale di lettura per gli studi generali...>"
  },
  AvgDialog_128697_Content_37 = {
    Text = "È gestibile."
  },
  AvgDialog_128697_Content_38 = {Text = "Eh?"},
  AvgDialog_128697_Content_39 = {
    Text = "Vortice abbassa la testa e preme il viso contro il tuo palmo, proprio come faceva quando eri ancora il piccolo Carboncino."
  },
  AvgDialog_128697_Content_4 = {
    Text = "Contrariamente a quanto l'Accademia aveva previsto, il tuo primo Legame con questa volatile Risvegliatrice è andato sorprendentemente liscio."
  },
  AvgDialog_128697_Content_40 = {
    Text = "Amico, Coalsie, incontrare di nuovo."
  },
  AvgDialog_128697_Content_41 = {
    Text = "Coalsie, attraversa l'oscurità, ricorda Vortice, bene."
  },
  AvgDialog_128697_Content_42 = {
    Text = "Il suo volto si apre in un sorriso — ampio, luminoso, e così completamente felice."
  },
  AvgDialog_128697_Content_43 = {
    Text = "Ma, braccialetto, sparito."
  },
  AvgDialog_128697_Content_44 = {
    Text = "Ma, noi qui, meglio, meglio del meglio!"
  },
  AvgDialog_128697_Content_45 = {Text = "Vortice..."},
  AvgDialog_128697_Content_46 = {Text = "Cip?"},
  AvgDialog_128697_Content_47 = {
    Text = "??Perché c'è una lontra marina con un cappello da Mythag qui?"
  },
  AvgDialog_128697_Content_48 = {
    Text = "Le mie scuse, Custode, sembra che molti studenti si siano piuttosto affezionati a questa lontra marina randagia e l'abbiano adornata con alcune decorazioni superflue."
  },
  AvgDialog_128697_Content_49 = {
    Text = "Erica avvierà la procedura di espulsione il prima possibile. Uno, due—"
  },
  AvgDialog_128697_Content_5 = {
    Text = "Dopo questo sogno inaspettato, credi di aver trovato la risposta."
  },
  AvgDialog_128697_Content_50 = {
    Text = "Ah, lontra marina! Carina! Giocare con Vortice!"
  },
  AvgDialog_128697_Content_51 = {
    Text = "Bang. Tonf. Clang—"
  },
  AvgDialog_128697_Content_52 = {Text = "Bang!"},
  AvgDialog_128697_Content_53 = {
    Text = "Ahi, Vortice!"
  },
  AvgDialog_128697_Content_54 = {
    Text = "Nautila è appena entrata in classe quando vede la sua nuova migliore amica scatenarsi per la stanza inseguendo una lontra marina con un cappello da Mythag, lasciando una scia di attrezzature demolite al suo passaggio."
  },
  AvgDialog_128697_Content_55 = {
    Text = "Custode, per favore dica alla Professoressa Erica che sistemerò tutto in classe!"
  },
  AvgDialog_128697_Content_56 = {
    Text = "Vortice, basta!"
  },
  AvgDialog_128697_Content_57 = {
    Text = "Iik— squeak—!"
  },
  AvgDialog_128697_Content_58 = {Text = "SQUEAK!"},
  AvgDialog_128697_Content_59 = {
    Text = "<Italic:*versetti felici*>"
  },
  AvgDialog_128697_Content_6 = {
    Text = "Ama la carne arrosto e il mare. È timida, e odia il freddo, l'Oscurità e la solitudine... Quando ha paura, tira su col naso in silenzio perché nessuno se ne accorga."
  },
  AvgDialog_128697_Content_60 = {
    Text = "Se non mi sbaglio, quella lontra marina sta dicendo \"gioca con me,\" giusto? ...Come fa esattamente a comunicare con Vortice?"
  },
  AvgDialog_128697_Content_61 = {
    Text = "Eh?! Perché riesco a capire anche la lontra marina?!"
  },
  AvgDialog_128697_Content_62 = {
    Text = "Aspetta, se è così..."
  },
  AvgDialog_128697_Content_63 = {
    Text = "Ehm. O lontra marina Mythag senza nome, con la presente ti conferisco il titolo di \"Coalsie.\""
  },
  AvgDialog_128697_Content_64 = {
    Text = "Erediterai il nome di Coalsie e diventerai la grande, gloriosa Coalsie Seconda!"
  },
  AvgDialog_128697_Content_65 = {Text = "!"},
  AvgDialog_128697_Content_66 = {
    Text = "Coalsie Secondo! Coalsie Secondo!"
  },
  AvgDialog_128697_Content_67 = {
    Text = "Cip— (IMPATTO LONTRA!)"
  },
  AvgDialog_128697_Content_68 = {
    Text = "NAUTILA—!!"
  },
  AvgDialog_128697_Content_69 = {
    Text = "Perfetto, ora è un caos totale."
  },
  AvgDialog_128697_Content_7 = {
    Text = "È un pomeriggio dorato a Mythag. La luce del sole filtra attraverso le vetrate colorate e cade sul volto della Bambina alle prese con il suo Libro di Testo di lingua Leoniana."
  },
  AvgDialog_128697_Content_70 = {
    Text = "E così, in quanto mia legittima erede, <Small:è tuo solenne dovere occuparti di ciò che dispiace a me, Coalsie Prima...>"
  },
  AvgDialog_128697_Content_71 = {
    Text = "Fischietti con nonchalance, poi piano, sempre più piano..."
  },
  AvgDialog_128697_Content_72 = {
    Text = "...lanci i tuoi compiti di analisi verso le zampe della lontra marina nel bel mezzo del trambusto."
  },
  AvgDialog_128697_Content_73 = {
    Text = "In un Bagliore, i compiti si trasformano in brandelli accartocciati, che giacciono pacificamente in un mucchio di carta straccia."
  },
  AvgDialog_128697_Content_74 = {
    Text = "Che bella giornata, vero, Nautila, Vortice?"
  },
  AvgDialog_128697_Content_75 = {Text = "Ah—!"},
  AvgDialog_128697_Content_76 = {
    Text = "Mythag, anche oggi, è amichevole e pacifica come sempre."
  },
  AvgDialog_128697_Content_77 = {
    Text = "Meraviglioso. Davvero, assolutamente meraviglioso."
  },
  AvgDialog_128697_Content_8 = {
    Text = "Ma è anche incredibilmente coraggiosa — sempre pronta a fare scudo ai suoi amici da tutto ciò che odia."
  },
  AvgDialog_128697_Content_9 = {
    Text = "Straaap — il Libro di Testo si divide nettamente in due, proprio nel bel mezzo di quello che si stava rivelando un momento piuttosto toccante."
  },
  AvgDialog_128698_Content_1 = {
    Text = "Splash~ Splash~"
  },
  AvgDialog_128698_Content_10 = {
    Text = "La propulsione e il carburante non sono un problema, ma lo scafo è davvero troppo fragile… Vortice, c'è qualche modo per aggirare quel grande Vortice? È lì vicino che la flotta precedente ha avuto l'incidente."
  },
  AvgDialog_128698_Content_11 = {
    Text = "...Non riesco a uscire."
  },
  AvgDialog_128698_Content_12 = {
    Text = "Vortice scuote la testa, ti prende di nuovo in braccio, poi voi due gesticolate selvaggiamente insieme — agitando all'unisono tutte e quattro le mani e i quattro piedi."
  },
  AvgDialog_128698_Content_13 = {
    Text = "Persone cattive, prendere Mamma e Papà. Vortice, mordere, portata via. Carboncino, su nave, incontrare."
  },
  AvgDialog_128698_Content_14 = {
    Text = "Oceano, whoosh— poi qui. Vortice, provare, ma non funzionare."
  },
  AvgDialog_128698_Content_15 = {
    Text = "Sei stata presa da persone cattive e separata dai tuoi genitori... e da allora non sei più riuscita a uscire?"
  },
  AvgDialog_128698_Content_16 = {
    Text = "Mamma, Papà, non qui."
  },
  AvgDialog_128698_Content_17 = {
    Text = "Mi dispiace..."
  },
  AvgDialog_128698_Content_18 = {
    Text = "Oh! Mamma, Papà, tipo... venite!"
  },
  AvgDialog_128698_Content_19 = {
    Text = "Vortice! Dove mi stai trascinando?!"
  },
  AvgDialog_128698_Content_2 = {
    Text = "Una volta che avremo riparato completamente i cuscinetti di questa sezione, il timone dovrebbe—"
  },
  AvgDialog_128698_Content_20 = {Text = "..."},
  AvgDialog_128698_Content_21 = {
    Text = "Huff... huff... Ma cosa sei, un mostro?! Come fai a nuotare così veloce portandomi in braccio?!"
  },
  AvgDialog_128698_Content_22 = {
    Text = "Aspetta—dove siamo?"
  },
  AvgDialog_128698_Content_23 = {Text = "Ah—!"},
  AvgDialog_128698_Content_24 = {
    Text = "Salti allegramente in acqua per prima, spaventando tutti i pesci intorno."
  },
  AvgDialog_128698_Content_25 = {
    Text = "Mentre tu e Vortice vi tuffate una dopo l'altra con grida di gioia, increspature si sollevano dalle profondità sottostanti, come a rispondere ai vostri richiami."
  },
  AvgDialog_128698_Content_26 = {
    Text = "Mamma, Papà, piacciono! Nautila, Vortice, uguali!"
  },
  AvgDialog_128698_Content_27 = {
    Text = "Diversi splendidi delfini bianchi risalgono scivolando dalle profondità, radunandosi intorno a voi, strofinando affettuosamente il muso e le pinne contro te e Vortice."
  },
  AvgDialog_128698_Content_28 = {
    Text = "Vi girano intorno con grazia, alcuni balzano persino fuori dall'acqua spruzzando Nautila con piccoli getti d'acqua, come per invitarla a unirsi al gioco."
  },
  AvgDialog_128698_Content_29 = {
    Text = "Sono... delfini? Vortice, stai dicendo che anche i tuoi genitori sono delfini?"
  },
  AvgDialog_128698_Content_3 = {
    Text = "Il portolano?"
  },
  AvgDialog_128698_Content_30 = {
    Text = "Sì. Piccola Vortice, persa. Delfini, nutrire piccola Vortice. Vortice, crescere!"
  },
  AvgDialog_128698_Content_31 = {
    Text = "Vortice, dai da mangiare a Coalsie. Coalsie, cresci!"
  },
  AvgDialog_128698_Content_32 = {
    Text = "Vortice scoppia a ridere, schivando l'acqua che le schizzi addosso con stizza — e poi, insieme, entrambe tendete le mani verso Nautila."
  },
  AvgDialog_128698_Content_33 = {
    Text = "Fidati. Amico."
  },
  AvgDialog_128698_Content_34 = {Text = "Certo."},
  AvgDialog_128698_Content_35 = {
    Text = "Nautila stringe forte le vostre mani. Una davanti, una dietro, tu e Vortice la guidate verso una grotta nascosta."
  },
  AvgDialog_128698_Content_36 = {
    Text = "Dopo un breve momento di Oscurità, un gruppo, due gruppi… innumerevoli gruppi di luci soffuse e oniriche si destarono, le meduse si riversarono verso la superficie, poi furono dolcemente respinte dal Vortice, finché una luce più intensa non scese dalla volta celeste."
  },
  AvgDialog_128698_Content_37 = {
    Text = "…Io, non sto mica sognando."
  },
  AvgDialog_128698_Content_38 = {
    Text = "La luce del sole perfora gli strati di roccia, dipingendo il fondale marino di sfumature cangianti d'azzurro. Coralli variopinti e innumerevoli creature marine squarciano il blu, creando uno spettacolo così mozzafiato da lasciare senza parole."
  },
  AvgDialog_128698_Content_39 = {
    Text = "Gli anemoni di mare trascinano i loro tentacoli velenosi in una danza lenta e ipnotica. I molluschi si aggrappano vicini, vivendo in quieta armonia con loro. I predatori si annidano nell'oscurità dell'abisso, in paziente attesa. Questo luogo è pericoloso e bellissimo, tenebroso e abbagliante — un mondo a sé, un microcosmo dell'oceano."
  },
  AvgDialog_128698_Content_4 = {
    Text = "Il timone. È come un volante — controlla la direzione in cui vai. Sai cos'è un volante?"
  },
  AvgDialog_128698_Content_40 = {Text = "Nautila?"},
  AvgDialog_128698_Content_41 = {
    Text = "Questo. Bello. Per te."
  },
  AvgDialog_128698_Content_42 = {
    Text = "Vortice tira fuori una perla luccicante e luminosa. Con un'espressione di assoluta sincerità, la depone con cura nel palmo di Nautila."
  },
  AvgDialog_128698_Content_43 = {
    Text = "Vortice, qui, piace. Vortice, tesoro, piace. Nautila, amica, per te."
  },
  AvgDialog_128698_Content_44 = {
    Text = "(Te l'ho chiesta così tante volte e non me l'hai mai data! Cattivona!)"
  },
  AvgDialog_128698_Content_45 = {
    Text = "Brontoli tra te e te, ma pensando a tutto il delizioso pesce alla griglia e allo stufato di mare che hai mangiato ultimamente, con generosità spingi la perla più a fondo nella mano di Nautila insieme a Vortice."
  },
  AvgDialog_128698_Content_46 = {
    Text = "Oh... grazie! Bene, allora ho un dono anch'io per Vortice."
  },
  AvgDialog_128698_Content_47 = {Text = "Un dono?"},
  AvgDialog_128698_Content_48 = {
    Text = "Nautila slaccia dal polso il piccolo braccialetto che porta sempre, ornato da un minuscolo ciondolo a forma di nautilo."
  },
  AvgDialog_128698_Content_49 = {
    Text = "Quando un'amica dà qualcosa a un'amica, si chiama \"dono\". La perla è il tuo dono per me. E questo... questo è il mio dono per te."
  },
  AvgDialog_128698_Content_5 = {Text = "Hmm?"},
  AvgDialog_128698_Content_50 = {
    Text = "Mia madre mi ha dato una collana e questo braccialetto, e le ho promesso che sarei diventata una grande avventuriera."
  },
  AvgDialog_128698_Content_51 = {
    Text = "Vortice, riparerò la nave presto. Partiremo insieme e andremo a cercare i tuoi genitori."
  },
  AvgDialog_128698_Content_52 = {
    Text = "E dopo... saresti disposta a indossare questo braccialetto, portare Coalsie con te e partire all'avventura con me?"
  },
  AvgDialog_128698_Content_53 = {Text = "..."},
  AvgDialog_128698_Content_54 = {
    Text = "Nautila, Vortice, Coalsie, avventura!"
  },
  AvgDialog_128698_Content_55 = {Text = "Evviva!"},
  AvgDialog_128698_Content_56 = {
    Text = "Dopo un breve silenzio che sembra quasi un'illusione, Vortice esplode nel suo solito sorriso radioso e ti stringe forte tra le braccia mentre applaude."
  },
  AvgDialog_128698_Content_57 = {
    Text = "Cip! (Avventura!)"
  },
  AvgDialog_128698_Content_58 = {
    Text = "Cosa potresti mai capire? Sei solo una lontra di mare. Anche se avessi colto un suggerimento di qualcosa, il tuo piccolo cervello non riuscirebbe ad afferrarlo del tutto. E così lasci perdere, tuffandoti a capofitto nell'atmosfera gioiosa."
  },
  AvgDialog_128698_Content_59 = {
    Text = "Bene, Coalsie, ho un dono anche per te!"
  },
  AvgDialog_128698_Content_6 = {
    Text = "Un volante è ciò che controlla dove vanno queste grandi macchine — giri la ruota, e la nave o l'automobile segue la rotta che hai impostato."
  },
  AvgDialog_128698_Content_60 = {Text = "..."},
  AvgDialog_128698_Content_61 = {Text = "!"},
  AvgDialog_128698_Content_62 = {
    Text = "La cabina della nave, un tempo fatiscente, è stata completamente trasformata: tra due letti identici, semplici ma puliti e robusti, si trova un baule di legno ricolmo di morbidi cuscini."
  },
  AvgDialog_128698_Content_63 = {
    Text = "Eh eh, ora ognuno ha il proprio letto."
  },
  AvgDialog_128698_Content_64 = {
    Text = "Prima ancora che la voce di Nautila si spenga, ti sei tuffata a capofitto nella tua tana perfetta — Nautila ti ha persino lasciato un angolino speciale per le tue preziose conchiglie!"
  },
  AvgDialog_128698_Content_65 = {
    Text = "Il calore della zuppa di pesce della cena indugia ancora nel tuo ventre, e al ritmo del respiro regolare delle ragazze, scivoli nel sonno in men che non si dica."
  },
  AvgDialog_128698_Content_66 = {
    Text = "Ma quando la notte cala davvero, quella sensazione minacciosa comincia a propagarsi, densa e viscosa come la nebbia del mare."
  },
  AvgDialog_128698_Content_67 = {
    Text = "<Shake:Vortice, @3...>"
  },
  AvgDialog_128698_Content_68 = {
    Text = "<Shake:Torna da me, sottomettiti a me, @4...@4!>"
  },
  AvgDialog_128698_Content_69 = {
    Text = "Nell'oscurità, l'oceano si riempie di orrore e mistero. La luce del sole non sfiora più la superficie, e nel profondo dell'abisso, qualcosa si agita con un rombo basso e gutturale."
  },
  AvgDialog_128698_Content_7 = {
    Text = "Ohhhh! Un timone! Che figata!"
  },
  AvgDialog_128698_Content_70 = {
    Text = "Fluttui nel vuoto sconfinato e gelido, cercando disperatamente di raggiungere la figura lontana che piange sommessamente nel buio."
  },
  AvgDialog_128698_Content_71 = {
    Text = "Cip— (Grosso—)"
  },
  AvgDialog_128698_Content_72 = {
    Text = "SQUEAAKKK! (Grande!)"
  },
  AvgDialog_128698_Content_73 = {
    Text = "Ti svegli di soprassalto. Non c'è il respiro gentile delle ragazze addormentate, tutto è avvolto in un silenzio di morte. Strisci fuori dal tuo nido e segui l'odore di Vortice fino al ponte."
  },
  AvgDialog_128698_Content_74 = {
    Text = "Sta fissando il vortice in lontananza."
  },
  AvgDialog_128698_Content_75 = {
    Text = "(Ancora quel sogno... quante volte è successo, da quando quegli orribili umani sono morti e abbiamo fatto di questo posto la nostra casa?)"
  },
  AvgDialog_128698_Content_76 = {
    Text = "Chiamare, Vortice, là."
  },
  AvgDialog_128698_Content_77 = {
    Text = "Paura... no..."
  },
  AvgDialog_128698_Content_78 = {
    Text = "Ehi, Coalsie, Vortice, che ci fate voi due qui fuori?"
  },
  AvgDialog_128698_Content_79 = {
    Text = "La voce di Nautila squarcia i deliri onirici di Vortice. Un istante dopo, Nautila spinge con entusiasmo un set di equipaggiamento metallico verso di voi."
  },
  AvgDialog_128698_Content_8 = {Text = "..."},
  AvgDialog_128698_Content_80 = {
    Text = "Vortice, hai detto che immergerti troppo in profondità ti fa stare male, ma vuoi comunque vedere cosa c'è laggiù, vero?"
  },
  AvgDialog_128698_Content_81 = {
    Text = "Ho riparato la muta da immersione che ho trovato sulla nave. Con questa potrai immergerti più a lungo e non ti sentirai più male."
  },
  AvgDialog_128698_Content_82 = {
    Text = "Peccato che devo riparare la nave prima che arrivi la prossima tempesta. Dopo la tempesta, ne farò una anche per me."
  },
  AvgDialog_128698_Content_83 = {
    Text = "Un giorno potremo esplorare il mare insieme!"
  },
  AvgDialog_128698_Content_84 = {
    Text = "Vortice è insolitamente silenziosa. Dopo un istante, annuisce con decisione, ti prende in braccio e stringe Nautila in un grande abbraccio."
  },
  AvgDialog_128698_Content_85 = {Text = "Fuga."},
  AvgDialog_128698_Content_86 = {
    Text = "Vortice, Nautila, Coalsie, Fuga! Insieme!"
  },
  AvgDialog_128698_Content_9 = {
    Text = "I dati degli strumenti indicano che abbiamo al massimo una settimana prima che arrivi una tempesta — una che durerà almeno mezzo mese. Questa nave è già in pessime condizioni... non so nemmeno se reggerà dopo la tempesta."
  },
  AvgDialog_128699_Content_1 = {
    Text = "Pic, pic, pic."
  },
  AvgDialog_128699_Content_10 = {
    Text = "Vortice, ascoltami—sono stata io a proporre di spiegare le vele, e sono stata io a giudicare male il tempo, quindi è mia responsabilità portare te e Carboncino fuori di qui."
  },
  AvgDialog_128699_Content_11 = {
    Text = "Mi tolgo la muta e la do a te. La barca può ancora muoversi, quindi cercherò di guidarla verso il bordo del vortice, e poi tu..."
  },
  AvgDialog_128699_Content_12 = {Text = "Tu..."},
  AvgDialog_128699_Content_13 = {
    Text = "Nautila resta immobile, pietrificata. Per la prima volta, vede quella bambina spensierata, vivace e ingenua indossare un'espressione complessa e preoccupata."
  },
  AvgDialog_128699_Content_14 = {
    Text = "Nautila, mi dispiace."
  },
  AvgDialog_128699_Content_15 = {
    Text = "Vortice allunga la mano. Pur non comprendendo come funzioni il dispositivo, spinta da un istinto bestiale, finisce di vestire Nautila con la muta da immersione con la forza."
  },
  AvgDialog_128699_Content_16 = {
    Text = "Vortice, pericolo, sensazione."
  },
  AvgDialog_128699_Content_17 = {
    Text = "Ma, speranza, non accadrà."
  },
  AvgDialog_128699_Content_18 = {
    Text = "La pioggia si riversa da un buco nel tetto, schizzando su entrambe."
  },
  AvgDialog_128699_Content_19 = {
    Text = "Il silenzio riempie la cabina. È Vortice a romperlo infine."
  },
  AvgDialog_128699_Content_2 = {
    Text = "<Shake:Criiiiic—>"
  },
  AvgDialog_128699_Content_20 = {
    Text = "Vortice, vieni qui, sogno."
  },
  AvgDialog_128699_Content_21 = {
    Text = "Vortice sogno... qualcosa, chiama Vortice..."
  },
  AvgDialog_128699_Content_22 = {
    Text = "Ma... non voglio andare. Freddo, nessuno intorno, sola..."
  },
  AvgDialog_128699_Content_23 = {
    Text = "Nautila capisce improvvisamente perché la pioggia torrenziale è caduta in anticipo, perché il tornado è apparso senza preavviso. Comincia a tremare in modo incontrollabile."
  },
  AvgDialog_128699_Content_24 = {
    Text = "Quella cosa... proprio lì..."
  },
  AvgDialog_128699_Content_25 = {
    Text = "Seguendo il dito di Vortice, Nautila avverte un senso di terrore strisciare su dal suo subconscio."
  },
  AvgDialog_128699_Content_26 = {
    Text = "Terrore dal fondo del Moskstraumen. Terrore di qualcosa che trascende la comprensione mortale."
  },
  AvgDialog_128699_Content_27 = {Text = "..."},
  AvgDialog_128699_Content_28 = {
    Text = "No, no, no—so cosa stai per fare, non se ne parla!"
  },
  AvgDialog_128699_Content_29 = {
    Text = "Fidati di me, deve esserci un altro modo!"
  },
  AvgDialog_128699_Content_3 = {
    Text = "La corrente furiosa afferra lo scafo come due mani enormi che strizzano un panno bagnato."
  },
  AvgDialog_128699_Content_30 = {
    Text = "Nautila si aggrappa disperatamente a Vortice. Sebbene Vortice, con la sua forza bestiale, potrebbe scrollarsi Nautila di dosso in qualsiasi momento, non lo fa."
  },
  AvgDialog_128699_Content_31 = {
    Text = "Ti prende semplicemente in braccio e ti strofina il muso con affetto."
  },
  AvgDialog_128699_Content_32 = {
    Text = "Amico, forte, ma, no. Solo, Vortice, può."
  },
  AvgDialog_128699_Content_33 = {
    Text = "Solo, Vortice, può."
  },
  AvgDialog_128699_Content_34 = {
    Text = "...Perché, perché deve essere così?"
  },
  AvgDialog_128699_Content_35 = {
    Text = "Amico, non piangere, sorridi, Vortice, piace!"
  },
  AvgDialog_128699_Content_36 = {
    Text = "Ehm, scusa, ho visto che mangiavate tutti pesce crudo, così l'ho cucinato un po'… anche se non ci sono condimenti, vuoi Assaggiare?"
  },
  AvgDialog_128699_Content_37 = {
    Text = "<Italic:Gnam gnam!>"
  },
  AvgDialog_128699_Content_38 = {
    Text = "<Italic:Gnam gnam!>"
  },
  AvgDialog_128699_Content_39 = {Text = "Delizioso"},
  AvgDialog_128699_Content_4 = {
    Text = "La nave emette un gemito sotto l'immensa pressione. Vortice urla sovrastando la tempesta, mentre con una mano ficca disperatamente Nautila nella muta da immersione e con l'altra ti stringe più forte a sé."
  },
  AvgDialog_128699_Content_40 = {
    Text = "Avventura, aspettare!"
  },
  AvgDialog_128699_Content_41 = {
    Text = "Vortice, riparerò la nave presto. Partiremo insieme e andremo a cercare i tuoi genitori."
  },
  AvgDialog_128699_Content_42 = {
    Text = "E dopo... saresti disposta a indossare questo braccialetto, portare Coalsie con te e partire all'avventura con me?"
  },
  AvgDialog_128699_Content_43 = {
    Text = "Nautila, Vortice, Coalsie, avventura!"
  },
  AvgDialog_128699_Content_44 = {
    Text = "Amico, piacere!"
  },
  AvgDialog_128699_Content_45 = {
    Text = "Amico, dare Vortice, tanto, tanto!"
  },
  AvgDialog_128699_Content_46 = {
    Text = "Quindi, ora, Vortice dare amico, tanto, tanto!"
  },
  AvgDialog_128699_Content_47 = {
    Text = "Si pianta come un muro contro la tempesta furiosa, stringendo te e Nautila saldamente tra le braccia. Poi fa un respiro profondo e sfoggia un largo sorriso rassicurante, così interamente suo."
  },
  AvgDialog_128699_Content_48 = {
    Text = "Vortice, tornare, sicuro!"
  },
  AvgDialog_128699_Content_49 = {
    Text = "...Va bene, ti credo, Vortice. Quando tornerai, avrò pronta la nave più bella del mondo, e poi porterò te e Carboncino nella più grande avventura di sempre."
  },
  AvgDialog_128699_Content_5 = {
    Text = "Pericolo! Aggrappati!"
  },
  AvgDialog_128699_Content_50 = {
    Text = "Nautila si asciuga le lacrime, si ricompone e riesce ad abbozzare un sorriso un po' brutto."
  },
  AvgDialog_128699_Content_51 = {
    Text = "Vedendo che Nautila finalmente la lascia andare, Vortice piano, pianissimo, prende la tua zampa nella sua mano e preme il viso contro i tuoi cuscinetti."
  },
  AvgDialog_128699_Content_52 = {
    Text = "Coalsie, non, paura."
  },
  AvgDialog_128699_Content_53 = {
    Text = "Iiik... SQUEAK! (Mi stai lasciando indietro...)"
  },
  AvgDialog_128699_Content_54 = {
    Text = "SQUEAK! SQUEAKKK!— (Mi stai lasciando indietro!!)"
  },
  AvgDialog_128699_Content_55 = {
    Text = "I tuoi guaiti riempiono l'aria mentre vieni deposto tra le braccia di Nautila. Un istante dopo, quando la nave si inclina di nuovo, Vortice si volta senza esitazione e corre verso il vortice."
  },
  AvgDialog_128699_Content_56 = {Text = "...Plop."},
  AvgDialog_128699_Content_57 = {
    Text = "Come un pesce che ritorna al suo mare."
  },
  AvgDialog_128699_Content_58 = {Text = "VORTICE!"},
  AvgDialog_128699_Content_59 = {
    Text = "La tempesta sommerge tutte le urla. Un'onda alta come una montagna si abbatte sul ponte e trascina anche voi due in mare."
  },
  AvgDialog_128699_Content_6 = {Text = "Boom—"},
  AvgDialog_128699_Content_60 = {
    Text = "Sotto le acque blu scuro, innumerevoli tentacoli filiformi di melma nera si dispiegano verso Vortice. Le sue mani si dissolvono in massicce correnti vorticose, la sua espressione serena e tranquilla, le profondità dei suoi occhi calme e immobili, come l'occhio del vortice stesso."
  },
  AvgDialog_128699_Content_61 = {
    Text = "Vortice, mulinello. Vortice, timone."
  },
  AvgDialog_128699_Content_62 = {
    Text = "Coalsie, Nautila, qui, sempre."
  },
  AvgDialog_128699_Content_63 = {
    Text = "Vortice alla fine non riesce a trattenersi e scoppia in lacrime, premendo la mano contro il proprio petto."
  },
  AvgDialog_128699_Content_64 = {
    Text = "Poi alza la mano. Un vortice che porta con sé una forza distruttiva, eppure anormalmente gentile, vi spinge entrambi lontano, lontanissimo dal vortice."
  },
  AvgDialog_128699_Content_65 = {
    Text = "Filo dopo filo, la melma scura si aggrappa al corpo di Vortice, propagandosi su tutto il suo corpo in un istante."
  },
  AvgDialog_128699_Content_66 = {
    Text = "Il vortice inizia a convergere verso il proprio centro, portando con sé l'appagamento del Suo desiderio. La bambina, come intrecciata e trascinata da innumerevoli alghe oscure, sprofonda lentamente nell'abisso privo di sole."
  },
  AvgDialog_128699_Content_67 = {Text = "..."},
  AvgDialog_128699_Content_68 = {
    Text = "Tutto si è placato. Il cielo è di un azzurro terso, lavato dalla pioggia. Sul mare tranquillo, la nave deriva silenziosa."
  },
  AvgDialog_128699_Content_69 = {
    Text = "Eh, dove sono, e perché sono in acqua? Ugh... che afa!"
  },
  AvgDialog_128699_Content_7 = {
    Text = "La violenta scossa scaraventa Nautila in aria, facendola sbattere contro un barile di legno rotolato sul pavimento."
  },
  AvgDialog_128699_Content_70 = {
    Text = "Fissi con curiosità l'umana che galleggia in superficie con quell'abito strano."
  },
  AvgDialog_128699_Content_71 = {
    Text = "(Come sono finito qui, e chi è quello?)"
  },
  AvgDialog_128699_Content_72 = {Text = "Plap-plap."},
  AvgDialog_128699_Content_73 = {Text = "Plap-plap."},
  AvgDialog_128699_Content_74 = {
    Text = "(Oh giusto, sono una lontra marina! E le lontre marine cercano conchiglie. Conchiglie, conchiglie, conchiglie!)"
  },
  AvgDialog_128699_Content_75 = {
    Text = "Ti tuffi gioiosamente nell'acqua calda, nuotando nella direzione opposta rispetto all'umana che arranca verso la nave."
  },
  AvgDialog_128699_Content_76 = {
    Text = "Non ti accorgi delle tue lacrime che si fondono nel mare."
  },
  AvgDialog_128699_Content_8 = {Text = "Ugh..."},
  AvgDialog_128699_Content_9 = {
    Text = "Nautila, sopportando il dolore, si rialza barcollando e corre al fianco di Vortice."
  },
  AvgDialog_128700_Content_1 = {
    Text = "Glu... Glu..."
  },
  AvgDialog_128700_Content_10 = {
    Text = "Sei una lontra marina di un anno e mezzo, uscita a cercare cibo con la tua Grande preferita."
  },
  AvgDialog_128700_Content_100 = {
    Text = "La saliva ti inonda la bocca. Tentati dal cibo cotto, tu e Vortice vi lanciate in avanti quasi simultaneamente, addentando entrambi il pesce alla griglia."
  },
  AvgDialog_128700_Content_101 = {
    Text = "Buonissimo—!!"
  },
  AvgDialog_128700_Content_102 = {
    Text = "Ehi, ah… Nautila, la mano?"
  },
  AvgDialog_128700_Content_103 = {
    Text = "Solo una lussazione—l'ho già rimessa a posto. Sono un'avventuriera, quindi non è nulla di grave. E grazie per la medicina!"
  },
  AvgDialog_128700_Content_104 = {
    Text = "<Small: (Anche se è super amara e ha un retrogusto forte, funziona davvero bene.)>"
  },
  AvgDialog_128700_Content_105 = {
    Text = "Evviva!! Felice, abbraccio—"
  },
  AvgDialog_128700_Content_106 = {
    Text = "Eheh. Vortice. Attenta."
  },
  AvgDialog_128700_Content_107 = {
    Text = "Eh? Eh! Non preoccuparti, Vortice. La prossima volta griderò forte così saprai di lasciar andare, va bene?"
  },
  AvgDialog_128700_Content_108 = {Text = "Cip!"},
  AvgDialog_128700_Content_11 = {
    Text = "(Cosa abbiamo qui? Alghe, alghe marine, sassolini...)"
  },
  AvgDialog_128700_Content_12 = {
    Text = "(E Sasso, la zia di Sasso, il nonno di Sasso...?)"
  },
  AvgDialog_128700_Content_13 = {
    Text = "(SASSO! Di' alla tua famiglia di smetterla di nuotare qui intorno!!)"
  },
  AvgDialog_128700_Content_14 = {
    Text = "<Shake:ROAARRR—>"
  },
  AvgDialog_128700_Content_15 = {Text = "(Oh oh...)"},
  AvgDialog_128700_Content_16 = {
    Text = "Il mare si solleva in un enorme vortice. Una figura familiare ti viene incontro a tutta velocità, trascinando qualcosa di grosso sulla schiena!"
  },
  AvgDialog_128700_Content_17 = {
    Text = "Carboncino! Carne! Vortice trovare!"
  },
  AvgDialog_128700_Content_18 = {
    Text = "Felice! Andare casa! Insieme!"
  },
  AvgDialog_128700_Content_19 = {
    Text = "Prima che tu possa protestare, la bambina ti carica sulla schiena e schizza verso la superficie come un pesce."
  },
  AvgDialog_128700_Content_2 = {
    Text = "<Shake:Glu glu... Grrr...>"
  },
  AvgDialog_128700_Content_20 = {Text = "..."},
  AvgDialog_128700_Content_21 = {
    Text = "BOOM—! Un lampo squarcia il cielo, il tuono rimbomba, e le nubi gonfie di pioggia esplodono finalmente, rovesciando tutta la loro acqua nel mare."
  },
  AvgDialog_128700_Content_22 = {
    Text = "Tu e Vortice vi ritirate nella cabina al sicuro, fissandovi l'un l'altra."
  },
  AvgDialog_128700_Content_23 = {
    Text = "Eek? S-Squeakk?! (QUELLA sarebbe la carne? Grande, è identica a te!)"
  },
  AvgDialog_128700_Content_24 = {
    Text = "Proprio come me?"
  },
  AvgDialog_128700_Content_25 = {
    Text = "Vortice inclina la testa con la sua classica espressione perplessa, poi finalmente osserva bene la \"carne\" che ha lasciato cadere sul pavimento."
  },
  AvgDialog_128700_Content_26 = {
    Text = "Pfft—urgh."
  },
  AvgDialog_128700_Content_27 = {
    Text = "Cosa è appena successo... la mia testa sembra essere stata sott'acqua tutto il tempo... dove mi trovo... sono morta?"
  },
  AvgDialog_128700_Content_28 = {
    Text = "La sconosciuta tossisce violentemente e sputa un fiotto d'acqua di mare."
  },
  AvgDialog_128700_Content_29 = {
    Text = "Amico? Amico!! Uguale a Vortice!"
  },
  AvgDialog_128700_Content_3 = {
    Text = "<Shake:Grrr... Grrr... Grrr...>"
  },
  AvgDialog_128700_Content_30 = {
    Text = "Eh... cosa?"
  },
  AvgDialog_128700_Content_31 = {
    Text = "<LightGray:Viene da qualche tribù indigena dei dintorni? Strano... E dove mi trovo esattamente?>"
  },
  AvgDialog_128700_Content_32 = {
    Text = "Percepisci che è diffidente, ma non ostile. In silenzio, ti avvicini poco a poco per osservare meglio la nuova arrivata."
  },
  AvgDialog_128700_Content_33 = {
    Text = "Questa dovrebbe essere la cabina di una nave. Logora, ma strutturalmente solida per la maggior parte..."
  },
  AvgDialog_128700_Content_34 = {
    Text = "Aspetta — quelli sono rivetti della Northdrey Corporation?! Indicatori del livello dell'acqua, valvole a cassetto anulari—"
  },
  AvgDialog_128700_Content_35 = {
    Text = "Vediamo, in quel caso..."
  },
  AvgDialog_128700_Content_36 = {
    Text = "La sconosciuta fruga con entusiasmo nella cabina stipata all'inverosimile. Nel frattempo, Vortice resta lì accanto, sbattendo le palpebre con allegra curiosità."
  },
  AvgDialog_128700_Content_37 = {
    Text = "Luccicante, bello. Vortice, portare. Amico, piacere?"
  },
  AvgDialog_128700_Content_38 = {
    Text = "Vortice, con questi pezzi posso rimettere in funzione questa nave. Potresti darmeli?"
  },
  AvgDialog_128700_Content_39 = {
    Text = "Una volta raggiunta Aglo, ti prometto che ti porterò ancora più cosine luccicanti, ancora più belle."
  },
  AvgDialog_128700_Content_4 = {
    Text = "Ti sdrai sulla schiena nel mare caldo, allungando comodamente i tuoi arti corti, e fai una virata perfetta."
  },
  AvgDialog_128700_Content_40 = {
    Text = "SQUEAK—!! (Non se ne parla! La mia graziosa pallina è ancora lì dentro!!)"
  },
  AvgDialog_128700_Content_41 = {
    Text = "Emetti uno strillo furioso e ti lanci per riprenderti la pallina — ma la tua attenzione viene subito catturata da Vortice."
  },
  AvgDialog_128700_Content_42 = {
    Text = "Shh. Vortice, dare te. Conchiglie."
  },
  AvgDialog_128700_Content_43 = {
    Text = "Vortice infila silenziosamente nelle tue zampette due conchiglie che avevi adocchiato, poi spinge quei pezzi verso la sconosciuta, facendole segno che può prenderli."
  },
  AvgDialog_128700_Content_44 = {
    Text = "Amico, piacere, Vortice dare!"
  },
  AvgDialog_128700_Content_45 = {
    Text = "Non hai la minima idea del perché quei pezzi entusiasmino tanto la sconosciuta, ma hai già smesso di curartene. Affondi beatamente il tuo musetto in quelle splendide conchiglie che Vortice non ti aveva mai lasciato avvicinare."
  },
  AvgDialog_128700_Content_46 = {
    Text = "Meraviglioso! Grazie... amico."
  },
  AvgDialog_128700_Content_47 = {
    Text = "Riscaldata dalla gentilezza aperta e sincera di Vortice, la sconosciuta finalmente si rilassa un po' e vi rivolge un sorriso."
  },
  AvgDialog_128700_Content_48 = {
    Text = "A proposito, il mio nome è Nautila."
  },
  AvgDialog_128700_Content_49 = {
    Text = "Yay!! Nautila, Vortice, amici, felici!"
  },
  AvgDialog_128700_Content_5 = {
    Text = "(Aspetta, zampette tozze?)"
  },
  AvgDialog_128700_Content_50 = {
    Text = "Vortice esulta e spalanca le braccia, pronta a stringere la sua nuovissima amica in un enorme abbraccio."
  },
  AvgDialog_128700_Content_51 = {
    Text = "Ah! (Accidenti… il gigante…)"
  },
  AvgDialog_128700_Content_52 = {
    Text = "Amico! Abbraccio!!"
  },
  AvgDialog_128700_Content_53 = {
    Text = "Aspetta, Vortice—mmph! AHI—!"
  },
  AvgDialog_128700_Content_54 = {
    Text = "Le correnti d'aria nella cabina convergono all'improvviso; nel mezzo della pressione del vento intensificata, senti un nitido <Italic:schiocco>."
  },
  AvgDialog_128700_Content_55 = {Text = "SQUEAK!"},
  AvgDialog_128700_Content_56 = {
    Text = "Vortice si riscuote e lascia andare in fretta. Ma Nautila sta già facendo una smorfia di dolore, il braccio piegato in un angolo innaturale."
  },
  AvgDialog_128700_Content_57 = {
    Text = "S-scusa... Io... Io—"
  },
  AvgDialog_128700_Content_58 = {
    Text = "Vedendo Vortice paralizzata dal panico, le stringi i denti sulla gamba dei pantaloni e la trascini verso qualcosa."
  },
  AvgDialog_128700_Content_59 = {
    Text = "Squeak, squeak! (Da questa parte, Grosso! Qui!)"
  },
  AvgDialog_128700_Content_6 = {
    Text = "<Shake:Plip plop.>"
  },
  AvgDialog_128700_Content_60 = {
    Text = "Oh giusto, questo! Nautila—bevi!"
  },
  AvgDialog_128700_Content_61 = {
    Text = "Togliti di dosso!"
  },
  AvgDialog_128700_Content_62 = {
    Text = "Nautila istintivamente scosta con uno schiaffo la mano di Vortice, tirandosi indietro."
  },
  AvgDialog_128700_Content_63 = {
    Text = "[@Compound Tonic]"
  },
  AvgDialog_128700_Content_64 = {
    Text = "Glug, glug— La boccetta di medicina cade a terra e rotola fino a fermarsi ai piedi di Vortice."
  },
  AvgDialog_128700_Content_65 = {
    Text = "La ragazza, che solo un attimo prima era così allegra e spensierata, coglie con acutezza il terrore della sconosciuta. Lentamente, abbassa la mano."
  },
  AvgDialog_128700_Content_66 = {Text = "..."},
  AvgDialog_128700_Content_67 = {
    Text = "Mi scuso, ma… c'è un altro posto sulla nave? Potrei aver bisogno di riposare un po' da solo."
  },
  AvgDialog_128700_Content_68 = {
    Text = "Vortice resta in silenzio per un momento. Poi trascina la coperta più grande e morbida della nave e la stende sul pavimento — a una certa distanza."
  },
  AvgDialog_128700_Content_69 = {
    Text = "Vortice... maldestro. Troppo forte... fare male gente."
  },
  AvgDialog_128700_Content_7 = {Text = "Plaf plaf~"},
  AvgDialog_128700_Content_70 = {
    Text = "Vortice, cattivo. Scusa. Focolare, caldo, Nautila."
  },
  AvgDialog_128700_Content_71 = {
    Text = "Vieni sollevato in aria all'improvviso. Vortice con cautela, quasi timidamente, ti porge verso Nautila, come se offrisse un dono prezioso."
  },
  AvgDialog_128700_Content_72 = {
    Text = "Vortice, fuori. Carboncino, caldo, Nautila, restare."
  },
  AvgDialog_128700_Content_73 = {
    Text = "Inclina il mento verso la porta, poi indica la coperta, piantandosi ostinatamente tra Nautila e la porta."
  },
  AvgDialog_128700_Content_74 = {
    Text = "…Va bene, grazie."
  },
  AvgDialog_128700_Content_75 = {
    Text = "Iiik. Squeak?? (E-ehi, Grosso—??)"
  },
  AvgDialog_128700_Content_76 = {Text = "..."},
  AvgDialog_128700_Content_77 = {
    Text = "La pioggia non cessa per tutta la notte. A mezzanotte, Nautila si avvicina alla soglia della cabina e guarda la ragazza addormentata sul ponte."
  },
  AvgDialog_128700_Content_78 = {
    Text = "Rannicchiata stretta nell'angolo della nave, si ripara dal vento e dalla pioggia."
  },
  AvgDialog_128700_Content_79 = {
    Text = "...Dormire così profondamente in un posto del genere. Sei davvero come un piccolo animale..."
  },
  AvgDialog_128700_Content_8 = {
    Text = "(Oh, giusto! Sono una lontra marina!)"
  },
  AvgDialog_128700_Content_80 = {
    Text = "Scusa, Vortice. Non avrei dovuto scattare così."
  },
  AvgDialog_128700_Content_81 = {
    Text = "Vortice viene coperta con una coperta in più. Schiocca le labbra nel sonno e sprofonda in un sogno ancora più profondo e dolce."
  },
  AvgDialog_128700_Content_82 = {Text = "Cip!"},
  AvgDialog_128700_Content_83 = {
    Text = "Dopo una notte di pioggia, è il momento perfetto per pescare al mattino presto. Con orgoglio afferri con i denti il pesce più grosso della giornata e lo lanci addosso a Vortice. Ma—"
  },
  AvgDialog_128700_Content_84 = {
    Text = "<Italic:SBAM!>"
  },
  AvgDialog_128700_Content_85 = {Text = "..."},
  AvgDialog_128700_Content_86 = {
    Text = "Vortice si prende il pesce in piena faccia, spezzando il torpore che durava da tutta la mattina. Ti guarda, gli angoli della bocca che si curvano verso il basso. E poi — grosse, pesanti lacrime cominciano a scendere."
  },
  AvgDialog_128700_Content_87 = {
    Text = "Waah... waaaaaaah—"
  },
  AvgDialog_128700_Content_88 = {
    Text = "Un attimo dopo, affonda il viso interamente nella tua pancia e scoppia in singhiozzi fragorosi."
  },
  AvgDialog_128700_Content_89 = {
    Text = "Vortice, cattivo!"
  },
  AvgDialog_128700_Content_9 = {
    Text = "La tua testolina ricorda allegramente la situazione attuale."
  },
  AvgDialog_128700_Content_90 = {
    Text = "Eek!! Squeak! SQUEAK!! (Grandona!! IL TUO MOCCIO!! Attenta al tuo moccio!!)"
  },
  AvgDialog_128700_Content_91 = {
    Text = "<Italic:Sniff>— sa parlare, uguale, amica, mai...waaah waaah..."
  },
  AvgDialog_128700_Content_92 = {
    Text = "Vortice piange così forte che riesce a malapena a respirare. Lotti disperatamente per salvare la tua pancia da sotto il suo viso, ma alla fine rinunci con un sospiro e la lasci spalmarti il moccio addosso."
  },
  AvgDialog_128700_Content_93 = {
    Text = "(Probabilmente voleva dire che ha finalmente trovato un'amica con cui può parlare come lei, ma ha fatto confusione? Ma Big One conta davvero come capace di \"parlare\"?)"
  },
  AvgDialog_128700_Content_94 = {
    Text = "(Hm, aspetta—cos'è quel profumo incredibile?!)"
  },
  AvgDialog_128700_Content_95 = {Text = "..."},
  AvgDialog_128700_Content_96 = {
    Text = "Nella cabina, Nautila ha infilato diversi pesci su sottili fili metallici. Le fiamme ne hanno reso croccante la pelle, e il grasso gocciola sfrigolando sul pavimento sottostante, sprigionando un aroma che risveglia istantaneamente gli istinti più primitivi."
  },
  AvgDialog_128700_Content_97 = {
    Text = "Ehm, scusa, ho visto che mangiavate tutti pesce crudo, così l'ho cucinato un po'… anche se non ci sono condimenti, vuoi Assaggiare?"
  },
  AvgDialog_128700_Content_98 = {
    Text = "<Italic:Gnam gnam!>"
  },
  AvgDialog_128700_Content_99 = {
    Text = "<Italic:Gnam gnam!>"
  },
  AvgDialog_130451_Content_1 = {
    Text = "La notte è fioca. Hai appena terminato una missione sul campo, e il Risvegliatore che ti ha accompagnato — il piccolo cavaliere di un altro mondo, Giurasfranto·Ogier — ti segue silenziosamente alle spalle."
  },
  AvgDialog_130451_Content_10 = {
    Text = "Aspetta — ti prego, non avvicinarti!"
  },
  AvgDialog_130451_Content_11 = {
    Text = "Prima ancora che le sue parole si spengano, la tua visione diventa improvvisamente buia pece."
  },
  AvgDialog_130451_Content_12 = {
    Text = "Le presenze invisibili che da tempo coesistono con Giurasfranto·Ogier si lanciano improvvisamente verso di te, premendo contro le tue membra, coprendo i tuoi occhi, avvolgendosi strettamente intorno a te — lasciandoti una vaga sensazione di freddo."
  },
  AvgDialog_130451_Content_13 = {Text = "Ogier!"},
  AvgDialog_130451_Content_14 = {
    Text = "Gridi, ma il fango oscuro si attorciglia ancora più stretto, come se fosse disperato di legarti completamente dentro di sé. Allunghi le mani e tiri con forza, eppure si riavvolge ostinatamente intorno a te come viticci di una vite."
  },
  AvgDialog_130451_Content_15 = {Text = "Ugh..."},
  AvgDialog_130451_Content_16 = {
    Text = "La voce fioca e sfocata del ragazzo giunge a tratti spezzati — è chiaramente in lotta per trattenere qualcosa."
  },
  AvgDialog_130451_Content_17 = {
    Text = "Ogier? Riesci a sentirmi?"
  },
  AvgDialog_130451_Content_18 = {
    Text = "La stretta che ti vincola trasale leggermente, poi si stringe di nuovo — come se venisse tirata avanti e indietro tra due volontà opposte."
  },
  AvgDialog_130451_Content_19 = {
    Text = "A causa della mia incapacità, sei stato comunque ferito. Se solo riuscissi a trovare un modo migliore per proteggerti…"
  },
  AvgDialog_130451_Content_2 = {
    Text = "Questa missione non era particolarmente difficile. Come esperto Custode, tu e Giurasfranto·Ogier avete eliminato ogni nemico con facilità. Tuttavia, a causa di un momento di distrazione, hai comunque riportato un piccolo taglio al polso."
  },
  AvgDialog_130451_Content_20 = {
    Text = "Riesci a distinguere solo poche parole confuse, come qualcuno che parla tra sé e sé."
  },
  AvgDialog_130451_Content_21 = {
    Text = "Sebbene il fango ti vincoli strettamente, non ti causa il minimo dolore né soffocamento. Ti rendi improvvisamente conto che probabilmente non è inteso a farti del male — sembra piuttosto un tentativo di nasconderti in un posto assolutamente sicuro, dove nulla possa avvicinarsi a te."
  },
  AvgDialog_130451_Content_22 = {
    Text = "Va tutto bene. Sto benissimo — non devi aver paura."
  },
  AvgDialog_130451_Content_23 = {
    Text = "Le tue parole sembrano aver avuto effetto. Questa volta, la stretta del fango comincia finalmente ad allentarsi. Cogli il momento e lo allontani da te."
  },
  AvgDialog_130451_Content_24 = {
    Text = "Vedi Giuraspergiuro·Ogier con la testa china nello sconforto, la fronte leggermente corrugata, gli occhi ancora velati di confusione — come una statua penitente che porta il peso di un peccato enorme."
  },
  AvgDialog_130451_Content_25 = {Text = "Stai bene?"},
  AvgDialog_130451_Content_26 = {
    Text = "Pensare di aver scatenato su di te un potere così incontrollabile…"
  },
  AvgDialog_130451_Content_27 = {
    Text = "No, devo riportare me stesso… alla ragione."
  },
  AvgDialog_130451_Content_28 = {
    Text = "Chiude gli occhi e mormora, plasmando la piccola massa di fango nero che vortica attorno alla sua mano nella forma di un pugnale. La luce della luna cade sulla lama fredda e lucente — puntata verso il suo stesso altro braccio."
  },
  AvgDialog_130451_Content_29 = {
    Text = "Ma l'oggetto affilato non cade mai. Ti precipiti in avanti in tempo per fermare il suo movimento. Solo allora realizzi, con ritardo, che le cose invisibili che ti si erano strette così forte addosso poco prima si sono completamente ritirate."
  },
  AvgDialog_130451_Content_3 = {
    Text = "I dintorni sono completamente silenziosi. La stanchezza ha reso la tua mente un po' annebbiata, e vieni colto di sorpresa da un suono improvviso alle tue spalle."
  },
  AvgDialog_130451_Content_30 = {
    Text = "Mio signore...?"
  },
  AvgDialog_130451_Content_31 = {
    Text = "Ti accovacci a metà e lo abbracci delicatamente, accarezzandogli la schiena per confortarlo."
  },
  AvgDialog_130451_Content_32 = {
    Text = "Lui non si ritrae come farebbe di solito, ma rimane immobile al suo posto, mantenendo la postura di chi è tenuto tra le tue braccia."
  },
  AvgDialog_130451_Content_33 = {
    Text = "Non avere tanta fretta — rilassati. Vedi, è stato soppresso con successo da te. Ma cosa è successo esattamente?"
  },
  AvgDialog_130451_Content_34 = {
    Text = "Mi scuso, mio signore. Per qualche ragione, la presenza che mi è attaccata oggi era insolitamente irrequieta, e i miei pensieri sono diventati molto dispersi."
  },
  AvgDialog_130451_Content_35 = {
    Text = "Anche con te al mio fianco, non solo non si è ritirata come fa di solito — è diventata ancora più attiva… Ecco perché volevo usare il dolore per calmarmi."
  },
  AvgDialog_130451_Content_36 = {
    Text = "Tenendo Ogier tra le braccia, puoi sentire il calore anomalo che irradia dal suo corpo, e hai più o meno raggiunto una conclusione nella tua mente. Non ti aspettavi che l'influenza del Fiume sacro interferisse direttamente con l'altro potere che risiede in Ogier."
  },
  AvgDialog_130451_Content_37 = {
    Text = "Non è colpa tua — è l'influenza di alcune… altre cose."
  },
  AvgDialog_130451_Content_38 = {
    Text = "Inoltre, sebbene questo fango nero mi abbia intrappolato per un momento, non mi ha fatto del male… Deve essere perché tu lo stavi tenendo sotto controllo, giusto? Davvero straordinario."
  },
  AvgDialog_130451_Content_39 = {
    Text = "Dopo un breve silenzio, senti finalmente la voce soffocata del giovane."
  },
  AvgDialog_130451_Content_4 = {
    Text = "……Basta! Come potrei mai — verso il mio signore—"
  },
  AvgDialog_130451_Content_40 = {
    Text = "…Grazie. Ti ho fatto consolare me ancora una volta."
  },
  AvgDialog_130451_Content_41 = {
    Text = "Si sta facendo tardi. Ti prego, permettimi prima di medicarti le ferite, e poi di scortarti nella tua stanza."
  },
  AvgDialog_130451_Content_5 = {
    Text = "Sai da tempo che Giurasfranto·Ogier lotta contro la presenza invisibile che si aggrappa a lui, ma la sua reazione oggi sembra insolitamente esagerata."
  },
  AvgDialog_130451_Content_6 = {
    Text = "Così ti giri e ti avvicini a lui."
  },
  AvgDialog_130451_Content_7 = {
    Text = "Ogier? Stai bene? Sta cercando di controllarti di nuovo?"
  },
  AvgDialog_130451_Content_8 = {Text = "!"},
  AvgDialog_130451_Content_9 = {
    Text = "Giurasfranto·Ogier alza di scatto la testa — stava fissando intensamente la punta delle proprie scarpe — e indietreggia di un passo tremante."
  },
  AvgDialog_130453_Content_1 = {
    Text = "Date le abilità speciali di Saya, tutti sono stati in apprensione su come potrebbe reagire all'influenza del Fiume sacro."
  },
  AvgDialog_130453_Content_10 = {
    Text = "Tutto ciò che ho vissuto mi rende quella che sono, ma c'è ancora tanto che devo imparare."
  },
  AvgDialog_130453_Content_11 = {
    Text = "\"L'istinto è riprodursi\", eh. Ah… capisco…"
  },
  AvgDialog_130453_Content_12 = {
    Text = "Mentre parla, ti porge un cuscino."
  },
  AvgDialog_130453_Content_13 = {
    Text = "Lasci uscire un lungo respiro di sollievo, appoggiandoti all'indietro proprio come fa lei."
  },
  AvgDialog_130453_Content_14 = {
    Text = "Capisco... quindi dopo tutto quello che hai passato, la ragione prevale sull'istinto..."
  },
  AvgDialog_130453_Content_15 = {
    Text = "<Small: Anche dopo essere diventata una Risvegliatore, Saya resta davvero unica...>"
  },
  AvgDialog_130453_Content_16 = {
    Text = "Saya—se non è troppo disturbo, posso usare casa tua come rifugio sicuro?!"
  },
  AvgDialog_130453_Content_17 = {
    Text = "I tuoi occhi si riempiono di lacrime di puro sollievo mentre avanzi la tua disperata richiesta."
  },
  AvgDialog_130453_Content_18 = {
    Text = "In questo momento, ciò che conta di più è che il povero Custode dei Mythag ha finalmente un rifugio sicuro affidabile."
  },
  AvgDialog_130453_Content_19 = {
    Text = "Eh? Anche se non capisco bene…"
  },
  AvgDialog_130453_Content_2 = {
    Text = "Eppure, con sorpresa di tutti, resta semplicemente in piedi accanto alla finestra in silenzio. La sua pelle pallida è quasi traslucida, come se fosse sigillata in un altro mondo."
  },
  AvgDialog_130453_Content_20 = {
    Text = "Saya aggrottò le sopracciglia con aria di finta difficoltà, e solo dopo aver visto la tua espressione delusa — proprio come sperava — tornò a sorridere."
  },
  AvgDialog_130453_Content_21 = {
    Text = "Saya aggrotta le sopracciglia in una giocosa esitazione, sorridendo solo dopo aver visto l'espressione delusa sul tuo volto."
  },
  AvgDialog_130453_Content_22 = {
    Text = "Certo che puoi. Ma... %player%, in cambio, potresti dirmi:"
  },
  AvgDialog_130453_Content_23 = {
    Text = "Chi è la persona a cui tieni di più?"
  },
  AvgDialog_130453_Content_24 = {
    Text = "Come due amici intimi che condividono tutto, vi immergete in una conversazione piacevole e spensierata."
  },
  AvgDialog_130453_Content_25 = {
    Text = "Una figura appare nella tua coscienza, chiudi gli occhi con serenità e offri la tua benedizione al futuro di Saya — che questa presenza possa attraversare il lungo scorrere del tempo."
  },
  AvgDialog_130453_Content_26 = {
    Text = "Una certa figura affiora nella tua mente. Chiudi gli occhi, rilassato, offrendo una benedizione silenziosa per il futuro di Saya—purché quei sentimenti non finiscano davvero per distruggere il mondo. Ma chi lo sa?"
  },
  AvgDialog_130453_Content_27 = {
    Text = "Il potere del Fiume sacro scorre tra voi come una dolce marea, silenzioso e senza fretta."
  },
  AvgDialog_130453_Content_3 = {
    Text = "Salve, Custode."
  },
  AvgDialog_130453_Content_4 = {
    Text = "Saya... ti senti bene? C'è qualcosa che... non va?"
  },
  AvgDialog_130453_Content_5 = {
    Text = "Come se percepisse la tua preoccupazione, la ragazza ruota leggermente sui talloni—"
  },
  AvgDialog_130453_Content_6 = {
    Text = "niente febbre, niente battito accelerato, niente strana euforia. Nulla di strano."
  },
  AvgDialog_130453_Content_7 = {
    Text = "Non preoccuparti per me. Sembra che non mi sia successo nulla di speciale."
  },
  AvgDialog_130453_Content_8 = {
    Text = "Quindi l'istinto della specie di Lady Thais è la riproduzione... ma potrebbe influenzare anche me?"
  },
  AvgDialog_130453_Content_9 = {
    Text = "Si siede più vicino a te, accoccolandosi su un morbido cuscino e sorridendo come un piccolo animale innocuo."
  },
  AvgDialog_130454_Content_1 = {
    Text = "Nella sala vuota, rimanevano solo gli echi dei tuoi e dei passi di Murphy."
  },
  AvgDialog_13049_Content_1 = {
    Text = "Ogier stringe forte la sua arma, attento a ogni fruscio intorno a lui. Ai suoi occhi, ogni suono potrebbe essere un'imboscata nemica."
  },
  AvgDialog_13049_Content_10 = {
    Text = "Il suono dell'acqua? Dev'essere l'orologio ad acqua laggiù."
  },
  AvgDialog_13049_Content_11 = {
    Text = "Sembra provenire da fuori! Vado a controllare!"
  },
  AvgDialog_13049_Content_12 = {
    Text = "Non abbiate fretta! Andiamo insieme!"
  },
  AvgDialog_13049_Content_13 = {
    Text = "Prima che tu possa fermarlo, Ogier afferra la sua arma e si precipita verso l'ingresso del palazzo."
  },
  AvgDialog_13049_Content_14 = {
    Text = "Questo è—?!"
  },
  AvgDialog_13049_Content_15 = {
    Text = "Attacco nemico!"
  },
  AvgDialog_13049_Content_2 = {
    Text = "Non trovate parole per confortarlo. Le righe del fascicolo del Risvegliatore che un tempo avete letto con attenzione vi balenano davanti—"
  },
  AvgDialog_13049_Content_3 = {
    Text = [[
Resoconto del Risvegliatore: Ogier Dansk, Cavaliere del Ducato di @2
Caduto nella Notte della Difesa Nazionale...]]
  },
  AvgDialog_13049_Content_4 = {
    Text = "Vi prego, rifugiatevi nei sobborghi, {Male=Sir,Female=Miss}. Qui possiamo cavarcela noi..."
  },
  AvgDialog_13049_Content_5 = {
    Text = "Voi due cavalieri non sapete nemmeno distinguere l'aconito dalle orchidee; e se preparaste del veleno invece che una medicina?"
  },
  AvgDialog_13049_Content_6 = {
    Text = "Il rifiuto schietto allenta la tensione. Ogier arrossisce fino alle orecchie, il Cavaliere Guardiano trattiene una risata, e persino da dietro la porta giunge una risatina soffocata."
  },
  AvgDialog_13049_Content_7 = {
    Text = "Non potete andarvene—non finché siete intrappolati nel mistero che ruota attorno a Ogier. Partire avventatamente potrebbe portare a conseguenze imprevedibili."
  },
  AvgDialog_13049_Content_8 = {Text = "Tic-tac—"},
  AvgDialog_13049_Content_9 = {
    Text = "Avete sentito qualcosa?"
  },
  AvgDialog_13050_Content_1 = {
    Text = "Finalmente, la battaglia si conclude. Tu e Ogier restate sui gradini sottostanti a ripulire la sala del palazzo, mentre il Cavaliere Guardiano è già tornato a vegliare fuori dalla stanza della principessa."
  },
  AvgDialog_13050_Content_10 = {
    Text = "...<Italic: Fruscio>..."
  },
  AvgDialog_13050_Content_11 = {
    Text = "Tuttavia... la pestilenza si trasforma in mostri che la gente comune non può vedere?"
  },
  AvgDialog_13050_Content_12 = {
    Text = "Sembra davvero assurdo. Anche se i poeti di corte lo cantassero, ben pochi ci crederebbero."
  },
  AvgDialog_13050_Content_13 = {
    Text = "All'inizio, mio padre e io pensavamo fosse una maledizione lanciata dai maghi del regno vicino, ma presto... anche le loro terre furono devastate dalla pestilenza."
  },
  AvgDialog_13050_Content_14 = {
    Text = "Persino io... coff, coff..."
  },
  AvgDialog_13050_Content_15 = {
    Text = "Mentre parla, un colpo di tosse straziante esplode da dietro la porta."
  },
  AvgDialog_13050_Content_16 = {
    Text = "Principessa, vi prego, smettete di parlare per ora. Vi prego, tornate a letto."
  },
  AvgDialog_13050_Content_17 = {
    Text = "...<Italic: Fruscio>..."
  },
  AvgDialog_13050_Content_18 = {
    Text = "Attendente! Torna ad aiutarci! La principessa—"
  },
  AvgDialog_13050_Content_19 = {Text = "Ugh!"},
  AvgDialog_13050_Content_2 = {
    Text = "È la prima volta che combattiamo nemici invisibili. Quando tutto questo sarà finito, dovremmo trovare un bardo che trasformi la storia in una canzone... che ne dici?"
  },
  AvgDialog_13050_Content_20 = {
    Text = "Il suono secco di ossa che si spezzano riecheggia nell'aria. Qualcosa si fa strada con forza attraverso il tessuto muscolare strettamente connesso, e un liquido cremisi schizza ovunque."
  },
  AvgDialog_13050_Content_21 = {Text = "Cosa...?"},
  AvgDialog_13050_Content_22 = {
    Text = "Sir Fernando!!!"
  },
  AvgDialog_13050_Content_23 = {
    Text = "Il Cavaliere Guardiano tossisce, sangue misto a frammenti di tessuto gli sgorga dalla gola. I suoi occhi si spalancano increduli, colmi di confusione e paura."
  },
  AvgDialog_13050_Content_3 = {
    Text = "Ho già un titolo: <Italic:Gli Occhi di Dansk, la Spada di Fernando>!"
  },
  AvgDialog_13050_Content_4 = {
    Text = "Sentendo il suo nome, Ogier alza lo sguardo, con le mani ricoperte di D-melma. Esita, incerto su come pulirle, visibilmente imbarazzato."
  },
  AvgDialog_13050_Content_5 = {
    Text = "Il mio nome in una canzone? Cosa ho fatto per meritare un simile onore..."
  },
  AvgDialog_13050_Content_6 = {
    Text = "Eh eh... L'Attendente e io non possiamo avere una menzione?"
  },
  AvgDialog_13050_Content_7 = {
    Text = "Ma certo! Il vostro nome sarà nel primissimo verso di questa canzone!"
  },
  AvgDialog_13050_Content_8 = {
    Text = "...<Italic: Fruscio>..."
  },
  AvgDialog_13050_Content_9 = {
    Text = "Principessa @1 Suite... Che ne dite? Ho un talento per la poesia?"
  },
  AvgDialog_13051_Content_1 = {
    Text = "Che... che è successo?"
  },
  AvgDialog_13051_Content_10 = {
    Text = "Sir Fernando... ricordo che era figlio unico nella sua famiglia."
  },
  AvgDialog_13051_Content_11 = {
    Text = "Se solo fossi stato più vigile..."
  },
  AvgDialog_13051_Content_12 = {
    Text = "Non incolparti per questo. Quei @1 mostri colpiscono senza preavviso. Abbiamo fatto tutto il possibile."
  },
  AvgDialog_13051_Content_13 = {
    Text = "Ogier scuote la testa; le tue deboli parole di conforto chiaramente non sono riuscite a placarlo. In quel momento, un lieve bussare proviene da dietro."
  },
  AvgDialog_13051_Content_14 = {
    Text = "Attendente, prendi Ogier e andate via."
  },
  AvgDialog_13051_Content_15 = {Text = "Perché!"},
  AvgDialog_13051_Content_16 = {
    Text = "Voi... non avete più bisogno di me? So di non essere riuscito a salvare Sir Fernando, ma..."
  },
  AvgDialog_13051_Content_17 = {
    Text = "La peste ha portato malattie, guerra e dolore... Restando qui non fate altro che preparare un altro banchetto per essa."
  },
  AvgDialog_13051_Content_18 = {
    Text = "La sua voce trema, eppure parla con tono scherzoso. Di fronte all'incombente minaccia della morte, non mostra alcuna traccia di paura."
  },
  AvgDialog_13051_Content_19 = {
    Text = "Suppongo... che Sir Fernando non vorrebbe ricongiungersi con voi così presto, non è vero?"
  },
  AvgDialog_13051_Content_2 = {
    Text = "Passi flebili e incerti provengono dall'interno, seguiti dallo scorrere del chiavistello della porta—"
  },
  AvgDialog_13051_Content_20 = {
    Text = "Ma... questo... è il mio dovere..."
  },
  AvgDialog_13051_Content_21 = {
    Text = "Ormai... sono rimasto solo io... Porterò avanti la volontà di Sir Fernando... Devo farlo..."
  },
  AvgDialog_13051_Content_22 = {
    Text = "Un lungo sospiro rassegnato giunge da dietro la porta. Dopo un momento, la principessa si rivolge a voi."
  },
  AvgDialog_13051_Content_23 = {
    Text = "Attendente, promettetemi... quando la mia voce scomparirà del tutto, dovrete portare via Ogier, anche se doveste tramortirlo, d'accordo?"
  },
  AvgDialog_13051_Content_24 = {
    Text = "...Come desiderate."
  },
  AvgDialog_13051_Content_25 = {
    Text = "Ogier stringe la sua arma con forza, le nocche bianche per la pressione. È come se la lancia tra le sue braccia fosse la sua famiglia dal destino ignoto, la principessa morente o Fernando, ormai perduto per sempre."
  },
  AvgDialog_13051_Content_26 = {
    Text = "Fissa l'ingresso del palazzo con lo sguardo perso, la mente lontana. Nemmeno il fragore del portone colpito con violenza riesce a riportarlo alla realtà."
  },
  AvgDialog_13051_Content_27 = {
    Text = "Ogier? Ogier?"
  },
  AvgDialog_13051_Content_28 = {
    Text = "Qualcuno sta arrivando."
  },
  AvgDialog_13051_Content_29 = {
    Text = "Qualcuno... sta arrivando? I cavalieri sono tornati!?"
  },
  AvgDialog_13051_Content_3 = {
    Text = "Non uscire!"
  },
  AvgDialog_13051_Content_30 = {
    Text = "Il portone viene spalancato con forza, ma lo stendardo che sventola nel vento non è del colore che speravate."
  },
  AvgDialog_13051_Content_4 = {
    Text = "Vostra Altezza... vi prego, restate dentro..."
  },
  AvgDialog_13051_Content_5 = {
    Text = "Ogier si sforza di allontanare il corpo di Sir Fernando dalla porta, poi strappa una tenda per coprire la pozza di sangue che si espande prima che possa infiltrarsi all'interno."
  },
  AvgDialog_13051_Content_6 = {
    Text = "Gli aculei del Mutante hanno trafitto l'armatura pettorale e la carne, riducendo il torace a un ammasso sanguinolento come se fosse esploso dall'interno. Sir Fernando è già morto tra atroci sofferenze."
  },
  AvgDialog_13051_Content_7 = {
    Text = "...D'accordo."
  },
  AvgDialog_13051_Content_8 = {
    Text = "Vi prego, fate il possibile per dargli degna sepoltura."
  },
  AvgDialog_13051_Content_9 = {
    Text = "Tu e Ogier vi scambiate uno sguardo, avvolgete in silenzio il corpo del cavaliere in un tappeto, poi vi sedete a terra davanti alla porta della camera da letto. Il dolore e l'angoscia riempiono l'aria."
  },
  AvgDialog_13052_Content_1 = {
    Text = "Quale nemico? Dove?!"
  },
  AvgDialog_13052_Content_10 = {
    Text = "Li vedete anche voi, {Male=Sir,Female=Miss}?"
  },
  AvgDialog_13052_Content_11 = {
    Text = "Gli rivolgi uno sguardo rassicurante e insisti."
  },
  AvgDialog_13052_Content_12 = {
    Text = "Ogier non è mai stato un ragazzo incline a fare storie senza motivo, e voi lo sapete meglio di chiunque altro dopo esservi allenato con lui, non è vero?"
  },
  AvgDialog_13052_Content_13 = {
    Text = "Anche se lo dite voi, io davvero non vedo nulla..."
  },
  AvgDialog_13052_Content_14 = {
    Text = "...Aspettate, Sir Fernando."
  },
  AvgDialog_13052_Content_15 = {
    Text = "Un colpo proviene dalla direzione della camera. La voce fragile della principessa richiama tutti verso la porta."
  },
  AvgDialog_13052_Content_16 = {
    Text = "Hanno ragione... Quelli sono i nemici invisibili che diffondono la pestilenza."
  },
  AvgDialog_13052_Content_17 = {
    Text = "Se lo dice la principessa..."
  },
  AvgDialog_13052_Content_18 = {
    Text = "Stringendo i denti, il Cavaliere Guardiano alza la sua arma e si schiera al tuo fianco."
  },
  AvgDialog_13052_Content_19 = {
    Text = "Indicami la posizione del nemico e farò del mio meglio per assistervi in battaglia!"
  },
  AvgDialog_13052_Content_2 = {
    Text = "Anche il Cavaliere Guardiano scende di corsa le scale fino a voi, completamente sconcertato."
  },
  AvgDialog_13052_Content_3 = {
    Text = "Non è il momento di scherzare. Non abbassate la guardia."
  },
  AvgDialog_13052_Content_4 = {
    Text = "Non sto scherzando! Non li—non li vedete?!"
  },
  AvgDialog_13052_Content_5 = {
    Text = "Ogier cerca di spiegare con ansia, ma il Cavaliere Guardiano resta scettico."
  },
  AvgDialog_13052_Content_6 = {
    Text = "Non è colpa sua; dopotutto, i nemici che tu e Ogier avete sconfitto erano interamente aberrazioni derivate dalla Dissoluzione."
  },
  AvgDialog_13052_Content_7 = {
    Text = "Coloro che riescono a osservare visivamente il D-fenomeno sono estremamente rari. Ogier è uno dei pochi sfortunati eppure fortunati."
  },
  AvgDialog_13052_Content_8 = {
    Text = "Vi prego, credeteci."
  },
  AvgDialog_13052_Content_9 = {
    Text = "Vi prego, credeteci. Credete nell'integrità di Ogier."
  },
  AvgDialog_13053_Content_1 = {
    Text = "Ultimo Atto"
  },
  AvgDialog_13053_Content_10 = {Text = "..."},
  AvgDialog_13053_Content_11 = {
    Text = "Lascia che Ogier resti a guardia del palazzo. Dopotutto, è un legittimo Cavaliere Guardiano nominato dal Granduca, non è vero?"
  },
  AvgDialog_13053_Content_12 = {
    Text = "Il cavaliere non riesce a trovare altri motivi per rifiutare. Annuisce in segno di assenso e insieme fate ritorno al palazzo."
  },
  AvgDialog_13053_Content_13 = {
    Text = "Il palazzo è vuoto; persino quella chiassosa cameriera se n'è andata. A parte voi tre, rimane solo la principessa."
  },
  AvgDialog_13053_Content_14 = {
    Text = "Bussi alla porta dorata della camera da letto. Il suono riecheggia attraverso i corridoi silenziosi, vuoto e pesante come il sospiro di una tomba."
  },
  AvgDialog_13053_Content_15 = {
    Text = "Principessa? State bene?"
  },
  AvgDialog_13053_Content_16 = {
    Text = "Non c'è risposta. Attendi un momento prima di bussare di nuovo."
  },
  AvgDialog_13053_Content_17 = {
    Text = "Principessa, siamo qui—io, il Cavaliere Guardiano e Ogier."
  },
  AvgDialog_13053_Content_18 = {
    Text = "Attraverso la pesante porta di legno giunge il fruscio di tessuti. Qualcuno sta lottando per mettersi seduto a letto."
  },
  AvgDialog_13053_Content_19 = {
    Text = "...Sciocchezze."
  },
  AvgDialog_13053_Content_2 = {Text = "\"Sogno\""},
  AvgDialog_13053_Content_20 = {
    Text = "Andatevene... tutti quanti. Andate con gli altri. Non c'è bisogno di sorvegliare un cadavere."
  },
  AvgDialog_13053_Content_21 = {
    Text = "Il respiro della ragazza è flebile, la sua voce sottile come il ronzio di una zanzara. Sembra che il solo rispondervi abbia prosciugato tutte le sue forze."
  },
  AvgDialog_13053_Content_22 = {
    Text = "La peste si è diffusa senza controllo nel Ducato, senza risparmiare nemmeno la nobiltà. La principessa si è ammalata prima dell'inizio della guerra, e ormai le mancano persino le forze per alzarsi dal letto."
  },
  AvgDialog_13053_Content_23 = {
    Text = "Il medico di corte ha dichiarato che è troppo debole per essere spostata dal palazzo—anche il minimo sobbalzo potrebbe costarle la vita."
  },
  AvgDialog_13053_Content_24 = {
    Text = "Principessa..."
  },
  AvgDialog_13053_Content_25 = {
    Text = "Non importa cosa direte, non me ne andrò. Vi prego, permettetemi di proteggervi... di adempiere al mio giuramento cavalleresco."
  },
  AvgDialog_13053_Content_26 = {Text = "..."},
  AvgDialog_13053_Content_27 = {
    Text = "...Allora non avvicinatevi troppo alla mia stanza. La peste è irreversibile, almeno... non lasciate che contagi anche voi."
  },
  AvgDialog_13053_Content_28 = {
    Text = "Ogni volta che la clessidra ad acqua si svuota, venite a parlarmi, d'accordo? Quando non risponderò più... dovreste andarvene."
  },
  AvgDialog_13053_Content_3 = {
    Text = "Cospirazioni si agitano nell'oscurità, accendendo la miccia posata dalla peste. La guerra esplode da un giorno all'altro."
  },
  AvgDialog_13053_Content_4 = {
    Text = "L'incurabile <Yellow:pestilenza> si è già diffusa in tutto il Ducato. Le guardie cittadine, afflitte dalla malattia e dal dolore, sono impotenti contro la cavalleria invasore."
  },
  AvgDialog_13053_Content_5 = {
    Text = "Persino i cavalieri reali si sono spinti oltre il fossato per ordine del Granduca, unendosi all'ultima linea di difesa della capitale."
  },
  AvgDialog_13053_Content_6 = {
    Text = "Ogier, perché sei ancora qui?"
  },
  AvgDialog_13053_Content_7 = {
    Text = "Io... Voglio montare la guardia con voi."
  },
  AvgDialog_13053_Content_8 = {
    Text = "Sei troppo giovane; la guerra... non è ancora un fardello che ti spetta. Va', cerca la tua famiglia e fuggi in un luogo sicuro."
  },
  AvgDialog_13053_Content_9 = {
    Text = "La casa di Ogier, la Tenuta Dansk... dovrebbe trovarsi al di fuori della linea difensiva, giusto?"
  },
  AvgDialog_13054_Content_1 = {
    Text = "Sogno, o Ideale"
  },
  AvgDialog_13054_Content_10 = {
    Text = "Attendente, potresti fare una commissione per me, per favore?"
  },
  AvgDialog_13054_Content_100 = {
    Text = "Riguardo a quello di cui abbiamo appena parlato... Davvero non lo dirai alla principessa?"
  },
  AvgDialog_13054_Content_101 = {
    Text = "Come? Non ti fidi di me?"
  },
  AvgDialog_13054_Content_102 = {
    Text = "Sì! Certo che mi fido! Non dubiterei mai di te!"
  },
  AvgDialog_13054_Content_103 = {
    Text = "Allora dovrò ricattarti con questo piccolo segreto."
  },
  AvgDialog_13054_Content_104 = {Text = "Ricattare?"},
  AvgDialog_13054_Content_105 = {
    Text = "Ti inginocchi su un ginocchio, portando i tuoi occhi al livello del cucciolo agitato, poi tendi la mano."
  },
  AvgDialog_13054_Content_106 = {
    Text = "Posso prometterti di non dirlo a nessuno. Ma in cambio del mio silenzio, devi promettermi una cosa."
  },
  AvgDialog_13054_Content_107 = {
    Text = "Quest'epoca non conosce la tradizione della promessa del mignolo, ma Ogier, un po' confuso, intreccia comunque il suo mignolo al tuo."
  },
  AvgDialog_13054_Content_108 = {
    Text = "Purché sia qualcosa che posso fare..."
  },
  AvgDialog_13054_Content_109 = {
    Text = "Molto bene, mi riserverò il diritto di esprimere un desiderio. Un giorno, in futuro, potrei venire a riscuoterlo. Non dimenticarlo allora, \"Sir Ogier\"."
  },
  AvgDialog_13054_Content_11 = {
    Text = "Se si tratta della seconda ipotesi, allora svegliare il sognatore potrebbe essere una via d'uscita?"
  },
  AvgDialog_13054_Content_12 = {
    Text = "Ehi! Attendente? Svegliati!"
  },
  AvgDialog_13054_Content_13 = {
    Text = "I tuoi pensieri seguono i deboli indizi sempre più lontano, e proprio quando il tuo piano \"Sveglia il Sognatore\" inizia a prendere forma, delle unghie si conficcano nel tuo braccio. Il dolore ti riporta bruscamente alla realtà."
  },
  AvgDialog_13054_Content_14 = {
    Text = "Aaah—! Fa male!"
  },
  AvgDialog_13054_Content_15 = {
    Text = "Quindi senti il dolore! Ti stavamo chiamando da un'eternità, e tu lì impalato/a come una statua. Hai qualche problema alle orecchie?"
  },
  AvgDialog_13054_Content_16 = {
    Text = "Ultimamente sei sempre con la testa fra le nuvole. Sei troppo stanco/a? Vorresti tornare alla tenuta di famiglia per riposarti un po'? È da molto che non prendi una vacanza."
  },
  AvgDialog_13054_Content_17 = {
    Text = "No... mi scuso. È solo che... ho alcune cose per la testa..."
  },
  AvgDialog_13054_Content_18 = {
    Text = "La chiave per fuggire dal \"Sogno\" deve risiedere in Ogier. Sebbene tu sia curioso/a di sapere com'è il mondo oltre il centro del sogno, non puoi allontanarti troppo in questo momento."
  },
  AvgDialog_13054_Content_19 = {
    Text = "Cose per la testa? Di cosa si tratta? Forse ti sei innamorato/a di qualcuno e ne sei turbato/a?"
  },
  AvgDialog_13054_Content_2 = {
    Text = [[
Nel "Sogno"
Palazzo della Principessa]]
  },
  AvgDialog_13054_Content_20 = {
    Text = "Temi che l'altra persona non ricambi i tuoi sentimenti? Principessa, perché non fate una piccola divinazione per il nostro caro attendente? O meglio ancora, dategli/datele una pozione d'amore... {Male=him,Female=her}"
  },
  AvgDialog_13054_Content_21 = {
    Text = "Non dire sciocchezze. Come possiamo usare la magia o le pozioni per mantenere una relazione?"
  },
  AvgDialog_13054_Content_22 = {
    Text = "La principessa sorride dolcemente, ignorando le provocazioni della cameriera. Ti fa cenno di avvicinarti."
  },
  AvgDialog_13054_Content_23 = {
    Text = "Ogier si sta allenando con i cavalieri. Per favore, vai a controllare come sta per me, e assicurati che il ragazzo non si faccia male."
  },
  AvgDialog_13054_Content_24 = {
    Text = "Come desiderate!"
  },
  AvgDialog_13054_Content_25 = {
    Text = "Tempismo perfetto: la principessa ti offre su un piatto d'argento un motivo per avvicinarti a Ogier."
  },
  AvgDialog_13054_Content_26 = {
    Text = "Ma se dovessi aver bisogno di una pozione, puoi sempre venire da me."
  },
  AvgDialog_13054_Content_27 = {
    Text = [[
Nel "Sogno"
Campo d'addestramento dell'Ordine dei Cavalieri]]
  },
  AvgDialog_13054_Content_28 = {
    Text = "Guidato da altri attendenti, attraversi il labirinto del castello e dei giardini fino a raggiungere il campo d'addestramento."
  },
  AvgDialog_13054_Content_29 = {
    Text = "Il nitido clangore delle lame misto a grida di incitamento e scherno rimbomba sul campo come un tuono: qualcuno sta combattendo sotto il sole cocente."
  },
  AvgDialog_13054_Content_3 = {
    Text = "Dopo il terzo tentativo di svegliarti senza notare alcun cambiamento nella scena davanti a te, finalmente accetti la verità: sei intrappolato/a nei ricordi di Ogier."
  },
  AvgDialog_13054_Content_30 = {
    Text = "Non ti aspetti, tuttavia, che uno dei combattenti sia Ogier."
  },
  AvgDialog_13054_Content_32 = {Text = "Ngh...!"},
  AvgDialog_13054_Content_33 = {
    Text = "Di fronte a una disparità di forza così assoluta, la perseveranza e la determinazione contano poco. Il cavaliere adulto non ha nemmeno usato tutta la sua forza, eppure l'impatto degli scontri tra le armi ha già fatto perdere la presa a Ogier."
  },
  AvgDialog_13054_Content_34 = {
    Text = "La lancia viene scaraventata via. Madido di sudore e senza fiato, il ragazzo crolla sul terreno ruvido e ghiaioso."
  },
  AvgDialog_13054_Content_35 = {
    Text = "Ragazzo, torna indietro per ora. Se continui ad allenarti così, ti spezzerai le mani."
  },
  AvgDialog_13054_Content_36 = {
    Text = "Già, sei ancora troppo giovane. Torna ad allenarti tra un paio d'anni. A malapena riesci a sollevare un'arma adesso."
  },
  AvgDialog_13054_Content_37 = {Text = "No..."},
  AvgDialog_13054_Content_38 = {
    Text = "Ogier trema in tutto il corpo mentre si china a raccogliere la lancia caduta. Con grande sforzo, aggiusta la posizione, puntando la punta della lancia verso il cavaliere avversario."
  },
  AvgDialog_13054_Content_39 = {
    Text = "Posso ancora... resistere!"
  },
  AvgDialog_13054_Content_4 = {
    Text = "Te ne stai in un angolo della camera della principessa, assumendo la posa perfetta di un diligente ascoltatore, interpretando docilmente il ruolo di attendente."
  },
  AvgDialog_13054_Content_40 = {
    Text = "Questo moccioso è testardo come un mulo..."
  },
  AvgDialog_13054_Content_41 = {
    Text = "Il volto del ragazzo è arrossato per la fatica e la mancanza d'ossigeno. Vedendo la sua tenace forza di volontà, il Comandante che intendeva far arrendere Ogier attraverso l'allenamento finalmente prende la parola."
  },
  AvgDialog_13054_Content_42 = {
    Text = "Niente male davvero. Con i nemici che guardano con avidità al nostro Ducato, abbiamo bisogno di più ragazzi con il fegato del giovane Maestro Dansk."
  },
  AvgDialog_13054_Content_43 = {
    Text = "Allora faccio sul serio?"
  },
  AvgDialog_13054_Content_44 = {
    Text = "Non essere così avventato! Se alleni questo ragazzo fino a farlo crollare, come lo spiegherai al Granduca e alla Principessa?"
  },
  AvgDialog_13054_Content_45 = {
    Text = "Inizia con l'addestramento fisico di base. Tienilo d'occhio; non lasciare che le armi lo feriscano."
  },
  AvgDialog_13054_Content_46 = {
    Text = "Le parole del Comandante accendono Ogier. Gli occhi del ragazzo si illuminano all'istante, traboccanti di entusiasmo."
  },
  AvgDialog_13054_Content_47 = {
    Text = "Accettate di farmi entrare nell'Ordine dei Cavalieri?!"
  },
  AvgDialog_13054_Content_48 = {
    Text = "Anche senza la battuta del Granduca, con una forza di volontà simile, hai le qualità per essere un cavaliere apprendista."
  },
  AvgDialog_13054_Content_49 = {
    Text = "Il Comandante si ferma, lo sguardo si addolcisce mentre osserva gli arti graffiati e sanguinanti di Ogier."
  },
  AvgDialog_13054_Content_5 = {
    Text = "Principessa, principessa! Ho sentito che il giovane Maestro Dansk si è presentato di nuovo all'Ordine dei Cavalieri... è il terzo giorno consecutivo!"
  },
  AvgDialog_13054_Content_50 = {
    Text = "Per oggi torna indietro. Domani ti darò un programma di addestramento personalizzato— E voi altri! Smettetela di restare a bocca aperta! Due giri extra di esercizi con i pesi per tutti!"
  },
  AvgDialog_13054_Content_51 = {
    Text = "Pietà, Comandante—"
  },
  AvgDialog_13054_Content_52 = {
    Text = "Prima ancora che le parole del Comandante svaniscano, una protesta sfacciata emerge dalla folla—i giovani cavalieri che si sfogano in quest'atmosfera spensierata."
  },
  AvgDialog_13054_Content_53 = {Text = "Tre round!"},
  AvgDialog_13054_Content_54 = {
    Text = "Tra i lamenti collettivi, Ogier finalmente si rilassa e crolla a terra con un tonfo."
  },
  AvgDialog_13054_Content_55 = {
    Text = "Bene... finalmente..."
  },
  AvgDialog_13054_Content_56 = {
    Text = "Ogier, possiamo parlare?"
  },
  AvgDialog_13054_Content_57 = {
    Text = "Voi siete... il Signor Attendente! Vi prego di perdonare il mio aspetto indecoroso, io..."
  },
  AvgDialog_13054_Content_58 = {
    Text = "Ogier scatta in piedi all'istante. L'escoriazione sul ginocchio striscia contro la sabbia, torcendogli l'espressione tra dolore e tensione."
  },
  AvgDialog_13054_Content_59 = {
    Text = "Gli fai cenno di lasciar perdere e tiri fuori una piccola fiala che la principessa ti ha infilato in tasca poco prima."
  },
  AvgDialog_13054_Content_6 = {
    Text = "Ha preso davvero sul serio le parole di nostro padre... È solo un bambino, come può resistere al loro addestramento?"
  },
  AvgDialog_13054_Content_60 = {
    Text = "Eh... Non fa male? Non dovrebbe essere una medicina?"
  },
  AvgDialog_13054_Content_61 = {
    Text = "È una formulazione speciale della principessa in persona. Dev'essere stata trattata appositamente."
  },
  AvgDialog_13054_Content_62 = {
    Text = "La principessa che \"tu\" servi è una ragazza misteriosa: schiva, eppure dotata di una conoscenza sorprendente dei rimedi erboristici. Nella tua epoca, sarebbe una farmacista rinomata."
  },
  AvgDialog_13054_Content_63 = {
    Text = "Ma qui, in quest'epoca dimenticata secoli fa, i suoi talenti vengono fraintesi. Hai sentito altri servitori chiamarla segretamente \"strega\" più di una volta."
  },
  AvgDialog_13054_Content_64 = {
    Text = "La pozione della principessa?! È troppo preziosa, come posso usarla— Ahi!"
  },
  AvgDialog_13054_Content_65 = {
    Text = "Stai fermo. Vuoi sprecare la sua gentilezza? Siediti, lascia che ti curi le ferite."
  },
  AvgDialog_13054_Content_66 = {
    Text = "Timoroso di sprecare un rimedio così raro, Ogier alla fine si siede in silenzio. Gli altri cavalieri lasciano gradualmente il campo, e ti rendi conto che questa è la tua occasione."
  },
  AvgDialog_13054_Content_67 = {
    Text = "Ogier, riesci a percepire che stai sognando?"
  },
  AvgDialog_13054_Content_68 = {
    Text = "Beh... sì. Sembra un sogno..."
  },
  AvgDialog_13054_Content_69 = {
    Text = "Il ragazzo interpreta male le tue parole nel modo che meglio si adatta alla situazione attuale. Sospira a occhi chiusi, la voce colma di soddisfazione e nostalgia."
  },
  AvgDialog_13054_Content_7 = {
    Text = "No... non è giusto... forse ci sono altre possibilità."
  },
  AvgDialog_13054_Content_70 = {
    Text = "Essere convocato, scelto, guadagnare il rispetto dei cavalieri... Sembra davvero un sogno."
  },
  AvgDialog_13054_Content_71 = {
    Text = "<LightGray:(Dovrei dirgli direttamente che questo è un sogno? Ma non ho ancora capito cosa sia davvero questo posto. Un ricordo? O un sogno...?)>"
  },
  AvgDialog_13054_Content_72 = {
    Text = "La tua esitazione attira l'attenzione di Ogier. All'improvviso diventa inquieto, strofinando nervosamente l'orlo dei suoi vestiti."
  },
  AvgDialog_13054_Content_73 = {
    Text = "{Male=Sir,Female=Miss}, la... la principessa è insoddisfatta di me?"
  },
  AvgDialog_13054_Content_74 = {Text = "..."},
  AvgDialog_13054_Content_75 = {
    Text = "Ogier, sei nato in una famiglia nobile. Avresti potuto vivere tutta la vita negli agi e nella sicurezza... allora perché scegliere questa strada? Perché vuoi diventare un cavaliere?"
  },
  AvgDialog_13054_Content_76 = {
    Text = "Perché... perché..."
  },
  AvgDialog_13054_Content_77 = {
    Text = "La voce di Ogier si fa sempre più flebile per l'imbarazzo, la testa che si abbassa sempre di più. Qualunque sia la ragione, evidentemente lo fa vergognare."
  },
  AvgDialog_13054_Content_78 = {
    Text = "Lo giuro, nessun'altra anima verrà mai a sapere della nostra conversazione."
  },
  AvgDialog_13054_Content_79 = {
    Text = "Perché... anche mio padre è malato, proprio come zia Merinte nelle cucine e fratello Pedro nei giardini..."
  },
  AvgDialog_13054_Content_8 = {
    Text = "Stando al racconto della cameriera, Ogier sta attualmente svolgendo l'addestramento presso l'Ordine dei Cavalieri. Dato che Ogier non ha partecipato a questa conversazione, l'ipotesi che questo sia un \"ricordo di Ogier\" non regge."
  },
  AvgDialog_13054_Content_80 = {
    Text = "E molti, molti altri. Tutti hanno la stessa malattia."
  },
  AvgDialog_13054_Content_81 = {
    Text = "Mio padre non riesce nemmeno più ad alzarsi dal letto, ma io non sono ancora cresciuto... Come suo unico erede, io..."
  },
  AvgDialog_13054_Content_82 = {
    Text = "Se mio padre dovesse morire, tutti nella tenuta verrebbero congedati. Ma sono ancora malati... senza nessun altro posto dove andare."
  },
  AvgDialog_13054_Content_83 = {
    Text = "Devo... devo assumermi la responsabilità per tutti... Solo diventando un cavaliere e ottenendo il favore del Granduca..."
  },
  AvgDialog_13054_Content_84 = {
    Text = "Nel dire questo, il volto di Ogier impallidisce. Ti guarda con ansia, come se temesse che tu possa accusarlo di \"secondi fini\" o punirlo per conto della principessa."
  },
  AvgDialog_13054_Content_85 = {
    Text = "La stessa innocenza giovanile, la stessa volontà tenace. È senza dubbio l'Ogier che conosci."
  },
  AvgDialog_13054_Content_86 = {
    Text = "Scusa, {Male=Sir,Female=Miss}... Se, se desideri che la principessa mi sostituisca... non mi lamenterò affatto..."
  },
  AvgDialog_13054_Content_87 = {
    Text = "La notte in cui sei stato scelto dal Granduca, hai giurato sull'onore della tua famiglia davanti a tutti gli ospiti, non è vero?"
  },
  AvgDialog_13054_Content_88 = {
    Text = "Hai giurato di adempiere ai doveri di un cavaliere con la tua vita... Eri sincero quando hai recitato il giuramento insieme agli altri?"
  },
  AvgDialog_13054_Content_89 = {
    Text = "<Big:Certo! Ogni parola era sincera!>"
  },
  AvgDialog_13054_Content_9 = {
    Text = "Questo non è solo un \"ricordo\". Forse sei entrato/a in un evento storico reale, o forse è un sogno basato sul subconscio di qualcuno?"
  },
  AvgDialog_13054_Content_90 = {
    Text = "\"Sarò per sempre leale, per sempre devoto\"... Anche mio padre vorrebbe che facessi così."
  },
  AvgDialog_13054_Content_91 = {
    Text = "Va bene, va bene, non dirò nulla alla principessa. Non preoccuparti così tanto; le lacrime stanno per caderti."
  },
  AvgDialog_13054_Content_92 = {
    Text = "L-Lacrime?! Chiedo scusa!"
  },
  AvgDialog_13054_Content_93 = {
    Text = "Ugh... I miei occhi... mi fanno male..."
  },
  AvgDialog_13054_Content_94 = {
    Text = "Ogier cerca a tentoni il suo fazzoletto, ma è già incrostato di polvere dall'allenamento. Questa passata non fa che peggiorare il disastro sul volto di Ogier."
  },
  AvgDialog_13054_Content_95 = {
    Text = "Farmi vedere così da te... Sono un caso disperato..."
  },
  AvgDialog_13054_Content_96 = {
    Text = "Non fa niente. Ti ho visto in condizioni ben peggiori. Torniamo prima al palazzo per ripulirti. Non possiamo lasciarti tornare a casa conciato così."
  },
  AvgDialog_13054_Content_97 = {Text = "..."},
  AvgDialog_13054_Content_98 = {
    Text = "{Male=Sir,Female=Miss}, posso chiederti un favore?"
  },
  AvgDialog_13054_Content_99 = {
    Text = "Dimmi pure, ti ascolto."
  },
  AvgDialog_13055_Content_1 = {
    Text = "Fili del Passato"
  },
  AvgDialog_13055_Content_10 = {
    Text = "Ristabilire il Legame"
  },
  AvgDialog_13055_Content_11 = {
    Text = "Vedendo Ogier vacillare sempre più vicino alla perdita di controllo, decidi di non aspettare oltre. Afferri saldamente le sue mani, ormai ricoperte di fanghiglia nera."
  },
  AvgDialog_13055_Content_12 = {
    Text = "La Chiave d'argento tremola. Guidi i tuoi filamenti mentali attraverso la Tempesta di Gnosi, attraversando strati di oscurità per stabilire nuovamente il Legame con Ogier."
  },
  AvgDialog_13055_Content_13 = {
    Text = "Accompagnate da un lieve pizzicore simile a una scarica elettrica, delle immagini lampeggiano davanti ai tuoi occhi e svaniscono in un istante."
  },
  AvgDialog_13055_Content_14 = {
    Text = "I segni della frenesia si ritirano come una marea calante. Le condizioni di Ogier si stabilizzano, sebbene il suo volto giovanile mostri un accenno di spossatezza."
  },
  AvgDialog_13055_Content_15 = {
    Text = "Mio signore, quanto ho resistito questa volta?"
  },
  AvgDialog_13055_Content_16 = {
    Text = "Il timer ha coperto a malapena metà del suo cerchio. Senza il Legame, Ogier non è riuscito a resistere più a lungo della sessione di addestramento precedente."
  },
  AvgDialog_13055_Content_17 = {
    Text = "Hmm... 30 secondi, più 200 millisecondi."
  },
  AvgDialog_13055_Content_18 = {
    Text = "Come... com'è possibile...!"
  },
  AvgDialog_13055_Content_19 = {
    Text = "Il suo tono è ansioso; dopotutto, questo <Yellow:Addestramento alla Separazione del Legame> è stata una sua idea."
  },
  AvgDialog_13055_Content_2 = {
    Text = "Campi di Addestramento dell'Università di Mythag\nAl Crepuscolo"
  },
  AvgDialog_13055_Content_20 = {
    Text = "Continua a rimuginare sull'anomalia del giorno della Cerimonia di Conferimento della Chiave, temendo che un giorno possa perdere il controllo e rivolgere la lancia contro tutti voi. A tal fine, vuole potenziare la sua capacità di mantenere la lucidità senza il Legame."
  },
  AvgDialog_13055_Content_21 = {
    Text = "Mio signore, riproviamo!"
  },
  AvgDialog_13055_Content_22 = {
    Text = "Ci siamo allenati abbastanza. L'allenamento sotto fatica sarà controproducente."
  },
  AvgDialog_13055_Content_23 = {
    Text = "Gli occhi di Ogier brillano di determinazione, poi si spengono. La sua voce è venata di rimprovero verso se stesso:"
  },
  AvgDialog_13055_Content_24 = {
    Text = "Non ci avevo pensato bene..."
  },
  AvgDialog_13055_Content_25 = {Text = "..."},
  AvgDialog_13055_Content_26 = {
    Text = "Non ho missioni nemmeno domani. Ci vediamo dopo pranzo, stesso posto."
  },
  AvgDialog_13055_Content_27 = {
    Text = "Mio Signore!"
  },
  AvgDialog_13055_Content_28 = {
    Text = "Sotto il suo sguardo esuberante da cucciolo, trascini il tuo corpo altrettanto esausto fino al dormitorio."
  },
  AvgDialog_13055_Content_29 = {
    Text = "Ti dai una rinfrescata veloce e crolli sul letto morbido. Con un ringraziamento silenzioso al gusto di Mythag in fatto di biancheria, la tua coscienza si dissolve gradualmente..."
  },
  AvgDialog_13055_Content_3 = {
    Text = "La Chiave d'argento brilla. Guidi l'invisibile e delicato filo d'argento nella tua mente, ritraendolo dal punto di luce scintillante."
  },
  AvgDialog_13055_Content_30 = {Text = "..."},
  AvgDialog_13055_Content_31 = {
    Text = "Una melodia strana e armoniosa risuona nell'oscurità, accompagnata dal tintinnio di calici d'argento. Il sogno trabocca di un'atmosfera vivace ma elegante."
  },
  AvgDialog_13055_Content_32 = {
    Text = "Che rumore... Chi è... che organizza un banchetto nei dormitori a mezzanotte...?"
  },
  AvgDialog_13055_Content_33 = {
    Text = "Ti giri e allunghi la mano verso la coperta che hai scalciato giù dal letto."
  },
  AvgDialog_13055_Content_34 = {
    Text = "La tua mano affonda nella nebbia, afferrando qualcosa che sembra una nuvola di pioggia — il suo tocco è al contempo reale e illusorio."
  },
  AvgDialog_13055_Content_35 = {
    Text = "Oh, eccoti. Ti stavo proprio cercando."
  },
  AvgDialog_13055_Content_36 = {Text = "Cosa...?"},
  AvgDialog_13055_Content_37 = {
    Text = "Mi sento di nuovo le gambe deboli. Potresti andare da mio padre e portare qui il mio cavaliere?"
  },
  AvgDialog_13055_Content_38 = {
    Text = "Cavaliere...?"
  },
  AvgDialog_13055_Content_39 = {
    Text = "Cosa aspetti? Non hai sentito la principessa?"
  },
  AvgDialog_13055_Content_4 = {Text = "Ngh...!"},
  AvgDialog_13055_Content_40 = {
    Text = "Una donna ti colpisce forte sulla spalla. L'oscurità svanisce e una scena sconosciuta appare davanti ai tuoi occhi."
  },
  AvgDialog_13055_Content_41 = {
    Text = "Una sala maestosa, un'orchestra che suona antiche suite in lontananza, dolci squisiti e invitanti, e nobildonne che ti fissano tutte quante."
  },
  AvgDialog_13055_Content_42 = {
    Text = "E lì, circondata da loro, c'è una giovane ragazza adagiata su una morbida chaise longue."
  },
  AvgDialog_13055_Content_43 = {
    Text = "Non importa, non siate troppo severi con {Male=him,Female=her}. Il mio attendente è stato impegnato tutta la notte senza riposo per offrire a tutti un banchetto perfetto."
  },
  AvgDialog_13055_Content_44 = {
    Text = "La ragazza, chiamata dagli altri principessa, interviene gentilmente in tua difesa."
  },
  AvgDialog_13055_Content_45 = {
    Text = "Potresti portarmi il \"cavaliere\" che mio padre ha designato per me? Dopodiché potrai riposare per il resto della giornata, d'accordo?"
  },
  AvgDialog_13055_Content_46 = {
    Text = "Frammenti di memoria ti invadono la mente. Sono frammentari e incompleti, ma sufficienti per interpretare il ruolo di questo involucro: il primo attendente della principessa."
  },
  AvgDialog_13055_Content_47 = {
    Text = "...Vi ringrazio per la vostra grazia, Vostra Altezza."
  },
  AvgDialog_13055_Content_48 = {
    Text = "Il tuo corpo si inchina istintivamente. Tra sguardi invidiosi o sprezzanti, ti fai strada tra il gruppo di nobildonne verso la parte più affollata della sala."
  },
  AvgDialog_13055_Content_49 = {
    Text = "Abbassi lo sguardo sulle \"tue\" mani. Il tono della pelle è di qualche sfumatura più scuro del tuo, solitamente nascosto sotto i guanti. Sottili e lievi segni di cicatrici le ricoprono ovunque: chiaramente non sono le mani di qualcuno cresciuto nel lusso."
  },
  AvgDialog_13055_Content_5 = {
    Text = "Non sforzarti troppo. Se non riesci a resistere, collegati alla Pozza Nera!"
  },
  AvgDialog_13055_Content_50 = {
    Text = "Un vaso dorato ornato lungo il cammino conferma ulteriormente i tuoi sospetti—"
  },
  AvgDialog_13055_Content_51 = {
    Text = "il riflesso che proietta non è il tuo volto."
  },
  AvgDialog_13055_Content_52 = {
    Text = "Signore! Siete venuto per conto della principessa?"
  },
  AvgDialog_13055_Content_53 = {
    Text = "Una cameriera sbuca dalla folla, con occhi chiaramente più acuti dei tuoi; individua all'istante il \"te\" familiare nel mezzo della calca."
  },
  AvgDialog_13055_Content_54 = {
    Text = "<Small:Il Granduca ha nominato cavaliere un ragazzino! Vogliono davvero che un bambino così piccolo partecipi all'addestramento dei cavalieri? Dubito che riesca persino a sollevare un'arma.>"
  },
  AvgDialog_13055_Content_55 = {
    Text = "<BigItalic:Mi scusi, per favore fate largo. Siamo qui per ordine della Principessa @1 per un'udienza—>"
  },
  AvgDialog_13055_Content_56 = {
    Text = "<Small:Non l'avete visto prima; era rosso come un peperone quando il Granduca lo ha presentato a tutti.>"
  },
  AvgDialog_13055_Content_57 = {
    Text = "<BigItalic:Scusate! Il primo attendente della principessa richiede un'udienza!!>"
  },
  AvgDialog_13055_Content_58 = {
    Text = "<Small:Quanto ci vorrà perché un ragazzino come questo diventi un vero cavaliere... Il Granduca starà scherzando, no?>"
  },
  AvgDialog_13055_Content_59 = {
    Text = "La cameriera apre abilmente un varco tra la folla con le sue parole, sussurrandoti nel frattempo commenti scherzosi, e ti conduce fino al trono."
  },
  AvgDialog_13055_Content_6 = {
    Text = "Posso... ancora... resistere..."
  },
  AvgDialog_13055_Content_60 = {
    Text = "S-Salve. Voi siete il primo attendente, {Male=Sir,Female=Miss}?"
  },
  AvgDialog_13055_Content_61 = {
    Text = "Voi siete...!"
  },
  AvgDialog_13055_Content_62 = {
    Text = "Sono il figlio maggiore della Casata Dansk. Sono profondamente grato per il favore del Granduca, ed è un g-grande onore servire come cavaliere della Principessa @1."
  },
  AvgDialog_13055_Content_7 = {
    Text = "Ogier cade su un ginocchio. Con il Legame reciso, si sostiene con la lancia per non crollare del tutto."
  },
  AvgDialog_13055_Content_8 = {Text = "Maestro..."},
  AvgDialog_13055_Content_9 = {
    Text = "Un denso liquido nero trasuda dagli angoli dei suoi occhi, dalle labbra e dalle orecchie. I suoi organi sono già devastati da una melma nera amorfa—è facile immaginare l'agonia che il ragazzo sta sopportando."
  },
  AvgDialog_13056_Content_1 = {
    Text = "Una Nuova Ballata"
  },
  AvgDialog_13056_Content_10 = {
    Text = "Non avvicinatevi! Non avrò pietà!"
  },
  AvgDialog_13056_Content_100 = {
    Text = "Andiamo, è un giorno di riposo. Il Mercato del Distretto Est sarà in fermento. Possiamo anche fermarci all'orfanotrofio a vedere i bambini..."
  },
  AvgDialog_13056_Content_101 = {
    Text = "Mormorando il vostro itinerario come se nulla fosse, vi allontanate a grandi passi senza voltarvi. Non provate alcuna preoccupazione."
  },
  AvgDialog_13056_Content_102 = {
    Text = "Mio signore! Mio signore! Vi prego, ditemi come facevate a sapere—"
  },
  AvgDialog_13056_Content_103 = {
    Text = "Perché sapete che vi seguirà."
  },
  AvgDialog_13056_Content_11 = {
    Text = "Ogier alza la lancia, bloccando la scala."
  },
  AvgDialog_13056_Content_12 = {
    Text = "Questo è il mio ultimo avvertimento. Vi prego, lasciate il palazzo!"
  },
  AvgDialog_13056_Content_13 = {
    Text = "Ehi, avete sentito? Cos'ha appena detto? \"Vi prego\", lasciate il palazzo?"
  },
  AvgDialog_13056_Content_14 = {
    Text = "Hahahaha, è esilarante! Non c'è da stupirsi che il Ducato sia così debole—giocano ai cavalieri con un bambino."
  },
  AvgDialog_13056_Content_15 = {
    Text = "Fate silenzio; il vostro baccano mi fa male alle orecchie."
  },
  AvgDialog_13056_Content_16 = {
    Text = "Il sergente ignora l'avvertimento di Ogier, avanzando fino alla porta della camera, guardando Ogier dall'alto in basso."
  },
  AvgDialog_13056_Content_17 = {
    Text = "Fatti da parte."
  },
  AvgDialog_13056_Content_18 = {
    Text = "Ogier si sforza di tenere la lancia in orizzontale, cercando di bloccare l'avanzata del sergente."
  },
  AvgDialog_13056_Content_19 = {
    Text = "Vi prego, andatevene!"
  },
  AvgDialog_13056_Content_2 = {
    Text = "Gli stivali corazzati, trascinando scintille e polvere, calpestano il tappeto del palazzo."
  },
  AvgDialog_13056_Content_20 = {
    Text = "Sai, l'arma di un cavaliere non è adatta a te."
  },
  AvgDialog_13056_Content_22 = {
    Text = "La Resistenza è cosa fragile di fronte al potere assoluto. Il sergente para senza sforzo la lancia di Ogier e, con un gesto noncurante del polso, affonda un pugnale nel petto del ragazzo."
  },
  AvgDialog_13056_Content_23 = {Text = "Cough—!"},
  AvgDialog_13056_Content_24 = {
    Text = "Visto? Queste sono le abilità che dovresti imparare. Dopo la caduta della tua nazione, sarai adatto solo ai vicoli bui dove non batte il sole."
  },
  AvgDialog_13056_Content_25 = {
    Text = "Furto, fame e odio reciproco... questo è il tuo destino. E questa lancia, simbolo dell'onore cavalleresco? Allora ti sarà del tutto inutile."
  },
  AvgDialog_13056_Content_26 = {
    Text = "Il Sangue gli invade la trachea, provocando un'agonia sorda e soffocante, come annegare sulla terraferma. Ogni respiro si strozza nell'odore del Sangue."
  },
  AvgDialog_13056_Content_27 = {
    Text = "Vorresti lanciarti fuori da sotto il tavolino, spingere il sergente giù per le scale, proteggere Ogier inginocchiato accanto alla porta. Ma il tuo corpo ti tradisce. Tremante, rigido, si rifiuta di obbedire."
  },
  AvgDialog_13056_Content_28 = {
    Text = "No... cough..."
  },
  AvgDialog_13056_Content_29 = {
    Text = "Ah, mi sbagliavo su una cosa: non vivrai nemmeno abbastanza da vedere quel futuro. Farai la stessa fine di questo qui, combustibile per dare fuoco a questo palazzo."
  },
  AvgDialog_13056_Content_3 = {
    Text = "Questo è il vostro tappeto preferito in questo \"Sogno\". Voi e la loquace cameriera avete trascorso un intero pomeriggio a selezionarlo dal magazzino del Granduca, e un altro mezzo giorno a stenderlo."
  },
  AvgDialog_13056_Content_30 = {
    Text = "Lo stivale corazzato calpesta pesantemente il cadavere di Fernando, accompagnato dal clangore del metallo e dallo schiocco secco di ossa che si spezzano."
  },
  AvgDialog_13056_Content_31 = {
    Text = "...Fernan..."
  },
  AvgDialog_13056_Content_33 = {
    Text = "Il corpo di Ogier vibra di adrenalina; afferra la sua lancia e si scaglia contro il nemico!"
  },
  AvgDialog_13056_Content_34 = {
    Text = "<Big:NON TOCCARLO!>"
  },
  AvgDialog_13056_Content_36 = {Text = "UGH!"},
  AvgDialog_13056_Content_37 = {
    Text = "La Resistenza è futile. Il suo attacco non solo non riesce a smuovere il sergente, ma espone anche la schiena all'esploratore."
  },
  AvgDialog_13056_Content_38 = {
    Text = "Ragazzino testardo. Se fosse scappato fin dall'inizio, non ci saremmo nemmeno disturbati a inseguirlo, giusto?"
  },
  AvgDialog_13056_Content_39 = {
    Text = "Guardati, piccolo, così determinato... stai proteggendo qualcuno? La principessa è dietro questa porta?"
  },
  AvgDialog_13056_Content_4 = {
    Text = "La principessa esce dalla sua stanza — un evento raro. Si appoggia alla ringhiera del corridoio al secondo piano, osservando con aria svagata il vostro affaccendarvi nella sala sottostante. Ogier, venuto per un'udienza, è così nervoso da non sapere dove mettere i piedi."
  },
  AvgDialog_13056_Content_40 = {
    Text = "Il Sangue gli cola dalle orecchie. Ogier non riesce a distinguere ogni parola, ma coglie comunque quella più cruciale."
  },
  AvgDialog_13056_Content_41 = {
    Text = "No... andate via..."
  },
  AvgDialog_13056_Content_42 = {
    Text = "La sua vista comincia a sbiancarsi dai bordi. Una qualche forza sta trascinando la sua coscienza fuori dal suo corpo giovane."
  },
  AvgDialog_13056_Content_43 = {
    Text = "Striscia in avanti, oltre il cadavere di Fernando, oltre gli stivali del sergente e dell'esploratore, finché le sue dita non toccano finalmente la pesante porta di legno."
  },
  AvgDialog_13056_Content_44 = {
    Text = "Il legno è caldo al tatto, con una fragranza leggermente pungente. Dietro questa porta, una voce gentile lo chiamava un tempo. Ora, l'unico suono rimasto è il ticchettio costante della clessidra ad acqua."
  },
  AvgDialog_13056_Content_45 = {
    Text = "Andatevene... da qui..."
  },
  AvgDialog_13056_Content_46 = {
    Text = "<Big:AAAHHHHH—!>"
  },
  AvgDialog_13056_Content_47 = {
    Text = "Questa volta, è la sua stessa lancia a conficcarsi in profondità nella carne."
  },
  AvgDialog_13056_Content_48 = {
    Text = "L'arma derisa da molti e disprezzata dai nemici — quella che non ha mai lasciato andare dall'inizio alla fine."
  },
  AvgDialog_13056_Content_49 = {
    Text = "La punta della lancia gli trafigge il corpo, inchiodandolo alla porta. Non può muoversi."
  },
  AvgDialog_13056_Content_5 = {
    Text = "Questi non sono cavalieri del Ducato... Nascondersi! Presto!"
  },
  AvgDialog_13056_Content_50 = {
    Text = "Ohh—non essere così crudele. E se la \"Principessa Strega\" ci lanciasse una maledizione per aver torturato il suo cavaliere?"
  },
  AvgDialog_13056_Content_51 = {
    Text = "Una strega? Lei? Ridicolo."
  },
  AvgDialog_13056_Content_52 = {
    Text = "<Small:La Principessa @1... non è...>"
  },
  AvgDialog_13056_Content_53 = {
    Text = "Ogier resta a bocca aperta. Il nome della principessa è sulla punta della lingua, eppure non riesce proprio a ricordarlo."
  },
  AvgDialog_13056_Content_54 = {
    Text = "<Small:@1...>"
  },
  AvgDialog_13056_Content_55 = {
    Text = "Sente il suono dell'acqua che scorre. L'orologio ad acqua è caduto? Significa forse... che la Principessa è ancora viva?"
  },
  AvgDialog_13056_Content_56 = {
    Text = "<Small:No... non uscire... no... vattene...>"
  },
  AvgDialog_13056_Content_57 = {
    Text = "Basta... Ogier... Grazie..."
  },
  AvgDialog_13056_Content_58 = {
    Text = "Grazie... mio..."
  },
  AvgDialog_13056_Content_59 = {
    Text = "Dapprima, alcuni rivoli neri filtrano sotto la fessura della porta, mescolandosi al sangue di Ogier, come lacrime versate per qualcuno."
  },
  AvgDialog_13056_Content_6 = {
    Text = "Aspetta! E tu?!"
  },
  AvgDialog_13056_Content_60 = {
    Text = "Poi, un'inondazione torrenziale irrompe attraverso lo stipite della porta, spaccandolo. Ruggendo e montando, sommerge il palazzo in un istante."
  },
  AvgDialog_13056_Content_61 = {
    Text = "<Shake:GAH—Ugh!>"
  },
  AvgDialog_13056_Content_62 = {
    Text = "La pestilenza, invisibile alla gente comune, si abbatte sui due intrusi. Una melma nera sgorga nei loro occhi, naso e bocca, annegandoli a mezz'aria."
  },
  AvgDialog_13056_Content_63 = {
    Text = "<Shake:Maledizione... È una maledizione—>"
  },
  AvgDialog_13056_Content_65 = {
    Text = "Custode? Svegliati! Custode? %player%?"
  },
  AvgDialog_13056_Content_66 = {Text = "Ogier!"},
  AvgDialog_13056_Content_67 = {
    Text = "Hai avuto un incubo? Sono io."
  },
  AvgDialog_13056_Content_68 = {
    Text = "...Doll? Perché sei nella mia stanza?"
  },
  AvgDialog_13056_Content_69 = {
    Text = "Non mi interessa il contenuto del tuo incubo, ma la scorsa notte le tue onde spirituali erano attive come se stessero danzando."
  },
  AvgDialog_13056_Content_7 = {
    Text = "Ogier ti spinge con forza, facendoti scivolare sotto il tavolino basso. La vista ti si annebbia, e tutto ciò che riesci a vedere è il lussuoso tappeto persiano che si arriccia ai bordi a causa delle fiamme."
  },
  AvgDialog_13056_Content_70 = {
    Text = "I Risvegliatori collegati a te, me compresa, hanno più o meno percepito delle anomalie."
  },
  AvgDialog_13056_Content_71 = {
    Text = "La notte scorsa? ...È passata solo una notte? Era davvero solo un sogno..."
  },
  AvgDialog_13056_Content_72 = {
    Text = "Descrivi a Doll ogni dettaglio dell'assurdo sogno. La principessa, i cavalieri, la peste..."
  },
  AvgDialog_13056_Content_73 = {
    Text = "Tra gli Investigatori legati ai Risvegliatori, si verificano occasionalmente casi di memorie o emozioni condivise. Ma quello che hai descritto... non ne ho mai sentito parlare."
  },
  AvgDialog_13056_Content_74 = {
    Text = "Sembra che questo \"sogno\" non ti abbia causato ulteriori effetti. Continuerò a monitorare attentamente le tue onde spirituali."
  },
  AvgDialog_13056_Content_75 = {
    Text = "...Forse vorresti incontrare Ogier adesso?"
  },
  AvgDialog_13056_Content_76 = {
    Text = "La sensazione di essere divorati dalla D-melma era fin troppo reale. Il sole del mattino illumina le coperte, ma il calore che dovrebbe risultare confortante ora fa sentire il tuo corpo come immerso in acqua gelida."
  },
  AvgDialog_13056_Content_77 = {
    Text = "Ogier... giusto. Avevamo programmato di continuare l'allenamento oggi..."
  },
  AvgDialog_13056_Content_78 = {
    Text = "Università di Mythag  Campo di addestramento\nMattina"
  },
  AvgDialog_13056_Content_79 = {
    Text = "Wahhh—No, no, no, sto per morire—"
  },
  AvgDialog_13056_Content_8 = {
    Text = "Solo questo moccioso? Siamo sicuri di essere nel posto giusto?"
  },
  AvgDialog_13056_Content_80 = {
    Text = "Pietà, abbia pietà di questa povera piccola reporter, Sir Ogier—"
  },
  AvgDialog_13056_Content_81 = {
    Text = "Ancora un po', signorina Hanna—un altro giro e abbiamo finito. Supererai sicuramente questo test fisico!"
  },
  AvgDialog_13056_Content_82 = {
    Text = "Sob... va bene..."
  },
  AvgDialog_13056_Content_83 = {
    Text = "La mediatrice del campus ha i polpacci legati con sacchi di sabbia zavorrati mentre, in lacrime, fa jogging lentamente intorno alla pista. Ogier corre al suo fianco, incoraggiandola, mantenendo il passo senza il minimo sforzo."
  },
  AvgDialog_13056_Content_84 = {Text = "Ogier"},
  AvgDialog_13056_Content_85 = {Text = "Custode!"},
  AvgDialog_13056_Content_86 = {
    Text = "Affida la supervisione di Hannah a un altro membro dello staff e corre verso di te."
  },
  AvgDialog_13056_Content_87 = {
    Text = "Non avevi detto che il nostro allenamento inizia nel pomeriggio? Perché sei qui così presto?"
  },
  AvgDialog_13056_Content_88 = {
    Text = "Si è allenato con altri studenti e Risvegliatori per tutta la mattina, eppure si presenta davanti a te con gli occhi luminosi, pieno di reverenza e vigore."
  },
  AvgDialog_13056_Content_89 = {Text = "Io..."},
  AvgDialog_13056_Content_9 = {
    Text = "Esatto. La mappa strategica indica chiaramente che questo è il palazzo delle donne reali."
  },
  AvgDialog_13056_Content_90 = {
    Text = "... Dopo l'allenamento di Hannah, andiamo a fare una passeggiata nel centro di Londinium."
  },
  AvgDialog_13056_Content_91 = {Text = "Eh?"},
  AvgDialog_13056_Content_92 = {
    Text = "Ogier chiaramente non si aspettava che tu proponessi una pausa all'improvviso. Nemmeno tu te lo aspettavi."
  },
  AvgDialog_13056_Content_93 = {
    Text = "Mio signore, vi prego di permettermi di rifiutare. La crisi della Dissoluzione è imminente. Ma io... non sono ancora pronto."
  },
  AvgDialog_13056_Content_94 = {
    Text = "Devo concentrarmi interamente sull'affinare le mie abilità. Non ho tempo per attività così frivole."
  },
  AvgDialog_13056_Content_95 = {
    Text = "Allora lasciate che riformuli."
  },
  AvgDialog_13056_Content_96 = {
    Text = "Quel pomeriggio trascorso con lui nell'Ordine dei Cavalieri vi torna improvvisamente in mente. Ricordi che pensavate sarebbero svaniti con il sogno riaffiorano."
  },
  AvgDialog_13056_Content_97 = {
    Text = "È tempo di esaudire quel desiderio, Sir Ogier."
  },
  AvgDialog_13056_Content_98 = {Text = "!?"},
  AvgDialog_13056_Content_99 = {
    Text = "Come... Come facevi a saperlo?!"
  },
  AvgDialog_130571_Content_1 = {Text = "BANG—!"},
  AvgDialog_130571_Content_10 = {
    Text = "Ahi... ahia... Carboncino, scusa... Vortice... ti sta schiacciando."
  },
  AvgDialog_130571_Content_11 = {
    Text = "Va tutto bene. Ma Vortice, perché tutta questa fretta?"
  },
  AvgDialog_130571_Content_12 = {
    Text = "Ah! Vortice... caldo! Abbracciare Carboncino... stare meglio!"
  },
  AvgDialog_130571_Content_13 = {
    Text = "Vortice strano... non più freddo."
  },
  AvgDialog_130571_Content_14 = {
    Text = "Ma così caldo... così caldo..."
  },
  AvgDialog_130571_Content_15 = {
    Text = "(Non va bene. Potrebbe essere l'influenza del Fiume sacro?)"
  },
  AvgDialog_130571_Content_16 = {
    Text = "Vortice... non sapere..."
  },
  AvgDialog_130571_Content_17 = {
    Text = "Il Suo Sguardo si fa velato e sfocato. Le sue dita sottili scivolano tra le pieghe dei tuoi vestiti, tracciando delicatamente la superficie della tua pelle."
  },
  AvgDialog_130571_Content_18 = {
    Text = "Conosci fin troppo bene questa sensazione. In quei tuoi sogni, \"Carboncino\" si godeva spesso questo genere di \"coccole\" rannicchiato tra le sue braccia."
  },
  AvgDialog_130571_Content_19 = {
    Text = "Carboncino... abbraccio... stare calmo..."
  },
  AvgDialog_130571_Content_2 = {
    Text = "Carboncino! Abbraccio!"
  },
  AvgDialog_130571_Content_20 = {
    Text = "Carboncino... buon profumo..."
  },
  AvgDialog_130571_Content_21 = {
    Text = "Si avvicina, annusandoti piano. Non sai se sia un profumo persistente o la tua natura unica a placare infine il suo Spirito."
  },
  AvgDialog_130571_Content_22 = {
    Text = "Ma una cosa è certa: non puoi permettere che questo continui sul pavimento."
  },
  AvgDialog_130571_Content_23 = {
    Text = "Il legno è duro contro la tua schiena, e la tua vita implora già il conforto di un materasso."
  },
  AvgDialog_130571_Content_24 = {
    Text = "Che ne dici di tenermi così a letto stanotte? Dormiamo insieme."
  },
  AvgDialog_130571_Content_25 = {
    Text = "Sì! Carboncino, amore! Volere abbraccio!"
  },
  AvgDialog_130571_Content_26 = {
    Text = "Abbracciare Carboncino... dormire, ora di dormire..."
  },
  AvgDialog_130571_Content_27 = {
    Text = "Cogli l'occasione per guidarla verso il letto. Vi adagiate tra le coperte soffici, stretti in un Abbraccio e con gli occhi fissi l'uno nell'altra, proprio come faceste un tempo su quella nave."
  },
  AvgDialog_130571_Content_28 = {
    Text = "Vortice... non caldo ora... Vortice... così felice..."
  },
  AvgDialog_130571_Content_29 = {
    Text = "Nanna-nanna... zzz... Carboncino... zzz..."
  },
  AvgDialog_130571_Content_3 = {Text = "V-Vortice?"},
  AvgDialog_130571_Content_4 = {
    Text = "Vortice irrompe improvvisamente nella stanza. Ti getta le braccia attorno alla vita, affondando il viso nel tuo petto mentre i suoi lunghi capelli argentei ti solleticano la pelle."
  },
  AvgDialog_130571_Content_5 = {
    Text = "Tiri un silenzioso sospiro di sollievo. Sembra che abbia avuto la premura di ritrarre l'\"oggetto orribile\" sulla sua mano sinistra, risparmiandoti il rischio di un morso accidentale."
  },
  AvgDialog_130571_Content_6 = {
    Text = "Carboncino... stare bene..."
  },
  AvgDialog_130571_Content_7 = {
    Text = "Vortice, aspetta—aspetta un momento—ah!"
  },
  AvgDialog_130571_Content_8 = {Text = "Thud."},
  AvgDialog_130571_Content_9 = {
    Text = "Come temevi, Vortice non riesce a controllare la propria forza. Lo slancio vi fa rotolare entrambi a terra."
  },
  AvgDialog_131200_Content_1 = {
    Text = "Catene Tenere"
  },
  AvgDialog_131200_Content_10 = {
    Text = "Arachne accarezza la metà rimasta della sua guancia. Mentre chiude delicatamente gli occhi morti, l'imponente pilastro alle sue spalle emette un debole bagliore."
  },
  AvgDialog_131200_Content_11 = {
    Text = "Arachne tende la mano. Le ultime braci all'interno del pilastro vorticano come sabbia fine, danzando attorno alle sue dita sottili prima di disperdersi sul pavimento."
  },
  AvgDialog_131200_Content_12 = {
    Text = "Braci residue... avevamo ragione. È qui che Nefraea aveva nascosto le braci, ma le ha già reclamate."
  },
  AvgDialog_131200_Content_13 = {
    Text = "Prende le braci, uccide le marionette... qual è il suo scopo finale?"
  },
  AvgDialog_131200_Content_14 = {Text = "Hm?"},
  AvgDialog_131200_Content_15 = {
    Text = "Qualcosa la fa trasalire. Arachne alza lo sguardo, fissando attraverso l'emblema della Lanterna sulla vetrata la stazione in lontananza."
  },
  AvgDialog_131200_Content_16 = {
    Text = "Arachne? Che succede?"
  },
  AvgDialog_131200_Content_17 = {
    Text = "Il mio corpo principale... non riesco più a percepire la sua presenza."
  },
  AvgDialog_131200_Content_18 = {Text = "!!!"},
  AvgDialog_131200_Content_19 = {
    Text = "Vuoi dire che ha lasciato il teatro?"
  },
  AvgDialog_131200_Content_2 = {
    Text = "Dita, tibie, occhi, costole, cranio... Davanti a te giace una bambola adorata fatta a pezzi dalla sua padrona, i suoi resti abbandonati ad annegare nel fango e nel sangue."
  },
  AvgDialog_131200_Content_20 = {
    Text = "Mentre noi davamo la caccia alle marionette, il mio corpo principale stava epurando gli Scudieri Abissali in tutta la città. Dopo aver trovato \"Memorie,\" è venuta in questa chiesa per incontrarci."
  },
  AvgDialog_131200_Content_21 = {
    Text = "Era così vicina... ma ora, la sua luce è svanita."
  },
  AvgDialog_131200_Content_22 = {
    Text = "Le è successo qualcosa? Ma \"Memorie\" è appena morta... come..."
  },
  AvgDialog_131200_Content_23 = {
    Text = "Non conosco i dettagli. Ma prima di svanire, ha toccato la tela per inviare un ultimo messaggio. Oltre all'ordine di fare Ritorno, ha lasciato una sola parola."
  },
  AvgDialog_131200_Content_24 = {Text = "\"Estasi.\""},
  AvgDialog_131200_Content_25 = {Text = "Estasi...?"},
  AvgDialog_131200_Content_26 = {
    Text = "Il detestabile volto sorridente di N ti balena davanti agli occhi."
  },
  AvgDialog_131200_Content_27 = {
    Text = "Non capisco. Condividete le stesse memorie—devi sapere cosa intendeva."
  },
  AvgDialog_131200_Content_28 = {
    Text = "Arachne scuote la testa."
  },
  AvgDialog_131200_Content_29 = {
    Text = "Il tuo Fato è una Farfalla che non oso sfiorare; qualsiasi spiegazione causerebbe incalcolabili increspature."
  },
  AvgDialog_131200_Content_3 = {
    Text = "\"Memorie\"..."
  },
  AvgDialog_131200_Content_30 = {
    Text = "Ma sappi questo: nel tuo futuro immediato, \"Rapimento\" è una chiave. Aprirà la serratura segreta che hai davanti."
  },
  AvgDialog_131200_Content_31 = {
    Text = "Il mio... futuro? Vuoi dire che ora riesci davvero a vedere il mio Filo del Fato?!"
  },
  AvgDialog_131200_Content_32 = {
    Text = "Sostieni il suo sguardo. In quel sorriso gentile, scorgi l'innegabile Autorità del Fato."
  },
  AvgDialog_131200_Content_33 = {
    Text = "...Qualunque cosa accada, fidati di me. E fidati di te stessa."
  },
  AvgDialog_131200_Content_34 = {
    Text = "Fa' Ritorno al Teatro del Fato. La chiave e la serratura ti attendono là, %player%."
  },
  AvgDialog_131200_Content_35 = {Text = "Ma..."},
  AvgDialog_131200_Content_36 = {
    Text = "La voce di Arachne è calda come un Tramonto d'autunno. La sua forma si dissolve in un filo di seta di ragno, svanendo nella luce fioca della cattedrale."
  },
  AvgDialog_131200_Content_37 = {
    Text = "Sotto il bagliore caleidoscopico delle vetrate, solo braci dimensionali aleggiano sul sangue rappreso e gli arti mozzati."
  },
  AvgDialog_131200_Content_38 = {
    Text = "\"Estasi\"..."
  },
  AvgDialog_131200_Content_39 = {
    Text = "Mormori quella parola, poi torni a volgere lo sguardo verso le spoglie delle \"Memorie.\""
  },
  AvgDialog_131200_Content_4 = {
    Text = "Raccogli con delicatezza le spoglie della ragazza. I fluidi vischiosi e il sangue macchiano i tuoi vestiti mentre stringi i suoi arti recisi."
  },
  AvgDialog_131200_Content_40 = {
    Text = "Immersi in un fluido torbido e nella luce sacra, i frammenti sembrano fondersi con la cattedrale stessa."
  },
  AvgDialog_131200_Content_41 = {Text = "..."},
  AvgDialog_131200_Content_42 = {
    Text = "Il Sentiero di seta trema. Quando sali sul palco, ogni marionetta si immobilizza a metà della sua esibizione."
  },
  AvgDialog_131200_Content_43 = {
    Text = "Innumerevoli Occhi da ogni Dimensione si volgono verso di te — colmi di curiosità, Euforia e una terrificante reverenza."
  },
  AvgDialog_131200_Content_44 = {
    Text = "È una grandiosa, silenziosa cerimonia di benvenuto. Gli artisti sono diventati il pubblico, e l'unico spettatore è diventato la stella."
  },
  AvgDialog_131200_Content_45 = {
    Text = "Forse ascoltare Arachne è stato un errore..."
  },
  AvgDialog_131200_Content_46 = {
    Text = "Stringi la presa sulla Chiave d'Argento, camminando in solitudine attraverso un silenzio sinistro."
  },
  AvgDialog_131200_Content_47 = {
    Text = "La nuova padrona del teatro vi attendeva, {Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_131200_Content_48 = {
    Text = "Le Ombre convergono sull'alto palco. D'istinto, ti slanci all'indietro e sollevi la Chiave d'Argento."
  },
  AvgDialog_131200_Content_49 = {
    Text = "Nuovo padrone?!"
  },
  AvgDialog_131200_Content_5 = {
    Text = "Forse... forse c'è un modo per salvarla. Il potere degli Eoni... una correzione del Destino..."
  },
  AvgDialog_131200_Content_50 = {
    Text = "Bentornato al teatro, {Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_131200_Content_51 = {
    Text = "Arachne, tu..."
  },
  AvgDialog_131200_Content_52 = {
    Text = "Mi dispiace, ma la nostra nuova Storia richiede la vostra partecipazione."
  },
  AvgDialog_131200_Content_53 = {
    Text = "La ragnatela vibra. La padrona del teatro si avvicina con passi misurati, la sua Voce ancora calda come il crepuscolo della sera."
  },
  AvgDialog_131200_Content_54 = {
    Text = "Tutt'intorno a te, le marionette — indistinguibili dalle Ancelle Ragno di Leng — si voltano e balzano verso di te all'unisono."
  },
  AvgDialog_131200_Content_55 = {Text = "!!!"},
  AvgDialog_131200_Content_6 = {
    Text = "Nefraea ha reciso i suoi fili. La sua storia ha raggiunto la fine, {Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_131200_Content_7 = {
    Text = "Il ronzio dell'arcolaio di Arachne resta calmo e distante."
  },
  AvgDialog_131200_Content_8 = {
    Text = "Anche \"Memorie\" è morta... questo significa...?"
  },
  AvgDialog_131200_Content_9 = {
    Text = "Nefraea possiede ora il potere di riscrivere l'intero Livello."
  },
  AvgDialog_131201_Content_1 = {
    Text = "Uff... gli scudieri di Nefraea sono un bel problema..."
  },
  AvgDialog_131201_Content_10 = {
    Text = "Tra venti giorni, inizierà a studiare seriamente i segreti celati in quel libro. Da quel momento in poi, questo Livello seguirà tutti gli altri, scivolando inesorabilmente verso la Distruzione Totale."
  },
  AvgDialog_131201_Content_100 = {
    Text = "L'Arciduca e sua moglie siedono sul retro della loro automobile scoperta, ammirando l'antica città. La gente insegue il veicolo, precipitandosi a capofitto verso il destino che fu scritto per loro molto tempo fa."
  },
  AvgDialog_131201_Content_11 = {
    Text = "Ricordi di questo mondo — nuovi e stranamente familiari — ti invadono la mente. Non hai mai visto un luogo così vibrante e fiorente."
  },
  AvgDialog_131201_Content_12 = {
    Text = "Hai visto troppo. Le immagini di paesaggi desolati e soffocati dalla cenere causati dalla Dissoluzione sovrascrivono facilmente questa prosperità, affollando la tua mente con visioni di Decomposizione."
  },
  AvgDialog_131201_Content_13 = {
    Text = "Arachne allunga la mano, le dita sfiorano delicatamente la luce del mattino che si riversa nel vicolo. Sta piangendo per l'ennesimo mondo sulla Soglia della Morte."
  },
  AvgDialog_131201_Content_14 = {
    Text = "Un mondo ignorato dagli dèi... Non avrei mai nemmeno immaginato che una cosa simile fosse possibile."
  },
  AvgDialog_131201_Content_15 = {
    Text = "Abbiamo ancora una possibilità di cambiarlo?"
  },
  AvgDialog_131201_Content_16 = {
    Text = "È proprio per questo che siamo qui."
  },
  AvgDialog_131201_Content_17 = {
    Text = "Dimmi. Cosa devo fare?"
  },
  AvgDialog_131201_Content_18 = {Text = "Aspetta!"},
  AvgDialog_131201_Content_19 = {
    Text = "Li hai notati, {Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_131201_Content_2 = {
    Text = "Ti appoggi al muro umido di un vicolo appartato, ansimando per riprendere fiato."
  },
  AvgDialog_131201_Content_20 = {
    Text = "Fuori dal vicolo, un gruppo di individui con frequenze spirituali inquietantemente anomale si sta avvicinando alla vostra posizione."
  },
  AvgDialog_131201_Content_21 = {
    Text = "Dietro di te, sopra di te, davanti a te... sempre più nemici si manifestano nella tua percezione."
  },
  AvgDialog_131201_Content_22 = {
    Text = "Siamo circondati!"
  },
  AvgDialog_131201_Content_23 = {
    Text = "Da quando abbiamo messo piede su questo Livello, ho lavorato per riparare il destino manomesso. Ma Correggere i destini di così tante persone non è un compito semplice."
  },
  AvgDialog_131201_Content_24 = {
    Text = "Nefraea ha lasciato questi ostacoli appositamente per impedire la mia opera di ripristino."
  },
  AvgDialog_131201_Content_25 = {
    Text = "Forse c'è un'altra via."
  },
  AvgDialog_131201_Content_26 = {
    Text = "Arachne, sono uno degli Operativi assegnati all'assassinio che la Mano di Ferro ha pianificato per oggi."
  },
  AvgDialog_131201_Content_27 = {
    Text = "Questo mondo brucerà perché quel principe studierà quel grimorio. Se riesco nell'assassinio, forse posso fermare tutto prima ancora che inizi!"
  },
  AvgDialog_131201_Content_28 = {
    Text = "Non è esattamente il modo giusto..."
  },
  AvgDialog_131201_Content_29 = {
    Text = "Eccoli! Prendeteli!"
  },
  AvgDialog_131201_Content_3 = {
    Text = "Non hai mai visto Arachne correre; semplicemente è in piedi accanto a te, calma come se fosse il suo destino assoluto trovarsi in questo preciso punto in questo preciso istante."
  },
  AvgDialog_131201_Content_30 = {
    Text = "Arachne pizzica una corda invisibile. Uno Scudiero bloccato a metà Mutazione all'ingresso del vicolo si arresta di colpo, trasformandosi in una Statua immobile."
  },
  AvgDialog_131201_Content_31 = {
    Text = "Il fragore lontano di trombe e sassofoni si diffonde nell'aria, accompagnato dal rombo basso e costante di motori in avvicinamento."
  },
  AvgDialog_131201_Content_32 = {
    Text = "Il complotto è stato scoperto; gli altri Assassini non riusciranno a portarlo a termine. Il principe è proprio lì. Se non agisco adesso, perderemo la nostra occasione!"
  },
  AvgDialog_131201_Content_33 = {
    Text = "Arachne guarda nei tuoi occhi frenetici. Esita, poi annuisce lentamente e deliberatamente."
  },
  AvgDialog_131201_Content_34 = {
    Text = "Se le correnti del Destino ci hanno condotti qui... forse compiere una Scelta per questo mondo è esattamente ciò che sei destinato a fare."
  },
  AvgDialog_131201_Content_35 = {
    Text = "Va'. Fa' ciò che devi, {Male=Sig.,Female=Sig.na} Custode. La Verità del Destino ti sarà rivelata qui."
  },
  AvgDialog_131201_Content_36 = {
    Text = "Non hai tempo di analizzare le sue parole. Annuisci e, con l'Assistenza di Arachne, ti lanci fuori dal vicolo e svanisci nella Folla in tumulto."
  },
  AvgDialog_131201_Content_37 = {
    Text = "Quello è l'Arciduca Flavian? L'erede dell'impero... chissà quanto costa un'automobile del genere."
  },
  AvgDialog_131201_Content_38 = {
    Text = "Bah! Figlio bastardo di un ladro! Ogni centesimo che spende è stato strappato dal nostro sangue e sudore!"
  },
  AvgDialog_131201_Content_39 = {
    Text = "Se non fossi uno storpio, sarei morto sul campo di battaglia caricando quei banditi!"
  },
  AvgDialog_131201_Content_4 = {
    Text = "Si è spinta a tanto... cosa sta cercando di ottenere davvero?"
  },
  AvgDialog_131201_Content_40 = {
    Text = "Shh! Le strade brulicano di Guardie Imperiali! Vuoi morire?!"
  },
  AvgDialog_131201_Content_41 = {Text = "..."},
  AvgDialog_131201_Content_42 = {
    Text = "Vi fate largo a gomitate nella calca fino a raggiungere finalmente il bordo del marciapiede, proprio mentre una decappottabile nuova fiammante sfila lentamente."
  },
  AvgDialog_131201_Content_43 = {
    Text = "Il principe ereditario, un uomo prossimo alla sessantina, siede sul sedile posteriore con la moglie. Salutano con grazia la folla, indicando l'architettura storica di Hvatz."
  },
  AvgDialog_131201_Content_44 = {
    Text = "Anche con i ricordi offuscati, conosci fin troppo bene la profonda sofferenza che questa casata reale ha inflitto alla terra."
  },
  AvgDialog_131201_Content_45 = {
    Text = "Temendo le conseguenze cosmiche dell'uso del vostro vero potere, ritraete la mano dalla Chiave d'Argento. Al suo posto, estraete la pistola che dovrebbe trovarsi lì e vi avvicinate al veicolo in lento movimento."
  },
  AvgDialog_131201_Content_46 = {
    Text = "Ehi! Tu, studente! Indietro!"
  },
  AvgDialog_131201_Content_47 = {
    Text = "Perdonatemi, Vostra Altezza. Ma dal momento che sono salito sul palco, devo recitare questa parte fino alla fine!"
  },
  AvgDialog_131201_Content_48 = {
    Text = "BANG BANG BANG!!"
  },
  AvgDialog_131201_Content_49 = {
    Text = "Nel caos delle strade, l'orgoglioso erede imperiale è sorprendentemente vulnerabile. Attingendo al vostro rigoroso addestramento, colmate la distanza con facilità e premete il grilletto."
  },
  AvgDialog_131201_Content_5 = {
    Text = "Nefraea ha lasciato un catalizzatore. All'interno della vasta Rete del Fato che governa questo mondo, ha contaminato un singolo filo."
  },
  AvgDialog_131201_Content_50 = {
    Text = "Mentre tre proiettili perforano il petto dell'Arciduca con precisione letale, il mondo intero si arresta."
  },
  AvgDialog_131201_Content_51 = {
    Text = "L'agonia dell'Arciduca, lo shock della Principessa, le guardie a metà passo — tutto si cristallizza in un grottesco, vivido dipinto a olio."
  },
  AvgDialog_131201_Content_52 = {
    Text = "!!! Questo è..."
  },
  AvgDialog_131201_Content_53 = {
    Text = "Dopo un battito di silenzio, i colori del dipinto iniziano a colare e sgocciolare. Tempo, spazio e gravità collassano in una frenesia caotica. Il vostro corpo sembra lacerarsi mentre un uragano di immagini vi lampeggia davanti agli occhi."
  },
  AvgDialog_131201_Content_54 = {
    Text = "Un funerale grandioso. La furia di un monarca. Guerra. Cannoni. Morte. Lo squillo dei corni di guerra e le urla dei civili. Avvoltoi che calano sui campi cremisi di Verdun per banchettare su quattrocentomila resti straziati."
  },
  AvgDialog_131201_Content_55 = {
    Text = "La caduta degli imperi, terre lacerate, re in esilio, e il grimorio... che si apre ancora una volta."
  },
  AvgDialog_131201_Content_56 = {
    Text = "Un liquido nero e viscoso inonda la vostra visuale. La tragedia familiare si ripete — oscurità assoluta e agonia, una corrosione che penetra in ogni singola cellula del vostro essere."
  },
  AvgDialog_131201_Content_57 = {
    Text = "Non preoccupatevi, {Male=Sig.,Female=Sig.na} Custode. Ora siete al sicuro."
  },
  AvgDialog_131201_Content_58 = {
    Text = "Una mano si posa sulla vostra spalla. I colori caotici e sanguinanti e l'oscurità sconfinata svaniscono."
  },
  AvgDialog_131201_Content_59 = {
    Text = "Spalanchi gli occhi. Il caffè è silenzioso come sempre; la pistola Browning è scomparsa dalla tua mano, e la Sachertorte appena servita è davanti a te, emanando un aroma irresistibile."
  },
  AvgDialog_131201_Content_6 = {
    Text = "In questa linea temporale corrotta, il principe ereditario di Phio-Garia ha scoperto un certo libro due mesi fa."
  },
  AvgDialog_131201_Content_60 = {
    Text = "Arachne... cosa... cos'è successo? Stavamo appena..."
  },
  AvgDialog_131201_Content_61 = {
    Text = "Non allarmatevi. Siamo semplicemente tornati al momento in cui siamo entrati per la prima volta nel caffè. Il lato positivo è che siamo riusciti a ottenere una tazza di caffè gratis."
  },
  AvgDialog_131201_Content_62 = {
    Text = "Arachne solleva la tazza e ne sorseggia un piccolo sorso, sorridendo. Il vostro riflesso attonito vi fissa dalla superficie del liquido scuro."
  },
  AvgDialog_131201_Content_63 = {
    Text = "I Fili del Fato non sono fatti per essere percepiti dai vostri occhi. Quando un attore esterno al palcoscenico tenta di alterare con la forza il destino di questo mondo, finisce inevitabilmente per perdersi nella trama."
  },
  AvgDialog_131201_Content_64 = {
    Text = "Passato e futuro, gli innumerevoli destini di questo palcoscenico che si intrecciano davanti ai tuoi occhi... questo è il vero volto della Trama del Fato."
  },
  AvgDialog_131201_Content_65 = {
    Text = "Il futuro... state dicendo che tutto ciò che ho visto era reale? Le guerre, i milioni di morti... sono stato davvero io a causare tutto questo?"
  },
  AvgDialog_131201_Content_66 = {
    Text = "Il Fato vi ha concesso di esserne testimone. Dopo l'assassinio dell'Arciduca, quello era in effetti Il Sentiero che il mondo avrebbe dovuto percorrere. Ma state tranquillo, {Male=Sig.,Female=Sig.na} Custode. Ho già ritessuto il destino di questo livello."
  },
  AvgDialog_131201_Content_67 = {
    Text = "Lanciate uno sguardo fuori dalla finestra. La folla è ancora in fermento, ma i cittadini e gli ufficiali corrotti dall'influenza di Nefraea sono svaniti senza lasciare traccia."
  },
  AvgDialog_131201_Content_68 = {
    Text = "Se fossi andato fino in fondo... se voi non aveste riparato il danno..."
  },
  AvgDialog_131201_Content_69 = {
    Text = "Fra un mese, la morte di quel Principe Ereditario avrebbe innescato la più grande guerra della storia. Otto imperi sarebbero stati trascinati nell'abisso, e venti milioni di anime sarebbero perite."
  },
  AvgDialog_131201_Content_7 = {
    Text = "Un grimorio di stregoneria proibita — capace di invocare una certa divinità che non appartiene a questa dimensione."
  },
  AvgDialog_131201_Content_70 = {
    Text = "Il suolo stesso sotto i nostri piedi si sarebbe ridotto in cenere. Di tutte le persone sedute attorno a noi in questo caffè, nemmeno una sarebbe sopravvissuta."
  },
  AvgDialog_131201_Content_71 = {
    Text = "Arachne fa roteare il suo caffè, osservando il flusso costante del traffico all'esterno. Parla con una calma terrificante, come se stesse semplicemente descrivendo gli ingredienti di un comune dessert."
  },
  AvgDialog_131201_Content_72 = {
    Text = "Il vivace brusio della strada raggiunge le vostre orecchie, una melodia di pace e prosperità che ora appare incredibilmente fragile."
  },
  AvgDialog_131201_Content_73 = {
    Text = "E la Dissoluzione? Perché uccidere il principe ha comunque portato alla fine del mondo?"
  },
  AvgDialog_131201_Content_74 = {
    Text = "In quella grande guerra, l'impero fu sconfitto. Il Monarca non ebbe altra scelta che accettare il crudele verdetto del Fato — finché non trovò un nuovo sentiero."
  },
  AvgDialog_131201_Content_75 = {
    Text = "Stregoneria proveniente dall'aldilà di questo mondo, una divinità che trascende ogni potere conosciuto... per un padre che ha perso il figlio e un Imperatore che ha perso la sua nazione, potrebbe esservi qualcosa di più seducente?"
  },
  AvgDialog_131201_Content_76 = {
    Text = "Il suo tono gentile vi fa correre un brivido lungo la schiena. Il peso schiacciante di due miliardi di vite si fa sentire come un fardello fisico che preme contro il vostro petto."
  },
  AvgDialog_131201_Content_77 = {
    Text = "<Shake:Non avrei mai immaginato che assassinare un principe potesse degenerare in tutto questo... Credevo di essere d'aiuto...>"
  },
  AvgDialog_131201_Content_78 = {
    Text = "Il Fato vi ha costretto a compiere quella scelta affinché poteste finalmente vederlo per ciò che è. Non potete scorgere i fili stessi, ma ora comprendete i modi intricati in cui sono intessuti."
  },
  AvgDialog_131201_Content_79 = {
    Text = "Questi fili formano una vasta trama. Il minimo tremore in un singolo filo può far crollare l'intera struttura."
  },
  AvgDialog_131201_Content_8 = {
    Text = "Arachne alza il capo, il suo sguardo fisso sui fili che tu non puoi vedere."
  },
  AvgDialog_131201_Content_80 = {
    Text = "Questo è il Fato — in tutta la sua terribile complessità."
  },
  AvgDialog_131201_Content_81 = {
    Text = "Fate un respiro profondo, cercando di calmare il cuore che ancora martella contro le costole per il terrore persistente."
  },
  AvgDialog_131201_Content_82 = {
    Text = "Almeno... almeno hai fermato la guerra..."
  },
  AvgDialog_131201_Content_83 = {
    Text = "Non ho fermato la guerra, {Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_131201_Content_84 = {
    Text = "Arachne scuote dolcemente il capo."
  },
  AvgDialog_131201_Content_85 = {
    Text = "Nel nuovo destino che ho tessuto, l'Imperatore sarà testimone di una mera frazione dei miracoli contenuti in quel grimorio. Quel assaggio di potere diverrà il fondamento stesso su cui edificherà la sua guerra."
  },
  AvgDialog_131201_Content_86 = {
    Text = "Il Monarca e i suoi alleati scateneranno un conflitto di proporzioni ancora più grandiose, trascinando imperi d'oltremare nella mischia."
  },
  AvgDialog_131201_Content_87 = {
    Text = "Il numero di persone che periranno in questa versione della storia sarà quattro volte superiore a prima."
  },
  AvgDialog_131201_Content_88 = {
    Text = "Continua la sua narrazione pacata, con il tono di una madre che racconta una fiaba della buonanotte a un bambino che non riesce a dormire."
  },
  AvgDialog_131201_Content_89 = {
    Text = "<Shake:Que… questo perché?>"
  },
  AvgDialog_131201_Content_9 = {
    Text = "Questo Livello non era mai stato destinato a connettersi con il divino. Per lungo tempo, avrebbe potuto essere risparmiato dal destino della Dissoluzione."
  },
  AvgDialog_131201_Content_90 = {
    Text = "Avete visto la complessità della tela. Evitare con la forza un evento destinato a compiersi non fa che invitare un esito assai più orribile."
  },
  AvgDialog_131201_Content_91 = {
    Text = "Il Monarca viene comunque sconfitto; la Conoscenza limitata contenuta in quel libro non offre all'impero alcuna salvezza duratura."
  },
  AvgDialog_131201_Content_92 = {
    Text = "Dopo questo secondo fallimento, la stregoneria verrà liquidata come una farsa. Nessun sovrano su questo Livello vi farà mai più ricorso."
  },
  AvgDialog_131201_Content_93 = {
    Text = "I loro occhi si volgeranno altrove. Riporranno la loro fede nella scienza, ricercando armi capaci di Divorare interi Pianeti. Godranno di una pace breve e tesa all'Ombra di questi armamenti, solo per essere distrutti dagli stessi strumenti che hanno creato."
  },
  AvgDialog_131201_Content_94 = {
    Text = "Questo Livello è comunque destinato a svanire in qualche futura apocalisse — è il suo fato ineluttabile. Ma per un tempo, godranno di un periodo di prosperità bello come un'opera d'arte."
  },
  AvgDialog_131201_Content_95 = {
    Text = "Lo Sguardo di Tohuwabohu verrà tenuto a bada, almeno per un po'."
  },
  AvgDialog_131201_Content_96 = {
    Text = "Il cucchiaio di Arachne gira lentamente nella tazza. Il vortice bruno scuro che crea appare identico ai motivi vorticosi che avete scorto nella Tela del Destino."
  },
  AvgDialog_131201_Content_97 = {
    Text = "China il capo. La luce del sole dalla finestra le ricade addosso come un sudario di lutto."
  },
  AvgDialog_131201_Content_98 = {
    Text = "Lottare, tessere, rammendare... eppure nulla cambia davvero. Questo è il Destino, {Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_131201_Content_99 = {
    Text = "Lo squillo di trombe e sassofoni filtra oltre la finestra, portando con sé gli Applausi e le Maledizioni della Folla lontana."
  },
  AvgDialog_131202_Content_1 = {Text = "Pop—"},
  AvgDialog_131202_Content_10 = {Text = "Credenti?"},
  AvgDialog_131202_Content_11 = {
    Text = "In vesti purpuree... non ho mai... mai visto nulla di simile..."
  },
  AvgDialog_131202_Content_12 = {
    Text = "Loro… hanno portato i \"Ricordi\" all'altare… <Shake:Uhm uhm……>"
  },
  AvgDialog_131202_Content_13 = {
    Text = "Via San Basilio... in una chiesa che appartiene a loro..."
  },
  AvgDialog_131202_Content_14 = {
    Text = "Osso e carne tremano mentre il vecchio lotta per strappare un ultimo respiro dal suo corpo devastato."
  },
  AvgDialog_131202_Content_15 = {
    Text = "Sa che Arachne non può percepire i fili di quegli uomini. Sa che questo è il suo ultimo dovere."
  },
  AvgDialog_131202_Content_16 = {
    Text = "Signorina... dei malfattori nelle ombre ci stanno dando la caccia... Lei ha corrotto i nostri destini..."
  },
  AvgDialog_131202_Content_17 = {
    Text = "Hanno preso il mio sangue... In quella chiesa, compirà il suo orrendo rito..."
  },
  AvgDialog_131202_Content_18 = {
    Text = "Vendicatore del Destino, bagnati nel nostro Sangue… il dio malvagio delle ombre sta per compiere l'Avvento, ogni Destino sprofonderà nel… totale… <Shake:Uhm uhm uhm……><Big:nel Caos totale…!>"
  },
  AvgDialog_131202_Content_19 = {
    Text = "Le sue pupille si dilatano. Rabbrividisce per un terrore freddo e primordiale, come se stesse fissando un purgatorio più orrendo del suo più oscuro incubo."
  },
  AvgDialog_131202_Content_2 = {
    Text = "I ragni si disperdono. L'ultimo scudiero cade in un lampo di luce argentea, ma il signore della tempesta è svanito da tempo. Tu e Arachne vi avvicinate all'uomo distrutto rannicchiato al centro della stanza."
  },
  AvgDialog_131202_Content_20 = {
    Text = "Afferra la manica di Arachne, alzando lo sguardo verso di lei con occhi imploranti."
  },
  AvgDialog_131202_Content_21 = {
    Text = "Signorina... mi ritrovo ancora a chiamarvi Signorina... Eravate così lenta a imparare le vostre prime parole. Avete fatto preoccupare il Padrone e la Signora senza fine..."
  },
  AvgDialog_131202_Content_22 = {
    Text = "Quando finalmente parlaste per darmi l'addio, tutti gli altri gioirono... ma io sapevo. Solo io sapevo che quelle parole erano un verdetto dal quale il Fato non vi avrebbe mai lasciato fuggire."
  },
  AvgDialog_131202_Content_23 = {
    Text = "Tornai al focolare ad attendere la morte. Non riuscivo a smettere di piangere — non solo per me stesso, ma per voi, Signorina Arachne..."
  },
  AvgDialog_131202_Content_24 = {
    Text = "Sapevo già allora... che pesante maledizione eravate destinata a portare..."
  },
  AvgDialog_131202_Content_25 = {
    Text = "Le lacrime scorrono sulle sue guance segnate e solcate dal tempo. Con una mano tremante, si protende verso Arachne. Attraverso la sua visuale offuscata, la rivede ancora una volta come una bambina."
  },
  AvgDialog_131202_Content_26 = {
    Text = "Quel volto innocente non pianse mai; semplicemente osservava il cielo vuoto con curiosità, sorridendo a destini che nessun altro poteva vedere."
  },
  AvgDialog_131202_Content_27 = {
    Text = "Signorina Arachne, vi prego... proteggetela. Proteggete \"Memorie\"... e vi prego, abbiate cura di voi stessa."
  },
  AvgDialog_131202_Content_28 = {
    Text = "Non... perderti... nella ragnatela..."
  },
  AvgDialog_131202_Content_29 = {
    Text = "La sua voce sfuma in un sussurro e infine svanisce. Quando il suo respiro si arresta, Arachne gli chiude dolcemente gli occhi."
  },
  AvgDialog_131202_Content_3 = {Text = "Sei tu..."},
  AvgDialog_131202_Content_30 = {
    Text = "\"Riposa ora, Signor Lawrence...\""
  },
  AvgDialog_131202_Content_31 = {
    Text = "L'angolo della bocca di Lawrence si solleva in un debole sorriso. Nei suoi ultimi istanti, ode ancora una volta le primissime parole che Arachne abbia mai pronunciato."
  },
  AvgDialog_131202_Content_32 = {
    Text = "Non chiede nient'altro."
  },
  AvgDialog_131202_Content_33 = {
    Text = "Hai usato i ricordi del tuo stesso maggiordomo per creare questa Marionetta... non è come le altre bambole che hai creato. Perché?"
  },
  AvgDialog_131202_Content_34 = {
    Text = "Forse come memoriale. O forse... cercavo soltanto un po' di conforto."
  },
  AvgDialog_131202_Content_35 = {Text = "Conforto?"},
  AvgDialog_131202_Content_36 = {
    Text = "Volevo dire a me stessa che erano ancora con me. Che non se ne erano mai veramente andati."
  },
  AvgDialog_131202_Content_37 = {
    Text = "Arachne adagia il corpo spezzato del vecchio sul pavimento. Non offre altre spiegazioni, e voi non insistete. Sapete che le risposte vi attendono, non lontano da qui."
  },
  AvgDialog_131202_Content_38 = {
    Text = "All'interno di questa Grande Tela, il potere di Nefraea è legato a queste Marionette. La loro morte non fa che avvicinarla al centro dell'ordito."
  },
  AvgDialog_131202_Content_39 = {
    Text = "Dobbiamo fermarla prima che ottenga il potere di lacerare la trama. È tutto ciò che conta ora, Custode {Male=Mr.,Female=Miss}."
  },
  AvgDialog_131202_Content_4 = {
    Text = "<Shake:Sig.na Arachne... e voi, {Male=signorino,Female=signorina}... coff coff...>"
  },
  AvgDialog_131202_Content_40 = {
    Text = "Arachne posa le mani sul capo del vecchio, sfiorando il filo quasi invisibile. Dall'altro lato della città, un debole eco vibra attraverso la trama."
  },
  AvgDialog_131202_Content_41 = {
    Text = "Il Fato ti ha risposto?"
  },
  AvgDialog_131202_Content_42 = {
    Text = "Arachne annuisce. Prima di alzarsi, rivolge un ultimo sguardo al volto sorridente di Lawrence."
  },
  AvgDialog_131202_Content_43 = {
    Text = "\"Memorie\" è ancora vivo. E quelli della Prigione Abissale... ci stanno aspettando."
  },
  AvgDialog_131202_Content_5 = {
    Text = "Il corpo davanti a voi è una rovina. Metà della sua carne è stata divorata, lasciando un ammasso di putrefazione e ossa macchiate di sangue."
  },
  AvgDialog_131202_Content_6 = {
    Text = "Un accesso di tosse scuote il vecchio, strappandogli le ultime gocce di sangue. Arachne regge un unico filo invisibile che tremola come una candela nella bufera, sul punto di spezzarsi."
  },
  AvgDialog_131202_Content_7 = {
    Text = "Dobbiamo fermare il salasso... aiutami a trovare qualcosa!"
  },
  AvgDialog_131202_Content_8 = {
    Text = "È troppo tardi... Signorina Arachne... salvatela... salvate \"Memorie\"..."
  },
  AvgDialog_131202_Content_9 = {
    Text = "I credenti... l'hanno presa..."
  },
  AvgDialog_131203_Content_1 = {
    Text = "Arachne! Che stai facendo?! È questa quella che chiami... \"fiducia\"?"
  },
  AvgDialog_131203_Content_10 = {
    Text = "Recitazione. Inganno. Manipolazione."
  },
  AvgDialog_131203_Content_11 = {
    Text = "\"Estasi,\" questo è il tuo destino. Sali sul palco, {Male=Sig.,Female=Sig.na} Custode.\nSu questo palco, porterai a compimento la tua Storia."
  },
  AvgDialog_131203_Content_12 = {
    Text = "Su questo palcoscenico, otterrai ciò che il tuo cuore desidera."
  },
  AvgDialog_131203_Content_2 = {
    Text = "Senior William... Si-Si sta ancora riprendendo dalle ferite!..."
  },
  AvgDialog_131203_Content_3 = {
    Text = "Non temere, Custode {Male=Mr.,Female=Miss}. Non ha nulla a che fare con questo filo del Fato. L'ho teletrasportato in un luogo sicuro."
  },
  AvgDialog_131203_Content_4 = {
    Text = "Questo è un destino a cui nessuno dei due può sfuggire, {Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_131203_Content_5 = {
    Text = "Non ti ho mai mentito. Ti sto conducendo al tuo palco, dove darai la rappresentazione di una Vita intera. Una rappresentazione che sarà interamente tua."
  },
  AvgDialog_131203_Content_6 = {
    Text = "Mentre si avvicina, fissi i suoi Occhi velati di Nebbia, cercando il messaggio che non può pronunciare ad alta voce."
  },
  AvgDialog_131203_Content_7 = {
    Text = "(Uno spettacolo... interamente mio...)"
  },
  AvgDialog_131203_Content_8 = {
    Text = "Una scintilla di Ispirazione attraversa la tua mente come una stella cadente, per poi svanire nel groviglio dei tuoi pensieri."
  },
  AvgDialog_131203_Content_9 = {
    Text = "Le Ancelle Ragno si ritirano. Arachne alza la Mano, pizzicando una corda invisibile."
  },
  AvgDialog_131204_Content_1 = {
    Text = "La luce d'argento recide la seta. Sfruttando l'apertura, infranga la difesa delle ancelle e raggiungi Arachne."
  },
  AvgDialog_131204_Content_10 = {
    Text = "Lei si volta. Mentre i suoi fili si muovono, un impulso non richiesto si accende nel tuo cuore, costringendoti ad alzarti in piedi."
  },
  AvgDialog_131204_Content_11 = {
    Text = "Sei certo della tua autonomia, un vaso perfetto di libero arbitrio. Eppure, di tua spontanea volontà, segui Arachne, adeguandoti al suo passo e al suo ritmo esattamente mentre cammini verso la fine del sentiero di seta."
  },
  AvgDialog_131204_Content_12 = {Text = "..."},
  AvgDialog_131204_Content_13 = {
    Text = "Oh, benvenuto! {Male=Sig.,Female=Sig.na} %player%, mio stimato ospite! I tuoi passi non sono mai risuonati così melodiosi."
  },
  AvgDialog_131204_Content_14 = {
    Text = "La nuova signora del teatro fa il suo ingresso, la sua voce esagerata riecheggia sul palcoscenico avvolto nell'oscurità."
  },
  AvgDialog_131204_Content_15 = {
    Text = "Non è piacevole, vero? Avere il proprio destino manipolato? Non importa, Custode {Male=Mr.,Female=Miss}. Questa storia è quasi finita."
  },
  AvgDialog_131204_Content_16 = {
    Text = "Nefraea, che stai facendo? ..."
  },
  AvgDialog_131204_Content_17 = {
    Text = "Suspense! È per questo che il pubblico viene in questo teatro! Ma non avere tanta fretta, tesoro."
  },
  AvgDialog_131204_Content_18 = {
    Text = "Signore e signori! Preparatevi ad applaudire... un momento, dove sono le mie marionette? Ah, eccole."
  },
  AvgDialog_131204_Content_19 = {
    Text = "Quale fantasioso spettacolo ci offrirà la nostra grande vendicatrice, ora che ha eliminato tre Marionette?"
  },
  AvgDialog_131204_Content_2 = {Text = "Fatto!"},
  AvgDialog_131204_Content_20 = {
    Text = "Ora, assistete al <Big:<Red:Climax del Secondo Atto!>>"
  },
  AvgDialog_131204_Content_21 = {
    Text = "Lo chiamo... \"Rinascita dalla Terra.\""
  },
  AvgDialog_131204_Content_22 = {Text = "Pop—"},
  AvgDialog_131204_Content_23 = {
    Text = "Un fascio di luce frantuma l'oscurità. Una marionetta che regge un arcolaio avanza barcollando sul palcoscenico."
  },
  AvgDialog_131204_Content_24 = {
    Text = "Nefraea, Mietitrice dell'Abisso, Vendicatrice del Fato... <Shake:Mi sottometto al tuo glorioso potere!>"
  },
  AvgDialog_131204_Content_25 = {
    Text = "Questa è la Passione; rende gli uomini stolti. Questa è la Gentilezza; li rende deboli. E queste sono le mie Memorie... la fonte di ogni agonia."
  },
  AvgDialog_131204_Content_26 = {
    Text = "Non riesco più a sopportarle... Le offro a te, grande Nefraea."
  },
  AvgDialog_131204_Content_27 = {
    Text = "Davvero, sorella? Mia cara sorella..."
  },
  AvgDialog_131204_Content_28 = {
    Text = "Va tutto bene. Io ti comprendo meglio di chiunque altro. Affida a me la tua sofferenza."
  },
  AvgDialog_131204_Content_29 = {
    Text = "Vedi? La Lanterna dell'Abisso è accesa. La sua luce ci guiderà a Focolare."
  },
  AvgDialog_131204_Content_3 = {Text = "Ding—"},
  AvgDialog_131204_Content_30 = {
    Text = "Che luce calda... ma come torniamo a casa?"
  },
  AvgDialog_131204_Content_31 = {
    Text = "Non vedi, sorella?"
  },
  AvgDialog_131204_Content_32 = {
    Text = "Questo filatoio è il corpo dell'Apostolo. Queste fiamme sono gli occhi dell'Apostolo — ci stanno osservando!"
  },
  AvgDialog_131204_Content_33 = {
    Text = "\"Nefraea\" si erge trionfante, a braccia aperte."
  },
  AvgDialog_131204_Content_34 = {
    Text = "Solo unendo l'Autorità dei Tre Eoni l'Apostolo Senza Nome si risveglierà!"
  },
  AvgDialog_131204_Content_35 = {
    Text = "Egli aprirà per noi il passaggio verso la suprema Divinità… e in quel momento, <Big:ogni sofferenza perirà, ogni vana fatica giungerà alla Fine!>"
  },
  AvgDialog_131204_Content_36 = {
    Text = "La marionetta \"Nefraea\" si strappa la maschera di legno, rivelando la vera Nefraea celata sotto."
  },
  AvgDialog_131204_Content_37 = {
    Text = "Un palcoscenico di legno, marionette di legno, e una donna viva in piedi al centro, immersa nello sguardo del suo unico spettatore."
  },
  AvgDialog_131204_Content_38 = {
    Text = "Il varco si sta aprendo. La tua missione è quasi Completa. Non lo vedi, sorella?"
  },
  AvgDialog_131204_Content_39 = {
    Text = "Non devi più tessere quella tela infinita. Non devi più continuare a lacerarti!"
  },
  AvgDialog_131204_Content_4 = {
    Text = "Dita sottili pizzicano l'aria. Una corda vibra, propagando un'elegante increspatura attraverso la stanza."
  },
  AvgDialog_131204_Content_40 = {
    Text = "Riprendimi con te, vuoi, Arachne? ...Ti prego... Fammi di nuovo parte di te..."
  },
  AvgDialog_131204_Content_41 = {
    Text = "Le lacrime le rovinano il trucco, lasciando striature nere e corrosive sul volto. Le sue risa maniacali e i singhiozzi tessono una ragnatela soffocante intorno a lei — l'unica Anima viva su questo palcoscenico."
  },
  AvgDialog_131204_Content_42 = {
    Text = "Nefraea cade in Ginocchio per cullare la guancia liscia e insensibile di \"Arachne\", le sue lacrime che si raccolgono nel ghigno vuoto della sua maschera sorridente."
  },
  AvgDialog_131204_Content_43 = {
    Text = "Fissa intensamente la vera Arachne sotto il palcoscenico, le labbra tremanti premute contro l'orecchio di legno della marionetta. La sua Voce è così flebile che sembra un Sussurro destinato solo a sé stessa."
  },
  AvgDialog_131204_Content_44 = {
    Text = "Non abbandonarmi. Non lasciarmi indietro un'altra volta... <Italic:ti prego?>"
  },
  AvgDialog_131204_Content_5 = {
    Text = "L'increspatura inghiotte la tua luce d'argento, e la Chiave d'Argento svanisce all'istante. Mentre l'onda ti attraversa, la tua carne avvizzisce fino all'osso e il tuo sangue si tramuta in melma. Vieni fatto a pezzi, poi ricomposto come se nulla fosse accaduto."
  },
  AvgDialog_131204_Content_6 = {
    Text = "Ogni potere svanisce; ogni pensiero si estingue. Ovunque l'increspatura giunga, i mondi si trasformano in fili nelle sue mani. Te compreso."
  },
  AvgDialog_131204_Content_7 = {
    Text = "Lei è la Signora di questo Teatro. \nLei è il Fato stesso."
  },
  AvgDialog_131204_Content_8 = {
    Text = "Arachne... puoi controllare il mio Fato?!..."
  },
  AvgDialog_131204_Content_9 = {
    Text = "Il sorriso di Arachne è come un lago placido; non puoi vedere cosa si celi sotto la superficie, solo il riflesso di te stesso."
  },
  AvgDialog_131205_Content_1 = {Text = "Spari"},
  AvgDialog_131205_Content_10 = {
    Text = "Non devi consegnare alcun incarico."
  },
  AvgDialog_131205_Content_11 = {
    Text = "Professoressa Arachne... cosa intende?"
  },
  AvgDialog_131205_Content_12 = {
    Text = "Ricordi chi sei e da dove vieni?"
  },
  AvgDialog_131205_Content_13 = {
    Text = "Io? Ovviamente sono..."
  },
  AvgDialog_131205_Content_14 = {
    Text = "%player%. Un locale di Hvatz fino al midollo. Studente del primo anno all'Accademia di Arti Drammatiche. I tuoi genitori sono comuni impiegati statali che stravedono per te. Hai avuto due storie d'amore rispettabili. Appassionato, se non eccezionalmente dotato di talento, con una debolezza per la Sachertorte e gli involtini di carne alla griglia."
  },
  AvgDialog_131205_Content_15 = {
    Text = "Le memorie nitide si offuscano all'improvviso, mentre un diverso insieme di ricordi si fa strada in superficie. Mythag, Risvegliati, Dissoluzione, Tohuwabohu..."
  },
  AvgDialog_131205_Content_16 = {
    Text = "I tuoi occhi si spalancano di colpo e fissi la donna seduta di fronte a te, intenta a gustare il suo caffè con calma."
  },
  AvgDialog_131205_Content_17 = {
    Text = "No... non è giusto... Io sono il Custode del Mythag... Cosa sta succedendo?!"
  },
  AvgDialog_131205_Content_18 = {
    Text = "Ora ricordo... Eravamo nel tuo teatro. Siamo saliti su un palco, e poi... e poi..."
  },
  AvgDialog_131205_Content_19 = {
    Text = "E poi hai ordinato il tè del pomeriggio. Il tuo gusto da locale è piuttosto raffinato."
  },
  AvgDialog_131205_Content_2 = {Text = "Din-din!"},
  AvgDialog_131205_Content_20 = {
    Text = "Arachne sorseggia il liquido scuro nella sua tazza e annuisce con approvazione."
  },
  AvgDialog_131205_Content_21 = {
    Text = "Ecco il vostro ordine. È tutto servito."
  },
  AvgDialog_131205_Content_22 = {
    Text = "I piatti sprigionano un aroma che fa venire l'acquolina in bocca. Mentre il cameriere si china per apparecchiare, avvicina la bocca al tuo orecchio."
  },
  AvgDialog_131205_Content_23 = {
    Text = "Il complotto per l'assassinio è trapelato. L'Arciduca cambierà probabilmente il suo percorso. Il referente ti avviserà non appena ci saranno notizie. Tieniti pronto, %player%."
  },
  AvgDialog_131205_Content_24 = {
    Text = "Ti preme discretamente in mano una pistola Browning nuova di zecca. Quando alzi lo sguardo, il cameriere sfoggia di nuovo un sorriso cordiale e professionale. Si inchina e scompare in cucina con il suo vassoio."
  },
  AvgDialog_131205_Content_25 = {
    Text = "Il peso di memorie contrastanti si accumula, e ti massaggi le tempie doloranti dal dolore."
  },
  AvgDialog_131205_Content_26 = {
    Text = "Portare due vite distinte in un'unica mente è raramente un'esperienza piacevole per un novizio."
  },
  AvgDialog_131205_Content_27 = {
    Text = "Non è nulla. Rispetto ad affrontare il Tohuwabohu, un mal di testa sembra un massaggio."
  },
  AvgDialog_131205_Content_28 = {
    Text = "La mia memoria dice che sto seguendo gli ordini della Mano di Ferro. Tra due ore, dovrei usare questa pistola per assassinare l'erede in visita al trono dell'Impero Phio-Gariano..."
  },
  AvgDialog_131205_Content_29 = {
    Text = "Percorri con le dita le scanalature della pistola, cercando di organizzare le memorie che appartengono a questo mondo."
  },
  AvgDialog_131205_Content_3 = {
    Text = "Le ruote sferragliano sul selciato sconnesso. Una campana furiosa stride contro il massiccio corteo, sollevando nuvole di polvere e un coro di imprecazioni."
  },
  AvgDialog_131205_Content_30 = {
    Text = "Prima che tu possa chiedere altro, una luce cruda inonda il caffè. Il secco ticchettio di stivali militari sul cemento risuona mentre i soldati marciano verso il bancone."
  },
  AvgDialog_131205_Content_31 = {
    Text = "Buon pomeriggio, agenti. Come posso—"
  },
  AvgDialog_131205_Content_32 = {
    Text = "Senza una parola, un ufficiale si lancia in avanti, bloccando le mani del cameriere dietro la schiena e sbattendogli la testa sul bancone."
  },
  AvgDialog_131205_Content_33 = {
    Text = "Una canna di pistola viene premuta contro la sua fronte. Gli occhi del cameriere si spalancano per il terrore."
  },
  AvgDialog_131205_Content_34 = {
    Text = "Bosant, membro della Mano di Ferro. Hai dieci secondi per dirmi dove sono i tuoi complici."
  },
  AvgDialog_131205_Content_35 = {
    Text = "Il cameriere ansima, tremante. Nella sua disperata lotta, i suoi occhi scattano verso l'angolo della stanza."
  },
  AvgDialog_131205_Content_36 = {
    Text = "Ma il tavolo che occupavi poco fa è vuoto. Rimane solo mezza tazza di caffè, il cui vapore si disperde pigramente nell'aria."
  },
  AvgDialog_131205_Content_37 = {Text = "..."},
  AvgDialog_131205_Content_38 = {
    Text = "Qui dovremmo essere al sicuro per un momento."
  },
  AvgDialog_131205_Content_39 = {
    Text = "Sgattaiolate dalla porta sul retro del caffè, fondendovi come due insignificanti gocce d'acqua nella folla caotica all'esterno."
  },
  AvgDialog_131205_Content_4 = {
    Text = "Agiti una mano, scacciando la polvere che filtra attraverso le tende del caffè."
  },
  AvgDialog_131205_Content_40 = {
    Text = "Cosa sta succedendo? Perché ho queste memorie contrastanti?"
  },
  AvgDialog_131205_Content_41 = {
    Text = "Salire sul palco del Teatro del Fato significa diventare un personaggio. E ogni personaggio ha una vita propria."
  },
  AvgDialog_131205_Content_42 = {
    Text = "Questo è un mondo in una dimensione remota di cui non hai mai sentito parlare né che hai mai visitato. Eppure, come personaggio nato qui, lo conosci come il palmo della tua mano."
  },
  AvgDialog_131205_Content_43 = {
    Text = "Benvenuto in uno dei miei livelli, {Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_131205_Content_44 = {
    Text = "Vuoi dire... che puoi usare il livello per raggiungere altri mondi?!"
  },
  AvgDialog_131205_Content_45 = {
    Text = "Arachne nota l'improvvisa intensità nel tuo sguardo. Solleva il caffè che ha portato dal locale, assaporandone l'aroma prima di scuotere la testa."
  },
  AvgDialog_131205_Content_46 = {
    Text = "Lo strano fatto che stia fuggendo dalla scena di un crimine con caffè e torta non ti colpisce nemmeno come bizzarro. Ti sembra perfettamente naturale per lei, come se fosse semplicemente parte del suo fato."
  },
  AvgDialog_131205_Content_47 = {
    Text = "Lady Daffodil ti ha spiegato i principi del viaggio dimensionale. Le barriere tra i mondi sono incredibilmente solide. Ogni attraversamento esige un prezzo terribile; non è qualcosa che si fa alla leggera."
  },
  AvgDialog_131205_Content_48 = {
    Text = "Ma non siamo qui proprio adesso?..."
  },
  AvgDialog_131205_Content_49 = {
    Text = "Il Teatro del Fato può collegare brevemente i destini di mondi diversi."
  },
  AvgDialog_131205_Content_5 = {
    Text = "Uno shawarma, una Sachertorte e due tazze di caffè Hvatz. Grazie."
  },
  AvgDialog_131205_Content_50 = {
    Text = "Al momento, siamo solo due personaggi persi in un mare di persone — proiezioni fugaci che svaniranno in un batter d'occhio."
  },
  AvgDialog_131205_Content_51 = {
    Text = "Una proiezione... anche una proiezione va bene. Puoi usare questo metodo per aiutarmi a tornare?"
  },
  AvgDialog_131205_Content_52 = {
    Text = "Mi dispiace davvero, %player%. Il portale che hai chiuso ha bloccato lo Sguardo del Tohuwabohu, ma ha anche reciso i Fili del Fato."
  },
  AvgDialog_131205_Content_53 = {
    Text = "Tentare di esercitare un'influenza là ora scatenerebbe un disastro oltre la nostra sopportazione."
  },
  AvgDialog_131205_Content_54 = {
    Text = "Vede la delusione sul tuo volto e sorride, porgendoti la torta."
  },
  AvgDialog_131205_Content_55 = {
    Text = "Stai tranquillo, %player%. Una volta che avremo affrontato mia sorella, il passaggio verso Kadath si riaprirà."
  },
  AvgDialog_131205_Content_56 = {
    Text = "Il Fato non tradisce mai chi sa attendere, e noi non dobbiamo mai disprezzare i doni che il Fato ci offre. Su, provalo."
  },
  AvgDialog_131205_Content_57 = {
    Text = "Fai un respiro e dai un piccolo morso alla torta. La dolcezza è così travolgente che quasi dimentichi lo stridente disagio delle tue memorie in collisione."
  },
  AvgDialog_131205_Content_58 = {
    Text = "Hmm... Si dice che l'Arciduca Flavian non perda mai l'occasione di assaggiare la torta tipica locale ogni volta che viene in visita. Per un principe ereditario, ha davvero un gusto raffinato."
  },
  AvgDialog_131205_Content_59 = {
    Text = "Quindi, cosa ha influenzato esattamente Nefraea qui? Come dovremmo rimediare..."
  },
  AvgDialog_131205_Content_6 = {
    Text = "Restituisci il menu di pergamena al cameriere e fissi con aria cupa la strada familiare oltre la finestra."
  },
  AvgDialog_131205_Content_60 = {
    Text = "Mentre parli, Arachne sembra attratta da qualcos'altro. Alza lo sguardo verso fili invisibili nell'aria che restano celati alla tua vista."
  },
  AvgDialog_131205_Content_61 = {
    Text = "Sorride, prosciugando l'ultima goccia del suo caffè. Porge alcune monete e il vassoio vuoto a un cameriere di passaggio diretto al caffè, rivolgendogli un sommesso ringraziamento."
  },
  AvgDialog_131205_Content_62 = {
    Text = "Ci ha trovati. Tempismo perfetto. Stai attento, %player%."
  },
  AvgDialog_131205_Content_63 = {Text = "Bang—"},
  AvgDialog_131205_Content_64 = {
    Text = "Ti abbassi d'istinto. Un proiettile sfreccia oltre, sfiorandoti quasi la sommità del capo."
  },
  AvgDialog_131205_Content_65 = {
    Text = "Proprio lì!"
  },
  AvgDialog_131205_Content_66 = {
    Text = "Sono gli assassini della Mano di Ferro! Prendeteli!"
  },
  AvgDialog_131205_Content_67 = {
    Text = "Guidati da alcuni cittadini urlanti, uno sciame di ufficiali si fa largo tra la folla per circondarti."
  },
  AvgDialog_131205_Content_68 = {
    Text = "Mentre si avvicinano, i loro corpi iniziano a deformarsi — arti di ragno scuri e chitinosi erompono dai loro torsi, e artigli affilati come rasoi sferzano l'aria."
  },
  AvgDialog_131205_Content_7 = {
    Text = "Questa strada andrebbe davvero allargata. Era identica quando ero bambino. A parte essersi ulteriormente deteriorata, non è cambiata di una virgola in tutti questi anni."
  },
  AvgDialog_131205_Content_8 = {
    Text = "Le autorità sono incapaci di costruire qualsiasi cosa. L'unica cosa in cui eccellono è svendere le terre di Hvatz e servire torte alla famiglia reale."
  },
  AvgDialog_131205_Content_9 = {
    Text = "Rifugiati, proteste, e un Arciduca che proprio adesso doveva venire in visita... Professoressa Arachne, posso avere una proroga per il compito di folklore? Le attività della Mano di Ferro mi stanno prosciugando ogni energia ultimamente."
  },
  AvgDialog_131206_Content_10 = {
    Text = "Scricchiolio — scricchiolio — la Dea del Fato gira il Suo arcolaio."
  },
  AvgDialog_131206_Content_11 = {
    Text = "Scricchiolio — scricchiolio — i Fili del Fato convergono nelle sue mani."
  },
  AvgDialog_131206_Content_12 = {
    Text = "Le marionette marciano in fila, addentrandosi nella Grande Trama."
  },
  AvgDialog_131206_Content_13 = {
    Text = "Danzano. Cantano. Scricchiolio — scricchiolio —"
  },
  AvgDialog_131206_Content_14 = {
    Text = "Muoiono con la Grande Trama, in silenzio e senza lasciare traccia."
  },
  AvgDialog_131206_Content_15 = {Text = "..."},
  AvgDialog_131206_Content_16 = {
    Text = "Mia signora, il nostro nuovo spettacolo è iniziato."
  },
  AvgDialog_131206_Content_17 = {
    Text = "Il Passaggio verso Kadath è stato chiuso appena in tempo. Quel {Male=signore,Female=signorina} è arrivato in città."
  },
  AvgDialog_131206_Content_18 = {
    Text = "Ebbene. Vi piace il nuovo spettacolo?"
  },
  AvgDialog_131206_Content_19 = {
    Text = "Hmm... forse è un tantino troppo complicato?"
  },
  AvgDialog_131206_Content_2 = {
    Text = "Il Vecchio Fumo, Addormentato"
  },
  AvgDialog_131206_Content_20 = {
    Text = "Le storie semplici sono più facili da gestire, sì — ma per certe persone, una storia semplice non può contenere il loro Fato."
  },
  AvgDialog_131206_Content_21 = {
    Text = "Emozioni intense, svolte drammatiche, una trama commovente, un finale tragico..."
  },
  AvgDialog_131206_Content_22 = {
    Text = "Questi sono i destini che appartengono a un \"Eroe.\""
  },
  AvgDialog_131206_Content_23 = {
    Text = "Avanti; è il tuo turno sul palcoscenico."
  },
  AvgDialog_131206_Content_24 = {
    Text = "La fanciulla si prostra. Nell'istante in cui la sua fronte tocca il pavimento, il suo corpo si frantuma — carne e pelle si dissolvono in ragni di un pallido viola che si disperdono in ogni angolo della Stanza e svaniscono."
  },
  AvgDialog_131206_Content_25 = {Text = "..."},
  AvgDialog_131206_Content_26 = {
    Text = "<Shake:Ugh… ugh ugh……>"
  },
  AvgDialog_131206_Content_27 = {
    Text = "Sotto di te c'è asfalto Difficile. Barcollando ti rialzi in piedi, premendo i palmi contro la testa dolorante e confusa."
  },
  AvgDialog_131206_Content_28 = {
    Text = "Cos'era quello..."
  },
  AvgDialog_131206_Content_29 = {
    Text = "Ah! La porta per Kadath!!"
  },
  AvgDialog_131206_Content_3 = {
    Text = "Ah, Kadath, la patria dei miei sogni! Finalmente posso tornare!"
  },
  AvgDialog_131206_Content_30 = {
    Text = "Ti ridesti all'Allerta, sollevando lo Sguardo al cielo."
  },
  AvgDialog_131206_Content_31 = {
    Text = "Il cielo è di un azzurro limpido e brillante. La luce del sole ti illumina. Non resta traccia del sole oscuro né del Passaggio dimensionale."
  },
  AvgDialog_131206_Content_32 = {
    Text = "Beh, da quel che so, c'è un'azienda tecnologica qui vicino che testa aeromobili. {Male=he,Female=she} è probabilmente uno dei loro piloti collaudatori."
  },
  AvgDialog_131206_Content_33 = {
    Text = "Beh, da quel che so, qui vicino c'è un'azienda tecnologica che sta testando degli aeromobili. Probabilmente {Male=è,Female=è} un{Male=o,Female=a} dei loro Pilota di collaudo."
  },
  AvgDialog_131206_Content_34 = {
    Text = "Ugh... Io..."
  },
  AvgDialog_131206_Content_35 = {Text = "Persone."},
  AvgDialog_131206_Content_36 = {
    Text = "Una folla densa riempie la tua visuale, gli occhi ancora brucianti per la luce."
  },
  AvgDialog_131206_Content_37 = {
    Text = "Una città vivace come Londinium ti riporta a memorie lontane di Kadath."
  },
  AvgDialog_131206_Content_38 = {
    Text = "Strade affollate, folle radunate, negozi che esplodono di colore ovunque..."
  },
  AvgDialog_131206_Content_39 = {
    Text = "Il mondo di questa dimensione ha visto la sua popolazione calare drasticamente a causa della Dissoluzione. Non hai mai assistito a una scena così viva, nemmeno a Necrovia."
  },
  AvgDialog_131206_Content_4 = {
    Text = "Ah, Kadath, la Terra dei Bianchi Uccelli dei miei sogni! Finalmente, posso fare Ritorno!"
  },
  AvgDialog_131206_Content_40 = {
    Text = "Scusate... dove mi trovo?"
  },
  AvgDialog_131206_Content_41 = {
    Text = "Ah, strano! Qualcuno che non ha mai nemmeno sentito parlare di Londinium? Questa è la più grande città del mondo!"
  },
  AvgDialog_131206_Content_42 = {
    Text = "<Shake:!!!>"
  },
  AvgDialog_131206_Content_43 = {
    Text = "Come avete detto che si chiama questo posto?!"
  },
  AvgDialog_131206_Content_44 = {
    Text = "Sei certo di aver udito quelle parole."
  },
  AvgDialog_131206_Content_45 = {
    Text = "La tua mente intorpidita si fa lucida in un istante. Balzi in piedi e osservi tutto ciò che ti circonda."
  },
  AvgDialog_131206_Content_46 = {
    Text = "Incrocio dei Mattoni. Le lettere consumate sul cartello dell'intersezione sono esattamente come le ricordi."
  },
  AvgDialog_131206_Content_47 = {
    Text = "Libreria della Piega del Tempo. Ogni volta che marinavi la scuola, la cosa che preferivi era nasconderti qui e perderti nei romanzi polizieschi."
  },
  AvgDialog_131206_Content_48 = {
    Text = "Drogheria del Mercato Fragrante... dove il Professor Dexter ti chiedeva sempre di portargli una bottiglia di gin. Il piccolo trucco di N."
  },
  AvgDialog_131206_Content_49 = {
    Text = "Fiorista della Rugiada Mattutina. Per l'anniversario del tuo primo anno come Custode, Ramona aveva pensato di ordinarti qui il bouquet più luminoso di tutta Londinium..."
  },
  AvgDialog_131206_Content_5 = {
    Text = "I miei mentori, i miei compagni, il mio più caro amico, il mio... tutto."
  },
  AvgDialog_131206_Content_50 = {Text = "..."},
  AvgDialog_131206_Content_51 = {
    Text = "Londinium... davvero... sono tornato?"
  },
  AvgDialog_131206_Content_52 = {
    Text = "Mi scusi... mi scusi, che ne è stato di Mythag?!"
  },
  AvgDialog_131206_Content_53 = {
    Text = "Mythag? Non abbiamo mai sentito parlare di un posto simile, {Male=signore,Female=signorina}."
  },
  AvgDialog_131206_Content_54 = {
    Text = "E la Dissoluzione? Quanto duramente ha colpito qui?!"
  },
  AvgDialog_131206_Content_55 = {
    Text = "Giovane {Male=sir,Female=lady}, credo che tu sia solo stanco e un po' confuso... Siediti su quella panchina e mangia qualcosa. Mi capita di averne un po' con me."
  },
  AvgDialog_131206_Content_56 = {
    Text = "Giovane {Male=signore,Female=signora}, credo che siate solo stanco e un po' confuso... Sedetevi su quella panchina e mangiate qualcosa. Mi capita di averne un po' con me."
  },
  AvgDialog_131206_Content_57 = {
    Text = "L'anziano porge il pane e l'acqua appena comprati alla drogheria."
  },
  AvgDialog_131206_Content_58 = {
    Text = "Ah, grazie mille... Ma non ho fame adesso, è solo che... ci sono cose che non riesco a capire..."
  },
  AvgDialog_131206_Content_59 = {
    Text = "<Small:Questo è impossibile… né Mythag, né la Dissoluzione……>"
  },
  AvgDialog_131206_Content_6 = {
    Text = "Una volta varcato questo portale oscuro, mi ricongiungerò con loro ancora una volta!"
  },
  AvgDialog_131206_Content_60 = {
    Text = "Q-questa persona è così strana... {Male=è,Female=è} appena cadut{Male=o,Female=a} dal cielo?"
  },
  AvgDialog_131206_Content_61 = {
    Text = "Non è carino da dire. Potrebbe star attraversando un momento difficile. Comportati bene con gli ospiti che vengono da lontano."
  },
  AvgDialog_131206_Content_62 = {
    Text = "Una mano ti batte delicatamente sulla spalla. Ti volti e trovi un viso sconosciuto."
  },
  AvgDialog_131206_Content_63 = {
    Text = "Siamo agenti di pattuglia della zona, sotto la giurisdizione dell'MTC. Ecco il mio tesserino."
  },
  AvgDialog_131206_Content_64 = {
    Text = "Buongiorno a voi. Un gentile cittadino ci ha informato che un viaggiatore si è perso nella nostra bella città."
  },
  AvgDialog_131206_Content_65 = {
    Text = "Possiamo esservi d'aiuto in qualche modo, {Male=signore,Female=signorina}?"
  },
  AvgDialog_131206_Content_66 = {
    Text = "Ti prendi un breve momento per riflettere. Finché non capirai cosa sta succedendo, è meglio attirare il meno possibile l'attenzione."
  },
  AvgDialog_131206_Content_67 = {
    Text = "Ah... vi ringrazio per la premura. Sono svenuto mentre passeggiavo—nulla di grave."
  },
  AvgDialog_131206_Content_68 = {
    Text = "Vi ringraziamo entrambi. Abbiamo delle cose da sbrigare, quindi ci congediamo..."
  },
  AvgDialog_131206_Content_69 = {
    Text = "Capisco. In tal caso, se non vi dispiace—vorrei rubarvi ancora un momento. Ci sono alcune cose che vorrei chiedervi."
  },
  AvgDialog_131206_Content_7 = {
    Text = "Allora perché questa porta, così vicina, a Portata di Mano, è serrata? Perché questo cielo crudele mi ha abbandonato?"
  },
  AvgDialog_131206_Content_70 = {
    Text = "L'agente si avvicina a te con un sorriso, spolverandoti la polvere dalla spalla"
  },
  AvgDialog_131206_Content_71 = {
    Text = "<Red:Custode>, dovrei chiamarti così, giusto?"
  },
  AvgDialog_131206_Content_72 = {
    Text = "Vorrei chiedervi... siete soddisfatto della cerimonia di benvenuto che ho organizzato per voi?"
  },
  AvgDialog_131206_Content_73 = {Text = "!!!"},
  AvgDialog_131206_Content_74 = {
    Text = "Un nauseante suono umido di lacerazione si leva nell'aria. Enormi zampe di ragno esplodono dai corpi degli agenti e dei passanti, schizzandoti addosso sangue denso dall'odore ferroso."
  },
  AvgDialog_131206_Content_75 = {
    Text = "Il Fato porge i suoi saluti, caro Custode."
  },
  AvgDialog_131206_Content_76 = {
    Text = "Sì, mia signora."
  },
  AvgDialog_131206_Content_77 = {
    Text = "Sì, mia signora."
  },
  AvgDialog_131206_Content_78 = {Text = "Attento!!"},
  AvgDialog_131206_Content_8 = {
    Text = "Mia cara Chiave d'Argento... illumina il mio cammino... concedimi anche solo un Frammento di risposta..."
  },
  AvgDialog_131206_Content_9 = {
    Text = "Le luci cambiano. La Cantante d'Argento sale sul palco."
  },
  AvgDialog_131207_Content_1 = {
    Text = "Riflesso della Divinità"
  },
  AvgDialog_131207_Content_10 = {
    Text = "Hai ancora la possibilità di fermarti, Nefraea."
  },
  AvgDialog_131207_Content_11 = {
    Text = "E se svanissimo tutti? Che importa?"
  },
  AvgDialog_131207_Content_12 = {
    Text = "Nefraea offre un sorriso malizioso, voltandosi a fissare i suoi devoti Scudieri."
  },
  AvgDialog_131207_Content_13 = {
    Text = "Ditemi, fanciulli, avete paura?"
  },
  AvgDialog_131207_Content_14 = {
    Text = "Un'ondata di risate disperate accoglie il monito di Arachne."
  },
  AvgDialog_131207_Content_15 = {
    Text = "Hahaha! Noi siamo gli abbandonati dal Fato. Nessun disastro può farci tremare... Vi preghiamo, portateci la salvezza, mia signora!"
  },
  AvgDialog_131207_Content_16 = {
    Text = "Brava bambina."
  },
  AvgDialog_131207_Content_17 = {
    Text = "Nefraea accarezza affettuosamente la testa di uno scudiero."
  },
  AvgDialog_131207_Content_18 = {
    Text = "Ti sbagli di grosso, cara sorella. Il Fato ci ha già condannati a morte e a prigionia eterna. Le anime reiette non implorano pietà."
  },
  AvgDialog_131207_Content_19 = {
    Text = "Siamo qui per vendetta. Vendetta contro il Fato."
  },
  AvgDialog_131207_Content_2 = {
    Text = "Su un grande palcoscenico come nulla che abbiate mai visto, il nero arcolaio di Nefraea si erge solitario al centro. All'interno dell'immenso anello, una luce azzurra eterea che mai si spegne illumina il volto gioioso di Nefraea."
  },
  AvgDialog_131207_Content_20 = {
    Text = "Per caso o per volontà, uno dei Fili del Fato con cui Nefraea sta giocando si spezza silenziosamente."
  },
  AvgDialog_131207_Content_21 = {
    Text = "In quello stesso istante, un palcoscenico poco distante si frantuma con un fragore di tuono, spezzandosi in Frammenti che si dissolvono nel Vuoto infinito del teatro."
  },
  AvgDialog_131207_Content_22 = {
    Text = "Oh! Le mie scuse. Ho accidentalmente spezzato il tuo filo..."
  },
  AvgDialog_131207_Content_23 = {
    Text = "Sbrigati, cara sorella. In questo teatro ci sono molti palcoscenici, ma odieresti vederne un altro andare in pezzi, non è vero?"
  },
  AvgDialog_131207_Content_24 = {
    Text = "Arachne lascia sfuggire un debole sospiro. Quando riapre gli occhi, solleva la punta di un dito e tocca lievemente la sommità della vostra testa."
  },
  AvgDialog_131207_Content_25 = {
    Text = "Arachne! Non farlo... deve esserci un altro modo!"
  },
  AvgDialog_131207_Content_26 = {
    Text = "Sali sul palco. Offri l'Autorità degli Eoni all'Apostolo... Questo è il tuo destino ineluttabile, {Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_131207_Content_27 = {
    Text = "La voce irresistibile di Arachne risuona nella tua mente. Mentre sollevi i piedi e cammini verso il palco, i tre poteri a lungo assenti dentro di te cominciano ad agitarsi."
  },
  AvgDialog_131207_Content_28 = {
    Text = "Si contorcono e si scontrano dentro di te, infuriandosi contro il comando oracolare di Arachne."
  },
  AvgDialog_131207_Content_29 = {
    Text = "Impressionante. Degno dei Tre Eoni... conservare un simile frammento di Autorità, eppure possedere ancora il potere di influenzare il proprio Ospite a tale distanza."
  },
  AvgDialog_131207_Content_3 = {
    Text = "Guardate, {Male=Sig.,Female=Sig.na} Custode, che luci meravigliose..."
  },
  AvgDialog_131207_Content_30 = {
    Text = "Falli rigare dritto, {Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_131207_Content_4 = {
    Text = "Questo fascio è un dono del Fato. Ci guiderà verso quella terra di Estasi dove la sofferenza non esiste."
  },
  AvgDialog_131207_Content_5 = {
    Text = "Nefraea allunga la mano, tracciando i disegni lasciati dalla luce nello spazio dimensionale. L'Ombra della sua mano si chiude lentamente, strisciando sul volto di Arachne."
  },
  AvgDialog_131207_Content_6 = {
    Text = "Vieni, sorella. È tempo che la nostra protagonista faccia il suo ingresso."
  },
  AvgDialog_131207_Content_7 = {
    Text = "...Il Fato non è qualcosa con cui giocare o da manomettere, Nefraea."
  },
  AvgDialog_131207_Content_8 = {
    Text = "Ogni destino è già Sigillato. Se risvegli quella divinità e lasci che tutto finisca... alterare il Fato con la forza porterà una catastrofe oltre ogni immaginazione."
  },
  AvgDialog_131207_Content_9 = {
    Text = "Che si tratti di ciò che disprezzi o di ciò che ti è caro, tutto svanirà nell'apocalisse."
  },
  AvgDialog_131208_Content_1 = {
    Text = "Il Verdetto"
  },
  AvgDialog_131208_Content_10 = {
    Text = "La Bambina inspira profondamente e sorride con appagamento."
  },
  AvgDialog_131208_Content_11 = {
    Text = "Gli iris hanno cominciato a fiorire... la Primavera è davvero arrivata."
  },
  AvgDialog_131208_Content_12 = {
    Text = "Ehi, Rea, ti ho mai chiesto quale sia la tua stagione preferita?"
  },
  AvgDialog_131208_Content_13 = {
    Text = "Non ho una stagione preferita, mia signora."
  },
  AvgDialog_131208_Content_14 = {Text = "Noioso."},
  AvgDialog_131208_Content_15 = {
    Text = "Arachne alza gli Occhi al cielo. Tende la mano libera, catturando la luce del sole nel palmo."
  },
  AvgDialog_131208_Content_16 = {
    Text = "Amo ogni stagione, specialmente la primavera. È passato così tanto tempo da quando siamo usciti di casa... dovremmo trovare il tempo per fare un'escursione?"
  },
  AvgDialog_131208_Content_17 = {
    Text = "Accanto alla tenuta dove sono nata, c'è un giardino curato con grande bellezza. So che lo ameresti."
  },
  AvgDialog_131208_Content_18 = {
    Text = "Avete atteso tre giorni, mia signora. È tempo di decidere."
  },
  AvgDialog_131208_Content_19 = {
    Text = "L'Ancella adempie al suo dovere. Le sue parole fredde cadono come una pioggia gelida, spegnendo la splendida primavera negli occhi di Arachne."
  },
  AvgDialog_131208_Content_2 = {
    Text = "Scricchiolio — scricchiolio — la Dea del Fato gira il Suo arcolaio."
  },
  AvgDialog_131208_Content_20 = {
    Text = "Scricchiolio, scricchiolio..."
  },
  AvgDialog_131208_Content_21 = {
    Text = "Dopo una breve pausa, il filatoio riprende a girare. Il suo ritmo è dolce, nitido, ed eterno."
  },
  AvgDialog_131208_Content_22 = {
    Text = "La nostra terra è appena emersa da un secolo di guerra. Il popolo ha ricostruito le proprie città sulle rovine. Una lunga, duratura pace li attende."
  },
  AvgDialog_131208_Content_23 = {
    Text = "Guardate, laggiù..."
  },
  AvgDialog_131208_Content_24 = {
    Text = "Seguendo lo sguardo di Arachne, l'Ancella volge gli occhi verso un imponente dipinto nella sala. Non è mai riuscita a comprenderlo."
  },
  AvgDialog_131208_Content_25 = {
    Text = "Di tutti i capolavori del signor Zoss, questo passa inosservato, eppure è il mio preferito."
  },
  AvgDialog_131208_Content_26 = {
    Text = "Questi cervi, dipinti in ocra e forme geometriche... persino come simboli astratti, pulsano di vita."
  },
  AvgDialog_131208_Content_27 = {
    Text = "Ogni volta che lo vedo, mi ricorda la mia opera teatrale preferita..."
  },
  AvgDialog_131208_Content_28 = {
    Text = "La frattura esiste da tre giorni. Il Fato di questa Dimensione è già stato contaminato dallo Sguardo di quella divinità."
  },
  AvgDialog_131208_Content_29 = {
    Text = "Se questo continua, la Distruzione provocata dal Suo sguardo non si fermerà ai nostri confini."
  },
  AvgDialog_131208_Content_3 = {
    Text = "Scricchiolio — scricchiolio — i Fili del Fato convergono nelle sue mani."
  },
  AvgDialog_131208_Content_30 = {
    Text = "Scricchiolio, scricchiolio."
  },
  AvgDialog_131208_Content_31 = {
    Text = "La Bambina chiude gli occhi, beandosi del calore. La Stanza cade nel Silenzio, se non per l'eterno ronzio del filatoio."
  },
  AvgDialog_131208_Content_32 = {
    Text = "Ricordi quanti destini di mondi abbiamo tessuto?"
  },
  AvgDialog_131208_Content_33 = {
    Text = "Ventisette in totale, mia signora."
  },
  AvgDialog_131208_Content_34 = {
    Text = "Dopo che mio padre mi donò questo filatoio, ne seguii i fili fino alla Porta della Verità. Oltre quella Porta, intravidi il Fato che attende questo mondo."
  },
  AvgDialog_131208_Content_35 = {
    Text = "So cosa ci aspetta. So la Scelta che devo compiere... ma non riesco a farlo."
  },
  AvgDialog_131208_Content_36 = {
    Text = "Famiglia. Amici. Memorie. Diciassettemila anni di grande storia. Tecnologia e arte innumerevoli come le Stelle..."
  },
  AvgDialog_131208_Content_37 = {
    Text = "Dopo aver visto La Verità, cominciai a tessere il Fato di questo mondo... Credevo che, poiché il Fato mi aveva concesso questo Potere, dovessi fare qualcosa per il mio popolo."
  },
  AvgDialog_131208_Content_38 = {
    Text = "Questa è la mia casa. La mia creatura. <Shake:Io... non posso farlo>, Rea..."
  },
  AvgDialog_131208_Content_39 = {Text = "Maestro..."},
  AvgDialog_131208_Content_4 = {
    Text = "Le marionette marciano in fila, addentrandosi nella Grande Trama."
  },
  AvgDialog_131208_Content_40 = {
    Text = "L'Ancella si inginocchia e asciuga le lacrime della sua signora. Nella luce primaverile, la sua Voce è limpida e Tenace."
  },
  AvgDialog_131208_Content_41 = {
    Text = "Avevi previsto questo giorno. Per questo hai fatto di me la tua Ancella."
  },
  AvgDialog_131208_Content_42 = {
    Text = "L'intero scopo della mia esistenza è dirti, in questo istante, ciò che deve essere fatto."
  },
  AvgDialog_131208_Content_43 = {
    Text = "Tu sei il Padrone del Destino, il Guardiano delle Dimensioni. È un cammino crudele, ma hai già fatto la tua Scelta."
  },
  AvgDialog_131208_Content_44 = {
    Text = "Le tre Parche sono responsabili di tessere, misurare... e recidere."
  },
  AvgDialog_131208_Content_45 = {
    Text = "Dal momento in cui hai scelto questo, questi sono divenuti i tuoi sacri doveri."
  },
  AvgDialog_131208_Content_46 = {
    Text = "Arachne alza lo sguardo. Nei suoi occhi sfocati, una fenditura invisibile ai mortali tremola ai confini del cielo. Siede accanto al sole tiepido come un sorriso crudele e frastagliato."
  },
  AvgDialog_131208_Content_47 = {
    Text = "La fenditura le sussurra, narrandole di futuri gelidi. Ha accettato questa Maledizione molto tempo fa, eppure ora che il momento è giunto, trema di terrore."
  },
  AvgDialog_131208_Content_48 = {
    Text = "Arachne si risiede al suo telaio. Mentre si riprendeva dall'orrore e dalla disperazione appena vissuti, un rossore febbrile le è salito sulle guance."
  },
  AvgDialog_131208_Content_49 = {
    Text = "Accarezza i fili densi e aggrovigliati come se sfiorasse il volto di un bambino."
  },
  AvgDialog_131208_Content_5 = {
    Text = "Danzano. Cantano. Scricchiolio — scricchiolio —"
  },
  AvgDialog_131208_Content_50 = {
    Text = "Nell'anno 804, prima ancora che potessi parlare, il nostro maggiordomo suonò un brano al pianoforte."
  },
  AvgDialog_131208_Content_51 = {
    Text = "<Italic:\"Il funerale del fiume Lahosse\"> di Elychion. La musica era come una fontana che scorreva fuori da un tempio. Vidi persino gli dèi fermarsi ad ascoltare..."
  },
  AvgDialog_131208_Content_52 = {
    Text = "Recide un singolo filo. Esso si libra nell'aria, oscillando silenzioso nelle increspature del Destino."
  },
  AvgDialog_131208_Content_53 = {
    Text = "La musica nella sala muore, sebbene il Fonografo continui a girare. I solchi del disco svaniscono; l'elegante corsivo del titolo del brano viene cancellato."
  },
  AvgDialog_131208_Content_54 = {
    Text = "Elychion incontra un destino diverso. In questo mondo desolato, la sua magnifica vita non è mai accaduta."
  },
  AvgDialog_131208_Content_55 = {
    Text = "Cassandra... le cattedrali che progettò erano più degne di adorazione degli dèi che vi dimoravano..."
  },
  AvgDialog_131208_Content_56 = {
    Text = "Un altro filo si spezza. A miglia di distanza, una magnifica cattedrale crolla. Gli occhi compassionevoli di una Statua divina si frantumano, divenendo indistinguibili dalla polvere."
  },
  AvgDialog_131208_Content_57 = {
    Text = "Le fiabe di Mornlin, le opere di Aldo, i dipinti di Marmo, la poesia di Rovell..."
  },
  AvgDialog_131208_Content_58 = {
    Text = "I libri si riducono a carta straccia; le Sculture si frantumano; i dipinti si dissolvono in vortici caotici di Colore."
  },
  AvgDialog_131208_Content_59 = {
    Text = "Lei è la Custode degli Archivi. Lei è la Carnefice. Recita i nomi di ogni grande artista, recidendo i loro fili uno a uno."
  },
  AvgDialog_131208_Content_6 = {
    Text = "La luce del sole bagna i loro volti. Quanta gioia nei loro occhi..."
  },
  AvgDialog_131208_Content_60 = {
    Text = "San Vildburg, una grande città di eroi. Ha resistito a cento Battaglie, affrontato Distruzione e Rinascita dalla Terra trentasette volte, e visto ventuno grandi sovrani ascendere alla gloria e precipitare nella rovina."
  },
  AvgDialog_131208_Content_61 = {
    Text = "I Nobili festeggiano qui; i poveri gemono in Agonia; i poeti lasciano dietro di sé eleganti Versi. Lungo il fiume Nevrich, l'eco di canti e colpi di cannone risuona nell'aria. Oggi, la sua storia eroica giunge al termine."
  },
  AvgDialog_131208_Content_62 = {
    Text = "Un groviglio di fili recisi si libra in una Danza frenetica. A 2.300 chilometri di distanza, quella magnifica città crolla in un rimbombo di rovine."
  },
  AvgDialog_131208_Content_63 = {
    Text = "Diciassettemila anni di resistenza... un'antica civiltà sopravvissuta a ogni catastrofe, ora cade..."
  },
  AvgDialog_131208_Content_64 = {
    Text = "Debole e tremante, Arachne raccoglie le sue ultime forze per afferrare gli infiniti fili che le si stendono dinanzi."
  },
  AvgDialog_131208_Content_65 = {
    Text = "I fili si spezzano. A 8.000 chilometri di distanza, un vasto impero antico — custode ininterrotto della civiltà umana — svanisce dai rotoli della storia come una voluta di fumo."
  },
  AvgDialog_131208_Content_66 = {Text = "..."},
  AvgDialog_131208_Content_67 = {
    Text = "Popoli. Arte. Città. Nazioni. Civiltà."
  },
  AvgDialog_131208_Content_68 = {
    Text = "Tutto sta crollando. Tutto sta scomparendo."
  },
  AvgDialog_131208_Content_69 = {
    Text = "<Shake:Hai visto, Rea?> Il mio primo figlio è morto, l'ho uccisa con le mie stesse mani…"
  },
  AvgDialog_131208_Content_7 = {
    Text = "Scricchiolio, scricchiolio."
  },
  AvgDialog_131208_Content_70 = {
    Text = "Le lacrime cadono in silenzio. Arachne sorride debolmente, lo sguardo rivolto alla finestra. Tra le rovine del mondo, solo il maniero in rovina là fuori resta ancora in piedi."
  },
  AvgDialog_131208_Content_71 = {
    Text = "Pensavo che se avessi potuto vegliare sul luogo in cui un tempo vivevo, non mi sarei sentita così sola."
  },
  AvgDialog_131208_Content_72 = {
    Text = "Che infantile... per un'esecutrice senza scelta, ho preparato solo la più crudele delle punizioni per me stessa."
  },
  AvgDialog_131208_Content_73 = {
    Text = "Allunga la mano, cogliendo un filo tenue e nebbioso sopra il proprio capo — uno che non riesce a vedere chiaramente — e ne collega una parte all'ultimo filo rimasto di questo mondo."
  },
  AvgDialog_131208_Content_74 = {
    Text = "Mia signora, che state...?"
  },
  AvgDialog_131208_Content_75 = {
    Text = "L'amore porta follia. La gentilezza porta fragilità. Le memorie portano solo dolore."
  },
  AvgDialog_131208_Content_76 = {
    Text = "Ho preso la mia decisione, Rea. Sono un'esecutrice maledetta; la bellezza non ha posto dentro di me."
  },
  AvgDialog_131208_Content_77 = {
    Text = "Stai per... spegnere una parte di te stessa? Ma questi sono i brani che custodisci con più cura... come puoi..."
  },
  AvgDialog_131208_Content_78 = {
    Text = "Quand'ero molto giovane, feci il mio primo sogno."
  },
  AvgDialog_131208_Content_79 = {
    Text = "Arachne allunga la mano, catturando la luce che risplende sulle rovine infinite."
  },
  AvgDialog_131208_Content_8 = {
    Text = "Un antico filatoio canticchia un dolce accompagnamento. Una Giovane Donna siede dinanzi ad esso, mormorando una melodia semplice."
  },
  AvgDialog_131208_Content_80 = {
    Text = "Nel sogno, camminavo sulla superficie di un lago. Attorno a me c'erano rovine e ossa rinsecchite, ma sotto la superficie, il riflesso della mia infanzia camminava attraverso una terra meravigliosa."
  },
  AvgDialog_131208_Content_81 = {
    Text = "Nessuna morte, nessuna sofferenza, nessun oblio. Una dolce luce solare risplende là per sempre, e la gente canta gioiosamente al suo fianco."
  },
  AvgDialog_131208_Content_82 = {
    Text = "Non riesco a vedere dove conducano i miei fili, ma credo di comprendere ora il destino preannunciato da quel sogno."
  },
  AvgDialog_131208_Content_83 = {
    Text = "Si sforza di sorridere — forse per la sua ancella, o forse per qualcosa di completamente diverso."
  },
  AvgDialog_131208_Content_84 = {
    Text = "Madre una volta disse che se provi a leggere Arachne al contrario, suona come \"Nefraea\". Nelle leggende di questo mondo, quello è il nome della Dea della Primavera."
  },
  AvgDialog_131208_Content_85 = {
    Text = "Amo ogni stagione, specialmente la primavera. La primavera è molto più piccola del Fato. Ma il Fato conduce alla morte, mentre la primavera... la primavera porta solo rinascita."
  },
  AvgDialog_131208_Content_86 = {
    Text = "Fissa lo sguardo fuori dalla finestra. Ai due lati del riquadro, il Fato e la Primavera si scambiano un ultimo sguardo."
  },
  AvgDialog_131208_Content_87 = {
    Text = "Lasciami, mio riflesso. Mia cara sorella. Porta con te tutta la nostra bontà e le nostre belle memorie."
  },
  AvgDialog_131208_Content_88 = {
    Text = "Fato... offro una parte di me stessa come sacrificio totale a te. Percorrerò questo arduo sentiero al posto suo."
  },
  AvgDialog_131208_Content_89 = {
    Text = "Arachne accarezza dolcemente i fili aggrovigliati. Tremano come se lottassero, come se gridassero."
  },
  AvgDialog_131208_Content_9 = {
    Text = "Un raggio di sole filtra dalla finestra, illuminando una targhetta incisa con \"Moirae\" accanto alla ruota."
  },
  AvgDialog_131208_Content_90 = {
    Text = "Le sue lacrime cadono attraverso i fili e sul piatto delle \"Moire\"."
  },
  AvgDialog_131208_Content_91 = {
    Text = "Ora ti rendo libera, \"Arachne.\""
  },
  AvgDialog_131208_Content_92 = {
    Text = "Scricchiolio."
  },
  AvgDialog_131208_Content_93 = {
    Text = "Il filo si spezza. Nella calda luce primaverile, l'arcolaio emette un ultimo sospiro."
  },
  AvgDialog_131209_Content_1 = {Text = "Riunione"},
  AvgDialog_131209_Content_10 = {
    Text = "Se avessi scelto di fare la cantante d'opera, le file al teatro si sarebbero estese per tre isolati lungo la strada."
  },
  AvgDialog_131209_Content_11 = {
    Text = "È una tragedia che le marionette di Londinium non abbiano mai assistito alla mia spettacolare esibizione. Da questo punto di vista, sei una piccola fortunata."
  },
  AvgDialog_131209_Content_12 = {
    Text = "Nefraea pizzica le guance della bambina con finto affetto, come una madre che accarezza un'amata figlia."
  },
  AvgDialog_131209_Content_13 = {
    Text = "Al centro della navata della cattedrale, chiodi d'acciaio trafiggono il petto, l'addome, le spalle, gli stinchi e i palmi della bambina — perforando ogni punto adatto alla sospensione e alla percezione del dolore, inchiodandola saldamente a un massiccio lampadario a ruota."
  },
  AvgDialog_131209_Content_14 = {
    Text = "Nefraea porta una mano macchiata di sangue al naso e chiude gli occhi in un'ossessione."
  },
  AvgDialog_131209_Content_15 = {
    Text = "Ah... il profumo del sangue vivo. Così vibrante."
  },
  AvgDialog_131209_Content_16 = {
    Text = "Per anni ho tentato di tutto — squarciando i corpi dei fanciulli, persino la mia stessa carne — eppure non sono mai riuscita ad assaporare una sola goccia di vitalità."
  },
  AvgDialog_131209_Content_17 = {
    Text = "Il destino corretto. Uno spirito ardente. Che invidia... ma lo sapevi? Eri destinata a essere gettata nel cumulo di scarti del Fato, proprio come noi."
  },
  AvgDialog_131209_Content_18 = {
    Text = "Non hai bisogno di cibo, e non parli mai. A parte le memorie che custodisci per lei, non sei nulla e non sai nulla."
  },
  AvgDialog_131209_Content_19 = {
    Text = "Il Fato ti ha abbandonata molto tempo fa, povera creatura. Non sei che una bambola che lei usa per conforto — una becchina delle sue memorie, che vaga sola su questo palcoscenico vuoto."
  },
  AvgDialog_131209_Content_2 = {
    Text = "<Shake:La...♪ La la...♪>"
  },
  AvgDialog_131209_Content_20 = {
    Text = "Osserva la bambina, che a questo punto respira appena, la voce tremante di un dolore simulato mentre le scosta una ciocca ribelle dalla tempia."
  },
  AvgDialog_131209_Content_21 = {
    Text = "Ora, la tua crudele madre, il Fato, sta arrivando... Qualunque cosa accada, accoglila nella tua versione più bella, d'accordo?"
  },
  AvgDialog_131209_Content_22 = {Text = "..."},
  AvgDialog_131209_Content_23 = {
    Text = "Una volta abituati alla luce fioca della chiesa, una serie di enormi affreschi cattura il vostro sguardo."
  },
  AvgDialog_131209_Content_24 = {
    Text = "Pigmenti viscosi si spalmano su pareti alte decine di metri, estendendosi fino a un soffitto di oscurità assoluta. Imponenti, sacri e luridi — come la statua di un santo salvatore eretta in una fogna."
  },
  AvgDialog_131209_Content_25 = {
    Text = "La premurosa padrona di casa ha sgomberato la stanza, lasciando solo l'eco dei vostri passi e del vostro respiro. Camminate sotto l'imponente affresco e alzate lo sguardo."
  },
  AvgDialog_131209_Content_26 = {
    Text = "Una donna siede a un filatoio, tagliando fili di seta con delle forbici... è un ritratto di te, Arachne?"
  },
  AvgDialog_131209_Content_27 = {
    Text = "Sembrerebbe proprio di sì. Credo che queste siano le parole che mia sorella desidera trasmettere."
  },
  AvgDialog_131209_Content_28 = {
    Text = "Arachne non mostra fretta nel cercare le \"Memorie\". Piuttosto, vi segue, studiando gli affreschi con quieto interesse."
  },
  AvgDialog_131209_Content_29 = {
    Text = "Una figura identica si separa dalla donna seduta e precipita nell'oscurità di una caverna..."
  },
  AvgDialog_131209_Content_3 = {
    Text = "Scricchiolio — scricchiolio — la Dea del Fato gira il Suo arcolaio."
  },
  AvgDialog_131209_Content_30 = {
    Text = "Nella caverna oscura, una donna e altre creature della notte eseguono una danza bizzarra. Tiene in mano... un filatoio?"
  },
  AvgDialog_131209_Content_31 = {
    Text = "Il centro risplende come una Lanterna, illuminando le ombre."
  },
  AvgDialog_131209_Content_32 = {
    Text = "Una donna che porta una Lanterna a forma di filatoio giunge in una città... un gruppo di figure in tonaca si inginocchia davanti a lei. Il sigillo sui loro abiti... è il sigillo del Portatore di Luce?!"
  },
  AvgDialog_131209_Content_33 = {
    Text = "Differisce leggermente dai sigilli che avete visto prima — attorno a quel sinistro triangolo rovesciato si trova un anello aggiuntivo, simile a un filatoio."
  },
  AvgDialog_131209_Content_34 = {
    Text = "Ma ne riconoscete gli elementi. Sapete esattamente di cosa si tratta. Questa è la nascita della Chiesa dei Portatori di Luce."
  },
  AvgDialog_131209_Content_35 = {
    Text = "L'ultimo..."
  },
  AvgDialog_131209_Content_36 = {
    Text = "L'ultimo affresco si erge alla fine del corridoio come un cancello che sigilla il Fato. La pittura sudicia ondeggia sulla superficie, riflettendo le ombre torbide della cappella."
  },
  AvgDialog_131209_Content_37 = {
    Text = "Una donna regge una Lanterna, inginocchiata davanti a una figura sfocata. Dietro di loro incombe qualcosa di enorme..."
  },
  AvgDialog_131209_Content_38 = {Text = "Ugh..."},
  AvgDialog_131209_Content_39 = {
    Text = "Quando riconoscete quell'immenso bulbo oculare semichiuso, una fitta violenta vi attraversa, sollevando onde tumultuose nella vostra mente."
  },
  AvgDialog_131209_Content_4 = {
    Text = "Scricchiolio — scricchiolio — i Fili del Fato convergono nelle sue mani."
  },
  AvgDialog_131209_Content_40 = {
    Text = "Distogli rapidamente lo sguardo e fai un respiro profondo per placare l'ondata di nausea che sale."
  },
  AvgDialog_131209_Content_41 = {
    Text = "<Shake:Huff... huff...> I Portatori di Luce... Tohuwabohu..."
  },
  AvgDialog_131209_Content_42 = {
    Text = "In questa dimensione, Nefraea era in realtà... la fondatrice della Chiesa dei Portatori di Luce!"
  },
  AvgDialog_131209_Content_43 = {
    Text = "Ora vedo. Capisco!..."
  },
  AvgDialog_131209_Content_44 = {
    Text = "Hai visto la verità, {Male=Sig.,Female=Sig.na} Custode. Mentre la Divinità Suprema si avvicinava al suo risveglio, la mia sorella rinnegata è fuggita dalla Prigione Abissale."
  },
  AvgDialog_131209_Content_45 = {
    Text = "La sua Interferenza ha offuscato la mia Visuale, permettendole di nascondere questo culto sotto il mio Livello."
  },
  AvgDialog_131209_Content_46 = {
    Text = "Colui che ella venerava era l'Apostolo — l'essere connesso a quella Divinità Suprema in questa Dimensione."
  },
  AvgDialog_131209_Content_47 = {
    Text = "Osservi di nuovo la Figura Oscura sfocata sul murale, quella disegnata accanto a Tohuwabohu."
  },
  AvgDialog_131209_Content_48 = {
    Text = "Capisco... Nefraea vuole usare il Potere dell'Apostolo per ristabilire un legame con Tohuwabohu!"
  },
  AvgDialog_131209_Content_49 = {
    Text = "Ma se è così, perché dare la caccia ai Burattini...?"
  },
  AvgDialog_131209_Content_5 = {
    Text = "Le marionette marciano in fila, addentrandosi nella Grande Trama."
  },
  AvgDialog_131209_Content_50 = {Text = "CLANG—"},
  AvgDialog_131209_Content_51 = {
    Text = "Un rintocco torbido risuona dalla torre campanaria. Un Oracolo Divino immondo."
  },
  AvgDialog_131209_Content_52 = {
    Text = "La cattedrale rimbomba con un rombo cupo. Tra i pesanti Tremori, le pareti di pietra che reggono i murali si sollevano stridendo verso l'alto."
  },
  AvgDialog_131209_Content_53 = {Text = "Là!!"},
  AvgDialog_131209_Content_54 = {
    Text = "Signora... Arachne..."
  },
  AvgDialog_131209_Content_55 = {
    Text = "Oh, povere... le nostre piccole \"Memorie.\" La tua Voce è così debole, è quasi pietosa."
  },
  AvgDialog_131209_Content_56 = {
    Text = "Nefraea! Lasciala andare!"
  },
  AvgDialog_131209_Content_57 = {
    Text = "L'esile corpo della ragazza pende dal grande lampadario a filatoio. Sangue Cremisi si espande sul pavimento di marmo bianco."
  },
  AvgDialog_131209_Content_58 = {
    Text = "Luci intense risplendono alle sue spalle, proiettando una sacra silhouette attorno al suo corpo intriso di sangue."
  },
  AvgDialog_131209_Content_59 = {
    Text = "Nefraea, poni fine a questo conflitto insensato. Rilasciala."
  },
  AvgDialog_131209_Content_6 = {
    Text = "Danzano. Cantano. Scricchiolio — scricchiolio —"
  },
  AvgDialog_131209_Content_60 = {
    Text = "Oh? La nostra Dea del Fato improvvisamente si preoccupa delle sue \"Memorie\" adesso?"
  },
  AvgDialog_131209_Content_61 = {
    Text = "Non ti è mai importato. Li hai abbandonati, Arachne."
  },
  AvgDialog_131209_Content_62 = {
    Text = "Nefraea, so che vuoi evocare il Richiamo dell'Apostolo e risvegliare Tohuwabohu... possiamo trovare un'altra via. Non c'è bisogno di Ucciderli."
  },
  AvgDialog_131209_Content_63 = {
    Text = "Il modo in cui cerchi di guadagnare tempo è adorabilmente infantile, %player%."
  },
  AvgDialog_131209_Content_64 = {
    Text = "Non capisci nulla. Non li ho mai uccisi. Li sto semplicemente riportando a casa."
  },
  AvgDialog_131209_Content_65 = {
    Text = "Ti ho portato qui solo perché potessi assistere al loro perfetto finale insieme."
  },
  AvgDialog_131209_Content_66 = {
    Text = "Atto Secondo, Scena Terza. Lo chiamo... \"Felice Ricongiungimento.\""
  },
  AvgDialog_131209_Content_67 = {
    Text = "Nefraea ti lancia uno sguardo sprezzante. La sua unghia sfiora la guancia di Memorie, lasciando una sottile Traiettoria rossa."
  },
  AvgDialog_131209_Content_68 = {
    Text = "Si china, osservando il volto tremante della ragazza con una tenerezza predatoria."
  },
  AvgDialog_131209_Content_69 = {
    Text = "Brava bambina, non avere paura. Saremo a casa presto."
  },
  AvgDialog_131209_Content_7 = {
    Text = "Muoiono con la Grande Trama, in silenzio e senza lasciare traccia."
  },
  AvgDialog_131209_Content_70 = {
    Text = "Di' addio ai tuoi miserabili ricordi, cara sorella!"
  },
  AvgDialog_131209_Content_71 = {
    Text = "Fermati... Nefraea!"
  },
  AvgDialog_131209_Content_72 = {Text = "Pop—"},
  AvgDialog_131209_Content_73 = {
    Text = "Con uno schiocco secco delle dita di Nefraea, il corpo della bambina esplode come un vivido fuoco d'artificio cremisi."
  },
  AvgDialog_131209_Content_74 = {
    Text = "La Luce della Lanterna cattura gli schizzi, proiettando un fiore rosso sangue sul murale."
  },
  AvgDialog_131209_Content_75 = {
    Text = "Gocce di sangue volano nell'aria, si librano sospese, poi invertono la rotta, precipitandosi avide verso Nefraea e macchiando ogni centimetro della sua pelle."
  },
  AvgDialog_131209_Content_76 = {
    Text = "Il sangue si insinua nei suoi abiti e nella sua carne, inondandole le vene e scorrendo impetuoso attraverso il suo esile corpo."
  },
  AvgDialog_131209_Content_77 = {
    Text = "Nefraea lecca il sangue dalle labbra e spalanca le braccia, come una signora gentile che dà il bentornato a una persona cara."
  },
  AvgDialog_131209_Content_78 = {
    Text = "Bentornata a casa, tesoro."
  },
  AvgDialog_131209_Content_79 = {Text = "Basta!"},
  AvgDialog_131209_Content_8 = {
    Text = "Il canto riecheggia attraverso la chiesa cavernosa. Nefraea spalanca le braccia, assaporando il suono della propria voce."
  },
  AvgDialog_131209_Content_80 = {
    Text = "Nell'istante in cui quel piccolo corpo si frantuma, una luce argentea sboccia dalle tue mani mentre ti lanci verso Nefraea."
  },
  AvgDialog_131209_Content_81 = {
    Text = "Sotto la luce sacra e sanguinaria, innumerevoli ombre si protendono dai luridi murali per bloccarti il Sentiero..."
  },
  AvgDialog_131209_Content_9 = {
    Text = "Allora? Ero intonata?"
  },
  AvgDialog_131210_Content_1 = {
    Text = "Non mi aspettavo che avresti avuto un aspetto così patetico al nostro prossimo incontro."
  },
  AvgDialog_131210_Content_2 = {Text = "Thais..."},
  AvgDialog_131210_Content_3 = {
    Text = "Tawil ha ragione. Va tutto bene, Custode."
  },
  AvgDialog_131210_Content_4 = {
    Text = "Mi hai promesso di mostrarmi un altro finale. Credo in te, ora e per sempre."
  },
  AvgDialog_131210_Content_5 = {
    Text = "Che tu ti fermi qui o mi oltrepassi, io sono sempre al tuo fianco."
  },
  AvgDialog_131211_Content_1 = {Text = "Bozzolo"},
  AvgDialog_131211_Content_10 = {
    Text = "Non voglio mai più rivivere una cosa simile..."
  },
  AvgDialog_131211_Content_11 = {
    Text = "Non sei sicuro/a di pensarlo davvero. Stringi il pugno, riadattandoti al corpo che hai appena condiviso con \"N\"."
  },
  AvgDialog_131211_Content_12 = {
    Text = "La Visuale si schiarisce. Massaggiandoti la testa pulsante, ti dirigi verso la fragile figura inginocchiata al bordo del palco."
  },
  AvgDialog_131211_Content_13 = {
    Text = "Nefraea, il tuo piano ormai—"
  },
  AvgDialog_131211_Content_14 = {
    Text = "Vi prego, fate attenzione."
  },
  AvgDialog_131211_Content_16 = {
    Text = "Come se un filo ti trattenesse, il tuo passo rallenta. Un affilato Artiglio nero di ragno fende l'aria, sfiorando pericolosamente i tuoi occhi."
  },
  AvgDialog_131211_Content_17 = {
    Text = "Otto enormi arti velenosi le squarciano i vestiti lungo la spina dorsale, dibattendosi e contorcendosi nell'aria. Nefraea sembra del tutto indifferente ad essi."
  },
  AvgDialog_131211_Content_18 = {
    Text = "Frammenti del Passaggio dimensionale fluttuano attorno a lei come coriandoli. Le sue lacrime cadono, bagnando la scura ruota spezzata tra le sue mani. La sua luce si è spenta."
  },
  AvgDialog_131211_Content_19 = {
    Text = "Il portale è svanito. Non hai più possibilità."
  },
  AvgDialog_131211_Content_2 = {
    Text = "...Custo..."
  },
  AvgDialog_131211_Content_20 = {
    Text = "Il Fato percorre il Sentiero che gli è destinato, Nefraea. Accettalo."
  },
  AvgDialog_131211_Content_21 = {
    Text = "Un'occasione? Heh... hahaha!"
  },
  AvgDialog_131211_Content_22 = {
    Text = "Il suo corpo fragile trema di risa, i suoi arti velenosi tracciano Traiettorie strazianti nell'aria."
  },
  AvgDialog_131211_Content_23 = {
    Text = "Non ho mai avuto un'occasione, né ne ho mai avuto bisogno."
  },
  AvgDialog_131211_Content_24 = {
    Text = "Libertà, Infanzia, famiglia, amore, identità... Il Fato ci ha rubato tutto. Non sarò mai, mai sua Prigioniera come te."
  },
  AvgDialog_131211_Content_25 = {
    Text = "Nefraea si alza lentamente, posizionandosi all'interno della fioca ruota frantumata."
  },
  AvgDialog_131211_Content_26 = {
    Text = "Guarda bene, Arachne! Farò ciò che hai disperatamente bramato ma non hai mai osato!"
  },
  AvgDialog_131211_Content_27 = {
    Text = "Con un ruggito furioso, il corpo di Nefraea viene trafitto da innumerevoli Spuntoni. Il Sangue sgorga dalle sue Ferite, collegandosi alla ruota spezzata come una ragnatela macabra."
  },
  AvgDialog_131211_Content_28 = {
    Text = "<Shake:@2—!>"
  },
  AvgDialog_131211_Content_29 = {
    Text = "Uno Strido ad alta frequenza oltre la sopportazione umana erutta da Nefraea. Il suo corpo è scosso da Tremori di Agonia mentre vene viola scuro si gonfiano sulla sua pelle."
  },
  AvgDialog_131211_Content_3 = {
    Text = "{Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_131211_Content_30 = {
    Text = "I frammenti del passaggio dimensionale cessano di vagare, attratti verso la ragnatela di sangue. La ruota oscura si riaccende con un cupo, sanguigno fulgore."
  },
  AvgDialog_131211_Content_31 = {
    Text = "Heh... Hahaha! <Big:<Shake:Se non ci sono dèi, diventerò io stessa una divinità!>>"
  },
  AvgDialog_131211_Content_32 = {
    Text = "La mia storia... il mio palcoscenico... non finiranno mai! Porterò la liberazione a questa ragnatela che non sarebbe mai dovuta esistere... <Big:<Shake:<Red:liberazione!!!>>>"
  },
  AvgDialog_131211_Content_33 = {
    Text = "Nello strido agonizzante di Nefraea, l'intero Teatro del Destino trema violentemente. Le marionette crollano e si scontrano, i loro fili si aggrovigliano in un groviglio scomposto."
  },
  AvgDialog_131211_Content_34 = {
    Text = "Arachne la osserva mentre viene consumata dal potere e dalla follia. Il pianto increspa i suoi occhi profondi, proprio come il giorno in cui per la prima volta recise una parte di sé."
  },
  AvgDialog_131211_Content_35 = {
    Text = "Ho cercato di liberarti da questa maledizione... Mi sbagliavo, Nefraea."
  },
  AvgDialog_131211_Content_36 = {
    Text = "La maledizione è ineluttabile. Questa gabbia... non potremo mai lasciarla."
  },
  AvgDialog_131211_Content_37 = {
    Text = "Quei frammenti... quella ruota!"
  },
  AvgDialog_131211_Content_38 = {
    Text = "Nefraea sta assorbendo il potere residuo del passaggio! Sta trasformando se stessa nello Stoppino!"
  },
  AvgDialog_131211_Content_39 = {
    Text = "Un flebile sospiro echeggia attraverso il teatro tremante."
  },
  AvgDialog_131211_Content_4 = {
    Text = "<Shake:Ugh... coff, coff...>"
  },
  AvgDialog_131211_Content_40 = {
    Text = "Tieniti forte, {Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_131211_Content_41 = {Text = "Cosa..."},
  AvgDialog_131211_Content_42 = {
    Text = "<Shake:Boom—>"
  },
  AvgDialog_131211_Content_43 = {
    Text = "Prima ancora che le sue parole potessero svanire, l'intero teatro si squarcia. Nefraea strappa i Fili del Destino. Attraverso l'orrifica fenditura, gli edifici della città e i detriti dimensionali si aggrovigliano insieme."
  },
  AvgDialog_131211_Content_44 = {
    Text = "Il palcoscenico principale si frantuma. Frammenti di passato, futuro e presente si intrecciano nel caos sul palco distrutto, formando una scena incomprensibile."
  },
  AvgDialog_131211_Content_45 = {
    Text = "Arachne... la tua tela!"
  },
  AvgDialog_131211_Content_46 = {
    Text = "La ruota di Arachne gira a un ritmo furioso. Immense Braci Dimensionali sgorgano da lei, fluendo lungo i fili per riparare i vuoti infranti nella Grande Ragnatela, tenendo a malapena insieme il palcoscenico."
  },
  AvgDialog_131211_Content_47 = {
    Text = "Guidato dai fili, ti rialzi a fatica."
  },
  AvgDialog_131211_Content_48 = {
    Text = "Stai assorbendo il Suo potere disperso per alterare il corso del Destino... ma tu non sei un frammento di Tohuwabohu. Non puoi sopportare questa pressione. Non devi morire in tale agonia, Nefraea."
  },
  AvgDialog_131211_Content_49 = {
    Text = "Agonia? No, sono esaltata, sorella! Ho sognato questo ogni singolo istante nella Prigione Abissale."
  },
  AvgDialog_131211_Content_5 = {
    Text = "Cosa è successo..."
  },
  AvgDialog_131211_Content_50 = {
    Text = "Questa fantasia è l'unica cosa che mi ha tenuta in vita!"
  },
  AvgDialog_131211_Content_51 = {
    Text = "La risata maniacale di Nefraea risuona attraverso lo spazio frantumato. Alza il capo, assorbendo avidamente gli ultimi residui di luce."
  },
  AvgDialog_131211_Content_52 = {
    Text = "Un dio dormiente, un destino rubato... non importa! Se il dio non ci benedirà, lo farò io al Suo posto!"
  },
  AvgDialog_131211_Content_53 = {
    Text = "Vendicatori del Destino, salite sul palco! <Red:Questo atto appartiene a voi!>"
  },
  AvgDialog_131211_Content_54 = {
    Text = "Nefraea alza la mano. Un'infinita melma nera sgorga dal suo corpo, tessendo una ragnatela oscura nel vuoto del teatro."
  },
  AvgDialog_131211_Content_55 = {
    Text = "Innumerevoli rancori, un tempo scartati dal Fato, prendono forma fisica. Strisciano lungo l'immensa ragnatela in una marea travolgente, riversandosi verso di te."
  },
  AvgDialog_131211_Content_56 = {
    Text = "Arachne, i nostri corpi...!!"
  },
  AvgDialog_131211_Content_57 = {
    Text = "Scopri un filo nero, appena visibile, che emerge dalla figura di Arachne."
  },
  AvgDialog_131211_Content_58 = {
    Text = "Alzi lo sguardo e trovi un filo nero simile che si estende da te, da ogni palcoscenico e da ogni marionetta. Tutti conducono al fuso nelle mani di Nefraea."
  },
  AvgDialog_131211_Content_59 = {
    Text = "Ave, Arachne! Sia benedetta la Dea del Fato!"
  },
  AvgDialog_131211_Content_6 = {
    Text = "Intense vertigini e Spasmi allo stomaco sono i relitti lasciati dall'Estasi. Combatti la nausea e lentamente ti rialzi."
  },
  AvgDialog_131211_Content_60 = {
    Text = "Sguainate le lame, soldati! Combattete per il nostro destino!"
  },
  AvgDialog_131211_Content_61 = {
    Text = "Signorina Arachne, accetta il tuo destino... cessa questa futile resistenza."
  },
  AvgDialog_131211_Content_62 = {
    Text = "Non preoccuparti, cara. La tua liberazione arriverà presto. Molto presto..."
  },
  AvgDialog_131211_Content_63 = {
    Text = "Arachne chiude gli occhi. Le sue mani tremano mentre stringe i fili in preda all'agonia."
  },
  AvgDialog_131211_Content_64 = {
    Text = "Arachne chiude gli occhi. Le sue mani tremano mentre stringe i fili in preda all'agonia."
  },
  AvgDialog_131211_Content_65 = {
    Text = "Nefraea, loro non possono aiutarti a diventare la divinità che cerchi. Facendo questo, li condanni soltanto a un altro ciclo di distruzione straziante."
  },
  AvgDialog_131211_Content_66 = {
    Text = "Che importa? Non cerchiamo altro che vendetta! Non è forse così, miei compagni figli abbandonati dal Fato?"
  },
  AvgDialog_131211_Content_67 = {
    Text = "<Shake:Heh... hahaha!>"
  },
  AvgDialog_131211_Content_68 = {
    Text = "Risate acute, rimbombanti e laceranti erompono dalle infinite ragnatele nere — un coro di pura agonia."
  },
  AvgDialog_131211_Content_69 = {
    Text = "I Fati Abbandonati urlano e si lamentano, formando un muro d'ombra davanti a Nefraea."
  },
  AvgDialog_131211_Content_7 = {
    Text = "La coscienza dell'Apostolo ha abbandonato il fuso. Recisa dal Divino, è ora completamente distrutta. L'Autorità degli Eoni si è placata."
  },
  AvgDialog_131211_Content_70 = {
    Text = "Le porte dell'Abisso sono spalancate. Contempla, Arachne! Contempla i destini che hai forgiato con le tue stesse mani! Guarda i tuoi amati figli!"
  },
  AvgDialog_131211_Content_71 = {
    Text = "Guarda la loro agonia, la loro disperazione... guardali, e poi uccidili ancora una volta!"
  },
  AvgDialog_131211_Content_72 = {
    Text = "Osserva ogni Filo del Fato che gira e si frantuma nei miei palmi! Sii testimone della mia ascensione! Io sono la dea che porta la fine!"
  },
  AvgDialog_131211_Content_73 = {
    Text = "Frammenti dimensionali, carichi di potere divino e volontà maniacale, trafiggono la carne di Nefraea uno a uno. Il sangue vitale si riversa senza fine nella sua ruota."
  },
  AvgDialog_131211_Content_74 = {
    Text = "Il suo volto si contorce dall'agonia, eppure la sua risata si fa solo più frenetica."
  },
  AvgDialog_131211_Content_75 = {
    Text = "Osserva il palcoscenico in rovina con trepidante attesa, come una drammaturga che aspetta il debutto del suo capolavoro."
  },
  AvgDialog_131211_Content_76 = {
    Text = "L'Abisso si è manifestato su questo palcoscenico... Nefraea sta sacrificando la sua stessa esistenza."
  },
  AvgDialog_131211_Content_77 = {
    Text = "Intende trasformare ogni anima presente nelle sue marionette. Cerca di diventare quella dea. Cerca di diventare il Fato stesso."
  },
  AvgDialog_131211_Content_78 = {
    Text = "Arachne parla con la calma distaccata di una spettatrice che non è mai veramente entrata nella rappresentazione. Braci Dimensionali recuperate fluttuano attorno alle sue dita come sabbia infinita e mutevole."
  },
  AvgDialog_131211_Content_79 = {
    Text = "La sua ruota geme mentre gira, lottando per preservare i destini che Nefraea cerca di disfare. Combatte per impedire ai fili neri di convergere nella presa di sua sorella."
  },
  AvgDialog_131211_Content_8 = {
    Text = "Hai messo in scena una magnifica rappresentazione."
  },
  AvgDialog_131211_Content_80 = {
    Text = "Le mie braci sono tornate. Non ho più motivo di esitare."
  },
  AvgDialog_131211_Content_81 = {
    Text = "Aiutami a raggiungerla. La ruota di Nefraea si sta fermando. Insieme, correggeremo questo destino infranto."
  },
  AvgDialog_131211_Content_82 = {
    Text = "Aiutami... concedi a queste anime abbandonate la loro liberazione."
  },
  AvgDialog_131211_Content_9 = {
    Text = "Uff... non riesco a credere che quelle parole siano davvero uscite dalla mia bocca."
  },
  AvgDialog_131212_Content_1 = {
    Text = "Nel frattempo, dall'altra parte della città..."
  },
  AvgDialog_131212_Content_10 = {
    Text = "Il numero sei è stato selezionato personalmente dalle scuderie del Duca. Vincerà la coppa, segna le mie parole. Punta tutto sul sei!"
  },
  AvgDialog_131212_Content_11 = {
    Text = "Le Chiacchiere della metropolitana scorrono come un ruscello gorgogliante. Arachne fissa in silenzio le luci che sfrecciano oltre il finestrino, sorridendo mentre ascolta le sue marionette discutere di spettacoli, corse di cavalli e matrimoni."
  },
  AvgDialog_131212_Content_12 = {
    Text = "Gira il suo fuso in Silenzio. Fra i miliardi di fili intricati, assapora questo fugace momento di pace."
  },
  AvgDialog_131212_Content_13 = {
    Text = "Mia signora, ci avviciniamo alla nostra fermata. La carrozza è pronta, e le nostre sorelle vi attendono al punto di trasferimento."
  },
  AvgDialog_131212_Content_14 = {
    Text = "Brava bambina."
  },
  AvgDialog_131212_Content_15 = {
    Text = "Scruta le marionette ancora immerse nelle loro esibizioni, simile a una spettatrice che non riesce a lasciare il proprio posto."
  },
  AvgDialog_131212_Content_16 = {
    Text = "Ricordate quanto tempo è passato dall'ultima volta che abbiamo lasciato il teatro?"
  },
  AvgDialog_131212_Content_17 = {
    Text = "Sono al vostro fianco dal giorno in cui sono diventata un Ragno di Leng. Cinquant'anni? Sessanta? Ho perso il conto."
  },
  AvgDialog_131212_Content_18 = {
    Text = "Ma questa volta siamo rimaste lontane dal teatro per parecchio tempo."
  },
  AvgDialog_131212_Content_19 = {
    Text = "Devo ringraziare Nefraea per questo. Se non fosse stato per il suo arrivo, non avrei mai avuto l'occasione di indugiare così a lungo all'esterno."
  },
  AvgDialog_131212_Content_2 = {
    Text = "Biglietto, prego. Signore, posso vedere il suo biglietto?"
  },
  AvgDialog_131212_Content_20 = {
    Text = "Abbiamo cacciato centinaia di scudieri abissali al fianco del Custode. Una volta che avremo salvato \"Memorie,\" sarà tempo di tornare a casa."
  },
  AvgDialog_131212_Content_21 = {
    Text = "Chissà quando avremo di nuovo un'occasione simile..."
  },
  AvgDialog_131212_Content_22 = {
    Text = "Come percependo i suoi pensieri, le luci della metropolitana si affievoliscono. Lei fissa l'oscurità, cercando tra le memorie di mille civiltà che si alzano e si abbassano qualche traccia ordinaria di sé stessa."
  },
  AvgDialog_131212_Content_23 = {
    Text = "Due secondi scorrono. La signora della città nota che il vivace chiacchiericcio svanisce nell'istante in cui il treno sprofonda nell'oscurità totale."
  },
  AvgDialog_131212_Content_24 = {
    Text = "Mia signora, qualcosa non..."
  },
  AvgDialog_131212_Content_25 = {Text = "CRACK—"},
  AvgDialog_131212_Content_26 = {
    Text = "Il sangue gelido dell'ancella schizza sul volto placido di Arachne, portando con sé la delicata fragranza degli iris."
  },
  AvgDialog_131212_Content_27 = {
    Text = "Le luci tornano tremolando. Arachne vede il corpo reciso della sua ancella e la lama che l'ha trapassata, ancora in movimento. Dietro l'acciaio, i fantocci le si avventano addosso come un branco di bestie affamate."
  },
  AvgDialog_131212_Content_28 = {Text = "..."},
  AvgDialog_131212_Content_29 = {
    Text = "I freni gemono con uno stanco strido metallico. La brezza che ne risulta agita i capelli di un'altra ancella."
  },
  AvgDialog_131212_Content_3 = {
    Text = "Non l'hanno appena controllato alla Porta? È esattamente così che si sperperano i soldi dei contribuenti..."
  },
  AvgDialog_131212_Content_30 = {
    Text = "Ah! Siamo arrivati!"
  },
  AvgDialog_131212_Content_31 = {
    Text = "Le porte si aprono, ma nessuna folla emerge. Solo un denso rivolo metallico di sangue filtra attraverso le fessure, scorrendo in un silenzioso ensemble."
  },
  AvgDialog_131212_Content_32 = {
    Text = "Calcando il fiume di sangue, Arachne scende. Le sue vesti restano immacolate; il suo fuso continua a girare, senza mai fermarsi."
  },
  AvgDialog_131212_Content_33 = {
    Text = "Quello è..."
  },
  AvgDialog_131212_Content_34 = {
    Text = "Un affascinante spettacolo di teatro interattivo. Essere al contempo pubblico e attrice rende l'esperienza assai più vivida di quella di un drammaturgo."
  },
  AvgDialog_131212_Content_35 = {
    Text = "Guarda l'ancella dinanzi a sé, la sua espressione indecifrabile."
  },
  AvgDialog_131212_Content_36 = {
    Text = "Le mie ancelle sono con me da molti anni. Raramente tocco i fili dei loro fati."
  },
  AvgDialog_131212_Content_37 = {
    Text = "In quel tetro teatro, erano tra le poche anime vibranti."
  },
  AvgDialog_131212_Content_38 = {
    Text = "Oggi hai ucciso due delle mie ancelle. Una simile violazione del Fato ha un prezzo, Nefraea."
  },
  AvgDialog_131212_Content_39 = {
    Text = "Ehehehe… <Shake:Ahahaha!> Quanto sei nobile, Arachne."
  },
  AvgDialog_131212_Content_4 = {
    Text = "Charlie! Dov'è la mia spilla?"
  },
  AvgDialog_131212_Content_40 = {
    Text = "Come burro gettato in una padella rovente, il corpo dell'ancella si scioglie. Sotto la fanghiglia nera ribollente, un volto identico a quello di Arachne ride con gioia sfrenata."
  },
  AvgDialog_131212_Content_41 = {
    Text = "<Italic:\"Contemplate! Io sono il Padrone del Destino, il diligente carnefice! Sceglierò i sentieri giusti e getterò ogni errore nell'abisso!\">"
  },
  AvgDialog_131212_Content_42 = {
    Text = "Tu sei il mio idolo, la mia fede, cara sorella. Sto semplicemente interpretando il tuo ruolo."
  },
  AvgDialog_131212_Content_43 = {
    Text = "Allora? Sono stata una Studente degna?"
  },
  AvgDialog_131212_Content_44 = {
    Text = "Arachne sostiene in silenzio lo sguardo di Nefraea. Gli occhi che ricambiano sono luminosi e colmi di attesa, come quelli di una bambina che aspetta la lode dell'amata sorella."
  },
  AvgDialog_131212_Content_45 = {
    Text = "Banchine, scale, colonnati... mentre parla, ombre si manifestano in ogni angolo della stazione."
  },
  AvgDialog_131212_Content_46 = {
    Text = "Le loro aure torbide si intrecciano, convergendo nelle mani di Nefraea come una vasta rete che si stringe attorno ad Arachne."
  },
  AvgDialog_131212_Content_47 = {
    Text = "Le labbra di Arachne si incurvano in un dolce sorriso."
  },
  AvgDialog_131212_Content_48 = {
    Text = "Non avrei mai immaginato che qualcuno avrebbe provato a intrappolare <Italic:me> in una rete."
  },
  AvgDialog_131212_Content_49 = {
    Text = "Hai mai visto un baco da seta, sorella? Passano la vita a non fare altro che mangiare e filare seta... e poi aspettano che i bozzoli che hanno tessuto li soffochino."
  },
  AvgDialog_131212_Content_5 = {
    Text = "Non l'avevo appuntata al tuo vestito prima di partire?"
  },
  AvgDialog_131212_Content_50 = {
    Text = "Quasi tutti i tuoi scudieri sono periti negli angoli di questa città e su questo treno. Erano i tuoi unici compagni durante quei lunghi anni nel vuoto."
  },
  AvgDialog_131212_Content_51 = {
    Text = "Hai dato loro un finale che non avrebbero mai dovuto avere. Il Fato non può essere sfidato, Nefraea."
  },
  AvgDialog_131212_Content_52 = {
    Text = "Vuoi dire che il loro Fato \"corretto\" era marcire in quella prigione oscura per l'eternità? È così, stimato Padrone del Destino?"
  },
  AvgDialog_131212_Content_53 = {
    Text = "Nefraea scuote il capo con una risata sprezzante."
  },
  AvgDialog_131212_Content_54 = {
    Text = "Li amo più di quanto tu possa immaginare. E mi hanno detto che se la morte potesse risparmiarli dall'essere imprigionati di nuovo, l'avrebbero abbracciata senza esitazione."
  },
  AvgDialog_131212_Content_55 = {
    Text = "Dopo questo massacro nei tunnel, quante braci ti restano per riparare il danno?"
  },
  AvgDialog_131212_Content_56 = {
    Text = "Nefraea ostenta il fuso nero nella sua mano. Innumerevoli fili dal livello della città sono collegati alla ruota immobile."
  },
  AvgDialog_131212_Content_57 = {
    Text = "I fili di questa città sono nelle mie mani. Non posso manipolarli... il che è un peccato, davvero, perché mi sto perdendo un bel po' di divertimento..."
  },
  AvgDialog_131212_Content_58 = {
    Text = "Per fortuna, mentre ripararli ti costa le tue preziose braci, inquinarli a me non costa nulla."
  },
  AvgDialog_131212_Content_59 = {
    Text = "Se semplicemente lasciassi andare... il tuo teatro e il tuo livello diventeranno il perfetto terreno di allevamento per il Caos. Proprio come il buco in cui ho trascorso la mia vita."
  },
  AvgDialog_131212_Content_6 = {
    Text = "Oh, cielo... Ho passato un mese a prepararmi per oggi! Senza quella spilla, questo abito non è altro che un sudario funebre..."
  },
  AvgDialog_131212_Content_60 = {
    Text = "E tu dovrai stare a guardare. Impotente di fronte al cambiamento. Impotente di fronte alla resistenza."
  },
  AvgDialog_131212_Content_61 = {
    Text = "Nefraea si avvicina ad Arachne e le accarezza dolcemente il volto."
  },
  AvgDialog_131212_Content_62 = {
    Text = "Cosa sarà, cara sorella? Mi obbedirai, o guarderemo insieme questo mondo trasformarsi in un inferno vivente?"
  },
  AvgDialog_131212_Content_63 = {
    Text = "Sei un frammento incompleto del Fato. Per inquinare un'intera città... ti manca la—"
  },
  AvgDialog_131212_Content_64 = {
    Text = "Lo schiocco di un filo di seta riecheggia nell'orecchio di Arachne. Alza lo sguardo, i suoi occhi colmi del pianto di una spettatrice."
  },
  AvgDialog_131212_Content_65 = {
    Text = "...Hai appena ucciso anche \"Memorie\"."
  },
  AvgDialog_131212_Content_66 = {
    Text = "No, io l'ho accettata. Romanticismo, Gentilezza, Memorie... una a una, ho riportato al Focolare tutto ciò che tu hai gettato via."
  },
  AvgDialog_131212_Content_67 = {
    Text = "Nefraea si alza e volteggia su se stessa con gioia."
  },
  AvgDialog_131212_Content_68 = {
    Text = "Una me completa. Una vendicatrice completa. Ti piace la vista, sorella?"
  },
  AvgDialog_131212_Content_69 = {
    Text = "Hai il Caos che bramavi. Perché aspettare ancora?"
  },
  AvgDialog_131212_Content_7 = {
    Text = "La Compagnia del Cycnus è abbastanza aggraziata, suppongo, ma se si trattasse di un conflitto di programma, sceglierei <Italic:Sogno nel Giardino di Smeraldo> ogni volta."
  },
  AvgDialog_131212_Content_70 = {
    Text = "Oh, no, no, no. Sono ancora molto, molto lontana da ciò che desidero davvero."
  },
  AvgDialog_131212_Content_71 = {
    Text = "Mi prenderò cura io del tuo fuso. Le tue Braci Dimensionali non si esauriranno mai. Non torcerò un capello a nessuno dei tuoi preziosi livelli."
  },
  AvgDialog_131212_Content_72 = {
    Text = "E tutto ciò che chiedo è un piccolo, piccolo Favore."
  },
  AvgDialog_131212_Content_73 = {
    Text = "Nefraea si avvicina, tracciando con lo sguardo la ruota che non smette mai di girare tra le mani di Arachne. Il suo respiro si spezza, alimentato dall'impeto della sua immaginazione febbrile."
  },
  AvgDialog_131212_Content_74 = {
    Text = "Prendi il controllo del Custode per me, cara sorella. Solo il Custode può portarmi ciò che desidero davvero."
  },
  AvgDialog_131212_Content_75 = {
    Text = "Sai bene che %player% è un frammento dell'Essere Supremo. Non possiamo comandare il {Male=suo,Female=suo} destino..."
  },
  AvgDialog_131212_Content_76 = {
    Text = "Una luce verdastra e malsana trasuda dal fuso nero tra le mani di Nefraea. Nel suo bagliore, un filo torbido e nascosto si manifesta davanti agli occhi di Arachne."
  },
  AvgDialog_131212_Content_77 = {
    Text = "Questo è... <Shake:il Filo del Fato del Custode?!>"
  },
  AvgDialog_131212_Content_78 = {
    Text = "<Shake:Heh...> <Big:<Shake:HAHAHAHA!>> È la prima volta che sento la tua voce tremare. Allora, sorella? Non è esaltante?!"
  },
  AvgDialog_131212_Content_79 = {
    Text = "Nella Prigione Abissale, l'Apostolo — incarnazione della volontà divina di <Italic:Esso> — fu intrappolato in questa ruota per servire da Stoppino. Era l'unica luce che avessimo mai avuto in quell'oscurità."
  },
  AvgDialog_131212_Content_8 = {
    Text = "L'Ensemble multistrato, la complessa narrativa non lineare... l'ascesa e la caduta dei giardini reali è di gran lunga superiore a quelle trame trite e ritrite."
  },
  AvgDialog_131212_Content_80 = {
    Text = "Con il nostro potere e la guida dell'Apostolo, <Big:persino il destino di un frammento divino riposa nelle NOSTRE mani!>"
  },
  AvgDialog_131212_Content_81 = {
    Text = "Questo non è il corso corretto del Destino, Nefraea... Nessuno può sfidare il Destino."
  },
  AvgDialog_131212_Content_82 = {
    Text = "Presto lo faranno, sorella. Una volta ottenute le Autorità dei Tre Eoni, l'Apostolo rinascerà! Riapriranno il canale verso il Divino; porteranno le voci dei Credenti nel Santuario Eterno!"
  },
  AvgDialog_131212_Content_83 = {
    Text = "La Divinità Suprema si risveglierà... e tu non dovrai mai più potare un altro destino agonizzante né tessere una tela destinata a frantumarsi."
  },
  AvgDialog_131212_Content_84 = {
    Text = "Nefraea inspira bruscamente, una singola lacrima traccia un solco attraverso la sua espressione estatica."
  },
  AvgDialog_131212_Content_85 = {
    Text = "La sua voce trema sotto il peso del suo splendido sogno. Attraverso un velo di lacrime, fissa in profondità il volto placido di Arachne."
  },
  AvgDialog_131212_Content_86 = {
    Text = "Smetti di combattermi, sorella. Ti porta solo pain."
  },
  AvgDialog_131212_Content_87 = {
    Text = "Vieni al mio fianco. Accogliamo insieme il Suo risveglio e doniamo a ogni livello il finale che merita!"
  },
  AvgDialog_131212_Content_9 = {
    Text = "Ha! Se punti sul numero otto, stai buttando via i soldi. So da fonte autorevole che qualcuno gli sta drogando il mangime oggi."
  },
  AvgDialog_131213_Content_1 = {
    Text = "Commedia Improvvisata"
  },
  AvgDialog_131213_Content_10 = {
    Text = "Ora, hai un nuovo credente—"
  },
  AvgDialog_131213_Content_100 = {
    Text = "Sto prendendo in prestito l'Autorità di \"N\"... <color=#98918C>Sto occupando metà della coscienza di %player%</color>... ma un nome è l'ultima cosa che conta adesso."
  },
  AvgDialog_131213_Content_101 = {
    Text = "Ciò che conta è che abbiamo lavorato bene insieme, Arachne."
  },
  AvgDialog_131213_Content_102 = {
    Text = "<Shake:Voi... voi tutti... lo sapevate fin dall'inizio...>"
  },
  AvgDialog_131213_Content_103 = {
    Text = "Lo sguardo debole di Nefraea si sposta da Arachne a te. Assapori avidamente il veleno e l'angoscia che vi ardono dentro. Ah, che fragranza inebriante..."
  },
  AvgDialog_131213_Content_104 = {
    Text = "Guarda bene, cara Nefraea, piccola piantagrane sfuggita dal vuoto."
  },
  AvgDialog_131213_Content_105 = {
    Text = "Il tuo gioco mi delizia. Un soffio della coscienza di Tohuwabohu, un frammento della divinità di Tohuwabohu... solo attraverso la loro unione l'Autorità degli Eoni poteva essere scatenata così perfettamente. Solo allora ho potuto finalmente assaporare un intrattenimento che non avevo mai conosciuto prima."
  },
  AvgDialog_131213_Content_106 = {
    Text = "Se potessi, continuerei a giocare così per sempre. È abbastanza divertimento per un'intera settimana..."
  },
  AvgDialog_131213_Content_107 = {
    Text = "Lasci sfuggire un sospiro di profondo rammarico."
  },
  AvgDialog_131213_Content_108 = {
    Text = "Ma ahimè, non posso permettere che continui. Se quel Dio dovesse risvegliarsi, questo magnifico luna park svanirebbe."
  },
  AvgDialog_131213_Content_109 = {
    Text = "Quindi, purtroppo... il climax deve finire. Alza lo sguardo, tesoro. In ogni caso, possiamo almeno concordare su una cosa riguardo a questa storia del Fato..."
  },
  AvgDialog_131213_Content_11 = {
    Text = "I fili del Fato guidano il tuo corpo. Intrecci le dita, stringi le mani al petto e lentamente ti inginocchi dinanzi all'arcolaio, chinando il capo in reverenza."
  },
  AvgDialog_131213_Content_110 = {
    Text = "Ti chini, afferrando il mento elegante di Nefraea in una presa beffarda, e avvicini le labbra al suo orecchio."
  },
  AvgDialog_131213_Content_111 = {
    Text = "La Distruzione è lo spettacolo più bello dell'universo, non è vero, mia cara?"
  },
  AvgDialog_131213_Content_112 = {
    Text = "Schiocchi le dita davanti ai suoi occhi. Il suono risuona di sconfinata euforia e rimpianto."
  },
  AvgDialog_131213_Content_113 = {Text = "Boom—"},
  AvgDialog_131213_Content_114 = {
    Text = "Il passaggio verso il Divino trema. Crepe si ramificano come ragnatele sulla sua superficie eterea..."
  },
  AvgDialog_131213_Content_115 = {
    Text = "<Big:<Shake:NOOOO!!—>>"
  },
  AvgDialog_131213_Content_116 = {
    Text = "Nefraea si lancia verso il passaggio, ma questo si frantuma a pochi centimetri dalle sue dita."
  },
  AvgDialog_131213_Content_117 = {
    Text = "Innumerevoli frammenti illusori fluttuano davanti a Nefraea come un caleidoscopio infranto; brandelli sgargianti di carta colorata a buon mercato riempiono l'aria, i loro bordi frastagliati le graffiano il volto."
  },
  AvgDialog_131213_Content_118 = {
    Text = "Sollevi il tuo invisibile cilindro, lo fai ruotare due volte e offri un profondo inchino alla sua schiena smarrita."
  },
  AvgDialog_131213_Content_119 = {
    Text = "Il Fato è un palcoscenico così divertente. E così, il sipario cala sul Terzo Atto. Ho apprezzato immensamente i vostri applausi e le vostre ovazioni."
  },
  AvgDialog_131213_Content_12 = {
    Text = "O Apostolo... della mia adorazione... Non sono che un'umile serva... di Voi e della Divinità Suprema... La vostra più fedele devota."
  },
  AvgDialog_131213_Content_120 = {
    Text = "Goditi lo spettacolo, mia cara Nefraea."
  },
  AvgDialog_131213_Content_121 = {
    Text = "Tra le urla strazianti di Nefraea, la coscienza dell'Apostolo si frantuma. Indossi un ultimo sorriso di Estasi mentre crolli sul palcoscenico."
  },
  AvgDialog_131213_Content_13 = {
    Text = "La tua gola e le tue membra assumono un fato proprio. Non ti appartengono più, e tu non fai alcun vano tentativo di reclamarle."
  },
  AvgDialog_131213_Content_14 = {
    Text = "Non cercare di controllare. Non cercare di comprendere. Godi. La verità dell'Estasi risiede dentro..."
  },
  AvgDialog_131213_Content_15 = {
    Text = "Guarda, sorella! Che attore straordinario hai addestrato!"
  },
  AvgDialog_131213_Content_16 = {
    Text = "Arachne siede in silenzio sotto il palcoscenico, il suo arcolaio che gira al suo ritmo eterno. Contempla il bagliore umbratile della Lanterna sul palco, un'osservatrice che segue diligentemente le convenienze."
  },
  AvgDialog_131213_Content_17 = {
    Text = "Mio caro Apostolo... il nostro Credente ti ha portato il Sacrificio che più desideri."
  },
  AvgDialog_131213_Content_18 = {
    Text = "Il fuso oscuro erutta in una Detonazione improvvisa, disperdendo una luce fioca e viscosa in ogni angolo del Livello."
  },
  AvgDialog_131213_Content_19 = {Text = "Ugh!!..."},
  AvgDialog_131213_Content_2 = {
    Text = "Toc, toc, toc."
  },
  AvgDialog_131213_Content_20 = {
    Text = "Il dolore Colpo senza preavviso. Non colpisce la tua carne né i tuoi organi, ma erutta dai recessi più profondi del tuo Reame dello Spirito — dal seggio stesso della tua anima."
  },
  AvgDialog_131213_Content_21 = {
    Text = "Una grande bestia si manifesta dentro di te. Si dibatte e ruggisce, la sua forma massiccia si espande rapidamente nel tuo corpo."
  },
  AvgDialog_131213_Content_22 = {
    Text = "La bestia riempie il tuo corpo intero, schiacciando ogni organo. Si espande ancora, furiosa di esplodere attraverso la tua pelle. La pressione intensa e travolgente quasi ti fa perdere i sensi..."
  },
  AvgDialog_131213_Content_23 = {
    Text = "Hah... <Big:<Shake:AAAARGH!!—>>"
  },
  AvgDialog_131213_Content_24 = {
    Text = "Tra le tue grida strazianti di agonia, tre aure tremolanti trasudano dal tuo corpo tormentato, fluttuando verso la ruota luminosa che gira."
  },
  AvgDialog_131213_Content_25 = {
    Text = "L'Autorità converge nella luce come puro combustibile versato nel fuoco. Fiamme fioche erompono, ardendo ferocemente nell'anello del fuso. Lo splendore della Lanterna si innalza, illuminando l'intera Dimensione."
  },
  AvgDialog_131213_Content_26 = {
    Text = "<Shake:Hah... Hah...>"
  },
  AvgDialog_131213_Content_27 = {
    Text = "Oh, povero, fedele piccolo credente..."
  },
  AvgDialog_131213_Content_28 = {
    Text = "Nefraea ti si avvicina, il volto colmo di preoccupazione mentre accarezza la tua guancia madida di sudore."
  },
  AvgDialog_131213_Content_29 = {
    Text = "Va tutto bene, {Male=Sig.,Female=Sig.na} Custode. Vedi? Il nostro Apostolo ha già rivelato la Sua forma..."
  },
  AvgDialog_131213_Content_3 = {
    Text = "I fili serici del Fato tirano dolcemente. Le scarpe della marionetta colpiscono il palcoscenico, producendo un suono nitido e cristallino."
  },
  AvgDialog_131213_Content_30 = {
    Text = "Sollevi il capo in agonia. La luce della ruota che gira converge, e una forma mutevole e fugace si materializza sopra il bagliore."
  },
  AvgDialog_131213_Content_31 = {
    Text = "Non hanno volto né forma. Sono il fedele Araldo del Divino, che scruta nel vuoto verso il Dio in Dormiveglia."
  },
  AvgDialog_131213_Content_32 = {
    Text = "Il loro sguardo è un invito. Sotto quegli occhi che non battono ciglio, una scalinata che conduce al luogo di riposo del Dio prende lentamente forma..."
  },
  AvgDialog_131213_Content_33 = {
    Text = "<Shake:Ha funzionato... ha funzionato!> Il Passaggio verso il Piano Superiore si sta aprendo... Il Dio sta per risvegliarsi..."
  },
  AvgDialog_131213_Content_34 = {
    Text = "Sorella, vedi? La tua tela è quasi Completa..."
  },
  AvgDialog_131213_Content_35 = {
    Text = "Nefraea osserva il Passaggio delinearsi nitidamente, sorridendo tra un fiume di lacrime nella sua estasi."
  },
  AvgDialog_131213_Content_36 = {Text = "@2...@3..."},
  AvgDialog_131213_Content_37 = {
    Text = "Il teatro trema violentemente. Il Livello crolla, e la Dimensione si scuote. Ogni cosa si rannicchia nel terrore, sottomettendosi dinanzi a questo Avvento."
  },
  AvgDialog_131213_Content_38 = {
    Text = "L'Autorità dentro di te si è ridotta quasi a nulla. Il Potere dell'Eone è stato assorbito nel corpo dell'Apostolo. Il loro fulgore è troppo feroce per essere contemplato; la loro esistenza è assolutamente innegabile."
  },
  AvgDialog_131213_Content_39 = {
    Text = "Sotto lo sguardo calmo di Arachne, nel tremore di ogni Destino, Essi discendono su questo Livello finale —"
  },
  AvgDialog_131213_Content_4 = {
    Text = "Ah, caro pubblico, il momento che stavate aspettando è finalmente giunto! Diamo il benvenuto alla nostra stella! Woooh!"
  },
  AvgDialog_131213_Content_40 = {
    Text = "Nel nome di... @2... @3 credenti..."
  },
  AvgDialog_131213_Content_41 = {
    Text = "Parla, Apostolo... cosa desideri dirmi? I tuoi Desideri? O le parole del Divino?"
  },
  AvgDialog_131213_Content_42 = {
    Text = "Quale decreto pronuncia? Desidera frantumare questi Livelli? O vuole che queste marionette diano il Benvenuto al Suo avvento?!"
  },
  AvgDialog_131213_Content_43 = {
    Text = "Dimmi, mio caro Apostolo! Che Bestia pericolosa e adorabile sei, che sai solo strappare e distruggere... dimmi cosa desideri..."
  },
  AvgDialog_131213_Content_44 = {
    Text = "Recita @2... il mio nome... risveglia @2... @3 Primordiale..."
  },
  AvgDialog_131213_Content_45 = {
    Text = "Ah, il tuo nome! Sì... lo pronuncerò ad alta voce! Porterò alle tue labbra tutto ciò che desideri divorare. Aprirò questa gabbia per te..."
  },
  AvgDialog_131213_Content_46 = {
    Text = "Il mio nome... @2..."
  },
  AvgDialog_131213_Content_47 = {
    Text = "La Voce dell'Apostolo è torbida e indistinta. Nefraea cammina verso la colonna di luce sempre più brillante, senza rivolgere un solo sguardo a te che tremi in Agonia."
  },
  AvgDialog_131213_Content_48 = {
    Text = "Il fervore la riempie di meraviglia e risa mentre si avvicina alla grande figura. Il suo respiro si spezza per l'Euforia."
  },
  AvgDialog_131213_Content_49 = {
    Text = "Accarezza la fioca luce verde — accarezza la magnifica Bestia che sta per divorare ogni cosa. Sarà il primo pasto della Bestia, e si protende in una Dolce resa."
  },
  AvgDialog_131213_Content_5 = {
    Text = "Nefraea alza la mano, e le ragnatele si disperdono come coriandoli. Ti trovi al centro del palcoscenico, la luce fioca a illuminarti il volto."
  },
  AvgDialog_131213_Content_50 = {
    Text = "Ora è il momento, Apostolo... dimmi, di' al mondo il tuo nome!"
  },
  AvgDialog_131213_Content_51 = {
    Text = "Il mio nome... @2..."
  },
  AvgDialog_131213_Content_52 = {
    Text = "Il mio nome è... <Red:%player%>..."
  },
  AvgDialog_131213_Content_53 = {
    Text = "Il mio nome è... <Yellow:%player%>!"
  },
  AvgDialog_131213_Content_54 = {Text = "!!!"},
  AvgDialog_131213_Content_55 = {
    Text = "Il tempo si congela. Negli occhi di Nefraea, i Fili del Destino si liquefanno e si frantumano. La rovina del destino vortica come un vortice violento in un vasto oceano, trascinandola negli abissi per divorarla intera."
  },
  AvgDialog_131213_Content_56 = {
    Text = "<Shake:Cosa... cosa sta succedendo?!!>"
  },
  AvgDialog_131213_Content_57 = {
    Text = "Il vortice si placa. L'oceano si ritira. Le gocce si coalizzano in seta ancora una volta, eppure la trama che tessono assume una forma che Nefraea non aveva mai immaginato."
  },
  AvgDialog_131213_Content_58 = {
    Text = "Non capisci, Nefraea? Prostrati in reverenza. L'Apostolo per cui hai pregato è davanti a te, ora."
  },
  AvgDialog_131213_Content_59 = {
    Text = "Ti ergi sopra Nefraea, fissando il Passaggio che conduce al Tempio del Tohuwabohu. Sorridi a quella sagoma suprema."
  },
  AvgDialog_131213_Content_6 = {
    Text = "Orsù, {Male=Sig.,Female=Sig.na} Custode. Il nostro atto finale ha inizio..."
  },
  AvgDialog_131213_Content_60 = {
    Text = "L'Autorità dei Tre Eoni scorre nelle tue vene, ma non ti porta più Pain. Lo splendore del fuso — la volontà assoluta nella luce — si riversa in te come una marea crescente, fondendosi con il tuo Potere."
  },
  AvgDialog_131213_Content_61 = {
    Text = "Senti l'Ombra dell'Apostolo sovrapporsi alla tua. Ti senti immenso. Sconfinato. Libero. Senti... la suprema, assoluta Estasi."
  },
  AvgDialog_131213_Content_62 = {
    Text = "Tu... hai rubato il destino dell'Apostolo?!"
  },
  AvgDialog_131213_Content_63 = {
    Text = "Heh... hahaha! Atto Terzo: l'Avvento, eh?... Ha, è un bel titolo. Ma questa non è la tua Storia, mia cara Nefraea."
  },
  AvgDialog_131213_Content_64 = {
    Text = "Sono io a scrivere questo atto. E lo chiamo... <Big:<color=#98918C>Estasi</color>>!"
  },
  AvgDialog_131213_Content_65 = {
    Text = "<Shake:Voi... tutti voi...>"
  },
  AvgDialog_131213_Content_66 = {
    Text = "No, è impossibile... posso vedere il tuo destino... non può essere..."
  },
  AvgDialog_131213_Content_67 = {
    Text = "<color=#EE4D0C><Italic:\"Oh, mio caro Duca, perché quella faccia lunga? Lascia che il tuo giullare restituisca quel prezioso sorriso!\"></color>"
  },
  AvgDialog_131213_Content_68 = {
    Text = "<color=#BF0909><Italic:\"Guardatelo: il destino crudele, la maledizione malvagia... che spettacolo ridicolo! Che dolce, deliziosa menzogna!\"></color>"
  },
  AvgDialog_131213_Content_69 = {
    Text = "<color=#FC1818><Italic:\"Ecco come finisce la storia del cattivo... l'unica ricompensa per la malvagità è l'Estasi!\"></color>"
  },
  AvgDialog_131213_Content_7 = {
    Text = "Chiamo questo momento — \"L'Avvento!\""
  },
  AvgDialog_131213_Content_70 = {
    Text = "Un applauso fragoroso esplode dai posti vuoti. Luci brillanti inondano il Livello in rovina. Tu sei il perno del mondo, il padrone della Singolarità.\nApri le braccia. Dichiari che il Destino si inchinerà a te. Dichiari questa esibizione un capolavoro."
  },
  AvgDialog_131213_Content_71 = {
    Text = "Inganno. Manipolazione. Puro godimento... <Shake:Hehe... <Big:HAHAHAHA!>> Che spettacolo delizioso, piccolo ragno."
  },
  AvgDialog_131213_Content_72 = {
    Text = "<Shake:Tu... non puoi avere il Potere di alterare il Fato...>"
  },
  AvgDialog_131213_Content_73 = {
    Text = "Aww.. No, no, no. Simili sforzi sono per gente come te. Un devoto dell'Estasi non si abbasserebbe mai a tanta fatica."
  },
  AvgDialog_131213_Content_74 = {
    Text = "<Shake:Ho visto la fine... Dovevi cedere la tua Autorità! <Big:Dovevi guardare il Passaggio aprirsi e morire su questo Livello! PERCHÉ?!>>"
  },
  AvgDialog_131213_Content_75 = {
    Text = "Coloro che manipolano il Fato sanno tutto — tranne di coloro che dimorano nell'Estasi. Perché, mia cara... chi vive nell'Estasi non segue alcun fato..."
  },
  AvgDialog_131213_Content_76 = {
    Text = "Ti chini, assaporando lo sguardo tremante di Nefraea. L'Agonia e la disperazione nei suoi occhi nutrono ogni fibra del tuo essere."
  },
  AvgDialog_131213_Content_77 = {
    Text = "Le nostre intere vite sono spese nella ricerca del piacere. Senza di esso, non siamo nulla. E coloro che lo trovano... sono oltre la Portata del destino."
  },
  AvgDialog_131213_Content_78 = {
    Text = "Ciò che vedi è un gioco di prestigio. Un piccolo scherzo giocato al mio io passato e al Fato dal nuovo me, quello Benedetto dalla volontà e dal Potere di un Dio."
  },
  AvgDialog_131213_Content_79 = {
    Text = "Perché controllare il Fato quando puoi farlo sembrare uno sciocco? Non è così, Emissario del Fato?"
  },
  AvgDialog_131213_Content_8 = {
    Text = "L'Avvento. Sul sipario dietro il palcoscenico, ragnatele viscide come melma tessono le enormi, orribili parole. Nefraea inspira profondamente e spalanca le braccia."
  },
  AvgDialog_131213_Content_80 = {
    Text = "Cerchi di mantenere un tono serio, ma non riesci a sopprimere la tua risata maniacale."
  },
  AvgDialog_131213_Content_81 = {
    Text = "Sei il Custode? Sei \"N\"? Non lo sai, e non ti importa. L'essenza dell'Estasi inonda la volontà dell'Apostolo, riempiendo ogni cellula del tuo corpo."
  },
  AvgDialog_131213_Content_82 = {
    Text = "Vuoi urlare dalle risate. Vuoi esultare. Vuoi sottoporre questa manipolatrice fallita alla più tenera, devastante umiliazione."
  },
  AvgDialog_131213_Content_83 = {
    Text = "Hai trovato la chiave. Ti volti e offri un elegante inchino all'artefice di questo piano."
  },
  AvgDialog_131213_Content_84 = {
    Text = "Arachne, magnifica drammaturga! Hai tessuto questo Livello per me dal momento in cui ho messo piede in questo mondo!"
  },
  AvgDialog_131213_Content_85 = {
    Text = "Mi hai mostrato come si muovono i fili, mi hai insegnato il fascino della menzogna e mi hai sussurrato il Segreto dell'\"Estasi.\""
  },
  AvgDialog_131213_Content_86 = {
    Text = "Ora, la serratura è aperta. Ebbene? Sei soddisfatta del tuo attore protagonista?"
  },
  AvgDialog_131213_Content_87 = {
    Text = "Io ho solo allestito il Livello. Sei tu quello che scrive il copione."
  },
  AvgDialog_131213_Content_88 = {
    Text = "Le sorridi. Sei un Apostolo del Divino. Sei uno Schiavo dell'Estasi. Sei l'indiscusso, unico padrone di questo mondo. Alzi la Mano e la abbassi dolcemente, come un direttore d'orchestra."
  },
  AvgDialog_131213_Content_89 = {
    Text = "Come segno della mia gratitudine... indossa il tuo costume, Arachne. Il tuo ingresso è imminente!"
  },
  AvgDialog_131213_Content_9 = {
    Text = "Apostolo della Divinità Suprema, Messaggero del Dio Cieco Idiota. Il tuo fulgore illumina la Prigione Eterna. Ho udito la tua Voce invocare il Caos!"
  },
  AvgDialog_131213_Content_90 = {
    Text = "Pizzichi i Fili un tempo invisibili come se spostassi blocchi in un asilo."
  },
  AvgDialog_131213_Content_91 = {
    Text = "Mentre la trama si rimodella, le Braci Dimensionali rubate tornano volando da lei."
  },
  AvgDialog_131213_Content_92 = {
    Text = "Sabbia viola infinita vortica attorno ad Arachne. Nella tua nuova realtà, quelle braci non sono mai state rubate."
  },
  AvgDialog_131213_Content_93 = {
    Text = "<color=#8C7E96>Passato e futuro, appartengono a lei sola.</color>"
  },
  AvgDialog_131213_Content_94 = {
    Text = "Arachne annuisce con un sorriso, attirando le ceneri nel suo corpo. La sua ruota non si ferma mai. Il suo sorriso non cambia mai."
  },
  AvgDialog_131213_Content_95 = {
    Text = "Scuoti la testa sul palcoscenico e lasci sfuggire un sospiro esagerato e teatrale."
  },
  AvgDialog_131213_Content_96 = {
    Text = "Spenta e priva di passione... avresti potuto essere così interessante, Arachne."
  },
  AvgDialog_131213_Content_97 = {
    Text = "Sei schiava del destino, proprio come Tawil. Non conoscerai mai questa gioia."
  },
  AvgDialog_131213_Content_98 = {
    Text = "Guarda il tuo volto privo di vita, Arachne. Provo davvero pietà per entrambi."
  },
  AvgDialog_131213_Content_99 = {
    Text = "Ognuno fa la propria scelta, %player%... o dovrei chiamarti Apostolo? O forse... \"N\"?"
  },
  AvgDialog_131214_Content_1 = {
    Text = "<Shake:AAAAARGH!!>"
  },
  AvgDialog_131214_Content_10 = {
    Text = "Perché... la nostra vendetta non è finita. Non sarà mai finita..."
  },
  AvgDialog_131214_Content_11 = {
    Text = "Indietreggi d'istinto, ma nessun pericolo emana da Nefraea."
  },
  AvgDialog_131214_Content_12 = {
    Text = "Con un solo colpo d'Artiglio squarcia il sipario al suo fianco, rivelando la scena celata Dietro il Velo."
  },
  AvgDialog_131214_Content_13 = {
    Text = "Questo è...!"
  },
  AvgDialog_131214_Content_14 = {
    Text = "Fili cremisi collegano i numerosi Livelli, la grande città e gli innumerevoli burattini al suo interno. Tutti convergono nel Corpo ferito di Nefraea."
  },
  AvgDialog_131214_Content_15 = {
    Text = "Tu... non hai legato i fili all'arcolaio?"
  },
  AvgDialog_131214_Content_16 = {
    Text = "Ha visto la propria sconfitta. Mentre aveva ancora Potere, ha legato questi fati a sé stessa, proprio come..."
  },
  AvgDialog_131214_Content_17 = {
    Text = "Proprio come la prima volta che mi hai ucciso."
  },
  AvgDialog_131214_Content_18 = {
    Text = "Nefraea sorride, pizzicando un filo nascosto davanti a sé."
  },
  AvgDialog_131214_Content_19 = {
    Text = "Quel filo cremisi si estende dalla nuca, intrecciandosi nell'aria fino a confluire nel Corpo di Arachne."
  },
  AvgDialog_131214_Content_2 = {Text = "Boom—"},
  AvgDialog_131214_Content_20 = {
    Text = "È passato così tanto tempo dall'ultima volta che eravamo così vicine, sorella. Solo ora ho trovato l'occasione di restituirti questo filo."
  },
  AvgDialog_131214_Content_21 = {
    Text = "Ritorno...?"
  },
  AvgDialog_131214_Content_22 = {
    Text = "Questo filo... è quello che ho reciso quando ho distrutto la mia prima creazione."
  },
  AvgDialog_131214_Content_23 = {
    Text = "La tua Passione, la tua Gentilezza, le tue Memorie... tutto ciò che un tempo era mio è di nuovo tuo."
  },
  AvgDialog_131214_Content_24 = {
    Text = "Sei completa, Arachne."
  },
  AvgDialog_131214_Content_25 = {
    Text = "Le labbra di Nefraea si incurvano in un ghigno, come una bambina nascosta dietro una tenda che osserva un adulto cadere in uno scherzo."
  },
  AvgDialog_131214_Content_26 = {
    Text = "È questo che volevi fare... quando avevi quel potere?"
  },
  AvgDialog_131214_Content_27 = {
    Text = "Ti piace? Un'idea brillante, non è vero?"
  },
  AvgDialog_131214_Content_28 = {
    Text = "Avanti, allora, uccidimi! Distruggi i fati che un tempo hai abbandonato! Distruggi la città in cui ti sei rifugiata, distruggi il teatro che ti è così caro, e distruggi ogni singola anima qui presente!"
  },
  AvgDialog_131214_Content_29 = {
    Text = "Vieni, Arachne! Con tutta la tua debolezza, <Shake:uccidi ancora una volta tutto ciò che ami!!!>"
  },
  AvgDialog_131214_Content_3 = {
    Text = "Urla strazianti e il fragore del crollo echeggiano tra le rovine. I fili cremisi si spezzano. L'arcolaio che ha accompagnato Nefraea per tutta la vita rotola a terra."
  },
  AvgDialog_131214_Content_30 = {
    Text = "Le urla frenetiche e le risate di Nefraea riecheggiano senza fine nel teatro in frantumi."
  },
  AvgDialog_131214_Content_31 = {
    Text = "Il corpo di Arachne sembra farsi impossibilmente pesante. Lentamente volge il capo, scrutando ogni cosa connessa a Nefraea."
  },
  AvgDialog_131214_Content_32 = {
    Text = "Attraverso le crepe nel teatro, scorge la città brulicante, gremita di automobili e Folla. Scorge volti familiari e nomi familiari in ogni angolo."
  },
  AvgDialog_131214_Content_33 = {
    Text = "Vede il palcoscenico su cui un tempo siete salite insieme. La guerra brutale è Terminato, e quel mondo sta per accogliere due secoli di magnifica pace."
  },
  AvgDialog_131214_Content_34 = {
    Text = "Nel fango nero, vede il volto di sua Madre. Vede suo padre seduto sotto le betulle nel cortile, che le fa cenno di avvicinarsi."
  },
  AvgDialog_131214_Content_35 = {
    Text = "Il Signor Lawrence è accanto a loro, mentre lucida le posate forgiate appositamente per lei."
  },
  AvgDialog_131214_Content_36 = {
    Text = "La chiami vendetta perché non hai mai visto il Fato con chiarezza, Nefraea. E non hai mai visto me."
  },
  AvgDialog_131214_Content_37 = {
    Text = "Un filo ricoperto di melma collega Arachne al palcoscenico in frantumi sotto i piedi di Nefraea. Trascinando la sua pesante figura, Arachne sale sul Fragile filamento."
  },
  AvgDialog_131214_Content_38 = {
    Text = "Il filo trema come se potesse spezzarsi e precipitare la Prigioniera del Fato nell'abisso."
  },
  AvgDialog_131214_Content_39 = {
    Text = "Arachne fissa con calma gli occhi attoniti di Nefraea. I suoi passi non vacillano mai."
  },
  AvgDialog_131214_Content_4 = {
    Text = "Si aggrappa all'arcolaio come un'Infante che affoga. Il fuso oscurato si dissolve tra le sue mani, trasformandosi in braci dimensionali che confluiscono nelle sabbie mutevoli accanto ad Arachne."
  },
  AvgDialog_131214_Content_40 = {
    Text = "Il momento fatidico è giunto..."
  },
  AvgDialog_131214_Content_41 = {
    Text = "In piedi sulla sua tela, Arachne solleva il fuso. Il mondo intero si ferma. L'universo connesso a questo teatro trattiene il respiro, in attesa del suo decreto."
  },
  AvgDialog_131214_Content_42 = {
    Text = "Nel nome del Fato, con la presente dichiaro—"
  },
  AvgDialog_131214_Content_43 = {
    Text = "Tutti i destini erronei saranno sepolti nella polvere del tempo. Il destino del mondo tornerà al suo corso prestabilito."
  },
  AvgDialog_131214_Content_44 = {
    Text = "Il fato sbagliato finisce qui. Gli abbandonati troveranno pace..."
  },
  AvgDialog_131214_Content_45 = {
    Text = "Il fuso si inclina. Innumerevoli fili tremano."
  },
  AvgDialog_131214_Content_46 = {
    Text = "I fili si spezzano. Il palcoscenico in attesa di pace si sgretola nel nulla."
  },
  AvgDialog_131214_Content_47 = {
    Text = "I fili si spezzano. Attraverso le crepe del teatro, la città svanisce."
  },
  AvgDialog_131214_Content_48 = {
    Text = "I fili si spezzano, e si spezzano, e si spezzano..."
  },
  AvgDialog_131214_Content_49 = {
    Text = "Fai fatica a vedere i fili, ma odi chiaramente il grido del Fato."
  },
  AvgDialog_131214_Content_5 = {
    Text = "Nefraea fissa con sguardo vuoto la sua Speranza che svanisce, poi scoppia improvvisamente in una risatina sommessa."
  },
  AvgDialog_131214_Content_50 = {
    Text = "Innumerevoli vite, gioie e dolori si frantumano e si dissolvono al tuo orecchio, solo per essere ricostruiti e annientati."
  },
  AvgDialog_131214_Content_51 = {Text = "...Luci?"},
  AvgDialog_131214_Content_52 = {
    Text = "Luci di scena si accendono da una fonte ignota. La luce trafigge il teatro in frantumi. Gli abbandonati in agguato nelle ombre svaniscono nell'istante in cui la luce li colpisce — come se non fossero mai esistiti."
  },
  AvgDialog_131214_Content_53 = {
    Text = "Arachne... sorella... tu..."
  },
  AvgDialog_131214_Content_54 = {
    Text = "Arachne attraversa il fragile filo e si ferma davanti a lei. Nefraea alza lo sguardo verso di lei come se contemplasse il volto inflessibile del Fato stesso."
  },
  AvgDialog_131214_Content_55 = {
    Text = "Avvicinati, Nefraea."
  },
  AvgDialog_131214_Content_56 = {
    Text = "Arachne prende la mano di Nefraea e la preme contro la propria guancia."
  },
  AvgDialog_131214_Content_57 = {
    Text = "Nel momento in cui tocca Arachne, un cancello segreto si apre. Nefraea attraversa strati di gabbie, trovandosi davvero di fronte ad Arachne per la prima volta."
  },
  AvgDialog_131214_Content_58 = {
    Text = "In quella gabbia, vede tre volti familiari."
  },
  AvgDialog_131214_Content_59 = {
    Text = "Arachne!!! Tu..."
  },
  AvgDialog_131214_Content_6 = {
    Text = "La sua risata si fa più forte, benché abbia a malapena la forza di restare seduta. Il Sangue gocciola dal suo corpo tremante, macchiando i Frammenti oscuri dell'arcolaio."
  },
  AvgDialog_131214_Content_60 = {
    Text = "<Shake:Romanticismo, Gentilezza, Ricordi... loro... loro...>"
  },
  AvgDialog_131214_Content_61 = {
    Text = "Non sono mai riuscita a lasciarli andare del tutto. Non sono mai riuscita a lasciar andare davvero <Italic:te>."
  },
  AvgDialog_131214_Content_62 = {
    Text = "Ma avevi detto che non riuscivi a sopportare il dolore..."
  },
  AvgDialog_131214_Content_63 = {
    Text = "Distruggere scioccamente e dolorosamente tutto ciò che mi è caro... non puoi usarlo per vendicarti di me, Nefraea."
  },
  AvgDialog_131214_Content_64 = {
    Text = "Perché quella è la punizione che il Fato ha decretato per me molto tempo fa."
  },
  AvgDialog_131214_Content_65 = {
    Text = "Arachne sorride con calma. La sua ruota gira, incessantemente per l'eternità."
  },
  AvgDialog_131214_Content_66 = {
    Text = "È finita, Nefraea."
  },
  AvgDialog_131214_Content_67 = {
    Text = "Un singolo filo vibra. Nefraea ode il grido di un airone, proprio come il giorno in cui suo padre le portò il fuso chiamato Moirae."
  },
  AvgDialog_131214_Content_68 = {
    Text = "Questa è la sua stanza. Le betulle fuori dalla finestra sono le sue fedeli compagne—eterne, solitarie prigioniere."
  },
  AvgDialog_131214_Content_69 = {
    Text = "Sono imprigionate dal Fato, e qui dipendono l'una dall'altra per sopravvivere."
  },
  AvgDialog_131214_Content_7 = {
    Text = "La fine... la fine davvero non può essere cambiata. Questo è il Fato..."
  },
  AvgDialog_131214_Content_70 = {Text = "Scricch—"},
  AvgDialog_131214_Content_71 = {
    Text = "La semplice porta di legno si spalanca. Arachne le si avvicina e si china, accarezzandole dolcemente il viso."
  },
  AvgDialog_131214_Content_72 = {
    Text = "Sorella... ho perso... abbiamo perso..."
  },
  AvgDialog_131214_Content_73 = {
    Text = "Non abbiamo mai avuto il diritto di vincere."
  },
  AvgDialog_131214_Content_74 = {
    Text = "Ricordi il desiderio che esprimemmo il giorno in cui ricevemmo la ruota?"
  },
  AvgDialog_131214_Content_75 = {
    Text = "\"Non sprecherò i doni del Fato... porterò un destino meraviglioso a questo mondo...\""
  },
  AvgDialog_131214_Content_76 = {
    Text = "Che desiderio ingenuo, Arachne... non avevamo idea di cosa significasse."
  },
  AvgDialog_131214_Content_77 = {
    Text = "Arachne allunga una mano tremante, toccando il volto del suo sé lontano."
  },
  AvgDialog_131214_Content_78 = {
    Text = "Il Fato... chi può davvero vederlo?"
  },
  AvgDialog_131214_Content_79 = {
    Text = "Anche se avessi potuto prevedere tutto questo, la mia scelta non sarebbe cambiata."
  },
  AvgDialog_131214_Content_8 = {
    Text = "Avevi previsto questa tragica vittoria, non è vero, Arachne?"
  },
  AvgDialog_131214_Content_80 = {
    Text = "<Shake:Perché, Arachne?> Avresti potuto andartene. Avresti potuto arrenderti. Avresti potuto..."
  },
  AvgDialog_131214_Content_81 = {
    Text = "Avresti potuto avere la libertà eterna dopo aver lasciato l'Abisso. Sapevi che avresti fallito, eppure sei venuta qui lo stesso per cercare di portare la liberazione a me e a coloro che ti hanno seguita."
  },
  AvgDialog_131214_Content_82 = {
    Text = "Ogni manipolatore del Fato diventa suo prigioniero. Non siamo diverse, Nefraea."
  },
  AvgDialog_131214_Content_83 = {
    Text = "Nefraea siede in silenzio, osservando con tristezza la betulla fuori dalla finestra. La guarda germogliare, crescere e appassire in un istante."
  },
  AvgDialog_131214_Content_84 = {
    Text = "Lascia sfuggire un lieve sospiro e asciuga le lacrime che scorrono sul volto di Arachne. Sorride."
  },
  AvgDialog_131214_Content_85 = {
    Text = "Come sono felice di rivederti... sorellina."
  },
  AvgDialog_131214_Content_86 = {
    Text = "Una singola lacrima cade sul volto identico a quello di Arachne."
  },
  AvgDialog_131214_Content_87 = {
    Text = "Perdonami per il mio egoismo..."
  },
  AvgDialog_131214_Content_88 = {
    Text = "Tu... ora sei libera, <Red:\"Arachne.\">"
  },
  AvgDialog_131214_Content_89 = {
    Text = "Scricchiolio."
  },
  AvgDialog_131214_Content_9 = {
    Text = "Tu stessa ne hai colto un breve scorcio poco fa. Se sai come finisce, perché continui ad aggrapparti?"
  },
  AvgDialog_131214_Content_90 = {
    Text = "Quando l'ultimo filo si spezza, un fragoroso applauso esplode."
  },
  AvgDialog_131214_Content_91 = {
    Text = "I posti in basso, un tempo eternamente vuoti, sono ora gremiti fino all'ultimo. I Fati Abbandonati e le Marionette cadute per mano tua occupano ogni logora poltrona di velluto."
  },
  AvgDialog_131214_Content_92 = {
    Text = "Gli attori prendono posto tra il pubblico, osservando in silenzio il finale che si compie su questo palcoscenico in rovina."
  },
  AvgDialog_131214_Content_93 = {
    Text = "Restano inespressivi e muti, eppure applaudono con fervore febbrile. L'ovazione è assordante... ed eterna."
  },
  AvgDialog_131215_Content_1 = {
    Text = "L'Attore Interiore"
  },
  AvgDialog_131215_Content_10 = {
    Text = "Non capivo perché Arachne avesse rimosso sua sorella dalla Tela, né perché avessi bisogno del potere di quei tre Burattini."
  },
  AvgDialog_131215_Content_100 = {Text = "..."},
  AvgDialog_131215_Content_101 = {
    Text = "Un destino tanto tenace quanto futile... uno spettacolo disperato, di una bellezza che perseguita l'anima."
  },
  AvgDialog_131215_Content_102 = {
    Text = "Perché credi che lo faccia?"
  },
  AvgDialog_131215_Content_103 = {
    Text = "Nefraea fissa intensamente il palcoscenico spoglio, la voce ridotta a un mero sussurro."
  },
  AvgDialog_131215_Content_104 = {
    Text = "È tutto un sogno, Dea del Fato... Avresti potuto scegliere il fato più felice per tutti. Avresti potuto ricucire le tue fantasie infantili e soddisfare ogni desiderio."
  },
  AvgDialog_131215_Content_105 = {
    Text = "Ma non l'hai mai nemmeno preso in considerazione. Nel creare la perfezione, hai creato anche la sofferenza. Ancora e ancora, hai lasciato che l'agonia calasse su questo mondo."
  },
  AvgDialog_131215_Content_106 = {
    Text = "Hai riversato la tua stessa anima nel tessere quella Grande Tela, eppure entrambe abbiamo visto ciò che si cela oltre il portale. Conosciamo la destinazione."
  },
  AvgDialog_131215_Content_107 = {
    Text = "L'istante in cui la Tela del Fato sarà completa è l'istante in cui la Divinità Suprema si risveglierà del tutto."
  },
  AvgDialog_131215_Content_108 = {Text = "Cosa...?!"},
  AvgDialog_131215_Content_109 = {
    Text = "Guardi Arachne, cercando una smentita sul suo volto."
  },
  AvgDialog_131215_Content_11 = {
    Text = "Almeno posso ringraziarti per aver chiarito il mistero."
  },
  AvgDialog_131215_Content_110 = {
    Text = "Trovi soltanto la sua consueta, eterna calma. Sul palcoscenico del Fato, la serenità è una maschera che non può rimuovere."
  },
  AvgDialog_131215_Content_111 = {
    Text = "Sorella, non puoi smettere di tessere, perché non riesci a sopportare di guardare l'universo sprofondare nel caos. Ma il giorno in cui la tua tela sarà completata, sarai tu stessa a seppellire con le tue mani tutto ciò che ami."
  },
  AvgDialog_131215_Content_112 = {
    Text = "Che ironia, Arachne. Perché? Perché non lasciare che l'universo abbracci la propria fine nella pura beatitudine?"
  },
  AvgDialog_131215_Content_113 = {
    Text = "Tutto ciò che è Fato è scritto nella Costante; tutto ciò che è Fato è soggetto alla Variabile. Queste massime contraddittorie sono l'essenza del destino."
  },
  AvgDialog_131215_Content_114 = {
    Text = "Arachne guarda negli occhi Nefraea, rispondendo alla domanda che si è posta mille volte."
  },
  AvgDialog_131215_Content_115 = {
    Text = "Nefraea, nelle infinite dimensioni, vi sono ancora innumerevoli anime che lottano per quell'unica Variabile di speranza."
  },
  AvgDialog_131215_Content_116 = {
    Text = "Mantenere il palcoscenico in funzione, attendere che la Variabile si manifesti... questi sono i ceppi che il Fato mi ha imposto. È un dovere a cui non posso sfuggire."
  },
  AvgDialog_131215_Content_117 = {
    Text = "Dovere, pericolo... parli sempre di cose grandiose, ma mai di te stessa, Arachne. Povera, tragica sorella mia. Non importa... Il tuo doloroso dovere sta finalmente giungendo al termine."
  },
  AvgDialog_131215_Content_118 = {
    Text = "Nefraea accarezza teneramente la guancia di Arachne e le rivolge un dolce sorriso."
  },
  AvgDialog_131215_Content_119 = {
    Text = "Nell'Abisso, ho immaginato il nostro ricongiungimento migliaia di volte. Mi chiedevo quale dono potesse essere degno di un momento simile."
  },
  AvgDialog_131215_Content_12 = {
    Text = "Perché non mi hai detto nulla di tutto questo prima?"
  },
  AvgDialog_131215_Content_120 = {
    Text = "Ci ho pensato a lungo, così a lungo... e poi mi è venuto in mente. Questo è il miglior dono che possa farti, cara sorella!"
  },
  AvgDialog_131215_Content_121 = {
    Text = "Ti dono... <Red:Liberazione.>"
  },
  AvgDialog_131215_Content_122 = {
    Text = "Mentre Nefraea pronuncia quelle parole gentili, una melma nera come inchiostro si raccoglie nelle fenditure dimensionali. Al termine del sentiero di seta, un palcoscenico magnifico si rivela."
  },
  AvgDialog_131215_Content_13 = {
    Text = "Guardi l'Arachne accanto a te, che ancora guida ogni tuo passo."
  },
  AvgDialog_131215_Content_14 = {
    Text = "Una pietra che non increspa il lago del Fato non serve ad altro che a turbarne la pace."
  },
  AvgDialog_131215_Content_15 = {
    Text = "Lei e io siamo diventate due persone separate molto tempo fa, {Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_131215_Content_16 = {
    Text = "Avevi previsto questo giorno?"
  },
  AvgDialog_131215_Content_17 = {
    Text = "Nessun prigioniero vede il proprio fato finché il verdetto non viene pronunciato."
  },
  AvgDialog_131215_Content_18 = {
    Text = "Se avessi saputo che quei fati scartati sarebbero stati esiliati nella Prigione Abissale anziché svanire... l'avresti fatto comunque, Arachne?"
  },
  AvgDialog_131215_Content_19 = {Text = "..."},
  AvgDialog_131215_Content_2 = {
    Text = "La la la la..."
  },
  AvgDialog_131215_Content_20 = {
    Text = "Silenzio. Il silenzio è l'eterna maledizione del drammaturgo. Il silenzio è l'impotente autodifesa del prigioniero. In un silenzio simile a una condanna a morte, la risata frenetica di Nefraea risuonò."
  },
  AvgDialog_131215_Content_21 = {
    Text = "Oh, l'avresti fatto di certo, sorella. Il Fato è la tua dottrina; nessuna condizione può mutarne la risposta finale."
  },
  AvgDialog_131215_Content_22 = {
    Text = "Tu, la Dea del Fato. Così insignificante, così fragile, così crudele..."
  },
  AvgDialog_131215_Content_23 = {
    Text = "Ma non importa. Qualunque cosa tu abbia fatto, ti ho sempre tenuta nei miei pensieri durante tutti quegli anni, cara sorella."
  },
  AvgDialog_131215_Content_24 = {
    Text = "Romanticismo, Gentilezza, Memorie. Questi splendidi ingredienti hanno fermentato, distillando il sorriso di Nefraea in un dolce veleno."
  },
  AvgDialog_131215_Content_25 = {
    Text = "Mentre sorride raggiante, le luci lungo il sentiero di seta illuminano il palcoscenico."
  },
  AvgDialog_131215_Content_26 = {
    Text = "Sorella, {Male=Sig.,Female=Sig.na} Custode... questi nuovi spettacoli sono un dono da parte mia, la nuova padrona del teatro."
  },
  AvgDialog_131215_Content_27 = {
    Text = "Prima del grande terzo atto, godetevi questo preludio... e ricordate le regole del teatro. Non si parla!"
  },
  AvgDialog_131215_Content_28 = {
    Text = "Nefraea spalanca le braccia come un'annunciatrice. Innumerevoli palcoscenici si illuminano uno dopo l'altro al vostro passaggio."
  },
  AvgDialog_131215_Content_29 = {Text = "..."},
  AvgDialog_131215_Content_3 = {
    Text = "Danzano. Cantano. Scricchiolio, scricchiolio!"
  },
  AvgDialog_131215_Content_30 = {
    Text = "Grande Dea del Fato, tre recipienti-marionetta sono pronti per voi."
  },
  AvgDialog_131215_Content_31 = {
    Text = "Che bambole squisite... Coloro che ho perduto troveranno nuova vita in esse..."
  },
  AvgDialog_131215_Content_32 = {
    Text = "La marionetta \"Arachne\" abbandona il suo telaio e si avvicina alle bambole."
  },
  AvgDialog_131215_Content_33 = {
    Text = "Al primo, conferisco il nome \"Romanzo.\""
  },
  AvgDialog_131215_Content_34 = {
    Text = "Voi siete il movimento più appassionato della sinfonia: un concentrato di emozione pura, il frutto maturo di una primavera in fiore."
  },
  AvgDialog_131215_Content_35 = {
    Text = "Andrete nel paradise di mezzanotte, portando vino, incontri fortuiti e un fuoco inestinguibile a questa città."
  },
  AvgDialog_131215_Content_36 = {
    Text = "Vi ringrazio, grande Dea Arachne. Come comandate, vino e miele sgorgheranno dalle mie labbra."
  },
  AvgDialog_131215_Content_37 = {
    Text = "La bella donna si inchina con grazia alla marionetta Arachne."
  },
  AvgDialog_131215_Content_38 = {
    Text = "Al secondo, conferisco il nome \"Gentilezza.\""
  },
  AvgDialog_131215_Content_39 = {
    Text = "Voi siete l'anziano che mi ha cresciuta — una piuma bianca perduta da un angelo, il raggio di sole più sacro."
  },
  AvgDialog_131215_Content_4 = {
    Text = "Antichi racconti e passi gioiosi vibrano attraverso la tela. Nefraea congiunge le mani dietro la schiena, saltellando in avanti."
  },
  AvgDialog_131215_Content_40 = {
    Text = "Camminerete per le strade della città, riscaldando chiunque incontriate con la vostra benevolenza."
  },
  AvgDialog_131215_Content_41 = {
    Text = "Vi ringrazio, grande Dea Arachne! Mi avete donato la vita; non potrò mai ripagare un simile debito."
  },
  AvgDialog_131215_Content_42 = {
    Text = "Non possiedo nulla, eppure amo profondamente questo mondo. Proteggerò i deboli e soccorrerò i sofferenti."
  },
  AvgDialog_131215_Content_43 = {
    Text = "Tutto ciò che possiedo appartiene a chi soffre."
  },
  AvgDialog_131215_Content_44 = {
    Text = "Il gentile anziano offre un profondo, rispettoso inchino."
  },
  AvgDialog_131215_Content_45 = {
    Text = "E a te, la terza... conferisco il nome \"Memorie.\""
  },
  AvgDialog_131215_Content_46 = {
    Text = "La marionetta \"Arachne\" si ferma dinanzi alla piccola bambola. Si accovaccia, fissandone gli occhi vacui."
  },
  AvgDialog_131215_Content_47 = {
    Text = "Tu sei l'orfana del Fato — una foglia avvizzita sepolta sotto la neve profonda."
  },
  AvgDialog_131215_Content_48 = {
    Text = "Cammini sola nel silenzio, inespressa e sconosciuta al mondo."
  },
  AvgDialog_131215_Content_49 = {
    Text = "Nella tua lunga, quieta vita, sarai l'unica custode di quelle memorie."
  },
  AvgDialog_131215_Content_5 = {
    Text = "Segui Arachne irresistibilmente, camminando lungo il sentiero di seta verso la sua fine."
  },
  AvgDialog_131215_Content_50 = {
    Text = "La ragazza silenziosa alza lo sguardo, la mano che sfiora la guancia della marionetta \"Arachne.\""
  },
  AvgDialog_131215_Content_51 = {
    Text = "\"Arachne\" si alza, contemplando le sue creazioni con tenerezza."
  },
  AvgDialog_131215_Content_52 = {
    Text = "Andate, fanciulli miei. Veglierò su di voi dal telaio del Fato, per sempre."
  },
  AvgDialog_131215_Content_53 = {
    Text = "Coloro che l'eternità ha abbandonato fioriranno, uno a uno, nei vostri destini."
  },
  AvgDialog_131215_Content_54 = {Text = "..."},
  AvgDialog_131215_Content_55 = {
    Text = "Il livello si oscura. A ogni passo che muovi, le luci dell'atto successivo si accendono."
  },
  AvgDialog_131215_Content_56 = {
    Text = "La luce del sole non raggiunse mai questo luogo. Nessun vento, nessun fiore, nessuna nuvola... in tre lunghi secoli, persino il calendario cessò di esistere."
  },
  AvgDialog_131215_Content_57 = {
    Text = "Mia signora, un altro dei Reietti è arrivato."
  },
  AvgDialog_131215_Content_58 = {
    Text = "L'oboe suona una fioritura. I laceri Reietti appaiono."
  },
  AvgDialog_131215_Content_59 = {
    Text = "La marionetta \"Nefraea\" si alza e cammina verso il centro del palcoscenico."
  },
  AvgDialog_131215_Content_6 = {
    Text = "Allora, {Male=Sig.,Female=Sig.na} Custode? Lo spettacolo è stato grandioso? Soprattutto con quello sguardo dietro le quinte?"
  },
  AvgDialog_131215_Content_60 = {
    Text = "Ditemi, poveri fanciulli... chi siete, e da dove venite?"
  },
  AvgDialog_131215_Content_61 = {
    Text = "Dea del Fato, perdona la mia insolenza... ma la rabbia mi costringe a porvi una domanda."
  },
  AvgDialog_131215_Content_62 = {
    Text = "Ho sopportato mille avversità per lasciare in eredità un'epopea scritta nel sangue e nel coraggio — un lascito destinato a navigare con la mia terra dei bianchi uccelli fino ai confini dell'universo."
  },
  AvgDialog_131215_Content_63 = {
    Text = "Perché, grande dea… perché ci hai bandito in questa terra selvaggia? <Shake:Perché hai ridotto in polvere quelle melodie immortali!>"
  },
  AvgDialog_131215_Content_64 = {
    Text = "I miei soldati sopravvissero a un inverno brutale. Respingemmo i barbari e difendemmo la nostra civiltà, la nostra storia."
  },
  AvgDialog_131215_Content_65 = {
    Text = "Nella nostra ora più buia, i feriti offrirono la propria carne per sfamare i compagni... fu una vittoria di pura agonia, mia Dea."
  },
  AvgDialog_131215_Content_66 = {
    Text = "Quando il nemico si ritirò, piangemmo di gioia. Al festino, versai spiriti forti per ogni uomo rimasto."
  },
  AvgDialog_131215_Content_67 = {
    Text = "Ma in quell'esatto istante — prima ancora che potessimo alzare un brindisi — le nostre case crollarono in cenere, e i nostri cari svanirono nel nulla."
  },
  AvgDialog_131215_Content_68 = {
    Text = "<Shake:Amata Dea, non vorresti concederci nemmeno un singolo istante di gioia?>"
  },
  AvgDialog_131215_Content_69 = {Text = "..."},
  AvgDialog_131215_Content_7 = {
    Text = "Nefraea ha abbandonato la sua maniacale persona da palcoscenico. Si volta indietro, guardandovi con impaziente attesa."
  },
  AvgDialog_131215_Content_70 = {
    Text = "\"Nefraea\" sopporta i lamenti incessanti delle marionette. Due righe di lacrime tracciano solchi sul suo volto privo di espressione."
  },
  AvgDialog_131215_Content_71 = {
    Text = "Ti ascolto. Ti vedo."
  },
  AvgDialog_131215_Content_72 = {
    Text = "Le grandi civiltà crollano; l'arte e l'architettura magnifica si riducono in cenere. Le anime gemelle si dimenticano l'una dell'altra e incontrano la loro fine violenta nel terrore."
  },
  AvgDialog_131215_Content_73 = {
    Text = "Un solo fato \"corretto\" rimane. Gli innumerevoli \"errori\" generati in quello stesso istante si riversano in questo selvaggio Abisso. In questo tempo congelato, la stessa rappresentazione si ripete ogni singolo giorno."
  },
  AvgDialog_131215_Content_74 = {
    Text = "Quanto ancora dovrò guardare tutto questo, sorella? Quanto ancora dovrò ascoltare?"
  },
  AvgDialog_131215_Content_75 = {
    Text = "\"Nefraea\" inspira bruscamente e volge le spalle al pubblico."
  },
  AvgDialog_131215_Content_76 = {
    Text = "Non temete, fanciulli miei. La sofferenza che vi ho inflitto... sarò io stessa a porvi fine."
  },
  AvgDialog_131215_Content_77 = {
    Text = "Riposate qui per ora. Un giorno vi condurrò fuori da questo luogo e reclamerò i destini che vi spettano di diritto."
  },
  AvgDialog_131215_Content_78 = {
    Text = "In nome di Nefraea, Vendicatrice del Fato, vi do la mia parola..."
  },
  AvgDialog_131215_Content_79 = {Text = "..."},
  AvgDialog_131215_Content_8 = {
    Text = "Vedendo il vostro silenzio, scuote la testa con delusione."
  },
  AvgDialog_131215_Content_80 = {
    Text = "La la la la... la la..."
  },
  AvgDialog_131215_Content_81 = {
    Text = "Mentre il palcoscenico svanisce e le luci si spengono, scorgi per un istante le braccia protese della marionetta e le striature scure sul suo volto."
  },
  AvgDialog_131215_Content_82 = {
    Text = "Resti in silenzio. Solo Nefraea canticchia la melodia del palcoscenico. La sua voce è limpida e chiara, come una storia raccontata così tante volte che ogni emozione ne è stata prosciugata."
  },
  AvgDialog_131215_Content_83 = {
    Text = "Oh! Sta per arrivare uno dei miei atti preferiti! Sbrigati, sorella!"
  },
  AvgDialog_131215_Content_84 = {
    Text = "La voce di Nefraea risuona di euforia. Prende la mano di Arachne e si lancia verso il livello successivo."
  },
  AvgDialog_131215_Content_85 = {Text = "..."},
  AvgDialog_131215_Content_86 = {
    Text = "Le luci si accendono. Non c'è musica, non c'è dialogo — solo una marionetta solitaria a un filatoio su un palcoscenico vuoto."
  },
  AvgDialog_131215_Content_87 = {
    Text = "Scric, scric. La ruota gira, come se il giorno in cui si fermerà non arriverà mai."
  },
  AvgDialog_131215_Content_88 = {
    Text = "...Danzano. Cantano. Scricchiolio — scricchiolio —"
  },
  AvgDialog_131215_Content_89 = {
    Text = "La luce del sole bagna i loro volti. Quanta gioia nei loro occhi..."
  },
  AvgDialog_131215_Content_9 = {
    Text = "Niente applausi? Niente lacrime? Il silenzio è un tale insulto... e dopo che ho provato così a lungo nella Prigione Abissale. Un vero peccato."
  },
  AvgDialog_131215_Content_90 = {
    Text = "La marionetta di \"Arachne\" canticchia una ninnananna con il suo volto inespressivo. Le sue dita girano la ruota con un ritmo costante, senza fretta."
  },
  AvgDialog_131215_Content_91 = {
    Text = "È un ritmo ossessionante: basta uno sguardo per capire che, una volta iniziato, non cambierà mai fino alla fine di ogni cosa."
  },
  AvgDialog_131215_Content_92 = {
    Text = "La Dea del Fato ha quasi terminato la sua Grande Tela."
  },
  AvgDialog_131215_Content_93 = {
    Text = "La Tela del Fato completa veglia su tutti... danzano, cantano..."
  },
  AvgDialog_131215_Content_94 = {
    Text = "Un'immensa tela si propaga attraverso il palcoscenico. I fili sciolti del Fato ricadono oltre il bordo della piattaforma."
  },
  AvgDialog_131215_Content_95 = {
    Text = "Ogni volta che la tela si avvicina al completamento, i suoi bordi più esterni iniziano a dissolversi."
  },
  AvgDialog_131215_Content_96 = {
    Text = "Fanghiglia d'inchiostro e fuliggine oscura si dissolvono nel nulla. Conosci fin troppo bene questa visione."
  },
  AvgDialog_131215_Content_97 = {
    Text = "Gioite, fanciulli miei, popolo mio... la Dea del Fato ha quasi ultimato la sua Grande Tela..."
  },
  AvgDialog_131215_Content_98 = {
    Text = "La marionetta fissa la tela, tessuta e cancellata in un ciclo senza fine."
  },
  AvgDialog_131215_Content_99 = {
    Text = "La sua voce non trema; le sue mani non esitano. Prosegue la sua dolce melodia mentre la ruota gira, senza mai fermarsi."
  },
  AvgDialog_131216_Content_1 = {Text = "Mascherata"},
  AvgDialog_131216_Content_10 = {
    Text = "Un doppiopesismo alquanto sfacciato, Senior."
  },
  AvgDialog_131216_Content_11 = {
    Text = "Ahem... Formulare Giudizi che si allineino al carattere di ciascuno è un'Abilità Base per un Investigatore..."
  },
  AvgDialog_131216_Content_12 = {
    Text = "William finge di non cogliere la vostra frecciata e inizia a cercare seriamente un bersaglio degno a cui avvicinarsi."
  },
  AvgDialog_131216_Content_13 = {
    Text = "Ho perso tutto in quella Battaglia. Il mio titolo, la mia famiglia, la mia gamba sinistra... la mia vita."
  },
  AvgDialog_131216_Content_14 = {
    Text = "Vent'anni. Vent'anni interi. È stata una lenta tortura, amico mio. Il destino ha voluto lasciarmi in vita, condannandomi a trascorrere i giorni restanti espiando i miei errori."
  },
  AvgDialog_131216_Content_15 = {
    Text = "Ho distrutto il mio stesso lignaggio con le mie stesse mani, ma che importa ormai? Dimmi, c'è qualcosa in questa vita più importante di un drink?"
  },
  AvgDialog_131216_Content_16 = {Text = "..."},
  AvgDialog_131216_Content_17 = {
    Text = "Oh, tesoro, ricordi il cocktail che il barista ci preparò l'ultima volta che eravamo qui?"
  },
  AvgDialog_131216_Content_18 = {
    Text = "Scommetto che non troverai un drink migliore in tutta Londinium. Era così preciso, così elegante — sembrava meno una ricetta e più una Profezia!"
  },
  AvgDialog_131216_Content_19 = {
    Text = "Stavo pensando a quanto sarebbe meraviglioso se potessimo invitare quel barista alla nostra festa il mese prossimo."
  },
  AvgDialog_131216_Content_2 = {
    Text = "\"90 minuti dopo la mezzanotte, una maschera da 15 pollici, 10 galloni di sogno, 2 once di spiriti — l'unica formula per la felicità.\""
  },
  AvgDialog_131216_Content_20 = {Text = "..."},
  AvgDialog_131216_Content_21 = {Text = "Pop—"},
  AvgDialog_131216_Content_22 = {
    Text = "Un secco schiocco di dita risuona come un fuoco d'artificio accanto al vostro orecchio. Vi voltate e trovate un volto illuminato da un sorriso radioso."
  },
  AvgDialog_131216_Content_23 = {
    Text = "Perdonate l'interruzione, stimati ospiti. Dato che state discutendo di argomenti così affascinanti, che ne dite di un drink altrettanto affascinante per accompagnarli?"
  },
  AvgDialog_131216_Content_24 = {
    Text = "Vediamo un menu, William."
  },
  AvgDialog_131216_Content_25 = {
    Text = "William comprende il vostro sguardo. Due persone in uniformi non identificate sedute in un posto come questo senza toccare una goccia d'alcol è un modo sicuro per attirare attenzioni indesiderate."
  },
  AvgDialog_131216_Content_26 = {
    Text = "Vedendolo cercare un menu, la barista scuote la testa con un sorriso malizioso."
  },
  AvgDialog_131216_Content_27 = {
    Text = "Un menu? Che buffo. Che tedioso. Che... ordinario."
  },
  AvgDialog_131216_Content_28 = {
    Text = "Un locale davvero romantico non ha spazio per qualcosa di così banale."
  },
  AvgDialog_131216_Content_29 = {
    Text = "Niente menu? E come dovremmo ordinare, allora?"
  },
  AvgDialog_131216_Content_3 = {
    Text = "Ho memorizzato lo slogan del Ballo di Mezzanotte da anni. Quando ero a Kadath, era il posto che desideravo visitare più di ogni altro."
  },
  AvgDialog_131216_Content_30 = {
    Text = "Ogni posto al Ballo di Mezzanotte è un teatro privato per l'ospite che lo occupa. Qui si osserva, si recita e si assapora..."
  },
  AvgDialog_131216_Content_31 = {
    Text = "Da una biblioteca di storie infinite, sceglierò quella più adatta a voi."
  },
  AvgDialog_131216_Content_32 = {
    Text = "Prego, accomodatevi. Il narratore è pronto."
  },
  AvgDialog_131216_Content_33 = {
    Text = "Voi e William vi scambiate un'occhiata prima di prendere posto esitanti al bancone del bar."
  },
  AvgDialog_131216_Content_34 = {
    Text = "Per prima cosa, guardiamo voi — lo stoico gentiluomo dai capelli chiari."
  },
  AvgDialog_131216_Content_35 = {
    Text = "La barista si avvicina. Sotto il suo sguardo indagatore, William tossisce sommessamente e distoglie lo sguardo, leggermente a disagio."
  },
  AvgDialog_131216_Content_36 = {
    Text = "Ah... vedo i frutti di una disciplina quotidiana estenuante. Tenacia, compostezza, spirito tenace, coraggio, saggezza... Una leggenda vivente, ammantata di tributi floreali e gloria."
  },
  AvgDialog_131216_Content_37 = {
    Text = "Eppure, dietro le lodi e l'aureola si cela... il rimpianto. Un rimpianto più profondo e straziante della nebbia che soffoca questa città."
  },
  AvgDialog_131216_Content_38 = {
    Text = "Vedo le lacrime che brillano invisibili nel cuore della notte. Odo i giuramenti sussurrati solo a sé stessi."
  },
  AvgDialog_131216_Content_39 = {
    Text = "La luce che un tempo vi guidava nell'oscurità si è spenta, e con essa il vostro mondo si è frantumato... e frantumato ancora."
  },
  AvgDialog_131216_Content_4 = {
    Text = "Non pensi che le Regole di Mythag siano un po' troppo rigide a volte?"
  },
  AvgDialog_131216_Content_40 = {
    Text = "Pensi tra te: <Italic:Se solo mi fossi impegnato di più. Se solo fossi stato più forte... forse avrei potuto tessere un destino diverso per il mio caro amico.>"
  },
  AvgDialog_131216_Content_41 = {
    Text = "L'espressione di William resta una maschera d'indifferenza, ma notate le vene gonfie sulla mano che stringe il bicchiere fino a sbiancare le nocche."
  },
  AvgDialog_131216_Content_42 = {
    Text = "Riesco a udire il suono di un mondo che va in frantumi. Un ragazzino affronta il dolore, raccogliendo i frammenti uno a uno, ricucendoli insieme..."
  },
  AvgDialog_131216_Content_43 = {
    Text = "Attraverso questa lunga, brutale riparazione, il ragazzino è infine diventato un uomo."
  },
  AvgDialog_131216_Content_44 = {
    Text = "La sua voce è una cadenza bassa e melodiosa mentre preleva bottiglie dalle forme bizzarre da uno scaffale che sembra estendersi all'infinito, dando inizio alla sua arte."
  },
  AvgDialog_131216_Content_45 = {
    Text = "In breve, fa scivolare un bicchiere di liquido dorato pallido verso William."
  },
  AvgDialog_131216_Content_46 = {
    Text = "Due once di whiskey, un'oncia di vino bianco, e una base di dolorosa tenacia — due gocce di amaro."
  },
  AvgDialog_131216_Content_47 = {
    Text = "<Yellow:\"L'Esploratore\">. Spero che Lei possa guidare coloro che La venerano insieme a sé, trovando il cammino giusto — proprio come colui che Lei venera ha un tempo guidato Lei."
  },
  AvgDialog_131216_Content_48 = {
    Text = "William accetta il drink dorato, facendolo roteare lentamente mentre studia la barista con uno sguardo penetrante."
  },
  AvgDialog_131216_Content_49 = {
    Text = "Tutto quello che hai appena detto... come fai a sapere tutte queste cose?"
  },
  AvgDialog_131216_Content_5 = {
    Text = "Ho proposto di vietare agli Studenti di Mythag l'accesso a tali locali senza autorizzazione proprio per impedire che certi Custodi — quelli negligenti — dilapidassero i fondi delle missioni con il pretesto di condurre Indagini."
  },
  AvgDialog_131216_Content_50 = {
    Text = "Un maestro barista deve saper ascoltare l'anima. Questo è un segreto del mestiere, mio caro ospite."
  },
  AvgDialog_131216_Content_51 = {
    Text = "La barista schiva lo sguardo di William con la grazia di un cerbiatto. Si preme un dito sulle labbra in un gesto di silenzio, poi indica direttamente te."
  },
  AvgDialog_131216_Content_52 = {
    Text = "Ora, per te..."
  },
  AvgDialog_131216_Content_53 = {
    Text = "Ho la sensazione che questa potrebbe essere la cosa più pericolosa che abbia mai tentato — ma non importa. Ho sempre avuto un debole per l'avventura."
  },
  AvgDialog_131216_Content_54 = {
    Text = "Si avvicina, fissandoti intensamente negli occhi. Riesci quasi a sentire il ritmo sommesso del suo respiro."
  },
  AvgDialog_131216_Content_55 = {
    Text = "Hmm... Cosa sto guardando? Un viaggiatore da un luogo lontano? O forse... una divinità decaduta, che arranca nel fango del reame mortale?"
  },
  AvgDialog_131216_Content_56 = {Text = "?!!"},
  AvgDialog_131216_Content_57 = {
    Text = "Indietreggi d'istinto, il cuore che martella contro le costole."
  },
  AvgDialog_131216_Content_58 = {
    Text = "È impossibile che una barista qualunque sappia queste cose... Chi — o cosa — sei?!"
  },
  AvgDialog_131216_Content_59 = {
    Text = "Stai tranquillo, caro ospite. In questo bar, non sono io quella con intenzioni malevole."
  },
  AvgDialog_131216_Content_6 = {
    Text = "Questo particolare Custode, dopotutto, ha accumulato un bel curriculum durante il periodo da Studente."
  },
  AvgDialog_131216_Content_60 = {
    Text = "Potresti aver notato che alcuni dei tuoi \"vecchi amici\" sono appena arrivati alle tue spalle."
  },
  AvgDialog_131216_Content_61 = {
    Text = "%player%, attento alle spalle."
  },
  AvgDialog_131216_Content_62 = {
    Text = "Li sento..."
  },
  AvgDialog_131216_Content_63 = {
    Text = "Messo in allerta dall'avvertimento, percepisci oltre una dozzina di acute increspature psichiche che si avvicinano rapidamente da ogni direzione."
  },
  AvgDialog_131216_Content_64 = {
    Text = "William si muove per coprire le tue spalle in perfetta sincronia. Stringi forte la tua Chiave d'argento, gli occhi fissi sull'enigmatico barista."
  },
  AvgDialog_131216_Content_65 = {
    Text = "La barista posa il bicchiere e sposta le bottiglie in un angolo sicuro dove non si romperanno nella mischia."
  },
  AvgDialog_131216_Content_66 = {
    Text = "Piano, %player%. Ti stanno seguendo le tracce da un po'. Qui, almeno, posso offrirti un qualche tipo di aiuto."
  },
  AvgDialog_131216_Content_67 = {
    Text = "Tu? Loro? ..."
  },
  AvgDialog_131216_Content_68 = {
    Text = "Heh... Trovato."
  },
  AvgDialog_131216_Content_69 = {
    Text = "Questo lurido posto non è adatto a una lunga permanenza, miei piccoli visitatori da lontano."
  },
  AvgDialog_131216_Content_7 = {
    Text = "Oh, ma mi sembra di ricordare che nel fascicolo del Senior Fingal il suo più grande passatempo fosse fermarsi al Ballo di Mezzanotte per un drink dopo il lavoro..."
  },
  AvgDialog_131216_Content_70 = {
    Text = "Attenzione! Stanno arrivando!"
  },
  AvgDialog_131216_Content_8 = {
    Text = "...E naturalmente, un Riposo occasionale non è del tutto privo di merito."
  },
  AvgDialog_131216_Content_9 = {
    Text = "Inoltre, la lista dei membri del Ballo di Mezzanotte include l'Élite di tutta Londinium. È il luogo ideale per raccogliere informazioni."
  },
  AvgDialog_131217_Content_1 = {
    Text = "L'Autorità dei Tre Eoni si insedia dentro di te, eppure tieni gli Occhi chiusi."
  },
  AvgDialog_131217_Content_10 = {
    Text = "Lo spirito dei contratti, i principi degli affari... un accordo richiede una leva. Sai come funziona, non è vero?"
  },
  AvgDialog_131217_Content_11 = {
    Text = "\"N\" scuote la testa, sforzandosi di trattenere una risata."
  },
  AvgDialog_131217_Content_12 = {
    Text = "La buona notizia è che hai sempre la leva perfetta."
  },
  AvgDialog_131217_Content_13 = {
    Text = "Un valoroso guardiano sul punto di abbandonare la {Male=his,Female=her} fede, annegando nella tela del Fato... ingannare, imbrogliare, del tutto privo di principi... che scena accattivante!"
  },
  AvgDialog_131217_Content_14 = {
    Text = "Non mi perderei il miglior posto in prima fila per nulla al mondo."
  },
  AvgDialog_131217_Content_15 = {
    Text = "Quando mai ho detto—"
  },
  AvgDialog_131217_Content_16 = {
    Text = "Il Festaiolo non ha pazienza per le tue domande. Soppesa il debito che contrarrai in futuro e agita un dito con un ghigno."
  },
  AvgDialog_131217_Content_17 = {
    Text = "Non tanto un suggerimento, quanto un piccolo e sincero consiglio."
  },
  AvgDialog_131217_Content_18 = {
    Text = "Perché resistere a Nefraea? Perché non sottometterti a lei, %player%?"
  },
  AvgDialog_131217_Content_19 = {
    Text = "\"N\" sorride e si sporge verso di te, benevolo come un avvocato in visita a un cliente in prigione."
  },
  AvgDialog_131217_Content_2 = {
    Text = "La tua coscienza si immerge più a fondo nel vasto oceano della mente, sprofondando nell'Oscurità sconfinata, discendendo nell'Abisso dentro di te."
  },
  AvgDialog_131217_Content_20 = {
    Text = "Tu... cosa hai detto? No, non potrei mai—"
  },
  AvgDialog_131217_Content_21 = {
    Text = "Ah, giusto. Mai rinunciare, mai arrendersi, mai accettare i crimini di Nefraea... eroismo vecchio stampo, un classico."
  },
  AvgDialog_131217_Content_22 = {
    Text = "Consegnaci a Nefraea, richiama quella cara <Italic:cugina> tua, e fa' ritorno al <Italic:palazzo> che ti appartiene... oltre a questo, cos'altro puoi fare, %player%?"
  },
  AvgDialog_131217_Content_23 = {
    Text = "Ti svelerò un segreto: dal momento che non puoi sfuggire alla rete, perché non aprire le braccia e darle il benvenuto?"
  },
  AvgDialog_131217_Content_24 = {
    Text = "Smettila di sognare, \"N\". Non potrei mai..."
  },
  AvgDialog_131217_Content_25 = {
    Text = "Shh. Non sminuirti, tesoro."
  },
  AvgDialog_131217_Content_26 = {
    Text = "Non dimenticare, Arachne ha intessuto il tuo fato nella Grande Rete. Sei già uno di loro."
  },
  AvgDialog_131217_Content_27 = {
    Text = "La Dea del Fato ti ha dato una chiave chiamata Estasi. Ma ti sei mai chiesto verso dove si affaccia quella Porta, e dove conduce?"
  },
  AvgDialog_131217_Content_28 = {
    Text = "Dove la Porta è rivolta... dove conduce...?"
  },
  AvgDialog_131217_Content_29 = {
    Text = "Credevo che Arachne fosse una signora laboriosa, gentile e del tutto insignificante, i cui unici talenti fossero tessere e sorridere. Ma è assai più interessante di quanto immaginassi."
  },
  AvgDialog_131217_Content_3 = {
    Text = "Ti sforzi di aprire una bocca che non esiste, urlando in silenziosa Furia nelle profondità."
  },
  AvgDialog_131217_Content_30 = {
    Text = "Ha tessuto una vasta rete per questo livello, e dal momento in cui sei giunto in questo mondo, quella rete ha cominciato a dispiegarsi per te."
  },
  AvgDialog_131217_Content_31 = {
    Text = "Possedere un talento così straordinario, e sprecarlo in qualcosa di tanto sciocco come mantenere il mondo in funzione... Un peccato, davvero. Che spreco."
  },
  AvgDialog_131217_Content_32 = {
    Text = "Salire sul palco del Teatro del Fato significa diventare un personaggio. E ogni personaggio ha una vita propria."
  },
  AvgDialog_131217_Content_33 = {
    Text = "Il Fato vi ha costretto a compiere quella scelta affinché poteste finalmente vederlo per ciò che è. Non potete scorgere i fili stessi, ma ora comprendete i modi intricati in cui sono intessuti."
  },
  AvgDialog_131217_Content_34 = {
    Text = "Questi fili formano una vasta trama. Il minimo tremore in un singolo filo può far crollare l'intera struttura."
  },
  AvgDialog_131217_Content_35 = {
    Text = "Questo è il Fato, {Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_131217_Content_36 = {
    Text = "Recitare, ingannare, intrattenere... porti quei poteri dentro di te. Il palcoscenico del Fato raramente concede tempo per una Prova generale. Quando il momento verrà, quel Potere ti sosterrà."
  },
  AvgDialog_131217_Content_37 = {
    Text = "Non puoi sfuggire ai ruoli che eri destinato a interpretare. Rifletti, poi recita, {Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_131217_Content_38 = {Text = "\"Estasi.\""},
  AvgDialog_131217_Content_39 = {
    Text = "Nel tuo futuro immediato, \"Estasi\" è una chiave. Aprirà il lucchetto segreto che hai davanti."
  },
  AvgDialog_131217_Content_4 = {Text = "\"N\"!"},
  AvgDialog_131217_Content_40 = {
    Text = "...Qualunque cosa accada, fidati di me. E fidati di te stessa."
  },
  AvgDialog_131217_Content_41 = {
    Text = "Fa' Ritorno al Teatro del Fato. La chiave e la serratura ti attendono là, %player%."
  },
  AvgDialog_131217_Content_42 = {
    Text = "Le parole di Arachne si intrecciano nella tua mente come fili di seta, incrociandosi e avvolgendosi l'uno sull'altro. Infine convergono in una vasta, intricata rete."
  },
  AvgDialog_131217_Content_43 = {
    Text = "Finalmente comprendi. Sin dal primo incontro, Arachne ti ha parlato attraverso il tempo."
  },
  AvgDialog_131217_Content_44 = {
    Text = "Fissi la ragnatela intricata con stupore. Qualcosa di vitale sta prendendo forma nella tua mente."
  },
  AvgDialog_131217_Content_45 = {
    Text = "Recitare... ingannare... intrattenere..."
  },
  AvgDialog_131217_Content_46 = {
    Text = "Ah, sì. Non cercare mai di dare un senso a nulla. Semplicemente godi! Questo è l'unico segreto dell'Estasi."
  },
  AvgDialog_131217_Content_47 = {
    Text = "Gioia e dolore, bene e male — emozioni e moralità cessano di esistere. Non resta nulla se non il piacere."
  },
  AvgDialog_131217_Content_48 = {
    Text = "Ora, dimmi... comprendi l'\"Estasi,\" Custode?"
  },
  AvgDialog_131217_Content_49 = {
    Text = "Il sorriso cremisi di \"N\" svanisce dalla tua mente. Vedi uno specchio, e riflesso in esso c'è il tuo stesso volto che ride."
  },
  AvgDialog_131217_Content_5 = {
    Text = "Shh... sei troppo rumoroso, Custode."
  },
  AvgDialog_131217_Content_50 = {
    Text = "Estasi...? Estasi..."
  },
  AvgDialog_131217_Content_51 = {
    Text = "Hehehe... hahahaha. Sì! Estasi, amico mio!"
  },
  AvgDialog_131217_Content_52 = {
    Text = "La parola più meravigliosa dell'esistenza, l'intero significato di questo sogno..."
  },
  AvgDialog_131217_Content_53 = {
    Text = "Come se intravedesse la scena che sta per compiersi, l'intero corpo di N trema di delizia. Preme un dito avvolto da una foschia oscura contro la propria fronte."
  },
  AvgDialog_131217_Content_54 = {
    Text = "Ci sei quasi. Solo a un passo. Rifletti, poi entra nella ragnatela, Custode."
  },
  AvgDialog_131217_Content_55 = {
    Text = "La verità dell'Estasi giace all'interno."
  },
  AvgDialog_131217_Content_6 = {
    Text = "Il fantasma di \"N\" permane. Appare nel tuo spazio mentale con disinvoltura, come il padrone indiscusso del reame."
  },
  AvgDialog_131217_Content_7 = {
    Text = "L'\"Estasi\" di cui parlava Arachne... intendeva te!"
  },
  AvgDialog_131217_Content_8 = {
    Text = "\"N\", dammi un indizio..."
  },
  AvgDialog_131217_Content_9 = {
    Text = "Un suggerimento? Hahaha... cosa ho fatto per meritare un simile insulto?"
  },
  AvgDialog_131218_Content_10 = {
    Text = "Voi... Tutti voi... cosa sta succedendo?"
  },
  AvgDialog_131218_Content_11 = {
    Text = "L'ubriaco, la giovane donna, il gentiluomo nobile, il delinquente, il cameriere esausto, la bella barista..."
  },
  AvgDialog_131218_Content_12 = {
    Text = "Ogni volto nel locale — giovane, anziano, avvenente o anonimo — si volta verso di te all'unisono, le espressioni identiche come copie carbone."
  },
  AvgDialog_131218_Content_13 = {
    Text = "Non sono individui. Sono più simili a..."
  },
  AvgDialog_131218_Content_14 = {
    Text = "Coloro che sembravano così pieni di vita solo un istante fa ora stanno davanti a te come manichini di legno senza vita."
  },
  AvgDialog_131218_Content_15 = {
    Text = "...Più simili a marionette, intrappolate in una ragnatela."
  },
  AvgDialog_131218_Content_16 = {
    Text = "Ho sentito molto parlare del vostro acuto intuito, Sig. William."
  },
  AvgDialog_131218_Content_17 = {
    Text = "Ciò che vedete dinanzi a voi non sono che oggetti di scena su un palcoscenico — riflessi in uno specchio."
  },
  AvgDialog_131218_Content_18 = {
    Text = "Vi prego di scusarmi. Non posso ancora lasciare la mia tela. Devo usare questi ricettacoli per parlarvi."
  },
  AvgDialog_131218_Content_19 = {
    Text = "Benvenuto sul mio palcoscenico, Sig. William... e anche voi, {Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_131218_Content_2 = {
    Text = "È finita... ma che diavolo erano quelle cose?"
  },
  AvgDialog_131218_Content_20 = {
    Text = "Ogni parola è pronunciata con una precisione inquietante; venti voci distinte si intrecciano in un unico, gelido filo di voce."
  },
  AvgDialog_131218_Content_21 = {
    Text = "Tutti nella stanza si inchinano in perfetta sincronia. L'angolazione delle schiene e la posizione delle mani sono speculari con un'esattezza innaturale."
  },
  AvgDialog_131218_Content_22 = {
    Text = "Il vostro... livello? Chi siete voi?"
  },
  AvgDialog_131218_Content_23 = {
    Text = "Sono il padrone di questo luogo — e il suo Prigioniero."
  },
  AvgDialog_131218_Content_24 = {
    Text = "Immagino abbiate molte domande."
  },
  AvgDialog_131218_Content_25 = {
    Text = "Questo luogo non è più sicuro; i loro uomini torneranno presto. La mia ancella verrà a prendervi. Non allarmatevi quando la vedrete."
  },
  AvgDialog_131218_Content_26 = {
    Text = "Una volta che ci incontreremo faccia a faccia, risponderò a ogni domanda."
  },
  AvgDialog_131218_Content_27 = {
    Text = "Nell'istante in cui quelle parole le sfuggono dalle labbra, la coscienza della folla sembra prosciugarsi in un attimo."
  },
  AvgDialog_131218_Content_28 = {
    Text = "Il bicchiere di cristallo di un gentiluomo si blocca alle sue labbra; il ventaglio aperto di una dama si immobilizza appena sotto il mento; il barista resta in posa, il bicchiere sollevato in alto."
  },
  AvgDialog_131218_Content_29 = {
    Text = "Come se i loro fili fossero stati recisi tutti in una volta, ognuno mantiene la propria posa finale — figure di cera cristallizzate sul posto."
  },
  AvgDialog_131218_Content_3 = {
    Text = "Attento alle spalle!!"
  },
  AvgDialog_131218_Content_30 = {
    Text = "Trai un respiro lento e ti guardi intorno con inquietudine nel mare di \"marionette\", ciascuna immobile con quello stesso, immutabile sorriso."
  },
  AvgDialog_131218_Content_31 = {
    Text = "Mi hanno aiutato poco fa, è vero, ma non riesco ancora a fidarmi completamente di loro..."
  },
  AvgDialog_131218_Content_32 = {
    Text = "William, per tutto ciò che dobbiamo sapere... questa \"Dama\" potrebbe essere la nostra migliore occasione per avere risposte."
  },
  AvgDialog_131218_Content_33 = {
    Text = "Anche se è pericoloso, credo di doverci andare. È solo che..."
  },
  AvgDialog_131218_Content_34 = {Text = "Lo so."},
  AvgDialog_131218_Content_35 = {
    Text = "Incrociando il vostro sguardo, William annuisce in silenzio, con aria d'intesa."
  },
  AvgDialog_131218_Content_36 = {
    Text = "Traccerò i movimenti di quelle ombre qui fuori. Vi stanno cercando. Muovendomi all'esterno attirerò meno attenzione di quanta ne attirereste voi."
  },
  AvgDialog_131218_Content_37 = {
    Text = "Questa \"Dama\" ha origini sconosciute. Se qualcosa dovesse andare storto..."
  },
  AvgDialog_131218_Content_38 = {
    Text = "William batte il dito sul distintivo appuntato al petto. Naufraghi insieme in questo mondo estraneo, i vostri distintivi raggiungono soltanto l'uno l'altro."
  },
  AvgDialog_131218_Content_39 = {
    Text = "Capisco... Anche tu, William."
  },
  AvgDialog_131218_Content_4 = {
    Text = "Una scarica di pura adrenalina ti scuote dal torpore. Ti volti di scatto e trovi una lama d'ombra solidificata sospesa a pochi centimetri dalla tua gola."
  },
  AvgDialog_131218_Content_40 = {
    Text = "La Dama comprende la vostra cautela. Sig. William, questo Livello cela molti pericoli in questo momento; vi prego di procedere con prudenza. Offriremo tutta l'assistenza possibile."
  },
  AvgDialog_131218_Content_41 = {
    Text = "Ragni di un pallido violetto convergono da ogni angolo del locale, e un'Ancella dai tratti aracnidi appare silenziosamente alle vostre spalle. Dopo avervi rivolto un cortese inchino, si dirige verso la porta."
  },
  AvgDialog_131218_Content_42 = {
    Text = "{Male=Sig.,Female=Sig.na} Custode, prego, seguitemi. La Dama vi attende."
  },
  AvgDialog_131218_Content_5 = {Text = "Ssssh—"},
  AvgDialog_131218_Content_6 = {
    Text = "Abbassi lentamente il braccio che ti proteggeva il volto. L'ombra è stata squarciata da qualcuno alle tue spalle; icore nero schizza nell'aria, macchiandoti i vestiti."
  },
  AvgDialog_131218_Content_7 = {
    Text = "Perdonate lo spavento."
  },
  AvgDialog_131218_Content_8 = {
    Text = "Ti stanno dando la caccia. Entro queste mura, posso almeno darti una mano."
  },
  AvgDialog_131218_Content_9 = {
    Text = "Perdonami per essermi presa la libertà di guidarti fin qui senza il tuo consenso."
  },
  AvgDialog_131219_Content_1 = {
    Text = "È... è finita?"
  },
  AvgDialog_131219_Content_2 = {
    Text = "Stai attento, Custode... il fuso che dipana il destino ha già cominciato a girare dietro di lei..."
  },
  AvgDialog_131219_Content_3 = {
    Text = "Eh... ahahaha...!"
  },
  AvgDialog_131220_Content_1 = {
    Text = "Vola, Cigno, Vola"
  },
  AvgDialog_131220_Content_10 = {
    Text = "Ricordi il cancello arrugginito che geme ogni volta che si muove, come il respiro costante di un nonno."
  },
  AvgDialog_131220_Content_11 = {
    Text = "L'Università Miskatonic..."
  },
  AvgDialog_131220_Content_12 = {
    Text = "In questo scenario familiare, tracci il nome sconosciuto inciso sulla targa della piazza."
  },
  AvgDialog_131220_Content_13 = {
    Text = "Ogni attore ha un palcoscenico che ama più di ogni altro. Persino un campus costruito dalle memorie è insostituibile per te."
  },
  AvgDialog_131220_Content_14 = {
    Text = "Perché creare un luogo identico a Mythag...?"
  },
  AvgDialog_131220_Content_15 = {
    Text = "Non l'ho creato io; semplicemente appartiene a questo luogo. Come questa città e questo mondo, è un frammento della Grande Rete."
  },
  AvgDialog_131220_Content_16 = {
    Text = "Non guardare così lontano, %player%. Se ti trovi su un palcoscenico, c'è una ragione per cui sei qui."
  },
  AvgDialog_131220_Content_17 = {
    Text = "A pensarci bene, dopo tutto il tempo trascorso con Liz, non l'ho mai vista esibirsi dal vivo."
  },
  AvgDialog_131220_Content_18 = {
    Text = "Ti guardi intorno nella piazza familiare, le dita che sfiorano l'erba."
  },
  AvgDialog_131220_Content_19 = {
    Text = "I momenti più belli della vita sono quelli in cui non ti rendi nemmeno conto di sorridere."
  },
  AvgDialog_131220_Content_2 = {
    Text = "È un lusso raro. Anche il biglietto più economico per questa compagnia mi costerebbe normalmente due mesi di stipendio."
  },
  AvgDialog_131220_Content_20 = {
    Text = "Oh... scusa."
  },
  AvgDialog_131220_Content_21 = {
    Text = "Stai pensando a Mythag?"
  },
  AvgDialog_131220_Content_22 = {
    Text = "Abbiamo tenuto così tante esibizioni in questa piazza. A quei tempi era gremita di studenti di Mythag, proprio come adesso."
  },
  AvgDialog_131220_Content_23 = {
    Text = "Molti Risvegliatori sono maestri nella loro arte. Alcuni all'inizio erano riluttanti a esibirsi, così io e il corpo docente dovevamo trovare il modo di convincerli..."
  },
  AvgDialog_131220_Content_24 = {
    Text = "Alla fine, molti di loro iniziarono a offrirsi volontari per mettere in scena spettacoli per i loro compagni."
  },
  AvgDialog_131220_Content_25 = {
    Text = "Le danze di Liz, le ballate di Tintura, le sinfonie di Hameln, la poesia di Horla, le sculture di Sanga..."
  },
  AvgDialog_131220_Content_26 = {
    Text = "Mi chiedo se la vita a Mythag sia mai tornata com'era dopo la mia partenza..."
  },
  AvgDialog_131220_Content_27 = {
    Text = "Il sipario si è appena mosso! La signorina Elizabeth sta per fare il suo ingresso!"
  },
  AvgDialog_131220_Content_28 = {
    Text = "Scuoti la testa, scacciando la malinconia dalla mente."
  },
  AvgDialog_131220_Content_29 = {
    Text = "In ogni caso, vedere Liz danzare di nuovo in questo mondo lontano è qualcosa di cui essere grati."
  },
  AvgDialog_131220_Content_3 = {
    Text = "Ho sentito che Lady Sorel sta finanziando personalmente questo spettacolo di beneficenza! Se solo ogni nobile di questa città fosse così generoso."
  },
  AvgDialog_131220_Content_30 = {
    Text = "Quando tutto questo sarà finito, se ci sarà tempo, vorrei sedermi e parlare davvero con loro."
  },
  AvgDialog_131220_Content_31 = {
    Text = "Signore e signori... benvenuti al nostro spettacolo!"
  },
  AvgDialog_131220_Content_32 = {
    Text = "Il Cycnus Dance Troupe — un nome tanto sacro quanto intoccabile! Oggi, il più elegante cigno bianco di Londinium si presenta al pubblico per la primissima volta!"
  },
  AvgDialog_131220_Content_33 = {
    Text = "Grazie per la vostra pazienza. I nostri artisti sono pronti. Uno spettacolo straordinario sta per avere inizio!"
  },
  AvgDialog_131220_Content_34 = {
    Text = "Allo schiocco secco del presentatore, le luci si spengono. I riflettori convergono al centro del palcoscenico."
  },
  AvgDialog_131220_Content_35 = {
    Text = "Ora, godetevi \"Il Volo del Cigno,\" interpretato dalla signorina Elizabeth Salle!"
  },
  AvgDialog_131220_Content_36 = {
    Text = "Tra applausi fragorosi e ovazioni, il sipario si apre lentamente—"
  },
  AvgDialog_131220_Content_37 = {
    Text = "<Big:<Red:!!!!>>"
  },
  AvgDialog_131220_Content_38 = {
    Text = "Hai visto Liz molte volte."
  },
  AvgDialog_131220_Content_39 = {
    Text = "Nella sala cerimoniale di Mythag, lei danza una piroetta solo per voi."
  },
  AvgDialog_131220_Content_4 = {
    Text = "Non ci capisco nulla, ma non mi lascio sfuggire un'occasione come questa."
  },
  AvgDialog_131220_Content_40 = {
    Text = "Sotto le stelle di Londinium, le sue punte sfioravano lucciole danzanti nella notte."
  },
  AvgDialog_131220_Content_41 = {
    Text = "Nella brezza di Charing Cross Road, la sua gonna ondeggiava come una fiamma ardente."
  },
  AvgDialog_131220_Content_42 = {
    Text = "Ma oggi, su questo palcoscenico straniero, appare in un modo che non avreste mai immaginato."
  },
  AvgDialog_131220_Content_43 = {
    Text = "La prima ballerina, il fuoco d'artificio più abbagliante della città, è impalata. Spuntoni neri le trafiggono la gola, le braccia, il petto e i piedi arcuati — dilaniando il corpo che un tempo dominava la danza."
  },
  AvgDialog_131220_Content_44 = {
    Text = "Il sangue schizza contro il fondale, formando un paio di ali cremisi dietro di lei. Violente striature rosse deturpano il suo sorriso calmo e sereno."
  },
  AvgDialog_131220_Content_45 = {
    Text = "La folla piomba in un silenzio mortale. Il vento spazza la piazza, facendo ondeggiare il suo tutù nero e verde come una fiamma che arde in eterno."
  },
  AvgDialog_131220_Content_46 = {
    Text = "In questo istante, comprendete: se la morte è inevitabile, è esattamente così che Liz avrebbe scelto di affrontarla."
  },
  AvgDialog_131220_Content_47 = {
    Text = "Ha offerto il suo ultimo sipario con la propria vita. La sua figura è cristallizzata in un salto magnifico, come un cigno nero in volo."
  },
  AvgDialog_131220_Content_48 = {
    Text = "Ammirate la posa finale della signorina Elizabeth... che eleganza, che grazia!"
  },
  AvgDialog_131220_Content_49 = {
    Text = "Godetevi lo spettacolo, mio caro pubblico! Esserne testimoni è il più grande onore delle vostre vite."
  },
  AvgDialog_131220_Content_5 = {
    Text = "Trent'anni... Non mettevo piede in un teatro da trent'anni."
  },
  AvgDialog_131220_Content_50 = {
    Text = "Osservi il volto dell'annunciatore squarciarsi in due. La maschera senza vita dell'uomo di mezza età si scioglie come fanghiglia, rivelando gli occhi di Nefraea, spalancati dall'esaltazione."
  },
  AvgDialog_131220_Content_51 = {
    Text = "Tra le urla di panico e la fuga precipitosa della folla, la sua risata stridula vi trafigge le orecchie come un ago avvelenato."
  },
  AvgDialog_131220_Content_52 = {
    Text = "<Big:Liz!!>"
  },
  AvgDialog_131220_Content_53 = {
    Text = "Vi fate largo tra la folla terrorizzata e correte verso il palcoscenico."
  },
  AvgDialog_131220_Content_54 = {
    Text = "Oh? Un ospite davvero perspicace. Come hai fatto a sapere che questo spettacolo aveva un secondo atto?"
  },
  AvgDialog_131220_Content_55 = {
    Text = "Quelli rimasti indietro convergono improvvisamente su di te. I loro corpi esplodono mentre corrono, e implacabili scudieri-ragno neri strisciano fuori dalle spoglie."
  },
  AvgDialog_131220_Content_56 = {
    Text = "Sul palco, il corpo di Liz scivola giù dagli spuntoni. È un'opera d'arte plasmata da un'eretica, segnata da cavità crudeli e rosso vivido."
  },
  AvgDialog_131220_Content_57 = {
    Text = "Impronte insanguinate si estendono dal centro del palcoscenico. Liz cammina verso di te, il volto dipinto in una maschera macabra e stupefacente di sangue che ti lascia senza fiato."
  },
  AvgDialog_131220_Content_58 = {
    Text = "Alza lo sguardo verso di te. I suoi occhi cavi e sanguinanti ti ricordano un capolavoro destinato all'eternità."
  },
  AvgDialog_131220_Content_59 = {
    Text = "Ora, è tempo di danzare con il tuo Vecchio Amico... {Male=Sig.,Female=Sig.na} Custode!"
  },
  AvgDialog_131220_Content_6 = {
    Text = "Il balletto è la più pura delle danze sulla terra. Solo chi l'ha praticato comprende davvero la bellezza di quell'eleganza brutale!"
  },
  AvgDialog_131220_Content_7 = {
    Text = "Vedere la signorina Elizabeth esibirsi dal vivo è qualcosa che non avrei mai nemmeno sognato..."
  },
  AvgDialog_131220_Content_8 = {
    Text = "Il rumore di fondo della folla sfuma in un ronzio lontano."
  },
  AvgDialog_131220_Content_9 = {
    Text = "Ricordi questo prato, quel lago. Ricordi le diverse altezze degli edifici del campus e la scultura che fissa tenace l'orizzonte."
  },
  AvgDialog_131221_Content_1 = {
    Text = "Atto Secondo"
  },
  AvgDialog_131221_Content_10 = {
    Text = "Non sono che un Prigioniero del Destino; questo è un dovere che non ho altra Scelta se non adempiere."
  },
  AvgDialog_131221_Content_11 = {
    Text = "Per qualcuno che manipola i destini di innumerevoli mondi, forse \"giudice\" o \"Guardiano\" del Fato sarebbe un titolo più appropriato?"
  },
  AvgDialog_131221_Content_12 = {
    Text = "In questo luogo, non vi è differenza alcuna tra un Carceriere e un Prigioniero."
  },
  AvgDialog_131221_Content_13 = {
    Text = "Sig. William, il viaggio è stato confortevole?"
  },
  AvgDialog_131221_Content_14 = {
    Text = "Grazie all'aiuto della vostra Ancella. Se fossi stato lasciato a me stesso, eludere quegli Scudieri in agguato nell'ombra mi sarebbe costato assai di più."
  },
  AvgDialog_131221_Content_15 = {
    Text = "Nefraea... ti sei imbattuto di nuovo nella sua gente?"
  },
  AvgDialog_131221_Content_16 = {
    Text = "William annuisce solennemente."
  },
  AvgDialog_131221_Content_17 = {
    Text = "Quando ci siamo separati, mi sono imbattuto in alcuni passanti che sembravano... strani. Li ho pedinati per un po' e ho colto frammenti della loro conversazione."
  },
  AvgDialog_131221_Content_18 = {
    Text = "Stanno cercando qualcosa che chiamano \"Burattini\"."
  },
  AvgDialog_131221_Content_19 = {
    Text = "Sospetto che la contaminazione del Fato del Livello di cui parlavate prima possa essere soltanto una misura preliminare."
  },
  AvgDialog_131221_Content_2 = {
    Text = "Che spettacolo..."
  },
  AvgDialog_131221_Content_20 = {
    Text = "Quei \"Burattini\" sono il loro vero obiettivo."
  },
  AvgDialog_131221_Content_21 = {
    Text = "Mia sorella ha nascosto i propri Fili del Fato insieme a quelli dei suoi scudieri; non riesco a percepirli facilmente. Questa è un'informazione vitale, Signor William."
  },
  AvgDialog_131221_Content_22 = {
    Text = "Per la prossima fase, verrò con voi—"
  },
  AvgDialog_131221_Content_23 = {Text = "No!"},
  AvgDialog_131221_Content_24 = {
    Text = "No, devi restare! Separarci prima era una necessità, ma non voglio rischiare che si ripeta quanto accaduto a Remouahe."
  },
  AvgDialog_131221_Content_25 = {
    Text = "Il Custode ha ragione. La mia cameriera tratterà le tossine nel tuo organismo. Fino a completa guarigione, ti prego di restare nel teatro a riposarti."
  },
  AvgDialog_131221_Content_26 = {
    Text = "Il giorno in cui avremo davvero bisogno della vostra Possanza è ormai prossimo."
  },
  AvgDialog_131221_Content_27 = {
    Text = "Le parole di Arachne cadono come un verdetto sommesso, trafiggendo senza sforzo carne e Anima per insediarsi nella trama del Fato di William."
  },
  AvgDialog_131221_Content_28 = {
    Text = "William getta uno sguardo al Sangue che filtra attraverso le bende e annuisce lentamente."
  },
  AvgDialog_131221_Content_29 = {
    Text = "Se andassi ora, sarei solo un peso. Stai tranquillo, mi assicurerò di essere pronto quando quel giorno arriverà."
  },
  AvgDialog_131221_Content_3 = {
    Text = "<Shake:Coff, coff...>"
  },
  AvgDialog_131221_Content_30 = {
    Text = "Arachne accenna un lieve sorriso e tende la Mano. Uno, due... poi innumerevoli ragni strisciano fuori dalle sue maniche, discendendo al suolo lungo fili di seta."
  },
  AvgDialog_131221_Content_31 = {
    Text = "I ragni cadono come pioggia, convergendo e ammassandosi insieme. La massa di aracnidi si sovrappone formando una sagoma umana, mentre colore e luce aderiscono alla forma mutevole."
  },
  AvgDialog_131221_Content_32 = {
    Text = "In pochi istanti, una seconda Arachne, identica, si erge dinanzi a voi."
  },
  AvgDialog_131221_Content_33 = {
    Text = "Seguitemi, {Male=Sig.,Female=Sig.na} Custode. Credo che sia giunto il momento di un incontro faccia a faccia con mia sorella."
  },
  AvgDialog_131221_Content_34 = {Text = "..."},
  AvgDialog_131221_Content_35 = {
    Text = "Vi sono molti negozi in questa città che adoro, ma come voi, trovo che questo luogo sia tra i miei preferiti."
  },
  AvgDialog_131221_Content_36 = {
    Text = "Sedete al vostro posto abituale al Ballo di Mezzanotte, con la fronte aggrottata, osservando Arachne studiare ciò che la circonda."
  },
  AvgDialog_131221_Content_37 = {
    Text = "Quindi cosa saresti esattamente in questo momento? Un burattino? Un'esca? Una qualche misteriosa macchina fatta di un mucchio di ragni perché la vera te possa saltare la lezione?"
  },
  AvgDialog_131221_Content_38 = {
    Text = "In sostanza, la \"me\" qui e la \"me\" nel teatro sono lo stesso Fato; siamo due esperienze distinte che si dispiegano nello stesso istante."
  },
  AvgDialog_131221_Content_39 = {
    Text = "La maggior parte del mio Potere deve restare nel teatro per mantenere la Grande Tela. A parte questo, non c'è differenza tra noi. Non lasciare che la Diffidenza guasti l'atmosfera, Custode."
  },
  AvgDialog_131221_Content_4 = {
    Text = "Il suono agita la sua Ferita. William si stringe l'addome fasciato, incapace di sopprimere un violento accesso di tosse."
  },
  AvgDialog_131221_Content_40 = {
    Text = "Arachne offre un sorriso pacato, il ghiaccio tintinna sommessamente nel suo bicchiere mentre fa roteare il drink."
  },
  AvgDialog_131221_Content_41 = {
    Text = "Sapevi che questo locale ospita una mascherata ogni mese? A ogni Ospite che entra è richiesto di indossare la maschera più interessante che possieda."
  },
  AvgDialog_131221_Content_42 = {
    Text = "L'alta Società di solito rende questo posto noioso, ma in quella sola notte diventa l'angolo più affascinante della città."
  },
  AvgDialog_131221_Content_43 = {
    Text = "Forse per la prossima mascherata dovrei mettere tutto da parte e viverla davvero."
  },
  AvgDialog_131221_Content_44 = {
    Text = "Pensavo che qualcuno in grado di vedere l'intero arazzo del Fato perdesse ogni interesse per il futuro."
  },
  AvgDialog_131221_Content_45 = {
    Text = "È vero, %player%. Tuttavia, ho scoperto un modo per tenere a bada la noia molto tempo fa."
  },
  AvgDialog_131221_Content_46 = {
    Text = "A volte esco da dietro il sipario e salgo sul Livello stesso che ho creato, trasformandomi in uno dei personaggi."
  },
  AvgDialog_131221_Content_47 = {
    Text = "Mi acceco alla mia stessa preveggenza e mi abbandono alla rappresentazione. Mi lascio sentire il fluire del tempo e il mutare del destino..."
  },
  AvgDialog_131221_Content_48 = {
    Text = "È un raro momento di Riposo. Occasioni simili sono poche, perciò le custodisco ciascuna come una festività sacra."
  },
  AvgDialog_131221_Content_49 = {
    Text = "Arachne parla osservando con genuino interesse gli sfarzosi Ospiti e i premurosi camerieri. La luce ambrata del bar danza nei suoi Occhi."
  },
  AvgDialog_131221_Content_5 = {
    Text = "William?! Sei ferito!"
  },
  AvgDialog_131221_Content_50 = {
    Text = "Eppure... non dovremmo essere a caccia di quei \"Burattini\"? Perché siamo qui?"
  },
  AvgDialog_131221_Content_51 = {
    Text = "Una di loro è proprio qui. La vedrai presto... o meglio, l'hai già vista."
  },
  AvgDialog_131221_Content_52 = {
    Text = "Salve, cari clienti."
  },
  AvgDialog_131221_Content_53 = {
    Text = "La sua Voce è liscia come il miele. Le sue dita sembrano scolpite nella porcellana più fine. Il profumo luminoso di gelsomino e mimosa si aggrappa al suo collo scoperto, e i suoi Occhi scintillano di una luce penetrante, onniveggente."
  },
  AvgDialog_131221_Content_54 = {
    Text = "Ah, vi ricordo, l'elegante %player%."
  },
  AvgDialog_131221_Content_55 = {
    Text = "Mostri nelle ombre, un abbagliante fulgore d'Argento... che magnifica epopea eroica!"
  },
  AvgDialog_131221_Content_56 = {
    Text = "A dire il vero, mentre eri via, la Mascherata di Mezzanotte ha tratto un bel profitto dalla tua Storia. Ti dobbiamo dei diritti d'autore — come minimo, lascia che ti offriamo da bere."
  },
  AvgDialog_131221_Content_57 = {
    Text = "Sei tu... Per ora passo sul drink, ma potresti offrirne uno alla mia amica qui?"
  },
  AvgDialog_131221_Content_58 = {
    Text = "Ho già un nome per questo: \"L'Atto Solitario.\""
  },
  AvgDialog_131221_Content_59 = {
    Text = "Un bel nome. Quanto al fatto che si addica alla tua amica... dovrò guardarla più da vicino."
  },
  AvgDialog_131221_Content_6 = {
    Text = "Guidati da Arachne, varcate la parete anonima accanto al caffè Hvatz."
  },
  AvgDialog_131221_Content_60 = {
    Text = "La Doll conosciuta come \"Romance\" si sporge sul bancone del bar, fissando intensamente gli occhi di Arachne."
  },
  AvgDialog_131221_Content_61 = {
    Text = "L'umile Creatrice resta immersa nella propria esibizione. Arachne sorride e ne sostiene lo sguardo."
  },
  AvgDialog_131221_Content_62 = {
    Text = "Oh, che paio di occhi espressivi avete, mia signora."
  },
  AvgDialog_131221_Content_63 = {
    Text = "Sono come un oceano vasto e insondabile. Sepolti in quelle profondità invisibili giacciono segreti che nessuna anima ha mai conosciuto."
  },
  AvgDialog_131221_Content_64 = {
    Text = "Questo oceano inghiotte ogni onda furiosa. Per quanto violenta sia la tempesta, la superficie resta calma come lo è stata sin dall'alba dei tempi."
  },
  AvgDialog_131221_Content_65 = {
    Text = "Il tempo scorre, le stelle si spostano. Le montagne si sgretolano in pianure, e i mari si mutano in prati..."
  },
  AvgDialog_131221_Content_66 = {
    Text = "Ma sotto tutto questo mutamento... cosa ha rigettato questo oceano?"
  },
  AvgDialog_131221_Content_67 = {
    Text = "La barista si siede di fronte ad Arachne e le solleva il mento. Le sue unghie lunghe si posano naturalmente sulla carotide di Arachne."
  },
  AvgDialog_131221_Content_68 = {
    Text = "Questo è..."
  },
  AvgDialog_131221_Content_69 = {
    Text = "Dea del Fato, la grande Arachne. Quanta eleganza quando giocate col destino. Vi invidio davvero — coloro che avete scelto, coloro che avete tenuto con voi."
  },
  AvgDialog_131221_Content_7 = {
    Text = "Facendo Ritorno sul palcoscenico del teatro, notate immediatamente William, seduto da solo tra il pubblico."
  },
  AvgDialog_131221_Content_70 = {
    Text = "Peccato... alcune di noi sono nate solo per essere gettate via."
  },
  AvgDialog_131221_Content_71 = {
    Text = "...A quanto pare oggi non riuscirò ad assaggiare quel drink, dopotutto."
  },
  AvgDialog_131221_Content_72 = {
    Text = "Arachne non fa alcun gesto per sottrarsi a quella mano minacciosa. Sospira sommessamente, come a piangere memorie lontane... o forse solo il drink che non avrà mai."
  },
  AvgDialog_131221_Content_73 = {
    Text = "Puoi corrompere i fili di queste Doll per offuscare la mia visuale, Nefraea, ma è futile. Non hai il potere di controllare il Fato."
  },
  AvgDialog_131221_Content_74 = {
    Text = "Come una bambola fatta di crema nera che si scioglie, la pelle della barista si stacca dal corpo in un ammasso fangoso."
  },
  AvgDialog_131221_Content_75 = {
    Text = "Sotto la lordura, un volto familiare si rivela."
  },
  AvgDialog_131221_Content_76 = {Text = "Sei tu?!"},
  AvgDialog_131221_Content_77 = {
    Text = "Mia cara sorella. Ti restano così poche Braci Dimensionali da bruciare."
  },
  AvgDialog_131221_Content_78 = {
    Text = "Mi piacerebbe avere un vero dialogo a cuore aperto, ma per ora lascerò che i miei piccoli ragni ti diano il benvenuto al posto mio."
  },
  AvgDialog_131221_Content_79 = {
    Text = "Attento alle spalle!"
  },
  AvgDialog_131221_Content_8 = {
    Text = "È solo un graffio."
  },
  AvgDialog_131221_Content_9 = {
    Text = "Ho assistito al destino che si è dispiegato su quel Livello. Credo che qualcuno vi debba un tributo di gratitudine per i vostri sforzi, Lady Arachne."
  },
  AvgDialog_131222_Content_1 = {
    Text = "L'invito del Maniero"
  },
  AvgDialog_131222_Content_10 = {
    Text = "Un invito? Ho vissuto tutta la mia vita senza mai dover mostrare un pezzo di carta per entrare in una stanza."
  },
  AvgDialog_131222_Content_100 = {
    Text = "Sorel socchiude gli occhi, un raro lampo di rabbia che si accende nel suo sguardo."
  },
  AvgDialog_131222_Content_101 = {
    Text = "Non so cosa abbiate fatto a Karen, ma non importa. Il vostro prezzo è già stato fissato."
  },
  AvgDialog_131222_Content_102 = {
    Text = "Ah, una trattativa fallita. Che tragedia, Lady Sorel. A quanto pare dovrò estrarre le risposte dal vostro cadavere."
  },
  AvgDialog_131222_Content_103 = {
    Text = "Sorel aggrotta la fronte, percependo le potenti increspature psichiche che emanano dall'avversario. Ombre d'inchiostro si chiudono rapidamente, sigillando ogni via di fuga."
  },
  AvgDialog_131222_Content_105 = {
    Text = "Proprio mentre una lama si lancia dall'oscurità, una striscia di luce argentea irrompe nella stanza come una stella cadente."
  },
  AvgDialog_131222_Content_106 = {
    Text = "Sorel, indietro!"
  },
  AvgDialog_131222_Content_11 = {
    Text = "Fatti da parte."
  },
  AvgDialog_131222_Content_12 = {
    Text = "Le porgo le mie scuse, signore. Il banchetto di stasera è riservato esclusivamente a chi possiede un invito."
  },
  AvgDialog_131222_Content_13 = {
    Text = "Sciocco cieco. Hai idea di chi io sia?"
  },
  AvgDialog_131222_Content_14 = {
    Text = "Non è affar mio, signore."
  },
  AvgDialog_131222_Content_15 = {
    Text = "Dal suo accento sembra del posto, signore. Presumo che comprenda un inglese semplice."
  },
  AvgDialog_131222_Content_16 = {
    Text = "Ma come si permette—!! Bene! Mi assicurerò che lei e la padrona di questa casa la paghiate cara!"
  },
  AvgDialog_131222_Content_17 = {
    Text = "Arachne osserva il nobile allontanarsi furioso e scuote la testa."
  },
  AvgDialog_131222_Content_18 = {
    Text = "Sembra che ottenere accesso a questo maniero sarà più difficile di quanto avessi previsto."
  },
  AvgDialog_131222_Content_19 = {
    Text = "Se riuscissi a trovare quell'ancella che vende acqua da bagno, forse potrei comprare un paio di inviti da lei..."
  },
  AvgDialog_131222_Content_2 = {
    Text = "La Tenuta del Duca di Cadrin si erge come il luogo mondano più prestigioso della vecchia Londinium."
  },
  AvgDialog_131222_Content_20 = {
    Text = "Rari sali marini di Thira, lavanda, agrumi, chiodi di garofano e petali di rosa dal sud di Constan..."
  },
  AvgDialog_131222_Content_21 = {
    Text = "Un'acqua da bagno simile è ben più preziosa — e più difficile da trovare — di un semplice invito."
  },
  AvgDialog_131222_Content_22 = {Text = "???"},
  AvgDialog_131222_Content_23 = {
    Text = "Stavo solo parlando tra me e me... come potresti sapere cosa è accaduto nei miei sogni?"
  },
  AvgDialog_131222_Content_24 = {
    Text = "Sebbene il tuo Fato resti celato ai miei occhi, ho sempre osservato i destini di coloro che ti circondano."
  },
  AvgDialog_131222_Content_25 = {
    Text = "Se controlli i loro destini, di certo puoi gestire qualcosa di così piccolo come materializzare due inviti? Anche se le increspature sono complicate?"
  },
  AvgDialog_131222_Content_26 = {
    Text = "Hai già visto il Caos che segue a un mutamento del destino. Il Fato non è un giocattolo; è una Casa di vetro che richiede la mia costante e attenta manutenzione."
  },
  AvgDialog_131222_Content_27 = {
    Text = "Ogni Scelta che compio richiede un'immensa concentrazione e Braci dimensionali. Una sola svista potrebbe portare al collasso totale."
  },
  AvgDialog_131222_Content_28 = {
    Text = "E poi... come ho già detto, essere spettatori è spesso molto più divertente che essere drammaturghi."
  },
  AvgDialog_131222_Content_29 = {
    Text = "Non vedo l'ora di assistere alla tua esibizione, %player%."
  },
  AvgDialog_131222_Content_3 = {
    Text = "Nel suo splendore, il Primo Ministro e i funzionari di gabinetto sedevano ai tavoli del giardino, vergando decreti che plasmavano il fato stesso dell'impero."
  },
  AvgDialog_131222_Content_30 = {
    Text = "Ma non so assolutamente nulla di questo luogo..."
  },
  AvgDialog_131222_Content_31 = {
    Text = "Recitare, ingannare, intrattenere... porti quei poteri dentro di te. Il palcoscenico del Fato raramente concede tempo per una Prova generale. Quando il momento verrà, quel Potere ti sosterrà."
  },
  AvgDialog_131222_Content_32 = {
    Text = "Non puoi sfuggire ai ruoli che eri destinato a interpretare. Rifletti, poi recita, {Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_131222_Content_33 = {
    Text = "Una tagliente serietà guizza dietro il sorriso cortese di Arachne. Ti parla, eppure I Suoi Occhi sembrano trapassare la tua figura, rivolgendosi a un futuro ben oltre questo istante."
  },
  AvgDialog_131222_Content_34 = {
    Text = "Le sue parole portano il peso di un comando a cui non puoi sottrarti. Un comando del tuo Fato. Abbassi lo sguardo, riflettendo sul suo significato."
  },
  AvgDialog_131222_Content_35 = {
    Text = "Recitare, ingannare, intrattenere... intendi l'Autorità di N?"
  },
  AvgDialog_131222_Content_36 = {
    Text = "Ma dalla Battaglia finale con Tohuwabohu, ho perso la mia connessione con il Potere dei Tre Eoni..."
  },
  AvgDialog_131222_Content_37 = {
    Text = "Il loro Potere è in Dormiveglia, sì. Ma l'Autorità è ben più di semplice Potere grezzo."
  },
  AvgDialog_131222_Content_38 = {
    Text = "L'Autorità è più del Potere..."
  },
  AvgDialog_131222_Content_39 = {
    Text = "Mentre rifletti sulle sue parole, una scintilla d'Ispirazione illumina la tua mente."
  },
  AvgDialog_131222_Content_4 = {
    Text = "Nella sua rovina, la tenuta venduta restò come un testimone silenzioso, osservando la sua figura curva condotta verso il patibolo."
  },
  AvgDialog_131222_Content_40 = {
    Text = "Cogli due foglie d'acero cadute dall'erba. Le loro venature, sotto i polpastrelli, sembrano quasi pergamena stampata."
  },
  AvgDialog_131222_Content_41 = {
    Text = "Hai detto che tutti in questo mondo portano un Nucleo d'Argento. Significa che le loro menti sono aperte all'influenza della mia Chiave d'Argento... giusto?"
  },
  AvgDialog_131222_Content_42 = {
    Text = "Arachne accenna un sorriso e si affianca a te mentre vi avvicinate ai cancelli della tenuta."
  },
  AvgDialog_131222_Content_43 = {
    Text = "Buonasera. Prego, mostri il suo—"
  },
  AvgDialog_131222_Content_44 = {
    Text = "Che tenuta magnifica. Siamo onorati di accettare l'invito di Lady Sorel."
  },
  AvgDialog_131222_Content_45 = {
    Text = "Mentre porgi alla Guardia le foglie d'acero, la Chiave d'Argento emette un debole bagliore nella tua tasca. Agganci con facilità il punto di luce della Guardia."
  },
  AvgDialog_131222_Content_46 = {
    Text = "Simultaneamente, un'altra luce tremola nella tua mente. Nel punto d'incontro di quei due punti di luce, il fantasma di Clementine appare, oscillando il suo pendolo."
  },
  AvgDialog_131222_Content_47 = {
    Text = "C-Conte Huey..."
  },
  AvgDialog_131222_Content_48 = {
    Text = "Ah! Conte Huey, Contessa! La Tenuta Cadrin è onorata dalla vostra presenza."
  },
  AvgDialog_131222_Content_49 = {
    Text = "Sotto lo sguardo rispettoso della Guardia, metti piede sul levigato sentiero di ciottoli della tenuta."
  },
  AvgDialog_131222_Content_5 = {
    Text = "Dopo un breve periodo di lutto, la tenuta si riempie ancora una volta di ospiti illustri. La sua nuova proprietaria tiene salone dopo salone, proclamando a gran voce il ritorno alla gloria della residenza."
  },
  AvgDialog_131222_Content_50 = {
    Text = "Che effetto fa, {Male=Sig.,Female=Sig.na} Custode?"
  },
  AvgDialog_131222_Content_51 = {
    Text = "Ancora non afferro del tutto cosa intendi per \"Autorità\", ma ho decisamente sentito qualcosa cambiare poco fa..."
  },
  AvgDialog_131222_Content_52 = {
    Text = "È stata... un'ebbrezza. Un'ondata di eccitazione per averli ingannati — per aver fatto loro credere che fossi il Conte. Non ho mai provato nulla di simile. Era come se quell'emozione non mi appartenesse nemmeno."
  },
  AvgDialog_131222_Content_53 = {
    Text = "Apri la Mano, lasciando che le due foglie d'acero scivolino dalle dita per danzare via nella brezza."
  },
  AvgDialog_131222_Content_54 = {
    Text = "Mentre tu e Arachne entrate nella tenuta con sorrisi composti, giureresti di udire una risatina divertita riecheggiare dal profondo del tuo petto."
  },
  AvgDialog_131222_Content_55 = {Text = "..."},
  AvgDialog_131222_Content_56 = {
    Text = "È davvero notevole vedere qualcuno raggiungere così tanto in così giovane età."
  },
  AvgDialog_131222_Content_57 = {
    Text = "Una volta concluse queste trattative commerciali, i legami tra l'Élite imprenditoriale e politica di questa città saranno completamente trasformati. È un'opportunità rara..."
  },
  AvgDialog_131222_Content_58 = {
    Text = "Il capo ha passato l'Inferno per ottenere questi inviti. Dobbiamo fare degli scatti perfetti. Tieni l'attrezzatura pronta e seguimi — dobbiamo avvicinarci il più possibile alla prima fila..."
  },
  AvgDialog_131222_Content_59 = {
    Text = "È qui! Sta uscendo!!"
  },
  AvgDialog_131222_Content_6 = {
    Text = "Buonasera. Ecco il mio invito."
  },
  AvgDialog_131222_Content_60 = {
    Text = "Al grido del Giovane Uomo, la Folla si riversa verso le porte che si aprono."
  },
  AvgDialog_131222_Content_61 = {
    Text = "Una dama in un abito Cremisi appare, simile a una rosa in fiore. La sua presenza fa sembrare spenti, al confronto, il sontuoso arredamento e la Folla brulicante."
  },
  AvgDialog_131222_Content_62 = {
    Text = "Sorel sfoggia un sorriso impeccabile e studiato, salutando gli ospiti con disinvoltura naturale."
  },
  AvgDialog_131222_Content_63 = {
    Text = "Quindi, è lei l'attuale proprietaria della tenuta..."
  },
  AvgDialog_131222_Content_64 = {
    Text = "Signore e signori, Benvenuto. Al salone di oggi, diversi quartieri commerciali della nostra città troveranno i loro nuovi padroni."
  },
  AvgDialog_131222_Content_65 = {
    Text = "E, naturalmente, i nostri nobili amici riceveranno i benefici che così giustamente meritano."
  },
  AvgDialog_131222_Content_66 = {
    Text = "Confido che questa sarà una serata quanto mai splendida e deliziosa."
  },
  AvgDialog_131222_Content_67 = {
    Text = "I miei chef hanno preparato le migliori paste e champagne. Prego, godetevi un momento di svago. Il servizio di cena inizierà a breve."
  },
  AvgDialog_131222_Content_68 = {
    Text = "Sorel scruta la stanza con un sorriso, poi si volta per salire al piano superiore."
  },
  AvgDialog_131222_Content_69 = {
    Text = "Sor... Sorel! Karen!"
  },
  AvgDialog_131222_Content_7 = {
    Text = "Ah, benvenuto, Sig. Fugen. La Signora vi attende. Prego, accomodatevi pure."
  },
  AvgDialog_131222_Content_70 = {
    Text = "La vostra voce è divorata dalle chiacchiere e dagli applausi della folla."
  },
  AvgDialog_131222_Content_71 = {
    Text = "Lady Sorel! Lady Sorel! Come intendete suddividere i distretti commerciali? Questo influenzerà..."
  },
  AvgDialog_131222_Content_72 = {
    Text = "Shh, signor reporter. Sono appena tornata da un impegno. Non appena avrò avuto modo di cambiarmi, risponderò a tutte le vostre domande."
  },
  AvgDialog_131222_Content_73 = {
    Text = "Sorel rivolge un ultimo cenno di saluto prima di scomparire negli alloggi privati al piano superiore."
  },
  AvgDialog_131222_Content_74 = {
    Text = "Sembra che dovremo aspettare che torni fuori."
  },
  AvgDialog_131222_Content_75 = {
    Text = "Hai notato l'ancella accanto a Sorel?"
  },
  AvgDialog_131222_Content_76 = {
    Text = "Karen? Sì, nemmeno lei sembrava sentirmi... aspetta, cosa stai dicendo?"
  },
  AvgDialog_131222_Content_77 = {
    Text = "Richiamate alla mente l'aura di Karen. Era del tutto sbagliata — anche tenendo conto di dimensioni differenti, quella presenza non poteva in alcun modo appartenere alla bambina che conoscevate."
  },
  AvgDialog_131222_Content_78 = {
    Text = "Percepisco in lei un sentiero del fato che non appartiene a questo livello. Il suo destino è stato contaminato."
  },
  AvgDialog_131222_Content_79 = {
    Text = "Lady Sorel è in pericolo!"
  },
  AvgDialog_131222_Content_8 = {
    Text = "Hmph. Quando mercanti avidi di denaro come Fugen possono entrare indisturbati nella residenza del vecchio Duca, si capisce che la grazia di Londinium è davvero svanita..."
  },
  AvgDialog_131222_Content_80 = {
    Text = "Vi fate largo tra la folla, trovando una scala di servizio nascosta sul retro dell'edificio."
  },
  AvgDialog_131222_Content_81 = {
    Text = "Le mie scuse, {Male=signore,Female=signora}, ma questa è la residenza privata di Lady Sorel. Nessun accesso non autorizzato—"
  },
  AvgDialog_131222_Content_82 = {
    Text = "Lady Sorel mi ha invitato qui per discutere una questione urgente in privato."
  },
  AvgDialog_131222_Content_83 = {
    Text = "Estraete un tovagliolo appena sottratto da un tavolo. Con un lampo d'argento, un tesserino del Comitato del trattato di Mystia appare nella vostra mano."
  },
  AvgDialog_131222_Content_84 = {
    Text = "Perdonatemi, {Male=signore,Female=signora}, non sapevo... Lady Sorel è appena al piano di sopra. Posso condurvi—"
  },
  AvgDialog_131222_Content_85 = {
    Text = "Questa è una missione confidenziale. Non dite a nessuno che ero qui."
  },
  AvgDialog_131222_Content_86 = {
    Text = "Vi lanciate su per le scale prima che l'ufficiale possa proferire un'altra parola."
  },
  AvgDialog_131222_Content_87 = {Text = "..."},
  AvgDialog_131222_Content_88 = {
    Text = "Il vostro abito è pronto, Lady Sorel!"
  },
  AvgDialog_131222_Content_89 = {
    Text = "Londinium è una terra selvaggia. I politici e i mercanti sono le iene di questa città..."
  },
  AvgDialog_131222_Content_9 = {
    Text = "Buonasera, signore. La prego di presentare il suo invito."
  },
  AvgDialog_131222_Content_90 = {
    Text = "Sorel prende l'abito preparato da Karen. La luce del sole filtra attraverso la garza rossa, proiettando una vivida ombra cremisi nella sontuosa camera da letto."
  },
  AvgDialog_131222_Content_91 = {
    Text = "Anche le iene hanno il loro fascino. Un solo pezzo di carogna basta a farle accorrere. Avide, acute, spietate e ingenue: non esiste arma migliore."
  },
  AvgDialog_131222_Content_92 = {
    Text = "Là fuori stanno perdendo la pazienza. Sei apparsa molto in ritardo oggi, e questo vestito costoso è stato macchiato."
  },
  AvgDialog_131222_Content_93 = {
    Text = "Avreste dovuto tornare prima, signora."
  },
  AvgDialog_131222_Content_94 = {
    Text = "Sorel si blocca a metà del gesto. Abbassa l'orlo cremisi della gonna e studia l'espressione placida di Karen."
  },
  AvgDialog_131222_Content_95 = {
    Text = "Qualcuno avrebbe dovuto insegnarti come una serva si rivolge alla sua Signora. Cosa ti è preso oggi?"
  },
  AvgDialog_131222_Content_96 = {
    Text = "Lady Sorel, portate addosso la lordura del Distretto Est. Sono curiosa: dove avete mandato quel gentile gentiluomo?"
  },
  AvgDialog_131222_Content_97 = {
    Text = "La stanza luminosa si oscura per un battito di cuore. Diversi ragni neri emergono dalle ombre, coalizzandosi in forme umane che circondano Sorel."
  },
  AvgDialog_131222_Content_98 = {
    Text = "Avete una serva molto leale, Lady Sorel. Nonostante la sua predilezione per rubare e svendere i vostri beni, la sua devozione alla vostra sicurezza è fuori discussione."
  },
  AvgDialog_131222_Content_99 = {
    Text = "Ancora adesso, la sua volontà combatte ferocemente contro di me. Un peccato, davvero: nessun mortale può resistere al potere del Fato."
  },
  AvgDialog_131223_Content_1 = {
    Text = "Fato. Fato selvaggio, vuoto, miserabile. I Fati Abbandonati non sanno da dove vengono, né dove vanno."
  },
  AvgDialog_131223_Content_10 = {
    Text = "La voce di Nefraea diventa stridula. Una luce fioca divampa mentre fili cremisi la stringono, le braci morenti della Lanterna le bruciano la carne."
  },
  AvgDialog_131223_Content_11 = {
    Text = "Enormi artigli scattano nell'aria. Ti fissa con un sorriso attraverso un paio di giganteschi occhi composti da cui cola una melma nera. Fili Cremisi avvolgono il suo corpo, fluttuando nelle correnti del vortice del Fato."
  },
  AvgDialog_131223_Content_12 = {
    Text = "Accanto a lei, il filatoio spezzato dove i fili convergono gira lentamente e inarrestabilmente, strangolando i palcoscenici, strangolando Nefraea stessa."
  },
  AvgDialog_131223_Content_13 = {Text = "Huhhh—"},
  AvgDialog_131223_Content_14 = {
    Text = "Ti stringi la testa in preda all'agonia. Mentre la ruota gira, il tuo Mondo degli spiriti ribolle e si agita. Ansimi per respirare, lottando per dominare il dolore intenso."
  },
  AvgDialog_131223_Content_15 = {
    Text = "Accanto a Nefraea, i frammenti del passaggio dimensionale sono quasi esauriti. I fili sul tuo corpo — le trame simili a quelle di una marionetta — si fanno sempre più nitidi."
  },
  AvgDialog_131223_Content_16 = {
    Text = "Il potere del passaggio... lo ha quasi completamente assorbito!"
  },
  AvgDialog_131223_Content_17 = {
    Text = "Braci lilla sgorgano incessantemente dal corpo di Arachne, volando come falene verso la Tela del Fato ormai quasi distrutta."
  },
  AvgDialog_131223_Content_18 = {
    Text = "Le mani di Arachne tremano mentre gira il suo filatoio a un ritmo eterno e immutabile. La sua voce resta calma come il primo giorno in cui vi siete incontrati."
  },
  AvgDialog_131223_Content_19 = {
    Text = "L'hai visto. Questa è l'intersezione del Fato, Nefraea."
  },
  AvgDialog_131223_Content_2 = {
    Text = "Sono trascinati da fili di seta, si riversano verso di te, solo per dissolversi in pozze di melma nera nella tua radiosità argentea."
  },
  AvgDialog_131223_Content_20 = {
    Text = "Tutti gli errori giungono a termine qui."
  },
  AvgDialog_131223_Content_21 = {
    Text = "Che dichiarazione sicura, Signora Prigioniera. Allora mostrami come fermerai una dea. Mostrami come fermi il Fato stesso..."
  },
  AvgDialog_131223_Content_22 = {
    Text = "Un sorriso maniacale sboccia sul volto di Nefraea. I fili la sollevano in aria. Su questo palcoscenico in frantumi, lei è l'unica luce."
  },
  AvgDialog_131223_Content_23 = {
    Text = "\"Venite, voi fedeli striscianti del mondo! Chinate il capo e prosternatevi dinanzi a me!\""
  },
  AvgDialog_131223_Content_24 = {
    Text = "\"L'Esaltata è discesa dal trono celeste! La Fine Ineluttabile si rivela qui e ora!\""
  },
  AvgDialog_131223_Content_25 = {
    Text = "\"Quel falso destino — accogliamone insieme la distruzione!\""
  },
  AvgDialog_131223_Content_3 = {
    Text = "Questa melma è selvaggia, vuota e miserabile — proprio come i loro destini."
  },
  AvgDialog_131223_Content_4 = {
    Text = "Nefraea non vi presta attenzione. Ha osservato questa scena ripetersi per un'eternità; vi si è abituata da tempo."
  },
  AvgDialog_131223_Content_5 = {
    Text = "Ora lo vedo chiaramente. Quelle immagini che hai visto, tutto ciò di cui sei stato/a testimone... finalmente vedo tutto."
  },
  AvgDialog_131223_Content_6 = {
    Text = "Si è ormai assuefatta al dolore dei frammenti conficcati nella sua pelle. Un sorriso le affiora sulle labbra mentre fissa il vuoto caotico del teatro."
  },
  AvgDialog_131223_Content_7 = {
    Text = "Orgogliosa, compassionevole, indifferente... per un istante, quasi non riesci a distinguerla da Arachne."
  },
  AvgDialog_131223_Content_8 = {
    Text = "Solo chi è dentro la gabbia può davvero aprirla. Il caos e la distruzione che vedi non sono la verità del Fato, Nefraea..."
  },
  AvgDialog_131223_Content_9 = {
    Text = "Heh... hahaha! È così che ti sei ingannata per tutti questi anni, Arachne?"
  },
  AvgDialog_131224_Content_1 = {
    Text = "Pubblico, Giocatore, Autore"
  },
  AvgDialog_131224_Content_10 = {
    Text = "Questo è...!"
  },
  AvgDialog_131224_Content_100 = {
    Text = "Andate, Fanciulli miei. Trovate %player%."
  },
  AvgDialog_131224_Content_101 = {
    Text = "Impadronisciti del {Male=suo,Female=suo} potere, recidi ogni filo del Fato e riduci la Grande Tela in brandelli! Che ogni anima che si frappone sul nostro cammino vi perisca!"
  },
  AvgDialog_131224_Content_102 = {
    Text = "Useremo il sangue di questo frammento per risvegliare ancora una volta il Grande Primordiale."
  },
  AvgDialog_131224_Content_103 = {
    Text = "Quando vedrai la tua preziosa Trama del Fato frantumata e ridotta a una palude di lordura, sprofonderai nel Vuoto infinito proprio come noi?"
  },
  AvgDialog_131224_Content_104 = {
    Text = "Dea del Fato... cara sorella mia... mia amata <Red:Arachne>?"
  },
  AvgDialog_131224_Content_105 = {
    Text = "Il confine tra il palcoscenico e il pubblico sembra svanire; lo spazio stesso perde ogni significato."
  },
  AvgDialog_131224_Content_106 = {
    Text = "Tra le sue risate stridenti, la marionetta sembra trovarsi proprio davanti a te, fissando dritto negli occhi di Arachne."
  },
  AvgDialog_131224_Content_107 = {
    Text = "La luce si affievolisce e il sipario cala. La marionetta e le sue risate svaniscono, lasciando il teatro vuoto nel Silenzio, rotto soltanto dal lieve e ritmico ronzio dell'arcolaio."
  },
  AvgDialog_131224_Content_108 = {
    Text = "Mi perdoni, non comprendo bene... cos'è esattamente il \"Fato Abbandonato\"?"
  },
  AvgDialog_131224_Content_109 = {
    Text = "Come potete vedere, il Fato è un groviglio caotico di fili grezzi. Se lasciato a sé stesso, l'universo precipiterebbe in un Caos senza fondo. Credo sia uno spettacolo che nessuno di noi desideri contemplare."
  },
  AvgDialog_131224_Content_11 = {
    Text = "Non appena varcate la soglia, la porta alle vostre spalle svanisce."
  },
  AvgDialog_131224_Content_110 = {Text = "Certo..."},
  AvgDialog_131224_Content_111 = {
    Text = "È mio eterno dovere tessere quei fili nella Trama del Fato, assicurando che l'universo funzioni come dovrebbe."
  },
  AvgDialog_131224_Content_112 = {
    Text = "In ogni istante, il Fato racchiude infinite possibilità. In ogni istante, sono costretta a compiere una Scelta."
  },
  AvgDialog_131224_Content_113 = {
    Text = "I destini corretti vengono intessuti nella Grande Trama; quelli errati vengono scartati. È così che la trama funziona. È inevitabile."
  },
  AvgDialog_131224_Content_114 = {
    Text = "Mia sorella... è una parte di me che ho scartato tra quelle svolte errate del Fato."
  },
  AvgDialog_131224_Content_115 = {
    Text = "Arachne continua a sorridere. Mentre parla, non riesci a percepire neppure la minima increspatura di emozione nella sua Voce."
  },
  AvgDialog_131224_Content_116 = {
    Text = "E questi fati abbandonati... vengono inviati alla \"Prigione Abissale\"?"
  },
  AvgDialog_131224_Content_117 = {
    Text = "I sogni della Divinità Suprema costituiscono la sostanza di questo universo. La Prigione Abissale è il subconscio di quel Dio — una discarica per ogni evento mai accaduto e ogni fato che non esiste."
  },
  AvgDialog_131224_Content_118 = {
    Text = "Avrebbero dovuto dissolversi nel nulla in quel Vuoto, ma sotto la guida di mia sorella, hanno trovato in qualche modo un modo per sopravvivere."
  },
  AvgDialog_131224_Content_119 = {
    Text = "Arachne fissa l'immenso sipario, guardando attraverso di esso verso la marionetta che rappresenta Nefraea."
  },
  AvgDialog_131224_Content_12 = {
    Text = "Dove vi aspettavate un interno angusto si estende un vasto, sconfinato spazio dimensionale."
  },
  AvgDialog_131224_Content_120 = {
    Text = "Non sa tessere il destino come faccio io. Ma come me, può vedere i fili. Li oscura, li contamina e sconvolge le traiettorie che ho tracciato, conducendoli verso la morte."
  },
  AvgDialog_131224_Content_121 = {
    Text = "Dunque vuole trovarmi e usare il mio Potere per risvegliare Tohuwabohu?"
  },
  AvgDialog_131224_Content_122 = {
    Text = "Non posso conoscere il suo piano specifico, ma tutti i segni indicano quello. In ogni caso, è un errore che devo rettificare."
  },
  AvgDialog_131224_Content_123 = {
    Text = "Ecco perché ha chiuso il varco dimensionale..."
  },
  AvgDialog_131224_Content_124 = {
    Text = "No, sono stata io a chiudere il varco. Lei ha atteso proprio questo momento — attendeva di seguirti fino a Kadath."
  },
  AvgDialog_131224_Content_125 = {
    Text = "Kadath è una Dimensione che il mio Potere non ha mai raggiunto. È anche il luogo in cui la connessione con la Divinità Suprema è più forte."
  },
  AvgDialog_131224_Content_126 = {
    Text = "Se dovesse seguirti fin laggiù, la catastrofe diverrebbe inevitabile."
  },
  AvgDialog_131224_Content_127 = {
    Text = "Perdonami per essermi presa tali libertà, {Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_131224_Content_128 = {
    Text = "Capisco, Arachne. Se ciò che dici è vero, nemmeno io desidero che accada."
  },
  AvgDialog_131224_Content_129 = {
    Text = "Quindi, se voglio tornare a Kadath, devo prima occuparmi di lei..."
  },
  AvgDialog_131224_Content_13 = {
    Text = "Innumerevoli palcoscenici fluttuano come Stelle in questa distesa oscura, e su ciascuno di essi marionette recitano le proprie battute."
  },
  AvgDialog_131224_Content_130 = {
    Text = "Mia signora, è stata rilevata un'anomalia sul Livello nell'Area GI-9849. È la terza oggi."
  },
  AvgDialog_131224_Content_131 = {
    Text = "Da quando ha rubato i materiali per la tessitura, ha trovato gioia infinita nel disfare i destini altrui."
  },
  AvgDialog_131224_Content_132 = {
    Text = "Le mie scuse, %player%, ma devo occuparmi di questi disordini. Ti prego, vieni con me. Ci sono questioni vitali che devi vedere."
  },
  AvgDialog_131224_Content_133 = {
    Text = "Arachne scuote il capo con un sorriso stanco. Ti fa cenno di seguirla, raccoglie il suo filatoio e si alza."
  },
  AvgDialog_131224_Content_134 = {Text = "..."},
  AvgDialog_131224_Content_135 = {
    Text = "Questo... questo è il Livello che è stato distrutto?"
  },
  AvgDialog_131224_Content_136 = {
    Text = "Seguendo un Sentiero tessuto di seta di ragno, raggiungi un Livello fatiscente. All'interno di un caffè improvvisato sulla scena, alcune persone dall'aspetto di studenti sono rannicchiate insieme, sussurrando."
  },
  AvgDialog_131224_Content_137 = {
    Text = "Ultimamente, ha inviato i suoi Scudieri a sabotare i destini di questi mondi. Le mie Ancelle li hanno braccati, ma le Battaglie sono costate la vita a molti dei miei valenti Fanciulli."
  },
  AvgDialog_131224_Content_138 = {
    Text = "I destini di tutti i mondi sono legati alla stessa Grande Tela. Se un mondo crolla, lacera l'intera struttura, precipitando l'esistenza in un disordine assoluto e fatale."
  },
  AvgDialog_131224_Content_139 = {
    Text = "Nefraea ha rubato le materie prime che uso per la tessitura, impedendomi di esercitare liberamente il mio Potere. {Male=Sig.,Female=Sig.na} Custode, mi chiedo... saresti disposto ad aiutarmi a ripristinare il Fato di questo mondo?"
  },
  AvgDialog_131224_Content_14 = {
    Text = "Le parole vi giungono da lontano, simili al mormorio di innumerevoli devoti in Preghiera."
  },
  AvgDialog_131224_Content_140 = {
    Text = "Se la tua Storia è vera, allora lei è un problema di cui devo occuparmi in ogni caso."
  },
  AvgDialog_131224_Content_141 = {
    Text = "Arachne ti rivolge un cenno di gratitudine. Solleva la Mano e pizzica delicatamente i fili nascosti sospesi nell'aria vuota."
  },
  AvgDialog_131224_Content_142 = {Text = "CLANG—"},
  AvgDialog_131224_Content_143 = {
    Text = "Dopo un acuto tintinnio musicale, la voce melodiosa dell'annunciatrice risuona come un eterno ruscello che sfocia in una pozza profonda."
  },
  AvgDialog_131224_Content_144 = {
    Text = "Le trombe suonano un Rigoglio. In scena: lo Studente e l'Erudito!"
  },
  AvgDialog_131224_Content_145 = {
    Text = "Arachne compie un gesto ampio e invitante verso il Livello."
  },
  AvgDialog_131224_Content_146 = {
    Text = "È tempo del nostro ingresso in scena, %player%."
  },
  AvgDialog_131224_Content_147 = {
    Text = "Annuisci. Al richiamo dell'annunciatore, due marionette salgono sul palco che è stato preparato per loro."
  },
  AvgDialog_131224_Content_15 = {
    Text = "Fili di seta si dipartono da ogni marionetta e palcoscenico, convergendo insieme al sentiero di seta intrecciata sotto i vostri piedi verso l'unico palcoscenico al centro esatto di questo spazio."
  },
  AvgDialog_131224_Content_16 = {
    Text = "Vi voltate. L'Ancella vi ha già preceduto."
  },
  AvgDialog_131224_Content_17 = {
    Text = "Che strano Benvenuto..."
  },
  AvgDialog_131224_Content_18 = {
    Text = "Esitate, poi vi incamminate lungo il sentiero simile a una ragnatela verso il palcoscenico centrale. Mentre oltrepassate i palcoscenici sospesi, Frammenti di conversazione vi giungono all'orecchio."
  },
  AvgDialog_131224_Content_19 = {
    Text = "Mio caro cliente, vedo Confusione nei tuoi Occhi."
  },
  AvgDialog_131224_Content_2 = {
    Text = "Ho un'altra domanda..."
  },
  AvgDialog_131224_Content_20 = {
    Text = "Spero che l'incidente di poco fa non vi abbia spaventato troppo?"
  },
  AvgDialog_131224_Content_21 = {
    Text = "Una base di gin con un tocco di ibisco—credo si adatterebbe perfettamente al vostro umore in questo momento."
  },
  AvgDialog_131224_Content_22 = {Text = "..."},
  AvgDialog_131224_Content_23 = {
    Text = "Ah! Un bimbo senza tetto, così piccolo, così smarrito."
  },
  AvgDialog_131224_Content_24 = {
    Text = "Con nient'altro che quegli abiti leggeri, come pensate di superare l'inverno?"
  },
  AvgDialog_131224_Content_25 = {
    Text = "Vieni con me. Lascia che ti trovi un riparo dalla tempesta..."
  },
  AvgDialog_131224_Content_26 = {Text = "..."},
  AvgDialog_131224_Content_27 = {
    Text = "Questi... sono le persone in cui mi sono appena imbattuto?"
  },
  AvgDialog_131224_Content_28 = {
    Text = "Come sono finiti su questi Livelli..."
  },
  AvgDialog_131224_Content_29 = {
    Text = "Un agente in pattuglia, un impiegato che legge il giornale, un conducente che osserva la strada, amanti che comprano fiori, nobili nel mezzo di una conversazione..."
  },
  AvgDialog_131224_Content_3 = {
    Text = "Questa è già la vostra ventitreesima Domanda, %player%."
  },
  AvgDialog_131224_Content_30 = {
    Text = "Coloro che avete incontrato e coloro che non incontrerete mai—tutti intenti a recitare le proprie storie su innumerevoli palcoscenici. Su ciascuno dei propri palcoscenici, ognuno di loro è il protagonista."
  },
  AvgDialog_131224_Content_31 = {
    Text = "Ave, %player%! Benedetto sia, Infante di Yakutsk!"
  },
  AvgDialog_131224_Content_32 = {
    Text = "Ave, %player%! Benedetto sia, Custode di Mythag!"
  },
  AvgDialog_131224_Content_33 = {
    Text = "Ave, %player%! Benedetto sia, Dio della Distruzione!"
  },
  AvgDialog_131224_Content_34 = {
    Text = "Avvicinandovi al palcoscenico centrale, tre marionette di forme diverse vi salgono sopra e si inchinano nella vostra direzione."
  },
  AvgDialog_131224_Content_35 = {
    Text = "La Signora vi attende all'interno. Prego, entrate—{Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_131224_Content_36 = {
    Text = "Quando la porta del palco si apre, le immagini e i suoni dell'intero teatro sembrano arrestarsi per un singolo istante sospeso."
  },
  AvgDialog_131224_Content_37 = {
    Text = "Varchi la soglia e scosti il sipario—"
  },
  AvgDialog_131224_Content_38 = {
    Text = "Appaiono su questi palcoscenici perché questo teatro porta un unico nome: Fato."
  },
  AvgDialog_131224_Content_39 = {
    Text = "Una voce fresca e pacata vi raggiunge prima di qualsiasi colore."
  },
  AvgDialog_131224_Content_4 = {
    Text = "Rispetto ai misteri di questo luogo, ventitré non sono neanche lontanamente sufficienti."
  },
  AvgDialog_131224_Content_40 = {
    Text = "In un palco che sembra privo di pareti, i fili che collegano ogni palcoscenico e ogni marionetta convergono su un fuso dalla tenue luminescenza. Una donna siede nel punto in cui tutti i fili si incontrano, facendolo ruotare con mano gentile."
  },
  AvgDialog_131224_Content_41 = {
    Text = "Vedi ogni dettaglio di lei con perfetta chiarezza. Eppure a ogni battito di ciglia, ogni impressione svanisce dalla tua mente, senza lasciare nulla."
  },
  AvgDialog_131224_Content_42 = {
    Text = "La sua immagine si rifiuta di restare impressa. Quando volta la testa per guardarti, il tuo cuore — teso dalla vigilanza per tutto questo tempo — inizia a battere violentemente."
  },
  AvgDialog_131224_Content_43 = {Text = "Sei tu?!!"},
  AvgDialog_131224_Content_44 = {
    Text = "Sul Paradise... e quegli Attacchi...!"
  },
  AvgDialog_131224_Content_45 = {
    Text = "Nell'istante in cui vi preparate a convogliare la vostra energia spirituale nella Chiave d'Argento, la signora del teatro tende la mano. Il suo gesto fende l'aria con una grazia così delicata da sembrare che stia pizzicando una corda invisibile."
  },
  AvgDialog_131224_Content_46 = {Text = "!!!"},
  AvgDialog_131224_Content_47 = {
    Text = "L'energia spirituale si riversa fino alla punta delle dita, per poi ritrarsi come una piena che urta contro un'immensa diga. Quando alzate la mano, una scarica di shock vi colpisce: il palmo è vuoto. La chiave è scomparsa."
  },
  AvgDialog_131224_Content_48 = {
    Text = "La Chiave d'Argento... La stringevo appena un istante fa... Come..."
  },
  AvgDialog_131224_Content_49 = {
    Text = "La signora accenna un debole sorriso e rivolge alla sua ancella un lieve cenno del capo."
  },
  AvgDialog_131224_Content_5 = {
    Text = "Non sono io la persona che cercate. Chi può rispondere alle vostre domande vi attende poco più avanti."
  },
  AvgDialog_131224_Content_50 = {
    Text = "Sotto il vostro sguardo attonito, l'ancella si fa avanti e ripone con rispetto la Chiave d'Argento nella vostra mano."
  },
  AvgDialog_131224_Content_51 = {
    Text = "Impossibile... Non può averla sottratta dalle mie mani!"
  },
  AvgDialog_131224_Content_52 = {
    Text = "Prima di entrare nel teatro, stringevate quella chiave con forza, mantenendo un legame spirituale costante."
  },
  AvgDialog_131224_Content_53 = {
    Text = "Il tuo addestramento al Mythag ti ha conferito un livello di Vigilanza così elevato che nessuno potrebbe mai sperare di strapparlo dalla tua presa."
  },
  AvgDialog_131224_Content_54 = {
    Text = "Allora perché..."
  },
  AvgDialog_131224_Content_55 = {
    Text = "Nessuno potrebbe sottrartelo. Ma il Fato può."
  },
  AvgDialog_131224_Content_56 = {
    Text = "Perdonami, %player%. Comprendo la tua Ansia e rispetto il tuo Potere."
  },
  AvgDialog_131224_Content_57 = {
    Text = "Per evitare qualsiasi Danno involontario al mio teatro, non ho avuto Scelta se non alterare brevemente il destino della chiave nella tua mano. Spero che tu possa perdonare questa libertà."
  },
  AvgDialog_131224_Content_58 = {
    Text = "Agita una mano, e un fascio di luce perfora lo spazio tra voi. Guardando attentamente, scorgi un filo tenue, quasi impercettibile, che si estende dalla Chiave d'Argento, risalendo fino al filatoio al suo fianco."
  },
  AvgDialog_131224_Content_59 = {
    Text = "Questi fili... cosa sono?"
  },
  AvgDialog_131224_Content_6 = {
    Text = "Vi fermate davanti all'ingresso di un teatro appena abbastanza largo per una persona. Nessuna insegna, nessun avventore — un anonimo filo di ragnatela nascosto tra le grandiose vetrine di Londinium."
  },
  AvgDialog_131224_Content_60 = {
    Text = "Esistono molte spiegazioni per quei fili, la maggior parte troppo complesse per questo momento. Puoi semplicemente pensarli come... il Fato."
  },
  AvgDialog_131224_Content_61 = {
    Text = "Il filatoio gira dolcemente da solo. Lei si alza in piedi e offre un grazioso cenno di saluto."
  },
  AvgDialog_131224_Content_62 = {
    Text = "Arachne. Sono la Maestra di questo Teatro del Fato. È un onore conoscerti, Custode."
  },
  AvgDialog_131224_Content_63 = {
    Text = "Vi prego, state tranquilli. Qui siete al sicuro."
  },
  AvgDialog_131224_Content_64 = {
    Text = "Suppongo di sì. Se mi avessi voluto morto, non sarei sopravvissuto a quella dimostrazione di poco fa."
  },
  AvgDialog_131224_Content_65 = {
    Text = "Il bagliore del fuso si affievolisce mentre Arachne scaglia un filo. Abbassi lo sguardo sulla chiave restituita con un'espressione combattuta, poi rivolgi a lei uno sguardo sospettoso."
  },
  AvgDialog_131224_Content_66 = {
    Text = "Sul Paradise, mi hai aiutato. Ma da quando sono in questa città, mi hai attaccato due volte."
  },
  AvgDialog_131224_Content_67 = {
    Text = "Comprendo la tua diffidenza. Ma ti prego di credermi quando dico che non ho mai alzato un dito per farti del male."
  },
  AvgDialog_131224_Content_68 = {
    Text = "Hai bloccato il mio collegamento con Kadath e mi hai teso un'Imboscata più volte... mi stai dicendo che nulla di tutto ciò è opera tua?"
  },
  AvgDialog_131224_Content_69 = {
    Text = "Colei che ti ha tormentato può condividere il mio volto, ma non è me."
  },
  AvgDialog_131224_Content_7 = {
    Text = "L'Ancella sospinge la porta, aprendola delicatamente, e scivola nell'Oscurità oltre la soglia. Una luce fievole tremola all'interno, priva di fonte discernibile, come un invito sommesso e celato."
  },
  AvgDialog_131224_Content_70 = {
    Text = "Quanto al tuo collegamento con Kadath... quella è una trappola pericolosa, %player%."
  },
  AvgDialog_131224_Content_71 = {
    Text = "Una Trappola?"
  },
  AvgDialog_131224_Content_72 = {
    Text = "Una creatura nata dalla mia stessa esistenza ti ha causato sofferenze inutili, e per questo sono sinceramente dispiaciuta. Questa situazione ha avuto inizio con me, e sto facendo tutto ciò che è in mio Potere per rimediare all'errore."
  },
  AvgDialog_131224_Content_73 = {
    Text = "Non ti seguo..."
  },
  AvgDialog_131224_Content_74 = {
    Text = "È una lunga storia, legata alla natura del Fato. Le storie sono sempre più facili da digerire dei semplici fatti."
  },
  AvgDialog_131224_Content_75 = {
    Text = "Prego, accomodati, {Male=Sig.,Female=Sig.na} Custode. Questo nuovo atto della nostra rappresentazione è iniziato solo poco tempo fa."
  },
  AvgDialog_131224_Content_76 = {
    Text = "Arachne agita dolcemente la mano. I sipari si aprono, rivelando un vasto Livello fluttuante sospeso nel vuoto."
  },
  AvgDialog_131224_Content_77 = {
    Text = "Uno scintillante Riflesso etereo si erge sul palco, riflettendo entrambe le vostre sagome."
  },
  AvgDialog_131224_Content_78 = {
    Text = "Le trombe suonano una fanfara. Entra in scena: Il Fato Abbandonato."
  },
  AvgDialog_131224_Content_79 = {
    Text = "Il tuo riflesso svanisce dalla superficie dello specchio, mentre l'immagine di Arachne si trasforma in una marionetta."
  },
  AvgDialog_131224_Content_8 = {
    Text = "Esiti un istante, poi varchi la soglia."
  },
  AvgDialog_131224_Content_80 = {
    Text = "La marionetta resta seduta, ma la sua dolce compostezza è evaporata."
  },
  AvgDialog_131224_Content_81 = {
    Text = "Fa roteare un calice colmo di un rosso sangue d'annata, come se fosse assisa su un trono di massacro. I suoi occhi, innocenti eppure assolutamente spietati, spazzano lo sguardo sul pubblico."
  },
  AvgDialog_131224_Content_82 = {
    Text = "Dietro la marionetta, quattro paia di arti di ragno affilati come rasoi oscillano pigramente, le punte sfiorano le guance degli inservienti lì accanto."
  },
  AvgDialog_131224_Content_83 = {
    Text = "Ah, il dolce profumo della libertà..."
  },
  AvgDialog_131224_Content_84 = {
    Text = "Quanti anni abbiamo marcito in quella Prigione Abissale, mio caro scudiero?"
  },
  AvgDialog_131224_Content_85 = {
    Text = "Non lo so, mia signora."
  },
  AvgDialog_131224_Content_86 = {
    Text = "Nomi, tempo, emozioni... ho dimenticato tutto. Ricordo solo voi, mia signora — la stimata Nefraea."
  },
  AvgDialog_131224_Content_87 = {
    Text = "Ricordo solo la vostra promessa: che ci avreste condotti fuori, e che avremmo brandito la lama della vendetta contro il Fato stesso."
  },
  AvgDialog_131224_Content_88 = {
    Text = "Ricordo, figlio mio. Ti ho fatto novantamila promesse, e ora lascia che ti faccia la novantamilaunesima."
  },
  AvgDialog_131224_Content_89 = {
    Text = "In ogni dato istante, un solo destino può davvero esistere. L'Emissario del Fato recide gli innumerevoli destini \"sbagliati\", lasciando dietro di sé soltanto l'unico cammino \"vero\"."
  },
  AvgDialog_131224_Content_9 = {Text = "..."},
  AvgDialog_131224_Content_90 = {
    Text = "Noi siamo il Fato Abbandonato. Heh... mio caro scudiero, tu sei un errore. Proprio come me."
  },
  AvgDialog_131224_Content_91 = {
    Text = "Nel subconscio di questo universo, in quel vuoto di una Prigione Abissale, siamo stati esiliati e imprigionati. Vaghiamo là, dimenticati, per l'eternità. La nostra condanna ha superato il tempo stesso..."
  },
  AvgDialog_131224_Content_92 = {
    Text = "La donna di nome Nefraea si alza dal suo seggio e si sporge in avanti, il suo sguardo riflesso si fissa sulla vera Arachne tra il pubblico."
  },
  AvgDialog_131224_Content_93 = {
    Text = "Ma con quale diritto, o Dea del Fato? Perché dobbiamo essere proprio noi a venire scartati?"
  },
  AvgDialog_131224_Content_94 = {
    Text = "La suprema, unica divinità del cosmo infinito si è infine mossa per un istante fugace. È ricaduta nel dormiveglia, ma la prigione della Sua coscienza — l'eterna Prigione Abissale — si è finalmente incrinata per noi."
  },
  AvgDialog_131224_Content_95 = {
    Text = "Avevo già accettato l'oblio. Ero svanita. Allora perché — perché devo essere costretta a ricordare tutta questa agonia?"
  },
  AvgDialog_131224_Content_96 = {
    Text = "Nefraea prosciuga il suo calice e lascia sfuggire un sospiro di pura soddisfazione. Gocce cremisi le scivolano lungo le labbra pallide, macchiando l'opaca ruota che fila nel suo grembo."
  },
  AvgDialog_131224_Content_97 = {
    Text = "Forse questa è la volontà del Fato... un destino che neppure tu puoi controllare."
  },
  AvgDialog_131224_Content_98 = {
    Text = "La Divinità Primordiale dorme di nuovo, ma i Suoi frammenti hanno trovato la strada fino alla nostra soglia."
  },
  AvgDialog_131224_Content_99 = {
    Text = "Non possiedo il tuo dono di tessere il destino. Sono soltanto una correttrice del Fato — una giustiziera dal nulla. Punirò i peccati nel fiume del tempo per conto del Primordiale."
  },
  AvgDialog_131225_Content_1 = {
    Text = "Echi del Passato"
  },
  AvgDialog_131225_Content_10 = {
    Text = "Invece dell'interno spazioso che ti aspettavi, la villa è claustrofobicamente stipata. Nefraea sembra intenzionata a scarabocchiare il caos nel suo copione."
  },
  AvgDialog_131225_Content_11 = {
    Text = "File interminabili di armadi e scaffali giacciono nel silenzio, ogni centimetro di spazio colmo di barattoli di varie dimensioni."
  },
  AvgDialog_131225_Content_12 = {
    Text = "Specchi d'argento, uova di ragno, scarpette da danza infestate da strani insetti... oggetti conservati in fluidi sospetti, simili a bocche cristallizzate in un grido silenzioso."
  },
  AvgDialog_131225_Content_13 = {
    Text = "Ti avvicini ai barattoli e leggi le etichette ad alta voce."
  },
  AvgDialog_131225_Content_14 = {
    Text = "<Italic:\"Due anni. Ha pronunciato le prime parole. Non un richiamo alla famiglia, ma un addio al vecchio maggiordomo che serviva la casa da generazioni.\">"
  },
  AvgDialog_131225_Content_15 = {
    Text = "<Italic:\"Quella stessa notte, il maggiordomo morì d'infarto. Piangeva fuori dalla portineria, aggrappato ai suoi averi...\">"
  },
  AvgDialog_131225_Content_16 = {
    Text = "È una vecchia spilla di famiglia."
  },
  AvgDialog_131225_Content_17 = {
    Text = "<Italic:\"Cinque anni. Danzava un timido valzer proprio come la Madre, tra gli applausi arrossiti degli ospiti a cena...\">"
  },
  AvgDialog_131225_Content_18 = {
    Text = "È un paio di vivaci scarpe da danza rosse."
  },
  AvgDialog_131225_Content_19 = {
    Text = "<Italic:\"Sette anni. Ha ricevuto un regalo di compleanno dal Padre: un arcolaio chiamato Moirae.\">"
  },
  AvgDialog_131225_Content_2 = {
    Text = "Brick Lane. Ricordi le tue precedenti indagini in questa zona di Londinium."
  },
  AvgDialog_131225_Content_20 = {
    Text = "<Italic:\"Ha visto l'ombra del Fato proiettata tra i fili...\">"
  },
  AvgDialog_131225_Content_21 = {
    Text = "È una manciata di filo spezzato."
  },
  AvgDialog_131225_Content_22 = {
    Text = "<Italic:\"Prima volta all'opera con i genitori... Primo incontro con un'anima gemella... Prima volta a seppellire un cane amato...\">"
  },
  AvgDialog_131225_Content_23 = {
    Text = "Le parole sulle etichette dei barattoli scivolano nel tuo sguardo, una dopo l'altra. Ogni volta che le sfiori, una memoria nebulosa tremola in fondo alla tua mente. Ti volti e rivolgi ad Arachne uno sguardo perplesso."
  },
  AvgDialog_131225_Content_24 = {
    Text = "Queste... sono le tue memorie?"
  },
  AvgDialog_131225_Content_25 = {
    Text = "Erano mie, un tempo. Molto tempo fa, furono affidate al Burattino chiamato 'Memorie.'"
  },
  AvgDialog_131225_Content_26 = {
    Text = "Sono preziose. Perché mai metterle dentro un Fantoccio?"
  },
  AvgDialog_131225_Content_27 = {
    Text = "Tutti devono compiere delle scelte. E ogni scelta ha un prezzo."
  },
  AvgDialog_131225_Content_28 = {
    Text = "Per raggiungere la fine della strada, bisogna sempre abbandonare qualcosa lungo il cammino. Credo che voi lo comprendiate meglio di chiunque altro, {Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_131225_Content_29 = {
    Text = "Arachne elude una risposta diretta. Fissa le vetrine, le dita che sfiorano il vetro dei barattoli."
  },
  AvgDialog_131225_Content_3 = {
    Text = "Lurida e caotica. L'aria è densa di fumo di carbone e liquami — i miasmi che definirono le vite di Mason e Jenkin."
  },
  AvgDialog_131225_Content_30 = {
    Text = "Il suo tocco è lieve e lento, come un anziano che accarezza con dolcezza i giocattoli prediletti della propria infanzia."
  },
  AvgDialog_131225_Content_31 = {
    Text = "Estrarre queste memorie e metterle in mostra così... questo è lo spettacolo che hai preparato per me, vero, Nefraea?"
  },
  AvgDialog_131225_Content_32 = {
    Text = "Capisco cosa stai cercando di dire..."
  },
  AvgDialog_131225_Content_33 = {
    Text = "<Big:<Shake:AAAHHHH!—>>"
  },
  AvgDialog_131225_Content_34 = {
    Text = "Uno strido lacerante riecheggia per la stanza. I barattoli di memorie tintinnano, simili a una folla di spettatori muti e ridenti."
  },
  AvgDialog_131225_Content_35 = {
    Text = "!! Proviene dalla stanza in fondo al corridoio!"
  },
  AvgDialog_131225_Content_36 = {Text = "Bang—"},
  AvgDialog_131225_Content_37 = {
    Text = "Correte lungo il corridoio, spalancate la porta con un calcio..."
  },
  AvgDialog_131225_Content_38 = {
    Text = "...e fai un passo in un diluvio torrenziale."
  },
  AvgDialog_131225_Content_39 = {
    Text = "Non c'è tuono, né vento, né pioggia. Solo un diluvio di ragni che precipitano dal soffitto come una tempesta."
  },
  AvgDialog_131225_Content_4 = {
    Text = "All'improvviso, una magnifica villa dorata appare tra due baracche, come un portagioie gettato in un cumulo di rottami."
  },
  AvgDialog_131225_Content_40 = {
    Text = "La massa di arti aracnidi neri e viscosi forma una marea montante, che divora ogni oggetto e ogni brandello di luce."
  },
  AvgDialog_131225_Content_41 = {
    Text = "Nel centro della tempesta oscura, i ragni brulicanti e voraci si fondono in una forma umana. Dove la marea non è ancora giunta, un volto avvizzito e familiare fa capolino."
  },
  AvgDialog_131225_Content_42 = {
    Text = "Signora... Arachne..."
  },
  AvgDialog_131225_Content_43 = {
    Text = "Corri... vattene da qui...!"
  },
  AvgDialog_131225_Content_44 = {
    Text = "Shh... non hai battute in questa scena, Sig. Gentilezza."
  },
  AvgDialog_131225_Content_45 = {
    Text = "La Vendetta del Fato, Atto Secondo, Scena Seconda. La chiamo \"Acquazzone.\""
  },
  AvgDialog_131225_Content_46 = {
    Text = "Godetevi la pioggia, mio caro pubblico."
  },
  AvgDialog_131225_Content_47 = {
    Text = "Il liquido accumulato ribolle in un'ondata. Obbedendo a un comando supremo, i ragni neri dilagano in ogni angolo della stanza."
  },
  AvgDialog_131225_Content_48 = {
    Text = "Tra le risate deliziata di Nefraea, gli Scudieri Abissali nati dallo sciame si lanciano verso di te—"
  },
  AvgDialog_131225_Content_5 = {
    Text = "Vagabondi e operai sfiniti passano davanti alla struttura ornata senza degnarla di uno sguardo, come se fosse lì dall'alba dei tempi."
  },
  AvgDialog_131225_Content_6 = {
    Text = "Persino il fato della città è distorto... Il potere di Nefraea cresce."
  },
  AvgDialog_131225_Content_7 = {
    Text = "Ti avvicini con cautela. Proprio mentre allunghi la mano per bussare, la porta si apre in silenzio."
  },
  AvgDialog_131225_Content_8 = {
    Text = "Sembra che il nostro premuroso ospite abbia lasciato la porta aperta per noi."
  },
  AvgDialog_131225_Content_9 = {
    Text = "Quello è..."
  },
  AvgDialog_131226_Content_1 = {
    Text = "S-sono morti!!"
  },
  AvgDialog_131226_Content_10 = {
    Text = "Ho visto tutto. Non sei passato attraverso quella Porta, %player%. Questo non è il luogo in cui dovremmo trovarci."
  },
  AvgDialog_131226_Content_11 = {
    Text = "Tutto sembra sbagliato... la Dissoluzione, i Mythag, i Cataclismi—non ne sanno assolutamente nulla."
  },
  AvgDialog_131226_Content_12 = {
    Text = "Ma questa città appare esattamente come la ricordo. Esattamente com'era prima del Tohuwabohu. Forse dovremmo tornare alla scuola e dare un'occhiata. Potremmo trovare qualcosa..."
  },
  AvgDialog_131226_Content_13 = {
    Text = "Vengo proprio da lì. Non ci sono Mythag qui, %player%."
  },
  AvgDialog_131226_Content_14 = {
    Text = "Nessun Mythag...?"
  },
  AvgDialog_131226_Content_15 = {
    Text = "La mappa del mondo nel negozio era diversa da qualsiasi cosa avessi mai visto. E ogni calendario che ho trovato... sono tutti diversi. Non il calendario Dopo il diluvio che usiamo noi."
  },
  AvgDialog_131226_Content_16 = {
    Text = "La cosa più strana è... questa città non ha fine."
  },
  AvgDialog_131226_Content_17 = {
    Text = "Nessuna... fine?"
  },
  AvgDialog_131226_Content_18 = {
    Text = "Dirigendosi a nord da dove dovrebbe trovarsi Mythag, si dovrebbe oltrepassare i confini di Londinium."
  },
  AvgDialog_131226_Content_19 = {
    Text = "Sono stato attaccato da quei ragni lungo la strada. Per sfuggire loro, ho continuato su quella via. Ma alla fine... mi sono ritrovato vicino a dove eravate voi. L'estremità meridionale di Londinium."
  },
  AvgDialog_131226_Content_2 = {
    Text = "La folla urla e si disperde. Prima ancora che tu te ne accorga, William è al tuo fianco, quei capelli dorati inconfondibili come sempre."
  },
  AvgDialog_131226_Content_20 = {
    Text = "Questa non è Londinium. Questa non è Kadath."
  },
  AvgDialog_131226_Content_21 = {
    Text = "Quindi la mia memoria era giusta... la porta si è davvero chiusa prima che potessi entrare..."
  },
  AvgDialog_131226_Content_22 = {
    Text = "Alzi lo sguardo verso i panorami familiari oltre il passaggio e sospiri, mentre un senso di vuoto ti pervade."
  },
  AvgDialog_131226_Content_23 = {
    Text = "Un luogo identico a Londinium, una città senza fine, ragni neri che appaiono dal nulla... e la «Dama» a cui obbediscono..."
  },
  AvgDialog_131226_Content_24 = {
    Text = "È troppo presto per averne certezza, ma non credo che la chiusura della porta e il nostro avvento qui siano una coincidenza. Qualcuno ha orchestrato tutto questo deliberatamente — chiunque comandi quei ragni."
  },
  AvgDialog_131226_Content_25 = {
    Text = "Non capiamo ancora nulla. Dobbiamo prima raccogliere informazioni..."
  },
  AvgDialog_131226_Content_26 = {Text = "Voi due..."},
  AvgDialog_131226_Content_27 = {Text = "Chi?!"},
  AvgDialog_131226_Content_28 = {
    Text = "Una radiosità argentea divampa nel palmo meccanico di William, come una lama pronta a essere sguainata in qualsiasi momento."
  },
  AvgDialog_131226_Content_29 = {
    Text = "In quel pericoloso bagliore argenteo, distingui l'anziano che poco prima aveva cercato di offrirti del cibo."
  },
  AvgDialog_131226_Content_3 = {
    Text = "William... quando hai... cosa sta succedendo?"
  },
  AvgDialog_131226_Content_30 = {
    Text = "Sono... sono solo io..."
  },
  AvgDialog_131226_Content_31 = {
    Text = "Questo... è tuo?"
  },
  AvgDialog_131226_Content_32 = {
    Text = "Il vecchio apre la mano. Il distintivo della scuola di Mythag — il tuo comunicatore — giace silenzioso nel suo palmo ruvido."
  },
  AvgDialog_131226_Content_33 = {
    Text = "Ah! Dev'essere caduto durante lo scontro..."
  },
  AvgDialog_131226_Content_34 = {
    Text = "Questo significa moltissimo per me... grazie infinite!"
  },
  AvgDialog_131226_Content_35 = {
    Text = "Sotto lo sguardo vigile di William, riprendi il distintivo e lo riponi con cura."
  },
  AvgDialog_131226_Content_36 = {
    Text = "Signore... non si è spaventato per quello che è appena successo?"
  },
  AvgDialog_131226_Content_37 = {
    Text = "Spaventato... certo che lo ero. Ho vissuto qui tutta la vita. Non ho mai visto nulla di simile..."
  },
  AvgDialog_131226_Content_38 = {
    Text = "Ma quell'oggetto sembrava importante per te, e siete appena arrivati — se l'avessi perso, non avresti avuto la minima idea di dove cercarlo. Così l'ho portato qui."
  },
  AvgDialog_131226_Content_39 = {
    Text = "Che gentilezza... grazie."
  },
  AvgDialog_131226_Content_4 = {
    Text = "Non è qui. Muoviti!"
  },
  AvgDialog_131226_Content_40 = {
    Text = "Siamo appena arrivati e c'è molto che non sappiamo. Le dispiacerebbe se le facessimo qualche domanda?"
  },
  AvgDialog_131226_Content_41 = {
    Text = "Non mi dispiace passare un po' più di tempo con voi due, ma temo di sapere ben poco su ciò che cercate."
  },
  AvgDialog_131226_Content_42 = {
    Text = "Un posto con più gente potrebbe esservi più utile, immagino."
  },
  AvgDialog_131226_Content_43 = {
    Text = "Bene, ho restituito ciò che andava restituito. Vado per la mia strada."
  },
  AvgDialog_131226_Content_44 = {
    Text = "Il vecchio liquida le vostre cortesie di commiato con un gesto della mano mentre si allontana nel vicolo."
  },
  AvgDialog_131226_Content_45 = {
    Text = "Non sembra avere cattive intenzioni. Ha ragione — dobbiamo trovare un luogo dove le informazioni circolino più liberamente, e in fretta."
  },
  AvgDialog_131226_Content_46 = {
    Text = "Conosco il posto giusto!"
  },
  AvgDialog_131226_Content_47 = {
    Text = "Se questa città rispecchia davvero Londinium, allora quel posto dovrebbe essere esattamente ciò di cui abbiamo bisogno."
  },
  AvgDialog_131226_Content_48 = {
    Text = "Mentre vi allontanate, un ragno viola pallido si nasconde appena oltre il limite della vostra Visuale, strisciando lungo il suo filo e infilandosi in una crepa nel muro, svanendo senza lasciare traccia."
  },
  AvgDialog_131226_Content_5 = {
    Text = "William ti afferra e si dirige nella direzione opposta alla folla."
  },
  AvgDialog_131226_Content_6 = {Text = "..."},
  AvgDialog_131226_Content_7 = {
    Text = "Non dovrebbe esserci nessuno da queste parti."
  },
  AvgDialog_131226_Content_8 = {
    Text = "Che cosa sta succedendo? Perché Londinium è diventata così..."
  },
  AvgDialog_131226_Content_9 = {
    Text = "Quei ragni che ci hanno attaccato, e quella persona... potrebbe essere collegata alla donna che abbiamo incontrato sul Paradise?"
  },
  AvgDialog_131227_Content_1 = {
    Text = "Tawil! Io..."
  },
  AvgDialog_131227_Content_2 = {
    Text = "Capisco, Custode."
  },
  AvgDialog_131227_Content_3 = {
    Text = "Il tuo fato è riscritto. Non puoi fermarti, né dovresti."
  },
  AvgDialog_131227_Content_4 = {
    Text = "Arachne non può parlare del futuro... Per favore, dimmi cosa devo fare..."
  },
  AvgDialog_131227_Content_5 = {
    Text = "Non posso parlare di ciò che si trova Oltre il portale. Vi sono altri più adatti a guidarti in questa faccenda."
  },
  AvgDialog_131227_Content_6 = {
    Text = "Avanza, Custode. Il tuo fato è tuo da vedere con chiarezza."
  },
  AvgDialog_131228_Content_1 = {
    Text = "Hmm... Eroi e giullari, marionette del fato... che spettacolo."
  },
  AvgDialog_131228_Content_2 = {
    Text = "Arachne mi ha detto che la chiave del Lucchetto è \"Estasi\"... quello è il tuo Dominio, N."
  },
  AvgDialog_131228_Content_3 = {
    Text = "Shh! Nessuna fretta, per favore. Rovinare un buon spettacolo è il peccato più imperdonabile di questo universo."
  },
  AvgDialog_131228_Content_4 = {
    Text = "Avanti, Custode. È passato così tanto tempo! Fammi vedere se hai acquisito nuove intuizioni riguardo all'... \"Estasi.\""
  },
  AvgDialog_131229_Content_10 = {
    Text = "Rispondimi... Liz!"
  },
  AvgDialog_131229_Content_11 = {
    Text = "I suoi fili del fato sono recisi. La sua vita è spenta."
  },
  AvgDialog_131229_Content_12 = {
    Text = "<Shake:No... non possiamo permettere a Nefraea di farla franca.> <Big:<Red:Deve pagare per questa atrocità!>>"
  },
  AvgDialog_131229_Content_13 = {
    Text = "Il Fato ha già preparato il prezzo che dovrà pagare. La traiettoria non finisce qui."
  },
  AvgDialog_131229_Content_14 = {
    Text = "Ma hai appena detto che Liz è..."
  },
  AvgDialog_131229_Content_15 = {
    Text = "La morte non è che una parte del Fato. Questo è il mio palcoscenico, Custode {Male=Mr.,Female=Miss}. Tutti i destini sono fili nelle mie mani, e solo io ne tesso il corso."
  },
  AvgDialog_131229_Content_16 = {Text = "!!!"},
  AvgDialog_131229_Content_17 = {
    Text = "<Shake:Aspetta, vuoi dire...>"
  },
  AvgDialog_131229_Content_18 = {
    Text = "L'espressione di Arachne non mostra né pianto né gioia. Si avvicina all'annunciatrice appena manovrata da Nefraea. La luce del crepuscolo delinea la sua sagoma ferma, immutabile come il Fato stesso."
  },
  AvgDialog_131229_Content_19 = {
    Text = "Heh... hahaha... Arachne, sei ancora così, così arrogante! Hahaha..."
  },
  AvgDialog_131229_Content_2 = {
    Text = "I nemici circostanti cadono, ma tu non ti fermi."
  },
  AvgDialog_131229_Content_20 = {
    Text = "Nefraea sembra trovare tutto ciò esilarante, la sua risata echeggia mentre rotola sul pavimento."
  },
  AvgDialog_131229_Content_21 = {
    Text = "Hai contaminato il fato della Sig.na Salle e l'hai condotta a una morte vuota. La Grande Tela ricorda ogni tua azione."
  },
  AvgDialog_131229_Content_22 = {
    Text = "I destini corrotti devono essere riparati. Un prezzo vi attende nelle ombre del vostro futuro."
  },
  AvgDialog_131229_Content_23 = {
    Text = "Arachne protende la mano, le dita danzano sul capo del cadavere. Il suo fuso gira sommessamente, e la realtà inizia a distorcersi e rimodellarsi a ogni rotazione..."
  },
  AvgDialog_131229_Content_24 = {
    Text = "Fili del Fato, rispondete al richiamo della Tela. Percorrete l'unico sentiero e calate sul palco ancora una volta..."
  },
  AvgDialog_131229_Content_25 = {
    Text = "Il suo corpo... è scomparso?"
  },
  AvgDialog_131229_Content_26 = {
    Text = "Sotto il tocco di Arachne, il corpo di Liz sembra subire una combustione silenziosa, dissolvendosi in cenere che si disperde nell'aria."
  },
  AvgDialog_131229_Content_27 = {
    Text = "Sotto le braci che cadono, una nuova forma si rivela."
  },
  AvgDialog_131229_Content_28 = {
    Text = "Quella è... la presentatrice?!"
  },
  AvgDialog_131229_Content_29 = {
    Text = "Degli Spuntoni trafiggono ora il corpo della presentatrice, sospendendola sopra il palco in un perfetto, macabro Riflesso della posa di Liz."
  },
  AvgDialog_131229_Content_3 = {
    Text = "Urli, calpestando freneticamente il volto sorridente dell'annunciatrice contro le assi del pavimento fino a renderlo irriconoscibile."
  },
  AvgDialog_131229_Content_30 = {
    Text = "Il ghigno orrendo della presentatrice è l'ultima cosa che resta di lei, mentre cade in un silenzio eterno."
  },
  AvgDialog_131229_Content_31 = {
    Text = "Arachne, tu..."
  },
  AvgDialog_131229_Content_32 = {
    Text = "Scusate il ritardo, io... Oh!"
  },
  AvgDialog_131229_Content_33 = {
    Text = "Una figura familiare scosta il sipario. I Suoi Occhi vi oltrepassano con una Spazzata e si fissano sul cadavere appeso in alto."
  },
  AvgDialog_131229_Content_34 = {
    Text = "La sua postura... è magnifica..."
  },
  AvgDialog_131229_Content_35 = {
    Text = "Liz sembra Ignorare i cadaveri e il pubblico rimasto. Cammina verso il centro del palco, la Mano che traccia l'aria vicino alle gambe del corpo appeso, come se ne studiasse la curva della forma."
  },
  AvgDialog_131229_Content_36 = {
    Text = "Arachne... hai scambiato i loro destini?!"
  },
  AvgDialog_131229_Content_37 = {
    Text = "Ma hai detto che un prezzo simile era insostenibile..."
  },
  AvgDialog_131229_Content_38 = {
    Text = "Il costo è irrilevante rispetto alla Scelta. Nel mio stesso destino, questo è il prezzo che sono destinata a pagare."
  },
  AvgDialog_131229_Content_39 = {
    Text = "Va', %player%. Non far aspettare la signorina Liz."
  },
  AvgDialog_131229_Content_4 = {
    Text = "Sì... proprio così... Lascia che esca! Che magnifica espressione..."
  },
  AvgDialog_131229_Content_40 = {
    Text = "Occhi vuoti e respiro gelato. La sua gonna ondeggia nel vento, tremolante di fioche Fiamme Verdi. Ogni fremito delle sue dita sembra una Danza coreografata."
  },
  AvgDialog_131229_Content_41 = {
    Text = "La figura insanguinata che si è lanciata verso di te poco fa si sovrappone alla donna che hai davanti ora. Liz è lì, vivida e viva — l'intricata ritessitura del fato non ha lasciato alcun segno su di lei."
  },
  AvgDialog_131229_Content_42 = {
    Text = "Alla fine, Liz si scuote dalla sua Trance e si volta verso di voi."
  },
  AvgDialog_131229_Content_43 = {
    Text = "Ho dormito fino al pomeriggio e ho perso lo spettacolo. Non mi era mai successo prima..."
  },
  AvgDialog_131229_Content_44 = {
    Text = "Mi sono perso qualcosa di importante?"
  },
  AvgDialog_131229_Content_45 = {
    Text = "I Suoi Occhi scivolano sui corpi e gli Schizzi di Sangue che aveva precedentemente ignorato."
  },
  AvgDialog_131229_Content_46 = {
    Text = "No, non ti sei persa nulla, Liz."
  },
  AvgDialog_131229_Content_47 = {
    Text = "Stai... bene? Ti senti bene?"
  },
  AvgDialog_131229_Content_48 = {
    Text = "Mi sento bene. Ma ditemi, {Male=signore,Female=signorina}, ci siamo già incontrati? Mi risultate stranamente familiare..."
  },
  AvgDialog_131229_Content_49 = {
    Text = "Forse è perché sono un vostro devoto ammiratore. Ho assistito a molti dei vostri spettacoli."
  },
  AvgDialog_131229_Content_5 = {
    Text = "Il volto straziato continua a sorridere. Una flebile voce sfugge dalla sua gola frantumata."
  },
  AvgDialog_131229_Content_50 = {
    Text = "Le sorridete. Questo palco ha la sua Storia, e non avete alcuna Intenzione di gravarla col peso del passato."
  },
  AvgDialog_131229_Content_51 = {
    Text = "Siamo qui per \"Gentilezza.\""
  },
  AvgDialog_131229_Content_52 = {
    Text = "Ah, dunque siete amici di Lady Sorel. Temevo di essere stata un po' scortese lasciando il Signor Kindness a casa mentre venivo a esibirmi. Prego, seguitemi. Abito qui vicino."
  },
  AvgDialog_131229_Content_53 = {
    Text = "Liz rivolge un ultimo sguardo prolungato al cadavere sulla parete prima di condurti dietro il sipario."
  },
  AvgDialog_131229_Content_54 = {Text = "..."},
  AvgDialog_131229_Content_55 = {
    Text = "Quindi... avrebbe dovuto essere il mio corpo appeso lassù... sul palco..."
  },
  AvgDialog_131229_Content_56 = {
    Text = "Sembra troppo rapita dalla bellezza della scena per piangere i colleghi caduti, o per rivolgere un'altra parola di ringraziamento al suo salvatore."
  },
  AvgDialog_131229_Content_57 = {
    Text = "Mentre parli, gli occhi di Liz tremolano come fiamme danzanti. Protende le braccia, imitando la posa del cadavere."
  },
  AvgDialog_131229_Content_58 = {
    Text = "È stato... bello?"
  },
  AvgDialog_131229_Content_59 = {
    Text = "La vera bellezza si rivela solo alla nascita e alla morte. Era uno spettacolo senza pari, Sig.na Salle."
  },
  AvgDialog_131229_Content_6 = {
    Text = "Nefraea non è qui. Questa è solo un'illusione. Non lasciare che la rabbia ti accechi, {Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_131229_Content_60 = {
    Text = "Grazie, Lady Arachne. In quanto tessitrice del Fato, dovete essere costantemente circondata da tale bellezza. Vi invidio... davvero."
  },
  AvgDialog_131229_Content_61 = {
    Text = "Troppi tesori segreti possono diventare una maledizione."
  },
  AvgDialog_131229_Content_62 = {
    Text = "Se questa è la tua maledizione, quale ricompensa cerchi?"
  },
  AvgDialog_131229_Content_63 = {
    Text = "Liz non nota la breve esitazione di Arachne mentre apre la porta della stanza degli ospiti."
  },
  AvgDialog_131229_Content_64 = {
    Text = "Questa è la stanza del Sig. Kindness. Signore, i vostri amici sono qui."
  },
  AvgDialog_131229_Content_65 = {
    Text = "Signor Gentilezza?"
  },
  AvgDialog_131229_Content_66 = {
    Text = "La stanza è semplice. Nulla è fuori posto, ma non c'è nessuno all'interno."
  },
  AvgDialog_131229_Content_67 = {
    Text = "Un biglietto solitario giace sullo scaffale nella stanza vuota."
  },
  AvgDialog_131229_Content_68 = {
    Text = "<Italic:\"Perdonate la mia partenza improvvisa. Lady Sorel temeva per la vostra sicurezza e ha preso nuove disposizioni. Mi sto dirigendo alla villa dove risiede 'Memorie'.\">"
  },
  AvgDialog_131229_Content_69 = {
    Text = "<Italic:\"Vi sono profondamente grato per le vostre premure. Troverò il modo di ripagare questo debito.\">"
  },
  AvgDialog_131229_Content_7 = {
    Text = "<Shake:Huff... huff...>"
  },
  AvgDialog_131229_Content_70 = {
    Text = "Sorel ci avrebbe avvisati se avesse cambiato il piano..."
  },
  AvgDialog_131229_Content_71 = {
    Text = "Guardi gli occhi calmi di Arachne. Dietro il suo eterno, sereno sorriso, cogli un'ombra fugace di preoccupazione."
  },
  AvgDialog_131229_Content_72 = {
    Text = "\"Memorie\" è senza dimora. Non ha alcuna villa."
  },
  AvgDialog_131229_Content_73 = {
    Text = "Cosa?!! Allora..."
  },
  AvgDialog_131229_Content_74 = {
    Text = "Nefraea ha probabilmente manomesso anche il fato di Memoria. Sono entrambi in grave pericolo."
  },
  AvgDialog_131229_Content_75 = {
    Text = "Mi dispiace. Non me ne ero resa conto..."
  },
  AvgDialog_131229_Content_76 = {
    Text = "Non è colpa vostra, signorina Salle."
  },
  AvgDialog_131229_Content_77 = {
    Text = "Se Nefraea può riscrivere il vostro destino, trovare chi vi circonda è un compito semplice. Questo è un fardello che dobbiamo portare noi."
  },
  AvgDialog_131229_Content_78 = {
    Text = "L'inchiostro non è nemmeno asciutto. Era qui di recente — se ci affrettiamo, potremmo ancora fare in tempo."
  },
  AvgDialog_131229_Content_79 = {
    Text = "Liz, ci sono cose che volevo dirti, ma non c'è tempo..."
  },
  AvgDialog_131229_Content_8 = {
    Text = "Ti fermi finalmente solo quando il volto non è più che una poltiglia."
  },
  AvgDialog_131229_Content_80 = {
    Text = "Ci saranno altre occasioni, {Male=Sig.,Female=Sig.na} Custode. Spero che la mia prossima danza vi commuova altrettanto."
  },
  AvgDialog_131229_Content_81 = {
    Text = "Con un semplice sorriso d'addio, Liz torna al suo mondo."
  },
  AvgDialog_131229_Content_82 = {
    Text = "Solleva le braccia, imitando la curva del cadavere che ha visto, cercando di catturare la posa che le ossessiona la mente."
  },
  AvgDialog_131229_Content_83 = {
    Text = "La brezza le agita la gonna. Sembra proprio un cigno in volo."
  },
  AvgDialog_131229_Content_9 = {
    Text = "Il cadavere manipolato di Liz ha perso ogni segno di vita. Adagi il suo corpo straziato delicatamente sul pavimento e attivi il legame spirituale."
  },
  AvgDialog_131230_Content_1 = {
    Text = "Il sipario cala"
  },
  AvgDialog_131230_Content_10 = {
    Text = "Dato che hai ricreato questa città... pensavo avresti riportato anche le cose scomparse."
  },
  AvgDialog_131230_Content_11 = {
    Text = "...Ti mancano, vero?"
  },
  AvgDialog_131230_Content_12 = {
    Text = "Preferisco che il livello si presenti per ciò che è davvero, piuttosto che avere una tazza di caffè perfetta."
  },
  AvgDialog_131230_Content_13 = {
    Text = "Ho ricreato questo luogo dalla memoria, eppure non posso cambiare il fatto che sia un livello del tutto nuovo."
  },
  AvgDialog_131230_Content_14 = {
    Text = "E poi, il nuovo caffè qui ha un suo sapore unico, non trovi?"
  },
  AvgDialog_131230_Content_15 = {
    Text = "Arachne sorride e prende un piccolo sorso del liquido amaro."
  },
  AvgDialog_131230_Content_16 = {
    Text = "Nefraea... cosa le è successo alla fine?"
  },
  AvgDialog_131230_Content_17 = {
    Text = "I vostri fili del destino sono stati ritessuti insieme. Significa che... siete di nuovo la stessa persona?"
  },
  AvgDialog_131230_Content_18 = {
    Text = "Ciò che un tempo apparteneva a Nephrea—le sue qualità, la sua natura originale—è tornato al mio destino. O meglio, come già sai... non se ne sono mai veramente andati."
  },
  AvgDialog_131230_Content_19 = {
    Text = "Ma la Trama del Fato è unica. La Nephrea che conoscevi... quella vendicatrice sprofondata nella Prigione Abissale, abbandonata dal fato... non c'è filo in questa trama che le appartenga."
  },
  AvgDialog_131230_Content_2 = {
    Text = [[
<Italic:Lascia ch'io pianga / Lascia ch'io pianga
mia cruda sorte, / la mia cruda sorte,>]]
  },
  AvgDialog_131230_Content_20 = {
    Text = "Lei... è svanita, {Male=Mr.,Female=Miss} Custode."
  },
  AvgDialog_131230_Content_21 = {
    Text = "Il fuso gira dolcemente, senza fine. Arachne chiude gli occhi e reclina il capo all'indietro, inspirando il tenue profumo di fiori portato dal vento."
  },
  AvgDialog_131230_Content_22 = {
    Text = "I Fati Abbandonati... condannati soltanto alla prigionia eterna o al completo annientamento. Che crudeltà..."
  },
  AvgDialog_131230_Content_23 = {
    Text = "In ogni istante, il Fato richiede una Scelta. I sentieri giusti restano, mentre quelli sbagliati vengono scartati. Finché non troveremo il Vero Sentiero, questo è inevitabile quanto il collasso dell'universo stesso."
  },
  AvgDialog_131230_Content_24 = {
    Text = "Finché non troveremo il Vero Sentiero, questo è inevitabile quanto il collasso dell'universo stesso."
  },
  AvgDialog_131230_Content_25 = {
    Text = "Dimmi, {Male=Mr.,Female=Miss} Custode, se avessi il potere di controllare il Fato, lo lasceresti precipitare nel caos? O faresti la scelta al posto degli altri, anche se significasse portare il nome di un assassino?"
  },
  AvgDialog_131230_Content_26 = {
    Text = "Io... non lo so."
  },
  AvgDialog_131230_Content_27 = {
    Text = "Questo è solo un dibattito per il tuo diletto, non una domanda a cui devi rispondere. Porti già fin troppo sulle spalle; non hai bisogno di sobbarcarti anche questo peso."
  },
  AvgDialog_131230_Content_28 = {
    Text = "Arachne scuote la testa con un dolce sorriso."
  },
  AvgDialog_131230_Content_29 = {
    Text = "La Scelta è una forma di potere, eppure molti scelgono di rinunciarvi anche quando è alla loro portata."
  },
  AvgDialog_131230_Content_3 = {
    Text = "<Italic:E che sospiri la libertà! / e che sospiri la libertà!>"
  },
  AvgDialog_131230_Content_30 = {
    Text = "Scegliere significa sopportarne le conseguenze, e non è cosa da poco, {Male=Mr.,Female=Miss} Custode."
  },
  AvgDialog_131230_Content_31 = {
    Text = "Io sono la Signora del Fato. Ogni conseguenza del destino grava sulle mie spalle."
  },
  AvgDialog_131230_Content_32 = {
    Text = "Queste furono le parole che mi vennero conferite quando bussai per la prima volta al Cancello di Chokmah-Da'at. Le accettai a braccia aperte."
  },
  AvgDialog_131230_Content_33 = {
    Text = "Quindi... anche se non puoi vedere il tuo stesso destino, sapevi che tutto questo sarebbe accaduto. Tutto ciò che sta succedendo adesso... lo sapevi."
  },
  AvgDialog_131230_Content_34 = {
    Text = "La calda luce del sole bagna la strada. Mentre studi il volto sereno di Arachne e immagini il fardello che affronta ogni giorno, non puoi fare a meno di rabbrividire."
  },
  AvgDialog_131230_Content_35 = {
    Text = "L'amore porta follia. La gentilezza porta fragilità. Le memorie portano solo dolore."
  },
  AvgDialog_131230_Content_36 = {
    Text = "Anche se ti eri preparata a questo da tempo, non li hai mai veramente lasciati andare. Perché?"
  },
  AvgDialog_131230_Content_37 = {
    Text = "Lasciarli andare avrebbe reso la tua vita molto più semplice."
  },
  AvgDialog_131230_Content_38 = {
    Text = "Hai mai visitato una prigione? I detenuti rinchiusi per anni tengono sempre un piccolo tesoro vicino a sé."
  },
  AvgDialog_131230_Content_39 = {
    Text = "Una medaglia vinta in battaglia, un orologio di famiglia, una foto dei propri cari..."
  },
  AvgDialog_131230_Content_4 = {
    Text = "Il canto melodioso risuona per le strade, trasportato con grazia da una brezza leggera. I passanti sul sentiero si fermano o proseguono, assaporando la quieta vita racchiusa in questo angolo di primavera."
  },
  AvgDialog_131230_Content_40 = {
    Text = "Per un prigioniero, i desideri stessi che lo tormentano sono le uniche cose che lo tengono in vita."
  },
  AvgDialog_131230_Content_41 = {
    Text = "Conservano questi beni più preziosi fino a quando la morte non si avvicina. Solo allora cedono quegli oggetti senza valore, uno a uno."
  },
  AvgDialog_131230_Content_42 = {
    Text = "...Nella gabbia del Fato, non abbiamo nient'altro, {Male=Mr.,Female=Miss} Custode."
  },
  AvgDialog_131230_Content_43 = {
    Text = [[
<Italic:Il duolo infranga / Che il dolore spezzi
queste ritorte / queste catene>]]
  },
  AvgDialog_131230_Content_44 = {
    Text = "<Italic:de miei martiri / dei miei tormenti\nsol per pietà. / solo per pietà>"
  },
  AvgDialog_131230_Content_45 = {
    Text = "Un cantante di strada si esibisce per il fiume del Fato che attraversa la città. Arachne sorseggia il suo caffè, ascoltando con attenzione. Dall'inizio alla fine, il suo sorriso non vacilla mai."
  },
  AvgDialog_131230_Content_46 = {
    Text = "Sai, {Male=Mr.,Female=Miss} Custode, sogno spesso la stessa scena, più e più volte."
  },
  AvgDialog_131230_Content_47 = {
    Text = "È un teatro bellissimo, e ci siamo solo io e Nefraea. È sulle note di questa bella canzone che le dico addio."
  },
  AvgDialog_131230_Content_48 = {
    Text = "Vedi, anche quando non riusciamo a vedere chiaramente il nostro destino, il suo verdetto è ovunque."
  },
  AvgDialog_131230_Content_49 = {
    Text = "<Italic:E che sospiri la libertà! / E che sospiri la libertà!\nE che sospiri la libertà! / E che sospiri la libertà!>"
  },
  AvgDialog_131230_Content_5 = {
    Text = "Prendi il tuo caffè e ne bevi un lungo sorso."
  },
  AvgDialog_131230_Content_50 = {
    Text = "La voce del cantante tiene la nota mentre i fili dell'arcolaio girano eternamente. Arachne posa la tazza e si unisce al pubblico in un applauso sommesso e sincero."
  },
  AvgDialog_131230_Content_51 = {
    Text = "In ogni caso, lo spettacolo è giunto al termine. Questo palcoscenico si guadagna un breve momento di riposo. Noi, gli interpreti, dobbiamo incamminarci verso il prossimo atto."
  },
  AvgDialog_131230_Content_52 = {
    Text = "L'influenza di Nefraea si è dissipata. È possibile riaprire il passaggio per Kadath ora?"
  },
  AvgDialog_131230_Content_53 = {
    Text = "Il passaggio per Kadath giace nel destino di questo mondo. Hai già tentato di attraversare le dimensioni."
  },
  AvgDialog_131230_Content_54 = {
    Text = "Conosci già i pericoli che si celano al suo interno."
  },
  AvgDialog_131230_Content_55 = {
    Text = "Lo Sguardo di Tohuwabohu... Non ho alcun desiderio di affrontarli di nuovo."
  },
  AvgDialog_131230_Content_56 = {
    Text = "Arachne, tu controlli il Fato di questo mondo... forse hai un modo per aiutarmi?"
  },
  AvgDialog_131230_Content_57 = {
    Text = "Sarei felice di aiutarti, ma solo questa città è il mio palcoscenico. Non sono la Signora del Fato di questo intero mondo."
  },
  AvgDialog_131230_Content_58 = {
    Text = "Cosa? Non è possibile..."
  },
  AvgDialog_131230_Content_59 = {
    Text = "Il Signore di questo mondo possiede abilità che vanno oltre la mia portata. Questo mondo esiste unicamente perché Egli lo ha voluto."
  },
  AvgDialog_131230_Content_6 = {
    Text = "Neanche lontanamente paragonabile al caffè bosniaco."
  },
  AvgDialog_131230_Content_60 = {
    Text = "A meno che il passaggio non venga aperto deliberatamente, questo luogo resta celato persino allo sguardo del Primordiale... È proprio per questo che ho scelto di dimorare qui."
  },
  AvgDialog_131230_Content_61 = {
    Text = "Questo significa che aprire il portale mette in pericolo questo luogo?"
  },
  AvgDialog_131230_Content_62 = {
    Text = "Come ho detto, il Fato segue il proprio sentiero. Dimorare qui è solo una lenta attesa della morte. Aiutarti a tornare a Kadath è anche il desiderio a lungo custodito dal signore di questo mondo."
  },
  AvgDialog_131230_Content_63 = {
    Text = "Per la luce che ci attende alla fine del cammino del destino, questo è un pericolo che siamo più che disposti ad affrontare."
  },
  AvgDialog_131230_Content_64 = {
    Text = "Capito... d'accordo."
  },
  AvgDialog_131230_Content_65 = {
    Text = "Dove posso trovarlo?"
  },
  AvgDialog_131230_Content_66 = {
    Text = "I Suoi Fili del Fato sono vasti come un mare di stelle, eppure effimeri come volute di fumo. Non posso indicarti direttamente dove si trova."
  },
  AvgDialog_131230_Content_67 = {
    Text = "Ma forse questo ti sarà d'aiuto."
  },
  AvgDialog_131230_Content_68 = {
    Text = "Arachne ti porge un foglietto. Aggrotti le sopracciglia, fissando la calligrafia elegante e ornata, vergata con devozione religiosa."
  },
  AvgDialog_131230_Content_69 = {
    Text = "Annuncio di lavoro:"
  },
  AvgDialog_131230_Content_7 = {
    Text = "Mi era sembrato piuttosto buono quando l'avevo assaggiato su quel livello l'ultima volta. Purtroppo, su questo livello specifico, la famiglia che inventò quella miscela si è estinta da tempo."
  },
  AvgDialog_131230_Content_70 = {
    Text = "Il grande leader, l'Eletto del Divino, Vicario del Dio Supremo, Legittimo Erede del Grande Ordine, Salvatore dei Sofferenti e Amico Intimo del Re-Dio, è giunto a Hyperborea. La setta si sta espandendo rapidamente: i credenti sono invitati a venire a rendere omaggio."
  },
  AvgDialog_131230_Content_71 = {
    Text = "I primi dodici fedeli ad arrivare saranno ordinati santi, al fianco della Fata per sempre, benedetti dal Divino per l'eternità..."
  },
  AvgDialog_131230_Content_72 = {
    Text = "Ma che diavolo è questa roba...?"
  },
  AvgDialog_131230_Content_73 = {
    Text = "Come puoi vedere, è un opuscolo realizzato con cura."
  },
  AvgDialog_131230_Content_74 = {
    Text = "Il contenuto è incredibilmente bizzarro... Arachne, tu puoi vedere il corso del Fato: sei sicura che non sia una trappola?"
  },
  AvgDialog_131230_Content_75 = {
    Text = "Ho visto la tua sagoma su questi fili. Ne sono certa: questo è il destino che stai per incontrare."
  },
  AvgDialog_131230_Content_76 = {
    Text = "Se porterà aiuto o pericolo, non posso dirlo. Ma so che questa è l'unica connessione tra te e colui che governa questo mondo."
  },
  AvgDialog_131230_Content_77 = {
    Text = "Arachne allunga la mano verso l'assurda brochure e pizzica qualcosa di invisibile dall'aria, posandolo nel tuo palmo."
  },
  AvgDialog_131230_Content_78 = {
    Text = "E questo sarebbe...?"
  },
  AvgDialog_131230_Content_79 = {
    Text = "Ben presto, un tenue filo luccica di un debole bagliore nella tua mano."
  },
  AvgDialog_131230_Content_8 = {
    Text = "Osservi la città. L'Incrocio dei Mattoni, la Libreria della Piega del Tempo, la Drogheria del Mercato Fragrante..."
  },
  AvgDialog_131230_Content_80 = {
    Text = "Questo è il catalizzatore che ti lega a quel destino. Ti guiderà dove sei destinato a essere."
  },
  AvgDialog_131230_Content_81 = {
    Text = "Capisco. Una volta che il Senior William si sarà ripreso, noi..."
  },
  AvgDialog_131230_Content_82 = {
    Text = "Nel mio breve sguardo nei tuoi fili, ho visto una storia interessante."
  },
  AvgDialog_131230_Content_83 = {
    Text = "Non sono riuscita a vedere il tuo finale, e di questo sono lieta. Significa che ho ancora l'onore di essere spettatrice del tuo destino."
  },
  AvgDialog_131230_Content_84 = {
    Text = "Credo che nessuna storia meriti di restare inascoltata... Quindi, ti prego, non c'è bisogno di affrettarsi. Ascoltiamo quest'opera fino alla fine, {Male=Mr.,Female=Miss} Custode."
  },
  AvgDialog_131230_Content_85 = {
    Text = "La voce del cantante si riversa ancora una volta per le strade. Arachne chiude gli occhi. La luce del sole le cade sul volto sereno, dolce come tutte le primavere che ha già perduto."
  },
  AvgDialog_131230_Content_86 = {
    Text = "Il fuso gira. La canzone non si ferma mai. La gente passa, e innumerevoli fili che non puoi vedere si raccolgono e si intrecciano attorno a lei."
  },
  AvgDialog_131230_Content_87 = {
    Text = "Guardi il volto sorridente di Arachne. E vedi che accanto a lei non c'è assolutamente nulla."
  },
  AvgDialog_131230_Content_9 = {
    Text = "Tutto resta immutato. Persino le chiazze di ruggine sulle insegne dei negozi appaiono esattamente come le ricordi."
  },
  AvgDialog_131231_Content_1 = {
    Text = "Phew... appena in tempo."
  },
  AvgDialog_131231_Content_10 = {
    Text = "Sorel socchiude gli occhi, studiando Arachne. Scopre che il suo dono di leggere le persone — un'abilità di cui va particolarmente fiera — l'ha completamente tradita. Non riesce a scorgere il passato di questa donna, né a comprenderne i desideri."
  },
  AvgDialog_131231_Content_11 = {
    Text = "Ogni dettaglio che Sorel tenta di imprimere nella memoria svanisce in un batter d'occhio. Le sue labbra si incurvano in un sorriso incuriosito."
  },
  AvgDialog_131231_Content_12 = {
    Text = "Due ospiti affascinanti. Questo salotto sarà senza dubbio indimenticabile. Prego, accomodatevi."
  },
  AvgDialog_131231_Content_13 = {
    Text = "Sorel si siede sul divano e ti fa cenno di unirti a lei."
  },
  AvgDialog_131231_Content_14 = {
    Text = "Ho incrociato la strada di \"Gentilezza\" alcune volte. Venne da me in cerca di asilo."
  },
  AvgDialog_131231_Content_15 = {
    Text = "Mi avete salvata. Non riesco a scorgere le vostre vere identità, ma posso dire che non avete cattive intenzioni."
  },
  AvgDialog_131231_Content_16 = {
    Text = "Esatto, Lady Sorel. Siamo qui per salvarlo."
  },
  AvgDialog_131231_Content_17 = {
    Text = "Non è al maniero."
  },
  AvgDialog_131231_Content_18 = {
    Text = "Ma avete appena detto..."
  },
  AvgDialog_131231_Content_19 = {
    Text = "Come potete vedere, la mia tenuta non è certo un rifugio sicuro."
  },
  AvgDialog_131231_Content_2 = {
    Text = "Dopo aver controllato Karen, vi alzate e vi asciugate il sudore freddo dalla fronte."
  },
  AvgDialog_131231_Content_20 = {
    Text = "Sorel alza il braccio, indicando i cadaveri straziati sparsi per la sua stanza immacolata come se stesse esibendo una collezione pregiata."
  },
  AvgDialog_131231_Content_21 = {
    Text = "È un uomo gentile, ma tutt'altro che uno sciocco. Potevo capire che la sua situazione era disperata."
  },
  AvgDialog_131231_Content_22 = {
    Text = "Molte persone conoscono il mio legame con lui. Nasconderlo qui sarebbe stato imprudente."
  },
  AvgDialog_131231_Content_23 = {
    Text = "Dov'è adesso?"
  },
  AvgDialog_131231_Content_24 = {
    Text = "Sorel si alza e si avvicina a un dipinto a olio. La segui, osservando l'immagine."
  },
  AvgDialog_131231_Content_25 = {
    Text = "Quello è...!"
  },
  AvgDialog_131231_Content_26 = {
    Text = "Anni fa, assistetti a uno spettacolo della Compagnia di Danza Cycnus al Teatro di Londinium. Era un mero obbligo mondano, ma la sua danza mi commosse profondamente."
  },
  AvgDialog_131231_Content_27 = {
    Text = "Nel corso degli anni, ho fatto visita di tanto in tanto ai camerini. Non abbiamo alcun legame pubblico, il che rende la sua compagnia il luogo perfetto per nascondere \"Gentilezza.\""
  },
  AvgDialog_131231_Content_28 = {
    Text = "Nel dipinto, Liz indossa un etereo costume da danza, slanciata in aria come un cigno in volo."
  },
  AvgDialog_131231_Content_29 = {
    Text = "Liz... dov'è la sua compagnia adesso?"
  },
  AvgDialog_131231_Content_3 = {
    Text = "Karen dovrebbe stare bene. È stata colpita dalla possessione, ma si riprenderà con un po' di riposo."
  },
  AvgDialog_131231_Content_30 = {
    Text = "Arachne segue i Fili del Fato che si stringono, volgendo lo sguardo dalla finestra verso un punto celato nel profondo del bosco."
  },
  AvgDialog_131231_Content_31 = {
    Text = "In un luogo che conoscete fin troppo bene."
  },
  AvgDialog_131231_Content_4 = {
    Text = "Riesco a ricordare ogni volto che abbia mai visto, eppure voi mi risultate... strano. Non riesco a stabilire con certezza se ci siamo già incontrati. Non mi era mai successo prima."
  },
  AvgDialog_131231_Content_5 = {
    Text = "Sorel raccoglie una bottiglia rimasta in piedi sul tavolo e versa da bere. Scavalcando i cadaveri in dissoluzione, vi porge il bicchiere."
  },
  AvgDialog_131231_Content_6 = {
    Text = "Un Porto di quarant'anni dalla mia collezione privata. Le iene al piano di sotto non meritano nemmeno una goccia. Chiunque voi siate, credo che questo bicchiere vi appartenga."
  },
  AvgDialog_131231_Content_7 = {
    Text = "Siamo qui per \"Gentilezza,\" Lady Sorel."
  },
  AvgDialog_131231_Content_8 = {
    Text = "Arachne prende il bicchiere e accenna un piccolo, cortese cenno del capo."
  },
  AvgDialog_131231_Content_9 = {
    Text = "Quando tace, è impercettibile come una ragnatela nella luce del mattino. Ma nel momento in cui parla, sembra attirare verso di sé ogni briciolo di luminosità nella stanza."
  },
  AvgDialog_131232_Content_1 = {
    Text = "Che spettacolo magnifico, sorella."
  },
  AvgDialog_131232_Content_10 = {
    Text = "Tu e i tuoi scudieri siete coloro privi di destino; non riesco ad afferrare i vostri fili. Ma poiché il vostro potere ha origine dal mio, siete ciechi al vostro stesso fato quanto io lo sono al mio."
  },
  AvgDialog_131232_Content_11 = {
    Text = "Tu e io... siamo in una situazione di stallo. Una guerra insensata che non sarebbe mai dovuta cominciare."
  },
  AvgDialog_131232_Content_12 = {
    Text = "Ma certo, certo. Per te, noi \"cose scartate\" apparteniamo al cimitero del Fato — da smantellare, dimenticare e dissolvere per l'eternità."
  },
  AvgDialog_131232_Content_13 = {
    Text = "Che peccato che tu non possa vedere 'Lui'... Per quanto grande sia il tuo potere, come potresti mai paragonarti alla Divinità Suprema?"
  },
  AvgDialog_131232_Content_14 = {
    Text = "Lo sai. Lo sai nel profondo che tutto questo è futile. Eppure, non riesci a smettere di tessere la tua tela..."
  },
  AvgDialog_131232_Content_15 = {
    Text = "Poiché hai visto i fili, non sopporti vederli aggrovigliati. Poiché possiedi il potere, non riesci a restare a guardare mentre i mondi sprofondano in un caos senza fine."
  },
  AvgDialog_131232_Content_16 = {
    Text = "Offri loro una pace illusoria mentre li conduci lungo un sentiero che termina solo in rovina."
  },
  AvgDialog_131232_Content_17 = {
    Text = "Che creatura pietosa sei, Arachne."
  },
  AvgDialog_131232_Content_18 = {
    Text = "Questo è il nostro destino, Nefraea."
  },
  AvgDialog_131232_Content_19 = {
    Text = "Ah... mi sta venendo sonno. Discutere con una sciocca è la cosa più tediosa al mondo."
  },
  AvgDialog_131232_Content_2 = {
    Text = "Il vivace bar cade nel silenzio. I cadaveri sparsi sul pavimento si dissolvono in melma nera e polvere, svanendo sotto le luci calde."
  },
  AvgDialog_131232_Content_20 = {
    Text = "Benvenuto al Secondo Atto. Questo è il tuo livello, ma d'ora in poi sarò io a scrivere il copione."
  },
  AvgDialog_131232_Content_21 = {
    Text = "Le note d'apertura sono le più importanti, non è vero? Come dovremmo chiamarlo... che ne dici di \"Ricongiungimento\"?"
  },
  AvgDialog_131232_Content_22 = {
    Text = "Nefraea sembra deliziata dal nome. Immerge un arto simile a quello di un ragno nella sua bevanda, lo assaggia e lascia sfuggire un sospiro di beatitudine."
  },
  AvgDialog_131232_Content_23 = {
    Text = "Mi sono preparata così a lungo per questo giorno. Assaporerò ogni istante della nostra storia insieme, cara sorella."
  },
  AvgDialog_131232_Content_24 = {
    Text = "Senza darti la possibilità di interrogarla oltre, Nefraea sfiora la guancia di Arachne con un'unghia affilata e poi crolla al suolo."
  },
  AvgDialog_131232_Content_25 = {
    Text = "Aspetta...!"
  },
  AvgDialog_131232_Content_26 = {
    Text = "Lei non è qui, {Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_131232_Content_27 = {
    Text = "Con un suono gorgogliante, una fanghiglia nera si stacca ancora una volta dal volto del cadavere."
  },
  AvgDialog_131232_Content_28 = {
    Text = "Gli occhi di Romance restano fissi in un sorriso, anche mentre ragni neri strisciano attraverso il suo corpo svuotato, visibili dietro il suo sguardo velato. Le sue labbra eleganti non parleranno mai più."
  },
  AvgDialog_131232_Content_29 = {
    Text = "Quello è..."
  },
  AvgDialog_131232_Content_3 = {
    Text = "Nefraea e Arachne restano sedute l'una di fronte all'altra. Nefraea prepara un cocktail e lo fa scivolare verso la sorella."
  },
  AvgDialog_131232_Content_30 = {
    Text = "Ha assassinato questa Marionetta. Ha lasciato il suo marchio, contaminato il suo fato, e l'ha usata come un ricettacolo temporaneo."
  },
  AvgDialog_131232_Content_31 = {
    Text = "Arachne si avvicina alla Marionetta e allunga la mano verso la sua testa, fissando il filo del fato ormai quasi svanito."
  },
  AvgDialog_131232_Content_32 = {
    Text = "...Riesci a vedere qualcosa?"
  },
  AvgDialog_131232_Content_33 = {
    Text = "Anche le altre Marionette sono state contaminate; non riesco più a percepirle attraverso la Grande Ragnatela. Ma il fato di Romance era connesso al loro."
  },
  AvgDialog_131232_Content_34 = {
    Text = "Mi ha mostrato dove trovare \"Gentilezza.\""
  },
  AvgDialog_131232_Content_35 = {
    Text = "Arachne rilascia il filo e risistemava delicatamente la frangia di Romance al suo posto."
  },
  AvgDialog_131232_Content_36 = {
    Text = "Il potere di Nefraea è derivato dal mio. Non posso vedere i fati che ha contaminato, e le mie stesse capacità ne sono ostacolate."
  },
  AvgDialog_131232_Content_37 = {
    Text = "Tu sei un frammento del Divino — uno il cui fato è invisibile a noi. Ecco perché ho bisogno del tuo aiuto, {Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_131232_Content_38 = {
    Text = "Non preoccuparti. Non fosse altro che per tornare a Kadath, devo occuparmi di lei."
  },
  AvgDialog_131232_Content_39 = {
    Text = "Perché dà la caccia a queste Marionette?"
  },
  AvgDialog_131232_Content_4 = {
    Text = "Anche se la signorina \"Romance\" non c'è più, non dovremmo sprecare un buon drink."
  },
  AvgDialog_131232_Content_40 = {
    Text = "Queste Marionette diventeranno la fonte del suo potere."
  },
  AvgDialog_131232_Content_41 = {
    Text = "Allora dobbiamo agire in fretta. Dobbiamo trovare le Marionette e le braci dimensionali di cui hai bisogno per tessere."
  },
  AvgDialog_131232_Content_42 = {
    Text = "Questa Marionetta chiamata \"Gentilezza\"... dov'è?"
  },
  AvgDialog_131232_Content_43 = {
    Text = "Romance è riuscita ad avvertirlo del pericolo prima di cadere. Ora è nascosto, protetto da un tuo vecchio amico."
  },
  AvgDialog_131232_Content_44 = {
    Text = "Un vecchio amico...?"
  },
  AvgDialog_131232_Content_45 = {
    Text = "Seguimi, {Male=Sig.,Female=Sig.na} Custode. Il gran salone di Lady Sorel sta per avere inizio."
  },
  AvgDialog_131232_Content_5 = {
    Text = "Ne vuoi un sorso? Ti conosco molto meglio di quanto quella Doll avrebbe mai potuto."
  },
  AvgDialog_131232_Content_6 = {
    Text = "Arachne non esita. Sorride, solleva il bicchiere e ne sorseggia un raffinato sorso."
  },
  AvgDialog_131232_Content_7 = {
    Text = "Non sei fatta per questo mestiere, Nefraea. Questa bevanda non ha nulla da offrire se non amarezza."
  },
  AvgDialog_131232_Content_8 = {
    Text = "Lo chiamo \"Fato.\" Ti piace il sapore?"
  },
  AvgDialog_131232_Content_9 = {
    Text = "Arachne ignora lo sguardo carico d'attesa negli occhi di Nefraea. Finisce il cocktail lentamente e posa il bicchiere sul tavolo."
  },
  AvgDialog_132684_Content_1 = {
    Text = "<Small:<LightGray:...? Cip...? (Hmm...?)>>"
  },
  AvgDialog_132684_Content_10 = {
    Text = "Esatto. E dato che Mythag ha una sua orgogliosa tradizione di scherzi leggeri in questo giorno, la scuola non punirà nessuno per uno \"scherzo\" così innocuo."
  },
  AvgDialog_132684_Content_11 = {
    Text = "Cip! Cip, cip—! <Small:<LightGray:(Maestra Doll, mi stai stringendo la mano e la faccia, mi stai strofinando la faccia, vero!)>>"
  },
  AvgDialog_132684_Content_12 = {
    Text = "Il suo tono resta freddo e tagliente come sempre. Eppure, sei assolutamente certo/a che gli angoli della bocca di Doll si siano sollevati di non meno di 2 millimetri."
  },
  AvgDialog_132684_Content_13 = {
    Text = "Mi scuso, Custode. Il traduttore a tecnologia d'Argento sembra avere qualche difficoltà. Non c'è bisogno di preoccuparsi però; il reagente dovrebbe essere pronto entro domani mattina."
  },
  AvgDialog_132684_Content_14 = {
    Text = "Fissi Doll a bocca aperta, incredulo/a. Anche con il cervello di una lontra marina, puoi chiaramente vedere che i reagenti posati proprio dietro di lei sono completamente pronti."
  },
  AvgDialog_132684_Content_15 = {
    Text = "Professoressa. Cerca Vortice?"
  },
  AvgDialog_132684_Content_16 = {
    Text = "!! Carbonella—"
  },
  AvgDialog_132684_Content_17 = {
    Text = "Cip— <Small:<LightGray:(Capo—)>>"
  },
  AvgDialog_132684_Content_18 = {
    Text = "Per coincidenza, abbiamo personale con ampia esperienza diretta nella gestione di questa particolare specie. Credo che un'intera giornata in loro compagnia sarà tremendamente istruttiva per il nostro Custode."
  },
  AvgDialog_132684_Content_19 = {
    Text = "Vortice. %player% è sotto la tua responsabilità oggi. Cerca di non perdere {Male=him,Female=her}."
  },
  AvgDialog_132684_Content_2 = {
    Text = "<Italic:*saltello* *saltello* *saltello*>"
  },
  AvgDialog_132684_Content_20 = {
    Text = "<Italic:*esultanza fragorosa*> SÌ!! Carbonella!! Andiamo andiamo ANDIAMO!!"
  },
  AvgDialog_132684_Content_21 = {
    Text = "Cip! <Small:<LightGray:(Giochiamo insieme!)>>"
  },
  AvgDialog_132684_Content_22 = {
    Text = "Cip— <Small:<LightGray:(No, Ramona, salvami—)>>"
  },
  AvgDialog_132684_Content_23 = {Text = "Ehm."},
  AvgDialog_132684_Content_24 = {
    Text = "Partner, non c'è nulla di importante in programma per oggi. Per favore, non preoccuparti."
  },
  AvgDialog_132684_Content_25 = {
    Text = "Naturalmente dedicherò del tempo oggi per garantire la tua sicurezza e il tuo benessere."
  },
  AvgDialog_132684_Content_26 = {
    Text = "...Detto ciò, è palesemente ovvio che lei, proprio come Vortice, è già stata completamente e irrimediabilmente sconfitta da quanto è irragionevolmente morbida la tua pelliccia."
  },
  AvgDialog_132684_Content_27 = {
    Text = "Cip, cip cip cip cip……<Small:<LightGray:(C'è qualcuno che possa venire in aiuto, William……)>>"
  },
  AvgDialog_132684_Content_28 = {
    Text = "Per inciso—William è in missione sul campo oggi e non tornerà fino a tardi."
  },
  AvgDialog_132684_Content_29 = {
    Text = "*beve il tè <Small:<LightGray:(Ah, che rara occasione. Il mio studente più problematico, ma anche il più importante — lascia perdere tutto e Relax per un giorno intero.)>>"
  },
  AvgDialog_132684_Content_3 = {
    Text = "<Italic:*si strofina vigorosamente il muso*>"
  },
  AvgDialog_132684_Content_30 = {
    Text = "Nel frattempo, un certo Senior, da qualche parte lontano..."
  },
  AvgDialog_132684_Content_31 = {Text = "ETCIÙ!!"},
  AvgDialog_132684_Content_32 = {
    Text = "...Strano. Ho una bruttissima sensazione all'improvviso."
  },
  AvgDialog_132684_Content_33 = {
    Text = "Torno prima oggi."
  },
  AvgDialog_132684_Content_34 = {
    Text = "Il Pesce d'Aprile a Mythag trascorre pacificamente. Più o meno."
  },
  AvgDialog_132684_Content_35 = {
    Text = "Meraviglioso. Davvero, assolutamente meraviglioso."
  },
  AvgDialog_132684_Content_4 = {Text = "???!!!"},
  AvgDialog_132684_Content_5 = {
    Text = "Cip cip cip cip cip! Uiii uiii uiii uiii uiii!!! <Small:<LightGray:(Sono diventata una lontra marina! Ramona, aiutami!)>>"
  },
  AvgDialog_132684_Content_6 = {Text = "..."},
  AvgDialog_132684_Content_7 = {
    Text = "Buone notizie: gli effetti di questo... \"Spray di Lontrificazione d'Emergenza\" sono completamente reversibili, e l'antidoto è imbarazzantemente semplice da preparare. Chiunque l'abbia fatto chiaramente non intendeva fare del male."
  },
  AvgDialog_132684_Content_8 = {
    Text = "Notizia ancora migliore: hai usato il regalo di quella piccola bugiarda senza pensarci due volte. Onestamente? Prendere in prestito temporaneamente il cervello di una lontra potrebbe farti bene."
  },
  AvgDialog_132684_Content_9 = {
    Text = "Quindi... questa \"conversione temporanea\" non causerà alcun danno al Custode?"
  },
  AvgDialog_13733_Content_1 = {
    Text = "Rito Vermiglio"
  },
  AvgDialog_13733_Content_10 = {
    Text = "Heh, non si può mai fare affidamento sulla perspicacia dei Remouani. Tieni gli occhi ben aperti e osserva..."
  },
  AvgDialog_13733_Content_11 = {
    Text = "Purin estrasse un coltello rituale dalla manica e, senza esitazione, si tagliò il polso."
  },
  AvgDialog_13733_Content_12 = {
    Text = "Sangue Cremisi gocciolò, goccia dopo goccia, sul cerchio rituale tracciato con lo zolfo, e proprio così, un Miracolo avvenne—"
  },
  AvgDialog_13733_Content_13 = {
    Text = "Come una goccia d'acqua che converge in un deserto arido, il cerchio rituale, avendo Assorbito il Sangue fresco, emise rapidamente anello dopo anello di luce cremisi scura."
  },
  AvgDialog_13733_Content_14 = {
    Text = "Erano come fiamme sotto un cielo annerito, che lambivano avidamente la sabbia gialla spazzata dal Vento, come se cercassero di divorare l'intera Terra nelle loro fauci."
  },
  AvgDialog_13733_Content_15 = {
    Text = "Lo vedi? Questo è il vero momento della magia! Hahahaha!"
  },
  AvgDialog_13733_Content_16 = {
    Text = "Hahaha... <Big:GAAAH!!!>"
  },
  AvgDialog_13733_Content_17 = {
    Text = "Purin crollò in ginocchio con un tonfo, le mani che involontariamente si stringevano attorno alla propria gola."
  },
  AvgDialog_13733_Content_18 = {
    Text = "Le catene che lo collegano a Uvhash si tendono rapidamente, stringendo carne e anime insieme in modo serrato."
  },
  AvgDialog_13733_Content_19 = {
    Text = "Ngh... Cosa...?"
  },
  AvgDialog_13733_Content_2 = {
    Text = [[
Margine del Deserto di Kuxi
Sito Rituale]]
  },
  AvgDialog_13733_Content_20 = {
    Text = "Uvhash non riusciva più a mantenere la sua postura rilassata."
  },
  AvgDialog_13733_Content_21 = {
    Text = "Fu scaraventato da un Potere invisibile, fissando con sguardo un po' stordito il cerchio rituale davanti a lui che era sul punto di perdere il controllo."
  },
  AvgDialog_13733_Content_22 = {Text = "Ugh..."},
  AvgDialog_13733_Content_23 = {
    Text = "<Big:AAAAAGH!>"
  },
  AvgDialog_13733_Content_24 = {
    Text = "Purin giaceva disteso a terra, fissando con ferocia la figura di Uvhash che si dibatteva, e lasciò sfuggire una risata sinistra."
  },
  AvgDialog_13733_Content_25 = {
    Text = "Fa male... Bene, deve fare male..."
  },
  AvgDialog_13733_Content_26 = {
    Text = "In questo momento, le nostre coscienze sono legate strettamente insieme..."
  },
  AvgDialog_13733_Content_27 = {
    Text = "Hai visto come i cani Remouahe hanno massacrato i miei simili e profanato mia moglie... l'hai sentito..."
  },
  AvgDialog_13733_Content_28 = {
    Text = "<Big:Rispondimi, stupida creatura non migliore di @1!>"
  },
  AvgDialog_13733_Content_29 = {Text = "Heh heh..."},
  AvgDialog_13733_Content_3 = {
    Text = "Bene, prima cospargere uno strato di zolfo, poi la polvere di carbone..."
  },
  AvgDialog_13733_Content_30 = {
    Text = "Non cantare vittoria troppo presto... vecchio stolto."
  },
  AvgDialog_13733_Content_31 = {
    Text = "Quando mi libererò di queste Catene, sarai il primo che farò a pezzi— Mmph!!"
  },
  AvgDialog_13733_Content_32 = {
    Text = "Che sfortuna. Temo che questa volta il tuo desiderio non si avvererà…"
  },
  AvgDialog_13733_Content_33 = {
    Text = "Purin boccheggiò in cerca d'aria, le mani tremanti strette attorno alla catena invisibile, poi la strattonò con violenza—"
  },
  AvgDialog_13733_Content_34 = {
    Text = "La catena un tempo infrangibile si spezzò, proprio così."
  },
  AvgDialog_13733_Content_35 = {
    Text = "Heh heh@3AHHH@1AHHH!!"
  },
  AvgDialog_13733_Content_36 = {
    Text = "Purin emette un grido di agonia mentre la carne sul suo viso marcisce e si stacca come corteccia, rivelando la carne viva sottostante."
  },
  AvgDialog_13733_Content_37 = {
    Text = "Il cerchio magico apre la sua oscura e spalancata fauci, divorando la sua carne pezzo per pezzo finché il mago non è ridotto a uno scheletro vuoto."
  },
  AvgDialog_13733_Content_38 = {
    Text = "Ho sacrificato la mia carne, la mia anima e tutto... e tu?"
  },
  AvgDialog_13733_Content_39 = {
    Text = "Non raggiungerai mai la vera libertà finché non avrai ucciso 10.000 cani Remouahe!"
  },
  AvgDialog_13733_Content_4 = {
    Text = "No, non è giusto. Fammi controllare cosa dice il libro..."
  },
  AvgDialog_13733_Content_40 = {
    Text = "Uvhash si alzò lentamente in piedi."
  },
  AvgDialog_13733_Content_41 = {
    Text = "Il suo volto era stato bruciato in uno Scheletro Cinereo annerito da fiamme invisibili, che si sgretolava a ogni raffica di Vento."
  },
  AvgDialog_13733_Content_42 = {Text = "Heh..."},
  AvgDialog_13733_Content_43 = {
    Text = "\"Vera libertà\"…? Che diavolo sarebbe?"
  },
  AvgDialog_13733_Content_44 = {
    Text = "Il guerriero bruciato si ergeva fiero tra le fiamme ardenti. I suoi occhi erano rosso cremisi, e dalla gola gli sfuggiva solo un rauco Scuotimento."
  },
  AvgDialog_13733_Content_45 = {
    Text = "C'è sempre stata una sola cosa che a me, Uvhash, importa davvero—"
  },
  AvgDialog_13733_Content_46 = {
    Text = "Si lanciò in avanti a velocità accecante, placcando il mago a terra."
  },
  AvgDialog_13733_Content_47 = {
    Text = "Poi mostrò le sue zanne affilate e azzannò selvaggiamente il collo del mago."
  },
  AvgDialog_13733_Content_48 = {
    Text = "<Red:Ed è il Sangue!!>"
  },
  AvgDialog_13733_Content_49 = {
    Text = "Signor Purin!"
  },
  AvgDialog_13733_Content_5 = {
    Text = "A meno di cinquanta iarde dal campo di battaglia, Purin era indaffarato al lavoro."
  },
  AvgDialog_13733_Content_50 = {
    Text = "<Shake:Questa vita… è tua… Vendicami@2Aiutami…>"
  },
  AvgDialog_13733_Content_51 = {
    Text = "Aiutarti? Vecchio, devi essere confuso…"
  },
  AvgDialog_13733_Content_52 = {
    Text = "La preda non ha il diritto di fare richieste a me, Uvhash."
  },
  AvgDialog_13733_Content_53 = {
    Text = "Il motivo per cui ti ho ascoltato docilmente è perché posso distruggere il tuo giocattolino a catena quando voglio — non per quella stronzata di contratto che abbiamo firmato."
  },
  AvgDialog_13733_Content_54 = {
    Text = "Il gioco è finito. Ora, voglio che spalanchi bene gli occhi e guardi attentamente—"
  },
  AvgDialog_13733_Content_55 = {
    Text = "Mentre massacro i tuoi nemici, i tuoi compatrioti e ogni essere vivente in vista…"
  },
  AvgDialog_13733_Content_56 = {
    Text = "<Change>Demonio… sei un demonio…"
  },
  AvgDialog_13733_Content_57 = {
    Text = "Il Sangue di Purin scorreva liberamente attraverso il cerchio rituale, facendo sembrare persino quelle luci cremisi incomparabilmente fioche."
  },
  AvgDialog_13733_Content_58 = {
    Text = "Ha sacrificato la propria vita in cambio della libertà di Uvhash."
  },
  AvgDialog_13733_Content_59 = {
    Text = "Hehe… Ahhh@4…"
  },
  AvgDialog_13733_Content_6 = {
    Text = "Uvhash, su richiesta di Purin, sedeva eretto al centro di un cerchio rituale tracciato con polvere di zolfo."
  },
  AvgDialog_13733_Content_60 = {
    Text = "Uvhash alzò lentamente la testa. Il Sangue indugiava ancora agli angoli della sua bocca, non ancora leccato via, e i suoi occhi erano stati da tempo consumati dall'Oscurità."
  },
  AvgDialog_13733_Content_61 = {
    Text = "Era diventato una vera Bestia. O forse, questo era il suo vero volto da sempre."
  },
  AvgDialog_13733_Content_62 = {
    Text = "<Red:È tornato, è tornato tutto…>"
  },
  AvgDialog_13733_Content_7 = {
    Text = "Huff... huff..."
  },
  AvgDialog_13733_Content_8 = {
    Text = "Impressionante, riuscire ad addormentarsi in una situazione come questa..."
  },
  AvgDialog_13733_Content_9 = {
    Text = "Ho una domanda tecnica da porre, signor Purin.\nLa polvere che hai sparso non verrà semplicemente spazzata via dal Vento?"
  },
  AvgDialog_13734_Content_1 = {
    Text = [[
Uff... Finalmente ti ho raggiunto.
Ti avverto, Uvhash, dovresti conoscere le conseguenze dell'avermi lasciato indietro, giusto?]]
  },
  AvgDialog_13734_Content_10 = {
    Text = "Avevi finalmente raggiunto la destinazione di questo viaggio. Purin emise un paio di strane risate dalla gola, le fiamme della vendetta facevano tremare tutto il suo corpo."
  },
  AvgDialog_13734_Content_11 = {
    Text = "<Shake:Andiamo, Uvhash...>"
  },
  AvgDialog_13734_Content_12 = {
    Text = "<Red:Uccidiamo a sazietà.>"
  },
  AvgDialog_13734_Content_2 = {Text = "Shh!!"},
  AvgDialog_13734_Content_3 = {
    Text = "Uvhash era accovacciato in cima a un'alta duna di sabbia, emettendo un sibilo impaziente dalle narici, come una Bestia concentrata sulla caccia infastidita da una Molestia."
  },
  AvgDialog_13734_Content_4 = {
    Text = "Le sue labbra erano leggermente dischiuse, le narici fremevano appena, e il bagliore rosso sangue nei suoi occhi era più intenso che mai."
  },
  AvgDialog_13734_Content_5 = {
    Text = "<RedShake:Trovato, trovato...>"
  },
  AvgDialog_13734_Content_6 = {
    Text = "Seguisti il suo sguardo verso il basso—"
  },
  AvgDialog_13734_Content_7 = {
    Text = "Innumerevoli piccoli puntini neri erano sparsi sulle dune di sabbia ondulate, come formiche che strisciavano su un plastico di sabbia."
  },
  AvgDialog_13734_Content_8 = {
    Text = "Il fragore delle lame, le grida ruggenti e il tuonare degli zoccoli si alzavano e cadevano a ondate, mentre un grande arazzo di guerra si dispiegava lentamente davanti ai tuoi occhi."
  },
  AvgDialog_13734_Content_9 = {
    Text = "Remouani, Leoniani... Bene, molto bene."
  },
  AvgDialog_13735_Content_1 = {
    Text = "Spedizione solare"
  },
  AvgDialog_13735_Content_10 = {
    Text = "Era ancora legato da catene invisibili, costretto a sedersi a gambe incrociate a terra in una postura scomoda, la sua intera figura quasi fusa in un tutt'uno con l'oscurità."
  },
  AvgDialog_13735_Content_11 = {
    Text = "...Non mi aspettavo che fossi ancora sveglio."
  },
  AvgDialog_13735_Content_12 = {
    Text = "Un <Yellow:golem> non ha bisogno di dormire."
  },
  AvgDialog_13735_Content_13 = {Text = "Golem...?"},
  AvgDialog_13735_Content_14 = {
    Text = "Heh heh... Smettila di fingere."
  },
  AvgDialog_13735_Content_15 = {
    Text = "Puoi vedere le catene su di me, quindi sicuramente devi sapere cos'è un golem."
  },
  AvgDialog_13735_Content_16 = {
    Text = [[
Non ti aspettavi che quella tua occhiata apparentemente casuale di allora fosse stata notata da lui.
Ha davvero l'istinto di una Bestia.]]
  },
  AvgDialog_13735_Content_17 = {
    Text = "Il mio maestro una volta mi disse..."
  },
  AvgDialog_13735_Content_18 = {
    Text = "Durante l'antica era romana, un alchimista folle creò il primo golem al costo di un gran numero di sacrifici umani."
  },
  AvgDialog_13735_Content_19 = {
    Text = "È anche l'esistenza più vicina a un Risvegliatore che si possa trovare nei testi antichi."
  },
  AvgDialog_13735_Content_2 = {
    Text = "Deserto di Kushi settentrionale, Notte"
  },
  AvgDialog_13735_Content_20 = {
    Text = "Quel golem... eri tu, vero?"
  },
  AvgDialog_13735_Content_21 = {
    Text = "Esatto... Ero io. Divenni il cagnolino di <Blue:Caligola> e uccisi molte persone per lui."
  },
  AvgDialog_13735_Content_22 = {
    Text = "In seguito, non ebbero più bisogno di me, così mi rinchiusero sottoterra nell'oscurità più totale, finché quello non mi liberò."
  },
  AvgDialog_13735_Content_23 = {
    Text = "Mentre Uvhash parlava, il suo sguardo scivolò su Purin, che dormiva ancora profondamente nella tenda."
  },
  AvgDialog_13735_Content_24 = {
    Text = "—La condizione?"
  },
  AvgDialog_13735_Content_25 = {
    Text = "La condizione è servirlo come un cane e uccidere molti Remouahe sul campo di battaglia."
  },
  AvgDialog_13735_Content_26 = {
    Text = "Poi ci separiamo, ognuno per la propria strada."
  },
  AvgDialog_13735_Content_27 = {
    Text = "Uvhash si stiracchiò comodamente, allargando le gambe mentre si appoggiava alla duna di sabbia."
  },
  AvgDialog_13735_Content_28 = {
    Text = "Catene di questo calibro non possono certo trattenerti. Perché non uccidi semplicemente lo stregone e te ne vai?"
  },
  AvgDialog_13735_Content_29 = {
    Text = "Perché ha detto che sul campo di battaglia ci sarebbero state molte persone."
  },
  AvgDialog_13735_Content_3 = {
    Text = "Zzz… Zzz… Wheeze…"
  },
  AvgDialog_13735_Content_30 = {
    Text = "<Red:Dove ci sono molte persone, ci sarà molto Sangue.>"
  },
  AvgDialog_13735_Content_31 = {
    Text = "<RedShake:Devi sapere che è passato quasi un millennio dall'ultima volta che ho assaggiato quel Sangue…>"
  },
  AvgDialog_13735_Content_32 = {Text = "..."},
  AvgDialog_13735_Content_33 = {
    Text = "Quel tizio non sembra il tipo che mantiene le promesse. E se ti stesse mentendo?"
  },
  AvgDialog_13735_Content_34 = {
    Text = "Allora lo ucciderò. Semplice, no?"
  },
  AvgDialog_13735_Content_35 = {Text = "..."},
  AvgDialog_13735_Content_36 = {
    Text = "Devi ammettere che le sue parole hanno molto senso."
  },
  AvgDialog_13735_Content_37 = {
    Text = "Il Vento della sera soffia dolcemente mentre le dune ondulate si estendono all'infinito davanti a te. Sotto il cielo sconfinato, rimangono solo due minuscole figure."
  },
  AvgDialog_13735_Content_38 = {
    Text = "Alzi la testa, volgendo lo sguardo verso il cielo stellato."
  },
  AvgDialog_13735_Content_39 = {
    Text = "Per trascorrere questa lunga notte, decidi di scambiare qualche pensiero ed esperienza con questo golem che hai davanti."
  },
  AvgDialog_13735_Content_4 = {
    Text = "Un russare fragoroso riempie la notte silenziosa. Sembra che il piccolo incidente durante il giorno non abbia minimamente intaccato il sonno profondo di Purin."
  },
  AvgDialog_13735_Content_40 = {
    Text = "Essere rinchiuso sottoterra dev'essere stato terribile.\nUna volta adempiuto l'accordo, riacquisterai la tua libertà. Come ti senti adesso?"
  },
  AvgDialog_13735_Content_41 = {
    Text = [[
E tu?
Neanche tu sei stato schiavo per molto tempo. Vagare nel deserto giorno dopo giorno, tirando avanti a stento... come ci si sente?]]
  },
  AvgDialog_13735_Content_42 = {Text = "..."},
  AvgDialog_13735_Content_43 = {
    Text = "Non benissimo, a dire il vero. In questo posto dimenticato da Dio, non si riesce nemmeno a vedere il Sole…"
  },
  AvgDialog_13735_Content_44 = {
    Text = "Sei cieco? Non riesci a vedere quell'enorme Sole nel deserto?"
  },
  AvgDialog_13735_Content_45 = {
    Text = "Non capisci. Parlo del tipo di Sole che è gentile, luminoso e caldo quando ti illumina… Quello non lo trovi nel deserto."
  },
  AvgDialog_13735_Content_46 = {
    Text = "Lasci sfuggire uno sbadiglio mentre la sonnolenza si insinua gradualmente.\nCon la guardia leggermente abbassata, la conversazione diventa molto più informale."
  },
  AvgDialog_13735_Content_47 = {
    Text = "Con tua sorpresa, Uvhash si rivela un ascoltatore passabile."
  },
  AvgDialog_13735_Content_48 = {
    Text = "Potresti non crederci, ma in realtà anch'io ho una missione tutta mia…"
  },
  AvgDialog_13735_Content_49 = {
    Text = "Una volta finito tutto quello che c'è da fare, troverò sicuramente un posto dove sdraiarmi a crogiolarmi al Sole, e mangiare tante, tantissime tortine…"
  },
  AvgDialog_13735_Content_5 = {
    Text = "Non riuscendo più a sopportarlo, alla fine spalanchi il lembo della tenda e esci fuori."
  },
  AvgDialog_13735_Content_50 = {
    Text = "…Difficile da capire."
  },
  AvgDialog_13735_Content_51 = {
    Text = "I golem nascono dall'Oscurità, temendo per natura la luce del sole. Quasi un millennio di prigionia non aveva fatto altro che acuire la sua avversione."
  },
  AvgDialog_13735_Content_52 = {
    Text = "Mi fai davvero pena. Crogiolarsi al Sole è la cosa più meravigliosa del mondo..."
  },
  AvgDialog_13735_Content_53 = {
    Text = "Purtroppo per me, anche un desiderio così semplice è difficile da realizzare..."
  },
  AvgDialog_13735_Content_54 = {
    Text = "Il Vento si alzò.\nSabbia fine alla deriva tesseva velo su velo di un pallido dorato, fluttuando dolcemente sotto il cielo notturno colmo di Stelle."
  },
  AvgDialog_13735_Content_55 = {
    Text = "Ascoltando il suono limpido del Vento in lontananza, scivolasti infine nel Sogno."
  },
  AvgDialog_13735_Content_56 = {Text = "..."},
  AvgDialog_13735_Content_57 = {
    Text = "Deserto di Kushi settentrionale, Giorno"
  },
  AvgDialog_13735_Content_58 = {
    Text = "Ma che diavolo?! Non avevi giurato e spergiurato che non ci sarebbero state tempeste di sabbia nei prossimi giorni?!"
  },
  AvgDialog_13735_Content_59 = {
    Text = "Purin spalancò gli occhi, indicando la sabbia furiosa che avanzava dall'orizzonte."
  },
  AvgDialog_13735_Content_6 = {
    Text = "Che meraviglia…"
  },
  AvgDialog_13735_Content_60 = {
    Text = "Adesso dimmi, <Big:cos'@1è QUELLO?>"
  },
  AvgDialog_13735_Content_61 = {Text = "Uh..."},
  AvgDialog_13735_Content_62 = {
    Text = "Prima che entrassi in Morpheus, il proprietario originale aveva effettivamente fatto alcune promesse poco sincere pur di spennare questa gallina dalle uova d'oro."
  },
  AvgDialog_13735_Content_63 = {
    Text = "Non è il momento di discutere. La tempesta di sabbia sta arrivando — corri!"
  },
  AvgDialog_13735_Content_64 = {
    Text = "Detto ciò, scattasti a tutta velocità, lasciando Purin molto indietro."
  },
  AvgDialog_13735_Content_65 = {
    Text = "<Big:Ehi... Torna qui!>"
  },
  AvgDialog_13735_Content_66 = {
    Text = "Tempesta di sabbia? Cos'è? A me il panorama sembra piuttosto carino."
  },
  AvgDialog_13735_Content_67 = {
    Text = "Uvhash ti raggiunse senza sforzo correndo all'indietro, con gli occhi fissi in lontananza senza battere ciglio."
  },
  AvgDialog_13735_Content_68 = {
    Text = "Non hai mai visto una tempesta di sabbia?"
  },
  AvgDialog_13735_Content_69 = {
    Text = "Uvhash scrollò le spalle."
  },
  AvgDialog_13735_Content_7 = {
    Text = "Buonasera, signor Guida."
  },
  AvgDialog_13735_Content_70 = {
    Text = "In passato il mio raggio d'azione era limitato alla città di Roma. Ci sono fin troppe cose che non ho mai visto."
  },
  AvgDialog_13735_Content_71 = {
    Text = "<Shake:Ugh... Blurgh...>"
  },
  AvgDialog_13735_Content_72 = {
    Text = "Trascinata dalle catene, Purin, rimasta molto indietro, fu strappata da terra e lanciata in aria."
  },
  AvgDialog_13735_Content_73 = {
    Text = "<Shake:R-Rallenta... Sto morendo qui...>"
  },
  AvgDialog_13735_Content_74 = {
    Text = "Tch. Quasi dimenticavo, c'è ancora quel vecchio rimbambito."
  },
  AvgDialog_13735_Content_75 = {
    Text = "Uvhash si voltò e sollevò senza sforzo il corpo basso e tozzo della maga."
  },
  AvgDialog_13735_Content_76 = {
    Text = "C-Cosa stai facendo?"
  },
  AvgDialog_13735_Content_77 = {
    Text = "Niente di che, ti aiuto solo a correre un po' più veloce."
  },
  AvgDialog_13735_Content_78 = {
    Text = "Detto ciò, Uvhash prese disinvoltamente il mago sotto braccio, fece un passo avanti con un piede e spinse a terra con l'avampiede dell'altro, avvolgendo tutto il corpo come una molla."
  },
  AvgDialog_13735_Content_79 = {
    Text = "Ehi... ti avverto, non è il momento di giocare—<Big:AAARGH!!!>"
  },
  AvgDialog_13735_Content_8 = {Text = "!!"},
  AvgDialog_13735_Content_80 = {
    Text = "Uvhash diede una spinta poderosa e schizzò in avanti come una freccia scoccata da un arco."
  },
  AvgDialog_13735_Content_81 = {
    Text = "Io— tu... brutto puzzolente@1, mettimi giù!"
  },
  AvgDialog_13735_Content_82 = {
    Text = "Uvhash scoppiò in una Detonazione di risate fragorose.\nLe risate volarono nel Vento, intrecciandosi con granelli dorati di sabbia e polvere, correndo gioiosamente verso l'orizzonte."
  },
  AvgDialog_13735_Content_83 = {
    Text = "Non se ne parla— ho ancora bisogno di tenerti in vita per aiutarmi a riconquistare la mia libertà!"
  },
  AvgDialog_13735_Content_9 = {
    Text = "Uvhash è spuntato dall'angolo senza preavviso, rivolgendoti un ghigno."
  },
  AvgDialog_13736_Content_1 = {
    Text = "La Guida, lo Stregone e lo Schiavo"
  },
  AvgDialog_13736_Content_10 = {
    Text = "Giallastre, secche, con linee ruvide e Sfrenate sui palmi — queste sono le mani di un guerriero."
  },
  AvgDialog_13736_Content_100 = {
    Text = "Mi spiace, non ho nulla da dirti."
  },
  AvgDialog_13736_Content_101 = {
    Text = "I mercenari sono una massa di feccia senza fede. Quanto agli schiavi, non potrebbero mai capire cosa significhino dignità e onore."
  },
  AvgDialog_13736_Content_102 = {
    Text = "Tu e quel tizio — non c'è alcuna vera differenza tra voi due."
  },
  AvgDialog_13736_Content_103 = {
    Text = "Ma ho passato da un pezzo l'età in cui si agisce d'impulso."
  },
  AvgDialog_13736_Content_104 = {
    Text = [[
Primo, non potrei batterti in un combattimento.
Secondo, mi sei ancora utile.]]
  },
  AvgDialog_13736_Content_105 = {
    Text = "Non mi importa da dove vieni. Adesso, in questo preciso momento, continua a fare strada, mia cara guida."
  },
  AvgDialog_13736_Content_11 = {
    Text = "<Gray:Jamila · @1, 32 anni, ex mercenaria mamelucca, ora guida nel deserto…>"
  },
  AvgDialog_13736_Content_12 = {
    Text = "Elabori in silenzio la tua nuova Identità."
  },
  AvgDialog_13736_Content_13 = {
    Text = "Sembra che tu sia entrato ancora una volta in Morpheus."
  },
  AvgDialog_13736_Content_14 = {
    Text = "Ehi, che cosa borbotti? Se sei sveglio, alzati una buona volta. Il mio <Blue:Schiavo> e io abbiamo affari urgenti da sbrigare."
  },
  AvgDialog_13736_Content_15 = {
    Text = "L'Uomo basso e tarchiato dall'abbigliamento peculiare è il tuo cliente per questo incarico — <Blue:Ludwig · Purin>."
  },
  AvgDialog_13736_Content_16 = {
    Text = "Parlò con impazienza, indicando con noncuranza dietro di sé con la frusta."
  },
  AvgDialog_13736_Content_17 = {Text = "Hss..."},
  AvgDialog_13736_Content_18 = {
    Text = "Uvhash—?!"
  },
  AvgDialog_13736_Content_19 = {
    Text = "Solo allora noti l'Uomo nascosto dietro la duna di sabbia."
  },
  AvgDialog_13736_Content_2 = {
    Text = "@2, il Papa perse il potere e sorse il governo Sovrano.\nLa città santa di Acri divenne una terra ferocemente contesa.\n\nTemendo le forze mamelucche guidate da Baibars,\nil Principe chiamò a raccolta tutti i popoli per marciare verso est e riconquistare la città santa di Acri."
  },
  AvgDialog_13736_Content_20 = {
    Text = "Mantiene una postura accovacciata, le lunghe braccia appoggiate con disinvoltura al suolo, come una bestia pronta a colpire."
  },
  AvgDialog_13736_Content_21 = {
    Text = "Vedendo la tua espressione sconvolta, si lascia sfuggire un ghigno, rivelando una fila di zanne bianche e scintillanti."
  },
  AvgDialog_13736_Content_22 = {
    Text = "Che c'è, mi conosci?"
  },
  AvgDialog_13736_Content_24 = {
    Text = "Prima che tu potessi rispondere, la lunga frusta dello stregone si abbatté con forza su Uvhash."
  },
  AvgDialog_13736_Content_25 = {
    Text = "Questo qui, amico, ti consiglio di non rivolgergli la parola."
  },
  AvgDialog_13736_Content_26 = {
    Text = "Potrà anche avere i nostri stessi occhi e lo stesso naso, ma resta una Bestia incivile, o meglio…"
  },
  AvgDialog_13736_Content_28 = {
    Text = "Un altro schiocco della frusta si abbatté con forza su Uvhash."
  },
  AvgDialog_13736_Content_29 = {
    Text = "È un <Red:demone>."
  },
  AvgDialog_13736_Content_3 = {
    Text = "E così, la grande <Yellow:Crociata> diede ancora una volta inizio al suo Prologo…"
  },
  AvgDialog_13736_Content_30 = {
    Text = "Nonostante le frustate una dopo l'altra, Uvhash non batté nemmeno ciglio."
  },
  AvgDialog_13736_Content_31 = {
    Text = "Si asciugò il Sangue che gli colava dalla tempia, portò il palmo al naso e annusò, poi con calma iniziò a leccarsi il Sangue dalla punta delle dita."
  },
  AvgDialog_13736_Content_32 = {
    Text = "Visto? Persino il cane che sorveglia il mio Cancello ha più umanità di lui! Più in basso di una bestia, ahahaha!"
  },
  AvgDialog_13736_Content_33 = {
    Text = "Ehi… vecchio, oggi le tue frustate sono molto più deboli.\nChe succede, non riesci più nemmeno a tenere ferma la frusta?"
  },
  AvgDialog_13736_Content_34 = {Text = "Hmph..."},
  AvgDialog_13736_Content_35 = {
    Text = "Il motivo per cui le bestie sono bestie è che non riescono mai a controllare la loro bocca né a riconoscere il proprio posto."
  },
  AvgDialog_13736_Content_36 = {
    Text = "Non importa, ti <BigItalic:insegnerò per bene>—"
  },
  AvgDialog_13736_Content_37 = {
    Text = "Purin era così furioso che i suoi baffi si drizzarono, e poi, come una palla lanciata, schizzò rapidamente verso Uvhash."
  },
  AvgDialog_13736_Content_38 = {Text = "Aspetta."},
  AvgDialog_13736_Content_39 = {
    Text = "Hai afferrato Purin per il polso e l'hai tirato indietro."
  },
  AvgDialog_13736_Content_4 = {Text = "..."},
  AvgDialog_13736_Content_40 = {
    Text = "Dammi la frusta."
  },
  AvgDialog_13736_Content_41 = {
    Text = "Lasciami! Lasciami dare una lezione a quella bestia…"
  },
  AvgDialog_13736_Content_42 = {
    Text = "Signor Jamila, ora sono il vostro datore di lavoro. Non devo spiegarvi cosa significa datore di lavoro, vero?"
  },
  AvgDialog_13736_Content_43 = {
    Text = [[
Mi dispiace, ma sono io la guida di questo viaggio.
Dato che sono la guida, seguite le mie indicazioni.]]
  },
  AvgDialog_13736_Content_44 = {
    Text = "Altrimenti me ne vado subito, e potrete trovare da soli la strada per il <Blue:campo di battaglia>."
  },
  AvgDialog_13736_Content_45 = {
    Text = "<Shake:Ehi, ehi...! Parliamone, parliamone...>"
  },
  AvgDialog_13736_Content_46 = {
    Text = "Un'altra cosa."
  },
  AvgDialog_13736_Content_47 = {
    Text = "Aggrotti le sopracciglia e guardi Uvhash."
  },
  AvgDialog_13736_Content_48 = {
    Text = "Anche se le vostre strade si sono incrociate raramente nel campus, hai sentito una cosa o due sulle sue varie imprese."
  },
  AvgDialog_13736_Content_49 = {
    Text = "Non è decisamente il tipo che si lascia controllare dagli altri."
  },
  AvgDialog_13736_Content_5 = {
    Text = "Aprite gli occhi da un lungo, profondo sonno. A perdita d'occhio, non c'è altro che un vasto, sconfinato deserto."
  },
  AvgDialog_13736_Content_50 = {
    Text = "Cosa gli hai fatto? Come può obbedirti così volentieri?"
  },
  AvgDialog_13736_Content_51 = {
    Text = "Cosa, stai mettendo in dubbio le mie capacità di <Blue:Primo Stregone del Levante>?"
  },
  AvgDialog_13736_Content_52 = {
    Text = "Questa è un'arte rara e perduta del nostro mestiere, e anche una questione privata del datore di lavoro. Chiedo alla guida di non ficcare il naso dove non deve..."
  },
  AvgDialog_13736_Content_53 = {
    Text = "Non vuoi parlare, eh?\nAllora te lo farò sputare a forza."
  },
  AvgDialog_13736_Content_54 = {
    Text = "Ehi, aspetta... <Big:Ahi!>"
  },
  AvgDialog_13736_Content_56 = {
    Text = "<Shake:Sss, fa male... T-Tu non sei una guida qualunque!>"
  },
  AvgDialog_13736_Content_57 = {
    Text = "Parla, sei una spia mandata da <Blue:Remouahe> per intercettarmi?"
  },
  AvgDialog_13736_Content_58 = {
    Text = "Non hai risposto all'Eterna Domanda di Purin, perché tutta la tua attenzione era già stata catturata da qualcos'altro—"
  },
  AvgDialog_13736_Content_59 = {
    Text = "Una catena sottile brillava debolmente alla luce del sole, emanando un bagliore insolito."
  },
  AvgDialog_13736_Content_6 = {
    Text = "Sveglio? Che mi venga un colpo. Non avevamo nemmeno fatto due passi che la nostra guida è svenuta per un colpo di calore. Che razza di assurdità è questa?"
  },
  AvgDialog_13736_Content_60 = {
    Text = "Si estendeva dal polso di Purin fino al collo di Uvhash."
  },
  AvgDialog_13736_Content_61 = {
    Text = "<Gray:Questa tecnica mi sembra così familiare... Ho la sensazione che qualcuno l'abbia menzionata prima...>"
  },
  AvgDialog_13736_Content_62 = {
    Text = "Se non si comportano bene, basta metterli al guinzaglio. Semplice."
  },
  AvgDialog_13736_Content_63 = {
    Text = "Questo è illegale a Londinium, signorina Agrippa. Temo che dovremo istruirla su alcune nozioni giuridiche di base..."
  },
  AvgDialog_13736_Content_64 = {
    Text = "Hehe, non sono mica una sciocca."
  },
  AvgDialog_13736_Content_65 = {
    Text = "Conosci @1?"
  },
  AvgDialog_13736_Content_66 = {
    Text = "È un'antica arte segreta che permette a chi la pratica di controllare gli altri con una catena invisibile..."
  },
  AvgDialog_13736_Content_67 = {
    Text = "Quanto al prezzo..."
  },
  AvgDialog_13736_Content_68 = {
    Text = "Qual era il prezzo? Dannazione, non riesco a ricordare..."
  },
  AvgDialog_13736_Content_69 = {
    Text = "Eri perso nei tuoi ricordi quando qualcuno ti ha strappato improvvisamente la maschera dal volto."
  },
  AvgDialog_13736_Content_7 = {
    Text = "Meno male che in questo posto dimenticato da Dio ci vengo solo una volta nella vita, @1!"
  },
  AvgDialog_13736_Content_70 = {
    Text = "Tre fiumi curvi... Sei un <Blue:mercenario schiavo dei Mamelucchi>?!"
  },
  AvgDialog_13736_Content_71 = {
    Text = "Nel momento in cui Purin finì di parlare, Uvhash, che sembrava completamente disinteressato, si voltò improvvisamente a guardarti."
  },
  AvgDialog_13736_Content_72 = {
    Text = "Interessante..."
  },
  AvgDialog_13736_Content_73 = {
    Text = "No, aspetta— La gente dei Mamelucchi dovrebbe essere sul campo di battaglia in questo momento..."
  },
  AvgDialog_13736_Content_74 = {
    Text = "Capisco. Sei un disertore."
  },
  AvgDialog_13736_Content_75 = {
    Text = "Istintivamente ti sei toccato il viso."
  },
  AvgDialog_13736_Content_76 = {
    Text = "<Gray:Quindi ho dei tatuaggi sul viso...>"
  },
  AvgDialog_13736_Content_77 = {
    Text = "Certo, sono un disertore. La mia città natale è <Blue:Remouahe>, ma non voglio tornarci..."
  },
  AvgDialog_13736_Content_78 = {
    Text = "Anche i disertori devono mangiare, quindi ora mi guadagno da vivere come guida.\nNon preoccuparti— la mia più grande virtù è essere meticoloso nel mio lavoro."
  },
  AvgDialog_13736_Content_79 = {
    Text = "Ti garantisco che posso portarti al campo di battaglia—"
  },
  AvgDialog_13736_Content_8 = {
    Text = "Guida? Dove... siamo..."
  },
  AvgDialog_13736_Content_80 = {Text = "Pfft."},
  AvgDialog_13736_Content_81 = {
    Text = "Dopo aver visto abbastanza di quella farsa, Uvhash si stiracchiò pigramente e si avvicinò a te con passo tranquillo."
  },
  AvgDialog_13736_Content_82 = {
    Text = "Ti mise un braccio attorno alle spalle, poi ti girò delicatamente il mento finché il tuo sguardo non fu puntato direttamente sul mago silenzioso davanti a te."
  },
  AvgDialog_13736_Content_83 = {
    Text = "Visto che siamo tutti Schiavi, o almeno lo eravamo— ecco un piccolo suggerimento—"
  },
  AvgDialog_13736_Content_84 = {
    Text = "Se fossi in te, chiuderei il becco proprio adesso.\nSai che tipo di persone quello odia di più?"
  },
  AvgDialog_13736_Content_85 = {
    Text = "...Farmi fare la predica sul pesare le parole proprio da questo tizio— che sensazione peculiare."
  },
  AvgDialog_13736_Content_86 = {
    Text = "...Dimmi pure."
  },
  AvgDialog_13736_Content_87 = {
    Text = "Terzo— i mercenari Mamelucchi."
  },
  AvgDialog_13736_Content_88 = {
    Text = [[
Secondo, i Remouani.
Quanto al primo...]]
  },
  AvgDialog_13736_Content_89 = {
    Text = "Un dolore acuto ti trafigge la spalla — Uvhash ti dà una pacca violenta sulla schiena ridendo a crepapelle."
  },
  AvgDialog_13736_Content_9 = {
    Text = "Il sole cocente vi cuoce fino a farvi girare la testa. Abbassate lo sguardo sulle vostre mani."
  },
  AvgDialog_13736_Content_90 = {
    Text = "<Big:Ovviamente, sono i mercenari Mamulu di Remouahe!>"
  },
  AvgDialog_13736_Content_91 = {
    Text = "<Gray:…Fantastico. Nessun altro potrebbe trovare la cosa divertente.>"
  },
  AvgDialog_13736_Content_92 = {
    Text = "<Gray:Questo tizio ha davvero un talento di prim'ordine per inimicarsi la gente.>"
  },
  AvgDialog_13736_Content_93 = {Text = "Heh..."},
  AvgDialog_13736_Content_94 = {
    Text = "All'epoca, i mercenari Mamelucchi massacrarono decine di migliaia della mia gente. Mia moglie, i miei compagni, il mio mentore… perirono tutti qui."
  },
  AvgDialog_13736_Content_95 = {
    Text = "Bene, la mia tragica storia è finita. Potete tornare a ridere, adesso."
  },
  AvgDialog_13736_Content_96 = {
    Text = "Mi dispiace, signor Purin. Mi permetta di spiegare — anche se effettivamente ho un passato... beh, non proprio onorevole."
  },
  AvgDialog_13736_Content_97 = {
    Text = "Ma è tutto nel passato. Non ha nulla a che fare con chi sono adesso."
  },
  AvgDialog_13736_Content_98 = {
    Text = "Purin agita la mano in un gesto di diniego verso di te."
  },
  AvgDialog_13736_Content_99 = {
    Text = "Il suo viso tondo, cotto dal sole cocente, sembra una mela troppo matura — sfortunatamente, questa mela non è molto felice in questo momento."
  },
  AvgDialog_13737_Content_1 = {
    Text = "Sipario della Tragedia"
  },
  AvgDialog_13737_Content_10 = {
    Text = "<RedShake:Corri…>"
  },
  AvgDialog_13737_Content_11 = {
    Text = "Uvhash schiacciò senza sforzo il cranio di colui che gli bloccava il cammino, poi si diresse lentamente verso un altro Soldato."
  },
  AvgDialog_13737_Content_12 = {
    Text = "<RedShake:Sangue… Ho bisogno di più Sangue…>"
  },
  AvgDialog_13737_Content_13 = {
    Text = "Alzò lentamente la mano."
  },
  AvgDialog_13737_Content_15 = {Text = "..."},
  AvgDialog_13737_Content_16 = {Text = "Sei tu..."},
  AvgDialog_13737_Content_17 = {
    Text = "Già, sono io."
  },
  AvgDialog_13737_Content_18 = {
    Text = "Ti metti tra i due, voltandoti a guardare i Soldati alle tue spalle che sono caduti in ginocchio dalla paura."
  },
  AvgDialog_13737_Content_19 = {
    Text = "Andate. Correte più lontano che potete."
  },
  AvgDialog_13737_Content_2 = {
    Text = "Margine del Deserto di Kusi, Campo di battaglia"
  },
  AvgDialog_13737_Content_20 = {
    Text = "<Big:Fuori di qui!!>"
  },
  AvgDialog_13737_Content_21 = {
    Text = "<Shake:O-okay... me ne vado...>"
  },
  AvgDialog_13737_Content_22 = {
    Text = "I Soldati fuggirono carponi a gambe levate."
  },
  AvgDialog_13737_Content_23 = {
    Text = "Perché ti metti sulla mia strada? Stavo appena iniziando ad assaporare la gioia del Sangue e della battaglia..."
  },
  AvgDialog_13737_Content_24 = {
    Text = "Vuoi solo combattere, giusto? Ci gioco io con te."
  },
  AvgDialog_13737_Content_25 = {
    Text = "Tu? Hahahaha, ma che cosa sei—"
  },
  AvgDialog_13737_Content_27 = {
    Text = "Premi la tua lama ricurva contro la gola di Uvhash, fissando con calma i suoi occhi che hanno ormai perso ogni lucidità."
  },
  AvgDialog_13737_Content_28 = {
    Text = "Come fai a saperlo senza provare?"
  },
  AvgDialog_13737_Content_3 = {
    Text = "Ehi, hai sentito? Un altro è impazzito, uccide chiunque a vista."
  },
  AvgDialog_13737_Content_4 = {
    Text = "Dicono che non sia né Leoriano né Remouaheano... nessuno sa da dove venga."
  },
  AvgDialog_13737_Content_5 = {
    Text = "Comunque, andiamocene da qui—"
  },
  AvgDialog_13737_Content_6 = {Text = "..."},
  AvgDialog_13737_Content_7 = {
    Text = "<Shake:Q-quando sei apparso…>"
  },
  AvgDialog_13737_Content_8 = {
    Text = "Ahhh! Presto—"
  },
  AvgDialog_13737_Content_9 = {Text = "—!!"},
  AvgDialog_13738_Content_1 = {
    Text = "Bene, la tempesta di sabbia è andata dall'altra parte. Ora noi..."
  },
  AvgDialog_13738_Content_10 = {Text = "..."},
  AvgDialog_13738_Content_11 = {
    Text = "Vuoi andare sul campo di battaglia, no? Allora è naturale avanzare nella <Red:direzione del Sangue>."
  },
  AvgDialog_13738_Content_12 = {
    Text = "La direzione del Sangue...?"
  },
  AvgDialog_13738_Content_13 = {
    Text = "Indicasti la figura di Uvhash che si allontanava a grandi passi."
  },
  AvgDialog_13738_Content_14 = {
    Text = "La sua direzione."
  },
  AvgDialog_13738_Content_2 = {Text = "BLEGH—!!"},
  AvgDialog_13738_Content_3 = {
    Text = "Purin si appoggiò al tronco di un albero spoglio, piegandosi in avanti mentre iniziava a vomitare violentemente."
  },
  AvgDialog_13738_Content_4 = {
    Text = "Lo giuro, una volta finito questo lavoro. Lo giuro..."
  },
  AvgDialog_13738_Content_5 = {
    Text = "Questa volta, la debole Maledizione del mago non ricevette alcuna risposta."
  },
  AvgDialog_13738_Content_6 = {
    Text = "Avendo scoperto qualcosa, le pupille di Uvhash si contrassero improvvisamente, quasi impercettibilmente, per un istante."
  },
  AvgDialog_13738_Content_7 = {
    Text = "<Red:...Sangue.>"
  },
  AvgDialog_13738_Content_8 = {
    Text = "Detto ciò, se ne andò senza voltarsi indietro."
  },
  AvgDialog_13738_Content_9 = {
    Text = "Aspetta...! Senza il mio permesso, non puoi andare da nessuna parte!"
  },
  AvgDialog_13739_Content_1 = {
    Text = "Gli avvoltoi gridano sotto il crepuscolo rosso sangue. Il campo di battaglia è deserto ormai da tempo."
  },
  AvgDialog_13739_Content_10 = {
    Text = "Durante il combattimento, percepisci chiaramente che lo Stato di Uvhash si sta deteriorando a un ritmo allarmante."
  },
  AvgDialog_13739_Content_11 = {
    Text = "Che sia o meno un effetto collaterale del contratto, ormai è allo stremo delle forze."
  },
  AvgDialog_13739_Content_12 = {
    Text = "Una battaglia è divertente solo quando gli avversari sono alla pari. Per questo, non mi dispiace diventare un po' più debole."
  },
  AvgDialog_13739_Content_13 = {
    Text = "Non mi è mai importato di ciò che pensano gli umani, così come agli umani non importa delle formiche."
  },
  AvgDialog_13739_Content_14 = {
    Text = "Ma tu sei diverso. C'è un Potere possente dentro di te, e sai come esercitare il Contrattacco."
  },
  AvgDialog_13739_Content_15 = {
    Text = "Continua così, guerriero. Quei tuoi noiosi desideri — il Sole, i dolcetti, e cose simili — forse possono davvero avverarsi."
  },
  AvgDialog_13739_Content_16 = {
    Text = "<Gray:Era solo qualcosa che avevo detto di sfuggita, eppure se lo ricordava ancora…>"
  },
  AvgDialog_13739_Content_17 = {
    Text = "Andiamo… nel posto di cui parlavi, dove splende il Sole."
  },
  AvgDialog_13739_Content_18 = {Text = "?!"},
  AvgDialog_13739_Content_19 = {Text = "E tu?"},
  AvgDialog_13739_Content_2 = {
    Text = "Tu e Uvhash vi trovate a meno di dieci metri di distanza, a fissarvi in silenzio."
  },
  AvgDialog_13739_Content_20 = {
    Text = "Io…? Il vecchio aveva un ultimo asso nella manica. Non vivrò ancora a lungo. Heh heh…"
  },
  AvgDialog_13739_Content_21 = {
    Text = "Sia io che il vecchio dobbiamo morire… questo è il vero prezzo per aver infranto il patto."
  },
  AvgDialog_13739_Content_22 = {
    Text = "Si avvicinò a te con passi faticosi, colmando lentamente la distanza."
  },
  AvgDialog_13739_Content_23 = {
    Text = "Poi si morse il polso con i denti, aprendolo."
  },
  AvgDialog_13739_Content_24 = {
    Text = "Sangue Cremisi e pungente sgorgò a fiotti, gocciolando sulla sommità del tuo capo, sulle tue palpebre, poi scivolando lungo il ponte del naso fino alle tue labbra riarse."
  },
  AvgDialog_13739_Content_25 = {
    Text = "Questo Sangue… consideralo il mio Sacramento d'addio."
  },
  AvgDialog_13739_Content_26 = {
    Text = "Gli avvoltoi volteggiavano sopra la sua testa, avendo chiaramente puntato la loro preda morente."
  },
  AvgDialog_13739_Content_27 = {
    Text = "Sono nato da innumerevoli carni e ho vagato per questo mondo per quasi mille anni..."
  },
  AvgDialog_13739_Content_28 = {
    Text = "Ho visto foglie d'Oro danzare nel cielo durante le processioni trionfali, e palazzi d'Oro ardere ferocemente tra le fiamme."
  },
  AvgDialog_13739_Content_29 = {
    Text = "Ho assaporato il Sangue più squisito, e vissuto le battaglie più brutali."
  },
  AvgDialog_13739_Content_3 = {
    Text = "Ehi... da quanto tempo stiamo combattendo?"
  },
  AvgDialog_13739_Content_30 = {
    Text = "Ho massacrato esseri umani, e sono stato anche incatenato e sfruttato dagli umani, e alla fine, com'era prevedibile, ho trovato la morte per mano umana."
  },
  AvgDialog_13739_Content_31 = {
    Text = "Ora è giunto il momento per me di andarmene…"
  },
  AvgDialog_13739_Content_32 = {
    Text = "Ti guardava dall'alto in basso, i suoi occhi privi di qualsiasi emozione."
  },
  AvgDialog_13739_Content_33 = {
    Text = "Sangue appiccicoso gocciolava dalla punta del tuo naso a terra, goccia dopo goccia."
  },
  AvgDialog_13739_Content_34 = {
    Text = "Eri come un iniziato al battesimo disorientato, completamente perso e impotente davanti a tutto ciò che si svolgeva davanti ai tuoi occhi."
  },
  AvgDialog_13739_Content_35 = {
    Text = "Restituisco tutta la mia carne a te e a questo mondo."
  },
  AvgDialog_13739_Content_36 = {
    Text = "Appartengono al cielo, alla Terra… a te, ma non a me."
  },
  AvgDialog_13739_Content_37 = {
    Text = "Ora puoi levarti di torno… levarti di torno e non voltarti indietro."
  },
  AvgDialog_13739_Content_38 = {
    Text = [[
La tua visione viene infine inghiottita dalla vasta nebbia di Sangue.
Chiudi gli occhi, sentendo ondate di vertigini una dopo l'altra, come se la Terra stesse sprofondando senza fine.]]
  },
  AvgDialog_13739_Content_39 = {
    Text = "Riesci a malapena a ricordare cosa sia successo dopo."
  },
  AvgDialog_13739_Content_4 = {Text = "..."},
  AvgDialog_13739_Content_40 = {
    Text = "Forse te ne eri già andato, o forse sei morto insieme a lui in questo deserto."
  },
  AvgDialog_13739_Content_41 = {
    Text = "Niente di tutto ciò ha importanza. Perché ricorderai per sempre quel momento prima della sua morte."
  },
  AvgDialog_13739_Content_42 = {
    Text = "In quel momento, uno stormo di avvoltoi neri passò in volo, oscurando il bagliore dietro di lui."
  },
  AvgDialog_13739_Content_43 = {
    Text = "La luce continuava ad affievolirsi, le ombre si insinuavano da ogni lato, e lui era lì in ginocchio tra quelle ombre, a fissarti."
  },
  AvgDialog_13739_Content_44 = {Text = "Disse—"},
  AvgDialog_13739_Content_45 = {
    Text = "Levati di torno."
  },
  AvgDialog_13739_Content_46 = {
    Text = "Va' a cercare quel maledetto posto dove splende il Sole."
  },
  AvgDialog_13739_Content_5 = {
    Text = "Chi lo sa... un'ora, un giorno?"
  },
  AvgDialog_13739_Content_6 = {Text = "..."},
  AvgDialog_13739_Content_7 = {
    Text = "Mille anni... sono passati quasi mille anni dall'ultima volta che ho goduto di una battaglia così esaltante."
  },
  AvgDialog_13739_Content_8 = {
    Text = "Sei un guerriero nato."
  },
  AvgDialog_13739_Content_9 = {
    Text = "Che sorpresa. Quando hai imparato ad adulare come un umano?"
  },
  AvgDialog_138765_Content_1 = {
    Text = "Le braci della dimensione scorrono. La ruota del destino, Moirae, ha già cominciato a girare."
  },
  AvgDialog_138765_Content_2 = {
    Text = "Dai tutto ciò che hai, Custode del Segreto{Male=先生,Female=小姐}. Ti assisterò nel correggere il destino errato e nel distruggere i bozzoli che non avrebbero dovuto esistere."
  },
  AvgDialog_138765_Content_3 = {
    Text = "Il corso del destino non è mai stato tessuto da mani altrui."
  },
  AvgDialog_138766_Content_1 = {
    Text = "È... è finita?"
  },
  AvgDialog_138766_Content_2 = {
    Text = "Attento, Custode... il fuso che dipana il fato ha già iniziato a girare dietro di lei..."
  },
  AvgDialog_138766_Content_3 = {
    Text = "Heh... hahahaha...!"
  },
  AvgDialog_138766_Content_4 = {
    Text = "\"Guardate, voi ciechi fedeli del Fato! La campana che da sempre era destinata a suonare per voi ha finalmente rintoccato!\""
  },
  AvgDialog_138766_Content_5 = {
    Text = "\"Io sono la fine— Io sono il Fato— Io sono @4!\""
  },
  AvgDialog_138766_Content_6 = {
    Text = "\"Ora, vi concedo la fine ultima. Vi dono la liberazione che avete così disperatamente bramato!!\""
  },
  AvgDialog_13946_Content_1 = {
    Text = "Mare Senza Approdo"
  },
  AvgDialog_13946_Content_10 = {
    Text = "Ti hanno mandato a \"scortarmi\" dalla strega?\nÈ ridicolo. Le loro intenzioni non potrebbero essere più ovvie..."
  },
  AvgDialog_13946_Content_11 = {
    Text = "Golia emette un gemito di dolore. Sotto di lui, una pozza di sangue rosso scuro si espande lentamente, scorrendo fino ai tuoi piedi."
  },
  AvgDialog_13946_Content_12 = {
    Text = "<Red:Vogliono che moriamo insieme in mare.>"
  },
  AvgDialog_13946_Content_13 = {
    Text = "Padrone, siete gravemente ferito! Cosa è successo...?"
  },
  AvgDialog_13946_Content_14 = {
    Text = "Ricordi caotici inondano la tua mente."
  },
  AvgDialog_13946_Content_15 = {
    Text = "Nell'ultima battaglia decisiva, il Capo Golia ha perso contro la tribù rivale per averla sottovalutata."
  },
  AvgDialog_13946_Content_16 = {
    Text = "I Perishiti non accettano la sconfitta. Il Golia gravemente ferito è stato esiliato, accompagnato solo da una piccola barca malandata e da te—"
  },
  AvgDialog_13946_Content_17 = {
    Text = "Il Perishita più debole potrebbe persino perdere una lotta contro un bambino di dieci anni."
  },
  AvgDialog_13946_Content_18 = {
    Text = "Ricordo che il capo <Blue:Glen> menzionava una strega misteriosa nelle acque vicine che usa una specie di melma nera..."
  },
  AvgDialog_13946_Content_19 = {
    Text = "Basta applicarla sulla ferita e la lesione guarirà sicuramente!"
  },
  AvgDialog_13946_Content_2 = {
    Text = [[
Lamento per l'Apostolo del mare.
Lamento per la nostra luce, la nostra speranza.

Piangiamo, singhiozziamo e versiamo lacrime per il nostro destino di esiliati nell'oceano.]]
  },
  AvgDialog_13946_Content_20 = {
    Text = "Hai tirato fuori d'istinto la leggenda della strega, solo per renderti conto che qualcosa non quadrava."
  },
  AvgDialog_13946_Content_21 = {
    Text = "<Gray:Aspetta, questa è D-slime...?>"
  },
  AvgDialog_13946_Content_22 = {
    Text = "Capo, intendi Glen?"
  },
  AvgDialog_13946_Content_23 = {
    Text = "Un lento sorriso si diffuse sul volto freddo di Golia."
  },
  AvgDialog_13946_Content_24 = {
    Text = "A quanto pare è diventato il vostro nuovo capo. Molto efficienti, miei cari compagni di clan."
  },
  AvgDialog_13946_Content_25 = {Text = "Splash!!"},
  AvgDialog_13946_Content_26 = {
    Text = "La barca in decomposizione non riusciva più a resistere all'impatto delle onde, aprendosi in una grande falla attraverso cui l'acqua di mare entrava incessantemente."
  },
  AvgDialog_13946_Content_27 = {
    Text = "Tsk, proprio come mi aspettavo."
  },
  AvgDialog_13946_Content_28 = {
    Text = "Oh no, stiamo per annegare! Dobbiamo trovare qualcosa per tappare il buco..."
  },
  AvgDialog_13946_Content_29 = {Text = "...Oh."},
  AvgDialog_13946_Content_3 = {
    Text = [[
Oh, proteggi gli afflitti!
Posa su di noi il tuo sguardo misericordioso e concedici la nera fonte della vita.]]
  },
  AvgDialog_13946_Content_30 = {
    Text = "Golia si appoggiò con disinteresse al ponte, lasciando che il sangue sotto di lui tingesse di rosso l'acqua di mare che entrava."
  },
  AvgDialog_13946_Content_31 = {
    Text = "Rilassati. Anche se riparassimo la nave, avrebbero comunque diecimila modi per uccidermi in questo mare."
  },
  AvgDialog_13946_Content_32 = {
    Text = "Il mio consiglio: lasciami stare. Scendi dalla barca e torna a nuoto da solo."
  },
  AvgDialog_13946_Content_33 = {
    Text = "Digli che mi hai ucciso. Se sei fortunato, potresti sopravvivere."
  },
  AvgDialog_13946_Content_34 = {Text = "E tu...?"},
  AvgDialog_13946_Content_35 = {Text = "Io?"},
  AvgDialog_13946_Content_36 = {
    Text = "Golia si gode tranquillamente la vista del mare e ti rivolge un lieve sorriso."
  },
  AvgDialog_13946_Content_37 = {
    Text = "Starmene seduto qui ad ammirare il mare, aspettando di morire."
  },
  AvgDialog_13946_Content_38 = {Text = "...?"},
  AvgDialog_13946_Content_39 = {
    Text = "<Gray:Così pessimista, è davvero il Golia che conosco?>"
  },
  AvgDialog_13946_Content_4 = {
    Text = "<Red:Pietà, pietà, pietà...>"
  },
  AvgDialog_13946_Content_40 = {
    Text = "A proposito, c'è un'altra cosa che devo ricordarti."
  },
  AvgDialog_13946_Content_41 = {
    Text = "C'è un buco a poppa. In base alla mia esperienza, questa nave si spezzerà in due a breve. Non ti resta molto tempo per pensare."
  },
  AvgDialog_13946_Content_42 = {Text = "Splash!!"},
  AvgDialog_13946_Content_43 = {
    Text = "Come a confermare le parole di Golia, un'onda enorme colpì la barca, spezzando in due la barca di legno all'istante."
  },
  AvgDialog_13946_Content_44 = {
    Text = "<Shake:Aaaah—!!>"
  },
  AvgDialog_13946_Content_45 = {
    Text = "L'acqua salata del mare continua a inondare i tuoi polmoni. Apri la bocca, ma altra acqua ti divora completamente."
  },
  AvgDialog_13946_Content_46 = {
    Text = "Il corpo continua a sprofondare e respirare diventa sempre più difficile..."
  },
  AvgDialog_13946_Content_47 = {
    Text = "In uno stato confuso, ti sembra di sentire un sospiro di rassegnazione."
  },
  AvgDialog_13946_Content_48 = {
    Text = "Prima che tu possa reagire, una forza potente ti afferra per i capelli e ti solleva senza sforzo fuori dal mare."
  },
  AvgDialog_13946_Content_49 = {
    Text = "Cough... Ugh!"
  },
  AvgDialog_13946_Content_5 = {Text = "..."},
  AvgDialog_13946_Content_50 = {
    Text = "Tieniti forte, questa è la nostra unica ancora di salvezza."
  },
  AvgDialog_13946_Content_51 = {
    Text = "Ti guardi intorno e realizzi che tu e Golia siete stipati insieme su una tavola di legno traballante."
  },
  AvgDialog_13946_Content_52 = {
    Text = "Dannazione... Com'è possibile che i Perishiti, padroni del mare, non sappiano nuotare?"
  },
  AvgDialog_13946_Content_53 = {
    Text = "Sei davvero un Perishita?"
  },
  AvgDialog_13946_Content_54 = {
    Text = "<SmallShake:Mi dispiace, il mio corpo è stato fragile fin dall'infanzia...>"
  },
  AvgDialog_13946_Content_55 = {
    Text = "Grazie, mio signore. Se non fosse stato per voi, sarei morto qui..."
  },
  AvgDialog_13946_Content_56 = {
    Text = "...A quanto pare non sei stato mandato da loro per uccidermi."
  },
  AvgDialog_13946_Content_57 = {
    Text = "Il tuo istinto di sopravvivenza di poco fa sembrava genuino, non simulato."
  },
  AvgDialog_13946_Content_58 = {
    Text = "Golia si scostò i capelli umidi dalla fronte e fissò il mare nebbioso davanti a sé."
  },
  AvgDialog_13946_Content_59 = {
    Text = "Quando sei caduto in mare, ti sei aggrappato a me come un granchio gigante, rifiutandoti di lasciarmi. Perché?"
  },
  AvgDialog_13946_Content_6 = {Text = "Sveglio/a?"},
  AvgDialog_13946_Content_60 = {
    Text = "Eh? Ovviamente, per sopravvivere..."
  },
  AvgDialog_13946_Content_61 = {
    Text = "Sopravvivere... ma anche da vivo, sei inutile. Non sai nemmeno nuotare."
  },
  AvgDialog_13946_Content_62 = {
    Text = "Per cosa vivi?"
  },
  AvgDialog_13946_Content_63 = {
    Text = "La voce di Golia si affievolì gradualmente, come se stesse chiedendo a te, o forse a se stesso."
  },
  AvgDialog_13946_Content_64 = {
    Text = "Esiliato dalla sua tribù e gravemente ferito, il cammino davanti a lui, come il mare avvolto nella fitta nebbia, è pieno di infinita incertezza."
  },
  AvgDialog_13946_Content_65 = {Text = "..."},
  AvgDialog_13946_Content_66 = {
    Text = "Quando hai detto che eri pronto a morire, ma quando sono arrivate le onde, non solo hai trovato questa tavola e ci sei salito sopra, ma hai anche salvato me."
  },
  AvgDialog_13946_Content_67 = {
    Text = "...È perché tu continui a tormentarmi."
  },
  AvgDialog_13946_Content_68 = {
    Text = "Niente di tutto ciò conta. Quello che conta è che, grazie a voi, Padrone, siamo entrambi vivi."
  },
  AvgDialog_13946_Content_69 = {
    Text = "Perché pensi che sia così?"
  },
  AvgDialog_13946_Content_7 = {
    Text = "Il mare solleva onde cotte dal sole, portando al tuo naso una brezza salata dal forte odore di pesce."
  },
  AvgDialog_13946_Content_70 = {
    Text = "Golia scosse la testa."
  },
  AvgDialog_13946_Content_71 = {
    Text = "A essere sincero, non lo so nemmeno io. Ma mi sono reso conto di una cosa..."
  },
  AvgDialog_13946_Content_72 = {
    Text = "Golia abbassa la testa, osservandoti pensieroso."
  },
  AvgDialog_13946_Content_73 = {
    Text = "Capisco perché sei un tale fallimento eppure sei ancora vivo."
  },
  AvgDialog_13946_Content_8 = {
    Text = "<Gray:Questo è... un sogno?>"
  },
  AvgDialog_13946_Content_9 = {
    Text = "Come ci si aspetta dal membro notoriamente più fragile del clan, una singola grande onda può lasciarti privo di sensi per mezza giornata."
  },
  AvgDialog_13947_Content_1 = {
    Text = "Cronache dei Giganti"
  },
  AvgDialog_13947_Content_10 = {
    Text = "Solo gli sciocchi affiderebbero la propria vita ad altri."
  },
  AvgDialog_13947_Content_11 = {
    Text = "<Gray:Strega...>"
  },
  AvgDialog_13947_Content_12 = {
    Text = "Secondo il fascicolo del Risvegliatore di Golia, questa cosiddetta \"strega\" è senza dubbio Miryam."
  },
  AvgDialog_13947_Content_13 = {
    Text = "Sebbene gli sviluppi successivi non fossero quelli previsti, Miryam salvò effettivamente la vita di Golia."
  },
  AvgDialog_13947_Content_14 = {
    Text = "Siete gravemente ferito, signore. Temo non ci sia altro modo. Cerchiamo insieme la strega—"
  },
  AvgDialog_13947_Content_15 = {Text = "BANG!!"},
  AvgDialog_13947_Content_16 = {
    Text = "Con una forza tremenda, la tua fragile gola viene stretta in una morsa, sollevandoti da terra fino a trovarti faccia a faccia con il gigante."
  },
  AvgDialog_13947_Content_17 = {
    Text = "Lo dirò una sola volta: non guardarmi con quello sguardo e non rivolgerti a me con quel tono."
  },
  AvgDialog_13947_Content_18 = {
    Text = "L'ultima cosa di cui io, Golia, ho bisogno è la pietà dei deboli."
  },
  AvgDialog_13947_Content_19 = {
    Text = "Golia parlava con calma, la sua espressione immutata, come se stesse discutendo del tempo con te."
  },
  AvgDialog_13947_Content_2 = {
    Text = "La luce del sole brucia la superficie del mare, come se volesse consumare ogni vita nell'interminabile calore."
  },
  AvgDialog_13947_Content_20 = {
    Text = "Ma sei così vicino che puoi vedere chiaramente i suoi occhi, arrossati dal dolore e dalla frustrazione."
  },
  AvgDialog_13947_Content_21 = {
    Text = "In quel momento, sembrava essersi spogliato della sua gloria di signore dei mari, diventando solo un altro pesce sperduto nell'oceano sconfinato, proprio come te."
  },
  AvgDialog_13947_Content_22 = {
    Text = "Mi scusi... ehm, mio signore..."
  },
  AvgDialog_13947_Content_23 = {
    Text = "<Shake:Woo—>"
  },
  AvgDialog_13947_Content_24 = {
    Text = "Il suono profondo di un corno giunge da lontano."
  },
  AvgDialog_13947_Content_25 = {
    Text = "Il peso sul collo si alleggerì improvvisamente. Golia allentò la presa e volse lo sguardo nella direzione da cui proveniva il suono del corno."
  },
  AvgDialog_13947_Content_26 = {
    Text = "<Gray:Coff... Uff, sono salvo...>"
  },
  AvgDialog_13947_Content_27 = {
    Text = "Interessante... Temete che non muoia abbastanza in fretta, e così siete venuti tutti insieme a darmi l'addio?"
  },
  AvgDialog_13947_Content_28 = {
    Text = "In poco tempo, l'immensa flotta vi circondò, lasciando le assi di legno ondeggianti come unica isola in questo vasto mare."
  },
  AvgDialog_13947_Content_29 = {
    Text = "Siete già circondati."
  },
  AvgDialog_13947_Content_3 = {
    Text = "Tu e Golia vi aggrappate all'asse, l'unica isola nel vasto mare. Sotto il sole cocente, senti di nuovo le vertigini."
  },
  AvgDialog_13947_Content_30 = {
    Text = "Permettetemi di presentare a tutti il condottiero più valoroso nella storia dei Perishita! L'indomabile gigante dalla forza immensa! Il temibile, impareggiabile eroe tribale—"
  },
  AvgDialog_13947_Content_31 = {
    Text = "<BigShake:Lord Golia!>"
  },
  AvgDialog_13947_Content_32 = {
    Text = "La luce del sole riflessa dal mare è troppo intensa; riesci solo a intravedere una figura nera in piedi a prua, che ti osserva dall'alto."
  },
  AvgDialog_13947_Content_33 = {
    Text = "I fratelli appena arrivati forse non lo sanno, ma questo signore è stato gravemente ferito in un duello e quasi catturato, spingendo l'intero nostro clan sull'orlo di una crisi senza precedenti!"
  },
  AvgDialog_13947_Content_34 = {
    Text = "L'imminente rovina ha divorato la maggior parte della nostra gente! Lode a voi, mio carissimo Lord Golia!"
  },
  AvgDialog_13947_Content_35 = {
    Text = "Hehe... Come potrei osare prendermi tutto il merito di un'impresa così grande, Glen?"
  },
  AvgDialog_13947_Content_36 = {
    Text = "Chi si nascondeva dietro di me, troppo spaventato per combattere, e chi è stato il primo a gettare l'arma e correre a casa piangendo?"
  },
  AvgDialog_13947_Content_37 = {Text = "Tu...!"},
  AvgDialog_13947_Content_38 = {
    Text = "Il volto di Glen divenne rosso cremisi, i suoi occhi torbidi tremarono prima di fissarsi finalmente su di te."
  },
  AvgDialog_13947_Content_39 = {
    Text = "Oh, anche se la tribù si disperde, il capo ha ancora un... seguace molto adorabile."
  },
  AvgDialog_13947_Content_4 = {
    Text = "<Shake:Scusa, non mi sento bene... Riposerò un attimo...>"
  },
  AvgDialog_13947_Content_40 = {
    Text = "La vergogna dei Perishiti — un buono a nulla che non riesce nemmeno a reggere un singolo pugno nella tribù, eppure cerca di seguirti per diventare un guerriero..."
  },
  AvgDialog_13947_Content_41 = {
    Text = "Hahaha...!!"
  },
  AvgDialog_13947_Content_42 = {
    Text = "Golia alza lo sguardo, sorpreso di vederti tra le risate della folla."
  },
  AvgDialog_13947_Content_43 = {
    Text = "Ehi, piccolo, sei venuto a seguirmi di tua spontanea volontà?"
  },
  AvgDialog_13947_Content_44 = {
    Text = "<Gray:Ehm... È così che me lo ricordo...>"
  },
  AvgDialog_13947_Content_45 = {
    Text = "Non è commovente? Ho solo menzionato la strega di sfuggita, e questo piccolo sciocco l'ha presa sul serio, desideroso di seguirti fin qui..."
  },
  AvgDialog_13947_Content_46 = {
    Text = "Non c'è stato verso di fermarlo, haha—"
  },
  AvgDialog_13947_Content_47 = {Text = "Splash!!"},
  AvgDialog_13947_Content_48 = {
    Text = "Le risate si interruppero bruscamente. Un vento feroce ululò, e una gamba mozzata rotolò davanti a tutti."
  },
  AvgDialog_13947_Content_49 = {
    Text = "Aaaah... la mia gamba, la mia gamba!!"
  },
  AvgDialog_13947_Content_5 = {
    Text = "Una camicia macchiata di sudore e sangue ti viene gettata sulla testa, facendoti balzare immediatamente in piedi a causa del fetore."
  },
  AvgDialog_13947_Content_50 = {
    Text = "Il signore dei mari un tempo dominante si erge come una montagna davanti a Glen, emanando un'aura che gela il cuore."
  },
  AvgDialog_13947_Content_51 = {
    Text = "Quella mosca mi ronza intorno all'orecchio da un po' ormai..."
  },
  AvgDialog_13947_Content_52 = {
    Text = "Golia pulì con calma il sangue dalla lama, poi alzò lo sguardo e rivolse a Glen un sorriso gelido."
  },
  AvgDialog_13947_Content_53 = {
    Text = "Glenn, ti ho forse rivolto una domanda?"
  },
  AvgDialog_13947_Content_6 = {
    Text = "Cough... Ugh!"
  },
  AvgDialog_13947_Content_7 = {
    Text = "Hai un colpo di calore. Mettitela sulla testa per ripararti dal sole, e non toglierla."
  },
  AvgDialog_13947_Content_8 = {
    Text = [[
Come ci si poteva aspettare dai vestiti indossati dal Padrone, davvero rinvigorenti...
Dove andiamo adesso? A cercare la strega?]]
  },
  AvgDialog_13947_Content_9 = {
    Text = "Che sciocchezze sulle streghe? Non puoi davvero credere alle loro bugie, vero?"
  },
  AvgDialog_13948_Content_1 = {
    Text = "Ritornello dorato"
  },
  AvgDialog_13948_Content_10 = {
    Text = "La pallida calma del mare si spezza quando un serpente marino dal colore scuro violaceo-nero balza fuori all'improvviso, avvolgendo tutti in una stretta mortale."
  },
  AvgDialog_13948_Content_11 = {
    Text = "Hmm... Aaaahhh!!"
  },
  AvgDialog_13948_Content_12 = {
    Text = "Con un debole sibilo, il corpo del serpente si trasforma in una lama nera come la pece, trafiggendo completamente la persona."
  },
  AvgDialog_13948_Content_13 = {
    Text = "<Big:Fuori dai piedi>... Eh?"
  },
  AvgDialog_13948_Content_15 = {
    Text = "Una sensazione morbida e gelida emana dal collo dove il serpente nero si avvolge, guarendo gradualmente la ferita."
  },
  AvgDialog_13948_Content_16 = {
    Text = "Le mie ferite... sono tutte guarite?"
  },
  AvgDialog_13948_Content_17 = {
    Text = "Il serpente nero ti lascia senza esitazione e si avvolge rapidamente attorno a Glenn."
  },
  AvgDialog_13948_Content_18 = {
    Text = "Scappa, la strega sta... arrivando..."
  },
  AvgDialog_13948_Content_19 = {
    Text = "I serpenti neri come la pece strisciarono fuori dagli occhi e dalla bocca di Glen. Crollò a terra prima di riuscire a pronunciare una frase completa."
  },
  AvgDialog_13948_Content_2 = {
    Text = [[
Lamento per l'Apostolo del mare.
Lamento per la nostra luce, la nostra speranza.

Piangiamo, singhiozziamo e versiamo lacrime per il nostro destino di esiliati nell'oceano.]]
  },
  AvgDialog_13948_Content_20 = {
    Text = "In poco tempo, innumerevoli cadaveri dilaniati galleggiavano sul mare."
  },
  AvgDialog_13948_Content_21 = {
    Text = "Questo è un massacro silenzioso."
  },
  AvgDialog_13948_Content_22 = {
    Text = "<Gray:È finita? Impressionante, come ci si aspettava da Miryam.>"
  },
  AvgDialog_13948_Content_23 = {
    Text = "Ci hai aiutato... Chi sei?"
  },
  AvgDialog_13948_Content_24 = {
    Text = "La donna dal velo nero resta in silenzio. Si trova a prua, con una fitta nebbia che vi separa da lei."
  },
  AvgDialog_13948_Content_25 = {
    Text = "Sembra così vicina, eppure così lontana."
  },
  AvgDialog_13948_Content_26 = {
    Text = "La donna osservò Golia, rimasto attonito, con un lieve sorriso sulle labbra. Puntò il dito verso la distanza, come a rivolgere un invito silenzioso."
  },
  AvgDialog_13948_Content_27 = {
    Text = "Poi virò la prua e se ne andò con calma."
  },
  AvgDialog_13948_Content_28 = {
    Text = "Aspetta, non andare...<Big:Non andartene!>"
  },
  AvgDialog_13948_Content_29 = {
    Text = "La nebbia si dissipa e un raggio di sole squarcia le nuvole, tingendo le onde di una tonalità dorata."
  },
  AvgDialog_13948_Content_3 = {
    Text = "La vista si oscura improvvisamente; la luce accecante del sole svanisce gradualmente, e una fitta nebbia avvolge l'intera superficie del mare."
  },
  AvgDialog_13948_Content_30 = {
    Text = "Hai sbattuto le palpebre, e la fine del mare era già vuota."
  },
  AvgDialog_13948_Content_31 = {
    Text = "La tempesta si placa, e tu e Golia vi aggrappate all'unica tavola intatta, ansimando per riprendere fiato."
  },
  AvgDialog_13948_Content_32 = {
    Text = "Il mare un tempo azzurro è ormai tinto di rosso sangue, e voi andate alla deriva come lenticchie d'acqua."
  },
  AvgDialog_13948_Content_33 = {
    Text = "Non sono riuscito a prendere la nave... Ora non so nemmeno come tornare a casa."
  },
  AvgDialog_13948_Content_34 = {
    Text = "Non si torna a casa."
  },
  AvgDialog_13948_Content_35 = {
    Text = "Golia si appoggiò su una gamba, fissando con sguardo assente la direzione in cui Miryam se n'era andata."
  },
  AvgDialog_13948_Content_36 = {
    Text = "Ho deciso. Andrò a cercare quella strega. Verrai con me?"
  },
  AvgDialog_13948_Content_37 = {
    Text = "Ehm, \"Solo uno stolto affiderebbe la propria vita a qualcun altro.\""
  },
  AvgDialog_13948_Content_38 = {
    Text = "Abbassi deliberatamente la voce, imitando il tono che Golia aveva usato prima e ripetendo le sue parole."
  },
  AvgDialog_13948_Content_39 = {
    Text = "Hmph, è perché la posta in gioco non era abbastanza alta. Non avevo mai visto un potere capace di annientare tutto in un istante."
  },
  AvgDialog_13948_Content_4 = {
    Text = [[
Oh, proteggi coloro che sono afflitti dalla sventura.
Posa il tuo sguardo compassionevole su di noi...]]
  },
  AvgDialog_13948_Content_40 = {
    Text = "Inoltre, ci ha appena aiutati e ha persino rivolto un invito a me..."
  },
  AvgDialog_13948_Content_41 = {
    Text = "Ma se fosse... una trappola?"
  },
  AvgDialog_13948_Content_42 = {
    Text = "Trappola..."
  },
  AvgDialog_13948_Content_43 = {
    Text = "Ricordi la domanda che mi hai fatto prima?"
  },
  AvgDialog_13948_Content_44 = {
    Text = "...L'importante è che, grazie a voi, mio signore, siamo entrambi vivi adesso."
  },
  AvgDialog_13948_Content_45 = {
    Text = "Perché pensi che sia così?"
  },
  AvgDialog_13948_Content_46 = {
    Text = "Ora conosco la risposta."
  },
  AvgDialog_13948_Content_47 = {
    Text = "Qual è la risposta?"
  },
  AvgDialog_13948_Content_48 = {
    Text = "Uno stormo di uccelli marini si levò improvvisamente in volo. Le loro ali bianche battevano come nuvole in movimento, fluttuando liberamente nella brezza marina."
  },
  AvgDialog_13948_Content_49 = {
    Text = "Golia non si lasciò disturbare dallo stormo di uccelli. Fissava davanti a sé, gli occhi brillanti di eccitazione."
  },
  AvgDialog_13948_Content_5 = {
    Text = "Canti antichi e inquietanti si diffondono. La sagoma di una donna appare e scompare a prua, come un fantasma errante nella nebbia."
  },
  AvgDialog_13948_Content_50 = {
    Text = "Perché io sono Golia."
  },
  AvgDialog_13948_Content_51 = {
    Text = "Golia, il condottiero più longevo nella storia dei Perishita, un gigante indomabile e un leggendario eroe tribale."
  },
  AvgDialog_13948_Content_52 = {
    Text = "Anche se restasse un solo seguace, finché c'è un barlume di speranza, posso rialzarmi."
  },
  AvgDialog_13948_Content_53 = {
    Text = "Quella strega è la mia ultima possibilità. Solo lei può concedermi il Potere assoluto."
  },
  AvgDialog_13948_Content_54 = {
    Text = "Anche se fosse una trappola, ci andrò."
  },
  AvgDialog_13948_Content_55 = {
    Text = "Allora perché salvarmi? Un \"buono a nulla\" come me probabilmente non potrà esserti di alcun aiuto..."
  },
  AvgDialog_13948_Content_56 = {
    Text = "Hai deliberatamente enfatizzato la pronuncia di una parola, facendo scoppiare Golia in una risata."
  },
  AvgDialog_13948_Content_57 = {
    Text = "La luce del sole squarcia le nuvole, proiettando un bagliore dorato. Ciocche di capelli danzano dolcemente sotto il cielo azzurro."
  },
  AvgDialog_13948_Content_58 = {
    Text = "Non c'è modo che un comandante senza truppe possa avere successo in questo mondo."
  },
  AvgDialog_13948_Content_59 = {
    Text = "Piccolo, non sei inutile.\nSei l'unico seguace del gigante Golia, e nessuno può sostituirti."
  },
  AvgDialog_13948_Content_6 = {
    Text = "Eh, qualcuno sta cantando?"
  },
  AvgDialog_13948_Content_60 = {
    Text = "Quando avrò raggiunto il mio dominio, come minimo ti nominerò capo tribù!"
  },
  AvgDialog_13948_Content_61 = {
    Text = "...Non è necessario."
  },
  AvgDialog_13948_Content_62 = {
    Text = "Il cielo si oscurò gradualmente. Il bagliore del crepuscolo somigliava a fiumi dorati e scintillanti che scorrevano lungo l'orizzonte."
  },
  AvgDialog_13948_Content_63 = {
    Text = "Ehi, lo sai? Gli eroi possono essere eroi solo grazie a persone come noi."
  },
  AvgDialog_13948_Content_64 = {
    Text = "<Small:Quindi anch'io sono importante, capito...>"
  },
  AvgDialog_13948_Content_65 = {
    Text = "<Small:Hmm...>"
  },
  AvgDialog_13948_Content_66 = {
    Text = "Parole frammentate si disperdono come soffioni nella brezza marina, portate lontano, lontanissimo."
  },
  AvgDialog_13948_Content_67 = {
    Text = "Tu e Golia eravate seduti su una sottile tavola di legno, simili a minuscole foglie alla deriva in un mare dorato."
  },
  AvgDialog_13948_Content_68 = {
    Text = "Nessuno sa dove alla fine approderete."
  },
  AvgDialog_13948_Content_7 = {
    Text = "<Shake:La strega, è la strega!>"
  },
  AvgDialog_13948_Content_8 = {
    Text = "Come è possibile... La leggenda potrebbe essere vera davvero..."
  },
  AvgDialog_13948_Content_9 = {
    Text = "<Red:Pietà.\n         Pietà.\n                  Pietà...>"
  },
  AvgDialog_139656_Content_1 = {Text = "Addio"},
  AvgDialog_139656_Content_10 = {
    Text = "Come sono adesso...? Hmm. Probabilmente è meglio di no."
  },
  AvgDialog_139656_Content_11 = {
    Text = "Dopo il collegamento di poco fa... molte cose sono cambiate."
  },
  AvgDialog_139656_Content_12 = {
    Text = "A proposito di quello... ho fatto un sogno."
  },
  AvgDialog_139656_Content_13 = {
    Text = "Nel sogno, Ramona era diventata..."
  },
  AvgDialog_139656_Content_14 = {
    Text = "Non importa quante volte l'hai rigirata nella mente, l'immagine resiste ancora alle parole. Il tuo corpo si ritrae prima che i pensieri riescano a raggiungerlo."
  },
  AvgDialog_139656_Content_15 = {
    Text = "Lo so. Eri terrorizzato. Disgustato."
  },
  AvgDialog_139656_Content_16 = {
    Text = "Il Dominio è parte del mio Paesaggio Mentale—quindi potevo percepirlo."
  },
  AvgDialog_139656_Content_17 = {
    Text = "Mi dispiace davvero, per quello che ti ho fatto passare."
  },
  AvgDialog_139656_Content_18 = {
    Text = "No—non è quello che volevo dire."
  },
  AvgDialog_139656_Content_19 = {
    Text = "Intendo... all'epoca, non sapevo se quella cosa avvolta nella carne fosse davvero lei."
  },
  AvgDialog_139656_Content_2 = {
    Text = "Il mondo è tornato \"normale\". Normale secondo gli standard del vostro mondo."
  },
  AvgDialog_139656_Content_20 = {
    Text = "Ma ora lo so. Quella era la Ramona che conosco. Quindi, adesso non ho paura."
  },
  AvgDialog_139656_Content_21 = {
    Text = "Le parole ti danno stabilità. La tua voce si fa gradualmente più ferma."
  },
  AvgDialog_139656_Content_22 = {
    Text = "L'aspetto non conta. Ciò che conta è solo il legame tra me e i miei Risvegliatori—quelli che passano attraverso i Nuclei d'Argento."
  },
  AvgDialog_139656_Content_23 = {
    Text = "Ho visto troppe cose simili per lasciarmi scuotere dalle sole apparenze."
  },
  AvgDialog_139656_Content_24 = {
    Text = "Ho visto un cuore d'oro puro nascere dalla melma più immonda del mondo;"
  },
  AvgDialog_139656_Content_25 = {
    Text = "Ho visto l'amore—vero, tenero amore—mettere radici nel più febbrile desiderio di procreazione. Quindi—"
  },
  AvgDialog_139656_Content_26 = {
    Text = "Tutto cade nel silenzio."
  },
  AvgDialog_139656_Content_27 = {
    Text = "Dopo una lunga pausa, un sorriso si propaga dall'altro lato del collegamento—calmo e sereno."
  },
  AvgDialog_139656_Content_28 = {
    Text = "...Sono così felice di averti incontrato."
  },
  AvgDialog_139656_Content_29 = {
    Text = "…Poi, nel Dominio in Scuotimento, sei caduto di nuovo in quel Sogno."
  },
  AvgDialog_139656_Content_3 = {
    Text = "Sabbia gialla soffocata nel fango di dissoluzione si estende in una distesa infinita e ululante."
  },
  AvgDialog_139656_Content_30 = {
    Text = "Wｸe&Lｨcｴ0ﾋmEｺ tｸO3 M缮yTｱhAﾉgｲ Uｸn巛iV龠ｻeRｦsItｭYｲ,ｲ %player%."
  },
  AvgDialog_139656_Content_31 = {
    Text = "Il suono viscoso e gutturale striscia fuori da una massa di carne putrescente e contorta."
  },
  AvgDialog_139656_Content_32 = {
    Text = "In un mondo ricoperto di sangue e melma, Ramona—scivolosa di fluidi—tende la mano. Le sue dita sfiorano appena il tuo mignolo."
  },
  AvgDialog_139656_Content_33 = {
    Text = "Non dimenticherò mai questo momento."
  },
  AvgDialog_139656_Content_34 = {
    Text = "Sussurri dolcemente nel tuo cuore."
  },
  AvgDialog_139656_Content_35 = {
    Text = "Mｸa&Yｨ tｴHeﾋ Sｺi3LvEｸrｱ Kﾉeｲyｸ l巛iGｻhｦTｭ yｲOｲuRｸ pAtH."
  },
  AvgDialog_139656_Content_36 = {
    Text = "Nel mezzo di carne e desolazione, stringi saldamente la mano di Ramona, fissando dritto nei suoi occhi vuoti e la sua forma macchiata di sangue."
  },
  AvgDialog_139656_Content_37 = {
    Text = "Che la Chiave d'Argento ci Guidi."
  },
  AvgDialog_139656_Content_38 = {
    Text = "La radiosità della Chiave d'Argento si diffonde attraverso il mondo intero."
  },
  AvgDialog_139656_Content_39 = {
    Text = "Una figura di un bianco puro affiora nella tua mente. È Saya, sorridente."
  },
  AvgDialog_139656_Content_4 = {
    Text = "Solo la piccola capanna nel bosco è intrisa del colore crudo e carnoso delle viscere. E attraverso il legame, percepisci Saya al suo interno. Sai che la sua fine è a pochi battiti di distanza."
  },
  AvgDialog_139656_Content_40 = {
    Text = "Qualcosa simile a bellissime ali freme nel vento."
  },
  AvgDialog_139656_Content_41 = {
    Text = "I denti di leone prendono il volo, disperdendosi nel cielo azzurro."
  },
  AvgDialog_139656_Content_42 = {
    Text = "Nel momento in cui ogni seme si stacca dallo stelo, il mondo nebuloso e onirico si ritrae nella realtà."
  },
  AvgDialog_139656_Content_43 = {
    Text = "Ti risvegli dal sogno, e tutte le cose rivelano la loro vera forma."
  },
  AvgDialog_139656_Content_44 = {Text = "Grazie..."},
  AvgDialog_139656_Content_45 = {
    Text = "Ti sembra di udire un addio sussurrato al tuo orecchio. È un'illusione?"
  },
  AvgDialog_139656_Content_46 = {
    Text = "A un certo punto, un Nucleo d'Argento appare nel palmo della tua mano."
  },
  AvgDialog_139656_Content_47 = {
    Text = "È lo stesso nucleo che Tintura trovò un tempo, quello intriso di nostalgia eterna."
  },
  AvgDialog_139656_Content_48 = {
    Text = "Quando verrà il momento, potrai usarlo—per risvegliare il suo eterno \"amore.\""
  },
  AvgDialog_139656_Content_49 = {
    Text = "—L'amore di Saya... la Risvegliatrice."
  },
  AvgDialog_139656_Content_5 = {
    Text = "Credo che le nostre anime siano legate ora. E con questo... la barriera svanirà completamente."
  },
  AvgDialog_139656_Content_50 = {Text = "Fine."},
  AvgDialog_139656_Content_6 = {
    Text = "Poter provare tutto questo nei miei ultimi istanti... sono appagata. ...Grazie."
  },
  AvgDialog_139656_Content_7 = {
    Text = "Ora—lascia questo luogo. Cammina nella sabbia. Al confine di quel mare di dune, ti ricongiungerai con il tuo passato."
  },
  AvgDialog_139656_Content_8 = {
    Text = "Va tutto bene. Anche quando non sarò più in questo mondo, la nostra coscienza resterà connessa attraverso i Nuclei d'Argento."
  },
  AvgDialog_139656_Content_9 = {
    Text = "Prima della fine... mi lascerai vedere la tua vera forma?"
  },
  AvgDialog_139657_Content_1 = {Text = "\"Scopo\""},
  AvgDialog_139657_Content_10 = {
    Text = "Qualcosa sta arrivando. Lo percepisco ai margini..."
  },
  AvgDialog_139657_Content_11 = {
    Text = "Saya aggrotta la fronte, il volto teso e pallido."
  },
  AvgDialog_139657_Content_12 = {
    Text = "Strappi la carne dal suo polso e la aiuti a rialzarsi."
  },
  AvgDialog_139657_Content_13 = {
    Text = "Voglio vedere il campo di denti di leone. Cammini un po' con me?"
  },
  AvgDialog_139657_Content_14 = {
    Text = "Dovresti riposare..."
  },
  AvgDialog_139657_Content_15 = {
    Text = "Va tutto bene. Davvero..."
  },
  AvgDialog_139657_Content_16 = {
    Text = "Saya spinge delicatamente la porta della capanna. Il mondo esterno inonda la tua vista."
  },
  AvgDialog_139657_Content_17 = {
    Text = "Il colore del campo è cambiato."
  },
  AvgDialog_139657_Content_18 = {
    Text = "Il verde rigoglioso di ieri è ora ricoperto da un'ombra profonda rosso-nera. I fili d'erba sparsi non riescono a resistere, deformati e consumati dalla decomposizione."
  },
  AvgDialog_139657_Content_19 = {
    Text = "È la <Red:Dissoluzione>……!"
  },
  AvgDialog_139657_Content_2 = {
    Text = "Sogni grotteschi ti assalgono come una marea."
  },
  AvgDialog_139657_Content_20 = {
    Text = "Sembri... triste?"
  },
  AvgDialog_139657_Content_21 = {
    Text = "Ieri questo era un bellissimo campo di denti di leone."
  },
  AvgDialog_139657_Content_22 = {
    Text = "Oggi la Dissoluzione l'ha trovato, inghiottito per intero. Tra qualche giorno, sarà completamente scomparso."
  },
  AvgDialog_139657_Content_23 = {
    Text = "E con il tempo, anche il ricordo svanirà—persino il tuo."
  },
  AvgDialog_139657_Content_24 = {
    Text = "Non ti addolora?"
  },
  AvgDialog_139657_Content_25 = {
    Text = "Hmm, è così che la vedi...?"
  },
  AvgDialog_139657_Content_26 = {
    Text = "Tu la vedi diversamente?"
  },
  AvgDialog_139657_Content_27 = {
    Text = "Mm. Ci sono sempre così tante cose diverse in questo mondo..."
  },
  AvgDialog_139657_Content_28 = {
    Text = "E i più forti prendono e saccheggiano dai più deboli."
  },
  AvgDialog_139657_Content_29 = {
    Text = "È semplicemente così, no?"
  },
  AvgDialog_139657_Content_3 = {
    Text = "La figura di Ramona appare e scompare—la sua voce lacerata nelle giunture, raschiante come aria forzata attraverso un mantice rotto."
  },
  AvgDialog_139657_Content_30 = {
    Text = "No. È esattamente per questo che Mythag esiste."
  },
  AvgDialog_139657_Content_31 = {
    Text = "Noi ci poniamo tra la Dissoluzione e tutto ciò che essa vorrebbe inghiottire—vite e ricordi che forse non sono potenti, ma portano comunque la propria luce."
  },
  AvgDialog_139657_Content_32 = {
    Text = "E questo include te, Saya."
  },
  AvgDialog_139657_Content_33 = {
    Text = "...Davvero."
  },
  AvgDialog_139657_Content_34 = {
    Text = "Lo mormora tra sé e sé."
  },
  AvgDialog_139657_Content_35 = {
    Text = "In tal caso... forse hai ragione..."
  },
  AvgDialog_139657_Content_36 = {
    Text = "Camminate attraverso il paesaggio che si ripete per quella che sembra un'eternità, finché uno spiraglio di qualcosa di diverso spezza finalmente la monotonia."
  },
  AvgDialog_139657_Content_37 = {
    Text = "Un altro campo di denti di leone...?"
  },
  AvgDialog_139657_Content_38 = {
    Text = "Saya tiene la testa bassa, respirando piano. Non riesci a vederle il volto."
  },
  AvgDialog_139657_Content_39 = {
    Text = "Questa è... la capanna da cui siamo partiti. Guarda laggiù."
  },
  AvgDialog_139657_Content_4 = {
    Text = "Ti svegli di soprassalto."
  },
  AvgDialog_139657_Content_40 = {
    Text = "Indichi l'angolo della stanza—il pezzo di carne che avevi strappato dal polso di Saya e gettato via stamattina."
  },
  AvgDialog_139657_Content_41 = {
    Text = "...Abbiamo camminato in cerchio."
  },
  AvgDialog_139657_Content_42 = {
    Text = "Non c'è nulla in questo Dominio se non desolazione."
  },
  AvgDialog_139657_Content_43 = {
    Text = "Meglio così. Possiamo... riposare un po'."
  },
  AvgDialog_139657_Content_44 = {
    Text = "Sorride come se non fosse nulla. Ma la sua voce si sfilaccia ai bordi, tremando leggermente, in un modo che non riesce del tutto a trattenere."
  },
  AvgDialog_139657_Content_45 = {
    Text = "Saya, il tuo corpo..."
  },
  AvgDialog_139657_Content_46 = {
    Text = "Sono solo un po' stanca..."
  },
  AvgDialog_139657_Content_47 = {
    Text = "Proprio davanti ai tuoi occhi, le sue ginocchia cedono—cade dritta a terra, come se tutto ciò che la sosteneva avesse semplicemente ceduto."
  },
  AvgDialog_139657_Content_48 = {Text = "Saya!"},
  AvgDialog_139657_Content_49 = {
    Text = "Nel cuore della notte, Saya brucia di febbre. Seguendo le sue indicazioni, accendi un fuoco con materiali che non sapresti nominare neanche volendo."
  },
  AvgDialog_139657_Content_5 = {
    Text = "*Coff, coff...*"
  },
  AvgDialog_139657_Content_50 = {
    Text = "Se avessi saputo che stavi così male, non ti avrei mai lasciata camminare tutto il giorno..."
  },
  AvgDialog_139657_Content_51 = {
    Text = "Va tutto bene. Non credo di essermi ammalata per la camminata.\nComunque—possiamo parlare un po'?"
  },
  AvgDialog_139657_Content_52 = {
    Text = "Certo. Di cosa vorresti parlare?"
  },
  AvgDialog_139657_Content_53 = {
    Text = "Stamattina hai detto che tu e Mythag volete combattere la Dissoluzione. Per proteggere le altre persone. Per proteggere me."
  },
  AvgDialog_139657_Content_54 = {
    Text = "Lo pensavi davvero?"
  },
  AvgDialog_139657_Content_55 = {
    Text = "Ogni singola parola. L'ho giurato il giorno in cui mi è stata concessa la Chiave d'argento."
  },
  AvgDialog_139657_Content_56 = {
    Text = "La tua voce esce più ferma di quanto ti aspettassi. Nel momento in cui le parole lasciano le tue labbra, la cerimonia riemerge nella tua mente—"
  },
  AvgDialog_139657_Content_57 = {
    Text = "Il peso fresco della Chiave d'Argento che si posa nel tuo palmo. Gli sguardi solenni della folla. La determinazione ardente nel tuo cuore quando hai chiuso le dita attorno ad essa."
  },
  AvgDialog_139657_Content_58 = {
    Text = "Saya resta in silenzio per un momento. La luce del fuoco dora la piccola curva della sua silhouette di un caldo bagliore ambrato."
  },
  AvgDialog_139657_Content_59 = {
    Text = "Allora—se un giorno perdessi il tuo potere di Custode... se diventassi una persona comune,"
  },
  AvgDialog_139657_Content_6 = {
    Text = "Saya è appoggiata alla porta della cabina, e tossisce piano."
  },
  AvgDialog_139657_Content_60 = {
    Text = "e non potessi più portare sulle spalle il dovere contro la Dissoluzione... cosa faresti?"
  },
  AvgDialog_139657_Content_61 = {
    Text = "Beh, ci ho già pensato."
  },
  AvgDialog_139657_Content_62 = {
    Text = "Ti appoggi all'indietro, puntando le mani sull'erba dietro di te, sollevando il viso verso le stelle."
  },
  AvgDialog_139657_Content_63 = {
    Text = "Passerei il resto della mia vita con le persone che amo. In tranquillità. Nella normalità."
  },
  AvgDialog_139657_Content_64 = {
    Text = "Quando saremo vecchi e canuti, troppo stanchi per correre ancora, ci siederemo attorno al focolare a raccontare le stesse buffe disavventure della nostra gioventù finché tutti non le sapranno a memoria."
  },
  AvgDialog_139657_Content_65 = {
    Text = "Ramona starebbe ancora correggendo ogni singolo nome che Lord Dexter pronuncia male. William avrebbe quella stessa espressione perfettamente composta sul viso, tenendo un libro come se stesse leggendo mentre le sue orecchie sono dritte..."
  },
  AvgDialog_139657_Content_66 = {
    Text = "La Professoressa Czort starebbe ancora aggrappata alla sua vodka, trascinando tutti a cantare non appena prende il via."
  },
  AvgDialog_139657_Content_67 = {
    Text = "Volti la testa. Saya ti osserva in silenzio. La luce del fuoco le guizza negli occhi come piccole stelle catturate."
  },
  AvgDialog_139657_Content_68 = {
    Text = "Sembra meraviglioso."
  },
  AvgDialog_139657_Content_69 = {Text = "Ma..."},
  AvgDialog_139657_Content_7 = {
    Text = "Saya! La tua mano!"
  },
  AvgDialog_139657_Content_70 = {
    Text = "La sua voce si spezza. Distoglie lo sguardo, gli occhi velati, fissi sul vuoto di un angolo buio."
  },
  AvgDialog_139657_Content_71 = {
    Text = "Se fossi separato da loro—se non ci fosse più nessuno al tuo fianco—cosa faresti?"
  },
  AvgDialog_139657_Content_72 = {
    Text = "Se ne sono andati? O non sono mai esistiti?"
  },
  AvgDialog_139657_Content_73 = {
    Text = "Se... avessi ancora i ricordi. Di averli incontrati, del tempo trascorso insieme..."
  },
  AvgDialog_139657_Content_74 = {
    Text = "Ma è passato troppo tempo. I ricordi sono in frantumi. E non sai nemmeno se siano reali..."
  },
  AvgDialog_139657_Content_75 = {
    Text = "Finché riesco ancora a ricordare, andrò a cercarli."
  },
  AvgDialog_139657_Content_76 = {
    Text = "Ovunque siano. A qualunque costo."
  },
  AvgDialog_139657_Content_77 = {
    Text = "Non c'è la minima esitazione nel tuo sguardo."
  },
  AvgDialog_139657_Content_78 = {
    Text = "Se... voglio dire, se non riuscissi a trovarli?"
  },
  AvgDialog_139657_Content_79 = {
    Text = "Continuerei a cercare comunque—lungo ogni strada, oltre ogni montagna, attraverso ogni mare..."
  },
  AvgDialog_139657_Content_8 = {
    Text = "Carne intrecciata di melma nera si è insinuata attraverso le fessure della porta, avvolgendosi attorno al suo polso."
  },
  AvgDialog_139657_Content_80 = {
    Text = "Finché la ricerca stessa non mi accompagnasse fino all'ultimo dei miei giorni."
  },
  AvgDialog_139657_Content_81 = {
    Text = "E quando quell'ultimo istante arrivasse, quando i miei occhi si chiudessero per sempre, credo che mi sentirei completo."
  },
  AvgDialog_139657_Content_82 = {
    Text = "Perché avrei vissuto con ricordi degni di essere custoditi, e una meta che ero destinato a raggiungere, a qualunque costo."
  },
  AvgDialog_139657_Content_83 = {
    Text = "La ricerca stessa è il significato."
  },
  AvgDialog_139657_Content_84 = {
    Text = "Cala il silenzio mentre le tue parole si posano. Resta solo il lieve fruscio dei denti di leone nella brezza."
  },
  AvgDialog_139657_Content_85 = {Text = "...Saya?"},
  AvgDialog_139657_Content_86 = {
    Text = "Saya ha chiuso gli occhi. Il suo viso è pallido, quasi trasparente. Il tuo cuore si stringe."
  },
  AvgDialog_139657_Content_87 = {Text = "Saya..."},
  AvgDialog_139657_Content_88 = {
    Text = "Ti avvicini—e scopri che il suo respiro è lento e regolare, il petto che si alza e si abbassa in un ritmo appena percettibile, come la più piccola increspatura su un lago immobile."
  },
  AvgDialog_139657_Content_89 = {
    Text = "Hmm, stai solo dormendo..."
  },
  AvgDialog_139657_Content_9 = {
    Text = "Cambiamenti come questi... non sono ciò che mi preoccupa."
  },
  AvgDialog_139657_Content_90 = {
    Text = "Sono... un po' stanca anch'io..."
  },
  AvgDialog_139657_Content_91 = {
    Text = "Il sollievo ti colpisce tutto in una volta, e con esso, la stanchezza della giornata e lo sforzo visivo di quel paesaggio infernale ti sopraffanno."
  },
  AvgDialog_139657_Content_92 = {
    Text = "Prima che giunga la fine, anche questa notte scivola silenziosamente tra le tue dita."
  },
  AvgDialog_139658_Content_1 = {
    Text = "Dopo la Pioggia"
  },
  AvgDialog_139658_Content_10 = {
    Text = "Che bello... sentire il sole."
  },
  AvgDialog_139658_Content_11 = {
    Text = "Sorride, allungando la mano verso il punto in cui cade la luce, come una pianta che si protende verso il sole."
  },
  AvgDialog_139658_Content_12 = {
    Text = "Mi aiuti ad andare fuori?"
  },
  AvgDialog_139658_Content_13 = {
    Text = "La guidi a sedersi contro la parete della capanna. Anche questo breve tragitto le lascia il respiro affannoso e superficiale."
  },
  AvgDialog_139658_Content_14 = {
    Text = "Saya, il tuo corpo..."
  },
  AvgDialog_139658_Content_15 = {
    Text = "Non preoccuparti. Credo che il mio tempo sia quasi scaduto."
  },
  AvgDialog_139658_Content_16 = {
    Text = "Lo senti anche tu, vero? La barriera che blocca il nostro legame... si sta sgretolando."
  },
  AvgDialog_139658_Content_17 = {
    Text = "Non passerà molto prima che collassi del tutto.\nQuando succederà... dovremmo riuscire a stabilire il collegamento di cui parlavi."
  },
  AvgDialog_139658_Content_18 = {Text = "Ma..."},
  AvgDialog_139658_Content_19 = {
    Text = "Una volta formato il collegamento, Saya potrebbe scomparire. Quella barriera è il suo ultimo scudo—e si sta assottigliando solo perché le sue forze stanno venendo meno."
  },
  AvgDialog_139658_Content_2 = {
    Text = "Quando ti svegli, la luce è cambiata."
  },
  AvgDialog_139658_Content_20 = {
    Text = "Per favore, non trattenerti. Averti qui con me, poter parlare così... sono davvero felice."
  },
  AvgDialog_139658_Content_21 = {
    Text = "Socchiude gli occhi contro la luce, offrendo un sorriso sincero eppure fragile. Riesci a malapena a guardarla, ma ti sforzi di imprimere ogni dettaglio nella memoria."
  },
  AvgDialog_139658_Content_22 = {
    Text = "Resterò con te. Fino alla fine."
  },
  AvgDialog_139658_Content_23 = {
    Text = "Dai, non fare quella faccia cupa. Riprendiamo da dove ci eravamo interrotti ieri."
  },
  AvgDialog_139658_Content_24 = {
    Text = "Hai detto che anche senza il tuo potere, anche senza più nessuno al tuo fianco, avresti continuato ad andare avanti."
  },
  AvgDialog_139658_Content_25 = {
    Text = "Voglio sapere perché."
  },
  AvgDialog_139658_Content_26 = {
    Text = "Perché? La luce del sole dopo la pioggia è così intensa da far bruciare gli occhi di lacrime trattenute."
  },
  AvgDialog_139658_Content_27 = {
    Text = "Fai un respiro lento e profondo."
  },
  AvgDialog_139658_Content_28 = {
    Text = "Perché amo Ramona. Amo tutti all'Università di Mythag.\nE so—con certezza—che anche loro amano me."
  },
  AvgDialog_139658_Content_29 = {
    Text = "Ma siete così lontani. Non potete toccarvi. Non potete confermare ciò che l'altro prova."
  },
  AvgDialog_139658_Content_3 = {
    Text = "L'aria umida porta un profumo puro, lavato. Ciò che filtra attraverso le fessure della porta non è più il vento, ma un quieto raggio di luce."
  },
  AvgDialog_139658_Content_30 = {
    Text = "E in un mondo con qualcosa come la Dissoluzione—come puoi essere sicura che le persone che ti mancano non ti abbiano già dimenticata?"
  },
  AvgDialog_139658_Content_31 = {
    Text = "La sua voce è sommessa, quasi come un sogno mormorato sul confine del sonno."
  },
  AvgDialog_139658_Content_32 = {
    Text = "La Dissoluzione può cancellare la presenza—ma i Nuclei d'Argento legano me e Ramona attraverso il mare del subconscio."
  },
  AvgDialog_139658_Content_33 = {
    Text = "Guardi verso l'orizzonte. Il panorama dopo la pioggia è di una limpidezza impossibile. Il vento squarcia un varco tra le nuvole, e una colonna di luce dorata si riversa attraverso, colpendo il crinale in lontananza."
  },
  AvgDialog_139658_Content_34 = {
    Text = "Riesco a sentire la sua presenza. Anche adesso, anche dispersi in mondi diversi—questo non è cambiato."
  },
  AvgDialog_139658_Content_35 = {Text = "E poi..."},
  AvgDialog_139658_Content_36 = {Text = "Hm?"},
  AvgDialog_139658_Content_37 = {
    Text = "Inclina leggermente la testa."
  },
  AvgDialog_139658_Content_38 = {
    Text = "I veri amanti non hanno bisogno di stare fianco a fianco per sentire il loro legame... o per confermare il loro amore."
  },
  AvgDialog_139658_Content_39 = {
    Text = "Non importa quante volte il mondo finisce e ricomincia, troverò sempre Ramona. E lei farà sempre la stessa scelta."
  },
  AvgDialog_139658_Content_4 = {
    Text = "...È così silenzioso fuori."
  },
  AvgDialog_139658_Content_40 = {
    Text = "Lo so e basta. I pensieri e i sentimenti che condividiamo nel mare della coscienza... non saranno mai recisi."
  },
  AvgDialog_139658_Content_41 = {
    Text = "Saya resta in silenzio a lungo. Il vento lavato dalla pioggia si insinua nella cabina, sfiorando la sua guancia esangue."
  },
  AvgDialog_139658_Content_42 = {
    Text = "Poi sorride."
  },
  AvgDialog_139658_Content_43 = {
    Text = "Una fiducia così feroce, così incrollabile... Un amore così grande..."
  },
  AvgDialog_139658_Content_44 = {
    Text = "Quando pronuncia quella parola—amore—nella sua voce non c'è invidia. Nessun dolore. Nessuna traccia di rimpianto."
  },
  AvgDialog_139658_Content_45 = {
    Text = "Solo una profonda tenerezza."
  },
  AvgDialog_139658_Content_46 = {
    Text = "Come una viaggiatrice che ha camminato sola attraverso una lunga notte d'inverno, e finalmente scorge la prima luce dell'alba sul bordo lontano dell'orizzonte—forse non la raggiungerà mai. Ma sapere che quella luce esiste le basta."
  },
  AvgDialog_139658_Content_47 = {
    Text = "Saya sorride, persa in una trance."
  },
  AvgDialog_139658_Content_48 = {
    Text = "Poi tende la mano verso di te."
  },
  AvgDialog_139658_Content_49 = {
    Text = "...Stringimi la mano."
  },
  AvgDialog_139658_Content_5 = {
    Text = "La pioggia... si è fermata?"
  },
  AvgDialog_139658_Content_50 = {
    Text = "La sua mano è pallida, esile e trema leggermente. Non può vederti, eppure la sua mano si protende infallibilmente nella tua direzione—"
  },
  AvgDialog_139658_Content_51 = {
    Text = "come guidata da qualcosa di più antico della vista, più profondo del linguaggio."
  },
  AvgDialog_139658_Content_52 = {
    Text = "Allunghi la mano e stringi la sua."
  },
  AvgDialog_139658_Content_53 = {
    Text = "E nell'istante in cui i vostri palmi si incontrano—"
  },
  AvgDialog_139658_Content_54 = {
    Text = "Un dolore acuto esplode dietro i tuoi occhi."
  },
  AvgDialog_139658_Content_55 = {
    Text = "Qualcosa di ben più tagliente—rovente, incandescente—si conficca come un fulmine nel tuo cranio, colpendo dritto nel nucleo più profondo della tua mente."
  },
  AvgDialog_139658_Content_56 = {
    Text = "La tua vista vacilla violentemente."
  },
  AvgDialog_139658_Content_57 = {
    Text = "Vedi soffioni umidi che brillano alla luce del sole. Il profilo pallido e tranquillo di Saya. Il sorriso che increspa le sue labbra screpolate—"
  },
  AvgDialog_139658_Content_58 = {
    Text = "E poi tutto si spezza in un universo di carne. Il cielo diventa rosso sangue. La terra diventa rosso sangue. Persino la Saya proprio davanti a te—"
  },
  AvgDialog_139658_Content_59 = {Text = "No—"},
  AvgDialog_139658_Content_6 = {
    Text = "Saya guarda verso la finestra, lo sguardo velato e sfocato."
  },
  AvgDialog_139658_Content_60 = {
    Text = "Due mondi lampeggiano, si sovrappongono e si fondono davanti ai tuoi occhi. Due fiumi che non avrebbero mai dovuto incontrarsi si scontrano violentemente in un crocevia impossibile."
  },
  AvgDialog_139658_Content_61 = {
    Text = "Il legame tra te e Saya è completo."
  },
  AvgDialog_139658_Content_7 = {
    Text = "La luce del sole le cade negli occhi come una pietra cade nell'acqua ferma—senza sollevare alcuna increspatura."
  },
  AvgDialog_139658_Content_8 = {Text = "Sì."},
  AvgDialog_139658_Content_9 = {
    Text = "Le parole escono ruvide."
  },
  AvgDialog_139659_Content_1 = {Text = "\"Amore\""},
  AvgDialog_139659_Content_10 = {
    Text = "Saya è in piedi nel campo di denti di leone, immersa nella luce del mattino."
  },
  AvgDialog_139659_Content_11 = {
    Text = "La pioggia ha staccato innumerevoli semi dai loro steli. Sono caduti sulla terra cremisi e nera—e alcuni, incredibilmente, hanno già iniziato a germogliare."
  },
  AvgDialog_139659_Content_12 = {
    Text = "Nati in una notte, cresciuti in una notte..."
  },
  AvgDialog_139659_Content_13 = {
    Text = "Dalla tua espressione... ti è venuto in mente qualcosa?"
  },
  AvgDialog_139659_Content_14 = {
    Text = "Sì. Una volta ho visto uno spettacolo simile nei deserti di Aram."
  },
  AvgDialog_139659_Content_15 = {
    Text = "La terra laggiù è benedetta dall'Albero Madre. I discendenti della sua stirpe mettono radici ovunque cadano, crescendo con il vento."
  },
  AvgDialog_139659_Content_16 = {
    Text = "Sembra bello, non trovi?"
  },
  AvgDialog_139659_Content_17 = {
    Text = "...Ma dal modo in cui l'hai detto, non sembra che tu la pensi così."
  },
  AvgDialog_139659_Content_18 = {
    Text = "Non sta a me giudicare. Sono un'estranea in quella storia."
  },
  AvgDialog_139659_Content_19 = {
    Text = "È solo che... credo che per la maggior parte delle persone, ogni fase della vita conti."
  },
  AvgDialog_139659_Content_2 = {
    Text = "Tu e Saya vi rannicchiate ciascuno nel proprio angolo della capanna. La notte trascorre in silenzio."
  },
  AvgDialog_139659_Content_20 = {
    Text = "Neferure, per esempio. Non ha mai avuto una vera infanzia. Non ha mai saputo cosa significasse essere accudito da un genitore. È stato gettato nella guerra contro il Muro della Tempesta prima che tutto ciò potesse accadere..."
  },
  AvgDialog_139659_Content_21 = {
    Text = "Saya annuisce, non del tutto certa di comprendere."
  },
  AvgDialog_139659_Content_22 = {
    Text = "Quindi per gli umani, anche la durata di una vita conta?"
  },
  AvgDialog_139659_Content_23 = {
    Text = "Più di quello. Ogni esperienza, ogni persona che incontri—diventano tutte parte dei ricordi che porti con te."
  },
  AvgDialog_139659_Content_24 = {
    Text = "Quei ricordi, stratificati nel tempo, sono ciò che rende una persona quello che è."
  },
  AvgDialog_139659_Content_25 = {
    Text = "Si potrebbe persino dire che gli umani sono recipienti per la memoria.\nAnche dopo che il corpo non c'è più, la memoria continua—tramandata, finché l'ultima persona che la custodisce non dimentica."
  },
  AvgDialog_139659_Content_26 = {
    Text = "Capisco... credo di aver compreso."
  },
  AvgDialog_139659_Content_27 = {
    Text = "Allora—se un giorno dovessi morire, il ricordo di oggi, di essere qui con te così, diventerà parte di ciò che sei?"
  },
  AvgDialog_139659_Content_28 = {Text = "Sì."},
  AvgDialog_139659_Content_29 = {
    Text = "All'ombra del fragile sorriso di Saya, annuisci con fermezza."
  },
  AvgDialog_139659_Content_3 = {
    Text = "A un certo punto, la stanchezza ti trascina in un sonno profondo."
  },
  AvgDialog_139659_Content_30 = {
    Text = "La giornata trascorre tra esplorazioni e passeggiate lungo il confine."
  },
  AvgDialog_139659_Content_31 = {
    Text = "Oltre il campo di denti di leone, lo stesso paesaggio desolato si ripete in ogni direzione. La terra è sepolta sotto la carne, irriconoscibile sotto strati di rosso e nero."
  },
  AvgDialog_139659_Content_32 = {
    Text = "Un senso di inquietudine mette radici nel tuo petto, insinuandosi nei tuoi pensieri. Lo reprimi a forza."
  },
  AvgDialog_139659_Content_33 = {
    Text = "(Se non c'è nulla qui fuori, allora il nucleo di questo Dominio può essere solo...)"
  },
  AvgDialog_139659_Content_34 = {
    Text = "La notte cala di nuovo."
  },
  AvgDialog_139659_Content_35 = {
    Text = "Riposati un po'. Mi sento un po' stanca."
  },
  AvgDialog_139659_Content_36 = {
    Text = "Bene. Vorrei andare a dormire presto—più lontano riusciremo a esplorare domani, meglio sarà."
  },
  AvgDialog_139659_Content_37 = {
    Text = "Detto questo, vi addormentate entrambi."
  },
  AvgDialog_139659_Content_38 = {Text = "..."},
  AvgDialog_139659_Content_39 = {
    Text = "Qualcosa ti sveglia. Un suono—o un calore. Un calore che si insinua sotto la pelle—come se fossi di nuovo nel deserto."
  },
  AvgDialog_139659_Content_4 = {
    Text = "(Che freddo... Spero che domani potrò dormire in un vero letto...)"
  },
  AvgDialog_139659_Content_40 = {Text = "?!!"},
  AvgDialog_139659_Content_41 = {
    Text = "La testa ti gira. Non riesci a capire se è la scena inquietante davanti a te, o la foschia che aleggia nell'aria."
  },
  AvgDialog_139659_Content_42 = {
    Text = "O l'influenza del Fiume sacro."
  },
  AvgDialog_139659_Content_43 = {
    Text = "Che peccato — speravate in qualcun altro?"
  },
  AvgDialog_139659_Content_44 = {
    Text = "La Regina di Aram—Thais—scosta il lembo della tenda ed entra, premendosi contro di te senza ritegno. Il suo velo diafano si avvinghia al tuo braccio, un invito sfrontato."
  },
  AvgDialog_139659_Content_45 = {
    Text = "Venite — abbracciate la stirpe di Aram, diventate uno di noi."
  },
  AvgDialog_139659_Content_46 = {
    Text = "Vieni da me, abbracciami... dammi il tuo sangue, il tuo seme..."
  },
  AvgDialog_139659_Content_47 = {
    Text = "Il fuoco danza nei suoi occhi ferventi, le guance arrossate tradiscono una brama febbrile."
  },
  AvgDialog_139659_Content_48 = {
    Text = "Solo una goccia — una volta che la nostra carne si mescola, Lei ci concederà il futuro che bramiamo..."
  },
  AvgDialog_139659_Content_49 = {
    Text = "Lascia che... generiamo eredi per la tribù, e condividiamo un'eternità di..."
  },
  AvgDialog_139659_Content_5 = {
    Text = "Qualcosa si posa su di te nel buio."
  },
  AvgDialog_139659_Content_50 = {
    Text = "Trascini la ragione su da qualche luogo profondo, lottando contro l'attrazione delle sue parole. La campana che per prima ti svegliò come Custode resta in silenzio."
  },
  AvgDialog_139659_Content_51 = {
    Text = "E poi—una voce diversa squarcia l'aria."
  },
  AvgDialog_139659_Content_52 = {
    Text = "Perché? Perché continui a rifiutare?"
  },
  AvgDialog_139659_Content_53 = {
    Text = "È apparsa da un angolo della tenda senza fare alcun rumore."
  },
  AvgDialog_139659_Content_54 = {
    Text = "La sua voce è diversa dal solito. Qualcosa di più pesante si cela sotto le sue parole, qualcosa che non riesci a definire."
  },
  AvgDialog_139659_Content_55 = {
    Text = "La riproduzione... Credo sia una cosa buona. Lo scopo di tutti gli esseri viventi..."
  },
  AvgDialog_139659_Content_56 = {
    Text = "Ma perché non vuoi accettarlo?"
  },
  AvgDialog_139659_Content_57 = {
    Text = "Perché? Perché continui a rifiutare?"
  },
  AvgDialog_139659_Content_58 = {
    Text = "Perché questo non ha nulla a che fare con l'amore. Questa è solo tentazione."
  },
  AvgDialog_139659_Content_59 = {
    Text = "La tentazione non è amore. Il dovere non è amore. Il desiderio non è amore."
  },
  AvgDialog_139659_Content_6 = {Text = "...Hmm?"},
  AvgDialog_139659_Content_60 = {
    Text = "L'amore è—"
  },
  AvgDialog_139659_Content_61 = {
    Text = "L'amore è—"
  },
  AvgDialog_139659_Content_62 = {
    Text = "Il mondo si spegne."
  },
  AvgDialog_139659_Content_63 = {
    Text = "Tutto sprofonda in un'oscurità lunga e senza luce."
  },
  AvgDialog_139659_Content_7 = {
    Text = "Una sottile coperta è stata adagiata su di te."
  },
  AvgDialog_139659_Content_8 = {
    Text = "Il cielo si è schiarito."
  },
  AvgDialog_139659_Content_9 = {
    Text = "È ora di uscire."
  },
  AvgDialog_139660_Content_1 = {Text = "\"Memorie\""},
  AvgDialog_139660_Content_10 = {
    Text = "E hai ragione, non sono esattamente una persona ordinaria. Sono un investigatore dell'Università di Mythag."
  },
  AvgDialog_139660_Content_11 = {
    Text = "C'è un'espressione perplessa sul volto di Saya—chiaramente questi termini non significano nulla per lei."
  },
  AvgDialog_139660_Content_12 = {
    Text = "È una lunga storia. In questo momento, ho qualcosa di più urgente di cui occuparmi."
  },
  AvgDialog_139660_Content_13 = {
    Text = "La mia compagna, Ramona. Ho visto qualcosa consumarla. È diventata—"
  },
  AvgDialog_139660_Content_14 = {
    Text = "Non finisci la frase. Non ci riesci."
  },
  AvgDialog_139660_Content_15 = {
    Text = "Le parole sono solo simboli vuoti. Non possono portare ciò che hai provato in quel momento—la paura che ti è strisciata su dalla base della spina dorsale."
  },
  AvgDialog_139660_Content_16 = {
    Text = "La paura di perdere Ramona per sempre."
  },
  AvgDialog_139660_Content_17 = {
    Text = "È insostituibile per me."
  },
  AvgDialog_139660_Content_18 = {
    Text = "Lo sguardo di Saya si perde nel vuoto per un istante."
  },
  AvgDialog_139660_Content_19 = {
    Text = "Insostituibile... Capisco."
  },
  AvgDialog_139660_Content_2 = {
    Text = "Prima che tu possa mettere ordine tra le tue domande, è lei a parlare per prima."
  },
  AvgDialog_139660_Content_20 = {
    Text = "Credo di aver avuto... qualcuno così anch'io."
  },
  AvgDialog_139660_Content_21 = {
    Text = "Abbassa lo sguardo, con la fronte aggrottata, mormorando tra sé."
  },
  AvgDialog_139660_Content_22 = {
    Text = "C'era qualcuno. Una persona molto importante. Dovrei ricordare il suo volto... devo ricordarlo. Ma quando provo a immaginarlo adesso, tutto ciò che vedo è—"
  },
  AvgDialog_139660_Content_23 = {
    Text = "—solo un contorno. Come guardare attraverso un vetro smerigliato. So che era lì. So che era importante. Ma tutti i dettagli sono stati... cancellati."
  },
  AvgDialog_139660_Content_24 = {
    Text = "Non è solo lui. Tutto il resto è uguale. So che c'è qualcosa che devo fare—qualcosa di importante."
  },
  AvgDialog_139660_Content_25 = {
    Text = "Ma i ricordi continuano a combattersi a vicenda. Uno dice che era gentile; il successivo dice che sono rimasta in un posto molto buio per molto tempo. Uno dice che stavo aspettando che qualcuno venisse a prendermi; un altro dice che dovevo fare qualcosa... che avrebbe spaventato le persone."
  },
  AvgDialog_139660_Content_26 = {
    Text = "Ogni frammento sembra reale. Ma non si incastrano insieme."
  },
  AvgDialog_139660_Content_27 = {
    Text = "Ogni frammento sembra reale. Ma semplicemente non si incastrano."
  },
  AvgDialog_139660_Content_28 = {
    Text = "Hai già visto questa condizione."
  },
  AvgDialog_139660_Content_29 = {
    Text = "Non so quali parti siano davvero accadute. Non so quali ricordi siano davvero miei..."
  },
  AvgDialog_139660_Content_3 = {
    Text = [[
Io sono... hmm, puoi chiamarmi Saya.
Sai dove ci troviamo?]]
  },
  AvgDialog_139660_Content_30 = {
    Text = "Non so quali parti siano davvero accadute. Non so quali ricordi siano veramente miei..."
  },
  AvgDialog_139660_Content_31 = {
    Text = "Le dita di Saya si chiudono verso l'interno, come se cercassero di afferrare qualcosa che non esiste più."
  },
  AvgDialog_139660_Content_32 = {
    Text = "Mentre lei vacilla, il mondo intorno a te inizia a mutare."
  },
  AvgDialog_139660_Content_33 = {Text = "Attento!"},
  AvgDialog_139660_Content_34 = {
    Text = "Guardi verso il bordo del campo di denti di leone. La membrana carnosa, intrisa di melma nera, sta premendo verso l'interno centimetro dopo centimetro. Il confine sembra meno definito di prima."
  },
  AvgDialog_139660_Content_4 = {
    Text = "Perché mi trovo in un posto come questo...\nHmm—ci sono così tante cose che non riesco a ricordare."
  },
  AvgDialog_139660_Content_5 = {
    Text = "...Tu non sei una persona ordinaria, vero?\nHai qualche tipo di abilità speciale...?"
  },
  AvgDialog_139660_Content_6 = {
    Text = "Non rispondi subito. La ragazza di nome Saya lascia andare la tua mano, fa mezzo passo indietro, gli occhi che si restringono mentre ti scruta."
  },
  AvgDialog_139660_Content_7 = {
    Text = "Mi hai vista e non hai provato nulla? Perché sei venuto qui?"
  },
  AvgDialog_139660_Content_8 = {
    Text = "Aspetta, una domanda alla volta."
  },
  AvgDialog_139660_Content_9 = {
    Text = "Da quello che posso capire, questo è molto probabilmente un Dominio."
  },
  AvgDialog_139661_Content_1 = {
    Text = "Paesaggio Mentale"
  },
  AvgDialog_139661_Content_10 = {
    Text = "Una bella ragazza e un giovane uomo."
  },
  AvgDialog_139661_Content_11 = {
    Text = "Mano nella mano, camminano insieme attraverso la landa desolata e ululante."
  },
  AvgDialog_139661_Content_12 = {Text = "..."},
  AvgDialog_139661_Content_13 = {
    Text = "Lei ridacchia, aprendo le braccia per abbracciare il vento."
  },
  AvgDialog_139661_Content_14 = {
    Text = "Il giovane uomo accanto a lei si avvicina, ascoltando attentamente ogni sua dolce parola."
  },
  AvgDialog_139661_Content_15 = {
    Text = "Il cielo è limpido, eppure tinto di una quieta malinconia."
  },
  AvgDialog_139661_Content_16 = {
    Text = "Ma nella loro sagoma condivisa, scorgi un barlume di gioia silenziosa e spontanea."
  },
  AvgDialog_139661_Content_17 = {
    Text = "Anche se non c'era nessun altro intorno, anche se non ricevevano comprensione o benedizioni da nessuno, il loro amore comunque—"
  },
  AvgDialog_139661_Content_18 = {
    Text = "Poi il sogno si interrompe. La tempesta di sabbia spazza via ogni cosa."
  },
  AvgDialog_139661_Content_19 = {
    Text = "Il mondo sprofonda nel nero del vuoto."
  },
  AvgDialog_139661_Content_2 = {
    Text = "Il mondo è fatto di sabbia."
  },
  AvgDialog_139661_Content_20 = {
    Text = "—C'era una volta una cantante, che si faceva strada tra le stelle."
  },
  AvgDialog_139661_Content_21 = {
    Text = "In un universo arido e desolato, trovò un Nucleo d'Argento adagiato nella polvere."
  },
  AvgDialog_139661_Content_22 = {
    Text = "Nel momento in cui lo toccò, \"Io\" mi risvegliai."
  },
  AvgDialog_139661_Content_23 = {
    Text = "\"Io\" avevo perso ogni ricordo. Ma sapevo una cosa: dovevo trovare quella \"persona insostituibile\"."
  },
  AvgDialog_139661_Content_24 = {
    Text = "\"Io\" chiesi alla cantante se potevamo viaggiare insieme, ma la richiesta fu rifiutata."
  },
  AvgDialog_139661_Content_25 = {
    Text = "Vado a cercare colei che per me è tutto—mia sorella."
  },
  AvgDialog_139661_Content_26 = {
    Text = "Fu quello che disse."
  },
  AvgDialog_139661_Content_27 = {
    Text = "Spero che anche tu trovi il tuo amore, Saya. Ti auguro davvero un lieto fine."
  },
  AvgDialog_139661_Content_28 = {
    Text = "Con quelle parole, la cantante se ne andò."
  },
  AvgDialog_139661_Content_29 = {
    Text = "E così, rimasta senza il mio passato e ora senza la cantante,"
  },
  AvgDialog_139661_Content_3 = {
    Text = "Tra i venti che hanno spazzato questo deserto per ere, ti trovi alla deriva, contemplando il tutto."
  },
  AvgDialog_139661_Content_30 = {
    Text = "portai con me la sua benedizione mentre camminavo sola per questo mondo."
  },
  AvgDialog_139661_Content_31 = {
    Text = "Per trovare colei che un tempo era insostituibile... per ricomporre ciò che avevo perduto..."
  },
  AvgDialog_139661_Content_32 = {
    Text = "Continuai ad andare avanti, credendo che ciò che cercavo mi attendesse poco più in là."
  },
  AvgDialog_139661_Content_33 = {
    Text = "Finché, alla fine... incontrai te."
  },
  AvgDialog_139661_Content_4 = {
    Text = "Questo luogo..."
  },
  AvgDialog_139661_Content_5 = {
    Text = "Nessuna melma della Dissoluzione. Nessuna massa sconfinata di viscere."
  },
  AvgDialog_139661_Content_6 = {
    Text = "Il paesaggio qui è solitario, puro e bellissimo."
  },
  AvgDialog_139661_Content_7 = {
    Text = "Questo è il mio Paesaggio Mentale."
  },
  AvgDialog_139661_Content_8 = {
    Text = "Un frammento della mia esistenza—qualcosa di insostituibile, qualcosa che non dovrebbe mai essere dimenticato..."
  },
  AvgDialog_139661_Content_9 = {
    Text = "La sabbia si sposta e rotola, e nell'angolo più lontano del deserto, due figure emergono."
  },
  AvgDialog_139662_Content_10 = {
    Text = "Come tua assistente, sarò con te fino alla fine... <Yellow:Che la Chiave d'Argento Illumini il Cammino.>"
  },
  AvgDialog_139662_Content_11 = {
    Text = "Tutto bene, %player%? Sei un po' pallido/a. Dovremmo fare un salto in infermeria?"
  },
  AvgDialog_139662_Content_12 = {Text = "Ramona..."},
  AvgDialog_139662_Content_13 = {
    Text = "Il nome ti si blocca in gola. Non riesci a pronunciare il suo nome—il nome che conosci così bene."
  },
  AvgDialog_139662_Content_14 = {
    Text = "<Shake:<Red:Mmｦ,ﾋ assicu5razioneｸk iniziaQ...ﾃ è爨 meglioｨ collegarsiA con meﾑ鑷链9ｴﾅ.>>"
  },
  AvgDialog_139662_Content_15 = {
    Text = "<Shake:<Red:Léggeroｷ anticipo z(diﾉ tempoｲ驫ｲ di8 unﾃP po'ｬ, maﾗ nonｸ importaﾎ関靇ﾑ, noW?ｦJ?>>"
  },
  AvgDialog_139662_Content_16 = {
    Text = "<Red:Sbagliato, sbagliato, sbagliato, sbagliato. Tutto è sbagliato.>"
  },
  AvgDialog_139662_Content_17 = {
    Text = "<Shake:<Red:ﾒDaｩﾇ龥 anniｯ fa7開ﾘ,L aspettoﾝ questoQ giornoｱ齉月ﾏ conr impazienza今ｮ麤.>>"
  },
  AvgDialog_139662_Content_18 = {
    Text = "<Shake:No, quella non è Ramona. Ramona non potrebbe essere una massa di carne deforme e ripugnante, non emetterebbe quel ronzio nauseante, non avrebbe il corpo che trabocca di D-melma nerissima……>"
  },
  AvgDialog_139662_Content_19 = {
    Text = "<Red:Non fisserebbe con quegli Occhi neri e vuoti, puntati su di me senza sosta —>"
  },
  AvgDialog_139662_Content_2 = {
    Text = "Blo0ﾝdiｲwoRｮ"
  },
  AvgDialog_139662_Content_20 = {Text = "No—!"},
  AvgDialog_139662_Content_21 = {
    Text = "Quello era... un Sogno?"
  },
  AvgDialog_139662_Content_22 = {
    Text = "Ti svegli di soprassalto, madido di sudore freddo."
  },
  AvgDialog_139662_Content_23 = {
    Text = "Che sogno strano. Anche da sveglio, continua a persistere davanti ai miei occhi."
  },
  AvgDialog_139662_Content_24 = {
    Text = "Quello che stai vedendo... è..."
  },
  AvgDialog_139662_Content_25 = {Text = "È..."},
  AvgDialog_139662_Content_26 = {
    Text = "<Shake:<Red:Carne. Grandi blocchi di carne ammassati e sovrapposti.>>"
  },
  AvgDialog_139662_Content_27 = {
    Text = "Viscere cremisi e contorte che ricoprono le pareti, strangolano i pilastri, strisciano sulle finestre.\nE tra le crepe della carne—"
  },
  AvgDialog_139662_Content_28 = {
    Text = "Un liquido nero sta filtrando fuori."
  },
  AvgDialog_139662_Content_29 = {
    Text = "Dissoluzione."
  },
  AvgDialog_139662_Content_3 = {
    Text = "Dolore. Dolore lancinante. Un cremisi scuro inonda le tue retine."
  },
  AvgDialog_139662_Content_30 = {
    Text = "Hai già visto la Dissoluzione. Troppe volte. Ma mai così—due mali distinti che lacerano un singolo corpo contemporaneamente."
  },
  AvgDialog_139662_Content_31 = {Text = "Ramona..."},
  AvgDialog_139662_Content_32 = {
    Text = "L'immagine torna a lampeggiare. Orbite nere e vuote. Contorni Distorti e gonfi. Le sue dita nel palmo della tua mano si trasformano in <Shake:escrescenze di carne irregolari> —"
  },
  AvgDialog_139662_Content_33 = {
    Text = "No—basta. Smetti di pensare—"
  },
  AvgDialog_139662_Content_34 = {
    Text = "È ancora là fuori—deve essere da qualche parte—"
  },
  AvgDialog_139662_Content_35 = {
    Text = "Un debole tremore si propaga nella tua mente. Quasi impercettibile."
  },
  AvgDialog_139662_Content_36 = {
    Text = "Istintivamente, cerchi la fonte—non è Ramona. Riconosceresti Ramona a occhi chiusi; le sue onde spirituali sono calme e morbide, come la superficie di un lago immobile."
  },
  AvgDialog_139662_Content_37 = {
    Text = "Vai a est..."
  },
  AvgDialog_139662_Content_38 = {Text = "Chi?"},
  AvgDialog_139662_Content_39 = {
    Text = "Nessuna risposta."
  },
  AvgDialog_139662_Content_4 = {
    Text = "La mia testa..."
  },
  AvgDialog_139662_Content_40 = {
    Text = "Senza altri indizi, ti muovi verso il suono."
  },
  AvgDialog_139662_Content_41 = {
    Text = "Attraversi un fiume che puzza di ruggine e putrefazione. Calpesti un terreno simile a una membrana infestato da tendini rosso scuro."
  },
  AvgDialog_139662_Content_42 = {
    Text = "Il tuo respiro si fa affannoso; i tuoi nervi pulsano sotto l'invasione di quei colori eldritch."
  },
  AvgDialog_139662_Content_43 = {
    Text = "Qualcuno... chiunque... fatemi uscire da questo sogno..."
  },
  AvgDialog_139662_Content_44 = {
    Text = "Deve essere un sogno. La sensazione è troppo reale—ma devi crederci. Devi."
  },
  AvgDialog_139662_Content_45 = {
    Text = "Qualcosa di morbido e bianco si posa sulla punta del tuo naso."
  },
  AvgDialog_139662_Content_46 = {
    Text = "Un soffione...?"
  },
  AvgDialog_139662_Content_47 = {
    Text = "Metti piede su un confine. Uno visibile—una linea netta e inconfondibile che divide due mondi."
  },
  AvgDialog_139662_Content_48 = {
    Text = "Oltre di esso: carne nauseante e melma nera ribollente."
  },
  AvgDialog_139662_Content_49 = {
    Text = "Al suo interno: un piccolo campo di denti di leone. Al centro, una piccola capanna di legno."
  },
  AvgDialog_139662_Content_5 = {
    Text = "Una luce fioca e tremolante, un ronzio che echeggia nei tuoi timpani. Non ci si può fidare di questo mondo. Tutto ciò che vedi è solo un'illusione."
  },
  AvgDialog_139662_Content_50 = {
    Text = "Qualcosa si muove tra i denti di leone."
  },
  AvgDialog_139662_Content_51 = {
    Text = "Segui il movimento. Un ciuffo bianco viene scostato, rivelando un angolo di tessuto pallido."
  },
  AvgDialog_139662_Content_52 = {
    Text = "Poi lei si alza in piedi."
  },
  AvgDialog_139662_Content_53 = {
    Text = "Una ragazza, fragile e leggera come un dente di leone."
  },
  AvgDialog_139662_Content_54 = {
    Text = "Inclina la testa, osservando la tua espressione."
  },
  AvgDialog_139662_Content_55 = {
    Text = "Non hai paura di me?"
  },
  AvgDialog_139662_Content_56 = {
    Text = "È quasi ironico. Dopo tutto quello che hai attraversato, lei è l'unico essere umano normale che hai visto. L'unica esistenza che non sia spaventosa."
  },
  AvgDialog_139662_Content_57 = {
    Text = "Allora... ti andrebbe di stringerci la mano?"
  },
  AvgDialog_139662_Content_58 = {
    Text = "Eh? Perché?"
  },
  AvgDialog_139662_Content_59 = {
    Text = "Hmm... sento semplicemente che dovrei."
  },
  AvgDialog_139662_Content_6 = {
    Text = "Svegliati. Svegliati adesso..."
  },
  AvgDialog_139662_Content_60 = {
    Text = "Quanto al perché... non riesco a ricordarlo bene."
  },
  AvgDialog_139662_Content_61 = {Text = "Inoltre..."},
  AvgDialog_139662_Content_62 = {
    Text = "La ragazza inclina la testa, un sorriso malizioso le sfiora le labbra."
  },
  AvgDialog_139662_Content_63 = {
    Text = "Anche tu vuoi toccarmi, vero?"
  },
  AvgDialog_139662_Content_64 = {
    Text = "È così. Certo che vuoi."
  },
  AvgDialog_139662_Content_65 = {
    Text = "Dopo tutto—l'oscurità, il fetore, il repellente assalto sensoriale—come potresti non voler toccare la prima persona viva che hai trovato?"
  },
  AvgDialog_139662_Content_66 = {
    Text = "Allunghi la mano, toccando le sue dita sottili e morbide."
  },
  AvgDialog_139662_Content_67 = {
    Text = "Che sensazione strana..."
  },
  AvgDialog_139662_Content_68 = {
    Text = "Sì. Lo senti anche tu. Insieme al calore umano, c'è una debole sensazione, come una corrente elettrica fioca che vi collega."
  },
  AvgDialog_139662_Content_69 = {
    Text = "È la risonanza dei Nuclei d'Argento."
  },
  AvgDialog_139662_Content_7 = {
    Text = "Benvenuto all'Università di Mythag, %player%."
  },
  AvgDialog_139662_Content_8 = {
    Text = "O meglio, bentornato nel mondo al di là del velo."
  },
  AvgDialog_139662_Content_9 = {
    Text = "(Sono... tornato?)"
  },
  AvgDialog_139663_Content_1 = {
    Text = "Quelle cose sono..."
  },
  AvgDialog_139663_Content_10 = {
    Text = "Se è una persona comune... probabilmente non riuscirà a parlarmi."
  },
  AvgDialog_139663_Content_11 = {
    Text = "Dato che sei un Risvegliatore, potrei riuscire a stabilire un collegamento con te. Attraverso la risonanza onirica, potresti vedere che aspetto ha Ramona."
  },
  AvgDialog_139663_Content_12 = {
    Text = "Forse lei può essere la pista per recuperare i tuoi ricordi."
  },
  AvgDialog_139663_Content_13 = {
    Text = "Prendi di nuovo la mano di Saya. Ti concentri interiormente, tracciando la forma di Ramona nella tua mente—la sua voce, il suo volto—sperando che il tenue collegamento tra voi possa trasmetterla."
  },
  AvgDialog_139663_Content_14 = {
    Text = "<Italic:Snap>. Il collegamento si spezza."
  },
  AvgDialog_139663_Content_15 = {
    Text = "Sembra che una sorta di muro informe stia bloccando il nostro collegamento..."
  },
  AvgDialog_139663_Content_16 = {
    Text = "È come se un muro informe stesse bloccando il nostro legame..."
  },
  AvgDialog_139663_Content_17 = {
    Text = "Forse è legato a ciò che devo fare. Ho la sensazione... che sia qualcosa di proibito. Qualcosa che non posso dire a tutti."
  },
  AvgDialog_139663_Content_18 = {
    Text = "Sembra che stia arrivando un temporale. Riposiamoci dentro per un po'."
  },
  AvgDialog_139663_Content_19 = {
    Text = "Dalle crepe nelle assi di legno, una melma nera fluttua occasionalmente verso l'alto, sfidando la gravità."
  },
  AvgDialog_139663_Content_2 = {
    Text = "Non lo so nemmeno io. Ma ho la sensazione... che la risposta sia da qualche parte nei miei ricordi."
  },
  AvgDialog_139663_Content_20 = {
    Text = "Saya si rannicchia in un angolo, la metà inferiore del viso nascosta contro le braccia. Chiede a bassa voce—"
  },
  AvgDialog_139663_Content_21 = {
    Text = "Questa è quella che hai chiamato \"Dissoluzione,\" vero?"
  },
  AvgDialog_139663_Content_22 = {Text = "Annuisci."},
  AvgDialog_139663_Content_23 = {
    Text = "È questo che mi ha portato via i ricordi?"
  },
  AvgDialog_139663_Content_24 = {
    Text = "Sì. E non solo a te, innumerevoli persone hanno perso ricordi importanti a causa della Dissoluzione."
  },
  AvgDialog_139663_Content_25 = {
    Text = "Alcuni hanno dimenticato i volti dei loro cari. Hanno passato anni a cercarli—e a volte, in quella ricerca, hanno finito per ferire proprio coloro che rimpiangevano."
  },
  AvgDialog_139663_Content_26 = {
    Text = "Alcuni hanno dimenticato le città in cui erano nati. Hanno vagato soli attraverso l'oceano, inseguendo un passato a cui non potranno mai tornare."
  },
  AvgDialog_139663_Content_27 = {
    Text = "...Perdere ricordi preziosi dev'essere molto doloroso."
  },
  AvgDialog_139663_Content_28 = {
    Text = "Saya guarda la pioggia che cade in linee sottili e costanti—come se l'acqua potesse lavare via la nera lordura."
  },
  AvgDialog_139663_Content_29 = {
    Text = "Mi chiedo... quali sono le cose importanti nascoste nei miei ricordi?"
  },
  AvgDialog_139663_Content_3 = {
    Text = "Troverò un modo per tirarti fuori da questo Dominio. Recupereremo i tuoi ricordi."
  },
  AvgDialog_139663_Content_30 = {
    Text = "Mi chiedo... quali sono le cose importanti nascoste nei miei ricordi?"
  },
  AvgDialog_139663_Content_31 = {
    Text = "Rimani in silenzio."
  },
  AvgDialog_139663_Content_32 = {
    Text = "Fuori, la pioggia continua a cadere, costante e leggera."
  },
  AvgDialog_139663_Content_4 = {Text = "Ma…"},
  AvgDialog_139663_Content_5 = {
    Text = "Vuoi trovare prima Ramona, giusto?"
  },
  AvgDialog_139663_Content_6 = {
    Text = "A dire il vero... credo di ricordare di aver incontrato qualcuno una volta, e poi..."
  },
  AvgDialog_139663_Content_7 = {
    Text = "Ad essere onesta... credo di ricordare di aver incontrato qualcuno una volta, e poi..."
  },
  AvgDialog_139663_Content_8 = {
    Text = "Comunque. Questa Ramona—è... diversa, come lo sei tu?"
  },
  AvgDialog_139663_Content_9 = {
    Text = "Se è una persona ordinaria... probabilmente non sarà in grado di parlare con me."
  },
  AvgDialog_141373_Content_1 = {
    Text = "Non è la prima volta che vieni a Ebwynnos, ma non c'è mai stata una volta in cui queste creature senza volto fossero così Irrequiete come oggi."
  },
  AvgDialog_141373_Content_10 = {
    Text = "Aspetta, Tu sei… perché sei qui?"
  },
  AvgDialog_141373_Content_11 = {
    Text = "Un rumore bianco acuto inghiottì la coscienza, una marea antica e invisibile ti costrinse a sollevare pesantemente la testa, guardando verso l'unica cosa che riuscivi a distinguere."
  },
  AvgDialog_141373_Content_12 = {
    Text = "Esatto, niente di tutto ciò è importante: chi sei, cosa vuoi fare, Il Motivo per cui sei venuto qui."
  },
  AvgDialog_141373_Content_13 = {
    Text = "Una voce bassa disperde il suono del mare, e l'anziano restringe dall'alto La Caccia."
  },
  AvgDialog_141373_Content_14 = {
    Text = "Sei al sicuro, bentornato."
  },
  AvgDialog_141373_Content_15 = {
    Text = "Oh… già, Ebwynnos, sono tornato a Ebwynnos."
  },
  AvgDialog_141373_Content_16 = {
    Text = "Borbotti ripetendo quelle parole, e senza accorgertene gli angoli della bocca si sollevano; tutto ciò che segue sembra del tutto naturale."
  },
  AvgDialog_141373_Content_17 = {
    Text = "Beh, ammetto che questo è un po' irregolare, ma non preoccuparti, ti riporterò a Mythag."
  },
  AvgDialog_141373_Content_18 = {
    Text = "L'abisso ti ha già avvolto completamente, e la tua Fragile intelligenza, scossa da continui sconvolgimenti, non riesce affatto a comprendere ciò che l'altro sta esponendo."
  },
  AvgDialog_141373_Content_19 = {Text = "Cosa?"},
  AvgDialog_141373_Content_2 = {
    Text = "Ehi, Ehi! Fermati, non sono un nemi..."
  },
  AvgDialog_141373_Content_20 = {
    Text = "Una risata rauca e breve."
  },
  AvgDialog_141373_Content_21 = {
    Text = "Appena non adesso."
  },
  AvgDialog_141373_Content_22 = {
    Text = "Umidità, Confusione, affollamento: ti riempiono fino all'orlo, poi ti trascinano in onde continue a restare Trincerato, e tu perdi ogni controllo."
  },
  AvgDialog_141373_Content_23 = {
    Text = "All'orecchio rimangono Solo sussurri mescolati ad ansimi."
  },
  AvgDialog_141373_Content_24 = {
    Text = "Ora appartieni a questo luogo, appartieni a me, appartieni a Ebwynnos."
  },
  AvgDialog_141373_Content_25 = {
    Text = "Non capisci nulla, Tu ti abbandoni semplicemente alla gioia, assecondando quell'antico mare."
  },
  AvgDialog_141373_Content_26 = {
    Text = "Egli non mostra alcun segno di volersi fermare."
  },
  AvgDialog_141373_Content_3 = {
    Text = "*Fischio da caccia"
  },
  AvgDialog_141373_Content_4 = {
    Text = "L'Attacco si fermò, tuttavia, l'Oscurità ti travolse all'improvviso. Quasi in un istante, un silenzio pesante ti precipitò in una sorta di abisso indescrivibile."
  },
  AvgDialog_141373_Content_5 = {Text = "Hm?"},
  AvgDialog_141373_Content_6 = {Text = "Ah..."},
  AvgDialog_141373_Content_7 = {
    Text = "Come Se volesse confermare qualcosa, ignorando i brividi che ti erano esplosi addosso per la reazione istantanea, il signore di questo luogo ti sfiorò con gesto imperioso il sopracciglio, la coda dell'Occhio, fino al lato del collo."
  },
  AvgDialog_141373_Content_8 = {
    Text = "Visitare Ebwynnos in un momento come questo non è una buona idea, %player%."
  },
  AvgDialog_141373_Content_9 = {
    Text = "<Small:Appena……>"
  },
  AvgDialog_142850_Content_1 = {
    Text = "Prima sezione"
  },
  AvgDialog_142850_Content_10 = {
    Text = "Varro… tu, lascia perdere! Siamo in tanti, non puoi uscire vivo da questa Foresta!"
  },
  AvgDialog_142850_Content_100 = {
    Text = "Era una velocità e un potere a cui non poteva resistere. Varo alzò gli occhi confusi, guardando Lotan con incomprensione."
  },
  AvgDialog_142850_Content_101 = {
    Text = "Tu… avevi promesso…"
  },
  AvgDialog_142850_Content_102 = {
    Text = "Avevo promesso di farti unire alla mia squadra. Ma non ho detto che saresti rimasto in vita."
  },
  AvgDialog_142850_Content_103 = {
    Text = "La Debolezza non è colpa tua. Ma il tuo cuore non è puro, guerriero."
  },
  AvgDialog_142850_Content_104 = {
    Text = "Lotan prende i due Sigilli d'Osso dalla mano di Varro e getta il suo cadavere — il volto ancora congelato in un'espressione di confusione — sul mucchio dei dodici cavalieri morti, come spazzatura da buttare via."
  },
  AvgDialog_142850_Content_105 = {
    Text = "Lancia uno sguardo verso i cespugli, alzando la sua spada a due mani, pronta a distruggere il Sigillo in eccesso..."
  },
  AvgDialog_142850_Content_106 = {
    Text = "Aspetta!! —"
  },
  AvgDialog_142850_Content_107 = {
    Text = "La lama di Lotan si ferma a mezz'aria. Con fredda indifferenza, ti osserva strisciare fuori dai cespugli."
  },
  AvgDialog_142850_Content_108 = {
    Text = "Non mi interessano i rivali troppo deboli."
  },
  AvgDialog_142850_Content_109 = {
    Text = "Piccolo scudiero del corpo dei cavalieri, se fossi in te, fuggerei prima che l'altro cambi idea, più in fretta possibile."
  },
  AvgDialog_142850_Content_11 = {
    Text = "Consegnaci il tuo sigillo osseo, ti garantiamo, ti garantiamo che potrai andartene sano e salvo!"
  },
  AvgDialog_142850_Content_110 = {
    Text = "Il signore Elian ha ordinato al corpo dei cavalieri di riportargli la corona, se… se scopre che sono fuggito, tutta la mia famiglia non sopravviverà…"
  },
  AvgDialog_142850_Content_111 = {
    Text = "Raccogliesti tutto il tuo coraggio e facesti un passo nella direzione di Lotan."
  },
  AvgDialog_142850_Content_112 = {
    Text = "Ha ancora un'impronta ossea… La prego, mi lasci andare anche io all'Arena della Balena Celeste, va bene? Devo solo arrivare lì e il mio compito sarà compiuto… Lei è così forte, non rappresenterò alcuna minaccia per lei…"
  },
  AvgDialog_142850_Content_113 = {Text = "Voi?"},
  AvgDialog_142850_Content_114 = {
    Text = "Lotan alzò un sopracciglio, guardandoti con scherno."
  },
  AvgDialog_142850_Content_115 = {
    Text = "Il tuo potere è persino inferiore a quei rifiuti uccisi da Varo. Nel primo secondo in cui entri in quell'Arena, morirai come un verme."
  },
  AvgDialog_142850_Content_116 = {
    Text = "Vattene ora, hai ancora la possibilità di sopravvivere."
  },
  AvgDialog_142850_Content_117 = {
    Text = "Guardasti i cadaveri sparsi ovunque, guardasti quella figura che ti riempiva di paura nel profondo del cuore, e inghiottisti a fatica la saliva."
  },
  AvgDialog_142850_Content_118 = {
    Text = "Sai che la vittoria non è mai stata tua da conquistare. Ogni istinto ti urla di fuggire da questo mostro, di correre il più lontano possibile."
  },
  AvgDialog_142850_Content_119 = {
    Text = "Vuoi dimenticare tua madre, sacrificata viva al Ceto Astrale. Vuoi dimenticare i tuoi fratelli, rinchiusi come bestiame nelle stalle. Vuoi semplicemente sopravvivere."
  },
  AvgDialog_142850_Content_12 = {
    Text = "Ha ragione, Varro! Anche se sei il mercenario più forte dei sei regni, circondato dai nostri tredici uomini, non hai alcuna possibilità di cavartela."
  },
  AvgDialog_142850_Content_120 = {
    Text = "Ma non c'era modo, non riuscivi a dimenticare. Proprio come partecipare a questa competizione destinata a fare da carne da cannone, non hai mai avuto il diritto di scegliere."
  },
  AvgDialog_142850_Content_121 = {
    Text = "Sono la guida del gruppo, conosco il Sentiero per l'Arena. Ho fatto lo Scudiero per moltissimi anni, so come servire un guerriero! Sono molto utile, avrete bisogno di me…"
  },
  AvgDialog_142850_Content_122 = {
    Text = "Fai un respiro profondo, raccogli il Sigillo e usi uno straccio per pulire lo sporco dall'armatura di Lotan, proprio come facevi un tempo per i cavalieri."
  },
  AvgDialog_142850_Content_123 = {
    Text = "Prego, da questa parte, Questo… Questo… eh?"
  },
  AvgDialog_142850_Content_124 = {
    Text = "Ti inchini davanti a lei; il suo respiro calmo ti opprime al punto che non osi alzare la testa, puoi solo fissare il suolo ai suoi piedi. Senti che Lo Sguardo di lei, affilato come una Lama, si sofferma su di te per alcuni secondi."
  },
  AvgDialog_142850_Content_125 = {
    Text = "Se incontri un pericolo, non sperare che io ti aiuti."
  },
  AvgDialog_142850_Content_126 = {
    Text = "Senza suffissi. Puoi chiamarmi Lotan."
  },
  AvgDialog_142850_Content_127 = {
    Text = "Lotan ripone la grande spada e si avvia nella direzione che hai indicato."
  },
  AvgDialog_142850_Content_128 = {
    Text = "Il Sangue aveva già completamente permeato il suolo. Nelle profondità della volta celeste rosso scuro, un'ombra enorme e lentamente in movimento appariva e scompariva."
  },
  AvgDialog_142850_Content_129 = {
    Text = "Hai un brivido e ti affretti a seguire i passi di Lotan."
  },
  AvgDialog_142850_Content_13 = {
    Text = "Possiamo collaborare, no?"
  },
  AvgDialog_142850_Content_130 = {
    Text = "Sì… Signora Lotan!"
  },
  AvgDialog_142850_Content_14 = {
    Text = "Collaborare?"
  },
  AvgDialog_142850_Content_15 = {
    Text = "La Balena del Cielo Stellato sceglierà un solo Proxy, e questo non è qualcosa che si può fare da soli!"
  },
  AvgDialog_142850_Content_16 = {
    Text = "Basta deporre il sigillo osseo, ti garantiamo che uscirai da qui sano e salvo, e otterrai tutto ciò che puoi ottenere…"
  },
  AvgDialog_142850_Content_17 = {Text = "Davvero?"},
  AvgDialog_142850_Content_18 = {
    Text = "Lo so, Varro, sei sopravvissuto al branco di bestie sull'isola deserta, hai ucciso davanti allo Sguardo dello Specchio la persona che amavi di più, forse i tuoi genitori, un figlio, o qualcos'altro."
  },
  AvgDialog_142850_Content_19 = {
    Text = "Hai vissuto per mezzo mese in questa Foresta primitiva. Di certo non vuoi tornartene indietro così…"
  },
  AvgDialog_142850_Content_2 = {
    Text = "Le foglie cadevano dai rami, scivolando attraverso il cielo rosso scuro, per poi posarsi nelle pozze di Sangue sul terreno, suscitando un fievole increspamento."
  },
  AvgDialog_142850_Content_20 = {
    Text = "Ma pensa, pensa a cosa ti aspetta davanti!"
  },
  AvgDialog_142850_Content_21 = {
    Text = "Devi sfondare il nostro accerchiamento, schivare i pericoli lungo il Sentiero, trovare l'Arena della Balena del Cielo Stellato, e lì combattere una Lotta Mortale contro le persone più pericolose del mondo."
  },
  AvgDialog_142850_Content_22 = {
    Text = "Anche se quel sigillo osseo ti porta all'Arena, puoi essere sicuro di essere l'ultimo a sopravvivere?"
  },
  AvgDialog_142850_Content_23 = {
    Text = "Purché tu rinunci, quando il signore Elian salirà al potere, potrai diventare uno dei fondatori del regno… pensaci bene, Varro!"
  },
  AvgDialog_142850_Content_24 = {
    Text = "La tua proposta è allettante. Peccato però che solo i deboli abbiano bisogno di fare gruppo. Non capisci affatto cosa significa essere forti."
  },
  AvgDialog_142850_Content_25 = {
    Text = "Basta chiacchiere, venite tutti insieme, feccia del Cavaliere."
  },
  AvgDialog_142850_Content_26 = {Text = "Tu..."},
  AvgDialog_142850_Content_27 = {
    Text = "Varro! Pagherai per la tua mancanza di rispetto!"
  },
  AvgDialog_142850_Content_28 = {
    Text = "Cavalieri! All'attacco!!!"
  },
  AvgDialog_142850_Content_29 = {
    Text = "Una massa di rifiuti…"
  },
  AvgDialog_142850_Content_3 = {
    Text = "L'antica Foresta era permeata da un persistente odore dolciastro di Sangue; i corpi che avevano nutrito la terra con il loro Sangue giacevano sul muschio cremisi, gli occhi spalancati in un'espressione di risentimento, ormai privi di vita."
  },
  AvgDialog_142850_Content_30 = {
    Text = "Un'ondata di armature si riversò come un mare in tempesta verso la figura solitaria al centro. La carica di oltre dieci uomini frantumò muschio e ossa, e la Terra sotto i loro piedi tremò."
  },
  AvgDialog_142850_Content_31 = {
    Text = "Il violento fragore di metallo esplose nella foresta fitta, spaventando uno stormo di uccelli neri che si alzò in volo come un frammento oscuro strappato dalla chioma degli alberi."
  },
  AvgDialog_142850_Content_32 = {
    Text = "I rami e le foglie del nascondiglio fremettero. Tu ti rannicchiasti dietro i cespugli, trattenendo il respiro mentre osservavi quel massacro attraverso le fessure tra i rampicanti."
  },
  AvgDialog_142850_Content_33 = {Text = "..."},
  AvgDialog_142850_Content_34 = {
    Text = "La scimitarra spezzò spade e lame, trapassò la Caro Fragile sotto le armature, recidendo arti e teste tra le giunture delle piastre. Ogni colpo era preciso, brutale, senza un solo movimento superfluo."
  },
  AvgDialog_142850_Content_35 = {
    Text = "Potere, velocità, tecnica… di fronte a questo guerriero, l'Élite dei Cavalieri cadde uno dopo l'altro come agnelli al macello."
  },
  AvgDialog_142850_Content_36 = {Text = "..."},
  AvgDialog_142850_Content_37 = {
    Text = "Questo… quest'uomo…"
  },
  AvgDialog_142850_Content_38 = {
    Text = "La carica e le grida di battaglia si placarono rapidamente. Varro strappò un panno pulito dal corpo di un Cavaliere caduto e asciugò il Sangue dalla scimitarra."
  },
  AvgDialog_142850_Content_39 = {
    Text = "Esaminò la lama immacolata e annuì soddisfatto. Poi frugò nel cadavere del Cavaliere a capo del gruppo e trovò il sigillo d'osso che dava accesso all'Arena."
  },
  AvgDialog_142850_Content_4 = {
    Text = "Espira… calma… nessuno dovrebbe avermi Scoperto…"
  },
  AvgDialog_142850_Content_40 = {
    Text = "Uno, due, tre… undici, dodici."
  },
  AvgDialog_142850_Content_41 = {
    Text = "Dodici, dodici…"
  },
  AvgDialog_142850_Content_42 = {
    Text = "Si guardò intorno, senza trovare il tredicesimo cadavere."
  },
  AvgDialog_142850_Content_43 = {
    Text = "Brutto affare! Mi ha Scoperto… devo andarmene subito…"
  },
  AvgDialog_142850_Content_44 = {Text = "*Snap*—"},
  AvgDialog_142850_Content_45 = {
    Text = "Un tronco secco apparve nel momento peggiore sul tuo Sentiero di ritirata. Varro si girò di scatto, puntando lo sguardo verso il cespuglio dove Tu eri nascosto."
  },
  AvgDialog_142850_Content_46 = {Text = "!!!"},
  AvgDialog_142850_Content_47 = {
    Text = "Mi chiedevo perché mi sembrava di averne mancato uno, ed eccolo qui nascosto."
  },
  AvgDialog_142850_Content_48 = {
    Text = "Vieni fuori, amico, ti darò una morte rapida."
  },
  AvgDialog_142850_Content_49 = {
    Text = "Varro ammirava il riflesso del proprio volto sulla scimitarra, avanzando verso Tu con calma e senza fretta."
  },
  AvgDialog_142850_Content_5 = {
    Text = "Un Sogno intenso. Ti nascondevi tra i cespugli, cercando di placare il tuo respiro affannoso, spiando all'esterno attraverso le fessure tra gli alberi."
  },
  AvgDialog_142850_Content_50 = {
    Text = "Tu ti guardasti intorno, cercando ansiosamente una via di fuga adatta."
  },
  AvgDialog_142850_Content_51 = {
    Text = "Impossibile… è tutta foresta fitta… con questo corpo da bambino, non riuscirei mai a superarlo in velocità…"
  },
  AvgDialog_142850_Content_52 = {
    Text = "Cosa faccio…"
  },
  AvgDialog_142850_Content_53 = {
    Text = "Tu chiudesti gli occhi, sforzandoti di reprimere la Paura che ribolliva nel petto, la mente completamente vuota…"
  },
  AvgDialog_142850_Content_54 = {
    Text = "<Red:Fru. Fru. Fru.>"
  },
  AvgDialog_142850_Content_55 = {Text = "Hm?"},
  AvgDialog_142850_Content_56 = {
    Text = "Passi che calpestano foglie cadute e licheni, provenienti da un'altra direzione."
  },
  AvgDialog_142850_Content_57 = {
    Text = "Calmi, stabili, come una passeggiata nel pomeriggio."
  },
  AvgDialog_142850_Content_58 = {
    Text = "Un aiutante del Cavaliere... non scegliere la Fuga richiede coraggio, ma è anche stupido."
  },
  AvgDialog_142850_Content_59 = {
    Text = "Quando i Passi si fermarono, il Vento e il canto degli uccelli svanirono del tutto, persino il Sangue che colava dai cadaveri alle tue spalle sembrò smettere di scorrere, e l'intera Foresta sprofondò in un silenzio di morte inquietante."
  },
  AvgDialog_142850_Content_6 = {
    Text = "Una scimitarra fu estratta di netto dal suo petto, emettendo uno stridio che faceva accapponare la pelle. Il guerriero si spolverò la polvere dall'armatura e alzò lo sguardo verso i Dintorni."
  },
  AvgDialog_142850_Content_60 = {
    Text = "Una donna entra nel campo visivo. Un'armatura leggera nera ornamentale le copre il corpo, e tra le mani regge con nonchalance due rozze spade a due mani, del tutto sproporzionate alla sua corporatura."
  },
  AvgDialog_142850_Content_61 = {
    Text = "I suoi Occhi scansionarono i cadaveri sparsi ovunque, Lo Sguardo passò fugacemente sulle loro Ferite."
  },
  AvgDialog_142850_Content_62 = {
    Text = "Ognuno è morto con meno di cinque colpi, mirati deliberatamente alle giunture dell'armatura, con angolazione e forza precise... questi uomini, li hai uccisi Tu?"
  },
  AvgDialog_142850_Content_63 = {
    Text = "Eheheh... Esatto. Peccato, non mi ero ancora divertita abbastanza, eppure sono già caduti."
  },
  AvgDialog_142850_Content_64 = {
    Text = "Dodici persone, e Tu non hai riportato Ferite. Non male."
  },
  AvgDialog_142850_Content_65 = {
    Text = "La donna dall'armatura nera annuì con soddisfazione, e i suoi passi stabili continuarono ad avvicinarsi a lui."
  },
  AvgDialog_142850_Content_66 = {
    Text = "Varro era in La Veglia. Cercava la Paura negli Occhi di quella Donna, ma vi scorgeva solo una calma irritante."
  },
  AvgDialog_142850_Content_67 = {
    Text = "Chiunque Tu sia, posso darti tre minuti per la Fuga. Dopo tre minuti, se sopravviverai dipenderà da..."
  },
  AvgDialog_142850_Content_68 = {
    Text = "Dico, sei sordo? Non riesci a sentire quello che dico?"
  },
  AvgDialog_142850_Content_69 = {
    Text = "La donna dall'armatura nera non rispose, i suoi passi rimasti placidi come durante una passeggiata. La Rabbia infiammò Varro all'istante, la sua mano si strinse sull'impugnatura e sguainò quella lama ricurva affilata."
  },
  AvgDialog_142850_Content_7 = {
    Text = "Il prossimo, a chi tocca?"
  },
  AvgDialog_142850_Content_70 = {
    Text = "Volevo risparmiarti la vita, ma se vuoi così tanto morire, allora non sarò cle..."
  },
  AvgDialog_142850_Content_71 = {Text = "Clang—"},
  AvgDialog_142850_Content_72 = {
    Text = "Il suono di metallo più cristallino che Varro avesse mai sentito in vita sua risuonò brevemente accanto al suo orecchio e svanì."
  },
  AvgDialog_142850_Content_73 = {
    Text = "La donna che avrebbe dovuto trovarsi di fronte a Varro era apparsa chissà quando alle sue spalle. Impugnava una delle enormi spade con una sola mano, la lama posata con noncuranza sul lato del suo collo."
  },
  AvgDialog_142850_Content_74 = {
    Text = "Varro abbassò lo sguardo. Quella lama ricurva, forgiata dai fabbri più abili di sei nazioni e che aveva ucciso innumerevoli nemici, era stata recisa di netto alla radice, sospesa a pochi centimetri dal fodero."
  },
  AvgDialog_142850_Content_75 = {
    Text = "La splendida lama di cui andava tanto fiero era conficcata a testa in giù nel terreno intriso di sangue, rotando su se stessa come una fredda lapide."
  },
  AvgDialog_142850_Content_76 = {
    Text = "Questo… tu…"
  },
  AvgDialog_142850_Content_77 = {
    Text = "Qualcuno capace di annientare un intero ordine di Cavalieri… pensavo potesse almeno suscitare il mio interesse."
  },
  AvgDialog_142850_Content_78 = {
    Text = "La donna in armatura nera parlava con una delusione tutt'altro che celata."
  },
  AvgDialog_142850_Content_79 = {
    Text = "Il sigillo osseo, ce l'hai?"
  },
  AvgDialog_142850_Content_8 = {
    Text = "Leccò il Sangue sulla scimitarra, si guardò intorno osservando le decine di persone che lo circondavano, e chiese con curiosità."
  },
  AvgDialog_142850_Content_80 = {
    Text = "<Shake:Sì! Sì sì sì!>"
  },
  AvgDialog_142850_Content_81 = {
    Text = "Varo aveva visto molte persone e molte situazioni, sapeva quando era il momento di agire. Le sue gambe cedettero e si inginocchiò davanti a lei."
  },
  AvgDialog_142850_Content_82 = {
    Text = "Signora, signora, la prego di ascoltarmi… La Balena Celeste sceglie un solo Proxy, ed è qualcosa che non si può fare da soli!"
  },
  AvgDialog_142850_Content_83 = {
    Text = "La Corona! Quella Corona che tutti sognano... La vuoi anche tu, vero?!"
  },
  AvgDialog_142850_Content_84 = {
    Text = "Lei possiede un Potere così straordinario — se formassimo una squadra insieme, potremmo sicuramente ottenere la vittoria finale!"
  },
  AvgDialog_142850_Content_85 = {
    Text = "Sarò il suo servitore più fedele, le giuro eterna lealtà e l'aiuterò a ottenere il Potere della Balena Celeste! …"
  },
  AvgDialog_142850_Content_86 = {
    Text = "Signora… la prego di prenderlo in considerazione…"
  },
  AvgDialog_142850_Content_87 = {
    Text = "Proposta interessante. Accetto."
  },
  AvgDialog_142850_Content_88 = {
    Text = "Tu... tu..."
  },
  AvgDialog_142850_Content_89 = {
    Text = "Varo aveva già preparato un lungo discorso, e si ritrovò a non averne alcun bisogno."
  },
  AvgDialog_142850_Content_9 = {
    Text = "Quando alzò la scimitarra, Tutti fecero un passo indietro all'unisono."
  },
  AvgDialog_142850_Content_90 = {
    Text = "Stai tranquillo. Non vengo mai meno alla mia parola."
  },
  AvgDialog_142850_Content_91 = {
    Text = "<Shake:Ot-, ottimo!>"
  },
  AvgDialog_142850_Content_92 = {
    Text = "Come un uomo strappato dall'orlo dell'abisso, Varro fruga tra i suoi averi, presentando infine i Sigilli d'Osso a Lotan con mani tremanti a coppa."
  },
  AvgDialog_142850_Content_93 = {
    Text = "Eccolo! Proprio questo!"
  },
  AvgDialog_142850_Content_94 = {
    Text = "Quei cavalieri hanno sequestrato due Sigilli. Con questi, possiamo entrare nell'arena insieme!"
  },
  AvgDialog_142850_Content_95 = {
    Text = "A quel punto, nessuno potrà sconfiggerci…"
  },
  AvgDialog_142850_Content_96 = {Text = "Swish—"},
  AvgDialog_142850_Content_97 = {Text = "ARGH!!"},
  AvgDialog_142850_Content_98 = {
    Text = "Il filo della grande spada scivolò facilmente attraverso l'armatura, e una ferita enorme che quasi perforava il corpo si estese dal fianco destro di Varo fino alla spalla sinistra."
  },
  AvgDialog_142850_Content_99 = {
    Text = "Il sangue caldo schizzò sui cespugli davanti a te, condensandosi sulle foglie in gocce rosso scuro."
  },
  AvgDialog_142851_Content_1 = {
    Text = "La quarta sezione"
  },
  AvgDialog_142851_Content_10 = {
    Text = "Al centro di quelle colonne spezzate, una crepa verso un altro spazio Squarciò la realtà, come una pupilla verticale che si apriva lentamente."
  },
  AvgDialog_142851_Content_100 = {
    Text = "Le pareti di carne sotto i piedi ebbero violenti Spasmi, e un intenso odore di ruggine invase le narici. Lo spazio stesso stava diventando Euforia."
  },
  AvgDialog_142851_Content_101 = {
    Text = "Bene… Bene!"
  },
  AvgDialog_142851_Content_102 = {
    Text = "Dodicimila anni, Lotan… ho atteso in questo vuoto, aspettando qualcuno che mi facesse sentire che l'esistenza non è una tortura."
  },
  AvgDialog_142851_Content_103 = {
    Text = "Re, santi, guerrieri, creature demoniache… si presentavano davanti a me, portando i loro desideri che credevano grandiosi, si inginocchiavano, imploravano."
  },
  AvgDialog_142851_Content_104 = {
    Text = "Poi venivano corrosi poco a poco dal Potere che avevo concesso loro, diventando un altro volto fluttuante nell'abisso."
  },
  AvgDialog_142851_Content_105 = {
    Text = "Credevo che questo fosse tutto ciò che l'eternità aveva da offrire."
  },
  AvgDialog_142851_Content_106 = {
    Text = "Finché non ti sei fermata qui, guardandomi con quegli Occhi che non bramano nulla, dicendomi che vuoi… ehehehe… che vuoi uccidermi?!!"
  },
  AvgDialog_142851_Content_107 = {
    Text = "Un rosso scuro puro, denso e pesante sgorgò dalla fenditura del cuore, inghiottendo tutte le vene di luce e i volti nell'abisso."
  },
  AvgDialog_142851_Content_108 = {
    Text = "In quel rosso scuro e corrotto, il profilo dell'enorme corpo della Balena Stellare si manifestò all'orizzonte."
  },
  AvgDialog_142851_Content_109 = {
    Text = "Un corpo più grande di questo mondo stesso piegò la forma del vuoto, il piano sotto i tuoi piedi cominciò a curvarsi come carta, e l'Oscurità in lontananza iniziò a collassare verso l'interno."
  },
  AvgDialog_142851_Content_11 = {
    Text = "Quindi non era necessario uccidere l'avversario per aprire il Portale… Hai avuto fortuna."
  },
  AvgDialog_142851_Content_110 = {
    Text = "Questo pianeta cresce sul suo corpo, e gli esseri umani dei sei regni esistono grazie a lei. È la divinità che Divora il Potere dei pianeti, il padrone indiscusso di questo astro. È lo spazio stesso."
  },
  AvgDialog_142851_Content_111 = {
    Text = "Il Fantasma svanì del tutto, e il Leviatano aprì di scatto i suoi maestosi occhi."
  },
  AvgDialog_142851_Content_112 = {
    Text = "Una forza devastante eruttò dal corpo della Balena Stellare. L'intera Dimensione spaziale cominciò a collassare, una forza invisibile ti scaraventò via, facendoti cadere pesantemente sul bordo del piano."
  },
  AvgDialog_142851_Content_113 = {
    Text = "Le tue dita si aggrapparono alla crepa, lottando disperatamente per non scivolare nell'abisso."
  },
  AvgDialog_142851_Content_114 = {
    Text = "Mi hai resa molto, molto felice, Lotan!"
  },
  AvgDialog_142851_Content_115 = {
    Text = "Dopo la tua morte, farò scolpire a tutti i servitori di questo mondo la statua più grandiosa in tuo onore!"
  },
  AvgDialog_142851_Content_116 = {
    Text = "Al centro di quell'Oscurità che inghiottiva ogni cosa, dinanzi a quell'immensa presenza innominabile, Lotan strinse tra le mani la grande spada e avanzò verso quei terribili occhi colossali."
  },
  AvgDialog_142851_Content_117 = {
    Text = "I suoi passi si fecero sempre più veloci, sempre più veloci, finché non si trasformarono in una tempesta inarrestabile. Sul suo volto brillava un sorriso di Fervore che non avevi mai visto prima."
  },
  AvgDialog_142851_Content_118 = {
    Text = "Vieni! Leviatano!!!"
  },
  AvgDialog_142851_Content_119 = {
    Text = "Un ruggito gioioso come le onde del mare risuonò, frantumando gli ultimi residui della tua coscienza. Le mani che stringevano la Pietra persero ogni Potere, e in quel vento ruggente, attraverso quella crepa tornasti nell'Arena."
  },
  AvgDialog_142851_Content_12 = {
    Text = "Lotan distolse Lo Sguardo, non aveva mai avuto il minimo interesse per te. Quella figura esile impugnò la grande spada e si avviò verso la crepa."
  },
  AvgDialog_142851_Content_120 = {
    Text = "Nell'ultimo barlume della tua vista, vedesti Lotan impugnare quelle due grandi spade e slanciarsi verso la divinità più maestosa delle stelle."
  },
  AvgDialog_142851_Content_121 = {
    Text = "La tempesta si frantumò in mille pezzi.\nLa tempesta non si voltò mai indietro."
  },
  AvgDialog_142851_Content_13 = {
    Text = "Solo quando la sua figura scomparve completamente nella crepa, ti rialzasti finalmente a sedere, ansimando a pieni polmoni."
  },
  AvgDialog_142851_Content_14 = {
    Text = "Uff… che spavento…"
  },
  AvgDialog_142851_Content_15 = {
    Text = "Là… è forse la dimora della Balena Celeste Stellare…"
  },
  AvgDialog_142851_Content_16 = {
    Text = "Volevi fuggire da lì, ma un'attrazione irresistibile si riversava da quella crepa, come un filo invisibile legato alle tue ossa, che ti tirava dolcemente e senza sosta."
  },
  AvgDialog_142851_Content_17 = {
    Text = "I tuoi piedi si mossero involontariamente verso la crepa. La crepa fremeva leggermente, come un Occhio gentile che ti osservava."
  },
  AvgDialog_142851_Content_18 = {
    Text = "Solo uno sguardo, appena uno sguardo. Per vedere che aspetto avesse davvero il grande signore che Divora le stelle… Ti avvicinasti furtivamente alla crepa, seguendola all'interno…"
  },
  AvgDialog_142851_Content_19 = {Text = "..."},
  AvgDialog_142851_Content_2 = {
    Text = "Lo… Lotan, mia signora! ……"
  },
  AvgDialog_142851_Content_20 = {
    Text = "Nessuna luce, nessun suono, persino il battito del tuo cuore era inudibile. Non eri sicuro di possedere ancora un corpo, o se fossi già diventato qualche frammento di coscienza fluttuante nell'Illusione."
  },
  AvgDialog_142851_Content_21 = {
    Text = "Il tatto fece Ritorno al corpo, e sotto i tuoi piedi sentisti un morbido, caldo e ritmico fremito. Si contraeva dolcemente sotto le tue piante, come una lingua enorme che ti leccava."
  },
  AvgDialog_142851_Content_22 = {
    Text = "Questo è?!!..."
  },
  AvgDialog_142851_Content_23 = {
    Text = "Stelle oscure scorrevano nel cielo stellato, e una pulsazione dai colori in continuo mutamento illuminava lo spazio in cui ti trovavi."
  },
  AvgDialog_142851_Content_24 = {
    Text = "Masse di Caro si estendevano senza fine sotto i tuoi piedi, ondeggiando come una lingua gigantesca o uno stomaco."
  },
  AvgDialog_142851_Content_25 = {
    Text = "Inspirasti profondamente e incrociasti Lo Sguardo con quella pulsazione lontana che Batteva di Ciglia, simile a un bulbo oculare. In un solo secondo, una forte vertigine ti travolse, e un caldo Banchetto di Sangue sgorgò dalle tue narici. Ti affrettasti a distogliere Lo Sguardo."
  },
  AvgDialog_142851_Content_26 = {
    Text = "Negli ultimi bagliori della tua coscienza, vedi quella massa pulsante e mutevole condensarsi in una forma, un Fantasma dell'Illusione che appare davanti a Lotan. Nel momento in cui Egli apre la bocca, un vasto canto di balena risuona in questo spazio."
  },
  AvgDialog_142851_Content_27 = {
    Text = "Benvenuto, quattromillesimo sfidante giunto al mio cospetto! Benvenuto nella mia dimora."
  },
  AvgDialog_142851_Content_28 = {
    Text = "Proprio come immaginavo fossi tu."
  },
  AvgDialog_142851_Content_29 = {
    Text = "Una sfida così straordinaria... che piacere ci sarebbe a non poterla osservare di persona."
  },
  AvgDialog_142851_Content_3 = {
    Text = "Io… io non ho mai… mai pensato di contenderle la Corona…"
  },
  AvgDialog_142851_Content_30 = {
    Text = "Ho assistito a ogni tuo combattimento, bambino dalla grande spada."
  },
  AvgDialog_142851_Content_31 = {
    Text = "Gracchus, le Sorelle Vaughan, Sanchi, Elian, Alish... In questa grande arena, hai sconfitto tutti gli esseri più potenti di questo pianeta."
  },
  AvgDialog_142851_Content_32 = {
    Text = "La tua spada non compie movimenti superflui. La tua anima non porta pesi inutili. La tua vittoria è più che meritata, Lotan."
  },
  AvgDialog_142851_Content_33 = {
    Text = "Il Fantasma annuì con soddisfazione."
  },
  AvgDialog_142851_Content_34 = {
    Text = "Le creature che giungono fin qui lo fanno per non più di tre ragioni: conoscenza, potere, vita."
  },
  AvgDialog_142851_Content_35 = {
    Text = "Il re avido vuole un trono immortale, la Madre disperata vuole la Rinascita del figlio morto, il mago folle vuole spiare la conoscenza proibita… ciò che desiderano è tanto, tantissimo."
  },
  AvgDialog_142851_Content_36 = {
    Text = "E così infliggono Danno, uccidono, Sacrificano tutto. Si inginocchiano davanti a me e mi supplicano con le stesse parole che ascolto da migliaia e migliaia di anni."
  },
  AvgDialog_142851_Content_37 = {
    Text = "Ma ne vale sempre la pena… alla fine, ognuno ottiene ciò che ha tanto cercato."
  },
  AvgDialog_142851_Content_38 = {
    Text = "Allora, valoroso guerriero… cosa desideri tu?"
  },
  AvgDialog_142851_Content_39 = {Text = "Potere."},
  AvgDialog_142851_Content_4 = {
    Text = "Io… io appena…"
  },
  AvgDialog_142851_Content_40 = {
    Text = "Il Potere è Appena uno strumento, un gradino di una scala, e sopra quella scala c'è qualcosa che ti aspetta."
  },
  AvgDialog_142851_Content_41 = {
    Text = "Dimmi, cosa desideri davvero, nel profondo?"
  },
  AvgDialog_142851_Content_42 = {
    Text = "L'ho già detto… ciò che voglio è Solo Potere. Un Potere sempre più grande, senza mai fine."
  },
  AvgDialog_142851_Content_43 = {
    Text = "Tutto ciò che non è Potere non mi interessa."
  },
  AvgDialog_142851_Content_44 = {
    Text = "La Balena Celeste osservò Lotan con aria pensierosa, e una risata simile a un rombo di tuono risuonò in quello spazio."
  },
  AvgDialog_142851_Content_45 = {
    Text = "Ah ah ah ah..."
  },
  AvgDialog_142851_Content_46 = {
    Text = "Queste parole le ho sentite molte volte. Ogni persona che le ha pronunciate ha finito per perdersi nel Vuoto del desiderio generato dal Potere."
  },
  AvgDialog_142851_Content_47 = {
    Text = "Hanno ottenuto il mio Potere, ma non riescono a sopportarne il peso. Cresce nel midollo osseo, erode l'anima, il desiderio di uccidere e conquistare inghiotte la loro coscienza una dopo l'altra…"
  },
  AvgDialog_142851_Content_48 = {
    Text = "Storie come questa ne ho viste quattromila, e non mi stancano mai."
  },
  AvgDialog_142851_Content_49 = {
    Text = "Al suono di un canto di balena, un enorme cuore di balena apparve in quello spazio. Una colonna di Sangue sgorgò dal cuore, confluendo davanti a Lotan in fitte rune."
  },
  AvgDialog_142851_Content_5 = {
    Text = "Avevi già dimenticato la Ferita sulla spalla, senza il coraggio di fissare quegli Occhi calmi."
  },
  AvgDialog_142851_Content_50 = {
    Text = "Si disponevano in una figura incomprensibile: ogni volta che Lotan cercava di vederne la forma completa, essa si trasformava in qualcosa di completamente diverso."
  },
  AvgDialog_142851_Content_51 = {
    Text = "Bastava sfiorarle con la coda dell'occhio per sentire un flusso di Sangue ardente scorrere nel corpo, colpire ogni organo, spingerti a impugnare la spada e trafiggerle il cuore… Ti affrettasti a distogliere lo sguardo."
  },
  AvgDialog_142851_Content_52 = {
    Text = "Firmalo. E riceverai ciò che hai tanto desiderato — la mia forza."
  },
  AvgDialog_142851_Content_53 = {Text = "Il prezzo?"},
  AvgDialog_142851_Content_54 = {
    Text = "Nessun prezzo, solo una promessa."
  },
  AvgDialog_142851_Content_55 = {
    Text = "Il mio Potere sarà condiviso con te, il mio Destino sarà legato al tuo. Dal momento in cui firmerai Il Testamento, sarai il padrone di questo pianeta, il rappresentante della mia volontà."
  },
  AvgDialog_142851_Content_56 = {
    Text = "Avrai tutto ciò che appartiene alle sei nazioni, fino a — fino a quando, tre anni dopo, inizierà una nuova contesa e nascerà un nuovo re."
  },
  AvgDialog_142851_Content_57 = {
    Text = "Mi accompagnerai, osservando quelle anime interessanti — osservando te stesso — avanzare passo dopo passo verso l'abisso. Proprio come i re che ti hanno preceduto."
  },
  AvgDialog_142851_Content_58 = {
    Text = "Ma so che, anche conoscendo le conseguenze, non ti opporrai."
  },
  AvgDialog_142851_Content_59 = {
    Text = "Stai pensando di essere diverso dai quattromila sfidanti che ti hanno preceduto. Che possiedi una volontà capace di Superare qualsiasi cosa, che non cadrai mai nell'abisso del Potere e del desiderio…"
  },
  AvgDialog_142851_Content_6 = {
    Text = "Lotan non disse nulla, avanzando verso di te con la lama in mano, senza fretta. La tua fronte premeva contro il suolo, il corpo tremante davanti a quella figura che si avvicinava."
  },
  AvgDialog_142851_Content_60 = {
    Text = "Come si firma questo Testamento?"
  },
  AvgDialog_142851_Content_61 = {
    Text = "Il sorriso della Balena Celeste portava con sé un'antica stanchezza. Aveva già visto troppe volte la stessa storia. Questa volta non era diversa."
  },
  AvgDialog_142851_Content_62 = {
    Text = "…Avidità. Decisione. Non ti preoccupi delle formalità, ma almeno possiedi qualità che trovo piacevoli."
  },
  AvgDialog_142851_Content_63 = {
    Text = "Tendi la mano e posala su Il Testamento."
  },
  AvgDialog_142851_Content_64 = {
    Text = "Senza esitare, Lotan tese la mano e la posò su quella figura formata dal Sangue."
  },
  AvgDialog_142851_Content_65 = {
    Text = "Dei caratteri liquidi e viventi strisciarono fuori dalla pozza di Sangue. Risalirono lungo il braccio di Lotan, penetrando e infiltrandosi sotto la sua pelle."
  },
  AvgDialog_142851_Content_66 = {
    Text = "Nei luoghi attraversati da quei caratteri, la Caro di Lotan si decompose e andò in Rottura rapidamente, lasciando Solo ossa candide e Sangue cremisi."
  },
  AvgDialog_142851_Content_67 = {
    Text = "Il corpo di Lotan tremava per il dolore, ma non emise alcun suono dall'inizio alla fine. Aprì quegli occhi già per metà in frantumi, testimoniando tutto ciò con attenzione."
  },
  AvgDialog_142851_Content_68 = {
    Text = "I caratteri si diffusero lungo la rete di vasi sanguigni verso il cuore, raggiungendo infine i suoi occhi. In un istante, le pupille di Lotan si trasformarono nello stesso Vortice della Balena Stellare."
  },
  AvgDialog_142851_Content_69 = {
    Text = "Poi, il Vortice svanì, e il colore delle pupille della Balena Stellare rimase per sempre nei suoi occhi, mentre un'armatura simile a ossa candide avvolse il suo corpo rinato."
  },
  AvgDialog_142851_Content_7 = {
    Text = "Uno sfidante ha scelto la sottomissione, uno sfidante ha scelto la fuga, quindici sfidanti hanno scelto la morte… Sembra che il nostro ultimo vincitore sia già stato decretato."
  },
  AvgDialog_142851_Content_70 = {
    Text = "L'intero vuoto emise una profonda Risonanza, e i volti che fluttuavano nell'abisso, morti nell'Arena, aprirono la bocca all'unisono, lanciando urla silenziose."
  },
  AvgDialog_142851_Content_71 = {
    Text = "Accoglievano il loro Nuovo Re."
  },
  AvgDialog_142851_Content_72 = {
    Text = "Questo… è il Potere della Balena Stellare…"
  },
  AvgDialog_142851_Content_73 = {
    Text = "Lotan strinse il pugno, percependo il Potere dell'antico dio che scorreva impetuoso dentro di sé, sentendo il proprio Collegamento con questo mondo."
  },
  AvgDialog_142851_Content_74 = {
    Text = "I mondi Divorati dalla Balena Stellare pulsavano nella sua percezione, e tutte le Vite create e asservite dalla Balena Stellare erano come fiammelle tenue: bastava un solo pensiero per spegnerle tutte."
  },
  AvgDialog_142851_Content_75 = {
    Text = "Quel fiume di Sangue si raccolse in una corona Cremisi, che brillava splendente davanti a lei."
  },
  AvgDialog_142851_Content_76 = {
    Text = "Il Testamento è compiuto. Il tuo Destino e il mio si fondono in uno, irreversibilmente. Per quante ere sono esistito, altrettanto peso di ere tu erediterai."
  },
  AvgDialog_142851_Content_77 = {
    Text = "Goditi tutto, Lotan. Ho visto troppe anime simili a te. Pure, ardenti, indomabili."
  },
  AvgDialog_142851_Content_78 = {
    Text = "Lo attenderò… attenderò il giorno in cui cadrai nell'abisso. Io sprofonderò in un nuovo lungo sonno… ora puoi andare a fare tutto ciò che desideri."
  },
  AvgDialog_142851_Content_79 = {
    Text = "Il Fantasma della Balena Stellare pronunciò un noioso Addio e riaprì la fenditura."
  },
  AvgDialog_142851_Content_8 = {
    Text = "La voce affluiva da ogni direzione, portando con sé un piacere fastidioso. Innumerevoli Fantasmi sulle tribune si alzarono all'unisono, e sui loro volti in continua mutazione apparve un sorriso identico."
  },
  AvgDialog_142851_Content_80 = {
    Text = "Hai finito di parlare?"
  },
  AvgDialog_142851_Content_81 = {
    Text = "La dimora della Balena Stellare cadde in un breve silenzio. Essa non ricevette la recitazione e la sottomissione che si aspettava; ciò che trovò fu uno sguardo di guerriero, con gli occhi che Bruciavano di un desiderio insopprimibile."
  },
  AvgDialog_142851_Content_82 = {
    Text = "Allora ora… è il tuo turno di agire."
  },
  AvgDialog_142851_Content_83 = {
    Text = "Non avresti mai pensato di vedere la confusione negli occhi di un dio."
  },
  AvgDialog_142851_Content_84 = {
    Text = "Tu... cosa?"
  },
  AvgDialog_142851_Content_85 = {
    Text = "Hai detto che posso fare tutto ciò che voglio… c'è una sola cosa che voglio fare. Ucciderti, o essere uccisa da te."
  },
  AvgDialog_142851_Content_86 = {
    Text = "La mia abitudine è lasciare che il Rivale faccia la prima mossa. Quindi, è il tuo turno di agire, Leviatano."
  },
  AvgDialog_142851_Content_87 = {
    Text = "Hai appena firmato Il Testamento…"
  },
  AvgDialog_142851_Content_88 = {
    Text = "Ho promesso di diventare il Guardiano di questo pianeta, l'esecutore della tua volontà."
  },
  AvgDialog_142851_Content_89 = {
    Text = "Tu sei il padrone schiavista di questo pianeta. Combatterti in loro nome è anch'esso adempiere al mio dovere."
  },
  AvgDialog_142851_Content_9 = {
    Text = "Un suono sordo e cupo. Le colonne di pietra dell'Arena alle tue spalle crollarono, i frammenti volarono verso il cielo, scomparendo nelle profondità di quel cielo rosso scuro come una palude."
  },
  AvgDialog_142851_Content_90 = {
    Text = "Tu sei il divoratore di stelle, sinonimo di massacro e guerra. Combattere è la tua volontà."
  },
  AvgDialog_142851_Content_91 = {
    Text = "Uno scherzo niente male, Lotan. Vattene ora e potrai ancora ottenere tutto ciò che Tutti desiderano. Resta qui e non otterrai nulla."
  },
  AvgDialog_142851_Content_92 = {
    Text = "Ho già detto tutto quello che c'era da dire."
  },
  AvgDialog_142851_Content_93 = {
    Text = "Il Testamento ha legato il tuo Destino al mio. La mia morte è la tua morte."
  },
  AvgDialog_142851_Content_94 = {
    Text = "Non me ne importa."
  },
  AvgDialog_142851_Content_95 = {
    Text = "Il tuo Potere non arriva nemmeno alla metà del mio. Lo hai appena ottenuto, non capisci affatto la forza che vorresti dominare… non hai assolutamente la capacità di sfidarmi, Lotan."
  },
  AvgDialog_142851_Content_96 = {
    Text = "Voglio provarci."
  },
  AvgDialog_142851_Content_97 = {
    Text = "Ehehehe… Ahahahahaha!!!"
  },
  AvgDialog_142851_Content_98 = {
    Text = "La Balena Celeste rise fragorosamente. Non rideva con tale piacere da decine di migliaia di anni."
  },
  AvgDialog_142851_Content_99 = {
    Text = "Le risate eruppero dal profondo del vuoto, facendo vibrare ogni vena di luce, ogni scaglia, ogni volto che fluttuava nell'abisso."
  },
  AvgDialog_142852_Content_1 = {
    Text = "La terza sezione"
  },
  AvgDialog_142852_Content_10 = {
    Text = "Ti girasti, e proprio in quel momento vedesti due ombre che si lanciavano verso di Te a gran velocità—"
  },
  AvgDialog_142852_Content_100 = {
    Text = "Alish guardò con stupore la giovane Donna davanti a lui. Un bagliore rosso Sangue cupo illuminava la sua sagoma. Nell'ultimo momento della sua vita, vide la sua stessa fede."
  },
  AvgDialog_142852_Content_101 = {
    Text = "Ah… Ahahahahah! Magnifico!"
  },
  AvgDialog_142852_Content_102 = {
    Text = "Ho immaginato molte volte la mia morte… nessuna mi avrebbe soddisfatto più di quanto sia accaduto oggi."
  },
  AvgDialog_142852_Content_103 = {
    Text = "Grazie a Te, Signora Lotan."
  },
  AvgDialog_142852_Content_104 = {
    Text = "Il generale Alish aprì le braccia, bagnandosi nella luce solare color Sangue."
  },
  AvgDialog_142852_Content_106 = {
    Text = "Un lampo di lama netto e deciso si accese, e la testa del vecchio Alish rotolò accanto al cavallo da guerra morto e alle bandiere spezzate."
  },
  AvgDialog_142852_Content_107 = {
    Text = "Sul volto segnato dalla vita campeggiava un sorriso soddisfatto. Per la propria fine, il vecchio Alish non chiedeva nient'altro."
  },
  AvgDialog_142852_Content_108 = {
    Text = "Dopo avergli chiuso gli occhi, Lotan si voltò e vide il nobile vestito da primo ministro, e il bambino tremante sotto la sua lama."
  },
  AvgDialog_142852_Content_109 = {
    Text = "Lo… Lotan, mio signore…"
  },
  AvgDialog_142852_Content_11 = {Text = "!!!"},
  AvgDialog_142852_Content_110 = {
    Text = "Vira? Vira!"
  },
  AvgDialog_142852_Content_111 = {
    Text = "Seguendo la voce di Elian, Lotan si voltò a guardare la figura nascosta nell'Oscurità dietro di Lei."
  },
  AvgDialog_142852_Content_112 = {
    Text = "Dopo una breve lotta durata qualche secondo, il velenoso consigliere della residenza del Gran Visir ritirò la sua mano tremante e si voltò per correre fuori dall'Arena. Di fronte alla morte, la maggior parte delle persone sa bene cosa scegliere."
  },
  AvgDialog_142852_Content_113 = {
    Text = "A quanto pare, il tuo controllo sulle persone che ti circondano è davvero limitato."
  },
  AvgDialog_142852_Content_114 = {
    Text = "Signora Lotan, siamo alleati! Lo ricordi?"
  },
  AvgDialog_142852_Content_115 = {
    Text = "Lasciami vivere, lasciami andare dalla Balena Celeste… ti darò tutto ciò che vuoi!"
  },
  AvgDialog_142852_Content_116 = {
    Text = "E questo bambino... non vuoi che {Male=him,Female=her} muoia, vero? Lo capisco... Lo hai protetto {Male=him,Female=her} durante quella brutale battaglia..."
  },
  AvgDialog_142852_Content_117 = {
    Text = "I passi della morte continuavano ad avvicinarsi inesorabilmente ad Elian. La sua voce cominciò a tremare."
  },
  AvgDialog_142852_Content_118 = {
    Text = "AAAHHHH!!—"
  },
  AvgDialog_142852_Content_119 = {
    Text = "Il pugnale affilato affonda in profondità nella tua spalla. Il tuo grido straziante riecheggia per tutta l'arena."
  },
  AvgDialog_142852_Content_12 = {Text = "..."},
  AvgDialog_142852_Content_120 = {
    Text = "Lotan! Se ti avvicini ancora, quest'uomo morirà per colpa tua!"
  },
  AvgDialog_142852_Content_121 = {
    Text = "Tu non uccidi mai gli innocenti… non hai mai voluto che degli innocenti morissero per causa tua! Esatto, esatto!! Non mi sono sbagliato su di te!!"
  },
  AvgDialog_142852_Content_122 = {
    Text = "Il pugnale si torce dentro di te, accompagnato dalle tue urla incessanti."
  },
  AvgDialog_142852_Content_123 = {
    Text = "Lotan rimase impassibile, come se non sentisse nulla, e avanzò verso Elian impugnando la sua grande spada, con un passo tranquillo come una passeggiata pomeridiana."
  },
  AvgDialog_142852_Content_124 = {
    Text = "Apprezzo le persone pure. Pura volontà di uccidere, puro Potere, pura gloria, pura saggezza e astuzia."
  },
  AvgDialog_142852_Content_125 = {
    Text = "Ma tu, Elian…"
  },
  AvgDialog_142852_Content_126 = {
    Text = "Lotan scosse la testa con disprezzo."
  },
  AvgDialog_142852_Content_127 = {
    Text = "Non hai nemmeno capito cosa mi importa davvero."
  },
  AvgDialog_142852_Content_128 = {
    Text = "Tu non sei niente."
  },
  AvgDialog_142852_Content_13 = {
    Text = "Due Venti ti sfiorarono, e un liquido tiepido ti schizzò addosso."
  },
  AvgDialog_142852_Content_130 = {
    Text = "Un colpo netto e preciso balenò nell'aria. Questo politico che aveva dominato sei nazioni giunse alla sua fine, con occhi pieni di stupore e impotenza."
  },
  AvgDialog_142852_Content_131 = {
    Text = "Nell'intera Arena rimasero solo due esseri ancora in grado di respirare. La grande spada in mano a Lotan era grondante di Sangue, e quello Sguardo privo di qualsiasi calore si posò su di te."
  },
  AvgDialog_142852_Content_14 = {
    Text = "Nessun dolore, e la morte sembrava non essere ancora giunta. Allontanasti le mani dagli Occhi e vedesti due teste fresche di taglio che ti fissavano con sguardo pieno di risentimento."
  },
  AvgDialog_142852_Content_15 = {Text = "ARGH!!"},
  AvgDialog_142852_Content_16 = {
    Text = "Ti affrettasti a fare due passi indietro, mancando di poco di inciampare nel mezzo cadavere di Gracco."
  },
  AvgDialog_142852_Content_17 = {
    Text = "Ah, le sorelle Vaughn, due cacciatrici di taglie così celebri. I re dei sei regni avevano tentato in mille modi di reclutarle, senza mai riuscirci."
  },
  AvgDialog_142852_Content_18 = {
    Text = "Ora, avevano incontrato l'unica caccia in cui erano destinate a fallire."
  },
  AvgDialog_142852_Content_19 = {
    Text = "Tra le grida fragorose del Pubblico di Fantasmi, Elian attraversò soddisfatto i cadaveri."
  },
  AvgDialog_142852_Content_2 = {
    Text = "Le alte mura circolari dell'Arena si ergevano imponenti, e le tribune erano gremite di Fantasmi in trepidante attesa."
  },
  AvgDialog_142852_Content_20 = {
    Text = "Non nell'ordine che avevo previsto, ma non importa. I nostri nemici sono ormai ridotti a ben pochi. Ora, credo che Tu abbia bisogno di Riposo…"
  },
  AvgDialog_142852_Content_21 = {
    Text = "Un violento fragore di zoccoli accompagnato da un Vento ululante interruppe le parole di Elian, comparendo all'improvviso alle spalle di Elian e Tua."
  },
  AvgDialog_142852_Content_22 = {
    Text = "Prima ancora che Tu potessi reagire, Lotan Ti sollevò e Ti scaraventò da parte."
  },
  AvgDialog_142852_Content_23 = {
    Text = "<RedBigShake:Muori—!>"
  },
  AvgDialog_142852_Content_24 = {
    Text = "Il nitrito squillante del destriero riecheggiò per tutta l'Arena. Tra la polvere, un generale in vecchia armatura trattenne il cavallo al galoppo e conficcò lo Spuntone dello stendardo che stringeva in mano nel petto di un Cavaliere che non aveva fatto in tempo a schivare."
  },
  AvgDialog_142852_Content_25 = {
    Text = "La polvere che si diradava lentamente delineava una figura tutt'altro che imponente. Tirò delicatamente le redini, girando il cavallo da guerra, e quegli occhi abituati a montagne di cadaveri e mari di Sangue vi fissarono con calma."
  },
  AvgDialog_142852_Content_26 = {
    Text = "Per un momento incrociasti involontariamente quello sguardo. Una potente sensazione di oppressione ti fece cedere le ginocchia, e Tu faticasti Quasi a restare in piedi."
  },
  AvgDialog_142852_Content_27 = {
    Text = "La polvere si diradò. Vedesti quella vecchia armatura leggendaria con settanta crepe, e quel cavallo da guerra bardato che aveva calpestato le terre di sei regni, sbuffando vapore con alterigia."
  },
  AvgDialog_142852_Content_28 = {
    Text = "Quattro teste grondanti Sangue pendevano dai fianchi del cavallo da guerra: un'abitudine che l'Anziano aveva coltivato fin da piccolo."
  },
  AvgDialog_142852_Content_29 = {
    Text = "Generale Alish."
  },
  AvgDialog_142852_Content_3 = {
    Text = "In profondità nel cielo rosso scuro come una palude, un'ombra enorme simile a una balena nuotava lentamente."
  },
  AvgDialog_142852_Content_30 = {
    Text = "Notasti che il tono di Lotan cambiava in modo evidente per la prima volta. La sua voce era rauca ed Euforica, come quella di un leone che aveva fiutato la preda."
  },
  AvgDialog_142852_Content_31 = {
    Text = "Dimmi, come si chiama il mio Rivale."
  },
  AvgDialog_142852_Content_32 = {
    Text = "Puoi chiamarmi Lotan."
  },
  AvgDialog_142852_Content_33 = {
    Text = "Lotan… La maggior parte delle persone degne di misurarsi con me le ho sentite nominare, ma non ricordo questo nome."
  },
  AvgDialog_142852_Content_34 = {
    Text = "Forse perché la maggior parte di coloro che hanno sentito questo nome sono già morti. Non importa. Tra cinque minuti, ricorderai il mio nome."
  },
  AvgDialog_142852_Content_35 = {
    Text = "Ha… Questo mondo produce spesso cambiamenti a cui faccio fatica ad Adattarmi. Forse i giovani d'oggi hanno qualcosa che mi fa stare in guardia."
  },
  AvgDialog_142852_Content_36 = {
    Text = "Sono già passati trenta minuti dall'inizio della gara di fuga. Per essere sopravvissuta fino ad ora, devi avere una forza all'altezza della tua arroganza."
  },
  AvgDialog_142852_Content_37 = {
    Text = "Ha frainteso, Generale Alish, non siamo Suoi nemici."
  },
  AvgDialog_142852_Content_38 = {
    Text = "Fatti da parte, Elian."
  },
  AvgDialog_142852_Content_39 = {
    Text = "(sottovoce) Signora Lotan, per favore non dimentichi il piano che abbiamo stabilito in precedenza. Ora dovremmo prima eliminare gli altri nemici. Alish è vecchio e debilitato, quando le sue forze cominceranno a venire meno…"
  },
  AvgDialog_142852_Content_4 = {
    Text = "Era sempre stato così curioso di assistere agli spettacoli?"
  },
  AvgDialog_142852_Content_40 = {
    Text = "Ho detto, fatti da parte."
  },
  AvgDialog_142852_Content_41 = {
    Text = "Elian aveva conosciuto molti individui pericolosi, e la voce di Lotan non era affatto più intensa rispetto a loro, eppure quelle parole fredde gli fecero provare una Paura più intensa di qualsiasi altra mai sentita prima."
  },
  AvgDialog_142852_Content_42 = {
    Text = "Non ci pensò a lungo, e si fece da parte con un'espressione impassibile."
  },
  AvgDialog_142852_Content_43 = {
    Text = "Non restano molte persone in questa Arena. C'è Solo un Rivale degno della mia sfida."
  },
  AvgDialog_142852_Content_44 = {
    Text = "Lotan posò la mano sull'impugnatura della grande spada e si avviò nella direzione di Alish."
  },
  AvgDialog_142852_Content_45 = {
    Text = "Le Apparizioni sulle tribune cadono in un silenzio assoluto, i loro volti privi di lineamenti che si girano all'unisono per seguire i passi di Lotan."
  },
  AvgDialog_142852_Content_46 = {
    Text = "Il ronzio a bassa frequenza nell'aria si fece più nitido, come un'antica e Avida attesa."
  },
  AvgDialog_142852_Content_47 = {
    Text = "Ho visto come combatti, giovane. In settant'anni di battaglie, non ho mai incontrato un Rivale forte come te."
  },
  AvgDialog_142852_Content_48 = {
    Text = "In quest'Arena si trovano i nemici più potenti del mondo, ognuno vuole colpire per primo, ma tu no. Tu aspetti sempre che il tuo Rivale sfogli la spada per primo…"
  },
  AvgDialog_142852_Content_49 = {
    Text = "Puoi dirmi perché?"
  },
  AvgDialog_142852_Content_5 = {
    Text = "Lotan scosse la testa ed estrasse la grande spada dal cadavere ai suoi piedi."
  },
  AvgDialog_142852_Content_50 = {
    Text = "Perché… un nemico che ha sguainato la spada è un po' più forte."
  },
  AvgDialog_142852_Content_51 = {
    Text = "Un po'… più forte?"
  },
  AvgDialog_142852_Content_52 = {
    Text = "Mi interessa Solo ciò che è più forte. Alza il tuo stendardo, Alish."
  },
  AvgDialog_142852_Content_53 = {
    Text = "Le parole di Lotan erano prive di qualsiasi provocazione. Lei teneva la mano sulla grande spada, gli Occhi fissi su Quello anziano generale, i passi solenni come quelli di un pellegrino."
  },
  AvgDialog_142852_Content_54 = {
    Text = "Eh eh… Ah ah ah ah!"
  },
  AvgDialog_142852_Content_55 = {
    Text = "Il vecchio generale rise a testa alta. Il suo destriero rimase immobile, uomo e cavallo soli al centro dell'Arena, la bandiera rossa che svolazzava Disordinata nel Vento."
  },
  AvgDialog_142852_Content_56 = {
    Text = "Molto simile. Davvero molto simile… Se fossimo stati un po' più giovani, forse avremmo potuto vedere in questo mondo un altro noi stessi."
  },
  AvgDialog_142852_Content_57 = {
    Text = "In ogni caso… spero che nessuno dei due deluda l'altro!"
  },
  AvgDialog_142852_Content_58 = {
    Text = "La voce di Alish si alza all'improvviso, le sue gambe che spronano abilmente la cavalcatura. Il destriero che lo ha portato attraverso innumerevoli battaglie scatta in avanti, il suo nitrito acuto che riecheggia per tutta la vasta arena —"
  },
  AvgDialog_142852_Content_59 = {
    Text = "Lo stendardo sventolò, come un fulmine rosso che squarciava la polvere al centro dell'Arena, scagliandosi verso Lotan."
  },
  AvgDialog_142852_Content_6 = {
    Text = "Le ossa trafitte stridevano contro la lama con un suono agghiacciante, il corpo robusto fu dilaniato in due tronconi, e quegli occhi pieni di risentimento rotolarono insieme a metà del corpo nel canale di scolo grondante Sangue."
  },
  AvgDialog_142852_Content_60 = {
    Text = "Vedesti che gli angoli della bocca di Lotan si sollevarono senza poterli Sopprimere. Era la prima volta che vedevi il sorriso di Lotan."
  },
  AvgDialog_142852_Content_61 = {
    Text = "Lei sguainò la grande spada e si lanciò di testa contro quel fulmine rosso—"
  },
  AvgDialog_142852_Content_62 = {Text = "..."},
  AvgDialog_142852_Content_63 = {Text = "BOOM!! —"},
  AvgDialog_142852_Content_64 = {
    Text = "La grande spada bianca si scontrò con la bandiera rossa, un suono acuto e stridulo fece vibrare i timpani di ognuno."
  },
  AvgDialog_142852_Content_65 = {
    Text = "Gli zoccoli ferrati del destriero sollevarono nuvole di polvere, le sagome di Lotan e Alish si incrociarono nel buio del campo di battaglia."
  },
  AvgDialog_142852_Content_66 = {
    Text = "Ad ogni collisione, l'ombra dell'enorme balena nel cielo tremava violentemente, come se stesse assaporando delle rare Prelibatezze Macabre."
  },
  AvgDialog_142852_Content_67 = {Text = "..."},
  AvgDialog_142852_Content_68 = {
    Text = "Generale Alish… Signora Lotan…"
  },
  AvgDialog_142852_Content_69 = {
    Text = "Che battaglia straordinaria…"
  },
  AvgDialog_142852_Content_7 = {
    Text = "Come aveva detto che si chiamava, poco fa?"
  },
  AvgDialog_142852_Content_70 = {
    Text = "Ti sforzi di catturare con gli Occhi le sagome dei due, ma è estremamente difficile distinguerle."
  },
  AvgDialog_142852_Content_71 = {
    Text = "Vira, agisci."
  },
  AvgDialog_142852_Content_72 = {
    Text = "Sì, signor Elian."
  },
  AvgDialog_142852_Content_73 = {Text = "!!!"},
  AvgDialog_142852_Content_74 = {
    Text = "Quello è… il mago avvelenatore della residenza del Primo Ministro?! Signora Lotan! Attenta…"
  },
  AvgDialog_142852_Content_75 = {
    Text = "Le tue parole rimangono incompiute, mentre una sensazione gelida si posa sulla tua pelle."
  },
  AvgDialog_142852_Content_76 = {
    Text = "Sssh… passerotto. Sei sempre stato fedele a me; ora, vorresti tradirmi per qualcuno che non conosci affatto?"
  },
  AvgDialog_142852_Content_77 = {
    Text = "Io… però…"
  },
  AvgDialog_142852_Content_78 = {
    Text = "Ho detto che, una volta ottenuta la Corona della Balena Celeste e diventato il re supremo dei sei regni, tu e i tuoi familiari riceverete la ricompensa che meritate."
  },
  AvgDialog_142852_Content_79 = {
    Text = "Ma ora, chiudi quella bocca per me."
  },
  AvgDialog_142852_Content_8 = {
    Text = "Gracco… Il Gladiatore più famoso di tutto il nord, mai sconfitto nelle Arene dei sei regni…"
  },
  AvgDialog_142852_Content_80 = {
    Text = "La gola si stringe. Solo chi è stato uno Schiavo sa quanto siano irresistibili le parole di Elian."
  },
  AvgDialog_142852_Content_81 = {
    Text = "Osservi l'avvelenatore nascondersi, scivolando nella polvere vorticante. Non dici altro."
  },
  AvgDialog_142852_Content_82 = {Text = "Hm?"},
  AvgDialog_142852_Content_83 = {
    Text = "Il generale, che stava galoppando a tutta velocità, intravide una sagoma dissolversi nel fumo e la polvere, aggrottando le sopracciglia. Questo lo fece reagire con un attimo di ritardo."
  },
  AvgDialog_142852_Content_84 = {
    Text = "Quando quella spada enorme e feroce si abbatté di nuovo su di lui, riuscì a malapena a sollevare il vessillo militare per parare il colpo."
  },
  AvgDialog_142852_Content_85 = {Text = "..."},
  AvgDialog_142852_Content_86 = {
    Text = "Un'ondata di Vigore si scontrò violentemente: il cavallo da guerra inciampò e cadde di schianto a terra. Il vessillo rosso sangue si spezzò in due tronconi, e una grande spada si posò sul suo collo."
  },
  AvgDialog_142852_Content_87 = {
    Text = "I tuoi movimenti si sono fatti lenti, Alish."
  },
  AvgDialog_142852_Content_88 = {
    Text = "…Il tuo alleato ti ha tradito."
  },
  AvgDialog_142852_Content_89 = {
    Text = "Questa cosa ha importanza?"
  },
  AvgDialog_142852_Content_9 = {
    Text = "Avevi visto molti morti, eppure lo spettacolo davanti a Te faceva rivoltare lo stomaco."
  },
  AvgDialog_142852_Content_90 = {
    Text = "Avete detto... cosa?"
  },
  AvgDialog_142852_Content_91 = {
    Text = "Lotan sospirò dolcemente, quel lieve sospiro colmo di rimpianto."
  },
  AvgDialog_142852_Content_92 = {
    Text = "Sei vicino, Alish, ma non abbastanza. Al di là del Potere e del combattimento, hai un'altra brama — l'onore."
  },
  AvgDialog_142852_Content_93 = {
    Text = "Ti preoccupi troppo di queste cose futili. Non sei ancora abbastanza puro."
  },
  AvgDialog_142852_Content_94 = {
    Text = "Lotan aprì gli Occhi, scosse la testa, ignorando completamente l'ombra nascosta dietro di Lei."
  },
  AvgDialog_142852_Content_95 = {
    Text = "Credi che, con l'aiuto di Elian, voi in gruppo contro di me, la vittoria non sarebbe onorevole."
  },
  AvgDialog_142852_Content_96 = {
    Text = "Non dovrebbe essere così? Due persone di abilità e pensiero simili, un duello equo…"
  },
  AvgDialog_142852_Content_97 = {
    Text = "Guarda quante parole hai usato. Onore, equità, dignità… sono tutte catene che i deboli forgiano per sé stessi."
  },
  AvgDialog_142852_Content_98 = {
    Text = "Il guerriero nasce Solo per combattere. Il combattimento… è Solo combattimento. Non ha nulla a che fare con qualsiasi altra cosa."
  },
  AvgDialog_142852_Content_99 = {
    Text = "L'ombra nel cielo si fermò, emettendo un rombo soddisfatto."
  },
  AvgDialog_142853_Content_1 = {
    Text = "La seconda sezione"
  },
  AvgDialog_142853_Content_10 = {
    Text = "Ho detto… Signora Lotan… potrebbe rallentare un po'…"
  },
  AvgDialog_142853_Content_100 = {
    Text = "Signora Lotan… non creda alle sue parole! È un impostore… Stando al suo fianco, l'ho visto commettere innumerevoli crimini…"
  },
  AvgDialog_142853_Content_101 = {
    Text = "Sono certo che Lei non collaborerebbe mai con uno come lui…"
  },
  AvgDialog_142853_Content_102 = {
    Text = "Agiti le mani verso Lotan ripetutamente. Vuoi avvertirla di quanto Elian sia un uomo astuto e subdolo."
  },
  AvgDialog_142853_Content_103 = {
    Text = "Da Schiavo a Mercante, da Mercante a nobile, da nobile a primo ministro, Elian ha percorso un Sentiero arduo lasciando innumerevoli impronte, e ognuna di esse era colma di Una Bugia e Banchetto di Sangue."
  },
  AvgDialog_142853_Content_104 = {
    Text = "Ma Lotan non Ti guardò. Girò la testa e alzò gli Occhi verso la volta del cielo rosso scuro. Quell'ombra enorme a forma di balena continuava a muoversi lentamente, il suo profilo irto di spine appariva e scompariva nell'oscurità."
  },
  AvgDialog_142853_Content_105 = {
    Text = "Fatti da parte."
  },
  AvgDialog_142853_Content_106 = {
    Text = "Ti scosti intorpidito. Lotan Ti passa accanto, china la testa e fissa dall'alto il primo ministro davanti a Lei. La luce rosso scuro disegna dietro di Lei una sagoma affilata come una lama."
  },
  AvgDialog_142853_Content_107 = {
    Text = "Sei molto più interessante del Tuo ordine di Cavalieri, Elian. Non mi importa che tipo di persona Tu sia, né mi preoccupo di quando mi tradirai. Puoi essermi utile, e questo è sufficiente."
  },
  AvgDialog_142853_Content_108 = {
    Text = "Accetto la Tua richiesta. Non disturbare i miei combattimenti: questa è la mia unica condizione."
  },
  AvgDialog_142853_Content_109 = {
    Text = "Signora Lotan… Lei…"
  },
  AvgDialog_142853_Content_11 = {
    Text = "Per tutto il Sentiero non ha quasi parlato, ha solo ucciso e camminato senza mai fermarsi a riposare…"
  },
  AvgDialog_142853_Content_110 = {
    Text = "La sete di potere che aleggia nell'aria ti travolge come una marea. Un sorriso amaro ti affiora sul volto. Tutti qui sono uguali — non avresti dovuto aspettarti niente di diverso."
  },
  AvgDialog_142853_Content_111 = {
    Text = "Elian si aprì in un sorriso smagliante; nel suo atteggiamento non vi era nemmeno una traccia di gioia inaspettata, Come Se si trattasse di una trattativa dal risultato già scontato."
  },
  AvgDialog_142853_Content_112 = {
    Text = "Si girò e si avviò verso le tribune ai bordi dell'Arena."
  },
  AvgDialog_142853_Content_113 = {
    Text = "Le informazioni su Tutti, le squadre che formeranno, il momento in cui si spezzeranno, e persino l'ordine delle sfide che Ti darà maggior piacere: ho già pensato a tutto per Te."
  },
  AvgDialog_142853_Content_114 = {
    Text = "Goditi questo combattimento, Signora Lotan."
  },
  AvgDialog_142853_Content_12 = {
    Text = "Preferisci tacere da solo, o vuoi che ti ficchi la spada in bocca?"
  },
  AvgDialog_142853_Content_13 = {Text = "..."},
  AvgDialog_142853_Content_14 = {
    Text = "Ti copri la bocca con forza. Lo Sguardo di Lotan non si sofferma su di Te. Lei osserva i Dintorni, la mano che scorre lungo un frammento di colonna spezzata."
  },
  AvgDialog_142853_Content_15 = {
    Text = "La sezione della colonna è ricoperta di venature nere, simili a vasi sanguigni, come se il tessuto di qualche essere vivente stesse crescendo al suo interno."
  },
  AvgDialog_142853_Content_16 = {
    Text = "Quello è..."
  },
  AvgDialog_142853_Content_17 = {
    Text = "Accosti l'orecchio alla colonna e percepisci vagamente un ritmo profondissimo, come se una creatura enorme respirasse lentamente nelle viscere della Pietra."
  },
  AvgDialog_142853_Content_18 = {
    Text = "Un'improvvisa nausea e un impulso omicida ti invadono il corpo; ti allontani in fretta."
  },
  AvgDialog_142853_Content_19 = {
    Text = "Questa cosa… è viva?!"
  },
  AvgDialog_142853_Content_2 = {
    Text = "È questo il Sentiero che hai indicato?"
  },
  AvgDialog_142853_Content_20 = {
    Text = "Secondo la leggenda, la Balena del Cielo Stellato ha creato questo mondo con il Suo corpo, e i popoli delle sei nazioni esistono tutti sulla Sua carne."
  },
  AvgDialog_142853_Content_21 = {
    Text = "A quanto pare, le siamo già molto vicini."
  },
  AvgDialog_142853_Content_22 = {
    Text = "Lotan si avvicina a un tavolo di Pietra al centro della piazza. Quel tavolo, fatto di lapislazzuli, con la sua fattura raffinata e i suoi materiali pregiati, stonava completamente con quel luogo desolato."
  },
  AvgDialog_142853_Content_23 = {
    Text = "La superficie del tavolo è ricoperta da uno strato di squame fitte e umide che si aprono e chiudono lentamente nella fioca luce, con una frequenza identica al respiro che avevi appena sentito."
  },
  AvgDialog_142853_Content_24 = {
    Text = "Lotan vi posa sopra i due Sigilli d'Osso. Nel momento in cui le scaglie toccano i Sigilli, si stringono come innumerevoli dita che afferrano una preda e divorano i due Sigilli interi."
  },
  AvgDialog_142853_Content_25 = {
    Text = "I nostri sigilli d'osso!!!"
  },
  AvgDialog_142853_Content_26 = {
    Text = "Ah! Due nuovi sfidanti!"
  },
  AvgDialog_142853_Content_27 = {
    Text = "Mentre Ti lanci verso il tavolo di Pietra, una sagoma umanoide emerge lentamente dal centro del tavolo."
  },
  AvgDialog_142853_Content_28 = {
    Text = "Il suo volto cambia continuamente: a volte è un re, a volte un Cavaliere, a volte qualcosa che non riesci a riconoscere."
  },
  AvgDialog_142853_Content_29 = {
    Text = "La sua voce sembra provenire da sotto un lago di Sangue, e ogni sillaba porta con sé una strana Risonanza."
  },
  AvgDialog_142853_Content_3 = {
    Text = "Stiamo cercando l'Arena, non delle rovine. Questo posto sembra abbandonato da molti anni."
  },
  AvgDialog_142853_Content_30 = {
    Text = "Sono il Fantasma della Balena del Cielo Stellato, il Suo servo più fedele, nonché il gestore e Il Pubblico di questa Arena."
  },
  AvgDialog_142853_Content_31 = {
    Text = "Avete affrontato innumerevoli pericoli e siete giunti fin qui grazie al vostro Potere e alla vostra saggezza. Siete l'orgoglio delle sei nazioni, i più forti e tenaci…"
  },
  AvgDialog_142853_Content_32 = {
    Text = "Meno chiacchiere."
  },
  AvgDialog_142853_Content_33 = {
    Text = "……Sei piuttosto maleducato, sfidante. Per fortuna, la Balena Celeste non bada a queste cose."
  },
  AvgDialog_142853_Content_34 = {
    Text = "A Lei importa una sola cosa: il Potere. Puro, senza la minima impurità."
  },
  AvgDialog_142853_Content_35 = {
    Text = "Benvenuto, benvenuto nell'Arena della Balena Celeste, benvenuto sul palcoscenico del Potere puro—"
  },
  AvgDialog_142853_Content_36 = {
    Text = "Il Fantasma alza entrambe le braccia, e un suono basso e lontano come il canto di una balena emerge dal suo corpo, attraversa le tue ossa e Risonanza nella tua cavità cranica."
  },
  AvgDialog_142853_Content_37 = {
    Text = "!!! Questo è..."
  },
  AvgDialog_142853_Content_38 = {
    Text = "Il canto si propaga verso l'esterno. Ovunque si diffonda, il cielo si tinge di un rosso cupo. Le rovine in frantumi, incollate da un viscido non identificabile, si fondono in una grande e antica arena."
  },
  AvgDialog_142853_Content_39 = {
    Text = "Le gigantesche sculture di divinità tutt'intorno assumono pose diverse, osservando con occhi pietosi o colmi di Rabbia le creature insignificanti come formiche ai loro piedi."
  },
  AvgDialog_142853_Content_4 = {
    Text = "Ricordavo bene la mappa, dovrebbe essere proprio questo posto… Ma perché è diverso da come era descritto?"
  },
  AvgDialog_142853_Content_40 = {
    Text = "Una dozzina di sfidanti si trova sparsa sulla piattaforma, a scrutarti."
  },
  AvgDialog_142853_Content_41 = {
    Text = "Uno, due, tre… quindici, sedici."
  },
  AvgDialog_142853_Content_42 = {
    Text = "In totale ci sono venti Sigilli d'Osso — dovrebbero arrivare altre due persone..."
  },
  AvgDialog_142853_Content_43 = {
    Text = "Non ce ne sono altri, sfidanti. Quei due Sigilli sono stati già distrutti nel turno precedente."
  },
  AvgDialog_142853_Content_44 = {
    Text = "Congratulazioni. Essendo l'ultima ad arrivare, ti guadagni l'onore dell'attenzione di tutti —"
  },
  AvgDialog_142853_Content_45 = {
    Text = "Tra le risate leggere del Fantasma, sedici sguardi ostili si rivolgono verso di voi."
  },
  AvgDialog_142853_Content_46 = {
    Text = "Quella persona mi sembra molto familiare… l'ho forse vista in qualche immagine promozionale di un'arena gladiatoria?"
  },
  AvgDialog_142853_Content_47 = {
    Text = "Quell'abito… sembra appartenere all'organizzazione di assassini chiamata Mignolo! Non mi aspettavo di incontrare qualcuno di loro qui…"
  },
  AvgDialog_142853_Content_48 = {
    Text = "Ne sai parecchio."
  },
  AvgDialog_142853_Content_49 = {
    Text = "Non posso parlare durante le riunioni dell'Ordine dei Cavalieri, ma vi ho assistito molte volte. Il signor Elian ci ha raccontato molte cose…"
  },
  AvgDialog_142853_Content_5 = {
    Text = "Osservi le mura diroccate e i resti sgretolati dal Vento nel corso degli anni e ti gratti la testa."
  },
  AvgDialog_142853_Content_50 = {
    Text = "Ah! Guarda laggiù!! Quell'uomo con la vecchia armatura!"
  },
  AvgDialog_142853_Content_51 = {
    Text = "È il generale più valoroso dei sei regni! Ha ucciso da Solo il re di un paese nemico sul campo di battaglia, e sono cresciuto ascoltando le sue storie!"
  },
  AvgDialog_142853_Content_52 = {
    Text = "Una leggenda vivente! Non me lo sarei mai aspettato… non mi aspettavo di incontrarlo qui!"
  },
  AvgDialog_142853_Content_53 = {
    Text = "Lotan non ha badato alle tue grida di Euforia incontenibile. Ha scansionato i partecipanti con lo sguardo, poi si è appoggiata a una colonna di pietra chiudendo gli occhi."
  },
  AvgDialog_142853_Content_54 = {
    Text = "Prima che il Cavaliere prendesse parte a questa competizione, ho scommesso con la signora su chi sarebbe entrato nel palazzo della Balena Celeste."
  },
  AvgDialog_142853_Content_55 = {
    Text = "Hai fatto molto bene, passerotto. Quando questo noioso gioco sarà finito, la signora dovrà risarcirmi con una bella sommetta."
  },
  AvgDialog_142853_Content_56 = {Text = "!!!"},
  AvgDialog_142853_Content_57 = {
    Text = "E… il signor Elian…"
  },
  AvgDialog_142853_Content_58 = {
    Text = "Una Voce Gentile, un passo sicuro, un ampio mantello di pregiato tessuto, il profumo di ginepro che emana da lui… anche ridotto in Resti Cinerei, lo riconosceresti."
  },
  AvgDialog_142853_Content_59 = {
    Text = "Lei… come mai è venuto di persona… voglio dire…"
  },
  AvgDialog_142853_Content_6 = {
    Text = "Il re scrisse nel suo diario che le mura qui erano fatte d'Oro, che nel cielo volavano messaggeri divini dalle sei ali, e che nei fiumi scorrevano miele e vino…"
  },
  AvgDialog_142853_Content_60 = {
    Text = "Ha incaricato il Cavaliere di lottare per la Corona al suo posto, pensavo…"
  },
  AvgDialog_142853_Content_61 = {
    Text = "Pensavi che avrei riposto tutte le mie speranze in un Cavaliere che non riesce nemmeno a battere dei mercenari? Te l'ho insegnato, passerotto: non mettere mai tutte le uova nello stesso paniere."
  },
  AvgDialog_142853_Content_62 = {
    Text = "Abbi un po' di fede nel buon Elian: la grande Balena Celeste concede sempre la sua Benedizione alle persone oneste."
  },
  AvgDialog_142853_Content_63 = {
    Text = "Il nobile sorrise con eleganza. Lo Sguardo non si allontanò mai da Lotan."
  },
  AvgDialog_142853_Content_64 = {
    Text = "Questa è… una tua amica?"
  },
  AvgDialog_142853_Content_65 = {
    Text = "Ehm, forse non proprio…"
  },
  AvgDialog_142853_Content_66 = {
    Text = "Lotan. Una guerriera."
  },
  AvgDialog_142853_Content_67 = {
    Text = "È un piacere conoscerti, signora Lotan. Spero che i miei servitori non ti abbiano causato problemi."
  },
  AvgDialog_142853_Content_68 = {
    Text = "Il Gran Visir?"
  },
  AvgDialog_142853_Content_69 = {
    Text = "Lo Sguardo di Lotan scorse i fregi sui suoi abiti e sulla spada al fianco. Anche per chi non si interessava minimamente alla politica dei Sei Regni, l'Impronta del Gran Visir era comunque facilmente riconoscibile."
  },
  AvgDialog_142853_Content_7 = {
    Text = "E ora questa piazza che sembra un cumulo di rovine… non si vede nemmeno nessuno che controlli i sigilli d'osso."
  },
  AvgDialog_142853_Content_70 = {
    Text = "Un titolo onorifico, nient'altro. L'unica utilità è risparmiare tempo nelle presentazioni."
  },
  AvgDialog_142853_Content_71 = {
    Text = "Elian sorrise e si sedette sulla colonna di pietra di fronte a Lotan."
  },
  AvgDialog_142853_Content_72 = {
    Text = "Hai portato qui il mio servo, eppure il mio Cavaliere è sparito. Credo di aver già capito più o meno cosa è successo lungo il Sentiero."
  },
  AvgDialog_142853_Content_73 = {
    Text = "Il tuo Cavaliere è morto in modo miserevole. Dodici uomini, senza nemmeno sfiorare l'armatura di un guerriero di infima categoria."
  },
  AvgDialog_142853_Content_74 = {
    Text = "E tu, hai vinto quella battaglia con estrema facilità."
  },
  AvgDialog_142853_Content_75 = {
    Text = "Sembra che la loro morte non ti interessi affatto."
  },
  AvgDialog_142853_Content_76 = {
    Text = "Ah, no no no, mi ha frainteso, signora Lotan…"
  },
  AvgDialog_142853_Content_77 = {
    Text = "Elian scoppiò in una grande risata, scuotendo la testa."
  },
  AvgDialog_142853_Content_78 = {
    Text = "I miei Cavalieri sono tutti bravi ragazzi, leali, diligenti… ma questa è l'Arena della Balena Celeste. I deboli hanno incontrato la fine che spetta ai deboli, e questo non mi preoccupa affatto."
  },
  AvgDialog_142853_Content_79 = {
    Text = "Ciò che mi preoccupa sei tu, signora Lotan. Una guerriera potente, che ama le lame, il massacro e il Sangue, disposta a sacrificare tutto per quella Corona forgiata nel sangue…"
  },
  AvgDialog_142853_Content_8 = {
    Text = "Ehi! Aspettami…"
  },
  AvgDialog_142853_Content_80 = {
    Text = "Elian parlava sempre più velocemente. L'aria impregnata di massacro e sete di potere lo pervadeva, facendo battere il suo cuore indurito dagli anni in modo incontrollabile."
  },
  AvgDialog_142853_Content_81 = {
    Text = "Come se si fosse accorto di aver perso il controllo, fece un respiro profondo e indietreggiò di mezzo passo."
  },
  AvgDialog_142853_Content_82 = {
    Text = "Credo che potremmo collaborare."
  },
  AvgDialog_142853_Content_83 = {
    Text = "Ti sembra che io sia una persona a cui piace collaborare?"
  },
  AvgDialog_142853_Content_84 = {
    Text = "I deboli tendono sempre a fare gruppo, e tu ovviamente non sei così. Ma ognuno ha bisogno di collaborare, e tu non fai eccezione."
  },
  AvgDialog_142853_Content_85 = {
    Text = "Lotan non aveva ancora risposto quando innumerevoli Fantasmi identici apparvero sui sedili dell'Arena, riempiendo ogni posto del gremito settore del Pubblico, e una voce simile al canto della balena risuonò di nuovo in tutta la vasta Arena."
  },
  AvgDialog_142853_Content_86 = {
    Text = "Bene, sfidanti, non vediamo l'ora. La prova finale sta per svolgersi in questa magnifica Arena!"
  },
  AvgDialog_142853_Content_87 = {
    Text = "Quando l'ultimo vincitore emergerà, un Portale verso il palazzo della Balena Celeste si aprirà per lui!"
  },
  AvgDialog_142853_Content_88 = {
    Text = "Oltre quel Portale, gloria infinita, ricchezze, potere — tutto!"
  },
  AvgDialog_142853_Content_89 = {
    Text = "Scegliere il vincitore… quali sono le regole?"
  },
  AvgDialog_142853_Content_9 = {
    Text = "Mentre parli da solo rivolto all'antico piedistallo di pietra, Lotan si avvia verso il centro della grande piazza."
  },
  AvgDialog_142853_Content_90 = {
    Text = "Le regole? Eheh… Ahahaha! Le regole?!…"
  },
  AvgDialog_142853_Content_91 = {
    Text = "Le risate esagerate dei Fantasmi fecero risuonare dolorosamente i timpani di tutti nell'Arena. Tra le risate di Follia, smisero di parlare e guardarono con aspettativa il centro dell'Arena vuota."
  },
  AvgDialog_142853_Content_92 = {
    Text = "Ma… non ha ancora detto quali sono le regole…"
  },
  AvgDialog_142853_Content_93 = {
    Text = "Lo ha già detto. \"L'ultimo vincitore\", Solo Uno. Questa è l'unica regola, passerotto."
  },
  AvgDialog_142853_Content_94 = {
    Text = "Uccisioni, sfide, alleanze, tradimenti… Diciotto partecipanti, solo uno rimasto in piedi potrà attraversare quel Portale."
  },
  AvgDialog_142853_Content_95 = {
    Text = "Il Volto di Elian si illumina di nuovo con quel sorriso che Ti è familiare."
  },
  AvgDialog_142853_Content_96 = {
    Text = "Ciò che dovrai affrontare sarà il gruppo di persone più potenti di questo mondo."
  },
  AvgDialog_142853_Content_97 = {
    Text = "Non fraintendermi, non metto in Quesito Eterno il Tuo Potere nemmeno per un istante, Signora Lotan."
  },
  AvgDialog_142853_Content_98 = {
    Text = "Ma immagino che Tu non voglia essere disturbata da persone noiose mentre Ti godi quelle piacevoli uccisioni, vero?"
  },
  AvgDialog_142853_Content_99 = {
    Text = "Lotan alzò la testa seriamente per la prima volta. Vide un Il Volto dal sorriso gentile, e su quel Il Volto un paio di Occhi che sembravano capaci di scrutare ogni cosa."
  },
  AvgDialog_142854_Content_1 = {
    Text = "La quinta sezione"
  },
  AvgDialog_142854_Content_10 = {
    Text = "Lo… Lotan, mia signora?"
  },
  AvgDialog_142854_Content_11 = {
    Text = "Non riesci a riconoscere se la persona davanti a te, coperta di Sangue, sia Lotan o meno."
  },
  AvgDialog_142854_Content_12 = {
    Text = "Un Sangue sporco e corrotto ricopre il suo corpo, impossibile dire se provenga da lei stessa o da qualcos'altro."
  },
  AvgDialog_142854_Content_13 = {
    Text = "Sotto quel Sangue immondo e quell'armatura in frantumi, metà del suo corpo è ridotta a ossa bianche e nude."
  },
  AvgDialog_142854_Content_14 = {
    Text = "La guerriera con metà del corpo rimasto emerge da quella fenditura impregnata di odore di Sangue. Il suo passo è lento, stanco, e la grande spada spezzata trascina sul suolo, tracciando un solco leggero nel lago di Sangue."
  },
  AvgDialog_142854_Content_15 = {
    Text = "Nell'altra mano, la Corona formata dal Banchetto di Sangue lascia cadere gocce di Sangue sporco."
  },
  AvgDialog_142854_Content_16 = {
    Text = "I suoi Occhi brillano come mai prima d'ora."
  },
  AvgDialog_142854_Content_17 = {
    Text = "Lo… Lotan, mia signora… la Balena del Cielo Stellato… Essa…"
  },
  AvgDialog_142854_Content_18 = {Text = "Ha perso."},
  AvgDialog_142854_Content_19 = {
    Text = "La voce di Lotan non tradisce alcun tremore, Come Se stesse semplicemente enunciando qualcosa che doveva inevitabilmente accadere."
  },
  AvgDialog_142854_Content_2 = {
    Text = "Coff... Coff, coff..."
  },
  AvgDialog_142854_Content_20 = {
    Text = "Lei ha stipulato Il Testamento con Essa… se Essa subisce un Danno, anche Lei…"
  },
  AvgDialog_142854_Content_21 = {
    Text = "Non hai bisogno di continuare a chiedere. Le ferite sul corpo di Lotan dicono già tutto."
  },
  AvgDialog_142854_Content_22 = {
    Text = "Lady Lotan, hai sconfitto ogni sfidante... persino il Ceto Astrale!"
  },
  AvgDialog_142854_Content_23 = {
    Text = "Ora Lei è l'indiscussa regina di questo pianeta… ora è il momento più glorioso della sua vita! Ora…"
  },
  AvgDialog_142854_Content_24 = {
    Text = "Ora è anche il momento in cui lei è più Fragile."
  },
  AvgDialog_142854_Content_25 = {
    Text = "L'odore di Sangue che filtra dalla fenditura ti avvolge, e il Sussurro simile al canto della balena si fa sempre più nitido alle tue orecchie."
  },
  AvgDialog_142854_Content_26 = {
    Text = "Guarda, la Corona formata dal Banchetto di Sangue…"
  },
  AvgDialog_142854_Content_27 = {
    Text = "I troni di sei nazioni, la sottomissione di milioni di persone, ricchezze e gloria inesauribili… quella Corona può donare al suo padrone qualsiasi cosa."
  },
  AvgDialog_142854_Content_28 = {
    Text = "Ogni persona nell'Arena la brama. Quei Cavalieri che ti rimproverano ogni giorno, Gracco, le sorelle Vorn, il generale Alish, il potentissimo signor Elian…"
  },
  AvgDialog_142854_Content_29 = {
    Text = "E anche Tu, passerotto. Anche Tu la brami…"
  },
  AvgDialog_142854_Content_3 = {
    Text = "Quello è..."
  },
  AvgDialog_142854_Content_30 = {
    Text = "Tu fissi la Corona Cremisi tra le mani di Lotan. A ogni goccia di Banchetto di Sangue che cade, il Sussurro della Balena del Cielo Stellato si fa sempre più nitido."
  },
  AvgDialog_142854_Content_31 = {
    Text = "Non sarai mai più una schiava, piccolo passero."
  },
  AvgDialog_142854_Content_32 = {
    Text = "Costruirai un grande mausoleo per tua madre. Porterai i tuoi fratelli fuori dalle stalle per vivere con te in uno splendido palazzo."
  },
  AvgDialog_142854_Content_33 = {
    Text = "Coloro che un tempo vi hanno umiliato si inginocchieranno davanti a Te e baceranno il dorso dei tuoi piedi."
  },
  AvgDialog_142854_Content_34 = {
    Text = "Il potere. Il potere supremo."
  },
  AvgDialog_142854_Content_35 = {
    Text = "Quei nomi che scorrono nelle leggende sono morti per esso... e ora, è davanti ai tuoi Occhi, a portata di mano."
  },
  AvgDialog_142854_Content_36 = {
    Text = "Vai, passerotto. In tutta la tua vita, questa è la tua unica occasione!"
  },
  AvgDialog_142854_Content_37 = {
    Text = "Il sussurro si trasformò in un fragore, e un impulso irresistibile si agitò nella tua mente come un'Ondata. La gola secca si contrasse, e la tua mano tremante sollevò il Pugnale tempestato di gemme lasciato da Elian. Sulla lama del Pugnale era ancora impresso il tuo stesso Sangue."
  },
  AvgDialog_142854_Content_38 = {
    Text = "Sei già arrivato fin qui, perché non puoi fare un altro passo avanti? Quella è tua... la Corona ti appartiene da sempre..."
  },
  AvgDialog_142854_Content_39 = {
    Text = "Sei già arrivato fin qui, perché non puoi fare un altro passo avanti? Quella è tua... la Corona ti appartiene da sempre..."
  },
  AvgDialog_142854_Content_4 = {
    Text = "Ti rialzasti dalla polvere che ricopriva il suolo, scrollasti via i granelli di sabbia dal corpo e impiegasti qualche secondo per ricordare dove ti trovassi."
  },
  AvgDialog_142854_Content_40 = {
    Text = "<Red:Uccidila?... Uccidila... Uccidila... Uccidila!!!>"
  },
  AvgDialog_142854_Content_41 = {
    Text = "Tre passi. Sei a soli tre passi da quella gloria suprema..."
  },
  AvgDialog_142854_Content_42 = {
    Text = "Nel momento in cui stai raccogliendo il coraggio per fare il primo passo, Lotan si volta. Quei due Occhi stanchi Ti fissano con calma."
  },
  AvgDialog_142854_Content_43 = {
    Text = "Nel momento in cui stai raccogliendo il coraggio per fare il primo passo, Lotan si volta. Quei due Occhi stanchi Ti fissano con calma."
  },
  AvgDialog_142854_Content_44 = {
    Text = "Nell'istante in cui sei investito da Lo Sguardo, tutti i sussurri che ti sostenevano svaniscono all'unisono, e il tuo Sangue ribollente si raffredda di colpo."
  },
  AvgDialog_142854_Content_45 = {
    Text = "Io... io non..."
  },
  AvgDialog_142854_Content_46 = {
    Text = "Negli Occhi di Lotan non vi è la minima intenzione di uccidere. Guardando quegli Occhi, capisci all'improvviso che, se non fosse per incontrare la Balena del Cielo Stellato, nessuno qui meriterebbe che Lei muovesse un dito."
  },
  AvgDialog_142854_Content_47 = {
    Text = "Negli Occhi di Lotan non vi è la minima intenzione di uccidere. Guardando quegli Occhi, capisci all'improvviso che, se non fosse per incontrare la Balena del Cielo Stellato, nessuno qui meriterebbe che Lei muovesse un dito."
  },
  AvgDialog_142854_Content_48 = {
    Text = "Era Lo Sguardo di chi osserva dall'alto le formiche che si battono per un pezzo di zucchero. Nient'altro, nessuna emozione in più."
  },
  AvgDialog_142854_Content_49 = {
    Text = "La storia delle formiche non è mai cambiata. Lei alzò quella mano ormai ridotta a puro osso e posò con noncuranza ciò che stringeva sulla tua testa."
  },
  AvgDialog_142854_Content_5 = {
    Text = "Le pareti di Pietra dell'Arena si sgretolarono come carta, enormi blocchi di roccia precipitarono dagli spalti, e le ultime tracce degli spettatori Fantasma erano già svanite."
  },
  AvgDialog_142854_Content_50 = {
    Text = "!!! Questo è..."
  },
  AvgDialog_142854_Content_51 = {
    Text = "Gocce di Sangue caldo e sporco ti caddero sulla sommità del capo. Allungasti la mano e, sulla tua stessa testa, toccasti quella Corona fredda e vischiosa, formata da una Confluenza di Banchetto di Sangue."
  },
  AvgDialog_142854_Content_52 = {
    Text = "Innumerevoli eroi hanno ucciso per essa, innumerevoli anime si sono corrotte per essa. Il potere e la ricchezza di sei nazioni, la nobiltà e la gloria supreme, ora posano leggere leggere sulla tua testa."
  },
  AvgDialog_142854_Content_53 = {
    Text = "Il vincitore finale te la gettò tra le mani con indifferenza, come si ficca un pezzo di zucchero nella bocca Avida di un bambino — ora, hai tutto."
  },
  AvgDialog_142854_Content_54 = {
    Text = "Signora Lotan… Lei… Lei…"
  },
  AvgDialog_142854_Content_55 = {
    Text = "Fammi un favore."
  },
  AvgDialog_142854_Content_56 = {
    Text = "Devo andare a cercare un nuovo Rivale. Prima di allora, ho bisogno di una nuova coppia di spade."
  },
  AvgDialog_142854_Content_57 = {
    Text = "Lotan guardò la coppia di enormi spade che l'aveva accompagnata per tanti anni, riponendo i loro corpi distrutti nei foderi."
  },
  AvgDialog_142854_Content_58 = {
    Text = "Lei si girò, trascinando il suo corpo devastato, avanzando stanca e lenta verso di essa, verso un traguardo che Tu non puoi comprendere."
  },
  AvgDialog_142854_Content_59 = {
    Text = "Nella fenditura dietro di Tu, le antiche rune si spensero una ad una, e quella divinità in disfacimento e corruzione mostrò un sorriso di sollievo che Tu non aveva mai visto prima."
  },
  AvgDialog_142854_Content_6 = {
    Text = "Eri disteso sul terreno cosparso di macerie, con un ronzio incessante nelle orecchie. La Frattura Dimensionale era sospesa al centro dell'Arena, i suoi bordi si contraevano violentemente, come una Ferita orribile e straziante."
  },
  AvgDialog_142854_Content_60 = {
    Text = "Al mio posto… Record il suo nome."
  },
  AvgDialog_142854_Content_61 = {
    Text = "Tu eri inginocchiato in un lago di Sangue, fissando quella figura che si allontanava sempre di più, incapace di rialzarti per lungo tempo."
  },
  AvgDialog_142854_Content_62 = {
    Text = "La Corona sul tuo capo è pesante, così tanto pesante. Il peso di dodicimila anni di desiderio ti fa cadere in ginocchio nella pozza di sangue. La osservi allontanarsi, incapace di rialzarti per molto, molto tempo."
  },
  AvgDialog_142854_Content_63 = {
    Text = "La Corona sulla testa era leggera, così leggera, come se non fosse mai esistita."
  },
  AvgDialog_142854_Content_7 = {
    Text = "Un lamento cupo e prolungato giunse dalla Ferita, trapassando il tuo cranio fino alle profondità della mente, pesante come il sospiro di un intero pianeta."
  },
  AvgDialog_142854_Content_8 = {
    Text = "Quella voce… è la Balena Stellare?!"
  },
  AvgDialog_142854_Content_9 = {
    Text = "Dalla crepa si sprigionava un intenso e nauseante odore di Sangue. Mentre ti preparavi ad avvicinarti lentamente, un piede ridotto a puro scheletro uscì dalla crepa."
  },
  AvgDialog_142888_Content_1 = {Text = "Una Bugia"},
  AvgDialog_142888_Content_10 = {
    Text = "Non riesci a rispondere, i tuoi ricordi sono ora in subbuglio come un cane a pelo lungo che si è rotolato tre volte nel fango."
  },
  AvgDialog_142888_Content_100 = {
    Text = "Invade il petto, invade i padiglioni auricolari, invade…"
  },
  AvgDialog_142888_Content_101 = {
    Text = "Mio Signore!"
  },
  AvgDialog_142888_Content_102 = {
    Text = "Torni improvvisamente alla realtà. In lontananza, Ogier, Lotan e Ramona camminano verso di te, avendo terminato il loro allenamento. I burattini separati di Doll stanno analizzando i dati dell'addestramento."
  },
  AvgDialog_142888_Content_103 = {
    Text = "La persona accanto a te sospira con grande rammarico."
  },
  AvgDialog_142888_Content_104 = {
    Text = "Non preoccuparti, terrò sempre aperta questa scelta per te."
  },
  AvgDialog_142888_Content_105 = {
    Text = "Nessuno rimane al tuo fianco. L'orizzonte dove il sole al tramonto sta per sprofondare rifrange un bagliore perlaceo tenue e lievemente psichedelico."
  },
  AvgDialog_142888_Content_106 = {Text = "Ah..."},
  AvgDialog_142888_Content_107 = {
    Text = "Hai ancora molte cose da dire. Riguardo a quella catastrofe priva di qualsiasi mira precisa, scatenata solo per capriccio da N che aveva sobillato i fedeli."
  },
  AvgDialog_142888_Content_108 = {
    Text = "Riguardo al ruolo della Chiesa della Lanterna nell'alimentare le fiamme, riguardo ai vari atti folli di ritorsione di Pontos nel secolo successivo circa."
  },
  AvgDialog_142888_Content_109 = {
    Text = "Riguardo a… se ci sia stato un momento in cui anche lui abbia vacillato di fronte a un'altra possibilità, lasciando che gli anni lasciassero un segno su di lui."
  },
  AvgDialog_142888_Content_11 = {
    Text = "Leisha, quasi senza forze a causa della battaglia precedente, si sforzò di rialzarsi e si frappose tra te e Pontos."
  },
  AvgDialog_142888_Content_110 = {
    Text = "Riguardo a Jago e Leisha, se stiano ancora festeggiando a Ebwynnos in questo momento."
  },
  AvgDialog_142888_Content_111 = {
    Text = "…Alla fine vuoi solo pregare che non combini qualcosa con il Professor Dexter a scuola."
  },
  AvgDialog_142888_Content_112 = {
    Text = "Scuoti la testa e cammini verso i tuoi amici senza esitazione."
  },
  AvgDialog_142888_Content_12 = {
    Text = "Pontos, è finita."
  },
  AvgDialog_142888_Content_13 = {
    Text = "Chi è ancora vivo, se rimane a Ebwynnos, dovrà pagare il prezzo di dimenticare i ricordi del mondo esterno."
  },
  AvgDialog_142888_Content_14 = {
    Text = "E persone come me, già morte e rimodellate in incubi, vedranno alla fine tutti i loro ricordi lentamente erosi dalla Corrosione."
  },
  AvgDialog_142888_Content_15 = {
    Text = "Jago ha fatto la sua scelta, e anch'io ho fatto la mia…\nAndiamocene."
  },
  AvgDialog_142888_Content_16 = {
    Text = "Le labbra di Pontos si strinsero in una linea fredda e indifferente, i muscoli della mascella tesi."
  },
  AvgDialog_142888_Content_17 = {
    Text = "Dovresti ricordarlo: la tua esistenza dipende da Ebwynnos. Se lasci Ebwynnos, morirai."
  },
  AvgDialog_142888_Content_18 = {
    Text = "Sì, ma i miei ricordi del passato torneranno. Morirò come essere umano. È l'unico modo."
  },
  AvgDialog_142888_Content_19 = {
    Text = "Già… non ricordo più che aspetto avevate tu e Jago da bambini. Almeno, prima che vi dimentichi del tutto."
  },
  AvgDialog_142888_Content_2 = {
    Text = "Il Sinistro soffocante si ritira come una marea, il tuo cervello è scosso da fitte lancinanti e la vista ti si annebbia più volte."
  },
  AvgDialog_142888_Content_20 = {
    Text = "Pontos rimase immobile. Per la prima volta, vedesti apparire sul suo volto un'Espressione di così profonda tristezza."
  },
  AvgDialog_142888_Content_21 = {
    Text = "…Vorrei tanto poter dire che quella forza mi stia ancora controllando."
  },
  AvgDialog_142888_Content_22 = {
    Text = "Chiuse gli occhi, come se volesse fuggire da qualcosa che non riusciva ad affrontare. Alla fine, lasciò trasparire un sorriso sarcastico e rassegnato."
  },
  AvgDialog_142888_Content_23 = {
    Text = "Così potrei oppormi alla vostra volontà con la coscienza a posto e farvi del male senza rimorsi."
  },
  AvgDialog_142888_Content_24 = {Text = "..."},
  AvgDialog_142888_Content_25 = {
    Text = "Pontos cede in silenzio. Il carro che un tempo lo portava alla vendetta contro i suoi nemici ora porta anche Leisha nel suo cammino."
  },
  AvgDialog_142888_Content_26 = {
    Text = "Nell'istante in cui il carro, irradiante un indescrivibile bagliore perlaceo, scivolò oltre i cieli di Ebwynnos, un'espressione di sollievo apparve sul volto di Leisha. Si volta verso di voi entrambi..."
  },
  AvgDialog_142888_Content_27 = {
    Text = "Poi svanì completamente nella brezza marina notturna."
  },
  AvgDialog_142888_Content_28 = {
    Text = "Nessuno di voi aprì bocca. Vi limitaste a fissare a lungo quell'Illusione, finché Pontos non ruppe il silenzio."
  },
  AvgDialog_142888_Content_29 = {
    Text = "Com'è la vita che hai vissuto dopo aver lasciato Ebwynnos, la vita di \"Tu\"?"
  },
  AvgDialog_142888_Content_3 = {
    Text = "Ah, che dolore!"
  },
  AvgDialog_142888_Content_30 = {
    Text = "Non ti aspettavi che la sua prima frase fosse questa. Rimasesti interdetto per un momento, poi cominciasti a raccogliere quei ricordi confusi."
  },
  AvgDialog_142888_Content_31 = {
    Text = "Qualcosa sembra essere andato storto in questo Dominio. Né i ricordi di Jago né i tuoi sono del tutto intatti."
  },
  AvgDialog_142888_Content_32 = {
    Text = "…Non ricordo bene. La mia mente ora contiene sia i ricordi di essere Jago sia i ricordi di essere qualcun altro, in un luogo lontano. Tutti i ricordi sono mescolati insieme."
  },
  AvgDialog_142888_Content_33 = {
    Text = "Istintivamente infilasti la mano in tasca, cercando di accarezzare quella cavalletta di paglia."
  },
  AvgDialog_142888_Content_34 = {
    Text = "Eppure—semplice, ordinaria, frenetica, sempre le stesse routine giorno dopo giorno—era una vita felice."
  },
  AvgDialog_142888_Content_35 = {
    Text = "Abbastanza felice da farmi diventare quello che sono. Abbastanza felice che, qualunque cosa accada, voglio tornare."
  },
  AvgDialog_142888_Content_36 = {
    Text = "Ti fissa negli occhi, quieto e immobile. È quasi come il modo in cui... il modo in cui Leisha ti guardava un tempo."
  },
  AvgDialog_142888_Content_37 = {
    Text = "<Red:Non stava guardando Solo Jago.>"
  },
  AvgDialog_142888_Content_38 = {
    Text = "Vi siete sbagliati, Jago……<Red:%player%>."
  },
  AvgDialog_142888_Content_39 = {Text = "!!!???"},
  AvgDialog_142888_Content_4 = {
    Text = "Pontos è solo, immobile sul posto, non riesci a distinguere la sua Espressione."
  },
  AvgDialog_142888_Content_40 = {Text = "Cosa?!"},
  AvgDialog_142888_Content_41 = {
    Text = "Un brivido ti percorre. Come può conoscere il tuo <Red:\"nome\">? Non è forse solo un Dominio?"
  },
  AvgDialog_142888_Content_42 = {
    Text = "Scivola di nuovo in quella compostezza fredda e aristocratica, come se nulla gli fosse mai sfuggito di mano, e ti rivolge un sorriso calmo."
  },
  AvgDialog_142888_Content_43 = {
    Text = "So che <Red:\"Tu\"> sei sempre stato qui, so che <Red:\"Tu\"> sei \"lui\", fin da quando <Red:\"Tu\"> eri piccolo, ho sempre saputo che <Red:\"Tu\"> eri diverso dagli altri."
  },
  AvgDialog_142888_Content_44 = {
    Text = "Il rumore sordo e cupo dell'acqua marina ti sommerse di nuovo le orecchie."
  },
  AvgDialog_142888_Content_45 = {
    Text = "Siete ancora troppo piccoli, troppo ingenui, e credete erroneamente che quella mediocrità si chiami felicità."
  },
  AvgDialog_142888_Content_46 = {
    Text = "Questa volta, non commetterò l'<Red:errore> di lasciare di nuovo la scelta nelle tue mani."
  },
  AvgDialog_142888_Content_47 = {
    Text = "Ti sbagliavi. Non ha mai ceduto. Non lascerà andare, e non aveva mai intenzione di farlo. Ha solo posato un'esca luminosa."
  },
  AvgDialog_142888_Content_48 = {
    Text = [[
Aveva scoperto da tempo l'altra parte di "te". 
Stava per trovare "te". Non avrebbe permesso altre sorprese.]]
  },
  AvgDialog_142888_Content_49 = {
    Text = [[
Troppo facile. Quella battaglia, quella vittoria. 
Era stata una trappola per attirare <Italic:te> allo scoperto.]]
  },
  AvgDialog_142888_Content_5 = {
    Text = "Ma evidentemente, qualcosa lo aveva già abbandonato."
  },
  AvgDialog_142888_Content_50 = {
    Text = "Qualunque prezzo debba pagare, a qualunque essere debba giurare fedeltà…"
  },
  AvgDialog_142888_Content_51 = {
    Text = "Farò sì che la festa di Ebwynnos duri per sempre."
  },
  AvgDialog_142888_Content_52 = {
    Text = "Nessuno sapeva perché avesse improvvisamente permesso alla vecchiaia di prendere possesso di lui."
  },
  AvgDialog_142888_Content_53 = {
    Text = "Tutto Ebwynnos trema con lui. I medium attorno a lui e l'acqua di mare che sgorga dal suo petto si fondono insieme, indistinguibili l'uno dall'altro."
  },
  AvgDialog_142888_Content_54 = {
    Text = "Forse ci sono amici, forse nemici. Innumerevoli braccia nere emergono dal suo petto, graffiando la sua pelle, accarezzandola."
  },
  AvgDialog_142888_Content_55 = {
    Text = "Come se cercassero di fuggire. Come se anelassero a stare con lui per sempre."
  },
  AvgDialog_142888_Content_56 = {
    Text = "Sono su una strada senza ritorno. E non ne ho bisogno."
  },
  AvgDialog_142888_Content_57 = {
    Text = "Gli anni che non hai mai vissuto non significano nulla. Qui a Ebwynnos, sono docili. Controllabili. Non possono farti del male."
  },
  AvgDialog_142888_Content_58 = {
    Text = "È davvero un peccato. Non posso ancora trattenerti qui. Il nostro tempo è scaduto, <Red:%player%>."
  },
  AvgDialog_142888_Content_59 = {Text = "!!!"},
  AvgDialog_142888_Content_6 = {
    Text = "Dammi un motivo."
  },
  AvgDialog_142888_Content_60 = {
    Text = "Un'improvvisa assenza di peso ti coglie di sorpresa, strappandoti via dallo spazio squarciato. I Gaunt che oscurano il cielo spiegano le loro ali membranose e si lanciano verso di te in una morbida ondata."
  },
  AvgDialog_142888_Content_61 = {
    Text = "Non preoccuparti. Ci rivedremo presto."
  },
  AvgDialog_142888_Content_62 = {
    Text = "Ebwynnos e io aspetteremo il tuo ritorno. Per sempre."
  },
  AvgDialog_142888_Content_63 = {
    Text = "I segni del tempo si diffondono sul corpo di Pontos come erosione."
  },
  AvgDialog_142888_Content_64 = {
    Text = "Ridendo, alza il calice verso di te da Ebwynnos, che si allontana rapidamente in lontananza."
  },
  AvgDialog_142888_Content_65 = {
    Text = "Nell'ultimo sguardo prima che l'oscurità lo inghiotta, vedi due figure in piedi al suo fianco."
  },
  AvgDialog_142888_Content_66 = {
    Text = "Non lasciò andare nessuno. Li tenne tutti — fino all'ultimo."
  },
  AvgDialog_142888_Content_67 = {
    Text = "<Red:Era Leisha, insieme a un giovane Jago.>"
  },
  AvgDialog_142888_Content_68 = {Text = "..."},
  AvgDialog_142888_Content_69 = {
    Text = "Eh?! E poi, e poi? Custode, ti ha lasciato cadere a morte?!"
  },
  AvgDialog_142888_Content_7 = {
    Text = "La sua voce è rauca, ma il suo corpo rimane teso, come una bestia braccata senza via di scampo."
  },
  AvgDialog_142888_Content_70 = {
    Text = "Lo zio Pontos era così cattivo! Non può farlo a te!!"
  },
  AvgDialog_142888_Content_71 = {
    Text = "Già, come puoi essere così cattivo, Pontos!"
  },
  AvgDialog_142888_Content_72 = {
    Text = "Stai raccontando con foga ad Aurita le tue esperienze nel Sogno, quando ti giri di scatto…"
  },
  AvgDialog_142888_Content_73 = {
    Text = "E ti spaventi vedendo qualcuno che, con le mani in tasca e altrettanto curioso, se ne stava appoggiato allo stipite del Portale chissà da quanto tempo ad ascoltare."
  },
  AvgDialog_142888_Content_74 = {
    Text = "Dopo, il piccolo Jago se la cavò sano e salvo. Aprì gli occhi e si svegliò dal sogno."
  },
  AvgDialog_142888_Content_75 = {
    Text = "Si ritrovò sdraiato nel suo letto a casa, circondato dalle persone che amava."
  },
  AvgDialog_142888_Content_76 = {
    Text = "L'altro protagonista della storia si appoggia alla parete della camera da letto di Aurita e, con voce bassa e tranquilla, fornisce il finale."
  },
  AvgDialog_142888_Content_77 = {
    Text = "Ricordò tutti i ricordi della sua vita, chiuse serenamente gli occhi e andò in un luogo di felicità."
  },
  AvgDialog_142888_Content_78 = {
    Text = "Aurita emise un piccolo sospiro soddisfatto dal naso e si addormentò gradualmente in un dormiveglia, proprio come la Vera nei tuoi ricordi."
  },
  AvgDialog_142888_Content_79 = {
    Text = "Pontos inclina la testa verso la porta e fa un gesto di invito."
  },
  AvgDialog_142888_Content_8 = {
    Text = "Perché, perché anche tu vuoi andartene, perché preferisci gettarti verso la morte piuttosto che —"
  },
  AvgDialog_142888_Content_80 = {
    Text = "Immagino che tu voglia scambiare due parole con me?"
  },
  AvgDialog_142888_Content_81 = {Text = "..."},
  AvgDialog_142888_Content_82 = {
    Text = "Riuniti dopo una lunga separazione — che bella espressione."
  },
  AvgDialog_142888_Content_83 = {
    Text = "Non hai detto ad Aurita com'è andata davvero a finire. Hai mentito, vero?"
  },
  AvgDialog_142888_Content_84 = {
    Text = "Non hai mai lasciato andare Leisha. E l'unica che ha potuto lasciare Ebwynnos sono stata io, non Jago."
  },
  AvgDialog_142888_Content_85 = {
    Text = "Tagliato così bruscamente, Pontos non mostra alcun fastidio. Sorride e inarca un sopracciglio."
  },
  AvgDialog_142888_Content_86 = {
    Text = "Certo, ovviamente. Alcune storie non sono adatte ai Bambini, non è vero?"
  },
  AvgDialog_142888_Content_87 = {
    Text = "Allora immagino che questa... <Italic:apparenza> che indossi ora... sia solo per mostrare a tutti che invecchiare—l'unica cosa che ti sei perso—non significa nulla per te."
  },
  AvgDialog_142888_Content_88 = {
    Text = "Per dimostrare di avere tutto sotto controllo, eh? Il tempo. L'invecchiamento. Persino le vite degli altri..."
  },
  AvgDialog_142888_Content_89 = {
    Text = "L'ostilità nelle tue parole è probabilmente troppo evidente per passare inosservata. Pontos non risponde direttamente; ti rivolge solo un sorriso che ti fa andare su tutte le furie."
  },
  AvgDialog_142888_Content_9 = {
    Text = "E non \"Io\"."
  },
  AvgDialog_142888_Content_90 = {
    Text = "Chi può dirlo? Forse volevo semplicemente provare qualcosa di nuovo."
  },
  AvgDialog_142888_Content_91 = {
    Text = "Ad ogni modo, sono contento che tu abbia ricordato. Fin dalla prima volta che sono venuto a Mythag, attendevo questo giorno."
  },
  AvgDialog_142888_Content_92 = {
    Text = "Ebwynnos ti sta ancora aspettando, %player%."
  },
  AvgDialog_142888_Content_93 = {
    Text = "…Se hai bisogno di un promemoria, Mythag dispone di un sistema di sicurezza completo."
  },
  AvgDialog_142888_Content_94 = {
    Text = "Non essere così teso."
  },
  AvgDialog_142888_Content_95 = {
    Text = "A proposito, sono piuttosto curioso. Mio piccolo di Mythag, tu non sei più Jago. Hai una risposta per me adesso?"
  },
  AvgDialog_142888_Content_96 = {
    Text = "Pontos inclina leggermente la testa, e tu guardi nei suoi occhi blu scuro."
  },
  AvgDialog_142888_Content_97 = {
    Text = "Se ti dessi un'altra possibilità di scegliere, sceglieresti la vita eterna con l'eterna giovinezza, o i ricordi creati nel corso di una vita?"
  },
  AvgDialog_142888_Content_98 = {
    Text = "Il suono del mare, il fruscio delle ali."
  },
  AvgDialog_142888_Content_99 = {
    Text = "Il rumore bianco, familiare eppure lontano, si insinua lentamente nel corpo ancora una volta."
  },
  AvgDialog_142889_Content_1 = {
    Text = "La Cosa Migliore di Sempre"
  },
  AvgDialog_142889_Content_10 = {
    Text = "Quando sarai grande capirai. Ci rivedremo sempre. E quando saremo separati, ti penserò continuamente."
  },
  AvgDialog_142889_Content_100 = {
    Text = "Sospira. Con un sorriso del tutto naturale, finisce poi il resto della frase insieme a un'altra voce."
  },
  AvgDialog_142889_Content_101 = {
    Text = "Di cosa stai parlando? Questa è Ebwynnos. Qui non si invecchia. Festeggeremo per sempre, eternamente giovani."
  },
  AvgDialog_142889_Content_102 = {
    Text = "<Italic:Qualcuno> emerge da dietro Orney. Parla con voce bassa e rauca, come il più magnanimo e dignitoso degli anziani."
  },
  AvgDialog_142889_Content_103 = {
    Text = "Quella non è la voce di Pontos."
  },
  AvgDialog_142889_Content_104 = {
    Text = "Era così antico da spazzare via ogni senso di familiarità, lasciando Solo il Mare Profondo <Red:nelle sue profondità più remote>, mentre l'Eco delle acque lavava ancora una volta la tua coscienza."
  },
  AvgDialog_142889_Content_105 = {
    Text = "Sì, sì, questa è Ebwynnos. Sono tornato a Ebwynnos."
  },
  AvgDialog_142889_Content_106 = {
    Text = "<Shake:<Red:Faremo baldoria per sempre.>>"
  },
  AvgDialog_142889_Content_107 = {
    Text = "<Red:Saremo giovani per sempre.>"
  },
  AvgDialog_142889_Content_108 = {
    Text = "Sei così felice, così spensierato. Sei a Ebwynnos."
  },
  AvgDialog_142889_Content_109 = {
    Text = "A parte questo, tutti i pensieri irrilevanti si sono dissolti."
  },
  AvgDialog_142889_Content_11 = {
    Text = "<Red:Clic—>"
  },
  AvgDialog_142889_Content_110 = {
    Text = "Tuttavia, non sai perché, ma non hai mostrato a nessuno quella cavalletta di cui avevi dimenticato il nome."
  },
  AvgDialog_142889_Content_12 = {
    Text = "Nel momento in cui la bussola lasciò le tue mani, dalla finestra giunse un fitto susseguirsi di lievi rumori."
  },
  AvgDialog_142889_Content_13 = {
    Text = "Subito dopo, una risatina sommessa."
  },
  AvgDialog_142889_Content_14 = {
    Text = "Fammi vedere chi è questo bel giovanotto—"
  },
  AvgDialog_142889_Content_15 = {
    Text = "Con una forza invisibile e immensa, la finestra si spalancò. Nell'oscurità profonda e cacofonica, la luna argentea baluginava tra le fessure."
  },
  AvgDialog_142889_Content_16 = {
    Text = "Ciao, Jago."
  },
  AvgDialog_142889_Content_17 = {
    Text = "Quante… quante ali, nonno!!"
  },
  AvgDialog_142889_Content_18 = {
    Text = "Innumerevoli enormi ali membranose nere, che oscuravano il cielo, si riversarono verso di te. Le tue pupille tremavano mentre fissavi il centro oscuro, incapace di muoverti."
  },
  AvgDialog_142889_Content_19 = {
    Text = "<Red:Zio Pontos……>"
  },
  AvgDialog_142889_Content_2 = {
    Text = "Il ricordo finisce. Rimani in silenzio per un lungo momento."
  },
  AvgDialog_142889_Content_20 = {
    Text = "Squelch... squelch...<LightGray:*suoni viscidi di compressione>"
  },
  AvgDialog_142889_Content_21 = {
    Text = [[
La piccola mano di Vera ti stringe forte, lasciando infine solo un profondo graffio.
Avvolgere, soffocare, inghiottire.]]
  },
  AvgDialog_142889_Content_22 = {
    Text = "Sereno. Calmo. Familiare. Piacevole..."
  },
  AvgDialog_142889_Content_23 = {
    Text = "Ondate di rumore bianco hanno sommerso le tue orecchie."
  },
  AvgDialog_142889_Content_24 = {
    Text = "<Red:Caduta.>"
  },
  AvgDialog_142889_Content_25 = {Text = "..."},
  AvgDialog_142889_Content_26 = {
    Text = "Jago, svegliati. Smettila di dormire."
  },
  AvgDialog_142889_Content_27 = {
    Text = "I festeggiamenti di oggi stanno per cominciare. Tutti ti stanno aspettando."
  },
  AvgDialog_142889_Content_28 = {
    Text = "Un rumore bianco penetrante ti trafigge i timpani con un dolore acuto, e d'istinto scatti su dal letto."
  },
  AvgDialog_142889_Content_29 = {
    Text = "Te l'avevo detto che si sarebbe ripreso presto. Il mio Jago è un ragazzino davvero straordinario."
  },
  AvgDialog_142889_Content_3 = {
    Text = "Chiamala egoismo da vecchio, pensi — perché forse sei l'ultima persona che li ricorda, e non vuoi che vengano dimenticati."
  },
  AvgDialog_142889_Content_30 = {
    Text = "Pontos sorride e dà una gomitata a Leisha. Orney, Zio White e tanti volti familiari sono tutti affollati intorno al tuo letto."
  },
  AvgDialog_142889_Content_31 = {
    Text = "La tua coscienza sembra sommersa in acque profonde. Hai la fastidiosa sensazione di aver dimenticato qualcosa, e l'agilità del tuo corpo ti sembra sottilmente sbagliata."
  },
  AvgDialog_142889_Content_32 = {
    Text = "Zio Pontos, mamma? Cos'è successo? Perché sono tutti qui?"
  },
  AvgDialog_142889_Content_33 = {
    Text = "Oh, te ne sei andato in un lungo viaggio, piccolo mio, ho impiegato moltissimo tempo a trovarti."
  },
  AvgDialog_142889_Content_34 = {
    Text = "Ora ti ho riportato a casa."
  },
  AvgDialog_142889_Content_35 = {
    Text = "Il sole al tramonto squarcia le nuvole, intagliando il mare in increspature scintillanti come oro sparso riflesso sul vetro della finestra. Sei tornato nella locanda sul mare dove sei cresciuto."
  },
  AvgDialog_142889_Content_36 = {
    Text = "Ah, giusto. Questo posto è... @4"
  },
  AvgDialog_142889_Content_37 = {Text = "??!!!"},
  AvgDialog_142889_Content_39 = {
    Text = "Un dolore pulsante, una pressione incalzante—il nome della città resta sulla punta della lingua."
  },
  AvgDialog_142889_Content_4 = {
    Text = "Guardi Vera con tenerezza. La tua famiglia, premurosa, vi ha lasciati soli così da non farti stancare."
  },
  AvgDialog_142889_Content_40 = {
    Text = "Un fragore stridulo come ferro che graffia il vetro si abbatte dall'interno del tuo cranio giù nella gola, trasformando il tuo cervello in una pasta densa e viscosa."
  },
  AvgDialog_142889_Content_41 = {
    Text = "Finché quel palmo caldo e ruvido non ti sorregge la nuca, e come sempre, lui ride e preme la sua fronte contro la tua."
  },
  AvgDialog_142889_Content_42 = {
    Text = "Ehi, torna da me. Cosa c'è che non va?"
  },
  AvgDialog_142889_Content_43 = {
    Text = "Apri lentamente la bocca, cercando a tentoni la tua voce."
  },
  AvgDialog_142889_Content_44 = {
    Text = "Pontos ti osserva intensamente, e non capisci—il modo in cui ti guarda, è il modo in cui si guarda qualcosa che si credeva perduto per sempre."
  },
  AvgDialog_142889_Content_45 = {
    Text = "Come si guarda la cosa più preziosa del mondo."
  },
  AvgDialog_142889_Content_46 = {
    Text = "Bentornato a Ebwynnos, Jago."
  },
  AvgDialog_142889_Content_47 = {
    Text = "La coscienza torna a fluire. Fissi tutte le cose familiari intorno a te, la luce del sole che cuoce le assi del pavimento finché non sudano granelli di sale..."
  },
  AvgDialog_142889_Content_48 = {
    Text = "Una strana, serena felicità soffoca ogni altro pensiero. Un sorriso affiora lentamente sul tuo volto."
  },
  AvgDialog_142889_Content_49 = {
    Text = "Ora ricordo. Ebwynnos. Questa è Ebwynnos—il posto dove sono cresciuto..."
  },
  AvgDialog_142889_Content_5 = {
    Text = "Non rividi mai più la mamma né lo zio Pontos. Se non fosse per questa bussola, probabilmente penserei che fu tutta un'allucinazione causata dall'esplosione."
  },
  AvgDialog_142889_Content_50 = {
    Text = "Esatto. È da tanto che non ci vediamo!"
  },
  AvgDialog_142889_Content_51 = {
    Text = "Sei finalmente tornato a casa, Jago."
  },
  AvgDialog_142889_Content_52 = {Text = "..."},
  AvgDialog_142889_Content_53 = {
    Text = "I tuoi pensieri sembrano immersi in uno sciroppo chiamato felicità. Tutti intorno a te appaiono giovani come quando vi siete separati..."
  },
  AvgDialog_142889_Content_54 = {
    Text = "Oh... separati."
  },
  AvgDialog_142889_Content_55 = {
    Text = "Quando hai lasciato Ebwynnos, e come sei tornato? Sembra che non molto tempo fa fossi disteso in un altro letto. Hai una nipote, di nome…"
  },
  AvgDialog_142889_Content_56 = {
    Text = "A cosa stai pensando, piccolo?"
  },
  AvgDialog_142889_Content_57 = {
    Text = "Pontos era appoggiato alla finestra, il sole al tramonto già immerso nel mare, i suoi ultimi raggi di luce nascosti dietro di lui."
  },
  AvgDialog_142889_Content_58 = {
    Text = "Zio Pontos, sento di aver dimenticato qualcosa di molto importante. Cos'era…"
  },
  AvgDialog_142889_Content_59 = {
    Text = "Ahahah, se per ora non riesci a ricordarlo, vuol dire che non è così importante. Non avere fretta, a Ebwynnos abbiamo tutto il tempo del mondo."
  },
  AvgDialog_142889_Content_6 = {
    Text = "Quindi, Vera, è per questo che il nonno voleva raccontarti questa storia."
  },
  AvgDialog_142889_Content_60 = {
    Text = "Dai! Sei ancora giovane, hai tanti bei momenti davanti a te, certo che devi usarli per far festa."
  },
  AvgDialog_142889_Content_61 = {
    Text = "Ti mise un braccio intorno alle spalle e si diresse verso la sala appena decorata al piano di sotto, dove la folla festante vi trascinò insieme sulla pista da ballo."
  },
  AvgDialog_142889_Content_62 = {
    Text = "Solo ora noti che la locanda è diventata una sala di abbagliante splendore."
  },
  AvgDialog_142889_Content_63 = {
    Text = "Volti familiari ridono attraverso la pista da ballo, alzando i loro calici e salutandoti con la mano, tazze di legno e di vetro che si scontrano in un clamore sparso."
  },
  AvgDialog_142889_Content_64 = {
    Text = "Sono ancora giovane, sono ancora… giovane?"
  },
  AvgDialog_142889_Content_65 = {
    Text = "Un pesante capogiro ti travolge di nuovo. Quella strana felicità ti stringe forte, senza lasciarti andare."
  },
  AvgDialog_142889_Content_66 = {
    Text = "Alzi il braccio e vedi due mani giovani e forti;"
  },
  AvgDialog_142889_Content_67 = {
    Text = "guardi il vetro, e il volto di un giovane porta la stessa risata di tutti gli altri."
  },
  AvgDialog_142889_Content_68 = {
    Text = "Amici, alziamo i nostri calici—a Ebwynnos!"
  },
  AvgDialog_142889_Content_69 = {
    Text = "Prima che tu possa raccoglierti, Pontos si sporge oltre la tua spalla e alza il calice verso la folla."
  },
  AvgDialog_142889_Content_7 = {
    Text = "Forse stanno ancora volando da qualche parte nel cielo notturno. E se un giorno dovessi sparire, forse sono venuti a prendermi."
  },
  AvgDialog_142889_Content_70 = {
    Text = "A Ebwynnos!"
  },
  AvgDialog_142889_Content_71 = {
    Text = "In una gioia confusa e immensa alzi il calice insieme agli altri, e il fragore della folla ti trascina sempre più al centro della marea umana."
  },
  AvgDialog_142889_Content_72 = {
    Text = "Festeggi, balli, bevi senza freni."
  },
  AvgDialog_142889_Content_73 = {
    Text = "Le travi di luce della grande casa trafiggono la nebbia che si alza dal mare, scintillando per tutta la notte."
  },
  AvgDialog_142889_Content_74 = {
    Text = "Solo quando una debole luce pallida apparve all'orizzonte e le persone crollarono le une sulle altre nel sonno, tu, leggermente brillo, canticchiasti una canzone e ti adagiasti sui cuscini foderati di velluto."
  },
  AvgDialog_142889_Content_75 = {Text = "..."},
  AvgDialog_142889_Content_76 = {
    Text = "Stai quasi per appisolarti quando improvvisamente vedi il volto di Leisha in un angolo della sala. Ti affretti verso di lei."
  },
  AvgDialog_142889_Content_77 = {
    Text = "Mamma! Aspettami, dove sei andata? Non ti ho vista per tutta la sera."
  },
  AvgDialog_142889_Content_78 = {
    Text = "Un panico inspiegabile ti stringe il cuore, e non puoi fare a meno di mormorare tra te e te."
  },
  AvgDialog_142889_Content_79 = {
    Text = "Che strano—non ero appena via per un viaggio? Perché sembra che non ci vediamo da così tanto tempo?"
  },
  AvgDialog_142889_Content_8 = {
    Text = "Ma... non voglio stare lontana dal nonno. Puoi portarmi con te?"
  },
  AvgDialog_142889_Content_80 = {
    Text = "I tuoi passi si arrestarono bruscamente—a causa dell'espressione di totale impotenza e dolore sul volto di Leisha."
  },
  AvgDialog_142889_Content_81 = {
    Text = "Ti ha trovato. Mio povero Jago, non saresti mai dovuto venire qui."
  },
  AvgDialog_142889_Content_82 = {
    Text = "Pensa, in fretta—finché non hai ancora dimenticato. Ricorda che tipo di vita hai vissuto."
  },
  AvgDialog_142889_Content_83 = {
    Text = "Le lacrime della Madre caddero sulla tua mano, così fredde che ti ritraesti istintivamente. L'aria gelida ti fece percorrere brividi per tutto il corpo in un istante."
  },
  AvgDialog_142889_Content_84 = {
    Text = "Guarda le persone intorno a te. Guardami. Guarda ciò che dovremmo essere."
  },
  AvgDialog_142889_Content_85 = {
    Text = "Metti la mano in tasca, Jago."
  },
  AvgDialog_142889_Content_86 = {
    Text = "Goffa, rozza, un po' pungente — lì c'era una <Red:cavalletta>."
  },
  AvgDialog_142889_Content_87 = {
    Text = "Una cavalletta fatta da <Red:Vera>, chiamata <Red:Vera>."
  },
  AvgDialog_142889_Content_88 = {
    Text = "<Shake:<Red:Vera>... no, l'ho già... è passato tanto tempo...>"
  },
  AvgDialog_142889_Content_89 = {
    Text = "<Shake:Sto morendo, sono a letto, avevo degli amici, avevo l'amore della mia vita, avevo dei figli, ero...>"
  },
  AvgDialog_142889_Content_9 = {
    Text = "Non riesci a trattenere un sorriso, estrai dal petto quella bussola che non ti ha mai lasciato per decenni e la metti nel palmo di Vera."
  },
  AvgDialog_142889_Content_90 = {
    Text = "Tutto intorno a te gira in un caos disordinato, due flussi di pensiero completamente diversi si intrecciano tra loro."
  },
  AvgDialog_142889_Content_91 = {
    Text = "Ti stringi la testa tra le mani, piegandoti in due per il dolore, ansimando."
  },
  AvgDialog_142889_Content_92 = {
    Text = "Santo cielo, Jago, cosa ti succede? Hai un aspetto terribile!"
  },
  AvgDialog_142889_Content_93 = {
    Text = "Orney ti travolge all'improvviso dal nulla, e il ronzio nelle tue orecchie svanisce di colpo."
  },
  AvgDialog_142889_Content_94 = {
    Text = "Alzi lo sguardo, e Leisha è già sparita."
  },
  AvgDialog_142889_Content_95 = {
    Text = "Orney, Orney, no, no, ora ricordo!"
  },
  AvgDialog_142889_Content_96 = {
    Text = "Siamo cresciuti insieme, vero? Ero alla tua laurea, al tuo matrimonio. Non dovresti essere così giovane! Abbiamo la stessa età, siamo invecchiati entrambi..."
  },
  AvgDialog_142889_Content_97 = {
    Text = "Orney ti fissa con un'espressione che non riconosci affatto, e ti fissa per un lungo, lunghissimo tempo, finché quasi vorresti fuggire."
  },
  AvgDialog_142889_Content_98 = {Text = "Allora..."},
  AvgDialog_142889_Content_99 = {
    Text = "Ah, Jago…"
  },
  AvgDialog_142890_Content_1 = {Text = "Lei e Lui"},
  AvgDialog_142890_Content_10 = {
    Text = "Grazie per il tuo Dono, zio Pontos, ma…"
  },
  AvgDialog_142890_Content_11 = {
    Text = "Deve essere stata una vita molto lunga e preziosa; per questo sono disposto a rinunciare alla giovinezza eterna e alla Vita."
  },
  AvgDialog_142890_Content_12 = {
    Text = "Le persone smettono di parlare. All'unisono, tutti si voltano a guardarti."
  },
  AvgDialog_142890_Content_13 = {
    Text = "I timpani dolgono come se stessero per scoppiare, e il suono dell'acqua di mare che si muove ti trapana il cranio."
  },
  AvgDialog_142890_Content_14 = {
    Text = "Attraverso le acque pesanti del mare, odi un sospiro."
  },
  AvgDialog_142890_Content_15 = {
    Text = "<Red:Di nuovo così.>"
  },
  AvgDialog_142890_Content_16 = {
    Text = "<Shake:<Red:Scric… mh, gugu, gu…>>"
  },
  AvgDialog_142890_Content_17 = {
    Text = "Le quattro pareti tremano, tutto cola in un muco umido e viscoso."
  },
  AvgDialog_142890_Content_18 = {
    Text = "Anche dopo averti separato da lui, la vecchiaia ti fa dire queste <Red:stupidaggini da debole>, proprio come Leisha."
  },
  AvgDialog_142890_Content_19 = {
    Text = "Sentisti all'improvviso che lui <Red:non era più> Pontos."
  },
  AvgDialog_142890_Content_2 = {
    Text = "Guardando quella mano familiare e calda, alla fine — fai un passo indietro."
  },
  AvgDialog_142890_Content_20 = {
    Text = "Così antico da essere stato dimenticato, una Paura profonda e gelida, immensa, maestosa e impossibile da Sguardo ti paralizzò sul posto strappandoti un <Red:urlo> silenzioso."
  },
  AvgDialog_142890_Content_22 = {
    Text = "Ricordasti — quel suono di quando arrivasti a Ebwynnos, quando lasciasti Ebwynnos, quando tornasti a Ebwynnos."
  },
  AvgDialog_142890_Content_23 = {
    Text = "Pelle, costole, che si staccavano verso l'esterno, si dispiegavano, e poi…"
  },
  AvgDialog_142890_Content_24 = {
    Text = [[
Nulla, innumerevoli mani, nulla, nulla, nulla, nulla, nulla, @2y@2, @4@4@2@4
@3@2@4@3@1@3@3!!!!!!]]
  },
  AvgDialog_142890_Content_25 = {
    Text = "Resta qui, resta a Ebwynnos."
  },
  AvgDialog_142890_Content_26 = {
    Text = "<Change>Ascolta l'abisso, gettati nell'abisso."
  },
  AvgDialog_142890_Content_27 = {Text = "Luna."},
  AvgDialog_142890_Content_28 = {
    Text = "La Luna splendente, appesa lontana nel cielo lontano."
  },
  AvgDialog_142890_Content_29 = {
    Text = [[
Le sue costole la sua pelle le sue braccia il suo petto il suo abbraccio
Il suo abbraccio il suo abbraccio il suo abbraccio il suo abbraccio il suo abbraccio
Il suo abbraccio il suo abbraccio il suo abbraccio il suo abbraccio il suo abbraccio
Eb@3@4wyn@3@2nos
Ebwy@4@3@2n@4@3@2nos
Il suo abbraccio le sue costole la sua pelle le sue braccia il suo petto
Per sempre per sempre per sempre per sempre per sempre per sempre per sempre
Per sempreper sempre per sempre per sempre per sempre per sempre per sempre <Red:Ebwynnos>]]
  },
  AvgDialog_142890_Content_3 = {
    Text = "…C'è, invece."
  },
  AvgDialog_142890_Content_30 = {
    Text = "<Red:Ebwynnos che viene tra le sue braccia.>"
  },
  AvgDialog_142890_Content_31 = {
    Text = "Ali su ali, che avvolgono un abbraccio stretto, solido, irresistibile, e un inghiottimento totale."
  },
  AvgDialog_142890_Content_32 = {
    Text = "Sei spinta, sei avvolta, sei accolta, stai cadendo in una quiete infinita."
  },
  AvgDialog_142890_Content_33 = {Text = "Basta!"},
  AvgDialog_142890_Content_34 = {
    Text = "Una figura si fece strada con forza attraverso la folla gelida e ignara, irrompendo nel vortice di <Red:\"Pontos\">."
  },
  AvgDialog_142890_Content_35 = {
    Text = "Senza causare alcun Danno, ma con uno stupore così evidente da far tremare le pupille di <Red:\"Pontos\">, che fissò intensamente Il Volto di lei."
  },
  AvgDialog_142890_Content_36 = {
    Text = "Ho sempre creduto… di aver rimodellato soltanto un Guscio vuoto."
  },
  AvgDialog_142890_Content_37 = {
    Text = "Proprio come le cose che Jago ha dimenticato ma che continuano a influenzarlo, anche una parte di me esiste ancora."
  },
  AvgDialog_142890_Content_38 = {
    Text = "Lascialo andare, Pontos, lui non appartiene a questo posto."
  },
  AvgDialog_142890_Content_39 = {
    Text = "Oh, Leisha."
  },
  AvgDialog_142890_Content_4 = {Text = "Cosa?"},
  AvgDialog_142890_Content_40 = {
    Text = "Lo amo, come lo ami tu."
  },
  AvgDialog_142890_Content_41 = {
    Text = "Orney, Bianco."
  },
  AvgDialog_142890_Content_42 = {
    Text = "Tutta la gente di Ebwynnos."
  },
  AvgDialog_142890_Content_43 = {
    Text = "In silenzio, insieme agli incubi, si avvicinano a te come un muro che incalza e schiaccia."
  },
  AvgDialog_142890_Content_44 = {
    Text = "No, no no no! No!!"
  },
  AvgDialog_142890_Content_45 = {
    Text = "Leisha ti guarda, guarda Jago, e guarda anche… te."
  },
  AvgDialog_142890_Content_46 = {
    Text = "So perché li vuoi così tanto, lì non c'è solo Jago, non c'è solo un'anima."
  },
  AvgDialog_142890_Content_47 = {
    Text = "Ah… dimenticheranno tutto, rimarranno qui."
  },
  AvgDialog_142890_Content_48 = {
    Text = "Leisha è intrappolata ancora una volta. Torce il corpo con tutta la sua forza e ti fissa—non il tuo viso, ma attraverso di esso, come se cercasse di vedere nella parte più profonda della tua anima."
  },
  AvgDialog_142890_Content_49 = {
    Text = "Ti prego. Chiunque tu sia—so che sei lì dentro. Riporta Jago indietro. \nRiportalo alla vita che eravate destinati a vivere!"
  },
  AvgDialog_142890_Content_5 = {
    Text = "Come se non avesse capito la tua domanda, aggrottò leggermente le sopracciglia con incredulità."
  },
  AvgDialog_142890_Content_50 = {
    Text = "Fitte membrane nere si dispiegano, tutto è così silenzioso, così… affascinante, sei quasi sul punto di avvicinarti a Loro."
  },
  AvgDialog_142890_Content_51 = {
    Text = "Poi, sentisti… la voce di <Red:\"Tu\">."
  },
  AvgDialog_142890_Content_52 = {
    Text = "Credo che <Red:\"Io\"> abbia già fatto la mia scelta."
  },
  AvgDialog_142890_Content_53 = {
    Text = "Dal profondo del mare della coscienza, uno spirito lotta per emergere."
  },
  AvgDialog_142890_Content_54 = {
    Text = "Sopravvissuto alla grande esplosione di Akut, \"Tu\", in quanto <Red:\"Custode di Mythag\">, prendesti il controllo di questo corpo."
  },
  AvgDialog_142890_Content_55 = {
    Text = "Una radiosità d'Argento tremolò nel tuo palmo."
  },
  AvgDialog_142890_Content_56 = {
    Text = "I ricordi sparsi di Jago vengono raccolti, pezzo per pezzo."
  },
  AvgDialog_142890_Content_57 = {
    Text = "Sai, zio Pontos... la prima cosa che ho appena ricordato era qualcosa di così piccolo. Qualcosa che non avrebbe dovuto avere alcuna importanza."
  },
  AvgDialog_142890_Content_58 = {Text = "..."},
  AvgDialog_142890_Content_59 = {
    Text = "\"Pontos\" non parla. Ti studia in silenzio."
  },
  AvgDialog_142890_Content_6 = {
    Text = "Hanno un significato, quei ricordi."
  },
  AvgDialog_142890_Content_60 = {
    Text = "Quando \"Io\" compii diciotto anni, Orney e io ci infilammo di nascosto sul piroscafo più vicino e supplicammo i marinai di lasciarci lavorare nel ponte inferiore in cambio del passaggio. Una crociera gratuita, così, senza tante storie."
  },
  AvgDialog_142890_Content_61 = {
    Text = "La mattina seguente, vedemmo il più bel sorgere del sole che avessimo mai visto. Orney disse che avrebbe voluto che il sole non tramontasse mai. Ma io no."
  },
  AvgDialog_142890_Content_62 = {
    Text = "Perché il sole tramonta. Perché ogni giorno finisce. È questo che dà significato alle cose che viviamo."
  },
  AvgDialog_142890_Content_63 = {
    Text = "Basta con queste sciocchezze. A Ebwynnos, posso far sorgere e tramontare il sole a tuo piacimento, se è questo che desideri."
  },
  AvgDialog_142890_Content_64 = {
    Text = "Chiude gli occhi, stanco, la sua pazienza finalmente esaurita. Scuoti la testa con fermezza."
  },
  AvgDialog_142890_Content_65 = {
    Text = "Ciò che conta è il tempo che viviamo. Non un sole che rimane lì per sempre."
  },
  AvgDialog_142890_Content_66 = {
    Text = "Scusa, Pontos."
  },
  AvgDialog_142890_Content_67 = {
    Text = "Alza la mano. Il muro di Gaunt si stringe intorno a te."
  },
  AvgDialog_142890_Content_68 = {
    Text = "Andate, servitori."
  },
  AvgDialog_142890_Content_7 = {
    Text = "Non per gli altri, ma per me stesso."
  },
  AvgDialog_142890_Content_8 = {
    Text = "Voglio sapere che tipo di vita ho vissuto, e perché, dopo aver perso la memoria, qualsiasi gioia mi lasci con un senso di vuoto."
  },
  AvgDialog_142890_Content_9 = {
    Text = "Le spine della cavalletta ti pungono leggermente la punta delle dita, e senza sapere perché ti viene in mente l'immagine di quel bambino che piangeva accanto al letto."
  },
  AvgDialog_142891_Content_1 = {
    Text = "Segreto di Famiglia"
  },
  AvgDialog_142891_Content_10 = {
    Text = "Si chiama — uhm, si chiama Vera, perché Vera è il nome che ha scelto il nonno, ed è il nome più bello."
  },
  AvgDialog_142891_Content_100 = {
    Text = "La Sua ira vi brucerà, Solo la Gioia può… @1!"
  },
  AvgDialog_142891_Content_101 = {Text = "Pfft."},
  AvgDialog_142891_Content_102 = {
    Text = "Schizzi di sangue, e tu fissasti, sbalordito, Leisha e alcuni degli habitué della locanda combattere in groppa alle stesse creature su cui avevate cavalcato."
  },
  AvgDialog_142891_Content_103 = {
    Text = "Perché mai queste cose Maledette sono venute fin qui…\nVabbè, questo dovrebbe essere l'ultimo."
  },
  AvgDialog_142891_Content_104 = {
    Text = "Speriamo che stiano solo passando…"
  },
  AvgDialog_142891_Content_105 = {
    Text = "Leisha e i suoi compagni se ne andarono. Tu e Pontos rimaneste nell'ombra. Ti saresti accasciato a terra se lui non ti avesse sorretto per le spalle."
  },
  AvgDialog_142891_Content_106 = {
    Text = "Ti aggrappasti all'orlo dei suoi abiti. La sua voce era calma e dolce, come se stesse facendo del suo meglio per non spaventarti ulteriormente."
  },
  AvgDialog_142891_Content_107 = {
    Text = "Jago, è proprio come quello che hai visto... quelle creature che ci hanno portato qui poco fa si chiamano Gaunt. Le guidiamo a combattere per noi."
  },
  AvgDialog_142891_Content_108 = {
    Text = "Si fermò, con la mano appoggiata al fianco del Gaunt, facendo schioccare le nocche, come se stesse esitando su come spiegare."
  },
  AvgDialog_142891_Content_109 = {
    Text = "Beh, siamo gli eroi di una storia d'avventura — il tipo che addomestica i draghi, solo che noi addomestichiamo questi Gaunt."
  },
  AvgDialog_142891_Content_11 = {
    Text = "Vera… Il nonno ha bisogno di Riposo, vieni dal papà."
  },
  AvgDialog_142891_Content_110 = {
    Text = "C-cosa... Di cosa stai parlando, zio Pontos?! La nostra famiglia gestisce solo una locanda..."
  },
  AvgDialog_142891_Content_111 = {
    Text = "Dopo... dopo l'incidente, eravamo rimasti in pochi. Leisha ha fatto molto per tutti, e le persone si sono appoggiate a lei."
  },
  AvgDialog_142891_Content_112 = {
    Text = "Ma lei non voleva che noi, specialmente tu, avessimo nulla a che fare con tutto questo. Questa vita tranquilla e senza nome è esattamente quella che voleva per noi."
  },
  AvgDialog_142891_Content_113 = {
    Text = "Ma ci sono ancora così tante cose malvagie e brutte là fuori in questo mondo, proprio come quelle che hai visto oggi. Non capisco..."
  },
  AvgDialog_142891_Content_114 = {
    Text = "Un lampo di frustrazione attraversò il volto di Pontos — raro per lui — e si passò i capelli dorati e sciolti dalla fronte verso la nuca."
  },
  AvgDialog_142891_Content_115 = {
    Text = "Ultimamente, i Gaunt mi hanno trovato. E posso sentire qualcosa di molto più potente dietro di loro. Lui mi ha scelto, Lui mi sta chiamando."
  },
  AvgDialog_142891_Content_116 = {
    Text = "Potrei fare molto di più. Ma Leisha pensa che finché ci nascondiamo bene, andrà tutto bene."
  },
  AvgDialog_142891_Content_117 = {
    Text = "Il peso di tutto ciò ti lasciò a sbattere le palpebre nel vuoto. Per la prima volta, capivi ogni singola parola eppure non riuscivi a dare senso a nessuna di esse messe insieme."
  },
  AvgDialog_142891_Content_118 = {
    Text = "Pontos sembrò riscuotersi, tornò al momento presente e ti rivolse un sorriso."
  },
  AvgDialog_142891_Content_119 = {
    Text = "Scusa, Jago. Ti ho scaricato addosso troppo tutto in una volta?"
  },
  AvgDialog_142891_Content_12 = {
    Text = "Tuo figlio è un po' preoccupato per la tua salute e vuole portare via la nipotina; lei fa il broncio, sul punto di scoppiare a piangere."
  },
  AvgDialog_142891_Content_120 = {
    Text = "Torniamo prima che Leisha scopra che siamo sgattaiolati via. Avremo tutto il tempo del mondo per parlarne."
  },
  AvgDialog_142891_Content_121 = {
    Text = "In lontananza, Leisha sembrò guardarti. Lo zio Pontos ti fece di nuovo il gesto di <Italic:silenzio>."
  },
  AvgDialog_142891_Content_122 = {Text = "..."},
  AvgDialog_142891_Content_123 = {
    Text = "La finestra si aprì e si richiuse, senza fare alcun rumore."
  },
  AvgDialog_142891_Content_124 = {
    Text = "Come se il vento avesse semplicemente spalancato la finestra. Fuori, le onde si infrangevano e si ritiravano. Sentisti il suono di Leisha che saliva le scale dal piano di sotto."
  },
  AvgDialog_142891_Content_125 = {
    Text = "Affondate i volti nei cuscini con il respiro regolare, fingendo che sia ancora una notte qualunque."
  },
  AvgDialog_142891_Content_13 = {
    Text = "Sorridi tossendo qualche volta, fai forza per sollevare queste ossa Fragili, appoggiandoti alla testiera del letto."
  },
  AvgDialog_142891_Content_14 = {
    Text = "Vera, non piangere. Il chiaro di luna là fuori è così bello, abbassa un po' la luce."
  },
  AvgDialog_142891_Content_15 = {
    Text = "Il nonno ha ancora tempo per raccontarti una storia, fammi pensare…"
  },
  AvgDialog_142891_Content_16 = {
    Text = "Il tuo sguardo cade sulla bussola di ottone che non ti ha mai lasciato. Intatta dagli anni, porta un morbido bordo argentato nel chiaro di luna."
  },
  AvgDialog_142891_Content_17 = {
    Text = "Passi lentamente il pollice sulla sua superficie, colmo di nostalgia, e la tua voce si fa rauca mentre sproffondi nei ricordi."
  },
  AvgDialog_142891_Content_18 = {
    Text = "Era… più di sessant'anni fa, quando ero ancora un bambino."
  },
  AvgDialog_142891_Content_19 = {
    Text = "Leisha, la nave sta per lasciare il porto. Non è ancora tornato?"
  },
  AvgDialog_142891_Content_2 = {Text = "Luna."},
  AvgDialog_142891_Content_20 = {
    Text = "Sembra che davvero non potremo salutarci di persona. Per favore, accetta almeno questa spilla…"
  },
  AvgDialog_142891_Content_21 = {
    Text = "Il fischio del porto risuonò. I proprietari dei ninnoli lasciati indietro depositarono un tintinnante mucchio di gioielli personali, i volti pieni di rammarico mentre tornavano alla nave."
  },
  AvgDialog_142891_Content_22 = {
    Text = "Cielo, per amor di @3, cara, quando imparerà finalmente tuo zio a non avere così tanti \"amici\"?"
  },
  AvgDialog_142891_Content_23 = {
    Text = "Tua madre Leisha ti guardò con un'espressione al tempo stesso divertita e rassegnata, sospirò e infilò i gioielli nella piccola scatola che sarebbe stata restituita al capitano per la consegna al prossimo attracco della nave."
  },
  AvgDialog_142891_Content_24 = {
    Text = "La tua famiglia gestiva una piccola locanda perfettamente ordinaria in una cittadina sul mare. Solo una cosa era leggermente speciale…"
  },
  AvgDialog_142891_Content_25 = {
    Text = "Fammi vedere chi è questo bel giovanotto—"
  },
  AvgDialog_142891_Content_26 = {
    Text = "Il grande portale si spalanca di nuovo portando con sé un Vento salato, e quella \"cosa speciale\" ride fragorosamente afferrandoti in vita e facendoti roteare in aria."
  },
  AvgDialog_142891_Content_27 = {
    Text = "Pontos! Quante volte te l'ho detto, gli strapperai le braccia!"
  },
  AvgDialog_142891_Content_28 = {
    Text = "Zio Pontos!"
  },
  AvgDialog_142891_Content_29 = {
    Text = "Ehi, piccolo Jago, guarda cosa ti ho portato!"
  },
  AvgDialog_142891_Content_3 = {
    Text = "La luna piena più luminosa che tu abbia mai visto è appesa nel cielo. I tuoi arti sono privi di forza, e anche i tuoi pensieri sono un po' appannati."
  },
  AvgDialog_142891_Content_30 = {
    Text = "Schioccò le dita, aprì la mano in aria, e una pesante bussola placcata in rame ti cadde nel palmo."
  },
  AvgDialog_142891_Content_31 = {
    Text = "Spero che tu l'abbia ottenuto onestamente. Questa casa non può contenere altri \"pegni d'amore\" e \"cuori spezzati\"."
  },
  AvgDialog_142891_Content_32 = {
    Text = "Leisha gli lanciò indietro la scatola di gioielli con un sorriso beffardo e indicò con il mento verso la finestra, da cui la nave che trasportava l'altra metà di quei \"cuori spezzati\" aveva appena lasciato il porto."
  },
  AvgDialog_142891_Content_33 = {
    Text = "Dai, su... mi conosci. Non sono mai stato bravo a dire di no."
  },
  AvgDialog_142891_Content_34 = {
    Text = "Ridendo, Pontos inclinò la testa e schivò uno schiaffo deciso di Leisha, poi ti posò a terra."
  },
  AvgDialog_142891_Content_35 = {
    Text = "A proposito, ho fatto nuove amicizie. Dobbiamo parlare, Leisha."
  },
  AvgDialog_142891_Content_36 = {
    Text = "Di quelle cose di cui non vuoi parlare."
  },
  AvgDialog_142891_Content_37 = {
    Text = "Troppo impegnato a studiare il tuo nuovo tesoro, non notasti l'espressione che si oscurava sul volto di Leisha. Pontos ti scompigliò i capelli."
  },
  AvgDialog_142891_Content_38 = {
    Text = "Tua madre ed io abbiamo alcune cose di cui discutere. Se il mio giovane preferito è disposto ad andare a giocare di sopra per un po', gli racconterò meravigliosi racconti dei miei viaggi. Affare fatto?"
  },
  AvgDialog_142891_Content_39 = {
    Text = "Tese la mano, e per amor della bussola tu la stringesti—è la \"Stretta dell'Accordo\" che apparteneva solo a voi due."
  },
  AvgDialog_142891_Content_4 = {
    Text = "Alzi la mano, e le rughe che simboleggiano la vecchiaia hanno già invaso la tua pelle."
  },
  AvgDialog_142891_Content_40 = {Text = "..."},
  AvgDialog_142891_Content_41 = {
    Text = "Sdraiato sul pavimento della camera da letto al piano di sopra, tirasti fuori una mappa e ti mettesti, in profonda concentrazione, a usare la bussola per trovare i punti cardinali di quei racconti marinari."
  },
  AvgDialog_142891_Content_42 = {
    Text = "Tuttavia, questa casa era troppo vecchia, e il Mare Profondo e il vento la logoravano costantemente. Qualche parola sparsa riusciva ancora a filtrare attraverso le fessure delle assi del pavimento."
  },
  AvgDialog_142891_Content_43 = {
    Text = "…già… dire… non puoi solo… nascondersi non è una soluzione."
  },
  AvgDialog_142891_Content_44 = {
    Text = "...Quelle <Italic:creature>... posso... Il mio talento..."
  },
  AvgDialog_142891_Content_45 = {
    Text = "Il tono dello zio Pontos si fece sempre più urgente. Proprio mentre stavi per avvicinare l'orecchio per curiosità—"
  },
  AvgDialog_142891_Content_46 = {
    Text = "CRASH! TONF!"
  },
  AvgDialog_142891_Content_47 = {
    Text = "Il Portale fu spalancato con un colpo secco, Pontos fu trascinato per il colletto e scaraventato dentro, mentre Leisha assunse un'Espressione severa che significava \"non si discute\"."
  },
  AvgDialog_142891_Content_48 = {
    Text = "Non sono d'accordo, Pontos. Il mio unico desiderio è che tutti voi restiate al sicuro e in vita… Stai lontano da quei tuoi nuovi amici."
  },
  AvgDialog_142891_Content_49 = {
    Text = "Se le cose dovessero davvero sfuggire di mano, vi porterò tutti via da qui."
  },
  AvgDialog_142891_Content_5 = {
    Text = "Ah, quindi sono già arrivato a quest'età… Forse questa è l'ultima notte."
  },
  AvgDialog_142891_Content_50 = {
    Text = "Ehi, Leisha, non sono più un bambino! Non possiamo continuare a scappare per sempre."
  },
  AvgDialog_142891_Content_51 = {
    Text = "Prima impara ad aiutarmi a gestire gli affari. Smettila di vagabondare fuori tutto il giorno prima di parlare di queste cose."
  },
  AvgDialog_142891_Content_52 = {
    Text = "Raramente avevi sentito Leisha parlare con tanta durezza. Fece un respiro profondo e riuscì a regalarti un sorriso forzato."
  },
  AvgDialog_142891_Content_53 = {
    Text = "Jago, fai un favore alla mamma. Tieni d'occhio tuo zio, almeno stanotte non lasciarlo andare in giro a zonzo."
  },
  AvgDialog_142891_Content_54 = {
    Text = "Lasciò quelle parole dietro di sé e scese di fretta al piano di sotto verso i registri che non sembravano mai finire, come se fosse ansiosa di chiudere la conversazione il prima possibile."
  },
  AvgDialog_142891_Content_55 = {
    Text = "Pontos alzò un sopracciglio e ti fece un'alzata di spalle."
  },
  AvgDialog_142891_Content_56 = {
    Text = "Bene allora, Jago, sembra che possiamo anticipare un po' l'ora delle storie."
  },
  AvgDialog_142891_Content_57 = {Text = "..."},
  AvgDialog_142891_Content_58 = {
    Text = "Forse quei racconti che rotolavano fuori dalle cabine delle navi insieme al carico erano troppo avvincenti e fantastici. Anche a mezzanotte, non dormivi profondamente."
  },
  AvgDialog_142891_Content_59 = {
    Text = "Il chiaro di luna fuori dalla finestra gettava un velo argentato sulle tue palpebre. Qualcosa lo bloccò."
  },
  AvgDialog_142891_Content_6 = {
    Text = "I ricordi tornano gradualmente, ma stranamente, non c'è Paura della morte nel tuo cuore. Al contrario, sorridi per una profonda pace interiore."
  },
  AvgDialog_142891_Content_60 = {
    Text = "Un clic—il fermo della finestra. Apristi gli occhi. La finestra era già stata spalancata."
  },
  AvgDialog_142891_Content_61 = {Text = "!"},
  AvgDialog_142891_Content_62 = {
    Text = "Zio Pontos, non puoi uscire dalla finestra! La mamma si arrabbierà!"
  },
  AvgDialog_142891_Content_63 = {
    Text = "Pontos era già per metà fuori dal davanzale, e Tu senza pensarci ti slanci per abbracciarlo, dimenticando persino di chiederti perché sembrava… sospeso in aria."
  },
  AvgDialog_142891_Content_64 = {
    Text = "Aspetta, attento!"
  },
  AvgDialog_142891_Content_65 = {
    Text = "Arriva la sensazione di assenza di peso, e poi—"
  },
  AvgDialog_142891_Content_66 = {Text = "WHOOSH!"},
  AvgDialog_142891_Content_67 = {
    Text = "Straaap—!"
  },
  AvgDialog_142891_Content_69 = {
    Text = "…! …!!!!"
  },
  AvgDialog_142891_Content_7 = {
    Text = "I tuoi cari ti circondano, la nipotina più piccola, Vera, non capisce ancora nulla e si appoggia affettuosamente alla tua mano."
  },
  AvgDialog_142891_Content_70 = {
    Text = "Fosti sollevato di scatto per la stoffa alla vita, la strana sensazione di un pelo liscio che ti sfiorava il viso."
  },
  AvgDialog_142891_Content_71 = {
    Text = "Quando apristi gli occhi, un brivido di orrore ti percorse la schiena."
  },
  AvgDialog_142891_Content_72 = {Text = "Pon—"},
  AvgDialog_142891_Content_73 = {
    Text = "La coda di una creatura informe e indicibile era agganciata dietro la tua schiena, la punta strisciante ricoperta di orribili aculei."
  },
  AvgDialog_142891_Content_74 = {
    Text = "Non avesti modo di renderti conto che quella cosa terrificante ti aveva chiaramente appena salvato—incontrollabilmente, un grido strozzato ti salì su per la gola."
  },
  AvgDialog_142891_Content_75 = {Text = "Shh!"},
  AvgDialog_142891_Content_76 = {
    Text = "Pontos, disteso su quella creatura senza volto, ti afferra e ti tira su, tappandoti la bocca con forza; la creatura spiegò le sue enormi ali simili a quelle di un pipistrello e scivolò in silenzio nel manto della notte."
  },
  AvgDialog_142891_Content_77 = {
    Text = "Non aver paura. Non ti faranno del male."
  },
  AvgDialog_142891_Content_78 = {
    Text = "Non c'è tempo, Jago. Stai zitto—ti spiego tutto dopo."
  },
  AvgDialog_142891_Content_79 = {
    Text = "Pontos ti mise un braccio intorno alle spalle per rassicurarti, stringendoti tra sé e la creatura, il corpo basso, gli occhi fissi sugli scogli in un angolo remoto del porto."
  },
  AvgDialog_142891_Content_8 = {
    Text = "Nonno, quando potrai giocare ancora con me? Guarda, ho già imparato quello che mi hai insegnato l'ultima volta."
  },
  AvgDialog_142891_Content_80 = {
    Text = "Prima che tu potessi chiedere qualcosa, un suono sinistro strisciò fuori dal mare, come vermi."
  },
  AvgDialog_142891_Content_81 = {
    Text = "<Shake:<Red:Frusciare, frusciare… frusciare, frusciare…>>"
  },
  AvgDialog_142891_Content_82 = {
    Text = "<Shake:<Red:Schiocco, schiocco… splash—>>"
  },
  AvgDialog_142891_Content_83 = {
    Text = "!… Urgh…"
  },
  AvgDialog_142891_Content_84 = {
    Text = "Prima vennero piedi artigliati ricoperti di scaglie, poi braccia—o forse morbidi arti contorti di artropode—corpi incrostati di cirripedi e una melma blasfemamente abominevole…"
  },
  AvgDialog_142891_Content_85 = {
    Text = "Conoscevi il mare solo come un'infinita fonte di cibo. Non avresti mai immaginato che potesse essere anche la dimora di simili abominazioni. I loro occhi sporgenti e terribili erano colmi di malizia mentre fissavano gli edifici della città."
  },
  AvgDialog_142891_Content_86 = {
    Text = "<Change>@4Tipu… ovunque si vada…"
  },
  AvgDialog_142891_Content_87 = {
    Text = "<Change>…si passa di qui… nutrire la Dissoluzione, immergersi nella Dissoluzione! Carne, carne!!"
  },
  AvgDialog_142891_Content_88 = {
    Text = "<Small:<Shake:Zio, un Mostro, c'è un Mostro!!>>"
  },
  AvgDialog_142891_Content_89 = {
    Text = "Un istante dopo, la creatura alata senza volto sotto di te si tuffò verso il basso. Pontos allargò le sue dita ossute, e una luce oscura si scagliò verso i due miserabili mostri."
  },
  AvgDialog_142891_Content_9 = {
    Text = "Tiene in mano una cavalletta storta e la posa sul copriletto."
  },
  AvgDialog_142891_Content_90 = {Text = "Ngh, mmph!"},
  AvgDialog_142891_Content_91 = {
    Text = "Crollarono esanimi a terra, come due statue di pietra mozzate."
  },
  AvgDialog_142891_Content_92 = {
    Text = "Tap— un tocco leggero."
  },
  AvgDialog_142891_Content_93 = {
    Text = "Poi quei due mezzi corpi si gettarono a terra, dissolvendosi in cenere grigia trascinata dal vento del mare."
  },
  AvgDialog_142891_Content_94 = {
    Text = "Uff, sapevo che ci sarebbe scappato qualche pesce dalla rete, Leisha e gli altri sono stati troppo sbadati."
  },
  AvgDialog_142891_Content_95 = {
    Text = "<Shake:La mamma e gli altri? Zio Pontos, cosa sta succedendo?!>"
  },
  AvgDialog_142891_Content_96 = {
    Text = "Lo spavento quasi ti fece cedere le gambe, e per poco non scivolasti dalla schiena liscia della creatura."
  },
  AvgDialog_142891_Content_97 = {
    Text = "Resisti ancora un po'. Prima devo assicurarmi che stiano tutti bene."
  },
  AvgDialog_142891_Content_98 = {
    Text = "Pontos ti diede una pacca sulla spalla, poi guidò la creatura a portarvi entrambi verso la costa dall'altro lato della città."
  },
  AvgDialog_142891_Content_99 = {Text = "..."},
  AvgDialog_142892_Content_1 = {
    Text = "Quando Eri Via"
  },
  AvgDialog_142892_Content_10 = {
    Text = "Sabbia gialla."
  },
  AvgDialog_142892_Content_11 = {
    Text = "Distese di Neve."
  },
  AvgDialog_142892_Content_12 = {Text = "Vuoto."},
  AvgDialog_142892_Content_13 = {
    Text = "E poi di nuovo la notte."
  },
  AvgDialog_142892_Content_14 = {
    Text = "Questo non è un viaggio o una traiettoria che gli esseri umani possano comprendere. Il tempo e lo spazio hanno perso ogni significato. Continui semplicemente ad attraversare, a pattugliare. Fai esperienza di tutto, poi vieni distrutto da tutto."
  },
  AvgDialog_142892_Content_15 = {
    Text = "Dato che hanno osato intrufolarsi, banditeli dal mondo mortale! Fate che ci temano! Fate che ricordino il mio nome!"
  },
  AvgDialog_142892_Content_16 = {
    Text = "Pontos spende il potere che ha acquisito con abbandono sconsiderato, e gli esseri che lo hanno conquistato ora fanno a pezzi anche i suoi nemici."
  },
  AvgDialog_142892_Content_17 = {
    Text = "Innumerevoli mostri contorti e ripugnanti vengono dati alla caccia dai Thrall-Gaunt e dai Gauntward."
  },
  AvgDialog_142892_Content_18 = {
    Text = "Vengono trafitti, resi parte dei festeggiamenti, suscitando fischi e risate di celebrazione senza fine."
  },
  AvgDialog_142892_Content_19 = {
    Text = "No, no, non di nuovo, nonononono!!!!!!"
  },
  AvgDialog_142892_Content_2 = {
    Text = "La strana sensazione di un pelo liscio, l'aculeo affilato sulla coda, enormi ali membranose che fendevano silenziose il cielo notturno."
  },
  AvgDialog_142892_Content_20 = {
    Text = "Hai visto con i tuoi occhi il raggio scatenato da Pontos ridurre il fanatico in polvere, ma subito dopo, il Loro corpo si è riassemblato ancora una volta, un urlo di Paura che erompeva dalla Loro bocca."
  },
  AvgDialog_142892_Content_21 = {
    Text = "Questo era il più devoto di tutti i cultisti. E ora ha già subito morte e riassemblaggio nell'agonia, più volte di quante chiunque potrebbe contare."
  },
  AvgDialog_142892_Content_22 = {
    Text = "Zio Pontos, questa... <Italic:cosa>... sta tornando in vita?"
  },
  AvgDialog_142892_Content_23 = {
    Text = "No. Sta semplicemente morendo e tornando, ancora e ancora, per assaporare la sofferenza che le era stata promessa."
  },
  AvgDialog_142892_Content_24 = {
    Text = "A volte li lascio morire, purché rinuncino alla loro devozione verso quegli dèi blasfemi e immondi."
  },
  AvgDialog_142892_Content_25 = {
    Text = "Ma se la Loro fede è troppo salda, allora nemmeno la morte può liberarli dalla sofferenza."
  },
  AvgDialog_142892_Content_26 = {
    Text = "Parlando con la disinvoltura di chi tratta una questione banale, Pontos alzò il palmo. Una forza invisibile allargò le braccia del fanatico, piegò il suo busto in avanti e lo costrinse a inginocchiarsi prostrato davanti a Pontos."
  },
  AvgDialog_142892_Content_27 = {
    Text = "Ora, dimmelo ancora una volta — adori ancora il tuo dio immondo?"
  },
  AvgDialog_142892_Content_28 = {
    Text = "<LightGray:*singhiozza>No… no, ti prego, ti supplico, lasciami morire, purché tu mi lasci morire!"
  },
  AvgDialog_142892_Content_29 = {
    Text = "<Shake:Ahahah, ahahahahah, nessun salvatore, non c'è proprio nessun salvatore, solo AB@2S, solo @2@3!!>"
  },
  AvgDialog_142892_Content_3 = {
    Text = "Pontos ti porta con sé nella caccia che precede i festeggiamenti notturni di Ebwynnos."
  },
  AvgDialog_142892_Content_30 = {
    Text = "Molto bene, preda. Alza la testa. Scopri la gola."
  },
  AvgDialog_142892_Content_31 = {
    Text = "Il fanatico, con la mente in Crollo, emette singhiozzi distorti e risate folli, avanza in ginocchio, sollevando il collo in una posa bizzarra."
  },
  AvgDialog_142892_Content_32 = {
    Text = "Ti concederò la morte."
  },
  AvgDialog_142892_Content_33 = {
    Text = "La luce gli attraversò la gola come un coltello rovente nel burro. Il Suo corpo collassò improvvisamente in cenere e polvere, trasportato dal vento nel Mare Profondo."
  },
  AvgDialog_142892_Content_34 = {
    Text = "Questa volta, il miserabile cultista non torna."
  },
  AvgDialog_142892_Content_35 = {
    Text = "Dove vanno gli altri? I mostri che vengono catturati?"
  },
  AvgDialog_142892_Content_36 = {
    Text = "Sono anche loro in Ebwynnos."
  },
  AvgDialog_142892_Content_37 = {
    Text = "Un Ebwynnos altrettanto eterno, solo senza la gioia."
  },
  AvgDialog_142892_Content_38 = {
    Text = "Lì, non esiste nulla. Persino il dolore conterebbe come una misericordia."
  },
  AvgDialog_142892_Content_39 = {
    Text = "Capisci a metà. La luce della luna splende. I Gaunt ti proteggono mentre questo strano viaggio si avvicina alla sua conclusione."
  },
  AvgDialog_142892_Content_4 = {
    Text = "Attraverso innumerevoli mezzi al di là della comprensione, il popolo di Ebwynnos dà la caccia alla propria \"preda\" attraverso innumerevoli dimensioni."
  },
  AvgDialog_142892_Content_40 = {
    Text = "Chiudi gli occhi, Jago."
  },
  AvgDialog_142892_Content_41 = {
    Text = "Un'oscurità umida, familiare, intima ti abbracciò, ti inghiottì completamente."
  },
  AvgDialog_142892_Content_42 = {
    Text = "Tornasti alla Casa Alta. Pontos scese dal carro, svelando il preludio di un'altra festa."
  },
  AvgDialog_142892_Content_43 = {
    Text = "Questo bambino sembra essersi affezionato molto a te."
  },
  AvgDialog_142892_Content_44 = {
    Text = "Vicino al davanzale della terrazza, Pontos si voltò dalla vivace Folla e tese la mano verso l'Incubo che volteggiava fuori dalla finestra."
  },
  AvgDialog_142892_Content_45 = {
    Text = "Non riesco a ricordare molte cose chiaramente per qualche motivo, ma... Zio Pontos, tu non sei più umano, e questo non è più il mondo come lo conosco, vero?"
  },
  AvgDialog_142892_Content_46 = {
    Text = "Sono già morto?"
  },
  AvgDialog_142892_Content_47 = {
    Text = "Apparentemente non aspettandosi che tu chiedessi così direttamente, Pontos alzò le sopracciglia sorpreso, e poi—rise."
  },
  AvgDialog_142892_Content_48 = {
    Text = "Mio caro piccolo amico, certo che no."
  },
  AvgDialog_142892_Content_49 = {
    Text = "Resta a Ebwynnos, e vivrai la vita grandiosa e straordinaria che desideravi quando da bambino leggevi i libri di fiabe. Non sarai mai più logorato."
  },
  AvgDialog_142892_Content_5 = {
    Text = "Quel bagliore inquietante pulsa ancora dall'interno delle finestre della casa."
  },
  AvgDialog_142892_Content_50 = {
    Text = "Partiremo per avventure, fuggiremo dal mondo banale. Quei nemici che hanno portato sconvolgimento e disastro nelle nostre vite saranno alla fine abbattuti fino a quando non oseranno più mostrare la faccia."
  },
  AvgDialog_142892_Content_51 = {
    Text = "Hai fatto un respiro profondo. Hai sentito di nuovo quella cavalletta—grezza, ruvida, leggermente pungente."
  },
  AvgDialog_142892_Content_52 = {
    Text = "Sì, tutto questo sembra meraviglioso."
  },
  AvgDialog_142892_Content_53 = {
    Text = "Ma quale prezzo devo pagare, Zio Pontos?"
  },
  AvgDialog_142892_Content_54 = {
    Text = "La sua fronte si corrugò con una lentezza straziante, portando con sé un'arroganza altezzosa che non ti era familiare."
  },
  AvgDialog_142892_Content_55 = {
    Text = "Il prezzo è appena… qualcosa di assolutamente irrilevante, qualcosa di cui non hai bisogno e che non ricorderai. <Red:Dammelo>, Jago."
  },
  AvgDialog_142892_Content_56 = {
    Text = "Nel momento in cui finì di parlare, la coda uncinata dell'incubo scese dall'esterno della finestra verso la tua tasca."
  },
  AvgDialog_142892_Content_57 = {
    Text = "Verso la cavalletta storta che hai tenuto nascosta."
  },
  AvgDialog_142892_Content_58 = {Text = "No!"},
  AvgDialog_142892_Content_59 = {
    Text = "Istintivamente sei barcollato all'indietro, ma il movimento sembrò far infuriare Pontos, che ti afferrò il braccio."
  },
  AvgDialog_142892_Content_6 = {
    Text = "Gaunt dopo Gaunt volteggia nell'aria, finché Pontos — in piedi accanto a te in un carro che irradia un indescrivibile bagliore perlaceo — non emette un grido risonante."
  },
  AvgDialog_142892_Content_60 = {
    Text = "Semplicemente non capisci, ragazzo. Sai quanta fatica ho fatto per trovarti…"
  },
  AvgDialog_142892_Content_61 = {
    Text = "Cu-cù, cu-cù…"
  },
  AvgDialog_142892_Content_62 = {
    Text = "Ti sei immobilizzato sul posto. Non erano solo le dita di Pontos a premere contro la tua pelle—una Paura senza nome ti ha costretto ad alzare lo sguardo, e le pupille blu intenso di Pontos ti gravavano addosso pesantemente."
  },
  AvgDialog_142892_Content_63 = {
    Text = "Dato che vuoi vedere, allora guarda—da che genere di cosa ti ho salvato."
  },
  AvgDialog_142892_Content_64 = {
    Text = "Sei stato di nuovo <Red:inghiottito>."
  },
  AvgDialog_142892_Content_65 = {Text = "..."},
  AvgDialog_142892_Content_66 = {
    Text = "Ehi, ehi, vecchio amico, hai sentito cosa ho detto? Ti sei incantato di nuovo! Attento!"
  },
  AvgDialog_142892_Content_67 = {
    Text = "Splash! Acqua fangosa ti ha colpito in faccia, e sei tornato alla realtà, fissando con sguardo vuoto la persona accanto a te. Anziano, curvo e dal chiacchiericcio infinito—ma lo riconoscevi. Era inconfondibilmente un Orney anziano."
  },
  AvgDialog_142892_Content_68 = {
    Text = "Questi maledetti Marinai, completamente fuori controllo! Se vuoi la mia opinione, tutti quei viaggi gli hanno reso il cuore irrequieto. Non riescono a tenere la mente su nulla di pratico!"
  },
  AvgDialog_142892_Content_69 = {
    Text = "Orney? ...Di cosa stai parlando? Da bambini sognavi sempre di fare il marinaio, di vedere ogni continente!"
  },
  AvgDialog_142892_Content_7 = {
    Text = "Catturateli, assicuratevi che non possano mai più andarsene, fateli soffrire qui per l'eternità!"
  },
  AvgDialog_142892_Content_70 = {
    Text = "Ho davvero detto una cosa del genere? Non essere ridicolo. Alla nostra età, dovresti sapere che la stabilità è la cosa migliore."
  },
  AvgDialog_142892_Content_71 = {
    Text = "L'hai dimenticato, vecchio mio, dal secondo anno di università non ne parliamo più. Parliamo di quelle notizie di Giornale, di quei maledetti rendiconti uno dopo l'altro, della pensione, delle cene di famiglia ogni due Settimane."
  },
  AvgDialog_142892_Content_72 = {
    Text = "Ti ha dato una pacca sulla spalla e ha ritirato tremolante due sacchetti di carta dallo sportello della farmacia."
  },
  AvgDialog_142892_Content_73 = {
    Text = "Non sei come me? Dopo la laurea, tornare qui, e grazie al cielo, non abbiamo neanche più la voglia di fare un viaggio lungo."
  },
  AvgDialog_142892_Content_74 = {
    Text = "Questa maledetta artrite. Grazie al cielo—a parte te e questi antidolorifici, non c'è nient'altro che mi costringa a uscire di casa."
  },
  AvgDialog_142892_Content_75 = {
    Text = "La solitudine, ah! Da giovani pensavamo fosse roba da leggende, come il mostro di Loch Ness."
  },
  AvgDialog_142892_Content_76 = {
    Text = "Orney continuava a blaterare di qualcosa. Fissavi le sue labbra che si aprivano e chiudevano, quando un'improvvisa ondata di vertigine ti strappò dalla monotona routine."
  },
  AvgDialog_142892_Content_77 = {Text = "..."},
  AvgDialog_142892_Content_78 = {
    Text = "Hai visto cosa hanno fatto quei giorni monotoni a Orney? Vai a dare un'altra occhiata—a ciò che hai barattato."
  },
  AvgDialog_142892_Content_79 = {
    Text = "Vedi te stesso, disteso a letto, avvizzito e consumato."
  },
  AvgDialog_142892_Content_8 = {Text = "Nuvole."},
  AvgDialog_142892_Content_80 = {
    Text = "Certo, all'inizio saranno tristi, verseranno qualche lacrima per te."
  },
  AvgDialog_142892_Content_81 = {
    Text = "Vedi una coppia e la loro figlioletta uscire a passeggio, consolandosi a vicenda."
  },
  AvgDialog_142892_Content_82 = {
    Text = "Ma nel giro di una settimana, o anche solo di qualche giorno, se ne faranno una ragione."
  },
  AvgDialog_142892_Content_83 = {
    Text = "Cene, passeggiate, l'università, chissà? I bambini potrebbero resistere un po' più a lungo. Non molto, ovviamente."
  },
  AvgDialog_142892_Content_84 = {
    Text = "Alla fine, non rimarrà nulla. Nessuno si ricorderà di te."
  },
  AvgDialog_142892_Content_85 = {
    Text = "Inverno, primavera, un altro inverno. Osservi la polvere depositarsi lentamente per tutta la casa."
  },
  AvgDialog_142892_Content_86 = {
    Text = "Capisci adesso, Jago? Ho semplicemente portato le parti interessanti di tutti voi… le parti vibranti… a Ebwynnos."
  },
  AvgDialog_142892_Content_87 = {
    Text = "Il tuo guscio di corpo sta per morire. Con o senza di te, tutti coloro che hai mai conosciuto continueranno a vivere le proprie vite, vite che non hanno nulla a che fare con te."
  },
  AvgDialog_142892_Content_88 = {
    Text = "La voce di Pontos riecheggia nelle tue orecchie, e un istante dopo, ricompari nella grande sala dell'Alta Dimora di Ebwynnos."
  },
  AvgDialog_142892_Content_89 = {
    Text = "Ora, Jago, pensaci—pensaci bene. Liberati di quell'involucro, abbandona quei ricordi privi di significato, e resta con noi."
  },
  AvgDialog_142892_Content_9 = {
    Text = "Terra annientata."
  },
  AvgDialog_142892_Content_90 = {
    Text = "Orney, Zio White e tutti nella sala da ballo affollata di Ebwynnos sembrano accorgersene all'improvviso."
  },
  AvgDialog_142892_Content_91 = {
    Text = "Ehi, perché avete quella faccia voi due? Abbiamo appena ottenuto un'altra grande vittoria!"
  },
  AvgDialog_142892_Content_92 = {
    Text = "Dai, Jago, bevi con noi. Non c'è nulla di cui preoccuparsi a Ebwynnos!"
  },
  AvgDialog_142892_Content_93 = {
    Text = "Ridono di cuore, accogliendoti tra loro."
  },
  AvgDialog_142892_Content_94 = {
    Text = "Le persone si stanno passando il bottino. Le maree ti rimbombano di nuovo nelle orecchie."
  },
  AvgDialog_142892_Content_95 = {
    Text = "Pontos tende la mano, aspettando che tu la prenda."
  },
  AvgDialog_142892_Content_96 = {
    Text = "Proprio come quella \"stretta dell'accordo\" che avevate stabilito da bambini."
  },
  AvgDialog_142893_Content_1 = {Text = "Il Motivo"},
  AvgDialog_142893_Content_10 = {
    Text = "<Red:Non avrebbe dovuto essere così.>"
  },
  AvgDialog_142893_Content_11 = {
    Text = "Avresti dovuto scoprire per caso la tua stirpe, la mamma avrebbe dovuto essere convinta dallo zio Pontos a guidarti, e insieme sareste partiti per un viaggio, vivendo ogni sorta di avventure emozionanti, entusiasmanti e meravigliose."
  },
  AvgDialog_142893_Content_12 = {
    Text = "<Shake:E poi diventerai un grande <Red:eroe>, è così che si scrive nei romanzi d'avventura.>"
  },
  AvgDialog_142893_Content_13 = {
    Text = "Jago! Fatti forza, andrà tutto bene, tua madre è la più forte tra i Gauntward che abbia mai visto, si risolverà tutto!"
  },
  AvgDialog_142893_Content_14 = {
    Text = "Io… Zio Pontos, mamma…"
  },
  AvgDialog_142893_Content_15 = {
    Text = "La città un tempo tranquilla era completamente avvolta dalle fiamme."
  },
  AvgDialog_142893_Content_16 = {
    Text = "Era passato solo un giorno, quando fanatici improvvisi e travolgenti avevano sommerso ogni luogo a perdita d'occhio."
  },
  AvgDialog_142893_Content_17 = {
    Text = "Tra di loro c'erano sia esseri umani che Mostri puri, e gli attacchi indiscriminati avevano fatto ardere l'intero paese in fiamme."
  },
  AvgDialog_142893_Content_18 = {
    Text = "Sangue dal sapore salmastro e metallico ti schizzò sul viso e sul corpo. Pontos incanalava disperatamente il fischietto da caccia nella sua mano, aprendo un varco a viva forza insieme al suo Incubo."
  },
  AvgDialog_142893_Content_19 = {
    Text = "Pontos, prendi Jago e scappa!"
  },
  AvgDialog_142893_Content_2 = {
    Text = "Quella notte, sfinito da troppa paura e troppi pensieri, ti addormentasti presto."
  },
  AvgDialog_142893_Content_20 = {
    Text = "Leisha, che stava cercando disperatamente insieme agli altri Gauntward di fermare l'ondata di Mostri, vedendoti sano e salvo, si illuminò negli Occhi e urlò a squarciagola verso Pontos."
  },
  AvgDialog_142893_Content_21 = {Text = "Screeee!"},
  AvgDialog_142893_Content_22 = {
    Text = "Un'altra testa simile a un anemone di mare fu dilaniata dagli artigli affilati dell'Incubo. Leisha scagliò con disinvoltura una striscia della stessa enigmatica luce bianca di Pontos, impedendogli di caricare verso di lei."
  },
  AvgDialog_142893_Content_23 = {
    Text = "Questa non possiamo vincerla, ma possiamo ancora guadagnarvi del tempo. Correte, più lontano che potete!"
  },
  AvgDialog_142893_Content_24 = {
    Text = "Ma cosa dici, ne hai già affrontati di più senza problemi, non succederà niente! E poi, lo sai, troviamo sempre un modo."
  },
  AvgDialog_142893_Content_25 = {
    Text = "Non sapevi cosa intendesse lo zio Pontos con \"una via d'uscita\". Vedesti solo il suo sguardo posarsi su quel fischietto da caccia, quello che non aveva lasciato uscire dalla sua mano dal giorno in cui era tornato."
  },
  AvgDialog_142893_Content_26 = {
    Text = "No, <Red:assolutamente no.>"
  },
  AvgDialog_142893_Content_27 = {
    Text = "<Shake:So cosa stai pensando, <Red:mio fratello non deve restare intrappolato per sempre in quel maledetto posto!>   >"
  },
  AvgDialog_142893_Content_28 = {
    Text = "Abbracciate la Baldoria@1, nutrite l'Erosione!"
  },
  AvgDialog_142893_Content_29 = {Text = "Leisha!!!"},
  AvgDialog_142893_Content_3 = {
    Text = "Sia tu che Pontos pensavate che ci sarebbero state molte altre occasioni per parlarne."
  },
  AvgDialog_142893_Content_30 = {
    Text = "Nel fragore di squame che si spezzavano furiosamente, un fanatico con metà del corpo già dilaniato spalancò i globi oculari Cremisi fino all'inverosimile, borbottando in preda al Furore mentre si avventava su Leisha."
  },
  AvgDialog_142893_Content_31 = {
    Text = "…Il suono straziante di pelle e muscoli che si laceravano."
  },
  AvgDialog_142893_Content_32 = {
    Text = "Il suono di due corpi che si schiantavano sulla strada acciottolata."
  },
  AvgDialog_142893_Content_33 = {
    Text = "Il suono delle viscere che si riversavano fuori."
  },
  AvgDialog_142893_Content_34 = {
    Text = "Poi, il mondo piombò nel silenzio in un istante. Non riuscivi a sentire nulla, a vedere nulla."
  },
  AvgDialog_142893_Content_35 = {
    Text = "Sangue, cielo notturno, luna."
  },
  AvgDialog_142893_Content_36 = {
    Text = "Una luna color sangue, sospesa lontana nell'immensità del cielo."
  },
  AvgDialog_142893_Content_37 = {
    Text = "Ah… ahhh."
  },
  AvgDialog_142893_Content_38 = {
    Text = "AAAAAAAAHHHHH!!!!!"
  },
  AvgDialog_142893_Content_39 = {
    Text = "Dopo un breve gemito senza fiato strozzato dal profondo della gola, Pontos emise qualcosa che non avevi mai sentito in tutta la tua vita."
  },
  AvgDialog_142893_Content_4 = {
    Text = "<Red:Ma non fu così.>"
  },
  AvgDialog_142893_Content_40 = {
    Text = "Un lamento del tutto disumano."
  },
  AvgDialog_142893_Content_41 = {
    Text = "Sore— Sorella… Leisha, LEISHA!!!"
  },
  AvgDialog_142893_Content_42 = {
    Text = "Un ronzio lacerante ti attraversò il cervello, e un'ondata travolgente di sgomento ti investì come un'onda di marea. No, no, no, no, no no no no no no…"
  },
  AvgDialog_142893_Content_43 = {
    Text = "Nessuno sopravvisse. I Gaunt, che di giorno erano sembrati nient'altro che vicini amichevoli, cadevano uno dopo l'altro. I comuni abitanti della città urlavano nel mare di fuoco e nella marea di mostri."
  },
  AvgDialog_142893_Content_44 = {
    Text = "Ma tu non riuscivi più a sentire nulla di tutto ciò. Il tuo corpo ti aveva tradito completamente, e urlava insieme a loro, un grido grezzo e lacerante."
  },
  AvgDialog_142893_Content_45 = {
    Text = "<Change>Sacrificio! Sacrificateli tutti al <Red:Rapimento>！"
  },
  AvgDialog_142893_Content_46 = {
    Text = "Gli altri cultisti ti individuarono senza la minima difficoltà, e proprio mentre quegli artigli squamosi, grondanti di melma blasfema, si protendevano verso di te..."
  },
  AvgDialog_142893_Content_47 = {
    Text = "Pontos soffiò nel fischietto da caccia."
  },
  AvgDialog_142893_Content_48 = {
    Text = "Non avevi mai sentito un suono così stridulo e così antico. Una forza irrazionale ti trapassò i timpani e martellò ogni ultimo brandello di sanità nella tua mente."
  },
  AvgDialog_142893_Content_49 = {
    Text = "Un'incomparabile, immensa pressione si abbatté sulla terra!"
  },
  AvgDialog_142893_Content_5 = {Text = "Hisss—!"},
  AvgDialog_142893_Content_50 = {
    Text = "Una forza enorme e invisibile schiacciò Pontos a terra, ma lui non sembrava sentirla affatto, gli occhi spalancati fino a spaccarsi mentre recitava una preghiera incomprensibile."
  },
  AvgDialog_142893_Content_51 = {
    Text = "O @2, @4,@3 Signore dell'Abisso, ti invoco nel nome di @3…"
  },
  AvgDialog_142893_Content_52 = {
    Text = "Innumerevoli presenze simili a braccia nere si protesero da una voragine più profonda del Mare Profondo più antico, cercando l'unica <Red:preda> che desideravano."
  },
  AvgDialog_142893_Content_53 = {
    Text = "<Shake:Cercando il <Red:padrone >che avevano scelto.>"
  },
  AvgDialog_142893_Content_54 = {
    Text = "<Change>Prendi la mia carne, prendi la mia anima, prendi tutto!"
  },
  AvgDialog_142893_Content_55 = {
    Text = "Su quel volto che portava sempre un sorriso disinvolto, apparve ora un'espressione di tragica determinazione e di abbandono temerario."
  },
  AvgDialog_142893_Content_56 = {
    Text = "Mentre qualcosa di molto più grande e travolgente si fondeva in lui, ali che oscuravano il cielo si alzarono, innalzando barriera su barriera di oscurità nero pece."
  },
  AvgDialog_142893_Content_57 = {
    Text = "<Change>Rispondi alla preghiera del tuo Proxy—riducili tutti in polvere!!"
  },
  AvgDialog_142893_Content_58 = {
    Text = "Ormai nessuno riusciva più a distinguere quel suono profondo e imperscrutabile dalla voce che un tempo era stata quella di Pontos."
  },
  AvgDialog_142893_Content_59 = {
    Text = "Divennero uno, indistinguibili, come Loro desideravano."
  },
  AvgDialog_142893_Content_6 = {
    Text = "<Shake:<Red:Non è così, la storia d'avventura di un eroe non dovrebbe essere così.>>"
  },
  AvgDialog_142893_Content_60 = {
    Text = "Mentre il fischio stridulo echeggiava lungo la costa, ogni ultimo cultista si sgretolò in cenere bianca."
  },
  AvgDialog_142893_Content_61 = {Text = "..."},
  AvgDialog_142893_Content_62 = {
    Text = "Ahhh! ...Cosa successe dopo? Lo zio Pontos, e la madre del nonno... loro..."
  },
  AvgDialog_142893_Content_63 = {
    Text = "Vera aveva trattenuto il respiro per tutto il tempo, e alla fine non riuscì a trattenersi dal gridare, con le lacrime quasi agli occhi."
  },
  AvgDialog_142893_Content_64 = {
    Text = "Quello che accadde dopo, per quanto mi sforzi, proprio non riesco a ricordarlo. Tutto ciò che ricordo è…"
  },
  AvgDialog_142893_Content_65 = {Text = "..."},
  AvgDialog_142893_Content_66 = {
    Text = "*Sob*… Jago… Jago! Grazie al cielo, finalmente ti sei svegliato."
  },
  AvgDialog_142893_Content_67 = {
    Text = "Papà, zia Lesa, tutti quanti, la nostra città, tutto quanto... Waaaaaah!!"
  },
  AvgDialog_142893_Content_68 = {
    Text = "Attraverso il racconto singhiozzante di Orney, la tua amica d'infanzia, venisti a sapere che l'intera città era stata annientata da un'enorme esplosione."
  },
  AvgDialog_142893_Content_69 = {
    Text = "Solo una manciata di persone sopravvisse tra le rovine e fu accolta da parenti o amici nelle città vicine. Eri rimasto privo di sensi per quattro giorni interi."
  },
  AvgDialog_142893_Content_7 = {
    Text = "Jago, chiudi gli occhi e seguimi!"
  },
  AvgDialog_142893_Content_70 = {
    Text = "No, non è stata un'esplosione. Ricordo chiaramente… Ugh! Mi fa così male la testa."
  },
  AvgDialog_142893_Content_71 = {
    Text = "Il rumore bianco lancinante nella tua mente ti fece scivolare di nuovo nel sonno. Quando ti svegliasti di nuovo, ti ritrovasti cullato confusamente tra le braccia di qualcuno."
  },
  AvgDialog_142893_Content_72 = {
    Text = "Mamma… Mamma?!"
  },
  AvgDialog_142893_Content_73 = {
    Text = "Non muoverti troppo. Le tue ferite non si sono ancora rimarginate."
  },
  AvgDialog_142893_Content_74 = {
    Text = "Vedesti con i tuoi stessi occhi che Leisha—il cui ventre era stato squarciato dai fanatici—era seduta accanto al letto completamente illesa. La gioia travolgente ti fece spalancare gli occhi mentre le lacrime ti rigavano il volto."
  },
  AvgDialog_142893_Content_75 = {
    Text = "Mamma! Era tutto un sogno? Sapevo che stavi bene, sei ancora viva."
  },
  AvgDialog_142893_Content_76 = {
    Text = "Shh, ascoltami, Jago. La mamma deve lasciarti e andare in un posto molto lontano."
  },
  AvgDialog_142893_Content_77 = {
    Text = "La famiglia di Orney si prenderà cura di te. Domani mattina troveranno abbastanza soldi sul tavolo. Devi vivere bene."
  },
  AvgDialog_142893_Content_78 = {
    Text = "Aspetta, lasciarmi? Mamma, perché? E lo zio Pontos? Dov'è?"
  },
  AvgDialog_142893_Content_79 = {
    Text = "Leisha ammutolì all'improvviso. Dopo un momento, ti strinse forte la mano, ti premette nel palmo la bussola di rame che avevi lasciato cadere, e si chinò a baciarti la fronte."
  },
  AvgDialog_142893_Content_8 = {
    Text = "Roar! Roar!"
  },
  AvgDialog_142893_Content_80 = {
    Text = "Jago, tieni questo. Giurami che vivrai al sicuro, da qualche parte."
  },
  AvgDialog_142893_Content_81 = {
    Text = "Volevi disperatamente scuotere la testa, ma Leisha non te ne diede la possibilità."
  },
  AvgDialog_142893_Content_82 = {
    Text = "Ricorda, non venire mai a cercare me o tuo zio. Mai."
  },
  AvgDialog_142893_Content_83 = {Text = "Mamma!…"},
  AvgDialog_142893_Content_84 = {
    Text = "Ti sei alzato di scatto."
  },
  AvgDialog_142893_Content_85 = {
    Text = "Un vento leggero agitava le foglie. La notte era calata senza che te ne accorgessi."
  },
  AvgDialog_142893_Content_86 = {
    Text = "Era un sogno? Tua madre Leisha non era da nessuna parte. Orney, che stava sonnecchiando al tuo capezzale per vegliarti, sembrò trasalire."
  },
  AvgDialog_142893_Content_87 = {
    Text = "Jago?! Che succede?"
  },
  AvgDialog_142893_Content_88 = {
    Text = "Fissasti con sguardo vuoto fuori dalla finestra. La luna pendeva ancora lontana nel cielo."
  },
  AvgDialog_142893_Content_89 = {
    Text = "Oltre a quello, non c'era nulla."
  },
  AvgDialog_142893_Content_9 = {
    Text = "Pontos ti stringe forte e corre verso l'interno, lontano dalla costa, con la schiena a farti scudo. Fissi terrorizzato le fiamme ovunque e le persone che si agitano nel caos."
  },
  AvgDialog_145231_Content_1 = {Text = "Bang—"},
  AvgDialog_145231_Content_10 = {
    Text = "Oggi non riuscivo a concentrarmi né sulla lama né sul nemico."
  },
  AvgDialog_145231_Content_11 = {
    Text = "Qualcos'altro continuava a distrarmi."
  },
  AvgDialog_145231_Content_12 = {
    Text = "Qualcos'altro? Come cosa?"
  },
  AvgDialog_145231_Content_13 = {Text = "Tu."},
  AvgDialog_145231_Content_14 = {
    Text = "??? Vuoi dire..."
  },
  AvgDialog_145231_Content_15 = {
    Text = "Sì. Quella pazza di Thais, e il suo fiume folle."
  },
  AvgDialog_145231_Content_16 = {
    Text = "Va bene perdere uno scontro ogni tanto. Riposati qui per ora, vado a prendere delle medicine..."
  },
  AvgDialog_145231_Content_17 = {Text = "..."},
  AvgDialog_145231_Content_18 = {
    Text = "Cerchi di sgusciare fuori dalla stanza, ma Lotan non te ne dà il tempo."
  },
  AvgDialog_145231_Content_19 = {
    Text = "Due secchi schiocchi risuonano vicino alle tue orecchie. Le lame d'osso di Lotan trafiggono il letto, i loro manici d'osso inchiodando le tue mani al materasso. Non riesci a muoverti."
  },
  AvgDialog_145231_Content_2 = {
    Text = "La porta si spalanca con un fragore simile a un tamburo da guerra. Reeking di sangue, qualcuno irrompe nella stanza e crolla sul tuo letto, ansimando."
  },
  AvgDialog_145231_Content_20 = {
    Text = "Non sono venuta qui per guarire. Sono venuta per risolvere un problema. E tu... sei il problema."
  },
  AvgDialog_145231_Content_21 = {
    Text = "Ehi! Lotan... cosa... cosa stai facendo..."
  },
  AvgDialog_145231_Content_22 = {
    Text = "Odio non riuscire a concentrarmi durante il combattimento. Mi irrita."
  },
  AvgDialog_145231_Content_23 = {
    Text = "I—io ho un'idea! Potresti andare a cercare Thais... mmph..."
  },
  AvgDialog_145231_Content_24 = {
    Text = "Una mano macchiata di sangue ti stringe la mascella, soffocando la tua voce in gemiti incoerenti."
  },
  AvgDialog_145231_Content_25 = {
    Text = "La mia mente non ha mai contenuto altro che la battaglia. Ma avere un'eccezione... non è poi così male."
  },
  AvgDialog_145231_Content_26 = {
    Text = "Mi piace concentrarmi su una cosa alla volta. Che si tratti di un combattimento... o di qualcos'altro."
  },
  AvgDialog_145231_Content_27 = {
    Text = "Lotan ti fissa dall'alto come se stesse immobilizzando una rivale che le procura il piacere supremo, e lo spirito combattivo nei suoi occhi si trasforma in fame sfrenata."
  },
  AvgDialog_145231_Content_28 = {
    Text = "Ho versato tutto questo sangue a causa tua. Dovrai pagarne il prezzo, non credi?"
  },
  AvgDialog_145231_Content_29 = {
    Text = "Gli artigli di ferro del suo guanto scorrono lungo la tua mascella, scivolando oltre la gola, il petto e la vita... Ti dibatti furiosamente, emettendo suoni privi di senso, ma le lame ti tengono fermo, immobile come la pietra."
  },
  AvgDialog_145231_Content_3 = {Text = "Ah! Chi—"},
  AvgDialog_145231_Content_30 = {
    Text = "Lotan si avvicina, ammirando il tuo viso arrossato per la lotta."
  },
  AvgDialog_145231_Content_31 = {
    Text = "Sorride, lasciando che il suo sangue goccioli dalle labbra sul tuo viso."
  },
  AvgDialog_145231_Content_32 = {
    Text = "Dibattiti quanto vuoi. Vediamo se riesci a liberarti... mio \"avversario\"."
  },
  AvgDialog_145231_Content_4 = {
    Text = "...Lotan? Sei ferita?!"
  },
  AvgDialog_145231_Content_5 = {
    Text = "La fissi incredulo, contemplando il suo corpo malconcio."
  },
  AvgDialog_145231_Content_6 = {
    Text = "Solo graffi. Niente di grave."
  },
  AvgDialog_145231_Content_7 = {
    Text = "Cosa è successo... Chi avrebbe potuto farti questo?"
  },
  AvgDialog_145231_Content_8 = {
    Text = "Un Verme del Mare Astrale. Avrebbe dovuto essere una preda facile. Ma oggi..."
  },
  AvgDialog_145231_Content_9 = {
    Text = "Corruga la fronte, con un lampo di irritazione negli occhi."
  },
  AvgDialog_14530_Content_10 = {
    Text = "Schiudi le labbra; un debole sapore salato si diffonde sulla lingua. Non è pioggia."
  },
  AvgDialog_14530_Content_11 = {
    Text = "<Gray:...Lacrime?>"
  },
  AvgDialog_14530_Content_12 = {
    Text = "Come se fosse stato lavato da quell'umidità, il mondo intorno a te si mette a fuoco."
  },
  AvgDialog_14530_Content_14 = {
    Text = "Ra...mona..."
  },
  AvgDialog_14530_Content_15 = {
    Text = "Il tuo grido muore in gola."
  },
  AvgDialog_14530_Content_16 = {
    Text = "Una pressione schiacciante irrompe da ogni direzione mentre una marea nera ti inghiotte."
  },
  AvgDialog_14530_Content_17 = {Text = "..."},
  AvgDialog_14530_Content_18 = {
    Text = "Un orologio ticchetta. Il canto degli uccelli filtra attraverso una finestra socchiusa."
  },
  AvgDialog_14530_Content_19 = {
    Text = "Una persistente sensazione di soffocamento ti spinge a batterti il petto. Ti alzi a sedere lentamente, avendo bisogno di un momento per sentire il peso della realtà."
  },
  AvgDialog_14530_Content_2 = {
    Text = "Lacrime di pioggia"
  },
  AvgDialog_14530_Content_20 = {
    Text = "<Gray:Ho fatto molti sogni strani, ma questa è la prima volta che muoio in uno di essi.>"
  },
  AvgDialog_14530_Content_21 = {
    Text = "È una sensazione strana."
  },
  AvgDialog_14530_Content_22 = {
    Text = "Quasi interessante."
  },
  AvgDialog_14530_Content_23 = {
    Text = "Drin, drin—"
  },
  AvgDialog_14530_Content_24 = {
    Text = "Silenzi la sveglia, ti alzi e ti stiracchi."
  },
  AvgDialog_14530_Content_25 = {
    Text = "Vabbè. Mi ricordo che devo andare a—"
  },
  AvgDialog_14530_Content_26 = {
    Text = "Addestramento speciale domani alle 8 di mattina nella Sala del Risveglio. Non fare tardi."
  },
  AvgDialog_14530_Content_27 = {
    Text = "La Sala del Risveglio? Si tratta di esercitazioni legate al Risveglio?"
  },
  AvgDialog_14530_Content_28 = {
    Text = "Stiamo testando la stabilità del <Yellow:Dominio Artificiale>."
  },
  AvgDialog_14530_Content_29 = {
    Text = "Che cos'è?"
  },
  AvgDialog_14530_Content_3 = {Text = "Cadere."},
  AvgDialog_14530_Content_30 = {
    Text = "Un piccolo progetto che sto sviluppando—un hobby personale, in realtà. Utilizza l'amplificazione mentale del dispositivo di Risveglio per potenziare la coscienza e lo spirito di un soggetto mentre dorme."
  },
  AvgDialog_14530_Content_31 = {
    Text = "In teoria, uno spirito sufficientemente amplificato può formare un Dominio. Un Dominio stabilizzato può esistere indipendentemente sia dalla realtà che dalla dimensione spirituale."
  },
  AvgDialog_14530_Content_32 = {
    Text = "Questi reami condividono molte caratteristiche con il <Yellow:Dominio>, perciò li chiamo Domini Artificiali."
  },
  AvgDialog_14530_Content_33 = {
    Text = "A differenza dei Domini naturali che invadono la realtà, i Domini Artificiali sono non aggressivi, stabili e controllabili. Possono <Yellow:ricreare un momento di un tempo che non esiste nel presente>."
  },
  AvgDialog_14530_Content_34 = {
    Text = "Un tempo che non esiste... vuoi dire che può manifestare i ricordi di una persona?"
  },
  AvgDialog_14530_Content_35 = {
    Text = "Può <Yellow:presentare un ricordo basato sulla comprensione dell'ospite>. Inoltre, permette ad altri di entrare in quel ricordo."
  },
  AvgDialog_14530_Content_36 = {
    Text = "Come entrare in un normale Dominio...?"
  },
  AvgDialog_14530_Content_37 = {
    Text = "Sei sveglio/a. Esattamente. Una volta che un Dominio Artificiale si forma, altri individui possono entrarvi fisicamente e interagire con la coscienza dell'entità ospitante."
  },
  AvgDialog_14530_Content_38 = {
    Text = "Se l'ospite riconosce il visitatore o come reagisce alla sua presenza... ah, le possibilità sono affascinanti."
  },
  AvgDialog_14530_Content_39 = {
    Text = "Se funziona, sarà il modo definitivo per Investigatori e Custodi di costruire un rapporto e approfondire la comprensione dei propri Risvegliatori."
  },
  AvgDialog_14530_Content_4 = {
    Text = "Stai cadendo."
  },
  AvgDialog_14530_Content_40 = {
    Text = "Ripensi all'espressione incuriosita di Doll e un brivido ti percorre il cuoio capelluto."
  },
  AvgDialog_14530_Content_41 = {
    Text = "Lo chiama addestramento speciale, ma sono chiaramente una cavia da laboratorio... Spero che non succeda nulla di strano."
  },
  AvgDialog_14530_Content_42 = {
    Text = "Raccogli il coraggio e spingi la porta nel passaggio sotterraneo."
  },
  AvgDialog_14530_Content_43 = {
    Text = "Prima che tu possa reagire, una luce accecante ti inghiotte completamente."
  },
  AvgDialog_14530_Content_5 = {
    Text = "La sensazione di cadere ti tira verso il basso, trascinando la tua coscienza fuori da un sogno nero come la pece."
  },
  AvgDialog_14530_Content_6 = {
    Text = "Una luce sfocata tremola davanti a te. Dopo un istante di disorientamento, ti rendi conto di aver aperto gli occhi."
  },
  AvgDialog_14530_Content_7 = {
    Text = "<Gray:Perché... perché è tutto così sfocato...?>"
  },
  AvgDialog_14530_Content_8 = {
    Text = "Una goccia, poi due... un liquido fresco ti cade sulla fronte e scivola lungo la guancia."
  },
  AvgDialog_14530_Content_9 = {
    Text = "Pioggia...?"
  },
  AvgDialog_145510_Content_10 = {
    Text = "Ai piedi delle montagne innevate, un mercato caotico è cresciuto dal permafrost. Baracche di legno, tende e bancarelle improvvisate di pelle di yak si accalcano fitte su entrambi i lati di un sentiero di montagna fangoso."
  },
  AvgDialog_145510_Content_11 = {
    Text = "Iperborea è davvero troppo fredda, ho quasi nostalgia del tè caldo della signora Sylvia..."
  },
  AvgDialog_145510_Content_12 = {
    Text = "Anche se è presto per dirlo, una volta tornati a Mythag, chiederò alla signora Sylvia di fornirti tè caldo in un Ciclo di rifornimento continuo di 24 ore."
  },
  AvgDialog_145510_Content_13 = {
    Text = "Per ora, concentriamoci sul compito che abbiamo davanti."
  },
  AvgDialog_145510_Content_14 = {
    Text = "Tiri fuori il dépliant promozionale, tutto sgualcito dopo essere rimasto arrotolato tra i bagagli, e lo ruoti verso il Sole per confrontarlo."
  },
  AvgDialog_145510_Content_15 = {
    Text = "Il profilo delle montagne parte dal bordo del dépliant e si fonde perfettamente con la sagoma delle cime sotto il cielo cupo."
  },
  AvgDialog_145510_Content_16 = {
    Text = "È proprio qui, solo che non so come trovare quel misterioso maestro con una lista di titoli più alta dell'Everest..."
  },
  AvgDialog_145510_Content_17 = {
    Text = "<Shake:Tutti, ascoltateee!>"
  },
  AvgDialog_145510_Content_18 = {
    Text = "Seguendo il Richiamo con lo sguardo, una ragazza vestita di bianco si staglia da sola davanti a una tenda su una collinetta, con gli occhi sulla Folla sparsa."
  },
  AvgDialog_145510_Content_19 = {
    Text = "Sono il Proxy del dio supremo, la grande Fata del Sacro Ordine Caraboo, incarnazione della dea della neve Umapati discesa tra gli uomini."
  },
  AvgDialog_145510_Content_2 = {
    Text = "I Prigionieri della Neve"
  },
  AvgDialog_145510_Content_20 = {
    Text = "(È un po' diverso da quello che c'era scritto nel dépliant...)"
  },
  AvgDialog_145510_Content_21 = {
    Text = "Oh, se sei davvero la dea della neve, mostraci un po' di magia!"
  },
  AvgDialog_145510_Content_22 = {
    Text = "Lo Scherno dell'Uomo suscitò qualche risata sparsa."
  },
  AvgDialog_145510_Content_23 = {
    Text = "No, al momento non sono ancora in grado di farlo."
  },
  AvgDialog_145510_Content_24 = {
    Text = "La ragazza tirò fuori con nonchalance una mela rossa e brillante, mordendola."
  },
  AvgDialog_145510_Content_25 = {
    Text = "Perché ho perso sette artefatti magici, i sette tesori che amo più di ogni cosa."
  },
  AvgDialog_145510_Content_26 = {
    Text = "Sono la Mela d'Oro di Eris, lo Specchio di Yata, la Piuma di Ma'at, la Chiave di Salomone, l'Occhio di Balor..."
  },
  AvgDialog_145510_Content_27 = {
    Text = "Questi tuoi artefatti magici provengono da civiltà davvero numerose e disparate!"
  },
  AvgDialog_145510_Content_28 = {
    Text = "Di nuovo una risata generale, ma la ragazza non se ne curava affatto."
  },
  AvgDialog_145510_Content_29 = {
    Text = "E poi il Filo delle Moirae e la Corona di Arianna."
  },
  AvgDialog_145510_Content_3 = {
    Text = "La più grande bugia di questo mondo,\nnata dalle labbra di chi non mente mai."
  },
  AvgDialog_145510_Content_30 = {
    Text = "Il Filo delle Moirae… il telaio delle Tre Parche…"
  },
  AvgDialog_145510_Content_31 = {
    Text = "Che sia proprio questo il \"Destino che dobbiamo accogliere\" di cui parlava Arachne?"
  },
  AvgDialog_145510_Content_32 = {
    Text = "Estrai dal doppio fondo della tasca quel piccolo rotolo di Filo; il Filo luminoso scintilla tra le tue dita con colori cangianti difficili da cogliere a occhio nudo."
  },
  AvgDialog_145510_Content_33 = {
    Text = "Aspetta ancora un po', agisci con cautela."
  },
  AvgDialog_145510_Content_34 = {
    Text = "Il Destino ci ha guidati fin qui, ma non ci ha rivelato il ruolo che il proprietario del manuale ricopre in questa storia."
  },
  AvgDialog_145510_Content_35 = {
    Text = "*Coff, coff!*"
  },
  AvgDialog_145510_Content_36 = {
    Text = "Se avete capito tutto, lasciate qui la vostra Offerta!"
  },
  AvgDialog_145510_Content_37 = {
    Text = "Né più né meno, Purché cinquanta Rosa dorata! Così la dea della montagna innevata Umapati potrà sentire la vostra sincerità!"
  },
  AvgDialog_145510_Content_38 = {
    Text = "Come dea della montagna innevata, una volta riuniti i sette grandi artefatti e rinata sotto la luna nuova, risponderò alle vostre preghiere cento, mille volte tanto!"
  },
  AvgDialog_145510_Content_39 = {
    Text = "Dopo tutto questo discorso confuso, alla fine è venuta a chiedere donazioni!"
  },
  AvgDialog_145510_Content_4 = {
    Text = "-Altitudine 4000 m-"
  },
  AvgDialog_145510_Content_40 = {
    Text = "Da quando la dea della montagna innevata si è manifestata, le spedizioni venute ad arrampicarsi non sono mille, ma ottocento, e ognuna si porta il proprio vitto."
  },
  AvgDialog_145510_Content_41 = {
    Text = "Un tipo come te, che pensa Solo a ottenere tutto senza faticare, farebbe meglio a togliersi dai piedi e imparare a realizzare i propri desideri con le proprie mani laboriose!"
  },
  AvgDialog_145510_Content_42 = {
    Text = "I curiosi si dispersero in un attimo."
  },
  AvgDialog_145510_Content_43 = {
    Text = "Approfittando del momento, ti fai largo controcorrente tra la folla per avvicinarti alla ragazza solitaria e rivolgerle qualche domanda."
  },
  AvgDialog_145510_Content_44 = {
    Text = "Scusi… Vorrei chiederle, è lei ad aver spedito questo opuscolo?"
  },
  AvgDialog_145510_Content_45 = {
    Text = "Tiri fuori quell'opuscolo promozionale sgargiante e bussi sulle parole \"Il Grande Maestro, Il Prescelto della Divinità, Amico del Cuore del Re degli Dei\"."
  },
  AvgDialog_145510_Content_46 = {
    Text = "Gli occhi della ragazza si illuminarono all'istante."
  },
  AvgDialog_145510_Content_47 = {
    Text = "<Shake:Ohhh! Hai davvero preso il mio opuscolo di reclutamento!>"
  },
  AvgDialog_145510_Content_48 = {
    Text = "Allora, dove sono i tuoi dodici apostoli e gli altri fedeli?"
  },
  AvgDialog_145510_Content_49 = {
    Text = "Questa è una lunga storia. La mia grandiosa setta è stata vittima di un vile complotto: tra i dodici apostoli, uno nascondeva in cuor suo propositi malvagi, bramando di accaparrarsi da solo la gloria suprema."
  },
  AvgDialog_145510_Content_5 = {
    Text = "È qui il posto."
  },
  AvgDialog_145510_Content_50 = {
    Text = "Gli altri fedeli furono sobillati e divisi, finché la setta non si sbriciolò. Rimasi sola io, la Maestra, a intraprendere un lungo e arduo viaggio per far rinascere la setta."
  },
  AvgDialog_145510_Content_51 = {
    Text = "Chiunque sponsorizzi ora mille Rosa dorata potrà salire al primo posto dei nuovi Dodici Apostoli, diventando il mio discepolo numero uno…"
  },
  AvgDialog_145510_Content_52 = {
    Text = "Ma poco fa, quando ti esibivi per strada, dicevi di essere Umapati, la dea della montagna di neve."
  },
  AvgDialog_145510_Content_53 = {
    Text = "Quindi fuori casa l'Identità te la dai da sola, è così?"
  },
  AvgDialog_145510_Content_54 = {
    Text = "Bah, Scoperta."
  },
  AvgDialog_145510_Content_55 = {
    Text = "La ragazza balzò in piedi e in un attimo sparì dietro una tenda."
  },
  AvgDialog_145510_Content_56 = {
    Text = "Stavi per inseguire la ragazza quando qualcuno ti diede un colpetto sulla schiena."
  },
  AvgDialog_145510_Content_57 = {
    Text = "Voi due, siete qui per scalare la montagna?"
  },
  AvgDialog_145510_Content_58 = {Text = "Eh? Noi?"},
  AvgDialog_145510_Content_59 = {
    Text = "Sì, a vedervi si capisce subito che siete persone di riguardo. Non siete del posto, vero?"
  },
  AvgDialog_145510_Content_6 = {
    Text = "Questo è l'ultimo punto di rifornimento sulla via per l'Everest."
  },
  AvgDialog_145510_Content_60 = {
    Text = "Ultimamente, chi mai arriva in questa landa desolata se non per raggiungere la dea in cima alla montagna, quella che esaudisce ogni desiderio?"
  },
  AvgDialog_145510_Content_61 = {
    Text = "Voi due avete poca attrezzatura, sembra che abbiate intenzione di approfittare dei rifornimenti altrui. Che coincidenza, no?"
  },
  AvgDialog_145510_Content_62 = {
    Text = "<Yellow:Mi chiamo Naraka. Sono una guida Sherpa locale.>"
  },
  AvgDialog_145510_Content_63 = {
    Text = "La spedizione a cui apparteniamo è finanziata dalla Fondazione Green, i rifornimenti sono già pronti, aspettiamo solo \"l'anima predestinata\" per raggiungere insieme la vetta."
  },
  AvgDialog_145510_Content_64 = {
    Text = "Una persona del destino?"
  },
  AvgDialog_145510_Content_65 = {
    Text = "Sì, vivo ai piedi della montagna innevata da molti anni. Chi ha la capacità di raggiungere la vetta—"
  },
  AvgDialog_145510_Content_66 = {
    Text = "Indicò i propri occhi."
  },
  AvgDialog_145510_Content_67 = {
    Text = "Questi occhi lo capiscono a prima vista."
  },
  AvgDialog_145510_Content_68 = {
    Text = "Oh? Perché non ce lo racconti?"
  },
  AvgDialog_145510_Content_69 = {
    Text = "Prima di tutto, naturalmente, un'età adeguata, un fisico robusto e un'Energia spirituale stabile."
  },
  AvgDialog_145510_Content_7 = {
    Text = "Più in su, i veicoli non possono arrivare."
  },
  AvgDialog_145510_Content_70 = {
    Text = "Oltre a ciò, ancora più importante è la tenacia e la determinazione di raggiungere la vetta — la determinazione di non tirare l'ultimo respiro Purché non si sia arrivati in cima."
  },
  AvgDialog_145510_Content_71 = {
    Text = "Tirare l'ultimo respiro in cima — sembra quasi che tu non abbia intenzione di lasciarci scendere vivi?"
  },
  AvgDialog_145510_Content_72 = {
    Text = "Eh, non si può dire così. Una volta in cima, incontrando la dea della montagna innevata, qualsiasi desiderio può avverarsi. A quel punto, una cosa da niente come scendere, vale ancora la pena preoccuparsene?"
  },
  AvgDialog_145510_Content_73 = {
    Text = "Venite, seguitemi al campo base. Vi garantisco che sarete soddisfatti."
  },
  AvgDialog_145510_Content_74 = {
    Text = "Lanci uno sguardo a William, chiedendo silenziosamente la sua opinione."
  },
  AvgDialog_145510_Content_75 = {
    Text = "Andiamo. Non so nemmeno dove sia finita quella ragazza di prima."
  },
  AvgDialog_145510_Content_76 = {
    Text = "Se si vuole davvero scalare la montagna, una guida locale e rifornimenti completi sono indispensabili."
  },
  AvgDialog_145510_Content_77 = {
    Text = "Andiamo, diamo un'occhiata al campo."
  },
  AvgDialog_145510_Content_79 = {
    Text = "Che bella voce…"
  },
  AvgDialog_145510_Content_8 = {
    Text = "Apri lo sportello dell'auto, e l'aria — impregnata del profumo bruciato del tè al burro di yak, del tanfo degli animali e del freddo sottile e pungente tipico dell'altopiano — si precipita impaziente nelle tue narici."
  },
  AvgDialog_145510_Content_80 = {
    Text = "Mi sembra di averla già sentita."
  },
  AvgDialog_145510_Content_81 = {
    Text = "Come se scorresse giù da una lontana galassia stellata, o come se emergesse placidamente dalle profondità dell'Aequor sconfinato."
  },
  AvgDialog_145510_Content_83 = {
    Text = "Il canto proveniva dalla direzione del campo, filo dopo filo, via via più nitido, come nebbia che si dirada e rivela il chiarore della luna piena."
  },
  AvgDialog_145510_Content_85 = {
    Text = "In uno spiazzo ai margini del campo, una giovane dal volto pieno di tristezza cantava a piena voce."
  },
  AvgDialog_145510_Content_86 = {
    Text = "Tutti i passanti rallentarono involontariamente il passo e trattennero il respiro — nel timore di disturbare quella voce che scorreva come luce di luna."
  },
  AvgDialog_145510_Content_88 = {
    Text = "Solo quando il brano giunse al termine, lei si riscosse dal mondo in cui era immersa, accorgendosi finalmente della vostra presenza."
  },
  AvgDialog_145510_Content_89 = {
    Text = "Ci sono nuovi membri?"
  },
  AvgDialog_145510_Content_9 = {
    Text = "Un cielo plumbeo preme sull'orizzonte del mondo. Le cime innevate si ergono come una fila di divinità silenziose, al confine tra il crepuscolo e le nuvole."
  },
  AvgDialog_145511_Content_1 = {
    Text = "Qualcosa non va."
  },
  AvgDialog_145511_Content_10 = {
    Text = "No, non solo il mantello: da dietro di lui si sollevò anche qualcos'altro."
  },
  AvgDialog_145511_Content_11 = {
    Text = "Un paio di ali."
  },
  AvgDialog_145511_Content_12 = {
    Text = "Un paio di ali nere — un nero intenso, profondo, che incuteva un senso di presagio in chiunque le fissasse."
  },
  AvgDialog_145511_Content_13 = {
    Text = "<BigShake:Con questo corpo immortale, respingo ogni Cladi!>"
  },
  AvgDialog_145511_Content_14 = {
    Text = "Castor spiegò le Ali Spiegate e la Neve accumulata esplose alle sue spalle tracciando un arco bianco e luminoso, Quasi verticale."
  },
  AvgDialog_145511_Content_15 = {
    Text = "Si lancia dal pendio innevato, coprendo una distanza che altrimenti non avrebbe mai potuto attraversare—"
  },
  AvgDialog_145511_Content_16 = {
    Text = "E poi si gettò tra il Wendigo ed Evelyn."
  },
  AvgDialog_145511_Content_17 = {
    Text = "Le sue ali si aprono ampiamente, formando un'enorme barriera nera come la pece dietro di lui."
  },
  AvgDialog_145511_Content_18 = {
    Text = "Le fauci del Wendigo, pronte a chiudersi, si abbatterono sull'ala destra di Castor, strappandone via di radice un'intera ciocca di Piume."
  },
  AvgDialog_145511_Content_19 = {
    Text = "<Shake:Ugh!!>"
  },
  AvgDialog_145511_Content_2 = {
    Text = "Con la coda dell'occhio, nell'angolo del branco, il Wendigo più alto e più magro non aveva ancora attaccato dall'inizio del combattimento."
  },
  AvgDialog_145511_Content_20 = {
    Text = "Castor emette un grugnito soffocato, ma non si ritrae."
  },
  AvgDialog_145511_Content_21 = {
    Text = "Non sprecare l'occasione che ha creato Castor, adesso!"
  },
  AvgDialog_145511_Content_3 = {
    Text = "Stava aspettando, osservando l'anello più debole della squadra alpinistica."
  },
  AvgDialog_145511_Content_4 = {
    Text = "Aggira voi tre e si avventa su Evelyn."
  },
  AvgDialog_145511_Content_5 = {
    Text = "Evelyn——!"
  },
  AvgDialog_145511_Content_6 = {
    Text = "Caraboo era troppo lontana; nel momento in cui gridò, sapeva già di non fare in tempo."
  },
  AvgDialog_145511_Content_7 = {
    Text = "— Ma qualcun altro ce la fece."
  },
  AvgDialog_145511_Content_8 = {
    Text = "Castor scattò in Corsa e allungò la mano per sciogliere i lacci del mantello."
  },
  AvgDialog_145511_Content_9 = {
    Text = "Il mantello sventolò fragorosamente dietro di lui—"
  },
  AvgDialog_145512_Content_1 = {
    Text = "È finita, perdente."
  },
  AvgDialog_145512_Content_10 = {
    Text = "Il tuo padrone ti ha detto così: tesoro mio, hai faticato tanto, questa è la ricompensa per tutto ciò che hai dato."
  },
  AvgDialog_145512_Content_11 = {
    Text = "Che dovevi solo scalare personalmente la vetta innevata, sconfiggere i Rivali e riprenderti la tua corona?"
  },
  AvgDialog_145512_Content_12 = {
    Text = "Peccato, <BigShake:SEI——STA——TO——IN——GAN——NA——TO——!!>"
  },
  AvgDialog_145512_Content_13 = {
    Text = "Un pedone sarà sempre e solo un pedone, e quando necessario, diventerà anche un pedone sacrificabile."
  },
  AvgDialog_145512_Content_14 = {
    Text = "Quando il valore che puoi offrire è stato sfruttato fino all'ultimo, quando cominci a sentirti insoddisfatto… è giunto il momento di offrire la tua testa."
  },
  AvgDialog_145512_Content_15 = {
    Text = "Come uno dei sette Sacrifici sull'altare, hai qualche ultima parola da dire?"
  },
  AvgDialog_145512_Content_16 = {
    Text = "Non avrei dovuto… non avrei dovuto fidarmi di nessuno…"
  },
  AvgDialog_145512_Content_17 = {
    Text = "Fin dall'inizio, fidarsi della benevolenza di quella signora… Dopo… il desiderio di vendetta per i miei simili…"
  },
  AvgDialog_145512_Content_18 = {
    Text = "E ora, spinto dalla promessa di qualcuno…"
  },
  AvgDialog_145512_Content_19 = {
    Text = "Va bene, va bene, il tempo concesso per le ultime parole è solo una cortesia, nessuno si preoccupa davvero della tua miserabile vita fallita."
  },
  AvgDialog_145512_Content_2 = {
    Text = "Caraboo scavalcò Helot inginocchiato a terra e raccolse delicatamente il bulbo oculare dal cerchio magico."
  },
  AvgDialog_145512_Content_20 = {
    Text = "Le cose che non riesci a ottenere da solo, rubale, ingannale, strappale — a cosa serve aspettare che qualcuno te le elargisca."
  },
  AvgDialog_145512_Content_21 = {
    Text = "Non c'è più tempo, il resto della riflessione, aspetta la prossima vita per continuarla."
  },
  AvgDialog_145512_Content_22 = {
    Text = "Caraboo alzò la mano e lanciò delicatamente il bulbo oculare, che sprofondò nel corpo di Helot."
  },
  AvgDialog_145512_Content_23 = {
    Text = "Subito dopo, si udì un crepitio, il suono dell'Ingestione."
  },
  AvgDialog_145512_Content_24 = {
    Text = "Mangia, mangia."
  },
  AvgDialog_145512_Content_25 = {
    Text = "Il corpo di Helot collassò rapidamente, lasciando una pozza color Sangue."
  },
  AvgDialog_145512_Content_26 = {
    Text = "Esatto, è proprio così, ti mangeranno, finché non rimarrà nemmeno un osso…"
  },
  AvgDialog_145512_Content_27 = {
    Text = "Dal Volto di Caraboo, intravedi una certa crudele soddisfazione."
  },
  AvgDialog_145512_Content_28 = {
    Text = "Guarda, le tue misere conseguenze hanno tutte Origine dalla tua stupidità, dall'Origine della tua credulità verso Una Bugia."
  },
  AvgDialog_145512_Content_29 = {Text = "Caraboo…"},
  AvgDialog_145512_Content_3 = {
    Text = "Anche il tuo desiderio diventerà concime per nutrire la montagna innevata."
  },
  AvgDialog_145512_Content_30 = {
    Text = "Hmm? Ti serve qualcosa?"
  },
  AvgDialog_145512_Content_31 = {
    Text = "Lei si voltò, osservando attentamente la tua espressione."
  },
  AvgDialog_145512_Content_32 = {
    Text = "Lei assunse il suo solito atteggiamento birichino e vezzoso, ma Tu riuscisti comunque a leggere, dall'angolo dei suoi occhi, un filo di arroganza che tradiva il suo Occulto risentimento."
  },
  AvgDialog_145512_Content_33 = {
    Text = "Posso dare un'occhiata a quei sei artefatti?"
  },
  AvgDialog_145512_Content_34 = {Text = "Ma certo!"},
  AvgDialog_145512_Content_35 = {
    Text = "Caraboo si fece da parte, cedendoti la posizione di fronte al cerchio magico."
  },
  AvgDialog_145512_Content_36 = {
    Text = "Il Filo di Moirae — un dono di Arachne."
  },
  AvgDialog_145512_Content_37 = {
    Text = "Lo Specchio di Yata, recuperato sulla riva del lago ghiacciato dove Tintura vagava."
  },
  AvgDialog_145512_Content_38 = {
    Text = "La Piuma di Ma'at, caduta tra Neve e Vento dopo la partenza di Castor."
  },
  AvgDialog_145512_Content_39 = {
    Text = "L'Occhio di Balor, cristallizzato nella pozza di Sangue di Helot."
  },
  AvgDialog_145512_Content_4 = {
    Text = "Quel bulbo oculare divenne improvvisamente mostruoso, la pupilla rosso sangue si spalancò emanando un bagliore sanguigno."
  },
  AvgDialog_145512_Content_40 = {
    Text = "la Mela d'Oro, Caraboo l'ha tirata fuori da chissà quale fagotto."
  },
  AvgDialog_145512_Content_41 = {
    Text = "La Chiave di Salomone, in realtà è la Chiave d'argento che porti sempre con te."
  },
  AvgDialog_145512_Content_42 = {
    Text = "E poi, quella trovata dalla spedizione precedente, la Corona di Arianna…"
  },
  AvgDialog_145512_Content_43 = {
    Text = "Rimani senza parole."
  },
  AvgDialog_145512_Content_44 = {
    Text = "Corona di Arianna… che razza di Corona di Arianna è questa, non è forse la <Yellow:Corona di Tulu>!"
  },
  AvgDialog_145512_Content_45 = {
    Text = "Cos'hai da stupirsi tanto? Anche la Mela d'Oro non è dorata, no?"
  },
  AvgDialog_145512_Content_46 = {
    Text = "Ma, la Corona di Tulu, perché mai si troverebbe qui?"
  },
  AvgDialog_145512_Content_47 = {
    Text = "Perché è il Suo strumento rituale, la Sua offerta, il Suo ingrediente preferito."
  },
  AvgDialog_145512_Content_48 = {
    Text = "Mentre le parole di Caraboo si spengono, la Terra trema all'improvviso."
  },
  AvgDialog_145512_Content_49 = {
    Text = "Cosa sta succedendo?"
  },
  AvgDialog_145512_Content_5 = {
    Text = "No, come è possibile...!"
  },
  AvgDialog_145512_Content_50 = {
    Text = "Sta ridendo!"
  },
  AvgDialog_145512_Content_51 = {
    Text = "…Ridendo?"
  },
  AvgDialog_145512_Content_52 = {
    Text = "La vetta della montagna trema a ondate, Come Se una giovane fanciulla in fiore, avendo assistito a qualcosa di divertente, ridesse scossa da fremiti, agitandosi tutta."
  },
  AvgDialog_145512_Content_53 = {
    Text = "La Neve accumulata cade scuotendosi via."
  },
  AvgDialog_145512_Content_54 = {
    Text = "Quella cima aguzza non è una montagna, bensì un enorme verme che si annida sulla vetta, simile a un serpente gigantesco capace di inghiottire il cielo e divorare la Terra."
  },
  AvgDialog_145512_Content_55 = {
    Text = "A causa della debolezza degli esseri umani, incapaci di affrontare la realtà, hanno scelto di credere a Una Bugia, affidando i propri desideri a Divinità dell'Illusione."
  },
  AvgDialog_145512_Content_56 = {
    Text = "Non hanno mai pensato che — anche le cosiddette Divinità possano mentire. Perché anche le Divinità hanno desideri che vogliono realizzare."
  },
  AvgDialog_145512_Content_57 = {
    Text = "Il desiderio delle Divinità è — divorarli."
  },
  AvgDialog_145512_Content_58 = {
    Text = "Corona, Filo, Chiave d'Argento, frutto proibito, piuma alata, specchio lucente, occhio magico. Sette strumenti rituali, Sacrifici forgiati con la Vita di quegli esseri Avidi."
  },
  AvgDialog_145512_Content_59 = {
    Text = "Tutto ciò che siete voi non è altro che un pasto abbondante per Lei."
  },
  AvgDialog_145512_Content_6 = {
    Text = "L'Occhio di Balor, l'occhio demoniaco del dio malvagio. In grado di distruggere tutto ciò su cui posa lo sguardo, eppure è la Sua unica debolezza."
  },
  AvgDialog_145512_Content_60 = {
    Text = "Ora, Egli ha ottenuto ciò che voleva, certo che dovrebbe ridere!"
  },
  AvgDialog_145512_Content_61 = {
    Text = "Ora che siamo a questo punto, non è il momento di dirci la verità?"
  },
  AvgDialog_145512_Content_62 = {
    Text = "Non sei affatto capitata in questo viaggio per caso, come hai recitato."
  },
  AvgDialog_145512_Content_63 = {
    Text = "Anzi, è stato sotto la tua guida che l'intera spedizione alpinistica è arrivata fin qui."
  },
  AvgDialog_145512_Content_64 = {
    Text = "L'incontro casuale nella grotta all'Inizio con Castor, la scelta di Tintura di andare a osservare il lago ghiacciato…"
  },
  AvgDialog_145512_Content_65 = {
    Text = "E anche questo Helot che ci ha seguiti per tutto il tempo… in realtà avevi previsto tutto fin dall'Inizio."
  },
  AvgDialog_145512_Content_66 = {
    Text = "Chi sei davvero?"
  },
  AvgDialog_145512_Content_7 = {
    Text = "Il tuo padrone non te l'ha detto? Questo bulbo oculare, solo impregnato del tuo Banchetto di Sangue, merita di essere chiamato \"Occhio di Balor\"."
  },
  AvgDialog_145512_Content_8 = {
    Text = "Lui ha detto..."
  },
  AvgDialog_145512_Content_9 = {
    Text = "Shh, lascia che lo indovini."
  },
  AvgDialog_145513_Content_1 = {
    Text = "Patto dei Bugiardi"
  },
  AvgDialog_145513_Content_10 = {
    Text = "<Yellow:Sei stata tu a bruciare il mio pacco>? Vedrai che ti smascherero, faccia da impostora—"
  },
  AvgDialog_145513_Content_11 = {
    Text = "Lei afferrò con forza le guance di Naraka, tirandole ai lati."
  },
  AvgDialog_145513_Content_12 = {
    Text = "<Shake:ASPETTA!>"
  },
  AvgDialog_145513_Content_13 = {Text = "Strappo—"},
  AvgDialog_145513_Content_14 = {
    Text = "Il guscio noto come \"Naraka\" viene spaccato in due di netto, come una bambola di gomma tra le mani di un bambino dispettoso."
  },
  AvgDialog_145513_Content_15 = {
    Text = "Da quella crepa sgorgava gorgogliando un fumo nero chiamato \"Caos\"."
  },
  AvgDialog_145513_Content_16 = {
    Text = "Il fumo si agitò, si avvolse su se stesso, si condensò, poi allungò con leggerezza una rosa."
  },
  AvgDialog_145513_Content_17 = {
    Text = "Ci rivediamo, vecchio amico."
  },
  AvgDialog_145513_Content_18 = {
    Text = "Prima di fare due chiacchiere, facciamo un po' di riscaldamento per calmare la nostra piccola impostora furiosa?"
  },
  AvgDialog_145513_Content_2 = {
    Text = "All'estremità del Filo, una fanciulla emerse dall'ombra."
  },
  AvgDialog_145513_Content_3 = {
    Text = "Ehi, piccola impostora, hai coinvolto anche te stessa?"
  },
  AvgDialog_145513_Content_4 = {
    Text = "Le parole di Naraka non fanno che inasprire il temperamento di una ragazza che già chinava la testa per la frustrazione."
  },
  AvgDialog_145513_Content_5 = {
    Text = "Per te è facile."
  },
  AvgDialog_145513_Content_6 = {
    Text = "Caraboo alzò la testa, i suoi occhi ardenti di rabbia fissi su Naraka."
  },
  AvgDialog_145513_Content_7 = {
    Text = "Smettila di fingere. Una guida Sherpa, inghiottita dal ventre della montagna, e hai ancora voglia di scherzare?"
  },
  AvgDialog_145513_Content_8 = {
    Text = "Dal momento in cui ti ho visto per la prima volta, ho capito che anche tu sei un impostore."
  },
  AvgDialog_145513_Content_9 = {
    Text = "Caraboo si lanciò su di lei. Questa volta, non le permise di scappare."
  },
  AvgDialog_145514_Content_1 = {
    Text = "L'ultimo Wendigo si dissolse nell'ombra di Castor."
  },
  AvgDialog_145514_Content_10 = {
    Text = "Forse i rapporti tra le persone Iniziano proprio quando si rivela un piccolo segreto, no?"
  },
  AvgDialog_145514_Content_11 = {
    Text = "Senza che Te ne accorgessi, Caraboo ti si era avvicinata e, con un sorriso, aveva pronunciato davanti a Tu esattamente ciò che stavi pensando."
  },
  AvgDialog_145514_Content_12 = {
    Text = "Scambiarsi segreti non è una cosa a senso unico."
  },
  AvgDialog_145514_Content_13 = {
    Text = "Quella Zia Rosa che hai chiamato tante volte — è qualcuno di molto importante per Tu?"
  },
  AvgDialog_145514_Content_14 = {
    Text = "Ovviamente me l'ero inventata. Non ci avrai mica creduto davvero?"
  },
  AvgDialog_145514_Content_15 = {
    Text = "Eheh, ingannare uno sciocco non è niente di speciale, ma ingannare Tu non è affatto facile."
  },
  AvgDialog_145514_Content_16 = {
    Text = "Convincere i Wendigo che fossi stato ammaliato è molto più difficile che ingannare me."
  },
  AvgDialog_145514_Content_17 = {
    Text = "Possono sentire la voce nel tuo cuore e poi ripeterla attraverso il Vento."
  },
  AvgDialog_145514_Content_18 = {
    Text = "E chi può saperlo? Forse la dea della Neve ha così tante storie nel cuore che ognuna sembra vera?"
  },
  AvgDialog_145514_Content_19 = {
    Text = "Caraboo scivolò via con leggerezza, schivando la questione con una battuta spiritosa."
  },
  AvgDialog_145514_Content_2 = {
    Text = "Poi il Vento che sfiorava le orecchie divenne improvvisamente limpido. Non portava più con sé alcun suono."
  },
  AvgDialog_145514_Content_20 = {
    Text = "Se non vuoi parlarne, di certo non ti costringeremo."
  },
  AvgDialog_145514_Content_21 = {
    Text = "Ma la sincerità è qualcosa di molto prezioso — anche se sei un impostore, è meglio non deludere le aspettative di tutti."
  },
  AvgDialog_145514_Content_22 = {
    Text = "Questo è il mio sincero consiglio, sta a te decidere se seguirlo."
  },
  AvgDialog_145514_Content_23 = {
    Text = "William finì di parlare e si portò in testa al gruppo."
  },
  AvgDialog_145514_Content_24 = {Text = "Hmph."},
  AvgDialog_145514_Content_25 = {
    Text = "Benefattore, non sareste così insensibile come lui, vero?"
  },
  AvgDialog_145514_Content_26 = {
    Text = "Ho trascorso molto tempo a lavorare con William. Non è un uomo che dice nulla di superfluo."
  },
  AvgDialog_145514_Content_27 = {
    Text = "Per quanto ricordo, ogni consiglio che ha dato si è rivelato efficace."
  },
  AvgDialog_145514_Content_28 = {
    Text = "<Shake:Boo-hoo, benefattore, a quanto pare siete crudele quanto lui...>"
  },
  AvgDialog_145514_Content_29 = {
    Text = "Caraboo si allontanò fingendo di essere triste, mentre tu raggiunsi William, che stava chiacchierando con Naraka."
  },
  AvgDialog_145514_Content_3 = {
    Text = "Il silenzio significava sicurezza, eppure quella sicurezza lasciava un senso di vuoto malinconico."
  },
  AvgDialog_145514_Content_30 = {
    Text = "Con un cenno degli occhi ti indicò di fare qualche passo da parte, finché chi vi stava accanto non poteva più sentire i vostri sussurri."
  },
  AvgDialog_145514_Content_31 = {
    Text = "Nel combattimento di poco fa contro il Wendigo, hai notato qualcosa di strano?"
  },
  AvgDialog_145514_Content_32 = {Text = "Dove?"},
  AvgDialog_145514_Content_33 = {Text = "Naraka."},
  AvgDialog_145514_Content_34 = {
    Text = "Ripensaci: da quando quelle voci si sono levate nel vento, a quando il Wendigo è apparso, fino all'accerchiamento di poco fa—"
  },
  AvgDialog_145514_Content_35 = {
    Text = "Naraka, c'è stato un solo momento in cui un qualsiasi Wendigo le si è avvicinato?"
  },
  AvgDialog_145514_Content_36 = {
    Text = "Caraboo è stata aggredita da un Wendigo mentre recitava la parte della vittima, Evelyn è stata abbattuta dal Wendigo più alto, Castor si è visto strappare via un pezzo di Piuma…"
  },
  AvgDialog_145514_Content_37 = {
    Text = "Anche la volta precedente, quando i Wendigo tentarono di ammaliarla, Naraka sembrava non aver subito alcun effetto."
  },
  AvgDialog_145514_Content_38 = {
    Text = "Quindi intendi dire..."
  },
  AvgDialog_145514_Content_39 = {
    Text = "Non voglio dire nulla in particolare."
  },
  AvgDialog_145514_Content_4 = {
    Text = "Evelyn gettò uno sguardo alle ali di Castor, ma la sua espressione rimase impassibile, Come Se fosse la cosa più naturale del mondo che ognuno nascondesse un paio di ali."
  },
  AvgDialog_145514_Content_40 = {
    Text = "Ci vorranno ancora quattro o cinque giorni per salire, e non abbiamo altre guide con cui sostituirla."
  },
  AvgDialog_145514_Content_41 = {
    Text = "Spero di essere io quello che si preoccupa troppo, ma dobbiamo restare vigili."
  },
  AvgDialog_145514_Content_42 = {
    Text = "In questo Sentiero abbiamo già perso una Tintura. Non voglio che, per mia negligenza, qualcun altro rimanga su questa montagna."
  },
  AvgDialog_145514_Content_43 = {
    Text = "Il Vento soffiava aggirando il bordo esterno della cresta rocciosa."
  },
  AvgDialog_145514_Content_44 = {
    Text = "Aggirò la sagoma accovacciata in lontananza, intenta a picchiettare il ghiaccio."
  },
  AvgDialog_145514_Content_45 = {
    Text = "La punta del piccone di Naraka batteva sui frammenti di ghiaccio sotto le suole, emettendo un suono regolare e cadenzato come un pendolo."
  },
  AvgDialog_145514_Content_46 = {
    Text = "-Altitudine 6.500 m-"
  },
  AvgDialog_145514_Content_5 = {
    Text = "Lascia che ti fasci le ferite."
  },
  AvgDialog_145514_Content_6 = {
    Text = "Mi dispiace… di averlo tenuto nascosto per tutto questo tempo."
  },
  AvgDialog_145514_Content_7 = {
    Text = "Non importa. Siamo tutti qui per cercare un Miracolo straordinario capace di far risorgere i morti… in un momento come questo, Scoprire l'esistenza di qualcosa che sfida il senso comune è una buona notizia."
  },
  AvgDialog_145514_Content_8 = {
    Text = "Dopotutto, non hai mai tolto quel mantello nemmeno per dormire — chiunque avrebbe capito che nascondevi qualcosa."
  },
  AvgDialog_145514_Content_9 = {
    Text = "Nonostante le parole di lieve rimprovero, sentivi chiaramente che, dopo questa battaglia, tutti stavano abbassando le proprie difese e cominciavano ad affiatarsi."
  },
  AvgDialog_145515_Content_1 = {
    Text = "Sette Fili del Destino"
  },
  AvgDialog_145515_Content_10 = {
    Text = "<Shake:Guardate laggiù——!>"
  },
  AvgDialog_145515_Content_11 = {
    Text = "Prima ancora di finire la frase, si lanciò di corsa verso il pendio dall'altro lato."
  },
  AvgDialog_145515_Content_12 = {
    Text = "Era un altare esagonale."
  },
  AvgDialog_145515_Content_13 = {
    Text = "Al centro dell'altare era già stata posta una Corona."
  },
  AvgDialog_145515_Content_14 = {
    Text = "La donna avvolta nelle catene passava in rassegna i tesori sottratti. %player%La Chiave d'Argento e il Filo nella tasca, lo specchio, la Piuma d'Onice e la Mela d'oro nel fagotto di Caraboo."
  },
  AvgDialog_145515_Content_15 = {
    Text = "Il bulbo oculare di Balor?"
  },
  AvgDialog_145515_Content_16 = {
    Text = "Helot emise una risatina sprezzante, poi conficcò le sue unghie affilate nella palla chiodata al suo fianco."
  },
  AvgDialog_145515_Content_17 = {
    Text = "Con un suono viscido, la palla chiodata emise uno strano rumore appiccicoso."
  },
  AvgDialog_145515_Content_18 = {
    Text = "Lei mescolò, scavò… finché non ne estrasse un bulbo oculare insanguinato."
  },
  AvgDialog_145515_Content_19 = {
    Text = "Te li ho dati tutti, ghiottone."
  },
  AvgDialog_145515_Content_2 = {
    Text = "-Quota 8800 metri-"
  },
  AvgDialog_145515_Content_20 = {
    Text = "Dispose i sei oggetti preziosi in ciascun angolo dell'altare."
  },
  AvgDialog_145515_Content_21 = {
    Text = "Ora è il momento di esaudire il mio desiderio."
  },
  AvgDialog_145515_Content_22 = {
    Text = "Lei chiuse gli occhi e rimase in silenzio."
  },
  AvgDialog_145515_Content_23 = {
    Text = "Falla rinascere… lascia che io uccida il mio nemico con le mie stesse mani e compia la mia vendetta tanto attesa."
  },
  AvgDialog_145515_Content_24 = {
    Text = "Un vento gelido soffiava sulle vette de I Prigionieri della Neve. Il suo desiderio non ricevette alcuna risposta."
  },
  AvgDialog_145515_Content_25 = {
    Text = "Perché? Non ti ho forse già consegnato le sette Offerte?"
  },
  AvgDialog_145515_Content_26 = {
    Text = "La voce accusatoria di Helot riecheggiò tra le lontane vette, scatenando una serie di piccole valanghe."
  },
  AvgDialog_145515_Content_27 = {
    Text = "Perché una delle offerte è falsa, forse?"
  },
  AvgDialog_145515_Content_28 = {Text = "Chi?!"},
  AvgDialog_145515_Content_29 = {
    Text = "Caraboo saltellò avanti con leggerezza, Come Se Helot non contasse nulla ai suoi occhi."
  },
  AvgDialog_145515_Content_3 = {
    Text = "Questo è un luogo dove le orme dell'umanità non hanno mai messo piede."
  },
  AvgDialog_145515_Content_30 = {
    Text = "Voi altri pensate Solo ai vostri desideri, senza mai chiedervi cosa voglia davvero la Divinità come offerta."
  },
  AvgDialog_145515_Content_31 = {
    Text = "la Mela d'Oro, la Mela d'Oro — non crederai mica che Purché sia una Mela dorata tu abbia scelto quella giusta?"
  },
  AvgDialog_145515_Content_32 = {
    Text = "Prese in mano la Mela d'Oro sull'altare e la morse delicatamente."
  },
  AvgDialog_145515_Content_33 = {
    Text = "Mmm, è proprio quella che pensavo."
  },
  AvgDialog_145515_Content_34 = {
    Text = "La carta stagnola dorata si staccò, rivelando la vera natura dell'interno."
  },
  AvgDialog_145515_Content_35 = {
    Text = "Snack, caramella, massa di cacao — chiamala come vuoi, in ogni caso è cioccolato, ordinario quanto non mai."
  },
  AvgDialog_145515_Content_36 = {
    Text = "<BigShake:Ta-dà! La Benedizione della fata, il sapore supremo!>"
  },
  AvgDialog_145515_Content_37 = {
    Text = "Tu... bugiardo..."
  },
  AvgDialog_145515_Content_38 = {
    Text = "Un bandito non è poi tanto meglio di un bugiardo, no?"
  },
  AvgDialog_145515_Content_39 = {
    Text = "Smettila di perdere tempo e consegna la vera Mela d'Oro!"
  },
  AvgDialog_145515_Content_4 = {
    Text = "In piedi sulla cima innevata, a contemplare le montagne candide all'orizzonte, ciò che Riverbero nel petto non era il senso di conquista per aver raggiunto la vetta."
  },
  AvgDialog_145515_Content_40 = {
    Text = "Allora dovrai chiedere a loro se sono d'accordo."
  },
  AvgDialog_145515_Content_41 = {
    Text = "Caraboo si fece da parte, mentre i membri del gruppo di scalata scavalcavano l'ultima parete rocciosa."
  },
  AvgDialog_145515_Content_5 = {Text = "Era Paura."},
  AvgDialog_145515_Content_6 = {
    Text = "La Paura di essere lontani dal mondo degli uomini, la Paura di essere separati da tutto ciò che si conosce."
  },
  AvgDialog_145515_Content_7 = {
    Text = "Qui non vi sono cime più alte, e chi raggiunge la vetta può Solo inginocchiarsi verso il cielo."
  },
  AvgDialog_145515_Content_8 = {
    Text = "Amici, abbiamo raggiunto la vetta."
  },
  AvgDialog_145515_Content_9 = {
    Text = "Tra i membri della spedizione, una sola persona non era rimasta minimamente colpita dallo spettacolo della cima."
  },
  AvgDialog_145516_Content_1 = {
    Text = "Il Precursore"
  },
  AvgDialog_145516_Content_10 = {
    Text = "Mancano ancora la <Blue:Chiave di Salomone> e l'<Blue:Occhio di Balor>."
  },
  AvgDialog_145516_Content_11 = {
    Text = "Caraboo conta sulle dita, borbottando tra sé e sé."
  },
  AvgDialog_145516_Content_12 = {
    Text = "Secondo te, l'Occhio di Balor potrebbe cadere dal cielo all'improvviso, proprio come la Piuma di Ma'at?"
  },
  AvgDialog_145516_Content_13 = {
    Text = "Questa battuta non fa ridere per niente."
  },
  AvgDialog_145516_Content_14 = {
    Text = "Non sai cosa sia successo a Castor, ma su quella piuma nerissima è rimasta la sua essenza."
  },
  AvgDialog_145516_Content_15 = {
    Text = "Non è lontano ormai."
  },
  AvgDialog_145516_Content_16 = {
    Text = "Prima di raggiungere la vetta, non possiamo tornare indietro."
  },
  AvgDialog_145516_Content_17 = {
    Text = "William ti dà una pacca sulla spalla. Evidentemente sa a cosa stai pensando."
  },
  AvgDialog_145516_Content_18 = {
    Text = "Lo sai? Ho una sensazione."
  },
  AvgDialog_145516_Content_19 = {
    Text = "Castor ha sicuramente trovato qualcosa che voleva perseguire, ed è per questo che ha lasciato il gruppo."
  },
  AvgDialog_145516_Content_2 = {
    Text = "Questo è l'ultimo punto di sosta prima della vetta."
  },
  AvgDialog_145516_Content_20 = {
    Text = "E se si tratta di lui, sono certa che riuscirà a realizzare il suo desiderio."
  },
  AvgDialog_145516_Content_21 = {
    Text = "Evelyn si schiarì la voce, come per dare più forza alle proprie parole, e aggiunse."
  },
  AvgDialog_145516_Content_22 = {
    Text = "Purché si viva abbastanza a lungo, anche da una breve convivenza si riesce a sbirciare il Destino degli altri."
  },
  AvgDialog_145516_Content_23 = {
    Text = "In Castor, cosa hai visto?"
  },
  AvgDialog_145516_Content_24 = {
    Text = "Semplicità e tenacia."
  },
  AvgDialog_145516_Content_25 = {
    Text = "Finché non otterrà quell'unica risposta, non si fermerà.\nNon esiterà, né si arrenderà."
  },
  AvgDialog_145516_Content_26 = {
    Text = "E tu, Evelyn? Dove si trova La Tua Risposta?"
  },
  AvgDialog_145516_Content_27 = {
    Text = "Proprio sulla montagna."
  },
  AvgDialog_145516_Content_28 = {
    Text = "Allora per fortuna, siamo sullo stesso Sentiero!"
  },
  AvgDialog_145516_Content_29 = {
    Text = "Caraboo tirò fuori da chissà dove un'altra Mela, la lanciò in aria e la riprese."
  },
  AvgDialog_145516_Content_3 = {
    Text = "Guardando indietro verso le montagne lontane, ai vostri piedi si estende una distesa immensa di ghiaccio e neve, che svanisce nell'orizzonte lontano tra le nebbie del valico."
  },
  AvgDialog_145516_Content_30 = {
    Text = "Se siete tutti pronti, allora diamo Inizio all'ultima tappa."
  },
  AvgDialog_145516_Content_31 = {
    Text = "Non abbassate la guardia. Molti imprevisti accadono nell'ultimo chilometro."
  },
  AvgDialog_145516_Content_32 = {
    Text = "Davanti a voi si erge una parete di ghiaccio quasi verticale."
  },
  AvgDialog_145516_Content_33 = {
    Text = "#N/ANaraka impugna la piccozza, conficcando il becco in diagonale nella neve dura con un tonfo sordo, poi sposta il peso verso l'alto, con i ramponi anteriori che si posizionano con precisione nel piccolo foro lasciato dal becco."
  },
  AvgDialog_145516_Content_34 = {
    Text = "Strano, sembra che qualcuno sia passato di recente."
  },
  AvgDialog_145516_Content_35 = {
    Text = "Guardate, qui ci sono alcune cavità, sembrano quasi scavate da una piccozza."
  },
  AvgDialog_145516_Content_36 = {
    Text = "Potrebbero essere state lasciate dall'ultima spedizione esplorativa?"
  },
  AvgDialog_145516_Content_37 = {
    Text = "Non credo. È passato troppo tempo, le tracce di allora si sarebbero già ricoperte di ghiaccio da un pezzo."
  },
  AvgDialog_145516_Content_38 = {
    Text = "Lascia perdere, non pensarci troppo. Che qualcuno sia passato di qui è una buona cosa, significa che questo sentiero è percorribile."
  },
  AvgDialog_145516_Content_39 = {
    Text = "Prese un chiodo da ghiaccio dall'imbracatura, lo avvitò nello strato di ghiaccio facendolo ruotare, producendo uno stridio che faceva venire i brividi ai denti."
  },
  AvgDialog_145516_Content_4 = {
    Text = "Lo spettacolo maestoso vi regala un senso di sollievo, nonostante la stanchezza che vi attanaglia."
  },
  AvgDialog_145516_Content_40 = {
    Text = "Finché il cono non fu conficcato fino alla base, Naraka vi agganciò un moschettone a vite, vi fece passare la corda principale e serrò il blocco fino in fondo."
  },
  AvgDialog_145516_Content_41 = {
    Text = "Primo punto di protezione."
  },
  AvgDialog_145516_Content_42 = {
    Text = "Tutti, agganciate il bloccante alla corda principale. Usate i ramponi degli scarponi da montagna per incastrarvi nelle tacche che ho scavato, e avanzate lentamente."
  },
  AvgDialog_145516_Content_43 = {
    Text = "Cercasti con la piccozza un punto d'appoggio solido sopra la testa, piantasti la punta con fermezza, poi sollevasti il piede destro e calciasti con forza nella superficie ghiacciata, lasciando che quei due denti d'acciaio facessero presa."
  },
  AvgDialog_145516_Content_44 = {
    Text = "Sposta il peso sui piedi, non abbracciare la parete di ghiaccio."
  },
  AvgDialog_145516_Content_45 = {
    Text = "Inspirasti profondamente l'aria rarefatta che bruciava i polmoni, spingi il corpo leggermente lontano dalla parete di ghiaccio, lasciando che i ramponi sostenessero il peso. Il piede sinistro seguì, un altro calcio deciso."
  },
  AvgDialog_145516_Content_46 = {
    Text = "Il bloccante scivolava lentamente verso l'alto insieme a te, scattando con un clic a ogni piccolo avanzamento."
  },
  AvgDialog_145516_Content_47 = {
    Text = "A metà strada eri già in un bagno di sudore, e la concentrazione che avevi accumulato cominciava a svanire senza che tu potessi trattenerla."
  },
  AvgDialog_145516_Content_48 = {
    Text = "Tirati su con il morale, questo tratto non può permettersi alcun imprevisto."
  },
  AvgDialog_145516_Content_49 = {
    Text = "Proprio mentre le sue parole si spegnevano, accadde l'imprevisto."
  },
  AvgDialog_145516_Content_5 = {
    Text = "<Shake:Asp... aspettate.>"
  },
  AvgDialog_145516_Content_50 = {Text = "..."},
  AvgDialog_145516_Content_51 = {
    Text = "Un filo di luce rossa balenò nell'oscurità della notte, e il naso di William fremette—"
  },
  AvgDialog_145516_Content_52 = {
    Text = "<BigShake:Abbassati—!>"
  },
  AvgDialog_145516_Content_53 = {
    Text = "Prima ancora che finisse di parlare, si era già lanciato su di te con forza, il suo corpo intero che ti schiacciava, con solo la corda di sicurezza a tenervi entrambi sospesi, sbattendo contro la parete di ghiaccio."
  },
  AvgDialog_145516_Content_54 = {
    Text = "Un sottile filo di sangue apparve sulla sua guancia."
  },
  AvgDialog_145516_Content_55 = {
    Text = "Tsk, riflessi piuttosto veloci."
  },
  AvgDialog_145516_Content_56 = {
    Text = "Nelle profondità dell'Oscurità, pesanti catene strisciavano sul pavimento, il suono del metallo che sfregava contro il pavimento era sordo e prolungato."
  },
  AvgDialog_145516_Content_57 = {
    Text = "Ah, sei tu, il tizio che ci ha seguiti per tutto il tragitto."
  },
  AvgDialog_145516_Content_58 = {
    Text = "Ci ha seguiti per tutto il tragitto?"
  },
  AvgDialog_145516_Content_59 = {
    Text = "Già, quando abbiamo incontrato Castor per la prima volta, vi avevo avvertiti: qualcuno ci stava seguendo."
  },
  AvgDialog_145516_Content_6 = {
    Text = "Evelyn ansima a pieni polmoni. La bassa pressione dell'alta quota ha chiaramente un effetto devastante sul suo corpo."
  },
  AvgDialog_145516_Content_60 = {
    Text = "Quello che non so è quando ci abbia superati."
  },
  AvgDialog_145516_Content_61 = {
    Text = "Non c'è da stupirsi che quell'aura mi sembrasse così familiare."
  },
  AvgDialog_145516_Content_62 = {
    Text = "Ricordo il tuo nome——"
  },
  AvgDialog_145516_Content_63 = {
    Text = "Bene, così risparmio le presentazioni."
  },
  AvgDialog_145516_Content_64 = {
    Text = "Al confine tra luce e ombra, una figura avanzò lentamente."
  },
  AvgDialog_145516_Content_65 = {
    Text = "Entrambi i polsi erano recisi, e dietro di lei trascinava due pesanti sfere a catena, su cui un paio di enormi occhi color sangue fissavano il mondo con espressione feroce."
  },
  AvgDialog_145516_Content_66 = {
    Text = "……Helot-catena."
  },
  AvgDialog_145516_Content_67 = {
    Text = "Nel mondo precedente, fu l'ultima persona che vidi."
  },
  AvgDialog_145516_Content_68 = {
    Text = "In altre parole——fu lei a uccidermi."
  },
  AvgDialog_145516_Content_69 = {
    Text = "All'epoca obbediva a Herbert, obbediva agli Associazione degli Scultori."
  },
  AvgDialog_145516_Content_7 = {
    Text = "Alle sue spalle, la ragazza minuta avanza invece con passo leggero."
  },
  AvgDialog_145516_Content_70 = {
    Text = "E adesso? <Yellow:Chi> ti ha mandato qui?"
  },
  AvgDialog_145516_Content_71 = {
    Text = "Solo i cani si preoccupano di sapere chi sia il loro padrone."
  },
  AvgDialog_145516_Content_72 = {
    Text = "Ho una sola cosa da fare——seppellirvi qui per sempre."
  },
  AvgDialog_145516_Content_73 = {
    Text = "Dal suolo emersero innumerevoli Pustole, circondandovi da ogni lato."
  },
  AvgDialog_145516_Content_8 = {
    Text = "Abbiamo lo <Blue:Specchio di Yata> e la <Blue:Piuma di Ma'at>. La <Blue:Corona di Arianna> dovrebbe essere sulla vetta."
  },
  AvgDialog_145516_Content_9 = {
    Text = "Quanto al <Blue:Filo di Moirae>... Eheh, alcuni di voi non me lo diranno, ma so dov'è. E posso procurarci una <Blue:Mela d'Oro>."
  },
  AvgDialog_145517_Content_1 = {
    Text = "Oggi gli Uccelli Partono"
  },
  AvgDialog_145517_Content_10 = {
    Text = "Uscite pure, mi avete seguito per tutto il Sentiero, no?"
  },
  AvgDialog_145517_Content_11 = {
    Text = "Sono già solo, e la distanza ora non è sufficiente per chiamare aiuto."
  },
  AvgDialog_145517_Content_12 = {
    Text = "<Shake:Lasciaci... affrontarci... a vicenda...>"
  },
  AvgDialog_145517_Content_13 = {
    Text = "La figura che emergeva dalla foresta sembrava uscita direttamente dal suo sogno."
  },
  AvgDialog_145517_Content_14 = {
    Text = "<Shake:No… tu sei…>"
  },
  AvgDialog_145517_Content_15 = {
    Text = "Una figura elegante e fiera, ancora più esile di quando si erano separati."
  },
  AvgDialog_145517_Content_16 = {
    Text = "Il mio nome è Pollux. Per ordine del Maestro, sono venuto a catturare il fuggitivo Castor."
  },
  AvgDialog_145517_Content_17 = {
    Text = "Le parole non avevano più importanza; la sua voce risuonava nelle orecchie di Castor come Mormorii."
  },
  AvgDialog_145517_Content_18 = {
    Text = "<SmallShake:Un Wendigo?>"
  },
  AvgDialog_145517_Content_19 = {
    Text = "No, non era un Wendigo. Nemmeno la più sublime delle illusioni avrebbe potuto imitare la consistenza della realtà."
  },
  AvgDialog_145517_Content_2 = {
    Text = "Il ragazzo correva veloce nella Neve."
  },
  AvgDialog_145517_Content_20 = {
    Text = "Peccatore… Castor… La luce sacra rivelerà le tue colpe."
  },
  AvgDialog_145517_Content_21 = {
    Text = "Reale, aspra, gelida, crudele, agghiacciante."
  },
  AvgDialog_145517_Content_22 = {Text = "Pollux…"},
  AvgDialog_145517_Content_23 = {
    Text = "Quel dolore lancinante che saliva dal profondo del cuore."
  },
  AvgDialog_145517_Content_24 = {
    Text = "Per quanto tempo ancora si poteva Eludere? Per quanto tempo ancora?"
  },
  AvgDialog_145517_Content_25 = {
    Text = "Castor avanzava sulla Neve, un passo dopo l'altro, verso Pollux."
  },
  AvgDialog_145517_Content_26 = {
    Text = "<Red:<Shake:Inginocchiati dinanzi alla Lanterna, e io ti assolverò dai tuoi peccati, concedendoti la rinascita in una nuova forma sulla sacra terra senza peccato!>"
  },
  AvgDialog_145517_Content_27 = {
    Text = "Castor non obbedì. Continuò semplicemente ad avanzare verso Pollux."
  },
  AvgDialog_145517_Content_28 = {
    Text = "Anche se fosse stato un Wendigo, non importava. Avanzava e basta."
  },
  AvgDialog_145517_Content_29 = {
    Text = "Pollux alzò il coltello. Un coltello familiare. Durante L'inseguimento precedente, aveva Perforato il petto di Castor."
  },
  AvgDialog_145517_Content_3 = {
    Text = "Niente poteva più fermarlo."
  },
  AvgDialog_145517_Content_30 = {
    Text = "<Big:Ancora un passo, e la luce sacra ti abbatterà!>"
  },
  AvgDialog_145517_Content_4 = {
    Text = "Il Sentiero verso il basso… leggero come volare col Vento."
  },
  AvgDialog_145517_Content_5 = {
    Text = "Un Sentiero senza il peso di Una Bugia lo faceva sentire il cuore libero di librarsi in volo."
  },
  AvgDialog_145517_Content_6 = {
    Text = "Mi dispiace, non avrei dovuto ingannarvi."
  },
  AvgDialog_145517_Content_7 = {
    Text = "Per fortuna, c'è ancora tempo per rimediare."
  },
  AvgDialog_145517_Content_8 = {
    Text = "Ogni volta che si fermava un momento, dalla foresta alle sue spalle giungeva un suono simile alla Neve che cadeva."
  },
  AvgDialog_145517_Content_9 = {
    Text = "Erano Passi che si bloccavano di colpo."
  },
  AvgDialog_145518_Content_1 = {
    Text = "La Luna Sgelata"
  },
  AvgDialog_145518_Content_10 = {
    Text = "Accetti di buon grado."
  },
  AvgDialog_145518_Content_100 = {
    Text = "Ah, l'astuto bugiardo, che si presenta sempre come la vittima più innocente…"
  },
  AvgDialog_145518_Content_101 = {
    Text = "Lei canticchiava una melodia, tornando in testa alla fila."
  },
  AvgDialog_145518_Content_102 = {
    Text = "Cosa intendeva dire con quelle parole?"
  },
  AvgDialog_145518_Content_103 = {
    Text = "Non l'ho capito nemmeno io."
  },
  AvgDialog_145518_Content_104 = {
    Text = "Ehi~ tenetevi dietro, non restate indietro~"
  },
  AvgDialog_145518_Content_105 = {
    Text = "I due, del tutto disorientati, non poterono fare altro che avanzare."
  },
  AvgDialog_145518_Content_106 = {
    Text = "-Altitudine 6000 metri-"
  },
  AvgDialog_145518_Content_11 = {
    Text = "So che è difficile da credere, ma vengo da una stella molto, molto lontana. Ho vagato così a lungo che tutto ciò che ricordo è che nei suoi ultimi giorni la chiamavamo <Blue:il Desolato.>"
  },
  AvgDialog_145518_Content_12 = {
    Text = "Ho attraversato un tempo così lungo da non potersi contare prima di arrivare qui."
  },
  AvgDialog_145518_Content_13 = {
    Text = "Mi fido di te."
  },
  AvgDialog_145518_Content_14 = {
    Text = "Quello che voglio dire è… il Desolato è così lontano che è persino Difficile immaginarlo o descriverlo."
  },
  AvgDialog_145518_Content_15 = {
    Text = "Ma poco fa, nelle acque del lago… mi è sembrato di vedere mia sorella, Faint."
  },
  AvgDialog_145518_Content_16 = {
    Text = "Tintura si morde il labbro."
  },
  AvgDialog_145518_Content_17 = {
    Text = "No, in realtà non è nemmeno quello… Appena ho percepito una sorta di presagio, e l'ombra nel lago viene anch'essa dal Desolato…"
  },
  AvgDialog_145518_Content_18 = {
    Text = "So che è impossibile, ma ho la sensazione che... <Shake:non fosse un'allucinazione...>"
  },
  AvgDialog_145518_Content_19 = {
    Text = "Sembri molto stanca."
  },
  AvgDialog_145518_Content_2 = {
    Text = "La tormenta si è fermata chissà quando, e nel cielo e sulla terra rimane solo un silenzio così vasto da far tremare. Sopra di voi si stende un blu profondo senza una nuvola, e persino le cime innevate in lontananza si mostrano in ogni minimo dettaglio."
  },
  AvgDialog_145518_Content_20 = {
    Text = "Evelyn mostrò un'espressione preoccupata."
  },
  AvgDialog_145518_Content_21 = {
    Text = "Se ti senti stanca, riposati per tempo."
  },
  AvgDialog_145518_Content_22 = {
    Text = "Siamo partiti da poco, scendere dalla montagna da sola non sarebbe pericoloso."
  },
  AvgDialog_145518_Content_23 = {
    Text = "<Yellow:<Big:No...! Non sono stanca! NON ME NE VADO!>>"
  },
  AvgDialog_145518_Content_24 = {
    Text = "Con sorpresa di tutti, Tintura lanciò un grido isterico."
  },
  AvgDialog_145518_Content_25 = {
    Text = "Rendendosi conto che tutti la stavano guardando, Tintura cercò di calmarsi, ma il suo petto che si alzava e abbassava tradiva i suoi veri sentimenti."
  },
  AvgDialog_145518_Content_26 = {
    Text = "Mi dispiace… mi sono lasciata andare. Grazie per la tua preoccupazione, ma <Yellow:non sono stanca.>"
  },
  AvgDialog_145518_Content_27 = {
    Text = "Mentire non serve a niente."
  },
  AvgDialog_145518_Content_28 = {
    Text = "Sono determinata. Non resterò indietro."
  },
  AvgDialog_145518_Content_29 = {
    Text = "Tintura strinse di nuovo le labbra, gettò uno sguardo al lago ghiacciato e si mise in cammino per l'Inizio del Viaggio."
  },
  AvgDialog_145518_Content_3 = {
    Text = "Sotto il cielo sereno e sconfinato, camminate fino alle rive di un lago ghiacciato."
  },
  AvgDialog_145518_Content_30 = {
    Text = "Sulla superficie ghiacciata del lago, si rifletteva Solo la sua ombra sfocata."
  },
  AvgDialog_145518_Content_31 = {
    Text = "Dopo mezza giornata di marcia, trovaste un terreno pianeggiante dove accamparvi; Naraka ordinò a tutti gli scalatori di raccogliere la Neve sciolta e far bollire l'acqua con i fornelli da alta quota."
  },
  AvgDialog_145518_Content_32 = {
    Text = "Quando tornaste con la neve raccolta, Scopriste che dal campo si levava un denso fumo nero."
  },
  AvgDialog_145518_Content_33 = {
    Text = "Ehi, di chi sono i bagagli che bruciano laggiù!"
  },
  AvgDialog_145518_Content_34 = {
    Text = "Eh...? No!!!"
  },
  AvgDialog_145518_Content_35 = {
    Text = "Le fiamme lambivano la piccola borsa di stoffa che Caraboo aveva sempre custodito come un tesoro."
  },
  AvgDialog_145518_Content_36 = {
    Text = "Aspetta, questo sacchetto di monete d'oro nella tua borsa?"
  },
  AvgDialog_145518_Content_37 = {
    Text = "Sotto l'ardore delle fiamme, le monete d'oro si afflosciarono e sprofondarono."
  },
  AvgDialog_145518_Content_38 = {
    Text = "No! Non importa! Posso ancora salvarle!"
  },
  AvgDialog_145518_Content_39 = {
    Text = "No, fammi vedere!"
  },
  AvgDialog_145518_Content_4 = {
    Text = "Tintura fissa le acque del lago con lo sguardo perso nel vuoto."
  },
  AvgDialog_145518_Content_40 = {
    Text = "Strappata la confezione, tutte le monete di cioccolato semisciolte rotolarono a terra."
  },
  AvgDialog_145518_Content_41 = {
    Text = "Una di esse rotolò ai piedi di William, che si chinò a raccoglierla."
  },
  AvgDialog_145518_Content_42 = {
    Text = "<Blue:Debauve & Gallais, cioccolatini Pistoles de Marie...>"
  },
  AvgDialog_145518_Content_43 = {
    Text = "Cioccolato?!"
  },
  AvgDialog_145518_Content_44 = {
    Text = "<Shake:Ah, ahahah…> Questo… anche se è Solo cioccolato, è comunque molto costoso!"
  },
  AvgDialog_145518_Content_45 = {
    Text = "Ma va' a quel paese, se non riesci a pagare la quota per la guida, togliti dai piedi!"
  },
  AvgDialog_145518_Content_46 = {
    Text = "<Shake:No, ti prego, io non conosco il Sentiero da sola…>"
  },
  AvgDialog_145518_Content_47 = {
    Text = "<Shake:Se mi cacci dalla squadra, morirò sicuramente durante la discesa!>"
  },
  AvgDialog_145518_Content_48 = {
    Text = "Vaffanculo, a cosa serve piangere e lamentarsi adesso? Chi inganna gli altri deve essere pronto a essere smascherato!"
  },
  AvgDialog_145518_Content_49 = {
    Text = "Vedendo che Naraka non cedeva né alle lusinghe né alle minacce, Caraboo si guardò intorno, poi Come Se avesse afferrato un'ancora di salvezza, si inginocchiò con un tonfo e si aggrappò disperatamente alle tue gambe."
  },
  AvgDialog_145518_Content_5 = {
    Text = "C'è qualcosa nel lago?"
  },
  AvgDialog_145518_Content_50 = {
    Text = "<Shake:Ti prego, anima buona, non puoi abbandonare una povera ragazzina a scendere dalla montagna da sola, vero?>"
  },
  AvgDialog_145518_Content_51 = {
    Text = "<Shake:Uh uh uh, è sempre così, vengo sempre abbandonata, ovunque vada tutti mi disprezzano perché non ho niente…>"
  },
  AvgDialog_145518_Content_52 = {
    Text = "<Shake:Persona buona, anima generosa, Tu sei sicuramente diverso da loro, mi aiuterai di certo, vero?>"
  },
  AvgDialog_145518_Content_53 = {
    Text = "Lei alzò la testa e ti fissò con gli Occhi colmi di lacrime."
  },
  AvgDialog_145518_Content_54 = {
    Text = "…Lascia perdere. La sua quota per la guida, la pagherò io Dopo la discesa."
  },
  AvgDialog_145518_Content_55 = {
    Text = "Incapace di resistere al suo sguardo, acconsentisti."
  },
  AvgDialog_145518_Content_56 = {
    Text = "<Big:Grazie, grazie mille, mio benefattore!!> Sei il salvatore più grande e magnifico che Caraboo abbia mai conosciuto!!"
  },
  AvgDialog_145518_Content_57 = {
    Text = "Caraboo asciugò immediatamente le lacrime e saltò su ridendo."
  },
  AvgDialog_145518_Content_58 = {
    Text = "Benefattore, una volta che avrò recuperato il mio potere di dea della montagna, ripagherò la tua gentilezza mille volte!"
  },
  AvgDialog_145518_Content_59 = {
    Text = "A quel punto, altro che trenta monete d'oro, ne potrei dare anche trecento, tremila!"
  },
  AvgDialog_145518_Content_6 = {
    Text = "No, no, niente, non c'è niente…"
  },
  AvgDialog_145518_Content_60 = {
    Text = "Certo, certo."
  },
  AvgDialog_145518_Content_61 = {
    Text = "Rispondi in modo evasivo."
  },
  AvgDialog_145518_Content_62 = {
    Text = "Dobbiamo pur scalare la montagna insieme, l'importante è che questa faccenda si risolva in fretta."
  },
  AvgDialog_145518_Content_63 = {
    Text = "La situazione si calma finalmente, e ognuno torna alle proprie occupazioni o si riposa."
  },
  AvgDialog_145518_Content_64 = {
    Text = "William ti tira da parte e ti parla sottovoce."
  },
  AvgDialog_145518_Content_65 = {
    Text = "È strano, ricordo che il zaino di Caraboo prima non era in quella posizione."
  },
  AvgDialog_145518_Content_66 = {
    Text = "<Red:Chi l'ha spostato vicino al fuoco da campo?>"
  },
  AvgDialog_145518_Content_67 = {
    Text = "L'acqua è bollita. Beviamo tutti qualcosa per scaldarci."
  },
  AvgDialog_145518_Content_68 = {
    Text = "C'è la zuppa d'aglio?"
  },
  AvgDialog_145518_Content_69 = {
    Text = "Lo chiedi a me? Non ho niente del genere. Accontentati di un po' d'acqua calda."
  },
  AvgDialog_145518_Content_7 = {
    Text = "Tintura torna in sé all'improvviso, con un'espressione come se volesse dire qualcosa ma si trattenesse."
  },
  AvgDialog_145518_Content_70 = {
    Text = "Hmph, non c'è... Il cosiddetto miglior capogruppo Sherpa non è poi così eccezionale, eppure prende una tariffa da guida così cara."
  },
  AvgDialog_145518_Content_71 = {
    Text = "Vedendo che la tensione stava per tornare a salire, Evelyn si affrettò a intervenire."
  },
  AvgDialog_145518_Content_72 = {
    Text = "Se vuoi qualcosa di caldo, ho del cioccolato caldo qui."
  },
  AvgDialog_145518_Content_73 = {
    Text = "E tu, piccolo, le tue provviste non sono un po' scarse? Ho notato che non mangi molto."
  },
  AvgDialog_145518_Content_74 = {
    Text = "Io? Non fa niente, quando siamo in ritiro spirituale mangiamo solo un pasto al giorno."
  },
  AvgDialog_145518_Content_75 = {
    Text = "Quando si scala una montagna, non ci si può permettere di non fare il pieno di energie."
  },
  AvgDialog_145518_Content_76 = {
    Text = "Mio marito, quando scalava, era come te e preferiva sempre portare Gli Zaini più leggeri."
  },
  AvgDialog_145518_Content_77 = {
    Text = "Da quando rimase bloccato da una bufera di neve per diversi giorni, ha sempre scelto strategie più prudenti."
  },
  AvgDialog_145518_Content_78 = {
    Text = "Suo marito... era anche lui un Alpinista?"
  },
  AvgDialog_145518_Content_79 = {
    Text = "Sì, è un ottimo Alpinista, in passato ha già tentato l'Impatto sull'Everest e sul K2."
  },
  AvgDialog_145518_Content_8 = {
    Text = "Dopo un lungo silenzio, si volta verso di te e parla sottovoce."
  },
  AvgDialog_145518_Content_80 = {Text = "E poi?"},
  AvgDialog_145518_Content_81 = {Text = "E poi?"},
  AvgDialog_145518_Content_82 = {
    Text = "Tuo marito, ha smesso di scalare?"
  },
  AvgDialog_145518_Content_83 = {
    Text = "<Shake:Eh? Perché mi stai tirando?>"
  },
  AvgDialog_145518_Content_84 = {
    Text = "Tutti seguirono le sue parole e guardarono di lato: Caraboo aveva un sorriso sul viso, ma la mano, senza dare nell'occhio, stringeva la manica di Castor."
  },
  AvgDialog_145518_Content_85 = {
    Text = "Accorgendosi che l'Azione era stata Scoperta, ritirò la mano con un certo imbarazzo e mormorò sottovoce."
  },
  AvgDialog_145518_Content_86 = {
    Text = "<Small:Stupido>."
  },
  AvgDialog_145518_Content_87 = {
    Text = "Non fa niente…"
  },
  AvgDialog_145518_Content_88 = {
    Text = "Mio marito… è scomparso durante l'ultimo tentativo di raggiungere la vetta dell'Everest. Nessuno sa dove sia andato. Non è stato trovato nemmeno il corpo."
  },
  AvgDialog_145518_Content_89 = {
    Text = "Prima lo accompagnavo sempre, mi fermavo ad aspettare intorno al Campo 2."
  },
  AvgDialog_145518_Content_9 = {
    Text = "Scusa, non so perché, ma con te ho sempre una sensazione di grande familiarità. Quindi… potresti ascoltarmi per un momento?"
  },
  AvgDialog_145518_Content_90 = {
    Text = "Ora che lui non c'è più, voglio vedere anch'io il paesaggio che vedeva lui…"
  },
  AvgDialog_145518_Content_91 = {
    Text = "Evelyn scrutava la cresta montuosa in lontananza. La montagna di Neve eterna taceva, rispondendo con l'Ululato del Vento."
  },
  AvgDialog_145518_Content_92 = {
    Text = "Questa volta raggiungeremo sicuramente la vetta."
  },
  AvgDialog_145518_Content_93 = {
    Text = "Ne sono convinta."
  },
  AvgDialog_145518_Content_94 = {
    Text = "Poco dopo la conversazione, Caraboo tornò al suo solito atteggiamento disinvolto, passeggiando qua e là con le mani dietro la schiena."
  },
  AvgDialog_145518_Content_95 = {
    Text = "Si avvicinò a Castor con aria misteriosa."
  },
  AvgDialog_145518_Content_96 = {
    Text = "Ehi, stupido, non hai la sensazione che qualcuno ci stia seguendo?"
  },
  AvgDialog_145518_Content_97 = {
    Text = "Non mi sembra. Per tutto il Sentiero ho tenuto d'occhio eventuali inseguitori della Chiesa dei Portatori di Luce. Ma voi siete le prime persone che ho incontrato…"
  },
  AvgDialog_145518_Content_98 = {
    Text = "Neanch'io ho avvertito nulla."
  },
  AvgDialog_145518_Content_99 = {
    Text = "Davvero? Allora forse mi sono fatta troppe idee."
  },
  AvgDialog_145519_Content_1 = {Text = "..."},
  AvgDialog_145519_Content_10 = {
    Text = "Lo Specchio di Yata, insieme alla spada Kusanagi e al gioiello Yasakani no Magatama, è considerato uno dei tre tesori sacri nella mitologia giapponese. Nelle raffigurazioni più comuni, lo Specchio di Yata è realizzato in metallo, con decorazioni in stile giapponese incise sul retro."
  },
  AvgDialog_145519_Content_11 = {
    Text = "Ma guarda questo Specchio…"
  },
  AvgDialog_145519_Content_12 = {
    Text = "La superficie dello specchio è sottile, piatta e liscia, dalla forma perfettamente rotonda, simile alla luna splendente sospesa in alto nel cielo."
  },
  AvgDialog_145519_Content_13 = {
    Text = "Sotto la fredda superficie di vetro, sembrano scorrere furtivamente alcune particelle luminose di un certo colore."
  },
  AvgDialog_145519_Content_14 = {
    Text = "In ogni caso, prima tiriamolo fuori per dargli un'occhiata."
  },
  AvgDialog_145519_Content_15 = {
    Text = "Naraka sollevò un punteruolo di ghiaccio e spezzò agevolmente lo strato di ghiaccio, estraendo quello Specchio."
  },
  AvgDialog_145519_Content_16 = {
    Text = "Caraboo scattò in avanti, lo strappò via con un gesto rapido e lo nascose velocemente nel bagaglio che portava con sé."
  },
  AvgDialog_145519_Content_17 = {
    Text = "<Shake:Cosa fai! Cosa guardate, non guardatemi!>"
  },
  AvgDialog_145519_Content_18 = {
    Text = "Questo è sempre stato il tesoro della dea della montagna innevata, quindi ovviamente spetta a me ora che l'ho trovato!"
  },
  AvgDialog_145519_Content_19 = {
    Text = "Nessuno tentò di contenderle il possesso."
  },
  AvgDialog_145519_Content_2 = {
    Text = "Vi aggirate intorno al lago ghiacciato. La superficie del lago è Come uno specchio, liscia e cristallina, e l'intera distesa è visibile a colpo d'occhio: nessuna traccia di Tintura."
  },
  AvgDialog_145519_Content_20 = {
    Text = "Rispetto a uno Specchio dall'aspetto del tutto ordinario, la scomparsa di Tintura meritava chiaramente maggiore attenzione."
  },
  AvgDialog_145519_Content_21 = {
    Text = "Eppure nessuno tornò a parlare di quella faccenda. Solo la sua ombra pesava ancora inevitabilmente, come un fardello, nel cuore di ognuno."
  },
  AvgDialog_145519_Content_3 = {
    Text = "Nel Vento che Riverbera tra le montagne innevate, Come Se si mescolassero il canto di Tintura e un tenue pianto — presenti e assenti al tempo stesso, impossibile distinguere se fosse il Vento o un Fantasma."
  },
  AvgDialog_145519_Content_4 = {
    Text = "Tintura… non tornerà più, vero?"
  },
  AvgDialog_145519_Content_5 = {
    Text = "Nessuno replicò."
  },
  AvgDialog_145519_Content_6 = {
    Text = "Strano, ieri c'era questa cosa?"
  },
  AvgDialog_145519_Content_7 = {
    Text = "Sulla superficie del lago ghiacciato, nel ghiaccio trasparente e compatto, era silenziosamente sigillato uno Specchio perfettamente rotondo."
  },
  AvgDialog_145519_Content_8 = {
    Text = "<Shake:Lo Specchio di Yata! Questo è lo Specchio di Yata che deve essere offerto alla dea della montagna!>"
  },
  AvgDialog_145519_Content_9 = {
    Text = "William, sembri voler dire qualcosa ma trattenerti."
  },
  AvgDialog_145520_Content_1 = {
    Text = "Settimo Viaggiatore"
  },
  AvgDialog_145520_Content_10 = {
    Text = "In questi giorni non ci sono altre squadre di alpinisti, potete riposare qui tranquillamente, nessuno verrà a disturbarvi—"
  },
  AvgDialog_145520_Content_100 = {
    Text = "Attento! Qualcosa sta emergendo!"
  },
  AvgDialog_145520_Content_11 = {
    Text = "Prima che Naraka finisse di parlare, dall'angolo della grotta giunse improvvisamente un fruscio."
  },
  AvgDialog_145520_Content_12 = {
    Text = "…Eh, c'è qualcuno?"
  },
  AvgDialog_145520_Content_13 = {
    Text = "La voce interrogativa di William risuonò nel Riverbero della caverna, senza risposta."
  },
  AvgDialog_145520_Content_14 = {
    Text = "Siamo una squadra di alpinisti, siamo venuti qui per ripararci dal vento e dalla neve, non abbiamo cattive intenzioni."
  },
  AvgDialog_145520_Content_15 = {
    Text = "Tu emanavi segnali amichevoli, avanzando con la lanterna verso le rocce."
  },
  AvgDialog_145520_Content_16 = {Text = "Attento!"},
  AvgDialog_145520_Content_17 = {
    Text = "La sagoma dietro le rocce si irrigidì all'improvviso. Prima che chiunque potesse spiegare, un attacco feroce si scatenò dall'Oscurità."
  },
  AvgDialog_145520_Content_19 = {
    Text = "Forse perché era uno contro molti, l'aggressore lanciò un'Imboscata e si dissolse nuovamente nell'ombra in un istante. Ma tu riuscisti comunque a riconoscere quella sagoma nel breve scontro."
  },
  AvgDialog_145520_Content_2 = {
    Text = "Dopo che Naraka vi ha guidati per un po', tra le cime delle montagne si è aperta una fenditura nera."
  },
  AvgDialog_145520_Content_20 = {
    Text = "<Shake:Castor?!>"
  },
  AvgDialog_145520_Content_21 = {
    Text = "Dopo un momento, dall'ombra sbucò un mantello nero, e da dietro il mantello spuntò metà di un volto dall'espressione guardinga."
  },
  AvgDialog_145520_Content_22 = {
    Text = "…Tu mi conosci?"
  },
  AvgDialog_145520_Content_23 = {
    Text = "No, questa è una storia molto lunga da raccontare…"
  },
  AvgDialog_145520_Content_24 = {
    Text = "Quindi, perché sei qui da solo?"
  },
  AvgDialog_145520_Content_25 = {Text = "..."},
  AvgDialog_145520_Content_26 = {Text = "..."},
  AvgDialog_145520_Content_27 = {
    Text = "Beh, io e mio fratello — Pollux avevamo concordato di fuggire dalla Chiesa dei Portatori di Luce in momenti diversi e con metodi diversi. Ma ho aspettato un mese nel luogo che avevamo stabilito, e lui non si è mai fatto vedere."
  },
  AvgDialog_145520_Content_28 = {
    Text = "Penso che la mia fuga abbia spinto la signora Juliette a rafforzare la sorveglianza. Da allora, ho cercato continuamente un modo per liberarlo."
  },
  AvgDialog_145520_Content_29 = {
    Text = "<Yellow:Per fortuna mi sono nascosta con successo e sono riuscita a sfuggire ai loro inseguitori.>"
  },
  AvgDialog_145520_Content_3 = {Text = "Entriamo."},
  AvgDialog_145520_Content_30 = {
    Text = "Alla fine, ho sentito dire che in cima alla montagna innevata dimora una Divinità capace di esaudire qualsiasi desiderio."
  },
  AvgDialog_145520_Content_31 = {
    Text = "Ma non posso unirmi a nessuna spedizione alpinistica… le spie della Chiesa sono ovunque, e se mi facessi vedere troppo spesso, sarei scoperta facilmente."
  },
  AvgDialog_145520_Content_32 = {Text = "Stupida."},
  AvgDialog_145520_Content_33 = {Text = "Ah… ?"},
  AvgDialog_145520_Content_34 = {
    Text = "Non ho mai visto nessuno stupido quanto te."
  },
  AvgDialog_145520_Content_35 = {
    Text = "Anche se scalassi la montagna da sola, dove andresti a trovare i sette artefatti magici?"
  },
  AvgDialog_145520_Content_36 = {Text = "..."},
  AvgDialog_145520_Content_37 = {
    Text = "Sembra che non ci abbia mai pensato…"
  },
  AvgDialog_145520_Content_38 = {
    Text = "Esatto! Ecco perché ora hai bisogno dell'aiuto della Dea della Neve."
  },
  AvgDialog_145520_Content_39 = {
    Text = "Dai, purché tu ti unisca al Sacro Ordine della fata, ti prometto che dopo aver raggiunto la vetta ti aiuterò a porre fine alla tua Separazione da tuo fratello!"
  },
  AvgDialog_145520_Content_4 = {
    Text = "Vi siete aiutati a vicenda per scendere dalle rocce scoscese, e tu hai guardato indietro verso l'ingresso della grotta."
  },
  AvgDialog_145520_Content_40 = {Text = "Davvero?"},
  AvgDialog_145520_Content_41 = {
    Text = "Certo che è vero! Non potrebbe essere più vero di così!"
  },
  AvgDialog_145520_Content_42 = {
    Text = "Però, per dimostrare la tua devozione al Sacro Ordine, tutti i tesori che porti con te dovranno essere consegnati alla fata perché li custodisca al posto tuo."
  },
  AvgDialog_145520_Content_43 = {
    Text = "...D'accordo."
  },
  AvgDialog_145520_Content_44 = {
    Text = "Castor esitò a lungo balbettando, poi tirò fuori alcune monete e un Libro di Fiabe tutto consumato e sgualcito."
  },
  AvgDialog_145520_Content_45 = {
    Text = "Ho Solo queste cose. Posso unirmi a voi?"
  },
  AvgDialog_145520_Content_46 = {
    Text = "William ti diede un colpetto sul braccio."
  },
  AvgDialog_145520_Content_47 = {
    Text = "Ne hai viste abbastanza?"
  },
  AvgDialog_145520_Content_48 = {
    Text = "Ehm, allora, Castor, benvenuto nella nostra squadra di esploratori."
  },
  AvgDialog_145520_Content_49 = {
    Text = "Caraboo stava solo scherzando con te: purché tu abbia i tuoi rifornimenti, non devi consegnare nient'altro."
  },
  AvgDialog_145520_Content_5 = {
    Text = "La spaccatura era stretta e piatta, come un occhio socchiuso, che teneva fuori il vento e la neve."
  },
  AvgDialog_145520_Content_50 = {
    Text = "Hmph, nemmeno la dea della montagna innevata vuole la tua misera Offerta, tienila pure per te."
  },
  AvgDialog_145520_Content_51 = {
    Text = "Castor spianò con cura le pieghe del Libro di Fiabe, poi lo ripose delicatamente nel petto."
  },
  AvgDialog_145520_Content_52 = {
    Text = "Poi lanciò un'occhiata alle monete, con lo sguardo che vagava tra voi."
  },
  AvgDialog_145520_Content_53 = {
    Text = "Se non le vuole nessuno, allora le accetto volentieri io."
  },
  AvgDialog_145520_Content_54 = {
    Text = "Naraka fece un gesto con la mano e il piano di pietra si svuotò all'istante."
  },
  AvgDialog_145520_Content_55 = {
    Text = "La tariffa da guida di questo giovane è molto più economica di quella degli altri."
  },
  AvgDialog_145520_Content_56 = {
    Text = "Se non ricordo male, la tua tariffa da guida l'abbiamo già pagata."
  },
  AvgDialog_145520_Content_57 = {
    Text = "Se proprio devi riscuoterne un'altra, la pago io per lui."
  },
  AvgDialog_145520_Content_58 = {
    Text = "Non si preoccupi, non ci conosciamo affatto, non posso permettermi di disturbarla…"
  },
  AvgDialog_145520_Content_59 = {
    Text = "La mano tesa di Evelyn interruppe le parole di Castor; quest'ultimo esitò per mezzo secondo, poi la ricambiò con una stretta."
  },
  AvgDialog_145520_Content_6 = {
    Text = "Dentro… fa così caldo…"
  },
  AvgDialog_145520_Content_60 = {
    Text = "Evelyn, mi chiamo Evelyn, sono un'archeologa."
  },
  AvgDialog_145520_Content_61 = {
    Text = "Ora non siamo più estranei, giusto?"
  },
  AvgDialog_145520_Content_62 = {Text = "..."},
  AvgDialog_145520_Content_63 = {
    Text = "La bufera di neve vi intrappola tutti nella stretta caverna. Senza ancora un fuoco, la conversazione è la vostra unica difesa contro il freddo."
  },
  AvgDialog_145520_Content_64 = {
    Text = "Hai detto poco fa che stai cercando il tuo fratello gemello, giusto?"
  },
  AvgDialog_145520_Content_65 = {Text = "Certo."},
  AvgDialog_145520_Content_66 = {
    Text = "Castor annuì con cautela."
  },
  AvgDialog_145520_Content_67 = {
    Text = "Che coincidenza, anch'io sto cercando la mia sorella gemella."
  },
  AvgDialog_145520_Content_68 = {
    Text = "Io e Faint siamo persone molto diverse. Mia sorella, pur avendo una salute cagionevole, è in realtà una persona coraggiosa e forte."
  },
  AvgDialog_145520_Content_69 = {
    Text = "Quando menzionò la sorella gemella, anche Tintura, che di solito sembrava persa nei suoi pensieri, si animò come per magia, lasciando affiorare un tenue sorriso."
  },
  AvgDialog_145520_Content_7 = {
    Text = "Ah, ah, io che sono la dea della montagna innevata, come potevo non sapere che esistesse un posto simile tra i monti?"
  },
  AvgDialog_145520_Content_70 = {
    Text = "E Pollux? Che tipo di persona è?"
  },
  AvgDialog_145520_Content_71 = {
    Text = "<Shake:Pollux…>"
  },
  AvgDialog_145520_Content_72 = {
    Text = "Non è molto simile a me. È intelligente, acuto, con una grande capacità di comprensione. Da quando eravamo piccoli, il Maestro e i nostri insegnanti lo hanno sempre preferito a me…"
  },
  AvgDialog_145520_Content_73 = {
    Text = "Non preoccuparti. Anche tu hai i tuoi punti di forza. Per esempio, non hai detto poco fa che sei riuscito a sfuggire al tracciamento della Chiesa? È davvero una cosa notevole."
  },
  AvgDialog_145520_Content_74 = {
    Text = "Castor arrossì leggermente, si schiarì la voce e spostò l'argomento su Tintura."
  },
  AvgDialog_145520_Content_75 = {
    Text = "Tu e tua sorella, perché vi siete separati?"
  },
  AvgDialog_145520_Content_76 = {
    Text = "Nel momento della fuga, mi lasciò l'ultimo biglietto per la nave."
  },
  AvgDialog_145520_Content_77 = {
    Text = "La sua voce era tenue, Come Se bastasse un soffio perché quel ricordo venisse disperso dal Vento e dalla Neve."
  },
  AvgDialog_145520_Content_78 = {
    Text = "Speriamo che alla fine riusciremo tutti a rivederli."
  },
  AvgDialog_145520_Content_79 = {
    Text = "Castor rimase in Silenzio per un momento, Lo Sguardo che scivolava oltre Lei verso la tempesta bianca che imperversava fuori dalla caverna."
  },
  AvgDialog_145520_Content_8 = {
    Text = "Ovviamente, la guida degli Sherpa non si paga per niente."
  },
  AvgDialog_145520_Content_80 = {
    Text = "Tra una chiacchiera e l'altra, il tempo passava minuto dopo minuto."
  },
  AvgDialog_145520_Content_81 = {Text = "..."},
  AvgDialog_145520_Content_82 = {
    Text = "Alla settima ora, la tempesta raggiunge un apice quasi malevolo."
  },
  AvgDialog_145520_Content_83 = {
    Text = "A quanto pare, questa notte la passeremo nella caverna."
  },
  AvgDialog_145520_Content_84 = {
    Text = "Naraka rimosse i resti già umidi al centro della caverna e tentò di accendere un nuovo fuoco con del legno secco."
  },
  AvgDialog_145520_Content_85 = {
    Text = "Dall'Oscurità nelle Profondità della Caverna proveniva un suono sottile e frammentato, come se qualcosa stesse graffiando la parete rocciosa con le unghie."
  },
  AvgDialog_145520_Content_86 = {
    Text = "Ci sono dei topi?"
  },
  AvgDialog_145520_Content_87 = {
    Text = "A questa altitudine non dovrebbero esserci topi…"
  },
  AvgDialog_145520_Content_88 = {
    Text = "Il suono si interruppe all'improvviso. Il silenzio all'interno della caverna era inquietante."
  },
  AvgDialog_145520_Content_89 = {
    Text = "Da quell'Oscurità così densa da non lasciar filtrare nemmeno un raggio di luce, un senso di malevolenza si fece Assalto Imminente."
  },
  AvgDialog_145520_Content_9 = {
    Text = "Gli anziani dicono che questa spaccatura è apparsa all'improvviso dopo una valanga."
  },
  AvgDialog_145520_Content_90 = {
    Text = "Naraka alzò la torcia e la puntò verso le Profondità della Caverna seguendo il suono. La luce avanzò solo di qualche passo prima di essere inghiottita dall'Oscurità davanti a lei."
  },
  AvgDialog_145520_Content_91 = {
    Text = "Non andarci."
  },
  AvgDialog_145520_Content_92 = {
    Text = "Do Solo un'occhiata."
  },
  AvgDialog_145520_Content_93 = {
    Text = "Naraka si appoggiò alla parete rocciosa e si sporse con cautela."
  },
  AvgDialog_145520_Content_94 = {
    Text = "La luce tremolante del fuoco superò il bordo di pietra ai suoi piedi, illuminando una pozza d'acqua completamente buia in basso. La superficie dell'acqua era liscia, senza la minima increspatura, quasi in Fusione in Uno con le ombre dei Dintorni."
  },
  AvgDialog_145520_Content_95 = {
    Text = "Sotto c'è dell'acqua. <Shake:Sembra molto profonda——>"
  },
  AvgDialog_145520_Content_96 = {
    Text = "Prima ancora che le parole finissero, quella \"superficie d'acqua\" nerissima sprofondò improvvisamente verso il basso."
  },
  AvgDialog_145520_Content_97 = {
    Text = "Naraka perse l'equilibrio, con mezzo piede già scivolato nell'apertura che si era allargata all'improvviso."
  },
  AvgDialog_145520_Content_98 = {
    Text = "<Shake:Prendimi——!>"
  },
  AvgDialog_145520_Content_99 = {
    Text = "Tu lo afferrasti di scatto per il colletto, trascinandolo all'indietro."
  },
  AvgDialog_145521_Content_1 = {
    Text = "Al Focolare, dopo il Tramonto"
  },
  AvgDialog_145521_Content_10 = {
    Text = "In un angolo erano ammucchiate alcune casse di legno ammuffite, e più in fondo sulla parete rocciosa era conficcato un tratto di catena spezzata."
  },
  AvgDialog_145521_Content_100 = {
    Text = "Chiuse gli Occhi, percependo con la punta delle dita i contorni."
  },
  AvgDialog_145521_Content_101 = {
    Text = "<Small:<Italic:...\"Il malvagio lanciò un incantesimo e trasformò il fratellino in un corvo.\">>"
  },
  AvgDialog_145521_Content_102 = {
    Text = "<Small:<Italic:...\"Ma il fratello maggiore conosceva il colore delle sue ali.\">>"
  },
  AvgDialog_145521_Content_103 = {
    Text = "La fiamma guizzò una volta, poi si affievolì."
  },
  AvgDialog_145521_Content_104 = {
    Text = "Posso riportarti indietro?"
  },
  AvgDialog_145521_Content_105 = {
    Text = "La prossima volta che ci incontreremo, riuscirai ancora a riconoscermi?"
  },
  AvgDialog_145521_Content_106 = {Text = "..."},
  AvgDialog_145521_Content_107 = {
    Text = "Molto tempo dopo, chiuse il libro, si alzò e camminò in silenzio verso l'ingresso della grotta, chinandosi a liberare le fessure di ventilazione ostruite dalla neve notturna."
  },
  AvgDialog_145521_Content_108 = {
    Text = "La neve scivolò tra le sue dita, cadendo sul piccolo cumulo già formatosi, senza fare alcun rumore."
  },
  AvgDialog_145521_Content_109 = {
    Text = "L'alba non era ancora sorta."
  },
  AvgDialog_145521_Content_11 = {
    Text = "Qualcuno ci ha vissuto in passato?"
  },
  AvgDialog_145521_Content_110 = {
    Text = "Vieni svegliato dalla fioca luce che filtra dall'ingresso della grotta."
  },
  AvgDialog_145521_Content_111 = {
    Text = "Castor aveva già preparato Gli Zaini e stava aspettando all'ingresso della grotta che tu ti svegliassi."
  },
  AvgDialog_145521_Content_112 = {
    Text = "Mi dispiace, mi sto preparando ad andarmene."
  },
  AvgDialog_145521_Content_113 = {
    Text = "Il mio desiderio è diverso dal vostro."
  },
  AvgDialog_145521_Content_114 = {
    Text = "Voglio ritrovare mio fratello, e posso farcela con le mie sole mani."
  },
  AvgDialog_145521_Content_115 = {
    Text = "Ma questo percorso è troppo pericoloso, da solo tu—"
  },
  AvgDialog_145521_Content_116 = {
    Text = "…C'è un'altra cosa su cui ho esitato se dirvi o meno. Ma ora è il momento di essere onesto—"
  },
  AvgDialog_145521_Content_117 = {
    Text = "Castor fece un respiro profondo, come se avesse preso una grande decisione."
  },
  AvgDialog_145521_Content_118 = {
    Text = "La prima volta che ci siamo incontrati, la Tintura disse che, sebbene non fossi simpatico come Pollux, avevo anch'io i miei punti di forza e che potevo sfuggire da solo al tracciamento della Chiesa dei Portatori di Luce."
  },
  AvgDialog_145521_Content_119 = {
    Text = "Ma era falso. Era una bugia per voi."
  },
  AvgDialog_145521_Content_12 = {
    Text = "È un rifugio di una vecchia spedizione alpinistica, abbandonato da molti anni. Il posto per il fuoco da campo è là, vado a sistemarlo."
  },
  AvgDialog_145521_Content_120 = {
    Text = "Sono molto più debole di quanto sappiate, non ci sono riuscito."
  },
  AvgDialog_145521_Content_121 = {
    Text = "I fedeli mi sono sempre stati alle calcagna. Se rimango, sarò un peso per tutti voi."
  },
  AvgDialog_145521_Content_122 = {
    Text = "Alzò la testa e guardò verso il fondo della grotta, dove gli altri dormivano ancora."
  },
  AvgDialog_145521_Content_123 = {
    Text = "Il simbolo danneggiato nella grotta, l'ho riconosciuto: è il simbolo della Chiesa dei Portatori di Luce."
  },
  AvgDialog_145521_Content_124 = {
    Text = "Questo è il loro Temporaneo quartier generale."
  },
  AvgDialog_145521_Content_125 = {
    Text = "Più si sale, più è aperto. Prima o poi mi Scopriranno. È meglio andarsene subito, mischiarsi alla Folla — così sarà più facile sfuggire a L'inseguimento."
  },
  AvgDialog_145521_Content_126 = {
    Text = "Si girò e si incamminò nel Vento e nella Neve."
  },
  AvgDialog_145521_Content_127 = {
    Text = "Tu restasti fermo sul posto a guardare a lungo, finché la sua figura non scomparve del tutto."
  },
  AvgDialog_145521_Content_128 = {
    Text = "Da dietro giunsero lievi Passi."
  },
  AvgDialog_145521_Content_129 = {
    Text = "Caraboo si era alzata in qualche momento senza che nessuno se ne accorgesse, appoggiata all'ingresso della grotta, a guardare nella direzione in cui Castor si era allontanato."
  },
  AvgDialog_145521_Content_13 = {
    Text = "Si diresse con passo sicuro verso una piattaforma di pietra annerita dal fumo al centro della caverna, si accovacciò e cominciò a rimuovere i Resti Cinerei accumulati negli anni."
  },
  AvgDialog_145521_Content_130 = {
    Text = "…Stupido."
  },
  AvgDialog_145521_Content_131 = {
    Text = "Nel tono di Lei non c'era il solito Spuntone."
  },
  AvgDialog_145521_Content_132 = {
    Text = "La squadra alpinistica era passata da cinque a quattro persone."
  },
  AvgDialog_145521_Content_14 = {
    Text = "Lo Sguardo di Castor si soffermò brevemente su quelle incisioni nella roccia. Non disse nulla, si limitò a distogliere Lo Sguardo."
  },
  AvgDialog_145521_Content_15 = {
    Text = "Prima che qualcuno potesse fare domande, tutti furono attratti dal Richiamo di Caraboo."
  },
  AvgDialog_145521_Content_16 = {
    Text = "<Big:Una grotta bella calda! Un fuoco! Un lungo Riposo!>"
  },
  AvgDialog_145521_Content_17 = {
    Text = "Caraboo era in preda all'Euforia."
  },
  AvgDialog_145521_Content_18 = {
    Text = "Nonostante tutti stessero reggendo a fatica, riuscivi a vedere che ognuno era esausto per la battaglia contro il Wendigo."
  },
  AvgDialog_145521_Content_19 = {
    Text = "Una grotta perfetta. Un Riposo perfetto."
  },
  AvgDialog_145521_Content_2 = {
    Text = "La tormenta non si era placata. Seguiste le crepe nel ghiaccio in cerca di un riparo, finché non trovaste una cavità nevosa riparata dal vento sotto una parete rocciosa."
  },
  AvgDialog_145521_Content_20 = {
    Text = "Qualunque pericolo si nasconda davanti a voi, non può impedirvi di godervi un momento di tranquillità in questo istante."
  },
  AvgDialog_145521_Content_21 = {
    Text = "Il fuoco arde all'interno della grotta, vicino all'ingresso. Il fumo viene portato fuori dal Vento obliquo."
  },
  AvgDialog_145521_Content_22 = {
    Text = "Evelyn tirò fuori dallo zaino un rotolo di materassino impermeabile, prima pressò uno strato sottile di Neve sul terreno, poi vi stese sopra il materassino."
  },
  AvgDialog_145521_Content_23 = {
    Text = "Tutti si tolsero i cappotti irrigiditi dal gelo e si radunarono attorno al fuoco, avvicinando le mani il più possibile alle fiamme."
  },
  AvgDialog_145521_Content_24 = {
    Text = "Sarebbe bello se sulla montagna facesse sempre così caldo."
  },
  AvgDialog_145521_Content_25 = {Text = "Pfft."},
  AvgDialog_145521_Content_26 = {
    Text = "Di cosa ridi?"
  },
  AvgDialog_145521_Content_27 = {
    Text = "Rido di te, sciocco, che non sai misurare le parole. E se la dea della montagna di Neve prendesse questo come il tuo vero desiderio e te lo esaudisse?"
  },
  AvgDialog_145521_Content_28 = {
    Text = "Non sarebbe male neanche così. In quel caso, chi scala la montagna sarebbe molto più al sicuro."
  },
  AvgDialog_145521_Content_29 = {
    Text = "La luce del falò si rifletteva negli Occhi seri di Castor."
  },
  AvgDialog_145521_Content_3 = {
    Text = "L'ingresso era stretto, ma l'interno era sorprendentemente spazioso."
  },
  AvgDialog_145521_Content_30 = {
    Text = "Lascia perdere, non c'è gusto a prendere in giro uno sciocco come te."
  },
  AvgDialog_145521_Content_31 = {
    Text = "Caraboo, Tu hai qualche desiderio?"
  },
  AvgDialog_145521_Content_32 = {
    Text = "Caraboo sembrava non aspettarsi di essere interpellata così all'improvviso; dopo un attimo di sorpresa, fece girare gli Occhi."
  },
  AvgDialog_145521_Content_33 = {
    Text = "Io sono la dea della montagna di Neve, sono quella che esaudisce i vostri desideri!"
  },
  AvgDialog_145521_Content_34 = {
    Text = "Se dovessi dire qual è il mio desiderio, sarebbe recuperare il mio potere."
  },
  AvgDialog_145521_Content_35 = {
    Text = "Sì! Esatto! Dopo aver recuperato il potere, voglio riorganizzare Il Sacro Ordine! Che tutto il continente venga a fare Offerta alla dea della montagna di Neve!"
  },
  AvgDialog_145521_Content_36 = {
    Text = "Evelyn emette una risatina sommessa. La luce del fuoco tremola nei suoi occhi scuri."
  },
  AvgDialog_145521_Content_37 = {
    Text = "Dove sono gli altri?"
  },
  AvgDialog_145521_Content_38 = {
    Text = "Si girò verso di Te, ma il suo sguardo non era indagatore, solo la premura di una Chat tra amici."
  },
  AvgDialog_145521_Content_39 = {
    Text = "Sono curiosa anch'io! Che tipo di desiderio dovrei esaudire al mio benefattore?"
  },
  AvgDialog_145521_Content_4 = {
    Text = "Per ora non entrate."
  },
  AvgDialog_145521_Content_40 = {
    Text = "Qualcuno mi ha indicato un Sentiero per tornare a La Nostra Casa; per tornare, ho bisogno di trovare una persona."
  },
  AvgDialog_145521_Content_41 = {
    Text = "Sei proprio uno stupido. Perché non esprimi semplicemente il desiderio di tornare?"
  },
  AvgDialog_145521_Content_42 = {
    Text = "Qualcuno ha scritto una Profezia per me."
  },
  AvgDialog_145521_Content_43 = {
    Text = "<Yellow:Il Destino è una trama di anelli intrecciati; chi tenta di saltare qualsiasi nodo per raggiungere direttamente la fine, dovrà sopportare il dolore del filo spezzato.>"
  },
  AvgDialog_145521_Content_44 = {
    Text = "Capito. E questo signor William al tuo fianco?"
  },
  AvgDialog_145521_Content_45 = {
    Text = "La storia di William è un po' complicata da raccontare."
  },
  AvgDialog_145521_Content_46 = {
    Text = "Almeno per ora, la cosa più importante per me è accompagnare %player% a tornare a Mythag, a tornare da Ramona."
  },
  AvgDialog_145521_Content_47 = {
    Text = "Guardi William con stupore. Ha un'espressione serena, e nelle sue microespressioni non riesci a trovare la minima traccia di menzogna."
  },
  AvgDialog_145521_Content_48 = {
    Text = "Non fissarmi così."
  },
  AvgDialog_145521_Content_49 = {
    Text = "<Yellow:I miei altri doveri in questo mondo sono giunti a una conclusione temporanea.>"
  },
  AvgDialog_145521_Content_5 = {
    Text = "Alzò il piccone e cominciò a battere pollice per pollice lungo la volta interna dell'ingresso."
  },
  AvgDialog_145521_Content_50 = {
    Text = "Mentre pronunciava queste parole, William alzò deliberatamente una mano per scostare i capelli che gli coprivano gli occhi, nascondendo gran parte della sua Espressione."
  },
  AvgDialog_145521_Content_51 = {
    Text = "E tu, stupido?"
  },
  AvgDialog_145521_Content_52 = {Text = "Io?"},
  AvgDialog_145521_Content_53 = {
    Text = "Castor fissava il falò con sguardo assente."
  },
  AvgDialog_145521_Content_54 = {
    Text = "Voglio che Pollux… torni."
  },
  AvgDialog_145521_Content_55 = {
    Text = "Caraboo alzò gli occhi verso Castor, e quel tocco di solita spavalderia nel suo sguardo svanì per un momento."
  },
  AvgDialog_145521_Content_56 = {
    Text = "Hai appena detto che vuoi che lui torni."
  },
  AvgDialog_145521_Content_57 = {
    Text = "Ma quando ci siamo incontrati per la prima volta, hai detto che volevi salvarlo."
  },
  AvgDialog_145521_Content_58 = {
    Text = "C'è una sottile differenza tra queste due formulazioni… ma non è detto che non possano coincidere."
  },
  AvgDialog_145521_Content_59 = {
    Text = "Castor, tuo fratello, è davvero tenuto prigioniero da quel tale capocult?"
  },
  AvgDialog_145521_Content_6 = {
    Text = "Questo pezzo è Allentato, quando montate il campo evitate di stare proprio sotto."
  },
  AvgDialog_145521_Content_60 = {
    Text = "Un breve Silenzio. Caraboo prese la Mela e ci diede un altro morso, cambiando argomento come se nulla fosse accaduto."
  },
  AvgDialog_145521_Content_61 = {
    Text = "In realtà, sai, realizzare un desiderio è molto semplice."
  },
  AvgDialog_145521_Content_62 = {
    Text = "Vedi, tra i sette tesori non c'è forse anche una piuma? Chissà, magari la piuma che porti con te è proprio la <Yellow:Piuma di Ma'at>."
  },
  AvgDialog_145521_Content_63 = {
    Text = "Ma'at, dea della verità, dell'ordine e della giustizia, porta sul capo una piuma di struzzo."
  },
  AvgDialog_145521_Content_64 = {
    Text = "Durante il Giudizio dei defunti, Anubi pone il cuore del Defunto sulla stessa bilancia di questa piuma. Se il cuore è più pesante della piuma, viene Divorato dal mostro Ammit; se il cuore è leggero quanto la piuma, l'anima può entrare nel Campo dei Giunchi."
  },
  AvgDialog_145521_Content_65 = {
    Text = "La piuma rappresenta l'\"innocenza\" nella mitologia egizia."
  },
  AvgDialog_145521_Content_66 = {
    Text = "La piuma dell'innocenza… che ironia."
  },
  AvgDialog_145521_Content_67 = {
    Text = "Castor mostrò un sorriso leggermente rassegnato."
  },
  AvgDialog_145521_Content_68 = {
    Text = "Queste Piume, me le ha impiantate insieme a quelle di mio fratello Juliette, la Gran Sacerdotessa della Chiesa dei Portatori di Luce, per creare la sua Divinità."
  },
  AvgDialog_145521_Content_69 = {
    Text = "Nel suo racconto, sentisti una voce. Una voce di dolore incontenibile."
  },
  AvgDialog_145521_Content_7 = {
    Text = "Si abbassò e avanzò verso il fondo della caverna, si accovacciò ad ascoltare rasente al suolo per un po', poi tastò con il dorso della mano l'umidità della roccia."
  },
  AvgDialog_145521_Content_70 = {
    Text = "Dopo, strappò via le ali di Pollux. Ora, solo io conservo ancora queste Piume della Profanazione."
  },
  AvgDialog_145521_Content_71 = {
    Text = "Castor accarezzò delicatamente le piume all'estremità delle ali, e per un momento ti sembrò di vedere su di esse macchie di Sangue."
  },
  AvgDialog_145521_Content_72 = {
    Text = "Quindi, parlare di innocenza… queste Piume sono forse l'esistenza più lontana dall'innocenza che ci sia."
  },
  AvgDialog_145521_Content_73 = {
    Text = "L'aria si fece silenziosa, con solo il crepitio della Bruciatura del fuoco del campo."
  },
  AvgDialog_145521_Content_74 = {
    Text = "Naraka, e il tuo desiderio?"
  },
  AvgDialog_145521_Content_75 = {
    Text = "William si girò all'improvviso verso Naraka, che stava scaldandosi al fuoco lì accanto e non sembrava avere intenzione di unirsi alla conversazione."
  },
  AvgDialog_145521_Content_76 = {
    Text = "Sono Solo una guida, non ho intenzione di esprimere desideri insieme a voi."
  },
  AvgDialog_145521_Content_77 = {
    Text = "Se proprio si deve parlare del <Yellow:desiderio di Naraka>, forse spera che anche il nome delle guide Sherpa possa essere iscritto negli annali degli scalatori."
  },
  AvgDialog_145521_Content_78 = {
    Text = "Ma realizzare un desiderio del genere tramite un miracolo sarebbe troppo noioso, non è così?"
  },
  AvgDialog_145521_Content_79 = {
    Text = "Creare Una Bugia attraverso la Storia compilando e falsificando libri è troppo semplice, troppo facile — così facile da perdere ogni valore."
  },
  AvgDialog_145521_Content_8 = {
    Text = "Potete entrare, Dentro dovrebbe essere al sicuro."
  },
  AvgDialog_145521_Content_80 = {
    Text = "Raggiungere la vetta è qualcosa che si deve realizzare con i propri piedi."
  },
  AvgDialog_145521_Content_81 = {
    Text = "Con le proprie forze…"
  },
  AvgDialog_145521_Content_82 = {
    Text = "Castor sembrava aver percepito qualcosa."
  },
  AvgDialog_145521_Content_83 = {
    Text = "Ehi — non sembri proprio il tipo da fare discorsi così sensati."
  },
  AvgDialog_145521_Content_84 = {
    Text = "Caraboo si tappò il naso agitando la mano, Come Se avesse sentito qualcosa di puzzolente."
  },
  AvgDialog_145521_Content_85 = {
    Text = "Momento di sincerità, smettila di recitare, parliamo sul serio?"
  },
  AvgDialog_145521_Content_86 = {
    Text = "Lei fissò maliziosa gli Occhi di Naraka; Naraka cercò di Eludere il Suo Sguardo, ma Lei si chinò in avanti, inseguendolo con Lo Sguardo senza mollare."
  },
  AvgDialog_145521_Content_87 = {
    Text = "<Shake:Dai, mostrami il tuo vero volto!>"
  },
  AvgDialog_145521_Content_88 = {
    Text = "Caraboo si lanciò in avanti, cercando di afferrare Naraka come un'aquila che piomba su un pulcino, ma Naraka si scansò con un leggero movimento del fianco."
  },
  AvgDialog_145521_Content_89 = {
    Text = "Smettila di fare storie, domani dobbiamo ancora percorrere il Sentiero. Non voglio che non riusciate ad arrivare in cima."
  },
  AvgDialog_145521_Content_9 = {
    Text = "Sulla parete rocciosa rimanevano tracce di motivi sbiaditi, come il profilo di qualche simbolo, con la vernice ormai scrostata al punto da essere irriconoscibile."
  },
  AvgDialog_145521_Content_90 = {
    Text = "Caraboo mancò il colpo e, cogliendo l'occasione, si sedette direttamente sulla Neve, sorridendo a tutta bocca."
  },
  AvgDialog_145521_Content_91 = {
    Text = "Visto che anche tu vuoi che arriviamo in cima, allora sono tranquilla."
  },
  AvgDialog_145521_Content_92 = {Text = "..."},
  AvgDialog_145521_Content_93 = {
    Text = "Il fuoco da campo brucia nel cuore della notte, ridotto a braci sparse di luce rossa."
  },
  AvgDialog_145521_Content_94 = {
    Text = "Naraka organizzò i turni di guardia notturna, due ore ciascuno.\nUno dopo l'altro, tutti si addormentarono. Dai sacchi a pelo provenivano flebili e soffocati russii."
  },
  AvgDialog_145521_Content_95 = {
    Text = "Castor prese naturalmente il primo turno. Appoggiato alla parete della caverna, frugò in fondo a Gli Zaini ed estrasse un libricino con gli angoli consumati e sbiancati."
  },
  AvgDialog_145521_Content_96 = {
    Text = "Era un Libro di Fiabe."
  },
  AvgDialog_145521_Content_97 = {
    Text = "Le sue dita accarezzarono i due nomi sul frontespizio."
  },
  AvgDialog_145521_Content_98 = {
    Text = "La grafia ordinata da bambino era la sua; l'altra era tracciata in modo sghembo con un pastello rosso, il colore sbiadito dal passare del tempo."
  },
  AvgDialog_145521_Content_99 = {Text = "Pollux…"},
  AvgDialog_145522_Content_1 = {
    Text = "Non Rispondere"
  },
  AvgDialog_145522_Content_10 = {
    Text = "Castor camminava in coda al gruppo, più silenzioso del solito."
  },
  AvgDialog_145522_Content_11 = {
    Text = "Ehi, testone. Hai freddo?"
  },
  AvgDialog_145522_Content_12 = {Text = "Sto bene."},
  AvgDialog_145522_Content_13 = {
    Text = "Anche per me. È strano."
  },
  AvgDialog_145522_Content_14 = {
    Text = "Allora, da chi proviene quel respiro così pesante e affannoso?"
  },
  AvgDialog_145522_Content_15 = {
    Text = "Il gruppo si fermò. Tutti si voltarono all'unisono. Dietro di loro c'erano solo le loro stesse orme, più o meno profonde."
  },
  AvgDialog_145522_Content_16 = {
    Text = "Ai bordi delle orme, la Neve era pulita. Pulita come se qualcosa l'avesse delicatamente spazzata via."
  },
  AvgDialog_145522_Content_17 = {
    Text = "Silenzio. Solo il Vento. Il Vento soffiava da molto lontano, girava attorno alla cresta e si infilava nel colletto di ognuno."
  },
  AvgDialog_145522_Content_18 = {
    Text = "Nel Vento si celava un suono Quasi impercettibile. Non era un canto. Era un Richiamo."
  },
  AvgDialog_145522_Content_19 = {
    Text = "<Change>...Eve...lyn..."
  },
  AvgDialog_145522_Content_2 = {
    Text = "La tormenta si era attenuata, ma il cielo appariva ancora più cupo di quando infuriava."
  },
  AvgDialog_145522_Content_20 = {Text = "?!"},
  AvgDialog_145522_Content_21 = {
    Text = "Lei si girò di scatto. Il Campo di neve era deserto, non c'era nulla. Ma quella voce tornò, questa volta più vicina, con una dolcezza quasi crudele."
  },
  AvgDialog_145522_Content_22 = {
    Text = "<Change>...Evelyn... Ho freddo..."
  },
  AvgDialog_145522_Content_23 = {
    Text = "Quello è..."
  },
  AvgDialog_145522_Content_24 = {
    Text = "<Shake:Impossibile…>"
  },
  AvgDialog_145522_Content_25 = {
    Text = "Il Volto di lei perse all'istante ogni colore. Le sue labbra erano pallide, la voce tremante, come se il momento che aveva immaginato più di una volta fosse finalmente arrivato."
  },
  AvgDialog_145522_Content_26 = {
    Text = "Voi… l'avete sentita anche voi?!"
  },
  AvgDialog_145522_Content_27 = {Text = "È lui."},
  AvgDialog_145522_Content_28 = {
    Text = "<Shake:È la sua voce……>"
  },
  AvgDialog_145522_Content_29 = {
    Text = "Signora Evelyn, chiunque tu stia sentendo, ti prego di non rispondergli."
  },
  AvgDialog_145522_Content_3 = {
    Text = "Nuvole grigio piombo pendevano basse sulle creste delle montagne, come uno strato pesante di vecchi Sogni che si rifiutavano di dissiparsi."
  },
  AvgDialog_145522_Content_30 = {
    Text = "Trattenete il respiro. Il vento della Distesa di Neve vi soffia accanto alle orecchie, e poi— \nLo avete sentito tutti anche voi."
  },
  AvgDialog_145522_Content_31 = {
    Text = "Il vento si è trasformato in innumerevoli voci, innumerevoli Richiami avvolgenti. Ognuno soffiava da una direzione che un tempo conoscevi, e che un tempo hai perduto."
  },
  AvgDialog_145522_Content_32 = {
    Text = "Una voce. Una voce ti chiama. Gelida e cristallina."
  },
  AvgDialog_145522_Content_33 = {
    Text = "<Change>Ti sto aspettando, compagno..."
  },
  AvgDialog_145522_Content_34 = {
    Text = "<Change>Non restare indietro. Raggiungeremo insieme la fine di questo cammino."
  },
  AvgDialog_145522_Content_35 = {Text = "Ramona..."},
  AvgDialog_145522_Content_36 = {
    Text = "Stringi i denti, esercitando un Contrattacco al desiderio di seguire quella voce."
  },
  AvgDialog_145522_Content_37 = {
    Text = "I tuoi piedi sembrano congelati nella neve, fuori dal tuo controllo. Puoi sentire una forza leggerissima, delicatissima, provenire dalla direzione della voce, che lentamente, lentamente, trascina il tuo baricentro in avanti."
  },
  AvgDialog_145522_Content_38 = {
    Text = "È L'Invito. Un invito impossibile da rifiutare."
  },
  AvgDialog_145522_Content_39 = {
    Text = "Purché tu voglia fare un passo avanti, potresti tornare a qualsiasi momento caldo del passato—"
  },
  AvgDialog_145522_Content_4 = {
    Text = "Nessuno parlava. I cani da guida camminavano in testa, e persino loro avevano soffocato in gola quel guaito abituale."
  },
  AvgDialog_145522_Content_40 = {Text = "Custode—"},
  AvgDialog_145522_Content_41 = {
    Text = "La voce di William giunge da un luogo lontanissimo. Solo allora ti accorgi di aver già fatto mezzo passo senza sapere quando."
  },
  AvgDialog_145522_Content_42 = {
    Text = "Un paio di cani da guida giacciono morti sul terreno accanto a te, la gola brutalmente squarciata, con il sangue cremisi schizzato in macchie stridenti e nette sulla neve candida."
  },
  AvgDialog_145522_Content_43 = {
    Text = "Fai un passo indietro."
  },
  AvgDialog_145522_Content_44 = {
    Text = "Dammi la mano."
  },
  AvgDialog_145522_Content_45 = {
    Text = "Il volto di William è pallido come un foglio, e la mano con cui ti stringe il braccio trema involontariamente."
  },
  AvgDialog_145522_Content_46 = {
    Text = "Puoi sentire quanto stia facendo forza per controllarsi, per non lasciarsi sedurre da quella voce."
  },
  AvgDialog_145522_Content_47 = {
    Text = "Quella voce è falsa. Dovete svegliarvi."
  },
  AvgDialog_145522_Content_48 = {
    Text = "Lo dice con voce bassissima, come se stesse pronunciando Il Verdetto."
  },
  AvgDialog_145522_Content_49 = {
    Text = "<Shake:<Small:Uh… Zia Rosa…>>"
  },
  AvgDialog_145522_Content_5 = {
    Text = "Andate più lentamente, il terreno non va bene."
  },
  AvgDialog_145522_Content_50 = {
    Text = "Caraboo si svegliò come da un sogno, ancora borbottando qualcosa."
  },
  AvgDialog_145522_Content_51 = {
    Text = "Ma non tutti riescono a svegliarsi."
  },
  AvgDialog_145522_Content_52 = {
    Text = "Pollux…! Pollux…! Dove sei?!"
  },
  AvgDialog_145522_Content_53 = {
    Text = "<Shake:<Big:Pollux…!!!>>"
  },
  AvgDialog_145522_Content_54 = {
    Text = "<Italic:…Fratello, ho freddo…>"
  },
  AvgDialog_145522_Content_55 = {
    Text = "<Italic:Fratello, la cella è così buia, ho così paura… ti prego… lasciami uscire… La Santissima, lei…>"
  },
  AvgDialog_145522_Content_56 = {
    Text = "<Shake:<Italic:…Fratello, perché non vieni a cercarmi…>>"
  },
  AvgDialog_145522_Content_57 = {
    Text = "Pollux!! Aspettami, arrivo subito—"
  },
  AvgDialog_145522_Content_58 = {
    Text = "<Shake:Ehi, stupido, fermati!>"
  },
  AvgDialog_145522_Content_59 = {
    Text = "Ignorando il vostro Richiamo, Castor si lanciò fuori."
  },
  AvgDialog_145522_Content_6 = {
    Text = "Questo tratto era un pendio dritto, ora si sono aperte delle crepe trasversali."
  },
  AvgDialog_145522_Content_60 = {
    Text = "<Shake:Fermatelo!>"
  },
  AvgDialog_145522_Content_61 = {
    Text = "Non lasciate che quello stupido si faccia ingannare!"
  },
  AvgDialog_145522_Content_7 = {
    Text = "Sono nuove fessure formatesi dopo l'ultima valanga… non dovrebbero essere così profonde."
  },
  AvgDialog_145522_Content_8 = {
    Text = "La forma della montagna sta cambiando."
  },
  AvgDialog_145522_Content_9 = {
    Text = "William non continuò. I suoi occhi color smeraldo fissavano il lontano, le sopracciglia leggermente aggrottate."
  },
  AvgDialog_145523_Content_1 = {
    Text = "La Vetta Senza Desideri"
  },
  AvgDialog_145523_Content_10 = {
    Text = "William si accovaccia lentamente, sfiorando con la punta delle dita le intricate incisioni tra i piedistalli, quelle che avevi scambiato per semplici decorazioni."
  },
  AvgDialog_145523_Content_100 = {
    Text = "<Shake:Fermalo! Spegnilo! <Red:Marcirò prima ancora che il desiderio venga esaudito!>>"
  },
  AvgDialog_145523_Content_101 = {
    Text = "Questo non faceva parte del nostro accordo."
  },
  AvgDialog_145523_Content_102 = {
    Text = "Già, ha promesso solo di avviare il rituale per te. Non ha mai promesso che saresti sopravvissuto."
  },
  AvgDialog_145523_Content_103 = {
    Text = "Capisco… Ogni singola parola di William era la pura verità… eppure, messe insieme, hanno formato una menzogna perfetta."
  },
  AvgDialog_145523_Content_104 = {
    Text = "Il sesto alone di luce si leva."
  },
  AvgDialog_145523_Content_105 = {
    Text = "L'intera montagna trema come qualcosa che sta morendo. Innumerevoli masse di carne pallida spuntano dalle rocce che si spaccano e si riversano verso l'altare come un'onda."
  },
  AvgDialog_145523_Content_106 = {
    Text = "No! Quelle sono mie! La mia Caro! Il mio Potere! I miei desideri!"
  },
  AvgDialog_145523_Content_107 = {
    Text = "O forse non ti sono mai appartenuti. Quel potere non ti appartiene. Sono i desideri rubati degli innumerevoli pellegrini che hai attirato e sepolto qui."
  },
  AvgDialog_145523_Content_108 = {
    Text = "Quel potere appartiene a tutti coloro che hai ingannato, divorato e scartato. Non hai il diritto di reclamarlo..."
  },
  AvgDialog_145523_Content_109 = {
    Text = "...E ora, stanno semplicemente tornando dove appartengono."
  },
  AvgDialog_145523_Content_11 = {
    Text = "Impossibile... come può trovarsi qui... Questi segni accanto alle incisioni dell'altare... li riconosco."
  },
  AvgDialog_145523_Content_110 = {
    Text = "Tintura, Castor, Evelyn e Fingal, che non hai mai avuto modo di incontrare di persona..."
  },
  AvgDialog_145523_Content_111 = {
    Text = "Volto dopo volto, nome dopo nome affiora alla superficie della tua mente, prima di sprofondare nel silenzioso buio della memoria."
  },
  AvgDialog_145523_Content_112 = {
    Text = "<BigShake:Non osare! NON OSARE!>"
  },
  AvgDialog_145523_Content_113 = {
    Text = "<Big:<Red:Distruggerò prima l'altare, poi farò a pezzi ognuno di voi!>"
  },
  AvgDialog_145523_Content_114 = {
    Text = "William ti fa un cenno con la testa."
  },
  AvgDialog_145523_Content_115 = {
    Text = "Facciamo ognuno la nostra parte. Io manterrò il rituale in corso."
  },
  AvgDialog_145523_Content_116 = {
    Text = "Lascia fare a me. Fermerò il verme!"
  },
  AvgDialog_145523_Content_12 = {
    Text = "È opera di Fingal."
  },
  AvgDialog_145523_Content_13 = {Text = "Fingal?"},
  AvgDialog_145523_Content_14 = {
    Text = "Conosci quel nome. Il compagno di William, l'Investigatore scomparso da \"quel mondo\" prima di lui."
  },
  AvgDialog_145523_Content_15 = {
    Text = "Capisco, la Chiave di Salomone… il motivo per cui il Verme non riesce ad avviare il rituale… e lo scopo per cui Fingal è venuto in questo mondo…"
  },
  AvgDialog_145523_Content_16 = {
    Text = "Ahahah... Capisco! Ora capisco! È esilarante!"
  },
  AvgDialog_145523_Content_17 = {
    Text = "Quindi è questo che quel tessitore maniaco del lavoro voleva mostrarmi. È valsa la pena portarvi fin quassù!"
  },
  AvgDialog_145523_Content_18 = {
    Text = "Cosa intendi?"
  },
  AvgDialog_145523_Content_19 = {
    Text = "N si stringe semplicemente nelle spalle."
  },
  AvgDialog_145523_Content_2 = {
    Text = "Era un altare immenso, Come Se avesse la stessa età dell'intera catena montuosa."
  },
  AvgDialog_145523_Content_20 = {
    Text = "Ebbene, non sono il tuo traduttore. Vedi questo signor William qui? Chiedi a lui. Mi hai sì lasciato uscire dal tuo ventre, ma ti sembro forse qualcuno che intende ricambiare il \"favore\"?"
  },
  AvgDialog_145523_Content_21 = {
    Text = "Spiegherò io."
  },
  AvgDialog_145523_Content_22 = {
    Text = "\"La Chiave di Salomone\" non è in realtà una chiave, bensì un grimorio."
  },
  AvgDialog_145523_Content_23 = {
    Text = "E il contenuto più cruciale registrato nel grimorio è il metodo di Evocazione dei settantadue demoni di Salomone. In altre parole, il metodo per collegare i mondi."
  },
  AvgDialog_145523_Content_24 = {
    Text = "Alzò la testa e guardò verso il centro esatto dei sette piedistalli — una stretta serratura Quasi fusa con le ombre."
  },
  AvgDialog_145523_Content_25 = {
    Text = "Questi segni sono un codice segreto che Solo lui e io sappiamo leggere."
  },
  AvgDialog_145523_Content_26 = {
    Text = "William si inginocchia davanti al cerchio magico, tracciando con cura le incisioni sul terreno. Lentamente, le parole silenziose cominciano a comporsi nella sua mente, formando una voce familiare."
  },
  AvgDialog_145523_Content_27 = {
    Text = "È William? Sapevo che saresti arrivato fin qui.\n\nIl cerchio magico qui contiene tre diversi antichi alfabeti. Scommetterei che tra i nostri, solo tu, lo studente diligente, potresti leggerli tutti in una volta sola.\nSono incantesimi di evocazione e sigillo. Dovresti capire cosa significa."
  },
  AvgDialog_145523_Content_28 = {
    Text = "Controlla l'apertura e la chiusura di un certo \"Portale.\""
  },
  AvgDialog_145523_Content_29 = {
    Text = "#N/AIn breve, questo cerchio magico usa la \"Corona\" come medium, collegandosi all'origine di questo mondo. Pertanto, solo all'interno di questo mondo, può davvero esaudire qualsiasi desiderio.\n\nDevi esserti chiesto perché sei stato gettato in questo mondo sconosciuto, immagino?\n\nOra posso darti la risposta.\n\nTu sei quel desiderio... il mio desiderio."
  },
  AvgDialog_145523_Content_3 = {
    Text = "Gradini di pietra disposti in cerchio si innalzavano uno dopo l'altro, e in cima si ergevano sette piedistalli vuoti disposti a formare un cerchio. Tra un piedistallo e l'altro, in antichi solchi scavati nella pietra, era coagulata una luce dorata scura, ormai da tempo prosciugata."
  },
  AvgDialog_145523_Content_30 = {
    Text = [[
Purtroppo, il potere che ho offerto non era sufficiente. Ho potuto solo socchiudere una fessura attraverso cui far passare il tuo Nucleo d'Argento.

La destinazione che non ho potuto raggiungere... devi raggiungerla al posto mio.

Dopotutto, sei il leggendario Investigatore William, no?]]
  },
  AvgDialog_145523_Content_31 = {
    Text = "Spero che tu abbia ancora la mia Chiave d'Argento.\n\nUsala per attivare il cerchio magico, poi esprimi il tuo desiderio, e ti guiderà verso la terra promessa.\n\nLa strada davanti a te—quella, la lascio a te.\n\nCon sincerità,\nFingal"
  },
  AvgDialog_145523_Content_32 = {
    Text = "Le dita di William si fermarono."
  },
  AvgDialog_145523_Content_33 = {
    Text = "Non dice una parola. Non hai mai visto quella espressione sul suo viso."
  },
  AvgDialog_145523_Content_34 = {Text = "%player%."},
  AvgDialog_145523_Content_35 = {Text = "Sono qui."},
  AvgDialog_145523_Content_36 = {
    Text = "All'epoca non mi hai chiesto perché fossi la prima persona a risvegliarsi sotto il Richiamo del Wendigo?"
  },
  AvgDialog_145523_Content_37 = {
    Text = "Perché sono l'unico tra noi ad aver visto le sue ossa."
  },
  AvgDialog_145523_Content_38 = {
    Text = "Il suo corpo era completamente decomposto, impossibile riconoscerne l'Identità. Ma ho riconosciuto quella mezza Chiave d'argento che portava con sé."
  },
  AvgDialog_145523_Content_39 = {
    Text = "Numero I-1021, il numero appartenente a Fingal. Ogni volta che un numero scompare dai Registri, sappiamo che un altro predecessore è stato dimenticato dal mondo."
  },
  AvgDialog_145523_Content_4 = {
    Text = "Questo è il luogo dove il Verme della Montagna, usando i desideri come esca, ha attirato innumerevoli alpinisti verso la loro fine."
  },
  AvgDialog_145523_Content_40 = {
    Text = "Da allora, ho sempre tenuto questa Chiave d'argento addosso."
  },
  AvgDialog_145523_Content_41 = {
    Text = "Chiuse gli occhi. Quando li riaprì, in quegli Occhi color smeraldo rimase soltanto qualcosa di sereno, di incrollabile."
  },
  AvgDialog_145523_Content_42 = {
    Text = "…Fingal, grazie per la fiducia che mi hai dato."
  },
  AvgDialog_145523_Content_43 = {
    Text = "Verme della Montagna, ti dirò come attivare il rituale."
  },
  AvgDialog_145523_Content_44 = {
    Text = "Coloro che offrono i loro desideri alla montagna cedono le proprie anime per alimentare il cerchio magico. Attraverso di loro, viene costruito un ponte verso l'Origine del mondo."
  },
  AvgDialog_145523_Content_45 = {
    Text = "L'Origine del mondo?"
  },
  AvgDialog_145523_Content_46 = {
    Text = "Se la mia ipotesi è corretta, è il Sole Nero che pende nel cielo."
  },
  AvgDialog_145523_Content_47 = {
    Text = "Il Sole Nero esiste in modo simile al \"Black Pool\" di Mythag—onnicomprensivo, una sospensione delle rovine di tutto il passato e il futuro, annegato in una marea corrosiva."
  },
  AvgDialog_145523_Content_48 = {
    Text = "La portata del desiderio esaudito dipende interamente da quanta di quella marea chi desidera osa attingere dal Sole Nero."
  },
  AvgDialog_145523_Content_49 = {
    Text = "Bambina, tieni gli occhi fissi su di lui. Assicurati che non stia tessendo menzogne."
  },
  AvgDialog_145523_Content_5 = {
    Text = "Nessuno ha mai lasciato questo posto in vita. Tutti gli scalatori del passato... sono tutti qui. Sotto i nostri piedi. Nel ventre della montagna."
  },
  AvgDialog_145523_Content_50 = {
    Text = "A malincuore, Caraboo si fa avanti e fissa lo sguardo negli occhi di William."
  },
  AvgDialog_145523_Content_51 = {Text = "<Shake:!!>"},
  AvgDialog_145523_Content_52 = {
    Text = "William chiude gli occhi e scuote delicatamente la testa."
  },
  AvgDialog_145523_Content_53 = {
    Text = "Ogni parola che ha appena detto è vera."
  },
  AvgDialog_145523_Content_54 = {
    Text = "<Shake:Non mentirmi! Hai esitato proprio ora, piccolo impostore!>"
  },
  AvgDialog_145523_Content_55 = {
    Text = "Sto mentendo? Dovresti saperlo meglio di me."
  },
  AvgDialog_145523_Content_56 = {
    Text = "Il Verme emette una risata fredda e beffarda, facendo rimbombare una cascata di neve giù dalle scogliere."
  },
  AvgDialog_145523_Content_57 = {
    Text = "Hmph. Il rituale è tutto ciò che conta. Una volta terminato, mi occuperò di te personalmente, traditore."
  },
  AvgDialog_145523_Content_58 = {
    Text = "Dimmi allora, Verme della Montagna—quale è la portata del desiderio che vuoi esaudire?"
  },
  AvgDialog_145523_Content_59 = {
    Text = "Ehehehe... hai bisogno di chiedere? Più è grandioso, meglio è! Voglio inghiottire il mondo intero nel mio ventre—un banchetto infinito, inesauribile!"
  },
  AvgDialog_145523_Content_6 = {
    Text = "Basta parlare. Dimmi come funziona questo cerchio magico."
  },
  AvgDialog_145523_Content_60 = {
    Text = "Che creatura avida e sciocca. Forse avresti dovuto imparare la bellezza della moderazione."
  },
  AvgDialog_145523_Content_61 = {
    Text = "Come potresti capire, tu che sei un parassita del Caos? Se avessi seguito le regole, non avrei mai raggiunto queste vette."
  },
  AvgDialog_145523_Content_62 = {
    Text = "E per \"vette\" intendi trascinare il tuo corpo gonfio e contorcente lungo una cima ghiacciata?"
  },
  AvgDialog_145523_Content_63 = {
    Text = "Ugh... lascia perdere. Tanto nessuno ascolta mai i miei ottimi consigli."
  },
  AvgDialog_145523_Content_64 = {Text = "Capito."},
  AvgDialog_145523_Content_65 = {
    Text = "William annuì."
  },
  AvgDialog_145523_Content_66 = {
    Text = "Per esigere un desiderio di portata grandiosa, devi cedere ogni singola offerta."
  },
  AvgDialog_145523_Content_67 = {
    Text = "<BigShake:Prendili! Prendili tutti! Esistono proprio per questo momento!>"
  },
  AvgDialog_145523_Content_68 = {
    Text = "%player%, dammi il Sacrificio."
  },
  AvgDialog_145523_Content_69 = {
    Text = "Apri la valigetta."
  },
  AvgDialog_145523_Content_7 = {
    Text = "La voce del Verme della Montagna proveniva dal suolo sotto di loro. Questa volta, nel suo tono non c'era più solo scherno, ma anche una certa urgenza repressa per lunghissimi anni."
  },
  AvgDialog_145523_Content_70 = {
    Text = "la Mela d'Oro, lo Specchio di Yata, la Piuma di Ma'at, l'Occhio di Balor, il Filo delle Moire, la Corona di Arianna… e la Chiave d'Argento stessa."
  },
  AvgDialog_145523_Content_71 = {
    Text = "Sette offerte trovano ciascuna il proprio posto sui piedistalli, e attraverso le antiche scanalature una luce dorata scura scorre e si riversa di nuovo, congiungendosi in un anello completo."
  },
  AvgDialog_145523_Content_72 = {
    Text = "<Shake:Ahaha... Finalmente... FINALMENTE!>"
  },
  AvgDialog_145523_Content_73 = {
    Text = "La Montagna avrà il suo banchetto. La Montagna spenderà l'intero suo tesoro."
  },
  AvgDialog_145523_Content_74 = {
    Text = "La Montagna ha patito la fame per così, così tanto tempo."
  },
  AvgDialog_145523_Content_75 = {
    Text = "William stringeva quella Chiave unica nel suo genere e la inserì nella serratura."
  },
  AvgDialog_145523_Content_76 = {
    Text = "In nome di Fingal—"
  },
  AvgDialog_145523_Content_77 = {
    Text = "<Red:Inizio questo rituale.>"
  },
  AvgDialog_145523_Content_78 = {Text = "Clic."},
  AvgDialog_145523_Content_79 = {
    Text = "Con un suono sottile e acuto, tutte e sette le offerte eruttano in una luce accecante."
  },
  AvgDialog_145523_Content_8 = {
    Text = "Tutti gli occhi si volgono verso l'altare, attratti dalla fitta e misteriosa scrittura che ne ricopre la superficie."
  },
  AvgDialog_145523_Content_80 = {
    Text = "Il primo anello di luce si leva sopra l'altare. Poi il secondo, e il terzo. I desideri sopiti nei sette manufatti risuonano in armonia, come sette fiumi che si precipitano verso un unico, oscuro mare."
  },
  AvgDialog_145523_Content_81 = {
    Text = "Se la Montagna avesse mani, artiglerebbe il cielo per afferrare quell'anello brillante, straziata da una fame disperata."
  },
  AvgDialog_145523_Content_82 = {
    Text = "<Shake:Questo giorno è finalmente arrivato!>"
  },
  AvgDialog_145523_Content_83 = {
    Text = "Strapperebbe l'anello dai cieli e lo premerebbe in profondità contro il Suo petto, seppellendolo nella Sua carne gonfia finché ogni goccia del suo potere fosse divorata."
  },
  AvgDialog_145523_Content_84 = {
    Text = "Fissi con sguardo vuoto il cielo in tumulto. Quando il desiderio della Montagna sarà esaudito, cosa ne sarà delle vostre vite? Il vostro viaggio finirà semplicemente in questo deserto ghiacciato?"
  },
  AvgDialog_145523_Content_85 = {
    Text = "In quell'istante, vedi il lampo del monocolo di William."
  },
  AvgDialog_145523_Content_86 = {
    Text = "Subito dopo, il quarto anello di luce si accende."
  },
  AvgDialog_145523_Content_87 = {
    Text = "La roccia solida sotto i tuoi piedi geme con un rombo basso e pesante—un fremito che non appartiene alla pietra, ma alla carne viva. Deboli, malsani bagliori di luce cominciano a trasparire dagli strati di ghiaccio che si frantumano sotto di te."
  },
  AvgDialog_145523_Content_88 = {
    Text = "<Shake:...Cos'è questo?>"
  },
  AvgDialog_145523_Content_89 = {
    Text = "<Shake:Perché... le mie forze... mi abbandonano?>"
  },
  AvgDialog_145523_Content_9 = {
    Text = "Aspetta… questi motivi…"
  },
  AvgDialog_145523_Content_90 = {
    Text = "Questo è il prezzo del rituale che desideravi così ardentemente."
  },
  AvgDialog_145523_Content_91 = {
    Text = "Dopo aver pagato il prezzo, cosa ne sarà di esso?"
  },
  AvgDialog_145523_Content_92 = {
    Text = "Il rituale estrarrà \"tutto\" il Potere del Sacrificio, quindi immagino che tornerà a com'era prima di incontrarti, forse anche più debole."
  },
  AvgDialog_145523_Content_93 = {
    Text = "Così debole da contorcersi e distorcersi in una Mela, un piccolo vermiciattolo che si sbriciolerebbe a una stretta?"
  },
  AvgDialog_145523_Content_94 = {
    Text = "<BigShake:Mi hai ingannato! Bugiardo miserabile!>"
  },
  AvgDialog_145523_Content_95 = {
    Text = "Ti ho promesso che avrei avviato completamente il rituale, e tu hai accettato di cedere <Italic:tutte> le offerte."
  },
  AvgDialog_145523_Content_96 = {
    Text = "Tutto ciò che hai inghiottito nel tuo ventre, l'intera forza vitale di questa montagna, sarà offerta all'altare—sacrificata al dio che ha scolpito questa formazione."
  },
  AvgDialog_145523_Content_97 = {
    Text = "Il quinto alone di luce si leva."
  },
  AvgDialog_145523_Content_98 = {
    Text = "Le rocce sotto i piedi iniziano a screpolarsi e sfaldarsi, rivelando lo strato sottostante di carne umida, pallida, in preda a violente contrazioni."
  },
  AvgDialog_145523_Content_99 = {
    Text = "Enormi lastre di neve crollano con un fragore assordante, e il cielo viene inghiottito, pezzo per pezzo, da un'ombra inimmaginabile."
  },
  AvgDialog_145524_Content_1 = {
    Text = "Tu… non avvicinarti!"
  },
  AvgDialog_145524_Content_10 = {
    Text = "<Change>Ricordi ancora la tua missione?"
  },
  AvgDialog_145524_Content_11 = {
    Text = "<Small:Eliminare... il traditore... Devo...>"
  },
  AvgDialog_145524_Content_12 = {
    Text = "Il Caos negli occhi di Pollux svanì gradualmente, sostituito da uno sguardo vuoto, un vuoto che poteva essere mosso Solo dalle Voci nella Tua Testa."
  },
  AvgDialog_145524_Content_13 = {
    Text = "Sì, hai ragione, sono un traditore. Sono colui che ti ha tradito e che è fuggito."
  },
  AvgDialog_145524_Content_14 = {
    Text = "Ma ora, non me ne andrò più."
  },
  AvgDialog_145524_Content_15 = {
    Text = "<Shake:Traditore, Castor...>"
  },
  AvgDialog_145524_Content_16 = {
    Text = "Era disorientato, voleva resistere a qualcosa, aggrapparsi a qualcosa, ma le voci nella sua testa continuavano a lottare."
  },
  AvgDialog_145524_Content_17 = {
    Text = "Pollux, ci hai seguiti per tutto questo tempo, di certo hai incontrato anche tu il Wendigo."
  },
  AvgDialog_145524_Content_18 = {
    Text = "Nell'Illusione del Wendigo, cosa hai sentito?"
  },
  AvgDialog_145524_Content_19 = {
    Text = "Le pupille di Pollux si dilatarono all'istante, poi si persero lentamente nel vuoto. Cadde in una meditazione simile ai Mormorii."
  },
  AvgDialog_145524_Content_2 = {
    Text = "Pollux spalancò gli Occhi. Non riusciva a capire cosa stesse pensando il folle che aveva di fronte."
  },
  AvgDialog_145524_Content_20 = {
    Text = "Ho sentito... qualcuno che mi chiamava..."
  },
  AvgDialog_145524_Content_21 = {
    Text = "Diceva che potevamo diventare cavalieri straordinari."
  },
  AvgDialog_145524_Content_22 = {
    Text = "Cavalcavamo a cavallo, attraversando montagne, mari e fiumi, abbattendo draghi..."
  },
  AvgDialog_145524_Content_23 = {
    Text = "E poi, e poi, alla fine del sogno…"
  },
  AvgDialog_145524_Content_24 = {Text = "..."},
  AvgDialog_145524_Content_25 = {
    Text = "<BigShake:No, no…!>"
  },
  AvgDialog_145524_Content_26 = {
    Text = "È molto doloroso, Juliette, <Shake:Aiutami!, Aiutami!…>"
  },
  AvgDialog_145524_Content_27 = {
    Text = "<Shake:Sono… nobile… unico… Divus… Aiutami!…<Small:Non posso…>>"
  },
  AvgDialog_145524_Content_28 = {
    Text = "Non importa… Non devi ricordare."
  },
  AvgDialog_145524_Content_29 = {
    Text = "Le sofferenze insopportabili, lascia che le sopporti io. Come quando eravamo piccoli."
  },
  AvgDialog_145524_Content_3 = {
    Text = "Sul volto di Castor non c'era riverenza per i precetti, né Paura per l'ostilità."
  },
  AvgDialog_145524_Content_30 = {
    Text = "Dopotutto, sono il fratello maggiore."
  },
  AvgDialog_145524_Content_31 = {
    Text = "Castor abbracciò Pollux, calmandolo con una voce dolce come quella di chi consola un bambino."
  },
  AvgDialog_145524_Content_32 = {
    Text = "Il respiro di Pollux rallentò, il viso appoggiato alla spalla di Castor, le palpebre che si abbassavano lentamente."
  },
  AvgDialog_145524_Content_33 = {
    Text = "<Shake:Castor…>"
  },
  AvgDialog_145524_Content_34 = {
    Text = "Sono io, sono, Castor…"
  },
  AvgDialog_145524_Content_35 = {
    Text = "<Shake:Castor, Castor…>"
  },
  AvgDialog_145524_Content_36 = {
    Text = "<Shake:<Small:...Fratello?>>"
  },
  AvgDialog_145524_Content_37 = {
    Text = "Le pupille prima spente si fecero improvvisamente limpide, la voce di Pollux era così leggera da essere Quasi dispersa dal Vento, eppure raggiunse le orecchie di Castor senza deviare."
  },
  AvgDialog_145524_Content_38 = {
    Text = "Il Richiamo che aveva immaginato e rievocato infinite volte risuonò finalmente di nuovo accanto a lui."
  },
  AvgDialog_145524_Content_39 = {Text = "Ah—"},
  AvgDialog_145524_Content_4 = {
    Text = "Si fece semplicemente avanti, oltre quella lama, oltre tutti gli ostacoli che avrebbero dovuto esserci ma non c'erano più."
  },
  AvgDialog_145524_Content_40 = {
    Text = "Voleva piangere, voleva gridare, voleva urlare."
  },
  AvgDialog_145524_Content_41 = {
    Text = "Anche se in quel momento intorno a lui c'era Solo la vastità infinita della Distesa di Neve, voleva proclamarlo al mondo intero senza alcun motivo: suo fratello era tornato."
  },
  AvgDialog_145524_Content_42 = {
    Text = "Ma non disse nulla, come sempre, come quando Pollux lo prendeva in giro chiamandolo un pezzo di legno e Caraboo lo derideva chiamandolo uno stupido."
  },
  AvgDialog_145524_Content_43 = {
    Text = "<Shake:Pollux…>"
  },
  AvgDialog_145524_Content_44 = {
    Text = "— Proprio in quel momento, in cima alla montagna innevata — in un punto ancora più alto, dove la vetta non si vedeva —"
  },
  AvgDialog_145524_Content_45 = {
    Text = "Lo Sguardo di un Giudizio calò dall'alto."
  },
  AvgDialog_145524_Content_46 = {
    Text = "<Change>Scarto di produzione."
  },
  AvgDialog_145524_Content_47 = {
    Text = "Castor strinse il fratello a sé con forza—"
  },
  AvgDialog_145524_Content_48 = {
    Text = "Ma non servì a nulla. La luce sbocciò dal petto di Pollux."
  },
  AvgDialog_145524_Content_49 = {
    Text = "La luce squarciò dritto il petto dei due, attraversò il logoro mantello di Castor, attraversò le Piume con cui Castor li avvolgeva entrambi—"
  },
  AvgDialog_145524_Content_5 = {
    Text = "Strinse Pollux in un abbraccio."
  },
  AvgDialog_145524_Content_50 = {
    Text = "Come catene di pura luce bianca, li legò saldamente l'uno all'altro, promettendo che da quel momento in poi, non si sarebbero mai più separati."
  },
  AvgDialog_145524_Content_51 = {
    Text = "Fratello… mi dispiace…"
  },
  AvgDialog_145524_Content_52 = {
    Text = "Pronunciate le ultime parole, Pollux si appoggiò alla spalla di Castor e sprofondò in un sonno profondo."
  },
  AvgDialog_145524_Content_53 = {
    Text = "Così… va bene… non ci separeremo mai più…"
  },
  AvgDialog_145524_Content_54 = {
    Text = "Questo è… anche un mio piccolo desiderio egoistico…"
  },
  AvgDialog_145524_Content_55 = {
    Text = "Gettò uno sguardo verso la cima più alta della montagna, immaginando i compagni della spedizione alpinistica che si sostenevano a vicenda nella scalata."
  },
  AvgDialog_145524_Content_56 = {
    Text = "Una Bugia era giunta al termine, quel viaggio non gli apparteneva più."
  },
  AvgDialog_145524_Content_57 = {
    Text = "Sostituire Una Bugia con un'altra bugia…"
  },
  AvgDialog_145524_Content_58 = {
    Text = "Addio… a tutti… che il vostro viaggio… giunga infine alla terra promessa…"
  },
  AvgDialog_145524_Content_59 = {
    Text = "Una Piuma nera si staccò dalle Piume di Castor, trascinata dal Vento di Neve verso l'alto."
  },
  AvgDialog_145524_Content_6 = {
    Text = "Proprio come un tempo, nel liquido amniotico."
  },
  AvgDialog_145524_Content_60 = {
    Text = "Lascia che vada al nostro posto, verso quella terra pura e innocente che hai desiderato…"
  },
  AvgDialog_145524_Content_61 = {
    Text = "Una fessura si aprì sotto i piedi dei due, inghiottendo lentamente ogni peso nelle nevi del ventre della montagna."
  },
  AvgDialog_145524_Content_62 = {
    Text = "Buonanotte, Pollux."
  },
  AvgDialog_145524_Content_63 = {
    Text = "Avete scalato nuovi sentieri di montagna, riassestando il pesante equipaggiamento."
  },
  AvgDialog_145524_Content_64 = {
    Text = "Un soffio di Vento di Neve Come Se dotato di volontà propria turbinò sopra di voi."
  },
  AvgDialog_145524_Content_65 = {
    Text = "Aspetta, quello è..."
  },
  AvgDialog_145524_Content_66 = {
    Text = "Nel Vento di Neve, una Piuma di un nero corvino scendeva lentamente volteggiando."
  },
  AvgDialog_145524_Content_67 = {
    Text = "Alzi la mano e il fiocco atterra dolcemente sul tuo palmo."
  },
  AvgDialog_145524_Content_68 = {
    Text = "Come una Benedizione Da Lontano."
  },
  AvgDialog_145524_Content_69 = {
    Text = "Altitudine -7000m-"
  },
  AvgDialog_145524_Content_7 = {
    Text = "Torna da me, Pollux. Come quando eravamo piccoli."
  },
  AvgDialog_145524_Content_8 = {
    Text = "La mente di Pollux era colma di confusione, di incomprensione. Eppure, per qualche ragione, non riuscì a respingere quel caldo abbraccio."
  },
  AvgDialog_145524_Content_9 = {
    Text = "Un rimprovero severo risuonò all'improvviso accanto al suo orecchio."
  },
  AvgDialog_145525_Content_1 = {
    Text = "La grotta tornò a una calma innaturale, e i presenti, ancora sconvolti, si scambiarono sguardi attoniti."
  },
  AvgDialog_145525_Content_10 = {
    Text = "Appena in questa montagna c'è qualcosa al di là della dea, una presenza che sta tramando di sottrarvi i vostri desideri."
  },
  AvgDialog_145525_Content_11 = {
    Text = "Smettila di spaventare tutti, Caraboo."
  },
  AvgDialog_145525_Content_12 = {
    Text = "Credete pure o no. La dea della montagna di Neve riesce a percepirla, è vicina alla nostra squadra, e ci segue da vicino…"
  },
  AvgDialog_145525_Content_13 = {
    Text = "Non riuscite a capire dal suo tono se stia fingendo o se abbia davvero percepito qualcosa."
  },
  AvgDialog_145525_Content_14 = {
    Text = "La tormenta si placa gradualmente."
  },
  AvgDialog_145525_Content_15 = {
    Text = "In mezzo a questo peso opprimente, riprendete il Viaggio."
  },
  AvgDialog_145525_Content_2 = {
    Text = "Strano, ho accompagnato la squadra alpinistica a questa quota molte volte, ma è la prima volta che mi capita una cosa del genere…"
  },
  AvgDialog_145525_Content_3 = {
    Text = "Questo dimostra che i pericoli su questa montagna di Neve non si limitano alle temperature di meno trenta gradi e alla mancanza di ossigeno ad alta quota."
  },
  AvgDialog_145525_Content_4 = {
    Text = "Caraboo abbassò la voce e parlò lentamente con un tono che faceva venire i brividi lungo la schiena."
  },
  AvgDialog_145525_Content_5 = {
    Text = "La dea della montagna di Neve esiste davvero."
  },
  AvgDialog_145525_Content_6 = {
    Text = "<Red:La dea della montagna non vi accoglie. Non accoglie coloro che mancano di devozione.>"
  },
  AvgDialog_145525_Content_7 = {
    Text = "L'aria si irrigidì."
  },
  AvgDialog_145525_Content_8 = {
    Text = "Vi stavo solo prendendo in giro! Non ci avrete creduto davvero!"
  },
  AvgDialog_145525_Content_9 = {
    Text = "Sono la dea della montagna di Neve più benevola che ci sia; con la mia benedizione, la montagna vi accoglierà e vi porterà fino alla vetta."
  },
  AvgDialog_145526_Content_1 = {
    Text = "Il Giorno dell'Abbandono del Nido"
  },
  AvgDialog_145526_Content_10 = {
    Text = "Abbiamo appena respinto un attacco, ma la sua offensiva non si fermerà."
  },
  AvgDialog_145526_Content_11 = {
    Text = "In un luogo pericoloso come la montagna, è inevitabile che le persone mostrino momenti di Fragilità e debolezza…"
  },
  AvgDialog_145526_Content_12 = {
    Text = "In quei momenti, è meglio ingannare."
  },
  AvgDialog_145526_Content_13 = {
    Text = "Caraboo tirò fuori una Mela da chissà dove, la morse con un crunch, con l'aria di chi dice \"quella frase non l'ho detta io\"."
  },
  AvgDialog_145526_Content_14 = {
    Text = "…Non hai tutti i torti a dirlo così."
  },
  AvgDialog_145526_Content_15 = {
    Text = "In ogni caso, dobbiamo trovarlo e poi catturarlo."
  },
  AvgDialog_145526_Content_16 = {
    Text = "Ma non lasciano tracce quando camminano sulla Neve, come faremo a…"
  },
  AvgDialog_145526_Content_17 = {
    Text = "Lasciate fare a me. Sono il migliore ad avere a che fare con gli ingannatori, no?"
  },
  AvgDialog_145526_Content_18 = {
    Text = "Guardate, stanno per arrivare."
  },
  AvgDialog_145526_Content_19 = {
    Text = "Caraboo indica l'ultimo cane guida che hai. Si è abbassato, guaendo piano."
  },
  AvgDialog_145526_Content_2 = {Text = "Wendigo."},
  AvgDialog_145526_Content_20 = {
    Text = "Non muovetevi e non parlate."
  },
  AvgDialog_145526_Content_21 = {
    Text = "Lei ti lancia la Mela di cui aveva già morso un pezzo."
  },
  AvgDialog_145526_Content_22 = {
    Text = "Nel taglio è nascosto un bigliettino: qualunque cosa dica da ora in poi, non crederci."
  },
  AvgDialog_145526_Content_23 = {
    Text = "Caraboo si calma, chiude gli occhi e poi li riapre."
  },
  AvgDialog_145526_Content_24 = {
    Text = "In quell'istante, il suo sguardo cambia. Confuso, ansioso, perso, sentimenti complessi racchiusi nei suoi piccoli occhi."
  },
  AvgDialog_145526_Content_25 = {
    Text = "<Shake:Zia Rosa, sei tu?>"
  },
  AvgDialog_145526_Content_26 = {
    Text = "<Shake:Stai preparando ancora la torta di Mele? Ne sento il profumo.>"
  },
  AvgDialog_145526_Content_27 = {
    Text = "<Shake:Zia Rosa, non mi lamenterò più che la crosta della torta di Mele è troppo spessa. Da allora, non ho mai più mangiato una torta di Mele così buona. Mi manca quel profumo tostato.>"
  },
  AvgDialog_145526_Content_28 = {
    Text = "<Shake:Zia Rosa. Adesso vengo da te, aspettami.>"
  },
  AvgDialog_145526_Content_29 = {
    Text = "Caraboo avanza barcollando."
  },
  AvgDialog_145526_Content_3 = {
    Text = "William scandisce le parole una ad una."
  },
  AvgDialog_145526_Content_30 = {
    Text = "Sulla Neve, dietro Caraboo, si sollevano all'improvviso due cumuli di neve alti quanto una persona e mezza."
  },
  AvgDialog_145526_Content_31 = {
    Text = "Si lancia verso Caraboo. Nel momento in cui balza, lei si abbassa di scatto."
  },
  AvgDialog_145526_Content_32 = {
    Text = "<Big:William, preparati!!>"
  },
  AvgDialog_145526_Content_4 = {
    Text = "<Italic:\"I suoi piedi sono forgiati dal fuoco — quando corre, la Neve brucia sotto di essi.\">"
  },
  AvgDialog_145526_Content_5 = {
    Text = "Nel settimo volume di \"Cronache delle Terre del Nord\" è scritto: <Italic:Chiunque oda il Sussurro nelle notti d'inverno, non deve rispondere.>"
  },
  AvgDialog_145526_Content_6 = {
    Text = "<Italic:Rispondi una volta, e esso Registra il tuo nome; rispondi due volte, e esso riconosce la tua ombra; rispondi una terza volta — e tu diventerai esso.>"
  },
  AvgDialog_145526_Content_7 = {
    Text = "Non possiamo aggirarlo?"
  },
  AvgDialog_145526_Content_8 = {
    Text = "È inutile, ovunque il Vento e la Neve si estendano, è territorio in cui il Wendigo vaga."
  },
  AvgDialog_145526_Content_9 = {
    Text = "Un tempo erano esseri umani. Si sono trasformati divorando i propri simili, e da allora le loro labbra e i loro denti marciscono, condannati a una Fame eterna — non si saziano nemmeno mangiando un'intera Foresta."
  },
  AvgDialog_145527_Content_1 = {Text = "Gli Zaini"},
  AvgDialog_145527_Content_10 = {Text = "No."},
  AvgDialog_145527_Content_100 = {
    Text = "Avvicinò i propri rami al braciere per accenderli, poi si unì a voi."
  },
  AvgDialog_145527_Content_101 = {
    Text = "Le fiamme si propagarono di ramo in ramo, e il Tremolio della luce illuminò uno ad uno ogni volto levato verso l'alto."
  },
  AvgDialog_145527_Content_102 = {
    Text = "Nel silenzio assoluto, Come Se si udissero provenire da non lontano il basso mormorio di canti sacri, il suono di campane e di tamburi."
  },
  AvgDialog_145527_Content_103 = {
    Text = "Gridate Lha Gyalo, poi gettateli nel fuoco."
  },
  AvgDialog_145527_Content_104 = {
    Text = "Una voce rauca ma potente Riverbero nell'aria rarefatta, e i rami tra le mani caddero uno ad uno nel fuoco al grido di battaglia."
  },
  AvgDialog_145527_Content_105 = {
    Text = "Grazie allo spirito della montagna, che perdona la nostra irriverenza nell'aver calpestato il suo dominio sacro."
  },
  AvgDialog_145527_Content_106 = {
    Text = "Rami di pino e cipresso crepitano nel fuoco, mandando fumo grigio che sale dritto verso l'alto prima di essere dilaniato dai venti forti."
  },
  AvgDialog_145527_Content_107 = {
    Text = "E tu hai fiutato in esso un vago presagio di sventura."
  },
  AvgDialog_145527_Content_108 = {Text = "..."},
  AvgDialog_145527_Content_109 = {
    Text = "Bene, ho terminato di illustrare a tutti i pericoli di questa scalata e i piani di emergenza."
  },
  AvgDialog_145527_Content_11 = {
    Text = "Ehi!!! Perché!!!"
  },
  AvgDialog_145527_Content_110 = {
    Text = "Nel corso dell'ultima Settimana, ognuno di voi si è già adattato a muoversi indossando guanti, scarponi da montagna e occhiali da neve, e ha esercitato e padroneggiato l'uso di corde e viti da ghiaccio."
  },
  AvgDialog_145527_Content_111 = {
    Text = "Sulla base del monitoraggio ravvicinato degli ultimi giorni, i prossimi 5-7 giorni rappresentano la finestra meteorologica più favorevole per la scalata: è il momento giusto per partire."
  },
  AvgDialog_145527_Content_112 = {
    Text = "Si prega di verificare le mappe del Sentiero, il cibo, il carburante, le bombole di ossigeno, i kit medici e gli altri rifornimenti che ognuno porta con sé."
  },
  AvgDialog_145527_Content_113 = {
    Text = "Ribadisco ancora una volta: durante la scalata è obbligatorio <Yellow:seguire scrupolosamente le istruzioni della guida>; ad eccezione dei membri che si ritirano anticipatamente, tutti gli altri <Yellow:non devono assolutamente abbandonare il gruppo>."
  },
  AvgDialog_145527_Content_114 = {
    Text = "Se siete pronti, partiamo!"
  },
  AvgDialog_145527_Content_115 = {Text = "..."},
  AvgDialog_145527_Content_116 = {Text = "..."},
  AvgDialog_145527_Content_117 = {
    Text = "Avete percorso la montagna per poco più di mezza giornata quando il cielo sereno si è improvvisamente coperto di nuvole."
  },
  AvgDialog_145527_Content_118 = {
    Text = "Il vento e la neve si intensificano bruscamente; persino i crinali delle montagne sono a malapena distinguibili, e i cani da guida guaiscono, riluttanti ad andare avanti."
  },
  AvgDialog_145527_Content_119 = {
    Text = "Strano, in base ai nostri rilevamenti non avrebbe dovuto manifestarsi così presto un'anomalia climatica."
  },
  AvgDialog_145527_Content_12 = {
    Text = "Anche loro due non si sono appena uniti al gruppo?"
  },
  AvgDialog_145527_Content_120 = {
    Text = "Avete mai incontrato una situazione simile in passato?"
  },
  AvgDialog_145527_Content_121 = {
    Text = "Mai. Anche quando i rilevamenti presentano scostamenti, di solito si verificano tre giorni dopo i risultati previsti."
  },
  AvgDialog_145527_Content_122 = {
    Text = "<Shake:Una tormenta innaturale… come se… <Yellow:la montagna ci stesse respingendo>.>"
  },
  AvgDialog_145527_Content_123 = {
    Text = "Impossibile! Come può essere, se io, la grande dea della montagna, sono proprio qui?"
  },
  AvgDialog_145527_Content_124 = {
    Text = "Non c'è bisogno di preoccuparsi troppo; anche durante la discesa capita a volte di imbattersi in tormente improvvise."
  },
  AvgDialog_145527_Content_125 = {
    Text = "Qui vicino c'è un rifugio, dove sono persino disponibili alcune scorte di rifornimento; andiamo a riposarci un po', aspettiamo che la tormenta si calmi e poi ripartiamo equipaggiati."
  },
  AvgDialog_145527_Content_126 = {
    Text = "Allora cosa aspettiamo, muoviamoci!"
  },
  AvgDialog_145527_Content_13 = {
    Text = "Caraboo, con un'espressione tutt'altro che convinta, allungò la mano e indicò te e William."
  },
  AvgDialog_145527_Content_14 = {
    Text = "È semplice. Loro due sono adulti, capaci di badare a se stessi."
  },
  AvgDialog_145527_Content_15 = {
    Text = "L'alpinismo non è un gioco da bambini, ragazzina."
  },
  AvgDialog_145527_Content_16 = {
    Text = "Qui puoi dichiararti padre, madre, dea della Neve o Volontà suprema, fa' pure."
  },
  AvgDialog_145527_Content_17 = {
    Text = "Ma una volta raggiunte le vette oltre i cinquemila metri, tutte le bugie verranno a galla tra il Vento, la Neve e il mal di montagna."
  },
  AvgDialog_145527_Content_18 = {
    Text = "Ma ho soldi, ne ho <Italic:TANTISSIMI>!"
  },
  AvgDialog_145527_Content_19 = {
    Text = "Sei solo una bambina, quanto puoi avere——"
  },
  AvgDialog_145527_Content_2 = {
    Text = "Sotto la guida di Naraka, tu e i membri della squadra di scalata vi presentate l'uno all'altro."
  },
  AvgDialog_145527_Content_20 = {Text = "<Big:!>"},
  AvgDialog_145527_Content_21 = {
    Text = "Le parole di Naraka si interruppero di colpo."
  },
  AvgDialog_145527_Content_22 = {
    Text = "La ragazza estrae una pesante borsa di tela, afferra una bella manciata di monete d'oro e le lascia ricadere nella borsa con un tintinnio a cascata. Ne trattiene solo una, facendola girare e volteggiare tra le dita."
  },
  AvgDialog_145527_Content_23 = {
    Text = "Ho detto che sono una fata, come potrei essere a corto di Beni Terreni come il denaro!"
  },
  AvgDialog_145527_Content_24 = {
    Text = "<Small:Ma non hai appena detto che eri una dea...?>"
  },
  AvgDialog_145527_Content_25 = {
    Text = "Non importa, a chi interessa!"
  },
  AvgDialog_145527_Content_26 = {
    Text = "Caraboo lanciò la moneta d'oro con noncuranza, e Naraka si sporse in fretta per prenderla, barcollando e mancando per poco di cadere nella Neve."
  },
  AvgDialog_145527_Content_27 = {
    Text = "La tenne tra le mani e la morse con i denti, raggiante di gioia."
  },
  AvgDialog_145527_Content_28 = {
    Text = "<Shake:È autentico...!>"
  },
  AvgDialog_145527_Content_29 = {
    Text = "Hmph, come potrebbero essere false le monete d'oro di una fata?"
  },
  AvgDialog_145527_Content_3 = {
    Text = "Tintura, una cantante misteriosa e distante, che afferma di voler ritrovare sua sorella."
  },
  AvgDialog_145527_Content_30 = {
    Text = "Comunque, ora potete portarmi con voi nella spedizione alpinistica, giusto?"
  },
  AvgDialog_145527_Content_31 = {
    Text = "<Shake:<Small:In effetti, far unire una bambina alla spedizione sarebbe un po' irresponsabile nei confronti della tua sicurezza…>>"
  },
  AvgDialog_145527_Content_32 = {
    Text = "<BigShake:Eh?>"
  },
  AvgDialog_145527_Content_33 = {
    Text = "Ma d'altra parte, la nostra spedizione ha una grande esperienza nell'arrampicata e risorse abbondanti, proteggere anche Te è <Big:più che sufficiente>!"
  },
  AvgDialog_145527_Content_34 = {
    Text = "Però ti avverto, se dovessi decidere di tornare indietro a metà strada, ti lasceremo le risorse necessarie per scendere, ma la tariffa da guida <Big:non verrà rimborsata>, eh."
  },
  AvgDialog_145527_Content_35 = {
    Text = "Sì sì, una fata si preoccuperebbe forse di questi spiccioli?"
  },
  AvgDialog_145527_Content_36 = {
    Text = "<Shake:<Small:Che strano, non stava forse mendicando con le sue esibizioni poco fa?>>"
  },
  AvgDialog_145527_Content_37 = {
    Text = "Non credere che non ti senta!"
  },
  AvgDialog_145527_Content_38 = {
    Text = "L'ho già detto, quella era un'Offerta! Quello che la dea raccoglie è la sincerità di tutti, capito?"
  },
  AvgDialog_145527_Content_39 = {
    Text = "<Shake:<Small:Quando non è necessario, l'udito è davvero ottimo...>>"
  },
  AvgDialog_145527_Content_4 = {
    Text = "Evelyn, un'archeologa, venuta in questo mondo post-apocalittico ancora per ragioni di ricerca scientifica."
  },
  AvgDialog_145527_Content_40 = {
    Text = "<BigShake:SENTO ANCHE QUELLO!>"
  },
  AvgDialog_145527_Content_41 = {
    Text = "Il gruppo fa l'inventario delle provviste, e la conversazione deriva presto al rituale."
  },
  AvgDialog_145527_Content_42 = {
    Text = "Credete davvero che sulla cima della montagna esista una dea capace di esaudire qualsiasi desiderio?"
  },
  AvgDialog_145527_Content_43 = {
    Text = "William chiede con aria apparentemente distratta."
  },
  AvgDialog_145527_Content_44 = {
    Text = "Almeno i Locali ci credono tutti. A causa della spedizione precedente."
  },
  AvgDialog_145527_Content_45 = {
    Text = "La spedizione precedente?"
  },
  AvgDialog_145527_Content_46 = {
    Text = "Sì. Da quando si sparse la voce della Dea della Montagna, Iperborea è diventata una terra interamente dominata dalla ricerca dei desideri, con un'intera società costruita attorno alla scalata. Quella squadra era la più disciplinata e preparata tra tutte quelle che avevano mai tentato; avevano le migliori possibilità di raggiungere la vetta."
  },
  AvgDialog_145527_Content_47 = {
    Text = "Erano in sette quando partirono. Ma durante la scalata, i membri della squadra morirono uno dopo l'altro."
  },
  AvgDialog_145527_Content_48 = {
    Text = "Qualcuno lasciò la tenda nel cuore della notte e camminò a piedi nudi nella tormenta di Neve; qualcuno tagliò la propria corda di sicurezza e si gettò giù da una parete di ghiaccio;"
  },
  AvgDialog_145527_Content_49 = {
    Text = "e qualcun altro scomparve per diversi giorni, per poi essere Scoperto congelato a morte davanti alla squadra—"
  },
  AvgDialog_145527_Content_5 = {
    Text = "Mentre stavate discutendo i piani per la partenza del giorno seguente, all'ingresso dell'accampamento spuntò all'improvviso una testa bianca."
  },
  AvgDialog_145527_Content_50 = {
    Text = "Come se, anche Dopo la morte, avesse continuato a scalare."
  },
  AvgDialog_145527_Content_51 = {
    Text = "I movimenti del gruppo nell'inventariare le provviste rallentarono all'unisono."
  },
  AvgDialog_145527_Content_52 = {
    Text = "Alla fine, Solo una persona tornò viva ai piedi della montagna."
  },
  AvgDialog_145527_Content_53 = {
    Text = "Anche se non si può dire che fosse davvero \"tornato vivo\"."
  },
  AvgDialog_145527_Content_54 = {
    Text = "Cosa intendi?"
  },
  AvgDialog_145527_Content_55 = {
    Text = "Le sue dieci dita erano tutte marcite per il gelo, le orecchie tappate di Neve mista a Sangue. Qualunque cosa gli chiedessero, lui non faceva altro che ripetere le stesse poche frasi."
  },
  AvgDialog_145527_Content_56 = {
    Text = "Naraka abbassò la voce, imitando il tono da Mormorii del sopravvissuto."
  },
  AvgDialog_145527_Content_57 = {
    Text = "<Shake:\"La leggenda è vera. Il desiderio sulla cima è vero.\">"
  },
  AvgDialog_145527_Content_58 = {
    Text = "<Shake:<Red:\"Tappati le orecchie, non ascoltare.\">>"
  },
  AvgDialog_145527_Content_59 = {
    Text = "<Shake:\"Chi sente il canto verrà sedotto, Divorato… e poi salirà al cielo, diventando la <Red:Luna>.\">"
  },
  AvgDialog_145527_Content_6 = {
    Text = "Senta~ questo è il gruppo alpinistico di Naraka?"
  },
  AvgDialog_145527_Content_60 = {Text = "E poi?"},
  AvgDialog_145527_Content_61 = {Text = "Dopo…"},
  AvgDialog_145527_Content_62 = {
    Text = "Naraka accennò uno strano sorriso ambiguo."
  },
  AvgDialog_145527_Content_63 = {
    Text = "La gente del posto credeva che avessero profanato la dea della montagna. Temendo che questi stranieri potessero attirare l'ira della dea sui loro villaggi…"
  },
  AvgDialog_145527_Content_64 = {
    Text = "Così scelsero una notte buia e tempestosa per gettarlo in una crepaccia di ghiaccio insondabile."
  },
  AvgDialog_145527_Content_65 = {
    Text = "È questo il finale della storia?"
  },
  AvgDialog_145527_Content_66 = {Text = "No."},
  AvgDialog_145527_Content_67 = {
    Text = "Da allora, ad ogni luna piena, chi passava vicino a quella crepaccia poteva ancora sentire qualcuno cantare Sotto."
  },
  AvgDialog_145527_Content_68 = {
    Text = "Così tutti capirono che diceva la verità. Sulla montagna doveva esserci qualcosa."
  },
  AvgDialog_145527_Content_69 = {
    Text = "Naraka abbassò di nuovo la testa, avvolgendo la corda in cerchi dentro Gli Zaini, Come Se quanto detto poco prima fosse solo una vecchia storia di nessuna importanza."
  },
  AvgDialog_145527_Content_7 = {
    Text = "Cercavi me?"
  },
  AvgDialog_145527_Content_70 = {
    Text = "Nel breve silenzio, Solo il Vento sfiorava la tenda, emettendo un lamento sottile e indistinto."
  },
  AvgDialog_145527_Content_71 = {
    Text = "Ho anche sentito dire che, durante la scalata, udirono il canto delle sirene."
  },
  AvgDialog_145527_Content_72 = {
    Text = "Stai di nuovo dicendo sciocchezze. Le sirene sono mostri marini, come potrebbero apparire su una montagna?"
  },
  AvgDialog_145527_Content_73 = {
    Text = "Caraboo fece il broncio con disappunto, emettendo un leggero sbuffo."
  },
  AvgDialog_145527_Content_74 = {
    Text = "Nel mare ci sono mostri che cantano, perché non potrebbero esserci anche in montagna?"
  },
  AvgDialog_145527_Content_75 = {
    Text = "Credici o no, come vuoi. Quando senti il canto, ricordati di tapparti le orecchie."
  },
  AvgDialog_145527_Content_76 = {
    Text = "Quando stavi per fare un'altra domanda, ti accorgesti che Caraboo si era già girato ed era entrato nella piccola capanna, senza alcuna intenzione di continuare la discussione."
  },
  AvgDialog_145527_Content_77 = {Text = "..."},
  AvgDialog_145527_Content_78 = {
    Text = "Sette giorni dopo"
  },
  AvgDialog_145527_Content_79 = {
    Text = "L'allenamento di oggi finisce qui. Domani è il giorno ufficiale della scalata."
  },
  AvgDialog_145527_Content_8 = {
    Text = "Eheh, ho sentito dire che sei la migliore guida alpina di tutto il popolo Sherpa!"
  },
  AvgDialog_145527_Content_80 = {
    Text = "Caraboo si fece avanti all'improvviso, bloccando Naraka che stava per andarsene."
  },
  AvgDialog_145527_Content_81 = {
    Text = "Non si terrà <Yellow:il Rituale Lhasang>?"
  },
  AvgDialog_145527_Content_82 = {
    Text = "Il Rituale Lhasang, cos'è?"
  },
  AvgDialog_145527_Content_83 = {
    Text = "Prima di ogni scalata, dieci Sherpa su dieci eseguono questo rituale di Preghiera. Non hai alcun rispetto per le Divinità?"
  },
  AvgDialog_145527_Content_84 = {
    Text = "Naraka si diede una mano sulla fronte."
  },
  AvgDialog_145527_Content_85 = {
    Text = "<Yellow:Ah, con tutto quello che stava succedendo, mi era passato di mente.>"
  },
  AvgDialog_145527_Content_86 = {
    Text = "Come si fa a dimenticare una cosa del genere?"
  },
  AvgDialog_145527_Content_87 = {
    Text = "Non importa, domani mattina ne faccio uno veloce e semplificato."
  },
  AvgDialog_145527_Content_88 = {Text = "..."},
  AvgDialog_145527_Content_89 = {
    Text = "Muovi le spalle indolenzite e apri la porta della stanza; nel corridoio si è già insinuato un tenue filo di fumo."
  },
  AvgDialog_145527_Content_9 = {
    Text = "Con la Benedizione della dea della Neve, potresti portarmi con te in montagna?"
  },
  AvgDialog_145527_Content_90 = {
    Text = "William è in piedi davanti allo specchio di bronzo a pochi passi da te, intento ad appianare una ad una le pieghe del colletto."
  },
  AvgDialog_145527_Content_91 = {
    Text = "Buongiorno, Custode."
  },
  AvgDialog_145527_Content_92 = {
    Text = "Annusi l'aria. L'aria porta il profumo di legno bruciato ed erbe aromatiche, con una fresca fragranza ghiacciata che si stratifica al di sotto."
  },
  AvgDialog_145527_Content_93 = {
    Text = "Apri il portone e il freddo e il denso profumo di fumo ti investono insieme."
  },
  AvgDialog_145527_Content_94 = {
    Text = "Nel cortile, su uno spazio aperto, arde un piccolo braciere. Un fumo bianco-azzurro si leva tra rami di pino e cipresso e erbe aromatiche, salendo dritto verso il cielo grigio-blu."
  },
  AvgDialog_145527_Content_95 = {
    Text = "Gli Sherpa venerano le vette come divinità, e sull'Everest risiede persino la dea Madre del Mondo."
  },
  AvgDialog_145527_Content_96 = {
    Text = "Prima della prima scalata ufficiale, gli Sherpa erigono un altare, issano le bandiere di preghiera, recitano i sutra e bruciano offerte rituali accanto all'altare, lasciando che il fumo trasmetta doni e Preghiere alle divinità."
  },
  AvgDialog_145527_Content_97 = {
    Text = "Il rituale propiziatorio è piuttosto elaborato; una cerimonia formale può durare anche tre o quattro ore."
  },
  AvgDialog_145527_Content_98 = {
    Text = "Naraka estrasse da un sacchetto di tela un fascio di rami di pino e cipresso e ne distribuì uno a ciascuno."
  },
  AvgDialog_145527_Content_99 = {
    Text = "Alzateli in alto, avvicinateli."
  },
  AvgDialog_145528_Content_1 = {
    Text = "Ti lanci su di lui, abbracciando stretto Castor per la vita da dietro. Castor continua a dibattersi, le sue corde vocali Quasi Squarciate dai singhiozzi nel Vento e nella Neve."
  },
  AvgDialog_145528_Content_10 = {
    Text = "Evelyn si avvicinò passo dopo passo. Si accovacciò, portandosi allo stesso livello del ragazzo che tu e William stavate tenendo bloccato nella neve."
  },
  AvgDialog_145528_Content_11 = {
    Text = "Castor, ascoltami. Anch'io credevo che il Wendigo fosse una creatura esistente solo nelle leggende."
  },
  AvgDialog_145528_Content_12 = {
    Text = "Ma poco fa… ho sentito."
  },
  AvgDialog_145528_Content_13 = {
    Text = "Ho sentito… mio marito che mi chiamava."
  },
  AvgDialog_145528_Content_14 = {
    Text = "Dal giorno della sua scomparsa, ogni giorno sento un Richiamo simile, ma nessuno mai così nitido, così reale…"
  },
  AvgDialog_145528_Content_15 = {
    Text = "La voce di Evelyn si fa leggermente rauca per un momento."
  },
  AvgDialog_145528_Content_16 = {
    Text = "<Shake:Ma Castor… lo sai…>"
  },
  AvgDialog_145528_Content_17 = {
    Text = "Sono passati più di novanta giorni da quando mio marito è scomparso sulla montagna innevata, il momento migliore per il salvataggio è ormai trascorso da tempo."
  },
  AvgDialog_145528_Content_18 = {
    Text = "Nel migliore dei casi, potrò solo imbattermi nelle sue ossa su qualche sentiero di montagna."
  },
  AvgDialog_145528_Content_19 = {
    Text = "Non sarà vivo… qui. Tuo fratello, tanto meno."
  },
  AvgDialog_145528_Content_2 = {
    Text = "Castor, non è lui."
  },
  AvgDialog_145528_Content_20 = {
    Text = "Dobbiamo salire, continuare a salire fino alla cima della montagna."
  },
  AvgDialog_145528_Content_21 = {
    Text = "È l'unica possibilità che abbiamo di avere una Riunione con loro."
  },
  AvgDialog_145528_Content_22 = {
    Text = "Castor, rassicurato dalle parole di Evelyn, si calmò gradualmente."
  },
  AvgDialog_145528_Content_23 = {
    Text = "Hai ragione… sulla montagna innevata non ci sarebbero celle di isolamento… lui non è in un posto simile."
  },
  AvgDialog_145528_Content_24 = {
    Text = "Andrò avanti… fino alla Riunione con lui."
  },
  AvgDialog_145528_Content_25 = {
    Text = "Alle vostre spalle, qualcuno impugnò un piccone da ghiaccio e bussò due volte sulla roccia con un suono secco."
  },
  AvgDialog_145528_Content_26 = {
    Text = "Se le emozioni di tutti si sono stabilizzate, dobbiamo prepararci ad affrontare la vera minaccia."
  },
  AvgDialog_145528_Content_27 = {
    Text = "<Yellow:Wendigo>."
  },
  AvgDialog_145528_Content_3 = {
    Text = "<Shake:Come fai a sapere che non è lui?! Tu non lo conosci nemmeno!>"
  },
  AvgDialog_145528_Content_4 = {
    Text = "Nessuno di voi lo conosce! Solo io lo conosco, conosco la sua voce!! Sono io che l'ho abbandonato lì!"
  },
  AvgDialog_145528_Content_5 = {
    Text = "È la prima volta che alza la voce con William. Poi si spaventa della propria voce."
  },
  AvgDialog_145528_Content_6 = {
    Text = "Castor, calmati, quello è un <Yellow:Wendigo>."
  },
  AvgDialog_145528_Content_7 = {
    Text = "Il Wendigo, mostro della montagna… scava nell'ombra più profonda del tuo cuore…"
  },
  AvgDialog_145528_Content_8 = {
    Text = "Poi, prende in prestito la voce di chi ami e seduce il Disperso, attirándolo nella sua trappola."
  },
  AvgDialog_145528_Content_9 = {
    Text = "<Shake:No, con che certezza dici——>"
  },
  AvgDialog_145529_Content_1 = {
    Text = "Un'Altra Primavera"
  },
  AvgDialog_145529_Content_10 = {
    Text = "<Shake:Questo posto… dove sono?>"
  },
  AvgDialog_145529_Content_100 = {
    Text = "Che fosse una vita tranquilla, o un anziano premuroso."
  },
  AvgDialog_145529_Content_101 = {
    Text = "Persino quel piccolo coniglio."
  },
  AvgDialog_145529_Content_102 = {
    Text = "Il lepre selvatico nel campo si voltò, i suoi due Occhi tondi e rotondi incontrarono i suoi."
  },
  AvgDialog_145529_Content_103 = {
    Text = "Poi si girò, scalciò via la terra con le zampe posteriori e si infilò nella tana di fango."
  },
  AvgDialog_145529_Content_11 = {
    Text = "Stando alle ultime parole di Caraboo, ci troviamo ora nel ventre della montagna, in Allineamento."
  },
  AvgDialog_145529_Content_12 = {
    Text = "La priorità assoluta è trovare il Sentiero per La Fuga."
  },
  AvgDialog_145529_Content_13 = {
    Text = "Non sono mai stato in questo posto, temo di non poter fare da guida per voi."
  },
  AvgDialog_145529_Content_14 = {
    Text = "Non preoccuparti, abbiamo vissuto momenti ben più difficili di così."
  },
  AvgDialog_145529_Content_15 = {
    Text = "%player%, cos'hai in mano?"
  },
  AvgDialog_145529_Content_16 = {
    Text = "Oh, questo è… il Filo di Arachne…"
  },
  AvgDialog_145529_Content_17 = {
    Text = "Senza che tu te ne accorgessi, questo Filo si è avvolto silenziosamente attorno al tuo mignolo."
  },
  AvgDialog_145529_Content_18 = {
    Text = "Il Filo, un tempo avvolto nel Silenzio e dalla consistenza morbida, ora brilla e scorre con un bagliore ipnotico, la sua estremità si allunga naturalmente verso l'Oscurità lontana."
  },
  AvgDialog_145529_Content_19 = {
    Text = "È la guida del Destino? Seguiamolo e vediamo dove porta."
  },
  AvgDialog_145529_Content_2 = {
    Text = "Oscurità. Oscurità infinita."
  },
  AvgDialog_145529_Content_20 = {
    Text = "Caraboo seguì il Filo, senza sapere per quanto tempo avanzò. In fondo al Filo, apparve un barlume di luce."
  },
  AvgDialog_145529_Content_21 = {Text = "Luce… ?"},
  AvgDialog_145529_Content_22 = {
    Text = "La luce e le ombre mutarono all'improvviso."
  },
  AvgDialog_145529_Content_23 = {
    Text = "Questo luogo..."
  },
  AvgDialog_145529_Content_24 = {
    Text = "Ehi, Caraboo, rallenta!"
  },
  AvgDialog_145529_Content_25 = {
    Text = "Guarda, Zia Rosa, là ci sono dei conigli!"
  },
  AvgDialog_145529_Content_26 = {
    Text = "È scappato in una tana!"
  },
  AvgDialog_145529_Content_27 = {
    Text = "Lei aspettò dal giorno alla notte, ma i conigli non uscirono mai."
  },
  AvgDialog_145529_Content_28 = {
    Text = "Zia Rosa, l'ho visto con i miei occhi! Il coniglio è entrato proprio in questo buco!"
  },
  AvgDialog_145529_Content_29 = {
    Text = "Zia Rosa accarezzò dolcemente i capelli di Caraboo."
  },
  AvgDialog_145529_Content_3 = {
    Text = "Fa male, fa male, fa male… Dove mi trovo?"
  },
  AvgDialog_145529_Content_30 = {
    Text = "Sciocca bambina, i conigli non sono animali così semplici."
  },
  AvgDialog_145529_Content_31 = {
    Text = "Le tane sotto questi campi sono come una grande e intricata rete di tunnel. Sono tutte collegate."
  },
  AvgDialog_145529_Content_32 = {
    Text = "Quel coniglietto bianco che avevi adocchiato è già scappato chissà da quale altra tana."
  },
  AvgDialog_145529_Content_33 = {
    Text = "E allora cosa si fa?"
  },
  AvgDialog_145529_Content_34 = {
    Text = "Niente, piccola Caraboo."
  },
  AvgDialog_145529_Content_35 = {
    Text = "Noi seminiamo nei campi, li irrighiamo, aspettiamo che maturino, raccogliamo e gustiamo i frutti che le Divinità ci donano."
  },
  AvgDialog_145529_Content_36 = {
    Text = "Ma, e se volessi quel coniglio?"
  },
  AvgDialog_145529_Content_37 = {
    Text = "Cara piccola Caraboo, non dobbiamo desiderare quel coniglio. Se vuoi mangiare della carne, possiamo andare al mercato e scambiarla con frutta e verdura."
  },
  AvgDialog_145529_Content_38 = {
    Text = "Ma, e se lo volessi ancora quel coniglio?"
  },
  AvgDialog_145529_Content_39 = {
    Text = "<Red:Perché… Perché non posso avere quel coniglio?>"
  },
  AvgDialog_145529_Content_4 = {
    Text = "Non aveva bisogno di chiedere per saperlo. Era nel ventre del verme."
  },
  AvgDialog_145529_Content_40 = {Text = "..."},
  AvgDialog_145529_Content_41 = {Text = "..."},
  AvgDialog_145529_Content_42 = {
    Text = "Perché proprio adesso, vedo i ricordi della mia Infanzia…?"
  },
  AvgDialog_145529_Content_43 = {
    Text = "Calma. Forse ho un Fantasma perché cammino nell'Oscurità da troppo tempo."
  },
  AvgDialog_145529_Content_44 = {
    Text = "Non è mica un Fantasma, sai?"
  },
  AvgDialog_145529_Content_45 = {
    Text = "<Shake:Aaaah! Un fantasma!!>"
  },
  AvgDialog_145529_Content_46 = {
    Text = "Ricordi uno dei sette artefatti sacri, il Filo del Destino? Ciò che vedi è la Traccia del Destino."
  },
  AvgDialog_145529_Content_47 = {
    Text = "Ora la Traccia del Destino ti mostrerà un'altra possibilità e il suo punto di divergenza."
  },
  AvgDialog_145529_Content_48 = {
    Text = "Cosa c'entra tutto questo con il fatto che sono intrappolata nello stomaco di un mostro in questo momento?"
  },
  AvgDialog_145529_Content_49 = {
    Text = "Perché quello era il tuo desiderio. I desideri sono la miccia, che guida ognuno verso la propria fine predestinata."
  },
  AvgDialog_145529_Content_5 = {
    Text = "Maledizione, mi ha attirata dentro, e alla fine sono stata io a essere divorata."
  },
  AvgDialog_145529_Content_50 = {
    Text = "Basta con gli indovinelli! Potresti usare un po' di quel fiato per dirmi come uscire da qui invece?! <BigShake:EHI—>"
  },
  AvgDialog_145529_Content_51 = {
    Text = "L'ombra svanì in silenzio."
  },
  AvgDialog_145529_Content_52 = {
    Text = "Bah, che tirchio. Non c'è niente da fare, tanto nella cavità addominale del verme non ci sono altri bivi, andiamo avanti."
  },
  AvgDialog_145529_Content_53 = {Text = "..."},
  AvgDialog_145529_Content_54 = {Text = "..."},
  AvgDialog_145529_Content_55 = {
    Text = "Zia Rosa! Non si preoccupi, arrivo subito ad aiutarla!"
  },
  AvgDialog_145529_Content_56 = {
    Text = "Questa sono… io?"
  },
  AvgDialog_145529_Content_57 = {
    Text = "Brava bambina, la zia è venuta Appena a farti una visita."
  },
  AvgDialog_145529_Content_58 = {
    Text = "Zia, lei ha problemi alle gambe, non deve venire sempre nella piantagione. Finisco di raccogliere questo basilico e torno con lei a dar da mangiare ai conigli."
  },
  AvgDialog_145529_Content_59 = {
    Text = "Li hai già visti? Lattuga ha partorito la notte scorsa! Tanti coniglietti, tutti di colori diversi!"
  },
  AvgDialog_145529_Content_6 = {
    Text = "Aspetta, cos'è questo? Un Filo…?"
  },
  AvgDialog_145529_Content_60 = {
    Text = "La nostra Caraboo è diventata una signorina."
  },
  AvgDialog_145529_Content_61 = {
    Text = "Zia, cosa sta dicendo. Questi lavori nei campi li facevo già da sola a tredici anni."
  },
  AvgDialog_145529_Content_62 = {
    Text = "La decisione più giusta che la zia abbia preso in tutta la sua vita è stata portarti via dai tuoi genitori e tenerti con me."
  },
  AvgDialog_145529_Content_63 = {
    Text = "Quando mi hai detto che tuo padre ubriaco ti picchiava, ho esitato per tutta una notte, poi alla Prima Mattina sono salita sul primo treno disponibile."
  },
  AvgDialog_145529_Content_64 = {
    Text = "Ho quasi fatto a pugni con tuo padre prima di riportarti via."
  },
  AvgDialog_145529_Content_65 = {
    Text = "Da allora sono passati quasi dieci anni, vero?"
  },
  AvgDialog_145529_Content_66 = {
    Text = "Ora, senza di te, con queste gambe, non saprei proprio come vivere da sola—"
  },
  AvgDialog_145529_Content_67 = {
    Text = "Ah— Ah—"
  },
  AvgDialog_145529_Content_68 = {
    Text = "Questa è... un'altra possibilità di quella notte— di quella notte—"
  },
  AvgDialog_145529_Content_69 = {
    Text = "Quella notte, la notte in cui incontrò il \"Verme della Montagna\", la notte in cui decise di liberarsi con le proprie mani dal Destino."
  },
  AvgDialog_145529_Content_7 = {
    Text = "Un Filo cristallino e luminoso emergeva dall'Oscurità lontana, librandosi davanti a Caraboo."
  },
  AvgDialog_145529_Content_70 = {
    Text = "Appartenente al mondo reale, quella notte che lei aveva vissuto."
  },
  AvgDialog_145529_Content_71 = {
    Text = "Nel crepitio delle fiamme del camino, lei stava in piedi davanti al letto del padre ubriaco, esitando a lungo, a lungo."
  },
  AvgDialog_145529_Content_72 = {
    Text = "Vai, fai ciò che hai sempre voluto fare."
  },
  AvgDialog_145529_Content_73 = {
    Text = "Lei alzò il coltello—"
  },
  AvgDialog_145529_Content_74 = {
    Text = "Esatto, proprio così."
  },
  AvgDialog_145529_Content_75 = {
    Text = "Uccidilo, e tutti potranno essere felici."
  },
  AvgDialog_145529_Content_76 = {
    Text = "Poi lentamente, lentamente lo abbassò."
  },
  AvgDialog_145529_Content_77 = {
    Text = "Mi dispiace, non riesco ancora a farlo."
  },
  AvgDialog_145529_Content_78 = {
    Text = "Vattene, Purché tu fugga lontano da qui, non dovrai più sopportare il dolore."
  },
  AvgDialog_145529_Content_79 = {
    Text = "Piccola inutile."
  },
  AvgDialog_145529_Content_8 = {
    Text = "Non importa, non importa, è meglio che tu non mi stia ingannando!"
  },
  AvgDialog_145529_Content_80 = {
    Text = "Va bene lo stesso, ciò che ho visto in te è qualcos'altro."
  },
  AvgDialog_145529_Content_81 = {
    Text = "Andiamo, con quella tua lingua scaltra, riusciremo comunque a ottenere il tesoro più prezioso."
  },
  AvgDialog_145529_Content_82 = {
    Text = "La mattina seguente, mi nascosi di nascosto nella paglia di un carro trainato da buoi e mi infiltrai nella città più vicina."
  },
  AvgDialog_145529_Content_83 = {
    Text = "Poi, grazie a un'Identità e a documenti falsificati, salii sul treno diretto a est."
  },
  AvgDialog_145529_Content_84 = {
    Text = "Da allora, ho avuto molte Identità: la nipote del capotreno, l'amica della Guardia, la Fata del Sacro Ordine, la dea della montagna di Neve…"
  },
  AvgDialog_145529_Content_85 = {
    Text = "Ho lasciato tutto il mio passato alle spalle, abbandonato in quella notte di grande Neve durante la fuga."
  },
  AvgDialog_145529_Content_86 = {
    Text = "Dopo, molto molto tempo Dopo, venni a sapere da un compaesano incontrato per caso sul campo di battaglia—"
  },
  AvgDialog_145529_Content_87 = {
    Text = "Il signor Hans?"
  },
  AvgDialog_145529_Content_88 = {
    Text = "Un giorno di grande Neve, era ubriaco fradicio."
  },
  AvgDialog_145529_Content_89 = {
    Text = "Il fuoco nel camino era stato spento dalla Neve sciolta che colava dal soffitto; di solito, la sua bambina andava ad accenderlo di nuovo."
  },
  AvgDialog_145529_Content_9 = {
    Text = "Ti risvegli dal torpore, e davanti a te si apre un vuoto soffice, umido e opprimente."
  },
  AvgDialog_145529_Content_90 = {
    Text = "Appena quel giorno, quella bambina non era in Casa Nostra per qualche motivo."
  },
  AvgDialog_145529_Content_91 = {
    Text = "Morì assiderato in quella notte di Neve."
  },
  AvgDialog_145529_Content_92 = {
    Text = "Dopo non abbiamo più rivisto quella bambina."
  },
  AvgDialog_145529_Content_93 = {
    Text = "Ah già, grande Fata, perché chiede improvvisamente di questo? La mia Benedizione, me la può dare adesso?"
  },
  AvgDialog_145529_Content_94 = {
    Text = "Caraboo prese una bella manciata di caramelle e le porse al giovane davanti a Lei."
  },
  AvgDialog_145529_Content_95 = {
    Text = "Per la Fata in alto, una al giorno: quando avrai finito queste caramelle benedette, la tua gamba guarirà."
  },
  AvgDialog_145529_Content_96 = {
    Text = "Anche se Lei sapeva bene nel suo cuore che nessuna caramella avrebbe mai potuto guarire le gambe già amputate del giovane."
  },
  AvgDialog_145529_Content_97 = {Text = "..."},
  AvgDialog_145529_Content_98 = {Text = "..."},
  AvgDialog_145529_Content_99 = {
    Text = "Ridicolo, davvero ridicolo. Quella notte, Purché non avessi fatto nulla, avrei potuto ottenere la felicità che desideravo."
  },
  AvgDialog_145530_Content_1 = {
    Text = "Il Lungo Sogno"
  },
  AvgDialog_145530_Content_10 = {
    Text = "Se è così, ti sostengo."
  },
  AvgDialog_145530_Content_11 = {
    Text = "Ti sostengo nel ritrovare quella parte di Te che era stata gettata via."
  },
  AvgDialog_145530_Content_12 = {
    Text = "Dopotutto, siamo sempre stati le persone più Egoiste."
  },
  AvgDialog_145530_Content_13 = {
    Text = "La montagna di Neve morì."
  },
  AvgDialog_145530_Content_14 = {
    Text = "<Shake:È finita…>"
  },
  AvgDialog_145530_Content_15 = {
    Text = "Al centro della montagna di Neve si aprì una Ferita agghiacciante, dalla sommità del verme fino all'estremità della cavità addominale."
  },
  AvgDialog_145530_Content_16 = {
    Text = "Il corpo del verme, lungo quella Ferita, lentamente, lentamente, cedette verso i due lati."
  },
  AvgDialog_145530_Content_17 = {
    Text = "Anche voi precipitaste verso il basso insieme al crollo della vetta."
  },
  AvgDialog_145530_Content_18 = {
    Text = "<Shake:Attenzione, sta crollando!>"
  },
  AvgDialog_145530_Content_19 = {
    Text = "Nel Vento della caduta, all'improvviso, udisti un Sussurro."
  },
  AvgDialog_145530_Content_2 = {
    Text = "Hai deciso?"
  },
  AvgDialog_145530_Content_20 = {
    Text = "Non è ancora finita."
  },
  AvgDialog_145530_Content_21 = {
    Text = "Caraboo tese la mano."
  },
  AvgDialog_145530_Content_22 = {
    Text = "Sul Volto di Lei, rigato di lacrime, apparve un sorriso noncurante."
  },
  AvgDialog_145530_Content_23 = {
    Text = "Poi, nella forza di gravità che non potevate controllare, i sette anelli di luce si illuminarono."
  },
  AvgDialog_145530_Content_24 = {
    Text = "Ciò che è morto… Solo la montagna innevata… Il rituale… È ancora in funzione!"
  },
  AvgDialog_145530_Content_25 = {
    Text = "In quell'istante, Come Se il cielo e la Terra avessero perso ogni suono."
  },
  AvgDialog_145530_Content_26 = {
    Text = "Tu vedevi Solo le sue labbra muoversi appena, pronunciando parole che Solo dopo molti secondi avrebbero cominciato a risuonare tra il cielo e la Terra."
  },
  AvgDialog_145530_Content_27 = {
    Text = "Il mio desiderio è che in questo mondo non esista più alcuna bugia."
  },
  AvgDialog_145530_Content_28 = {
    Text = "Nell'istante in cui le sue parole uscirono, il mondo davanti a Lei si dissolse."
  },
  AvgDialog_145530_Content_29 = {
    Text = "Cenere argentata, abbondante e leggera, cadeva dall'alto lontano con estrema lentezza."
  },
  AvgDialog_145530_Content_3 = {
    Text = "Sì, ho già preso la mia decisione."
  },
  AvgDialog_145530_Content_30 = {
    Text = "Fu un crollo silenzioso, un Crollo lento, il Cala il Sipario di un Sogno antico e senza tempo."
  },
  AvgDialog_145530_Content_31 = {Text = "Le vette."},
  AvgDialog_145530_Content_32 = {
    Text = "La Neve accumulata."
  },
  AvgDialog_145530_Content_33 = {Text = "Il cielo."},
  AvgDialog_145530_Content_34 = {Text = "La Terra."},
  AvgDialog_145530_Content_35 = {
    Text = "Tutto ciò che era stato, Come Se Una Bugia smascherata, si dissolse nell'Illusione."
  },
  AvgDialog_145530_Content_36 = {
    Text = "...Perché?"
  },
  AvgDialog_145530_Content_37 = {
    Text = "Una conoscenza che Tu non avresti dovuto possedere, insieme a ricordi lontani, si conficcò nella tua mente come uno Spuntone."
  },
  AvgDialog_145530_Content_38 = {
    Text = "Questa nave è un sogno, ma quando il sipario di menzogne viene sollevato..."
  },
  AvgDialog_145530_Content_39 = {
    Text = "Ti renderai conto che anche questo intero mondo è il Sogno di Qualcuno, solo che quel sogno è più grande, più illusorio e più distante..."
  },
  AvgDialog_145530_Content_4 = {
    Text = "È Una Bugia, è un tradimento."
  },
  AvgDialog_145530_Content_40 = {
    Text = "Persino il sole, la luna e le stelle hanno origine dalla Sua illusione; solo gli esseri intrecciati con il Suo spirito possono @3..."
  },
  AvgDialog_145530_Content_41 = {
    Text = "<Italic:Il mondo intero è un'enorme bugia.>"
  },
  AvgDialog_145530_Content_42 = {
    Text = "Con questa consapevolezza, la dissoluzione accelerò. Dal cielo cominciò a cadere una fitta pioggia argentata."
  },
  AvgDialog_145530_Content_43 = {
    Text = "La pioggia cadeva nell'acqua. Quei frammenti che un tempo erano stati il \"mondo\" si trasformarono in gocce argentate, scendendo lentamente verso un mare senza fondo."
  },
  AvgDialog_145530_Content_44 = {
    Text = "E Tu eri lì, in quell'acqua marina."
  },
  AvgDialog_145530_Content_45 = {
    Text = "Sprofondando, sprofondando."
  },
  AvgDialog_145530_Content_46 = {
    Text = "Finché il lungo Sogno illusorio non giunse al termine e Tu riapristi gli occhi."
  },
  AvgDialog_145530_Content_47 = {
    Text = "Guardando in faccia la Verità Nascosta di questo mondo."
  },
  AvgDialog_145530_Content_48 = {
    Text = "Nel fondo più profondo e oscuro dell'Aequor."
  },
  AvgDialog_145530_Content_49 = {
    Text = "Il grandioso Regno divino, ormai caduto in rovina, ha finalmente rivelato il suo vero aspetto."
  },
  AvgDialog_145530_Content_5 = {
    Text = "Tutti si sono presi cura di Te, e anche loro hanno desideri che vogliono realizzare."
  },
  AvgDialog_145530_Content_6 = {
    Text = "Ma l'occasione per esprimere un desiderio è Solo una."
  },
  AvgDialog_145530_Content_7 = {
    Text = "Anche così, vuoi ancora esprimere <Yellow:\"quel\"> desiderio?"
  },
  AvgDialog_145530_Content_8 = {
    Text = "Non c'è nessun desiderio più importante di questo."
  },
  AvgDialog_145530_Content_9 = {
    Text = "L'ombra sorrise."
  },
  AvgDialog_145531_Content_1 = {Text = "Buonanotte"},
  AvgDialog_145531_Content_10 = {
    Text = "Alle sue spalle, qualcuno aprì silenziosamente un Occhio, spiando la sua figura che si allontanava."
  },
  AvgDialog_145531_Content_11 = {
    Text = "Tintura seguiva lentamente la direzione da cui proveniva il canto, mentre i frammenti di ghiaccio e il permafrost scricchiolavano sotto le sue scarpe dalla suola sottile."
  },
  AvgDialog_145531_Content_12 = {
    Text = "(Questo è… il lago ghiacciato di oggi…)"
  },
  AvgDialog_145531_Content_13 = {
    Text = "(Ma c'è qualcosa di diverso…)"
  },
  AvgDialog_145531_Content_14 = {
    Text = "Il lago, rimasto ghiacciato durante il giorno, si era risvegliato per qualche ragione inspiegabile."
  },
  AvgDialog_145531_Content_15 = {
    Text = "La superficie dell'acqua, silenziosa e immobile, aprì gli Occhi verso il cielo, come uno specchio limpido che rifletteva in silenzio l'eterna Luna."
  },
  AvgDialog_145531_Content_16 = {
    Text = "Faint, sei tu?"
  },
  AvgDialog_145531_Content_17 = {
    Text = "(L'acqua del lago… insolitamente limpida…)"
  },
  AvgDialog_145531_Content_18 = {
    Text = "Lei guardò verso il fondo del lago."
  },
  AvgDialog_145531_Content_19 = {
    Text = "L'acqua del lago era così profonda da non vederne il fondo, come se Perforasse la Terra, conducendo verso un luogo ancora più lontano delle Stelle."
  },
  AvgDialog_145531_Content_2 = {
    Text = "A mezzanotte, Tintura viene svegliata da un suono lontano e fioco."
  },
  AvgDialog_145531_Content_20 = {
    Text = "Una canzone si diffonde nel vento. Rauca, antica, come se avesse resistito a un passaggio di tempo inimmaginabilmente lungo e non si fosse ancora fermata."
  },
  AvgDialog_145531_Content_21 = {
    Text = "<Italic:La—la la~ la~ ♪>"
  },
  AvgDialog_145531_Content_22 = {
    Text = "Tintura chiuse gli occhi e respirò profondamente."
  },
  AvgDialog_145531_Content_23 = {
    Text = "(Una melodia familiare… un'atmosfera… nostalgica…)"
  },
  AvgDialog_145531_Content_24 = {
    Text = "La qualità di quella voce faceva pensare a un letto di fiume prosciugato, agli strati di arenaria erosi dal vento per centomila anni, alle grida delle antiche Foreste compresse in carbone sotto il peso delle ere geologiche."
  },
  AvgDialog_145531_Content_25 = {
    Text = "(Questa sembra essere… una melodia… proveniente dal Desolato…)"
  },
  AvgDialog_145531_Content_26 = {
    Text = "I ricordi di mille anni fa cominciarono lentamente a Rianimarsi, e Lei iniziò a tentare di canticchiare, cercando di seguire quel canto sfuggente."
  },
  AvgDialog_145531_Content_27 = {
    Text = "<Shake:La la~ la la la~♪>"
  },
  AvgDialog_145531_Content_28 = {
    Text = "Lei lo sentì, Lei lo colse."
  },
  AvgDialog_145531_Content_29 = {
    Text = "Sul Il Volto di Lei affiorò una gioia sincera."
  },
  AvgDialog_145531_Content_3 = {
    Text = "(Fuori... questo è... un canto?)"
  },
  AvgDialog_145531_Content_30 = {
    Text = "La sua estensione vocale si espanse, verso l'alto. Una voce limpida come quella di un usignolo si Intrecciò con dolcezza e leggerezza alla melodia di fondo rauca."
  },
  AvgDialog_145531_Content_31 = {
    Text = "Le due voci cominciarono a tirarsi, intrecciarsi, avvicinarsi."
  },
  AvgDialog_145531_Content_32 = {
    Text = "<Change>La la la la la la~♪"
  },
  AvgDialog_145531_Content_33 = {
    Text = "Lo strato di ghiaccio si chiuse centimetro per centimetro; nelle profondità del lago, innumerevoli volti pallidi e spettrali alzarono lo sguardo seguendo il canto."
  },
  AvgDialog_145531_Content_34 = {
    Text = "Ma Tintura non se ne accorse affatto."
  },
  AvgDialog_145531_Content_35 = {
    Text = "Solo il canto. Il canto attraversò I Prigionieri della Neve e il permafrost, attraversò l'universo stellato, attraversò le ere eterne, trasformandosi in qualcosa che ogni essere dovrebbe considerare eterno."
  },
  AvgDialog_145531_Content_36 = {
    Text = "Sì, non dovrei più ingannare me stessa…"
  },
  AvgDialog_145531_Content_37 = {
    Text = "Ormai… non voglio più cercare… La speranza non esiste da nessuna parte… Lei è nei miei ricordi, e solo nei miei ricordi…"
  },
  AvgDialog_145531_Content_38 = {
    Text = "Il Vecchio Amico nell'acqua le tende la mano."
  },
  AvgDialog_145531_Content_39 = {
    Text = "Una voce cantilenante e anziana la chiama con dolcezza, pronunciando il suo nome di mille anni fa."
  },
  AvgDialog_145531_Content_4 = {
    Text = "Il suono è estremamente tenue, filtra da qualche profondità insondabile attraverso innumerevoli strati di ghiaccio, neve e roccia."
  },
  AvgDialog_145531_Content_41 = {
    Text = "Dovrei arrendermi…"
  },
  AvgDialog_145531_Content_42 = {
    Text = "Questo viaggio è stato troppo lungo, troppo lungo… sono già esausta da tempo…"
  },
  AvgDialog_145531_Content_43 = {
    Text = "Il Richiamo vibrava lungo le sue ossa, donandole il conforto che tanto desiderava. La sua angoscia senza dimora, il suo dolore senza sfogo, venivano finalmente compresi e accolti in pieno da qualcosa."
  },
  AvgDialog_145531_Content_44 = {
    Text = "<Shake:Abbracciami, Faint… ombra nei miei ricordi… abbracciami, come un tempo…>"
  },
  AvgDialog_145531_Content_45 = {
    Text = "<Shake:Concedimi… la Ning che tanto desidero…>"
  },
  AvgDialog_145531_Content_46 = {
    Text = "Lentamente, piano piano, entrò nelle acque silenziose del lago."
  },
  AvgDialog_145531_Content_47 = {
    Text = "Il lago non increspa nemmeno un'onda. Come una lingua fredda, la lambisce teneramente alla vita, alle spalle, alla gola."
  },
  AvgDialog_145531_Content_48 = {
    Text = "<Change>La la la…"
  },
  AvgDialog_145531_Content_49 = {
    Text = "Continuava a cantare."
  },
  AvgDialog_145531_Content_5 = {
    Text = "È rauca e lenta, ogni sillaba suona come sabbia trascinata dal vento che rotola sulla terra. Ostinata e incessante, continua come un fiume sotterraneo che scorre per sempre."
  },
  AvgDialog_145531_Content_50 = {
    Text = "La sua figura, il suo corpo, la sua esistenza si dissolsero insieme al canto, fondendosi e disperdendosi nella luce lunare."
  },
  AvgDialog_145531_Content_51 = {
    Text = "Un pensiero, un pensiero così flebile da essere Quasi impossibile da cogliere, in quell'istante, si insinuò stranamente nella coscienza di Tintura."
  },
  AvgDialog_145531_Content_52 = {
    Text = "(Strano… oggi… avrebbe dovuto essere luna nuova…)"
  },
  AvgDialog_145531_Content_53 = {
    Text = "E poi — la superficie del lago sprofondò improvvisamente verso l'interno."
  },
  AvgDialog_145531_Content_54 = {
    Text = "Nessuno schizzo, nessun grido. Solo il canto che aleggiava nell'aria."
  },
  AvgDialog_145531_Content_55 = {
    Text = "La Luna in cielo era scomparsa chissà quando."
  },
  AvgDialog_145531_Content_56 = {
    Text = "Rimase solo l'acqua del lago che ondeggiava con il riflesso della luna, in cui si specchiava nitida l'ombra di Tintura."
  },
  AvgDialog_145531_Content_57 = {Text = "..."},
  AvgDialog_145531_Content_58 = {
    Text = "La mattina seguente."
  },
  AvgDialog_145531_Content_59 = {
    Text = "Qualcuno ha visto Tintura?"
  },
  AvgDialog_145531_Content_6 = {
    Text = "(Così lontana, eppure così familiare…)"
  },
  AvgDialog_145531_Content_60 = {
    Text = "Tutti scossero la testa."
  },
  AvgDialog_145531_Content_61 = {
    Text = "Mmh… ieri notte ho sentito dei rumori vicino a me, ma mi sono riaddormentato subito."
  },
  AvgDialog_145531_Content_62 = {
    Text = "Ho cercato in tutte le tende, ma non c'è da nessuna parte."
  },
  AvgDialog_145531_Content_63 = {
    Text = "Forse si è ritirata a metà strada?"
  },
  AvgDialog_145531_Content_64 = {
    Text = "Ieri, quando era vicino al lago ghiacciato, il suo Stato era già molto strano…"
  },
  AvgDialog_145531_Content_65 = {
    Text = "Evelyn mormorò con Ansia."
  },
  AvgDialog_145531_Content_66 = {
    Text = "Non ha nemmeno portato con sé la bombola di ossigeno."
  },
  AvgDialog_145531_Content_67 = {
    Text = "Siamo a seimila metri di quota: ognuno deve — e può Solo — essere responsabile della propria Vita."
  },
  AvgDialog_145531_Content_68 = {
    Text = "Almeno… almeno andiamo a dare un'occhiata al lago ghiacciato."
  },
  AvgDialog_145531_Content_69 = {
    Text = "Ci andiamo?"
  },
  AvgDialog_145531_Content_7 = {
    Text = "I compagni di squadra nelle tende vicine erano sprofondati in un sonno profondo, esausti per la scalata del giorno. Persino i cani da guida russavano."
  },
  AvgDialog_145531_Content_70 = {
    Text = "Tu vuoi andare a cercare Tintura, non vuoi rinunciare ad alcuna possibilità. Ma sai anche che ogni scelta che fai porta con sé la Vita di tutta la squadra."
  },
  AvgDialog_145531_Content_71 = {
    Text = "Andiamo, la quota qui e al lago ghiacciato è Quasi identica, il tempo di andata e ritorno è entro limiti gestibili."
  },
  AvgDialog_145531_Content_72 = {
    Text = "L'unica cosa a cui prestare attenzione sono le bestie selvatiche lungo il percorso."
  },
  AvgDialog_145531_Content_8 = {
    Text = "È ora di uscire."
  },
  AvgDialog_145531_Content_9 = {
    Text = "Lei aprì il sacco a pelo, sollevò il telo della tenda e si fece lentamente strada fuori."
  },
  AvgDialog_145532_Content_1 = {
    Text = "Si Voltò Indietro"
  },
  AvgDialog_145532_Content_10 = {
    Text = "Poi tocca a Evelyn. William chiude il gruppo, con Lo Sguardo calmo e concentrato che fa da Guardiano a tutti."
  },
  AvgDialog_145532_Content_11 = {
    Text = "Aspettate…"
  },
  AvgDialog_145532_Content_12 = {
    Text = "Lo Sguardo di Evelyn si posa su un tratto di corda sulla parete spezzata."
  },
  AvgDialog_145532_Content_13 = {
    Text = "Questo è… il loro moschettone! Riconosco questo segno!"
  },
  AvgDialog_145532_Content_14 = {
    Text = "L'angolo formato dalla cornice di Neve! L'angolo formato dalla cornice di Neve crea una zona sicura, che impedisce alla Neve di coprire questo punto!"
  },
  AvgDialog_145532_Content_15 = {
    Text = "Tu guardi dall'alto verso la direzione di Evelyn. Solo un'occhiata, e il Fantasma della caduta ti fa girare la testa."
  },
  AvgDialog_145532_Content_16 = {
    Text = "Devo andare a cercarlo!"
  },
  AvgDialog_145532_Content_17 = {
    Text = "Evelyn Allentato il moschettone e scese lentamente verso il basso."
  },
  AvgDialog_145532_Content_18 = {
    Text = "È troppo pericoloso, Evelyn!"
  },
  AvgDialog_145532_Content_19 = {
    Text = "Non importa, sono venuta proprio per questo! Se parliamo di pericolo, l'arrampicata in sé è già abbastanza pericolosa!"
  },
  AvgDialog_145532_Content_2 = {
    Text = "Quattro persone, come quattro dadi, sospese sul tavolo da gioco chiamato parete di ghiaccio."
  },
  AvgDialog_145532_Content_20 = {
    Text = "Non preoccupatevi di me! Vi raggiungo subito!"
  },
  AvgDialog_145532_Content_21 = {
    Text = "Nelle profondità della crepa nel ghiaccio, Come Se qualcosa la stesse attirando."
  },
  AvgDialog_145532_Content_22 = {
    Text = "Evelyn, non puoi——!"
  },
  AvgDialog_145532_Content_23 = {
    Text = "Allunghi la mano verso il tuo moschettone, fai un respiro profondo e ti prepari alla caduta."
  },
  AvgDialog_145532_Content_24 = {
    Text = "%player%..."
  },
  AvgDialog_145532_Content_25 = {
    Text = "William ti blocca la mano e scuote lentamente la testa."
  },
  AvgDialog_145532_Content_26 = {
    Text = "Nessuno sa se Helot tornerà indietro, non possiamo restare tutti sospesi a mezz'aria."
  },
  AvgDialog_145532_Content_27 = {
    Text = "Guarda Sopra."
  },
  AvgDialog_145532_Content_28 = {
    Text = "Caraboo ha già scavalcato per primo l'ultima parete di ghiaccio."
  },
  AvgDialog_145532_Content_29 = {
    Text = "Verso l'alto c'è la fine di questo viaggio, la terra promessa dove ogni desiderio si avvera."
  },
  AvgDialog_145532_Content_3 = {
    Text = "Ognuno stringeva saldamente la corda di sicurezza tra le mani, cercando disperatamente il prossimo appiglio."
  },
  AvgDialog_145532_Content_30 = {
    Text = "Verso il basso c'è un abisso di Oscurità senza fondo."
  },
  AvgDialog_145532_Content_31 = {
    Text = "Ma non possiamo perdere un altro compagno——!"
  },
  AvgDialog_145532_Content_32 = {Text = "Lo so."},
  AvgDialog_145532_Content_33 = {
    Text = "Quindi, lascia fare a me."
  },
  AvgDialog_145532_Content_34 = {
    Text = "Prima ancora che le parole si registrassero, William sgancia l'imbracatura e si lancia direttamente nell'abisso."
  },
  AvgDialog_145532_Content_35 = {
    Text = "La parete di ghiaccio verticale che aveva richiesto ogni briciola delle tue forze per essere scalata viene conquistata in pochi secondi nella discesa. In un batter d'occhio, William ed Evelyn si sono ridotti a due minuscoli puntini lontani, inghiottiti dalle strette fauci della crepaccia."
  },
  AvgDialog_145532_Content_36 = {
    Text = "Osservi così Evelyn e William scendere sempre più in basso, dirigendosi verso la crepa nel ghiaccio."
  },
  AvgDialog_145532_Content_37 = {
    Text = "Poi alzi la testa e pianti il chiodo successivo nella roccia."
  },
  AvgDialog_145532_Content_38 = {Text = "..."},
  AvgDialog_145532_Content_39 = {Text = "..."},
  AvgDialog_145532_Content_4 = {
    Text = "Sopra c'è una roccia, dobbiamo scavalcarla."
  },
  AvgDialog_145532_Content_40 = {
    Text = "La crepa nel ghiaccio è insondabile; quando rimetti piede su terreno pianeggiante, è già buio pesto, impossibile vedere la propria mano davanti al viso."
  },
  AvgDialog_145532_Content_41 = {
    Text = "Aspetta, Evelyn…"
  },
  AvgDialog_145532_Content_42 = {
    Text = "La luce della frontale Danza proiettandosi in avanti."
  },
  AvgDialog_145532_Content_43 = {
    Text = "In fondo alla crepa sembra esserci una grotta di stalattiti, con un'atmosfera diversa dal resto. Fredda, umida, e nel Vento si mescola uno strano odore indefinibile."
  },
  AvgDialog_145532_Content_44 = {
    Text = "Attento ai piedi, qui c'è un avvallamento…"
  },
  AvgDialog_145532_Content_45 = {
    Text = "Le sue parole gli si bloccano in gola, trasformandosi in un brusco respiro di freddo."
  },
  AvgDialog_145532_Content_46 = {
    Text = "Dove la luce scorreva, c'erano decine di scheletri ormai saponificati."
  },
  AvgDialog_145532_Content_47 = {
    Text = "Mantenevano la posizione in cui erano caduti — alcuni rannicchiati, altri abbracciati — coperti in silenzio, strato su strato, sul pavimento."
  },
  AvgDialog_145532_Content_48 = {
    Text = "Questa è… la divisa della spedizione Green."
  },
  AvgDialog_145532_Content_49 = {
    Text = "Sono tutti qui."
  },
  AvgDialog_145532_Content_5 = {
    Text = "Vi muovete con estrema cautela attorno al masso, verificando se sotto i piedi ci sia roccia solida o Neve soffice accumulata."
  },
  AvgDialog_145532_Content_50 = {
    Text = "Dopo un lungo silenzio, Evelyn si girò e fissò con attenzione gli occhi di William."
  },
  AvgDialog_145532_Content_51 = {
    Text = "Sembra che qui non ci siano molte informazioni di cui abbiate bisogno, giusto?"
  },
  AvgDialog_145532_Content_52 = {
    Text = "Se è così, potreste lasciarmi stare qui da sola per un po'? Voglio cercare se lui è qui."
  },
  AvgDialog_145532_Content_53 = {
    Text = "Se possibile, vorrei anche parlargli."
  },
  AvgDialog_145532_Content_54 = {
    Text = "Questi cadaveri potrebbero portare batteri pericolosi…"
  },
  AvgDialog_145532_Content_55 = {
    Text = "Evelyn espresse la propria fermezza con lo sguardo."
  },
  AvgDialog_145532_Content_56 = {Text = "Capito."},
  AvgDialog_145532_Content_57 = {
    Text = "Però, promettimi che uscirai da qui sana e salva."
  },
  AvgDialog_145532_Content_58 = {
    Text = "Sì, va bene, te lo prometto. Raggiungerò sicuramente la vetta."
  },
  AvgDialog_145532_Content_59 = {
    Text = "William annuì."
  },
  AvgDialog_145532_Content_6 = {
    Text = "Dopo averlo finalmente aggirato, prima ancora di riprendere fiato, ai vostri piedi appare una crepa dal fondo insondabile."
  },
  AvgDialog_145532_Content_60 = {
    Text = "Ti aspetto all'ingresso della grotta."
  },
  AvgDialog_145532_Content_61 = {Text = "..."},
  AvgDialog_145532_Content_62 = {Text = "..."},
  AvgDialog_145532_Content_63 = {
    Text = "Passò molto, molto tempo — tanto che William quasi non riuscì a resistere all'impulso di entrare a vedere — quando finalmente dalla grotta giunse il fruscio sommesso di abiti che si muovevano."
  },
  AvgDialog_145532_Content_64 = {
    Text = "Poi Evelyn apparve."
  },
  AvgDialog_145532_Content_65 = {
    Text = "Tu… l'hai trovato?"
  },
  AvgDialog_145532_Content_66 = {
    Text = "Sì, l'ho trovato."
  },
  AvgDialog_145532_Content_67 = {
    Text = "Evelyn annuì, con un tono di voce calmo, senza la minima inflessione."
  },
  AvgDialog_145532_Content_68 = {
    Text = "Le mie condoglianze."
  },
  AvgDialog_145532_Content_69 = {
    Text = "Non è necessario."
  },
  AvgDialog_145532_Content_7 = {
    Text = "Fate attenzione, non guardate giù."
  },
  AvgDialog_145532_Content_70 = {
    Text = "Evelyn rise leggermente."
  },
  AvgDialog_145532_Content_71 = {
    Text = "Sapevo già che sarebbe andata così."
  },
  AvgDialog_145532_Content_72 = {
    Text = "Anche tu, vero?"
  },
  AvgDialog_145532_Content_73 = {
    Text = "Anche tu stai cercando qualcuno che non tornerà mai più."
  },
  AvgDialog_145532_Content_74 = {
    Text = "È sempre così."
  },
  AvgDialog_145532_Content_75 = {
    Text = "All'inizio, si nutre sempre la speranza, pensando che forse domani tornerà."
  },
  AvgDialog_145532_Content_76 = {
    Text = "Poi un domani…"
  },
  AvgDialog_145532_Content_77 = {
    Text = "…e poi un altro ancora."
  },
  AvgDialog_145532_Content_78 = {
    Text = "La speranza si assottiglia sempre di più, e la Pietra nel fondo del cuore pesa sempre di più."
  },
  AvgDialog_145532_Content_79 = {
    Text = "Giorno dopo giorno, continua La Discesa, scende, scende."
  },
  AvgDialog_145532_Content_8 = {
    Text = "Tu segui da vicino Naraka, tenendo la corda e sforzandoti di attraversare la crepa."
  },
  AvgDialog_145532_Content_80 = {
    Text = "Finché un giorno, Scopri di non pensarci più."
  },
  AvgDialog_145532_Content_81 = {
    Text = "Mangi, dormi, lavori, viaggi, parli con gli altri, ridi e scherzi come al solito…"
  },
  AvgDialog_145532_Content_82 = {
    Text = "E poi, per molto, molto tempo, non se ne parla più."
  },
  AvgDialog_145532_Content_83 = {
    Text = "La voce di Evelyn cambiò leggermente tono."
  },
  AvgDialog_145532_Content_84 = {
    Text = "Ma sai che non hai dimenticato, non hai mai dimenticato."
  },
  AvgDialog_145532_Content_85 = {
    Text = "Non dimenticherai mai."
  },
  AvgDialog_145532_Content_86 = {
    Text = "Basta una leggenda, una scintilla, e inizierà a bruciare…"
  },
  AvgDialog_145532_Content_87 = {
    Text = "Ti inghiottirà completamente..."
  },
  AvgDialog_145532_Content_88 = {
    Text = "...e ti ridurrà in cenere."
  },
  AvgDialog_145532_Content_89 = {
    Text = "William alzò bruscamente la testa, fissando Lo Sguardo di Evelyn."
  },
  AvgDialog_145532_Content_9 = {
    Text = "Con la coda dell'occhio, scorgi all'interno della crepa un buio assoluto che mette i brividi, senza che si riesca a vedere dove finisce."
  },
  AvgDialog_145532_Content_90 = {
    Text = "L'altra ricambiò lo sguardo con dolcezza, ma ciò che riempiva quegli Occhi — fiamme o vuoto — lui non riusciva a distinguerlo, offuscato dal riflesso degli occhiali protettivi."
  },
  AvgDialog_145532_Content_91 = {
    Text = "Smettila di sognare ad occhi aperti, andiamo. Ti ho promesso che avrei raggiunto la vetta con voi, no?"
  },
  AvgDialog_145532_Content_92 = {
    Text = "Per qualche ragione, William aveva sempre la sensazione che, nonostante i loro sguardi si incontrassero, l'interlocutrice stesse parlando con qualcun altro, non con lui."
  },
  AvgDialog_145532_Content_93 = {
    Text = "Evelyn non lo aspettava più. Si girò e si avviò verso l'uscita della grotta, chinandosi a controllare la corda di trazione con movimenti così decisi Come Se quel Soliloquio di poco prima non fosse mai avvenuto."
  },
  AvgDialog_145532_Content_94 = {
    Text = "William rimane immobile sul posto, con le parole che non riesce a pronunciare conficcate in gola. La osserva rimpicciolirsi in lontananza, poi volge lo sguardo verso la bocca buia e spalancata della grotta dietro di lui."
  },
  AvgDialog_145532_Content_95 = {
    Text = "Non trovava alcun motivo per restare un secondo in più. Distolse Lo Sguardo e la seguì in Silenzio."
  },
  AvgDialog_145534_Content_1 = {
    Text = "La farsa è finita. Ora, la montagna di neve vi inghiottirà."
  },
  AvgDialog_145534_Content_10 = {
    Text = "La cima si Squarciò improvvisamente al centro, aprendosi sempre di più, trasformandosi in una voragine verticale che squarciava il cielo e la Terra; una bava rossastra colava tra zanna dopo zanna, riversandosi come pioggia."
  },
  AvgDialog_145534_Content_11 = {
    Text = "La voragine si richiuse di colpo —"
  },
  AvgDialog_145534_Content_12 = {
    Text = "Prima ancora che la folla potesse lanciare il primo grido, era già stata inghiottita nel ventre insondabile della creatura."
  },
  AvgDialog_145534_Content_13 = {
    Text = "La Terra smise di tremare, e tra la Neve che cadeva soffice, spuntò un piccolo cappello a punta."
  },
  AvgDialog_145534_Content_14 = {
    Text = "Caraboo scosse via la Neve che la ricopriva e passò in rassegna con soddisfazione i frutti della sua impresa —"
  },
  AvgDialog_145534_Content_15 = {
    Text = "Perché? Perché sei ancora qui?"
  },
  AvgDialog_145534_Content_16 = {
    Text = "Una sagoma solitaria, che non avrebbe dovuto esistere, di un'altra persona."
  },
  AvgDialog_145534_Content_17 = {
    Text = "Anch'io vorrei sapere perché sono ancora qui."
  },
  AvgDialog_145534_Content_18 = {
    Text = "Hai appena detto che i visitatori offrono i loro desideri alla montagna, e la montagna risponde alle preghiere di chi la supplica."
  },
  AvgDialog_145534_Content_19 = {
    Text = "Forse perché, rispetto a voi, non ho grandi desideri. Sono troppo ordinaria, troppo comune, non abbastanza appetitosa?"
  },
  AvgDialog_145534_Content_2 = {
    Text = "Caraboo si girò, rivolgendosi alle montagne che si estendevano all'orizzonte, alla tormenta di Vento e Neve."
  },
  AvgDialog_145534_Content_20 = {
    Text = "No, non è possibile. Non hai nessun desiderio da affidare alla montagna?"
  },
  AvgDialog_145534_Content_21 = {
    Text = "Caraboo spalancò gli occhi, nella sua domanda si celava un filo di incredulità e irritazione."
  },
  AvgDialog_145534_Content_22 = {
    Text = "No. L'unico desiderio che avevo per questo viaggio si è già realizzato."
  },
  AvgDialog_145534_Content_23 = {
    Text = "Ai piedi dell'ultima parete rocciosa, ho trovato i suoi resti. Che fortuna: era incastrato in una fessura della roccia, non sepolto dalla neve."
  },
  AvgDialog_145534_Content_24 = {
    Text = "La carne è in Decomposizione, ma la Targhetta è ancora lì. Riesco ancora a riconoscerlo, a confermare la sua esistenza."
  },
  AvgDialog_145534_Content_25 = {
    Text = "Com'è possibile, com'è possibile essere soddisfatti così facilmente!"
  },
  AvgDialog_145534_Content_26 = {
    Text = "È semplicemente così. I desideri dei mortali non dovrebbero richiedere il potere divino per essere realizzati."
  },
  AvgDialog_145534_Content_27 = {
    Text = "E ci sono anche altre buone notizie. A giudicare dall'equipaggiamento che portava, erano in discesa quando li ha colti la sventura."
  },
  AvgDialog_145534_Content_28 = {
    Text = "Quindi, in vita aveva già realizzato il suo desiderio di raggiungere la vetta più alta."
  },
  AvgDialog_145534_Content_29 = {
    Text = "Sebbene a distanza di tempo, proprio qui, entrambi moriremo in pace."
  },
  AvgDialog_145534_Content_3 = {
    Text = "O vera fata della montagna di Neve, o grande Dio Verme, vi ho portato le Offerte!"
  },
  AvgDialog_145534_Content_30 = {
    Text = "<Shake:No, ti stai ingannando… non è vero, devi volere di più…>"
  },
  AvgDialog_145534_Content_31 = {
    Text = "Il tono di Caraboo si fece sempre più acuto, le lacrime sgorgarono dagli angoli degli occhi."
  },
  AvgDialog_145534_Content_32 = {
    Text = "Evelyn la guardava con Lo Sguardo pieno di compassione."
  },
  AvgDialog_145534_Content_33 = {
    Text = "La Neve continuava a cadere."
  },
  AvgDialog_145534_Content_34 = {
    Text = "Dopo un lungo silenzio, Evelyn si avvicinò e scrollò via la neve caduta sulle spalle di Caraboo."
  },
  AvgDialog_145534_Content_35 = {
    Text = "Pensaci ancora bene. Io vado a stare con mio marito."
  },
  AvgDialog_145534_Content_36 = {
    Text = "Dette queste parole, lei canticchiò sottovoce qualcosa e si incamminò passo dopo passo verso il fondo della scogliera."
  },
  AvgDialog_145534_Content_37 = {
    Text = "Senza corda di sicurezza fissa, non temeva la caduta. La fessura di ghiaccio in fondo alla roccia era la sua destinazione."
  },
  AvgDialog_145534_Content_38 = {
    Text = "<Shake:Non andare, Evelyn, non andare—>"
  },
  AvgDialog_145534_Content_39 = {
    Text = "A rifiutarla non era Evelyn."
  },
  AvgDialog_145534_Content_4 = {
    Text = "Lei era in preda all'euforia, Lei rideva fragorosamente. Provava piacere nel vedere il suo inganno riuscire."
  },
  AvgDialog_145534_Content_40 = {
    Text = "A trattenerla non era nemmeno qualcun altro al di fuori di Evelyn."
  },
  AvgDialog_145534_Content_41 = {Text = "Perché..."},
  AvgDialog_145534_Content_42 = {
    Text = "Perché… la montagna trema?…"
  },
  AvgDialog_145534_Content_43 = {Text = "..."},
  AvgDialog_145534_Content_44 = {
    Text = "Tra i monti dimora la creatura più terrificante."
  },
  AvgDialog_145534_Content_45 = {
    Text = "Si estende per mille miglia, avvolgendosi sulla terra che rivendica. Si nutre dei cuori degli uomini e divora le loro illusioni."
  },
  AvgDialog_145534_Content_46 = {
    Text = "Ora veniva a catturare la sua preda."
  },
  AvgDialog_145534_Content_47 = {
    Text = "<Change>Desideri… desideri… desideri ardenti…"
  },
  AvgDialog_145534_Content_48 = {
    Text = "No! Li ho ingannati tutti per te, avevi promesso che non avresti mangiato me!"
  },
  AvgDialog_145534_Content_49 = {
    Text = "<Change>Chi rispetterebbe… il patto… di un bugiardo…"
  },
  AvgDialog_145534_Content_5 = {
    Text = "O gente avida, o gente stolta."
  },
  AvgDialog_145534_Content_50 = {
    Text = "Il verme sulla Mela alzò anch'esso la voce, scoppiando in una risata acuta."
  },
  AvgDialog_145534_Content_51 = {
    Text = "Dopotutto, non è forse vero che fin dall'inizio sapevi che uno dei Sacrifici era la Mela d'Oro?"
  },
  AvgDialog_145534_Content_52 = {
    Text = "No, io sono la dea della montagna di neve, la Mela d'Oro è il mio strumento sacro, non posso essere un sacrificio!"
  },
  AvgDialog_145534_Content_53 = {
    Text = "Hai dimenticato chi sei? Lascia che te lo ricordi, Caraboo, tu non sei nessuno."
  },
  AvgDialog_145534_Content_54 = {
    Text = [[
Non sei una dea, non sei una principessa, non sei una fata.
Sei solo un relitto nato sul campo di battaglia, una profuga che ha persino dimenticato il volto dei propri genitori.]]
  },
  AvgDialog_145534_Content_55 = {
    Text = "Avresti dovuto saperlo da tempo… quelle Identità che ti sei inventata, quegli onori ottenuti con l'inganno… un giorno ti sarebbero tornati indietro, duramente, moltiplicati."
  },
  AvgDialog_145534_Content_56 = {
    Text = "Oggi, è arrivato quel momento."
  },
  AvgDialog_145534_Content_57 = {
    Text = "La montagna spalancò le sue fauci di Sangue."
  },
  AvgDialog_145534_Content_58 = {
    Text = "<Change>Entra… nel mio ventre… e diventa… il mio Potere…"
  },
  AvgDialog_145534_Content_59 = {Text = "..."},
  AvgDialog_145534_Content_6 = {
    Text = "Affidate i vostri desideri alla montagna, affidate le vostre brame alla montagna."
  },
  AvgDialog_145534_Content_60 = {
    Text = "Il pendio dolce divenne improvvisamente ripido, ed Evelyn, a pochi decine di metri dalla crepaccia, abbandonò ogni peso superfluo."
  },
  AvgDialog_145534_Content_61 = {
    Text = "Strappò i ganci della bombola d'ossigeno, si liberò dei pesanti ramponi, poi senza esitare tagliò l'unica corda di sicurezza che la legava."
  },
  AvgDialog_145534_Content_62 = {
    Text = "Niente poteva più trattenerla."
  },
  AvgDialog_145534_Content_63 = {
    Text = "Lei si mosse leggera, quasi gioiosa, gettandosi verso l'amato che dormiva nella crepaccia."
  },
  AvgDialog_145534_Content_64 = {
    Text = "Amore mio, sono venuta a prenderti."
  },
  AvgDialog_145534_Content_65 = {
    Text = "In mezzo a una nuova ondata di tremori, Evelyn abbracciò teneramente le ossa del suo amato."
  },
  AvgDialog_145534_Content_66 = {
    Text = "Nella Visione della caduta, la montagna innevata spalancava la sua immensa bocca, inghiottendo quella piccola figura simile a una torta di panna e ciliegie."
  },
  AvgDialog_145534_Content_67 = {
    Text = "Ingoiata nel ventre dei monti."
  },
  AvgDialog_145534_Content_7 = {
    Text = "<BigShake:La montagna vi ascolterà, e poi vi \"risponderà\"!>"
  },
  AvgDialog_145534_Content_8 = {
    Text = "In un istante, il corpo della montagna si scosse violentemente dalle fondamenta — la Neve candida si staccò a fiocchi, il corpo segmentato si contorse e si avvolse su se stesso, sollevandosi pezzo per pezzo come un ghiacciaio che crolla."
  },
  AvgDialog_145534_Content_9 = {
    Text = "L'intera \"montagna\" si ergeva fragorosamente, chinandosi su di loro, e ogni centimetro del suo strisciare riduceva in polvere il Campo di neve sotto di essa."
  },
  AvgDialog_145535_Content_1 = {
    Text = "Ospiti al Banchetto"
  },
  AvgDialog_145535_Content_10 = {
    Text = "Ingannare? E allora? Chi non inganna?"
  },
  AvgDialog_145535_Content_11 = {
    Text = "Lo sai, vero, %player%? So che puoi fiutare le bugie proprio come me."
  },
  AvgDialog_145535_Content_12 = {
    Text = "<Yellow:Per fortuna mi sono nascosta con successo e sono riuscita a sfuggire ai loro inseguitori.>"
  },
  AvgDialog_145535_Content_13 = {
    Text = "<Yellow:<Big:No...! Non sono stanca! NON ME NE VADO!>>"
  },
  AvgDialog_145535_Content_14 = {
    Text = "<Yellow:I miei altri doveri in questo mondo sono giunti a una conclusione temporanea.>"
  },
  AvgDialog_145535_Content_15 = {
    Text = "Tintura non sarebbe sopravvissuta a quella notte, eppure ha scelto di nascondere la sua Malattia. Non è forse anche lei una bugiarda?"
  },
  AvgDialog_145535_Content_16 = {
    Text = "Castor, dal momento in cui ci ha incontrati, ha nascosto il fatto di portare le Piume. Non è forse anche lui un bugiardo?"
  },
  AvgDialog_145535_Content_17 = {
    Text = "William voleva chiaramente qualcos'altro. Qualcosa di personale. Ma non voleva dircelo. Anche lui è un bugiardo, no?"
  },
  AvgDialog_145535_Content_18 = {
    Text = "Tutti ingannano, tutti sono bugiardi. Perché il Rimprovero silenzioso ricade solo su di me?"
  },
  AvgDialog_145535_Content_19 = {
    Text = "Ma Tintura voleva solo andare un po' più avanti. Quanto alle ali di Castor e al desiderio segreto di William... quella è la loro sfera privata."
  },
  AvgDialog_145535_Content_2 = {
    Text = "Chi sei davvero?"
  },
  AvgDialog_145535_Content_20 = {
    Text = "Non hanno detto la verità, ma non avevano nemmeno intenzione di fare del Danno a nessuno."
  },
  AvgDialog_145535_Content_21 = {
    Text = "Come fai a non capirlo ancora — le persone in questo mondo, le cose che desiderano, che sia il Potere o un desiderio del cuore, sono come questa Mela—"
  },
  AvgDialog_145535_Content_22 = {
    Text = "Tutti la vogliono, tutti la inseguono disperatamente…"
  },
  AvgDialog_145535_Content_23 = {
    Text = "Caraboo lanciò la Mela lontano con nonchalance, fece finta di inseguirla, poi si lasciò cadere teatralmente nella neve."
  },
  AvgDialog_145535_Content_24 = {Text = "Ma..."},
  AvgDialog_145535_Content_25 = {
    Text = "Per sempre, per sempre, solo un numero limitato di persone potrà ottenerla."
  },
  AvgDialog_145535_Content_26 = {
    Text = "E io, voglio esserne l'eterno, unico padrone."
  },
  AvgDialog_145535_Content_27 = {
    Text = "Ma il mezzo con cui persegui questo scopo è Una Bugia."
  },
  AvgDialog_145535_Content_28 = {
    Text = "Già, non basta forse Una Bugia?"
  },
  AvgDialog_145535_Content_29 = {
    Text = "Ciò che vi ha attirato fin qui non è qualcosa di grande o maestoso come il Destino o il Re degli Dei, è Appena Una Bugia, nient'altro che Una Bugia!"
  },
  AvgDialog_145535_Content_3 = {
    Text = "Caraboo rise piano."
  },
  AvgDialog_145535_Content_30 = {
    Text = "Voi portate Offerte alla montagna, e la montagna esaudisce i vostri desideri secondo il suo umore. Non è poi così diverso dalle Divinità del mondo dei mortali."
  },
  AvgDialog_145535_Content_31 = {
    Text = "Solo che questa volta, ciò che la montagna esige da voi è... il vostro <RedItalic:tutto.>"
  },
  AvgDialog_145535_Content_32 = {
    Text = "Non ci riuscirai…!"
  },
  AvgDialog_145535_Content_4 = {
    Text = "Chi sono davvero?"
  },
  AvgDialog_145535_Content_5 = {
    Text = "Non ve l'ho forse detto fin dall'Inizio? Sono la dea della Neve, la fata madrina, l'incarnazione della volontà della montagna innevata."
  },
  AvgDialog_145535_Content_6 = {
    Text = "Sono io, la Guida più importante e più adorabile, Caraboo, che ora vi darà in pasto a Lei."
  },
  AvgDialog_145535_Content_7 = {
    Text = "Caraboo… ci hai ingannati."
  },
  AvgDialog_145535_Content_8 = {
    Text = "Hai ingannato Evelyn, che si era presa cura di te lungo tutto il cammino, hai ingannato %player%, che aveva combattuto per darti la possibilità di restare."
  },
  AvgDialog_145535_Content_9 = {
    Text = "È questo il risultato che cercavi?"
  },
  AvgDialog_145862_Content_1 = {Text = "Caraboo…"},
  AvgDialog_145862_Content_2 = {
    Text = "Quello che hai detto prima… era vero?"
  },
  AvgDialog_145862_Content_3 = {
    Text = "Tu che ne pensi?"
  },
  AvgDialog_145862_Content_4 = {
    Text = "Non lo so..."
  },
  AvgDialog_145862_Content_5 = {
    Text = "Allora non pensarci. Stai attento, arrivano dei nemici da quella parte!"
  },
  AvgDialog_146405_Content_1 = {
    Text = "Fatemi passare, devo andare a cercarlo!"
  },
  AvgDialog_146405_Content_2 = {
    Text = "Pollux mi sta chiamando!"
  },
  AvgDialog_146516_Content_1 = {
    Text = "Maledizione, queste Pustole non possono essere congelate?"
  },
  AvgDialog_146516_Content_10 = {
    Text = "Fino a quel momento, nessuno aveva prestato attenzione ai tesori di cui parlava Caraboo."
  },
  AvgDialog_146516_Content_11 = {
    Text = "Dopotutto, nessuna leggenda menzionava un simile elemento."
  },
  AvgDialog_146516_Content_12 = {
    Text = "Dicevano solo che, una volta raggiunta la vetta, il desiderio si sarebbe avverato."
  },
  AvgDialog_146516_Content_13 = {Text = "Fatto."},
  AvgDialog_146516_Content_14 = {
    Text = "Così, quando la catena sferragliante di Helot sfiorò tutti voi agganciando i rispettivi zaini, nessuno se lo aspettava."
  },
  AvgDialog_146516_Content_15 = {
    Text = "Solo innumerevoli monete di cioccolato dorate schizzarono fuori dalle sacche strappate, disperdendosi lungo la parete rocciosa."
  },
  AvgDialog_146516_Content_16 = {
    Text = "Come una pioggia d'oro splendente."
  },
  AvgDialog_146516_Content_17 = {
    Text = "<Shake:Tintura… Castor…>"
  },
  AvgDialog_146516_Content_18 = {
    Text = [[
Non sai cosa hai perso.
Ma di certo avete perso qualcosa, qualcosa di molto importante.]]
  },
  AvgDialog_146516_Content_19 = {
    Text = "Non mollate! Lei si sta dirigendo verso l'altare in cima alla montagna!"
  },
  AvgDialog_146516_Content_2 = {
    Text = "Hmph, sono creature cresciute nella neve fin da piccole."
  },
  AvgDialog_146516_Content_20 = {
    Text = "Prima che il rituale finisca, c'è ancora una possibilità!"
  },
  AvgDialog_146516_Content_21 = {
    Text = "Caraboo fu la prima a riprendersi e a ricominciare a scalare, non mancando di abbassare la testa per richiamarvi."
  },
  AvgDialog_146516_Content_22 = {
    Text = "Non sai perché, ma nei suoi occhi intravedi una gioia di origine misteriosa."
  },
  AvgDialog_146516_Content_23 = {
    Text = "Ascoltate Caraboo."
  },
  AvgDialog_146516_Content_24 = {
    Text = "E con Helot-catena… ci si rivede in cima."
  },
  AvgDialog_146516_Content_25 = {
    Text = "In lontananza, il profilo della vetta innevata appare e scompare tra le nuvole."
  },
  AvgDialog_146516_Content_26 = {
    Text = "-Altitudine 7950 metri-"
  },
  AvgDialog_146516_Content_3 = {
    Text = "Le sfere a catena volteggiavano in aria, e tu e William proteggavate Evelyn e Naraka, arrangiandovi a stento."
  },
  AvgDialog_146516_Content_4 = {
    Text = "Caraboo si nascondeva dietro qualche cumulo di neve, la sua figura celata dalla candida coltre bianca."
  },
  AvgDialog_146516_Content_5 = {
    Text = "Non vi sembra strano? Ci stava seguendo fin dall'inizio della salita."
  },
  AvgDialog_146516_Content_6 = {
    Text = "Perché ha lanciato un attacco proprio adesso?"
  },
  AvgDialog_146516_Content_7 = {
    Text = "<Shake:Se il suo obiettivo non è ucciderci, ma——>"
  },
  AvgDialog_146516_Content_8 = {
    Text = "È troppo tardi. Le catene vorticanti hanno separato tutti, impedendovi di badare ai pesanti bagagli."
  },
  AvgDialog_146516_Content_9 = {
    Text = "<Big:——I tesori che abbiamo con noi!>"
  },
  AvgDialog_147080_Content_1 = {Text = "..."},
  AvgDialog_147080_Content_10 = {
    Text = "Va bene, va bene, lo so. Ma non posso dirtelo."
  },
  AvgDialog_147080_Content_100 = {
    Text = "Teseo uscì dal labirinto grazie al filo di Arianna, ma il loro amore non fu benedetto dalla Dea del Destino…"
  },
  AvgDialog_147080_Content_101 = {
    Text = "Alla fine, il dio del vino Dioniso donò ad Arianna una splendida Corona ornata di sette gemme scintillanti."
  },
  AvgDialog_147080_Content_102 = {
    Text = "William lanciò un'occhiata a Caraboo."
  },
  AvgDialog_147080_Content_103 = {
    Text = "Nonostante avessero viaggiato insieme e superato ogni ostacolo fianco a fianco, Teseo e Arianna erano forse destinati a percorrere strade diverse."
  },
  AvgDialog_147080_Content_104 = {
    Text = "Caraboo evitò lo sguardo di William."
  },
  AvgDialog_147080_Content_105 = {
    Text = "Un Guscio vuoto che ha già compiuto la sua missione, in cambio di un desiderio capace di riscrivere il Destino — non ti sembra uno scambio svantaggioso?"
  },
  AvgDialog_147080_Content_106 = {
    Text = "Lo scopo della nostra scalata era proprio trovare il proprietario della Corona attraverso questa Corona."
  },
  AvgDialog_147080_Content_107 = {
    Text = "Tu puoi leggere direttamente la coscienza di Caraboo, e Lei è in grado di capire se stiamo dicendo Una Bugia."
  },
  AvgDialog_147080_Content_108 = {
    Text = "Quindi, puoi essere certo che quello che sto dicendo ora è la verità, giusto?"
  },
  AvgDialog_147080_Content_109 = {
    Text = "<Yellow:La mia carta vincente è mostrare le carte>."
  },
  AvgDialog_147080_Content_11 = {
    Text = "Tu rispondi con uno sguardo furioso."
  },
  AvgDialog_147080_Content_110 = {Text = "..."},
  AvgDialog_147080_Content_111 = {
    Text = "<Shake:Ah ah, ah ah ah ah!> Esatto, si può persino sfruttare questo meccanismo al contrario. Fare affari con una persona intelligente è davvero semplice."
  },
  AvgDialog_147080_Content_112 = {
    Text = "<Big:Preparatevi a riconquistare la libertà!>"
  },
  AvgDialog_147080_Content_113 = {
    Text = "<Shake:Conto alla rovescia: tre, due, uno—>"
  },
  AvgDialog_147080_Content_114 = {Text = "—Zero."},
  AvgDialog_147080_Content_115 = {
    Text = "Le pareti di Caro da ogni direzione vi si stringono addosso contemporaneamente, e il liquido viscoso che trasuda dalle pieghe si trasforma in innumerevoli tentacoli sottili e allungati, avvolgendovi i polsi, le caviglie e la vita."
  },
  AvgDialog_147080_Content_116 = {
    Text = "Aspetta, non è che questa libertà riconquistata sia un po' diversa da quello che ci eravamo detti—"
  },
  AvgDialog_147080_Content_117 = {
    Text = "Ho promesso solo di portarvi fuori. Non ho mai promesso che il viaggio sarebbe stato comodo."
  },
  AvgDialog_147080_Content_118 = {
    Text = "Una forza irresistibile sale dal basso."
  },
  AvgDialog_147080_Content_119 = {
    Text = "Come corpi estranei inghiottiti e poi rigurgitati, venite spinti all'indietro lungo l'esofago, salendo rapidamente attraverso un corridoio di Caro stretto e viscido."
  },
  AvgDialog_147080_Content_12 = {
    Text = "Non arrabbiarti, non arrabbiarti, comincio a spiegare subito."
  },
  AvgDialog_147080_Content_120 = {
    Text = "La Visione viene inghiottita dall'Oscurità. Alle orecchie non rimane che il suono appiccicoso della Caro che sfrega, e il battito cardiaco sordo e prolungato dell'intera montagna."
  },
  AvgDialog_147080_Content_121 = {Text = "Thud."},
  AvgDialog_147080_Content_122 = {Text = "Thud."},
  AvgDialog_147080_Content_123 = {
    Text = "<Red:Bum—>"
  },
  AvgDialog_147080_Content_124 = {
    Text = "Quando cade l'ultimo battito del cuore, davanti a voi si apre una fessura di luce bianca accecante."
  },
  AvgDialog_147080_Content_125 = {
    Text = "Il Vento furioso, avvolgendo la Neve e il ghiaccio, vi assale con Assalto Imminente."
  },
  AvgDialog_147080_Content_126 = {
    Text = "Quella forza vi scaglia violentemente fuori, facendovi cadere pesantemente nella neve accumulata fino alle ginocchia."
  },
  AvgDialog_147080_Content_127 = {
    Text = "Tosse… questa creatura si sta sicuramente vendicando."
  },
  AvgDialog_147080_Content_128 = {
    Text = "Almeno non vi ha addebitato le spese di pulizia al momento del check-out. Per i Suoi standard di ospitalità, si può già considerare generoso."
  },
  AvgDialog_147080_Content_129 = {
    Text = "Ti sollevi dalla neve. Quell'odore di Sangue persistente nelle viscere viene finalmente disperso dal vento gelido e pungente."
  },
  AvgDialog_147080_Content_13 = {
    Text = "Per discutere di come uscire da qui, prima di tutto dobbiamo sapere dove siamo e perché ci troviamo qui."
  },
  AvgDialog_147080_Content_130 = {
    Text = "Questo posto non è più il crinale da cui eravate arrivati."
  },
  AvgDialog_147080_Content_131 = {
    Text = "A perdita d'Occhio, tutte le vette più basse sono sommerse sotto un mare di nuvole. Il cielo nero è così vicino da sembrare quasi a portata di mano, mentre le Stelle brillano e si spengono alternativamente oltre il velo di Neve sollevato dal Vento impetuoso."
  },
  AvgDialog_147080_Content_132 = {
    Text = "State in piedi sulla vetta più alta dell'intera catena montuosa."
  },
  AvgDialog_147080_Content_133 = {
    Text = "Questo luogo..."
  },
  AvgDialog_147080_Content_134 = {
    Text = "La vera cima della montagna."
  },
  AvgDialog_147080_Content_135 = {
    Text = "Una voce giunge da sotto la neve accumulata."
  },
  AvgDialog_147080_Content_136 = {
    Text = "Lo strato di ghiaccio trema leggermente, Come Se questa vetta innevata non fosse altro che un frammento di scheletro esposto di qualche creatura colossale."
  },
  AvgDialog_147080_Content_137 = {
    Text = "Il sito del rituale si trova poco più avanti. Ricollocate i sette artefatti nei loro posti designati, e la formazione vi indicherà da sola cosa fare dopo."
  },
  AvgDialog_147080_Content_138 = {
    Text = "Non vieni con noi?"
  },
  AvgDialog_147080_Content_139 = {
    Text = "Sono ovunque."
  },
  AvgDialog_147080_Content_14 = {
    Text = "Siamo nel ventre del Verme della Montagna, e il motivo per cui il Verme della Montagna ha usato il rituale del desiderio per attirarvi tutti qui..."
  },
  AvgDialog_147080_Content_140 = {
    Text = "Dalle profondità sotto i piedi giunge una risata bassa e cupa."
  },
  AvgDialog_147080_Content_141 = {
    Text = "L'intera montagna è il mio involucro. Ogni passo che fate lo compite sulla mia Caro."
  },
  AvgDialog_147080_Content_142 = {
    Text = "Quindi, non nutrite Illusioni di giocarmi qualche ridicolo scherzo."
  },
  AvgDialog_147080_Content_143 = {
    Text = "Andate avanti. Lasciatemi vedere quale Portale aprirete per me, voi che portate il peso di così tanti desideri."
  },
  AvgDialog_147080_Content_144 = {
    Text = "La Neve si apre lentamente davanti a voi."
  },
  AvgDialog_147080_Content_145 = {
    Text = "Un'antica scalinata di pietra, sepolta dalla tormenta per chissà quanti anni, si rivela, serpeggiando fino alla sommità."
  },
  AvgDialog_147080_Content_146 = {
    Text = "E in fondo alla scalinata, sette fiochi bagliori dorati si accendono uno dopo l'altro, Come Se fossero Occhi che dormivano da millenni e avessero finalmente atteso l'arrivo di chi li avrebbe risvegliati."
  },
  AvgDialog_147080_Content_147 = {
    Text = "William sale per primo sulla scalinata."
  },
  AvgDialog_147080_Content_148 = {
    Text = "La sua mano rimane premuta all'interno del cappotto — Come Se stesse placando un desiderio ormai abbandonato."
  },
  AvgDialog_147080_Content_149 = {
    Text = "In questo momento, nessuno nota che la Chiave rimasta in Silenzio per anni sta emettendo un Tremore impercettibile attraverso il tessuto."
  },
  AvgDialog_147080_Content_15 = {
    Text = "Per Divorare il vostro Potere."
  },
  AvgDialog_147080_Content_150 = {
    Text = "Come Se qualcosa, in cima alla montagna, stesse aspettando di riceverla."
  },
  AvgDialog_147080_Content_16 = {
    Text = "Una spiegazione chiara e semplice."
  },
  AvgDialog_147080_Content_17 = {
    Text = "Allora, il Potere degli altri scalatori..."
  },
  AvgDialog_147080_Content_18 = {
    Text = "È tutto racchiuso in questi Sacrifici."
  },
  AvgDialog_147080_Content_19 = {
    Text = "Il meccanismo di cooperazione tra Caraboo e il Verme della Montagna è che Lei seleziona i Sacrifici dotati di desideri intensi e spiritualità, attirando l'altra parte a inoltrarsi tra le montagne."
  },
  AvgDialog_147080_Content_2 = {
    Text = "Allora, signore, quale capriccio ha spinto Vostra Signoria a fare il cosplay di una guida alpina Sherpa? Non sarà mica per amore degli sport estremi umani, vero?"
  },
  AvgDialog_147080_Content_20 = {
    Text = "Sorge una domanda: perché il Verme della Montagna ha rotto attivamente questa cooperazione?"
  },
  AvgDialog_147080_Content_21 = {
    Text = "Perché sapeva che ero in preda allo Scuotimento."
  },
  AvgDialog_147080_Content_22 = {
    Text = "Caraboo menzionò l'ultima conversazione avuta sulla cresta della montagna."
  },
  AvgDialog_147080_Content_23 = {
    Text = "Credevo che nessuno potesse resistere alla Cupidigia, che per realizzare i propri desideri si dovesse fare affidamento su \"qualcosa di non umano\". Ma Lei mi ha fatto capire che accontentarsi dell'ordinario può portare ugualmente alla felicità."
  },
  AvgDialog_147080_Content_24 = {
    Text = "In quell'istante, ho provato un \"desiderio\" superfluo."
  },
  AvgDialog_147080_Content_25 = {
    Text = "Il \"desiderio\" è un'esca, è una miccia."
  },
  AvgDialog_147080_Content_26 = {
    Text = "Fin dall'Inizio, ero io la \"Mela d'Oro\" destinata ad essere Divorata."
  },
  AvgDialog_147080_Content_27 = {
    Text = "Come possiamo essere sicuri che non stai di nuovo cercando di ingannarci?"
  },
  AvgDialog_147080_Content_28 = {
    Text = "Credici o no. In questo momento, tra tutti voi, sono io quello che odia di più il Verme della Montagna."
  },
  AvgDialog_147080_Content_29 = {
    Text = "Se non fosse stato per quella notte di Neve, quando il Verme della Montagna mi ingannò e strinsi Il Testamento con lui… non avrei mai imboccato il Sentiero che percorro oggi."
  },
  AvgDialog_147080_Content_3 = {
    Text = "Se ti dicessi che è per dare voce al popolo Sherpa, mi crederesti?"
  },
  AvgDialog_147080_Content_30 = {
    Text = "<Small:Impostore maledetto>."
  },
  AvgDialog_147080_Content_31 = {
    Text = "Nel breve Silenzio, si udiva solo il respiro nauseante delle pareti di Caro che si alzavano e abbassavano."
  },
  AvgDialog_147080_Content_32 = {
    Text = "Capito. Purché tu non faccia nulla di eccessivo, per ora non chiederemo conto dei problemi del passato."
  },
  AvgDialog_147080_Content_33 = {
    Text = "Ora la cosa più urgente è trovare un modo per uscire dallo stomaco di questa Divinità… preferibilmente senza ricorrere al Potere del signor N."
  },
  AvgDialog_147080_Content_34 = {
    Text = "Oh, ma come potete sprecare così la buona volontà del generoso e affascinante signor N?"
  },
  AvgDialog_147080_Content_35 = {
    Text = "O forse credete davvero che uscire dal suo ventre sia semplice come lasciare una Stanza d'albergo che non vi soddisfa?"
  },
  AvgDialog_147080_Content_36 = {
    Text = "Hai detto che non potevi dircelo."
  },
  AvgDialog_147080_Content_37 = {
    Text = "Pensate che lo faccia apposta a nascondervi qualcosa? Allora mi fate un torto."
  },
  AvgDialog_147080_Content_38 = {
    Text = "N giocherellava con la rosa apparsa dal nulla tra le dita, volgendo con calma Lo Sguardo verso Caraboo."
  },
  AvgDialog_147080_Content_39 = {
    Text = "Qualunque soluzione io abbia, non posso fartela sapere. Giusto, piccola bugiarda?"
  },
  AvgDialog_147080_Content_4 = {
    Text = "Certo, non solo ci credo, credo anche che Lady Sorel sostenga il laissez-faire, che Ryker abbia abbandonato la Scommessa per sempre, che Erica sia saggia e brillante nelle parole…"
  },
  AvgDialog_147080_Content_40 = {
    Text = "Caraboo non replicò. Lei si limitò a mordere il labbro inferiore con forza, evitando Lo Sguardo di tutti."
  },
  AvgDialog_147080_Content_41 = {Text = "Caraboo?"},
  AvgDialog_147080_Content_42 = {
    Text = "…Lui riesce a sentirmi."
  },
  AvgDialog_147080_Content_43 = {
    Text = "Non è una metafora. Quando avevo sei anni, la notte di neve in cui la seguii per andarmene, le ipotecai la mia anima."
  },
  AvgDialog_147080_Content_44 = {
    Text = "Questo è Il Testamento tra me e lui. Lui mi ha prestato il Potere di Una Bugia, permettendomi di ingannare chiunque al mondo; e come prezzo —"
  },
  AvgDialog_147080_Content_45 = {
    Text = "A lui, non posso nascondere nemmeno un singolo pensiero."
  },
  AvgDialog_147080_Content_46 = {
    Text = "…Quindi, in questo momento, ogni parola che diciamo —"
  },
  AvgDialog_147080_Content_47 = {
    Text = "Purché entri nelle mie orecchie e raggiunga la mia mente, lui sa tutto."
  },
  AvgDialog_147080_Content_48 = {
    Text = "La Caro tutt'intorno si tese bruscamente per un istante, poi si allentò lentamente. Come se una creatura immensa si nascondesse dietro un sipario, ad ascoltare tutto ciò con vivo interesse."
  },
  AvgDialog_147080_Content_49 = {
    Text = "Ora capite?"
  },
  AvgDialog_147080_Content_5 = {
    Text = "Non è il momento di bisticciare."
  },
  AvgDialog_147080_Content_50 = {
    Text = "C'è sempre stato un modo. Ma se dovesse arrivare anche solo alle orecchie di questa giovane signora, tanto varrebbe giocare a Texas Hold'em con le carte scoperte."
  },
  AvgDialog_147080_Content_51 = {
    Text = "Quando discutiamo il piano, facciamo Eludere Caraboo?"
  },
  AvgDialog_147080_Content_52 = {
    Text = "Anche se non sentissi il vostro piano, potrei accorgermi di qualcosa di strano durante l'esecuzione."
  },
  AvgDialog_147080_Content_53 = {
    Text = "Non posso vedere le tue microespressioni, i tuoi piccoli gesti. Altrimenti, saprei quale frase è Una Bugia."
  },
  AvgDialog_147080_Content_54 = {
    Text = "Forse potresti non guardare?"
  },
  AvgDialog_147080_Content_55 = {
    Text = "No, Una Bugia è un'atmosfera fluida… e io vi sono immersa da troppo tempo."
  },
  AvgDialog_147080_Content_56 = {
    Text = "A volte, anche senza che nessuno apra bocca, riesco a percepire l'esistenza di Una Bugia nell'aria immobile."
  },
  AvgDialog_147080_Content_57 = {
    Text = "Lasciami provare."
  },
  AvgDialog_147080_Content_58 = {
    Text = "Al suono cristallino di uno schiocco di dita, una nuvola di fumo nero avvolse gli occhi di Caraboo."
  },
  AvgDialog_147080_Content_59 = {
    Text = "Bene, Occhi Aperti."
  },
  AvgDialog_147080_Content_6 = {
    Text = "Arachne ci ha condotti qui, e deve avere le sue ragioni. E tu dovresti essere un anello del Destino."
  },
  AvgDialog_147080_Content_60 = {
    Text = "Caraboo aprì gli Occhi. Tutto ciò che aveva davanti era avvolto da un fumo di Distorsione, e persino i suoni diventarono confusi e lontani."
  },
  AvgDialog_147080_Content_61 = {
    Text = "William invece abbassò improvvisamente lo sguardo, le nocche appoggiate al mento, come se stesse elaborando una Deduzione su una partita a scacchi che solo lui poteva vedere."
  },
  AvgDialog_147080_Content_62 = {Text = "Fermati."},
  AvgDialog_147080_Content_63 = {Text = "Hm?"},
  AvgDialog_147080_Content_64 = {
    Text = "Non è necessario coprirle gli Occhi."
  },
  AvgDialog_147080_Content_65 = {
    Text = "Al contrario, d'ora in poi spero che Tu, Caraboo, sia massimamente vigile nel distinguere la verità dalla menzogna in ogni mia parola."
  },
  AvgDialog_147080_Content_66 = {
    Text = "Ascolta bene, Caraboo — o meglio, il Verme della Montagna che si cela dietro Caraboo. Voglio fare un patto con Te."
  },
  AvgDialog_147080_Content_67 = {
    Text = "La parete di carne fremette come in una risata beffarda."
  },
  AvgDialog_147080_Content_68 = {
    Text = "Ridicolo, siete nel mio ventre. Cosa hai da offrirmi in cambio?"
  },
  AvgDialog_147080_Content_69 = {
    Text = "Un desiderio."
  },
  AvgDialog_147080_Content_7 = {
    Text = "Sai come uscire da qui, vero, N?"
  },
  AvgDialog_147080_Content_70 = {
    Text = "Tutt'intorno calò improvvisamente il silenzio."
  },
  AvgDialog_147080_Content_71 = {
    Text = "Il cerchio dei desideri sulla cima della montagna <Yellow:non è stato creato da te>, ma da qualcosa di più antico di te, vero?"
  },
  AvgDialog_147080_Content_72 = {Text = "..."},
  AvgDialog_147080_Content_73 = {
    Text = "Il Verme della Montagna tacque per un istante, poi emise una risatina non committente."
  },
  AvgDialog_147080_Content_74 = {
    Text = "Interessante. Continua."
  },
  AvgDialog_147080_Content_75 = {
    Text = "Prima di questa scalata, la leggenda raccontata da Caraboo differiva leggermente da quella diffusa tra la gente di montagna. In breve, la gente di montagna sapeva solo che raggiungere la vetta avrebbe esaudito un desiderio, ma ignorava l'esistenza dei sette artefatti rituali."
  },
  AvgDialog_147080_Content_76 = {
    Text = "Ha senso. Se lo scopo era solo attirare gli esseri umani a scalare la montagna per poi divorarli, non c'era alcun bisogno di tessere la leggenda dei sette artefatti rituali."
  },
  AvgDialog_147080_Content_77 = {
    Text = "Bastava dire a tutti che raggiungere la vetta avrebbe esaudito qualsiasi desiderio."
  },
  AvgDialog_147080_Content_78 = {
    Text = "Più è difficile, meno sono coloro che osano tentare — questa logica elementare non potete non capirla, a meno che—"
  },
  AvgDialog_147080_Content_79 = {
    Text = "A meno che—"
  },
  AvgDialog_147080_Content_8 = {
    Text = "Lo so… o forse no… Ah, questa è davvero una domanda interessante."
  },
  AvgDialog_147080_Content_80 = {
    Text = "Il Verme della Montagna allungò il tono con aria sarcastica."
  },
  AvgDialog_147080_Content_81 = {
    Text = "A meno che i sette artefatti rituali esistano davvero, e il rituale per esaudire i desideri esista davvero."
  },
  AvgDialog_147080_Content_82 = {
    Text = [[
E tu stai appostato accanto al cerchio rituale non solo per divorare gli scalatori.
Stai anche aspettando un'occasione per avviare il rituale.]]
  },
  AvgDialog_147080_Content_83 = {
    Text = "Il mondo di Caro smise di respirare."
  },
  AvgDialog_147080_Content_84 = {
    Text = "Se hai sempre vegliato sul rituale, perché non lo hai avviato tu stesso?"
  },
  AvgDialog_147080_Content_85 = {
    Text = "Essere umano, fai troppe domande."
  },
  AvgDialog_147080_Content_86 = {
    Text = "Sembra che abbia fatto la domanda giusta."
  },
  AvgDialog_147080_Content_87 = {
    Text = "Lasciami indovinare."
  },
  AvgDialog_147080_Content_88 = {
    Text = "Nel cerchio magico esiste un nucleo che non riesci a decifrare, giusto? Quindi in tutti questi anni hai accumulato un Sacrificio dopo l'altro, ma non sei mai riuscito ad aprire quell'ultimo Portale."
  },
  AvgDialog_147080_Content_89 = {
    Text = "Le pareti di carne si contrassero improvvisamente, Quasi schiacciando tutti."
  },
  AvgDialog_147080_Content_9 = {
    Text = "Non fare il misterioso, parla chiaro."
  },
  AvgDialog_147080_Content_90 = {
    Text = "So perché non riesci a decifrarlo. Ho dato un'occhiata al cerchio magico poco fa, e le rune incise su di esso contengono testo latino e altri caratteri antichi."
  },
  AvgDialog_147080_Content_91 = {
    Text = "E questa tua… piccola Proxy, a giudicare dal Calcolo deduttivo del tempo trascorso da quando ha lasciato Casa Nostra, è evidente che non abbia mai ricevuto una buona istruzione accademica…"
  },
  AvgDialog_147080_Content_92 = {
    Text = "<Shake:Sì, scusa se non so leggere! E allora?!>"
  },
  AvgDialog_147080_Content_93 = {
    Text = "Il tempo stringeva, poco fa non avevo ancora finito di leggerlo quando mi hai inghiottito qui. Ma immagino che ciò che è Registro Sopra riguardi per lo più le conoscenze relative all'attivazione del cerchio magico."
  },
  AvgDialog_147080_Content_94 = {
    Text = "La Dea del Destino ci ha guidati fin qui, i sette artefatti sono stati riuniti. Dovresti sapere che questa è la volta in cui sei più vicino a realizzare il tuo desiderio."
  },
  AvgDialog_147080_Content_95 = {
    Text = "E noi possiamo <Yellow:rinunciare volontariamente all'opportunità di esprimere un desiderio alla montagna>."
  },
  AvgDialog_147080_Content_96 = {
    Text = "Il Verme della Montagna sprofondò in un lungo Silenzio. Proprio quando pensavate che non avrebbe più risposto, emise un leggero grugnito."
  },
  AvgDialog_147080_Content_97 = {
    Text = "Rinunciare a un desiderio… davvero un Sacrificio notevole. Quello che vuoi non è solo che vi lasci andare, vero?"
  },
  AvgDialog_147080_Content_98 = {
    Text = "Al termine del rituale, tutti gli altri artefatti potranno restare a te, ma noi porteremo via la <Blue:Corona di Arianna>."
  },
  AvgDialog_147080_Content_99 = {
    Text = "La Corona di Arianna…"
  },
  AvgDialog_147095_Content_1 = {
    Text = "Nella sala vuota, rimanevano solo gli echi dei tuoi e dei passi di Murphy."
  },
  AvgDialog_149752_Content_1 = {
    Text = "Tana del Drago"
  },
  AvgDialog_149752_Content_10 = {
    Text = "Non ti rimane nulla. Non puoi sopportare di dimenticare ancora."
  },
  AvgDialog_149752_Content_11 = {
    Text = "Le fiamme ruggenti sono state spente dalla pioggia. Attraversi il cancello incustodito e non vedi altro che rovine."
  },
  AvgDialog_149752_Content_12 = {
    Text = "Il castello si erge in silenzio — barili di olio vuoti, sacchi di tela strappati, scudi in frantumi, lance spezzate, frecce distese come file di canne piegate dal vento, il puzzo acre del fango bagnato che si mescola al persistente odore di bruciato."
  },
  AvgDialog_149752_Content_13 = {
    Text = "Una volta qui si combatté una battaglia. Ora rimangono solo ombre."
  },
  AvgDialog_149752_Content_14 = {
    Text = "Le ombre si diffondono liberamente nell'oscurità, arrampicandosi sulle alte mura, strisciando sui merli, inghiottendo i corpi sparsi sul terreno, emettendo suoni umidi e viscidi. Cerchi di non pensare a cosa significhi."
  },
  AvgDialog_149752_Content_15 = {
    Text = "Segui le ombre… segui solo le ombre…"
  },
  AvgDialog_149752_Content_16 = {
    Text = "A-aiuto… aiutami…"
  },
  AvgDialog_149752_Content_17 = {
    Text = "Un gemito di dolore si leva da sotto un elmo deformato, con le ombre che vi si aggrappano come un amante devoto. Raccogli il coraggio e fai un passo avanti."
  },
  AvgDialog_149752_Content_18 = {
    Text = "Colui che ha portato le ombre — dove è andato?"
  },
  AvgDialog_149752_Content_19 = {
    Text = "<Shake:Om… ombra? No, no — è un mostro! Sangue nero… vuoto dentro… un cavaliere della morte… è reale, è tutto reale!>"
  },
  AvgDialog_149752_Content_2 = {
    Text = "Cos'è una promessa? Magia che non si avvera a meno che tu non ci creda."
  },
  AvgDialog_149752_Content_20 = {
    Text = "<Shake:Scappa… ugh… scappa! Un mostro immortale… vendetta… distruzione… gorgoglio… gorgoglio gorgoglio…>"
  },
  AvgDialog_149752_Content_21 = {
    Text = "Un suono denso e viscoso sale dalla gola del mostro. Si contorce come un pesce spiaggiato, eppure il suo braccio si alza lentamente, protendendosi verso il fagotto tra le tue braccia. Un viscido melmoso e palpitante filtra attraverso le giunture della sua armatura."
  },
  AvgDialog_149752_Content_22 = {
    Text = "È un'ombra. Vuole il Santo Graal."
  },
  AvgDialog_149752_Content_23 = {
    Text = "No, no, questo è qualcosa di importante. Non posso dartelo."
  },
  AvgDialog_149752_Content_24 = {
    Text = "Rifiutare è inutile. Le ombre scorrono giù dalle mura e convergono rapidamente su di te. Stringi il fagotto con forza nel panico e ti giri per fuggire più in profondità nel castello."
  },
  AvgDialog_149752_Content_25 = {
    Text = "Il corpo di guardia, la grande sala, la cappella — scale di pietra a spirale scendono nelle viscere della terra. Il castello è una pericolosa tana di drago. L'aria si fa sempre più fredda, i tuoi ansiti e i tuoi passi amplificati strato dopo strato dalle pareti di pietra, come se appartenessero a qualcun altro."
  },
  AvgDialog_149752_Content_26 = {
    Text = "Una fiamma tremola in fondo alla scala a chiocciola, e scorgi una figura familiare."
  },
  AvgDialog_149752_Content_27 = {Text = "Og—"},
  AvgDialog_149752_Content_28 = {
    Text = "Stai per chiamarlo con gioia quando ti rendi improvvisamente conto che non siete solo voi due. Il mostro parla prima che tu possa farlo."
  },
  AvgDialog_149752_Content_29 = {
    Text = "<Shake:Tosse, tosse, tosse, tosse… Ogier…>"
  },
  AvgDialog_149752_Content_3 = {
    Text = "Cos'è la separazione? Il momento dopo l'arrivo."
  },
  AvgDialog_149752_Content_30 = {
    Text = "Come sei ridotto così?"
  },
  AvgDialog_149752_Content_31 = {
    Text = "Il mio… aspetto?"
  },
  AvgDialog_149752_Content_32 = {
    Text = "Vini pregiati e un sontuoso banchetto sono disposti sul tavolo, posate d'argento che brillano alla luce delle candele. Se non fosse per il freddo glaciale che filtra dalle crepe nella pietra, questa scenografia così curata farebbe quasi dimenticare di trovarsi nelle profondità di un oscuro sotterraneo."
  },
  AvgDialog_149752_Content_33 = {
    Text = "Il signore emaciato siede solo dietro al tavolo, occhi infossati, zigomi affilati e prominenti, sepolto sotto strati di pesante seta — come un drago malvagio raggomitolato sul suo tesoro d'oro e d'argento."
  },
  AvgDialog_149752_Content_34 = {
    Text = "Il tuo cavaliere avanza verso di esso passo dopo passo, una lunga ombra che si trascina dietro di lui. Forse lui stesso è un'ombra. I suoi abiti sono a brandelli, il suo volto contorto e terrificante, i suoi passi completamente silenziosi."
  },
  AvgDialog_149752_Content_35 = {
    Text = "Davvero, se non l'avessi visto con i miei stessi occhi, stenterei a crederci… tosse, tosse, tosse… Il cavaliere più giovane del ducato, ridotto a un mostro."
  },
  AvgDialog_149752_Content_36 = {
    Text = "Il ducato… è già distrutto."
  },
  AvgDialog_149752_Content_37 = {
    Text = "Per colpa tua."
  },
  AvgDialog_149752_Content_38 = {
    Text = "Per colpa della guerra, per colpa della peste, per colpa dell'avidità delle nazioni vicine, per colpa della propria debolezza. Ci sono molte ragioni per cui un ducato può cadere. Io sono semplicemente, tosse tosse, la più insignificante di esse."
  },
  AvgDialog_149752_Content_39 = {
    Text = "<Shake:Tu… hai tradito il ducato… ti sei accordato con il nemico… hai venduto… il tuo stesso popolo…>"
  },
  AvgDialog_149752_Content_4 = {
    Text = "Cos'è la morte? Un domani senza addio."
  },
  AvgDialog_149752_Content_40 = {
    Text = "<Shake:Traditore… meriti di morire.>"
  },
  AvgDialog_149752_Content_41 = {
    Text = "Sì, sì, come puoi vedere, il frutto amaro è già ricaduto su di me. Non mi resta molto tempo, tosse, tosse, tosse, tosse."
  },
  AvgDialog_149752_Content_42 = {
    Text = "La peste non mi ha risparmiato, Ogier. La morte — non fa distinzioni. Aspetta pazientemente dall'altra parte del ponte per ognuno. Nessuno può sfuggirle… tranne te."
  },
  AvgDialog_149752_Content_43 = {
    Text = "Dimmi, che patto hai stretto con il diavolo?"
  },
  AvgDialog_149752_Content_44 = {Text = "..."},
  AvgDialog_149752_Content_45 = {
    Text = "Il prezzo di sfuggire alla morte peserà sempre più della morte stessa. Cavaliere della Morte… diventarne il boia — era un desiderio che hai espresso, o una punizione che hai ricevuto?"
  },
  AvgDialog_149752_Content_46 = {
    Text = "Ogier, il cavaliere più leale, più devoto del Ducato, ah, <Shake:tosse tosse tosse tosse tosse……>"
  },
  AvgDialog_149752_Content_47 = {
    Text = "Sono un dannato traditore — ma tu sei diverso?"
  },
  AvgDialog_149752_Content_48 = {Text = "!!"},
  AvgDialog_149752_Content_49 = {
    Text = "Un fulmine invisibile colpisce il tuo cavaliere, inchiodandolo saldamente al suo posto. Le ombre nell'oscurità tremano violentemente — di gioia o di furia, non riescono più a contenersi."
  },
  AvgDialog_149752_Content_5 = {
    Text = "Cos'è il dimenticare?"
  },
  AvgDialog_149752_Content_50 = {
    Text = "Io ho tradito il Granduca, ma tu — tu e la tua principessa — voi avete tradito Dio."
  },
  AvgDialog_149752_Content_51 = {
    Text = "Te lo ricordi ancora… osi tirarlo in ballo…"
  },
  AvgDialog_149752_Content_52 = {
    Text = "<Red:La Principessa Strega>, tosse tosse tosse, che ironia — i suoi inganni furono infine smascherati, eppure nemmeno il suo nome viene più ricordato. L'ho detto da tempo: consegnatela, e i fuochi della guerra si sarebbero spenti, il Ducato non sarebbe caduto."
  },
  AvgDialog_149752_Content_53 = {
    Text = "Sai cosa ci ha portato — lo sai fin troppo bene. La maledizione… la guerra iniziò per colpa sua, e per colpa sua finì. Grazie a lei, @3il Ducato divenne un luogo dimenticato."
  },
  AvgDialog_149752_Content_54 = {
    Text = "Chiudi quella bocca! Tu… non sei degno… di pronunciare il suo nome!"
  },
  AvgDialog_149752_Content_55 = {
    Text = "La lancia informe fende il lungo tavolo in due; coppe e piatti si schiantano a terra, il banchetto falso va in frantumi, rivelando le macerie sottostanti."
  },
  AvgDialog_149752_Content_56 = {
    Text = "Le ombre estendono viscosi pseudopodi, divorando avidamente tutto ciò che toccano; paludi emergono da profondità senza luce, e il mondo comincia ad affondare."
  },
  AvgDialog_149752_Content_57 = {
    Text = "La morte… e poi l'oblio… come se non fosse mai accaduto. Questo è il destino di coloro che abbandonano Dio."
  },
  AvgDialog_149752_Content_58 = {
    Text = "È stata lei a ridurrti in questo stato, vero… trascinando l'intero Ducato nel vuoto, per poi lasciare dietro di sé un fantoccio d'odio a diffondere la vera morte per tutta la terra. Chiami lealtà il portare a termine una simile missione?"
  },
  AvgDialog_149752_Content_59 = {
    Text = "Ogier… chi servi, davvero?"
  },
  AvgDialog_149752_Content_6 = {Text = "..."},
  AvgDialog_149752_Content_60 = {
    Text = "<Shake:No… no… la Principessa non è… glu… glu glu……>"
  },
  AvgDialog_149752_Content_61 = {
    Text = "Il tuo cavaliere si stringe la testa in preda all'agonia; ombre sgorgano dal suo petto, dalle orecchie, dagli angoli degli occhi. Il tormento incessante del demone lo ha lasciato debole — non riesce più a emettere un suono, come una bambola d'argilla che si dissolve nell'acqua nera."
  },
  AvgDialog_149752_Content_62 = {
    Text = "Mentre nessuno dei due stava prestando attenzione, il signore girò di lato la sua sedia a rotelle, rivelando una feritoia delle dimensioni di un pugno nascosta nella parete di pietra dietro di lui. Un'ombra nera guizza come un serpente, accompagnata da un sordo tonfo — una lancia di ferro trafigge il tuo cavaliere in pieno petto."
  },
  AvgDialog_149752_Content_63 = {
    Text = "<Big:Ogier!!!>"
  },
  AvgDialog_149752_Content_64 = {
    Text = "<Shake:Tosse tosse tosse tosse……>Un mostro che è strisciato fuori dalla sua tomba farebbe meglio a tornarci in fretta."
  },
  AvgDialog_149752_Content_65 = {
    Text = "Tu e il tuo mostriciattolo potete essere sepolti qui insieme."
  },
  AvgDialog_149752_Content_66 = {
    Text = "Alcune guardie completamente armate emersero dal passaggio segreto, con scudi e spade che brillavano di una luce sinistra — l'ultima trappola si era finalmente rivelata."
  },
  AvgDialog_149752_Content_7 = {Text = "..."},
  AvgDialog_149752_Content_8 = {
    Text = "<Red:Una maledizione.>"
  },
  AvgDialog_149752_Content_9 = {
    Text = "Una maledizione. Una piaga. Una punizione. Un vuoto divorato dai vermi. Un letto di fiume spezzato. Marcire in silenzio. Consumarsi. Affondare. Uno sguardo che si spende nel nulla. Svanire dalla storia nell'ombra. La morte finale."
  },
  AvgDialog_149753_Content_1 = {
    Text = "Calice Sacro"
  },
  AvgDialog_149753_Content_10 = {
    Text = "Nulla di ciò che ho fatto è degno di un cavaliere. Lo hai visto con i tuoi occhi."
  },
  AvgDialog_149753_Content_11 = {
    Text = "Perché? Un cavaliere deve combattere i mostri — è il tuo dovere, e lo hai fatto bene."
  },
  AvgDialog_149753_Content_12 = {
    Text = "E stai cercando qualcosa, vero? Lo sento. Hai perquisito ogni posto, da quando siamo entrati in città — sono già giorni. Il mostro ti ha portato via qualcosa anche a te?"
  },
  AvgDialog_149753_Content_13 = {Text = "..."},
  AvgDialog_149753_Content_14 = {
    Text = "Siamo arrivati."
  },
  AvgDialog_149753_Content_15 = {
    Text = "La calda luce ambrata delle candele riempiva le pareti tutt'intorno, e le porte di quercia tenevano fuori il vento freddo. Per i viandanti senza casa a cui tornare, il magazzino del monastero spalancato in una notte di pioggia poteva persino salvare vite."
  },
  AvgDialog_149753_Content_16 = {
    Text = "Ma non ti saresti lasciata ingannare dall'illusione — li ricordavi. Coloro che andavano e venivano portando candelabri, tuniche nere, pendenti di ottone, carnefici che si definivano pastori — erano mostri tra i mostri."
  },
  AvgDialog_149753_Content_17 = {
    Text = "<Small:Perché siamo venuti qui… quello che cerchi è dentro?>"
  },
  AvgDialog_149753_Content_18 = {
    Text = "Resta qui ad aspettarmi. Non seguire."
  },
  AvgDialog_149753_Content_19 = {
    Text = "<Big:Cosa?! No! Assolutamente no!>"
  },
  AvgDialog_149753_Content_2 = {
    Text = "<Shake:Non lo so, non so cos'era quello — no, no, no, per favore, per favore abbi pietà——>"
  },
  AvgDialog_149753_Content_20 = {
    Text = "<Big:Non resto qui, mi rifiuto categoricamente di restare qui! Vengo con te!>"
  },
  AvgDialog_149753_Content_21 = {
    Text = "Cosa c'è? Bambina, hai bisogno di aiuto?"
  },
  AvgDialog_149753_Content_22 = {
    Text = "Sì, ti prego tienila d'occhio. Non lasciarla scappare."
  },
  AvgDialog_149753_Content_23 = {
    Text = "Oh… è così tardi, e la pioggia cade a dirotto — dove stai andando di tanta fretta? Aspetta l'alba, e non lasciare qui da sola la tua sorellina."
  },
  AvgDialog_149753_Content_24 = {
    Text = "Tornerò a prenderla all'alba."
  },
  AvgDialog_149753_Content_25 = {
    Text = "Se insisti, va bene, va bene. Povera bambina, bagnata fino alle ossa, vieni qui, vieni da me, lascia che ti asciughi il viso."
  },
  AvgDialog_149753_Content_26 = {
    Text = "Sei intrappolata, incapace di muoverti, un panno di lino asciutto ti strofina le guance, e non sai quando potrebbe soffocarti la bocca e il naso."
  },
  AvgDialog_149753_Content_27 = {
    Text = "La paura ti schiaccia il petto, non riesci a respirare, puoi solo urlare."
  },
  AvgDialog_149753_Content_28 = {
    Text = "<Shake:Torna! Sei il mio cavaliere, dovresti proteggermi, non puoi lasciarmi indietro — me lo avevi promesso!>"
  },
  AvgDialog_149753_Content_29 = {
    Text = "<Shake:Ti prego, non darò fastidio, lasciami venire con te!>!"
  },
  AvgDialog_149753_Content_3 = {Text = "Ugh!!"},
  AvgDialog_149753_Content_30 = {
    Text = "Molti occhi vengono attratti dalle tue urla rauche, alcuni simili a quelli dei coleotteri, altri a quelli delle capre, altri ancora a quelli dei gufi."
  },
  AvgDialog_149753_Content_31 = {
    Text = "Ti fissano immobili, come se fossi l'unica ad essere nata senza occhi."
  },
  AvgDialog_149753_Content_32 = {
    Text = "<SmallShake:Non… non andare… avevi chiaramente promesso…>"
  },
  AvgDialog_149753_Content_33 = {
    Text = "<SmallShake:Ti prego, non lasciarmi indietro…>"
  },
  AvgDialog_149753_Content_34 = {
    Text = "Ho cambiato idea. Lascia che venga con me."
  },
  AvgDialog_149753_Content_35 = {
    Text = "Sollevi di scatto la testa — il tuo cavaliere è tornato indietro a un certo punto, bloccando con la propria schiena gli sguardi di tutti i mostri."
  },
  AvgDialog_149753_Content_36 = {
    Text = "Ma dove hai intenzione di portarla? In città ci sono pochi posti dove ripararsi dalla pioggia, e nessuno di essi è adatto a una bambina."
  },
  AvgDialog_149753_Content_37 = {
    Text = "Dove sto andando non è in città."
  },
  AvgDialog_149753_Content_38 = {
    Text = "Fuori dalla città c'è ancora meno — ah! Non dirmi che stai andando verso quel maniero?"
  },
  AvgDialog_149753_Content_39 = {
    Text = "Cosa c'è che non va in quel maniero?"
  },
  AvgDialog_149753_Content_4 = {
    Text = "Le urla furono soffocate dalla pioggia torrenziale, mescolandosi al sangue che scorreva nel canale ai piedi del muro, marcendo insieme al fango, allo sterco di cavallo e agli scarti di verdura, finché il vicolo buio non inghiottì tutto."
  },
  AvgDialog_149753_Content_40 = {
    Text = "Quel posto, quel posto… sospiro, anche voi due siete rifugiati, vero? Bambina, stai lontana da lì."
  },
  AvgDialog_149753_Content_41 = {
    Text = "Quel signore — era un tempo un uomo buono, ma guerra, pestilenza e calamità si sono abbattute come maree, e le persone hanno smesso di essere persone. Tutti dicono che sia impazzito. Sempre meno persone rimangono in città, e quelli che andavano a mendicare del pane non sono mai tornati."
  },
  AvgDialog_149753_Content_42 = {
    Text = "Che il Signore perdoni… tutti dicono che mangi segretamente le persone."
  },
  AvgDialog_149753_Content_43 = {
    Text = "I mostri mangiano le persone — lo sai da molto tempo, quindi non sei per niente sorpresa, né spaventata… almeno non così spaventata. Hai il tuo cavaliere."
  },
  AvgDialog_149753_Content_44 = {
    Text = "Stai vicina a me. Qui qualcosa non va."
  },
  AvgDialog_149753_Content_45 = {Text = "O-Okay."},
  AvgDialog_149753_Content_46 = {
    Text = "Il vasto maniero era deserto — nessuna guardia, nessun servo, come se fosse stato abbandonato da secoli. Solo il suono dei tuoi passi deliberatamente attutiti riecheggiava nei lunghi e stretti corridoi."
  },
  AvgDialog_149753_Content_47 = {
    Text = "Allora… cosa stai cercando esattamente? È importante per te? Dimmi com'è fatto — posso aiutarti a trovarlo."
  },
  AvgDialog_149753_Content_48 = {
    Text = "Un calice d'oro."
  },
  AvgDialog_149753_Content_49 = {
    Text = "Un calice d'oro? Intendi fatto d'oro? Wow, quanto è grande, quanto è alto? Cosa ci metti dentro? Com'è l'oro — brilla come la luna di notte?"
  },
  AvgDialog_149753_Content_5 = {
    Text = "Il corpo si accasciò mollemente a terra, un freddo bagliore metallico lampeggiò e svanì, mentre l'assassino stringeva il mantello e si allontanava a passo svelto, i passi dissolti nella pioggia."
  },
  AvgDialog_149753_Content_50 = {
    Text = "...Non ne sono sicuro."
  },
  AvgDialog_149753_Content_51 = {
    Text = "Eh? Non è tuo?"
  },
  AvgDialog_149753_Content_52 = {
    Text = "No, ma è molto importante per me."
  },
  AvgDialog_149753_Content_53 = {
    Text = "Oh! Lo so — è il Santo Graal, vero? Ne ho sentito parlare nelle storie. Un tesoro magico che solo un cavaliere che supera le prove può ottenere. Non c'è da stupirsi che tu lo stia cercando da così tanto tempo."
  },
  AvgDialog_149753_Content_54 = {
    Text = "Ehm, in quanto tua principessa, se riuscissi a ottenere il Santo Graal, ne trarrei vantaggio anch'io, quindi…"
  },
  AvgDialog_149753_Content_55 = {
    Text = "Si fermò di colpo, alzò l'indice e ti fece un gesto per chiederti di tacere."
  },
  AvgDialog_149753_Content_56 = {
    Text = "Ti bloccasti immediatamente, trattenendo istintivamente il respiro. La Lanterna si spense, e l'oscurità si riversò dentro, avvolgendoti senza lasciare alcuno spiraglio."
  },
  AvgDialog_149753_Content_57 = {
    Text = "Contasti quattordici battiti del cuore. Poi un tonfo sordo giunse dal fondo del corridoio, seguito dal fracasso di qualcosa che si frantumava sul pavimento, e alcune urla incontrollate spezzarono il silenzio."
  },
  AvgDialog_149753_Content_58 = {
    Text = "Una luce divampò — tremolante e instabile, come le sagome di molte persone in una furiosa lotta. Ti lanciasti di corsa verso di essa, ma fosti respinto da un'ondata di calore. Era fuoco. Fuoco blu."
  },
  AvgDialog_149753_Content_59 = {
    Text = "La — colpo di tosse, colpo di tosse — lasciami! Ero così vicino! Ancora un poco — ancora un poco!"
  },
  AvgDialog_149753_Content_6 = {
    Text = "Tirasti in fretta il cappuccio e trotterellasti sotto la pioggia, riuscendo a malapena a tenergli il passo."
  },
  AvgDialog_149753_Content_60 = {
    Text = "Un odore pungente riempì la camera segreta. Un sospetto liquido rosso scuro gocciolava lentamente attraverso tubi di vetro. Una candela aveva dato fuoco a un liquido trasparente sparso sul pavimento, e pallide fiamme blu bruciavano in silenzio. Nel profondo del maniero, una stanza alchemica nascosta era rimasta celata per tutto quel tempo."
  },
  AvgDialog_149753_Content_61 = {
    Text = "Al centro dei numerosi recipienti di vetro, un calice d'oro puro brillava intensamente — più dello Stoppino. Doveva essere il Santo Graal."
  },
  AvgDialog_149753_Content_62 = {
    Text = "Cosa ci hai messo dentro?"
  },
  AvgDialog_149753_Content_63 = {
    Text = "Lasciami! Non capisci! Sta quasi arrivando — sta quasi arrivando… si diffonde attraverso tende in putrefazione, striscia lungo il Sentiero dell'Oblio. I vivi, i morti — nessuno può sfuggire… nessuno può sfuggire…"
  },
  AvgDialog_149753_Content_64 = {Text = "Cosa?"},
  AvgDialog_149753_Content_65 = {
    Text = "Lei… la notte eterna senza fine, l'annientamento definitivo… è una maledizione… <Shake:La maledizione sta quasi arrivando! Una maledizione che divora tutto — la maledizione della <Red:Principessa Strega>!!>"
  },
  AvgDialog_149753_Content_66 = {
    Text = "Cosa hai detto?!"
  },
  AvgDialog_149753_Content_67 = {
    Text = "L'ombra dietro di lui trasalì violentemente. Le fiamme caddero su occhi spalancati dal terrore — accendendo qualcosa. Paura, o speranza?"
  },
  AvgDialog_149753_Content_68 = {
    Text = "In quelle parole doveva essere nascosto un potente incantesimo, poiché il tuo cavaliere si bloccò all'improvviso come una statua di pietra, eppure sembrava prendere vita per la primissima volta. La sua ombra tremava senza sosta."
  },
  AvgDialog_149753_Content_69 = {
    Text = "Tu, tu… ti ricordi di lei? Cos'altro ricordi?"
  },
  AvgDialog_149753_Content_7 = {
    Text = "Cosa stai cercando?"
  },
  AvgDialog_149753_Content_70 = {
    Text = "<Shake:Vanità, vanità delle vanità, tutto è vanità… l'umanità fatica come polvere sulla pietra, senza passato, senza futuro…>"
  },
  AvgDialog_149753_Content_71 = {
    Text = "No — il calice d'oro! Il calice d'oro è l'unica salvezza! Lasciami bere la verità, lasciami — devo andare avanti!"
  },
  AvgDialog_149753_Content_72 = {
    Text = "<Big:Rispondi alla mia domanda!@1@2La principessa — quanto ricordi ancora di lei?!>"
  },
  AvgDialog_149753_Content_73 = {
    Text = "L'ombra si contorceva, l'ombra si gonfiava, l'ombra danzava selvaggiamente, avvolgendosi sempre più stretta attorno alla gola del mostro, le sue due labbra che si aprivano e si chiudevano in rantoli vani."
  },
  AvgDialog_149753_Content_74 = {
    Text = "<Shake:Ricordo… la peste… la pozione… la maledizione… kh, kh… ricordo, ti ricordo…>"
  },
  AvgDialog_149753_Content_75 = {
    Text = "<Shake:<Red:Au… gur>… mio cavaliere… tu… fuggi…>"
  },
  AvgDialog_149753_Content_76 = {Text = "\"Kh.\""},
  AvgDialog_149753_Content_77 = {
    Text = "Le parole rimasero incompiute, poiché non poteva più parlare — l'ombra gli spezzò il collo. La testa gonfia ricadde senza vita su un lato come un sacco di tela da imballaggio stretto, e attraverso i vuoti cavi, due bulbi oculari corrosi dalla ruggine fissavano ancora immobili il vuoto."
  },
  AvgDialog_149753_Content_78 = {Text = "..."},
  AvgDialog_149753_Content_79 = {
    Text = "Au… gur? Potrebbe essere… il tuo nome?"
  },
  AvgDialog_149753_Content_8 = {
    Text = "Non ho mai acconsentito a lasciarti seguire."
  },
  AvgDialog_149753_Content_80 = {
    Text = "Girò il viso di scatto, come uno spettro la cui vera forma era stata smascherata, la sua espressione sospesa tra lo sconcerto e l'odio. L'ombra sul muro ondeggiava e barcollava, danzando con passi gioiosi, circondando voi due al centro."
  },
  AvgDialog_149753_Content_81 = {
    Text = "No, non è giusto? Beh… qualunque sia il tuo nome, sei comunque il mio cavaliere."
  },
  AvgDialog_149753_Content_82 = {
    Text = "Il Santo Graal è stato trovato. Dove andiamo adesso?"
  },
  AvgDialog_149753_Content_83 = {
    Text = "Richiamato dalle tue parole, girò lentamente la testa verso il calice d'oro sul tavolo, poi con grande sforzo si liberò dalle ombre e sollevò la mezza coppa rimasta di antidoto — o veleno, non lo sapevi."
  },
  AvgDialog_149753_Content_84 = {
    Text = "Guardasti soltanto mentre reclinava la testa all'indietro e lo beveva tutto d'un fiato."
  },
  AvgDialog_149753_Content_85 = {
    Text = "<Big:Ehi!!>"
  },
  AvgDialog_149753_Content_9 = {
    Text = "Se non ti seguivo, e se tradivi la tua principessa? Non hai nemmeno voluto giurare."
  },
  AvgDialog_149754_Content_1 = {
    Text = "Il fragore assordante era devastante, come se l'intera torre principale stesse tremando. Mattoni e pietre frantumati crepitavano e cadevano, mentre i mostri rimasti si stringevano attorno al signore al centro, scortandolo mentre si ritiravano verso il passaggio segreto."
  },
  AvgDialog_149754_Content_10 = {
    Text = "Chissà quanto camminaste prima che una brezza vi venisse incontro. Salata. Il mare."
  },
  AvgDialog_149754_Content_11 = {
    Text = "Siamo — siamo fuori! Siamo scappati! Ogier, mi senti? Siamo salvi!!"
  },
  AvgDialog_149754_Content_12 = {Text = "…Ogier?"},
  AvgDialog_149754_Content_13 = {
    Text = "Non emetteva alcun suono — non riuscivi nemmeno a sentirlo respirare. Le onde si infrangevano sulle rocce, e l'acqua di mare gelida mista alla pioggia ti schizzava sul viso. Era come se sentissi freddo per la prima volta in assoluto, e non riuscivi a smettere di tremare."
  },
  AvgDialog_149754_Content_14 = {
    Text = "<SmallShake:…tosse… tosse, tosse…>"
  },
  AvgDialog_149754_Content_15 = {
    Text = "Ogier! Grazie al cielo — sapevo che non saresti morto!"
  },
  AvgDialog_149754_Content_16 = {
    Text = "<Shake:Io… non ti ho mai… promesso… di venire con te.>"
  },
  AvgDialog_149754_Content_17 = {
    Text = "Sì, sì, quante volte lo ripeterai. Una principessa ha forse bisogno del permesso del suo cavaliere per andare dove le pare?"
  },
  AvgDialog_149754_Content_18 = {Text = "..."},
  AvgDialog_149754_Content_19 = {
    Text = "<Shake:Io… una volta avevo… una… principessa.>"
  },
  AvgDialog_149754_Content_2 = {
    Text = "Il tuo cavaliere lottava per resistere, un grido rauco che gli esplodeva dal petto spezzato, ma le ombre avanzavano come una marea. Più che i nemici, sembravano volerlo divorare vivo."
  },
  AvgDialog_149754_Content_20 = {
    Text = "<Shake:Non sono riuscito a… proteggerla.>"
  },
  AvgDialog_149754_Content_21 = {
    Text = "I suoi flebili mormorii sembravano parole dette nel sonno, facilmente disperse dalla brezza marina. Dovesti trattenere il respiro."
  },
  AvgDialog_149754_Content_22 = {
    Text = "Prima che la guerra… scoppiasse… mi ordinò… di andarmene…"
  },
  AvgDialog_149754_Content_23 = {
    Text = "Io… ho obbedito."
  },
  AvgDialog_149754_Content_24 = {
    Text = "Non avevo mai pensato… il nemico… così veloce… non ce l'ho fatta, tosse tosse, non ce l'ho fatta…"
  },
  AvgDialog_149754_Content_25 = {
    Text = "Il massacro… i corpi… la peste nera… <Shake:La principessa… lei… lei ha scelto da sola, tosse tosse tosse tosse!>"
  },
  AvgDialog_149754_Content_26 = {
    Text = "Qualunque ricordo doloroso avesse rievocato, potevi sentirlo raggomitolarsi su se stesso, come una lumaca cosparsa di sale."
  },
  AvgDialog_149754_Content_27 = {
    Text = "<Shake:Sono stato io… non sono riuscito a proteggerli… tutti perduti… tutti andranno perduti…>"
  },
  AvgDialog_149754_Content_28 = {
    Text = "<Shake:Un tempo… volevo diventare un cavaliere…>"
  },
  AvgDialog_149754_Content_29 = {
    Text = "<Shake:Ma… ora… chi… sono io…>"
  },
  AvgDialog_149754_Content_3 = {
    Text = "Fermatevi! I mostri siete voi! Non scappate!!"
  },
  AvgDialog_149754_Content_30 = {
    Text = "Il passato è passato, e il presente è presente. Adesso hai anche tu una principessa, e devi ancora proteggermi."
  },
  AvgDialog_149754_Content_31 = {
    Text = "Rimase in silenzio a lungo, poi si mosse."
  },
  AvgDialog_149754_Content_32 = {
    Text = "<Shake:Posami, tosse tosse tosse, giù.>"
  },
  AvgDialog_149754_Content_33 = {
    Text = "Sono il più debole… il più inutile…"
  },
  AvgDialog_149754_Content_34 = {
    Text = "Quello che dovrebbe… restare indietro… rimanere nel… dimenticato… passato…"
  },
  AvgDialog_149754_Content_35 = {
    Text = "Impossibile! Non hai ancora mantenuto la tua promessa — stai cercando di rimangiartela?"
  },
  AvgDialog_149754_Content_36 = {
    Text = "La marea crescente ti lambiva le ginocchia mentre ti facevi strada a fatica nel buio. Rocce taglienti ti incidevano i polpacci, le ferite intorpidite dall'acqua salata. Stringevi i denti senza emettere alcun suono di dolore."
  },
  AvgDialog_149754_Content_37 = {
    Text = "Le tue parole venivano strappate via da ansiti affannosi. Forzavi ogni sillaba fuori dalla gola con sforzo — finire una frase, fare un passo, come se li usassi per trascinarti avanti."
  },
  AvgDialog_149754_Content_38 = {
    Text = "Tu sei il cavaliere che ho scelto. Se ti lascio indietro, come farà la principessa, da sola, a sconfiggere il mostro e a completare l'avventura?"
  },
  AvgDialog_149754_Content_39 = {
    Text = "… È solo una storia."
  },
  AvgDialog_149754_Content_4 = {
    Text = "Ansiosa e furiosa, scagliasti con tutta la tua forza il fagotto che stringevi tra le braccia. Era pieno zeppo, e il nodo allentato si disfece in aria — gli oggetti di qualcuno si sparsero ovunque: una candela, un pettine, una piccola statuetta di pietra… e il calice."
  },
  AvgDialog_149754_Content_40 = {
    Text = "Tutto, è una storia."
  },
  AvgDialog_149754_Content_41 = {
    Text = "Ieri, è la storia di oggi, oggi è, la storia di domani. Alcune, sono svanite, altre, continueranno. Ma non può, non esserci una storia."
  },
  AvgDialog_149754_Content_42 = {
    Text = "Quindi, vai a trovare, l'Isola delle Mele. Vai, hoo, hoo… vai a completare, la nostra storia."
  },
  AvgDialog_149754_Content_5 = {
    Text = "La luce dorata rotolò e si alzò in volo sopra la palude di ombre, colpì la parete di pietra, rimbalzò due volte sul suolo e infine si fermò — perfettamente — ai piedi del signore."
  },
  AvgDialog_149754_Content_6 = {
    Text = "Lo guardasti alzare una mano per fermare le guardie, poi chinarsi lui stesso a raccogliere la piccola coppa dorata. Passò il pollice lungo i motivi sulla sua superficie, come se stesse ricordando qualcosa, e si voltò a guardare indietro con uno sguardo colmo di scherno."
  },
  AvgDialog_149754_Content_7 = {
    Text = "Poi si trasformò rapidamente in terrore."
  },
  AvgDialog_149754_Content_8 = {
    Text = "…Prima che il castello crollasse completamente in macerie, seppellendo le ombre, il drago e le reliquie insieme, il tuo cavaliere ti trascinò nel passaggio segreto."
  },
  AvgDialog_149754_Content_9 = {
    Text = "Era completamente esausto, incapace persino di stare in piedi. Gli stringesti il braccio forte, sforzandoti di muovere i piedi, come se portassi un pesante sacco di grano."
  },
  AvgDialog_149755_Content_1 = {
    Text = "Isola della Mela"
  },
  AvgDialog_149755_Content_10 = {
    Text = "La ferita alla gamba non era mai guarita. Anzi, era diventata ancora più dolorosa con i giorni di pioggia incessante, la gamba gonfia sotto il ginocchio come una carota — non riuscivi a fare un solo passo. Negli ultimi giorni, Ogier ti aveva portato in spalla attraverso montagne e valli."
  },
  AvgDialog_149755_Content_100 = {
    Text = "Vostra Altezza, vi prego di non piangere per me. Ci sono già fin troppi mostri. L'unica cosa che posso fare per voi è proteggere il paradiso che appartiene all'umanità, che appartiene a voi. Questo è il mio dovere, e la mia espiazione."
  },
  AvgDialog_149755_Content_101 = {
    Text = "Non sto camminando verso una fine. La attraverserò, poiché ho già ricevuto l'alba."
  },
  AvgDialog_149755_Content_102 = {
    Text = "Continuerò a vegliarvi da dove sorge il sole."
  },
  AvgDialog_149755_Content_103 = {
    Text = "Le ombre si riversarono avanti al posto del sangue. Chiunque mettesse piede in quel torrente ruggente spariva in un batter d'occhio, eppure l'ombra non scomparve."
  },
  AvgDialog_149755_Content_104 = {
    Text = "L'ombra si contorceva, l'ombra ribolliva, l'ombra si condensava in uno scudo, in un muro, e infine in una grande diga. Fissasti lo sguardo nell'oscurità più profonda, finché il carro trainato dai buoi non svoltò un angolo e non riuscisti più a vedere la superficie del fiume."
  },
  AvgDialog_149755_Content_105 = {
    Text = "Il tuo cavaliere scomparve senza lasciare traccia da quel giorno in poi. Aveva mantenuto solo metà della sua promessa, eppure lasciò dietro di sé un'ultima parola straordinariamente astuta — una che ti faceva attendere il domani con speranza, anche mentre ti addormentavi tra le lacrime."
  },
  AvgDialog_149755_Content_106 = {
    Text = "Poiché un nuovo sole sarebbe sorto allora, giorno dopo giorno, senza mai cambiare."
  },
  AvgDialog_149755_Content_11 = {
    Text = "Tieni, l'ho appena raccolta."
  },
  AvgDialog_149755_Content_12 = {
    Text = "Come per offrirti un po' di conforto, ti premette un frutto in mano. Ne mordesti un boccone assonnato, e fu solo quando un'acuta acidità si diffuse dalle radici dei denti che capisti di cosa si trattasse."
  },
  AvgDialog_149755_Content_13 = {
    Text = "…Una mela?"
  },
  AvgDialog_149755_Content_14 = {
    Text = "Sì, poco fa siamo passati attraverso un meleto."
  },
  AvgDialog_149755_Content_15 = {
    Text = "Una mela… L'Isola delle Mele, siamo arrivati?"
  },
  AvgDialog_149755_Content_16 = {Text = "Quasi."},
  AvgDialog_149755_Content_17 = {
    Text = "Svolse le bende e applicò la medicina a base di erbe sulla ferita, poi la fasciò di nuovo, strato dopo strato. Studiasti la sua espressione e sentisti che non era quella di chi attende qualcosa con impazienza."
  },
  AvgDialog_149755_Content_18 = {
    Text = "Vuoi insistere, ma un coro di abbai ti interrompe — dapprima lontano, poi sempre più vicino."
  },
  AvgDialog_149755_Content_19 = {
    Text = "Aspetta, non correre così veloce! Dove stai andando? Non è la strada per tornare al villaggio — ah!"
  },
  AvgDialog_149755_Content_2 = {
    Text = "……svegliati……"
  },
  AvgDialog_149755_Content_20 = {
    Text = "Un feroce cane da pastore sbuca dalla vegetazione, abbaiando forte per scacciare gli intrusi. La ragazza che gli corre dietro vi scorge e lancia un grido involontario, il cesto di vimini tra le sue mani che cade a terra."
  },
  AvgDialog_149755_Content_21 = {
    Text = "È Ogier. Cicatrici scure e sporche gli solcano il viso, come una bambola di pezza strappata e ricucita alla rinfusa, evocando ogni sorta di leggenda terrificante."
  },
  AvgDialog_149755_Content_22 = {
    Text = "Lui e la ragazza si fissano in silenzio, poi lui si alza e si tira su il cappuccio."
  },
  AvgDialog_149755_Content_23 = {Text = "Andiamo."},
  AvgDialog_149755_Content_24 = {
    Text = "No… no, non volevo — aspetta, ti prego!"
  },
  AvgDialog_149755_Content_25 = {
    Text = "Ogier ha appena mosso qualche passo con te in spalla quando la ragazza li segue affannosamente."
  },
  AvgDialog_149755_Content_26 = {
    Text = "Non andare! Non intendevo quello. Nel villaggio ci sono molti malati — lascia che ti porti da loro!"
  },
  AvgDialog_149755_Content_27 = {Text = "Malati?"},
  AvgDialog_149755_Content_28 = {
    Text = "Sì, tutti lebbrosi. All'inizio erano solo lebbrosi. Poi è arrivato l'esercito — ha distrutto innumerevoli villaggi, ma non si è mai avvicinato alla colonia dei lebbrosi — così chi non aveva più un posto dove andare è venuto qui. Io ero una di loro."
  },
  AvgDialog_149755_Content_29 = {
    Text = "Non preoccuparti, tutti ci hanno fatto l'abitudine. A parte l'aspetto diverso, non siamo poi così diversi dagli altri — mangiamo allo stesso modo, dormiamo allo stesso modo, lavoriamo allo stesso modo… La lebbra non è neanche lontanamente spaventosa quanto l'esercito. Ci si abitua."
  },
  AvgDialog_149755_Content_3 = {
    Text = "……pioggia……riposa……svegliati……"
  },
  AvgDialog_149755_Content_30 = {
    Text = "Mi dispiace, non avevo paura di voi — è solo che non avevo mai visto… Scusa! Tieni, prendi questo cesto di mele. Le ho raccolte io stessa, ti prometto che sono le più grandi e le più dolci!"
  },
  AvgDialog_149755_Content_31 = {
    Text = "Come dovrebbe essere il paradiso?"
  },
  AvgDialog_149755_Content_32 = {
    Text = "Nessun mostro, nessuna disperazione, nessun terrore indicibile, nessun occhio in agguato nell'oscurità. Non dover temere di non svegliarsi prima di addormentarsi. Una zuppa calda da bere ogni singolo giorno."
  },
  AvgDialog_149755_Content_33 = {
    Text = "Non conosci nessun altro posto che si avvicini di più al paradiso di questo."
  },
  AvgDialog_149755_Content_34 = {
    Text = "…Basta così."
  },
  AvgDialog_149755_Content_35 = {
    Text = "Un coltello affilato apre l'ascesso, raschiando via la carne marcia pezzo per pezzo. Un ferro rovente viene premuto sulla ferita che non smette di sanguinare. Il dolore bruciante strappa un grido soffocato dalla tua gola, e scoppi in un sudore freddo."
  },
  AvgDialog_149755_Content_36 = {
    Text = "È finita. Il panno infilato in bocca viene rimosso. Ansimi con tutta la forza che hai, quasi inghiottendo l'aria intera."
  },
  AvgDialog_149755_Content_37 = {
    Text = "Questa volta è diverso — lo sai. Lo stanno facendo per salvarti, e il tuo cavaliere è proprio qui accanto a te."
  },
  AvgDialog_149755_Content_38 = {
    Text = "Medicina. Portala via e falla bollire nell'acqua. Una volta all'alba, una volta al tramonto."
  },
  AvgDialog_149755_Content_39 = {
    Text = "Bene, grazie."
  },
  AvgDialog_149755_Content_4 = {
    Text = "Vieni svegliato dolcemente, la mente ancora annebbiata, e senti il leggero scrosciare della pioggia."
  },
  AvgDialog_149755_Content_40 = {
    Text = "Tirò fuori alcune monete come pagamento, ma il barbiere le rifiutò con un gesto. In un luogo tagliato fuori dal mondo, i prezzi dell'esterno non avevano alcun valore — le persone qui non vivevano per queste cose."
  },
  AvgDialog_149755_Content_41 = {
    Text = "<Small:Il cielo si è rasserenato…>"
  },
  AvgDialog_149755_Content_42 = {
    Text = "<Small:Ogier, voglio andare al frutteto di mele.>"
  },
  AvgDialog_149755_Content_43 = {
    Text = "Hai bisogno di riposarti."
  },
  AvgDialog_149755_Content_44 = {
    Text = "Portami lì. Ho fatto una grande scoperta… devo dirtela."
  },
  AvgDialog_149755_Content_45 = {
    Text = "Eccoci. Qual è questa grande scoperta?"
  },
  AvgDialog_149755_Content_46 = {
    Text = "Ah… ho capito — questa è l'Isola delle Mele. L'abbiamo già trovata."
  },
  AvgDialog_149755_Content_47 = {
    Text = "Il tuo cavaliere ti adagia su un tronco caduto che giace su un fianco, poi si inginocchia, sostenendo con cura la tua gamba ferita. Il suo sguardo è concentrato e preoccupato — evidentemente, la verità che hai appena realizzato non riesce a stupirlo."
  },
  AvgDialog_149755_Content_48 = {
    Text = "Ma questa non è un'isola."
  },
  AvgDialog_149755_Content_49 = {
    Text = "Nessuno ha mai detto che un'isola debba trovarsi in mare, vero? Finché non è collegata al mondo esterno, è un'isola."
  },
  AvgDialog_149755_Content_5 = {
    Text = "La pioggia è ricominciata. Non si era mai davvero fermata."
  },
  AvgDialog_149755_Content_50 = {
    Text = "E per di più, qui ci sono le fate."
  },
  AvgDialog_149755_Content_51 = {Text = "Le fate?"},
  AvgDialog_149755_Content_52 = {
    Text = "Sì, nel villaggio ci sono molte fate. Alcune hanno il volto dei leoni, altre le squame dei pesci, e altre ancora cambiano la pelle come i serpenti. Sono fate che vivono in una terra incantata."
  },
  AvgDialog_149755_Content_53 = {
    Text = "Fate… non mostri?"
  },
  AvgDialog_149755_Content_54 = {
    Text = "Certo che no! Come potrebbero mai essere la stessa cosa, fate e mostri?"
  },
  AvgDialog_149755_Content_55 = {
    Text = "I mostri mangiano le persone. Fanno di tutto pur di mangiarle — a volte uccidendole di netto con una lama, a volte tessendo menzogne per rinchiudere le persone e strappar loro la carne pezzo per pezzo."
  },
  AvgDialog_149755_Content_56 = {
    Text = "E non solo mangiandola da soli — la trasformano in zuppa, in carne stagionata, in pappa, e la danno da mangiare agli altri. La carne umana è ovunque. Morirai di fame se non la mangi, ma nel momento in cui lo fai, diventi un mostro. E così i mostri diventano sempre più numerosi."
  },
  AvgDialog_149755_Content_57 = {
    Text = "Gli umani non mangiano gli umani, e le fate non mangiano gli umani. Sull'Isola delle Mele, sono puri."
  },
  AvgDialog_149755_Content_58 = {
    Text = "E io? Non sono né umano né elfo. Le mie mani sono macchiate di sangue, e un demone dimora nel mio corpo — lo hai visto con i tuoi stessi occhi."
  },
  AvgDialog_149755_Content_59 = {
    Text = "Perché non hai paura?"
  },
  AvgDialog_149755_Content_6 = {
    Text = "La foresta aveva dato rifugio agli esiliati in fuga. La notizia del massacro dei mostri al castello era giunta alle orecchie dei sovrani, i manifesti di ricerca erano stati affissi in ogni città, e sia l'ordine cavalleresco della Chiesa che i mercenari erano stati mobilitati — non avevate altra scelta che procedere giorno e notte."
  },
  AvgDialog_149755_Content_60 = {
    Text = "Perché dovrei avere paura? Dal primissimo momento in cui lo hai visto, sapevi che doveva essere un cavaliere. Attraverso le ombre che si aggrappavano a lui e non svanivano, riuscivi comunque a vedere il cavaliere dentro di lui — così chiaramente, così inconfondibilmente, come se lo avessi già visto da qualche parte."
  },
  AvgDialog_149755_Content_61 = {
    Text = "Cosa occorre per diventare un vero cavaliere? Lealtà, coraggio, compassione, sacrificio, e…"
  },
  AvgDialog_149755_Content_62 = {
    Text = "L'investitura di un signore."
  },
  AvgDialog_149755_Content_63 = {
    Text = "Ehm… Allora, con questo dichiaro, in nome di una principessa — ti nomino cavaliere."
  },
  AvgDialog_149755_Content_64 = {
    Text = "Hai sconfitto il mostro, conquistato il Santo Graal, resistito al demone e protetto me. Hai mantenuto la tua promessa e hai condotto la tua principessa all'Isola delle Mele."
  },
  AvgDialog_149755_Content_65 = {
    Text = "Non importa chi fossi un tempo, nella nostra storia sei un cavaliere — e nessuna principessa temerebbe mai il proprio cavaliere."
  },
  AvgDialog_149755_Content_66 = {
    Text = "Sarai sempre il mio cavaliere."
  },
  AvgDialog_149755_Content_67 = {
    Text = "Il tuo cavaliere rimase immobile, una mano che stringeva il mantello, come se desiderasse nascondersi nella sua ampia ombra. Il mantello celava le tracce dell'oscurità, e solo lui sapeva quanto miserabile fosse la verità sotto quel travestimento."
  },
  AvgDialog_149755_Content_68 = {
    Text = "Un esile ramo ancora imperlato di pioggia si posò dolcemente sulla sua spalla. Un desiderio così lontano da essere quasi dimenticato si avverò all'improvviso — eppure ciò che fece tremare la sua stessa anima non era gioia."
  },
  AvgDialog_149755_Content_69 = {Text = "Era Paura."},
  AvgDialog_149755_Content_7 = {
    Text = "C'è un villaggio poco più avanti. Vado a barattare del cibo e delle medicine. Riposati qui, e ci rimetteremo in cammino quando la pioggia si fermerà."
  },
  AvgDialog_149755_Content_70 = {
    Text = "Fiamme di terrore si levarono dall'abisso senza fondo — sotto i suoi piedi, sopra la sua testa, negli occhi terrorizzati dietro le crepe. Scottanti, ardenti, schizzanti da colli recisi, sgorganti dai petti. Le fiamme si contorcevano così violentemente che le ombre impazzivano insieme a loro. Fuoco e ombra erano una cosa sola."
  },
  AvgDialog_149755_Content_71 = {
    Text = "Fu un massacro — senza onore, senza giustizia, uguale per tutti. Il finale intriso di sangue squarciò le belle bugie che lo avevano adornato; la morte non era altro che morte. Non riusciva a ricordare come fosse sopravvissuto. Forse non era sopravvissuto affatto."
  },
  AvgDialog_149755_Content_72 = {
    Text = "Un mostro caduto, uno spettro assetato di vendetta — la sua ricerca era come portare legna per combattere un incendio. L'Anima Perduta scivolava inesorabilmente verso la rovina, senza mai credere che la redenzione potesse appartenergli."
  },
  AvgDialog_149755_Content_73 = {
    Text = "<Shake:Ma… ma…>"
  },
  AvgDialog_149755_Content_74 = {
    Text = "Ogier, Ogier? Ehi, mi stai ascoltando? Ho finito — tocca a te."
  },
  AvgDialog_149755_Content_75 = {Text = "..."},
  AvgDialog_149755_Content_76 = {
    Text = "Sì. Sono disposto."
  },
  AvgDialog_149755_Content_77 = {
    Text = "In nome della mia patria perduta, io, Ogier, figlio della Casa di Dansk, ti giuro lealtà e riverenza."
  },
  AvgDialog_149755_Content_78 = {
    Text = "Ti offro il mio scudo e la mia lancia, insieme alla fede che ho macchiato, alla mia paura duratura e al mio cuore spezzato. Avevo perso il mio nome nella lunga notte — è stata la tua voce a illuminare l'alba."
  },
  AvgDialog_149755_Content_79 = {
    Text = "Chi ha infranto un giuramento non è più degno di parlare di fede — ma se il tuo sguardo è ancora disposto a soffermarsi, allora ti apparterrò, fino all'ultimo respiro della mia vita."
  },
  AvgDialog_149755_Content_8 = {
    Text = "<Small:Capito… torna presto.>"
  },
  AvgDialog_149755_Content_80 = {
    Text = "Le storie non iniziano sempre con colori vivaci — possono anche cominciare dalle rive della disperazione."
  },
  AvgDialog_149755_Content_81 = {
    Text = "Anche se la fine è eterna, proiettando la sua pesante ombra su ogni cosa, prima di raggiungerla hai ancora la libertà di scegliere ciò che diventerà il tuo destino."
  },
  AvgDialog_149755_Content_82 = {
    Text = "Una brezza leggera, il caldo sole, il profumo di mele mature, la nebbia che si leva dalla foresta come nuvole — il mondo è bello come un dipinto, e sorridi di gioia, come se un finale perfetto fosse finalmente arrivato."
  },
  AvgDialog_149755_Content_83 = {
    Text = "Ma sai che la storia continuerà. Continua sempre."
  },
  AvgDialog_149755_Content_84 = {
    Text = "<Big:Quante persone non si sono ancora svegliate? Andate a svegliarle subito — l'alluvione sta arrivando!>"
  },
  AvgDialog_149755_Content_85 = {
    Text = "L'oscurità della notte alimentava la furia della tempesta. Le gocce di pioggia cadevano come pietre, il fiume torbido ruggiva oltre entrambe le rive, e l'acqua dell'alluvione aveva già superato le ginocchia."
  },
  AvgDialog_149755_Content_86 = {
    Text = "Le figure correvano avanti e indietro, urlando a gran voce, battendo con tutta la loro forza su ogni porta e finestra — ma gli sprite si muovevano lentamente, e una volta caduti non riuscivano più ad alzarsi, incapaci di guadare da soli il terreno irregolare e allagato."
  },
  AvgDialog_149755_Content_87 = {
    Text = "\"BOOM!!\" Un fragore assordante scosse il tuo cuore, ma con la notte che incombeva, le persone si guardavano intorno confuse, senza sapere cosa stesse per crollare."
  },
  AvgDialog_149755_Content_88 = {
    Text = "<Big:No — è la diga!!>"
  },
  AvgDialog_149755_Content_89 = {
    Text = "<Big:Correte! Chiunque possa muoversi, correte — non c'è tempo!>"
  },
  AvgDialog_149755_Content_9 = {
    Text = "Per quanto odiassi essere lasciato indietro, tutto il tuo corpo bruciava per una febbre spaventosa, e non avevi più la forza di stare al passo con lui."
  },
  AvgDialog_149755_Content_90 = {
    Text = "Suppliche, gemiti, pianti — il paradiso dei tuoi sogni vacillava sull'orlo della rovina, sul punto di essere inghiottito dalla pioggia senza fine, lasciando solo macerie. E tu non riuscivi nemmeno a camminare da solo, impotente, incapace di fare altro che guardare."
  },
  AvgDialog_149755_Content_91 = {
    Text = "Il tuo cavaliere ti sollevò sul predellino della carrozza, slacciò il suo mantello e te lo avvolse strettamente intorno."
  },
  AvgDialog_149755_Content_92 = {
    Text = "Vostra Altezza, chiedo umilmente il vostro permesso di andare a contenere la furia dell'alluvione."
  },
  AvgDialog_149755_Content_93 = {
    Text = "Puoi fermare l'alluvione?"
  },
  AvgDialog_149755_Content_94 = {
    Text = "Farò tutto ciò che è in mio potere."
  },
  AvgDialog_149755_Content_95 = {
    Text = "Puoi tornare?"
  },
  AvgDialog_149755_Content_96 = {
    Text = "…Farò tutto ciò che è in mio potere."
  },
  AvgDialog_149755_Content_97 = {
    Text = "<Big:No — no, mi rifiuto! Non lo permetterò!>"
  },
  AvgDialog_149755_Content_98 = {
    Text = "Andiamo — adesso… Ce ne sarà un altro. L'Isola delle Mele, l'Isola delle Zucche, qualsiasi cosa — ce ne sarà sempre un altro!"
  },
  AvgDialog_149755_Content_99 = {
    Text = "Stringesti con tutta la tua forza l'orlo dei suoi abiti, eppure sapevi in cuor tuo che era inutile — aveva già fatto la sua scelta. Ti si inchinò, proprio come il più gentile degli eroi e il più leale dei cavalieri in ogni storia mai raccontata."
  },
  AvgDialog_149756_Content_1 = {
    Text = "Principessa"
  },
  AvgDialog_149756_Content_10 = {
    Text = "Vuoi urlare, ridere, imprecare, gridare, ma uno straccio imbevuto d'olio ti viene ficcato in bocca. La cosa puzzolente e unta preme forte contro la radice della tua lingua, e a parte i conati di vomito, non riesci a emettere un solo suono."
  },
  AvgDialog_149756_Content_11 = {
    Text = "Guardatela, trema — il demonio si agita dentro di lei. Questo è il suo vero, orribile volto."
  },
  AvgDialog_149756_Content_12 = {
    Text = "Misericordioso Signore, Ti supplico di dissigillare la bocca che il diavolo ha legato, e di lasciarle confessare i suoi peccati con le sue stesse labbra — se nel suo cuore rimane ancora un qualche desiderio di salvezza."
  },
  AvgDialog_149756_Content_13 = {
    Text = "Il bavaglio viene strappato via bruscamente, e tu tossisci e ansimi due volte, cercando aria, con la saliva che cola dall'angolo della bocca."
  },
  AvgDialog_149756_Content_14 = {
    Text = "Mostri armati di asce e forconi formano un cerchio intorno a te, osservandoti con occhi diffidenti. Più lontano, lungo i bordi dei campi, tra i rami, dietro finestre socchiuse, si nascondono ancora più occhi."
  },
  AvgDialog_149756_Content_15 = {
    Text = "Parla, bambina! Dichiara il tuo pentimento davanti al Signore — questo è il tuo ultimo momento per essere risparmiata dalla dannazione eterna!"
  },
  AvgDialog_149756_Content_16 = {
    Text = "<Small:…Mostri.>"
  },
  AvgDialog_149756_Content_17 = {
    Text = "Cosa? Cosa ha detto?"
  },
  AvgDialog_149756_Content_18 = {
    Text = "<BigShake:Mostri! Mostri! Mo— tosse tosse tosse!>"
  },
  AvgDialog_149756_Content_19 = {
    Text = "Le tue parole fanno a pezzi la loro farsa accuratamente costruita, e i volti dei mostri si contorcono in espressioni di panico. Provi una soddisfazione feroce e amara."
  },
  AvgDialog_149756_Content_2 = {
    Text = "I mostri hanno divorato la mia famiglia. Ora intendono divorare me."
  },
  AvgDialog_149756_Content_20 = {
    Text = "Una maledizione — è una maledizione! Maledetta strega!"
  },
  AvgDialog_149756_Content_21 = {
    Text = "Rimettile il bavaglio!"
  },
  AvgDialog_149756_Content_22 = {
    Text = "Signore… proteggici…"
  },
  AvgDialog_149756_Content_23 = {
    Text = "<Big:Bruciatela! Bruciatela!>"
  },
  AvgDialog_149756_Content_24 = {
    Text = "<Big:Folletti! Creature delle paludi! Ghoul! Mostri! Siete tutti mo— aaaaaah——!!>"
  },
  AvgDialog_149756_Content_25 = {
    Text = "Il diavolo ha già reclamato la sua anima. Per proteggere il nostro villaggio dal danno della magia oscura, questa cosa impura deve essere eliminata."
  },
  AvgDialog_149756_Content_26 = {
    Text = "Che il fuoco sacro bruci via i suoi peccati, che il Signore ci conceda la pace."
  },
  AvgDialog_149756_Content_27 = {
    Text = "Fascio dopo fascio di legna secca viene ammucchiato ai tuoi piedi, le spine lacerano la tua pelle nuda, e tu ti contorci dal dolore, le catene di ferro che tintinnano e risuonano."
  },
  AvgDialog_149756_Content_28 = {
    Text = "Questo ti vale ulteriori scherni e insulti, insieme a una corda stretta ancora più forte."
  },
  AvgDialog_149756_Content_29 = {
    Text = "Il fuoco si accende."
  },
  AvgDialog_149756_Content_3 = {
    Text = "Il crepuscolo è un presagio di qualcosa che torna in vita. Il sole al tramonto è come una chiazza rossa malsana, e il cielo si gonfia di sangue livido."
  },
  AvgDialog_149756_Content_30 = {
    Text = "Ti scacciamo… spirito immondo, eretico apostata… come fumo disperso dal vento, come cera sciolta dal fuoco…"
  },
  AvgDialog_149756_Content_31 = {
    Text = "Caduto, persecutore, esiliato — in nome di Sua Maestà, ti ordino: trema, sottomettiti, fuggi—"
  },
  AvgDialog_149756_Content_32 = {
    Text = "La sua voce si interrompe di colpo, come se fosse stata recisa nettamente da un paio di forbici."
  },
  AvgDialog_149756_Content_33 = {
    Text = "Forzi i tuoi occhi brucianti ad aprirsi bene, e attraverso il fumo nero che si spande, vedi uno sconosciuto in piedi accanto al sacerdote."
  },
  AvgDialog_149756_Content_34 = {
    Text = "Quando è apparso? Non lo sai. Guardi verso i mostri rimasti — se ne stanno immobili, come una folla di rane a bocca aperta."
  },
  AvgDialog_149756_Content_35 = {
    Text = "Il sacerdote ha convulsioni incontrollabili, entrambe le mani che stringono la gola, il sangue che filtra tra le dita e schizza dalla bocca, il viso dello stesso colore del cielo. Crolla."
  },
  AvgDialog_149756_Content_36 = {
    Text = "<Big:Ah——!!>"
  },
  AvgDialog_149756_Content_37 = {
    Text = "Urla, più forti di qualsiasi fischio, e le lingue di fuoco tremano insieme a loro."
  },
  AvgDialog_149756_Content_38 = {
    Text = "Sangue… così tanto sangue… qualcuno è stato ucciso! Aiuto, aiuto — il mostro ha ucciso qualcuno!"
  },
  AvgDialog_149756_Content_39 = {
    Text = "No, no… un demonio, è un demonio! Quella strega ha evocato qualcosa dall'inferno! Signore, perdonaci…"
  },
  AvgDialog_149756_Content_4 = {
    Text = "Il fuoco non è ancora stato acceso, eppure gli alberi morti si sono già contorti in forme distorte — la loro postura di disperazione, come se persino la luce quotidiana del giorno fosse un'arsura insopportabile."
  },
  AvgDialog_149756_Content_40 = {
    Text = "Il tuo cuore batte furiosamente. Sai chi è lui. Sai che la tua vita non finirà oggi — non è altro che un preludio, un intermezzo, tutto per annunciare il suo arrivo."
  },
  AvgDialog_149756_Content_41 = {
    Text = "Colma di ardente speranza, agiti il corpo disperatamente, emettendo gemiti soffocati, nel disperato tentativo di fargli posare lo sguardo su di te — quasi dimenticando le catene roventi."
  },
  AvgDialog_149756_Content_43 = {
    Text = "Una mano guantata ti trascina fuori dal rogo. Le gambe ti cedono sotto e crolli a terra senza controllo, tossendo e singhiozzando, lacrime e muco che si mescolano insieme."
  },
  AvgDialog_149756_Content_44 = {
    Text = "<Shake:Tosse tosse tosse tosse tosse tosse tosse——!! Aspetta — tosse tosse tosse tosse — aspetta! Non andare!>"
  },
  AvgDialog_149756_Content_45 = {
    Text = "Prima che possa girarsi e andarsene, afferri freneticamente il suo mantello."
  },
  AvgDialog_149756_Content_46 = {
    Text = "Apparentemente colto di sorpresa dalla tua azione, il suo cappuccio scivola a metà, rivelando il viso di un ragazzo giovane."
  },
  AvgDialog_149756_Content_47 = {
    Text = "Lasciami andare."
  },
  AvgDialog_149756_Content_48 = {
    Text = "Sei abbastanza sveglio da distinguere un bluff da un avvertimento. Ricordando la fine orribile del sacerdote poco fa, un brivido ti percorre la schiena."
  },
  AvgDialog_149756_Content_49 = {
    Text = "Ma poi vedi il suo volto — senza alcun dubbio, il nobile cavaliere delle storie dovrebbe avere esattamente quest'aspetto. Deve essere venuto per te, e hai persino la sensazione che quegli occhi e quelle sopracciglia ti siano in qualche modo familiari."
  },
  AvgDialog_149756_Content_5 = {
    Text = "<BigShake:Non lasciatevi ingannare dal suo aspetto!> Il volto di una bambina è solo un travestimento — un diavolo abita in quel corpo. I suoi peccati, il Signore li ha visti tutti."
  },
  AvgDialog_149756_Content_50 = {
    Text = "Sì, devi averlo visto da qualche parte prima — in un sogno, una maledizione, o una profezia. Come potresti altrimenti spiegare questo improvviso slancio di coraggio?"
  },
  AvgDialog_149756_Content_51 = {
    Text = "<Shake:No… colpo colpo colpo, non puoi andartene.>"
  },
  AvgDialog_149756_Content_52 = {Text = "Perché?"},
  AvgDialog_149756_Content_53 = {
    Text = "Perché — colpo colpo — perché sei venuto a salvarmi, come potresti lasciarmi indietro?"
  },
  AvgDialog_149756_Content_54 = {
    Text = "Sei già salva. Torna alla vita che ti appartiene."
  },
  AvgDialog_149756_Content_55 = {
    Text = "Non c'è nessuna vita qui che mi appartenga. Ci sono mostri ovunque, non fanno altro che afferrare le persone e mangiarle — lo hai già visto."
  },
  AvgDialog_149756_Content_56 = {
    Text = "Non mi riguarda."
  },
  AvgDialog_149756_Content_57 = {
    Text = "Come può non riguardarti? Ti stavo chiaramente aspettando da sempre."
  },
  AvgDialog_149756_Content_58 = {
    Text = "Aspettavi me? Tu… mi conosci?"
  },
  AvgDialog_149756_Content_59 = {
    Text = "Certo. Sei il mio cavaliere."
  },
  AvgDialog_149756_Content_6 = {
    Text = "È una ladra, una bugiarda, una serva delle tenebre. La calamità scorre dalle sue labbra, il suo veleno ha contaminato pozzi e fiumi, così il bestiame è caduto morto nei recinti e i fedeli sono stati colpiti da terribili malattie."
  },
  AvgDialog_149756_Content_60 = {
    Text = "Shock, sconcerto, panico, angoscia — un turbine di espressioni invade il suo volto tutto in una volta. Strappa la mano via da te come se si ritraesse da un serpente velenoso, e preme la sua corta spada macchiata di sangue contro la tua gola."
  },
  AvgDialog_149756_Content_61 = {Text = "Chi sei!"},
  AvgDialog_149756_Content_62 = {
    Text = "Io — sono una principessa! Esatto, sono una principessa. Sono stata rapita dai mostri e ti stavo aspettando perché venissi a salvarmi!"
  },
  AvgDialog_149756_Content_63 = {
    Text = "Non dubitare di me — se non fossi una principessa, perché il Cielo avrebbe mandato un cavaliere a salvarmi?"
  },
  AvgDialog_149756_Content_64 = {Text = "..."},
  AvgDialog_149756_Content_65 = {
    Text = "La corta spada scivola nel fodero. Si alza e si addentra nella fitta foresta senza dirti un'altra parola."
  },
  AvgDialog_149756_Content_66 = {
    Text = "Aspetta, dove stai andando? Io — colpo — vengo con te."
  },
  AvgDialog_149756_Content_67 = {
    Text = "<Shake:Fermati! Colpo colpo — in nome della principessa, ti ordino di fermarti!>"
  },
  AvgDialog_149756_Content_68 = {
    Text = "Sebbene sia straordinariamente agile, tu hai il vantaggio di conoscere questa foresta come il palmo della tua mano."
  },
  AvgDialog_149756_Content_69 = {
    Text = "Inoltre, non hai nessun altro posto dove andare — solo inseguire, e inseguire, anche se crolli qui nella foresta e diventi cibo per le bestie."
  },
  AvgDialog_149756_Content_7 = {
    Text = "Siete tutti testimoni — quante volte è entrata nella foresta, scomparsa senza lasciare traccia, e tornata come se nulla fosse accaduto? Questa è la prova della stregoneria!"
  },
  AvgDialog_149756_Content_70 = {
    Text = "<Shake:Ansima… ansima… aspetta, io — conosco le regole.>"
  },
  AvgDialog_149756_Content_71 = {
    Text = "Ho un posto dove andare. Scortami lì, e riceverai onore e ricompensa."
  },
  AvgDialog_149756_Content_72 = {
    Text = "Non ne ho bisogno."
  },
  AvgDialog_149756_Content_73 = {
    Text = "Ne hai bisogno — almeno in questo momento, hai bisogno di qualcuno che ti guidi fuori di qui, no?"
  },
  AvgDialog_149756_Content_74 = {
    Text = "Non rispose, ma i suoi passi si fermarono gradualmente."
  },
  AvgDialog_149756_Content_75 = {
    Text = "Dove stai andando?"
  },
  AvgDialog_149756_Content_76 = {
    Text = "Hmm… ah già, l'Isola delle Mele — ne hai sentito parlare? Un paradiso dove non c'è bisogno di piantare nulla, nessuno si ammala e l'inverno non arriva mai. È lì che sono diretta."
  },
  AvgDialog_149756_Content_77 = {
    Text = "Non ne ho mai sentito parlare. Dov'è?"
  },
  AvgDialog_149756_Content_78 = {
    Text = "La fata non mi ha detto la direzione, ma ha detto che l'avrei trovata un giorno — proprio come ha fatto lei. Possiamo camminare e cercare allo stesso tempo. Dopotutto, le grandi avventure sono sempre piene di sfide, no?"
  },
  AvgDialog_149756_Content_79 = {
    Text = "Il mantello nero si dissolse nell'oscurità della notte. Lui stava dietro un groviglio di arbusti selvatici, i suoi lineamenti indistinti."
  },
  AvgDialog_149756_Content_8 = {
    Text = "<SmallShake:La peste… una strega… sì, è colpa della strega… la maledizione della strega…>"
  },
  AvgDialog_149756_Content_80 = {
    Text = "Ti avvicinasti a lui con una lentezza estenuante, come se temessi di spaventare un lupo selvatico."
  },
  AvgDialog_149756_Content_81 = {
    Text = "Fermati. Resta lì. Non avvicinarti."
  },
  AvgDialog_149756_Content_82 = {
    Text = "Apri la strada."
  },
  AvgDialog_149756_Content_83 = {
    Text = "Significa che hai accettato, valoroso cavaliere?"
  },
  AvgDialog_149756_Content_84 = {Text = "..."},
  AvgDialog_149756_Content_85 = {
    Text = "Non sono un cavaliere."
  },
  AvgDialog_149756_Content_86 = {
    Text = "Lo sei. Da questo momento in poi, sei il mio fedele cavaliere."
  },
  AvgDialog_149756_Content_87 = {
    Text = "Un cavaliere mantiene le sue promesse — finché non raggiungiamo l'Isola delle Mele, devi proteggermi. Camminerai davanti e sgombererai per me spine e rovi. Se qualche mostro ci insegue, lo scaccerai, e inoltre…"
  },
  AvgDialog_149756_Content_88 = {
    Text = "Dove stai andando? Non hai ancora giurato! Se osi mentire e ingannare la tua principessa, verrai catturato e divorato dai mostri. Giura prima."
  },
  AvgDialog_149756_Content_89 = {
    Text = "Ehi! Non andare — aspettami — conosco la strada!"
  },
  AvgDialog_149756_Content_9 = {
    Text = "Una strega che non ha ancora dieci anni? Nemmeno un pazzo potrebbe inventare una bugia simile."
  },
  AvgDialog_149757_Content_1 = {Text = "Tumulo"},
  AvgDialog_149757_Content_10 = {
    Text = "<Shake:Ah, ah... dove sei... mio cavaliere...>"
  },
  AvgDialog_149757_Content_11 = {
    Text = "Ricordasti la voce che circolava, e la tua preoccupazione si fece più profonda. Non avresti mai potuto permettere che il tuo unico cavaliere venisse sconfitto da un demonio. Avresti ricordato il suo nome — lo ricordavi già."
  },
  AvgDialog_149757_Content_12 = {
    Text = "Ogier... esatto, Ogier! Dove sei! <Big:O — gi — er —>"
  },
  AvgDialog_149757_Content_13 = {
    Text = "Un grido di angoscia squarciò il sipario di pioggia — più simile a una bestia ferita che a un essere umano. Ti lanciasti immediatamente di corsa verso la fonte del suono."
  },
  AvgDialog_149757_Content_14 = {
    Text = "Smettila di nasconderti! Ti vedo già!"
  },
  AvgDialog_149757_Content_15 = {
    Text = "Vattene! Non — ah — non avvicinarti!!"
  },
  AvgDialog_149757_Content_16 = {
    Text = "La luce della lampada tremolava e vacillava, incapace di respingere l'oscurità che si stringeva da ogni lato. Il tuo cavaliere era stato messo alle strette, la sua schiena tesa come una balestra in posizione di tiro."
  },
  AvgDialog_149757_Content_17 = {
    Text = "Stai zitta! Non ho dimenticato! Non è — no, io non ho mai — non dimenticherò!"
  },
  AvgDialog_149757_Content_18 = {
    Text = "<Shake:Li vendicherò... devo vendicarli... occhio per occhio, dente per dente...>"
  },
  AvgDialog_149757_Content_19 = {
    Text = "No, non è vero, stai mentendo! La principessa non direbbe mai una cosa del genere, la principessa, lei —"
  },
  AvgDialog_149757_Content_2 = {
    Text = "Avevi sentito dire una volta che il nome di ogni persona è una maledizione."
  },
  AvgDialog_149757_Content_20 = {
    Text = "<Big:Ugh — !!>"
  },
  AvgDialog_149757_Content_21 = {
    Text = "Le parole sconnesse furono troncate da un grido, come se qualcuno gli avesse conficcato una lancia nel petto. Inciampò e cadde in ginocchio, eppure l'ombra dietro di lui rimase in piedi — come un'armatura, come una gabbia."
  },
  AvgDialog_149757_Content_22 = {
    Text = "Sentisti un'ondata di panico. Sapevi che se non l'avessi fermata adesso, l'ombra sarebbe diventata la persona, e la persona sarebbe caduta nell'ombra."
  },
  AvgDialog_149757_Content_23 = {
    Text = "Svegliati! Smettila di ascoltarla — la tua principessa è proprio qui!!"
  },
  AvgDialog_149757_Content_24 = {
    Text = "<Shake:……@1@2Vostra Altezza… vi ho deluso?>"
  },
  AvgDialog_149757_Content_25 = {
    Text = "<Shake:Non sono fuggito, sei stata tu a dirmi di farlo——>No, non intendevo quello. Vi ho deluso. Non ho il diritto di chiedere perdono."
  },
  AvgDialog_149757_Content_26 = {
    Text = "<Shake:Vergogna… vergogna vergogna vergogna vergogna vergogna vergogna vergogna vergogna, la vergogna è l'unica cosa che possiedo…>"
  },
  AvgDialog_149757_Content_27 = {
    Text = "<Shake:Non sono un cavaliere, sono… sono…>"
  },
  AvgDialog_149757_Content_28 = {Text = "<Red:Chi?>"},
  AvgDialog_149757_Content_29 = {
    Text = "Perso nella confusione per un momento, alzò il viso per guardarti — se ancora lo si poteva chiamare viso."
  },
  AvgDialog_149757_Content_3 = {
    Text = "Se si è abbastanza incauti da perdere il proprio nome — che venga dimenticato da sé stessi o dagli altri — si diventa come una pecora smarrita dal gregge, privata di riparo, e il diavolo posarà su di essa i propri occhi."
  },
  AvgDialog_149757_Content_30 = {
    Text = "L'ombra aveva divorato la sua carne, lasciando scie simili ai percorsi di lumache striscianti. I suoi lineamenti erano chiazzati e in putrefazione, eppure ciò che trasudava dalle ferite era fango nero e viscoso."
  },
  AvgDialog_149757_Content_31 = {
    Text = "La risposta di chi stava aspettando? La pioggia gelida ti aveva congelato le labbra e la lingua. Restavi immobile nel fango, un tremito tardivo che si diffondeva per le tue membra."
  },
  AvgDialog_149757_Content_32 = {
    Text = "…A-aspetta, lo so! Tu sei——"
  },
  AvgDialog_149757_Content_33 = {
    Text = "<BigShake:No! Ogier!!>"
  },
  AvgDialog_149757_Content_34 = {
    Text = "Dal suo petto eruttò fango nero. Il tuo cavaliere esaurì in silenzio le ultime forze, crollando mollemente, come un guscio vuoto abbandonato, mentre le ombre gli giravano intorno ridendo e piangendo allo stesso tempo."
  },
  AvgDialog_149757_Content_35 = {
    Text = "Hai assistito a come una persona va in pezzi."
  },
  AvgDialog_149757_Content_36 = {
    Text = "Ogier! Sei Ogier! Lo so — ora ricordo! Il diavolo non può farti del male, ho già ricordato!"
  },
  AvgDialog_149757_Content_37 = {
    Text = "Svegliati! Riesci a sentirmi? Svegliati, non siamo ancora arrivati! Starai bene — Avalon, il diavolo non può raggiungere quel posto. Una volta che arriveremo ad Avalon, andrà tutto bene! Alzati, alzati adesso!"
  },
  AvgDialog_149757_Content_38 = {
    Text = "Il diluvio aveva trasformato la foresta in una pozza di palude marcia. Urlavi, tiravi, piangevi — solo per sprofondare tu stesso ancora di più. Non avevi idea di dove altro potresti fuggire."
  },
  AvgDialog_149757_Content_39 = {
    Text = "Così muore il mondo… sepolto vivo dalla disperazione."
  },
  AvgDialog_149757_Content_4 = {
    Text = "Forse il tuo cavaliere, come te, aveva avuto tutto sottratto dal mostro. Aveva perso ancora di più di te — non gli era rimasto nemmeno il nome."
  },
  AvgDialog_149757_Content_40 = {
    Text = "<SmallShake:Tosse… tosse, tosse…>"
  },
  AvgDialog_149757_Content_41 = {
    Text = "<SmallShake:Quando smette di piovere… vai al cimitero…>"
  },
  AvgDialog_149757_Content_42 = {
    Text = "Ogier! Sei ancora vivo!"
  },
  AvgDialog_149757_Content_43 = {
    Text = "Aspetta, il cimitero? Per cosa? Sei — sei davvero ancora vivo?"
  },
  AvgDialog_149757_Content_44 = {
    Text = "<Shake:Vai al cimitero… sepoltura… non c'è tempo… devo andare a seppellire…>"
  },
  AvgDialog_149757_Content_45 = {
    Text = "Chi? Chi devi seppellire?"
  },
  AvgDialog_149757_Content_46 = {Text = "..."},
  AvgDialog_149757_Content_47 = {
    Text = "Cadde in silenzio, lo sguardo fisso verso l'alto — verso la fine di tutte le paludi, dove ogni ricordo e ogni oblio si sarebbero dissolti, dove la pioggia scendeva e rendeva l'aria sempre più rarefatta."
  },
  AvgDialog_149757_Content_48 = {
    Text = "Ma non puoi mai raggiungere il cielo, quindi puoi solo camminare verso il cimitero. È il luogo più vicino alla fine."
  },
  AvgDialog_149757_Content_49 = {
    Text = "Solo per un pezzo di terra vuota, e costa così tanto…"
  },
  AvgDialog_149757_Content_5 = {
    Text = "E così il <Red:demone> in agguato mostrò i suoi artigli."
  },
  AvgDialog_149757_Content_50 = {
    Text = "Se avessi saputo prima quanto fosse caro il luogo in cui i mostri si seppelliscono, non saresti mai venuta."
  },
  AvgDialog_149757_Content_51 = {
    Text = "La pioggia cadde per tre giorni di fila prima di concedersi un breve respiro. Il tuo cavaliere era gravemente ferito nella sua battaglia contro il diavolo, e poté solo mandarti al suo posto al cimitero a seppellire il fagotto che aveva portato con sé. Disse che erano le cose lasciate indietro da qualcuno."
  },
  AvgDialog_149757_Content_52 = {
    Text = "La lapide era vuota — nessun nome inciso. Non avevi idea per chi fosse stata eretta."
  },
  AvgDialog_149757_Content_53 = {
    Text = "Una candela, un pettine, una piccola figura di pietra, un pezzo di pergamena…"
  },
  AvgDialog_149757_Content_54 = {
    Text = "Il fagotto era leggero, con poche cose dentro, eppure tutte erano gravemente danneggiate. Ti scervellasti ma non trovasti risposte. Il tuo cavaliere era un enigma anche per te — non sapevi nulla di lui."
  },
  AvgDialog_149757_Content_55 = {
    Text = "…Anche il sacro graal deve essere sepolto con il resto?"
  },
  AvgDialog_149757_Content_56 = {
    Text = "Ehi, tu piccola laggiù — di quale famiglia sei? Cosa stai facendo ad aggirarsi furtivamente qui?"
  },
  AvgDialog_149757_Content_57 = {
    Text = "Mostri vestiti di armatura marciavano attraverso il cimitero. Uno di loro si fermò all'improvviso, e poi l'intera colonna si arrestò. Stavano in formazione perfetta, indistinguibili l'uno dall'altro, come un enorme centopiedi dai molti segmenti."
  },
  AvgDialog_149757_Content_58 = {
    Text = "Sei diventata sorda? Ti sto chiedendo da dove vieni — ehi, perché stai scappando? Prendetela!"
  },
  AvgDialog_149757_Content_59 = {
    Text = "Lasciami! Lasciami andare! Non ho fatto niente — ho comprato questo appezzamento di terra!"
  },
  AvgDialog_149757_Content_6 = {
    Text = "Dove... dove... non è in questa direzione?"
  },
  AvgDialog_149757_Content_60 = {
    Text = "L'hai comprato? Ah, allora dimmi — sulla pietra non c'è nemmeno un nome. Di chi è questa tomba?"
  },
  AvgDialog_149757_Content_61 = {
    Text = "Io... Io..."
  },
  AvgDialog_149757_Content_62 = {
    Text = "Miei signori, questo è il cimitero della parrocchia. Questa bambina ha effettivamente acquistato un appezzamento — è tutto registrato nel registro."
  },
  AvgDialog_149757_Content_63 = {
    Text = "Quanto ai nomi — la peste è già arrivata. Le persone scompaiono ogni giorno. Le lapidi senza nome sono davvero così rare?"
  },
  AvgDialog_149757_Content_64 = {
    Text = "Le espressioni dei mostri cambiarono. Si scambiarono sguardi e si affrettarono ad andarsene, come se avessero paura di contagiarsi con qualcosa. In quegli occhi, riconoscesti una paura familiare."
  },
  AvgDialog_149757_Content_65 = {Text = "Peste?"},
  AvgDialog_149757_Content_66 = {
    Text = "Sì — la crudele peste, la terribile peste. Far dimenticare una persona richiede solo un po' di tempo. Far dimenticare la pietra, tuttavia, richiede di ridurla in sabbia."
  },
  AvgDialog_149757_Content_67 = {
    Text = "Le pietre dell'oblio diventano sempre più numerose, gli anziani diventano vuoti come i bambini, e non ci restano più storie."
  },
  AvgDialog_149757_Content_68 = {
    Text = "Tu... non pensi che questa sia una maledizione? A causa della strega, o di qualcos'altro."
  },
  AvgDialog_149757_Content_69 = {
    Text = "Una maledizione, una pestilenza, la punizione del Signore, o la vendetta del cavaliere della morte — che differenza fa? Siamo impotenti, figliolo. Possiamo solo guardare al presente. Il presente è tutto ciò che abbiamo. È sempre stato così."
  },
  AvgDialog_149757_Content_7 = {
    Text = "La notte senza luna era buia pece, e la fitta foresta sembrava non avere fondo. Stringevi la Lanterna al petto, cercando ovunque tracce di una fuga disperata."
  },
  AvgDialog_149757_Content_70 = {
    Text = "Torna a casa. Farà buio presto."
  },
  AvgDialog_149757_Content_71 = {
    Text = "Aspetta — un cavaliere della morte? Cos'è?"
  },
  AvgDialog_149757_Content_72 = {
    Text = "Una leggenda. Quella guerra fu un errore. Gridavano di voler sradicare la pestilenza, eppure non fecero che abbatterla su di noi più in fretta. Crearono un mostro."
  },
  AvgDialog_149757_Content_73 = {
    Text = "Si nasconde nelle ombre degli alberi, delle navi, dei muri di pietra e degli uccelli in volo, spostandosi da un luogo all'altro — persino la luce del sole non riesce a raggiungerlo."
  },
  AvgDialog_149757_Content_74 = {
    Text = "Il suo sangue è nero come la pece, il suo cuore brucia di una fiamma spettrale, i suoi occhi brillano come le profondità di una palude. Ovunque passi, lascia dietro di sé ombre che squarciano la luce del giorno."
  },
  AvgDialog_149757_Content_75 = {
    Text = "È la continuazione di quella guerra, un vaso del risentimento dei morti. Appare solo di notte per distruggere i suoi nemici. Non dimentica mai, non vacilla mai. Il motivo della sua venuta è chiaro — il nostro signore, e la nazione che un tempo gli apparteneva."
  },
  AvgDialog_149757_Content_76 = {
    Text = "Cosa? Vuoi dire che il signore è il suo nemico, e che è venuto qui... per vendetta?"
  },
  AvgDialog_149757_Content_77 = {
    Text = "Certo. Lo sappiamo tutti, e anche il signore lo sa. Altrimenti perché la città sarebbe improvvisamente piena di così tanti soldati in pattuglia?"
  },
  AvgDialog_149757_Content_78 = {
    Text = "Lo stanno tutti aspettando."
  },
  AvgDialog_149757_Content_79 = {
    Text = "La pioggia è ricominciata, e le strade sembrano un fiume in piena."
  },
  AvgDialog_149757_Content_8 = {
    Text = "Prima che le ombre lo inghiottissero, ti aveva detto di andartene — ma come poteva una principessa stare senza il suo cavaliere? Avevi cercato di liberarlo, ma lui si era scrollato di dosso la tua mano, aveva sfondato la finestra, era saltato dal soppalco ed era scomparso nei boschi selvaggi oltre il maniero."
  },
  AvgDialog_149757_Content_80 = {
    Text = "Stringi tutte le reliquie al petto e ti lanci a capofitto attraverso i vicoli stretti, schivando di misura pattuglia dopo pattuglia di guardie, dirigendoti dritto verso il capanno di paglia dove ti stai nascondendo."
  },
  AvgDialog_149757_Content_81 = {
    Text = "<Shake:Più veloce, più veloce — torna e digli...>"
  },
  AvgDialog_149757_Content_82 = {
    Text = "Il mostro di cui parlano i mostri — senza alcun dubbio il tuo cavaliere. Le sue sfacciate uccisioni sono finalmente giunte alle orecchie del signore. Si dice che stanotte le guardie perlustreranno ogni angolo della città."
  },
  AvgDialog_149757_Content_83 = {
    Text = "C'è ancora tempo. I cancelli della città non sono ancora chiusi. Solo un po' più veloce..."
  },
  AvgDialog_149757_Content_84 = {
    Text = "<Big:Ogier! Scappa — stanno arrivando—>"
  },
  AvgDialog_149757_Content_85 = {
    Text = "Il capanno stretto era costruito in fondo a un vicolo cieco, circondato da sacchi di tela che non riuscivano comunque a trattenere il fango che scorreva. Ti precipiti verso la figura distesa nell'angolo più profondo e afferri il suo mantello — solo per sollevare un mantello vuoto."
  },
  AvgDialog_149757_Content_86 = {
    Text = "Nel capanno non c'è nient'altro che paglia secca. Del tuo cavaliere non c'è traccia."
  },
  AvgDialog_149757_Content_9 = {
    Text = "La pioggia torrenziale aveva cancellato i rami spezzati e le ultime impronte. Ogni direzione sembrava uguale, e i tuoi passi si facevano sempre più lenti finché non ti fermasti del tutto, persa e disorientata."
  },
  AvgDialog_15363_Content_1 = {
    Text = "Morte della Sig.ra Coral"
  },
  AvgDialog_15363_Content_10 = {
    Text = "La gente si accalcava attorno così fittamente che nemmeno una goccia d'acqua avrebbe potuto passare. Innumerevoli flash di macchine fotografiche scattavano all'unisono, e una cacofonia di chiacchiere si alzava e abbassava—finché un addetto non tirò via il telo con un unico gesto rapido."
  },
  AvgDialog_15363_Content_11 = {
    Text = "Questo è... mio Dio."
  },
  AvgDialog_15363_Content_12 = {
    Text = "...Incredibile."
  },
  AvgDialog_15363_Content_13 = {
    Text = "Come se qualcuno avesse premuto un interruttore, la Folla ammutolì da sola. La sala un tempo rumorosa e vivace sembrò improvvisamente quasi vuota."
  },
  AvgDialog_15363_Content_14 = {
    Text = "Ti facesti largo a fatica tra la Folla, riuscendo finalmente a scorgere l'opera circondata al centro."
  },
  AvgDialog_15363_Content_15 = {Text = "..."},
  AvgDialog_15363_Content_16 = {
    Text = "Era Sanga. Aveva perso ogni colore ed emozione, trasformata in una scultura di corallo bianco puro."
  },
  AvgDialog_15363_Content_17 = {
    Text = "La luce del giorno si rifrangeva attraverso l'immacolata cupola di vetro soprastante, avvolgendola in un delicato velo di luce dorata pallida."
  },
  AvgDialog_15363_Content_18 = {
    Text = "Abbassasti lo sguardo sulla targhetta d'ottone sul piedistallo della scultura. Sopra di essa, in elegante corsivo, era inciso il nome della scultura: <Red:\"Figlia del Corallo Senza Nome\">."
  },
  AvgDialog_15363_Content_19 = {
    Text = "Corallo Senza Nome..."
  },
  AvgDialog_15363_Content_2 = {
    Text = "Caro Monsieur Claudel:\n\nMolto è accaduto di recente. Vi prego di perdonare il mio ritardo nel rispondere.\n\nDopo la partenza della Signorina Sanga, Monsieur August non fu mai più in grado di produrre opere degne di nota.\nSotto la pressione dell'opinione pubblica, annunciò la sospensione a tempo indeterminato della sua carriera di scultore.\nHa ricevuto la punizione che meritava, eppure non riesco a rallegrarmene—<Yellow:il luogo in cui si trova la Signorina Sanga resta sconosciuto.>"
  },
  AvgDialog_15363_Content_20 = {
    Text = "Fissasti quella sequenza di parole in uno stato di torpore, la tua coscienza sembrava oscillare e contorcersi seguendo quelle eleganti curve delle lettere..."
  },
  AvgDialog_15363_Content_21 = {
    Text = "Alzasti una mano per strofinarti gli occhi, solo per scoprire che a un certo punto, strati di bianco ruvido e opaco avevano iniziato a strisciare sulle tue dita."
  },
  AvgDialog_15363_Content_22 = {Text = "?!"},
  AvgDialog_15363_Content_23 = {
    Text = "La foschia di corallo bianco continuò a diffondersi dalle tue dita, ricoprendo il tuo intero corpo poco a poco, inondando rapidamente l'intera sala espositiva, e poi—"
  },
  AvgDialog_15363_Content_24 = {Text = "—!!"},
  AvgDialog_15363_Content_25 = {
    Text = "Tu e la sala espositiva vi frantumaste simultaneamente in innumerevoli frammenti bianchi, precipitando nelle profondità sconfinate degli Abissi Marini."
  },
  AvgDialog_15363_Content_26 = {
    Text = "Tra innumerevoli sculture bianche e coralli, sotto la quieta luce del mattino, le rovine bianche di un palazzo si ergevano imponenti."
  },
  AvgDialog_15363_Content_27 = {
    Text = "Pesci di ogni colore guizzavano attraverso gli archi inclinati e i corridoi delle rovine, godendosi i loro piacevoli momenti di svago."
  },
  AvgDialog_15363_Content_28 = {
    Text = "L'intera rovina sembrava abbandonata nell'ombra del tempo, lontana dalla Corrosione del mondo, al riparo dalle molestie della Folla."
  },
  AvgDialog_15363_Content_29 = {
    Text = "Una volta che avrai visto quei Miracoli... mi capirai..."
  },
  AvgDialog_15363_Content_3 = {
    Text = "<Yellow:Domani andrò alla mostra del Salon della Cité per cercare le \"risposte\" di cui parlava la Signorina Sanga.>\nAuguratemi buona fortuna.\n\nCamille@1\nA.F.2@1, settembre"
  },
  AvgDialog_15363_Content_30 = {
    Text = "Questo è... il Miracolo che hai visto, Signorina Sanga?"
  },
  AvgDialog_15363_Content_31 = {
    Text = "Hai vagato attraverso le calde acque marine, osservando tutto ciò che ti circondava con fascino e smarrimento."
  },
  AvgDialog_15363_Content_32 = {
    Text = "Fuori dai piedi, fatemi passare!!"
  },
  AvgDialog_15363_Content_33 = {
    Text = "<Big:Fatemi passare!!>"
  },
  AvgDialog_15363_Content_34 = {
    Text = "Il clamore della confusione ti riportò alla realtà."
  },
  AvgDialog_15363_Content_35 = {
    Text = "Un anziano dall'aspetto trasandato sfondò i vari livelli di Catene di sicurezza e si lanciò verso di te, afferrandoti la mano con una presa mortale."
  },
  AvgDialog_15363_Content_36 = {
    Text = "Anche tu l'hai visto, vero? Il mare profondo, il palazzo, tutte quelle caotiche illusioni..."
  },
  AvgDialog_15363_Content_37 = {Text = "?!"},
  AvgDialog_15363_Content_38 = {
    Text = "Quella donna malvagia, lei è una ladra…"
  },
  AvgDialog_15363_Content_39 = {
    Text = "L'anziano mormorava incessantemente. Hai fissato il volto celato sotto la tesa larga del cappello e la folta barba, e all'improvviso hai colto un barlume di qualcosa di familiare."
  },
  AvgDialog_15363_Content_4 = {
    Text = "Mostra del Salon della Cité\nGiorno di apertura"
  },
  AvgDialog_15363_Content_40 = {
    Text = "…Signor August?!"
  },
  AvgDialog_15363_Content_41 = {
    Text = "Cielo, è davvero lui... Mio Dio! Cosa gli è successo?"
  },
  AvgDialog_15363_Content_42 = {
    Text = "È andato in bancarotta molto tempo fa, non lo sapevi? Dopo il fiasco della <Italic:Musa Tragica>, ha investito una fortuna in diversi pezzi, ma nessuno di essi è stato venduto..."
  },
  AvgDialog_15363_Content_43 = {
    Text = "Il governo diffida della sua reputazione ormai e ha smesso di affidargli commissioni. Probabilmente è impazzito per il troppo stress…"
  },
  AvgDialog_15363_Content_44 = {
    Text = "La folla osservava August da una distanza prudente, al contempo scioccata e spaventata."
  },
  AvgDialog_15363_Content_45 = {
    Text = "August si liberò dalla tua mano. Zoppicò verso la scultura, gli occhi traboccanti di un odio che non poteva più essere contenuto."
  },
  AvgDialog_15363_Content_46 = {
    Text = "Hah… Pensavi che morire avrebbe cancellato tutto ciò che hai fatto?"
  },
  AvgDialog_15363_Content_47 = {
    Text = "Hai ingannato tutti… Il mio talento, la mia Intuizione e la mia reputazione mi sono stati portati via da te."
  },
  AvgDialog_15363_Content_48 = {
    Text = "Sono rovinato, completamente rovinato. E tu? Seduta qui a tuo agio, crogiolarti nell'ammirazione di tutti, in attesa che ti consacrino come un classico…"
  },
  AvgDialog_15363_Content_49 = {Text = "..."},
  AvgDialog_15363_Content_5 = {
    Text = "Avete sentito? Il Sig. August è tornato a esporre le sue sculture."
  },
  AvgDialog_15363_Content_50 = {
    Text = "Di fronte alle Maledizioni isteriche del suo ex maestro, la scultura restava in silenzio, la sua espressione indifferente non scalfita nel minimo."
  },
  AvgDialog_15363_Content_51 = {
    Text = "August non riuscì più a sopportarlo. Si scagliò con ferocia contro la scultura."
  },
  AvgDialog_15363_Content_52 = {
    Text = "Di nuovo quell'Espressione, di nuovo quella derisione...\""
  },
  AvgDialog_15363_Content_53 = {
    Text = "Diavolo... Diavolo! <Big:Ti strapperò la maschera!>"
  },
  AvgDialog_15363_Content_6 = {
    Text = "August, lo scultore? Non era sparito dopo essere stato colpito da quell'Eterna Questione sul plagio? Pensavo che non si sarebbe mai più fatto vedere."
  },
  AvgDialog_15363_Content_7 = {
    Text = "Sono piuttosto curiosa, però. Senza quella sua apprendista, cosa mai potrà aver creato adesso..."
  },
  AvgDialog_15363_Content_8 = {
    Text = "La cerimonia di inaugurazione dell'esposizione del salone brulicava di visitatori."
  },
  AvgDialog_15363_Content_9 = {
    Text = "L'opera di August si ergeva al centro della sala espositiva, avvolta sotto strati di pesante tessuto, stuzzicando la curiosità di innumerevoli spettatori."
  },
  AvgDialog_15364_Content_1 = {Text = "UUGHH!"},
  AvgDialog_15364_Content_10 = {
    Text = "Esposizione del Salone della Cité\nSerata inaugurale"
  },
  AvgDialog_15364_Content_11 = {
    Text = "Quando l'ultima Serratura di ferro scattò al suo posto, la sala espositiva sprofondò in un silenzio buio pesto."
  },
  AvgDialog_15364_Content_12 = {
    Text = "Uscisti dalle ombre nell'angolo e ti fermasti di nuovo davanti a Lei."
  },
  AvgDialog_15364_Content_13 = {
    Text = "Libero dal clamore diurno, quello era il momento perfetto per parlare."
  },
  AvgDialog_15364_Content_14 = {
    Text = "Signorina Sanga, il signor August è stato portato via oggi. Ha detto...\nChe hai ingannato Tutti."
  },
  AvgDialog_15364_Content_15 = {
    Text = "\"Tutti\" include anche me?"
  },
  AvgDialog_15364_Content_16 = {Text = "..."},
  AvgDialog_15364_Content_17 = {
    Text = "Una volta hai promesso che saresti venuta a casa con me. Era vero?"
  },
  AvgDialog_15364_Content_18 = {Text = "..."},
  AvgDialog_15364_Content_19 = {
    Text = "La scultura rimase silenziosa come sempre. Anche se le vite di Tutti erano state stravolte a causa Sua, Lei non abbassò mai lo sguardo dal fissare lontano."
  },
  AvgDialog_15364_Content_2 = {
    Text = "Lasciatemi, quella che dovreste arrestare è Lei, è Lei—"
  },
  AvgDialog_15364_Content_20 = {
    Text = "Il chiaro di Luna filtrava attraverso le vetrate della sala espositiva, avvolgendoLa in un alone di luce bianca pallida."
  },
  AvgDialog_15364_Content_21 = {
    Text = "<Red:Segui il mio sguardo...>"
  },
  AvgDialog_15364_Content_22 = {
    Text = "Seguire lo sguardo... Possibile che?!"
  },
  AvgDialog_15364_Content_23 = {
    Text = "Ti alzasti in punta di piedi, solo per scoprire che sotto la luce della luna, gli occhi un tempo distanti e sfocati della scultura erano ormai cambiati, cristallizzandosi in qualcosa di concreto e intensamente emotivo."
  },
  AvgDialog_15364_Content_24 = {
    Text = "Il suo sguardo era sempre stato fisso sulla lontananza."
  },
  AvgDialog_15364_Content_25 = {
    Text = "Ti voltasti, seguendo la sua linea di vista."
  },
  AvgDialog_15364_Content_26 = {
    Text = "Nell'istante in cui i tuoi occhi vagarono, la sala espositiva sotto i tuoi piedi svanì come per miracolo."
  },
  AvgDialog_15364_Content_27 = {
    Text = "Al suo posto si estendeva un mare sconfinato e una vasta distesa di sabbia bianca."
  },
  AvgDialog_15364_Content_28 = {
    Text = "Il rombo di un tuono lontano rotolò verso di te mentre le maree si sollevavano violentemente, precipitandosi nella tua direzione."
  },
  AvgDialog_15364_Content_29 = {
    Text = "Questo era il mare che tu e Sanga avevate visitato insieme."
  },
  AvgDialog_15364_Content_3 = {
    Text = "Signor August, abbiamo ricevuto una segnalazione secondo cui il suo comportamento ha causato gravi disordini all'esposizione del salone. La preghiamo di seguirci immediatamente."
  },
  AvgDialog_15364_Content_4 = {Text = "No, no..."},
  AvgDialog_15364_Content_5 = {
    Text = "La scena era nel Caos più totale. La folla che accorreva da ogni direzione ti separò completamente da August. Potevi solo guardare mentre veniva trascinato via a forza dalla polizia."
  },
  AvgDialog_15364_Content_6 = {
    Text = "Non cantare vittoria troppo presto... Un giorno, farai la mia stessa fine..."
  },
  AvgDialog_15364_Content_7 = {
    Text = "Heh... Heheheh..."
  },
  AvgDialog_15364_Content_8 = {
    Text = "L'ordine fu finalmente ristabilito nella sala espositiva."
  },
  AvgDialog_15364_Content_9 = {
    Text = "L'ultima risata tremante e nevrotica di August aleggiava come increspature che svanivano lentamente, appena percettibili nella vasta sala vuota."
  },
  AvgDialog_15365_Content_1 = {
    Text = "Mare di Mezzo"
  },
  AvgDialog_15365_Content_10 = {
    Text = [[
Quindi sei tu.
Scusa, ti ho svegliata quando mi sono alzata?]]
  },
  AvgDialog_15365_Content_11 = {
    Text = "Piuttosto che preoccuparti di svegliare me, dovresti preoccuparti di più di disturbare quei <Blue:vecchi signori che dormono sottoterra>."
  },
  AvgDialog_15365_Content_12 = {
    Text = "Sollevasti il mento per indicare la tomba davanti a lei, scavata per quasi trenta centimetri di profondità."
  },
  AvgDialog_15365_Content_13 = {
    Text = "Sembra che tu stia cercando qualcosa. Hai bisogno di aiuto?"
  },
  AvgDialog_15365_Content_14 = {
    Text = "Non ce n'è bisogno. L'ho già trovato."
  },
  AvgDialog_15365_Content_15 = {
    Text = "Sanga aprì la mano verso di te con un sorriso radioso. Era ricoperta di un liquido viscoso, nero come la pece—"
  },
  AvgDialog_15365_Content_16 = {
    Text = "D-melma. Non potevi conoscerla meglio di così."
  },
  AvgDialog_15365_Content_17 = {
    Text = "Vedi? Sotto la luce della luna, emettono una strana sfumatura blu. Di giorno, assumono un aspetto completamente diverso..."
  },
  AvgDialog_15365_Content_18 = {
    Text = "È il materiale da scultura più perfetto che abbia mai visto."
  },
  AvgDialog_15365_Content_19 = {Text = "..."},
  AvgDialog_15365_Content_2 = {
    Text = "Caro Signor Claudel:\n\nLa Signorina Sanga non ha rifiutato la richiesta di tornare a casa, ma spera che io possa concederle un po' di tempo.\nHa detto: <Yellow:Quando l'esposizione del Salon sarà finita, potrò tornare a casa.>\n\nDetto ciò, lo Stato della Signorina Sanga ultimamente è preoccupante.\nOgni notte sgattaiola via in silenzio e non torna fino alle prime ore del mattino."
  },
  AvgDialog_15365_Content_20 = {
    Text = "Ti sei sgattaiolata fuori ogni notte solo per raccogliere D-melma qui?"
  },
  AvgDialog_15365_Content_21 = {
    Text = "Conosci il loro nome? Hai una certa familiarità con loro."
  },
  AvgDialog_15365_Content_22 = {
    Text = "Non è... niente di raro. Ce n'è in abbondanza a Besançon."
  },
  AvgDialog_15365_Content_23 = {
    Text = "Capisco... Pensavo fosse una meravigliosa scoperta tutta mia."
  },
  AvgDialog_15365_Content_24 = {
    Text = "Dissoluzione... Un nome davvero appropriato."
  },
  AvgDialog_15365_Content_25 = {
    Text = "Non è il momento per le battute, Sanga."
  },
  AvgDialog_15365_Content_26 = {
    Text = "Morirai. Non è qualcosa che persone comuni come noi dovrebbero toccare."
  },
  AvgDialog_15365_Content_27 = {
    Text = "Lo capisco, certo che lo capisco... La bellezza attira inevitabilmente il pericolo."
  },
  AvgDialog_15365_Content_28 = {
    Text = "Ma d'altra parte, il pericolo stesso non è forse una forma di bellezza?\nPer me, la morte non è qualcosa da temere."
  },
  AvgDialog_15365_Content_29 = {
    Text = "Ciò che è davvero terrificante è..."
  },
  AvgDialog_15365_Content_3 = {
    Text = "Stranamente, questa persistente abitudine di dormire di giorno e uscire di notte l'ha invece riempita di vitalità,\ne persino il Signor August è piuttosto soddisfatto della sua recente efficienza lavorativa.\n\n<Yellow:È diventata così irriconoscibile.>\n\nIn diverse notti, mi sono svegliata da incubi e l'ho trovata lì in piedi accanto al mio letto...\nMi fissava senza battere ciglio, con gli occhi pieni di cose spaventose che non riuscivo a comprendere."
  },
  AvgDialog_15365_Content_30 = {
    Text = "Un Vento gentile soffiò, inghiottendo le parole successive di Sanga. La Luna era emersa a un certo punto dalle nubi scure stratificate, proiettando la sua fredda luce lunare su entrambi."
  },
  AvgDialog_15365_Content_31 = {
    Text = "Fu allora che vedesti le cicatrici sul collo di Sanga."
  },
  AvgDialog_15365_Content_32 = {
    Text = "Erano come Tentacoli di corallo, che si estendevano sempre più in alto, tremolando di un Bagliore Marino grigio-azzurro nelle Fessure in cui la luce della luna mutava."
  },
  AvgDialog_15365_Content_33 = {
    Text = "Signorina Sanga, sei già stata infettata...?!"
  },
  AvgDialog_15365_Content_34 = {
    Text = "Pur sapendo che era Solo un Sogno, il tuo cuore fu comunque trafitto da una breve fitta di dolore."
  },
  AvgDialog_15365_Content_35 = {
    Text = "Dopotutto, ora possedevi tutti i ricordi e le emozioni dell'ospite originale. Questa Cameriera della campagna di Besançon nutriva un profondo affetto per la Sua padrona."
  },
  AvgDialog_15365_Content_36 = {
    Text = "È a causa del Signor August? Le sue parole ti hanno messo troppa pressione, quindi..."
  },
  AvgDialog_15365_Content_37 = {
    Text = "Sanga scosse la testa."
  },
  AvgDialog_15365_Content_38 = {
    Text = [[
Dall'inizio alla fine, questa faccenda non ha avuto nulla a che fare con lui.
Vieni, lascia che ti porti in un posto.]]
  },
  AvgDialog_15365_Content_39 = {
    Text = "Finalmente siamo qui — la mia base segreta."
  },
  AvgDialog_15365_Content_4 = {
    Text = [[
<Yellow:Ho deciso di seguirla di nascosto stanotte per scoprire cosa fa davvero.>
Auguratemi buona fortuna.

Camille@1
A.F.2@1 Settembre]]
  },
  AvgDialog_15365_Content_40 = {
    Text = "Era un magazzino abbandonato in riva al mare. All'interno c'erano molte Esercitazioni di Scultura bizzarramente contorte in ogni sorta di posa."
  },
  AvgDialog_15365_Content_41 = {
    Text = "Coralli, conchiglie, Tentacoli, ed edifici e creature adornati con strane incisioni... L'unica cosa che avevano in comune era il loro stretto legame con l'oceano."
  },
  AvgDialog_15365_Content_42 = {
    Text = "La consistenza di queste sculture..."
  },
  AvgDialog_15365_Content_43 = {
    Text = "Non è né marmo né granito. Dove hai trovato questo materiale?"
  },
  AvgDialog_15365_Content_44 = {
    Text = "Sanga ti rivolse un Occhiolino giocoso."
  },
  AvgDialog_15365_Content_45 = {
    Text = "Questo è il mio segreto. Lo scoprirai un giorno."
  },
  AvgDialog_15365_Content_46 = {
    Text = "Al centro della capanna di legno si ergeva una scultura umanoide incompiuta."
  },
  AvgDialog_15365_Content_47 = {
    Text = "Il suo corpo era avvolto in sinistri Tentacoli, contorto in angoli incredibili. Le vene del collo erano gonfie, Come Se fossero un serpente sinuoso."
  },
  AvgDialog_15365_Content_48 = {
    Text = "Bella, vero?\nMi chiamano tutti \"la Macellaia,\" perché sono sempre spietata con i miei modelli."
  },
  AvgDialog_15365_Content_49 = {
    Text = "Ma è proprio per questo che riesco a catturare l'essenza — l'agonia intrecciata che giace sotto la pelle e la carne."
  },
  AvgDialog_15365_Content_5 = {
    Text = "Settembre a Cité è già terribilmente freddo.\nCammini in silenzio per la strada, cercando di celarti nelle ombre."
  },
  AvgDialog_15365_Content_50 = {
    Text = "Ma il mio maestro trattava sempre i suoi modelli con eccessiva cura, ed è per questo che non è mai riuscito a essere altro che uno scultore di second'ordine."
  },
  AvgDialog_15365_Content_51 = {
    Text = "Contempli la scultura davanti a te. È innegabilmente bella, ma anche crudele."
  },
  AvgDialog_15365_Content_52 = {
    Text = "È questa l'opera che intendi portare all'esposizione?"
  },
  AvgDialog_15365_Content_53 = {
    Text = "Sanga scosse la testa."
  },
  AvgDialog_15365_Content_54 = {
    Text = "Solo alcune bozze. Prima di incontrare quelle... D-melma, la mia comprensione della scultura era ancora piuttosto superficiale."
  },
  AvgDialog_15365_Content_55 = {
    Text = "Ora sono come una neonata che ha appena aperto gli occhi, costretta a riscoprire il mondo che ho davanti..."
  },
  AvgDialog_15365_Content_56 = {
    Text = "<Yellow:E a riscoprire te.>"
  },
  AvgDialog_15365_Content_57 = {Text = "Me...?"},
  AvgDialog_15365_Content_58 = {
    Text = "Sì, te. Nei tuoi occhi e nella tua espressione, vedo nuove possibilità."
  },
  AvgDialog_15365_Content_59 = {
    Text = "Sanga tracciò delicatamente i contorni del tuo viso con le dita."
  },
  AvgDialog_15365_Content_6 = {
    Text = "La figura esile di Sanga era appena più avanti.\nMantenevi una distanza tra voi — né troppo vicina né troppo lontana — come se foste collegate da un filo invisibile."
  },
  AvgDialog_15365_Content_60 = {
    Text = "A differenza delle altre signorine viziate, i polpastrelli delle sue dita portavano un sottile strato di calli, conferendo loro una consistenza ruvida e unica."
  },
  AvgDialog_15365_Content_61 = {
    Text = "Hai paura. Non preoccuparti, non ti costringerò a fare nulla."
  },
  AvgDialog_15365_Content_62 = {
    Text = "Ti ricordi ancora di quando eravamo bambini?"
  },
  AvgDialog_15365_Content_63 = {
    Text = "Quando eravamo bambini?"
  },
  AvgDialog_15365_Content_64 = {
    Text = "Seguendo le sue parole, ti addentri sempre più nei ricordi aggrovigliati del proprietario originale, esplorando..."
  },
  AvgDialog_15365_Content_65 = {
    Text = "Fino a soffermarti infine su quell'estate fioca e nebulosa."
  },
  AvgDialog_15365_Content_66 = {
    Text = "Certo che ricordo. Quando avevi 5 anni, sapevi già scolpire uno scheletro umano con il fango."
  },
  AvgDialog_15365_Content_67 = {
    Text = "Io andavo al mare a cercare ogni sorta di materiali per te, e il giovane padrone Paul Claudel si occupava di gettare quei modelli nella fornace per cuocerli."
  },
  AvgDialog_15365_Content_68 = {
    Text = "Sì, era il nostro piccolo segreto — solo noi tre."
  },
  AvgDialog_15365_Content_69 = {
    Text = "Una volta, quando tuo padre lo scoprì, ti prendesti tutta la colpa e fosti persino costretto a stare in piedi come punizione per un'intera notte."
  },
  AvgDialog_15365_Content_7 = {
    Text = "Quel filo vi condusse entrambe oltre un edificio dopo l'altro, attraverso il lungo e cupo gelo, finché non arrivaste alla vostra destinazione comune—"
  },
  AvgDialog_15365_Content_70 = {
    Text = "Una sottile foschia di tristezza affiorò negli occhi grigi di Sanga."
  },
  AvgDialog_15365_Content_71 = {
    Text = "Ti abbraccia dolcemente."
  },
  AvgDialog_15365_Content_72 = {
    Text = "Siete tutta la mia famiglia, per sempre. È stato Paul a mandarti a cercarmi, vero?"
  },
  AvgDialog_15365_Content_73 = {
    Text = "Sì. Il giovane padrone... si è ammalato e non è potuto venire di persona."
  },
  AvgDialog_15365_Content_74 = {
    Text = [[
Respiri piano contro l'incavo del collo di Sanga, il suo profumo ti riempie le narici.
Il sapore inebriante delle onde del mare.]]
  },
  AvgDialog_15365_Content_75 = {
    Text = "Non preoccuparti. Ti ho promesso che saremmo tornate a casa insieme, e non verrò meno alla mia parola."
  },
  AvgDialog_15365_Content_76 = {
    Text = "Ma prima di allora, devo lasciarti."
  },
  AvgDialog_15365_Content_77 = {
    Text = "Lasciarmi...? Dove vai?"
  },
  AvgDialog_15365_Content_78 = {
    Text = "Sanga non aggiunge altro, volgendo invece lo sguardo verso il grigio mare velato di foschia."
  },
  AvgDialog_15365_Content_79 = {
    Text = "È una notte avvolta nella nebbia. Le onde gentili si infrangono in un ritmo eterno e immutabile, proprio come il battito percepito sul lato del collo di Sanga."
  },
  AvgDialog_15365_Content_8 = {
    Text = "Una tomba desolata."
  },
  AvgDialog_15365_Content_80 = {
    Text = "Non lo so. Forse nelle profondità degli Abissi Marini, o forse @1..."
  },
  AvgDialog_15365_Content_81 = {
    Text = "Dopo quel giorno, la Signorina Sanga scomparve."
  },
  AvgDialog_15365_Content_82 = {
    Text = "Andai ovunque potessi andare, chiesi a chiunque potessi trovare, eppure non ottenni nulla.\n\nCi lasciò come un soffio di vento.\nAncora oggi, mi ritrovo a rivivere quella notte in riva al mare, ancora e ancora."
  },
  AvgDialog_15365_Content_83 = {
    Text = [[
In quel momento, la Signorina Sanga mi strinse forte.
Forse in seguito mi disse qualcos'altro, o forse no. Non lo so.

I miei ricordi iniziarono a farsi confusi da quel giorno in poi.

<Red:Corallo bianco, conchiglie a spirale, un misterioso palazzo sotto il mare...>
Ancora oggi, queste immagini caotiche continuano a tormentare la mia mente nel cuore della notte.]]
  },
  AvgDialog_15365_Content_84 = {
    Text = "<Yellow:\"Vai alla mostra del Salon e cerca le risposte.\">\n\nQuesto è ciò che la Signorina Sanga mi disse. Disse anche—"
  },
  AvgDialog_15365_Content_85 = {
    Text = "Quando avrai assistito a quei miracoli, mi capirai."
  },
  AvgDialog_15365_Content_86 = {
    Text = "Basta che tu segua il mio sguardo..."
  },
  AvgDialog_15365_Content_87 = {
    Text = "Te lo prometto."
  },
  AvgDialog_15365_Content_9 = {
    Text = "Signorina Sanga."
  },
  AvgDialog_15367_Content_1 = {
    Text = "Via, non toccatemi...!!"
  },
  AvgDialog_15367_Content_10 = {
    Text = "So che avete gestito di nascosto una specie di <Yellow:atelier> per conto vostro, ma credo di dovervi ricordare una cosa."
  },
  AvgDialog_15367_Content_11 = {
    Text = "Non aspettatevi che le vostre <Yellow:creazioni amatoriali, abominevoli e frutto di Profanazione> conquistino il favore dei funzionari governativi."
  },
  AvgDialog_15367_Content_12 = {
    Text = "Ammetto che siete molto talentuosa e che siete stata di grande aiuto per l'atelier. Ma per perseguire l'arte in un luogo come la Cité, serve ben più del talento."
  },
  AvgDialog_15367_Content_13 = {
    Text = "Se mi fai arrabbiare..."
  },
  AvgDialog_15367_Content_14 = {
    Text = "Signor August, la prego di moderare le parole."
  },
  AvgDialog_15367_Content_15 = {
    Text = "Va tutto bene, Camille."
  },
  AvgDialog_15367_Content_16 = {
    Text = "Sanga ti tirò delicatamente indietro da dietro. Di fronte al rimprovero di August, la sua espressione rimase calma."
  },
  AvgDialog_15367_Content_17 = {
    Text = "Si inginocchiò, raccolse uno a uno i frammenti del volto della scultura e li gettò nel mucchio di spazzatura lì vicino."
  },
  AvgDialog_15367_Content_18 = {
    Text = "Se vi faccio arrabbiare, le mie opere non potranno essere esposte, non potranno essere vendute, e come artista non vedrò mai la luce del giorno. E alla fine..."
  },
  AvgDialog_15367_Content_19 = {
    Text = "Non potrò che morire di freddo per strada, o essere rinchiusa in un manicomio."
  },
  AvgDialog_15367_Content_2 = {
    Text = "Tutti si affrettarono a trattenere quest'ultimo — il maestro scultore, ormai fuori di sé dalla rabbia."
  },
  AvgDialog_15367_Content_20 = {
    Text = "Naturalmente so tutto questo perfettamente, Maestro."
  },
  AvgDialog_15367_Content_3 = {
    Text = "Non siate avventato, mio caro maestro."
  },
  AvgDialog_15367_Content_4 = {
    Text = "Un'opera così mediocre rovinerebbe non solo il mio umore, ma anche la vostra reputazione."
  },
  AvgDialog_15367_Content_5 = {
    Text = "Heh... Non siate così presuntuosa. Manca meno di mezzo anno all'esposizione del Salon. Pensate forse di far apparire qualcosa di meglio dal nulla?"
  },
  AvgDialog_15367_Content_6 = {Text = "Un mese."},
  AvgDialog_15367_Content_7 = {Text = "...Cosa?"},
  AvgDialog_15367_Content_8 = {
    Text = "Datemi un mese, e vi consegnerò un'assoluta <Yellow:sorpresa>."
  },
  AvgDialog_15367_Content_9 = {Text = "...Hmph."},
  AvgDialog_15368_Content_1 = {
    Text = "Una lettera per te"
  },
  AvgDialog_15368_Content_10 = {
    Text = "Le tempie pulsano senza sosta. Cerchi di muovere il corpo, ma—"
  },
  AvgDialog_15368_Content_11 = {Text = "...!"},
  AvgDialog_15368_Content_12 = {
    Text = "<Shake:Le mie gambe... si sono intorpidite...>"
  },
  AvgDialog_15368_Content_13 = {
    Text = "Hmm, è solo la mia immaginazione? Nel momento in cui hai aperto gli occhi, mi è sembrato di vedere una lucentezza che non avevo mai visto prima."
  },
  AvgDialog_15368_Content_14 = {
    Text = "No, non è la mia immaginazione. Anche la tua espressione è diversa..."
  },
  AvgDialog_15368_Content_15 = {
    Text = "Gli occhi della giovane apprendista scultrice brillano di Euforia mentre si avvicina improvvisamente a te."
  },
  AvgDialog_15368_Content_16 = {Text = "Chi sei?"},
  AvgDialog_15368_Content_17 = {
    Text = "La tua Cameriera"
  },
  AvgDialog_15368_Content_18 = {
    Text = "<Shake:I-Io sono la tua Cameriera, Camille@1! Non ricordi? Ahaha...>"
  },
  AvgDialog_15368_Content_19 = {
    Text = "Tieni ben salda in mente la tua Identità."
  },
  AvgDialog_15368_Content_2 = {
    Text = "Caro Monsieur Claudel:\n\nSono arrivata a Cité.\nA differenza della tranquillità di Besançon, questo luogo è sempre colmo di un rumore assordante.\nRintocchi di campane, lo sferragliare delle carrozze e il frastuono incessante della Folla…\nIl solo pensiero che Miss Sanga abbia vissuto in un simile ambiente mi riempie di inquietudine."
  },
  AvgDialog_15368_Content_20 = {
    Text = "Questa volta, sei la Cameriera cresciuta con Sanga fin dall'infanzia, inviata dal Signor Paul per riportare Sanga a casa."
  },
  AvgDialog_15368_Content_21 = {
    Text = "\"Devi salvare la sua anima dalle grinfie di quel diavolo che non fa altro che Sfruttare e plagiare gli altri.\""
  },
  AvgDialog_15368_Content_23 = {
    Text = "<Gray:No, non è giusto...>"
  },
  AvgDialog_15368_Content_24 = {
    Text = "Tieni ben salda in mente la tua Identità."
  },
  AvgDialog_15368_Content_25 = {
    Text = "Questa volta, sei una cameriera cresciuta insieme a Sanga e sei stata inviata dal Giovane Padrone @1: Claudel per riportarla a casa."
  },
  AvgDialog_15368_Content_26 = {
    Text = "\"Devi salvare la sua anima dalle grinfie di quel diavolo che non fa altro che sfruttare e plagiare i suoi subordinati.\""
  },
  AvgDialog_15368_Content_27 = {
    Text = "S-Sono la tua cameriera, Camille@1! Non ti ricordi? Ahah..."
  },
  AvgDialog_15368_Content_28 = {
    Text = "<Shake:Dopo tanti anni di separazione, siamo cambiate entrambe un po', non è vero?>"
  },
  AvgDialog_15368_Content_29 = {Text = "..."},
  AvgDialog_15368_Content_3 = {
    Text = "Le voci si sono già diffuse.\nLa gente dice che Miss Sanga trascorra giorni e notti con un Uomo di oltre 20 anni più grande di lei, \"in nome dell'arte\".\nÈ del tutto assurdo. Domani mi recherò allo studio per vedere con i miei occhi.\n\nQuesta volta, adempirò alla vostra richiesta—\n<Yellow:Riportare vostra sorella, la nostra cara Miss Sanga, a Besançon.>\n\nCamille@1\nA.F.2@1 Agosto"
  },
  AvgDialog_15368_Content_30 = {
    Text = "Sei davvero molto diversa. Sei molto più vivida di prima.\nÈ come se... ti fossi improvvisamente animata."
  },
  AvgDialog_15368_Content_31 = {
    Text = "<Gray:Quindi questo è il Profumo della Bestia di un'artista... Dovrò stare più attenta d'ora in poi.>"
  },
  AvgDialog_15368_Content_32 = {
    Text = "<Shake:Se non ti dispiace, potresti aiutarmi? Non riesco proprio ad alzarmi in questo momento...>"
  },
  AvgDialog_15368_Content_33 = {
    Text = "Sanga prende delicatamente la tua mano, un barlume di preoccupazione attraversa i suoi occhi calmi e imperturbabili."
  },
  AvgDialog_15368_Content_34 = {
    Text = "Mi dispiace, ero troppo assorta nel mio lavoro poco fa. Devi sentirti molto a disagio in questo momento. Fammi dare un'occhiata."
  },
  AvgDialog_15368_Content_35 = {
    Text = "Whoosh—!!"
  },
  AvgDialog_15368_Content_36 = {
    Text = "La porta dello studio venne spalancata."
  },
  AvgDialog_15368_Content_37 = {
    Text = "Un uomo alto e cupo entrò, seguito da diversi volti sconosciuti."
  },
  AvgDialog_15368_Content_38 = {
    Text = "Senza bisogno di accedere ai ricordi dell'ospite originale, lo riconoscesti dai suoi caratteristici baffi—"
  },
  AvgDialog_15368_Content_39 = {
    Text = "Il rinomato scultore, <Blue:August>."
  },
  AvgDialog_15368_Content_4 = {
    Text = "Miss Sanga, torni con me. Qui non c'è nemmeno un posto dove scaldarsi—"
  },
  AvgDialog_15368_Content_40 = {
    Text = "Ancora oggi, le sue sculture sono considerate capolavori, molto ricercate alle aste di Londinium."
  },
  AvgDialog_15368_Content_41 = {
    Text = "Vedendo le vostre mani intrecciate, quelle tue e di Sanga, August aggrottò le sopracciglia. Ma presto, la sua attenzione fu catturata dalla scultura davanti a lui."
  },
  AvgDialog_15368_Content_42 = {
    Text = "Questo è... <Big:Un capolavoro, un capolavoro indiscutibile!>"
  },
  AvgDialog_15368_Content_43 = {
    Text = "Anche gli altri si radunarono attorno, osservando con curiosità la scultura appena completata, lasciandosi sfuggire ondate di ammirazione."
  },
  AvgDialog_15368_Content_44 = {
    Text = "Bene, molto bene... Contattate le persone al Ministero della Cultura. Dite loro che abbiamo un'opera promettente per l'esposizione di Cité di quest'anno."
  },
  AvgDialog_15368_Content_45 = {
    Text = "Non vedo l'ora di vedere le facce di quei critici quando resteranno a bocca aperta... Hahahaha!"
  },
  AvgDialog_15368_Content_46 = {
    Text = "La risata fragorosa di August risuonò nell'ampio studio. Ti spinse da parte e afferrò saldamente la mano di Sanga."
  },
  AvgDialog_15368_Content_47 = {
    Text = "Sapevo che non mi avresti deluso, Sanga."
  },
  AvgDialog_15368_Content_48 = {
    Text = "Sanga ritirò lentamente la mano e si avvicinò alla scultura."
  },
  AvgDialog_15368_Content_49 = {
    Text = "Un indiscutibile... capolavoro?"
  },
  AvgDialog_15368_Content_5 = {
    Text = "Non muoverti e non parlare. Resta così.\nSì, proprio così…"
  },
  AvgDialog_15368_Content_50 = {
    Text = "Tu che ne pensi, Camille?"
  },
  AvgDialog_15368_Content_51 = {Text = "Eh, io...?"},
  AvgDialog_15368_Content_52 = {
    Text = "Fissasti la scultura che somigliava quasi perfettamente a \"te\" e ti immergesti in profondi pensieri..."
  },
  AvgDialog_15368_Content_53 = {Text = "Mediocre"},
  AvgDialog_15368_Content_54 = {
    Text = "Hmm, l'espressione è rigida, la struttura è caotica e manca di tensione..."
  },
  AvgDialog_15368_Content_55 = {
    Text = "Commentasti con aria da esperto. In realtà, sei sempre stato completamente estraneo all'arte. L'unico motivo per cui lo dicesti era che non sopportavi l'atteggiamento prepotente di August."
  },
  AvgDialog_15368_Content_56 = {
    Text = "Non ti piace."
  },
  AvgDialog_15368_Content_57 = {
    Text = "Sanga ti osservò con un sorriso, come una Madre amorevole di fronte ai balbettii insensati di un bambino."
  },
  AvgDialog_15368_Content_58 = {
    Text = "Hmm... Sebbene le nostre ragioni siano diverse, siamo giunti alla stessa conclusione."
  },
  AvgDialog_15368_Content_59 = {
    Text = "Un capolavoro!"
  },
  AvgDialog_15368_Content_6 = {
    Text = "Fammi da brava modella, lasciami finire quest'opera… poi potremo discutere del ritorno a casa."
  },
  AvgDialog_15368_Content_60 = {
    Text = "Davvero impareggiabile. Non riesco a trovarci un solo difetto."
  },
  AvgDialog_15368_Content_61 = {
    Text = "Come tutti gli altri, la tua mente fu completamente rapita da questa scultura — apparentemente libera nella forma, eppure meticolosamente precisa."
  },
  AvgDialog_15368_Content_62 = {
    Text = "Naturalmente, questo aveva anche a che fare con la scarsa Circolazione del Sangue causata dal mantenere la stessa posa per così tanto tempo."
  },
  AvgDialog_15368_Content_63 = {
    Text = "Un cervello privato di ossigeno non riesce a percepire le cose con chiarezza, ma l'adulazione non è mai sbagliata."
  },
  AvgDialog_15368_Content_64 = {
    Text = "Hai ragione. Non avere difetti — è proprio questo il suo problema più grande."
  },
  AvgDialog_15368_Content_65 = {
    Text = "Ora... cosa dovrei fare con te?"
  },
  AvgDialog_15368_Content_66 = {
    Text = "Sanga appoggiò il mento sulla mano, contemplando la scultura davanti a sé. Poi estese l'indice e diede un colpetto disinvolto alla scultura tra le sopracciglia—"
  },
  AvgDialog_15368_Content_67 = {Text = "CRASH—!!"},
  AvgDialog_15368_Content_68 = {
    Text = "La scultura tracciò un arco elegante nell'aria, per poi schiantarsi al suolo."
  },
  AvgDialog_15368_Content_69 = {
    Text = "Camille — o meglio, quel tuo volto carico d'ansia — si frantumò in innumerevoli pezzi in un istante."
  },
  AvgDialog_15368_Content_7 = {
    Text = "Questo è...?"
  },
  AvgDialog_15368_Content_70 = {Text = "..."},
  AvgDialog_15368_Content_71 = {
    Text = "Signorina Claudel, siete impazzita?!"
  },
  AvgDialog_15368_Content_72 = {
    Text = "August si lanciò verso di te, furioso."
  },
  AvgDialog_15368_Content_73 = {
    Text = "<Big:Questo era il più puro marmo pentelico, estratto da Paros—>"
  },
  AvgDialog_15368_Content_8 = {
    Text = "Una stanza in disordine."
  },
  AvgDialog_15368_Content_9 = {
    Text = "Sculture di varie argille Appiccicose, marmo e granito sono disposte alla rinfusa, trasformando questo spazio in uno studio di scultura improvvisato."
  },
  AvgDialog_15370_Content_1 = {
    Text = "Testa d'Oro"
  },
  AvgDialog_15370_Content_10 = {
    Text = "La pioggia si faceva sempre più forte, la tua gola sempre più secca.\nIn una tempesta come questa, dovevi urlare solo per sentire la tua stessa voce."
  },
  AvgDialog_15370_Content_11 = {
    Text = "Qui... Sono qui..."
  },
  AvgDialog_15370_Content_12 = {
    Text = "Qui@1hee hee hee qui qui@2qui qui qui..."
  },
  AvgDialog_15370_Content_13 = {
    Text = "Innumerevoli voci ti assalirono da ogni direzione. Incapace di resistere, crollasti infine sulla sabbia."
  },
  AvgDialog_15370_Content_14 = {
    Text = "Forse era tutto solo un tuo Fantasma... forse la Sig.ra Sanga era già scomparsa per sempre."
  },
  AvgDialog_15370_Content_15 = {
    Text = "<Shake:Sig.ra Sanga, per favore venga fuori... So che è qui...>"
  },
  AvgDialog_15370_Content_16 = {
    Text = "A un certo punto, la coscienza della Cameriera ti aveva gradualmente Divorato. Le sue speranze e le sue sofferenze avevano profondamente scosso il tuo cuore."
  },
  AvgDialog_15370_Content_17 = {
    Text = "Premi la fronte contro la sabbia umida, un gemito strano ti sfugge dalla gola."
  },
  AvgDialog_15370_Content_18 = {
    Text = "<Shake:Signorina Sanga...>"
  },
  AvgDialog_15370_Content_19 = {
    Text = "<Red:Qui... Sono qui...>"
  },
  AvgDialog_15370_Content_2 = {
    Text = "Caro Sig. Claudel:\n\n\"Morte della Sig.ra Coral\" è stato un enorme successo a Cité. Tutti ne parlano.\nGuardando questa scultura, non posso fare a meno di pensare a te.\n\nÈ fatta di un materiale bianco e opaco, molto simile alla Pietra che ricopriva tutto il tuo corpo e ti rendeva incapace di muoverti.\nMa non mi lasciano toccare la scultura@1\nTroverò un modo."
  },
  AvgDialog_15370_Content_20 = {
    Text = "...Cos'è questo?"
  },
  AvgDialog_15370_Content_21 = {
    Text = "Un freddo gelido raggiunge la punta delle tue dita."
  },
  AvgDialog_15370_Content_22 = {
    Text = "La foschia bianca si Diffonde ancora una volta tra le tue dita, come rampicanti viventi..."
  },
  AvgDialog_15370_Content_23 = {
    Text = "Lentamente, metodicamente..."
  },
  AvgDialog_15370_Content_24 = {
    Text = "Finalmente... questo momento è arrivato."
  },
  AvgDialog_15370_Content_25 = {
    Text = [[
Un paio di delicate scarpe di pelle da donna si fermano davanti a te.
Sanga impugna un coltello da intaglio, la sua espressione indifferente come sempre.]]
  },
  AvgDialog_15370_Content_26 = {
    Text = "Signorina Sanga... è davvero ancora viva..."
  },
  AvgDialog_15370_Content_27 = {
    Text = "Dipende da come definisci \"viva\"."
  },
  AvgDialog_15370_Content_28 = {
    Text = "Il tenue bagliore delle luci lontane avvolge dolcemente il corpo di Sanga. Ti sorride in silenzio."
  },
  AvgDialog_15370_Content_29 = {
    Text = "Sono tornata, Camille. Devi avermi aspettata a lungo, vero?"
  },
  AvgDialog_15370_Content_3 = {
    Text = "La Sig.ra Sanga ha finalmente realizzato il Suo desiderio. Ha scambiato la Sua stessa Vita per raggiungere l'arte immortale.\nMa per questo, ci ha lasciati per sempre.\nÈ passato quasi un mese dalla mostra, e mi manca ancora profondamente.\n\n<Yellow:La troverò e la riporterò a casa.>\n\nCamille@1\nA.F.2@1 Agosto"
  },
  AvgDialog_15370_Content_30 = {
    Text = "Angoscia, shock, estasi..."
  },
  AvgDialog_15370_Content_31 = {
    Text = "Innumerevoli emozioni ti travolgono il petto. Apri la bocca, solo per Scoprire che non riesci più a formulare una sillaba completa."
  },
  AvgDialog_15370_Content_32 = {
    Text = "Sanga@1... no@2..."
  },
  AvgDialog_15370_Content_33 = {Text = "Shh..."},
  AvgDialog_15370_Content_34 = {
    Text = "Lo sapevi? Il corpo umano è come un mondo tremante e pulsante."
  },
  AvgDialog_15370_Content_35 = {
    Text = "Quando carne e anima sono state temprate a sufficienza, al culmine dell'eruzione emotiva, subiscono la Metamorfosi nella scultura più perfetta..."
  },
  AvgDialog_15370_Content_36 = {
    Text = "Dita gelide accarezzano il tuo volto che si irrigidisce gradualmente."
  },
  AvgDialog_15370_Content_37 = {
    Text = "Sanga ti guardava con amore, i suoi occhi ardenti quasi ti incenerivano."
  },
  AvgDialog_15370_Content_38 = {
    Text = "Proprio come sei adesso..."
  },
  AvgDialog_15370_Content_39 = {
    Text = "Come sono adesso...? Sig.ra Sanga, è la D-melma..."
  },
  AvgDialog_15370_Content_4 = {
    Text = "Barcollasti fino alla riva. Non c'era nessuno qui — solo il cupo silenzio del mare e l'orizzonte nebbioso a farti compagnia."
  },
  AvgDialog_15370_Content_40 = {
    Text = "Shh... Silenzio."
  },
  AvgDialog_15370_Content_41 = {
    Text = "Per me, la morte non è mai stata qualcosa di spaventoso. Ciò che è davvero spaventoso è..."
  },
  AvgDialog_15370_Content_42 = {
    Text = "<Yellow:Perdere la bellezza, o chiudere gli occhi davanti ad essa.>"
  },
  AvgDialog_15370_Content_43 = {
    Text = "<Shake:Allontanati... Lasciami...>"
  },
  AvgDialog_15370_Content_44 = {
    Text = "Non essere sciocca, Camille."
  },
  AvgDialog_15370_Content_45 = {
    Text = "<Red:Sei già morta da molto tempo. Non ricordi?>"
  },
  AvgDialog_15370_Content_46 = {
    Text = "<Red:Morta...>"
  },
  AvgDialog_15370_Content_47 = {Text = "..."},
  AvgDialog_15370_Content_48 = {
    Text = "Ti sei tuffata ancora una volta nelle profondità dell'infinito Mare Profondo."
  },
  AvgDialog_15370_Content_49 = {
    Text = "Frammenti sigillati nella memoria affioravano come schiuma bianca alla deriva tutt'intorno, emergendo senza fine, incontrando senza fine la Distruzione..."
  },
  AvgDialog_15370_Content_5 = {
    Text = "Siete tutti la mia famiglia, per sempre."
  },
  AvgDialog_15370_Content_50 = {
    Text = "Nell'ultimo istante prima della morte, non hai avuto altra scelta che affrontare quelle crudeli Verità Nascoste—"
  },
  AvgDialog_15370_Content_51 = {
    Text = "È tutta colpa mia, Camille. È tutta colpa mia... Lascia che ti abbracci, e la Ferita non farà più male."
  },
  AvgDialog_15370_Content_52 = {
    Text = "Mia sorella è un vero genio. Diventerà sicuramente una grande artista immortalata nei libri!"
  },
  AvgDialog_15370_Content_53 = {
    Text = "*cough cough*... Smettila di ingannare te stessa, Camille..."
  },
  AvgDialog_15370_Content_54 = {
    Text = "Riportala qui da me@2C'è qualcosa che voglio chiederle faccia a faccia..."
  },
  AvgDialog_15370_Content_55 = {
    Text = "Ultime notizie, ultime notizie!!"
  },
  AvgDialog_15370_Content_56 = {
    Text = "Il <Yellow:caso dell'omicidio della scultura> che ha sconvolto il mondo miete un'altra vittima!"
  },
  AvgDialog_15370_Content_57 = {
    Text = "Ad oggi, i casi di <Yellow:Stordimento e Isteria> causati dalla visione della \"Morte della Sig.ra Coral\" sono saliti a 54..."
  },
  AvgDialog_15370_Content_58 = {
    Text = "<Red:Di questi, 23 si sono già suicidati…>"
  },
  AvgDialog_15370_Content_59 = {Text = "..."},
  AvgDialog_15370_Content_6 = {
    Text = "Non preoccuparti. Ti ho promesso che saremmo tornate a casa insieme, e non verrò meno alla mia parola."
  },
  AvgDialog_15370_Content_60 = {
    Text = "Quindi io… sapevo già tutto fin dall'inizio…"
  },
  AvgDialog_15370_Content_61 = {
    Text = "Rivedi quel palazzo oceanico bianco. Il plancton si raggruppa sul carbonato di calcio bianco, stirando pigramente i propri arti."
  },
  AvgDialog_15370_Content_62 = {
    Text = "Vedi anche quelle sculture bianche che vagano senza meta nell'acqua marina."
  },
  AvgDialog_15370_Content_63 = {
    Text = "Tra di esse ci sono alcuni volti familiari — il Sig. August, per esempio, ancora congelato nella rabbia e nella disperazione di quando si scagliò contro la scultura."
  },
  AvgDialog_15370_Content_64 = {
    Text = "Il Maestro Paul, per un altro, le sue orbite incavate colme di malinconia, come se avesse previsto da tempo il proprio Destino."
  },
  AvgDialog_15370_Content_65 = {
    Text = "L'acqua marina tiepida avvolge il tuo corpo, il suo ritmo incessante come una ninna nanna fluente."
  },
  AvgDialog_15370_Content_66 = {
    Text = "Prima che gli Occhi si Aprano l'Infante agita piccole mani\nStringendo figure d'argilla provando una gioia simile all'amore materno\nL'arte di plasmare e controllare da allora Si diffonde tra le dita\n\n<Red:Gli Occhi si Aprono e tutto ciò che si vede è nato dalla bellezza bellezza bellezza bellezza bellezza bellezza bellezza…>"
  },
  AvgDialog_15370_Content_67 = {
    Text = "Mani fredde ti abbracciano dolcemente. Sanga preme la Sua guancia morbida contro la tua spalla rigida."
  },
  AvgDialog_15370_Content_68 = {
    Text = "Riesci a sentirli? Quei canti — risuonano senza fine nella mia mente."
  },
  AvgDialog_15370_Content_69 = {
    Text = "È la <Yellow:Loro> Evocazione, il Destino ineluttabile che mi Richiama…"
  },
  AvgDialog_15370_Content_7 = {
    Text = "Non avrebbe infranto la Sua promessa... non l'avrebbe fatto."
  },
  AvgDialog_15370_Content_70 = {
    Text = "Ho seguito quei canti e alla fine ho trovato questo luogo."
  },
  AvgDialog_15370_Content_71 = {
    Text = "Il Miracolo e la bellezza dalle profondità degli Abissi Marini… Non ho nulla da offrire Loro se non te."
  },
  AvgDialog_15370_Content_72 = {Text = "Me...?"},
  AvgDialog_15370_Content_73 = {
    Text = "Sì, solo te — %player%."
  },
  AvgDialog_15370_Content_74 = {
    Text = "Pronunciò il tuo nome originale con chiarezza, senza alcun dubbio."
  },
  AvgDialog_15370_Content_75 = {
    Text = "Dal momento stesso in cui hai aperto gli Occhi, lo sapevo."
  },
  AvgDialog_15370_Content_76 = {
    Text = "<Yellow:Tu sei la vera \"Morte della Sig.ra Coral\".>"
  },
  AvgDialog_15370_Content_77 = {
    Text = "La coscienza svanisce. Il corallo bianco si è ormai diffuso su tutto il tuo corpo."
  },
  AvgDialog_15370_Content_78 = {
    Text = "Senti il tuo Sangue e la tua carne farsi pesanti, eppure, stranamente, i vostri corpi continuano a sollevarsi tra la schiuma e il corallo."
  },
  AvgDialog_15370_Content_79 = {
    Text = "<Shake:No… casa… tornare a casa…>"
  },
  AvgDialog_15370_Content_8 = {
    Text = "Sollevasti l'orlo della gonna e continuasti a correre lungo la lunga costa."
  },
  AvgDialog_15370_Content_80 = {
    Text = "Questa è casa tua, %player%."
  },
  AvgDialog_15370_Content_81 = {Text = "No..."},
  AvgDialog_15370_Content_82 = {
    Text = "Fissi con gli occhi spalancati il volto di Sanga, finché anche le tue pupille vengono ricoperte dal corallo grigio pallido."
  },
  AvgDialog_15370_Content_83 = {
    Text = "Sprofondi in un vuoto senza confini."
  },
  AvgDialog_15370_Content_84 = {
    Text = "Tutto il Mare Profondo, il corallo, le sculture si allontanano da te, eppure la sua voce rimane."
  },
  AvgDialog_15370_Content_85 = {
    Text = "Dolce come sempre, quella voce fredda e distaccata."
  },
  AvgDialog_15370_Content_86 = {
    Text = "Ti avevo promesso che ti avrei portato a casa con me..."
  },
  AvgDialog_15370_Content_87 = {
    Text = "Te l'avevo promesso."
  },
  AvgDialog_15370_Content_9 = {
    Text = "Sig.ra Sanga— Sig.ra Sanga—"
  },
  AvgDialog_15605_Content_1 = {
    Text = "Inizia il Test"
  },
  AvgDialog_15605_Content_10 = {
    Text = "Potresti essere entrato di nuovo nel passato del Risvegliatore? Ricordi che stavi leggendo dei documenti..."
  },
  AvgDialog_15605_Content_11 = {
    Text = "Perché non c'è nessuna risposta? Il modulo uditivo è malfunzionante?"
  },
  AvgDialog_15605_Content_12 = {
    Text = "Dipende— sei entrata di nascosto a smanettare con i moduli dopo che me ne sono andata ieri?"
  },
  AvgDialog_15605_Content_13 = {
    Text = "No no, questa volta davvero no, lo giuro!\nFammi riprovare— Uomo Tic-Tac, mi senti?"
  },
  AvgDialog_15605_Content_14 = {Text = "Sì."},
  AvgDialog_15605_Content_15 = {
    Text = "Guarda, guarda! La sua bocca si è mossa! Te l'avevo detto che avrebbe funzionato!"
  },
  AvgDialog_15605_Content_16 = {
    Text = "Il primo burattino meccanico completamente automatico al mondo in grado di seguire comandi vocali! Il primo! Completamente automatico!\nCaro Padre Supremo, portami pure ora, non ho più rimpianti nella vita!"
  },
  AvgDialog_15605_Content_17 = {
    Text = "Io di rimpianti ne ho parecchi, però—come non aver completato il test di risposta ai comandi, il test di flessibilità degli arti, il test di durata operativa..."
  },
  AvgDialog_15605_Content_18 = {
    Text = "Io—ma—tu non sei proprio per niente divertente."
  },
  AvgDialog_15605_Content_19 = {
    Text = "...test di coordinazione generale, test di equilibrio, test di carico..."
  },
  AvgDialog_15605_Content_2 = {
    Text = "Ingranaggi, nella norma; sistema idraulico, nessuna perdita di pressione rilevata; motore MF311000 funzionante normalmente, temperatura leggermente elevata ma entro i limiti accettabili."
  },
  AvgDialog_15605_Content_20 = {
    Text = "Ok, ok, ho capito! <Small:Sei ancora più meccanica dell'Uomo Tic-Tac.>"
  },
  AvgDialog_15605_Content_21 = {
    Text = "Cosa hai detto?"
  },
  AvgDialog_15605_Content_22 = {
    Text = "Ah—ora iniziamo il test base di ricezione e comprensione dei comandi!\nUomo Tic-Tac, sbatti le palpebre."
  },
  AvgDialog_15605_Content_23 = {
    Text = "Battito di ciglia"
  },
  AvgDialog_15605_Content_24 = {
    Text = [[
Segui il mio dito, bene.
Apri la bocca? Molto bene, che bravo bambino.]]
  },
  AvgDialog_15605_Content_25 = {Text = "...Uffa."},
  AvgDialog_15605_Content_26 = {
    Text = "Come! L'ho costruito pezzo per pezzo con le mie mani—è perfettamente ragionevole che mi chiami mamma."
  },
  AvgDialog_15605_Content_27 = {
    Text = "Sì, sì, Mamma Maniaca-degli-Ingranaggi. Porta il braccio sinistro del tuo caro bebè d'acciaio—è ora di iniziare il test degli arti."
  },
  AvgDialog_15605_Content_28 = {
    Text = "Un braccio composto da ingranaggi intricati e strutture meccaniche che non riusciresti nemmeno a comprendere è apparso brevemente nella tua Visione, poi è scomparso alla tua sinistra, seguito dalla destra."
  },
  AvgDialog_15605_Content_29 = {
    Text = "L'installazione di tutti e quattro gli arti è andata liscia. Hai alzato le braccia e disteso le gambe seguendo i comandi, e il sorriso sul volto di Erica si faceva sempre più radioso."
  },
  AvgDialog_15605_Content_3 = {
    Text = "Fonte di energia speciale S, stato stabile."
  },
  AvgDialog_15605_Content_30 = {
    Text = "Bene, ora il prossimo—Ah!"
  },
  AvgDialog_15605_Content_31 = {
    Text = "Un denso fumo nero si è levato sotto la tua linea visiva: qualcosa stava bruciando.\nHai guardato in basso e hai visto scintille elettriche e lampi di luce lampeggiare nella tua cavità addominale."
  },
  AvgDialog_15605_Content_32 = {
    Text = "L'estintore, Mei, Mei!"
  },
  AvgDialog_15605_Content_33 = {
    Text = "Fuori dai piedi!"
  },
  AvgDialog_15605_Content_34 = {
    Text = "La schiuma bianca spruzzò dall'estintore, e l'odore di bruciato si diffuse nell'aria.\nErica si precipitò in avanti e, incurante del calore rovente, staccò il motore."
  },
  AvgDialog_15605_Content_35 = {Text = "Erica!"},
  AvgDialog_15605_Content_36 = {
    Text = "Il motore annerito giaceva sul banco da lavoro. Erica riprese fiato, poi soffiò tardivamente sulle mani coperte di schiuma bianca."
  },
  AvgDialog_15605_Content_37 = {
    Text = "Ahi ahi ahi, scotta da morire!"
  },
  AvgDialog_15605_Content_38 = {
    Text = "Origin S, presto, controlla Origin S!"
  },
  AvgDialog_15605_Content_39 = {
    Text = "Erica si avvicinò al motore, le dita leggermente arrossate dal calore che sfioravano delicatamente l'involucro metallico."
  },
  AvgDialog_15605_Content_4 = {
    Text = "Phew— sei pronto?\nAutoma Uomo Tic-Tac, 13° test di attivazione, Inizio."
  },
  AvgDialog_15605_Content_40 = {
    Text = "Sembra che il cablaggio esterno sia andato in cortocircuito e abbia preso fuoco. L'interno dovrebbe essere intatto."
  },
  AvgDialog_15605_Content_41 = {
    Text = "Non preoccuparti, farò un controllo completo tra un momento."
  },
  AvgDialog_15605_Content_42 = {
    Text = "…Mi caccerai fuori di nuovo?"
  },
  AvgDialog_15605_Content_43 = {Text = "Mei…"},
  AvgDialog_15605_Content_44 = {
    Text = "Lo so che è stato sbagliato da parte mia sperimentare con Origin S senza permesso, ma conosci la nostra situazione coi fondi. Usare S come punto di svolta potrebbe farci guadagnare più tempo e materiali."
  },
  AvgDialog_15605_Content_45 = {
    Text = "Lasciami solo dare un'occhiata, per favore. Solo una volta. Giuro che non rivelerò alcuna informazione a nessuno.\nTi prego."
  },
  AvgDialog_15605_Content_46 = {
    Text = "Te l'ho detto, non c'è niente all'interno."
  },
  AvgDialog_15605_Content_47 = {
    Text = "…Non ti degni nemmeno più di inventare una scusa. È davvero necessario essere così diffidente con me?\nNon ho sempre pensato al nostro futuro?"
  },
  AvgDialog_15605_Content_48 = {Text = "..."},
  AvgDialog_15605_Content_49 = {
    Text = [[
Lascia perdere.
Vado a sedermi un po' da Joey's Diner. Fai quello che vuoi.]]
  },
  AvgDialog_15605_Content_5 = {
    Text = "Occhi Aperti"
  },
  AvgDialog_15605_Content_50 = {
    Text = "Il cancello si chiuse, i passi si allontanarono, ed Erica lasciò sfuggire un sospiro."
  },
  AvgDialog_15605_Content_51 = {
    Text = "Lei ancora… ma quella persona mi ha avvertita riguardo a Origin S…\nNon posso permettere che Mei condivida questo rischio con me."
  },
  AvgDialog_15605_Content_52 = {
    Text = "Si voltò di nuovo verso il motore, come per raccogliere tutta la sua determinazione."
  },
  AvgDialog_15605_Content_53 = {
    Text = "Troverò una soluzione. Aspettami, Mei."
  },
  AvgDialog_15605_Content_54 = {
    Text = "Svitò il coperchio ed estrasse un cilindro nero dall'interno."
  },
  AvgDialog_15605_Content_55 = {
    Text = "In quell'istante, il tuo mondo sprofondò nell'Oscurità."
  },
  AvgDialog_15605_Content_6 = {
    Text = "Uomo Tic-Tac, mi senti?"
  },
  AvgDialog_15605_Content_7 = {Text = "...Erica?"},
  AvgDialog_15605_Content_8 = {
    Text = "Quel volto familiare porta un'Espressione naturale del tutto diversa da quella nei tuoi ricordi. Più che un automa, sembra una persona in carne e ossa."
  },
  AvgDialog_15605_Content_9 = {
    Text = "...Cosa sta succedendo?"
  },
  AvgDialog_15606_Content_1 = {
    Text = "Così Parlò la Voce"
  },
  AvgDialog_15606_Content_10 = {
    Text = "Lei mormorò mentre se ne andava, lasciandoti con i motori e i pezzi sul banco da lavoro."
  },
  AvgDialog_15606_Content_11 = {
    Text = "Guardi le tue mani."
  },
  AvgDialog_15606_Content_12 = {
    Text = "Sottili, forti, il delicato rivestimento in porcellana accuratamente pulito e mantenuto. Sebbene fredde al tatto, sotto la luce fioca non erano diverse da quelle di una persona in carne e ossa."
  },
  AvgDialog_15606_Content_13 = {
    Text = "Queste sono le mani di Erica—le mani dell'<Blue:automa Erica> che conoscevi un tempo.\nSembra che tu abbia preso possesso del Suo corpo Successivo, diventando l'automa che Lei ha Creato."
  },
  AvgDialog_15606_Content_14 = {
    Text = "La Lei che hai appena visto era chiaramente un'umana.\nChe tipo di Esperienza potrebbe averLa trasformata in ciò che è diventata in Seguito?"
  },
  AvgDialog_15606_Content_15 = {Text = "Erica?"},
  AvgDialog_15606_Content_16 = {
    Text = "Sbatti le palpebre, e Mei è entrata nella Stanza a un certo punto senza che te ne accorgessi.\nIl suo sguardo percorre la Stanza prima di posarsi infine sul motore accanto a te."
  },
  AvgDialog_15606_Content_17 = {Text = "..."},
  AvgDialog_15606_Content_18 = {
    Text = "Dopo aver scrutato la Stanza una seconda volta, Lei chiude il Cancello e si dirige a passo svelto verso il motore."
  },
  AvgDialog_15606_Content_19 = {
    Text = "Mi dispiace, Erica."
  },
  AvgDialog_15606_Content_2 = {
    Text = "Uomo Tic-Tac, caro, mi senti?"
  },
  AvgDialog_15606_Content_20 = {
    Text = "Il coperchio si svita, e Mei afferra l'oggetto all'Interno. Questa volta lo vedi chiaramente—un cilindro metallico di non più di 5 centimetri di diametro, con la lettera \"S\" incisa sul lato."
  },
  AvgDialog_15606_Content_21 = {
    Text = "Una volta che Lei avrà estratto completamente il cilindro, perderai di nuovo conoscenza.\nQuindi, prima che ciò accada, devi—"
  },
  AvgDialog_15606_Content_22 = {
    Text = "Afferrare la Sua mano"
  },
  AvgDialog_15606_Content_23 = {Text = "SQUEAK!"},
  AvgDialog_15606_Content_24 = {
    Text = "Cosa sta succedendo, cosa sta succedendo—"
  },
  AvgDialog_15606_Content_25 = {
    Text = "Erica irrompe nella Stanza, la preoccupazione sul Suo volto si congela nell'istante in cui vede il cilindro nella mano di Mei."
  },
  AvgDialog_15606_Content_26 = {
    Text = "Mei, cosa stai facendo?"
  },
  AvgDialog_15606_Content_27 = {
    Text = "Cosa stai facendo!"
  },
  AvgDialog_15606_Content_28 = {
    Text = "Stavo solo provando… Questa fonte di energia… Funziona davvero…"
  },
  AvgDialog_15606_Content_29 = {
    Text = "Fissando il piccolo cilindro che aveva alimentato l'intero motore e tutti i macchinari collegati, gli occhi di Mei si spalancarono."
  },
  AvgDialog_15606_Content_3 = {
    Text = "Risvegliato dall'Oscurità eterna, Scopri di trovarti ancora nell'officina. Il motore carbonizzato è ancora sul banco da lavoro, collegato al tuo corpo da cavi di vario spessore."
  },
  AvgDialog_15606_Content_30 = {
    Text = "Sai cosa significa questo, Erica?"
  },
  AvgDialog_15606_Content_31 = {
    Text = "Significa che è pericoloso. Te l'ho detto, Mei, non puoi semplicemente metterti a giocherellare con—"
  },
  AvgDialog_15606_Content_32 = {
    Text = "No, no, ascolta, Erica— Questa cosa, questa cosina minuscola, può fornire un approvvigionamento energetico a lungo termine senza perdite e senza emissioni. Non capisci?"
  },
  AvgDialog_15606_Content_33 = {
    Text = "Carbone, petrolio— non sono nulla in confronto. Se riusciamo a produrla in serie, riscriveremo l'intera infrastruttura energetica dell'umanità. Entreremo nella storia!"
  },
  AvgDialog_15606_Content_34 = {
    Text = "Devi dirmi come l'hai realizzata. Devi!"
  },
  AvgDialog_15606_Content_35 = {
    Text = "Erica, dove stai andando? Come sarebbe che non sai come è fatta? Erica!"
  },
  AvgDialog_15606_Content_36 = {
    Text = "L'investitore ha detto che, non appena vedrà un prototipo, sarà disposto a fornirci finanziamenti ingenti, persino un laboratorio dedicato."
  },
  AvgDialog_15606_Content_37 = {
    Text = "Perché non vuoi ascoltare— Non so come è fatta questa cosa. Non sono in grado di costruirla!"
  },
  AvgDialog_15606_Content_38 = {
    Text = "Ho passato l'età in cui si crede alle favole, Erica. Un <Blue:Misterioso Negoziante>? Se vuoi liquidarmi, almeno trovati una scusa migliore."
  },
  AvgDialog_15606_Content_39 = {
    Text = "Sei chiaramente in grado di creare qualcosa di così incredibile. Perché non riesci a vedere il quadro generale?"
  },
  AvgDialog_15606_Content_4 = {Text = "Ti sento."},
  AvgDialog_15606_Content_40 = {
    Text = "Perché insisti a rinchiuderti in un posto come questo, armeggiando con rottami di ferro?"
  },
  AvgDialog_15606_Content_41 = {
    Text = "Le parole di Mei colpirono Erica come uno schiaffo in pieno volto. Fissò la sua compagna, la sua socia, incapace di credere a ciò che stava sentendo."
  },
  AvgDialog_15606_Content_42 = {
    Text = "…Rottami. È davvero quello che pensi?"
  },
  AvgDialog_15606_Content_43 = {
    Text = "Pensavo che condividessimo lo stesso sogno."
  },
  AvgDialog_15606_Content_44 = {
    Text = "Mei strinse i denti e serrò la presa sul cilindro."
  },
  AvgDialog_15606_Content_45 = {
    Text = "Guarda in faccia la realtà, Erica. Nessuno è più disposto a spendere soldi per gli automi. La nuova energia... quella è la nostra via d'uscita."
  },
  AvgDialog_15606_Content_46 = {
    Text = "…Posa la fonte di energia speciale."
  },
  AvgDialog_15606_Content_47 = {
    Text = "Pensa a tutto quello che potremmo avere: più fondi, più risorse.\nCon quelli, potresti continuare il tuo sogno. Con quelli, potresti—"
  },
  AvgDialog_15606_Content_48 = {
    Text = "Ho detto posala!"
  },
  AvgDialog_15606_Content_49 = {
    Text = "Erica si lanciò in avanti per strappargliela di mano. Mei non riuscì a schivare in tempo e andò a sbattere contro un armadietto vicino."
  },
  AvgDialog_15606_Content_5 = {
    Text = "Scusa per quello. Ti prometto che il prossimo sarà il modulo vocale! Abbi solo un po' di pazienza, va bene?"
  },
  AvgDialog_15606_Content_50 = {Text = "!!"},
  AvgDialog_15606_Content_51 = {
    Text = "Bottiglie e barattoli pieni di vari reagenti e combustibili caddero a terra. Ti gettasti in avanti per proteggere entrambe, e un istante dopo—"
  },
  AvgDialog_15606_Content_6 = {Text = "Annuire."},
  AvgDialog_15606_Content_7 = {
    Text = "Che il Padre Supremo sia lodato, è fantastico. Avevo davvero paura che qualche filo si fosse bruciato."
  },
  AvgDialog_15606_Content_8 = {
    Text = "Lei emise un sospiro di sollievo, poi fece un grande sbadiglio come se la stanchezza l'avesse appena raggiunta."
  },
  AvgDialog_15606_Content_9 = {
    Text = "Devo andare a prendere una tazza di caffè, e la cena..."
  },
  AvgDialog_15607_Content_1 = {
    Text = "Il cannone al plasma sparò contro la mano gigante. L'Argento si liberò dal palmo sotto l'Impatto e cadde silenziosamente a terra."
  },
  AvgDialog_15607_Content_10 = {
    Text = "Cosa... ho... fatto..."
  },
  AvgDialog_15607_Content_11 = {
    Text = "Non capisci ancora. Ma non importa—hai già acceso questa rivoluzione della vita e dell'anima—questa <Red:\"Trascendenza\">.\nMuori in pace. Mi assicurerò che il mondo intero ricordi il tuo contributo."
  },
  AvgDialog_15607_Content_12 = {
    Text = "Erica chiuse gli occhi."
  },
  AvgDialog_15607_Content_13 = {
    Text = "Hai... ragione, hai sempre avuto..."
  },
  AvgDialog_15607_Content_14 = {
    Text = "Lacrime nere scivolarono dagli angoli dei suoi occhi. Arricciò il naso, poi improvvisamente si voltò a guardarti."
  },
  AvgDialog_15607_Content_15 = {
    Text = "Avrei dovuto... ascoltarti... fin dall'inizio... Non... avrei dovuto prendere questa cosa..."
  },
  AvgDialog_15607_Content_16 = {
    Text = "La mia sanità... la mia... aiutami... quest'ultima volta..."
  },
  AvgDialog_15607_Content_17 = {
    Text = "Esiste davvero una terza coscienza in questo corpo, o sei semplicemente la manifestazione del suo senso di colpa sotto l'influenza della Dissoluzione? Non hai modo di saperlo."
  },
  AvgDialog_15607_Content_18 = {
    Text = "Tende la mano verso di te."
  },
  AvgDialog_15607_Content_19 = {
    Text = "Aiutami... salva..."
  },
  AvgDialog_15607_Content_2 = {
    Text = "Dopo un momento di immobilità, la mano gigante crollò e si disintegrò. Melma nera si riversò come una pioggia torrenziale — ti attraversò, ma macchiò di nero il fantasma di Erica."
  },
  AvgDialog_15607_Content_20 = {
    Text = "Tutto ciò che sai è che la aiuterai, e sarai un Testimone Silenzioso della sua fine come \"essere umano\"."
  },
  AvgDialog_15607_Content_21 = {
    Text = "Prenderle la mano"
  },
  AvgDialog_15607_Content_22 = {
    Text = "Ti guarda sorpresa, come se non avesse mai immaginato di poter davvero toccare la propria \"sanità mentale\"."
  },
  AvgDialog_15607_Content_23 = {Text = "Annuire"},
  AvgDialog_15607_Content_24 = {
    Text = "Ti guarda sorpresa, come se non si fosse mai aspettata che la propria \"coscienza\" potesse darle una risposta."
  },
  AvgDialog_15607_Content_25 = {Text = "Grazie..."},
  AvgDialog_15607_Content_26 = {
    Text = "Il fantasma esplode e si dissipa come una bolla, lasciando solo la sfera di luce tremolante, che emette ancora il suo ultimo bagliore."
  },
  AvgDialog_15607_Content_27 = {
    Text = "Culli tra le braccia la sfera di luce, ora rimpicciolita, e volgi lo sguardo verso l'Argento in frantumi lì vicino."
  },
  AvgDialog_15607_Content_28 = {
    Text = "Ce la farai."
  },
  AvgDialog_15607_Content_3 = {
    Text = "È... finita..."
  },
  AvgDialog_15607_Content_4 = {
    Text = "Lo pensi davvero?"
  },
  AvgDialog_15607_Content_5 = {Text = "!?"},
  AvgDialog_15607_Content_6 = {
    Text = "Te l'ho detto, una volta entrata in questo cuore d'Argento, la vera immortalità mi attende."
  },
  AvgDialog_15607_Content_7 = {
    Text = "Lotta quanto vuoi. La sostanza nera finirà per cancellarti, e allora potrò portare la vera <Red:\"Metamorfosi\"> al mondo — A tutti sarà concessa l'immortalità, a tutti sarà concessa la vita eterna."
  },
  AvgDialog_15607_Content_8 = {
    Text = "Quella è... morte... non..."
  },
  AvgDialog_15607_Content_9 = {
    Text = "Sempre più nero consumava il Suo corpo. Erica si piegò in due dall'agonia, il Suo spirito sull'orlo del collasso."
  },
  AvgDialog_15608_Content_1 = {
    Text = "Questo è... il Mondo degli spiriti?"
  },
  AvgDialog_15608_Content_2 = {
    Text = "Oh mio dio, ma che diavolo, che diavolo sta..."
  },
  AvgDialog_15608_Content_3 = {
    Text = "Una voce... Erica!"
  },
  AvgDialog_15609_Content_1 = {
    Text = "No, Erica, non credergli!"
  },
  AvgDialog_15609_Content_10 = {
    Text = "Un corpo di Caro non è altro che Catene per l'anima. Solo liberando l'anima potrà unirsi a noi.\nSolo un corpo e una mente di metallo possono concederci l'eternità."
  },
  AvgDialog_15609_Content_11 = {
    Text = "Le dita si strinsero, e un'espressione di agonia apparve sul volto di Mei."
  },
  AvgDialog_15609_Content_12 = {
    Text = "<Shake:Tu… pazza…>"
  },
  AvgDialog_15609_Content_13 = {
    Text = "Un'altra mano tremante apparve nell'inquadratura. Erica afferrò il proprio polso e lo torse, staccando la mano incontrollabile e gettandola da parte."
  },
  AvgDialog_15609_Content_14 = {
    Text = "La mano gigante si fermò per un istante, come se fosse in qualche modo perplessa."
  },
  AvgDialog_15609_Content_15 = {
    Text = "Perché resistermi? Le sto donando la Rinascita."
  },
  AvgDialog_15609_Content_16 = {
    Text = "Fantasma, è tutto, un Fantasma."
  },
  AvgDialog_15609_Content_17 = {
    Text = "Erica tenne tra le braccia Mei priva di sensi e si alzò lentamente in piedi."
  },
  AvgDialog_15609_Content_18 = {
    Text = "Devo portarla in ospedale. Devo… tenerla in vita."
  },
  AvgDialog_15609_Content_19 = {
    Text = "Si mise Mei in spalla, attraversò lo studio distrutto dall'esplosione e si diresse verso il Portale poco distante."
  },
  AvgDialog_15609_Content_2 = {
    Text = "Erica, Erica!"
  },
  AvgDialog_15609_Content_3 = {
    Text = "Mentre combattevi il nemico davanti a te, un Mostro fatto di melma ti ha aggirato alle spalle e si è lanciato sulla sfera di luce che rappresentava lo spirito di Erica."
  },
  AvgDialog_15609_Content_4 = {
    Text = "Come inchiostro versato nell'acqua, l'Oscurità si diffuse all'interno della sfera di luce, ricoprendo tutto al suo Interno.\nLa sfera di luce iniziò a Lampeggiare."
  },
  AvgDialog_15609_Content_5 = {
    Text = "Cosa sta succedendo, le mie mani... da sole..."
  },
  AvgDialog_15609_Content_6 = {
    Text = "Sei tu a fare questo? Smetti, <Big:smettila!>"
  },
  AvgDialog_15609_Content_7 = {
    Text = "Perché, non vuoi più salvarla?"
  },
  AvgDialog_15609_Content_8 = {
    Text = "Stai cercando di strangolarla! Lasciala andare!"
  },
  AvgDialog_15609_Content_9 = {
    Text = "Tra lampi di Oscurità e luce, vedesti la mano meccanica avvicinarsi sempre di più al collo di Mei."
  },
  AvgDialog_15610_Content_1 = {
    Text = "La linea difensiva di una sola persona era quasi Nulla. Non importava quanti Mostri frantumavi, i loro corpi fatti di melma potevano ricomporsi rapidamente, sgusciarti oltre e balzare dritti nella sfera di luce."
  },
  AvgDialog_15610_Content_10 = {
    Text = "Plasma dorato crepitò attraverso l'ombra, e la forma di Erica divenne sempre più solida."
  },
  AvgDialog_15610_Content_11 = {
    Text = "Alzò la mano e disperse i Mostri davanti a te con il plasma. La mano gigante si mosse leggermente ed emise un sospiro."
  },
  AvgDialog_15610_Content_12 = {
    Text = "Volevo solo ripagarti per avermi riportato indietro e avermi dato un nuovo corpo. Perché devi farmi del Danno?"
  },
  AvgDialog_15610_Content_13 = {
    Text = "Riportato indietro? Cosa intendi con riportato indietro? Io non ho mai..."
  },
  AvgDialog_15610_Content_14 = {
    Text = "Questa cosa può alimentare il mio burattino?"
  },
  AvgDialog_15610_Content_15 = {
    Text = "Erica teneva il tubo di metallo nero con sospetto, esaminandolo da ogni angolazione."
  },
  AvgDialog_15610_Content_16 = {
    Text = "Se temi che non possa sostenere il funzionamento prolungato del burattino, non c'è bisogno di preoccuparsi.\nUna cosa del genere è più che sufficiente per alimentare qualcosa di molto più complesso e massiccio."
  },
  AvgDialog_15610_Content_17 = {
    Text = "Stai dicendo che qualcun altro sta usando questo tipo di fonte di energia?"
  },
  AvgDialog_15610_Content_18 = {
    Text = "Qualcosa di simile? Sì. Ma una copia esatta? Assolutamente impossibile."
  },
  AvgDialog_15610_Content_19 = {
    Text = "Quello che volevi era una \"fonte di energia unica nel suo genere\", e il negozietto di Daffodil non delude mai i suoi clienti."
  },
  AvgDialog_15610_Content_2 = {
    Text = "Maled... izione..."
  },
  AvgDialog_15610_Content_20 = {
    Text = "Oh, e un consiglio da amica — non farti prendere dalla curiosità sulla sua costruzione o sul suo funzionamento.\nUna volta aperto il vaso di Pandora, dovrai sopportarne le conseguenze da sola."
  },
  AvgDialog_15610_Content_21 = {
    Text = "Mi dispiacerebbe vedere un genio come te morire giovane. Oltre al proiettore, ho così tante altre idee che voglio realizzare."
  },
  AvgDialog_15610_Content_22 = {
    Text = "In attesa della tua prossima visita, Erica."
  },
  AvgDialog_15610_Content_23 = {
    Text = "No, è impossibile. All'interno della Fonte di Energia S, c'era chiaramente solo—"
  },
  AvgDialog_15610_Content_24 = {
    Text = "Un minuscolo <Yellow:frammento d'Argento>, giusto?\nUna piccola meraviglia — non solo può alimentare macchinari, ma può anche preservare le anime degli esseri viventi."
  },
  AvgDialog_15610_Content_25 = {
    Text = "Il tuo spirito si è già fuso con questo corpo grazie alla sostanza nera. Finché entrerai nel <Yellow:cuore d'Argento> prima di essere corrosa da loro, potrai raggiungere la vera immortalità. Tu e io.\n\nCome mia \"Madre\" in questa vita, hai il diritto di condividerla con me.\nPeccato che tu debba essere così ostinata."
  },
  AvgDialog_15610_Content_26 = {
    Text = "Non ho altra scelta che lasciare che la <Yellow:sostanza nera> ti Divori."
  },
  AvgDialog_15610_Content_27 = {
    Text = "La mano gigante si mise improvvisamente in movimento, aprendo le cinque dita per rivelare il palmo. L'Argento al suo interno era coperto di crepe, eppure brillava ancora intensamente."
  },
  AvgDialog_15610_Content_28 = {
    Text = "Addio, mia effimera creatrice."
  },
  AvgDialog_15610_Content_3 = {
    Text = "La sfera di luce lampeggiò di nuovo, e vedesti le gambe di Erica tremare in modo incontrollabile."
  },
  AvgDialog_15610_Content_4 = {
    Text = "Gli ingranaggi si incastrarono e si strinsero l'uno contro l'altro, e archi di elettricità giallo brillante lampeggiarono tra i tubi e i supporti."
  },
  AvgDialog_15610_Content_5 = {
    Text = "Smetti di resistere. Cedi a me il controllo del tuo corpo."
  },
  AvgDialog_15610_Content_6 = {
    Text = "Non vuoi più salvarla? Non vuoi che ottenga l'eternità insieme a te?"
  },
  AvgDialog_15610_Content_7 = {
    Text = "Altri archi di elettricità apparvero nella scena."
  },
  AvgDialog_15610_Content_8 = {
    Text = "Particelle scintillanti si dissiparono dalla sfera di luce, raccogliendosi insieme per formare un fantasma umanoide."
  },
  AvgDialog_15610_Content_9 = {Text = "E-Erica?!"},
  AvgDialog_15611_Content_1 = {
    Text = "Perché salvarla?\nHa barattato il tuo Sogno per la propria carriera. Non provi davvero alcun Risentimento?"
  },
  AvgDialog_15611_Content_10 = {
    Text = "Ma presto ho capito: questo non è un disastro, non è un Fantasma, ma un'opportunità per l'umanità."
  },
  AvgDialog_15611_Content_11 = {
    Text = "Nessun dolore né morte nelle macchine; nelle macchine, possiamo creare un vero Regno divino, migliore del vostro falso.\n\nPossiamo trascendere la vita del Caro."
  },
  AvgDialog_15611_Content_12 = {
    Text = "Melma nera gocciolò ancora una volta dalla mano gigante. Le gocce tremavano e si contorcevano, strisciando in avanti mentre si fondevano l'una con l'altra, fremendo di Euforia per la visione inquietante dipinta dalla voce."
  },
  AvgDialog_15611_Content_13 = {
    Text = "La voce raggiunse un crescendo. La mano gigante oscillò, scagliando altra melma, altri Mostri."
  },
  AvgDialog_15611_Content_14 = {
    Text = "Possiamo diventare noi stessi degli dèi."
  },
  AvgDialog_15611_Content_15 = {
    Text = "La melma accelerò improvvisamente, lanciandosi ancora una volta verso la sfera di luce dietro di te."
  },
  AvgDialog_15611_Content_2 = {
    Text = "Lei ha solo… preso una decisione sbagliata.\nQuando si sveglierà, ne parleremo, e tutto potrà risolversi."
  },
  AvgDialog_15611_Content_3 = {
    Text = "La cabina telefonica più vicina è a un km di distanza. Non può permettersi di aspettare."
  },
  AvgDialog_15611_Content_4 = {
    Text = "Mi dispiace, preferisco credere nella volontà di sopravvivenza dell'umanità piuttosto che nelle tue sciocchezze sulla \"liberazione delle anime\"."
  },
  AvgDialog_15611_Content_5 = {
    Text = "Se le mie parole sono false, come spieghi il tuo Stato attuale?\nIl tuo corpo di Caro si è ridotto in pezzi, eppure il tuo spirito persiste, e può persino controllare questo corpo per continuare a vivere.\n\nNon è forse una prova sufficiente di ciò che dico?"
  },
  AvgDialog_15611_Content_6 = {
    Text = "<Big:Non puoi essere sicura che sia questo il motivo per cui sono diventata così!>"
  },
  AvgDialog_15611_Content_7 = {
    Text = "Erica si fermò. Sembrava voler prendere un respiro, ma aveva già perso gli organi per farlo."
  },
  AvgDialog_15611_Content_8 = {
    Text = "Ma che sto facendo, a discutere con un Fantasma… Non ascoltare, non pensare, è un Fantasma, un Fantasma causato dai fumi tossici—"
  },
  AvgDialog_15611_Content_9 = {
    Text = [[
Hai paura, quindi cerchi di fuggire.
Capisco. Quando avevo appena completato la mia <Red:"Metamorfosi">, ero piena di paura proprio come te.]]
  },
  AvgDialog_15612_Content_1 = {
    Text = "Un ritmo invisibile ti circonda, ti avvolge. Deboli punti di luce tremolano in lontananza, appaiono Fragili e incredibilmente distanti."
  },
  AvgDialog_15612_Content_10 = {
    Text = "<Gray:Non è possibile... Potrebbe essere...>"
  },
  AvgDialog_15612_Content_11 = {
    Text = "Potrebbe essere che in questo momento tu ed Erica condividiate lo stesso corpo?\nPotrebbe essere questa la ragione per cui è diventata un automa meccanico?"
  },
  AvgDialog_15612_Content_12 = {
    Text = "<Gray:Ma come potrebbe un'esplosione ordinaria avere questo tipo di Effetto?>"
  },
  AvgDialog_15612_Content_13 = {
    Text = "Vuoi salvarla?"
  },
  AvgDialog_15612_Content_14 = {Text = "?!"},
  AvgDialog_15612_Content_15 = {
    Text = "Una voce appare dal nulla—onnipresente, eppure impossibile da localizzare.\nTi guardi intorno. Nell'immenso e vuoto Mondo degli spiriti, una sagoma sta iniziando a emergere."
  },
  AvgDialog_15612_Content_16 = {
    Text = "Chi, chi c'è?"
  },
  AvgDialog_15612_Content_17 = {
    Text = "Sono la volontà che risponde al tuo richiamo, la vita a cui hai donato un corpo nuovo di zecca."
  },
  AvgDialog_15612_Content_18 = {
    Text = "Potresti chiamarmi la tua Reliquia, e tu sei la mia \"Madre\" in questa vita."
  },
  AvgDialog_15612_Content_19 = {
    Text = "Una mano enorme si materializzò dietro la sfera di luce che rappresentava lo spirito di Erica, le sue dita che fremevano e tremavano, gocciolando melma nera."
  },
  AvgDialog_15612_Content_2 = {
    Text = "Mei, Mei! Svegliati, Mei!"
  },
  AvgDialog_15612_Content_20 = {
    Text = "…Uomo Tic-Tac…?"
  },
  AvgDialog_15612_Content_21 = {
    Text = "Mi piace quel nome. Sì, chiamami l'Uomo Tic-Tac.\nCome ricompensa per avermi concesso la Rinascita, posso aiutarti a salvare Lei.\nDevi solo lasciarti andare."
  },
  AvgDialog_15612_Content_22 = {
    Text = "Lasciati andare, e poi, lascia tutto a me."
  },
  AvgDialog_15612_Content_23 = {
    Text = "La melma accumulata sul terreno si agitò all'improvviso. Si fusero l'una con l'altra, coalizzandosi in forme contorte e individuali, strisciando e avanzando verso la luce."
  },
  AvgDialog_15612_Content_3 = {
    Text = "Ti affretti verso la fonte della voce."
  },
  AvgDialog_15612_Content_4 = {
    Text = "È una sfera di luce sospesa a mezz'aria. Attraverso di essa, vedi un volto coperto di Sangue e polvere: il volto di Mei."
  },
  AvgDialog_15612_Content_5 = {
    Text = "Sembra essere in Svenimento. Anche mentre una mano pallida la scuote delicatamente, non c'è alcuna risposta."
  },
  AvgDialog_15612_Content_6 = {
    Text = "<Gray:Quella mano...>"
  },
  AvgDialog_15612_Content_7 = {
    Text = "Abbassi lo sguardo e confermi il sospetto nella tua mente: la mano mostrata nella sfera di luce è identica alla tua.\nÈ la mano di un automa, che ora si muove secondo la volontà di qualcun altro."
  },
  AvgDialog_15612_Content_8 = {
    Text = "Dannazione, Mei! Dobbiamo andarcene da qui, Mei!"
  },
  AvgDialog_15612_Content_9 = {
    Text = "La mano meccanica si sposta sulla spalla di Mei. La scena all'interno della sfera di luce cambia, rivelando il laboratorio ancora in fiamme, come se qualcuno si stesse guardando intorno freneticamente."
  },
  AvgDialog_15613_Content_1 = {
    Text = "Un finale brillante"
  },
  AvgDialog_15613_Content_10 = {
    Text = "Piede destro."
  },
  AvgDialog_15613_Content_11 = {
    Text = "Erica crolla in avanti sulle ginocchia. I cortocircuiti troppo frequenti hanno privato la sua gamba sinistra di energia, costringendola a sorreggersi a malapena con il braccio destro, privo della mano."
  },
  AvgDialog_15613_Content_12 = {
    Text = [[
Appoggia con cura Mei contro la cabina telefonica, poi striscia all'interno carponi.
La corrente elettrica forza l'attivazione del telefono. Preme il pulsante di chiamata d'emergenza e comunica la posizione della cabina.]]
  },
  AvgDialog_15613_Content_13 = {
    Text = "Così... lei... sarà al sicuro..."
  },
  AvgDialog_15613_Content_14 = {
    Text = "E... adesso... cosa..."
  },
  AvgDialog_15613_Content_15 = {
    Text = "Lo sai cos'è."
  },
  AvgDialog_15613_Content_16 = {
    Text = "Ora ricordi: il contenuto del fascicolo che hai letto prima di entrare in questo luogo."
  },
  AvgDialog_15613_Content_17 = {
    Text = "A.F. 297, @1/@1, 03:47. Un'esplosione non identificata si è verificata a sud-est della città di @1@2@1, provincia di @3, La Repubblica di Aglo. L'onda d'urto ha provocato un terremoto locale di magnitudo 3.8, con tremori percepibili fino ai villaggi a 5 km dalla città di @1@2@1.\n\n…\n\nA.F. 297, @1/@1. 13 componenti sono stati recuperati nella foresta a sud-est della città di @3@1@2@1, provincia di @3, La Repubblica di Aglo, numerati da A101 ad A114. Tra questi, i componenti A108, A109 e A113 erano gravemente danneggiati e sono stati consegnati a Doll per la ricostruzione progettuale.\nLa squadra investigativa ha recuperato una serie di progetti dal Sentiero @2 N. @1. I disegni corrispondono ai componenti residui trovati sul luogo dell'esplosione e si sospetta siano i progetti del dispositivo esplosivo. Anch'essi sono stati consegnati a Doll per l'analisi."
  },
  AvgDialog_15613_Content_18 = {
    Text = "Senti il suono del vento che accarezza le foglie."
  },
  AvgDialog_15613_Content_19 = {
    Text = "La sfera di luce si è fatta molto fioca, quasi confondendosi con l'oscurità circostante."
  },
  AvgDialog_15613_Content_2 = {
    Text = "Piede sinistro."
  },
  AvgDialog_15613_Content_20 = {
    Text = "Anche se salvi il suo corpo Caro, e allora?\nLa morte arriverà comunque. Quando accadrà, ti ringrazierà, o ti odierà per averle tolto la possibilità dell'immortalità?\n\nLascia andare, Erica. Lascia che sia io a prendere il controllo di questo corpo.\nLe concederò la <Red:\"Metamorfosi\"> e le darò un futuro migliore."
  },
  AvgDialog_15613_Content_21 = {
    Text = "Io… ho sempre pensato… che sarei morta in un'esplosione…\nMi dispiace… di… trascinarti con me…"
  },
  AvgDialog_15613_Content_22 = {
    Text = "…Cosa stai facendo?"
  },
  AvgDialog_15613_Content_23 = {
    Text = "Stai zitto… demone… Non sto… parlando con te…"
  },
  AvgDialog_15613_Content_24 = {
    Text = "L'immagine che appare all'interno della sfera di luce è una mano meccanica, già coperta di segni di bruciatura, da cui continua a fuoriuscire elettro-plasma."
  },
  AvgDialog_15613_Content_25 = {
    Text = "A un certo punto, la mano aveva afferrato diversi cavi, ricoperti di melma nera."
  },
  AvgDialog_15613_Content_26 = {
    Text = "Mi dispiace, Uomo Tic-Tac… Alla fine… devo… distruggerti con le mie stesse mani…"
  },
  AvgDialog_15613_Content_27 = {
    Text = "Il silenzio cala tra voi.\nNon sei ancora certo della tua Identità in questo Sogno, e lei non sembra aspettare una risposta."
  },
  AvgDialog_15613_Content_28 = {Text = "*sigh*..."},
  AvgDialog_15613_Content_29 = {
    Text = "Che… peccato…"
  },
  AvgDialog_15613_Content_3 = {
    Text = "Piede destro."
  },
  AvgDialog_15613_Content_30 = {
    Text = "Strappa con tutte le sue forze."
  },
  AvgDialog_15613_Content_32 = {
    Text = "Ti risvegli di soprassalto, ritrovandoti nella tua familiare Stanza."
  },
  AvgDialog_15613_Content_33 = {
    Text = "Qualcuno sta bussando alla tua porta."
  },
  AvgDialog_15613_Content_34 = {Text = "Entra."},
  AvgDialog_15613_Content_35 = {
    Text = "Buon pomeriggio, Custode. Hai un messaggio da Doll. Desideri riceverlo?"
  },
  AvgDialog_15613_Content_36 = {
    Text = "Che nuova funzione ha escogitato Doll per te stavolta… Ricevi."
  },
  AvgDialog_15613_Content_37 = {
    Text = "Beep— Ti ricordi che giorno è, %player%? Due parole per te: il test."
  },
  AvgDialog_15613_Content_38 = {Text = "…Oh no."},
  AvgDialog_15613_Content_39 = {
    Text = "Ti suggerisco di presentarti in aula entro cinque minuti, o non posso garantire come sarà la tua vita di addestramento per i prossimi 30 giorni. Forse il programma di allenamento fisico verrà raddoppiato?"
  },
  AvgDialog_15613_Content_4 = {
    Text = "A ogni passo, volano scintille. A ogni passo, si sente il suono stridente di ingranaggi che grattano l'uno contro l'altro."
  },
  AvgDialog_15613_Content_40 = {
    Text = "Beep— Fine del messaggio. Desideri rispondere?"
  },
  AvgDialog_15613_Content_41 = {
    Text = "Rispondere?! Non c'è tempo, devo correre!!"
  },
  AvgDialog_15613_Content_42 = {
    Text = "La figura del Custode svanì in fondo al corridoio. Erica si voltò e guardò i documenti sparsi sulla scrivania."
  },
  AvgDialog_15613_Content_43 = {
    Text = "Dopo il Diluvio 298, @1/@2, Dipartimento di Studi sul Risveglio dell'Università di Mythag, @3\nCompletato il restauro del torso dell'automa E basato sul progetto T-38, numero di serie EA301881.\nQuesto è il nostro 10° tentativo di restauro. Devo ammirare chiunque abbia originariamente progettato e Forgiato questo automa— è straordinariamente intricato ed elegante. Centinaia e migliaia di ingranaggi e cuscinetti si incastrano tra loro, eseguendo insieme una magnifica sinfonia di ingegneria meccanica. Anche ora, mentre è fermo e immobile, riesco a percepire una vitalità unica al suo interno.\nSfortunatamente, non abbiamo ancora trovato la chiave per il progetto del motore— un cilindro di 5 centimetri di diametro e 10 centimetri di lunghezza. Dovrebbe essere il nucleo energetico dell'intero automa, eppure non ho mai visto nulla di tali dimensioni capace di alimentare un meccanismo così complesso…\nSpero che il Professor Doll riesca a trovare una soluzione. Non vedo l'ora di vederlo prendere davvero vita."
  },
  AvgDialog_15613_Content_44 = {
    Text = "Dopo il Diluvio 298, @1/@2, Dipartimento di Studi sul Risveglio dell'Università di Mythag, @3\nCompletato il restauro del motore, numero di serie MF311028.\nSebbene abbiamo incontrato parecchi ostacoli lungo il percorso (Per l'Onnipotente, abbiamo fatto ben 28 tentativi, 28!), l'ipotesi finale del Professor Doll si è rivelata corretta— il nucleo energetico del motore è un Argento.\nDopo aver testato molteplici Argenti, solo l'Argento E-1929 ha permesso al motore di funzionare correttamente. Non posso fare a meno di immaginare che si tratti di qualche influenza residua della volontà del progettista, anche se non conosciamo ancora dove si trovi questa persona."
  },
  AvgDialog_15613_Content_45 = {
    Text = "Dopo il Diluvio 300, @2/@1, Dipartimento di Studi sul Risveglio dell'Università di Mythag, Doll\nL'automa Erica si è Risvegliato con successo.\nIl Risvegliatore mostra estrema aggressività e impulsi distruttivi. Anche con un Investigatore che mantiene il suo Stato mentale, mostra ancora chiare tendenze all'Attacco e Scatena incontrollabilmente correnti elettriche, conducendo attacchi indiscriminati sugli oggetti circostanti.\nAlistair ha determinato che E-1929 contiene due spiriti— uno travolgente nella sua Follia, e un altro che, sebbene debole, possiede maggiore razionalità. Si dovrebbe tentare di Separare i due, o Sopprimere la Follia a un livello controllabile.\n…\nDopo il Diluvio 300, @2/@2, Dipartimento di Studi sul Risveglio dell'Università di Mythag, Doll\nImpossibile Separare gli spiriti. Si sta considerando attivamente il secondo piano.\nUn dispositivo di Soppressione degli spiriti è una buona idea.\n…\nDopo il Diluvio 303, @1/@2, Dipartimento di Studi sul Risveglio dell'Università di Mythag, Doll\nDispositivo di Soppressione Forgiato e installato con successo.\nLa Follia del Risvegliatore è stata Soppressa. Lo Stato generale tende alla stabilità, sebbene si verifichino ancora brevi cali nella Soppressione.\nLa personalità, gli interessi e gli altri tratti del Risvegliatore sono andati completamente perduti. Il suo comportamento somiglia più a quello di una bambola che a quello di una persona.\nAlmeno non è più sul punto di esplodere in ogni momento.\n…"
  },
  AvgDialog_15613_Content_46 = {
    Text = "Erica inclinò la testa, riordinò i documenti e lasciò la Stanza."
  },
  AvgDialog_15613_Content_5 = {
    Text = "Sotto un lampione poco distante, una cabina telefonica pubblica se ne sta in silenzio."
  },
  AvgDialog_15613_Content_6 = {
    Text = "Piede sinistro."
  },
  AvgDialog_15613_Content_7 = {
    Text = "Piede destro."
  },
  AvgDialog_15613_Content_8 = {
    Text = "Come se percepisse la tua determinazione, la melma accasciata a terra prosegue il suo assalto alla coscienza di Erica, tingendo di nero pece anche te."
  },
  AvgDialog_15613_Content_9 = {
    Text = "Piede sinistro."
  },
  AvgDialog_18708_Content_1 = {Text = "!!!"},
  AvgDialog_18708_Content_10 = {
    Text = "Tra gemiti di dolore, i lineamenti del Cacciatore di Teschi si contorsero in modo incredibile, con cisti purulente che si agitavano sotto la pelle, pronte a esplodere."
  },
  AvgDialog_18708_Content_11 = {
    Text = "Questo è...?"
  },
  AvgDialog_18708_Content_13 = {
    Text = "La sua testa viene mozzata senza pietà, D-melma nera sgorga dal collo, quasi schizzandoti in faccia."
  },
  AvgDialog_18708_Content_14 = {
    Text = "Essere troppo curiosi non è una buona abitudine, Custode."
  },
  AvgDialog_18708_Content_15 = {
    Text = "Il suo cranio era colmo di D-melma accumulata. Ti consiglio di mantenere le distanze."
  },
  AvgDialog_18708_Content_16 = {
    Text = "Lady Daffodil!"
  },
  AvgDialog_18708_Content_17 = {
    Text = "Buonasera, mia piccola rosa."
  },
  AvgDialog_18708_Content_18 = {
    Text = "Perché sei di nuovo tu...?"
  },
  AvgDialog_18708_Content_19 = {
    Text = "Ho seguito la Traiettoria del Cacciatore di Teschi fin qui e ho recuperato il mio fiore."
  },
  AvgDialog_18708_Content_2 = {
    Text = "Il Cacciatore di Teschi crolla pesantemente al suolo, emettendo un debole gemito."
  },
  AvgDialog_18708_Content_20 = {
    Text = "Daffodil camminò con disinvoltura sul pavimento macchiato di Sangue e D-melma, colse un narciso dal comodino e lo annusò delicatamente."
  },
  AvgDialog_18708_Content_21 = {
    Text = "Questo è il mio Narciso Brown Cup, che ho coltivato con cura per tre anni. Ha un Effetto calmante e rilassante."
  },
  AvgDialog_18708_Content_22 = {
    Text = "Vorresti annusarlo?"
  },
  AvgDialog_18708_Content_23 = {
    Text = "<LightGray:Ecco perché dormivo così profondamente poco fa...>"
  },
  AvgDialog_18708_Content_24 = {
    Text = "Scosti con irritazione il narciso in fiore, coperto di rugiada, dalla sua mano."
  },
  AvgDialog_18708_Content_25 = {
    Text = "Sembri sapere molto sul Cacciatore di Teschi."
  },
  AvgDialog_18708_Content_26 = {
    Text = "Come fai a sapere che dal suo cervello trasudava D-melma?"
  },
  AvgDialog_18708_Content_27 = {
    Text = "Se avessi vissuto quanto me e avessi visto abbastanza Pazienti da Dissoluzione, anche tu ne sapresti di più."
  },
  AvgDialog_18708_Content_28 = {
    Text = "La Traiettoria del Cacciatore di Teschi?"
  },
  AvgDialog_18708_Content_29 = {
    Text = "\"Seguendo la Traiettoria del Cacciatore di Teschi\" — Riesci a percepire la sua posizione?"
  },
  AvgDialog_18708_Content_3 = {
    Text = "Senti un \"toc, toc, toc\" provenire dalle scale. La porta di legno alle tue spalle viene spalancata all'improvviso."
  },
  AvgDialog_18708_Content_30 = {
    Text = "Ho i miei metodi. Tuttavia... per non spaventare i bambini, è meglio che non li riveli."
  },
  AvgDialog_18708_Content_31 = {Text = "..."},
  AvgDialog_18708_Content_32 = {
    Text = "Per ora vi prego di andarvene, Lady Daffodil. Non interferite con le nostre indagini."
  },
  AvgDialog_18708_Content_33 = {
    Text = "Huh, non dubiti più di me?"
  },
  AvgDialog_18708_Content_34 = {
    Text = "Non posso ancora escludere del tutto la vostra diffidenza. Ma il mio intuito mi dice..."
  },
  AvgDialog_18708_Content_35 = {
    Text = "Se foste voi il \"Cacciatore di Teschi\", avreste agito in modo più pulito ed efficiente, senza lasciare tracce così evidenti."
  },
  AvgDialog_18708_Content_36 = {
    Text = "Oh cielo, questo è un complimento per me?\nPer essere precisi, è un dato di fatto, non semplice intuito."
  },
  AvgDialog_18708_Content_37 = {
    Text = "...Non cambiare argomento."
  },
  AvgDialog_18708_Content_38 = {
    Text = "Dato che siete arrivato in città solo oggi, chi era quella persona che ho visto ieri notte?"
  },
  AvgDialog_18708_Content_39 = {
    Text = "Hai una sorella gemella?"
  },
  AvgDialog_18708_Content_4 = {
    Text = "{Male=Mr.,Female=Miss} %player%, ho appena sentito un rumore, cos'è successo?"
  },
  AvgDialog_18708_Content_40 = {Text = "..."},
  AvgDialog_18708_Content_41 = {
    Text = "Daffodil parve assorta in pensieri tormentati, poi all'improvviso tese la mano verso di voi."
  },
  AvgDialog_18708_Content_42 = {
    Text = "Polpastrelli delicati sfiorano il vostro volto per un istante, poi scivolano verso il collo, soffermandosi a percepire la pulsazione nel profondo dei vasi sanguigni."
  },
  AvgDialog_18708_Content_43 = {
    Text = "<Shake:...?>"
  },
  AvgDialog_18708_Content_44 = {
    Text = "Ho sempre pensato che gli esseri umani fossero creature abili nel travestimento."
  },
  AvgDialog_18708_Content_45 = {
    Text = "Vi avvolgete in involucri simili fatti di carne, pronunciate parole simili, con pulsazioni e battiti cardiaci simili..."
  },
  AvgDialog_18708_Content_46 = {
    Text = "Per lungo tempo, non riuscivo a distinguervi, così come voi non riuscivate a distinguere me."
  },
  AvgDialog_18708_Content_47 = {
    Text = "Quindi... intendete dire che non siete gemelli, ma condividete una sorta di relazione speciale?"
  },
  AvgDialog_18708_Content_48 = {
    Text = "È possibile. Volete provare a indovinare? Avete tre possibilità."
  },
  AvgDialog_18708_Content_49 = {
    Text = "...Rifiuto."
  },
  AvgDialog_18708_Content_5 = {
    Text = "Q-Questo è...?!"
  },
  AvgDialog_18708_Content_50 = {
    Text = "Anche se indovinassi, non mi rivelereste comunque la vera risposta. Ho ragione?"
  },
  AvgDialog_18708_Content_51 = {
    Text = "Daffodil tracciava distrattamente le vene sul vostro collo con la punta delle dita, gli occhi colmi di un sorriso ancora più profondo."
  },
  AvgDialog_18708_Content_52 = {
    Text = "Stai davvero imparando a conoscermi, {Male=Mr.,Female=Miss} Custode."
  },
  AvgDialog_18708_Content_53 = {
    Text = "Fate mezzo passo indietro, uscendo dalla portata di Daffodil, e le rivolgete uno sguardo di ammonimento."
  },
  AvgDialog_18708_Content_54 = {
    Text = "Ai vostri occhi, avere lo stesso identico aspetto fa di loro dei gemelli?"
  },
  AvgDialog_18708_Content_55 = {
    Text = "In linea generale, questa è probabilmente l'unica possibilità."
  },
  AvgDialog_18708_Content_56 = {
    Text = "Ma voi e io sappiamo bene che il mondo in cui viviamo è tutt'altro che \"ordinario\"."
  },
  AvgDialog_18708_Content_57 = {
    Text = "Certo. L'aspetto più deplorevole di questo mondo è la sua \"non convenzionalità.\""
  },
  AvgDialog_18708_Content_58 = {
    Text = "Anche essere un paio di gemelle spensierate non sembra male."
  },
  AvgDialog_18708_Content_6 = {
    Text = "Ti fai avanti e tiri indietro il cappuccio nero del Cacciatore di Teschi, rivelando il volto sottostante."
  },
  AvgDialog_18708_Content_7 = {
    Text = "Zigomi pronunciati, naso adunco e guance incavate — un volto del tutto sconosciuto."
  },
  AvgDialog_18708_Content_8 = {
    Text = "Sai davvero scegliere i tuoi bersagli, inseguendomi fin qui. Chi sei esattamente?"
  },
  AvgDialog_18708_Content_9 = {
    Text = "Ugh... Ah..."
  },
  AvgDialog_18709_Content_1 = {
    Text = "Pioggia Amara"
  },
  AvgDialog_18709_Content_10 = {
    Text = "Ti appoggi alla testiera del letto, le memorie degli eventi recenti balenano davanti ai tuoi occhi. Molte questioni restano ancora da risolvere."
  },
  AvgDialog_18709_Content_11 = {
    Text = "Chiediamo prima alla Sig.na Horla cosa sa."
  },
  AvgDialog_18709_Content_12 = {
    Text = "Chiedi al Vecchio Freeman"
  },
  AvgDialog_18709_Content_13 = {
    Text = "Il Vecchio Freeman? Quindi è ancora vivo..."
  },
  AvgDialog_18709_Content_14 = {
    Text = "Ho sentito dire dalla gente del posto che da giovane era una persona ottimista e allegra, e piaceva a tutti."
  },
  AvgDialog_18709_Content_15 = {
    Text = "Dopo la <Yellow:pestilenza>, lasciò Rainy Town e tornò come una persona completamente diversa."
  },
  AvgDialog_18709_Content_16 = {Text = "Peste?"},
  AvgDialog_18709_Content_17 = {
    Text = "Tre anni fa, un disastro di Dissoluzione colpì a nord di Rainy Town. La gente del posto lo chiamava pestilenza."
  },
  AvgDialog_18709_Content_18 = {
    Text = "Ormai si è completamente trasformata in una terra morta."
  },
  AvgDialog_18709_Content_19 = {
    Text = "Chiedi a Daffodil"
  },
  AvgDialog_18709_Content_2 = {Text = "..."},
  AvgDialog_18709_Content_20 = {
    Text = "Signorina Horla, il tono che ha usato poco fa parlando di Daffodil... vi conoscevate già?"
  },
  AvgDialog_18709_Content_21 = {
    Text = "Lady Daffodil..."
  },
  AvgDialog_18709_Content_22 = {
    Text = "Horla fissò la pagina del libro che teneva in mano, un lieve sorriso che le affiorava sul volto."
  },
  AvgDialog_18709_Content_23 = {
    Text = "Lady Daffodil, lei... mi ha aiutato."
  },
  AvgDialog_18709_Content_24 = {
    Text = "Anno 15@1, San Pedro"
  },
  AvgDialog_18709_Content_25 = {
    Text = "Questa raccolta di poesie di Longsa è unica nel suo genere. Abbine cura come di un tesoro."
  },
  AvgDialog_18709_Content_26 = {
    Text = "Grazie infinite, Lady Daffodil. Non posso credere che l'abbiate davvero trovata..."
  },
  AvgDialog_18709_Content_27 = {
    Text = "\"Possa tu conservare per sempre la bellezza radiosa di una rosa.\""
  },
  AvgDialog_18709_Content_28 = {
    Text = "Poesia magnifica. Hai un gusto eccellente."
  },
  AvgDialog_18709_Content_29 = {
    Text = "Sì, ma preferisco \"Onoro questo istante con latte e fiori...\""
  },
  AvgDialog_18709_Content_3 = {
    Text = "Finalmente ti sei svegliato, {Male=Mr.,Female=Miss} Custode."
  },
  AvgDialog_18709_Content_30 = {
    Text = "Ah... Scusa, ho divagato di nuovo."
  },
  AvgDialog_18709_Content_31 = {
    Text = "Conosco le regole della \"Borsa di Scambio.\" Dunque, cosa vuoi da me?"
  },
  AvgDialog_18709_Content_32 = {
    Text = "Hmm... Dovrò osservarti da vicino, mia piccola rosa."
  },
  AvgDialog_18709_Content_33 = {
    Text = "Lo Sguardo percorse l'intero corpo di Horla senza emozione. La bambina raddrizzò involontariamente la schiena."
  },
  AvgDialog_18709_Content_34 = {
    Text = "Puoi condividere una memoria con me?\nDolorosa, triste... qualsiasi memoria infelice andrà bene."
  },
  AvgDialog_18709_Content_35 = {
    Text = "Memorie infelici? N-Non è una cosa buona. Cosa intendi farne...?"
  },
  AvgDialog_18709_Content_36 = {
    Text = "Intendo usarla per un piccolo esperimento. Lo scoprirai a tempo debito."
  },
  AvgDialog_18709_Content_37 = {
    Text = "Giorni di implacabile esaurimento logorano i tuoi nervi; scivoli nel sonno cullata dalle parole sommesse di Horla."
  },
  AvgDialog_18709_Content_38 = {Text = "..."},
  AvgDialog_18709_Content_39 = {
    Text = "Dopo un tempo imprecisato, una pioggerella leggera cominciò a cadere fuori dalla finestra."
  },
  AvgDialog_18709_Content_4 = {
    Text = "Ricordo che mi sembrava di essere svenuta, e poi..."
  },
  AvgDialog_18709_Content_40 = {
    Text = "Qualcuno avanza lentamente, senza sosta, lungo la strada fangosa sotto la pioggia."
  },
  AvgDialog_18709_Content_41 = {
    Text = "Appaiono solo nelle notti di pioggia, i loro passi occultati dalla pioggia, avvicinandosi furtivamente alle tue spalle..."
  },
  AvgDialog_18709_Content_42 = {
    Text = "I Cacciatori di Teschi non sono una persona, né due. I Cacciatori di Teschi sono un'organizzazione."
  },
  AvgDialog_18709_Content_43 = {
    Text = "Una notte piovosa, da solo... <Red:Non è forse la tua situazione attuale?>"
  },
  AvgDialog_18709_Content_44 = {
    Text = "<Red:Zzz... Krr...>"
  },
  AvgDialog_18709_Content_45 = {
    Text = "<RedBig:Snap!>"
  },
  AvgDialog_18709_Content_46 = {Text = "?!"},
  AvgDialog_18709_Content_47 = {
    Text = "Un pallido fulmine squarcia la quiete della notte. Spalanchi gli occhi di colpo nell'oscurità."
  },
  AvgDialog_18709_Content_48 = {
    Text = "Qualcuno è in piedi accanto al tuo letto."
  },
  AvgDialog_18709_Content_49 = {
    Text = "Lo Sguardo greve è come una falce fredda e umida che ti percorre gli arti, la schiena, e..."
  },
  AvgDialog_18709_Content_5 = {
    Text = "Sì, è stata Lady Daffodil a riportarvi indietro e a ordinarmi di prendermi cura di voi."
  },
  AvgDialog_18709_Content_50 = {
    Text = "Un collo indifeso."
  },
  AvgDialog_18709_Content_51 = {
    Text = "Testa@1 Teschio@4"
  },
  AvgDialog_18709_Content_54 = {Text = "Hmm...!!"},
  AvgDialog_18709_Content_55 = {
    Text = "Cadi improvvisamente dal letto e d'istinto ti copri il collo."
  },
  AvgDialog_18709_Content_56 = {
    Text = "Una figura umbratile che impugna una falce si erge accanto al letto, quasi indistinguibile dalla notte oscura alle sue spalle."
  },
  AvgDialog_18709_Content_57 = {
    Text = "L'aria è satura dell'odore di pioggia e ruggine. Sangue rosso cupo gocciola dalla Lama fredda e bianca, raccogliendosi in una pozza sul pavimento."
  },
  AvgDialog_18709_Content_58 = {
    Text = "—È il Cacciatore di Teschi."
  },
  AvgDialog_18709_Content_6 = {
    Text = "Daffodil...?"
  },
  AvgDialog_18709_Content_7 = {
    Text = "Cogli un profumo familiare."
  },
  AvgDialog_18709_Content_8 = {
    Text = "Un vaso dal collo sottile è apparso sul comodino, con narcisi bianchi che protendono i petali verso la luce del sole."
  },
  AvgDialog_18709_Content_9 = {
    Text = "È il suo profumo..."
  },
  AvgDialog_18710_Content_1 = {
    Text = "Regno delle Bestie"
  },
  AvgDialog_18710_Content_10 = {
    Text = "Era una limpida notte d'estate, e come al solito trasportavo diligentemente il mio \"bottino\"."
  },
  AvgDialog_18710_Content_11 = {
    Text = "<Shake:Teste... ancora teste...>"
  },
  AvgDialog_18710_Content_12 = {
    Text = "Tap. Tap. Tap."
  },
  AvgDialog_18710_Content_13 = {
    Text = "Il suono di passi leggeri si avvicinò silenziosamente, e una voce gentile giunse dall'alto."
  },
  AvgDialog_18710_Content_14 = {
    Text = "Eh... Guarda cosa ho trovato? Una piccola bestia randagia."
  },
  AvgDialog_18710_Content_15 = {
    Text = "Quella notte, una donna venne da me."
  },
  AvgDialog_18710_Content_16 = {
    Text = "Quando mi si avvicinò, colsi una fragranza gradevole.\nEra il profumo di fiori e nebbia."
  },
  AvgDialog_18710_Content_17 = {
    Text = "È il profumo di un altro mondo, tanto diverso dal mio regno quanto il giorno lo è dalla notte, mai destinati a intersecarsi."
  },
  AvgDialog_18710_Content_18 = {
    Text = "Eppure lei attraversò ugualmente la melma maleodorante, camminò tra le ombre della città e tese la mano verso di me."
  },
  AvgDialog_18710_Content_19 = {Text = "Disse..."},
  AvgDialog_18710_Content_2 = {
    Text = "Sono una bestia... Sono un paziente.\n\nSono al di là di ogni redenzione."
  },
  AvgDialog_18710_Content_20 = {
    Text = "Vuoi venire con me, piccola bestia?"
  },
  AvgDialog_18710_Content_21 = {
    Text = "5:00, Nord di Rainy Town"
  },
  AvgDialog_18710_Content_22 = {
    Text = "Questo posto è... davvero desolato."
  },
  AvgDialog_18710_Content_23 = {
    Text = "Tre anni fa, una <Yellow:D-fessura di Classe S> apparve qui. L'acqua, la vegetazione... l'intero ecosistema subì gravi danni."
  },
  AvgDialog_18710_Content_24 = {
    Text = "Fortunatamente le vittime furono poche, e i residenti vennero evacuati sotto la supervisione del Comitato."
  },
  AvgDialog_18710_Content_25 = {
    Text = "Il tuo sguardo si posa sulle mura desolate e sugli alberi pallidi e rinsecchiti più avanti."
  },
  AvgDialog_18710_Content_26 = {
    Text = "Se non fosse stato per la Dissoluzione, questo sarebbe un campo verde in piena fioritura di lillà. Quando soffia il vento, l'erba ondeggia come flutti, simile a un oceano verde."
  },
  AvgDialog_18710_Content_27 = {
    Text = "Sei sicura che il Cacciatore di Teschi sia qui, Lady Daffodil?"
  },
  AvgDialog_18710_Content_28 = {
    Text = "L'unica risposta è il gracchiare rauco dei corvi."
  },
  AvgDialog_18710_Content_29 = {
    Text = "Oh, Lady Daffodil è sparita?"
  },
  AvgDialog_18710_Content_3 = {
    Text = "Di giorno mi nascondo nelle ombre della città, sdraiato sulla schiena con la pancia all'aria, dormendo profondamente."
  },
  AvgDialog_18710_Content_30 = {
    Text = "Beh, le conseguenze del fidarsi degli altri."
  },
  AvgDialog_18710_Content_31 = {
    Text = "Ahem. Lei è sempre così imprevedibile nei suoi spostamenti; ormai ci ho fatto l'abitudine."
  },
  AvgDialog_18710_Content_32 = {
    Text = "Non preoccupatevi, posso indagare da solo. Troverò sicuramente qualcosa qui..."
  },
  AvgDialog_18710_Content_33 = {
    Text = "<Big:Boom—!!>"
  },
  AvgDialog_18710_Content_34 = {
    Text = "Il tuono rimbomba tra le nuvole basse, e le foglie secche frusciano nel vento autunnale."
  },
  AvgDialog_18710_Content_35 = {
    Text = "Questo è un segno di pioggia."
  },
  AvgDialog_18710_Content_36 = {
    Text = "Perché appare solo nei giorni di pioggia?"
  },
  AvgDialog_18710_Content_37 = {
    Text = "Perché quando piove, il sangue e la pioggia si mescolano e defluiscono nelle fogne."
  },
  AvgDialog_18710_Content_38 = {
    Text = "Sì, scorre nelle fogne, nelle bare e nelle piccole grondaie intorno a voi..."
  },
  AvgDialog_18710_Content_39 = {
    Text = "<Red:Zzz... Krr...>"
  },
  AvgDialog_18710_Content_4 = {
    Text = "Di notte vago per le strade come un fantasma, cercando una testa dopo l'altra."
  },
  AvgDialog_18710_Content_40 = {
    Text = "Una notte buia e piovosa... No, sto di nuovo sognando a occhi aperti."
  },
  AvgDialog_18710_Content_41 = {
    Text = "Scuotesti vigorosamente la testa, cercando di scacciare il caos dalla mente."
  },
  AvgDialog_18710_Content_42 = {
    Text = "Il tempo stringe. Devi agire in fretta."
  },
  AvgDialog_18710_Content_5 = {
    Text = "<Red:Teste. Teste. Teste.>"
  },
  AvgDialog_18710_Content_6 = {
    Text = [[
<RedBig:Testa.
        Testa.
                Testa.
                        Testa.
                                Testa.
                                        Testa...>]]
  },
  AvgDialog_18710_Content_7 = {
    Text = "La mia mente non riesce più a contemplare la sopravvivenza, l'amore e la dignità.\n\nÈ stata colmata da tempo fino all'orlo da quelle fantasie insaziabili."
  },
  AvgDialog_18710_Content_8 = {
    Text = "Sono al di là della Redenzione."
  },
  AvgDialog_18710_Content_9 = {
    Text = "Anno 15@1, San Pedro City"
  },
  AvgDialog_18711_Content_1 = {Text = "Ahhhh—!!"},
  AvgDialog_18711_Content_10 = {
    Text = "Ignorò la melma lurida e il sangue sul terreno, si accovacciò e fissò la creatura che si dibatteva davanti a lei."
  },
  AvgDialog_18711_Content_11 = {
    Text = "Smetti di cercare. Se ne sono andati e non torneranno mai più."
  },
  AvgDialog_18711_Content_12 = {
    Text = "Ciò di cui hai bisogno non sono queste cose."
  },
  AvgDialog_18711_Content_13 = {
    Text = "Non ne ho bisogno...? No, la Testa@1, dammela..."
  },
  AvgDialog_18711_Content_14 = {Text = "..."},
  AvgDialog_18711_Content_15 = {
    Text = "Lo sapevi? In realtà... siamo uguali.\nComprendo il tuo dolore."
  },
  AvgDialog_18711_Content_16 = {
    Text = "Anno 15@1, San Pedro City"
  },
  AvgDialog_18711_Content_17 = {
    Text = "Vuoi venire con me, piccola bestia? Hai bisogno di aiuto."
  },
  AvgDialog_18711_Content_18 = {
    Text = "Anno 15@1 Nell'estate del primo anno, una donna mi tese la mano."
  },
  AvgDialog_18711_Content_19 = {
    Text = "Forse è il suo profumo gradevole, o forse semplicemente appare gentile."
  },
  AvgDialog_18711_Content_2 = {
    Text = "Una massa di carne collassa, riversando D-melma e muco grigiastro, rivelando il corpo fragile di Harriet."
  },
  AvgDialog_18711_Content_20 = {
    Text = "In breve, non l'ho rifiutata."
  },
  AvgDialog_18711_Content_21 = {
    Text = "Ingenuamente afferrai la sua mano, e con essa il mio fato futuro."
  },
  AvgDialog_18711_Content_22 = {
    Text = "Cough... Cough..."
  },
  AvgDialog_18711_Content_23 = {
    Text = "Stai morendo, Daffodil."
  },
  AvgDialog_18711_Content_24 = {
    Text = "Sciocca creatura... Dopo tutti questi anni, non hai ancora imparato a parlare come si deve."
  },
  AvgDialog_18711_Content_25 = {
    Text = "Non piangere... *cough*..."
  },
  AvgDialog_18711_Content_26 = {
    Text = "<Shake:Io... io non ho...>"
  },
  AvgDialog_18711_Content_27 = {
    Text = "Prendi la mia testa. Ti affido la mia identità, il mio aspetto e questo piccolo negozio."
  },
  AvgDialog_18711_Content_28 = {Text = "?!"},
  AvgDialog_18711_Content_29 = {
    Text = "Lo so, coff coff... hai sempre desiderato camminare per il mondo come un comune essere umano."
  },
  AvgDialog_18711_Content_3 = {
    Text = "Teschi bianco-grigiastri emersero in massa, per poi svanire in un Bagliore."
  },
  AvgDialog_18711_Content_30 = {
    Text = "Ti nascondi nell'angolo, osservando come parlo e cammino. Quando sono via, indossi di nascosto i miei vestiti e fingi persino di essere me per fare amicizia..."
  },
  AvgDialog_18711_Content_31 = {
    Text = "L'ho sempre saputo."
  },
  AvgDialog_18711_Content_32 = {
    Text = "Scusa, Daffodil, non volevo..."
  },
  AvgDialog_18711_Content_33 = {
    Text = "Ora esaudirò il tuo desiderio, ahem... ma devi promettermi..."
  },
  AvgDialog_18711_Content_34 = {
    Text = "In futuro, non recidere con leggerezza la testa degli innocenti. Se incontrerai qualcuno come te, dovrai aiutarlo."
  },
  AvgDialog_18711_Content_35 = {
    Text = "Proprio come ti sto aiutando adesso."
  },
  AvgDialog_18711_Content_36 = {
    Text = "<Shake:Salvami, salvami...>"
  },
  AvgDialog_18711_Content_37 = {
    Text = "Harriet emette un lamento bestiale e, tremante, tende le mani verso Lady Daffodil."
  },
  AvgDialog_18711_Content_38 = {Text = "..."},
  AvgDialog_18711_Content_39 = {
    Text = "Allora... quando vedesti tuo marito nel cimitero, devi esserti sentita completamente disperata, vero?"
  },
  AvgDialog_18711_Content_4 = {
    Text = "La test@1... No..."
  },
  AvgDialog_18711_Content_40 = {
    Text = "Freeman... Huh.@2..."
  },
  AvgDialog_18711_Content_41 = {
    Text = "Portiamo la stessa maledizione, ma io sono molto più fortunata di te."
  },
  AvgDialog_18711_Content_42 = {
    Text = "Quando ancora non conoscevo la differenza tra il bene e il male, fu quella signora a tendermi la mano."
  },
  AvgDialog_18711_Content_43 = {
    Text = "Daffodil si inginocchiò davanti alla signora Harriet, stringendo delicatamente la sua mano coperta di cicatrici e D-Melma."
  },
  AvgDialog_18711_Content_44 = {
    Text = "Imparai a parlare e camminare come lei, plasmando me stessa a sua immagine."
  },
  AvgDialog_18711_Content_45 = {
    Text = "Attenzione, Lady Daffodil! Le mani di Harriet sono coperte di D-melma—"
  },
  AvgDialog_18711_Content_46 = {
    Text = "Shh... Ho ancora qualcosa da dirle."
  },
  AvgDialog_18711_Content_47 = {
    Text = "Daffodil continuò a fissare Harriet. Una connessione segreta fluiva tra loro, isolandole da ogni distrazione."
  },
  AvgDialog_18711_Content_48 = {
    Text = "Ora posso finalmente raggiungere gli altri, proprio come fece lei... Ma è troppo tardi."
  },
  AvgDialog_18711_Content_49 = {
    Text = "Un pallido fumo violaceo si leva gradualmente, fluttuando lentamente nella stanza oscura."
  },
  AvgDialog_18711_Content_5 = {
    Text = "Harriet, priva di testa e inquieta, si contorceva mentre le vene del collo pulsavano rapidamente, emettendo un debole ronzio."
  },
  AvgDialog_18711_Content_50 = {
    Text = "Cogli di nuovo quel familiare profumo floreale, mescolato all'umidità della nebbia di mezzanotte, che diluisce il pesante odore di sangue della stanza."
  },
  AvgDialog_18711_Content_51 = {
    Text = "Daffodil posò delicatamente la mano accanto alla signora Harriet."
  },
  AvgDialog_18711_Content_52 = {
    Text = "Stia tranquilla, Lady Harriet. Non sentirà alcun dolore."
  },
  AvgDialog_18711_Content_53 = {
    Text = "Una fenditura si squarcia rapidamente dal suo palmo, inghiottendo lentamente Harriet..."
  },
  AvgDialog_18711_Content_54 = {
    Text = "<Shake:...>"
  },
  AvgDialog_18711_Content_55 = {
    Text = "Di' a mio marito@2 di smettere di bere."
  },
  AvgDialog_18711_Content_56 = {
    Text = "C'è dell'altro..."
  },
  AvgDialog_18711_Content_57 = {
    Text = "La gola esposta di Harriet tremò leggermente, ma infine tacque come una foglia appassita."
  },
  AvgDialog_18711_Content_58 = {
    Text = "Lasciò andare la mano di Daffodil e precipitò in silenzio in un'insondabile Fenditura Dimensionale."
  },
  AvgDialog_18711_Content_59 = {
    Text = "<Change>Addio, addio..."
  },
  AvgDialog_18711_Content_6 = {
    Text = "Datemi la @2, datemi la testa..."
  },
  AvgDialog_18711_Content_60 = {
    Text = "Finalmente... È finita? Dove l'avete portata, Lady Daffodil?"
  },
  AvgDialog_18711_Content_61 = {
    Text = "L'Oceano Primordiale. Avrà molto tempo per ricordare... o dimenticare tutto ciò che è accaduto."
  },
  AvgDialog_18711_Content_62 = {
    Text = "Lady Harriet..."
  },
  AvgDialog_18711_Content_63 = {
    Text = "Prima che tu possa raccogliere i tuoi pensieri dispersi, dei passi flebili echeggiano fuori dalla casa."
  },
  AvgDialog_18711_Content_64 = {
    Text = "Chi c'è? Seguiamo e diamo un'occhiata."
  },
  AvgDialog_18711_Content_65 = {
    Text = "Sì, sono io... hic."
  },
  AvgDialog_18711_Content_66 = {
    Text = "Quanto tempo, piccolo detective! Ti ricordi di me, il custode del cimitero Vecchio Freeman?"
  },
  AvgDialog_18711_Content_67 = {
    Text = "Il Vecchio Freeman, stringendo una bottiglia di brandy, continuava a ruttare con un sorriso imbarazzato sul volto."
  },
  AvgDialog_18711_Content_68 = {
    Text = "Vecchio Freeman?! Che ci fai qui... Hai sentito tutto?"
  },
  AvgDialog_18711_Content_69 = {Text = "Io..."},
  AvgDialog_18711_Content_7 = {
    Text = "Strisciava ansiosamente sul pavimento, le braccia scheletriche che si agitavano. Come una Bestia messa all'angolo, emetteva gemiti disperati dalla gola."
  },
  AvgDialog_18711_Content_70 = {
    Text = "Non so nemmeno io cosa sia successo. Ho dormito come un sasso dopo aver bevuto."
  },
  AvgDialog_18711_Content_71 = {
    Text = "Non ricordo cosa sia accaduto nel frattempo, ma in qualche modo sono finito qui in uno stato confuso."
  },
  AvgDialog_18711_Content_72 = {
    Text = "Poi ho sentito del rumore all'interno... Non preoccuparti, non ho dato neanche una sbirciatina!"
  },
  AvgDialog_18711_Content_73 = {
    Text = "Il Vecchio Freeman si avvicinò all'improvviso e ti fece un misterioso occhiolino.\nNon riuscisti a scansarti in tempo e cogliesti una forte zaffata dell'odore pungente di fumo e alcol."
  },
  AvgDialog_18711_Content_74 = {
    Text = "Hai ucciso quel Cacciatore di Teschi, vero?"
  },
  AvgDialog_18711_Content_75 = {
    Text = "Non benissimo, ma ci siamo quasi. Nessuno disturberà più il tuo sonno d'ora in poi."
  },
  AvgDialog_18711_Content_76 = {
    Text = "Ti tappi il naso, fai tre passi indietro e annuisci in modo sbrigativo."
  },
  AvgDialog_18711_Content_77 = {Text = "Oh..."},
  AvgDialog_18711_Content_78 = {
    Text = "Il Vecchio Freeman si grattò i capelli arruffati, un lampo di confusione negli occhi."
  },
  AvgDialog_18711_Content_79 = {
    Text = "Niente male, niente male..."
  },
  AvgDialog_18711_Content_8 = {Text = "..."},
  AvgDialog_18711_Content_80 = {
    Text = "Signor Freeman. D'ora in poi... basta bere."
  },
  AvgDialog_18711_Content_81 = {
    Text = "Smettere di bere? No, no, no... Preferirei morire."
  },
  AvgDialog_18711_Content_82 = {
    Text = "È una richiesta da parte di un'amica. Se n'è andata lontano, molto lontano... ma tiene ancora a te."
  },
  AvgDialog_18711_Content_83 = {
    Text = "Amici? Heh, non prenderti in giro. Il Vecchio Freeman non ha amici..."
  },
  AvgDialog_18711_Content_84 = {
    Text = "Ti scacciò con un gesto sprezzante, borbottando mentre si allontanava barcollando."
  },
  AvgDialog_18711_Content_85 = {
    Text = "Sembra così abbattuto. Che peccato...\nNon saprà mai perché si sente così."
  },
  AvgDialog_18711_Content_86 = {
    Text = "È quasi come se non capisse perché si trova qui."
  },
  AvgDialog_18711_Content_87 = {
    Text = "Questo dev'essere ciò che la signora Harriet avrebbe voluto."
  },
  AvgDialog_18711_Content_88 = {
    Text = "Non dirgli nulla... Può continuare a bere, cantare e trascinare la sua vita così."
  },
  AvgDialog_18711_Content_89 = {
    Text = "In un certo senso, anche questa è una forma di fortuna. La vita di un essere umano è molto breve..."
  },
  AvgDialog_18711_Content_9 = {
    Text = "Daffodil lasciò sfuggire un lieve sospiro, gli occhi scintillanti di un Pianto inespresso."
  },
  AvgDialog_18711_Content_90 = {
    Text = "Osservi il Vecchio Freeman allontanarsi."
  },
  AvgDialog_18711_Content_91 = {
    Text = "Una figura curva trema nel vento desolato, sempre più piccola, sempre più lontana..."
  },
  AvgDialog_18711_Content_92 = {
    Text = "Fino a essere completamente divorata dall'orizzonte lontano."
  },
  AvgDialog_18711_Content_93 = {
    Text = "Poi scorgi un tenue raggio d'alba che trafigge la nebbia, illuminando gradualmente il cielo."
  },
  AvgDialog_18711_Content_94 = {
    Text = "La pioggia è cessata... Daffodil."
  },
  AvgDialog_18712_Content_1 = {
    Text = "Inno dell'Ombra"
  },
  AvgDialog_18712_Content_10 = {
    Text = "Dammela... <Big:Restituiscimela>!"
  },
  AvgDialog_18712_Content_11 = {
    Text = "Neri viticci si estendono incessantemente dal suo collo, assorbendo con bramosia le teste decadute nel suo corpo."
  },
  AvgDialog_18712_Content_12 = {
    Text = "Con ogni teschio che divora, le sue dimensioni aumentano ulteriormente."
  },
  AvgDialog_18712_Content_13 = {
    Text = "L'ultima cosa che si erge davanti a te è un'enorme massa di carne ammassata."
  },
  AvgDialog_18712_Content_14 = {
    Text = "<Bold:—!!!>"
  },
  AvgDialog_18712_Content_15 = {
    Text = "Queste teste... Le ho già viste."
  },
  AvgDialog_18712_Content_16 = {
    Text = "Alcuni di quei volti li hai già visti nei fascicoli consegnati dalla polizia, in quelle fredde fotografie delle vittime allineate in fila."
  },
  AvgDialog_18712_Content_17 = {
    Text = "Le hai viste."
  },
  AvgDialog_18712_Content_18 = {
    Text = "Ora comprendi: non è mai esistita alcuna organizzazione dei Cacciatori di Teschi."
  },
  AvgDialog_18712_Content_19 = {
    Text = "<Yellow:Dall'inizio alla fine, il Cacciatore di Teschi è sempre stato solo.>"
  },
  AvgDialog_18712_Content_2 = {
    Text = "Lady Daffodil...?!"
  },
  AvgDialog_18712_Content_20 = {
    Text = "<RedShake:Non basta...>"
  },
  AvgDialog_18712_Content_21 = {
    Text = "<RedShake:Non basta... non basta...>"
  },
  AvgDialog_18712_Content_22 = {
    Text = "Un corpo tumefatto in cui sono incastrati innumerevoli capi che esprimono Pain e Lamenti, che si sollevano e si abbassano al ritmo del grasso molle..."
  },
  AvgDialog_18712_Content_23 = {
    Text = "Onde spirituali così familiari... Possibile che siano i Mille Miraggi?!"
  },
  AvgDialog_18712_Content_24 = {
    Text = "È un potere che ha la stessa origine dei Mille Miraggi, ed è per questo che riesco a percepire la sua posizione."
  },
  AvgDialog_18712_Content_25 = {
    Text = "Ormai è completamente fuori controllo e continua a crescere.\nDobbiamo agire in fretta."
  },
  AvgDialog_18712_Content_26 = {Text = "Quindi..."},
  AvgDialog_18712_Content_27 = {
    Text = "Daffodil si chinò improvvisamente verso di te, afferrando la Chiave d'Argento sul tuo petto."
  },
  AvgDialog_18712_Content_28 = {
    Text = "Ti va di fare squadra con me, %player%?"
  },
  AvgDialog_18712_Content_29 = {
    Text = "Oh, vuoi creare un Legame con me?"
  },
  AvgDialog_18712_Content_3 = {
    Text = "Mi dispiace... Ti ho lasciato qui di proposito per attirarlo fuori. Nel tuo cuore mi stai incolpando, vero?"
  },
  AvgDialog_18712_Content_30 = {
    Text = "Dopo tutto questo tempo passato a lavorare insieme, pensavo che avremmo raggiunto una certa intesa ormai."
  },
  AvgDialog_18712_Content_31 = {
    Text = "Oppure... non sei sicuro di riuscire a tenermi testa?"
  },
  AvgDialog_18712_Content_32 = {
    Text = "Heh... Vogliamo provare?"
  },
  AvgDialog_18712_Content_33 = {
    Text = "Chiudi gli occhi e ti concentri, sollecitando la Chiave d'Argento sul tuo petto."
  },
  AvgDialog_18712_Content_34 = {
    Text = "Ben presto, la Chiave d'argento inizia a emettere una vibrazione debole e continua, e il freddo bagliore bianco avvolge rapidamente l'intera camera oscura."
  },
  AvgDialog_18712_Content_35 = {
    Text = "Ti sembra di trovarti in un immenso mare di tempo."
  },
  AvgDialog_18712_Content_36 = {
    Text = "Un'energia estranea si propaga a Ondate nel tuo petto, un torrente che attraversa le Dimensioni."
  },
  AvgDialog_18712_Content_37 = {
    Text = [[
Attraverso il vasto mare del tempo, Daffodil ti osserva in silenzio.
In questo istante, un'Espressione sottile e sconosciuta appare sul suo volto.]]
  },
  AvgDialog_18712_Content_38 = {
    Text = "È una sicurezza assoluta, incontestabile, forgiata nel corso di centinaia di anni attraverso innumerevoli scontri e Battaglie."
  },
  AvgDialog_18712_Content_39 = {
    Text = "Partiamo, %player%. Sono pronta."
  },
  AvgDialog_18712_Content_4 = {Text = "..."},
  AvgDialog_18712_Content_5 = {
    Text = "Sistemeremo tutto una volta usciti di qui."
  },
  AvgDialog_18712_Content_6 = {
    Text = "<Shake:La mia testa... Ridatemela...>"
  },
  AvgDialog_18712_Content_7 = {
    Text = "\"Harriet\" barcollò in avanti di due passi, protendendo invano le mani sopra il collo."
  },
  AvgDialog_18712_Content_8 = {
    Text = "Un Colpo Subito, due Colpi Subiti..."
  },
  AvgDialog_18712_Content_9 = {
    Text = "Rendendosi conto che la sua testa era ormai scomparsa, emise una serie di urla laceranti."
  },
  AvgDialog_18713_Content_1 = {
    Text = "Sta piovendo."
  },
  AvgDialog_18713_Content_10 = {
    Text = "Ti asciughi in fretta la pioggia dal viso e sbatti le palpebre, solo per renderti conto che qualcuno ti sta davvero rivolgendo la parola."
  },
  AvgDialog_18713_Content_11 = {
    Text = "Credevo che non vivesse più nessuno qui."
  },
  AvgDialog_18713_Content_12 = {
    Text = "La maggior parte della gente se n'è andata."
  },
  AvgDialog_18713_Content_13 = {
    Text = "Chi era malato o anziano scelse di restare, mentre alcuni uscirono e poi tornarono..."
  },
  AvgDialog_18713_Content_14 = {
    Text = "Non tutti riescono ad adattarsi alla vita là fuori."
  },
  AvgDialog_18713_Content_15 = {
    Text = "Capisco. Ma non ho visto nessuno poco fa."
  },
  AvgDialog_18713_Content_16 = {
    Text = "...Detestano avere a che fare con gli estranei."
  },
  AvgDialog_18713_Content_17 = {
    Text = "Ti guardi intorno, osservando le case rade e fatiscenti."
  },
  AvgDialog_18713_Content_18 = {
    Text = "Attraverso le finestre nere come la pece, si intravedono sguardi silenziosi, colmi di diffidenza e ostilità."
  },
  AvgDialog_18713_Content_19 = {
    Text = "Salve, signora. Posso chiederle—"
  },
  AvgDialog_18713_Content_2 = {
    Text = "Cammini da solo sotto la pioggia, l'acqua fredda e umida ti inzuppa i vestiti e si aggrappa alla pelle."
  },
  AvgDialog_18713_Content_20 = {
    Text = "Ha visto qualcosa di strano?"
  },
  AvgDialog_18713_Content_21 = {
    Text = "Cose strane...?"
  },
  AvgDialog_18713_Content_22 = {
    Text = "Ehm... che sia una persona o una bestia, si muove con estrema rapidità."
  },
  AvgDialog_18713_Content_23 = {
    Text = "La donna scosse la testa."
  },
  AvgDialog_18713_Content_24 = {
    Text = "È passato molto tempo dall'ultima volta che qualcuno è venuto qui; persino gli avvoltoi rifiutano di avvicinarsi."
  },
  AvgDialog_18713_Content_25 = {
    Text = "Ha visto Daffodil?"
  },
  AvgDialog_18713_Content_26 = {
    Text = "Avete visto una bella signora con un lungo vestito viola?"
  },
  AvgDialog_18713_Content_27 = {
    Text = "La donna scosse la testa."
  },
  AvgDialog_18713_Content_28 = {
    Text = "È passato molto tempo dall'ultima volta che qualcuno è venuto qui; persino gli avvoltoi rifiutano di avvicinarsi."
  },
  AvgDialog_18713_Content_29 = {
    Text = "<Big:Boom—>"
  },
  AvgDialog_18713_Content_3 = {
    Text = "Attraversi una casa abbandonata dopo l'altra, passando accanto a una tomba dopo l'altra."
  },
  AvgDialog_18713_Content_30 = {
    Text = "La pioggia cade sempre più forte, tingendo ogni cosa di grigio."
  },
  AvgDialog_18713_Content_31 = {
    Text = "La figura della donna comincia a sfumare e a perdere nitidezza, e persino la sua voce si fa sempre più flebile..."
  },
  AvgDialog_18713_Content_32 = {
    Text = "Entra, {Male=sir,Female=miss}. Ti prenderai un raffreddore con questa pioggia battente..."
  },
  AvgDialog_18713_Content_33 = {Text = "..."},
  AvgDialog_18713_Content_34 = {
    Text = "Con piacere."
  },
  AvgDialog_18713_Content_4 = {
    Text = "Ovunque vadano, non restano che cicatrici e desolazione."
  },
  AvgDialog_18713_Content_5 = {
    Text = "Solo pioggia. Una pioggia incessante e gelida ti accompagna per tutto il cammino."
  },
  AvgDialog_18713_Content_6 = {Text = "Custode..."},
  AvgDialog_18713_Content_7 = {
    Text = "Una donna anziana è in piedi davanti alla capanna e ti fa cenno con la mano."
  },
  AvgDialog_18713_Content_8 = {
    Text = "Indossava un vestito spento, il volto celato nella pioggia grigia, confondendosi perfettamente con la casa fatiscente alle sue spalle."
  },
  AvgDialog_18713_Content_9 = {
    Text = "{Male=Sir,Female=Miss}, sembri avere molto freddo... Vuoi entrare a sederti un momento?"
  },
  AvgDialog_18714_Content_1 = {
    Text = "Squarcio di Tempesta"
  },
  AvgDialog_18714_Content_10 = {
    Text = "Una sola persona?!"
  },
  AvgDialog_18714_Content_11 = {
    Text = "Oh cielo, hai un aspetto terribile. Serve aiuto?"
  },
  AvgDialog_18714_Content_12 = {
    Text = "Fai un passo indietro. Ho qualcosa da chiederti."
  },
  AvgDialog_18714_Content_13 = {
    Text = "Questo è davvero offensivo. Cosa, emano forse qualche odore sgradevole?"
  },
  AvgDialog_18714_Content_14 = {
    Text = "Non saprei... Forse il profumo dei morti?"
  },
  AvgDialog_18714_Content_15 = {
    Text = "Beren Stock, Dwight Williams... Questi nomi ti dicono qualcosa?"
  },
  AvgDialog_18714_Content_16 = {Text = "..."},
  AvgDialog_18714_Content_17 = {
    Text = "Capisco, sospetti che io sia il Cacciatore di Teschi."
  },
  AvgDialog_18714_Content_18 = {
    Text = "E tu conosci chiaramente i nomi delle vittime del Cacciatore di Teschi."
  },
  AvgDialog_18714_Content_19 = {Text = "..."},
  AvgDialog_18714_Content_2 = {
    Text = "Daffodil passeggia verso di te con un'aria di disinvolta eleganza, come se fosse qui in vacanza."
  },
  AvgDialog_18714_Content_20 = {
    Text = "Pensavo avessimo costruito un po' di fiducia reciproca dopo Rye."
  },
  AvgDialog_18714_Content_21 = {
    Text = "Il Cacciatore di Teschi mi ha sottratto un <Yellow:teschio prezioso>, quindi sto solo conducendo una piccola indagine. È semplice quanto sembra."
  },
  AvgDialog_18714_Content_22 = {
    Text = "Di chi sarà mai... questa preziosa testa?"
  },
  AvgDialog_18714_Content_23 = {Text = "..."},
  AvgDialog_18714_Content_24 = {
    Text = "Daffodil ti sorride. Sfoggia sempre questo sorriso quando non vuole rispondere alle domande degli altri."
  },
  AvgDialog_18714_Content_25 = {
    Text = "Se ricordo bene, hai sempre avuto l'abitudine di collezionare teste. Rainy Town dista meno di 15 miglia in linea d'aria da Rye, rendendo il viaggio di andata e ritorno piuttosto comodo."
  },
  AvgDialog_18714_Content_26 = {
    Text = "Spiacente, io colleziono teste, non le produco."
  },
  AvgDialog_18714_Content_27 = {
    Text = "C'è una sottile differenza tra le due cose... Credo che tu possa capirlo, nostro brillante Custode?"
  },
  AvgDialog_18714_Content_28 = {
    Text = [[
Certo, capisco.
Allora, dove ti trovavi e cosa stavi facendo alle 8:15 di ieri sera?]]
  },
  AvgDialog_18714_Content_29 = {
    Text = "Fammi pensare... Il negozio ha ricevuto una nuova partita di sali da bagno, così li ho provati nella vasca."
  },
  AvgDialog_18714_Content_3 = {Text = "Sei tu...?"},
  AvgDialog_18714_Content_30 = {
    Text = "Allora, vuoi sentire i dettagli del mio processo?"
  },
  AvgDialog_18714_Content_31 = {
    Text = "Davvero? Eppure quando ti ho vista ieri notte, eri in piedi da sola sotto il lampione, stringendo una testa umana."
  },
  AvgDialog_18714_Content_32 = {
    Text = "Non sembra affatto sale da bagno."
  },
  AvgDialog_18714_Content_33 = {Text = "..."},
  AvgDialog_18714_Content_34 = {
    Text = "Stai dicendo... che ieri notte hai visto qualcuno identico a me?"
  },
  AvgDialog_18714_Content_35 = {
    Text = "Ricordi di aver visto Daffodil la scorsa notte."
  },
  AvgDialog_18714_Content_36 = {
    Text = "Senza dubbio, il loro aspetto è quasi identico, ma il portamento e l'aura sono profondamente diversi."
  },
  AvgDialog_18714_Content_37 = {
    Text = "O piuttosto, ho visto <Yellow:te>, non qualcuno che ti somiglia."
  },
  AvgDialog_18714_Content_38 = {
    Text = "Tutte le prove sfavorevoli ora puntano verso di te, e ho ogni ragione di sospettare di te."
  },
  AvgDialog_18714_Content_39 = {
    Text = "Hmm, la tua diffidenza è davvero fondata."
  },
  AvgDialog_18714_Content_4 = {
    Text = "Oh cielo, qualcuno sembra restio a vedermi?"
  },
  AvgDialog_18714_Content_40 = {Text = "..."},
  AvgDialog_18714_Content_41 = {
    Text = "Non hai nulla da spiegare?"
  },
  AvgDialog_18714_Content_42 = {
    Text = "Daffodil ti guardò con sorpresa, come se avessi posto una domanda assurda."
  },
  AvgDialog_18714_Content_43 = {
    Text = "Spiegare? Mi dispiace, non devo spiegare nulla a nessuno."
  },
  AvgDialog_18714_Content_44 = {
    Text = "Si avvicina a te con passo aggraziato."
  },
  AvgDialog_18714_Content_45 = {
    Text = "L'ampia gonna fruscia tra le foglie morte, mentre un fumo viola si avvolge come viticci tutt'intorno."
  },
  AvgDialog_18714_Content_46 = {
    Text = "L'istante successivo, svanisce nel nulla davanti ai tuoi occhi."
  },
  AvgDialog_18714_Content_47 = {
    Text = "Le nuvole basse bloccano completamente la luce del sole, facendoti sentire come immerso in un grigio sogno, con i sussurri di Daffodil che indugiano nelle tue orecchie—"
  },
  AvgDialog_18714_Content_48 = {
    Text = "Dato che pensi che io sia il \"Cacciatore di Teschi\"... e adesso? Cosa intendi fare con me?"
  },
  AvgDialog_18714_Content_49 = {
    Text = "O piuttosto... cosa potresti farmi?"
  },
  AvgDialog_18714_Content_5 = {
    Text = "Il desolato vento autunnale soffia alle tue spalle. Ti volti, ma non c'è nulla davanti a te; il Vecchio Freeman è svanito da tempo."
  },
  AvgDialog_18714_Content_6 = {
    Text = "Ripensando a tutto ciò che è appena accaduto, sembrava un incubo."
  },
  AvgDialog_18714_Content_7 = {
    Text = "Sig. Freeman...?"
  },
  AvgDialog_18714_Content_8 = {
    Text = "Hmm, hai portato un accompagnatore? È quella ragazza che ha sempre quell'aria così seria?"
  },
  AvgDialog_18714_Content_9 = {
    Text = "Poco fa eri qui in piedi da solo, completamente immobile, come posseduto."
  },
  AvgDialog_18715_Content_1 = {
    Text = "Mi arrendo, {Male=Mr.,Female=Miss} Custode."
  },
  AvgDialog_18715_Content_10 = {
    Text = "Sprofondi in un mare di essenza primordiale grigia."
  },
  AvgDialog_18715_Content_11 = {
    Text = "La luce del giorno ferisce i tuoi occhi, rivelando una distesa infinita di oceano grigio."
  },
  AvgDialog_18715_Content_12 = {
    Text = "Le onde grigie impetuose brillano di una luce scintillante, punteggiate da innumerevoli macchie nere."
  },
  AvgDialog_18715_Content_13 = {
    Text = "Man mano che la tua visuale si adatta, ti rendi conto che non si tratta di macchie nere, ma soltanto di teschi."
  },
  AvgDialog_18715_Content_14 = {
    Text = "Innumerevoli teste sono sommerse nel mare grigio, sollevandosi e sprofondando con le onde. Gridano e si lamentano, annegando in un immenso pianto e terrore."
  },
  AvgDialog_18715_Content_15 = {
    Text = "<Change>Cristalli, cristalli..."
  },
  AvgDialog_18715_Content_16 = {
    Text = "<Shake:Non toccare quel libretto, non toccarlo...>"
  },
  AvgDialog_18715_Content_17 = {
    Text = "<Shake:San Pedro, lasciami tornare, lasciami tornare...>"
  },
  AvgDialog_18715_Content_18 = {
    Text = "Innumerevoli voci stridono nelle tue orecchie, costringendoti a coprirle, come se migliaia di aghi trafiggessero la tua mente."
  },
  AvgDialog_18715_Content_19 = {
    Text = "Hmm... <Big:AAAAAHHH...!!>"
  },
  AvgDialog_18715_Content_2 = {
    Text = "Poiché non sopporto di vederti soffrire, continuare questo scontro sarebbe solo uno spreco del tempo di tutti."
  },
  AvgDialog_18715_Content_20 = {
    Text = "Sangue caldo cola dalle orecchie e dalle narici, generando onde immense nel momento in cui tocca l'acqua."
  },
  AvgDialog_18715_Content_21 = {
    Text = "La marea avanza in un'ondata di rabbia e terrore, trascinando innumerevoli teste che ondeggiano tra i flutti, precipitandosi verso di te."
  },
  AvgDialog_18715_Content_22 = {
    Text = "<Change>No, no..."
  },
  AvgDialog_18715_Content_23 = {
    Text = "<Shake:Intrusi... Intrusi!!>"
  },
  AvgDialog_18715_Content_24 = {
    Text = "Non hai via d'uscita. Chiudi gli occhi."
  },
  AvgDialog_18715_Content_25 = {Text = "Ngh...!"},
  AvgDialog_18715_Content_26 = {
    Text = "Cough... Cough..."
  },
  AvgDialog_18715_Content_27 = {
    Text = "Daffodil si tenne la fronte e ti guardò accigliata."
  },
  AvgDialog_18715_Content_28 = {
    Text = "Già fuori...? Pensavo di poterti tenere intrappolato almeno per un giorno intero."
  },
  AvgDialog_18715_Content_29 = {
    Text = "Sembra che siamo destinati a essere legati l'uno all'altro, non è vero?"
  },
  AvgDialog_18715_Content_3 = {
    Text = "Date le differenze inconciliabili tra noi, ti suggerisco di smettere di importunarmi."
  },
  AvgDialog_18715_Content_30 = {
    Text = "La testa... mi fa male..."
  },
  AvgDialog_18715_Content_31 = {
    Text = "Cos'era quello appena ora...? Che genere di cosa era...?"
  },
  AvgDialog_18715_Content_32 = {
    Text = "Questo è il mio spazio ultra-dimensionale. L'ho chiamato <Yellow:Mille Miraggi>.\nChe ne pensi? Non è affascinante?"
  },
  AvgDialog_18715_Content_33 = {Text = "..."},
  AvgDialog_18715_Content_34 = {
    Text = "%player%, ti sta uscendo sangue dal naso. Aspetta, ti sanguinano anche le orecchie..."
  },
  AvgDialog_18715_Content_35 = {
    Text = "<Shake:Sto bene... State lontani...>"
  },
  AvgDialog_18715_Content_36 = {
    Text = "Non è saggio fare il duro adesso; riesci a malapena a stare in piedi."
  },
  AvgDialog_18715_Content_37 = {
    Text = "*Coff coff*... non avvicinarti..."
  },
  AvgDialog_18715_Content_38 = {
    Text = "La tua visuale si oscura, e crolli pesantemente a terra."
  },
  AvgDialog_18715_Content_39 = {
    Text = "Nell'oscurità, ti sembra di udire una voce familiare."
  },
  AvgDialog_18715_Content_4 = {
    Text = "Daffodil, con un'espressione gelida, tracciò rapidamente nell'aria una serie di rune viola luminescenti."
  },
  AvgDialog_18715_Content_40 = {
    Text = "Gentile, indifferente, avvolta in un ronzio elettrico leggermente aspro, che appare distante e vaga."
  },
  AvgDialog_18715_Content_41 = {
    Text = "%player%, riesci a sentirmi adesso...<Red:Direzione d'indagine errata>..."
  },
  AvgDialog_18715_Content_42 = {
    Text = [[
Il Cacciatore di Teschi colpisce ancora...
Tre vittime, tutte decapitate...]]
  },
  AvgDialog_18715_Content_43 = {
    Text = "Solo un momento fa..."
  },
  AvgDialog_18715_Content_5 = {
    Text = "<Change>Mille Miraggi, attivazione."
  },
  AvgDialog_18715_Content_6 = {
    Text = "Il mondo davanti ai tuoi occhi si trasforma improvvisamente in riflessi frammentati nell'acqua, che tremolano dolcemente di fronte a te."
  },
  AvgDialog_18715_Content_7 = {
    Text = "Istintivamente allunghi la mano, ma vieni risucchiato in un vortice profondo nel momento in cui tocchi i riflessi."
  },
  AvgDialog_18715_Content_8 = {Text = "AAAHHH—!"},
  AvgDialog_18715_Content_9 = {
    Text = "Quello è..."
  },
  AvgDialog_18716_Content_1 = {Text = "Aaahh—!!"},
  AvgDialog_18716_Content_10 = {
    Text = "I fili si contrassero all'improvviso, sfondando la porta della camera da letto mentre innumerevoli teste rotolavano fuori."
  },
  AvgDialog_18716_Content_11 = {
    Text = "Quando ritorni in te, una testa vagamente familiare è già attaccata al collo vuoto di Harriet."
  },
  AvgDialog_18716_Content_12 = {
    Text = "Questa testa... Questo volto..."
  },
  AvgDialog_18716_Content_13 = {
    Text = "Beren Stock, la vittima precedente... Che sta succedendo?!"
  },
  AvgDialog_18716_Content_14 = {
    Text = "Il teschio pallido emette un rigido scricchiolio e infine apre i suoi occhi privi di messa a fuoco."
  },
  AvgDialog_18716_Content_15 = {
    Text = "La rinata \"Harriet\" sogghigna e si lancia verso di te a una velocità incredibile."
  },
  AvgDialog_18716_Content_16 = {
    Text = "Aaaahhh—!!"
  },
  AvgDialog_18716_Content_18 = {
    Text = "La fredda lama fende spietata l'oscurità."
  },
  AvgDialog_18716_Content_19 = {
    Text = "L'istante successivo, la testa di \"Harriet\" volò via con grazia, rotolando accanto alla sua ampia gonna."
  },
  AvgDialog_18716_Content_2 = {
    Text = "Harriet crollò a terra, emettendo un grido lacerante dal profondo della gola."
  },
  AvgDialog_18716_Content_20 = {
    Text = "Whew... Sembra che non sia troppo tardi."
  },
  AvgDialog_18716_Content_21 = {
    Text = "Hai un bell'aspetto, %player%."
  },
  AvgDialog_18716_Content_3 = {
    Text = "Fai un passo avanti e la afferri per il colletto."
  },
  AvgDialog_18716_Content_4 = {
    Text = "Parla, chi sono i tuoi complici e dove si trovano? Il Vecchio Freeman è uno di loro?"
  },
  AvgDialog_18716_Content_5 = {
    Text = "Freeman...? Heh... Hehehe..."
  },
  AvgDialog_18716_Content_6 = {
    Text = "Il suo volto si contorse violentemente, con innumerevoli pustole che si gonfiavano sotto la pelle sottile, sul punto di esplodere."
  },
  AvgDialog_18716_Content_7 = {
    Text = "Zzzzap—!!"
  },
  AvgDialog_18716_Content_8 = {
    Text = "La testa di Harriet esplose in una poltiglia tiepida."
  },
  AvgDialog_18716_Content_9 = {
    Text = "Il suo collo si contorceva senza sosta, con D-melma mista a sangue che formava fili sottili protesi verso il soffitto, le pareti e il pavimento..."
  },
  AvgDialog_18717_Content_1 = {
    Text = "Musa Felina"
  },
  AvgDialog_18717_Content_10 = {
    Text = "È stata un'esperienza piuttosto interessante."
  },
  AvgDialog_18717_Content_11 = {
    Text = "Le memorie originariamente dolorose, reinterpretate attraverso le immagini, hanno inaspettatamente acquisito un fascino comico."
  },
  AvgDialog_18717_Content_12 = {
    Text = "Ho sentito che in seguito avete fondato un club cinematografico chiamato <Yellow:\"Felin Poetry Society\">?"
  },
  AvgDialog_18717_Content_13 = {
    Text = "Sì... A volte aiuto a scrivere le sceneggiature, anche se sono sempre stata una pessima drammaturga."
  },
  AvgDialog_18717_Content_14 = {
    Text = "È stata Lady Daffodil ad aiutarmi a lasciarmi il passato alle spalle, indipendentemente dalle sue vere intenzioni."
  },
  AvgDialog_18717_Content_15 = {
    Text = "Sono sempre stato grato a Lady Daffodil."
  },
  AvgDialog_18717_Content_16 = {
    Text = "Capisco, quindi è questo che ti ha detto."
  },
  AvgDialog_18717_Content_17 = {
    Text = "Sono anche profondamente grata alla Sig.na Horla. È stato un bellissimo incontro."
  },
  AvgDialog_18717_Content_18 = {
    Text = "Quindi, per riguardo alla Sig.na Horla, mi fiderò di te questa volta."
  },
  AvgDialog_18717_Content_19 = {
    Text = "<LightGray:Inoltre, le persone inviate dalla scuola sono già in cammino.>"
  },
  AvgDialog_18717_Content_2 = {
    Text = "2:15, Via Kenting"
  },
  AvgDialog_18717_Content_20 = {
    Text = "<LightGray:Se dovessi assentarmi troppo a lungo, non resteranno certo con le mani in mano...>"
  },
  AvgDialog_18717_Content_21 = {
    Text = "Allora partiamo, {Male=Mr.,Female=Miss} Custode."
  },
  AvgDialog_18717_Content_22 = {
    Text = "Daffodil annuì felice, porgendoti la mano."
  },
  AvgDialog_18717_Content_23 = {Text = "..."},
  AvgDialog_18717_Content_24 = {
    Text = "Stringi delicatamente la mano di Daffodil. Contrariamente alle aspettative, la sua mano è morbida e calda."
  },
  AvgDialog_18717_Content_25 = {
    Text = "Tieni duro, Custode."
  },
  AvgDialog_18717_Content_26 = {
    Text = "Il tuo passo vacilla, e vieni trascinato in una Dimensione profonda."
  },
  AvgDialog_18717_Content_27 = {
    Text = "Bentornato/a nel mio \"Mille Miraggi\"."
  },
  AvgDialog_18717_Content_28 = {
    Text = "Ecco di nuovo il familiare Mare dell'Essenza Primordiale, con le teste che ancora ondeggiano al ritmo delle onde."
  },
  AvgDialog_18717_Content_29 = {
    Text = "A differenza dell'ultima volta, le teste sembrano molto più silenziose ora. Le loro orbite vuote si rivolgono tutte verso di te, eppure continuano a sussurrare tra loro."
  },
  AvgDialog_18717_Content_3 = {
    Text = "Non mi aspettavo che accettassi di venire con me così prontamente. Non temi che possa portarti in qualche luogo bizzarro?"
  },
  AvgDialog_18717_Content_30 = {
    Text = "Daffodil agitò lievemente la mano, e due teste tremarono mentre fluttuavano fino all'altezza dei suoi occhi."
  },
  AvgDialog_18717_Content_31 = {
    Text = "<Change>Mio signore..."
  },
  AvgDialog_18717_Content_32 = {
    Text = "<Change>È passato molto tempo..."
  },
  AvgDialog_18717_Content_33 = {
    Text = "<Change>Aiutami a trovare qualcuno..."
  },
  AvgDialog_18717_Content_34 = {
    Text = "Daffodil e il teschio sussurrano in una lingua che non riesci a comprendere. Qualunque cosa abbiano discusso, l'ha fatta ridere felice."
  },
  AvgDialog_18717_Content_35 = {
    Text = "Non l'hai mai vista sorridere così; sembra fuori luogo."
  },
  AvgDialog_18717_Content_36 = {
    Text = "Invece, ha attraversato centinaia di anni ed è atterrato in un angolo di una storia a te sconosciuta."
  },
  AvgDialog_18717_Content_37 = {Text = "..."},
  AvgDialog_18717_Content_38 = {
    Text = "Che c'è? Ho qualcosa in faccia?"
  },
  AvgDialog_18717_Content_39 = {
    Text = "Sembri raggiante."
  },
  AvgDialog_18717_Content_4 = {
    Text = "Allora, mi... porterai in luoghi strani?"
  },
  AvgDialog_18717_Content_40 = {
    Text = "Queste sono tutte le mie collezioni più preziose."
  },
  AvgDialog_18717_Content_41 = {
    Text = "È passato molto tempo dal mio ultimo ritorno. Mi mancano terribilmente."
  },
  AvgDialog_18717_Content_42 = {
    Text = "Di cosa stai parlando?"
  },
  AvgDialog_18717_Content_43 = {
    Text = "Passato, presente e futuro."
  },
  AvgDialog_18717_Content_44 = {
    Text = "Ciascuna di queste teste è una <Yellow:proiezione dalla realtà>. La loro visuale e memoria trascendono le dimensioni del tempo e dello spazio, aiutandomi a scoprire molte cose inaspettate."
  },
  AvgDialog_18717_Content_45 = {
    Text = "Ecco perché il tuo negozio ha così tanti oggetti strani e insoliti...?"
  },
  AvgDialog_18717_Content_46 = {
    Text = "Daffodil batté le palpebre, acconsentendo tacitamente alla tua ipotesi."
  },
  AvgDialog_18717_Content_47 = {
    Text = "Da dove vengono tutte queste teste?"
  },
  AvgDialog_18717_Content_48 = {
    Text = [[
Commercio, doni e un pizzico di fortuna.
Naturalmente, ne ho anche presi alcuni io stessa.]]
  },
  AvgDialog_18717_Content_49 = {
    Text = "Si dice che tu abbia dato la caccia a ben @1 teste — e questo è solo il numero ufficialmente registrato."
  },
  AvgDialog_18717_Content_5 = {
    Text = "Naturalmente."
  },
  AvgDialog_18717_Content_50 = {
    Text = "Daffodil aspirò pigramente una lunga boccata dalla sua pipa, poi esalò un filo di fumo bianco."
  },
  AvgDialog_18717_Content_51 = {
    Text = "Mi spiace deluderti, Custode {Male=Mr.,Female=Miss}, ma i rimproveri morali non mi fanno effetto."
  },
  AvgDialog_18717_Content_52 = {
    Text = "Le regole create dagli umani non si applicano a noi. Ciò che vedi ora sono io, con occhi e naso come i tuoi..."
  },
  AvgDialog_18717_Content_53 = {
    Text = "Daffodil raccolse la Chiave d'Argento sul tuo petto, tracciandone delicatamente i motivi intricati."
  },
  AvgDialog_18717_Content_54 = {
    Text = "Un ronzio caotico e vibrazioni le riempiono il petto, scontrandosi ferocemente come una guerra silenziosa."
  },
  AvgDialog_18717_Content_55 = {
    Text = "Lo senti? Non siamo umani. Siamo \"bestie\", o come alcuni ci chiamerebbero..."
  },
  AvgDialog_18717_Content_56 = {
    Text = "Noi siamo <Yellow:esseri superiori>."
  },
  AvgDialog_18717_Content_57 = {
    Text = "Tolleriamo gli umani ignoranti, seguiamo regole in continuo mutamento, obbediamo a Legami fragili, tutto per terrore..."
  },
  AvgDialog_18717_Content_58 = {
    Text = "Ti accarezza dolcemente il volto."
  },
  AvgDialog_18717_Content_59 = {
    Text = "E una promessa."
  },
  AvgDialog_18717_Content_6 = {Text = "..."},
  AvgDialog_18717_Content_60 = {Text = "..."},
  AvgDialog_18717_Content_61 = {
    Text = "Così sei diventata una delle poche Risvegliate registrate senza alcun Legame."
  },
  AvgDialog_18717_Content_62 = {
    Text = "Nessuno nasce per godere dell'essere controllato; la maggior parte delle creature anela per natura alla libertà."
  },
  AvgDialog_18717_Content_63 = {
    Text = "Personalmente, non mi dispiace il cosiddetto \"Legame\"... Finché è reciprocamente vantaggioso, perché preoccuparsi delle apparenze?"
  },
  AvgDialog_18717_Content_64 = {
    Text = "Il problema potrebbe non essere mio.\nNessuno stringe un Legame con me perché non ne sono all'altezza. Chiaro?"
  },
  AvgDialog_18717_Content_65 = {Text = "Ehm..."},
  AvgDialog_18717_Content_66 = {
    Text = "E io? Sono anch'io uno di quei \"non qualificati\"...?"
  },
  AvgDialog_18717_Content_67 = {
    Text = "Daffodil scoppiò a ridere, ma il fumo le andò di traverso e non poté fare a meno di tossire più volte."
  },
  AvgDialog_18717_Content_68 = {
    Text = "Non preoccuparti, ragazzo... Conoscerai la risposta molto presto."
  },
  AvgDialog_18717_Content_69 = {
    Text = "<LightGray:Un'altra risposta ambigua...>"
  },
  AvgDialog_18717_Content_7 = {
    Text = "In realtà... la Sig.na Horla mi ha parlato del vostro primo incontro questo pomeriggio. Ha detto—"
  },
  AvgDialog_18717_Content_70 = {
    Text = "Ops, forse ho detto un po' troppo."
  },
  AvgDialog_18717_Content_71 = {
    Text = "Daffodil alzò la mano e diede un colpetto su ciascuna fronte, facendoli fluttuare via docilmente."
  },
  AvgDialog_18717_Content_72 = {
    Text = "<Change>Grazie a tutti."
  },
  AvgDialog_18717_Content_73 = {
    Text = "D'accordo. Andiamo, Custode."
  },
  AvgDialog_18717_Content_74 = {
    Text = "Conosco già la posizione del Cacciatore di Teschi."
  },
  AvgDialog_18717_Content_8 = {
    Text = "In seguito ho scoperto che aveva trasformato quel ricordo in qualcosa chiamato \"film.\""
  },
  AvgDialog_18717_Content_9 = {
    Text = "Mi sono seduta tra il pubblico e ho guardato il primo film della mia vita."
  },
  AvgDialog_18718_Content_1 = {
    Text = "Un Ricongiungimento Solitario"
  },
  AvgDialog_18718_Content_10 = {
    Text = "Questo è il mio focolare.\nNon ho altro posto dove andare."
  },
  AvgDialog_18718_Content_11 = {
    Text = "Per gente di campagna come noi, è lo stesso ovunque si vada."
  },
  AvgDialog_18718_Content_12 = {
    Text = "Lady Harriet..."
  },
  AvgDialog_18718_Content_13 = {
    Text = "L'atmosfera all'interno della casa si fece alquanto pesante."
  },
  AvgDialog_18718_Content_14 = {
    Text = "La pioggia cade ancora sommessa mentre tu e lei rivolgete lo sguardo all'interminabile cortina di pioggia."
  },
  AvgDialog_18718_Content_15 = {
    Text = "L'esterno è avvolto in una nebbia grigia, il vapore acqueo vi stringe in una morsa, come se foste l'unica vita rimasta tra cielo e terra."
  },
  AvgDialog_18718_Content_16 = {
    Text = "<LightGray:Dove si trova ora Lady Daffodil...>"
  },
  AvgDialog_18718_Content_17 = {
    Text = "Attendi un momento, {Male=sir,Female=miss}. Vado a preparare del tè caldo in cucina."
  },
  AvgDialog_18718_Content_18 = {
    Text = "Per quanto sia umile qui, posso ancora offrirvi una tazza di tè."
  },
  AvgDialog_18718_Content_19 = {
    Text = "La signora Harriet trascinò i suoi passi lenti verso la cucina."
  },
  AvgDialog_18718_Content_2 = {
    Text = "Segui la donna nella capanna di legno.\nL'interno è molto semplice, e avverti un odore di legno umido."
  },
  AvgDialog_18718_Content_20 = {
    Text = "Finché la sua sagoma non fu divorata dalle ombre profonde del corridoio, tornaste infine in voi."
  },
  AvgDialog_18718_Content_21 = {
    Text = "Sembra che ci vorrà ancora un po' prima che la pioggia smetta. Diamo un'occhiata in giro."
  },
  AvgDialog_18718_Content_3 = {
    Text = "La donna si chinò lentamente, raccolse qualche pezzo di legna dall'angolo e la gettò nella piccola stufa scura."
  },
  AvgDialog_18718_Content_4 = {
    Text = "Mettete le mani qui, scaldatele ancora un po', e non sentirete più freddo."
  },
  AvgDialog_18718_Content_5 = {
    Text = "La ringrazio molto..."
  },
  AvgDialog_18718_Content_6 = {
    Text = "Il mio nome è Harriet: @1, {Male=sir,Female=miss}. Puoi chiamarmi Harriet."
  },
  AvgDialog_18718_Content_7 = {
    Text = "Certo, signora Harriet. A dire il vero, sono curioso: perché resta qui?"
  },
  AvgDialog_18718_Content_8 = {
    Text = "Questa zona non sembra molto abitabile."
  },
  AvgDialog_18718_Content_9 = {
    Text = "La signora Harriet si accovacciò, armeggiando con la legna. Le fiamme tremolanti danzavano sul suo volto scarno e stanco."
  },
  AvgDialog_18719_Content_1 = {
    Text = "Raduno della Caccia al Teschio"
  },
  AvgDialog_18719_Content_10 = {
    Text = "La notte scorsa non sei riuscito a raggiungere Daffodil e hai potuto solo seguire l'indirizzo fornito da Ramona fino alla residenza di Horla."
  },
  AvgDialog_18719_Content_11 = {
    Text = "B-Buongiorno, Signorina Horla."
  },
  AvgDialog_18719_Content_12 = {
    Text = "Buongiorno, {Male=Mr.,Female=Miss} %player%."
  },
  AvgDialog_18719_Content_13 = {Text = "..."},
  AvgDialog_18719_Content_14 = {Text = "..."},
  AvgDialog_18719_Content_15 = {
    Text = "Un silenzio imbarazzante riempie l'aria. Ti rendi conto che questa Risvegliatrice non sembra molto portata per le relazioni sociali."
  },
  AvgDialog_18719_Content_16 = {
    Text = [[
Signorina Horla, sono qui riguardo all'incidente del Cacciatore di Teschi.
Dato che vive qui da molto tempo, ha qualche pista o informazione?]]
  },
  AvgDialog_18719_Content_17 = {
    Text = "\"Cacciatore di Teschi\"... Un momento, prego."
  },
  AvgDialog_18719_Content_18 = {
    Text = "Horla si voltò e iniziò a cercare tra gli scaffali dell'alta libreria."
  },
  AvgDialog_18719_Content_19 = {
    Text = "Trovato! *Coff, coff...*"
  },
  AvgDialog_18719_Content_2 = {Text = "Daffodil!"},
  AvgDialog_18719_Content_20 = {
    Text = "Horla spazzò via la polvere che aleggiava nell'aria e posò il taccuino ingiallito nelle tue mani."
  },
  AvgDialog_18719_Content_21 = {
    Text = "Un mese fa, la Sig.na Doll richiese la mia assistenza."
  },
  AvgDialog_18719_Content_22 = {
    Text = "Non possiedo abilità particolari, ma ho documentato tutti i casi recenti. Spero che possa essere d'aiuto."
  },
  AvgDialog_18719_Content_23 = {
    Text = "Apri il taccuino e, in una calligrafia elegante, vi trovi annotati l'ora e il luogo della scoperta di ciascun caso, compresi persino schizzi dei corpi e delle scene del crimine."
  },
  AvgDialog_18719_Content_24 = {
    Text = "<Shake:Mi scuso, le mie capacità nel disegno sono piuttosto scarse. Può semplicemente ignorarli...>"
  },
  AvgDialog_18719_Content_25 = {
    Text = "No, è davvero notevole.\nGrazie, Signorina Horla. Questi appunti sono fondamentali per noi."
  },
  AvgDialog_18719_Content_26 = {
    Text = "In ogni caso, sono lieta di poter aiutare. Quelle povere anime..."
  },
  AvgDialog_18719_Content_27 = {
    Text = "Horla lasciò sfuggire un lieve sospiro e si voltò a contemplare il cielo cupo all'esterno."
  },
  AvgDialog_18719_Content_28 = {
    Text = "Rainy Town è un luogo dove piove tutto l'anno. Tuttavia, dopo la pioggia, ciò che spesso l'attende non è un raccolto abbondante, ma inondazioni e pestilenze senza fine."
  },
  AvgDialog_18719_Content_29 = {
    Text = "I giovani lavorano nelle grandi città come Londinium, lasciandosi alle spalle solo anziani e fanciulli."
  },
  AvgDialog_18719_Content_3 = {
    Text = "Eh... Dove mi trovo?"
  },
  AvgDialog_18719_Content_30 = {
    Text = "Ora, persino gli anziani cominciano ad andarsene, uno dopo l'altro..."
  },
  AvgDialog_18719_Content_31 = {
    Text = "Ho partecipato ad alcuni funerali locali. Ogni volta che una persona cara viene a mancare, gli abitanti della città intonano un antico canto..."
  },
  AvgDialog_18719_Content_32 = {
    Text = "Horla iniziò a canticchiare sommessamente, e la melodia malinconica si condensò presto in parole scure come inchiostro."
  },
  AvgDialog_18719_Content_33 = {
    Text = [[
<RedItalic:Scriviamo col sangue come penna e col fango come carta.>
<RedItalic:Incidiamo pianto e paura con corpi intrisi di pioggia...>]]
  },
  AvgDialog_18719_Content_34 = {
    Text = "Queste parole fluirono lentamente attorno a Horla, poi formarono una lettera ingiallita che la avvolse."
  },
  AvgDialog_18719_Content_35 = {
    Text = "Lasciò sfuggire un lieve sospiro, le lacrime luccicanti nei suoi occhi."
  },
  AvgDialog_18719_Content_36 = {
    Text = "Non è forse tutto ciò che sta accadendo ora il dolore che gli abitanti di Rainy Town hanno scritto con i loro corpi intrisi di pioggia..."
  },
  AvgDialog_18719_Content_37 = {
    Text = "L'aria è colma di una depressione silenziosa e densa, che quasi ti soffoca."
  },
  AvgDialog_18719_Content_38 = {
    Text = "<Shake:Tosse, Sig.na Horla...>"
  },
  AvgDialog_18719_Content_39 = {Text = "..."},
  AvgDialog_18719_Content_4 = {
    Text = "Il cinguettio allegro degli uccelli ti riporta alla realtà, strappandoti dai tuoi sogni."
  },
  AvgDialog_18719_Content_40 = {
    Text = "Ah! Scusate, l'ho fatto di nuovo..."
  },
  AvgDialog_18719_Content_41 = {
    Text = "Horla riprese i sensi e fece due profondi respiri."
  },
  AvgDialog_18719_Content_42 = {
    Text = "Le emozioni oppressive finalmente si dissiparono, e il peso greve sul tuo petto si alleggerì notevolmente."
  },
  AvgDialog_18719_Content_43 = {Text = "..."},
  AvgDialog_18719_Content_44 = {Text = "..."},
  AvgDialog_18719_Content_45 = {
    Text = "Ah, giusto, giusto."
  },
  AvgDialog_18719_Content_46 = {
    Text = "Ho preparato una teiera di tè alla rosa con petali appena colti. Vuoi unirti a me per assaggiarlo?"
  },
  AvgDialog_18719_Content_47 = {
    Text = "Tra mezz'ora"
  },
  AvgDialog_18719_Content_48 = {
    Text = "In una mano reggi una tazza di porcellana con tè alla rosa, mentre con l'altra sfogli gli appunti di Horla, cercando un possibile punto di svolta."
  },
  AvgDialog_18719_Content_49 = {
    Text = "Dove sono quelli della stazione di polizia?"
  },
  AvgDialog_18719_Content_5 = {
    Text = "Osservi la stanza pulita e semplice con aria confusa, poi sollevi la coperta e la annusi."
  },
  AvgDialog_18719_Content_50 = {
    Text = "In Norwich Street, il luogo davanti al quale sei passato ieri notte."
  },
  AvgDialog_18719_Content_51 = {Text = "..."},
  AvgDialog_18719_Content_52 = {
    Text = "Pioggia. Sangue. Daffodil.\nRipensando all'incontro di ieri notte, non riesci a distinguere se fosse un sogno o la realtà."
  },
  AvgDialog_18719_Content_53 = {
    Text = "La tua voce è debole... Non hai riposato bene ieri notte?"
  },
  AvgDialog_18719_Content_54 = {
    Text = "No, è solo che..."
  },
  AvgDialog_18719_Content_55 = {
    Text = "Scuotesti il capo, cercando di scacciare i pensieri confusi dalla mente."
  },
  AvgDialog_18719_Content_56 = {Text = "..."},
  AvgDialog_18719_Content_57 = {
    Text = "L'indagine a Rye Town si è conclusa appena due giorni fa, e le tue ferite non si sono ancora completamente rimarginate."
  },
  AvgDialog_18719_Content_58 = {
    Text = "Sigh, non si può farci nulla se anche gli altri Investigatori sono impegnati, no?"
  },
  AvgDialog_18719_Content_59 = {
    Text = "A questo punto, chiudiamo in fretta questo caso. Voglio prendermi una vacanza."
  },
  AvgDialog_18719_Content_6 = {
    Text = "Bene. Asciutta e morbida, senza odore di pioggia né di sangue."
  },
  AvgDialog_18719_Content_60 = {
    Text = "Eh, questo è..."
  },
  AvgDialog_18719_Content_61 = {
    Text = "Il suono delle pagine sfogliate si arrestò bruscamente."
  },
  AvgDialog_18719_Content_62 = {
    Text = "Fissi lo sguardo sulla pagina immobile, iniziando a formulare il tuo prossimo piano d'indagine."
  },
  AvgDialog_18719_Content_63 = {
    Text = "Ramona... Prima di incontrare il detective, voglio andare in un posto."
  },
  AvgDialog_18719_Content_7 = {
    Text = "Buongiorno, {Male=Mr.,Female=Miss} %player%. Benvenuto/a nella mia umile dimora..."
  },
  AvgDialog_18719_Content_8 = {
    Text = "Signorina Horla?!"
  },
  AvgDialog_18719_Content_9 = {
    Text = "La Memoria comincia a tornare gradualmente."
  },
  AvgDialog_18720_Content_1 = {
    Text = "11:00, Cimitero di Highgate"
  },
  AvgDialog_18720_Content_10 = {
    Text = "Non aspettarti troppo dalla competenza dei detective nelle zone remote."
  },
  AvgDialog_18720_Content_11 = {
    Text = "...Ha senso."
  },
  AvgDialog_18720_Content_12 = {
    Text = "Tiri fuori la lente d'ingrandimento e continui a osservare lo scheletro."
  },
  AvgDialog_18720_Content_13 = {
    Text = "C'è un <Red:taglio frastagliato> sull'osso del collo..."
  },
  AvgDialog_18720_Content_14 = {
    Text = "Tuttavia, è piuttosto caotico, con numerosi tagli sovrapposti, completamente diverso da ciò che abbiamo visto nelle foto prima."
  },
  AvgDialog_18720_Content_15 = {
    Text = "Ancora piuttosto inesperto, la prima volta che commette un crimine?"
  },
  AvgDialog_18720_Content_16 = {
    Text = [[
Avvia l'indagine concentrandoti sul Cimitero.
I novizi inesperti di solito non si allontanano molto dal focolare durante il loro primo crimine.]]
  },
  AvgDialog_18720_Content_17 = {
    Text = "Capito. Questa volta sono fiducioso: il colpevole sarà catturato presto!"
  },
  AvgDialog_18720_Content_18 = {
    Text = "Assassino? Come osi presumere, *hic*, che ci sia un solo assassino?"
  },
  AvgDialog_18720_Content_19 = {
    Text = "Dalle profondità della fitta foresta emerse un vecchio, puzzolente d'alcol e con le guance arrossate."
  },
  AvgDialog_18720_Content_2 = {
    Text = "Cammini in solitudine tra i desolati tumuli funerari."
  },
  AvgDialog_18720_Content_20 = {
    Text = "Scusa, non volevo origliare il tuo monologo."
  },
  AvgDialog_18720_Content_21 = {
    Text = "Sono l'assistente di questo cimitero. Puoi chiamarmi... ehm, <Blue:Vecchio Freeman>."
  },
  AvgDialog_18720_Content_22 = {
    Text = "Buon pomeriggio, signor Freeman.\nHa appena insinuato che c'è più di un assassino?"
  },
  AvgDialog_18720_Content_23 = {
    Text = "Il Vecchio Freeman afferrò la bottiglia e tracannò il liquore, il grosso pomo d'Adamo che oscillava su e giù."
  },
  AvgDialog_18720_Content_24 = {
    Text = "Burp! Questa maledetta foresta non vede un'anima per tutto il giorno. Dato che sei qui, lascia che ti racconti una storia..."
  },
  AvgDialog_18720_Content_25 = {
    Text = "Era probabilmente all'inizio di quest'anno...? Non ricordo bene."
  },
  AvgDialog_18720_Content_26 = {
    Text = "Come al solito, bevvi e mi appisolai in un angolo ombreggiato."
  },
  AvgDialog_18720_Content_27 = {
    Text = "E poi ho sentito dei rumori strani, quasi come..."
  },
  AvgDialog_18720_Content_28 = {
    Text = "<RedItalic:Zzz... Crack...>"
  },
  AvgDialog_18720_Content_29 = {
    Text = "Uno strano suono. E poi?"
  },
  AvgDialog_18720_Content_3 = {
    Text = "I corvi planano nel cielo cupo mentre il desolato vento autunnale ulula."
  },
  AvgDialog_18720_Content_30 = {
    Text = [[
Non preoccuparti, piccolo detective.
Ho aperto gli occhi... hic, indovina cos'ho visto?]]
  },
  AvgDialog_18720_Content_31 = {
    Text = "Ma no, è solo il Cacciatore di Teschi, non è vero?"
  },
  AvgDialog_18720_Content_32 = {
    Text = "Certo, è un Cacciatore di Teschi! O, si potrebbe dire che è una donna..."
  },
  AvgDialog_18720_Content_33 = {
    Text = "Una donna sta tagliando la testa di Pinocchio!"
  },
  AvgDialog_18720_Content_34 = {
    Text = "Poi lei mi ha visto—hic—come se avesse visto un fantasma, ed è scappata più veloce di chiunque altro!"
  },
  AvgDialog_18720_Content_35 = {
    Text = "La mia povera Pinoko, il suo collo è appeso a un filo!"
  },
  AvgDialog_18720_Content_36 = {
    Text = "Haha, <Big:Hahahaha...>"
  },
  AvgDialog_18720_Content_37 = {
    Text = "Il Vecchio Freeman scoppiò in una serie di fragorose risate, versando persino lacrime di gioia."
  },
  AvgDialog_18720_Content_38 = {
    Text = "<SmallShake:Pazienza, pazienza...>"
  },
  AvgDialog_18720_Content_39 = {
    Text = "Hic, hic! È passato circa un mese, e ho sentito di nuovo quella voce..."
  },
  AvgDialog_18720_Content_4 = {Text = "Trovato."},
  AvgDialog_18720_Content_40 = {
    Text = "<RedItalic:Zzz... Crack... Crack...>"
  },
  AvgDialog_18720_Content_41 = {
    Text = "Questa volta, non è la donna a fare ritorno, ma un uomo molto magro."
  },
  AvgDialog_18720_Content_42 = {
    Text = "Che mano esperta! Con un solo fendente..."
  },
  AvgDialog_18720_Content_43 = {
    Text = "<RedBig:Whoosh!> La testa di Pinoko è sparita!"
  },
  AvgDialog_18720_Content_44 = {
    Text = "Sembra che ci fossero due Cacciatori di Teschi. Cosa successe dopo?"
  },
  AvgDialog_18720_Content_45 = {
    Text = "Dopo? Non c'è nessun dopo. Questa è l'intera storia del Vecchio Freeman e dei Granchiocefali, hic."
  },
  AvgDialog_18720_Content_46 = {
    Text = "Il Vecchio Freeman emise un rutto soddisfatto, socchiuse i suoi torbidi occhi gialli e ti squadrò da capo a piedi."
  },
  AvgDialog_18720_Content_47 = {
    Text = "Sembri del tutto all'oscuro, povero piccolo detective. Hai mai sentito parlare de <Red:La Leggenda del Cacciatore di Teschi>?"
  },
  AvgDialog_18720_Content_48 = {
    Text = "La Leggenda del Cacciatore di Teschi? Racconta pure."
  },
  AvgDialog_18720_Content_49 = {
    Text = "Il Vecchio Freeman si appoggiò pigramente alla lapide, mandò giù qualche sorso per finire il liquore rimasto nella bottiglia, e la gettò con noncuranza a terra."
  },
  AvgDialog_18720_Content_5 = {
    Text = "Ti fermi davanti a una tomba solitaria, il coperchio marcio della bara già forzato e aperto."
  },
  AvgDialog_18720_Content_50 = {
    Text = "Il liquido colò dalla bottiglia rotta, lasciando una traiettoria sinuosa sul terreno. Come lacrime, o forse sangue."
  },
  AvgDialog_18720_Content_51 = {
    Text = "Alcuni dicono che il Cacciatore di Teschi sia un mostro nato dall'<Yellow:Epidemia>."
  },
  AvgDialog_18720_Content_52 = {
    Text = "Alcuni dicono che il Cacciatore di Teschi non sia una persona sola, né due persone."
  },
  AvgDialog_18720_Content_53 = {
    Text = "<Red:I Cacciatori di Teschi sono un'organizzazione.>"
  },
  AvgDialog_18720_Content_54 = {
    Text = "Un'organizzazione?"
  },
  AvgDialog_18720_Content_55 = {
    Text = "Sì, un'organizzazione."
  },
  AvgDialog_18720_Content_56 = {
    Text = "Appaiono solo nelle notti di pioggia, i loro passi occultati dalla pioggia, strisciando silenziosamente alle tue spalle..."
  },
  AvgDialog_18720_Content_57 = {
    Text = "<RedBig:Snap!>"
  },
  AvgDialog_18720_Content_58 = {Text = "!!"},
  AvgDialog_18720_Content_59 = {
    Text = "Hahaha! E questo cos'è? Già spaventato, mio piccolo detective?"
  },
  AvgDialog_18720_Content_6 = {
    Text = "Uno scheletro senza testa giace nella bara, ormai un paradiso per muschio e insetti."
  },
  AvgDialog_18720_Content_60 = {
    Text = "Si avvicina barcollando, i suoi torbidi occhi gialli che ruotano, quasi bruciandoti addosso."
  },
  AvgDialog_18720_Content_61 = {
    Text = "Questa persona non mi convince. Meglio andarsene in fretta."
  },
  AvgDialog_18720_Content_62 = {
    Text = "Mi scusi, signor Freeman. Si è fatto tardi. Credo di dover andare..."
  },
  AvgDialog_18720_Content_63 = {
    Text = "Hai preso un leggero respiro e te ne sei andato senza voltarti indietro."
  },
  AvgDialog_18720_Content_64 = {
    Text = "Risate beffarde giungono da dietro, ma non puoi permetterti di badarci adesso. Tutto ciò che vuoi è andartene."
  },
  AvgDialog_18720_Content_65 = {
    Text = "Il cielo si oscurò gradualmente, con nubi basse e scure che bloccavano la pallida luce del sole. Il vento agitava le foglie, facendole ondeggiare come onde."
  },
  AvgDialog_18720_Content_66 = {
    Text = "In fondo al cimitero, scorgi una figura al tempo stesso familiare e sconosciuta."
  },
  AvgDialog_18720_Content_67 = {
    Text = "È Daffodil. Gran parte del suo volto è nascosta sotto la tesa del cappello calato, con i capelli grigio-bianchi che ondeggiano dolcemente nel vento."
  },
  AvgDialog_18720_Content_68 = {
    Text = "Vedendoti in uno stato così trasandato, Daffodil rise allegramente."
  },
  AvgDialog_18720_Content_69 = {
    Text = "È da un po' che non ci vediamo, Custode {Male=Mr.,Female=Miss}."
  },
  AvgDialog_18720_Content_7 = {
    Text = "L'appunto riporta che la scoperta risale a sei mesi fa; il momento della morte dev'essere ancora precedente..."
  },
  AvgDialog_18720_Content_8 = {
    Text = "In altre parole, questa è probabilmente la prima vittima conosciuta del \"Cacciatore di Teschi\". Tuttavia, i rapporti di polizia non ne hanno mai fatto menzione..."
  },
  AvgDialog_18720_Content_9 = {
    Text = "Qui non c'è un ospedale né un'agenzia funebre degni di questo nome, e nessuno presta molta attenzione ai morti."
  },
  AvgDialog_18721_Content_1 = {
    Text = "Forse potresti provare a usare la Traccia Mentale per trovare il Cacciatore di Teschi?"
  },
  AvgDialog_18721_Content_2 = {
    Text = "Questo metodo ha scarso effetto sulle creature del Reame Ultra."
  },
  AvgDialog_18721_Content_3 = {
    Text = "Nemmeno la retrospezione spirituale è onnipotente."
  },
  AvgDialog_18722_Content_1 = {
    Text = "Fino al nostro prossimo incontro"
  },
  AvgDialog_18722_Content_10 = {
    Text = "<LightGray:Un teschio prezioso? Di chi potrebbe essere...>"
  },
  AvgDialog_18722_Content_11 = {Text = "..."},
  AvgDialog_18722_Content_12 = {
    Text = "Sembri turbato, %player%. Pare che tu voglia davvero conoscere la risposta?"
  },
  AvgDialog_18722_Content_13 = {
    Text = "Sì, credo di sì."
  },
  AvgDialog_18722_Content_14 = {
    Text = "Ahem, non sono il tipo che ficca il naso nella vita privata degli altri con tanta disinvoltura."
  },
  AvgDialog_18722_Content_15 = {
    Text = "Davvero? Ma la tua espressione ti ha già tradito."
  },
  AvgDialog_18722_Content_16 = {
    Text = "Certo, voglio sapere."
  },
  AvgDialog_18722_Content_17 = {
    Text = "Voglio solo sapere di più su di te, Lady Daffodil."
  },
  AvgDialog_18722_Content_18 = {
    Text = "Oh? Qualcuno sembra farsi sempre più avido."
  },
  AvgDialog_18722_Content_19 = {
    Text = "Ecco un suggerimento: <Yellow:È qualcosa che hai già visto.>"
  },
  AvgDialog_18722_Content_2 = {
    Text = "I rinforzi e il Comitato sono in arrivo. Resta qui e metti in sicurezza l'area."
  },
  AvgDialog_18722_Content_20 = {
    Text = "L'hai già visto...?"
  },
  AvgDialog_18722_Content_21 = {
    Text = "Rifletti intensamente, e la storia degli ultimi due giorni e le persone che hai incontrato ti scorrono davanti agli occhi come una lanterna magica."
  },
  AvgDialog_18722_Content_22 = {Text = "..."},
  AvgDialog_18722_Content_23 = {Text = "!!"},
  AvgDialog_18722_Content_24 = {
    Text = "Potrebbe essere quella di Norwich Street, che ti somiglia in tutto e per tutto...?"
  },
  AvgDialog_18722_Content_25 = {
    Text = "Molto astuto."
  },
  AvgDialog_18722_Content_26 = {
    Text = "Ma perché... Non capisco."
  },
  AvgDialog_18722_Content_27 = {
    Text = "Daffodil contemplava l'alba nebbiosa all'orizzonte lontano, il vento gelido le sollevava i lunghi capelli."
  },
  AvgDialog_18722_Content_28 = {
    Text = "Quello è un \"esemplare\". Apparteneva al mio precedente padrone."
  },
  AvgDialog_18722_Content_29 = {
    Text = "Ecco un segreto: il mio volto attuale è modellato su di esso."
  },
  AvgDialog_18722_Content_3 = {
    Text = "Non preoccuparti, questa volta farò il bravo e aspetterò qui. Non andrò in giro dappertutto."
  },
  AvgDialog_18722_Content_30 = {Text = "?!"},
  AvgDialog_18722_Content_31 = {
    Text = "<LightGray:Quindi questo non è il tuo vero aspetto...>"
  },
  AvgDialog_18722_Content_32 = {
    Text = "Mi hai dato un grande aiuto questa volta.\nNon riesco ancora a perdonarmi per aver usato come esca un Custode così inesperto."
  },
  AvgDialog_18722_Content_33 = {
    Text = "...Non importa. Purché l'indagine venga completata, non mi dispiace essere usato una volta."
  },
  AvgDialog_18722_Content_34 = {
    Text = "Davvero? Ma mi sento davvero in colpa. Quindi..."
  },
  AvgDialog_18722_Content_35 = {
    Text = "Come scusa, posso esaudirti un desiderio."
  },
  AvgDialog_18722_Content_36 = {Text = "È gratis~"},
  AvgDialog_18722_Content_37 = {Text = "!!"},
  AvgDialog_18722_Content_38 = {
    Text = "La persona che hai davanti è una mercante astuta e spietata, in possesso di informazioni, conoscenze proibite e preziosi oggetti da collezione che molti bramano."
  },
  AvgDialog_18722_Content_39 = {
    Text = "E ora, può esaudire una tua richiesta gratuitamente."
  },
  AvgDialog_18722_Content_4 = {
    Text = "Non mi sarei mai aspettato che l'indagine venisse completata così in fretta.\nOttimo lavoro, %player%."
  },
  AvgDialog_18722_Content_40 = {
    Text = "<LightGray:No... La Sig.na Doll si arrabbierebbe se scoprisse che faccio affari con altri là fuori.>"
  },
  AvgDialog_18722_Content_41 = {
    Text = "Un fiume di possibilità ti attraversa la mente: Reliquie d'oro perdute, le torte più deliziose, un'enorme quantità di denaro..."
  },
  AvgDialog_18722_Content_42 = {
    Text = "Pensieri contrastanti si intrecciano e si scontrano, ma alla fine si ritirano come la marea — decidi di seguire il tuo istinto."
  },
  AvgDialog_18722_Content_43 = {
    Text = "Hai deciso la tua richiesta? Non essere troppo avido."
  },
  AvgDialog_18722_Content_44 = {
    Text = "Ho deciso. Le mie richieste sono semplici."
  },
  AvgDialog_18722_Content_45 = {
    Text = "Fammi vedere la tua vera forma."
  },
  AvgDialog_18722_Content_46 = {Text = "..."},
  AvgDialog_18722_Content_47 = {
    Text = "È davvero così semplice? Pensaci bene. Posso offrirti molte cose, ognuna delle quali vale più di questa."
  },
  AvgDialog_18722_Content_48 = {
    Text = "Il valore lo stabilisce il mio giudizio. Questa è la mia unica richiesta."
  },
  AvgDialog_18722_Content_49 = {
    Text = "Come ci si aspetta da un Custode {Male=Mr.,Female=Miss}, mi sorprendi sempre. Quindi..."
  },
  AvgDialog_18722_Content_5 = {
    Text = "Ehm, è tutto merito di Lady Daffodil."
  },
  AvgDialog_18722_Content_50 = {
    Text = "Daffodil si avvicinò a te. Il vento le sollevava i lunghi capelli, facendoli ondeggiare come onde grigie."
  },
  AvgDialog_18722_Content_51 = {
    Text = "Sei così vicino che puoi quasi scorgere il tuo riflesso nei suoi occhi."
  },
  AvgDialog_18722_Content_52 = {
    Text = "Ricorda di mantenere il Segreto, %player%."
  },
  AvgDialog_18722_Content_53 = {
    Text = "Non aveva ancora finito di parlare che i suoi lineamenti iniziarono a sfumare e dissolversi, come colori a olio nell'acqua..."
  },
  AvgDialog_18722_Content_54 = {
    Text = "Finalmente, finalmente sei riuscito a vedere chiaramente il suo volto."
  },
  AvgDialog_18722_Content_55 = {
    Text = "Era un volto @2, che ti ricordava molte cose."
  },
  AvgDialog_18722_Content_56 = {
    Text = "Come la nebbia umida dopo la pioggia, il narciso che sboccia silenzioso nell'angolo, o il piccolo animale raggomitolato nell'oscurità..."
  },
  AvgDialog_18722_Content_57 = {
    Text = "Prima che potessi osservarlo meglio, quel volto svanì come una goccia d'acqua che si fonde nell'acqua."
  },
  AvgDialog_18722_Content_58 = {
    Text = "Quindi... questa è la tua vera forma."
  },
  AvgDialog_18722_Content_59 = {
    Text = "Com'è? È brutta, vero?"
  },
  AvgDialog_18722_Content_6 = {
    Text = "È solo un piccolo sforzo, e ho anche recuperato ciò che era andato perduto."
  },
  AvgDialog_18722_Content_60 = {
    Text = "Scuoti la testa."
  },
  AvgDialog_18722_Content_61 = {
    Text = "È stato inaspettato... ma ti si addice."
  },
  AvgDialog_18722_Content_62 = {
    Text = "La luce del mattino spazzò via l'umidità della pioggia, avvolgendola in un alone soffuso."
  },
  AvgDialog_18722_Content_63 = {
    Text = "A dire il vero... poco fa ho avuto un po' di paura, e poi mi sono sorpresa della mia stessa paura."
  },
  AvgDialog_18722_Content_64 = {
    Text = "Dieci anni, cinquant'anni? Non ricordo nemmeno l'ultima volta che ho provato terrore."
  },
  AvgDialog_18722_Content_65 = {
    Text = "Paura...? Temevi che potessi trovarti poco attraente?"
  },
  AvgDialog_18722_Content_66 = {
    Text = "Daffodil non rispose, limitandosi ad arruffarti dolcemente i capelli."
  },
  AvgDialog_18722_Content_67 = {
    Text = "%player%, ora sei l'unica persona al mondo ad aver visto la vera \"me\"."
  },
  AvgDialog_18722_Content_68 = {
    Text = "Heh, ora ho un piccolo vantaggio su di te."
  },
  AvgDialog_18722_Content_69 = {
    Text = "Prima di perdere la memoria, devo sbrigarmi a disegnare il tuo volto sulla carta."
  },
  AvgDialog_18722_Content_7 = {
    Text = "Dal punto di vista del mercante, questo è stato un \"affare\" perfetto."
  },
  AvgDialog_18722_Content_70 = {
    Text = "Daffodil sorrise, i suoi occhi si curvarono in un arco bellissimo."
  },
  AvgDialog_18722_Content_71 = {
    Text = "Che bambina sciocca."
  },
  AvgDialog_18722_Content_72 = {
    Text = "Bene, i tuoi amici del Comitato e della polizia dovrebbero essere in arrivo ormai, giusto?"
  },
  AvgDialog_18722_Content_73 = {
    Text = "<Shake:Quindi lo sapevi fin dall'inizio...>"
  },
  AvgDialog_18722_Content_74 = {
    Text = "Non ho la pazienza per quegli interrogatori tediosi.\nLa prossima volta, troviamo un posto tranquillo e prendiamoci un caffè."
  },
  AvgDialog_18722_Content_75 = {
    Text = "Addio, mio {Male=Mr.,Female=Miss} Custode."
  },
  AvgDialog_18722_Content_76 = {
    Text = "Eh? Oh... Addio, Lady Daffodil."
  },
  AvgDialog_18722_Content_77 = {
    Text = "Daffodil ti ha salutato con la mano e se n'è andata."
  },
  AvgDialog_18722_Content_78 = {
    Text = "Osservando la sua figura rilassata in lontananza, senti il tuo umore alleggerirsi."
  },
  AvgDialog_18722_Content_79 = {
    Text = "La foschia persistente si è completamente dissipata e il cielo si è finalmente rasserenato. La luce del sole filtra attraverso le nuvole pigre, scaldandoti tutto il corpo."
  },
  AvgDialog_18722_Content_8 = {
    Text = "Hai perso qualcosa..."
  },
  AvgDialog_18722_Content_80 = {
    Text = "Per qualche ragione, hai un presentimento—"
  },
  AvgDialog_18722_Content_81 = {
    Text = "Continuerete a incontrarvi attraverso epoche e dimensioni diverse."
  },
  AvgDialog_18722_Content_9 = {
    Text = "Il Cacciatore di Teschi mi ha sottratto un <Yellow:teschio prezioso>, quindi sono qui per svolgere una piccola indagine. È così semplice."
  },
  AvgDialog_18723_Content_1 = {
    Text = "Coff, coff, i Risvegli del Reame Ultra sono davvero difficili da inseguire..."
  },
  AvgDialog_18723_Content_10 = {
    Text = "Risposta...?"
  },
  AvgDialog_18723_Content_11 = {
    Text = "È scappato mentre eri temporaneamente assente, e io e la Sig.ra Horla stavamo chiacchierando."
  },
  AvgDialog_18723_Content_12 = {
    Text = "Ma non c'è bisogno di preoccuparsi. Se mi segui, lo vedrai presto."
  },
  AvgDialog_18723_Content_13 = {
    Text = "Si trova nella <Blue:landa desolata a nord di Rainy Town>?"
  },
  AvgDialog_18723_Content_14 = {
    Text = "Oh? Sembra che il nostro piccolo detective sia piuttosto acuto. Come sei riuscito a capirlo?"
  },
  AvgDialog_18723_Content_15 = {
    Text = "Quel tizio manifesta il D-fenomeno, che è probabilmente collegato alla peste scoppiata nel nord tre anni fa."
  },
  AvgDialog_18723_Content_16 = {
    Text = "Ora che è gravemente ferito e sotto attacco sia da parte nostra che della polizia, non gli restano molti posti dove andare."
  },
  AvgDialog_18723_Content_17 = {
    Text = "Non importa se si nasconde nella landa desolata, è una pista che vale la pena indagare."
  },
  AvgDialog_18723_Content_18 = {
    Text = "Niente male, piuttosto astuto. Ma sai quanto è vasta quella landa desolata?"
  },
  AvgDialog_18723_Content_19 = {
    Text = [[
Circa 50 miglia quadrate.
Non vorrai mica sprecare le tue preziose vacanze in esplorazioni geologiche e lavori di censimento, vero?]]
  },
  AvgDialog_18723_Content_2 = {
    Text = "Barcolli fino a un bivio."
  },
  AvgDialog_18723_Content_20 = {
    Text = [[
E io conosco il suo esatto nascondiglio.
Vuoi venire con me?]]
  },
  AvgDialog_18723_Content_21 = {
    Text = "Non accettare. È estremamente pericolosa; non lasciarti ingannare da lei."
  },
  AvgDialog_18723_Content_22 = {
    Text = "Conterò fino a tre. Tre, due..."
  },
  AvgDialog_18723_Content_23 = {Text = "..."},
  AvgDialog_18723_Content_24 = {
    Text = "Verrò con voi."
  },
  AvgDialog_18723_Content_25 = {Text = "..."},
  AvgDialog_18723_Content_26 = {
    Text = "Hmm, che bambina obbediente."
  },
  AvgDialog_18723_Content_27 = {
    Text = "Lady Daffodil, posso accompagnarvi?"
  },
  AvgDialog_18723_Content_28 = {
    Text = "Una fragile bambina emerge dalle ombre degli alberi alle tue spalle, i suoi occhi colmi di preoccupazione."
  },
  AvgDialog_18723_Content_29 = {
    Text = "So che sei preoccupato per %player%."
  },
  AvgDialog_18723_Content_3 = {
    Text = "Nessun altro cacciatore qui, solo Daffodil e la sua ombra allungata."
  },
  AvgDialog_18723_Content_30 = {
    Text = "Ma mi dispiace, mia piccola rosa. Questa volta posso portare con me solo una persona."
  },
  AvgDialog_18723_Content_31 = {
    Text = "Il vento gelido ulula per le strade notturne. Horla si avvolge stretta nella lettera antivento e riscaldante, il suo piccolo viso pallido sollevato mentre guarda Daffodil con un'espressione seria."
  },
  AvgDialog_18723_Content_32 = {
    Text = "Perché? Forse non sono brava a combattere, ma una mano in più è sempre utile, no?"
  },
  AvgDialog_18723_Content_33 = {
    Text = "Posso portare solo una persona. Scusa, Piccola Rosa, ho le mie ragioni."
  },
  AvgDialog_18723_Content_34 = {Text = "..."},
  AvgDialog_18723_Content_35 = {
    Text = "Lady Daffodil, riporterete sicuramente {Male=Mr.,Female=Miss} %player% a casa sana e salva, vero?"
  },
  AvgDialog_18723_Content_36 = {
    Text = "Daffodil osservava le falene che battevano le ali sotto la luce del lampione e soffiò pigramente un anello di fumo dalla bocca."
  },
  AvgDialog_18723_Content_37 = {
    Text = "Naturalmente, stai tranquillo."
  },
  AvgDialog_18723_Content_4 = {
    Text = "Per qualche ragione, senti che lei è rimasta lì in piedi per molto, molto tempo."
  },
  AvgDialog_18723_Content_5 = {
    Text = "Sembra che fin dai tempi antichi sia rimasta qui da sola, a scrutare in silenzio la distanza senza proferire parola."
  },
  AvgDialog_18723_Content_6 = {Text = "Sei qui."},
  AvgDialog_18723_Content_7 = {
    Text = "Daffodil si voltò, la sua espressione ancora tenue."
  },
  AvgDialog_18723_Content_8 = {
    Text = "Dov'è il Cacciatore di Teschi? Ne hai perso le tracce?"
  },
  AvgDialog_18723_Content_9 = {
    Text = "Sì, abbiamo perso le tracce. Ma... credo di conoscere già la risposta."
  },
  AvgDialog_18724_Content_1 = {Text = "Da lontano"},
  AvgDialog_18724_Content_10 = {
    Text = "In base alle condizioni dei corpi e alle testimonianze, i due sono morti a mezz'ora di distanza l'uno dall'altro."
  },
  AvgDialog_18724_Content_11 = {
    Text = "Il luogo della morte è qui vicino?"
  },
  AvgDialog_18724_Content_12 = {
    Text = "Ramona scosse la testa."
  },
  AvgDialog_18724_Content_13 = {
    Text = "Anche in auto ci vuole più di un'ora, per non parlare del fatto che pochissimi in città possiedono un'automobile."
  },
  AvgDialog_18724_Content_14 = {
    Text = "... Forse il Vecchio Freeman aveva ragione."
  },
  AvgDialog_18724_Content_15 = {
    Text = "I Cacciatori di Teschi sono un'organizzazione. Ma qual è il loro vero scopo?"
  },
  AvgDialog_18724_Content_16 = {
    Text = "Teste@2... Altre teste..."
  },
  AvgDialog_18724_Content_17 = {
    Text = "Un improvviso vento freddo soffiò da dietro."
  },
  AvgDialog_18724_Content_18 = {
    Text = "Ti volti, solo per vedere il cadavere senza testa lanciarsi verso di te a una velocità incredibile."
  },
  AvgDialog_18724_Content_19 = {Text = "?!"},
  AvgDialog_18724_Content_2 = {
    Text = "00:15, Capanna di Horla"
  },
  AvgDialog_18724_Content_20 = {
    Text = "Dammi la testa@3... dammi@1 altre teste @4..."
  },
  AvgDialog_18724_Content_21 = {
    Text = "Sposti rapidamente il corpo di lato. Il cadavere sfonda il vetro davanti a te, svanendo nella vastità della notte."
  },
  AvgDialog_18724_Content_22 = {
    Text = "Una velocità così incredibile... Potrebbe essere un Risveglio dal Reame Ultra?"
  },
  AvgDialog_18724_Content_23 = {
    Text = "Proprio mentre sei perplesso, un intenso profumo di narciso ti avvolge completamente."
  },
  AvgDialog_18724_Content_24 = {
    Text = "Una gonna viola ti sfiora rapida, poi svanisce davanti ai tuoi occhi."
  },
  AvgDialog_18724_Content_25 = {
    Text = "Lady Daffodil...?"
  },
  AvgDialog_18724_Content_26 = {
    Text = "Presto, inseguila! Non lasciarti sfuggire l'indizio importante."
  },
  AvgDialog_18724_Content_3 = {
    Text = "Hai trovato un angolo tranquillo e hai spiegato a Ramona ciò che era appena accaduto."
  },
  AvgDialog_18724_Content_4 = {
    Text = "Certo, salta pure la parte in cui hanno quasi sgozzato te."
  },
  AvgDialog_18724_Content_5 = {Text = "..."},
  AvgDialog_18724_Content_6 = {
    Text = "Ti ho chiamato <Red:35> volte da questo pomeriggio, ma non c'è stata alcuna risposta."
  },
  AvgDialog_18724_Content_7 = {
    Text = "Scusa, è successo così all'improvviso..."
  },
  AvgDialog_18724_Content_8 = {
    Text = "...Non accadrà di nuovo."
  },
  AvgDialog_18724_Content_9 = {
    Text = "L'identità delle vittime rinvenute durante il giorno è stata confermata.\nIl carpentiere Damon Mendes, 35 anni; il giovane disoccupato Thomas Quillen, 23 anni."
  },
  AvgDialog_18725_Content_1 = {
    Text = "Una cornice capovolta attira la vostra attenzione."
  },
  AvgDialog_18725_Content_10 = {
    Text = "<RedItalic:Bevve dieci bottiglie di alcol la domenica, perse il lavoro e perse la moglie.>"
  },
  AvgDialog_18725_Content_11 = {
    Text = "Qualcuno canticchia sommessamente una filastrocca senza ritmo."
  },
  AvgDialog_18725_Content_12 = {
    Text = "La melodia arida sembra una mano umida e invisibile che accarezza dolcemente i peli già rizzati sulla nuca."
  },
  AvgDialog_18725_Content_13 = {
    Text = "<RedItalic:Il Vecchio Freeman pianse e bevve di nuovo undici bottiglie di liquore il lunedì...>"
  },
  AvgDialog_18725_Content_14 = {
    Text = "Accompagnata dallo scricchiolio delle assi di legno, Harriet si fermò in silenzio davanti al corridoio fiocamente illuminato."
  },
  AvgDialog_18725_Content_15 = {
    Text = "Esatto, il Vecchio Freeman è mio marito."
  },
  AvgDialog_18725_Content_16 = {Text = "Cosa?!"},
  AvgDialog_18725_Content_17 = {
    Text = "A quel tempo, tutti pensavano che fossi morta, compreso mio marito."
  },
  AvgDialog_18725_Content_18 = {
    Text = "Più tardi, dopo un tempo imprecisato, tornai in vita... ma qualcosa in me era cambiato."
  },
  AvgDialog_18725_Content_19 = {
    Text = "Resti in silenzio, avendo già intuito il resto della storia."
  },
  AvgDialog_18725_Content_2 = {
    Text = "Dalla cucina giungeva il gorgoglio dell'acqua in ebollizione; la signora Harriet era ancora indaffarata là dentro."
  },
  AvgDialog_18725_Content_20 = {
    Text = "Gli esseri umani infettati dalla Dissoluzione subiscono danni mentali irreversibili, che portano a varie complicazioni."
  },
  AvgDialog_18725_Content_21 = {
    Text = "Non sorprende che Lady Harriet sia finita così."
  },
  AvgDialog_18725_Content_22 = {
    Text = "Cominciai a bramare teste, molte teste... Così mi intrufolai in un cimitero."
  },
  AvgDialog_18725_Content_23 = {
    Text = [[
Mi chinai sul corpo del vecchio Pinoco, usando un falcetto arrugginito per cercare di tagliargli la testa.
Ma a quel tempo ero troppo debole, e non riuscivo nemmeno a tenere fermo il falcetto...]]
  },
  AvgDialog_18725_Content_24 = {
    Text = "E indovina chi ho incontrato?"
  },
  AvgDialog_18725_Content_25 = {Text = "..."},
  AvgDialog_18725_Content_26 = {
    Text = "Ho incontrato mio marito."
  },
  AvgDialog_18725_Content_27 = {
    Text = "È diventato più grasso, più vecchio, e si è ridotto a un ubriacone."
  },
  AvgDialog_18725_Content_28 = {
    Text = "Heh... Questo mondo trova sempre nuovi modi per tormentare noi povere anime."
  },
  AvgDialog_18725_Content_29 = {
    Text = "Stringeva il suo bicchiere e mi guardava come un cane randagio."
  },
  AvgDialog_18725_Content_3 = {
    Text = "Capovolgi delicatamente la cornice."
  },
  AvgDialog_18725_Content_30 = {
    Text = "Ha riso per tutto il tempo. Sì, lo so che dovevo apparire tanto pietosa quanto ridicola allora."
  },
  AvgDialog_18725_Content_31 = {
    Text = "Ma lui... non mi riconosce affatto."
  },
  AvgDialog_18725_Content_32 = {
    Text = "...Dunque, sei il Cacciatore di Teschi di cui parlava."
  },
  AvgDialog_18725_Content_33 = {
    Text = "Harriet inclinò meccanicamente la testa verso destra, producendo uno scricchiolio dal collo."
  },
  AvgDialog_18725_Content_34 = {
    Text = "Già. Anche se so che non mi ricorda, continuo a sbirciarlo di nascosto."
  },
  AvgDialog_18725_Content_35 = {
    Text = "Quindi hai origliato la nostra conversazione, hai scoperto che stavo conducendo un'indagine sugli omicidi, e hai deciso di seguirmi e tendermi un'imboscata?"
  },
  AvgDialog_18725_Content_36 = {Text = "..."},
  AvgDialog_18725_Content_37 = {
    Text = "Sei davvero diverso da loro. Ho detto così tanto, eppure rimani impassibile."
  },
  AvgDialog_18725_Content_38 = {
    Text = "Lasci sfuggire un lieve sospiro, abbassando lo sguardo sulla porta chiusa a chiave accanto a te."
  },
  AvgDialog_18725_Content_39 = {
    Text = "Sangue rosso scuro trasuda come denso sciroppo dalla fessura della porta, strisciando lentamente verso i tuoi piedi."
  },
  AvgDialog_18725_Content_4 = {
    Text = "È una vecchia foto di famiglia. I volti della moglie e del bambino sono ormai sfocati, e rimane solo il marito, in piedi all'estrema sinistra."
  },
  AvgDialog_18725_Content_40 = {
    Text = "Lo sapevi..."
  },
  AvgDialog_18725_Content_41 = {
    Text = "Il pavimento, il soffitto, gli armadi... tutto puzza di sangue e del fetore della morte."
  },
  AvgDialog_18725_Content_42 = {
    Text = "Dal momento in cui sono entrata, sapevo già tutto."
  },
  AvgDialog_18725_Content_5 = {
    Text = "Se ne sta eretto e rilassato davanti alla sua casa appena costruita, rivolgendo un sorriso radioso all'obiettivo."
  },
  AvgDialog_18725_Content_6 = {
    Text = "Fissi la sua fronte e i suoi occhi, in qualche modo familiari, e un pensiero assurdo ti attraversa improvvisamente la mente."
  },
  AvgDialog_18725_Content_7 = {
    Text = "Vecchio Freeman...?!"
  },
  AvgDialog_18725_Content_8 = {
    Text = "Potrebbe essere il marito della signora Harriet?"
  },
  AvgDialog_18725_Content_9 = {
    Text = "<RedItalic:Vecchio Freeman, Vecchio Freeman, il povero e folle ubriacone Vecchio Freeman...>"
  },
  AvgDialog_18726_Content_1 = {
    Text = "Ti addentri nel vicolo, il cappotto ormai fradicio di pioggia."
  },
  AvgDialog_18726_Content_10 = {
    Text = "Toc, toc, toc."
  },
  AvgDialog_18726_Content_11 = {
    Text = "Il suono di passi cadenzati riecheggiò dalla strada oltre il vicolo, e una figura indistinta apparve sotto il lampione."
  },
  AvgDialog_18726_Content_12 = {
    Text = "Qui è pericoloso, andate via immediatamente—"
  },
  AvgDialog_18726_Content_13 = {
    Text = "Quella è una donna."
  },
  AvgDialog_18726_Content_14 = {
    Text = "Se ne sta sola sotto il lampione, reggendo una testa turgida che si incastra perfettamente con il collo del corpo decapitato alle tue spalle."
  },
  AvgDialog_18726_Content_15 = {
    Text = "Il sangue gocciola dal collo, scorrendo lentamente lungo le crepe tra le piastrelle del pavimento."
  },
  AvgDialog_18726_Content_16 = {
    Text = [[
Resta dove sei.
Chi sei?]]
  },
  AvgDialog_18726_Content_17 = {
    Text = "I fiochi lampioni tremolano, emettendo un ronzio elettrico irritante."
  },
  AvgDialog_18726_Content_18 = {
    Text = "La donna alza il capo, e finalmente riesci a distinguerne i lineamenti."
  },
  AvgDialog_18726_Content_19 = {Text = "..."},
  AvgDialog_18726_Content_2 = {
    Text = "Sangue rosso scuro cola dall'<Shadow>, estendendo tentacoli minacciosi, invitandoti in silenzio."
  },
  AvgDialog_18726_Content_20 = {
    Text = "<Gray:L-Lady Daffodil?>"
  },
  AvgDialog_18726_Content_3 = {
    Text = "Qui regna la quiete; puoi udire soltanto il suono della pioggia, dei passi e del respiro."
  },
  AvgDialog_18726_Content_4 = {
    Text = "Risuonano come un rullare caotico di tamburi, sempre più rapido e forte, finché non raggiungi il fondo del vicolo."
  },
  AvgDialog_18726_Content_5 = {
    Text = "Il cadavere gonfio giace floscio tra i rifiuti, gettato via con noncuranza."
  },
  AvgDialog_18726_Content_6 = {
    Text = "L'incisione sul collo è sfumata, con sangue rosso scuro che sgorga copioso dai vasi."
  },
  AvgDialog_18726_Content_7 = {
    Text = "Non hai bisogno di toccarlo per sapere che il sangue è ancora caldo."
  },
  AvgDialog_18726_Content_8 = {
    Text = "Testa mancante, ferite frastagliate sul collo..."
  },
  AvgDialog_18726_Content_9 = {
    Text = "È il \"Cacciatore di Teschi\"."
  },
  AvgDialog_18727_Content_1 = {
    Text = "Serendipità"
  },
  AvgDialog_18727_Content_10 = {
    Text = "Se non ha mentito né giudicato male, allora sì."
  },
  AvgDialog_18727_Content_11 = {
    Text = "L'<Blue:Avanguardia> è arrivata a Rainy Town una settimana fa e ha rilevato segni di un Argento attivo sul luogo della morte."
  },
  AvgDialog_18727_Content_12 = {
    Text = "Inclusi gli ultimi tre, questo è l'ottavo <Blue:Evento del Cacciatore di Teschi> a Rainy Town."
  },
  AvgDialog_18727_Content_13 = {
    Text = "Cacciatore di Teschi? È così che la gente del posto chiama l'assassino?"
  },
  AvgDialog_18727_Content_14 = {
    Text = "Molto evocativo, non è vero? Grazie a lui, nessuno osa più uscire dopo il tramonto da queste parti."
  },
  AvgDialog_18727_Content_15 = {
    Text = "Fissi la strada desolata davanti a te."
  },
  AvgDialog_18727_Content_16 = {
    Text = "Entro le 20, tutte le porte e le finestre dei dintorni sono sbarrate ermeticamente. Il Terrore trasuda dalle finestre buie come la pece, avvolgendo silenziosamente ogni cosa intorno."
  },
  AvgDialog_18727_Content_17 = {
    Text = "A parte qualche latrato di cane prolungato, qui regna un silenzio inquietante."
  },
  AvgDialog_18727_Content_18 = {
    Text = "Pic, pic, pic..."
  },
  AvgDialog_18727_Content_19 = {
    Text = "Hmm, sta piovendo?"
  },
  AvgDialog_18727_Content_2 = {
    Text = [[
Belen Stock, 46 anni, deceduta in casa, in cucina, il 12 settembre.
<Red:Testa mancante>, corpo intatto ad eccezione di un taglio frastagliato sul collo.]]
  },
  AvgDialog_18727_Content_20 = {
    Text = "Una pioggia fine e fresca sgocciola dal cielo notturno, stendendo un velo bianco davanti a te."
  },
  AvgDialog_18727_Content_21 = {
    Text = "Sento la pioggia dalla tua parte. Hai un ombrello?"
  },
  AvgDialog_18727_Content_22 = {
    Text = "<Shake:Oh no. Sei sempre tu a portare l'ombrello, quindi...>"
  },
  AvgDialog_18727_Content_23 = {
    Text = "A quanto pare devo ancora abituarmi alla vita senza di te."
  },
  AvgDialog_18727_Content_24 = {Text = "..."},
  AvgDialog_18727_Content_25 = {
    Text = "Mi dispiace, questa volta non ho potuto venire con te."
  },
  AvgDialog_18727_Content_26 = {
    Text = "La Signorina Doll insiste perché io resti a condurre con lei una Ricerca sulla Dissoluzione apparentemente \"importante\"..."
  },
  AvgDialog_18727_Content_27 = {
    Text = "<Small:Ramona, potresti passarmi il campione di Argento sul terzo ripiano della quinta fila, codice SI-3007...>"
  },
  AvgDialog_18727_Content_28 = {Text = "..."},
  AvgDialog_18727_Content_29 = {
    Text = "Abbi cura di te, %player%. Per quanto riguarda l'alloggio... <Blue:la Signorina Horla> si occuperà di tutto."
  },
  AvgDialog_18727_Content_3 = {
    Text = [[
Dwight Williams, 56 anni, deceduto all'incrocio di Deman Street il 13 settembre.
<Red:Testa mancante>, corpo intatto con un taglio frastagliato sul collo.]]
  },
  AvgDialog_18727_Content_30 = {
    Text = "La signorina Horla? Non c'è da stupirsi che la si veda raramente a scuola; vive fuori?"
  },
  AvgDialog_18727_Content_31 = {
    Text = "Mythag non è un campo unidirezionale."
  },
  AvgDialog_18727_Content_32 = {
    Text = "I Risvegliati a basso rischio possono andare in vacanza, pernottare fuori o far visita alla famiglia.\nLa condizione è semplice: fare richiesta in anticipo ed evitare di causare problemi."
  },
  AvgDialog_18727_Content_33 = {
    Text = "Ehm... Quindi anche la signorina Horla parteciperà all'indagine?"
  },
  AvgDialog_18727_Content_34 = {
    Text = "Non tutti i Risvegliati sono interessati alle missioni sul campo. Se lo ritieni necessario, chiedi a lei la sua opinione."
  },
  AvgDialog_18727_Content_35 = {
    Text = "La situazione attuale è stabile e gestibile, non c'è bisogno di—"
  },
  AvgDialog_18727_Content_36 = {Text = "Whoosh—"},
  AvgDialog_18727_Content_37 = {
    Text = "All'improvviso, dal vicolo più avanti giunse il suono di carne che si spiaccicava, seguito da passi caotici, rompendo bruscamente il silenzio della notte."
  },
  AvgDialog_18727_Content_38 = {Text = "?!"},
  AvgDialog_18727_Content_39 = {
    Text = "A quest'ora, questo rumore... Potrebbe essere...?"
  },
  AvgDialog_18727_Content_4 = {
    Text = "Deceduto N. 012, identità ed età sconosciute, morto presso il Lago Knerl a nord nelle prime ore del mattino del 16 settembre..."
  },
  AvgDialog_18727_Content_40 = {
    Text = "Seguiamo e diamo un'occhiata. Ricorda di restare in contatto."
  },
  AvgDialog_18727_Content_41 = {
    Text = "Che la Chiave d'Argento Illumini il Cammino."
  },
  AvgDialog_18727_Content_5 = {
    Text = [[
20:00, Norwich Street
Rainy Town]]
  },
  AvgDialog_18727_Content_6 = {
    Text = "Testa mancante, cicatrici frastagliate..."
  },
  AvgDialog_18727_Content_7 = {
    Text = "E tutti sono morti mentre erano soli fuori casa o tra le mura domestiche."
  },
  AvgDialog_18727_Content_8 = {
    Text = "Inoltre, una settimana dopo la morte di Dwight Williams, sua moglie ha dichiarato di averlo visto correre in fretta nelle terre selvagge."
  },
  AvgDialog_18727_Content_9 = {
    Text = "...Resuscitato?"
  },
  AvgDialog_18764_Content_1 = {Text = "No, non..."},
  AvgDialog_18764_Content_10 = {
    Text = "Coff coff coff... T-tu, come puoi barare in quel modo!"
  },
  AvgDialog_18764_Content_11 = {
    Text = "<SmallShake:Era solo un gioco di indovinelli, non c'è bisogno di agitarsi tanto...>"
  },
  AvgDialog_18764_Content_12 = {
    Text = "Dov'è l'uscita del labirinto?"
  },
  AvgDialog_18764_Content_13 = {
    Text = "Hehe, vuoi saperlo? Allora inginocchiati, porgi le tue scuse a questa grande sovrana, e poi..."
  },
  AvgDialog_18764_Content_14 = {
    Text = "Alzi lentamente la mano."
  },
  AvgDialog_18764_Content_15 = {
    Text = "<Shake:A-aspetta! Parlo...>"
  },
  AvgDialog_18764_Content_16 = {
    Text = "La Fanciulla aprì la bocca, poi abbassò la testa sconsolata."
  },
  AvgDialog_18764_Content_17 = {
    Text = "In realtà... non lo so nemmeno io. Sono rinchiusa qui da quasi mille anni..."
  },
  AvgDialog_18764_Content_18 = {
    Text = "Non faccio altro che dormire, fissare il vuoto e gestire la mia prole. Sto impazzendo dalla noia!"
  },
  AvgDialog_18764_Content_19 = {Text = "..."},
  AvgDialog_18764_Content_20 = {
    Text = "Non sei la padrona del labirinto? Come puoi non sapere dov'è l'uscita?"
  },
  AvgDialog_18764_Content_21 = {
    Text = "<SmallShake:Dovresti chiederlo a chi mi ha gettato qui dentro. Come potrei sapere cosa avevano in mente...>"
  },
  AvgDialog_18764_Content_22 = {
    Text = "Com'è possibile..."
  },
  AvgDialog_18764_Content_23 = {
    Text = "Allora, e se, dico per ipotesi—"
  },
  AvgDialog_18764_Content_24 = {
    Text = "E se la persona che è entrata nel labirinto non fosse fisicamente presente, ma esistesse sotto forma di coscienza."
  },
  AvgDialog_18764_Content_25 = {
    Text = "Sarebbe possibile per lei, ehm, diciamo... aggirare le regole di questo labirinto?"
  },
  AvgDialog_18764_Content_26 = {
    Text = "Agrippa ti ha rivolto uno sguardo perplesso."
  },
  AvgDialog_18764_Content_27 = {
    Text = "Certo che no."
  },
  AvgDialog_18764_Content_28 = {
    Text = "Vuoi provare a indovinare perché hai visto così tante persone e luoghi familiari nel labirinto?"
  },
  AvgDialog_18764_Content_29 = {
    Text = "Fantasma? No, ricordi..."
  },
  AvgDialog_18764_Content_3 = {
    Text = "Hai finalmente eliminato l'ultima \"Charlotte\"."
  },
  AvgDialog_18764_Content_30 = {
    Text = "Agrippa scosse la testa."
  },
  AvgDialog_18764_Content_31 = {
    Text = "Nessuno dei due. Per essere precisi, è la <Yellow:coscienza>."
  },
  AvgDialog_18764_Content_32 = {
    Text = "<Yellow:Ciò che è rimasto intrappolato nel labirinto è sempre stata solo la tua coscienza, dopotutto.>"
  },
  AvgDialog_18764_Content_4 = {
    Text = "La Chiave Sepolcrale svanì gradualmente e sei tornato/a al punto di partenza."
  },
  AvgDialog_18764_Content_5 = {
    Text = "Vieni fuori. So dove sei."
  },
  AvgDialog_18764_Content_6 = {
    Text = "Un ronzio simile a uno Scuotimento si levò dalle profondità del sottosuolo e il terreno si spaccò lentamente."
  },
  AvgDialog_18764_Content_7 = {Text = "BOOM!!"},
  AvgDialog_18764_Content_8 = {
    Text = "Pfft... Ptuh ptuh ptuh!!"
  },
  AvgDialog_18764_Content_9 = {
    Text = "Agrippa emerse dal sottosuolo, coperta di polvere."
  },
  AvgDialog_18765_Content_1 = {
    Text = "Mente-Alveare"
  },
  AvgDialog_18765_Content_10 = {
    Text = "Hai fatto i compiti di questa settimana? L'esame di \"Introduzione alla Dissoluzione\" è alle porte. Come va il ripasso?"
  },
  AvgDialog_18765_Content_11 = {
    Text = "Ramona?! No, io non… Aspetta, non è…"
  },
  AvgDialog_18765_Content_12 = {
    Text = "%player%, oggi sei arrivato/a in classe con 5 minuti di ritardo. Il ritardo complessivo accumulato questo mese è di 30 minuti e 15 secondi."
  },
  AvgDialog_18765_Content_13 = {
    Text = "Vieni nel mio ufficio dopo la lezione."
  },
  AvgDialog_18765_Content_14 = {Text = "—!!"},
  AvgDialog_18765_Content_15 = {
    Text = "Pfft. <Big:Ahahahahahaha!>"
  },
  AvgDialog_18765_Content_16 = {
    Text = "Spaventato/a, eh? Dovresti davvero guardarti allo specchio e vedere che faccia hai adesso."
  },
  AvgDialog_18765_Content_17 = {Text = "..."},
  AvgDialog_18765_Content_18 = {
    Text = "Questi... trucchi di trasformismo, dove li hai imparati tutti?"
  },
  AvgDialog_18765_Content_19 = {
    Text = "Una volta hai visto il fascicolo di Agrippa negli archivi dei Risvegliatori. Non c'erano registrazioni relative al \"trasformismo\" in Superficie."
  },
  AvgDialog_18765_Content_20 = {
    Text = "Imparare? Io sono il padrone di questo labirinto. Nel mio dominio, posso fare ciò... che... mi pare."
  },
  AvgDialog_18765_Content_21 = {
    Text = "Figurati solo una... posso mettere in scena uno spettacolo con dieci, cento di loro."
  },
  AvgDialog_18765_Content_22 = {
    Text = "Dopo aver parlato, Agrippa svanì ancora una volta."
  },
  AvgDialog_18765_Content_23 = {
    Text = "In poco tempo, una, due... ancora più Charlotte apparvero davanti a te."
  },
  AvgDialog_18765_Content_24 = {
    Text = "Indovina quale sono davvero io, hehe..."
  },
  AvgDialog_18765_Content_25 = {
    Text = "Buuu buuu... Quale Charlotte è davvero Agrippa?"
  },
  AvgDialog_18765_Content_26 = {
    Text = "Una possibilità, solo una possibilità..."
  },
  AvgDialog_18765_Content_27 = {
    Text = "Innumerevoli voci stridule si intrecciarono in una melodia caotica e dissonante, fluttuando nella tua mente."
  },
  AvgDialog_18765_Content_28 = {
    Text = "Via... andate via...!!"
  },
  AvgDialog_18765_Content_29 = {
    Text = "Hai fatto un respiro profondo e finalmente hai ritrovato la calma."
  },
  AvgDialog_18765_Content_3 = {
    Text = "Charlotte, come hai fatto a ridurrti così?"
  },
  AvgDialog_18765_Content_30 = {
    Text = "Mi dispiace. Siete tutte uguali. Non riesco a distinguervi."
  },
  AvgDialog_18765_Content_31 = {
    Text = "Eh? Ti arrendi già? Che noia."
  },
  AvgDialog_18765_Content_33 = {
    Text = "Un istante dopo, una \"Charlotte\" fu scaraventata a terra.\nTi sei massaggiato/a le tempie e hai detto con calma—"
  },
  AvgDialog_18765_Content_34 = {
    Text = "Ma va bene così."
  },
  AvgDialog_18765_Content_35 = {
    Text = "Posso stendere ognuno di voi, e poi chiedere uno per uno."
  },
  AvgDialog_18765_Content_4 = {
    Text = "\"Charlotte\" torse la testa, e un ronzio agghiacciante emanò dal profondo della sua gola."
  },
  AvgDialog_18765_Content_5 = {
    Text = "<Shake:Hee hee, non te l'aspettavi, vero? La tua amichetta è diventata una delle mie creature già da tempo!>"
  },
  AvgDialog_18765_Content_6 = {
    Text = "Quella voce… Sei tu, Agrippa?"
  },
  AvgDialog_18765_Content_7 = {
    Text = [[
Che commovente, ricordi ancora la mia voce.
Aspetta, lascia che ti mostri qualcosa di impressionante!]]
  },
  AvgDialog_18765_Content_8 = {
    Text = "Un soffocato sghignazzare proveniva dalla gola di \"Charlotte\", poi il suo collo si torse bruscamente e in un istante il suo aspetto cambiò completamente."
  },
  AvgDialog_18765_Content_9 = {
    Text = "%player%, stai mangiando spuntini di nascosto di nuovo!"
  },
  AvgDialog_18766_Content_1 = {Text = "Il Portale"},
  AvgDialog_18766_Content_10 = {
    Text = "Sei pronto/a, @1? Spingiamolo insieme."
  },
  AvgDialog_18766_Content_11 = {
    Text = "Scricchiolio—"
  },
  AvgDialog_18766_Content_12 = {Text = "<Big:!!!>"},
  AvgDialog_18766_Content_13 = {
    Text = "Questo è... che razza di posto...?"
  },
  AvgDialog_18766_Content_14 = {
    Text = "È il posto dove resterai docilmente per il resto della tua vita."
  },
  AvgDialog_18766_Content_15 = {
    Text = "La Fanciulla sedeva sulla piattaforma cava con un sorriso malizioso, il mento appoggiato su entrambe le mani, la gamba destra accavallata che dondolava pigramente."
  },
  AvgDialog_18766_Content_16 = {
    Text = "Benvenuto nel mio labirinto."
  },
  AvgDialog_18766_Content_17 = {
    Text = "Stavi dormendo così profondamente. Stavo per imboccarti qualche insettino per tirarti su."
  },
  AvgDialog_18766_Content_18 = {
    Text = "<LightGray:Agrippa...?>"
  },
  AvgDialog_18766_Content_19 = {
    Text = "Abbassi lo sguardo sugli abiti sconosciuti che indossi e realizzi di essere entrato ancora una volta in Morpheus."
  },
  AvgDialog_18766_Content_2 = {
    Text = "Si dice che nel labirinto di \"Lui\", non è solo il senso dell'orientamento a perdersi."
  },
  AvgDialog_18766_Content_20 = {
    Text = "La differenza è che questa volta hai quasi perso tutti i ricordi dell'ospite originale.\nChi è Lei? Da dove viene Lei?"
  },
  AvgDialog_18766_Content_21 = {
    Text = "Non sai nulla."
  },
  AvgDialog_18766_Content_22 = {
    Text = "<Shake:Cosa sta succedendo... L'ospite originale, no, chi sono io...>"
  },
  AvgDialog_18766_Content_23 = {
    Text = "Bene, smetti di pensare. Non ricorderai nulla."
  },
  AvgDialog_18766_Content_24 = {
    Text = "Anche dopo 1 giorno, 100 giorni, 1000 giorni, la tua mente sarà ancora pulita come quella di un neonato."
  },
  AvgDialog_18766_Content_25 = {
    Text = "Ora ti darò due scelte."
  },
  AvgDialog_18766_Content_26 = {
    Text = "<Red:Uno: Firma un contratto con me, e poi diventa la mia progenie.>"
  },
  AvgDialog_18766_Content_27 = {
    Text = "<Red:Due: Morire di fame nel labirinto, e poi diventare una mia progenie.>"
  },
  AvgDialog_18766_Content_28 = {
    Text = "Agrippa espose abilmente la situazione e ti presentò le scelte, come se questa routine fosse già stata ripetuta innumerevoli volte."
  },
  AvgDialog_18766_Content_29 = {
    Text = "Progenie? Che cos'è?"
  },
  AvgDialog_18766_Content_3 = {
    Text = "Il tuo nome, la tua patria, la persona amata… tutto ciò che è importante e non importante verrà lasciato indietro."
  },
  AvgDialog_18766_Content_30 = {
    Text = "Tranquillo. Niente veleno, niente dolore, niente danni. Effetti collaterali? Non ti accorgerai nemmeno che esistono."
  },
  AvgDialog_18766_Content_31 = {
    Text = "Quindi, rispetto a quegli dèi malvagi che ti chiedono continuamente di Sacrificare la tua vita o di uccidere i tuoi cari, non diresti che sono molto più gentile?"
  },
  AvgDialog_18766_Content_32 = {Text = "..."},
  AvgDialog_18766_Content_33 = {
    Text = "Ora ti do tre secondi per fare la tua scelta. Firmare il patto, o morire di fame?"
  },
  AvgDialog_18766_Content_34 = {Text = "Tre—"},
  AvgDialog_18766_Content_35 = {Text = "Due—"},
  AvgDialog_18766_Content_36 = {
    Text = "Va bene, ho deciso."
  },
  AvgDialog_18766_Content_37 = {Text = "Eh...?"},
  AvgDialog_18766_Content_38 = {
    Text = "Deciso. Non sei... niente male. Allora dimmi la tua scelta."
  },
  AvgDialog_18766_Content_39 = {
    Text = "Annuisci, spostando silenziosamente il piede destro indietro di una breve distanza."
  },
  AvgDialog_18766_Content_4 = {
    Text = "Da quel momento in poi, hai una sola identità: <Red:la Sua progenie>."
  },
  AvgDialog_18766_Content_40 = {
    Text = "La mia scelta è—"
  },
  AvgDialog_18766_Content_41 = {
    Text = "Ti giri senza esitazione e scatti via a tutta velocità."
  },
  AvgDialog_18766_Content_42 = {
    Text = "<BigShake:Corri!!>"
  },
  AvgDialog_18766_Content_43 = {
    Text = "Molto, molto tempo dopo..."
  },
  AvgDialog_18766_Content_44 = {
    Text = "Huff... huff..."
  },
  AvgDialog_18766_Content_45 = {
    Text = "Corri lungo il corridoio, finché un Portale non ti blocca il cammino."
  },
  AvgDialog_18766_Content_46 = {
    Text = "Il Museo delle Cere? Di nuovo..."
  },
  AvgDialog_18766_Content_47 = {
    Text = "Se ricordo bene, questa è la ventitreesima volta che lo vedo."
  },
  AvgDialog_18766_Content_48 = {
    Text = "Sì, ci sono innumerevoli Portali qui, che conducono a innumerevoli spazi."
  },
  AvgDialog_18766_Content_49 = {
    Text = "Appaiono davanti a te ancora e ancora, con una frequenza tale da far impazzire anche l'Investigatore più composto."
  },
  AvgDialog_18766_Content_5 = {
    Text = "<Shake:P-progenie?>"
  },
  AvgDialog_18766_Content_50 = {
    Text = "Spingi il Cancello e prosegui lungo il corridoio."
  },
  AvgDialog_18766_Content_51 = {
    Text = "Di nuovo questo corridoio... 15 volte."
  },
  AvgDialog_18766_Content_52 = {
    Text = "Istintivamente tocchi i Gemelli d'argento incastonati nella tua manica."
  },
  AvgDialog_18766_Content_53 = {
    Text = "Un vecchio emblema scolastico del Mythag... Quindi questa volta sono diventata una studentessa degli anni passati?"
  },
  AvgDialog_18766_Content_54 = {
    Text = "Ma come è entrata nel labirinto?"
  },
  AvgDialog_18766_Content_55 = {
    Text = "Mentre rifletti, un altro Cancello blocca il tuo Cammino."
  },
  AvgDialog_18766_Content_56 = {
    Text = "Sei davanti a questo Cancello adesso, @1. Aprilo."
  },
  AvgDialog_18766_Content_57 = {
    Text = "Chi sta parlando?!"
  },
  AvgDialog_18766_Content_58 = {
    Text = "La mia testa... mi fa male. Sono questi i ricordi di quella studentessa più grande?"
  },
  AvgDialog_18766_Content_59 = {
    Text = "Respira profondamente, %player%. Libera la mente..."
  },
  AvgDialog_18766_Content_6 = {
    Text = "Sì. Innumerevoli progenie, come una pallida marea, si riversano nel labirinto da ogni direzione."
  },
  AvgDialog_18766_Content_60 = {
    Text = "Ti sforzi di calmarti, giri la maniglia d'ottone e tiri delicatamente il Cancello per aprirlo."
  },
  AvgDialog_18766_Content_61 = {
    Text = "...Keygrave?"
  },
  AvgDialog_18766_Content_62 = {
    Text = "Attraverso la nebbia vorticosa, noti una figura al tempo stesso familiare e sconosciuta."
  },
  AvgDialog_18766_Content_63 = {
    Text = "Charlotte... <Big:Charlotte!>"
  },
  AvgDialog_18766_Content_64 = {
    Text = "Ricordi la Fanciulla chiamata Charlotte. Era l'amica che aveva portato \"te\" nel labirinto."
  },
  AvgDialog_18766_Content_65 = {
    Text = "<Big:Aspettami, Charlotte!>"
  },
  AvgDialog_18766_Content_66 = {
    Text = "Ti slanci in avanti e afferri Charlotte per il polso."
  },
  AvgDialog_18766_Content_67 = {
    Text = "Nell'istante in cui la tua pelle tocca la sua, innumerevoli frammenti caotici balenano nella tua mente."
  },
  AvgDialog_18766_Content_68 = {
    Text = "Apri il Cancello, @1."
  },
  AvgDialog_18766_Content_69 = {
    Text = "<Shake:No, io— mi sono appena ricordata che non ho finito i compiti, voglio—>"
  },
  AvgDialog_18766_Content_7 = {
    Text = "I passaggi verso il labirinto sono ovunque. Nei muri, nelle fogne, e dove ci troviamo ora..."
  },
  AvgDialog_18766_Content_70 = {
    Text = "<Big:Aaaaah!!>"
  },
  AvgDialog_18766_Content_71 = {
    Text = "<Shake:Charlotte, la tua faccia...>"
  },
  AvgDialog_18766_Content_72 = {
    Text = "Varco… Varco…"
  },
  AvgDialog_18766_Content_73 = {
    Text = "@1Varco@2aprire@4"
  },
  AvgDialog_18766_Content_74 = {
    Text = "<RedBig:Aprite il Varco…>"
  },
  AvgDialog_18766_Content_75 = {
    Text = "Quindi è così. Sei tu quella che ha attirato \"me\" nel labirinto…"
  },
  AvgDialog_18766_Content_76 = {
    Text = "Istintivamente lasciasti andare il polso di Charlotte e indietreggiasti barcollando di qualche passo."
  },
  AvgDialog_18766_Content_77 = {
    Text = "La nebbia si dissipò gradualmente. Charlotte si voltò con fatica e ti guardò con aria addolorata."
  },
  AvgDialog_18766_Content_78 = {
    Text = "…@4Varco@4@1"
  },
  AvgDialog_18766_Content_79 = {
    Text = "—Con quelle sue orbite vuote e cave."
  },
  AvgDialog_18766_Content_8 = {
    Text = "In un cancello nascosto sotto la <Blue:Biblioteca Comunale>."
  },
  AvgDialog_18766_Content_9 = {
    Text = "<Shake:Io... Non posso credere che un posto del genere esista davvero... Tutte quelle leggende erano vere...>"
  },
  AvgDialog_18767_Content_1 = {
    Text = "Fine del Labirinto"
  },
  AvgDialog_18767_Content_10 = {
    Text = "Shh... Chiudi gli occhi, svuota la mente, non pensare a nulla."
  },
  AvgDialog_18767_Content_11 = {
    Text = "Non fare nulla..."
  },
  AvgDialog_18767_Content_12 = {Text = "UUGHH!"},
  AvgDialog_18767_Content_13 = {
    Text = "Mi sta per scoppiare la testa... Meglio non usare questo metodo troppo spesso..."
  },
  AvgDialog_18767_Content_14 = {
    Text = "<Shake:Fuori dai piedi, levatevi tutti di mezzo!>"
  },
  AvgDialog_18767_Content_15 = {
    Text = "Chiunque osi toccare la mia famiglia... ammazzo prima questo porco!!"
  },
  AvgDialog_18767_Content_16 = {
    Text = "Una Lama tremante ti preme contro la gola."
  },
  AvgDialog_18767_Content_17 = {Text = "...?"},
  AvgDialog_18767_Content_18 = {
    Text = "Morpheus riuscito— anche se non proprio l'ingresso che avevi immaginato."
  },
  AvgDialog_18767_Content_19 = {
    Text = "Davanti a te si erge una folla di Schiavi a torso nudo. La loro consueta sottomissione è ormai un lontano ricordo, i loro occhi brillano di odio."
  },
  AvgDialog_18767_Content_2 = {
    Text = "Vuoi dire che puoi immergerti nella mia coscienza e cambiare il passato?"
  },
  AvgDialog_18767_Content_20 = {
    Text = "Di fronte alla minaccia di Agrippa, ammutoliscono per un istante, poi esplodono in una Detonazione di risate fragorose."
  },
  AvgDialog_18767_Content_21 = {
    Text = "Pfft. Hahahahahaha!"
  },
  AvgDialog_18767_Content_22 = {
    Text = "Beh beh, la nostra Principessina ha del fegato!"
  },
  AvgDialog_18767_Content_23 = {
    Text = "Heh. Non mi credete, ve..."
  },
  AvgDialog_18767_Content_24 = {
    Text = "La Lama fende l'aria rapida, e un dolore bruciante ti attraversa il collo."
  },
  AvgDialog_18767_Content_25 = {
    Text = "Ngh! Fai sul serio!!"
  },
  AvgDialog_18767_Content_26 = {
    Text = "<Big:Zitto!> Tu e loro— siete tutti complici! Sei tu che hai rubato la Chiave della mia famiglia e i contratti di servitù!"
  },
  AvgDialog_18767_Content_27 = {Text = "...?"},
  AvgDialog_18767_Content_28 = {
    Text = "E voi tutti! Se qualcuno ride ancora, farò un altro taglio sul collo di {Male=his,Female=her}!"
  },
  AvgDialog_18767_Content_29 = {
    Text = "Abbassa il coltello, Agrippa... <Big:Scappa!>"
  },
  AvgDialog_18767_Content_3 = {
    Text = "Se avessi davvero un potere simile, come avrei potuto intrappolarti?"
  },
  AvgDialog_18767_Content_31 = {
    Text = "La frusta si abbatté con ferocia sulla donna. Prima ancora di poter emettere un suono, crollò a terra priva di sensi."
  },
  AvgDialog_18767_Content_32 = {
    Text = "<Big:Madre!!>"
  },
  AvgDialog_18767_Content_33 = {
    Text = "Smettila con quella messinscena ridicola. Non siamo più i tuoi Schiavi."
  },
  AvgDialog_18767_Content_34 = {
    Text = "Quando ci tiranneggiavi nei campi di addestramento, perché non hai pensato a questo giorno?"
  },
  AvgDialog_18767_Content_35 = {
    Text = "Apri gli occhi e guarda bene, \"Principessina.\" Guarda come ti umilieremo..."
  },
  AvgDialog_18767_Content_36 = {
    Text = "<Shake:Codardi, siete tutti codardi! Come osate...>"
  },
  AvgDialog_18767_Content_37 = {
    Text = "<Shake:Chi vi ha maltrattato ero io, non loro... No, sono stata troppo sciocca. Non avrei dovuto trattarvi così...>"
  },
  AvgDialog_18767_Content_38 = {
    Text = "<Shake:Prendetevela con me, fate quello che volete! Basta che lasciate andare mia Madre...>"
  },
  AvgDialog_18767_Content_39 = {
    Text = "La fanciulla era già in preda al panico, al punto che le sue parole uscivano incoerenti. Il pugnale nella sua mano tremava violentemente, quasi cadendole a terra."
  },
  AvgDialog_18767_Content_4 = {
    Text = "Ehm... Per essere precisi, si tratta di influenzare, non di cambiare."
  },
  AvgDialog_18767_Content_40 = {
    Text = "Lasciasti sfuggire un lieve sospiro e le togliesti delicatamente il pugnale dalla mano."
  },
  AvgDialog_18767_Content_41 = {
    Text = "Non avere paura, Agrippa. Ti aiuterò io."
  },
  AvgDialog_18767_Content_42 = {
    Text = "Aiutarmi? Ma tu non sei..."
  },
  AvgDialog_18767_Content_43 = {
    Text = "Ti mettesti davanti ad Agrippa, guardando gli schiavi dritto negli occhi."
  },
  AvgDialog_18767_Content_44 = {
    Text = "Bene, il gioco è finito.\nAvete già ottenuto ciò che volevate. Ora potete andarvene."
  },
  AvgDialog_18767_Content_45 = {
    Text = "Oh, qualcuno si atteggia a capo adesso, e ci fa pure la predica."
  },
  AvgDialog_18767_Content_46 = {
    Text = "Cres, non dovresti essere dalla nostra parte?"
  },
  AvgDialog_18767_Content_47 = {
    Text = "Scuoti la testa."
  },
  AvgDialog_18767_Content_48 = {
    Text = "Ho sempre rispettato la vostra causa di ribellione, ma nessuno ha il diritto di massacrare degli innocenti."
  },
  AvgDialog_18767_Content_49 = {
    Text = "\"Innocenti\"...?"
  },
  AvgDialog_18767_Content_5 = {
    Text = "Non sottovalutarti. Il tuo labirinto è molto più complesso di quanto mi aspettassi..."
  },
  AvgDialog_18767_Content_50 = {
    Text = "Heh, questo qui ci ha completamente traditi. Perché sprecare altre parole con lui."
  },
  AvgDialog_18767_Content_51 = {
    Text = "<Big:Uccidetelo!>"
  },
  AvgDialog_18767_Content_6 = {
    Text = "Agrippa ti osserva con sospetto."
  },
  AvgDialog_18767_Content_7 = {
    Text = "Lascia perdere, non è che ci siano altre soluzioni.\nCosa devo fare?"
  },
  AvgDialog_18767_Content_8 = {
    Text = "Cerchi di ricordare il tuo Stato ogni volta che sei entrato in Morpheus, e prendi delicatamente la mano di Agrippa."
  },
  AvgDialog_18767_Content_9 = {
    Text = "Ehi, tu... non è che stai cercando di approfittarti di me, vero?"
  },
  AvgDialog_18768_Content_1 = {
    Text = "Cough... Cough..."
  },
  AvgDialog_18768_Content_10 = {
    Text = "Il suono cupo dei corni riecheggia debolmente in lontananza: non sei ancora riuscito a sfuggire alla Caccia dell'esercito ribelle."
  },
  AvgDialog_18768_Content_11 = {
    Text = "Tu e Agrippa correte mano nella mano sotto il cielo nero come la pece."
  },
  AvgDialog_18768_Content_12 = {
    Text = "La sua famiglia non è lontana da voi. Tutti, spinti dalla paura e dalla speranza allo stesso modo, corrono verso un orizzonte senza fine in vista."
  },
  AvgDialog_18768_Content_13 = {
    Text = "Chi sei? Perché mi hai salvata?"
  },
  AvgDialog_18768_Content_14 = {
    Text = "Hmm… per essere precisi, l'ho fatto per salvare me stesso."
  },
  AvgDialog_18768_Content_15 = {
    Text = "Oh… a prescindere dal motivo, sei… una brava persona."
  },
  AvgDialog_18768_Content_16 = {
    Text = "Una volta che saremo tratti in salvo, ti darò tutto il denaro e i gioielli che ho messo da parte in segreto nel corso degli anni."
  },
  AvgDialog_18768_Content_17 = {
    Text = "Non puoi fare a meno di ridere."
  },
  AvgDialog_18768_Content_18 = {
    Text = "Non ho bisogno dei tuoi soldi. Ma… se vuoi ripagarmi, ho una richiesta."
  },
  AvgDialog_18768_Content_19 = {
    Text = "Dimmi: la realizzerò, qualunque cosa sia."
  },
  AvgDialog_18768_Content_2 = {
    Text = "Per rispetto dei vecchi tempi, i fratelli si sono trattenuti poco fa."
  },
  AvgDialog_18768_Content_20 = {
    Text = "Una stella cadente attraversa il cielo notturno: è il momento perfetto per esprimere un desiderio."
  },
  AvgDialog_18768_Content_21 = {
    Text = "La mia richiesta è semplice. Continua a sorridere e ricorda come ti senti in questo momento."
  },
  AvgDialog_18768_Content_22 = {
    Text = "Come mi sento in questo momento? Hmm... Felice, sollevata, preoccupata? Quale intendi!"
  },
  AvgDialog_18768_Content_23 = {
    Text = "Segui il tuo cuore. Sono curioso di scoprire a quale Agrippa mi condurranno."
  },
  AvgDialog_18768_Content_24 = {Text = "?"},
  AvgDialog_18768_Content_25 = {
    Text = "<SmallShake:Questo tizio sarà anche una brava persona, ma il modo in cui parla è davvero strano...>"
  },
  AvgDialog_18768_Content_26 = {
    Text = "Il suono del corno finalmente svanì, e la tranquillità della notte tornò ancora una volta."
  },
  AvgDialog_18768_Content_27 = {
    Text = "Finalmente... è finita."
  },
  AvgDialog_18768_Content_28 = {
    Text = "La fanciulla corse in cima alla duna di sabbia con pochi passi rapidi, strinse i pugni e gridò verso il punto in cui il corno era svanito."
  },
  AvgDialog_18768_Content_29 = {
    Text = "Scommetto che non ve l'aspettavate, branco di @2, sono io quella sopravvissuta fino alla fine!"
  },
  AvgDialog_18768_Content_3 = {
    Text = "Dato che insisti nell'aiutarli, non biasimarci se non mostreremo pietà—"
  },
  AvgDialog_18768_Content_30 = {
    Text = "Hahahahahaha, @2!"
  },
  AvgDialog_18768_Content_31 = {
    Text = "<Shake:Agrippa! Sii una signora, una signora...!>"
  },
  AvgDialog_18768_Content_32 = {
    Text = "Non ti sento!!!"
  },
  AvgDialog_18768_Content_33 = {
    Text = "Al diavolo il fare la signora e tutte quelle regole di etichetta, finalmente sono libera!!"
  },
  AvgDialog_18768_Content_34 = {
    Text = "Con quella dichiarazione risonante, la fanciulla spalancò le braccia, come se stringesse tra le mani il magnifico cielo stellato sopra di lei."
  },
  AvgDialog_18768_Content_35 = {
    Text = "<Big:Sono libera—!!>"
  },
  AvgDialog_18768_Content_36 = {Text = "CRASH—!!"},
  AvgDialog_18768_Content_37 = {Text = "...Eh?"},
  AvgDialog_18768_Content_38 = {
    Text = "Il cielo svanì, e il labirinto svanì con esso."
  },
  AvgDialog_18768_Content_39 = {
    Text = "Il canyon cambriano irruppe nel tuo campo visivo."
  },
  AvgDialog_18768_Content_4 = {Text = "CRASH!"},
  AvgDialog_18768_Content_40 = {
    Text = "L'acqua profonda del lago, simile a uno specchio, scorreva in quieta immobilità, mentre il vento ne increspava la superficie, generando anelli di ondulazioni luminose."
  },
  AvgDialog_18768_Content_41 = {
    Text = "Agrippa sedeva stordita sull'erba, fissando con sguardo vuoto tutto ciò che aveva davanti."
  },
  AvgDialog_18768_Content_42 = {
    Text = "%player%, siamo... fuori?"
  },
  AvgDialog_18768_Content_43 = {
    Text = "Bentornata nel mondo reale, Agrippa."
  },
  AvgDialog_18768_Content_44 = {Text = "...Oh."},
  AvgDialog_18768_Content_45 = {
    Text = "Quindi questa è la valle fluviale. È cento volte più bella di quanto si dica... no, mille volte più bella."
  },
  AvgDialog_18768_Content_46 = {
    Text = "Una tenue luce mattutina filtra attraverso la foschia e si posa su di te."
  },
  AvgDialog_18768_Content_47 = {
    Text = "Agrippa chiude gli occhi, assaporando avidamente i profumi a lungo dimenticati."
  },
  AvgDialog_18768_Content_48 = {
    Text = "Riesco a sentire così tanti odori. Terra, erba, fresie e luce del sole..."
  },
  AvgDialog_18768_Content_49 = {
    Text = "Anche la luce del sole ha un odore?"
  },
  AvgDialog_18768_Content_5 = {
    Text = "Approfittando del caos, spingi giù il pilastro che blocca il passaggio, e l'intero edificio inizia a vacillare sull'orlo del crollo."
  },
  AvgDialog_18768_Content_50 = {
    Text = "Mm-hm. Quel tipo di odore che ti fa venire sonno."
  },
  AvgDialog_18768_Content_51 = {
    Text = "Grazie, %player%."
  },
  AvgDialog_18768_Content_52 = {
    Text = "Si stiracchia pigramente e comincia a canticchiare sottovoce un'antica ballata romana."
  },
  AvgDialog_18768_Content_53 = {
    Text = "La leggera melodia si diffonde nell'aria a spirale, portando il buonumore della sua cantante in ogni angolo della valle fluviale."
  },
  AvgDialog_18768_Content_54 = {
    Text = "Dopo più di mille anni, ha finalmente rivisto la luce del sole."
  },
  AvgDialog_18768_Content_55 = {
    Text = "E ha finalmente visto la valle fluviale per la primissima volta."
  },
  AvgDialog_18768_Content_6 = {
    Text = "Ora è il momento—seguitemi, presto!"
  },
  AvgDialog_18768_Content_7 = {
    Text = "Afferri la mano di Agrippa e fuggi in fretta insieme alla sua famiglia."
  },
  AvgDialog_18768_Content_8 = {
    Text = "Il cortile un tempo glorioso crolla come una bestia silenziosa che si accascia al suolo."
  },
  AvgDialog_18768_Content_9 = {
    Text = "16@1 anni prima del Dopo Diluvio, periferia di Capua"
  },
  AvgDialog_18769_Content_1 = {
    Text = "Barriera della Memoria"
  },
  AvgDialog_18769_Content_10 = {
    Text = "Cosa hai@1 appena detto—"
  },
  AvgDialog_18769_Content_11 = {
    Text = "Lascia perdere, non metterti con quel tipo. È un pazzo…"
  },
  AvgDialog_18769_Content_12 = {
    Text = "Gli Schiavi si spintonarono mentre uscivano, e la cella buia tornò finalmente silenziosa."
  },
  AvgDialog_18769_Content_13 = {
    Text = "La Ragazza emerse dalle ombre nell'angolo della cella, con il capo chino."
  },
  AvgDialog_18769_Content_14 = {
    Text = "Perché non sei andato via con loro? Stanotte sarebbe stata un'occasione perfetta per riconquistare la tua libertà."
  },
  AvgDialog_18769_Content_15 = {
    Text = "Mi piace stare qui. Perché dovrei andarmene?"
  },
  AvgDialog_18769_Content_16 = {
    Text = "Ti piace…? Haha, notevole. Ti piace essere insultato, o ti piace essere frustato dalla mia frusta?"
  },
  AvgDialog_18769_Content_17 = {
    Text = "Il Gladiatore sbadigliò e stirò le membra comodamente."
  },
  AvgDialog_18769_Content_18 = {
    Text = "Mi piace il Sangue, e mi piace ancora di più uccidere. Per me, uccidere è libertà."
  },
  AvgDialog_18769_Content_19 = {
    Text = "Quanto al titolo di Schiavo, non mi importa quanti me ne diano. Perché dovrei andarmene?"
  },
  AvgDialog_18769_Content_2 = {
    Text = "16 anni prima del Dopo Diluvio@1, Capua"
  },
  AvgDialog_18769_Content_20 = {Text = "..."},
  AvgDialog_18769_Content_21 = {
    Text = "Heh… Adesso comincio davvero a vederti sotto una nuova luce. Sei un autentico folle."
  },
  AvgDialog_18769_Content_22 = {
    Text = "Agrippa alzò lo sguardo verso l'uscita della prigione, la sua espressione perfettamente calma."
  },
  AvgDialog_18769_Content_23 = {
    Text = "Onde cremisi di fuoco si levarono verso il cielo. Risate, pianti, urla… ogni sorta di suono si mescolava insieme, componendo una sinfonia dall'inferno."
  },
  AvgDialog_18769_Content_24 = {
    Text = "Presto mi troveranno,@1 mi prenderanno, poi mi taglieranno la testa, proprio come hanno fatto ai miei genitori."
  },
  AvgDialog_18769_Content_25 = {
    Text = "Non voglio queste creature infime vicino a me. Ma tu…"
  },
  AvgDialog_18769_Content_26 = {
    Text = "Tu sei diverso da loro.\nSo che c'è stato del \"cattivo sangue\" tra noi, ma questa volta, sicuramente non rifiuterai la mia richiesta."
  },
  AvgDialog_18769_Content_27 = {
    Text = "Oh? Sentiamo."
  },
  AvgDialog_18769_Content_28 = {Text = "..."},
  AvgDialog_18769_Content_29 = {Text = "Uccidimi."},
  AvgDialog_18769_Content_3 = {
    Text = "Dannazione, quella donna è sparita."
  },
  AvgDialog_18769_Content_30 = {
    Text = "<RedBig:Uccidimi…>"
  },
  AvgDialog_18769_Content_31 = {
    Text = "Agrippa…?"
  },
  AvgDialog_18769_Content_32 = {
    Text = "<RedBig:Uccidimi uccidimi uccidimi uccidimi uccidimi uccidimi uccidimi uccidimi…>"
  },
  AvgDialog_18769_Content_33 = {Text = "Agrippa!"},
  AvgDialog_18769_Content_34 = {Text = "!!"},
  AvgDialog_18769_Content_35 = {
    Text = "<Shake:Ugh...>"
  },
  AvgDialog_18769_Content_36 = {
    Text = "Ho fatto un Sogno molto, molto lungo…"
  },
  AvgDialog_18769_Content_37 = {
    Text = "Ascolta, sembra che prima abbiamo trascurato alcune domande."
  },
  AvgDialog_18769_Content_38 = {
    Text = "Assurdo! Io sono la Signora dei Labirinti—tutto è sotto il mio controllo—"
  },
  AvgDialog_18769_Content_39 = {
    Text = "Primo, perché la tua progenie può entrare e uscire liberamente dal labirinto, mentre tu e io non possiamo?"
  },
  AvgDialog_18769_Content_4 = {
    Text = "Heh heh. Quindi adesso sa nascondersi? Quando la troveremo, le taglieremo prima le gambe…"
  },
  AvgDialog_18769_Content_40 = {
    Text = "Non condividete una coscienza collettiva?"
  },
  AvgDialog_18769_Content_41 = {
    Text = "Cosa ne sai tu? In quanto Signora dei Labirinti, devo mantenere un'aura di mistero in ogni momento."
  },
  AvgDialog_18769_Content_42 = {
    Text = "Inoltre, finché lo desidero, sono tutti costretti a strisciare indietro obbedienti. Come sarebbe \"entrare e uscire liberamente\"?"
  },
  AvgDialog_18769_Content_43 = {
    Text = "Annuisci, poi tiri fuori il taccuino che hai in mano."
  },
  AvgDialog_18769_Content_44 = {
    Text = "C'è un'altra domanda."
  },
  AvgDialog_18769_Content_45 = {
    Text = "Ho tenuto un registro di tutti i luoghi che ho incontrato nel labirinto: la scuola, il Museo delle Cere, le strade di Londinium..."
  },
  AvgDialog_18769_Content_46 = {
    Text = "Ma nessuno dei luoghi che hai vissuto era presente. Nemmeno uno."
  },
  AvgDialog_18769_Content_47 = {
    Text = "Perché? Non sei intrappolata anche tu qui dentro?"
  },
  AvgDialog_18769_Content_48 = {
    Text = "Quante domande! Perché questa grande sovrana non vuole ricordare, perché mai dovrei pensare a cose spiacevoli."
  },
  AvgDialog_18769_Content_49 = {
    Text = "Sì, <Yellow:tu non vuoi ricordare>."
  },
  AvgDialog_18769_Content_5 = {
    Text = "Ehi, Uvhash, hai visto Agrippa?"
  },
  AvgDialog_18769_Content_50 = {
    Text = "È possibile che..."
  },
  AvgDialog_18769_Content_51 = {
    Text = "È proprio perché tu—la Signora dei Labirinti—rifiuti la condivisione della coscienza che questo labirinto, formato dalla coscienza di coloro che vi sono intrappolati, rimarrà per sempre incompleto."
  },
  AvgDialog_18769_Content_52 = {
    Text = "Quindi non potremo mai trovare la via d'uscita."
  },
  AvgDialog_18769_Content_53 = {Text = "..."},
  AvgDialog_18769_Content_54 = {
    Text = "Le domande che stai ponendo—ci ho pensato anch'io, a suo tempo. Dopotutto, questo è il mio labirinto."
  },
  AvgDialog_18769_Content_55 = {
    Text = "Ma nel momento in cui penso al passato, mi fa impazzire completamente..."
  },
  AvgDialog_18769_Content_56 = {
    Text = "Agrippa si strinse la testa tra le mani, le parole le sgorgavano rapide dalle labbra come mormorii in un sogno."
  },
  AvgDialog_18769_Content_57 = {
    Text = "Quei vili parassiti... come hanno osato farmi questo..."
  },
  AvgDialog_18769_Content_58 = {
    Text = "Nient'altro che schiavi, a malapena umani. Meritavano di essere calpestati sotto i nostri piedi per l'eternità."
  },
  AvgDialog_18769_Content_59 = {
    Text = "Ribellione? Che fantasia."
  },
  AvgDialog_18769_Content_6 = {
    Text = "Il Gladiatore nell'ombra aprì lentamente gli occhi."
  },
  AvgDialog_18769_Content_60 = {
    Text = "Ma non si sono limitati a farlo—hanno appeso le teste dei miei genitori sulle mura della città, mi hanno afferrata per i capelli e mi hanno costretta a guardare da vicino, attentamente, senza poter perdere un singolo dettaglio."
  },
  AvgDialog_18769_Content_61 = {
    Text = "E poi la mia sorellina, Julia. Quando l'ho trovata, il suo intero corpo@3, ed era ancora così piccola..."
  },
  AvgDialog_18769_Content_62 = {
    Text = "Che ridicolo... Pensi che abbia pianto?"
  },
  AvgDialog_18769_Content_63 = {
    Text = "No, mai. Piuttosto morire che versare una sola lacrima davanti a loro."
  },
  AvgDialog_18769_Content_64 = {
    Text = "Siamo discendenti del Lupo Grigio. Moriamo con dignità, come veri lupi. Quei bastardi non lo capiranno mai in tutta la loro vita."
  },
  AvgDialog_18769_Content_65 = {
    Text = "Hahahaha..."
  },
  AvgDialog_18769_Content_66 = {
    Text = "Agrippa si strinse lo stomaco, ridendo così forte che le lacrime le rigavano il volto."
  },
  AvgDialog_18769_Content_67 = {
    Text = "Devono essere rimasti così delusi quando hanno visto il mio cadavere... Hahaha..."
  },
  AvgDialog_18769_Content_68 = {
    Text = "Agrippa...? Agrippa!"
  },
  AvgDialog_18769_Content_69 = {
    Text = "Afferri saldamente le spalle di Agrippa, cercando di riportarla indietro dall'Incubo del passato."
  },
  AvgDialog_18769_Content_7 = {
    Text = "…Levatevi di torno."
  },
  AvgDialog_18769_Content_70 = {
    Text = "Basta. È tutto nel passato ormai."
  },
  AvgDialog_18769_Content_71 = {Text = "..."},
  AvgDialog_18769_Content_72 = {
    Text = "Mi dispiace, Agrippa. Non lo sapevo prima... Lascia che quelle cose spiacevoli restino nel passato."
  },
  AvgDialog_18769_Content_73 = {
    Text = "Sei la Signora dei Labirinti, dopotutto. Niente può ferirti davvero."
  },
  AvgDialog_18769_Content_74 = {Text = "...Mm."},
  AvgDialog_18769_Content_75 = {
    Text = "Agrippa cade in un raro silenzio. Sembra che non sia ancora emersa dalle ombre del passato."
  },
  AvgDialog_18769_Content_76 = {
    Text = "<LightGray:Se solo potessi davvero cambiare il passato... Così potrei aiutarla e trovare una via d'uscita da questa situazione.>"
  },
  AvgDialog_18769_Content_77 = {
    Text = "<LightGray:No, non arrenderti ancora. Pensa a un'altra soluzione...>"
  },
  AvgDialog_18769_Content_78 = {
    Text = "Cerchi disperatamente tra i tuoi ricordi frammentati qualsiasi informazione che possa essere utile."
  },
  AvgDialog_18769_Content_79 = {
    Text = "Morpheus non può cambiare il passato, ma può influenzare il futuro. Ecco perché durante Morpheus, il Custode deve imparare a esercitare il Contrattacco."
  },
  AvgDialog_18769_Content_8 = {
    Text = "Heh heh, tutti i fratelli combattono per la grande causa, e solo tu sei disposto a restare qui a fare il cane."
  },
  AvgDialog_18769_Content_80 = {
    Text = "Influenzare il futuro?"
  },
  AvgDialog_18769_Content_81 = {
    Text = "Per dirla semplicemente, la memoria di una persona è come un lago tranquillo."
  },
  AvgDialog_18769_Content_82 = {
    Text = "Morpheus è come lanciare un sasso al suo interno: le increspature che crea svaniscono in fretta."
  },
  AvgDialog_18769_Content_83 = {
    Text = "Ma il sasso resta."
  },
  AvgDialog_18769_Content_84 = {
    Text = "Esatto. Anche se la persona sottoposta a Morpheus non ricorda nulla al risveglio..."
  },
  AvgDialog_18769_Content_85 = {
    Text = "Quel sasso affonderà per sempre nel suo subconscio, influenzando il suo presente."
  },
  AvgDialog_18769_Content_86 = {Text = "!!!"},
  AvgDialog_18769_Content_87 = {
    Text = "Agrippa, so come uscire."
  },
  AvgDialog_18769_Content_9 = {
    Text = "Ho detto, levatevi di torno. Non capite?"
  },
  AvgDialog_18770_Content_1 = {
    Text = "Il Suo Regno"
  },
  AvgDialog_18770_Content_10 = {
    Text = "È inutile, del tutto inutile! Quando erano intrappolati nel labirinto, c'erano anche persone brillanti come matematici, sai!"
  },
  AvgDialog_18770_Content_11 = {
    Text = "Se nemmeno loro sono riusciti a risolvere questo enigma, non vale la pena provarci."
  },
  AvgDialog_18770_Content_12 = {
    Text = "Se vuoi la mia opinione, visto che nessuna delle due può uccidere l'altra, tanto vale andare d'accordo."
  },
  AvgDialog_18770_Content_13 = {
    Text = "Chiacchieriamo! O giochiamo a carte. Che giochi di carte conosci?"
  },
  AvgDialog_18770_Content_14 = {
    Text = "Non lasciarti ingannare dal fatto che sono rimasta bloccata sottoterra: ho sviluppato delle abilità micidiali con le carte. Nessuno può battermi!"
  },
  AvgDialog_18770_Content_15 = {
    Text = "Dovevi ammetterlo, le sue parole ti avevano colpito come un pugno allo stomaco."
  },
  AvgDialog_18770_Content_16 = {
    Text = "Se nessuno è riuscito a decifrare questo labirinto dopo tutti questi anni, cosa ti fa pensare di poterci riuscire tu?"
  },
  AvgDialog_18770_Content_17 = {
    Text = "Di certo non hai una mente brillante come quella di Ramona."
  },
  AvgDialog_18770_Content_18 = {
    Text = "Con questo pensiero, ti lasci cadere a faccia in giù nel soffice cuscino."
  },
  AvgDialog_18770_Content_19 = {
    Text = [[
Non sono molto brava con le carte. Chiacchieriamo e basta.
Come sei finita intrappolata in questo labirinto?]]
  },
  AvgDialog_18770_Content_2 = {
    Text = "39, 40, 41..."
  },
  AvgDialog_18770_Content_20 = {Text = "Ehm..."},
  AvgDialog_18770_Content_21 = {
    Text = "Come se non si fosse aspettata questa domanda, gli occhi composti che ruotavano incessantemente nelle orbite della Fanciulla si bloccarono tutti insieme per un istante."
  },
  AvgDialog_18770_Content_22 = {
    Text = "Sei tu quella che ha detto che dobbiamo andare d'accordo. Bene, allora essere sincere l'una con l'altra è il primo passo."
  },
  AvgDialog_18770_Content_23 = {
    Text = "Va bene, parlo, parlo...! Tanto è solo una storia trita e ritrita."
  },
  AvgDialog_18770_Content_24 = {
    Text = "Ai bei tempi, la mia famiglia era la più ricca di Capua. La fila di schiavi che mi seguiva ogni giorno si estendeva a perdita d'occhio..."
  },
  AvgDialog_18770_Content_25 = {
    Text = "Poi quegli sciocchi hanno davvero iniziato una rivoluzione, blaterando di \"liberazione\" e \"libertà\" — cose che comunque non ho mai capito."
  },
  AvgDialog_18770_Content_26 = {
    Text = "Non volevo morire per mano loro, così ho fatto in modo che un gladiatore mi uccidesse."
  },
  AvgDialog_18770_Content_27 = {
    Text = "Disse Agrippa, allargando le mani verso di te."
  },
  AvgDialog_18770_Content_28 = {
    Text = "...Quando mi sono svegliata, ero già qui."
  },
  AvgDialog_18770_Content_29 = {
    Text = "Ho sentito parlare di questa rivoluzione a lezione di storia. A quanto pare—"
  },
  AvgDialog_18770_Content_3 = {
    Text = "Hai annotato frettolosamente il Registro del <Blue:Dormitorio Studentesco: 41> nel quaderno che portava la tua senpai."
  },
  AvgDialog_18770_Content_30 = {
    Text = "Non voglio sentirne parlare. Questo argomento è così noioso! Prossimo argomento, prossimo argomento."
  },
  AvgDialog_18770_Content_31 = {
    Text = "Un'ora dopo..."
  },
  AvgDialog_18770_Content_32 = {
    Text = "La conversazione insipida proseguì, finché Agrippa non riportò finalmente il discorso su di sé."
  },
  AvgDialog_18770_Content_33 = {
    Text = "Sai, ormai ho un migliaio di discendenti sotto il mio comando..."
  },
  AvgDialog_18770_Content_34 = {
    Text = "Possono andare e venire liberamente attraverso il labirinto, raccogliendo per me storie di ciò che accade all'esterno, e persino riportare povere anime adatte a diventare nuovi discendenti."
  },
  AvgDialog_18770_Content_35 = {
    Text = "Se non fosse per loro, sarei morta di noia da un'eternità."
  },
  AvgDialog_18770_Content_36 = {
    Text = "Mentre ascolti le sue lamentele sconnesse, per qualche ragione, un'immagine affiora nella tua mente—"
  },
  AvgDialog_18770_Content_37 = {
    Text = "Un re anziano appoggiato a un bastone, trincerato in un trono pesante e in Decomposizione."
  },
  AvgDialog_18770_Content_38 = {
    Text = "Il suo dominio si estendeva senza fine, il suo potere era indiscutibile."
  },
  AvgDialog_18770_Content_39 = {
    Text = "Inviò molti emissari, facendosi riportare storie da terre lontane: gemme verdi come occhi di gatto, elefanti smarriti e arcobaleni dopo la pioggia…"
  },
  AvgDialog_18770_Content_4 = {
    Text = "Smettila di perdere tempo con quello e vieni a giocare con me!"
  },
  AvgDialog_18770_Content_40 = {
    Text = "Quando i racconti raggiungevano i momenti più avvincenti, gli emissari agitavano le braccia con entusiasmo. Eppure il re restava sempre in silenzio, come una statua ricoperta di muschio."
  },
  AvgDialog_18770_Content_41 = {
    Text = "Non poteva farci nulla, poiché da tempo non era più in grado di allontanarsi dal suo trono nemmeno di mezzo passo."
  },
  AvgDialog_18770_Content_42 = {
    Text = "Agrippa, hai sentito così tante storie dal mondo esterno… C'è qualche posto dove vorresti andare?"
  },
  AvgDialog_18770_Content_43 = {
    Text = "Un posto dove vorrei andare…"
  },
  AvgDialog_18770_Content_44 = {
    Text = "<Blue:Il canyon cambriano>, direi."
  },
  AvgDialog_18770_Content_45 = {
    Text = "Agrippa rispose quasi senza esitazione."
  },
  AvgDialog_18770_Content_46 = {
    Text = "I miei discendenti mi hanno detto che il centro di questo labirinto sembra trovarsi sotto un canyon chiamato Il canyon cambriano."
  },
  AvgDialog_18770_Content_47 = {
    Text = "Ho sentito dire che è un posto bellissimo, con laghi simili allo Sguardo del Riflesso."
  },
  AvgDialog_18770_Content_48 = {
    Text = "Ogni Primavera, fiori chiamati Boccioli di Fresia sbocciano ovunque…"
  },
  AvgDialog_18770_Content_49 = {
    Text = "Agrippa appoggiò il mento sulla mano, fissando pensierosa la lontananza."
  },
  AvgDialog_18770_Content_5 = {Text = "..."},
  AvgDialog_18770_Content_50 = {
    Text = "C'è un lago bellissimo anche nella mia terra natale, ma non l'ho mai visto."
  },
  AvgDialog_18770_Content_51 = {
    Text = "Perché non vai a vederlo?"
  },
  AvgDialog_18770_Content_52 = {
    Text = "Agrippa ti lanciò uno sguardo altezzoso, sollevando il suo piccolo mento appuntito."
  },
  AvgDialog_18770_Content_53 = {
    Text = "Sono una dama romana di nobile Casata. Una dama non può semplicemente andarsene in giro come le pare."
  },
  AvgDialog_18770_Content_54 = {
    Text = "Quindi puoi comandare molti Schiavi, eppure tu stessa non sei del tutto libera."
  },
  AvgDialog_18770_Content_55 = {
    Text = "La sua realtà messa a nudo dalla tua semplice osservazione, il volto della Ragazza si rabbuiò all'istante, come una melanzana colpita dal gelo."
  },
  AvgDialog_18770_Content_56 = {
    Text = "All'epoca, stavo persino peggio di quegli Schiavi. Figuriamoci adesso…"
  },
  AvgDialog_18770_Content_6 = {
    Text = "Scusa, potresti metterti un'altra faccia prima di parlarmi?"
  },
  AvgDialog_18770_Content_7 = {
    Text = "Tch, che meschinità!"
  },
  AvgDialog_18770_Content_8 = {
    Text = "\"William\" alzò gli occhi al cielo, poi svanì nel nulla con un \"puf\"."
  },
  AvgDialog_18770_Content_9 = {
    Text = "Hai immerso di nuovo la testa nei Registri fittamente stipati davanti a te, cercando un modo per risolvere il labirinto."
  },
  AvgDialog_18779_Content_1 = {
    Text = "Questo... questo è l'embrione?"
  },
  AvgDialog_18779_Content_10 = {
    Text = "Sta prosciugando l'energia da Miryam?!\nSuccederà di nuovo?"
  },
  AvgDialog_18779_Content_11 = {
    Text = "Inutile.\nÈ protetto dalla \"placenta\", e l'energia fornita da Miryam può ancora riparare la placenta almeno altre tre volte."
  },
  AvgDialog_18779_Content_12 = {
    Text = "Per sconfiggerlo completamente, dovete attaccare direttamente il suo vero nucleo."
  },
  AvgDialog_18779_Content_13 = {Text = "Nucleo?"},
  AvgDialog_18779_Content_14 = {
    Text = "Un cuore pallido è incastonato in un bozzolo trasparente, illuminato dalla luce lunare. All'interno dell'immenso bozzolo, l'ombra di \"Lui\" è appena visibile."
  },
  AvgDialog_18779_Content_15 = {
    Text = "È il \"contraffatto\" stesso?"
  },
  AvgDialog_18779_Content_16 = {
    Text = "Sì, ma non proprio."
  },
  AvgDialog_18779_Content_17 = {
    Text = "È... Murphy?"
  },
  AvgDialog_18779_Content_18 = {
    Text = "Sì. Esatto!"
  },
  AvgDialog_18779_Content_19 = {
    Text = "Miryam ha forzato l'avanzamento del rituale, ma \"Lui\" è nato da menzogne e desideri; finché le stelle non raggiungeranno l'Allineamento, la Sua esistenza non sarà riconosciuta dalla realtà."
  },
  AvgDialog_18779_Content_2 = {
    Text = "Sembra essere immobile."
  },
  AvgDialog_18779_Content_20 = {
    Text = "Prima della sua nascita, il nucleo era ancora lei."
  },
  AvgDialog_18779_Content_3 = {
    Text = "Non è ancora finita."
  },
  AvgDialog_18779_Content_4 = {
    Text = "Il \"cuore\" ha smesso di battere, ma il lamento sommesso portato dalla brezza marina non può essere ignorato."
  },
  AvgDialog_18779_Content_5 = {
    Text = "Avete sentito il pianto?"
  },
  AvgDialog_18779_Content_6 = {
    Text = "Le onde si sollevarono mentre il bozzolo gigante, sorretto da Miryam, si innalzò bruscamente sopra il mare."
  },
  AvgDialog_18779_Content_7 = {
    Text = "Certo, proprio così..."
  },
  AvgDialog_18779_Content_8 = {
    Text = "È tuo diritto prendere tutto ciò che desideri, per la tua nascita e per punire questi senza fede..."
  },
  AvgDialog_18779_Content_9 = {
    Text = "La voce di Miryam si affievolisce, ma la presenza all'interno del bozzolo dormiente diventa più consistente."
  },
  AvgDialog_18784_Content_10 = {
    Text = "Patetica. Basta perdere un Legame d'Argento per ridursi così."
  },
  AvgDialog_18784_Content_11 = {
    Text = "Il Mostro coperto di pustole ignora gli Scherni di Lotan, ruggendo e caricando i suoi nemici."
  },
  AvgDialog_18784_Content_12 = {
    Text = "<Change>Dammela... a... me..."
  },
  AvgDialog_18784_Content_13 = {
    Text = "Se riuscisse ad afferrare quella Bambina... e diventare con lei una coppia di Divi Gemelli..."
  },
  AvgDialog_18784_Content_14 = {
    Text = "Non sarà abbandonata, non piangerà le sue origini, non sarà una pedina al servizio altrui."
  },
  AvgDialog_18784_Content_17 = {
    Text = "<Change>Consegnala... a... me!"
  },
  AvgDialog_18784_Content_18 = {
    Text = "Hai perso persino la capacità di parlare?"
  },
  AvgDialog_18784_Content_19 = {
    Text = "Se è così, canalizza le tue parole e le tue emozioni nella tua spada.\nFammi sentire la tua rabbia!"
  },
  AvgDialog_18784_Content_2 = {
    Text = "<BigShake:ROAR—>"
  },
  AvgDialog_18784_Content_3 = {
    Text = "Poco dopo esservi addentrati nel buio, un Mostro viscoso striscia da sotto il ponte, la sua forma massiccia trascinando innumerevoli sfere di melma, e si schianta davanti a voi."
  },
  AvgDialog_18784_Content_4 = {
    Text = "La creatura solleva la sua metà superiore vagamente Umanoide, scrutandovi, il suo Sguardo che indugia su Lily, sempre più frenetico."
  },
  AvgDialog_18784_Content_6 = {
    Text = "Dammela... a me!"
  },
  AvgDialog_18784_Content_7 = {
    Text = "Lotan avanza, affrontando gli Occhi del Mostro con altera sfida."
  },
  AvgDialog_18784_Content_8 = {
    Text = "Le catene si spezzano, gli arti si gonfiano e si deformano, ma il volto lurido sotto i capelli aggrovigliati e incrostati tradisce ancora l'identità della sua proprietaria."
  },
  AvgDialog_18784_Content_9 = {
    Text = "Tu sei... Helot..."
  },
  AvgDialog_18785_Content_1 = {
    Text = "Realtà Distorta"
  },
  AvgDialog_18785_Content_10 = {
    Text = "A quella luce, vide innumerevoli Ferite nere, grandi e piccole, che sfregiavano la pelle liscia della \"Madre\"."
  },
  AvgDialog_18785_Content_11 = {
    Text = "\"Mi dispiace...\""
  },
  AvgDialog_18785_Content_12 = {
    Text = "Una melma nera ribollì, frantumando la quiete della vasca."
  },
  AvgDialog_18785_Content_13 = {
    Text = "La \"Madre\" emise un grido acuto e stridulo, i Tentacoli si contorcevano mentre depositavano qualcosa nel petto dell'implume."
  },
  AvgDialog_18785_Content_14 = {
    Text = "Tentacoli viscidi, gelidi e morbidi la avvolsero. La Pozza nera non le ostruiva più bocca e naso — al contrario, come liquido amniotico, sosteneva la sua vita."
  },
  AvgDialog_18785_Content_15 = {
    Text = [[
<Change>"Mi dispiace..."
"Io ancora... non voglio morire..."]]
  },
  AvgDialog_18785_Content_16 = {
    Text = "La superficie mantenne una calma prolungata. Neppure i venti polari ululanti riuscivano a increspare la pozza viscosa."
  },
  AvgDialog_18785_Content_17 = {
    Text = "Lady Miryam, la Fanciulla Divina potrebbe già aver..."
  },
  AvgDialog_18785_Content_18 = {
    Text = "Era nata durante l'ultimo Allineamento Stellare, una bambina capace di \"vedere\"."
  },
  AvgDialog_18785_Content_19 = {
    Text = "Nessuno al mondo è più degno del riconoscimento della stirpe divina."
  },
  AvgDialog_18785_Content_2 = {
    Text = "Un uccello implume dalle ali spezzate precipitò in una Pozza nera."
  },
  AvgDialog_18785_Content_20 = {
    Text = "La Donna emaciata stava in piedi al centro del cerchio, arroccata nel punto più alto a dominare ogni cosa.\nI veli ne celavano i lineamenti; neppure i più fidati collaboratori potevano scrutarne i pensieri."
  },
  AvgDialog_18785_Content_21 = {Text = "Murphy..."},
  AvgDialog_18785_Content_3 = {
    Text = "Le Preghiere mormorate dalla somma sacerdotessa si diffondevano ferme e sfuggenti. Parole fanatiche trafissero la melma nera, tramutandosi in Lame che squarciarono il petto dell'implume."
  },
  AvgDialog_18785_Content_4 = {
    Text = "Un liquido Cremisi sgorgò dalla Ferita, sbocciando sinistro sulla superficie nera ormai immobile—"
  },
  AvgDialog_18785_Content_5 = {
    Text = "Eppure continuava a sprofondare, radici intrise di Sangue che si addentravano negli abissi, in un Abbraccio soffice e gelido."
  },
  AvgDialog_18785_Content_6 = {Text = "..."},
  AvgDialog_18785_Content_7 = {Text = "..."},
  AvgDialog_18785_Content_8 = {
    Text = "Lo vide.\nAlzando lo sguardo, la \"Madre\" abbassò tre paia di peduncoli oculari, incontrando il suo Sguardo."
  },
  AvgDialog_18785_Content_9 = {
    Text = "Era una colossale bestia cremisi, con le zone macchiate di sangue che diventavano di un bianco trasparente. La \"Madre\" emanava un debole bagliore, illuminando temporaneamente un piccolo mondo."
  },
  AvgDialog_18786_Content_1 = {
    Text = "Video in dissolvenza"
  },
  AvgDialog_18786_Content_2 = {
    Text = "Ciclo Video 1"
  },
  AvgDialog_18786_Content_3 = {
    Text = "Ciclo Video 2"
  },
  AvgDialog_18786_Content_4 = {
    Text = "Dissolvenza Video in uscita"
  },
  AvgDialog_18786_Content_5 = {Text = "È tutto."},
  AvgDialog_18787_Content_1 = {
    Text = "Ma ora c'è qualcosa di più urgente."
  },
  AvgDialog_18787_Content_10 = {
    Text = "Questa è la ragazza che Herbert sta seguendo. Potrebbe avere indizi rilevanti per la tua indagine."
  },
  AvgDialog_18787_Content_11 = {
    Text = [[
Andiamo, cosa state aspettando?
Vi va di ululare coi lupi tutta la notte all'addiaccio?]]
  },
  AvgDialog_18787_Content_12 = {
    Text = "Se vuoi dormire all'addiaccio, sono sempre pronto a unirmi a te. Ma temo che una ragazza delicata come te potrebbe non farcela."
  },
  AvgDialog_18787_Content_13 = {
    Text = "Lotan dà una pacca sulla spalla di Ramona. Ramona fa una smorfia come se avesse divorato una mosca, ma non dice nulla."
  },
  AvgDialog_18787_Content_14 = {
    Text = "Lady Daffodil... sembra il nome di qualche ricca benefattrice, no?"
  },
  AvgDialog_18787_Content_2 = {Text = "?"},
  AvgDialog_18787_Content_3 = {
    Text = "Se non hai intenzione di usare la neve come coperta, dovresti seriamente pensare a dove alloggeremo stanotte, Custode."
  },
  AvgDialog_18787_Content_4 = {
    Text = "<Italic:Fratellone, Sorellona, venite da un posto molto lontano?>"
  },
  AvgDialog_18787_Content_5 = {
    Text = "Una voce tenera interrompe la vostra conversazione."
  },
  AvgDialog_18787_Content_6 = {
    Text = "Chi è là?"
  },
  AvgDialog_18787_Content_7 = {
    Text = "La neve sul muro riflette l'incontaminata luce lunare, e al suo centro si erge una fanciulla più candida del chiarore della luna."
  },
  AvgDialog_18787_Content_8 = {
    Text = "Se non riuscite a trovare un posto dove stare, potete temporaneamente alloggiare nella stanza di <Blue:Lady Daffodil>.\nÈ proprio dietro l'angolo."
  },
  AvgDialog_18787_Content_9 = {
    Text = "Scambiate uno sguardo con Ramona, che annuisce in segno di conferma."
  },
  AvgDialog_18790_Content_1 = {
    Text = "Ti sei fatto strada combattendo fino alla prua, ma prima che potessi guardare verso il mare, una spinta verso l'alto fece inclinare la nave ancora di più."
  },
  AvgDialog_18790_Content_2 = {
    Text = "La nave cargo si alza e si abbassa con le onde impetuose, e qualcosa emerge dall'acqua—"
  },
  AvgDialog_18790_Content_3 = {Text = "Murphy!"},
  AvgDialog_18790_Content_4 = {
    Text = "La testa del serpente stringeva saldamente il corpo della ragazza, e Miryam poteva solo pregare con voce rauca e indistinta."
  },
  AvgDialog_18790_Content_5 = {
    Text = "Ph'nglui mglw'nafh @3..."
  },
  AvgDialog_18790_Content_6 = {
    Text = "Sollevò Murphy alla luce della luna. Piccole, delicate mani nere sgorgarono dal petto della ragazza, contorcendosi e intrecciandosi, avvolgendo il suo corpo in strati fino a formare un gigantesco bozzolo nero."
  },
  AvgDialog_18790_Content_7 = {
    Text = "Con un ringhio soffocato, mani e fili neri usano Miryam come struttura, avvolgendo strettamente il bozzolo attorno al corpo del serpente gigante."
  },
  AvgDialog_18790_Content_8 = {
    Text = "Il guscio del bozzolo diventa trasparente per il rigonfiamento. Innumerevoli mani si intrecciano a formare un trono, sollevando un cuore pallido."
  },
  AvgDialog_18790_Content_9 = {
    Text = "Ph'nglui mglw'nafh @1'@2 wgah'nagl fhtagn!"
  },
  AvgDialog_18792_Content_1 = {
    Text = "È solo una ragazzina dei bassifondi, non sa nulla e non rappresenterà alcuna minaccia per voi..."
  },
  AvgDialog_18792_Content_10 = {
    Text = "Che seccatura, le mie braccia si stancano. Hai intenzione di morire qui oggi, 24?"
  },
  AvgDialog_18792_Content_11 = {
    Text = "Perdere un animale domestico così obbediente farebbe venire le lacrime persino a me."
  },
  AvgDialog_18792_Content_12 = {
    Text = "Mi dispiace... non mi allontanerò di un solo passo da qui."
  },
  AvgDialog_18792_Content_14 = {
    Text = "SCHIAFFO—!"
  },
  AvgDialog_18792_Content_15 = {
    Text = "Ben presto, l'intero corpo di 24 è un ammasso sanguinante. Eppure lei non si muove di un centimetro, ripetendo le stesse parole ancora e ancora."
  },
  AvgDialog_18792_Content_16 = {
    Text = "<Shake:L-Lasciatela andare... Vi prego...>"
  },
  AvgDialog_18792_Content_17 = {
    Text = "<Shake:Lasciatela andare...>"
  },
  AvgDialog_18792_Content_18 = {
    Text = "Venite a prendermi se avete il coraggio, branco di perdenti! Non..."
  },
  AvgDialog_18792_Content_19 = {
    Text = "<Bold:Non fate del male a mia sorella...>"
  },
  AvgDialog_18792_Content_2 = {
    Text = "SCHIAFFO—!"
  },
  AvgDialog_18792_Content_20 = {
    Text = "Signorina 24! Fermati... Ugh..."
  },
  AvgDialog_18792_Content_21 = {
    Text = "<Small:Non... riesco a muovermi. Devo trovare un modo per ottenere la Chiave d'argento...>"
  },
  AvgDialog_18792_Content_22 = {
    Text = "Sei così sciocca, così tanto sciocca! Non biasimarmi se sarò spietata~"
  },
  AvgDialog_18792_Content_23 = {
    Text = "Leigh, è il tuo momento di brillare."
  },
  AvgDialog_18792_Content_3 = {
    Text = "La frusta si abbatte senza pietà, lasciando un feroce segno rosso sul volto di 24."
  },
  AvgDialog_18792_Content_4 = {Text = "UGH!"},
  AvgDialog_18792_Content_5 = {
    Text = "24 si erge davanti a Jenkin, le sue scapole sottili tremano come ali di farfalla."
  },
  AvgDialog_18792_Content_6 = {
    Text = "Riesce ad abbozzare un debole sorriso, ma sembra più doloroso di un pianto."
  },
  AvgDialog_18792_Content_7 = {
    Text = "Mio signore, vi prego, abbiate pietà... Lasciatela andare, e farò qualsiasi cosa..."
  },
  AvgDialog_18792_Content_8 = {
    Text = "SCHIAFFO—!"
  },
  AvgDialog_18792_Content_9 = {
    Text = "Innumerevoli frustate cadono come gocce di pioggia."
  },
  AvgDialog_18795_Content_1 = {
    Text = "La punta del suo stocco perforò le scaglie del serpente, colpendone il punto vitale."
  },
  AvgDialog_18795_Content_10 = {
    Text = "Re... Mio Signore... Murphy... Murphy..."
  },
  AvgDialog_18795_Content_12 = {
    Text = "Non è troppo tardi.\nTorna alla setta, e rimarrai la venerata Madre Divina."
  },
  AvgDialog_18795_Content_13 = {
    Text = "Il tuo funerale sarà il rito più grandioso nella storia del Reame Divino, venerato da migliaia di fedeli... il tuo nome inciso negli annali eterni."
  },
  AvgDialog_18795_Content_14 = {
    Text = "Torna da me. Insieme, noi... giustizieremo questo <Blue:blasfemo>."
  },
  AvgDialog_18795_Content_15 = {
    Text = "Esecuzione... Questa persona ignobile, travestita da mio signore!"
  },
  AvgDialog_18795_Content_16 = {
    Text = "Il serpente si dissolse e si riformò, lo spazio si deformava sotto il potere di Miryam."
  },
  AvgDialog_18795_Content_17 = {
    Text = "Miryam! Ti ordino di fermarti!"
  },
  AvgDialog_18795_Content_18 = {
    Text = "Falso dio, contraffatto, ingannatore, blasfemo... Nessun @1@2... Non è permesso usare la forma di @3@4!"
  },
  AvgDialog_18795_Content_19 = {
    Text = [[
In un istante, le ombre che avvolgevano la sala macchine si solidificarono.
Strutture indescrivibili e contorte si levarono dal suolo.]]
  },
  AvgDialog_18795_Content_2 = {
    Text = "Ehi, ehi! {Male=Sta,Female=Sta} per cadere!"
  },
  AvgDialog_18795_Content_20 = {
    Text = "<Change>Irriverenti... Irriverenti... Sfrenato e incontrollabile▼▼▼▼▼▼▼▼!"
  },
  AvgDialog_18795_Content_21 = {
    Text = "La sua voce degenerò in un rumore stridulo e incoerente, le mani che artigliavano la gola mentre il corpo si stirava e contorceva."
  },
  AvgDialog_18795_Content_22 = {
    Text = "Attento! Sta perdendo il controllo!"
  },
  AvgDialog_18795_Content_3 = {
    Text = "Sei precipitato tra il ruggito del serpente..."
  },
  AvgDialog_18795_Content_4 = {
    Text = "—in un abbraccio tremante e caldo."
  },
  AvgDialog_18795_Content_5 = {
    Text = "...%player%."
  },
  AvgDialog_18795_Content_6 = {
    Text = "Sono in paradiso?"
  },
  AvgDialog_18795_Content_7 = {
    Text = "Spiacente, siamo ancora sulla Sonanil. E la crisi è imminente..."
  },
  AvgDialog_18795_Content_8 = {
    Text = "<Small:Imperdonabile...>"
  },
  AvgDialog_18795_Content_9 = {
    Text = "Attenzione! Miryam si sta comportando in modo strano!"
  },
  AvgDialog_18796_Content_1 = {
    Text = "Ahem, ahem, ciao a tutti! Oggi testeremo gli effetti di transizione dello Z1~"
  },
  AvgDialog_18796_Content_10 = {
    Text = "Adatta per passare rapidamente a scene più scure."
  },
  AvgDialog_18796_Content_11 = {
    Text = "Phew... sono esausta. Non c'è bisogno di spiegarlo, vero? Dopo la Fase 4, è ovviamente il momento della Fase 5!"
  },
  AvgDialog_18796_Content_12 = {
    Text = "Hmm... In sintesi, la N.5 è una transizione molto versatile che funziona bene in molte situazioni."
  },
  AvgDialog_18796_Content_13 = {
    Text = "Bene, ora passiamo all'ultima transizione—diamo il benvenuto alla N. 6!"
  },
  AvgDialog_18796_Content_14 = {
    Text = "Questa è la transizione più lunga di sempre~"
  },
  AvgDialog_18796_Content_15 = {
    Text = "Questi sono tutti gli effetti di transizione. Tutti hanno capito?"
  },
  AvgDialog_18796_Content_16 = {
    Text = "Alla prossima♡"
  },
  AvgDialog_18796_Content_2 = {
    Text = "Ecco la Transizione 1 — Transizione Sinistra e Destra~!!"
  },
  AvgDialog_18796_Content_3 = {
    Text = "Ta-da! Che ne pensate? Non è magnifica!"
  },
  AvgDialog_18796_Content_4 = {
    Text = "Questa transizione viene tipicamente usata per passare tra scene simili, sapete."
  },
  AvgDialog_18796_Content_5 = {
    Text = "La prossima è la Transizione n. 2 —"
  },
  AvgDialog_18796_Content_6 = {
    Text = "Questa transizione viene tipicamente usata per passare a una scena più luminosa."
  },
  AvgDialog_18796_Content_7 = {
    Text = "Poi... Transizione n. 3!"
  },
  AvgDialog_18796_Content_8 = {
    Text = "La Transizione n. 3 è anch'essa adatta per passare a scene luminose, ma il ritmo sarà leggermente più lento, hehe."
  },
  AvgDialog_18796_Content_9 = {
    Text = "La prossima è — Scena 4!"
  },
  AvgDialog_18797_Content_1 = {
    Text = "Hmm... @1... Ugh..."
  },
  AvgDialog_18797_Content_10 = {
    Text = "Non sei tu il \"Re Divino\"!"
  },
  AvgDialog_18797_Content_11 = {
    Text = "Dopotutto, in quanto colui che Miryam serve, non sei stato tu a decretare la profezia della resurrezione di Dio?"
  },
  AvgDialog_18797_Content_12 = {Text = "Tu..."},
  AvgDialog_18797_Content_13 = {
    Text = "Ho appena visto... attraverso il legame, ho visto i tuoi ricordi"
  },
  AvgDialog_18797_Content_14 = {Text = "...Sì."},
  AvgDialog_18797_Content_15 = {
    Text = "Questa è la profezia che ho conferito, ma il cosiddetto \"oracolo divino\" non esiste."
  },
  AvgDialog_18797_Content_16 = {Text = "Cosa?"},
  AvgDialog_18797_Content_17 = {
    Text = "Molto prima che il diluvio arrivasse, avevo perso la capacità di intravedere il futuro nei Suoi sogni./nNon so dove sia andato; potrebbe essersi risvegliato, o potrebbe essersene andato."
  },
  AvgDialog_18797_Content_18 = {
    Text = "Allora, la tua profezia..."
  },
  AvgDialog_18797_Content_19 = {
    Text = "Miryam è una devota credente, nata per il Reame Divino e mossa dalla Mia volontà."
  },
  AvgDialog_18797_Content_2 = {
    Text = "Murphy emise un gemito di dolore, i suoi mormorii frammentati."
  },
  AvgDialog_18797_Content_20 = {
    Text = "Speravo soltanto che le mie parole la confortassero nei suoi ultimi istanti, senza mai immaginare che le avrebbe prese come verità assoluta e avrebbe cercato di ricostruire il Reame Divino."
  },
  AvgDialog_18797_Content_21 = {
    Text = "Tutto quanto era..."
  },
  AvgDialog_18797_Content_22 = {
    Text = "La colpa è interamente mia."
  },
  AvgDialog_18797_Content_23 = {
    Text = "Conto alla rovescia: 60 minuti"
  },
  AvgDialog_18797_Content_3 = {
    Text = "Cos'è questo?!"
  },
  AvgDialog_18797_Content_4 = {
    Text = "Terrificanti segni verde scuro apparvero sul volto di Murphy, insinuandosi in profondità sotto la pelle come radici di piante."
  },
  AvgDialog_18797_Content_5 = {
    Text = "Sta iniziando a bloccare il flusso sanguigno dell'ospite."
  },
  AvgDialog_18797_Content_6 = {
    Text = "Non si diceva che bastasse stare lontani dai corpi celesti?"
  },
  AvgDialog_18797_Content_7 = {
    Text = "Intendevo dire che potrebbe soffrire meno."
  },
  AvgDialog_18797_Content_8 = {
    Text = "L'orbita celeste è stata raggiunta; non si può più tornare indietro."
  },
  AvgDialog_18797_Content_9 = {
    Text = "Non c'è davvero nessuna soluzione?"
  },
  AvgDialog_18798_Content_1 = {
    Text = "Ahh... Ahh... Niente sopra, niente nemmeno sotto..."
  },
  AvgDialog_18798_Content_10 = {
    Text = "Murphy perse istantaneamente le forze, scivolando lungo la ringhiera della nave sul ponte, senza più curarsi di mantenere una postura composta."
  },
  AvgDialog_18798_Content_11 = {
    Text = "Voleva trovare qualcosa a cui aggrapparsi. Dopo qualche tentativo, si appoggiò alla tua spalla."
  },
  AvgDialog_18798_Content_12 = {
    Text = "Solo un momento..."
  },
  AvgDialog_18798_Content_13 = {
    Text = [[
In pochi secondi, un respiro rapido ma ritmico raggiunge le tue orecchie.

Murphy perde conoscenza ancora una volta.]]
  },
  AvgDialog_18798_Content_14 = {
    Text = "Si sta indebolendo..."
  },
  AvgDialog_18798_Content_15 = {
    Text = "Il Dio con cui comunico proviene da miriadi di stelle. Persino una mera replica è al di là della resistenza umana."
  },
  AvgDialog_18798_Content_16 = {
    Text = "Non c'è modo di alleviarlo?"
  },
  AvgDialog_18798_Content_17 = {
    Text = "...Portala sotto coperta."
  },
  AvgDialog_18798_Content_18 = {
    Text = "Stando lontana dai corpi celesti, potrebbe sentirsi meglio."
  },
  AvgDialog_18798_Content_2 = {
    Text = "Dove... ahh... sono?"
  },
  AvgDialog_18798_Content_3 = {
    Text = "<Small:Ugh... Perché questa nave è così enorme...>"
  },
  AvgDialog_18798_Content_4 = {Text = "Stai bene?"},
  AvgDialog_18798_Content_5 = {
    Text = "Sto benissimo! Cough, cough..."
  },
  AvgDialog_18798_Content_6 = {
    Text = "Murphy alza la voce per risponderti ma accidentalmente si strozza e inizia a tossire violentemente."
  },
  AvgDialog_18798_Content_7 = {
    Text = "Ma sono davvero stanca, e mi fa un po' male la testa."
  },
  AvgDialog_18798_Content_8 = {
    Text = "Mentre parli, ti sei già seduto sul posto."
  },
  AvgDialog_18798_Content_9 = {
    Text = "Beh... riposiamoci, solo un momento..."
  },
  AvgDialog_18802_Content_1 = {
    Text = "Se solo fossi un po' più forte, se potessi sempre resistergli...\nMa non posso, semplicemente non posso."
  },
  AvgDialog_18802_Content_10 = {
    Text = "Mi dispiace... Mi dispiace... È tutta colpa... È tutta colpa mia..."
  },
  AvgDialog_18802_Content_11 = {
    Text = "Sono un mostro inutile. Ho causato la morte di così tante persone, eppure non sono riuscita a salvare la sorella di Jenkin."
  },
  AvgDialog_18802_Content_12 = {
    Text = "È stata portata via, portata via... ma non so nemmeno dove sia andata...\nNon so nemmeno chi ci stia controllando..."
  },
  AvgDialog_18802_Content_13 = {
    Text = "Ramona si inginocchiò davanti ad Aigis, stringendo dolcemente la ragazza tra le sue braccia."
  },
  AvgDialog_18802_Content_14 = {
    Text = "Hai fatto del tuo meglio, Aigis. Non è colpa tua."
  },
  AvgDialog_18802_Content_15 = {
    Text = "Quello era il vero Squartatore, colui che ti controllava e commetteva questi crimini.\nNon è mai stata colpa tua."
  },
  AvgDialog_18802_Content_16 = {
    Text = "La ragazza si gettò tra le braccia di Ramona, singhiozzando senza controllo, ma senza mai dimenticare di coprirsi gli occhi con la mano destra."
  },
  AvgDialog_18802_Content_17 = {
    Text = "Troveremo quella persona."
  },
  AvgDialog_18802_Content_18 = {
    Text = [[
Lo troveremo e gliela faremo pagare.
Te lo giuro.]]
  },
  AvgDialog_18802_Content_19 = {
    Text = "Grazie, grazie a tutti... Grazie."
  },
  AvgDialog_18802_Content_2 = {
    Text = "L'ultima volta ho provato a resistergli, ma... ma... non ce l'ho fatta. Singhiozzo..."
  },
  AvgDialog_18802_Content_20 = {
    Text = "I raggi dorati del sole al tramonto penetrano l'enorme quadrante trasparente della torre dell'orologio, avvolgendo la ragazza nella loro luce."
  },
  AvgDialog_18802_Content_21 = {
    Text = "Aigis si voltò di lato, posando una mano sul vetro, socchiudendo gli occhi nella calda luce del sole."
  },
  AvgDialog_18802_Content_22 = {
    Text = "Oggi riesco a vedere il sole..."
  },
  AvgDialog_18802_Content_24 = {
    Text = "Forse rinvigorita dalla rara giornata di sole, barcolla fino a un pezzo di vetro più pulito."
  },
  AvgDialog_18802_Content_25 = {
    Text = "La sua Visuale offuscata si schiarisce. Contemplando strade familiari e sconosciute, qualcuno sembra sussurrarle all'orecchio."
  },
  AvgDialog_18802_Content_26 = {
    Text = "<Italic:\"Guarda,\"> dice quella Voce, <Italic:\"Te l'avevo detto. Stanotte ci saranno delle Stelle bellissime.\">"
  },
  AvgDialog_18802_Content_28 = {
    Text = "La ragazza abbassò la testa, rivelando un sorriso malinconico."
  },
  AvgDialog_18802_Content_29 = {
    Text = "In passato, ogni volta che il sole era visibile, Tyog mi portava quassù di nascosto durante la notte."
  },
  AvgDialog_18802_Content_3 = {
    Text = "Basta. Smettila di costringermi a fare questo."
  },
  AvgDialog_18802_Content_30 = {
    Text = "La signorina Sarah non ci permetteva mai di venire qui; diceva che era troppo pericoloso e che potevamo farci male facilmente. Ma a Tyug non importava nulla di tutto ciò."
  },
  AvgDialog_18802_Content_31 = {
    Text = "Ha una vista eccellente; riesce a vedere chiaramente il sentiero, non importa quanto sia buio il posto."
  },
  AvgDialog_18802_Content_32 = {
    Text = "È furbo e coraggioso, proprio come Jenkin. Conosce sempre sentieri nascosti e scorciatoie che gli altri ignorano."
  },
  AvgDialog_18802_Content_33 = {
    Text = "Finché lui era con me, la signorina Sarah non ci avrebbe mai trovati."
  },
  AvgDialog_18802_Content_34 = {
    Text = "Finché lui era con me, questo posto sarebbe sempre stato il Nostro Segreto rifugio."
  },
  AvgDialog_18802_Content_35 = {
    Text = [[
Mi disse che dovevo connettermi con le stelle per rafforzare la mia magia. 
Anche se qui non riusciamo a vedere nemmeno una stella.]]
  },
  AvgDialog_18802_Content_36 = {
    Text = [[
A quel tempo, era l'unico a credere in me.
Credeva che potessi vedere quelle cose oscure e mi disse che era un dono da strega.]]
  },
  AvgDialog_18802_Content_37 = {
    Text = "Dopo... dopo di allora, i dottori iniziarono a portare via i pazienti, smettendo di curarli all'ospizio. Non riuscii a raccogliere prove né a vendicare Tiyoug."
  },
  AvgDialog_18802_Content_38 = {
    Text = "Se fossi stata intelligente come lui e coraggiosa come Jenkin, probabilmente avrei già scoperto la verità."
  },
  AvgDialog_18802_Content_39 = {
    Text = "Ma non sono una strega."
  },
  AvgDialog_18802_Content_4 = {
    Text = "Non voglio fare del male a nessuno, e non voglio uccidere."
  },
  AvgDialog_18802_Content_40 = {
    Text = "Sono solo un codardo."
  },
  AvgDialog_18802_Content_41 = {Text = "Un mostro."},
  AvgDialog_18802_Content_42 = {
    Text = "Un... assassino."
  },
  AvgDialog_18802_Content_43 = {
    Text = [[
Sai quante volte sono stata manipolata?
Sai quanto sangue macchia le mie mani?]]
  },
  AvgDialog_18802_Content_44 = {
    Text = "Sono terrorizzata da ciò che sto per diventare..."
  },
  AvgDialog_18802_Content_46 = {
    Text = "Un tempo provavo dolore agli occhi e al corpo. Ma ora non sento più nulla, come se fossi fatta di pietra."
  },
  AvgDialog_18802_Content_48 = {
    Text = "Dannazione, dove diavolo sono finiti tutti..."
  },
  AvgDialog_18802_Content_49 = {
    Text = "Aspetta, quello è..."
  },
  AvgDialog_18802_Content_5 = {
    Text = "<Shake:<AvgNormalFont:No! No!\nNon fate fare questo al piccolo Mike. È così piccolo. Come può... <Shake:Vi prego...>>>"
  },
  AvgDialog_18802_Content_50 = {
    Text = "Aigis?! Aigis—!"
  },
  AvgDialog_18802_Content_51 = {
    Text = "All'improvviso, la voce di Jenkin giunse da sotto la torre dell'orologio. In qualche modo era apparsa nel cortile."
  },
  AvgDialog_18802_Content_52 = {
    Text = "Gridò ansiosamente il nome di Aigis, tendendo le braccia verso il cielo."
  },
  AvgDialog_18802_Content_53 = {
    Text = "Il piccolo corpo della ragazza precipita, svanendo per sempre dal cielo notturno."
  },
  AvgDialog_18802_Content_54 = {
    Text = "Un uccello attraversa il cielo notturno, svanendo nella fitta nebbia senza lasciare traccia."
  },
  AvgDialog_18802_Content_55 = {
    Text = "Le braccia tese di Jenkin stringevano soltanto il vestito vuoto di Aigis, mentre pezzetti di carta quadrati si sparpagliavano come fiocchi di neve."
  },
  AvgDialog_18802_Content_56 = {
    Text = "Ai... Aigis...?\nCome... come è potuto succedere...?"
  },
  AvgDialog_18802_Content_57 = {
    Text = "Una farfalla dorata è disegnata sulla carta, con i bordi piegati accuratamente lisciati e ripiegati. Cadendo, porta con sé un dolce profumo di caramella."
  },
  AvgDialog_18802_Content_58 = {
    Text = "Ugh... Aigis..."
  },
  AvgDialog_18802_Content_59 = {
    Text = "Un nastro macchiato di sangue, insieme a un involucro di caramella, cadde nella mano della ragazza. Oscillava con il vento, sfiorando delicatamente le sue dita, proprio come una tenera carezza offerta da qualcuno."
  },
  AvgDialog_18802_Content_6 = {
    Text = "Non sento, non sento, non sento, non sento, non sento—"
  },
  AvgDialog_18802_Content_60 = {
    Text = "La ragazza sbatté le palpebre, e le lacrime le offuscarono la vista, catturate silenziosamente da quel rosso vivido."
  },
  AvgDialog_18802_Content_61 = {
    Text = "Questo colore familiare, questa consistenza familiare — manca solo una fibbia d'argento per corrispondere perfettamente a ciò che ricorda."
  },
  AvgDialog_18802_Content_62 = {
    Text = "...Sorella...?"
  },
  AvgDialog_18802_Content_7 = {
    Text = [[
Ha funzionato? Ce l'abbiamo fatta?
Presto, scappate, ma per favore non ditelo a nessuno.]]
  },
  AvgDialog_18802_Content_8 = {
    Text = "<Shake:<AvgNormalFont:Aspetta, cos'è questo?! La mia testa, la mia testa...\nAh... ah...!<Shake:Ahhh!!>>>"
  },
  AvgDialog_18802_Content_9 = {
    Text = "Mi dispiace... Mi dispiace tanto..."
  },
  AvgDialog_18804_Content_1 = {
    Text = "In quanto Custode rispettabile, sei stato completamente raggirato da un gruppo di ragazzini qualunque. Un anno di addestramento buttato al vento. Persino le matricole delle scuole pubbliche sono più sveglie di te."
  },
  AvgDialog_18804_Content_2 = {
    Text = "Sei fortunato che il ladro si trovasse sul luogo della missione. Altrimenti, peggio per te. Non ti permetterò di sprecare il tempo della missione per questioni personali."
  },
  AvgDialog_18804_Content_3 = {
    Text = "Non è poi così grave, Doll. Dai un po' di fiducia a %player%."
  },
  AvgDialog_18804_Content_4 = {
    Text = "Si prega di non interferire con le indagini del Custode."
  },
  AvgDialog_18805_Content_1 = {
    Text = "In quanto Custode rispettabile, sei stato completamente raggirato da un gruppo di ragazzini qualunque. Un anno di addestramento buttato al vento. Persino le matricole delle scuole pubbliche sono più sveglie di te."
  },
  AvgDialog_18805_Content_2 = {
    Text = "Sei fortunato che il ladro si trovasse sul luogo della missione. Altrimenti, peggio per te. Non ti permetterò di sprecare il tempo della missione per questioni personali."
  },
  AvgDialog_18805_Content_3 = {
    Text = "Non è poi così grave, Doll. Dai un po' di fiducia a %player%."
  },
  AvgDialog_18805_Content_4 = {
    Text = "Si prega di non interferire con le indagini del Custode."
  },
  AvgDialog_18808_Content_1 = {
    Text = "Questo è un test di dialogo senza sfondo 1"
  },
  AvgDialog_18808_Content_2 = {
    Text = "Questo è un test di dialogo senza sfondo 2"
  },
  AvgDialog_18809_Content_1 = {
    Text = "\nMurphy non esitò molto; tirò Ramona da parte e iniziò a slacciarle i vestiti.\nQuando l'ultimo bottone sul davanti fu sbottonato, Ramona vide il \"dio\" dentro la ragazza."
  },
  AvgDialog_18809_Content_2 = {
    Text = "Una chiazza di pelle trasparente è chiaramente visibile sul petto, che tira la pelle e i muscoli circostanti, conferendo all'intero torace e addome una tonalità grigiastra, di un bianco in decomposizione."
  },
  AvgDialog_18809_Content_3 = {
    Text = "Una tale anomalia esponeva gli organi nel suo petto; Ramona vide un giovane cuore di un cremisi pallido e un \"uovo\" lattiginoso."
  },
  AvgDialog_18809_Content_4 = {
    Text = "Innumerevoli filamenti sottili germogliavano dall'uovo, intrecciandosi con i vasi sanguigni di Murphy in una danza simbiotica."
  },
  AvgDialog_18809_Content_5 = {
    Text = "Se non fosse stato per il modo in cui premeva contro il suo cuore, sarebbe potuto sembrare una parte naturale del suo corpo traslucido, non un intruso estraneo."
  },
  AvgDialog_18809_Content_6 = {
    Text = "Caotico eppure silenzioso, recava un triangolo invertito e immobile di segni neri, come un'opera d'arte grottesca."
  },
  AvgDialog_18809_Content_7 = {
    Text = "Dissoluzione... quella cosa è stata marchiata dalla Dissoluzione."
  },
  AvgDialog_18809_Content_8 = {
    Text = "Ti sei stancato di fissare?"
  },
  AvgDialog_18809_Content_9 = {
    Text = "Scusa, errore mio. Per favore, rimettiti i vestiti."
  },
  AvgDialog_18810_Content_1 = {
    Text = "Conto alla rovescia: 20 minuti"
  },
  AvgDialog_18810_Content_10 = {
    Text = "Attenzione! Non cadete in mare!"
  },
  AvgDialog_18810_Content_11 = {
    Text = [[
Un enorme serpente eruppe dal mare, quasi capovolgendo l'intera nave.
Molteplici teste di serpente si contorcevano e attorcigliavano, proiettando grandi ombre minacciose sul ponte.]]
  },
  AvgDialog_18810_Content_12 = {
    Text = "Usurpatore... Impudente... Stolto!"
  },
  AvgDialog_18810_Content_13 = {
    Text = "Dea... Dea... @3!"
  },
  AvgDialog_18810_Content_14 = {
    Text = "Oh no, è Miryam!"
  },
  AvgDialog_18810_Content_15 = {
    Text = "Abbattete Murphy, presto!"
  },
  AvgDialog_18810_Content_16 = {Text = "Ugh!!"},
  AvgDialog_18810_Content_17 = {
    Text = "Ti volti verso il ponte; Murphy non c'è più. Una testa di serpente gigantesca ha afferrato la ragazza e l'ha trascinata in mare."
  },
  AvgDialog_18810_Content_2 = {
    Text = "Legame? Significa che in futuro dipenderà da te per sopravvivere?"
  },
  AvgDialog_18810_Content_3 = {
    Text = "È solo una misura temporanea. Non abbiamo intenzione di portarvi via la signorina Celeste."
  },
  AvgDialog_18810_Content_4 = {
    Text = "Non è qualcosa che posso decidere io."
  },
  AvgDialog_18810_Content_5 = {
    Text = "Celeste, sei disposta?"
  },
  AvgDialog_18810_Content_6 = {
    Text = "Come attivata da una parola chiave, Celeste alzò lo sguardo ma lo rivolse al mare alle sue spalle, e il viaggio si arrestò."
  },
  AvgDialog_18810_Content_7 = {
    Text = "La nave non riesce a muoversi."
  },
  AvgDialog_18810_Content_8 = {
    Text = "Qualcosa mi ha afferrata."
  },
  AvgDialog_18810_Content_9 = {
    Text = "Prima che le parole fossero finite, il suolo tremò violentemente come mai prima, e la nave si inclinò a un angolo inconcepibile."
  },
  AvgDialog_18812_Content_1 = {
    Text = "Anche voi... Un branco di adulti egocentrici."
  },
  AvgDialog_18812_Content_10 = {
    Text = "La luce abbagliante ti ferisce gli occhi, provocando lacrime incontenibili."
  },
  AvgDialog_18812_Content_11 = {
    Text = "Questo, questo è!?"
  },
  AvgDialog_18812_Content_12 = {
    Text = "Il liquido torbido defluisce, e i tuoi occhi finalmente tornano a mettere a fuoco la bambina."
  },
  AvgDialog_18812_Content_13 = {
    Text = "La lama affonda nel suo petto, e la bambina illuminata dalla luna apre gli occhi."
  },
  AvgDialog_18812_Content_14 = {
    Text = "La luna piena, simbolo di morte, incombe vicina, eppure non vi è traccia di terrore sul suo volto giovane."
  },
  AvgDialog_18812_Content_15 = {
    Text = "L'ho... trafitto... Non nascerà..."
  },
  AvgDialog_18812_Content_16 = {
    Text = "Allora... Loro possono..."
  },
  AvgDialog_18812_Content_17 = {
    Text = "La mano che stringe il coltello cade debolmente, mentre un liquido cremisi, viscoso e scuro cola dalla lama, gocciolando tra le sue dita nel mare."
  },
  AvgDialog_18812_Content_18 = {
    Text = "Il sangue defluisce rapidamente dal corpo, lasciando la pelle di un pallore mortale, eppure una vitalità insolita emana dall'interno."
  },
  AvgDialog_18812_Content_19 = {
    Text = "No... No, no, no, no, aahh—"
  },
  AvgDialog_18812_Content_2 = {
    Text = "Nessuno mi ha mai chiesto la mia opinione... Hmph."
  },
  AvgDialog_18812_Content_20 = {
    Text = "Oh Signore, perdonami, perdona questa bambina, perdona la Tua devota credente..."
  },
  AvgDialog_18812_Content_21 = {
    Text = "L'Allineamento Stellare, è vicino... È vicino..."
  },
  AvgDialog_18812_Content_22 = {
    Text = "La \"placenta\" si frantumò, e anche il \"cuore\" collassò—innumerevoli mani eruppero dal corpo, schiacciando la cavità toracica della ragazza."
  },
  AvgDialog_18812_Content_23 = {
    Text = "La mano deforme afferrò i resti irriconoscibili, sovrapponendosi, gonfiandosi, sovrapponendosi, gonfiandosi—"
  },
  AvgDialog_18812_Content_24 = {
    Text = "Ah... Mi avete udito... Mi avete risposto..."
  },
  AvgDialog_18812_Content_25 = {
    Text = "Spingono un'entità deforme nella luce lunare."
  },
  AvgDialog_18812_Content_26 = {
    Text = "Mio grande Dio...!"
  },
  AvgDialog_18812_Content_3 = {
    Text = "Una vita comprata con il sacrificio... Chi la vorrebbe?"
  },
  AvgDialog_18812_Content_4 = {
    Text = "\nNo, la placenta è troppo torbida.\nRiesco a vedere attraverso con il \"Tracciamento Spirituale\"?"
  },
  AvgDialog_18812_Content_5 = {
    Text = "Afferrasti la tremante Chiave d'Argento e sprofondasti nuovamente nello spazio della coscienza."
  },
  AvgDialog_18812_Content_6 = {
    Text = "Nello spazio buio e vuoto ricoperto dalla D-Melma, una minuscola scintilla che simboleggia vita e intelligenza brilla con ancor più fulgore."
  },
  AvgDialog_18812_Content_7 = {
    Text = "—Una lama sacrificale risplende, riflettendo la fredda, spettrale luce lunare."
  },
  AvgDialog_18812_Content_8 = {Text = "—AAGH!!"},
  AvgDialog_18812_Content_9 = {
    Text = "Un'esplosione di luce erutta all'improvviso, scaraventandoti con forza fuori dal Reame dello Spirito."
  },
  AvgDialog_18813_Content_1 = {
    Text = "Ora testeremo l'effetto di transizione: Time Lapse Lento"
  },
  AvgDialog_18813_Content_10 = {
    Text = "Tempesta di sabbia 2"
  },
  AvgDialog_18813_Content_11 = {
    Text = "Test completato"
  },
  AvgDialog_18813_Content_12 = {
    Text = "Ora condurremo un test di scuotimento continuo dello schermo"
  },
  AvgDialog_18813_Content_13 = {
    Text = "Inizio del test"
  },
  AvgDialog_18813_Content_16 = {
    Text = "Test completato"
  },
  AvgDialog_18813_Content_17 = {
    Text = "Ora segue il test video [Effetto Schermo] Attivazione Chiave d'Argento"
  },
  AvgDialog_18813_Content_18 = {
    Text = "Inizio del test"
  },
  AvgDialog_18813_Content_19 = {
    Text = "Test completato, ma avvierò il test [Effetto Schermo] effetto attivazione Chiave d'Argento"
  },
  AvgDialog_18813_Content_2 = {
    Text = "Inizio del test"
  },
  AvgDialog_18813_Content_20 = {
    Text = "Inizio del test"
  },
  AvgDialog_18813_Content_21 = {Text = "In corso"},
  AvgDialog_18813_Content_22 = {
    Text = "Test completato"
  },
  AvgDialog_18813_Content_23 = {
    Text = "Ora eseguiremo il test dell'effetto FadeDarkRole."
  },
  AvgDialog_18813_Content_26 = {Text = "Fine"},
  AvgDialog_18813_Content_3 = {
    Text = "Test completato"
  },
  AvgDialog_18813_Content_4 = {
    Text = "Ora segue il test di transizione sfondo con time-lapse veloce."
  },
  AvgDialog_18813_Content_5 = {
    Text = "Inizio del test"
  },
  AvgDialog_18813_Content_6 = {
    Text = "Test completato"
  },
  AvgDialog_18813_Content_7 = {
    Text = "Ora segue il test [Effetto Schermo] Tempesta di sabbia"
  },
  AvgDialog_18813_Content_8 = {
    Text = "Inizio del test"
  },
  AvgDialog_18813_Content_9 = {
    Text = "Tempesta di sabbia 1"
  },
  AvgDialog_18814_Content_1 = {
    Text = "Uff. Mi dispiace, non c'è tempo perché tu possa abituarti a tutto questo come si deve."
  },
  AvgDialog_18814_Content_10 = {
    Text = "Ramona sembra terrorizzata; non l'hai mai vista così sconvolta."
  },
  AvgDialog_18814_Content_11 = {
    Text = "La ragazza, bombardata di domande, parla con voce tremante, la sua fatica evidente."
  },
  AvgDialog_18814_Content_12 = {
    Text = "Ovviamente. Pensavi che fossi venuta qui per una passeggiata di piacere?"
  },
  AvgDialog_18814_Content_13 = {
    Text = "Chiude gli occhi, ricomponendosi in fretta."
  },
  AvgDialog_18814_Content_14 = {
    Text = "Avrei dovuto capirlo. Gli aggressori hanno mostrato una profonda familiarità con i Mythag; la Tomba della Chiave non poteva essere risparmiata.\nSiamo vicini alla porta sul retro. Sbrigatevi e uscite."
  },
  AvgDialog_18814_Content_15 = {
    Text = "Possiamo andare! %player% può creare un Legame con tutti noi e poi comandare—"
  },
  AvgDialog_18814_Content_16 = {
    Text = "Ramona.\nQuelli sono i nostri obblighi, %player% è solo un novellino."
  },
  AvgDialog_18814_Content_17 = {
    Text = "Ma %player% può farcela, so che {Male=lui,Female=lei} può."
  },
  AvgDialog_18814_Content_18 = {
    Text = "Doll ti scruta attentamente, poi si volta verso Ramona con un'espressione severa."
  },
  AvgDialog_18814_Content_19 = {
    Text = [[
Se non mi sbaglio, la cerimonia del giuramento dovrebbe essere ancora incompleta.
{Male=He,Female=She} non ha ancora ricevuto la Chiave d'argento, giusto?]]
  },
  AvgDialog_18814_Content_2 = {
    Text = "Questi Mutanti hanno raggiunto il Keygrave prima che l'allarme suonasse. La <Blue:Barriera di Nebbia> attorno al Mythag dev'essere caduta."
  },
  AvgDialog_18814_Content_20 = {
    Text = "L'accesso non autorizzato all'area ristretta dei Mythag è un reato grave. Pensavo fossi cresciuta qui e ne fossi consapevole."
  },
  AvgDialog_18814_Content_21 = {
    Text = "La situazione è urgente, e %player% non è una matricola qualunque, {Male=lui,Female=lei} è il nostro unico Custode."
  },
  AvgDialog_18814_Content_22 = {
    Text = "Dovresti ancora ricordare, vero? L'<Yellow:esplosione di Yakutsk> di un anno fa. Se non fosse stato per il {Male=suo,Female=suo} sforzo individuale nel creare un Legame con tutti i Risvegliatori, oggi non sarei qui a discutere con te."
  },
  AvgDialog_18814_Content_23 = {
    Text = "La ragazza dai capelli rosa non risponde e, invece, si volta verso di te."
  },
  AvgDialog_18814_Content_24 = {
    Text = "So che hai intravisto ciò che giace oltre il <Yellow:Portale>; ma la realtà, che si tratti delle fondamenta del Mythag o del Fato del mondo, potrebbe non essere come la idealizzi."
  },
  AvgDialog_18814_Content_25 = {
    Text = "Ci troviamo di fronte a un fenomeno che distrugge l'esistenza materiale stessa. Una volta contaminati dalla <Yellow:Dissoluzione>, tutto ciò che vi riguarda svanirà, persino i ricordi di voi."
  },
  AvgDialog_18814_Content_26 = {
    Text = "Durante la cerimonia del giuramento, il nome inciso sulla lapide si trasformerà in una pozza di fango nero, dimenticato da tutti."
  },
  AvgDialog_18814_Content_27 = {
    Text = "Rispondimi. Sei davvero pronto per questo?"
  },
  AvgDialog_18814_Content_28 = {
    Text = "Lo Sguardo gelido di Doll incontra il tuo, la sua Voce piatta."
  },
  AvgDialog_18814_Content_29 = {
    Text = "Il suo volto non tradisce nulla, ma nel profondo delle sue gelide pupille, intravedi un fuoco ardente."
  },
  AvgDialog_18814_Content_3 = {
    Text = "Abbiamo informato <Blue:William> della cerimonia odierna, ma nessun rinforzo è giunto in nostro aiuto. La campana... dovremmo riorganizzarci ed <Yellow:eliminare la fonte dell'anomalia>!"
  },
  AvgDialog_18814_Content_30 = {
    Text = "La tua risposta è—"
  },
  AvgDialog_18814_Content_31 = {
    Text = "La mia lapide ora si erge come parte del Keygrave."
  },
  AvgDialog_18814_Content_32 = {
    Text = "Sei un membro del Mythag. Forse lo eri già a Yakutsk."
  },
  AvgDialog_18814_Content_33 = {
    Text = "Ci sono cose che solo io posso compiere."
  },
  AvgDialog_18814_Content_34 = {
    Text = "La decisione può essere affrettata, ma si può mai essere davvero preparati a tutto nella vita?"
  },
  AvgDialog_18814_Content_35 = {Text = "Bene."},
  AvgDialog_18814_Content_36 = {
    Text = "Per l'Autorità del Sesto Preside del Mythag, <Blue:Oliver Elsie>, con la presente ti conferisco la Chiave d'Argento K-0617."
  },
  AvgDialog_18814_Content_38 = {
    Text = "Doll recupera la Chiave d'Argento da un cofanetto ornato e la posa sul tuo petto. Emana un debole bagliore, inondandoti di una vaga sensazione di familiarità."
  },
  AvgDialog_18814_Content_39 = {
    Text = "D'ora in avanti, ti ergi come Custode tra i molti studenti e studiosi di Mythag."
  },
  AvgDialog_18814_Content_4 = {Text = "?!"},
  AvgDialog_18814_Content_40 = {Text = "..."},
  AvgDialog_18814_Content_41 = {
    Text = "Ora, stabilisci un Legame con me."
  },
  AvgDialog_18814_Content_5 = {
    Text = "Ai margini della tua Visuale, un giovane biondo solleva un enorme scudo nero, respingendo a malapena l'Assalto di una spadaccina con due lame."
  },
  AvgDialog_18814_Content_6 = {
    Text = "Protegge una ragazza dai capelli rosa dietro di sé; ogni colpo deviato lo costringe a indietreggiare di un altro passo."
  },
  AvgDialog_18814_Content_7 = {
    Text = "Riconosci quella ragazza dai capelli rosa. È la Professoressa Doll, nota per essere difficile da approcciare, e appartiene all'<Blue:Istituto di Ricerca sul Risveglio>. In altre parole, è una non combattente."
  },
  AvgDialog_18814_Content_8 = {
    Text = "Aspetta... l'aggressore... è un Risvegliatore?"
  },
  AvgDialog_18814_Content_9 = {
    Text = "Doll? La <Blue:Torre dell'Orologio> è stata compromessa?!"
  },
  AvgDialog_18815_Content_1 = {
    Text = "Conto alla rovescia: 80 minuti"
  },
  AvgDialog_18815_Content_10 = {
    Text = "Murphy fece due passi avanti, barcollò improvvisamente e crollò senza forze contro l'albero maestro."
  },
  AvgDialog_18815_Content_11 = {Text = "Murphy?!"},
  AvgDialog_18815_Content_12 = {
    Text = "Aiuti Murphy a rialzarsi dal ponte. È a malapena cosciente, la frangia umida di sudore freddo, appiccicata disordinatamente alla fronte."
  },
  AvgDialog_18815_Content_13 = {
    Text = "Ahi... fa così male..."
  },
  AvgDialog_18815_Content_14 = {
    Text = "Hmm... @1... @1..."
  },
  AvgDialog_18815_Content_15 = {
    Text = "Si aggrappa alla tua Mano che la sorregge, il dolore le fa affondare le dita a fondo—eppure avverti a malapena quella lieve fitta."
  },
  AvgDialog_18815_Content_16 = {
    Text = "Senti i battiti crescenti — muscoli non di origine umana pulsano nel petto della ragazza."
  },
  AvgDialog_18815_Content_17 = {
    Text = "L'embrione... Sta prosciugando la sua forza vitale."
  },
  AvgDialog_18815_Content_18 = {
    Text = "Mir... @2..."
  },
  AvgDialog_18815_Content_19 = {
    Text = "Oltre a gemere di dolore, Murphy riusciva solo a mormorare parole prive di senso."
  },
  AvgDialog_18815_Content_2 = {
    Text = "Una fitta nebbia ricopre il mare, ma il ponte è immerso nella luce lunare, rendendo chiaramente visibili le espressioni di tutti."
  },
  AvgDialog_18815_Content_20 = {
    Text = "Nel mezzo del rumore caotico, i nemici emergono dalle ombre."
  },
  AvgDialog_18815_Content_3 = {Text = "La Luna..."},
  AvgDialog_18815_Content_4 = {
    Text = "Che succede con la Luna?"
  },
  AvgDialog_18815_Content_5 = {
    Text = "Si sta schiarendo."
  },
  AvgDialog_18815_Content_6 = {
    Text = "Murphy trattiene il resto, ma sai cosa intende—"
  },
  AvgDialog_18815_Content_7 = {
    Text = "Il suo tempo sta per scadere."
  },
  AvgDialog_18815_Content_8 = {
    Text = "...Sbrigati a riunirti con gli altri; il capitano potrebbe avere un modo rapido per attraccare."
  },
  AvgDialog_18815_Content_9 = {Text = "Hmm..."},
  AvgDialog_18818_Content_1 = {Text = "Fatto!"},
  AvgDialog_18818_Content_10 = {
    Text = "La bestia grottesca ora abbassa docilmente la testa, come in attesa del tocco della bambina bianca."
  },
  AvgDialog_18818_Content_11 = {
    Text = "Sul collo del gigantesco canide siede, inconfondibilmente, una testa umana coronata, rendendo la scena profondamente inquietante."
  },
  AvgDialog_18818_Content_12 = {Text = "Lily..."},
  AvgDialog_18818_Content_13 = {
    Text = "La ragazza pallida si avvicinò lentamente alla bestia grottesca, estendendo il suo braccio esile per accarezzarle la testa come se stesse coccolando un animale qualunque."
  },
  AvgDialog_18818_Content_14 = {
    Text = "Sul collo del gigantesco canide siede, inconfondibilmente, una testa umana coronata, rendendo la scena profondamente inquietante."
  },
  AvgDialog_18818_Content_15 = {Text = "..."},
  AvgDialog_18818_Content_16 = {
    Text = "Tu e Ramona vi scambiate uno sguardo, mille parole non dette che pesano nei vostri cuori."
  },
  AvgDialog_18818_Content_17 = {
    Text = "Ehi, non starete lì a fissare e basta, vero? Il Segugio infernale è proprio qui."
  },
  AvgDialog_18818_Content_18 = {
    Text = "La mente dietro a tutto ciò che dobbiamo investigare è proprio qui. Come dire? \"È arrivata senza alcuno sforzo\"?"
  },
  AvgDialog_18818_Content_19 = {
    Text = "La bambina, come sorda a Lotan, sussurra nell'orecchio di Koum, la sua voce delicata portata dalla brezza serale."
  },
  AvgDialog_18818_Content_2 = {
    Text = "Ramona balza in avanti. Il mostro messo alle strette ruggisce ferocemente, dibattendosi in un'ultima resistenza."
  },
  AvgDialog_18818_Content_20 = {
    Text = "Koum, fai il bravo. Obbedisci agli ordini della tua padrona.\nSolo chi obbedisce è un bravo bambino."
  },
  AvgDialog_18818_Content_21 = {
    Text = "Le sue parole cadono lievi. Lily si volta e cammina verso di voi."
  },
  AvgDialog_18818_Content_22 = {
    Text = "Lady Daffodil ha detto che se Koum fosse stato scoperto, Lily avrebbe dovuto tornare dalla madre."
  },
  AvgDialog_18818_Content_23 = {
    Text = "Ora, torniamo al negozio.\nLady Daffodil vi racconterà tutto."
  },
  AvgDialog_18818_Content_3 = {
    Text = "<Italic:No, no! Koum, torna indietro!>"
  },
  AvgDialog_18818_Content_4 = {
    Text = "Quella voce... mi suona familiare."
  },
  AvgDialog_18818_Content_5 = {
    Text = "Una piccola figura tremante emerge dalla penombra del lampione spento."
  },
  AvgDialog_18818_Content_6 = {
    Text = "Koum, non far loro del male."
  },
  AvgDialog_18818_Content_7 = {
    Text = "Il grosso canide chiamato \"Koum\" siede a terra, leccandosi docilmente la zampa."
  },
  AvgDialog_18818_Content_8 = {Text = "Koum..."},
  AvgDialog_18818_Content_9 = {
    Text = "Solo ora noti che il volto nero come la pece non è privo di lineamenti; i suoi occhi chiusi, il naso piatto e le labbra appena visibili sono tutti di un nero profondo, creando l'illusione di un'entità senza volto."
  },
  AvgDialog_18819_Content_1 = {
    Text = "Questo è un test di dialogo senza sfondo 1"
  },
  AvgDialog_18819_Content_2 = {
    Text = "Questo è un test di dialogo senza sfondo 2"
  },
  AvgDialog_18820_Content_1 = {
    Text = "L'Orrore del Museo delle Cere"
  },
  AvgDialog_18820_Content_10 = {
    Text = "Andiamo a chiedere a lei."
  },
  AvgDialog_18820_Content_11 = {
    Text = "Dunque, bella e adorabile signorina, possiamo entrare per una visita?"
  },
  AvgDialog_18820_Content_12 = {
    Text = "Questo museo delle cere apre ai visitatori solo nelle giornate nebbiose come questa.\nFinché sarete ospiti educati, potete entrare."
  },
  AvgDialog_18820_Content_13 = {
    Text = "Siete ospiti rispettosi delle regole?"
  },
  AvgDialog_18820_Content_14 = {
    Text = "Certamente."
  },
  AvgDialog_18820_Content_15 = {
    Text = "Quali sono le regole?"
  },
  AvgDialog_18820_Content_16 = {
    Text = "Bene, mi piacciono i clienti che rispettano le regole."
  },
  AvgDialog_18820_Content_17 = {
    Text = "Non preoccuparti, diventerai obbediente. Fidati di me."
  },
  AvgDialog_18820_Content_18 = {
    Text = "Questo è il mio adorato cane, Bobby. Non vorrete farlo arrabbiare, vero?"
  },
  AvgDialog_18820_Content_19 = {
    Text = "<BigShake:Whoa!!!>"
  },
  AvgDialog_18820_Content_2 = {
    Text = "Il Museo delle Cere Ampliato"
  },
  AvgDialog_18820_Content_20 = {
    Text = "La ragazza condusse i tre nella sala e poi si spostò dietro il bancone della reception, assumendo l'atteggiamento di una receptionist."
  },
  AvgDialog_18820_Content_21 = {
    Text = "Questa è l'<Yellow:Area Espositiva 1>."
  },
  AvgDialog_18820_Content_22 = {
    Text = "Ricordo che Dorr ha detto che qualcosa è nascosto qui."
  },
  AvgDialog_18820_Content_23 = {
    Text = "Non abbassare la guardia, Custode. Potrebbe esserci... qualcosa di imprevedibile in agguato."
  },
  AvgDialog_18820_Content_24 = {
    Text = "Che c'è, paura?"
  },
  AvgDialog_18820_Content_25 = {
    Text = "Per niente."
  },
  AvgDialog_18820_Content_26 = {
    Text = "<Small:Hm... Che strano odore.>"
  },
  AvgDialog_18820_Content_27 = {
    Text = "È meglio che tu non lo sappia."
  },
  AvgDialog_18820_Content_28 = {
    Text = "Questa è la <Yellow:Seconda Area Espositiva>."
  },
  AvgDialog_18820_Content_29 = {Text = "..."},
  AvgDialog_18820_Content_3 = {
    Text = "Il Museo delle Cere Ordinario"
  },
  AvgDialog_18820_Content_30 = {
    Text = "<BigShake:Whoa!!!>"
  },
  AvgDialog_18820_Content_31 = {
    Text = "Questo è il nostro <Shake:Capolavoro>. Che ne dite? Non è realistico?"
  },
  AvgDialog_18820_Content_32 = {
    Text = "Quasi identico a una persona vera—"
  },
  AvgDialog_18820_Content_33 = {
    Text = "<Change>Risatina."
  },
  AvgDialog_18820_Content_34 = {Text = "?!"},
  AvgDialog_18820_Content_35 = {
    Text = "Me lo sono immaginato o ha appena sorriso?"
  },
  AvgDialog_18820_Content_36 = {
    Text = "Oh, chissà."
  },
  AvgDialog_18820_Content_37 = {
    Text = "Ecco la <Red:Mappa del Luogo> preparata per voi."
  },
  AvgDialog_18820_Content_38 = {
    Text = "Ora godetevi la visita alla mostra~"
  },
  AvgDialog_18820_Content_4 = {
    Text = "L'Ospizio Ordinario"
  },
  AvgDialog_18820_Content_5 = {
    Text = "Ospizio Ingrandito 1.2x"
  },
  AvgDialog_18820_Content_6 = {
    Text = "L'Ospizio Ordinario"
  },
  AvgDialog_18820_Content_7 = {
    Text = "Questo è... il Museo delle Cere di Rogers?"
  },
  AvgDialog_18820_Content_8 = {
    Text = "E adesso, <Yellow:%player%?>"
  },
  AvgDialog_18820_Content_9 = {
    Text = "Dobbiamo trovare la posizione di \"Primavera\""
  },
  AvgDialog_18823_Content_1 = {
    Text = "Ehi, svegliati!"
  },
  AvgDialog_18823_Content_10 = {
    Text = "Il tempo dei ricordi è finito! Ora passiamo all'evento principale—"
  },
  AvgDialog_18823_Content_11 = {
    Text = "Simulazione del filtro viscoso della D-melma che scorre!"
  },
  AvgDialog_18823_Content_12 = {
    Text = "Questo è un filtro piuttosto lungo, si consiglia di usarlo con più righe di dialogo."
  },
  AvgDialog_18823_Content_13 = {Text = "..."},
  AvgDialog_18823_Content_14 = {Text = "..."},
  AvgDialog_18823_Content_15 = {
    Text = "Bene, il tempo è scaduto! Ora passiamo al nostro modulo meteo—"
  },
  AvgDialog_18823_Content_16 = {
    Text = "Sta nevicando!"
  },
  AvgDialog_18823_Content_17 = {
    Text = "Etciù! Etciù! Oggi non mi sono vestita abbastanza pesante..."
  },
  AvgDialog_18823_Content_18 = {
    Text = "C'è un incendio!"
  },
  AvgDialog_18823_Content_19 = {
    Text = "L'aria è secca, attenzione al rischio di incendi!"
  },
  AvgDialog_18823_Content_2 = {
    Text = "Hmm? Hai chiesto dell'effetto di apertura e chiusura degli occhi di poco fa?"
  },
  AvgDialog_18823_Content_20 = {
    Text = "Sta piovendo!"
  },
  AvgDialog_18823_Content_21 = {
    Text = "Anche il cuore di Hannah diventa un po' malinconico nei giorni di pioggia."
  },
  AvgDialog_18823_Content_22 = {
    Text = "Dopo aver visto così tanti filtri, vi gira un po' la testa?"
  },
  AvgDialog_18823_Content_23 = {
    Text = "Hehe, raddoppiamo la dose e tiriamo fuori il nostro filtro vertigini!"
  },
  AvgDialog_18823_Content_24 = {
    Text = "Com'è? Vi gira la testa... molto la testa..."
  },
  AvgDialog_18823_Content_25 = {
    Text = "Ora aggiungiamo delle rose romantiche! Attivare fiori rossi!"
  },
  AvgDialog_18823_Content_26 = {
    Text = "Non so se sia romantico, ma chi soffre di allergia ai pollini è nei guai, perché —"
  },
  AvgDialog_18823_Content_27 = {
    Text = "Dopo la Rosa Rossa arriva la Rosa Gotica! Attivare, Fiore Nero!"
  },
  AvgDialog_18823_Content_28 = {
    Text = "E poi c'è l'effetto misterioso che lascia tutti perplessi, senza sapere dove usarlo—"
  },
  AvgDialog_18823_Content_29 = {
    Text = "Nebbia di Sangue!"
  },
  AvgDialog_18823_Content_3 = {
    Text = "Ahem, questo è il nostro Filtro Apertura Occhi!"
  },
  AvgDialog_18823_Content_30 = {
    Text = "Sembra piuttosto figo, quindi teniamolo per ora."
  },
  AvgDialog_18823_Content_31 = {
    Text = "Avete visto la Nebbia di Sangue. Ora diamo un'occhiata alla Nebbia Nera."
  },
  AvgDialog_18823_Content_32 = {
    Text = "Buio pesto—sinistro—Londinium come una casa stregata—"
  },
  AvgDialog_18823_Content_33 = {
    Text = "Avete guardato così a lungo che i vostri occhi sono stanchi. Sbattete le palpebre per riposarli."
  },
  AvgDialog_18823_Content_34 = {
    Text = "No, no, così non va. Dovrò procurarmi del collirio più tardi."
  },
  AvgDialog_18823_Content_35 = {
    Text = "Bene, questi sono tutti gli effetti filtro per ora."
  },
  AvgDialog_18823_Content_36 = {
    Text = "Questo episodio della Lezione sui Filtri di Hannah è giunto al termine. Ci rivediamo la prossima volta~!"
  },
  AvgDialog_18823_Content_4 = {
    Text = "Oltre a questo, abbiamo molti altri filtri. Rivediamoli insieme a Hannah!"
  },
  AvgDialog_18823_Content_5 = {
    Text = "Cosa vi viene in mente pensando alla Londra del 1900?"
  },
  AvgDialog_18823_Content_6 = {
    Text = "La risposta è sicuramente la nebbia!"
  },
  AvgDialog_18823_Content_7 = {
    Text = "Una vasta distesa di bianco—evoca in tutti ricordi di un'epoca passata?"
  },
  AvgDialog_18823_Content_8 = {
    Text = "A proposito di ricordi, abbiamo anche un filtro memoria, proprio così!"
  },
  AvgDialog_18823_Content_9 = {
    Text = "Allora? Non sembra un po' come un vecchio film?"
  },
  AvgDialog_18824_Content_1 = {
    Text = "《La Primavera di Botticelli》"
  },
  AvgDialog_18824_Content_10 = {
    Text = "A proposito, queste sono lettere scritte per te da tutti quelli del laboratorio. La signorina Diana mi ha chiesto di consegnartele."
  },
  AvgDialog_18824_Content_11 = {
    Text = "Se hai bisogno di qualcosa qui, non esitare a contattarci. Verrò a trovarti il più spesso possibile.\nAlla prossima, signorina Sarah."
  },
  AvgDialog_18824_Content_12 = {
    Text = "Mentre ti volti verso la porta, senti un debole suono dietro di te."
  },
  AvgDialog_18824_Content_13 = {
    Text = [[
...Mi scusi... Ho notato che non sembra esserci una lettera di Aigis.
Sta... sta bene?]]
  },
  AvgDialog_18824_Content_14 = {Text = "..."},
  AvgDialog_18824_Content_15 = {
    Text = "Il volto di Sarah mostrava un accenno di cauta speranza, mentre accanto a te, Ramona sospirò."
  },
  AvgDialog_18824_Content_16 = {
    Text = "Lei... sta bene."
  },
  AvgDialog_18824_Content_17 = {
    Text = "Date le circostanze particolari, l'abbiamo trasferita all'Ospedale dell'Università di Mythag. Una volta che le sue condizioni si saranno stabilizzate, ti scriverà sicuramente."
  },
  AvgDialog_18824_Content_18 = {
    Text = "Meno male, meno male. Io... temevo che potesse serbarmi rancore."
  },
  AvgDialog_18824_Content_19 = {
    Text = "Quando uscirò di qui, devo farmi perdonare. Pensi che vorrebbe vivere con me? Solo noi due e Jenkin. Sarà felice, vero?"
  },
  AvgDialog_18824_Content_2 = {
    Text = "—Due giorni dopo—"
  },
  AvgDialog_18824_Content_20 = {Text = "Lo sarà?"},
  AvgDialog_18824_Content_21 = {
    Text = "Forse, ma a questo punto, nessuno può garantirlo.\nDopotutto, le persone che avrebbero potuto rispondere a questa domanda non ci sono più."
  },
  AvgDialog_18824_Content_22 = {
    Text = "...Mi dispiace davvero tanto."
  },
  AvgDialog_18824_Content_23 = {
    Text = "No... Io... Non ci posso credere..."
  },
  AvgDialog_18824_Content_24 = {
    Text = "La voce di Sarah cominciò a tremare."
  },
  AvgDialog_18824_Content_25 = {
    Text = "È solo arrabbiata, vero? Si dice che le persone solitamente calme diventino estremamente intense quando si arrabbiano. Anche lei è così, vero?"
  },
  AvgDialog_18824_Content_26 = {
    Text = "Aigis, Aigis... La mia cara Aigis... Perdonami... Perdonami..."
  },
  AvgDialog_18824_Content_27 = {Text = "..."},
  AvgDialog_18824_Content_28 = {Text = "Andiamo."},
  AvgDialog_18824_Content_29 = {
    Text = "Noi... ci vediamo la prossima volta, signorina Sarah."
  },
  AvgDialog_18824_Content_3 = {
    Text = [[
11:41, Londinium
Quartier Generale del Comitato
Sala di Osservazione Sotterranea D-31]]
  },
  AvgDialog_18824_Content_30 = {
    Text = "13:20, Londinium\nUniversità di Mythag"
  },
  AvgDialog_18824_Content_31 = {
    Text = "Tu e Ramona vi addentrate nella fitta foresta fuori dal cancello della scuola e notate Jenkin e una studentessa in uniforme scolastica che si azzuffano a terra."
  },
  AvgDialog_18824_Content_32 = {Text = "..."},
  AvgDialog_18824_Content_33 = {Text = "..."},
  AvgDialog_18824_Content_34 = {
    Text = "Il nostro topolino sta lottando contro il furetto."
  },
  AvgDialog_18824_Content_35 = {
    Text = "Una meraviglia del mondo: i topi attaccano e mordono i furetti!"
  },
  AvgDialog_18824_Content_36 = {
    Text = "Chi stai chiamando topo?!"
  },
  AvgDialog_18824_Content_37 = {
    Text = "Chi stai chiamando furetto?!"
  },
  AvgDialog_18824_Content_38 = {
    Text = "Hannah? Jenkin? Cosa state..."
  },
  AvgDialog_18824_Content_39 = {
    Text = "Non è colpa mia! Ha cominciato lei! È stata lei a chiamare le guardie per prima!"
  },
  AvgDialog_18824_Content_4 = {
    Text = "...Revocate il blocco. La signorina Diana ora è responsabile del laboratorio, e il piccolo Mike è tornato."
  },
  AvgDialog_18824_Content_40 = {
    Text = [[
Ops, le ho solo fatto un piccolo scherzo.
Prendere la vita troppo sul serio la rende noiosa.]]
  },
  AvgDialog_18824_Content_41 = {
    Text = "Quindi la persona che cercava sei tu, giusto? Dove vi siete incontrate, al Laboratorio Lilyan? Dal Macellaio? Ah! È la piccola Jenkin, vero?"
  },
  AvgDialog_18824_Content_42 = {
    Text = "Non c'è da stupirsi che tu sia il miglior ficcanaso del Regno di Leonia. Stai raccogliendo materiale per il giornale scolastico di domani?"
  },
  AvgDialog_18824_Content_43 = {
    Text = "È più di questo. Ramona, mi conosci: le informazioni sono la mia vita."
  },
  AvgDialog_18824_Content_44 = {
    Text = "Dunque, in pieno giorno, una povera orfana si avventura da sola nella foresta profonda. Cosa cerca? Le due persone che sta cercando potranno portarle un po' di luce?"
  },
  AvgDialog_18824_Content_45 = {
    Text = "Hannah tira fuori all'improvviso un taccuino — da dove, non lo sai — e ti guarda con aspettativa, la penna pronta a catturare ogni tua parola e azione."
  },
  AvgDialog_18824_Content_46 = {
    Text = "L'inviata speciale Hannah Peasley sta per iniziare il suo servizio!"
  },
  AvgDialog_18824_Content_47 = {
    Text = "...Ora capisco. Nessuno di voi di questa università del non-so-che parla come una persona normale."
  },
  AvgDialog_18824_Content_48 = {
    Text = "Oh, vi prego, lasciatemi fuori da questa storia."
  },
  AvgDialog_18824_Content_49 = {
    Text = "Per favore, non farci caso. Hannah è semplicemente Hannah. In cosa possiamo aiutarti, Jenkin?"
  },
  AvgDialog_18824_Content_5 = {
    Text = "L'Università di Mythag ha avviato una raccolta fondi per il laboratorio. L'effetto è stato eccellente, e con il supporto del Nobile Dexter, potrà funzionare ancora per un bel po'."
  },
  AvgDialog_18824_Content_50 = {
    Text = "Jenkin fruga nella borsa, tirando fuori una pila di giornali sgualciti, e li porge a te e Ramona."
  },
  AvgDialog_18824_Content_51 = {
    Text = "Avevamo un accordo: avevi promesso di aiutarmi a trovare mia sorella. Ora è il momento di mantenere la promessa."
  },
  AvgDialog_18824_Content_52 = {
    Text = "Ne distende rapidamente una, indicando una curiosità locale: \"Dipinti Tridimensionali\"."
  },
  AvgDialog_18824_Content_53 = {
    Text = "L'articolo allegato, scritto in uno stile drammatico e documentaristico, descrive in dettaglio una stupefacente nuova esposizione al museo delle cere al 44 di Via Southwark: l'ultima opera di Rogers, \"Primavera.\""
  },
  AvgDialog_18824_Content_54 = {
    Text = "Una foto dall'aspetto serio è allegata per dare credibilità."
  },
  AvgDialog_18824_Content_55 = {
    Text = "Si tratta di un gruppo scultoreo di cera ispirato al celebre dipinto di Botticelli. La figura femminile centrale ha un trucco comico e un'espressione chiaramente sofferente."
  },
  AvgDialog_18824_Content_56 = {
    Text = [[
Voglio proteggere tutti, proteggere la signorina Sarah, proteggere il piccolo Mike, proteggere Jenkin.
Non voglio che vengano trasformati in <Yellow:sculture di cera>.]]
  },
  AvgDialog_18824_Content_57 = {
    Text = "Non conosco l'indirizzo, ma ho camminato a lungo, fino al quartiere ovest. In una vetrina c'era una casa. La targhetta diceva <Yellow:N. 44>."
  },
  AvgDialog_18824_Content_58 = {
    Text = "Rogers... una scultura di cera? E a Southwark Street <Yellow:N. 44>, non può essere una coincidenza."
  },
  AvgDialog_18824_Content_59 = {
    Text = "Cos'è? Sai qualcosa?"
  },
  AvgDialog_18824_Content_6 = {
    Text = "Quindi, ora puoi stare tranquilla."
  },
  AvgDialog_18824_Content_60 = {
    Text = "Aigis ha detto—"
  },
  AvgDialog_18824_Content_61 = {Text = "*Coff!*"},
  AvgDialog_18824_Content_62 = {
    Text = "Hai scambiato uno sguardo con Ramona, ma era già troppo tardi.\nSentendo il nome di Aigis, Jenkin si è visibilmente abbattuta."
  },
  AvgDialog_18824_Content_63 = {
    Text = "...Per quanto riguarda Aigis, non essere troppo triste."
  },
  AvgDialog_18824_Content_64 = {
    Text = "Non sono triste. È solo che...\nLe avevo promesso che poteva essere la mia sorellina."
  },
  AvgDialog_18824_Content_65 = {
    Text = "Se l'è svignata, completamente priva di parola."
  },
  AvgDialog_18824_Content_66 = {
    Text = "E quella donna spregevole? Lo sa? Di Aigis..."
  },
  AvgDialog_18824_Content_67 = {Text = "..."},
  AvgDialog_18824_Content_68 = {
    Text = "Lascia perdere; è meglio che non lo sappia. Aigis sicuramente non vorrebbe che si sentisse triste."
  },
  AvgDialog_18824_Content_69 = {
    Text = [[
Allora, cos'hai sentito?
Smettila di girarci intorno, sbrigati! Hai promesso di aiutarmi a trovare qualcuno!]]
  },
  AvgDialog_18824_Content_7 = {
    Text = "Signorina Sarah."
  },
  AvgDialog_18824_Content_70 = {
    Text = "Aigis ha detto che quando era sotto controllo, è andata in un posto nel quartiere ovest con il numero civico <Yellow:44>. In più, \"sono stati trasformati in sculture di cera\"... Le persone scomparse potrebbero essere lì?"
  },
  AvgDialog_18824_Content_71 = {
    Text = "Canaglia... Chiunque tu sia, non la passerai liscia!"
  },
  AvgDialog_18824_Content_72 = {
    Text = "Quando partiamo?"
  },
  AvgDialog_18824_Content_73 = {
    Text = "Dato che è probabilmente molto pericoloso, devo chiedervi di restare indietro mentre risolviamo la questione. Anche se sono certo che avrete altre idee."
  },
  AvgDialog_18824_Content_74 = {
    Text = "Quella è mia sorella. Devo andare! E poi, potreste aver bisogno di me per strisciare attraverso qualche condotto d'aerazione, prima o poi!"
  },
  AvgDialog_18824_Content_75 = {
    Text = "Quest'idea è troppo specifica."
  },
  AvgDialog_18824_Content_76 = {
    Text = "A quanto pare devo presentare una richiesta urgente per un'operazione sul campo."
  },
  AvgDialog_18824_Content_77 = {
    Text = "Stavo giusto per cercare il Professor Alistair; dovrebbe essere felice di farci entrare dalla porta sul retro."
  },
  AvgDialog_18824_Content_78 = {
    Text = "Se parli tu, non dovrebbero esserci problemi. Tuttavia... speriamo che William riesca a ritardare la scadenza per la consegna del nostro rapporto."
  },
  AvgDialog_18824_Content_79 = {
    Text = "Oh, non devi preoccuparti di questo adesso."
  },
  AvgDialog_18824_Content_8 = {
    Text = "Bene, è... è fantastico.\nGrazie mille, Ashe—no, %player%, signorina Ramona."
  },
  AvgDialog_18824_Content_80 = {Text = "?"},
  AvgDialog_18824_Content_81 = {
    Text = "Circa un'ora fa, William ha lasciato la scuola con un permesso per operazioni sul campo."
  },
  AvgDialog_18824_Content_82 = {
    Text = "Ho provato a seguirlo per scovare qualche notizia, ma l'ho perso lungo la strada. Sembrava diretto verso il Distretto Ovest."
  },
  AvgDialog_18824_Content_83 = {
    Text = [[
Southwark Street si trova nel Distretto Ovest.
Sembra che questa volta avremo l'occasione di vedere in azione il rinomato Investigatore William.]]
  },
  AvgDialog_18824_Content_84 = {
    Text = "...Ho sempre la sensazione che mi sgriderà duramente..."
  },
  AvgDialog_18824_Content_85 = {
    Text = "18:24, Londinium Ovest, Via Southwark"
  },
  AvgDialog_18824_Content_86 = {
    Text = "Grazie per la collaborazione. Da qui in poi me ne occupo io."
  },
  AvgDialog_18824_Content_87 = {
    Text = "Non se ne parla, signore. Gli ordini sono chiari: dobbiamo accompagnarla nell'indagine.\nInoltre, Rogers è anche un nostro sospettato; non possiamo lasciarle gestire la cosa da solo."
  },
  AvgDialog_18824_Content_88 = {
    Text = "Inoltre, con noi intorno, la sua identità sarà meglio protetta, giusto?"
  },
  AvgDialog_18824_Content_89 = {Text = "..."},
  AvgDialog_18824_Content_9 = {
    Text = "Stiamo solo facendo del nostro meglio."
  },
  AvgDialog_18824_Content_90 = {
    Text = "Non si preoccupi, signore. Abbiamo armi e gambe veloci. Non saremo un peso."
  },
  AvgDialog_18824_Content_91 = {
    Text = "Capito. Mantenete lo stato di allerta rossa. In caso di compromissione, la vostra vita ha la priorità sul completamento della missione."
  },
  AvgDialog_18824_Content_92 = {
    Text = "Aggiornamento: Raggiunta la posizione obiettivo, Via Southwark 44, Museo delle Cere Rogers. Obiettivo primario: Confermare potenziali legami tra il proprietario del museo, Rogers, e l'Associazione degli Scultori."
  },
  AvgDialog_18824_Content_93 = {
    Text = [[
Posizione confermata, obiettivo dell'indagine identificato.
Che la Chiave d'Argento Illumini il Cammino.]]
  },
  AvgDialog_18824_Content_94 = {
    Text = "Che la Chiave d'Argento ci Guidi."
  },
  AvgDialog_18825_Content_1 = {
    Text = "Ramona avanzò, dirigendosi dritta verso il punto in cui aveva visto la sagoma."
  },
  AvgDialog_18825_Content_10 = {
    Text = "All'improvviso, uno di loro allungò la mano e afferrò il collo della persona accanto. Un grido breve, come olio bollente che colpisce l'acqua, incendiò istantaneamente la folla circostante."
  },
  AvgDialog_18825_Content_11 = {Text = "Indietro!"},
  AvgDialog_18825_Content_2 = {
    Text = "Signorina Mary, q-questo è il cortile esterno. L'avete già visto. Torniamo al percorso originale della visita."
  },
  AvgDialog_18825_Content_3 = {
    Text = "Oh? Ma stavo proprio pensando di fare una passeggiata nel cortile. Mi capite, vero, Signorina Sarah?"
  },
  AvgDialog_18825_Content_4 = {
    Text = "Certo, certo. Capisco perfettamente. Solo, ehm, che ne dite di una tazza di tè prima? Signorina Mary—"
  },
  AvgDialog_18825_Content_5 = {
    Text = "Ignorando le obiezioni di Sarah, Ramona entrò nel cortile anteriore, scrutando con lo sguardo tra i lavoratori immersi nelle loro mansioni."
  },
  AvgDialog_18825_Content_6 = {
    Text = "L'aria è impregnata di sudore e di uno strano odore umido, come carbone che brucia."
  },
  AvgDialog_18825_Content_7 = {
    Text = "Vedete, Signorina Mary, ve l'avevo detto che non c'è niente da vedere qui. Torniamo indietro, presto."
  },
  AvgDialog_18825_Content_8 = {
    Text = [[
Mentre Sarah parlava, diversi lavoratori smisero improvvisamente di lavorare.
Le loro labbra tremavano leggermente, come se sussurrassero qualcosa, e i loro corpi oscillavano dolcemente.]]
  },
  AvgDialog_18825_Content_9 = {
    Text = "Attraverso il monocolo, Ramona vide le loro schiene gonfiarsi gradualmente, con una melma nera che trasudava e strisciava lungo gli arti come se fosse viva."
  },
  AvgDialog_18826_Content_1 = {
    Text = "Nella folla caotica, Ramona fatica a respingere gli attacchi dei lavoratori impazziti, assicurandosi che gli altri lavoratori possano fuggire in sicurezza."
  },
  AvgDialog_18826_Content_2 = {
    Text = "L'inserviente! Chiamate l'inserviente!"
  },
  AvgDialog_18826_Content_3 = {
    Text = "Il suono di passi affrettati si avvicinò. Diverse persone in uniformi speciali si fecero largo tra la folla, con corde in mano ed espressioni serie."
  },
  AvgDialog_18826_Content_4 = {
    Text = "Dietro di loro si ergeva una figura vestita di bianco."
  },
  AvgDialog_18826_Content_5 = {
    Text = "Signorina Mary, attenzione!"
  },
  AvgDialog_18826_Content_6 = {
    Text = "Ramona si spostò di lato, sfruttando lo slancio dell'attacco del lavoratore impazzito per affondare in avanti. Premette la punta della spada nel fodero contro lo sterno, costringendo l'avversario a indietreggiare di qualche passo."
  },
  AvgDialog_18826_Content_7 = {
    Text = "Dietro di lei, gli inservienti si fermarono."
  },
  AvgDialog_18826_Content_8 = {
    Text = "Ti copro io. Preparati."
  },
  AvgDialog_18827_Content_1 = {
    Text = "Nebbia insanguinata"
  },
  AvgDialog_18827_Content_10 = {
    Text = "Vedendo l'espressione leggermente confusa sul volto di Aigis, Jenkin emise un profondo sospiro, prese la pesante teiera dal vassoio, la avvolse in un panno e la tenne in mano."
  },
  AvgDialog_18827_Content_11 = {
    Text = "Jenkin, la Signorina Sarah si arrabbierà se ci giochi..."
  },
  AvgDialog_18827_Content_12 = {
    Text = [[
Chi sta giocando? Ti sto aiutando!
Andiamo, andiamo, sbrigati! Prima finiamo, prima possiamo concludere!]]
  },
  AvgDialog_18827_Content_13 = {Text = "Mm, mm!"},
  AvgDialog_18827_Content_14 = {
    Text = [[
20:27, Laboratorio di Lily
Cortile anteriore]]
  },
  AvgDialog_18827_Content_15 = {
    Text = "...Quindi hai davvero creduto a quella ragazza e hai intenzione di aspettare qui per una specie di ombra oscura?"
  },
  AvgDialog_18827_Content_16 = {
    Text = "Considerando i D-marchi anomali avvistati nella Zanna e il \"Ricercatore\" scomparso, fare la guardia sembra una buona idea."
  },
  AvgDialog_18827_Content_17 = {
    Text = "...Va bene, è il tuo tempo che stai sprecando.\nTornando all'argomento, qualche segno di Cladi nel laboratorio?"
  },
  AvgDialog_18827_Content_18 = {
    Text = "La Chiave d'argento non mostra alcuna reazione. Presumo che la forma di vita sconosciuta non sia un Cataclisma di recente formazione, ma sia più probabilmente collegata a Marchi-D Speciali e a quel \"Ricercatore.\""
  },
  AvgDialog_18827_Content_19 = {
    Text = [[
Non ho mai visto un D-marchio come questo. Sembra persino una specie di maldestro tentativo di sutura.
E il suo siero per controllare le mutazioni... Onestamente, dubito che possa interferire con la Dissoluzione.]]
  },
  AvgDialog_18827_Content_2 = {
    Text = [[
20:27, Laboratorio di Lily
Mensa]]
  },
  AvgDialog_18827_Content_20 = {
    Text = "Nessun Cataclisma, ma c'è la Dissoluzione, un D-segno cucito... Che siano loro?"
  },
  AvgDialog_18827_Content_21 = {
    Text = "Lettura della parola chiave riuscita, \"D-marchio suturato,\" con un totale di 37 incidenti correlati.\nParole chiave dell'evento: <Blue:Attività di organizzazione malevola, Gli scultori>."
  },
  AvgDialog_18827_Content_22 = {
    Text = "Non erano stati eliminati 14 anni fa nell'operazione congiunta tra Mythag e il <Blue:Comitato>?"
  },
  AvgDialog_18827_Content_23 = {
    Text = "L'operazione iniziale ebbe un intoppo, permettendo ai loro membri chiave di fuggire. Dopo tutti questi anni, la squadra investigativa non è ancora riuscita a rintracciarli. Inaspettatamente, li incontriamo qui."
  },
  AvgDialog_18827_Content_24 = {
    Text = "La natura della situazione è cambiata. Dovresti prepararti a ritirarti.\nRicorda, non agire avventatamente, o sarò la prima a darti un addestramento extra."
  },
  AvgDialog_18827_Content_25 = {
    Text = "Aspetta, Doll—"
  },
  AvgDialog_18827_Content_26 = {
    Text = "La Professoressa Doll se n'è andata. Desidera lasciare un messaggio?"
  },
  AvgDialog_18827_Content_27 = {
    Text = "Autoritaria come sempre in laboratorio.\nNon c'è bisogno di lasciare un messaggio. Grazie, Erica."
  },
  AvgDialog_18827_Content_28 = {
    Text = "Il comunicatore tace. Guardi Ramona e vedi la stessa emozione riflessa nei suoi occhi."
  },
  AvgDialog_18827_Content_29 = {
    Text = "Questa è la nostra missione."
  },
  AvgDialog_18827_Content_3 = {
    Text = "Proprio non capisco. Aiuti in cucina e porti i pasti a Rogers.\nTi piace davvero così tanto lavorare? Non ti riposi mai."
  },
  AvgDialog_18827_Content_30 = {
    Text = "L'indagine che abbiamo iniziato deve essere portata a termine da noi."
  },
  AvgDialog_18827_Content_31 = {
    Text = "Non possiamo andarcene."
  },
  AvgDialog_18827_Content_32 = {
    Text = "Sai che sosterrò sempre la tua decisione, qualunque essa sia.\nMi fido di te, %player%."
  },
  AvgDialog_18827_Content_33 = {
    Text = "Se riusciamo a trovare qualcosa prima dell'evacuazione, Doll potrebbe lasciarsi convincere."
  },
  AvgDialog_18827_Content_34 = {
    Text = "Mostriamole fin dove possiamo arrivare."
  },
  AvgDialog_18827_Content_35 = {
    Text = [[
20:35, Laboratorio di Lily
Ccorridoio]]
  },
  AvgDialog_18827_Content_36 = {
    Text = "Fino a che punto sei disposta ad arrivare per quel piccolo Mike? Non rinunciare alla tua cena ogni volta che dice di avere fame!"
  },
  AvgDialog_18827_Content_37 = {
    Text = "Non fa niente se salto qualche pasto. Il piccolo Mike è così giovane; ha bisogno di mangiare di più per restare in salute e non ammalarsi."
  },
  AvgDialog_18827_Content_38 = {
    Text = "Ti credi tanto brava? Se non avessi rubato i soldi di %player% per comprarti caramelle e pane, chissà per quanto tempo avresti patito la fame!"
  },
  AvgDialog_18827_Content_39 = {
    Text = "Ma è molto educato. Dopo aver mangiato, mi chiama felice \"Sorella\" e mi ha persino fatto un regalo!"
  },
  AvgDialog_18827_Content_4 = {
    Text = "Jenkin si appoggiò al lato del tavolo da pranzo, osservando Aigis e diversi assistenti e cuochi indaffarati al lavoro."
  },
  AvgDialog_18827_Content_40 = {
    Text = "Non è bello? Gliel'ha dato un fratello maggiore gentile che chiedeva indicazioni l'altro ieri. Tutti sono così invidiosi.\nE indovina un po'? Il piccolo Mike ha anche detto—"
  },
  AvgDialog_18827_Content_41 = {
    Text = "Uno per me, uno per te. Saremo sempre le migliori amiche!"
  },
  AvgDialog_18827_Content_42 = {
    Text = "...Tch, chi se ne importa. Quando troverò mia sorella, ce ne andremo insieme. Poi tu sarai mia sorella, e ti darò due sorelle!"
  },
  AvgDialog_18827_Content_43 = {Text = "...Aigis?"},
  AvgDialog_18827_Content_44 = {
    Text = "<Small:La nebbia... sta salendo di nuovo... com'è possibile... proprio oggi... la nebbia è tornata...>"
  },
  AvgDialog_18827_Content_45 = {
    Text = "Hmm? È vero. Non c'erano così tante giornate nebbiose negli anni passati. Il tempo è stato piuttosto strano ultimamente."
  },
  AvgDialog_18827_Content_46 = {
    Text = "Mi ricorda la notte in cui ci siamo incontrate per la prima volta."
  },
  AvgDialog_18827_Content_47 = {
    Text = [[
20:35, Laboratorio di Lily
Cortile Anteriore]]
  },
  AvgDialog_18827_Content_48 = {
    Text = "Questo tempo... Quel sopravvissuto non aveva forse detto che anche la notte del loro incidente era calata improvvisamente la nebbia?"
  },
  AvgDialog_18827_Content_49 = {
    Text = "La debole luce della torcia non riesce a penetrare la foschia. Tutto intorno a te appare in ombra, e riesci a malapena a distinguere il cancello di ferro vicino."
  },
  AvgDialog_18827_Content_5 = {
    Text = "Volevo fare di più, ma... ma sono così inutile. Queste faccende sono tutto ciò che riesco a gestire..."
  },
  AvgDialog_18827_Content_50 = {
    Text = "Un'ombra guizzò oltre, destando la nebbia addormentata."
  },
  AvgDialog_18827_Content_51 = {
    Text = "Quello è...!"
  },
  AvgDialog_18827_Content_52 = {
    Text = "Il cancello di ferro ben chiuso emette un suono stridulo. Tu e Ramona vi lanciate all'inseguimento, solo per vedere il cancello aperto e la strada oltre, avvolta nella nebbia notturna."
  },
  AvgDialog_18827_Content_53 = {
    Text = "Presto, inseguiamolo!"
  },
  AvgDialog_18827_Content_6 = {
    Text = "Ci risiamo. Chi ti ha detto che sei inutile?"
  },
  AvgDialog_18827_Content_7 = {
    Text = "Questa bambina è così da quando è arrivata al laboratorio e non ascolta qualsiasi cosa le si dica."
  },
  AvgDialog_18827_Content_8 = {
    Text = "Diana sorrise mentre porgeva il vassoio con il servizio da tè e gli spuntini ad Aigis, poi accarezzò la testa di Jenkin."
  },
  AvgDialog_18827_Content_9 = {
    Text = "Quindi, se riuscirà a smettere di essere così dura con se stessa dipende da te, piccolo Jenkin."
  },
  AvgDialog_18828_Content_1 = {
    Text = "Non abbiamo davvero intenzione di fermarli? Se appartengono all'\"Associazione degli Scultori\"..."
  },
  AvgDialog_18828_Content_2 = {
    Text = "Valutiamo la situazione e adattiamoci di conseguenza. Se li mettiamo in allarme, sarà molto più difficile catturarli."
  },
  AvgDialog_18829_Content_1 = {Text = "Giù!"},
  AvgDialog_18829_Content_10 = {
    Text = "È davvero possibile? È incredibilmente versatile!"
  },
  AvgDialog_18829_Content_11 = {
    Text = "In ogni caso, dobbiamo provare. La tratterrò e attenderò il tuo comando."
  },
  AvgDialog_18829_Content_12 = {
    Text = "Pronti... Via!"
  },
  AvgDialog_18829_Content_3 = {
    Text = "La lama fende l'aria, sollevando una raffica alle tue spalle. Ramona fa un passo di lato, blocca un colpo d'artiglio con la spada, e poi ti spinge con forza verso le scale."
  },
  AvgDialog_18829_Content_5 = {
    Text = "Sarah impazzita ti segue nel seminterrato. Il suo stocco si scontra con il muco nero indurito, producendo un forte stridio metallico."
  },
  AvgDialog_18829_Content_6 = {
    Text = "Ti volti e, con Ramona che alza lo stocco, indietreggi cautamente più in profondità nella stanza."
  },
  AvgDialog_18829_Content_7 = {
    Text = "Erica! Un Mutante da Dissoluzione speciale, conserva una forma umanoide tranne che per la testa e possiede intelligenza. Si sospetta sia indotto da onde Spirituali innescate dalle emozioni. Soluzione?"
  },
  AvgDialog_18829_Content_8 = {
    Text = "Recupero in corso, attendere prego."
  },
  AvgDialog_18829_Content_9 = {
    Text = "Oltre ad eliminare i Mutanti, la Chiave d'argento può essere utilizzata per influenzare la psiche dei Mutanti e dei Mutanti speciali."
  },
  AvgDialog_18830_Content_1 = {
    Text = "Signorina Sarah—Signorina Sarah, si svegli! Mi guardi, Signorina Sarah—"
  },
  AvgDialog_18830_Content_2 = {
    Text = [[
Questa mutazione sembra essere innescata da emozioni intense e conserva un certo livello di intelligenza. 
Non ho mai assistito a un comportamento simile, completamente diverso dagli altri mutanti.]]
  },
  AvgDialog_18830_Content_3 = {
    Text = "Che Mutante, che cosa, che diavolo!"
  },
  AvgDialog_18830_Content_4 = {
    Text = "Fate attenzione a non lasciarla scappare; sarebbe un problema se incontrasse gente comune."
  },
  AvgDialog_18830_Content_5 = {
    Text = "Vai nel seminterrato che abbiamo appena visitato e vedi se riesci a trovare un modo per calmarla."
  },
  AvgDialog_18830_Content_6 = {
    Text = "Signorina Sarah! Per favore, non fate del male alla Signorina Sarah!"
  },
  AvgDialog_18830_Content_7 = {
    Text = "Jenkin, porta via Aigis, subito!"
  },
  AvgDialog_18830_Content_8 = {
    Text = "Dannazione, tocca sempre a me. Aigis! Sbrigati!"
  },
  AvgDialog_18830_Content_9 = {
    Text = "Signorina Sarah—!"
  },
  AvgDialog_18831_Content_1 = {
    Text = "Pericolo Interiore"
  },
  AvgDialog_18831_Content_10 = {
    Text = "Jenkin, non spaventarmi. Io... ho paura. Puoi tornare indietro? Oppure, posso venire con te? Jenkin—"
  },
  AvgDialog_18831_Content_11 = {
    Text = [[
La porta si chiuse silenziosamente, lasciando la ragazza e il topo all'interno.
Aigis sedeva sul letto, tremando in modo incontrollabile.]]
  },
  AvgDialog_18831_Content_12 = {
    Text = "Perché... Anche se qualcuno è già venuto oggi... perché di nuovo... perché...!"
  },
  AvgDialog_18831_Content_13 = {
    Text = "Le lacrime scesero lungo le guance, bagnando le lenzuola per l'ennesima volta quella notte.\nFuori, la nebbia oscurò gradualmente la luna piena, avvolgendo tutto in un velo fioco e sfocato."
  },
  AvgDialog_18831_Content_14 = {
    Text = "Cosa dovrei fare... Cosa devo fare, cosa devo sacrificare... per"
  },
  AvgDialog_18831_Content_15 = {
    Text = [[
00:17, Laboratorio di Lily
Stanza degli ospiti]]
  },
  AvgDialog_18831_Content_16 = {Text = "..."},
  AvgDialog_18831_Content_17 = {
    Text = "...Che...cos'è questo suono...?"
  },
  AvgDialog_18831_Content_18 = {
    Text = "Come ho fatto ad addormentarmi?"
  },
  AvgDialog_18831_Content_19 = {
    Text = [[
Ricordo di aver parlato con Sarah, e poi mi sono addormentata...
Ramona, Ramona?]]
  },
  AvgDialog_18831_Content_2 = {
    Text = [[
00:14, Laboratorio di Lily
Stanza di Aigis]]
  },
  AvgDialog_18831_Content_20 = {
    Text = "Non senti alcuna risposta e puoi solo muovere lentamente le membra pesanti, cercando di concentrarti per osservare ciò che ti circonda."
  },
  AvgDialog_18831_Content_21 = {
    Text = "La serratura della porta si era allentata e la porta era leggermente socchiusa, lasciando entrare il vento freddo della notte attraverso lo spiraglio buio."
  },
  AvgDialog_18831_Content_22 = {
    Text = "Un'ombra guizza da dietro i mobili, attaccando all'istante."
  },
  AvgDialog_18831_Content_24 = {Text = "!"},
  AvgDialog_18831_Content_25 = {
    Text = [[
La lama affilata riflette un bagliore freddo, la sua corta lunghezza rispecchia il tuo volto.
I riflessi allenati ti fanno schivare appena in tempo, rivelando la figura dell'aggressore.]]
  },
  AvgDialog_18831_Content_26 = {Text = "Jenkin?!"},
  AvgDialog_18831_Content_27 = {
    Text = "Gli occhi della ragazza erano privi di colore, la sua espressione così spenta da sembrare stordita. Non reagiva ai tuoi richiami, come se non fosse in grado di percepire nulla."
  },
  AvgDialog_18831_Content_28 = {
    Text = "Allo stesso tempo, i suoi movimenti erano eccezionalmente agili. La lama tracciava un arco gelido nell'aria, senza lasciarti il tempo di pensare. La ragazza si lanciò di nuovo contro di te."
  },
  AvgDialog_18831_Content_29 = {
    Text = "Schiva immediatamente"
  },
  AvgDialog_18831_Content_3 = {
    Text = "Il chiaro di luna che riempiva la stanza divenne improvvisamente sfocato, come se fosse velato da uno strato di nebbia.\nUna persona si alzò bruscamente dal letto, disturbando la tranquillità della stanza."
  },
  AvgDialog_18831_Content_30 = {
    Text = "Ramona, svegliati!"
  },
  AvgDialog_18831_Content_31 = {
    Text = "Torni indietro verso Ramona e le scuoti vigorosamente le spalle."
  },
  AvgDialog_18831_Content_32 = {
    Text = "Come...? Cosa sta succedendo?"
  },
  AvgDialog_18831_Content_33 = {
    Text = "È Jenkin! Mi ha attaccata all'improvviso!"
  },
  AvgDialog_18831_Content_34 = {
    Text = "Risveglia Ramona"
  },
  AvgDialog_18831_Content_35 = {
    Text = "Dannazione, di questo passo..."
  },
  AvgDialog_18831_Content_36 = {
    Text = "Chiudi gli occhi e ti concentri. La Chiave d'Argento sul tuo petto emette un debole bagliore."
  },
  AvgDialog_18831_Content_37 = {
    Text = "Il legame formato dal vincolo spirituale risponde all'evocatore, anche attraverso grandi distanze o tra il mondo della veglia e le città dei sogni"
  },
  AvgDialog_18831_Content_38 = {Text = "Ramona!"},
  AvgDialog_18831_Content_4 = {Text = "...Jenkin?"},
  AvgDialog_18831_Content_40 = {
    Text = "Le lame si scontrarono quando Ramona bloccò il pugnale. Inclinò leggermente la testa, lanciando un'occhiata con la coda dell'occhio per assicurarsi che fossi al sicuro."
  },
  AvgDialog_18831_Content_41 = {Text = "Stai bene?"},
  AvgDialog_18831_Content_42 = {
    Text = "Ti sei svegliata appena in tempo."
  },
  AvgDialog_18831_Content_43 = {Text = "Jenkin?"},
  AvgDialog_18831_Content_44 = {
    Text = "Jenkin non rispose, semplicemente alzò di nuovo il pugnale."
  },
  AvgDialog_18831_Content_45 = {
    Text = "Sembra che dovremo prima sottometterla. Attirala fuori!"
  },
  AvgDialog_18831_Content_5 = {
    Text = "Il fruscio dei vestiti fu la sua unica risposta. Strofinandosi gli occhi gonfi, Aigis vide Jenkin saltare giù dal letto e dirigersi verso la porta."
  },
  AvgDialog_18831_Content_6 = {
    Text = "Squiit? Squiit squiit!"
  },
  AvgDialog_18831_Content_7 = {
    Text = "Jenkin, stai... andando in bagno?"
  },
  AvgDialog_18831_Content_8 = {
    Text = "Apparentemente ignorando la domanda della sua compagna e gli squittii ansiosi del suo topolino, Jenkin aprì la porta con lo zaino in spalla, l'espressione completamente vuota."
  },
  AvgDialog_18831_Content_9 = {
    Text = "Il volto di Aigis impallidì all'istante."
  },
  AvgDialog_18832_Content_1 = {
    Text = "Nell'oscurità, una piccola figura bianca è rannicchiata."
  },
  AvgDialog_18832_Content_10 = {
    Text = [[
Arrenditi, chiudi gli occhi e lascia tutto a me.
Sarah, il piccolo Mike... tutti nel tuo laboratorio diventeranno bellezza, eterna e imperitura.]]
  },
  AvgDialog_18832_Content_100 = {
    Text = "Il nastro legato alla sua mano si scioglie e si invola lontano. Il piccolo corpo della ragazza cade, scomparendo per sempre nella notte."
  },
  AvgDialog_18832_Content_101 = {
    Text = "Il vestito bianco vuoto e i quadratini di carta sparsi si posano delicatamente nella mano di Jenkin."
  },
  AvgDialog_18832_Content_102 = {
    Text = "Non resta nemmeno una traccia di calore."
  },
  AvgDialog_18832_Content_103 = {
    Text = "Ai... Aigis...?"
  },
  AvgDialog_18832_Content_104 = {
    Text = "Una farfalla dorata è disegnata sulla carta, con i bordi stropicciati accuratamente spianati. Porta persino un lieve sentore di dolcezza zuccherina."
  },
  AvgDialog_18832_Content_105 = {
    Text = "Come... com'è possibile..."
  },
  AvgDialog_18832_Content_106 = {
    Text = "Il nastro cremisi e l'involucro della caramella cadono nella mano di Jenkin, sfiorandole le dita come una tenera carezza."
  },
  AvgDialog_18832_Content_107 = {
    Text = "Sbatte le palpebre, le lacrime le offuscano la visuale e scivolano dalle ciglia, catturate in silenzio da quel rosso vivido."
  },
  AvgDialog_18832_Content_108 = {Text = "Aigis..."},
  AvgDialog_18832_Content_11 = {
    Text = "No, no...! Per favore, non farlo, non puoi!"
  },
  AvgDialog_18832_Content_12 = {
    Text = "Quel topolino è tua amica, vero? Dato che mi hai aiutato a raccogliere così tanti materiali, posso dare la priorità a renderla eterna e libera dal dolore."
  },
  AvgDialog_18832_Content_13 = {
    Text = "No! Non far loro del male! Per favore! Farò qualsiasi cosa, assolutamente qualsiasi cosa!"
  },
  AvgDialog_18832_Content_14 = {
    Text = "Una volta lo supplicai allo stesso modo, ma poi—arrivai a comprendere i suoi ideali.\nSicuramente, anche tu arriverai a comprendere i miei. Dopotutto, che altra scelta hai?"
  },
  AvgDialog_18832_Content_15 = {Text = "Io—"},
  AvgDialog_18832_Content_16 = {
    Text = "Resistere? Il tuo spirito è quasi spezzato. Se non lo fosse, non potrei influenzarti mentre sei sveglia."
  },
  AvgDialog_18832_Content_17 = {
    Text = "Perché non ti arrendi? E mi aiuti a trasformare tutti qui in materiali preziosi."
  },
  AvgDialog_18832_Content_18 = {
    Text = "Un'enorme figura si immobilizzò in lontananza. Estraesti rapidamente la Chiave d'argento e la lanciasti in aria, ignorando le proteste di Doll e Ramona."
  },
  AvgDialog_18832_Content_19 = {
    Text = "La Chiave d'argento fluttua nell'aria, emettendo una luce tenue. Chiudi gli occhi e sprofondi in un'oscurità gelida."
  },
  AvgDialog_18832_Content_2 = {
    Text = "Il vecchio Charlie aveva un gatto soriano che amava tantissimo. Un giorno, lei scomparve, e lui la cercò ovunque..."
  },
  AvgDialog_18832_Content_20 = {
    Text = [[
Mentre le innumerevoli luci argentee si ritirano, un bagliore particolarmente fioco fluttua davanti a te.
Ascolti attentamente e ti sembra di udire il sussurro di una ragazza.]]
  },
  AvgDialog_18832_Content_21 = {
    Text = [[
Voglio proteggere tutti, proteggere la signorina Sarah, proteggere il piccolo Mike e proteggere Jenkin.
Non voglio che vengano trasformati in sculture di cera.]]
  },
  AvgDialog_18832_Content_22 = {
    Text = "Li proteggerò, anche a costo di tutto ciò che ho—"
  },
  AvgDialog_18832_Content_23 = {
    Text = "Provi a toccare il piccolo puntino, e la Chiave d'argento vibra in risposta."
  },
  AvgDialog_18832_Content_24 = {
    Text = "...Cos'è questo?"
  },
  AvgDialog_18832_Content_25 = {
    Text = "La ragazza sollevò il viso e vide una piccola chiave d'argento apparire davanti a lei, che ruotava lentamente emettendo una luce tenue ma abbagliante come una stella."
  },
  AvgDialog_18832_Content_26 = {
    Text = "Si sforzò di muovere il braccio, puntandolo sotto il corpo. \nL'oscurità la avvolgeva da ogni direzione, premendola e inchiodandola sul posto."
  },
  AvgDialog_18832_Content_27 = {
    Text = "Piccolo congegno speciale. Non muoverti, Aigis. Non voglio perdere uno strumento utile come te.\nSe continui così, non rivedrai mai più i tuoi compagni. Ti sta bene?"
  },
  AvgDialog_18832_Content_28 = {
    Text = "Non ascolterò... Non ascolterò mai più."
  },
  AvgDialog_18832_Content_29 = {
    Text = "Anche se non potrò mai più mangiare caramelle, vedere le persone del laboratorio, o vedere Jenkin.\nAnche se dovessi morire."
  },
  AvgDialog_18832_Content_3 = {
    Text = "La prossima volta ci riuscirò! Frugò nell'armadio e guardò sotto il letto."
  },
  AvgDialog_18832_Content_30 = {
    Text = "Non ti permetterò mai più di far loro del male, mai."
  },
  AvgDialog_18832_Content_31 = {
    Text = "La Chiave d'Argento tremola intensamente mentre la bambina sorregge il proprio corpo. Senti qualcosa debolmente, qualcosa che viene lacerato."
  },
  AvgDialog_18832_Content_32 = {
    Text = "La benda scivola giù, colori sinuosi rimpiazzano l'oscurità, e un enorme occhio pallido appare sotto di lei, come se la osservasse da tempo immemorabile."
  },
  AvgDialog_18832_Content_33 = {
    Text = "Tu sei... gli occhi?"
  },
  AvgDialog_18832_Content_34 = {
    Text = [[
Puoi davvero prestarmi il tuo potere?
...Va bene, anche se fosse solo per un istante, io... ho qualcosa da dire loro.]]
  },
  AvgDialog_18832_Content_35 = {Text = "Grazie..."},
  AvgDialog_18832_Content_36 = {
    Text = "Aigis si muove e apre davvero gli occhi."
  },
  AvgDialog_18832_Content_37 = {
    Text = "Dopo un grido lacerante, il corpo massiccio del Mostro si dissolve in melma nera e crolla su se stesso. La melma si riduce in polvere, sollevandosi a oscurare le travi di legno."
  },
  AvgDialog_18832_Content_38 = {
    Text = "Crolli debolmente a terra, sopportando a malapena il dolore pulsante alla testa e la nausea che ne consegue."
  },
  AvgDialog_18832_Content_39 = {Text = "%player%!"},
  AvgDialog_18832_Content_4 = {
    Text = "Piccola Aigis, guarda cosa ti ho fatto! Non è più carina questa benda sull'occhio dell'ultima?"
  },
  AvgDialog_18832_Content_40 = {
    Text = "Hai esaurito il tuo potere spirituale, vero? Ti avevo detto di non fare sciocchezze.\nIl lavoro sul campo non è come la scuola; se ti succede qualcosa, nessuno verrà a sistemare il pasticcio."
  },
  AvgDialog_18832_Content_41 = {
    Text = "Non preoccuparti per me, controlla Aigis."
  },
  AvgDialog_18832_Content_42 = {
    Text = [[
Il suono del liquido che evapora si affievolisce gradualmente e presto svanisce del tutto.
Sul pavimento macchiato di melma nera, la ragazza siede in silenzio.]]
  },
  AvgDialog_18832_Content_43 = {
    Text = "Signorina Ramona... e... %player%.\nSono così felice che siate entrambi al sicuro."
  },
  AvgDialog_18832_Content_44 = {
    Text = "Scusatemi, davvero scusatemi. Se avessi parlato prima e ammesso tutto prima, forse tutto sarebbe già finito."
  },
  AvgDialog_18832_Content_45 = {
    Text = "Non ho fatto del male a nessun altro, vero? Io... sono riuscita a resistere, vero?"
  },
  AvgDialog_18832_Content_46 = {
    Text = "Sì, sei stata coraggiosa e straordinaria. Hai protetto tutti al laboratorio."
  },
  AvgDialog_18832_Content_47 = {
    Text = "Meno male... In tal caso, resta solo una cosa da fare.\nVi dirò tutto quello che so."
  },
  AvgDialog_18832_Content_48 = {
    Text = "<Small:Devo... sbrigarmi...>"
  },
  AvgDialog_18832_Content_49 = {
    Text = "Da un giorno imprecisato, quella voce misteriosa è arrivata.\nViene sempre nelle notti di nebbia, si insinua nelle nostre menti e ci fa fare cose cattive."
  },
  AvgDialog_18832_Content_5 = {
    Text = "Aigis, Aigis! Oggi c'è il sole, quindi potremo sicuramente vedere le stelle!"
  },
  AvgDialog_18832_Content_50 = {
    Text = "La prima volta che me ne sono accorta è stata una notte in cui mi sono alzata per andare in bagno. La piccola Lucy teneva in mano un coltello. L'ho vista nasconderlo nell'armadio e poi infilarsi dritta a letto."
  },
  AvgDialog_18832_Content_51 = {
    Text = "Avevo paura che la sgridassero per il pigiama sporco, così le ho cambiato i vestiti e le lenzuola. Si è svegliata e mi ha chiesto perché li stessi cambiando, come se... non avesse idea di quello che aveva fatto."
  },
  AvgDialog_18832_Content_52 = {
    Text = "Sono terrorizzata. Voglio dirlo alla signorina Sarah, ma ho paura che punisca Lucy. Ho ancora più paura che non mi creda..."
  },
  AvgDialog_18832_Content_53 = {
    Text = "Così, alla fine non ho detto nulla."
  },
  AvgDialog_18832_Content_54 = {
    Text = "Dopo quello che è successo con Lucy, non è accaduto nulla per diverse notti. Pensavo fosse finita, ma un giorno mi sono svegliata con un coltello in mano."
  },
  AvgDialog_18832_Content_55 = {
    Text = "Una sorella maggiore è crollata davanti a me. Piange e implora pietà. Voglio fermarmi, ma..."
  },
  AvgDialog_18832_Content_56 = {
    Text = "Non ci riesco."
  },
  AvgDialog_18832_Content_57 = {
    Text = "Finché quella voce canta, non ci riesco."
  },
  AvgDialog_18832_Content_58 = {
    Text = "La voce ha notato che ero ancora \"sveglia\" ed era entusiasta. Ha detto che avevo del potenziale e mi ha ordinato di obbedire, altrimenti avrebbe trasformato tutti in pietra, usandoli come suo \"materiale\"."
  },
  AvgDialog_18832_Content_59 = {
    Text = "Ho detto che l'avrei detto alla signorina Sarah, ma ha solo riso e mi ha detto di provare a vedere se qualcuno mi avrebbe creduto."
  },
  AvgDialog_18832_Content_6 = {
    Text = "Aigis, va bene essere un po' capricciosa ogni tanto. Lo capisci?"
  },
  AvgDialog_18832_Content_60 = {
    Text = "La voce ha ragione; sembra avere sempre ragione riguardo alle cose brutte."
  },
  AvgDialog_18832_Content_61 = {
    Text = "Nessuno mi crede, nessuno ricorda cosa succede di notte. Ma nelle notti di nebbia, ogni volta che quella canzone riecheggia nelle nostre teste, i bambini vengono controllati dal suono e lasciano la Zanna."
  },
  AvgDialog_18832_Content_62 = {
    Text = "Ogni bambino che torna è coperto di sangue. Ogni bambino controllato è uno \"smembratore\".\nAlcuni sono persino più piccoli di me. Se venissero davvero presi dalla polizia..."
  },
  AvgDialog_18832_Content_63 = {
    Text = "Non posso permettere che accada."
  },
  AvgDialog_18832_Content_64 = {
    Text = "Così ho nascosto tutti gli oggetti macchiati di sangue nel cortile sul retro. Non riuscivo a resistere alle voci, ma almeno potevo impedire che venissero portati via dalla polizia."
  },
  AvgDialog_18832_Content_65 = {
    Text = "Perché le voci vogliono che tagliamo i corpi delle altre persone? Non lo so. So solo che quello che tagliamo viene mandato in una vetrina nel distretto ovest, messo davanti alla casa di qualcuno."
  },
  AvgDialog_18832_Content_66 = {
    Text = "La sorella di Jenkin... Anch'io l'ho portata lì, in una casa con una porta contrassegnata dal <Blue:N. 44>."
  },
  AvgDialog_18832_Content_67 = {
    Text = "Stava ancora piangendo quando me ne sono andata. Volevo consolarla, ma potevo solo essere controllata per tornare al laboratorio.\nAnche se sono uscita di nuovo a cercarla non appena ho potuto muovermi, quando sono arrivata, era già scomparsa."
  },
  AvgDialog_18832_Content_68 = {
    Text = "È scomparsa, insieme al fratello maggiore che avevo trasformato in pietra quella notte."
  },
  AvgDialog_18832_Content_69 = {
    Text = "Non so se siano ancora vivi. Se li trovate, potreste scusarvi con loro da parte mia?"
  },
  AvgDialog_18832_Content_7 = {
    Text = "Aigis! Ta-da—Pane! Non sono brava?"
  },
  AvgDialog_18832_Content_70 = {
    Text = "Se non fosse stato per me, loro non avrebbero... e Jenkin non sarebbe così triste.\nIo... devo davvero delle scuse a lei, a loro, a tutti."
  },
  AvgDialog_18832_Content_71 = {Text = "Aigis..."},
  AvgDialog_18832_Content_73 = {
    Text = "Aigis fissò l'ombra proiettata davanti a lei, una luce fioca che tremolava nei suoi occhi."
  },
  AvgDialog_18832_Content_74 = {
    Text = "Come vorrei, come vorrei poter ricominciare da capo... Se solo potessi, sicuramente..."
  },
  AvgDialog_18832_Content_76 = {
    Text = "La sua Visuale offuscata si schiarisce. Contemplando strade familiari e sconosciute, qualcuno sembra sussurrarle all'orecchio."
  },
  AvgDialog_18832_Content_77 = {
    Text = "La ragazza sbatté le palpebre e accennò un sorriso nostalgico."
  },
  AvgDialog_18832_Content_78 = {
    Text = "Lo sapevate? Nei giorni in cui si poteva vedere il sole, Tiyug mi portava di nascosto quassù di notte."
  },
  AvgDialog_18832_Content_79 = {
    Text = "La signorina Sarah non ci permetteva mai di venire qui. Diceva che era troppo pericoloso e che potevamo facilmente farci male."
  },
  AvgDialog_18832_Content_8 = {
    Text = "La ragazza si rannicchiò, stringendo il suo orsacchiotto.\nLe carte delle caramelle nascoste all'interno erano piegate con cura e emanavano ancora un dolce profumo."
  },
  AvgDialog_18832_Content_80 = {
    Text = "Ma T'yog non ascoltava mai. Ogni volta, mi portava di sopra al buio di nascosto, una volta che la signorina Sarah aveva finito il suo giro della buonanotte."
  },
  AvgDialog_18832_Content_81 = {
    Text = "È furbo e coraggioso, proprio come Jenkin. Conosce sempre sentieri nascosti e scorciatoie che gli altri ignorano."
  },
  AvgDialog_18832_Content_82 = {
    Text = "Finché lui era con me, la signorina Sarah non ci avrebbe mai trovati."
  },
  AvgDialog_18832_Content_83 = {
    Text = "Finché lui era con me, questo posto sarebbe sempre stato il Nostro Segreto rifugio."
  },
  AvgDialog_18832_Content_84 = {
    Text = "Era l'unico che mi credeva — credeva che potessi vedere quelle cose nere e mi diceva che era un dono da strega."
  },
  AvgDialog_18832_Content_85 = {
    Text = "Diceva che più contatto si ha con le stelle, più si rafforza la propria magia, ma le stelle appaiono solo di notte dopo una giornata di sole.\nTuttavia, guardare le stelle è inutile."
  },
  AvgDialog_18832_Content_86 = {
    Text = "Non sono una strega."
  },
  AvgDialog_18832_Content_87 = {
    Text = "Sono solo un codardo."
  },
  AvgDialog_18832_Content_88 = {
    Text = "Un'inutile buona a nulla."
  },
  AvgDialog_18832_Content_89 = {
    Text = "Un... assassino."
  },
  AvgDialog_18832_Content_9 = {Text = "Jenkin..."},
  AvgDialog_18832_Content_90 = {
    Text = "Non riesco a fermare il Dottore, né la voce misteriosa. So che altre persone moriranno, ma non posso fare nulla."
  },
  AvgDialog_18832_Content_91 = {
    Text = "Ho paura che tutti si facciano male, paura che vengano portati via. Ma quello di cui ho più paura... quello di cui ho più paura..."
  },
  AvgDialog_18832_Content_93 = {
    Text = "La Dottoressa Clementine aveva ragione. Rischiare la vita deve portare a qualcosa.\nPrima avevo paura, ma ora—"
  },
  AvgDialog_18832_Content_95 = {
    Text = "Dannazione, dovevano restare nella stanza, ma ora nessuno sa dove siano finiti."
  },
  AvgDialog_18832_Content_96 = {
    Text = "Aspetta, quello è..."
  },
  AvgDialog_18832_Content_97 = {
    Text = "Aigis?! Aigis—!"
  },
  AvgDialog_18832_Content_98 = {
    Text = "La voce di Jenkin risuona all'improvviso dal basso, gridando con ansia il nome di Aigis, le braccia protese verso il cielo."
  },
  AvgDialog_18832_Content_99 = {
    Text = "Un uccello attraversa il cielo notturno, svanendo nella fitta nebbia senza lasciare traccia."
  },
  AvgDialog_18833_Content_1 = {
    Text = "Aigis barcollava, ma la sua velocità non diminuiva affatto.\nStringendosi la testa, soffocò un grido di dolore e corse avanti disperatamente."
  },
  AvgDialog_18833_Content_2 = {Text = "Aigis!"},
  AvgDialog_18833_Content_3 = {
    Text = "La ragazza si fece rapidamente strada lungo il corridoio e salì le scale che portavano in cima alla torre dell'orologio, mormorando sottovoce."
  },
  AvgDialog_18833_Content_4 = {
    Text = "La insegui su per la scala a chiocciola, giro dopo giro, l'aria impregnata del profumo di legno e polvere."
  },
  AvgDialog_18833_Content_5 = {
    Text = "Non voglio far loro del male, per favore..."
  },
  AvgDialog_18833_Content_6 = {
    Text = "Non voglio... non intendevo farlo. Basta, basta...!"
  },
  AvgDialog_18834_Content_1 = {
    Text = "Tu e Ramona sfondante da entrambi i lati, ma avete perso di vista da tempo il bambino incappucciato. Gli altri bambini vi bloccano ostinatamente la strada."
  },
  AvgDialog_18834_Content_2 = {
    Text = "Siete... tutti... d'accordo!"
  },
  AvgDialog_18834_Content_3 = {Text = "E allora!"},
  AvgDialog_18834_Content_4 = {
    Text = "Provate a picchiarci, se avete il coraggio!"
  },
  AvgDialog_18834_Content_5 = {
    Text = "Non si può essere così violenti con i bambini. Tuttavia—"
  },
  AvgDialog_18834_Content_6 = {
    Text = "Una buona educazione resta comunque molto necessaria, non credi?"
  },
  AvgDialog_18835_Content_1 = {
    Text = "Avvicinandoti al laboratorio, la strada cade improvvisamente nel silenzio, fatta eccezione per un vagabondo solitario seduto svogliatamente a bordo strada."
  },
  AvgDialog_18835_Content_2 = {
    Text = "Perché è così silenzioso qui? Qualcosa non quadra."
  },
  AvgDialog_18835_Content_3 = {
    Text = "Allora dovremmo stare attenti, Dissoluzione—"
  },
  AvgDialog_18835_Content_4 = {
    Text = "Prima che potesse finire di parlare, il corpo del vagabondo si trasformò improvvisamente. Un gigantesco mostro nero formato dalla melma che sgorgava dal suo petto iniziò a contorcersi verso di voi."
  },
  AvgDialog_18836_Content_1 = {
    Text = "Il mostro nero come la pece si disperde e si riforma rapidamente. Solleva il corpo, aprendosi improvvisamente dalla cima, emettendo un suono stridulo e lacerante."
  },
  AvgDialog_18836_Content_2 = {
    Text = "...Salvami...@4...Salvami..."
  },
  AvgDialog_18836_Content_3 = {
    Text = "Sta... sta parlando...?"
  },
  AvgDialog_18836_Content_4 = {
    Text = "Non fare rumore!"
  },
  AvgDialog_18836_Content_5 = {
    Text = "Sha...@2...Muori...Muori...!"
  },
  AvgDialog_18836_Content_6 = {Text = "!"},
  AvgDialog_18837_Content_1 = {
    Text = "Non vi siete allontanati molto quando i fanciulli, che poco prima si stavano solo prendendo gioco di voi, si sono radunati in fretta davanti a voi, bloccandovi il cammino."
  },
  AvgDialog_18837_Content_2 = {
    Text = "Scusate, per favore... fate passare i bambini."
  },
  AvgDialog_18837_Content_3 = {
    Text = "Na-na-na! Se avete il coraggio, saltateci sopra!"
  },
  AvgDialog_18837_Content_4 = {
    Text = "Guardi Ramona in cerca di aiuto."
  },
  AvgDialog_18837_Content_5 = {
    Text = "E sia, allora cerca di stare al passo."
  },
  AvgDialog_18838_Content_1 = {
    Text = "Andate via di qui! I pazienti sono impazziti e stanno attaccando!"
  },
  AvgDialog_18838_Content_2 = {
    Text = "Non erano pazzi all'inizio—Oh mio Dio! Perché sono usciti tutti?!"
  },
  AvgDialog_18838_Content_3 = {
    Text = "Pensi che stia mentendo? Corri, presto!"
  },
  AvgDialog_18839_Content_1 = {
    Text = "Vedendo che eravate più tosti di quanto avessero immaginato, i ragazzini si dispersero e fuggirono.\nTu e Ramona ne avete catturato uno."
  },
  AvgDialog_18839_Content_2 = {
    Text = "Ahi, parlo, parlo! Il ladro che vi ha rubato la roba è andato al Laboratorio di Lavoro. Cercate lì."
  },
  AvgDialog_18839_Content_3 = {
    Text = "...Sembra un po' troppo una coincidenza. Ti piace gironzolare intorno al laboratorio?"
  },
  AvgDialog_18839_Content_4 = {
    Text = "Non oserei mai. Dicono che quel posto sia infestato da demoni mangia-uomini; solo un pazzo andrebbe a giocare lì."
  },
  AvgDialog_18839_Content_5 = {
    Text = "Quindi neanche il tuo compagno incappucciato ci andrà?"
  },
  AvgDialog_18839_Content_6 = {
    Text = "N-non vi sto mentendo! Io— comunque, credeteci o no!"
  },
  AvgDialog_18839_Content_7 = {
    Text = "Il ragazzino scappò via dopo aver parlato. Hai osservato la sua figura scomparire in lontananza e hai sospirato."
  },
  AvgDialog_18839_Content_8 = {
    Text = "Lascia perdere, la missione viene prima. Andiamo al Laboratorio di Lavoro."
  },
  AvgDialog_18840_Content_1 = {
    Text = "Che diavolo!?"
  },
  AvgDialog_18840_Content_2 = {
    Text = "Bambini, venite qui!"
  },
  AvgDialog_18840_Content_3 = {
    Text = "Sarah si ritirò in fretta, trascinando un bambino con una mano. Tutto il suo corpo tremava di paura, eppure si mise davanti ai bambini e coprì loro gli occhi."
  },
  AvgDialog_18840_Content_4 = {Text = "Indietro!"},
  AvgDialog_18840_Content_5 = {
    Text = "%player%, stai attento!"
  },
  AvgDialog_18841_Content_1 = {
    Text = "Una mela al giorno toglie il medico di torno."
  },
  AvgDialog_18841_Content_10 = {
    Text = [[
08:16, Laboratorio di Lily
Mensa]]
  },
  AvgDialog_18841_Content_11 = {
    Text = "Ma non mi sono alzata durante la notte! Aigis, perché continui a chiedermelo? Ho solo dormito tutta la notte e non ho fatto nient'altro."
  },
  AvgDialog_18841_Content_12 = {Text = "Io..."},
  AvgDialog_18841_Content_13 = {
    Text = "Esatto. Perché, Aigis?"
  },
  AvgDialog_18841_Content_14 = {
    Text = "Perché continui a chiedere ancora e ancora, anche se abbiamo già detto che non sappiamo?\nPensi davvero di sapere cosa abbiamo fatto la scorsa notte?"
  },
  AvgDialog_18841_Content_15 = {
    Text = "Non è così, io... Come potrei—"
  },
  AvgDialog_18841_Content_16 = {
    Text = "Sei mia amica, Aigis. Non voglio continuare a fare supposizioni così con un'amica. Dimmelo e basta, cosa sai?"
  },
  AvgDialog_18841_Content_17 = {
    Text = "...Jenkin, io... Non capisco..."
  },
  AvgDialog_18841_Content_18 = {
    Text = "Volevo chiedertelo ieri, cosa sta succedendo con questo?"
  },
  AvgDialog_18841_Content_19 = {Text = "!"},
  AvgDialog_18841_Content_2 = {
    Text = "Il Secondo Giorno"
  },
  AvgDialog_18841_Content_20 = {
    Text = "Mi chiedevo se avessi semplicemente trovato un pezzo di nastro da qualche parte e lo avessi tenuto perché era carino."
  },
  AvgDialog_18841_Content_21 = {
    Text = "Tuttavia, perché sei rimasta in silenzio dopo aver visto quell'altra metà nella mano di %player%?\nQueste due sono chiaramente dello stesso nastro."
  },
  AvgDialog_18841_Content_22 = {
    Text = "Gli altri bambini al tavolo non notarono la loro conversazione e continuarono a ridere e giocare.\nAigis abbassò la testa, le spalle leggermente sollevate e tremanti."
  },
  AvgDialog_18841_Content_23 = {
    Text = "Puoi dirmi dove è stato trovato? Dov'è mia sorella?\nTutto il resto può rimanere non detto, tranne questo—"
  },
  AvgDialog_18841_Content_24 = {
    Text = "Posso capire tutto, che siano le tue preoccupazioni o qualsiasi altra cosa. Ma devi dirmelo, Aigis.\nDov'è scomparsa mia sorella? Per favore, dimmelo!"
  },
  AvgDialog_18841_Content_25 = {
    Text = "Non posso... Mi dispiace... Non lo so, davvero non lo so...\nJenkin, Jenkin, darò qualsiasi cosa, per favore non andartene, non smettere di essere mio amico..."
  },
  AvgDialog_18841_Content_26 = {
    Text = "Ma di cosa stai parlando?"
  },
  AvgDialog_18841_Content_27 = {
    Text = "Radunatevi! Bambini, lavoratori, venite nel cortile! Mettetevi in fila—"
  },
  AvgDialog_18841_Content_28 = {
    Text = [[
08:16, Laboratorio di Lily
Mensa]]
  },
  AvgDialog_18841_Content_29 = {
    Text = [[
Mi scusi, ieri ho cercato di nascondere l'esistenza dei pazienti e ho continuato a insistere che si sbagliasse, signorina Mary.
Dopotutto, ricercatori del genere non esisterebbero in un laboratorio normale.]]
  },
  AvgDialog_18841_Content_3 = {
    Text = [[
08:15, Laboratorio di Lily
Mensa]]
  },
  AvgDialog_18841_Content_30 = {
    Text = "A proposito, dov'è il ricercatore? Non l'ho visto in giro.\n{Male=signore,Female=signorina} Ash e io volevamo chiedergli del trattamento sperimentale."
  },
  AvgDialog_18841_Content_31 = {
    Text = [[
Probabilmente sono tornati all'istituto di ricerca. Devono fare rapporto periodicamente.
Non conosco i dettagli.]]
  },
  AvgDialog_18841_Content_32 = {
    Text = "Quindi, potrebbe darmi il loro indirizzo?"
  },
  AvgDialog_18841_Content_33 = {
    Text = "Hmm... Non sono molto sicura dell'indirizzo. Ma oggi è il giorno in cui il Dott. Miller visita i pazienti. Forse potete chiedergli direttamente? È quasi ora—ah, guardate, eccoli che arrivano."
  },
  AvgDialog_18841_Content_34 = {
    Text = "Guardate nella direzione in cui avete salutato Sarah: Rogers e alcuni uomini in abito, con valigette mediche, stanno camminando verso di voi. Clementine non è tra loro."
  },
  AvgDialog_18841_Content_35 = {
    Text = "Dott. Miller e Sig. Rogers! {Male=Lord,Female=Lady} Ashe e io stavamo proprio parlando di voi."
  },
  AvgDialog_18841_Content_36 = {
    Text = [[
L'illustre Ospite mi ha menzionato? Che fortuna la mia.
Salve, {Male=Lord,Female=Lady} Ashe, Signorina Mary. Il Sig. Rogers mi stava appunto parlando di voi.]]
  },
  AvgDialog_18841_Content_37 = {
    Text = "Piacere di conoscerla."
  },
  AvgDialog_18841_Content_38 = {
    Text = "A dire il vero, siamo molto curiosi riguardo alla vostra terapia sperimentale. Potremmo assistere al vostro trattamento più tardi?"
  },
  AvgDialog_18841_Content_39 = {
    Text = "È un peccato. Di recente abbiamo spostato tutte le cure al laboratorio, il che potrebbe essere scomodo."
  },
  AvgDialog_18841_Content_4 = {
    Text = "Dobbiamo sbrigarci. Chissà quando Doll ci ordinerà di ritirarci."
  },
  AvgDialog_18841_Content_40 = {
    Text = "Potremmo forse visitare il vostro istituto di ricerca? Se gli effetti sono davvero come affermano la signorina Sarah e il signor Rogers, vorremmo anche noi contribuire con fondi e risorse."
  },
  AvgDialog_18841_Content_41 = {
    Text = "Più compagni con ideali comuni ci sono, meglio è. Tuttavia, la nostra ricerca è attualmente in una fase critica e non possiamo accogliere visitatori. Sono certo che entrambi possiate capire, giusto?"
  },
  AvgDialog_18841_Content_42 = {
    Text = "Forse potrebbe dare loro uno dei suoi biglietti da visita, Dott. Miller?\nRenderebbe più facili i contatti futuri."
  },
  AvgDialog_18841_Content_43 = {
    Text = "Il signor Rogers ha ragione.\nUna volta fissata una data, sarà nostra premura accogliervi come si deve."
  },
  AvgDialog_18841_Content_44 = {
    Text = "Il Dott. Miller vi porge un biglietto da visita che recita: \"Frederick Miller, Cross Street 10\"."
  },
  AvgDialog_18841_Content_45 = {
    Text = "La via e i numeri civici fin troppo ordinati vi fanno dubitare che ci sia anche una sola verità su questo biglietto da visita."
  },
  AvgDialog_18841_Content_46 = {
    Text = "Signorina Sarah, raduni tutti così possiamo stabilire chi necessita di cure e controlli."
  },
  AvgDialog_18841_Content_47 = {
    Text = "Nessun problema.\nRadunatevi! Bambini, lavoratori, venite nel cortile! Mettetevi in fila—"
  },
  AvgDialog_18841_Content_48 = {
    Text = "Avete seguito Sarah e il Dott. Miller nel cortile."
  },
  AvgDialog_18841_Content_5 = {
    Text = "Evacuare? Cosa intendi con evacuazione?"
  },
  AvgDialog_18841_Content_6 = {
    Text = "Oh, niente. Buongiorno, signorina Sarah."
  },
  AvgDialog_18841_Content_7 = {
    Text = [[
Buongiorno, {Male=Lord,Female=Lady} Ashe, Signorina Mary.
Mi chiedo come abbiate riposato stanotte.]]
  },
  AvgDialog_18841_Content_8 = {
    Text = "Grazie a te, ho dormito davvero bene.\nIl tè della signorina Sarah ha davvero un effetto impareggiabile."
  },
  AvgDialog_18841_Content_9 = {
    Text = "Sì, davvero? È meraviglioso."
  },
  AvgDialog_18842_Content_1 = {
    Text = "Tu sei l'assassino, sei tu che mi controlli... Ugh... Ahh..."
  },
  AvgDialog_18842_Content_2 = {
    Text = "Aigis, ascoltami. Abbiamo un modo per liberarti dalla persona che cerca di controllarti. Non devi fare questo."
  },
  AvgDialog_18842_Content_3 = {
    Text = "Non avvicinatevi... Non... Aaah...!"
  },
  AvgDialog_18843_Content_1 = {
    Text = "Dietro il Muro di Pietra"
  },
  AvgDialog_18843_Content_10 = {
    Text = "Non voglio andarci. Non voglio. Ci sono già andata l'ultima volta; ci sono già stata. Non voglio andarci di nuovo. Non voglio."
  },
  AvgDialog_18843_Content_11 = {
    Text = "Ma non hai detto di recente di vedere cose nere? Ho consultato il Dott. Miller, e ha detto che vedere fantasmi non è una cosa da poco. Devi farti controllare di nuovo oggi."
  },
  AvgDialog_18843_Content_12 = {
    Text = [[
Signorina Sarah, la prego, non mi ci faccia andare.
Non l'ho visto, davvero no. La prego.]]
  },
  AvgDialog_18843_Content_13 = {
    Text = "E se finissi come quei pazzi? No, devo andare. Ascoltami."
  },
  AvgDialog_18843_Content_14 = {
    Text = "Signorina Sarah—"
  },
  AvgDialog_18843_Content_15 = {
    Text = "Questa è la bambina."
  },
  AvgDialog_18843_Content_16 = {
    Text = "No... non voglio andarci... ci sono già stata una volta, non voglio..."
  },
  AvgDialog_18843_Content_17 = {
    Text = "Vado io, signore."
  },
  AvgDialog_18843_Content_18 = {Text = "!"},
  AvgDialog_18843_Content_19 = {
    Text = "...Non ti senti bene?"
  },
  AvgDialog_18843_Content_2 = {
    Text = "L'ho visto davvero, sul serio! Quelle cose nere, triangolari. Tutti quelli che vanno dal Dottore finiscono con queste addosso—così spaventoso, così spaventoso."
  },
  AvgDialog_18843_Content_20 = {
    Text = [[
Non mi sento male; posso correre e saltare, sono perfettamente sana!
Ma riesco a vedere delle cose.]]
  },
  AvgDialog_18843_Content_21 = {
    Text = "Oh? Cosa riesci a vedere?"
  },
  AvgDialog_18843_Content_22 = {
    Text = [[
Come Aigis, anch'io vedo cose nere.
Potrebbe aiutarmi, per favore?]]
  },
  AvgDialog_18843_Content_23 = {
    Text = "Interessante. Allora porto te."
  },
  AvgDialog_18843_Content_24 = {Text = "T'yog..."},
  AvgDialog_18843_Content_25 = {
    Text = "Non avere paura, Aigis."
  },
  AvgDialog_18843_Content_26 = {
    Text = "Tornerò presto."
  },
  AvgDialog_18843_Content_27 = {
    Text = [[
09:00, Laboratorio di Lily
Stanza di Aigis]]
  },
  AvgDialog_18843_Content_28 = {
    Text = "Ti sei seduto nella stanza di Aigis, ascoltando il racconto esitante della ragazza."
  },
  AvgDialog_18843_Content_29 = {
    Text = "Quelli portati dal Dottore tornano con sempre più buchi neri sul corpo, che aumentano col tempo.\nMa nessun altro riesce a vederli; tutti mi chiamano bugiarda."
  },
  AvgDialog_18843_Content_3 = {
    Text = "Le macchie scure... stai dicendo che i miei vestiti sono sporchi? Forse si sono macchiati."
  },
  AvgDialog_18843_Content_30 = {
    Text = "Solo Tyug mi credeva, solo Tyug. Ma è morto...\nÈ morto, ed è tutta colpa mia."
  },
  AvgDialog_18843_Content_31 = {
    Text = "Se non l'avessi lasciato andare a farsi controllare, se fossi stata più forte, se avessi potuto fare di più, lui non sarebbe... non sarebbe... Sono un tale fallimento..."
  },
  AvgDialog_18843_Content_32 = {
    Text = "Non parlare di te stessa così. Non lo sei!"
  },
  AvgDialog_18843_Content_33 = {
    Text = "Lo sono, lo sono! Non riesco a salvarlo, non riesco a salvare nessuno, non riesco a fare niente!\nLa mamma aveva ragione. Sono solo un peso, una nullità inutile. Non riesco a fare niente..."
  },
  AvgDialog_18843_Content_34 = {
    Text = "Io... non riesco a fare niente..."
  },
  AvgDialog_18843_Content_35 = {Text = "E allora!"},
  AvgDialog_18843_Content_36 = {
    Text = "La voce di Jenkin squarciò la stanza angusta, lasciando Aigis a fissarla con aria stordita."
  },
  AvgDialog_18843_Content_37 = {
    Text = "E chi se ne importa se non riesci a salvarli? Chi se ne importa se hai paura! Chi ha detto che devi essere tu l'eroina?\nNon è mai stata una tua responsabilità!"
  },
  AvgDialog_18843_Content_38 = {
    Text = "Ma, sono tutti..."
  },
  AvgDialog_18843_Content_39 = {
    Text = "E allora? Dovrebbero lasciare che una bambina come te salvi il mondo? Perché?\nNon hai già fatto abbastanza?"
  },
  AvgDialog_18843_Content_4 = {
    Text = "No! Sono scure e umide, e fanno sparire le mani e i piedi!"
  },
  AvgDialog_18843_Content_40 = {
    Text = "Jenkin tirò fuori dalla tasca un nastro sgualcito e lo porse ad Aigis. I suoi colori vivaci erano identici a quello che avevi in mano."
  },
  AvgDialog_18843_Content_41 = {
    Text = "Non sei né una bugiarda né un'inutile. Sei la mia amica.\nQuello che non riesci a fare da sola, possiamo realizzarlo insieme."
  },
  AvgDialog_18843_Content_42 = {
    Text = "Io mi fido di te. Tu ti fidi di me, va bene?"
  },
  AvgDialog_18843_Content_43 = {
    Text = "Aigis fissò il nastro nella sua mano, mentre le lacrime le scendevano una dopo l'altra.\nScosse vigorosamente la testa, e l'espressione sofferente riapparve sul suo volto."
  },
  AvgDialog_18843_Content_44 = {Text = "Aigis—"},
  AvgDialog_18843_Content_45 = {
    Text = "Jenkin, lascia stare. Aigis probabilmente ha le sue preoccupazioni."
  },
  AvgDialog_18843_Content_46 = {
    Text = [[
Sembra che la clinica possa essere una buona pista da seguire.
Aigis, riesci a resistere e portarci alla clinica?]]
  },
  AvgDialog_18843_Content_47 = {
    Text = "Basta arrivare alla porta. Se ti senti a disagio, non c'è bisogno di entrare."
  },
  AvgDialog_18843_Content_48 = {
    Text = "Ho capito. Io... vi porterò là."
  },
  AvgDialog_18843_Content_49 = {
    Text = [[
09:11, Laboratorio di Lily
Clinica Temporanea]]
  },
  AvgDialog_18843_Content_5 = {
    Text = "Diana, per favore non andare a fare l'esame. Ti prego, non andare a farti controllare. Diana, Diana!"
  },
  AvgDialog_18843_Content_50 = {
    Text = "Lo spazio qui è piccolo, e il confine è chiaramente visibile. A parte qualche tavolo e sedia, non c'è quasi nulla, nemmeno un singolo fascicolo."
  },
  AvgDialog_18843_Content_51 = {
    Text = "Dopo essere stati portati qui, ci veniva richiesto di prendere una medicina, che ci faceva addormentare."
  },
  AvgDialog_18843_Content_52 = {
    Text = "Dopo esserti addormentata, sogni di trovarti in un posto molto buio e freddo, senza finestre, con solo un'enorme luce accecante puntata sul viso, che risulta estremamente abbagliante."
  },
  AvgDialog_18843_Content_53 = {
    Text = "Quando ti svegli, trovi... quei segni neri... sul corpo..."
  },
  AvgDialog_18843_Content_54 = {
    Text = "Buio, freddo e senza finestre. Sembra un seminterrato."
  },
  AvgDialog_18843_Content_55 = {
    Text = "Ma l'ingresso del seminterrato del laboratorio non è qui, ed è pieno di cianfrusaglie. Non è come nel sogno."
  },
  AvgDialog_18843_Content_56 = {
    Text = "Potrebbe essere una stanza nascosta?"
  },
  AvgDialog_18843_Content_57 = {
    Text = "Una stanza nascosta, eh? È la mia specialità. Brown!"
  },
  AvgDialog_18843_Content_58 = {Text = "Squeak!"},
  AvgDialog_18843_Content_59 = {
    Text = [[
Il topo corse via, scomparendo in una crepa nel muro.
Poco dopo, senti degli squittii provenire dal muro di fronte a te.]]
  },
  AvgDialog_18843_Content_6 = {
    Text = "Qui non c'è chiaramente niente di scuro. Aigis è una gran bugiarda! Bugiarda, naso lungo!"
  },
  AvgDialog_18843_Content_60 = {
    Text = "Là, c'è uno spazio aperto!"
  },
  AvgDialog_18843_Content_61 = {
    Text = "Jenkin iniziò a battere freneticamente sul muro. Capendo cosa stava facendo, ti unisti a lei, premendo deliberatamente sui mattoni."
  },
  AvgDialog_18843_Content_62 = {
    Text = "Il muro cedette improvvisamente sotto il palmo di Ramona. Dopo un clic proveniente da qualche parte, il muro sporse leggermente e iniziò lentamente ad aprirsi verso l'esterno."
  },
  AvgDialog_18843_Content_63 = {
    Text = "Man mano che le fessure tra i mattoni si allargavano, l'odore di sangue e decomposizione si riversò fuori."
  },
  AvgDialog_18843_Content_64 = {
    Text = "Un passaggio buio e stretto che conduce dritto verso il basso appare davanti a te."
  },
  AvgDialog_18843_Content_7 = {
    Text = "Non ho mentito, davvero no. L'ho visto davvero!"
  },
  AvgDialog_18843_Content_8 = {
    Text = "L'ho visto davvero... Credetemi..."
  },
  AvgDialog_18843_Content_9 = {
    Text = "Aigis, vieni. Seguimi nella sala di trattamento."
  },
  AvgDialog_18844_Content_1 = {
    Text = "Cosa c'è che non va in quella bambina?"
  },
  AvgDialog_18844_Content_2 = {
    Text = "Sembra che stia parlando con qualcuno che noi non possiamo vedere."
  },
  AvgDialog_18844_Content_3 = {
    Text = "Possibile che anche lei sia controllata da qualcuno, proprio come Jenkin? Com'è possibile una cosa del genere?"
  },
  AvgDialog_18845_Content_1 = {
    Text = "Prova la Retrospettiva. Altri Investigatori potrebbero avere difficoltà a indagare su entità non Risvegliate."
  },
  AvgDialog_18845_Content_2 = {
    Text = "Ma se sei tu — con la tua acutezza, ci riuscirai sicuramente."
  },
  AvgDialog_18846_Content_1 = {
    Text = "Fai un respiro profondo, chiudi gli occhi e la tua visione sprofonda nell'oscurità.\nAll'inizio non c'è nulla, solo il suono del tuo respiro e di quello di Ramona."
  },
  AvgDialog_18846_Content_2 = {
    Text = "Gradualmente, riesci a sentire le sottili goccioline d'acqua nella foschia collidere tra loro, mentre i mostri trasformati in fango dietro di te si disintegrano, e la polvere nera si posa dolcemente."
  },
  AvgDialog_18846_Content_3 = {
    Text = "La Chiave d'argento vibra, e ascolti attentamente per discernere la melodia nascosta.\nÈ vivace, come una ballata che chiama sommessamente da vicino."
  },
  AvgDialog_18846_Content_4 = {
    Text = "\"Il vecchio Charlie ha un amato gatto soriano...\""
  },
  AvgDialog_18846_Content_5 = {
    Text = "Da questa parte!"
  },
  AvgDialog_18847_Content_1 = {
    Text = "I mostri che hai sconfitto collassano in una pozza di melma nera. Ti guardi intorno, senza vedere altro che una vasta distesa di nebbia bianca."
  },
  AvgDialog_18847_Content_2 = {
    Text = "Dannazione, non si vede niente."
  },
  AvgDialog_18847_Content_3 = {
    Text = "Neanche i miei occhiali mostrano granché."
  },
  AvgDialog_18847_Content_4 = {
    Text = "Che facciamo adesso?"
  },
  AvgDialog_18847_Content_5 = {
    Text = "Se solo ci fosse un modo per tracciare senza affidarsi alla vista."
  },
  AvgDialog_18847_Content_6 = {
    Text = [[
Lettura parola chiave riuscita, "un metodo per tracciare senza la vista," ricerca in corso...
Ricerca completata. Il Custode potrebbe considerare di eseguire una traccia spirituale.]]
  },
  AvgDialog_18847_Content_7 = {
    Text = "Non è quello che gli Investigatori usano per rintracciare i Risvegliatori scomparsi? Funziona anche sui Mutanti?"
  },
  AvgDialog_18847_Content_8 = {
    Text = [[
Il principio della traccia mentale consiste nel localizzare fluttuazioni mentali anomale.
Sotto questo aspetto, i mutanti sono uguali ai Risvegliatori.]]
  },
  AvgDialog_18847_Content_9 = {
    Text = "Tuttavia — occupiamoci prima di questo tizio."
  },
  AvgDialog_18848_Content_1 = {
    Text = "Un Mutante dopo l'altro si dissolse sotto la lama di Ramona. Il colorito di Aigis si fece sempre più pallido tra la polvere nera che si disperdeva nell'aria."
  },
  AvgDialog_18848_Content_2 = {
    Text = [[
Cosa state aspettando? Portatemi via adesso.
Sono io la colpevole. Prendete me, e poi... riportate indietro Lucy.]]
  },
  AvgDialog_18848_Content_3 = {
    Text = "Se la rivuoi, dimostra la sua innocenza e dicci la verità, non in questo modo. Questo non è un buon approccio."
  },
  AvgDialog_18848_Content_4 = {
    Text = "Non capite... Nessuno di voi capisce... Io sono l'unica e sola vera squartatrice."
  },
  AvgDialog_18848_Content_5 = {
    Text = "Il suo corpo oscilla mentre si lancia contro voi due."
  },
  AvgDialog_18849_Content_1 = {
    Text = [[
15:01, Londinium Est
Laboratorio di Lily]]
  },
  AvgDialog_18849_Content_10 = {
    Text = "Jenkin strappò il nastro dalle mani. \nAigis, apparentemente colpita dalle sue emozioni, divenne estremamente tesa."
  },
  AvgDialog_18849_Content_11 = {
    Text = "Sorella, questo è... questo è di mia sorella! Ho personalizzato io stessa la fibbia. Non posso sbagliarmi."
  },
  AvgDialog_18849_Content_12 = {
    Text = "Il suo viso divenne ancora più pallido mentre stringeva il nastro, come se pesasse mille libbre. Le sue dita lo afferravano rigidamente, come se volesse stringerlo forte ma non sopportasse l'idea di rovinarlo."
  },
  AvgDialog_18849_Content_13 = {
    Text = "Dov'è? Sta bene? È ferita? È... è..."
  },
  AvgDialog_18849_Content_14 = {
    Text = "Cip, cip cip."
  },
  AvgDialog_18849_Content_15 = {
    Text = "Sì, sì. Dev'essere scomparsa, vero? Non l'avete trovata nemmeno voi, vero?"
  },
  AvgDialog_18849_Content_16 = {
    Text = "In effetti non abbiamo trovato alcuna traccia di lei."
  },
  AvgDialog_18849_Content_17 = {
    Text = "Allora c'è ancora speranza. Il nastro era strappato, quindi dev'essere scappata e si è nascosta nel laboratorio. Di sicuro."
  },
  AvgDialog_18849_Content_18 = {
    Text = "Puoi vedere il tremore nei suoi occhi. Ma a volte, una falsa convinzione può sostenere una persona meglio di una verità crudele."
  },
  AvgDialog_18849_Content_19 = {
    Text = "Aigis tirò fuori alcune caramelle confezionate con cura da sotto il materasso e le porse a Jenkin."
  },
  AvgDialog_18849_Content_2 = {
    Text = "Hai detto <Blue:pazzi malati>, che tipo di pazzi malati?"
  },
  AvgDialog_18849_Content_20 = {
    Text = "Noi... troveremo tua sorella. Sicuramente."
  },
  AvgDialog_18849_Content_21 = {
    Text = "La ragazza mormorò, la sua voce consolante si affievolì. Era pallida, come se stesse sopportando un dolore immenso."
  },
  AvgDialog_18849_Content_22 = {
    Text = "%player%. Sta succedendo qualcosa nel cortile anteriore. Vieni subito."
  },
  AvgDialog_18849_Content_23 = {
    Text = "Ti sei affrettato e hai visto Ramona, insieme a diverse persone vestite diversamente dagli altri lavoratori, che legavano un uomo con delle corde."
  },
  AvgDialog_18849_Content_24 = {
    Text = "L'uomo ha strane cicatrici sul corpo, che a prima vista sembrano suture contorte. La carne non rimarginata è piena di un fluido scuro e vischioso."
  },
  AvgDialog_18849_Content_25 = {
    Text = "Quello è un <Yellow:D-marchio>, e sembra essere in una <Yellow:Dissoluzione a stadio intermedio>.\nNon hai mai visto nulla di simile."
  },
  AvgDialog_18849_Content_26 = {
    Text = "Guarda, è il tipo di pazzo di cui parlavo.\nVedi, indossa ancora i vestiti da lavoro. Dev'essere appena impazzito. Spaventoso."
  },
  AvgDialog_18849_Content_27 = {
    Text = "Una persona vestita di bianco tirò fuori una siringa da qualche parte.\nLa iniettò nel collo dell'uomo. L'uomo ebbe un breve spasmo prima di afflosciarsi e ammutolirsi."
  },
  AvgDialog_18849_Content_28 = {
    Text = "Hai trattenuto la tua espressione—i farmaci ordinari non dovrebbero funzionare su un Corpo in Dissoluzione. Come ha fatto questa persona?"
  },
  AvgDialog_18849_Content_29 = {
    Text = "Diverse persone videro l'uomo perdere conoscenza, lo legarono rapidamente e lo portarono via.\nRamona cercò di seguirli, ma Sarah le bloccò il cammino."
  },
  AvgDialog_18849_Content_3 = {
    Text = [[
Hmm, non saprei dirlo con certezza. Quelle persone possono sembrare normali un giorno e impazzire completamente il giorno dopo.
Fa davvero paura come i loro occhi e il naso si fondono improvvisamente insieme.]]
  },
  AvgDialog_18849_Content_30 = {
    Text = "Signorina Mary, non andate laggiù, lasciate fare a loro.\nSe vi faceste male, come potrei spiegarlo a {Male=Lord,Female=Lady} Ashe?"
  },
  AvgDialog_18849_Content_31 = {
    Text = "Non servono spiegazioni."
  },
  AvgDialog_18849_Content_32 = {
    Text = "L-{Male=Lord,Female=Lady} Ashe!"
  },
  AvgDialog_18849_Content_33 = {
    Text = "Sebbene il <Yellow:Comitato> regolamenti severamente la ricerca civile sulla Dissoluzione, ci sono sempre uno o due individui con mezzi speciali. La persona in bianco è riuscita a sottomettere un Mutante in un istante — di certo non è una persona comune."
  },
  AvgDialog_18849_Content_34 = {
    Text = "Sa qualcosa di questi eventi nel Distretto Est?\nÈ coinvolto in questi eventi?"
  },
  AvgDialog_18849_Content_35 = {
    Text = "Cos'è appena successo? Chi era quella persona in bianco del laboratorio?"
  },
  AvgDialog_18849_Content_36 = {
    Text = "Q-Quello è solo un <Blue:Ricercatore>—"
  },
  AvgDialog_18849_Content_37 = {
    Text = [[
Signorina Sarah, spero che possa essere sincera con noi.
Non voglio che le cose arrivino a un punto di non ritorno.]]
  },
  AvgDialog_18849_Content_38 = {
    Text = [[
Fissi Sarah con espressione seria, mentre i suoi occhi sono sfuggenti.
Incerta se avesse compreso il tuo significato, Sarah si morse il labbro e prese una decisione.]]
  },
  AvgDialog_18849_Content_39 = {
    Text = "Va bene. Se la metti così... seguitemi, per favore."
  },
  AvgDialog_18849_Content_4 = {
    Text = "Te lo dico io, questo laboratorio è pieno di segreti.\nQuella donna odiosa ha nascosto parecchie cose solo nell'ufficio."
  },
  AvgDialog_18849_Content_40 = {
    Text = [[
15:01, Laboratorio Lilyan
Area Medica Temporanea]]
  },
  AvgDialog_18849_Content_41 = {
    Text = "Decine di letti sono ammassati nella mensa già angusta, con tutti i pazienti legati e mani e piedi fissati ai letti."
  },
  AvgDialog_18849_Content_42 = {
    Text = "Gli inservienti si muovono intorno, alcuni con strisce di tessuto grezzo, pronti a rinforzare le contenzioni dei pazienti in qualsiasi momento."
  },
  AvgDialog_18849_Content_43 = {
    Text = "Su un letto vicino alla finestra giaceva un vecchio emaciato, con gli occhi spalancati, e una goccia di liquido nero e viscoso che trasudava dall'angolo dell'occhio."
  },
  AvgDialog_18849_Content_5 = {Text = "Brown."},
  AvgDialog_18849_Content_6 = {
    Text = "\nBrown sbucò dalla borsa a tracolla, stringendo due anelli luccicanti con le zampette anteriori.\nA giudicare dalla fattura e dai materiali, non sono inestimabili, ma hanno comunque un discreto valore."
  },
  AvgDialog_18849_Content_7 = {
    Text = "Hai pensato al nastro ornato con una fibbia quadrata d'argento."
  },
  AvgDialog_18849_Content_8 = {
    Text = "Allora, hai visto qualcosa di simile a questo?"
  },
  AvgDialog_18849_Content_9 = {Text = "!"},
  AvgDialog_18850_Content_1 = {
    Text = "Il mostro contorto è a malapena vivo, la melma nera si agita con difficoltà. Innumerevoli volti si formano e si dissolvono, emettendo suoni inquietanti."
  },
  AvgDialog_18850_Content_10 = {
    Text = "Non... ce la farà. Sembra che gli resti solo un barlume di coscienza.\nVoglio comunicare con lui, sentire cosa ha da dire. C'è un modo per farlo?"
  },
  AvgDialog_18850_Content_100 = {
    Text = [[
Per lei, oggi deve essere stata una giornata dura.
Con questo pensiero, hai raggiunto Ramona e Jenkin, e hai sentito Aigis seguirti alle spalle.]]
  },
  AvgDialog_18850_Content_11 = {
    Text = "...Non esiste un precedente simile tra gli Investigatori ordinari.\nTuttavia, il Professor Alistair è riuscito a comunicare con la coscienza residua all'interno dell'anomalia usando la Chiave d'Argento."
  },
  AvgDialog_18850_Content_12 = {
    Text = "Non c'è bisogno di aggiungere altro. Estrai la Chiave d'Argento e chiudi istintivamente gli occhi."
  },
  AvgDialog_18850_Content_13 = {
    Text = "Il fetore della putrefazione di Caro, l'aria fredda del seminterrato e la debole vibrazione della Chiave d'Argento svaniscono rapidamente.\nSei immerso nell'oscurità, ascoltando attentamente ogni grido intriso di dolore."
  },
  AvgDialog_18850_Content_14 = {
    Text = "Sorella Sasha... Aiutami..."
  },
  AvgDialog_18850_Content_15 = {
    Text = "Non voglio morire, davvero non voglio..."
  },
  AvgDialog_18850_Content_16 = {
    Text = "È lei... È quella donna... Mi ha costretto ad accettare il trattamento, lei"
  },
  AvgDialog_18850_Content_17 = {
    Text = "Pericolo... Bisogna aspettare Mythag..."
  },
  AvgDialog_18850_Content_18 = {
    Text = "Hai individuato il suono."
  },
  AvgDialog_18850_Content_19 = {
    Text = "Sono un nuovo Custode. Tu sei... un veterano della Scuola di Gestione?"
  },
  AvgDialog_18850_Content_2 = {
    Text = "Tra le frenetiche preghiere di Sarah, un volto con troppi occhi e denti emerse dal Mutante. Aprì la bocca e lanciò un ululato rauco."
  },
  AvgDialog_18850_Content_20 = {
    Text = "Sono io... cinque giorni fa... Sean e io... siamo usciti a indagare sullo Smembratore... e abbiamo incontrato un mostro...\nSean è... al sicuro...?"
  },
  AvgDialog_18850_Content_21 = {
    Text = "Sta ricevendo cure a scuola ed è ora stabile.\nPuoi dirmi cosa ti è successo?"
  },
  AvgDialog_18850_Content_22 = {
    Text = "Il mostro mi ha trasformato in... ha portato via la signora... poi... qualcuno... la persona con il marchio del coltello da intaglio... mi ha portato qui... frantumato, tagliato... e messo insieme agli altri..."
  },
  AvgDialog_18850_Content_23 = {
    Text = [[
"Hanno menzionato un... piano... fuori dalla Zanna... molti altri... 
Trovateli... Custodi... e... fermateli..."]]
  },
  AvgDialog_18850_Content_24 = {
    Text = "La flebile voce svanisce gradualmente. Apri gli occhi. Il pallido volto umano sul Mutante si dissolve lentamente nel nulla, lasciando solo una pozza di residui nerissimi sul terreno."
  },
  AvgDialog_18850_Content_25 = {Text = "Stai bene?"},
  AvgDialog_18850_Content_26 = {
    Text = "Sto bene. Poco fa... quel veterano mi ha detto che è stato trasformato in una statua da una forma di vita sconosciuta, portato qui per esperimenti e poi messo insieme ad altri, finendo così."
  },
  AvgDialog_18850_Content_27 = {
    Text = "I ricercatori portano i marchi dei coltelli da intaglio."
  },
  AvgDialog_18850_Content_28 = {
    Text = "Come previsto, sono Gli Scultori. Il loro emblema è un coltello da intaglio."
  },
  AvgDialog_18850_Content_29 = {
    Text = [[
Non solo, ma ha detto che gli scultori hanno menzionato un piano.
Un piano che si estende oltre il laboratorio.]]
  },
  AvgDialog_18850_Content_3 = {
    Text = "Sha... Sha... Sorella..."
  },
  AvgDialog_18850_Content_30 = {
    Text = "Ramona fece oscillare lo stocco, lo rinfoderò e guardò Sarah seduta lì vicino."
  },
  AvgDialog_18850_Content_31 = {
    Text = "Parla. Conducete esperimenti su esseri umani e uccidete indiscriminatamente qui. Qual è il vostro vero scopo?\nE cos'è esattamente quel piano?"
  },
  AvgDialog_18850_Content_32 = {
    Text = "Quale esperimento umano, quale... quale scultore? Non capisco. Non capisco niente."
  },
  AvgDialog_18850_Content_33 = {
    Text = "Voglio solo che il laboratorio continui, così tutti possano crescere sani..."
  },
  AvgDialog_18850_Content_34 = {
    Text = "Sani un corno! Guarda quei pazienti, guarda Aigis! Le hanno rovinato gli occhi, e la chiami salute?!"
  },
  AvgDialog_18850_Content_35 = {
    Text = "No, impossibile... Ho esaminato personalmente il Dottore. Ho testato il trattamento su me stessa. Solo dopo aver confermato che fosse sicuro ho permesso a tutti gli altri di provarlo. Impossibile..."
  },
  AvgDialog_18850_Content_36 = {
    Text = [[
Aigis, tesoro, dimmi che stai bene?
Il dottore ha curato il tuo fantasma, vero?]]
  },
  AvgDialog_18850_Content_37 = {
    Text = "Aigis ti guardò, come se stesse raccogliendo il coraggio."
  },
  AvgDialog_18850_Content_38 = {
    Text = "No, non sperimentate su di lui!"
  },
  AvgDialog_18850_Content_39 = {Text = "Aigis!"},
  AvgDialog_18850_Content_4 = {
    Text = "...Piccolo Willy...?\nSolo il piccolo Willy mi chiamava così. Piccolo Willy, sei tu? Piccolo Willy?"
  },
  AvgDialog_18850_Content_40 = {
    Text = [[
Sei tu, piccola Aigis.
Hai deciso di collaborare con noi?]]
  },
  AvgDialog_18850_Content_41 = {
    Text = "Io, io... Io non..."
  },
  AvgDialog_18850_Content_42 = {
    Text = "Se sei malata, devi essere visitata e curata di conseguenza. Dato che tutti voi potete vedere la cosa nera, dovreste tutti ricevere un trattamento per guarire il prima possibile, giusto?"
  },
  AvgDialog_18850_Content_43 = {
    Text = "No... Tiyog, Tiyog non riesce a vedere nulla...! Lasciatelo andare!\nSe continuate così, io-io-io lo dirò alla signorina Sarah!"
  },
  AvgDialog_18850_Content_44 = {
    Text = "Non riesce a vedere? Allora è un piccolo bugiardo.\nDato che non riesce a vedere, allora—"
  },
  AvgDialog_18850_Content_45 = {
    Text = "Aigis! Attenta alle spalle!"
  },
  AvgDialog_18850_Content_47 = {
    Text = "—Tocca a te."
  },
  AvgDialog_18850_Content_48 = {
    Text = "Hmm... Questo posto è..."
  },
  AvgDialog_18850_Content_49 = {
    Text = "La luce intensa fece venire ad Aigis la voglia di chiudere gli occhi, ma scoprì che non riusciva nemmeno a sbattere le palpebre."
  },
  AvgDialog_18850_Content_5 = {
    Text = "Io sono... Mythag..."
  },
  AvgDialog_18850_Content_50 = {
    Text = "Qualcosa teneva il suo sguardo fisso; poteva solo guardare impotente mentre un uomo in bianco appariva, impugnando un sottile bisturi."
  },
  AvgDialog_18850_Content_51 = {
    Text = "<Big:No, vi prego, signorina Sarah, signorina Sarah!>"
  },
  AvgDialog_18850_Content_52 = {
    Text = "La lama argentata traccia un lungo percorso scintillante seguendo i movimenti del ricercatore."
  },
  AvgDialog_18850_Content_53 = {
    Text = "<Big:Signorina Sarah! Tiyug! Aiuto! Salvatemi! Salvatemi!>"
  },
  AvgDialog_18850_Content_54 = {
    Text = "La Lama si avvicinò sempre di più, fino a consumare la mia Visuale. E poi, e poi—"
  },
  AvgDialog_18850_Content_55 = {
    Text = "<Shake:AAAAAHHH—!>"
  },
  AvgDialog_18850_Content_56 = {
    Text = "Nell'oscurità sconfinata, fluttuava da sola, come avvolta dall'acqua gelida di un lago.\nLe membra erano intorpidite e non riusciva a muoversi."
  },
  AvgDialog_18850_Content_57 = {
    Text = "Fa male... Quell'occhio fa così male..."
  },
  AvgDialog_18850_Content_58 = {
    Text = "Un caleidoscopio di colori sinuosi si insinuò. I colori, un liquido viscoso, si mescolavano a sangue e lacrime, scorrendo incessantemente."
  },
  AvgDialog_18850_Content_59 = {
    Text = "Mi sbagliavo. Sono chiaramente inutile... Non avrei dovuto... tentare l'impossibile."
  },
  AvgDialog_18850_Content_6 = {Text = "!?"},
  AvgDialog_18850_Content_60 = {
    Text = "Sostituì il lago, l'aria, l'odore, il suono, il tatto e la vita stessa.\nDivenne il suo intero mondo, avvolgendola in un abbraccio doloroso."
  },
  AvgDialog_18850_Content_61 = {
    Text = "Signorina Sarah... Tiyug... Aiutatemi... Mi fa male... Ho così tanto dolore..."
  },
  AvgDialog_18850_Content_62 = {
    Text = "I colori sinuosi si sollevarono rapidamente verso l'alto, e lei cadde improvvisamente in uno schermo di luce bianca. Un impulso sconosciuto si trasformò in una miriade di colori, inondandole gli occhi. Cercò di coprirsi gli occhi ma non riusciva a muoversi."
  },
  AvgDialog_18850_Content_63 = {
    Text = "Chi... sei...?"
  },
  AvgDialog_18850_Content_64 = {
    Text = "Il dolore lancinante alla fine si intorpidì. Dopo un tempo indefinito, riuscì finalmente a percepire un debole suono nel silenzio."
  },
  AvgDialog_18850_Content_65 = {
    Text = [[
Gli occhi della Veggente @2 sono semplicemente il materiale migliore.
Se non fosse stato per Sarah e questa ragazzina che si mettevano sempre in mezzo, li avrei usati per gli esperimenti molto tempo fa.]]
  },
  AvgDialog_18850_Content_66 = {
    Text = "Non è troppo tardi, Dottore. Abbiamo finalmente ottenuto @4@2, e questo merita di essere festeggiato!"
  },
  AvgDialog_18850_Content_67 = {
    Text = "Il rumore nelle mie orecchie—di chi era quella voce? Cosa stavano dicendo? Quando l'incubo finisce, tutto diventa confuso."
  },
  AvgDialog_18850_Content_68 = {
    Text = "Aigis si ritrovò seduta su una sedia a un certo punto, circondata da ricercatori in camice bianco. Parlavano con entusiasmo, ma lei non riusciva a sentire nulla."
  },
  AvgDialog_18850_Content_69 = {
    Text = "T-T'yog...?"
  },
  AvgDialog_18850_Content_7 = {
    Text = "Questo è... lo scomparso...!?"
  },
  AvgDialog_18850_Content_70 = {
    Text = "Il volto familiare davanti a me svanisce come acquerelli che si dissolvono. Prima che le iridi marroni vengano completamente sostituite dalla pietra bianca, esso—o lui—esalò il suo ultimo respiro."
  },
  AvgDialog_18850_Content_71 = {
    Text = "Ai... gis..."
  },
  AvgDialog_18850_Content_72 = {
    Text = "<Shake:Tyug—!!>"
  },
  AvgDialog_18850_Content_73 = {
    Text = "Quando mi sono svegliata, ero nella stanza, e Tyog si era già trasformato in... qualcosa di terribile."
  },
  AvgDialog_18850_Content_74 = {
    Text = "Se non fossi entrata avventatamente, se mi fossi resa conto di essere solo una nullità... Non li avrei provocati, e loro non avrebbero fatto quello a Tiyug."
  },
  AvgDialog_18850_Content_75 = {
    Text = "Impossibile, non può essere vero, non può essere vero...!"
  },
  AvgDialog_18850_Content_76 = {
    Text = "<Big:Smettila di fare la finta tonta!>"
  },
  AvgDialog_18850_Content_77 = {
    Text = "Jenkin spinse Sarah con forza, facendola quasi cadere a terra. Il topo sulla sua spalla condivideva la sua rabbia, mostrando i denti verso di lei."
  },
  AvgDialog_18850_Content_78 = {
    Text = "Dimmi, dove ha portato tutti quel maledetto dottore? Dove hanno portato mia sorella! Dimmi!"
  },
  AvgDialog_18850_Content_79 = {
    Text = "Jenkin, non...! La signorina Sarah, non lo ha fatto apposta, e non sapeva—"
  },
  AvgDialog_18850_Content_8 = {
    Text = "Hai trovato la persona? Come sta? Ha bisogno di assistenza?"
  },
  AvgDialog_18850_Content_80 = {
    Text = "Smettila di proteggerla! Tu sei ridotta così, quei pazzi sono diventati quello che sono, e mia sorella è scomparsa—tutto per colpa sua! Deve pagare!"
  },
  AvgDialog_18850_Content_81 = {
    Text = "Mi dispiace, mi dispiace..."
  },
  AvgDialog_18850_Content_82 = {
    Text = "...Erica, contatta la squadra investigativa. Abbiamo una richiesta di trasporto."
  },
  AvgDialog_18850_Content_83 = {
    Text = "Richiesta di assistenza per l'indagine in fase di invio.\nRichiesta inviata e confermata. La Squadra 3 arriverà alla posizione designata entro 3 ore."
  },
  AvgDialog_18850_Content_84 = {
    Text = "Per favore, signorina Sarah.\nDovrà attendere in ufficio fino all'arrivo del personale competente."
  },
  AvgDialog_18850_Content_85 = {
    Text = "Mi dispiace... Davvero... Mi dispiace..."
  },
  AvgDialog_18850_Content_86 = {
    Text = "Hai fatto qualche passo e hai notato che una piccola figura bianca mancava accanto a te."
  },
  AvgDialog_18850_Content_87 = {
    Text = "Potrebbe aver bisogno di un po' di tempo da sola."
  },
  AvgDialog_18850_Content_88 = {Text = "?"},
  AvgDialog_18850_Content_89 = {
    Text = "Non è niente. Andiamo."
  },
  AvgDialog_18850_Content_9 = {
    Text = "Il Mutante davanti a loro si contorceva nell'agonia. Il suo volto quasi umano si stirò e si distorse, poi si contrasse — in qualunque modo lo si guardasse, era chiaramente oltre ogni salvezza."
  },
  AvgDialog_18850_Content_90 = {Text = "Aigis?"},
  AvgDialog_18850_Content_91 = {
    Text = "Ti giri e vedi la ragazza in piedi, immobile."
  },
  AvgDialog_18850_Content_92 = {
    Text = "Cosa c'è, Aigis? Vuoi che ti riaccompagni a riposare?"
  },
  AvgDialog_18850_Content_93 = {
    Text = "...La signorina Sarah, starà bene?"
  },
  AvgDialog_18850_Content_94 = {
    Text = "Vogliamo solo farle qualche domanda. Non preoccuparti."
  },
  AvgDialog_18850_Content_95 = {Text = "Tornerà?"},
  AvgDialog_18850_Content_96 = {
    Text = "Lei... Potrebbe tornare."
  },
  AvgDialog_18850_Content_97 = {Text = "..."},
  AvgDialog_18850_Content_98 = {Text = "Aigis?"},
  AvgDialog_18850_Content_99 = {
    Text = "Va tutto bene... Andiamo, {Male=Mr.,Female=Miss} %player%.\nStarò bene."
  },
  AvgDialog_18851_Content_1 = {
    Text = [[
13:37, Londinium Est
La Zanna di Lily]]
  },
  AvgDialog_18851_Content_10 = {
    Text = "Tirò fuori dalla tasca un pezzo di metallo e un chiodo sottile e li inserì nella serratura. Il topo si drizzò sulla sua spalla, guardandosi intorno con cautela con le zampette anteriori."
  },
  AvgDialog_18851_Content_11 = {
    Text = "La serratura scattò con un lieve clic. Afferrò la maniglia, la girò e spinse la porta verso l'interno."
  },
  AvgDialog_18851_Content_12 = {
    Text = "Hehe, un gioco da ragazzi!"
  },
  AvgDialog_18851_Content_13 = {
    Text = [[
13:37, Londinium Est
La Zanna di Lily]]
  },
  AvgDialog_18851_Content_14 = {
    Text = "Signorina Sarah, perché non veste un po' la piccola Aigis? Oggi abbiamo ospiti importanti, non è vero?"
  },
  AvgDialog_18851_Content_15 = {
    Text = "Cosa ne sai tu? Vestirsi troppo bene ci fa sembrare ricchi, mentre vestirsi troppo male ci fa sembrare un pozzo senza fondo che allontana i donatori."
  },
  AvgDialog_18851_Content_16 = {
    Text = "Tirò il vestito di Aigis, poi le strofinò con forza la guancia con un po' di saliva sulla manica."
  },
  AvgDialog_18851_Content_17 = {
    Text = "Aigis, mia cara Aigis, ti ricordi cosa dire quando incontri lo sponsor?"
  },
  AvgDialog_18851_Content_18 = {
    Text = "Capito, Signorina Sarah. Sono stata ubbidiente, e lo stavo ancora recitando prima di andare a dormire ieri sera."
  },
  AvgDialog_18851_Content_19 = {
    Text = "Sarah annuì soddisfatta, poi guardò l'uomo di mezza età in piedi con le mani in tasca."
  },
  AvgDialog_18851_Content_2 = {
    Text = "Aigis, che stai ancora facendo? Lo sponsor sta arrivando!"
  },
  AvgDialog_18851_Content_20 = {
    Text = "Stai attento, e non dire nulla di superfluo, capito?"
  },
  AvgDialog_18851_Content_21 = {Text = "Capito!"},
  AvgDialog_18851_Content_22 = {
    Text = "Stai dritto se hai capito, {Male=lui,Female=lei} stanno arrivando."
  },
  AvgDialog_18851_Content_23 = {
    Text = "Non ho trovato il portafoglio, ma ho incontrato un Corpo della Dissoluzione. Questo è quello che chiami rischio basso...?"
  },
  AvgDialog_18851_Content_24 = {
    Text = "Prima che tu finisca di parlare, una voce familiare riecheggia nella tua mente."
  },
  AvgDialog_18851_Content_25 = {
    Text = "Le circostanze si evolvono, Custode, così come le missioni. \nO stai mettendo in dubbio la competenza di William?"
  },
  AvgDialog_18851_Content_26 = {
    Text = "Mi fido completamente del giudizio del Signor Delapur. Il Fenomeno-D deve essersi aggravato!"
  },
  AvgDialog_18851_Content_27 = {
    Text = [[
Riflessi pronti. 
Ora concentrati: i Mutanti indicano la vicinanza al tuo obiettivo.]]
  },
  AvgDialog_18851_Content_28 = {
    Text = "Esatto. Guarda."
  },
  AvgDialog_18851_Content_29 = {
    Text = "Guardi nella direzione che ha indicato. Non lontano si trova una porta di metallo con la scritta \"Laboratorio di Lillian\", con tre persone davanti."
  },
  AvgDialog_18851_Content_3 = {
    Text = "Eccomi. Scusa, signorina Sarah. Io... non volevo farti aspettare."
  },
  AvgDialog_18851_Content_30 = {
    Text = "Rapporto: Arrivati alla posizione della missione."
  },
  AvgDialog_18851_Content_31 = {
    Text = "Posizione della missione confermata. Verificare gli obiettivi della missione: infiltrarsi nel laboratorio, recuperare lo studente scomparso, confermare l'identità della forma di vita sconosciuta e fermarne le azioni."
  },
  AvgDialog_18851_Content_32 = {
    Text = "Obiettivi della missione verificati. Ingresso nel laboratorio imminente. Mantenere le comunicazioni."
  },
  AvgDialog_18851_Content_33 = {
    Text = "Ramona ti guarda."
  },
  AvgDialog_18851_Content_34 = {
    Text = "Allora? Sei pronto?"
  },
  AvgDialog_18851_Content_35 = {
    Text = "Ce la posso fare, purché le persone all'interno non siano come quei ragazzi di prima."
  },
  AvgDialog_18851_Content_36 = {
    Text = "<Small:...Non come Doll.>"
  },
  AvgDialog_18851_Content_37 = {
    Text = "Ti rendi conto che i Comunicatori d'Argento sono eccezionalmente sensibili?"
  },
  AvgDialog_18851_Content_38 = {
    Text = "<Shake:Coff, coff!>"
  },
  AvgDialog_18851_Content_39 = {
    Text = "State tranquillo. Difenderò la vostra spilla e i vostri Gemelli da Polso a costo della vita, {Male=Lord,Female=Lady} Ashe."
  },
  AvgDialog_18851_Content_4 = {
    Text = "Va bene, ormai siete tutti adulti, quindi smettetela di fare i bambini. Sbrigatevi! Non sarà un bene se arriviamo in ritardo..."
  },
  AvgDialog_18851_Content_40 = {
    Text = "Mi affiderò a te, cara cameriera Signorina Mary."
  },
  AvgDialog_18851_Content_41 = {
    Text = "Continua a scherzare con le tue identità sotto copertura e te ne pentirai durante l'addestramento correttivo."
  },
  AvgDialog_18851_Content_5 = {
    Text = "La ragazza seguì obbediente, voltandosi silenziosamente per salutare la pianta in vaso nell'angolo.\nQuando i passi si allontanarono, la ragazza col topo spuntò fuori dalle foglie verdi."
  },
  AvgDialog_18851_Content_6 = {
    Text = "Finalmente! Quella donna insopportabile è sempre in ufficio, anche di notte. Oggi finalmente ho la mia occasione!"
  },
  AvgDialog_18851_Content_7 = {
    Text = "Squeak! Squeak, squeak!"
  },
  AvgDialog_18851_Content_8 = {
    Text = "Tranquillo, Aigis ha detto che oggi fanno quel tour autogestito e non torneranno prima di mezzogiorno. Cercherò a fondo, senza tralasciare un solo capello."
  },
  AvgDialog_18851_Content_9 = {
    Text = "Durante le ore di lavoro, il corridoio residenziale era deserto. La ragazza arrivò davanti a una porta con la targhetta \"Ufficio dell'Amministratore\"."
  },
  AvgDialog_18852_Content_1 = {
    Text = "{Male=Lord,Female=Lady} Ashe, Miss Mary!"
  },
  AvgDialog_18852_Content_2 = {
    Text = "Stiamo bene. Fate solo indietreggiare tutti. Ce la caviamo noi."
  },
  AvgDialog_18852_Content_3 = {
    Text = "D'accordo, va bene. Oh cielo... Bambini, bambini, venite qui, presto."
  },
  AvgDialog_18852_Content_4 = {
    Text = "Muovetevi in fretta, è comparso un tipo pericoloso."
  },
  AvgDialog_18853_Content_1 = {
    Text = "La rivolta è finita e le persone si sono rimesse in fila.\nAigis era in piedi tra i bambini, pallida e leggermente tremante."
  },
  AvgDialog_18853_Content_10 = {
    Text = "Maledizione—"
  },
  AvgDialog_18853_Content_11 = {
    Text = "Cosa state facendo? Fermatevi!"
  },
  AvgDialog_18853_Content_2 = {
    Text = "Ecco questi, e—aggiungete Aigis.\nÈ la nostra bambina più amata."
  },
  AvgDialog_18853_Content_3 = {
    Text = "No, per favore... Non voglio andare, non voglio diventare... No..."
  },
  AvgDialog_18853_Content_4 = {
    Text = "Ascolta, Aigis, vieni qui. Non far perdere tempo agli adulti."
  },
  AvgDialog_18853_Content_5 = {
    Text = "Proprio quando il ricercatore allungò la mano, Jenkin saltò fuori all'improvviso, mettendosi davanti ad Aigis."
  },
  AvgDialog_18853_Content_6 = {
    Text = "Non hai sentito che ha detto di non voler andare?"
  },
  AvgDialog_18853_Content_7 = {
    Text = "Sei tu quella appena arrivata?"
  },
  AvgDialog_18853_Content_8 = {
    Text = "Che importa se è nuova o vecchia? Se Aigis non vuole andare, nessuno può costringerla!\nBrown, aiuto!"
  },
  AvgDialog_18853_Content_9 = {Text = "Squeak!"},
  AvgDialog_18854_Content_1 = {
    Text = "Tu e Ramona state sussurrando quando all'improvviso un forte trambusto esplode alle vostre spalle."
  },
  AvgDialog_18854_Content_2 = {
    Text = "Attenzione fuori! Il paziente è scappato! È scappato!"
  },
  AvgDialog_18854_Content_3 = {Text = "!"},
  AvgDialog_18855_Content_1 = {
    Text = "Il canto inudibile ti guida avanti attraverso l'illusione. Avanzi nella nebbia ma non riesci mai a scorgere la fine."
  },
  AvgDialog_18855_Content_10 = {
    Text = "Tieni d'occhio i dintorni per me."
  },
  AvgDialog_18855_Content_11 = {
    Text = [[
Ti inginocchi a terra, evitando le macchie di sangue, per ispezionare.
Nessun segno di pietrificazione, ma noti diverse impronte con sfumature strane vicino al corpo.]]
  },
  AvgDialog_18855_Content_12 = {
    Text = "D-melma? Sul cadavere... Potrebbe essere dell'assassino?"
  },
  AvgDialog_18855_Content_13 = {
    Text = [[
In questa zona ci sono solo tracce di D-melma oltre al laboratorio.
Non credo sia una coincidenza.]]
  },
  AvgDialog_18855_Content_14 = {
    Text = "Questo quasi dimostra che il colpevole proviene dal laboratorio. Le domande rimanenti sono: Chi è? Dove si nasconde nel laboratorio? È la forma di vita sconosciuta che stai cercando?"
  },
  AvgDialog_18855_Content_15 = {
    Text = "Aspetta un momento, queste dimensioni... Sono impronte di bambino?!"
  },
  AvgDialog_18855_Content_16 = {Text = "?!"},
  AvgDialog_18855_Content_17 = {
    Text = "...In effetti, sembra dirigersi verso il laboratorio."
  },
  AvgDialog_18855_Content_18 = {
    Text = "Sbrigati, trova il bambino prima che si nasconda."
  },
  AvgDialog_18855_Content_19 = {
    Text = [[
20:47, Laboratorio di Lily
Ccorridoio]]
  },
  AvgDialog_18855_Content_2 = {
    Text = "Gli edifici ai lati della strada ti osservano in silenzio con le loro finestre scure. I tuoi passi riecheggiano nella nebbia, creando l'illusione che tu stia correndo da solo su questa strada da molto tempo."
  },
  AvgDialog_18855_Content_20 = {
    Text = "Nella nebbia pervasiva, il laboratorio sembrava ancora più freddo e sinistro.\nUn uomo con un bastone di legno alla cintura pattugliava i corridoi vuoti e bui, reggendo una lanterna."
  },
  AvgDialog_18855_Content_21 = {
    Text = "Niente luci accese, risparmiare elettricità—**. Quella Sarah è così tirchia. E così pignola! Chi vorrebbe rapinare questo buco, comunque... Eh?"
  },
  AvgDialog_18855_Content_22 = {
    Text = "Nella luce fioca, una porta si apre silenziosamente."
  },
  AvgDialog_18855_Content_23 = {
    Text = "Chi, chi c'è?"
  },
  AvgDialog_18855_Content_24 = {
    Text = "Strinse forte il bastone e trovò il coraggio di fare un passo avanti."
  },
  AvgDialog_18855_Content_25 = {
    Text = "La lanterna antiquata si spense improvvisamente."
  },
  AvgDialog_18855_Content_26 = {Text = "!!!"},
  AvgDialog_18855_Content_27 = {
    Text = "Una forza invisibile lo trascinò dentro. La porta di legno si chiuse di colpo, e il corridoio tornò al silenzio e alla quiete."
  },
  AvgDialog_18855_Content_28 = {
    Text = [[
20:43, Laboratorio di Lily
Ccorridoio]]
  },
  AvgDialog_18855_Content_29 = {
    Text = "Due ragazze si stringono nella debole luce della lanterna, guardandosi intorno di continuo."
  },
  AvgDialog_18855_Content_3 = {
    Text = "Nulla ha un inizio o una fine. Continuerai ad andare avanti finché la tua vita non si esaurirà, finché il tempo—"
  },
  AvgDialog_18855_Content_30 = {
    Text = "Passi lontani echeggiano nel corridoio silenzioso, quasi laceranti."
  },
  AvgDialog_18855_Content_31 = {
    Text = "C-chi va là?\nFatti vedere! Sono armato, ti avverto!"
  },
  AvgDialog_18855_Content_32 = {
    Text = "L'aria non circola nel corridoio, eppure la fiamma tremola come soffiata dal vento."
  },
  AvgDialog_18855_Content_33 = {
    Text = "Il vassoio nelle mani di Aigis tremava, la tazza bianca e il piattino tintinnavano insieme, echeggiando i lamenti di un uccellino morente."
  },
  AvgDialog_18855_Content_34 = {
    Text = "I passi si avvicinano. Gli artigli di Brown affondano nella spalla di Jenkin, i denti scoperti e un sibilo acuto."
  },
  AvgDialog_18855_Content_35 = {
    Text = "Come spronati dalla voce di Brown, i passi si fecero improvvisamente più rapidi, dirigendosi dritti verso le due."
  },
  AvgDialog_18855_Content_36 = {
    Text = "Un'ombra densa inghiottì completamente la fioca luce della candela. Le ragazze chiusero gli occhi, sentendo solo un'ondata di nebbia colpirle in viso."
  },
  AvgDialog_18855_Content_37 = {
    Text = "Una mano emerse dall'oscurità, posandosi con precisione sulla tazza tremante e facendola tacere."
  },
  AvgDialog_18855_Content_38 = {
    Text = "Che vi succede? Perché siete così pallide?"
  },
  AvgDialog_18855_Content_39 = {
    Text = "Signor Rogers!\nÈ così buio qui. Noi..."
  },
  AvgDialog_18855_Content_4 = {
    Text = "Il Sapore del Sangue"
  },
  AvgDialog_18855_Content_40 = {
    Text = "Una notte nebbiosa è davvero snervante e fa battere il cuore, non è vero?"
  },
  AvgDialog_18855_Content_41 = {
    Text = "Rogers spinge la porta aperta, e una luce calda si riversa fuori, dissipando le ombre profonde del corridoio."
  },
  AvgDialog_18855_Content_42 = {
    Text = "Grazie per avermi portato da mangiare, Aigis, Jenkin."
  },
  AvgDialog_18855_Content_43 = {
    Text = "Rogers prese il vassoio e lo posò sul tavolino, poi portò una bambola finemente lavorata dal letto, sorridendo alle due ragazze."
  },
  AvgDialog_18855_Content_44 = {
    Text = "Come ricompensa, che ne dite di una carezza?\nGeorge ne sarà molto felice."
  },
  AvgDialog_18855_Content_45 = {
    Text = "Gli occhi inorganici della bambola riflettono la luce gialla della lampada, implorando in silenzio: Toccami, ti prego. Basta un solo tocco."
  },
  AvgDialog_18855_Content_46 = {
    Text = "Toccami, e—"
  },
  AvgDialog_18855_Content_47 = {
    Text = "Diventa il mio fedele amico."
  },
  AvgDialog_18855_Content_5 = {
    Text = [[
Torni improvvisamente in te, percependo in ritardo un odore pungente, dolciastro e metallico.
Rallentando il passo, ti avvicini all'ombra distesa a terra davanti a te.]]
  },
  AvgDialog_18855_Content_6 = {
    Text = "Sono i resti distrutti di una donna. La sua cavità addominale aperta emana ancora calore, il suo volto è una massa indistinta di carne, ed entrambe le braccia mancano — le sezioni trasversali sono nette, come se qualcuno le avesse recise con precisione."
  },
  AvgDialog_18855_Content_7 = {
    Text = "Questa tecnica appartiene al Dissettore."
  },
  AvgDialog_18855_Content_8 = {
    Text = "\nSventrare e smembrare per prendere parti del corpo come trofei corrisponde perfettamente alle caratteristiche dello smembratore descritto nel rapporto di polizia.\nNon si riesce a capire chi sia più crudele: la Dissoluzione o l'assassino."
  },
  AvgDialog_18855_Content_9 = {
    Text = "Ma perché il canto di tracciamento spirituale ti ha condotto qui? L'abilità della forma di vita sconosciuta è chiaramente la pietrificazione. O forse ci sono più entità speciali qui?"
  },
  AvgDialog_18856_Content_1 = {
    Text = "Peso della Coscienza"
  },
  AvgDialog_18856_Content_10 = {
    Text = "Segui Sarah fino alla porta di metallo del laboratorio e vedi diverse persone in uniforme che trascinano via una bambina in lacrime che si dimena."
  },
  AvgDialog_18856_Content_11 = {
    Text = "È il Comitato."
  },
  AvgDialog_18856_Content_12 = {
    Text = "È questo che Doll intendeva per evacuazione? Perché sta succedendo così in fretta?"
  },
  AvgDialog_18856_Content_13 = {
    Text = "Lasciatela! Dove la state portando? Dove state portando Lucy?"
  },
  AvgDialog_18856_Content_14 = {Text = "Aspetta!"},
  AvgDialog_18856_Content_15 = {
    Text = "Tiri fuori una collana nascosta. La Chiave d'argento fluttua dritta sopra il tuo palmo, emanando una luce tenue."
  },
  AvgDialog_18856_Content_16 = {
    Text = "Custode dell'Università di Mythag %player%, Chiave N. K-0617, richiede di parlare con il capo della missione."
  },
  AvgDialog_18856_Content_17 = {
    Text = "La persona davanti a te distoglie lo sguardo dalla Chiave d'argento e ti saluta."
  },
  AvgDialog_18856_Content_18 = {
    Text = "<Blue:Comitato del Trattato di Mystia>, Capo della Terza Squadra di Risposta, responsabile del trasferimento relativo all'indagine sull'Organizzazione Speciale S."
  },
  AvgDialog_18856_Content_19 = {
    Text = "Non mi aspettavo di incontrare un nuovo Custode qui, è un onore, {Male=Sig.,Female=Sig.na} %player%."
  },
  AvgDialog_18856_Content_2 = {
    Text = [[
10:20, Laboratorio Lily
Ingresso dell'Ufficio dell'Amministratore]]
  },
  AvgDialog_18856_Content_20 = {
    Text = "Cos'è successo? Perché avete arrestato improvvisamente i membri della Zanna?"
  },
  AvgDialog_18856_Content_21 = {
    Text = "Mi permetta di spiegare."
  },
  AvgDialog_18856_Content_22 = {
    Text = "Il capitano ha fatto un cenno, e un agente vicino ha consegnato un sacchetto di carta."
  },
  AvgDialog_18856_Content_23 = {
    Text = "Apri il sacchetto e trovi all'interno un vecchio pigiama da bambina. I bordi sono macchiati di chiazze marrone scuro, indurite dal liquido essiccato."
  },
  AvgDialog_18856_Content_24 = {
    Text = "Arrivati alle 10:23 dopo aver ricevuto l'avviso di indagine congiunta dall'Università di Mythag, abbiamo iniziato la perquisizione preliminare del laboratorio per confermarne lo stato."
  },
  AvgDialog_18856_Content_25 = {
    Text = "Durante la perquisizione, abbiamo scoperto macchie di sangue nella vecchia stanza sul lato sud-est del primo piano del laboratorio, nonché una mannaia insanguinata nel ripostiglio sotto le scale."
  },
  AvgDialog_18856_Content_26 = {
    Text = "Dopo l'identificazione da parte dei membri del laboratorio, questa camicia da notte apparteneva a una bambina di nome Lucy. Considerando le macchie di sangue nella vecchia stanza e le testimonianze di urla udite la notte scorsa, abbiamo deciso di portarla in custodia per le indagini."
  },
  AvgDialog_18856_Content_27 = {
    Text = "Sono stata io a urlare! Mi ha spaventata un'ombra la notte scorsa, ma non è successo niente di male! Anche questo Custode l'ha visto, giusto?"
  },
  AvgDialog_18856_Content_28 = {
    Text = "Signore, questa faccenda non è così semplice come sembra. Sospettiamo il coinvolgimento di una terza parte, e questa bambina potrebbe essere sotto il controllo di qualcuno. Potrebbe per favore evitare di portarla via?"
  },
  AvgDialog_18856_Content_29 = {
    Text = "Siamo a conoscenza dell'evento dell'organizzazione illegale. Indipendentemente da qualsiasi manipolazione, il colpevole resta un colpevole. Dal punto di vista procedurale, non posso permettere che rimanga a piede libero."
  },
  AvgDialog_18856_Content_3 = {
    Text = "Prima ancora di raggiungere la porta dell'ufficio, una giovane donna ti è corsa incontro."
  },
  AvgDialog_18856_Content_30 = {
    Text = "Il Comitato si atterrà alle disposizioni pertinenti dell'<Accordo> durante le indagini e non la sottoporrà a trattamenti ingiusti. Posso assicurarglielo."
  },
  AvgDialog_18856_Content_31 = {
    Text = "Inoltre, l'auto per il vostro ritorno a scuola è pronta. Date le circostanze speciali, assegnerò due Agenti per accompagnarvi e garantire la vostra sicurezza. Prego, seguitemi."
  },
  AvgDialog_18856_Content_32 = {Text = "No."},
  AvgDialog_18856_Content_33 = {
    Text = "L'Associazione degli Scultori usa la cosiddetta ricerca come copertura, conducendo segretamente esperimenti umani nel laboratorio con il sostegno del finanziatore Rogers, il che ha portato al verificarsi di una dissoluzione anomala."
  },
  AvgDialog_18856_Content_34 = {
    Text = "Sulla base degli indizi attuali, oltre alla \"follia\" nel laboratorio, lo \"Smembratore\" attivo nel Distretto Est potrebbe essere un'altra manifestazione della Dissoluzione anomala."
  },
  AvgDialog_18856_Content_35 = {
    Text = "Abbiamo scoperto molto. L'unica cosa che manca è l'identità dello smembratore, che ci permetterà di svelare completamente la verità dietro l'evento e sventare il piano dello scultore. A questo punto, non possiamo andarcene."
  },
  AvgDialog_18856_Content_36 = {
    Text = "Comprendo il vostro desiderio di continuare le indagini, ma i miei ordini—"
  },
  AvgDialog_18856_Content_37 = {
    Text = "Ha premuto improvvisamente il bracciale del Comitato sul braccio, come se stesse ascoltando qualcosa.\nDev'essere il comunicatore d'Argento fornito dall'Università di Mythag. Ci sono nuovi ordini?"
  },
  AvgDialog_18856_Content_38 = {
    Text = "<Blue:Comandante Lydia>. Sì, il Custode non è disposto ad abbandonare le indagini.\nTre giorni? No, non la sto mettendo in discussione... Sì, capisco. Va bene, messaggio ricevuto."
  },
  AvgDialog_18856_Content_39 = {
    Text = "Salve, è un onore comunicare con lei, <Blue:Primo Custode>."
  },
  AvgDialog_18856_Content_4 = {
    Text = "Signorina Sarah, brutte notizie! Alcune persone stanno cercando di portare via Lucy!"
  },
  AvgDialog_18856_Content_40 = {
    Text = "Conosci solo una persona degna di quel titolo: il tuo mentore che risiede nel sottosuolo di Mythag. Nell'ultimo anno, non ha contattato nessuno tranne te e Doll. Potrebbe essere che..."
  },
  AvgDialog_18856_Content_41 = {
    Text = "Capito. Arrivederci, signore."
  },
  AvgDialog_18856_Content_42 = {
    Text = "Il capitano smette di parlare e si volta verso di te. Nel frattempo, senti la voce gentile del tuo maestro nella mente."
  },
  AvgDialog_18856_Content_43 = {
    Text = "Fai quello che ritieni giusto, %player%. Al resto penserò io.\nHo fiducia in te."
  },
  AvgDialog_18856_Content_44 = {
    Text = [[
Ti ha detto la stessa cosa prima che partissi.
Sembra che per ora non sia necessario tornare.]]
  },
  AvgDialog_18856_Content_45 = {
    Text = "Dopo aver consultato il Primo Custode, il Comitato ha deciso di permettere al Custode di continuare a indagare sull'Incidente del Laboratorio Lily. Tuttavia, avete solo tre giorni. Dopodiché, il caso verrà affidato a Investigatori più esperti."
  },
  AvgDialog_18856_Content_46 = {
    Text = "Mentre parlava, si è voltato e ha iniziato a dare ordini agli agenti circostanti."
  },
  AvgDialog_18856_Content_47 = {
    Text = "Trasferimento sospeso. Implementare immediatamente il blocco dell'area di Livello 5. Sospettata temporaneamente trattenuta. L'interrogatorio seguirà dopo il trasferimento."
  },
  AvgDialog_18856_Content_48 = {
    Text = "No, no! Vi prego, vi darò qualsiasi cosa, ma non portatela via! Lucy, <Big:Lucy—>"
  },
  AvgDialog_18856_Content_49 = {
    Text = "Non è stata lei, non è stata lei! %player%! Per favore, aiuta Lucy, aiutala!"
  },
  AvgDialog_18856_Content_5 = {Text = "C-Cosa?!"},
  AvgDialog_18856_Content_50 = {
    Text = "Mi dispiace, ma questo è un ordine assoluto e devo eseguirlo.\nDetto questo, mi congedo."
  },
  AvgDialog_18856_Content_51 = {
    Text = "Giuro di squarciare le tenebre con la mia spada."
  },
  AvgDialog_18856_Content_52 = {
    Text = "Ti ha salutato di nuovo, ignorando le grida di Lucy e le suppliche di Sarah e Aigis, ha ordinato ai suoi uomini di prendere la bambina e si è diretto verso il veicolo in attesa."
  },
  AvgDialog_18856_Content_53 = {
    Text = "La portiera dell'auto si chiuse, bloccando ogni vista. Una dopo l'altra, le auto si allontanarono. Sarah, completamente priva di forze, crollò in ginocchio."
  },
  AvgDialog_18856_Content_54 = {
    Text = "<Small:Sono inutile, sono disgustosa, non sono una buona direttrice, non riesco a proteggere nessuno, non riesco a proteggere i bambini...>"
  },
  AvgDialog_18856_Content_55 = {
    Text = "Signorina Sarah, la prego... Lo capiamo tutti. Ha fatto del suo meglio."
  },
  AvgDialog_18856_Content_56 = {
    Text = [[
<Small:Perdonatemi, Little Mike, perdonami, Aigis, perdonami... Jenkin... 
Perdonami, Diana, Henry e piccola Lucy...>]]
  },
  AvgDialog_18856_Content_57 = {
    Text = "Si rannicchia, stringendosi la testa tra le braccia. I suoi sussurri di pianto si fanno rochi e caotici, fino a diventare indistinguibili."
  },
  AvgDialog_18856_Content_58 = {
    Text = "Signorina Sarah...?"
  },
  AvgDialog_18856_Content_59 = {
    Text = "Il laboratorio vivacemente animato piombò improvvisamente in un silenzio glaciale, come se fosse stato sommerso sott'acqua.\nUna pressione invisibile ti colpisce dal nulla, facendoti boccheggiare e capire che qualcosa non va."
  },
  AvgDialog_18856_Content_6 = {
    Text = "Indossavano uniformi sconosciute e avevano un aspetto feroce e aggressivo. Dopo una rapida ispezione, hanno dichiarato Lucy sospettata e non è stato possibile fermarli."
  },
  AvgDialog_18856_Content_60 = {
    Text = "No! Ramona! Porta tutti gli altri fuori di qui!"
  },
  AvgDialog_18856_Content_61 = {
    Text = "Non c'è più tempo.\nLa testa della giovane amministratrice si aprì come un fiore, spruzzando melma nera sul pavimento."
  },
  AvgDialog_18856_Content_62 = {
    Text = "S-signorina Sarah!!"
  },
  AvgDialog_18856_Content_63 = {
    Text = [[
Emise uno stridio acuto, e in lontananza risuonarono grida di risposta.
Arti contorti, Aberranti infettati dalla Dissoluzione si riversarono fuori dall'edificio.]]
  },
  AvgDialog_18856_Content_7 = {
    Text = "Come può essere Lucy?! Chiaramente..."
  },
  AvgDialog_18856_Content_8 = {
    Text = "Henry e Manny stanno tenendo la porta. Non so quanto potranno resistere. Fate presto!"
  },
  AvgDialog_18856_Content_9 = {
    Text = "Sarah si è subito sollevata la gonna e si è messa a correre fuori."
  },
  AvgDialog_18857_Content_1 = {
    Text = "Notte Senza Uccelli"
  },
  AvgDialog_18857_Content_10 = {
    Text = "Come se non l'avesse vista, la ragazza continuò a camminare in avanti, passo dopo passo."
  },
  AvgDialog_18857_Content_11 = {
    Text = "Mentre le passava accanto, Aigis udì un canto estremamente flebile."
  },
  AvgDialog_18857_Content_12 = {
    Text = "<Italic:Il soriano del vecchio Charlie, grasso e caro...>"
  },
  AvgDialog_18857_Content_13 = {
    Text = "Lucy, dove stai andando? Dammi il coltello, Lucy!"
  },
  AvgDialog_18857_Content_14 = {
    Text = "Che freddo... Questo è... l'esterno? Come sono finita qui?"
  },
  AvgDialog_18857_Content_15 = {
    Text = "Stavo chiaramente dormendo nella mia stanza, ma il piccolo Mike continuava a fare storie... Ugh, mi fanno male gli occhi..."
  },
  AvgDialog_18857_Content_16 = {
    Text = "Pazzo... Pazzo! Stai lontano! Non avvicinarti!"
  },
  AvgDialog_18857_Content_17 = {
    Text = "Signora, ha bisogno d'aiuto? Non abbia paura. Chiamo subito qualcuno—"
  },
  AvgDialog_18857_Content_18 = {
    Text = "Aiuto! C'è qualcuno là fuori? Per favore, salvatemi!"
  },
  AvgDialog_18857_Content_19 = {
    Text = "Io... non riesco a muovermi?! Perché, perché il mio corpo non si muove?"
  },
  AvgDialog_18857_Content_2 = {
    Text = "La nebbia si addensa, rendendo il corridoio già stretto ancora più profondo, finché non viene completamente divorato dall'oscurità."
  },
  AvgDialog_18857_Content_20 = {
    Text = "Che bambina speciale, per essere riuscita a riprendere conoscenza."
  },
  AvgDialog_18857_Content_21 = {
    Text = "Chi sei? C-cosa hai intenzione di fare a questa signora?"
  },
  AvgDialog_18857_Content_22 = {
    Text = "Io? No, no, no, ti sbagli. Non sono io che voglio farle qualcosa."
  },
  AvgDialog_18857_Content_23 = {
    Text = "La... la mia mano... cosa è successo...?"
  },
  AvgDialog_18857_Content_24 = {
    Text = "Sta a te decidere cosa fare di lei."
  },
  AvgDialog_18857_Content_25 = {
    Text = "Non uccidermi, <Big:Ti prego, non uccidermi!>"
  },
  AvgDialog_18857_Content_26 = {
    Text = "Non sono stata io, non sono stata io! Posa il coltello! Corri, corri!"
  },
  AvgDialog_18857_Content_27 = {
    Text = "<BigShake:AHHH—!>"
  },
  AvgDialog_18857_Content_28 = {
    Text = "Mi dispiace... Mi dispiace tanto..."
  },
  AvgDialog_18857_Content_29 = {
    Text = "Corri, sbrigati!"
  },
  AvgDialog_18857_Content_3 = {
    Text = "La candela tremola nell'aria umida, faticando a illuminare una piccola area. Al limite della luce, nel profondo dell'oscurità, qualcosa si sta avvicinando."
  },
  AvgDialog_18857_Content_30 = {
    Text = "Il soriano del vecchio Charlie, grasso e caro..."
  },
  AvgDialog_18857_Content_31 = {
    Text = "Le mie gambe... Le mie gambe non si muovono! Aiutatemi! Aiutatemi!"
  },
  AvgDialog_18857_Content_32 = {Text = "Signora!"},
  AvgDialog_18857_Content_33 = {
    Text = "Senpai, non andare! Senpai!"
  },
  AvgDialog_18857_Content_34 = {
    Text = "La prego, misterioso signore, la prego non faccia questo."
  },
  AvgDialog_18857_Content_35 = {
    Text = "Un giorno lei scomparve, e lui la cercò ovunque."
  },
  AvgDialog_18857_Content_36 = {
    Text = "Presto, contattate la scuola!"
  },
  AvgDialog_18857_Content_37 = {
    Text = "Non voglio far loro del male, la prego. Farò tutto quello che dice, solo—non faccia loro del male."
  },
  AvgDialog_18857_Content_38 = {
    Text = "Frugò nell'armadio. Controllò sotto il letto."
  },
  AvgDialog_18857_Content_39 = {
    Text = "<Shake:D-dietro di te!>"
  },
  AvgDialog_18857_Content_4 = {
    Text = "Il fruscio si trasformò in passi leggeri mentre una figura vaga si avvicinava lentamente a quest'isola fiocamente illuminata."
  },
  AvgDialog_18857_Content_40 = {
    Text = "Vagò per la cantina con la caldaia accesa."
  },
  AvgDialog_18857_Content_41 = {Text = "Ah... Ah!!"},
  AvgDialog_18857_Content_42 = {
    Text = "La prego! Signore! La prego, non lo faccia! No, no, no!"
  },
  AvgDialog_18857_Content_43 = {
    Text = "Il vecchio Charlie non riusciva a trovare la sua gatta soriana da nessuna parte."
  },
  AvgDialog_18857_Content_44 = {
    Text = "<Shake:No, no, non avvicinarti... Non avvicinarti... Ti prego, ti prego lasciami andare...>"
  },
  AvgDialog_18857_Content_45 = {
    Text = "Così pianse e pianse—"
  },
  AvgDialog_18857_Content_46 = {
    Text = "<Shake:Ho una sorellina... Vi prego... Risparmiatemi la vita...>"
  },
  AvgDialog_18857_Content_47 = {
    Text = "—Finché non scomparvi anch'io."
  },
  AvgDialog_18857_Content_48 = {
    Text = "<BigShake:Ahhh—!>"
  },
  AvgDialog_18857_Content_49 = {Text = "Non..."},
  AvgDialog_18857_Content_5 = {
    Text = "Piccola Lucy, dove sei andata? Sei stata via così a lungo stanotte, stavo iniziando a preoccuparmi—"
  },
  AvgDialog_18857_Content_50 = {
    Text = "Perché... Cosa abbiamo fatto di male... Perché dobbiamo sopportare tutto questo..."
  },
  AvgDialog_18857_Content_51 = {
    Text = "Il piccolo Mac restava impassibile, lo sguardo fisso davanti a sé, stringendo un coltello affilato. I suoi vestiti intrisi di sangue gocciolavano un liquido denso."
  },
  AvgDialog_18857_Content_52 = {
    Text = "Dietro di lui c'era una porta aperta, attraverso la quale si intravedeva un corpo straziato disteso nella stanza."
  },
  AvgDialog_18857_Content_53 = {
    Text = "Tutti hanno sentito quella voce, eppure nessuno la ricorda. Se... se la voce andasse a cercare Jenkin..."
  },
  AvgDialog_18857_Content_54 = {
    Text = "Povera bambina, stai cercando di fare qualcosa di futile ancora una volta?"
  },
  AvgDialog_18857_Content_55 = {
    Text = [[
...!
S-sei tu...! Malvagio, malvagio! Non controllare il piccolo Mike!]]
  },
  AvgDialog_18857_Content_56 = {
    Text = "Smettila di controllarlo! O, o lo dirò—dirò a..."
  },
  AvgDialog_18857_Content_57 = {
    Text = [[
Dirlo a chi, alla tua cara signorina Sarah?
Aigis, hai dimenticato come ha reagito l'ultima volta che le hai parlato?]]
  },
  AvgDialog_18857_Content_58 = {Text = "..."},
  AvgDialog_18857_Content_59 = {
    Text = [[
Pensa che tu stia avendo un incubo o vedendo un altro fantasma e si sta preparando a mandarti per un altro "controllo".
Le prove che presenti vengono liquidate come residui del "trattamento terapeutico" del dottore.]]
  },
  AvgDialog_18857_Content_6 = {Text = "!!"},
  AvgDialog_18857_Content_60 = {
    Text = "Vederti così sconvolta fa soffrire anche me, ma questa è la realtà crudele e orribile.\nSe i tuoi occhi non fossero utili, ti salverei e ti trasformerei in una bella Reliquia."
  },
  AvgDialog_18857_Content_61 = {
    Text = "Ora, continua con quello che stavi facendo prima: cancella le tracce, brucia le prove.\nÈ tutto ciò di cui sei capace."
  },
  AvgDialog_18857_Content_62 = {
    Text = "Il ragazzo se ne andò con un'espressione vuota.\nAigis entrò nella stanza e si inginocchiò accanto al corpo ancora caldo della guardia di sicurezza."
  },
  AvgDialog_18857_Content_63 = {
    Text = "Si tolse la benda dagli occhi. Le punte delle dita dell'uomo si irrigidirono immediatamente, diventando bianche come pietra. Un oggetto metallico rotondo rotolò fuori dalla sua mano indurita. Proprio mentre Aigis stava per raccoglierlo, sentì un urlo alle sue spalle."
  },
  AvgDialog_18857_Content_64 = {
    Text = "Ai, Aigis...?!"
  },
  AvgDialog_18857_Content_65 = {
    Text = "Ho ucciso quella persona, e proprio mentre stavo per disfarmi del corpo, la signorina Sarah mi ha vista."
  },
  AvgDialog_18857_Content_66 = {
    Text = "Mi ha tirata fuori, mi ha pulito il sangue dalle mani e mi ha assicurato che sarebbe andato tutto bene—\"lascia fare a lei\"."
  },
  AvgDialog_18857_Content_67 = {
    Text = "Ho appena controllato; la stanza è immacolata. La signorina Sarah deve averla pulita per me.\nE inoltre—"
  },
  AvgDialog_18857_Content_68 = {
    Text = [[
Tira fuori un gemello luccicante dall'orsacchiotto e te lo mostra.
Sia lo stile che il materiale sono identici a quello che hai trovato ieri.]]
  },
  AvgDialog_18857_Content_69 = {
    Text = "L'hai trovato, il gemello che avevo lasciato cadere lì."
  },
  AvgDialog_18857_Content_7 = {
    Text = "La figura emerse gradualmente alla vista. Era una bambina, inespressiva, con lo sguardo fisso davanti a sé, che stringeva un pugnale dalla cui punta gocciolava sangue."
  },
  AvgDialog_18857_Content_70 = {
    Text = "Non ci posso credere. A prescindere dalle tue motivazioni, tu non sei quel tipo di persona, Aigis.\nSei una brava bambina. Dicci la verità e troveremo una soluzione insieme, va bene?"
  },
  AvgDialog_18857_Content_71 = {
    Text = "......\nNon vi ho mai detto come è morto Tyug."
  },
  AvgDialog_18857_Content_72 = {
    Text = "Aigis rimosse la benda dal suo occhio destro, rivelando un occhio pallido, simile alla pietra."
  },
  AvgDialog_18857_Content_73 = {Text = "Sono io."},
  AvgDialog_18857_Content_74 = {
    Text = "L'ho trasformato in pietra."
  },
  AvgDialog_18857_Content_75 = {
    Text = "Aigis, noi—"
  },
  AvgDialog_18857_Content_76 = {
    Text = "Basta parlare! Io... sono la vera colpevole."
  },
  AvgDialog_18857_Content_77 = {
    Text = "Fece un passo indietro, circondata da una melma nera apparsa senza che nessuno se ne accorgesse, pronta a colpire."
  },
  AvgDialog_18857_Content_8 = {
    Text = "<Shake:Q-q-questa... Lucy...? Tu, tu hai u-u-ucciso...?>"
  },
  AvgDialog_18857_Content_9 = {
    Text = "Non poté fare a meno di voltarsi e vomitare la sua magra cena in un angolo."
  },
  AvgDialog_18858_Content_1 = {
    Text = "Quelli sono... i pazienti? Quelli che Aigis ha detto avevano segni neri? È in questo che si trasformano?"
  },
  AvgDialog_18858_Content_2 = {
    Text = "Queste sono... le persone scomparse?"
  },
  AvgDialog_18859_Content_1 = {
    Text = "Nello spazio di nero puro, innumerevoli deboli punti argentei formano una distesa scintillante, ondulando come onde seguendo uno schema imperscrutabile."
  },
  AvgDialog_18859_Content_10 = {
    Text = "La luce si ritira, lo spazio nero si dissolve rapidamente."
  },
  AvgDialog_18859_Content_11 = {
    Text = "Apri gli occhi e incontri lo sguardo smarrito di Jenkin."
  },
  AvgDialog_18859_Content_12 = {
    Text = [[
01:14, Laboratorio Lilyan
Stanza degli ospiti]]
  },
  AvgDialog_18859_Content_13 = {
    Text = "%player%...? Che è successo? Qualcosa non va?"
  },
  AvgDialog_18859_Content_14 = {
    Text = "Jenkin si strofinò gli occhi e cercò di mettersi seduto, solo per scoprire di avere le mani legate dietro la schiena."
  },
  AvgDialog_18859_Content_15 = {
    Text = "Che diav—?! Chi è stato? Lasciatemi andare!"
  },
  AvgDialog_18859_Content_16 = {
    Text = "Fai un cenno a Ramona, e lei sfodera rapidamente il suo stocco, tagliando con precisione la corda attorno al polso di Jenkin."
  },
  AvgDialog_18859_Content_17 = {
    Text = "Scusa, qualcosa è andato storto e abbiamo dovuto prendere alcune misure protettive.\nTu... ricordi cosa hai appena fatto?"
  },
  AvgDialog_18859_Content_18 = {
    Text = "Non stavo semplicemente dormendo? Con Brown e Aigis, ho fatto un sogno così caotico... Aspetta, questa non è la stanza di Aigis. Come sono finito qui?"
  },
  AvgDialog_18859_Content_19 = {
    Text = "Cosa volete da me? Avete intenzione di rapirmi e farmi tacere?"
  },
  AvgDialog_18859_Content_2 = {
    Text = [[
Fai parte di tutto questo eppure ne sei separato. Appartieni ma ti senti fuori posto.
Non sai cosa siano; sai solo che sei qui per trovare qualcuno.]]
  },
  AvgDialog_18859_Content_20 = {
    Text = "Non sarebbe conforme agli standard e al codice degli Investigatori dell'Università di Mythag."
  },
  AvgDialog_18859_Content_22 = {
    Text = "La spada di Ramona guizza fuori. La lama d'argento si libra al collo di Clementine, ma lei non mostra alcun terrore, deviando lo stocco con due dita."
  },
  AvgDialog_18859_Content_23 = {
    Text = "Osservi con diffidenza: porte e finestre chiuse, eppure è apparsa come un fantasma."
  },
  AvgDialog_18859_Content_24 = {
    Text = "Chi sei? Come fai a sapere chi siamo?"
  },
  AvgDialog_18859_Content_25 = {
    Text = [[
Sei de Gli scultori? E poco fa nella nebbia, le tue ali...
Sei... umana?]]
  },
  AvgDialog_18859_Content_26 = {
    Text = [[
Sono solo una terza parte disponibile, anche se nutro un certo interesse personale.
Mi incuriosisci, Investigatore speciale.]]
  },
  AvgDialog_18859_Content_27 = {
    Text = "Sorride, lo sguardo carico di uno strano fervore."
  },
  AvgDialog_18859_Content_28 = {
    Text = "...Perché?"
  },
  AvgDialog_18859_Content_29 = {
    Text = "Questo va oltre le mie capacità di speculazione.\nSolo quell'essere supremo può fornirti le risposte che cerchi."
  },
  AvgDialog_18859_Content_3 = {
    Text = "\"Sorella... Sorella...\""
  },
  AvgDialog_18859_Content_30 = {
    Text = "Ma come scusa, non mi dispiace rispondere alla tua domanda precedente.\nCome sospettavi, il cuore umano è fatto di carne, ma il mio è un cuore d'Argento."
  },
  AvgDialog_18859_Content_31 = {
    Text = "Stando così le cose, non possiamo lasciarti andare."
  },
  AvgDialog_18859_Content_32 = {
    Text = [[
Se fossi sola, verrei volentieri con voi.
Ma devo pensare ai miei pazienti; non possono fare a meno di me in questo momento.]]
  },
  AvgDialog_18859_Content_33 = {
    Text = "Dal nulla estrae uno strano pendente. Una fatica opprimente ti colpisce, costringendoti ad appoggiarti al tavolo per restare in piedi."
  },
  AvgDialog_18859_Content_34 = {
    Text = [[
Il fioretto di Ramona si abbassa, la testa ciondola, gli occhi a malapena aperti.
Jenkin giace immobile, apparentemente addormentato.]]
  },
  AvgDialog_18859_Content_35 = {
    Text = "Cosa... hai fatto..."
  },
  AvgDialog_18859_Content_36 = {
    Text = "Un piccolo trucco per permettermi di andarmene.\nCon le tue capacità, dovrebbe essere facile da dissipare."
  },
  AvgDialog_18859_Content_37 = {
    Text = "Arrivederci, <Blue:Occhio Cieco Pallido>. Ci rivedremo qui..."
  },
  AvgDialog_18859_Content_38 = {
    Text = "Ti fa un inchino e lascia la stanza. Incapace di resistere oltre, ti accasci sulla sedia."
  },
  AvgDialog_18859_Content_39 = {
    Text = "Clementine chiude la porta, canticchiando allegramente. Saluta con la mano lungo il corridoio, poi se ne va."
  },
  AvgDialog_18859_Content_4 = {
    Text = "Guardi verso il suono. Una luce particolarmente fioca tremola nel mare di stelle. Fili neri, con un sinistro luccichio metallico, la avvolgono e la tengono immobile."
  },
  AvgDialog_18859_Content_40 = {
    Text = "Nell'oscurità, la fanciulla in vestito resta immobile come una statua.\nA capo chino, stringe con forza una benda bianca."
  },
  AvgDialog_18859_Content_5 = {
    Text = [[
Una melodia allegra emana debolmente dalla linea nera, come una filastrocca cantata da bambini.
Il vecchio Charlie ha un gatto soriano che ama tantissimo...]]
  },
  AvgDialog_18859_Content_6 = {
    Text = "\"Sorella... non andartene...\""
  },
  AvgDialog_18859_Content_7 = {
    Text = "La voce di Jenkin emerse dalla sfera di luce. Tentò di avvicinarsi a te, ma fu istantaneamente legata dai fili neri, costringendola a ritirarsi come una marionetta sotto controllo."
  },
  AvgDialog_18859_Content_8 = {
    Text = [[
Comprendi che qualcosa, o qualcuno, la sta controllando.
Mentre ti muovi per aiutarla, i fili si assottigliano e svaniscono.]]
  },
  AvgDialog_18859_Content_9 = {
    Text = "\"No... Aigis...?\""
  },
  AvgDialog_18860_Content_1 = {
    Text = "Insegui Aigis fino in cima alla torre dell'orologio."
  },
  AvgDialog_18860_Content_2 = {
    Text = "Aigis era in piedi sulla piattaforma, si voltò, e lacrime miste a sangue e D-melma scorrevano dal suo occhio coperto."
  },
  AvgDialog_18860_Content_3 = {
    Text = "Mi dispiace... Io... non riesco più a resistere..."
  },
  AvgDialog_18860_Content_4 = {
    Text = "Il suo corpo si gonfiò rapidamente, la carne ribolliva in grumi di varie dimensioni, bloccando velocemente la scala e raggiungendo il soffitto alto."
  },
  AvgDialog_18860_Content_5 = {
    Text = "Tra suoni orribili di arti che si contorcono, solo una faint traccia della voce della ragazza permane."
  },
  AvgDialog_18860_Content_6 = {
    Text = "<Shake:Corri... corri...>"
  },
  AvgDialog_18861_Content_1 = {
    Text = "Le Apparenze Ingannano"
  },
  AvgDialog_18861_Content_10 = {
    Text = "Un giorno lei scomparve, e lui la cercò ovunque."
  },
  AvgDialog_18861_Content_11 = {
    Text = "Vai avanti tu! Non preoccuparti per noi! Contatta subito la scuola!"
  },
  AvgDialog_18861_Content_12 = {
    Text = "Frugò nell'armadio. Controllò sotto il letto."
  },
  AvgDialog_18861_Content_13 = {
    Text = "<Shake:D-dietro di te!>"
  },
  AvgDialog_18861_Content_15 = {
    Text = "Gli artigli nerissimi squarciarono la nebbia, afferrando i capelli della donna."
  },
  AvgDialog_18861_Content_16 = {
    Text = "Un nastro rosso fluttua dolcemente verso il basso, e il contorno di un occhio gigante appare improvvisamente nelle ombre."
  },
  AvgDialog_18861_Content_17 = {
    Text = "Vagò per la cantina con la caldaia accesa."
  },
  AvgDialog_18861_Content_18 = {
    Text = "Gli occhi del giovane batterono al ritmo della filastrocca, e il suo volto perse istantaneamente colore e si irrigidì.\nAprì la bocca, e un urlo si congelò insieme al suo corpo, trasformandolo in una statua."
  },
  AvgDialog_18861_Content_19 = {Text = "Ah... Ah!!"},
  AvgDialog_18861_Content_2 = {
    Text = "Una fitta Nebbia avvolge le strade umide e buie. Le luci fioche si riflettono nelle pozzanghere, come se contemplassero questo mondo desolato."
  },
  AvgDialog_18861_Content_20 = {
    Text = "Il vecchio Charlie non riusciva a trovare la sua gatta soriana da nessuna parte."
  },
  AvgDialog_18861_Content_21 = {
    Text = "<Shake:No, no, per favore... Per favore, lasciatemi andare...>"
  },
  AvgDialog_18861_Content_22 = {
    Text = "Così pianse e pianse—"
  },
  AvgDialog_18861_Content_23 = {
    Text = "<Shake:Ho una sorellina... Vi prego... Risparmiatemi la vita...>"
  },
  AvgDialog_18861_Content_24 = {
    Text = "—Finché non scomparvi anch'io."
  },
  AvgDialog_18861_Content_25 = {
    Text = "<BigShake:Ahhh—!>"
  },
  AvgDialog_18861_Content_26 = {
    Text = "08:00, Università di Mythag, Edificio del Sistema Risvegliatore\nAll'interno dell'ufficio di William Draper"
  },
  AvgDialog_18861_Content_27 = {
    Text = [[
Ti sei seduto alla scrivania, esaminando attentamente gli oggetti nel vassoio sotto lo sguardo di William:
Una mano scolpita nella pietra incredibilmente realistica e un pezzo di nastro rosso ornato con una fibbia d'argento.]]
  },
  AvgDialog_18861_Content_28 = {Text = "Allora?"},
  AvgDialog_18861_Content_29 = {
    Text = "Sei un po' nervoso. William non è solo il tuo senpai, ma anche il tuo istruttore di addestramento.\nAnche se ora sei un Custode a tutti gli effetti, hai ancora la sensazione di essere valutato da lui."
  },
  AvgDialog_18861_Content_3 = {
    Text = "Una scarpa di cuoio frantumò il riflesso nella pozzanghera e si allontanò in fretta."
  },
  AvgDialog_18861_Content_30 = {
    Text = "Sembra essere una parte della statua. Tuttavia, una statua cava? È la prima volta per me.\nE all'interno... è sangue?"
  },
  AvgDialog_18861_Content_31 = {
    Text = "Questo è collegato a quei due Studenti fuggitivi, non è vero?"
  },
  AvgDialog_18861_Content_32 = {
    Text = "Esatto. Cinque giorni fa, due studenti hanno lasciato la scuola senza autorizzazione, dirigendosi a <Blue:Londinium Est> per indagare su <Red:\"Gli Omicidi Seriali dello Squartatore\">."
  },
  AvgDialog_18861_Content_33 = {
    Text = "Di notte, i due hanno sentito grida d'aiuto nei pressi del <Blue:Laboratorio Lilian> su Bernard Road. Indagando, hanno scoperto una donna inseguita da una <Yellow:Forma di Vita Sconosciuta>."
  },
  AvgDialog_18861_Content_34 = {
    Text = "I due studenti hanno seguito il motto della scuola e tentato un salvataggio, ma sono stati attaccati. Alla fine, lo studente del primo anno è riuscito a fuggire ed è tornato a scuola all'alba di quattro giorni fa, mentre lo studente del secondo anno risulta ancora disperso."
  },
  AvgDialog_18861_Content_35 = {
    Text = "Tre giorni fa, lo studente del primo anno si è risvegliato dallo svenimento e ha raccontato l'accaduto.\nCi ha detto che la creatura sembrava possedere abilità di pietrificazione, trasformando le gambe delle donne in pietra."
  },
  AvgDialog_18861_Content_36 = {
    Text = "Pietrificato? Questa statua potrebbe essere... parte dello studente disperso?"
  },
  AvgDialog_18861_Content_37 = {
    Text = "Il sopravvissuto non può essere identificato, ma è molto probabile.\nQuanto a questo nastro, probabilmente appartiene a una vittima di sesso femminile."
  },
  AvgDialog_18861_Content_38 = {
    Text = "Tracce di <Yellow:Dissoluzione>? Con quell'Abilità, potrebbe trattarsi di un nuovo <Yellow:Cataclisma>."
  },
  AvgDialog_18861_Content_39 = {
    Text = "È questo l'aspetto strano. Le catastrofi, in quanto nucleo delle <Yellow:Faglie-D>, dovrebbero <Yellow:Dissolvere indiscriminatamente>. Non ho mai sentito che attacchino in modo proattivo."
  },
  AvgDialog_18861_Content_4 = {
    Text = "Presto! Ci sta raggiungendo!"
  },
  AvgDialog_18861_Content_40 = {
    Text = "A parte una piccola quantità di <Yellow:D-melma>, non abbiamo trovato D-marchi evidenti sulla scena né nell'intero Distretto Est, il che è incoerente con i <Yellow:tratti di Dissoluzione> di una D-fessura."
  },
  AvgDialog_18861_Content_41 = {
    Text = "Ciò che possiamo confermare ora è: le recenti sparizioni nei pressi del <Blue:Laboratorio Lilian> e il caso dello <Red:\"Smembratore\"> potrebbero essere collegati a quella Forma di Vita."
  },
  AvgDialog_18861_Content_42 = {
    Text = "Dopo un'analisi preliminare, riteniamo che la forma di vita non identificata si nasconda probabilmente nella Zanna di Lily An."
  },
  AvgDialog_18861_Content_43 = {
    Text = "Sembra che dovremo fare un salto laggiù."
  },
  AvgDialog_18861_Content_44 = {
    Text = "Sì. Confermare la posizione dello studente disperso, scoprire la verità dietro l'evento, localizzare e fermare la mente dietro tutto questo. Questa è la tua missione."
  },
  AvgDialog_18861_Content_45 = {
    Text = "Allora, %player%? Pensi di farcela?"
  },
  AvgDialog_18861_Content_46 = {
    Text = "Un gioco da ragazzi."
  },
  AvgDialog_18861_Content_47 = {
    Text = "Farò del mio meglio."
  },
  AvgDialog_18861_Content_48 = {
    Text = "Molto bene. Considerando che l'obiettivo questa volta potrebbe possedere un'intelligenza considerevole, ti suggerisco di procurarti dei travestimenti dal dipartimento logistico prima di partire, così da non destare sospetti."
  },
  AvgDialog_18861_Content_49 = {
    Text = "Porta con te questo nastro. Potrebbe aiutare a scoprire perché la forma di vita sconosciuta ha attaccato la sua proprietaria e, se possibile, a identificare la vittima."
  },
  AvgDialog_18861_Content_5 = {
    Text = "Tre persone correvano freneticamente nella Nebbia, il respiro affannoso, come topi sotto lo sguardo di un gatto tra canti allegri."
  },
  AvgDialog_18861_Content_50 = {
    Text = "L'incarico non è molto pericoloso. Terremo il comunicatore aperto. <Blue:Doll> ed <Blue:Erica> ti guideranno e assisteranno in qualsiasi momento."
  },
  AvgDialog_18861_Content_51 = {
    Text = "Hai toccato il distintivo sul petto. Il <Blue:Frammento d'Argento> incastonato garantisce le tue comunicazioni a lunga distanza."
  },
  AvgDialog_18861_Content_52 = {
    Text = "Senza ulteriori indugi, mettiamoci in marcia."
  },
  AvgDialog_18861_Content_53 = {
    Text = "Che la Chiave d'Argento Illumini il Cammino."
  },
  AvgDialog_18861_Content_54 = {
    Text = [[
13:07, Londinium Est
Un piccolo vicolo]]
  },
  AvgDialog_18861_Content_55 = {
    Text = "Alcuni bambini magrissimi e mal vestiti sono accovacciati nel vicolo, apparentemente intenti a discutere di qualcosa."
  },
  AvgDialog_18861_Content_56 = {
    Text = "Come al solito, Brown e io ce ne occupiamo. Voi distraete quei creduloni e fateci guadagnare tempo. Ci vediamo alla porta sul retro della panetteria."
  },
  AvgDialog_18861_Content_57 = {
    Text = "Non torni al Laboratorio di Lavoro?"
  },
  AvgDialog_18861_Content_58 = {
    Text = "Prima devo comprare qualcosa da mangiare. Il pane di quel maledetto posto è più duro di un sasso; non riesco neanche a mandarlo giù. Non ce la faccio più."
  },
  AvgDialog_18861_Content_59 = {
    Text = "La signora Blake del negozio di latticini ha detto che una volta che qualcuno entra lì, non può più uscire, nemmeno da morto. È terrificante. Tua sorella potrebbe già essere...?"
  },
  AvgDialog_18861_Content_6 = {
    Text = "Il soriano del vecchio Charlie, grasso e caro..."
  },
  AvgDialog_18861_Content_60 = {
    Text = "Non dire sciocchezze! La Sorella Maggiore starà bene, vero, Jenkin?"
  },
  AvgDialog_18861_Content_61 = {
    Text = "La ragazza non rispose e si limitò a fissare fuori dal vicolo.\nIl topo sulla sua spalla la spinse col naso, come per confortarla o esprimere preoccupazione."
  },
  AvgDialog_18861_Content_62 = {
    Text = [[
In una strada trafficata, un'auto nera e lucida si ferma lentamente.
Due individui vestiti in modo impeccabile scendono, uno dei quali con dei bellissimi capelli argentati.]]
  },
  AvgDialog_18861_Content_63 = {
    Text = [[
Vedete quei due polli? Sono gli obiettivi di oggi.
Pronti a partire!]]
  },
  AvgDialog_18861_Content_64 = {
    Text = [[
13:10, Londinium Est
Una strada]]
  },
  AvgDialog_18861_Content_65 = {
    Text = "Un'umidità densa e un tanfo di marcio ti soffocano nell'istante in cui scendi dall'auto."
  },
  AvgDialog_18861_Content_66 = {
    Text = "Un'improvvisa ondata di vertigini e un intenso ronzio nelle orecchie ti colpiscono. Immagini sfocate balenano nella tua mente, come se avessi già visto questa scena."
  },
  AvgDialog_18861_Content_67 = {
    Text = "È un'illusione, o è parte dei tuoi ricordi perduti?\nPrima che tu possa riflettere, un gruppo di bambini vivaci ti urta addosso."
  },
  AvgDialog_18861_Content_68 = {Text = "!"},
  AvgDialog_18861_Content_69 = {
    Text = "Stringi il braccio contuso, notando Ramona che ti osserva con un lieve sorriso."
  },
  AvgDialog_18861_Content_7 = {
    Text = "Le mie gambe... Le mie gambe non si muovono! Aiutatemi! Aiutatemi!"
  },
  AvgDialog_18861_Content_70 = {
    Text = "Che succede?"
  },
  AvgDialog_18861_Content_71 = {
    Text = "Indicò la tua tasca. Seguendo il suo dito, un detto ti venne improvvisamente in mente:\n\"Il benvenuto più famigerato del Distretto Est è il tuo portafoglio che sparisce senza che tu te ne accorga.\""
  },
  AvgDialog_18861_Content_72 = {
    Text = "Non è possibile... il mio portafoglio!"
  },
  AvgDialog_18861_Content_73 = {
    Text = "Sbrigati, %player%, o non potrai permetterti i cupcake questo mese."
  },
  AvgDialog_18861_Content_8 = {Text = "Signora!"},
  AvgDialog_18861_Content_9 = {
    Text = "Senpai, non andare! Senpai!"
  },
  AvgDialog_18862_Content_1 = {
    Text = "Ramona bloccò l'attacco di Aigis. Aigis barcollò indietro di qualche passo, le mani che tremavano leggermente, una melma nera che trasudava tra le dita mentre si copriva gli occhi."
  },
  AvgDialog_18862_Content_10 = {
    Text = "Non avvicinatevi... State indietro!"
  },
  AvgDialog_18862_Content_11 = {
    Text = "La ragazza si voltò e corse via."
  },
  AvgDialog_18862_Content_12 = {Text = "Aigis!"},
  AvgDialog_18862_Content_13 = {
    Text = "Smettila di gridare, sbrigati e inseguili!"
  },
  AvgDialog_18862_Content_2 = {
    Text = "Aigis, stai bene?"
  },
  AvgDialog_18862_Content_3 = {
    Text = "Sussultò e alzò la testa, il suo sguardo oscillava tra lucidità e confusione."
  },
  AvgDialog_18862_Content_4 = {
    Text = "Come... come è potuto succedere... No, no, non stavo dormendo, non..."
  },
  AvgDialog_18862_Content_5 = {Text = "Aigis?"},
  AvgDialog_18862_Content_6 = {
    Text = "Non parlare, non, non farlo. Non è ancora buio, e non c'è nessuna nebbia. Non puoi controllarmi, non puoi...!"
  },
  AvgDialog_18862_Content_7 = {
    Text = "Aigis si strinse la testa, il suo piccolo corpo si piegò in avanti a causa di un dolore inspiegabile."
  },
  AvgDialog_18862_Content_8 = {
    Text = "No... non voglio essere trasformata in una scultura di cera... Mi rifiuto, mi rifiuto assolutamente..."
  },
  AvgDialog_18862_Content_9 = {
    Text = "Hai sentito qualcosa, Aigis?"
  },
  AvgDialog_18863_Content_1 = {
    Text = "***Non sembra malata, com'è possibile che sia impazzita?! Aigis, stai attenta e schiva!***"
  },
  AvgDialog_18863_Content_2 = {
    Text = [[
Ha detto di aver ricevuto delle cure, probabilmente in quel periodo...
In ogni caso, dobbiamo attirarla in un luogo appartato.]]
  },
  AvgDialog_18863_Content_3 = {
    Text = "Prima di quello, occupiamoci di questi tizi."
  },
  AvgDialog_18864_Content_1 = {
    Text = "Tu e Ramona combattete ritirandovi, raggiungendo il cortile del laboratorio senza allertare gli altri."
  },
  AvgDialog_18864_Content_2 = {
    Text = "La nebbia è tornata!"
  },
  AvgDialog_18864_Content_3 = {
    Text = "Una nebbia fitta ha avvolto tutto, e con essa arrivano stridii sinistri da luoghi invisibili, avvicinandosi gradualmente a voi."
  },
  AvgDialog_18864_Content_4 = {
    Text = "Tu e Ramona vi mettete schiena contro schiena, osservando con cautela le ombre contorte."
  },
  AvgDialog_18864_Content_5 = {
    Text = "Come possono esserci Mutanti qui? I Pazienti non erano stati rinchiusi?"
  },
  AvgDialog_18864_Content_6 = {
    Text = "Non importa da dove vengano, respingiamoli!"
  },
  AvgDialog_18864_Content_7 = {
    Text = "Ramona brandì il suo stocco e ingaggiò proattivamente i mostri più vicini."
  },
  AvgDialog_18865_Content_1 = {
    Text = "I Mutanti caddero sotto la lama di Ramona, sgretolando rapidamente in fine polvere nera che si disperse nell'aria."
  },
  AvgDialog_18865_Content_10 = {
    Text = "Fai un respiro profondo e raddrizzi il corpo."
  },
  AvgDialog_18865_Content_11 = {
    Text = "Stai attenta, Ramona."
  },
  AvgDialog_18865_Content_12 = {
    Text = "Non preoccuparti, conosco i miei limiti."
  },
  AvgDialog_18865_Content_2 = {
    Text = "Ti asciughi il sudore dalla fronte, ansimando e sbattendo forte le palpebre."
  },
  AvgDialog_18865_Content_3 = {Text = "Stai bene?"},
  AvgDialog_18865_Content_4 = {
    Text = "Sto bene. Solo un leggero mal di testa."
  },
  AvgDialog_18865_Content_5 = {
    Text = "Il mio cervello sembra stia per esplodermi fuori dagli occhi."
  },
  AvgDialog_18865_Content_6 = {
    Text = "Hai ancora la forza di scherzare, quindi non sembra nulla di grave."
  },
  AvgDialog_18865_Content_7 = {
    Text = "Hai bisogno di una pausa?"
  },
  AvgDialog_18865_Content_8 = {
    Text = "Sbrighiamoci a trovare Jenkin. Ho la sensazione che non sia così semplice."
  },
  AvgDialog_18865_Content_9 = {
    Text = "Una piccola figura emerge dalla nebbia davanti a voi. Piega leggermente le ginocchia, il corpo teso, chiaramente in posizione d'attacco."
  },
  AvgDialog_18866_Content_1 = {
    Text = "Non c'è nessuno lì. Sei sicura di non aver visto male?"
  },
  AvgDialog_18866_Content_2 = {
    Text = "Signorina Mary, dove state andando? Ahimè, Signorina Mary!"
  },
  AvgDialog_18867_Content_1 = {Text = "%player%!"},
  AvgDialog_18867_Content_10 = {
    Text = "Signorina Sarah, ho tanta paura, la prego... la prego, non se ne vada..."
  },
  AvgDialog_18867_Content_11 = {
    Text = "Signorina Sarah..."
  },
  AvgDialog_18867_Content_12 = {
    Text = "Che succede, Aigis?"
  },
  AvgDialog_18867_Content_13 = {
    Text = "Signorina Sarah, potrebbe cantare ancora quella canzone, solo una volta? Cioè, se non è troppo disturbo per lei..."
  },
  AvgDialog_18867_Content_14 = {
    Text = "Cara Aigis, ascolta bene. Sei la bambina più ubbidiente e giudiziosa di tutto il laboratorio, e tutti ti vogliono un mondo di bene."
  },
  AvgDialog_18867_Content_15 = {
    Text = "Quindi, va bene essere un po' capricciosa ogni tanto. Capisci?"
  },
  AvgDialog_18867_Content_16 = {
    Text = "Allora io... voglio sentire la signorina Sarah cantare ancora la filastrocca."
  },
  AvgDialog_18867_Content_17 = {
    Text = [[
Nessun problema.
Il vecchio Charlie ha un gatto soriano che ama alla follia...]]
  },
  AvgDialog_18867_Content_18 = {
    Text = "Apri improvvisamente gli occhi su un mondo reale vibrante di vita."
  },
  AvgDialog_18867_Content_19 = {
    Text = "%player%, stai bene?"
  },
  AvgDialog_18867_Content_2 = {
    Text = "Mentre Ramona tiene a bada Sarah, ti concentri rapidamente e ti immergi nello spazio nero — quello che ti sta diventando familiare."
  },
  AvgDialog_18867_Content_20 = {
    Text = [[
Annuisci, lottando contro il capogiro.
Con la coda dell'occhio, scorgi una figura bianca.]]
  },
  AvgDialog_18867_Content_21 = {
    Text = "Aigis? Qui è pericoloso. Torna da Jenkin."
  },
  AvgDialog_18867_Content_22 = {
    Text = "Signorina Sarah, sta dormendo?"
  },
  AvgDialog_18867_Content_23 = {Text = "...?"},
  AvgDialog_18867_Content_24 = {
    Text = "Beh, la Signorina Sarah non dormiva bene da molto, molto tempo."
  },
  AvgDialog_18867_Content_25 = {
    Text = "Per evitare che il laboratorio si dissolvesse, era sempre in giro, a incontrare i ricchi signori e le dame che risiedevano nel castello, senza tempo per mangiare o riposare."
  },
  AvgDialog_18867_Content_26 = {
    Text = "Di notte, tornata al laboratorio, accendeva una candela nel suo ufficio e continuava a calcolare se i soldi del Maestro fossero sufficienti."
  },
  AvgDialog_18867_Content_27 = {
    Text = "Cerca di capire quanto possano valere i gioielli che quelle signore le hanno dato."
  },
  AvgDialog_18867_Content_28 = {
    Text = "Tutti ridevano di lei e dicevano cose cattive, ma la Signorina Sarah non si arrabbiava mai. Mi consolava e cantava per noi."
  },
  AvgDialog_18867_Content_29 = {
    Text = "Ci tratta bene, davvero. Tratta molto bene anche me."
  },
  AvgDialog_18867_Content_3 = {
    Text = "La Chiave d'Argento vibra intensamente. L'Oscurità davanti a te si trasforma, schiarendosi dai bordi della tua Visuale."
  },
  AvgDialog_18867_Content_30 = {
    Text = "Ero un peso per mia madre, e lei mi ha abbandonata. Il precedente amministratore si rifiutò di accogliermi, ma la Signorina Sarah disse che era disposta a fare due lavori pur di prendermi con sé."
  },
  AvgDialog_18867_Content_31 = {
    Text = "Da allora, giurai di non essere un peso per la signorina Sarah, ma una bambina utile."
  },
  AvgDialog_18867_Content_32 = {
    Text = "Mi dispiace, Signorina Sarah. Ho fatto tutto il possibile, ma non sono riuscita a proteggere Little Mike e non sono riuscita a proteggere lei. Mi dispiace."
  },
  AvgDialog_18867_Content_33 = {
    Text = "Aigis accarezzò delicatamente la guancia di Sarah, poi si voltò verso di te."
  },
  AvgDialog_18867_Content_34 = {
    Text = "Aigis, tu..."
  },
  AvgDialog_18867_Content_35 = {
    Text = "Vuoi sapere cosa è successo la scorsa notte?"
  },
  AvgDialog_18867_Content_36 = {
    Text = "La bambina forza un sorriso a malapena riconoscibile come gioia."
  },
  AvgDialog_18867_Content_37 = {
    Text = [[
Rilasciate Lucy, e anche la Signorina Sarah.
Io sono lo squartatore Jack che stavate cercando.]]
  },
  AvgDialog_18867_Content_4 = {
    Text = "Signorina Sarah, ho tanta fame."
  },
  AvgDialog_18867_Content_5 = {
    Text = "Mi rammarico di doverle dire questo, ma non possiamo più continuare a finanziarla, signorina Sarah."
  },
  AvgDialog_18867_Content_6 = {
    Text = "Signorina Sarah, ho fatto arrabbiare la mamma con me?"
  },
  AvgDialog_18867_Content_7 = {
    Text = "Luci bianche e nere lampeggiano come più film proiettati su un unico schermo. Non riesci a distinguere i dettagli, per quanto ti sforzi."
  },
  AvgDialog_18867_Content_8 = {
    Text = "Signorina Sarah, la mia mamma dice che sono inutile... Posso davvero aiutarla?"
  },
  AvgDialog_18867_Content_9 = {
    Text = "Signorina Sarah, la mamma mi ha buttata fuori... Lei... lei mi butterà fuori anche lei?"
  },
  AvgDialog_18868_Content_1 = {
    Text = "Oh cielo... questo..."
  },
  AvgDialog_18868_Content_2 = {
    Text = "Non si preoccupi, signorina Sarah. Il Dott. Miller aiuterà sicuramente i pazienti."
  },
  AvgDialog_18868_Content_3 = {
    Text = "Signorina Sarah, riorganizzi la fila, per favore. Prima finiamo la selezione, prima potranno ricevere le cure."
  },
  AvgDialog_18869_Content_1 = {
    Text = "Per favore, calmatevi tutti!"
  },
  AvgDialog_18869_Content_2 = {
    Text = "Io sono perfettamente calma. Dovreste chiedere a lui cosa ha fatto ad Aigis per spaventarla così tanto!"
  },
  AvgDialog_18869_Content_3 = {
    Text = "Voi non sapete niente! Lo facciamo per il bene dell'umanità!"
  },
  AvgDialog_18870_Content_1 = {
    Text = "Il Nostro Segreto"
  },
  AvgDialog_18870_Content_10 = {
    Text = [[
Ricerca effettuata.
Nessun risultato pertinente trovato. Ci scusiamo sinceramente. Si consiglia di inviare una richiesta di Operazione di Assistenza.]]
  },
  AvgDialog_18870_Content_11 = {
    Text = "Investigatore Ramona, ID comunicatore I-3017, segnala formalmente Clementine Fairfax, sospetta Risvegliatrice non appartenente al <Blue:\"Patto\">, attualmente sotto le sembianze del Dott. George Rogers"
  },
  AvgDialog_18870_Content_12 = {
    Text = [[
Richiesta di operazione di assistenza ricevuta.
Approvata, trasferita al <Blue:Dipartimento Operazioni di Mythag>.]]
  },
  AvgDialog_18870_Content_13 = {
    Text = "La richiesta è stata inviata. Lascia il resto alla squadra investigativa.\nManca ancora un po' all'alba. Vuoi riposare un po'?"
  },
  AvgDialog_18870_Content_14 = {
    Text = "No, per convincere Doll, dobbiamo trovare rapidamente un indizio decisivo o un sospettato."
  },
  AvgDialog_18870_Content_15 = {
    Text = "Stai parlando di Sarah."
  },
  AvgDialog_18870_Content_16 = {
    Text = "Quello che ci ha dato da bere era sicuramente più di un semplice tè. Inoltre, trovo difficile credere che qualcuno che ha vissuto in un laboratorio così a lungo possa avere paura delle ombre."
  },
  AvgDialog_18870_Content_17 = {
    Text = "Ora pensa che stiamo dormendo, quindi probabilmente abbasserà la guardia."
  },
  AvgDialog_18870_Content_18 = {
    Text = "Vai. Controlla prima il corridoio, poi dirigiti al suo ufficio.\nSarà lei il nostro punto di svolta."
  },
  AvgDialog_18870_Content_19 = {
    Text = [[
01:15, Laboratorio Lilyan
Stanza degli ospiti]]
  },
  AvgDialog_18870_Content_2 = {
    Text = [[
01:13, Laboratorio Lily
Stanza degli ospiti]]
  },
  AvgDialog_18870_Content_20 = {
    Text = "Aigis aprì silenziosamente la porta e si avvicinò a Jenkin addormentato.\nRestò ferma per un po', poi iniziò a singhiozzare piano."
  },
  AvgDialog_18870_Content_21 = {
    Text = "Stai bene, stai davvero bene...! Mi dispiace, mi dispiace, mi dispiace."
  },
  AvgDialog_18870_Content_22 = {
    Text = [[
Avrei dovuto venire prima. Avrei dovuto provarci, anche se sono inutile, anche se io...
La Dottoressa Clementine aveva ragione, ma...]]
  },
  AvgDialog_18870_Content_23 = {
    Text = "Ci rifletterò, saprò quale prezzo è sufficiente...\nSicuramente ci riuscirò."
  },
  AvgDialog_18870_Content_24 = {
    Text = "Se ne andò in silenzio, e quando la porta si chiuse, Jenkin aprì gli occhi senza fare rumore."
  },
  AvgDialog_18870_Content_25 = {
    Text = [[
01:37, Laboratorio Lily
Corridoio]]
  },
  AvgDialog_18870_Content_26 = {
    Text = "Ti dirigi silenziosamente verso il punto in cui hai incontrato di recente Sarah e Aigis.\nÈ in fondo al corridoio, con solo una porta, le pareti e una finestra che si affaccia sul cortile posteriore a catturare la tua attenzione."
  },
  AvgDialog_18870_Content_27 = {
    Text = "Ramona spinse la porta. Il fascio della torcia spazzò il letto e l'armadio, illuminando la polvere sospesa nell'aria."
  },
  AvgDialog_18870_Content_28 = {
    Text = "Questa è... la vecchia stanza?"
  },
  AvgDialog_18870_Content_29 = {
    Text = "Ramona si accovacciò, passò le dita sulle fughe dei mattoni e annusò delicatamente."
  },
  AvgDialog_18870_Content_3 = {
    Text = "Dopo un lampo particolarmente abbagliante della Chiave d'argento, tu e Ramona sentite le membra leggere e vi precipitate fuori dalla porta.\nIl corridoio è vuoto, ci siete solo voi due."
  },
  AvgDialog_18870_Content_30 = {
    Text = "C'è un debole odore di sangue, probabilmente ripulito.\nA giudicare dall'umidità, è successo nell'ultima ora."
  },
  AvgDialog_18870_Content_31 = {
    Text = "Puntò la torcia sul pavimento intorno a sé. Le macchie d'acqua nelle fessure dei mattoni riflettevano debolmente la luce, e in alcuni degli interstizi si poteva persino scorgere un sinistro liquido nero."
  },
  AvgDialog_18870_Content_32 = {
    Text = "Cos'è successo? Chi è stato ferito o ucciso?\nÈ stato lo Smembratore o una forma di vita sconosciuta?"
  },
  AvgDialog_18870_Content_33 = {
    Text = "In base alle nostre scoperte precedenti, c'era solo un intervallo di circa dieci minuti tra lo Smembratore e noi. Anche se abbiamo impiegato del tempo a esaminare il corpo, non dovremmo essere troppo indietro."
  },
  AvgDialog_18870_Content_34 = {
    Text = [[
E a giudicare dalla dimensione delle impronte, lo smembratore potrebbe persino essere... un bambino.
Ma quando eravamo con Sarah nel laboratorio prima, non abbiamo visto nessun bambino con del sangue addosso.]]
  },
  AvgDialog_18870_Content_35 = {
    Text = "In un lasso di tempo così breve, completare compiti come uccidere, saccheggiare, fuggire, uccidere di nuovo e nascondere la propria identità è assolutamente impossibile per un singolo individuo."
  },
  AvgDialog_18870_Content_36 = {
    Text = "Vuoi dire che questo bambino probabilmente ha un complice?"
  },
  AvgDialog_18870_Content_37 = {
    Text = "Potrebbero persino essere complici, commettendo il secondo crimine qui simultaneamente o quasi, mentre l'altro stava compiendo il primo."
  },
  AvgDialog_18870_Content_38 = {
    Text = "Potrebbe essere Sarah? Aveva abbastanza tempo ed era anche qui."
  },
  AvgDialog_18870_Content_39 = {
    Text = "Al momento non ci sono prove sufficienti per formulare un giudizio."
  },
  AvgDialog_18870_Content_4 = {
    Text = "Ha detto di avere un \"Cuore d'Argento\", probabilmente qualcosa di simile a un Risvegliatore. Quindi..."
  },
  AvgDialog_18870_Content_40 = {
    Text = "Ramona si avvicinò all'angolo, si chinò e recuperò un piccolo oggetto metallico dall'oscurità.\nEra un gemello da polsino macchiato di sangue."
  },
  AvgDialog_18870_Content_41 = {
    Text = "A giudicare dalla fattura, questo è probabilmente uno dei \"gioielli in oro e argento\" che Jenkin ha menzionato dalla scorta di Sarah.\nAndiamo in ufficio; potremmo trovare altre prove."
  },
  AvgDialog_18870_Content_42 = {
    Text = [[
01:55, Laboratorio di Lily
Ufficio del Direttore]]
  },
  AvgDialog_18870_Content_43 = {
    Text = "Avevo ragione, %player%. Guarda."
  },
  AvgDialog_18870_Content_44 = {
    Text = "Ramona tirò fuori una piccola bottiglia marrone dal cassetto della scrivania. La prendi e la esamini, notando un'etichetta con il nome e gli effetti del farmaco."
  },
  AvgDialog_18870_Content_45 = {
    Text = "Può aiutare i pazienti a rilassare lo spirito e dormire — sembra che questo sia l'ingrediente aggiunto al nostro tè."
  },
  AvgDialog_18870_Content_46 = {
    Text = "Fortunatamente, non ha ancora padroneggiato il dosaggio, altrimenti stanotte sarebbe andata diversamente per entrambi."
  },
  AvgDialog_18870_Content_47 = {
    Text = "A proposito, cosa sta succedendo con Jenkin? Sarah non sembra avere la capacità di controllare lo spirito degli altri... Hmm? Cos'è questo?"
  },
  AvgDialog_18870_Content_48 = {
    Text = [[
Frugate nel cassetto mentre parlate, tirando fuori un libro con la copertina nera dal fondo.
Lo posate sul tavolo e lo aprite, solo per trovarlo pieno di nomi scritti in fitte righe.]]
  },
  AvgDialog_18870_Content_49 = {
    Text = "John Douglas, Diana Wolf... Registro del Laboratorio? Contrassegnato anche con età, sesso e stato familiare. Ma oltre a questo..."
  },
  AvgDialog_18870_Content_5 = {
    Text = "Chiudi gli occhi, costringendoti a tornare in quel mondo illusorio, solo per scoprire che tutto è avvolto da un velo nebuloso, sfocato e indistinto."
  },
  AvgDialog_18870_Content_50 = {
    Text = "Ogni nome è seguito da un simbolo che rappresenta la valuta del Regno di Leo, <Blue:Zanna di Leo>, seguito da un numero."
  },
  AvgDialog_18870_Content_51 = {
    Text = "I numeri ordinatamente disposti e le informazioni sul personale rendevano difficile distinguere se si trattasse di un registro dei lavoratori per le Zanne o di una lista della spesa da qualche catalogo."
  },
  AvgDialog_18870_Content_52 = {
    Text = "Ognuno ha un prezzo diverso: uomini, donne... e bambini."
  },
  AvgDialog_18870_Content_53 = {
    Text = "È come trattare le persone come merci.\nChi? Chi farebbe un simile affare con lei?"
  },
  AvgDialog_18870_Content_54 = {
    Text = "Ricordi che Sarah ha chiesto chi stava aiutando a curare i pazienti?"
  },
  AvgDialog_18870_Content_55 = {
    Text = "L'Istituto di Ricerca del Dottor Miller. Potrebbe essere una copertura per gli Scultori?"
  },
  AvgDialog_18870_Content_56 = {
    Text = "È possibile. Portiamo con noi le prove chiave per ora.\nDomani cercheremo di far parlare Sarah e vedere se riusciamo a ottenere qualcosa da lei."
  },
  AvgDialog_18870_Content_57 = {
    Text = [[
01:50, Laboratorio di Lily
Da qualche parte nel Cortile]]
  },
  AvgDialog_18870_Content_58 = {
    Text = "Sarah accese il fiammifero e lo gettò nella catasta di legna davanti a lei."
  },
  AvgDialog_18870_Content_59 = {
    Text = "Catalizzate dalla benzina, le fiamme si diffusero rapidamente e avvolsero gli abiti intrisi di sangue."
  },
  AvgDialog_18870_Content_6 = {
    Text = "L'occipite inizia a pulsare a ondate, un acufene acuto ti trafigge; ti stringi la fronte e sei costretto a smettere di tentare di ricordare."
  },
  AvgDialog_18870_Content_60 = {
    Text = "Rimase in silenzio per un momento, si assicurò che le fiamme non si sarebbero spente, e poi si voltò per andarsene."
  },
  AvgDialog_18870_Content_7 = {
    Text = "Hai già esaurito una grande quantità di energia spirituale oggi. Non sforzarti."
  },
  AvgDialog_18870_Content_8 = {
    Text = "Ma Clementine... Non posso lasciarla così..."
  },
  AvgDialog_18870_Content_9 = {
    Text = [[
Possiamo chiedere rinforzi.
Erica, cerca Clementine Fairfax.]]
  },
  AvgDialog_18871_Content_1 = {
    Text = "Il mio portafoglio, la mia tortina..."
  },
  AvgDialog_18871_Content_2 = {
    Text = "Su col morale. Forse riceveremo ricompense extra se completiamo questa missione con successo."
  },
  AvgDialog_18871_Content_3 = {
    Text = "Se si arrivasse a quello, non mi dispiacerebbe condividere."
  },
  AvgDialog_18872_Content_1 = {
    Text = "Incubo Cromatico"
  },
  AvgDialog_18872_Content_10 = {
    Text = "...D'accordo, se {Male=Lord,Female=Lady} Ashe lo ordina."
  },
  AvgDialog_18872_Content_11 = {
    Text = [[
09:23, Laboratorio di Lily
Camera Sotterranea]]
  },
  AvgDialog_18872_Content_12 = {
    Text = "Questo sembra essere una sorta di sala operatoria sperimentale. Al centro della stanza c'è un tavolo operatorio modificato, macchiato di sporcizia sospetta."
  },
  AvgDialog_18872_Content_13 = {
    Text = "Nell'angolo più profondo del seminterrato giace un mucchio di vestiti sporchi irriconoscibili nella loro forma originale, alto metà persona, che emana continuamente un fetore nauseante."
  },
  AvgDialog_18872_Content_14 = {
    Text = "Q-Q-Questo che razza di posto è?!"
  },
  AvgDialog_18872_Content_15 = {
    Text = "Non fare la finta tonta. Sappiamo tutto dei tuoi piani malvagi con quel dottore di merda."
  },
  AvgDialog_18872_Content_16 = {
    Text = "Quali piani malvagi stai tramando, ragazzina? Non hai fatto altro che fare casino da quando sei arrivata. Dovrò darti una lezione."
  },
  AvgDialog_18872_Content_17 = {
    Text = "Abbiamo visto il vostro grosso registro!"
  },
  AvgDialog_18872_Content_18 = {Text = "...?"},
  AvgDialog_18872_Content_19 = {
    Text = "Raccogli il registro, lo apri e fai cenno a Sarah."
  },
  AvgDialog_18872_Content_2 = {
    Text = [[
09:15, Laboratorio di Lily
Ufficio della Direttrice]]
  },
  AvgDialog_18872_Content_20 = {
    Text = [[
Mike, maschio, 5 anni, 10 Leo Fang; Diana, femmina, 23 anni, 5 Leo Fang...
Aigis, femmina, 8 anni, 40 Leo Fang.]]
  },
  AvgDialog_18872_Content_21 = {
    Text = "Dopo aver finito di parlare, raccogli la lista dei pazienti appena trovata."
  },
  AvgDialog_18872_Content_22 = {
    Text = "Mike, maschio, 5 anni, 5 Leo Fang; Diana, femmina, 23 anni, 5 Leo Fang; Aigis, femmina, 8 anni, 5 Leo Fang."
  },
  AvgDialog_18872_Content_23 = {
    Text = "...Devo continuare?"
  },
  AvgDialog_18872_Content_24 = {
    Text = "No, non è così. Io—"
  },
  AvgDialog_18872_Content_25 = {
    Text = "Non cercare scuse! Stai trasformando le persone del laboratorio in cavie per quel \"Dottore Cane,\" tutto per scambiare il tuo oro e i tuoi gioielli!"
  },
  AvgDialog_18872_Content_26 = {
    Text = "No, non è così! La signorina Sarah ha detto che era un supporto nutrizionale per chi riceveva trattamenti dal laboratorio, 5 Leofan ogni volta, come concordato."
  },
  AvgDialog_18872_Content_27 = {Text = "Aigis!"},
  AvgDialog_18872_Content_28 = {
    Text = "In effetti. Quanto al ragazzo che parlava di gioielli, sono solo sciocchezze, vi prego di credermi, {Male=Lord,Female=Lady} Ashe!"
  },
  AvgDialog_18872_Content_29 = {
    Text = "Jenkin estrae due anelli d'argento dal fondo della sua bisaccia."
  },
  AvgDialog_18872_Content_3 = {
    Text = "Collana di smeraldi, anello... Strano, dov'è il mio registro?"
  },
  AvgDialog_18872_Content_30 = {
    Text = "Stai dicendo che ho fatto apparire dal nulla questi due gingilli dal cassetto destro dell'ufficio?"
  },
  AvgDialog_18872_Content_31 = {
    Text = "Come è finito nelle tue mani? Ridammelo—è un regalo di un altro sponsor!"
  },
  AvgDialog_18872_Content_32 = {
    Text = "{Male=Lord,Female=Lady} Ashe, credetemi, li considero scorte d'emergenza per sostenere i laboratori, come potrei, come potrei fare del male ai fanciulli del laboratorio per queste cose?"
  },
  AvgDialog_18872_Content_33 = {Text = "E questo?"},
  AvgDialog_18872_Content_34 = {Text = "...!!"},
  AvgDialog_18872_Content_35 = {
    Text = "Gemelli da polso?"
  },
  AvgDialog_18872_Content_36 = {
    Text = "Siamo entrati nella stanza di ieri."
  },
  AvgDialog_18872_Content_37 = {
    Text = "Il posto è stato pulito di recente, ma il pavimento è ancora bagnato, con macchie di sangue rimaste nelle fessure tra i mattoni.\nQuesto sembra essere stato accidentalmente trascurato e lasciato nell'angolo."
  },
  AvgDialog_18872_Content_38 = {
    Text = "È realizzato con materiali pregiati e una lavorazione squisita.\nChi altro nel laboratorio, a parte lei, la Direttrice, avrebbe simili decorazioni?"
  },
  AvgDialog_18872_Content_39 = {
    Text = "No, non è suo! Non è della signorina Sarah; è mio! L'ho lasciato cadere io là!"
  },
  AvgDialog_18872_Content_4 = {
    Text = "? Chi è?\nPrego, entrate."
  },
  AvgDialog_18872_Content_40 = {
    Text = "È lei, è lei! Un'assassina e una rapitrice!"
  },
  AvgDialog_18872_Content_41 = {
    Text = "Ignorando l'ostruzione di Aigis, Jenkin si lanciò in avanti e afferrò la gonna di Sarah."
  },
  AvgDialog_18872_Content_42 = {
    Text = "Canaglie, ditemi, dov'è mia sorella? <Big:Dove avete portato mia sorella?>"
  },
  AvgDialog_18872_Content_43 = {
    Text = "Stai per fare un passo avanti per intervenire quando un brivido improvviso ti percorre la schiena.\nQualcosa è dietro di te, dietro tutti voi, e vi osserva con intento malevolo."
  },
  AvgDialog_18872_Content_44 = {
    Text = "Volti la testa e vedi i vestiti sporchi nell'angolo che si agitano."
  },
  AvgDialog_18872_Content_45 = {
    Text = "Un liquido nero filtra attraverso le cuciture del tessuto, inzuppando i vestiti un tempo asciutti e formando aberrazioni viscide sul pavimento."
  },
  AvgDialog_18872_Content_46 = {Text = "Ramona!"},
  AvgDialog_18872_Content_5 = {
    Text = "Signorina Sarah."
  },
  AvgDialog_18872_Content_6 = {
    Text = "Signorina Mary!\nPosso chiederle se c'è qualcosa in cui posso assisterla?"
  },
  AvgDialog_18872_Content_7 = {
    Text = [[
Temo di aver bisogno della vostra compagnia.
{Male=Lord,Female=Lady} Ashe ha alcune questioni, nella speranza che possiate fornire delle risposte.]]
  },
  AvgDialog_18872_Content_8 = {
    Text = "{Male=Lord,Female=Lady} Ashe? Non può attendere un momento? Sono un po' occupato qui."
  },
  AvgDialog_18872_Content_9 = {
    Text = "Temo di dover insistere."
  },
  AvgDialog_18873_Content_1 = {
    Text = "Ragazzina, lo facciamo per il bene di Aigis. La sua condizione è piuttosto particolare, e se non viene controllata adeguatamente, potrebbe diventare molto problematica."
  },
  AvgDialog_18873_Content_10 = {
    Text = [[
Jenkin, smettila di combattere!
...Me ne vado.]]
  },
  AvgDialog_18873_Content_11 = {Text = "...Cosa?!"},
  AvgDialog_18873_Content_12 = {
    Text = "È quello che merito. Una volta che inizia, una volta che ho... non ci sarà più..."
  },
  AvgDialog_18873_Content_13 = {
    Text = "Cosa intendi con \"È quello che meriti\"? In base a cosa?"
  },
  AvgDialog_18873_Content_14 = {
    Text = "Il Dott. Miller ha ragione. Se ho una ricaduta, causerò un sacco di problemi a tutti.\nNon voglio farvi del male. Io... lasciatemi andare, per favore."
  },
  AvgDialog_18873_Content_15 = {
    Text = "Sei impazzita?! Cosa stai facendo, a borbottare tra te e te? Ho detto chiaramente di no!"
  },
  AvgDialog_18873_Content_16 = {Text = "Jenkin—"},
  AvgDialog_18873_Content_17 = {
    Text = "Dott. Miller."
  },
  AvgDialog_18873_Content_18 = {
    Text = "Chiudiamola qui per oggi. Ne riparleremo dopo."
  },
  AvgDialog_18873_Content_19 = {
    Text = "...Ne è sicuro, Sig. Rogers?"
  },
  AvgDialog_18873_Content_2 = {
    Text = "Potrebbe persino ferire le persone intorno a voi."
  },
  AvgDialog_18873_Content_20 = {
    Text = "È quello che penso."
  },
  AvgDialog_18873_Content_21 = {
    Text = [[
D'accordo, credo che non sia un problema saltare una settimana.
In tal caso, mi congedo. Arrivederci, Signorina Sarah, Sig. Rogers e {Male=Lord,Female=Lady} Ashe.]]
  },
  AvgDialog_18873_Content_22 = {
    Text = "Il Dott. Miller vi ha fatto un inchino ed è andato via con diversi ricercatori."
  },
  AvgDialog_18873_Content_23 = {
    Text = "Istintivamente, senti che non dovresti lasciarli andare, ma—al momento tutto non è che mera speculazione. Non sai se appartengano davvero all'Associazione degli Scultori, né quanti siano, o dove si trovi la loro base."
  },
  AvgDialog_18873_Content_24 = {
    Text = [[
Guardi Ramona, la sua espressione cupa, chiaramente condivide la tua preoccupazione:
Trattenerli ora non farebbe altro che mettere in allarme il nemico?]]
  },
  AvgDialog_18873_Content_25 = {
    Text = "Io... anch'io mi preparo ad andare, Signorina Sarah. C-ci vediamo il mese prossimo."
  },
  AvgDialog_18873_Content_26 = {
    Text = "Porto la piccola Aigis e Jenkin a riposare prima.\nSignorina Sarah, che ne dice di vederci nel suo ufficio più tardi?"
  },
  AvgDialog_18873_Content_27 = {
    Text = "Eh? Ma, Aigis, lei—"
  },
  AvgDialog_18873_Content_28 = {
    Text = "Sembra piuttosto spaventata. Vorrei restare con lei per un po' così che possa calmarsi."
  },
  AvgDialog_18873_Content_29 = {
    Text = "Allora... d'accordo. Vi disturbo, {Male=Lord,Female=Lady} Ashe."
  },
  AvgDialog_18873_Content_3 = {
    Text = "Vedi, Aigis, ecco cosa succede quando non ascolti e non collabori."
  },
  AvgDialog_18873_Content_4 = {
    Text = "I tuoi amici, le persone intorno a te... pagheranno tutti il prezzo per questo."
  },
  AvgDialog_18873_Content_5 = {
    Text = "Obbedisci, sottomettiti e non opporre resistenza. Sappi questo: non hai nessun posto dove fuggire."
  },
  AvgDialog_18873_Content_6 = {
    Text = "Cosa intende con \"intorno\"? Sono stata con lei per tutto questo tempo e non è successo niente!"
  },
  AvgDialog_18873_Content_7 = {Text = "...Jenkin"},
  AvgDialog_18873_Content_8 = {
    Text = "Aigis, non avere paura. Guardami mentre mi occupo di lui. Brown, mordilo!"
  },
  AvgDialog_18873_Content_9 = {Text = "Squeak!"},
  AvgDialog_18874_Content_1 = {
    Text = "Avviso di Persona Scomparsa"
  },
  AvgDialog_18874_Content_10 = {
    Text = "Non siate così negative, vogliamo solo che il laboratorio vada sempre meglio"
  },
  AvgDialog_18874_Content_11 = {Text = "Ugh!"},
  AvgDialog_18874_Content_12 = {
    Text = "All'improvviso senti un urto al tuo fianco e abbassi lo sguardo: un bambino fragile è crollato a terra, tremando in modo incontrollabile."
  },
  AvgDialog_18874_Content_13 = {
    Text = "Là, là, ci sono dei mostri!!"
  },
  AvgDialog_18874_Content_14 = {
    Text = "Pochi minuti prima, al Laboratorio di Lily"
  },
  AvgDialog_18874_Content_15 = {
    Text = "Nel corridoio silenzioso, una porta con una targhetta metallica si aprì lentamente.\nUn topo sgusciò attraverso la fessura, si guardò intorno e squittì due volte verso qualcosa dietro di sé."
  },
  AvgDialog_18874_Content_16 = {
    Text = "\"Tutto chiaro,\" è esattamente quello che hai detto l'ultima volta! Sarei stato nei guai se non fosse stata Aigis."
  },
  AvgDialog_18874_Content_17 = {
    Text = "Squeak, squeak squeak!"
  },
  AvgDialog_18874_Content_18 = {
    Text = "Come dici tu, come dici tu. Brown è la più furba!"
  },
  AvgDialog_18874_Content_19 = {
    Text = "Squeak, squeak."
  },
  AvgDialog_18874_Content_2 = {
    Text = "14:01, Laboratorio di Lily"
  },
  AvgDialog_18874_Content_20 = {
    Text = "Non preoccuparti, quella donna ha così tanti gioielli. Ho preso solo due anelli; non se ne accorgerà!"
  },
  AvgDialog_18874_Content_21 = {
    Text = "Beh... hehe, ora so dove tiene tutte le cose belle. Quando troverò mia sorella, ripulirò tutti i tesori di quella donna odiosa!"
  },
  AvgDialog_18874_Content_22 = {Text = "Squeak!"},
  AvgDialog_18874_Content_23 = {
    Text = "Va bene, smettila di parlare—hmm?\nCos'è... quel suono?"
  },
  AvgDialog_18874_Content_24 = {
    Text = "In fondo al corridoio, qualcosa tremolò dietro l'angolo."
  },
  AvgDialog_18874_Content_25 = {Text = "Brown."},
  AvgDialog_18874_Content_26 = {
    Text = "Il topo balzò giù dalla tracolla e, con la sua agilità unica, sgattaiolò silenziosamente lungo il muro per controllare dietro l'angolo."
  },
  AvgDialog_18874_Content_27 = {Text = "Squeak!"},
  AvgDialog_18874_Content_28 = {
    Text = "Sentendo il segnale del suo compagno che indicava sicurezza, la ragazza si accucciò e lo seguì.\nSi appoggiò al muro, sbirciando avanti, e tirò un sospiro di sollievo quando non trovò nessuno davanti a sé."
  },
  AvgDialog_18874_Content_29 = {
    Text = "Decidendo di andarsene in fretta, la ragazza ritirò la testa ma colse con la coda dell'occhio un'ombra pallida."
  },
  AvgDialog_18874_Content_3 = {
    Text = "Come potete vedere, nonostante i nostri sforzi, ci sono troppe persone bisognose, e questo laboratorio non durerà ancora a lungo. Io... sigh!"
  },
  AvgDialog_18874_Content_30 = {Text = "?"},
  AvgDialog_18874_Content_31 = {
    Text = "Si avventurò nel corridoio e trovò un oggetto bianco dalla forma irregolare posato sul pavimento di legno non troppo pulito, simile a una specie di pietra."
  },
  AvgDialog_18874_Content_32 = {
    Text = "Sembra essere parte di una maschera di pietra, realizzata con grande precisione. Ogni sopracciglio è stato scolpito meticolosamente, apparendo incredibilmente realistico."
  },
  AvgDialog_18874_Content_33 = {
    Text = "Cos'è questo? Non ho visto nessuna maschera di pietra o statua in lavorazione nel laboratorio."
  },
  AvgDialog_18874_Content_34 = {
    Text = "Inclinò la testa, guardandosi intorno con curiosità, e toccò con l'indice."
  },
  AvgDialog_18874_Content_35 = {
    Text = "Perché è ancora calda...?"
  },
  AvgDialog_18874_Content_36 = {
    Text = "Stava per raccogliere la maschera quando le sue labbra di pietra si aprirono improvvisamente, emettendo un gemito di dolore ultraterreno."
  },
  AvgDialog_18874_Content_37 = {Text = "!!"},
  AvgDialog_18874_Content_38 = {
    Text = "Indietreggia di due passi per il terrore; tra i suoi respiri affannosi, percepisce il fetore di carne in putrefazione."
  },
  AvgDialog_18874_Content_39 = {
    Text = "Mostro, mostro... Mostro!"
  },
  AvgDialog_18874_Content_4 = {
    Text = "L-la Signorina Sarah lavora così duramente ogni giorno; ha persino venduto le sue cose preferite per sostenere il laboratorio. P-per favore, aiutateci..."
  },
  AvgDialog_18874_Content_40 = {
    Text = [[
14:37, Laboratorio di Lily
Stanza di Aigis]]
  },
  AvgDialog_18874_Content_41 = {
    Text = "Così sono scappata, poi ho sbattuto contro di voi. Poi avete insistito per portarmi a \"riposare\", e ora sono qui."
  },
  AvgDialog_18874_Content_42 = {
    Text = "Questa volta dovrebbe essere abbastanza dettagliato."
  },
  AvgDialog_18874_Content_43 = {Text = "Hmm..."},
  AvgDialog_18874_Content_44 = {
    Text = "Due bambini siedono fianco a fianco sul letto. Li osservi, specialmente Jenkin, e alla fine poni la domanda."
  },
  AvgDialog_18874_Content_45 = {
    Text = "Sei... un maschio o una femmina?"
  },
  AvgDialog_18874_Content_46 = {
    Text = "Ma hai gli occhi rotti o cosa!? Sono una ragazza, una ragazza!"
  },
  AvgDialog_18874_Content_47 = {
    Text = "Confermo, confermo."
  },
  AvgDialog_18874_Content_48 = {
    Text = "Onestamente, ma che razza di persona è? Ha perso il senno...? \nHai finito di fare domande? Se hai finito, tocca a me."
  },
  AvgDialog_18874_Content_49 = {
    Text = "Jenkin agitò la mano, tirando fuori un portafoglio da qualche parte.\nLa forma familiare, l'impronta dello stemma dei Mythag: senza dubbio, è il tuo portafoglio, ma..."
  },
  AvgDialog_18874_Content_5 = {
    Text = "Non dire un'altra parola, mia cara piccola Aigis. Se il laboratorio dovesse davvero fallire, non ti lascerò mai morire di fame, anche se dovessi restare a digiuno io stessa!"
  },
  AvgDialog_18874_Content_50 = {
    Text = "...Perché è vuoto dentro? Dove sono i miei soldi!"
  },
  AvgDialog_18874_Content_51 = {
    Text = "Non è questo il punto!"
  },
  AvgDialog_18874_Content_52 = {
    Text = "Ehm, beh, nonostante il mio aspetto, so leggere un po'.\nQui dentro non c'è un certificato di {Male=Lord,Female=Lady}, %player%."
  },
  AvgDialog_18874_Content_53 = {
    Text = "Se dicessi a quella donna odiosa chi siete davvero voi due, pensate che farebbe cacciare fuori dai tizi alla porta?"
  },
  AvgDialog_18874_Content_54 = {
    Text = "È una bambina della Zanna?"
  },
  AvgDialog_18874_Content_55 = {
    Text = "No... altrimenti, ahah, il nostro laboratorio ha una sicurezza molto rigida e non permette a persone di provenienza sconosciuta di entrare o uscire."
  },
  AvgDialog_18874_Content_56 = {
    Text = "A giudicare dalla reazione di Sarah, chiaramente non conosce Jenkin. Quindi allora—"
  },
  AvgDialog_18874_Content_57 = {
    Text = "Se ci beccano, non sarà solo un problema mio, giusto? Dopotutto, nemmeno voi appartenete al laboratorio."
  },
  AvgDialog_18874_Content_58 = {
    Text = "Io ho molti modi per entrare. Ma per voi, avendo perso lo status di autonomi, sarà difficile intrufolarvi di nuovo."
  },
  AvgDialog_18874_Content_59 = {
    Text = "...è lo sponsor."
  },
  AvgDialog_18874_Content_6 = {
    Text = "Signorina Sarah...! I-io sarò ubbidiente, mi prenderò cura di lei, la ripagherò, e non le sarò di peso."
  },
  AvgDialog_18874_Content_60 = {
    Text = "Non importa! In ogni caso, o mi fate un favore, o soffriamo entrambi!"
  },
  AvgDialog_18874_Content_61 = {
    Text = "Sia chiaro, io non rubo."
  },
  AvgDialog_18874_Content_62 = {
    Text = "Ho forse bisogno del vostro aiuto per rubare qualcosa? No, voglio che mi aiutiate a trovare qualcuno!"
  },
  AvgDialog_18874_Content_63 = {
    Text = "Dimmi pure le tue richieste."
  },
  AvgDialog_18874_Content_64 = {
    Text = "Ho bisogno che troviate qualcuno per me, una persona molto importante."
  },
  AvgDialog_18874_Content_65 = {Text = "Chi?"},
  AvgDialog_18874_Content_66 = {
    Text = "Mia sorella, Mason."
  },
  AvgDialog_18874_Content_7 = {Text = "..."},
  AvgDialog_18874_Content_8 = {
    Text = "Mia cara piccola Aigis—"
  },
  AvgDialog_18874_Content_9 = {
    Text = "Guardando la scena che si svolge tra le due—soprattutto Sarah—non puoi fare a meno di sentirti un po' impotente.\nAnche se le capisci, l'aiuto che puoi offrire non è di tipo economico."
  },
  AvgDialog_18875_Content_1 = {
    Text = "Piccolo Detective"
  },
  AvgDialog_18875_Content_10 = {
    Text = "Tsk, vabbè. Per poco non mi facevi beccare. La responsabilità è tua."
  },
  AvgDialog_18875_Content_11 = {
    Text = "A essere sincera, non faccio davvero parte di questo laboratorio scalcinato.\nMi chiamo Jenkin, e questo è Brown."
  },
  AvgDialog_18875_Content_12 = {Text = "Squeak!"},
  AvgDialog_18875_Content_13 = {
    Text = "Sono venuta qui per cercare mia sorella. Si chiama Mason, ed è scomparsa qui vicino due settimane fa.\nQualcuno di nome Mason è apparso da queste parti di recente?"
  },
  AvgDialog_18875_Content_14 = {
    Text = "Mi dispiace, io... non lo so... mi dispiace..."
  },
  AvgDialog_18875_Content_15 = {
    Text = "Pensaci bene. È alta più o meno così, con i capelli lunghi legati con un bel nastro rosso."
  },
  AvgDialog_18875_Content_16 = {Text = "..."},
  AvgDialog_18875_Content_17 = {
    Text = "L'hai vista o no? Rispondimi. Quei bastardi della vostra Zanna l'hanno catturata e costretta a lavorare?"
  },
  AvgDialog_18875_Content_18 = {
    Text = "Tsk, impossibile. Tu non sai niente. Devo restare, anche se devo infiltrarmi nel laboratorio sotto copertura—"
  },
  AvgDialog_18875_Content_19 = {
    Text = "Non se ne parla! Se ti unisci, verrai guarito. Non se ne parla!"
  },
  AvgDialog_18875_Content_2 = {
    Text = [[
3 giorni fa, Zanna Est di Londinium
Laboratorio di Lily]]
  },
  AvgDialog_18875_Content_20 = {
    Text = "Abbassa la voce! Tu forse non hai paura di essere scoperta, ma io sì!"
  },
  AvgDialog_18875_Content_21 = {
    Text = "Ti aiuterò a trovare tua sorella. Posso nasconderti e portarti del cibo, ma non unirti al laboratorio, va bene?"
  },
  AvgDialog_18875_Content_22 = {
    Text = "Davvero? È meraviglioso! Giuro che ti ripagherò!"
  },
  AvgDialog_18875_Content_23 = {
    Text = "A proposito, come ti chiami?"
  },
  AvgDialog_18875_Content_24 = {
    Text = "Io... mi chiamo Aigis."
  },
  AvgDialog_18875_Content_25 = {
    Text = "Piacere di conoscerti, Aigis. Da oggi in poi siamo amiche!"
  },
  AvgDialog_18875_Content_26 = {
    Text = [[
15:00, Londinium Est
La Zanna di Lily]]
  },
  AvgDialog_18875_Content_27 = {
    Text = "Più tardi, Aigis mi ha aiutata a nascondermi nel magazzino, e ho cercato mia sorella nel laboratorio quando gli adulti non facevano attenzione."
  },
  AvgDialog_18875_Content_28 = {
    Text = "Pensavo che l'avremmo sicuramente trovata quando tutti erano riuniti durante la pausa.\nMa non ho visto nessuno ieri né l'altro ieri, quindi posso solo controllare di giorno durante il lavoro."
  },
  AvgDialog_18875_Content_29 = {
    Text = [[
Non ho paura di essere cacciata fuori, ma non voglio problemi, a differenza tua.
Con il tuo status, puoi aggirarmi per il laboratorio senza che nessuno ci faccia caso.]]
  },
  AvgDialog_18875_Content_3 = {
    Text = "Il Distretto Est avvolto dall'Oscurità, notte fonda. Lampioni, luce lunare, nulla penetrava la nebbia, lasciando solo ombre sfocate ondeggiare nell'aria."
  },
  AvgDialog_18875_Content_30 = {
    Text = "Non chiedo molto, solo un'occhiata per verificare se mia sorella è tra i lavoratori."
  },
  AvgDialog_18875_Content_31 = {
    Text = "Aiutami, ti restituirò il portafoglio e i documenti, tieni il segreto.\nNon aiutarmi... hehe!"
  },
  AvgDialog_18875_Content_32 = {Text = "Decidi tu!"},
  AvgDialog_18875_Content_33 = {
    Text = "Perché sei così sicura che tua sorella sia qui?"
  },
  AvgDialog_18875_Content_34 = {
    Text = "Forse non lo sai, ma questa è la famosa \"Zanna Divoratrice\". Molte persone sono scomparse qui intorno, inclusa mia sorella."
  },
  AvgDialog_18875_Content_35 = {
    Text = "Qualche giorno fa, ho visto un'<Red:ombra scura> sfrecciare nel cortile di notte. Deve esserci qualcosa di strano in corso."
  },
  AvgDialog_18875_Content_36 = {
    Text = "......Va bene, ti aiuterò a trovare tua sorella. In cambio, devi aiutarmi a indagare sul laboratorio, d'accordo?"
  },
  AvgDialog_18875_Content_37 = {
    Text = "Affare fatto!"
  },
  AvgDialog_18875_Content_38 = {
    Text = "Sputa nel palmo della mano e ti guarda con aria d'attesa."
  },
  AvgDialog_18875_Content_39 = {Text = "..."},
  AvgDialog_18875_Content_4 = {
    Text = "Due piccole figure stanno in piedi nell'angolo del cortile anteriore del Laboratorio."
  },
  AvgDialog_18875_Content_40 = {
    Text = "Cosa aspetti? Stringi la mano. Non hai rispetto per le regole della strada?"
  },
  AvgDialog_18875_Content_41 = {
    Text = "Stringile la mano"
  },
  AvgDialog_18875_Content_42 = {
    Text = "La imiti, sputi nel palmo della mano e le stringi la mano con fermezza."
  },
  AvgDialog_18875_Content_43 = {
    Text = "Molto sveglia, ragazza del West Side. Ti avevo sottovalutata."
  },
  AvgDialog_18875_Content_44 = {
    Text = "La imiti, sputi nel palmo della mano e le stringi la mano con fermezza."
  },
  AvgDialog_18875_Content_45 = {
    Text = "È un piacere lavorare con te!"
  },
  AvgDialog_18875_Content_46 = {
    Text = [[
14:50, Londinium Est
La Zanna di Lily]]
  },
  AvgDialog_18875_Content_47 = {
    Text = "Signorina Mary, la prego, deve assolutamente porgere le mie più sincere scuse a {Male=Lord,Female=Lady} Ashe."
  },
  AvgDialog_18875_Content_48 = {
    Text = "Il laboratorio è pieno di povera gente dal cuore buono. Quella ragazzina non è... ehm, cioè, le darò una lezione!"
  },
  AvgDialog_18875_Content_49 = {
    Text = "Ramona stava per rispondere quando intravide una strana figura in fondo al corridoio."
  },
  AvgDialog_18875_Content_5 = {
    Text = "T-Tu non sei Mac o Lucy! Chi sei...?!"
  },
  AvgDialog_18875_Content_50 = {
    Text = "Signorina Mary?"
  },
  AvgDialog_18875_Content_51 = {
    Text = "Cos'è quello...?"
  },
  AvgDialog_18875_Content_6 = {
    Text = "Dovrei essere io a chiedere chi sei! Andare in giro nel cuore della notte, la gente potrebbe scambiarti per quel famigerato squartatore."
  },
  AvgDialog_18875_Content_7 = {
    Text = "Non sono io! Non sono io!"
  },
  AvgDialog_18875_Content_8 = {
    Text = "Shh! Ma ce le hai le orecchie? Ti ho detto di abbassare la voce!"
  },
  AvgDialog_18875_Content_9 = {
    Text = "Io... io... mi dispiace, è solo che... non sono... io..."
  },
  AvgDialog_18876_Content_1 = {
    Text = "Etichetta Inespressa"
  },
  AvgDialog_18876_Content_10 = {
    Text = "Era davvero straordinario. Ha persino curato gli occhi di Aigis, liberandola dai fantasmi."
  },
  AvgDialog_18876_Content_100 = {
    Text = "Squeak, squeak."
  },
  AvgDialog_18876_Content_101 = {
    Text = "Anche se potrebbe sapere dove si trova mia sorella, io... No, non credo che sia una cattiva persona.\nAndiamo per ora. Troverò un momento tranquillo più tardi per chiederle con calma."
  },
  AvgDialog_18876_Content_11 = {
    Text = "Vero, Aigis?"
  },
  AvgDialog_18876_Content_12 = {
    Text = "...Sì, il Dott. Miller... molto impressionante..."
  },
  AvgDialog_18876_Content_13 = {
    Text = "Non se ne parla! Se ti unisci, verrai guarito. Non se ne parla!"
  },
  AvgDialog_18876_Content_14 = {
    Text = "Ti aiuterò a trovare tua sorella, te lo prometto. Posso nasconderti, ma non unirti al laboratorio, d'accordo?"
  },
  AvgDialog_18876_Content_15 = {
    Text = "Dalla descrizione di Jenkin e dalle sue reazioni attuali, questa bambina sembra essere piena di paura verso il Dott. Miller e il \"trattamento\"."
  },
  AvgDialog_18876_Content_16 = {
    Text = "Se quel ricercatore sta collaborando con il Dott. Miller, allora questa cosiddetta \"terapia sperimentale\" probabilmente coinvolge la Dissoluzione e i D-marchi."
  },
  AvgDialog_18876_Content_17 = {
    Text = "In quel momento, alcune inservienti vestite da cuoche spinsero dei carrelli, portando l'aroma di porridge d'avena."
  },
  AvgDialog_18876_Content_18 = {
    Text = "Oh cielo, ho completamente perso la cognizione del tempo, {Male=Lord,Female=Lady} Ashe dev'essere affamato."
  },
  AvgDialog_18876_Content_19 = {
    Text = [[
Aigis, sii brava e vai a cercare Diana per portare i pasti agli ospiti.
Poi potrai consegnare i pasti ai pazienti, d'accordo?]]
  },
  AvgDialog_18876_Content_2 = {
    Text = [[
15:11, Londinium Est
Zanna di Lily]]
  },
  AvgDialog_18876_Content_20 = {
    Text = "Capito, signorina Sarah. Vado subito."
  },
  AvgDialog_18876_Content_21 = {
    Text = "La ragazza portava il vassoio, camminando lentamente accanto a ogni letto, salutando i pazienti lucidi o deliranti."
  },
  AvgDialog_18876_Content_22 = {
    Text = "Buon pomeriggio, nonna Thompson; buon pomeriggio, zio Kelvin..."
  },
  AvgDialog_18876_Content_23 = {
    Text = "Si fermò accanto a un letto vicino alla finestra.\nSul letto giaceva un vecchio, gli arti legati con strisce di stoffa, che gemeva di dolore."
  },
  AvgDialog_18876_Content_24 = {
    Text = "Nonno Robert, ti ho messo il pasto qui accanto. Non dimenticare di mangiare!"
  },
  AvgDialog_18876_Content_25 = {
    Text = "La ragazza abbassò la testa per sistemare la coperta del vecchio, completamente ignara che un triangolo nero come la pece stava silenziosamente divorando il suo volto, fondendo i suoi lineamenti in una melma scura."
  },
  AvgDialog_18876_Content_26 = {
    Text = [[
Devi mangiare bene per guarire in fretta.
Quando starai meglio, potremo andare insieme al Parco Delair a dare da mangiare ai piccioni.]]
  },
  AvgDialog_18876_Content_27 = {
    Text = "Il braccio emaciato del vecchio strappò la fascia che lo legava e si sollevò all'improvviso—"
  },
  AvgDialog_18876_Content_28 = {
    Text = "Se avessimo più fondi, potremmo assumere più professionisti, e i pazienti potrebbero riprendersi in strutture migliori—"
  },
  AvgDialog_18876_Content_29 = {Text = "!"},
  AvgDialog_18876_Content_3 = {
    Text = [[
Hai seguito Sarah in una stanza piena di letti improvvisati.
Sembra che questo posto fosse originariamente una mensa, con un tavolo da pranzo ancora al centro.]]
  },
  AvgDialog_18876_Content_30 = {
    Text = "Ti volti rapidamente verso la fonte del rumore e vedi un mostro il cui volto è stato completamente sostituito da buchi neri che afferra Aigis."
  },
  AvgDialog_18876_Content_31 = {Text = "Aigis!"},
  AvgDialog_18876_Content_32 = {
    Text = "Ramona reagì prontamente. Si fece strada tra la folla caotica e colpì la spalla del mostro con il fodero del suo stocco."
  },
  AvgDialog_18876_Content_33 = {
    Text = "Il mostro allentò la presa, e gli inservienti nelle vicinanze accorsero rapidamente per legare di nuovo al letto la creatura ancora urlante."
  },
  AvgDialog_18876_Content_34 = {
    Text = "Nonno Robert, nonno Robert—"
  },
  AvgDialog_18876_Content_35 = {
    Text = [[
Tra le grida della ragazza, guardasti la "persona" che si dibatteva nel letto, provando un'ondata di tristezza.
<Yellow:Dissoluzione avanzata>, a questo vecchio restavano solo pochi giorni per mantenere a malapena una forma umana.]]
  },
  AvgDialog_18876_Content_36 = {
    Text = "Bende, ho trovato le bende! Aigis, presto, fammi vedere la ferita!"
  },
  AvgDialog_18876_Content_37 = {
    Text = "Nonno Robert, sbrigatevi ad aiutare nonno Robert."
  },
  AvgDialog_18876_Content_38 = {
    Text = "Perché pensi ancora agli altri in un momento come questo? Se la ferita non viene trattata subito, sarà un problema!"
  },
  AvgDialog_18876_Content_39 = {
    Text = "Jenkin afferrò il braccio di Aigis e, senza esitare, le tirò su la manica, rivelando una ferita da cui colava sangue."
  },
  AvgDialog_18876_Content_4 = {
    Text = "Per prenderci cura di loro, abbiamo dovuto dirottare parte della manodopera, il che ha influito sull'efficienza lavorativa e sui ricavi del laboratorio. In più, c'era quella strana malattia..."
  },
  AvgDialog_18876_Content_40 = {
    Text = "Quel maledetto pazzo ha graffiato così forte!"
  },
  AvgDialog_18876_Content_41 = {
    Text = "Il sottile graffio sul braccio della ragazza trasuda sangue, ma rispetto alla grottesca cicatrice nera che le attraversa il polso, è cosa da poco."
  },
  AvgDialog_18876_Content_42 = {
    Text = "Punti di sutura intrecciati tirano la pelle da entrambi i lati verso il centro, tentando di \"chiudere\" l'apertura nera, ma finendo invece per farla sembrare una bocca avida e vorace."
  },
  AvgDialog_18876_Content_43 = {
    Text = "Questo è un <Yellow:D-marchio>, contorto come quelli dei pazienti."
  },
  AvgDialog_18876_Content_44 = {
    Text = "...Jenkin, vai a prendere dell'acqua."
  },
  AvgDialog_18876_Content_45 = {
    Text = "Jenkin annuì vigorosamente e corse via."
  },
  AvgDialog_18876_Content_46 = {
    Text = "Ramona pulì delicatamente il sangue di Aigis con un fazzoletto, evitando il polso.\nAigis guardò Ramona, poi te, con aria esitante."
  },
  AvgDialog_18876_Content_47 = {
    Text = "Aigis, c'è qualcosa che vuoi dire?"
  },
  AvgDialog_18876_Content_48 = {Text = "!"},
  AvgDialog_18876_Content_49 = {
    Text = "No, no... Io non..."
  },
  AvgDialog_18876_Content_5 = {
    Text = "Non volevo rischiare la fiducia dello sponsor, quindi ho tenuto tutto nascosto. Solo lo sponsor principale, <Blue:il Sig. Rogers>, è al corrente."
  },
  AvgDialog_18876_Content_50 = {
    Text = "Non avere paura, Aigis. Qualunque cosa sia, ti aiuteremo sicuramente."
  },
  AvgDialog_18876_Content_51 = {
    Text = "Non avere paura, Aigis. Il dottor Miller è qui per aiutarti."
  },
  AvgDialog_18876_Content_52 = {
    Text = "Non avere paura, Aigis. È solo una puntura. Non farà male."
  },
  AvgDialog_18876_Content_53 = {
    Text = "Non avere paura, Aigis. Finirà presto."
  },
  AvgDialog_18876_Content_54 = {
    Text = "Non avere paura, Aigis..."
  },
  AvgDialog_18876_Content_55 = {
    Text = "Non avere paura..."
  },
  AvgDialog_18876_Content_56 = {Text = "Aigis?"},
  AvgDialog_18876_Content_57 = {
    Text = [[
La ragazza scosse vigorosamente la testa.
Proprio in quel momento, dopo aver calmato gli altri lavoratori, Sarah accorse da voi.]]
  },
  AvgDialog_18876_Content_58 = {
    Text = "Aigis, tu stai— oh mio Dio, stai sanguinando! Dove sono le bende? Presto, prendete le bende!"
  },
  AvgDialog_18876_Content_59 = {
    Text = "Sto bene, signorina Sarah.\nMi dispiace, è stata una mia disattenzione a farvi preoccupare."
  },
  AvgDialog_18876_Content_6 = {
    Text = "Ti sei guardato intorno, i pazienti mostravano diversi gradi di dissoluzione, ciascuno distorto come l'uomo di prima."
  },
  AvgDialog_18876_Content_60 = {
    Text = "Tu... sigh. Quante volte te l'ho detto? Questi pazzi sono pericolosi. Ma tu non hai voluto ascoltare e hai insistito per occuparti di portare loro il cibo. Perché sei così testarda?"
  },
  AvgDialog_18876_Content_61 = {
    Text = "Mi dispiace... Non volevo che succedesse..."
  },
  AvgDialog_18876_Content_62 = {
    Text = "So che vuoi condividere il peso con tutti, ma devi valutare le tue capacità. Non finiresti per creare problemi a tutti quanti?"
  },
  AvgDialog_18876_Content_63 = {
    Text = "Sei davvero un bel grattacapo. Come farai a crescere se continui a fare di testa tua—"
  },
  AvgDialog_18876_Content_64 = {
    Text = "Hai finito di parlare?!"
  },
  AvgDialog_18876_Content_65 = {
    Text = "Jenkin tornò inaspettatamente, gettando un secchio a terra e mettendosi davanti ad Aigis."
  },
  AvgDialog_18876_Content_66 = {
    Text = "Ogni giorno Aigis lavora così duramente e vi aiuta con così tante cose. Cos'altro potreste pretendere?\nCrescere? Se crescere significa fare tutto quello che dite voi, allora è meglio non crescere mai!"
  },
  AvgDialog_18876_Content_67 = {
    Text = "C-Cosa sta succedendo?"
  },
  AvgDialog_18876_Content_68 = {
    Text = [[
Ti volti al suono e vedi due persone in piedi dietro di te.
Una di loro la riconosci: una volta ti ha consegnato un questionario psicologico per strada.]]
  },
  AvgDialog_18876_Content_69 = {
    Text = [[
Signor Rogers, dottor Fairfax!
Di solito venite di sera. Se me lo aveste detto prima, vi avrei accolto alla porta.]]
  },
  AvgDialog_18876_Content_7 = {
    Text = "Stranamente, la persona in camice bianco chiamata \"<Blue:Ricercatore>\" durante la spiegazione di Sarah non è qui ora."
  },
  AvgDialog_18876_Content_70 = {
    Text = "N-non sono un estraneo qui, signorina Sarah. Non c'è bisogno.\nA proposito, perché la piccola Aigis piange così disperatamente? Qualcuno le ha fatto del male?"
  },
  AvgDialog_18876_Content_71 = {
    Text = "È tutta colpa di quella maledetta Sarah! Lei è solo..."
  },
  AvgDialog_18876_Content_72 = {
    Text = "Mentre Jenkin gridava, Clementine si chinò e prese abilmente la mano di Aigis."
  },
  AvgDialog_18876_Content_73 = {
    Text = "La piccola Aigis ha incontrato nuovi problemi? Dovremmo parlare di nuovo con la Dottoressa Clementine?"
  },
  AvgDialog_18876_Content_74 = {
    Text = "Aspetta, tu chi sei? Non tirarmi in giro a caso."
  },
  AvgDialog_18876_Content_75 = {
    Text = "Conosco la piccola Aigis da molto tempo, nuova arrivata. Ogni volta che Aigis si sentiva triste in passato, veniva sempre da me per fare due chiacchiere."
  },
  AvgDialog_18876_Content_76 = {
    Text = "Dopotutto, parlare delle proprie preoccupazioni è uno dei modi per guarire psicologicamente, e io sono un'ascoltatrice molto professionale.\nVuoi unirti a noi? Sembra che anche tu sia turbata da qualcosa."
  },
  AvgDialog_18876_Content_77 = {
    Text = "Non vengo. Tutta quella roba sulla guarigione psicologica è solo strana..."
  },
  AvgDialog_18876_Content_78 = {
    Text = [[
Che peccato. Se cambi idea, sentiti libera di unirti a noi in qualsiasi momento.
Andiamo, Aigis.]]
  },
  AvgDialog_18876_Content_79 = {
    Text = "Dopo che le due se ne vanno, riporti la tua attenzione sul presente."
  },
  AvgDialog_18876_Content_8 = {
    Text = "Il Sig. Rogers è stato tra i primi a notare la strana malattia e ha monitorato da vicino le condizioni dei pazienti. È stato lui a presentarci il Dott. <Blue:Miller>, un esperto nella ricerca di malattie rare e difficili."
  },
  AvgDialog_18876_Content_80 = {
    Text = "George Rogers, piacere di conoscervi entrambi."
  },
  AvgDialog_18876_Content_81 = {
    Text = "Libera una mano per stringere delicatamente la tua. Nel momento in cui i palmi si toccano, un'ondata di intensa vertigine ti travolge."
  },
  AvgDialog_18876_Content_82 = {
    Text = [[
Tutto intorno a te si scioglie come cera, persino la persona di fronte a te si distorce.
Sotto il volto giovanile, scheletri pallidi si intrecciano come rampicanti.]]
  },
  AvgDialog_18876_Content_83 = {
    Text = "L'inquietante illusione svanì senza lasciare traccia dopo qualche battito di ciglia, lasciando solo un acuto ronzio nelle orecchie — era un'allucinazione nata dalla stanchezza, o un presagio di qualche tipo?"
  },
  AvgDialog_18876_Content_84 = {
    Text = "Non ne hai idea. Sai solo che è simile a ciò che hai sperimentato al cimitero qualche giorno fa."
  },
  AvgDialog_18876_Content_85 = {
    Text = "...Viene ogni mese per controllare le condizioni dei pazienti. Grazie a lui, siamo riusciti a creare questa zona di cura per guarire i pazienti. È il vero benefattore del laboratorio."
  },
  AvgDialog_18876_Content_86 = {
    Text = "S-signorina Sarah, mi lusingate troppo. Sono solo una persona comune che cerca di fare qualcosa per il mondo."
  },
  AvgDialog_18876_Content_87 = {
    Text = "Piacere di conoscerla, Signor Rogers. Mi chiamo Ash, e questo è il mio maggiordomo, Mary.\nQuesto bambino è Jenkin... eh?"
  },
  AvgDialog_18876_Content_88 = {
    Text = "Dove sei scappato di nuovo?"
  },
  AvgDialog_18876_Content_89 = {
    Text = "Aigis teneva la mano di Clementine e seguiva il suo passo, passeggiando nel cortile anteriore."
  },
  AvgDialog_18876_Content_9 = {
    Text = "Il Dott. Miller ha accettato di fornirci cure gratuite, chiedendo solo di utilizzare la sua \"<Blue:Terapia Sperimentale>\"."
  },
  AvgDialog_18876_Content_90 = {
    Text = "Capisco, quella <Red:\"voce\"> che appare sempre nella tua mente di notte ti ha fatto fare di nuovo cose brutte?"
  },
  AvgDialog_18876_Content_91 = {
    Text = "Ho provato a chiudere la porta a chiave, a coprirmi le orecchie... ma la \"voce\" trova sempre un modo per raggiungermi, per raggiungere tutti..."
  },
  AvgDialog_18876_Content_92 = {
    Text = "Tutti hanno dimenticato la \"voce,\" ma non io. Anche se volessi, non potrei dimenticarla."
  },
  AvgDialog_18876_Content_93 = {
    Text = "Sono morte così tante persone, inclusa la sorella di Jenkin... Non ce la faccio più. Se le cose continuano così, prima o poi, la polizia ci troverà e ci arresterà tutti!"
  },
  AvgDialog_18876_Content_94 = {
    Text = "Pensi che siano innocenti?"
  },
  AvgDialog_18876_Content_95 = {
    Text = "So che sono innocenti! È tutta colpa di quella \"voce.\" Ha cambiato tutti, me compresa..."
  },
  AvgDialog_18876_Content_96 = {
    Text = "Puoi aiutarmi, Dottoressa Clementine? Nessuno crede al mio avvertimento, ma forse ascolterebbero te."
  },
  AvgDialog_18876_Content_97 = {
    Text = "Le \"voci\" che gli altri non possono sentire non contano davvero come prove, ed è difficile per le persone reagire ad avvertimenti senza prove. Ma — non scoraggiarti."
  },
  AvgDialog_18876_Content_98 = {
    Text = "In questo mondo, nulla è irraggiungibile se sei disposta a rischiare la vita per ottenerlo."
  },
  AvgDialog_18876_Content_99 = {
    Text = "Aigis abbassò la testa, persa nei suoi pensieri.\nVicino al muro del cortile, dietro una pila di casse di legno, spuntò una testa con un cappuccio marrone."
  },
  AvgDialog_18877_Content_1 = {
    Text = "Chi ha ucciso il pettirosso"
  },
  AvgDialog_18877_Content_10 = {
    Text = "Il laboratorio era avvolto nella nebbia, circondato dall'oscurità, eppure questo non sembrava influenzare la ragazza.\nCorreva avanti con tutte le sue forze."
  },
  AvgDialog_18877_Content_11 = {
    Text = "Presto, più in fretta! Se qualcuno lo scopre, se %player% lo scopre...\nCattureranno sicuramente quella persona, di sicuro."
  },
  AvgDialog_18877_Content_12 = {
    Text = "Svoltò un angolo e si fermò di colpo."
  },
  AvgDialog_18877_Content_13 = {
    Text = "No, oh no..."
  },
  AvgDialog_18877_Content_14 = {
    Text = "Non tu, piccolo Mike."
  },
  AvgDialog_18877_Content_15 = {
    Text = [[
20:50, Laboratorio di Lily
Stanza di Aigis]]
  },
  AvgDialog_18877_Content_16 = {
    Text = "Jenkin girò per la stanza vuota, con le mani sui fianchi, e sospirò."
  },
  AvgDialog_18877_Content_17 = {
    Text = "Non è in bagno, non è in cucina, e nemmeno in mensa. Dove diavolo è andata?"
  },
  AvgDialog_18877_Content_18 = {
    Text = "Si sedette direttamente a terra e infilò la mano sotto il materasso, tastando qua e là."
  },
  AvgDialog_18877_Content_19 = {
    Text = "Pazienza, prima o poi dovrà tornare a dormire. Aspetterò qui e mangerò caramelle nell'attesa!"
  },
  AvgDialog_18877_Content_2 = {
    Text = [[
20:43, Laboratorio di Lily
Stanza degli ospiti]]
  },
  AvgDialog_18877_Content_20 = {
    Text = "Squeak! Squeak! Squeak!"
  },
  AvgDialog_18877_Content_21 = {
    Text = "Non osare fare la spia! E poi, gliene comprerò altre —"
  },
  AvgDialog_18877_Content_22 = {
    Text = "Interruppe il suo movimento e tirò fuori qualcosa.\nUn nastro rosso con una fibbia d'argento, un'estremità strappata in modo irregolare."
  },
  AvgDialog_18877_Content_23 = {
    Text = "Questo è... di mia sorella...?"
  },
  AvgDialog_18877_Content_24 = {
    Text = [[
20:50, Laboratorio di Lily
Cortile Anteriore]]
  },
  AvgDialog_18877_Content_25 = {
    Text = "Il laboratorio si addormenta sotto la notte. Tu e Ramona vi affrettate a tornare, avvertendo un presagio—\nPresto, qualcosa oltre a voi infrangerà la quiete."
  },
  AvgDialog_18877_Content_26 = {Text = "%player%."},
  AvgDialog_18877_Content_27 = {
    Text = "Chiudi di nuovo gli occhi. Un freddo indescrivibile si diffonde come acqua dalla nuca fino agli arti, mentre una melodia sconosciuta svanisce gradualmente, come se stesse per essere portata via dal vento."
  },
  AvgDialog_18877_Content_28 = {
    Text = "Apri gli occhi e noti che la nebbia circostante si è diradata."
  },
  AvgDialog_18877_Content_29 = {
    Text = "Non riesco più a percepirlo, è come se... come se il suono si stesse affievolendo."
  },
  AvgDialog_18877_Content_3 = {
    Text = "Rogers mosse la mano di George per far salutare la scultura di cera a Jenkin."
  },
  AvgDialog_18877_Content_30 = {
    Text = "Le fluttuazioni spirituali degli individui speciali potrebbero essere collegate a questa nebbia?"
  },
  AvgDialog_18877_Content_31 = {Text = "!"},
  AvgDialog_18877_Content_32 = {
    Text = "Viene da quella direzione!"
  },
  AvgDialog_18877_Content_33 = {
    Text = "Corri immediatamente verso la fonte del suono e ti scontri con Jenkin all'ingresso del laboratorio."
  },
  AvgDialog_18877_Content_34 = {Text = "Jenkin?"},
  AvgDialog_18877_Content_35 = {
    Text = "Aigis non è nella stanza! Quello potrebbe essere stato— comunque, sbrighiamoci!"
  },
  AvgDialog_18877_Content_36 = {
    Text = [[
Ricordando la devastazione vista per strada, acceleri il passo ed entri nel laboratorio.
Ben presto, un barlume di luce appare in fondo al corridoio.]]
  },
  AvgDialog_18877_Content_37 = {
    Text = "Era una lanterna all'antica, tenuta in mano, che illuminava i volti della donna e della bambina."
  },
  AvgDialog_18877_Content_38 = {
    Text = "Aigis! Ho sentito un urlo. Stai bene?"
  },
  AvgDialog_18877_Content_39 = {
    Text = "La ragazzina rannicchiata tra le braccia di Sarah tremava tutta, affondando il viso ancora di più nel collo di Sarah.\nVedendo questo, Jenkin si fermò brevemente e si rivolse a Sarah con rabbia."
  },
  AvgDialog_18877_Content_4 = {
    Text = "Ciao, amico. Ti piace George?"
  },
  AvgDialog_18877_Content_40 = {
    Text = "Donna spregevole, le hai fatto qualcosa di brutto? Lasciala andare, mi hai sentito!"
  },
  AvgDialog_18877_Content_41 = {Text = "..."},
  AvgDialog_18877_Content_42 = {
    Text = "Sarah mise giù la ragazzina in silenzio.\nAnche con la testa abbassata, si poteva ancora vedere il viso rigato di lacrime di Aigis alla luce della lanterna."
  },
  AvgDialog_18877_Content_43 = {
    Text = "Potresti riportarla a riposare prima? Aigis si è persa e ha paura del buio. Ha davvero bisogno di riposare adesso."
  },
  AvgDialog_18877_Content_44 = {
    Text = "Jenkin fissò Sarah con sospetto mentre afferrava la mano di Aigis."
  },
  AvgDialog_18877_Content_45 = {
    Text = "Aigis si aggrappò al vestito di Sarah e cominciò a singhiozzare piano."
  },
  AvgDialog_18877_Content_46 = {
    Text = "Vai, piccola Aigis."
  },
  AvgDialog_18877_Content_47 = {
    Text = "Fai un bel sonno, e domani l'incubo sarà finito, d'accordo?"
  },
  AvgDialog_18877_Content_48 = {
    Text = "Ma... Signorina Sarah..."
  },
  AvgDialog_18877_Content_49 = {
    Text = "Andiamo. Ho una luce, quindi non c'è bisogno di preoccuparsi."
  },
  AvgDialog_18877_Content_5 = {
    Text = "Così bello, a chi non piacerebbe? Vero, Aigis?"
  },
  AvgDialog_18877_Content_50 = {
    Text = [[
I due bambini si allontanano mano nella mano.
Sarah si volta verso di te con un sorriso leggermente rigido.]]
  },
  AvgDialog_18877_Content_51 = {
    Text = "Scusate, siete stati disturbati dalle mie urla?"
  },
  AvgDialog_18877_Content_52 = {
    Text = "I giorni di nebbia rendono sempre le persone inquiete, e sono stata spaventata da un'ombra. Per favore, datemi la possibilità di scusarmi e permettetemi di preparare una teiera per entrambi."
  },
  AvgDialog_18877_Content_53 = {
    Text = "Non c'è bisogno di tanto disturbo, Signorina Sarah. Possiamo tornare da soli."
  },
  AvgDialog_18877_Content_54 = {
    Text = [[
Come sarebbe possibile? Vi prego, promettetemelo, {Male=Lord,Female=Lady} Ashe, Signorina Mary.
Altrimenti non riesco a stare tranquilla!]]
  },
  AvgDialog_18877_Content_55 = {
    Text = "Se la Signorina Sarah insiste così, allora ci accompagni per una passeggiata nel laboratorio.\nDopo, il tè avrà un sapore ancora più dolce, non crede?"
  },
  AvgDialog_18877_Content_56 = {
    Text = "...D'accordo. Da questa parte, prego."
  },
  AvgDialog_18877_Content_57 = {
    Text = [[
21:03, Laboratorio di Lily
Corridoio verso la Stanza di Aigis]]
  },
  AvgDialog_18877_Content_58 = {
    Text = "Jenkin, tu... vai prima nella mia stanza. Io vado in bagno."
  },
  AvgDialog_18877_Content_59 = {
    Text = "Esci di nuovo? Non hai paura? Vuoi che ti accompagni?"
  },
  AvgDialog_18877_Content_6 = {
    Text = [[
......
Scusa, Jenkin, io... scusa, devo allontanarmi un momento.]]
  },
  AvgDialog_18877_Content_60 = {
    Text = "Va tutto bene, torno subito."
  },
  AvgDialog_18877_Content_61 = {Text = "Subito."},
  AvgDialog_18877_Content_62 = {
    Text = [[
22:00, Laboratorio di Lily
Camera degli Ospiti]]
  },
  AvgDialog_18877_Content_63 = {
    Text = "È ora. La consulenza di oggi si conclude qui."
  },
  AvgDialog_18877_Content_64 = {
    Text = "Grazie, Dott.ssa Clementine.\nOgni volta che parliamo, sento che la mia mente diventa molto più lucida."
  },
  AvgDialog_18877_Content_65 = {
    Text = "È il mio dovere.\nDimmi, sai cosa fare adesso?"
  },
  AvgDialog_18877_Content_66 = {
    Text = "Certo. Continuerò."
  },
  AvgDialog_18877_Content_67 = {
    Text = "Come diceva lui: La bellezza alla fine sostituirà ogni sofferenza."
  },
  AvgDialog_18877_Content_7 = {
    Text = "Aigis? Dove vai? Ehi, Aigis!"
  },
  AvgDialog_18877_Content_8 = {
    Text = [[
20:44, Laboratorio di Lily
Ccorridoio]]
  },
  AvgDialog_18877_Content_9 = {
    Text = [[
Corre.
Aigis sta correndo.]]
  },
  AvgDialog_18878_Content_1 = {
    Text = "Ogier e Ramona immobilizzano Jenkin, che oppone resistenza, bloccandola da entrambi i lati."
  },
  AvgDialog_18878_Content_10 = {
    Text = "<Italic:Il soriano del vecchio Charlie, grasso e caro...>"
  },
  AvgDialog_18878_Content_11 = {
    Text = "\"Sorella... non andartene...\""
  },
  AvgDialog_18878_Content_12 = {
    Text = "La voce di Jenkin emerge dalla luce. Cerca di protendersi verso di te, ma è trattenuta dai fili neri, come una marionetta."
  },
  AvgDialog_18878_Content_13 = {
    Text = [[
Comprendi che qualcosa, o qualcuno, la sta controllando.
Mentre ti muovi per aiutarla, i fili si assottigliano e svaniscono.]]
  },
  AvgDialog_18878_Content_14 = {
    Text = "\"No... Aigis...?\""
  },
  AvgDialog_18878_Content_15 = {
    Text = "La luce si ritira, lo spazio nero si dissolve rapidamente."
  },
  AvgDialog_18878_Content_16 = {
    Text = "Apri gli occhi e incontri lo sguardo smarrito di Jenkin."
  },
  AvgDialog_18878_Content_17 = {
    Text = "%player%...? Che è successo? Qualcosa non va?"
  },
  AvgDialog_18878_Content_18 = {
    Text = "SQUEAK SQUEAK!"
  },
  AvgDialog_18878_Content_19 = {
    Text = "Jenkin sbatte le palpebre sugli occhi aridi e tenta di mettersi seduta, solo per scoprire di essere legata."
  },
  AvgDialog_18878_Content_2 = {
    Text = "È... isterica...?"
  },
  AvgDialog_18878_Content_20 = {
    Text = "Che diav—?! Chi è stato? Lasciatemi andare!"
  },
  AvgDialog_18878_Content_21 = {
    Text = "Fai un cenno a Ramona. Lei si avvicina e taglia i legacci di Jenkin con un colpo rapido della sua spada."
  },
  AvgDialog_18878_Content_22 = {
    Text = "Scusa, qualcosa è andato storto e abbiamo dovuto prendere alcune misure protettive.\nTu... ricordi cosa hai appena fatto?"
  },
  AvgDialog_18878_Content_23 = {
    Text = "Cosa avrei fatto? Dovevamo introdurci nel seminterrato di quella donna, no? Brown e io ci siamo nascosti nella stanza di Aigis ad aspettare... devo essermi addormentata e aver fatto un sogno strano..."
  },
  AvgDialog_18878_Content_24 = {
    Text = "Aspetta, questa non è la stanza di Aigis. Come ci sono finita qui? Qual è il vostro piano? Volete farmi sparire, adesso?"
  },
  AvgDialog_18878_Content_25 = {
    Text = "Sei venuto come promesso, ma qualcosa in te era terribilmente sbagliato, come se..."
  },
  AvgDialog_18878_Content_26 = {
    Text = "Come se fossi posseduto da qualcosa. In altre parole, potresti essere stato ipnotizzato."
  },
  AvgDialog_18878_Content_27 = {
    Text = "Ipnosi... Ah! Potrebbe essere lo psicologo che ha preso <Aigis>?"
  },
  AvgDialog_18878_Content_28 = {
    Text = "Che maleducazione. La psicoterapia è una scienza, non un superpotere per controllare le menti... Ah, scienza, simile a ciò che perseguono quei <Blue:Pigmalioni>."
  },
  AvgDialog_18878_Content_3 = {
    Text = "No. %player%, il suo spirito è inquieto.\nIl potere mentale della Chiave d'argento potrebbe avere un effetto calmante."
  },
  AvgDialog_18878_Content_30 = {
    Text = "La spada di Ramona guizza fuori. La lama d'argento si libra al collo di Clementine, ma lei non mostra alcun terrore, deviando lo stocco con due dita."
  },
  AvgDialog_18878_Content_31 = {
    Text = "Osservi con diffidenza: porte e finestre chiuse, eppure è apparsa come un fantasma."
  },
  AvgDialog_18878_Content_32 = {
    Text = "Sei dell'Associazione degli Scultori?"
  },
  AvgDialog_18878_Content_33 = {
    Text = [[
Sono solo una terza parte disponibile, anche se nutro un certo interesse personale.
Mi incuriosisci, Investigatore speciale.]]
  },
  AvgDialog_18878_Content_34 = {
    Text = "Sorride, lo sguardo carico di uno strano fervore."
  },
  AvgDialog_18878_Content_35 = {
    Text = "...Perché?"
  },
  AvgDialog_18878_Content_36 = {
    Text = "Clementine arretra con un sorriso misterioso, accennando un lieve inchino."
  },
  AvgDialog_18878_Content_37 = {
    Text = "Ho detto abbastanza stanotte, abbastanza da far tremare il mio <Yellow:cuore d'argento> di eccitazione."
  },
  AvgDialog_18878_Content_38 = {
    Text = "Un <Yellow:Cuore d'argento>... Sei un Risvegliatore?!"
  },
  AvgDialog_18878_Content_39 = {
    Text = "In tal caso, Clementine, tu NON te ne vai."
  },
  AvgDialog_18878_Content_4 = {
    Text = "Attiva la tua Chiave d'Argento"
  },
  AvgDialog_18878_Content_40 = {
    Text = "Non sarebbe noioso se la nostra storia finisse oggi?"
  },
  AvgDialog_18878_Content_41 = {
    Text = "Dal nulla estrae uno strano pendente. Una fatica opprimente ti colpisce, costringendoti ad appoggiarti al tavolo per restare in piedi."
  },
  AvgDialog_18878_Content_42 = {
    Text = [[
Il fioretto di Ramona si abbassa, la testa ciondola, gli occhi a malapena aperti.
Jenkin giace immobile, apparentemente addormentato.]]
  },
  AvgDialog_18878_Content_43 = {
    Text = "Cosa... hai fatto..."
  },
  AvgDialog_18878_Content_44 = {
    Text = [[
Solo un piccolo trucco per svignarsela.
Sei in gamba, e credo che starai bene abbastanza presto.]]
  },
  AvgDialog_18878_Content_45 = {
    Text = "Addio, Pallido Occhio Senza Pupilla. Le nostre strade... si incroceranno di nuovo."
  },
  AvgDialog_18878_Content_46 = {
    Text = [[
Si inchina ed esce.
Tu crolli sulla sedia, incapace di resistere oltre.]]
  },
  AvgDialog_18878_Content_47 = {
    Text = "Clementine chiude la porta, canticchiando allegramente. Saluta con la mano lungo il corridoio, poi se ne va."
  },
  AvgDialog_18878_Content_48 = {
    Text = "Nell'oscurità, la fanciulla in vestito resta immobile come una statua.\nA capo chino, stringe con forza una benda bianca."
  },
  AvgDialog_18878_Content_5 = {
    Text = "Ti trovi in un'oscurità assoluta, dove punti luminosi d'argento formano connessioni ondulanti, muovendosi in modo imperscrutabile."
  },
  AvgDialog_18878_Content_6 = {
    Text = [[
Fai parte di tutto questo eppure ne sei separato. Appartieni ma ti senti fuori posto.
Non sai cosa siano; sai solo che sei qui per trovare qualcuno.]]
  },
  AvgDialog_18878_Content_7 = {
    Text = "\"Sorella... Sorella...\""
  },
  AvgDialog_18878_Content_8 = {
    Text = "Guardi verso il suono—una luce fioca tremola tra le stelle,\nintrappolata e immobilizzata da fili neri dal sinistro luccichio metallico."
  },
  AvgDialog_18878_Content_9 = {
    Text = "Una melodia allegra emerge dai fili neri, simile a una filastrocca per fanciulli."
  },
  AvgDialog_18879_Content_1 = {
    Text = "Uscite dal vicolo, raggiungendo la porta di ferro dell'Ospizio dei Poveri."
  },
  AvgDialog_18879_Content_2 = {
    Text = "Un uomo dal volto unto se ne sta sdraiato su una panca, un bastone nero alla cintola, una pipa scura tra le labbra."
  },
  AvgDialog_18879_Content_3 = {
    Text = "Notate un piccolo segno nero sul braccio dell'uomo. Una ferita triangolare che ricorda un minuscolo abisso, da cui trasuda un fluido scuro e viscoso."
  },
  AvgDialog_18879_Content_4 = {
    Text = "Ramona si schiarisce la gola, facendosi avanti proprio come un maggiordomo altezzoso."
  },
  AvgDialog_18879_Content_5 = {
    Text = "Buongiorno, signore. Vi prego, informate la casa che è arrivato un ospite."
  },
  AvgDialog_18879_Content_6 = {
    Text = "Prima che possa finire, il corpo della guardia si contorce. Una melma nera erutta dal suo petto, formando una massa mostruosa che si avventa su di voi."
  },
  AvgDialog_18880_Content_1 = {
    Text = "Sorella? Cosa sono quelli? Sorella?"
  },
  AvgDialog_18880_Content_10 = {
    Text = "Eppure non puoi fare altro che guardarla cadere, atterrare sul lurido pavimento della fogna, la dura <Red:Statua> che si frantuma in pezzi."
  },
  AvgDialog_18880_Content_11 = {
    Text = "...Statua? Perché una statua?"
  },
  AvgDialog_18880_Content_12 = {
    Text = "Non c'è tempo per pensare. Alzi lo sguardo verso il punto da cui è caduta."
  },
  AvgDialog_18880_Content_13 = {
    Text = "No... non può essere..."
  },
  AvgDialog_18880_Content_14 = {
    Text = "La bambina che conosci è lì in piedi, la benda caduta, gli occhi vacui, stringe un nastro rosso sangue, strappato a metà."
  },
  AvgDialog_18880_Content_2 = {
    Text = "Non chiedere, corri e basta, Jenkin."
  },
  AvgDialog_18880_Content_3 = {
    Text = "I Mostri si avvicinano, sospingendoti verso l'Abisso."
  },
  AvgDialog_18880_Content_4 = {
    Text = "È solo una ragazzina dei bassifondi, non sa nulla. Non rappresenterà mai una minaccia per voi..."
  },
  AvgDialog_18880_Content_5 = {
    Text = "Seguendo le istruzioni di tua sorella, scendi lungo il tubo della fogna portando Brown con te."
  },
  AvgDialog_18880_Content_6 = {
    Text = "<Shake:Per favore, ti supplico...>"
  },
  AvgDialog_18880_Content_7 = {
    Text = "Quelle furono le sue ultime volontà."
  },
  AvgDialog_18880_Content_8 = {
    Text = "Mentre la Voce si spezza, una sagoma familiare precipita dall'alto, stringendo ancora metà di un Nastro Rosso."
  },
  AvgDialog_18880_Content_9 = {
    Text = "Il nastro era stato fatto su misura per tua sorella. Ti era costato un anno di risparmi.\nNon hai mai conosciuto i tuoi genitori; lei era la persona più cara che avessi."
  },
  AvgDialog_18881_Content_1 = {
    Text = "Un'Ombra nera guizza dall'angolo, sfiorando Aigis e schiantandosi contro la parete sinistra."
  },
  AvgDialog_18881_Content_10 = {
    Text = "Si libera all'improvviso e si avventa su di te."
  },
  AvgDialog_18881_Content_2 = {
    Text = "Concentri lo sguardo su di lui:\nun uomo trasandato, scalzo, in abiti della carità, con polsi e caviglie segnati da legature."
  },
  AvgDialog_18881_Content_3 = {
    Text = [[
Alcuni inservienti lo inseguono, cercando di trascinarlo via.
L'uomo resta impassibile. Si piega all'indietro e sbatte la testa contro il muro freddo e duro.]]
  },
  AvgDialog_18881_Content_4 = {
    Text = "Dietro di te, Aigis trattiene il respiro."
  },
  AvgDialog_18881_Content_5 = {Text = "—!"},
  AvgDialog_18881_Content_6 = {
    Text = "Il suono sordo di Osso che colpisce il mattone aumenta di frequenza mentre l'uomo continua a cozzare senza mostrare Pain."
  },
  AvgDialog_18881_Content_7 = {
    Text = [[
Il Sangue schizza, lasciando macchie scure sulle pareti e sul pavimento.
Fai un passo avanti per aiutare, ma l'uomo smette improvvisamente di muoversi.]]
  },
  AvgDialog_18881_Content_8 = {
    Text = "Inspira profondamente, come un cane, poi lentamente e rigidamente si volta verso di te."
  },
  AvgDialog_18881_Content_9 = {
    Text = "Il Sangue gli cola dalla fronte. La Ferita tumefatta ha lacerato la pelle, rivelando un barlume di Osso bianco."
  },
  AvgDialog_18882_Content_1 = {
    Text = "Non vi siete allontanati molto quando i fanciulli, che poco prima si stavano solo prendendo gioco di voi, si sono radunati in fretta davanti a voi, bloccandovi il cammino."
  },
  AvgDialog_18882_Content_2 = {
    Text = "Gentile {Male=signore,Female=signora}, un po' di spiccioli. Mane, Pensh, qualsiasi cosa..."
  },
  AvgDialog_18882_Content_3 = {
    Text = "Potremmo pensarci DOPO che avrai tolto la mano dalla tasca di %player%."
  },
  AvgDialog_18882_Content_4 = {Text = "Hmph!"},
  AvgDialog_18882_Content_5 = {
    Text = "Il bambino scappa via."
  },
  AvgDialog_18882_Content_6 = {
    Text = "Dobbiamo impartire a questi sfortunati marmocchi una piccola lezione, non credi?"
  },
  AvgDialog_18882_Content_7 = {
    Text = "Facciamo un tentativo."
  },
  AvgDialog_18882_Content_8 = {
    Text = "Sembrano essere in combutta con quello dal cappuccio marrone."
  },
  AvgDialog_18882_Content_9 = {
    Text = "D'accordo, andiamo. Difendere la giustizia è un dovere civico."
  },
  AvgDialog_18883_Content_1 = {
    Text = "Ogier corre ansiosamente lungo muri di mattoni anneriti dalla fuliggine, incrostati dalla sporcizia di Londinium."
  },
  AvgDialog_18883_Content_10 = {
    Text = "Sto bene, e questo giovane signore non aveva cattive intenzioni, vero?"
  },
  AvgDialog_18883_Content_11 = {
    Text = "Mi dispiace infinitamente. Non ho prestato attenzione a ciò che mi circondava."
  },
  AvgDialog_18883_Content_12 = {
    Text = [[
Clementine offre un sorriso gentile, spolverando polvere immaginaria dai suoi vestiti.
Annuisce e si allontana con grazia.]]
  },
  AvgDialog_18883_Content_13 = {
    Text = [[
In alto, un'insegna di ferro arrugginita recita "Workhouse di Lilian".
Una guardia annoiata ciondola sotto di essa.]]
  },
  AvgDialog_18883_Content_14 = {
    Text = [[
Eccoci. Entriamo a dare un'occhiata.
Ti ricordi il tuo travestimento, {Male=Lord Ashe and his younger brother,Female=Lady Ashe and her younger brother}?]]
  },
  AvgDialog_18883_Content_15 = {
    Text = "Ma certo, cara Mary, la mia governante."
  },
  AvgDialog_18883_Content_16 = {
    Text = "Al vostro servizio, signorina Mary."
  },
  AvgDialog_18883_Content_17 = {
    Text = "...Ugh. Dovrà bastare."
  },
  AvgDialog_18883_Content_2 = {
    Text = "Prima indagine al servizio del mio signore. Non posso permettermi alcun..."
  },
  AvgDialog_18883_Content_3 = {Text = "Ugh!"},
  AvgDialog_18883_Content_4 = {
    Text = "Una porta di ferro si apre, e una donna in bianco appare all'improvviso, scontrandosi frontalmente con Ogier."
  },
  AvgDialog_18883_Content_5 = {
    Text = "<Small:Ah...>"
  },
  AvgDialog_18883_Content_6 = {
    Text = "S-scusa! Stai bene?"
  },
  AvgDialog_18883_Content_7 = {
    Text = "Tu e Ramona raggiungete finalmente Ogier."
  },
  AvgDialog_18883_Content_8 = {
    Text = "Mi scusi, noi... Oh, ma lei non è la psicologa che distribuiva questionari poco fa?"
  },
  AvgDialog_18883_Content_9 = {
    Text = "Vi ricordate di me? Che onore."
  },
  AvgDialog_18884_Content_1 = {
    Text = "Così tanti Mostri in questo angusto spazio sotterraneo..."
  },
  AvgDialog_18884_Content_2 = {
    Text = "Questo Ospizio dei Poveri è davvero qualcosa."
  },
  AvgDialog_18884_Content_3 = {
    Text = "Shh, per favore resta calmo. È quasi finita."
  },
  AvgDialog_18885_Content_1 = {
    Text = "La creatura nera ruggisce, poi collassa in un ammasso di fanghiglia."
  },
  AvgDialog_18885_Content_10 = {
    Text = "Appoggiate le spoglie della guardia contro il cancello ed entrate."
  },
  AvgDialog_18885_Content_11 = {
    Text = "Dietro l'angolo, una figura bianca guizza via."
  },
  AvgDialog_18885_Content_12 = {
    Text = "Sono... Dobbiamo rientrare prima che incontrino Miss Sarah. Sgattaioliamo dalla finestra della cucina."
  },
  AvgDialog_18885_Content_13 = {
    Text = "Quelle persone possono aiutare; non opporti al loro avvento."
  },
  AvgDialog_18885_Content_14 = {Text = "No!"},
  AvgDialog_18885_Content_15 = {
    Text = "Quelle persone non si lasceranno intimidire da ciò che accade qui. Te lo prometto."
  },
  AvgDialog_18885_Content_16 = {
    Text = "No... non possiamo coinvolgere altre persone... È pericoloso per chiunque si avvicini. Lo SAI bene..."
  },
  AvgDialog_18885_Content_17 = {
    Text = "<Red:Signor Anderson>."
  },
  AvgDialog_18885_Content_2 = {
    Text = "Lui... Che... che è successo?"
  },
  AvgDialog_18885_Content_3 = {
    Text = "<Yellow:Erosione da Dissoluzione precoce>.\nNon dovrebbe manifestarsi così presto... non dovrebbe manifestarsi affatto."
  },
  AvgDialog_18885_Content_4 = {
    Text = "Due voci risuonano attraverso la spilla, echeggiando nelle vostre menti."
  },
  AvgDialog_18885_Content_5 = {
    Text = "Sembra catalisi artificiale in azione."
  },
  AvgDialog_18885_Content_6 = {
    Text = [[
I pattern anomali di Dissoluzione... potrebbero essere correlati alla <Yellow:scomparsa dell'Investigatore Anderson>.
La workhouse potrebbe essere un obiettivo... e forse anche tu.]]
  },
  AvgDialog_18885_Content_7 = {
    Text = "Terremo d'occhio la situazione."
  },
  AvgDialog_18885_Content_8 = {
    Text = "Resta vigile, Custode."
  },
  AvgDialog_18885_Content_9 = {Text = "Lo farò."},
  AvgDialog_18886_Content_1 = {
    Text = "Sembra che questa sia un po' diversa."
  },
  AvgDialog_18886_Content_2 = {
    Text = "È ora di fare sul serio."
  },
  AvgDialog_18887_Content_1 = {
    Text = "Nel frattempo—\nOgier osserva il cortile della workhouse dalla finestra."
  },
  AvgDialog_18887_Content_10 = {
    Text = "No, non potete portarla via!"
  },
  AvgDialog_18887_Content_11 = {
    Text = [[
Devi averci frainteso, piccola.
Siamo dottori assunti dalla workhouse, e lei viene per un controllo di routine.]]
  },
  AvgDialog_18887_Content_12 = {
    Text = "Il volto di Ogier avvampa di rosso, eppure un'improvvisa ispirazione lo colpisce."
  },
  AvgDialog_18887_Content_13 = {
    Text = "Non se ne parla! {Male=Mio fratello,Female=Mia sorella} ha detto che presto chiederemo informazioni sulla situazione ad Aigis per conto di Lord Ashe. Non potete portarla via adesso."
  },
  AvgDialog_18887_Content_14 = {
    Text = "I bambini dovrebbero imparare a obbedire agli adulti."
  },
  AvgDialog_18887_Content_2 = {
    Text = [[
La porta di ferro si apre cigolando. Figure in bianco entrano in fila.
I bambini si mettono in riga nella nebbia grigia, in attesa della selezione.]]
  },
  AvgDialog_18887_Content_3 = {
    Text = [[
Tra loro, Ogier riconosce una figura familiare:
la piccola ragazza bianca che vi aveva accolti tutti.]]
  },
  AvgDialog_18887_Content_4 = {
    Text = "Spalle curve, capo chino, stringe l'orlo del vestito tra le mani. Sebbene spaventata, avanza davanti agli altri."
  },
  AvgDialog_18887_Content_5 = {
    Text = "Cerca di farsi più piccola, di scomparire dentro il proprio corpo. Un'ombra alta incombe; lei rabbrividisce, non osa muoversi."
  },
  AvgDialog_18887_Content_6 = {
    Text = [[
Scoppia un conflitto.
Lo sconosciuto in bianco le afferra il braccio, costringendola a obbedire.]]
  },
  AvgDialog_18887_Content_7 = {Text = "—Fermo!"},
  AvgDialog_18887_Content_8 = {
    Text = "Cedendo all'impulso, Ogier si lancia tra lo sconosciuto e la bambina."
  },
  AvgDialog_18887_Content_9 = {
    Text = "G-Giovane Padrone Ashe?"
  },
  AvgDialog_18888_Content_1 = {
    Text = "Nonno Robert... perché..."
  },
  AvgDialog_18888_Content_2 = {
    Text = "Attento, ha perso il senno!"
  },
  AvgDialog_18889_Content_1 = {
    Text = "Per favore, non fate del male alla signorina Sarah. Vi dirò tutto..."
  },
  AvgDialog_18889_Content_2 = {
    Text = "Ai... gis..."
  },
  AvgDialog_18889_Content_3 = {
    Text = "Non è completamente perduta!"
  },
  AvgDialog_18889_Content_4 = {
    Text = "Eliminate questi Mostri, poi sottomettete Sarah! Dobbiamo sapere da lei dove si trova Sean!"
  },
  AvgDialog_18889_Content_5 = {Text = "Capito!"},
  AvgDialog_18890_Content_1 = {
    Text = "Ramona si muove rapidamente dietro di lui, afferrandogli il polso con una mano e premendogli la spalla con l'altra. Gli torce il braccio dietro la schiena, immobilizzandolo con fermezza."
  },
  AvgDialog_18890_Content_10 = {
    Text = "N-non sono un estraneo qui, signorina Sarah. Non c'è bisogno.\nA proposito, perché la piccola Aigis piange così disperatamente? Qualcuno le ha fatto del male?"
  },
  AvgDialog_18890_Content_11 = {
    Text = "<Small:Sto bene, signor Rogers.>"
  },
  AvgDialog_18890_Content_12 = {
    Text = [[
La pressione dello sguardo della direttrice costringe Aigis a ingoiare le parole.
Fa un inchino a tutti, ti guarda, poi scompare dietro la porta.]]
  },
  AvgDialog_18890_Content_13 = {
    Text = "Mi dispiace per averti nascosto il reparto. Non posso rischiare alcuna possibile infezione..."
  },
  AvgDialog_18890_Content_14 = {
    Text = "Ahimè, non soffermiamoci su questo. Permettetemi di presentarvi il nostro patrono di lunga data — lo Scultore di cera di Fama Rinomata, il signor Rogers."
  },
  AvgDialog_18890_Content_15 = {
    Text = "Questo reparto e le cure dei Pazienti sono stati resi possibili grazie a lui."
  },
  AvgDialog_18890_Content_16 = {
    Text = "George Rogers, piacere di conoscervi."
  },
  AvgDialog_18890_Content_17 = {
    Text = [[
Libera una mano per stringere gentilmente la tua.
Nell'istante in cui i palmi si toccano, un'intensa vertigine ti travolge.]]
  },
  AvgDialog_18890_Content_18 = {
    Text = "Tutto intorno a te sembra dissolversi come cera che si scioglie; persino la persona di fronte a te si torce e si deforma. Sotto il volto, pallidi Scheletri si intrecciano come rampicanti."
  },
  AvgDialog_18890_Content_19 = {
    Text = "L'inquietante Illusione svanisce in pochi Bagliori, lasciando solo un ronzio acuto nelle orecchie — era dovuta alla Fatica? Non lo sai."
  },
  AvgDialog_18890_Content_2 = {
    Text = [[
Ogier si fa avanti rapidamente e, con l'aiuto di Ramona, gli lega mani e piedi con strisce di stoffa.
L'uomo continua a dimenarsi, rivelando una cicatrice peculiare attraverso il colletto aperto.]]
  },
  AvgDialog_18890_Content_20 = {
    Text = "Sai solo che somiglia a ciò che hai sperimentato al cimitero l'altro giorno."
  },
  AvgDialog_18890_Content_21 = {
    Text = "...Ogni mese, viene personalmente a controllare i Pazienti. È davvero un grande benefattore e un sostenitore Maggiore del nostro Ospizio dei Poveri."
  },
  AvgDialog_18890_Content_22 = {
    Text = "S-signorina Sarah, mi lusingate troppo. Sono solo una persona comune che cerca di fare qualcosa per il mondo."
  },
  AvgDialog_18890_Content_23 = {
    Text = "A proposito, avevate menzionato che sareste venuto con un <Yellow:amico>..."
  },
  AvgDialog_18890_Content_24 = {
    Text = "Quello s-<Yellow:scultore> ha trovato l'ispirazione ed è t-tornato in studio."
  },
  AvgDialog_18890_Content_25 = {
    Text = "E questi giovani signore e signori...?"
  },
  AvgDialog_18890_Content_26 = {
    Text = "...{Male=Signor,Female=Signorina} Ashe?"
  },
  AvgDialog_18890_Content_27 = {
    Text = "Ehm, mi scusi, ero distratto. Piacere di conoscerla, signor Rogers.\nSono Ashe. Questo è mio fratello minore Ogier e la nostra governante Mary. Questo è Jenkin..."
  },
  AvgDialog_18890_Content_28 = {Text = "Eh?"},
  AvgDialog_18890_Content_29 = {
    Text = "Dov'è Jenkin?"
  },
  AvgDialog_18890_Content_3 = {
    Text = "Una cicatrice profonda gli attraversa il petto, a malapena tenuta insieme da punti di sutura contorti. Un liquame nero continua a trasudare lentamente dalle fessure."
  },
  AvgDialog_18890_Content_4 = {
    Text = "Passi affrettati risuonano fuori dal reparto. Sarah appare, senza fiato, aggrappata allo stipite della Porta."
  },
  AvgDialog_18890_Content_5 = {
    Text = "Vedendo che all'interno tutto si è calmato, si rilassa per un istante, poi immediatamente aggrotta le sopracciglia e si volta verso la Bambina rannicchiata nell'angolo."
  },
  AvgDialog_18890_Content_6 = {
    Text = [[
Aigis! Non avevo detto che i finanziatori non possono entrare nel reparto?
Chi ci finanzierebbe se succedesse qualcosa a...]]
  },
  AvgDialog_18890_Content_7 = {
    Text = "C-Cosa sta succedendo?"
  },
  AvgDialog_18890_Content_8 = {
    Text = "Ti volti verso il suono e trovi due persone dietro di te.\nUna la riconosci: la donna in bianco che Ogier aveva già incontrato."
  },
  AvgDialog_18890_Content_9 = {
    Text = "Signor Rogers, Dottor Fairfax!\nMi perdoni, prego, si accomodi nel salotto per un rinfresco mentre attende. Verrò a ricevervi non appena avrò finito qui."
  },
  AvgDialog_18891_Content_1 = {
    Text = "Piccolo Detective"
  },
  AvgDialog_18891_Content_10 = {
    Text = "Seguendo le indicazioni del biglietto, arrivi nel cortile sul retro. Prima ancora di avvicinarti, senti una voce infantile mormorare vicino alla base del muro."
  },
  AvgDialog_18891_Content_11 = {
    Text = "Ricorda—se lo sponsor non è affidabile, scappa e porta Aigis.\nSicuramente è stata mandata ai <Yellow:Pazzi Malati> da quella megera."
  },
  AvgDialog_18891_Content_12 = {
    Text = "Quali pazzi?"
  },
  AvgDialog_18891_Content_13 = {
    Text = "Oh! Perché sei qui così presto? E ti avevo detto di venire da solo!"
  },
  AvgDialog_18891_Content_14 = {
    Text = "Il topo sgattaiola sulla spalla del ragazzino incappucciato, agitando nervosamente i baffi verso di te."
  },
  AvgDialog_18891_Content_15 = {
    Text = "Quello non è il mio Portafoglio. Non posso farcela da solo."
  },
  AvgDialog_18891_Content_16 = {
    Text = "Smettetela di recitare. Ho visto tutto — il capelli bianchi finge di essere un maggiordomo, la bionda va in giro a chiedere indicazioni, e tu? Te ne stai lì con le mani in tasca."
  },
  AvgDialog_18891_Content_17 = {
    Text = "Credi che non lo capisca? Sei tu il capo. Dopotutto, non c'è nessun \"certificato da giovane padrone\" in quella borsa."
  },
  AvgDialog_18891_Content_18 = {
    Text = "La mano di Jenkin guizza, tirando fuori un portafoglio dal nulla. Ha una consistenza e una forma familiari, con impresso l'emblema dell'Università di Mythag — il portafoglio di Ogier."
  },
  AvgDialog_18891_Content_19 = {
    Text = "Giusto, Brown?"
  },
  AvgDialog_18891_Content_2 = {
    Text = "Come potete vedere, nonostante i nostri sforzi per dare rifugio ai bisognosi, sono semplicemente troppi! Di questo passo, l'Ospizio dei Poveri non reggerà ancora a lungo... Io... sigh!"
  },
  AvgDialog_18891_Content_20 = {
    Text = "Squeak, squeak!"
  },
  AvgDialog_18891_Content_21 = {
    Text = "Ehi! Il mio Portafoglio!"
  },
  AvgDialog_18891_Content_22 = {
    Text = "Ogier allunga la mano in fretta per afferrarlo, ma Jenkin scarta di lato, e il portafoglio svanisce come per magia ancora una volta."
  },
  AvgDialog_18891_Content_23 = {
    Text = "Che maleducazione, biondino.\nÈ così che i ragazzi dei Mythag trattano le ragazze di strada?"
  },
  AvgDialog_18891_Content_24 = {
    Text = "Bambina... tu?"
  },
  AvgDialog_18891_Content_25 = {
    Text = "Sei cieco? Certo che sono una bambina! Una BAMBINA!"
  },
  AvgDialog_18891_Content_26 = {
    Text = "Comunque, basta chiacchiere. Faresti meglio ad ascoltare e—"
  },
  AvgDialog_18891_Content_27 = {
    Text = "Molto bene, accettiamo le tue condizioni. Ma in cambio, ci porterai a vedere quei <Yellow:Folli Malati> di cui hai parlato."
  },
  AvgDialog_18891_Content_28 = {Text = "...Eh?"},
  AvgDialog_18891_Content_29 = {
    Text = "Non ci stai forse chiedendo di trovare qualcuno nell'Ospizio dei Poveri? Allora, chi sarebbe?"
  },
  AvgDialog_18891_Content_3 = {
    Text = "La... la signorina Sarah lavora così duramente ogni giorno. Ha persino venduto le sue cose più care per sostenere l'Ospizio dei Poveri. Vi prego, vi prego, aiutateci..."
  },
  AvgDialog_18891_Content_30 = {
    Text = "Non ho detto niente!"
  },
  AvgDialog_18891_Content_31 = {
    Text = "Ma lo farai. Quindi ti suggerisco di essere onesti e saltare le finzioni."
  },
  AvgDialog_18891_Content_32 = {
    Text = [[
State indagando sulle <Yellow:sparizioni dalla workhouse>, vero?
I nostri obiettivi coincidono. Una cooperazione reciproca sarebbe vantaggiosa.]]
  },
  AvgDialog_18891_Content_33 = {
    Text = "Come... come facevi a saperlo?"
  },
  AvgDialog_18891_Content_34 = {
    Text = "Semplice. Hai mani svelte e compagni leali, il che ti garantisce un'entrata stabile ma illegale."
  },
  AvgDialog_18891_Content_35 = {
    Text = "Ramona parla mentre passeggia per abitudine nel cortile."
  },
  AvgDialog_18891_Content_36 = {
    Text = "Procedura operativa standard: tu esegui le azioni principali mentre i complici forniscono diversione e copertura per la fuga. La spartizione dei profitti sostiene l'accordo."
  },
  AvgDialog_18891_Content_37 = {
    Text = "La vita di strada indipendente offre un'autonomia superiore rispetto alla dipendenza istituzionale. L'ingresso non autorizzato nell'Ospizio dei Poveri comporta pene severe."
  },
  AvgDialog_18891_Content_38 = {
    Text = "Ma perché? Cosa ti spinge a restare nell'Ospizio dei Poveri, anche a rischio di multe o reclusione?"
  },
  AvgDialog_18891_Content_39 = {
    Text = "Questo schema, combinato con le recenti sparizioni, suggerisce una conclusione:\nQualcuno a cui tieni è scomparso, e sospetti il coinvolgimento della workhouse."
  },
  AvgDialog_18891_Content_4 = {
    Text = "La vista della loro recita esagerata — specialmente i teatrini melodrammatici di Sarah — ti strappa un sospiro silenzioso di frustrazione."
  },
  AvgDialog_18891_Content_40 = {
    Text = "La Bambina fissa Ramona con sguardo vacuo per un lungo istante prima di reagire."
  },
  AvgDialog_18891_Content_41 = {
    Text = "Abbiamo a malapena parlato e mi segui come se fossimo vecchi amici..."
  },
  AvgDialog_18891_Content_42 = {
    Text = [[
Incluso l'incidente del portafoglio, abbiamo documentato sedici interazioni.
Combinate con le osservazioni sul campo, forniscono dati sufficienti per un profilo completo.]]
  },
  AvgDialog_18891_Content_43 = {
    Text = "...Va bene, d'accordo, sei davvero un tipo. D'accordo, Brown."
  },
  AvgDialog_18891_Content_44 = {Text = "Squeak!"},
  AvgDialog_18891_Content_45 = {
    Text = "Il topo che ha chiamato Brown emette uno Squeak e con un Salto scende dall'albero, lanciando il Portafoglio tra le braccia di Ogier."
  },
  AvgDialog_18891_Content_46 = {
    Text = "Ti mostrerò i folli malati e ti dirò quello che so. Ma tu—"
  },
  AvgDialog_18891_Content_47 = {
    Text = "mi aiuterai ad abbattere quel Fantasma dell'Ospizio e a salvare mia sorella, <Blue:Mason>."
  },
  AvgDialog_18891_Content_48 = {
    Text = "Segui Jenkin attraverso i corridoi dell'Ospizio dei Poveri."
  },
  AvgDialog_18891_Content_49 = {
    Text = "Mia sorella veniva ogni giovedì a ritirare il bucato da questo posto. Probabilmente ha contratto quella malattia dell'\"<Yellow:Isteria>\" dai loro vestiti sporchi."
  },
  AvgDialog_18891_Content_5 = {
    Text = "In quel momento una pallina di carta ti colpisce la testa."
  },
  AvgDialog_18891_Content_50 = {
    Text = "È venuto un dottore di beneficenza.\nPrima che me ne rendessi conto, ha detto che stava ricevendo cure e poi è sparita."
  },
  AvgDialog_18891_Content_51 = {
    Text = "Jenkin sembra ansioso."
  },
  AvgDialog_18891_Content_52 = {
    Text = "Non capisco, ma ultimamente... Il suo volto ha cominciato a sfumare nella mia mente."
  },
  AvgDialog_18891_Content_53 = {
    Text = "A volte le sue cose mi aiutano a ricordare, ma svanisce in fretta."
  },
  AvgDialog_18891_Content_54 = {
    Text = "Ramona si ferma all'improvviso e ti fa un cenno col capo."
  },
  AvgDialog_18891_Content_55 = {
    Text = "Perché ti sei fermata? Non dovevi andare a vedere quei folli malati?"
  },
  AvgDialog_18891_Content_56 = {
    Text = "Riguardo alla malattia di tua sorella... potremmo avere qualche pista."
  },
  AvgDialog_18891_Content_57 = {Text = "..."},
  AvgDialog_18891_Content_58 = {
    Text = "Dopo aver inoltrato una richiesta di divulgazione informazioni via comunicatore, Ramona si rivolge a Jenkin e inizia a spiegare la Dissoluzione."
  },
  AvgDialog_18891_Content_59 = {
    Text = "Jenkin, tua sorella manifesta un fenomeno di Dissoluzione unico che causa una progressiva cancellazione dalla Memoria collettiva."
  },
  AvgDialog_18891_Content_6 = {
    Text = "E chi diavo—"
  },
  AvgDialog_18891_Content_60 = {
    Text = "Il Corpo, l'identità, il passato e i legami sociali... scompariranno tutti completamente senza lasciare traccia."
  },
  AvgDialog_18891_Content_61 = {
    Text = "Le condizioni di quei folli malati assomigliano a <Yellow:sintomi precoci di Dissoluzione>. Tua sorella ha raggiunto uno stadio avanzato; temo che lei..."
  },
  AvgDialog_18891_Content_62 = {
    Text = "Jenkin, da quanto tempo Mason... è scomparso?"
  },
  AvgDialog_18891_Content_63 = {
    Text = "27 giorni. Li ho contati uno per uno."
  },
  AvgDialog_18891_Content_64 = {
    Text = "Vedendo l'Espressione turbata di Ramona, Jenkin tira su col naso."
  },
  AvgDialog_18891_Content_65 = {
    Text = "So che è passato abbastanza tempo da perdere la speranza.\nMa noi ragazzi di strada abbiamo l'istinto. SO che è ancora viva là fuori."
  },
  AvgDialog_18891_Content_66 = {
    Text = "Quindi... devo sbrigarmi. Prima che dimentichi completamente il suo volto e le passi accanto senza riconoscerla."
  },
  AvgDialog_18891_Content_67 = {
    Text = "Non essere triste, ti aiuteremo a trovare tua sorella. E la riconoscerai non appena la vedrai."
  },
  AvgDialog_18891_Content_68 = {
    Text = [[
Ramona resta in silenzio.
Sotto il suo sguardo malinconico, ricordi il contenuto che Doll ha narrato in classe:]]
  },
  AvgDialog_18891_Content_69 = {
    Text = "<Yellow:\"L'eliminazione dell'esistenza è il Sintomo finale della Dissoluzione, e il processo è irreversibile.\">"
  },
  AvgDialog_18891_Content_7 = {
    Text = "Fai un gesto per placare la rabbia di Sarah e spieghi il foglio accartocciato. Vi si legge:"
  },
  AvgDialog_18891_Content_8 = {
    Text = "\"Vieni nel cortile sul retro da solo se rivuoi il tuo <Del:portafoglo>portafoglio.\""
  },
  AvgDialog_18891_Content_9 = {Text = "..."},
  AvgDialog_18892_Content_1 = {
    Text = "Uno squittio acuto di topo ti scuote dal sonno. Ramona è la prima ad alzarsi, accendendo la luce."
  },
  AvgDialog_18892_Content_10 = {
    Text = "Il filo tagliente riflette una luce fredda, il coltello corto rivela il tuo volto."
  },
  AvgDialog_18892_Content_11 = {
    Text = "Chi è là!"
  },
  AvgDialog_18892_Content_12 = {
    Text = "I riflessi addestrati ti permettono di scartare quel tanto che basta per vedere l'aggressore."
  },
  AvgDialog_18892_Content_13 = {Text = "Jenkin?!"},
  AvgDialog_18892_Content_14 = {
    Text = "Gli occhi vuoti della ragazza sono privi di colore; il volto inespressivo, insensibile ai tuoi richiami."
  },
  AvgDialog_18892_Content_15 = {
    Text = "Sorella... gliela farò pagare..."
  },
  AvgDialog_18892_Content_16 = {
    Text = [[
I suoi movimenti sono spaventosamente agili, la lama traccia archi gelidi.
Prima che tu possa pensare, si lancia di nuovo all'attacco.]]
  },
  AvgDialog_18892_Content_17 = {
    Text = [[
Dovremo sottometterla prima di interrogarla.
Ramona, Ogier, attiratela in uno spazio aperto!]]
  },
  AvgDialog_18892_Content_18 = {Text = "Aye!"},
  AvgDialog_18892_Content_19 = {
    Text = "Ai vostri ordini!"
  },
  AvgDialog_18892_Content_2 = {
    Text = "Brown? Perché sei qui da solo?"
  },
  AvgDialog_18892_Content_3 = {
    Text = "Squeak—! Squeak squeak!"
  },
  AvgDialog_18892_Content_4 = {
    Text = "Noi non siamo Jenkin. Non capiamo cosa stai dicendo."
  },
  AvgDialog_18892_Content_5 = {
    Text = "È quasi ora. Jenkin dovrebbe unirsi a noi a breve."
  },
  AvgDialog_18892_Content_6 = {
    Text = "Guardi fuori; gli edifici si ergono come statue in un cimitero, avvolti in una tenue foschia bianca."
  },
  AvgDialog_18892_Content_7 = {
    Text = "La porta si apre con uno scricchiolio, quel tanto che basta a lasciar entrare un vento notturno e gelido attraverso lo spiraglio buio."
  },
  AvgDialog_18892_Content_8 = {
    Text = "Un'ombra guizza da dietro i mobili, attaccando all'istante."
  },
  AvgDialog_18893_Content_1 = {
    Text = "《La Primavera di Botticelli》"
  },
  AvgDialog_18893_Content_10 = {
    Text = "Il topo attacca il furetto."
  },
  AvgDialog_18893_Content_11 = {
    Text = "Chi stai chiamando topo?!"
  },
  AvgDialog_18893_Content_12 = {
    Text = "Chi stai chiamando furetto?!"
  },
  AvgDialog_18893_Content_13 = {
    Text = "Hannah? Jenkin? Cosa state..."
  },
  AvgDialog_18893_Content_14 = {
    Text = "Non è colpa mia! Ha cominciato lei! È stata lei a chiamare le guardie per prima!"
  },
  AvgDialog_18893_Content_15 = {
    Text = "Oh, andiamo! Era solo uno scherzo! La vita non è divertente se prendi tutto così sul serio."
  },
  AvgDialog_18893_Content_16 = {
    Text = "Allora, sei venuta a cercarli, vero? Dove vi siete conosciuti, all'Ospizio dei Poveri? Ah! Tu devi essere quella piccola Jenkin di cui hanno tanto parlato!"
  },
  AvgDialog_18893_Content_17 = {
    Text = "Non c'è da stupirsi che tu sia il miglior ficcanaso del Regno di Leonia. Stai raccogliendo materiale per il giornale scolastico di domani?"
  },
  AvgDialog_18893_Content_18 = {
    Text = "È più di questo. Ramona, mi conosci: le informazioni sono la mia vita."
  },
  AvgDialog_18893_Content_19 = {
    Text = "Dunque, quale segreto profondo ha spinto una povera orfana nelle ombre della foresta in pieno giorno?"
  },
  AvgDialog_18893_Content_2 = {
    Text = "13:20, Londinium\nUniversità di Mythag"
  },
  AvgDialog_18893_Content_20 = {
    Text = "L'oggetto della sua ossessione illuminerà la verità, o la trascinerà ancora più nel buio? La reporter in prima linea Hannah Peaslee sta per svelare lo scoop!"
  },
  AvgDialog_18893_Content_21 = {
    Text = "Hannah tira fuori all'improvviso un taccuino — da dove, non lo sai — e ti guarda con aspettativa, la penna pronta a catturare ogni tua parola e azione."
  },
  AvgDialog_18893_Content_22 = {
    Text = "...Ora capisco. Nessuno di voi di questa università del non-so-che parla come una persona normale."
  },
  AvgDialog_18893_Content_23 = {
    Text = "Oh, vi prego, lasciatemi fuori da questa storia."
  },
  AvgDialog_18893_Content_24 = {
    Text = "Per favore, non farci caso. Hannah è semplicemente Hannah. In cosa possiamo aiutarti, Jenkin?"
  },
  AvgDialog_18893_Content_25 = {
    Text = "Jenkin fruga nella borsa, tirando fuori una pila di giornali sgualciti, e li porge a te e Ramona."
  },
  AvgDialog_18893_Content_26 = {
    Text = "Avevamo un accordo: avevi promesso di aiutarmi a trovare mia sorella. Ora è il momento di mantenere la promessa."
  },
  AvgDialog_18893_Content_27 = {
    Text = "Ne distende rapidamente una, indicando una curiosità locale: \"Dipinti Tridimensionali\"."
  },
  AvgDialog_18893_Content_28 = {
    Text = "L'articolo allegato, scritto in uno stile drammatico e documentaristico, descrive in dettaglio una stupefacente nuova esposizione al museo delle cere al 44 di Via Southwark: l'ultima opera di Rogers, \"Primavera.\""
  },
  AvgDialog_18893_Content_29 = {
    Text = "Una foto dall'aspetto serio è allegata per dare credibilità."
  },
  AvgDialog_18893_Content_3 = {
    Text = "Mentre tu e Ramona vi avvicinate all'ingresso principale, un trambusto attira il vostro sguardo. Jenkin e uno studente in uniforme sono impegnati in una rissa caotica proprio sul marciapiede."
  },
  AvgDialog_18893_Content_30 = {
    Text = "Si tratta di un gruppo scultoreo di cera ispirato al celebre dipinto di Botticelli. La figura femminile centrale ha un trucco comico e un'espressione chiaramente sofferente."
  },
  AvgDialog_18893_Content_31 = {
    Text = "Questa scultura al centro... non so perché, ma mi ricorda mia sorella maggiore."
  },
  AvgDialog_18893_Content_32 = {
    Text = "Rogers... È stato il Dott. Miller a presentarlo a Sarah. Dopo l'incidente all'Ospizio dei Poveri, è misteriosamente scomparso."
  },
  AvgDialog_18893_Content_33 = {
    Text = "Quindi è lui che ha ucciso mia sorella... e... Aigis..."
  },
  AvgDialog_18893_Content_34 = {
    Text = "Non vedo l'ora. Quando andiamo a prenderlo?"
  },
  AvgDialog_18893_Content_35 = {
    Text = "Dato che è probabilmente molto pericoloso, devo chiedervi di restare indietro mentre risolviamo la questione. Anche se sono certo che avrete altre idee."
  },
  AvgDialog_18893_Content_36 = {
    Text = "Quella è mia sorella. Devo andare! E poi, potreste aver bisogno di me per strisciare attraverso qualche condotto d'aerazione, prima o poi!"
  },
  AvgDialog_18893_Content_37 = {
    Text = "Sono sicuro che la tua unica Abilità si rivelerà molto utile in Battaglia."
  },
  AvgDialog_18893_Content_38 = {
    Text = "A quanto pare devo presentare una richiesta urgente per un'operazione sul campo."
  },
  AvgDialog_18893_Content_39 = {
    Text = "Sto per andare a parlare con il Professor Alistair. Spero che sia disposto a concederci un'autorizzazione speciale."
  },
  AvgDialog_18893_Content_4 = {Text = "..."},
  AvgDialog_18893_Content_40 = {
    Text = "Sono sicuro di sì, visto che la richiesta viene da te. Inoltre, cosa ancora più importante, dobbiamo convincere il Senior William a concederci una proroga per i rapporti sul campo."
  },
  AvgDialog_18893_Content_41 = {
    Text = "Oh, non devi preoccuparti di questo adesso."
  },
  AvgDialog_18893_Content_42 = {Text = "?"},
  AvgDialog_18893_Content_43 = {
    Text = "Circa un'ora fa, William ha lasciato la scuola con un permesso per operazioni sul campo."
  },
  AvgDialog_18893_Content_44 = {
    Text = "Ho provato a seguirlo per scovare qualche notizia, ma l'ho perso lungo la strada. Sembrava diretto verso il Distretto Ovest."
  },
  AvgDialog_18893_Content_45 = {
    Text = "Via Southwark si trova nel Distretto Ovest. A quanto pare, questa volta avremo l'occasione di vedere in azione il rinomato Investigatore William."
  },
  AvgDialog_18893_Content_46 = {
    Text = "Anche <Italic:William> deve andare, eh..."
  },
  AvgDialog_18893_Content_47 = {
    Text = "18:24, Londinium Ovest, Via Southwark"
  },
  AvgDialog_18893_Content_48 = {
    Text = "Grazie per la collaborazione. Da qui in poi me ne occupo io."
  },
  AvgDialog_18893_Content_49 = {
    Text = "Non se ne parla, signore. Gli ordini sono chiari: dobbiamo accompagnarla nell'indagine.\nInoltre, Rogers è anche un nostro sospettato; non possiamo lasciarle gestire la cosa da solo."
  },
  AvgDialog_18893_Content_5 = {Text = "..."},
  AvgDialog_18893_Content_50 = {
    Text = "E con le nostre risorse potrai nascondere meglio la tua vera identità."
  },
  AvgDialog_18893_Content_51 = {Text = "..."},
  AvgDialog_18893_Content_52 = {
    Text = "Non si preoccupi, signore. Abbiamo armi e gambe veloci. Non saremo un peso."
  },
  AvgDialog_18893_Content_53 = {
    Text = "Capito. Mantenete lo stato di allerta rossa. In caso di compromissione, la vostra vita ha la priorità sul completamento della missione."
  },
  AvgDialog_18893_Content_54 = {
    Text = "Aggiornamento: Raggiunta la posizione obiettivo, Via Southwark 44, Museo delle Cere Rogers. Obiettivo primario: Confermare potenziali legami tra il proprietario del museo, Rogers, e l'Associazione degli Scultori."
  },
  AvgDialog_18893_Content_55 = {
    Text = [[
Posizione confermata, obiettivo dell'indagine identificato.
Che la Chiave d'Argento Illumini il Cammino.]]
  },
  AvgDialog_18893_Content_56 = {
    Text = "Che la Chiave d'Argento ci Guidi."
  },
  AvgDialog_18893_Content_6 = {
    Text = "Il nostro topolino sta lottando contro il furetto."
  },
  AvgDialog_18893_Content_7 = {
    Text = "Woah, sto assistendo a uno spettacolo."
  },
  AvgDialog_18893_Content_8 = {Text = "Eh?"},
  AvgDialog_18893_Content_9 = {
    Text = "Uno spettacolo di cosa?"
  },
  AvgDialog_18894_Content_1 = {
    Text = "Notte Senza Uccelli"
  },
  AvgDialog_18894_Content_10 = {
    Text = "Non resterò più nell'inerzia."
  },
  AvgDialog_18894_Content_11 = {
    Text = "Non permetterò che la signorina Sarah, il piccolo Mac, Jenkin, o nessuno di voi...\nNon permetterò che le persone che conosco diventino pietre immobili come T'yog."
  },
  AvgDialog_18894_Content_12 = {
    Text = "Trattenendo le lacrime, Aigis si volta e corre verso l'uscita del seminterrato."
  },
  AvgDialog_18894_Content_13 = {Text = "Fermatela!"},
  AvgDialog_18894_Content_2 = {
    Text = "Questo è il mio... crimine. Il mio peccato."
  },
  AvgDialog_18894_Content_3 = {
    Text = "Aigis si ferma un istante e chiude gli occhi."
  },
  AvgDialog_18894_Content_4 = {
    Text = "Sono io quella che ha ucciso T'yog e ha trasformato il Piccolo Willy in un uomo di caramella. Io sono il vero Fantasma dell'Ospizio."
  },
  AvgDialog_18894_Content_5 = {
    Text = "Da quel giorno, qualcosa ha cercato di impossessarsi del mio corpo. Per fortuna, <Yellow:il signor Anderson> mi ha aiutata. Viveva nel mio occhio, insegnandomi a resistere all'oscurità."
  },
  AvgDialog_18894_Content_6 = {
    Text = "Ma la sua voce si è affievolita col tempo. Alla fine, l'ho persa in <Yellow:ogni notte di nebbia>... È tutta colpa mia, tutta colpa mia."
  },
  AvgDialog_18894_Content_7 = {
    Text = "Ho provato a indossare una benda sugli occhi, ho provato a legarmi al letto, ma niente ha funzionato. Le fasce che mi tenevano stretta di giorno venivano spezzate con facilità da quella forza durante la notte."
  },
  AvgDialog_18894_Content_8 = {
    Text = "Aigis si accarezza delicatamente il polso, arrossato dallo sforzo."
  },
  AvgDialog_18894_Content_9 = {
    Text = "La signorina Sarah deve aver notato qualcosa, credo.\nÈ per questo che è così disperata, così ansiosa che il dottore mi curi."
  },
  AvgDialog_18895_Content_1 = {
    Text = "Chi ha ucciso il pettirosso"
  },
  AvgDialog_18895_Content_10 = {
    Text = "Riconosci questa canzone da un sogno."
  },
  AvgDialog_18895_Content_11 = {
    Text = "Il tuo corpo si irrigidisce gradualmente, le ossa scricchiolano a ogni movimento. Ogni gesto è come forzare ingranaggi arrugginiti in una marionetta meccanica. Una polvere sottile cade dalle tue articolazioni."
  },
  AvgDialog_18895_Content_12 = {
    Text = "<Italic:Un giorno svanì — scomparso nel nulla.>"
  },
  AvgDialog_18895_Content_13 = {
    Text = [[
Le tue palpebre si fanno pesanti come piombo, costringendoti a chiuderle.
Nel mondo buio, solo una nebbia densa vortica.]]
  },
  AvgDialog_18895_Content_14 = {
    Text = "<Italic:Nessun soriano dove guardasse, da nessuna parte!>"
  },
  AvgDialog_18895_Content_15 = {
    Text = [[
Nel vuoto oscuro, sei solo.
Sopra cieli sconfinati, occhi color miele versano lacrime sciroppose, guardando in basso.]]
  },
  AvgDialog_18895_Content_16 = {
    Text = "<Italic:Pianse e pianse in preda alla disperazione —>"
  },
  AvgDialog_18895_Content_17 = {
    Text = "Ricordi l'agonia del vecchio morente e la densa lacrima nera all'angolo dei suoi occhi."
  },
  AvgDialog_18895_Content_18 = {
    Text = "<Italic:—Finché anche Charlie non fu mai esistito.>"
  },
  AvgDialog_18895_Content_19 = {
    Text = "Seguendo l'istinto, alzi lo sguardo e sussurri dolcemente agli occhi nel cielo che sembrano parlare."
  },
  AvgDialog_18895_Content_2 = {
    Text = "Secondo il racconto di Jenkin, il <Yellow:Fantasma dell'Ospizio> infesta il cortile durante le notti di nebbia, rapendo le vittime. L'Investigatore Anderson potrebbe essere tra loro."
  },
  AvgDialog_18895_Content_20 = {
    Text = "Non è questo che vorresti vedere, vero?"
  },
  AvgDialog_18895_Content_21 = {
    Text = [[
Gli occhi color miele tremano e battono le palpebre.
Le lacrime cadono, atterrando sulla tua guancia con un forte profumo dolce.]]
  },
  AvgDialog_18895_Content_22 = {
    Text = "In un istante, il canto si ferma e l'oscurità svanisce. Torni in te ancora una volta.\nScopri che la nebbia si è un po' diradata mentre eri perduto."
  },
  AvgDialog_18895_Content_23 = {Text = "WOAH!"},
  AvgDialog_18895_Content_24 = {
    Text = "La bambina accorre, ti riconosce da vicino e stringe nervosamente il suo orsacchiotto."
  },
  AvgDialog_18895_Content_25 = {
    Text = "S-sponsor, perché sei qui?"
  },
  AvgDialog_18895_Content_26 = {
    Text = "Apprezziamo la vostra ospitalità. Stavamo semplicemente prendendo una boccata d'aria serale. C'è qualche problema?"
  },
  AvgDialog_18895_Content_27 = {
    Text = "Le notti di nebbia sono pericolose, non dovreste vagare all'esterno, o..."
  },
  AvgDialog_18895_Content_28 = {
    Text = "Oppure... cosa?"
  },
  AvgDialog_18895_Content_29 = {
    Text = [[
Lasciami indovinare... altrimenti verremo presi, giusto?
Sai chi sono le vittime e dove sono finite, vero?]]
  },
  AvgDialog_18895_Content_3 = {
    Text = "Non c'è tempo da perdere, allora; andiamo subito nel seminterrato di cui ha parlato Jenkin."
  },
  AvgDialog_18895_Content_30 = {
    Text = "Aigis resta impietrita, trema e scuote la testa, incapace di parlare."
  },
  AvgDialog_18895_Content_31 = {
    Text = "Aigis, sei una brava bambina. Le brave bambine non dovrebbero dire bugie."
  },
  AvgDialog_18895_Content_32 = {Text = "Io..."},
  AvgDialog_18895_Content_33 = {
    Text = "Rispondimi, Aigis! Hai detto che non dovremmo aggirarci nella nebbia, quindi perché sei qui?"
  },
  AvgDialog_18895_Content_34 = {
    Text = "Le mani della bambina si stringono forte l'una all'altra."
  },
  AvgDialog_18895_Content_35 = {
    Text = "Per favore... non chiedere altro..."
  },
  AvgDialog_18895_Content_36 = {
    Text = "Ramona, la nebbia si è infittita di nuovo."
  },
  AvgDialog_18895_Content_37 = {
    Text = "Nella nebbia, coppie di occhi scarlatti si accendono, fissando senza via di fuga."
  },
  AvgDialog_18895_Content_4 = {
    Text = "Non essere avventato, l'ingresso è vicino all'ufficio della sorvegliante."
  },
  AvgDialog_18895_Content_5 = {
    Text = "Aspetteremo che la notte sia più fonda e agiremo quando Sarah dormirà.\nPrima di allora, riposiamo e recuperiamo le forze."
  },
  AvgDialog_18895_Content_6 = {
    Text = "Eh? Si sta alzando la nebbia?"
  },
  AvgDialog_18895_Content_7 = {
    Text = [[
Una nebbia insolitamente fitta si diffonde nell'area proprio mentre parli.
La foschia, che dovrebbe essere leggera e fluttuante, ora ti si aggrappa addosso come un peso denso e appiccicoso.]]
  },
  AvgDialog_18895_Content_8 = {
    Text = "Nella fitta nebbia, senti qualcuno cantare."
  },
  AvgDialog_18895_Content_9 = {
    Text = "<Italic:Il soriano del vecchio Charlie, grasso e caro...>"
  },
  AvgDialog_18896_Content_1 = {
    Text = "In uno stato confuso, una voce misteriosa sussurra all'orecchio della bambina."
  },
  AvgDialog_18896_Content_2 = {
    Text = [[
Arrenditi e basta. Chiudi gli occhi e lascia tutto a me.
Sarah, il piccolo Mac... tutti quelli dell'ospizio diventeranno belli ed eterni.]]
  },
  AvgDialog_18896_Content_3 = {
    Text = "No, non lo farò... Non cederò... Mai più..."
  },
  AvgDialog_18896_Content_4 = {
    Text = "Cerchi di combattermi? Non durerai a lungo senza l'aiuto di quell'impiccione. Ecco perché posso impossessarmi di te anche quando sei sveglia."
  },
  AvgDialog_18896_Content_5 = {
    Text = "Perché non ti arrendi? E mi aiuti a trasformare tutti qui in materiali preziosi."
  },
  AvgDialog_18896_Content_6 = {
    Text = "Non lo farò! E il signor Anderson NON è un impiccione!"
  },
  AvgDialog_18896_Content_7 = {
    Text = "Lui mi ha protetta... E io proteggerò tutti. Proteggerò la signorina Sarah, proteggerò il piccolo Mac, proteggerò Jenkin. E proteggerò i gentili visitatori."
  },
  AvgDialog_18896_Content_8 = {
    Text = "Li proteggerò, anche a costo di tutto ciò che ho—"
  },
  AvgDialog_18897_Content_1 = {
    Text = "Ora, vedi? Dibattiti pure quanto vuoi, i cambiamenti su di te non si fermeranno, non importa quanto tu sia disposta a sacrificare."
  },
  AvgDialog_18897_Content_10 = {
    Text = "Io credo in loro. Credo che elimineranno..."
  },
  AvgDialog_18897_Content_11 = {Text = "<Red:Io>."},
  AvgDialog_18897_Content_12 = {
    Text = "Ho sentito tutto. Stai avendo davvero difficoltà a trovare un soggetto perfetto come me."
  },
  AvgDialog_18897_Content_13 = {
    Text = "Le tue malefatte sono state smascherate. Ora, saranno tutti al sicuro quando non ci sarò più, vero?"
  },
  AvgDialog_18897_Content_14 = {
    Text = "La Voce Misteriosa non risponde."
  },
  AvgDialog_18897_Content_2 = {
    Text = "Così funziona il mondo, e tutti lo capiscono quando crescono. Non importa quanto ti sforzi, lotti o resisti, non puoi sfuggire all'ambiente che ti circonda."
  },
  AvgDialog_18897_Content_3 = {
    Text = "Sei ancora giovane, ma non mi dispiace insegnarti questa lezione in anticipo."
  },
  AvgDialog_18897_Content_4 = {
    Text = "No, non è vero..."
  },
  AvgDialog_18897_Content_5 = {
    Text = "Perché io... non sono più sola...\nIo... mi fido di loro!"
  },
  AvgDialog_18897_Content_6 = {
    Text = [[
{Male=Mr.,Female=Miss} %player%, la signorina Ramona, Ogier...
Loro sono diversi. Sono forti, e elimineranno...]]
  },
  AvgDialog_18897_Content_7 = {
    Text = "La voce la interrompe con impazienza, con un freddo ghigno beffardo."
  },
  AvgDialog_18897_Content_8 = {
    Text = [[
Eliminare me...? Non riescono nemmeno a trovare dove mi trovo, vero?
Dopotutto, nemmeno tu sai dove sono.]]
  },
  AvgDialog_18897_Content_9 = {
    Text = "No, non è vero..."
  },
  AvgDialog_18898_Content_1 = {
    Text = "Tutto come al solito"
  },
  AvgDialog_18898_Content_10 = {
    Text = "Rogers, il benefattore, scomparve, lasciando il futuro dell'ospizio incerto.\nCol tempo, Lord Dexter fornì generosamente i fondi e organizzò la presa in carico dell'ospizio."
  },
  AvgDialog_18898_Content_11 = {
    Text = "Il giorno in cui Lord Dexter prende in carico il Laboratorio di Lilian, tu e Ramona fate ritorno."
  },
  AvgDialog_18898_Content_12 = {
    Text = "Una suora dirige gli operai affinché spostino un lettino dall'area medica."
  },
  AvgDialog_18898_Content_13 = {
    Text = "Ma quella non è la Sarah che ricordi."
  },
  AvgDialog_18898_Content_14 = {
    Text = "Che strano. Non abbiamo mai avuto fanciulli malati qui, quindi perché c'è questo letto...?"
  },
  AvgDialog_18898_Content_15 = {
    Text = "Sull'angolo della struttura di ferro del letto, restano ancora legate alcune strisce di stoffa strappata."
  },
  AvgDialog_18898_Content_16 = {
    Text = "Come rispondendo al desiderio di Aigis, il ricordo di lei svanisce dalle menti dell'Ospizio dei Poveri nel giro di due settimane."
  },
  AvgDialog_18898_Content_17 = {
    Text = "Il vecchio ordine si spezza, e uno nuovo si forma rapidamente."
  },
  AvgDialog_18898_Content_18 = {
    Text = [[
Alcuni se ne andarono, altri scomparvero. Alcuni incubi finirono, alcune condizioni persistettero.
Ma la vita va avanti, senza concedere pause.]]
  },
  AvgDialog_18898_Content_19 = {
    Text = "Sarah giace quieta su un piccolo letto. La sua testa resta incrinata, gli arti avvinti da catene."
  },
  AvgDialog_18898_Content_2 = {
    Text = "Più tardi—"
  },
  AvgDialog_18898_Content_20 = {
    Text = "Posso avere la chiave per un momento?"
  },
  AvgDialog_18898_Content_21 = {
    Text = "Il Capitano del Comitato che li accompagna aggrotta le sopracciglia e posa la chiave sul comodino."
  },
  AvgDialog_18898_Content_22 = {
    Text = "Vado a controllare il perimetro. Voi tenete d'occhio la situazione."
  },
  AvgDialog_18898_Content_23 = {
    Text = "Tu e Ramona sbloccate silenziosamente le catene."
  },
  AvgDialog_18898_Content_24 = {
    Text = "Signorina Sarah, lei... si ricorda ancora di noi?"
  },
  AvgDialog_18898_Content_25 = {
    Text = "Il Mostro silenzioso scuote la testa — se quella massa nera e stillante può ancora essere chiamata testa."
  },
  AvgDialog_18898_Content_26 = {
    Text = "Si ricorda... di Aigis?"
  },
  AvgDialog_18898_Content_27 = {
    Text = "Come confusa, Sarah ripete le vostre parole."
  },
  AvgDialog_18898_Content_28 = {
    Text = "Ai... gis...?"
  },
  AvgDialog_18898_Content_29 = {
    Text = "I suoi organi vocali gorgogliano, tremando con toni caotici."
  },
  AvgDialog_18898_Content_3 = {
    Text = "Un'unità inviata dal Comitato giunse al Laboratorio di Lilian per scortare Sanga fuori dal seminterrato."
  },
  AvgDialog_18898_Content_30 = {
    Text = "Dopo un lungo Silenzio, Sarah tende una mano serrata a pugno."
  },
  AvgDialog_18898_Content_31 = {
    Text = "Mi state... dando qualcosa?"
  },
  AvgDialog_18898_Content_32 = {
    Text = "Apri il palmo della mano."
  },
  AvgDialog_18898_Content_33 = {
    Text = "Un piccolo Nucleo d'Argento vi cade dentro."
  },
  AvgDialog_18898_Content_34 = {
    Text = "Ai... gis..."
  },
  AvgDialog_18898_Content_35 = {
    Text = "Questa è... lei?"
  },
  AvgDialog_18898_Content_36 = {
    Text = "Frammenti di memorie convergono."
  },
  AvgDialog_18898_Content_37 = {
    Text = "Quando Aigis precipitò come un uccello nella notte, vi lanciaste tutti verso di lei."
  },
  AvgDialog_18898_Content_38 = {
    Text = "Jenkin afferrò un nastro, tu raccogliesti un involucro di caramella, e Sarah, già impazzita...\nSeguendo l'istinto, toccò ciò che restava dell'anima della ragazza."
  },
  AvgDialog_18898_Content_39 = {
    Text = "Consegnatelo al Laboratorio Argento. Forse un giorno potremo Risvegliare quella Bambina e il Potere che custodisce in sé."
  },
  AvgDialog_18898_Content_4 = {
    Text = "Mentre veniva trasportata sulla barella del Comitato, ti guardò con un mezzo sorriso. Leggesti le sue parole dal movimento delle labbra."
  },
  AvgDialog_18898_Content_40 = {
    Text = "Dovremmo dirlo a Jenkin?"
  },
  AvgDialog_18898_Content_41 = {
    Text = [[
...Le fasi iniziali del Risveglio inducono frammentazione della memoria.
Alcuni sperimentano amnesia completa, altri conservano solo frammenti emotivamente carichi che richiedono ricostruzione.]]
  },
  AvgDialog_18898_Content_42 = {
    Text = "Aigis è stata modificata, e la struttura del suo Nucleo d'Argento è instabile.\nAnche se riuscissimo nel suo Risveglio, potrebbe non riconoscere Jenkin..."
  },
  AvgDialog_18898_Content_43 = {
    Text = "Credo dovremmo dirglielo quando le cose si saranno calmate."
  },
  AvgDialog_18898_Content_44 = {
    Text = "Chiudi la mano, sentendo il calore del Nucleo d'Argento, ricordando la Bambina che seguiva sempre il gruppo, quasi invisibile."
  },
  AvgDialog_18898_Content_45 = {
    Text = "Quando vi incontraste per la prima volta, lei seguiva Sarah e vi salutò con un timido Benvenuto;"
  },
  AvgDialog_18898_Content_46 = {
    Text = "Quando Jenkin vi portò nel reparto, lei si nascose dietro Jenkin, spaventata."
  },
  AvgDialog_18898_Content_47 = {
    Text = "Solo quell'ultimo istante di coraggio la trasformò in una stella cadente, ardente e luminosa contro il crepuscolo."
  },
  AvgDialog_18898_Content_48 = {
    Text = "Aigis... il suo Sacrificio ha salvato Tutti coloro che erano rimasti."
  },
  AvgDialog_18898_Content_49 = {
    Text = "Lei è... una vera cavaliera."
  },
  AvgDialog_18898_Content_5 = {
    Text = "Lo capisci, vero?"
  },
  AvgDialog_18898_Content_50 = {
    Text = "<Blue:Investigatore Sean Anderson>... Gli Scultori gli hanno estratto con la forza il Nucleo d'Argento dopo averlo ucciso, eppure lui ha impiegato la coscienza residua per Assistere Aigis."
  },
  AvgDialog_18898_Content_51 = {
    Text = "Non siamo nemmeno riusciti a raccogliere le sue spoglie."
  },
  AvgDialog_18898_Content_52 = {
    Text = "Ramona, possiamo davvero salvare qualcosa? Possiamo davvero cambiare qualcosa?"
  },
  AvgDialog_18898_Content_53 = {
    Text = "Questo è il prezzo per affrontare la Dissoluzione."
  },
  AvgDialog_18898_Content_54 = {
    Text = "Custode, tu sei speciale. Ecco perché non puoi fermarti qui."
  },
  AvgDialog_18898_Content_55 = {
    Text = "Dobbiamo fare qualcosa. Salvare le persone. Portare un cambiamento.\nMa, anche se alla fine non si otterrà nulla..."
  },
  AvgDialog_18898_Content_56 = {
    Text = "Prima dell'avvento di quella notte oscura in cui tutto sarà dimenticato, lascia che la tua memoria sia l'ultima testimone di ciò che è accaduto."
  },
  AvgDialog_18898_Content_6 = {
    Text = "Il vescovo della Cattedrale di Londinium giunse all'ospizio dei poveri. Dopo aver raggiunto un accordo con il Comitato, Sarah — in preda a una trasformazione irreversibile — fu temporaneamente ospitata nella cattedrale sotto guardia."
  },
  AvgDialog_18898_Content_7 = {
    Text = "Seguendo i vaghi ricordi dei fanciulli, individuaste il laboratorio abbandonato del Dott. Miller."
  },
  AvgDialog_18898_Content_8 = {
    Text = "Il luogo era deserto."
  },
  AvgDialog_18898_Content_9 = {
    Text = "William assegnò una squadra d'indagine per rintracciare i suoi spostamenti e coordinarsi con il Comitato per una ricerca su vasta scala delle basi degli scultori."
  },
  AvgDialog_18899_Content_1 = {
    Text = "Sogno nero pece"
  },
  AvgDialog_18899_Content_10 = {
    Text = "<Italic:Perquisì l'armadio, controllò il letto,>"
  },
  AvgDialog_18899_Content_11 = {
    Text = "Lo spazio si restringe. Una pressione schiacciante ti ruba il respiro e il tuo corpo si irrigidisce, immobile."
  },
  AvgDialog_18899_Content_12 = {
    Text = "<Italic:Controlla il seminterrato, gli aveva detto il suo amico,>"
  },
  AvgDialog_18899_Content_13 = {
    Text = [[
Solo i tuoi occhi e la tua gola funzionano ancora.
Tutto intorno a te, un dolore lieve e pungente si diffonde, come se degli insetti stessero rosicchiando la tua pelle.]]
  },
  AvgDialog_18899_Content_14 = {
    Text = "<Italic:Nessun soriano dove guardasse, da nessuna parte!>"
  },
  AvgDialog_18899_Content_15 = {
    Text = "<Shake:Qualcuno... per favore... aiuto...>"
  },
  AvgDialog_18899_Content_16 = {
    Text = "<Italic:Pianse e pianse in preda alla disperazione —>"
  },
  AvgDialog_18899_Content_17 = {
    Text = "<Shake:...@1...Io... Ramon@1...>"
  },
  AvgDialog_18899_Content_18 = {
    Text = "<Italic:—Finché anche Charlie non fu mai esistito.>"
  },
  AvgDialog_18899_Content_19 = {
    Text = "La pelle ti formicola come se insetti la rodessero, il dolore che trema debolmente. Un sapore metallico ti inonda la gola, riducendoti al silenzio, immergendo il mondo nella quiete."
  },
  AvgDialog_18899_Content_2 = {
    Text = "Ti risvegli nell'oscurità più totale."
  },
  AvgDialog_18899_Content_20 = {Text = "..."},
  AvgDialog_18899_Content_21 = {
    Text = "Da qualche parte, in qualche tempo, hai già vissuto tutto questo."
  },
  AvgDialog_18899_Content_22 = {
    Text = "Chi ti trasse dall'Oscurità l'ultima volta era—"
  },
  AvgDialog_18899_Content_23 = {
    Text = "%player%! %player%, svegliati!"
  },
  AvgDialog_18899_Content_24 = {
    Text = "La luce esplode. Qualcuno ti afferra la mano. Ti risvegli di soprassalto, madido di sudore freddo."
  },
  AvgDialog_18899_Content_25 = {
    Text = "Cos'era? Un altro sogno strano?"
  },
  AvgDialog_18899_Content_26 = {
    Text = "...Non ne sono sicuro."
  },
  AvgDialog_18899_Content_27 = {
    Text = "Da quando sei tornato da <Yellow:Akut>, i sogni ti perseguitano—\ni tuoi, quelli degli altri, sogni del passato, persino... visioni del futuro."
  },
  AvgDialog_18899_Content_28 = {
    Text = "Ramona, possiamo andare insieme al Keygrave?"
  },
  AvgDialog_18899_Content_29 = {
    Text = "Tu e Ramona camminate in silenzio nel Keygrave finché non scorgi una lapide ordinaria eppure unica."
  },
  AvgDialog_18899_Content_3 = {
    Text = "Sembra uno spazio angusto — piccolo, buio, silenzioso, freddo, privo di luce, con l'aria rarefatta, come se fossi intrappolato dentro una bara."
  },
  AvgDialog_18899_Content_30 = {
    Text = "Questa è la tua lapide."
  },
  AvgDialog_18899_Content_31 = {Text = "Ramona..."},
  AvgDialog_18899_Content_32 = {
    Text = "Ho sognato l'esplosione di Yakutsk... Ho sognato di essere sepolto sotto le macerie e te che mi tiravi fuori."
  },
  AvgDialog_18899_Content_33 = {
    Text = "Devo la mia seconda vita a te. A Mythag."
  },
  AvgDialog_18899_Content_34 = {
    Text = "Trovarti è stata una benedizione per me e per i Mythag.\nSenza di te, tutti qui sarebbero stati inghiottiti dalla <Yellow:Cladi della Dissoluzione> di Akut."
  },
  AvgDialog_18899_Content_35 = {
    Text = "Ancora non riesci a ricordare cosa accadde prima di allora?"
  },
  AvgDialog_18899_Content_36 = {
    Text = "Scuoti la testa."
  },
  AvgDialog_18899_Content_37 = {
    Text = "La polvere vorticante di Yakutsk e il volto ansioso di Ramona segnano l'Inizio delle tue Memorie. La tua vita passata sembra perduta nell'esplosione della landa desolata."
  },
  AvgDialog_18899_Content_38 = {
    Text = "La nostra medico scolastica, la dottoressa Sylvia, ha osservato che il recupero della memoria avviene in modo progressivo. L'interazione sociale e le esperienze variegate possono contribuire a stimolare i ricordi."
  },
  AvgDialog_18899_Content_39 = {
    Text = "Ti sei ripreso? <Blue:William> attende il nostro rapporto."
  },
  AvgDialog_18899_Content_4 = {
    Text = "La paura ti sopraffà. Ti dibatti, martelli e gridi, ma la fuga sembra impossibile."
  },
  AvgDialog_18899_Content_40 = {
    Text = "Ecco il briefing della missione: infiltrati nel Laboratorio di Lilian in modo furtivo e localizza l'Investigatore disperso <Blue:Sean Anderson>."
  },
  AvgDialog_18899_Content_41 = {
    Text = "Le squadre d'avanguardia non hanno rilevato firme di <Yellow:Cataclisma> ad alto rischio all'esterno dell'ospizio, ma mantieni la cautela operativa. Sarai accompagnato da Ramona e da ulteriori Risvegliati."
  },
  AvgDialog_18899_Content_42 = {
    Text = "So che puoi collegare più Risvegliati contemporaneamente, ma considerando il peso fisico... Sarai accompagnato da Ogier, che è già collegato a te."
  },
  AvgDialog_18899_Content_43 = {
    Text = "Sissignore! Darò il massimo!"
  },
  AvgDialog_18899_Content_44 = {
    Text = "C'è qualcos'altro che dovremmo sapere sulla scomparsa di Anderson?"
  },
  AvgDialog_18899_Content_45 = {
    Text = "Questo distretto rappresenta la zona con la più alta concentrazione di sparizioni del Distretto Est, con casi che si estendono su sei mesi. L'Investigatore Anderson, essendo originario del Distretto Est, probabilmente ha scoperto indizi cruciali."
  },
  AvgDialog_18899_Content_46 = {
    Text = "Sebbene risolvere i casi di sparizione sarebbe l'ideale, devi mantenere la concentrazione sulla localizzazione dell'Investigatore disperso."
  },
  AvgDialog_18899_Content_47 = {
    Text = "Il tempo stringe e le possibilità di sopravvivenza di Sean si riducono. Ora vai.\nChe la Chiave d'argento illumini il tuo cammino."
  },
  AvgDialog_18899_Content_5 = {
    Text = "A poco a poco, una voce canta nell'oscurità."
  },
  AvgDialog_18899_Content_6 = {
    Text = "<Italic:Il soriano del vecchio Charlie, grasso e caro,>"
  },
  AvgDialog_18899_Content_7 = {
    Text = "C'è nessuno? Qualcuno? Per favore?"
  },
  AvgDialog_18899_Content_8 = {
    Text = "<Italic:Un giorno svanì — scomparso nel nulla.>"
  },
  AvgDialog_18899_Content_9 = {
    Text = "Ti sembra familiare. Sì, sei già stato avvolto da questo vuoto soffocante."
  },
  AvgDialog_18900_Content_1 = {
    Text = "Incubo Cromatico"
  },
  AvgDialog_18900_Content_10 = {
    Text = [[
Ci mettemmo in fila, aspettando la selezione del dottore.
Mi sentivo senza peso. Come aria. Come niente.]]
  },
  AvgDialog_18900_Content_11 = {
    Text = "Scegliamo questa bambina. Le sue condizioni sono piuttosto complesse, e l'ultima volta non siamo riusciti a curarla."
  },
  AvgDialog_18900_Content_12 = {
    Text = "<Shake:No... non voglio andare... ci sono già stata una volta, e non voglio...>"
  },
  AvgDialog_18900_Content_13 = {
    Text = "Vado io, signore."
  },
  AvgDialog_18900_Content_14 = {Text = "!"},
  AvgDialog_18900_Content_15 = {
    Text = "...Non ti senti bene?"
  },
  AvgDialog_18900_Content_16 = {
    Text = [[
Non mi sento male; posso correre e saltare, sono perfettamente sana!
Ma riesco a vedere delle cose.]]
  },
  AvgDialog_18900_Content_17 = {
    Text = "Oh? Cosa riesci a vedere?"
  },
  AvgDialog_18900_Content_18 = {
    Text = [[
Come Aigis, anch'io vedo cose nere.
Potrebbe aiutarmi, per favore?]]
  },
  AvgDialog_18900_Content_19 = {
    Text = "Interessante. Allora porto te."
  },
  AvgDialog_18900_Content_2 = {
    Text = "All'inizio, dissero che erano venuti per offrire aiuto."
  },
  AvgDialog_18900_Content_20 = {Text = "T'yog..."},
  AvgDialog_18900_Content_21 = {
    Text = "Non avere paura, Aigis."
  },
  AvgDialog_18900_Content_22 = {
    Text = "Tornerò presto."
  },
  AvgDialog_18900_Content_23 = {
    Text = "T'yog non tornò mai più."
  },
  AvgDialog_18900_Content_24 = {
    Text = "Dissero alla signorina Sarah che la sua malattia era grave, ma che un gentile signore lo avrebbe preso con sé. Pagò per l'operazione e tutto il resto."
  },
  AvgDialog_18900_Content_25 = {
    Text = "Mentivano, persino io riuscivo a capirlo. Ma la signorina Sarah ci credette. Li ringraziò ancora e ancora."
  },
  AvgDialog_18900_Content_26 = {
    Text = "Perché, perché è finita così..."
  },
  AvgDialog_18900_Content_27 = {
    Text = "Camminavo nel corridoio, con le vertigini. Urtai qualcuno di alto."
  },
  AvgDialog_18900_Content_28 = {
    Text = "Salve, piccina. Potresti indicarmi come raggiungere il nuovo reparto?"
  },
  AvgDialog_18900_Content_29 = {
    Text = "Arrivarono altri malati. La signorina Sarah spostò il reparto nell'edificio est.\nPiù spazio. Più letti improvvisati."
  },
  AvgDialog_18900_Content_3 = {
    Text = "Non so quando sia iniziato. Una strana malattia si è propagata nell'Ospizio dei Poveri. Gli infetti si arrabbiavano in fretta, con segni triangolari neri sulla testa, sulle mani, sui piedi."
  },
  AvgDialog_18900_Content_30 = {
    Text = "P-potreste per favore non andare là?\nÈ... è davvero pericoloso..."
  },
  AvgDialog_18900_Content_31 = {
    Text = "Oh? Perché dici questo?"
  },
  AvgDialog_18900_Content_32 = {
    Text = "Non lo so, m-mi dispiace davvero...\nIl reparto è a est."
  },
  AvgDialog_18900_Content_33 = {
    Text = [[
Grazie.
Sembri avere molti pensieri per la testa. Se ti va di parlare, sono tutto orecchi.]]
  },
  AvgDialog_18900_Content_34 = {
    Text = "Ho una sorellina che ha più o meno la tua età..."
  },
  AvgDialog_18900_Content_35 = {
    Text = "Si incamminò verso est, il suo vistoso Nastro Rosso ondeggiava nell'aria."
  },
  AvgDialog_18900_Content_36 = {
    Text = "Fu l'ultima volta che vidi la sorella di Jenkin. Dopo quel giorno, era scomparsa."
  },
  AvgDialog_18900_Content_37 = {
    Text = "Sapevo che vedevano tutto attraverso il mio occhio."
  },
  AvgDialog_18900_Content_38 = {
    Text = "Così l'ho coperto con una benda. Era l'occhio malato."
  },
  AvgDialog_18900_Content_39 = {
    Text = "Ma questo non fermò gli incubi."
  },
  AvgDialog_18900_Content_4 = {
    Text = "La signorina Sarah li mandò alla clinica. I segni non scomparivano. Ne apparivano altri..."
  },
  AvgDialog_18900_Content_40 = {
    Text = "Ugh... Questo è..."
  },
  AvgDialog_18900_Content_41 = {
    Text = "La luce mi faceva venire voglia di chiudere gli Occhi. Provai a sbattere le palpebre, ma non ci riuscii."
  },
  AvgDialog_18900_Content_42 = {
    Text = "Qualcosa mi teneva le palpebre aperte."
  },
  AvgDialog_18900_Content_43 = {
    Text = "Arrivò un uomo in camice bianco, un coltello in Mano. Si avvicinò lentamente a me..."
  },
  AvgDialog_18900_Content_44 = {
    Text = "No, NO! Signorina Sarah, SIGNORINA SARAH!"
  },
  AvgDialog_18900_Content_45 = {
    Text = "Signorina Sarah! T'yog! Aiuto! Aiutami! <Big:NOOO!!>"
  },
  AvgDialog_18900_Content_46 = {
    Text = "La Lama si avvicinò sempre di più, fino a consumare la mia Visuale. E poi, e poi—"
  },
  AvgDialog_18900_Content_47 = {
    Text = "<Shake:AAAAAHHH—!>"
  },
  AvgDialog_18900_Content_48 = {
    Text = [[
Buio. Freddo. Come annegare nel fiume Aethis a dicembre.
Volevo alzarmi, ma non ci riuscivo.]]
  },
  AvgDialog_18900_Content_49 = {
    Text = "Fa male... Quell'occhio fa così male..."
  },
  AvgDialog_18900_Content_5 = {
    Text = "Ne parlai alla signorina Sarah, ma lei disse..."
  },
  AvgDialog_18900_Content_50 = {
    Text = [[
Il Dottore mi ha ficcato qualcosa nell'occhio, e poi ho visto dei colori.
Colori che si mescolavano, come la tavolozza rovesciata del piccolo Mac.]]
  },
  AvgDialog_18900_Content_51 = {
    Text = "Signorina Sarah... T'yog... Fa male... Fa così, così male... Non ce la faccio più..."
  },
  AvgDialog_18900_Content_52 = {
    Text = "Si muovevano... i Colori stavano cambiando! Strisciavano nel mio occhio come insetti. Non riuscivo a vedere nulla. Solo Colori."
  },
  AvgDialog_18900_Content_53 = {
    Text = "Mi sbagliavo. Non avrei dovuto chiedere aiuto..."
  },
  AvgDialog_18900_Content_54 = {
    Text = "I colori mi invadevano la mente. Stavo perdendo me stessa..."
  },
  AvgDialog_18900_Content_55 = {
    Text = "Vi prego... qualcuno... aiuto..."
  },
  AvgDialog_18900_Content_56 = {
    Text = "Stavo quasi per svanire quando mi impiantarono qualcos'altro. Poi una luce d'Argento divorò i Colori."
  },
  AvgDialog_18900_Content_57 = {
    Text = "Faceva così freddo. Faceva ancora male, ma ero di nuovo me stessa."
  },
  AvgDialog_18900_Content_58 = {
    Text = "Non avere paura, piccola. Sono qui per aiutarti."
  },
  AvgDialog_18900_Content_59 = {
    Text = "Chi... sei...?"
  },
  AvgDialog_18900_Content_6 = {
    Text = "Aigis, le tue allucinazioni stanno peggiorando.\nNon c'è nessun segno nero qui."
  },
  AvgDialog_18900_Content_60 = {Text = "..."},
  AvgDialog_18900_Content_61 = {
    Text = [[
Chi sono non ha importanza.
Ora, segui il mio ritmo. Insieme resisteremo al controllo di quella <Yellow:cosa estranea>.]]
  },
  AvgDialog_18900_Content_62 = {
    Text = "Con l'aiuto di quella Voce, mi sentivo meno male. Riuscivo a pensare di nuovo."
  },
  AvgDialog_18900_Content_63 = {
    Text = "Avevo perso il conto di quanto tempo fosse passato. Sembrava un'eternità, la mia pelle era diventata insensibile. Poi udii di nuovo la Voce del Dottore."
  },
  AvgDialog_18900_Content_64 = {
    Text = "Un occhio che riesce a vedere @2... È il miglior soggetto di ricerca che abbia mai trovato.\nL'avrei già usata per gli esperimenti se non fosse stato per quello stupido ragazzo."
  },
  AvgDialog_18900_Content_65 = {
    Text = "Non è troppo tardi, Dottore. Un innesto xenotrapiantato di nucleo d'Argento riuscito con successo! C'è da festeggiare!"
  },
  AvgDialog_18900_Content_66 = {
    Text = "La fusione della coscienza di @4 con il recettore è riuscita. L'Effetto di pietrificazione esula dai parametri previsti, ma finché continueremo a esercitare Soppressione sulla coscienza del recettore..."
  },
  AvgDialog_18900_Content_67 = {
    Text = "Dovremmo ringraziare quello sciocco <Yellow:Investigatore> per essersi presentato alla nostra porta. Il suo nucleo d'Argento di prima qualità ha ridotto il rigetto."
  },
  AvgDialog_18900_Content_68 = {
    Text = "Quei Ricercatori mi si affollavano intorno, parlando a voce alta. Sembravano così eccitati. Recettore? Rigetto? Investigatore? Parole che non conoscevo."
  },
  AvgDialog_18900_Content_69 = {
    Text = "Allora, piccola? Avanti, prova. Con un solo sguardo, la tua migliore amica resterà con te per sempre... come il tuo dolcetto preferito."
  },
  AvgDialog_18900_Content_7 = {
    Text = "No, signorina Sarah, riesco a vederlo. Davvero!"
  },
  AvgDialog_18900_Content_70 = {
    Text = "Strinsero il dispositivo che teneva le mie palpebre aperte. Un Bagliore, e gli uncini avrebbero tagliato."
  },
  AvgDialog_18900_Content_71 = {
    Text = [[
Hanno portato una sedia.
Legato ad essa c'era il mio migliore amico...]]
  },
  AvgDialog_18900_Content_72 = {
    Text = "T-T'yog...?"
  },
  AvgDialog_18900_Content_73 = {
    Text = "T'yog si destò di soprassalto. Mi guardò, poi si guardò intorno."
  },
  AvgDialog_18900_Content_74 = {
    Text = "Aigis?! Giù le mani! Non toccarla!"
  },
  AvgDialog_18900_Content_75 = {
    Text = "No! Non muoverti! T'YOG! NON GUARDARMI!!"
  },
  AvgDialog_18900_Content_76 = {
    Text = "T'yog piangeva e si dimenava, ma non servì a nulla.\nSi muoveva sempre più lentamente, come un orologio rotto."
  },
  AvgDialog_18900_Content_77 = {
    Text = "Come rassegnato al Fato, mi guardò in silenzio. I nostri Occhi si incontrarono, e poi—"
  },
  AvgDialog_18900_Content_78 = {
    Text = "Cominciò a dissolversi come il vecchio vestito della signorina Sarah. Uno sciroppo dolciastro colava dalla sua pelle, ricoprendo il suo corpo duro come la pietra."
  },
  AvgDialog_18900_Content_79 = {
    Text = "Il mio <Yellow:occhio> osservava. Mi costrinsero a guardare, finché quello—lui—non esalò l'ultimo respiro."
  },
  AvgDialog_18900_Content_8 = {
    Text = "Non preoccuparti. Non è reale, tesoro. Non mi credi? Chiedi al piccolo Mac.\nHa solo cinque anni. Non mente."
  },
  AvgDialog_18900_Content_80 = {
    Text = "Ai... gis..."
  },
  AvgDialog_18900_Content_81 = {
    Text = "<Big:T'YOG—!!>"
  },
  AvgDialog_18900_Content_9 = {
    Text = "Sì, Aigis, dobbiamo fare i bravi e ascoltare il dottore quando siamo malati.\nÈ quello che mi hai detto tu quando avevo la febbre!"
  },
  AvgDialog_18901_Content_1 = {
    Text = "Il Nostro Segreto"
  },
  AvgDialog_18901_Content_10 = {
    Text = "Ordine della squadra: Jenkin, Ramona, tu."
  },
  AvgDialog_18901_Content_11 = {
    Text = "Alle tue spalle, Brown squittisce e spinge la porta di legno fino a chiuderla."
  },
  AvgDialog_18901_Content_12 = {Text = "..."},
  AvgDialog_18901_Content_13 = {
    Text = "Mia sorella e il tuo amico studente devono essere laggiù, insieme a quel cosiddetto fantasma."
  },
  AvgDialog_18901_Content_14 = {
    Text = "Fiammiferi, dove sono quei fiammiferi..."
  },
  AvgDialog_18901_Content_15 = {
    Text = "Ehi, senti quel prurito?"
  },
  AvgDialog_18901_Content_16 = {
    Text = "Il suo avvertimento ti fa notare un formicolio inspiegabile che si propaga dalle dita dei piedi alle caviglie, e su lungo la schiena..."
  },
  AvgDialog_18901_Content_17 = {
    Text = "Jenkin finisce finalmente di lucidare la lanterna, abbassandola per illuminare un piccolo lembo di terreno."
  },
  AvgDialog_18901_Content_18 = {
    Text = "In quel preciso istante—"
  },
  AvgDialog_18901_Content_19 = {
    Text = "La tua retina viene colpita da una visione straziante."
  },
  AvgDialog_18901_Content_2 = {
    Text = "Dopo una notte di tumulto, l'alba si avvicina."
  },
  AvgDialog_18901_Content_20 = {
    Text = "Innumerevoli formiche convergono in un branco denso e irrequieto."
  },
  AvgDialog_18901_Content_21 = {
    Text = "Si sollevano, si radunano, vorticano, fondendosi in un abisso nero come la pece."
  },
  AvgDialog_18901_Content_3 = {
    Text = [[
Ogier resta indietro per occuparsi di Sarah.
Tu e Ramona seguite Jenkin nel seminterrato del "Fantasma della Workhouse".]]
  },
  AvgDialog_18901_Content_4 = {
    Text = "Silenzio, prima che Sarah senta.\nManderà i suoi scagnozzi a cercarci."
  },
  AvgDialog_18901_Content_5 = {
    Text = "Ogier tiene d'occhio i movimenti di Sarah. Con lui lì, staremo bene.\nRaccontami di nuovo cosa hai scoperto nell'ufficio di Sarah l'ultima volta."
  },
  AvgDialog_18901_Content_6 = {
    Text = "Ugh, quante volte devo ripeterlo?!"
  },
  AvgDialog_18901_Content_7 = {
    Text = "Quella donna orribile vende la gente dell'Ospizio dei Poveri a dottori pazzi per i loro esperimenti! Con quei soldi compra gioielli! Li ho trovati nel suo cassetto!"
  },
  AvgDialog_18901_Content_8 = {
    Text = "Ti ho già mostrato il tesserino da studente del tuo amico. Cos'altro vuoi?"
  },
  AvgDialog_18901_Content_9 = {
    Text = [[
Bene, questa stanza.
L'ultimo che entra chiuda la porta.]]
  },
  AvgDialog_18902_Content_1 = {
    Text = "Arte Melliflua"
  },
  AvgDialog_18902_Content_10 = {
    Text = "Il tuo Avvento non interrompe il suo lavoro. Esamina la Statua, regola la posizione dello scalpello e continua a scolpire."
  },
  AvgDialog_18902_Content_11 = {
    Text = "Quello dev'essere il Fantasma della Workhouse...\nDov'è mia sorella? Dove l'avete nascosta?!"
  },
  AvgDialog_18902_Content_12 = {
    Text = "Il fantasma ti nota, ma non reagisce."
  },
  AvgDialog_18902_Content_13 = {
    Text = "Ramona estrae la sua arma, incrocia il tuo sguardo, poi avanza."
  },
  AvgDialog_18902_Content_14 = {
    Text = "Siate Pazienti, e non disturbate la contemplazione dell'arte..."
  },
  AvgDialog_18902_Content_15 = {
    Text = "Mentre parla, innumerevoli Mostri stridono dalle Ombre del seminterrato, scaraventandosi attraverso corpi contorti per attaccare."
  },
  AvgDialog_18902_Content_2 = {
    Text = "Riuscite finalmente a forzare la porta di ferro del seminterrato. Un aroma dolciastro di sciroppo, opprimente e denso, vi assale immediatamente i sensi."
  },
  AvgDialog_18902_Content_3 = {
    Text = "Più sconvolgente del fetore è la scena orrifica all'interno: diversi corpi umani, ricoperti di sciroppo, giacciono sparsi disordinatamente sul pavimento."
  },
  AvgDialog_18902_Content_4 = {
    Text = "Queste forme distorte, non umane, si contorcono e si dibattono, trascinando dietro di sé scie disordinate di sciroppo."
  },
  AvgDialog_18902_Content_5 = {
    Text = "Fitti Branchi di formiche strisciano tutt'intorno, sorseggiando avidamente e trasportando sciroppo con le antenne, come se si trovassero dinanzi al più prezioso Tesoro segreto del mondo."
  },
  AvgDialog_18902_Content_6 = {
    Text = "Eppure queste non sono la vera sorpresa."
  },
  AvgDialog_18902_Content_7 = {
    Text = "Diverse Statue bruno-rossastre sono esposte in bella mostra. Ciascuna aggraziata, con un'Espressione stanca. Un solo sguardo evoca reverenza e sacralità."
  },
  AvgDialog_18902_Content_8 = {
    Text = "Tra loro siede il Fantasma dell'Ospizio."
  },
  AvgDialog_18902_Content_9 = {
    Text = "È chiaramente il Fantasma — il suo corpo color Pietra regge con leggerezza uno scalpello, incidendo Espressioni terrorizzate sulle Statue con raschiature da gelare il sangue."
  },
  AvgDialog_18903_Content_1 = {
    Text = "Pericolo Interiore"
  },
  AvgDialog_18903_Content_2 = {
    Text = "Clang, clang..."
  },
  AvgDialog_18903_Content_3 = {
    Text = "Ti rendi conto che stai sognando."
  },
  AvgDialog_18903_Content_4 = {
    Text = "Qualcuno si avvicina, calpestando i tubi delle fognature."
  },
  AvgDialog_18903_Content_5 = {
    Text = [[
Nella confusione, una figura familiare corre verso di te.
Ti afferra la mano e tira con urgenza, chiamandoti.]]
  },
  AvgDialog_18903_Content_6 = {
    Text = "Corri, Jenkin, corri!"
  },
  AvgDialog_18903_Content_7 = {
    Text = "Alle tue spalle, innumerevoli Mostri neri e viscosi ti danno l'Inseguimento."
  },
  AvgDialog_18904_Content_1 = {Text = "%player%!"},
  AvgDialog_18904_Content_10 = {
    Text = "Signorina Sarah, ho tanta paura, la prego... la prego, non se ne vada..."
  },
  AvgDialog_18904_Content_11 = {
    Text = "Signorina Sarah..."
  },
  AvgDialog_18904_Content_12 = {
    Text = "Che succede, Aigis?"
  },
  AvgDialog_18904_Content_13 = {
    Text = "Signorina Sarah, potrebbe cantare di nuovo quella canzone, solo un'ultima volta?\nIntendo, se non è troppo disturbo..."
  },
  AvgDialog_18904_Content_14 = {
    Text = "Ascolta, cara Aigis: sei la bambina più educata e giudiziosa dell'intero Ospizio dei Poveri. Tutti ti vogliono bene."
  },
  AvgDialog_18904_Content_15 = {
    Text = "Non devi stare sempre così attenta. Va bene essere un po' capricciosa ogni tanto, capito?"
  },
  AvgDialog_18904_Content_16 = {
    Text = "Allora io... voglio sentire la signorina Sarah cantare ancora la filastrocca."
  },
  AvgDialog_18904_Content_17 = {
    Text = [[
Nessun problema.
<Italic:Il gatto tigrato del vecchio Charlie, grasso e caro...>]]
  },
  AvgDialog_18904_Content_18 = {
    Text = "Apri improvvisamente gli occhi su un mondo reale vibrante di vita."
  },
  AvgDialog_18904_Content_19 = {
    Text = "%player%, stai bene?"
  },
  AvgDialog_18904_Content_2 = {
    Text = "Mentre Ramona tiene a bada Sarah, ti concentri rapidamente e ti immergi nello spazio nero — quello che ti sta diventando familiare."
  },
  AvgDialog_18904_Content_20 = {
    Text = "Annuisci nonostante il capogiro. Con la coda dell'occhio, scorgi una figura bianca.\nAigis ti ha superato e si è gettata nella mischia."
  },
  AvgDialog_18904_Content_21 = {
    Text = "Aigis, torna indietro! È troppo pericoloso!"
  },
  AvgDialog_18904_Content_22 = {
    Text = [[
Aigis fissa con sguardo vuoto Sarah a terra.
La melma continua a sgorgare dalla ferita aperta, formando un rivolo nero.]]
  },
  AvgDialog_18904_Content_23 = {
    Text = [[
Poi avanza nella pozza nera come pece e si siede nella melma,
lasciando che Sarah si sdrai sulle sue ginocchia e accarezzandole la schiena con destrezza.]]
  },
  AvgDialog_18904_Content_24 = {
    Text = "Proprio come faceva la direttrice Sarah quando la metteva a dormire."
  },
  AvgDialog_18904_Content_25 = {
    Text = "Signorina Sarah... Va tutto bene, va tutto bene... Era solo un Incubo..."
  },
  AvgDialog_18904_Content_26 = {
    Text = "Il debole bagliore nei suoi occhi perfora la benda per un istante fugace. Senza lo shock della gnosi, potresti scambiarlo per un pianto trattenuto."
  },
  AvgDialog_18904_Content_27 = {
    Text = "Il volto frammentato di Sarah trema inquieto. Dopo che la luce tenue l'attraversa, giace immobile come in un sonno profondo."
  },
  AvgDialog_18904_Content_28 = {
    Text = "La signorina Sarah non dorme bene da molto tempo."
  },
  AvgDialog_18904_Content_29 = {
    Text = "È sempre stata in movimento, incontrando ricchi lord e dame al castello, solo per tenere in piedi l'Ospizio dei Poveri. Non aveva nemmeno il tempo di mangiare o riposare."
  },
  AvgDialog_18904_Content_3 = {
    Text = "La Chiave d'Argento vibra intensamente. L'Oscurità davanti a te si trasforma, schiarendosi dai bordi della tua Visuale."
  },
  AvgDialog_18904_Content_30 = {
    Text = "Quando tornava la sera, accendeva una candela nell'ufficio e continuava a fare calcoli, cercando di far quadrare i conti con le poche elemosine che la nobiltà concedeva."
  },
  AvgDialog_18904_Content_31 = {
    Text = "Cerca di capire quanto possano valere i gioielli che quelle signore le hanno dato."
  },
  AvgDialog_18904_Content_32 = {
    Text = [[
Tutti ridevano di lei e dicevano cose cattive, ma la signorina Sarah non si arrabbia mai.
Anzi, consolava me e cantava per noi.]]
  },
  AvgDialog_18904_Content_33 = {
    Text = "Ci tratta bene, davvero. Tratta molto bene anche me."
  },
  AvgDialog_18904_Content_34 = {
    Text = "Ero un peso per mia madre, e lei mi ha abbandonata. Il direttore precedente si rifiutò di accogliermi, ma la signorina Sarah disse che avrebbe fatto due lavori pur di portarmi qui."
  },
  AvgDialog_18904_Content_35 = {
    Text = "Da allora, giurai di non essere un peso per la signorina Sarah, ma una bambina utile."
  },
  AvgDialog_18904_Content_36 = {
    Text = "Mi dispiace, signorina Sarah. Ho fatto del mio meglio, ma le cose continuano ad andare storte... Non sono riuscita a proteggere tutti, e non sono riuscita a proteggere te. Mi dispiace."
  },
  AvgDialog_18904_Content_37 = {
    Text = "Aigis sfiora delicatamente la guancia non più umana di Sarah, poi si volta verso di te."
  },
  AvgDialog_18904_Content_38 = {
    Text = "Non stai cercando l'Investigatore <Blue:Sean Anderson>?"
  },
  AvgDialog_18904_Content_39 = {
    Text = "Aigis, tu..."
  },
  AvgDialog_18904_Content_4 = {
    Text = "Signorina Sarah, ho tanta fame."
  },
  AvgDialog_18904_Content_40 = {
    Text = "La bambina forza un sorriso a malapena riconoscibile come gioia."
  },
  AvgDialog_18904_Content_41 = {
    Text = "Lasciate andare la signorina Sarah.\nVi dirò dove si trova."
  },
  AvgDialog_18904_Content_42 = {
    Text = "È proprio qui."
  },
  AvgDialog_18904_Content_43 = {
    Text = "Aigis rimuove lentamente la sua benda sull'occhio, rivelando un occhio pallido color pietra."
  },
  AvgDialog_18904_Content_44 = {
    Text = "<Red:Nel mio occhio.>"
  },
  AvgDialog_18904_Content_5 = {
    Text = "Mi rammarico di doverle dire questo, ma non possiamo più continuare a finanziarla, signorina Sarah."
  },
  AvgDialog_18904_Content_6 = {
    Text = "Signorina Sarah, ho fatto arrabbiare la mamma con me?"
  },
  AvgDialog_18904_Content_7 = {
    Text = "Luci bianche e nere lampeggiano come più film proiettati su un unico schermo. Non riesci a distinguere i dettagli, per quanto ti sforzi."
  },
  AvgDialog_18904_Content_8 = {
    Text = "Signorina Sarah, la mia mamma dice che sono inutile... Posso davvero aiutarla?"
  },
  AvgDialog_18904_Content_9 = {
    Text = "Signorina Sarah, la mamma mi ha buttata fuori... Lei... lei mi butterà fuori anche lei?"
  },
  AvgDialog_18905_Content_1 = {
    Text = "Peso della Coscienza"
  },
  AvgDialog_18905_Content_10 = {
    Text = "Smettila di prenderci in giro! Sappiamo dei tuoi affari con quel dottore malvagio! Ridammi mia sorella!"
  },
  AvgDialog_18905_Content_11 = {
    Text = "Io non ho... e questi..."
  },
  AvgDialog_18905_Content_12 = {
    Text = "Sarah lancia un'occhiata a quelle creature — non sapendo se possano ancora essere chiamate umane — e prosegue a fatica."
  },
  AvgDialog_18905_Content_13 = {
    Text = "Davvero non lo so!"
  },
  AvgDialog_18905_Content_14 = {
    Text = "Abbiamo visto il vostro grosso registro!"
  },
  AvgDialog_18905_Content_15 = {Text = "...?"},
  AvgDialog_18905_Content_16 = {
    Text = "Raccogli il registro, lo apri e fai cenno a Sarah."
  },
  AvgDialog_18905_Content_17 = {
    Text = "Mac, maschio, 5 anni, 10 Fiorini; Diana, femmina, 23 anni, 5 Fiorini; Aigis... femmina, 8 anni, 40 Fiorini."
  },
  AvgDialog_18905_Content_18 = {
    Text = "...Devo continuare?"
  },
  AvgDialog_18905_Content_19 = {
    Text = "No, non è così. Io—"
  },
  AvgDialog_18905_Content_2 = {
    Text = "Passi affrettati risuonano. Sarah appare, il volto colmo di rabbia, seguita da un'Aigis preoccupata e da un Ogier risoluto."
  },
  AvgDialog_18905_Content_20 = {
    Text = "Niente scuse! Stai usando la gente dell'Ospizio dei Poveri per gli esperimenti di quel dottore folle e compri gioielli con il denaro!"
  },
  AvgDialog_18905_Content_21 = {
    Text = "Aigis, sei stata alle cure. Sai che il denaro era—"
  },
  AvgDialog_18905_Content_22 = {
    Text = "Sì... il laboratorio fornisce 5 Fiorini a persona come sussidio alimentare durante le sedute di cura, come concordato."
  },
  AvgDialog_18905_Content_23 = {
    Text = "La signorina Sarah ha usato tutto quel denaro per comprare cibo per tutti."
  },
  AvgDialog_18905_Content_24 = {
    Text = "Non ho tenuto un solo centesimo di quel denaro! Quanto ai gioielli che ha menzionato, sono pure assurdità. La prego, {Male=Signor,Female=Signora} Ashe, mi creda!"
  },
  AvgDialog_18905_Content_25 = {
    Text = "Basta con le menzogne!"
  },
  AvgDialog_18905_Content_26 = {
    Text = "Jenkin estrae due anelli d'argento dal fondo della sua bisaccia."
  },
  AvgDialog_18905_Content_27 = {
    Text = "Se non sei stata tu, chi li ha messi nel cassetto dell'ufficio? Pensi che siano apparsi lì per magia?"
  },
  AvgDialog_18905_Content_28 = {
    Text = "Come hai potuto prenderli? Restituiscili! Sono doni di un altro benefattore!"
  },
  AvgDialog_18905_Content_29 = {
    Text = "Mi creda, li conservo per le emergenze dell'Ospizio dei Poveri! C-Come potrei mai fare del male ai fanciulli qui per queste cose?"
  },
  AvgDialog_18905_Content_3 = {
    Text = "Come avete potuto—"
  },
  AvgDialog_18905_Content_30 = {
    Text = "Se non hai nulla a che fare con tutto questo, allora come spieghi questi... fanciulli?"
  },
  AvgDialog_18905_Content_31 = {
    Text = "Ramona indica il mostro strisciante a terra."
  },
  AvgDialog_18905_Content_32 = {
    Text = [[
...Bambini?
Vuoi dire...]]
  },
  AvgDialog_18905_Content_33 = {
    Text = "Realizzando qualcosa, Sarah volta rigidamente la testa per esaminare da vicino i mostri."
  },
  AvgDialog_18905_Content_34 = {
    Text = "Sono questi gli operai e i fanciulli scomparsi dall'Ospizio dei Poveri?"
  },
  AvgDialog_18905_Content_35 = {
    Text = "No, non può essere..."
  },
  AvgDialog_18905_Content_36 = {
    Text = "Che baccano."
  },
  AvgDialog_18905_Content_37 = {
    Text = [[
Smettete di guardare quelle imperfezioni.
Ora, ammirate la vera bellezza.]]
  },
  AvgDialog_18905_Content_38 = {
    Text = "Spinge la statua appena completata davanti a Sarah."
  },
  AvgDialog_18905_Content_39 = {
    Text = "È la statua di un fanciullo, i suoi lineamenti realistici preservati sotto un guscio torbido di zucchero."
  },
  AvgDialog_18905_Content_4 = {Text = "Ah—"},
  AvgDialog_18905_Content_40 = {
    Text = "Quello è... Quello è... Il piccolo... Willy..."
  },
  AvgDialog_18905_Content_41 = {
    Text = "Il bulbo oculare della statua sussulta all'improvviso."
  },
  AvgDialog_18905_Content_42 = {
    Text = "Iih—Iiih—<Shake:AAAAHHHHHHH—>"
  },
  AvgDialog_18905_Content_43 = {
    Text = "Sarah emette un urlo malato."
  },
  AvgDialog_18905_Content_44 = {
    Text = "Si rannicchia, stringendosi la testa tra le braccia. I suoi sussurri di pianto si fanno rochi e caotici, fino a diventare indistinguibili."
  },
  AvgDialog_18905_Content_45 = {
    Text = "<Small:Sono inutile, sono disgustosa, non sono una buona direttrice, non riesco a proteggere nessuno, non riesco a proteggere i bambini...>"
  },
  AvgDialog_18905_Content_46 = {
    Text = "Signorina Sarah, la prego... Lo capiamo tutti. Ha fatto del suo meglio."
  },
  AvgDialog_18905_Content_47 = {
    Text = "Scusami, piccola Aigis; scusami, piccola Lucy; scusami, Jenkin, Henry, Diana..."
  },
  AvgDialog_18905_Content_48 = {
    Text = "Sarah alza il capo, i lineamenti completamente stravolti. I Suoi Occhi e le labbra si contorcono in spasmi disumani, simili a una Danza."
  },
  AvgDialog_18905_Content_49 = {
    Text = "Signorina Sarah...?"
  },
  AvgDialog_18905_Content_5 = {
    Text = "Prima che possa finire, la figura di zucchero contorta a terra emette un urlo terrificante."
  },
  AvgDialog_18905_Content_50 = {
    Text = [[
Come sommersi sott'acqua, l'ambiente sprofonda in un freddo silenzio.
Una pressione invisibile colpisce inaspettatamente, facendoti boccheggiare mentre realizzi che qualcosa non va.]]
  },
  AvgDialog_18905_Content_51 = {
    Text = "No! Ramona! Porta tutti gli altri fuori di qui!"
  },
  AvgDialog_18905_Content_52 = {
    Text = [[
Troppo tardi.
La testa della giovane direttrice si apre come un fiore, spruzzando melma nera sul pavimento.]]
  },
  AvgDialog_18905_Content_53 = {
    Text = "S-signorina Sarah!!"
  },
  AvgDialog_18905_Content_54 = {
    Text = "Emette uno stridio acutissimo. I corpi contorti intorno a lei rispondono con Ululato lupoide, mutando rapidamente in Mostri infetti dalla Dissoluzione."
  },
  AvgDialog_18905_Content_6 = {
    Text = [[
"Come avete potuto?" Questo dovremmo dirlo noi.
Non siete stata voi a nascondere il Fantasma della Workhouse in questo seminterrato? Ci ha raccontato tutto.]]
  },
  AvgDialog_18905_Content_7 = {
    Text = "Come attratta dall'urlo di Sarah, l'umanoide semi-zuccherificato si dimena e striscia verso di lei."
  },
  AvgDialog_18905_Content_8 = {
    Text = "Ascoltate, signorina Sarah, non potete più nasconderlo."
  },
  AvgDialog_18905_Content_9 = {
    Text = "Vi preghiamo di comunicarci le informazioni di contatto dell'Associazione degli Scultori, nonché il luogo in cui si trova l'Investigatore <Blue:Sean Anderson>."
  },
  AvgDialog_18906_Content_1 = {
    Text = "Le Apparenze Ingannano"
  },
  AvgDialog_18906_Content_10 = {Text = "Ehm..."},
  AvgDialog_18906_Content_11 = {
    Text = "Te l'ho detto, oggi siamo chiusi. Devo andare dentro a cercare mia sorella."
  },
  AvgDialog_18906_Content_12 = {
    Text = "Il ragazzino non lo degna nemmeno di uno sguardo."
  },
  AvgDialog_18906_Content_13 = {
    Text = [[
No, volevo solo chiedere...
Conosce la strada per la Workhouse di Lilian?]]
  },
  AvgDialog_18906_Content_14 = {Text = "..."},
  AvgDialog_18906_Content_15 = {
    Text = "<Small:Che zoticone...>"
  },
  AvgDialog_18906_Content_16 = {Text = "...?"},
  AvgDialog_18906_Content_17 = {
    Text = "Scusa, non ho capito. Potresti ripetere?"
  },
  AvgDialog_18906_Content_18 = {
    Text = "Da questa parte, ti faccio vedere."
  },
  AvgDialog_18906_Content_19 = {
    Text = "Guarda, proprio dietro quell'angolo. Vicinissimo."
  },
  AvgDialog_18906_Content_2 = {
    Text = "Un'umidità densa e un tanfo di marcio ti soffocano nell'istante in cui scendi dall'auto."
  },
  AvgDialog_18906_Content_20 = {
    Text = "Oh! Grazie mille."
  },
  AvgDialog_18906_Content_21 = {
    Text = "No, grazie a TE, piuttosto."
  },
  AvgDialog_18906_Content_22 = {
    Text = "Ringraziarmi?"
  },
  AvgDialog_18906_Content_23 = {
    Text = "Quando Ogier si volta, le scale sono vuote—\nla figura incappucciata ora si nasconde in fondo alla strada, stringendo il portafoglio rubato."
  },
  AvgDialog_18906_Content_24 = {
    Text = "Ah, il mio portafoglio—"
  },
  AvgDialog_18906_Content_25 = {
    Text = "Curiosità su Londinium n° 2: il saluto più famigerato del Distretto Est prevede portafogli che svaniscono senza preavviso."
  },
  AvgDialog_18906_Content_26 = {
    Text = [[
Sembra che dobbiamo aiutare Ogier.
Andiamo, Custode.]]
  },
  AvgDialog_18906_Content_3 = {
    Text = "Un capogiro ti colpisce, le orecchie che fischiano.\nImmagini sfocate lampeggiano—le hai già viste prima?"
  },
  AvgDialog_18906_Content_4 = {
    Text = "È un'Illusione, o è un frammento della tua Memoria perduta?"
  },
  AvgDialog_18906_Content_5 = {
    Text = "Nessun cartello stradale né indicazione... e non corrisponde alla mappa..."
  },
  AvgDialog_18906_Content_6 = {
    Text = "Curiosità su Londinium n. 1: la nebbia perenne del Distretto Est e i vicoli contorti disorientano regolarmente i visitatori."
  },
  AvgDialog_18906_Content_7 = {
    Text = "Chiederò indicazioni."
  },
  AvgDialog_18906_Content_8 = {
    Text = "Un ragazzino con un cappuccio lacero ozia a bordo strada, rimpicciolito dal suo mantello troppo grande."
  },
  AvgDialog_18906_Content_9 = {
    Text = "Ogier si avvicina al ragazzino e accenna un lieve inchino."
  },
  AvgDialog_18907_Content_1 = {Text = "Morbo"},
  AvgDialog_18907_Content_10 = {
    Text = "Jenkin! Come hai potuto... Non possiamo portare i benefattori nel <Blue:reparto>, ricordi? Se lo vedono, allora..."
  },
  AvgDialog_18907_Content_11 = {
    Text = "Fai l'occhiolino a Ramona, e lei si avvicina ad Aigis, chiedendole gentilmente."
  },
  AvgDialog_18907_Content_12 = {
    Text = "Aigis, potresti dirci perché non puoi permettere ai benefattori di entrare nel reparto?"
  },
  AvgDialog_18907_Content_13 = {
    Text = "Ehm... Io... Cioè, Loro... sono molto deboli, quindi..."
  },
  AvgDialog_18907_Content_14 = {
    Text = "Aigis esita, lanciando un'occhiata ai pazienti dietro di lei e al vostro seguito ben vestito, incerta su come rispondere."
  },
  AvgDialog_18907_Content_15 = {
    Text = "Cogliendo l'attimo, tu e Ogier vi avvicinate all'anziano sul letto."
  },
  AvgDialog_18907_Content_16 = {
    Text = "Il vecchio è legato mani e piedi con rozze strisce di stoffa, assicurato al letto. Il suo corpo porta strane ferite simili a suture contorte, carne non rimarginata da cui trasuda un fluido scuro e viscoso."
  },
  AvgDialog_18907_Content_17 = {
    Text = "Aigis, questa ispezione determinerà se forniremo supporto finanziario.\nSicuramente capisci che nessun mecenate vuole che i propri soldi vengano sprecati in frodi."
  },
  AvgDialog_18907_Content_18 = {
    Text = "Non opporre resistenza. Non ti faranno del male."
  },
  AvgDialog_18907_Content_19 = {
    Text = "Aigis si calma dopo una breve pausa. Inspira profondamente e risponde con una voce flebile come il ronzio di una zanzara."
  },
  AvgDialog_18907_Content_2 = {
    Text = "Jenkin vi conduce attraverso il cortile sul retro, indicando una piccola capanna fatiscente nell'angolo."
  },
  AvgDialog_18907_Content_20 = {
    Text = "<Small:La signorina Sarah ha detto che se i benefattori vedono questi pazienti, penseranno che nessuna somma di denaro potrà fare la differenza...>"
  },
  AvgDialog_18907_Content_21 = {
    Text = "Non avrei dovuto dare retta a quella donna! Questi benefattori ci aiuteranno con il <Yellow:Fantasma dell'Ospizio>. Anche loro stanno cercando qualcuno — troveranno la sorell..."
  },
  AvgDialog_18907_Content_22 = {
    Text = "Il reparto è troppo pericoloso!"
  },
  AvgDialog_18907_Content_23 = {
    Text = "Il suo tono concitato si interrompe bruscamente. Lancia un'occhiata ansiosa al vecchio privo di sensi, poi trascina Jenkin lontano dal capezzale."
  },
  AvgDialog_18907_Content_24 = {
    Text = "E se tu e gli sponsor veniste contagiati..."
  },
  AvgDialog_18907_Content_25 = {
    Text = "Aigis stringe il suo orsacchiotto, ribattendo nervosamente a Jenkin. Le maniche bianche le scivolano giù, rivelando orribili segni di sutura neri e due solchi rossi e gonfi."
  },
  AvgDialog_18907_Content_26 = {
    Text = "Il suo braccio esile è deturpato da una fessura simile a un centopiedi gigante, i cui bordi trasudano melma nera, evocando terrore."
  },
  AvgDialog_18907_Content_27 = {
    Text = "Aigis, quella Ferita..."
  },
  AvgDialog_18907_Content_28 = {
    Text = "Aigis si affretta a richiudere le maniche, scuotendo la testa per evitare lo Sguardo di Ramona."
  },
  AvgDialog_18907_Content_29 = {
    Text = "È, è stato... quando sono caduta accidentalmente dalle scale."
  },
  AvgDialog_18907_Content_3 = {
    Text = [[
Attraverso la finestra, vedi Aigis indaffarata.
Porta una bacinella di metallo, spostando frettolosamente bende sporche dal comodino a un mucchio di biancheria sporca.]]
  },
  AvgDialog_18907_Content_30 = {
    Text = "Queste suture non corrispondono a tipiche lesioni da abrasione."
  },
  AvgDialog_18907_Content_31 = {
    Text = "Vedi, loro possono \"vedere\".\nDì loro tutto. Sono la nostra ultima speranza."
  },
  AvgDialog_18907_Content_32 = {
    Text = "<Small:Saranno in pericolo. Non possiamo...>"
  },
  AvgDialog_18907_Content_33 = {
    Text = "Ascolta, Aigis. La piena trasparenza è essenziale per determinare l'assistenza appropriata."
  },
  AvgDialog_18907_Content_34 = {
    Text = "Accanto a te, il vecchio emette un gorgoglio dalla gola. Il suo braccio emaciato scatta all'improvviso, strappando il panno di Vincolo—"
  },
  AvgDialog_18907_Content_35 = {
    Text = "Custode, attento!"
  },
  AvgDialog_18907_Content_4 = {
    Text = "Hmm? Ti serve qualcosa?"
  },
  AvgDialog_18907_Content_5 = {
    Text = [[
Sembra sentire il richiamo di qualcuno. Posa la bacinella, si china e si avvicina al capezzale.
Dalla tua angolazione, solo la sua voce dolce resta udibile.]]
  },
  AvgDialog_18907_Content_6 = {
    Text = "Nonno Robert, per favore, resta sdraiato. Ti porto io l'acqua."
  },
  AvgDialog_18907_Content_7 = {
    Text = "Non dire così. Guarirai sicuramente.\nPoi potremo andare al Parco Drell a dare da mangiare ai piccioni insieme."
  },
  AvgDialog_18907_Content_8 = {
    Text = [[
"Bang!" Jenkin spalanca la porta della cabina.
Aigis sussulta, quasi rovesciando l'acqua sul paziente nel panico.]]
  },
  AvgDialog_18907_Content_9 = {
    Text = "Guarda — i <Yellow:pazzi malati>."
  },
  AvgDialog_18908_Content_1 = {
    Text = "Etichetta Inespressa"
  },
  AvgDialog_18908_Content_10 = {
    Text = "Il volto di Aigis impallidisce per un istante alla vista delle caramelle, ma le accetta comunque con cura."
  },
  AvgDialog_18908_Content_11 = {
    Text = "Ricordi quando ci siamo incontrati per la prima volta?"
  },
  AvgDialog_18908_Content_12 = {
    Text = "Hmm, non lo dimenticherò mai."
  },
  AvgDialog_18908_Content_13 = {
    Text = [[
10 giorni fa, Distretto Est, Londinium
La casa di lavoro di Lilian]]
  },
  AvgDialog_18908_Content_14 = {
    Text = "Il Distretto Est avvolto dall'Oscurità, notte fonda. Lampioni, luce lunare, nulla penetrava la nebbia, lasciando solo ombre sfocate ondeggiare nell'aria."
  },
  AvgDialog_18908_Content_15 = {
    Text = "La ragazza in bianco, stretta tra senso di colpa e paura, corse attraverso il cortile buio e vuoto della casa di lavoro...\nFinché non urtò qualcosa nascosto nell'ombra e gridò di dolore."
  },
  AvgDialog_18908_Content_16 = {Text = "Ahi!"},
  AvgDialog_18908_Content_17 = {Text = "Ahi!"},
  AvgDialog_18908_Content_18 = {
    Text = "T-Tu non sei Mac o Lucy! Chi sei...?!"
  },
  AvgDialog_18908_Content_19 = {
    Text = "Dovrei essere io a chiedere chi sei TU! A sgattaiolare di notte spaventando la gente."
  },
  AvgDialog_18908_Content_2 = {
    Text = "Ti sei fatto male là dentro?"
  },
  AvgDialog_18908_Content_20 = {
    Text = "Scusa... Pensavo fosse..."
  },
  AvgDialog_18908_Content_21 = {
    Text = "Fosse cosa?"
  },
  AvgDialog_18908_Content_22 = {
    Text = "Era... il fantasma... Sì, pensavo fosse il <Red:Fantasma dell'Ospizio>..."
  },
  AvgDialog_18908_Content_23 = {
    Text = "Fantasma? Sciocchezze. Ma sarò sincero con te, non vengo da questo posto di merda.\nSono Jenkin, e questo è Brown."
  },
  AvgDialog_18908_Content_24 = {Text = "Squeak!"},
  AvgDialog_18908_Content_25 = {
    Text = "Sono qui per cercare mia sorella. Si chiama <Blue:Mason>. È scomparsa da queste parti due settimane fa.\nL'hai vista?"
  },
  AvgDialog_18908_Content_26 = {
    Text = "Ci sono stati molti nuovi arrivati all'ospizio, e non li ho riconosciuti tutti..."
  },
  AvgDialog_18908_Content_27 = {
    Text = "Pensa bene. Alta più o meno così, capelli lunghi, <Yellow:nastro rosso con fibbia quadrata a M>."
  },
  AvgDialog_18908_Content_28 = {
    Text = "Viene per le cure a volte. L'ultima volta non è più tornata a casa. La tenete qui a lavorare?"
  },
  AvgDialog_18908_Content_29 = {
    Text = [[
<Shake:P-paziente?>
M-mi scusi... non ho visto nessuna giovane paziente donna...]]
  },
  AvgDialog_18908_Content_3 = {
    Text = "Sto bene..."
  },
  AvgDialog_18908_Content_30 = {
    Text = "Tch, come vuoi. Non mi aspettavo granché comunque.\nMa per poco non mi facevi beccare—è colpa tua."
  },
  AvgDialog_18908_Content_31 = {
    Text = "Allora t-ti porto alla mia base segreta! La sorvegliante non entra mai nella torre dell'orologio, non ti troverà lì."
  },
  AvgDialog_18908_Content_32 = {
    Text = "È stata una fortuna imbattermi in te, Aigis.\nAltrimenti mi avrebbero trascinato fuori per il cappuccio."
  },
  AvgDialog_18908_Content_33 = {
    Text = "Non dire così. Qui sono tutti gentilissimi. Sono solo turbati dalle recenti disgrazie..."
  },
  AvgDialog_18908_Content_34 = {Text = "Aigis."},
  AvgDialog_18908_Content_35 = {Text = "Hm?"},
  AvgDialog_18908_Content_36 = {
    Text = "So che sei legata alla gente dell'ospizio... ma pensavo fossimo amiche. Lo siamo?"
  },
  AvgDialog_18908_Content_37 = {
    Text = "Certo! Mi piace davvero, davvero tanto passare il tempo con te, Jenkin, proprio così—mangiando caramelle e chiacchierando."
  },
  AvgDialog_18908_Content_38 = {
    Text = "Allora perché menti alla tua amica?\nDimmi la verità, Aigis."
  },
  AvgDialog_18908_Content_39 = {
    Text = "Io... non capisco cosa stai dicendo..."
  },
  AvgDialog_18908_Content_4 = {
    Text = "...Sei arrabbiato con me? Per aver portato quelle persone?"
  },
  AvgDialog_18908_Content_40 = {
    Text = "Ho trovato il <Blue:registro> e il <Blue:tesserino studentesco> nell'ufficio di quella donna. So che vende le persone a dottori folli!"
  },
  AvgDialog_18908_Content_41 = {
    Text = "Lei si fida di te più di tutti, ti lascia persino gestire i pazienti. TU SAI qualcosa. Puoi dirmelo, per favore?"
  },
  AvgDialog_18908_Content_42 = {
    Text = "Io, io, <Small:non lo so...>"
  },
  AvgDialog_18908_Content_43 = {
    Text = "La ragazza mormora, la voce si affievolisce.\nIl suo viso è pallido, come se soffrisse un dolore immenso."
  },
  AvgDialog_18908_Content_44 = {
    Text = "Mythag eccelle nello svelare segreti; presto scopriranno la verità."
  },
  AvgDialog_18908_Content_45 = {
    Text = "Non puoi vivere in catene per sempre."
  },
  AvgDialog_18908_Content_46 = {
    Text = "Jenkin, se ciò che è perduto resta perduto... la \"verità\" conta ancora?"
  },
  AvgDialog_18908_Content_47 = {
    Text = "Certo che conta! Niente conta più di ritrovare mia sorella."
  },
  AvgDialog_18908_Content_48 = {
    Text = "So che hai paura di quella donna, perché continui a difenderla? Sta vendendo i lavoranti E nascondendo il <Yellow:Fantasma dell'Ospizio>."
  },
  AvgDialog_18908_Content_49 = {
    Text = "I-il Fantasma dell'Ospizio?"
  },
  AvgDialog_18908_Content_5 = {Text = "No!"},
  AvgDialog_18908_Content_50 = {
    Text = "Sì, è la leggenda che mi hai raccontato.\n<Yellow:Non vagare nelle notti di nebbia, o verrai portato via da un fantasma con un coltello>."
  },
  AvgDialog_18908_Content_51 = {
    Text = "Q-Quello me lo sono inventato... Di notte è troppo pericoloso. Non volevo che andassi in giro."
  },
  AvgDialog_18908_Content_52 = {
    Text = "Smettila di trovare scuse per Sarah! Ho già trovato il <Yellow:seminterrato col fantasma> e ho sentito il <Yellow:suono di un coltello>.\nMia sorella è lì dentro?"
  },
  AvgDialog_18908_Content_53 = {
    Text = "Non appena la parola \"seminterrato\" lascia le labbra di Jenkin, l'ultimo residuo di colore svanisce dal volto di Aigis."
  },
  AvgDialog_18908_Content_54 = {
    Text = "Non avere paura, Aigis, perché Egli percepirà la crepa nel tuo cuore."
  },
  AvgDialog_18908_Content_55 = {
    Text = "Segui la guida d'Argento, e la sua luce ti mostrerà la via."
  },
  AvgDialog_18908_Content_56 = {
    Text = "Jenkin, mi dispiace, non posso..."
  },
  AvgDialog_18908_Content_57 = {
    Text = "Con le lacrime agli occhi, Aigis lancia uno sguardo a Jenkin, poi si volta e risale la torre dell'orologio, precipitandosi giù per le scale senza esitazione."
  },
  AvgDialog_18908_Content_58 = {
    Text = "Aigis! Dove stai andando!"
  },
  AvgDialog_18908_Content_59 = {
    Text = "Prima che se ne accorga, la nebbia appare nella casa di lavoro.\nArriva così all'improvviso, avvolgendo tutto nell'umidità e rendendo ogni cosa indistinta."
  },
  AvgDialog_18908_Content_6 = {
    Text = "Non volevo che tu... venissi contagiato..."
  },
  AvgDialog_18908_Content_60 = {
    Text = "Aigis! Dannazione, com'è entrata questa nebbia?!"
  },
  AvgDialog_18908_Content_61 = {
    Text = "Dalla nebbia lontana giunge il suono di carne che si gonfia e un canto flebile, intriso di foschia."
  },
  AvgDialog_18908_Content_62 = {
    Text = "<Italic:Il soriano del vecchio Charlie, grasso e caro...>"
  },
  AvgDialog_18908_Content_63 = {
    Text = "Jenkin lucida la sua lanterna, il cui debole bagliore è fioco nella nebbia densa."
  },
  AvgDialog_18908_Content_64 = {
    Text = "Passi lontani echeggiano nel corridoio silenzioso, quasi laceranti."
  },
  AvgDialog_18908_Content_65 = {
    Text = "C-chi va là?\nFatti vedere! Sono armato, ti avverto!"
  },
  AvgDialog_18908_Content_66 = {
    Text = "L'aria non circola nel corridoio, eppure la fiamma tremola come soffiata dal vento."
  },
  AvgDialog_18908_Content_67 = {
    Text = "I passi si avvicinano. Gli artigli di Brown affondano nella spalla di Jenkin, i denti scoperti e un sibilo acuto."
  },
  AvgDialog_18908_Content_68 = {
    Text = "Come innescati dalla voce di Brown, i passi improvvisamente accelerano, dirigendosi dritti verso Jenkin."
  },
  AvgDialog_18908_Content_69 = {
    Text = "Un'ombra densa inghiotte la luce fioca. La bambina chiude gli occhi e urla con tutto il fiato, ma sente solo la nebbia investirle il volto."
  },
  AvgDialog_18908_Content_7 = {Text = "Bene."},
  AvgDialog_18908_Content_70 = {
    Text = "Una mano emerge dall'oscurità, posandosi con precisione sulla spalla di Jenkin."
  },
  AvgDialog_18908_Content_71 = {
    Text = "Cosa c'è che non va? Perché sei così p-pallida?"
  },
  AvgDialog_18908_Content_72 = {
    Text = "R-Rogers? Hai visto Aigis?"
  },
  AvgDialog_18908_Content_73 = {
    Text = "Non preoccuparti, Aigis conosce bene questo ospizio dei poveri. Starà bene."
  },
  AvgDialog_18908_Content_74 = {
    Text = "Capisco. Le notti nebbiose p-possono fare paura."
  },
  AvgDialog_18908_Content_75 = {
    Text = "Rogers spinge la porta aperta, e una luce calda si riversa fuori, dissipando le ombre profonde del corridoio."
  },
  AvgDialog_18908_Content_76 = {
    Text = "Raccoglie una bambola finemente lavorata dal letto e sorride alla bambina."
  },
  AvgDialog_18908_Content_77 = {
    Text = "Che ne dici di un tocco? Ti sentirai molto meglio.\nE <Blue:George> sarà felice."
  },
  AvgDialog_18908_Content_78 = {
    Text = "Gli occhi inorganici della bambola riflettono la luce gialla della lampada, implorando in silenzio: Toccami, ti prego. Basta un solo tocco."
  },
  AvgDialog_18908_Content_79 = {
    Text = "Toccami, e—"
  },
  AvgDialog_18908_Content_8 = {
    Text = "Jenkin apre le mani con fare teatrale, rivelando due piccole caramelle nei palmi."
  },
  AvgDialog_18908_Content_80 = {
    Text = "<Red:diventa il mio fedele compagno.>"
  },
  AvgDialog_18908_Content_81 = {
    Text = "Con uno \"squeak\", il grido di Brown scuote Jenkin dal suo torpore."
  },
  AvgDialog_18908_Content_82 = {
    Text = "No, no grazie! Non ho bisogno di artisti raffinati come voi."
  },
  AvgDialog_18908_Content_83 = {
    Text = "Oh, mio ingenuo topolino. In realtà, la bellezza e l'arte non fanno mai di-distinzione tra ricchi e poveri, nobili e umili.\nRacchiudere la sofferenza nella bellezza è ve-veramente meraviglioso."
  },
  AvgDialog_18908_Content_84 = {
    Text = "Rogers fissa la bambina guardinga e il topolino grigio che fa capolino dal suo cappuccio, gli occhi ardenti di un desiderio irresistibile."
  },
  AvgDialog_18908_Content_85 = {
    Text = "Forse un giorno trasformerò anche voi due in statue di cera.\nChe ne dite di chiamarla \"Brown e Jenkin\"?"
  },
  AvgDialog_18908_Content_9 = {
    Text = "Ecco, una per te e una per me. Così siamo a posto, sì?"
  },
  AvgDialog_18909_Content_1 = {
    Text = "Fantasma Sotterraneo"
  },
  AvgDialog_18909_Content_10 = {
    Text = "Ramona resta composta, recitando le battute provate alla perfezione.\nEppure il viso di Ogier è diventato completamente rosso."
  },
  AvgDialog_18909_Content_11 = {
    Text = "Come ci si aspetta dal giovane erede di Lord Ashe, assumersi responsabilità così importanti a un'età così giovane.\nNella workhouse, abbiamo bambini della sua età a malapena capaci di servire la zuppa..."
  },
  AvgDialog_18909_Content_12 = {
    Text = "P-per favore, non dite così..."
  },
  AvgDialog_18909_Content_13 = {
    Text = "Ramona si schiarisce la gola e cambia rapidamente argomento."
  },
  AvgDialog_18909_Content_14 = {
    Text = [[
Da qui il nostro studio longitudinale sul campo nel Distretto Est.
La Workhouse di Lilian funge da primo sito di ricerca, dove ci aspettiamo piena trasparenza dalla direttrice...]]
  },
  AvgDialog_18909_Content_15 = {
    Text = "Ramona racconta brevemente la violenta esplosione della guardia, omettendo la Dissoluzione."
  },
  AvgDialog_18909_Content_16 = {
    Text = "Ne eravate al corrente, Miss Sarah? Che una delle vostre guardie ci ha appena attaccati?"
  },
  AvgDialog_18909_Content_17 = {
    Text = "Non ci posso credere! Quella guardia, s-sicuramente non è della nostra workhouse.\nNon abbiamo nulla che valga la pena rubare, quindi perché assumere della sicurezza?"
  },
  AvgDialog_18909_Content_18 = {
    Text = "Il suo tono impacciato tradisce la menzogna."
  },
  AvgDialog_18909_Content_19 = {
    Text = "Ma, signorina Sarah..."
  },
  AvgDialog_18909_Content_2 = {
    Text = "Il vostro gruppo entra nell'Ospizio dei Poveri e, in lontananza, scorgete una suora che guida diversi fanciulli e lavoranti, disposti in fila ad attendervi."
  },
  AvgDialog_18909_Content_20 = {
    Text = "Sarah dissuade la ragazza con uno sguardo severo, e la ragazza visibilmente si lascia prendere dal panico."
  },
  AvgDialog_18909_Content_21 = {
    Text = "Silenzio, Aigis. Questa è una faccenda da adulti."
  },
  AvgDialog_18909_Content_22 = {
    Text = "La bambina fissa la sua Doll con le labbra serrate, in silenzio."
  },
  AvgDialog_18909_Content_23 = {
    Text = "...Va bene. Fate portare via il suo corpo. Copritelo con un panno, così i topi non lo rodono."
  },
  AvgDialog_18909_Content_24 = {
    Text = "Poi si volta verso di te."
  },
  AvgDialog_18909_Content_25 = {
    Text = "Vi chiedo perdono. Quando arriverà il dottore, gli chiederò di assistere con la sepoltura."
  },
  AvgDialog_18909_Content_26 = {Text = "Dottore?"},
  AvgDialog_18909_Content_27 = {
    Text = "Ehm, dunque... vedete, qui abbiamo parecchi fanciulli, e grazie alla generosità dei nostri benefattori, siamo riusciti ad assumere alcuni dottori per le visite periodiche."
  },
  AvgDialog_18909_Content_28 = {
    Text = "È ora del prossimo controllo medico."
  },
  AvgDialog_18909_Content_29 = {
    Text = "Qualcuno è appena morto. Non dovremmo chiamare la polizia?"
  },
  AvgDialog_18909_Content_3 = {
    Text = [[
Buongiorno, {Male=Lord,Female=Lady} Ashe, signorina Mary. Sono Sarah, la direttrice qui.
La workhouse richiede molto da noi, e mi scuso per non avervi accolto al cancello.]]
  },
  AvgDialog_18909_Content_30 = {
    Text = "Ahimè... Vedi, questo è il Distretto Est."
  },
  AvgDialog_18909_Content_31 = {
    Text = "Persino durante l'inquietante <Red:caso dello squartatore>, si sono limitati a mandare qualcuno a raccogliere i corpi, senza prendere ulteriori provvedimenti."
  },
  AvgDialog_18909_Content_32 = {
    Text = "Per gente come noi, avere abbastanza cibo nel piatto è tutto ciò che possiamo sperare; non abbiamo il lusso di preoccuparci d'altro."
  },
  AvgDialog_18909_Content_33 = {
    Text = "Detto ciò, Sarah vi conduce all'interno della workhouse.\nDietro di voi, i lavoratori si sono disposti silenziosamente in due file, fiancheggiandovi come sorveglianti... O guardie carcerarie."
  },
  AvgDialog_18909_Content_34 = {
    Text = "Ramona mormora sottovoce."
  },
  AvgDialog_18909_Content_35 = {
    Text = "Londinium, curiosità n° 3 —"
  },
  AvgDialog_18909_Content_36 = {
    Text = "Nel Distretto Est, il valore umano resta inquantificabile, poiché non esiste."
  },
  AvgDialog_18909_Content_37 = {
    Text = [[
Nel corridoio silenzioso, una porta con una targhetta metallica si apre lentamente.
Un topo sguscia attraverso la fessura, si guarda intorno e squittisce due volte nell'ombra.]]
  },
  AvgDialog_18909_Content_38 = {Text = "Squeak!"},
  AvgDialog_18909_Content_39 = {
    Text = "\"Tutto chiaro,\" è esattamente quello che hai detto l'ultima volta! Sarei stato nei guai se non fosse stata Aigis."
  },
  AvgDialog_18909_Content_4 = {
    Text = "Irritata dalla mancanza di risposte, aggrotta le sopracciglia e dà una gomitata a una ragazza distratta.\nLa ragazza sussulta, poi si inchina frettolosamente davanti a tutti voi."
  },
  AvgDialog_18909_Content_40 = {
    Text = "Jenkin sbircia oltre l'angolo, si assicura che il corridoio sia vuoto, poi sguscia attraverso la porta e la richiude alle proprie spalle."
  },
  AvgDialog_18909_Content_41 = {
    Text = "Squeak, squeak squeak!"
  },
  AvgDialog_18909_Content_42 = {
    Text = "Come dici tu, come dici tu. Brown è la più furba!"
  },
  AvgDialog_18909_Content_43 = {
    Text = "Squeak, squeak."
  },
  AvgDialog_18909_Content_44 = {
    Text = [[
Vediamo cosa nasconde quella strega.
Anelli, collane... Sono tutti d'oro?]]
  },
  AvgDialog_18909_Content_45 = {
    Text = "Non voleva nemmeno comprare una caramella ad Aigis, dicendo \"non ci sono soldi,\" mentre accumulava tutto questo bagliore dorato per sé!"
  },
  AvgDialog_18909_Content_46 = {
    Text = [[
Chiave, perfetto. Ora possiamo entrare e uscire facilmente dagli altri posti.
Dovremmo davvero ringraziare quel <Yellow:"sponsor">; ora possiamo indagare su questo posto come si deve.]]
  },
  AvgDialog_18909_Content_47 = {
    Text = "Squeak, squeak."
  },
  AvgDialog_18909_Content_48 = {
    Text = "Calmo, Brown. Abbiamo tempo."
  },
  AvgDialog_18909_Content_49 = {
    Text = "Eh... Questo è... un registro?\nMac, maschio, 5 anni, 10 Fang; Diana, femmina, 23 anni, 5 Fang..."
  },
  AvgDialog_18909_Content_5 = {
    Text = "B-Benvenuto! Abbiamo preparato degli spuntini nella mensa..."
  },
  AvgDialog_18909_Content_50 = {
    Text = "Non è possibile... Stanno vendendo persone in questo Ospizio dei Poveri?!"
  },
  AvgDialog_18909_Content_51 = {Text = "..."},
  AvgDialog_18909_Content_52 = {
    Text = "Squeak, squeak squeak!"
  },
  AvgDialog_18909_Content_53 = {
    Text = "Brown lancia uno strido d'avvertimento mentre la porta di legno geme."
  },
  AvgDialog_18909_Content_54 = {
    Text = "Sarah trova un ufficio vuoto."
  },
  AvgDialog_18909_Content_55 = {
    Text = "Fa scivolare un bigliettino grande quanto un palmo nel cassetto, lo sbatte chiuso e si allontana in fretta."
  },
  AvgDialog_18909_Content_56 = {
    Text = "Squeak, squeak."
  },
  AvgDialog_18909_Content_57 = {
    Text = "Una volta che se n'è andata, Brown schizza fuori dall'ombra del vaso di pianta."
  },
  AvgDialog_18909_Content_58 = {
    Text = "Jenkin avanza furtivamente e forza il cassetto."
  },
  AvgDialog_18909_Content_59 = {
    Text = [[
Tessera studentesca? <Blue:Sean... Anderson>...
Non sono gli stessi segni sul portafoglio elegante di quel ragazzino azzimato?]]
  },
  AvgDialog_18909_Content_6 = {
    Text = "E questo è...?"
  },
  AvgDialog_18909_Content_60 = {
    Text = "Squeak, squeak squeak!"
  },
  AvgDialog_18909_Content_61 = {
    Text = [[
Shhh, Brown.
Calma... devo mantenere la testa lucida...]]
  },
  AvgDialog_18909_Content_62 = {
    Text = "Ho controllato tutto; il nome di mia sorella non è in quel registro."
  },
  AvgDialog_18909_Content_63 = {
    Text = "Abbiamo un sacco di chiavi. Aprirò ogni porta di questo posto, se necessario! Nessuna prova può nascondersi da me!"
  },
  AvgDialog_18909_Content_64 = {
    Text = "Aspetta, sorella."
  },
  AvgDialog_18909_Content_65 = {Text = "..."},
  AvgDialog_18909_Content_66 = {Text = "..."},
  AvgDialog_18909_Content_67 = {
    Text = "Accidenti, questa è l'ultima stanza."
  },
  AvgDialog_18909_Content_68 = {
    Text = [[
Buio pesto e vuoto come la promessa di un politico.
Ce ne andiamo a mani vuote, Brown.]]
  },
  AvgDialog_18909_Content_69 = {
    Text = "Squeak, squeak squeak!"
  },
  AvgDialog_18909_Content_7 = {
    Text = "La presenza di Ogier lascia perplessa Sarah, che vi guarda in attesa di una spiegazione."
  },
  AvgDialog_18909_Content_70 = {
    Text = "Cosa? ...sotto il pavimento?"
  },
  AvgDialog_18909_Content_71 = {
    Text = "Jenkin esita un istante, poi accende delicatamente la lanterna. Abbassa la fiamma e si china verso il pavimento."
  },
  AvgDialog_18909_Content_72 = {
    Text = "Una fila di formiche marcia in formazione ordinata dentro la fessura del legno."
  },
  AvgDialog_18909_Content_73 = {
    Text = [[
Jenkin toglie alcuni chiodi e solleva l'asse.
Sotto si trova un coperchio di ferro quadrato da 25 pollici.]]
  },
  AvgDialog_18909_Content_74 = {
    Text = "Jenkin prova tutte le chiavi."
  },
  AvgDialog_18909_Content_75 = {
    Text = [[
Nessuna di queste funziona!
Ha nascosto un'altra chiave da qualche parte?]]
  },
  AvgDialog_18909_Content_76 = {
    Text = "Preme l'orecchio contro la lastra di ferro, ascoltando i suoni provenienti dal seminterrato."
  },
  AvgDialog_18909_Content_77 = {
    Text = "<Italic:Raschio... Raschio...>"
  },
  AvgDialog_18909_Content_78 = {Text = "!!"},
  AvgDialog_18909_Content_79 = {
    Text = "Questo è... il <Yellow:Fantasma dell'Ospizio> di cui ci ha parlato Aigis?!"
  },
  AvgDialog_18909_Content_8 = {
    Text = "Questo è il mio fratello minore, Ogier, uno degli eredi della famiglia."
  },
  AvgDialog_18909_Content_80 = {
    Text = "Squeak, squeak squeak!"
  },
  AvgDialog_18909_Content_81 = {
    Text = "Passi flebili risuonano fuori dalla porta."
  },
  AvgDialog_18909_Content_82 = {
    Text = "È così, Brown.\nNon possiamo affrontarla da soli se ha un fantasma dalla sua parte."
  },
  AvgDialog_18909_Content_83 = {
    Text = "Ci serve <Yellow:qualcuno che la spaventi>..."
  },
  AvgDialog_18909_Content_84 = {
    Text = "Jenkin si nasconde nell'ombra, sbirciando da dietro la pianta in vaso."
  },
  AvgDialog_18909_Content_85 = {
    Text = "Nel corridoio, Sarah sta presentando ossequiosamente la situazione finanziaria dell'Ospizio dei Poveri ai visitatori."
  },
  AvgDialog_18909_Content_86 = {
    Text = "...Sono quelli gli \"sponsor\" di cui parlava Aigis?"
  },
  AvgDialog_18909_Content_87 = {
    Text = "Jenkin annuisce pensieroso, poi sgattaiola via dal magazzino buio mentre nessuno guarda."
  },
  AvgDialog_18909_Content_88 = {
    Text = "Dietro di lei, le assi del pavimento parzialmente sollevate rivelano una fessura scura, in silenziosa attesa dei visitatori."
  },
  AvgDialog_18909_Content_9 = {
    Text = "Lord Ashe desidera che il giovane Maestro Ogier acquisisca una conoscenza approfondita delle condizioni del Distretto Est, così da agevolare riforme efficaci una volta assunto il controllo."
  },
  AvgDialog_18910_Content_1 = {
    Text = "Dannazione, i mostri continuano ad affluire!"
  },
  AvgDialog_18910_Content_2 = {
    Text = "Ogier, sigilla la schiusa! Ramona, concentrati su Sarah!"
  },
  AvgDialog_18910_Content_3 = {Text = "Ricevuto!"},
  AvgDialog_18911_Content_1 = {
    Text = "La situazione è sotto controllo."
  },
  AvgDialog_18911_Content_10 = {
    Text = "La Lama lascia una Traiettoria d'Argento al movimento della mano."
  },
  AvgDialog_18911_Content_11 = {
    Text = "Signorina Sarah! T'yog! Aiuto! Aiutami! <Big:NOOO!!>"
  },
  AvgDialog_18911_Content_12 = {
    Text = "La Lama si avvicinò sempre di più, fino a consumare la mia Visuale. E poi, e poi—"
  },
  AvgDialog_18911_Content_13 = {
    Text = "<Shake:AAAAAHHH—!>"
  },
  AvgDialog_18911_Content_14 = {
    Text = "Aigis trema, un grido soffocato di terrore le sale dalla gola."
  },
  AvgDialog_18911_Content_15 = {
    Text = "Come per un Richiamo, la misteriosa psicologa appare in silenzio alle sue spalle."
  },
  AvgDialog_18911_Content_16 = {
    Text = "Qualcosa ti turba, piccola Aigis? Vuoi raccontarlo alla Dottoressa Clementine?"
  },
  AvgDialog_18911_Content_17 = {
    Text = "Dottore Clementine?!"
  },
  AvgDialog_18911_Content_18 = {
    Text = "Le visite notturne all'Ospizio dei Poveri non rientrano certo nella prassi medica standard. Spieghi la sua presenza."
  },
  AvgDialog_18911_Content_19 = {
    Text = "Non allarmarti. Ci sono state delle agitazioni nell'Ospizio dei Poveri, e il signor Rogers è preoccupato per lo Stato mentale dei lavoratori e dei Fanciulli, così mi ha assunta per dare una mano."
  },
  AvgDialog_18911_Content_2 = {
    Text = "Ramona si volta verso la bambina terrorizzata, che trema troppo per riuscire a parlare."
  },
  AvgDialog_18911_Content_20 = {
    Text = "Di tanto in tanto passo la notte nell'Ospizio dei Poveri, in una stanza vicina a quella dei Fanciulli."
  },
  AvgDialog_18911_Content_21 = {
    Text = "Aigis, conosci questa signora?"
  },
  AvgDialog_18911_Content_22 = {
    Text = "L'Avvento di Clementine strappa la ragazza dalle sue Memorie. Lei annuisce in segno di assenso."
  },
  AvgDialog_18911_Content_23 = {
    Text = "È stata la mia piccola Ospite fin dal mio primo giorno qui nell'Ospizio dei Poveri."
  },
  AvgDialog_18911_Content_24 = {
    Text = "Condividere i propri affanni è un modo per guarire la mente, e io sono un'ascoltatrice molto professionale."
  },
  AvgDialog_18911_Content_25 = {
    Text = "Lo Sguardo indagatore compie una Spazzata sui volti di Tutti prima di fissarsi su di te."
  },
  AvgDialog_18911_Content_26 = {
    Text = "No grazie, abbiamo altre faccende di cui occuparci."
  },
  AvgDialog_18911_Content_27 = {
    Text = [[
Che peccato. Se cambi idea, sei sempre la benvenuta nel nostro viaggio di scoperta interiore.
Andiamo, Aigis.]]
  },
  AvgDialog_18911_Content_28 = {
    Text = "Aigis prende la mano di Clementine e si allontana in silenzio."
  },
  AvgDialog_18911_Content_29 = {
    Text = "Aigis! Dove stai andando?!"
  },
  AvgDialog_18911_Content_3 = {
    Text = "Le rimbocca delicatamente la manica di Aigis, rivelando punti di sutura scioccanti che risaltano sul suo polso pallido."
  },
  AvgDialog_18911_Content_30 = {
    Text = "<Small:Scusate... la Dottoressa Clementine può aiutarmi...>"
  },
  AvgDialog_18911_Content_31 = {
    Text = "Detto ciò, la ragazza tira la manica di Clementine — cosa che faceva raramente. Con quella muta insistenza, scompaiono oltre la porta dell'Ospizio dei Poveri."
  },
  AvgDialog_18911_Content_32 = {
    Text = "Aigis... chissà quale segreto nasconde."
  },
  AvgDialog_18911_Content_33 = {
    Text = "La nebbia si sta dissipando; dovremmo riposare prima di addentrarci nel seminterrato con Jenkin."
  },
  AvgDialog_18911_Content_4 = {
    Text = [[
Aigis, hanno condotto gli stessi esperimenti su di te.
Ti hanno legata e operata con la forza, impiantandoti degli... <Yellow:oggetti estranei>, vero?]]
  },
  AvgDialog_18911_Content_5 = {
    Text = "Io, io... era..."
  },
  AvgDialog_18911_Content_6 = {
    Text = "Ugh... Questo è..."
  },
  AvgDialog_18911_Content_7 = {
    Text = "La luce intensa rendeva difficile tenere gli occhi aperti. Aigis provò, ma non riuscì a controllare le palpebre."
  },
  AvgDialog_18911_Content_8 = {
    Text = "Il metallo freddo immobilizzava i muscoli attorno ai suoi occhi. Osservò impotente l'uomo in camice bianco avvicinarsi, bisturi in mano."
  },
  AvgDialog_18911_Content_9 = {
    Text = "No, NO! Signorina Sarah, SIGNORINA SARAH!"
  },
  AvgDialog_18912_Content_1 = {
    Text = "La Chiave d'Argento tremola intensamente mentre la bambina sorregge il proprio corpo. Senti qualcosa debolmente, qualcosa che viene lacerato."
  },
  AvgDialog_18912_Content_10 = {
    Text = "Crolli debolmente a terra, lottando per sopportare un martellante mal di testa e la nausea."
  },
  AvgDialog_18912_Content_11 = {Text = "%player%!"},
  AvgDialog_18912_Content_12 = {
    Text = "Hai abusato del tuo potere mentale? Non vivrai abbastanza a lungo per assistere al futuro dei Mythag così.\nSiediti e riposa. Abusare del potere mentale comprometterà la tua capacità percettiva."
  },
  AvgDialog_18912_Content_13 = {
    Text = "Non preoccuparti per me, controlla Aigis."
  },
  AvgDialog_18912_Content_14 = {
    Text = [[
Il suono del liquido che evapora si affievolisce e svanisce.
Sul pavimento macchiato di melma, la ragazza siede in silenzio, coprendosi un occhio.]]
  },
  AvgDialog_18912_Content_15 = {
    Text = "Signorina Ramona... e... {Male=Mr.,Female=Miss} %player%.\nSono così felice che stiate bene."
  },
  AvgDialog_18912_Content_16 = {Text = "Aigis..."},
  AvgDialog_18912_Content_17 = {
    Text = "Vieni a Mythag con noi. Troveremo un modo per curare i tuoi occhi."
  },
  AvgDialog_18912_Content_18 = {
    Text = "Tendi la mano verso Aigis."
  },
  AvgDialog_18912_Content_19 = {
    Text = [[
Delicatamente, Aigis posa la sua mano sulla tua.
Le sue dita sono fredde come la pietra, eppure in quel momento sembrano calde come il tramonto dorato fuori dalla finestra.]]
  },
  AvgDialog_18912_Content_2 = {
    Text = "La benda scivola giù, colori sinuosi rimpiazzano l'oscurità, e un enorme occhio pallido appare sotto di lei, come se la osservasse da tempo immemorabile."
  },
  AvgDialog_18912_Content_20 = {
    Text = "Me l'ha detto Jenkin. Ciò che stai ricercando, e ciò che i dottori hanno sperimentato su di noi, è un fenomeno chiamato \"Dissoluzione\". Cancellerebbe l'esistenza di una persona, persino le Memorie correlate."
  },
  AvgDialog_18912_Content_21 = {
    Text = "Se è vero... Ho un desiderio."
  },
  AvgDialog_18912_Content_22 = {
    Text = "Aigis esita, soffocando deboli singhiozzi."
  },
  AvgDialog_18912_Content_23 = {
    Text = "Spero che tutti all'Ospizio dei Poveri si dimentichino di me e del dolore che ho causato."
  },
  AvgDialog_18912_Content_24 = {
    Text = "Alza la testa e ti fissa con il suo occhio freddo, color pietra."
  },
  AvgDialog_18912_Content_25 = {
    Text = "Ti senti immobilizzato in quell'istante."
  },
  AvgDialog_18912_Content_26 = {
    Text = "Cogliendo l'occasione, si volta e svanisce nell'oscurità, arrampicandosi fino alla piattaforma della torre dell'Orologio."
  },
  AvgDialog_18912_Content_27 = {
    Text = "I raggi dorati del sole al tramonto perforano il gigantesco quadrante trasparente dell'orologio, dorando la figura della bambina."
  },
  AvgDialog_18912_Content_28 = {
    Text = "Aigis si volta di lato, posando una mano sul vetro da tempo non lavato, socchiudendo gli occhi nella calda luce del sole."
  },
  AvgDialog_18912_Content_29 = {
    Text = "Oggi c'è il sole..."
  },
  AvgDialog_18912_Content_3 = {
    Text = "Tu sei... un occhio? Il mio occhio?"
  },
  AvgDialog_18912_Content_30 = {
    Text = "Forse rinvigorita dalla rara giornata di sole, barcolla fino a un pezzo di vetro più pulito."
  },
  AvgDialog_18912_Content_31 = {
    Text = "La sua Visuale offuscata si schiarisce. Contemplando strade familiari e sconosciute, qualcuno sembra sussurrarle all'orecchio."
  },
  AvgDialog_18912_Content_32 = {
    Text = "<Italic:\"Guarda,\"> dice quella Voce, <Italic:\"Te l'avevo detto. Stanotte ci saranno delle Stelle bellissime.\">"
  },
  AvgDialog_18912_Content_33 = {
    Text = "In passato, dopo ogni giornata di sole, T'yog mi portava quassù di nascosto."
  },
  AvgDialog_18912_Content_34 = {
    Text = "La signorina Sarah ci proibiva sempre di venire qui. Diceva che era troppo pericoloso, che potevamo farci male."
  },
  AvgDialog_18912_Content_35 = {
    Text = "Ma T'yog non ascoltava mai. Ogni volta, mi portava di sopra al buio di nascosto, una volta che la signorina Sarah aveva finito il suo giro della buonanotte."
  },
  AvgDialog_18912_Content_36 = {
    Text = "È furbo e coraggioso, proprio come Jenkin. Conosce sempre sentieri nascosti e scorciatoie che gli altri ignorano."
  },
  AvgDialog_18912_Content_37 = {
    Text = "Finché lui era con me, la signorina Sarah non ci avrebbe mai trovati."
  },
  AvgDialog_18912_Content_38 = {
    Text = "Finché lui era con me, questo posto sarebbe sempre stato il Nostro Segreto rifugio."
  },
  AvgDialog_18912_Content_39 = {
    Text = "Mi disse che dovevo abbracciare le stelle per potenziare la mia magia, anche se qui non riuscivamo a vedere nemmeno una stella."
  },
  AvgDialog_18912_Content_4 = {
    Text = "No, non lo è! Questa sensazione è...! È il signor @2!"
  },
  AvgDialog_18912_Content_40 = {
    Text = "Fu l'unico a credermi, allora. Credeva che potessi vedere quelle cose nere e mi disse che era un dono da strega."
  },
  AvgDialog_18912_Content_41 = {
    Text = "Ma è stato portato via, solo per proteggere me..."
  },
  AvgDialog_18912_Content_42 = {
    Text = "Se fossi stata intelligente come lui e coraggiosa come Jenkin, avrei scoperto la verità.\nMa non sono una strega; sono solo una codarda, un mostro."
  },
  AvgDialog_18912_Content_43 = {
    Text = "Un... assassino."
  },
  AvgDialog_18912_Content_44 = {
    Text = "Aigis, sei una brava bambina. Eri controllata; non è colpa tua."
  },
  AvgDialog_18912_Content_45 = {
    Text = "Sai quante persone ho trasformato in statue?"
  },
  AvgDialog_18912_Content_46 = {
    Text = "Sono terrorizzata da ciò che sto per diventare..."
  },
  AvgDialog_18912_Content_47 = {
    Text = "...e da ciò che sono già diventata."
  },
  AvgDialog_18912_Content_48 = {
    Text = "Ma niente di tutto questo ha più importanza."
  },
  AvgDialog_18912_Content_5 = {
    Text = "Mi presterai la tua forza? Ma tu che ne sarà di te?"
  },
  AvgDialog_18912_Content_50 = {
    Text = "Non sarò più controllata, non farò del male a nessuno, né lascerò morire i miei amici per causa mia."
  },
  AvgDialog_18912_Content_52 = {
    Text = "Dannazione, dovevano restare nella stanza, ma ora nessuno sa dove siano finiti."
  },
  AvgDialog_18912_Content_53 = {
    Text = "Aspetta, quello è..."
  },
  AvgDialog_18912_Content_54 = {
    Text = "Aigis?! Aigis—!"
  },
  AvgDialog_18912_Content_55 = {
    Text = "La voce di Jenkin risuona all'improvviso dal basso, gridando con ansia il nome di Aigis, le braccia protese verso il cielo."
  },
  AvgDialog_18912_Content_56 = {
    Text = "Un uccello attraversa il cielo notturno, svanendo nella fitta nebbia senza lasciare traccia."
  },
  AvgDialog_18912_Content_57 = {
    Text = "Il nastro legato alla sua mano si scioglie e si invola lontano. Il piccolo corpo della ragazza cade, scomparendo per sempre nella notte."
  },
  AvgDialog_18912_Content_58 = {
    Text = "Il vestito bianco vuoto e i quadratini di carta sparsi si posano delicatamente nella mano di Jenkin."
  },
  AvgDialog_18912_Content_59 = {
    Text = "Non resta nemmeno una traccia di calore."
  },
  AvgDialog_18912_Content_6 = {
    Text = "Grazie... So che sarà breve, ma io... ho qualcosa da dire loro."
  },
  AvgDialog_18912_Content_60 = {
    Text = "Ai... Aigis...?"
  },
  AvgDialog_18912_Content_61 = {
    Text = "Una farfalla dorata è disegnata sulla carta, con i bordi stropicciati accuratamente spianati. Porta persino un lieve sentore di dolcezza zuccherina."
  },
  AvgDialog_18912_Content_62 = {
    Text = "Come... com'è possibile..."
  },
  AvgDialog_18912_Content_63 = {
    Text = "Il nastro cremisi e l'involucro della caramella cadono nella mano di Jenkin, sfiorandole le dita come una tenera carezza."
  },
  AvgDialog_18912_Content_64 = {
    Text = "Sbatte le palpebre, le lacrime le offuscano la visuale e scivolano dalle ciglia, catturate in silenzio da quel rosso vivido."
  },
  AvgDialog_18912_Content_65 = {Text = "Aigis..."},
  AvgDialog_18912_Content_7 = {
    Text = "Aigis, Aigis!"
  },
  AvgDialog_18912_Content_8 = {
    Text = "Aigis si muove e apre davvero gli occhi."
  },
  AvgDialog_18912_Content_9 = {
    Text = "Dopo un grido lacerante, il corpo massiccio del Mostro si dissolve in melma nera e crolla su se stesso. La melma si riduce in polvere, sollevandosi a oscurare le travi di legno."
  },
  AvgDialog_18913_Content_1 = {
    Text = "Finalmente raggiungi Aigis e la immobilizzi unendo le forze. Con urgenza allunghi la mano, le afferri il braccio e premi la Chiave d'Argento per completare il vincolo."
  },
  AvgDialog_18913_Content_10 = {
    Text = "No, Aigis, fidati di me. L'Università di Mythag ha affrontato situazioni ben peggiori..."
  },
  AvgDialog_18913_Content_11 = {
    Text = "Davvero? Ogier... Guarda i loro corpi."
  },
  AvgDialog_18913_Content_12 = {
    Text = "Ogier si volta verso il Custode e Ramona che si dibattono.\nI loro corpi trasudano sudore dai colori strani—non sudore, ma sciroppo sottile."
  },
  AvgDialog_18913_Content_13 = {
    Text = "Dopo che la voce del signor Anderson si è spenta, i colori nei miei occhi sono gradualmente sfuggiti al controllo, insieme al mio corpo. Anche senza guardare, le persone intorno a me si trasformavano in pietra."
  },
  AvgDialog_18913_Content_14 = {
    Text = "Quanto ancora potrò resistere? Un anno, un mese, un giorno, un'ora?"
  },
  AvgDialog_18913_Content_15 = {
    Text = "Dovrei restare nascosta dietro a tutti e aspettare finché non ci sarà più ritorno?"
  },
  AvgDialog_18913_Content_16 = {
    Text = "No, voglio essere coraggiosa come T'yog, coraggiosa come Jenkin, coraggiosa come te. Almeno per questa volta."
  },
  AvgDialog_18913_Content_17 = {
    Text = [[
Ogier, non sei un cavaliere? Allora capisci.
Se resto, sono una criminale in attesa del giudizio dei cavalieri.]]
  },
  AvgDialog_18913_Content_18 = {
    Text = "Ogier resta impietrito."
  },
  AvgDialog_18913_Content_19 = {
    Text = "Ogier, una volta hai detto... la redenzione dipende da noi stessi."
  },
  AvgDialog_18913_Content_2 = {
    Text = [[
Per favore, non fatelo...
Lo so...]]
  },
  AvgDialog_18913_Content_20 = {
    Text = "Ora... guardami, e giudica la mia anima... Può essere redenta?"
  },
  AvgDialog_18913_Content_21 = {
    Text = "Ogier fissa l'unico occhio sano di Aigis, esita, poi lascia solennemente la presa."
  },
  AvgDialog_18913_Content_22 = {
    Text = "Nel momento in cui si muove, Aigis si libera dal tuo legame di controllo."
  },
  AvgDialog_18913_Content_23 = {
    Text = "In un istante, il corpo della bambina si gonfia rapidamente, la pelle si ricopre di vesciche di varie dimensioni, bloccando la tromba delle scale e premendo contro il soffitto."
  },
  AvgDialog_18913_Content_24 = {
    Text = "Tra suoni orribili di arti che si contorcono, solo una faint traccia della voce della ragazza permane."
  },
  AvgDialog_18913_Content_25 = {
    Text = "<Shake:Corri... corri...>"
  },
  AvgDialog_18913_Content_3 = {
    Text = "Vieni trascinato nell'oscurità."
  },
  AvgDialog_18913_Content_4 = {
    Text = "L'oscurità rovente, ardente, ti avvolge come sciroppo fuso, stringendoti in una morsa."
  },
  AvgDialog_18913_Content_5 = {
    Text = "<Italic:Il soriano del vecchio Charlie, grasso e caro...>"
  },
  AvgDialog_18913_Content_6 = {
    Text = "Il dolore inizia in superficie, prima come morsi di formiche, poi si intensifica mentre innumerevoli aghi perforano ogni centimetro della tua pelle—"
  },
  AvgDialog_18913_Content_7 = {
    Text = "Il legame si spezza con violenza."
  },
  AvgDialog_18913_Content_8 = {
    Text = "Sopportando il dolore, stringi la Chiave d'Argento con la mano sinistra, tremando mentre riporti la mano destra sul braccio di Aigis."
  },
  AvgDialog_18913_Content_9 = {
    Text = "È troppo tardi..."
  },
  AvgDialog_18914_Content_1 = {
    Text = "Questi mostri hanno tutti dei D-segno sui loro corpi. E... sembra che siano stati cuciti addosso."
  },
  AvgDialog_18914_Content_2 = {
    Text = "Ramona batte due volte sulla sua spilla."
  },
  AvgDialog_18914_Content_3 = {
    Text = "Erica, avvia il protocollo di ricerca per \"D-segno Cucito.\""
  },
  AvgDialog_18914_Content_4 = {
    Text = "Parola chiave corrispondente, \"D-marchio cucito\", con un totale di 37 incidenti correlati.\nParole chiave dell'evento: Attività di organizzazione malevola, <Blue:Gli scultori>."
  },
  AvgDialog_18914_Content_5 = {
    Text = "L'Associazione degli Scultori?"
  },
  AvgDialog_18914_Content_6 = {
    Text = "Sono un gruppo di folli che si fanno chiamare \"Pigmalione\", ossessionati dalla <Red:modificazione biologica>... Abbiamo avuto diversi scontri con loro nelle città fuori da Londinium."
  },
  AvgDialog_18914_Content_7 = {
    Text = "La loro infiltrazione nel Distretto Est richiede un livello di Allerta maggiore... In particolare per individui <Yellow:armati di bisturi>."
  },
  AvgDialog_18915_Content_1 = {
    Text = "Ogier affronta senza paura diversi dottori, schivando e neutralizzando la loro forza con destrezza per quindici minuti."
  },
  AvgDialog_18915_Content_10 = {
    Text = "Ora sbrigati a prepararti. Ti porterò personalmente alla clinica... e anche il Piccolo Mac; è passato un po' dall'ultimo controllo."
  },
  AvgDialog_18915_Content_11 = {
    Text = "Spero che il signor Rogers sia disposto a comunicarmi il loro indirizzo."
  },
  AvgDialog_18915_Content_12 = {
    Text = "No! La prego, signorina Sarah, non vogliamo il trattamento."
  },
  AvgDialog_18915_Content_13 = {
    Text = "Aigis dà una spinta a Mac, che sembra confuso ma alla fine corre di nuovo nella stanza."
  },
  AvgDialog_18915_Content_14 = {
    Text = "Piccolo Mac! Torna indietro!"
  },
  AvgDialog_18915_Content_15 = {
    Text = "Aigis afferra con urgenza la manica di Sarah, permettendo a Mac di fuggire."
  },
  AvgDialog_18915_Content_16 = {
    Text = "Se... se proprio dobbiamo, prendete solo me..."
  },
  AvgDialog_18915_Content_17 = {
    Text = "Signorina Sarah."
  },
  AvgDialog_18915_Content_18 = {
    Text = "Che succede, Giovane Padrone Ashe?"
  },
  AvgDialog_18915_Content_19 = {
    Text = "Sarah indossa immediatamente di nuovo una maschera servile."
  },
  AvgDialog_18915_Content_2 = {Text = "Basta."},
  AvgDialog_18915_Content_20 = {
    Text = "In nome di Ogier, cavaliere del Granduca, vi proibisco di imporre ad Aigis il \"trattamento\"."
  },
  AvgDialog_18915_Content_21 = {
    Text = "C-Cavaliere?"
  },
  AvgDialog_18915_Content_22 = {
    Text = "Ogier si rende conto della gaffe, il volto si arrossa all'istante. Prosegue esitante."
  },
  AvgDialog_18915_Content_23 = {
    Text = "S-Sì, il figlio più giovane della nostra casata viene sempre nominato cavaliere.\nComunque, devo portare Aigis e aspettare {Male=my brother,Female=my sister} e la direttrice. Non rendere le cose più difficili per lei."
  },
  AvgDialog_18915_Content_24 = {
    Text = "Così dicendo, Ogier afferra la mano di Aigis e corre verso la stanza.\nLa ragazza tiene la testa bassa, apparentemente singhiozzando."
  },
  AvgDialog_18915_Content_25 = {
    Text = "Bene, questo dovrebbe fermare la Signorina Sarah."
  },
  AvgDialog_18915_Content_26 = {
    Text = "Aigis, potresti dirmi perché rifiuti il trattamento per te e per gli altri?"
  },
  AvgDialog_18915_Content_27 = {
    Text = "Le labbra di Aigis si serrano, un gemito soffocato le sfugge."
  },
  AvgDialog_18915_Content_28 = {
    Text = "Non temere, SONO un cavaliere. E un cavaliere TI proteggerà."
  },
  AvgDialog_18915_Content_29 = {Text = "Davvero!"},
  AvgDialog_18915_Content_3 = {
    Text = "Non costringeremo Aigis se non è d'accordo.\nPorteremo gli altri pazienti selezionati alla clinica per il trattamento e li riporteremo a terapia completata."
  },
  AvgDialog_18915_Content_30 = {
    Text = [[
Ogier balbetta, cercando di sembrare solenne.
Aigis lo guarda, esita, poi scoppia a ridere.]]
  },
  AvgDialog_18915_Content_31 = {
    Text = [[
Smettila, Ogier. Ho letto nei libri che i cavalieri proteggono sempre le principesse.
Guardami. Ti sembro una principessa?]]
  },
  AvgDialog_18915_Content_32 = {
    Text = "Aigis sfiora delicatamente la toppa sulla gonna, parlando a bassa voce."
  },
  AvgDialog_18915_Content_33 = {
    Text = "Allora quei libri non dicono la verità.\nI cavalieri non proteggono solo le principesse; proteggono anche la gente comune. Proteggono tutti."
  },
  AvgDialog_18915_Content_34 = {
    Text = "Aigis cerca di capire Ogier."
  },
  AvgDialog_18915_Content_35 = {
    Text = "Sei davvero un Cavaliere?"
  },
  AvgDialog_18915_Content_36 = {
    Text = "Si batte il petto, il guanto d'arme tintinna, la sua espressione si contorce per un istante."
  },
  AvgDialog_18915_Content_37 = {
    Text = "Sì, lo sono! Sono stato nominato cavaliere personalmente da una famiglia reale. È mio dovere proteggere tutti."
  },
  AvgDialog_18915_Content_38 = {
    Text = "Ammiro il tuo coraggio... alzarti in difesa di qualcuno che hai appena incontrato."
  },
  AvgDialog_18915_Content_39 = {
    Text = "Peccato che io non sia un Cavaliere, né una Principessa, nemmeno un popolano. Sono solo un miserabile..."
  },
  AvgDialog_18915_Content_4 = {
    Text = "Buongiorno, Signorina Sarah."
  },
  AvgDialog_18915_Content_40 = {
    Text = "Non finì la frase."
  },
  AvgDialog_18915_Content_41 = {
    Text = "Ogier, hai detto che i cavalieri proteggono tutti..."
  },
  AvgDialog_18915_Content_42 = {
    Text = "E i criminali? Persino... gli assassini?"
  },
  AvgDialog_18915_Content_43 = {
    Text = "Ogier si erge fiero e Tenace:"
  },
  AvgDialog_18915_Content_44 = {
    Text = "I cavalieri non proteggono i criminali.\nPerché i cavalieri puniscono i criminali e proteggono la gente da loro."
  },
  AvgDialog_18915_Content_45 = {
    Text = "Lo sapevo..."
  },
  AvgDialog_18915_Content_46 = {
    Text = "Senza cogliere il sospiro di Aigis, continua a parlare."
  },
  AvgDialog_18915_Content_47 = {
    Text = "Questo perché i cavalieri non sono onnipotenti."
  },
  AvgDialog_18915_Content_48 = {
    Text = "Dopo la Sanzione, i Cavalieri consegneranno il penitente ai Sacerdoti."
  },
  AvgDialog_18915_Content_49 = {
    Text = "I Sacerdoti misericordiosi assistono ogni penitente... ma se la loro anima possa infine essere redenta, dipende solo da loro stessi."
  },
  AvgDialog_18915_Content_5 = {
    Text = "Vick rivolge ad Aigis un ultimo sguardo prima di andarsene con gli altri."
  },
  AvgDialog_18915_Content_50 = {
    Text = "Dipende da... loro stessi..."
  },
  AvgDialog_18915_Content_51 = {
    Text = "Sì, non è troppo tardi."
  },
  AvgDialog_18915_Content_52 = {
    Text = "Si tratta tutto di te@4..."
  },
  AvgDialog_18915_Content_53 = {
    Text = [[
Aigis si ferma, assaporando le sue parole.
Esitante, comincia a parlare lentamente.]]
  },
  AvgDialog_18915_Content_54 = {
    Text = "Mi fido di te, Ogier. Sono disposta a provarci ancora.\nQuindi ti dirò... la verità su quei trattamenti."
  },
  AvgDialog_18915_Content_6 = {
    Text = "Sarah congeda i dottori con un sorriso forzato, ma la sua espressione si fa severa quando si rivolge ad Aigis."
  },
  AvgDialog_18915_Content_7 = {
    Text = "Aigis, perché sei così disobbediente?"
  },
  AvgDialog_18915_Content_8 = {
    Text = "Signorina Sarah, io..."
  },
  AvgDialog_18915_Content_9 = {
    Text = "Sono venuti solo per il signor Rogers. Ora li hai cacciati via. Come dovrei spiegare tutto questo al signor Rogers?"
  },
  AvgDialog_18916_Content_1 = {
    Text = "In silenzio, i Mostri si dissolvono in fumo nero."
  },
  AvgDialog_18916_Content_10 = {
    Text = "Se chiamate me Mostro, come chiamereste quella cosa?"
  },
  AvgDialog_18916_Content_11 = {
    Text = "Lei accarezza il mento della Statua in risposta, poi sfiora lievemente il dorso della tua Mano."
  },
  AvgDialog_18916_Content_12 = {
    Text = "Siete intrappolati in un'illusione del mare."
  },
  AvgDialog_18916_Content_13 = {
    Text = "Una grandiosa città costruita con Pietre verdi e mostruose che sfida completamente la geometria euclidea. I rilievi ornati eppure Impurità abbagliano in modo splendido e sinistro sotto la luce rifratta del mare."
  },
  AvgDialog_18916_Content_14 = {
    Text = "Una sensazione soffocante ti avvolge. L'aria preziosa viene spremuta dai tuoi polmoni e defluisce attraverso la tua bocca."
  },
  AvgDialog_18916_Content_15 = {
    Text = "—Poi, qualcuno vi afferra, spezzando l'illusione."
  },
  AvgDialog_18916_Content_16 = {Text = "Custode!"},
  AvgDialog_18916_Content_17 = {
    Text = "Non preoccupatevi, è solo un'illusione."
  },
  AvgDialog_18916_Content_18 = {
    Text = "Cosa stai cercando di dirmi mostrandomi tutto questo?"
  },
  AvgDialog_18916_Content_19 = {
    Text = "Sanga abbassa gli occhi e non risponde."
  },
  AvgDialog_18916_Content_2 = {Text = "Phew—"},
  AvgDialog_18916_Content_20 = {
    Text = "Richiami alla mente ciò che hai appreso dai corsi preparatori di Studi sul Risveglio."
  },
  AvgDialog_18916_Content_21 = {
    Text = "<Yellow:Aequor>, <Yellow:Caro> e <Yellow:Ultra> sono le classificazioni principali dei Reami dei Risvegliati nel mondo accademico. Inoltre, esistono alcuni reami meno studiati per mancanza di soggetti, come l'<Yellow:Occulto> e l'<Yellow:Etere>..."
  },
  AvgDialog_18916_Content_22 = {
    Text = "Di norma i Reami si escludono a vicenda, ma alcuni Risvegliati possiedono la capacità di adattarsi ad altri reami e vengono classificati nel <Yellow:Reame del Caos>."
  },
  AvgDialog_18916_Content_23 = {
    Text = "La voce strozzata di Jenkin interrompe i tuoi pensieri. Sguscia tra le sculture di zucchero del seminterrato come un topo in trappola."
  },
  AvgDialog_18916_Content_24 = {
    Text = "Li ho controllati tutti. Ogni volto."
  },
  AvgDialog_18916_Content_25 = {
    Text = "Non è qui...\n<Big:DOV'È MIA SORELLA? DITEMELO!>"
  },
  AvgDialog_18916_Content_26 = {
    Text = "Ramona chiude la comunicazione con la scuola, la sua voce gelida taglia i tuoi pensieri."
  },
  AvgDialog_18916_Content_27 = {
    Text = "Confermato Risvegliato non registrato. In base all'<Yellow:Articolo 12 del Trattato di Mystia>, dobbiamo contattare il <Blue:Comitato del Trattato> per il contenimento."
  },
  AvgDialog_18916_Content_28 = {
    Text = "Prima del loro avvento, vi preghiamo di rivelare l'ubicazione di tutti gli scomparsi, inclusi <Blue:Sean Anderson, l'Investigatore Mythag> e <Blue:Mason il Tessitore>, nonché i vostri legami con l'<Blue:Associazione degli Scultori>."
  },
  AvgDialog_18916_Content_29 = {
    Text = "Aspettate, Ramona, Jenkin."
  },
  AvgDialog_18916_Content_3 = {
    Text = "Il fantasma espira dolcemente, disperdendo polvere di zucchero dal suo coltello da intaglio."
  },
  AvgDialog_18916_Content_30 = {
    Text = "Liquidi con un gesto le loro domande e ti volti verso Sanga, che sfoggia un sorriso consapevole."
  },
  AvgDialog_18916_Content_31 = {
    Text = "Chi ha ridotto queste persone così... non sei stata tu, vero?"
  },
  AvgDialog_18916_Content_32 = {Text = "%player%?"},
  AvgDialog_18916_Content_33 = {
    Text = "Mi hai mostrato un'illusione, una scena composta dal mondo sottomarino e da intagli di corallo... È il potere dei mari e dei sogni, il potere del <Yellow:Reame di Aequor>."
  },
  AvgDialog_18916_Content_34 = {
    Text = "Volgi lo sguardo alle grottesche figure di zucchero che si contorcono. Un respiro profondo porta una dolcezza opprimente che assale ancora una volta i tuoi sensi."
  },
  AvgDialog_18916_Content_35 = {
    Text = "Questi corpi sono stati fusi in sciroppo e poi solidificati in statue...\nQuesta capacità assomiglia più all'opera di un <Yellow:Risvegliatore del Reame di Caro>, spesso più abili nel trasformare la carne."
  },
  AvgDialog_18916_Content_36 = {
    Text = "Potresti essere coinvolta, ma il vero colpevole è qualcun altro."
  },
  AvgDialog_18916_Content_37 = {
    Text = "Parlare con persone intelligenti è davvero delizioso."
  },
  AvgDialog_18916_Content_38 = {
    Text = "In effetti, un amico mi ha parlato dei materiali unici di questo luogo, e volevo solo prenderne in prestito alcuni per plasmare il mio \"Dio\"."
  },
  AvgDialog_18916_Content_39 = {
    Text = "Sanga parla con disinvoltura mentre ripone i coltelli da intaglio nella borsa."
  },
  AvgDialog_18916_Content_4 = {
    Text = [[
Fatto.
Ma ancora una volta, non abbastanza bene.]]
  },
  AvgDialog_18916_Content_40 = {
    Text = [[
Andiamo, non mi stavate portando da qualche comitato?
Potete aiutarmi a impacchettare anche queste statue?]]
  },
  AvgDialog_18916_Content_41 = {
    Text = "C'è dell'altro..."
  },
  AvgDialog_18916_Content_42 = {
    Text = "Batte la mano sul sedile di pietra sotto di lei."
  },
  AvgDialog_18916_Content_43 = {
    Text = "Vedi, non sono molto brava a camminare. Per caso hai un'auto a disposizione?"
  },
  AvgDialog_18916_Content_44 = {
    Text = "Le afferrate il polso."
  },
  AvgDialog_18916_Content_45 = {
    Text = "Chi li ha ridotti così?"
  },
  AvgDialog_18916_Content_46 = {
    Text = "Lo state chiedendo a me?"
  },
  AvgDialog_18916_Content_47 = {
    Text = "Sanga lascia sfuggire un lieve sospiro."
  },
  AvgDialog_18916_Content_48 = {
    Text = [[
Oggi mi sento generosa, siete fortunati.
Andate a chiedere alla direttrice e a quei dottori.]]
  },
  AvgDialog_18916_Content_49 = {
    Text = [[
Sarah! Sapevo che quella donna c'era dietro a tutto questo!
Aspettate, io... io...]]
  },
  AvgDialog_18916_Content_5 = {
    Text = "Posa il coltello, voltandosi a metà verso di te."
  },
  AvgDialog_18916_Content_50 = {
    Text = "La ferocia di Jenkin si tramuta presto in sconforto."
  },
  AvgDialog_18916_Content_51 = {
    Text = "Vi fate avanti con delicatezza e le posate una mano sulla spalla."
  },
  AvgDialog_18916_Content_52 = {
    Text = "Nessuna notizia è una buona notizia. Finché...\nc'è ancora speranza."
  },
  AvgDialog_18916_Content_53 = {
    Text = "Non abbiamo più bisogno di travestirci.\nRamona, chiama il Comitato. Jenkin, porta Sarah qui."
  },
  AvgDialog_18916_Content_54 = {
    Text = "E il suo registro."
  },
  AvgDialog_18916_Content_6 = {
    Text = "Ora, miei cari Ospiti, cosa vi porta qui? Quali affari avete con me?"
  },
  AvgDialog_18916_Content_7 = {
    Text = "Tu... tu, mostro!"
  },
  AvgDialog_18916_Content_8 = {
    Text = "Mostro? Preferirei che mi chiamaste \"Sanga.\""
  },
  AvgDialog_18916_Content_9 = {
    Text = "Sanga spazzola la polvere dalla superficie della Scultura di zucchero, evasiva."
  },
  AvgDialog_18917_Content_1 = {
    Text = "Signorina 24, perché ci avete attaccato immediatamente?"
  },
  AvgDialog_18917_Content_2 = {
    Text = "Attacco? No, io non combatto..."
  },
  AvgDialog_18917_Content_3 = {
    Text = "Ah! Quindi avete incontrato \"lei\"?"
  },
  AvgDialog_18917_Content_4 = {
    Text = "So che sembra assurdo, quella non ero davvero io—"
  },
  AvgDialog_18917_Content_5 = {
    Text = "In realtà, lei <Italic:sono> io, ma è la parte anormale..."
  },
  AvgDialog_18917_Content_6 = {
    Text = "No, non è giusto nemmeno così. In realtà c'è un'altra me... Ce ne sono diverse di me..."
  },
  AvgDialog_18917_Content_7 = {
    Text = "Fantastico! Finalmente qualcuno che parla, ed è pazzo."
  },
  AvgDialog_18918_Content_1 = {
    Text = "Signorina 24, c'è qualcosa che volevo chiederti..."
  },
  AvgDialog_18918_Content_2 = {
    Text = "Come sei riuscita esattamente a emergere da una scultura di cera?"
  },
  AvgDialog_18918_Content_3 = {
    Text = "Io... scusa, mi sento un po' confusa. La confusione mi perseguita da tempo."
  },
  AvgDialog_18918_Content_4 = {
    Text = "Sono stata trasformata in una scultura di cera, non so per quanto tempo sono rimasta lì..."
  },
  AvgDialog_18918_Content_5 = {
    Text = "All'improvviso, mi è sembrato di potermi muovere e respirare. Poi—"
  },
  AvgDialog_18918_Content_6 = {
    Text = "Poi sei strisciata fuori dalla cera come un fantasma."
  },
  AvgDialog_18918_Content_7 = {
    Text = "Sì, sì..."
  },
  AvgDialog_18919_Content_1 = {Text = "Occhi..."},
  AvgDialog_18919_Content_2 = {
    Text = "Gli occhi di Mr. Wax... sembrano stranamente familiari."
  },
  AvgDialog_18920_Content_1 = {
    Text = "Ahhh, d-da dove siete sbucati tutti quanti?!"
  },
  AvgDialog_18920_Content_2 = {
    Text = "Etcì! Che puzza... I morti hanno davvero bisogno del profumo?"
  },
  AvgDialog_18920_Content_3 = {
    Text = "Voi... bene, molto bene..."
  },
  AvgDialog_18920_Content_4 = {
    Text = "Lasciate che vi insegni le buone maniere!"
  },
  AvgDialog_18921_Content_1 = {
    Text = "4:40, Museo delle Cere di Rogers"
  },
  AvgDialog_18921_Content_10 = {
    Text = "Fermi. Guardate la sua ferita. Ha assorbito troppa D-melma..."
  },
  AvgDialog_18921_Content_11 = {
    Text = "Presto si dissolverà completamente, insieme a questo maledetto Museo delle Cere."
  },
  AvgDialog_18921_Content_12 = {
    Text = "Accidenti... Mi è finita addosso della D-melma."
  },
  AvgDialog_18921_Content_13 = {
    Text = "Jenkin trema mentre tende la mano, rivelando la chiave."
  },
  AvgDialog_18921_Content_14 = {
    Text = "Vieni qui, sorellina."
  },
  AvgDialog_18921_Content_15 = {
    Text = "Non muoverti, Jenkin! Sei ferita, ti tiro fuori di qui..."
  },
  AvgDialog_18921_Content_16 = {
    Text = "Vieni da questa parte, sorellina."
  },
  AvgDialog_18921_Content_17 = {
    Text = "Ora apri la mano... Sì, proprio così—"
  },
  AvgDialog_18921_Content_18 = {
    Text = "24 trema mentre apre la mano, e una chiave le cade nel palmo, ancora calda."
  },
  AvgDialog_18921_Content_19 = {
    Text = "L-la chiave è pulita! Ho fatto del mio meglio..."
  },
  AvgDialog_18921_Content_2 = {
    Text = "L'attesa sembra interminabile, finché dall'alto giunge il suono di un movimento affannoso."
  },
  AvgDialog_18921_Content_20 = {
    Text = "Che peccato. Ho solo tredici anni e non ho ancora vissuto abbastanza..."
  },
  AvgDialog_18921_Content_21 = {
    Text = "Jenkin annusa di nuovo e ti rivolge un sorriso radioso."
  },
  AvgDialog_18921_Content_22 = {
    Text = "Sorellona, non abbiamo nemmeno avuto il tempo di parlare un po' di più, e ora dobbiamo dirci ciao ciao di nuovo..."
  },
  AvgDialog_18921_Content_23 = {
    Text = "Ricordi cosa mi hai detto?"
  },
  AvgDialog_18921_Content_24 = {
    Text = "Hai detto... che non ero mai stata sola. Hai detto che avevo ancora te. Che avevo tutti."
  },
  AvgDialog_18921_Content_25 = {
    Text = "Da quel momento, seppi..."
  },
  AvgDialog_18921_Content_26 = {
    Text = "Farei qualsiasi cosa per te."
  },
  AvgDialog_18921_Content_27 = {Text = "Jenkin..."},
  AvgDialog_18921_Content_28 = {
    Text = "Grazie, grazie a tutti... Un'ultima cosa..."
  },
  AvgDialog_18921_Content_29 = {
    Text = "Non dimenticarmi, d'accordo?"
  },
  AvgDialog_18921_Content_3 = {
    Text = "Il suono diventa gradualmente più chiaro e più forte..."
  },
  AvgDialog_18921_Content_30 = {
    Text = "La melma nerissima si riversa da dietro la bambina, cristallizzando il suo sorriso radioso nel suo ultimo istante."
  },
  AvgDialog_18921_Content_31 = {
    Text = "La bambina che ama fare le smorfie, parla con gli animaletti e litiga sempre con la signorina Sarah..."
  },
  AvgDialog_18921_Content_32 = {
    Text = "...svanisce in silenzio, insieme a questo museo delle cere."
  },
  AvgDialog_18921_Content_4 = {
    Text = "Dopo un lungo momento, un braccio sottile e minuto si sporge dall'interno."
  },
  AvgDialog_18921_Content_5 = {Text = "Presa..."},
  AvgDialog_18921_Content_6 = {
    Text = "Jenkin, esci subito! Questo posto sta crollando..."
  },
  AvgDialog_18921_Content_7 = {
    Text = "Scusa. Forse... non mi unirò a voi."
  },
  AvgDialog_18921_Content_8 = {Text = "Squeak..."},
  AvgDialog_18921_Content_9 = {
    Text = "Jenkin, afferrami la mano, presto!"
  },
  AvgDialog_18922_Content_1 = {
    Text = [[
12:25, Museo delle Cere di Rogers
Studio]]
  },
  AvgDialog_18922_Content_10 = {
    Text = "Parla, Brown. Cos'hai visto là sotto?"
  },
  AvgDialog_18922_Content_11 = {
    Text = "Squeak, ugh... squeak squeak..."
  },
  AvgDialog_18922_Content_12 = {
    Text = "Hmm, e adesso?"
  },
  AvgDialog_18922_Content_13 = {
    Text = "Squeak squeak squeak..."
  },
  AvgDialog_18922_Content_14 = {
    Text = "Capito. Bravo, Brown."
  },
  AvgDialog_18922_Content_15 = {
    Text = "Brown dice che era troppo buio, non riusciva a vedere granché. Ha solo riportato questo."
  },
  AvgDialog_18922_Content_16 = {
    Text = "Jenkin apre con delicatezza la piccola zampa di Brown e ne estrae una bustina portadocumenti."
  },
  AvgDialog_18922_Content_17 = {
    Text = "Vediamo... delle monete, dei bottoni, e..."
  },
  AvgDialog_18922_Content_18 = {
    Text = "Una lettera?"
  },
  AvgDialog_18922_Content_19 = {
    Text = "Oh, fammi leggere cosa c'è scritto qui."
  },
  AvgDialog_18922_Content_2 = {Text = "Squeak!"},
  AvgDialog_18922_Content_20 = {
    Text = "Ehi, quella è mia!"
  },
  AvgDialog_18922_Content_21 = {
    Text = "Spiega la lettera. Contiene parole scarabocchiate frettolosamente, scritte in tutta fretta."
  },
  AvgDialog_18922_Content_22 = {
    Text = "Jenkin,\n\nCredo che non vivrò ancora a lungo @2\n\nStanno trasformando le persone in sculture di cera, e presto toccherà a me @4\n@2 Ho parlato con il Sig. Davis @1\n...Ti farà lavorare nella sua fabbrica.\nIl Sig. Davis è severo, ma offrono zuppa di piselli e pane nero a pranzo ogni giorno.\n<Yellow:Ricordati di non rispondergli male.>\n\nInoltre, ho lasciato tutti i soldi in @4"
  },
  AvgDialog_18922_Content_23 = {
    Text = "Si ferma alla fine."
  },
  AvgDialog_18922_Content_24 = {
    Text = "Ha un'espressione peculiare, come se fosse immersa in profondi pensieri, eppure la sua mente sembra essersi persa lontano."
  },
  AvgDialog_18922_Content_25 = {
    Text = "Perché hai smesso di leggere? C'è ancora dell'altro!"
  },
  AvgDialog_18922_Content_26 = {
    Text = "Ti mette la lettera in mano senza dire una parola."
  },
  AvgDialog_18922_Content_27 = {
    Text = "La apri — restano solo dei saluti e una firma."
  },
  AvgDialog_18922_Content_28 = {
    Text = "<Italic:...Ancora adesso, mi mancano i giorni in cui prendevamo il sole insieme a Wood Park.>"
  },
  AvgDialog_18922_Content_29 = {
    Text = "<Italic:Con amore, Mason.>"
  },
  AvgDialog_18922_Content_3 = {
    Text = "Brown, sei tornato!"
  },
  AvgDialog_18922_Content_30 = {
    Text = "È reale... Mia sorella esiste..."
  },
  AvgDialog_18922_Content_31 = {
    Text = "Non lavorerò per Davis!"
  },
  AvgDialog_18922_Content_32 = {
    Text = "La signorina Mason è stata sicuramente imprigionata qui. Ha corso rischi enormi per scrivere questa lettera."
  },
  AvgDialog_18922_Content_33 = {
    Text = "Non ha mai perso la speranza, e non si è mai dimenticata di te."
  },
  AvgDialog_18922_Content_34 = {
    Text = "Ma ormai non riesco nemmeno a ricordare il suo volto..."
  },
  AvgDialog_18922_Content_35 = {
    Text = "Sono inutile... Scusa, sorella..."
  },
  AvgDialog_18922_Content_36 = {
    Text = "Una mano si protende, posandosi delicatamente sulla mano di Jenkin."
  },
  AvgDialog_18922_Content_37 = {
    Text = "Questa mano è costellata di cicatrici. Immersa nella luce lunare, le vene livide e le ferite sono inconfondibili."
  },
  AvgDialog_18922_Content_38 = {
    Text = "Non piangere, e non scusarti."
  },
  AvgDialog_18922_Content_39 = {
    Text = "È quello di cui mi avevi avvertito."
  },
  AvgDialog_18922_Content_4 = {
    Text = "Brown giace debole tra le braccia di Jenkin, arricciando il naso prima di scoppiare in singhiozzi."
  },
  AvgDialog_18922_Content_40 = {Text = "24..."},
  AvgDialog_18922_Content_41 = {
    Text = "Almeno sei ancora viva, e c'è ancora speranza."
  },
  AvgDialog_18922_Content_42 = {
    Text = "Credo che anche tua sorella avrebbe sperato questo."
  },
  AvgDialog_18922_Content_43 = {Text = "..."},
  AvgDialog_18922_Content_44 = {
    Text = "Io... non stavo piangendo."
  },
  AvgDialog_18922_Content_45 = {
    Text = "Sei quasi normale quando non sei fuori di testa."
  },
  AvgDialog_18922_Content_46 = {
    Text = "La bambina risponde con tono imbronciato, con una qualità nasale appena percettibile."
  },
  AvgDialog_18922_Content_47 = {
    Text = "In ogni caso, finalmente trovi tracce di Mason."
  },
  AvgDialog_18922_Content_48 = {
    Text = "Finalmente buone notizie."
  },
  AvgDialog_18922_Content_5 = {
    Text = "Squeak... Squeak—!!"
  },
  AvgDialog_18922_Content_6 = {Text = "Hmm..."},
  AvgDialog_18922_Content_7 = {
    Text = "Brown dice che là sotto puzza, si sente malissimo."
  },
  AvgDialog_18922_Content_8 = {
    Text = "Oh cielo, anche i topi si ammalano? Che istruttivo."
  },
  AvgDialog_18922_Content_9 = {
    Text = "Brown non è un topo qualunque."
  },
  AvgDialog_18923_Content_1 = {
    Text = "Hai tentato di tutto, ma la botola resta inamovibile."
  },
  AvgDialog_18923_Content_10 = {
    Text = "La nostra indagine è stata scoperta. Ora entrambe le uscite rimanenti sono sorvegliate."
  },
  AvgDialog_18923_Content_11 = {
    Text = "Ho trovato una <Yellow:porta che conduce all'esterno> qui vicino. È particolare, chiusa dall'interno."
  },
  AvgDialog_18923_Content_12 = {
    Text = "Rogers deve averla manomessa; non può essere aperta con mezzi ordinari."
  },
  AvgDialog_18923_Content_13 = {
    Text = "Devi andare nell'<Yellow:Ufficio del Direttore>, ehm, e prendere una <Yellow:chiave>..."
  },
  AvgDialog_18923_Content_14 = {
    Text = "Ho trovato parecchie cose. Registri contabili, rapporti, contratti... abbastanza da tenere Rogers in prigione per il resto dei suoi giorni."
  },
  AvgDialog_18923_Content_15 = {
    Text = "Te li darò per sicurezza, allora—"
  },
  AvgDialog_18923_Content_16 = {Text = "Ahh—!!"},
  AvgDialog_18923_Content_17 = {
    Text = "La donna in bianco, lei... è scomparsa..."
  },
  AvgDialog_18923_Content_18 = {
    Text = "Volgi lo sguardo verso il punto in cui la donna si trovava. Ora è vuoto, con solo le tende bianche che ondeggiano nel vento."
  },
  AvgDialog_18923_Content_19 = {
    Text = "Scomparsa... cos'è successo?"
  },
  AvgDialog_18923_Content_2 = {
    Text = "Dannazione, non si apre..."
  },
  AvgDialog_18923_Content_20 = {
    Text = "Io... non lo so. Era qui un attimo fa..."
  },
  AvgDialog_18923_Content_21 = {
    Text = "Jenkin si precipita furioso verso 24 e le afferra la mano."
  },
  AvgDialog_18923_Content_22 = {
    Text = "Sei stata tu, vero? Vi ho sentite sussurrare. Vuoi ancora fingere di non conoscerla?"
  },
  AvgDialog_18923_Content_23 = {
    Text = "No, no... Signorina Jenkin, mi ascolti! Anche la polizia ha bisogno di prove per condannare un criminale..."
  },
  AvgDialog_18923_Content_24 = {
    Text = [[
Stavamo tutti osservando William, tranne voi due.
Siete ciechi e sordi?]]
  },
  AvgDialog_18923_Content_25 = {
    Text = "Sarà anche strana, ma se fosse davvero mia sorella..."
  },
  AvgDialog_18923_Content_26 = {
    Text = "Te lo chiedo di nuovo: dov'è andata?"
  },
  AvgDialog_18923_Content_27 = {
    Text = "Nella colluttazione, 24 cade a terra, i lunghi capelli scostati di lato."
  },
  AvgDialog_18923_Content_28 = {
    Text = "Cos'è questo... 0, 2, 4?"
  },
  AvgDialog_18923_Content_29 = {
    Text = "Sul collo chiaro della donna, si distingue un vistoso codice nero: \"024\"."
  },
  AvgDialog_18923_Content_3 = {
    Text = "Torna indietro."
  },
  AvgDialog_18923_Content_30 = {
    Text = "Hai visto segni simili da qualche altra parte, non molto tempo fa."
  },
  AvgDialog_18923_Content_31 = {
    Text = [[
Vedi questo? Marchiano ogni esemplare riuscito con un codice.
Il nostro <Blue:speciale, unico, insostituibile>...]]
  },
  AvgDialog_18923_Content_32 = {
    Text = "Quella è... l'Associazione degli Scultori..."
  },
  AvgDialog_18923_Content_33 = {Text = "?!"},
  AvgDialog_18923_Content_34 = {
    Text = "24 si aggrappa invano al collo, il volto estremamente pallido."
  },
  AvgDialog_18923_Content_35 = {
    Text = "Lo sapevo... È una bugiarda! E io in realtà..."
  },
  AvgDialog_18923_Content_36 = {
    Text = "Capisco. Eravamo tutti distratti dall'... episodio della Signorina 24."
  },
  AvgDialog_18923_Content_37 = {
    Text = "Nessuna vittima ordinaria potrebbe muoversi così liberamente in questo Museo delle Cere."
  },
  AvgDialog_18923_Content_38 = {Text = "No, no..."},
  AvgDialog_18923_Content_39 = {
    Text = "24 siede a terra, grattando meccanicamente il codice sul suo collo fino a ridurlo a un groviglio sanguinolento."
  },
  AvgDialog_18923_Content_4 = {Text = "Cosa...?"},
  AvgDialog_18923_Content_40 = {
    Text = "<Shake:Non è come pensate, non è come pensate...>"
  },
  AvgDialog_18923_Content_5 = {
    Text = "Ho detto: \"Torna indietro.\""
  },
  AvgDialog_18923_Content_6 = {
    Text = "Scherzi? Ci siamo appena riusciti a entrare!"
  },
  AvgDialog_18923_Content_7 = {
    Text = "Ci sono molti... mostri quaggiù, più di quanti tu possa affrontarne. Doll non ti aveva avvertito?"
  },
  AvgDialog_18923_Content_8 = {
    Text = "E tu? Non possiamo lasciarti qui."
  },
  AvgDialog_18923_Content_9 = {
    Text = "C'è una frattura di livello B, e ci vorrà molto tempo per gestirla. Non posso andarmene da qui.\nAscolta, lo dirò una volta sola—"
  },
  AvgDialog_18924_Content_1 = {
    Text = "Silenzio... sento qualcuno avvicinarsi. Al riparo."
  },
  AvgDialog_18924_Content_2 = {
    Text = "Che bella notte di luna!"
  },
  AvgDialog_18924_Content_3 = {
    Text = "Quand'ero viva, nelle notti come questa, mi sedevo sulla terrazza di marmo e mi versavo un bicchiere di vino..."
  },
  AvgDialog_18924_Content_4 = {
    Text = "Invece di fare l'ancella al Museo delle Cere come adesso, sniff sniff..."
  },
  AvgDialog_18924_Content_5 = {
    Text = "Dai, questa storia l'ho sentita cento volte. Mi si sono praticamente formate le callosità alle orecchie!"
  },
  AvgDialog_18924_Content_6 = {
    Text = "Tutti gli oggetti sono chiusi nell'armadio?"
  },
  AvgDialog_18924_Content_7 = {
    Text = "Tutto pronto, ho controllato tre volte!"
  },
  AvgDialog_18924_Content_8 = {
    Text = "Armadio...?"
  },
  AvgDialog_18924_Content_9 = {
    Text = "Andiamo a dare un'occhiata."
  },
  AvgDialog_18925_Content_1 = {
    Text = "Atterrata al suolo, la Donna ha ancora del Sangue che le macchia l'angolo della bocca."
  },
  AvgDialog_18925_Content_10 = {
    Text = "Quindi... Se mi rifiuto di rispondere, me la conficcherai dentro?"
  },
  AvgDialog_18925_Content_11 = {
    Text = "Lo farai con forza, bene a fondo?"
  },
  AvgDialog_18925_Content_12 = {
    Text = "Lo farai? Lo farai?"
  },
  AvgDialog_18925_Content_13 = {Text = "..."},
  AvgDialog_18925_Content_14 = {
    Text = "Se ti rifiuti di rispondere, non ti faremo del male. Ti ignoreremo semplicemente e ce ne andremo."
  },
  AvgDialog_18925_Content_15 = {Text = "È chiaro?"},
  AvgDialog_18925_Content_16 = {
    Text = "Oh... Capisco..."
  },
  AvgDialog_18925_Content_17 = {
    Text = "<Big:Fermati, Ramona!>"
  },
  AvgDialog_18925_Content_18 = {
    Text = "Jenkin si precipita verso la Donna, afferrandole urgentemente il polso e tirandola a sé."
  },
  AvgDialog_18925_Content_19 = {
    Text = "Sorella... Sei tu?"
  },
  AvgDialog_18925_Content_2 = {
    Text = "Oh cielo, il tuo Sangue ha un sapore così peculiare... Fa nuotare i miei pensieri in cerchio."
  },
  AvgDialog_18925_Content_20 = {
    Text = "Sorella...?"
  },
  AvgDialog_18925_Content_21 = {
    Text = "Il suo Sguardo errante si posa dolcemente su Jenkin, e dopo un istante, scoppia improvvisamente a ridere."
  },
  AvgDialog_18925_Content_22 = {
    Text = "Oh cielo. Se mi chiami sorella, devi appartenere a quella Vita che ho dimenticato."
  },
  AvgDialog_18925_Content_23 = {
    Text = "Rinchiusa sottoterra per tre gloriosi anni... 1235 giorni squisiti, per gentile concessione della mia amata famiglia."
  },
  AvgDialog_18925_Content_24 = {Text = "Cosa?!"},
  AvgDialog_18925_Content_25 = {
    Text = "Assurdo! Non ti farei mai una cosa del genere!"
  },
  AvgDialog_18925_Content_26 = {
    Text = "Hmm, perché no? La Dissoluzione aiuta. Da quando mi sono ammalata, la mia mente nuota in fiumi Cremisi di Sangue."
  },
  AvgDialog_18925_Content_27 = {
    Text = "Temevate che facessi del male agli altri, temevate che vi disonorassi, così mi avete nascosta per bene..."
  },
  AvgDialog_18925_Content_28 = {
    Text = "Jenkin, non è che ci stai nascondendo dei segreti, vero...?"
  },
  AvgDialog_18925_Content_29 = {
    Text = "La Donna balza agilmente su Jenkin, sollevando il suo polso delicato."
  },
  AvgDialog_18925_Content_3 = {
    Text = "Fammi indovinare, non sei del tutto umano, ma nemmeno del tutto un Risvegliato..."
  },
  AvgDialog_18925_Content_30 = {
    Text = "Vedi? Graziose Catene ai polsi, alle caviglie, persino questo bel collare intorno alla gola."
  },
  AvgDialog_18925_Content_31 = {
    Text = "Io... Io..."
  },
  AvgDialog_18925_Content_32 = {
    Text = "Tre anni di cocktail a base di Sangue di topo, e ora puzzo come il pavimento di un macellaio."
  },
  AvgDialog_18925_Content_33 = {
    Text = "Come potrei fare del male a mia sorella? Lei è... lei è..."
  },
  AvgDialog_18925_Content_34 = {
    Text = "È famiglia!"
  },
  AvgDialog_18925_Content_35 = {
    Text = "Il volto di Jenkin si fa rosso mentre stringe i pugni e fissa la donna con sguardo di sfida."
  },
  AvgDialog_18925_Content_36 = {
    Text = "...Famiglia?"
  },
  AvgDialog_18925_Content_37 = {
    Text = "Apparentemente non aspettandosi la risposta di Jenkin, la donna fino a poco prima così chiassosa finalmente tace."
  },
  AvgDialog_18925_Content_38 = {Text = "..."},
  AvgDialog_18925_Content_39 = {
    Text = "Scherzavo, topolino."
  },
  AvgDialog_18925_Content_4 = {
    Text = "Ramona si frappone tra voi, guardando la donna con cipiglio."
  },
  AvgDialog_18925_Content_40 = {
    Text = "Non ho famiglia, e di certo non sono vostra sorella. Mi state confondendo con qualcun altro."
  },
  AvgDialog_18925_Content_5 = {
    Text = "Chi sei? Perché sei qui?"
  },
  AvgDialog_18925_Content_6 = {
    Text = "Ma grazie comunque. Non mi nutro come si deve da una lunga settimana. La tua generosità è apprezzata..."
  },
  AvgDialog_18925_Content_7 = {
    Text = "Ramona sguaina il suo stocco e lo punta contro il petto della Donna."
  },
  AvgDialog_18925_Content_8 = {
    Text = "Non lo chiederò di nuovo."
  },
  AvgDialog_18925_Content_9 = {
    Text = "La Donna lancia un'occhiata alla Lama puntata contro di lei, i suoi Occhi tremolano brevemente prima che si raddrizzi di colpo."
  },
  AvgDialog_18926_Content_1 = {
    Text = "Ahi! Questo Tunnel è stretto, mi sono sbucciata le ginocchia..."
  },
  AvgDialog_18926_Content_2 = {
    Text = "Squeak... Sob... (Jenkin ha un forte Salasso... Sob...)"
  },
  AvgDialog_18926_Content_3 = {
    Text = "Solo un graffio. Vedi l'uscita? Salta giù verso l'ufficio del direttore!"
  },
  AvgDialog_18927_Content_1 = {Text = "..."},
  AvgDialog_18927_Content_2 = {
    Text = "Sfortuna, Brown. Non credo che ce la farò a uscire."
  },
  AvgDialog_18927_Content_3 = {
    Text = "Squeak... squeak squeak. (Jenkin... devi sentirti terribilmente in questo momento.)"
  },
  AvgDialog_18927_Content_4 = {
    Text = "Squeak, squeak? Squeak. (Riesci a resistere ancora un po'? Solo un altro momento? L'uscita è proprio qui davanti, squeak.)"
  },
  AvgDialog_18927_Content_5 = {
    Text = "Io... non so... Mi sento come se bruciassi..."
  },
  AvgDialog_18927_Content_6 = {
    Text = "Mi sento malissimo, la mente è confusa... Tutto è appiccicoso..."
  },
  AvgDialog_18927_Content_7 = {
    Text = "Non voglio ancora morire..."
  },
  AvgDialog_18927_Content_8 = {
    Text = "Squeak, squeak squeak. (Seguimi, Jenkin. Ti porterò fuori, squeak.)"
  },
  AvgDialog_18928_Content_1 = {
    Text = "Cos'è questa roba schifosa addosso a me..."
  },
  AvgDialog_18928_Content_2 = {Text = "?!"},
  AvgDialog_18928_Content_3 = {
    Text = "Me lo sarò immaginato! Non importa, ha... hah."
  },
  AvgDialog_18929_Content_1 = {
    Text = "Allora, come hai conquistato esattamente la signorina Doll?"
  },
  AvgDialog_18929_Content_2 = {
    Text = "Semplice. Ci spacciamo per visitatori e ci infiltriamo nel museo."
  },
  AvgDialog_18929_Content_3 = {
    Text = "Prima l'Esploratore, ritirata al primo segno di pericolo."
  },
  AvgDialog_18930_Content_1 = {
    Text = "Recitare è divertente?"
  },
  AvgDialog_18930_Content_2 = {
    Text = "...Non capisco cosa intendi."
  },
  AvgDialog_18930_Content_3 = {
    Text = "Non essere nervosa... Sono solo curiosa, non ti smaschererò."
  },
  AvgDialog_18930_Content_4 = {
    Text = "@3 allora. Non dirai una parola, vero?"
  },
  AvgDialog_18930_Content_5 = {
    Text = "Aspetta...!"
  },
  AvgDialog_18930_Content_6 = {Text = "Shh..."},
  AvgDialog_18931_Content_1 = {
    Text = "Malinconia Anatomica"
  },
  AvgDialog_18931_Content_10 = {
    Text = "Hai finto la Follia, ci hai seguiti, hai cercato di fare del male a mia sorella... o a qualcuno che potrebbe essere lei..."
  },
  AvgDialog_18931_Content_11 = {
    Text = "Devi essere una spia mandata da quella maledetta associazione!"
  },
  AvgDialog_18931_Content_12 = {Text = "..."},
  AvgDialog_18931_Content_13 = {Text = "..."},
  AvgDialog_18931_Content_14 = {
    Text = "Aaahh!! Perché non volete ascoltare la mia spiegazione?!"
  },
  AvgDialog_18931_Content_15 = {
    Text = "Di fronte alle tue domande implacabili, 24 improvvisamente perde il controllo."
  },
  AvgDialog_18931_Content_16 = {
    Text = "Ascoltatemi, voi @4 ASCOLTATEMI—!! AAAHHHH!!"
  },
  AvgDialog_18931_Content_17 = {
    Text = "<SmallShake:Va bene, ti ascolto... Ugh, sta perdendo il controllo...>"
  },
  AvgDialog_18931_Content_18 = {
    Text = "24 respira affannosamente, con le vene gonfie sul volto."
  },
  AvgDialog_18931_Content_19 = {
    Text = "Ehi, le vene sul tuo viso..."
  },
  AvgDialog_18931_Content_2 = {
    Text = "Vi prego, ascoltatemi! Mi hanno costretta! Sono stata io a spingervi..."
  },
  AvgDialog_18931_Content_20 = {
    Text = "Hehe... Sì, quello è lo sguardo. Capisco..."
  },
  AvgDialog_18931_Content_21 = {Text = "Terrore."},
  AvgDialog_18931_Content_22 = {Text = "Disgusto."},
  AvgDialog_18931_Content_23 = {
    Text = "<RedShake:Un mostro. Ecco cosa sono. Un orribile Mostro abbandonato come me...>"
  },
  AvgDialog_18931_Content_24 = {
    Text = "<RedShake:Nessuno mi si avvicina, nessuno si fida di me...>"
  },
  AvgDialog_18931_Content_25 = {
    Text = "Braccia rosso scuro emergono ancora una volta dall'interno di 24, stringendosi saldamente attorno al suo collo."
  },
  AvgDialog_18931_Content_26 = {
    Text = "<RedShake:Non sono un Mostro, non sono un Mostro...>"
  },
  AvgDialog_18931_Content_27 = {
    Text = "Sta perdendo di nuovo il controllo! Dobbiamo evacuare immediatamente!"
  },
  AvgDialog_18931_Content_28 = {
    Text = "Non sono un @4 mostro... AAAAHHHHH@2!!"
  },
  AvgDialog_18931_Content_3 = {
    Text = "Eri tu? Bene... Almeno lo ammetti!"
  },
  AvgDialog_18931_Content_4 = {
    Text = "Mi sono resa conto che sei in gamba, così ho deciso di unirmi a te..."
  },
  AvgDialog_18931_Content_5 = {
    Text = "Rispondi a una sola Domanda, Signorina 24: l'hai lasciata andare?"
  },
  AvgDialog_18931_Content_6 = {Text = "!!"},
  AvgDialog_18931_Content_7 = {
    Text = "Anche questo è stato un caso di coercizione?"
  },
  AvgDialog_18931_Content_8 = {
    Text = "In realtà..."
  },
  AvgDialog_18931_Content_9 = {
    Text = "Aspetta. Pensi davvero che ci berremo questa storia?"
  },
  AvgDialog_18932_Content_1 = {
    Text = "Aiuto... aiutatemi... mi sta divorando viva—"
  },
  AvgDialog_18932_Content_2 = {
    Text = "No, vi prego uccidetemi... fatela finita, FATELA FINITA!"
  },
  AvgDialog_18932_Content_3 = {Text = "...?"},
  AvgDialog_18933_Content_1 = {Text = "UUGHH!"},
  AvgDialog_18933_Content_2 = {
    Text = "Eh, è appena crollata a terra?"
  },
  AvgDialog_18933_Content_3 = {
    Text = "Andiamo a controllare."
  },
  AvgDialog_18934_Content_1 = {
    Text = "Andate avanti voi, vi copro io... N-non ho paura di lei!"
  },
  AvgDialog_18934_Content_2 = {
    Text = "...Stai calma. Mettiti dietro di me e resta lì."
  },
  AvgDialog_18935_Content_1 = {
    Text = "Casa delle Bambole"
  },
  AvgDialog_18935_Content_10 = {Text = "Madre..."},
  AvgDialog_18935_Content_11 = {
    Text = "Ti stai abituando sempre più alla presenza della Madre, a quanto vedo."
  },
  AvgDialog_18935_Content_12 = {
    Text = "...S-Signor Cera."
  },
  AvgDialog_18935_Content_13 = {
    Text = "Magnifica, non è vero? Prima era piuttosto insignificante."
  },
  AvgDialog_18935_Content_14 = {
    Text = "Una cantante di strada, poveretta, devastata dalla malattia — la pelle come una tela di lesioni scarlatte."
  },
  AvgDialog_18935_Content_15 = {
    Text = "Ho osservato la vita prosciugarsi dal suo corpo martoriato, poi ho raccolto i suoi pezzi per creare questa perfezione."
  },
  AvgDialog_18935_Content_16 = {
    Text = "Non riesco a capire... È Magia?"
  },
  AvgDialog_18935_Content_17 = {
    Text = "Questa non è Magia, bambina. Questa è l'arte della cera."
  },
  AvgDialog_18935_Content_18 = {
    Text = "L'arte della... cera..."
  },
  AvgDialog_18935_Content_19 = {
    Text = "Osservo la \"Madre\": la luce fioca delle candele conferisce al suo volto un bagliore simile alla giada, esaltando il sorriso sulle sue labbra."
  },
  AvgDialog_18935_Content_2 = {
    Text = [[
Estate, 295 d.C.
Scarborough, North Yorkshire]]
  },
  AvgDialog_18935_Content_20 = {
    Text = "Il mio sguardo percorre ogni centimetro, cercando di trovare su di lei una qualsiasi traccia di povertà o sofferenza, ma invano."
  },
  AvgDialog_18935_Content_21 = {
    Text = "Non hai voglia di parlare? Non temere, non ho ancora intenzione di scolpirti... Qui puoi parlare liberamente."
  },
  AvgDialog_18935_Content_22 = {
    Text = "Dicono che sono m-malata, che devo ricevere un trattamento, e che non dovrei parlare a sproposito."
  },
  AvgDialog_18935_Content_23 = {
    Text = "Balbuzie? Come la... curavano?"
  },
  AvgDialog_18935_Content_24 = {
    Text = "P-pinze da fuoco, e Tintura di @2..."
  },
  AvgDialog_18935_Content_25 = {
    Text = "Tintura di @2? Una medicina così rozza."
  },
  AvgDialog_18935_Content_26 = {
    Text = "Non lo so. La mamma diceva che avrebbe aiutato a r-rilassare i muscoli della gola."
  },
  AvgDialog_18935_Content_27 = {
    Text = "È stata un'esperienza dolorosa. La mamma era ossessionata da varie terapie \"innovative\" e mi manipolava come se fossi un suo giocattolo."
  },
  AvgDialog_18935_Content_28 = {
    Text = "Ogni mattina, mi facevano stare in piedi sui gradini alti, la bocca piena di ghiaia tagliente."
  },
  AvgDialog_18935_Content_29 = {
    Text = "<Italic:Canta.> La mamma mi ha detto di cantare."
  },
  AvgDialog_18935_Content_3 = {
    Text = "Il soriano del vecchio Charlie, grasso e caro,"
  },
  AvgDialog_18935_Content_30 = {
    Text = "Così cantavo a gran voce l'allegra canzone dell'alfabeto, con il sangue che sgorgava dalla bocca e mi colava giù fino al petto."
  },
  AvgDialog_18935_Content_31 = {
    Text = "Niente lacrime ora, bambina. Ogni scultura qui culla una tragedia."
  },
  AvgDialog_18935_Content_32 = {
    Text = "Sarebbero marciti senza che nessuno se ne accorgesse, i loro pianti trascinati nei rigagnoli dalla pioggia."
  },
  AvgDialog_18935_Content_33 = {
    Text = "Come se il loro Pain non fosse mai esistito."
  },
  AvgDialog_18935_Content_34 = {
    Text = "Mai... esistito..."
  },
  AvgDialog_18935_Content_35 = {
    Text = "Crudele, non è vero? Desideravo aiutare, ma questo scalpello arrugginito era tutto ciò che avevo."
  },
  AvgDialog_18935_Content_36 = {
    Text = "Così divenni il loro cronista... sebbene presto la mera documentazione cessò di soddisfarmi."
  },
  AvgDialog_18935_Content_37 = {
    Text = "Tu... li hai cambiati."
  },
  AvgDialog_18935_Content_38 = {
    Text = "Ricordare, poi ricreare: questo è il mio credo artistico."
  },
  AvgDialog_18935_Content_39 = {
    Text = "Un sentiero esigente, bambina mia, eppure infinitamente affascinante."
  },
  AvgDialog_18935_Content_4 = {
    Text = "Un giorno svanì—sparì nel nulla; cercò nell'armadio, controllò sotto il letto..."
  },
  AvgDialog_18935_Content_40 = {
    Text = "Quando verrà il tuo momento, dividerai i mari come i profeti di un tempo."
  },
  AvgDialog_18935_Content_41 = {
    Text = "Tenaglie o @2 tinture... simili inezie non avranno più importanza."
  },
  AvgDialog_18935_Content_42 = {
    Text = [[
22:15, Museo delle Cere di Rogers
Area espositiva]]
  },
  AvgDialog_18935_Content_43 = {
    Text = "Attraversi l'antico e logoro Museo delle Cere."
  },
  AvgDialog_18935_Content_44 = {
    Text = "Quasi nessuna luce naturale penetra nella sala, e le poche lampade a cherosene sparse qua e là fanno ben poco per dissipare l'atmosfera inquietante."
  },
  AvgDialog_18935_Content_45 = {
    Text = "Ho una Domanda..."
  },
  AvgDialog_18935_Content_46 = {
    Text = "Perché queste Sculture di Cera sorridono in modo così strano?"
  },
  AvgDialog_18935_Content_47 = {
    Text = "Osservi queste sculture di cera squisitamente lavorate."
  },
  AvgDialog_18935_Content_48 = {
    Text = "Alcune con le labbra serrate, altre assopite, altre ancora con il parasole in mano... L'unica cosa che hanno in comune è il loro sorriso radioso."
  },
  AvgDialog_18935_Content_49 = {
    Text = [[
Inquietante. Davvero.
Sono felici? Ma i loro occhi sono completamente spenti.]]
  },
  AvgDialog_18935_Content_5 = {Text = "..."},
  AvgDialog_18935_Content_50 = {
    Text = "Se vuoi il mio parere, Rogers è tutto fumo e niente arrosto."
  },
  AvgDialog_18935_Content_51 = {
    Text = [[
Secondo il nostro database, la "risata" sembra essere uno dei temi ricorrenti di Rogers.
Sei d'accordo, Doll?]]
  },
  AvgDialog_18935_Content_52 = {Text = "Bambola?"},
  AvgDialog_18935_Content_53 = {
    Text = "<Italic:Shhhh... Shhhhh...>"
  },
  AvgDialog_18935_Content_54 = {
    Text = "Tocchi la spilla, ma non c'è risposta. L'intero Museo delle Cere è silenzioso come un'enorme tomba."
  },
  AvgDialog_18935_Content_55 = {
    Text = "Il Comunicatore funziona bene, ma il segnale è appena caduto... Cos'è successo?"
  },
  AvgDialog_18935_Content_56 = {
    Text = "Quando siamo entrati nel Museo delle Cere, mi è parso di sentire una corrente elettrica... Qualcosa sta interferendo con la comunicazione?"
  },
  AvgDialog_18935_Content_57 = {Text = "!!"},
  AvgDialog_18935_Content_58 = {
    Text = "L'ho sentito anch'io."
  },
  AvgDialog_18935_Content_59 = {
    Text = "E adesso? Il piano richiede l'assistenza della Signorina Doll..."
  },
  AvgDialog_18935_Content_6 = {
    Text = "Madre, canto bene??"
  },
  AvgDialog_18935_Content_60 = {
    Text = "Opera di Pandia, forse. Torniamo da lei."
  },
  AvgDialog_18935_Content_7 = {
    Text = "Oggi segna il quindicesimo giorno trascorso con \"Galatea\", la mia nuova Madre."
  },
  AvgDialog_18935_Content_8 = {
    Text = "Guardando il suo volto gentile e i suoi modi impeccabilmente curati, sento un'improvvisa ondata di emozione."
  },
  AvgDialog_18935_Content_9 = {
    Text = "Appoggio dolcemente la testa contro il suo petto."
  },
  AvgDialog_18936_Content_1 = {
    Text = "Perché tornare da lei... Mi sembra losca."
  },
  AvgDialog_18936_Content_2 = {
    Text = "Possiamo usare il telefono della reception per diagnosticare il guasto nelle comunicazioni."
  },
  AvgDialog_18936_Content_3 = {
    Text = "Capito! Le daremo una lezione se c'è lei dietro a tutto questo."
  },
  AvgDialog_18937_Content_1 = {
    Text = "Buhuhu, chi mi restituirà le mie povere budella rovesciate..."
  },
  AvgDialog_18937_Content_2 = {
    Text = "Tieni, riprenditi questo!"
  },
  AvgDialog_18937_Content_3 = {
    Text = "Non rientrano... Sniff sniff..."
  },
  AvgDialog_18938_Content_1 = {Text = "Galatea"},
  AvgDialog_18938_Content_10 = {
    Text = "I miei genitori sono persone rispettabili e facoltose. Vi daranno del denaro..."
  },
  AvgDialog_18938_Content_11 = {
    Text = "Purché mi lasciate andare."
  },
  AvgDialog_18938_Content_12 = {
    Text = "Shh... Silenzio, disturberai il suo riposo."
  },
  AvgDialog_18938_Content_13 = {
    Text = "Vieni qui, piccola."
  },
  AvgDialog_18938_Content_14 = {
    Text = "Più vicina, non c'è bisogno di aver paura."
  },
  AvgDialog_18938_Content_15 = {
    Text = "Osserva le sue mani. Non sono squisite?"
  },
  AvgDialog_18938_Content_16 = {
    Text = "Persino il marmo più puro piangerebbe d'invidia."
  },
  AvgDialog_18938_Content_17 = {
    Text = "<Shake:B...Bellissime, signore.>"
  },
  AvgDialog_18938_Content_18 = {
    Text = "Che sventura... Non vedo ammirazione nei vostri Occhi, solo repulsione..."
  },
  AvgDialog_18938_Content_19 = {
    Text = "No, non è... La prego, mi dia un'altra possibilità!"
  },
  AvgDialog_18938_Content_2 = {
    Text = [[
Estate, 295 d.C.
Scarborough, North Yorkshire]]
  },
  AvgDialog_18938_Content_20 = {
    Text = "Non importa, ti istruirò a dovere e solleverò il velo dai tuoi occhi ignoranti.\nOra, la prima lezione—"
  },
  AvgDialog_18938_Content_21 = {
    Text = "In ginocchio."
  },
  AvgDialog_18938_Content_22 = {
    Text = "Ora ti ordino, in ginocchio."
  },
  AvgDialog_18938_Content_23 = {
    Text = "In ginocchio, e premi le tue labbra reverenti..."
  },
  AvgDialog_18938_Content_24 = {
    Text = "Su Galatea, sulla tua \"Madre.\""
  },
  AvgDialog_18938_Content_25 = {
    Text = "Quella fu la prima volta che baciai la \"Madre.\""
  },
  AvgDialog_18938_Content_26 = {
    Text = "La Mano pallida, avvolta con cura in Olio di Cera appiccicoso, emanava un debole fetore sotto il calore rovente della mezza estate di Scarborough."
  },
  AvgDialog_18938_Content_27 = {
    Text = "Era l'odore della morte."
  },
  AvgDialog_18938_Content_28 = {
    Text = "21:00, Via Southwark"
  },
  AvgDialog_18938_Content_29 = {
    Text = "Chiamata al Comunicatore I-2069, chiamata al Comunicatore I-2069..."
  },
  AvgDialog_18938_Content_3 = {
    Text = "Questa è la mia creazione più preziosa—Galatea."
  },
  AvgDialog_18938_Content_30 = {
    Text = "Il venticinquesimo tentativo di comunicazione è fallito. Abbiamo perso il collegamento con l'Investigatore William Delapore."
  },
  AvgDialog_18938_Content_31 = {
    Text = "Riuscite a mettervi in contatto con i Detective che accompagnano William?"
  },
  AvgDialog_18938_Content_32 = {
    Text = "Purtroppo no.\nChiudiamo qui per oggi e facciamo rapporto ai Mythag. Nessuna mossa avventata finché non avremo più informazioni."
  },
  AvgDialog_18938_Content_33 = {
    Text = "Tutto qui? Ma abbiamo perso i contatti con William, e potrebbe essere..."
  },
  AvgDialog_18938_Content_34 = {
    Text = "Branco di fifoni."
  },
  AvgDialog_18938_Content_35 = {
    Text = "Ora, se volete scusarmi, mia sorella non ha tempo per le vostre scartoffie interminabili."
  },
  AvgDialog_18938_Content_36 = {
    Text = "Posso andare al Museo delle Cere da solo."
  },
  AvgDialog_18938_Content_37 = {Text = "Squeak!"},
  AvgDialog_18938_Content_38 = {
    Text = "Detto questo, Jenkin si volta e si tuffa nella fitta nebbia."
  },
  AvgDialog_18938_Content_39 = {
    Text = "Jenkin! Non farlo! È troppo pericoloso!"
  },
  AvgDialog_18938_Content_4 = {
    Text = "Hai mai sentito la storia di <Blue:Pigmalione>?"
  },
  AvgDialog_18938_Content_40 = {Text = "Andiamo."},
  AvgDialog_18938_Content_5 = {
    Text = "Scolpì dall'avorio una fanciulla perfetta, vestendola e accarezzandola come la sua amata sposa..."
  },
  AvgDialog_18938_Content_6 = {
    Text = "Riversando in lei tutta la sua devozione."
  },
  AvgDialog_18938_Content_7 = {
    Text = "\"Galatea\"—un nome incantevole, non trovi?"
  },
  AvgDialog_18938_Content_8 = {
    Text = "Perdona le mie divagazioni. Devi trovarle noiose."
  },
  AvgDialog_18938_Content_9 = {
    Text = "No, no, signore. La prego, signore..."
  },
  AvgDialog_18939_Content_1 = {
    Text = "Estate di Scarborough"
  },
  AvgDialog_18939_Content_10 = {
    Text = "George, mi chiamo George."
  },
  AvgDialog_18939_Content_11 = {
    Text = "Giugno @1, AF 295"
  },
  AvgDialog_18939_Content_12 = {
    Text = "Fu una giornata caotica, finché non aprirono la porta della cantina, lasciando entrare la luce del sole..."
  },
  AvgDialog_18939_Content_13 = {
    Text = "Solo allora capii che il mio giardino, il mio regno, non era che un angusto seminterrato."
  },
  AvgDialog_18939_Content_14 = {
    Text = "Bambina! Bambina mia... Finalmente ti ho trovata!"
  },
  AvgDialog_18939_Content_15 = {
    Text = "Presto, vieni via di qui con la mamma e non tornare mai più..."
  },
  AvgDialog_18939_Content_16 = {Text = "George..."},
  AvgDialog_18939_Content_17 = {Text = "...Cosa?"},
  AvgDialog_18939_Content_18 = {
    Text = "George... Voglio andare con George."
  },
  AvgDialog_18939_Content_19 = {
    Text = "\"George\"? Intendi questa piccola Scultura di Cera?"
  },
  AvgDialog_18939_Content_2 = {
    Text = [[
Estate, 295 d.C.
Scarborough, North Yorkshire]]
  },
  AvgDialog_18939_Content_20 = {
    Text = "George! Per favore, per favore ridammelo—"
  },
  AvgDialog_18939_Content_21 = {
    Text = "Non avere fretta, piccola. Prima rispondi alla mia Domanda."
  },
  AvgDialog_18939_Content_22 = {
    Text = "<Yellow:Dove è andato il \"Signor Cera\"?>"
  },
  AvgDialog_18939_Content_23 = {
    Text = "Il Signor Cera...? I-Io non so di cosa stia parlando..."
  },
  AvgDialog_18939_Content_24 = {
    Text = "Hehe. Davvero non lo sai? Lascia che ti faccia un'altra domanda."
  },
  AvgDialog_18939_Content_25 = {
    Text = "<Yellow:Com'è nata questa Scultura di Cera?>"
  },
  AvgDialog_18939_Content_26 = {Text = "..."},
  AvgDialog_18939_Content_27 = {
    Text = "<Shake:Mamma, io... ho paura.>"
  },
  AvgDialog_18939_Content_28 = {
    Text = "Detective, modera i toni."
  },
  AvgDialog_18939_Content_29 = {
    Text = "Qualora la Sua indagine richiedesse qualcosa da parte nostra, non esiti a contattare il nostro avvocato Franz @1. Buona giornata."
  },
  AvgDialog_18939_Content_3 = {
    Text = "È morto. Ora siamo solo tu e io."
  },
  AvgDialog_18939_Content_30 = {
    Text = "La donna elegantemente vestita solleva il mento appuntito, lancia un'occhiata di traverso al detective, poi prende il ragazzo e se ne va."
  },
  AvgDialog_18939_Content_31 = {
    Text = "Hehe... Interessante."
  },
  AvgDialog_18939_Content_32 = {
    Text = "Lo studio! Finalmente! Alla fine SEI utile!"
  },
  AvgDialog_18939_Content_33 = {
    Text = "D-davvero... Grazie..."
  },
  AvgDialog_18939_Content_34 = {
    Text = "Ti guardi intorno. È un altro luogo Oscuro."
  },
  AvgDialog_18939_Content_35 = {
    Text = "La lampada a muro nell'angolo tremola debolmente, gettando una sfumatura grigiastra sul chiaro di luna che filtra dalla finestra."
  },
  AvgDialog_18939_Content_36 = {
    Text = "Una stanza vuota colma di braccia, gambe, teste e torsi di cera..."
  },
  AvgDialog_18939_Content_37 = {
    Text = "Sono come calzini morbidi e strappati, ammucchiati alla rinfusa su panche, tavoli da lavoro e pavimenti."
  },
  AvgDialog_18939_Content_38 = {
    Text = "Freeman, il piccolo John, Luke Quattrodita..."
  },
  AvgDialog_18939_Content_39 = {
    Text = "Sono tutte persone che conoscevo a White Chapel!"
  },
  AvgDialog_18939_Content_4 = {
    Text = "Come ti chiami?"
  },
  AvgDialog_18939_Content_40 = {
    Text = [[
Questo conferma il coinvolgimento di Rogers.
Inoltre, implica fortemente Gli scultori.]]
  },
  AvgDialog_18939_Content_41 = {
    Text = "Ramona punzecchia gli arti ammassati mentre parla."
  },
  AvgDialog_18939_Content_42 = {
    Text = "Tutti questi esemplari mostrano segni di sperimentazione, coerenti con ciò che abbiamo visto nell'Ospizio dei Poveri."
  },
  AvgDialog_18939_Content_43 = {
    Text = "Lo sapevo... Anche Aigis è stata una sua vittima..."
  },
  AvgDialog_18939_Content_44 = {
    Text = "Lo troverò e gliela farò pagare."
  },
  AvgDialog_18939_Content_45 = {
    Text = "Rogers deve affrontare la giustizia. Ma prima, dobbiamo localizzare la \"Primavera\"."
  },
  AvgDialog_18939_Content_46 = {
    Text = "Trovare cose è il mio forte. Lascia fare a me!"
  },
  AvgDialog_18939_Content_5 = {Text = "G-Geor..."},
  AvgDialog_18939_Content_6 = {
    Text = "Geor... ge..."
  },
  AvgDialog_18939_Content_7 = {
    Text = "Ricorda, tu e io siamo diversi. Tu non b-balbutti."
  },
  AvgDialog_18939_Content_8 = {
    Text = "E-esercitiamoci ancora. Come ti chiami?"
  },
  AvgDialog_18939_Content_9 = {Text = "..."},
  AvgDialog_18940_Content_1 = {
    Text = "Fanciulla e Lacrime"
  },
  AvgDialog_18940_Content_10 = {
    Text = "George si rannicchia tra le braccia di Rogers e lancia uno strido accusatorio."
  },
  AvgDialog_18940_Content_11 = {
    Text = "Rogers accarezza con affetto la soffice testa d'oro di George e lascia sfuggire un sospiro."
  },
  AvgDialog_18940_Content_12 = {
    Text = "Una bambina qualunque? La piccola Jenkin ha sfidato il Museo delle Cere per sua sorella."
  },
  AvgDialog_18940_Content_13 = {
    Text = "Non è vero, <Yellow:Signorina Mason>?"
  },
  AvgDialog_18940_Content_14 = {
    Text = "Signorina Mason?!"
  },
  AvgDialog_18940_Content_15 = {
    Text = "Mason... Sei davvero la mia sorellina?"
  },
  AvgDialog_18940_Content_16 = {Text = "..."},
  AvgDialog_18940_Content_17 = {
    Text = "24 sospira piano e allunga le braccia per abbracciare Jenkin."
  },
  AvgDialog_18940_Content_18 = {
    Text = "Gli odori familiari la investono, risvegliando memorie a lungo sepolte di innumerevoli giorni e notti."
  },
  AvgDialog_18940_Content_19 = {
    Text = "Sei davvero tu, sorella... Allora non era un sogno. Che bello..."
  },
  AvgDialog_18940_Content_2 = {
    Text = [[
3:00, Museo delle Cere di Rogers
Area Esposizione Speciale]]
  },
  AvgDialog_18940_Content_20 = {
    Text = "Jenkin, tu non sei un topo indesiderato. Hai ancora me e Brown."
  },
  AvgDialog_18940_Content_21 = {
    Text = "Non preoccuparti, non permetterò che ti portino via."
  },
  AvgDialog_18940_Content_22 = {
    Text = "24 sfiora delicatamente la guancia di Jenkin, poi si volta e guarda con calma Rogers e i suoi scagnozzi."
  },
  AvgDialog_18940_Content_23 = {
    Text = "Lady Pandia, Maestro Rogers, avevamo un accordo."
  },
  AvgDialog_18940_Content_24 = {
    Text = "Te li porterò io. E in cambio, Jenkin se ne va libera."
  },
  AvgDialog_18940_Content_25 = {Text = "Perché..."},
  AvgDialog_18940_Content_26 = {
    Text = "SCHIAFFO—!"
  },
  AvgDialog_18940_Content_27 = {
    Text = "La frusta si abbatte senza pietà, lasciando un feroce segno rosso sul volto di 24."
  },
  AvgDialog_18940_Content_28 = {Text = "UGH!"},
  AvgDialog_18940_Content_29 = {
    Text = [[
Devi mettere in discussione tutto?
Quando stavi vandalizzando il mio museo, hai pensato alle conseguenze?]]
  },
  AvgDialog_18940_Content_3 = {Text = "Aspettare?"},
  AvgDialog_18940_Content_30 = {
    Text = "Lo dirò una sola volta. Toglietevi di mezzo."
  },
  AvgDialog_18940_Content_31 = {
    Text = "24 si erge davanti a Jenkin, le sue scapole sottili tremano come ali di farfalla."
  },
  AvgDialog_18940_Content_32 = {
    Text = "Riesce ad abbozzare un debole sorriso, ma sembra più doloroso di un pianto."
  },
  AvgDialog_18940_Content_33 = {
    Text = "Se la lasciate andare, mi farò da parte..."
  },
  AvgDialog_18940_Content_34 = {
    Text = "SCHIAFFO—!"
  },
  AvgDialog_18940_Content_35 = {
    Text = "Innumerevoli frustate cadono come gocce di pioggia."
  },
  AvgDialog_18940_Content_36 = {
    Text = "Che seccatura, le mie braccia si stancano. Hai intenzione di morire qui oggi, 24?"
  },
  AvgDialog_18940_Content_37 = {
    Text = "Perdere un animale domestico così obbediente farebbe venire le lacrime persino a me."
  },
  AvgDialog_18940_Content_38 = {
    Text = "Mio signore, vi prego, abbiate pietà... Lasciatela andare, e farò qualsiasi cosa..."
  },
  AvgDialog_18940_Content_39 = {
    Text = "Resterò nella sala per sempre, proprio come speravate. Basta fuggire in giro..."
  },
  AvgDialog_18940_Content_4 = {
    Text = "Hai concepito un addestramento ancor più delizioso per il nostro topolino? Condividilo con la classe, 24."
  },
  AvgDialog_18940_Content_40 = {
    Text = "SCHIAFFO—!"
  },
  AvgDialog_18940_Content_41 = {
    Text = "SCHIAFFO—!"
  },
  AvgDialog_18940_Content_42 = {
    Text = "In poco tempo, il corpo di 24 è coperto di lividi.\nMa lei non si muove, continua solo a mormorare le stesse parole."
  },
  AvgDialog_18940_Content_43 = {
    Text = "<Shake:L-Lasciatela andare... Vi prego...>"
  },
  AvgDialog_18940_Content_44 = {
    Text = "<Shake:Lasciatela andare...>"
  },
  AvgDialog_18940_Content_45 = {
    Text = "Avanti, perdenti! Non..."
  },
  AvgDialog_18940_Content_46 = {
    Text = "<Shake:Non fate del male alla mia sorellina...>"
  },
  AvgDialog_18940_Content_47 = {
    Text = "<Gray:Accidenti... Non riesco a muovere un muscolo. Devo recuperare quella Chiave d'Argento...>"
  },
  AvgDialog_18940_Content_48 = {
    Text = "Hmm, basta divertirsi per ora. Qualcuno la trascini via."
  },
  AvgDialog_18940_Content_49 = {
    Text = "Come desiderate!"
  },
  AvgDialog_18940_Content_5 = {
    Text = "Mia signora... È solo una bambina qualunque dei bassifondi. Non rappresenta alcuna minaccia."
  },
  AvgDialog_18940_Content_50 = {
    Text = "No... Non me ne vado. Non avete ancora accettato..."
  },
  AvgDialog_18940_Content_51 = {
    Text = "<Big:Basta parlare. Muovetevi!>"
  },
  AvgDialog_18940_Content_52 = {
    Text = "Nonostante la futile resistenza di 24, la trascinarono via come uno straccio."
  },
  AvgDialog_18940_Content_53 = {
    Text = "Mentre passa accanto a te, 24 alza improvvisamente lo sguardo e si lancia contro di te."
  },
  AvgDialog_18940_Content_54 = {
    Text = "La Chiave... %player%, la Chiave d'Argento, puoi usarla in battaglia, vero?"
  },
  AvgDialog_18940_Content_55 = {Text = "Cosa...?"},
  AvgDialog_18940_Content_56 = {
    Text = "Quella Chiave d'Argento ha funzionato su di me! Crea un Legame con me, salviamola insieme!"
  },
  AvgDialog_18940_Content_57 = {
    Text = "No, non siete un Risvegliatore. Non posso assolutamente—"
  },
  AvgDialog_18940_Content_58 = {Text = "Bang—!"},
  AvgDialog_18940_Content_59 = {
    Text = "Non avere idee strane, o ti faccio saltare le cervella seduta stante!"
  },
  AvgDialog_18940_Content_6 = {
    Text = "Non possiamo semplicemente lasciarla andare..."
  },
  AvgDialog_18940_Content_60 = {
    Text = "Quel pugno non fa indietreggiare 24. Miracolosamente, si libera dalle costrizioni e si lancia verso di te."
  },
  AvgDialog_18940_Content_61 = {
    Text = "Ti strappa la Chiave d'Argento dal petto e te la posa nel palmo della mano."
  },
  AvgDialog_18940_Content_62 = {
    Text = "Prendetela, non lasciatela scappare!"
  },
  AvgDialog_18940_Content_63 = {
    Text = "Non si sa finché non si prova! Sono stata oggetto di esperimenti; forse posso essere come loro..."
  },
  AvgDialog_18940_Content_64 = {
    Text = "Se lo tieni tu, io posso combattere, giusto?"
  },
  AvgDialog_18940_Content_65 = {Text = "..."},
  AvgDialog_18940_Content_66 = {
    Text = "D'accordo. Ci provo."
  },
  AvgDialog_18940_Content_67 = {
    Text = "Attivi la Chiave d'Argento nella tua mano. Il suo freddo Bagliore risplende sul tuo petto, illuminando il volto di 24—"
  },
  AvgDialog_18940_Content_68 = {
    Text = "Pallida, fragile, eppure irremovibile."
  },
  AvgDialog_18940_Content_69 = {
    Text = "24, ti ordino!"
  },
  AvgDialog_18940_Content_7 = {Text = "Tre volte."},
  AvgDialog_18940_Content_8 = {
    Text = "Mi ha chiamata maiale 3 volte, idiota 2 volte, e @2 5 volte."
  },
  AvgDialog_18940_Content_9 = {
    Text = "Ha offeso George! Jenkin deve morire! Deve morire!"
  },
  AvgDialog_18941_Content_1 = {
    Text = "Manuale del Medico"
  },
  AvgDialog_18941_Content_10 = {
    Text = "Aiuto... aiutatemi... mi sta divorando viva—"
  },
  AvgDialog_18941_Content_11 = {
    Text = "D-melma nera le colava dalle orbite, densa e incessante, eppure lei sembrava non accorgersene."
  },
  AvgDialog_18941_Content_12 = {
    Text = "Cosa brutta! George non vuole guardare quella cosa brutta!"
  },
  AvgDialog_18941_Content_13 = {
    Text = "Allungai la mano e premetti il palmo sul suo occhio destro."
  },
  AvgDialog_18941_Content_14 = {
    Text = "Così è meglio, m-molto meglio. Vuoi sopravvivere?"
  },
  AvgDialog_18941_Content_15 = {
    Text = "La bambina annuì con tutta la sua possanza."
  },
  AvgDialog_18941_Content_16 = {
    Text = "Non preoccuparti, esaudirò il tuo desiderio."
  },
  AvgDialog_18941_Content_17 = {
    Text = "Ma in un altro modo."
  },
  AvgDialog_18941_Content_18 = {
    Text = "Eccovi, signor Rogers."
  },
  AvgDialog_18941_Content_19 = {
    Text = "E tu saresti...?"
  },
  AvgDialog_18941_Content_2 = {
    Text = "È una sostanza nera e viscosa."
  },
  AvgDialog_18941_Content_20 = {
    Text = "Puoi chiamarmi <Yellow:Herbert>. Sono molto interessato alle tue arti della cera... C'è un bel bar dall'altra parte della strada. Ti va di bere qualcosa?"
  },
  AvgDialog_18941_Content_21 = {
    Text = "Avete bevuto insieme. Cosa accadde dopo?"
  },
  AvgDialog_18941_Content_22 = {
    Text = "In seguito, accettai l'invito del <Blue:Sig. Herbert> a unirmi a lui nella ricerca di alcuni a-argomenti."
  },
  AvgDialog_18941_Content_23 = {
    Text = "In cambio, mi avrebbe fornito dei \"materiali\" per le sculture di cera."
  },
  AvgDialog_18941_Content_24 = {
    Text = "Capisco. Ho compreso appieno la vostra storia, dunque..."
  },
  AvgDialog_18941_Content_25 = {
    Text = "Signor Rogers, avete ucciso il \"Signor Cera.\""
  },
  AvgDialog_18941_Content_26 = {
    Text = "Avete ucciso la donna nella neve."
  },
  AvgDialog_18941_Content_27 = {
    Text = "Avete ucciso anche quei fanciulli. Sbaglio forse?"
  },
  AvgDialog_18941_Content_28 = {
    Text = "Io... io non ho mai..."
  },
  AvgDialog_18941_Content_29 = {
    Text = "Oh? Li ho visti chiaramente all'Ospizio dei Poveri — quei fanciulli scomparsi."
  },
  AvgDialog_18941_Content_3 = {
    Text = "Sgorga dalle fessure sotterranee, gocciola lungo le venature delle foglie, e fluisce persino dalla bocca delle persone."
  },
  AvgDialog_18941_Content_30 = {
    Text = "Sig. Rogers, dal momento che ha scelto di sottoporsi al trattamento, la prego di essere sincero con me."
  },
  AvgDialog_18941_Content_31 = {
    Text = "Abbiamo bisogno di fiducia tra noi."
  },
  AvgDialog_18941_Content_32 = {
    Text = "È d-davvero importante, signorina Clementine?"
  },
  AvgDialog_18941_Content_33 = {
    Text = "Se sia importante dipende dalla vostra risposta. Prima di allora, tutto resta sconosciuto."
  },
  AvgDialog_18941_Content_34 = {
    Text = "Tuttavia, a volte è proprio questo senso dell'ignoto ad attrarci..."
  },
  AvgDialog_18941_Content_35 = {
    Text = "Mi scusi, signor Rogers, non avrei dovuto insistere così."
  },
  AvgDialog_18941_Content_36 = {
    Text = "Smettila di giocare, stronza. Ti stai godendo l'Agonia del Maestro Rogers, vero?"
  },
  AvgDialog_18941_Content_37 = {
    Text = "Il padrone Rogers non dice mai bugie."
  },
  AvgDialog_18941_Content_38 = {
    Text = "Non abbiamo mai ucciso; abbiamo solo... aiutato."
  },
  AvgDialog_18941_Content_39 = {
    Text = "Realizziamo i loro sogni di sculture di cera."
  },
  AvgDialog_18941_Content_4 = {
    Text = "La chiamiamo \"Dissoluzione.\" È ovunque, eppure invisibile."
  },
  AvgDialog_18941_Content_40 = {
    Text = "Persona sbagliata? Impossibile, indossi i loro vestiti..."
  },
  AvgDialog_18941_Content_41 = {
    Text = "La \"Primavera\" è un Gruppo di Sculture di Cera. Stai dicendo che siamo tutte tue sorelle?"
  },
  AvgDialog_18941_Content_42 = {
    Text = "C'è stato un tempo in cui il Maestro Rogers ci vestiva con abitini coordinati, come perfetti manichini congelati."
  },
  AvgDialog_18941_Content_43 = {
    Text = "La Donna solleva l'orlo del suo Vestito, lo strofina delicatamente, poi se lo porta al naso per annusarlo."
  },
  AvgDialog_18941_Content_44 = {
    Text = "Puah, puzza. Peccato che non indosso abiti decenti da un'eternità."
  },
  AvgDialog_18941_Content_45 = {
    Text = "Hai appena detto <Yellow:Maestro Rogers?> Sei una dei suoi subordinati?"
  },
  AvgDialog_18941_Content_46 = {
    Text = "Beh, questa è un'altra Domanda. Cosa mi... darai in cambio?"
  },
  AvgDialog_18941_Content_47 = {
    Text = "In cambio? Molto bene, eccolo."
  },
  AvgDialog_18941_Content_48 = {
    Text = "Ramona inspira profondamente e improvvisamente conficca la sua Spada nella spalla di Leigh."
  },
  AvgDialog_18941_Content_49 = {Text = "Ramona!!!"},
  AvgDialog_18941_Content_5 = {
    Text = "Le persone infettate dalla Dissoluzione verranno gradualmente dimenticate dal mondo."
  },
  AvgDialog_18941_Content_50 = {
    Text = "Ferma. So cosa sto facendo."
  },
  AvgDialog_18941_Content_51 = {
    Text = "Ora, signorina, abbiamo poco tempo. Può darci una risposta diretta?"
  },
  AvgDialog_18941_Content_52 = {
    Text = "Il volto pallido della Donna si tinge di rosso. Trema mentre ride."
  },
  AvgDialog_18941_Content_53 = {
    Text = "...Bene... Così meravigliosamente bene... Il dolore è semplicemente perfetto..."
  },
  AvgDialog_18941_Content_54 = {
    Text = "Se avete domande, prego... chiedete pure."
  },
  AvgDialog_18941_Content_55 = {
    Text = "Chi vi ha dato l'ordine?"
  },
  AvgDialog_18941_Content_56 = {
    Text = "Mi dispiace... Questa è l'unica risposta che non potrò mai darvi."
  },
  AvgDialog_18941_Content_57 = {Text = "Perché?"},
  AvgDialog_18941_Content_58 = {Text = "Per amore."},
  AvgDialog_18941_Content_59 = {Text = "...Eh?"},
  AvgDialog_18941_Content_6 = {
    Text = "Lettere, registri, fotografie... Ogni prova della sua esistenza verrà cancellata. È come se..."
  },
  AvgDialog_18941_Content_60 = {
    Text = "Un amore atroce, bruciante, senza speranza!"
  },
  AvgDialog_18941_Content_61 = {
    Text = "Sul suo gelido Altare, offro i miei singhiozzi, i miei Sussurri, e il mio più..."
  },
  AvgDialog_18941_Content_62 = {
    Text = "Anima preziosa!"
  },
  AvgDialog_18941_Content_63 = {Text = "..."},
  AvgDialog_18941_Content_64 = {
    Text = "Perché siete diventato un Risvegliatore?"
  },
  AvgDialog_18941_Content_65 = {
    Text = "Per sopravvivere, ovviamente. Il mio sacro voto a @1..."
  },
  AvgDialog_18941_Content_66 = {
    Text = "La Donna accarezza delicatamente il codice nero sbiadito sul suo polso, la Voce morbida e melliflua."
  },
  AvgDialog_18941_Content_67 = {
    Text = [[
Vedi questo? Marchiano ogni esemplare riuscito con un codice.
Il nostro <Blue:speciale, unico, insostituibile>...]]
  },
  AvgDialog_18941_Content_68 = {
    Text = "\"Loro\"... Ti riferisci all'Associazione degli Scultori?"
  },
  AvgDialog_18941_Content_69 = {
    Text = "Non risponde, confermando apparentemente la tua ipotesi."
  },
  AvgDialog_18941_Content_7 = {
    Text = "Non sono mai esistiti in questo mondo."
  },
  AvgDialog_18941_Content_70 = {Text = "..."},
  AvgDialog_18941_Content_71 = {
    Text = "Una come lei è davvero mia sorella...? Tu che ne pensi, Brown?"
  },
  AvgDialog_18941_Content_72 = {
    Text = "Il topo le balza sulla spalla, strusciandosi affettuosamente contro di lei."
  },
  AvgDialog_18941_Content_73 = {Text = "Squeak!"},
  AvgDialog_18941_Content_74 = {
    Text = "Oh cielo, i topi mi adorano come sempre."
  },
  AvgDialog_18941_Content_75 = {
    Text = "I putridi e germoglianti abitanti delle fogne condividono una curiosa affinità con i roditori."
  },
  AvgDialog_18941_Content_76 = {
    Text = "Anche tu sei stata nelle fogne? Non può essere una coincidenza..."
  },
  AvgDialog_18941_Content_77 = {
    Text = "Bang! Bang—!"
  },
  AvgDialog_18941_Content_78 = {
    Text = "La domanda è appena terminata quando dei tonfi sordi echeggiano dalle profondità della cantina."
  },
  AvgDialog_18941_Content_79 = {
    Text = "Trattenete il respiro, udendo grida intermittenti e soffocate — basse e represse."
  },
  AvgDialog_18941_Content_8 = {
    Text = [[
Inverno, AF @2
Londinium]]
  },
  AvgDialog_18941_Content_80 = {Text = "Fame..."},
  AvgDialog_18941_Content_81 = {
    Text = "<Change>Fame... Ho così tanta fame FAME FAME FAME"
  },
  AvgDialog_18941_Content_9 = {
    Text = "Era una notte d'inverno di sei anni fa quando vidi per la prima volta la neve a Londinium — e la bambina che vi giaceva."
  },
  AvgDialog_18942_Content_1 = {
    Text = "Sembri esausta. Sei ferita?"
  },
  AvgDialog_18942_Content_2 = {
    Text = "Abbiamo perso i contatti con la Signorina Doll. Qual è la vostra situazione?"
  },
  AvgDialog_18942_Content_3 = {
    Text = "Ehi, hai visto una bambina più alta di me?"
  },
  AvgDialog_18942_Content_4 = {
    Text = "*Coff coff*... Una alla volta."
  },
  AvgDialog_18943_Content_1 = {
    Text = "Una giovane donna pallida e magra è appoggiata al muro. I suoi occhi sono socchiusi, il volto arrossato e il respiro estremamente rapido."
  },
  AvgDialog_18943_Content_10 = {
    Text = "Un dolore acuto, come un ago che penetra in profondità, si conficca nel tuo collo, sempre più a fondo..."
  },
  AvgDialog_18943_Content_11 = {Text = "<Big:?!>"},
  AvgDialog_18943_Content_12 = {
    Text = "Nel tuo orecchio, senti un avido succhiare e deglutire. Qualcosa di morbido e freddo si aggrappa al tuo collo come una ventosa."
  },
  AvgDialog_18943_Content_13 = {
    Text = "Ugh... Indietro... indietro...!!"
  },
  AvgDialog_18943_Content_14 = {
    Text = "Dammelo, dammelo..."
  },
  AvgDialog_18943_Content_15 = {
    Text = "La sensazione di una rapida perdita di Sangue è insopportabile. La Visuale si oscura e il battito cardiaco accelera."
  },
  AvgDialog_18943_Content_16 = {Text = "..."},
  AvgDialog_18943_Content_17 = {
    Text = "Ho detto... <Big:Fuori dai piedi!!!>"
  },
  AvgDialog_18943_Content_2 = {
    Text = "Sembra ferita. Lasciami esaminarla."
  },
  AvgDialog_18943_Content_3 = {
    Text = "La donna indossa un sottile vestito bianco, simile a quello delle altre due sculture di cera, e ha ancora il trucco sul viso."
  },
  AvgDialog_18943_Content_4 = {
    Text = "Potrebbe essere la signorina Mason? Hmm, c'è qualcosa di strano nel suo collo..."
  },
  AvgDialog_18943_Content_5 = {
    Text = "Le catene di ferro quasi si conficcano nel collo candido, ornate da una gemma rosso sangue."
  },
  AvgDialog_18943_Content_6 = {
    Text = "Per qualche ragione, cadi in trance, contemplando con bramosia il tremolio della luce sulla gemma."
  },
  AvgDialog_18943_Content_7 = {
    Text = "<Shake:Eheh... Luccicante, luccicante...>"
  },
  AvgDialog_18943_Content_8 = {
    Text = "<Shake:Che sete... che sete... Dammelo, dammelo...>"
  },
  AvgDialog_18943_Content_9 = {
    Text = "La testa... Mi gira la testa..."
  },
  AvgDialog_18944_Content_1 = {Text = "Tre Regole"},
  AvgDialog_18944_Content_10 = {
    Text = "È un'ospite del Museo delle Cere, non l'obiettivo della nostra indagine."
  },
  AvgDialog_18944_Content_11 = {
    Text = "Lasciami ribadire: ci presentiamo come visitatori di questo Museo delle Cere..."
  },
  AvgDialog_18944_Content_12 = {
    Text = "...e non fare né dire nulla di stupido — Mi hai già fatto venire il mal di testa!"
  },
  AvgDialog_18944_Content_13 = {
    Text = "Bene. Entriamo."
  },
  AvgDialog_18944_Content_14 = {
    Text = [[
21:55, Museo delle Cere di Rogers
Atrio principale]]
  },
  AvgDialog_18944_Content_15 = {
    Text = "L'arredamento è vecchio e polveroso, con un leggero fetore che aleggia nell'aria."
  },
  AvgDialog_18944_Content_16 = {
    Text = "Una bambina siede alla reception, assorta in una rivista intitolata \"Guida alla Cura degli Animali\"."
  },
  AvgDialog_18944_Content_17 = {
    Text = "Buonasera, signora. Mi perdoni, è questo il Museo delle Cere di Rogers?"
  },
  AvgDialog_18944_Content_18 = {Text = "..."},
  AvgDialog_18944_Content_19 = {
    Text = "È aperto ai visitatori, adesso?"
  },
  AvgDialog_18944_Content_2 = {Text = "Din-don..."},
  AvgDialog_18944_Content_20 = {Text = "..."},
  AvgDialog_18944_Content_21 = {
    Text = "Hm hm hm, la la la..."
  },
  AvgDialog_18944_Content_22 = {
    Text = "Che sfortuna. Sembra che questa signora abbia qualche problema d'udito. Entriamo e basta."
  },
  AvgDialog_18944_Content_23 = {
    Text = "Accidenti, che maleducazione fin dall'inizio. Se stai cercando di attirare la mia attenzione..."
  },
  AvgDialog_18944_Content_24 = {
    Text = "Allora congratulazioni, tesoro... L'hai appena fatto."
  },
  AvgDialog_18944_Content_25 = {Text = "..."},
  AvgDialog_18944_Content_26 = {
    Text = "Pfft. Tesoro?"
  },
  AvgDialog_18944_Content_27 = {
    Text = "Benvenuti, tesori! Io sono Pandia, curatrice del Museo delle Cere di Rogers. Un piacere, davvero!"
  },
  AvgDialog_18944_Content_28 = {
    Text = "Ora, cosa vi porta qui a quest'ora empia? Cercate illuminazione artistica... o siete piccoli ladruncoli, venuti a rubare esemplari come quegli ficcanaso di studenti di medicina?"
  },
  AvgDialog_18944_Content_29 = {
    Text = "...Studenti di medicina? Rubare campioni?"
  },
  AvgDialog_18944_Content_3 = {
    Text = "Un'ondata di intensa vertigine ti travolge mentre apri la porta."
  },
  AvgDialog_18944_Content_30 = {
    Text = "Oh cielo! A meno che... non siate qui per un po' di @2 con la sottoscritta?"
  },
  AvgDialog_18944_Content_31 = {
    Text = "<Gray:Aspetta... La mia mente ha appena censurato qualcosa di indicibile...>"
  },
  AvgDialog_18944_Content_32 = {
    Text = "Siamo enormi ammiratori del Maestro Rogers! Siamo venuti a vedere il suo capolavoro — il, ehm... il B-Bo..."
  },
  AvgDialog_18944_Content_33 = {
    Text = "<Big:...La Primadonna del Mar Baltico! Giusto?>"
  },
  AvgDialog_18944_Content_34 = {
    Text = "...Non male, almeno conosce il Mar Baltico."
  },
  AvgDialog_18944_Content_35 = {
    Text = "Aspetta, era la Prima Donna Bosniaca? Il Barbarossa? ...O la Banana?"
  },
  AvgDialog_18944_Content_36 = {
    Text = "Jenkin. Nessuno l'ha chiesto."
  },
  AvgDialog_18944_Content_37 = {
    Text = "Perdonateci. La mia amica pecca forse di raffinatezza, ma la sua passione per l'arte arde più vivida di quella di qualsiasi studioso."
  },
  AvgDialog_18944_Content_38 = {
    Text = "Permettimi di correggere, è <Blue:\"La Primavera di Botticelli\">."
  },
  AvgDialog_18944_Content_39 = {
    Text = "Hmm... Davvero?"
  },
  AvgDialog_18944_Content_4 = {
    Text = "La visuale si oscura, e ti sembra di udire un faint ronzio di corrente elettrica."
  },
  AvgDialog_18944_Content_40 = {
    Text = "Mi spiace deluderti, tesoro, ma il Maestro Rogers stasera ha un impegno fuori."
  },
  AvgDialog_18944_Content_41 = {
    Text = "COSA?! E allora come dovremmo—"
  },
  AvgDialog_18944_Content_42 = {
    Text = "<Big:Jenkin.>"
  },
  AvgDialog_18944_Content_43 = {
    Text = "Ehm... cioè... Va bene. Se quel viscido...\nSe il signor Rogers non è qui, ci guarderemo intorno da soli..."
  },
  AvgDialog_18944_Content_44 = {Text = "Ugh..."},
  AvgDialog_18944_Content_45 = {
    Text = "La Primavera è la trinità di passione, genio e pura devianza del Maestro Rogers!\nDal momento che il vostro gusto non è del tutto deplorevole..."
  },
  AvgDialog_18944_Content_46 = {
    Text = "Potrei lasciarvi entrare—se promettete di comportarvi bene."
  },
  AvgDialog_18944_Content_47 = {
    Text = "Allora, tesori, vi comporterete bene?"
  },
  AvgDialog_18944_Content_48 = {Text = "Sì"},
  AvgDialog_18944_Content_49 = {
    Text = "Hmm... Noioso."
  },
  AvgDialog_18944_Content_5 = {
    Text = "Poi una fragranza — un mélange di violetta e cardamomo, con una nota di un singolare aroma legnoso."
  },
  AvgDialog_18944_Content_50 = {
    Text = "E va bene, obbedienti agnellini. Venite pure. E tenete la coda tra le gambe."
  },
  AvgDialog_18944_Content_51 = {Text = "No"},
  AvgDialog_18944_Content_52 = {
    Text = [[
Va bene, va bene.
ADORO dare una lezione agli ospiti disobbedienti!]]
  },
  AvgDialog_18944_Content_53 = {
    Text = "Tre giorni, e vi renderò tutti docili, bravi agnellini."
  },
  AvgDialog_18944_Content_54 = {
    Text = "Vi conduce all'ingresso della sala espositiva e assume una posa autoritaria, in tutto e per tutto la curatrice impeccabile."
  },
  AvgDialog_18944_Content_55 = {
    Text = "Ascoltate bene, dolcezze.\nTre regole non devono mai—e poi mai—essere infrante!"
  },
  AvgDialog_18944_Content_56 = {
    Text = "<Yellow:Primo: Non toccare le figure di cera.>"
  },
  AvgDialog_18944_Content_57 = {
    Text = "<Yellow:Secondo: non sollevate le loro coperture.>"
  },
  AvgDialog_18944_Content_58 = {
    Text = "<Yellow:Terza: Nessuna goccia di sangue dovrà macchiare queste sale.>"
  },
  AvgDialog_18944_Content_59 = {
    Text = "Tre Regole. Semplice, no?"
  },
  AvgDialog_18944_Content_6 = {
    Text = "Sniff sniff... Qualcosa ha un profumo meraviglioso!"
  },
  AvgDialog_18944_Content_60 = {
    Text = "Che... singolare. Le ha ideate il signor Rogers?"
  },
  AvgDialog_18944_Content_61 = {
    Text = "Segreti commerciali, tesoro."
  },
  AvgDialog_18944_Content_62 = {
    Text = "Ma certo. Come se le regole mi avessero mai fermata."
  },
  AvgDialog_18944_Content_63 = {
    Text = "<SmallShake:Scommetto che potrei fare quel che mi pare senza che tu te ne accorga...>"
  },
  AvgDialog_18944_Content_64 = {
    Text = "Ohh, i topolini dispettosi sono così deliziosamente sfiancanti.\nUn consiglio gratuito da parte mia, allora."
  },
  AvgDialog_18944_Content_65 = {
    Text = "<Italic:Non vorrai tentare la sorte.>"
  },
  AvgDialog_18944_Content_66 = {
    Text = "Infrangetele, e le conseguenze faranno sembrare i vasetti di belletto infranti della nonna una sciocchezza."
  },
  AvgDialog_18944_Content_67 = {
    Text = "Tch. Il numeretto inquietante va perfezionato."
  },
  AvgDialog_18944_Content_68 = {
    Text = [[
Un'ultima cosa: non offriamo visite guidate.
Quindi se dovesse capitarvi qualcosa di... spiacevole...]]
  },
  AvgDialog_18944_Content_69 = {
    Text = "Beh, quello è un problema tuo."
  },
  AvgDialog_18944_Content_7 = {Text = "..."},
  AvgDialog_18944_Content_70 = {
    Text = "Ora, godetevi la visita alla mostra!"
  },
  AvgDialog_18944_Content_8 = {
    Text = "Una donna vi oltrepassa ondeggiando con grazia."
  },
  AvgDialog_18944_Content_9 = {
    Text = "Ehi, chi c'è—"
  },
  AvgDialog_18945_Content_1 = {
    Text = "Trovata, la \"Primavera\"!"
  },
  AvgDialog_18945_Content_2 = {
    Text = "Guardi nella direzione indicata da 24."
  },
  AvgDialog_18945_Content_3 = {
    Text = "Le aggraziate sculture di cera in abiti di garza danzano mano nella mano sotto la luce cremisi della luna."
  },
  AvgDialog_18945_Content_4 = {
    Text = "Se non fosse per i loro sorrisi contorti e il trucco rigato di lacrime, sarebbe una deliziosa opera d'arte."
  },
  AvgDialog_18945_Content_5 = {
    Text = "Ne manca uno."
  },
  AvgDialog_18945_Content_6 = {
    Text = "Mason, che interpreta la dea \"Casta\" Sereya, dovrebbe essere posizionata al centro."
  },
  AvgDialog_18945_Content_7 = {Text = "Aiuto..."},
  AvgDialog_18945_Content_8 = {
    Text = "Un flebile grido d'aiuto proviene dall'angolo."
  },
  AvgDialog_18945_Content_9 = {
    Text = "Aiuto... aiutatemi... mi sta divorando viva—"
  },
  AvgDialog_18946_Content_1 = {
    Text = [[
22:30, Museo delle Cere di Rogers
Atrio principale]]
  },
  AvgDialog_18946_Content_10 = {
    Text = "Scultura di Cera? Ma ci stava parlando fino a un momento fa!"
  },
  AvgDialog_18946_Content_11 = {
    Text = "Ehi! Smettila di fare la morta!"
  },
  AvgDialog_18946_Content_12 = {
    Text = "<Italic:Eheh...>"
  },
  AvgDialog_18946_Content_13 = {
    Text = "Un'Ombra in agguato nell'angolo scatta fuori rapida e spinge Jenkin con forza."
  },
  AvgDialog_18946_Content_14 = {
    Text = "Cos'è quel rumore... Ehi!"
  },
  AvgDialog_18946_Content_15 = {
    Text = "Jenkin cade inaspettatamente verso Pandia. Nel momento in cui si toccano, viene risucchiata in un Vortice appiccicoso e molle."
  },
  AvgDialog_18946_Content_16 = {
    Text = "Ugh! Chi, <Big:chi mi sta spingendo—>"
  },
  AvgDialog_18946_Content_17 = {
    Text = "Jenkin ritrae istintivamente la Mano. Quando torna in sé, avverte una sensazione fredda e umida nel palmo."
  },
  AvgDialog_18946_Content_18 = {
    Text = "Nella Mano stringe forte un pezzo di intestino fatto di cera."
  },
  AvgDialog_18946_Content_19 = {
    Text = "<Big:Aaaaah—!!>"
  },
  AvgDialog_18946_Content_2 = {
    Text = "Signorina Pandia, possiamo usare il vostro telefono? Abbiamo perso i contatti con la nostra amica."
  },
  AvgDialog_18946_Content_20 = {
    Text = "Squeak squeak squeak squeak!!"
  },
  AvgDialog_18946_Content_21 = {
    Text = "<Shake:Santa Maria! Non avrei dovuto rubare i soldi della Signorina Sarah...>"
  },
  AvgDialog_18946_Content_22 = {
    Text = "<RedShake:Non toccare, non toccare...>"
  },
  AvgDialog_18946_Content_23 = {
    Text = "<RedShake:Fa male... Troppo dolore...>"
  },
  AvgDialog_18946_Content_24 = {
    Text = "Crac, crac, crac, crac..."
  },
  AvgDialog_18946_Content_25 = {
    Text = "Dal Corpo di Pandia proviene il lento Scricchiolio delle articolazioni, che sale e scende ritmicamente come un respiro."
  },
  AvgDialog_18946_Content_26 = {
    Text = "<Red:\"Non toccare le figure di cera.\">"
  },
  AvgDialog_18946_Content_27 = {
    Text = "I Suoi Occhi continuano a muoversi qua e là, e gli angoli della bocca sono particolarmente inquietanti."
  },
  AvgDialog_18946_Content_28 = {
    Text = "<Red:Regola 1 del Museo delle Cere: Non toccare le figure di cera.>"
  },
  AvgDialog_18946_Content_29 = {
    Text = "Ohh, qualcuno è stato un birichino trasgressore di regole. Che deliziosa imprudenza..."
  },
  AvgDialog_18946_Content_3 = {Text = "..."},
  AvgDialog_18946_Content_30 = {
    Text = "Non è, non è giusto! Qualcuno mi ha spinto!"
  },
  AvgDialog_18946_Content_31 = {
    Text = "Oh, povera me. Il nostro topolino racconta bugie così adorabili..."
  },
  AvgDialog_18946_Content_32 = {
    Text = "...e decisamente volgare.\nStavo facendo dei sogni così belli prima che mi svuotassi lo stomaco."
  },
  AvgDialog_18946_Content_33 = {
    Text = "Il mio stomaco brontola, e mi fa arrossire appena appena..."
  },
  AvgDialog_18946_Content_34 = {
    Text = "Pandia inclina la testa e ti fa l'occhiolino con aria giocosa."
  },
  AvgDialog_18946_Content_35 = {
    Text = "Ebbene, miei ospiti maleducati—"
  },
  AvgDialog_18946_Content_36 = {
    Text = "<Red:Benvenuto nel nostro piccolo paradise.>"
  },
  AvgDialog_18946_Content_37 = {
    Text = "Quando Pandia finisce, la fiamma della candela nel suo ventre divampa, riducendo il suo corpo a una pozza di cera oleosa trasparente."
  },
  AvgDialog_18946_Content_38 = {
    Text = "Tutte le luci nella sala si spengono contemporaneamente, e l'oscurità cala come un sipario."
  },
  AvgDialog_18946_Content_39 = {
    Text = "Ding—Ding—Ding—"
  },
  AvgDialog_18946_Content_4 = {
    Text = "Perché non risponde?"
  },
  AvgDialog_18946_Content_40 = {
    Text = "La campana rintocca dodici volte. È allora che vi rendete conto che è già mezzanotte."
  },
  AvgDialog_18946_Content_41 = {
    Text = "I fruscii si fanno più nitidi. Prima che ve ne rendiate conto, le sculture di cera vi hanno circondato."
  },
  AvgDialog_18946_Content_42 = {
    Text = "Ridacchiano, con toni strascicati che echeggiano nella sala espositiva vuota."
  },
  AvgDialog_18946_Content_43 = {
    Text = "<RedShake:Heheheh...>"
  },
  AvgDialog_18946_Content_44 = {
    Text = "<RedShake:Mangiateli tutti, divorateli finché non restano che spoglie!!!>"
  },
  AvgDialog_18946_Content_5 = {
    Text = "Jenkin agita la Mano davanti a Pandia e le fa qualche smorfia buffa."
  },
  AvgDialog_18946_Content_6 = {
    Text = "<Big:Ih-ih-ah! Maiale stupido! Mostro orrendo!>"
  },
  AvgDialog_18946_Content_7 = {Text = "..."},
  AvgDialog_18946_Content_8 = {
    Text = "Tch, che noia."
  },
  AvgDialog_18946_Content_9 = {
    Text = "L'illuminazione del corridoio era Oscura prima, ma ora riesco a vedere chiaramente... sembra essere una Scultura di Cera."
  },
  AvgDialog_18947_Content_1 = {
    Text = "Paura, Brown? Siamo solo noi adesso."
  },
  AvgDialog_18947_Content_2 = {
    Text = "Squeak, squeak! (Brown non ha paura, squeak. Avanti, squeak!)"
  },
  AvgDialog_18947_Content_3 = {Text = "Roar—!!"},
  AvgDialog_18947_Content_4 = {
    Text = "Tch, ancora Mostri qui... Metà dei loro corpi sembra invisibile."
  },
  AvgDialog_18947_Content_5 = {
    Text = "Squeak, squeak squeak... (%player% ha detto che la gente comune e i topi come noi non possono vedere il Disso-qualcosa.)"
  },
  AvgDialog_18947_Content_6 = {
    Text = "Pazienza, se non possiamo vincere, si scappa. È la mia specialità!"
  },
  AvgDialog_18947_Content_7 = {
    Text = "Brown, tieni il passo! Scappiamo!"
  },
  AvgDialog_18947_Content_8 = {
    Text = "Squeak! (Arrivo, squeak!)"
  },
  AvgDialog_18948_Content_1 = {Text = "Ahhhh—!!"},
  AvgDialog_18948_Content_10 = {
    Text = "Chi sono io..."
  },
  AvgDialog_18948_Content_11 = {
    Text = "Già... Chi sono io, davvero?"
  },
  AvgDialog_18948_Content_12 = {
    Text = "Il nome, non riesco più a ricordarlo... <Red:È svanito... tutto svanito...>"
  },
  AvgDialog_18948_Content_13 = {
    Text = "Ecco un nuovo volto che ho personalizzato per te. Ti piace?"
  },
  AvgDialog_18948_Content_14 = {
    Text = "Chi... è questa? Chi è il mostro nel riflesso?"
  },
  AvgDialog_18948_Content_15 = {
    Text = "Chi sei? Chi è la persona nel Riflesso? Niente di tutto questo ha importanza."
  },
  AvgDialog_18948_Content_16 = {
    Text = "Dimentica il tuo passato; non è altro che un mucchio di carta straccia."
  },
  AvgDialog_18948_Content_17 = {
    Text = "Ricorda il tuo codice sperimentale, <Blue:24>—ti accompagnerà per tutta la Vita."
  },
  AvgDialog_18948_Content_18 = {
    Text = "<Shake:La mia Vita... è finita... completamente finita...>"
  },
  AvgDialog_18948_Content_19 = {
    Text = "Se chiami \"Vita\" la tua miserabile e insignificante esistenza..."
  },
  AvgDialog_18948_Content_2 = {
    Text = "La donna si stringe forte il collo con le mani. I muscoli del viso le si contraggono senza sosta, e gli occhi si muovono rapidamente, quasi sul punto di uscire dalle orbite."
  },
  AvgDialog_18948_Content_20 = {
    Text = "Sì, in effetti ti ha lasciato."
  },
  AvgDialog_18948_Content_21 = {
    Text = "No, no... vi maledico tutti! <Red:Fino all'ultimo!>"
  },
  AvgDialog_18948_Content_22 = {
    Text = "<Red:Vi maledico tutti, vi maledico tutti...><RedBig:FINIRETE ALL'INFERNO!>"
  },
  AvgDialog_18948_Content_23 = {Text = "..."},
  AvgDialog_18948_Content_24 = {
    Text = "24... ora ricordo. <Shake:Solo un numero... solo un numero...>"
  },
  AvgDialog_18948_Content_25 = {
    Text = "Piacere di conoscerti. Puoi chiamarmi semplicemente 24. <Italic:...per ora.>"
  },
  AvgDialog_18948_Content_26 = {
    Text = "24? Che razza di nome strano è?"
  },
  AvgDialog_18948_Content_27 = {
    Text = "24 si rannicchia in un angolo, scuotendo disperatamente la testa e rifiutandosi di pronunciare un'altra parola."
  },
  AvgDialog_18948_Content_28 = {Text = "..."},
  AvgDialog_18948_Content_29 = {
    Text = [[
Sembri restio a parlare del tuo passato. E del museo delle cere?
Saresti disposto a condividere qualche informazione?]]
  },
  AvgDialog_18948_Content_3 = {
    Text = "Il suo Spirito sta diventando instabile... %player%, usa la Chiave d'Argento per stabilizzarla, ora!"
  },
  AvgDialog_18948_Content_30 = {
    Text = "Per esempio, riguardo a queste \"Tre Regole\"..."
  },
  AvgDialog_18948_Content_31 = {
    Text = "<Big:Shh!!>"
  },
  AvgDialog_18948_Content_32 = {
    Text = "Non dirlo ad alta voce, <Blue:\"loro\"> sentiranno. <Shake:Sono sempre in ascolto...>"
  },
  AvgDialog_18948_Content_33 = {Text = "\"Loro?\""},
  AvgDialog_18948_Content_34 = {
    Text = "24 si guarda intorno con cautela, poi assume un tono misterioso e si avvicina a te."
  },
  AvgDialog_18948_Content_35 = {
    Text = "<Shake:Loro sono... proprio qui...>"
  },
  AvgDialog_18948_Content_36 = {
    Text = "Le \"Tre Regole\" sono i Tabù di questo Museo delle Cere; non devono mai essere infrante."
  },
  AvgDialog_18948_Content_37 = {
    Text = "Ehm, ne ho già infranta una prima."
  },
  AvgDialog_18948_Content_38 = {
    Text = "<Big:Cosa?!>"
  },
  AvgDialog_18948_Content_39 = {
    Text = "Come hai potuto, come hai potuto essere così imprudente?!"
  },
  AvgDialog_18948_Content_4 = {Text = "Capito!"},
  AvgDialog_18948_Content_40 = {
    Text = "Oops, errore mio. A parte svegliare le figure di cera, cos'altro succede se si infrangono le Regole?"
  },
  AvgDialog_18948_Content_41 = {
    Text = "<Shake:Oh no, vengono a prendermi, vengono a prendermi...>"
  },
  AvgDialog_18948_Content_42 = {
    Text = "La 24 si tira ansiosamente i capelli, strappandoli via insieme a pezzi di cuoio capelluto."
  },
  AvgDialog_18948_Content_43 = {
    Text = "Ehi... ehi! Non ti fa male?"
  },
  AvgDialog_18948_Content_44 = {
    Text = "<Shake:Mi hanno trovata, mi hanno trovata...>"
  },
  AvgDialog_18948_Content_45 = {
    Text = "Braccia rosso scuro emergono lentamente dal suo Corpo, avvolgendosi delicatamente attorno al collo, e poi—"
  },
  AvgDialog_18948_Content_46 = {Text = "CRACK!"},
  AvgDialog_18948_Content_47 = {
    Text = "Ahhh, la sua testa—!!"
  },
  AvgDialog_18948_Content_48 = {
    Text = "Come una Doll a cui sia stata tolta la Primavera, la testa della 24 ricade pesantemente, i lunghi capelli a coprirle quasi interamente il volto."
  },
  AvgDialog_18948_Content_49 = {
    Text = "Clic. Clic. Clic."
  },
  AvgDialog_18948_Content_5 = {
    Text = "Estrai rapidamente la Chiave d'Argento dal petto: il suo freddo Bagliore bianco fende il cielo notturno."
  },
  AvgDialog_18948_Content_50 = {
    Text = "Con il suono di ossa che si spezzano e si ricompongono, rialza la testa, ma la sua Espressione è ben diversa da prima."
  },
  AvgDialog_18948_Content_51 = {
    Text = "Heh... hehehe... <Red:Troppo tardi... troppo tardi per tutti noi...>"
  },
  AvgDialog_18948_Content_52 = {
    Text = "<Red:Uccidere...>"
  },
  AvgDialog_18948_Content_53 = {
    Text = "<BigBoldRed:Vi @1 tutti quanti!!>"
  },
  AvgDialog_18948_Content_6 = {Text = "UGH!"},
  AvgDialog_18948_Content_7 = {
    Text = "Cosa sta succedendo...? <Shake:Perché... perché non riesco a ragionare?>"
  },
  AvgDialog_18948_Content_8 = {
    Text = "State indietro! E rispondete alle mie domande!"
  },
  AvgDialog_18948_Content_9 = {Text = "Chi sei?"},
  AvgDialog_18949_Content_1 = {
    Text = "Squeak, squeak squeak! (Jenkin, sbrigati! Il Disso-qualcosa si sta propagando e ha già raggiunto i condotti, squeak!)"
  },
  AvgDialog_18949_Content_2 = {
    Text = "Sembra che sia in Trappola... devo occuparmi di loro in fretta."
  },
  AvgDialog_18949_Content_3 = {
    Text = "Squeak... Squeak squeak. (Ma sei coperto di... In ogni caso, usciamo. Non ti lascerò per nessun motivo, squeak.)"
  },
  AvgDialog_18949_Content_4 = {
    Text = "Grazie, Brown!"
  },
  AvgDialog_18950_Content_1 = {
    Text = "Finalmente, l'ufficio del direttore! William ha detto che la Chiave è nella scrivania."
  },
  AvgDialog_18950_Content_10 = {
    Text = "Ignorando il consiglio di Brown, Jenkin si tuffa nell'Oscurità invisibile."
  },
  AvgDialog_18950_Content_2 = {
    Text = "Una scrivania di legno di noce galleggia storta sul fiume nero, come un'isola solitaria."
  },
  AvgDialog_18950_Content_3 = {
    Text = "Sniff sniff... squeak squeak! (State lontani! Qui l'odore è davvero strano, squeak!)"
  },
  AvgDialog_18950_Content_4 = {Text = "..."},
  AvgDialog_18950_Content_5 = {
    Text = "<Yellow:Dobbiamo andare. Sorella e %player% sono in Attesa.>"
  },
  AvgDialog_18950_Content_6 = {
    Text = "<Shake:Squeak, squeak... (Ma... ma...)>"
  },
  AvgDialog_18950_Content_7 = {
    Text = "Solo un pochino non mi ammazzerà, no?\nAl massimo mi prendo un raffreddore, a scuola mi curano gratis."
  },
  AvgDialog_18950_Content_8 = {
    Text = "Magari ci pagheranno pure bene per la ferita."
  },
  AvgDialog_18950_Content_9 = {
    Text = "Augurami buona fortuna, Brown."
  },
  AvgDialog_18951_Content_1 = {
    Text = "Huff... Huff... Mostri ovunque."
  },
  AvgDialog_18951_Content_2 = {
    Text = "Non si può più tornare indietro. Brown, prendi la chiave e vai avanti."
  },
  AvgDialog_18951_Content_3 = {
    Text = "Squeak! Squeak squeak... (Stai scherzando? Ce ne andiamo da questo posto per mangiare un sacco di formaggio insieme! Saremo ricchi con tutto questo bottino!)"
  },
  AvgDialog_18951_Content_4 = {
    Text = "Squeak! (Basta vivere in una casa fatiscente, squeak!)"
  },
  AvgDialog_18951_Content_5 = {
    Text = "Va bene... Resisterò ancora un po'. Usciamo di qui insieme."
  },
  AvgDialog_18952_Content_1 = {
    Text = "<Shake:Devo uscire... Devo...>"
  },
  AvgDialog_18952_Content_2 = {
    Text = "<Shake:Sorella, Ramona, %player%... mi aspettano...>"
  },
  AvgDialog_18952_Content_3 = {
    Text = "Non sei mai stata sola. Hai me, e hai tutti noi."
  },
  AvgDialog_18952_Content_4 = {
    Text = "C'è ancora così tanto che potrei imparare da te, <Blue:\"Maestro di Sopravvivenza Urbana\">."
  },
  AvgDialog_18952_Content_5 = {
    Text = "Ho preso la chiave... Non posso fallire adesso."
  },
  AvgDialog_18952_Content_6 = {
    Text = "Squeak... (Jenkin...)"
  },
  AvgDialog_18952_Content_7 = {
    Text = "Non guardarmi così, Brown... Non è ancora finita."
  },
  AvgDialog_18952_Content_8 = {
    Text = "Se muoio qui, porta la chiave a loro."
  },
  AvgDialog_18952_Content_9 = {
    Text = "...Squeak, squeak squeak. (...Va bene, squeak. Te lo prometto, Jenkin.)"
  },
  AvgDialog_18953_Content_1 = {
    Text = "41, 42, 43, 45..."
  },
  AvgDialog_18953_Content_2 = {
    Text = "Aspetta un momento, che fine ha fatto il numero 44?"
  },
  AvgDialog_18953_Content_3 = {
    Text = "41, 42, 43, 45..."
  },
  AvgDialog_18954_Content_1 = {
    Text = "Ancora tu? Non hai imparato la lezione?"
  },
  AvgDialog_18954_Content_2 = {
    Text = "Tu... Cosa hai detto?!"
  },
  AvgDialog_18954_Content_3 = {
    Text = "Provaci ancora e la prossima volta non sarà solo una Chiave!"
  },
  AvgDialog_18954_Content_4 = {
    Text = "Oltraggioso..."
  },
  AvgDialog_18954_Content_5 = {
    Text = "Presto, catturateli tutti!"
  },
  AvgDialog_18955_Content_1 = {
    Text = "Dietro il Velo"
  },
  AvgDialog_18955_Content_10 = {
    Text = "No, non lasciarmi solo..."
  },
  AvgDialog_18955_Content_11 = {
    Text = "Figlio mio... Prima che tu parta, ho un Dono per te."
  },
  AvgDialog_18955_Content_12 = {Text = "..."},
  AvgDialog_18955_Content_13 = {
    Text = "Porta i miei Occhi da lei. Lascia che parlino per me e veglino su di te."
  },
  AvgDialog_18955_Content_14 = {
    Text = "Mi supererai. Ricordalo—"
  },
  AvgDialog_18955_Content_15 = {
    Text = "Nessuna agonia potrà più sfiorarti, né mai sconfiggerti."
  },
  AvgDialog_18955_Content_16 = {
    Text = "Si fonderanno con l'arte che creerai, raggiungendo una bellezza eterna."
  },
  AvgDialog_18955_Content_17 = {
    Text = "Rogers fissa gli occhi familiari di George."
  },
  AvgDialog_18955_Content_18 = {
    Text = "Signor Cera... N-non capisco."
  },
  AvgDialog_18955_Content_19 = {
    Text = "Se nessuna sofferenza può ferirmi, allora perché... sento il bisogno di piangere adesso?"
  },
  AvgDialog_18955_Content_2 = {
    Text = "Vieni qui, bambino, vieni presto..."
  },
  AvgDialog_18955_Content_20 = {
    Text = "Rispondimi... Rispondimi!"
  },
  AvgDialog_18955_Content_21 = {
    Text = "<Change>Ahhhhh... Rogers, Rogers..."
  },
  AvgDialog_18955_Content_22 = {
    Text = "George apre la bocca, ma ne esce solo una melma nera.\nNon sarà mai in grado di rispondere a quella domanda."
  },
  AvgDialog_18955_Content_23 = {
    Text = "Maestro Rogers, la vostra Mano e quelle... cose... si stanno fondendo!"
  },
  AvgDialog_18955_Content_24 = {
    Text = "Nessuna risposta da Rogers. E nessun'altra verrà mai più da lui."
  },
  AvgDialog_18955_Content_25 = {
    Text = "<Small:Dobbiamo fuggire adesso, o tutti noi...>"
  },
  AvgDialog_18955_Content_26 = {Text = "..."},
  AvgDialog_18955_Content_27 = {
    Text = "Maestro Rogers, so che mi disprezzerete per questo, ma—"
  },
  AvgDialog_18955_Content_28 = {Text = "Splash!!"},
  AvgDialog_18955_Content_29 = {
    Text = [[
La frusta si avvolge attorno al braccio di Rogers, strappandoglielo.
Il sangue sgorga a fiotti, tingendo di rosso il cappotto di Rogers.]]
  },
  AvgDialog_18955_Content_3 = {
    Text = "Signor Cera...?"
  },
  AvgDialog_18955_Content_30 = {
    Text = "<Red:AHHH—!!>"
  },
  AvgDialog_18955_Content_31 = {
    Text = "<Red:La mia mano, la mia mano...>"
  },
  AvgDialog_18955_Content_32 = {
    Text = "George perde la presa. Il Gruppo di Sculture di Cera urlanti si aggrappa a lui, scivolando tutti verso il baratro."
  },
  AvgDialog_18955_Content_33 = {
    Text = "<Change>No, non..."
  },
  AvgDialog_18955_Content_34 = {
    Text = "La sua mano destra, creatrice di innumerevoli sculture di cera, sprofonda con lui nell'Abisso senza fine."
  },
  AvgDialog_18955_Content_35 = {
    Text = "<Red:AAAAHHHHH—!!>"
  },
  AvgDialog_18955_Content_36 = {
    Text = "<Red:Pandia, che stai facendo... la mia mano...>"
  },
  AvgDialog_18955_Content_37 = {
    Text = "Accompagnerò il Maestro Rogers in salvo. Leigh, intrattieni i nostri ospiti!"
  },
  AvgDialog_18955_Content_38 = {Text = "...Eh?"},
  AvgDialog_18955_Content_4 = {
    Text = "Nel lungo, solitario fascio di luce, il ragazzo cammina da solo."
  },
  AvgDialog_18955_Content_5 = {
    Text = "Attraversa il Passaggio, seguendo il richiamo, avvicinandosi al Signor Cera Passo dopo Passo."
  },
  AvgDialog_18955_Content_6 = {
    Text = "L'uomo è immerso in una pozza di cera cremisi, lacrime che scorrono lungo i solchi del suo volto."
  },
  AvgDialog_18955_Content_7 = {
    Text = "Signor Cera, c-che cosa sta facendo?!"
  },
  AvgDialog_18955_Content_8 = {
    Text = "Questo involucro cedevole è durato più a lungo del previsto..."
  },
  AvgDialog_18955_Content_9 = {
    Text = "Perire nella cera... che poesia sublime."
  },
  AvgDialog_18956_Content_1 = {
    Text = "No, sono decisamente troppi."
  },
  AvgDialog_18956_Content_10 = {
    Text = "La tua coscienza continua a immergersi, sprofondando sempre più, finché non sfiora qualcosa di strano—"
  },
  AvgDialog_18956_Content_11 = {
    Text = "Come qualcosa proveniente da anni luce di distanza, dalle profondità dell'universo, antico, attraverso innumerevoli stelle e distese di spazio-tempo, recante messaggi familiari eppure estranei."
  },
  AvgDialog_18956_Content_12 = {
    Text = [[
<Change>H's ymg'...
Sei tu...]]
  },
  AvgDialog_18956_Content_13 = {
    Text = "Innumerevoli voci antiche convergono, risuonando come accordi d'organo attraverso l'universo."
  },
  AvgDialog_18956_Content_14 = {
    Text = "Il loro linguaggio non ti è estraneo.\nÈ strano, considerando che vieni sempre bocciato in Lingua Antica."
  },
  AvgDialog_18956_Content_15 = {
    Text = [[
<Change>Y' ymg' kadishtu ephainog ephaii...
Sapevo che saresti tornato...]]
  },
  AvgDialog_18956_Content_16 = {
    Text = "Chi sei...? Cosa sei...?"
  },
  AvgDialog_18956_Content_17 = {
    Text = "Che posto è questo?"
  },
  AvgDialog_18956_Content_18 = {
    Text = "Le voci ignorano le tue domande. Si agitano, gridano, e ti rivolgono un invito."
  },
  AvgDialog_18956_Content_19 = {
    Text = [[
<Change>Llll nog c'...
Andiamocene insieme...]]
  },
  AvgDialog_18956_Content_2 = {
    Text = "Continuano a tornare!"
  },
  AvgDialog_18956_Content_20 = {
    Text = [[
Ya uh'@1.
Mio @2...]]
  },
  AvgDialog_18956_Content_21 = {
    Text = "Fluttui nel cielo stellato sconfinato mentre innumerevoli meteore ti sfrecciano accanto e confluiscono nel tuo corpo."
  },
  AvgDialog_18956_Content_22 = {
    Text = "Il loro calore quasi ti fonde gli organi. Ti senti come immerso in un sole dorato, colmo di potere."
  },
  AvgDialog_18956_Content_23 = {
    Text = "Nel flusso e riflusso della coscienza, la voce indifferente di William — accompagnata dal ticchettio ritmico degli strumenti — indugia flebilmente nelle tue orecchie."
  },
  AvgDialog_18956_Content_24 = {
    Text = "98%, 99%..."
  },
  AvgDialog_18956_Content_25 = {
    Text = "La frattura sta per chiudersi... Resisti ancora cinque minuti, %player%."
  },
  AvgDialog_18956_Content_3 = {Text = "No—"},
  AvgDialog_18956_Content_4 = {
    Text = "Sei avvolto ancora una volta nella cera bianca."
  },
  AvgDialog_18956_Content_5 = {
    Text = "La cera succhia avidamente il sangue, apparentemente insaziabile, finché non percepisce un sapore peculiare."
  },
  AvgDialog_18956_Content_6 = {
    Text = "Il profumo familiare, intimo, che appartiene a @2."
  },
  AvgDialog_18956_Content_7 = {
    Text = "Vieni trascinato in un vortice profondo."
  },
  AvgDialog_18956_Content_8 = {
    Text = [[
Gli intricati ricordi si dispiegano davanti a te come un rotolo. Gioiosi, tristi, dolorosi...
Non solo i tuoi ricordi, ma anche quelli degli altri.]]
  },
  AvgDialog_18956_Content_9 = {
    Text = "Che... cos'è quello..."
  },
  AvgDialog_18957_Content_1 = {
    Text = "Tsk, un po' più problematico del previsto."
  },
  AvgDialog_18957_Content_10 = {Text = "Bam! Bam!"},
  AvgDialog_18957_Content_11 = {
    Text = "Fratello, ti hanno sparato!"
  },
  AvgDialog_18957_Content_12 = {
    Text = "Non badare a me. Vai!"
  },
  AvgDialog_18957_Content_13 = {
    Text = "No, non me ne vado... Sono stata io a rovinarti, sono stata io a rovinare tutti..."
  },
  AvgDialog_18957_Content_14 = {
    Text = "Perché, perché fare tutto questo per una come me..."
  },
  AvgDialog_18957_Content_15 = {
    Text = "Scusa, Leigh.\nRipagherò con la mia vita gli anni in cui sei stata rinchiusa sottoterra."
  },
  AvgDialog_18957_Content_16 = {
    Text = "Ora siamo pari."
  },
  AvgDialog_18957_Content_17 = {
    Text = "Va'. Non voltarti indietro. Hai ancora una Vita davanti..."
  },
  AvgDialog_18957_Content_18 = {Text = "Addio."},
  AvgDialog_18957_Content_19 = {
    Text = "Fratello... ricordo... ora ricordo tutto..."
  },
  AvgDialog_18957_Content_2 = {
    Text = "Leigh, smettila di restare a bocca aperta. Non avevi giurato di essere il mio Scudo del Personaggio?"
  },
  AvgDialog_18957_Content_20 = {Text = "Leigh...?"},
  AvgDialog_18957_Content_21 = {
    Text = "Lo sapevo che tutte le sue dolci parole erano menzogne... Che rabbia, che assoluta follia!"
  },
  AvgDialog_18957_Content_22 = {
    Text = "Mettiti dietro di me come si deve e renditi utile, o subirai le conseguenze!"
  },
  AvgDialog_18957_Content_3 = {Text = "..."},
  AvgDialog_18957_Content_4 = {
    Text = "Lo Sguardo di Leigh scivola su di te per un istante, poi si posa sulle mani intrecciate di Jenkin e 24."
  },
  AvgDialog_18957_Content_5 = {
    Text = "Che strano, vedervi così... mi ricorda qualcosa di lontano e..."
  },
  AvgDialog_18957_Content_6 = {
    Text = "Qualcosa che non ho mai conosciuto..."
  },
  AvgDialog_18957_Content_7 = {
    Text = "Ultime notizie! Secondo le nostre fonti, i <Blue:Fratelli Vampiri> sono stati avvistati di recente a Londinium!!"
  },
  AvgDialog_18957_Content_8 = {
    Text = "Solo 5 penny per scoprire lo scandalo sconvolgente della famiglia Cavendish! 23 senzatetto ne sono già rimasti vittime..."
  },
  AvgDialog_18957_Content_9 = {
    Text = "Trovati! Sono proprio là davanti! Questa volta dobbiamo catturarli!"
  },
  AvgDialog_18958_Content_1 = {
    Text = "La Carica di Brown"
  },
  AvgDialog_18958_Content_10 = {
    Text = "V-va tutto bene, signorina Clementine."
  },
  AvgDialog_18958_Content_11 = {
    Text = "Mi sento molto più leggero e a mio agio ora, e il mio umore si è placato dopo che la Scultura di Cera è stata danneggiata."
  },
  AvgDialog_18958_Content_12 = {
    Text = "È questa la Magia della psicoterapia? Sembra avere qualcosa in comune con l'Arte della Cera..."
  },
  AvgDialog_18958_Content_13 = {Text = "Tsk"},
  AvgDialog_18958_Content_14 = {
    Text = "George, saluta la signorina Clementine."
  },
  AvgDialog_18958_Content_15 = {Text = "...Hmph."},
  AvgDialog_18958_Content_16 = {
    Text = "Arrivederci—signorina Clementine."
  },
  AvgDialog_18958_Content_17 = {
    Text = "<Shake:Sob... E questo è tutto. Persino il Sig. Lawrence...>"
  },
  AvgDialog_18958_Content_18 = {
    Text = "<Shake:Hehehe, che stupida, così stupida...>"
  },
  AvgDialog_18958_Content_19 = {
    Text = "<Shake:Punitela adesso, strappatele la faccia!>"
  },
  AvgDialog_18958_Content_2 = {
    Text = "Silenzio, tutti."
  },
  AvgDialog_18958_Content_20 = {
    Text = "<Shake:Punizione! Punizione! Punizione...>"
  },
  AvgDialog_18958_Content_21 = {
    Text = "Silenzio, miei preziosi."
  },
  AvgDialog_18958_Content_22 = {
    Text = "Che seccatura! Questo è solo un umile Museo delle Cere — perché devono venire tutti a ficcare il naso?"
  },
  AvgDialog_18958_Content_23 = {
    Text = "<Big:Boom—>"
  },
  AvgDialog_18958_Content_24 = {Text = "Waaah..."},
  AvgDialog_18958_Content_25 = {
    Text = "<Shake:Ah! Cos'era quel rumore? Potrebbe essere...>"
  },
  AvgDialog_18958_Content_26 = {
    Text = "<Shake:Si sveglia, si sta svegliando... Scappate!>"
  },
  AvgDialog_18958_Content_27 = {Text = "..."},
  AvgDialog_18958_Content_28 = {
    Text = "Fuggiti tutti? Che patetica noia."
  },
  AvgDialog_18958_Content_29 = {
    Text = "Padron Rogers, venga fuori. Ho avvistato il caro piccolo George!"
  },
  AvgDialog_18958_Content_3 = {
    Text = "Tutti ammutoliscono. I singhiozzi soffocati si trasformano in strida lunghe e ininterrotte."
  },
  AvgDialog_18958_Content_30 = {
    Text = "Quei tesori non piangerebbero senza motivo. Siete tornato, non è vero?"
  },
  AvgDialog_18958_Content_31 = {
    Text = "B-buonasera, Pandia."
  },
  AvgDialog_18958_Content_32 = {
    Text = "Vi siete goduto la vostra piccola chiacchierata con la signorina Clementine oggi? Ho pagato una bella sommetta per il vostro trattamento!"
  },
  AvgDialog_18958_Content_33 = {
    Text = "Pandia, s-sbrigati e lascia questo posto, presto! E porta George con te..."
  },
  AvgDialog_18958_Content_34 = {
    Text = "Andarcene? Che assurde sciocchezze state blaterando, Padron Rogers?"
  },
  AvgDialog_18958_Content_35 = {
    Text = "Abbiamo già imprigionato un in-investigatore, e ora ne è arrivato un altro..."
  },
  AvgDialog_18958_Content_36 = {
    Text = "Ho una b-brutta sensazione. I Mythag sembrano aver puntato gli occhi su di me..."
  },
  AvgDialog_18958_Content_37 = {
    Text = "Non temete, Maestro Rogers. Lasciate che la vostra Pandia si occupi di queste noiose inezie!"
  },
  AvgDialog_18958_Content_38 = {
    Text = "<SmallShake:Ho piazzato una graziosa piccola talpa tra di loro, e il caro George darà una mano. Impeccabile!>"
  },
  AvgDialog_18958_Content_39 = {
    Text = "Hai appena detto che il padrone sta tornando?"
  },
  AvgDialog_18958_Content_4 = {
    Text = "Metà Lamenti, metà terrore, come un'Eco dall'Inferno."
  },
  AvgDialog_18958_Content_40 = {
    Text = "Ho ragione nel presumere che il vostro vero obiettivo sia ritardarci fino all'arrivo di Rogers?"
  },
  AvgDialog_18958_Content_41 = {
    Text = "Sì, sì! Sono colpevole di infiniti peccati, assolutamente imperdonabile..."
  },
  AvgDialog_18958_Content_42 = {
    Text = "<Big:Puniscimi più forte!>"
  },
  AvgDialog_18958_Content_43 = {Text = "..."},
  AvgDialog_18958_Content_44 = {
    Text = "Personalmente, spero che voi non siate la Signorina Mason, così non dovrò trattenermi."
  },
  AvgDialog_18958_Content_45 = {
    Text = "%player%, indaghiamo sulle creature sotterranee?"
  },
  AvgDialog_18958_Content_46 = {Text = "Certo"},
  AvgDialog_18958_Content_47 = {
    Text = "Laggiù potrebbero esserci le vittime di Rogers. Non possiamo semplicemente andarcene."
  },
  AvgDialog_18958_Content_48 = {
    Text = "Esatto. Troviamo un passaggio che conduca sottoterra."
  },
  AvgDialog_18958_Content_49 = {Text = "Rifiuto."},
  AvgDialog_18958_Content_5 = {
    Text = "Dopo un tempo indeterminato, i suoni svaniscono."
  },
  AvgDialog_18958_Content_50 = {
    Text = "Il mio istinto mi dice che c'è qualcosa di strano in quel suono. Dovremmo mantenere le distanze."
  },
  AvgDialog_18958_Content_51 = {
    Text = "Ricorda, Custode: siamo qui per indagare, non per fare i turisti."
  },
  AvgDialog_18958_Content_52 = {
    Text = "Non puoi negarlo. Ti rendi conto che il tuo istinto di sopravvivenza ha sopraffatto il senso del dovere."
  },
  AvgDialog_18958_Content_53 = {
    Text = "<SmallShake:H-Hai ragione...>"
  },
  AvgDialog_18958_Content_54 = {
    Text = "Bene. Cerchiamo un accesso alle aree sotterranee."
  },
  AvgDialog_18958_Content_55 = {
    Text = "Botola qui. Porta sottoterra!"
  },
  AvgDialog_18958_Content_56 = {
    Text = "Yee—Ehi—"
  },
  AvgDialog_18958_Content_57 = {
    Text = "Usi tutta la tua forza, ma la botola si apre solo di una fessura."
  },
  AvgDialog_18958_Content_58 = {
    Text = "Niente da fare, non si muove."
  },
  AvgDialog_18958_Content_59 = {
    Text = "È il nostro momento di brillare."
  },
  AvgDialog_18958_Content_6 = {
    Text = "C-Cos'è quello..."
  },
  AvgDialog_18958_Content_60 = {
    Text = "Brown, vai!"
  },
  AvgDialog_18958_Content_61 = {Text = "Squeak!"},
  AvgDialog_18958_Content_7 = {
    Text = "Oh cielo. Il padrone è tornato.\nGli <Blue:adorati animali> nel seminterrato sentivano terribilmente la sua mancanza."
  },
  AvgDialog_18958_Content_8 = {
    Text = [[
23:00, Clinica del Dr. Fairfax
Un'ora prima]]
  },
  AvgDialog_18958_Content_9 = {
    Text = "Il tempo è scaduto. Grazie per la collaborazione, Sig. Rogers.\nMi scuso per il piccolo malinteso verificatosi in precedenza."
  },
  AvgDialog_18959_Content_1 = {Text = "Epilogo"},
  AvgDialog_18959_Content_10 = {
    Text = "Non dimenticarmi, d'accordo?"
  },
  AvgDialog_18959_Content_11 = {
    Text = "Nessun Nucleo d'Argento significa che è davvero, completamente scomparsa... Qualcuno potrebbe averlo preso deliberatamente?"
  },
  AvgDialog_18959_Content_12 = {
    Text = "O c'è qualche indizio che mi sfugge..."
  },
  AvgDialog_18959_Content_13 = {
    Text = "Doll ha detto che ultimamente hai saltato molte lezioni. E invece sei qui a chiacchierare con un insegnante?"
  },
  AvgDialog_18959_Content_14 = {
    Text = "Sig.ra Czort!"
  },
  AvgDialog_18959_Content_15 = {
    Text = "Tranquillo, non sono qui per controllare le presenze. William è tornato. Forse vorresti parlare con lui?"
  },
  AvgDialog_18959_Content_16 = {
    Text = "Ho sentito che ha rintracciato Rogers e lo ha consegnato al Comitato."
  },
  AvgDialog_18959_Content_17 = {Text = "!!"},
  AvgDialog_18959_Content_18 = {
    Text = "Capito... Andrò a parlare con lui."
  },
  AvgDialog_18959_Content_19 = {
    Text = "Arrivederci, Sig. Alistair, Sig.ra Czort."
  },
  AvgDialog_18959_Content_2 = {
    Text = [[
Un mese dopo
Mythag, Area Ristretta A-001]]
  },
  AvgDialog_18959_Content_20 = {
    Text = "I passi si affievoliscono gradualmente, seguiti dal ronzio pesante dell'ascensore in funzione."
  },
  AvgDialog_18959_Content_21 = {
    Text = "È passato un mese, e {Male=lui,Female=lei} ancora non riesce ad accettare che Jenkin non c'è più."
  },
  AvgDialog_18959_Content_22 = {
    Text = [[
{Male=He is blaming himself.,Female=She is blaming herself.}
Succede a tutti. Dai a {Male=him,Female=her} un po' di tempo.]]
  },
  AvgDialog_18959_Content_23 = {
    Text = "Da quanto tempo, Alistair. Come te la sei cavata?"
  },
  AvgDialog_18959_Content_24 = {
    Text = "Parlare di \"sentimenti\" con un vecchio ragazzo come me sembra superfluo."
  },
  AvgDialog_18959_Content_25 = {
    Text = "A giudicare dalla reazione di %player%, ora sei il preside di Mythag?"
  },
  AvgDialog_18959_Content_26 = {
    Text = "Preside ad interim. E... la tua rete di informatori ha bisogno di un aggiornamento."
  },
  AvgDialog_18959_Content_27 = {
    Text = [[
Mi scuso. Non sono in molti ad avere il coraggio di discutere di Mythag con me, di questi tempi.
Ad ogni modo, congratulazioni per la promozione: te la sei meritata.]]
  },
  AvgDialog_18959_Content_28 = {
    Text = "Heh... Questo è più un fardello che un onore."
  },
  AvgDialog_18959_Content_29 = {
    Text = "La gente sta cominciando a dimenticare coloro che sono morti a causa della Dissoluzione."
  },
  AvgDialog_18959_Content_3 = {
    Text = "Ho sentito che oggi sei stato al Museo delle Cere con il Comitato. Avete scoperto qualcosa?"
  },
  AvgDialog_18959_Content_30 = {
    Text = "<Yellow:Cancellazione Esistenziale.>"
  },
  AvgDialog_18959_Content_31 = {
    Text = "Ricordo che era... il 290 o 291 AF. Herbert propose la sua ipotesi—"
  },
  AvgDialog_18959_Content_32 = {
    Text = "<Yellow:La fine del D-fenomeno è la cancellazione della propria stessa esistenza.>"
  },
  AvgDialog_18959_Content_33 = {
    Text = "Era la stella più brillante dell'accademia. Chi avrebbe potuto prevedere che avrebbe ucciso il suo mentore in modo così brutale?"
  },
  AvgDialog_18959_Content_34 = {
    Text = "Era davvero imprevedibile? Li avevo avvertiti molto tempo fa."
  },
  AvgDialog_18959_Content_35 = {
    Text = "Solo il veleno cresce nell'oscurità."
  },
  AvgDialog_18959_Content_36 = {
    Text = [[
La cancellazione esistenziale era rara, prima.
Ora i segni si moltiplicano...]]
  },
  AvgDialog_18959_Content_37 = {
    Text = "Ho allertato il Comitato affinché sorvegli i Sintomi. Eppure..."
  },
  AvgDialog_18959_Content_38 = {
    Text = "Sono passati quasi tre secoli dal primo caso di Dissoluzione nell'anno 15 AF."
  },
  AvgDialog_18959_Content_39 = {
    Text = "Non comprendiamo ancora quasi nulla."
  },
  AvgDialog_18959_Content_4 = {
    Text = "Scuoti la testa."
  },
  AvgDialog_18959_Content_40 = {
    Text = "Sospetto... che questo nuovo Custode possa essere la chiave per svelare la verità."
  },
  AvgDialog_18959_Content_41 = {
    Text = "Il solo fatto che {Male=egli,Female=ella} ricordi le vittime della Dissoluzione lo rende {Male=lo,Female=la} rende un individuo straordinario."
  },
  AvgDialog_18959_Content_42 = {
    Text = "{Male=Lui,Female=Lei} supererà tutti noi."
  },
  AvgDialog_18959_Content_43 = {
    Text = "Via Southwark 44, Rovine del Museo delle Cere"
  },
  AvgDialog_18959_Content_44 = {
    Text = "Che rovina. Entro tre giorni, questo luogo si trasformerà in una pozza di fango nero e poi svanirà completamente."
  },
  AvgDialog_18959_Content_45 = {
    Text = "Dov'è Rogers?"
  },
  AvgDialog_18959_Content_46 = {
    Text = "Lui e Pandia sono ora Cacciati dai segugi del Comitato. L'ultima volta che ci siamo visti, eravamo in un Sanatorio nella Cité."
  },
  AvgDialog_18959_Content_47 = {
    Text = "Hanno agito indisturbati per troppo tempo. Hanno bisogno di questa lezione."
  },
  AvgDialog_18959_Content_48 = {
    Text = "Prima di andarsene, Pandia mi ha dato qualcosa, dicendo che era un pegno di scuse per te."
  },
  AvgDialog_18959_Content_49 = {
    Text = "Cos'è questo... un fascicolo del personale?"
  },
  AvgDialog_18959_Content_5 = {
    Text = "Completamente Dissolto, senza neppure un frammento di Nucleo d'Argento."
  },
  AvgDialog_18959_Content_50 = {
    Text = "Aprilo e guarda. Sorprese attendono all'interno."
  },
  AvgDialog_18959_Content_51 = {
    Text = "%player%...?"
  },
  AvgDialog_18959_Content_52 = {
    Text = "Data di Nascita sconosciuta... Ammesso da Mythag l'anno scorso. Mai addestrato, eppure in grado di creare un Legame con molteplici Risvegliati in Battaglia..."
  },
  AvgDialog_18959_Content_53 = {
    Text = "Interessante. Chi avrebbe mai pensato che Mythag avesse un asso nella manica."
  },
  AvgDialog_18959_Content_54 = {
    Text = "A quanto pare l'\"Evento Lanterna\" non impartì loro una lezione abbastanza dura, a suo tempo."
  },
  AvgDialog_18959_Content_55 = {
    Text = "È tempo di visitare l'accademia e rendere omaggio alla tomba del mio amatissimo mentore."
  },
  AvgDialog_18959_Content_56 = {
    Text = [[
Periferia di Londinium
Cimitero di Shoreditch]]
  },
  AvgDialog_18959_Content_57 = {
    Text = "Signorina 24"
  },
  AvgDialog_18959_Content_58 = {
    Text = "{Male=Signor,Female=Signorina} %player%! Cosa vi porta qui...?"
  },
  AvgDialog_18959_Content_59 = {
    Text = "Per rendere omaggio a Jenkin."
  },
  AvgDialog_18959_Content_6 = {
    Text = "Poche persone producono Nuclei d'Argento dopo la morte. Pensavo che ormai l'avessi capito."
  },
  AvgDialog_18959_Content_60 = {
    Text = "Ti accucci e spazzoli delicatamente i detriti dalla piccola lapide. È vuota; non hai ancora deciso di incidervi alcuna parola."
  },
  AvgDialog_18959_Content_61 = {
    Text = "Come se... una volta incise le parole, la partenza di Jenkin divenisse realtà."
  },
  AvgDialog_18959_Content_62 = {
    Text = "Signorina 24, perché non hai rivelato la tua vera identità al Museo delle Cere?"
  },
  AvgDialog_18959_Content_63 = {Text = "..."},
  AvgDialog_18959_Content_64 = {
    Text = "All'epoca ero così confusa e spaventata... Se Jenkin mi avesse vista così, le si sarebbe spezzato il cuore."
  },
  AvgDialog_18959_Content_65 = {
    Text = "Jenkin è più forte di quanto sembri — può reggere la verità."
  },
  AvgDialog_18959_Content_66 = {
    Text = "Sì... è sempre stata la bambina più coraggiosa e forte che abbia mai conosciuto."
  },
  AvgDialog_18959_Content_67 = {
    Text = "Ho saputo dell'accademia. Nessuna traccia del Nucleo d'Argento di Jenkin, vero?"
  },
  AvgDialog_18959_Content_68 = {
    Text = "William non ha ancora trovato nulla. Ma non preoccuparti, Signorina 24."
  },
  AvgDialog_18959_Content_69 = {
    Text = "Interrogherò personalmente Rogers una volta che lo avremo preso."
  },
  AvgDialog_18959_Content_7 = {
    Text = "Ma Jenkin è diverso..."
  },
  AvgDialog_18959_Content_70 = {
    Text = "24 scuote la testa."
  },
  AvgDialog_18959_Content_71 = {
    Text = "So che non rinuncerai. È solo che temo... i miei ricordi di Jenkin stiano cominciando a svanire."
  },
  AvgDialog_18959_Content_72 = {
    Text = "Temo che un giorno le passerò accanto senza riconoscerla."
  },
  AvgDialog_18959_Content_73 = {
    Text = "Te lo dirò quando l'avrai dimenticata."
  },
  AvgDialog_18959_Content_74 = {
    Text = "Di come vi siete incontrate, di come avete vissuto insieme, di come lei ti ha salvata, e di come è diventata la nostra eroina leggendaria..."
  },
  AvgDialog_18959_Content_75 = {
    Text = "Le tue parole sfumarono a poco a poco, disperdendosi infine nella brezza gentile."
  },
  AvgDialog_18959_Content_76 = {
    Text = "Squeak... Squeak..."
  },
  AvgDialog_18959_Content_77 = {
    Text = "Un suono flebile raggiunge d'improvviso le tue orecchie, con una cadenza ritmica."
  },
  AvgDialog_18959_Content_78 = {
    Text = "Un topo... <Big:Brown?!>"
  },
  AvgDialog_18959_Content_79 = {Text = "!!"},
  AvgDialog_18959_Content_8 = {
    Text = "Aiutami, ti restituirò il portafoglio e i documenti, tieni il segreto.\nNon aiutarmi... hehe!"
  },
  AvgDialog_18959_Content_80 = {
    Text = "Sembra... vicino."
  },
  AvgDialog_18959_Content_81 = {
    Text = "Ti volti rapidamente, ed eccolo lì — un topolino grassoccio nell'erba dietro la lapide."
  },
  AvgDialog_18959_Content_82 = {
    Text = "Zzz... Zzz..."
  },
  AvgDialog_18959_Content_83 = {
    Text = "La taglia e il colore... È proprio Brown!"
  },
  AvgDialog_18959_Content_84 = {
    Text = "Tu e 24 esclamate all'unisono."
  },
  AvgDialog_18959_Content_85 = {
    Text = "Il topo — scomparso dall'incidente al Museo delle Cere — non viene svegliato dalla tua presenza."
  },
  AvgDialog_18959_Content_86 = {
    Text = "Come se fosse appena sopravvissuto a un'avventura mozzafiato e ora giacesse esausto al termine del viaggio."
  },
  AvgDialog_18959_Content_87 = {
    Text = "Uff... Ahh... Zzz..."
  },
  AvgDialog_18959_Content_88 = {
    Text = "Sembra che tenga qualcosa..."
  },
  AvgDialog_18959_Content_89 = {Text = "..."},
  AvgDialog_18959_Content_9 = {
    Text = "<Big:...La Primadonna del Mar Baltico! Giusto?>"
  },
  AvgDialog_18959_Content_90 = {
    Text = "È un Nucleo d'Argento. Il Nucleo d'Argento di Jenkin."
  },
  AvgDialog_18959_Content_91 = {
    Text = "Un Nucleo d'Argento riposa tra le sue zampette. Un nucleo grezzo, che emana un bagliore torbido."
  },
  AvgDialog_18959_Content_92 = {
    Text = "Da quel debole bagliore, ti sembra di udire un battito cardiaco incredibilmente gioioso e vivace."
  },
  AvgDialog_18959_Content_93 = {
    Text = "È da tanto, Jenkin."
  },
  AvgDialog_18959_Content_94 = {
    Text = "Il cielo si rasserena finalmente. Il sole è alto, e proietta una luce dorata con il giusto calore."
  },
  AvgDialog_18959_Content_95 = {
    Text = "Il vento porta il fresco profumo della terra. Tu e 24 vi bagnate nella calda luce del sole e vi scambiate un sorriso."
  },
  AvgDialog_18959_Content_96 = {
    Text = "Andiamo, Signorina 24."
  },
  AvgDialog_18959_Content_97 = {
    Text = "Le nuvole si sono diradate, e la vostra avventura è appena cominciata."
  },
  AvgDialog_18960_Content_1 = {
    Text = "Crollo Silente"
  },
  AvgDialog_18960_Content_10 = {
    Text = "Ma non abbiamo scelta."
  },
  AvgDialog_18960_Content_11 = {
    Text = "Possiamo provare."
  },
  AvgDialog_18960_Content_12 = {
    Text = "%player%, ho bisogno che tu mantenga la calma."
  },
  AvgDialog_18960_Content_13 = {
    Text = "Il sentiero davanti è sommerso dalla D-melma. Anche i Risvegliati risentiranno di un'esposizione prolungata."
  },
  AvgDialog_18960_Content_14 = {
    Text = "Non possiamo tornare indietro per la strada da cui siamo venuti. Dovremo trovare un'altra uscita."
  },
  AvgDialog_18960_Content_15 = {
    Text = "Altre vie... Altri sentieri..."
  },
  AvgDialog_18960_Content_16 = {Text = "Fatto!"},
  AvgDialog_18960_Content_17 = {
    Text = "Guarda, una presa d'aria laggiù."
  },
  AvgDialog_18960_Content_18 = {
    Text = "Segui lo sguardo di Jenkin e alzi gli occhi. La piccola presa d'aria è proprio sopra di voi."
  },
  AvgDialog_18960_Content_19 = {
    Text = "Potrebbe esserci un accesso all'ufficio del direttore, e dovrebbe essere privo di D-melma..."
  },
  AvgDialog_18960_Content_2 = {
    Text = "4:15, Museo delle Cere di Rogers"
  },
  AvgDialog_18960_Content_20 = {
    Text = "No, questo passaggio è troppo stretto. Non riusciamo a entrare."
  },
  AvgDialog_18960_Content_21 = {Text = "Io sì."},
  AvgDialog_18960_Content_22 = {
    Text = "Sono il \"topolino\", no?"
  },
  AvgDialog_18960_Content_23 = {Text = "Squeak!"},
  AvgDialog_18960_Content_24 = {
    Text = "No, è troppo pericoloso. Non possiamo essere certi che la chiave sia ancora lì, né che questo condotto di ventilazione—"
  },
  AvgDialog_18960_Content_25 = {
    Text = "Tch. Parli troppo, signorina Ramona. Pensavo fossi più diretta."
  },
  AvgDialog_18960_Content_26 = {
    Text = "Mettiamo le cose in chiaro: primo, al momento non c'è altra via, giusto? Meglio che restare ad aspettare la morte."
  },
  AvgDialog_18960_Content_27 = {
    Text = "Secondo, andrò con Brown. Io comando, lui recupera la Chiave."
  },
  AvgDialog_18960_Content_28 = {
    Text = "Squeak! Squeak, squeak!"
  },
  AvgDialog_18960_Content_29 = {Text = "Terzo..."},
  AvgDialog_18960_Content_3 = {
    Text = "Barcolli tra le rovine, i tuoi respiri affannosi riempiono l'aria."
  },
  AvgDialog_18960_Content_30 = {
    Text = "Vi ho causato un sacco di problemi. Sorella si è persino ferita per me."
  },
  AvgDialog_18960_Content_31 = {Text = "Quindi..."},
  AvgDialog_18960_Content_32 = {
    Text = "Fatemi aiutare. Non sopporto più essere protetta in continuazione."
  },
  AvgDialog_18960_Content_33 = {
    Text = "Poi si lancia nel condotto, scomparendo all'istante, proprio come faceva sempre sfrecciando per il Distretto di White Chapel."
  },
  AvgDialog_18960_Content_34 = {
    Text = "Jenkin...! Non mi ascolta mai..."
  },
  AvgDialog_18960_Content_35 = {
    Text = "Non sottovalutate Jenkin. È più agile di chiunque di noi; ce la farà."
  },
  AvgDialog_18960_Content_36 = {
    Text = "...Io credo in lei."
  },
  AvgDialog_18960_Content_4 = {
    Text = "Finalmente, scorgi il pesante portone davanti a te. Basta una leggera spinta e—"
  },
  AvgDialog_18960_Content_5 = {
    Text = "Ugh, chiuso a chiave."
  },
  AvgDialog_18960_Content_6 = {
    Text = "Davanti a voi si stende un oceano nero, il pericolo si avvicina e non c'è possibilità di ritirata."
  },
  AvgDialog_18960_Content_7 = {
    Text = "Questa dovrebbe essere la porta di cui parlava William. La chiave dovrebbe trovarsi nell'ufficio del direttore."
  },
  AvgDialog_18960_Content_8 = {
    Text = "Non possiamo tornare là."
  },
  AvgDialog_18960_Content_9 = {
    Text = "Questo posto è invaso dalla D-melma... Persino un Risvegliato non resisterebbe a lungo esposto a tutto questo."
  },
  AvgDialog_18961_Content_1 = {
    Text = "Sottocanale"
  },
  AvgDialog_18961_Content_10 = {
    Text = "Ah, che sonno, che sonno!"
  },
  AvgDialog_18961_Content_100 = {
    Text = "Un istante dopo, con un guizzo del polso, la cera bollente si riversa giù, sbocciando in grotteschi petali scarlatti sul suo braccio pallido."
  },
  AvgDialog_18961_Content_101 = {
    Text = "Aaaaaah—!"
  },
  AvgDialog_18961_Content_102 = {
    Text = "Oh... che motivi squisiti."
  },
  AvgDialog_18961_Content_103 = {
    Text = "George odia i maiali rumorosi. Riempitele la bocca di cera per farla tacere."
  },
  AvgDialog_18961_Content_104 = {
    Text = "Il candelabro fluttuante vola in faccia a Jenkin, il suo calore rovente le arrossa il viso."
  },
  AvgDialog_18961_Content_105 = {
    Text = "Il candeliere è colmo di cera bollente, sul punto di traboccare."
  },
  AvgDialog_18961_Content_106 = {
    Text = "<Shake:Bugiardo... Avevi detto che non avrebbe fatto male...>"
  },
  AvgDialog_18961_Content_107 = {
    Text = "Perdonami, cara, è passata un'eternità da quando ero umana. Avevo dimenticato quanto fosse caotico provare sensazioni..."
  },
  AvgDialog_18961_Content_108 = {
    Text = "Perfetto. Voi due, venite a tenerle la bocca aperta."
  },
  AvgDialog_18961_Content_109 = {
    Text = "Allora versatele la cera, e il topo di fogna tacerà per sempre."
  },
  AvgDialog_18961_Content_11 = {
    Text = "Fai tardi ancora una volta e ti ficco in una bara per sempre!"
  },
  AvgDialog_18961_Content_110 = {
    Text = "Basta... Basta! Lei è innocente in tutto questo..."
  },
  AvgDialog_18961_Content_111 = {
    Text = "<Small:Sorella... fa così male... fa male...>"
  },
  AvgDialog_18961_Content_112 = {
    Text = "No... no. Ho cambiato idea! Non voglio morire! State lontani...!"
  },
  AvgDialog_18961_Content_113 = {Text = "..."},
  AvgDialog_18961_Content_114 = {
    Text = "...Aspettate un momento."
  },
  AvgDialog_18961_Content_115 = {
    Text = "Nel caos, udite all'improvviso un lieve sospiro."
  },
  AvgDialog_18961_Content_116 = {
    Text = "Ho detto... aspettate un momento, per favore."
  },
  AvgDialog_18961_Content_12 = {
    Text = "Scusate, Miss Pandia..."
  },
  AvgDialog_18961_Content_13 = {
    Text = "<Big:LADY PANDIA—!!>"
  },
  AvgDialog_18961_Content_14 = {
    Text = "La figura di una donna scivola come una nuvola, la sua gonna lunga volteggia in un bagliore bianco. Si inginocchia prostrata dinanzi a Pandia."
  },
  AvgDialog_18961_Content_15 = {
    Text = "Lady Pandia! Vi prego, non fate del male a 24 in questo modo. Se qualcuno deve essere punito..."
  },
  AvgDialog_18961_Content_16 = {
    Text = "Che sia io!"
  },
  AvgDialog_18961_Content_17 = {Text = "..."},
  AvgDialog_18961_Content_18 = {
    Text = "Ho cambiato idea. Siete state tutte degli animaletti così docili. Potete ritirarvi."
  },
  AvgDialog_18961_Content_19 = {
    Text = "Mia signora, so che non avete cuore di rimproverarmi. Siete sempre stata così gentile..."
  },
  AvgDialog_18961_Content_2 = {
    Text = "Splendido, tutta la combriccola è qui. Ora possiamo preparare il grande Dono di benvenuto per Mythag."
  },
  AvgDialog_18961_Content_20 = {Text = "..."},
  AvgDialog_18961_Content_21 = {
    Text = "Tesoro, mio dolcissimo bocconcino, saresti così cara da lasciarmi la gamba?"
  },
  AvgDialog_18961_Content_22 = {
    Text = "Ogni vostro desiderio è un ordine, Lady Pandia."
  },
  AvgDialog_18961_Content_23 = {
    Text = "Perfetto. Proprio così... Ora voltati, fai dieci passi aggraziati, esci da questa stanza e non voltarti mai indietro."
  },
  AvgDialog_18961_Content_24 = {
    Text = "Ci comprendiamo a vicenda?"
  },
  AvgDialog_18961_Content_25 = {
    Text = "Capito... Mi mancherete terribilmente, Lady Pandia...\nNo, mi mancate già adesso!"
  },
  AvgDialog_18961_Content_26 = {
    Text = "La donna si volta e con premura chiude la porta prima di andarsene."
  },
  AvgDialog_18961_Content_27 = {
    Text = "*Sigh*... Che noia spaventosa."
  },
  AvgDialog_18961_Content_28 = {
    Text = "Dopo essersi assicurata che la porta sia ben chiusa, Pandia trae un respiro profondo e torna alla sua solita energia."
  },
  AvgDialog_18961_Content_29 = {
    Text = "Ora, miei cari, dove eravamo rimasti?"
  },
  AvgDialog_18961_Content_3 = {
    Text = "Devo dire, però, che questo momento ha impiegato un tempo agonizzante per arrivare."
  },
  AvgDialog_18961_Content_30 = {
    Text = "Respirare... così difficile."
  },
  AvgDialog_18961_Content_31 = {Text = "..."},
  AvgDialog_18961_Content_32 = {
    Text = "Stai ferma. Il tuo trucco richiede attenzione."
  },
  AvgDialog_18961_Content_33 = {
    Text = "Oh cielo, le labbra necessitano di più lavoro. Hmm..."
  },
  AvgDialog_18961_Content_34 = {
    Text = "Sei tu, Rogers..."
  },
  AvgDialog_18961_Content_35 = {
    Text = "Dita fredde sfiorano l'angolo delle tue labbra, e senti l'odore pungente della decomposizione."
  },
  AvgDialog_18961_Content_36 = {
    Text = "Cerchi di muoverti, ma ti rendi conto che il tuo intero corpo è intrappolato in un macchinario freddo e rigido."
  },
  AvgDialog_18961_Content_37 = {
    Text = "Splendido. Sei un materiale ideale per una scultura."
  },
  AvgDialog_18961_Content_38 = {
    Text = "%player%, sei sveglio!"
  },
  AvgDialog_18961_Content_39 = {
    Text = "Lasciami andare... Ugh!"
  },
  AvgDialog_18961_Content_4 = {
    Text = "24, mia preziosa 24, vieni qui."
  },
  AvgDialog_18961_Content_40 = {
    Text = "Non muoverti! È costata tanta fatica sistemarti così perfettamente."
  },
  AvgDialog_18961_Content_41 = {
    Text = "Vedi quella bella bara laggiù? Fatta su misura apposta per te.\nSperimenterai una meravigliosa rinascita!"
  },
  AvgDialog_18961_Content_42 = {
    Text = "Come sculture di cera, naturalmente. Hehe. Che tema sceglieremo questa volta? Lasciami riflettere..."
  },
  AvgDialog_18961_Content_43 = {
    Text = "Nessun soriano trovato, per quanto cercasse con cura—"
  },
  AvgDialog_18961_Content_44 = {
    Text = "Cercato con cura, cercato con cura..."
  },
  AvgDialog_18961_Content_45 = {
    Text = "Ramona... Ramona?! Per l'amor del cielo, smettila di cantare..."
  },
  AvgDialog_18961_Content_46 = {
    Text = "È così da quando mi sono svegliata, canta senza sosta."
  },
  AvgDialog_18961_Content_47 = {
    Text = "La tua compagna ha realizzato una Scultura davvero adorabile. Il maestro Rogers ci ha lavorato per un'ora intera."
  },
  AvgDialog_18961_Content_48 = {
    Text = "Niente gattino! Miao!"
  },
  AvgDialog_18961_Content_49 = {
    Text = "Allora? Non è deliziosa? Non vorresti portartela a Focolare?"
  },
  AvgDialog_18961_Content_5 = {
    Text = "...Sì, Lady Pandia."
  },
  AvgDialog_18961_Content_50 = {
    Text = "Tch, togli le tue sporche mani da lei!"
  },
  AvgDialog_18961_Content_51 = {
    Text = "Rogers, sei tu quello che mi ha stordito nel laboratorio."
  },
  AvgDialog_18961_Content_52 = {
    Text = "Sei tu quello che ha fatto Uccidere Aigis e Piccolo Mac, che ha fatto sparire mia sorella..."
  },
  AvgDialog_18961_Content_53 = {
    Text = "Cos'è Aigis?"
  },
  AvgDialog_18961_Content_54 = {
    Text = "Scusate, ma George non si preoccupa dei nomi delle cose buttate via e della spazzatura."
  },
  AvgDialog_18961_Content_55 = {
    Text = "A chi dai del nome?! Porco!"
  },
  AvgDialog_18961_Content_56 = {
    Text = "Hmm, non è forse vero? Tu sei Jenkin, giusto? Sarah ci ha raccontato le storie della piccola Jenkin."
  },
  AvgDialog_18961_Content_57 = {
    Text = "La piccola Jenkin nacque quando il suo papà ubriacone scappò via."
  },
  AvgDialog_18961_Content_58 = {
    Text = "La mamma della piccola Jenkin contrasse la Dissoluzione e impazzì."
  },
  AvgDialog_18961_Content_59 = {
    Text = "La Donna pazza picchia la piccola Jenkin ogni giorno con scope, cinture, qualsiasi cosa trovi, urlando parole orribili..."
  },
  AvgDialog_18961_Content_6 = {
    Text = "SCHIAFFO—!"
  },
  AvgDialog_18961_Content_60 = {
    Text = "Tu... Stai mentendo..."
  },
  AvgDialog_18961_Content_61 = {
    Text = "Oh sì, dal suo Corpo cola anche melma nera. Il letto, il pavimento, tutto appiccicoso e bagnato... Bleah!"
  },
  AvgDialog_18961_Content_62 = {
    Text = "Dicendo questo, George rabbrividisce in modo esagerato e poi ridacchia."
  },
  AvgDialog_18961_Content_63 = {
    Text = "Poi la donna pazza scappò via da sola. Il piccolo Jenkin aspettò davanti alla porta, aspettò e aspettò...\nDov'era andata? Nessuno lo sa."
  },
  AvgDialog_18961_Content_64 = {
    Text = "No, non è vero..."
  },
  AvgDialog_18961_Content_65 = {
    Text = "Ptuh, ptuh, George doveva proprio dirlo! Poi la piccola Jenkin finì all'orfanotrofio, un altro mucchio di spazzatura."
  },
  AvgDialog_18961_Content_66 = {
    Text = "Ammettilo, sei solo spazzatura di strada trascinata dalla Pioggia nelle fogne di Londinium!"
  },
  AvgDialog_18961_Content_67 = {
    Text = "Perfino tua sorella... non ti ha forse lasciata con delle scuse perché era stanca di te?"
  },
  AvgDialog_18961_Content_68 = {
    Text = "Taci... <Big:SILENZIO!>"
  },
  AvgDialog_18961_Content_69 = {
    Text = "Jenkin trema, il volto pallido come la morte. Apre la bocca, vorrebbe dire qualcosa, ma alla fine abbassa il capo, frustrata."
  },
  AvgDialog_18961_Content_7 = {
    Text = "La frusta nera schiocca, e 24 viene scaraventata a terra, con segni rossi che compaiono all'istante sul suo corpo."
  },
  AvgDialog_18961_Content_70 = {
    Text = "Già, che diritto ha? Per i topi nelle fogne, l'amore è un lusso assoluto — una Caramella che possono solo osare di raggiungere nei loro Sogni."
  },
  AvgDialog_18961_Content_71 = {
    Text = "Un paio di mani accarezzano dolcemente la testa di Jenkin."
  },
  AvgDialog_18961_Content_72 = {
    Text = "P-povera, piccola creatura spezzata. Ne ho conosciuti tanti come te — indesiderati, maltrattati."
  },
  AvgDialog_18961_Content_73 = {
    Text = "Lascia che ti c-conceda la liberazione — come arte eterna."
  },
  AvgDialog_18961_Content_74 = {
    Text = "Aiutarci? Dopo quello che hai fatto ad Aigis, a Piccolo Mac..."
  },
  AvgDialog_18961_Content_75 = {
    Text = "Puoi davvero sostenere che prolungare la loro sofferenza sia misericordia?"
  },
  AvgDialog_18961_Content_76 = {
    Text = "<Shake:Io... Io non lo so...>"
  },
  AvgDialog_18961_Content_77 = {
    Text = "Non temere, bambino smarrito.\nTi plasmerò in un'opera d'arte mozzafiato, indolore come un sussurro."
  },
  AvgDialog_18961_Content_78 = {
    Text = "Jenkin, non cadere nella loro logica contorta!"
  },
  AvgDialog_18961_Content_79 = {
    Text = [[
Rogers, stai solo ingannando te stesso.
Credi davvero che diventare una scultura di cera cancelli tutto?]]
  },
  AvgDialog_18961_Content_8 = {Text = "Ngh...!"},
  AvgDialog_18961_Content_80 = {
    Text = [[
Sono davvero partecipanti volontari?
Puoi giurare di non aver mai costretto o manipolato i tuoi "materiali?!"]]
  },
  AvgDialog_18961_Content_81 = {
    Text = "Smetti di combattere."
  },
  AvgDialog_18961_Content_82 = {
    Text = "Ragazzino, hai ragione. Questo mondo è marcio."
  },
  AvgDialog_18961_Content_83 = {
    Text = "Tanto siamo in trappola comunque... Fallo, adesso. Mi manca stare con la mamma."
  },
  AvgDialog_18961_Content_84 = {
    Text = "Jenkin, so che sei giù di morale.\nMa ricorda perché siamo qui: per trovare tua sorella. Conta su di noi."
  },
  AvgDialog_18961_Content_85 = {
    Text = "Scusa, %player%. Sono stanco."
  },
  AvgDialog_18961_Content_86 = {
    Text = "Forse questa \"sorella\" esiste solo nella mia testa..."
  },
  AvgDialog_18961_Content_87 = {
    Text = "Altrimenti perché non è venuta a trovarmi?"
  },
  AvgDialog_18961_Content_88 = {
    Text = "Ora che il nostro topolino ha fatto Squeak, che cosa stiamo aspettando?"
  },
  AvgDialog_18961_Content_89 = {
    Text = "24, Leigh, versate la cera. Piano piano..."
  },
  AvgDialog_18961_Content_9 = {
    Text = "Ho aspettato fino quasi a diventare di pietra, e ancora nessun segno di te. Ho dovuto mandare George a cercarti."
  },
  AvgDialog_18961_Content_90 = {
    Text = "...Come comandate."
  },
  AvgDialog_18961_Content_91 = {
    Text = "Lady Pandia, le vostre parole sono il mio testo sacro."
  },
  AvgDialog_18961_Content_92 = {
    Text = "Quindi lavorate insieme... Capisco, siete complici."
  },
  AvgDialog_18961_Content_93 = {
    Text = "Heh... Sono proprio un'idiota."
  },
  AvgDialog_18961_Content_94 = {
    Text = "La Donna, reggendo una tazza colma di cera, si avvicina a Jenkin."
  },
  AvgDialog_18961_Content_95 = {
    Text = "A dire il vero... le fogne non sono poi così orribili."
  },
  AvgDialog_18961_Content_96 = {
    Text = "Oltre a spazzatura e pasti in putrefazione, a volte trovo pesce in scatola fresco. Una volta, un Bouquet di tulipani."
  },
  AvgDialog_18961_Content_97 = {Text = "...?"},
  AvgDialog_18961_Content_98 = {
    Text = "Sorpreso? Conosco questi Tunnel meglio di quanto tu conosca il tuo stesso riflesso."
  },
  AvgDialog_18961_Content_99 = {Text = "Splash—"},
  AvgDialog_18962_Content_1 = {
    Text = "William, stai bene?"
  },
  AvgDialog_18962_Content_2 = {
    Text = "*Cough cough*... Non badatemi. Proseguite con la missione."
  },
  AvgDialog_18962_Content_3 = {
    Text = "Non preoccuparti, William. Ti tirerò fuori da qui."
  },
  AvgDialog_18963_Content_1 = {
    Text = "<Change>Waaah... AAAAAHHHH!"
  },
  AvgDialog_18963_Content_10 = {
    Text = "Vedo il Passaggio di cui parlava William! Tutti, restate uniti e non allontanatevi!"
  },
  AvgDialog_18963_Content_11 = {
    Text = "Oh... Si sono tutti dimenticati di me? Sono qui con l'ordine di fermarvi tutti quanti."
  },
  AvgDialog_18963_Content_12 = {
    Text = "<Big:Fuori dai piedi!>"
  },
  AvgDialog_18963_Content_13 = {
    Text = "Leigh sorride a Jenkin e 24, le cui mani restano strette l'una nell'altra."
  },
  AvgDialog_18963_Content_14 = {
    Text = "Sai perché conosco così bene le fogne, topolino?"
  },
  AvgDialog_18963_Content_15 = {Text = "...Eh?"},
  AvgDialog_18963_Content_16 = {
    Text = "Quel giorno... degli agenti di polizia entrarono nelle fogne. Tutti armati di pistole."
  },
  AvgDialog_18963_Content_17 = {
    Text = "Mio fratello e io ci sostenevamo a vicenda, correndo, e correndo..."
  },
  AvgDialog_18963_Content_18 = {
    Text = "Mio fratello è stato colpito. Ho contato, uno per uno. 14, 15, 16...\nSì, è stato colpito un totale di 16 volte."
  },
  AvgDialog_18963_Content_19 = {
    Text = "È crivellato di buchi, sanguina copiosamente. Il suo sangue aveva un odore delizioso. Era così, così invitante...\nMa sono riuscita a trattenermi."
  },
  AvgDialog_18963_Content_2 = {
    Text = "La massa di sculture di cera ammassate crolla."
  },
  AvgDialog_18963_Content_20 = {
    Text = "Non ho bevuto una sola goccia del suo sangue."
  },
  AvgDialog_18963_Content_21 = {
    Text = "Che cosa sta farfugliando..."
  },
  AvgDialog_18963_Content_22 = {
    Text = "Non è niente... Ho semplicemente cambiato idea all'improvviso. Andate pure avanti."
  },
  AvgDialog_18963_Content_23 = {
    Text = "Ci lasci andare, così? Sei davvero così gentile...?"
  },
  AvgDialog_18963_Content_24 = {
    Text = "Leigh non risponde, ma si limita a indicare avanti."
  },
  AvgDialog_18963_Content_25 = {
    Text = "Il passaggio è laggiù. Vi consiglio di muovervi in fretta, a meno che non vogliate morire qui."
  },
  AvgDialog_18963_Content_26 = {Text = "E tu...?"},
  AvgDialog_18963_Content_27 = {
    Text = "Leigh ti guarda con un lampo di sorpresa, come se fosse confusa dalla tua domanda."
  },
  AvgDialog_18963_Content_28 = {
    Text = "Poi alza lo sguardo verso la melma nera che gocciola sopra di lei e accenna un sorriso vacuo."
  },
  AvgDialog_18963_Content_29 = {
    Text = "Arrivederci, {Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_18963_Content_3 = {
    Text = "La testa di George rotola a terra, i suoi grandi occhi ancora fissi su di te con uno sguardo furioso."
  },
  AvgDialog_18963_Content_30 = {
    Text = "Mentre esci dal seminterrato, ti volti a guardare Leigh."
  },
  AvgDialog_18963_Content_31 = {
    Text = "La D-melma nera scorre sul pavimento e sul soffitto. Leigh è in piedi al centro delle rovine, esile come un'erbaccia avvizzita."
  },
  AvgDialog_18963_Content_32 = {
    Text = [[
Non riesci a distinguere la sua espressione, ma puoi percepire il suo sguardo.
Ti ha osservato per tutto il tempo.]]
  },
  AvgDialog_18963_Content_4 = {
    Text = "<Change>Io sono... perfetta..."
  },
  AvgDialog_18963_Content_5 = {
    Text = "La Scultura di Cera si dissolve gradualmente, come tintura grigia che si mescola in un oceano nero di Dissoluzione, senza lasciare alcuna traccia."
  },
  AvgDialog_18963_Content_6 = {
    Text = "Così finisce... finalmente."
  },
  AvgDialog_18963_Content_7 = {
    Text = "<Big:Boom—!!>"
  },
  AvgDialog_18963_Content_8 = {
    Text = "Un torrente nero irrompe con violenza, inghiottendo tutto ciò che incontra sul suo cammino."
  },
  AvgDialog_18963_Content_9 = {
    Text = "Il Museo delle Cere si sta dissolvendo completamente. Dobbiamo evacuare adesso!"
  },
  AvgDialog_18964_Content_1 = {
    Text = "Fumo e Violetta"
  },
  AvgDialog_18964_Content_10 = {
    Text = "...Cinque minuti."
  },
  AvgDialog_18964_Content_11 = {
    Text = "Rogers, Rogers... ci rincontriamo."
  },
  AvgDialog_18964_Content_12 = {
    Text = "E tu saresti...?"
  },
  AvgDialog_18964_Content_13 = {
    Text = "L'ultima volta che ti ho visto, avevi 8 o 9 anni? Seduto tra un mucchio di cadaveri e sculture di cera."
  },
  AvgDialog_18964_Content_14 = {
    Text = "Quando tua madre ti portò via, piangevi e ti rifiutavi di andartene."
  },
  AvgDialog_18964_Content_15 = {
    Text = "Heh... Faccio il detective da 30 anni. Nel momento in cui ho visto i tuoi occhi, ho capito che eri un completo farabutto, una vera feccia."
  },
  AvgDialog_18964_Content_16 = {
    Text = "Quindi sei tu."
  },
  AvgDialog_18964_Content_17 = {
    Text = "<Yellow:Ho saputo che avevi ucciso \"Mr. Cera\" fin dall'inizio.>"
  },
  AvgDialog_18964_Content_18 = {
    Text = "Dimmi, dove l'hai nascosto dopo?"
  },
  AvgDialog_18964_Content_19 = {Text = "..."},
  AvgDialog_18964_Content_2 = {
    Text = [[
19:05, Museo delle Cere di Rogers
Quattro ore prima]]
  },
  AvgDialog_18964_Content_20 = {
    Text = "Parla. Sei balbuziente, non muto."
  },
  AvgDialog_18964_Content_21 = {Text = "..."},
  AvgDialog_18964_Content_22 = {
    Text = "P-proprio qui."
  },
  AvgDialog_18964_Content_23 = {Text = "...Cosa?"},
  AvgDialog_18964_Content_24 = {
    Text = "È ovunque... sottoterra, nella vetrina, nei miei incubi..."
  },
  AvgDialog_18964_Content_25 = {
    Text = "<Red:e... dietro di te.>"
  },
  AvgDialog_18964_Content_26 = {
    Text = "Nel momento in cui Rogers parlò, una sottile linea rossa apparve sul collo del detective."
  },
  AvgDialog_18964_Content_27 = {
    Text = "La sua testa scivolò dalle spalle, rotolando sul pavimento, gli occhi ancora spalancati."
  },
  AvgDialog_18964_Content_28 = {
    Text = "Chi c'è? Mostrati!"
  },
  AvgDialog_18964_Content_29 = {
    Text = "Il ricco profumo di narciso scorre lentamente nella notte, avvolgendo William in accumuli di pallida foschia viola."
  },
  AvgDialog_18964_Content_3 = {Text = "Splash—!"},
  AvgDialog_18964_Content_30 = {
    Text = "Sognare a occhi aperti non è una buona abitudine, Investigatore."
  },
  AvgDialog_18964_Content_31 = {
    Text = [[
23:30, Museo delle Cere di Rogers
Studio]]
  },
  AvgDialog_18964_Content_32 = {
    Text = "Aiuto... aiutatemi... mi sta divorando viva—"
  },
  AvgDialog_18964_Content_33 = {
    Text = "Una voce di donna... Sorella?!"
  },
  AvgDialog_18964_Content_34 = {
    Text = "Quel rumore sembra provenire da laggiù. Andiamo a controllare."
  },
  AvgDialog_18964_Content_4 = {
    Text = "I detective infrangono rapidamente il vetro della vetrina, abbattendo le sculture di cera una dopo l'altra."
  },
  AvgDialog_18964_Content_5 = {
    Text = "B-bruti, questa è una profanazione dell'arte..."
  },
  AvgDialog_18964_Content_6 = {
    Text = "<Big:NOOO!!!>"
  },
  AvgDialog_18964_Content_7 = {
    Text = "Signor Rogers, è sospettato di coinvolgimento nelle sparizioni del Distretto di White Chapel. In base all'<Yellow:Articolo 112 del Trattato>, abbiamo il diritto di trattenerla e interrogarla presso il Comitato."
  },
  AvgDialog_18964_Content_8 = {
    Text = "<Shake:Verrò con voi. Solo, solo non distruggete le mie opere—>"
  },
  AvgDialog_18964_Content_9 = {
    Text = "Aspetta, ho qualcosa da dirgli."
  },
  AvgDialog_18965_Content_1 = {
    Text = "Da dove venite, marmocchi? Siete quelli di cui parlava il curatore...?"
  },
  AvgDialog_18965_Content_10 = {
    Text = "Scommetto che hanno conservato dei fascicoli qui. Apriamolo."
  },
  AvgDialog_18965_Content_11 = {
    Text = "Usi la chiave per aprire la porta dell'armadio."
  },
  AvgDialog_18965_Content_12 = {
    Text = "Album d'arte, vernice..."
  },
  AvgDialog_18965_Content_13 = {
    Text = "Hmm, incisioni raffinate su questo scalpello. Deve valere qualcosa..."
  },
  AvgDialog_18965_Content_14 = {
    Text = "Sembrano oggetti d'antiquariato..."
  },
  AvgDialog_18965_Content_15 = {
    Text = "Heh... Prendi tutto, prendi tutto..."
  },
  AvgDialog_18965_Content_16 = {
    Text = "Brown, siamo ricchi!"
  },
  AvgDialog_18965_Content_17 = {Text = "Squeak!"},
  AvgDialog_18965_Content_18 = {
    Text = "Eh, cos'è questo?"
  },
  AvgDialog_18965_Content_19 = {
    Text = "Un giornale giace silenzioso in un angolo, coperto di muffa nera. Sembra essere lì da molto tempo."
  },
  AvgDialog_18965_Content_2 = {
    Text = "Sai chi siamo e te ne stai lì impalato? Attento o ti graffio."
  },
  AvgDialog_18965_Content_20 = {
    Text = "<Blue:\"Il bizzarro caso del rapimento del Signor Wax?\">"
  },
  AvgDialog_18965_Content_21 = {
    Text = "Pare documentare alcuni eventi inquietanti risalenti a oltre dieci anni fa."
  },
  AvgDialog_18965_Content_22 = {
    Text = "Il serial killer chiamato <Blue:\"Mr. Wax\"> non fu mai catturato..."
  },
  AvgDialog_18965_Content_23 = {
    Text = "La Signorina Sarah ha parlato di questo caso!"
  },
  AvgDialog_18965_Content_24 = {
    Text = "Un certo killer chiamato \"Mr. Wax\" rapiva persone—un centinaio circa—e le trasformava in sculture di cera."
  },
  AvgDialog_18965_Content_25 = {
    Text = "E poi? Alla fine è stato catturato?"
  },
  AvgDialog_18965_Content_26 = {
    Text = "Qui dice \"mai catturato\".\nLa polizia trovò solo alcune vittime a casa sua..."
  },
  AvgDialog_18965_Content_27 = {
    Text = "Jenkin arriccia il naso a disagio mentre parla."
  },
  AvgDialog_18965_Content_28 = {
    Text = [[
Uno psicopatico totale.
Non riuscii a dormire per una settimana dopo aver sentito quella storia da bambino.]]
  },
  AvgDialog_18965_Content_29 = {
    Text = "Trasformare persone in sculture di cera... non è esattamente il modus operandi di Rogers?"
  },
  AvgDialog_18965_Content_3 = {
    Text = "Voi... vedrete! Restate pure qui, se ne avete il coraggio!"
  },
  AvgDialog_18965_Content_30 = {
    Text = "Ma il killer in quella fotografia non è sicuramente Rogers."
  },
  AvgDialog_18965_Content_31 = {
    Text = "Osservi la foto di \"Mr. Wax\". È un uomo sulla trentina, estremamente magro, con occhi infossati che accentuano gli zigomi prominenti."
  },
  AvgDialog_18965_Content_32 = {
    Text = "Niente a che vedere con il Rogers che ricordi."
  },
  AvgDialog_18965_Content_33 = {
    Text = "Quegli occhi... ho la sensazione di averli già visti."
  },
  AvgDialog_18965_Content_34 = {
    Text = "Mettiamo da parte questo per ora."
  },
  AvgDialog_18965_Content_4 = {
    Text = "Lady Chatterley si solleva la gonna ed esce rapidamente dallo studio."
  },
  AvgDialog_18965_Content_5 = {
    Text = "Accidenti, sono scappati."
  },
  AvgDialog_18965_Content_6 = {
    Text = "Heh, buon viaggio, dico io!"
  },
  AvgDialog_18965_Content_7 = {
    Text = "Ora guardate, cos'è questo?"
  },
  AvgDialog_18965_Content_8 = {
    Text = "La chiave dell'armadio? Bel lavoro, Jenkin!"
  },
  AvgDialog_18965_Content_9 = {
    Text = "Niente può fermare il miglior ladro di Londinium!"
  },
  AvgDialog_18966_Content_1 = {
    Text = "Sussurri dell'immortale"
  },
  AvgDialog_18966_Content_10 = {
    Text = "Una <Yellow:D-fessura> perfetta. Il cuore pulsante del museo."
  },
  AvgDialog_18966_Content_11 = {
    Text = "Distorce la realtà stessa.\nAttraverso di esso, gli scarti trovano rinascita, e il nostro patto fu forgiato."
  },
  AvgDialog_18966_Content_12 = {
    Text = "Come rispondendo al ritorno del loro padrone, le sculture di cera ridono ancora più allegramente."
  },
  AvgDialog_18966_Content_13 = {
    Text = "<Shake:Rogers... Rogers...>"
  },
  AvgDialog_18966_Content_14 = {
    Text = "<Shake:La-la-la-la-la~>"
  },
  AvgDialog_18966_Content_15 = {
    Text = "Patto...? Potrebbe forse essere...?"
  },
  AvgDialog_18966_Content_16 = {
    Text = "<Yellow:Tre Regole.> Le devote sentinelle del museo, che puniscono chiunque ne profani la bellezza."
  },
  AvgDialog_18966_Content_17 = {
    Text = "Innumerevoli teste di cera frammentate emettono deliri incomprensibili, poi all'improvviso si voltano all'unisono per fissarti con occhi spalancati."
  },
  AvgDialog_18966_Content_18 = {
    Text = "<Shake:Punire, punire... Hehe...>"
  },
  AvgDialog_18966_Content_19 = {
    Text = "Oh no, ci hanno avvistati. Muoviamoci—"
  },
  AvgDialog_18966_Content_2 = {
    Text = "Ugh... fa male..."
  },
  AvgDialog_18966_Content_20 = {
    Text = "La paraffina bianca si propaga rapidamente, avvinghiandosi all'istante al trasgressore che ha infranto le regole."
  },
  AvgDialog_18966_Content_21 = {
    Text = "Indietro! Ugh..."
  },
  AvgDialog_18966_Content_22 = {
    Text = "Ti raggiunge il petto e sta per insinuarsi nella bocca e negli occhi..."
  },
  AvgDialog_18966_Content_23 = {
    Text = "Non riesco... a respirare..."
  },
  AvgDialog_18966_Content_24 = {Text = "..."},
  AvgDialog_18966_Content_25 = {Text = "..."},
  AvgDialog_18966_Content_26 = {Text = "Ding—!"},
  AvgDialog_18966_Content_27 = {
    Text = "All'improvviso, il rintocco della Chiave d'Argento riecheggia nelle tue orecchie."
  },
  AvgDialog_18966_Content_28 = {
    Text = "<Shake:Waaa...>"
  },
  AvgDialog_18966_Content_29 = {
    Text = "<Shake:Rogers... Male... Male...>"
  },
  AvgDialog_18966_Content_3 = {
    Text = "Che puzza..."
  },
  AvgDialog_18966_Content_30 = {
    Text = "Il bagliore argenteo si intensifica bruscamente, rivelando un nuovo incantesimo che già ricopre il cerchio di sangue."
  },
  AvgDialog_18966_Content_31 = {
    Text = "Illumina l'oscurità dietro la Fessura, rivelando William e il suo ingombrante Osservatore di D-fessure."
  },
  AvgDialog_18966_Content_32 = {
    Text = "William...! Sei stato tu a scrivere questo incantesimo? È così bello..."
  },
  AvgDialog_18966_Content_33 = {
    Text = "William alza brevemente lo sguardo, si accerta che tu sia al sicuro, poi torna a fissare il quadrante davanti a sé."
  },
  AvgDialog_18966_Content_34 = {
    Text = "Sei arrivato giusto in tempo. Quasi pensavo che non ce l'avresti fatta fin qui."
  },
  AvgDialog_18966_Content_35 = {Text = "Squeak!"},
  AvgDialog_18966_Content_36 = {
    Text = "Brown dimena il suo corpo massiccio e emerge dalla cima della testa di William."
  },
  AvgDialog_18966_Content_37 = {
    Text = "Brown! Pensavo di averti perso...!"
  },
  AvgDialog_18966_Content_38 = {
    Text = "La chiusura della Fessura è progredita al 70%. Andarsene ora è estremamente pericoloso. Devo restare qui per stabilizzare le fluttuazioni della Dissoluzione."
  },
  AvgDialog_18966_Content_39 = {
    Text = "%player%, per favore guadagnami ancora un po' di tempo."
  },
  AvgDialog_18966_Content_4 = {
    Text = "Silenzio. Guarda dritto davanti a te."
  },
  AvgDialog_18966_Content_40 = {Text = "Capito!"},
  AvgDialog_18966_Content_41 = {
    Text = "Non eri stato messo fuori combattimento...?"
  },
  AvgDialog_18966_Content_42 = {
    Text = "Mi perdoni, signor Rogers. A volte, l'\"inganno\" è un'abilità essenziale per gli Investigatori."
  },
  AvgDialog_18966_Content_43 = {
    Text = "Grazie a quella donna, sono riuscito a trovare questo luogo."
  },
  AvgDialog_18966_Content_44 = {
    Text = "Hmph, che Investigatore scaltro."
  },
  AvgDialog_18966_Content_45 = {
    Text = "Non temete, mio signore. I nostri soldati non si lasciano sconfiggere facilmente."
  },
  AvgDialog_18966_Content_46 = {
    Text = "Ora che siamo tutti riuniti, cancelliamoli con un solo, glorioso colpo!"
  },
  AvgDialog_18966_Content_5 = {
    Text = "Un'immensa fessura si estende davanti a te, esalando dal suo interno una densa foschia nera."
  },
  AvgDialog_18966_Content_6 = {
    Text = "Attorno alla fessura, su un complesso cerchio magico tracciato col sangue, scorgi una montagna di arti di sculture di cera."
  },
  AvgDialog_18966_Content_7 = {
    Text = "Sono ammassati fittamente, fino a raggiungere il soffitto. Innumerevoli bocche ghignano, formando un mare di ilarità."
  },
  AvgDialog_18966_Content_8 = {
    Text = "<Shake:Hehehe...>"
  },
  AvgDialog_18966_Content_9 = {
    Text = "Che... cos'è questo...?"
  },
  AvgDialog_18967_Content_1 = {
    Text = "Nessun soriano trovato, per quanto cercasse con cura—"
  },
  AvgDialog_18967_Content_10 = {
    Text = "Non possono controllare il proprio fato, non possono aiutare gli altri."
  },
  AvgDialog_18967_Content_11 = {
    Text = "Proprio come me, che ho visto Aigis scomparire davanti ai miei occhi..."
  },
  AvgDialog_18967_Content_12 = {
    Text = "Jenkin tira su col naso all'improvviso mentre parla."
  },
  AvgDialog_18967_Content_13 = {
    Text = "Ugh, ma che sto dicendo.\nNon sono più una persona normale dopo aver frequentato voi, eh."
  },
  AvgDialog_18967_Content_14 = {Text = "Jenkin..."},
  AvgDialog_18967_Content_15 = {
    Text = "Ramona emette un lieve sospiro e accarezza dolcemente la testa di Jenkin."
  },
  AvgDialog_18967_Content_16 = {
    Text = "Non c'è da stupirsi che tu sia stato turbato. Ti stai dando la colpa? Lascia che ti racconti una cosa."
  },
  AvgDialog_18967_Content_17 = {
    Text = "Quando il disastro colpisce, non fa distinzione tra un Custode e un mendicante di strada."
  },
  AvgDialog_18967_Content_18 = {
    Text = "Questa è solo la mia seconda missione con %player%. Ho appena più esperienza di te."
  },
  AvgDialog_18967_Content_19 = {
    Text = "C'è ancora così tanto che potrei imparare da te, <Blue:\"Maestro di Sopravvivenza Urbana\">."
  },
  AvgDialog_18967_Content_2 = {
    Text = "Pianse e pianse... finché anche Charlie non fu più lì—"
  },
  AvgDialog_18967_Content_20 = {Text = "Ramona..."},
  AvgDialog_18967_Content_21 = {
    Text = "Sei pessimo a consolare la gente. Ma grazie lo stesso."
  },
  AvgDialog_18967_Content_3 = {Text = "Mai lì!"},
  AvgDialog_18967_Content_4 = {
    Text = "Le allegre sculture di cera si tengono per mano e avanzano barcollando nei corridoi oscuri del museo delle cere."
  },
  AvgDialog_18967_Content_5 = {
    Text = "Uff... Siamo al sicuro, per ora."
  },
  AvgDialog_18967_Content_6 = {
    Text = "È tutta colpa mia... Ho messo tutti in pericolo."
  },
  AvgDialog_18967_Content_7 = {
    Text = "Non incolparti. Ci sono cose che le persone normali non possono affrontare."
  },
  AvgDialog_18967_Content_8 = {
    Text = "...Ti invidio davvero."
  },
  AvgDialog_18967_Content_9 = {
    Text = "Odio essere normale. Le persone normali sono inutili."
  },
  AvgDialog_18968_Content_1 = {
    Text = "Accidenti, l'ho persa...\nChe posto è questo? Un caos totale."
  },
  AvgDialog_18968_Content_10 = {
    Text = "Niente topi pigri in casa mia!"
  },
  AvgDialog_18968_Content_11 = {
    Text = "Trascurato, il topo dondola il suo Corpo grassoccio, barcollando verso l'angolo dell'ufficio."
  },
  AvgDialog_18968_Content_12 = {
    Text = "Nell'angolo si erge una piccola Scultura di Cera coperta da un panno bianco, in paziente Attesa..."
  },
  AvgDialog_18968_Content_13 = {
    Text = "...in paziente attesa di essere svelate."
  },
  AvgDialog_18968_Content_14 = {
    Text = "Bene, proprio così... Tanto cibo là dentro, tutto delizioso formaggio..."
  },
  AvgDialog_18968_Content_15 = {
    Text = "Basta un piccolo strattone..."
  },
  AvgDialog_18968_Content_16 = {
    Text = "Squeak! Squeak! Squeak!"
  },
  AvgDialog_18968_Content_17 = {Text = "...Brown?"},
  AvgDialog_18968_Content_18 = {
    Text = "Brown si è arrampicato sulla base della Scultura di Cera, le sue zampette che lottano per tirare la Copertura."
  },
  AvgDialog_18968_Content_19 = {
    Text = "No! La seconda regola del Museo delle Cere è—"
  },
  AvgDialog_18968_Content_2 = {
    Text = "Questo sembra essere l'ufficio di Rogers.\nIl tè sulla scrivania è ancora caldo. Qualcuno è stato qui di recente."
  },
  AvgDialog_18968_Content_20 = {
    Text = "Non sollevare le loro coperture."
  },
  AvgDialog_18968_Content_21 = {
    Text = "Almeno qualcuno qui ragiona ancora lucidamente."
  },
  AvgDialog_18968_Content_22 = {
    Text = "Niente rumori forti."
  },
  AvgDialog_18968_Content_23 = {
    Text = "Se queste regole fossero vere, saremmo già morti."
  },
  AvgDialog_18968_Content_24 = {
    Text = "Non ricordo nulla."
  },
  AvgDialog_18968_Content_25 = {
    Text = "Se stavi cercando di farmi arrabbiare, ci sei riuscito. Ben giocato."
  },
  AvgDialog_18968_Content_26 = {
    Text = "<Yellow:Regola 2: Non sollevare le loro coperture.>"
  },
  AvgDialog_18968_Content_27 = {
    Text = "Dobbiamo fermare tutto questo immediatamente, prima che sia troppo tardi!"
  },
  AvgDialog_18968_Content_28 = {
    Text = "Brown, fermati adesso! O... o ti lascio qui!"
  },
  AvgDialog_18968_Content_29 = {
    Text = "Di fronte alla minaccia di Jenkin, il piccolo topo non mostra alcun Terrore."
  },
  AvgDialog_18968_Content_3 = {
    Text = "Brown, che sonnecchiava sulla spalla di Jenkin, emette improvvisamente un Grido sommesso. Apre i suoi Occhi rosso Sangue e scruta i dintorni con inquietudine."
  },
  AvgDialog_18968_Content_30 = {
    Text = "Socchiude gli Occhi, gonfia il petto come un piccolo generale borioso, e poi con destrezza solleva la Copertura."
  },
  AvgDialog_18968_Content_31 = {
    Text = "<RedShake:Buaaah... i miei occhi, i miei occhi...>"
  },
  AvgDialog_18968_Content_32 = {
    Text = "<RedShake:Troppa luce, troppa luce...>"
  },
  AvgDialog_18968_Content_33 = {
    Text = "<Big:Brown, tu-tu-tu—!!>"
  },
  AvgDialog_18968_Content_34 = {
    Text = "Sotto il telo si erge il busto di un uomo adulto."
  },
  AvgDialog_18968_Content_35 = {
    Text = "Le sopracciglia si inarcano, il volto emaciato solcato da rughe profonde, e le labbra serrate."
  },
  AvgDialog_18968_Content_36 = {
    Text = "Quel volto ti lascia un'impressione profonda: il famigerato Scultore di cera dei giornali."
  },
  AvgDialog_18968_Content_37 = {
    Text = "Fissi le orbite vuote della Scultura di Cera, pensando che ci sia qualcosa di diverso — i suoi Occhi sono stati cavati."
  },
  AvgDialog_18968_Content_38 = {
    Text = "Ding—! Ding—!"
  },
  AvgDialog_18968_Content_39 = {
    Text = "La campana suona di nuovo, più urgente e intensa di prima, echeggiando nella Stanza scarsamente illuminata, penetrante come una risata stridula."
  },
  AvgDialog_18968_Content_4 = {Text = "Squeak..."},
  AvgDialog_18968_Content_40 = {
    Text = "Ehm, è il momento dell'annuncio speciale di Pandia!"
  },
  AvgDialog_18968_Content_41 = {
    Text = "Oh cielo, mio piccolo topo sbadato, sei andato a sollevare la Copertura!"
  },
  AvgDialog_18968_Content_42 = {
    Text = "<Red:Con la presente proclamo la seconda regola infranta nel modo più splendido!>"
  },
  AvgDialog_18968_Content_43 = {
    Text = "Brown, Brown non l'ha fatto apposta..."
  },
  AvgDialog_18968_Content_44 = {
    Text = "Hehe, forse vorresti spiegarti con <Blue:loro> quando sarai tutto comodo sottoterra?"
  },
  AvgDialog_18968_Content_45 = {
    Text = "Oh sciocca me, quasi dimenticavo — non capiscono una parola! Oh hohoho!"
  },
  AvgDialog_18968_Content_46 = {
    Text = "La risata vivace della Bambina svanisce gradualmente dalla trasmissione. Cominci a sentirti stordito."
  },
  AvgDialog_18968_Content_47 = {
    Text = "Oh no... La mia testa si sta annebbiando..."
  },
  AvgDialog_18968_Content_48 = {
    Text = "La tua testa si fa sempre più pesante."
  },
  AvgDialog_18968_Content_49 = {
    Text = "In questa notte allucinatoria, sei una falena intrappolata nell'ambra, avvolta nella resina nera di risate e canti, che sprofonda negli abissi più profondi e oscuri."
  },
  AvgDialog_18968_Content_5 = {
    Text = "Hai così tanta fame, topolino..."
  },
  AvgDialog_18968_Content_50 = {
    Text = "<Shake:Hehe. Strangolateli, strangolateli, STRANGOLATELI!>"
  },
  AvgDialog_18968_Content_51 = {
    Text = "<Shake:Soffocali, soffocali...>"
  },
  AvgDialog_18968_Content_52 = {Text = "No, no...!"},
  AvgDialog_18968_Content_53 = {Text = "..."},
  AvgDialog_18968_Content_54 = {
    Text = "Un istante prima di soffocare, qualcuno ti afferra saldamente la Mano."
  },
  AvgDialog_18968_Content_55 = {
    Text = "Tieni duro, %player%. Ce la faremo."
  },
  AvgDialog_18968_Content_56 = {
    Text = "<Shake:Ramona, sei tu quella spaventata. Le tue mani non smettono di tremare...>"
  },
  AvgDialog_18968_Content_57 = {Text = "..."},
  AvgDialog_18968_Content_58 = {
    Text = "Nell'Oscurità, odi una debole risata di Bambina, come se fosse lontana eppure apparentemente vicina."
  },
  AvgDialog_18968_Content_59 = {
    Text = "Anche tu, %player%."
  },
  AvgDialog_18968_Content_6 = {
    Text = "Lo so... stai morendo di fame..."
  },
  AvgDialog_18968_Content_7 = {Text = "Squeak!"},
  AvgDialog_18968_Content_8 = {
    Text = "Aspetta, perché Brown è saltato giù?"
  },
  AvgDialog_18968_Content_9 = {
    Text = "Non farci caso. Ho dormito abbastanza, è ora di muoversi."
  },
  AvgDialog_18969_Content_1 = {
    Text = "Le Sculture di Cera... sono vive?"
  },
  AvgDialog_18969_Content_2 = {
    Text = "Sono vive, nel momento in cui infrangi la regola..."
  },
  AvgDialog_18969_Content_3 = {
    Text = "Ora godetevi questa magnifica notte fino in fondo, miei piccoli!"
  },
  AvgDialog_18969_Content_4 = {
    Text = "<Shake:Hehehehehe...>"
  },
  AvgDialog_18969_Content_5 = {
    Text = "No... Sono troppi!"
  },
  AvgDialog_18969_Content_6 = {
    Text = "Ehi, Ramona! Sei intelligente, e hai un piano, vero?"
  },
  AvgDialog_18969_Content_7 = {
    Text = "Date le circostanze attuali, le opzioni si stanno esaurendo—"
  },
  AvgDialog_18969_Content_8 = {
    Text = "<Big:Corsa!>"
  },
  AvgDialog_18970_Content_1 = {
    Text = "Che faccio? Jenkin sarà scontento se fallisco... squeak..."
  },
  AvgDialog_18970_Content_2 = {
    Text = "Oh, c'è un'altra uscita qui..."
  },
  AvgDialog_18970_Content_3 = {
    Text = "Dev'essere questo il posto, sicuramente! Squeak squeak!"
  },
  AvgDialog_18971_Content_1 = {
    Text = [[
12:10, Museo delle Cere di Rogers
Seminterrato]]
  },
  AvgDialog_18971_Content_10 = {
    Text = "Scansione completa: diametro 5,65 metri, profondità 19,9... una <Yellow:Fenditura di Classe C>."
  },
  AvgDialog_18971_Content_11 = {
    Text = "Il diametro è troppo piccolo, non c'è da stupirsi che non sia stata rilevata prima. Il passo successivo è confermare il raggio d'azione attivo..."
  },
  AvgDialog_18971_Content_12 = {
    Text = "Brown vaga nei pressi di William, poi nota una cartellina che spunta da una valigia."
  },
  AvgDialog_18971_Content_13 = {Text = "..."},
  AvgDialog_18971_Content_14 = {
    Text = "Squeak—<Big:Squeak Squeak!!>"
  },
  AvgDialog_18971_Content_15 = {
    Text = "Lo afferra e scappa via di corsa."
  },
  AvgDialog_18971_Content_16 = {
    Text = "...<Big:Ehi!!>"
  },
  AvgDialog_18971_Content_17 = {
    Text = "Tap. Tap. Tap."
  },
  AvgDialog_18971_Content_18 = {
    Text = "Piccole scarpe battono sul pavimento. Qualcuno si avvicina con passi tranquilli."
  },
  AvgDialog_18971_Content_19 = {
    Text = "Non devo farmi scoprire... Prima di tutto, trovare un posto dove nascondermi."
  },
  AvgDialog_18971_Content_2 = {
    Text = "Squeak... squeak?"
  },
  AvgDialog_18971_Content_20 = {
    Text = "Vediamo un po', chi disturba la merenda di George?"
  },
  AvgDialog_18971_Content_21 = {
    Text = "Squeak—!!"
  },
  AvgDialog_18971_Content_22 = {
    Text = "Oh, solo un topolino. George oggi si sente generoso, quindi..."
  },
  AvgDialog_18971_Content_23 = {
    Text = "George lancia una massa sanguinolenta davanti a Brown."
  },
  AvgDialog_18971_Content_24 = {
    Text = "Forza, mangia."
  },
  AvgDialog_18971_Content_25 = {Text = "—Squeak?"},
  AvgDialog_18971_Content_26 = {
    Text = "Devi essere affamato, sciocchino."
  },
  AvgDialog_18971_Content_27 = {
    Text = "Squeak! Squeak squeak...?"
  },
  AvgDialog_18971_Content_28 = {
    Text = "Di' a George che hai fame."
  },
  AvgDialog_18971_Content_29 = {
    Text = "La voce misteriosa si propaga come onde concentriche, riempiendo l'aria di echi rumorosi."
  },
  AvgDialog_18971_Content_3 = {
    Text = "...Un topo?"
  },
  AvgDialog_18971_Content_30 = {
    Text = "Hai fame... Hai fame..."
  },
  AvgDialog_18971_Content_31 = {
    Text = "Fame@1 Fame faME FAME @4AME..."
  },
  AvgDialog_18971_Content_32 = {
    Text = "Squeak...<Big:Squeak!>"
  },
  AvgDialog_18971_Content_33 = {
    Text = "Gli occhi del topo brillano di rosso. Mostra i denti e divora la carne in decomposizione con bramosia."
  },
  AvgDialog_18971_Content_34 = {
    Text = "Povero stupido topolino... Il mio povero stupido topolino..."
  },
  AvgDialog_18971_Content_35 = {
    Text = "Nel frattempo, nello studio..."
  },
  AvgDialog_18971_Content_4 = {
    Text = "Glu, glu..."
  },
  AvgDialog_18971_Content_5 = {
    Text = "Il faint suono di una bramosia vorace riecheggia nel seminterrato buio pesto."
  },
  AvgDialog_18971_Content_6 = {Text = "...Squeak?"},
  AvgDialog_18971_Content_7 = {
    Text = "Shh... Non avvicinarti. Qui è pericoloso."
  },
  AvgDialog_18971_Content_8 = {
    Text = "Non svegliare \"loro\"."
  },
  AvgDialog_18971_Content_9 = {
    Text = "William tiene la testa bassa, concentrato sui numeri fluttuanti del suo strumento."
  },
  AvgDialog_18972_Content_10 = {
    Text = "Come dovrebbe essere. I miei voti in dissezione al Mythag negli ultimi tre anni? A+, A+, A++."
  },
  AvgDialog_18972_Content_11 = {
    Text = "Ci sono residui di tessuto umano e Sangue nel cranio... proprio come dicono le voci, <Red:le figure di cera sono davvero fatte con persone vive.>"
  },
  AvgDialog_18972_Content_12 = {
    Text = "Lo sapevo... Artista, elemosiniere, ma figuriamoci. Sapevo che non tramava nulla di buono."
  },
  AvgDialog_18972_Content_13 = {
    Text = "Ti guardi intorno. Le sculture di cera dai dolci sorrisi riempiono la sala espositiva, come i Fanciulli, gli adulti e gli animali più felici del mondo."
  },
  AvgDialog_18972_Content_14 = {
    Text = "Chi avrebbe mai pensato che questa felicità fosse costruita con vera carne umana?"
  },
  AvgDialog_18972_Content_15 = {
    Text = "Se davvero ha preso mia sorella..."
  },
  AvgDialog_18972_Content_16 = {
    Text = "Ho già perso Aigis... Non posso perdere anche mia sorella..."
  },
  AvgDialog_18972_Content_17 = {
    Text = "Clic. Clic. Clic."
  },
  AvgDialog_18972_Content_18 = {
    Text = "Con un debole gemito, un paio di mani emerge dall'Oscurità, accarezzando dolcemente la guancia di Jenkin."
  },
  AvgDialog_18972_Content_19 = {
    Text = "Jenkin... <Big:Attenta! C'è qualcosa dietro di te!>"
  },
  AvgDialog_18972_Content_2 = {
    Text = "Pandia... quella bambina è decisamente strana."
  },
  AvgDialog_18972_Content_20 = {
    Text = "<BigBold:?!>"
  },
  AvgDialog_18972_Content_21 = {Text = "Waaah..."},
  AvgDialog_18972_Content_22 = {
    Text = "Una figura oscura si contorce lentamente dentro la Scultura di Cera, come un neonato impaziente di nascere, stirando la cera morbida fino a renderla una Pellicola quasi trasparente."
  },
  AvgDialog_18972_Content_23 = {
    Text = "Qualcosa sta emergendo da quella scultura di cera..."
  },
  AvgDialog_18972_Content_24 = {Text = "Una testa."},
  AvgDialog_18972_Content_25 = {
    Text = "Una testa di Donna. Striscia fuori dalla Scultura di Cera, i lunghi capelli ricoperti di cera oleosa."
  },
  AvgDialog_18972_Content_26 = {
    Text = "Solleva il volto, rivelando occhi cavi e anneriti."
  },
  AvgDialog_18972_Content_27 = {
    Text = "<Shake:Aiuto...>"
  },
  AvgDialog_18972_Content_28 = {
    Text = "<Shake:Salvami...>"
  },
  AvgDialog_18972_Content_3 = {
    Text = "Quando ho toccato quella... cosa nel suo stomaco, sembrava fin troppo reale!"
  },
  AvgDialog_18972_Content_4 = {
    Text = "Ma era chiaramente di cera..."
  },
  AvgDialog_18972_Content_5 = {
    Text = [[
Basta chiacchiere, mettiamola alla prova.
Ho afferrato qualcosa quando ci siamo azzuffati con quelle sculture di cera.]]
  },
  AvgDialog_18972_Content_6 = {
    Text = "H-Hai preso QUESTO?!"
  },
  AvgDialog_18972_Content_7 = {
    Text = "\"Ragazzina Affronta il Caos di PETTO\"... La nostra reporter Hannah adorerà quel TITOLO da prima pagina."
  },
  AvgDialog_18972_Content_8 = {
    Text = "Ramona non risponde, le dita che esplorano con destrezza la cavità cranica con misurata precisione."
  },
  AvgDialog_18972_Content_9 = {
    Text = "Sembri... troppo brava in questo. Quasi come il vecchio Johnny, il macellaio della porta accanto."
  },
  AvgDialog_18973_Content_1 = {
    Text = "Ugh! Aaaaah—"
  },
  AvgDialog_18973_Content_10 = {Text = "Addio."},
  AvgDialog_18973_Content_11 = {
    Text = "Ferma, non scappare!!"
  },
  AvgDialog_18973_Content_2 = {
    Text = "24 respira affannosamente e spinge di nuovo la testa."
  },
  AvgDialog_18973_Content_3 = {
    Text = "Il collo lussato viene riallineato, e l'Espressione di 24 muta gradualmente da feroce a gentile."
  },
  AvgDialog_18973_Content_4 = {Text = "..."},
  AvgDialog_18973_Content_5 = {
    Text = "Tu... sei davvero diverso. Forse..."
  },
  AvgDialog_18973_Content_6 = {
    Text = "Un sorriso fugace appare sul volto di 24. È la prima volta che la vedi sorridere."
  },
  AvgDialog_18973_Content_7 = {
    Text = "Si ritira lentamente, il suo volto pallido e malinconico in gran parte avvolto nell'Ombra."
  },
  AvgDialog_18973_Content_8 = {
    Text = "Scusate, %player%. È stato bello stare con voi."
  },
  AvgDialog_18973_Content_9 = {
    Text = "Ma questo è... questo è tutto."
  },
  AvgDialog_18974_Content_1 = {
    Text = "George ha così fame..."
  },
  AvgDialog_18975_Content_1 = {
    Text = "*Coff, coff...*"
  },
  AvgDialog_18975_Content_2 = {Text = "?!"},
  AvgDialog_18975_Content_3 = {
    Text = "Sento odore di umano più avanti, squeak!"
  },
  AvgDialog_18975_Content_4 = {
    Text = "Ma qui è bloccato. Bisogna prima trovare la chiave, squeak!"
  },
  AvgDialog_18976_Content_1 = {Text = "Hmm...!!"},
  AvgDialog_18976_Content_10 = {
    Text = "Ramona sfodera uno stocco e lo appoggia delicatamente sulla spalla della 24."
  },
  AvgDialog_18976_Content_11 = {
    Text = "Signorina 24, la vostra reazione mi dice tutto. Guidateci alla Scultura di Cera adesso, o morirete per Mano mia."
  },
  AvgDialog_18976_Content_12 = {
    Text = "Fai la tua scelta."
  },
  AvgDialog_18976_Content_13 = {Text = "..."},
  AvgDialog_18976_Content_14 = {
    Text = "Questa Scultura di Cera... \"Primavera\", è importante per voi?"
  },
  AvgDialog_18976_Content_15 = {
    Text = "Sto cercando mia sorella, Mason."
  },
  AvgDialog_18976_Content_16 = {
    Text = "Sembra assurdo, ma non riesco a ricordare che aspetto abbia..."
  },
  AvgDialog_18976_Content_17 = {
    Text = "Potrebbe essere stata trasformata in una figura di cera e nascosta in un set chiamato... La Primadonna del Fondo."
  },
  AvgDialog_18976_Content_18 = {
    Text = "<Small:È 《La Primavera di Botticelli》... in realtà, lascia perdere.>"
  },
  AvgDialog_18976_Content_19 = {
    Text = "Non capisco... Hai detto che Mason è tua sorella, ma non riesci a ricordare che aspetto abbia?"
  },
  AvgDialog_18976_Content_2 = {
    Text = "Cosa... sta succedendo..."
  },
  AvgDialog_18976_Content_20 = {
    Text = "Ah! Scusa, non volevo metterti in discussione..."
  },
  AvgDialog_18976_Content_21 = {
    Text = "Questo posto è strano. Cancella le memorie."
  },
  AvgDialog_18976_Content_22 = {
    Text = "Potremmo finire confusi come Nonna Vanessa, tra poco."
  },
  AvgDialog_18976_Content_23 = {
    Text = "Nonna Vanessa?"
  },
  AvgDialog_18976_Content_24 = {
    Text = "La mia vecchia padrona di casa. A parte il giorno dell'affitto, non riusciva a capire nient'altro."
  },
  AvgDialog_18976_Content_25 = {
    Text = "<SmallShake:Accidenti! Perché mi ricordo solo le cose brutte...>"
  },
  AvgDialog_18976_Content_26 = {Text = "Capisco."},
  AvgDialog_18976_Content_27 = {
    Text = "Quindi, non finirai come me, senza ricordare più nulla?"
  },
  AvgDialog_18976_Content_28 = {
    Text = "Forse, chi lo sa?"
  },
  AvgDialog_18976_Content_29 = {
    Text = "Ma non m'importa. Riconoscerò mia sorella, basta che venga da me."
  },
  AvgDialog_18976_Content_3 = {
    Text = "La 24 siede a terra, stordita, e si tocca la testa."
  },
  AvgDialog_18976_Content_30 = {
    Text = "Ehm... Dimentica quello che ho detto."
  },
  AvgDialog_18976_Content_31 = {
    Text = "Sei solo un poveraccio che non ricorda nulla."
  },
  AvgDialog_18976_Content_32 = {
    Text = "Già... Non so fare niente, e non ricordo niente."
  },
  AvgDialog_18976_Content_33 = {
    Text = "Le lacrime di 24 sgorgano ancora una volta."
  },
  AvgDialog_18976_Content_34 = {
    Text = "Sono così inutile..."
  },
  AvgDialog_18976_Content_35 = {Text = "..."},
  AvgDialog_18976_Content_36 = {
    Text = "Volevo fare di più, ma... ma sono così inutile. Queste faccende sono tutto ciò che riesco a gestire..."
  },
  AvgDialog_18976_Content_37 = {
    Text = "Prima Aigis, ora tu..."
  },
  AvgDialog_18976_Content_38 = {
    Text = "<Big:Niente lacrime!>"
  },
  AvgDialog_18976_Content_39 = {
    Text = "Non sopporto i piagnucoloni. <Big:Mi fanno arrabbiare!>"
  },
  AvgDialog_18976_Content_4 = {
    Text = "<Shake:N-Non uccidetemi... non volevo, non volevo...>"
  },
  AvgDialog_18976_Content_40 = {
    Text = "Va bene, va bene... Non piangerò... Mi dispiace..."
  },
  AvgDialog_18976_Content_41 = {
    Text = "Asciugati la faccia, capito?"
  },
  AvgDialog_18976_Content_42 = {
    Text = "<Yellow:Niente lacrime, e niente scuse.>"
  },
  AvgDialog_18976_Content_43 = {
    Text = "Jenkin sta in piedi con le mani sui fianchi, sollevando il suo piccolo mento aguzzo."
  },
  AvgDialog_18976_Content_44 = {
    Text = "E chi ha detto che sei inutile?"
  },
  AvgDialog_18976_Content_45 = {
    Text = "Ti renderai utile portandoci alla Scultura di Cera, capito?"
  },
  AvgDialog_18976_Content_46 = {
    Text = "Va bene... va bene..."
  },
  AvgDialog_18976_Content_47 = {
    Text = "Vedendo 24 così obbediente, Jenkin annuisce con soddisfazione."
  },
  AvgDialog_18976_Content_48 = {
    Text = "Abbiamo sprecato abbastanza tempo. Andiamo!"
  },
  AvgDialog_18976_Content_49 = {
    Text = "Quel tale William probabilmente sta aspettando che lo salviamo."
  },
  AvgDialog_18976_Content_5 = {
    Text = "Siete intrappolati qui, vero... proprio come Tutti gli altri... <Italic:Proprio come me.>"
  },
  AvgDialog_18976_Content_50 = {
    Text = "No, no! La Scultura di Cera è nello <Blue:Studio>, non laggiù..."
  },
  AvgDialog_18976_Content_51 = {Text = "..."},
  AvgDialog_18976_Content_52 = {
    Text = "Hai qualcosa da dire?"
  },
  AvgDialog_18976_Content_53 = {
    Text = "Sto solo cercando di capire... Perché è andata su tutte le furie, per poi calmarsi all'improvviso?"
  },
  AvgDialog_18976_Content_54 = {
    Text = "Semplice. È solo una bambina che piange un'amica perduta, cercando di aiutare sia 24 che sé stessa."
  },
  AvgDialog_18976_Content_55 = {
    Text = "A modo suo... in maniera unica."
  },
  AvgDialog_18976_Content_6 = {
    Text = "Conosco bene questo Museo delle Cere. Posso guidarvi fuori! <Shake:Se... se riesco a ricordare...>"
  },
  AvgDialog_18976_Content_7 = {
    Text = "L'accordo è questo: trovate la \"Primavera\" per noi, e vi guadagnerete la libertà."
  },
  AvgDialog_18976_Content_8 = {
    Text = "Sentendo \"Primavera\", le Pupille della 24 si contraggono improvvisamente e le sopracciglia si aggrottano."
  },
  AvgDialog_18976_Content_9 = {
    Text = "Scusa, io..."
  },
  AvgDialog_18977_Content_1 = {
    Text = "È colpa vostra... di tutti voi..."
  },
  AvgDialog_18978_Content_1 = {
    Text = "Maestro Rogers..."
  },
  AvgDialog_18979_Content_1 = {
    Text = "Non lasciare George, non lasciare noi...!"
  },
  AvgDialog_18980_Content_1 = {
    Text = "Il Museo delle Cere, finalmente."
  },
  AvgDialog_18980_Content_10 = {
    Text = "\"Museo delle Cere di Rogers\"... riesci finalmente a decifrare le lettere consunte sull'insegna."
  },
  AvgDialog_18980_Content_11 = {
    Text = "Jenkin, puoi darmi una descrizione generale dell'aspetto della signorina Mason?"
  },
  AvgDialog_18980_Content_12 = {
    Text = "Mia sorella è splendida! Capelli lunghi, pelle perfetta..."
  },
  AvgDialog_18980_Content_13 = {
    Text = "Aspetta, no. I suoi capelli sono corti e la sua pelle è..."
  },
  AvgDialog_18980_Content_14 = {Text = "..."},
  AvgDialog_18980_Content_15 = {
    Text = "Dunque, sua sorella è una persona reale nel mondo fisico, o soltanto una figura errante nelle sue fantasie spirituali?"
  },
  AvgDialog_18980_Content_16 = {Text = "Ehm..."},
  AvgDialog_18980_Content_17 = {
    Text = "Credo che stia dimenticando che aspetto ha mia sorella... Non solo il suo volto, persino la sua Voce..."
  },
  AvgDialog_18980_Content_18 = {
    Text = "Ho visto la foto della signorina Mason. Lei..."
  },
  AvgDialog_18980_Content_19 = {Text = "Lei..."},
  AvgDialog_18980_Content_2 = {
    Text = [[
Conferma degli obiettivi della missione.
<Yellow:Missione 1: Recarsi al Museo delle Cere di Rogers per trovare la signorina Mason e l'Investigatore William.>]]
  },
  AvgDialog_18980_Content_20 = {
    Text = "Ramona aggrotta le sopracciglia, sprofondando in un inquietante Silenzio insieme a Jenkin."
  },
  AvgDialog_18980_Content_21 = {
    Text = "Hmm... forse dovremmo esaminare insieme le foto del giornale?"
  },
  AvgDialog_18980_Content_22 = {
    Text = "Srotoli il giornale di Jenkin, solo per scoprire che l'inchiostro sembra vivo, e si dissolve gradualmente—"
  },
  AvgDialog_18980_Content_23 = {
    Text = "Finché non riesci più a decifrare l'articolo su \"Primavera\"."
  },
  AvgDialog_18980_Content_24 = {
    Text = "Le filigrane danneggiate e le Macchie d'Inchiostro sembrano determinate a cancellare del tutto l'esistenza di Mason."
  },
  AvgDialog_18980_Content_25 = {Text = "..."},
  AvgDialog_18980_Content_26 = {
    Text = "Che stregoneria è questa? Ho letto questo giornale migliaia di volte."
  },
  AvgDialog_18980_Content_27 = {
    Text = "Ma ora... non riesco a ricordare una sola parola."
  },
  AvgDialog_18980_Content_28 = {
    Text = "Aspetta, non ricordi proprio nulla?"
  },
  AvgDialog_18980_Content_29 = {
    Text = "\"L'eccezionale difensore del Cubismo, la reincarnazione dell'anima di Botticelli, si nasconde ora in un Museo delle Cere all'angolo di Via Southwark...\""
  },
  AvgDialog_18980_Content_3 = {
    Text = "<Yellow:Missione 2: Indagare sul collegamento tra Rogers e il \"Caso delle Sparizioni dall'Ospizio dei Poveri.\">"
  },
  AvgDialog_18980_Content_30 = {
    Text = "Vedi? Riesco persino a citare quell'articolo parola per parola."
  },
  AvgDialog_18980_Content_31 = {
    Text = "Il giornale è stato Dissolto. Probabilmente un evento di <Yellow:amnesia di massa>, eppure..."
  },
  AvgDialog_18980_Content_32 = {
    Text = "Ramona e Jenkin si voltano verso di te nello stesso istante."
  },
  AvgDialog_18980_Content_33 = {
    Text = "A quanto pare non funziona su qualcuno in particolare."
  },
  AvgDialog_18980_Content_34 = {Text = "..."},
  AvgDialog_18980_Content_35 = {
    Text = "Che tu ci creda o no, qualcosa non torna affatto..."
  },
  AvgDialog_18980_Content_36 = {
    Text = "Sembra che, senza che nessuno se ne accorga, il passato venga alterato, e la storia devii dal suo corso prestabilito."
  },
  AvgDialog_18980_Content_37 = {
    Text = "E tu sei l'unico testimone di questi cambiamenti."
  },
  AvgDialog_18980_Content_38 = {
    Text = "Scricchiolio—"
  },
  AvgDialog_18980_Content_39 = {
    Text = "Le porte serrate del Museo delle Cere si spalancano all'improvviso, come a dare il benvenuto a ospiti inattesi."
  },
  AvgDialog_18980_Content_4 = {
    Text = "Per favore, conferma."
  },
  AvgDialog_18980_Content_40 = {
    Text = "La porta... si è appena aperta da sola?"
  },
  AvgDialog_18980_Content_41 = {
    Text = "...Sembra che il nostro piano di infiltrazione necessiti di una rivalutazione."
  },
  AvgDialog_18980_Content_42 = {
    Text = [[
Andiamo, %player%.
<Yellow:Troviamo Mason e William prima che i nostri ricordi svaniscano del tutto.>]]
  },
  AvgDialog_18980_Content_5 = {
    Text = "Obiettivo della missione confermato. Inizio dell'Indagine."
  },
  AvgDialog_18980_Content_6 = {
    Text = "Confermato. Le comunicazioni restano attive; il processo d'indagine verrà registrato.\nLivello di rischio: Alto. Si prega di procedere con cautela."
  },
  AvgDialog_18980_Content_7 = {
    Text = "Che la Chiave d'Argento Illumini il Cammino."
  },
  AvgDialog_18980_Content_8 = {
    Text = "Alzi lo sguardo e osservi la scena desolata della strada."
  },
  AvgDialog_18980_Content_9 = {
    Text = "Oltre la Nebbia, un lampione rosso spettrale emette un Tremolio, illuminando fiocamente le insegne dei Negozi vicini."
  },
  AvgDialog_18981_Content_1 = {Text = "Squeak?"},
  AvgDialog_18981_Content_2 = {
    Text = "Il percorso è così complicato... Squeak..."
  },
  AvgDialog_18981_Content_3 = {
    Text = "Voglio tornare a casa e mangiare formaggio, squeak."
  },
  AvgDialog_18982_Content_1 = {Text = "Ugh!"},
  AvgDialog_18982_Content_10 = {
    Text = "Poi concentri il tuo Potere spirituale, cercando di risvegliare Ramona addormentata."
  },
  AvgDialog_18982_Content_11 = {
    Text = "Ramona, torna in te!"
  },
  AvgDialog_18982_Content_12 = {
    Text = "Gatto soriano, gatto soriano... g-gatto..."
  },
  AvgDialog_18982_Content_13 = {
    Text = "Afferri Ramona per le spalle e la scuoti con forza. Ramona sbatte le palpebre, i suoi occhi si schiariscono gradualmente."
  },
  AvgDialog_18982_Content_14 = {
    Text = "Hmph. Perché poi mi sto disturbando con queste sciocchezze..."
  },
  AvgDialog_18982_Content_15 = {
    Text = "Grazie al cielo, finalmente ti sei svegliata!"
  },
  AvgDialog_18982_Content_16 = {
    Text = "Sono successe molte cose mentre eri priva di sensi. A dire il vero, 24—"
  },
  AvgDialog_18982_Content_17 = {
    Text = "Non riesco a muovermi e a malapena resto cosciente, ma posso ancora sentire tutto quello che dite."
  },
  AvgDialog_18982_Content_18 = {
    Text = "Vogliamo ripresentarci, signorina Mason?"
  },
  AvgDialog_18982_Content_19 = {Text = "..."},
  AvgDialog_18982_Content_2 = {
    Text = "La ferita brucia, fa così male! Come puoi essere così crudele con me!"
  },
  AvgDialog_18982_Content_20 = {
    Text = "Scusate, volevo portarvi tutti fuori di qui..."
  },
  AvgDialog_18982_Content_21 = {
    Text = "<Small:Prima volta che vedo un Risvegliato creato artificialmente. Devo consultare la Signorina Bambola...>"
  },
  AvgDialog_18982_Content_22 = {
    Text = "Tsk tsk, vi sembra davvero il momento per le Chiacchiere?"
  },
  AvgDialog_18982_Content_23 = {
    Text = "Non ti ho proprio schiacciata del tutto, ma qualcuno ha cominciato a perdere..."
  },
  AvgDialog_18982_Content_24 = {
    Text = "Segui lo Sguardo di Pandia verso il basso."
  },
  AvgDialog_18982_Content_25 = {
    Text = "Sangue cremisi gocciola lentamente dal tuo braccio a terra."
  },
  AvgDialog_18982_Content_26 = {
    Text = "Una goccia, due gocce, tre gocce..."
  },
  AvgDialog_18982_Content_27 = {
    Text = "<RedShake:Sangue, così tanto Sangue...>"
  },
  AvgDialog_18982_Content_28 = {
    Text = "Svegliati... Presto, svegliati..."
  },
  AvgDialog_18982_Content_29 = {
    Text = "Dannazione, ho perso la concentrazione durante lo scontro e..."
  },
  AvgDialog_18982_Content_3 = {
    Text = "Jenkin! Stai bene?"
  },
  AvgDialog_18982_Content_30 = {
    Text = "<Yellow:Regola 1 del Museo delle Cere: Non toccare le figure di cera.>"
  },
  AvgDialog_18982_Content_31 = {
    Text = "<Yellow:Regola 2 del Museo delle Cere: Non sollevare le loro coperture.>"
  },
  AvgDialog_18982_Content_32 = {
    Text = "Per quanto riguarda la Regola 3 del Museo delle Cere..."
  },
  AvgDialog_18982_Content_33 = {
    Text = "Nessun Sangue dovrà essere versato in queste sale."
  },
  AvgDialog_18982_Content_34 = {
    Text = "Bingo! Esatto!"
  },
  AvgDialog_18982_Content_35 = {
    Text = "Niente rumori forti."
  },
  AvgDialog_18982_Content_36 = {
    Text = "Che sciocca che sei!"
  },
  AvgDialog_18982_Content_37 = {
    Text = "Se tali regole avessero avuto peso, saresti perito da tempo!"
  },
  AvgDialog_18982_Content_38 = {
    Text = "Non ricordo nulla."
  },
  AvgDialog_18982_Content_39 = {
    Text = "Devo fare un Aggiornamento della tua Memoria?"
  },
  AvgDialog_18982_Content_4 = {
    Text = "24 si precipita da Jenkin e le toglie le Catene."
  },
  AvgDialog_18982_Content_40 = {
    Text = "Cara stupida creatura, permettimi di Illuminarti."
  },
  AvgDialog_18982_Content_41 = {
    Text = "<Red:Regola 3: Nessun sangue sarà versato in queste sale.>"
  },
  AvgDialog_18982_Content_42 = {
    Text = "Queste regole formavano il nostro <Yellow:Patto>. Ora, così... tutte infrante."
  },
  AvgDialog_18982_Content_43 = {
    Text = "Ebbene, Ospiti che infrangete le regole..."
  },
  AvgDialog_18982_Content_44 = {
    Text = "<Red:Gustatevi questa notte squisita.>"
  },
  AvgDialog_18982_Content_45 = {
    Text = "Ding—! Ding—!"
  },
  AvgDialog_18982_Content_46 = {
    Text = "Tutti i pendoli nella sala cominciano a risuonare con entusiasmo, fondendo vari rintocchi in un mare di suono."
  },
  AvgDialog_18982_Content_47 = {
    Text = "Quando i tabù vengono infranti e le regole calpestate, il rintocco del Giudizio spezza il Silenzio, emettendo le sue minacce più acute."
  },
  AvgDialog_18982_Content_48 = {Text = "Zing—!!"},
  AvgDialog_18982_Content_49 = {
    Text = "Un ronzio improvviso e penetrante proviene dal basso, accompagnato dalle grida dei Fanciulli, che riecheggiano per tutto il Museo delle Cere."
  },
  AvgDialog_18982_Content_5 = {
    Text = "Solleva Jenkin, proprio come ha fatto innumerevoli volte da quando erano bambini."
  },
  AvgDialog_18982_Content_50 = {
    Text = "BOOOMMM—!!"
  },
  AvgDialog_18982_Content_51 = {
    Text = "È come se un enorme vortice si aprisse sotto i tuoi piedi, bramoso di divorare tutto ciò che incontra sul suo cammino."
  },
  AvgDialog_18982_Content_52 = {Text = "Aaaaah—"},
  AvgDialog_18982_Content_6 = {Text = "Sorella..."},
  AvgDialog_18982_Content_7 = {
    Text = "Ora sto meglio. Vai ad aiutare %player%."
  },
  AvgDialog_18982_Content_8 = {
    Text = "Non preoccuparti per me, riesco a uscire da sola."
  },
  AvgDialog_18982_Content_9 = {
    Text = "La Chiave d'Argento attivata ti infonde nuovo potere. Muovi il corpo, liberandoti finalmente dalle restrizioni."
  },
  AvgDialog_18983_Content_1 = {
    Text = "Legno di Cedro"
  },
  AvgDialog_18983_Content_10 = {
    Text = "Ehi, tipo dell'acqua di colonia, mi stai ascoltando—"
  },
  AvgDialog_18983_Content_11 = {
    Text = "Cercate di tenere le voci basse, ma non riuscite più a sopprimere l'ansia e l'urgenza."
  },
  AvgDialog_18983_Content_12 = {
    Text = "Le grida si rincorrono l'una dopo l'altra, e presto, una risposta soffocata emerge dalle profondità."
  },
  AvgDialog_18983_Content_13 = {
    Text = "...Che chiasso."
  },
  AvgDialog_18983_Content_14 = {
    Text = "Cough... Cough..."
  },
  AvgDialog_18983_Content_15 = {
    Text = "Grazie al cielo, William! Temevo che..."
  },
  AvgDialog_18983_Content_16 = {
    Text = "Sto bene, solo qualche graffio e livido. Ma il detective che è con me..."
  },
  AvgDialog_18983_Content_17 = {
    Text = "Sognare a occhi aperti non è una buona abitudine, Investigatore."
  },
  AvgDialog_18983_Content_18 = {
    Text = "Non mi aspettavo che <Blue:quella donna> avesse rapporti con l'Associazione degli Scultori. Non sono stata abbastanza cauta."
  },
  AvgDialog_18983_Content_19 = {
    Text = "A proposito, avete appena visto una piccola scultura di cera? Riccioli dorati, vestita con un abito nero..."
  },
  AvgDialog_18983_Content_2 = {
    Text = [[
12:40, Museo delle Cere di Rogers
Studio]]
  },
  AvgDialog_18983_Content_20 = {
    Text = "Salite qui a guardare! Un mucchio di figure di cera! Quello stile? Ne trovo dieci così seduta stante."
  },
  AvgDialog_18983_Content_21 = {
    Text = "È semplicemente travolgente!"
  },
  AvgDialog_18983_Content_22 = {
    Text = "...Non è una scultura di cera ordinaria. A giudicare dalle vostre reazioni, probabilmente non l'avete vista."
  },
  AvgDialog_18983_Content_23 = {
    Text = "Questo non è un buon posto per parlare. Datemi dieci minuti."
  },
  AvgDialog_18983_Content_24 = {
    Text = "Forzeremo quella botola e scenderemo da voi."
  },
  AvgDialog_18983_Content_3 = {
    Text = "Strano, non doveva essere il seminterrato a ospitare i mostri?"
  },
  AvgDialog_18983_Content_4 = {
    Text = "Come ha fatto Brown a trovare ciò che la signorina Mason aveva nascosto?"
  },
  AvgDialog_18983_Content_5 = {
    Text = "Ramona prende il foglio, lo sfoglia, poi se lo avvicina al naso."
  },
  AvgDialog_18983_Content_6 = {
    Text = "Un tenue profumo di colonia... È la fragranza inconfondibile di William."
  },
  AvgDialog_18983_Content_7 = {Text = "William?!"},
  AvgDialog_18983_Content_8 = {
    Text = "Ti accovacci e allunghi il collo verso la botola che conduce alla cantina."
  },
  AvgDialog_18983_Content_9 = {
    Text = "William, sei là sotto?"
  },
  AvgDialog_18984_Content_1 = {
    Text = "Dovrei essere... la più perfetta..."
  },
  AvgDialog_18984_Content_2 = {Text = "L'unica..."},
  AvgDialog_18984_Content_3 = {Text = "Perché..."},
  AvgDialog_18985_Content_1 = {
    Text = "Ugh! Sono... tornato?"
  },
  AvgDialog_18985_Content_10 = {
    Text = "L'arte che simboleggia l'eternità si scioglie lentamente, rivelando il suo vero volto."
  },
  AvgDialog_18985_Content_11 = {
    Text = "La dama, che un tempo sorrideva con dolcezza, ora rivela un volto sinistro mentre piange il figlio perduto."
  },
  AvgDialog_18985_Content_12 = {
    Text = "Il gentiluomo affascinante sussulta senza sosta, ma le sue orbite vuote non riescono più a versare una sola lacrima."
  },
  AvgDialog_18985_Content_13 = {
    Text = "Il bambino innocente fissa il braccio mancante, emettendo un grido confuso."
  },
  AvgDialog_18985_Content_14 = {
    Text = "<Shake:Aaah, la mia mano...>"
  },
  AvgDialog_18985_Content_15 = {
    Text = "<Shake:Ricordo, ricordo tutto...>"
  },
  AvgDialog_18985_Content_16 = {
    Text = "No, no... le mie preziose sculture..."
  },
  AvgDialog_18985_Content_17 = {
    Text = "Quando la bellezza dell'arte si spoglia del suo velo delicato, la cruda realtà giunge puntuale."
  },
  AvgDialog_18985_Content_18 = {
    Text = "Le Sculture di Cera fluttuano a mezz'aria, piangendo. Tutte volgono il capo per fissare con odio l'artefice di tutto questo."
  },
  AvgDialog_18985_Content_19 = {
    Text = "N-non guardateci! Andate a combattere quei mocciosi di Mythag!"
  },
  AvgDialog_18985_Content_2 = {
    Text = "Nell'istante in cui apri gli occhi, le rune d'argento sopra la frattura sembrano prendere vita, fluttuando e ruotando rapidamente..."
  },
  AvgDialog_18985_Content_20 = {
    Text = "Continuate a guardare e George vi caverà gli occhi—"
  },
  AvgDialog_18985_Content_21 = {
    Text = "I capelli e i vestiti di George si sollevano improvvisamente, leggeri, prima che possa finire di parlare."
  },
  AvgDialog_18985_Content_22 = {
    Text = "Eh... Anch'io... Perché...?"
  },
  AvgDialog_18985_Content_23 = {
    Text = "George si libera dall'Abbraccio di Rogers e vola verso il centro della frattura, accompagnato dalle Sculture di Cera fluttuanti."
  },
  AvgDialog_18985_Content_24 = {
    Text = "Nella notte nera come la pece, fluttuano come meduse luminescenti nel profondo Tunnel."
  },
  AvgDialog_18985_Content_25 = {
    Text = "<Shake:Padrone, aiutami... Ti prego, aiutami, AAAHHHH!!>"
  },
  AvgDialog_18985_Content_26 = {
    Text = "George! Torna indietro—"
  },
  AvgDialog_18985_Content_27 = {
    Text = "Rogers afferra George, ma vengono avviluppati e circondati da sempre più arti."
  },
  AvgDialog_18985_Content_28 = {
    Text = "Maestro, puoi salvare George... vero?"
  },
  AvgDialog_18985_Content_29 = {Text = "..."},
  AvgDialog_18985_Content_3 = {
    Text = "Poi rilasciano simultaneamente una luce argentea abbagliante, illuminando quasi ogni angolo della frattura."
  },
  AvgDialog_18985_Content_30 = {
    Text = "È questo ciò da cui stavi scappando, Rogers."
  },
  AvgDialog_18985_Content_31 = {
    Text = "Te l'avevo detto — non puoi fingere che non siano mai esistiti."
  },
  AvgDialog_18985_Content_32 = {
    Text = "Ho speso più di v-vent'anni... e t-tutto qui?"
  },
  AvgDialog_18985_Content_33 = {
    Text = "Heh... Hahahah... Non è reale, vero? Niente di tutto questo è reale..."
  },
  AvgDialog_18985_Content_34 = {
    Text = "Certo che sono vere... solo troppo pallide."
  },
  AvgDialog_18985_Content_35 = {
    Text = "Musica, pittura, statue... Ogni bellezza e ogni arte impallidiscono di fronte alla vera sofferenza."
  },
  AvgDialog_18985_Content_36 = {
    Text = "Sotto lo sguardo di @2, tutto è fragile."
  },
  AvgDialog_18985_Content_37 = {
    Text = "Rogers si inginocchia, stringendo George che si sta sciogliendo."
  },
  AvgDialog_18985_Content_38 = {
    Text = "Questo Incubo finirà. Ti ri-riparerò... Lo giuro..."
  },
  AvgDialog_18985_Content_39 = {
    Text = "*Singhiozzi*... Fa male... Così tanto..."
  },
  AvgDialog_18985_Content_4 = {Text = "—!!"},
  AvgDialog_18985_Content_40 = {
    Text = "La cera si aggrappa con Bramosia al braccio di Rogers, perforando la pelle e propagandosi in profondità."
  },
  AvgDialog_18985_Content_41 = {
    Text = "Rogers non prova alcun dolore. Si limita a fissare con tristezza George — o, più precisamente, gli Occhi verde ardesia di George."
  },
  AvgDialog_18985_Content_42 = {
    Text = "Per più di 70 estati soffocanti, ha fissato quegli occhi nell'oscurità."
  },
  AvgDialog_18985_Content_43 = {
    Text = "Quegli occhi verde ardesia — le iridi pallide che catturavano la luce delle candele, scintillanti come acqua increspata, vorticanti come un Labirinto senza fine."
  },
  AvgDialog_18985_Content_44 = {
    Text = "In essi, intravide al contempo genesi e rovina."
  },
  AvgDialog_18985_Content_45 = {
    Text = "Non ti lascerò andare, <Blue:Signor Cera>..."
  },
  AvgDialog_18985_Content_5 = {
    Text = "William lascia sfuggire un sospiro di sollievo e ti rivolge un cenno di approvazione."
  },
  AvgDialog_18985_Content_6 = {
    Text = "Ben fatto, %player%. La frattura è stata chiusa con successo."
  },
  AvgDialog_18985_Content_7 = {
    Text = "Tuttavia, non possiamo abbassare la guardia. L'istante prima che la frattura si chiuda è spesso il più pericoloso..."
  },
  AvgDialog_18985_Content_8 = {
    Text = "<Big:Boom—!!>"
  },
  AvgDialog_18985_Content_9 = {
    Text = "Percependo la propria fine imminente, la frattura trema di disperazione, vomitando melma nera come la pece."
  },
  AvgDialog_18986_Content_1 = {
    Text = "Jenkin, calmati!"
  },
  AvgDialog_18986_Content_10 = {
    Text = "Primo fatto: William Delapore è un Investigatore navigato. Se persino qualcuno come lui è scomparso..."
  },
  AvgDialog_18986_Content_11 = {
    Text = "Potremmo trovarci di fronte a qualcosa di ben peggiore dell'Ospizio dei Poveri."
  },
  AvgDialog_18986_Content_12 = {
    Text = "Fatto numero due: senza il nostro aiuto, non riuscirebbe nemmeno ad arrivare al Museo delle Cere, figuriamoci a salvare sua sorella."
  },
  AvgDialog_18986_Content_13 = {
    Text = "Fatto numero tre..."
  },
  AvgDialog_18986_Content_14 = {
    Text = "Ramona interrompe la comunicazione prima che Doll possa finire."
  },
  AvgDialog_18986_Content_15 = {
    Text = "Mi dispiace, Jenkin. Hai appena perso il tuo migliore amico. Devi sentirti a pezzi."
  },
  AvgDialog_18986_Content_16 = {
    Text = "Ti do la mia parola: <Italic:troveremo> tua sorella. Ma basta azioni avventate, intesi?"
  },
  AvgDialog_18986_Content_17 = {
    Text = "Aspetta, ti stai offrendo di venire con me? Ma il tuo Boss..."
  },
  AvgDialog_18986_Content_18 = {
    Text = "Lascia la persuasione a me."
  },
  AvgDialog_18986_Content_19 = {Text = "..."},
  AvgDialog_18986_Content_2 = {
    Text = "Afferri il polso di Jenkin, ma lei ti scosta la Mano con uno schiaffo."
  },
  AvgDialog_18986_Content_20 = {
    Text = "Ramona sorride e tende la mano verso Jenkin."
  },
  AvgDialog_18986_Content_21 = {
    Text = "Dunque... <Blue:\"Squadra Investigativa del Museo delle Cere di Rogers\">... Raduno, che ne dite?"
  },
  AvgDialog_18986_Content_22 = {
    Text = "Jenkin canticchia sommessamente e stringe goffamente la Mano di Ramona."
  },
  AvgDialog_18986_Content_23 = {
    Text = "Tch. Immatura."
  },
  AvgDialog_18986_Content_3 = {
    Text = "Calmarmi? Io?"
  },
  AvgDialog_18986_Content_4 = {
    Text = "Ti rendi conto che ho appena perso un amico, e mia sorella è scomparsa? Eppure..."
  },
  AvgDialog_18986_Content_5 = {
    Text = "...eppure pretendi che io sopporti le vostre riunioni di Strategia e i rapporti, comportandomi come un soldato professionista?"
  },
  AvgDialog_18986_Content_6 = {
    Text = "Non vi fidate di noi."
  },
  AvgDialog_18986_Content_7 = {
    Text = "Mi fido di te, ma non del tuo boss."
  },
  AvgDialog_18986_Content_8 = {
    Text = "Correzione: consulente tecnico, non boss."
  },
  AvgDialog_18986_Content_9 = {
    Text = "Comprendo l'Ansia che gli esseri umani provano quando perdono un familiare, ma è ora che affronti la realtà."
  },
  AvgDialog_18987_Content_1 = {
    Text = "Buio pesto qui dentro. Potrebbe essere una trappola..."
  },
  AvgDialog_18987_Content_10 = {
    Text = "È equipaggiamento standard da campo, niente di particolarmente speciale."
  },
  AvgDialog_18987_Content_2 = {
    Text = "Che ne dici di questo?"
  },
  AvgDialog_18987_Content_3 = {
    Text = "Nell'oscurità, Ramona accende con calma una torcia, rischiarando nuovamente il sentiero."
  },
  AvgDialog_18987_Content_4 = {
    Text = "Oh, perché c'è luce qui dentro? Cos'è?"
  },
  AvgDialog_18987_Content_5 = {
    Text = [[
Nome scientifico: dispositivo elettronico portatile di illuminazione, comunemente chiamato torcia.
Previene collisioni con muri, alberi e lampioni.]]
  },
  AvgDialog_18987_Content_6 = {Text = "Oh..."},
  AvgDialog_18987_Content_7 = {
    Text = "A volte penso che il tuo zaino sia un buco magico."
  },
  AvgDialog_18987_Content_8 = {
    Text = "Pensi che un giorno tirerai fuori un intero servizio da tè, come nelle fiabe?"
  },
  AvgDialog_18987_Content_9 = {Text = "..."},
  AvgDialog_18988_Content_1 = {
    Text = "Che i nostri Sentieri non si incrocino mai più in questa Vita, miei carissimi nemici!"
  },
  AvgDialog_18988_Content_10 = {
    Text = "Lascialo andare. Rogers è un membro chiave dell'Associazione degli Scultori; non possiamo permetterci di farlo fuggire."
  },
  AvgDialog_18988_Content_11 = {
    Text = "Capito. Ora..."
  },
  AvgDialog_18988_Content_12 = {
    Text = "Ti volti a guardare il caos che hai davanti."
  },
  AvgDialog_18988_Content_13 = {
    Text = "No, non lasciarmi..."
  },
  AvgDialog_18988_Content_14 = {
    Text = "<Big:AAAAHHH—!!>"
  },
  AvgDialog_18988_Content_15 = {
    Text = "Prima le gambe, poi il torso, e infine le braccia..."
  },
  AvgDialog_18988_Content_16 = {
    Text = "No... essere immondo, stai lontano da George..."
  },
  AvgDialog_18988_Content_17 = {
    Text = "Poi la bocca, il naso, gli occhi..."
  },
  AvgDialog_18988_Content_18 = {
    Text = "Le Sculture di Cera strappano la bella Testa d'Oro di George fino a spaccarla completamente."
  },
  AvgDialog_18988_Content_19 = {
    Text = "<Change>Grazie, Rogers. Delizioso! Mangia, mangia—!!!"
  },
  AvgDialog_18988_Content_2 = {
    Text = "Restate qui e Dissolvetevi come brave piccole macchie, e non infestate mai più i miei pensieri!"
  },
  AvgDialog_18988_Content_20 = {
    Text = "<Change>Dammene un po', solo un poco—!!!"
  },
  AvgDialog_18988_Content_21 = {
    Text = "<Shake:Non mangiarmi! Come osi mangiarmi... No—>"
  },
  AvgDialog_18988_Content_22 = {Text = "No..."},
  AvgDialog_18988_Content_23 = {
    Text = "Con la presenza di George, le Sculture di Cera e le parti del corpo, un tempo ammassate come una piccola montagna, cominciano lentamente a fondersi di nuovo."
  },
  AvgDialog_18988_Content_24 = {
    Text = "Melma nera cola dai loro innumerevoli occhi, labbra e orecchie."
  },
  AvgDialog_18988_Content_25 = {
    Text = "La grande testa al centro è George."
  },
  AvgDialog_18988_Content_26 = {
    Text = "<Change>Buhuuu... Così affamato, così affamato..."
  },
  AvgDialog_18988_Content_27 = {
    Text = "È colpa tua... tutta colpa tua..."
  },
  AvgDialog_18988_Content_28 = {
    Text = "<Change>È colpa tua!"
  },
  AvgDialog_18988_Content_3 = {Text = "!!"},
  AvgDialog_18988_Content_4 = {
    Text = "Non possiamo lasciarlo fuggire... %player%, Ramona, riesci a gestire la situazione qui?"
  },
  AvgDialog_18988_Content_5 = {
    Text = "Tu e Ramona annuite all'unisono."
  },
  AvgDialog_18988_Content_6 = {
    Text = "La frattura più pericolosa è sigillata. Lascia il resto a noi. Ma tu, William, andare da solo..."
  },
  AvgDialog_18988_Content_7 = {
    Text = "D'accordo, credo in voi. Tornate vivi, mi raccomando."
  },
  AvgDialog_18988_Content_8 = {
    Text = "Pronunciato il suo commiato, William ripone il suo strumento, afferra la valigia e si affretta a uscire."
  },
  AvgDialog_18988_Content_9 = {Text = "William..."},
  AvgDialog_18991_Content_1 = {
    Text = "Salve, Lady Daffodil"
  },
  AvgDialog_18991_Content_10 = {
    Text = "Il suo tono è morbido e ambiguo, venato da una traccia di eleganza da alta società."
  },
  AvgDialog_18991_Content_11 = {
    Text = "Sebbene parli di scuse, la sua espressione non tradisce alcun rimorso, solo un faint bagliore di scherno."
  },
  AvgDialog_18991_Content_12 = {
    Text = "Un Segugio infernale si aggira per queste terre di recente. Un Dormiveglia anticipato potrebbe risparmiarvi Il Suo Sguardo."
  },
  AvgDialog_18991_Content_13 = {
    Text = "Segugio infernale?"
  },
  AvgDialog_18991_Content_14 = {
    Text = [[
La leggenda narra che se i suoi occhi vi colgono tre volte, cadrete nel nulla, incontrando la vostra fine.
Meglio essere cauti, cari ospiti.]]
  },
  AvgDialog_18991_Content_15 = {
    Text = "Credevo fosse solo una storia per spaventare i Fanciulli irrequieti."
  },
  AvgDialog_18991_Content_16 = {
    Text = "Finzione o realtà, chi può dirlo? Le leggende rurali racchiudono spesso un fondo di verità, non è vero?"
  },
  AvgDialog_18991_Content_17 = {
    Text = "Non sembri convinto."
  },
  AvgDialog_18991_Content_18 = {
    Text = "Verità e menzogna vanno in coppia. La verità di una persona può essere il Delirio di un'altra."
  },
  AvgDialog_18991_Content_19 = {
    Text = [[
Guardatemi, sto di nuovo farneticando.
Non fateci caso, cari ospiti. Riposate bene.]]
  },
  AvgDialog_18991_Content_2 = {
    Text = "Guidati dalla bambina, arrivate a un negozio dall'aspetto modesto all'angolo della strada."
  },
  AvgDialog_18991_Content_20 = {
    Text = "Detto ciò, Daffodil si alza e scivola via, lasciando soltanto la Fragranza Residua del suo profumo."
  },
  AvgDialog_18991_Content_21 = {
    Text = "...Di cosa stavate blaterando?"
  },
  AvgDialog_18991_Content_22 = {
    Text = "Non l'ho capito nemmeno io."
  },
  AvgDialog_18991_Content_23 = {
    Text = [[
Siamo intrappolati in un'illusione.
Usa la Chiave d'argento e vedrai tu stessa.]]
  },
  AvgDialog_18991_Content_24 = {Text = "..."},
  AvgDialog_18991_Content_25 = {Text = "!"},
  AvgDialog_18991_Content_26 = {
    Text = "La Dissoluzione in quest'area è ben oltre la norma, eppure Daffodil e le sue merci restano intatte."
  },
  AvgDialog_18991_Content_27 = {
    Text = "Lady Daffodil, la signora del narciso — difficilmente un nome vero."
  },
  AvgDialog_18991_Content_28 = {
    Text = "Se è una Mercante che traffica in merci di contrabbando, usare uno pseudonimo ha senso."
  },
  AvgDialog_18991_Content_29 = {
    Text = "Anche così, è strano."
  },
  AvgDialog_18991_Content_3 = {
    Text = [[
Una tenue foschia viola vortica nel negozio, largo appena tre metri, eppure l'arredamento trasuda gusto raffinato.
Delicati soprammobili rustici sono impilati strato su strato sul bancone, caotici eppure ordinati.]]
  },
  AvgDialog_18991_Content_30 = {
    Text = "Se fossi una Mercante navigata in una città afflitta da sparizioni, accoglieresti così prontamente tre sconosciuti a mezzanotte?"
  },
  AvgDialog_18991_Content_31 = {
    Text = "Inoltre, continuo a sentire qualcosa che ci osserva."
  },
  AvgDialog_18991_Content_32 = {
    Text = "Senti anche tu quel brivido?"
  },
  AvgDialog_18991_Content_33 = {
    Text = [[
Non mettermi nel tuo stesso mucchio.
Sono solo curiosa di sapere quale audace sciocco osa trattarmi come preda.]]
  },
  AvgDialog_18991_Content_34 = {
    Text = [[
Almeno abbiamo un tetto per ripararci dalla pioggia.
Riposiamo a turno, restiamo vigili e del resto ci occuperemo domani.]]
  },
  AvgDialog_18991_Content_35 = {Text = "..."},
  AvgDialog_18991_Content_36 = {
    Text = "A proposito, Erica?"
  },
  AvgDialog_18991_Content_37 = {
    Text = "Saluti, automa autonomo Erica, in servizio 24 ore su 24, 7 giorni su 7, per fornire tempestivo supporto tecnico e informativo."
  },
  AvgDialog_18991_Content_38 = {
    Text = "Parole chiave: \"Lady Daffodil,\" mercante d'antiquariato."
  },
  AvgDialog_18991_Content_39 = {
    Text = [[
Ricerca per parole chiave "Daffodil," "antiquario." Attendere prego.
Risultati della ricerca: nessuno. Ci scusiamo, provare con parole chiave diverse...]]
  },
  AvgDialog_18991_Content_4 = {
    Text = "Tch, quindi questo è il negozio di Lady Daffodil? Solo una bancarella di cianfrusaglie sul bordo della strada."
  },
  AvgDialog_18991_Content_40 = {Text = "..."},
  AvgDialog_18991_Content_41 = {
    Text = "Mentre la notte si fa più profonda, cullato dalla conversazione di Ramona ed Erica, scivoli in un Sogno..."
  },
  AvgDialog_18991_Content_42 = {Text = "..."},
  AvgDialog_18991_Content_43 = {
    Text = "...Non discutere con lei. Dopo quell'incidente, la gente diceva che avesse perso il senno."
  },
  AvgDialog_18991_Content_44 = {
    Text = "Andò da un dottore, sostenendo di poter vedere <Yellow:dei vuoti nei corpi delle persone>...\nDicendo che quei vuoti avevano ucciso suo marito e sua figlia."
  },
  AvgDialog_18991_Content_45 = {
    Text = "Non è sempre stata nubile? Da dove saltano fuori questo marito e questa figlia?"
  },
  AvgDialog_18991_Content_46 = {
    Text = "Esatto. Non è pura follia, questa?"
  },
  AvgDialog_18991_Content_47 = {
    Text = "Se è così, possiamo richiedere una valutazione psichiatrica per lei?"
  },
  AvgDialog_18991_Content_48 = {
    Text = "È davvero necessario? Le persone normali non si offrono volontarie per morire quando sono in perfetta salute."
  },
  AvgDialog_18991_Content_49 = {
    Text = "E quegli esploratori fanatici? Neanche loro sono a posto con la testa. Se facessimo controlli psichiatrici, dubito che qualcuno li supererebbe."
  },
  AvgDialog_18991_Content_5 = {
    Text = "E questi... oggetti d'antiquariato? Cose grottesche, contorte."
  },
  AvgDialog_18991_Content_50 = {
    Text = "Una melma nera e viscosa gocciola dal cielo, avvolgendo la tua visuale."
  },
  AvgDialog_18991_Content_51 = {
    Text = "Ricopre i gradini della <Blue:Fondazione>, le sue porte, i suoi sportelli."
  },
  AvgDialog_18991_Content_52 = {
    Text = "Fino a coprire i volti degli impiegati della Fondazione."
  },
  AvgDialog_18991_Content_53 = {
    Text = "La avverto, mi riservo il diritto di denunciarla per diffamazione."
  },
  AvgDialog_18991_Content_54 = {
    Text = [[
Queste melme nere... non potete vederle, ma sono reali.
Sono state loro. Hanno portato via...]]
  },
  AvgDialog_18991_Content_55 = {
    Text = "Mi hanno portato via i miei più cari..."
  },
  AvgDialog_18991_Content_56 = {
    Text = "Perché? Perché non riescono a vedere?"
  },
  AvgDialog_18991_Content_57 = {
    Text = "Fa male, ma @2 può sopportare, mamma."
  },
  AvgDialog_18991_Content_58 = {
    Text = "No, no, così non va. Svanirai.\nHo già perso @3; non posso perdere anche te."
  },
  AvgDialog_18991_Content_59 = {
    Text = "Non lascerò la mamma."
  },
  AvgDialog_18991_Content_6 = {
    Text = "Io li trovo piuttosto preziosi, questi tesori segreti. Non trovate una certa bellezza nel loro passaggio attraverso il logorio del tempo?"
  },
  AvgDialog_18991_Content_60 = {
    Text = "Perché? Non avevi detto che non mi avresti lasciata?"
  },
  AvgDialog_18991_Content_61 = {
    Text = "Nemmeno tu riesci a vederlo."
  },
  AvgDialog_18991_Content_62 = {
    Text = "Ma io sì, io riesco a vederlo!"
  },
  AvgDialog_18991_Content_63 = {
    Text = [[
Non sono scomparsi; sono malati, si stanno Dissolvendo...
Quelle melme nere li stanno dissolvendo...]]
  },
  AvgDialog_18991_Content_64 = {
    Text = [[
La donna mormora, sprofondando in un sonno profondo. Una nebbia gentile la avvolge, celando lentamente la sua figura.
Dalla fitta foschia emerge un'ombra viola scuro.]]
  },
  AvgDialog_18991_Content_65 = {
    Text = "Sono venuto a vedere se fosse il momento di mietere... ma la faccenda si fa assai più interessante."
  },
  AvgDialog_18991_Content_66 = {
    Text = "Va bene, tieniti quella testa per ora."
  },
  AvgDialog_18991_Content_67 = {
    Text = "Ma quando farai Ritorno da quell'Abisso gelido, sarà meglio che me la consegni con le buone, hmm?"
  },
  AvgDialog_18991_Content_7 = {
    Text = "Una voce inquietante si leva dalle ombre sfocate, come un basso profondo che confluisce in una sinfonia intricata."
  },
  AvgDialog_18991_Content_8 = {
    Text = "Le mie scuse, permettetemi di presentarmi. Sono Daffodil, la proprietaria di questo umile negozio."
  },
  AvgDialog_18991_Content_9 = {
    Text = "Non desidero intromettermi nella vostra conversazione.\nSolo un promemoria, cari ospiti, la notte si fa tarda—è ora di riposare."
  },
  AvgDialog_18992_Content_1 = {
    Text = "Una Vita Senza Amici"
  },
  AvgDialog_18992_Content_10 = {
    Text = "Helot mormora, le labbra appena dischiuse, intonando un'incantazione rozza, arcaica, profana."
  },
  AvgDialog_18992_Content_11 = {
    Text = "<BigShake:@2—@1—>"
  },
  AvgDialog_18992_Content_12 = {
    Text = "Cos'è quel suono?! Dannazione, la testa mi sta scoppiando..."
  },
  AvgDialog_18992_Content_13 = {
    Text = [[
Non hai mai sentito questa lingua, eppure in qualche modo ne afferri il significato.
Sussurri infiniti invadono la tua corteccia, la loro cadenza inquietante risuona come un incubo.]]
  },
  AvgDialog_18992_Content_14 = {
    Text = "<Change>Ritorno al nido primordiale..."
  },
  AvgDialog_18992_Content_15 = {
    Text = "<Change>Ritorno al Reame eterno..."
  },
  AvgDialog_18992_Content_16 = {
    Text = "<Change>Ritorno all'Abbraccio della Madre..."
  },
  AvgDialog_18992_Content_17 = {
    Text = "Capisci, ma non comprendi."
  },
  AvgDialog_18992_Content_18 = {
    Text = "Il calore premuto contro il tuo fianco svanisce, il lembo stretto ricade inerte, e nella tua visione offuscata, una figura fragile si dissolve in un tenue grappolo di luce."
  },
  AvgDialog_18992_Content_19 = {
    Text = "Ma... dre..."
  },
  AvgDialog_18992_Content_2 = {
    Text = "Huff, huff—"
  },
  AvgDialog_18992_Content_20 = {
    Text = "Lily, non ascoltare!"
  },
  AvgDialog_18992_Content_21 = {Text = "No, no..."},
  AvgDialog_18992_Content_22 = {
    Text = "Se Lisa gioca con me, la mamma non si arrabbierà?"
  },
  AvgDialog_18992_Content_23 = {
    Text = "Heh, finché lei non lo sa, va bene.\nManterrai il segreto, vero?"
  },
  AvgDialog_18992_Content_24 = {
    Text = "Hmm, Lily non lo dirà a nessuno."
  },
  AvgDialog_18992_Content_25 = {
    Text = "Allora va bene. È il nostro piccolo segreto, d'accordo?"
  },
  AvgDialog_18992_Content_26 = {
    Text = "Finalmente ti ho trovata."
  },
  AvgDialog_18992_Content_27 = {
    Text = [[
Chi... sei tu?
Non ti ho mai visto. Non sei di queste parti, vero?]]
  },
  AvgDialog_18992_Content_28 = {
    Text = [[
Non sono qui per te. Sono qui per lei.
Lily, ti ricordi di me? Sono un vecchio amico di tua mamma.]]
  },
  AvgDialog_18992_Content_29 = {
    Text = "Quando lavoravamo insieme, ti portava spesso all'istituto. Dopo tutti questi anni, non sei cambiata di una virgola."
  },
  AvgDialog_18992_Content_3 = {
    Text = "Non sei alla mia altezza."
  },
  AvgDialog_18992_Content_30 = {
    Text = "Sei stata lontana dalla tua mamma per un po', vero?\nLo zio è qui per riportarti a casa."
  },
  AvgDialog_18992_Content_31 = {
    Text = "Lily non può venire con te.\nOggi è sgattaiolata fuori per giocare con me. Devo prima portarla da Lady Daffodil."
  },
  AvgDialog_18992_Content_32 = {
    Text = "La mamma di Lily mi ha detto di riportarla il prima possibile."
  },
  AvgDialog_18992_Content_33 = {
    Text = "Lady Daffodil è solo un'Ospite. Non potresti, piccola amica, riferire un messaggio per noi?"
  },
  AvgDialog_18992_Content_34 = {
    Text = "Non se ne parla. Se Lady Daffodil mi sgrida, non saprò che fare."
  },
  AvgDialog_18992_Content_35 = {
    Text = "Ma Lily deve venire con me adesso."
  },
  AvgDialog_18992_Content_36 = {
    Text = "Herbert allunga la mano verso il braccio esile di Lily, ma Lisa si interpone per bloccarlo."
  },
  AvgDialog_18992_Content_37 = {
    Text = "Lily, corri!"
  },
  AvgDialog_18992_Content_38 = {
    Text = "Lo scenario dietro di te sfuma mentre fuggi.\nTutto ciò che senti è il grido disperato di Lisa."
  },
  AvgDialog_18992_Content_39 = {
    Text = "Corri, non voltarti indietro, trova Lady Daffodil!"
  },
  AvgDialog_18992_Content_4 = {
    Text = "Una preda della giungla, orgogliosa della propria velocità, osa sfidare la canna del cacciatore — ecco cosa succede."
  },
  AvgDialog_18992_Content_40 = {Text = "..."},
  AvgDialog_18992_Content_41 = {
    Text = "Hmph, insetto ficcanaso..."
  },
  AvgDialog_18992_Content_42 = {
    Text = "La Marea nero-verdastra si condensa in un'enorme pustola protoplasmatica, strani Bagliori che tremolano sulla sua superficie."
  },
  AvgDialog_18992_Content_43 = {
    Text = "Lacrime nere sgorgano dagli occhi di Lily."
  },
  AvgDialog_18992_Content_44 = {
    Text = "<BigShake:@2—@1—>"
  },
  AvgDialog_18992_Content_45 = {
    Text = "<BigShake:@2—@1—>"
  },
  AvgDialog_18992_Content_46 = {
    Text = [[
Un timbro familiare si distende in una cadenza aliena.
Una voce simile non dovrebbe provenire da una bambina.]]
  },
  AvgDialog_18992_Content_47 = {
    Text = "<BigShake:@2—@1—>"
  },
  AvgDialog_18992_Content_48 = {Text = "%player%!"},
  AvgDialog_18992_Content_49 = {
    Text = "Non fate del male a Lily!"
  },
  AvgDialog_18992_Content_5 = {
    Text = "Il mio vantaggio su di te... è schiacciante."
  },
  AvgDialog_18992_Content_50 = {
    Text = "Prima proteggi te stessa!"
  },
  AvgDialog_18992_Content_51 = {Text = "Capito!"},
  AvgDialog_18992_Content_52 = {
    Text = "Non c'è bisogno di dirmelo — un po' di mal di testa non mi fermerà!"
  },
  AvgDialog_18992_Content_6 = {
    Text = "Helot china il capo, sopportando gli scherni di Lotan senza battere ciglio."
  },
  AvgDialog_18992_Content_7 = {Text = "!"},
  AvgDialog_18992_Content_8 = {Text = "Che—"},
  AvgDialog_18992_Content_9 = {
    Text = "All'improvviso, una marea nero-verde ti sommerge, un antico lamento agghiacciante riecheggia nella tua mente."
  },
  AvgDialog_18994_Content_1 = {
    Text = "Commercio Equo"
  },
  AvgDialog_18994_Content_10 = {
    Text = "Daffodil estrae due <Blue:fascicoli> dal vuoto della nebbia grigia, spolverandoli con un gesto leggero."
  },
  AvgDialog_18994_Content_11 = {
    Text = "Una volta che la polvere si sarà posata, li invierò ai vostri rispettivi quartier generali.\nLa mia unica condizione è che vi separiate qui, ognuno per la propria strada."
  },
  AvgDialog_18994_Content_12 = {
    Text = "Forse un giorno le vostre strade si incroceranno di nuovo, ma questo spetta allo Sguardo di Loro deciderlo."
  },
  AvgDialog_18994_Content_13 = {
    Text = "Quei fascicoli..."
  },
  AvgDialog_18994_Content_14 = {
    Text = "Riguardano il Segugio infernale. Non pensavate che fossi venuta a Rye per degli oggetti d'antiquariato, vero?"
  },
  AvgDialog_18994_Content_15 = {
    Text = "Devo verificare il valore dei fascicoli."
  },
  AvgDialog_18994_Content_16 = {
    Text = "Ramona, tu cosa ne pensi?"
  },
  AvgDialog_18994_Content_17 = {
    Text = "Siamo noi quelli che sono stati attaccati... accettare una tregua non ci costa nulla."
  },
  AvgDialog_18994_Content_18 = {
    Text = [[
Ma devo verificare il valore dei dossier.
Posso leggere la copertina?]]
  },
  AvgDialog_18994_Content_19 = {
    Text = "Naturalmente."
  },
  AvgDialog_18994_Content_2 = {
    Text = "Il balbettio si spegne, lasciando solo un Silenzio senza fine nell'auto."
  },
  AvgDialog_18994_Content_20 = {
    Text = "Ramona prende il fascicolo dalle mani di Daffodil, gli occhi che guizzano lungo le righe dietro le lenti. Poi annuisce in tua direzione."
  },
  AvgDialog_18994_Content_21 = {
    Text = "Affare fatto."
  },
  AvgDialog_18994_Content_22 = {
    Text = "Adoro gli ospiti diretti come te.\nIl dossier verrà spedito all'ufficio dell'Università di Mythag entro sette giorni."
  },
  AvgDialog_18994_Content_23 = {
    Text = "E voi, signora? Avete preso la vostra decisione?"
  },
  AvgDialog_18994_Content_24 = {
    Text = "Helot si irrigidisce, la melma che si condensa in uno spuntone nel palmo della mano."
  },
  AvgDialog_18994_Content_25 = {
    Text = "Rifiuto. Ho una missione da portare a termine."
  },
  AvgDialog_18994_Content_26 = {
    Text = [[
Ci ripenserai.
Questo contiene dettagli su "<Yellow:quell'incidente>" di dieci anni fa.]]
  },
  AvgDialog_18994_Content_27 = {
    Text = [[
Daffodil tira fuori un emblema, mostrandolo a Helot nel palmo della mano.
Nel momento in cui lo vede, il volto di Helot cambia.]]
  },
  AvgDialog_18994_Content_28 = {
    Text = "Dove hai—"
  },
  AvgDialog_18994_Content_29 = {
    Text = "Shh—\nFinché non accetti l'accordo, non dirò una parola."
  },
  AvgDialog_18994_Content_3 = {
    Text = "Lotan balza in avanti, afferrando Lily che sta crollando."
  },
  AvgDialog_18994_Content_30 = {
    Text = "Helot aggrotta la fronte, apre la bocca come per parlare, ma tace, ritirandosi nelle ombre."
  },
  AvgDialog_18994_Content_31 = {
    Text = "Con un grugnito, Helot punta lo Spuntone verso il suolo, scavando un solco profondo, scintille che volano per l'attrito."
  },
  AvgDialog_18994_Content_32 = {
    Text = "Accetto. Ma—"
  },
  AvgDialog_18994_Content_33 = {
    Text = "Punta lo Spuntone verso il Fascicolo tra le braccia di Daffodil."
  },
  AvgDialog_18994_Content_34 = {
    Text = "Devi darmi il fascicolo adesso."
  },
  AvgDialog_18994_Content_35 = {
    Text = "Così impaziente? Peccato, il prezzo è fissato. Il Negozio di Daffodil non tratta."
  },
  AvgDialog_18994_Content_36 = {
    Text = "Daffodil evoca una Nebbia grigia, il Fascicolo pronto a svanire al suo interno."
  },
  AvgDialog_18994_Content_37 = {
    Text = "In un lampo, Helot si avventa su Daffodil come un'Ombra."
  },
  AvgDialog_18994_Content_39 = {
    Text = [[
Eppure, la sagoma viola svanisce nell'istante in cui Helot si avvicina.
Daffodil riappare tranquillamente alle sue spalle, ancora con il dossier saldamente in mano.]]
  },
  AvgDialog_18994_Content_4 = {
    Text = [[
Clap, clap, clap.
Nel tunnel buio pesto, un applauso nitido risuona.]]
  },
  AvgDialog_18994_Content_40 = {
    Text = "La fretta è cattiva consigliera, piccola.\nBene, non mi attarderò. Ancora una volta, buon viaggio."
  },
  AvgDialog_18994_Content_41 = {
    Text = "La nebbia grigia si gonfia.\nPochi secondi dopo, torna il silenzio, e Daffodil è scomparsa."
  },
  AvgDialog_18994_Content_42 = {Text = "..."},
  AvgDialog_18994_Content_43 = {
    Text = "Helot sbuffa, svanendo nell'oscurità."
  },
  AvgDialog_18994_Content_44 = {
    Text = "Ramona, e noi...?"
  },
  AvgDialog_18994_Content_45 = {
    Text = "...Lotan, per favore prenditi cura di Lily fino al nostro ritorno."
  },
  AvgDialog_18994_Content_46 = {
    Text = "Tanto perché tu lo sappia, non sono bravo con i bambini."
  },
  AvgDialog_18994_Content_47 = {
    Text = "Custode, ti fidi di me?"
  },
  AvgDialog_18994_Content_48 = {
    Text = "Naturalmente."
  },
  AvgDialog_18994_Content_49 = {
    Text = [[
Allora, per favore chiudi gli occhi un momento.
Andiamo da qualche parte.]]
  },
  AvgDialog_18994_Content_5 = {
    Text = "Ad accompagnare il ritmo degli applausi è una voce femminile ambigua, venata di divertita approvazione. Una gonna avvolta di nebbia grigia emerge dal confine tra luce e ombra, e l'aria si impregna all'improvviso di una tenue fragranza di violetta."
  },
  AvgDialog_18994_Content_50 = {
    Text = "Chiudi gli occhi come ti è stato detto.\nNell'oscurità, la mano fresca di Ramona prende la tua, guidandoti lentamente verso una certa destinazione."
  },
  AvgDialog_18994_Content_6 = {
    Text = "Grazie per lo splendido spettacolo. Sembrate tutti esausti... che ne dite di una tregua?"
  },
  AvgDialog_18994_Content_7 = {
    Text = "Lo dici tu di fermarci, e noi ci fermiamo? Perché dovremmo ascoltarti?"
  },
  AvgDialog_18994_Content_8 = {
    Text = [[
La bottega di Daffodil non delude mai i suoi ospiti.
Sono qui per proporre un affare.]]
  },
  AvgDialog_18994_Content_9 = {
    Text = "Ho due fascicoli, ciascuno contenente le risposte che cercate."
  },
  AvgDialog_18995_Content_1 = {
    Text = "Queste pustole... Ho un brutto presentimento."
  },
  AvgDialog_18995_Content_2 = {
    Text = "Che succede?"
  },
  AvgDialog_18995_Content_3 = {
    Text = "Forse sto pensando troppo. Raggiungiamo prima Lotan."
  },
  AvgDialog_18996_Content_1 = {
    Text = "Vieni qui, demonio marcio!"
  },
  AvgDialog_18996_Content_2 = {
    Text = "Ehi, ragazzina, pensi di riuscire a prendermi?"
  },
  AvgDialog_18996_Content_3 = {
    Text = "...Non sono sicura se i prepotenti siamo noi o loro."
  },
  AvgDialog_18997_Content_1 = {
    Text = "Pensa Prima di Agire"
  },
  AvgDialog_18997_Content_10 = {
    Text = [[
William dispone con cautela diverse fotografie dall'archivio.
Al centro di ciascuna, un inquietante triangolo nero emana lentamente una foschia oscura.]]
  },
  AvgDialog_18997_Content_11 = {
    Text = "<Yellow:Dissoluzione grave>."
  },
  AvgDialog_18997_Content_12 = {
    Text = "La polizia ha ricevuto denunce di persone scomparse due settimane fa."
  },
  AvgDialog_18997_Content_13 = {
    Text = "<Yellow:Si sta propagando rapidamente>, in modo insolito."
  },
  AvgDialog_18997_Content_14 = {
    Text = "Si sono verificati anche numerosi casi di isteria in città, e la polizia ha presentato un rapporto di avvistamento per il \"<Blue:Segugio infernale Cerbero>\"."
  },
  AvgDialog_18997_Content_15 = {
    Text = "Sospetti che il \"Segugio infernale\" sia il <Yellow:Cataclisma> di questa regione?"
  },
  AvgDialog_18997_Content_16 = {
    Text = "Esattamente. Date le antiche leggende locali sul \"Segugio infernale\", potrebbe persino trattarsi di un <Yellow:Cataclisma Primordiale> appena ridestato dal dormiveglia."
  },
  AvgDialog_18997_Content_17 = {
    Text = "Questa missione comporterà probabilmente una battaglia feroce. Vorrei che \"lei\" accompagnasse il Custode."
  },
  AvgDialog_18997_Content_18 = {
    Text = "Quella forsennata ossessionata dalla battaglia... Dopo l'incidente della Pozza nera, si è accampata là, disertando i suoi doveri d'insegnamento."
  },
  AvgDialog_18997_Content_19 = {
    Text = "Probabilmente servirà che il Custode glielo chieda di persona per smuoverla."
  },
  AvgDialog_18997_Content_2 = {
    Text = "Università di Mythag, Ufficio del Dipartimento di Studi sul Risveglio"
  },
  AvgDialog_18997_Content_20 = {
    Text = "{Male=Lui è,Female=Lei è} già al lavoro."
  },
  AvgDialog_18997_Content_21 = {
    Text = "Lotan siede nell'angolo più remoto della Pozza Nera, con lo sguardo rivolto al vasto cielo vuoto.\nÈ lì che Tawil apparve un tempo."
  },
  AvgDialog_18997_Content_22 = {
    Text = "Dimmi, si risveglieranno di nuovo?"
  },
  AvgDialog_18997_Content_23 = {
    Text = "Dovrai affrontare altri nemici—"
  },
  AvgDialog_18997_Content_24 = {
    Text = "Come il Segugio infernale, per esempio."
  },
  AvgDialog_18997_Content_25 = {
    Text = "Tch—\nIl \"Segugio infernale\"? Una banale fantasia partorita da mortali terrorizzati dalla morte?"
  },
  AvgDialog_18997_Content_26 = {
    Text = "Abbiamo bisogno della tua forza."
  },
  AvgDialog_18997_Content_27 = {
    Text = [[
E a me ne basta uno solo, quello nella pozza.
Che si risveglino, e mi offrano un combattimento degno.]]
  },
  AvgDialog_18997_Content_28 = {
    Text = "Nessuno sa per quanto tempo dormiranno."
  },
  AvgDialog_18997_Content_29 = {
    Text = "Esisto su questo pianeta sin dalla sua genesi. Nessuno mi supera in pazienza."
  },
  AvgDialog_18997_Content_3 = {
    Text = "<Blue:La leggenda di Cerbero> risale alla Grecia dell'VIII secolo a.C.\nI poeti di quell'epoca lo descrissero così:"
  },
  AvgDialog_18997_Content_30 = {
    Text = "E... nessuno sa per quanto tempo dormiranno?"
  },
  AvgDialog_18997_Content_31 = {Text = "Ti sbagli."},
  AvgDialog_18997_Content_32 = {
    Text = "Con te, l'unica Variabile, in gioco, il Loro risveglio è solo questione di tempo, non è vero?"
  },
  AvgDialog_18997_Content_33 = {Text = "..."},
  AvgDialog_18997_Content_34 = {
    Text = "Rilassati, ti sto solo prendendo in giro.\nVerrò con voi, ma stabiliamo tre regole fondamentali."
  },
  AvgDialog_18997_Content_35 = {
    Text = "Fai i loro nomi."
  },
  AvgDialog_18997_Content_36 = {
    Text = "Primo, i combattimenti li gestisco io — non seccatemi con le vostre faccende insignificanti."
  },
  AvgDialog_18997_Content_37 = {
    Text = "Secondo, non intrometterti nelle mie azioni indipendenti."
  },
  AvgDialog_18997_Content_38 = {
    Text = "Terzo, se scelgo un avversario, mi lasciate affrontarlo in singolar tenzone."
  },
  AvgDialog_18997_Content_39 = {
    Text = "E lei ha semplicemente accettato di venire?"
  },
  AvgDialog_18997_Content_4 = {
    Text = "Nato da Echidna, generato da Tifone, con tre teste, <Yellow:coloro che vengono cacciati tre volte da esso avranno le anime vincolate agli Inferi>."
  },
  AvgDialog_18997_Content_40 = {
    Text = "Con il mio misero corpo mortale, difficilmente avrei potuto trascinarla qui con la forza, no?"
  },
  AvgDialog_18997_Content_41 = {
    Text = "Ha una capacità di adattamento sorprendente."
  },
  AvgDialog_18997_Content_42 = {
    Text = "Una persona — no, una creatura — che ha vissuto per eoni, sopravvivendo a innumerevoli sconvolgimenti, dev'essere maestra nell'adattarsi ai colpi della sorte."
  },
  AvgDialog_18997_Content_43 = {
    Text = "Speriamo che l'indagine proceda altrettanto bene."
  },
  AvgDialog_18997_Content_44 = {
    Text = "Con i registri e le memorie cancellati dalla Dissoluzione, scarseggiano testimoni e prove..."
  },
  AvgDialog_18997_Content_45 = {
    Text = [[
Non portare sfortuna. Se Lotan fa questo viaggio per niente...
Probabilmente la ritroveremo solo alla Pozza Nera.]]
  },
  AvgDialog_18997_Content_46 = {
    Text = "A proposito, non è che abbiamo perso di vista Lotan da un po'?"
  },
  AvgDialog_18997_Content_5 = {
    Text = "Hmm, è scritto con un certo estro, e hanno persino elencato alcuni casi di avvistamento dell'anno 187 d.F."
  },
  AvgDialog_18997_Content_6 = {
    Text = "Risparmiami quegli avvistamenti. Le fonti citate sono dubbie o del tutto inventate."
  },
  AvgDialog_18997_Content_7 = {
    Text = "Persino quella cosiddetta descrizione di un antico poeta greco diverge enormemente dalla ricerca accademica moderna."
  },
  AvgDialog_18997_Content_8 = {
    Text = "Se stai mandando il Custode sul campo basandoti su poche pagine di finzione, William, devo mettere in dubbio la diligenza della squadra d'indagine."
  },
  AvgDialog_18997_Content_9 = {
    Text = "Non è che non sia disposto a fornire prove sul campo, è solo che..."
  },
  AvgDialog_18998_Content_1 = {
    Text = "Non riparare ciò che è intatto"
  },
  AvgDialog_18998_Content_10 = {
    Text = "Non è che rifiuti le voci esterne, solo... i {Male=suoi,Female=suoi} pensieri contano troppo."
  },
  AvgDialog_18998_Content_11 = {
    Text = "Ammassare avventatamente un carico pesante a prua o a poppa di un'imbarcazione a malapena stabile non è prudente."
  },
  AvgDialog_18998_Content_12 = {
    Text = [[
...Che ne pensi, Lotan?
Dell'essere un Risvegliatore.]]
  },
  AvgDialog_18998_Content_13 = {Text = "Io?"},
  AvgDialog_18998_Content_14 = {
    Text = "...Difficile a dirsi."
  },
  AvgDialog_18998_Content_15 = {
    Text = [[
Quando il pianeta nacque, mi risvegliai nella culla della terra, circondato dal caos.
Persino una balena del maelstrom si sente piccola di fronte al vasto cosmo.]]
  },
  AvgDialog_18998_Content_16 = {
    Text = "Diventare un Risvegliatore è la stessa sensazione.\nQuando mi sono Risvegliato, il mio spirito e la mia volontà erano incompleti, stabilizzandosi solo attraverso il legame con una Chiave d'argento."
  },
  AvgDialog_18998_Content_17 = {
    Text = "Non so cosa provino gli ex umani, ma per me è come stipare una bestia colossale in un guscio fragile e indifeso."
  },
  AvgDialog_18998_Content_18 = {
    Text = "Le tue forze alla fine sono tornate, no?"
  },
  AvgDialog_18998_Content_19 = {
    Text = "Già. Sono una creazione Mythag delle origini, il mio Risveglio è incompleto, e ha richiesto molto più tempo degli altri."
  },
  AvgDialog_18998_Content_2 = {
    Text = "{Male=Si è,Female=Si è} addormentato{Male=,Female=a}?"
  },
  AvgDialog_18998_Content_20 = {
    Text = "Ma presto ho ritrovato me stess{Male=o,Female=a}, ho trovato ciò che volevo: affrontare avversari capaci di farmi ribollire il sangue."
  },
  AvgDialog_18998_Content_21 = {
    Text = "In miliardi di anni, questo ciclo di sonno e risveglio si è ripetuto innumerevoli volte.\nCi sono abituato."
  },
  AvgDialog_18998_Content_22 = {
    Text = "Ma in un tempo quasi infinito, sono giunto a una conclusione:\nOltre alla ricerca di avversari degni, tutto il resto è privo di significato."
  },
  AvgDialog_18998_Content_23 = {
    Text = "Non puoi cambiare la tua forma. Invece di arrovellarti, trova un senso nel vivere come Risvegliatore.\nIl corpo può essere plasmato dal Nucleo d'Argento, ma ciò che faccio è una mia scelta."
  },
  AvgDialog_18998_Content_24 = {
    Text = "Quella è la tua risposta."
  },
  AvgDialog_18998_Content_25 = {
    Text = "Troverai anche la tua, bambina."
  },
  AvgDialog_18998_Content_26 = {
    Text = "Non vedo l'ora che arrivi il giorno in cui raggiungerai quel punto."
  },
  AvgDialog_18998_Content_27 = {
    Text = "Che la Chiave d'Argento Illumini il Cammino."
  },
  AvgDialog_18998_Content_28 = {
    Text = [[
Sembra sdolcinato a dirlo, ma va bene...
Che la Chiave d'argento ci guidi.]]
  },
  AvgDialog_18998_Content_29 = {Text = "Sogno"},
  AvgDialog_18998_Content_3 = {
    Text = [[
Crollat{Male=his,Female=her} appena la testa ha toccato il cuscino.
Questi ultimi giorni hanno prosciugato {Male=his,Female=her} energie mentali.]]
  },
  AvgDialog_18998_Content_30 = {Text = "..."},
  AvgDialog_18998_Content_31 = {Text = "Gabbie."},
  AvgDialog_18998_Content_32 = {
    Text = "Innumerevoli gabbie."
  },
  AvgDialog_18998_Content_33 = {
    Text = "Questa sembra essere una grotta.\nIl tuo corpo non è più freddo, ma il tuo cuore è più gelido del ghiaccio polare."
  },
  AvgDialog_18998_Content_34 = {
    Text = "...Colonnello... Bertrand."
  },
  AvgDialog_18998_Content_35 = {
    Text = "La tua voce è insopportabilmente roca."
  },
  AvgDialog_18998_Content_36 = {
    Text = "La bambina accanto al fuoco nota il tuo movimento, ma si limita a rivolgerti uno sguardo altero, senza dire nulla."
  },
  AvgDialog_18998_Content_37 = {
    Text = "Dove... sono?"
  },
  AvgDialog_18998_Content_38 = {
    Text = "La bambina non risponde."
  },
  AvgDialog_18998_Content_39 = {
    Text = "La tua coscienza si schiarisce, il tuo sguardo si fissa su un segno inciso sulla parete della grotta."
  },
  AvgDialog_18998_Content_4 = {
    Text = "Siamo nel territorio del Sanatorio di Rye ormai. Più avanti potrebbe non esserci tempo per riposare."
  },
  AvgDialog_18998_Content_40 = {
    Text = "...Corrisponde esattamente a quella sulla mappa di Cecily."
  },
  AvgDialog_18998_Content_41 = {
    Text = "Questa è... la Chiesa @3?\nSo di voi—potete riportare in vita i morti, vero?"
  },
  AvgDialog_18998_Content_42 = {
    Text = [[
La ragazza ti guarda di nuovo, gli occhi pieni di disgusto.
Come infastidita dal tuo rumore, si alza e si dirige fuori dalla grotta, borbottando sottovoce.]]
  },
  AvgDialog_18998_Content_43 = {
    Text = "<Small:Sciocco.>"
  },
  AvgDialog_18998_Content_44 = {Text = "..."},
  AvgDialog_18998_Content_45 = {Text = "..."},
  AvgDialog_18998_Content_46 = {Text = "..."},
  AvgDialog_18998_Content_47 = {
    Text = [[
Dopo un po', la ragazza torna,
con in mano un coltello da intaglio e un pezzo di legno.]]
  },
  AvgDialog_18998_Content_48 = {
    Text = "Si siede accanto al fuoco e inizia a intagliare."
  },
  AvgDialog_18998_Content_49 = {
    Text = "Noti che ha le dita avvolte in bende."
  },
  AvgDialog_18998_Content_5 = {
    Text = [[
Dovresti dormire anche tu.
Dopotutto, sei ancora umano.]]
  },
  AvgDialog_18998_Content_50 = {
    Text = "...Il tuo coltello è troppo smussato. Ti taglierai facilmente la mano.\nE per intagliare legno grande, quella piccola lama non è adatta."
  },
  AvgDialog_18998_Content_51 = {Text = "..."},
  AvgDialog_18998_Content_52 = {
    Text = "...È tutto ciò che ho."
  },
  AvgDialog_18998_Content_53 = {
    Text = "Ho degli attrezzi nella mia borsa. Potresti prenderli per me?"
  },
  AvgDialog_18998_Content_54 = {Text = "..."},
  AvgDialog_18998_Content_55 = {Text = "..."},
  AvgDialog_18998_Content_56 = {
    Text = "Passano un'ora o due, la bambina ancora intenta a intagliare."
  },
  AvgDialog_18998_Content_57 = {
    Text = "Come ti chiami?"
  },
  AvgDialog_18998_Content_58 = {
    Text = "<Blue:Murphy>."
  },
  AvgDialog_18998_Content_59 = {
    Text = "Avevo una figlia. Se fosse viva, avrebbe più o meno la tua età."
  },
  AvgDialog_18998_Content_6 = {Text = "..."},
  AvgDialog_18998_Content_60 = {
    Text = "È morta di una malattia nera. Nessuno mi ha creduto..."
  },
  AvgDialog_18998_Content_61 = {Text = "..."},
  AvgDialog_18998_Content_62 = {
    Text = "Fare amicizia non ti servirà.\nNon sono io a decidere qui."
  },
  AvgDialog_18998_Content_63 = {
    Text = "Non ho la chiave per farti uscire."
  },
  AvgDialog_18998_Content_64 = {
    Text = "Il tono della bambina è freddo e aspro."
  },
  AvgDialog_18998_Content_65 = {
    Text = "Non importa, non sto cercando di fuggire..."
  },
  AvgDialog_18998_Content_66 = {
    Text = "A proposito, puoi parlarmi di quella storia del \"riportare in vita i morti\"...\nÈ vera?"
  },
  AvgDialog_18998_Content_67 = {Text = "..."},
  AvgDialog_18998_Content_68 = {Text = "..."},
  AvgDialog_18998_Content_69 = {Text = "..."},
  AvgDialog_18998_Content_7 = {
    Text = "...\nPerché {Male=him,Female=her} hai interrotto prima?"
  },
  AvgDialog_18998_Content_70 = {
    Text = "L'aria si gela per oltre dieci minuti.\nProprio quando pensi che non risponderà, parla, con tono tagliente."
  },
  AvgDialog_18998_Content_71 = {
    Text = "Supponi di restare di nuovo incinta e avere un figlio, e che ti dicessero che è tua figlia rinata. Ci crederesti?"
  },
  AvgDialog_18998_Content_72 = {Text = "..."},
  AvgDialog_18998_Content_73 = {
    Text = "Se si ricordasse di me, se ricordasse il nostro passato, allora sì."
  },
  AvgDialog_18998_Content_74 = {Text = "..."},
  AvgDialog_18998_Content_75 = {
    Text = "Dopo un lungo silenzio, Murphy sospira."
  },
  AvgDialog_18998_Content_76 = {
    Text = "Gli esseri umani sono sciocchi come sempre."
  },
  AvgDialog_18998_Content_77 = {
    Text = "<Small:Pensavo che tu potessi vedere e che fossi diversa.>"
  },
  AvgDialog_18998_Content_78 = {Text = "..."},
  AvgDialog_18998_Content_79 = {
    Text = "...Quel cadavere che stavi trascinando, chi era?"
  },
  AvgDialog_18998_Content_8 = {Text = "..."},
  AvgDialog_18998_Content_80 = {
    Text = "La mia amica. Si è presa cura di me durante questo viaggio.\nLa mappa per arrivare qui era sua."
  },
  AvgDialog_18998_Content_81 = {
    Text = "Un'amica, eh..."
  },
  AvgDialog_18998_Content_82 = {
    Text = "Come sta... adesso?"
  },
  AvgDialog_18998_Content_83 = {
    Text = "<Blue:Miryam> probabilmente ha trasformato il suo corpo in una sorta di mangime. Un corpo con livor mortis non può nemmeno servire da combustibile."
  },
  AvgDialog_18998_Content_84 = {
    Text = "La bambina pronuncia parole agghiaccianti con un volto inespressivo."
  },
  AvgDialog_18998_Content_85 = {Text = "..."},
  AvgDialog_18998_Content_86 = {
    Text = "...Il giorno del <Yellow:Rito>, sarai trattenuta vicino all'<Yellow:Altare>."
  },
  AvgDialog_18998_Content_87 = {
    Text = "Non so perché tu sia ancora cosciente, ma fingi di essere svenuta.\nTi metterò il più vicino possibile al bordo della vasca."
  },
  AvgDialog_18998_Content_88 = {
    Text = "Quando saranno tutti usciti, indossa una veste e sgattaiola fuori dal Sentiero a nord dell'Altare."
  },
  AvgDialog_18998_Content_89 = {
    Text = "Corri più veloce che puoi e non tornare indietro.\nSe ti catturano, non posso aiutarti."
  },
  AvgDialog_18998_Content_9 = {
    Text = "Per le cose su cui non ho ancora le idee chiare, le {Male=sue,Female=sue} opinioni potrebbero influenzarmi."
  },
  AvgDialog_19001_Content_1 = {
    Text = "Hmph! Sei forte, ma la mamma di Lisa mi ha insegnato che l'astuzia può sconfiggere nemici ben più forti di te!"
  },
  AvgDialog_19001_Content_2 = {
    Text = "Li attireremo lontano e li abbatteremo uno alla volta!"
  },
  AvgDialog_19001_Content_3 = {
    Text = "Sissignore!"
  },
  AvgDialog_19002_Content_1 = {
    Text = "Buon Viaggio"
  },
  AvgDialog_19002_Content_10 = {
    Text = [[
Piuttosto protettiva, vero, ragazza?
Il vecchio Dexter ti ha detto qualcosa su di me?]]
  },
  AvgDialog_19002_Content_11 = {
    Text = "Un lampo di disapprovazione attraversa le guance pallide di Ramona, ma Daffodil non le dà il tempo di ribattere, agitando una mano in segno di congedo per mandarvi per la vostra strada."
  },
  AvgDialog_19002_Content_12 = {
    Text = "D'accordo, a quanto pare non sono la benvenuta qui.\nNon vi tratterrò oltre dal vostro viaggio."
  },
  AvgDialog_19002_Content_13 = {
    Text = "Buon Viaggio."
  },
  AvgDialog_19002_Content_14 = {
    Text = "Mi pareva di averti detto di non chiamare questo numero se non è urgente."
  },
  AvgDialog_19002_Content_15 = {
    Text = [[
Come potrei dimenticare i tuoi ordini perentori?
Non vuoi sentire che notizie ti ho portato?]]
  },
  AvgDialog_19002_Content_16 = {
    Text = "I movimenti di chi?"
  },
  AvgDialog_19002_Content_17 = {
    Text = "Università di Mythag. Il loro Custode sta tracciando \"quello grosso.\""
  },
  AvgDialog_19002_Content_18 = {Text = "..."},
  AvgDialog_19002_Content_19 = {
    Text = [[
Sembra che tu stia per perdere un altro pezzo sulla tua scacchiera.
Deve bruciare per un maestro stratega come <Blue:Herbert>, no?]]
  },
  AvgDialog_19002_Content_2 = {
    Text = "Sembra che siate pronti per il viaggio."
  },
  AvgDialog_19002_Content_20 = {
    Text = "Mi lusinga, signora. Sotto lo sguardo di quell'essere, siamo mere formiche — ben lungi dall'essere strateghi. Dove si trovano adesso?"
  },
  AvgDialog_19002_Content_21 = {
    Text = [[
Lo scoprirai abbastanza presto.
A proposito, quel "cavaliere" che hai mandato a intercettarli? Non la scelta migliore.]]
  },
  AvgDialog_19002_Content_22 = {
    Text = "Un bruto spericolato come quello non farà che sbattere contro un muro con l'Università di Mythag."
  },
  AvgDialog_19002_Content_23 = {
    Text = "Solo <Blue:spazzatura scaricata dai Portatori di Luce>. Se è inutile, pazienza."
  },
  AvgDialog_19002_Content_24 = {
    Text = "È tutto perché Rogers è scomparso, lasciandomi con grattacapi in più."
  },
  AvgDialog_19002_Content_25 = {
    Text = "Non preoccuparti, ci sono io.\nAl giusto prezzo, la bottega delle soluzioni di Daffodil risolverà tutti i tuoi problemi."
  },
  AvgDialog_19002_Content_26 = {
    Text = "<Shake:Coff, coff>... Dobbiamo davvero usare questo aggeggio?"
  },
  AvgDialog_19002_Content_27 = {
    Text = "Questa metropolitana... puzza terribilmente."
  },
  AvgDialog_19002_Content_28 = {
    Text = "Nel vagone rumoroso della metropolitana, alcuni passeggeri leggono <Italic:The Isis Times> sotto luci fioche, mentre altri tirano boccate dalle pipe, esalando nuvole di fumo."
  },
  AvgDialog_19002_Content_29 = {
    Text = "Il fetore di sudore umano, tabacco e benzina pesante si mescola in un odore peculiare e putrido."
  },
  AvgDialog_19002_Content_3 = {
    Text = "Grazie per l'\"ospitalità\" che ci avete riservato."
  },
  AvgDialog_19002_Content_30 = {
    Text = "Lanci un'occhiata a Lily vicino al finestrino. Studia con curiosità i passeggeri, i sedili e i corrimano, silenziosa come una bambola, come se vedesse questo mondo strano per la prima volta."
  },
  AvgDialog_19002_Content_31 = {
    Text = "Avremmo potuto prendere il trasporto privato della scuola, ma no, la vizi con questo rottame. Non la stai viziando troppo?"
  },
  AvgDialog_19002_Content_32 = {
    Text = "Provare cose nuove non è divertente? Credo che questa esperienza sia piuttosto rara."
  },
  AvgDialog_19002_Content_33 = {
    Text = "Qualche idea sulla nostra prossima mossa, Custode?"
  },
  AvgDialog_19002_Content_34 = {
    Text = "Considerando che lo <Yellow:sguardo> che abbiamo percepito durante lo scontro con Herbert proveniva molto probabilmente dal vero Segugio infernale, restare in città è la scelta più sicura."
  },
  AvgDialog_19002_Content_35 = {
    Text = "Ma c'è un altro sentiero: scortare Lily al Sanatorio di Rye e indagare su Francis."
  },
  AvgDialog_19002_Content_36 = {
    Text = "Sembra essere più di quel che appare."
  },
  AvgDialog_19002_Content_37 = {
    Text = "Che restiamo in città o ci dirigiamo al sanatorio, dobbiamo stare attenti alle ingerenze di Daffodil.\nLa sua presenza a Rye in questo frangente non è una coincidenza."
  },
  AvgDialog_19002_Content_38 = {
    Text = "È improbabile che interferisca direttamente.\nDa quel che so, solo le questioni legate alle sue collezioni suscitano il suo interesse."
  },
  AvgDialog_19002_Content_39 = {
    Text = "\"Improbabile\"?"
  },
  AvgDialog_19002_Content_4 = {
    Text = "Mia dolce bambina. Stai attenta, là fuori."
  },
  AvgDialog_19002_Content_40 = {
    Text = "Haha, ti ho inviato le informazioni sul Sanatorio. Assicurati di controllarle, d'accordo?"
  },
  AvgDialog_19002_Content_41 = {
    Text = "Grazie per aver inviato informazioni che Erica avrebbe potuto trasmettere da sola, Professor Dexter.\nSe non c'è altro, chiudo la comunicazione."
  },
  AvgDialog_19002_Content_42 = {
    Text = [[
Aspetta.
Dopo che hai richiesto quei documenti, ho esaminato le informazioni note sul sanatorio.]]
  },
  AvgDialog_19002_Content_43 = {
    Text = "Avete trovato qualcosa?"
  },
  AvgDialog_19002_Content_44 = {
    Text = "Nei casi di persone scomparse a Rye, le vittime avevano tutte parenti anziani o malati di mente, e tre di loro avevano personalmente affidato dei familiari al Sanatorio di Rye."
  },
  AvgDialog_19002_Content_45 = {
    Text = "Altri potrebbero aver fatto lo stesso, senza lasciare traccia."
  },
  AvgDialog_19002_Content_46 = {
    Text = "Forse per inesperienza, la polizia locale ha registrato il dato ma non ha indagato sullo schema."
  },
  AvgDialog_19002_Content_47 = {
    Text = "Direi che sono prove fragili. Vivi abbastanza a lungo, e chi non ha un parente malato o due?"
  },
  AvgDialog_19002_Content_48 = {
    Text = "Resta comunque l'unica pista che abbiamo, per ora."
  },
  AvgDialog_19002_Content_49 = {
    Text = "Terrò d'occhio queste possibilità."
  },
  AvgDialog_19002_Content_5 = {
    Text = "Daffodil sorride, squadrandoti, poi si avvicina al tuo orecchio."
  },
  AvgDialog_19002_Content_50 = {
    Text = "In tal caso, buonanotte.\nMi verserò un bicchiere di rosso della Cantina Chaplin e assaporerò l'aroma di casa—"
  },
  AvgDialog_19002_Content_51 = {
    Text = "Ramona interrompe le comunicazioni."
  },
  AvgDialog_19002_Content_52 = {
    Text = "Domani mattina ci dirigeremo al <Blue:Sanatorio di Rye>."
  },
  AvgDialog_19002_Content_53 = {
    Text = "Dopodiché, Francis è partita con il suo assistente nel cuore della notte, lasciando a te la responsabilità di scortare Lily al Sanatorio di Rye."
  },
  AvgDialog_19002_Content_54 = {
    Text = "Su richiesta di Lily, hai scelto di prendere la metropolitana verso la periferia remota."
  },
  AvgDialog_19002_Content_55 = {
    Text = [[
Un lieve movimento ti strappa dalle tue fantasticherie.
Abbassando lo sguardo, la ragazzina dall'aspetto di bambola stringe l'orlo dei tuoi vestiti.]]
  },
  AvgDialog_19002_Content_56 = {
    Text = "%player%..."
  },
  AvgDialog_19002_Content_57 = {
    Text = "Se una bambina fosse stata cattiva, non avesse ascoltato la sua mamma, e fosse successo qualcosa di brutto... la sua mamma sarebbe così arrabbiata da non volerla mai più vedere?"
  },
  AvgDialog_19002_Content_58 = {
    Text = "Essere vivaci è nella natura di un bambino. La sua mamma capirebbe."
  },
  AvgDialog_19002_Content_59 = {
    Text = "Ma... e se quella brutta cosa l'avesse cambiata?\nL'avesse resa così diversa che la sua mamma non potrebbe riconoscerla..."
  },
  AvgDialog_19002_Content_6 = {
    Text = "<Yellow:Non dimenticare, hai già visto il \"Segugio infernale\" una volta.>"
  },
  AvgDialog_19002_Content_60 = {
    Text = "Non sarebbe meglio non tornare a casa?\nLa sua mamma sarebbe così arrabbiata, così triste..."
  },
  AvgDialog_19002_Content_61 = {
    Text = "Sai che sta parlando di Lisa."
  },
  AvgDialog_19002_Content_62 = {
    Text = "Lisa, così com'è ora, potrebbe non tornare mai più al fianco di sua madre, sopravvivendo solo come \"Koum.\""
  },
  AvgDialog_19002_Content_63 = {
    Text = "Le tue memorie iniziano con l'esplosione di Yakutsk un anno fa. Non puoi offrire a Lily una risposta adeguata sulla famiglia o sulle madri, ma se si tratta solo di confortarla..."
  },
  AvgDialog_19002_Content_64 = {
    Text = "Una madre non abbandona la propria figlia."
  },
  AvgDialog_19002_Content_65 = {
    Text = "Dicono che l'amore di una madre sia il più indulgente al mondo."
  },
  AvgDialog_19002_Content_66 = {
    Text = "Non importa cosa diventi un figlio: se sa che è suo, lo abbraccerà."
  },
  AvgDialog_19002_Content_67 = {
    Text = "Una madre vuole che la propria figlia sia al sicuro."
  },
  AvgDialog_19002_Content_68 = {
    Text = "I Fanciulli crescono, forgiano il proprio cammino, e talvolta devono separarsi dai genitori."
  },
  AvgDialog_19002_Content_69 = {
    Text = "Alcune madri sperano che il proprio figlio diventi un Mercante, altre uno studioso, o un avventuriero."
  },
  AvgDialog_19002_Content_7 = {
    Text = "La sua voce, inquietante e criptica, ti fa scorrere un brivido lungo la schiena."
  },
  AvgDialog_19002_Content_70 = {
    Text = "Qualunque siano le loro scelte, una Madre li benedirà e pregherà per la loro incolumità."
  },
  AvgDialog_19002_Content_71 = {
    Text = "Chiudi gli occhi, e nella tua mente balena la sagoma di una figura che precipita da una torre dell'Orologio."
  },
  AvgDialog_19002_Content_72 = {
    Text = "La vita non segue sempre un percorso prestabilito.\nSe sbagli, rimedi; se non sbagli, vivi più felice."
  },
  AvgDialog_19002_Content_73 = {
    Text = "Durante i miei viaggi con Ramona, incontrammo una ragazza... aveva rinunciato a tutto ciò che aveva, cercando di rimediare."
  },
  AvgDialog_19002_Content_74 = {
    Text = "Ramona è al tuo fianco, la luce nei Suoi Occhi tremola, ma non interviene."
  },
  AvgDialog_19002_Content_75 = {
    Text = "Credeva che la sua morte avrebbe cancellato il suo peccato, ma invece ha causato ai suoi amici tanto dolore. Se persino gli amici provavano questo, quanto più dolore avrà provato sua madre?"
  },
  AvgDialog_19002_Content_76 = {
    Text = "Lily ascolta, il capo affondato tra le braccia, persa nei suoi pensieri, forse trovando le tue parole troppo oscure."
  },
  AvgDialog_19002_Content_77 = {
    Text = "Il treno sobbalza violentemente, seguito da un Coro di urla."
  },
  AvgDialog_19002_Content_78 = {
    Text = "Nel Caos, un fruscio proviene dal basso. Abbassando lo sguardo, gli occhi di Lily vacillano, una piccola mano aggrappata con forza al tuo lembo."
  },
  AvgDialog_19002_Content_79 = {Text = "È qui."},
  AvgDialog_19002_Content_8 = {
    Text = "Ramona ti tira indietro con delicatezza, parlando con cortese riserbo."
  },
  AvgDialog_19002_Content_80 = {
    Text = [[
Probabilmente vengono per noi.
Custode, Lotan, preparatevi alla battaglia!]]
  },
  AvgDialog_19002_Content_9 = {
    Text = "Grazie per la vostra preoccupazione.\nSe avete altre questioni, contattate il Professor Dexter. Lui ce le riferirà."
  },
  AvgDialog_19003_Content_1 = {
    Text = "Ti affretti a raggiungere Lotan."
  },
  AvgDialog_19003_Content_2 = {
    Text = "Io sono la creazione primordiale, l'antico leviatano, la marea dell'Abisso, l'anima dell'Eden, il dio della rovina e dell'ordine, vincolato alla volontà di questo Pianeta, e pretendo alloggio qui!"
  },
  AvgDialog_19003_Content_3 = {
    Text = "Questo posto è troppo piccolo per gente come voi!\nC'è un sanatorio fuori città—tanto spazio là, fa proprio al caso vostro!"
  },
  AvgDialog_19003_Content_4 = {
    Text = "Insolente—"
  },
  AvgDialog_19003_Content_5 = {
    Text = "Aspetta, Lotan..."
  },
  AvgDialog_19003_Content_6 = {
    Text = "Basta chiacchiere! Oggi insegno l'educazione a questo maleducato! Prova a vincolarmi di nuovo con quella Chiave, se ne hai il coraggio!"
  },
  AvgDialog_19005_Content_1 = {
    Text = "Una cattiva notizia e una buona notizia."
  },
  AvgDialog_19005_Content_2 = {
    Text = "Cattiva notizia: quell'uomo è sgattaiolato via nel caos."
  },
  AvgDialog_19005_Content_3 = {
    Text = "Buone notizie: il lato positivo è che a Lotan non mancheranno avversari degni."
  },
  AvgDialog_19005_Content_4 = {
    Text = "È fuggito così in fretta che non ho nemmeno avuto il tempo di scaldarmi."
  },
  AvgDialog_19005_Content_5 = {
    Text = "Aspetta, ho un piano."
  },
  AvgDialog_19005_Content_6 = {
    Text = [[
Attivi la Chiave d'argento, i cui bagliori stellati ti guidano alla sorgente dell'Aliemus.
Lanciando uno sguardo in quella direzione, scorgi un'ombra nera guizzare via.]]
  },
  AvgDialog_19005_Content_7 = {
    Text = "Da quella parte — andiamo!"
  },
  AvgDialog_19007_Content_1 = {
    Text = "Puoi aprirli adesso."
  },
  AvgDialog_19007_Content_2 = {
    Text = "Questo luogo..."
  },
  AvgDialog_19007_Content_3 = {
    Text = "Un Passaggio dimensionale. Stiamo seguendo le impronte di Daffodil."
  },
  AvgDialog_19009_Content_1 = {
    Text = "Asso nella Manica"
  },
  AvgDialog_19009_Content_10 = {
    Text = "Così sembri ancora più losco..."
  },
  AvgDialog_19009_Content_11 = {
    Text = "Dai, proprio come una bestia stupida non resiste all'odore del sangue, i marmocchi umani non sanno dire di no alle caramelle."
  },
  AvgDialog_19009_Content_12 = {
    Text = "Quella metafora è...\nAspetta, c'è qualcosa fuori."
  },
  AvgDialog_19009_Content_13 = {
    Text = "Hm? Cos'è quel rumore?"
  },
  AvgDialog_19009_Content_14 = {
    Text = "L'hai sentito anche tu, vero? Ti dispiace andare a controllare?"
  },
  AvgDialog_19009_Content_15 = {
    Text = "Ehi, vedo che stai cercando di liberarti di me—"
  },
  AvgDialog_19009_Content_16 = {
    Text = "%player%, tu non sei senza cuore come lei, vero?"
  },
  AvgDialog_19009_Content_17 = {
    Text = "Lascia fare a me e Ramona."
  },
  AvgDialog_19009_Content_18 = {
    Text = "Fidati, siamo esperti nel parlare con i bambini."
  },
  AvgDialog_19009_Content_19 = {
    Text = "Ramona lascia sfuggire un lieve sospiro."
  },
  AvgDialog_19009_Content_2 = {
    Text = [[
Tutto nel negozio sembra normale. Voi tre siete seduti in fila, di fronte alla piccola Lily.
La scena sembra quasi un interrogatorio...]]
  },
  AvgDialog_19009_Content_20 = {
    Text = "Il rumore fuori si fa più forte."
  },
  AvgDialog_19009_Content_21 = {
    Text = "Faresti meglio ad andare a controllare, Lotan. Lascia le piccole faccende a me e Ramona."
  },
  AvgDialog_19009_Content_22 = {
    Text = "Tch, spilorcio."
  },
  AvgDialog_19009_Content_23 = {
    Text = "Lotan esce a grandi passi dalla stanza, lo sguardo ansioso di Lily che la segue."
  },
  AvgDialog_19009_Content_24 = {
    Text = "La signora spaventosa se n'è andata. Possiamo rilassarci un po', vero, Lily?"
  },
  AvgDialog_19009_Content_25 = {
    Text = "La bambina sbatte le palpebre, come se si stesse davvero tranquillizzando — o forse senza afferrare affatto la situazione."
  },
  AvgDialog_19009_Content_26 = {
    Text = "Tu sai dov'è Lisa, vero?"
  },
  AvgDialog_19009_Content_27 = {
    Text = "Lily annuisce, poi scuote la testa."
  },
  AvgDialog_19009_Content_28 = {
    Text = [[
Puoi dircelo?
Non preoccuparti, ci siamo solo io e %player% qui. Manterremo il segreto e ti proteggeremo.]]
  },
  AvgDialog_19009_Content_29 = {
    Text = "Non posso, perché... degli <Yellow:occhi> osservano sempre Lily..."
  },
  AvgDialog_19009_Content_3 = {
    Text = "Lily si agita a disagio, lo sguardo che guizza verso la finestra."
  },
  AvgDialog_19009_Content_30 = {Text = "Occhi?"},
  AvgDialog_19009_Content_31 = {
    Text = "Hmm, tanti, tantissimi occhi, da <Yellow:altre Dimensioni>..."
  },
  AvgDialog_19009_Content_32 = {
    Text = "Dimensioni? Sai cosa significano le dimensioni, Lily?"
  },
  AvgDialog_19009_Content_33 = {
    Text = "Lily improvvisamente serra le labbra, senza dire nulla, gli occhi che guizzano nervosamente verso la finestra."
  },
  AvgDialog_19009_Content_34 = {
    Text = "%player%, c'è qualcosa là fuori."
  },
  AvgDialog_19009_Content_35 = {
    Text = "...Come, mandi via anche me?"
  },
  AvgDialog_19009_Content_36 = {Text = "No—"},
  AvgDialog_19009_Content_37 = {
    Text = "Roar———"
  },
  AvgDialog_19009_Content_38 = {
    Text = "Sta succedendo davvero qualcosa là fuori!"
  },
  AvgDialog_19009_Content_39 = {
    Text = "Lotan! Cosa sta succedendo?"
  },
  AvgDialog_19009_Content_4 = {
    Text = "Proprio mentre stai per dire qualcosa per alleggerire l'aria opprimente, Lotan parla per primo."
  },
  AvgDialog_19009_Content_40 = {
    Text = "State indietro, ci penso io!"
  },
  AvgDialog_19009_Content_5 = {
    Text = "Ehi, tu sai dove è andata Lisa, vero?"
  },
  AvgDialog_19009_Content_6 = {
    Text = "Non preoccuparti, siamo gente ragionevole. Non ti daremo la caccia come quella vecchia pazza finché non avremo il quadro completo."
  },
  AvgDialog_19009_Content_7 = {
    Text = "Se rivelassi dove si trova Lisa, quella bella signora laggiù potrebbe darti qualche caramella come ricompensa."
  },
  AvgDialog_19009_Content_8 = {
    Text = "Lotan, la stai spaventando."
  },
  AvgDialog_19009_Content_9 = {
    Text = "Spaventarla? Io? Sono la sorellona più dolce che ci sia, non è vero?"
  },
  AvgDialog_19013_Content_1 = {
    Text = "La Corrente ti Guiderà"
  },
  AvgDialog_19013_Content_10 = {
    Text = "Koum, non avere paura."
  },
  AvgDialog_19013_Content_11 = {
    Text = "Gli animali hanno i sensi acuti. Loro — e quella cosa — devono percepire qualcosa."
  },
  AvgDialog_19013_Content_12 = {
    Text = "Uno stridio gutturale e rauco squarcia l'oscurità,\ncome se le corde vocali si fossero lacerate, la gola soffocata dal pus."
  },
  AvgDialog_19013_Content_13 = {
    Text = "...Perché... abbandonare..."
  },
  AvgDialog_19013_Content_14 = {
    Text = "Lily alza una mano, indicando nel buio.\nPercepisci vagamente che è la fonte del suono."
  },
  AvgDialog_19013_Content_2 = {
    Text = [[
Il Ponte d'Acciaio Fowlers si stende sul fiume a mezzanotte,
i suoi montanti d'acciaio come corde d'arpa, tessono una nenia nel vento spettrale della notte.]]
  },
  AvgDialog_19013_Content_3 = {
    Text = "L'oscurità inghiotte tutto, un'ombra profonda. Koum guaisce all'estremità buia del ponte, dove la luce dei lampioni tremola ambiguamente."
  },
  AvgDialog_19013_Content_4 = {
    Text = "...Qualcosa non va."
  },
  AvgDialog_19013_Content_5 = {
    Text = "Lo sento anch'io, ma non riesco a capire cosa ci sia di sbagliato."
  },
  AvgDialog_19013_Content_6 = {
    Text = "Non è ovvio?\nRiesci a sentire qualche animale?"
  },
  AvgDialog_19013_Content_7 = {
    Text = [[
Nessuno.
Silenzio assoluto, non un suono.]]
  },
  AvgDialog_19013_Content_8 = {
    Text = "Anche trattenendo il respiro e chiudendo gli occhi per ascoltare, cogli soltanto il fruscio del vento e un ululato lontano dall'oscurità remota, troppo flebile per capire se sia reale."
  },
  AvgDialog_19013_Content_9 = {
    Text = "Koum sbuffa inquieto."
  },
  AvgDialog_19014_Content_1 = {
    Text = "Tch, ci sei andata piano con me, vero? Patetico."
  },
  AvgDialog_19014_Content_10 = {
    Text = "La comunicazione si interrompe bruscamente."
  },
  AvgDialog_19014_Content_11 = {
    Text = "Ai margini del tuo campo visivo appare una creatura—un gatto glabro dalle orecchie lunghe, o meglio, due.\nLe sue teste gemelle, fittamente cucite insieme, condividono un corpo elegante e aggraziato."
  },
  AvgDialog_19014_Content_12 = {
    Text = "Balza agilmente sulla spalla di un uomo trasandato con un occhio solo."
  },
  AvgDialog_19014_Content_13 = {
    Text = "Che incontro fatale.\nIl chiaro di luna stasera è piuttosto splendido, non trovi?"
  },
  AvgDialog_19014_Content_14 = {
    Text = "Saluti, amici dell'Università di Mythag."
  },
  AvgDialog_19014_Content_2 = {
    Text = "Le indagini sulla Dissoluzione non sono un incontro di pugilato, Lotan. Se sudare è l'unica cura per il tuo deficit d'attenzione, ti consiglio di prenotare una seduta con Sylvia per un consulto."
  },
  AvgDialog_19014_Content_3 = {
    Text = "Ramona, riferisci i tuoi valori di osservazione sull'anomalia."
  },
  AvgDialog_19014_Content_4 = {
    Text = "Sì. Ho osservato Pustole viscose nella Dimensione del Dominio, di circa 50 centimetri di diametro. Quando perforate, trasudano melma nera con un bagliore verdastro, prima di dissolversi naturalmente."
  },
  AvgDialog_19014_Content_5 = {
    Text = "Non vi è menzione di tali Pustole nei registri relativi a \"Cerbero.\""
  },
  AvgDialog_19014_Content_6 = {
    Text = "...È un Risvegliatore."
  },
  AvgDialog_19014_Content_7 = {
    Text = [[
Custode, Ramona.
Ascolta bene: devi fare attenzione a un uomo con un monocolo meccanico.]]
  },
  AvgDialog_19014_Content_8 = {
    Text = "I tuoi ripetuti scontri con l'Associazione degli Scultori ti hanno sicuramente messo nel suo mirino."
  },
  AvgDialog_19014_Content_9 = {
    Text = "Potrebbe non affrontarti direttamente, ma... <Shake:@1@2...>"
  },
  AvgDialog_19015_Content_1 = {
    Text = "Ieri, Ancora"
  },
  AvgDialog_19015_Content_10 = {
    Text = "Forse, scoprendo la verità, si perderà nella domanda \"chi sono io\"...\nL'ho visto accadere innumerevoli volte nel corso dei millenni."
  },
  AvgDialog_19015_Content_11 = {
    Text = "Cosa rappresenta per te?"
  },
  AvgDialog_19015_Content_12 = {
    Text = "È umana, una mia compagna di classe."
  },
  AvgDialog_19015_Content_13 = {
    Text = "Sa combattere al mio fianco, come una Risvegliatrice."
  },
  AvgDialog_19015_Content_14 = {
    Text = "Cosa sia non ha importanza."
  },
  AvgDialog_19015_Content_15 = {
    Text = "Prima che tu possa aggiungere altro, una voce familiare ti interrompe."
  },
  AvgDialog_19015_Content_16 = {
    Text = "Sono tornata, %player%, Lotan."
  },
  AvgDialog_19015_Content_17 = {
    Text = "...Che succede? Perché mi fissate così? Ho qualcosa in faccia?"
  },
  AvgDialog_19015_Content_18 = {
    Text = "No, niente."
  },
  AvgDialog_19015_Content_19 = {
    Text = "Bentornata."
  },
  AvgDialog_19015_Content_2 = {
    Text = [[
Strisciare, strisciare. Strisciare senza fine.
Gamebe prive di forza strisciano sul terreno, un mondo sfocato riflesso in una retina devastata.]]
  },
  AvgDialog_19015_Content_20 = {Text = "..."},
  AvgDialog_19015_Content_21 = {
    Text = "Ho una buona notizia e una cattiva."
  },
  AvgDialog_19015_Content_22 = {
    Text = "Buone notizie: l'università ha approvato il nostro piano di scortare prima Lily da sua madre."
  },
  AvgDialog_19015_Content_23 = {
    Text = "Cattive notizie: William ha avvistato strane figure che tenevano d'occhio il sanatorio."
  },
  AvgDialog_19015_Content_24 = {
    Text = "Se il mio istinto non sbaglia... si aggirano intorno a noi proprio adesso."
  },
  AvgDialog_19015_Content_3 = {
    Text = [[
Questo strisciare dura da quasi venti ore.
Il suo corpo, reciso dalla fonte spirituale, si decompone, le sue forze sull'orlo del collasso.]]
  },
  AvgDialog_19015_Content_4 = {
    Text = "Prima di sprofondare nell'oscurità eterna, deve trovare quella persona—"
  },
  AvgDialog_19015_Content_5 = {
    Text = "L'hai mandata via tu stessa, eppure ora sei tutta agitata.\nGli umani sono sempre così... disonesti."
  },
  AvgDialog_19015_Content_6 = {
    Text = "Non so quale verità ascolterà né quale scelta farà."
  },
  AvgDialog_19015_Content_7 = {
    Text = "...L'ho guardata crescere da bambina che muoveva i primi passi fino a ciò che è ora. Non è una Risvegliatrice, ma... nemmeno umana."
  },
  AvgDialog_19015_Content_8 = {
    Text = "Nessun essere umano ordinario potrebbe disporre di simili capacità di combattimento."
  },
  AvgDialog_19015_Content_9 = {
    Text = "Dexter e i suoi hanno nascosto bene le sue origini, arrivando persino a sigillare la Pozza nera. Non solo per proteggere Mythag, ma per proteggere lei."
  },
  AvgDialog_19016_Content_1 = {
    Text = "Spina nel Fianco"
  },
  AvgDialog_19016_Content_10 = {
    Text = "Poi si volta verso di te."
  },
  AvgDialog_19016_Content_100 = {
    Text = "...Proprio giù per questo pendio..."
  },
  AvgDialog_19016_Content_101 = {Text = "!"},
  AvgDialog_19016_Content_102 = {
    Text = "La neve soffice cede sotto i tuoi piedi mentre perdi i sensi."
  },
  AvgDialog_19016_Content_11 = {
    Text = "Questi devono essere i nuovi amici di cui parlavi, Lily?"
  },
  AvgDialog_19016_Content_12 = {
    Text = "Francis annuisce tra sé."
  },
  AvgDialog_19016_Content_13 = {
    Text = "Salve, sono la madre di Lily. Chiamatemi pure Francis."
  },
  AvgDialog_19016_Content_14 = {
    Text = "Questa è la mia assistente, <Blue:Nymphaea>."
  },
  AvgDialog_19016_Content_15 = {
    Text = "Buonasera. Sono Nymphaea Polones, ma vi prego, chiamatemi Nymphaea."
  },
  AvgDialog_19016_Content_16 = {
    Text = "Ho saputo dell'accaduto da Daffodil.\nSono una dottoressa dell'<Blue:Ospedale di Lai>. Lily viveva lì con me."
  },
  AvgDialog_19016_Content_17 = {
    Text = "Non volevo che Lily restasse troppo a lungo in quell'ambiente, così l'ho mandata temporaneamente in città. Non mi aspettavo che avrebbe faticato così tanto ad adattarsi al mondo esterno."
  },
  AvgDialog_19016_Content_18 = {
    Text = [[
Mi scuso profondamente per tutti i problemi che Lily vi ha causato.
Come madre inadeguata, vi chiedo perdono.]]
  },
  AvgDialog_19016_Content_19 = {
    Text = "Se non fosse per l'atteggiamento ancora diffidente di Koum, sembrerebbe una madre qualunque, un po' severa ma gentile."
  },
  AvgDialog_19016_Content_2 = {
    Text = "Un lieve bussare riecheggia alla porta. Nel silenzio della notte, quel battito ritmico vi invia un brivido inspiegabile lungo la schiena."
  },
  AvgDialog_19016_Content_20 = {
    Text = "Non c'è bisogno di dirlo. Lily è stata dolcissima."
  },
  AvgDialog_19016_Content_21 = {
    Text = "Va molto d'accordo anche con %player%."
  },
  AvgDialog_19016_Content_22 = {
    Text = "Spero di poter ricambiare, un giorno."
  },
  AvgDialog_19016_Content_23 = {
    Text = "Sembra che tu stia già andando via?"
  },
  AvgDialog_19016_Content_24 = {
    Text = "Sai che non posso restare la notte senza Nymphaea."
  },
  AvgDialog_19016_Content_25 = {
    Text = "E... fuggire non è una soluzione. Devo parlare con <Yellow:quella persona>."
  },
  AvgDialog_19016_Content_26 = {
    Text = "Direttrice Oswood, potrei forse alleggerire il suo fardello in questa faccenda?"
  },
  AvgDialog_19016_Content_27 = {
    Text = [[
No, Nymphaea, non hai bisogno di immischiarti nei miei affari.
Le decisioni che ho preso, devo portarle a termine io stessa.]]
  },
  AvgDialog_19016_Content_28 = {
    Text = "Allora le sconsiglierei di portare Lily con sé, specialmente in queste notti."
  },
  AvgDialog_19016_Content_29 = {
    Text = "Ecco una proposta vantaggiosa per tutti: lei si occupi delle sue faccende, e lasci la scorta di Lily a questi amici. Che ne dice?"
  },
  AvgDialog_19016_Content_3 = {Text = "Ssssh—"},
  AvgDialog_19016_Content_30 = {
    Text = "Non sarebbe giusto. Lily ha già causato loro abbastanza problemi."
  },
  AvgDialog_19016_Content_31 = {
    Text = [[
Daffodil ti lancia un'occhiata.
Sembra che questa sia la tua "risposta".]]
  },
  AvgDialog_19016_Content_32 = {
    Text = "Siamo felici di trascorrere del tempo con Lily."
  },
  AvgDialog_19016_Content_33 = {
    Text = "Se è così... ve la affido."
  },
  AvgDialog_19016_Content_34 = {
    Text = "Per favore, portate Lily a casa, al Sanatorio Rye."
  },
  AvgDialog_19016_Content_35 = {
    Text = "23:00, Camera da letto al secondo piano"
  },
  AvgDialog_19016_Content_36 = {
    Text = "Erica, recupera tutti i dati disponibili sul Sanatorio di Rye."
  },
  AvgDialog_19016_Content_37 = {
    Text = "Il Sanatorio di Rye, situato in Lindsay Road nell'angolo sud-est di Rye, con dodici anni di storia. La sua attività principale è l'osservazione e la riabilitazione dei disturbi mentali, da cui il soprannome di manicomio."
  },
  AvgDialog_19016_Content_38 = {
    Text = "Direttrice attuale: Francis Oswood—"
  },
  AvgDialog_19016_Content_39 = {
    Text = "Salta i dettagli superficiali. Ci sono cartelle cliniche dei pazienti o informazioni sulle famiglie disponibili?"
  },
  AvgDialog_19016_Content_4 = {
    Text = "Koum inarca improvvisamente la schiena, assumendo una postura predatoria come una bestia messa all'angolo."
  },
  AvgDialog_19016_Content_40 = {
    Text = "Ricerca in corso, attendere prego...\nA causa del volume di dati, il completamento del recupero è stimato per le 8:00 di domattina."
  },
  AvgDialog_19016_Content_41 = {
    Text = "...Va bene, grazie, Erica.\nSembra che questo sia tutto ciò che possiamo fare per oggi."
  },
  AvgDialog_19016_Content_42 = {
    Text = "Ho la sensazione che questo caso sia solo all'inizio..."
  },
  AvgDialog_19016_Content_43 = {
    Text = "Mentre giaci a letto, la sonnolenza si insinua, e un'impressione nebulosa si agita nella tua mente."
  },
  AvgDialog_19016_Content_44 = {
    Text = "Forse stai per fare di nuovo quel <Yellow:sogno>..."
  },
  AvgDialog_19016_Content_45 = {
    Text = [[
Benvenuto nella <Blue:Spedizione di Elworth>.
Sono il caposquadra; potete chiamarmi <Blue:Bertrand>.]]
  },
  AvgDialog_19016_Content_46 = {
    Text = "Ho esaminato la tua candidatura. Francamente, ci siamo preparati per tre mesi e non dovremmo accettare non professionisti a questo punto."
  },
  AvgDialog_19016_Content_47 = {
    Text = "Ma questo viaggio è pericoloso, e il personale medico è indispensabile. Quindi, nonostante il tuo breve addestramento, ti diamo il benvenuto nella conquista di <Blue:Elworth>."
  },
  AvgDialog_19016_Content_48 = {
    Text = "Se doveste sentirvi male in qualsiasi momento, segnalatelo immediatamente. Per sicurezza, invieremo un segnale di soccorso e vi lasceremo scorte sufficienti in attesa dei soccorsi."
  },
  AvgDialog_19016_Content_49 = {
    Text = "Siate consapevoli che questo significa che potreste non completare la spedizione con noi.\nLa squadra onorerà il vostro contributo, ma il vostro nome non apparirà nel registro finale dei primi esploratori."
  },
  AvgDialog_19016_Content_5 = {
    Text = "Scusa se ti disturbo a quest'ora tarda."
  },
  AvgDialog_19016_Content_50 = {
    Text = "Bertrand, non essere così freddo. È disposta ad affrontare quelle terre selvagge ghiacciate con noi... non è già ammirevole?"
  },
  AvgDialog_19016_Content_51 = {
    Text = "...In condizioni estreme, il rischio di morte non è mai pari a zero.\nSe siete sicuri, fate parte della squadra."
  },
  AvgDialog_19016_Content_52 = {
    Text = "Sì, capisco."
  },
  AvgDialog_19016_Content_53 = {
    Text = "Quella è la vostra stanza. Durante l'addestramento, sveglia alle 6:00 per le esercitazioni mattutine. Non fate tardi."
  },
  AvgDialog_19016_Content_54 = {Text = "..."},
  AvgDialog_19016_Content_55 = {
    Text = "Ah, è da un'eternità che non avevamo un tempo così limpido! Guardate, si vedono le cime delle montagne in lontananza!"
  },
  AvgDialog_19016_Content_56 = {
    Text = "Il tempo è peggiore del previsto, e i nostri progressi in questi giorni sono stati scarsi.\nDobbiamo sfruttare questa rara giornata serena e avanzare il più velocemente possibile."
  },
  AvgDialog_19016_Content_57 = {
    Text = "E voi, siete il dottore... non crollate costringendo gli altri a prendersi cura di voi."
  },
  AvgDialog_19016_Content_58 = {
    Text = "Santo cielo, Bertrand, il bel tempo è una buona notizia. Non puoi pensare al morale della squadra?"
  },
  AvgDialog_19016_Content_59 = {
    Text = "...Non sono come voi nobili signore in cerca di emozioni. I soldati hanno dei doveri.\nNon tornerò indietro finché non avremo raggiunto quella vetta più alta."
  },
  AvgDialog_19016_Content_6 = {
    Text = "Koum si volta di scatto, graffiando il pavimento, la spina dorsale tesa, ringhiando minacciosamente."
  },
  AvgDialog_19016_Content_60 = {
    Text = [[
Cecily, sto bene.
Il Colonnello Bertrand ha ragione: affrettiamoci.]]
  },
  AvgDialog_19016_Content_61 = {Text = "..."},
  AvgDialog_19016_Content_62 = {
    Text = "Abbandonate parte delle scorte, spingendo i cani da slitta e i poni al massimo della velocità."
  },
  AvgDialog_19016_Content_63 = {
    Text = "Un'inquietudine si agita dentro di voi. Estraete un orologio da tasca da sotto accumuli di indumenti, sussurrando una preghiera."
  },
  AvgDialog_19016_Content_64 = {
    Text = "State guardando di nuovo il vostro orologio. È speciale?"
  },
  AvgDialog_19016_Content_65 = {
    Text = "Sì, l'ho comprato in un curioso negozio di antiquariato.\nCi tengo dentro la foto di mia figlia e una ciocca dei suoi capelli. Mi ricorda di lei."
  },
  AvgDialog_19016_Content_66 = {
    Text = "Oh, dovete avere una figlia adorabile. Vi invidio."
  },
  AvgDialog_19016_Content_67 = {
    Text = "Ahimè, vorrei avere anch'io un figlio. Quanti anni ha adesso?"
  },
  AvgDialog_19016_Content_68 = {
    Text = "...Aveva otto anni quando è venuta a mancare."
  },
  AvgDialog_19016_Content_69 = {
    Text = "Mi dispiace, non lo sapevo..."
  },
  AvgDialog_19016_Content_7 = {Text = "Madre..."},
  AvgDialog_19016_Content_70 = {
    Text = "È gestibile."
  },
  AvgDialog_19016_Content_71 = {
    Text = "Allora, perché ti sei unita a questa spedizione?"
  },
  AvgDialog_19016_Content_72 = {
    Text = "Oh, per via di una leggenda!"
  },
  AvgDialog_19016_Content_73 = {Text = "Leggenda?"},
  AvgDialog_19016_Content_74 = {
    Text = "Si dice che nella Catena Montuosa di Elworth vi sia una chiesa potente. Coloro che vi aderiscono ricevono una <Yellow:Benedizione>."
  },
  AvgDialog_19016_Content_75 = {
    Text = "Alcuni sostengono persino che la Benedizione possa riportare in vita i morti."
  },
  AvgDialog_19016_Content_76 = {
    Text = "Ma Elworth è così remota, le sue distese innevate per lo più mai calpestate da piede umano..."
  },
  AvgDialog_19016_Content_77 = {
    Text = "È questo che lo rende reale, non credi? Se non esercitasse un potere che trascende i mortali, sfidando la vita e la morte, perché costruirci una chiesa?"
  },
  AvgDialog_19016_Content_78 = {Text = "..."},
  AvgDialog_19016_Content_79 = {
    Text = [[
Scusa, mi sono lasciata trasportare?
...Non volevo ignorare i tuoi sentimenti...]]
  },
  AvgDialog_19016_Content_8 = {
    Text = "Ho sentito che c'è stata una novità, così sono accorsa. Lily e il nostro animale non hanno causato problemi alla signora, vero?"
  },
  AvgDialog_19016_Content_80 = {
    Text = "Se quella chiesa esiste, pregherò per te..."
  },
  AvgDialog_19016_Content_81 = {
    Text = "Per riportare tua figlia al tuo fianco."
  },
  AvgDialog_19016_Content_82 = {Text = "..."},
  AvgDialog_19016_Content_83 = {
    Text = [[
La valanga colpisce in un istante.
Prima che qualcuno possa reagire, il mondo trema, sprofondando in un terrificante bianco assoluto.]]
  },
  AvgDialog_19016_Content_84 = {
    Text = "Non sai quanto tempo sia passato quando il freddo che gela le ossa e il dolore ti risvegliano."
  },
  AvgDialog_19016_Content_85 = {
    Text = "La vista è offuscata. Le mani sono intorpidite.\nLe gambe non si muovono."
  },
  AvgDialog_19016_Content_86 = {
    Text = "Al limite del tuo campo visivo, sotto un cumulo di neve, sporge un braccio pallido."
  },
  AvgDialog_19016_Content_87 = {
    Text = "Ci vuole un'eternità per rialzarti barcollando.\nAvanzi a fatica verso la figura, trascinando a stento il corpo congelato e rigido fuori dalla neve."
  },
  AvgDialog_19016_Content_88 = {
    Text = "Quello è..."
  },
  AvgDialog_19016_Content_89 = {
    Text = "Dall'abbraccio gelido di Cecily cade un involto di carta cerata. Lo apri delicatamente, rivelando una mappa con dei segni, una foto in bianco e nero e una ciocca di capelli biondo chiaro."
  },
  AvgDialog_19016_Content_9 = {
    Text = "La donna che Lily chiama Madre spalanca la porta, dirigendosi dritta verso Lily. Avvolge la piccola figura tra le braccia, accarezzandole dolcemente la testa."
  },
  AvgDialog_19016_Content_90 = {
    Text = [[
La foto mostra Cecily con un uomo dai capelli chiari.
Sul retro, scritto: "Tornerai."]]
  },
  AvgDialog_19016_Content_91 = {
    Text = "Quindi anche tu... hai perso qualcuno di caro."
  },
  AvgDialog_19016_Content_92 = {
    Text = "Controlli la mappa. Se la valanga non ti ha trascinato troppo lontano, il luogo indicato dista meno di mezza giornata di cammino da qui."
  },
  AvgDialog_19016_Content_93 = {
    Text = "I poni sono scomparsi e le tue razioni non basteranno per una discesa."
  },
  AvgDialog_19016_Content_94 = {
    Text = "...Non c'è esitazione. Non hai mai pianificato di tornare vivo."
  },
  AvgDialog_19016_Content_95 = {Text = "..."},
  AvgDialog_19016_Content_96 = {Text = "..."},
  AvgDialog_19016_Content_97 = {Text = "..."},
  AvgDialog_19016_Content_98 = {
    Text = "Trascinando il corpo congelato di Cecily con una corda da arrampicata, avanzi a fatica nella neve, un passo pesante dopo l'altro."
  },
  AvgDialog_19016_Content_99 = {
    Text = "La fortuna è dalla tua parte: superi un lago ghiacciato, il che ti aiuta a individuare la tua posizione."
  },
  AvgDialog_19017_Content_1 = {
    Text = "Ritorno alla Genesi"
  },
  AvgDialog_19017_Content_10 = {
    Text = "Custode... Io..."
  },
  AvgDialog_19017_Content_11 = {
    Text = "Siamo compagni, camerati. Ciò che conta per te conta anche per me."
  },
  AvgDialog_19017_Content_12 = {
    Text = "Grazie... Tornerò."
  },
  AvgDialog_19017_Content_13 = {
    Text = [[
Sei tornata.
Ti avevo detto di ritirarti contro avversari troppo forti e di contenere la situazione, no?]]
  },
  AvgDialog_19017_Content_14 = {
    Text = [[
Herbert sbatte un giornale sul tavolo.
Il titolo strilla: <Italic:Incidente nella metropolitana di Londinium, sospetto attacco di un gruppo misterioso>.]]
  },
  AvgDialog_19017_Content_15 = {Text = "..."},
  AvgDialog_19017_Content_16 = {
    Text = "Helot resta rigido davanti alla scrivania di Herbert, silenzioso come una statua."
  },
  AvgDialog_19017_Content_17 = {
    Text = "Che fai lì impalato? Aspetti che ti serva focaccine e tè?"
  },
  AvgDialog_19017_Content_18 = {
    Text = "Il fascicolo. Dammelo."
  },
  AvgDialog_19017_Content_19 = {
    Text = "...Fascicolo?"
  },
  AvgDialog_19017_Content_2 = {
    Text = [[
Ramona, stai bene?
Sei inquieta da quando abbiamo lasciato Lady Daffodil.]]
  },
  AvgDialog_19017_Content_20 = {
    Text = [[
Quella donna, Daffodil.
Ha detto che avrebbe inviato il dossier.]]
  },
  AvgDialog_19017_Content_21 = {
    Text = "Sul volto di Herbert guizza un lampo di comprensione, poi torna rapidamente alla sua consueta calma."
  },
  AvgDialog_19017_Content_22 = {
    Text = "Oh, sai com'è — troppe relazioni universitarie che si accumulano nella cassetta della posta."
  },
  AvgDialog_19017_Content_23 = {
    Text = "Ne ho smaltite un bel po' prima; non ho idea se sia ancora lì..."
  },
  AvgDialog_19017_Content_24 = {
    Text = "Helot scruta la stanza, estraendo rapidamente un fascicolo dalla copertina lavanda da sotto il giornale."
  },
  AvgDialog_19017_Content_25 = {
    Text = "Lo scorre rapidamente e lo posa davanti a Herbert."
  },
  AvgDialog_19017_Content_26 = {
    Text = "Che significa tutto questo?"
  },
  AvgDialog_19017_Content_27 = {
    Text = "Herbert prende il dossier, lo sfoglia distrattamente e poi lo posa,\ncome se ne conoscesse già il contenuto a memoria."
  },
  AvgDialog_19017_Content_28 = {
    Text = "Cosa significa <Yellow:Fallimento>?"
  },
  AvgDialog_19017_Content_29 = {
    Text = "<Blue:Albino> mi ha detto che l'Associazione degli Scultori ha perso le forze di Rogers e Francis, perciò mi hanno mandato ad assisterti."
  },
  AvgDialog_19017_Content_3 = {
    Text = "Ah, scusa... dovrei concentrarmi sul compito che ho davanti..."
  },
  AvgDialog_19017_Content_30 = {
    Text = "Quindi, in verità, sono stata abbandonata?"
  },
  AvgDialog_19017_Content_31 = {
    Text = "È una lunga storia, legata a Francis."
  },
  AvgDialog_19017_Content_32 = {
    Text = "Sai che il <Yellow:Piano di Creazione Divina> dipende fortemente dal potere dei <Yellow:Gemelli>.\nDa quando Lily ha avuto un Risveglio anomalo, non sono mai riusciti a creare la tua altra metà..."
  },
  AvgDialog_19017_Content_33 = {
    Text = "Non mi interessano le spiegazioni!"
  },
  AvgDialog_19017_Content_34 = {
    Text = [[
<BigShake:RISPONDIMI!>
Sono stata abbandonata?!]]
  },
  AvgDialog_19017_Content_35 = {
    Text = "In termini di risultato, sì, ma..."
  },
  AvgDialog_19017_Content_36 = {
    Text = "Perché? Perché? Devo vedere la Signora!"
  },
  AvgDialog_19017_Content_37 = {
    Text = "Non provarci. Credi ancora di essere la nobile figlia adottiva del magistrato?"
  },
  AvgDialog_19017_Content_38 = {
    Text = "Il sangue corrotto può generare solo una <Blue:traditrice> come te."
  },
  AvgDialog_19017_Content_39 = {
    Text = "Non ho fatto nulla di sbagliato. Non ho tradito la Signora!"
  },
  AvgDialog_19017_Content_4 = {
    Text = "È solo che questa cosa mi tormenta da così tanto tempo, io... non riesco a non preoccuparmene."
  },
  AvgDialog_19017_Content_40 = {
    Text = "Hai dato del cibo a quel lurido stalliere, vero? Chi te l'ha permesso?"
  },
  AvgDialog_19017_Content_41 = {
    Text = "<Small:Quello era... mio padre biologico...>"
  },
  AvgDialog_19017_Content_42 = {
    Text = "Ingrata miserabile. La magistrata ti ha accolta come figlia, eppure ti aggrappi ai tuoi consanguinei criminali."
  },
  AvgDialog_19017_Content_43 = {
    Text = "La Signora ha detto che non ti libererai mai di quelle catene finché lei sarà in vita.\nRisparmiarti la vita è la sua clemenza per i vecchi tempi."
  },
  AvgDialog_19017_Content_44 = {Text = "..."},
  AvgDialog_19017_Content_45 = {Text = "..."},
  AvgDialog_19017_Content_46 = {
    Text = "Maledetti governanti."
  },
  AvgDialog_19017_Content_47 = {
    Text = "Brandire il potere per giocare con gli altri, richiamare e scartare a capriccio..."
  },
  AvgDialog_19017_Content_48 = {
    Text = "Elargire favori come tesori preziosi, per poi gettarli via come spazzatura."
  },
  AvgDialog_19017_Content_49 = {
    Text = "Vado a vedere <Blue:Eve>."
  },
  AvgDialog_19017_Content_5 = {
    Text = "Allora va' a occupartene adesso."
  },
  AvgDialog_19017_Content_50 = {
    Text = "È inutile."
  },
  AvgDialog_19017_Content_51 = {
    Text = "Allora troverò la <Yellow:bambina consanguinea> e la riporterò alla Chiesa!"
  },
  AvgDialog_19017_Content_52 = {
    Text = "Ma prima, devo vedere Eve."
  },
  AvgDialog_19017_Content_53 = {
    Text = "Se sei così decisa, non ti fermerò.\nEcco l'indirizzo della sede di Londinium della Chiesa della luce del tempio. Troverai Eve lì."
  },
  AvgDialog_19017_Content_54 = {
    Text = "Non posso garantire come reagirà."
  },
  AvgDialog_19017_Content_55 = {
    Text = "Non serve. Lo scoprirò da sola."
  },
  AvgDialog_19017_Content_56 = {
    Text = "Nell'istante in cui Helot si volta per andarsene, avverte qualcosa di anomalo."
  },
  AvgDialog_19017_Content_57 = {
    Text = "Il terreno si ammorbidisce, cede, i suoi passi vacillano."
  },
  AvgDialog_19017_Content_58 = {
    Text = "Abbassa lo sguardo."
  },
  AvgDialog_19017_Content_59 = {
    Text = "Non è il terreno che crolla—è lei.\nDove dovrebbero esserci le gambe, la carne si spacca come germogli che sbocciano, trasudando sfere molli e viscose."
  },
  AvgDialog_19017_Content_6 = {
    Text = "Ma la missione—"
  },
  AvgDialog_19017_Content_60 = {
    Text = "<Shake:Tu... perché... perché stai recidendo... il legame...>"
  },
  AvgDialog_19017_Content_61 = {
    Text = "Le sue parole vengono troncate dall'anomalia, la voce che svanisce dissolvendosi in un ruggito vuoto."
  },
  AvgDialog_19017_Content_62 = {
    Text = "Il suo corpo si gonfia e si contorce rapidamente, grotteschi tumori neri erompono dalla pelle pallida."
  },
  AvgDialog_19017_Content_63 = {
    Text = "Pus fetido sgorga dalle lacerazioni, trascinando filamenti viscosi."
  },
  AvgDialog_19017_Content_64 = {
    Text = "Vuoi portare Lily a vedere Eve, vero?"
  },
  AvgDialog_19017_Content_65 = {
    Text = "Mi dispiace, ma un nuovo paio di <Yellow:Divi Gemelli> è già in fase di creazione."
  },
  AvgDialog_19017_Content_66 = {
    Text = "Anche se vedessi Eve, non cambierebbe nulla."
  },
  AvgDialog_19017_Content_67 = {
    Text = "Allora perché non rendere significativi i tuoi ultimi istanti?"
  },
  AvgDialog_19017_Content_68 = {
    Text = "In questa forma contorta, con i tuoi istinti — va' a cercare la tua altra metà."
  },
  AvgDialog_19017_Content_69 = {
    Text = "<Shake:@2—@1—>"
  },
  AvgDialog_19017_Content_7 = {
    Text = "Un viaggio di ritorno a Mythag non richiederà molto."
  },
  AvgDialog_19017_Content_70 = {
    Text = "Nel frattempo, Pozza Nera di Mythag"
  },
  AvgDialog_19017_Content_71 = {
    Text = "Il bordo della Pozza Nera è deserto.\nRamona si avvicina lentamente all'acqua, fissando il suo riflesso."
  },
  AvgDialog_19017_Content_72 = {
    Text = "Le onde increspate si placano, rivelando il volto impassibile di una donna."
  },
  AvgDialog_19017_Content_73 = {
    Text = "I suoi lineamenti sono quasi identici a quelli di Ramona, se non per un'aria più matura, percepibile solo a un esame ravvicinato."
  },
  AvgDialog_19017_Content_74 = {
    Text = "Sapevi che sarei venuta, vero?"
  },
  AvgDialog_19017_Content_75 = {
    Text = [[
Ho alcune domande.
Voglio chiedere... a <Blue:Tawil>.]]
  },
  AvgDialog_19017_Content_8 = {
    Text = [[
Con Lotan qui, non devi preoccuparti della mia sicurezza.
Vero, Lotan?]]
  },
  AvgDialog_19017_Content_9 = {
    Text = [[
Hmph, ovviamente.
Sbrigati a tornare quando hai finito. Questa ragazzina non apre bocca quando ci sono io.]]
  },
  AvgDialog_19018_Content_1 = {
    Text = "È da un'eternità che non sgranchisco le membra—lasciami divertire un po'!"
  },
  AvgDialog_19019_Content_1 = {
    Text = "Benvenuti a Rye"
  },
  AvgDialog_19019_Content_10 = {
    Text = "<Blue:Lily>..."
  },
  AvgDialog_19019_Content_11 = {
    Text = "Ti piace, Lily? Vuoi toccarlo?"
  },
  AvgDialog_19019_Content_12 = {Text = "Certo."},
  AvgDialog_19019_Content_13 = {
    Text = [[
Lily sfiora con cautela la punta della Chiave.
Che sia la tua immaginazione o meno, la Chiave d'argento sembra tremolare al suo tocco.]]
  },
  AvgDialog_19019_Content_14 = {Text = "Oh..."},
  AvgDialog_19019_Content_15 = {
    Text = [[
Lily si aggrappa improvvisamente a te con forza.
Un calore ti intenerisce il cuore, e non puoi fare a meno di accarezzarle dolcemente la testa.]]
  },
  AvgDialog_19019_Content_16 = {
    Text = "Ramona ti lancia un'occhiata, come se volesse dire qualcosa."
  },
  AvgDialog_19019_Content_17 = {
    Text = "Che c'è, Ramona?"
  },
  AvgDialog_19019_Content_18 = {
    Text = "Mi dispiace rovinare questo momento di pace, ma—\nLa scorsa notte il Segugio infernale ha colpito. E questa volta c'è un testimone oculare."
  },
  AvgDialog_19019_Content_19 = {
    Text = "Tu e Ramona vi affrettate verso la fattoria dove è avvenuto l'incidente."
  },
  AvgDialog_19019_Content_2 = {
    Text = "<Gray:Ho fatto una specie di <Yellow:Sogno>... ho la testa tutta annebbiata...>"
  },
  AvgDialog_19019_Content_20 = {
    Text = "Un fetore pungente e acre di sangue ti assale i sensi ancor prima di entrare.\nIl pavimento è cosparso di macchie di sangue nauseabonde, mezze asciutte in un inquietante rosso scuro."
  },
  AvgDialog_19019_Content_21 = {
    Text = "Decine di volatili morti giacciono sparsi ovunque, le gole rivolte al cielo in una postura di morte atroce."
  },
  AvgDialog_19019_Content_22 = {
    Text = "Dubito che un Cataclisma come il Segugio infernale prenderebbe di mira qualche gallina."
  },
  AvgDialog_19019_Content_23 = {
    Text = "Segugio infernale? Persino un cane randagio è più civile."
  },
  AvgDialog_19019_Content_24 = {
    Text = "Sta succedendo di nuovo, sta succedendo... Padre Supremo, la mia piccola Lisa... ti prego, fa' che sia salva..."
  },
  AvgDialog_19019_Content_25 = {
    Text = "%player%, guarda qui."
  },
  AvgDialog_19019_Content_26 = {
    Text = "Le spoglie delle galline presentano segni di artigli, le piume vivaci aggrovigliate caoticamente sopra squarci profondi. I colli sono spezzati da una forza immensa, ossa frastagliate che sporgono da fratture irregolari."
  },
  AvgDialog_19019_Content_27 = {
    Text = "Questi segni di morso... non sembrano canini."
  },
  AvgDialog_19019_Content_28 = {
    Text = "Incisivi piatti, canini smussati—per quanto sia difficile ammetterlo, questi sembrano <Blue:segni di morsi umani>."
  },
  AvgDialog_19019_Content_29 = {
    Text = "Ramona si rivolge alla donna del villaggio accanto a te.\nÈ una vedova che vive da sola in città da anni, con solo sua figlia, <Blue:Lisa>, al suo fianco."
  },
  AvgDialog_19019_Content_3 = {
    Text = "<Gray:Ma perché sento questo peso sul petto...>"
  },
  AvgDialog_19019_Content_30 = {
    Text = "I capelli della donna sono un groviglio arruffato, le mani giunte freneticamente mentre mormora preghiere, le labbra pallide tremanti."
  },
  AvgDialog_19019_Content_31 = {
    Text = "Signora, signora?\nNon abbia paura, siamo qui per aiutarla. Può dirci esattamente cos'è successo?"
  },
  AvgDialog_19019_Content_32 = {
    Text = "Non è la prima volta. È iniziato con qualche gallina, ma adesso, adesso..."
  },
  AvgDialog_19019_Content_33 = {
    Text = "La recinzione non può fermarlo, non può. L'ho visto, l'ho visto con i miei occhi!\nNon era una volpe ieri notte... era un mostro!"
  },
  AvgDialog_19019_Content_34 = {
    Text = [[
La voce della vedova si alza in un grido lacerante.
Urla con voce rauca, stringendosi le braccia con dita tremanti.]]
  },
  AvgDialog_19019_Content_35 = {
    Text = "Tutto questo trambusto per cosa? È solo una bestia!"
  },
  AvgDialog_19019_Content_36 = {
    Text = "La vedova sembra sorda ai rimproveri di Lotan, persa in memorie dolorose."
  },
  AvgDialog_19019_Content_37 = {
    Text = "Non è una bestia, non lo è!"
  },
  AvgDialog_19019_Content_38 = {
    Text = "Quando si è avvicinato, l'ho visto, chiaro come il sole—"
  },
  AvgDialog_19019_Content_39 = {
    Text = "Quella cosa aveva braccia umane, e la sua faccia... niente! Quello è il <Yellow:Segugio infernale>! Mi trascinerà all'inferno!"
  },
  AvgDialog_19019_Content_4 = {
    Text = "Forzando le palpebre pesanti ad aprirsi, ti ritrovi davanti un paio di Occhi pallidi e limpidi."
  },
  AvgDialog_19019_Content_40 = {
    Text = [[
La vedova indietreggia in preda al panico, urtando improvvisamente una piccola figura.
Il suo volto si contorce in un istante.]]
  },
  AvgDialog_19019_Content_41 = {
    Text = "Ancora tu, essere maledetto! Sparisci! Sparisci!"
  },
  AvgDialog_19019_Content_42 = {
    Text = "Hai già ucciso Lisa, cos'altro vuoi? Sparisci!"
  },
  AvgDialog_19019_Content_43 = {
    Text = "L'espressione della vedova è grottescamente ferina, come se volesse fare a pezzi Lily con le proprie mani."
  },
  AvgDialog_19019_Content_44 = {
    Text = [[
Fai un passo avanti, proteggendo Lily dietro di te.
Ramona si unisce a te in silenzio, formando una barriera protettiva.]]
  },
  AvgDialog_19019_Content_45 = {
    Text = "Signora, per favore si calmi.\nNon possiamo ancora confermare la situazione di Lisa; c'è la possibilità che sia ancora viva."
  },
  AvgDialog_19019_Content_46 = {
    Text = "Crede che non la voglia viva? Crede che la voglia morta? Ho udito le sue grida quando ho visto il Segugio infernale la scorsa notte!"
  },
  AvgDialog_19019_Content_47 = {
    Text = "È quel mostro! Dev'essere lui! Ha divorato la mia Lisa, la mia povera Lisa, la mia povera figlia—"
  },
  AvgDialog_19019_Content_48 = {
    Text = "Se non fosse stato per quella strega, mia figlia non si sarebbe allontanata tanto dal focolare, non sarebbe stata presa di mira dal Segugio infernale, non avrebbe incontrato la sua fine!"
  },
  AvgDialog_19019_Content_49 = {
    Text = "Figlia mia, figlia mia— mamma è dispiaciuta, così dispiaciuta—"
  },
  AvgDialog_19019_Content_5 = {
    Text = "Buongiorno..."
  },
  AvgDialog_19019_Content_50 = {
    Text = "Stringendosi il petto, la vedova singhiozza e trema, la sua fragile anima a malapena in grado di sostenere il corpo."
  },
  AvgDialog_19019_Content_51 = {
    Text = "Ramona soffoca un sospiro e sorregge delicatamente la donna."
  },
  AvgDialog_19019_Content_52 = {
    Text = "Non pensi così, signora. Sua figlia potrebbe essere semplicemente a casa di un'amica, magari domani—"
  },
  AvgDialog_19019_Content_53 = {
    Text = "<Yellow:Lisa non farà ritorno.>"
  },
  AvgDialog_19019_Content_54 = {
    Text = "La voce infantile tronca le vostre parole. Voltandovi, scorgete un'espressione indecifrabile sul volto di Lily—esitazione, o forse indifferenza."
  },
  AvgDialog_19019_Content_55 = {
    Text = "Tu... Cosa hai detto?"
  },
  AvgDialog_19019_Content_56 = {
    Text = "Lisa ha detto... che non tornerà."
  },
  AvgDialog_19019_Content_57 = {
    Text = "Impossibile, assolutamente impossibile!\nLisa è una brava ragazza, e non direbbe mai una cosa del genere..."
  },
  AvgDialog_19019_Content_58 = {
    Text = "Lily, dove hai visto Lisa?"
  },
  AvgDialog_19019_Content_59 = {
    Text = "Lily si limita a scuotere la testa."
  },
  AvgDialog_19019_Content_6 = {
    Text = [[
<Shake:Whoa?!>
Ramona, cosa sta succedendo?]]
  },
  AvgDialog_19019_Content_60 = {
    Text = "No, stai dicendo sciocchezze, demonio, strega!\nLisa era così gentile con te, e tu la maledici, la diffami!"
  },
  AvgDialog_19019_Content_61 = {
    Text = "Con uno schiaffo secco, la vedova colpisce il volto di Lily."
  },
  AvgDialog_19019_Content_62 = {
    Text = "Intervieni rapidamente per separarle."
  },
  AvgDialog_19019_Content_63 = {
    Text = "Lily, stringendosi la guancia, si rifugia dietro di te."
  },
  AvgDialog_19019_Content_64 = {
    Text = "Non ci sono prove che colleghino il caso di sua figlia a Lily!"
  },
  AvgDialog_19019_Content_65 = {
    Text = "Ramona vi lancia un'occhiata, facendovi segno di tacere."
  },
  AvgDialog_19019_Content_66 = {
    Text = "Voi, non osate fare i prepotenti con la mamma di Lisa!"
  },
  AvgDialog_19019_Content_67 = {
    Text = "E voi chi sareste?"
  },
  AvgDialog_19019_Content_68 = {
    Text = "Io sono Hank, lui è John, e siamo amici di Lisa!"
  },
  AvgDialog_19019_Content_69 = {
    Text = "Quel giorno, Lily ha portato Lisa alla periferia—l'abbiamo visto con i nostri occhi!"
  },
  AvgDialog_19019_Content_7 = {
    Text = "Non riuscivamo a svegliarti in nessun modo, così lei ha voluto controllarti... Non ci aspettavamo che si addormentasse sul tuo petto."
  },
  AvgDialog_19019_Content_70 = {
    Text = "Basta parlare, {Male=è con quel,Female=è con quel} diavolo! {Male=Diamogli,Female=Diamole} una lezione!"
  },
  AvgDialog_19019_Content_71 = {
    Text = "Proteggiamo la mamma di Lisa!"
  },
  AvgDialog_19019_Content_72 = {
    Text = "..Non hai mai la sensazione che ce la prendiamo sempre con i ragazzini?"
  },
  AvgDialog_19019_Content_8 = {
    Text = [[
La Bambina scende con riluttanza, il suo Sguardo indugia sul tuo petto.
Abbassando lo sguardo, vedi la Chiave d'Argento, ancora indossata persino nel sonno, che brilla di un tenue bagliore.]]
  },
  AvgDialog_19019_Content_9 = {
    Text = "Come ti chiami?"
  },
  AvgDialog_19021_Content_1 = {
    Text = "Sotto la Tesa"
  },
  AvgDialog_19021_Content_10 = {
    Text = [[
Quindi, sei qui per uno scopo legittimo e ragionevole.
Data la natura di questa bottega, si tratta di un affare.]]
  },
  AvgDialog_19021_Content_11 = {
    Text = "Non hai chiesto sul momento, ma hai fatto questa deviazione per trovarmi, il che significa che c'era qualcuno presente che non volevi ascoltasse."
  },
  AvgDialog_19021_Content_12 = {
    Text = "Pertanto, concludo: vuoi informazioni su Helot e Lily."
  },
  AvgDialog_19021_Content_13 = {
    Text = "Sì. Più precisamente, qual è il legame tra Helot e Lily?\nCosa significa esattamente <Yellow:affini>?"
  },
  AvgDialog_19021_Content_14 = {
    Text = "Non è questa la tua vera domanda."
  },
  AvgDialog_19021_Content_15 = {
    Text = "Ciò che vuoi davvero sapere riguarda il potere dentro di te...\nHai già visto qualcuno con un potere <Yellow:affine>, non è vero?"
  },
  AvgDialog_19021_Content_16 = {
    Text = "<Gray:Ramona lo sa?! Quindi, il mio accordo con Lord Dexter non poteva restare nascosto a lei...>"
  },
  AvgDialog_19021_Content_17 = {
    Text = "Il volto di Ramona muta bruscamente, ma Daffodil continua a sorridere, traboccante di calcolo."
  },
  AvgDialog_19021_Content_18 = {
    Text = "Non preoccuparti, non sono il tipo che fa la spia. Puoi continuare a fare l'innocente con Lord Dexter."
  },
  AvgDialog_19021_Content_19 = {
    Text = "Ma purtroppo non posso darti la risposta.\nIl mio accordo con l'Università di Mythag, nero su bianco, vieta di intromettersi negli affari della scuola."
  },
  AvgDialog_19021_Content_2 = {
    Text = "È qui il posto."
  },
  AvgDialog_19021_Content_20 = {
    Text = "Il mio unico consiglio:\nvisto che sei così curioso, perché non chiedi direttamente a <Yellow:Lei>?"
  },
  AvgDialog_19021_Content_21 = {
    Text = "Ramona si blocca."
  },
  AvgDialog_19021_Content_22 = {
    Text = "Forse la risposta era così semplice da cadere nel suo punto cieco. Non l'aveva mai presa in considerazione."
  },
  AvgDialog_19021_Content_23 = {
    Text = "Pizzica l'orlo della gonna e fa un'educata riverenza."
  },
  AvgDialog_19021_Content_24 = {
    Text = "Grazie per le indicazioni. Mi congedo."
  },
  AvgDialog_19021_Content_25 = {
    Text = "Fai attenzione. La via del ritorno non è così semplice."
  },
  AvgDialog_19021_Content_26 = {Text = "Ma..."},
  AvgDialog_19021_Content_27 = {
    Text = "Forse è esattamente ciò che desideri."
  },
  AvgDialog_19021_Content_3 = {
    Text = [[
Una stanza avvolta nella nebbia viola appare davanti a te.
Ti sembra vagamente familiare, eppure i dettagli differiscono sottilmente dai tuoi ricordi.]]
  },
  AvgDialog_19021_Content_4 = {
    Text = "Ripercorrendo i tuoi ricordi, individui finalmente la differenza..."
  },
  AvgDialog_19021_Content_5 = {
    Text = "I beni qui..."
  },
  AvgDialog_19021_Content_6 = {
    Text = "Oh, cielo. Ospiti inattesi ci onorano della loro presenza."
  },
  AvgDialog_19021_Content_7 = {
    Text = "Le tracce che ho lasciato sul Fascicolo erano evidenti. Dal momento che non le hai cancellate, confido che una visita sia gradita."
  },
  AvgDialog_19021_Content_8 = {
    Text = "Sveglia, ma senza pretese.\nDimmi, ragazza, perché sei qui?"
  },
  AvgDialog_19021_Content_9 = {
    Text = "No, meglio ancora, lasciami indovinare...\nNon mi stai seguendo di nascosto, altrimenti non avresti lasciato tracce così evidenti."
  },
  AvgDialog_19025_Content_1 = {
    Text = "Inseguite la creatura nera finché non si dissolve nella notte profonda, perdendone ogni traccia."
  },
  AvgDialog_19025_Content_10 = {
    Text = "Herbert? Intendete <Blue:Herbert Rosenthal>? L'ex ricercatore di Mythag, ricercato per l'omicidio del suo mentore?"
  },
  AvgDialog_19025_Content_11 = {
    Text = "Proprio lui. Ha fondato l'Associazione degli Scultori da solo. Speriamo che le vostre membra siano ancora al loro posto."
  },
  AvgDialog_19025_Content_12 = {
    Text = "Non ci ha causato problemi.\nPerò sembrava cercare una bambina di otto o nove anni."
  },
  AvgDialog_19025_Content_13 = {
    Text = "Sempre con i suoi vecchi trucchi... Capito. William assegnerà altri investigatori per rintracciare Herbert.\nLa tua priorità assoluta resta il Cladi."
  },
  AvgDialog_19025_Content_14 = {
    Text = "Dopotutto, questi mostri della Dissoluzione sono la prova della presenza del Cladi.\nA differenza dello smog di Londinium o dei pazzi dell'Università di Mythag, non sono esattamente comuni."
  },
  AvgDialog_19025_Content_15 = {
    Text = "Capito, ma... al momento abbiamo un problema più urgente."
  },
  AvgDialog_19025_Content_16 = {
    Text = "Un altro mutante?"
  },
  AvgDialog_19025_Content_17 = {
    Text = "Non così urgente—solo un problema di alloggio.\nSe posso evitarlo, non dormirò sotto una coltre di neve."
  },
  AvgDialog_19025_Content_18 = {
    Text = "<Italic:{Male=Signore,Female=Signorina}, siete ospiti venuti da molto, molto lontano?>"
  },
  AvgDialog_19025_Content_19 = {
    Text = "Una voce tenera interrompe la vostra conversazione."
  },
  AvgDialog_19025_Content_2 = {
    Text = "Fuggire via come un codardo — si può davvero chiamare <Yellow:Segugio infernale>?"
  },
  AvgDialog_19025_Content_20 = {
    Text = "Chi è là?"
  },
  AvgDialog_19025_Content_21 = {
    Text = "La neve sul muro riflette l'incontaminata luce lunare, e al suo centro si erge una fanciulla più candida del chiarore della luna."
  },
  AvgDialog_19025_Content_22 = {
    Text = [[
Se non trovi un posto dove stare, <Blue:Lady Daffodil> affitta stanze.
Proprio dietro l'angolo.]]
  },
  AvgDialog_19025_Content_23 = {
    Text = "Scambiate uno sguardo con Ramona, che annuisce in segno di conferma."
  },
  AvgDialog_19025_Content_24 = {
    Text = "Un vestito bianco, un cartellino medico, così giovane. Dev'essere la bambina che Herbert sta cercando di tracciare, e potrebbe custodire indizi per l'indagine."
  },
  AvgDialog_19025_Content_25 = {
    Text = [[
Andiamo, cosa state aspettando?
Vi va di ululare coi lupi tutta la notte all'addiaccio?]]
  },
  AvgDialog_19025_Content_26 = {
    Text = "Se volete arrangiarvi all'addiaccio, per me va bene in qualsiasi momento, ma dubito che i vostri corpicini fragili possano reggere."
  },
  AvgDialog_19025_Content_27 = {
    Text = "Lotan dà una pacca sulla spalla di Ramona. Ramona fa una smorfia come se avesse divorato una mosca, ma non dice nulla."
  },
  AvgDialog_19025_Content_28 = {
    Text = "Lady Daffodil... sembra il nome di qualche ricca benefattrice, no?"
  },
  AvgDialog_19025_Content_3 = {
    Text = "Sembrava fuggire solo dopo aver percepito che non avevamo paura di lei.\nI suoi istinti di sopravvivenza sono animaleschi, ma non ho mai sentito di un Cladi che si comporti così."
  },
  AvgDialog_19025_Content_4 = {
    Text = "Inoltre, era ferito."
  },
  AvgDialog_19025_Content_5 = {
    Text = "È vero, ho sentito l'odore di sangue."
  },
  AvgDialog_19025_Content_6 = {
    Text = "Il comunicatore emette un lieve bip."
  },
  AvgDialog_19025_Content_7 = {
    Text = "Finalmente di nuovo in linea. Dopo questa missione, potenzierò questo aggeggio."
  },
  AvgDialog_19025_Content_8 = {
    Text = "Doll? Cos'è appena successo?"
  },
  AvgDialog_19025_Content_9 = {
    Text = [[
Interferenze nelle comunicazioni, un trucco preferito di <Blue:Herbert>.
A quanto pare hai incontrato il pazzo con il gatto a due teste.]]
  },
  AvgDialog_19026_Content_1 = {
    Text = "Lord Dexter ha detto che è meglio non provocare Lady Daffodil."
  },
  AvgDialog_19026_Content_2 = {
    Text = "Va tutto bene — non ha cattive intenzioni."
  },
  AvgDialog_19026_Content_3 = {
    Text = "Quei mostri potrebbero non essere d'accordo..."
  },
  AvgDialog_19028_Content_1 = {
    Text = "Lasciatemi, lasciatemi! Adulti che fanno i prepotenti coi bambini!"
  },
  AvgDialog_19028_Content_10 = {
    Text = "Le indagini richiedono più dei pugni — servono cervelli."
  },
  AvgDialog_19028_Content_11 = {
    Text = "Chi vi ha chiesto di intromettervi?"
  },
  AvgDialog_19028_Content_12 = {
    Text = "Mi scuso, mi scuso.\nDoll, sii un po' più gentile con la nostra signorina."
  },
  AvgDialog_19028_Content_13 = {
    Text = "Doll, Lord Dexter?"
  },
  AvgDialog_19028_Content_14 = {
    Text = "Ramona è presente?"
  },
  AvgDialog_19028_Content_15 = {
    Text = "Per qualche ragione, il tono solitamente calmo di Doll tradisce una sfumatura d'urgenza."
  },
  AvgDialog_19028_Content_16 = {
    Text = "Sì. Che succede?"
  },
  AvgDialog_19028_Content_17 = {
    Text = "Stavo esaminando i registri delle comunicazioni. Hai chiesto a Erica informazioni su qualcuno?"
  },
  AvgDialog_19028_Content_18 = {
    Text = "Una donna che si fa chiamare \"Lady Daffodil\", sui ventotto anni, capelli grigio cenere, commerciante di antiquariato."
  },
  AvgDialog_19028_Content_19 = {
    Text = "Sì, ma Erica ha detto che non c'è traccia di lei negli archivi."
  },
  AvgDialog_19028_Content_2 = {
    Text = "Primo, siete stati voi ad attaccarci."
  },
  AvgDialog_19028_Content_20 = {
    Text = "Questo perché, nei registri ufficiali, lei <Blue:non esiste>."
  },
  AvgDialog_19028_Content_21 = {
    Text = "Non esiste?"
  },
  AvgDialog_19028_Content_22 = {
    Text = "Vuoi dire... che può manomettere i registri di Mythag?"
  },
  AvgDialog_19028_Content_23 = {
    Text = "Non è manomissione, solo un accordo.\nMythag ha distrutto i suoi documenti cartacei e, in cambio, lei ci fornisce informazioni."
  },
  AvgDialog_19028_Content_24 = {
    Text = "E causa meno problemi."
  },
  AvgDialog_19028_Content_25 = {
    Text = "Non è affascinante? Noi lottiamo per preservare i registri erosi dalla Dissoluzione, eppure c'è chi vuole le proprie tracce cancellate dall'esistenza."
  },
  AvgDialog_19028_Content_26 = {
    Text = "Mia cara Ramona, mi senti? Come procede la tua spedizione? Se hai bisogno d'aiuto, basta dirlo al tuo papà—"
  },
  AvgDialog_19028_Content_27 = {
    Text = "Se non hai nulla di urgente, lascia le comunicazioni a Doll e torna al tuo ricevimento, Padre."
  },
  AvgDialog_19028_Content_28 = {
    Text = "Che freddezza! È l'adolescenza? Sono venuta apposta per condividere informazioni.\nDopotutto, i dettagli su Daffodil sono conservati proprio qui da me."
  },
  AvgDialog_19028_Content_29 = {
    Text = "Puoi immaginare Dexter che alza un dito, sfoggiando il suo solito sorriso sgargiante e provocatorio, e si tocca la tempia."
  },
  AvgDialog_19028_Content_3 = {
    Text = "Secondo, stando alla mia età anagrafica, non sono ancora adulta."
  },
  AvgDialog_19028_Content_30 = {
    Text = "Se il cervello di Lord Dexter non è stato messo sotto spirito dall'alcol, ecco cosa sa Mythag su Daffodil."
  },
  AvgDialog_19028_Content_31 = {
    Text = "Lady Daffodil è ufficialmente una mercante di antiquariato, ma in privato è profondamente invischiata con gruppi illeciti come la <Yellow:Chiesa dei Portatori di Luce> e l'<Yellow:Associazione degli Scultori>."
  },
  AvgDialog_19028_Content_32 = {
    Text = "Nei trecento anni di registri dell'Università di Mythag, almeno venti casi portano la sua influenza... in modi che preferiremmo non vedere."
  },
  AvgDialog_19028_Content_33 = {
    Text = "In ogni caso, lei si presenta alla fine e <Yellow:raccoglie i teschi dei morti>."
  },
  AvgDialog_19028_Content_34 = {
    Text = "Trecento anni?"
  },
  AvgDialog_19028_Content_35 = {
    Text = "Sì, trecento anni. Nonostante mascheri la sua presenza con mezzi speciali, Lady Daffodil è indubbiamente una Risvegliata."
  },
  AvgDialog_19028_Content_36 = {
    Text = "Mezzi speciali? Probabilmente il fetore di cadaveri."
  },
  AvgDialog_19028_Content_37 = {
    Text = "Se è una Risvegliatrice pericolosa, perché Mythag o il Comitato non l'hanno messa sotto controllo?"
  },
  AvgDialog_19028_Content_38 = {
    Text = "Hai colto nel segno. Mentre gli umani si affannano per i tram affollati, Daffodil ha padroneggiato <Yellow:l'abilità di attraversare le Dimensioni liberamente>."
  },
  AvgDialog_19028_Content_39 = {
    Text = "I tentativi del Comitato di darle la caccia sono tutti falliti."
  },
  AvgDialog_19028_Content_4 = {
    Text = "Apparentemente colpito dalle sue parole, il ragazzo ammutolisce, fissando Ramona.\nRamona sospira, gli lascia il braccio e gli dà una leggera spinta sulla schiena."
  },
  AvgDialog_19028_Content_40 = {
    Text = "Quanto a noi, l'Università di Mythag non è una prigione. Il nostro rapporto con i Risvegliati si basa sulla cooperazione volontaria. Se lei non è disposta, non la costringiamo."
  },
  AvgDialog_19028_Content_41 = {
    Text = "Esatto. Certi sciocchi strillano tutto il giorno di voler fuggire, ma al di fuori della Pozza nera di Mythag non hanno un posto dove andare."
  },
  AvgDialog_19028_Content_42 = {
    Text = "Incatena un cane, poi chiamalo consenziente."
  },
  AvgDialog_19028_Content_43 = {
    Text = "Strano, ho sentito qualcosa abbaiare?"
  },
  AvgDialog_19028_Content_44 = {
    Text = "Basta, tutti e due."
  },
  AvgDialog_19028_Content_45 = {
    Text = "Hmph.\nIn breve, con Lady Daffodil coinvolta, questo caso è probabilmente più complesso del previsto."
  },
  AvgDialog_19028_Content_46 = {
    Text = "Se avessi notato prima la sua anomalia, forse..."
  },
  AvgDialog_19028_Content_47 = {
    Text = "Non essere troppo duro con te stesso. Hai già pensato di consultare Erica, no?\nI giovani hanno bisogno di esperienza per imparare a leggere una situazione."
  },
  AvgDialog_19028_Content_48 = {
    Text = "Il consiglio di Mythag: evita di impelagarti con lei, a meno che non sia strettamente necessario."
  },
  AvgDialog_19028_Content_49 = {
    Text = "Anche con il Custode, il nostro più forte Agente sul campo, non sareste all'altezza di quella donna astuta e navigata."
  },
  AvgDialog_19028_Content_5 = {
    Text = "D'accordo, vai a casa. Non disturberemo più la mamma di Lisa."
  },
  AvgDialog_19028_Content_50 = {
    Text = "Il caso del Segugio infernale non corrisponde al suo stile, quindi devono esserci altre forze all'opera in questa città.\nSe ti lasci invischiare in un groviglio, non avrai alcuna possibilità contro di lei."
  },
  AvgDialog_19028_Content_51 = {Text = "Capito."},
  AvgDialog_19028_Content_52 = {
    Text = "Procederemo con cautela."
  },
  AvgDialog_19028_Content_53 = {
    Text = "Tch. Non aspettatevi che cammini in punta di piedi."
  },
  AvgDialog_19028_Content_54 = {
    Text = "Doll ignora l'osservazione di Lotan, la sua voce si fa distante, come se si rivolgesse a qualcuno lì vicino."
  },
  AvgDialog_19028_Content_55 = {
    Text = "Dexter, qualcos'altro per tua figlia?"
  },
  AvgDialog_19028_Content_56 = {
    Text = [[
Certo, certo.
Oltre al combattimento, sii cauto nei tuoi rapporti personali con Lady Daffodil.]]
  },
  AvgDialog_19028_Content_57 = {
    Text = "Dopotutto, ecco... è una donna dal fascino maturo considerevole."
  },
  AvgDialog_19028_Content_58 = {
    Text = "Chi non ama la bellezza? Anch'io sono piuttosto affascinato dal suo portamento, ma non lasciatevi irretire dalle sue lusinghe..."
  },
  AvgDialog_19028_Content_59 = {
    Text = "Con un secco clic, Ramona interrompe le comunicazioni."
  },
  AvgDialog_19028_Content_6 = {
    Text = "Si rivolge alla donna ancora in lacrime, addolcendo la voce:"
  },
  AvgDialog_19028_Content_60 = {
    Text = "Andiamo. Ora dobbiamo parlare con Lily."
  },
  AvgDialog_19028_Content_7 = {
    Text = "Per favore, vada a riposare e si riprenda. Parleremo con Lily e andremo a fondo della questione."
  },
  AvgDialog_19028_Content_8 = {
    Text = "E la informeremo non appena avremo novità."
  },
  AvgDialog_19028_Content_9 = {
    Text = "Faresti meglio a trovarmi degli avversari veri. Questi ragazzini non sono all'altezza."
  },
  AvgDialog_19033_Content_1 = {
    Text = "Buone Notizie, Cattive Notizie"
  },
  AvgDialog_19033_Content_10 = {
    Text = "<Small:Lily fa la brava, e la Signora aiuterà la mamma... Lily fa la brava...>"
  },
  AvgDialog_19033_Content_11 = {
    Text = "La ragazza trattiene il respiro, rannicchiata nel folto dell'ombra, sfuggendo alla caccia di una donna dai tratti affilati."
  },
  AvgDialog_19033_Content_12 = {
    Text = "Il folto si anima all'improvviso di flebili sussurri."
  },
  AvgDialog_19033_Content_13 = {
    Text = "Vieni fuori!"
  },
  AvgDialog_19033_Content_14 = {Text = "..."},
  AvgDialog_19033_Content_15 = {
    Text = "Dopo un silenzio soffocante, una figura emerge lentamente dai cespugli."
  },
  AvgDialog_19033_Content_16 = {Text = "..."},
  AvgDialog_19033_Content_17 = {
    Text = "...Lascia perdere."
  },
  AvgDialog_19033_Content_18 = {
    Text = "Questo non ti riguarda... Continua a correre."
  },
  AvgDialog_19033_Content_19 = {
    Text = "La donna dai tratti affilati agita la mano con noncuranza, ordinando alla bestia di andarsene, poi si volta e svanisce nella notte."
  },
  AvgDialog_19033_Content_2 = {
    Text = "Le parole gli sono appena uscite di bocca quando Lotan e Ramona sguainano le Spade, fronteggiando l'Uomo con un Occhio Solo apparso dal nulla."
  },
  AvgDialog_19033_Content_20 = {
    Text = "Fuori dalla locanda"
  },
  AvgDialog_19033_Content_21 = {
    Text = "Beh, a quanto pare non lo sai.\nPeccato, le scorciatoie non spuntano dal nulla, e battere la fiacca è sempre così complicato."
  },
  AvgDialog_19033_Content_22 = {
    Text = "Oh, a proposito..."
  },
  AvgDialog_19033_Content_23 = {
    Text = "L'Uomo con un Occhio Solo si ferma, fingendo un'aria misteriosa."
  },
  AvgDialog_19033_Content_24 = {
    Text = "Il Segugio infernale...\nÈ proprio dietro di te."
  },
  AvgDialog_19033_Content_25 = {
    Text = "Cercate di distrarci con trucchetti così meschini? Ci sottovalutate."
  },
  AvgDialog_19033_Content_26 = {
    Text = "Un'improvvisa palpitazione ti attanaglia, un formicolio alla nuca, un'oppressione che penetra fino alle ossa.\nSai, con agghiacciante certezza, che non è un semplice scherzo della mente."
  },
  AvgDialog_19033_Content_27 = {
    Text = "Hmm? Perché te ne stai lì immobile?"
  },
  AvgDialog_19033_Content_28 = {
    Text = "Lotan, voltati."
  },
  AvgDialog_19033_Content_29 = {
    Text = "Lotan volta lentamente la testa."
  },
  AvgDialog_19033_Content_3 = {
    Text = "Non ce n'è bisogno. Sto semplicemente facendo visita a un amico, senza alcuna intenzione di scontrarmi con voi."
  },
  AvgDialog_19033_Content_30 = {Text = "Che—"},
  AvgDialog_19033_Content_31 = {Text = "!"},
  AvgDialog_19033_Content_32 = {
    Text = [[
Con un ansito assordante che martella i tuoi timpani, pupille dorate a fessura squarciano lo spazio dietro Lotan.
Il loro sguardo vacuo scruta la terra, per poi fissarsi infine su di te.]]
  },
  AvgDialog_19033_Content_33 = {
    Text = "Il vostro cuore trema incontrollabilmente, come se quegli occhi osservassero dal margine del mare cosmico sin dalla notte dei tempi—"
  },
  AvgDialog_19033_Content_34 = {
    Text = "Mantieni la calma, preparati al combattimento!"
  },
  AvgDialog_19033_Content_4 = {
    Text = "A proposito, hai visto una bambina?\nAlta più o meno così..."
  },
  AvgDialog_19033_Content_5 = {
    Text = "Ignorando la vostra presenza, l'uomo gesticola con fare indolente."
  },
  AvgDialog_19033_Content_6 = {
    Text = "Indossa un Vestito bianco, con una piccola targhetta appesa addosso..."
  },
  AvgDialog_19033_Content_7 = {
    Text = [[
Nel frattempo
Un boschetto a Rye]]
  },
  AvgDialog_19033_Content_8 = {
    Text = "Dove sei..."
  },
  AvgDialog_19033_Content_9 = {
    Text = "<Small:Devo fuggire... Devo trovare l'ospite...>"
  },
  AvgDialog_19034_Content_1 = {
    Text = "Lily, fatti da parte. Non vogliamo fare del male a Francis!"
  },
  AvgDialog_19034_Content_2 = {
    Text = "Non lasciare che tua madre continui a commettere errori!"
  },
  AvgDialog_19034_Content_3 = {
    Text = "Ma... dre..."
  },
  AvgDialog_19035_Content_1 = {
    Text = "%player%, resisti!"
  },
  AvgDialog_19035_Content_2 = {
    Text = "Questa pustola può mutare per proteggerti!"
  },
  AvgDialog_19035_Content_3 = {
    Text = "Dispiegalo ora per bloccare i colpi.\nVa bene così—Lily non sente dolore!"
  },
  AvgDialog_19036_Content_1 = {Text = "Epilogo"},
  AvgDialog_19036_Content_10 = {
    Text = "Che bello! Vorrei poter andare in un posto così lontano..."
  },
  AvgDialog_19036_Content_100 = {
    Text = "A proposito, ho visto un <Yellow:sigillo> all'Altare nel mio sogno."
  },
  AvgDialog_19036_Content_101 = {
    Text = "Quale sigillo?"
  },
  AvgDialog_19036_Content_102 = {
    Text = "Aspetta, lo disegno."
  },
  AvgDialog_19036_Content_103 = {
    Text = "Tiri fuori un taccuino, abbozzando uno schizzo approssimativo."
  },
  AvgDialog_19036_Content_104 = {
    Text = "Un momento, ho già visto quel sigillo..."
  },
  AvgDialog_19036_Content_105 = {
    Text = "Allora, che effetto fa essere fatta a pezzi, cara signorina Doll?"
  },
  AvgDialog_19036_Content_106 = {
    Text = [[
Grazie a te, niente di niente.
A differenza di alcuni, non sono combattuta tra nuove forme di vita e l'attaccamento alla carne mortale.]]
  },
  AvgDialog_19036_Content_107 = {
    Text = [[
Chiamare la linea pubblica della scuola? Davvero?
Lo Scherno non si addice alla tua solita codardia.]]
  },
  AvgDialog_19036_Content_108 = {
    Text = "Calma, ora. Ho buone notizie."
  },
  AvgDialog_19036_Content_109 = {
    Text = "Quel <Yellow:Nucleo d'Argento> che mi hai lasciato? Roba di prima qualità.\nQuesto viaggio non è stato una perdita totale."
  },
  AvgDialog_19036_Content_11 = {
    Text = "Ahimè... spero che riscriva non appena raggiungerà il prossimo porto..."
  },
  AvgDialog_19036_Content_110 = {
    Text = "Ma Lady Daffodil è furiosa. Dice che il teschio che aveva in Riserva è stato bloccato in un luogo fuori dalla sua Portata. Pessimo affare, pessima sorte."
  },
  AvgDialog_19036_Content_111 = {
    Text = [[
Per i vecchi tempi, un consiglio: smetti di inseguirmi.
Chi cerca di fregarmi finisce con un pugno di mosche.]]
  },
  AvgDialog_19036_Content_112 = {
    Text = "Niente? Non credo proprio."
  },
  AvgDialog_19036_Content_113 = {
    Text = "Ti sei mai chiesto perché ti ho lasciato quel Nucleo d'Argento quando mi sono fatta esplodere?"
  },
  AvgDialog_19036_Content_114 = {
    Text = "La Voce di Doll è gelida come il ghiaccio, ma per Herbert porta con sé una cadenza beffarda."
  },
  AvgDialog_19036_Content_115 = {
    Text = "Sul quaderno da disegno accanto a Doll, un motivo nitido è inciso."
  },
  AvgDialog_19036_Content_12 = {Text = "..."},
  AvgDialog_19036_Content_13 = {
    Text = "Helot resta sola al molo, i lunghi capelli danzanti nel vento."
  },
  AvgDialog_19036_Content_14 = {
    Text = "La nave sta partendo. Sali a bordo?"
  },
  AvgDialog_19036_Content_15 = {
    Text = "Helot saluta con la mano, facendo segno al traghetto di partire senza di lei."
  },
  AvgDialog_19036_Content_16 = {
    Text = "Se ne avrai l'occasione, vai a esplorare un mondo più vasto."
  },
  AvgDialog_19036_Content_17 = {Text = "..."},
  AvgDialog_19036_Content_18 = {
    Text = "Tra le grida del Marinaio, Helot aggancia la catena e balza sul ponte."
  },
  AvgDialog_19036_Content_19 = {
    Text = "Al suono del fischio, la riva svanisce in lontananza."
  },
  AvgDialog_19036_Content_2 = {
    Text = "Nymphaea! Il signor Crawford vuole riascoltare quella poesia sulla ninfea bianca — vai a leggergliela!"
  },
  AvgDialog_19036_Content_20 = {
    Text = "Hmph... quella gente di Mythag..."
  },
  AvgDialog_19036_Content_21 = {
    Text = "Stavolta, sono in debito con loro."
  },
  AvgDialog_19036_Content_22 = {Text = "..."},
  AvgDialog_19036_Content_23 = {
    Text = "Tornato a Mythag, sei crollato sul letto del dormitorio per tre giorni, senza cibo né acqua."
  },
  AvgDialog_19036_Content_24 = {
    Text = "Il coma del Custode divenne una grande notizia, sbattuta in prima pagina sul giornale scolastico da Hannah. Studenti di altri dipartimenti sbirciavano dalla tua porta."
  },
  AvgDialog_19036_Content_25 = {
    Text = "Il tuo risveglio si è propagato altrettanto in fretta, non c'è da stupirsi."
  },
  AvgDialog_19036_Content_26 = {
    Text = "Ramona te lo raccontò in seguito.\nIn quel momento, ti sentivi solo svuotato, come se ogni forza ti fosse stata prosciugata."
  },
  AvgDialog_19036_Content_27 = {
    Text = "Quando apri gli occhi, il primo volto che vedi ti fa pensare di star avendo un'allucinazione."
  },
  AvgDialog_19036_Content_28 = {
    Text = "Congratulazioni per esserti ripreso dal Contraccolpo dimensionale, Custode. Ho buone notizie."
  },
  AvgDialog_19036_Content_29 = {
    Text = "Questa missione è stata molto più dura di quanto avessimo stimato, ma ce l'hai fatta. Farà un'ottima figura nel tuo rapporto finale."
  },
  AvgDialog_19036_Content_3 = {
    Text = "Un momento, prego."
  },
  AvgDialog_19036_Content_30 = {
    Text = "Incredibile, eh? Doll non fa complimenti spesso."
  },
  AvgDialog_19036_Content_31 = {
    Text = "Doll...? Ma tu non eri... e Herbert..."
  },
  AvgDialog_19036_Content_32 = {
    Text = "Sto ripensando a quel complimento."
  },
  AvgDialog_19036_Content_33 = {
    Text = "<Shake:No! Ti prego, non farlo!>"
  },
  AvgDialog_19036_Content_34 = {
    Text = "Mi chiamano <Blue:il Cervello in una Vasca>. Il cervello che si trova a Mythag è il vero me."
  },
  AvgDialog_19036_Content_35 = {
    Text = "Il <Yellow:corpo artificiale> che è stato fatto saltare in aria? Posso costruirne quanti ne servono."
  },
  AvgDialog_19036_Content_36 = {
    Text = "Non posso però sprecarli, o il budget del Dipartimento di Studi sul Risveglio andrà a picco. E allora dovresti trascinare Ramona a eseguire danze di spada per ottenere la sponsorizzazione di Lord Dexter."
  },
  AvgDialog_19036_Content_37 = {
    Text = "Sarebbe un piacere assistere."
  },
  AvgDialog_19036_Content_38 = {
    Text = "Oh, a proposito, quei monocoli dimensionali che hai usato? Oggetti monouso."
  },
  AvgDialog_19036_Content_39 = {
    Text = "Comprati da quella Daffodil dal cuore nero. Uno solo vale circa cinque dei miei corpi artificiali."
  },
  AvgDialog_19036_Content_4 = {
    Text = "A proposito, è da un'eternità che non vedo il Direttore Oswood."
  },
  AvgDialog_19036_Content_40 = {
    Text = "Quindi se ne hai usati qualcuno di troppo, ti suggerisco di venderti come servo a Lord Dexter per ripagare il debito."
  },
  AvgDialog_19036_Content_41 = {
    Text = "Sarebbe un onore per me."
  },
  AvgDialog_19036_Content_42 = {Text = "..."},
  AvgDialog_19036_Content_43 = {
    Text = "Il flusso di visitatori è incessante, più estenuante delle missioni sul campo."
  },
  AvgDialog_19036_Content_44 = {
    Text = "Quando finalmente si disperdono, chiudi gli occhi per riprendere fiato, pronto a riposare, quando una figura familiare appare silenziosamente accanto al tuo letto."
  },
  AvgDialog_19036_Content_45 = {
    Text = "Dovremmo... andare a trovare Lily?"
  },
  AvgDialog_19036_Content_46 = {
    Text = "Una piccola figura siede sul letto, appoggiata a un cuscino bianco, lo sguardo rivolto fuori dalla finestra."
  },
  AvgDialog_19036_Content_47 = {
    Text = "Lily, %player% è qui."
  },
  AvgDialog_19036_Content_48 = {Text = "%player%."},
  AvgDialog_19036_Content_49 = {
    Text = [[
Che ne pensi della mia proposta di prima?
Stabilire un Legame con %player%, diventare nostra partner...]]
  },
  AvgDialog_19036_Content_5 = {
    Text = "La direttrice... sta lavorando da sola a una ricerca importante. Potrebbe passare molto, molto tempo prima che faccia ritorno al sanatorio."
  },
  AvgDialog_19036_Content_50 = {
    Text = "Lily distoglie lo sguardo, evitando i tuoi occhi."
  },
  AvgDialog_19036_Content_51 = {
    Text = [[
Se... se non volessi?
Mi rinchiuderete... come un mostro?]]
  },
  AvgDialog_19036_Content_52 = {
    Text = "Scusa, non volevo metterti pressione. Solo..."
  },
  AvgDialog_19036_Content_53 = {
    Text = "Lascia che me ne occupi io."
  },
  AvgDialog_19036_Content_54 = {Text = "Lily."},
  AvgDialog_19036_Content_55 = {Text = "Sì?"},
  AvgDialog_19036_Content_56 = {
    Text = "Quello che ti è successo... forse la colpa è un po' di tutti.\nMa da un altro punto di vista, né tu né tua madre avevate torto."
  },
  AvgDialog_19036_Content_57 = {
    Text = "La radice di tutto questo male è la Dissoluzione...\nuna malattia che fa dimenticare le persone."
  },
  AvgDialog_19036_Content_58 = {
    Text = "Poiché chi ti circondava ti aveva dimenticata, Francis inseguiva ossessivamente le prove della tua esistenza."
  },
  AvgDialog_19036_Content_59 = {
    Text = "Poiché anche lei aveva cominciato a dimenticarti, non riusciva più a riconoscere la sua stessa carne e sangue."
  },
  AvgDialog_19036_Content_6 = {
    Text = [[
Giusto! Una brillante come lei, bloccata in questo posto fatiscente? Che spreco!
Se la vedi, dille che le auguro buona fortuna con le sue ricerche.]]
  },
  AvgDialog_19036_Content_60 = {
    Text = "Se non sveleremo i segreti che si celano dietro la Dissoluzione, tragedie come questa continueranno a ripetersi."
  },
  AvgDialog_19036_Content_61 = {
    Text = "La ricerca di Francis era giusta, Lily... tua madre non aveva torto.\nÈ stata solo condotta sulla strada sbagliata."
  },
  AvgDialog_19036_Content_62 = {
    Text = [[
Ma noi percorreremo la strada giusta. Combatteremo la Dissoluzione fino alla fine.
Quindi, ci aiuterai, Lily?]]
  },
  AvgDialog_19036_Content_63 = {
    Text = "<Small:Francis... Mamma...>"
  },
  AvgDialog_19036_Content_64 = {
    Text = "Al nome di Francis, Lily singhiozza, lacrime limpide che le scorrono dagli occhi."
  },
  AvgDialog_19036_Content_65 = {
    Text = "So che nessuno può sostituire tua madre."
  },
  AvgDialog_19036_Content_66 = {
    Text = "Ma noi... possiamo essere la tua famiglia anche noi."
  },
  AvgDialog_19036_Content_67 = {
    Text = "Famiglia? Bah."
  },
  AvgDialog_19036_Content_68 = {
    Text = "Lotan irrompe nella stanza, intromettendosi nella conversazione con foga."
  },
  AvgDialog_19036_Content_69 = {
    Text = "Vai a trovare Lily senza di me?\nÈ così che tratti una compagna che ha combattuto al tuo fianco?"
  },
  AvgDialog_19036_Content_7 = {
    Text = "Sì, le augureremo... ogni bene."
  },
  AvgDialog_19036_Content_70 = {
    Text = "Lotan, tu... non torni alla Pozza nera?"
  },
  AvgDialog_19036_Content_71 = {
    Text = "Stare ad aspettare è noioso. Le missioni sul campo con voi potrebbero portare avversari interessanti."
  },
  AvgDialog_19036_Content_72 = {
    Text = "Smettila di piangere, su."
  },
  AvgDialog_19036_Content_73 = {
    Text = "Lotan dà un colpetto sulla fragile spalla di Lily."
  },
  AvgDialog_19036_Content_74 = {
    Text = "Se non ti dispiace, da ora in poi puoi chiamarmi mamma."
  },
  AvgDialog_19036_Content_75 = {Text = "Com'è?"},
  AvgDialog_19036_Content_76 = {
    Text = "A.F.290, Elworth"
  },
  AvgDialog_19036_Content_77 = {
    Text = "Francis deterge delicatamente dal volto della bambina lo sporco di olio e fango nero."
  },
  AvgDialog_19036_Content_78 = {
    Text = "<Yellow:Se non ti dispiace, da ora in poi puoi chiamarmi mamma.>"
  },
  AvgDialog_19036_Content_79 = {Text = "..."},
  AvgDialog_19036_Content_8 = {Text = "..."},
  AvgDialog_19036_Content_80 = {
    Text = "Mi sento come se un peso mi fosse stato tolto dal petto."
  },
  AvgDialog_19036_Content_81 = {
    Text = "Con Lotan nei paraggi, e se frequenterà Aurita e gli altri... Lily dovrebbe ambientarsi in fretta qui."
  },
  AvgDialog_19036_Content_82 = {
    Text = "Meno male che non sono tutti impassibili come te, Doll o William. Altrimenti vivere al Mythag sarebbe dura."
  },
  AvgDialog_19036_Content_83 = {
    Text = "Cerchi di alleggerire l'atmosfera, ma Ramona non abbocca."
  },
  AvgDialog_19036_Content_84 = {Text = "Ramona?"},
  AvgDialog_19036_Content_85 = {
    Text = "Custode, dobbiamo parlare."
  },
  AvgDialog_19036_Content_86 = {
    Text = [[
Ha usato il tuo titolo, non il tuo nome.
Ti raddrizzi istintivamente.]]
  },
  AvgDialog_19036_Content_87 = {
    Text = "Durante questa indagine, la tua espressione è apparsa spesso turbata."
  },
  AvgDialog_19036_Content_88 = {
    Text = "Il peggio è stato quando hai letto il diario di Francis...\nLa tua reazione non è stata quella che mi aspettavo."
  },
  AvgDialog_19036_Content_89 = {
    Text = "La prima metà era prolissa, ma l'hai sfogliata così in fretta,\ncome se sapessi già tutto."
  },
  AvgDialog_19036_Content_9 = {
    Text = "La mamma di Lisa, Lisa ha scritto di nuovo! Dice che lei e Lady Daffodil hanno lasciato il Deserto di Remouahe, navigando attraverso l'oceano verso la nuova Repubblica di Aglo."
  },
  AvgDialog_19036_Content_90 = {
    Text = "Ho una teoria a riguardo."
  },
  AvgDialog_19036_Content_91 = {
    Text = "<Italic:Hai visto il suo sogno, vero?>"
  },
  AvgDialog_19036_Content_92 = {
    Text = "Esiti, poi riveli tutto ciò che hai visto nei sogni."
  },
  AvgDialog_19036_Content_93 = {
    Text = "L'<Yellow:Empatia> che si manifesta così intensamente in te...\nConoscevi tutta la storia, ecco perché eri così risoluto alla fine."
  },
  AvgDialog_19036_Content_94 = {
    Text = "Ci ho riflettuto in questi giorni. Per noi, i Risvegliati sono compagni, a volte persino amici a cui affideremmo la vita."
  },
  AvgDialog_19036_Content_95 = {
    Text = [[
Ma per Francis, Lily era una vita nata dalla Dissoluzione.
Per lei, non era diversa dal mostro che le aveva portato via i suoi cari.]]
  },
  AvgDialog_19036_Content_96 = {
    Text = "Esporre semplicemente la verità... le mie parole allora furono troppo dure? Ho completamente ignorato i sentimenti suoi e di Lily?"
  },
  AvgDialog_19036_Content_97 = {
    Text = "Dure o meno, i crudeli esperimenti di Francis su Lily... sono innegabili. Anche senza di noi, il <Yellow:Comitato del trattato di Mystia> le avrebbe rintracciate prima o poi."
  },
  AvgDialog_19036_Content_98 = {Text = "Hmm..."},
  AvgDialog_19036_Content_99 = {
    Text = "Vedendo il volto di Ramona incupirsi, la tua mente cerca freneticamente un nuovo argomento."
  },
  AvgDialog_19037_Content_1 = {
    Text = "Dacci una Mano, Doll!"
  },
  AvgDialog_19037_Content_2 = {
    Text = "Non serve. Se la cava da sola."
  },
  AvgDialog_19037_Content_3 = {
    Text = "Sto per addormentarmi. Nessun avversario più tosto?"
  },
  AvgDialog_19037_Content_4 = {Text = "..."},
  AvgDialog_19038_Content_1 = {
    Text = "Lily, torna in te! Sono io, %player%, e Ramona!"
  },
  AvgDialog_19038_Content_2 = {
    Text = "...%player%..."
  },
  AvgDialog_19039_Content_1 = {
    Text = "Ondata dopo ondata, ci vengono addosso come..."
  },
  AvgDialog_19039_Content_2 = {
    Text = "Ci stavano aspettando?"
  },
  AvgDialog_19040_Content_1 = {Text = "Asilo"},
  AvgDialog_19040_Content_10 = {
    Text = "Ramona sussulta, infilandosi nella stanza vuota più vicina."
  },
  AvgDialog_19040_Content_11 = {
    Text = "Uffa, Bob non è nemmeno venuto a trovarmi...\nQuando finirà tutto questo..."
  },
  AvgDialog_19040_Content_12 = {
    Text = [[
Sono qui da anni, non ho mai visto un visitatore.
Se gli importasse, non ti avrebbe mandata in un posto come questo.]]
  },
  AvgDialog_19040_Content_13 = {Text = "*sigh*..."},
  AvgDialog_19040_Content_14 = {
    Text = "Le loro chiacchiere svaniscono mentre si allontanano trascinando i piedi. Ramona si prende un momento per esaminare il suo nascondiglio."
  },
  AvgDialog_19040_Content_2 = {
    Text = "Ramona avanza in punta di piedi, scivolando silenziosamente tra le ombre del corridoio."
  },
  AvgDialog_19040_Content_3 = {
    Text = "Il Custode disapprova la sua scelta, ma cede alla sua insistenza, esortandola soltanto a ritirarsi in fretta, che abbia successo o meno."
  },
  AvgDialog_19040_Content_4 = {
    Text = "Il suo ragionamento è sensato: se solo una persona può aiutare Lily, Ramona — ancora pronta al combattimento e abile nella furtività — è la scelta migliore."
  },
  AvgDialog_19040_Content_5 = {
    Text = "Alla terza svolta, schivando pazienti che chiacchierano, Ramona esita.\nUn barlume di dubbio si insinua sul perché sia qui."
  },
  AvgDialog_19040_Content_6 = {
    Text = "Un richiamo indistinto si agita dentro di lei, un vago senso del dovere verso la bambina."
  },
  AvgDialog_19040_Content_7 = {
    Text = "Quello stesso richiamo la convince che Lily si trovi nella stanza più a est del sanatorio."
  },
  AvgDialog_19040_Content_8 = {
    Text = "Se la fortuna regge, potrà portare via Lily senza farsi notare. Poi, avvisare Mythag di setacciare il posto e scoprire perché la Tecnologia Argento ha fallito..."
  },
  AvgDialog_19040_Content_9 = {
    Text = "*Coff, coff!*"
  },
  AvgDialog_19041_Content_1 = {
    Text = "Carapace Incrinato"
  },
  AvgDialog_19041_Content_10 = {
    Text = "Questo è..."
  },
  AvgDialog_19041_Content_11 = {
    Text = "Il vero Segugio infernale."
  },
  AvgDialog_19041_Content_12 = {
    Text = "Non è il tuo primo incontro con questa bestia, ma ora ne sei certo:\nè l'obiettivo della tua indagine, la causa delle sparizioni di Rye."
  },
  AvgDialog_19041_Content_13 = {
    Text = "L'intorpidimento al cuoio capelluto, il brivido lungo la schiena — è come le ultime due volte in cui sei stata \"catturata,\" ma più acuto, più intenso."
  },
  AvgDialog_19041_Content_14 = {
    Text = "La tua Visuale si offusca di rosso."
  },
  AvgDialog_19041_Content_15 = {
    Text = "Nella foschia rosso sangue, la voce seducente di Daffodil ti sussurra all'orecchio."
  },
  AvgDialog_19041_Content_16 = {
    Text = "Toglilo. Non guardare, e la testa non ti farà male."
  },
  AvgDialog_19041_Content_17 = {
    Text = "Cosa succede se lo faccio?"
  },
  AvgDialog_19041_Content_18 = {
    Text = "Scivolerai fuori dalla coscienza, diventando pasto per il Segugio Dimensionale in tutta pace."
  },
  AvgDialog_19041_Content_19 = {
    Text = "Allora resisterò."
  },
  AvgDialog_19041_Content_2 = {
    Text = "Il terreno trema violentemente."
  },
  AvgDialog_19041_Content_20 = {
    Text = "Tiri fuori una delle fiale di Doll, fai saltare il tappo e la mandi giù d'un sorso."
  },
  AvgDialog_19041_Content_21 = {
    Text = "Il sapore non è nulla di ciò che ti aspettavi — stucchevolmente dolce, ti sale alla testa."
  },
  AvgDialog_19041_Content_22 = {
    Text = "Se avessi saputo che era così buono, ne avrei chieste di più da mescolare con l'acqua."
  },
  AvgDialog_19041_Content_23 = {
    Text = "Il fumo si propaga per la stanza, e altri mostri deformi si materializzano."
  },
  AvgDialog_19041_Content_24 = {
    Text = "Ti asciughi sangue e lacrime dagli occhi, le vene cremisi sulla mano ti esortano ad agire in fretta."
  },
  AvgDialog_19041_Content_25 = {Text = "Ramona!"},
  AvgDialog_19041_Content_26 = {
    Text = "Sì! Cataclisma \"Segugio infernale\" rilevato—preparazione al combattimento finale!"
  },
  AvgDialog_19041_Content_3 = {
    Text = "Che sta succedendo?"
  },
  AvgDialog_19041_Content_4 = {
    Text = "Le rune sulle pareti si lacerano."
  },
  AvgDialog_19041_Content_5 = {
    Text = "Un graffio accidentale mentre sottometteva Lily, un danno collaterale dello scontro con Helot, o qualcosa che Daffodil ha fatto uscendo?"
  },
  AvgDialog_19041_Content_6 = {
    Text = "Non riesci a ricordare."
  },
  AvgDialog_19041_Content_7 = {
    Text = "Non ha più importanza."
  },
  AvgDialog_19041_Content_8 = {
    Text = "Fumo viola e amorfo filtra dalle crepe della runa, raccogliendosi sul pavimento in una forma."
  },
  AvgDialog_19041_Content_9 = {
    Text = [[
La vista si affatica, i nervi pulsano incontrollabilmente.
Dalle fessure distorte emerge un mostro bestiale e frastagliato.]]
  },
  AvgDialog_19042_Content_1 = {
    Text = "Siamo circondati."
  },
  AvgDialog_19042_Content_2 = {
    Text = "Non avevamo visto così tanti mostri l'ultima volta."
  },
  AvgDialog_19042_Content_3 = {
    Text = "Tch, da dove sono sbucati fuori?"
  },
  AvgDialog_19043_Content_1 = {
    Text = "Asilo del Cuculo"
  },
  AvgDialog_19043_Content_10 = {
    Text = "A parte Mia e Koum, questo è solo un semplice sanatorio isolato."
  },
  AvgDialog_19043_Content_11 = {
    Text = "Ho agito d'impulso, ho scoperto la nostra mano. Se ci avessi riflettuto un po' di più..."
  },
  AvgDialog_19043_Content_12 = {
    Text = "Andarsene per ora"
  },
  AvgDialog_19043_Content_13 = {
    Text = "Quel che è fatto è fatto.\nRitiriamoci per ora. Potremo tornare quando avremo raccolto più informazioni."
  },
  AvgDialog_19043_Content_14 = {Text = "Esitare"},
  AvgDialog_19043_Content_15 = {
    Text = "Hai qualche idea?"
  },
  AvgDialog_19043_Content_16 = {
    Text = "Questo posto... è troppo ordinario.\nQuasi deliberatamente."
  },
  AvgDialog_19043_Content_17 = {
    Text = "Una dottoressa allestisce un piccolo sanatorio ordinato in una cittadina sperduta, nascondendosi dal mondo, mantenendo ogni cosa in perfetto ordine."
  },
  AvgDialog_19043_Content_18 = {
    Text = "E per puro caso, salva una bambina che è una Risvegliatrice?\nSono troppe coincidenze."
  },
  AvgDialog_19043_Content_19 = {
    Text = "Per ora, contattiamo Mythag."
  },
  AvgDialog_19043_Content_2 = {
    Text = "Il tempo scorre, secondo dopo secondo. Lasciando Francis alle spalle, mettete il sanatorio sottosopra — nessuna porta nascosta, nessun meccanismo segreto, nessuna stanza occultata."
  },
  AvgDialog_19043_Content_20 = {
    Text = "Ramona tocca la spilla d'argento sul petto, e tutti trattengono il respiro, in attesa della connessione."
  },
  AvgDialog_19043_Content_21 = {Text = "..."},
  AvgDialog_19043_Content_22 = {
    Text = [[
Passano dieci secondi, riempiti solo da un silenzio soffocante.
Il tuo cuore inizia a battere forte.]]
  },
  AvgDialog_19043_Content_23 = {
    Text = "Le comunicazioni... si sono interrotte di nuovo?"
  },
  AvgDialog_19043_Content_24 = {
    Text = "...Non è così semplice.\nCustode, riesci a percepire gli altri Risvegliatori?"
  },
  AvgDialog_19043_Content_25 = {
    Text = "Ti concentri, cercando il flebile filo della risonanza, ma la connessione un tempo tangibile si è spezzata, lasciando solo un vuoto accecante dall'altra parte."
  },
  AvgDialog_19043_Content_26 = {
    Text = "Persino i legami con Ramona e Lotan accanto a te sono flebili, a malapena percettibili."
  },
  AvgDialog_19043_Content_27 = {
    Text = "Riesco appena a percepire voi due, ma Mythag è completamente svanito."
  },
  AvgDialog_19043_Content_28 = {
    Text = "Sembra che la <Yellow:Tecnologia d'Argento> sia bloccata qui, o meglio, qualsiasi cosa legata alla <Yellow:Dissoluzione> viene soppressa."
  },
  AvgDialog_19043_Content_29 = {Text = "Lotan."},
  AvgDialog_19043_Content_3 = {
    Text = "Persino l'ufficio proibito non rivela nulla di straordinario."
  },
  AvgDialog_19043_Content_30 = {
    Text = "Sì, che succede?"
  },
  AvgDialog_19043_Content_31 = {
    Text = "Abbiamo perso il contatto con Mythag, e il legame del Custode con i Risvegliati è debole. Questa è un'emergenza di Classe Due. Evacuazione immediata, priorità alla sicurezza del Custode."
  },
  AvgDialog_19043_Content_32 = {
    Text = "Va bene, va bene. Lo sapevo che questo viaggio era solo un incarico da babysitter..."
  },
  AvgDialog_19043_Content_33 = {
    Text = "Evacuare? E Lily? E Koum?"
  },
  AvgDialog_19043_Content_34 = {
    Text = "Ramona sospira, lanciando un'occhiata lungo il corridoio."
  },
  AvgDialog_19043_Content_35 = {
    Text = [[
Sono con Francis da un po'; non ha motivo di far loro del male.
Noi siamo solo estranei che rappresentano una minaccia per lei.]]
  },
  AvgDialog_19043_Content_36 = {
    Text = [[
Siamo al buio, lei ha il vantaggio.
Non precipitiamoci. Torneremo a prenderli, preparati.]]
  },
  AvgDialog_19043_Content_37 = {
    Text = "Il secco ticchettio dei tacchi riecheggia nel corridoio, seguito da una voce calma come acqua immobile."
  },
  AvgDialog_19043_Content_38 = {
    Text = "Presumo abbiate controllato di nuovo il posto? Trovato qualcosa?"
  },
  AvgDialog_19043_Content_39 = {
    Text = "Ce ne andiamo."
  },
  AvgDialog_19043_Content_4 = {
    Text = "Gocce di sudore iniziano a brillare sulla fronte di Ramona."
  },
  AvgDialog_19043_Content_40 = {
    Text = "Certo, certo. Lily riceve raramente visite, ma non vi tratterrò se siete decisi ad andare."
  },
  AvgDialog_19043_Content_41 = {
    Text = "Dove sono Lily e Koum?"
  },
  AvgDialog_19043_Content_42 = {
    Text = [[
Li ho appena sistemati.
Sei sveglia, quindi non diresti qualcosa di sciocco come portarli via con te, vero?]]
  },
  AvgDialog_19043_Content_43 = {
    Text = "Vi sono grata per averla riportata indietro, ma presentarsi a casa di qualcuno e cercare di portarsi via la figlia e l'animale domestico? È un po' maleducato, non trovate?"
  },
  AvgDialog_19043_Content_44 = {
    Text = "Francis si arrotola una ciocca di capelli attorno al dito, la voce grondante di minaccia."
  },
  AvgDialog_19043_Content_45 = {
    Text = "Naturalmente. Abbiamo solo pensato fosse opportuno congedarci di persona, dato che abbiamo viaggiato insieme."
  },
  AvgDialog_19043_Content_46 = {
    Text = "Non ce n'è bisogno. Sono giovani, sfiniti dal viaggio, e già addormentati."
  },
  AvgDialog_19043_Content_47 = {
    Text = "Ho le mani piene con gli affari del Sanatorio, quindi non vi accompagnerò. Buon viaggio."
  },
  AvgDialog_19043_Content_48 = {
    Text = "Detto ciò, Francis si volta e se ne va senza un secondo sguardo. Osservi la sua sagoma svanire nelle ombre del corridoio, rendendoti conto di essere madido di sudore freddo."
  },
  AvgDialog_19043_Content_49 = {
    Text = "Lotan, scorta il Custode fuori."
  },
  AvgDialog_19043_Content_5 = {
    Text = "Ramona, il Comitato ha detto quando manderanno qualcuno?"
  },
  AvgDialog_19043_Content_50 = {Text = "E tu?"},
  AvgDialog_19043_Content_51 = {
    Text = "Ramona estrae la sua arma, il volto tenace."
  },
  AvgDialog_19043_Content_52 = {
    Text = "Vado a cercare Lily."
  },
  AvgDialog_19043_Content_6 = {
    Text = "...Sono stata con voi tutto il tempo. Mi avete vista chiamare qualcuno?"
  },
  AvgDialog_19043_Content_7 = {
    Text = "Aspetta... le stavi facendo un bluff?!"
  },
  AvgDialog_19043_Content_8 = {
    Text = "Pensavo di riuscire a farle perdere la calma con uno scuotimento, ma non ha battuto ciglio."
  },
  AvgDialog_19043_Content_9 = {
    Text = "Ho tenuto gli occhi aperti mentre perquisivamo. Non una singola traccia di D-segno in questo posto."
  },
  AvgDialog_19044_Content_1 = {
    Text = "Dopo la feroce battaglia, Lily—che attaccava proteggendo Francis—è sopraffatta, visibilmente esausta."
  },
  AvgDialog_19044_Content_10 = {
    Text = "\"...coloro che vengono cacciati tre volte da Esso vedranno le proprie anime legate agli Inferi...\""
  },
  AvgDialog_19044_Content_11 = {
    Text = "Giusto. Chiunque si trovi qui è considerato un trasgressore dimensionale — una preda per il Segugio Dimensionale."
  },
  AvgDialog_19044_Content_12 = {
    Text = "Ehi, vecchia strega, devi sapere come affrontare questa cosa!"
  },
  AvgDialog_19044_Content_13 = {
    Text = "...Sì. È semplice, in realtà."
  },
  AvgDialog_19044_Content_14 = {
    Text = "La caccia di questo mostro è <Yellow:metodica attraverso tutte le dimensioni>."
  },
  AvgDialog_19044_Content_15 = {
    Text = "Pertanto, in tutte le dimensioni, <Yellow:esiste un solo Segugio infernale.>\nIntrappolaLo in una gabbia, e non potrà fare del male a nessuno."
  },
  AvgDialog_19044_Content_16 = {
    Text = "Più facile a dirsi che a farsi! Come si ingabbia un cane che salta tra le dimensioni?"
  },
  AvgDialog_19044_Content_17 = {
    Text = "...Le rune sul muro. È apparso dopo che sono state distrutte."
  },
  AvgDialog_19044_Content_18 = {
    Text = "Occhio acuto, ragazza. Quelle rune me le ha vendute Lady Daffodil — al prezzo del mio cranio dopo la morte."
  },
  AvgDialog_19044_Content_19 = {
    Text = "Puoi ripararli?"
  },
  AvgDialog_19044_Content_2 = {
    Text = "Le sue pustole nere vengono perforate più volte. È abbastanza rapida da evitare colpi fatali, ma un combattimento prolungato la prosciugherà completamente."
  },
  AvgDialog_19044_Content_20 = {
    Text = "Francis si blocca, come se non ci avesse mai pensato."
  },
  AvgDialog_19044_Content_21 = {
    Text = "Parla! Puoi farlo o no?"
  },
  AvgDialog_19044_Content_22 = {
    Text = "Il tracciato è impresso nella mia mente.\nMa devo disegnarlo con precisione, senza un singolo errore."
  },
  AvgDialog_19044_Content_23 = {
    Text = "Mi serve più tempo."
  },
  AvgDialog_19044_Content_24 = {
    Text = "Se è solo questione di tempo, lascia fare a noi."
  },
  AvgDialog_19044_Content_25 = {
    Text = "Lotan, facciamolo!"
  },
  AvgDialog_19044_Content_26 = {
    Text = "Inferno sì, non vedevo l'ora!"
  },
  AvgDialog_19044_Content_27 = {
    Text = "Non dare tutto subito—dosati!"
  },
  AvgDialog_19044_Content_3 = {
    Text = "Non restare lì impalato! Vogliamo lasciare che una ragazzina affronti il mostro da sola?"
  },
  AvgDialog_19044_Content_4 = {
    Text = "È inutile... inutile!"
  },
  AvgDialog_19044_Content_5 = {
    Text = "Quella Bestia è un <Yellow:Mostro della causalità>."
  },
  AvgDialog_19044_Content_6 = {
    Text = "Mostro della causalità?"
  },
  AvgDialog_19044_Content_7 = {
    Text = "Esiste in virtù di causa ed effetto. Finché c'è una causa, c'è un risultato."
  },
  AvgDialog_19044_Content_8 = {
    Text = "<Yellow:Una volta che qualcuno inizia un viaggio dimensionale, Esso insegue il trasgressore.>\nIndipendentemente dal metodo, Esso non può essere distrutto finché la caccia non è completa."
  },
  AvgDialog_19044_Content_9 = {
    Text = "Questa sala operatoria è stata modificata per esistere al di fuori della dimensione temporale."
  },
  AvgDialog_19045_Content_1 = {
    Text = "Frammenti di Memoria"
  },
  AvgDialog_19045_Content_10 = {
    Text = "3. Tentativi di contenimento dei Segugi ■■■■\n3.1 Primo esperimento di contenimento:\nFallito. Impossibile limitare il loro attraversamento.\nProposte modifiche alla scala della matrice e alla precisione delle iscrizioni.\n\n3.2 51° esperimento di contenimento:\nFallito. Impossibile ■■■ il loro attraversamento.\nI soggetti braccati non possono fuggire da spazi sigillati."
  },
  AvgDialog_19045_Content_11 = {
    Text = "3.3 73° esperimento di contenimento:\nFallito. Impossibile limitare il loro attraversamento.\nTuttavia, i Segugi ■■■■ sono rimasti nello spazio sigillato per ■ minuti dopo aver completato la caccia, uscendo tramite fessure ■■■.\nProposte modifiche alla precisione delle iscrizioni cifrarie ■■.\n\n3.4 Esperimento ■■■■■■ sui Segugi ■■■■:\nRiuscito.\nConfinati con successo i Segugi ■■■■ in uno spazio di 2,86 piedi di lunghezza, 2,08 piedi di larghezza e ■ piedi di altezza.\nContinuato ■■■■■■, ma a causa di ■■ nel combattimento ■■■■, i Segugi ■■■■ ■■■ sono fuggiti.\nI calcoli suggeriscono che uno spazio rettangolare simile sia il ■■■■ ottimale per contenere i Segugi ■■■■.\nProposte migliorie a ■■■■■■■■■.\n\n3.5 ■■■■■■■■■■■■■■■■\nContenere i Segugi ■■■■ è eccessivamente difficile, ma l'auto-confinamento per eludere la caccia potrebbe essere praticabile.\n■■■■■■■■■■"
  },
  AvgDialog_19045_Content_12 = {
    Text = "Questo fascicolo è oscurato all'Inferno."
  },
  AvgDialog_19045_Content_13 = {
    Text = [[
Tipico stile di Daffodil.
Ha tutte le carte in mano e la chiama una trattativa equa.]]
  },
  AvgDialog_19045_Content_14 = {
    Text = "Abbiamo finito? Se continuiamo a perdere tempo, la tua studentella diventerà pasto per mostri."
  },
  AvgDialog_19045_Content_15 = {Text = "Partiamo."},
  AvgDialog_19045_Content_16 = {
    Text = "Prima di quello, abbiamo qualche guaio da gestire."
  },
  AvgDialog_19045_Content_17 = {
    Text = "Ramona e io siamo colleghi..."
  },
  AvgDialog_19045_Content_18 = {
    Text = "Lascia perdere — abbiamo qualche guaio da gestire."
  },
  AvgDialog_19045_Content_19 = {
    Text = "O meglio, TU hai qualche guaio da gestire."
  },
  AvgDialog_19045_Content_2 = {
    Text = "Onestamente, mi impressiona che tu riesca a dormire ovunque, in qualsiasi momento."
  },
  AvgDialog_19045_Content_20 = {
    Text = "<BigShake:ROAR!>"
  },
  AvgDialog_19045_Content_3 = {
    Text = "Dunque, qual è la situazione adesso?"
  },
  AvgDialog_19045_Content_4 = {
    Text = "Fatto. Se un problema del genere mi avesse messo in difficoltà, il mio cervello sarebbe diverso da quello di Lotan?\nMettiti questo."
  },
  AvgDialog_19045_Content_5 = {
    Text = "Doll ti porge un piccolo frammento d'argento triangolare."
  },
  AvgDialog_19045_Content_6 = {
    Text = "Inseriscila nella tua spilla — non perderla."
  },
  AvgDialog_19045_Content_7 = {
    Text = "Ah, e William ha fatto recapitare un fascicolo. Sembra che Daffodil l'abbia mandato per te."
  },
  AvgDialog_19045_Content_8 = {
    Text = "Nome in codice: Cerbero\n\nDalla scoperta delle dimensioni, attraversarle è stato un tabù per la maggior parte degli esseri. Il pericolo non risiede solo negli ambienti alieni e nello stress visivo dei dati extradimensionali, ma anche nella presenza di questo meticoloso \"esecutore\".\n<Yellow:I Segugi ■■■■ possono manifestarsi in qualsiasi dimensione, dando sistematicamente la caccia a chiunque abbia attraversato i confini dimensionali.>"
  },
  AvgDialog_19045_Content_9 = {
    Text = "1. Casi di Caccia fallita\nSolo poche specie nel cosmo possono sfuggire al loro sguardo.\nLa razza ■■ è nota per l'uso della tecnologia di trasferimento mentale per evitare la vista dei Segugi ■■■■, il che suggerisce che i Segugi non abbiano la capacità di tracciare o cacciare le menti.\nVerifica della loro logica di tracciamento tramite trasferimenti parziali fisici e mentali:\nEsperimento 1: Trasferimento della coda di un soggetto non bersaglio in un'altra dimensione. I Segugi ■■■■ non hanno inseguito.\nEsperimento 2: Amputazione del braccio di un soggetto bersaglio e trasferimento in un'altra dimensione. Il soggetto è stato divorato nella dimensione originale. I Segugi ■■■■ non hanno inseguito il braccio.\nEsperimento 3: Trasferimento della mente di un soggetto non bersaglio in un'altra dimensione. I Segugi ■■■■ non hanno inseguito.\nConclusione: I Segugi ■■■■ possono agganciare i bersagli solo quando corpo e mente sono unificati.\n\n2. Tentativi di Uccisione dei Segugi ■■■■\n■■. Le ferite letali convenzionali causano ai Segugi ■■■■ di ■■■■.\nI Segugi ■■■■ sono classificati come entità immortali; recidere la loro forma li rallenta solo temporaneamente."
  },
  AvgDialog_19046_Content_1 = {
    Text = "Hai perso di nuovo. Fanno tre."
  },
  AvgDialog_19046_Content_10 = {
    Text = [[
Quindi vuoi vendicarti del traditore, proteggere Francis che ti ha salvato.
Ma combattere non riguarda questo.]]
  },
  AvgDialog_19046_Content_11 = {
    Text = "Non per protezione, non per vendetta, non per conferme.\nCombattere è solo combattere."
  },
  AvgDialog_19046_Content_12 = {
    Text = "Il tuo mondo è troppo piccolo, sempre a inseguire il faint bagliore della luce altrui come una falena."
  },
  AvgDialog_19046_Content_13 = {
    Text = "Se ne avrai l'occasione, vai a esplorare un mondo più vasto."
  },
  AvgDialog_19046_Content_14 = {
    Text = "Lotan le passa accanto, proseguendo senza voltarsi indietro."
  },
  AvgDialog_19046_Content_2 = {
    Text = "Questo... non può essere...\nPerché?"
  },
  AvgDialog_19046_Content_3 = {
    Text = "Helot si inginocchia, sconfitta, i lunghi capelli avvolti in pozze di sangue, un rauco mormorio che le sfugge dalla gola."
  },
  AvgDialog_19046_Content_4 = {
    Text = "Se volessi liquidarti, direi che è solo potere grezzo."
  },
  AvgDialog_19046_Content_5 = {
    Text = "Ma non è quello il punto.\nI tuoi movimenti sono rapidi, le tue abilità affilate."
  },
  AvgDialog_19046_Content_6 = {
    Text = "Lotan oltrepassa Helot, Spada in Mano."
  },
  AvgDialog_19046_Content_7 = {
    Text = "Ma tu sei perduto. Stai ancora cercando una ragione per combattere."
  },
  AvgDialog_19046_Content_8 = {
    Text = "Al ponte ferroviario, eri un mostro privo di senno... tradita dal tuo connettore, giusto?"
  },
  AvgDialog_19046_Content_9 = {Text = "!"},
  AvgDialog_19047_Content_1 = {
    Text = "Interrogate alcuni pazienti lucidi nel sanatorio."
  },
  AvgDialog_19047_Content_2 = {
    Text = "Descrivono Francis come \"severa ma devota.\""
  },
  AvgDialog_19048_Content_1 = {
    Text = "Non vedrete la signora Oswood..."
  },
  AvgDialog_19049_Content_1 = {
    Text = "Quando metti piede sul sentiero acciottolato fuori dal Sanatorio, il peso opprimente finalmente si solleva."
  },
  AvgDialog_19049_Content_10 = {
    Text = "Lotan! È ora che tu e il Custode vi facciate avanti!"
  },
  AvgDialog_19049_Content_11 = {
    Text = "Sì, sì, ho capito! Non darmi ordini come se fossi il tuo cane da guardia!"
  },
  AvgDialog_19049_Content_2 = {
    Text = "La spilla d'argento brilla di vita rinnovata."
  },
  AvgDialog_19049_Content_3 = {
    Text = "Proprio mentre stai per contattare Mythag, una voce squarcia l'aria, più nitida di qualsiasi segnale radio: è Doll."
  },
  AvgDialog_19049_Content_4 = {
    Text = "Che fai lì impalato? Vieni qui a dare una mano!"
  },
  AvgDialog_19049_Content_5 = {
    Text = "Doll?! Che ci fai qui?"
  },
  AvgDialog_19049_Content_6 = {
    Text = "Con quale logica da cervello liscio ti viene da chiedere una cosa del genere? Sei stato <Yellow:irreperibile per dieci giorni> e ti chiedi perché sono qui?"
  },
  AvgDialog_19049_Content_7 = {
    Text = "Dieci giorni?! Ma io ho appena..."
  },
  AvgDialog_19049_Content_8 = {
    Text = "Non c'è tempo per le tue lungaggini da detective."
  },
  AvgDialog_19049_Content_9 = {
    Text = "All'improvviso, figure ammantate di veli neri vi circondano."
  },
  AvgDialog_19050_Content_1 = {
    Text = "L'ufficio di Francis... Il cerchio si chiude, di nuovo qui."
  },
  AvgDialog_19050_Content_2 = {
    Text = "Tanto vale perquisirlo un'altra volta."
  },
  AvgDialog_19051_Content_1 = {
    Text = "La struttura, sebbene usurata e arredata in modo spartano, è tenuta pulita.\nDopo diversi giri, non trovi nulla oltre a pazienti e forniture mediche standard."
  },
  AvgDialog_19051_Content_10 = {
    Text = "Il rischio fa parte del gioco."
  },
  AvgDialog_19051_Content_11 = {
    Text = "Ramona spalanca la pesante e fredda porta di legno."
  },
  AvgDialog_19051_Content_12 = {
    Text = "Un vento gelido irrompe fuori, seguito da una figura semi-umana che si avventa con uno strido gutturale."
  },
  AvgDialog_19051_Content_2 = {
    Text = "Alla fine, vi fermate davanti a un cartello che recita \"Ufficio del Direttore - Vietato l'ingresso.\""
  },
  AvgDialog_19051_Content_3 = {
    Text = "Se c'è un segreto in questo posto, è dietro quella porta."
  },
  AvgDialog_19051_Content_4 = {
    Text = "Vuoi che la butti giù?"
  },
  AvgDialog_19051_Content_5 = {
    Text = "Non ce n'è bisogno. Guarda—"
  },
  AvgDialog_19051_Content_6 = {
    Text = "Gira la maniglia, e la porta si apre."
  },
  AvgDialog_19051_Content_7 = {
    Text = "Non è chiusa a chiave?"
  },
  AvgDialog_19051_Content_8 = {
    Text = "Fidati, sono sorpresa quanto te."
  },
  AvgDialog_19051_Content_9 = {Text = "Entriamo."},
  AvgDialog_19052_Content_1 = {Text = "Tramonto"},
  AvgDialog_19052_Content_10 = {
    Text = "Allora non provavo dolore — per niente."
  },
  AvgDialog_19052_Content_11 = {
    Text = "Poi le cose cambiarono. La mamma mi rinchiuse, fece sempre più esperimenti."
  },
  AvgDialog_19052_Content_12 = {
    Text = "Ma non è colpa della mamma.\nEra rinchiusa in questa stanza con me, incapace di andarsene."
  },
  AvgDialog_19052_Content_13 = {
    Text = "Perché persi il controllo, uccidendo così tante persone.\nPerché... faceva così male."
  },
  AvgDialog_19052_Content_14 = {
    Text = "Lisa disse che, come mia unica amica, avrebbe cercato di restare con me più a lungo."
  },
  AvgDialog_19052_Content_15 = {
    Text = "Altrimenti, non avrebbe potuto resistere."
  },
  AvgDialog_19052_Content_16 = {
    Text = "...La verità è che nemmeno io riuscivo a resistere."
  },
  AvgDialog_19052_Content_17 = {
    Text = "La bestia gigantesca squarcia altro spazio, i suoi artigli si abbattono su Lily."
  },
  AvgDialog_19052_Content_19 = {
    Text = "Dinanzi alla Fanciulla Pallida vacillante, il pus nero forma sfere e reti, deviando i Suoi attacchi ancora e ancora."
  },
  AvgDialog_19052_Content_2 = {
    Text = "Lily avanza, i suoi teneri piedi nudi agitano il pus nero che si raccoglie intorno a lei."
  },
  AvgDialog_19052_Content_20 = {
    Text = "Ma nonostante tutto—"
  },
  AvgDialog_19052_Content_21 = {
    Text = "È la mia unica mamma."
  },
  AvgDialog_19052_Content_23 = {
    Text = "Non osare — fare del male alla mia mamma!"
  },
  AvgDialog_19052_Content_24 = {
    Text = "Le sfere di pus nero esplodono, formando spuntoni che inchiodano gli artigli del Segugio infernale."
  },
  AvgDialog_19052_Content_25 = {
    Text = "Il pus rimanente germoglia denti affilati come lame, recidendo la caviglia imprigionata."
  },
  AvgDialog_19052_Content_27 = {
    Text = "Squarcia lo spazio, il tempo congelato filtra attraverso le crepe, il tramonto divorato per intero."
  },
  AvgDialog_19052_Content_28 = {
    Text = [[
Gli artigli si dissolvono in un fumo viola demoniaco, riformandosi.
Arti alieni erompono dalle fenditure spaziali, avventandosi su Lily!]]
  },
  AvgDialog_19052_Content_3 = {
    Text = "Lisa ha detto che sua madre non l'ha riconosciuta, le ha persino sparato con un fucile."
  },
  AvgDialog_19052_Content_30 = {
    Text = "Tu e Ramona vi scambiate uno sguardo e vi unite alla mischia."
  },
  AvgDialog_19052_Content_4 = {
    Text = "Lisa ha detto che sua madre era severa, la sgridava o la picchiava ogni volta che giocavamo."
  },
  AvgDialog_19052_Content_5 = {
    Text = "Lisa ha detto che se sua madre avesse saputo che si è trasformata in un grosso cane per colpa mia, non l'avrebbe mai perdonata."
  },
  AvgDialog_19052_Content_6 = {
    Text = "Ma non poteva farne a meno. Aveva così tanta fame, e non voleva rubare, così tornò a casa per mangiare... e venne scoperta."
  },
  AvgDialog_19052_Content_7 = {
    Text = "Lily si ferma."
  },
  AvgDialog_19052_Content_8 = {
    Text = "Ma la mia mamma è diversa."
  },
  AvgDialog_19052_Content_9 = {
    Text = "Mi scambiò per qualcun altro, ma la prima volta che mi tagliò con un bisturi, chiese scusa."
  },
  AvgDialog_19053_Content_1 = {
    Text = "C'è qualcosa di strano nell'odore qui."
  },
  AvgDialog_19053_Content_2 = {
    Text = [[
Olfatto.
Tu e Koum la pensate proprio allo stesso modo.]]
  },
  AvgDialog_19053_Content_3 = {
    Text = "Non servono odori per capirlo — sono qui."
  },
  AvgDialog_19054_Content_1 = {
    Text = "Scegli sempre battaglie impossibili."
  },
  AvgDialog_19054_Content_2 = {
    Text = [[
In metropolitana, Herbert mi ha trattenuto.
La seconda volta, mi sono presentata nella mia forma peggiore.]]
  },
  AvgDialog_19054_Content_3 = {
    Text = "Ora, Francis mi ha dato una buona occasione contro di te."
  },
  AvgDialog_19054_Content_4 = {
    Text = "Nessuna fonte di energia può riparare un cuore debole."
  },
  AvgDialog_19054_Content_5 = {
    Text = "Basta parole. Senti l'ira di un'anima vendicativa!"
  },
  AvgDialog_19055_Content_1 = {
    Text = "<Shake:Ma...dre...>"
  },
  AvgDialog_19055_Content_10 = {
    Text = "Perché non hai detto a tua madre che ora riesci a sentire il dolore?"
  },
  AvgDialog_19055_Content_11 = {
    Text = "Lo senti, allora perché non lo dici mai?"
  },
  AvgDialog_19055_Content_12 = {
    Text = "<Shake:La Madre diceva... I bravi bambini... non temono il dolore...>"
  },
  AvgDialog_19055_Content_13 = {
    Text = "<Shake:Ma... mamma... fa male... Lily... fa davvero male...>"
  },
  AvgDialog_19055_Content_14 = {
    Text = "Lacrime nere, intrise di melma di Dissoluzione, rigano il volto di Lily."
  },
  AvgDialog_19055_Content_15 = {
    Text = "Lily... tu..."
  },
  AvgDialog_19055_Content_16 = {
    Text = "<Shake:Mamma... fa male...>"
  },
  AvgDialog_19055_Content_17 = {
    Text = "No... anche se provi dolore umano, sei pur sempre un mostro..."
  },
  AvgDialog_19055_Content_18 = {
    Text = "<Small:Non sei mia figlia...>\n<Small:La mia vera figlia... se n'è andata, introvabile...>"
  },
  AvgDialog_19055_Content_19 = {
    Text = [[
Francis barcolla indietro disperata, rovesciando il tavolo chirurgico.
I bisturi si spargono ovunque, tagliando la bambola sul comodino e la coperta con il coniglio sul pavimento.]]
  },
  AvgDialog_19055_Content_2 = {
    Text = "Lily, non vuoi combatterci, vero?"
  },
  AvgDialog_19055_Content_20 = {
    Text = "<Italic:Din-don... Din-don...>"
  },
  AvgDialog_19055_Content_21 = {
    Text = "Un telefono squilla all'improvviso, frantumando l'aria tesa della stanza. Nessuno risponde, eppure la voce di un uomo si riversa dalla cornetta."
  },
  AvgDialog_19055_Content_22 = {
    Text = "Salve a tutti."
  },
  AvgDialog_19055_Content_23 = {
    Text = "Herbert! Dov'è Doll?!"
  },
  AvgDialog_19055_Content_24 = {
    Text = "Lei? Ridotta in cenere davanti ai miei occhi, ovviamente."
  },
  AvgDialog_19055_Content_25 = {
    Text = "Ecco l'unità dei Mythag: abbandonare gli amici nel momento cruciale per un \"nobile sacrificio\"."
  },
  AvgDialog_19055_Content_26 = {
    Text = "Ma torniamo a noi. Ho notato che \"<Yellow:il grande>\" si avvicina. Vi state avvicinando alla verità, non è vero?"
  },
  AvgDialog_19055_Content_27 = {
    Text = "Come ricompensa per i vostri sforzi, vi donerò generosamente la risposta definitiva."
  },
  AvgDialog_19055_Content_28 = {
    Text = "\"Toc toc\"—un bussare tranquillo risuona alla porta,\nil suo ritmo disinvolto tradisce la noncuranza del visitatore."
  },
  AvgDialog_19055_Content_29 = {
    Text = "Nessuno risponde, eppure la porta si spalanca."
  },
  AvgDialog_19055_Content_3 = {
    Text = "<Shake:Questo... è... l'ordine... della Madre...>"
  },
  AvgDialog_19055_Content_30 = {
    Text = "Sulla soglia si erge una donna in viola, perennemente sorridente, composta con eleganza."
  },
  AvgDialog_19055_Content_31 = {
    Text = "Che c'è? Nessun caloroso benvenuto per me?"
  },
  AvgDialog_19055_Content_4 = {
    Text = "Lily, non vuoi obbedire alla tua Madre!"
  },
  AvgDialog_19055_Content_5 = {
    Text = "Perché hai ricordato, vero?\nSei te stessa, non più quel mostro!"
  },
  AvgDialog_19055_Content_6 = {
    Text = "Puoi <Yellow:provare dolore>, non è vero?"
  },
  AvgDialog_19055_Content_7 = {
    Text = "Con uno schiaffo secco, la vedova colpisce il volto di Lily."
  },
  AvgDialog_19055_Content_8 = {
    Text = "Lily, stringendosi la guancia, si ritira dietro %player%."
  },
  AvgDialog_19055_Content_9 = {Text = "..."},
  AvgDialog_19056_Content_1 = {
    Text = "Respingete l'inquietante creatura. Passi rapidi riecheggiano lungo il corridoio mentre la porta dell'ufficio viene spalancata dall'esterno."
  },
  AvgDialog_19056_Content_10 = {
    Text = "Il confronto diretto di Ramona vi coglie alla sprovvista."
  },
  AvgDialog_19056_Content_11 = {
    Text = "Francis inclina la testa, imperturbabile, come se le parole di Ramona non avessero colto nel segno."
  },
  AvgDialog_19056_Content_12 = {
    Text = "Sperimentazione umana? Temo ci sia stato un malinteso."
  },
  AvgDialog_19056_Content_13 = {
    Text = "Questo sanatorio ha due piani, meno di venti stanze. Ispeziono ogni centimetro ogni giorno. Se si conducessero esperimenti illegali, lo saprei."
  },
  AvgDialog_19056_Content_14 = {
    Text = "Ramona aggrotta la fronte."
  },
  AvgDialog_19056_Content_15 = {
    Text = "Non può essere il proprio stesso alibi, signora. Ne sarà sicuramente consapevole.\nE abbiamo un bel po' di prove contro di lei."
  },
  AvgDialog_19056_Content_16 = {
    Text = "Questa \"Mia\"... ha subito parecchi interventi, non è vero?"
  },
  AvgDialog_19056_Content_17 = {
    Text = [[
E Lily.
Si definisce sua madre, eppure non ha idea che non sia umana?]]
  },
  AvgDialog_19056_Content_18 = {
    Text = "Francis si ferma, poi lascia sfuggire una risatina amara."
  },
  AvgDialog_19056_Content_19 = {
    Text = "Hai capito tutto male. Lily mi chiama madre, ma non sono la sua madre biologica."
  },
  AvgDialog_19056_Content_2 = {Text = "Mia!"},
  AvgDialog_19056_Content_20 = {
    Text = "L'ho salvata da un covo di ladri. Le sue anomalie sono opera dei delinquenti che l'hanno presa per primi."
  },
  AvgDialog_19056_Content_21 = {
    Text = "Quanto a Koum e Mia, è stata Lily a portarli qui. Non so nemmeno da dove vengano."
  },
  AvgDialog_19056_Content_22 = {
    Text = "La maggior parte delle persone indietreggerebbe alla vista di Koum o Mia, o quantomeno li terrebbe lontani dai bambini."
  },
  AvgDialog_19056_Content_23 = {
    Text = "Ma in gioventù, ebbi un... incontro bizzarro. Ho visto cose che i più non possono nemmeno immaginare."
  },
  AvgDialog_19056_Content_24 = {
    Text = "Quindi, nonostante l'aspetto... insolito di Koum, l'ho tenuto per il bene di Lily."
  },
  AvgDialog_19056_Content_25 = {
    Text = "È il suo compagno più caro, e lei non lega facilmente con gli altri. Come avrei potuto separarli?"
  },
  AvgDialog_19056_Content_26 = {Text = "..."},
  AvgDialog_19056_Content_27 = {
    Text = "Se questo non chiarisce le cose, sarò lieta di farvi da scorta di nuovo per il sanatorio, compreso il mio ufficio."
  },
  AvgDialog_19056_Content_28 = {
    Text = "Non preoccupatevi, non me ne vado da nessuna parte finché non arriva il Comitato."
  },
  AvgDialog_19056_Content_3 = {Text = "Roar—"},
  AvgDialog_19056_Content_4 = {
    Text = "Ecco dove vi nascondevate. Venite con me—"
  },
  AvgDialog_19056_Content_5 = {
    Text = "Si ferma di colpo, notandoti."
  },
  AvgDialog_19056_Content_6 = {
    Text = "Credo di aver già detto che l'ufficio è off-limits."
  },
  AvgDialog_19056_Content_7 = {
    Text = "Mi spiace, ma l'orario di \"visita\" è terminato."
  },
  AvgDialog_19056_Content_8 = {
    Text = "Ai sensi dell'Articolo 81, Comma A del <Blue:Trattato>, nessun individuo, organizzazione o istituzione può condurre esperimenti su esseri umani o entità sconosciute senza l'autorizzazione del <Blue:Comitato del trattato di Mystia>."
  },
  AvgDialog_19056_Content_9 = {
    Text = "Sospettiamo che qui si pratichi la sperimentazione umana, e il <Blue:Comitato> è stato informato. Sigilleranno questo luogo. La vostra collaborazione è attesa."
  },
  AvgDialog_19057_Content_1 = {
    Text = "Da un angolo in Ombra del ponte d'acciaio, creature Grottesche si avventano su di voi, i loro agghiaccianti ruggiti riecheggiano."
  },
  AvgDialog_19057_Content_10 = {
    Text = "Quando non riusciva a respirare, desiderava poter respirare come un pesce."
  },
  AvgDialog_19057_Content_11 = {
    Text = "I suoi genitori, in cerca di una cura, viaggiavano incessantemente per commercio. Troppo debole per i lunghi tragitti, la lasciarono in un sanatorio, dove i libri di poesia erano i suoi unici compagni."
  },
  AvgDialog_19057_Content_12 = {
    Text = "...Nessuno le disse che non era una malattia, ma un misterioso fenomeno chiamato \"Dissoluzione.\""
  },
  AvgDialog_19057_Content_13 = {
    Text = "Il sanatorio la trattava come una portatrice di peste, addebitando tariffe esorbitanti. Persino chi le portava i pasti rifiutava di rivolgerle la parola."
  },
  AvgDialog_19057_Content_14 = {
    Text = "Più a lungo restava, meno i suoi genitori potevano stare con lei.\nA parte la poesia e il mare, nulla la accettava."
  },
  AvgDialog_19057_Content_15 = {
    Text = "In seguito, i suoi genitori morirono in un naufragio. Il sanatorio la cacciò, lasciandola a tornare al mare da sola."
  },
  AvgDialog_19057_Content_16 = {
    Text = "Dimmi, se un dottore che studiava la Dissoluzione le avesse dato un focolare, trattandola come una persona qualunque affetta da un fenomeno, non dovrebbe ella mostrare gratitudine attraverso le azioni?"
  },
  AvgDialog_19057_Content_17 = {
    Text = "È il momento."
  },
  AvgDialog_19057_Content_2 = {
    Text = "Dietro di loro si erge una bambina in un vestito nero."
  },
  AvgDialog_19057_Content_3 = {
    Text = "Buonasera. È un piacere rivedervi."
  },
  AvgDialog_19057_Content_4 = {
    Text = "Mi dispiace, ma potreste tutti lasciare Rye per ora?"
  },
  AvgDialog_19057_Content_5 = {
    Text = "Nymphaea, tu ti prendi cura dei pazienti. Non puoi essere all'oscuro di ciò che Francis fa qui.\nNonostante tutto, ti schieri dalla sua parte?"
  },
  AvgDialog_19057_Content_6 = {
    Text = "...Lasciate che vi racconti una storia."
  },
  AvgDialog_19057_Content_7 = {
    Text = "C'era una volta una ragazza fragile, spaventata dalla gente, confortata solo dal respiro del mare."
  },
  AvgDialog_19057_Content_8 = {
    Text = "Ma il mare portò più che pace — portò una malattia terrificante."
  },
  AvgDialog_19057_Content_9 = {
    Text = "I suoi polmoni... cominciarono a svanire."
  },
  AvgDialog_19058_Content_1 = {
    Text = "Non voltarti indietro"
  },
  AvgDialog_19058_Content_10 = {Text = "Pronti"},
  AvgDialog_19058_Content_11 = {
    Text = "Tutti prendono un respiro profondo. Lotan avanza, spalancando i cancelli del Sanatorio—"
  },
  AvgDialog_19058_Content_12 = {
    Text = "Che diavolo è successo qui?!"
  },
  AvgDialog_19058_Content_13 = {
    Text = "L'interno brilla di una luce inquietante e umbratile. Pareti e pavimenti si spaccano, rivelando voragini di Caos infinito e luce stellare."
  },
  AvgDialog_19058_Content_14 = {
    Text = [[
Breccia dimensionale.
Le manipolazioni di Francis su tempo e spazio... hanno attirato <Yellow:Lo Sguardo>.]]
  },
  AvgDialog_19058_Content_15 = {
    Text = "I Custodi del tempo e dello spazio hanno fiutato la sua traccia."
  },
  AvgDialog_19058_Content_16 = {
    Text = "Potrebbe essere il vero Segugio infernale...!"
  },
  AvgDialog_19058_Content_17 = {
    Text = [[
Concentriamoci sulla missione.
Non affrontate <Yellow:Quello> direttamente.]]
  },
  AvgDialog_19058_Content_2 = {
    Text = [[
Lasci Nymphaea dall'altro lato del ponte d'acciaio, avanzando verso l'Ospedale di Lai.
Oltre il ponte, l'aria diventa mortalmente immobile, in un silenzio agghiacciante.]]
  },
  AvgDialog_19058_Content_3 = {
    Text = "Nymphaea stava prendendo tempo. È troppo silenzioso: probabilmente i pazienti sono stati spostati.\nL'intelligence degli Scultori è impeccabile."
  },
  AvgDialog_19058_Content_4 = {
    Text = "Francis e l'Associazione degli Scultori sono alleati solo di nome."
  },
  AvgDialog_19058_Content_5 = {
    Text = "Francis si concentra sulla cura della Dissoluzione, il che si scontra con gli ideali di Herbert."
  },
  AvgDialog_19058_Content_6 = {
    Text = "Nel suo diario, trattava Herbert come un semplice collaboratore esterno."
  },
  AvgDialog_19058_Content_7 = {
    Text = "Aprite questo cancello e saremo di nuovo dentro il Sanatorio."
  },
  AvgDialog_19058_Content_8 = {
    Text = "Tutti pronti?"
  },
  AvgDialog_19058_Content_9 = {
    Text = "Pronti a menare le mani?"
  },
  AvgDialog_19059_Content_1 = {
    Text = "È più tranquillo di quanto mi aspettassi."
  },
  AvgDialog_19059_Content_10 = {
    Text = "Capito.\nScusate, ragazzi, ho una questione urgente. Sentitevi liberi di esplorare da soli—"
  },
  AvgDialog_19059_Content_11 = {
    Text = [[
Usate pure il mio nome per accedere ovunque, tranne che nel mio ufficio.
Scusatemi.]]
  },
  AvgDialog_19059_Content_12 = {
    Text = "Francis si allontana in fretta con i pazienti, la sua figura svanisce nelle ombre del corridoio."
  },
  AvgDialog_19059_Content_13 = {
    Text = "L'occasione perfetta per dare un'occhiata in giro."
  },
  AvgDialog_19059_Content_14 = {
    Text = "Esatto. Se la trasformazione di Koum è avvenuta qui, ci saranno delle tracce."
  },
  AvgDialog_19059_Content_2 = {
    Text = [[
Un malinteso comune sui pazienti isterici.
La maggior parte del tempo, sono calmi come chiunque altro.]]
  },
  AvgDialog_19059_Content_3 = {
    Text = "Anche di notte?"
  },
  AvgDialog_19059_Content_4 = {
    Text = "Ed è qui che la faccenda si complica. Di notte le lamentele raggiungono il picco."
  },
  AvgDialog_19059_Content_5 = {
    Text = "Ma non posso biasimarli. La maggior parte viene abbandonata qui dalle proprie famiglie. Di notte, sono soggetti a crisi di pianto o episodi."
  },
  AvgDialog_19059_Content_6 = {
    Text = "Francis spalanca la porta di un reparto mentre parla."
  },
  AvgDialog_19059_Content_7 = {
    Text = "Direttrice, è qui!"
  },
  AvgDialog_19059_Content_8 = {
    Text = "Sì, come se la cavano tutti?"
  },
  AvgDialog_19059_Content_9 = {
    Text = "Noi stiamo bene, ma Mia non smette di piangere e chiede di voi. Fareste meglio ad andare a controllarla."
  },
  AvgDialog_19060_Content_1 = {
    Text = "Questo è...!"
  },
  AvgDialog_19060_Content_2 = {
    Text = "Dall'angolo della stanza, un mostro nero come la pece emerse."
  },
  AvgDialog_19060_Content_3 = {
    Text = "le sue orrende suture ne tradivano le origini: un prodotto dell'Associazione degli Scultori."
  },
  AvgDialog_19061_Content_1 = {
    Text = "Francis è legata a Lily, quindi il Connettore di Helot..."
  },
  AvgDialog_19061_Content_2 = {
    Text = "Il corso <Italic:Fondamenti di Plasmatura e Connessione dei Risvegliati> menzionava che, escludendo effetti collaterali incontrollabili, i migliori connettori per i Risvegliati sono individui inabili."
  },
  AvgDialog_19061_Content_3 = {
    Text = "I pazienti del sanatorio...?"
  },
  AvgDialog_19061_Content_4 = {
    Text = "Esattamente."
  },
  AvgDialog_19061_Content_5 = {
    Text = "Lily, Nymphaea, Helot... questi pazienti sono le batterie di Francis."
  },
  AvgDialog_19062_Content_1 = {
    Text = "Meno male che Francis ha rinforzato la porta. Quel baccano non dovrebbe aver attirato nessuno."
  },
  AvgDialog_19062_Content_10 = {
    Text = "Lusinghiero, ma la scienza non è come brandire una spada — ogni fendente che versa sangue."
  },
  AvgDialog_19062_Content_11 = {
    Text = "Se avessimo consegnato tutto questo ai vecchi barbagianni del dipartimento di ricerca, ci avrebbero messo diciotto ore senza ancora trovare il problema."
  },
  AvgDialog_19062_Content_12 = {
    Text = "Ma Ramona dovrebbe essere già uscita ormai. Una rapida perlustrazione della stanza non richiede tutto questo tempo..."
  },
  AvgDialog_19062_Content_13 = {
    Text = "Non c'è bisogno di preoccuparsi. Secondo i miei calcoli...\nè lì dentro da forse dieci, quindici minuti?"
  },
  AvgDialog_19062_Content_14 = {
    Text = "Tranquillo, ho quasi finito con i numeri."
  },
  AvgDialog_19062_Content_15 = {
    Text = "Prenditi una pausa. Tra poco entriamo a recuperare la tua amica."
  },
  AvgDialog_19062_Content_16 = {
    Text = [[
Allo stesso tempo,
nella sala operatoria dell'Ospedale di Lai]]
  },
  AvgDialog_19062_Content_17 = {
    Text = "Ramona si ridesta su un letto soffice, accolta dal volto preoccupato di una bambina."
  },
  AvgDialog_19062_Content_18 = {
    Text = "<SmallShake:Dove... sono? Per quanto tempo sono stato privo di sensi?>"
  },
  AvgDialog_19062_Content_19 = {
    Text = "Si tira su a sedere, stringendosi la fronte. La luce del tramonto filtra dalla finestra, immergendo la stanza in un caldo mare d'ambra."
  },
  AvgDialog_19062_Content_2 = {
    Text = [[
Questi fascicoli... Francis stava studiando...
La Dissoluzione?!]]
  },
  AvgDialog_19062_Content_20 = {
    Text = "...Sembra quasi accogliente."
  },
  AvgDialog_19062_Content_21 = {
    Text = "No, non è un'illusione..."
  },
  AvgDialog_19062_Content_22 = {
    Text = "Ramona delira."
  },
  AvgDialog_19062_Content_23 = {
    Text = "Se non fosse stato per il freddo luccichio degli strumenti chirurgici accanto al letto, sarebbe potuta sembrare la camera di una bambina."
  },
  AvgDialog_19062_Content_24 = {
    Text = "Ramona, devi andare. Porta Koum... con te."
  },
  AvgDialog_19062_Content_25 = {
    Text = "La bambina ignora la domanda di Ramona, lascia cadere le sue parole e si volta ad accarezzare la testa di Koum."
  },
  AvgDialog_19062_Content_26 = {Text = "E tu?"},
  AvgDialog_19062_Content_27 = {
    Text = "Lily non può andare; <Yellow:Lo> noterà."
  },
  AvgDialog_19062_Content_28 = {
    Text = "Lui?... Si riferisce al \"Segugio infernale\"?"
  },
  AvgDialog_19062_Content_29 = {
    Text = "Lily, non avere paura. Veniamo da un'università che combatte le anomalie. Possiamo proteggerti."
  },
  AvgDialog_19062_Content_3 = {
    Text = "Se volevi un altro giro, bastava chiedere. Perché tutto questo intrufolarsi?"
  },
  AvgDialog_19062_Content_30 = {
    Text = [[
Nessuno sfugge al Suo sguardo.
Coloro che Esso marchia diventano la Sua preda.]]
  },
  AvgDialog_19062_Content_31 = {
    Text = "Inoltre, Lily deve restare con la Mamma.\nÈ troppo sola da sola."
  },
  AvgDialog_19062_Content_32 = {
    Text = "Ha fatto cose crudeli a te e a Koum. Non permetterò che la faccia franca."
  },
  AvgDialog_19062_Content_33 = {
    Text = "No, la Mamma non ha mentito.\nChe Koum sia diventato così... non è stata colpa sua."
  },
  AvgDialog_19062_Content_34 = {
    Text = "Puoi dirmi quello che sai?"
  },
  AvgDialog_19062_Content_35 = {
    Text = "Non c'è tempo."
  },
  AvgDialog_19062_Content_36 = {
    Text = "Un raro pianto guizza sul volto di Lily."
  },
  AvgDialog_19062_Content_37 = {
    Text = "Koum, prendila e vai."
  },
  AvgDialog_19062_Content_38 = {
    Text = "La porta scricchiola mentre la maniglia gira."
  },
  AvgDialog_19062_Content_39 = {
    Text = [[
Koum afferra Ramona, caricandosela sulla schiena.
Lei si dibatte, ma una melma nera la lega saldamente a Koum.]]
  },
  AvgDialog_19062_Content_4 = {
    Text = "Un sospiro riecheggia da dietro lo schedario."
  },
  AvgDialog_19062_Content_40 = {
    Text = "Non tornare. Dimenticami, dimentica questo posto...\nLa Madre non farà più del male a nessuno..."
  },
  AvgDialog_19062_Content_41 = {
    Text = "Sotto lo Sguardo attonito del Nuovo Arrivato, Koum Carica in avanti, travolgendolo."
  },
  AvgDialog_19062_Content_42 = {
    Text = "Francis barcolla, incapace di ritrovare l'equilibrio. Koum sfonda il varco, balzando nell'oscurità senza fondo."
  },
  AvgDialog_19062_Content_43 = {
    Text = "Ramona si volta a guardare. Lily sorregge Francis, stagliata contro il Tramonto, i suoi occhi imploranti le rivolgono un ultimo addio."
  },
  AvgDialog_19062_Content_44 = {
    Text = [[
Dimenticami.
Come tutti gli altri...]]
  },
  AvgDialog_19062_Content_5 = {Text = "?!"},
  AvgDialog_19062_Content_6 = {Text = "O forse..."},
  AvgDialog_19062_Content_7 = {
    Text = "Francis schiocca le dita. La testa di Ramona gira, la sua visuale si distorce in modo strano..."
  },
  AvgDialog_19062_Content_8 = {
    Text = "<Yellow:Ti sei lasciata influenzare da lei, vero? Sei finita dritta nel vortice?>"
  },
  AvgDialog_19062_Content_9 = {
    Text = [[
"Doll onnipotente," "Cervello in un Vaso geniale."
Sei ore e ancora non avete risolto questo problemino?]]
  },
  AvgDialog_19063_Content_1 = {
    Text = "Combatti il Segugio infernale per quello che sembra un'eternità, eppure non è così estenuante come previsto."
  },
  AvgDialog_19063_Content_10 = {
    Text = "..No! Attenta!"
  },
  AvgDialog_19063_Content_11 = {
    Text = "Tra le urla di Francis, un fumo viola si condensa rapidamente, scagliandosi contro di te e Ramona come un fulmine."
  },
  AvgDialog_19063_Content_12 = {
    Text = "Spingi Ramona di lato, frapponendoti davanti a lei. L'istinto umano ti fa chiudere gli occhi, preparandoti a un dolore da incubo."
  },
  AvgDialog_19063_Content_13 = {Text = "Guaito!"},
  AvgDialog_19063_Content_14 = {
    Text = "L'Agonia attesa non arriva. Una Bestia, trafitta da spuntoni viola, si erge davanti a te."
  },
  AvgDialog_19063_Content_15 = {
    Text = "Gli spuntoni svaniscono, lasciando non una Ferita ma un vuoto circolare."
  },
  AvgDialog_19063_Content_16 = {
    Text = "Il vuoto sembra prosciugare ogni forza di Koum. Il suo corpo massiccio si accascia, il respiro si affievolisce."
  },
  AvgDialog_19063_Content_17 = {
    Text = "Succede troppo in fretta perché tu possa reagire."
  },
  AvgDialog_19063_Content_18 = {
    Text = "Il fumo viola risorge dalle fessure, una forma colossale che squarcia le rune crepate in lacerazioni frastagliate."
  },
  AvgDialog_19063_Content_19 = {
    Text = "Il Segugio infernale rivela la sua vera forma. Ciò che era apparso prima era un mero frammento; ora, incombe come una Bestia titanica, fulminando con lo sguardo coloro che osarono proclamarsi vittoriosi."
  },
  AvgDialog_19063_Content_2 = {
    Text = [[
Eccelle nell'oppressione mentale, ma i suoi artigli infliggono danni scarsi.
Le fiale dorate di Doll alleviano notevolmente lo stress mentale.]]
  },
  AvgDialog_19063_Content_20 = {
    Text = "Nell'angolo della stanza, la Fanciulla Pallida, ormai calma, si alza, allontanandosi dall'Abbraccio della madre in lacrime."
  },
  AvgDialog_19063_Content_21 = {
    Text = "Mamma, sono così felice che mi hai riconosciuta."
  },
  AvgDialog_19063_Content_22 = {
    Text = "Sono stati %player% e Ramona ad aiutarmi a decidere...\nSono così grata a loro."
  },
  AvgDialog_19063_Content_23 = {
    Text = "Perciò, voglio aiutarli."
  },
  AvgDialog_19063_Content_3 = {
    Text = "Poco dopo, il Segugio infernale emette un guaito caotico, dissolvendosi nell'aria."
  },
  AvgDialog_19063_Content_4 = {
    Text = "Ramona lancia un'occhiata alla madre e alla figlia singhiozzanti, sospira e tocca la sua spilla."
  },
  AvgDialog_19063_Content_5 = {
    Text = "Investigatrice Ramona, richiesta di registrazione: Il \"Segugio infernale\" è sconfitto. Missione completa."
  },
  AvgDialog_19063_Content_6 = {
    Text = "Custode %player%, preparazione al Recupero della Risvegliatrice Lily, dell'entità modificata Koum, e alla detenzione del sospettato Francis Oswood..."
  },
  AvgDialog_19063_Content_7 = {
    Text = "...Segnale...Zzz...Infer..."
  },
  AvgDialog_19063_Content_8 = {
    Text = "La Voce di Erica gracchia, a malapena udibile."
  },
  AvgDialog_19063_Content_9 = {
    Text = "Erica, ci sei? Mi senti?"
  },
  AvgDialog_19064_Content_1 = {
    Text = "Gli esperimenti di Francis hanno ferito persone innocenti."
  },
  AvgDialog_19064_Content_10 = {
    Text = "Per raggiungere la signora Oswood, dovrai passare sopra di me."
  },
  AvgDialog_19064_Content_2 = {
    Text = "Intendi quelli che sono svaniti? I crudeli che hanno abbandonato le loro famiglie qui e se ne sono andati?"
  },
  AvgDialog_19064_Content_3 = {
    Text = "Mi ricordano tanti — zii, zie, cugini — che stavano accanto al mio letto, poi svanivano senza il minimo pensiero."
  },
  AvgDialog_19064_Content_4 = {
    Text = "Erano interessati alla magra eredità dei miei genitori, mai ai miei pensieri."
  },
  AvgDialog_19064_Content_5 = {Text = "..."},
  AvgDialog_19064_Content_6 = {
    Text = "Non avete intenzione di farci entrare, vero?"
  },
  AvgDialog_19064_Content_7 = {
    Text = "Nymphaea annuisce dolcemente."
  },
  AvgDialog_19064_Content_8 = {
    Text = "Voglio fare qualcosa per la signora Oswood, a qualunque costo."
  },
  AvgDialog_19064_Content_9 = {
    Text = "Sono l'unico, fragile Scudo del Personaggio di questo Sanatorio."
  },
  AvgDialog_19065_Content_1 = {
    Text = "Visto? Avere un Custode nei paraggi rende tutto molto più semplice."
  },
  AvgDialog_19065_Content_10 = {
    Text = "Non dirmi che viene dal pezzo grosso del Regno di Leonia."
  },
  AvgDialog_19065_Content_11 = {
    Text = "Molto più interessante: i soldi vengono dal capo dell'Associazione degli Scultori, <Blue:Herbert>."
  },
  AvgDialog_19065_Content_12 = {
    Text = "Come previsto."
  },
  AvgDialog_19065_Content_13 = {
    Text = "Ecco il rapporto psichiatrico di Francis."
  },
  AvgDialog_19065_Content_14 = {
    Text = "Anche lei era in terapia?"
  },
  AvgDialog_19065_Content_15 = {
    Text = "Lo sapevo che quella donna era fuori di testa.\nSparava assurdità peggio degli studenti durante gli esami!"
  },
  AvgDialog_19065_Content_16 = {
    Text = [[
Sosteneva che "suo marito e sua figlia fossero stati dissolti da una melma nera".
Il dottore l'ha definito delirio da stress e le ha prescritto dei sonniferi.]]
  },
  AvgDialog_19065_Content_17 = {
    Text = "Riusciva a vedere la <Yellow:Dissoluzione>."
  },
  AvgDialog_19065_Content_18 = {
    Text = "E pagina tre: una foto di Francis con la Squadra di Spedizione di Elworth."
  },
  AvgDialog_19065_Content_19 = {
    Text = "Questa foto è datata <Yellow:25 anni fa>?!"
  },
  AvgDialog_19065_Content_2 = {
    Text = "È così che trattate un VIP \"scomparso da dieci giorni\"?"
  },
  AvgDialog_19065_Content_20 = {
    Text = "Esatto. Dovrebbe avere 52 anni ormai, ma le foto recenti la mostrano identica a 25 anni fa."
  },
  AvgDialog_19065_Content_21 = {
    Text = "Cosa, sta lavorando all'<Yellow:immortalità>?"
  },
  AvgDialog_19065_Content_22 = {
    Text = "Questo è più o meno il massimo che il tuo cervello di muscoli riesce ad afferrare."
  },
  AvgDialog_19065_Content_23 = {
    Text = [[
Sulla base di questo, abbiamo perquisito il suo vecchio laboratorio.
Era un disastro, come se ottocento Lotan ci avessero fatto a botte dentro.]]
  },
  AvgDialog_19065_Content_24 = {Text = "Ma?"},
  AvgDialog_19065_Content_25 = {
    Text = "Ma William ha fegato. Tossendo tra la polvere, ha sgomberato le macerie e ha trovato questo in un cassetto della scrivania sfondato."
  },
  AvgDialog_19065_Content_26 = {
    Text = "Doll ti porge un taccuino consumato, la cui copertina in pelle marrone è gonfia di pagine stipate."
  },
  AvgDialog_19065_Content_27 = {
    Text = "21 novembre\n\nTutti mi fanno le congratulazioni, non solo per la mia carriera medica, ma per aver trovato l'amore.\nDomani, dopo il matrimonio, sarò Francis Oswood, e inizierò una nuova vita con @3, mio marito.\n\n11 gennaio\n\nNon abbiamo fretta di avere figli, ma @1 è comunque la prova vivente del mio amore con @3. Giuro che le darò il miglior futuro possibile."
  },
  AvgDialog_19065_Content_28 = {
    Text = "7 luglio\nA cena, @1 mi ha raccontato con entusiasmo della festa del tè che lei e @3 avevano organizzato in giardino.\nVedendo il suo sorriso gioioso, ho quasi pianto. Se potessi passare più tempo a casa, potrei ridere con loro sul prato, invece di...\nPoi @3—per l'Onnipotente, il miglior marito e padre—mi ha abbracciata da dietro. Non ha detto nulla, ma sapevo cosa intendeva.\n\n\"Non c'è bisogno di preoccuparsi, siamo e saremo sempre la famiglia più felice.\""
  },
  AvgDialog_19065_Content_29 = {
    Text = "7 febbraio\n\nDicono che sto male, che scrivere le cose potrebbe alleviare la mia mente—se non per me, almeno per @1.\n\nQuindi, dall'inizio.\n\nIl @3 @1, mentre portava @1 al parco divertimenti, @3 è crollato. Sono corsa all'ospedale dopo la chiamata, solo per vedere @3 sorridermi dolcemente, dicendomi di non preoccuparmi. Ho chiesto del buco nero sulla sua spalla. Mi ha guardata perplesso, ha detto che ero stressata dal lavoro e avevo bisogno di riposo, poi mi ha accarezzato la testa, scherzando su chi fosse il vero paziente.\n\nMa ho visto della melma nera colare dalla sua spalla.\n...Ho già visto quella melma nera, da qualche parte. Dove? Perché non riesco a ricordare?"
  },
  AvgDialog_19065_Content_3 = {
    Text = "Adesso non stai mancando il bersaglio, vero?"
  },
  AvgDialog_19065_Content_30 = {
    Text = "Dopo @3, anche @1 si è ammalata. Melma nera le colava dal petto. Non volevano credermi—non riuscivano a vederla—ma era lì, che gocciolava come fango...\n\n@3 continuava a sorridere, dicendo che aveva trasmesso una malattia senza nome a @1, ecco perché si erano ammalati entrambi. Stringevo la sua mano pallida, guardandolo deperire, la ferita nera sulla sua spalla che cresceva, e non sapevo cosa fare.\n\n...Hanno mentito. Scrivere tutto questo non aiuta."
  },
  AvgDialog_19065_Content_31 = {
    Text = "5 marzo\n<Blue:Il signor Herbert> ha fatto visita a @3 e @1 di nuovo. Ha portato a @1 i suoi biscotti preferiti.\nSono così grata. Da quando si sono ammalati, ho preso un congedo dal laboratorio, e lui mi ha pazientemente incoraggiata a passare del tempo con la famiglia.\n\nRiguardo alla melma nera, non mi ha liquidata come gli altri, non l'ha definita isteria o allucinazioni. Invece, mi ha introdotta ad alcuni studi religiosi, per lo più legati a un'organizzazione chiamata la <Blue:Chiesa della luce del tempio>."
  },
  AvgDialog_19065_Content_32 = {
    Text = "Il diario si interrompe bruscamente qui."
  },
  AvgDialog_19065_Content_33 = {
    Text = "Herbert, la Chiesa dei Portatori di Luce... È invischiata in qualcosa di grosso."
  },
  AvgDialog_19065_Content_34 = {
    Text = "Il diario sembra incompleto. Dov'è il resto?"
  },
  AvgDialog_19065_Content_35 = {
    Text = "Abbiamo messo sottosopra quel laboratorio. Non è saltato fuori nient'altro.\nIl povero William ha quasi riempito i polmoni di polvere uscendo da quel posto."
  },
  AvgDialog_19065_Content_36 = {
    Text = "A proposito, dov'è Ramona?"
  },
  AvgDialog_19065_Content_37 = {
    Text = "Stavo giusto per dirtelo..."
  },
  AvgDialog_19065_Content_4 = {
    Text = "Basta chiacchiere. Ho informazioni cruciali per te, Custode."
  },
  AvgDialog_19065_Content_5 = {
    Text = "Dopo aver perso i contatti, abbiamo indagato sul Sanatorio di Rye dall'esterno."
  },
  AvgDialog_19065_Content_6 = {
    Text = "Il posto perde soldi da anni, sopravvivendo grazie a finanziamenti esterni. Il maggiore benefattore? La <Blue:Fondazione Nathan Greene>. Seguendo quella pista, abbiamo scoperto qualcosa."
  },
  AvgDialog_19065_Content_7 = {
    Text = "Quella fondazione adora finanziare tecnologie all'avanguardia e la spinta oltre i limiti umani: sviluppo di aeronavi, spedizioni glaciali, generatori ad alta efficienza, persino roba bizzarra come l'estrazione dell'anima."
  },
  AvgDialog_19065_Content_8 = {
    Text = "Ma un sanatorio? Non è il loro stile."
  },
  AvgDialog_19065_Content_9 = {
    Text = "Scavando più a fondo, abbiamo scoperto che i fondi erano una donazione mirata. La fondazione era solo un intermediario. Il vero donatore è qualcun altro."
  },
  AvgDialog_19066_Content_1 = {Text = "Lei"},
  AvgDialog_19066_Content_10 = {
    Text = "È in quel momento che—"
  },
  AvgDialog_19066_Content_11 = {
    Text = "Francis lancia un urlo, a malapena umano."
  },
  AvgDialog_19066_Content_12 = {
    Text = "Come se stesse contemplando la visione più terrificante del mondo, scaglia via l'orologio, barcolla all'indietro, le ginocchia cedono e crolla a terra."
  },
  AvgDialog_19066_Content_13 = {
    Text = "I suoi occhi sono spalancati, le pupille si contraggono, le mani artigliano i bisturi sul pavimento. Le lame le incidono la pelle, gocce di sangue affiorano una a una."
  },
  AvgDialog_19066_Content_14 = {
    Text = "Imperturbata, Francis scalcia freneticamente, farfugliando deliri incoerenti."
  },
  AvgDialog_19066_Content_15 = {
    Text = "<BigShake:Impossibile, impossibile, non può essere, non ci crederò!>"
  },
  AvgDialog_19066_Content_16 = {
    Text = [[
Ramona si fa avanti, recuperando l'orologio.
Apre il fermaglio e te lo porge in silenzio.]]
  },
  AvgDialog_19066_Content_17 = {
    Text = "Il quadrante dell'orologio è corroso, chiazzato di decomposizione, eppure il lato interno è immacolato, come se fosse stato sigillato contro qualche liquido."
  },
  AvgDialog_19066_Content_18 = {
    Text = "All'interno, una foto mostra Francis che tiene in braccio una bambina — il ritratto sputato della Lily che conosci, fin nell'ultimo dettaglio."
  },
  AvgDialog_19066_Content_19 = {
    Text = "Me lo immaginavo..."
  },
  AvgDialog_19066_Content_2 = {
    Text = "Tutti gli occhi si volgono verso Daffodil."
  },
  AvgDialog_19066_Content_20 = {
    Text = "Il diario di Francis diceva che aveva \"risvegliato\" Lily presso l'<Blue:Altare di Elworth>."
  },
  AvgDialog_19066_Content_21 = {
    Text = "La \"plasmazione\" di un Risvegliatore necessita di un'àncora a questo mondo, e la più efficace è il <Yellow:tessuto umano>."
  },
  AvgDialog_19066_Content_22 = {
    Text = "In quel diario, Francis scrisse di aver conservato i capelli di Lily in questo orologio, portandolo con sé a Elworth."
  },
  AvgDialog_19066_Content_23 = {
    Text = "<Yellow:Lily... è la figlia di Francis>."
  },
  AvgDialog_19066_Content_24 = {
    Text = [[
Francis, rispondimi...
Pensi ancora che sia un mostro?]]
  },
  AvgDialog_19066_Content_25 = {
    Text = "La voce di Ramona è sommessa, quasi un sussurro, eppure nel silenzio opprimente della stanza risuona nitida come uno spillo che cade."
  },
  AvgDialog_19066_Content_26 = {
    Text = "Francis scuote la testa incredula, striscia all'indietro sul pavimento e si schianta contro il tavolo operatorio con un forte clangore."
  },
  AvgDialog_19066_Content_27 = {
    Text = "Lily, a piedi nudi, si avvicina a Francis."
  },
  AvgDialog_19066_Content_28 = {
    Text = "Finalmente ti ricordi... Mamma..."
  },
  AvgDialog_19066_Content_29 = {
    Text = "No... tu... stai indietro..."
  },
  AvgDialog_19066_Content_3 = {
    Text = "Sotto lo sguardo di tutti, attraversa la stanza danzando con disinvoltura, posando un orologio da taschino nella mano di Francis."
  },
  AvgDialog_19066_Content_30 = {
    Text = "La voce di Francis è rauca, tremante di paura, un lamento di protesta."
  },
  AvgDialog_19066_Content_31 = {
    Text = "I frammenti di vetro sul pavimento tagliano i piedi teneri di Lily, che guariscono all'istante. Sorda alle suppliche di Francis, si avvicina —"
  },
  AvgDialog_19066_Content_32 = {
    Text = "Solleva la mano insanguinata della donna, premendola delicatamente sulla guancia.\nPoi sorride raggiante, con una felicità mai vista prima."
  },
  AvgDialog_19066_Content_33 = {
    Text = "Mamma, va tutto bene. Non fa male, Mamma."
  },
  AvgDialog_19066_Content_34 = {
    Text = "Mamma, ti ricordi? Avevi promesso di portare Lily sulla nuova metropolitana..."
  },
  AvgDialog_19066_Content_35 = {
    Text = "Ma non si era ancora aperta, e Lily si ammalò."
  },
  AvgDialog_19066_Content_36 = {
    Text = "Anche se la mamma non c'era, Lily ha scoperto cosa si prova a viaggiare in metropolitana."
  },
  AvgDialog_19066_Content_37 = {
    Text = "Un enorme blocco di ferro, che sfreccia attraverso tunnel bui... come volare sottoterra."
  },
  AvgDialog_19066_Content_38 = {
    Text = "Quando risali in superficie, sei così lontano da dove sei partito."
  },
  AvgDialog_19066_Content_39 = {
    Text = "Noi... possiamo fare tante altre cose insieme.\nLily vuole fare così tante altre cose... con la mamma."
  },
  AvgDialog_19066_Content_4 = {
    Text = "Herbert ha insistito perché questo fosse restituito al suo legittimo proprietario."
  },
  AvgDialog_19066_Content_40 = {
    Text = "Quindi, Mamma, tocca il viso di Lily come prima, va bene?"
  },
  AvgDialog_19066_Content_41 = {
    Text = "Possiamo ricominciare?"
  },
  AvgDialog_19066_Content_42 = {Text = "..."},
  AvgDialog_19066_Content_43 = {
    Text = "Francis stringe Lily in un abbraccio forte, singhiozzando senza controllo."
  },
  AvgDialog_19066_Content_44 = {
    Text = "Lily... Lily...!"
  },
  AvgDialog_19066_Content_45 = {
    Text = "Cosa... cosa ho fatto..."
  },
  AvgDialog_19066_Content_46 = {
    Text = [[
Non piangere, mamma, non piangere...
La mamma non ha fatto niente di sbagliato. Non sapevi che Lily era Lily, e Lily non sapeva di essere se stessa.]]
  },
  AvgDialog_19066_Content_47 = {
    Text = "Se non fosse stato per gli sforzi della mamma, Lily sarebbe svanita molto tempo fa, senza poter restare al fianco della mamma così a lungo."
  },
  AvgDialog_19066_Content_48 = {
    Text = "La mamma ora ricorda Lily. Lily è così felice adesso, come se fluttuasse su una nuvola...\nQuesto basta."
  },
  AvgDialog_19066_Content_49 = {
    Text = "No, no, Lily, è tutta colpa della Mamma..."
  },
  AvgDialog_19066_Content_5 = {
    Text = "Con un sorriso enigmatico, rivolge a tutti voi un ghigno malizioso e allusivo."
  },
  AvgDialog_19066_Content_50 = {
    Text = "La Mamma si farà perdonare..."
  },
  AvgDialog_19066_Content_51 = {
    Text = "Possiamo prendere la metropolitana, andare al parco divertimenti, alla fiera..."
  },
  AvgDialog_19066_Content_52 = {
    Text = "Ovunque Lily voglia andare, la Mamma ti porterà..."
  },
  AvgDialog_19066_Content_53 = {
    Text = "La mamma resterà con te, ti renderà la bambina più felice del mondo..."
  },
  AvgDialog_19066_Content_54 = {
    Text = "Lily è già la bambina più felice del mondo, Mamma."
  },
  AvgDialog_19066_Content_6 = {
    Text = "Se avete bisogno di qualcosa — monocoli, fascicoli di Herbert — rivolgetevi a Lord Dexter, d'accordo?"
  },
  AvgDialog_19066_Content_7 = {
    Text = "Ramona stringe i denti, come per parlare, ma si fa da parte, liberando il passaggio."
  },
  AvgDialog_19066_Content_8 = {
    Text = "<Small:Vediamo come si mette.>"
  },
  AvgDialog_19066_Content_9 = {
    Text = "<Small:Capito.>"
  },
  AvgDialog_19067_Content_1 = {
    Text = "Ehi, genio, i tuoi potenziamenti sembra che non servano a un bel niente."
  },
  AvgDialog_19067_Content_10 = {
    Text = "Ramona, tutto bene?"
  },
  AvgDialog_19067_Content_11 = {
    Text = "Io sto bene, ma Lily—"
  },
  AvgDialog_19067_Content_12 = {
    Text = [[
Basta parlare di Lily. Prendi {Male=him,Female=her} e vai.
Fare da balia ai deboli mi fa venire il mal di testa.]]
  },
  AvgDialog_19067_Content_13 = {
    Text = "...Sono ancora qui, sappiatelo."
  },
  AvgDialog_19067_Content_14 = {
    Text = [[
Questo dev'essere "Koum", eh?
I gusti de Gli scultori peggiorano di giorno in giorno.]]
  },
  AvgDialog_19067_Content_15 = {
    Text = "Ramona, il tuo Indice di Gnosi è completamente sballato. Cos'è successo?"
  },
  AvgDialog_19067_Content_16 = {
    Text = "Ramona annuisce, il suo volto già offuscato si incupisce ulteriormente."
  },
  AvgDialog_19067_Content_17 = {
    Text = "Da dove dovrei cominciare?"
  },
  AvgDialog_19067_Content_18 = {
    Text = "Il Custode mi ha messo al corrente di tutto prima che ve ne andaste dal Sanatorio."
  },
  AvgDialog_19067_Content_19 = {
    Text = "Ramona racconta il tempo trascorso da sola, da quando è rimasta indietro a quando è stata trascinata via da Koum."
  },
  AvgDialog_19067_Content_2 = {
    Text = "...Non porti davvero rispetto al capo della ricerca, vero? L'\"isolamento\" qui è insidioso. Non sono un Risvegliatore del Reame Ultra, quindi non è esattamente una passeggiata."
  },
  AvgDialog_19067_Content_20 = {
    Text = "E Lily mi ha dato..."
  },
  AvgDialog_19067_Content_21 = {
    Text = "Ti guarda, poi guarda Doll e Lotan, lo sguardo carico di emozioni contrastanti."
  },
  AvgDialog_19067_Content_22 = {
    Text = "Bene, è ora di prepararsi alla battaglia.\nLotan, vieni con me un momento."
  },
  AvgDialog_19067_Content_23 = {
    Text = "Eh? Perché?"
  },
  AvgDialog_19067_Content_24 = {
    Text = [[
Nessun motivo. Hai subito un colpo mentale nell'ultimo attacco, vero?
Fammi controllare il tuo Indice Gnostico.]]
  },
  AvgDialog_19067_Content_25 = {
    Text = "Doll spinge via Lotan."
  },
  AvgDialog_19067_Content_26 = {
    Text = "Custode... no, %player%."
  },
  AvgDialog_19067_Content_27 = {
    Text = "C'è qualcosa che devi vedere."
  },
  AvgDialog_19067_Content_28 = {
    Text = "Si ferma, chiude gli occhi, deglutendo a fatica per la tensione."
  },
  AvgDialog_19067_Content_29 = {
    Text = "Ti porge una cartellina."
  },
  AvgDialog_19067_Content_3 = {
    Text = "%player%, prova il Tracciamento Spirituale."
  },
  AvgDialog_19067_Content_30 = {
    Text = [[
Ho trovato questo in un compartimento nascosto nell'ufficio di Francis.
Il quaderno all'interno... credo che l'abbia messo Lily.]]
  },
  AvgDialog_19067_Content_31 = {
    Text = "Certe decisioni spettano a te — e solo a te."
  },
  AvgDialog_19067_Content_32 = {
    Text = "Il fascicolo contiene decine di brevi registri sperimentali:"
  },
  AvgDialog_19067_Content_33 = {
    Text = "Valori di Osservazione e referti chirurgici di Pazienti da Dissoluzione a vari stadi."
  },
  AvgDialog_19067_Content_34 = {
    Text = "Hai visto fascicoli simili a Mythag, ma i metodi di Francis superano di gran lunga i tuoi limiti etici."
  },
  AvgDialog_19067_Content_35 = {
    Text = "Il quaderno sembra essere il diario di qualcuno, scritto con grafia ordinata e precisa."
  },
  AvgDialog_19067_Content_36 = {
    Text = "13 marzo\nHo prelevato campioni della melma nera, testandone le proprietà fisiche e chimiche.\nDopo l'incenerimento, una traccia di polvere argentata è rimasta nel crogiolo.\n..."
  },
  AvgDialog_19067_Content_37 = {
    Text = "3 maggio\n@1 è venuta a mancare.\n@3 non ha partecipato al suo funerale—era troppo debole per alzarsi dal letto."
  },
  AvgDialog_19067_Content_38 = {
    Text = "6 luglio\nCome l'ultima volta, l'ospedale si è occupato del funerale di @3.\nQuando li ho ringraziati per avermi aiutato a superare il dolore, mi hanno guardato in modo strano, chiedendomi cosa intendessi con \"l'ultima volta\".\n..."
  },
  AvgDialog_19067_Content_39 = {Text = "..."},
  AvgDialog_19067_Content_4 = {
    Text = "Ti concentri, cercando fili flebili di risonanza nell'aria."
  },
  AvgDialog_19067_Content_40 = {
    Text = "Scorri rapidamente le pagine.\nPer qualche ragione, le annotazioni ti sembrano familiari, come se le avessi già viste o sentite."
  },
  AvgDialog_19067_Content_41 = {
    Text = "Tu <Italic:sai> queste cose."
  },
  AvgDialog_19067_Content_42 = {
    Text = "Alla fine del primo diario, Francis decise di recarsi a Elworth, senza alcuna intenzione di fare Ritorno."
  },
  AvgDialog_19067_Content_43 = {
    Text = "La prima metà del secondo diario racconta, attraverso le Memorie, ciò che già sai. La seconda metà si fa caotica..."
  },
  AvgDialog_19067_Content_44 = {
    Text = "Il Professor Herbert è venuto di nuovo, portando \"campioni\" da Gli scultori.\nQueste persone, devastate dalla Dissoluzione, non dureranno un mese prima di svanire dal mondo.\n\n...Per curare una malattia, bisogna studiarla a fondo.\nLe persone normali non possono vedere questa melma nera. Non avrei mai potuto raccogliere così tanti casi da solo.\nLo faccio per fermare la diffusione della Dissoluzione, per risparmiare ad altri il dolore che ha sopportato mia figlia.\n...\n..."
  },
  AvgDialog_19067_Content_45 = {
    Text = "La scorsa notte, Lily ha perso il controllo.\nÈ fuggita. Il Professor Herbert mi ha avvertito che le entità appena risvegliate possono essere instabili.\n...\nDevo trovarla in fretta e lasciare la clinica."
  },
  AvgDialog_19067_Content_46 = {
    Text = "No... si può ancora chiamare clinica quel posto?\nLe attrezzature sono state polverizzate, la materia organica ridotta a melma viscosa.\nHa appiattito un'intera cassaforte fino a ridurla a un foglio sottile come un segnalibro...\nAnche i tre ricercatori inviati da Herbert sono scomparsi. Non oso immaginare cosa ne sia stato di loro...\n..."
  },
  AvgDialog_19067_Content_47 = {
    Text = "Trentacinquesima modifica, impianto del Nucleo d'Argento.\nQuesti Nuclei d'Argento, forniti da Herbert, provenivano dall'Altare di Elworth dove incontrai Lily.\nQuel posto è abbandonato ormai. Herbert ha trovato questo Nucleo d'Argento tra le ceneri.\nCon il Nucleo d'Argento, Lily ha acquisito capacità comunicative di base e una migliore obbedienza ai comandi.\n...Non era il mio obiettivo originale, ma sapere che non farà del male ad altri mi dà un po' di conforto."
  },
  AvgDialog_19067_Content_48 = {
    Text = "A volte, penso all'improvviso che Lily le assomigli.\n...Ma un mostro è un mostro. Non importa quanti interventi, non dice mai: \"Mi fa male.\"\nNon ha risposta al dolore. Per un mostro, un addome squarciato che guarisce all'istante è routine.\nEppure quello sguardo distaccato me lo ricorda: la mia @1 è perduta per sempre..."
  },
  AvgDialog_19067_Content_49 = {
    Text = "Perché non senti dolore?\nPerché non riesci a sentire dolore come una persona normale?"
  },
  AvgDialog_19067_Content_5 = {
    Text = "L'ombra di Ramona emerge nella tua mente avvolta dalla nebbia, prima come un contorno, poi più nitida."
  },
  AvgDialog_19067_Content_50 = {
    Text = "Diciottesimo anno dalla partenza da Elworth, 374° esperimento su Lily.\nUna voce nella mia mente mi dice che le risposte che cerco sono dentro di lei.\nNon riesco a resistere all'impulso di operarla."
  },
  AvgDialog_19067_Content_51 = {
    Text = "<Yellow:Mi chiama, come il marmo chiama uno Scultore, come la carta bianca chiama un Pittore.>"
  },
  AvgDialog_19067_Content_52 = {
    Text = "...\nLily è scappata di nuovo.\nNon ho tempo né mezzi per riportarla indietro adesso.\nGli esperimenti sono a una fase critica, e il \"Segugio @4\" mi tiene d'occhio.\nAlmeno Lily ora ha una cognizione di base e non farà del male agli altri a caso.\nE se dovesse succedere qualcosa... è un sacrificio necessario...\nPer il bene superiore dell'umanità..."
  },
  AvgDialog_19067_Content_53 = {
    Text = "Quella ragazza ha chiesto se qui si facessero esperimenti sugli umani... Certo che no.\n...Queste cose un tempo erano umane, ma ora sono solo mostri alieni.\nSì, solo mostri alieni.\nSono qui per curare la malattia che ha portato via mia figlia, per risparmiare ad altri il mio dolore, passo dopo passo."
  },
  AvgDialog_19067_Content_54 = {
    Text = "Sono così vicina alla risposta, a un soffio..."
  },
  AvgDialog_19067_Content_6 = {
    Text = "Si muove a una velocità disumana, avvicinandosi,\nsempre più veloce, sempre più veloce..."
  },
  AvgDialog_19067_Content_7 = {Text = "Ramona!"},
  AvgDialog_19067_Content_8 = {
    Text = "Ramona, in groppa a una bestia simile a un leone, carica verso di te, sollevando polvere mentre frena bruscamente."
  },
  AvgDialog_19067_Content_9 = {
    Text = "Smonta, e Koum si stiracchia con uno sbadiglio pigro."
  },
  AvgDialog_19068_Content_1 = {
    Text = "Lily continua a manovrare le pustole nere contro il Segugio infernale, i suoi movimenti meno agili di prima."
  },
  AvgDialog_19068_Content_10 = {
    Text = "Ramona ti copre gli occhi, afferra una fiala dalla tua tasca e te la versa in gola."
  },
  AvgDialog_19068_Content_11 = {
    Text = "Apri quella porta ed esci. Sarai libero dalla Sua portata per sempre."
  },
  AvgDialog_19068_Content_12 = {
    Text = "E... porta Lily... con te."
  },
  AvgDialog_19068_Content_13 = {
    Text = "Non vieni con noi?"
  },
  AvgDialog_19068_Content_14 = {
    Text = "Appare solo per cacciare le prede.\nSe questa stanza è vuota, perché dovrebbe restare?"
  },
  AvgDialog_19068_Content_15 = {
    Text = "Siete tutti bravi ragazzi. Devo espiare i miei peccati."
  },
  AvgDialog_19068_Content_16 = {
    Text = "Per favore... prendetevi cura di Lily."
  },
  AvgDialog_19068_Content_17 = {
    Text = "Mamma! Lily non se ne va!"
  },
  AvgDialog_19068_Content_18 = {
    Text = "Lily, fai la brava."
  },
  AvgDialog_19068_Content_19 = {
    Text = "Lily non sarà buona! Hai detto che i bambini buoni non piangono per il dolore... Lily ha ascoltato.\nQuindi questa volta, Lily non lo farà!"
  },
  AvgDialog_19068_Content_2 = {
    Text = "Cinque minuti."
  },
  AvgDialog_19068_Content_20 = {
    Text = "Alza il braccio con fatica, scagliando pustole contro il fumo viola. Il Segugio infernale le perfora all'istante, schizzando liquido viscoso."
  },
  AvgDialog_19068_Content_21 = {
    Text = "Francis ti guarda, il suo sguardo sincero quanto le sue parole."
  },
  AvgDialog_19068_Content_22 = {
    Text = "Portatela via."
  },
  AvgDialog_19068_Content_23 = {
    Text = "<Italic:Questa è l'ultima supplica di una peccatrice, una madre fallita.>"
  },
  AvgDialog_19068_Content_24 = {
    Text = "Tu e Ramona agite in sincronia."
  },
  AvgDialog_19068_Content_25 = {
    Text = "Come lei fece un tempo per Ramona, tu e Ramona issate Lily sulle spalle di Lotan."
  },
  AvgDialog_19068_Content_26 = {
    Text = "Tch, il lavoro pesante tocca di nuovo a me, eh?"
  },
  AvgDialog_19068_Content_27 = {Text = "Mamma!—"},
  AvgDialog_19068_Content_28 = {
    Text = "Lily, privata di ogni resistenza, viene portata via dallo spazio distorto, lontano da Francis—\nil luogo dell'ultimo riposo di sua madre."
  },
  AvgDialog_19068_Content_29 = {
    Text = "Mentre te ne vai, lanci uno sguardo alla finestra, tremolante di una luce stellare inquietante."
  },
  AvgDialog_19068_Content_3 = {
    Text = "Dieci minuti."
  },
  AvgDialog_19068_Content_30 = {
    Text = "Oltre si stende il caos, null'altro che luce abissale."
  },
  AvgDialog_19068_Content_31 = {Text = "..."},
  AvgDialog_19068_Content_32 = {Text = "..."},
  AvgDialog_19068_Content_33 = {
    Text = "Francis, coperto di sporcizia, avanza verso la bestia colossale."
  },
  AvgDialog_19068_Content_34 = {
    Text = "Daffodil mi aveva avvertito che anche la minima manomissione del tempo attira il mostro chiamato \"segugio di @4\"."
  },
  AvgDialog_19068_Content_35 = {
    Text = "A quei tempi, ero ossessionato dal cambiare il passato, rubando anche un solo secondo per annullare ciò che la Dissoluzione aveva portato via."
  },
  AvgDialog_19068_Content_36 = {
    Text = "Ma la cosa più importante è sempre, sempre stata al mio fianco."
  },
  AvgDialog_19068_Content_37 = {
    Text = "Stavo quasi per capire..."
  },
  AvgDialog_19068_Content_38 = {
    Text = "Sono venuto da solo per dirti una cosa fondamentale."
  },
  AvgDialog_19068_Content_39 = {
    Text = "Non consegnerò Lily a te."
  },
  AvgDialog_19068_Content_4 = {
    Text = "Quindici minuti."
  },
  AvgDialog_19068_Content_40 = {
    Text = "Ci hai riflettuto bene? Consegnami Lily, e che tu abbia sabotato dei riti o nascosto dei soggetti sperimentali, il tuo passato non ti sarà rinfacciato."
  },
  AvgDialog_19068_Content_41 = {
    Text = "La tua ricerca potrà continuare. L'Associazione continuerà a finanziarti."
  },
  AvgDialog_19068_Content_42 = {
    Text = "La Chiesa non esiterà a condividere la loro ultima tecnologia di Risveglio. Potresti creare un'altra \"Lily\"."
  },
  AvgDialog_19068_Content_43 = {
    Text = "Devo rifiutare."
  },
  AvgDialog_19068_Content_44 = {
    Text = "Dopo tutti questi anni, Lily è diventata come una figlia per me."
  },
  AvgDialog_19068_Content_45 = {
    Text = "Eppure ero cieco, rinchiuso nel passato."
  },
  AvgDialog_19068_Content_46 = {
    Text = "Nemmeno il mostro della causalità o la mia prigionia in questo piccolo sanatorio potranno fermarmi."
  },
  AvgDialog_19068_Content_47 = {
    Text = "Mamma, guarda, un manifesto della metropolitana..."
  },
  AvgDialog_19068_Content_48 = {
    Text = "Vuoi fare un viaggio, Lily? Ma non possiamo lasciare l'ospedale, scusa."
  },
  AvgDialog_19068_Content_49 = {
    Text = "L'operazione è a un punto critico. Quando starai meglio, la mamma ti porterà ovunque vorrai."
  },
  AvgDialog_19068_Content_50 = {Text = "..."},
  AvgDialog_19068_Content_51 = {
    Text = "Dunque, ho preso la mia decisione."
  },
  AvgDialog_19068_Content_52 = {
    Text = "Colpa mia, rimedio mio."
  },
  AvgDialog_19068_Content_53 = {
    Text = "Sei il mostro che ho \"risvegliato\". La mia ossessione ha aperto il passaggio dimensionale, portandoti qui."
  },
  AvgDialog_19068_Content_54 = {
    Text = "Se l'ossessione è una forma di forza mentale—"
  },
  AvgDialog_19068_Content_55 = {
    Text = "Finché la mia mente non sarà esaurita, non raggiungerai la mia bambina!"
  },
  AvgDialog_19068_Content_6 = {
    Text = "Ehi, hai finito?"
  },
  AvgDialog_19068_Content_7 = {
    Text = "Ecco, fatto."
  },
  AvgDialog_19068_Content_8 = {
    Text = "Il suo ultimo tratto completa il disegno, collegandosi come un uroboro. Il simbolo davanti a Francis forma un cifrario vertiginoso."
  },
  AvgDialog_19068_Content_9 = {
    Text = "Non fissare!"
  },
  AvgDialog_19069_Content_1 = {
    Text = "Trascendenza"
  },
  AvgDialog_19069_Content_10 = {
    Text = "Helot? Non eri già..."
  },
  AvgDialog_19069_Content_11 = {
    Text = "Qualche impiccione si è dato da fare, eh."
  },
  AvgDialog_19069_Content_12 = {
    Text = "Già, scusate. Sono strisciato fuori dall'Inferno."
  },
  AvgDialog_19069_Content_13 = {
    Text = [[
Custode, ricordi le nostre tre regole?
Lasciami affrontarla uno contro uno.]]
  },
  AvgDialog_19069_Content_14 = {
    Text = "Non preoccuparti, non perderò contro di lei."
  },
  AvgDialog_19069_Content_15 = {
    Text = "Per me va benissimo."
  },
  AvgDialog_19069_Content_16 = {
    Text = "Morbide pustole strisciano dentro con i passi di Helot, infiltrandosi tra le fessure della porta."
  },
  AvgDialog_19069_Content_17 = {
    Text = [[
Ragazzi, andate a tenere a bada gli altri.
Il mio unico avversario sei tu, Lotan.]]
  },
  AvgDialog_19069_Content_2 = {
    Text = "La stanza riecheggia di singhiozzi, in contrasto con il dolce tramonto."
  },
  AvgDialog_19069_Content_3 = {
    Text = "Chiamiamo il Comitato?"
  },
  AvgDialog_19069_Content_4 = {
    Text = "Merita un processo."
  },
  AvgDialog_19069_Content_5 = {
    Text = "Riportiamola a Mythag."
  },
  AvgDialog_19069_Content_6 = {
    Text = "D'accordo, allora.\nQualunque cosa tu decida, la porterò a termine."
  },
  AvgDialog_19069_Content_7 = {
    Text = "Signora Francis, per favore venga con noi."
  },
  AvgDialog_19069_Content_8 = {
    Text = "<Italic:Mi dispiace, non può ancora andarsene con voi.>"
  },
  AvgDialog_19069_Content_9 = {
    Text = "Il clangore di catene risuona alle spalle, come rochi, sordi scampanelli al vento."
  },
  AvgDialog_19070_Content_1 = {Text = "28 Giorni"},
  AvgDialog_19070_Content_10 = {
    Text = [[
Koum annuisce, facendoti segno di salire sulla sua schiena.
Una volta che ti sei sistemato, emette un lungo ululato e si lancia verso l'ospedale.]]
  },
  AvgDialog_19070_Content_2 = {
    Text = "Avete finito di bisbigliare?"
  },
  AvgDialog_19070_Content_3 = {
    Text = "Chiudi di scatto il taccuino, un brivido ti percorre la schiena, come se fossi stato estratto da una caverna di ghiaccio millenaria."
  },
  AvgDialog_19070_Content_4 = {
    Text = [[
Sussurro?
Aspetta, il mio Indice Gnostico non era nella norma?]]
  },
  AvgDialog_19070_Content_5 = {
    Text = "Non si può sapere senza verificare. Vederti vivace come quando ti sei Risvegliato per la prima volta mi scalda il cuore."
  },
  AvgDialog_19070_Content_6 = {
    Text = "Il Caos di Rye va ben oltre le nostre aspettative. Non possiamo permetterci di perdere tempo — muoviamoci."
  },
  AvgDialog_19070_Content_7 = {
    Text = "Doll tira fuori diversi monocoli metallici dalla forma bizzarra e delle provette\n—piene di un liquido dorato scuro."
  },
  AvgDialog_19070_Content_8 = {
    Text = "Prendi questi. Indossali quando te lo dico."
  },
  AvgDialog_19070_Content_9 = {
    Text = "Vieni con noi, piccola?"
  },
  AvgDialog_19071_Content_1 = {
    Text = "Fiume Mistico"
  },
  AvgDialog_19071_Content_10 = {
    Text = "La sfera nera emette un grottesco risucchio viscido, le labbra della ragazza si muovono all'unisono, i suoi deliri si fondono con i rumori della sfera in una sinfonia bassa e opprimente."
  },
  AvgDialog_19071_Content_11 = {
    Text = "<Shake:@2—@1—>"
  },
  AvgDialog_19071_Content_12 = {
    Text = "La sfera nera si scaglia verso i cultisti, scatenando il caos nella folla."
  },
  AvgDialog_19071_Content_13 = {
    Text = "Tu e il Colonnello Bertrand cogliete l'attimo, scivolando in un sentiero stretto."
  },
  AvgDialog_19071_Content_14 = {Text = "..."},
  AvgDialog_19071_Content_15 = {Text = "..."},
  AvgDialog_19071_Content_16 = {
    Text = "Arrancate nell'oscurità per un tempo imprecisato, inseguiti da ruggiti lontani, stridi, rantoli, deliri e farneticazioni."
  },
  AvgDialog_19071_Content_17 = {
    Text = "Presto, sali sulle mie spalle—arrampicati!"
  },
  AvgDialog_19071_Content_18 = {
    Text = [[
Con la spinta di Bertrand, ti arrampichi fuori dallo stretto tunnel.
Un abbagliante campo innevato si stende davanti a te.]]
  },
  AvgDialog_19071_Content_19 = {
    Text = "Aspetta, sono accecato dalla neve... Ti tiro su tra poco..."
  },
  AvgDialog_19071_Content_2 = {
    Text = "Presto, l'uscita è proprio lì!"
  },
  AvgDialog_19071_Content_20 = {
    Text = "Non serve, ce la faccio..."
  },
  AvgDialog_19071_Content_21 = {
    Text = "Prima che Bertrand finisca, il terrore gli deforma il volto."
  },
  AvgDialog_19071_Content_22 = {
    Text = "Dallo spazio tra lui e l'uscita del tunnel, innumerevoli tentacoli liquidi, spessi e guizzanti, erompono."
  },
  AvgDialog_19071_Content_23 = {
    Text = "Si avvolgono attorno al corpo di Bertrand con una volontà propria."
  },
  AvgDialog_19071_Content_24 = {
    Text = "Si aggrappa al terreno, le dita che scavano, ma la neve non offre presa. In un respiro, viene trascinato giù."
  },
  AvgDialog_19071_Content_25 = {
    Text = "Poi, un suono snervante assale le tue orecchie..."
  },
  AvgDialog_19071_Content_26 = {
    Text = [[
Contorcimenti, masticazioni, ossa che cozzano...
persino il gorgoglio dei fluidi digestivi contro la materia organica risuona nitido.]]
  },
  AvgDialog_19071_Content_27 = {
    Text = [[
...Dopo secondi di terrore agghiacciante, cala il silenzio.
Solo il vento carico di neve fruscia, spolverando il terreno.]]
  },
  AvgDialog_19071_Content_28 = {
    Text = "La nausea ti sale dallo stomaco al petto. Vomiti sulla neve."
  },
  AvgDialog_19071_Content_29 = {Text = "Ugh..."},
  AvgDialog_19071_Content_3 = {
    Text = "Segui lo sguardo di Ramona, e una luce bianca accecante ti inonda la visuale."
  },
  AvgDialog_19071_Content_30 = {
    Text = "Le lacrime sgorgano incontenibili, se per il dolore o per la paura, non sai dirlo."
  },
  AvgDialog_19071_Content_31 = {
    Text = "Cerchi l'orologio da tasca, sperando in un po' di conforto,\nma la tasca è vuota."
  },
  AvgDialog_19071_Content_32 = {
    Text = "...Non hai recuperato nulla."
  },
  AvgDialog_19071_Content_33 = {
    Text = "Una mano fredda si posa sulla tua spalla."
  },
  AvgDialog_19071_Content_34 = {
    Text = "Pericolo, Madre. Vi prego, datemi ordini."
  },
  AvgDialog_19071_Content_35 = {Text = "..."},
  AvgDialog_19071_Content_36 = {Text = "..."},
  AvgDialog_19071_Content_37 = {
    Text = [[
Dopo giorni di cammino, i mostri e i cultisti all'inseguimento svaniscono nel campo innevato.
Tu e la ragazza togliete un po' di neve, rannicchiandovi accanto a un fuoco.]]
  },
  AvgDialog_19071_Content_38 = {
    Text = "Ogni tanto si allontana, tornando con pezzi sanguinolenti di creature sconosciute."
  },
  AvgDialog_19071_Content_39 = {
    Text = "Eviti di fare domande, arrostendo la carne sul fuoco, ignorando odore e sapore pur di ingoiare quelle rare proteine."
  },
  AvgDialog_19071_Content_4 = {
    Text = "La tua vista si dissolve in una foschia bianca e granulosa, come cecità da neve."
  },
  AvgDialog_19071_Content_40 = {
    Text = "La bambina non sembra aver bisogno di cibo, ma se gliene offri, lo divora voracemente."
  },
  AvgDialog_19071_Content_41 = {
    Text = "Hai un nome?"
  },
  AvgDialog_19071_Content_42 = {
    Text = "Mastica carne succosa, scuotendo la testa."
  },
  AvgDialog_19071_Content_43 = {
    Text = "E la... famiglia? Sai dove sono i tuoi genitori?"
  },
  AvgDialog_19071_Content_44 = {Text = "..."},
  AvgDialog_19071_Content_45 = {
    Text = "Ti lancia un'occhiata, poi guarda le cime lontane, quindi il cielo sconfinato, e scuote la testa."
  },
  AvgDialog_19071_Content_46 = {
    Text = "...Ti serve ancora un nome."
  },
  AvgDialog_19071_Content_47 = {
    Text = "Che ne dici di <Blue:Lily>?"
  },
  AvgDialog_19071_Content_48 = {
    Text = "Qualunque nome la Madre scelga per me, quello sarà il mio nome."
  },
  AvgDialog_19071_Content_49 = {
    Text = "Non sono la tua padrona..."
  },
  AvgDialog_19071_Content_5 = {
    Text = [[
Nel caos distorto, la tua coscienza viene strappata dal corpo, i tuoi sensi scagliati in una dimensione lontana e gelida.
Il <Yellow:Sogno> ti visita di nuovo...]]
  },
  AvgDialog_19071_Content_50 = {
    Text = "Madre, attenzione. Qualcosa ci sta raggiungendo."
  },
  AvgDialog_19071_Content_51 = {
    Text = "Come?! Siamo quasi fuori dalla Distesa Innevata..."
  },
  AvgDialog_19071_Content_52 = {
    Text = [[
I tuoi nervi bruciano, la coscienza compressa e stirata.
Il <Yellow:Sogno> ti respinge, cercando di espellerti dal suo mondo bianco.
Ma...]]
  },
  AvgDialog_19071_Content_53 = {
    Text = "No... non posso lasciare che li prendano... nemmeno nel mio sogno...!"
  },
  AvgDialog_19071_Content_6 = {Text = "..."},
  AvgDialog_19071_Content_7 = {
    Text = "Ciò che è accaduto a Elworth sfida tutto ciò che <Yellow:tu> conosci, ma non c'è tempo per la confusione—questioni più urgenti attendono."
  },
  AvgDialog_19071_Content_8 = {
    Text = "Aiutami... fermali."
  },
  AvgDialog_19071_Content_9 = {
    Text = "Sì, Madre."
  },
  AvgDialog_19072_Content_1 = {
    Text = "Una scatola chiusa a chiave sullo scaffale..."
  },
  AvgDialog_19072_Content_2 = {
    Text = "Una chiave nascosta dietro il quadro..."
  },
  AvgDialog_19073_Content_1 = {
    Text = "I ruggiti svaniscono nelle ombre, e la melma nera sul pavimento del corridoio evapora come acqua in ebollizione."
  },
  AvgDialog_19073_Content_10 = {
    Text = "Non c'è fretta di lanciarsi frecciate.\nCosa ne dici della mia offerta, signorina Doll?"
  },
  AvgDialog_19073_Content_11 = {
    Text = "Non ti importa della sopravvivenza dell'umanità, vero?"
  },
  AvgDialog_19073_Content_12 = {Text = "Esatto."},
  AvgDialog_19073_Content_13 = {Text = "Bambola?"},
  AvgDialog_19073_Content_14 = {
    Text = "A differenza loro, mi sono liberato del corpo umano molto tempo fa. Il Fato della gente comune non significa nulla per me."
  },
  AvgDialog_19073_Content_15 = {
    Text = "Come Ricercatore che insegue tecnologie all'avanguardia, chi non vorrebbe liberarsi dell'etica umana e condurre gli esperimenti più sfrenati?"
  },
  AvgDialog_19073_Content_16 = {Text = "Ma..."},
  AvgDialog_19073_Content_17 = {
    Text = "Rispetto a un opportunista senza spina dorsale come te, rispetto il coraggio di questa gente che lotta contro ogni probabilità."
  },
  AvgDialog_19073_Content_18 = {
    Text = "Basta chiacchiere.\nContinua a temporeggiare e Francis sarà già a metà oceano con Lily."
  },
  AvgDialog_19073_Content_19 = {
    Text = "Come ci si aspetta dal Cervello di Mythag: nulla ti sfugge."
  },
  AvgDialog_19073_Content_2 = {
    Text = "Le <Yellow:cavie> dell'Associazione degli Scultori—economiche ed efficaci."
  },
  AvgDialog_19073_Content_20 = {
    Text = "Herbert batte le mani, e una dozzina di porte si spalancano."
  },
  AvgDialog_19073_Content_21 = {
    Text = "Una malevolenza agghiacciante si propaga nell'oscurità, lo stretto corridoio riecheggia di ruggiti grotteschi."
  },
  AvgDialog_19073_Content_22 = {
    Text = "Ramona, %player%!"
  },
  AvgDialog_19073_Content_23 = {
    Text = "Siamo arrivati!"
  },
  AvgDialog_19073_Content_24 = {
    Text = "Mi occupo io di questo Vecchio Amico. Tu ferma Francis."
  },
  AvgDialog_19073_Content_25 = {
    Text = "Quei monocoli che ti ho dato—indossali per vedere la <Yellow:Porta> verso altre dimensioni."
  },
  AvgDialog_19073_Content_26 = {
    Text = "Non toglierli se non è strettamente necessario. Le vertigini sono normali. Se peggiorano, bevi una fiala."
  },
  AvgDialog_19073_Content_27 = {Text = "Ma tu—"},
  AvgDialog_19073_Content_28 = {Text = "Avanti!"},
  AvgDialog_19073_Content_29 = {
    Text = "Mythag e l'Associazione degli Scultori si danno battaglia da anni. Se potesse abbatterci, non avrebbe aspettato tutto questo tempo."
  },
  AvgDialog_19073_Content_3 = {
    Text = "Spero che tu non stia pensando a qualcosa di troppo sinistro."
  },
  AvgDialog_19073_Content_30 = {
    Text = "Che la Chiave d'Argento Illumini il Cammino."
  },
  AvgDialog_19073_Content_31 = {Text = "..."},
  AvgDialog_19073_Content_32 = {
    Text = "Che la Chiave d'Argento ci Guidi."
  },
  AvgDialog_19073_Content_33 = {
    Text = "Indossi il monocolo di metallo e, insieme a Ramona, ti lanci verso il corridoio più a est."
  },
  AvgDialog_19073_Content_34 = {
    Text = "Con la coda dell'occhio, le dozzine di cavie di Herbert circondano Doll, sbavando irrequiete."
  },
  AvgDialog_19073_Content_35 = {
    Text = "Non guardare! Doll ha detto che può farcela."
  },
  AvgDialog_19073_Content_36 = {
    Text = "Fidati di lei e concentrati sulla nostra missione!"
  },
  AvgDialog_19073_Content_4 = {
    Text = "Non sarebbe una sorpresa, vero?\nNon è che siamo esattamente dalla parte della gente comune."
  },
  AvgDialog_19073_Content_5 = {
    Text = "Se la pensi così, perché non ti unisci a noi?"
  },
  AvgDialog_19073_Content_6 = {
    Text = "Le tecnologie della <Yellow:civiltà Alaemyces> mi affascinano da tempo immemore."
  },
  AvgDialog_19073_Content_7 = {
    Text = [[
Raro vederti di persona, Herbert.
Pensavo odiassi mostrare la faccia.]]
  },
  AvgDialog_19073_Content_8 = {
    Text = "Beh, l'Associazione degli Scultori ha investito molto in questa \"genio\". Se la elimini, i nostri sforzi vanno in Spreco."
  },
  AvgDialog_19073_Content_9 = {
    Text = "Sei troppo sicuro di te. I tuoi sforzi non sono mai confluiti da nessun'altra parte, in primo luogo."
  },
  AvgDialog_19074_Content_1 = {
    Text = "Finestra segreta"
  },
  AvgDialog_19074_Content_10 = {
    Text = "Perché altrimenti non abbiamo trovato nulla?"
  },
  AvgDialog_19074_Content_11 = {
    Text = "Quella luce in lontananza..."
  },
  AvgDialog_19074_Content_12 = {
    Text = "È l'ossessione più profonda del proprietario di quella mente, qualcosa che non riesce a dimenticare."
  },
  AvgDialog_19074_Content_13 = {
    Text = "Sembra il quadrante di un orologio."
  },
  AvgDialog_19074_Content_14 = {
    Text = "Cosa, vuole diventare la padrona del tempo?"
  },
  AvgDialog_19074_Content_15 = {
    Text = "Aveva bisogno di così tanto tempo per raggiungere il suo obiettivo, perciò si è rinchiusa in quella stanza."
  },
  AvgDialog_19074_Content_16 = {
    Text = "Si è chiusa dentro?"
  },
  AvgDialog_19074_Content_17 = {
    Text = "Sì. Il costo del viaggio dimensionale non è qualcosa che i più possano sopportare."
  },
  AvgDialog_19074_Content_18 = {
    Text = "Ogni volta che lascia quella stanza, corre un rischio enorme —"
  },
  AvgDialog_19074_Content_19 = {Text = "Attento!"},
  AvgDialog_19074_Content_2 = {
    Text = "Tu e Ramona correte verso est lungo il corridoio. Presto, un muro si staglia davanti a voi."
  },
  AvgDialog_19074_Content_20 = {
    Text = "Un caotico mostro triangolare emerge dalla melma nera sotto i tuoi piedi."
  },
  AvgDialog_19074_Content_21 = {
    Text = "Andate via di qui!"
  },
  AvgDialog_19074_Content_3 = {
    Text = "Un rozzo disegno infantile è appeso in alto sulla parete bianca—una madre che gioca con la sua bambina—\nma dove dovrebbe esserci la bambina, resta solo melma nera."
  },
  AvgDialog_19074_Content_4 = {
    Text = "Un Vicolo Cieco?"
  },
  AvgDialog_19074_Content_5 = {
    Text = [[
No... fidati del tuo istinto.
Attraversa.]]
  },
  AvgDialog_19074_Content_6 = {
    Text = "Nell'istante in cui attraversi il muro, il dipinto sembra tremolare—\nla figura della bambina appare brevemente, poi sprofonda di nuovo nell'oscurità."
  },
  AvgDialog_19074_Content_7 = {
    Text = "Questo spazio..."
  },
  AvgDialog_19074_Content_8 = {
    Text = "Se ho ragione, questo è un passaggio formato dalla coscienza di Francis."
  },
  AvgDialog_19074_Content_9 = {
    Text = "Ben nascosto."
  },
  AvgDialog_19075_Content_1 = {Text = "Stanza"},
  AvgDialog_19075_Content_10 = {
    Text = "Francis è in piedi accanto alla finestra, le mani intrecciate dietro la schiena, lo sguardo perso in lontananza."
  },
  AvgDialog_19075_Content_11 = {
    Text = [[
Hai tradito la gentilezza di Lily.
Prima che Herbert si intromettesse, avremmo potuto separarci in pace.]]
  },
  AvgDialog_19075_Content_12 = {
    Text = "Non staremo a guardare mentre commettete atrocità."
  },
  AvgDialog_19075_Content_13 = {
    Text = "Atrocità... È così che mi vedi?\nUn mostro, una pazza, una criminale?"
  },
  AvgDialog_19075_Content_14 = {
    Text = "Non sono come Herbert. Non ho mai fatto del male a nessuno volontariamente."
  },
  AvgDialog_19075_Content_15 = {
    Text = "Forse non ai tuoi occhi, ma quegli esseri umani alterati... potrebbero ancora avere qualcuno che tiene a loro."
  },
  AvgDialog_19075_Content_16 = {
    Text = "So che siete persone gentili e rette, ma siete troppo giovani."
  },
  AvgDialog_19075_Content_17 = {
    Text = "Ho curato ex detenuti, rifiutati da tutti una volta che il loro passato veniva a galla, anche dopo un sincero pentimento."
  },
  AvgDialog_19075_Content_18 = {
    Text = "Le persone sono plasmate dalle loro esperienze.\nDopo certe esperienze, non sono più umane, né dovrebbero essere trattate come tali."
  },
  AvgDialog_19075_Content_19 = {
    Text = "Non è solo il mio punto di vista: è così che il mondo li vede."
  },
  AvgDialog_19075_Content_2 = {
    Text = "Eccoci. Lily e Francis... dovrebbero essere là dentro."
  },
  AvgDialog_19075_Content_20 = {
    Text = "Anche se non considerate umane le vittime della Dissoluzione, che dire delle loro famiglie che li hanno mandati qui?"
  },
  AvgDialog_19075_Content_21 = {
    Text = [[
Sono stati divorati dal Segugio infernale, vero?
Opera tua. Ed erano innegabilmente, puramente umani.]]
  },
  AvgDialog_19075_Content_22 = {
    Text = "Coloro che abbandonano i propri cari malati o anziani in questo remoto Sanatorio... non meritano forse una Punizione?"
  },
  AvgDialog_19075_Content_23 = {
    Text = "Non la morte. Non avete il diritto di giudicarli."
  },
  AvgDialog_19075_Content_24 = {
    Text = [[
Non ho il diritto di giudicarli...
E tu hai il diritto di giudicare me?]]
  },
  AvgDialog_19075_Content_25 = {
    Text = "Sai dove siamo? Questa è la stanza di mia figlia.\nIl tempo qui è fermo al crepuscolo in cui è scomparsa."
  },
  AvgDialog_19075_Content_26 = {
    Text = "Ho tentato di tutto per tenerla con me, anche a costo di vendere l'anima al diavolo.\nMa... nessun diavolo è venuto, e lei mi è stata portata via lo stesso."
  },
  AvgDialog_19075_Content_27 = {
    Text = "Ho dato a <Blue:Lily> il suo nome, ma non è mia figlia.\nÈ solo un mostro, della stessa età della mia bambina."
  },
  AvgDialog_19075_Content_28 = {
    Text = "Sul tavolo operatorio, la cavità nel petto di Lily si richiude lentamente, e il Colore torna nei suoi Occhi vacui."
  },
  AvgDialog_19075_Content_29 = {
    Text = "È il soggetto di studio perfetto. Non importa quante Ferite le infligga, guarisce. L'intervento non si ferma mai per il Pain."
  },
  AvgDialog_19075_Content_3 = {
    Text = "Siamo fuori dal passaggio dimensionale. Come ti senti? Ancora capogiri o nausea?"
  },
  AvgDialog_19075_Content_30 = {
    Text = "Ma tutto ciò che volevo era mia figlia! Una Bambina normale che piange, ride e si lamenta con me quando soffre!"
  },
  AvgDialog_19075_Content_31 = {
    Text = "Quelle persone... coloro che abbandonano i propri cari... hanno già perso la loro Umanità!"
  },
  AvgDialog_19075_Content_32 = {
    Text = "Persone che hanno perso la loro umanità—puoi ancora chiamarle umane?\nMostri che diventano preda del Segugio infernale—non è forse appropriato?"
  },
  AvgDialog_19075_Content_33 = {
    Text = "Avete perso ogni ragione."
  },
  AvgDialog_19075_Content_34 = {
    Text = "Per una volta, siamo d'accordo."
  },
  AvgDialog_19075_Content_35 = {
    Text = "Francis avanza, accarezzando dolcemente la guancia pallida e delicata di Lily, la sua tenerezza stridente con le sue parole feroci."
  },
  AvgDialog_19075_Content_36 = {
    Text = "Sapevo che non avreste capito."
  },
  AvgDialog_19075_Content_37 = {
    Text = "Mormora, la sua voce appena udibile."
  },
  AvgDialog_19075_Content_38 = {
    Text = "Alla terza ripetizione della sua Cantilena sussurrata, ne discernete la cadenza—"
  },
  AvgDialog_19075_Content_39 = {
    Text = "<Italic:@2—@1—>"
  },
  AvgDialog_19075_Content_4 = {
    Text = "Molto meglio. Anche se qualcosa mi colpisce, andrò avanti."
  },
  AvgDialog_19075_Content_40 = {
    Text = "<Italic:@2—@1—>"
  },
  AvgDialog_19075_Content_41 = {
    Text = "<Italic:@2—@1—>"
  },
  AvgDialog_19075_Content_42 = {
    Text = "Il Mostro dormiente si desta. Lily, prima distesa, si alza rigidamente, i suoi Occhi brillano di un verde sinistro."
  },
  AvgDialog_19075_Content_43 = {
    Text = "<Change>Ritorno al nido primordiale..."
  },
  AvgDialog_19075_Content_44 = {
    Text = "<Change>Ritorno al Reame eterno..."
  },
  AvgDialog_19075_Content_45 = {
    Text = "<Change>Ritorno all'Abbraccio della Madre..."
  },
  AvgDialog_19075_Content_46 = {
    Text = "<Change>Per la Madre, eliminateli."
  },
  AvgDialog_19075_Content_47 = {Text = "Ssssh—"},
  AvgDialog_19075_Content_48 = {
    Text = "Ramona, trova un modo per svegliare Lily!"
  },
  AvgDialog_19075_Content_49 = {Text = "Capito!"},
  AvgDialog_19075_Content_5 = {
    Text = "Con un respiro profondo, spingi la porta, grondante di melma viscosa, e varchi la soglia dell'ultima camera."
  },
  AvgDialog_19075_Content_6 = {
    Text = "Un tramonto senza tempo bagna la stanza, il cui arredo accogliente e femminile irradia calore."
  },
  AvgDialog_19075_Content_7 = {
    Text = [[
La bambola sul comodino, il vestito rosa sull'appendiabiti, il baldacchino ornato di pizzo...
tutto stridentemente fuori posto nel gelido squallore del sanatorio.]]
  },
  AvgDialog_19075_Content_8 = {
    Text = "Al centro, su un tavolo chirurgico, giace una piccola figura familiare, una voragine spalancata nel petto, immobile come la morte."
  },
  AvgDialog_19075_Content_9 = {Text = "Lily!"},
  AvgDialog_19076_Content_1 = {
    Text = "Bocca del Folle"
  },
  AvgDialog_19076_Content_10 = {
    Text = "Ramona risponde con un sommesso \"Mm\", ma il suono viene divorato dal vuoto, e il silenzio torna a regnare."
  },
  AvgDialog_19076_Content_11 = {
    Text = "Lily, stai per vedere la tua mamma. Sei emozionata?"
  },
  AvgDialog_19076_Content_12 = {
    Text = "Sì... Mamma..."
  },
  AvgDialog_19076_Content_13 = {
    Text = "La mano delicata di Lily si aggrappa stretta alle tue dita, il palmo leggermente umido di sudore. Le dai una stretta rassicurante."
  },
  AvgDialog_19076_Content_14 = {
    Text = "Se non vuoi restare qui, che ne dici di venire con noi a Mythag?"
  },
  AvgDialog_19076_Content_15 = {
    Text = "Mio padre mi ha accolta anni fa; sono sicura che non avrebbe nulla in contrario ad accoglierne un'altra.\nMi piacerebbe avere una sorellina così dolce."
  },
  AvgDialog_19076_Content_16 = {
    Text = "Non si tratta di quello. Lily, lei..."
  },
  AvgDialog_19076_Content_17 = {
    Text = "<Blue:Helot>. Se mi chiedi il mio ruolo, sono qualcosa come sua sorella.\nPiù precisamente, i nostri poteri sono <Yellow:\"della stessa origine\">."
  },
  AvgDialog_19076_Content_18 = {
    Text = "Se Helot dice il vero, la bambina gentile che ti tiene per mano è senza dubbio una <Yellow:Risvegliatrice>."
  },
  AvgDialog_19076_Content_19 = {
    Text = "Capisco. Ma abbiamo te, no?\nUn collegamento temporaneo dovrebbe reggere finché non riusciremo a connetterla alla Vasca Nera dell'università."
  },
  AvgDialog_19076_Content_2 = {
    Text = "Mentre attraversi il ponte ferroviario verso il Sanatorio di Rye, l'alba si leva all'orizzonte, diffondendo un pallido chiarore."
  },
  AvgDialog_19076_Content_20 = {
    Text = "La stretta di Lily si fa più forte. I suoi occhi guizzano tra Ramona e te, colmi di inquietudine."
  },
  AvgDialog_19076_Content_21 = {
    Text = "Lily... vuole ancora stare con la Mamma.\nPerché... Lily ha solo una mamma, e la Mamma ha solo una Lily."
  },
  AvgDialog_19076_Content_22 = {
    Text = "La Mamma non ha scelto di diventare così.\n<Small:Ha perso qualcosa di prezioso, e sta cercando di riprenderselo, ecco perché...>"
  },
  AvgDialog_19076_Content_23 = {
    Text = "La sua voce sfuma in un sussurro, quasi sommersa dal suono del suo stesso respiro."
  },
  AvgDialog_19076_Content_24 = {
    Text = "<SmallShake:Hiss—>"
  },
  AvgDialog_19076_Content_25 = {
    Text = "Siete finalmente arrivati. Benvenuti a Rye, al Sanatorio."
  },
  AvgDialog_19076_Content_26 = {
    Text = "Lily, perché non vai a riposare con Nymphaea per ora?"
  },
  AvgDialog_19076_Content_27 = {
    Text = [[
Andiamo, Lily.
Devi essere esausta dal viaggio.]]
  },
  AvgDialog_19076_Content_28 = {
    Text = "Lily prende esitante la mano di Nymphaea, rivolgendoti un ultimo sguardo prolungato prima di scomparire lungo il corridoio."
  },
  AvgDialog_19076_Content_29 = {
    Text = "Grazie a tutti per essere venuti. Permettetemi di presentarmi come si deve."
  },
  AvgDialog_19076_Content_3 = {
    Text = "La polvere turbina nell'aria, sollevata dall'apertura delle pesanti porte, riempiendo il corridoio di un odore acre e peculiare.\nNonostante fuori il giorno sia luminoso con la luce del sole sulla neve, il corridoio resta avvolto in un'oscurità opprimente."
  },
  AvgDialog_19076_Content_30 = {
    Text = [[
Sono <Blue:Francis Oswood>, la direttrice di questo ospedale.
Qui tutti mi chiamano Francis, e sei libera di fare lo stesso.]]
  },
  AvgDialog_19076_Content_31 = {
    Text = "A giudicare dal vostro abbigliamento, voi due siete studenti? E questa..."
  },
  AvgDialog_19076_Content_32 = {
    Text = "Esatto, siamo studenti del primo anno all'Università di Mythag.\nLotan... beh, considerala come la nostra professoressa di scorta."
  },
  AvgDialog_19076_Content_33 = {
    Text = "Capisco. Mi riporta alla mente vecchi ricordi. I miei giorni da studente sono ormai lontani, insieme alla concentrazione e alla convinzione che un tempo possedevo."
  },
  AvgDialog_19076_Content_34 = {
    Text = "I vostri occhi mi ricordano me stesso da giovane, però... oggi vi scorgo un tremolio di dubbio, a differenza di ieri notte."
  },
  AvgDialog_19076_Content_35 = {
    Text = "È successo qualcosa?\nO forse... hai aperto una scatola che doveva restare chiusa?"
  },
  AvgDialog_19076_Content_36 = {Text = "..."},
  AvgDialog_19076_Content_37 = {
    Text = "Non oserei paragonarmi a voi, Professor Oswood."
  },
  AvgDialog_19076_Content_38 = {
    Text = [[
Se fossi rimasta nel mondo accademico, avresti potuto rivoluzionare la medicina.
Ma ti sei ritirata, scomparendo dal mondo scientifico.]]
  },
  AvgDialog_19076_Content_39 = {
    Text = "Vecchie storie, non vale la pena soffermarcisi."
  },
  AvgDialog_19076_Content_4 = {
    Text = "Questo posto mi mette i brividi."
  },
  AvgDialog_19076_Content_40 = {
    Text = "Nient'affatto. Facevate parte della prima <Blue:Spedizione ai Campi di Ghiaccio di Elworth>."
  },
  AvgDialog_19076_Content_41 = {
    Text = "Non posso fare a meno di chiedermi come uno studioso del vostro calibro sia finito a lavorare in un posto come questo."
  },
  AvgDialog_19076_Content_42 = {
    Text = "Più che assunta, scelta. Ho scelto io questo sanatorio."
  },
  AvgDialog_19076_Content_43 = {
    Text = "Devi sapere che la spedizione è stata tutt'altro che un \"successo\".\nEro l'unica sopravvissuta. Tutti gli altri sono stati sepolti sotto la neve."
  },
  AvgDialog_19076_Content_44 = {
    Text = "Mi cambiò profondamente. Cominciai a chiedermi se, nella nostra caccia al \"progresso,\" non avessimo perduto qualcosa di ben più prezioso — e cosa significasse davvero quella perdita."
  },
  AvgDialog_19076_Content_45 = {
    Text = "Questo luogo è la tua risposta?"
  },
  AvgDialog_19076_Content_46 = {
    Text = "Un paio di visite al giorno, a chiacchierare con quelli etichettati come \"isterici,\" per poi ritirarmi nel mio studio a riflettere."
  },
  AvgDialog_19076_Content_47 = {
    Text = "Rispetto a rincorrere la prossima grande scoperta, preferisco questa vita più quieta."
  },
  AvgDialog_19076_Content_48 = {
    Text = "La tua compassione è fonte d'ispirazione."
  },
  AvgDialog_19076_Content_49 = {
    Text = "Parole gentili. Ma è solo impegno di facciata. Non cambia davvero le loro vite."
  },
  AvgDialog_19076_Content_5 = {Text = "..."},
  AvgDialog_19076_Content_50 = {
    Text = "Non sono d'accordo. Avete dato a questi pazienti stigmatizzati un focolare, un'occasione per riconquistare la normalità."
  },
  AvgDialog_19076_Content_51 = {
    Text = "Francis accenna un sorriso flebile e vago."
  },
  AvgDialog_19076_Content_52 = {Text = "Speriamo."},
  AvgDialog_19076_Content_53 = {
    Text = "Ma non siete venuti ad ascoltare le mie prediche. Venite, lasciate che vi mostri il sanatorio."
  },
  AvgDialog_19076_Content_6 = {
    Text = "Dai a Lily una carezza gentile, esortandola a guidare il gruppo in avanti."
  },
  AvgDialog_19076_Content_7 = {
    Text = "Il corridoio vuoto riecheggia del suono dei tuoi passi, ogni tonfo sordo riverbera con un peso inquietante."
  },
  AvgDialog_19076_Content_8 = {
    Text = "Questo posto puzza di disinfettante, come se ci fosse stato messo in salamoia. Non vi fa prudere il naso?"
  },
  AvgDialog_19076_Content_9 = {
    Text = "Come a voler infrangere il silenzio opprimente, Lotan batte deliberatamente gli stivali sul pavimento, creando un ritmico scalpiccio."
  },
  AvgDialog_19077_Content_1 = {
    Text = "Non vi capisco, voi. Basta trafiggere altre Pustole, giusto?"
  },
  AvgDialog_19077_Content_2 = {
    Text = "...Proteggere... la Madre..."
  },
  AvgDialog_19078_Content_1 = {
    Text = "Sesto Senso"
  },
  AvgDialog_19078_Content_10 = {Text = "......"},
  AvgDialog_19078_Content_11 = {
    Text = [[
Il rituale termina.
La donna a capo del gruppo scende dall'alto Altare, seguita da una processione di emissari in vesti nere, che si muovono come una colonia di formiche in migrazione.]]
  },
  AvgDialog_19078_Content_12 = {
    Text = "<Blue:Tu> lotti per alzarti, liberandoti degli abiti fradici, e trovi la veste cerimoniale menzionata da Murphy dietro un masso."
  },
  AvgDialog_19078_Content_13 = {
    Text = "Ti cambi in fretta, ignorando il freddo, e avanzi a tentoni verso il Passaggio settentrionale."
  },
  AvgDialog_19078_Content_14 = {Text = "..."},
  AvgDialog_19078_Content_15 = {Text = "..."},
  AvgDialog_19078_Content_16 = {
    Text = "Il passaggio è stretto, costringendoti a chinarti.\nNessuna luce penetra qui, solo oscurità assoluta."
  },
  AvgDialog_19078_Content_17 = {
    Text = "Posso davvero... fuggire da qui?"
  },
  AvgDialog_19078_Content_18 = {
    Text = "Cerchi l'orologio da tasca che ti dava forza, ma è scomparso."
  },
  AvgDialog_19078_Content_19 = {
    Text = "...Era il tuo ultimo legame con @1 in questo mondo."
  },
  AvgDialog_19078_Content_2 = {
    Text = "Forse l'Esaurimento ha avuto la meglio. Doll ti ha detto di fare una pausa, ma scivoli in un sonno confuso..."
  },
  AvgDialog_19078_Content_20 = {Text = "..."},
  AvgDialog_19078_Content_21 = {
    Text = "Per fortuna il Rito è terminato e la grotta è vuota."
  },
  AvgDialog_19078_Content_22 = {
    Text = "Frugi tra i tuoi vecchi vestiti senza trovare l'orologio, poi perlusti il bordo della pozza dove eri stato deposto."
  },
  AvgDialog_19078_Content_23 = {
    Text = "...Qualcosa non va."
  },
  AvgDialog_19078_Content_24 = {
    Text = "Il livello dell'acqua si è abbassato."
  },
  AvgDialog_19078_Content_25 = {
    Text = "I Sacrifici in stato comatoso nella pozza si sono raggomitolati inconsapevolmente, come Infanti nel grembo di una Madre."
  },
  AvgDialog_19078_Content_26 = {
    Text = "La tua mano sfiora il \"fango\" e trova l'orologio. Mentre ti volti per andartene, noti una figura accanto a te."
  },
  AvgDialog_19078_Content_27 = {Text = "..."},
  AvgDialog_19078_Content_28 = {
    Text = "Respira ancora... Esiti, poi provi a svegliarlo."
  },
  AvgDialog_19078_Content_29 = {
    Text = [[
Con Cecily scomparsa e nessun motivo per tornare,
pensi che salvarne una sia meglio di nessuna.]]
  },
  AvgDialog_19078_Content_3 = {
    Text = "E sprofondi ancora una volta in un angosciante <Yellow:Sogno>."
  },
  AvgDialog_19078_Content_30 = {
    Text = "<Small:...Colonnello Bertrand, Colonnello Bertrand.>"
  },
  AvgDialog_19078_Content_31 = {
    Text = "Chiami sommessamente. Lui si desta."
  },
  AvgDialog_19078_Content_32 = {
    Text = "Questo luogo..."
  },
  AvgDialog_19078_Content_33 = {
    Text = "Siamo stati usati come sacrifici per il culto. È una lunga storia—dobbiamo fuggire, adesso."
  },
  AvgDialog_19078_Content_34 = {
    Text = "Proprio in quel momento, la superficie della pozza nera si increspa di una luce inquietante."
  },
  AvgDialog_19078_Content_35 = {
    Text = "Lampeggia tre volte in pochi secondi, poi si spegne."
  },
  AvgDialog_19078_Content_36 = {
    Text = "Passi risuonano da ogni direzione."
  },
  AvgDialog_19078_Content_37 = {
    Text = "Sei circondato."
  },
  AvgDialog_19078_Content_38 = {
    Text = "Il cerchio si stringe, figure nere si chiudono come muri, soffocando chi è al loro interno."
  },
  AvgDialog_19078_Content_39 = {
    Text = "Sulla piattaforma in lontananza, Murphy è accanto alla donna a capo del gruppo,\ncon un'espressione mista di disgusto e rassegnazione."
  },
  AvgDialog_19078_Content_4 = {
    Text = "<Italic:Egli farà Ritorno... attraverso il perverso @2, Egli sorgerà da @4, Araldo dell'avvento di @3...>"
  },
  AvgDialog_19078_Content_40 = {
    Text = "...Posso ancora fuggire?"
  },
  AvgDialog_19078_Content_41 = {
    Text = "...Posso vedere @1 un'ultima volta?"
  },
  AvgDialog_19078_Content_42 = {
    Text = "...O è questo il modo per ricongiungerci?"
  },
  AvgDialog_19078_Content_43 = {
    Text = "...Se solo... potessi vedere..."
  },
  AvgDialog_19078_Content_44 = {Text = "..."},
  AvgDialog_19078_Content_45 = {
    Text = "Bolle gorgogliano nella pozza nera."
  },
  AvgDialog_19078_Content_46 = {
    Text = "Dal loro centro emerge una fanciulla pallida."
  },
  AvgDialog_19078_Content_47 = {
    Text = "Nella sua mano, un viscoso globo nero, una massa simile a un occhio con denti da squalo, si protende in avanti insieme a lei."
  },
  AvgDialog_19078_Content_48 = {
    Text = "<Yellow:Ordini. Vi prego, datemi ordini, Padrone>."
  },
  AvgDialog_19078_Content_5 = {
    Text = [[
La donna sull'Altare intona un canto.
I tuoi nervi si tendono mentre una melma nera ricopre il tuo corpo, sigillandoti bocca e naso.]]
  },
  AvgDialog_19078_Content_6 = {
    Text = "Il tuo viso è sommerso, eppure respirare è facile.\nLa pozza nera sembra il liquido amniotico di una madre, cullandoti nel sonno."
  },
  AvgDialog_19078_Content_7 = {
    Text = "Non riesco a dormire... non devo dormire..."
  },
  AvgDialog_19078_Content_8 = {Text = "..."},
  AvgDialog_19078_Content_9 = {Text = "..."},
  AvgDialog_19079_Content_1 = {Text = "21 Grammi"},
  AvgDialog_19079_Content_10 = {
    Text = "Non dire così. Tra i \"diplomati\" di Mythag, non conto forse come un successo?\nNon sono in molti a uscire vivi da quel posto."
  },
  AvgDialog_19079_Content_11 = {
    Text = "A volte prego persino per lui, sperando che possa tornare a reggersi in piedi come un uomo normale."
  },
  AvgDialog_19079_Content_12 = {
    Text = "Grazie per il pensiero, ma Alistair sta sopravvivendo al tuo altro mentore, quantomeno."
  },
  AvgDialog_19079_Content_13 = {
    Text = "Alistair è baciato dalla fortuna—probabilmente assisterà alla fine del mondo.\nPeccato che tu non vedrai quel giorno."
  },
  AvgDialog_19079_Content_14 = {
    Text = "Quanto potrai resistere, circondato da queste creature?"
  },
  AvgDialog_19079_Content_15 = {
    Text = "Non lo saprò finché non ci provo."
  },
  AvgDialog_19079_Content_16 = {
    Text = "Pensi davvero di poter affrontare da solo tutti questi soggetti sperimentali?"
  },
  AvgDialog_19079_Content_17 = {
    Text = "Non dare per scontato che io sia Oscuro quanto te, Herbert."
  },
  AvgDialog_19079_Content_18 = {
    Text = "La tua Voce è irritante come sempre, Doll."
  },
  AvgDialog_19079_Content_19 = {
    Text = "Vale più di quel cervello da cavernicolo che ti ritrovi."
  },
  AvgDialog_19079_Content_2 = {
    Text = "Ora siamo solo io e te."
  },
  AvgDialog_19079_Content_20 = {
    Text = [[
I tuoi colleghi potrebbero non essere d'accordo.
Se ci fosse un pulsante per farti tacere, lo premerebbero senza pensarci due volte.]]
  },
  AvgDialog_19079_Content_21 = {
    Text = "Sottovaluti la tolleranza di Mythag... e il mio valore."
  },
  AvgDialog_19079_Content_22 = {
    Text = "Errore mio. Ma anche la mente più brillante è impotente quando i mostri la circondano, no?"
  },
  AvgDialog_19079_Content_23 = {
    Text = [[
Impotente?
Guarda bene, e vedrai cosa ho al posto delle mani umane.]]
  },
  AvgDialog_19079_Content_24 = {
    Text = "Che la Chiave d'Argento Illumini il Cammino."
  },
  AvgDialog_19079_Content_25 = {
    Text = "Le Pupille di Doll iniziano a distorcersi."
  },
  AvgDialog_19079_Content_26 = {
    Text = "Pronti, amebe?"
  },
  AvgDialog_19079_Content_27 = {
    Text = "Aspetta! Sei fuori di testa?!"
  },
  AvgDialog_19079_Content_28 = {
    Text = "Un'esplosione ruggisce come un tuono, scuotendo il corridoio angusto."
  },
  AvgDialog_19079_Content_29 = {
    Text = "Corpi metallici si frantumano, i frammenti si conficcano nelle pareti in penombra."
  },
  AvgDialog_19079_Content_3 = {
    Text = "Herbert, stai ancora inseguendo quell'assurdo sogno?"
  },
  AvgDialog_19079_Content_30 = {
    Text = "Strida agonizzanti erompono e si spezzano di colpo."
  },
  AvgDialog_19079_Content_31 = {
    Text = "...Un silenzio di morte segue, lungo decine di secondi, con solo un fumo denso che si avvolge attraverso il sanatorio."
  },
  AvgDialog_19079_Content_32 = {
    Text = [[
Coff, coff... Maledizione, Doll...
Meno male che sono venuto preparato...]]
  },
  AvgDialog_19079_Content_33 = {
    Text = "Davanti a Herbert, uno scudo di soggetti sperimentali senza vita ammassati, parti metalliche conficcate nella pelle e nelle ossa, del tutto privi di vita."
  },
  AvgDialog_19079_Content_34 = {
    Text = "Con il corpo ridotto in pezzi a quel modo, mi chiedo quanto di ciò che resta sia ancora utilizzabile..."
  },
  AvgDialog_19079_Content_4 = {
    Text = "Se sapessi distinguere l'assurdità dalla grandezza, forse sceglieresti meglio le parole."
  },
  AvgDialog_19079_Content_5 = {
    Text = "Nessuna forma di vita sfugge alla Dissoluzione. La tua ossessione lascia solo una scia di macerie."
  },
  AvgDialog_19079_Content_6 = {
    Text = "Doll rivolge uno sguardo sprezzante alle creature deformi definite \"macerie.\""
  },
  AvgDialog_19079_Content_7 = {
    Text = "Il tuo gusto è macabro come sempre. Non ricordo che Mythag ti abbia insegnato questo."
  },
  AvgDialog_19079_Content_8 = {
    Text = "A quanto pare Alistair ha preso in mano la situazione e ha cancellato la mia grande opera dopo la mia partenza. A proposito—come sta?"
  },
  AvgDialog_19079_Content_9 = {
    Text = "Ti importa ancora di lui? Si vergognerebbe a sentirlo."
  },
  AvgDialog_19080_Content_1 = {
    Text = [[
Mi risparmi la vita?
Se questo posto cade, persone come noi saranno di nuovo senza un tetto.]]
  },
  AvgDialog_19080_Content_2 = {
    Text = "Non siamo qui per distruggere."
  },
  AvgDialog_19080_Content_3 = {
    Text = "Ho appena contattato Lord Dexter. È lieto di fare un po' di beneficenza e assumere la gestione delle operazioni."
  },
  AvgDialog_19080_Content_4 = {
    Text = "L'Innocente può restare, e lui garantirà i rifornimenti."
  },
  AvgDialog_19080_Content_5 = {
    Text = "...Parla in grande, ma le sue promesse sono solide."
  },
  AvgDialog_19080_Content_6 = {
    Text = "Dopo che ce ne saremo andati, questo sanatorio tornerà a funzionare senza intoppi. Sarà ancora il tuo focolare."
  },
  AvgDialog_19080_Content_7 = {
    Text = "Ma... la signora Oswood...\nLa prego, non le faccia del male. Tutto ciò che ha fatto era per una causa superiore..."
  },
  AvgDialog_19081_Content_1 = {
    Text = "Determinazione"
  },
  AvgDialog_19081_Content_10 = {
    Text = "Chi va là—<BigShake:Capitano!!>"
  },
  AvgDialog_19081_Content_11 = {
    Text = "L'uomo alto non riuscì a rispondere subito alla ragazza. Senza fiato, dovette appoggiarsi alla parete della cabina per restare in piedi."
  },
  AvgDialog_19081_Content_12 = {
    Text = "Elton fece diversi respiri profondi e riuscì a stabilizzarsi con l'aiuto di Celeste."
  },
  AvgDialog_19081_Content_13 = {
    Text = "E Celeste..."
  },
  AvgDialog_19081_Content_14 = {Text = "Tu..."},
  AvgDialog_19081_Content_15 = {
    Text = "Si erano indeboliti ancora di più."
  },
  AvgDialog_19081_Content_16 = {
    Text = "La forza vitale del capitano che le aveva donato un barlume di speranza e del Risvegliatore che aveva impedito all'<Red:aberrazione> dentro di lei di crescere si sta gradualmente dissipando."
  },
  AvgDialog_19081_Content_17 = {
    Text = "Paura... La paura della morte, la paura della perdita sopraffà la mente, lasciandola vuota."
  },
  AvgDialog_19081_Content_18 = {
    Text = "...Io...voi tutti..."
  },
  AvgDialog_19081_Content_19 = {
    Text = "Va tutto bene, Murphy. Non c'è bisogno di avere paura."
  },
  AvgDialog_19081_Content_2 = {
    Text = [[
22:45  
Sonanil  
Stiva 3]]
  },
  AvgDialog_19081_Content_20 = {
    Text = "C'è sempre una soluzione. Andrà tutto bene. Non preoccuparti per noi."
  },
  AvgDialog_19081_Content_21 = {
    Text = "Lasciando il supporto di Celeste, il capitano barcollò ma stabilizzò il corpo, poi allungò la mano—scompigliandole i capelli con forza."
  },
  AvgDialog_19081_Content_22 = {
    Text = "Non toccare così forte! Mi hai spettinato tutti i capelli!"
  },
  AvgDialog_19081_Content_23 = {
    Text = "Lo dici sempre! Guardati, riesci a malapena a stare in piedi!"
  },
  AvgDialog_19081_Content_24 = {
    Text = "Ora sto bene, vedi? Mi sono già ripreso."
  },
  AvgDialog_19081_Content_25 = {
    Text = "E loro? I due studenti che sono saliti sulla nave per sbaglio?"
  },
  AvgDialog_19081_Content_26 = {
    Text = "Ci hanno fatto guadagnare tempo; ora l'attenzione di tutti è sulla sala motori."
  },
  AvgDialog_19081_Content_27 = {
    Text = "Sala motori... Miryam è nella sala motori!"
  },
  AvgDialog_19081_Content_28 = {
    Text = "Hanno la mente lucida, sanno cosa possono e devono fare.\nQuell'università... ha addestrato bene quei ragazzi."
  },
  AvgDialog_19081_Content_29 = {
    Text = "Ma non siamo impotenti. Finché saremo abbastanza vicini alla terraferma, Celeste potrà trasferirli a riva."
  },
  AvgDialog_19081_Content_3 = {
    Text = "Stivali dalla suola dura battevano ritmicamente sul ponte, ogni passo pesante e sordo."
  },
  AvgDialog_19081_Content_30 = {
    Text = "Ma il tuo corpo..."
  },
  AvgDialog_19081_Content_31 = {
    Text = "Non preoccuparti, posso permettermi questo po' di Vita."
  },
  AvgDialog_19081_Content_32 = {
    Text = "Colludere con il culto e chiudere un occhio sulle tue <Blue:sofferenze>... I miei peccati sono già abbastanza pesanti. Non voglio portare sulle spalle le vite di altri due innocenti."
  },
  AvgDialog_19081_Content_33 = {
    Text = "La mia... sofferenza?"
  },
  AvgDialog_19081_Content_34 = {Text = "..."},
  AvgDialog_19081_Content_35 = {
    Text = "Sono io che ti ho consegnata a Miryam."
  },
  AvgDialog_19081_Content_36 = {Text = "..."},
  AvgDialog_19081_Content_37 = {
    Text = "Sei stato il \"carico\" più prezioso che ho trasportato dopo essermi unito al culto.\nQuel viaggio perfetto mi ha fatto guadagnare il favore di Miryam."
  },
  AvgDialog_19081_Content_38 = {
    Text = "Quindi quando ti ho chiesto aiuto, hai accettato senza esitazione..."
  },
  AvgDialog_19081_Content_39 = {
    Text = "Una volta abbastanza vicini alla costa, farò portare te fuori dalla nave da Celeste. Stai il più lontano possibile dal mare."
  },
  AvgDialog_19081_Content_4 = {
    Text = "Capitano... Celeste..."
  },
  AvgDialog_19081_Content_40 = {
    Text = "Come in risposta, Celeste fece ruotare la sua bussola."
  },
  AvgDialog_19081_Content_41 = {
    Text = "Vuoi che Celeste venga con me?"
  },
  AvgDialog_19081_Content_42 = {
    Text = "Quei due studenti hanno un mezzo di trasporto; basta trasformare la loro auto in un <Yellow:Dominio>..."
  },
  AvgDialog_19081_Content_43 = {
    Text = [[
Non scherzare! Pensi davvero di poter tenere a bada quei due mostri?
Non sei nemmeno un Navigatore, sei solo un semplice umano!]]
  },
  AvgDialog_19081_Content_44 = {
    Text = "Voglio che tu ti liberi da tutto questo. Che sia il mio ultimo desiderio."
  },
  AvgDialog_19081_Content_45 = {
    Text = "Al peggio affondo insieme alla Sona-Nyl. Avrei dovuto colare a picco con lei molto tempo fa."
  },
  AvgDialog_19081_Content_46 = {
    Text = "Murphy si aggrappò al cappotto del Capitano, rifiutando ostinatamente di lasciarlo andare."
  },
  AvgDialog_19081_Content_47 = {
    Text = "Il Risvegliatore non aveva intenzione di partecipare a questa disputa. Percependo lo stato del Custode dall'altro lato del legame oltre la porta, si preparò a dirigersi verso la sala motori."
  },
  AvgDialog_19081_Content_48 = {
    Text = "—Aspetta! Dove stai andando!"
  },
  AvgDialog_19081_Content_49 = {
    Text = "La ragazza spalancò la porta, afferrando un Tentacolo."
  },
  AvgDialog_19081_Content_5 = {
    Text = "Ramona, e %player%... perché non sono ancora tornati?"
  },
  AvgDialog_19081_Content_50 = {
    Text = "Come facevi a sapere che io..."
  },
  AvgDialog_19081_Content_51 = {
    Text = "Quindi, sei il \"Tulu\" di cui parlava Ramona? Hai intenzione di aiutarli?"
  },
  AvgDialog_19081_Content_52 = {
    Text = "Le mie azioni non spettano agli estranei metterle in discussione."
  },
  AvgDialog_19081_Content_53 = {
    Text = "Vengo anch'io."
  },
  AvgDialog_19081_Content_54 = {
    Text = "Murphy! Se cadi nelle mani di Miryam, tutti i nostri sforzi saranno stati vani."
  },
  AvgDialog_19081_Content_55 = {Text = "Lo so."},
  AvgDialog_19081_Content_56 = {
    Text = [[
Ma... non ce la faccio...
Non voglio morire, ma... e se si sacrificassero prima di raggiungere la riva...]]
  },
  AvgDialog_19081_Content_57 = {
    Text = "<SmallShake:Io... non voglio... che succeda...>"
  },
  AvgDialog_19081_Content_58 = {
    Text = "*Tosse*, *tosse tosse*!"
  },
  AvgDialog_19081_Content_59 = {
    Text = "Voglio dire... non posso restare nel Dominio per sempre. Per fuggire davvero, ho bisogno dell'aiuto di quei due studenti."
  },
  AvgDialog_19081_Content_6 = {
    Text = "Murphy camminava avanti e indietro con ansia, incapace di stare ferma. Prese a calci una cassa, poi tirò le funi che la assicuravano."
  },
  AvgDialog_19081_Content_60 = {
    Text = "Non posso semplicemente andare alla scuola e dire al preside che i loro studenti si sono sacrificati per aiutarmi.\nHo bisogno che siano vivi. Voglio diventare loro ospite con dignità."
  },
  AvgDialog_19081_Content_61 = {
    Text = "Non sprecherò energie a proteggerti."
  },
  AvgDialog_19081_Content_62 = {
    Text = "Non ho bisogno della vostra protezione. Conosco a memoria le Debolezze dei Navigatori. So cavarmela da sola."
  },
  AvgDialog_19081_Content_63 = {
    Text = "D'accordo, se sei così determinato."
  },
  AvgDialog_19081_Content_64 = {
    Text = "Che sguardo è quello?"
  },
  AvgDialog_19081_Content_65 = {
    Text = [[
Pensavo che non fossi degno del loro sacrificio.
A quanto pare, mi sbagliavo sul tuo conto.]]
  },
  AvgDialog_19081_Content_66 = {
    Text = "Che sono questi enigmi? Muoversi, muoversi!"
  },
  AvgDialog_19081_Content_67 = {
    Text = "Lei... va bene, se è la sua scelta."
  },
  AvgDialog_19081_Content_68 = {
    Text = "Celeste, mantienici a tutta velocità."
  },
  AvgDialog_19081_Content_7 = {
    Text = "Spero che non siano nei guai..."
  },
  AvgDialog_19081_Content_8 = {
    Text = "Non riusciva a trovare pace, né per pregare né per riposare."
  },
  AvgDialog_19081_Content_9 = {Text = "Bang—!"},
  AvgDialog_19082_Content_1 = {
    Text = "Cosa stai aspettando? Devo invitarti formalmente?"
  },
  AvgDialog_19082_Content_10 = {
    Text = "Presto! Prima tu!"
  },
  AvgDialog_19082_Content_11 = {
    Text = "Neanche per sogno! Tu sei una persona comune. Ho il dovere di proteggerti—<BigShake:Ah!>"
  },
  AvgDialog_19082_Content_12 = {
    Text = "Ignorando le tue proteste, la bambina—esile e agile—scivola alle tue spalle."
  },
  AvgDialog_19082_Content_13 = {
    Text = "—E con un calcio deciso, ti spedisce a ruzzolare nel vuoto nero."
  },
  AvgDialog_19082_Content_14 = {
    Text = "<SmallShake:Ahi, ahi...>"
  },
  AvgDialog_19082_Content_15 = {
    Text = "La ragazza seguì da vicino e saltò dentro. Chiuse con forza la porta di ferro, girò abilmente l'argano e la bloccò."
  },
  AvgDialog_19082_Content_16 = {
    Text = "Uff—per ora dovremmo essere al sicuro."
  },
  AvgDialog_19082_Content_17 = {
    Text = "La ragazza premette l'interruttore e, dopo qualche sfarfallio, la vecchia lampadina diffuse la sua luce nella stanza, dissipando l'oscurità."
  },
  AvgDialog_19082_Content_18 = {
    Text = "La stiva è spaziosa e vuota, con merci sparse fissate negli angoli. La polvere danza nella luce fioca, creando un'atmosfera di abbandono e decadenza."
  },
  AvgDialog_19082_Content_19 = {
    Text = "Un rumore sordo e continuo di colpi risuona sopra la tua testa, ogni tonfo che rimbomba nel tuo cranio."
  },
  AvgDialog_19082_Content_2 = {
    Text = "Una Porta nascosta?!"
  },
  AvgDialog_19082_Content_20 = {
    Text = "La mia testa..."
  },
  AvgDialog_19082_Content_21 = {
    Text = "Le tempie pulsano a ogni colpo, un dolore intenso che lacera il cervello sinistro e destro, l'acido gastrico che risale di nuovo in gola."
  },
  AvgDialog_19082_Content_22 = {
    Text = "Non dovrebbero riuscire a entrare per un po'... Eh?! Che ti succede?!"
  },
  AvgDialog_19082_Content_23 = {
    Text = "Non... non spaventarmi! Non morire!"
  },
  AvgDialog_19082_Content_24 = {
    Text = "Uff, finalmente li abbiamo seminati."
  },
  AvgDialog_19082_Content_25 = {
    Text = "Questa porta è robusta. Dovremmo essere al sicuro qui per ora... <BigShake:Dannazione!>"
  },
  AvgDialog_19082_Content_26 = {
    Text = "Dannazione, dannazione, dannazione! Avete rovinato tutto! Il mio intero piano è in frantumi! Devo inventarmi qualcosa..."
  },
  AvgDialog_19082_Content_27 = {
    Text = "A proposito, faresti bene a ricordarti il mio nome—"
  },
  AvgDialog_19082_Content_28 = {
    Text = "Il suo volto ansioso si fonde con memorie frammentate, mescolando due scene simili eppure distinte in una sola."
  },
  AvgDialog_19082_Content_29 = {Text = "Murphy...?"},
  AvgDialog_19082_Content_3 = {
    Text = "Che porta segreta? Come puoi scherzare con me in un momento simile?! Sei impazzito?!"
  },
  AvgDialog_19082_Content_30 = {
    Text = "Stai... stai bene?"
  },
  AvgDialog_19082_Content_31 = {
    Text = "Mi ha fatto un po' male."
  },
  AvgDialog_19082_Content_32 = {
    Text = "Non ci credo, ti sei fatto male cadendo?"
  },
  AvgDialog_19082_Content_33 = {
    Text = "Nella luce fioca, si avvicinò in punta di piedi per controllare le tue condizioni."
  },
  AvgDialog_19082_Content_34 = {Text = "—!"},
  AvgDialog_19082_Content_35 = {
    Text = "Che succede?"
  },
  AvgDialog_19082_Content_36 = {
    Text = "<SmallShake:N-Niente...>"
  },
  AvgDialog_19082_Content_37 = {
    Text = "<Small:Sembra che ci sia qualcosa di utile in questo carico...>"
  },
  AvgDialog_19082_Content_38 = {
    Text = "Murphy borbotta parole indistinte, frugando rigidamente tra le casse impilate."
  },
  AvgDialog_19082_Content_39 = {
    Text = "(Avvicinati a lei)"
  },
  AvgDialog_19082_Content_4 = {
    Text = "Non è che tu non sia mai stato sottocoperta—smettila di tergiversare, preparati!"
  },
  AvgDialog_19082_Content_40 = {
    Text = "Lo spacchettamento violento di Murphy sparse la carta da imballaggio e la paglia su tutto il pavimento, trasformando rapidamente questo angolo in un disastro."
  },
  AvgDialog_19082_Content_41 = {
    Text = "No... questi sono gioielli rotti."
  },
  AvgDialog_19082_Content_42 = {
    Text = "Dai un'occhiata dentro la cassa e vedi un set di gioielli in platino in stile regale, adornati con perle e diamanti che sembrano inestimabili."
  },
  AvgDialog_19082_Content_43 = {
    Text = "...Ma che diavolo, sono tutti oggetti rituali."
  },
  AvgDialog_19082_Content_44 = {
    Text = "La seconda cassa è piena di vari oggetti ed erbe: una ciotola di pietra, salvia, mirra... Senza conoscenze di alchimia, si potrebbe scambiare per la merce di un commerciante."
  },
  AvgDialog_19082_Content_45 = {
    Text = "Trovato! Tieni—accovacciati."
  },
  AvgDialog_19082_Content_46 = {
    Text = "Una pasta appiccicosa viene spalmata sulla parte posteriore della tua testa. La sua freschezza, con un tocco di piccantezza, allevia il dolore in una certa misura."
  },
  AvgDialog_19082_Content_47 = {
    Text = "Quello è..."
  },
  AvgDialog_19082_Content_48 = {
    Text = "Ehi! Non toccare quello."
  },
  AvgDialog_19082_Content_49 = {
    Text = "Murphy ti porge un barattolo di unguento."
  },
  AvgDialog_19082_Content_5 = {
    Text = "È sicuro là sotto?"
  },
  AvgDialog_19082_Content_50 = {
    Text = "L'etichetta non riporta né ricetta né nome del farmaco, solo uno strano simbolo—è chiaramente una pozione fatta in casa."
  },
  AvgDialog_19082_Content_51 = {
    Text = "...È un déjà vu? Il disegno sull'etichetta dell'unguento sembra familiare."
  },
  AvgDialog_19082_Content_52 = {
    Text = "Eccolo. Non preoccuparti, non ti ucciderà."
  },
  AvgDialog_19082_Content_53 = {
    Text = "Fin da quando ero piccola, ho sempre usato questo unguento per qualsiasi ferita esterna.\nCom'è? Il dolore non scompare appena lo applichi?"
  },
  AvgDialog_19082_Content_54 = {
    Text = "Ti osserva nervosamente, il senso di colpa evidente per la caduta dalle scale."
  },
  AvgDialog_19082_Content_55 = {
    Text = "Il dolore è sparito."
  },
  AvgDialog_19082_Content_56 = {
    Text = "Visto? Te l'avevo detto che funziona—"
  },
  AvgDialog_19082_Content_57 = {
    Text = "Ricevendo una risposta affermativa, Murphy finalmente si rilassò e accennò un sorriso."
  },
  AvgDialog_19082_Content_58 = {
    Text = "La parte posteriore della testa sta un po' meglio, ma le tempie dolgono ancora debolmente.\nVedendo il suo atteggiamento rilassato, una voce dentro di te sussurra—"
  },
  AvgDialog_19082_Content_59 = {
    Text = "Alcune cose possono essere approfondite dopo essersi riuniti con <Blue:il tuo partner>."
  },
  AvgDialog_19082_Content_6 = {
    Text = "E io che ne so?"
  },
  AvgDialog_19082_Content_7 = {
    Text = "Meglio che farsi prendere da questi pazzi e finire in pasto ai pesci! Smettila di perdere tempo e preparati."
  },
  AvgDialog_19082_Content_8 = {
    Text = "Il nemico è veloce. Fai fatica a ritardare il loro attacco mentre la ragazza solleva la grata di ferro."
  },
  AvgDialog_19082_Content_9 = {
    Text = "Sotto l'apertura, una scala di ferro si estende nell'oscurità insondabilmente profonda."
  },
  AvgDialog_19083_Content_1 = {
    Text = "Realtà Distorta"
  },
  AvgDialog_19083_Content_10 = {
    Text = "A quella luce, vide innumerevoli Ferite nere, grandi e piccole, che sfregiavano la pelle liscia della \"Madre\"."
  },
  AvgDialog_19083_Content_11 = {
    Text = "\"Mi dispiace...\""
  },
  AvgDialog_19083_Content_12 = {
    Text = "Una melma nera ribollì, frantumando la quiete della vasca."
  },
  AvgDialog_19083_Content_13 = {
    Text = "La \"Madre\" emise un grido acuto e stridulo, i Tentacoli si contorcevano mentre depositavano qualcosa nel petto dell'implume."
  },
  AvgDialog_19083_Content_14 = {
    Text = "Tentacoli viscidi, gelidi e morbidi la avvolsero. La Pozza nera non le ostruiva più bocca e naso — al contrario, come liquido amniotico, sosteneva la sua vita."
  },
  AvgDialog_19083_Content_15 = {
    Text = [[
<Change>"Mi dispiace..."
"Io ancora... non voglio morire..."]]
  },
  AvgDialog_19083_Content_16 = {
    Text = "La superficie mantenne una calma prolungata. Neppure i venti polari ululanti riuscivano a increspare la pozza viscosa."
  },
  AvgDialog_19083_Content_17 = {
    Text = "Lady Miryam, la Fanciulla Divina potrebbe già aver..."
  },
  AvgDialog_19083_Content_18 = {
    Text = "Era nata durante l'ultimo Allineamento Stellare, una bambina capace di \"vedere\"."
  },
  AvgDialog_19083_Content_19 = {
    Text = "Nessuno al mondo è più degno del riconoscimento della stirpe divina."
  },
  AvgDialog_19083_Content_2 = {
    Text = "Un uccello implume dalle ali spezzate precipitò in una Pozza nera."
  },
  AvgDialog_19083_Content_20 = {
    Text = "Con quel mormorio, come se un'energia geotermica fosse eruttata, la superficie prese a ribollire d'improvviso."
  },
  AvgDialog_19083_Content_21 = {
    Text = "L'acqua nera densa e viscosa traboccò dagli argini, lambendo i piedi, fluendo fino alle piante nude della Donna."
  },
  AvgDialog_19083_Content_22 = {
    Text = "Facendosi largo tra i sussulti sommessi dei giovani cultisti, percorse in silenzio il sentiero di liquido nero, immergendo le mani nel profondo della pozza—"
  },
  AvgDialog_19083_Content_23 = {Text = "—Splash"},
  AvgDialog_19083_Content_24 = {
    Text = "La ragazza si aggrappò alle sue mani, balzando fuori dalla vasca.\nIl liquido nero ne seguiva i contorni del volto, come due raccapriccianti scie di lacrime."
  },
  AvgDialog_19083_Content_25 = {
    Text = "Oh, niente male. Sembra che il <Blue:Feto Divino> abbia riconosciuto la nuova <Blue:Madre>."
  },
  AvgDialog_19083_Content_26 = {
    Text = "L'osservazione brusca di Golia grondava scherno, eppure nessuno badava più al suo sarcasmo."
  },
  AvgDialog_19083_Content_27 = {
    Text = "La Fanciulla Divina... ci è riuscita? Ce l'abbiamo fatta!"
  },
  AvgDialog_19083_Content_28 = {
    Text = "Miryam chiuse dolcemente gli occhi, lasciò le mani strette a quelle della ragazza e si voltò verso i seguaci fanatici."
  },
  AvgDialog_19083_Content_29 = {
    Text = "Alzò le braccia in alto, un liquido nero che scorreva lungo la texture della sua pelle, tingendo istantaneamente il suo velo di un nero profondo."
  },
  AvgDialog_19083_Content_3 = {
    Text = "Le Preghiere mormorate dalla somma sacerdotessa si diffondevano ferme e sfuggenti. Parole fanatiche trafissero la melma nera, tramutandosi in Lame che squarciarono il petto dell'implume."
  },
  AvgDialog_19083_Content_30 = {
    Text = "Le Preghiere si levavano a ondate, armonizzandosi nella caverna gelida — fanatiche, contorte, assordanti."
  },
  AvgDialog_19083_Content_31 = {
    Text = "La Madre Divina è giunta!"
  },
  AvgDialog_19083_Content_32 = {
    Text = "Egli si risveglierà da @1, inaugurando @2!"
  },
  AvgDialog_19083_Content_33 = {
    Text = "Egli si risveglierà da @1, inaugurando @2!"
  },
  AvgDialog_19083_Content_34 = {
    Text = "Tre mesi dopo"
  },
  AvgDialog_19083_Content_35 = {
    Text = "Stai dando a quella donna sempre più grattacapi. Non eri ben educata qualche mese fa? Che c'è, non vuoi più ascoltare la mamma?"
  },
  AvgDialog_19083_Content_36 = {
    Text = "La ragazza lanciò un'occhiata a Golia, conficcando il coltello con ferocia nel legno, gettando via attrezzo e materiale."
  },
  AvgDialog_19083_Content_37 = {
    Text = "Ma... mamma?"
  },
  AvgDialog_19083_Content_38 = {
    Text = "Tu... dove hai imparato quel termine?"
  },
  AvgDialog_19083_Content_39 = {
    Text = "Dizionario! Guarda: \"Donna adulta che si prende cura di un bambino, con legame affettivo.\""
  },
  AvgDialog_19083_Content_4 = {
    Text = "Un liquido Cremisi sgorgò dalla Ferita, sbocciando sinistro sulla superficie nera ormai immobile—"
  },
  AvgDialog_19083_Content_40 = {
    Text = "No, non sarò la tua mamma."
  },
  AvgDialog_19083_Content_41 = {
    Text = "Sei la Fanciulla Divina del culto, una predestinata alla gloria... Se lo desideri, chiamami per nome."
  },
  AvgDialog_19083_Content_42 = {
    Text = "Ehm... Miry... am?"
  },
  AvgDialog_19083_Content_43 = {
    Text = "Sì, Fanciulla Divina."
  },
  AvgDialog_19083_Content_44 = {
    Text = "Sono la tua fedele servitrice."
  },
  AvgDialog_19083_Content_45 = {
    Text = "...Non è mia madre, non lo è mai stata."
  },
  AvgDialog_19083_Content_46 = {
    Text = "Solo i vertici della Chiesa dei Portatori di Luce sanno da dove vengo. Non ho una mamma — sono solo il loro dono a Miryam."
  },
  AvgDialog_19083_Content_47 = {
    Text = "Eh? Ti ha raccontato anche quello?"
  },
  AvgDialog_19083_Content_48 = {
    Text = "Per un Prigioniero con una condanna a morte, i segreti non contano — finiranno tutti nella tomba con me."
  },
  AvgDialog_19083_Content_49 = {
    Text = "Anche questo è il risarcimento di quella donna verso di te. Sai, il giorno in cui l'embrione divino è stato trapiantato nel tuo corpo, la nostra Somma Sacerdotessa non ha dormito tutta la notte."
  },
  AvgDialog_19083_Content_5 = {
    Text = "Eppure continuava a sprofondare, radici intrise di Sangue che si addentravano negli abissi, in un Abbraccio soffice e gelido."
  },
  AvgDialog_19083_Content_50 = {
    Text = "Il senso di colpa può tormentarla terribilmente."
  },
  AvgDialog_19083_Content_51 = {
    Text = "Senso di colpa? Stai scherzando? Lei non ha quell'emozione."
  },
  AvgDialog_19083_Content_52 = {
    Text = "Così fredda, piccola Principessa.\nLe bambine troppo glaciali fanno rattristare la mamma, lo sai."
  },
  AvgDialog_19083_Content_53 = {
    Text = "Stai zitto! Ho detto che non è mia madre!"
  },
  AvgDialog_19083_Content_54 = {
    Text = "Non esserne così sicuro. Vuoi sentire una storia?"
  },
  AvgDialog_19083_Content_55 = {
    Text = [[
<BigShake:No, e non voglio vederti!>
Se sei qui solo per deridermi, vattene!]]
  },
  AvgDialog_19083_Content_56 = {
    Text = "No, invece sì."
  },
  AvgDialog_19083_Content_57 = {
    Text = "Il tono di Golia si fece grave, venato di un'Autorità da campo di Battaglia. I due cuori di Murphy quasi si fermarono per lo spavento."
  },
  AvgDialog_19083_Content_58 = {
    Text = [[
Si rese conto all'improvviso: il gigante non era mai stato un giocattolo con cui trastullarsi.
Aveva tirato troppo la corda con il suo status, e lui si era semplicemente goduto lo spettacolo.]]
  },
  AvgDialog_19083_Content_59 = {
    Text = "S-Sì, prego, continua pure."
  },
  AvgDialog_19083_Content_6 = {Text = "..."},
  AvgDialog_19083_Content_60 = {
    Text = "Un culto misterioso garantisce la purezza assoluta delle linee di sangue; tutti i matrimoni sono organizzati dal leader del culto.\nChi sposa estranei e ha figli finirà per affrontarne le conseguenze."
  },
  AvgDialog_19083_Content_61 = {
    Text = "Durante l'ultima resa dei conti, l'Esecutore riportò una bambina — una che può vedere le <Yellow:entità spirituali>."
  },
  AvgDialog_19083_Content_62 = {
    Text = "Una bambina..."
  },
  AvgDialog_19083_Content_63 = {
    Text = "Era rimasta troppo a lungo nel compartimento nascosto sotto il corpo di sua madre. Quando i cultisti la trovarono, stava quasi soffocando nel <Red:sangue della sua madre biologica>."
  },
  AvgDialog_19083_Content_64 = {
    Text = "La più grande impresa di quella donna mediocre e insignificante? Mettere al mondo una figlia eccezionale e cercare di impedire alla setta di portarla via."
  },
  AvgDialog_19083_Content_65 = {
    Text = "—Che commovente amore tra madre e figlia. Mi viene da piangere."
  },
  AvgDialog_19083_Content_66 = {
    Text = "Golia... tu..."
  },
  AvgDialog_19083_Content_67 = {
    Text = "Perché... perché mi racconti questo?"
  },
  AvgDialog_19083_Content_68 = {
    Text = "La malinconia non è mai una buona cosa. Ricorda, lo sviluppo di <Blue:Dio> dipende dallo stato dell'ospite."
  },
  AvgDialog_19083_Content_69 = {
    Text = "Fai qualcosa di divertente — distruggi roba, frusta i Navigatori, tormenta le tue ancelle... qualsiasi cosa."
  },
  AvgDialog_19083_Content_7 = {Text = "..."},
  AvgDialog_19083_Content_70 = {
    Text = "Golia troncò la conversazione unilateralmente, dandole una ruvida pacca sulla testa, priva di qualsiasi calore."
  },
  AvgDialog_19083_Content_71 = {
    Text = "Uscendo, lanciò un'occhiata all'intaglio di legno che Murphy aveva gettato in un angolo. La sua abilità era pessima — la forma tozza e grottesca in cima alla base di legno risultava repellente al primo sguardo."
  },
  AvgDialog_19083_Content_72 = {Text = "Heh."},
  AvgDialog_19083_Content_73 = {
    Text = "Dopo che Golia se ne fu andato, lo spazio piombò in un silenzio assoluto. Persino i sacrifici in gabbia in attesa del macello non emettevano alcun suono."
  },
  AvgDialog_19083_Content_74 = {
    Text = "Murphy rimase seduta accanto al fuoco per un tempo interminabile, finché la luce non si affievolì e le braci non si spensero. Solo allora si schiaffeggiò le guance, come riscuotendosi da un sogno."
  },
  AvgDialog_19083_Content_75 = {
    Text = "Diede un forte calcio a una gabbia vicina, facendo rannicchiare nell'angolo la donna emaciata al suo interno."
  },
  AvgDialog_19083_Content_76 = {
    Text = "Ehi, hai sentito tutto quello che è stato detto, vero?"
  },
  AvgDialog_19083_Content_77 = {Text = "S-sì..."},
  AvgDialog_19083_Content_78 = {
    Text = "Non ti sto aiutando per niente. Una volta fuggita, trova un modo per tornare e portarmi con te."
  },
  AvgDialog_19083_Content_79 = {
    Text = "Temo di non avere tutte queste capacità. Sono solo un'ordinaria scienziata..."
  },
  AvgDialog_19083_Content_8 = {
    Text = "Lo vide.\nAlzando lo sguardo, la \"Madre\" abbassò tre paia di peduncoli oculari, incontrando il suo Sguardo."
  },
  AvgDialog_19083_Content_80 = {
    Text = "Allora inventati qualcosa! Con il cervello di una scienziata, sicuramente puoi trovare almeno una soluzione!"
  },
  AvgDialog_19083_Content_81 = {
    Text = "Vedendo la ragazza che lottava per trattenere le lacrime, la donna ricordò il volto di sua figlia, ormai sbiadito dalla memoria, e finalmente provò una fitta di compassione."
  },
  AvgDialog_19083_Content_82 = {
    Text = "Non essere troppo triste."
  },
  AvgDialog_19083_Content_83 = {
    Text = "Ogni volta che incontravo un ostacolo nella ricerca e non riuscivo a dormire, sgattaiolavo nella stanza di mia figlia, mi sedevo accanto al suo letto e la guardavo."
  },
  AvgDialog_19083_Content_84 = {
    Text = "È così piccola, così tranquilla... Solo pensare che tutto quello che ho fatto è per il suo futuro più luminoso rende tutta la fatica sopportabile."
  },
  AvgDialog_19083_Content_85 = {
    Text = "Anch'io sono stata madre, quindi lo so... La tua madre biologica deve aver atteso con ansia il tuo arrivo. C'è sicuramente qualcuno in questo mondo che ti ama."
  },
  AvgDialog_19083_Content_86 = {Text = "..."},
  AvgDialog_19083_Content_87 = {
    Text = "Hai finito di parlare? Smettila di intrometterti nei miei affari e preoccupati di salvare la tua di vita!"
  },
  AvgDialog_19083_Content_88 = {
    Text = [[
"Mi dispiace..."
"Io... non voglio morire..."]]
  },
  AvgDialog_19083_Content_89 = {
    Text = "Non voglio... finire così..."
  },
  AvgDialog_19083_Content_9 = {
    Text = "Era una colossale bestia cremisi, con le zone macchiate di sangue che diventavano di un bianco trasparente. La \"Madre\" emanava un debole bagliore, illuminando temporaneamente un piccolo mondo."
  },
  AvgDialog_19084_Content_1 = {
    Text = "Lasci andare l'autista."
  },
  AvgDialog_19084_Content_10 = {
    Text = "Fin dall'inizio, i loro attacchi avevano uno scopo: spingerci qui, alla <Blue:Banchina N. 2 del Molo 3>."
  },
  AvgDialog_19084_Content_11 = {
    Text = "Ma questo posto sembra ordinario..."
  },
  AvgDialog_19084_Content_12 = {
    Text = "Vero, l'Ormeggio 2 non ha alcun significato."
  },
  AvgDialog_19084_Content_13 = {
    Text = "Il vero problema è la <Blue:nave> attraccata qui."
  },
  AvgDialog_19084_Content_14 = {Text = "Una nave?"},
  AvgDialog_19084_Content_15 = {
    Text = "Le parole di Ramona scatenarono una tempesta, disperdendo la nebbia nella tua mente."
  },
  AvgDialog_19084_Content_16 = {Text = "!"},
  AvgDialog_19084_Content_17 = {
    Text = "Un vascello colossale si materializzò alle tue spalle, eclissando la luna, avvolgendo ogni cosa nell'ombra."
  },
  AvgDialog_19084_Content_18 = {
    Text = "Questa nave era già qui?"
  },
  AvgDialog_19084_Content_19 = {
    Text = "Potrebbe essere sempre stata lì, ma per qualche ragione sconosciuta, l'abbiamo ignorata."
  },
  AvgDialog_19084_Content_2 = {
    Text = "Troppi; la ritirata è tagliata."
  },
  AvgDialog_19084_Content_20 = {
    Text = "Lo scafo esterno era arrugginito e sbiadito, le iscrizioni originali illeggibili, il nome in vernice bianca a malapena distinguibile."
  },
  AvgDialog_19084_Content_21 = {
    Text = "Sona... riel?"
  },
  AvgDialog_19084_Content_22 = {
    Text = [[
<Blue:Sona-Nyl>.
Erica, ci sono registrazioni nei Mythag?]]
  },
  AvgDialog_19084_Content_23 = {
    Text = "La Sonanir, precedentemente della <Blue:Black Star Shipping>, operava come nave passeggeri per rotte transoceaniche. Dopo il fallimento della compagnia, fu acquistata in forma anonima, reimmatricolata e convertita in nave cargo."
  },
  AvgDialog_19084_Content_24 = {
    Text = "William, conosci questa nave?"
  },
  AvgDialog_19084_Content_25 = {
    Text = "AF 288, il Sonanil affondò in una tempesta. Anni dopo, avvistamenti della <Blue:\"Nave Fantasma\"> iniziarono ad apparire lungo la costa del Mare del Nord."
  },
  AvgDialog_19084_Content_26 = {
    Text = "Un investigatore Mythag salì a bordo una volta, ma non riportò alcuna informazione utilizzabile."
  },
  AvgDialog_19084_Content_27 = {
    Text = "Nessuna informazione utilizzabile..."
  },
  AvgDialog_19084_Content_28 = {
    Text = "Ma è tornato sano e salvo al campus, giusto?"
  },
  AvgDialog_19084_Content_29 = {
    Text = "Sì, a parte le lacune nella memoria, nessun'altra anomalia.\nBreve convalescenza, poi di nuovo in prima linea."
  },
  AvgDialog_19084_Content_3 = {
    Text = "La superficie del mare illuminata dalla luce della luna continua ad agitarsi con increspature. Nei fondali dove la luce non riesce a penetrare, non si sa quanti nemici si nascondano ancora."
  },
  AvgDialog_19084_Content_30 = {
    Text = "Possiamo metterlo in collegamento?"
  },
  AvgDialog_19084_Content_31 = {
    Text = "Purtroppo, prima che tu entrassi nel Mythag, è caduto in azione durante una missione."
  },
  AvgDialog_19084_Content_32 = {Text = "Aspetta!"},
  AvgDialog_19084_Content_33 = {
    Text = "Ramona, non vorrai mica..."
  },
  AvgDialog_19084_Content_34 = {
    Text = "Sì, non ci lasceranno attendere i soccorsi."
  },
  AvgDialog_19084_Content_35 = {
    Text = "L'accerchiamento si stringe, e l'arma del nemico è già ai tuoi piedi."
  },
  AvgDialog_19084_Content_36 = {
    Text = "Saliamo a bordo."
  },
  AvgDialog_19084_Content_4 = {
    Text = "Indietro @2—! @1! Ordine @1!"
  },
  AvgDialog_19084_Content_5 = {
    Text = "Stringendo il cappio attorno a un certo ormeggio, gli uomini-pesce arrestarono la loro avanzata, mormorando un incomprensibile farfugliamento in uno stallo."
  },
  AvgDialog_19084_Content_6 = {
    Text = "L'attacco si è fermato?"
  },
  AvgDialog_19084_Content_7 = {Text = "..."},
  AvgDialog_19084_Content_8 = {
    Text = "Ramona, cos'è?"
  },
  AvgDialog_19084_Content_9 = {
    Text = "Dal sospingerci a nord al sigillare l'uscita, hanno sempre lasciato un sentiero."
  },
  AvgDialog_19085_Content_1 = {
    Text = "Finalmente è finita..."
  },
  AvgDialog_19085_Content_10 = {
    Text = "La mascella da pesce del Navigatore si spalanca in modo impossibile, la membrana che la connette tesa fino alla trasparenza."
  },
  AvgDialog_19085_Content_11 = {
    Text = "Spinto dalla paura, dalla speranza e dalla fede, erutta con una vitalità inimmaginabile, scaraventandoti da parte con un grido mentre si precipita fuori dalla sala macchine."
  },
  AvgDialog_19085_Content_12 = {
    Text = "No—sta scappando!"
  },
  AvgDialog_19085_Content_2 = {
    Text = "Murphy calcia il Navigatore privo di sensi, il cui corpo simile a un pesce rotola via inerte."
  },
  AvgDialog_19085_Content_3 = {
    Text = "Non dovrebbero più essere in grado di combattere... sono solo dei poveretti. Lasciali stare."
  },
  AvgDialog_19085_Content_4 = {
    Text = "Sbrighiamoci e andiamo via di qui."
  },
  AvgDialog_19085_Content_5 = {
    Text = "Gur... gurgll..."
  },
  AvgDialog_19085_Content_6 = {
    Text = "Tra i Navigatori caduti, uno lotta per rialzarsi, usando un'arma spezzata per sostenere il proprio corpo."
  },
  AvgDialog_19085_Content_7 = {
    Text = "Perché... perché... dal lato di @4 Lord... perché?"
  },
  AvgDialog_19085_Content_8 = {
    Text = "Oh, Dea Madre, Dea Madre... Gulp, gulp...!"
  },
  AvgDialog_19085_Content_9 = {
    Text = "...Mio signore, @4 mio signore!"
  },
  AvgDialog_19086_Content_1 = {
    Text = "Una mano grigio-azzurra sbucò dalle macerie, le sue dita palmate afferrarono lo stivale di Murphy."
  },
  AvgDialog_19086_Content_2 = {
    Text = "Goo, Goo..."
  },
  AvgDialog_19086_Content_3 = {
    Text = "Questo tizio è ancora vivo!? Era chiaramente sepolto sotto le macerie."
  },
  AvgDialog_19086_Content_4 = {
    Text = "Dio... Dio@1..."
  },
  AvgDialog_19086_Content_5 = {
    Text = "...Non avvicinarti!"
  },
  AvgDialog_19087_Content_1 = {
    Text = "Un fetore di putrefazione ti si insinuò nelle narici."
  },
  AvgDialog_19087_Content_2 = {
    Text = "I Navigatori furono convocati dal loro capo, riversandosi fuori da ogni lato delle cabine."
  },
  AvgDialog_19088_Content_1 = {
    Text = "Passi pesanti riecheggiarono dall'altra estremità del ponte. Una voce maschile roca parlò in una lingua sconosciuta, e i nemici circostanti si ritirarono come una marea."
  },
  AvgDialog_19088_Content_10 = {
    Text = "Ramona si voltò, ma non c'era nessuno. I due si erano separati durante l'accerchiamento nemico."
  },
  AvgDialog_19088_Content_11 = {
    Text = "Oh no! <Yellow:%player%>!"
  },
  AvgDialog_19088_Content_12 = {
    Text = "Da dietro le casse impilate lì vicino giunse un fruscio insolito."
  },
  AvgDialog_19088_Content_13 = {
    Text = "Smettila di nasconderti, so che sei lì. Non è il momento per i tuoi capricci, \"Giovane Maestro Ashe\"."
  },
  AvgDialog_19088_Content_14 = {
    Text = "Ramona scosse la testa con rassegnazione. Scrollò il sangue dalla spada, la rinfoderò e si diresse verso l'angolo pieno di casse."
  },
  AvgDialog_19088_Content_15 = {Text = "@1@2...!"},
  AvgDialog_19088_Content_16 = {Text = "Ch...!"},
  AvgDialog_19088_Content_18 = {
    Text = [[
Attacchi feroci trafissero le casse e impalarono il nemico.
Il sangue blu-nero spalmato sui tentacoli si mescolava con le schegge di legno, emanando un fetore nauseante.]]
  },
  AvgDialog_19088_Content_19 = {
    Text = "Il padrone dell'appendice scosse violentemente il corpo alieno aggrappato ad essa, facendo crollare la cassa con un fragore.\n—La figura del ragazzo apparve davanti a Ramona."
  },
  AvgDialog_19088_Content_2 = {
    Text = "Mio signore! Questo è l'ordine del Sommo Sacerdote..."
  },
  AvgDialog_19088_Content_20 = {Text = "!?"},
  AvgDialog_19088_Content_21 = {
    Text = "I Risvegliatori non possono lasciare il Reame dei Mythag senza l'approvazione del responsabile delle Operazioni sul Campo e il collegamento dell'Investigatore. Pensavo ne fossi consapevole..."
  },
  AvgDialog_19088_Content_22 = {
    Text = "Risvegliatore Tulu, Archivio N. 6291, Nome in codice <Blue:\"Il Signore Dormiente\">"
  },
  AvgDialog_19088_Content_23 = {
    Text = "Credo tu sappia bene che i vostri cosiddetti \"precetti\" non hanno alcun significato per me."
  },
  AvgDialog_19088_Content_24 = {
    Text = "E non usare quello stupido nome in codice con me."
  },
  AvgDialog_19088_Content_25 = {Text = "Tulu."},
  AvgDialog_19088_Content_26 = {
    Text = "Non sono come quei testardi membri del Comitato; i Risvegliatori non sono bestie che necessitano di catene, e questo non è il momento di parlare di \"fughe\"."
  },
  AvgDialog_19088_Content_27 = {
    Text = "La mia preoccupazione è che tu non sei nella lista delle missioni sul campo e non sei stato collegato con nessuno.\nSe resti lontano dal <Yellow:Nucleo> dei Mythag troppo a lungo, rischi di perdere il controllo."
  },
  AvgDialog_19088_Content_28 = {
    Text = "Non importa. Non mi lascerò governare da cosiddetti istinti."
  },
  AvgDialog_19088_Content_29 = {
    Text = "Il Risveglio conservava le sembianze di un ragazzo, eppure ogni parola e ogni gesto trasudavano l'Autorità di un superiore.\nUn semplice sguardo fugace bastava a far rizzare i capelli."
  },
  AvgDialog_19088_Content_3 = {
    Text = "Intendi dire..."
  },
  AvgDialog_19088_Content_30 = {Text = "...Sigh."},
  AvgDialog_19088_Content_31 = {
    Text = "Ramona emise un lungo sospiro e sostenne di nuovo il suo sguardo."
  },
  AvgDialog_19088_Content_32 = {
    Text = "—Voglio solo sapere, perché sei qui?\nSei stato in un sonno profondo per anni. Nemmeno la mutazione della <Yellow:Cerimonia della Chiave d'Argento> è riuscita a svegliarti."
  },
  AvgDialog_19088_Content_33 = {
    Text = "Eppure ora sei qui, a rischio di perdere la ragione... Ciò che è accaduto su questa nave deve avere una grande importanza per te."
  },
  AvgDialog_19088_Content_34 = {
    Text = "Tutto ciò che si sta svolgendo qui ha origine da me.\nQuanto ai dettagli, non ti riguardano."
  },
  AvgDialog_19088_Content_35 = {
    Text = "Oh? Quindi i murloc che ci inseguono non hanno nulla a che fare con me? O forse il Custode scomparso non mi riguarda?"
  },
  AvgDialog_19088_Content_36 = {Text = "..."},
  AvgDialog_19088_Content_37 = {
    Text = "La priorità immediata è trovare il Custode e lasciare questa nave.\nQuindi, non farò altre domande."
  },
  AvgDialog_19088_Content_38 = {
    Text = "Puoi restare in silenzio per ora, ma sai che troverò le risposte."
  },
  AvgDialog_19088_Content_4 = {
    Text = "...D'accordo, capisco."
  },
  AvgDialog_19088_Content_5 = {
    Text = "Non andartene! Chi sei esattamente?"
  },
  AvgDialog_19088_Content_6 = {
    Text = "Il giovane Risvegliatore ripose la sua arma, si voltò a guardare Ramona, e poi svanì dal ponte insieme al suo sciame."
  },
  AvgDialog_19088_Content_7 = {
    Text = "Che... cosa significa tutto questo?"
  },
  AvgDialog_19088_Content_8 = {
    Text = "Non possiamo preoccuparcene adesso. Il loro vero obiettivo non siamo noi... Approfittiamo di questa occasione per trovare un modo di scendere dalla nave."
  },
  AvgDialog_19088_Content_9 = {
    Text = "Procediamo con cautela ed evitiamo quei murloc... Custode!"
  },
  AvgDialog_19089_Content_1 = {
    Text = "In appena mezz'ora con Murphy, hai vomitato tre volte."
  },
  AvgDialog_19089_Content_2 = {
    Text = "Intense vertigini e nausea arrivano sempre insieme, con l'acido gastrico che risale bruciando la gola e causando un dolore debole e persistente."
  },
  AvgDialog_19089_Content_3 = {
    Text = "Mi fa male la testa..."
  },
  AvgDialog_19089_Content_4 = {
    Text = [[
Non starai per morire, vero?
Io... vado a cercare aiuto! Aspettami!]]
  },
  AvgDialog_19089_Content_5 = {
    Text = "Non andare da solo. È troppo pericoloso."
  },
  AvgDialog_19089_Content_6 = {
    Text = [[
Mi sento molto meglio, davvero.
Andiamo. Il mio compagno mi sta ancora aspettando.]]
  },
  AvgDialog_19090_Content_1 = {
    Text = "Murphy contemplò il cielo, un vortice di sfumature strane e luminescenti.\nGli uccelli volteggiavano sotto il velo scintillante, la luce soffusa e distorta, a proteggere la nave da qualsiasi tempesta al di là."
  },
  AvgDialog_19090_Content_10 = {
    Text = "Sì. In altre parole, sia Murphy che noi consideriamo <Blue:la signorina Celeste> fondamentale.\nE ora... è probabilmente sotto il controllo di Miryam, la leader dei Navigatori."
  },
  AvgDialog_19090_Content_11 = {
    Text = "Dannazione... quella donna..."
  },
  AvgDialog_19090_Content_12 = {
    Text = "Murphy si stringe il petto, l'espressione grave mentre fissa il confine del Dominio."
  },
  AvgDialog_19090_Content_13 = {
    Text = "L'unica cosa che le importa è la rinascita degli dèi; nient'altro conta per lei."
  },
  AvgDialog_19090_Content_14 = {
    Text = "Ucciderà tutti, e alla fine questo mostro roderà il mio cuore fino a non lasciare nulla."
  },
  AvgDialog_19090_Content_15 = {
    Text = "Non voglio... morire così..."
  },
  AvgDialog_19090_Content_16 = {
    Text = "Per un istante, il silenzio si diffuse come la quiete della morte."
  },
  AvgDialog_19090_Content_2 = {
    Text = "Gli appunti del culto del Navigatore sono ossessionati dall'<Blue:allineamento stellare>, e insistono che il rito di nascita debba avvenire in un istante preciso. Ecco perché quella donna voleva farmi addormentare."
  },
  AvgDialog_19090_Content_3 = {
    Text = "Il Capitano ipotizzò che la crescita del dio potesse essere legata ai cicli celesti.\nCosì Celeste tessé questo Dominio Isolato attorno alla nave."
  },
  AvgDialog_19090_Content_4 = {
    Text = "Abbiamo indovinato. Da quando ha lasciato il vero cielo, si è ammutolito.\nSe ci nascondiamo nel Dominio durante questo allineamento, potrebbe dormire per sempre."
  },
  AvgDialog_19090_Content_5 = {
    Text = "Aspetta, Celeste?"
  },
  AvgDialog_19090_Content_6 = {
    Text = "Qualcuno può spiegarmi? Chi è \"Celeste\"?"
  },
  AvgDialog_19090_Content_7 = {
    Text = "Eh? Non te l'ho già spiegato?"
  },
  AvgDialog_19090_Content_8 = {
    Text = "Celeste è la compagna del capitano e una Risvegliatrice.\nControlla il Sonaniel, che avrebbe dovuto affondare, e ha creato questo Dominio."
  },
  AvgDialog_19090_Content_9 = {
    Text = "Dipende anche da lei se possiamo tornare sulla terraferma?"
  },
  AvgDialog_19091_Content_1 = {
    Text = "L'umore di Murphy sprofondò, e tu non sapevi come consolarla. Nel frattempo, Ramona era immersa nei suoi pensieri, con lo sguardo rivolto agli uccelli marini nel cielo."
  },
  AvgDialog_19091_Content_10 = {
    Text = [[
Secondo i calcoli dell'Osservatorio Reale, la luna dovrebbe raggiungere il perigeo intorno al <Blue:giorno di San Patrizio>.
L'attuale fase lunare sfida le leggi scientifiche.]]
  },
  AvgDialog_19091_Content_11 = {
    Text = "Puoi parlare in modo comprensibile?"
  },
  AvgDialog_19091_Content_12 = {
    Text = "Sì, era una notte con una luna eccezionalmente grande.\nLa luna era così luminosa che tutte le altre costellazioni erano invisibili."
  },
  AvgDialog_19091_Content_13 = {
    Text = "C-Cosa?! È proprio oggi..."
  },
  AvgDialog_19091_Content_14 = {
    Text = "Anche se riuscissimo a sfuggire ai Navigatori, la cosa dentro il mio cuore mi ucciderà comunque."
  },
  AvgDialog_19091_Content_15 = {
    Text = "Se ci fosse un altro modo per isolare i corpi celesti, potrebbe farti guadagnare più tempo."
  },
  AvgDialog_19091_Content_16 = {
    Text = "<Big:Facile a dirsi!> Fermare il tempo, creare spazi... Niente di tutto ciò è un gioco da ragazzi. Anche io so che non è così semplice."
  },
  AvgDialog_19091_Content_17 = {
    Text = "Aspetta, ce n'è uno! Francis!"
  },
  AvgDialog_19091_Content_18 = {
    Text = "La Stanza di Lily!"
  },
  AvgDialog_19091_Content_19 = {
    Text = "Sì. Doll e la sig.ra Winkle stanno studiando quella stanza, sperando di creare uno spazio sicuro dalla caccia per gli esperimenti."
  },
  AvgDialog_19091_Content_2 = {
    Text = "Per sfuggire all'aria opprimente della nave, stormi di uccelli marini si dispersero, lanciandosi verso la luce iridescente."
  },
  AvgDialog_19091_Content_20 = {
    Text = "La ricerca sta prendendo forma. Prima della nostra partenza, la signora Winkle stava già preparando i test sugli animali."
  },
  AvgDialog_19091_Content_21 = {
    Text = "Non preoccuparti."
  },
  AvgDialog_19091_Content_22 = {
    Text = "La tua scuola... non è sul mare, vero?\nTornare a terra, e poi alla tua scuola... non c'è tempo."
  },
  AvgDialog_19091_Content_23 = {
    Text = "Inoltre, Celeste è ancora nelle mani di quella donna... Non è certo che questa nave raggiunga la riva."
  },
  AvgDialog_19091_Content_24 = {
    Text = [[
Istintivamente, lanci uno sguardo a Ramona.
Ha le sopracciglia aggrottate, eppure la sua postura resta risoluta. Sta ancora cercando un modo per garantire la sicurezza di tutti.]]
  },
  AvgDialog_19091_Content_25 = {Text = "Ramona"},
  AvgDialog_19091_Content_26 = {
    Text = "Ti fissò per un momento, poi finalmente sorrise con consapevole comprensione."
  },
  AvgDialog_19091_Content_27 = {
    Text = "Andiamo, se è ciò che desideri."
  },
  AvgDialog_19091_Content_3 = {
    Text = "Uno, due, tre... Si lanciano verso il cielo, disperati di fuggire, ma il Dominio li blocca dolcemente."
  },
  AvgDialog_19091_Content_5 = {
    Text = "La cortina divenne momentaneamente trasparente sotto l'impatto incessante degli uccelli marini. Quell'istante fugace fu colto con precisione da Ramona—"
  },
  AvgDialog_19091_Content_6 = {
    Text = "Il Dominio... è scomparso per un momento?"
  },
  AvgDialog_19091_Content_7 = {
    Text = "Sì... in effetti, ho sentito una pulsazione."
  },
  AvgDialog_19091_Content_8 = {
    Text = "Celeste si sforza di creare un Dominio che blocchi l'attrazione celeste.\nDifendersi dall'attacco dei Navigatori è troppo per lei."
  },
  AvgDialog_19091_Content_9 = {
    Text = "Corpi celesti... Aspetta, fuori è notte? Come appaiono le stelle e la luna?"
  },
  AvgDialog_19092_Content_10 = {
    Text = "Ecco la mappa."
  },
  AvgDialog_19092_Content_11 = {
    Text = "Questo livello ha un ingresso alla sala motori... Vai a controllare. Le impronte conducono in quella direzione."
  },
  AvgDialog_19092_Content_12 = {
    Text = "Agire avventatamente è pericoloso e imprudente."
  },
  AvgDialog_19092_Content_13 = {
    Text = "Proprio perché è pericoloso, dobbiamo andare.\nNon posso lasciare che il Custode affronti il nemico da solo."
  },
  AvgDialog_19092_Content_14 = {
    Text = "...D'accordo, se insisti."
  },
  AvgDialog_19092_Content_2 = {
    Text = "Ci sono delle tracce qui."
  },
  AvgDialog_19092_Content_3 = {
    Text = "L'acqua di mare aveva inumidito la polvere, lasciando tracce caotiche nella stiva: impronte palmate, segni di trascinamento serpentini e segni di tessuto trascinato..."
  },
  AvgDialog_19092_Content_4 = {
    Text = "Impronte di scarpe!"
  },
  AvgDialog_19092_Content_5 = {
    Text = "Ramona si accovacciò vicino alle scale, esaminò per un momento, poi si alzò e posò delicatamente il piede sull'impronta."
  },
  AvgDialog_19092_Content_6 = {
    Text = "I motivi corrispondono alle scarpe dell'uniforme scolastica. Il Custode è stato qui."
  },
  AvgDialog_19092_Content_7 = {
    Text = "Ecco un altro motivo."
  },
  AvgDialog_19092_Content_8 = {
    Text = "La misura della scarpa è più piccola della mia, probabilmente lasciata da un bambino."
  },
  AvgDialog_19092_Content_9 = {
    Text = "Impossibile seguirle; le impronte scompaiono qui..."
  },
  AvgDialog_19093_Content_1 = {
    Text = "È un Risvegliatore!"
  },
  AvgDialog_19093_Content_10 = {
    Text = "Una risata maniacale riecheggia nel Dominio, e l'atmosfera si fa sempre più tesa—"
  },
  AvgDialog_19093_Content_11 = {
    Text = "Andate pure avanti."
  },
  AvgDialog_19093_Content_12 = {Text = "Cosa?"},
  AvgDialog_19093_Content_13 = {
    Text = "Non state così all'erta, occuparmi di topi in fuga non è compito mio... Tch, <Blue:Lanterna> Quegli incapaci non riescono nemmeno a gestire questo."
  },
  AvgDialog_19093_Content_14 = {
    Text = "Grazie a loro, questa cerimonia è diventata ancora più entusiasmante."
  },
  AvgDialog_19093_Content_15 = {
    Text = "Non solo collegati alla <Blue:Chiesa Portaluce>, ma anche al <Blue:Rito> che hai menzionato..."
  },
  AvgDialog_19093_Content_16 = {
    Text = "Golia... chi sei esattamente?"
  },
  AvgDialog_19093_Content_17 = {
    Text = "Chi sono io? <Big:Hahahaha!>\nPerché non lo chiedi alla persona accanto a te?"
  },
  AvgDialog_19093_Content_18 = {
    Text = "Da dove veniamo io—e questi Navigatori—... Non riesci a indovinare? Dopotutto, tu sei il supremo..."
  },
  AvgDialog_19093_Content_19 = {
    Text = "Che presunzione!"
  },
  AvgDialog_19093_Content_2 = {
    Text = "Una potenza sbalorditiva! Anche per gli standard dei Risvegliatori, pochi possono sperare di eguagliarla."
  },
  AvgDialog_19093_Content_20 = {
    Text = "Che paura, che paura—ma scusa, non sono un tuo suddito fedele."
  },
  AvgDialog_19093_Content_21 = {
    Text = "Devo occuparmi dei preparativi del Rito—non ho tempo per continuare a battibeccare con te."
  },
  AvgDialog_19093_Content_22 = {
    Text = "Vai pure, sgattaiola in giro con i tuoi Tentacoli nascosti. Ma lo sai—la cosa che quella Donna vuole, solo tu puoi fornirla."
  },
  AvgDialog_19093_Content_23 = {
    Text = "—Golia, aspetta!"
  },
  AvgDialog_19093_Content_24 = {
    Text = "Oh? In cos'altro posso esservi d'aiuto, signorina?"
  },
  AvgDialog_19093_Content_25 = {
    Text = "Ammiro chi ha il coraggio di sfidare l'autorità. Hai un'altra possibilità di fare una domanda prima che perda la pazienza."
  },
  AvgDialog_19093_Content_26 = {
    Text = "Riguardo a..."
  },
  AvgDialog_19093_Content_27 = {
    Text = "Ho altre domande sulla Chiesa Portaluce..."
  },
  AvgDialog_19093_Content_3 = {
    Text = "Questa forza..."
  },
  AvgDialog_19093_Content_4 = {
    Text = "Non appena l'esitazione di Tulu divenne evidente, il gigante interruppe pensierosamente il suo attacco."
  },
  AvgDialog_19093_Content_5 = {
    Text = "Capisco... Quindi frequenti gente dell'Università di Mythag."
  },
  AvgDialog_19093_Content_6 = {
    Text = "Golia squadrò i due con uno sguardo nudo e penetrante, poi scoppiò a ridere."
  },
  AvgDialog_19093_Content_7 = {
    Text = "<Big:Ha, hahaha!> Affascinante, davvero affascinante!"
  },
  AvgDialog_19093_Content_8 = {
    Text = "Che espressione farebbe <Blue:quella donna> se vedesse questa scena—impazzirebbe?"
  },
  AvgDialog_19093_Content_9 = {
    Text = "Hahaha, non vedo l'ora che arrivi quel momento!"
  },
  AvgDialog_19094_Content_1 = {
    Text = [[
22:00
Sonaniel
Sala Motori]]
  },
  AvgDialog_19094_Content_10 = {
    Text = "La nave è pericolosa. La guiderò il più vicino possibile alla riva, ma dovrete usare la scialuppa di salvataggio per tornare a terra."
  },
  AvgDialog_19094_Content_11 = {
    Text = "E tu? È pericoloso restare qui dato che la nave è piena di nemici."
  },
  AvgDialog_19094_Content_12 = {
    Text = "Questa è la nostra nave, con il Dominio di <Blue:Celeste> a bordo. Staremo bene."
  },
  AvgDialog_19094_Content_13 = {
    Text = "La Risvegliatrice di nome Celeste lanciò un'occhiata a tutti, emettendo un mormorio appena percettibile."
  },
  AvgDialog_19094_Content_14 = {
    Text = "I Domini sono la manifestazione della volontà di Celeste. Quei Navigatori, che non sono riconosciuti da lei, dovrebbero restare fuori dai Domini."
  },
  AvgDialog_19094_Content_15 = {
    Text = "Potrebbe essere che...?!"
  },
  AvgDialog_19094_Content_16 = {
    Text = "Il nostro imbarco ha causato instabilità nel Dominio.\nAnche se ho rilasciato la passerella, i Navigatori hanno comunque violato il Dominio da altrove... Giusto?"
  },
  AvgDialog_19094_Content_17 = {
    Text = "Scusate, noi..."
  },
  AvgDialog_19094_Content_18 = {
    Text = "Non è colpa vostra. Farvi salire a bordo è stata una decisione che abbiamo preso insieme."
  },
  AvgDialog_19094_Content_19 = {
    Text = "\"Proteggere l'umanità\" è un fardello che grava su Celeste, e come suo compagno, la sosterrò al meglio delle mie capacità."
  },
  AvgDialog_19094_Content_2 = {
    Text = "Troppo pericoloso! Non ti avevo detto di stare alla larga?"
  },
  AvgDialog_19094_Content_20 = {
    Text = "Ugh...! Cough, cough, cough!"
  },
  AvgDialog_19094_Content_21 = {Text = "...!"},
  AvgDialog_19094_Content_22 = {
    Text = "Il capitano inizia a tossire violentemente; il corpo della Risvegliatrice tremola per un istante."
  },
  AvgDialog_19094_Content_23 = {
    Text = "Tulu apparve improvvisamente accanto a Celeste, il suo tentacolo ultraterreno posato sulla spalla di lei."
  },
  AvgDialog_19094_Content_24 = {
    Text = "La sua presenza è estremamente debole; dubito che riuscirà a mantenere la lucidità ancora a lungo."
  },
  AvgDialog_19094_Content_25 = {
    Text = "Celeste non perderà la ragione; non permetterò che diventi un mostro incontrollabile."
  },
  AvgDialog_19094_Content_26 = {
    Text = "Con la fragile vita di un mortale e una Gnosi eterea? Da dove viene la tua fiducia?"
  },
  AvgDialog_19094_Content_27 = {Text = "Tulu!"},
  AvgDialog_19094_Content_28 = {
    Text = [[
Non avere fretta, signorina.
Il Risvegliatore ha ragione.]]
  },
  AvgDialog_19094_Content_29 = {
    Text = "Mantenere l'esistenza di Celeste non è cosa da poco... ma ci sono sempre dei modi."
  },
  AvgDialog_19094_Content_3 = {
    Text = [[
Hai appena visto che sono in grado di gestire questi Navigatori.
Mi chiamo Ramona. Sei tu il capitano?]]
  },
  AvgDialog_19094_Content_30 = {
    Text = "Le reazioni di Celeste erano sempre flebili, come un dipinto senza vita ma squisito, o la polena di una vecchia nave, che osserva in silenzio il mondo e il mare."
  },
  AvgDialog_19094_Content_31 = {
    Text = "Ma in quel momento, come in risposta alle parole del Capitano Elton, si chinò leggermente e gli sfiorò la tesa del cappello."
  },
  AvgDialog_19094_Content_32 = {
    Text = "Ramona notò le condizioni del capitano: quell'uomo alto respirava molto debolmente, tremando incontrollabilmente mentre stava in piedi."
  },
  AvgDialog_19094_Content_33 = {
    Text = "Il tuo corpo..."
  },
  AvgDialog_19094_Content_34 = {
    Text = "Sto bene, è solo un vecchio problema."
  },
  AvgDialog_19094_Content_35 = {
    Text = "A proposito, perché sei sola? Ho visto chiaramente due studenti—\nCeleste, riesci a percepire dove si trova l'altro studente?"
  },
  AvgDialog_19094_Content_36 = {
    Text = [[
La ragazza chiamata per nome tiene lo sguardo fisso sulle sue dita, senza rispondere immediatamente al capitano.
Dopo un po', Celeste alza lentamente lo sguardo verso Ramona.]]
  },
  AvgDialog_19094_Content_37 = {
    Text = "...Non più.\nA parte Elton, Murphy, e..."
  },
  AvgDialog_19094_Content_38 = {
    Text = "Non c'è nessun altro... tranne te."
  },
  AvgDialog_19094_Content_39 = {
    Text = "Com'è possibile?! Siamo stati separati solo per mezz'ora."
  },
  AvgDialog_19094_Content_4 = {
    Text = "Elton, o semplicemente chiamami Capitano."
  },
  AvgDialog_19094_Content_40 = {
    Text = "Inoltre, riesco a percepire il legame con il Custode, {Male=lui,Female=lei} deve essere ancora sulla nave."
  },
  AvgDialog_19094_Content_41 = {
    Text = "Non avere fretta, studentessa. Tutto si risolverà.\nSe il tuo compagno è bravo quanto te, {Male=he,Female=she} starà bene."
  },
  AvgDialog_19094_Content_42 = {
    Text = "Non dimenticare le impronte di scarpe."
  },
  AvgDialog_19094_Content_43 = {
    Text = "Impronte di scarpe..."
  },
  AvgDialog_19094_Content_44 = {
    Text = "Esatto! Il Custode potrebbe essere insieme a un bambino."
  },
  AvgDialog_19094_Content_45 = {
    Text = "Un bambino? Capisco...\nQuella è <Blue:Murphy>, l'unica passeggera su questa nave."
  },
  AvgDialog_19094_Content_5 = {
    Text = "Il Capitano Elton tirò fuori un pacchetto di sigarette dalla sua borsa da cintura. Proprio mentre pizzicava l'ultimo po' di tabacco, un filo di nebbia bianca gli sfiorò la mano."
  },
  AvgDialog_19094_Content_6 = {
    Text = "Emise un profondo sospiro e ripose il pacchetto di sigarette."
  },
  AvgDialog_19094_Content_7 = {
    Text = "Vieni dall'Università di Mythag, vero? Riconosco quell'uniforme."
  },
  AvgDialog_19094_Content_8 = {
    Text = "Sì, molti anni fa, uno studente anziano della nostra scuola salì a bordo di questa nave."
  },
  AvgDialog_19094_Content_9 = {
    Text = "Peccato, non è un buon momento adesso.\nIn qualsiasi altro giorno, avrei potuto offrirti da bere e fare una bella chiacchierata."
  },
  AvgDialog_19095_Content_10 = {
    Text = "No... no... Me lo aveva promesso..."
  },
  AvgDialog_19095_Content_11 = {
    Text = "La donna emaciata mostrò finalmente una reazione. Alzò lo sguardo vacuo, mormorando tra sé."
  },
  AvgDialog_19095_Content_12 = {
    Text = "Il mio Dio onnipotente eserciterà il Suo potere... Per giudicare quegli eretici che hanno forgiato falsità!"
  },
  AvgDialog_19095_Content_13 = {
    Text = "Estrasse un pugnale dalla cintura: fiamme nero-violacee, dense come nebbia, avvolgevano la lama, irradiando un gelo mortale."
  },
  AvgDialog_19095_Content_14 = {
    Text = "Il pugnale è in fiamme!"
  },
  AvgDialog_19095_Content_15 = {
    Text = "Impostore... Muori!"
  },
  AvgDialog_19095_Content_16 = {
    Text = "Dietro di me!"
  },
  AvgDialog_19095_Content_17 = {
    Text = "—Il freddo e sinistro Fuoco della Morte sul pugnale ha incendiato la polvere di carbone."
  },
  AvgDialog_19095_Content_18 = {
    Text = "<BigShake:Aaahhh!>"
  },
  AvgDialog_19095_Content_19 = {
    Text = "Tra le reazioni a catena di fuoco e polvere, l'aria si è espansa rapidamente, e il rombo assordante dell'esplosione ha avvolto tutti."
  },
  AvgDialog_19095_Content_2 = {
    Text = "Questi edifici stanno scomparendo."
  },
  AvgDialog_19095_Content_20 = {
    Text = "Le fiamme si gonfiarono davanti a te, la paratia alle tue spalle squarciata dall'esplosione."
  },
  AvgDialog_19095_Content_21 = {
    Text = "%player%, dammi la mano!"
  },
  AvgDialog_19095_Content_22 = {
    Text = "L'impatto ha squarciato il metallo della nave; tra il gioco di luci fantasmagoriche e fiamme, hai mancato per un soffio la mano tesa della ragazza."
  },
  AvgDialog_19095_Content_23 = {
    Text = "— Cadi nel mare profondo."
  },
  AvgDialog_19095_Content_3 = {
    Text = "Questa è l'illusione creata da Miryam, forse il suo cosiddetto <Blue:Reame Divino>..."
  },
  AvgDialog_19095_Content_4 = {
    Text = "il Regno divino è tornato... L'ossessione che l'ha sostenuta per migliaia di anni è stata infranta.\nTulu, hai qualche parola di conforto?"
  },
  AvgDialog_19095_Content_5 = {Text = "..."},
  AvgDialog_19095_Content_6 = {
    Text = "Il nemico ha riacquistato un po' di lucidità dal caos e si è liberato della forma mostruosa."
  },
  AvgDialog_19095_Content_7 = {
    Text = "Miryam giaceva debole nella polvere nera, il Suo Sguardo vacuo, senza reagire neppure quando Tulu si avvicinò."
  },
  AvgDialog_19095_Content_8 = {
    Text = "Smettila di aggrapparti al delirio, Miryam."
  },
  AvgDialog_19095_Content_9 = {
    Text = "La nostra era, il nostro <Blue:Reame Eterno>, la sua caduta è segnata dal Sigillo."
  },
  AvgDialog_19096_Content_1 = {
    Text = "Il nostro Comunicatore è costoso?"
  },
  AvgDialog_19096_Content_2 = {
    Text = "L'Argento che contiene potrebbe essere scambiato al mercato nero per una proprietà nel centro di Londinium."
  },
  AvgDialog_19096_Content_3 = {Text = "?!"},
  AvgDialog_19097_Content_1 = {
    Text = "L'attacco sfondò un lato della parete della sala motori, con ombre simili a serpenti che si attorcigliavano in grappoli, sconvolgendo la battaglia fino a quel momento equilibrata."
  },
  AvgDialog_19097_Content_10 = {
    Text = "Non dovevi essere trascinata in tutto questo."
  },
  AvgDialog_19097_Content_11 = {
    Text = "Elton strinse i denti e avanzò, posizionandosi davanti a Ramona e Celeste."
  },
  AvgDialog_19097_Content_12 = {
    Text = "Maestro Sacerdote, non capisco cosa intendiate."
  },
  AvgDialog_19097_Content_13 = {
    Text = "Anche adesso... ti aggrappi ancora alle tue illusioni?"
  },
  AvgDialog_19097_Content_14 = {
    Text = "La donna si portò in prima fila nel gruppo dei Navigatori, e Ramona riuscì a vederla chiaramente."
  },
  AvgDialog_19097_Content_15 = {
    Text = "Era la donna apparsa durante la prima imboscata dopo essere saliti a bordo della nave."
  },
  AvgDialog_19097_Content_16 = {
    Text = "Imperdonabile... Imperdonabile, ingiustificabile!"
  },
  AvgDialog_19097_Content_17 = {
    Text = "Celeste! Sbrigati!"
  },
  AvgDialog_19097_Content_18 = {
    Text = "Celeste alzò la bussola in alto, la luce fluente che vorticava come uccelli attorno a Ramona."
  },
  AvgDialog_19097_Content_19 = {
    Text = "In un batter d'occhio, fu spinta fuori dalla sala motori da quella forza irresistibile."
  },
  AvgDialog_19097_Content_2 = {
    Text = "Tra le ombre eteree, un'elegante figura femminile entrò lentamente nella sala motori.\nLa sua presenza sembrava immobilizzare l'aria intorno a lei."
  },
  AvgDialog_19097_Content_20 = {Text = "Ramona?!"},
  AvgDialog_19097_Content_21 = {Text = "Sei tu!"},
  AvgDialog_19097_Content_3 = {Text = "Oh no...!"},
  AvgDialog_19097_Content_4 = {
    Text = "I miei tesori e le mie speranze..."
  },
  AvgDialog_19097_Content_5 = {
    Text = "Capitano Elton, un tempo mi fidavo della tua lealtà... Ed è così che mi ripaghi?"
  },
  AvgDialog_19097_Content_6 = {
    Text = "Un potere capace di assumere una forma... Potrebbe essere anche lei una Risvegliatrice?"
  },
  AvgDialog_19097_Content_7 = {
    Text = "Celeste, porta questa studentessa e il suo Risvegliatore fuori di qui!"
  },
  AvgDialog_19097_Content_8 = {
    Text = "Aspetta un momento?! Capitano, forse possiamo aiutare—"
  },
  AvgDialog_19097_Content_9 = {
    Text = "Attraverso il fumo sollevato dallo sciame di serpenti, Ramona cercò di individuare Tulu, ma il giovane Risvegliatore non si trovava da nessuna parte nella sala motori."
  },
  AvgDialog_19098_Content_1 = {
    Text = "<Yellow:Dissoluzione> Cos'è questo? Questa ferita nera?\nAnche la sua vera madre era coperta da questi segni."
  },
  AvgDialog_19098_Content_2 = {
    Text = "Sei mesi fa, quando mi risvegliai dal mio sonno, la Dissoluzione era piccola come un seme di sesamo. Man mano che cresceva, anche la ferita si ingrandiva..."
  },
  AvgDialog_19098_Content_3 = {
    Text = "A volte, nel silenzio della notte, riesco persino a sentire il suono di un liquido che scorre dalle ferite..."
  },
  AvgDialog_19098_Content_4 = {Text = "Murphy..."},
  AvgDialog_19098_Content_5 = {
    Text = "Metti via quell'espressione pietosa e occupati prima di questi tizi."
  },
  AvgDialog_19099_Content_1 = {
    Text = [[
22:30  
Sonanil  
Ponte 3]]
  },
  AvgDialog_19099_Content_10 = {
    Text = "Le manca un secolo di esperienza, conoscenze avanzate e avventure nel mondo.\nMettendo da parte il suo ruolo di Santa Fanciulla della Chiesa, la sua vita è persino più semplice di quella delle altre ragazze della sua età."
  },
  AvgDialog_19099_Content_11 = {
    Text = "Togli la spilla"
  },
  AvgDialog_19099_Content_12 = {
    Text = "Prendi questa e resta qui."
  },
  AvgDialog_19099_Content_13 = {
    Text = "Un lascito, un'eredità?\nVi avverto, non gettate via le vostre vite sconsideratamente!"
  },
  AvgDialog_19099_Content_14 = {
    Text = "È un Comunicatore. Potrebbe non funzionare in questo Dominio, ma la scuola deve star cercando di contattarci."
  },
  AvgDialog_19099_Content_15 = {
    Text = [[
Se riesci a vedere la <Yellow:Dissoluzione>, allora devi avere sufficiente potere spirituale per usare questo comunicatore.
Concentra la mente quando la spilla si illumina, e stabilirai il contatto con l'altra persona.]]
  },
  AvgDialog_19099_Content_16 = {
    Text = "Ma che vi prende... sembra che stiate marciando verso la morte."
  },
  AvgDialog_19099_Content_17 = {
    Text = "Murphy strinse la spilla."
  },
  AvgDialog_19099_Content_18 = {
    Text = "Ehi! Tornate in fretta! Se la nave attracca, non vi aspetterò!"
  },
  AvgDialog_19099_Content_2 = {
    Text = "Aspettate, dove state andando?!"
  },
  AvgDialog_19099_Content_3 = {
    Text = "La signorina Celeste non riesce a gestire il nemico, ma forse noi possiamo.\nFermare il rituale eretico è anche uno dei doveri di un Investigatore di Mythag."
  },
  AvgDialog_19099_Content_4 = {
    Text = "Voi?! Non siate assurdi, è un suicidio!\nÈ un mostro, un mostro! Nessuno può fermarla!"
  },
  AvgDialog_19099_Content_5 = {
    Text = "Allora, se questa fosse l'ultima ora della mia vita, non la sprecherò in Preghiera."
  },
  AvgDialog_19099_Content_6 = {
    Text = "Credo che nemmeno tu lo faresti, giusto? Altrimenti, perché darti tanta pena per fuggire dal culto?"
  },
  AvgDialog_19099_Content_7 = {Text = "Io..."},
  AvgDialog_19099_Content_8 = {
    Text = "Non è solo per te. Ricorda, anche noi siamo in Attesa di scendere dalla nave."
  },
  AvgDialog_19099_Content_9 = {
    Text = "Il sottile conforto di Ramona non funzionò; Murphy era ancora smarrita, il volto che tradiva inquietudine."
  },
  AvgDialog_19100_Content_1 = {
    Text = "Questi Navigatori... hanno assunto completamente l'aspetto di pesci."
  },
  AvgDialog_19100_Content_10 = {
    Text = "È corretto... Questo è qualcosa che solo noi possiamo compiere."
  },
  AvgDialog_19100_Content_11 = {
    Text = "Preparatevi, il nemico si avvicina!"
  },
  AvgDialog_19100_Content_2 = {
    Text = "Murphy è stata cresciuta da persone completamente diverse da lei?"
  },
  AvgDialog_19100_Content_3 = {
    Text = "Sì, quindi sono davvero sorpreso che condivida valori simili a quelli della gente comune. È un miracolo."
  },
  AvgDialog_19100_Content_4 = {
    Text = "Tuttavia, in questo momento abbiamo bisogno di pregare per un altro miracolo."
  },
  AvgDialog_19100_Content_5 = {
    Text = "Fermare il rituale"
  },
  AvgDialog_19100_Content_6 = {
    Text = "Esatto. Se il rituale continua, chissà che tipo di mostro nascerà dal corpo di Murphy."
  },
  AvgDialog_19100_Content_7 = {
    Text = [[
Le nostre sole forze non bastano a porre fine a tutto questo.
Ma se riuscissimo a salvare la signorina Celeste e a far scendere Murphy dalla nave per prima...]]
  },
  AvgDialog_19100_Content_8 = {
    Text = "Questo è qualcosa che solo noi possiamo compiere."
  },
  AvgDialog_19100_Content_9 = {Text = "..."},
  AvgDialog_19101_Content_1 = {
    Text = "Studentessa! Stai lontana da qui!"
  },
  AvgDialog_19101_Content_2 = {
    Text = "L'uomo di mezza età gridò a gran voce, attirando l'attenzione della maggior parte dei Navigatori."
  },
  AvgDialog_19101_Content_3 = {
    Text = "A giudicare dal suo abbigliamento, deve essere il capitano."
  },
  AvgDialog_19101_Content_4 = {
    Text = "E la ragazza accanto a lui... Non posso permettere che siano in pericolo."
  },
  AvgDialog_19101_Content_5 = {
    Text = "Goo... Intrusione...!"
  },
  AvgDialog_19101_Content_6 = {
    Text = "Attenzione, il nemico ci ha avvistati."
  },
  AvgDialog_19102_Content_1 = {
    Text = "Shlkk——"
  },
  AvgDialog_19102_Content_10 = {
    Text = "Ma andrà tutto bene; torneremo a terra sani e salvi."
  },
  AvgDialog_19102_Content_11 = {
    Text = "Murphy... Stai bene? Non c'è bisogno di sforzarti."
  },
  AvgDialog_19102_Content_12 = {
    Text = "Chi si sta sforzando? Non ho visto nessuno... aspetta, non ce n'è uno proprio davanti a me?"
  },
  AvgDialog_19102_Content_13 = {
    Text = "Qualcuno è sopravvissuto all'<Yellow:esplosione> ma ha battuto la testa e continua a fingere di stare bene."
  },
  AvgDialog_19102_Content_14 = {
    Text = "Aspetta, aspetta? A chi ti riferisci?"
  },
  AvgDialog_19102_Content_15 = {
    Text = "Sei davvero tosto, ma a giudicare dal tuo aspetto, temo che la tua testa abbia ancora qualche lesione interna..."
  },
  AvgDialog_19102_Content_16 = {Text = "Argh!"},
  AvgDialog_19102_Content_17 = {
    Text = "Lo scafo ruggì di nuovo, come se fosse sul punto di spezzarsi, e il ponte sotto i miei piedi tremò leggermente."
  },
  AvgDialog_19102_Content_18 = {
    Text = "Il Sonanil sta perdendo il controllo... Non mi resta molto tempo."
  },
  AvgDialog_19102_Content_19 = {
    Text = "Dobbiamo trovare il capitano, il suo equipaggio e Ramona, e abbandonare la nave il prima possibile."
  },
  AvgDialog_19102_Content_2 = {
    Text = "Una punta affilata esplode dal petto grigio-azzurro, fluidi che sprizzano mentre il Navigatore si accascia."
  },
  AvgDialog_19102_Content_20 = {
    Text = "Le parole di Murphy ti trafiggono la mente ancora una volta, ma questa volta, invece del desiderio di vomitare, provi una lucidità senza precedenti."
  },
  AvgDialog_19102_Content_21 = {
    Text = "Murphy, cosa hai appena detto?"
  },
  AvgDialog_19102_Content_22 = {
    Text = "È solo il cervello a essere danneggiato, o c'è dell'altro?"
  },
  AvgDialog_19102_Content_23 = {
    Text = "Ho detto, DOBBIAMO TROVARE IL CAPITANO E <Blue:RAMONA>—"
  },
  AvgDialog_19102_Content_24 = {
    Text = "Proprio quello!"
  },
  AvgDialog_19102_Content_25 = {
    Text = "Murphy, dall'inizio alla fine, non ti ho mai detto il nome della mia compagna."
  },
  AvgDialog_19102_Content_26 = {
    Text = "Dove hai imparato il nome \"Ramona\"?"
  },
  AvgDialog_19102_Content_3 = {
    Text = "...Scusa, non posso lasciarti andare."
  },
  AvgDialog_19102_Content_4 = {
    Text = "Murphy abbassò lo sguardo, fissò il pugnale per un istante, e infine ne pulì il liquido viscoso grigio-verde."
  },
  AvgDialog_19102_Content_5 = {
    Text = "Stava per avvertirli... Dannazione, c'è qualcuno che guida i Navigatori su questa nave..."
  },
  AvgDialog_19102_Content_6 = {
    Text = "Andiamo. Non possiamo restare qui a lungo."
  },
  AvgDialog_19102_Content_7 = {
    Text = "La Sala Motori è stata distrutta"
  },
  AvgDialog_19102_Content_8 = {
    Text = "Già... ormai è completamente in rovina."
  },
  AvgDialog_19102_Content_9 = {
    Text = "Murphy sta in piedi vicino al portello, lanciando un'occhiata al caos nella sala motori, le ciglia che tremano inquiete"
  },
  AvgDialog_19103_Content_1 = {
    Text = "Ramona, hai qualche idea su come togliere quella cosa?"
  },
  AvgDialog_19103_Content_2 = {
    Text = "Ramona guarda Murphy, poi te, con un'espressione piena di difficoltà."
  },
  AvgDialog_19103_Content_3 = {
    Text = "Di' quello che vuoi, non essere timida."
  },
  AvgDialog_19103_Content_4 = {
    Text = "I tuoi vasi sanguigni si sono fusi con l'aorta; nemmeno i chirurghi più abili possono garantire il successo di un'operazione del genere."
  },
  AvgDialog_19103_Content_5 = {
    Text = "Attualmente è in uno stato di ibernazione... C'è ancora tempo per trovare un'altra soluzione."
  },
  AvgDialog_19103_Content_6 = {
    Text = "Ibernazione?"
  },
  AvgDialog_19103_Content_7 = {
    Text = "Hai detto che è in ibernazione?"
  },
  AvgDialog_19103_Content_8 = {
    Text = "È solo temporanea."
  },
  AvgDialog_19104_Content_1 = {
    Text = "Murphy batté il piede con forza, chinandosi con riluttanza a esaminare la planimetria della paratia."
  },
  AvgDialog_19104_Content_10 = {
    Text = "Uff, <Small:pensavo che nemmeno tu ci avessi capito qualcosa.>"
  },
  AvgDialog_19104_Content_11 = {Text = "Un modulo?"},
  AvgDialog_19104_Content_12 = {
    Text = [[
<BigShake:No, niente!>
Guarda bene.]]
  },
  AvgDialog_19104_Content_13 = {
    Text = "Agli ordini, agli ordini."
  },
  AvgDialog_19104_Content_14 = {
    Text = "Siamo sotto la scalinata sul lato di prua... Murphy, dove pensi che siano gli altri? Nella cabina di pilotaggio sul ponte di poppa?"
  },
  AvgDialog_19104_Content_15 = {
    Text = "E che ne so! Ma se vuoi raggiungere la cabina di pilotaggio, devi passare dal ponte o dalla Sala Motori."
  },
  AvgDialog_19104_Content_16 = {
    Text = "Ci sono troppi nemici sul ponte; è più sicuro all'interno della cabina. Facciamo una deviazione dalla sala motori...<BigShake:Ugh!>"
  },
  AvgDialog_19104_Content_17 = {
    Text = "<Blue:\"Sala Motori\"> sembra portare con sé una certa forza, poiché una violenta ondata di vertigini colpisce di nuovo il tuo cervello nel momento in cui l'ultima sillaba viene pronunciata."
  },
  AvgDialog_19104_Content_18 = {
    Text = "Un'intensa ondata di nausea ti impedisce di restare in piedi. Sbatti improvvisamente contro la paratia e cominci a vomitare violentemente."
  },
  AvgDialog_19104_Content_19 = {
    Text = "*Cough, cough! ... Ugh...*"
  },
  AvgDialog_19104_Content_2 = {Text = "Hmm..."},
  AvgDialog_19104_Content_20 = {
    Text = "Stai bene?! Perché stai vomitando di nuovo?"
  },
  AvgDialog_19104_Content_3 = {
    Text = "Fammi vedere."
  },
  AvgDialog_19104_Content_4 = {
    Text = "Quando la planimetria appare davanti ai tuoi occhi, una forte sensazione di déjà vu ti travolge."
  },
  AvgDialog_19104_Content_5 = {
    Text = "In <Blue:passato>, nei <Blue:sogni>, in <Blue:un momento imprecisato>, ti sembra di aver vissuto qualcosa di simile."
  },
  AvgDialog_19104_Content_6 = {
    Text = "Accanto a me c'è una ragazza orgogliosa e testarda, anch'essa sulla nave sconosciuta, che esamina le incisioni sulla targhetta metallica."
  },
  AvgDialog_19104_Content_7 = {
    Text = "La sensazione di déjà vu è come un amo invisibile, e tu sei il povero pesce che ha abboccato, trascinato irresistibilmente verso l'altra estremità della palude—"
  },
  AvgDialog_19104_Content_8 = {
    Text = "A cosa stai pensando?"
  },
  AvgDialog_19104_Content_9 = {
    Text = "...Niente, forse sono solo troppo stanco."
  },
  AvgDialog_19105_Content_1 = {
    Text = "La sala motori non è vivace come immaginavi: niente operai muscolosi, niente caldaie ardenti."
  },
  AvgDialog_19105_Content_10 = {
    Text = "Murphy fissò il pugnale per un istante, poi improvvisamente si arrampicò sul cumulo di macerie con mani e piedi, allungandosi per afferrarlo—"
  },
  AvgDialog_19105_Content_11 = {
    Text = "Murphy, attento!"
  },
  AvgDialog_19105_Content_12 = {Text = "Argh!"},
  AvgDialog_19105_Content_2 = {
    Text = "Solo le indimenticabili scintille volano ovunque."
  },
  AvgDialog_19105_Content_3 = {
    Text = "Come è potuto succedere qui...?"
  },
  AvgDialog_19105_Content_4 = {
    Text = "<Shake:Cough cough>...L'odore è insopportabile."
  },
  AvgDialog_19105_Content_5 = {
    Text = "Un'enorme breccia si era aperta nella paratia, e il vento gelido si riversava nella cabina. Murphy si pizzicò il lobo dell'orecchio congelato, scavalcò le fiamme e si addentrò tra i rottami."
  },
  AvgDialog_19105_Content_6 = {
    Text = "Hmm? Sembra che ci sia qualcosa..."
  },
  AvgDialog_19105_Content_7 = {
    Text = "Tra le macerie, qualcosa luccica in modo vistoso."
  },
  AvgDialog_19105_Content_8 = {
    Text = "—È un pugnale, che giace silenzioso tra le braci spente. Nonostante la polvere che ne ricopre la lama, la sua affilatura resta evidente."
  },
  AvgDialog_19105_Content_9 = {Text = "..."},
  AvgDialog_19106_Content_1 = {
    Text = "Qualcuno sta arrivando."
  },
  AvgDialog_19106_Content_2 = {
    Text = "...Cancello principale, Navigatore."
  },
  AvgDialog_19107_Content_1 = {
    Text = "Questo molo è enorme."
  },
  AvgDialog_19107_Content_10 = {
    Text = "Concordo con la tua opinione su Herbert, ma non dimenticare, anche la Dissoluzione può causare mutazioni di gruppo simili"
  },
  AvgDialog_19107_Content_11 = {
    Text = "Spero che non sia l'influenza del <Yellow:Cataclisma>..."
  },
  AvgDialog_19107_Content_2 = {
    Text = "Non mollate—ci stiamo avvicinando alla porta nord."
  },
  AvgDialog_19107_Content_3 = {
    Text = [[
Dopo le battaglie lungo il cammino, pochi nemici restavano sul vostro percorso.
Solo una manciata di pesci piccoli si frapponeva tra voi e la fuga.]]
  },
  AvgDialog_19107_Content_4 = {
    Text = "Questi nemici... sono collegati a ciò che stiamo indagando?"
  },
  AvgDialog_19107_Content_5 = {
    Text = "Non si può escludere questa possibilità. Secondo le informazioni raccolte dall'equipaggiamento di spionaggio di Doll presso Herbert, la Chiesa Portaluce ha molte organizzazioni affiliate, tra cui Gli Scultori."
  },
  AvgDialog_19107_Content_6 = {
    Text = "Ma i membri della Chiesa Portaluce che abbiamo incontrato a Lai Town erano molto più raffinati."
  },
  AvgDialog_19107_Content_7 = {
    Text = "Ad assediarvi c'erano letteralmente dei \"pesci piccoli\" — umanoidi ricurvi, teste di pesce che spuntavano da cappucci laceri."
  },
  AvgDialog_19107_Content_8 = {
    Text = "Ogni assalto portava con sé il fetore della vita in decomposizione."
  },
  AvgDialog_19107_Content_9 = {
    Text = "Non si può nemmeno escludere il coinvolgimento dell'Associazione degli Scultori. Herbert è un miserabile che gioca con la Vita in nome dell'immortalità."
  },
  AvgDialog_19108_Content_1 = {
    Text = [[
Giusto, giusto. Non hai appena menzionato un leader maschio?
Quell'individuo ha detto qualcosa... qualsiasi cosa?]]
  },
  AvgDialog_19108_Content_10 = {Text = "..."},
  AvgDialog_19108_Content_11 = {
    Text = "A quali enigmi si riferisce?"
  },
  AvgDialog_19108_Content_12 = {
    Text = "Golia, quel tipo..."
  },
  AvgDialog_19108_Content_13 = {Text = "Murphy."},
  AvgDialog_19108_Content_14 = {
    Text = "Che... che stai facendo? Perché mi guardi così all'improvviso?"
  },
  AvgDialog_19108_Content_15 = {
    Text = "Conosci bene i <Blue:Navigatori>, sai identificare le loro guardie d'élite, e conosci persino il loro leader.\nDa quando ci siamo incontrati, non ho menzionato <Blue:Golia> nemmeno una volta."
  },
  AvgDialog_19108_Content_16 = {
    Text = "Eri un membro dei Navigatori, forse con un rango elevato... o forse sono qui per te."
  },
  AvgDialog_19108_Content_17 = {
    Text = "Quindi tu sei la <Blue:Santa Fanciulla>, la <Blue:Principessa Marionetta> e la <Blue:Chiave del Sacrificio per i Navigatori> di cui parlava Golia, giusto?"
  },
  AvgDialog_19108_Content_18 = {
    Text = "Non lo sono!"
  },
  AvgDialog_19108_Content_19 = {
    Text = "Come spieghi la tua familiarità con Golia e il fatto che eviti il leader?"
  },
  AvgDialog_19108_Content_2 = {
    Text = "Ramona rivolse a Murphy uno sguardo profondo e scrutatore — con la sua espressione inconfondibile."
  },
  AvgDialog_19108_Content_20 = {
    Text = "Sono solo... una serva... una serva qualunque. Ci sono innumerevoli ragazze come me nella base dell'Ordine!"
  },
  AvgDialog_19108_Content_21 = {
    Text = "Le sembianze umane sono rare tra i Navigatori. Altrimenti, con la loro abilità in combattimento, non avrebbero bisogno di allearsi con la Chiesa dei Portatori di Luce."
  },
  AvgDialog_19108_Content_22 = {
    Text = "Se fossi solo un'irrilevante Ancella umana, perché questa caccia spietata per trovarti?"
  },
  AvgDialog_19108_Content_23 = {
    Text = "Tutto questo... è solo..."
  },
  AvgDialog_19108_Content_24 = {
    Text = "Pensi che sia tutto una coincidenza? Io non credo."
  },
  AvgDialog_19108_Content_25 = {
    Text = "Anche il capitano che ti ha portata a bordo è stato etichettato come \"traditore\". Mentre i Navigatori ti danno la caccia, non hanno risparmiato nemmeno loro."
  },
  AvgDialog_19108_Content_26 = {
    Text = "Avete incontrato il capitano e Celeste? Sono ancora al sicuro?"
  },
  AvgDialog_19108_Content_27 = {
    Text = [[
Sono caduti nelle mani della leader femminile, Miryam.
Il risultato del "Tradimento" da parte dei Navigatori... credo che tu lo sappia meglio di me.]]
  },
  AvgDialog_19108_Content_28 = {
    Text = "<Small:No, non è possibile... Lei conta ancora sul capitano per servirla.>"
  },
  AvgDialog_19108_Content_29 = {
    Text = "Quando si tratta di trasportare merci, ci sono più che sufficienti navi che possono viaggiare tra il continente e il polo."
  },
  AvgDialog_19108_Content_3 = {
    Text = "Va bene, vi riferirò la sua conversazione con me."
  },
  AvgDialog_19108_Content_30 = {
    Text = "L'espressione di Ramona era calma e risoluta. Incalzava senza sosta, usando persino l'incerta sicurezza dei due capitani come arma psicologica, aumentando enormemente la pressione psicologica."
  },
  AvgDialog_19108_Content_31 = {Text = "Ramona..."},
  AvgDialog_19108_Content_32 = {
    Text = "Stai quasi iniziando a provare pena per Murphy — proprio in quel momento, Ramona ti fa l'occhiolino."
  },
  AvgDialog_19108_Content_33 = {
    Text = "Anni di intesa reciproca ti permettono di cogliere istantaneamente il suo significato."
  },
  AvgDialog_19108_Content_34 = {
    Text = "Murphy, abbiamo bisogno di sapere cosa è successo."
  },
  AvgDialog_19108_Content_35 = {
    Text = "Solo allora avremo una possibilità di sopravvivere. Solo allora potremo aiutarti."
  },
  AvgDialog_19108_Content_36 = {Text = "..."},
  AvgDialog_19108_Content_37 = {Text = "Va bene..."},
  AvgDialog_19108_Content_4 = {
    Text = "Chiesa dei Portaluce? Hah, non è un segreto."
  },
  AvgDialog_19108_Content_5 = {
    Text = "La Chiesa Portaluce aiuta a raccogliere i <Yellow:materiali> necessari per i riti. In cambio, i Navigatori svolgono occasionalmente qualche lavoro losco per loro..."
  },
  AvgDialog_19108_Content_6 = {
    Text = "L'aspetto dei Navigatori rende loro difficile camminare tra la gente, e desiderano il nostro potere... Solo uno sfruttamento reciproco tra creature anomale, che si stringono insieme per scaldarsi."
  },
  AvgDialog_19108_Content_7 = {
    Text = "Allora cos'è esattamente il \"rituale\" di cui parli..."
  },
  AvgDialog_19108_Content_8 = {
    Text = "Ah! Questa è la seconda domanda.\nLascia che sia chiaro, signorina — non ho alcun obbligo di riferire a te."
  },
  AvgDialog_19108_Content_9 = {
    Text = "Corri, corri più veloce.\nUna volta che la luna sorgerà, non avrai più possibilità di sopravvivere."
  },
  AvgDialog_19109_Content_1 = {
    Text = "Anche se sono navigatori, questi tizi sono più tosti di quelli di prima. \nMurphy, qualche idea?"
  },
  AvgDialog_19109_Content_10 = {
    Text = "Occupiamoci prima di questi tizi."
  },
  AvgDialog_19109_Content_2 = {
    Text = "Sono le guardie personali di <Blue:quella donna>. Anche tra i Navigatori infestati dai mostri, sono l'élite."
  },
  AvgDialog_19109_Content_3 = {
    Text = "\"Quella donna\"... Intendi la leader dei Navigatori?"
  },
  AvgDialog_19109_Content_4 = {
    Text = "Miryam, il suo nome è Miryam."
  },
  AvgDialog_19109_Content_5 = {
    Text = "La guardia personale del capo... Non c'è da stupirsi che siano più tosti degli altri."
  },
  AvgDialog_19109_Content_6 = {
    Text = "Tulu era con me fino a poco fa, ma dopo aver incontrato Miryam, è sparito da qualche parte."
  },
  AvgDialog_19109_Content_7 = {
    Text = "Con la sua forza, occuparsi di queste cosiddette \"guardie personali\" è un gioco da ragazzi."
  },
  AvgDialog_19109_Content_8 = {
    Text = "Tulu?! Cosa ci fa qui?"
  },
  AvgDialog_19109_Content_9 = {
    Text = "L'espressione di Ramona si indurì mentre sollevava nuovamente la spada."
  },
  AvgDialog_19110_Content_1 = {
    Text = "Studentessa, perché hai smesso di avanzare?"
  },
  AvgDialog_19110_Content_10 = {
    Text = "Sì, la sanità mentale e la vita di chi stabilisce il Legame si deterioreranno rapidamente."
  },
  AvgDialog_19110_Content_11 = {
    Text = "Per preservare Celeste, ho stretto un <Blue:patto> con la leader dei Navigatori."
  },
  AvgDialog_19110_Content_12 = {
    Text = "Lei mi forniva regolarmente medicine per tenermi a malapena in vita. In cambio, trasportavamo costantemente merci per i Navigatori."
  },
  AvgDialog_19110_Content_13 = {
    Text = "Questo implica che lei è un loro collaboratore... se è così, perché viene attaccato dai Navigatori?"
  },
  AvgDialog_19110_Content_14 = {
    Text = "Perché... ho <Blue:tradito> quella persona."
  },
  AvgDialog_19110_Content_2 = {
    Text = "Capitano, ho una domanda da farle."
  },
  AvgDialog_19110_Content_3 = {
    Text = "Lei ha qualche legame o conflitto irrisolto con i Navigatori, vero?"
  },
  AvgDialog_19110_Content_4 = {
    Text = "I Navigatori hanno un aspetto simile, eppure lei riesce a distinguere le differenze tra loro... Tuttavia, è comunque soggetto ai loro attacchi."
  },
  AvgDialog_19110_Content_5 = {
    Text = "Non essere così nervosa, sono un essere umano autentico."
  },
  AvgDialog_19110_Content_6 = {
    Text = [[
Ma a differenza dei vostri migliori studenti di Mythag, io sono solo una persona ordinaria.
Non ho alcun talento per il Legame con i Risvegliatori e non riesco a vedere la <Yellow:Dissoluzione>.]]
  },
  AvgDialog_19110_Content_7 = {
    Text = "Durante la rinascita del Risvegliatore, la sua coscienza viene inevitabilmente contaminata da <Yellow:entità sconosciute>, il che porta alla perdita di controllo..."
  },
  AvgDialog_19110_Content_8 = {
    Text = "Dato che sei una studentessa dell'Università di Mythag, dovresti sapere come sopprimere una situazione fuori controllo, giusto?"
  },
  AvgDialog_19110_Content_9 = {
    Text = "<Yellow:Legame Spirituale>... Ma se una persona ordinaria senza talento tentasse il Legame..."
  },
  AvgDialog_19111_Content_1 = {
    Text = "Signorina Ramona, Custode! Qui!"
  },
  AvgDialog_19111_Content_10 = {
    Text = "G-Giusto. Fate attenzione!"
  },
  AvgDialog_19111_Content_11 = {
    Text = "Il conducente si arrampicò dentro; il rombo del motore attirò gli occhi del nemico."
  },
  AvgDialog_19111_Content_12 = {
    Text = "Ehi! Occhi-di-pesce—qui!"
  },
  AvgDialog_19111_Content_2 = {
    Text = "È il conducente!"
  },
  AvgDialog_19111_Content_3 = {
    Text = "Più avanti, il familiare uomo di mezza età scuoteva ansiosamente il cancello incatenato, con aria turbata."
  },
  AvgDialog_19111_Content_4 = {
    Text = "Signorina Ramona, non riesco ad aprire questa serratura."
  },
  AvgDialog_19111_Content_5 = {
    Text = "Non preoccuparti, posso tagliare la catena direttamente. Per favore, fai un passo indietro."
  },
  AvgDialog_19111_Content_6 = {
    Text = "Solo 10 metri ci separano dalla libertà."
  },
  AvgDialog_19111_Content_7 = {
    Text = "Il fruscio si fa più forte mentre creature emergono dalle ombre una dopo l'altra, rendendo l'aria ancora più umida e pesante."
  },
  AvgDialog_19111_Content_8 = {
    Text = "Così tanti?! Ci stanno bloccando la strada!"
  },
  AvgDialog_19111_Content_9 = {
    Text = "Il conducente non è un combattente—fuori di qui, subito!"
  },
  AvgDialog_19112_Content_1 = {
    Text = "Questi tizi sono l'élite tra i Navigatori.\nFai attenzione, non farti male."
  },
  AvgDialog_19113_Content_1 = {
    Text = "Nell'istante in cui fai un passo avanti, l'aria si fa pesante e umida."
  },
  AvgDialog_19113_Content_2 = {
    Text = "Respiro e battito cardiaco vengono fortemente repressi, causando un inspiegabile senso di panico."
  },
  AvgDialog_19113_Content_3 = {Text = "È lei!"},
  AvgDialog_19114_Content_1 = {
    Text = [[
22:10  
Sonaniel  
Stiva 3]]
  },
  AvgDialog_19114_Content_2 = {
    Text = "Sembra che abbiano smesso di inseguirci."
  },
  AvgDialog_19114_Content_3 = {
    Text = "Uff... Finalmente posso tirare il fiato."
  },
  AvgDialog_19114_Content_4 = {
    Text = "Non esiste un posto completamente sicuro su questa nave. Restate all'erta."
  },
  AvgDialog_19115_Content_1 = {
    Text = "Gur... gurgll..."
  },
  AvgDialog_19115_Content_10 = {
    Text = "\"Le Stelle si levano nelle loro posizioni predestinate\" — conosci le condizioni del Rito."
  },
  AvgDialog_19115_Content_11 = {
    Text = "\"Tutto per tutto, lotta disperata\" — Dimostra che conosci la situazione del nemico."
  },
  AvgDialog_19115_Content_12 = {
    Text = "Il Rituale di Discesa — cosa sta succedendo? E chi sono questi uomini-pesce?"
  },
  AvgDialog_19115_Content_13 = {
    Text = "Seguendo l'esempio di Ramona, indichi una per una le informazioni rivelate dalle parole e dalle azioni di Tulu."
  },
  AvgDialog_19115_Content_14 = {
    Text = "...Capisco."
  },
  AvgDialog_19115_Content_15 = {
    Text = [[
Una mia negligenza, non aver notato il tuo malessere.
Per un umano essere intrappolato in tutto questo... ha lasciato il segno.]]
  },
  AvgDialog_19115_Content_16 = {
    Text = "\"Un simile evento?\""
  },
  AvgDialog_19115_Content_17 = {
    Text = "Qualcuno sta arrivando."
  },
  AvgDialog_19115_Content_18 = {
    Text = "Non appena Tulu finì di parlare, un leggero tremore giunse da sotto i tuoi piedi. Una figura si lanciò verso di te dall'altra estremità del ponte."
  },
  AvgDialog_19115_Content_19 = {
    Text = "Wah—aiuto—!"
  },
  AvgDialog_19115_Content_2 = {
    Text = [[
Questi corpi umanoidi, con caratteristiche di creature acquatiche, emettevano strani lamenti.
I suoni erano disordinati e stridenti, eppure in qualche modo ne comprendevi il significato.]]
  },
  AvgDialog_19115_Content_20 = {
    Text = "Ci stanno raggiungendo!!!"
  },
  AvgDialog_19115_Content_21 = {Text = "Attento!"},
  AvgDialog_19115_Content_22 = {
    Text = "La ragazza, ansimando pesantemente, corse al tuo fianco. Dietro di lei, attraverso il ponte, c'erano senza dubbio altri nemici."
  },
  AvgDialog_19115_Content_3 = {
    Text = "Stanno dicendo... \"ridatecela\"?"
  },
  AvgDialog_19115_Content_4 = {
    Text = "Cosa dovrei restituire? Non ho nulla tra le mani—"
  },
  AvgDialog_19115_Content_5 = {
    Text = "Anche la spilla è svanita senza lasciare traccia."
  },
  AvgDialog_19115_Content_6 = {
    Text = "È una lotta disperata, un'ultima scommessa. Non dare retta alle loro parole."
  },
  AvgDialog_19115_Content_7 = {
    Text = "Sotto il comando di Tulu, il tentacolo spazzò l'ultimo nemico fuori bordo. Lo schizzo segnò la fine temporanea della battaglia."
  },
  AvgDialog_19115_Content_8 = {
    Text = "Bene, nessuno ci disturba più. Puoi spiegare chiaramente?"
  },
  AvgDialog_19115_Content_9 = {
    Text = "Cosa esattamente va spiegato?"
  },
  AvgDialog_19116_Content_1 = {
    Text = "Elisir Speciale"
  },
  AvgDialog_19116_Content_10 = {
    Text = "Il dolore pulsante all'alluce ti riporta alla realtà. Vedendo la ragazza accanto a te e il cerchio che si restringe, ti prepari alla battaglia."
  },
  AvgDialog_19116_Content_11 = {
    Text = "Tulu, preparati alla battaglia!"
  },
  AvgDialog_19116_Content_12 = {Text = "..."},
  AvgDialog_19116_Content_13 = {Text = "...Tulu?"},
  AvgDialog_19116_Content_14 = {
    Text = "In questo momento cruciale, è scomparso all'improvviso... Beh, sembra che dovremo cavarcela da soli."
  },
  AvgDialog_19116_Content_2 = {
    Text = "Huff... Huff..."
  },
  AvgDialog_19116_Content_3 = {
    Text = "Grazie al cielo ti ho trovato..."
  },
  AvgDialog_19116_Content_4 = {
    Text = "La ragazza corse al tuo fianco, aggrappandosi all'orlo del tuo mantello come fosse un'ancora di salvezza, parlando a fatica tra i respiri."
  },
  AvgDialog_19116_Content_5 = {
    Text = "I nemici ti lasciano poco spazio per respirare, alzando le armi e caricandoti con un ruggito."
  },
  AvgDialog_19116_Content_6 = {
    Text = "Madre@2—!@1Madre!@2!"
  },
  AvgDialog_19116_Content_7 = {
    Text = "I ruggiti disordinati si fanno più chiari nelle tue orecchie.\nAncora un po', e avresti afferrato ciò che volevano —"
  },
  AvgDialog_19116_Content_8 = {
    Text = "In quell'istante di distrazione, la ragazza ti pesta con forza lo stivale."
  },
  AvgDialog_19116_Content_9 = {
    Text = "Te ne stai lì impalato? Fai qualcosa!"
  },
  AvgDialog_19117_Content_1 = {
    Text = "I due si diressero verso la sala motori. Quando furono abbastanza vicini, un frastuono di rumori giunse da dietro il portello."
  },
  AvgDialog_19117_Content_2 = {
    Text = "È in corso una battaglia!"
  },
  AvgDialog_19117_Content_3 = {
    Text = "Non essere avventato."
  },
  AvgDialog_19118_Content_1 = {
    Text = "Prima che le parole svanissero, il portello fu sfondato dall'interno e diversi Navigatori furono scaraventati fuori dalla sala motori tra fasci di luce."
  },
  AvgDialog_19118_Content_10 = {
    Text = "Sono circondati dai Navigatori. Dobbiamo aiutarli a fuggire.\nLa sala motori ha una porta sul retro. Possiamo aggirare da lì."
  },
  AvgDialog_19118_Content_2 = {
    Text = "Nell'angolo più interno della sala motori, anche i due assediati rivolsero lo sguardo verso la porta — la figura bianca tra loro incrociò lo sguardo con Ramona."
  },
  AvgDialog_19118_Content_3 = {
    Text = [[
Pura, nobile, trascendente, fragile; innumerevoli aggettivi balenarono nella mente di Ramona.
Poi, una consapevolezza incredibile sorse dentro di lei.]]
  },
  AvgDialog_19118_Content_4 = {
    Text = "Anche lei è..."
  },
  AvgDialog_19118_Content_5 = {Text = "...Umano."},
  AvgDialog_19118_Content_6 = {
    Text = "Proteggere..."
  },
  AvgDialog_19118_Content_7 = {
    Text = "La luce fluente bloccò silenziosamente Ramona, tenendola fuori dalla sala motori."
  },
  AvgDialog_19118_Content_8 = {
    Text = "Questa luce... È la stessa dello schermo luminoso che forma il confine del Dominio!"
  },
  AvgDialog_19118_Content_9 = {
    Text = "A quanto pare è lei la padrona di questo Dominio."
  },
  AvgDialog_19119_Content_10 = {
    Text = "Scalciò via alcune assi, rivelando una botola sul ponte."
  },
  AvgDialog_19119_Content_2 = {Text = "Ugh!"},
  AvgDialog_19119_Content_3 = {
    Text = "Hanno rinforzi. Non riesco a resistere ancora."
  },
  AvgDialog_19119_Content_4 = {
    Text = "Sottocoperta! Non dovrebbero esserci tanti <Blue:Navigatori> radunati là sotto."
  },
  AvgDialog_19119_Content_5 = {
    Text = "Hai scrutato il ponte e notato un portello che conduceva verso il basso."
  },
  AvgDialog_19119_Content_6 = {
    Text = "A parte il fatto che la porta è chiusa a chiave — non riusciremmo nemmeno a superarli per raggiungere la porta."
  },
  AvgDialog_19119_Content_7 = {
    Text = "I nemici che inseguono dall'altra estremità del ponte mostrano zanne e artigli, formando una barriera invalicabile di acciaio e carne."
  },
  AvgDialog_19119_Content_8 = {
    Text = "Non andare da quella parte."
  },
  AvgDialog_19119_Content_9 = {
    Text = "La ragazza fece qualche passo indietro da sola, e tu ti muovesti rapidamente per proteggerla mentre la seguivi."
  },
  AvgDialog_19120_Content_1 = {
    Text = "Cosa ti è successo mentre eravamo separati? Hai addirittura incontrato il capo nemico."
  },
  AvgDialog_19120_Content_10 = {
    Text = "Colui Che Solca Tutti i Mari?"
  },
  AvgDialog_19120_Content_11 = {
    Text = "Questo titolo è davvero..."
  },
  AvgDialog_19120_Content_12 = {
    Text = [[
Ho fatto squadra con Tulu, e avevamo solo un leggero vantaggio contro di lui.
Forse possiede davvero una tale forza.]]
  },
  AvgDialog_19120_Content_13 = {
    Text = "A proposito, perché Tulu è sulla nave?\nI Risvegliatori non collegati sono inclini a deliri una volta che lasciano il campus."
  },
  AvgDialog_19120_Content_14 = {
    Text = "Da soli, temo che non saremo in grado di contenere Tulu fuori controllo."
  },
  AvgDialog_19120_Content_15 = {
    Text = "Sembra che Tulu sia molto stabile per ora, ma non è chiaro quanto durerà."
  },
  AvgDialog_19120_Content_16 = {
    Text = "Sembra che quel Tulu sia piuttosto tosto, eh? Allora ignoratelo!"
  },
  AvgDialog_19120_Content_17 = {
    Text = "<BigShake:Quei tizi stanno per raggiungerci!>"
  },
  AvgDialog_19120_Content_2 = {
    Text = "È una lunga storia che coinvolge Tulu, nemici misteriosi, capitani umani e Risvegliatori..."
  },
  AvgDialog_19120_Content_3 = {
    Text = "A proposito, il leader dei Navigatori a bordo non è solo Miryam."
  },
  AvgDialog_19120_Content_4 = {Text = "...!"},
  AvgDialog_19120_Content_5 = {
    Text = "Mentre agivo con Tulu, abbiamo brevemente combattuto un Risvegliatore maschio che si faceva chiamare <Blue:Conquistatore dei Mari>."
  },
  AvgDialog_19120_Content_6 = {
    Text = "Il suo atteggiamento verso di noi... specialmente verso Tulu, è piuttosto sconcertante.\nSebbene appartenga alla fazione dei Navigatori, sembra indifferente al successo del <Blue:Rituale>."
  },
  AvgDialog_19120_Content_7 = {Text = "Rituale?"},
  AvgDialog_19120_Content_8 = {
    Text = "È questo lo scopo dei Navigatori? Condurre rituali pagani sulla nave?"
  },
  AvgDialog_19120_Content_9 = {
    Text = "È ancora ignoto, ma credo che Tulu possa conoscere l'intera storia dietro tutto questo."
  },
  AvgDialog_19121_Content_1 = {
    Text = "Imboscata da ogni lato"
  },
  AvgDialog_19121_Content_10 = {
    Text = "L'Investigatore di Drapur dovrebbe arrivare al Molo 3 tra mezz'ora."
  },
  AvgDialog_19121_Content_11 = {
    Text = "Trenta è troppo. La strada sud brulica di nemici — sfonderemo a nord."
  },
  AvgDialog_19121_Content_12 = {
    Text = "Conducente avvisato per il recupero all'uscita nord del Terzo Molo."
  },
  AvgDialog_19121_Content_13 = {
    Text = "Nemico sconosciuto? Si tratta della <Yellow:Chiesa del Portatore di Luce> e dei loro associati?"
  },
  AvgDialog_19121_Content_14 = {
    Text = "Registrare nuove informazioni sul nemico?"
  },
  AvgDialog_19121_Content_15 = {
    Text = "Per favore, Erica—non ora."
  },
  AvgDialog_19121_Content_16 = {
    Text = "Umanoidi con tratti acquatici non documentati; rapporto in arrivo al ritorno."
  },
  AvgDialog_19121_Content_17 = {
    Text = "Custode, proteggiti e preparati a sfondare."
  },
  AvgDialog_19121_Content_2 = {
    Text = "21:00\nCittà portuale - Brillport\nTerzo molo"
  },
  AvgDialog_19121_Content_3 = {
    Text = "<Shake:—Attento alle spalle!>"
  },
  AvgDialog_19121_Content_4 = {
    Text = [[
Rilevate onde ad alta frequenza non in stato di allerta; collegamento comunicazioni automatico.
Ancora una volta, buonasera, Custode, Ramona.]]
  },
  AvgDialog_19121_Content_5 = {
    Text = "Sembra che qualcuno sia terrorizzato a morte."
  },
  AvgDialog_19121_Content_6 = {
    Text = "Si prega di astenersi da interferenze verbali non necessarie con il personale operativo sul campo."
  },
  AvgDialog_19121_Content_7 = {
    Text = [[
Va bene, va bene.
Allora, serve una mano?]]
  },
  AvgDialog_19121_Content_8 = {
    Text = "Ci servono rinforzi!"
  },
  AvgDialog_19121_Content_9 = {
    Text = "Siamo al <Blue:Terzo Molo> della <Blue:città di Bridgeport>, impegnati contro ostili sconosciuti."
  },
  AvgDialog_19122_Content_1 = {
    Text = "I loro soli lineamenti grotteschi sembravano una bestemmia contro l'evoluzione."
  },
  AvgDialog_19122_Content_2 = {
    Text = "Si accalcano, le loro armi fredde si scontrano con un suono penetrante. Nel mezzo del caos, sembrano accerchiare qualcosa..."
  },
  AvgDialog_19123_Content_1 = {
    Text = "Senza Scampo"
  },
  AvgDialog_19123_Content_10 = {
    Text = "Lancia un attacco alla banchina, intrappolando i nemici sotto la passerella, i loro occhi vitrei da pesce fissi su di te."
  },
  AvgDialog_19123_Content_11 = {
    Text = "Non sono riusciti a tenere il passo con la passerella..."
  },
  AvgDialog_19123_Content_12 = {
    Text = "Ramona abbassò la voce fino a un sussurro."
  },
  AvgDialog_19123_Content_13 = {
    Text = "Siamo stati usati come cavie. Una volta messo piede sul ponte, probabilmente perderemo il nostro valore per loro."
  },
  AvgDialog_19123_Content_14 = {
    Text = "Quindi... ho un'idea."
  },
  AvgDialog_19123_Content_15 = {
    Text = "Hai posato il piede sull'ultimo gradino della passerella."
  },
  AvgDialog_19123_Content_16 = {
    Text = "Ramona, qualcosa non va! Aspetta un momento!"
  },
  AvgDialog_19123_Content_17 = {
    Text = "La passerella trema, e i nemici non ti danno tregua. Smettono di osservare e iniziano ad arrampicarsi usando mani e piedi."
  },
  AvgDialog_19123_Content_18 = {Text = "Clang—!"},
  AvgDialog_19123_Content_19 = {
    Text = "Ramona calò la spada con tutta la sua forza, frantumando il fermo di sicurezza. La passerella precipitò nel vuoto, ma nessun tonfo riecheggiò dal basso."
  },
  AvgDialog_19123_Content_2 = {
    Text = "21:10\nCittà Portuale - Brillport\nTerzo Molo"
  },
  AvgDialog_19123_Content_20 = {
    Text = "Almeno da questo lato non possono salire a bordo."
  },
  AvgDialog_19123_Content_21 = {
    Text = "Aspetta, questo..."
  },
  AvgDialog_19123_Content_22 = {
    Text = "Come uccelli baciati dal cielo, i tuoi occhi vengono accarezzati dalla brezza tiepida, e il mondo davanti a te si capovolge."
  },
  AvgDialog_19123_Content_23 = {
    Text = "L'enorme luna piena svanì dal cielo. Aloni simili ad aurore si attorcigliarono attorno allo scafo della nave, proiettando tonalità sinistre sul ponte."
  },
  AvgDialog_19123_Content_24 = {
    Text = "Visioni inondano le vostre menti, e ci vuole un po' prima di riacquistare la capacità di parlare."
  },
  AvgDialog_19123_Content_25 = {
    Text = "Interessante..."
  },
  AvgDialog_19123_Content_26 = {
    Text = "Ramona, tu cosa ne pensi?"
  },
  AvgDialog_19123_Content_27 = {
    Text = "Interessante, molto interessante. La passerella è caduta senza emettere alcun suono — il che suggerisce che potremmo trovarci in uno spazio isolato."
  },
  AvgDialog_19123_Content_28 = {
    Text = "Questo è un <Yellow:Dominio> visibile!"
  },
  AvgDialog_19123_Content_29 = {
    Text = "La nebbia attorno alla scuola funziona con la <Yellow:Tecnologia d'Argento>. Chissà quale forza alimenta questa nave?"
  },
  AvgDialog_19123_Content_3 = {
    Text = "L'odore acre dell'acciaio arrugginito ti assale le narici a ogni passo, la passerella geme sotto i tuoi piedi."
  },
  AvgDialog_19123_Content_30 = {
    Text = "Potrebbe essere un Risvegliatore?"
  },
  AvgDialog_19123_Content_31 = {
    Text = "Nessun documento simile nell'archivio, ma in teoria un Risvegliato potrebbe creare uno spazio isolato — vuoi i dettagli?"
  },
  AvgDialog_19123_Content_32 = {
    Text = "Risparmiami..."
  },
  AvgDialog_19123_Content_33 = {
    Text = "Dai, cerca di capire la situazione!"
  },
  AvgDialog_19123_Content_34 = {
    Text = "Scusa, scusa. Perdona la mia curiosità."
  },
  AvgDialog_19123_Content_35 = {
    Text = "Doll, mi senti?"
  },
  AvgDialog_19123_Content_36 = {
    Text = "Ramona tocca la sua spilla, e un bagliore scivola sulla superficie del comunicatore."
  },
  AvgDialog_19123_Content_37 = {Text = "Hmm...?"},
  AvgDialog_19123_Content_38 = {
    Text = "Ramona si sporse e sfiorò il tuo comunicatore.\nConcentrasti la mente come al solito, ma non accadde nulla."
  },
  AvgDialog_19123_Content_39 = {
    Text = "La tua energia mentale si dissipò come lacrime nell'oceano, dissolvendosi nel silenzio."
  },
  AvgDialog_19123_Content_4 = {
    Text = "Nonostante la mancanza di manutenzione e riparazioni, lo scafo in sé è relativamente intatto, seppur invecchiato."
  },
  AvgDialog_19123_Content_40 = {
    Text = "Anche il mio comunicatore ha perso la connessione."
  },
  AvgDialog_19123_Content_41 = {
    Text = "Il comunicatore sembra intatto, ma non riesce a inviare messaggi."
  },
  AvgDialog_19123_Content_42 = {
    Text = "<Small:Perché c'è sempre qualcosa che blocca le comunicazioni? Anche l'ultima volta al Museo delle Cere...>"
  },
  AvgDialog_19123_Content_43 = {
    Text = "La tecnologia generata dall'Argento non è onnipotente. Inoltre, la nostra ricerca sull'Argento stesso è ancora agli albori."
  },
  AvgDialog_19123_Content_44 = {
    Text = "...Altrimenti, dovremmo sbarcare?"
  },
  AvgDialog_19123_Content_45 = {
    Text = "Dai un'occhiata in giro per il ponte. Potresti trovare un altro modo per sbarcare."
  },
  AvgDialog_19123_Content_46 = {
    Text = "Fai attenzione a ciò che ti circonda, e prega che questa nave non salpi."
  },
  AvgDialog_19123_Content_47 = {
    Text = "<Big:Woo—>"
  },
  AvgDialog_19123_Content_48 = {
    Text = "Come un'allodola che risponde al trillo di un cantante d'opera, un lungo squillo di corno rispose alla preghiera di Ramona."
  },
  AvgDialog_19123_Content_49 = {Text = "..."},
  AvgDialog_19123_Content_5 = {
    Text = "Non ci sono segni evidenti di erosione da acqua marina, e non ci sono denti di cane o ostriche sotto la linea di galleggiamento..."
  },
  AvgDialog_19123_Content_50 = {Text = "..."},
  AvgDialog_19123_Content_51 = {
    Text = "So cosa stai pensando, ma per favore... non ora."
  },
  AvgDialog_19123_Content_52 = {
    Text = "Non possiamo salpare con la Sona-Nyl. Troppe anomalie su questa nave."
  },
  AvgDialog_19123_Content_53 = {
    Text = "Controlla l'altra estremità del ponte. Le navi grandi dovrebbero essere tutte equipaggiate con scialuppe di salvataggio. Forse possiamo calarne una ed evacuare via mare."
  },
  AvgDialog_19123_Content_54 = {
    Text = "Aspetta... sento qualcosa."
  },
  AvgDialog_19123_Content_56 = {
    Text = "Volti simili a pesci emersero sul ponte. I responsabili che vi avevano inseguito a bordo si fecero più vicini."
  },
  AvgDialog_19123_Content_6 = {
    Text = "Trovato qualcosa?"
  },
  AvgDialog_19123_Content_7 = {
    Text = "La Sona-Nyl non corrisponde al profilo di una nave fantasma affondata. Contraddice i registri che la danno come inabissata durante una tempesta."
  },
  AvgDialog_19123_Content_8 = {
    Text = "Se ne avrò l'occasione, vorrei indagare a fondo sulle origini di questa nave..."
  },
  AvgDialog_19123_Content_9 = {
    Text = "Ma chiaramente questo non è il momento adatto."
  },
  AvgDialog_19124_Content_1 = {
    Text = "Ah... Perché... Perché!"
  },
  AvgDialog_19124_Content_2 = {
    Text = "Miryam non sembra stare bene."
  },
  AvgDialog_19124_Content_3 = {
    Text = "Non è l'occasione perfetta? Sbrigati e salva <Yellow:%player%> adesso."
  },
  AvgDialog_19125_Content_1 = {
    Text = "Mentre la mente di Miryam vacillava, la coesione dei Navigatori veniva meno, e il caos si insinuava tra le loro fila."
  },
  AvgDialog_19125_Content_2 = {
    Text = "La coda del serpente sferzò le pareti della cabina, creando un ronzio risonante nell'acciaio."
  },
  AvgDialog_19125_Content_3 = {
    Text = "La fuliggine accumulata da tempo si solleva, cadendo come una soffice neve nera nella sala motori."
  },
  AvgDialog_19126_Content_1 = {
    Text = "Inseguendo le Stelle"
  },
  AvgDialog_19126_Content_10 = {
    Text = [[
Qualunque cosa tu creda sia successa, la decisione l'ho presa io. Io sono il padrone di questa nave.
Celeste non ha quasi alcuna autocoscienza. Come potrebbe mai cambiarmi?]]
  },
  AvgDialog_19126_Content_11 = {Text = "Davvero?"},
  AvgDialog_19126_Content_12 = {
    Text = "Posso lasciarti risvegliarla, e posso anche ritrasformarla in un mucchio di sabbia argentata."
  },
  AvgDialog_19126_Content_13 = {Text = "Tu!"},
  AvgDialog_19126_Content_14 = {Text = "È adesso!"},
  AvgDialog_19126_Content_15 = {Text = "BANG—!"},
  AvgDialog_19126_Content_16 = {Text = "Ugh!"},
  AvgDialog_19126_Content_17 = {
    Text = "L'attacco colpì in pieno lo scudo esterno di Ramona. Lo scudo si frantumò con un lampo dopo appena mezzo secondo."
  },
  AvgDialog_19126_Content_18 = {
    Text = "Studentessa?!"
  },
  AvgDialog_19126_Content_19 = {Text = "Ramona!"},
  AvgDialog_19126_Content_2 = {
    Text = [[
22:35
Sonaniel
Sala Motori]]
  },
  AvgDialog_19126_Content_20 = {
    Text = "Sto bene, non avvicinarti!"
  },
  AvgDialog_19126_Content_21 = {
    Text = "Mentre mi distraggo cercando di proteggere gli altri, non sono all'altezza di questa donna.\nFarò del mio meglio per trattenere i suoi attacchi. Prendili e andate via per primi."
  },
  AvgDialog_19126_Content_22 = {
    Text = "Verrai a raggiungermi, vero?"
  },
  AvgDialog_19126_Content_23 = {
    Text = "Cosa ti preoccupa?"
  },
  AvgDialog_19126_Content_24 = {
    Text = "Ramona brandì la spada, disperdendo le ombre serpentine che attaccavano, poi ti rivolse un rapido sorriso."
  },
  AvgDialog_19126_Content_25 = {Text = "..."},
  AvgDialog_19126_Content_26 = {
    Text = "Capitano, sbrigati!"
  },
  AvgDialog_19126_Content_27 = {
    Text = "—Come se fossi inseguito da una bestia furiosa, corri freneticamente fuori dalla cabina."
  },
  AvgDialog_19126_Content_3 = {
    Text = "Mossa da un destino comune di anime erranti, ti ho donato il mezzo per riportare il Defunto in questo mondo."
  },
  AvgDialog_19126_Content_4 = {
    Text = "La sua presenza ha esaudito il tuo desiderio più profondo. Sicuramente hai trovato conforto nei tuoi cari perduti..."
  },
  AvgDialog_19126_Content_5 = {
    Text = "Il mio desiderio, la grande aspettativa conferita da Dio, è <Blue:quella bambina>.\nRestituitemi la Santessa... no, la Madre Divina."
  },
  AvgDialog_19126_Content_6 = {
    Text = "Per grazia del nostro dio, quando Egli rinascerà nella vergine sacra e il regno divino discenderà ancora una volta... anche voi entrerete nel regno divino e troverete pace eterna."
  },
  AvgDialog_19126_Content_7 = {
    Text = "Alto Sacerdote, anch'io sono rimasto sconvolto nell'apprendere della scomparsa della Madre Divina. Ma come ho detto, non si trova sulla nave."
  },
  AvgDialog_19126_Content_8 = {
    Text = "Perché fingersi Il Folle con tanta ostentazione?"
  },
  AvgDialog_19126_Content_9 = {
    Text = "Un tempo ammiravo la tua intelligenza e la tua tenacia. Cosa ha cambiato la tua lealtà verso di me? È questo <Yellow:Golem>? Così debole e fugace..."
  },
  AvgDialog_19127_Content_1 = {Text = "Calcamare"},
  AvgDialog_19127_Content_10 = {
    Text = "Non mi aspetto che tu mi dia una mano."
  },
  AvgDialog_19127_Content_11 = {
    Text = "Ma se davvero tutto \"è iniziato per causa tua\", spero almeno di non sentire commenti insensibili dal colpevole."
  },
  AvgDialog_19127_Content_12 = {Text = "Custode..."},
  AvgDialog_19127_Content_13 = {
    Text = "Quelle creature hanno attaccato dal lato sud del ponte, il Custode non poteva lanciarsi dritto nell'accerchiamento nemico, {Male=lui,Female=lei} non è così sciocco."
  },
  AvgDialog_19127_Content_14 = {
    Text = "Deve esserci un'entrata con botola inosservata sul ponte lato nord dove ci trovavamo."
  },
  AvgDialog_19127_Content_15 = {Text = "Tu..."},
  AvgDialog_19127_Content_16 = {
    Text = "Che c'è? Altre scoperte?"
  },
  AvgDialog_19127_Content_17 = {
    Text = "Mi chiedo, come percepisci \"quei mostri\"?"
  },
  AvgDialog_19127_Content_18 = {
    Text = "Dita palmate, completamente ittici sopra il coccige, conservano una certa intelligenza."
  },
  AvgDialog_19127_Content_19 = {
    Text = "Le loro forme sono lisce e naturali, a differenza delle opere de Gli Scultori, che rovinano sempre i loro pezzi sperimentali."
  },
  AvgDialog_19127_Content_2 = {
    Text = [[
21:30
Sonnanir
Ponte]]
  },
  AvgDialog_19127_Content_20 = {
    Text = "Pensavo che il loro aspetto derivasse da mutazioni dopo l'esposizione al <Yellow:Cataclisma>, ma in questi scontri non ho individuato alcun <Yellow:D-segno> evidente su di loro."
  },
  AvgDialog_19127_Content_21 = {
    Text = "Loro... sono più simili a uno scherzo crudele che l'evoluzione ha giocato all'umanità."
  },
  AvgDialog_19127_Content_22 = {
    Text = "\"Uno scherzo idiota dell'evoluzione sull'umanità\"—apprezzo la tua metafora."
  },
  AvgDialog_19127_Content_23 = {
    Text = [[
Grazie, ma questo non mi rende meno vigile nei tuoi confronti.
Specialmente dopo che hai commentato con tanta disinvoltura il mio rapporto con il Custode.]]
  },
  AvgDialog_19127_Content_24 = {
    Text = "Non agirò contro di te."
  },
  AvgDialog_19127_Content_25 = {
    Text = "Davvero? Allora perché non vuoi rivelare il vero motivo per cui hai lasciato la scuola senza permesso? È davvero così difficile ammetterlo?"
  },
  AvgDialog_19127_Content_26 = {
    Text = "Non ti devo alcuna spiegazione, ma se necessario, presterò il mio aiuto."
  },
  AvgDialog_19127_Content_27 = {
    Text = "Il Custode e io speriamo di indagare sugli indizi riguardanti la Chiesa Portaluce e trovare un modo per fuggire in sicurezza da questa nave."
  },
  AvgDialog_19127_Content_28 = {
    Text = "Non credo ci sia un conflitto di interessi tra noi; altrimenti, non avrei l'opportunità di essere qui a parlare con te. Essere sinceri è vantaggioso per entrambi."
  },
  AvgDialog_19127_Content_29 = {
    Text = "I miei affari non ti riguardano."
  },
  AvgDialog_19127_Content_3 = {
    Text = "Ramona si aggrappava alla ringhiera della nave, con metà del corpo sporgente oltre il bordo."
  },
  AvgDialog_19127_Content_30 = {
    Text = "Vedi, è proprio questo atteggiamento che ti rende inaffidabile."
  },
  AvgDialog_19127_Content_31 = {
    Text = "La tua dimostrazione di rabbia ti rende molto umana."
  },
  AvgDialog_19127_Content_32 = {
    Text = "A essere sinceri, la freddezza che dimostri rende difficile credere che un tempo tu abbia vissuto come un essere umano."
  },
  AvgDialog_19127_Content_33 = {
    Text = "Discutere è una perdita di tempo per entrambi. Torniamo al ponte nord."
  },
  AvgDialog_19127_Content_34 = {
    Text = "Ramona concluse con calma la conversazione, passò accanto al giovane Risvegliatore e si diresse verso il punto in cui era salita a bordo."
  },
  AvgDialog_19127_Content_35 = {
    Text = "Attenzione, attacco nemico!"
  },
  AvgDialog_19127_Content_36 = {Text = "Cosa?"},
  AvgDialog_19127_Content_4 = {
    Text = "La punta dello stocco proteso trafisse lo schermo di luce, generando un piccolo e peculiare vortice nell'aria apparentemente vuota."
  },
  AvgDialog_19127_Content_5 = {
    Text = "Dopo un momento, rinfoderò lo stocco e si piantò saldamente sul ponte."
  },
  AvgDialog_19127_Content_6 = {
    Text = "La nave ha preso il largo, ma a causa della cortina di luce è impossibile determinare la direzione usando punti di riferimento."
  },
  AvgDialog_19127_Content_7 = {
    Text = "Porto, destinazione, armatore... niente di tutto ciò conta. La priorità è trovare il Custode."
  },
  AvgDialog_19127_Content_8 = {
    Text = "Pensavo che con le tue capacità, non avresti dovuto obbedire ciecamente al cosiddetto \"Custode\"."
  },
  AvgDialog_19127_Content_9 = {
    Text = "Non hai bisogno di un collegamento per restare razionale; puoi combattere da sola."
  },
  AvgDialog_19128_Content_1 = {
    Text = "I <Blue:Navigatori> sono per lo più fisicamente fragili. Questa spada gigante appartiene a un altro padrone; maneggiatela con cautela."
  },
  AvgDialog_19128_Content_2 = {
    Text = "Come chiamate questi murloc?"
  },
  AvgDialog_19128_Content_3 = {
    Text = "Si stanno avvicinando. Fate attenzione."
  },
  AvgDialog_19129_Content_1 = {
    Text = "Luce perduta"
  },
  AvgDialog_19129_Content_10 = {
    Text = "Ci conosci?"
  },
  AvgDialog_19129_Content_11 = {
    Text = "Se c'è qualcosa che <Blue:\"Stoppino\"> odia con passione, tu sei una di quelle... Tuttavia, ho sempre avuto un debole per le persone astute."
  },
  AvgDialog_19129_Content_12 = {
    Text = "Stoppino, lanterna... Potrebbe <Blue:\"stoppino\"> riferirsi a figure speciali all'interno della Chiesa Portaluce?"
  },
  AvgDialog_19129_Content_13 = {
    Text = "L'aspetto dei Navigatori rende loro difficile camminare tra la gente, e desiderano il nostro potere... Solo uno sfruttamento reciproco tra creature anomale, che si stringono insieme per scaldarsi."
  },
  AvgDialog_19129_Content_14 = {
    Text = [[
Devi essere una collaboratrice molto stimata che controlla le forze dei Navigatori.
O sei anche tu una degli "Stoppini"?]]
  },
  AvgDialog_19129_Content_15 = {
    Text = "Sebbene la mia forma sia quella di una <Yellow:Candela Fioca>, la visione che perseguo differisce enormemente da quella degli altri stoppini.\nVoi salvate il mondo dalla <Yellow:Lordura Nera>, e questo non è in conflitto con <Blue:il ritorno del Regno divino>."
  },
  AvgDialog_19129_Content_16 = {
    Text = [[
I saggi non dovrebbero perdersi nel mondano.
Sebbene la terra divina sia intrecciata con le stirpi, non disdegna accogliere sangue nuovo.]]
  },
  AvgDialog_19129_Content_17 = {
    Text = "Serviteci, unitevi alla Rinascita dalla Terra e alla Rinascita del Reame Divino, e camminate con me nella beatitudine eterna."
  },
  AvgDialog_19129_Content_18 = {
    Text = "Se la rinascita di cui parli prevede l'uso dei vivi come sacrifici e degli innocenti come recipienti per i mostri."
  },
  AvgDialog_19129_Content_19 = {
    Text = "Mi dispiace, non posso farlo, e nemmeno il Custode lo approverebbe."
  },
  AvgDialog_19129_Content_2 = {
    Text = [[
22:55
Sonaniel
Sala motori]]
  },
  AvgDialog_19129_Content_20 = {
    Text = "<Big:Insolente!> Dovresti sentirti onorata di servire come recipiente per la rinascita di un dio."
  },
  AvgDialog_19129_Content_21 = {
    Text = "<Gray:Bene, sei riuscita a provocarla... Ora, guidala ad attaccare! Se il suo attacco squarcia lo scafo, c'è una possibilità di fuggire nel caos...>"
  },
  AvgDialog_19129_Content_22 = {
    Text = "Questa volta ho giudicato male. Non c'è bisogno di sprecare parole con gli stolti..."
  },
  AvgDialog_19129_Content_23 = {
    Text = "<Gray:È adesso!>"
  },
  AvgDialog_19129_Content_24 = {
    Text = "Ehi? Sembra che andiate d'accordo."
  },
  AvgDialog_19129_Content_25 = {
    Text = "Vari scenari si ripresentarono nella mente di Ramona, ma la realtà indicava la possibilità che aveva deliberatamente ignorato."
  },
  AvgDialog_19129_Content_26 = {Text = "%player%!"},
  AvgDialog_19129_Content_27 = {
    Text = "Golia ti trascina per il mantello nella sala motori."
  },
  AvgDialog_19129_Content_28 = {
    Text = "Ra...mona..."
  },
  AvgDialog_19129_Content_29 = {
    Text = "Il Legame con Tulu ti ha completamente prosciugato, e sarà difficile resistere finché non avrai la possibilità di riposare."
  },
  AvgDialog_19129_Content_3 = {
    Text = "Dopo aver sferrato il primo colpo, Miryam non fece altre mosse.\nI Navigatori immuni al dolore bastavano da soli a mettere Ramona in seria difficoltà."
  },
  AvgDialog_19129_Content_30 = {
    Text = "Ho riportato anche questo ragazzo. Che ne pensi? Dovremmo sbarazzarci di lui?"
  },
  AvgDialog_19129_Content_31 = {
    Text = "Questa farsa deve finire."
  },
  AvgDialog_19129_Content_32 = {
    Text = "Non c'è tempo per capire la situazione. Il potere erutta dalle ombre, condensandosi in un'enorme e solida forma energetica simile a un serpente."
  },
  AvgDialog_19129_Content_33 = {
    Text = "Il serpente gigante si dibatte furiosamente nello spazio, le sue pupille si fissano infine su di te—"
  },
  AvgDialog_19129_Content_34 = {Text = "Basta!"},
  AvgDialog_19129_Content_35 = {
    Text = "Il serpente gigante si avvolge attorno alla tua vita, sollevandoti in alto senza sforzo."
  },
  AvgDialog_19129_Content_36 = {
    Text = "Basta, lascia andare quello studente."
  },
  AvgDialog_19129_Content_37 = {
    Text = "Chi va là!"
  },
  AvgDialog_19129_Content_38 = {
    Text = "Una Voce, dolorosamente familiare, balzò attraverso l'abisso della storia — lieve come una brezza al largo, eppure capace di scatenare un'ondata nel tuo cuore."
  },
  AvgDialog_19129_Content_39 = {
    Text = "Miryam, ho detto, lascia stare quello."
  },
  AvgDialog_19129_Content_4 = {
    Text = "Non degnò Ramona di un altro sguardo.\nCon gli occhi socchiusi, se ne stava tranquillamente nell'angolo della stanza, come una statua sacra."
  },
  AvgDialog_19129_Content_40 = {
    Text = "E vero. Questa farsa finisce ora."
  },
  AvgDialog_19129_Content_41 = {
    Text = "Ah... Ah..."
  },
  AvgDialog_19129_Content_42 = {
    Text = "Un gemito rauco gli sfuggì dalla gola, come ingranaggi sovraccarichi, o meglio, il crollo di un altare."
  },
  AvgDialog_19129_Content_43 = {
    Text = "I suoi occhi si spalancarono al massimo, le iridi viola scuro persero il loro colore, il suo atteggiamento non emanava più la fredda arroganza mostrata quando vi affrontava."
  },
  AvgDialog_19129_Content_44 = {
    Text = "Mio Signore... Come potete essere qui...\nPerché portate... l'odore di <Blue:Golem> addosso...?"
  },
  AvgDialog_19129_Content_45 = {
    Text = "Scaglie fredde e viscide scivolarono sul tuo corpo, il serpente che stringeva come un predatore che strangola la sua preda."
  },
  AvgDialog_19129_Content_46 = {
    Text = "<Blue:Mio Signore>... mio stimato <Blue:Re>..."
  },
  AvgDialog_19129_Content_47 = {
    Text = "Mi avevate promesso... Mi avevate promesso..."
  },
  AvgDialog_19129_Content_48 = {
    Text = "Miryam, <BigShake:stai sfidando i miei ordini?!>"
  },
  AvgDialog_19129_Content_49 = {
    Text = "No... non posso... Mio Re... non devo disobbedire..."
  },
  AvgDialog_19129_Content_5 = {
    Text = "<Gray:Per lei, le vite del Custode e la mia sono solo erbacce insignificanti.>"
  },
  AvgDialog_19129_Content_50 = {
    Text = "<Gray:C'è un'opportunità!>"
  },
  AvgDialog_19129_Content_6 = {
    Text = "<Gray:Forse posso sfruttare questo a mio vantaggio...>"
  },
  AvgDialog_19129_Content_7 = {Text = "Fermati."},
  AvgDialog_19129_Content_8 = {
    Text = "Sotto lo sguardo diffidente e perplesso di Ramona, i Navigatori si ritirarono dietro la loro padrona come la marea che si ritrae."
  },
  AvgDialog_19129_Content_9 = {
    Text = "Appartieni a quell'università.\nCosì giovane... Sei ancora un'apprendista, giusto?"
  },
  AvgDialog_19130_Content_1 = {
    Text = "Membro dell'Equipaggio"
  },
  AvgDialog_19130_Content_10 = {
    Text = "Teatro dell'opera?"
  },
  AvgDialog_19130_Content_11 = {
    Text = "<Yellow:%player%> si è unito ai Mythag ed è sempre in missione ogni volta che esce. Ho sempre voluto mostrargli Londinium."
  },
  AvgDialog_19130_Content_12 = {
    Text = "Il teatro dell'opera è un punto di riferimento conosciuto da tutti. Con un nuovo spettacolo in debutto, ha perfettamente senso iniziare il tour da lì."
  },
  AvgDialog_19130_Content_13 = {
    Text = "Ma non ti aspetti di essere una semplice spettatrice."
  },
  AvgDialog_19130_Content_14 = {
    Text = "...A volte trovo la tua perspicacia terrificante, come un re delle fiabe capace di leggere nel cuore delle persone."
  },
  AvgDialog_19130_Content_15 = {Text = "..."},
  AvgDialog_19130_Content_16 = {
    Text = "Riesco davvero ad apprezzare la bellezza dell'arte. Fin da bambina, mio padre mi portava spesso a teatro e alle mostre d'arte, e aveva persino assunto un insegnante per istruirmi nell'apprezzamento artistico."
  },
  AvgDialog_19130_Content_17 = {
    Text = "Crescendo, più comprendevo ciò che accadeva nell'ombra del mondo, meno riuscivo a godere dell'arte con animo sereno."
  },
  AvgDialog_19130_Content_18 = {
    Text = "Penso che se non riusciremo a trovare l'origine del <Yellow:Fenomeno-D>, tutte queste cose meravigliose si dissolveranno nell'Illusione."
  },
  AvgDialog_19130_Content_19 = {
    Text = "Amici, familiari e amanti svaniscono uno dopo l'altro. Alla fine, non importa quanti ne restino, questo mondo diventerà una landa desolata dove nessuno comprende più l'essenza dell'arte."
  },
  AvgDialog_19130_Content_2 = {
    Text = [[
21:50
Sonnanir
Ponte]]
  },
  AvgDialog_19130_Content_20 = {
    Text = "Nulla in questo mondo può davvero durare per sempre."
  },
  AvgDialog_19130_Content_21 = {
    Text = "Seguire la corrente, cogliere l'occasione... Cosa c'è di sbagliato?"
  },
  AvgDialog_19130_Content_22 = {Text = "...Heh."},
  AvgDialog_19130_Content_23 = {
    Text = "Perché ridi?"
  },
  AvgDialog_19130_Content_24 = {
    Text = "Non sono l'unica a non voler \"seguire la corrente\"."
  },
  AvgDialog_19130_Content_25 = {
    Text = "Una volta hai detto che tutto qui \"è iniziato per causa tua\".\nAll'inizio, non ho creduto del tutto alle tue parole a causa della tua reticenza,"
  },
  AvgDialog_19130_Content_26 = {
    Text = "Ma dopo che Golia è apparso... ora credo che, sebbene i vostri poteri provengano entrambi dal Reame del Mare Profondo, il legame tra voi non finisca certo lì."
  },
  AvgDialog_19130_Content_27 = {
    Text = "Quel guerriero è evasivo e cambia argomento. Lo hai appena conosciuto, perché ti fidi così facilmente delle sue parole?"
  },
  AvgDialog_19130_Content_28 = {
    Text = "Ciò che mi ha davvero convinta a fidarmi di lui è stato il tuo atteggiamento."
  },
  AvgDialog_19130_Content_29 = {
    Text = "Se davvero seguissi il destino senza opporre resistenza né desiderio di rimediare... non saresti qui, vero?"
  },
  AvgDialog_19130_Content_3 = {Text = "Hmm..."},
  AvgDialog_19130_Content_30 = {
    Text = "Le parole di Ramona non mostravano pietà. Parole che in origine non intendevano attaccare divennero lame affilate, lacerando senza pietà la copertura di qualcuno."
  },
  AvgDialog_19130_Content_31 = {
    Text = "Tulu socchiuse gli occhi, mantenendo la testa inclinata, lo sguardo che scivolava oltre Ramona per perdersi verso il mare che rifletteva una luce inquietante."
  },
  AvgDialog_19130_Content_32 = {
    Text = "Non posso e non voglio costringerti a confessare qui. Non è il momento né il luogo adatto per aprire i nostri cuori."
  },
  AvgDialog_19130_Content_33 = {
    Text = "La priorità assoluta è trovare il Custode e poi escogitare un modo per tornare a terra.\nControlla sotto coperta; potresti trovare qualche indizio."
  },
  AvgDialog_19130_Content_4 = {Text = "Ugh..."},
  AvgDialog_19130_Content_5 = {
    Text = "Ancora turbata dalle parole del guerriero?"
  },
  AvgDialog_19130_Content_6 = {
    Text = "Ramona emise un profondo sospiro, rivelando una rara espressione di angoscia."
  },
  AvgDialog_19130_Content_7 = {
    Text = "Le cose si sono fatte più complesse. Chi avrebbe mai pensato che questi uomini-pesce... i Navigatori, fossero davvero collegati alla Chiesa Portaluce."
  },
  AvgDialog_19130_Content_8 = {
    Text = "Questa missione doveva essere solo un'<Yellow:Operazione sul campo> di routine. Dopo aver verificato il contenuto del diario di Francis, potremo tornare rapidamente a Londinium."
  },
  AvgDialog_19130_Content_9 = {
    Text = "Con un po' di fortuna, potresti assistere al debutto di un nuovo spettacolo al <Blue:Teatro dell'Opera di Londinium>."
  },
  AvgDialog_19131_Content_1 = {
    Text = "Penzolavi a testa in giù nella morsa del serpente, il sangue che affluiva alla testa, la Visuale che svaniva nel nero."
  },
  AvgDialog_19131_Content_10 = {
    Text = "...%player%."
  },
  AvgDialog_19131_Content_11 = {
    Text = "Sono in paradiso?"
  },
  AvgDialog_19131_Content_12 = {
    Text = "Spiacente, siamo ancora sulla Sonanil. E la crisi è imminente..."
  },
  AvgDialog_19131_Content_13 = {
    Text = "<Small:Imperdonabile...>"
  },
  AvgDialog_19131_Content_14 = {
    Text = "In nome di @3, Costui, il 18° Inviato Reggente di Lemuria, vi comanda!"
  },
  AvgDialog_19131_Content_15 = {
    Text = "Lemuria è sprofondata e la civiltà è giunta al termine.\nSomma Sacerdotessa Miryam, cessate questa follia!"
  },
  AvgDialog_19131_Content_16 = {
    Text = "Follia...? Ho <Yellow:vagato in solitudine per diecimila anni>, agendo per il ritorno del Reame Divino... e questa sarebbe soltanto follia?"
  },
  AvgDialog_19131_Content_17 = {
    Text = "Non è reale... Maledetta contraffazione..."
  },
  AvgDialog_19131_Content_18 = {
    Text = "Padrone... Mio Signore... <Red:Il Vero Dio>... Murphy...\nSì... Ho ancora Murphy..."
  },
  AvgDialog_19131_Content_2 = {
    Text = "Ma nella tua confusione, intravedesti due ragazze... circondate da Navigatori, che si avvicinavano."
  },
  AvgDialog_19131_Content_20 = {
    Text = "Non è troppo tardi.\nTorna alla setta, e rimarrai la venerata Madre Divina."
  },
  AvgDialog_19131_Content_21 = {
    Text = "Il tuo funerale sarà il rito più grandioso nella storia del Reame Divino, venerato da migliaia di fedeli... il tuo nome inciso negli annali eterni."
  },
  AvgDialog_19131_Content_22 = {
    Text = "Torna da me. Insieme, noi... giustizieremo questo <Blue:blasfemo>."
  },
  AvgDialog_19131_Content_23 = {
    Text = "Esecuzione... Questa persona ignobile, travestita da mio signore!"
  },
  AvgDialog_19131_Content_24 = {
    Text = "Il serpente si dissolse e si riformò, lo spazio si deformava sotto il potere di Miryam."
  },
  AvgDialog_19131_Content_25 = {
    Text = "Miryam! Ti ordino di fermarti!"
  },
  AvgDialog_19131_Content_26 = {
    Text = "Falso dio, contraffatto, ingannatore, blasfemo... Nessun @1@2... Non è permesso usare la forma di @3@4!"
  },
  AvgDialog_19131_Content_27 = {
    Text = [[
In un istante, le ombre che avvolgevano la sala macchine si solidificarono.
Strutture indescrivibili e contorte si levarono dal suolo.]]
  },
  AvgDialog_19131_Content_28 = {
    Text = "<Change>Irriverenti... Irriverenti... Sfrenato e incontrollabile▼▼▼▼▼▼▼▼!"
  },
  AvgDialog_19131_Content_29 = {
    Text = "La sua voce degenerò in un rumore stridulo e incoerente, le mani che artigliavano la gola mentre il corpo si stirava e contorceva."
  },
  AvgDialog_19131_Content_3 = {
    Text = "Ramona! Adesso!"
  },
  AvgDialog_19131_Content_30 = {
    Text = "Attento! Sta perdendo il controllo!"
  },
  AvgDialog_19131_Content_4 = {
    Text = "Ramona inspirò profondamente, piegò un ginocchio, incanalò energia sotto i piedi, e spiccò un balzo —"
  },
  AvgDialog_19131_Content_6 = {
    Text = "La punta del suo stocco perforò le scaglie del serpente, colpendone il punto vitale."
  },
  AvgDialog_19131_Content_7 = {
    Text = "Ehi, ehi! {Male=Sta,Female=Sta} per cadere!"
  },
  AvgDialog_19131_Content_8 = {
    Text = "Sei precipitato tra il ruggito del serpente..."
  },
  AvgDialog_19131_Content_9 = {
    Text = "—in un abbraccio tremante e caldo."
  },
  AvgDialog_19132_Content_2 = {
    Text = "Dannazione, questi tizi continuano a inseguirci..."
  },
  AvgDialog_19132_Content_3 = {
    Text = "Anche senza ordini, il numero schiacciante di Navigatori formava un muro tra Miryam e Ramona."
  },
  AvgDialog_19132_Content_4 = {
    Text = "Senza le istruzioni del Custode, il cervello deve gestire sia i calcoli strategici che la coordinazione muscolare... Quanto ancora potrà resistere?"
  },
  AvgDialog_19132_Content_5 = {
    Text = "<Big:Tutti quanti, levatevi dalla mia strada!>"
  },
  AvgDialog_19132_Content_6 = {Text = "Murphy!?"},
  AvgDialog_19132_Content_7 = {
    Text = "I Navigatori riconobbero Murphy, che \"portava\" gli dèi, e si ritrassero istintivamente al suo avvicinarsi. Lei corse attraverso l'accerchiamento dei mostri."
  },
  AvgDialog_19132_Content_8 = {
    Text = "Smettila di fare baccano. Vuoi avvicinarti a quella donna, giusto? Seguimi, ti apro la strada."
  },
  AvgDialog_19133_Content_1 = {Text = "Apostolo"},
  AvgDialog_19133_Content_10 = {
    Text = "...D'accordo, fai strada, per favore."
  },
  AvgDialog_19133_Content_2 = {
    Text = [[
22:00
Sonaniel
Sala Motori]]
  },
  AvgDialog_19133_Content_3 = {
    Text = "Quando il Navigatore è salito a bordo, Murphy non era con noi.\nCeleste, dove si trova adesso?"
  },
  AvgDialog_19133_Content_4 = {
    Text = "La Risvegliatrice chiude gli occhi, e alcune particelle di luce si librano dalla bussola nella sua mano, svanendo rapidamente."
  },
  AvgDialog_19133_Content_5 = {
    Text = "Murphy... Alloggi dell'Equipaggio."
  },
  AvgDialog_19133_Content_6 = {
    Text = "Il dormitorio si trova a poppa. Ti ci porto io."
  },
  AvgDialog_19133_Content_7 = {
    Text = "Ma il tuo corpo..."
  },
  AvgDialog_19133_Content_8 = {
    Text = "È solo una passeggiata dalla prua alla poppa. Non sono così fragile."
  },
  AvgDialog_19133_Content_9 = {
    Text = "Non importa cosa succeda — c'è sempre un modo per risolvere le cose."
  },
  AvgDialog_19134_Content_1 = {
    Text = "Il rumore che abbiamo fatto li ha attirati qui?"
  },
  AvgDialog_19134_Content_2 = {
    Text = "Non è il momento di parlarne. Prima liberiamoci di loro."
  },
  AvgDialog_19134_Content_3 = {
    Text = "Andate al castello di poppa! <Yellow:%player%> e io abbiamo già eliminato i Navigatori laggiù!"
  },
  AvgDialog_19135_Content_1 = {Text = "Pugnale"},
  AvgDialog_19135_Content_10 = {
    Text = "Vivo su questa nave da mesi — conosco ogni condotto d'aerazione, ogni buco di topo."
  },
  AvgDialog_19135_Content_11 = {
    Text = "Ma non stavamo nemmeno strisciando nelle condutture, solo vagando per la cabina."
  },
  AvgDialog_19135_Content_12 = {
    Text = "Io... è solo che non scendo quaggiù da sola molto spesso. Di solito sono con il capitano e l'equipaggio."
  },
  AvgDialog_19135_Content_13 = {
    Text = "C'è una mappa del ponte sulla parete."
  },
  AvgDialog_19135_Content_14 = {
    Text = "Cosa vorresti dire? Metti in dubbio la mia memoria?"
  },
  AvgDialog_19135_Content_15 = {
    Text = "Ho detto che posso trovarlo, e lo troverò — il capitano dev'essere da questa parte!"
  },
  AvgDialog_19135_Content_16 = {
    Text = "Ma questa è la quinta volta che passiamo davanti a questa scalinata."
  },
  AvgDialog_19135_Content_17 = {
    Text = [[
La mia compagna ci sta aspettando per ricongiungersi. Dev'essere in ansia ormai.
Per favore, Lord Murphy, dai un'occhiata alla mappa.]]
  },
  AvgDialog_19135_Content_18 = {Text = "...Hmph!"},
  AvgDialog_19135_Content_2 = {Text = "..."},
  AvgDialog_19135_Content_3 = {Text = "Hmm..."},
  AvgDialog_19135_Content_4 = {Text = "Murphy..."},
  AvgDialog_19135_Content_5 = {
    Text = "Silenzio! Stai disturbando i miei pensieri."
  },
  AvgDialog_19135_Content_6 = {
    Text = [[
Tacesti riguardo all'"interrompere i ragionamenti di Murphy."
Ma sapevi che dovevi impedirle di "ragionare" oltre.]]
  },
  AvgDialog_19135_Content_7 = {
    Text = "Stai andando avanti e indietro, su e giù nella cabina da un bel po'."
  },
  AvgDialog_19135_Content_8 = {
    Text = "Ti sei persa?"
  },
  AvgDialog_19135_Content_9 = {
    Text = "Ma figurati! Io non mi perdo!"
  },
  AvgDialog_19136_Content_1 = {
    Text = "Capitano, puoi portare la nave a riva immediatamente?"
  },
  AvgDialog_19136_Content_2 = {
    Text = "Se avessimo potuto farlo, la Sonaniel non sarebbe stata catturata dai Navigatori."
  },
  AvgDialog_19136_Content_3 = {
    Text = "Più vicino, ancora più vicino... Basta lasciarti andare... Posso farcela...\nLa riva è a portata di mano."
  },
  AvgDialog_19136_Content_4 = {
    Text = "Finché saremo abbastanza vicini alla terraferma, potrai far scendere tutti dalla nave, giusto? Celeste."
  },
  AvgDialog_19136_Content_5 = {Text = "Tutti..."},
  AvgDialog_19136_Content_6 = {
    Text = "Attenzione, ci stanno raggiungendo!"
  },
  AvgDialog_19137_Content_1 = {Text = "Scappa"},
  AvgDialog_19137_Content_10 = {
    Text = "Custode, ora basta."
  },
  AvgDialog_19137_Content_11 = {
    Text = "Patetico, davvero patetico."
  },
  AvgDialog_19137_Content_12 = {
    Text = "L'esibizione pretenziosa attirò i fischi del pubblico. Con espressioni sdegnate, invasero il palco e attaccarono l'attore protagonista: Murphy ti sferrò una gomitata secca allo stomaco."
  },
  AvgDialog_19137_Content_13 = {
    Text = "*Coff, coff, coff!*"
  },
  AvgDialog_19137_Content_14 = {
    Text = "Rispondile con energia incontenibile"
  },
  AvgDialog_19137_Content_15 = {
    Text = "Per rassicurare la tua compagna, sfoggiasti un sorriso radioso, una smorfia contorta, mostrando esattamente otto denti, facendoti sembrare una delle creazioni di Rogers."
  },
  AvgDialog_19137_Content_16 = {Text = "..."},
  AvgDialog_19137_Content_17 = {
    Text = "A quanto pare te la sei cavata bene mentre non c'ero."
  },
  AvgDialog_19137_Content_18 = {
    Text = "Né... né..."
  },
  AvgDialog_19137_Content_19 = {
    Text = "Già, non ho mai visto un navigatore inseguire giovani studenti e ritrovarsi a rotolarsi per terra con il mal di schiena."
  },
  AvgDialog_19137_Content_2 = {
    Text = [[
22:10
Sonaniel
Esterno della Sala Motori]]
  },
  AvgDialog_19137_Content_20 = {
    Text = "Murphy si fece avanti, infilandosi tra te e Ramona, riuscendo anche a urtarti la parte bassa della schiena slogata."
  },
  AvgDialog_19137_Content_21 = {Text = "Ssssh—"},
  AvgDialog_19137_Content_22 = {
    Text = "A proposito, non avete intenzione di presentarci?"
  },
  AvgDialog_19137_Content_23 = {
    Text = "Il mio nome è Murphy..."
  },
  AvgDialog_19137_Content_24 = {
    Text = "Il nemico sfondò il portello interno, barcollando verso di voi."
  },
  AvgDialog_19137_Content_25 = {
    Text = "Tra la polvere di carbone sollevata dai fedeli, una donna alta e snella avanzava con devozione e follia."
  },
  AvgDialog_19137_Content_26 = {
    Text = "<BigShake:Correte!>"
  },
  AvgDialog_19137_Content_3 = {Text = "Custode!"},
  AvgDialog_19137_Content_4 = {
    Text = "Finalmente ti ho trovato. Sei ferito?"
  },
  AvgDialog_19137_Content_5 = {
    Text = "L'espressione della mia compagna oscillava tra shock, gioia e preoccupazione. Espressioni così vivide si vedevano raramente sul suo volto."
  },
  AvgDialog_19137_Content_6 = {
    Text = "Rispondile con voce flebile"
  },
  AvgDialog_19137_Content_7 = {
    Text = "Perciò, quando Ramona sembrava preoccupata, ti sei stretto l'addome fingendo di essere in punto di morte."
  },
  AvgDialog_19137_Content_8 = {
    Text = "Ramona... Non avrei mai pensato... di rivederti..."
  },
  AvgDialog_19137_Content_9 = {Text = "..."},
  AvgDialog_19138_Content_1 = {
    Text = "\nMurphy non esitò molto; tirò Ramona da parte e iniziò a slacciarle i vestiti.\nQuando l'ultimo bottone sul davanti fu sbottonato, Ramona vide il \"dio\" dentro la ragazza."
  },
  AvgDialog_19138_Content_2 = {
    Text = "Una chiazza di pelle trasparente è chiaramente visibile sul petto, che tira la pelle e i muscoli circostanti, conferendo all'intero torace e addome una tonalità grigiastra, di un bianco in decomposizione."
  },
  AvgDialog_19138_Content_3 = {
    Text = "Una tale anomalia esponeva gli organi nel suo petto; Ramona vide un giovane cuore di un cremisi pallido e un \"uovo\" lattiginoso."
  },
  AvgDialog_19138_Content_4 = {
    Text = "Innumerevoli filamenti sottili germogliavano dall'uovo, intrecciandosi con i vasi sanguigni di Murphy in una danza simbiotica."
  },
  AvgDialog_19138_Content_5 = {
    Text = "Se non fosse stato per il modo in cui premeva contro il suo cuore, sarebbe potuto sembrare una parte naturale del suo corpo traslucido, non un intruso estraneo."
  },
  AvgDialog_19138_Content_6 = {
    Text = "Caotico eppure silenzioso, recava un triangolo invertito e immobile di segni neri, come un'opera d'arte grottesca."
  },
  AvgDialog_19138_Content_7 = {
    Text = "<Yellow:Dissoluzione>... Questa cosa è già stata dissolta."
  },
  AvgDialog_19138_Content_8 = {
    Text = "Ti sei stancato di fissare?"
  },
  AvgDialog_19138_Content_9 = {
    Text = "Scusa, errore mio. Per favore, rimettiti i vestiti."
  },
  AvgDialog_19139_Content_1 = {
    Text = "L'uomo imponente non fa alcun tentativo di reprimere la sua rabbia, scalcia via il Navigatore ai suoi piedi, estrae la lama gigante dal ponte e parla con durezza."
  },
  AvgDialog_19139_Content_10 = {
    Text = "Tu sei l'uomo che apparve allora!"
  },
  AvgDialog_19139_Content_11 = {
    Text = "\"Quell'uomo\", suona terribile."
  },
  AvgDialog_19139_Content_12 = {
    Text = "Io sono <Blue:Golia>. Ricordatelo, questo è il nome di colui che ha conquistato i mari!"
  },
  AvgDialog_19139_Content_13 = {
    Text = "È ora di combattere!"
  },
  AvgDialog_19139_Content_2 = {
    Text = "Il vostro compito era trovare la <Blue:Santa Fanciulla> e recuperare l'<Blue:oggetto sacrificale chiave> per il rituale... È davvero questa che avete trovato?\nA parte essere femmina, ha anche la minima somiglianza con la <Blue:Principessa Marionetta>?"
  },
  AvgDialog_19139_Content_3 = {
    Text = "La tua vista non è migliore di quella di un pesce morto."
  },
  AvgDialog_19139_Content_4 = {Text = "Gulp..."},
  AvgDialog_19139_Content_5 = {
    Text = "<Big:Tutti quanti, levatevi dalla mia strada!>"
  },
  AvgDialog_19139_Content_6 = {
    Text = "Un gigante dalla pelle scura si piazza in prima fila, e i Navigatori si ritirano obbedienti a distanza sotto i suoi ordini."
  },
  AvgDialog_19139_Content_7 = {
    Text = "Hmph, non è forse la povera anima usata come <Blue:trampolino>? Perché sei ancora sulla nave? Ti avevo dato la possibilità di andartene."
  },
  AvgDialog_19139_Content_8 = {
    Text = "Passi pesanti riecheggiarono dall'altra estremità del ponte. Una voce maschile roca parlò in una lingua sconosciuta, e i nemici circostanti si ritirarono come una marea."
  },
  AvgDialog_19139_Content_9 = {
    Text = "Non andartene! Chi sei esattamente?"
  },
  AvgDialog_19140_Content_1 = {
    Text = "Studente, sei pallido."
  },
  AvgDialog_19140_Content_10 = {
    Text = "Thul... Hu..."
  },
  AvgDialog_19140_Content_11 = {
    Text = "Nell'oscurità, una manciata di fonti luminose brillava intensamente, ma inseguirle si rivelò vano. Le presenze dei Navigatori sbarravano la tua mente come una Barriera di ferro."
  },
  AvgDialog_19140_Content_12 = {
    Text = "Studente! Svegliati!"
  },
  AvgDialog_19140_Content_13 = {
    Text = "Capitano...?"
  },
  AvgDialog_19140_Content_14 = {
    Text = "Un nemico formidabile si avvicina, corri!"
  },
  AvgDialog_19140_Content_2 = {
    Text = "Ci sono troppi nemici.\nSe il loro assalto non si ferma, non so per quanto ancora potrò resistere..."
  },
  AvgDialog_19140_Content_3 = {
    Text = "Con la sua forza, affrontare questi cosiddetti \"soldati d'élite\" è cosa naturale."
  },
  AvgDialog_19140_Content_4 = {
    Text = "<Yellow:Tulu>?! Come fa a essere qui?"
  },
  AvgDialog_19140_Content_5 = {
    Text = "Ho un'idea! Capitano, per favore trattenete i nemici per ora."
  },
  AvgDialog_19140_Content_6 = {
    Text = "Non possiamo resistere ancora a lungo. Qualunque cosa tu stia pianificando, fallo in fretta."
  },
  AvgDialog_19140_Content_7 = {
    Text = "Chiudi gli occhi, la tua mente sprofonda nell'oscurità, inseguendo ancora una volta le scintille nel <Yellow:Mondo Spirituale>."
  },
  AvgDialog_19140_Content_8 = {
    Text = "<BigShake:...Troppi, troppi!>"
  },
  AvgDialog_19140_Content_9 = {
    Text = "Come entrare in uno stagno di una foresta estiva, il gracidare delle rane risuona come tamburi di guerra... Ogni Navigatore lascia il proprio segno."
  },
  AvgDialog_19141_Content_1 = {
    Text = "Basta. Sono insignificanti."
  },
  AvgDialog_19141_Content_2 = {
    Text = "La figura silenziosa in piedi nell'ultima fila dei nemici ha finalmente parlato."
  },
  AvgDialog_19141_Content_3 = {
    Text = "Era una donna adulta, il corpo avvolto in garza nera, che spiccava tra i brutti e deformi uomini-pesce."
  },
  AvgDialog_19141_Content_4 = {
    Text = "Ponete fine a questa farsa... e riportate indietro la <Blue:Madre Divina>."
  },
  AvgDialog_19141_Content_5 = {
    Text = "Si voltò e si diresse verso la torre del ponte. Al suo comando, un giovane alto si fece avanti dal gruppo di uomini-pesce."
  },
  AvgDialog_19141_Content_6 = {
    Text = "Un umano con le pinne... No... Potrebbe essere un <Yellow:Risvegliatore>?!"
  },
  AvgDialog_19142_Content_1 = {
    Text = "Un Altro Miracolo"
  },
  AvgDialog_19142_Content_10 = {
    Text = "Aigis, la signorina Mason, Lily, Lisa... Finora abbiamo incontrato molte persone i cui corpi sono stati modificati."
  },
  AvgDialog_19142_Content_11 = {
    Text = "Ma trapiantare un <Blue:\"Dio\"> in una persona viva? Questo è semplicemente..."
  },
  AvgDialog_19142_Content_12 = {
    Text = "Che tu ci creda o no, quello che sto dicendo è la verità."
  },
  AvgDialog_19142_Content_13 = {
    Text = "Scusa... è solo che tutto questo è troppo assurdo da comprendere."
  },
  AvgDialog_19142_Content_14 = {
    Text = "Murphy, posso vedere quel... \"Dio\"?"
  },
  AvgDialog_19142_Content_15 = {
    Text = "E dici che non stai dubitando!"
  },
  AvgDialog_19142_Content_16 = {
    Text = "Va bene, non c'è niente di sbagliato in questo. È troppo buio qui; andiamo su."
  },
  AvgDialog_19142_Content_2 = {
    Text = [[
22:20
Sonnanil
Terza Stiva]]
  },
  AvgDialog_19142_Content_3 = {Text = "Questo..."},
  AvgDialog_19142_Content_4 = {
    Text = "Questo è davvero sconvolgente!"
  },
  AvgDialog_19142_Content_5 = {
    Text = "La Setta dei Navigatori, la Chiesa Portaluce, gli dèi..."
  },
  AvgDialog_19142_Content_6 = {
    Text = "E quella prigioniera... è <Blue:Francis>, giusto?"
  },
  AvgDialog_19142_Content_7 = {
    Text = "La conosci? Quella bugiarda, quella peste! Non è mai tornata ad aiutarmi! Alla fine, ho dovuto trovare un modo per scappare da sola!"
  },
  AvgDialog_19142_Content_8 = {
    Text = "Ha i suoi problemi..."
  },
  AvgDialog_19142_Content_9 = {
    Text = "Hmph... Non la biasimo. Poco dopo che questa cosa è stata inserita, Miryam mi ha drogata per farmi dormire... Non ho idea di quanto tempo sia passato. Potrebbe essere venuta, ma me la sono persa."
  },
  AvgDialog_19143_Content_10 = {
    Text = "Nell'istante fugace prima che la lama cada, concentri la mente, chiudi gli occhi e sprofondi ancora una volta nell'oscurità."
  },
  AvgDialog_19143_Content_11 = {
    Text = "Insegui la luce più brillante intorno a te, il tuo spirito schiacciato da innumerevoli presenze nell'oscurità affollata, il tuo cervello lacerato da un dolore lancinante."
  },
  AvgDialog_19143_Content_12 = {
    Text = "<Gray:Ancora un po'... lo sforzo finale!>"
  },
  AvgDialog_19143_Content_13 = {
    Text = "Ti sei sforzato di \"protenderti,\" afferrando quella stella."
  },
  AvgDialog_19143_Content_14 = {
    Text = "Come se la tua anima avesse abbandonato il corpo, la tua visuale si levò in alto, trascinata da una forza irresistibile."
  },
  AvgDialog_19143_Content_15 = {
    Text = "Vedi te stesso, vedi Celeste, vedi Ramona... Infine, vedi il giovane re seduto in cima al ponte, con un'espressione gelida."
  },
  AvgDialog_19143_Content_16 = {
    Text = "Inizialmente osservava il caos sulla nave con uno sguardo sprezzante, ma poi sembrò rendersi conto di qualcosa e alzò lo sguardo verso il cielo scintillante."
  },
  AvgDialog_19143_Content_17 = {
    Text = "Nei cieli alti, il <Yellow:tuo> sguardo trafigge il Dominio di Celeste, incontrando i suoi occhi sorpresi."
  },
  AvgDialog_19143_Content_18 = {Text = "Whoosh—!"},
  AvgDialog_19143_Content_19 = {
    Text = "I grossi tentacoli pararono il colpo fatale, ma prima che il loro padrone potesse raggiungerti, il Maestro della Grande Lama ti aveva già afferrato."
  },
  AvgDialog_19143_Content_2 = {
    Text = "Investigatori dell'Università di Mythag, è tutto quello che sapete fare?"
  },
  AvgDialog_19143_Content_20 = {
    Text = "<BigShake:Hahahahaha>, interessante, molto interessante."
  },
  AvgDialog_19143_Content_21 = {
    Text = "Quel ragazzino è collegato a te adesso?\nOttimo, non vedo l'ora di vedere quella donna impazzire."
  },
  AvgDialog_19143_Content_22 = {
    Text = "<Big:Stai esagerando! Lascialo andare!>"
  },
  AvgDialog_19143_Content_23 = {
    Text = "Devo riportare qualcuno per fare rapporto. Se non è questo ragazzino, deve essere il capitano."
  },
  AvgDialog_19143_Content_24 = {
    Text = "Non preoccupatevi di me!"
  },
  AvgDialog_19143_Content_25 = {
    Text = "Prendete il capitano e portateli in salvo!"
  },
  AvgDialog_19143_Content_26 = {Text = "Tu..."},
  AvgDialog_19143_Content_27 = {
    Text = "Portali fuori!"
  },
  AvgDialog_19143_Content_28 = {Text = "..."},
  AvgDialog_19143_Content_3 = {
    Text = [[
Il potere del Risvegliatore... 
Sei il secondo capo del Culto dei Navigatori.]]
  },
  AvgDialog_19143_Content_4 = {
    Text = "Secondo posto? Ha, <BigShake:Solo una patetica formica che si vanta!>"
  },
  AvgDialog_19143_Content_6 = {Text = "Ugh!"},
  AvgDialog_19143_Content_7 = {
    Text = "Le battaglie continue ti hanno lasciato completamente esausto. Tentando di stabilire nuovamente un collegamento con il Risvegliatore, senti la vista che va e viene."
  },
  AvgDialog_19143_Content_8 = {
    Text = "Niente male, hai parato quel colpo, ma riuscirai a gestire il prossimo fendente?"
  },
  AvgDialog_19143_Content_9 = {
    Text = "<Gray:Questa è l'ultima possibilità...!>"
  },
  AvgDialog_19144_Content_1 = {
    Text = "Occhio del Ciclone"
  },
  AvgDialog_19144_Content_10 = {
    Text = "Un'enorme luna piena pende nel cielo notturno, una nebbia eterea avvolge il mare, l'aria densa di polvere da sparo e del sapore salmastro dell'acqua salata."
  },
  AvgDialog_19144_Content_11 = {
    Text = "Il suono dolce e ritmico delle onde che si rincorrono culla la barca, alla deriva verso una destinazione sconosciuta."
  },
  AvgDialog_19144_Content_12 = {
    Text = "Senza dubbio, sei su una nave, completamente solo.\nRamona non è al tuo fianco, e non c'è nessun altro in vista."
  },
  AvgDialog_19144_Content_13 = {
    Text = "Tentativo di connessione al comunicatore"
  },
  AvgDialog_19144_Content_14 = {
    Text = "Ramona? Mi senti?"
  },
  AvgDialog_19144_Content_15 = {
    Text = "Signorina Doll? Erica?"
  },
  AvgDialog_19144_Content_16 = {
    Text = "Hai atteso a lungo la voce dei tuoi compagni, solo per renderti conto che la <Yellow:spilla> che simboleggia la tua identità non era sul tuo bavero."
  },
  AvgDialog_19144_Content_17 = {
    Text = "...Ora la situazione è diversa."
  },
  AvgDialog_19144_Content_18 = {
    Text = "Pur non essendo grave quanto perdere la Chiave d'argento, perdere la spilla usata per comunicare significa essere tagliati fuori dai compagni e dai rinforzi."
  },
  AvgDialog_19144_Content_19 = {
    Text = "Calma, calma.\nRagioniamo dall'inizio. Perché mi trovo su questa nave...?"
  },
  AvgDialog_19144_Content_20 = {
    Text = "Il Diario di Francis... Il porto..."
  },
  AvgDialog_19144_Content_21 = {
    Text = "Quando sarete pronta, partiremo. Sarò il vostro compagno, come sempre."
  },
  AvgDialog_19144_Content_22 = {
    Text = "Questa volta... la Chiesa... gli affiliati... devi—"
  },
  AvgDialog_19144_Content_23 = {
    Text = "Avevi appena richiamato alcune immagini frammentarie, quando un dolore intenso ha frantumato i tuoi ricordi."
  },
  AvgDialog_19144_Content_24 = {Text = "...Ugh!"},
  AvgDialog_19144_Content_25 = {
    Text = "Il reflusso acido ti brucia la gola, rendendo l'aria fresca un lusso."
  },
  AvgDialog_19144_Content_26 = {
    Text = "Whew — Cosa è appena successo?"
  },
  AvgDialog_19144_Content_27 = {
    Text = "Ho lasciato la scuola con Ramona... Sì, Ramona, devo trovarla."
  },
  AvgDialog_19144_Content_28 = {
    Text = "Se è lei, dovrebbe sapere cosa è successo."
  },
  AvgDialog_19144_Content_29 = {Text = "—!"},
  AvgDialog_19144_Content_3 = {Text = "Ugh..."},
  AvgDialog_19144_Content_30 = {
    Text = "Il metallo emette un lamento acuto; questo colosso d'acciaio probabilmente non riesce più a resistere al mare."
  },
  AvgDialog_19144_Content_31 = {
    Text = "Non dovremmo restare qui a lungo."
  },
  AvgDialog_19144_Content_32 = {
    Text = "Desideroso di trovare un compagno, sopporti il dolore sordo alla nuca e la nausea, facendo due passi aggrappandoti alla ringhiera della nave."
  },
  AvgDialog_19144_Content_33 = {
    Text = "Non fare mosse avventate."
  },
  AvgDialog_19144_Content_34 = {Text = "Tulu?!"},
  AvgDialog_19144_Content_35 = {Text = "Tu..."},
  AvgDialog_19144_Content_36 = {
    Text = "Sei sveglio?"
  },
  AvgDialog_19144_Content_37 = {
    Text = "Il giovane Risvegliato vi lancia un'occhiata, lo Sguardo calmo eppure imperioso."
  },
  AvgDialog_19144_Content_38 = {
    Text = "Sorvolerò sulla tua impertinenza... per questa volta."
  },
  AvgDialog_19144_Content_39 = {
    Text = "Che ci fai qui?"
  },
  AvgDialog_19144_Content_4 = {
    Text = "È già... l'alba?"
  },
  AvgDialog_19144_Content_40 = {
    Text = "Il giovane Risvegliato inarca un sopracciglio con lieve sorpresa, valutandovi con uno sguardo misurato."
  },
  AvgDialog_19144_Content_41 = {
    Text = "Avete ancora lo spirito per scherzare. Allora non siete ferita."
  },
  AvgDialog_19144_Content_42 = {
    Text = "Come Lotan, Ogier e altri, Tulu è uno dei tanti Risvegliatori sotto la supervisione di <Yellow:Mythag>.\nMa durante l'anno di addestramento a Mythag, le volte in cui hai visto Tulu si potevano contare sulle dita di una mano."
  },
  AvgDialog_19144_Content_43 = {
    Text = "Si dice che Tulu dorma per la maggior parte del tempo, svegliandosi solo in rare occasioni. Naturalmente, Tulu è stato escluso dalla lista dei Risvegliatori operativi sul campo."
  },
  AvgDialog_19144_Content_44 = {
    Text = "In questo momento, sei strettamente avvolto da un <Yellow:Legame> invisibile, percependo l'energia spirituale di Tulu, impetuosa come una tempesta."
  },
  AvgDialog_19144_Content_45 = {
    Text = "Io... ho un Legame con te?!"
  },
  AvgDialog_19144_Content_46 = {
    Text = "Domanda sciocca."
  },
  AvgDialog_19144_Content_47 = {
    Text = "Aspetta, sai dove si trova Ramona? Siamo partiti insieme dalla scuola."
  },
  AvgDialog_19144_Content_48 = {
    Text = "Non è il momento di scherzare; non resta molto tempo."
  },
  AvgDialog_19144_Content_49 = {
    Text = "La <Yellow:Cerimonia di Invocazione> non è ancora terminata; le stelle stanno salendo verso i luoghi a loro destinati."
  },
  AvgDialog_19144_Content_5 = {
    Text = "Vertigini con le tempie pulsanti."
  },
  AvgDialog_19144_Content_50 = {
    Text = "\"Rito della Discesa\"?"
  },
  AvgDialog_19144_Content_51 = {
    Text = "Nel momento in cui la domanda lasciò le tue labbra, l'atmosfera tra te e Tulu si gelò all'istante. L'aria divenne così pesante che iniziasti a dubitare di avere il diritto di porgli qualsiasi domanda."
  },
  AvgDialog_19144_Content_52 = {
    Text = "Tuttavia, <Yellow:\"Discesa\"> è una parola chiave estremamente sensibile e cruciale per i Custodi di Mythag."
  },
  AvgDialog_19144_Content_53 = {
    Text = "Tulu, io..."
  },
  AvgDialog_19144_Content_54 = {
    Text = "Preparazione per affrontare il nemico."
  },
  AvgDialog_19144_Content_55 = {Text = "Cosa?"},
  AvgDialog_19144_Content_56 = {Text = "Plop..."},
  AvgDialog_19144_Content_57 = {
    Text = "Con un suono simile a pinne che sbattono, i nemici emersero dalle ombre."
  },
  AvgDialog_19144_Content_6 = {
    Text = "La gola brucia come se avessi ingoiato un sorso di salsa di soia piccante, ogni respiro accompagnato da un blocco soffocante e dolore."
  },
  AvgDialog_19144_Content_7 = {
    Text = "Occhi aperti, testa pulsante, dintorni sconosciuti."
  },
  AvgDialog_19144_Content_8 = {
    Text = "Oh cielo, non potevamo avere un'apertura più originale?"
  },
  AvgDialog_19144_Content_9 = {
    Text = "Ti sei alzato, e una scena inaspettata si è presentata davanti ai tuoi occhi."
  },
  AvgDialog_19145_Content_1 = {
    Text = "L'attacco nemico lasciò a Ramona poco tempo per reagire; la sua spada non ebbe nemmeno la possibilità di essere sguainata—"
  },
  AvgDialog_19145_Content_2 = {
    Text = "La lama gigante fu scagliata con violenza da lontano verso i due, la sua forza squarciò l'aria generando una potente onda d'urto."
  },
  AvgDialog_19145_Content_3 = {
    Text = "Un robusto appendice si avvolse attorno alla vita di Ramona, strappandola via dal punto d'impatto della lama gigante."
  },
  AvgDialog_19145_Content_4 = {
    Text = "Dopo che Ramona si fu stabilizzata, i tentacoli di Tulu si ritirarono rapidamente per unirsi all'attacco."
  },
  AvgDialog_19145_Content_5 = {
    Text = "Sembra che non abbiamo altra scelta se non cooperare, adesso."
  },
  AvgDialog_19145_Content_6 = {
    Text = "Non servono parole."
  },
  AvgDialog_19163_Content_1 = {
    Text = "Partenza Tragica"
  },
  AvgDialog_19163_Content_10 = {
    Text = "Non preoccuparti. Prosegui e ricongiungiti con gli altri.\nDevo capire perché si aggrappano al rituale."
  },
  AvgDialog_19163_Content_11 = {
    Text = "Tulu sta indagando da solo — vuole confermare cosa tiene in piedi i Navigatori."
  },
  AvgDialog_19163_Content_12 = {
    Text = "Tulu? Quindi vi siete incontrati dopo l'esplosione—sta bene dopo lo scontro e la deflagrazione?"
  },
  AvgDialog_19163_Content_13 = {
    Text = "Ricordi ogni scambio avuto con Tulu dopo l'esplosione — lui resta straordinariamente calmo."
  },
  AvgDialog_19163_Content_14 = {
    Text = "Tulu è molto più lucido di me dopo il mio risveglio dal coma, e non percepisco anomalie attraverso il legame."
  },
  AvgDialog_19163_Content_15 = {
    Text = "Nascondi il legame tra Tulu e Ramona nel profondo del tuo Reame dello Spirito, celando d'istinto la tempesta che ha devastato la tua mente."
  },
  AvgDialog_19163_Content_16 = {
    Text = "La cupola infranta della Gnosi si ricostruisce lentamente, il dolore lacerante dell'anima si affievolisce. In questo momento, non vuoi gravare la tua compagna esausta con altre preoccupazioni."
  },
  AvgDialog_19163_Content_17 = {
    Text = "Eri in coma?!"
  },
  AvgDialog_19163_Content_18 = {
    Text = "Non preoccuparti—ora sto perfettamente bene. Celeste mi ha guarito completamente."
  },
  AvgDialog_19163_Content_19 = {
    Text = "Lanci uno sguardo colpevole a Celeste—la Risvegliatrice menzionata ricambia lo sguardo.\nLe fai l'occhiolino, e lei ti osserva per un momento, in silenzio."
  },
  AvgDialog_19163_Content_2 = {
    Text = [[
Tempo all'Allineamento:
80 minuti]]
  },
  AvgDialog_19163_Content_20 = {
    Text = "Se lo dici tu..."
  },
  AvgDialog_19163_Content_21 = {
    Text = "La Specie Parassita di Murphy richiede una rimozione chirurgica immediata—più a lungo si sviluppa dentro di lei, peggio è per Tutti."
  },
  AvgDialog_19163_Content_22 = {
    Text = "Dobbiamo raggiungere la terraferma al più presto, ma... non sento la nave muoversi."
  },
  AvgDialog_19163_Content_23 = {
    Text = "Capitano, tu e Celeste non riuscite più a governare la Sona-Nyl, vero?"
  },
  AvgDialog_19163_Content_24 = {
    Text = "...Correggere, è un Miracolo che Celeste riesca ancora a resistere—per entrambi."
  },
  AvgDialog_19163_Content_25 = {
    Text = "E le scialuppe di salvataggio?"
  },
  AvgDialog_19163_Content_26 = {
    Text = "Elton scuote la testa."
  },
  AvgDialog_19163_Content_27 = {
    Text = "Le scialuppe di salvataggio sono prive di motore—remare tutti fino a riva? Non è realistico."
  },
  AvgDialog_19163_Content_28 = {
    Text = "No... non c'è davvero via d'uscita?"
  },
  AvgDialog_19163_Content_29 = {
    Text = "Elton accarezza la testa di Murphy per rassicurarla. Alzando lo sguardo, si ritrova circondato dagli sguardi tesi tuoi e di Ramona. Si ferma, poi ride sommessamente."
  },
  AvgDialog_19163_Content_3 = {
    Text = "Questi coralli... da dove sono spuntati?"
  },
  AvgDialog_19163_Content_30 = {
    Text = "Non dimenticare..."
  },
  AvgDialog_19163_Content_31 = {
    Text = "La Sona-Nyl è una nave."
  },
  AvgDialog_19163_Content_32 = {
    Text = "Faccio la manutenzione annuale del suo sistema di alimentazione seguendo il manuale alla lettera—la sua sala macchine è sempre in funzione."
  },
  AvgDialog_19163_Content_33 = {
    Text = "Se riusciamo a raggiungere la plancia..."
  },
  AvgDialog_19163_Content_34 = {
    Text = "Ma... il nostro scontro con Miryam ha gravemente danneggiato la sala macchine, per non parlare dell'esplosione che ha innescato dopo..."
  },
  AvgDialog_19163_Content_35 = {
    Text = "Hmm... me n'ero dimenticato... Senza caldaie per l'energia, raggiungere il ponte di comando non servirà a nulla."
  },
  AvgDialog_19163_Content_36 = {
    Text = "No... ce ne sono ancora alcune."
  },
  AvgDialog_19163_Content_37 = {
    Text = "%player% e io siamo passati dalla sala macchine—è distrutta, ma almeno due caldaie sono ancora accese."
  },
  AvgDialog_19163_Content_38 = {
    Text = "Due caldaie? Bastano per farla muovere."
  },
  AvgDialog_19163_Content_39 = {
    Text = "Allora possiamo controllare la plancia adesso? Sinceramente, è da un'eternità che sono curioso—"
  },
  AvgDialog_19163_Content_4 = {
    Text = "Il suo Sguardo spazza i coralli dalle forme bizzarre, posandosi infine su quello più grande e vistoso."
  },
  AvgDialog_19163_Content_40 = {
    Text = "Shh, shh, silenzio! Nemici in arrivo!"
  },
  AvgDialog_19163_Content_5 = {
    Text = "Gli ammassi di corallo erompono dai D-segni, scostando bruscamente il ponte, puntando dritti verso la paratia superiore."
  },
  AvgDialog_19163_Content_6 = {
    Text = "Le chiamiamo D-iperplasia.\nIn breve, più ci si avvicina al nucleo regionale di Dissoluzione, più è probabile che queste escrescenze compaiano."
  },
  AvgDialog_19163_Content_7 = {
    Text = "Dissoluzione... Di nuovo."
  },
  AvgDialog_19163_Content_8 = {
    Text = "Gli individui infestati tra i Navigatori sono probabilmente anch'essi legati alla Dissoluzione che si propaga."
  },
  AvgDialog_19163_Content_9 = {
    Text = "A proposito di quello..."
  },
  AvgDialog_19170_Content_1 = {
    Text = "Sentiero Astrale Sconosciuto"
  },
  AvgDialog_19170_Content_10 = {
    Text = "Quanto alla posizione dei Navigatori... quando siamo arrivati in mare, la Sona-Nyl era già completamente affondata, e non abbiamo trovato nulla."
  },
  AvgDialog_19170_Content_11 = {
    Text = "Dov'è Golia?"
  },
  AvgDialog_19170_Content_12 = {
    Text = "Nessuna idea. Forse si è trasformato in un vero pesce, forse è annegato, o forse è fuggito su una scialuppa di salvataggio. A proposito, stiamo cercando di recuperare l'Argento di Miryam, ma finora senza fortuna."
  },
  AvgDialog_19170_Content_13 = {
    Text = "Non parliamo di questo. Sono qui per interpretare il referto medico per te."
  },
  AvgDialog_19170_Content_14 = {
    Text = "Doll posa una pila di referti cartacei sulla scrivania, indicandoti di esaminarli da solo."
  },
  AvgDialog_19170_Content_15 = {
    Text = "Dopo tre giorni interi di esami fisici, sei esausto nel corpo e nella mente, e desideri disperatamente una risposta."
  },
  AvgDialog_19170_Content_16 = {
    Text = "Avanti, dimmi le cattive notizie. Posso sopportarlo."
  },
  AvgDialog_19170_Content_17 = {
    Text = "Riguardo alla tua salute..."
  },
  AvgDialog_19170_Content_18 = {
    Text = "Appari in ottima salute, a parte l'anemia, senza altre anomalie."
  },
  AvgDialog_19170_Content_19 = {
    Text = "Doll si ferma, poi prosegue."
  },
  AvgDialog_19170_Content_2 = {
    Text = "Tre giorni dopo. Università di Mythag"
  },
  AvgDialog_19170_Content_20 = {
    Text = "Quanto alla causa dell'anemia... la nostra ipotesi attuale è che sia stato prelevato troppo sangue durante i tre giorni di esami."
  },
  AvgDialog_19170_Content_21 = {
    Text = "Davvero? Ma io..."
  },
  AvgDialog_19170_Content_22 = {
    Text = "Stando ai rapporti di Ramona e degli altri, le ferite che hai riportato sulla nave avrebbero ucciso una persona comune nove volte. Nemmeno un mostro con nove vite avrebbe potuto resistere."
  },
  AvgDialog_19170_Content_23 = {
    Text = "Comincio a sospettare che tu abbia sangue di troll nelle vene."
  },
  AvgDialog_19170_Content_24 = {
    Text = "Hai il cuore in gola, e la tensione tiene ogni muscolo del tuo corpo serrato come una corda di violino."
  },
  AvgDialog_19170_Content_25 = {
    Text = "Scherzo, non esistono troll in questo mondo, almeno non nel reame conosciuto dagli esseri umani."
  },
  AvgDialog_19170_Content_26 = {
    Text = "I tuoi arresti domiciliari sono stati revocati. Se vuoi parlare con i compagni che hanno affrontato la vita e la morte sulla Sona-Nyl, sono nel cortile della scuola a dare l'addio al capitano."
  },
  AvgDialog_19170_Content_27 = {Text = "Addio?!"},
  AvgDialog_19170_Content_28 = {
    Text = "Sì, sebbene l'Università di Mythag non manchi certo di luoghi dove alloggiare, Elton chiaramente non voleva restare in un solo posto."
  },
  AvgDialog_19170_Content_29 = {
    Text = "Afferri in fretta il cappotto e fai un cenno a Doll mentre ti alzi dal letto. Ma proprio quando stai per lasciare il dormitorio, Doll ti ferma."
  },
  AvgDialog_19170_Content_3 = {
    Text = "Ti sei alzato presto oggi. Perché quell'aria preoccupata? Sembri William quando fai quell'espressione."
  },
  AvgDialog_19170_Content_30 = {
    Text = "...Sono felice che tu sia tornato sano e salvo."
  },
  AvgDialog_19170_Content_31 = {
    Text = "Bene, vai ora. Ti stanno aspettando."
  },
  AvgDialog_19170_Content_32 = {
    Text = "Custode, siamo qui."
  },
  AvgDialog_19170_Content_33 = {
    Text = "Tutti si trovano nel cortile della scuola. Dopo tre giorni, lo stato di tutti sembra essersi ripreso notevolmente."
  },
  AvgDialog_19170_Content_34 = {
    Text = "—Tranne Celeste. Rimane semi-trasparente, come un bellissimo fantasma che potrebbe essere spazzato via da una brezza."
  },
  AvgDialog_19170_Content_35 = {
    Text = "Dopo aver sconfitto il Feto Divino e lo smontaggio della Sona-Nyl, un familiare vento bianco ti avvolse. Celeste eseguì un teletrasporto a lunga distanza, riportando tutti sulla terraferma."
  },
  AvgDialog_19170_Content_36 = {
    Text = "Come conseguenza, lo spirito del Capitano Elton subì gravi danni. Anche dopo aver ricevuto cure presso l'Università di Mythag, il legame con Celeste non può essere ripristinato."
  },
  AvgDialog_19170_Content_37 = {
    Text = "Quel giovane ricercatore ti ha finalmente lasciato uscire. Temevo di non rivederti prima della mia partenza, e la cosa mi angustiava non poco."
  },
  AvgDialog_19170_Content_38 = {
    Text = "Capitano..."
  },
  AvgDialog_19170_Content_39 = {
    Text = "Per farla breve."
  },
  AvgDialog_19170_Content_4 = {
    Text = "Sto ancora pensando a ciò che è accaduto in mare... quei Navigatori, quel \"Falso Dio\" dissolto in polvere sopra l'oceano..."
  },
  AvgDialog_19170_Content_40 = {
    Text = "Il capitano si avvicina a te e fa un cenno a Celeste, il cui corpo è trasparente al punto da essere a malapena visibile."
  },
  AvgDialog_19170_Content_41 = {
    Text = "È perplessa quanto te, ma si avvicina silenziosamente al tuo fianco—"
  },
  AvgDialog_19170_Content_42 = {
    Text = "Dammi la mano."
  },
  AvgDialog_19170_Content_43 = {
    Text = "Tendi la mano."
  },
  AvgDialog_19170_Content_44 = {
    Text = "Elton solleva delicatamente la sua mano traslucida e la posa sul tuo palmo teso."
  },
  AvgDialog_19170_Content_45 = {
    Text = "A qualunque costo, falla restare."
  },
  AvgDialog_19170_Content_46 = {
    Text = "Ha sofferto abbastanza in vita; non c'è bisogno che continui a vivere per i miei desideri."
  },
  AvgDialog_19170_Content_47 = {
    Text = "...È anche questo il tuo desiderio?"
  },
  AvgDialog_19170_Content_48 = {
    Text = "Elton resta sbalordito dalle sue parole, ma dopo pochi secondi scoppia in una risata sincera."
  },
  AvgDialog_19170_Content_49 = {
    Text = "La prossima \"navigazione\" di Celeste è nelle tue mani."
  },
  AvgDialog_19170_Content_5 = {
    Text = "Dall'epicentro in cui il \"Falso Dio\" si è dissolto, il mondo del Dominio circostante ha subito una trasformazione drastica. Una situazione simile non si è mai verificata prima, nemmeno dopo le precedenti eradicazioni del \"Cataclisma.\""
  },
  AvgDialog_19170_Content_50 = {
    Text = "...D'accordo."
  },
  AvgDialog_19170_Content_51 = {
    Text = [[
Nel momento in cui ti colleghi con Celeste, una coscienza fragile ma potente inonda la tua mente.

Anche se sei sulla terraferma, il tuo petto avverte il soffocamento come se stessi annegando.]]
  },
  AvgDialog_19170_Content_52 = {
    Text = "La forma di Celeste non è più eterea; esiste davvero in questo mondo."
  },
  AvgDialog_19170_Content_53 = {
    Text = "Elton saluta un'ultima volta con la mano mentre lo guardi partire per un nuovo viaggio alla ricerca della sua casa perduta."
  },
  AvgDialog_19170_Content_54 = {
    Text = "A proposito, dov'è Caecus? Era quello più legato al capitano; perché non è venuto a salutarlo?"
  },
  AvgDialog_19170_Content_55 = {
    Text = "Ramona indica un albero lì vicino. Nascosto nella sua ombra c'è Caecus, lo sguardo fisso sull'auto in partenza fino a quando non scompare completamente nella periferia nebbiosa di Mythag."
  },
  AvgDialog_19170_Content_56 = {
    Text = "L'umore di Caecus non è dei migliori. La sua vita è cambiata completamente durante il tempo trascorso sulla nave. Lasciategli un po' di pace."
  },
  AvgDialog_19170_Content_57 = {
    Text = "Forse vorresti incontrare Murphy?"
  },
  AvgDialog_19170_Content_58 = {
    Text = "Università di Mythag\n\nEsterno del Dormitorio dei Risvegliatori"
  },
  AvgDialog_19170_Content_59 = {
    Text = "Murphy, sono io."
  },
  AvgDialog_19170_Content_6 = {
    Text = "Cos'è cambiato?"
  },
  AvgDialog_19170_Content_60 = {Text = "Entra."},
  AvgDialog_19170_Content_61 = {
    Text = "Il dipartimento logistico ha preparato il dormitorio più lussuoso per Murphy. Quando apri la porta, Murphy è seduta su un morbido materasso di lana, intenta a sorseggiare del tè, con il vassoio appoggiato distrattamente sul letto."
  },
  AvgDialog_19170_Content_62 = {
    Text = "Come ti... senti?"
  },
  AvgDialog_19170_Content_63 = {
    Text = "Come mi sento? Riguardo a cosa? I dessert insipidi di qui? Il fatto che alla fine abbiamo affondato i Navigatori? O che all'improvviso sono diventata una Risvegliatrice?"
  },
  AvgDialog_19170_Content_64 = {
    Text = "Io... mi dispiace. L'ho fatto senza il tuo permesso..."
  },
  AvgDialog_19170_Content_65 = {
    Text = "Stai parlando del fatto che mi hai trasformata in una Risvegliatrice?"
  },
  AvgDialog_19170_Content_66 = {
    Text = "Scusa, so che forse non è il risultato che speravi... ma io semplicemente..."
  },
  AvgDialog_19170_Content_67 = {
    Text = "Io... non volevo perderti."
  },
  AvgDialog_19170_Content_68 = {Text = "..."},
  AvgDialog_19170_Content_69 = {
    Text = "Provo un senso di sollievo."
  },
  AvgDialog_19170_Content_7 = {
    Text = "L'ambiente è più pericoloso, i mutanti sono più forti, e la nostra Tecnologia d'Argento, insieme alle abilità dei Risvegliati, sono gravemente limitate laggiù... La Squadra di Spedizione ha denominato questa situazione il <Yellow:\"D-Effetto Regionale\">."
  },
  AvgDialog_19170_Content_70 = {
    Text = "La sensazione di un cuore che non batte più è strana e terrificante. Ma..."
  },
  AvgDialog_19170_Content_71 = {
    Text = "Provo davvero un senso di liberazione senza precedenti."
  },
  AvgDialog_19170_Content_72 = {
    Text = "L'espressione di Murphy è distesa, non finta. In base a quel che sai di lei, mentire non è davvero il suo forte."
  },
  AvgDialog_19170_Content_73 = {
    Text = "Davvero? Non eri presente quando ho salutato il capitano. Pensavo..."
  },
  AvgDialog_19170_Content_74 = {
    Text = "Cosa? Pensavi che fossi nascosta sotto le coperte a piangere?"
  },
  AvgDialog_19170_Content_75 = {
    Text = "Perché dovrei essere triste? Non te l'ha detto? Ha promesso che verrà a trovare me e Caecus a ogni Festa della Brina Argentea."
  },
  AvgDialog_19170_Content_76 = {
    Text = "A dire il vero, Elton mi ha trascinata qui per il tè e mi ha fatto la predica tutta la mattina. Ha continuato a ripetere che dovrei essere libera e non lasciare che questa faccenda da Risvegliatrice mi definisca. Hmph, come se avessi bisogno che me lo dicesse lui."
  },
  AvgDialog_19170_Content_77 = {
    Text = "Comunque, vuoi assaggiare qualche dolcetto? I brownies della cucina oggi sono davvero niente male—"
  },
  AvgDialog_19170_Content_78 = {
    Text = "Ma hai appena detto che i dessert dell'università sono insipidi..."
  },
  AvgDialog_19170_Content_79 = {
    Text = "La forchetta è già alla tua bocca, e dai un morso alla torta."
  },
  AvgDialog_19170_Content_8 = {
    Text = "Buone notizie: il D-effetto regionale è attualmente localizzato; cattive notizie: non possiamo controllarne la comparsa né il movimento. È scivoloso come un pesce gatto nell'olio."
  },
  AvgDialog_19170_Content_80 = {
    Text = "I sapori aspri, dolci e amari del cioccolato si fondono insieme nella tua bocca, mentre gli oli delle noci li amalgamano alla perfezione, facendo danzare il brownie sulle tue papille gustative."
  },
  AvgDialog_19170_Content_81 = {
    Text = "Tu e Murphy ve ne state seduti accanto al letto, chiacchierando del più e del meno e finendo un tè pomeridiano con dolci per cinque persone."
  },
  AvgDialog_19170_Content_9 = {
    Text = "In ogni caso, quella zona di mare è stata designata dal Comitato come zona proibita per D-Effetto Regionale. Credo che scomparirà per sempre dalla già scarsa mappa delle risorse del Regno di Leonia."
  },
  AvgDialog_19196_Content_10 = {
    Text = [[
...Hmph.
<Small:Almeno ti ricordi ancora di Ramona...>]]
  },
  AvgDialog_19196_Content_11 = {
    Text = "Il calore di una presenza viva squarcia l'Oscurità, ma un dolore lancinante esplode dalla tua fronte, irradiandosi fino agli arti."
  },
  AvgDialog_19196_Content_12 = {
    Text = "Qualcuno ti dà un colpetto secco sulla fronte."
  },
  AvgDialog_19196_Content_13 = {Text = "Ahi!"},
  AvgDialog_19196_Content_14 = {
    Text = "Riesci ancora a sentire dolore? Allora non stai poi così male."
  },
  AvgDialog_19196_Content_15 = {
    Text = "Io... mi sono appena ricordato tutto."
  },
  AvgDialog_19196_Content_16 = {
    Text = "Ramona, Tulu, Capitano Elton, Celeste, i Navigatori, e tu con quella... cosa dentro di te..."
  },
  AvgDialog_19196_Content_17 = {
    Text = "Essere messa nello stesso mucchio di quel Mostro è già abbastanza grave, ma non potevi almeno pensare a me prima dei Navigatori?"
  },
  AvgDialog_19196_Content_18 = {
    Text = "Io... non intendevo dire quello..."
  },
  AvgDialog_19196_Content_19 = {
    Text = "Murphy sbuffa, tirandoti su da terra."
  },
  AvgDialog_19196_Content_2 = {
    Text = "Riavvio della Realtà"
  },
  AvgDialog_19196_Content_20 = {
    Text = "Sapevo che qualcosa non andava dopo quell'esplosione. Comportarti in modo così strano... alla fine ti sei davvero dato una botta in testa..."
  },
  AvgDialog_19196_Content_21 = {
    Text = "C'è solo una cosa che ancora non mi è chiara..."
  },
  AvgDialog_19196_Content_22 = {
    Text = "Quando Miryam ha provocato quell'esplosione nella sala macchine, chi ci ha tirato fuori di lì?"
  },
  AvgDialog_19196_Content_23 = {
    Text = "Dev'essere stata Celeste, no? Nessun altro su questa nave potrebbe generare quel tipo di luce bianca."
  },
  AvgDialog_19196_Content_24 = {
    Text = "L'Abbraccio del mare si fece tagliente, l'acqua reagì con la tua pelle ustionata in una lotta soffocante. Caos cieco, come uno spettro nella notte, lacerò e spezzò il tuo corpo."
  },
  AvgDialog_19196_Content_25 = {
    Text = "Poi, quel caos generò un tremolio di calore. Nell'oscurità sconfinata, solitudine, impotenza e disperazione si ritrassero rapide, un bagliore misterioso che brillava nel cosmo gelido."
  },
  AvgDialog_19196_Content_26 = {
    Text = "Come sfiorato dalla clemenza dell'universo, la tua coscienza vacillò sul confine del Reame spirituale. Il tuo corpo si fuse con l'ossigeno del mare, e spalancasti gli Occhi, sentendo l'acqua irrompere dentro di te."
  },
  AvgDialog_19196_Content_27 = {
    Text = "Infine, una luce gentile squarciò l'oscurità dell'oceano. Una forza azzurra pallida si protese verso di te — una dea dell'Uscita di Sicurezza che ti tendeva la mano."
  },
  AvgDialog_19196_Content_28 = {
    Text = "<Gray:In effetti, la forza che mi ha strappato dall'acqua era inconfondibilmente quella di Celeste.>"
  },
  AvgDialog_19196_Content_29 = {
    Text = "Chiudi gli occhi, rievocando l'istante in cui le fiamme ti bruciarono la Visuale, quando una luce calda lacerò e ricucì la tua volontà."
  },
  AvgDialog_19196_Content_3 = {
    Text = "Svegliati, %player%, forza, riprenditi!"
  },
  AvgDialog_19196_Content_30 = {
    Text = "<Gray:Ma quella forza di prima... non era di Celeste. Era troppo aliena, eppure anche familiare...>"
  },
  AvgDialog_19196_Content_31 = {
    Text = "Ehi, ti stai di nuovo incantando? Non ti ho mica colpito così forte, no? Ci sono andata piano..."
  },
  AvgDialog_19196_Content_32 = {
    Text = "Murphy borbotta, avvicinandosi in punta di piedi per scostare la frangia dai tuoi occhi. Il suo colpetto era calibrato — quanto bastava per farti tornare vigile senza lasciare dolore."
  },
  AvgDialog_19196_Content_33 = {
    Text = "È solo che mi preoccupo per gli altri... Dal fatto che ci siamo solo tu e io qui, l'esplosione dev'essere stata troppo caotica perché Celeste potesse controllare l'atterraggio di tutti."
  },
  AvgDialog_19196_Content_34 = {
    Text = "Dobbiamo trovare Ramona, poi ricongiungerci con il Capitano e gli altri."
  },
  AvgDialog_19196_Content_35 = {
    Text = "Sei sicuro di stare bene? Se ti senti strano, è meglio che lo dici subito."
  },
  AvgDialog_19196_Content_36 = {
    Text = "Sì, ti farò sapere."
  },
  AvgDialog_19196_Content_4 = {
    Text = "Non... non spaventarmi così... Alzati, su!"
  },
  AvgDialog_19196_Content_5 = {
    Text = "I singhiozzi della ragazza martellano contro i tuoi timpani, strappando la tua coscienza dal flusso torrenziale delle Memorie."
  },
  AvgDialog_19196_Content_7 = {
    Text = "I ricordi tremolano come diapositive incastrate in un proiettore malconcio.\nOgni cambio di fotogramma strappa un urlo dalle profondità della tua anima."
  },
  AvgDialog_19196_Content_8 = {
    Text = "Urgh... Ramo... na..."
  },
  AvgDialog_19196_Content_9 = {
    Text = "Questo è..."
  },
  AvgDialog_19200_Content_1 = {
    Text = "Combattere ne attira solo altri. Gioca d'astuzia, evita gli scontri."
  },
  AvgDialog_19200_Content_10 = {
    Text = "Ok, adesso siamo pari."
  },
  AvgDialog_19200_Content_11 = {
    Text = "Mi sono trattenuto. Altrimenti saresti volata dieci metri indietro."
  },
  AvgDialog_19200_Content_12 = {
    Text = "Ha! Come se potessi. Smettila di fare il pagliaccio — ti ho visto penzolare dalla presa di Miryam!"
  },
  AvgDialog_19200_Content_13 = {
    Text = "L'aria densa si dirada, la preoccupazione e la cupezza spazzate via dalla rivalità."
  },
  AvgDialog_19200_Content_14 = {
    Text = "Certo, signorina Murphy... Lady Murphy."
  },
  AvgDialog_19200_Content_15 = {
    Text = "Ehi! Mi stai prendendo in giro!"
  },
  AvgDialog_19200_Content_16 = {
    Text = "Murphy tira un pugno in alto, ma lo lascia cadere piano, sfiorandoti la camicia."
  },
  AvgDialog_19200_Content_17 = {
    Text = "Pietà, milady... ahi!"
  },
  AvgDialog_19200_Content_18 = {
    Text = "Aspetta, c'è qualcosa laggiù."
  },
  AvgDialog_19200_Content_19 = {
    Text = "Le tue orecchie captano uno strano sibilo basso, mescolato a un battito particolarmente ritmico."
  },
  AvgDialog_19200_Content_2 = {
    Text = "Murphy? Mi senti?"
  },
  AvgDialog_19200_Content_20 = {
    Text = "Quella è Ramona."
  },
  AvgDialog_19200_Content_21 = {
    Text = "Riesci a capire <Italic:questo>?"
  },
  AvgDialog_19200_Content_22 = {
    Text = "Fai un cenno a Murphy con lo sguardo. Lei annuisce a labbra strette, e vi lanciate entrambi verso il rumore."
  },
  AvgDialog_19200_Content_23 = {
    Text = [[
Tempo all'Allineamento:
90 minuti]]
  },
  AvgDialog_19200_Content_3 = {
    Text = "La bambina resta accovacciata accanto al corallo, lo sguardo perso nel vuoto, il tuo richiamo non la raggiunge."
  },
  AvgDialog_19200_Content_4 = {
    Text = "Ti accovacci accanto a lei, osservando il corallo e il suo sguardo fisso, quasi vacuo."
  },
  AvgDialog_19200_Content_5 = {
    Text = "Ripicca scherzosa o solo per divertimento..."
  },
  AvgDialog_19200_Content_6 = {
    Text = "Ti scaldi le Mani e le dai un colpetto sulla fronte..."
  },
  AvgDialog_19200_Content_7 = {Text = "Ahi!"},
  AvgDialog_19200_Content_8 = {Text = "Ehi!"},
  AvgDialog_19200_Content_9 = {
    Text = "Murphy si porta una mano alla fronte, pronta a darti ordini, ma poi si rende conto che è colpa sua e si morde la lingua."
  },
  AvgDialog_19967_Content_1 = {
    Text = "Ad essere sincero, non mi interessa prendermela con i bambini."
  },
  AvgDialog_19967_Content_2 = {
    Text = "Per essere giusti, ho con me alcuni <Yellow:preziosi oggetti da collezione>. Puoi sceglierne uno tra questi."
  },
  AvgDialog_19967_Content_3 = {
    Text = "Produrranno alcuni <Red:effetti inaspettati>. Vuoi provare?"
  },
  AvgDialog_19967_Content_4 = {
    Text = "Mi dispiace, fin da bambino i miei anziani mi hanno avvertito di non accettare cose dagli sconosciuti."
  },
  AvgDialog_19967_Content_5 = {
    Text = "Davvero? Che peccato... La tua vita ha perso un sacco di divertimento da ora in poi."
  },
  AvgDialog_19967_Content_6 = {
    Text = "Rifiutarmi potrebbe comportare una punizione severa~"
  },
  AvgDialog_19968_Content_1 = {
    Text = "Sfere di melma nera, scintillanti di una sinistra luce verde, saettano attraverso il vagone in cerca di un bersaglio."
  },
  AvgDialog_19968_Content_2 = {
    Text = "Le vetrate esplodono in agghiaccianti frammenti con un fragore che strazia i nervi."
  },
  AvgDialog_19969_Content_10 = {
    Text = [[
Il Conducente inchioda i freni, il treno sussulta fino a fermarsi.
I passeggeri nel panico balzano fuori, disperdendosi in ogni direzione.]]
  },
  AvgDialog_19969_Content_11 = {
    Text = "Emergenza — proteggere i civili!\nBambola, Bambola, mi senti?"
  },
  AvgDialog_19969_Content_12 = {
    Text = "Rilevamento... Interferenza nelle comunicazioni... fluttuazioni della Chiave d'Argento... possibile... zzzt... Risonanza..."
  },
  AvgDialog_19969_Content_13 = {
    Text = "Com'è quel detto? L'acqua lontana non spegne il fuoco vicino."
  },
  AvgDialog_19969_Content_2 = {
    Text = "C-Cos'è quella cosa?!"
  },
  AvgDialog_19969_Content_3 = {
    Text = "Sui binari più avanti, nell'Oscurità del Tunnel, una figura si staglia illuminata dai fari — una sagoma impossibile."
  },
  AvgDialog_19969_Content_4 = {
    Text = "Una Donna alta, il suo sguardo affilato come lame, affronta con calma il treno in arrivo."
  },
  AvgDialog_19969_Content_5 = {
    Text = "Ti ho trovato."
  },
  AvgDialog_19969_Content_6 = {
    Text = "In un istante fugace, la Donna svanisce—"
  },
  AvgDialog_19969_Content_8 = {
    Text = "No, non svanisce: sta caricando verso il treno in corsa!"
  },
  AvgDialog_19970_Content_1 = {
    Text = [[
Il mostro impazzito ulula di furia angosciata.
Le fiamme cremisi vendicative sprigionano le ultime scintille, poi si spengono a malincuore.]]
  },
  AvgDialog_19970_Content_10 = {Text = "..."},
  AvgDialog_19970_Content_11 = {
    Text = [[
Il mostro nero si contorce, stridendo, per poi crollare esausto in un angolo in rovina.
Si sforza di tenere gli occhi aperti, il loro sguardo vacuo intravede un caos debole e biancastro.]]
  },
  AvgDialog_19970_Content_12 = {
    Text = "L'orizzonte rivela un'alba fioca.\nMa non la riguarda più."
  },
  AvgDialog_19970_Content_13 = {
    Text = "<Shake:Perché... mi avete... abbandonato...>"
  },
  AvgDialog_19970_Content_14 = {
    Text = "Di chi è questa bambina... Nemmeno tu riesci a trovare il tuo padrone?"
  },
  AvgDialog_19970_Content_15 = {
    Text = "<Shake:Aiuto... aiuto...>"
  },
  AvgDialog_19970_Content_16 = {
    Text = "Sei ferito gravemente."
  },
  AvgDialog_19970_Content_17 = {
    Text = "Mi dispiace, non posso essere il tuo padrone.\nHo già Lily."
  },
  AvgDialog_19970_Content_18 = {Text = "Ma..."},
  AvgDialog_19970_Content_19 = {
    Text = "<Yellow:Se ti serve solo un connettore, ce ne sono in abbondanza qui, non è vero?>"
  },
  AvgDialog_19970_Content_2 = {
    Text = "Ramona solleva il suo stocco, preparando un ultimo addio alla creatura un tempo chiamata Helot."
  },
  AvgDialog_19970_Content_4 = {Text = "Lotan?!"},
  AvgDialog_19970_Content_5 = {
    Text = "La lama di Lotan blocca lo stocco che cala dall'alto."
  },
  AvgDialog_19970_Content_6 = {
    Text = "Lasciala marcire da sola.\nUn Risvegliatore senza un legame non sopravviverà ventiquattro ore in questo mondo."
  },
  AvgDialog_19970_Content_7 = {
    Text = "Nelle sue condizioni, non arriverà all'alba."
  },
  AvgDialog_19970_Content_8 = {
    Text = "Non può più fare del male a nessuno.\nLascia che incontri la morte in silenzio."
  },
  AvgDialog_19970_Content_9 = {Text = "..."},
  AvgDialog_19971_Content_1 = {
    Text = "Quella voce sta dicendo qualcosa?"
  },
  AvgDialog_19971_Content_2 = {
    Text = "Mi è parso di sentire qualcosa come... \"abbandonare\"..."
  },
  AvgDialog_19971_Content_3 = {
    Text = "Un mostro del genere vicino al sanatorio..."
  },
  AvgDialog_19971_Content_4 = {
    Text = "Francis nasconde più segreti di quanto pensassimo."
  },
  AvgDialog_19971_Content_5 = {
    Text = "In ogni caso, dovremo attraversare questo ponte per scoprirlo."
  },
  AvgDialog_19972_Content_1 = {
    Text = "Attraversi la dimensione, il suono dell'acqua che gocciola aggira le tue orecchie, risuonando direttamente nella tua mente."
  },
  AvgDialog_19972_Content_2 = {
    Text = "Un ribollire caotico si gonfia nel tuo petto, sforzandosi di esplodere."
  },
  AvgDialog_19972_Content_3 = {
    Text = "Inconsciamente, trattieni il respiro."
  },
  AvgDialog_19973_Content_1 = {Text = "..."},
  AvgDialog_19973_Content_10 = {
    Text = "Non fai parte dell'Associazione degli Scultori. Perché lavori per loro?"
  },
  AvgDialog_19973_Content_11 = {
    Text = "Oh? Come fai a sapere che non lo sono?"
  },
  AvgDialog_19973_Content_12 = {
    Text = "Quegli \"artisti\" con i loro coltelli da intaglio non sono audaci quanto te."
  },
  AvgDialog_19973_Content_13 = {
    Text = "Chi sei, e perché la vuoi?"
  },
  AvgDialog_19973_Content_14 = {
    Text = "<Blue:Helot>. Se mi chiedi il mio ruolo, sono qualcosa come sua sorella.\nPiù precisamente, i nostri poteri sono <Yellow:\"della stessa origine\">."
  },
  AvgDialog_19973_Content_15 = {
    Text = "Deve fare ritorno al fianco del suo <Yellow:padrone>, quindi sono qui per prenderla."
  },
  AvgDialog_19973_Content_16 = {
    Text = "Ramona annuisce, poi accarezza dolcemente la testa di Lily."
  },
  AvgDialog_19973_Content_17 = {
    Text = "Lily, vuoi andare con lei?"
  },
  AvgDialog_19973_Content_18 = {
    Text = "Lily alza lo sguardo con terrore, i suoi occhi guizzano tra Helot e Ramona, poi si posano su di te, implorando aiuto."
  },
  AvgDialog_19973_Content_19 = {
    Text = "Incoraggiala"
  },
  AvgDialog_19973_Content_2 = {
    Text = "Uno spuntone affilato come un rasoio fende l'aria, puntato verso di te."
  },
  AvgDialog_19973_Content_20 = {
    Text = "Va tutto bene, di' quello che senti davvero."
  },
  AvgDialog_19973_Content_21 = {
    Text = [[
La presa di Lily si stringe.
Poi, lentamente ma con fermezza, scuote la testa.]]
  },
  AvgDialog_19973_Content_22 = {
    Text = "Hai visto? Non vuole tornare da nessun \"padrone.\""
  },
  AvgDialog_19973_Content_23 = {
    Text = "Helot alza una mano, una raffica feroce le turbina attorno, pronta a scatenare una tempesta."
  },
  AvgDialog_19973_Content_24 = {
    Text = "Non spetta a lei decidere."
  },
  AvgDialog_19973_Content_25 = {
    Text = "Allora fatti avanti!"
  },
  AvgDialog_19973_Content_4 = {
    Text = "Prima che tu possa chiamare Ramona, il nitido clangore di lame risuona nell'aria."
  },
  AvgDialog_19973_Content_5 = {
    Text = [[
Lotan si erge fieramente davanti a te, affrontando il nemico senza paura.
Una ciocca di capelli le scivola dalla fronte.]]
  },
  AvgDialog_19973_Content_6 = {
    Text = "Hmph, niente male."
  },
  AvgDialog_19973_Content_7 = {
    Text = "Non sei il mio bersaglio. Fatti da parte."
  },
  AvgDialog_19973_Content_8 = {
    Text = "Non se ne parla. È da un'eternità che non sgranchisco le membra — che ne dici di fare a pugni con me?"
  },
  AvgDialog_19973_Content_9 = {Text = "..."},
  AvgDialog_19974_Content_1 = {Text = "..."},
  AvgDialog_19974_Content_2 = {
    Text = "L'inquietante figura velata svanisce ai margini della tua visuale. La insegui, ma invano."
  },
  AvgDialog_19974_Content_3 = {
    Text = "Queste persone sono..."
  },
  AvgDialog_19974_Content_4 = {
    Text = "Doll sta tracciando le loro origini, ma non abbiamo ancora piste concrete."
  },
  AvgDialog_19974_Content_5 = {
    Text = "Questi tizi sono piuttosto interessanti. Giocare a fare la casa con i ragazzini non è poi così male, ogni tanto."
  },
  AvgDialog_19974_Content_6 = {
    Text = "Il Focolare è... oltre il <Blue:Ponte d'Acciaio Fowlers>."
  },
  AvgDialog_19974_Content_7 = {Text = "Andiamo."},
  AvgDialog_19975_Content_1 = {
    Text = "Quelle creature sono randagi persi nel Passaggio dimensionale, o sottoprodotti dell'Erosione da Dissoluzione."
  },
  AvgDialog_19975_Content_2 = {
    Text = "Viaggiare sconsideratamente tra le Dimensioni è come immergersi a diecimila metri sott'acqua senza equipaggiamento, o scalare le vette ghiacciate di Elworth con addosso solo una camicia."
  },
  AvgDialog_19975_Content_3 = {
    Text = "La maggior parte non riesce a sopportare lo sforzo del viaggio dimensionale."
  },
  AvgDialog_19975_Content_4 = {
    Text = "Lungi dal tendere trappole, Lady Daffodil ha scelto un Passaggio con una pressione sopportabile—"
  },
  AvgDialog_19975_Content_5 = {
    Text = "Ci sta... invitando?"
  },
  AvgDialog_19975_Content_6 = {
    Text = "L'uscita è davanti a noi. Rivedremo presto Lady Daffodil.\nAllora potremo avere delle risposte."
  },
  AvgDialog_19976_Content_1 = {
    Text = "È qui.\nIl Segugio infernale che attendevi apre le sue pupille cremisi e oro alle tue spalle."
  },
  AvgDialog_19976_Content_2 = {
    Text = [[
Il suo sguardo trafigge da un'altezza irraggiungibile,
affilato e minaccioso, squarcia lo spazio come una lama.]]
  },
  AvgDialog_19976_Content_3 = {
    Text = "Non puoi combattere — puoi solo fuggire."
  },
  AvgDialog_19977_Content_1 = {
    Text = "La città innevata giace silenziosa, la neve soffice riflette il freddo chiaro di luna."
  },
  AvgDialog_19977_Content_10 = {
    Text = "Ora è il momento!"
  },
  AvgDialog_19977_Content_11 = {
    Text = "La creatura nera e umbratile, spaventata, scatta in fuga ma resta impigliata nella trappola, incapace di muoversi."
  },
  AvgDialog_19977_Content_12 = {
    Text = "Il mostro abbassa la testa, ringhiando sommessamente come per avvertirvi di stare indietro."
  },
  AvgDialog_19977_Content_13 = {
    Text = "Riesci a distinguerlo?"
  },
  AvgDialog_19977_Content_14 = {
    Text = "No, è come se... non avesse volto."
  },
  AvgDialog_19977_Content_15 = {
    Text = "Al centro della testa abbassata del mostro, distingui vagamente un profilo simile a quello umano, ma dove dovrebbero esserci i lineamenti, un vuoto nero inghiotte ogni luce."
  },
  AvgDialog_19977_Content_16 = {
    Text = "Tienilo fermo, Lotan! Io prendo la sinistra, tu prendi la destra!"
  },
  AvgDialog_19977_Content_17 = {
    Text = "Un Gioco da Ragazzi!"
  },
  AvgDialog_19977_Content_2 = {
    Text = "Voi tre vi rannicchiate dietro una staccionata rotta, avvolti nella notte profonda, lanciando di tanto in tanto occhiate alle spalle."
  },
  AvgDialog_19977_Content_3 = {
    Text = "Ehi, quest'imboscata funzionerà davvero? Con appena qualche gallina?"
  },
  AvgDialog_19977_Content_4 = {
    Text = "Aspettiamo e vediamo. Cerca di trattenerti e non lanciarti alla carica."
  },
  AvgDialog_19977_Content_5 = {
    Text = "Hmph, spreco del mio tempo."
  },
  AvgDialog_19977_Content_6 = {
    Text = "Shh, qualcosa si avvicina."
  },
  AvgDialog_19977_Content_7 = {
    Text = "Una zampa canina emerge dalle ombre, accompagnata da un respiro pesante."
  },
  AvgDialog_19977_Content_8 = {
    Text = "Un passo, due passi."
  },
  AvgDialog_19977_Content_9 = {
    Text = "Si lancia, rapido come il tuono."
  },
  AvgDialog_19978_Content_1 = {Text = "..."},
  AvgDialog_19978_Content_10 = {
    Text = "Le prime segnalazioni del Segugio infernale risalgono a <Blue:dieci giorni> fa. Padroneggiare questi sentieri aggrovigliati in dieci giorni non è cosa facile."
  },
  AvgDialog_19978_Content_11 = {Text = "E adesso?"},
  AvgDialog_19978_Content_12 = {
    Text = "Ramona si volta. Seguendo il suo sguardo, scorgi gocce sparse di un liquido nero-rossastro lungo la traiettoria."
  },
  AvgDialog_19978_Content_13 = {
    Text = "La perdita di sangue di solito prosciuga le forze — dovrà uscire allo scoperto per nutrirsi di nuovo. Dobbiamo solo farci trovare pronti."
  },
  AvgDialog_19978_Content_14 = {
    Text = "Lotan fa scattare la spada con un ghigno."
  },
  AvgDialog_19978_Content_15 = {
    Text = "Ancora meglio. Se è vivo, può essere catturato, ucciso...\nIncontrando me, sarebbe più felice da morto che da vivo."
  },
  AvgDialog_19978_Content_16 = {
    Text = "Andiamo. Dobbiamo essere pronti prima del buio."
  },
  AvgDialog_19978_Content_2 = {Text = "..."},
  AvgDialog_19978_Content_3 = {
    Text = "Insegui la creatura nera attraverso diversi incroci, per poi perderne la traiettoria dopo che si è infilata in un vicolo stretto."
  },
  AvgDialog_19978_Content_4 = {
    Text = "Dannazione, dov'è finito? Quella cosa è sfuggente come un topo di fogna!"
  },
  AvgDialog_19978_Content_5 = {
    Text = "Questo dovrebbe essere un vicolo cieco. Non avrebbe dovuto fuggire, a meno che—"
  },
  AvgDialog_19978_Content_6 = {
    Text = "Qualcuno l'ha aiutato? O... invisibilità?! Lotan, resta all'erta!"
  },
  AvgDialog_19978_Content_7 = {Text = "..."},
  AvgDialog_19978_Content_8 = {
    Text = "...Entrambi sono colpi di scena notevoli, ma la ragione è probabilmente più semplice. Questo vicolo ha con ogni probabilità <Blue:passaggi nascosti o biforcazioni> assenti dalle mappe ordinarie."
  },
  AvgDialog_19978_Content_9 = {
    Text = "Questa città è anteriore al Diluvio, prosperava grazie all'allevamento e alla ceramica. Le sue fognature e i suoi vicoli formano una rete intricata che nessuna mappa può cogliere appieno."
  },
  AvgDialog_19979_Content_1 = {
    Text = "Non osi alzare lo sguardo, non puoi voltarti indietro."
  },
  AvgDialog_19979_Content_2 = {
    Text = "Anche solo guardare l'ombra che potrebbe proiettare al suolo ti fa rabbrividire."
  },
  AvgDialog_19979_Content_3 = {
    Text = "In questa dimensione cupa, ti manca la forza per resistere."
  },
  AvgDialog_19980_Content_10 = {
    Text = "Patetica. Basta perdere un Legame d'Argento per ridursi così."
  },
  AvgDialog_19980_Content_11 = {
    Text = "Il Mostro coperto di pustole ignora gli Scherni di Lotan, ruggendo e caricando i suoi nemici."
  },
  AvgDialog_19980_Content_12 = {
    Text = "<Change>Dammela... a... me..."
  },
  AvgDialog_19980_Content_13 = {
    Text = "Se riuscisse ad afferrare quella Bambina... e diventare con lei una coppia di Divi Gemelli..."
  },
  AvgDialog_19980_Content_14 = {
    Text = "Non sarà abbandonata, non piangerà le sue origini, non sarà una pedina al servizio altrui."
  },
  AvgDialog_19980_Content_17 = {
    Text = "<Change>Consegnala... a... me!"
  },
  AvgDialog_19980_Content_18 = {
    Text = "Hai perso persino la capacità di parlare?"
  },
  AvgDialog_19980_Content_19 = {
    Text = [[
Allora lascia che la tua lama porti le tue parole, la tua rabbia.
Mostrami il tuo furore!]]
  },
  AvgDialog_19980_Content_2 = {
    Text = "<BigShake:ROAR—>"
  },
  AvgDialog_19980_Content_3 = {
    Text = "Poco dopo esservi addentrati nel buio, un Mostro viscoso striscia da sotto il ponte, la sua forma massiccia trascinando innumerevoli sfere di melma, e si schianta davanti a voi."
  },
  AvgDialog_19980_Content_4 = {
    Text = "La creatura solleva la sua metà superiore vagamente Umanoide, scrutandovi, il suo Sguardo che indugia su Lily, sempre più frenetico."
  },
  AvgDialog_19980_Content_6 = {
    Text = "Dammela... a me!"
  },
  AvgDialog_19980_Content_7 = {
    Text = "Lotan avanza, affrontando gli Occhi del Mostro con altera sfida."
  },
  AvgDialog_19980_Content_8 = {
    Text = "Le catene si spezzano, gli arti si gonfiano e si deformano, ma il volto lurido sotto i capelli aggrovigliati e incrostati tradisce ancora l'identità della sua proprietaria."
  },
  AvgDialog_19980_Content_9 = {
    Text = "Tu sei... Helot..."
  },
  AvgDialog_19981_Content_1 = {
    Text = "Una figura simile a un turbine si avvicina, l'aria densa del presagio di una battaglia imminente."
  },
  AvgDialog_19981_Content_2 = {
    Text = "Lotan stringe l'elsa della Spada, pronta a combattere."
  },
  AvgDialog_19981_Content_3 = {
    Text = "Lily, la conosci?"
  },
  AvgDialog_19981_Content_4 = {
    Text = "Lily si aggrappa stretta al tuo lembo, indietreggia, scuote la testa, poi annuisce."
  },
  AvgDialog_19981_Content_5 = {
    Text = "Lily sa... è qui per Lily."
  },
  AvgDialog_19982_Content_1 = {
    Text = "Ho un brutto presentimento... Questa volta potremmo perderlo."
  },
  AvgDialog_19982_Content_2 = {
    Text = "Quando si tratta di nascondino, Lotan non è all'altezza di quell'inafferrabile Segugio infernale."
  },
  AvgDialog_19983_Content_1 = {
    Text = "Lotan! Aspetta! Inseguirlo così non funzionerà."
  },
  AvgDialog_19983_Content_2 = {
    Text = "Hai un piano migliore?"
  },
  AvgDialog_19983_Content_3 = {
    Text = "Dividiamoci e intrapponiamolo nel vicolo più avanti!"
  },
  AvgDialog_19984_Content_1 = {Text = "Fatto!"},
  AvgDialog_19984_Content_10 = {
    Text = "La bestia grottesca ora abbassa docilmente la testa, come in attesa del tocco della bambina bianca."
  },
  AvgDialog_19984_Content_11 = {
    Text = "Sul collo del gigantesco canide siede, inconfondibilmente, una testa umana coronata, rendendo la scena profondamente inquietante."
  },
  AvgDialog_19984_Content_12 = {Text = "Lily..."},
  AvgDialog_19984_Content_13 = {
    Text = "La bambina bianca si avvicina lentamente alla bestia grottesca, protendendo un braccio esile per accarezzarle il capo come se stesse coccolando un animale qualunque."
  },
  AvgDialog_19984_Content_14 = {
    Text = "Sul collo del gigantesco canide siede, inconfondibilmente, una testa umana coronata, rendendo la scena profondamente inquietante."
  },
  AvgDialog_19984_Content_15 = {Text = "..."},
  AvgDialog_19984_Content_16 = {
    Text = "Tu e Ramona vi scambiate uno sguardo, mille parole nel cuore, eppure incerti su come cominciare."
  },
  AvgDialog_19984_Content_17 = {
    Text = "Ehi, non starete lì a fissare e basta, vero? Il Segugio infernale è proprio qui."
  },
  AvgDialog_19984_Content_18 = {
    Text = "La mente dietro a tutto è proprio accanto a noi. Come si dice? \"Nessuno sforzo, tutta ricompensa\"?"
  },
  AvgDialog_19984_Content_19 = {
    Text = "La bambina, come sorda a Lotan, sussurra nell'orecchio di Koum, la sua voce delicata portata dalla brezza serale."
  },
  AvgDialog_19984_Content_2 = {
    Text = "Ramona balza in avanti. Il mostro messo alle strette ruggisce ferocemente, dibattendosi in un'ultima resistenza."
  },
  AvgDialog_19984_Content_20 = {
    Text = "Koum, fai il bravo. Obbedisci agli ordini della tua padrona.\nSolo chi obbedisce è un bravo bambino."
  },
  AvgDialog_19984_Content_21 = {
    Text = "Le sue parole cadono lievi. Lily si volta e cammina verso di voi."
  },
  AvgDialog_19984_Content_22 = {
    Text = "Lady Daffodil ha detto che se Koum viene trovato, Lily deve tornare al fianco della <Blue:Madre>."
  },
  AvgDialog_19984_Content_23 = {
    Text = "Torniamo al negozio. Lady Daffodil potrebbe avere qualcosa da dire."
  },
  AvgDialog_19984_Content_24 = {
    Text = "Il viaggio è silenzioso.\nDaffodil, con una pipa in mano, è adagiata con disinvoltura su un'alta sedia di legno, come se attendesse il vostro arrivo."
  },
  AvgDialog_19984_Content_25 = {
    Text = "Te l'avevo detto, un cane grande non può nascondersi tra le persone.\nLily, non hai dimenticato la nostra <Yellow:punizione>, vero?"
  },
  AvgDialog_19984_Content_26 = {
    Text = "Sì, Lily ricorda."
  },
  AvgDialog_19984_Content_27 = {
    Text = "Basta con gli enigmi. Parlate — che storia ha questo Segugio infernale?"
  },
  AvgDialog_19984_Content_28 = {
    Text = "Pazienza, miei cari ospiti.\nVi spiegherò a tempo debito."
  },
  AvgDialog_19984_Content_29 = {
    Text = "O preferireste riprendervi Koum, chiudere il caso e farla finita?"
  },
  AvgDialog_19984_Content_3 = {
    Text = "<Italic:No, no! Koum, torna indietro!>"
  },
  AvgDialog_19984_Content_30 = {
    Text = "Koum non è il vero Segugio infernale."
  },
  AvgDialog_19984_Content_31 = {
    Text = "Daffodil accenna un sorriso di approvazione."
  },
  AvgDialog_19984_Content_32 = {
    Text = "Affascinante. Qual è la tua teoria?"
  },
  AvgDialog_19984_Content_33 = {
    Text = "Tre incidenti hanno colpito Rye: <Yellow:attacchi al bestiame>, <Yellow:la scomparsa di Lisa> e <Yellow:voci sul Segugio infernale>."
  },
  AvgDialog_19984_Content_34 = {
    Text = "Il bestiame dilaniato sembrava devastato da una bestia... ma i segni sui corpi sono <Yellow:morsi umani>."
  },
  AvgDialog_19984_Content_35 = {
    Text = "Ora che abbiamo catturato Koum, un rapido confronto dei segni di morso dovrebbe confermare—\n<Yellow:è il colpevole degli attacchi al bestiame>."
  },
  AvgDialog_19984_Content_36 = {
    Text = "Ma <Yellow:il Segugio infernale non c'entra nulla>.\nA Koum manca quell'aura opprimente... quella malvagità proveniente da oltre le Dimensioni."
  },
  AvgDialog_19984_Content_37 = {
    Text = "Il fucile di un abitante del villaggio gli ha inflitto ferite inguaribili, e Lotan l'ha abbattuto da solo. Non è abbastanza forte da essere l'ombra che incombe su questa città."
  },
  AvgDialog_19984_Content_38 = {
    Text = "Quindi sospetto che <Yellow:in questa città ci siano due Segugi infernali>."
  },
  AvgDialog_19984_Content_39 = {
    Text = "Un'ipotesi intrigante. Altro?"
  },
  AvgDialog_19984_Content_4 = {
    Text = "Quella voce... mi suona familiare."
  },
  AvgDialog_19984_Content_40 = {
    Text = "I segni di morsi umani sugli uccelli, combinati con l'attività dell'Associazione degli Scultori qui... sospetto che Koum sia un prodotto delle loro modifiche."
  },
  AvgDialog_19984_Content_41 = {
    Text = "La domanda che resta è: chi è la vittima in questa tragedia?"
  },
  AvgDialog_19984_Content_42 = {
    Text = "Mentre inseguivamo Koum, abbiamo notato che è intelligente e conosce intimamente i sentieri labirintici di Rye... il che suggerisce che abbia vissuto qui come essere umano per qualche tempo."
  },
  AvgDialog_19984_Content_43 = {
    Text = "La casa di Lisa si trova nel centro della città. Per una bestia o un ladro, prendere di mira le case vicino al bosco sarebbe più naturale — eppure aveva un motivo per nutrirsi qui."
  },
  AvgDialog_19984_Content_44 = {
    Text = "Ho corso un rischio. Ho scommesso che il \"Segugio infernale\" avesse scelto la casa di Lisa perché aveva per lui un significato speciale."
  },
  AvgDialog_19984_Content_45 = {
    Text = "Così abbiamo piazzato un'esca sulla soglia di Lisa, e il mio presentimento è stato confermato."
  },
  AvgDialog_19984_Content_46 = {
    Text = "Unendo questo all'affermazione di Lily secondo cui \"Lisa non tornerà,\" sospetto che Lisa non possa più affrontare sua madre — forse perché è stata <Red:trasformata> fino a diventare irriconoscibile."
  },
  AvgDialog_19984_Content_47 = {
    Text = "Mettendo tutto insieme, la vera identità di questo \"Segugio infernale\" diventa chiara—\n<Yellow:Koum è Lisa>."
  },
  AvgDialog_19984_Content_48 = {
    Text = "Per verificarlo, ho piazzato un'esca sulla soglia di Lisa e sono riuscita a \"catturarlo\" con successo."
  },
  AvgDialog_19984_Content_49 = {
    Text = "Koum, accucciato lì vicino, emette un basso guaito.\nLily accarezza la testa di Koum... di Lisa, come per consolarla."
  },
  AvgDialog_19984_Content_5 = {
    Text = "Una piccola figura tremante emerge dalla penombra del lampione spento."
  },
  AvgDialog_19984_Content_50 = {
    Text = "Lisa era una bambina così buona. Anche affamata, voleva solo \"mangiare\" a casa."
  },
  AvgDialog_19984_Content_51 = {
    Text = "Sei sveglia, ragazza. Non mi stupisce che il Professor Dexter tessa le tue lodi."
  },
  AvgDialog_19984_Content_52 = {
    Text = "Grazie, ma il professore mi ha anche parlato delle vostre \"gesta illustri,\" Lady Daffodil."
  },
  AvgDialog_19984_Content_53 = {
    Text = "Semplici affari ordinari, non meritano nemmeno di essere menzionati."
  },
  AvgDialog_19984_Content_54 = {
    Text = "Le tue deduzioni sono impeccabili. Koum è davvero \"Lisa,\" e i responsabili della sua disumana trasformazione sono, come sai, vecchie conoscenze tue."
  },
  AvgDialog_19984_Content_55 = {
    Text = "Preferirei non avere conoscenze del genere."
  },
  AvgDialog_19984_Content_56 = {
    Text = "Anche senza il vostro suggerimento, queste suture puntano dritte all'Associazione degli Scultori."
  },
  AvgDialog_19984_Content_57 = {
    Text = "...L'Associazione degli Scultori."
  },
  AvgDialog_19984_Content_58 = {
    Text = "Quei folli che si fanno chiamare <Yellow:Pigmalione>, ronzano intorno come mosche fastidiose. Insetti irritanti."
  },
  AvgDialog_19984_Content_59 = {
    Text = [[
Ben detto. Ora veniamo al punto.
Con la vostra rete di informazioni, avrete sicuramente notato la recente frenesia de Gli scultori.]]
  },
  AvgDialog_19984_Content_6 = {
    Text = "Koum, non far loro del male."
  },
  AvgDialog_19984_Content_60 = {
    Text = "La loro frenesia deriva dal fatto che il loro leader, Herbert, ha recentemente acquisito <Red:documenti classificati>."
  },
  AvgDialog_19984_Content_61 = {
    Text = "Non rivelerò il contenuto, ma posso confermare che hanno acceso le sue fantasie più sfrenate."
  },
  AvgDialog_19984_Content_62 = {
    Text = "Ora sta portando avanti i suoi esperimenti a qualunque costo."
  },
  AvgDialog_19984_Content_63 = {
    Text = "Qual è il suo obiettivo?"
  },
  AvgDialog_19984_Content_64 = {
    Text = "Questo è tutto ciò che condividerò.\nDopotutto, non sono la vostra <Yellow:unica cliente>, vero?"
  },
  AvgDialog_19984_Content_65 = {
    Text = "Daffodil batte la pipa, un sorriso malizioso che le gioca sulle labbra."
  },
  AvgDialog_19984_Content_66 = {
    Text = "Molto bene, altre due domande, se posso."
  },
  AvgDialog_19984_Content_67 = {
    Text = "A proposito dell'altro \"Segugio infernale\"... cosa sai?"
  },
  AvgDialog_19984_Content_68 = {
    Text = "O forse non siete in città da abbastanza tempo per conoscerne i segreti?"
  },
  AvgDialog_19984_Content_69 = {
    Text = "Oh, l'hai notato, vero?"
  },
  AvgDialog_19984_Content_7 = {
    Text = "Il grosso canide chiamato \"Koum\" siede a terra, leccandosi docilmente la zampa."
  },
  AvgDialog_19984_Content_70 = {
    Text = "Non posso raccontarvi l'intera storia di quel Segugio infernale, ma non sono del tutto all'oscuro."
  },
  AvgDialog_19984_Content_71 = {
    Text = "Tuttavia, in questa Borsa di Scambio, le risposte non sono gratuite."
  },
  AvgDialog_19984_Content_72 = {Text = "Cosa vuoi?"},
  AvgDialog_19984_Content_73 = {
    Text = "Hmm, fammi pensare..."
  },
  AvgDialog_19984_Content_74 = {
    Text = "Lo sguardo di Daffodil vi passa in rassegna — voi, Ramona e Lotan — poi si sofferma su Lily."
  },
  AvgDialog_19984_Content_75 = {
    Text = "Poi accenna un sorriso enigmatico."
  },
  AvgDialog_19984_Content_76 = {
    Text = "Dato che mi avete offerto uno spettacolo così splendido, vi proporrò uno sconto allettante."
  },
  AvgDialog_19984_Content_77 = {
    Text = "Orsù, la vostra \"risposta\" e il suo \"prezzo\"... sono arrivati."
  },
  AvgDialog_19984_Content_8 = {Text = "Koum..."},
  AvgDialog_19984_Content_9 = {
    Text = "Solo ora noti che quel volto nero come la pece non è privo di tratti. Occhi chiusi, narici piatte e labbra appena visibili, tutto di un nero assoluto, creano l'illusione di un vuoto."
  },
  AvgDialog_20082_Content_1 = {
    Text = "Uff... Cosa sta succedendo... La difficoltà della scalata è aumentata notevolmente rispetto a prima. Non è mai stata così... così dura!"
  },
  AvgDialog_20082_Content_2 = {
    Text = "La montagna di neve inizia a risvegliarsi e il terreno cambia continuamente. Tienimi la mano—"
  },
  AvgDialog_20082_Content_3 = {
    Text = "Afferri la mano di Helot e ti arrampichi a fatica fuori dalla fessura nella roccia, solo per vedere Lily che ti apre le braccia."
  },
  AvgDialog_20082_Content_4 = {
    Text = "Lily, fa male... Dammi un abbraccio, passerà presto."
  },
  AvgDialog_20082_Content_5 = {
    Text = "L'hai presa in braccio come richiesto. Lily è stata brava per tutto il tragitto, ma ora il suo stato sembra un po' strano..."
  },
  AvgDialog_20082_Content_6 = {
    Text = "Lily, resisti ancora un po', sarà tutto finito presto..."
  },
  AvgDialog_20082_Content_7 = {
    Text = "Le rocce nere sul terreno hanno ancora qualche chiazza di neve. Batti il piede e scopri che il suolo è diventato piuttosto appiccicoso."
  },
  AvgDialog_20082_Content_8 = {
    Text = "Ammorbidire la montagna, cercando di rallentarci... Non ci riuscirà!"
  },
  AvgDialog_20233_Content_1 = {
    Text = "Hai notato? Il suo punto debole è il \"Morto\" dietro di lui."
  },
  AvgDialog_20233_Content_2 = {
    Text = "Lascia che ti faccia un \"piccolo regalo\"."
  },
  AvgDialog_20475_Content_1 = {
    Text = "Finalmente... ti ho incontrato."
  },
  AvgDialog_20475_Content_10 = {
    Text = "La montagna di neve ha iniziato a divorarti... Devi sconfiggere i mostri e distruggere il nucleo il prima possibile!"
  },
  AvgDialog_20475_Content_11 = {
    Text = "Helot annuisce, estrae la spina nera e si lancia contro il mostro—"
  },
  AvgDialog_20475_Content_2 = {
    Text = "Hai combattuto duramente e finalmente hai raggiunto la vetta sorvegliata dal mostro blu azzurro."
  },
  AvgDialog_20475_Content_3 = {
    Text = "Sulla silenziosa cima della montagna innevata, un fuoco blu tremolante arde con forza, come il cuore pulsante della montagna di neve."
  },
  AvgDialog_20475_Content_4 = {
    Text = "Non puoi fermarci."
  },
  AvgDialog_20475_Content_5 = {
    Text = "La sua voce riecheggiò sulla desolata montagna di neve. Il mostro blu fluttuante nell'aria la fissava, e l'immensa bestia sospesa non diede alcuna risposta."
  },
  AvgDialog_20475_Content_6 = {
    Text = "Le mie gambe... non riesco a muoverle..."
  },
  AvgDialog_20475_Content_7 = {
    Text = "Guardi verso Lily. Le rocce nerissime si sono sciolte in liquido, e le gambe di Lily sono già per metà inghiottite dal fango nero."
  },
  AvgDialog_20475_Content_8 = {
    Text = "Tiri con tutte le tue forze, ma le gambe di Lily restano intrappolate nel fango nero fluido, sprofondando sempre di più."
  },
  AvgDialog_20475_Content_9 = {
    Text = "Il tallone di Helot viene catturato dal fango, le montagne sotto la luce rosso scuro brillano di un bagliore sinistro, come se trascinassero entrambe nell'Inferno."
  },
  AvgDialog_20483_Content_1 = {
    Text = "In qualità di emissario di @2, Questo Essere esige che vi fermiate!"
  },
  AvgDialog_20483_Content_2 = {
    Text = "La mente divorata dalla furia, la creatura un tempo chiamata Miryam si arrestò solo un istante prima di riprendere il suo Assalto frenetico."
  },
  AvgDialog_20483_Content_3 = {
    Text = "Mi ha già giudicata un'impostora... In tal caso, posso solo rispondere alla maniera di Lemuria."
  },
  AvgDialog_20483_Content_4 = {
    Text = [[
Miryam... 
Possa questo colpo dai tempi antichi... portarti illuminazione.]]
  },
  AvgDialog_20503_Content_1 = {
    Text = "Non si può più permettere che sia consumata dalla rabbia. Se perde completamente il controllo, diventerà un mostro assoluto."
  },
  AvgDialog_20503_Content_2 = {
    Text = "A quel punto, tutto sarà irreversibile.\nSottomettila, oppure... uccidila."
  },
  AvgDialog_20503_Content_3 = {
    Text = "La mia suddita più leale...\nPossa tu... non smarrire mai più la via."
  },
  AvgDialog_21363_Content_1 = {Text = "Sisifo"},
  AvgDialog_21363_Content_10 = {
    Text = "{Male=He,Female=She} è... importante."
  },
  AvgDialog_21363_Content_11 = {
    Text = "L'antico vortice nero inghiottì {Male=him,Female=her}. Osservai impotente mentre la tempesta della Pozza Nera consumava i Mythag fino a non lasciare più nulla."
  },
  AvgDialog_21363_Content_12 = {
    Text = "I Nuclei d'Argento custoditi con cura dal Dipartimento del Risveglio si dissolsero nelle acque oscure."
  },
  AvgDialog_21363_Content_13 = {
    Text = "La maggior parte dei Risvegliatori si perse nella follia—urlando, svenendo, piangendo o ridendo nel vuoto."
  },
  AvgDialog_21363_Content_14 = {
    Text = "Czort e William organizzarono l'evacuazione finale e sigillarono la barriera di nebbia per sempre."
  },
  AvgDialog_21363_Content_15 = {
    Text = "Fui sigillato da solo all'interno della Pozza Nera."
  },
  AvgDialog_21363_Content_16 = {
    Text = "Dopo un'eternità nell'oscurità, trovai una soluzione sepolta nella conoscenza che Tawil mi aveva concesso."
  },
  AvgDialog_21363_Content_17 = {
    Text = "Un passaggio—un modo per tornare indietro e riscrivere la tragedia. Ma né io né Tawil potevamo prevedere le conseguenze di una tale scelta."
  },
  AvgDialog_21363_Content_18 = {
    Text = "Sembrava avventato agire puramente per il mio tornaconto."
  },
  AvgDialog_21363_Content_19 = {
    Text = "Così attesi."
  },
  AvgDialog_21363_Content_2 = {
    Text = "Conteggio attivazioni del passaggio: 0"
  },
  AvgDialog_21363_Content_20 = {
    Text = "Fino a quel giorno. Il signor Alistair, confinato sulla sedia a rotelle, arrivò al bordo della piscina, spinto da una Doll malconcia e logorata."
  },
  AvgDialog_21363_Content_21 = {
    Text = "Visto? Alla fine era qui."
  },
  AvgDialog_21363_Content_22 = {
    Text = "Non avrei scommesso con te neanche se il mondo stesse finendo, Alistair... soprattutto perché è davvero finito."
  },
  AvgDialog_21363_Content_23 = {Text = "...?"},
  AvgDialog_21363_Content_24 = {
    Text = "Ah, non lo sapevi ancora. Il mondo là fuori è finito. Mythag..."
  },
  AvgDialog_21363_Content_25 = {
    Text = "Lascia che te lo dica così: siamo gli unici rimasti."
  },
  AvgDialog_21363_Content_26 = {
    Text = "È svanito tutto?"
  },
  AvgDialog_21363_Content_27 = {
    Text = "Spazzato via."
  },
  AvgDialog_21363_Content_28 = {
    Text = "Se non avessimo perso il nostro ultimo laboratorio, questo pianeta sarebbe stato il terreno di prova perfetto."
  },
  AvgDialog_21363_Content_29 = {
    Text = "...Allora non ho più nulla da temere."
  },
  AvgDialog_21363_Content_3 = {
    Text = "Il giorno dell'incidente della Pozza Nera, Tawil si lanciò verso di me e abbracciò dolcemente la mia anima."
  },
  AvgDialog_21363_Content_31 = {
    Text = "Chiusi gli occhi e sentii il potere scorrere dentro di me. Nel lungo silenzio, avevo imparato a conoscere intimamente quel potere. Portava con sé una vitalità che avevo dimenticato da tempo."
  },
  AvgDialog_21363_Content_32 = {
    Text = "Troverò un modo. Cambierò tutto questo."
  },
  AvgDialog_21363_Content_33 = {
    Text = "Un dolore lacerante mi sommerse. Ricordai quel pomeriggio. %player% aveva sofferto così? O era stato ancora peggio?"
  },
  AvgDialog_21363_Content_34 = {
    Text = "Questa tragedia non si ripeterà."
  },
  AvgDialog_21363_Content_35 = {
    Text = "Conteggio attivazioni del Passaggio: 1"
  },
  AvgDialog_21363_Content_36 = {
    Text = "Quando Tawil si lanciò verso di me, trassi il Custode indietro di mezzo passo."
  },
  AvgDialog_21363_Content_37 = {
    Text = "Perché? Hai fondato Mythag per cambiare il futuro, non è vero?"
  },
  AvgDialog_21363_Content_38 = {
    Text = "Perché continui a fare questo?"
  },
  AvgDialog_21363_Content_39 = {
    Text = "Tawil non disse nulla. Alzò semplicemente la mano e evocò la stessa tempesta di prima."
  },
  AvgDialog_21363_Content_4 = {
    Text = "Poi, la marea nera iniziò a montare."
  },
  AvgDialog_21363_Content_40 = {
    Text = "Conteggio attivazioni del Passaggio: 2"
  },
  AvgDialog_21363_Content_41 = {
    Text = "Quando Doll ci ordinò di fuggire, io e il Custode non discutemmo."
  },
  AvgDialog_21363_Content_42 = {
    Text = "Fuggimmo attraverso il cancello sul retro del cimitero, oltrepassando la sottile barriera di nebbia per addentrarci nel bosco buio e silenzioso."
  },
  AvgDialog_21363_Content_43 = {
    Text = "Il mondo si aprì davanti a noi: le strade animate di Londinium, piene di gente comune che viveva le proprie vite felici e ordinarie."
  },
  AvgDialog_21363_Content_44 = {
    Text = "Ma la felicità fu breve."
  },
  AvgDialog_21363_Content_45 = {
    Text = "Un'ombra densa e nera ci raggiunse da dietro."
  },
  AvgDialog_21363_Content_46 = {
    Text = "Questa volta, la distruzione a cui assistetti fu mille volte peggiore."
  },
  AvgDialog_21363_Content_47 = {
    Text = "Le persone che ridevano per strada si bloccarono all'improvviso. Il fango nero inghiottì i loro piedi, cancellando la loro stessa esistenza."
  },
  AvgDialog_21363_Content_48 = {
    Text = "Cercarono di muoversi, ma sprofondarono nella melma invisibile."
  },
  AvgDialog_21363_Content_49 = {
    Text = "Svanirono completamente."
  },
  AvgDialog_21363_Content_5 = {
    Text = "%player%, aggrappati a me! %player%!"
  },
  AvgDialog_21363_Content_50 = {
    Text = "Conteggio attivazioni del Passaggio: 3"
  },
  AvgDialog_21363_Content_51 = {
    Text = "Nascosi l'esistenza della torre dell'orologio e della Pozza Nera. Convinsi il Custode a lasciare il campus da solo mentre affrontavo Tawil per conto mio."
  },
  AvgDialog_21363_Content_52 = {
    Text = "Senza il comando del Custode né il supporto dei miei amici, non riuscii nemmeno a raggiungere la pozza. Fui abbattuta da altri Risvegliatori che avevano perso il controllo."
  },
  AvgDialog_21363_Content_53 = {
    Text = "Conteggio attivazioni del Passaggio: 4"
  },
  AvgDialog_21363_Content_54 = {
    Text = "Conteggio attivazioni del Passaggio: 5"
  },
  AvgDialog_21363_Content_55 = {Text = "..."},
  AvgDialog_21363_Content_56 = {
    Text = "Conteggio attivazioni del Passaggio: @3"
  },
  AvgDialog_21363_Content_57 = {
    Text = "<Italic:Quante volte è successo ormai?> \nMi chiesi."
  },
  AvgDialog_21363_Content_58 = {
    Text = "<Italic:Devo guardare il mondo... guardare %player% morire di nuovo?>"
  },
  AvgDialog_21363_Content_59 = {
    Text = "<Italic:Se {Male=he,Female=she} è destinat_ a morire come Custode qualunque cosa io faccia, allora farò in modo che {Male=he,Female=she} non lo diventi mai.>"
  },
  AvgDialog_21363_Content_6 = {
    Text = "Allungai la mano più lontano che potevo."
  },
  AvgDialog_21363_Content_60 = {
    Text = "Così nascosi le abilità di {Male=his,Female=her} e lasciai {Male=him,Female=her} ad Akut. Non mi importava se avessi dovuto percorrere questa strada da sola, purché {Male=he,Female=she} vivesse."
  },
  AvgDialog_21363_Content_61 = {
    Text = "Quella volta, non riuscii nemmeno a uscire dal cimitero."
  },
  AvgDialog_21363_Content_62 = {
    Text = "Ti siedi sul bordo della Pozza Nera. Mentre Ramona ti fascia le ferite, racconta la sua agonia con una voce vuota e ferma."
  },
  AvgDialog_21363_Content_63 = {
    Text = "Ho provato a fuggire dal campus. Ho provato ad affrontare Tawil direttamente."
  },
  AvgDialog_21363_Content_64 = {
    Text = "Ho provato a portare con me Lotan, Ogier e Doll. Ho provato a lasciarli indietro."
  },
  AvgDialog_21363_Content_65 = {
    Text = "Ho provato con le parole gentili. Ho provato con la violenza."
  },
  AvgDialog_21363_Content_66 = {
    Text = "Niente ha funzionato."
  },
  AvgDialog_21363_Content_67 = {
    Text = "Alla fine, ho iniziato ad affinare le mie abilità di combattimento."
  },
  AvgDialog_21363_Content_68 = {
    Text = "L'unica possibilità rimasta era colpire quando l'anomalia aveva inizio—trafiggere il nucleo di Tawil nel momento in cui avesse rivelato la sua vera forma."
  },
  AvgDialog_21363_Content_69 = {
    Text = "Dovevo essere veloce. Più veloce di qualsiasi cosa."
  },
  AvgDialog_21363_Content_7 = {
    Text = "Proprio come ad Akut—se avessi potuto afferrare {Male=him,Female=her}, {Male=he,Female=she} avrebbe potuto salvarci dalla disperazione in quella tempesta."
  },
  AvgDialog_21363_Content_70 = {
    Text = "Abbastanza veloce da lasciare Lotan sbalordito, abbastanza veloce da colpire prima che Doll potesse parlare, abbastanza veloce da cogliere Tawil di sorpresa."
  },
  AvgDialog_21363_Content_71 = {
    Text = "Chiunque incontrassi diventava un bersaglio su cui affilare la mia lama. Su questo cammino, non riconoscevo più nessuno come compagno."
  },
  AvgDialog_21363_Content_72 = {
    Text = "Ho smesso di parlare con il Custode. Mi sono concentrato solo sul perfezionare quell'unico Colpo Predestinato."
  },
  AvgDialog_21363_Content_73 = {
    Text = "Ci sei riuscito?"
  },
  AvgDialog_21363_Content_74 = {
    Text = "Ci sono riuscito... e ho fallito."
  },
  AvgDialog_21363_Content_75 = {
    Text = "Quel giorno, Tawil mi tese la mano."
  },
  AvgDialog_21363_Content_76 = {
    Text = "Seguendo un istinto affinato migliaia di volte, ho affondato la lama con tutto ciò che avevo verso il bagliore nel petto di Tawil."
  },
  AvgDialog_21363_Content_78 = {
    Text = "Il metallo si scontrò con un fragore assordante. Il mio polso vibrò per la forza dell'impatto."
  },
  AvgDialog_21363_Content_79 = {
    Text = "La forma di Tawil si frantumò in cenere argentata."
  },
  AvgDialog_21363_Content_8 = {
    Text = "Per non parlare del fatto che..."
  },
  AvgDialog_21363_Content_80 = {
    Text = "È finita. Finalmente."
  },
  AvgDialog_21363_Content_81 = {
    Text = "È FINITA...!"
  },
  AvgDialog_21363_Content_82 = {
    Text = "%player%, ce l'abbiamo fatta—"
  },
  AvgDialog_21363_Content_83 = {
    Text = "<Big: %player%!>"
  },
  AvgDialog_21363_Content_84 = {
    Text = "Nessun Custode era dietro di me."
  },
  AvgDialog_21363_Content_85 = {
    Text = "Solo una mano, che sprofondava in un vortice nero."
  },
  AvgDialog_21363_Content_86 = {
    Text = "Quel giorno, mi gettai nella Pozza Nera."
  },
  AvgDialog_21363_Content_87 = {
    Text = "E per un breve istante, intravidi un futuro che non mi apparteneva."
  },
  AvgDialog_21363_Content_88 = {
    Text = "Tawil rimase in piedi, sebbene la Sua compostezza si fosse incrinata."
  },
  AvgDialog_21363_Content_89 = {
    Text = "Prima che chiunque altro potesse reagire, dispiegò le Sue ali argentee e si scagliò contro Ramona—contro l'altra versione di me."
  },
  AvgDialog_21363_Content_9 = {
    Text = "%player% è un mio amico."
  },
  AvgDialog_21363_Content_90 = {
    Text = "Il tempo sembrò fermarsi."
  },
  AvgDialog_21363_Content_92 = {
    Text = "Il Custode scattò in avanti, gettando {Male=himself,Female=herself} davanti alla mia controparte."
  },
  AvgDialog_21363_Content_93 = {
    Text = "Fu allora che la consapevolezza mi colpì."
  },
  AvgDialog_21363_Content_94 = {
    Text = "Il futuro del mondo non spetta a me sceglierlo o cambiarlo."
  },
  AvgDialog_21363_Content_96 = {
    Text = "Ero a un solo passo di distanza. Un divario che non avrei mai potuto colmare."
  },
  AvgDialog_21364_Content_1 = {
    Text = "Cominciamo."
  },
  AvgDialog_21364_Content_2 = {
    Text = "Aspetta, Ramona! Doll e Ogier non sono qui. Non puoi affrontare tutto questo da sola..."
  },
  AvgDialog_21364_Content_3 = {
    Text = "È troppo tardi. Tawil ruggisce, dispiegando le sue sei ali argentate."
  },
  AvgDialog_21364_Content_4 = {
    Text = "Una familiare sensazione di calore acre brucia i tuoi occhi, questa volta ancora più pungente e bruciante dell'ultima, le lacrime scorrono inarrestabili."
  },
  AvgDialog_21364_Content_5 = {
    Text = "Ramona volta la testa e ti sussurra."
  },
  AvgDialog_21364_Content_6 = {
    Text = "Stabilisci un Legame con me. Dammi un ultimo comando."
  },
  AvgDialog_21364_Content_7 = {Text = "Custode."},
  AvgDialog_21365_Content_2 = {
    Text = "Un colpo rapido e netto pone fine alla battaglia all'istante. Ramona scuote la melma dalla lama. Non ti degna di uno sguardo."
  },
  AvgDialog_21365_Content_3 = {
    Text = "Fissi sotto shock la sua schiena fredda e distante. Sembra un'estranea."
  },
  AvgDialog_21365_Content_4 = {
    Text = "Questo è... davvero un ricordo?"
  },
  AvgDialog_21365_Content_5 = {
    Text = "Ramona scavalca il cadavere in dissoluzione del mutante e corre verso la piazza, spada alla mano."
  },
  AvgDialog_21366_Content_1 = {
    Text = "Ti precipiti per raggiungerla, forzando le porte dell'ascensore all'ultimo secondo, rischiando di schiacciarti le mani."
  },
  AvgDialog_21366_Content_10 = {
    Text = "Il Dominio Artificiale recide la connessione? Cos'è questa entità davanti a te?"
  },
  AvgDialog_21366_Content_11 = {
    Text = "Non lo sai. Non sai nemmeno quando potrai uscire."
  },
  AvgDialog_21366_Content_12 = {Text = "Ding—"},
  AvgDialog_21366_Content_13 = {
    Text = "Ramona esce dall'ascensore e ti lancia una risposta alle spalle."
  },
  AvgDialog_21366_Content_14 = {
    Text = "Non per molto tempo."
  },
  AvgDialog_21366_Content_2 = {
    Text = "Huff... Huff..."
  },
  AvgDialog_21366_Content_3 = {
    Text = "Solo ora riesci finalmente a vedere chiaramente il suo volto da quando sei entrato nel Dominio Artificiale."
  },
  AvgDialog_21366_Content_4 = {
    Text = "Ra... Ramona?"
  },
  AvgDialog_21366_Content_5 = {
    Text = "Questa Ramona indossa una benda nera sugli occhi. Sembra contrariata, irritata dal fatto che tu abbia ritardato la sua discesa."
  },
  AvgDialog_21366_Content_6 = {
    Text = "Tu... tu non sei la Ramona che conosco, vero?"
  },
  AvgDialog_21366_Content_7 = {
    Text = "L'ascensore vibra. Ramona è rivolta verso di te, ma resta in silenzio."
  },
  AvgDialog_21366_Content_8 = {
    Text = "Cerchi cautamente il legame tra voi, ma non trovi nulla."
  },
  AvgDialog_21366_Content_9 = {
    Text = "Nessun legame..."
  },
  AvgDialog_21367_Content_1 = {
    Text = "Non è un addio"
  },
  AvgDialog_21367_Content_10 = {
    Text = "La scena della Pozza Nera svanisce come una fotografia che perde i suoi colori. Il profilo del Dispositivo di risveglio si rivela debolmente là dove un tempo si ergeva Tawil."
  },
  AvgDialog_21367_Content_11 = {
    Text = "Anche se so che è impossibile..."
  },
  AvgDialog_21367_Content_12 = {
    Text = "Spero che ci rivedremo."
  },
  AvgDialog_21367_Content_13 = {
    Text = "Il Dominio Artificiale si dissipa gradualmente. Siedi davanti al Dispositivo di risveglio, osservando Ramona sulla poltrona reclinabile."
  },
  AvgDialog_21367_Content_14 = {
    Text = "Noti con sorpresa che indossa ancora la benda appartenente all'altra \"Ramona\"."
  },
  AvgDialog_21367_Content_15 = {
    Text = "...Ramona...?"
  },
  AvgDialog_21367_Content_16 = {
    Text = "...Non me lo aspettavo nemmeno io. Sono felice di rivederti così presto, %player%."
  },
  AvgDialog_21367_Content_17 = {
    Text = "Sei davvero quella \"Ramona\"?! Cosa sta succedendo?"
  },
  AvgDialog_21367_Content_18 = {
    Text = "Credo di poter rispondere a questa domanda."
  },
  AvgDialog_21367_Content_19 = {
    Text = "Una voce familiare ti fa trasalire. Ti volti e trovi Doll in piedi dietro di te, che sorseggia tranquillamente del tè."
  },
  AvgDialog_21367_Content_2 = {
    Text = "Guardi questa \"Ramona\" davanti a te, senza trovare le parole."
  },
  AvgDialog_21367_Content_20 = {
    Text = "Prima del tuo arrivo, Ramona e io abbiamo condotto un semplice test sul dispositivo del Dominio Artificiale per verificare fin dove potesse estendersi il suo spirito e la potenza del campo risultante."
  },
  AvgDialog_21367_Content_21 = {
    Text = "Durante il test, il <Blue:Misuratore di Gnosi> ha improvvisamente indicato fluttuazioni anomale. Il Dominio si è espanso completamente in soli tre secondi, formando un campo indipendente che ha inglobato Ramona, la porta e parte della strumentazione."
  },
  AvgDialog_21367_Content_22 = {
    Text = "Fortunatamente, nonostante un <Yellow:Indice Gnostico> spaventosamente alto, il Dominio è rimasto stabile e non influenzato dalle fluttuazioni mentali."
  },
  AvgDialog_21367_Content_23 = {
    Text = "Sfortunatamente, sei entrato nel Dominio nel momento stesso in cui hai varcato la stanza. Per qualche ragione, non sono riuscita a entrare, né a vedere cosa stesse accadendo all'interno."
  },
  AvgDialog_21367_Content_24 = {
    Text = "Non era mai successo negli esperimenti precedenti. Dal momento che eri dentro, non ho osato agire avventatamente."
  },
  AvgDialog_21367_Content_25 = {
    Text = "Per fortuna, avevo preimpostato la durata del Dominio Artificiale. Tutto ciò che dovevo fare era aspettare."
  },
  AvgDialog_21367_Content_26 = {
    Text = "È per questo che stai bevendo il tè?! Aspetta, è profumo di cupcake? Hai iniziato il tè pomeridiano senza di noi!"
  },
  AvgDialog_21367_Content_27 = {
    Text = "Registrare i dati non richiede molto tempo. Inoltre, come ho detto, non potevo vedere all'interno del Dominio. Altrimenti la mia mattinata sarebbe stata molto più impegnativa."
  },
  AvgDialog_21367_Content_28 = {
    Text = "Hai trovato la causa?"
  },
  AvgDialog_21367_Content_29 = {
    Text = "Doll lancia un'occhiata all'altra \"Ramona\", trattenendo visibilmente la sua curiosità mentre spiega."
  },
  AvgDialog_21367_Content_3 = {
    Text = "Ha portato troppo sulle spalle. Ha sofferto troppo. La sua espressione resta fredda, ma muove le mani con delicatezza mentre fascia le tue ferite."
  },
  AvgDialog_21367_Content_30 = {
    Text = "In base ai dati attuali, c'è un solo motivo per cui il Dominio Artificiale ha letto i ricordi di questa Ramona anziché della nostra."
  },
  AvgDialog_21367_Content_31 = {
    Text = "Esiste una <Yellow:risonanza spirituale tra i Risvegliati della stessa origine>. Amplificata dal dispositivo, ha infranto i confini dimensionali, causando la <Yellow:breve sovrapposizione> di due spiriti estremamente simili. Ciò ha portato alla costruzione erronea del dominio."
  },
  AvgDialog_21367_Content_32 = {
    Text = "Questa \"Ramona\" è riuscita a manifestarsi nel nostro mondo grazie a quella <Yellow:risonanza spirituale>."
  },
  AvgDialog_21367_Content_33 = {
    Text = "Della stessa origine... significa che condividono una fonte di potere comune?"
  },
  AvgDialog_21367_Content_34 = {
    Text = "Si potrebbe dire così. Il potere combattivo di un Risvegliatore è essenzialmente \"preso in prestito\" da esseri di dimensioni superiori che chiamiamo <Blue:Genesi>."
  },
  AvgDialog_21367_Content_35 = {
    Text = "I Risvegliatori con la stessa <Yellow:Genesi> sono quelli che chiamiamo <Yellow:Risvegliati della stessa origine>."
  },
  AvgDialog_21367_Content_36 = {
    Text = "Ma non siete la stessa persona?"
  },
  AvgDialog_21367_Content_37 = {
    Text = "In una certa misura, sì. Ma possediamo esperienze diverse e ricordi diversi."
  },
  AvgDialog_21367_Content_38 = {
    Text = "Inoltre, rispetto alla nostra Ramona, questa versione utilizza il potere in modo diverso. Il suo spirito è molto più vicino alla sua Genesi. Avete incontrato <Yellow:Tawil>, non è vero?"
  },
  AvgDialog_21367_Content_39 = {
    Text = "Sì. Con il Loro aiuto, ho aperto un passaggio verso il passato."
  },
  AvgDialog_21367_Content_4 = {Text = "Io..."},
  AvgDialog_21367_Content_40 = {
    Text = "Non c'è da stupirsi. La tua capacità è di gran lunga più..."
  },
  AvgDialog_21367_Content_41 = {
    Text = "Sono sempre più curiosa riguardo a te—e a tutti gli altri Risvegliatori che esistono più vicini alla loro Genesi."
  },
  AvgDialog_21367_Content_42 = {
    Text = "Vedendo Doll prepararsi a richiedere un esperimento, cambi rapidamente argomento."
  },
  AvgDialog_21367_Content_43 = {
    Text = "Quindi un Risvegliatore più vicino alla propria Genesi è un <Yellow:Risvegliatore della Genesi>?"
  },
  AvgDialog_21367_Content_44 = {
    Text = "Risvegliatore della Genesi? Mi piace il nome. Hai dimostrato un raro lampo di ingegno, %player%."
  },
  AvgDialog_21367_Content_45 = {
    Text = "Hai altre domande?"
  },
  AvgDialog_21367_Content_46 = {
    Text = "Tu... vuoi restare?"
  },
  AvgDialog_21367_Content_47 = {
    Text = "Una volta disattivato il dispositivo, l'amplificazione mentale svanisce e la risonanza si indebolirà."
  },
  AvgDialog_21367_Content_48 = {
    Text = "Quanto a tenerlo acceso a tempo indeterminato—mi dispiace, ma il dispositivo ha un raggio limitato. Qualunque cosa tu desideri, alla fine dovrà tornare nel suo mondo."
  },
  AvgDialog_21367_Content_49 = {
    Text = "È impossibile che coesistano in questo momento. Come può un corpo ospitare due spiriti? Ma in futuro... chi lo sa? Forse se usiamo... se raccogliamo abbastanza dati..."
  },
  AvgDialog_21367_Content_5 = {
    Text = "Va tutto bene. Non hai bisogno di dire nulla."
  },
  AvgDialog_21367_Content_50 = {
    Text = "La voce di Doll si affievolisce mentre sprofonda nei suoi pensieri. \"Ramona\" ti sorride."
  },
  AvgDialog_21367_Content_51 = {
    Text = "Quando avrai bisogno di me, invoca il legame che ci unisce. Usando lei come tramite, potrò manifestarmi in questo mondo per un breve periodo."
  },
  AvgDialog_21367_Content_52 = {
    Text = "Il passaggio è aperto. Finché resterò cosciente, verrò al tuo fianco."
  },
  AvgDialog_21367_Content_53 = {
    Text = "Ramona è consapevole di ciò che accade mentre tu sei qui?"
  },
  AvgDialog_21367_Content_54 = {
    Text = "Mentre io sono sveglia, la Ramona che conosci cade in un sonno profondo. È del tutto ignara della mia esistenza."
  },
  AvgDialog_21367_Content_55 = {
    Text = "Devo chiederti di riferirle i miei messaggi al posto mio."
  },
  AvgDialog_21367_Content_56 = {
    Text = "Tutti i Risvegliati della stessa origine vivono questa esperienza?"
  },
  AvgDialog_21367_Content_57 = {
    Text = "E se usassimo le parti di Erica per costruire un altro automa..."
  },
  AvgDialog_21367_Content_58 = {
    Text = "Cosa stai pensando? Non mi hai sentito dire \"spiriti altamente simili\"? A parte una controparte da un altro mondo, nessun altro spirito soddisfa quel requisito."
  },
  AvgDialog_21367_Content_59 = {
    Text = "Ma chi lo sa? Forse con il Dominio Artificiale potremo trovare pian piano il Risvegliatore della Genesi per tutti. Se dovesse accadere..."
  },
  AvgDialog_21367_Content_6 = {
    Text = "Resta ancora un po' prima di tornare indietro."
  },
  AvgDialog_21367_Content_60 = {
    Text = "Osservi impotente Doll immergersi in un altro turbinio di pensieri. \"Ramona\" ti sfiora delicatamente la mano."
  },
  AvgDialog_21367_Content_61 = {
    Text = "È ora che torni indietro. Non dovrei abusare della vostra ospitalità."
  },
  AvgDialog_21367_Content_62 = {
    Text = "Esiti, ma non riesci a trovare le parole per chiederle di restare."
  },
  AvgDialog_21367_Content_63 = {
    Text = "C'è qualcosa che vuoi dire a Ramona?"
  },
  AvgDialog_21367_Content_64 = {
    Text = "Rimane in silenzio a lungo. Trae un respiro profondo e parla con finta indifferenza."
  },
  AvgDialog_21367_Content_65 = {
    Text = "Dille... che è molto fortunata."
  },
  AvgDialog_21367_Content_66 = {
    Text = "Io sono... un po' invidiosa."
  },
  AvgDialog_21367_Content_67 = {
    Text = "Lasciandoti con quelle parole, si siede sulla poltrona reclinabile e chiude gli occhi. Il suo respiro si stabilizza gradualmente."
  },
  AvgDialog_21367_Content_68 = {
    Text = "Sai che la prossima a risvegliarsi sarà l'assistente saggia e distaccata che conosci così bene."
  },
  AvgDialog_21367_Content_69 = {
    Text = "E quella ragazza fredda e mascherata torna alla Pozza Nera in un'altra dimensione, con lo sguardo rivolto verso il cielo sconfinato e nero come la pece."
  },
  AvgDialog_21367_Content_7 = {
    Text = "Tornare? Tu sai che—"
  },
  AvgDialog_21367_Content_70 = {
    Text = "Attende una chiamata da una dimensione lontana."
  },
  AvgDialog_21367_Content_8 = {
    Text = "Lo so. Non appartieni a me, né a questa versione del mondo."
  },
  AvgDialog_21367_Content_9 = {
    Text = "Ma sapere che esiste un mondo intatto dalla distruzione—sapere che sei al sicuro—mi basta. Sono in pace."
  },
  AvgDialog_21368_Content_1 = {
    Text = "Tutto per tutto"
  },
  AvgDialog_21368_Content_10 = {
    Text = "Prima che tu possa impartire un ordine, lei si muove."
  },
  AvgDialog_21368_Content_2 = {
    Text = "Il tanfo di sangue ti punge le narici. Gli studenti urlano e si disperdono davanti a un mostro nero che si contorce. Tutto sembra identico al giorno in cui hai ricevuto la Chiave d'argento."
  },
  AvgDialog_21368_Content_3 = {
    Text = "...Il giorno in cui Ramona fu ferita."
  },
  AvgDialog_21368_Content_4 = {
    Text = "Questa è... la Cerimonia di Conferimento della Chiave?"
  },
  AvgDialog_21368_Content_5 = {
    Text = "La pioggia ti s'infiltra nei vestiti, portando un brivido gelido. Per un istante, avverti un'illusione terrificante: che la vita vissuta dopo fosse il sogno, e che tu non abbia mai lasciato questo disastro."
  },
  AvgDialog_21368_Content_6 = {
    Text = "Doll deve aver attivato il Dominio Artificiale in anticipo. Chissà dove si trova Ramona..."
  },
  AvgDialog_21368_Content_7 = {
    Text = "Ti fermi sui tuoi passi. Nel caos, una sagoma familiare è in piedi di spalle a te, rivolta verso il vento."
  },
  AvgDialog_21368_Content_8 = {
    Text = "Punta lo stocco contro \"Emily\" — la ragazza che un tempo si era presentata ai cancelli del cimitero, ora deformata oltre ogni riconoscimento."
  },
  AvgDialog_21368_Content_9 = {Text = "Ramona!"},
  AvgDialog_21369_Content_1 = {
    Text = "Tawil rimase in piedi, sebbene la Sua compostezza si fosse incrinata."
  },
  AvgDialog_21369_Content_11 = {
    Text = "Un volto femminile e indifferente appare davanti a te."
  },
  AvgDialog_21369_Content_12 = {
    Text = "Tawil allunga la mano e tocca leggermente la Chiave d'argento sul tuo petto."
  },
  AvgDialog_21369_Content_13 = {
    Text = "La Chiave d'argento emette un bagliore in risposta."
  },
  AvgDialog_21369_Content_14 = {
    Text = "Tu sei la Variabile, la risposta sia all'inizio che alla fine."
  },
  AvgDialog_21369_Content_15 = {
    Text = "Si spera che diventerai il punto di svolta..."
  },
  AvgDialog_21369_Content_17 = {
    Text = "Il mostro bianco a sei ali, i demoni di fango che si disperdono, le ombre contorte..."
  },
  AvgDialog_21369_Content_18 = {
    Text = "Tutti si dissolvono in acqua nera e svaniscono senza lasciare traccia."
  },
  AvgDialog_21369_Content_19 = {
    Text = "Stringi la Chiave d'argento al petto ed espiri lentamente."
  },
  AvgDialog_21369_Content_2 = {
    Text = "Prima che tu possa reagire, dispiega le sue ali d'argento e si lancia contro Ramona."
  },
  AvgDialog_21369_Content_20 = {
    Text = "...Perché."
  },
  AvgDialog_21369_Content_21 = {Text = "?"},
  AvgDialog_21369_Content_22 = {
    Text = "Perché ti sei messo davanti a me?"
  },
  AvgDialog_21369_Content_23 = {
    Text = "Non sapevi che era pericoloso?"
  },
  AvgDialog_21369_Content_24 = {
    Text = "Non hai paura della morte?"
  },
  AvgDialog_21369_Content_25 = {Text = "Io—"},
  AvgDialog_21369_Content_26 = {
    Text = "Non voglio che tu muoia."
  },
  AvgDialog_21369_Content_27 = {
    Text = "Non riesci a capire dove stiano guardando i suoi occhi bendati. Il tessuto scuro è umido, intriso di lacrime."
  },
  AvgDialog_21369_Content_28 = {
    Text = "L'ho visto troppe volte. Non voglio più..."
  },
  AvgDialog_21369_Content_29 = {
    Text = "Inspira bruscamente e inghiotte il resto delle sue parole."
  },
  AvgDialog_21369_Content_3 = {
    Text = "Il tempo sembrò fermarsi."
  },
  AvgDialog_21369_Content_30 = {
    Text = "La ragazza che un istante fa era fredda e priva di emozioni sembra aver ritrovato i suoi sentimenti. Trema, si avvicina con cautela e appoggia delicatamente la testa contro il tuo petto."
  },
  AvgDialog_21369_Content_31 = {
    Text = "Le lacrime cadono sulla tua spalla ferita. Un dolore acuto si intreccia nei tuoi nervi. Il tuo corpo trema incontrollabilmente, ma il calore delle sue lacrime ne attenua il colpo."
  },
  AvgDialog_21369_Content_32 = {
    Text = "Ramona, io..."
  },
  AvgDialog_21369_Content_33 = {
    Text = "Ti stringe la mano come se fossi l'ultimo filo di un aquilone nella tempesta. Non può fare altro che pregare che tu non svanisca nei venti del tempo."
  },
  AvgDialog_21369_Content_34 = {
    Text = "Smetti di rischiare la vita... %player%."
  },
  AvgDialog_21369_Content_4 = {
    Text = "Scatti con ogni briciolo di forza e ti getti davanti a Ramona."
  },
  AvgDialog_21369_Content_6 = {
    Text = "Uno stocco d'argento si conficca da dietro, trapassandoti la spalla sinistra."
  },
  AvgDialog_21369_Content_7 = {Text = "?!"},
  AvgDialog_21369_Content_8 = {
    Text = "Il mostro bianco ti fissa dritto negli occhi."
  },
  AvgDialog_21369_Content_9 = {
    Text = "Ti osserva in silenzio con la sua forma pallida e priva di volto."
  },
  AvgDialog_21391_Content_1 = {Text = "Tramonto"},
  AvgDialog_21391_Content_10 = {
    Text = "Allora non provavo dolore — per niente."
  },
  AvgDialog_21391_Content_11 = {
    Text = "Poi le cose cambiarono. La mamma mi rinchiuse, fece sempre più esperimenti."
  },
  AvgDialog_21391_Content_12 = {
    Text = "Ma non è colpa della mamma.\nEra rinchiusa in questa stanza con me, incapace di andarsene."
  },
  AvgDialog_21391_Content_13 = {
    Text = "Perché persi il controllo, uccidendo così tante persone.\nPerché... faceva così male."
  },
  AvgDialog_21391_Content_14 = {
    Text = "Lisa disse che, come mia unica amica, avrebbe cercato di restare con me più a lungo."
  },
  AvgDialog_21391_Content_15 = {
    Text = "Altrimenti, non avrebbe potuto resistere."
  },
  AvgDialog_21391_Content_16 = {
    Text = "...La verità è che nemmeno io riuscivo a resistere."
  },
  AvgDialog_21391_Content_17 = {
    Text = "La bestia gigantesca squarcia altro spazio, i suoi artigli si abbattono su Lily."
  },
  AvgDialog_21391_Content_19 = {
    Text = "Dinanzi alla Fanciulla Pallida vacillante, il pus nero forma sfere e reti, deviando i Suoi attacchi ancora e ancora."
  },
  AvgDialog_21391_Content_2 = {
    Text = "I passi delicati di Lily avanzano a piedi nudi, con del pus nero che si raccoglie e prende forma ai suoi piedi."
  },
  AvgDialog_21391_Content_20 = {
    Text = "Ma nonostante tutto—"
  },
  AvgDialog_21391_Content_21 = {
    Text = "È la mia unica mamma."
  },
  AvgDialog_21391_Content_22 = {
    Text = "Non osare — fare del male alla mia mamma!"
  },
  AvgDialog_21391_Content_24 = {
    Text = "Le sfere di pus nero esplodono, formando spuntoni che inchiodano gli artigli del Segugio infernale."
  },
  AvgDialog_21391_Content_25 = {
    Text = "Il pus rimanente germoglia denti affilati come lame, recidendo la caviglia imprigionata."
  },
  AvgDialog_21391_Content_27 = {
    Text = "Gli artigli si dissolsero in una nebbia viola demoniaca, per poi riformarsi ancora una volta."
  },
  AvgDialog_21391_Content_28 = {
    Text = "Squarcia lo spazio, il tempo congelato filtra attraverso le crepe, il tramonto divorato per intero."
  },
  AvgDialog_21391_Content_3 = {
    Text = "Lisa ha detto che sua madre non l'ha riconosciuta, le ha persino sparato con un fucile."
  },
  AvgDialog_21391_Content_30 = {
    Text = "Spalanca le sue fauci ultraterrene e si avventa su Lily!"
  },
  AvgDialog_21391_Content_4 = {
    Text = "Lisa ha detto che sua madre era severa, la sgridava o la picchiava ogni volta che giocavamo."
  },
  AvgDialog_21391_Content_5 = {
    Text = "Lisa ha detto che se sua madre avesse saputo che si è trasformata in un grosso cane per colpa mia, non l'avrebbe mai perdonata."
  },
  AvgDialog_21391_Content_6 = {
    Text = "Ma non poteva farne a meno. Aveva così tanta fame, e non voleva rubare, così tornò a casa per mangiare... e venne scoperta."
  },
  AvgDialog_21391_Content_7 = {
    Text = "Lily si ferma."
  },
  AvgDialog_21391_Content_8 = {
    Text = "Ma la mia mamma è diversa."
  },
  AvgDialog_21391_Content_9 = {
    Text = "Mi scambiò per qualcun altro, ma la prima volta che mi tagliò con un bisturi, chiese scusa."
  },
  AvgDialog_21392_Content_10 = {
    Text = [[
Il Conducente inchioda i freni, il treno sussulta fino a fermarsi.
I passeggeri nel panico balzano fuori, disperdendosi in ogni direzione.]]
  },
  AvgDialog_21392_Content_11 = {
    Text = "Emergenza — proteggere i civili!\nBambola, Bambola, mi senti?"
  },
  AvgDialog_21392_Content_12 = {
    Text = "Rilevamento... Interferenza nelle comunicazioni... fluttuazioni della Chiave d'Argento... possibile... zzzt... Risonanza..."
  },
  AvgDialog_21392_Content_13 = {
    Text = "Com'è quel detto? L'acqua lontana non spegne il fuoco vicino."
  },
  AvgDialog_21392_Content_2 = {
    Text = "C-Cos'è quella cosa?!"
  },
  AvgDialog_21392_Content_3 = {
    Text = "Sui binari più avanti, nell'Oscurità del Tunnel, una figura si staglia illuminata dai fari — una sagoma impossibile."
  },
  AvgDialog_21392_Content_4 = {
    Text = "Una Donna alta, il suo sguardo affilato come lame, affronta con calma il treno in arrivo."
  },
  AvgDialog_21392_Content_5 = {
    Text = "Ti ho trovato."
  },
  AvgDialog_21392_Content_6 = {
    Text = "In un istante fugace, la Donna svanisce—"
  },
  AvgDialog_21392_Content_8 = {
    Text = "No, non svanisce: sta caricando verso il treno in corsa!"
  },
  AvgDialog_21761_Content_1 = {
    Text = "Esecuzione di 10 test rapidi di dissolvenza a nero"
  },
  AvgDialog_21761_Content_11 = {
    Text = [[
Test [Vecchio Film], 2
Fine]]
  },
  AvgDialog_21761_Content_12 = {
    Text = "Ora procederemo con il test degli occhi chiusi"
  },
  AvgDialog_21761_Content_14 = {
    Text = "Chiudere gli occhi non è un effetto ciclico; ricorda di terminare con 2."
  },
  AvgDialog_21761_Content_15 = {
    Text = "Procedere con un lampo di luce rossa, 1"
  },
  AvgDialog_21761_Content_17 = {
    Text = "Un lampo di luce rossa non è un effetto ciclico. Ricorda di terminarlo con 2."
  },
  AvgDialog_21761_Content_3 = {
    Text = "Esecuzione test [Mist], 1"
  },
  AvgDialog_21761_Content_5 = {
    Text = [[
Test [Mist], 2
Fine]]
  },
  AvgDialog_21761_Content_6 = {
    Text = "Esecuzione test [Pioggia Leggera], 1"
  },
  AvgDialog_21761_Content_8 = {
    Text = [[
Test [Pioggia Leggera], 2
Fine]]
  },
  AvgDialog_21761_Content_9 = {
    Text = "Esecuzione test [Vecchio Film], 1"
  },
  AvgDialog_21801_Content_1 = {
    Text = "Compendio degli amici"
  },
  AvgDialog_21801_Content_10 = {
    Text = "Perché cammini così barcollando? Ti sei fatto male a una gamba?"
  },
  AvgDialog_21801_Content_11 = {
    Text = "Ti voltasti a guardare il percorso che avevi fatto: per evitare la melma-D che si espandeva sul terreno, le tue impronte formavano uno strano arco nel fango."
  },
  AvgDialog_21801_Content_12 = {
    Text = "Oppure... Aurita ti porta in braccio?"
  },
  AvgDialog_21801_Content_13 = {
    Text = "No, non serve. Ho solo pensato che questo percorso sarebbe stato più divertente. Non credi anche tu, Aurita?"
  },
  AvgDialog_21801_Content_14 = {
    Text = "Come giocare a campana!"
  },
  AvgDialog_21801_Content_15 = {
    Text = "Sì, come giocare a campana."
  },
  AvgDialog_21801_Content_16 = {
    Text = "...Aurita, giochiamo a pestare l'ombra?"
  },
  AvgDialog_21801_Content_17 = {
    Text = "Io cammino davanti, e tu segui le mie impronte... Che ne dici?"
  },
  AvgDialog_21801_Content_18 = {
    Text = "Hmm... Non è impossibile! Vai avanti tu, e Aurita ti indica la strada."
  },
  AvgDialog_21801_Content_19 = {
    Text = "Aurita fece obbedientemente un paio di passi indietro per lasciarti spazio, rischiando quasi di finire nella melma-D mentre saltellava."
  },
  AvgDialog_21801_Content_2 = {
    Text = "Hmm~ Hmm hmm hmm~"
  },
  AvgDialog_21801_Content_20 = {
    Text = "La tirasti bruscamente, ma lei sbatté le palpebre, sorridendo ancora beatamente mentre il gioco aveva inizio."
  },
  AvgDialog_21801_Content_21 = {
    Text = "Ciuf-ciuf— Il treno parte! Piazza Centrale— A sinistra!"
  },
  AvgDialog_21801_Content_3 = {
    Text = "Aurita canticchiava una melodia allegra, camminando al tuo fianco per le strade in via di dissoluzione."
  },
  AvgDialog_21801_Content_4 = {
    Text = "Le finestre scure e spente mostrano che questo luogo è stato abbandonato da tempo. Ai due lati della strada silenziosa, restano solo i contorni delle case in rovina."
  },
  AvgDialog_21801_Content_5 = {
    Text = "E i residenti? Hanno lasciato le loro case prima dell'esplosione del Fenomeno-D? Hanno trovato nuovi posti dove vivere, oppure..."
  },
  AvgDialog_21801_Content_6 = {
    Text = "Un liquido nero e viscoso scorre silenziosamente ai tuoi piedi. Fai un respiro profondo, sopprimendo la nausea che quasi ti sale in gola."
  },
  AvgDialog_21801_Content_7 = {
    Text = "Oppure... non hanno mai lasciato la loro amata casa?"
  },
  AvgDialog_21801_Content_8 = {Text = "..."},
  AvgDialog_21801_Content_9 = {
    Text = "Un mormorio pensieroso ti distoglie dalle tue preoccupazioni. Aurita ti osservò e alla fine chiese, perplessa."
  },
  AvgDialog_21803_Content_1 = {
    Text = "Palazzo Sottomarino"
  },
  AvgDialog_21803_Content_10 = {
    Text = "Davvero! Grazie, nonnina!"
  },
  AvgDialog_21803_Content_11 = {
    Text = "Nonna Betty consolò rapidamente Aurita e osservò la bambina saltellare tra le rovine vicine prima di rivolgersi a te con un sorriso."
  },
  AvgDialog_21803_Content_12 = {
    Text = "Perché hai mandato via Aurita di proposito? Cosa vuoi dirmi?"
  },
  AvgDialog_21803_Content_13 = {
    Text = "Non stare così in guardia, voglio solo... raccontare una storia."
  },
  AvgDialog_21803_Content_14 = {
    Text = "Un tempo, questo era un porto di pescatori. Alcuni giovani ambiziosi andarono in città, mentre altri restarono a casa a pescare... Era tranquillo come qualsiasi altro villaggio di pescatori."
  },
  AvgDialog_21803_Content_15 = {
    Text = "I cambiamenti avvennero in silenzio, lasciando indietro solo donne e bambini."
  },
  AvgDialog_21803_Content_16 = {
    Text = "Le barche da pesca salpano, ma solo chiglie spezzate tornano a riva trasportate dalla corrente."
  },
  AvgDialog_21803_Content_17 = {
    Text = "L'acqua nera trabocca dalla diga, erodendo le strade fino a ridurle in rovine."
  },
  AvgDialog_21803_Content_18 = {
    Text = "Quando Aurita se ne rese conto, i suoi compagni di giochi, la sua famiglia e persino tutti gli abitanti della città erano svaniti senza lasciare traccia..."
  },
  AvgDialog_21803_Content_19 = {
    Text = "Aspetta, e tu, nonnina?"
  },
  AvgDialog_21803_Content_2 = {
    Text = "L'anziana donna, che si era presentata come Betty, ti osserva sorridendo, valutando sottilmente se sei degno di essere amico di Aurita."
  },
  AvgDialog_21803_Content_20 = {
    Text = "Scuote la testa, facendoti cenno di guardare la parte inferiore del suo corpo."
  },
  AvgDialog_21803_Content_21 = {
    Text = [[
La D-melma fuoriusciva da sotto la sua gonna di lino.
La parte inferiore del suo corpo era quasi interamente immersa nella dissoluzione e nell'illusione.]]
  },
  AvgDialog_21803_Content_22 = {Text = "?!"},
  AvgDialog_21803_Content_23 = {
    Text = "Come ti senti adesso?"
  },
  AvgDialog_21803_Content_24 = {
    Text = "La vecchia ridacchiò e ti diede una pacca sulla spalla, proprio come farebbe una vera anziana."
  },
  AvgDialog_21803_Content_25 = {
    Text = "Non aver paura, piccolo. Non aver paura."
  },
  AvgDialog_21803_Content_26 = {
    Text = "\"Nonna Betty\" è scomparsa da tempo; è l'ossessione della bambina che mi ha tenuta qui."
  },
  AvgDialog_21803_Content_27 = {
    Text = "Mentre parlavano, una folata di vento portò un volantino da chissà dove.\nLa maggior parte dei disegni sul foglio era annerita dalla D-melma, ma gli slogan erano ancora vagamente leggibili."
  },
  AvgDialog_21803_Content_28 = {
    Text = "\"Panetteria di Betty, pane fatto in casa dalla nonna del paese\""
  },
  AvgDialog_21803_Content_29 = {
    Text = "Oh cielo... sembra che \"Betty\" potrebbe non essere nemmeno il mio vero nome."
  },
  AvgDialog_21803_Content_3 = {
    Text = "Dopo un lungo momento, distolse lo sguardo e diede un colpetto sulla schiena di Aurita."
  },
  AvgDialog_21803_Content_30 = {
    Text = "...Perché mi stai raccontando queste cose?"
  },
  AvgDialog_21803_Content_31 = {
    Text = "Nonna Betty lanciò un'occhiata al vecchio edificio crollato poco distante, dove Aurita stava \"cacciando tesori,\" sollevando una nuvola di polvere."
  },
  AvgDialog_21803_Content_32 = {
    Text = "Ho raccontato ad Aurita molte bugie per evitare di rattristarla."
  },
  AvgDialog_21803_Content_33 = {
    Text = "Per esempio..."
  },
  AvgDialog_21803_Content_34 = {
    Text = "\"La casa nel mare\""
  },
  AvgDialog_21803_Content_35 = {
    Text = "Te l'ha davvero raccontato? Sembra che creda davvero a questa storia...\nMa a parte tessere bugie, cos'altro può fare la sua vera suocera?"
  },
  AvgDialog_21803_Content_36 = {
    Text = "Possiamo dirle che i suoi genitori non torneranno mai?\nIn questa città senza futuro, parole simili sono troppo crudeli."
  },
  AvgDialog_21803_Content_37 = {
    Text = "Quindi, ho una richiesta... Per favore, ti prego, tieni il segreto con lei."
  },
  AvgDialog_21803_Content_38 = {
    Text = "Non dirle cosa sta succedendo nella realtà... Almeno, lascia che se ne vada con il cuore felice."
  },
  AvgDialog_21803_Content_39 = {
    Text = "Questo è il mio desiderio, e... anche il suo."
  },
  AvgDialog_21803_Content_4 = {
    Text = "Aurita, potresti andare a giocare da sola per un po'?\nLa nonna chiacchiererà con questo nuovo amico e verrà a cercarti presto."
  },
  AvgDialog_21803_Content_40 = {
    Text = "Il tono di Nonna Betty era sincero, quasi implorante."
  },
  AvgDialog_21803_Content_41 = {Text = "Andarsene?"},
  AvgDialog_21803_Content_42 = {
    Text = "Non c'è assolutamente niente di niente!"
  },
  AvgDialog_21803_Content_43 = {
    Text = "La nonna ha davvero nascosto la statuina di argilla laggiù? Aurita ha messo tutto sottosopra!"
  },
  AvgDialog_21803_Content_44 = {
    Text = "La voce cupa di Aurita attirò la tua attenzione; era in piedi sulle rovine, dandoti le spalle.\nQuesta volta, finalmente notasti una fugace macchia nera sulla sua schiena."
  },
  AvgDialog_21803_Content_45 = {
    Text = "Un buco spalancato domina il suo piccolo corpo — chiaramente un grande D-marchio."
  },
  AvgDialog_21803_Content_46 = {
    Text = "Sussultasti e ti voltasti a guardare il punto in cui \"Nonna Betty\" si trovava poco prima.\nTutto ciò che restava era una pozza di liquido viscoso, che si fondeva con l'acqua scura e stagnante."
  },
  AvgDialog_21803_Content_47 = {
    Text = "Nelle acque di scolo, la ceramica riflette una luce morbida e calda."
  },
  AvgDialog_21803_Content_48 = {
    Text = "Raccogli la statuina"
  },
  AvgDialog_21803_Content_49 = {
    Text = "Inaspettatamente, dopo la scomparsa di \"Nonna Betty\", ciò che rimase non era una statuetta d'argilla con le sembianze di una vecchia donna."
  },
  AvgDialog_21803_Content_5 = {
    Text = "Non posso chiacchierare con Aurita?"
  },
  AvgDialog_21803_Content_50 = {
    Text = "Una cupola rotonda e paffuta con tentacoli fini e fitti, decorata con smalto blu a forma di trifoglio su una base bianco porcellana."
  },
  AvgDialog_21803_Content_51 = {
    Text = "Wow — è la medusa preferita di Aurita!"
  },
  AvgDialog_21803_Content_52 = {
    Text = "Hai barato davvero! Hai ingannato Aurita facendola guardare laggiù, ma ce l'avevi chiaramente tra le mani!"
  },
  AvgDialog_21803_Content_53 = {
    Text = "Non, non arrabbiarti... Guarda, cosa sono questi?"
  },
  AvgDialog_21803_Content_54 = {
    Text = "Riesci a forzare un sorriso tirato, estraendo dalla tasca \"Poni\" e \"Biancaneve\", e li consegni ad Aurita insieme alla statuetta della \"Medusa.\""
  },
  AvgDialog_21803_Content_55 = {
    Text = "Tutti per Aurita?! Grazie, amico mio!"
  },
  AvgDialog_21803_Content_56 = {
    Text = "La vasca d'acqua ~L'acquario di Aurita~"
  },
  AvgDialog_21803_Content_57 = {
    Text = "Palazzo~Gli amici e il palazzo nell'acqua~"
  },
  AvgDialog_21803_Content_58 = {
    Text = "Aurita canticchiava una canzone, persa nella gioia del suo nuovo giocattolo. Werther, Poni, Biancaneve e Nonna Betty sembravano non aver lasciato alcun segno nel suo cuore."
  },
  AvgDialog_21803_Content_59 = {
    Text = "Uff... Uff... Va bene a tutti stare in piedi così?"
  },
  AvgDialog_21803_Content_6 = {
    Text = "Tesoro, le conversazioni tra adulti potrebbero annoiarti. Non è forse la nostra piccola Aurita quella che odia di più la noia?"
  },
  AvgDialog_21803_Content_60 = {
    Text = "Sposta \"Poni\" un po' più fuori; avere un cavallo in casa fa un certo effetto."
  },
  AvgDialog_21803_Content_61 = {
    Text = "Molto ragionevole! A proposito, l'hai chiamato \"Poni\"?"
  },
  AvgDialog_21803_Content_62 = {Text = "..."},
  AvgDialog_21803_Content_63 = {
    Text = "Il Palazzo di Aurita è pronto!"
  },
  AvgDialog_21803_Content_64 = {
    Text = "La futura casa di Aurita, la sua casa sott'acqua..."
  },
  AvgDialog_21803_Content_65 = {
    Text = "Aurita vuole dormire nella stanza accanto a mamma e papà e ogni tanto dormire con loro!"
  },
  AvgDialog_21803_Content_66 = {
    Text = "Il cagnolino vuole dormire sul letto di Aurita, il pony in salotto — o in giardino."
  },
  AvgDialog_21803_Content_67 = {
    Text = "Le meduse possono fluttuare ovunque, e gli amici di Aurita bevono tutti cioccolata calda accanto al camino..."
  },
  AvgDialog_21803_Content_68 = {
    Text = "Hmm... sott'acqua... si può accendere il camino?"
  },
  AvgDialog_21803_Content_69 = {
    Text = "Gli occhi di Aurita sbatterono le palpebre, rivelando un accenno di sonnolenza. Fece un lungo sbadiglio, e il suo sguardo divenne offuscato."
  },
  AvgDialog_21803_Content_7 = {
    Text = "Sniff...sob... Ma voglio restare con la nonnina..."
  },
  AvgDialog_21803_Content_70 = {
    Text = "Aurita è stanca?"
  },
  AvgDialog_21803_Content_71 = {
    Text = "Aurita... può ancora... giocare..."
  },
  AvgDialog_21803_Content_72 = {
    Text = "Dormi bene, Aurita."
  },
  AvgDialog_21803_Content_73 = {
    Text = "Il camino brucerà caldo e accogliente."
  },
  AvgDialog_21803_Content_74 = {
    Text = "Nella cioccolata servita ci sarà tanto zucchero."
  },
  AvgDialog_21803_Content_75 = {
    Text = "Quando ti sveglierai, tutti i tuoi amici saranno lì."
  },
  AvgDialog_21803_Content_76 = {
    Text = "Uff... amica..."
  },
  AvgDialog_21803_Content_77 = {
    Text = "Non... lasciare Aurita da sola..."
  },
  AvgDialog_21803_Content_8 = {
    Text = "Brava bambina, ti va di giocare a un gioco con la nonnina?"
  },
  AvgDialog_21803_Content_9 = {
    Text = "Aurita vuole decorare le case dei suoi amici, vero? La nonnina ha nascosto diverse statuine d'argilla qui vicino... Se Aurita le trova, sono tutte sue."
  },
  AvgDialog_21805_Content_1 = {
    Text = "Giorno Silente"
  },
  AvgDialog_21805_Content_10 = {
    Text = "Oh... No! L'acqua all'interno non è potabile! Ne hai già bevuta tantissima."
  },
  AvgDialog_21805_Content_11 = {
    Text = "Stavo quasi annegando; non era solo per aver bevuto acqua."
  },
  AvgDialog_21805_Content_12 = {
    Text = "Di fronte all'espressione innocente e imbronciata della ragazza, senti un dolore acuto ai polmoni. Dopo aver fatto diversi respiri profondi, la ragione finalmente riempie di nuovo la tua mente."
  },
  AvgDialog_21805_Content_13 = {
    Text = "Con la volontà e la memoria in risonanza, ti rendesti finalmente conto che, ancora una volta, eri entrato nella memoria del Risvegliatore—"
  },
  AvgDialog_21805_Content_14 = {
    Text = "Annegare... annegare..."
  },
  AvgDialog_21805_Content_15 = {
    Text = "Aurita è un'eccellente nuotatrice! Diventa amico di Aurita e non annegherai mai più!"
  },
  AvgDialog_21805_Content_16 = {
    Text = "Aurita si affaccendava intorno al letto, agitandosi mentre cercava di accendere la stufa della stanza."
  },
  AvgDialog_21805_Content_17 = {
    Text = "Mentre la ragazza tossiva per la cenere, la stanza si riscaldò gradualmente. I vestiti umidi emettevano fili di vapore, e le sue membra congelate iniziarono a sgelarsi."
  },
  AvgDialog_21805_Content_18 = {
    Text = "Aurita... tu sei Aurita, quindi questa è casa tua..."
  },
  AvgDialog_21805_Content_19 = {
    Text = "Hmm! Questa è la casa di Aurita, e tu sei un ospite che Aurita ha invitato dal mare!"
  },
  AvgDialog_21805_Content_2 = {
    Text = "*Cough... cough!*"
  },
  AvgDialog_21805_Content_20 = {
    Text = "Frammenti di memorie corporee affiorano, e gradualmente arrivi a comprendere il ruolo che interpreti in questo sogno—"
  },
  AvgDialog_21805_Content_21 = {
    Text = "Nella tempesta, un membro dell'equipaggio cadde in mare e fu gentilmente portato a riva dalle onde. Alla fine, la ragazza davanti a lui lo trascinò a casa..."
  },
  AvgDialog_21805_Content_22 = {
    Text = "Un'identità così ordinaria."
  },
  AvgDialog_21805_Content_23 = {
    Text = "Ti sei gradualmente abituato all'esperienza surreale di \"entrare nei sogni\". In genere, finché hai assistito ai ricordi che formano questo sogno, ti sveglierai al momento giusto."
  },
  AvgDialog_21805_Content_24 = {
    Text = "Il problema attuale è che non puoi confermare la \"memoria\" di Aurita."
  },
  AvgDialog_21805_Content_25 = {
    Text = "La \"memoria\" di Aurita è un mistero. La Dissoluzione ha divorato il suo passato prima che fosse risvegliata, rendendo difficile trovare abbastanza dettagli dalle sue parole infantili per ricostruire il quadro completo."
  },
  AvgDialog_21805_Content_26 = {
    Text = "Questo potrebbe essere il momento perfetto per colmare le lacune nei registri di Aurita."
  },
  AvgDialog_21805_Content_27 = {
    Text = "Che c'è? Perché non hai detto nulla per così tanto tempo?"
  },
  AvgDialog_21805_Content_28 = {
    Text = "Se non vuoi giocare con Aurita, posso accompagnarti via..."
  },
  AvgDialog_21805_Content_29 = {
    Text = "Te ne vai già così presto?"
  },
  AvgDialog_21805_Content_3 = {
    Text = "Sotto il colpo violento, il liquido fu espulso dalle vie respiratorie, e l'acqua salata del mare risalì inaspettatamente la gola, eseguendo un vivace cancan sulla lingua."
  },
  AvgDialog_21805_Content_30 = {
    Text = "Accompagnare... l'ospite?"
  },
  AvgDialog_21805_Content_31 = {
    Text = "Vuoi dire che giocherai con Aurita!"
  },
  AvgDialog_21805_Content_32 = {
    Text = [[
Fantastico, fantastico, fantastico!
Nuovi ospiti, nuovi amici, unitevi ai <Yellow:nuovi compagni di Aurita nell'acquario>!]]
  },
  AvgDialog_21805_Content_33 = {Text = "Acquario?"},
  AvgDialog_21805_Content_34 = {
    Text = "Acquario? Potrebbe essere che ti riferisci a quella vasca di vetro?"
  },
  AvgDialog_21805_Content_35 = {
    Text = "Aurita sta preparando la loro nuova casa!"
  },
  AvgDialog_21805_Content_36 = {
    Text = "La ragazza salutò con entusiasmo, e finalmente desti un'occhiata da vicino alla vasca di vetro piena d'acqua accanto alla finestra—"
  },
  AvgDialog_21805_Content_37 = {
    Text = [[
Presenta uno squisito paesaggio di castelli, ma le increspature generate dal ciclo della vita non si trovano da nessuna parte.
Non sembra essere altro che una fiaba sommersa.]]
  },
  AvgDialog_21805_Content_38 = {
    Text = "Nuovi compagni?"
  },
  AvgDialog_21805_Content_39 = {
    Text = "Sì! I nuovi amici di Aurita! Quando Aurita tornerà al mare per ricongiungersi con la sua famiglia, tutti i suoi amici potranno venire a trovarla."
  },
  AvgDialog_21805_Content_4 = {
    Text = "Wow! Hai ingoiato tantissima acqua!"
  },
  AvgDialog_21805_Content_40 = {
    Text = "Distesa su un morbido giaciglio, le parole di Aurita ti provocano comunque un brivido lungo la schiena senza un motivo apparente."
  },
  AvgDialog_21805_Content_41 = {
    Text = "È solo allora che te ne rendi conto — c'è troppo silenzio."
  },
  AvgDialog_21805_Content_42 = {
    Text = [[
Il suono degli insetti che friniscono, del vento che soffia, delle foglie che si scontrano tra loro...
Il suono delle chiacchiere, delle risate, delle suole delle scarpe che sfregano sulla strada...]]
  },
  AvgDialog_21805_Content_43 = {
    Text = "Il mondo è avvolto in un silenzio mortale; solo Aurita, la padrona dei sogni, è viva."
  },
  AvgDialog_21805_Content_44 = {
    Text = "Aurita... Vive qui da sola?"
  },
  AvgDialog_21805_Content_45 = {
    Text = "Da sola? No! Werther, Biancaneve, Poni... tutti gli amici di Aurita sono in città! E poi la Nonnina... la <Yellow:Nonnina> di Aurita vive anche lei qui!"
  },
  AvgDialog_21805_Content_46 = {
    Text = "Oh, giusto! La Nonnina! La Nonnina ha detto che se Aurita fa un nuovo amico, deve presentarglielo!"
  },
  AvgDialog_21805_Content_47 = {
    Text = "Al menzionare la \"Nonnina\", gli occhi di Aurita si illuminano. Salta di nuovo accanto al letto, cercando di tirarti su, ma si blocca improvvisamente come se si fosse ricordata di qualcosa."
  },
  AvgDialog_21805_Content_48 = {
    Text = "Vuoi altra acqua?"
  },
  AvgDialog_21805_Content_49 = {
    Text = "Sto annegando..."
  },
  AvgDialog_21805_Content_5 = {
    Text = "L'odore di acqua di mare e sangue riempie le tue narici troppo inzuppate. Con un colpo di tosse violento, persino sabbia grossa viene espulsa dal profondo."
  },
  AvgDialog_21805_Content_50 = {
    Text = "Mi piacerebbe conoscere anche la famiglia di Aurita. Aurita può portarmi dalla sua nonnina?"
  },
  AvgDialog_21805_Content_51 = {
    Text = "Hmm! La Nonnina dovrebbe essere nella piazza centrale!"
  },
  AvgDialog_21805_Content_52 = {
    Text = "Aurita scese saltellando al piano di sotto, e tu, senza più esitare, ti desti qualche pacca sulle guance per svegliarti del tutto."
  },
  AvgDialog_21805_Content_53 = {
    Text = "Fuori sta iniziando a piovere—"
  },
  AvgDialog_21805_Content_54 = {
    Text = "La voce di Aurita arriva dall'esterno; il suo tono cristallino e vivace è meno distinto attraverso la porta di legno."
  },
  AvgDialog_21805_Content_55 = {
    Text = "Fai un respiro profondo, spingi la porta e lasci il piccolo edificio dove vive Aurita."
  },
  AvgDialog_21805_Content_56 = {
    Text = "La casa si inclinava mentre veniva divorata dal terreno, con una sottile nebbia nera che fluiva sia dalle montagne lontane sia dai corsi d'acqua fluttuanti nelle vicinanze."
  },
  AvgDialog_21805_Content_57 = {
    Text = "Davanti ai tuoi occhi si stende una città inghiottita dalla Dissoluzione—"
  },
  AvgDialog_21805_Content_58 = {
    Text = "Ad Aurita piace la pioggerellina leggera; è fresca e rinfrescante!"
  },
  AvgDialog_21805_Content_59 = {
    Text = "Hmm... ma cerchiamo comunque un ombrello per te."
  },
  AvgDialog_21805_Content_6 = {
    Text = "Cosa è successo..."
  },
  AvgDialog_21805_Content_60 = {
    Text = "Tutto è silenzioso, avvolto nell'oscurità.\nNel caos, solo la figura di Aurita rimaneva vivida."
  },
  AvgDialog_21805_Content_7 = {
    Text = "Aprendo lentamente gli occhi, vedi un soffitto sconosciuto."
  },
  AvgDialog_21805_Content_8 = {
    Text = "Vecchio, ordinato, ma privo di carattere. Solo una vasca di vetro piena d'acqua lo fa sembrare meno simile a una normale stanza d'albergo."
  },
  AvgDialog_21805_Content_9 = {
    Text = "Cosa stai guardando? Le case degli amici di Aurita?"
  },
  AvgDialog_21813_Content_1 = {
    Text = [[
...@2...Torre...
@4]]
  },
  AvgDialog_21813_Content_10 = {
    Text = "Eh...? Come si chiamava...?"
  },
  AvgDialog_21813_Content_11 = {Text = "..."},
  AvgDialog_21813_Content_12 = {
    Text = "Aurita, non dimenticare, dobbiamo andare alla piazza centrale a cercare tua nonna."
  },
  AvgDialog_21813_Content_13 = {
    Text = "Giusto! Andiamo da questa parte—"
  },
  AvgDialog_21813_Content_14 = {
    Text = "Aurita si lasciò rapidamente alle spalle l'amichetto \"fuggitivo\" e ti spinse verso la destinazione."
  },
  AvgDialog_21813_Content_15 = {
    Text = "Aggiri la pozza di D-melma che un tempo era \"Werther,\" provando un groviglio di emozioni."
  },
  AvgDialog_21813_Content_16 = {
    Text = "Vivere in una città consumata dalla Dissoluzione, eppure incapace di vederne o percepirne la presenza."
  },
  AvgDialog_21813_Content_17 = {
    Text = "Il suo mondo sta morendo, eppure lei resta... completamente ignara."
  },
  AvgDialog_21813_Content_2 = {
    Text = "Il corpo mutato cadde rigidamente, come cuoio troppo conciato, fondendosi con la D-melma sul terreno e infine scomparendo dalla vista."
  },
  AvgDialog_21813_Content_3 = {
    Text = "Eh...? E Werther?"
  },
  AvgDialog_21813_Content_4 = {
    Text = "Com'è sparito così in fretta! Aurita chiaramente non stava giocando a nascondino..."
  },
  AvgDialog_21813_Content_5 = {
    Text = "Sul pavimento dove un tempo sedeva \"Werther\", giace un piccolo strillone di ceramica."
  },
  AvgDialog_21813_Content_6 = {Text = "..."},
  AvgDialog_21813_Content_7 = {
    Text = "Aurita, Werther ti ha lasciato un regalo."
  },
  AvgDialog_21813_Content_8 = {
    Text = "Non ci credo—Wow! È l'ornamento promesso ad Aurita!"
  },
  AvgDialog_21813_Content_9 = {
    Text = "Aurita vuole metterlo nelle case dei suoi amici! Grazie, grazie..."
  },
  AvgDialog_21814_Content_1 = {
    Text = "Ah! È Werther!"
  },
  AvgDialog_21814_Content_10 = {
    Text = "Quando Aurita tornerà, porteremo sicuramente tutti a fare visita."
  },
  AvgDialog_21814_Content_11 = {
    Text = "Prima che potessi riflettere sul sottile gelo nelle parole di Aurita, l'\"amico\" di Aurita si mosse improvvisamente."
  },
  AvgDialog_21814_Content_12 = {
    Text = "...@2...Torre"
  },
  AvgDialog_21814_Content_13 = {
    Text = "Il ragazzo si alzò barcollando, un liquido nero gli colava addosso.\nLa D-melma lo incollava al suolo, e il suono della carne che si lacerava mentre si alzava era terrificante."
  },
  AvgDialog_21814_Content_14 = {
    Text = "Certo! Werther, non preoccuparti. Ti riserverò sicuramente la stanza più lussuosa!"
  },
  AvgDialog_21814_Content_15 = {
    Text = "Sotto quella pelle pallida, i muscoli pulsano in modo strano, come se qualcosa stesse per erompere—"
  },
  AvgDialog_21814_Content_16 = {
    Text = "Aurita, attenta!"
  },
  AvgDialog_21814_Content_2 = {
    Text = "La ragazza ti dà una pacca decisa sulla schiena e, al suo gesto, rivolgi lo sguardo verso il ragazzo seduto all'angolo della strada."
  },
  AvgDialog_21814_Content_3 = {
    Text = "Aurita corse da lui con entusiasmo, rivelando una macchia scura sulla schiena.\nMa prima che potessi vederla bene, sfrecciò via come il vento."
  },
  AvgDialog_21814_Content_4 = {
    Text = "Witt, dai un'occhiata al nostro nuovo amico!"
  },
  AvgDialog_21814_Content_5 = {
    Text = "Il ragazzo era rannicchiato nell'angolo, a testa bassa, e non mostrò alcuna reazione all'avvicinarsi di Aurita."
  },
  AvgDialog_21814_Content_6 = {
    Text = "{Male=Lui,Female=Lei} è più alt{Male=o,Female=a} di tutti, quando faremo ritorno al palazzo oceanico, facciamo{Male=lo,Female=la} andare in testa! Sicuramente molto imponente!"
  },
  AvgDialog_21814_Content_7 = {
    Text = "Palazzo dell'Oceano?"
  },
  AvgDialog_21814_Content_8 = {
    Text = "La Nonnina ha detto che Aurita è una figlia del mare, e che un giorno dovremo tornare nell'acqua."
  },
  AvgDialog_21814_Content_9 = {
    Text = "Come i genitori di Aurita, loro sono andati avanti per preparare la nuova casa sott'acqua! Una volta che tutto sarà pronto, Aurita si ricongiungerà con loro insieme alla sua nonnina."
  },
  AvgDialog_21815_Content_1 = {
    Text = "Aurita ti spinge attraverso la città in rovina; col passare del tempo, il cielo già coperto si fa ancora più scuro."
  },
  AvgDialog_21815_Content_10 = {
    Text = "Sì! Trasformati in un cavalluccio marino!"
  },
  AvgDialog_21815_Content_11 = {
    Text = "Mentre parlava, si udivano lì vicino nitriti e il respiro pesante di cavalli. Il cupo battere degli zoccoli rendeva difficile capire se \"Poni\" fosse un altro Dissoluto."
  },
  AvgDialog_21815_Content_12 = {
    Text = "Poni? Poni—"
  },
  AvgDialog_21815_Content_13 = {Text = "Hiss—"},
  AvgDialog_21815_Content_14 = {
    Text = "Questa volta eri preparato e afferrasti rapidamente il colletto di Aurita, impedendole di lanciarsi verso il gigante scheletrico."
  },
  AvgDialog_21815_Content_2 = {
    Text = "Aurita, quanto manca alla piazza?"
  },
  AvgDialog_21815_Content_3 = {
    Text = "La ragazzina ti sale sulla schiena, si guarda intorno con cautela e infine indica un angolo."
  },
  AvgDialog_21815_Content_4 = {
    Text = "Laggiù! Dopo la stalla, 50 metri a nord!"
  },
  AvgDialog_21815_Content_5 = {
    Text = "Qui una volta allevavano cavalli?"
  },
  AvgDialog_21815_Content_6 = {
    Text = "Adesso sì! Anche «Poni» è mio amico, e voglio riportarlo a casa sua, nel mare!"
  },
  AvgDialog_21815_Content_7 = {
    Text = "In quel momento, Poni si trasformerà in..."
  },
  AvgDialog_21815_Content_8 = {
    Text = "Trasformarsi in..."
  },
  AvgDialog_21815_Content_9 = {
    Text = "Trasformarsi in un cavalluccio marino?"
  },
  AvgDialog_21816_Content_1 = {
    Text = "Biancaneve! È Biancaneve!"
  },
  AvgDialog_21816_Content_2 = {
    Text = "Aurita sgattaiolò di nuovo via, correndo verso qualcosa che giaceva nella D-melma—"
  },
  AvgDialog_21816_Content_3 = {
    Text = "Un cucciolo nero."
  },
  AvgDialog_21816_Content_4 = {
    Text = "B-Biancaneve?"
  },
  AvgDialog_21817_Content_1 = {
    Text = "Le prime due volte sono stati lasciati dei piccoli giocattoli, quindi questa volta non dovrebbe essere diverso..."
  },
  AvgDialog_21817_Content_2 = {
    Text = "Con noncuranza hai raccolto un forcone dalla stalla e hai rimestato la D-melma che un tempo era \"Poni\". Come previsto, un pony di ceramica particolarmente squisito brillava alla luce."
  },
  AvgDialog_21817_Content_3 = {
    Text = "Raccogli \"Poni\""
  },
  AvgDialog_21817_Content_4 = {
    Text = "Esiti un momento, ma alla fine ti togli il cappotto e raccogli il pony di ceramica attraverso il tessuto."
  },
  AvgDialog_21817_Content_5 = {
    Text = "Cosa stai facendo?"
  },
  AvgDialog_21817_Content_6 = {
    Text = "Quando ormai ti eri quasi abituato alla voce di Aurita che riempiva il mondo desolato, una voce canuta risuonò all'improvviso, facendoti raddrizzare di soprassalto."
  },
  AvgDialog_21817_Content_7 = {
    Text = "Nonnina—Aurita ha portato un nuovo amico da presentarti!"
  },
  AvgDialog_21817_Content_8 = {
    Text = "Il volto anziano si illuminò con un sorriso gentile. Accarezzò affettuosamente la testa di Aurita prima di rivolgersi a te."
  },
  AvgDialog_21817_Content_9 = {
    Text = "Salve, giovane. Sono Nonna Betty, la nonna di Aurita. Chiamami Nonnina, come fa questa bambina."
  },
  AvgDialog_21818_Content_1 = {
    Text = "Biancaneve emette un debole guaito, le sue membra si dissolvono gradualmente in D-melma, non conservando più la sua forma canina."
  },
  AvgDialog_21818_Content_2 = {
    Text = "Dove \"Biancaneve\" era svanita, un cucciolo di ceramica bianca grande quanto un palmo giaceva silenzioso."
  },
  AvgDialog_21818_Content_3 = {
    Text = "Raccogli \"Biancaneve\""
  },
  AvgDialog_21818_Content_4 = {
    Text = "Quindi sei davvero bianco..."
  },
  AvgDialog_21875_Content_1 = {
    Text = "Sembra che la trappola l'abbia preso."
  },
  AvgDialog_21875_Content_2 = {
    Text = "Usa questi attrezzi per immobilizzarlo!"
  },
  AvgDialog_22111_Content_1 = {Text = "Ah!—"},
  AvgDialog_22111_Content_10 = {
    Text = "Là... là c'è..."
  },
  AvgDialog_22111_Content_100 = {
    Text = "Non capisco... Che senso ha qualcosa che nessuno riesce a comprendere?"
  },
  AvgDialog_22111_Content_101 = {
    Text = "Hmm... Credo che la poesia non sia solo parole o immagini; è come una chiave."
  },
  AvgDialog_22111_Content_102 = {
    Text = "Una... chiave?"
  },
  AvgDialog_22111_Content_103 = {
    Text = "Sì! Il cuore di una persona è come uno scrigno colmo di emozioni. Questo scrigno è chiuso a chiave, e queste emozioni di solito restano dentro, difficili da tirare fuori."
  },
  AvgDialog_22111_Content_104 = {
    Text = "La poesia è la chiave per aprire questo scrigno."
  },
  AvgDialog_22111_Content_105 = {
    Text = "In realtà, la poesia non ha bisogno di essere compresa, e nemmeno letta."
  },
  AvgDialog_22111_Content_106 = {
    Text = "Tutti, che leggano poesia o meno, prima o poi, troveranno questa chiave in qualche momento della loro vita."
  },
  AvgDialog_22111_Content_107 = {
    Text = "Diventerai sicuramente la migliore fabbra di chiavi!"
  },
  AvgDialog_22111_Content_108 = {
    Text = "Bugiarda... Hai appena detto che non capivi."
  },
  AvgDialog_22111_Content_109 = {
    Text = "Non capisco cosa stai dicendo, ma mi fido di te, Horla."
  },
  AvgDialog_22111_Content_11 = {
    Text = "Vi trovate al margine della piazza del giardino. D-fessure visibili si propagano verso l'alto da sotto il piccolo edificio, avvolgendo lo spazio aperto al centro del giardino."
  },
  AvgDialog_22111_Content_110 = {
    Text = "Questo poema, \"La Dimora delle Rose\", è la tua prima opera. Da oggi in poi, ti aiuterò a custodire tutti i tuoi poemi."
  },
  AvgDialog_22111_Content_111 = {
    Text = "Li terrò insieme con degli spilli, e quando avrò i soldi, stamperò una bella raccolta di poesie!"
  },
  AvgDialog_22111_Content_112 = {
    Text = "Tese la mano, che aveva tenuto nascosta dietro la schiena. Le mani erano coperte di ferite di spine, scure e ruvide, del tutto irriconoscibili come quelle di una bambina."
  },
  AvgDialog_22111_Content_113 = {
    Text = "Questo... questo è..."
  },
  AvgDialog_22111_Content_114 = {
    Text = "I nuovi nobili dicono che Cité sia una città di fiori e poesia. Un buon poema può farti guadagnare un bouquet di rose..."
  },
  AvgDialog_22111_Content_115 = {
    Text = "Le mie rose sono fiorite oggi. Non molte, e sono state tutte usate per pagare l'affitto e il canone del terreno."
  },
  AvgDialog_22111_Content_116 = {
    Text = "Ma mentre non prestavano attenzione, ho tenuto un fiore di nascosto..."
  },
  AvgDialog_22111_Content_117 = {
    Text = "Quella mano sfregiata porse a Horla una rosa leggermente danneggiata, ma ancora di un rosso vivido."
  },
  AvgDialog_22111_Content_118 = {
    Text = "Un bel poema, Horla... In futuro, scambierò i miei fiori con i tuoi poemi!"
  },
  AvgDialog_22111_Content_12 = {
    Text = "Quello è... il nostro giardino... no... Colette, no..."
  },
  AvgDialog_22111_Content_13 = {
    Text = "Horla abbassò il capo. Colette le si avvicinò, le sollevò il mento e diresse il suo sguardo verso il centro del giardino."
  },
  AvgDialog_22111_Content_14 = {
    Text = "Sai, Horla... Molti anni fa, ho guardato quel grande incendio divampare proprio qui."
  },
  AvgDialog_22111_Content_15 = {
    Text = "Ho trasformato questo luogo in una piazza e vi ho eretto la mia statua... Vedi, anch'io comprendo il simbolismo."
  },
  AvgDialog_22111_Content_16 = {
    Text = "Guarda attentamente. Guarda bene. Quello è il luogo in cui viviamo... Quello è il nostro giardino. Presto, tutto ciò che vi si trova scomparirà."
  },
  AvgDialog_22111_Content_17 = {
    Text = "La mia vita è davvero iniziata il giorno in cui sei morta. Oggi, si avvierà nuovamente verso lo splendore..."
  },
  AvgDialog_22111_Content_18 = {
    Text = "La fessura nera si propaga rapidamente. In breve, l'intera villa lussuosa viene inghiottita."
  },
  AvgDialog_22111_Content_19 = {
    Text = "Giardino, ceneri, scarabocchi, poesia, memorie, risate, giuramenti... Tutto è sprofondato nell'oscurità senza fine."
  },
  AvgDialog_22111_Content_2 = {
    Text = "Il tuo attacco a sorpresa ha sconfitto con successo il mostro evocato da Colette. Il mondo all'interno del poema tremò, rivelando una porzione della vera forma della Cité."
  },
  AvgDialog_22111_Content_20 = {Text = "Tic-tac—"},
  AvgDialog_22111_Content_21 = {
    Text = "Eh? Cosa hanno i miei occhi...?"
  },
  AvgDialog_22111_Content_22 = {
    Text = "Era... dolore al cuore, poco fa? Perché..."
  },
  AvgDialog_22111_Content_23 = {
    Text = "Una lacrima scivolò lungo il volto di Horla."
  },
  AvgDialog_22111_Content_24 = {
    Text = "Le lacrime cadono a terra, come gocce in un lago immobile. Increspature silenziose si propagano, sfiorando ogni cuore pallido in questo mondo illusorio."
  },
  AvgDialog_22111_Content_25 = {
    Text = "!! No... questa sensazione..."
  },
  AvgDialog_22111_Content_26 = {
    Text = "Colette notò il cambiamento nelle proprie emozioni. Guardò Horla accanto a sé con sorpresa."
  },
  AvgDialog_22111_Content_27 = {
    Text = "<LightGray:Questa è... l'abilità di Horla di propagare le emozioni?!>"
  },
  AvgDialog_22111_Content_28 = {
    Text = "<LightGray:La sua abilità potrebbe rivelarsi utile! Devo cogliere questa opportunità...>"
  },
  AvgDialog_22111_Content_29 = {
    Text = "Vuoi uccidermi e usare la poesia per ottenere la vita che desideri... Qualunque cosa tu abbia fatto, non ti ho mai odiata, Colette."
  },
  AvgDialog_22111_Content_3 = {
    Text = "Ma nell'istante in cui ti sei avvicinato a Colette, innumerevoli rampicanti fioriti sono eruttati dal suolo attorno a lei. Gli spuntoni sui rampicanti hanno perforato i vostri corpi, vincolandovi strettamente."
  },
  AvgDialog_22111_Content_30 = {
    Text = "La Colette che conoscevo un tempo era la mia migliore amica. Ma se distruggi questo luogo... rimarrà soltanto la Colette di adesso."
  },
  AvgDialog_22111_Content_31 = {
    Text = "Non posso... permettere che la Colette che conoscevo un tempo venga cancellata da te..."
  },
  AvgDialog_22111_Content_32 = {
    Text = "Guardati, Horla... Cos'altro sai fare, oltre a scrivere poesie?"
  },
  AvgDialog_22111_Content_33 = {
    Text = "Hai ragione... A parte scrivere poesie, non sono brava in nient'altro..."
  },
  AvgDialog_22111_Content_34 = {
    Text = "Cité, la città di fiori e poesie, è la nostra casa... Ma tutte le rose qui sono appassite, Colette..."
  },
  AvgDialog_22111_Content_35 = {
    Text = "Queste rose sono quelle che un tempo mi donasti. Oggi te le restituisco."
  },
  AvgDialog_22111_Content_36 = {
    Text = "Fa un passo avanti."
  },
  AvgDialog_22111_Content_37 = {Text = "Puf—"},
  AvgDialog_22111_Content_38 = {Text = "Horla!!!"},
  AvgDialog_22111_Content_39 = {
    Text = "Spine aguzze le lacerano i vestiti e le perforano la carne, ma a lei non importa."
  },
  AvgDialog_22111_Content_4 = {
    Text = "Tu... mi hai sporcato i vestiti..."
  },
  AvgDialog_22111_Content_40 = {
    Text = "Un enorme spuntone di rosa le trafisse il cuore. Il suo sangue scorse lungo il ramo nero, oltrepassando la prima diramazione."
  },
  AvgDialog_22111_Content_41 = {
    Text = "I fiori neri avvizziscono rapidamente sui rami. Un bocciolo di rosa rossa appare, si schiude e fiorisce."
  },
  AvgDialog_22111_Content_42 = {
    Text = "Il sangue scorre lungo i rami, come le venature delle foglie, propagandosi in ogni angolo della città."
  },
  AvgDialog_22111_Content_43 = {
    Text = "Dove passava, l'oscurità profonda svaniva. Restituì colore ed emozione, fiori e poesia a Cité."
  },
  AvgDialog_22111_Content_44 = {
    Text = "Così... tanto dolore..."
  },
  AvgDialog_22111_Content_45 = {
    Text = "Il cuore... sembra trafitto..."
  },
  AvgDialog_22111_Content_46 = {
    Text = "Quella è... la Madre! Madre..."
  },
  AvgDialog_22111_Content_47 = {
    Text = "Il bambino... il mio bambino è nato..."
  },
  AvgDialog_22111_Content_48 = {
    Text = "Mentre il sangue si propaga, visioni si dispiegano davanti agli occhi della gente."
  },
  AvgDialog_22111_Content_49 = {
    Text = "È la rinascita dalla terra del neonato, la ninnananna della madre e l'addio degli amanti."
  },
  AvgDialog_22111_Content_5 = {
    Text = "Sai quanto è costato questo abito?"
  },
  AvgDialog_22111_Content_50 = {
    Text = "Quello è stato il momento più prezioso delle vostre vite."
  },
  AvgDialog_22111_Content_52 = {
    Text = "L'immenso dolore che Horla sopportò si propagò per tutta Cité, increspandosi con il suo sangue."
  },
  AvgDialog_22111_Content_53 = {
    Text = "Spuntoni di rosa perforano innumerevoli cuori. Fiori cremisi sbocciano in ognuno di essi."
  },
  AvgDialog_22111_Content_54 = {
    Text = "Colette, possiedi tutta Cité, eppure vivi ancora qui."
  },
  AvgDialog_22111_Content_55 = {
    Text = "Vivere nella casa che un tempo sognavamo, nel giardino dove un tempo vivevamo insieme..."
  },
  AvgDialog_22111_Content_56 = {
    Text = "Una volta mi hai salvato la vita. Questa poesia, scritta con la vita, è per te e per il giardino."
  },
  AvgDialog_22111_Content_57 = {
    Text = "Questo è un poema scritto per il giardino in primavera."
  },
  AvgDialog_22111_Content_58 = {
    Text = "Horla... tu..."
  },
  AvgDialog_22111_Content_59 = {
    Text = "Le lacrime lavarono via il suo trucco delicato, ma non le importava, lasciando che tracciassero segni disordinati sul suo volto."
  },
  AvgDialog_22111_Content_6 = {
    Text = "La rabbia di Colette svanì rapidamente. Riprese il suo sorriso nobile e composto."
  },
  AvgDialog_22111_Content_60 = {
    Text = "Colette non ricordava quando le sue lacrime avessero cominciato a scorrere."
  },
  AvgDialog_22111_Content_61 = {
    Text = "—Scene del passato si dispiegano nitide davanti a lei. Per la prima volta, comprese davvero la poesia di Horla. Finalmente capì ciò che custodiva nel profondo del cuore."
  },
  AvgDialog_22111_Content_62 = {
    Text = "Non solo lei. Tutti nella Cité compresero la poesia di Horla. Furono sopraffatti dalle emozioni di Horla, incapaci di muoversi."
  },
  AvgDialog_22111_Content_63 = {Text = "È adesso!"},
  AvgDialog_22111_Content_64 = {
    Text = "Eri ben preparato: il tuo potente Potere spirituale ti ha permesso di liberarti dalle emozioni di Horla."
  },
  AvgDialog_22111_Content_65 = {
    Text = "Ti liberi dalle spine e strappi la raccolta di poesie dalle mani di Colette."
  },
  AvgDialog_22111_Content_66 = {
    Text = "Addio... Cité dei poemi!"
  },
  AvgDialog_22111_Content_67 = {
    Text = "Un lampo d'Argento. Sotto una luce intensa, il D-segno sulla poesia evapora e si dissolve rapidamente."
  },
  AvgDialog_22111_Content_68 = {Text = "Ugh! —"},
  AvgDialog_22111_Content_69 = {
    Text = "Un dolore acuto ti colpisce. La grave perdita di Potere spirituale ti sopraffà."
  },
  AvgDialog_22111_Content_7 = {
    Text = "Va tutto bene, va tutto bene..."
  },
  AvgDialog_22111_Content_70 = {
    Text = "Quella raccolta di poesie, purificata dalla Dissoluzione, si trasformò in un mucchio di vecchi bozzetti ingialliti, semplicemente fermati insieme con una graffetta comune, e cadde a terra."
  },
  AvgDialog_22111_Content_71 = {
    Text = "Ah! Ah!!—"
  },
  AvgDialog_22111_Content_72 = {
    Text = "Innumerevoli Mostri ruggiscono, crollano a terra e gradualmente tornano a forma umana."
  },
  AvgDialog_22111_Content_73 = {
    Text = "Il Desiderio svanisce, le emozioni ritornano. Le fondamenta di questo mondo crollano."
  },
  AvgDialog_22111_Content_74 = {
    Text = "Colette lo sentì."
  },
  AvgDialog_22111_Content_75 = {
    Text = "Sentiva il suo Potere affievolirsi. Sentiva la sconfitta avvicinarsi. Evocò lame simili a spine e si incamminò verso Horla."
  },
  AvgDialog_22111_Content_76 = {
    Text = "\"Colette,\" vittoria... Quando il cane della vecchia signora morì e lei mi diede il suo nome, tu eri proprio accanto a me."
  },
  AvgDialog_22111_Content_77 = {
    Text = "Questo è il nome del cane, ma non l'ho mai cambiato. Devo ricordare a me stessa di non perdere mai più."
  },
  AvgDialog_22111_Content_78 = {
    Text = "Hai ragione. Non posso dimenticarti, non posso dimenticare nulla di tutto questo..."
  },
  AvgDialog_22111_Content_79 = {
    Text = "Voglio vincere. Voglio solo vincere. Cosa c'è di sbagliato nel voler vincere?"
  },
  AvgDialog_22111_Content_8 = {
    Text = "Affrontarmi nel mio giardino... dovete essere tanto coraggiosi quanto sciocchi."
  },
  AvgDialog_22111_Content_80 = {
    Text = "Perdonami, Horla."
  },
  AvgDialog_22111_Content_81 = {
    Text = "Colette singhiozzava angosciata, avvicinandosi lentamente a Horla."
  },
  AvgDialog_22111_Content_82 = {
    Text = "Il Dominio sta svanendo. Il tuo piano è fallito, Colette!"
  },
  AvgDialog_22111_Content_83 = {
    Text = "Anche se la attacchi ora, non cambierà nulla!"
  },
  AvgDialog_22111_Content_84 = {
    Text = "Nel tentativo di avvicinarti a Horla, il dolore intenso ti ha immobilizzato."
  },
  AvgDialog_22111_Content_85 = {
    Text = "Lo spuntone si protende verso la testa di Horla."
  },
  AvgDialog_22111_Content_86 = {Text = "Aspetta!!"},
  AvgDialog_22111_Content_87 = {Text = "*Snap*—"},
  AvgDialog_22111_Content_88 = {
    Text = "Una rosa fu tagliata. Colette la prese e la porse a Horla."
  },
  AvgDialog_22111_Content_89 = {
    Text = "Un bel poema, Horla... Scambierò i miei fiori con il tuo poema."
  },
  AvgDialog_22111_Content_9 = {
    Text = "Avete sprecato la vostra ultima possibilità di fuga... Questa celebrazione, dovrete vederla fino in fondo con me."
  },
  AvgDialog_22111_Content_90 = {Text = "Bang—"},
  AvgDialog_22111_Content_91 = {
    Text = "Forse la dissoluzione del Dominio ha cambiato la giardiniera."
  },
  AvgDialog_22111_Content_92 = {
    Text = "O forse è stata la trasformazione della giardiniera a causare la Dissoluzione del Dominio."
  },
  AvgDialog_22111_Content_93 = {
    Text = "La Cité nei poemi sta gradualmente scomparendo, e anche il potere che sosteneva Colette è svanito."
  },
  AvgDialog_22111_Content_94 = {
    Text = "Il suo corpo si trasformò in una pozza di melma nera, mescolata a petali sparsi, sprofondando nel terreno davanti a Horla."
  },
  AvgDialog_22111_Content_95 = {
    Text = "Colette, Colette, hai finito di leggere?"
  },
  AvgDialog_22111_Content_96 = {
    Text = "Hmm... Ho finito di leggere... ma non lo capisco del tutto."
  },
  AvgDialog_22111_Content_97 = {
    Text = "Ah, davvero...? Questo è il mio primo poema. Non è molto buono..."
  },
  AvgDialog_22111_Content_98 = {
    Text = "Non sei tu, Horla. In realtà non capisco la poesia di nessuno."
  },
  AvgDialog_22111_Content_99 = {
    Text = "Ho chiesto a molte persone intorno a me, e nemmeno loro riuscivano a dargli un senso."
  },
  AvgDialog_22120_Content_1 = {
    Text = "Giardino dei Sentieri che si Biforcano"
  },
  AvgDialog_22120_Content_10 = {
    Text = "Sarebbe un peccato se nemmeno la mia migliore amica potesse vederlo."
  },
  AvgDialog_22120_Content_11 = {
    Text = "Dall'altro lato del giardino, la vecchia donna ti sorride."
  },
  AvgDialog_22120_Content_12 = {
    Text = "La mia amica scultrice mi ha detto che solo chi possiede un certo Dono può diventare un Risvegliatore."
  },
  AvgDialog_22120_Content_13 = {
    Text = "Che invidia, Horla."
  },
  AvgDialog_22120_Content_14 = {
    Text = "Notate le tracce di Dissoluzione su di lei e sulla persona alle sue spalle."
  },
  AvgDialog_22120_Content_15 = {
    Text = "L'Associazione degli Scultori... Sembra che la situazione qui sia stata causata dal giardiniere e dai membri dell'Associazione degli Scultori."
  },
  AvgDialog_22120_Content_16 = {
    Text = "Hai quel poema con te?"
  },
  AvgDialog_22120_Content_17 = {
    Text = "Le reliquie di un Vecchio Amico vanno conservate bene, naturalmente."
  },
  AvgDialog_22120_Content_18 = {
    Text = "Inoltre, giusto per ricordartelo, questa non è la tua raccolta di poesie — è sempre stata mia."
  },
  AvgDialog_22120_Content_19 = {
    Text = "La Cité è diventata così... È opera tua?"
  },
  AvgDialog_22120_Content_2 = {
    Text = "Tu sei... Colette..."
  },
  AvgDialog_22120_Content_20 = {
    Text = "Questo posto dovrebbe chiamarsi \"La mia Cité.\""
  },
  AvgDialog_22120_Content_21 = {
    Text = "Ricordi? Il nostro più grande sogno era semplicemente comprare una casa."
  },
  AvgDialog_22120_Content_22 = {
    Text = "E adesso? La poesia, le persone, la terra... e l'edificio che abbiamo sempre sognato."
  },
  AvgDialog_22120_Content_23 = {
    Text = "Guarda, caro Horla. Ora, tutta la Cité è mia."
  },
  AvgDialog_22120_Content_24 = {
    Text = "Colette, questa domanda mi ha tormentata per molti, molti anni..."
  },
  AvgDialog_22120_Content_25 = {
    Text = "Le dita di Horla si torcono nervosamente tra loro. Alza lo sguardo, i suoi occhi luminosi fissi su Colette."
  },
  AvgDialog_22120_Content_26 = {
    Text = "Perché fai queste cose... Perché sei diventata quello che sei ora..."
  },
  AvgDialog_22120_Content_27 = {
    Text = "Colette sorrise e scosse la testa."
  },
  AvgDialog_22120_Content_28 = {
    Text = "Sei così intelligente da saper scrivere poesie meravigliose senza mai uscire di casa. Ma quando si tratta delle persone, non capisci davvero nulla di loro..."
  },
  AvgDialog_22120_Content_29 = {
    Text = "Non sono mai cambiata, Horla."
  },
  AvgDialog_22120_Content_3 = {
    Text = "Horla schiude leggermente le labbra, fissando la Vecchia Donna dall'altra parte del giardino bruciato."
  },
  AvgDialog_22120_Content_30 = {
    Text = "No... impossibile... tu una volta chiaramente..."
  },
  AvgDialog_22120_Content_31 = {
    Text = "A volte ti invidio davvero. Invidio il tuo talento, i tuoi doni, e persino la tua innocenza."
  },
  AvgDialog_22120_Content_32 = {
    Text = "Ma perché... perché tu puoi vivere così innocentemente?"
  },
  AvgDialog_22120_Content_33 = {
    Text = "—Horla, le persone come noi non possono permettersi il lusso dell'innocenza."
  },
  AvgDialog_22120_Content_34 = {
    Text = "Non è così, Colette..."
  },
  AvgDialog_22120_Content_35 = {
    Text = "Non mi importa nulla di quelle cose del passato. Ti prego, restituisci il nostro Poema e riporta la Cité alla normalità..."
  },
  AvgDialog_22120_Content_36 = {
    Text = "Non ti importa?"
  },
  AvgDialog_22120_Content_37 = {
    Text = "Sentendo una battuta divertente, Colette rise fragorosamente, quasi incapace di raddrizzare la schiena."
  },
  AvgDialog_22120_Content_38 = {
    Text = "Non ti importa... Con quale diritto ti mostri indifferente?"
  },
  AvgDialog_22120_Content_39 = {
    Text = "Risparmia la tua pietà, Horla. Non mi hai mai capita. Non capisci nulla."
  },
  AvgDialog_22120_Content_4 = {Text = "!!!"},
  AvgDialog_22120_Content_40 = {
    Text = "Si alzò, ritrovò la sua elegante compostezza e annuì alla persona accanto a lei."
  },
  AvgDialog_22120_Content_41 = {
    Text = "Il rito comincia stanotte. Lascio le cose qui nelle tue mani."
  },
  AvgDialog_22120_Content_42 = {
    Text = "Rito? Cosa stai cercando di fare?!"
  },
  AvgDialog_22120_Content_43 = {
    Text = "Colette ti ignora, si sistema gli abiti e si incammina verso l'edificio."
  },
  AvgDialog_22120_Content_44 = {Text = "Aspetta!"},
  AvgDialog_22120_Content_45 = {
    Text = "Cerchi di inseguirla, ma l'edificio svanisce all'improvviso e riappare alle tue spalle."
  },
  AvgDialog_22120_Content_46 = {
    Text = "Scopri che la struttura del giardino era completamente invertita, come una creatura vivente."
  },
  AvgDialog_22120_Content_47 = {
    Text = "La struttura di questo giardino è cambiata?"
  },
  AvgDialog_22120_Content_48 = {
    Text = "Scrissi di un giardino della vita nella mia poesia... ma il giardino nei poemi non è così..."
  },
  AvgDialog_22120_Content_49 = {
    Text = "Il poema è nelle mani della giardiniera; deve aver alterato la struttura di questo luogo..."
  },
  AvgDialog_22120_Content_5 = {
    Text = "Lei è... la fioraia..."
  },
  AvgDialog_22120_Content_50 = {
    Text = "Non è ancora chiaro come si sia formato questo luogo. Tuttavia, sembra che trovarla potrebbe rivelarsi piuttosto problematico."
  },
  AvgDialog_22120_Content_51 = {
    Text = "Sbrighiamoci e inseguiamoli!"
  },
  AvgDialog_22120_Content_52 = {
    Text = "Avvicinandoti all'edificio con Horla, senti improvvisamente il suo respiro mozzarsi."
  },
  AvgDialog_22120_Content_53 = {
    Text = "{Male=Signore,Female=Signora} Custode, cosa vedete qui?"
  },
  AvgDialog_22120_Content_54 = {
    Text = "Horla indica i gradini. Una piccola busta bianca giace dove si trovavano poco fa."
  },
  AvgDialog_22120_Content_55 = {
    Text = "Raccogli la lettera e la apri."
  },
  AvgDialog_22120_Content_56 = {
    Text = "\"Al Sig. Herbert — Colette\"..."
  },
  AvgDialog_22120_Content_57 = {Text = "Click—"},
  AvgDialog_22120_Content_58 = {
    Text = "Sentendo la porta del salotto aprirsi, l'uomo non si voltò e continuò a guardare fuori dalla finestra con grande interesse."
  },
  AvgDialog_22120_Content_59 = {
    Text = "Che bel giardino, Sig.ra Colette."
  },
  AvgDialog_22120_Content_6 = {
    Text = "È meraviglioso vedere che sei ancora così giovane."
  },
  AvgDialog_22120_Content_60 = {
    Text = "La vostra dimora è di un prestigio invidiabile."
  },
  AvgDialog_22120_Content_61 = {
    Text = "Solo grazie al Signor Herbert. Senza il vostro aiuto, sarei morta per la Dissoluzione."
  },
  AvgDialog_22120_Content_62 = {
    Text = "Per non parlare del fatto che potrete avere ancora più di prima..."
  },
  AvgDialog_22120_Content_63 = {
    Text = "Ciascuna parte ottiene ciò di cui ha bisogno. Ho bisogno del vostro aiuto per verificare la possibilità di unificare il Dominio con il mondo reale."
  },
  AvgDialog_22120_Content_64 = {
    Text = "Il poema dissolto ha prodotto un Dominio così singolare. Persino i versi dissolti potevano disturbare oggetti reali."
  },
  AvgDialog_22120_Content_65 = {
    Text = "Nemmeno i Mythag riescono a trovare molti progetti di Ricerca così interessanti."
  },
  AvgDialog_22120_Content_66 = {
    Text = "Se si può vivere per sempre nella menzogna, allora la menzogna cessa di esistere."
  },
  AvgDialog_22120_Content_67 = {
    Text = "La vostra saggezza è davvero sorprendente, signora."
  },
  AvgDialog_22120_Content_68 = {
    Text = "Come procedono i preparativi per il nostro rito?"
  },
  AvgDialog_22120_Content_69 = {
    Text = "Ci siamo quasi... Secondo le vostre istruzioni, il Rito avrà inizio il mese prossimo."
  },
  AvgDialog_22120_Content_7 = {
    Text = "Come hai individuato Horla?"
  },
  AvgDialog_22120_Content_70 = {
    Text = "Stando alle vostre dichiarazioni, a quel punto la Dissoluzione del poema si propagherà e potrebbe persino coinvolgere l'intera Cité?"
  },
  AvgDialog_22120_Content_71 = {
    Text = "Non ricordo che foste qualcuno a cui importa della morale."
  },
  AvgDialog_22120_Content_72 = {
    Text = "Naturalmente. Ma mi importa di ciò che possiedo... Il mio Dominio sarà ancora stabile a quel punto?"
  },
  AvgDialog_22120_Content_73 = {
    Text = "Heh... State tranquilla, signora. La Formazione del Dominio è strettamente legata alla Dissoluzione. Più Forte è la Dissoluzione, più stabile sarà il vostro Dominio."
  },
  AvgDialog_22120_Content_74 = {
    Text = "La Copertura del Dominio è ancora limitata. Una volta che il Rito sarà Completo, si propagherà per tutta la Cité."
  },
  AvgDialog_22120_Content_75 = {
    Text = "A quel punto, tutto il Potere e la ricchezza della Cité saranno vostri."
  },
  AvgDialog_22120_Content_76 = {
    Text = "Una vittoria inesorabile. Ah, Colette... non siete forse sempre stata una vincitrice?"
  },
  AvgDialog_22120_Content_77 = {
    Text = "La fioraia si avvicinò alla finestra e guardò il suo giardino."
  },
  AvgDialog_22120_Content_78 = {
    Text = "Cercò di mantenere un sorriso Nobile e dignitoso, ma il calice di vino nella sua Mano tremava incontrollabilmente."
  },
  AvgDialog_22120_Content_79 = {
    Text = "Il volto della Dama di Nobiltà si rifletteva nel calice di vino oscillante, come una Ferita purulenta."
  },
  AvgDialog_22120_Content_8 = {
    Text = "Ti ho già dato la risposta."
  },
  AvgDialog_22120_Content_80 = {
    Text = "<Italic:Saremo tutti vincitori, Sig. Herbert.>"
  },
  AvgDialog_22120_Content_9 = {
    Text = "Nella nuova Cité, ogni cosa bella merita di essere contemplata."
  },
  AvgDialog_22121_Content_1 = {
    Text = "Funerale Tardivo"
  },
  AvgDialog_22121_Content_10 = {
    Text = "Forse è stato colpito da quel grande incendio."
  },
  AvgDialog_22121_Content_11 = {
    Text = "In ogni caso, questo dovrebbe essere il luogo che stiamo cercando."
  },
  AvgDialog_22121_Content_12 = {
    Text = "Horla, dove hai messo il poema?"
  },
  AvgDialog_22121_Content_13 = {
    Text = "Quando scoppiò l'incendio, scavai una piccola fossa per proteggere la raccolta di poesie, la riposi in una scatola e la seppellii."
  },
  AvgDialog_22121_Content_14 = {
    Text = "Vivevamo in una serra dove si coltivavano rose. Potete trovarla attraversando l'aiuola."
  },
  AvgDialog_22121_Content_15 = {Text = "SQUEAK!"},
  AvgDialog_22121_Content_16 = {
    Text = "C'è pericolo?!"
  },
  AvgDialog_22121_Content_17 = {
    Text = "Ah, no... {Male=Signor,Female=Signora} Custode, guardate laggiù."
  },
  AvgDialog_22121_Content_18 = {
    Text = "Horla indica con entusiasmo una parete. Vi è tracciato sopra un disegno approssimativo con gessetti colorati."
  },
  AvgDialog_22121_Content_19 = {
    Text = "Due bambine in vestito giocano a fare la dama e l'ancella."
  },
  AvgDialog_22121_Content_2 = {
    Text = "Siamo arrivati!"
  },
  AvgDialog_22121_Content_20 = {
    Text = "Quando vivevamo qui, Colette e io giocavamo spesso insieme a questo gioco. A volte facevo io la nobile, a volte lei."
  },
  AvgDialog_22121_Content_21 = {
    Text = "Questo dipinto è opera sua, anche se non è molto bello. D'altronde, all'epoca non avevamo altri gessetti."
  },
  AvgDialog_22121_Content_22 = {
    Text = "Tinse questo vestito di rosso con il succo delle rose... Ormai è appena visibile, che peccato."
  },
  AvgDialog_22121_Content_23 = {
    Text = "Le dita di Horla sfiorano delicatamente il semplice disegno a tratti, un tenue sorriso le solleva gli angoli delle labbra."
  },
  AvgDialog_22121_Content_24 = {
    Text = "Colette... la giardiniera che vi bruciò viva, giusto?"
  },
  AvgDialog_22121_Content_25 = {
    Text = "Era anche la mia migliore amica."
  },
  AvgDialog_22121_Content_26 = {
    Text = "Crescere nella serra dei fiori era bello, ma un po' angusto. Sognavamo di avere un giorno un focolare nella tenuta."
  },
  AvgDialog_22121_Content_27 = {
    Text = "Tuttavia, alla fine, non sono mai riuscito a viverci..."
  },
  AvgDialog_22121_Content_28 = {
    Text = "Horla rivolse uno sguardo malinconico alla magnifica villa davanti a sé e proseguì il cammino."
  },
  AvgDialog_22121_Content_29 = {
    Text = "{Male=Signor,Female=Signora} Custode, attraverso questo Giardino di rose, ci siamo quasi."
  },
  AvgDialog_22121_Content_3 = {
    Text = "Camminando verso nordest lungo la vivace Avenue dei Medici nella Cité, arrivate presto in una bella zona residenziale."
  },
  AvgDialog_22121_Content_30 = {
    Text = "Giardino di rose? Dov'è il giardino di rose..."
  },
  AvgDialog_22121_Content_31 = {
    Text = "Il giardino sul retro di questa dimora un tempo era colmo di rose."
  },
  AvgDialog_22121_Content_32 = {
    Text = "Erano di Colette?"
  },
  AvgDialog_22121_Content_33 = {
    Text = "Hmm! A quel tempo, eravamo appena state cacciate dal nostro vecchio maniero e non avevamo un posto dove andare..."
  },
  AvgDialog_22121_Content_34 = {
    Text = "Aspetta! Colette... ho appena visto il cartello. Questo è il giardino della Contessa?"
  },
  AvgDialog_22121_Content_35 = {
    Text = "Non avevi detto che non vedevi un giardino da molto tempo? Ebbene, questo è il giardino più bello di tutta la zona."
  },
  AvgDialog_22121_Content_36 = {
    Text = "Colette, sbrighiamoci... Se ci scoprono, saranno guai seri!"
  },
  AvgDialog_22121_Content_37 = {
    Text = "No, non succederà. Guarda—"
  },
  AvgDialog_22121_Content_38 = {
    Text = "Colse una rosa e la posò nella mano di Horla."
  },
  AvgDialog_22121_Content_39 = {
    Text = "Ahhh! Colette, finiremo in prigione..."
  },
  AvgDialog_22121_Content_4 = {
    Text = "Un palazzo simile a una reggia si erge davanti a voi, vistoso e magnifico."
  },
  AvgDialog_22121_Content_40 = {
    Text = "Nessuno andrà in prigione. Horla, guarda laggiù!"
  },
  AvgDialog_22121_Content_41 = {
    Text = "Seguendo le indicazioni di Colette, Horla vide una serra dove si coltivavano rose pregiate."
  },
  AvgDialog_22121_Content_42 = {
    Text = "La stanza dei fiori conteneva due letti e i loro pochi averi."
  },
  AvgDialog_22121_Content_43 = {
    Text = "Colette... Cos'è questo?"
  },
  AvgDialog_22121_Content_44 = {
    Text = "Ho preso in affitto questo posto."
  },
  AvgDialog_22121_Content_45 = {
    Text = "Ma... come hai fatto..."
  },
  AvgDialog_22121_Content_46 = {
    Text = "Si accorse solo allora che la collana lasciatale dalla madre di Colette non era più al suo collo."
  },
  AvgDialog_22121_Content_47 = {
    Text = "Colette! Tu..."
  },
  AvgDialog_22121_Content_48 = {
    Text = "Shh~ Niente di tutto questo conta, Horla. Ciò che conta è che questo non è il giardino di qualche conte — questo è <Italic:il nostro giardino.>"
  },
  AvgDialog_22121_Content_49 = {
    Text = "Mangeremo e dormiremo nella serra... Venderò i fiori che crescono su questa terra per comprarci vestiti e cibo."
  },
  AvgDialog_22121_Content_5 = {
    Text = "Ma... perché questo posto è cambiato così?"
  },
  AvgDialog_22121_Content_50 = {
    Text = "Un giorno, ci comprerò persino un focolare in quell'edificio!"
  },
  AvgDialog_22121_Content_51 = {
    Text = "Ma... cosa posso fare...?"
  },
  AvgDialog_22121_Content_52 = {
    Text = "Tutto ciò che posso fare è scrivere poemi che nessuno legge..."
  },
  AvgDialog_22121_Content_53 = {
    Text = "A dire il vero, nemmeno io capisco i tuoi poemi... Ma non importa. Scrivi semplicemente ciò che desideri scrivere."
  },
  AvgDialog_22121_Content_54 = {
    Text = "Tutti hanno qualcosa per cui sono nati. Io sono nata per lottare per questo giardino e quella casa."
  },
  AvgDialog_22121_Content_55 = {
    Text = "E tu, tu sei nato per scrivere poesia."
  },
  AvgDialog_22121_Content_56 = {
    Text = "Da allora, ci ha mantenute entrambe con i fiori di questo giardino."
  },
  AvgDialog_22121_Content_57 = {
    Text = "Sebbene fosse estremamente duro e fossimo ben lontane dal comprare una casa, in quel periodo eravamo davvero piuttosto felici."
  },
  AvgDialog_22121_Content_58 = {
    Text = "Fino al giorno in cui l'editore mi inviò il primo compenso per i miei poemi..."
  },
  AvgDialog_22121_Content_59 = {
    Text = "Sebbene in seguito ti abbia rinchiusa nella serra e abbia appiccato il fuoco, non sembra che tu la odi."
  },
  AvgDialog_22121_Content_6 = {
    Text = "Nel vasto giardino ai suoi piedi, erba grigia e avvizzita cresceva ovunque. Vi addentrate nel giardino."
  },
  AvgDialog_22121_Content_60 = {
    Text = "Difficile a dirsi... Forse. Non so davvero cosa pensare."
  },
  AvgDialog_22121_Content_61 = {
    Text = "So solo che, se non fosse stato per quei poemi, niente di tutto questo sarebbe accaduto..."
  },
  AvgDialog_22121_Content_62 = {Text = "Horla..."},
  AvgDialog_22121_Content_63 = {
    Text = "Le visioni di Horla si dispiegano davanti a te. Il suo pianto sembra tangibile, si propaga e permea ogni cosa intorno."
  },
  AvgDialog_22121_Content_64 = {
    Text = "Mi dispiace! {Male=Signor,Female=Signora} Custode... Vi ho rattristato di nuovo..."
  },
  AvgDialog_22121_Content_65 = {
    Text = "Va tutto bene, non trattenere le tue emozioni."
  },
  AvgDialog_22121_Content_66 = {
    Text = "Continuiamo a cercare la raccolta di poesie."
  },
  AvgDialog_22121_Content_67 = {
    Text = "Il poema è sepolto laggiù! {Male=Signor,Female=Signora} Custode, seguitemi!"
  },
  AvgDialog_22121_Content_68 = {
    Text = "Avete percorso i sentieri tortuosi del giardino, aggirato le cornici di legno bruciate, e siete giunti in uno spiazzo aperto dietro il cortile."
  },
  AvgDialog_22121_Content_69 = {
    Text = "Siamo arrivati!"
  },
  AvgDialog_22121_Content_7 = {
    Text = "Più vi avvicinate, più i colori intorno a voi si fanno spenti... Anche questi fanno parte dell'immaginazione della vostra poesia?"
  },
  AvgDialog_22121_Content_70 = {
    Text = "Indica un piccolo punto al centro del cortile posteriore. Le rose circostanti si erano ridotte in cenere e fertilizzante, ora invase da erbacce nere."
  },
  AvgDialog_22121_Content_71 = {
    Text = "Il rapporto del Mythag dice che hanno trovato l'Argento di Horla in una radura bruciata."
  },
  AvgDialog_22121_Content_72 = {
    Text = "—È lì che il poema è sepolto. Quello è il suo ultimo luogo di riposo."
  },
  AvgDialog_22121_Content_73 = {
    Text = "Strano... C'è un buco qui..."
  },
  AvgDialog_22121_Content_74 = {
    Text = "La raccolta di poesie... la raccolta di poesie avrebbe dovuto essere sepolta qui!"
  },
  AvgDialog_22121_Content_75 = {
    Text = "Non c'era da molti anni."
  },
  AvgDialog_22121_Content_76 = {Text = "!!!"},
  AvgDialog_22121_Content_77 = {Text = "Chi?!—"},
  AvgDialog_22121_Content_78 = {
    Text = "Una Voce Familiare risuona. Vi voltate bruscamente."
  },
  AvgDialog_22121_Content_79 = {
    Text = "La porta sul retro della villa si apre, e la Dama di Nobiltà che avete incontrato sulla nave è ferma all'ingresso, guardandovi dall'alto."
  },
  AvgDialog_22121_Content_8 = {
    Text = "Non riesco a ricordare bene... Ma non dovrebbe essere così, giusto...?"
  },
  AvgDialog_22121_Content_80 = {
    Text = "Dopo il grande incendio, ho tenuto un funerale grandioso per te. Peccato che tu non abbia potuto vederlo di persona."
  },
  AvgDialog_22121_Content_81 = {
    Text = "Vederti sulla nave mi ha reso felice. Non provavo una gioia simile da molto tempo."
  },
  AvgDialog_22121_Content_82 = {
    Text = "Decenni... Decenni, e finalmente ci rincontriamo..."
  },
  AvgDialog_22121_Content_83 = {
    Text = "Bentornato a casa, Horla."
  },
  AvgDialog_22121_Content_9 = {
    Text = "Forse è perché avete scritto la morte in alcune delle vostre poesie."
  },
  AvgDialog_22122_Content_1 = {
    Text = "Innumerevoli mostri si riversano in un'ondata sul palco."
  },
  AvgDialog_22122_Content_2 = {
    Text = "Così non funziona. Horla, resta vicina. Apriamoci un varco da questo lato!"
  },
  AvgDialog_22122_Content_3 = {
    Text = "Ma se è così... Colette distruggerà questo luogo..."
  },
  AvgDialog_22122_Content_4 = {
    Text = "Non è il momento di esitare. Ci sono troppi Mostri, e non possiamo fermare Colette adesso... Fidati di me, Horla."
  },
  AvgDialog_22122_Content_5 = {
    Text = "Vedendo il tuo Sguardo determinato, Horla ancora non comprende il tuo intento, ma annuisce."
  },
  AvgDialog_22122_Content_6 = {
    Text = "Io... ho capito..."
  },
  AvgDialog_22122_Content_7 = {
    Text = "{Male=Signor,Female=Signora} Custode, fate attenzione!"
  },
  AvgDialog_22125_Content_1 = {Text = "Il Poeta"},
  AvgDialog_22125_Content_10 = {
    Text = "Una luce intensa proveniente da una fonte sconosciuta illumina il tetto e i tavoli del caffè lungo la strada."
  },
  AvgDialog_22125_Content_100 = {
    Text = "Andiamo, {Male=Sig.,Female=Sig.na} Custode, ci dirigiamo al Giardino di rose... là dove sono morta."
  },
  AvgDialog_22125_Content_11 = {
    Text = "Horla si crogiola nella luce, i piedi che oscillano nell'aria seguendo un ritmo sconosciuto."
  },
  AvgDialog_22125_Content_12 = {
    Text = "Ricordo di aver letto sul giornale che Via di Marzo era in origine una strada qualunque, ma divenne celebre perché un pittore creò un'opera per questo caffè."
  },
  AvgDialog_22125_Content_13 = {
    Text = "Adoro questa storia e una volta ci scrissi un poema. Nel poema, l'artista alla fine si stabilì al N. 99, Fine di Via di Marzo."
  },
  AvgDialog_22125_Content_14 = {
    Text = "Credo che non sia Via di Marzo ad aver incontrato il pittore, ma piuttosto il pittore ad aver incontrato Via di Marzo."
  },
  AvgDialog_22125_Content_15 = {
    Text = "La Cité è diventata così strana, eppure tu non sembri affatto spaventata, anzi ti stai persino divertendo?"
  },
  AvgDialog_22125_Content_16 = {
    Text = "Qui non devi interagire con le persone, eppure puoi imbatterti in molte cose nuove e affascinanti."
  },
  AvgDialog_22125_Content_17 = {
    Text = "Non riesco a esprimerlo a parole, ma mi sento sempre più a casa qui che quando guardavo i giornali e le foto della Cité..."
  },
  AvgDialog_22125_Content_18 = {
    Text = "Ah, guardi, {Male=Signor,Female=Signora} Custode! Sono le Stelle!"
  },
  AvgDialog_22125_Content_19 = {
    Text = "Stelle? Ma qui non sembra esserci né giorno né notte..."
  },
  AvgDialog_22125_Content_2 = {
    Text = "Due tazze di caffè... grazie."
  },
  AvgDialog_22125_Content_20 = {
    Text = "Alzi lo sguardo. Accanto alle Stelle dorate e scintillanti, petali bianchi si schiudono."
  },
  AvgDialog_22125_Content_21 = {
    Text = "Enormi Stelle simili a margherite trasformano il cielo in un giardino."
  },
  AvgDialog_22125_Content_22 = {
    Text = "La Cité è una città di poesia e fiori... Senza quelle faccende urgenti, sarebbe davvero un luogo piacevole."
  },
  AvgDialog_22125_Content_23 = {
    Text = "In trenta minuti abbiamo incontrato circa un centinaio di Cittadini senza alcun attacco... Quel tram non doveva averci mentito."
  },
  AvgDialog_22125_Content_24 = {
    Text = "Ah, dunque {Male=il Signor,Female=la Signora} Custode ha osservato tutto il tempo?"
  },
  AvgDialog_22125_Content_25 = {
    Text = "Non ho scelta. Alcuni rivolgono lo Sguardo alle Stelle, mentre altri devono guardare il terreno sotto i propri piedi."
  },
  AvgDialog_22125_Content_26 = {
    Text = "Pur non essendo dotato in poesia, in qualità di Custode di Mythag, posso comunque occuparmi di questo Compito."
  },
  AvgDialog_22125_Content_27 = {
    Text = "Il contatto si trova al 101 di March Street. Preparatevi, andiamo."
  },
  AvgDialog_22125_Content_28 = {Text = "..."},
  AvgDialog_22125_Content_29 = {Text = "Boom—"},
  AvgDialog_22125_Content_3 = {
    Text = "Poco dopo, un procione vestito con un'uniforme da cameriere vi portò due tazze di caffè."
  },
  AvgDialog_22125_Content_30 = {Text = "Chi?!"},
  AvgDialog_22125_Content_31 = {
    Text = "Incerti sui pericoli che si celano qui, osservate con cautela ciò che vi circonda."
  },
  AvgDialog_22125_Content_32 = {
    Text = "Ah, i miei saluti a entrambi!"
  },
  AvgDialog_22125_Content_33 = {
    Text = "Uff... Ci rivediamo..."
  },
  AvgDialog_22125_Content_34 = {
    Text = "Salve! Madame Farfalla, Signor Bruco!"
  },
  AvgDialog_22125_Content_35 = {
    Text = "Cosa state facendo?"
  },
  AvgDialog_22125_Content_36 = {
    Text = "Mio marito e io abbiamo cenato e ci stavamo preparando per una passeggiata lungo la strada."
  },
  AvgDialog_22125_Content_37 = {
    Text = "Che coincidenza! Ho sentito il Poema scritto da quella giovane signora — è assolutamente magnifico!"
  },
  AvgDialog_22125_Content_38 = {Text = "Grazie..."},
  AvgDialog_22125_Content_39 = {
    Text = "Vi siete persi, voi due?"
  },
  AvgDialog_22125_Content_4 = {
    Text = "Parlare con gli sconosciuti? Hai già fatto grandi progressi, Horla!"
  },
  AvgDialog_22125_Content_40 = {
    Text = "Le strade qui non corrispondono ai segni sulla mappa, e i numeri civici sono tutti sballati..."
  },
  AvgDialog_22125_Content_41 = {
    Text = "Mi scusi, sa dove si trova il numero 101 di March Street?"
  },
  AvgDialog_22125_Content_42 = {
    Text = "101... Non ricordo se esista un numero 101 su March Street."
  },
  AvgDialog_22125_Content_43 = {Text = "Davvero..."},
  AvgDialog_22125_Content_44 = {
    Text = "Questo posto non è molto grande. Continuiamo a cercare con calma."
  },
  AvgDialog_22125_Content_45 = {
    Text = "Mi dispiace di non essere stato di grande aiuto."
  },
  AvgDialog_22125_Content_46 = {
    Text = "Cercate con calma. Godetevi il soggiorno a Cité~"
  },
  AvgDialog_22125_Content_47 = {
    Text = "Dopo aver salutato la Signora Farfalla e il Signor Bruco, continuate a farvi strada per le vie di March Street, controllando i numeri sulle targhette uno per uno."
  },
  AvgDialog_22125_Content_48 = {
    Text = "Hmm, non ricordavo che March Street fosse così lunga..."
  },
  AvgDialog_22125_Content_49 = {
    Text = "Abbiamo controllato l'intera strada già due volte."
  },
  AvgDialog_22125_Content_5 = {
    Text = "Solo una persona, e sembra un animale, ma suppongo che non sia del tutto inutile..."
  },
  AvgDialog_22125_Content_50 = {
    Text = "Eh? Ma non vedo dove sia il numero 101..."
  },
  AvgDialog_22125_Content_51 = {
    Text = "La prima volta non ci ho fatto caso, ma la seconda ho osservato attentamente tutti i numeri sulle porte."
  },
  AvgDialog_22125_Content_52 = {
    Text = "Via March... Non esiste il numero 101."
  },
  AvgDialog_22125_Content_53 = {
    Text = "Il numero civico più alto qui è questo."
  },
  AvgDialog_22125_Content_54 = {
    Text = "Vi fermate accanto al muro alla fine della strada. La Targhetta metallica sul piccolo edificio davanti a voi è stata sostituita con un dipinto."
  },
  AvgDialog_22125_Content_55 = {
    Text = "Via di Marzo... N. 99."
  },
  AvgDialog_22125_Content_56 = {Text = "Chi?"},
  AvgDialog_22125_Content_57 = {
    Text = "La Porta si spalanca con violenza, rivelando una figura esile davanti a voi."
  },
  AvgDialog_22125_Content_58 = {
    Text = "Sugli abiti laceri macchiati di vernice si scorge il volto di un insetto."
  },
  AvgDialog_22125_Content_59 = {
    Text = "Siete dei ladri?!"
  },
  AvgDialog_22125_Content_6 = {
    Text = "Anche se non sono sicura che sia una buona cosa, finalmente c'è più gente nei paraggi."
  },
  AvgDialog_22125_Content_60 = {
    Text = "Ehm... no, siamo turisti venuti a trovare un amico. Si trova al 101 di March Street..."
  },
  AvgDialog_22125_Content_61 = {
    Text = "Qual è il numero?!"
  },
  AvgDialog_22125_Content_62 = {
    Text = "1... Ehm, N. 88."
  },
  AvgDialog_22125_Content_63 = {
    Text = "Hai detto 101. Non esiste nessun 101 qui..."
  },
  AvgDialog_22125_Content_64 = {
    Text = "Bugiardi... Avete rubato il mio dipinto! Siete stati voi a rubare il mio dipinto!!"
  },
  AvgDialog_22125_Content_65 = {
    Text = "Con i movimenti del Pittore, la scena circostante muta all'improvviso."
  },
  AvgDialog_22125_Content_66 = {
    Text = "Alcuni colori abbaglianti e bizzarri apparvero improvvisamente sugli edifici circostanti, simili a un dipinto completo lacerato in tonalità caotiche da una forza ignota."
  },
  AvgDialog_22125_Content_67 = {
    Text = "Questa è... Dissoluzione?!"
  },
  AvgDialog_22125_Content_68 = {
    Text = "Incerti sul principio alla base di quel fenomeno, vi ritirate in fretta insieme a Horla."
  },
  AvgDialog_22125_Content_69 = {
    Text = "Ridammi il mio dipinto!!"
  },
  AvgDialog_22125_Content_7 = {
    Text = "Il signor Bruco non ha forse detto che la maggior parte delle persone non ci farà del male, purché non ci comportiamo in modo strano?"
  },
  AvgDialog_22125_Content_70 = {
    Text = "La sua Mano si protende verso di voi. Prima che vi tocchi, strani colori gli si riversano attorno come un'ondata, inghiottendolo e divorandolo..."
  },
  AvgDialog_22125_Content_71 = {
    Text = "Ben presto, i colori sinistri cessano di contorcersi. Osservate in silenzio la scena che vi si para dinanzi."
  },
  AvgDialog_22125_Content_72 = {
    Text = "Il distintivo scolastico sul vostro petto emise un bagliore d'Argento."
  },
  AvgDialog_22125_Content_73 = {
    Text = "Cité... È successo qualcosa di nuovo?"
  },
  AvgDialog_22125_Content_74 = {
    Text = "Un edificio è scomparso."
  },
  AvgDialog_22125_Content_75 = {
    Text = "Si trova in Via di Marzo..."
  },
  AvgDialog_22125_Content_76 = {Text = "N. 99."},
  AvgDialog_22125_Content_77 = {
    Text = "Guardate la targhetta rimasta con il numero 99, trattenendo un respiro profondo."
  },
  AvgDialog_22125_Content_78 = {
    Text = "Non possiamo lasciare che le cose continuino così... Senza un contatto, dobbiamo trovare un'altra via."
  },
  AvgDialog_22125_Content_79 = {
    Text = "{Male=Signor,Female=Signora} Custode, ho un'ipotesi..."
  },
  AvgDialog_22125_Content_8 = {
    Text = "Speranza che non vengano altre api a \"cantare\" per me..."
  },
  AvgDialog_22125_Content_80 = {
    Text = "No, non un'ipotesi. Ne sono certo."
  },
  AvgDialog_22125_Content_81 = {
    Text = "Questa non è Cité!"
  },
  AvgDialog_22125_Content_82 = {
    Text = "...Horla, cosa stai dicendo?"
  },
  AvgDialog_22125_Content_83 = {
    Text = "Intendo dire che questa non è la vera Cité."
  },
  AvgDialog_22125_Content_84 = {
    Text = "Questa non è la vera Cité...?"
  },
  AvgDialog_22125_Content_85 = {
    Text = "Il Treno Bruco che richiede un Poema come biglietto, Madame Farfalla, solo il numero 99 di via March, il Pittore, le Stelle di Daisy..."
  },
  AvgDialog_22125_Content_86 = {
    Text = "Queste cose che abbiamo visto, ho sempre avuto la sensazione che mi fossero estremamente familiari. Solo adesso ho finalmente ricordato il perché."
  },
  AvgDialog_22125_Content_87 = {
    Text = "Tutte queste cose sono apparse nella mia raccolta di poesie. Ogni cosa qui è esattamente come l'avevo immaginata nei miei poemi..."
  },
  AvgDialog_22125_Content_88 = {
    Text = "{Male=Sig.,Female=Sig.na} Custode, questa non è la vera Cité."
  },
  AvgDialog_22125_Content_89 = {
    Text = "Questa è la <Yellow:Cité della mia immaginazione>..."
  },
  AvgDialog_22125_Content_9 = {
    Text = "Nella strada spaziosa, Cittadini con varie teste di animali vanno e vengono, senza mostrare alcun segno di aggressività."
  },
  AvgDialog_22125_Content_90 = {
    Text = "Sotto i colori caotici di via March, Horla ruotò lentamente su sé stessa, contemplando tutto ciò che apparteneva ai suoi poemi."
  },
  AvgDialog_22125_Content_91 = {
    Text = "La luce cade come un velo, illuminandole il volto, colmo di curiosità, Pianto e Confusione."
  },
  AvgDialog_22125_Content_92 = {
    Text = "Capisco... Non c'è da stupirsi che vi siano tante cose bizzarre qui."
  },
  AvgDialog_22125_Content_93 = {
    Text = "Ma come ha fatto Cité a ridursi così..."
  },
  AvgDialog_22125_Content_94 = {
    Text = "Non lo so nemmeno io... Alcune cose qui non sono esattamente uguali a quelle dei miei poemi."
  },
  AvgDialog_22125_Content_95 = {
    Text = "Tutto nel Poema avrebbe dovuto essere bello ed eterno... Non so perché sia finito così..."
  },
  AvgDialog_22125_Content_96 = {
    Text = "Ma credo che, se vogliamo risolvere la questione qui, potremmo dover trovare prima quel Poema."
  },
  AvgDialog_22125_Content_97 = {
    Text = "Ricordi ancora la strada?"
  },
  AvgDialog_22125_Content_98 = {
    Text = "Nella mia poesia, via March è vicina al Focolare. Ricordo sempre la via del ritorno."
  },
  AvgDialog_22125_Content_99 = {
    Text = "Lei si volge verso la zona residenziale, il Pianto come una Nebbia tangibile che vi avvolge."
  },
  AvgDialog_22126_Content_1 = {
    Text = "Huff... Huff... {Male=Signor,Female=Signora} Custode, ci sono troppi Mostri da gestire..."
  },
  AvgDialog_22126_Content_10 = {
    Text = "—Sfondare per cercare rinforzi è solo uno stratagemma. Questa è l'opportunità che stavi aspettando."
  },
  AvgDialog_22126_Content_11 = {
    Text = "Trattienila, Horla!"
  },
  AvgDialog_22126_Content_12 = {
    Text = "Ti volti improvvisamente."
  },
  AvgDialog_22126_Content_13 = {
    Text = "Horla si fermò un istante, comprendendo la tua intenzione, e poi caricò verso Colette insieme a te..."
  },
  AvgDialog_22126_Content_14 = {
    Text = "Questo è!!"
  },
  AvgDialog_22126_Content_15 = {
    Text = "Un mostro gigante a forma di fiore prende forma dai rampicanti attorno alla piazza, bloccando il cammino di Colette."
  },
  AvgDialog_22126_Content_16 = {
    Text = "Buona idea, Custode. Ma non permetterò che alcuna sorpresa interferisca con il mio piano."
  },
  AvgDialog_22126_Content_17 = {
    Text = "Ascolta, Horla. Questo poema è scritto per te—"
  },
  AvgDialog_22126_Content_2 = {
    Text = "La Dissoluzione si sta espandendo. Se continua così, resteremo intrappolati qui..."
  },
  AvgDialog_22126_Content_3 = {
    Text = "Ho origliato la vostra conversazione quando siete arrivati nella Cité."
  },
  AvgDialog_22126_Content_4 = {
    Text = "Cerchi rinforzi? Non te ne darò l'occasione, Custode."
  },
  AvgDialog_22126_Content_5 = {
    Text = "Sotto il comando di Colette, orde di Mostri si precipitano verso l'uscita, bloccando completamente il tuo cammino."
  },
  AvgDialog_22126_Content_6 = {
    Text = "L'opportunità è arrivata. Una sola volta."
  },
  AvgDialog_22126_Content_7 = {
    Text = "Eh? ...Cosa... cosa intendi..."
  },
  AvgDialog_22126_Content_8 = {
    Text = "La tua visione periferica coglie Colette mentre invia tutti i mostri dietro le quinte per bloccare la tua via di fuga."
  },
  AvgDialog_22126_Content_9 = {
    Text = "Attorno a lei, il numero di mostri è diminuito significativamente, rendendo possibile tentare qualcosa."
  },
  AvgDialog_22127_Content_1 = {
    Text = "Città dei Fiori"
  },
  AvgDialog_22127_Content_10 = {
    Text = "Queste scene meravigliose sembrano far dimenticare a Horla quei ricordi dolorosi, così come gli estranei intorno a lei."
  },
  AvgDialog_22127_Content_100 = {
    Text = "Salve, se non salite, me ne vado. Altri passeggeri stanno aspettando."
  },
  AvgDialog_22127_Content_101 = {
    Text = "Lo osservi con diffidenza. Il Treno Bruco sembra abbastanza amichevole..."
  },
  AvgDialog_22127_Content_102 = {
    Text = "Mi scusi, questo tram va a Viale Medici?"
  },
  AvgDialog_22127_Content_103 = {
    Text = "Certo, certo... Questo tram può portarvi ovunque."
  },
  AvgDialog_22127_Content_104 = {
    Text = "Un vagone che può andare ovunque, eh... Certo, ha senso."
  },
  AvgDialog_22127_Content_105 = {
    Text = "In ogni caso, almeno questo veicolo è davvero adibito al trasporto passeggeri."
  },
  AvgDialog_22127_Content_106 = {
    Text = "Il corpo del bruco si apre, rivelando al suo interno un sedile ordinato."
  },
  AvgDialog_22127_Content_107 = {
    Text = "Vedendo gli occhi pieni di aspettativa di Horla, ti siedi."
  },
  AvgDialog_22127_Content_108 = {
    Text = "Mi scusi, come si paga il biglietto?"
  },
  AvgDialog_22127_Content_109 = {
    Text = "È gratuito."
  },
  AvgDialog_22127_Content_11 = {
    Text = "I Suoi Occhi brillavano mentre ti seguiva attraverso questa città pittoresca."
  },
  AvgDialog_22127_Content_110 = {
    Text = "A quanto pare oggi non è poi così male, almeno c'è un passaggio gratuito..."
  },
  AvgDialog_22127_Content_111 = {
    Text = "Non è gratuito. Per ottenere un biglietto per questo vagone, bisogna pagare con un poema."
  },
  AvgDialog_22127_Content_112 = {Text = "???"},
  AvgDialog_22127_Content_113 = {
    Text = "Ah, giusto... Questa signorina dev'essere una locale."
  },
  AvgDialog_22127_Content_114 = {
    Text = "Horla, come fai a conoscere queste regole..."
  },
  AvgDialog_22127_Content_115 = {
    Text = "Non ne sono del tutto sicura... È semplicemente così che lo ricordo."
  },
  AvgDialog_22127_Content_116 = {
    Text = "Non è costoso; ogni passeggero deve solo scrivere una semplice frase."
  },
  AvgDialog_22127_Content_117 = {
    Text = "Vado per prima..."
  },
  AvgDialog_22127_Content_118 = {
    Text = "Si avvicina alla parte anteriore del bus e sussurra qualcosa nella cassetta del pedaggio accanto al posto del conducente."
  },
  AvgDialog_22127_Content_119 = {
    Text = "Ah... Che splendido poema! Si accomodi pure, signorina."
  },
  AvgDialog_22127_Content_12 = {
    Text = "...È notevole che tu abbia ancora la lucidità di pensare a questo, ora."
  },
  AvgDialog_22127_Content_120 = {
    Text = "Posso dare un'occhiata anch'io?"
  },
  AvgDialog_22127_Content_121 = {
    Text = "Io... Mi vergogno un po'... Lo scriverò in segreto dopo il ritorno, {Male=Signor Custode,Female=Signora Custode}."
  },
  AvgDialog_22127_Content_122 = {
    Text = "Tocca a lei, {Male=Signore,Female=Signora}."
  },
  AvgDialog_22127_Content_123 = {
    Text = "Hmm, fammi pensare..."
  },
  AvgDialog_22127_Content_124 = {
    Text = "Il tram avanzava lungo i binari lentamente, come un bruco."
  },
  AvgDialog_22127_Content_125 = {
    Text = "La mia analogia è piuttosto ingegnosa, affine a qualcos'altro."
  },
  AvgDialog_22127_Content_126 = {
    Text = "Sbrighiamoci, andiamo a Viale Medici!"
  },
  AvgDialog_22127_Content_127 = {Text = "..."},
  AvgDialog_22127_Content_128 = {Text = "..."},
  AvgDialog_22127_Content_129 = {
    Text = "Di norma, bisogna riscrivere una frase, ma il poema di quella signorina potrebbe acquistare abbonamenti per tutti i posti, e non desidero sopportare altri tormenti. Prego, si accomodi."
  },
  AvgDialog_22127_Content_13 = {
    Text = "Horla, non trovi che la città di Cité sia diventata strana?"
  },
  AvgDialog_22127_Content_130 = {
    Text = "Il bruco apre gli occhi, e da essi emanò una luce intensa."
  },
  AvgDialog_22127_Content_131 = {
    Text = "Avanza con passo costante."
  },
  AvgDialog_22127_Content_14 = {
    Text = "No, anche se ho dimenticato che aspetto abbia Cité, credo che dovrebbe apparire proprio così."
  },
  AvgDialog_22127_Content_15 = {
    Text = "Questa signora ha ragione. Cité, città di Fiori e Poesia, dovrebbe davvero apparire così."
  },
  AvgDialog_22127_Content_16 = {
    Text = "La dama di nobiltà sorrise e diede una pacca sulla schiena di Horla."
  },
  AvgDialog_22127_Content_17 = {Text = "Heh heh..."},
  AvgDialog_22127_Content_18 = {
    Text = "Solo ora sembrando rendersi conto che c'era un'estranea accanto a lei, sorrise con imbarazzo, arrossendo mentre si nascondeva leggermente dietro la pergamena."
  },
  AvgDialog_22127_Content_19 = {
    Text = "Una campana limpida risuona, e una carrozza appare davanti a voi."
  },
  AvgDialog_22127_Content_2 = {
    Text = "Questo... Questo è troppo..."
  },
  AvgDialog_22127_Content_20 = {
    Text = "Ah, il mio passaggio è quasi arrivato... Temo di non poter restare con voi oltre."
  },
  AvgDialog_22127_Content_21 = {
    Text = "Non mi aspettavo che veniste, quindi non ho preparato un dono... Ecco, questo è per voi. Spero che non vi dispiaccia."
  },
  AvgDialog_22127_Content_22 = {
    Text = "Porge la mano, offrendo qualcosa a Horla."
  },
  AvgDialog_22127_Content_23 = {
    Text = "Quello è..."
  },
  AvgDialog_22127_Content_24 = {
    Text = "Una rosa macchiata d'acquerello trema lievemente nel vento proveniente da una direzione sconosciuta."
  },
  AvgDialog_22127_Content_25 = {
    Text = "Horla alza lo sguardo con gioia per esprimere gratitudine, ma la Vecchia Donna è già salita sulla carrozza."
  },
  AvgDialog_22127_Content_26 = {
    Text = "Addio, Horla."
  },
  AvgDialog_22127_Content_27 = {
    Text = "La carrozza avanza, fondendosi presto nel dipinto a inchiostro in lontananza."
  },
  AvgDialog_22127_Content_28 = {
    Text = "Questa signora anziana è davvero gentile. Ma c'è qualcosa di un po' strano in lei..."
  },
  AvgDialog_22127_Content_29 = {
    Text = "In effetti... Oh cielo, ho dimenticato di chiederle indicazioni."
  },
  AvgDialog_22127_Content_3 = {
    Text = "Cité, la città di fiori e poesia."
  },
  AvgDialog_22127_Content_30 = {
    Text = "Non importa, cerchiamo qualcuno qui vicino."
  },
  AvgDialog_22127_Content_31 = {
    Text = "Una città così grande, eppure ci sono così poche persone per le strade... È davvero strano."
  },
  AvgDialog_22127_Content_32 = {
    Text = "Cambiamenti nei tratti visivi, discrepanze nei numeri... Le testimonianze de Il Testimone non erano errate."
  },
  AvgDialog_22127_Content_33 = {
    Text = "...In effetti. La situazione a Cité è più o meno questa."
  },
  AvgDialog_22127_Content_34 = {
    Text = "Le cose qui sono strane, ma non sono ancora stati trovati pericoli né segni di Dissoluzione."
  },
  AvgDialog_22127_Content_35 = {
    Text = "Horla ed io ci prepariamo ad avanzare, trovare il contatto il prima possibile e verificare la situazione qui."
  },
  AvgDialog_22127_Content_36 = {
    Text = "La scuola si sta preparando a inviare rinforzi, ma ci vorrà del tempo."
  },
  AvgDialog_22127_Content_37 = {
    Text = "Compreso. Fino ad allora, lasciate a noi l'indagine nella Cité."
  },
  AvgDialog_22127_Content_38 = {
    Text = "Spegnendo il Comunicatore d'Argento, scruti vigile i dintorni."
  },
  AvgDialog_22127_Content_39 = {
    Text = "Questa città sembra avvolta da un filtro peculiare, con tutti gli edifici che si ergono bizzarramente come dipinti a olio spalmati a casaccio."
  },
  AvgDialog_22127_Content_4 = {
    Text = "La Cité di oggi fa davvero onore al suo nome."
  },
  AvgDialog_22127_Content_40 = {
    Text = "Cammini per questa strada da dieci minuti senza aver visto anima viva. Le uniche cose qui sono gli strani edifici lungo la via, circondati da grappoli di fiori in piena fioritura."
  },
  AvgDialog_22127_Content_41 = {
    Text = "In pieno giorno, ho camminato così a lungo senza vedere una sola persona... La gente della Cité non esce di casa?"
  },
  AvgDialog_22127_Content_42 = {Text = "SQUEAK!"},
  AvgDialog_22127_Content_43 = {
    Text = "Perché ti sei nascosta di nuovo dentro la pergamena...?"
  },
  AvgDialog_22127_Content_44 = {
    Text = "<Italic:La, laa, la-aah~>"
  },
  AvgDialog_22127_Content_45 = {
    Text = "Un Residente canticchia una melodia sconosciuta, passando dall'incrocio poco più avanti, mostrando solo la schiena."
  },
  AvgDialog_22127_Content_46 = {
    Text = "Indossa un completo che sembra eccessivamente stretto, e la forma della sua testa appare alquanto bizzarra."
  },
  AvgDialog_22127_Content_47 = {
    Text = "Ah... Grazie al cielo, finalmente vedo qualcuno."
  },
  AvgDialog_22127_Content_48 = {
    Text = "Ti fai avanti rapidamente."
  },
  AvgDialog_22127_Content_49 = {
    Text = "Salve, signore."
  },
  AvgDialog_22127_Content_5 = {
    Text = "Guidati dalla Dama di Nobiltà, avanzate, sopraffatti da tutto ciò che cattura il vostro sguardo."
  },
  AvgDialog_22127_Content_50 = {
    Text = "Ah, salve, {Male=signore,Female=signora}! Posso chiederle in cosa posso esserle d'aiuto?"
  },
  AvgDialog_22127_Content_51 = {Text = "!!!"},
  AvgDialog_22127_Content_52 = {
    Text = "Si voltò. Sopra il completo c'era l'enorme testa di un'ape."
  },
  AvgDialog_22127_Content_53 = {
    Text = "Che succede, {Male=signore,Female=signora}? Ho forse detto qualcosa di inopportuno che l'ha messa a disagio?"
  },
  AvgDialog_22127_Content_54 = {
    Text = "No... <Italic:coff—> No."
  },
  AvgDialog_22127_Content_55 = {
    Text = "Mi scusi, potrebbe indicarmi come raggiungere Viale Medici?"
  },
  AvgDialog_22127_Content_56 = {
    Text = "Ah, {Male=signore,Female=signora}, è nuovo della Cité, vero?"
  },
  AvgDialog_22127_Content_57 = {Text = "Sì."},
  AvgDialog_22127_Content_58 = {
    Text = "Non c'è da stupirsi, non conosce nemmeno la strada più famosa..."
  },
  AvgDialog_22127_Content_59 = {
    Text = "Stia tranquillo, i Cittadini della Cité sono molto ospitali. Viale Medici si trova proprio..."
  },
  AvgDialog_22127_Content_6 = {
    Text = "Camminate per le strade avvolte nella nebbia, sfiorando i mattoni macchiati degli edifici, cogliendo foglie di platano simili a Inchiostro Colorato."
  },
  AvgDialog_22127_Content_60 = {Text = "Huhhh—"},
  AvgDialog_22127_Content_61 = {
    Text = "Questo Signor Ape non terminò la frase e all'improvviso iniziò a convulsare in tutto il corpo."
  },
  AvgDialog_22127_Content_62 = {
    Text = "Un paio di grandi ali membranose squarciarono il suo cappotto, fondendosi e gocciolando come burro sotto il Sole cocente."
  },
  AvgDialog_22127_Content_63 = {
    Text = "Tesoro, Signor Ape! ..."
  },
  AvgDialog_22127_Content_64 = {Text = "Pop—"},
  AvgDialog_22127_Content_65 = {
    Text = "Il corpo dell'ape Umanoide cadde a terra, si annerì, poi si sgretolò in polvere disperdendosi nell'aria."
  },
  AvgDialog_22127_Content_66 = {
    Text = "Questi non sono i Sintomi tipici della Dissoluzione..."
  },
  AvgDialog_22127_Content_67 = {
    Text = "Esamini i dintorni con attenzione ancora una volta."
  },
  AvgDialog_22127_Content_68 = {
    Text = "Circondata da edifici che ricordano dipinti astratti. Osservando gli occasionali residenti in lontananza, puoi notare che i loro corpi somigliano a varie piante e animali."
  },
  AvgDialog_22127_Content_69 = {
    Text = "—La Cité davanti a me appare come se fosse stata strappata direttamente da qualche sogno bizzarro."
  },
  AvgDialog_22127_Content_7 = {
    Text = "Questa città sembra avvolta da un filtro peculiare: tutti gli edifici e le piante si ergono in un aspetto estremamente surreale, simile a un acquerello."
  },
  AvgDialog_22127_Content_70 = {Text = "Ding—"},
  AvgDialog_22127_Content_71 = {
    Text = "Il distintivo sul tuo petto brillava d'argento. Hai stabilito la comunicazione."
  },
  AvgDialog_22127_Content_72 = {
    Text = "Professoressa Doll, ho appena incontrato un Mutante da Dissoluzione atipico..."
  },
  AvgDialog_22127_Content_73 = {
    Text = "Chiamata dalla Cité. Un cittadino si è trasformato in D-polvere in una strada affollata."
  },
  AvgDialog_22127_Content_74 = {Text = "!!!"},
  AvgDialog_22127_Content_75 = {
    Text = "Esattamente uguale a ciò che ho incontrato qui..."
  },
  AvgDialog_22127_Content_76 = {
    Text = "Ma io sono nella Cité, e non somiglia affatto a una città vivace."
  },
  AvgDialog_22127_Content_77 = {
    Text = "In effetti, qui non c'è alcuna interfaccia tra il mondo reale e il Dominio. Ma se non è un Dominio, perché questo luogo e queste persone sono diventati così... Non ha senso."
  },
  AvgDialog_22127_Content_78 = {
    Text = "Sembra che questo Dominio sia diverso da quelli ordinari, uno spazio completamente indipendente."
  },
  AvgDialog_22127_Content_79 = {
    Text = "Ma il suo impatto sulla Cité è reale e tangibile."
  },
  AvgDialog_22127_Content_8 = {
    Text = "{Male=Signor,Female=Signora} Custode, guardate questa casa, vi sembra che ci siano delle linee che fluttuano su di essa?"
  },
  AvgDialog_22127_Content_80 = {
    Text = "In ogni caso, dobbiamo trovare la causa prima che la situazione degeneri ulteriormente."
  },
  AvgDialog_22127_Content_81 = {Text = "Capito."},
  AvgDialog_22127_Content_82 = {
    Text = "La comunicazione si interrompe. L'atmosfera si fa pesante."
  },
  AvgDialog_22127_Content_83 = {
    Text = "{Male=Signor,Female=Signora} Custode... Il signor Bee, è deceduto?"
  },
  AvgDialog_22127_Content_84 = {
    Text = "Guardi Horla e le dai una pacca sulla schiena."
  },
  AvgDialog_22127_Content_85 = {
    Text = "Questa non è la vera Cité. Forse è solo una sorta di illusione..."
  },
  AvgDialog_22127_Content_86 = {
    Text = "Lo spero..."
  },
  AvgDialog_22127_Content_87 = {
    Text = "Horla raccoglie una foglia di platano e la posa sulla D-polvere rimasta."
  },
  AvgDialog_22127_Content_88 = {
    Text = "Andiamo in Avenue Medici e troviamo il contatto per l'indagine."
  },
  AvgDialog_22127_Content_89 = {Text = "..."},
  AvgDialog_22127_Content_9 = {
    Text = "Come poesia incisa sugli edifici... così bella!"
  },
  AvgDialog_22127_Content_90 = {
    Text = "Guardi, {Male=Signor,Female=Signora} Custode! Un tram!"
  },
  AvgDialog_22127_Content_91 = {
    Text = "Hai camminato per un po', e una massa scura ti è venuta incontro."
  },
  AvgDialog_22127_Content_92 = {
    Text = "Ci sono dei tram, ma non abbiamo visto la fermata, quindi non siamo sicuri che vadano dove vogliamo andare."
  },
  AvgDialog_22127_Content_93 = {
    Text = "Te l'ho mai detto? Dalla recinzione del vecchio giardino si poteva vedere il tram passare, ma non ci sono mai salita davvero."
  },
  AvgDialog_22127_Content_94 = {
    Text = "Credo di ricordare che possa andare ovunque. In ogni caso, vorrei comunque salirci, almeno una volta sola."
  },
  AvgDialog_22127_Content_95 = {
    Text = "Ogni volta che vedo quel tram, sembra un gigantesco..."
  },
  AvgDialog_22127_Content_96 = {
    Text = "Salve, posso offrirvi un passaggio?"
  },
  AvgDialog_22127_Content_97 = {Text = "!!!"},
  AvgDialog_22127_Content_98 = {
    Text = "Sui binari tortuosi, un gigantesco Bruco si ferma davanti a te."
  },
  AvgDialog_22127_Content_99 = {
    Text = "Ah! Proprio come ricordavo! È il Treno Bruco!"
  },
  AvgDialog_22128_Content_1 = {
    Text = "Fragranza Residua"
  },
  AvgDialog_22128_Content_10 = {
    Text = "...Ho alcune faccende da sbrigare, vi prego di scusarmi..."
  },
  AvgDialog_22128_Content_11 = {
    Text = "Ehi ehi ehi! Signorina Nymphaea!"
  },
  AvgDialog_22128_Content_12 = {Text = "Hannah."},
  AvgDialog_22128_Content_13 = {
    Text = "Aspettate un momento, Custode! Ho urgente bisogno di vedere la signorina Nymphaea! Questa potrebbe benissimo essere una notizia da prima pagina!"
  },
  AvgDialog_22128_Content_14 = {
    Text = "Horla mi ha mandato a cercarvi."
  },
  AvgDialog_22128_Content_15 = {Text = "Eh?!!!"},
  AvgDialog_22128_Content_16 = {
    Text = "Hannah si fermò di colpo."
  },
  AvgDialog_22128_Content_17 = {
    Text = "Mi ha chiesto di darvi questo."
  },
  AvgDialog_22128_Content_18 = {
    Text = "La Dimora delle Rose, di Horla Colette..."
  },
  AvgDialog_22128_Content_19 = {
    Text = "Questo è... un poema di Horla?! E anche un nuovo pseudonimo?!"
  },
  AvgDialog_22128_Content_2 = {
    Text = "Signorina Nymphaea! Signorina Nymphaea!"
  },
  AvgDialog_22128_Content_20 = {
    Text = "Mi ha chiesto di riferirvi che, se lo ritenete valido, di aiutarla cortesemente a pubblicarlo su—"
  },
  AvgDialog_22128_Content_21 = {
    Text = "Nessun problema, nessun problema! Non importa se il poema sia buono o meno, purché generi un po' di clamore!"
  },
  AvgDialog_22128_Content_22 = {
    Text = "Inoltre, Custode, Horla è disposta ad accettare la mia intervista esclusiva?!"
  },
  AvgDialog_22128_Content_23 = {
    Text = "Portami da lei in silenzio, e..."
  },
  AvgDialog_22128_Content_24 = {
    Text = "Sii troppo bramosa, e potresti non riuscire nemmeno a far pubblicare quel poema."
  },
  AvgDialog_22128_Content_25 = {Text = "Oh..."},
  AvgDialog_22128_Content_26 = {
    Text = "Ho dato il poema a Hannah."
  },
  AvgDialog_22128_Content_27 = {
    Text = "Una volta mi dicesti che i poemi non portavano sventura, ma non riuscivo a crederci."
  },
  AvgDialog_22128_Content_28 = {
    Text = "Solo dopo ho compreso davvero."
  },
  AvgDialog_22128_Content_29 = {
    Text = "Grazie, {Male=Signor,Female=Signora} Custode!"
  },
  AvgDialog_22128_Content_3 = {
    Text = "Ah, signorina Hannah, siete venuta a trovarmi di nuovo..."
  },
  AvgDialog_22128_Content_30 = {
    Text = "Puoi serbare queste parole per quando Hannah ti intervisterà..."
  },
  AvgDialog_22128_Content_31 = {
    Text = "Ah... no, no... ancora non oso parlare con gli altri... ma mi abituerò gradualmente!"
  },
  AvgDialog_22128_Content_32 = {
    Text = "Scherzavo. Ho già declinato al posto tuo."
  },
  AvgDialog_22128_Content_33 = {
    Text = "Horla lascia sfuggire un profondo sospiro. Ti avvicini a lei."
  },
  AvgDialog_22128_Content_34 = {
    Text = "Sai, anche se Hannah pubblicasse quella poesia, a pochi importerebbe davvero."
  },
  AvgDialog_22128_Content_35 = {
    Text = "Ciò che interessa davvero alla gente sono le storie e gli argomenti che ruotano attorno a quella raccolta di poesie."
  },
  AvgDialog_22128_Content_36 = {
    Text = "Hmm, lo so, {Male=Signor,Female=Signora} Custode."
  },
  AvgDialog_22128_Content_37 = {
    Text = "Persino in una città come Cité, i veri lettori di poesia sono pochissimi..."
  },
  AvgDialog_22128_Content_38 = {
    Text = "E non ti dà fastidio?"
  },
  AvgDialog_22128_Content_39 = {
    Text = "Per Colette, questo è il modo migliore per rendere Tributo."
  },
  AvgDialog_22128_Content_4 = {
    Text = "Beh, sono felice di vedervi anche io!"
  },
  AvgDialog_22128_Content_40 = {
    Text = "Quanto al poema in sé..."
  },
  AvgDialog_22128_Content_41 = {
    Text = "Colse un petalo da una rosa sopra il suo occhio e lo portò al naso."
  },
  AvgDialog_22128_Content_42 = {
    Text = "A Cité, anche dove i fiori non si vedono, la loro fragranza pervade l'aria."
  },
  AvgDialog_22128_Content_43 = {
    Text = "La poesia, come i fiori, non ha sempre bisogno di essere vista..."
  },
  AvgDialog_22128_Content_44 = {
    Text = "Voltò il capo e ti rivolse un sorriso."
  },
  AvgDialog_22128_Content_45 = {
    Text = "{Male=Signore,Female=Signora} Custode, anche voi ci credete?"
  },
  AvgDialog_22128_Content_46 = {
    Text = "A Cité in pochi leggono poesia, ma io credo che le rose siano fiorite nei loro cuori già da molto tempo."
  },
  AvgDialog_22128_Content_47 = {
    Text = "Alzò la mano. Petali cremisi si librarono con grazia dal suo palmo."
  },
  AvgDialog_22128_Content_48 = {
    Text = "Il vento porta il profumo delle rose, come se soffiasse dalla Cité di decenni fa."
  },
  AvgDialog_22128_Content_5 = {
    Text = "Ehm, ho una questione urgente da chiedervi..."
  },
  AvgDialog_22128_Content_6 = {
    Text = "Non so dove sia Horla."
  },
  AvgDialog_22128_Content_7 = {
    Text = "Cosa?! Com'è possibile! È tornata da un giorno intero e ancora non ti ha contattato?!"
  },
  AvgDialog_22128_Content_8 = {
    Text = "Che le voci sul fatto che voi due non andiate d'accordo siano vere?"
  },
  AvgDialog_22128_Content_9 = {
    Text = "Si tratta di reciproco disdegno tra appassionati di letteratura? O siete diventate rivali in amore?!"
  },
  AvgDialog_22129_Content_1 = {Text = "Salmo 1843"},
  AvgDialog_22129_Content_10 = {
    Text = "Horla... va tutto bene. Sono solo figure del Poema, non preoccuparti."
  },
  AvgDialog_22129_Content_11 = {
    Text = "Questa gabbia dev'essere un prodotto della Dissoluzione. Prendimi tempo; troverò presto una via d'uscita."
  },
  AvgDialog_22129_Content_12 = {
    Text = "Ah, quasi dimenticavo. Sei ancora così timida, Horla."
  },
  AvgDialog_22129_Content_13 = {
    Text = "Horla sbirciò lentamente da sotto la pergamena."
  },
  AvgDialog_22129_Content_14 = {
    Text = "Colette, ho letto la lettera che hai scritto a Herbert..."
  },
  AvgDialog_22129_Content_15 = {
    Text = "Mi piacerebbe davvero sentire come pensi di persuadermi in questo momento."
  },
  AvgDialog_22129_Content_16 = {
    Text = "Non sto cercando di persuaderti... Capisco perché stai facendo tutto questo."
  },
  AvgDialog_22129_Content_17 = {
    Text = "Eh... Cosa?"
  },
  AvgDialog_22129_Content_18 = {
    Text = "Per la fama e il Potere, sacrificare me, sacrificare la poesia, sacrificare la Cité... Tutto questo, posso comprenderlo."
  },
  AvgDialog_22129_Content_19 = {
    Text = "Amo scrivere poesie, Colette. Cerco di ascoltare le Voci di tutte le persone e le cose... Sei la mia migliore amica — come potrei non sentire il tuo cuore?"
  },
  AvgDialog_22129_Content_2 = {
    Text = "Lady Colette! I cittadini della Cité vi resteranno fedeli per sempre!"
  },
  AvgDialog_22129_Content_20 = {
    Text = "Ma dopo che la Dissoluzione si sarà propagata... questo giardino verrà cancellato dalla Memoria di Tutti..."
  },
  AvgDialog_22129_Content_21 = {
    Text = "Tutto ciò che è accaduto qui, i giorni felici e tristi che abbiamo trascorso insieme... Puoi davvero lasciar andare tutto questo?"
  },
  AvgDialog_22129_Content_22 = {
    Text = "Colette si fermò un istante, poi scoppiò a ridere. La sua risata si fece sempre più forte, quasi facendole dimenticare di mantenere il suo portamento Nobile."
  },
  AvgDialog_22129_Content_23 = {
    Text = "Pensavo... volessi dirmi qualcosa..."
  },
  AvgDialog_22129_Content_24 = {
    Text = "La Cité è piena di persone delle cui vite non mi importa nulla. Credi che mi importi di un misero giardino?"
  },
  AvgDialog_22129_Content_25 = {
    Text = "Inspirò profondamente e si raddrizzò."
  },
  AvgDialog_22129_Content_26 = {
    Text = "Horla, sei stata popolare fin da quando eri piccola. Anche se sono io quella che ha lavorato duramente per mantenerci, la gente ha sempre lodato te..."
  },
  AvgDialog_22129_Content_27 = {
    Text = "Possiedi un Talento straordinario, ma e allora? Ci sono verità che non comprenderai mai."
  },
  AvgDialog_22129_Content_28 = {
    Text = "Poesia, emozioni, Memorie, morale... Solo fardelli. Solo il Potere e la fama sono davvero eterni."
  },
  AvgDialog_22129_Content_29 = {
    Text = "Ben detto! Lady Colette!"
  },
  AvgDialog_22129_Content_3 = {
    Text = "Muoviti! Mi stai bloccando la strada!"
  },
  AvgDialog_22129_Content_30 = {
    Text = "La piazza esplode in Applausi e ovazioni, sommergendoti in un'ondata di suono."
  },
  AvgDialog_22129_Content_31 = {
    Text = "Ascolta, Horla. Odi le voci del popolo della Cité."
  },
  AvgDialog_22129_Content_32 = {
    Text = "In questo mondo, la poesia non ha alcun significato. In un altro mondo, è lo stesso."
  },
  AvgDialog_22129_Content_33 = {
    Text = "Quindi è questo che pensi... Capisco, Colette."
  },
  AvgDialog_22129_Content_34 = {
    Text = "A essere sincera, sono davvero felice che tu sia potuto venire qui."
  },
  AvgDialog_22129_Content_35 = {
    Text = "Nel momento più cruciale della mia vita, sei diventato ancora una volta il mio testimone."
  },
  AvgDialog_22129_Content_36 = {
    Text = "Alza le braccia."
  },
  AvgDialog_22129_Content_37 = {
    Text = "Nella piazza, tutti si inginocchiarono davanti a lei."
  },
  AvgDialog_22129_Content_38 = {
    Text = "Nessuna poesia, nessuna predica. Solo un'immaginaria adorazione fanatica. Solo puro Potere."
  },
  AvgDialog_22129_Content_39 = {
    Text = "La Terra comincia a tremare. Noti la Dissoluzione che si propaga visibilmente dal centro del Poema."
  },
  AvgDialog_22129_Content_4 = {
    Text = "Signora Colette! Signora Colette, guardi qui!!"
  },
  AvgDialog_22129_Content_40 = {
    Text = "Guarda, Horla. Guardami ottenere un'altra vittoria—"
  },
  AvgDialog_22129_Content_41 = {Text = "Clang—"},
  AvgDialog_22129_Content_42 = {Text = "?!"},
  AvgDialog_22129_Content_43 = {
    Text = "Un lampo di luce argentea. La gabbia svanisce, e tu e Horla cadete a terra."
  },
  AvgDialog_22129_Content_44 = {
    Text = "Potrebbe essere stato un errore portarmi qui come spettatore, Sig.ra Colette."
  },
  AvgDialog_22129_Content_45 = {
    Text = "La Chiave d'Argento di Mythag... Persino il Sig. Herbert ne è piuttosto invidioso."
  },
  AvgDialog_22129_Content_46 = {
    Text = "Ma sono curioso — anche in un posto come questo, cosa puoi fare anche se riesci a fuggire dalla gabbia?"
  },
  AvgDialog_22129_Content_5 = {
    Text = "Piazza Rosa è gremita. Tutti i Cittadini della Cité si sono radunati qui. Dall'alto, sembra una massa nera e immensa che si contorce."
  },
  AvgDialog_22129_Content_6 = {
    Text = "Che scena ispiratrice... non trovi?"
  },
  AvgDialog_22129_Content_7 = {
    Text = "Colette, nei suoi abiti migliori, si erge sul grande palco, salutando con eleganza verso il basso."
  },
  AvgDialog_22129_Content_8 = {
    Text = "Dietro di lei, una gabbia nera di materiale sconosciuto imprigiona te e Horla, appesa nel retroscena."
  },
  AvgDialog_22129_Content_9 = {
    Text = "Sotto lo Sguardo della Folla, Horla si ritrova rannicchiata sotto la pergamena, tremante in modo incontrollabile."
  },
  AvgDialog_22130_Content_10 = {
    Text = "Forse il vecchio che fumava poco fa è un membro segreto del Comitato."
  },
  AvgDialog_22130_Content_100 = {
    Text = "S-Sì... Signora..."
  },
  AvgDialog_22130_Content_101 = {
    Text = "Horla, hai disattivato il tuo velo?"
  },
  AvgDialog_22130_Content_102 = {
    Text = "No... Signora, potete vedermi?"
  },
  AvgDialog_22130_Content_103 = {
    Text = "Nella nuova Cité, ogni cosa bella merita di essere contemplata."
  },
  AvgDialog_22130_Content_104 = {
    Text = "La nuova Cité..."
  },
  AvgDialog_22130_Content_105 = {
    Text = "Ah, siamo arrivati."
  },
  AvgDialog_22130_Content_106 = {Text = "Ti volti."},
  AvgDialog_22130_Content_107 = {
    Text = "Un dipinto come non ne avete mai visti si dispiega davanti ai vostri occhi."
  },
  AvgDialog_22130_Content_108 = {
    Text = "La nave da crociera urta il buffer della riva, producendo un tonfo sordo."
  },
  AvgDialog_22130_Content_109 = {
    Text = "Voi e Horla restate a fissare sbigottiti, come se aveste dimenticato come camminare."
  },
  AvgDialog_22130_Content_11 = {
    Text = "Ho sempre avvertito qualcosa di molto misterioso in lui... Chi può dirlo?"
  },
  AvgDialog_22130_Content_110 = {
    Text = "La mia automobile non arriverà per un po', quindi lasciate che vi faccia da guida."
  },
  AvgDialog_22130_Content_111 = {
    Text = "Solleva la mano, il braccio che traccia un arco elegante."
  },
  AvgDialog_22130_Content_112 = {
    Text = "Benvenuti a Cité, ospiti venuti da lontano."
  },
  AvgDialog_22130_Content_12 = {
    Text = "La luce del sole inondava il ponte. Horla chiuse gli occhi, le braccia leggermente aperte."
  },
  AvgDialog_22130_Content_13 = {
    Text = "Notando il tuo sguardo, ritrasse timidamente le mani e le nascose dietro la schiena."
  },
  AvgDialog_22130_Content_14 = {
    Text = "Niente male, molto meglio di quanto mi aspettassi."
  },
  AvgDialog_22130_Content_15 = {
    Text = "Pensavo che avresti voluto tornare indietro dopo aver visto tutta quella gente sulla crociera."
  },
  AvgDialog_22130_Content_16 = {
    Text = "Ci ho pensato in quel momento, ma non ho avuto il coraggio di dirtelo..."
  },
  AvgDialog_22130_Content_17 = {
    Text = "Ah! {Male=Signor,Female=Signora} Custode, guarda! È il fiume Szenyér!"
  },
  AvgDialog_22130_Content_18 = {
    Text = "L'immensità del mare durò solo un breve istante. Ben presto, un faro emerse lentamente da sotto l'orizzonte."
  },
  AvgDialog_22130_Content_19 = {
    Text = "Dietro di esso, un ampio estuario e le città sfocate su entrambe le rive apparvero alla vista."
  },
  AvgDialog_22130_Content_2 = {Text = "Casa"},
  AvgDialog_22130_Content_20 = {
    Text = "Signorina Nymphaea! Signorina Nymphaea!"
  },
  AvgDialog_22130_Content_21 = {
    Text = "Salve, posso chiederle in cosa posso assisterla?"
  },
  AvgDialog_22130_Content_22 = {
    Text = "Avete visto Horla? È urgente!"
  },
  AvgDialog_22130_Content_23 = {
    Text = "Non avete un circolo di poesia o qualcosa del genere? Secondo il mio informatore, Horla sembra frequentare spesso i vostri eventi."
  },
  AvgDialog_22130_Content_24 = {
    Text = "Le sei così vicino, devi sapere dove si trova, giusto?!"
  },
  AvgDialog_22130_Content_25 = {
    Text = "Mi dispiace, ho visto Horla l'ultima volta due mesi fa... Non ama i luoghi affollati."
  },
  AvgDialog_22130_Content_26 = {
    Text = "Hai i suoi poemi? Il vostro circolo di poesia deve aver raccolto molte delle sue opere, giusto?!"
  },
  AvgDialog_22130_Content_27 = {
    Text = "Se li avete, sarei disposto a pagare un prezzo elevato."
  },
  AvgDialog_22130_Content_28 = {
    Text = "Hannah, hai qualcosa da chiederle?"
  },
  AvgDialog_22130_Content_29 = {
    Text = "Il giornale scolastico non ha ricevuto molta attenzione ultimamente. Horla non ha mai amato essere intervistata, nemmeno per pubblicare i propri poemi."
  },
  AvgDialog_22130_Content_3 = {
    Text = "Bene, Horla, i passeggeri accanto a noi se ne sono andati."
  },
  AvgDialog_22130_Content_30 = {
    Text = "Se riuscissimo a pubblicare le sue poesie o addirittura a farle un'intervista esclusiva, le vendite del giornale scolastico di questo mese raddoppierebbero di sicuro!"
  },
  AvgDialog_22130_Content_31 = {
    Text = "Ho già pensato al titolo: \"Giardino e Primavera — Le storie mai raccontate della giovane poetessa Horla\"..."
  },
  AvgDialog_22130_Content_32 = {
    Text = "...Secondo le statistiche, il numero attuale di avvistamenti ha raggiunto le doppie cifre."
  },
  AvgDialog_22130_Content_33 = {
    Text = "Secondo i testimoni oculari, i cambiamenti nella Cité non sembrano essere causati da una normale Dissoluzione."
  },
  AvgDialog_22130_Content_34 = {
    Text = "La Cité attuale è molto..."
  },
  AvgDialog_22130_Content_35 = {Text = "Molto...?"},
  AvgDialog_22130_Content_36 = {
    Text = "Nelle parole di un testimone oculare: \"Era bellissimo.\""
  },
  AvgDialog_22130_Content_37 = {
    Text = "Dissoluzione... bella?"
  },
  AvgDialog_22130_Content_38 = {
    Text = "La mancanza di logica è una caratteristica comune delle testimonianze oculari."
  },
  AvgDialog_22130_Content_39 = {
    Text = "Dalle loro parole confuse, si può concludere che l'unicità e l'Impatto di questo Evento siano estremamente rari, eppure il rischio manifestato è minimo, creando un contrasto netto."
  },
  AvgDialog_22130_Content_4 = {
    Text = "Davvero? Non mi stai ingannando?"
  },
  AvgDialog_22130_Content_40 = {
    Text = "Non abbiamo mai riscontrato un Evento simile. Se sia il risultato della Dissoluzione resta ignoto."
  },
  AvgDialog_22130_Content_41 = {
    Text = "Cosa ha detto il contatto a Cité?"
  },
  AvgDialog_22130_Content_42 = {
    Text = "Il contatto ha riferito che tutto era nella norma, quindi il Livello di questo Evento non è elevato. Ma dobbiamo comunque inviare qualcuno alla Cité per verificare..."
  },
  AvgDialog_22130_Content_43 = {Text = "Bang—"},
  AvgDialog_22130_Content_44 = {
    Text = "Prima che Doll finisse di parlare, una figura bianca scivolò nell'ufficio come un fantasma e si nascose dietro la tenda."
  },
  AvgDialog_22130_Content_45 = {Text = "..."},
  AvgDialog_22130_Content_46 = {Text = "..."},
  AvgDialog_22130_Content_47 = {
    Text = "Horla, se ti stai nascondendo da qualcuno... hai dimenticato di chiudere la Porta."
  },
  AvgDialog_22130_Content_48 = {
    Text = "Ah! Mi dispiace tanto! Vi ho causato problemi... {Male=Signor,Female=Signora} Custode! Signorina Doll!"
  },
  AvgDialog_22130_Content_49 = {
    Text = "Chiuse in fretta la Porta dell'ufficio e si nascose rapidamente dietro le tende."
  },
  AvgDialog_22130_Content_5 = {
    Text = "...Davvero."
  },
  AvgDialog_22130_Content_50 = {
    Text = "Horla! Dove sei? Horla!"
  },
  AvgDialog_22130_Content_51 = {
    Text = "Vieni fuori, cara Horla! Ci serve solo una breve intervista~ Non farà male, promesso!"
  },
  AvgDialog_22130_Content_52 = {
    Text = "La voce di Hannah si allontana dall'altro lato della porta."
  },
  AvgDialog_22130_Content_53 = {
    Text = "Hai finalmente iniziato a tormentare Horla? Sembra che la pressione per le vendite del giornale scolastico sia diventata davvero considerevole."
  },
  AvgDialog_22130_Content_54 = {
    Text = "Va bene se non vuoi fare l'intervista. Basta consegnare a Hannah alcune delle tante poesie che hai scritto, e ti lascerà in pace."
  },
  AvgDialog_22130_Content_55 = {
    Text = "Io... non ne ho molta voglia..."
  },
  AvgDialog_22130_Content_56 = {
    Text = "Quelle poesie portano solo sventura... Non voglio che accada di nuovo."
  },
  AvgDialog_22130_Content_57 = {
    Text = "Ricordando ciò che Horla aveva vissuto, comprendesti il suo significato e annuisti."
  },
  AvgDialog_22130_Content_58 = {
    Text = "Dovrei stare all'aperto, non in un luogo affollato come la scuola..."
  },
  AvgDialog_22130_Content_59 = {
    Text = "{Male=Signor,Female=Signora} Custode, posso chiedervi aiuto per trovare una soluzione?"
  },
  AvgDialog_22130_Content_6 = {
    Text = "Horla fece capolino da sotto la grande pergamena, guardandosi intorno con cautela."
  },
  AvgDialog_22130_Content_60 = {
    Text = "A dire il vero, non ho buone soluzioni per affrontare l'agilità e il fiuto di quel furetto."
  },
  AvgDialog_22130_Content_61 = {
    Text = "—Tuttavia, se preferisci stare all'aperto, c'è un modo in cui posso aiutarti."
  },
  AvgDialog_22130_Content_62 = {
    Text = "Ah... Devo davvero uscire..."
  },
  AvgDialog_22130_Content_63 = {
    Text = "Dove andremmo?"
  },
  AvgDialog_22130_Content_64 = {
    Text = "Prendi la foto dal tavolo e la agiti davanti a lei."
  },
  AvgDialog_22130_Content_65 = {
    Text = "Cité, casa tua."
  },
  AvgDialog_22130_Content_66 = {
    Text = "La crociera scivola in silenzio, le case e i fiori su entrambi i lati sfumano lentamente alle spalle, svanendo alla curva del fiume Szenyér."
  },
  AvgDialog_22130_Content_67 = {
    Text = "Horla chiuse gli occhi. Un sorriso sbocciò sul suo volto."
  },
  AvgDialog_22130_Content_68 = {
    Text = "È il vento di Cité! Cité è la città dei fiori, e persino il vento porta con sé il profumo dei fiori."
  },
  AvgDialog_22130_Content_69 = {
    Text = "Anche dopo tutti questi anni, nel momento in cui lo sento, ricordo."
  },
  AvgDialog_22130_Content_7 = {
    Text = "Dopo essersi assicurata che non ci fossero estranei nei paraggi, emise un lungo sospiro e strisciò fuori da sotto la pergamena."
  },
  AvgDialog_22130_Content_70 = {
    Text = "Ti mancano i panorami di Cité?"
  },
  AvgDialog_22130_Content_71 = {
    Text = "Certo! Ma ho sempre vissuto nella serra. Non sono mai stata nella maggior parte dei luoghi di Cité."
  },
  AvgDialog_22130_Content_72 = {
    Text = "Ho scritto molti poemi sui paesaggi di Cité, ma erano finzione... Se questa volta ci sarà l'occasione, vorrei vedere quei luoghi."
  },
  AvgDialog_22130_Content_73 = {
    Text = "Dove vorresti andare più di tutto?"
  },
  AvgDialog_22130_Content_74 = {
    Text = "Il luogo che desidero visitare di più... hmm, sarebbe il giardino dove vivevo un tempo."
  },
  AvgDialog_22130_Content_75 = {
    Text = "Ogni stagione delle rose, il giardino è in piena fioritura, come vivere in un sogno!"
  },
  AvgDialog_22130_Content_76 = {
    Text = "Solo che non so se le rose e il libro di poemi siano ancora lì dopo quell'incendio..."
  },
  AvgDialog_22130_Content_77 = {
    Text = "Quando scoppiò l'incendio, non riuscii a fuggire, così seppellii la mia raccolta di poemi nel giardino. Questa volta, intendo ritrovarla."
  },
  AvgDialog_22130_Content_78 = {
    Text = "Dopo tutto ciò che hai vissuto a Cité, non pensavo che questo luogo ti piacesse o che volessi rivedere quel poema."
  },
  AvgDialog_22130_Content_79 = {
    Text = "Quelle cose non hanno nulla a che fare con questa terra o la sua gente... Cité è un luogo meraviglioso."
  },
  AvgDialog_22130_Content_8 = {
    Text = "Lo sai che non possono vederti, vero?"
  },
  AvgDialog_22130_Content_80 = {
    Text = "Quanto al poema... non saprei dire, {Male=Signore,Female=Signora} Custode."
  },
  AvgDialog_22130_Content_81 = {
    Text = "Porta molta sofferenza a chi mi circonda, e questo mi dispiace, ma... è anche il mio bene più prezioso."
  },
  AvgDialog_22130_Content_82 = {
    Text = "Che sia da conservare o da distruggere, voglio comunque ritrovarlo."
  },
  AvgDialog_22130_Content_83 = {
    Text = "Non preoccuparti, ti ci porterò sicuramente. Solo non sono certo che riusciremo ancora a trovarlo dopo tutti questi anni."
  },
  AvgDialog_22130_Content_84 = {
    Text = "Una farfalla nera volteggia con grazia e si posa sulla punta del dito teso di Horla."
  },
  AvgDialog_22130_Content_85 = {
    Text = "Guardate, {Male=Signor,Female=Signora} Custode, una farfalla!"
  },
  AvgDialog_22130_Content_86 = {
    Text = "Se una farfalla si posa su qualcuno, significa che, agli occhi della farfalla, la vita di quella persona è come un fiore."
  },
  AvgDialog_22130_Content_87 = {
    Text = "Per la gente della Cité, una vita simile a un fiore porta sempre buona fortuna~"
  },
  AvgDialog_22130_Content_88 = {
    Text = "Esatto, signorina. Profumate di rose."
  },
  AvgDialog_22130_Content_89 = {
    Text = "La Cité ha molti splendidi giardini di rose; vi sentirete come a casa qui~"
  },
  AvgDialog_22130_Content_9 = {
    Text = "Non necessariamente. Tra i viaggiatori potrebbero esserci Risvegliati, ricercatori con equipaggiamento speciale, o individui dotati..."
  },
  AvgDialog_22130_Content_90 = {Text = "!!!"},
  AvgDialog_22130_Content_91 = {
    Text = "Horla, fai attenzione!"
  },
  AvgDialog_22130_Content_92 = {
    Text = "Non avete mai visto una farfalla parlare. Avete ritratto dolcemente Horla."
  },
  AvgDialog_22130_Content_93 = {
    Text = "Oh, una farfalla parlante?!"
  },
  AvgDialog_22130_Content_94 = {
    Text = "Signora Farfalla, mi scusi... I-io non sono molto brava nelle chiacchiere..."
  },
  AvgDialog_22130_Content_95 = {
    Text = "Nessuna aggressività, non sembra un Mutante da Dissoluzione... né un Fantasma..."
  },
  AvgDialog_22130_Content_96 = {
    Text = "L'umanoide farfalla, nera come la pece, batté le ali e si allontanò dalla nave da crociera oscillando qua e là. Vi guardaste intorno con cautela. Il fiume Szenyér continuava a scorrere silenzioso."
  },
  AvgDialog_22130_Content_97 = {
    Text = "Gli esseri umani che diventano farfalle... una bella immagine, non è vero?"
  },
  AvgDialog_22130_Content_98 = {
    Text = "Una Dama di Nobiltà elegantemente vestita appare al vostro fianco senza che ve ne accorgiate. Volge il viso verso il fiume Szenyér e rivolge a Horla un lieve sorriso."
  },
  AvgDialog_22130_Content_99 = {
    Text = "Tuttavia, signorina. La rosa sul vostro occhio è assai più bella di una farfalla."
  },
  AvgDialog_22132_Content_1 = {
    Text = "Elegia del Giardino"
  },
  AvgDialog_22132_Content_10 = {
    Text = "Povera bambina... tu e Horla siete come sorelle..."
  },
  AvgDialog_22132_Content_100 = {
    Text = "Tiri fuori il poema."
  },
  AvgDialog_22132_Content_101 = {Text = "Ti manca?"},
  AvgDialog_22132_Content_102 = {
    Text = "Mi manca molto, moltissimo... Ma va bene così, {Male=Signor,Female=Signora} Custode."
  },
  AvgDialog_22132_Content_103 = {
    Text = "Si asciugò le lacrime e scosse il capo con un sorriso."
  },
  AvgDialog_22132_Content_104 = {
    Text = "Per me, per Colette e per tutta la Cité, questo poema porta solo dolore infinito..."
  },
  AvgDialog_22132_Content_105 = {
    Text = "{Male=Signor,Female=Signora} Custode, posso?"
  },
  AvgDialog_22132_Content_106 = {
    Text = "Consegna il poema a Horla"
  },
  AvgDialog_22132_Content_107 = {
    Text = "Mi mancherà. Ma dovrebbe esistere solo nelle mie memorie."
  },
  AvgDialog_22132_Content_108 = {Text = "Addio..."},
  AvgDialog_22132_Content_109 = {
    Text = "Fiamme si accesero nella mano di Horla. In breve, il poema si trasformò in un cumulo di ceneri tra le fiamme."
  },
  AvgDialog_22132_Content_11 = {
    Text = "Horla non c'è più. Devi vivere bene. Il suo Spirito ti benedirà..."
  },
  AvgDialog_22132_Content_110 = {
    Text = "Questo libro e io avremmo dovuto condividere lo stesso fato, ridotti in ceneri molto tempo fa... Non ci sarebbero stati tutti questi problemi, altrimenti."
  },
  AvgDialog_22132_Content_111 = {
    Text = "Finalmente, il problema è risolto."
  },
  AvgDialog_22132_Content_112 = {
    Text = "{Male=Signor,Female=Signora} Custode, non mi sembra di notare alcun cambiamento?"
  },
  AvgDialog_22132_Content_113 = {
    Text = "Con un impatto così diffuso, potrebbe volerci del tempo prima che si dissipi. Andiamocene per ora..."
  },
  AvgDialog_22132_Content_114 = {
    Text = "Ti piace questa stanza, Horla? Ogni cosa qui è stata conservata esattamente com'era decenni fa."
  },
  AvgDialog_22132_Content_115 = {Text = "!!!"},
  AvgDialog_22132_Content_116 = {
    Text = "Il poema è già stato bruciato... Il tuo piano è fallito, Colette."
  },
  AvgDialog_22132_Content_117 = {
    Text = "I poemi? Oh, intendi questo..."
  },
  AvgDialog_22132_Content_118 = {
    Text = "Agitò la mano, e una nuova raccolta di poemi apparve tra le sue dita, identica a quella che era stata bruciata."
  },
  AvgDialog_22132_Content_119 = {
    Text = "Liquido di dissoluzione nero gocciola a terra dal poema."
  },
  AvgDialog_22132_Content_12 = {
    Text = "Non lasciarla triste... Colette, vivi una bella vita."
  },
  AvgDialog_22132_Content_120 = {Text = "!!!"},
  AvgDialog_22132_Content_121 = {Text = "Tu..."},
  AvgDialog_22132_Content_122 = {
    Text = "È una trappola... Horla, preparati all'attacco!"
  },
  AvgDialog_22132_Content_123 = {Text = "Bang—"},
  AvgDialog_22132_Content_124 = {
    Text = "Una gabbia appare improvvisamente accanto a te, intrappolandoti al suo interno."
  },
  AvgDialog_22132_Content_125 = {
    Text = "Questo è... non dovrebbero esserci cose simili nel poema..."
  },
  AvgDialog_22132_Content_126 = {
    Text = "Parole del genere non furono mai scritte nei poemi di Horla."
  },
  AvgDialog_22132_Content_127 = {
    Text = "Mi dispiace, ma questa è la mia raccolta di poemi. Qualsiasi cosa io desideri apparirà qui."
  },
  AvgDialog_22132_Content_128 = {
    Text = "Sorridendo, alzò la mano e ripose la raccolta di poemi nel petto."
  },
  AvgDialog_22132_Content_129 = {
    Text = "...In questa Cité, io sono l'unico padrone."
  },
  AvgDialog_22132_Content_13 = {
    Text = "All'inizio, molte persone vennero a confortarla. A poco a poco, tutti si allontanarono, lasciandola sola con i suoi pensieri."
  },
  AvgDialog_22132_Content_130 = {
    Text = "Clang— Clang— Clang—"
  },
  AvgDialog_22132_Content_131 = {
    Text = "Ascolta, Horla. La campana di mezzanotte ha suonato."
  },
  AvgDialog_22132_Content_132 = {
    Text = "Oggi è il più grandioso festival della Cité... Ho l'onore di avere due illustri ospiti qui a testimoniare la cerimonia."
  },
  AvgDialog_22132_Content_133 = {
    Text = "Guardie, portateli in piazza."
  },
  AvgDialog_22132_Content_134 = {
    Text = "Ho preparato i posti migliori per i nostri due illustri ospiti."
  },
  AvgDialog_22132_Content_14 = {
    Text = "Colette rimase immobile accanto alle ceneri della serra che aveva mantenuto con tanta cura, lasciando che le braci le bruciassero il volto."
  },
  AvgDialog_22132_Content_15 = {
    Text = "Una lacrima le scivolò lungo il viso, evaporando rapidamente nel Calore Residuo delle fiamme."
  },
  AvgDialog_22132_Content_16 = {
    Text = "Horla, avevano ragione... Tu mi benedirai. Non mi odierai."
  },
  AvgDialog_22132_Content_17 = {
    Text = "Non mi odierai per averti portato via tutto — il tuo Talento, la tua Vita... Nonostante ciò, non mi odierai comunque."
  },
  AvgDialog_22132_Content_18 = {
    Text = "Sei così gentile e Nobile. Al tuo cospetto, tutti gli altri appaiono volgari e meschini."
  },
  AvgDialog_22132_Content_19 = {
    Text = "Ho cercato con tutte le mie forze di vivere... Ma rispetto a te, perché sono sempre io quella spregevole?"
  },
  AvgDialog_22132_Content_2 = {
    Text = "Fuoco! Presto, spegnetelo!"
  },
  AvgDialog_22132_Content_20 = {
    Text = "Così crudele, Horla. Non mi dai una sola ragione per odiarti. Mi costringi a vivere i miei giorni restanti nel dolore..."
  },
  AvgDialog_22132_Content_21 = {
    Text = "Un singhiozzo. Colette si asciuga le lacrime. La cenere le si spalma sul viso, decorandolo in modo disordinato."
  },
  AvgDialog_22132_Content_22 = {
    Text = "Imitò una Nobile, alzando fieramente il capo e sorridendo al giardino ormai ridotto a braci e ceneri."
  },
  AvgDialog_22132_Content_23 = {
    Text = "...Addio, allora, Horla."
  },
  AvgDialog_22132_Content_24 = {Text = "Splash—"},
  AvgDialog_22132_Content_25 = {
    Text = "Una lacrima cade sulla raccolta di poesie, producendo un suono nitido nella Stanza."
  },
  AvgDialog_22132_Content_26 = {
    Text = "Sono passati molti, molti anni dall'ultima volta che ho provato qualcosa del genere... Horla, sei ancora piena di sorprese come un tempo."
  },
  AvgDialog_22132_Content_27 = {
    Text = "Chiedi, perché non hai lasciato la tua immagine nel Poema?"
  },
  AvgDialog_22132_Content_28 = {
    Text = "È stato davvero difficile rivederti... Che peccato."
  },
  AvgDialog_22132_Content_29 = {
    Text = "Lady Colette, la campana di mezzanotte sta per suonare. Vi prego di prepararvi."
  },
  AvgDialog_22132_Content_3 = {
    Text = "È troppo tardi... Del giardino non resta più nulla..."
  },
  AvgDialog_22132_Content_30 = {
    Text = "Hmm, capito."
  },
  AvgDialog_22132_Content_31 = {
    Text = "È seduta davanti al Riflesso mentre l'Ancella le asciuga delicatamente le lacrime con un fazzoletto."
  },
  AvgDialog_22132_Content_32 = {
    Text = "Oggi è un grande giorno. Persino il miglior pubblico è arrivato... Il trucco non deve essere rovinato oggi."
  },
  AvgDialog_22132_Content_33 = {
    Text = "Fissa intensamente il proprio riflesso nello specchio, piegando le labbra in un sorriso degno di nobiltà e vittoria."
  },
  AvgDialog_22132_Content_34 = {
    Text = "{Male=Signor,Female=Signora} Custode, da questa parte!"
  },
  AvgDialog_22132_Content_35 = {
    Text = "Il sentiero verso la torre dell'orologio è davvero complesso... e ci sono molti mostri a fare la guardia lungo il cammino."
  },
  AvgDialog_22132_Content_36 = {
    Text = "Nel poema \"Le Campane della Città della Poesia,\" il sentiero verso la torre dell'orologio è un labirinto. Simboleggia la confusione nel cuore dei residenti della città."
  },
  AvgDialog_22132_Content_37 = {
    Text = "Un'immagine appropriata."
  },
  AvgDialog_22132_Content_38 = {
    Text = "Che retorica inopportuna..."
  },
  AvgDialog_22132_Content_39 = {
    Text = "Evitando le ricerche dei mostri, arrivate all'ultimo piano."
  },
  AvgDialog_22132_Content_4 = {
    Text = "Sono stati tutti tratti in salvo?"
  },
  AvgDialog_22132_Content_40 = {
    Text = "La torre dell'orologio è proprio lì! Basta attraversare questo corridoio."
  },
  AvgDialog_22132_Content_41 = {
    Text = "C'è un solo mostro a guardia di questo luogo?"
  },
  AvgDialog_22132_Content_42 = {
    Text = "Gli altri mostri devono essere andati altrove... Questo dovrebbe essere il responsabile del suono della campana."
  },
  AvgDialog_22132_Content_43 = {
    Text = "Credi che ci sia un modo per ingannarlo?"
  },
  AvgDialog_22132_Content_44 = {
    Text = "Certo, dovrebbe essere possibile... Come recita il poema, l'inviato della scultura consegnerà una lettera al campanaro, segnalando l'avvento della mezzanotte."
  },
  AvgDialog_22132_Content_45 = {
    Text = "Bene... Horla, tu fai da inviato e ingannalo affinché suoni la campana. Io lo eliminerò prima che possa reagire."
  },
  AvgDialog_22132_Content_46 = {
    Text = "Eh? Io... devo... mentire a uno sconosciuto...?"
  },
  AvgDialog_22132_Content_47 = {
    Text = "Ehm... lascia stare, vado io... Tu resta qui, e se fanno qualche mossa improvvisa, aiutami a sottometterli."
  },
  AvgDialog_22132_Content_48 = {Text = "Certo."},
  AvgDialog_22132_Content_49 = {
    Text = "Ti sistemi gli abiti e fai un passo avanti."
  },
  AvgDialog_22132_Content_5 = {
    Text = "La maggior parte di loro, sì... Ma uno è ancora nella serra..."
  },
  AvgDialog_22132_Content_50 = {Text = "Chi?"},
  AvgDialog_22132_Content_51 = {
    Text = "Sono l'emissario di Lady Colette."
  },
  AvgDialog_22132_Content_52 = {
    Text = "Ah... Dunque siete l'emissario..."
  },
  AvgDialog_22132_Content_53 = {
    Text = "Sono qui per consegnare un messaggio. La mezzanotte si avvicina."
  },
  AvgDialog_22132_Content_54 = {
    Text = "Consegni al campanaro la lettera che Colette aveva scritto a Herbert. Lui la accetta con rispetto."
  },
  AvgDialog_22132_Content_55 = {
    Text = "Ma... Vostra Eccellenza, inviato, gli attuali segni celesti indicano che non è ancora mezzanotte..."
  },
  AvgDialog_22132_Content_56 = {
    Text = "C'è stato un errore nell'osservazione celeste odierna."
  },
  AvgDialog_22132_Content_57 = {
    Text = "Come osate mettere in discussione la decisione di Lady Colette?"
  },
  AvgDialog_22132_Content_58 = {
    Text = "Capito...! Me ne occupo subito!"
  },
  AvgDialog_22132_Content_59 = {
    Text = "Il campanaro preme un pulsante. Gli intricati ingranaggi cominciano a girare, e il martello cade, colpendo l'enorme campana."
  },
  AvgDialog_22132_Content_6 = {
    Text = "Che pena... Due fanciulli, proprio quando la vita cominciava a migliorare."
  },
  AvgDialog_22132_Content_60 = {
    Text = "Clang— Clang— Clang—"
  },
  AvgDialog_22132_Content_61 = {
    Text = "Il martello cade ripetutamente mentre i dodici rintocchi della mezzanotte echeggiano per tutta la Cité."
  },
  AvgDialog_22132_Content_62 = {
    Text = "Emissario, la campana di mezzanotte ha suonato."
  },
  AvgDialog_22132_Content_63 = {
    Text = "Bene... Ora possiamo partecipare alla celebrazione di Lady Colette."
  },
  AvgDialog_22132_Content_64 = {
    Text = "Ah, grande Lady Colette, è mia fortuna suonare la campana per la vostra celebrazione. Vedere la vostra calligrafia è per me..."
  },
  AvgDialog_22132_Content_65 = {
    Text = "mia...? \"Caro Signor Herbert — Colette\"..."
  },
  AvgDialog_22132_Content_66 = {
    Text = "Questo non è un ordine di suonare la campana... Voi...!"
  },
  AvgDialog_22132_Content_67 = {
    Text = "Prima che potesse finire, diverse righe di testo fluttuarono nella sua mente, e le sue palpebre si abbassarono."
  },
  AvgDialog_22132_Content_68 = {
    Text = "Dopo aver oscillato due volte nell'aria, il corpo pesante si schianta al suolo."
  },
  AvgDialog_22132_Content_69 = {
    Text = "Horla sbircia da dietro il muro e ti fa un cenno con la mano."
  },
  AvgDialog_22132_Content_7 = {
    Text = "Colette, Colette... non essere troppo triste."
  },
  AvgDialog_22132_Content_70 = {
    Text = "Sembra che non potrà partecipare alla celebrazione. Andiamo."
  },
  AvgDialog_22132_Content_71 = {
    Text = "Clang— Clang— Clang—"
  },
  AvgDialog_22132_Content_72 = {
    Text = "I dodici rintocchi risuonano limpidi e lontani, annunciando l'avvento della mezzanotte."
  },
  AvgDialog_22132_Content_73 = {
    Text = "La gente uscì dalle proprie case e si radunò per le strade della Cité, come un fiume nero, fluendo lentamente verso la piazza antistante il Giardino di Colette."
  },
  AvgDialog_22132_Content_74 = {
    Text = "Il giorno è finalmente arrivato! Sto per incontrare Lady Colette!"
  },
  AvgDialog_22132_Content_75 = {
    Text = "Ah, Madame Colette, l'unica poetessa e la fede di tutta la Cité..."
  },
  AvgDialog_22132_Content_76 = {
    Text = "Ho sentito dire che questa cerimonia sarà la più grandiosa di sempre. Se solo potessi stare sotto il palco e stringerle la mano..."
  },
  AvgDialog_22132_Content_77 = {
    Text = "Continua a sognare. Così tante persone vogliono incontrare Madame Colette. Cosa ti fa pensare di poter passare davanti a tutti?"
  },
  AvgDialog_22132_Content_78 = {
    Text = "Pensarci e basta... non è contro la legge, no?"
  },
  AvgDialog_22132_Content_79 = {
    Text = "Fidati, non pensarci troppo. Rilassati e guarda con me da fuori."
  },
  AvgDialog_22132_Content_8 = {
    Text = "Il fuoco divampò in un istante. Forse fu per l'alta temperatura, un mozzicone di sigaretta di un vecchio, o qualcos'altro."
  },
  AvgDialog_22132_Content_80 = {
    Text = "Intravedere Lady Colette da lontano e sentirla parlare mi basta."
  },
  AvgDialog_22132_Content_81 = {
    Text = "La porta si apre dolcemente. Sbirci con cautela all'interno."
  },
  AvgDialog_22132_Content_82 = {
    Text = "Entra. La campana ha suonato, e tutti sono andati in piazza."
  },
  AvgDialog_22132_Content_83 = {
    Text = "Horla, è questo il posto?"
  },
  AvgDialog_22132_Content_84 = {
    Text = "Horla non rispose subito. Si guardò intorno nella stanza, gli occhi lucidi."
  },
  AvgDialog_22132_Content_85 = {Text = "Horla?"},
  AvgDialog_22132_Content_86 = {
    Text = "È esattamente uguale a quando eravamo bambine..."
  },
  AvgDialog_22132_Content_87 = {
    Text = "Anche possedendo così tanto, anche avendo tutta la Cité... questo posto è sempre stato il luogo in cui riposano i sogni di Colette."
  },
  AvgDialog_22132_Content_88 = {
    Text = "Le emozioni di Horla si propagarono ancora una volta, e sentisti il tuo cuore venire toccato."
  },
  AvgDialog_22132_Content_89 = {Text = "Horla..."},
  AvgDialog_22132_Content_9 = {
    Text = "Le fiamme si levarono nel giardino colmo d'erba secca, inghiottendo la serra. Prima che la gente potesse reagire, si erano già placate."
  },
  AvgDialog_22132_Content_90 = {
    Text = "Ah! Mi perdoni, {Male=Signor,Female=Signora} Custode... faccio sempre fatica a controllare le mie emozioni..."
  },
  AvgDialog_22132_Content_91 = {
    Text = "Non preoccuparti, è perfettamente normale."
  },
  AvgDialog_22132_Content_92 = {
    Text = "Nessuno dovrebbe abbandonare il proprio passato."
  },
  AvgDialog_22132_Content_93 = {
    Text = "Grazie... {Male=Signor,Female=Signora} Custode..."
  },
  AvgDialog_22132_Content_94 = {
    Text = "Ne abbiamo parlato in passato. Colette disse che una volta acquistata questa casa, avrebbe riposto tutti i suoi oggetti preziosi in una vetrina speciale, perché tutti gli ospiti potessero ammirarli."
  },
  AvgDialog_22132_Content_95 = {
    Text = "Gioielli, borse, abiti raffinati... e una raccolta di poesie firmata con il suo nome."
  },
  AvgDialog_22132_Content_96 = {
    Text = "Guidata da Horla, arrivi davanti a una vetrina di vetro finemente lavorata."
  },
  AvgDialog_22132_Content_97 = {
    Text = "Sul ripiano centrale della vetrina, il grosso e sontuoso libro di poesie giaceva silenzioso, come un monarca addormentato in un palazzo."
  },
  AvgDialog_22132_Content_98 = {
    Text = "\"La Dimora delle Rose,\" scritto da Colette..."
  },
  AvgDialog_22132_Content_99 = {
    Text = "A quei tempi, questa raccolta di poesie era solo qualche foglio spillato insieme... Ora appare ben diversa."
  },
  AvgDialog_22133_Content_1 = {
    Text = "Retorica della Statua"
  },
  AvgDialog_22133_Content_10 = {
    Text = "Aiutate la Sig.ra Colette! Catturate l'intruso! Presto, cercate!"
  },
  AvgDialog_22133_Content_11 = {
    Text = "Un gruppo di Mostri dalle forme più disparate irrompe nell'edificio, passando non lontano da voi."
  },
  AvgDialog_22133_Content_12 = {
    Text = "I Mostri dal Mondo di Poesia hanno invaso il mondo reale..."
  },
  AvgDialog_22133_Content_13 = {
    Text = "La loro cerimonia sta per avere inizio. Dobbiamo sbrigarci."
  },
  AvgDialog_22133_Content_14 = {
    Text = "Sbirciando fuori, vedi che il Mostro è andato altrove. Afferri Horla e corri rapidamente al piano superiore."
  },
  AvgDialog_22133_Content_15 = {
    Text = "Horla, saliamo le scale e troviamo... eh?"
  },
  AvgDialog_22133_Content_16 = {
    Text = "Sali le scale, solo per scoprire che non conducono al piano superiore e si interrompono bruscamente a metà."
  },
  AvgDialog_22133_Content_17 = {
    Text = "Questo... Cosa sta succedendo..."
  },
  AvgDialog_22133_Content_18 = {
    Text = "Una volta scrissi un Poema su una scala che si spezza a metà, proprio come le nostre vite colme di svolte inattese e avversità."
  },
  AvgDialog_22133_Content_19 = {
    Text = "Ma questo chiaramente non è il mondo del mio Poema, com'è possibile che..."
  },
  AvgDialog_22133_Content_2 = {
    Text = "{Male=Signore,Female=Signora} Custode, il mondo poetico... è scomparso?"
  },
  AvgDialog_22133_Content_20 = {
    Text = "Ah! Capisco!"
  },
  AvgDialog_22133_Content_21 = {
    Text = "Horla alza improvvisamente la testa, troppo eccitata per trattenersi dal saltare."
  },
  AvgDialog_22133_Content_22 = {
    Text = "È Colette! Questo luogo è importante per noi... Lo ha preservato appositamente e lo ha rimodellato secondo la descrizione nel Poema!"
  },
  AvgDialog_22133_Content_23 = {
    Text = "Lo sapevo, Custode! Colette non è quel tipo di persona!"
  },
  AvgDialog_22133_Content_24 = {
    Text = "È la prima volta che vedi Horla così felice. Espiri profondamente."
  },
  AvgDialog_22133_Content_25 = {
    Text = "Non volendo infrangere la sua Illusione, le dai una leggera pacca sulla spalla."
  },
  AvgDialog_22133_Content_26 = {
    Text = "Forse... Conosci bene questo posto. Che ne dici di guidarci tu?"
  },
  AvgDialog_22133_Content_27 = {Text = "Certo."},
  AvgDialog_22133_Content_28 = {
    Text = "Guidati da Horla, eludete la ricerca dei Mostri e continuate ad avanzare."
  },
  AvgDialog_22133_Content_29 = {
    Text = "{Male=Signor,Female=Signora} Custode, più avanti c'è..."
  },
  AvgDialog_22133_Content_3 = {
    Text = "Guarda di nuovo fuori."
  },
  AvgDialog_22133_Content_30 = {Text = "Shh!"},
  AvgDialog_22133_Content_31 = {
    Text = "Copri rapidamente la bocca di Horla e la trascini nell'angolo del muro."
  },
  AvgDialog_22133_Content_32 = {
    Text = "Cosa dovremmo fare qui?"
  },
  AvgDialog_22133_Content_33 = {
    Text = "Sciocco! Lady Colette ci ha ordinato di sorvegliare questo posto perché... perché..."
  },
  AvgDialog_22133_Content_34 = {
    Text = "...Insomma, Lady Colette ci ha ordinato di montare la guardia qui!"
  },
  AvgDialog_22133_Content_35 = {
    Text = "Siamo di vedetta da così tanto tempo e non abbiamo visto nulla. Non ci perderemo la cerimonia?"
  },
  AvgDialog_22133_Content_36 = {
    Text = "No, la campana non ha ancora suonato. Non possiamo andare da nessuna parte finché non suona!"
  },
  AvgDialog_22133_Content_37 = {
    Text = "Non vedo l'ora di assistere alla creazione dal vivo di Madame Colette..."
  },
  AvgDialog_22133_Content_38 = {
    Text = "L'esibizione dal vivo di Madame Colette avviene solo una volta l'anno. Preparatevi, soldati. Dovremo contenderci i posti con tutta la Cité!"
  },
  AvgDialog_22133_Content_39 = {
    Text = "Perché non andiamo adesso?"
  },
  AvgDialog_22133_Content_4 = {
    Text = "Horla guarda fuori dalla porta."
  },
  AvgDialog_22133_Content_40 = {
    Text = "...perché dobbiamo restare qui."
  },
  AvgDialog_22133_Content_41 = {
    Text = "Quindi... cosa stiamo facendo esattamente qui?"
  },
  AvgDialog_22133_Content_42 = {
    Text = "Sciocco! Madame Colette ci ha ordinato di sorvegliare questo posto!"
  },
  AvgDialog_22133_Content_43 = {
    Text = "Quei due non sembrano molto svegli..."
  },
  AvgDialog_22133_Content_44 = {
    Text = "Non c'è altra via, Horla. Preparati a eliminarli."
  },
  AvgDialog_22133_Content_45 = {
    Text = "Horla ti fa un cenno col capo. Tu stringi la chiave d'argento, e Horla tira fuori carta e penna."
  },
  AvgDialog_22133_Content_46 = {Text = "Ah!!—"},
  AvgDialog_22133_Content_47 = {
    Text = "Accompagnata da una luce argentea, una scrittura elegante appare nell'aria, inscrivendosi nei mostri. I due mostri sprofondano in un sonno profondo."
  },
  AvgDialog_22133_Content_48 = {
    Text = "Dopo aver sconfitto i mostri, vi siete nascosti nella stanza dietro di loro."
  },
  AvgDialog_22133_Content_49 = {
    Text = "Sembra un magazzino... Per ora dovremmo essere al sicuro qui."
  },
  AvgDialog_22133_Content_5 = {
    Text = "Il giardino esterno conserva ancora l'aspetto del mondo descritto nella poesia, ma l'interno è identico al mondo reale, senza alcuna traccia del Dominio."
  },
  AvgDialog_22133_Content_50 = {
    Text = "Possiamo riposare qui e poi cercare Colette... Horla? Non hai un bell'aspetto."
  },
  AvgDialog_22133_Content_51 = {
    Text = "Ah... Davvero?"
  },
  AvgDialog_22133_Content_52 = {
    Text = "Stavi aggrottando la fronte poco fa, pensando a qualcosa?"
  },
  AvgDialog_22133_Content_53 = {
    Text = "Oh... {Male=Signore,Female=Signora} Custode, stavo riflettendo sulla conversazione tra quei due mostri di prima..."
  },
  AvgDialog_22133_Content_54 = {
    Text = "Quando origliavo poco fa, mi sembrava tutto così familiare... Solo adesso finalmente ho ricordato."
  },
  AvgDialog_22133_Content_55 = {
    Text = "In quella raccolta di poesie, ho scritto un poema sulla statua nella Città dei Poemi."
  },
  AvgDialog_22133_Content_56 = {
    Text = "La Città della Poesia è una città-stato che si nutre di poesia. Non ha re; la loro fede risiede in una statua."
  },
  AvgDialog_22133_Content_57 = {
    Text = "Ogni anno, nel giorno della festa, quando la torre dell'orologio rintocca, la statua prende vita e scrive un poema per il popolo della città."
  },
  AvgDialog_22133_Content_58 = {
    Text = "La sua poesia è così bella da poter sostenere l'intera città per un anno intero."
  },
  AvgDialog_22133_Content_59 = {
    Text = "Ogni anno, nel giorno della festa, la gente si raduna nella piazza dove sorge la statua per ascoltare i poemi che essa crea dal vivo..."
  },
  AvgDialog_22133_Content_6 = {
    Text = "Questa dovrebbe essere la vera Cité. Sembra che abbiamo attraversato un punto di Legame tra la realtà e il Dominio."
  },
  AvgDialog_22133_Content_60 = {
    Text = "Capisco. Colette ha alterato l'immagine della statua trasformandola nella propria..."
  },
  AvgDialog_22133_Content_61 = {
    Text = "Dov'è la torre dell'orologio?"
  },
  AvgDialog_22133_Content_62 = {
    Text = "Quando scrivevo poesie, non avevo idea di come fosse il mondo esterno... Così quella torre dell'orologio fu modellata su quella accanto a questo edificio."
  },
  AvgDialog_22133_Content_63 = {
    Text = "I due edifici sono collegati, e si può passare dall'uno all'altro attraverso un ponte coperto."
  },
  AvgDialog_22133_Content_64 = {
    Text = "...Horla, riesci a indovinare dove Colette ha nascosto il poema?"
  },
  AvgDialog_22133_Content_65 = {
    Text = "Dovrebbe... andare bene... giusto...?"
  },
  AvgDialog_22133_Content_66 = {
    Text = "In questo edificio c'è una stanza estremamente lussuosa, appartenente alla Contessa. Vi soggiorna una o due volte l'anno, mentre l'ancella la pulisce regolarmente in sua assenza."
  },
  AvgDialog_22133_Content_67 = {
    Text = "Colette adorava quella stanza e una volta mi ci fece entrare di nascosto per vederla. Disse che, una volta guadagnato abbastanza denaro, avrebbe sicuramente vissuto in quella stanza."
  },
  AvgDialog_22133_Content_68 = {
    Text = "Credo che sia lei che la raccolta di poesie si troveranno lì."
  },
  AvgDialog_22133_Content_69 = {
    Text = "Capisco... Ho una soluzione!"
  },
  AvgDialog_22133_Content_7 = {
    Text = "Ovunque sia, dobbiamo trovare Colette e recuperare il Poema..."
  },
  AvgDialog_22133_Content_70 = {
    Text = "Stai andando nella stanza di Colette a prendere il poema? Ma ci sono molti mostri qui..."
  },
  AvgDialog_22133_Content_71 = {
    Text = "Sì, ci sono molti mostri qui; probabilmente non riusciremo a gestirli."
  },
  AvgDialog_22133_Content_72 = {
    Text = "Quindi, prima li distrarremo, poi andremo nella sua stanza a prendere il poema."
  },
  AvgDialog_22133_Content_73 = {
    Text = "Ma ora sono così in allerta... cosa possiamo usare per distrarli?"
  },
  AvgDialog_22133_Content_74 = {
    Text = "Usa la torre dell'orologio."
  },
  AvgDialog_22133_Content_75 = {
    Text = "La torre dell'orologio? ... Ah! Ho capito!"
  },
  AvgDialog_22133_Content_76 = {
    Text = "Suoniamo la campana della torre dell'orologio in anticipo. Così i mostri si raduneranno nella piazza e nessuno ci fermerà!"
  },
  AvgDialog_22133_Content_77 = {
    Text = "Esatto. Colette deve fare preparazione per la sua esibizione. Non porterà con sé una raccolta di poesie così voluminosa; probabilmente sarà custodita in un luogo sicuro nella sua stanza."
  },
  AvgDialog_22133_Content_78 = {
    Text = "Approfittate di questo intervallo per andare nella sua stanza e distruggere quella raccolta di poesie!"
  },
  AvgDialog_22133_Content_8 = {
    Text = "Toc toc toc—"
  },
  AvgDialog_22133_Content_9 = {
    Text = "Il pavimento trema violentemente. Afferri in fretta Horla e ti nascondi dietro una Porta."
  },
  AvgDialog_22145_Content_1 = {
    Text = "Per favore... Non ne valgo la pena..."
  },
  AvgDialog_22145_Content_2 = {
    Text = "Aigis, posso aiutare! Possiamo stabilizzare lo spirito!"
  },
  AvgDialog_22145_Content_3 = {
    Text = "Per dimostrare le tue ragioni, estrai la Chiave d'Argento da sotto il mantello — brilla di una luce calda, come rugiada, come sole."
  },
  AvgDialog_22145_Content_4 = {
    Text = "La chiave... Il signor Anderson disse qualcosa a riguardo..."
  },
  AvgDialog_22145_Content_5 = {
    Text = "<LightGray:Ma è troppo tardi... davvero troppo tardi...>"
  },
  AvgDialog_22145_Content_6 = {
    Text = "Sta correndo verso la torre dell'orologio! Fermatela!"
  },
  AvgDialog_22297_Content_1 = {
    Text = "Occhi Aperti"
  },
  AvgDialog_22297_Content_10 = {Text = "Ospite?"},
  AvgDialog_22297_Content_100 = {
    Text = "Dense volute di fumo si levavano dalla poppa — dove si trovava la sala macchine."
  },
  AvgDialog_22297_Content_101 = {Text = "Oh no!"},
  AvgDialog_22297_Content_102 = {
    Text = "Ti reggi alla ringhiera della nave e cammini verso il fumo che si alza."
  },
  AvgDialog_22297_Content_103 = {
    Text = "L'odore di sangue e polvere da sparo mi riempie la gola, e ogni respiro mentre cammino porta un dolore lancinante."
  },
  AvgDialog_22297_Content_104 = {
    Text = "Ramona, Murphy, Celeste... Dobbiamo raggiungerli in fretta."
  },
  AvgDialog_22297_Content_105 = {
    Text = "Non avevamo fatto nemmeno due passi che un violento tremore, quasi da squarciare la nave, è salito da sotto i nostri piedi."
  },
  AvgDialog_22297_Content_106 = {
    Text = "Nell'immane esplosione, le fiamme ruggirono verso il cielo, e l'aria rovente ti scaraventò sul ponte."
  },
  AvgDialog_22297_Content_107 = {
    Text = "—L'ultima cosa che vidi prima di perdere conoscenza fu un uccello marino che planava nel cielo notturno, immerso nella luce della luna piena."
  },
  AvgDialog_22297_Content_11 = {
    Text = "Come hai dormito?"
  },
  AvgDialog_22297_Content_12 = {Text = "Doll?!"},
  AvgDialog_22297_Content_13 = {
    Text = "Niente panico. Non è il momento di farti una ramanzina per aver dormito sul prato durante l'orario di lavoro."
  },
  AvgDialog_22297_Content_14 = {
    Text = "<Gray:Quindi mi farai una ramanzina dopo...>"
  },
  AvgDialog_22297_Content_15 = {
    Text = "Ramona evitò il tuo sguardo, la sua schiena che praticamente urlava \"arrangiati da solo.\""
  },
  AvgDialog_22297_Content_16 = {
    Text = "Il Diario di Francis menzionava alcune informazioni sulla <Yellow:\"Chiesa Portaluce\">—a proposito, non hai ancora ripassato quelle tre lezioni obbligatorie."
  },
  AvgDialog_22297_Content_17 = {
    Text = "La Chiesa Portaluce, credendo che \"la Dissoluzione sia una benedizione divina e l'unica salvezza dell'Umanità,\" inganna i malati affinché si uniscano e contraggano la Dissoluzione."
  },
  AvgDialog_22297_Content_18 = {
    Text = [[
Grazie per il riepilogo, Professor Dexter.
Ma dubito che Erica apprezzi che tu le pesti i piedi.]]
  },
  AvgDialog_22297_Content_19 = {
    Text = "Colpa mia, colpa mia. A te la parola."
  },
  AvgDialog_22297_Content_2 = {
    Text = "Perché dormi qui?"
  },
  AvgDialog_22297_Content_20 = {
    Text = "Francis ha lasciato numerosi indizi che conducono alla Chiesa dei Portatori di Luce, in particolare alla loro \"resurrezione dei morti\"."
  },
  AvgDialog_22297_Content_21 = {
    Text = "Con la comparsa di Lily, abbiamo motivo di sospettare che abbiano padroneggiato l'arte di evocare i Risvegliati."
  },
  AvgDialog_22297_Content_22 = {
    Text = "Gli Awakener non dovrebbero essere top secret?"
  },
  AvgDialog_22297_Content_23 = {
    Text = [[
A quanto pare non hai prestato attenzione nemmeno a storia dei Risvegliati.
Comincio a chiedermi come tu abbia superato i test iniziali.]]
  },
  AvgDialog_22297_Content_24 = {
    Text = "Mythag non è l'unica a possedere la Tecnologia di Risveglio a Nucleo d'Argento o qualcosa di simile."
  },
  AvgDialog_22297_Content_25 = {
    Text = "L'origine del Risvegliatore può essere fatta risalire a prima del periodo Pluviale. I murali rinvenuti nelle tombe della XIX Dinastia dell'antico Remouahe sembrano raffigurare l'evocazione del Risvegliatore."
  },
  AvgDialog_22297_Content_26 = {
    Text = "La tecnologia \"Golem\" più vicina ai Risvegliati di Mythag proviene dai clan di stregoni del Levante."
  },
  AvgDialog_22297_Content_27 = {
    Text = "Ora torniamo in argomento."
  },
  AvgDialog_22297_Content_28 = {
    Text = "Dalle descrizioni di fede e riti nel diario, Francis ha incontrato una <Yellow:Chiesa Portaluce> diversa dalle informazioni in nostro possesso."
  },
  AvgDialog_22297_Content_29 = {
    Text = "Il tuo prossimo incarico sul campo è verificare il contenuto del diario."
  },
  AvgDialog_22297_Content_3 = {
    Text = "Svegliati. Ti prenderai un raffreddore qui fuori."
  },
  AvgDialog_22297_Content_30 = {
    Text = "Francis ha documentato i suoi spostamenti prima di dirigersi verso la regione polare.\nAndremo al suo punto d'imbarco — Bridgeport. Potrebbero esserci indizi laggiù."
  },
  AvgDialog_22297_Content_31 = {
    Text = "Quando sarete pronta, partiremo. Sarò il vostro compagno, come sempre."
  },
  AvgDialog_22297_Content_32 = {
    Text = "Il mio equipaggiamento è sempre pronto."
  },
  AvgDialog_22297_Content_33 = {
    Text = "Non ti serve un altro pisolino?"
  },
  AvgDialog_22297_Content_34 = {
    Text = "Non c'è bisogno!"
  },
  AvgDialog_22297_Content_35 = {
    Text = "Allora muoviamoci."
  },
  AvgDialog_22297_Content_36 = {
    Text = "Vado a prendere il conducente. Ci vediamo al cancello della scuola."
  },
  AvgDialog_22297_Content_37 = {
    Text = "La figura di Ramona svanì dalla vista, e tu ti voltasti per tornare al dormitorio a prendere l'equipaggiamento."
  },
  AvgDialog_22297_Content_38 = {Text = "Custode."},
  AvgDialog_22297_Content_39 = {
    Text = "Questa missione potrebbe portare a un contatto diretto con la Chiesa del Portatore di Luce."
  },
  AvgDialog_22297_Content_4 = {
    Text = "Ugh... Ramona?"
  },
  AvgDialog_22297_Content_40 = {
    Text = "Scoprire i loro segreti nascosti è secondario. Il tuo compito principale è restare in vita.\nNon saprei dove andare a scovare un altro Custode tra le rovine."
  },
  AvgDialog_22297_Content_41 = {
    Text = "Non essere così duro con i ragazzi."
  },
  AvgDialog_22297_Content_42 = {
    Text = "Ma Doll ha ragione.\nI cultisti che hai incontrato finora sono solo membri periferici. Il vero nucleo del culto non è ancora emerso."
  },
  AvgDialog_22297_Content_43 = {
    Text = "Sembra che ne sappia parecchio su di loro, Professore?"
  },
  AvgDialog_22297_Content_44 = {
    Text = "Ha, haha... solo un vecchio coinvolgimento."
  },
  AvgDialog_22297_Content_45 = {
    Text = "Se necessario, Mythag invierà investigatori esperti o chiederà persino aiuto al Comitato del trattato di Mystia per gestire la situazione."
  },
  AvgDialog_22297_Content_46 = {
    Text = "Mi raccomando, tornate vivi."
  },
  AvgDialog_22297_Content_47 = {
    Text = "Ricevuto. Torneremo sani e salvi."
  },
  AvgDialog_22297_Content_48 = {Text = "..."},
  AvgDialog_22297_Content_49 = {
    Text = "Che fissi? Se ne sono già andati."
  },
  AvgDialog_22297_Content_5 = {
    Text = "Per quanto tempo sono rimasto svenuto?"
  },
  AvgDialog_22297_Content_50 = {
    Text = "Non preoccuparti. Sanno quello che fanno."
  },
  AvgDialog_22297_Content_51 = {
    Text = [[
Non ho preoccupazioni.
Anche se dovessimo addestrare un nuovo Custode, i fondi verranno dal conto in banca della famiglia Dexter.]]
  },
  AvgDialog_22297_Content_52 = {
    Text = "Preoccupati per te. Ho sentito che la figlia di qualcuno ha un appuntamento galante all'opera."
  },
  AvgDialog_22297_Content_53 = {
    Text = "Ragazzo mio..."
  },
  AvgDialog_22297_Content_54 = {
    Text = "Quella notte"
  },
  AvgDialog_22297_Content_55 = {
    Text = "Una nave di linea per la regione polare? Siete fuori di testa! Non esiste una nave del genere qui, e nemmeno chiese!"
  },
  AvgDialog_22297_Content_56 = {
    Text = "Smettetela di chiedere. Siamo solo semplici pescatori. Non sappiamo niente!"
  },
  AvgDialog_22297_Content_57 = {
    Text = "Signora, la prego, aspetti—"
  },
  AvgDialog_22297_Content_58 = {
    Text = "Voi pezzi grossi di città venite a vessare noi gente di campagna!"
  },
  AvgDialog_22297_Content_59 = {
    Text = "Non è nostra intenzione—ehi!"
  },
  AvgDialog_22297_Content_6 = {
    Text = "Chi lo sa? Ti sei persino perso il briefing pre-missione di questo pomeriggio."
  },
  AvgDialog_22297_Content_60 = {
    Text = "La donna sbatté la porta. Se Ramona non ti avesse tirato indietro, saresti tornato a scuola con il naso storto."
  },
  AvgDialog_22297_Content_61 = {
    Text = "Bridgeport... questa città è strana."
  },
  AvgDialog_22297_Content_62 = {
    Text = "È la terza porta a cui bussiamo, e nessuno è disposto a condividere il minimo frammento di informazione su questo posto."
  },
  AvgDialog_22297_Content_63 = {
    Text = "Stiamo solo chiedendo indicazioni. È innaturale il modo in cui stanno tutti nascondendo qualcosa."
  },
  AvgDialog_22297_Content_64 = {
    Text = "Controlliamo i moli. Forse troveremo una pista laggiù."
  },
  AvgDialog_22297_Content_65 = {Text = "..."},
  AvgDialog_22297_Content_66 = {
    Text = "Che succede?"
  },
  AvgDialog_22297_Content_67 = {
    Text = "Forse è solo la mia immaginazione, ma mi è parso di sentire delle voci nel vento."
  },
  AvgDialog_22297_Content_68 = {Text = "..."},
  AvgDialog_22297_Content_69 = {
    Text = [[
Ehi, che tempismo perfetto. Due forestieri appena entrati.
Li prendiamo? Ci risparmia la fatica di cercarne altri.]]
  },
  AvgDialog_22297_Content_7 = {Text = "Briefing?"},
  AvgDialog_22297_Content_70 = {
    Text = "Spingeteli verso la nave."
  },
  AvgDialog_22297_Content_71 = {
    Text = "Tch, bastardo subdolo."
  },
  AvgDialog_22297_Content_72 = {
    Text = "Vai, Caecus. È il tuo momento di brillare."
  },
  AvgDialog_22297_Content_73 = {
    Text = "Ai vostri ordini, Lord Golia."
  },
  AvgDialog_22297_Content_74 = {
    Text = "Conto alla rovescia: tre ore"
  },
  AvgDialog_22297_Content_75 = {
    Text = "Aspetta! Non chiudere ancora la porta!"
  },
  AvgDialog_22297_Content_76 = {
    Text = "La ragazza ha ignorato le tue parole e ha sbattuto la porta.\nIl tentacolo del mostro, rimasto incastrato nella porta, è stato reciso e ha sussultato alcune volte prima di restare immobile."
  },
  AvgDialog_22297_Content_77 = {
    Text = "La mia compagna è ancora fuori!"
  },
  AvgDialog_22297_Content_78 = {
    Text = "Eh?! C'è qualcun altro sulla nave?"
  },
  AvgDialog_22297_Content_79 = {
    Text = "Circondati da così tanti mostri, nemmeno una divinità potrebbe scappare.\nSmetti di pensare a quella persona. Ti porterò dal capitano per vedere come farti scendere dalla nave."
  },
  AvgDialog_22297_Content_8 = {
    Text = "Riguarda Francis—"
  },
  AvgDialog_22297_Content_80 = {
    Text = "Lei è forte. Starà bene."
  },
  AvgDialog_22297_Content_81 = {
    Text = "Sì, sì, ce la farà. Ti porterò da lei dopo l'incontro con il capitano."
  },
  AvgDialog_22297_Content_82 = {
    Text = "Tuttavia, non posso garantire quanto ne resterà..."
  },
  AvgDialog_22297_Content_83 = {Text = "Chi sei?"},
  AvgDialog_22297_Content_84 = {
    Text = "Questa è la mia battuta, clandestina! Il capitano ha detto che salire a bordo senza permesso è considerato un atto clandestino."
  },
  AvgDialog_22297_Content_85 = {
    Text = "Signorina, c'è un malinteso. Non avevamo alcuna intenzione di imbarcarci clandestinamente; siamo saliti sulla nave solo perché abbiamo incontrato dei mostri e non avevamo altra scelta..."
  },
  AvgDialog_22297_Content_86 = {
    Text = "Quelle parole riservale al capitano. A me non interessa."
  },
  AvgDialog_22297_Content_87 = {
    Text = "Dannazione, dannazione, dannazione! Avete rovinato tutto! Il mio intero piano è in frantumi! Devo inventarmi qualcosa..."
  },
  AvgDialog_22297_Content_88 = {
    Text = "A proposito, faresti bene a ricordarti il mio nome—"
  },
  AvgDialog_22297_Content_89 = {
    Text = "Conto alla rovescia: @2 minuti"
  },
  AvgDialog_22297_Content_9 = {
    Text = "Lascia stare. Lascia che sia l'ospite a metterti al corrente."
  },
  AvgDialog_22297_Content_90 = {
    Text = "Saliamo a bordo."
  },
  AvgDialog_22297_Content_91 = {
    Text = "Ti sei stancato di fissare?"
  },
  AvgDialog_22297_Content_92 = {
    Text = "Esatto. Se il rituale continua, chissà che tipo di mostro nascerà dal corpo di Murphy."
  },
  AvgDialog_22297_Content_93 = {
    Text = "Impostore... Muori!"
  },
  AvgDialog_22297_Content_94 = {
    Text = "%player%, dammi la mano!"
  },
  AvgDialog_22297_Content_96 = {
    Text = "Poco prima che il mantello fosse inzuppato dall'acqua di mare, una brezza familiare ha increspato la superficie."
  },
  AvgDialog_22297_Content_97 = {
    Text = "Ora ricordo... Non sono riuscito ad afferrare la sua mano e sono caduto in mare... No, aspetta... Questo è il ponte della Sonanil."
  },
  AvgDialog_22297_Content_98 = {
    Text = "Il calore onirico cedette il passo alla cruda luce lunare, il velo che avvolgeva la nave si frantumò, si dissolse e sprofondò nelle profondità."
  },
  AvgDialog_22297_Content_99 = {
    Text = "Il velo... è scomparso?!"
  },
  AvgDialog_22403_Content_1 = {
    Text = "Siamo ad Aurita? Siamo ad Aurita?"
  },
  AvgDialog_22403_Content_2 = {
    Text = "Shh, non hai visto che sono legati? Come pensi di salvarli nelle tue condizioni?"
  },
  AvgDialog_22403_Content_3 = {
    Text = "Brown, è il nostro momento di salire sul palco!"
  },
  AvgDialog_22403_Content_4 = {Text = "Squeak!"},
  AvgDialog_22403_Content_5 = {
    Text = "Jenkin e i suoi compagni animali si intrufolarono nelle ombre del set, lasciando Aurita a sbuffare furiosa mentre camminava avanti e indietro dietro la telecamera."
  },
  AvgDialog_22403_Content_6 = {
    Text = "Non avere fretta, arriverà il tuo turno.\nPiù tardi, lascia che il Maestro Casiah ti regali delle \"grandi scene\"."
  },
  AvgDialog_22403_Content_7 = {
    Text = "Davvero?! Grazie, Maestro Casiah!"
  },
  AvgDialog_22403_Content_8 = {
    Text = "Maestro? Hmm~ Così mi piace di più."
  },
  AvgDialog_22406_Content_1 = {
    Text = "Fermi! Dove state portando il mio prezioso oggetto?!"
  },
  AvgDialog_22406_Content_10 = {
    Text = "Bleah!? Saliva di topo!!"
  },
  AvgDialog_22406_Content_11 = {Text = "Squeak!"},
  AvgDialog_22406_Content_12 = {
    Text = "Diede a Houdini una bella leccata!"
  },
  AvgDialog_22406_Content_13 = {
    Text = "La battaglia è imminente. La ragazza catturata guardò il suo compagno, che le stava davanti in modo protettivo, con un'espressione imperscrutabile."
  },
  AvgDialog_22406_Content_14 = {
    Text = "—Strinse i denti e fece uscire una pustola nerastra dalla schiena!"
  },
  AvgDialog_22406_Content_2 = {
    Text = "Le ombre calano, artigli si protendono da un altro reame, e spettri demoniaci bloccano il cammino dei coraggiosi avventurieri, minacciosi e feroci."
  },
  AvgDialog_22406_Content_3 = {
    Text = "In nome del Cavaliere..."
  },
  AvgDialog_22406_Content_4 = {Text = "Ahem!!"},
  AvgDialog_22406_Content_5 = {
    Text = "Coff, coff. Giuro sul mio onore di Detective di Londinium, proteggerò tutti!\nNon vi avvicinerete oltre!"
  },
  AvgDialog_22406_Content_6 = {
    Text = "Oh—Detective G, in quanto mio avversario sconfitto, non ne hai avuto abbastanza delle sconfitte?"
  },
  AvgDialog_22406_Content_7 = {
    Text = "Allora non biasimarmi se sarò scortese!"
  },
  AvgDialog_22406_Content_8 = {
    Text = "Ranger, questo è il momento!"
  },
  AvgDialog_22406_Content_9 = {
    Text = "Il peloso ranger si mosse rapidamente nell'oscurità, arrampicandosi sulla coscia di Houdini a una velocità quasi invisibile e diede un morso feroce..."
  },
  AvgDialog_22708_Content_1 = {
    Text = "Abbiamo vinto... Abbiamo vinto!"
  },
  AvgDialog_22708_Content_10 = {
    Text = "L'assistente sollevò in alto il Ranger Notturno, proteggendo temporaneamente la splendida pelliccia del ranger."
  },
  AvgDialog_22708_Content_11 = {
    Text = "Ehi!! Cadavere, smettila di parlare! Custode! Lotan! Fate qualcosa!!"
  },
  AvgDialog_22708_Content_12 = {
    Text = "Lotan scosse la testa, e il fantasma di una creatura simile a una balena apparve dietro di lei. Proprio mentre stava per tirare tutti fuori dall'acqua, una figura luminosa si tuffò dentro."
  },
  AvgDialog_22708_Content_13 = {
    Text = "Acqua! È acqua~ Il mare preferito di Aurita!"
  },
  AvgDialog_22708_Content_14 = {
    Text = "Esprimete un desiderio, voi che ne avete bisogno! L'oceano risponderà a tutte le vostre aspettative!"
  },
  AvgDialog_22708_Content_15 = {
    Text = "Il Detective G e il Ranger Notturno si scambiarono uno sguardo e contemporaneamente spinsero la ragazza in bianco, rimasta a lungo in silenzio, verso l'Elfa dell'Oceano."
  },
  AvgDialog_22708_Content_16 = {Text = "...?!"},
  AvgDialog_22708_Content_17 = {
    Text = "Per favore, per favore portateci via da qui."
  },
  AvgDialog_22708_Content_18 = {
    Text = "Casiah, con metà del corpo già sommerso dall'acqua, curvò le labbra in un sorriso soddisfatto."
  },
  AvgDialog_22708_Content_19 = {
    Text = "Le illusioni magiche si spostano e si trasformano con un gesto della sua mano."
  },
  AvgDialog_22708_Content_2 = {
    Text = "La perfida strega fu sconfitta dagli sforzi congiunti di tutti. Crollò a terra, allungando debolmente la mano verso un pulsante."
  },
  AvgDialog_22708_Content_20 = {
    Text = "In un batter d'occhio, tutti erano fradici d'acqua."
  },
  AvgDialog_22708_Content_21 = {
    Text = "Nessuno è stato risparmiato."
  },
  AvgDialog_22708_Content_22 = {
    Text = "Dici sul serio!?"
  },
  AvgDialog_22708_Content_23 = {
    Text = "L'elfa è tornata alla libertà del mare, e tutti sono fuggiti dal laboratorio di Houdini. Non è forse questo l'esaudimento del desiderio della ragazza?"
  },
  AvgDialog_22708_Content_24 = {
    Text = "Hai ragione, ma... come può questa storia raggiungere il finale che Lily desidera?"
  },
  AvgDialog_22708_Content_25 = {
    Text = "\"La ragazza visse per sempre felice e contenta con sua madre.\""
  },
  AvgDialog_22708_Content_26 = {
    Text = "\"Tsk, questa è l'ultima volta che faccio la babysitter per te.\nNon chiedermi più favori così fastidiosi.\""
  },
  AvgDialog_22708_Content_27 = {
    Text = "Lily, agente, guardate! Cos'è quello nell'acqua laggiù?!"
  },
  AvgDialog_22708_Content_29 = {
    Text = "Una colonna vertebrale massiccia emerge dall'acqua—la grande bestia che ha dimorato nei mari profondi di Kadath sin dalla nascita del pianeta. Risponde al richiamo della vita, attraversando il velo del tempo!"
  },
  AvgDialog_22708_Content_3 = {
    Text = "Lotan vide questo, ti lanciò l'altoparlante. Si avvicinò a Casiah e le sussurrò all'orecchio."
  },
  AvgDialog_22708_Content_30 = {Text = "Lotan...?"},
  AvgDialog_22708_Content_31 = {
    Text = "Siete pronti a partire? In caso contrario, la vostra storia finirà in queste acque."
  },
  AvgDialog_22708_Content_32 = {
    Text = "Wow! Un pesce enorme!"
  },
  AvgDialog_22708_Content_33 = {
    Text = "Non abbiate fretta, uno alla volta. La schiena della signorina Lotan è piuttosto spaziosa."
  },
  AvgDialog_22708_Content_34 = {
    Text = "Puoi smetterla di rubare la scena, tu, spiritello marino mezzo cotto? È chiaro che Bru... No, il Ranger della Notte e io siamo i veri eroi qui!"
  },
  AvgDialog_22708_Content_35 = {Text = "Ehm..."},
  AvgDialog_22708_Content_36 = {
    Text = "Il pesce grande è il compagno di Aurita! Quindi Aurita deve sedersi davanti!"
  },
  AvgDialog_22708_Content_37 = {Text = "Um...!"},
  AvgDialog_22708_Content_38 = {
    Text = "Lily, Lili... Io..."
  },
  AvgDialog_22708_Content_39 = {
    Text = "Posso sedermi davanti?"
  },
  AvgDialog_22708_Content_4 = {
    Text = "Che cosa stai tramando adesso? Non rendere impossibile a tutti ripulire questo casino."
  },
  AvgDialog_22708_Content_40 = {
    Text = "Considerando che sei più piccola di me... Fai attenzione! Non ci sono sedili sulla schiena del bestione."
  },
  AvgDialog_22708_Content_41 = {
    Text = "Aurita vuole stare con i suoi compagni!"
  },
  AvgDialog_22708_Content_42 = {
    Text = "Ehi! Perché sei così scivolosa!? Se sai nuotare, non arrampicarti quassù!"
  },
  AvgDialog_22708_Content_43 = {
    Text = "Il behemoth muggisce attraverso le sue vie respiratorie, balzando fuori dall'acqua con risate e speranza."
  },
  AvgDialog_22708_Content_44 = {
    Text = "La luce dell'alba trafigge le nuvole e la foschia, drappeggiando il mare, le bestie colossali e gli avventurieri di sfumature rosse e rosa."
  },
  AvgDialog_22708_Content_45 = {
    Text = "Così, così in alto—!"
  },
  AvgDialog_22708_Content_47 = {
    Text = "Il Detective G, lo Spirito dell'Oceano e l'assistente del Ranger della Notte unirono le forze per afferrare la ragazza, impedendole di scivolare giù dalla schiena della bestia gigante."
  },
  AvgDialog_22708_Content_48 = {
    Text = "Alcune persone risero e giocarono, spruzzandosi acqua a vicenda sui vestiti."
  },
  AvgDialog_22708_Content_49 = {
    Text = "In quel momento, la ragazza coraggiosa guardò improvvisamente dritto verso di te, il volto adornato da un sorriso eccezionalmente radioso e gentile."
  },
  AvgDialog_22708_Content_5 = {
    Text = "Ops, solo un piccolo test—"
  },
  AvgDialog_22708_Content_50 = {
    Text = "Un giglio che ha mancato il suo periodo di fioritura,"
  },
  AvgDialog_22708_Content_51 = {
    Text = "Il momento della fioritura è finalmente giunto."
  },
  AvgDialog_22708_Content_6 = {
    Text = "Mentre il sorriso sul volto di Casiah si allarga lentamente, il suono di una corrente sotterranea raggiunge le orecchie di tutti."
  },
  AvgDialog_22708_Content_7 = {
    Text = "Venite, acque! Assistete al gran finale del Maestro Houdini — la fuga definitiva dalla vasca d'acqua!"
  },
  AvgDialog_22708_Content_8 = {
    Text = "Il livello dell'acqua salì rapidamente, coprendo prima i piedi dei bambini, poi i polpacci... Infine raggiunse le cosce, rendendo difficile ogni movimento."
  },
  AvgDialog_22708_Content_9 = {
    Text = "Casiah!!! Che stai facendo?! Vuoi farci annegare?!"
  },
  AvgDialog_22718_Content_124 = {
    Text = "SpChar_PietraSanga_NF"
  },
  AvgDialog_22718_Content_125 = {
    Text = "SpChar_SkullCacciatore1_NF"
  },
  AvgDialog_22718_Content_126 = {
    Text = "SpChar_SkullCacciatore2_NF"
  },
  AvgDialog_22718_Content_128 = {
    Text = "SpChar_Ricercatore_NF"
  },
  AvgDialog_22718_Content_130 = {
    Text = "SpChar_Ubriaco_NF"
  },
  AvgDialog_22718_Content_133 = {
    Text = "SpChar_Ancella_NF"
  },
  AvgDialog_22718_Content_136 = {
    Text = "SpChar_MaskUomo_NF"
  },
  AvgDialog_22718_Content_76 = {
    Text = "SpChar_Ubriaco_NF"
  },
  AvgDialog_22718_Content_77 = {
    Text = "SpChar_Ubriaco_NF"
  },
  AvgDialog_22718_Content_78 = {
    Text = "SpChar_Ubriaco_NF"
  },
  AvgDialog_22718_Content_80 = {
    Text = "SpChar_GiocatoreM_NF"
  },
  AvgDialog_22718_Content_81 = {
    Text = "SpChar_GiocatriceF_NF"
  },
  AvgDialog_22718_Content_82 = {
    Text = "SpChar_Ragazzo_NF"
  },
  AvgDialog_22718_Content_83 = {
    Text = "SpChar_Bambina_NF"
  },
  AvgDialog_23346_Content_1 = {
    Text = "Le masse nere si ritirarono come una marea, e il palco tornò alla sua placida calma."
  },
  AvgDialog_23346_Content_10 = {
    Text = "Petali di rosa rosso sangue fluttuavano e si disperdevano nell'aria, la loro fragranza intensa e putrida aleggiava nel palco oscurato."
  },
  AvgDialog_23346_Content_11 = {
    Text = "L'ombra mascherata apparve silenziosamente dietro Lady Sorel."
  },
  AvgDialog_23346_Content_12 = {
    Text = "Perdonate l'interruzione, signore e signori. Ora, godetevi—"
  },
  AvgDialog_23346_Content_14 = {Text = "..."},
  AvgDialog_23346_Content_15 = {
    Text = "Una rosa rigogliosa, baciata dalla rugiada, trafisse il petto di Sorel; le gocce di rugiada sui suoi petali brillavano di una tenue luce azzurra nell'oscurità."
  },
  AvgDialog_23346_Content_16 = {
    Text = "Cos'è quella... quella cosa..."
  },
  AvgDialog_23346_Content_17 = {
    Text = "La Figura Oscura apparve solo per un istante prima di svanire, lasciando Sorel a fissare con sgomento il sangue che le sgorgava dal petto."
  },
  AvgDialog_23346_Content_18 = {
    Text = "Ahhh!! Mia Signora, il vostro petto..."
  },
  AvgDialog_23346_Content_19 = {
    Text = "Sangue? Che schifo... Karen, puliscilo subito..."
  },
  AvgDialog_23346_Content_2 = {
    Text = "Fai un passo avanti e afferri saldamente la mano di Sorel."
  },
  AvgDialog_23346_Content_20 = {
    Text = "Non indietreggiate, Lady Sorel! Cadrete!"
  },
  AvgDialog_23346_Content_21 = {
    Text = "Lady Sorel!!"
  },
  AvgDialog_23346_Content_23 = {
    Text = "Ahhh, qualcuno è caduto dall'edificio!!"
  },
  AvgDialog_23346_Content_24 = {
    Text = "<Shake:Q-quella sembra Lady Sorel...>"
  },
  AvgDialog_23346_Content_25 = {
    Text = "Vino dorato pallido si versò dal calice, danzando nell'aria insieme a delicati petali di rosa."
  },
  AvgDialog_23346_Content_26 = {
    Text = "Aiuto... aiutatemi... mi sta divorando viva—"
  },
  AvgDialog_23346_Content_27 = {
    Text = "La musica sontuosa e stravagante aleggiava ancora per tutto il teatro dell'opera."
  },
  AvgDialog_23346_Content_28 = {
    Text = "I suoi occhi erano colmi di paura e confusione. L'istinto di sopravvivenza la spinse a protendersi verso di te, eppure nell'istante in cui le punte delle vostre dita si sfiorarono, scivolò appena oltre la tua presa."
  },
  AvgDialog_23346_Content_3 = {
    Text = "Questo posto non è sicuro, Lady Sorel. Per favore, seguitemi."
  },
  AvgDialog_23346_Content_30 = {
    Text = "Questa, una bellezza di eleganza impareggiabile, cadde infine insieme ai suoi amati abiti raffinati, al vino pregiato, ai fiori freschi e agli applausi."
  },
  AvgDialog_23346_Content_31 = {
    Text = "<Yellow:Registro della Prima Operazione nel Dominio Artificiale>\n\n■ Numero Dominio: M-B04-001\n■ Orario di Configurazione: Dopo il Diluvio 315, Giugno @1, 20:00-21:00 (Giorno della morte di Sorel).\n■ Luogo di Configurazione: Teatro Covent"
  },
  AvgDialog_23346_Content_32 = {
    Text = "■Proprietaria del Dominio: Sorel @2\n■Intrusi nel Dominio: %player%, Ramona\n\n■Obiettivo: <Yellow:Indagare sulla caduta di Sorel e @3>"
  },
  AvgDialog_23346_Content_33 = {
    Text = "■<Yellow:Risultati dell'Operazione>\n\nIdentificazione preliminare del colpevole come una <Red:Figura Oscura mascherata>.\nSorel è morta per una caduta. Il Custode si è ritirato dal Dominio Artificiale."
  },
  AvgDialog_23346_Content_34 = {
    Text = [[
Sala di Riposo Mythag
Dopo il Primo Dominio Artificiale]]
  },
  AvgDialog_23346_Content_35 = {Text = "Sveglio/a?"},
  AvgDialog_23346_Content_36 = {
    Text = "<Shake:Ugh... la testa... mi fa male...>"
  },
  AvgDialog_23346_Content_37 = {
    Text = "Frequenza cardiaca e pressione sanguigna nella norma. La fluttuazione dell'energia mentale è leggermente elevata, ma ancora entro limiti controllabili."
  },
  AvgDialog_23346_Content_38 = {
    Text = "Niente male. Sembra che dopo aver sperimentato il <Blue:Dominio Artificiale di Ramona> l'ultima volta, ti sia gradualmente adattato/a."
  },
  AvgDialog_23346_Content_39 = {
    Text = "È anche merito dei miei continui miglioramenti al Dominio. Ora possiamo persino impostare gli orari e i luoghi di inizio e fine del Dominio."
  },
  AvgDialog_23346_Content_4 = {Text = "!!"},
  AvgDialog_23346_Content_40 = {
    Text = "Naturalmente, anche i fondi di ricerca che la signorina Czort ha richiesto per nostro conto hanno avuto un ruolo... dell'1%, suppongo."
  },
  AvgDialog_23346_Content_41 = {
    Text = "Davvero solo l'1%..."
  },
  AvgDialog_23346_Content_42 = {
    Text = "E Ramona? Siamo entrati insieme..."
  },
  AvgDialog_23346_Content_43 = {
    Text = "Sta riposando nella stanza accanto. Non preoccuparti, sta come te: nessun problema serio."
  },
  AvgDialog_23346_Content_44 = {
    Text = "Hai catturato il colpevole nel Dominio di Lady Sorel?"
  },
  AvgDialog_23346_Content_45 = {
    Text = "Scuoti la testa."
  },
  AvgDialog_23346_Content_46 = {
    Text = "Ho fatto appena in tempo a percepire un odore sul colpevole, era come... <Red:l'odore di rose in decomposizione.>"
  },
  AvgDialog_23346_Content_47 = {
    Text = "Tutto ciò che aveva davanti agli occhi sembrava irreale, i suoi pensieri in continuo mutamento e sussulto."
  },
  AvgDialog_23346_Content_48 = {
    Text = "Dalla caduta nel teatro dell'opera all'omicidio nell'angolo del vicolo, dalla Folla esultante e urlante alla Cameriera intrigante…"
  },
  AvgDialog_23346_Content_49 = {
    Text = "Finché alla fine si fermarono su tre settimane fa, dove la storia ebbe inizio—"
  },
  AvgDialog_23346_Content_5 = {
    Text = "Come osate toccare la mano della Signora, e stringerla così forte..."
  },
  AvgDialog_23346_Content_6 = {
    Text = "La Cameriera mormorò, poi si avvicinò improvvisamente al tuo orecchio."
  },
  AvgDialog_23346_Content_7 = {
    Text = "<SmallShake:Ehi, avevi detto che eravamo qui solo per guardare lo spettacolo. Mi hai mentito!>"
  },
  AvgDialog_23346_Content_8 = {
    Text = "...Te lo spiegherò dopo."
  },
  AvgDialog_23346_Content_9 = {Text = "..."},
  AvgDialog_23347_Content_1 = {
    Text = "Vieni scagliato violentemente all'indietro da una forza tremenda."
  },
  AvgDialog_23347_Content_2 = {
    Text = "Il mondo si dissolve in petali, disperdendosi poco a poco, e precipiti in un mare di fiori sconfinato."
  },
  AvgDialog_23347_Content_3 = {
    Text = "AAAAAH—!!!"
  },
  AvgDialog_23347_Content_4 = {
    Text = "<Yellow:Registro dell'Operazione nel Secondo Dominio Artificiale Ⅱ>\n\n■ Numero Dominio: M-B04-002\n■ Orario di allestimento: Dopo il Diluvio 315, 11 giugno, 20:00-21:00 (Giorno della morte di Sorel).\n■ Luogo di allestimento: Teatro Covent"
  },
  AvgDialog_23347_Content_5 = {
    Text = "■Proprietario del Dominio: Sorel @2\n■Intrusi nel Dominio: %player%, Ramona\n\n■Obiettivo: <Yellow:Sulla base dei risultati della prima intrusione nel Dominio, localizzare la fonte della fluttuazione dell'Argento al primo piano.>"
  },
  AvgDialog_23347_Content_6 = {
    Text = "■<Yellow:Risultati dell'Operazione>\n\nLa comparsa di un @2 non identificato ha interrotto l'operazione. Il Custode ha perso la maggior parte dei ricordi legati all'entità.\n<Red:Il Custode è stato espulso forzatamente dal Dominio e versa in condizioni critiche.>"
  },
  AvgDialog_23348_Content_1 = {
    Text = "Attendete, voi due."
  },
  AvgDialog_23348_Content_2 = {
    Text = "Abbiamo una questione urgente con quel vecchio signore. Potreste annunciarci?"
  },
  AvgDialog_23348_Content_3 = {
    Text = "Mi dispiace, il mio padrone soffre di un grave morbo contagioso. Non è in grado di ricevere visitatori esterni."
  },
  AvgDialog_23348_Content_4 = {
    Text = "Possiamo parlargli attraverso la carrozza. Non ci avvicineremo di un solo passo."
  },
  AvgDialog_23348_Content_5 = {
    Text = "Il bruto armato fino ai denti ha completamente ignorato la vostra proposta. Questo è il mercato più affollato del Distretto Ovest — iniziare una rissa qui attirerebbe sicuramente l'attenzione di tutti."
  },
  AvgDialog_23348_Content_6 = {
    Text = "Preferiresti non attirare guai inutili."
  },
  AvgDialog_23348_Content_7 = {
    Text = "Allora seguiamoli in silenzio e vediamo da dove vengono davvero."
  },
  AvgDialog_23349_Content_1 = {
    Text = "Seguite la carrozza attraverso una svolta dopo l'altra, e prima di rendervene conto vi siete allontanati dal centro città, arrivando in una periferia desolata."
  },
  AvgDialog_23349_Content_10 = {
    Text = "Entriamo a dare un'occhiata."
  },
  AvgDialog_23349_Content_2 = {
    Text = "Una fitta nebbia avvolge ogni cosa. Davanti a voi, resta solo la sagoma nera e tremolante della carrozza."
  },
  AvgDialog_23349_Content_3 = {
    Text = "La sagoma si sfuma gradualmente, finché alla fine non è più possibile scorgerla."
  },
  AvgDialog_23349_Content_4 = {
    Text = "Che razza di posto dimenticato da Dio è questo... Londinium è avvolta nella nebbia ovunque in questi giorni, ostacolando seriamente l'efficienza della polizia e degli Investigatori."
  },
  AvgDialog_23349_Content_5 = {
    Text = "Attraverso la nebbia fitta, un antico maniero avvolto nell'oscurità appare debolmente in lontananza."
  },
  AvgDialog_23349_Content_6 = {
    Text = "Il rivestimento in pino sulla superficie del maniero si è spaccato in innumerevoli crepe, dalle quali un'aura cupa si riversa silenziosamente."
  },
  AvgDialog_23349_Content_7 = {
    Text = "Nebbia, un maniero abbandonato, una mondana morta in circostanze misteriose, un vecchio signore misterioso... Niente male, tutti gli elementi di un romanzo sono al loro posto."
  },
  AvgDialog_23349_Content_8 = {
    Text = "Pensate che quel vecchio signore possa essere là dentro?"
  },
  AvgDialog_23349_Content_9 = {
    Text = "È così desolato qui intorno che non c'è nulla a perdita d'occhio. Temo che non abbiamo altra scelta."
  },
  AvgDialog_23351_Content_1 = {
    Text = "Hai spalancato il pesante sipario."
  },
  AvgDialog_23351_Content_10 = {
    Text = "...Sei sveglio?"
  },
  AvgDialog_23351_Content_11 = {Text = "?"},
  AvgDialog_23351_Content_12 = {
    Text = "Ti volti rapidamente, ma non c'è nessuno dietro di te."
  },
  AvgDialog_23351_Content_13 = {
    Text = "Lady Sorel?"
  },
  AvgDialog_23351_Content_14 = {
    Text = "Sorel riprende rapidamente la compostezza e ti rivolge un debole sorriso."
  },
  AvgDialog_23351_Content_15 = {
    Text = "Ci conosciamo da meno di mezz'ora e mi hai già chiesto scusa tre volte."
  },
  AvgDialog_23351_Content_16 = {
    Text = "Se vuoi davvero scusarti, questo sarebbe più sincero."
  },
  AvgDialog_23351_Content_17 = {
    Text = "Sorel fa roteare il liquido dorato nel suo bicchiere."
  },
  AvgDialog_23351_Content_18 = {
    Text = "La persona che stavo aspettando non è venuta. Perché non giochi con me, invece?\nTi farò tre domande, e se non saprai rispondere..."
  },
  AvgDialog_23351_Content_19 = {
    Text = "Sorel posa delicatamente il bicchiere sul tavolo e indica con noncuranza lo champagne sul carrello di servizio lì vicino."
  },
  AvgDialog_23351_Content_2 = {
    Text = "Sei finalmente tornato, mio Cavaliere."
  },
  AvgDialog_23351_Content_20 = {
    Text = "Allora bevi un bicchiere."
  },
  AvgDialog_23351_Content_3 = {
    Text = "Sorel era seduta nell'angolo con un sorriso raggiante, splendida come sempre."
  },
  AvgDialog_23351_Content_4 = {
    Text = "Meno male che stai bene."
  },
  AvgDialog_23351_Content_5 = {
    Text = "Non avevi detto che saresti venuto a proteggermi? Ti ho aspettato per un bel po'."
  },
  AvgDialog_23351_Content_6 = {
    Text = "Il suo sorriso era spensierato, eppure il suo tono portava un accenno di solitudine appena percettibile."
  },
  AvgDialog_23351_Content_7 = {
    Text = "Mi dispiace, Lady Sorel..."
  },
  AvgDialog_23351_Content_8 = {
    Text = "<Red:Hehe.>"
  },
  AvgDialog_23351_Content_9 = {
    Text = "Sorel fissò improvvisamente lo sguardo dietro di te, gli occhi pieni di inquietudine."
  },
  AvgDialog_23352_Content_1 = {
    Text = "Nel momento in cui spingi il cancello, un fetido profumo floreale ti investe con un assalto frontale. La sala è piena di rose rosse, ma stanno appassendo giorno dopo giorno senza nessuno che se ne prenda cura."
  },
  AvgDialog_23352_Content_10 = {
    Text = "Ramona lanciò un'occhiata al cielo fuori."
  },
  AvgDialog_23352_Content_11 = {
    Text = "Per oggi basta con le indagini. Ho annotato la posizione di questa residenza. Potremo controllare i registri di proprietà quando torniamo."
  },
  AvgDialog_23352_Content_12 = {
    Text = "Mm. L'Operazione di domani sarà come le precedenti."
  },
  AvgDialog_23352_Content_13 = {
    Text = "Prima prenderemo l'invito da Karen, poi io salirò al secondo piano per proteggere Lady Sorel mentre tu farai la guardia al primo piano."
  },
  AvgDialog_23352_Content_14 = {
    Text = "Se siamo fortunati, potremmo persino riuscire a vedere quel vecchio signore della carrozza."
  },
  AvgDialog_23352_Content_2 = {
    Text = "Ugh... Lo stesso odore di quella Figura Oscura mascherata."
  },
  AvgDialog_23352_Content_3 = {
    Text = "Non c'è niente qui... Sembra che nessuno ci abiti da molto tempo."
  },
  AvgDialog_23352_Content_4 = {
    Text = "Osservi la sala buia e umida. È completamente vuota: ragnatele oscillano nel Vento negli angoli trascurati, e il pavimento è coperto di petali appassiti e foglie cadute."
  },
  AvgDialog_23352_Content_5 = {
    Text = "Oh, qui c'è un dipinto appeso."
  },
  AvgDialog_23352_Content_6 = {
    Text = "All'angolo della scala era appeso un ritratto magnificamente incorniciato, che raffigurava con pennellate morbide e sfumate una donna riccamente abbigliata."
  },
  AvgDialog_23352_Content_7 = {
    Text = "Il trucco della donna è impeccabile, eppure gli angoli dei suoi occhi sono rivolti verso il basso e le sue labbra sottili sono serrate in una linea, conferendole un aspetto profondamente cupo e inquieto."
  },
  AvgDialog_23352_Content_8 = {
    Text = "Tempera? Pochissime persone usano ancora questa tecnica."
  },
  AvgDialog_23352_Content_9 = {
    Text = "Che strano: non c'è un granello di polvere su questo dipinto, come se qualcuno lo mantenesse regolarmente."
  },
  AvgDialog_23353_Content_1 = {Text = "Uovo"},
  AvgDialog_23353_Content_10 = {
    Text = "Ramona aggrottò le sopracciglia, gli occhi colmi di preoccupazione."
  },
  AvgDialog_23353_Content_11 = {Text = "Ramona..."},
  AvgDialog_23353_Content_12 = {
    Text = "Forse potremmo entrare nel Dominio ancora una volta?\nIo farò la guardia a Lady Sorel al piano di sopra, e Ramona sorveglierà il piano di sotto."
  },
  AvgDialog_23353_Content_13 = {
    Text = "Un Dominio Artificiale non è una meta turistica che puoi visitare quando ti pare. Ciò che conta di più per te adesso è il Riposo."
  },
  AvgDialog_23353_Content_14 = {
    Text = "Ma abbiamo anche bisogno di qualche <Yellow:misura straordinaria> per far avanzare le indagini..."
  },
  AvgDialog_23353_Content_15 = {
    Text = "Pensavo che entrare nel Dominio Artificiale fosse già abbastanza radicale."
  },
  AvgDialog_23353_Content_16 = {
    Text = "Un sorriso che si poteva descrivere solo come \"astuto\" si insinuò sul volto solitamente inespressivo di Doll."
  },
  AvgDialog_23353_Content_17 = {
    Text = "Ho un piano ancora più radicale — dipende solo da quanto siete disposti a rischiare."
  },
  AvgDialog_23353_Content_18 = {
    Text = "Sentiero di Brinsburg, 23:00"
  },
  AvgDialog_23353_Content_19 = {
    Text = "Hahahaha! Che serata meravigliosa, che meraviglioso Nettare d'Annata!"
  },
  AvgDialog_23353_Content_2 = {
    Text = "E poi? Nel teatro dell'opera, oltre a quella figura oscura mascherata, hai scoperto altri indizi?"
  },
  AvgDialog_23353_Content_20 = {
    Text = "Signor Nicholas, questa sua miscela speciale invecchiata è l'eroe che mi ha salvato dalla prigione."
  },
  AvgDialog_23353_Content_21 = {
    Text = "Paragonare i Mythag a una prigione — questo fa della vostra figlia adottiva la carceriera? Hahaha..."
  },
  AvgDialog_23353_Content_22 = {
    Text = "Le guance di Dexter erano arrossate, lo sguardo annebbiato. Si portò un dito alle labbra."
  },
  AvgDialog_23353_Content_23 = {
    Text = "Shh... questa volta sono sgattaiolato fuori. Qualunque cosa facciate, non fate scoprire la cosa a Ramona."
  },
  AvgDialog_23353_Content_24 = {Text = "..."},
  AvgDialog_23353_Content_25 = {
    Text = "Vi invidio davvero, signor Dexter. Avete qualcuno che si preoccupa sinceramente per voi."
  },
  AvgDialog_23353_Content_26 = {
    Text = "E io? Non molto tempo fa, l'amore della mia vita mi ha lasciato. Le sue ossa non si erano ancora raffreddate che anche mio padre è morto!"
  },
  AvgDialog_23353_Content_27 = {
    Text = "Mentre parlava, Nicholas si accovacciò e iniziò a singhiozzare."
  },
  AvgDialog_23353_Content_28 = {
    Text = "Sorel... una volta che avrò catturato l'assassino, ti vendicherò!"
  },
  AvgDialog_23353_Content_29 = {
    Text = "<Gray:L'amore della sua vita? Interessante. Almeno tre amici mi hanno detto esattamente la stessa cosa...>"
  },
  AvgDialog_23353_Content_3 = {
    Text = "Durante la perlustrazione del primo piano, il misuratore del Nucleo d'Argento ha mostrato una breve fluttuazione nei dati, ma è scomparsa rapidamente."
  },
  AvgDialog_23353_Content_30 = {
    Text = "<Gray:Lady Sorel era davvero ammirevole, in effetti.>"
  },
  AvgDialog_23353_Content_31 = {
    Text = "Hm hm hm~ Il suo canto era colmo di vera emozione, mi ha commosso profondamente~"
  },
  AvgDialog_23353_Content_32 = {
    Text = "Nel vicolo silenzioso, il gentiluomo elegantemente vestito barcollava lungo il sentiero acciottolato, il fioco lampione allungava la sua ombra dietro di lui."
  },
  AvgDialog_23353_Content_33 = {
    Text = "<BigShake:Vivo per il piacere!>"
  },
  AvgDialog_23353_Content_34 = {
    Text = "<RedItalic:Troppe lacrime stasera, troppo incantevoli per lasciarle andare.>"
  },
  AvgDialog_23353_Content_35 = {
    Text = "<RedItalic:Che il nostro splendido Sangue impregni le vetrate colorate, risplendendo sul banchetto festoso.>"
  },
  AvgDialog_23353_Content_36 = {
    Text = "Un Canto sommesso riecheggiava per le strade deserte, mentre una Figura Oscura con una maschera scivolava dall'angolo fino a fermarsi davanti a Dexter."
  },
  AvgDialog_23353_Content_37 = {
    Text = "Buonasera, Lord Dexter."
  },
  AvgDialog_23353_Content_38 = {
    Text = [[
Ehm... l'hai cantata sbagliata.
Il verso successivo dovrebbe essere "I suoi occhi erano colmi di lacrime, inebriandomi profondamente."]]
  },
  AvgDialog_23353_Content_39 = {
    Text = "La Figura Oscura annuì con improvvisa comprensione, battendosi la testa con stizza."
  },
  AvgDialog_23353_Content_4 = {
    Text = "Quindi l'assassino è molto probabilmente uno degli ospiti del primo piano."
  },
  AvgDialog_23353_Content_40 = {
    Text = "Che orrore. Volevo mettere in scena uno spettacolo splendido prima di ucciderti, eppure ho persino sbagliato le parole."
  },
  AvgDialog_23353_Content_41 = {
    Text = "Uccidermi...?"
  },
  AvgDialog_23353_Content_42 = {
    Text = "Francamente, sembrate un gentiluomo ragionevole. Perché togliere la vita a un innocente scapolo nel cuore della notte?"
  },
  AvgDialog_23353_Content_43 = {
    Text = "La Figura Oscura allargò le mani con aria innocente."
  },
  AvgDialog_23353_Content_44 = {
    Text = "Sono solo un umile servitore, niente di più. Tutto ciò che faccio è per esaudire i desideri del mio padrone."
  },
  AvgDialog_23353_Content_45 = {
    Text = "Detto ciò, si dissolse improvvisamente come inchiostro che si disperde nella nebbia, svanendo nella vasta oscurità della notte."
  },
  AvgDialog_23353_Content_46 = {Text = "...Eh?"},
  AvgDialog_23353_Content_47 = {
    Text = "Un brivido tagliente risalì improvvisamente da dietro, seguito dal ricco e marcescente profumo di fiori — così stucchevolmente dolce da risultare quasi nauseante."
  },
  AvgDialog_23353_Content_48 = {
    Text = "Si guardi le spalle, signor Dexter."
  },
  AvgDialog_23353_Content_49 = {
    Text = "State tranquillo, non mi siete antipatico. Si potrebbe persino dire che vi ammiro."
  },
  AvgDialog_23353_Content_5 = {
    Text = "Ramona annuì."
  },
  AvgDialog_23353_Content_50 = {
    Text = "Quindi cercherò di rendere la tua morte il più confortevole possibile—"
  },
  AvgDialog_23353_Content_6 = {
    Text = "Dopo la caduta di Lady Sorel dall'edificio, la scena è stata sigillata a lungo e tutti hanno rilasciato una dichiarazione."
  },
  AvgDialog_23353_Content_7 = {
    Text = "La maggior parte degli ospiti al primo piano appartiene alla classe media e non ha alcun legame con Lady Sorel."
  },
  AvgDialog_23353_Content_8 = {
    Text = "Sembra che le indagini siano giunte a un punto morto."
  },
  AvgDialog_23353_Content_9 = {
    Text = "Non sono molti i nobili che hanno partecipato al funerale ancora in vita. Dexter è in grave pericolo in questo momento."
  },
  AvgDialog_23354_Content_1 = {
    Text = "Desiderio dell'ancella"
  },
  AvgDialog_23354_Content_10 = {
    Text = "Fuori dai piedi, datemi tre mestoli! Ho diverse figlie a casa…"
  },
  AvgDialog_23354_Content_11 = {
    Text = "Come può una piccola truffatrice avere un invito per \"Il Nome della Rosa\"?"
  },
  AvgDialog_23354_Content_12 = {
    Text = "Non è solo una piccola truffatrice: è anche l'autentica cameriera di Lady Sorel."
  },
  AvgDialog_23354_Content_13 = {
    Text = "Ti schiaristi la voce e facesti un passo avanti, tirando fuori le credenziali investigative dalla tasca."
  },
  AvgDialog_23354_Content_14 = {
    Text = "Indagine del Dipartimento di Polizia di Londinium. Tutti i presenti, per favore fatevi da parte."
  },
  AvgDialog_23354_Content_15 = {
    Text = "La polizia?!"
  },
  AvgDialog_23354_Content_16 = {
    Text = "La transazione di oggi— no, l'evento finisce qui! Karen si è appena ricordata di avere una faccenda urgente…"
  },
  AvgDialog_23354_Content_17 = {
    Text = "Intendevo tutti tranne lei, signorina Karen. Gli altri possono andare."
  },
  AvgDialog_23354_Content_18 = {
    Text = "La folla si disperse gradualmente. Karen si agitò a disagio, ma si ricompose rapidamente."
  },
  AvgDialog_23354_Content_19 = {
    Text = "I suoi occhi ti scrutarono attentamente insieme a Ramona, poi improvvisamente sfoggiò un sorriso radioso."
  },
  AvgDialog_23354_Content_2 = {
    Text = "Chiariamo subito una cosa: questa non è una comune acqua da bagno!"
  },
  AvgDialog_23354_Content_20 = {
    Text = "Ma certo, agente. Karen non va da nessuna parte."
  },
  AvgDialog_23354_Content_21 = {
    Text = "M-ma Karen è solo un'umile cameriera. Mi chiedo in cosa potrei mai esservi d'aiuto?"
  },
  AvgDialog_23354_Content_22 = {
    Text = "Tranquilla. Non ci interessa il tuo piccolo commercio. Abbiamo solo bisogno che tu..."
  },
  AvgDialog_23354_Content_23 = {
    Text = "Whoosh—!!"
  },
  AvgDialog_23354_Content_24 = {
    Text = "Un secchio d'acqua gelata si è abbattuto su di te e Ramona, inzuppandovi all'istante come pulcini bagnati."
  },
  AvgDialog_23354_Content_25 = {Text = "..."},
  AvgDialog_23354_Content_26 = {Text = "..."},
  AvgDialog_23354_Content_27 = {
    Text = "Non mentiva. C'è davvero un profumo di rosa."
  },
  AvgDialog_23354_Content_28 = {
    Text = "Hah! Bugiardi, stavate cercando di convincermi a seguirvi docilmente in prigione, eh?"
  },
  AvgDialog_23354_Content_29 = {
    Text = "<Big:Venite a prendermi, se ci riuscite!!>"
  },
  AvgDialog_23354_Content_3 = {
    Text = "Karen ha aggiunto rari sali da bagno marini dall'isola di Thira, più diciotto tipi di spezie tra cui lavanda, agrumi, chiodi di garofano e altro ancora…"
  },
  AvgDialog_23354_Content_30 = {
    Text = "Karen vi ha fatto una linguaccia, si è sollevata la gonna ed è scappata a gambe levate in un lampo."
  },
  AvgDialog_23354_Content_31 = {
    Text = "Ferma! Quando ti prendo, ti do una bella lezione!"
  },
  AvgDialog_23354_Content_4 = {
    Text = "Infine, è stata infusa a vapore con petali di rosa spediti dal sud di Constan per un giorno e una notte interi, ed è ancora meravigliosamente profumata!"
  },
  AvgDialog_23354_Content_5 = {
    Text = "Il segreto dell'eterna giovinezza di Lady Sorel si trova in questo barile di acqua da bagno deliziosamente profumata…"
  },
  AvgDialog_23354_Content_6 = {
    Text = "Ooohhh——!!"
  },
  AvgDialog_23354_Content_7 = {
    Text = "Oh cielo, è incredibile! Può guarire le cicatrici sul mio viso…"
  },
  AvgDialog_23354_Content_8 = {
    Text = "Non spingete... Mettetevi in fila, tutti quanti! Ascoltate bene, cinque Fang a mestolo!"
  },
  AvgDialog_23354_Content_9 = {
    Text = "Datemi un mestolo! Ero qui prima io…!!"
  },
  AvgDialog_23355_Content_1 = {
    Text = "Guida della Dama"
  },
  AvgDialog_23355_Content_10 = {
    Text = "Capo... Ho trovato questo sotto la ruota!"
  },
  AvgDialog_23355_Content_11 = {
    Text = "Di nuovo una rosa? Heh, piuttosto sfrontato. Sembra che questo assassino ci abbia lanciato una sfida."
  },
  AvgDialog_23355_Content_12 = {
    Text = "Indagate: scoprite quali nobili che hanno partecipato al funerale sono ancora in vita."
  },
  AvgDialog_23355_Content_13 = {
    Text = "Sono in grave pericolo adesso."
  },
  AvgDialog_23355_Content_14 = {
    Text = "Passaggio Sotterraneo dei Mythag"
  },
  AvgDialog_23355_Content_15 = {
    Text = "Il gruppo avanzava nel profondo passaggio sotterraneo, i loro passi leggermente disordinati risuonavano al suo interno."
  },
  AvgDialog_23355_Content_16 = {Text = "..."},
  AvgDialog_23355_Content_17 = {
    Text = "È raro vederti in questo stato. Non dirmi che il fantasma ti ha spaventato così tanto da non riuscire a dormire?"
  },
  AvgDialog_23355_Content_18 = {
    Text = "Esattamente. Tutti nell'ambiente sono in agitazione in questo momento. Solo scrivere lettere di condoglianze mi sta sfinendo."
  },
  AvgDialog_23355_Content_19 = {
    Text = "E poi ci sono quei detective insistenti e i reporter dei tabloid con cui fare i conti..."
  },
  AvgDialog_23355_Content_2 = {
    Text = [[
Brinsborough Road, 19:30  
Tre settimane dopo la morte di Lady Sorel]]
  },
  AvgDialog_23355_Content_20 = {
    Text = [[
Resta alla scuola per i prossimi giorni.
In quanto sopravvissuto al funerale, sei ora sotto la nostra protezione prioritaria.]]
  },
  AvgDialog_23355_Content_21 = {
    Text = "Non preoccuparti, lo terrò d'occhio io, e nel frattempo correggerò la brutta abitudine di un certo qualcuno di bere e fare baldoria."
  },
  AvgDialog_23355_Content_22 = {
    Text = "Fare baldoria? È perfettamente normale socializzare e divertirsi, eppure dalla tua bocca sembra così indecoroso."
  },
  AvgDialog_23355_Content_23 = {
    Text = "<SmallShake:Ehm, per favore, voi due, calmiamoci...>"
  },
  AvgDialog_23355_Content_24 = {
    Text = "Ho sentito dire che dopo la morte di Lady Sorel, si è trasformata in una manciata di Argento, e che ora è in fase di estrazione presso la Divisione dei Risvegliatori, in attesa di <Yellow:un secondo Risveglio>?"
  },
  AvgDialog_23355_Content_25 = {
    Text = "Sei piuttosto ben informato. Tuttavia, il tasso di successo di un secondo Risveglio è estremamente basso. Non riporvi le tue speranze."
  },
  AvgDialog_23355_Content_26 = {
    Text = "Capito. Non mi aspettavo che un Risvegliatore potesse ancora produrre Argento dopo la morte. In cosa differirebbe il nuovo Risvegliatore dall'originale?"
  },
  AvgDialog_23355_Content_27 = {
    Text = "Erediterà i ricordi e la personalità del predecessore, ma le sue abilità saranno di gran lunga inferiori.\nEcco perché ricordo sempre ai nostri Risvegliatori: cercate di non morire con troppa leggerezza."
  },
  AvgDialog_23355_Content_28 = {
    Text = "In quanto Risvegliatore, Lady Sorel possedeva qualche Abilità Speciale?\nUna persona del suo rango doveva essere eccezionalmente potente."
  },
  AvgDialog_23355_Content_29 = {
    Text = "Doll scosse la testa."
  },
  AvgDialog_23355_Content_3 = {
    Text = "Passi Affrettati riecheggiavano nel vicolo stretto. Oltre la Folla di curiosi radunati a distanza, i Detective di Londinium erano al lavoro."
  },
  AvgDialog_23355_Content_30 = {
    Text = "Il suo fascicolo è classificato come informazione top-secret di Mythag, e nemmeno io ho l'autorizzazione per consultarlo.\nMa ho sentito dire che si trattava di abilità... beh, piuttosto inconsistenti."
  },
  AvgDialog_23355_Content_31 = {
    Text = "Questo spiega anche perché, pur essendo una Risvegliatore, sia stata pugnalata a morte nel teatro dell'opera davanti a tutti."
  },
  AvgDialog_23355_Content_32 = {
    Text = "Inconsistenti? Intendi tipo affascinare il sesso opposto, eterna giovinezza, cose del genere?"
  },
  AvgDialog_23355_Content_33 = {
    Text = "Forse. Non ho alcun interesse a fare simili speculazioni oziose."
  },
  AvgDialog_23355_Content_34 = {
    Text = "Informazioni top-secret... perché?"
  },
  AvgDialog_23355_Content_35 = {
    Text = "Perché ricopriva una posizione di potere sufficientemente elevata, ovviamente. Sorel manteneva stretti e prolungati Transiti con Mythag e alti funzionari governativi, ma le sue origini e il suo passato sono sempre stati un mistero."
  },
  AvgDialog_23355_Content_36 = {
    Text = "E le altre vittime? Legami di Sangue, Transiti finanziari, posizioni politiche... devo sapere tutto. Chi trae il maggior vantaggio da questa serie di casi."
  },
  AvgDialog_23355_Content_37 = {
    Text = "Stiamo indagando, ma i progressi saranno lenti. Le reti sociali di questi nobili signori sono più complesse degli affluenti del fiume Aethis."
  },
  AvgDialog_23355_Content_38 = {
    Text = "I dignitari che hanno partecipato al funerale stanno morendo uno dopo l'altro."
  },
  AvgDialog_23355_Content_39 = {
    Text = "Data la situazione attuale, è molto probabile che Dexter diventi il prossimo bersaglio..."
  },
  AvgDialog_23355_Content_4 = {
    Text = "Il defunto è @1: il Barone Cavendish, 32 anni. Dopo aver lasciato un ritrovo con amici nel cuore della notte, è stato trovato qui alle 4 del mattino."
  },
  AvgDialog_23355_Content_40 = {
    Text = "Non preoccupatevi. È esattamente per questo che vi ho portati tutti qui."
  },
  AvgDialog_23355_Content_41 = {
    Text = "Mentre parlate, siete già arrivati a destinazione. Doll si ferma e indica una Porta chiusa nell'angolo della stanza buia."
  },
  AvgDialog_23355_Content_42 = {
    Text = "L'avevi già attraversata una volta per entrare nel Dominio Artificiale di Ramona. Fu un'esperienza indimenticabile."
  },
  AvgDialog_23355_Content_43 = {
    Text = "Dato che l'approccio investigativo tradizionale è irto di difficoltà, perché non sfruttare il <Yellow:Dominio Artificiale>."
  },
  AvgDialog_23355_Content_44 = {
    Text = "Capisco! Possiamo tornare sulle scene del crimine attraverso il Dominio di Lady Sorel e indagare a nostro piacimento!"
  },
  AvgDialog_23355_Content_45 = {
    Text = "Il solo Dominio di Lady Sorel probabilmente non basterà. Dovremo anche combinarlo con il Dominio della sua <Blue:Cameriera Karen>, e forse anche di altri individui collegati, per raccogliere indizi."
  },
  AvgDialog_23355_Content_46 = {
    Text = "La cameriera Karen?"
  },
  AvgDialog_23355_Content_47 = {
    Text = "Doll annuì."
  },
  AvgDialog_23355_Content_48 = {
    Text = "Era distrutta dalla morte di Sorel e ha giurato di offrirci la sua Piena Cooperazione nelle indagini per trovare il vero assassino."
  },
  AvgDialog_23355_Content_49 = {
    Text = [[
Mythag, Ingresso del Dominio Artificiale
Prima della Partenza]]
  },
  AvgDialog_23355_Content_5 = {
    Text = "Questo è il settimo nobile a morire in circostanze anomale. Se ricordo bene, il primo a morire fu..."
  },
  AvgDialog_23355_Content_50 = {
    Text = "Una volta che tutto fu pronto, Ramona si voltò verso Dexter."
  },
  AvgDialog_23355_Content_51 = {
    Text = "Non lasciare la scuola, e non andare in giro nemmeno al suo interno. Aspetta che torniamo."
  },
  AvgDialog_23355_Content_52 = {
    Text = "Ancora quel tono, come se stessi parlando a un bambino. Ti ricordi che sono il tuo anziano, il tuo distinto e rispettato padre, vero?"
  },
  AvgDialog_23355_Content_53 = {Text = "..."},
  AvgDialog_23355_Content_54 = {
    Text = "Va bene, va bene, mi arrendo...\nResterò qui ogni giorno, non andrò da nessuna parte e di sicuro non causerò problemi a nessuno."
  },
  AvgDialog_23355_Content_55 = {
    Text = "Dexter aveva ancora la sua solita espressione sorridente. Posò le mani sulle vostre spalle, la tua e quella di Ramona, poi diede una leggera spinta in avanti—"
  },
  AvgDialog_23355_Content_56 = {
    Text = "Andate, ragazzi. La mia vita è nelle vostre mani ora."
  },
  AvgDialog_23355_Content_6 = {
    Text = "<Red:Il Duca Harold>. Ricordo questo caso molto chiaramente: era una Porsche! Ce ne sono a malapena una manciata in tutto il regno!"
  },
  AvgDialog_23355_Content_7 = {
    Text = "Peccato che sia stata ridotta a un ammasso di rottami... Il Duca Harold, il suo maggiordomo e il suo autista erano tutti in macchina in quel momento. Sono morti tutti e tre."
  },
  AvgDialog_23355_Content_8 = {
    Text = "A parte il fatto di essere tutti figure di spicco, l'unica cosa che queste vittime avevano in comune è che hanno tutte partecipato al funerale di Lady Sorel tre settimane fa."
  },
  AvgDialog_23355_Content_9 = {
    Text = "Possibile che sia davvero come dicono i tabloid, che siano perseguitati dal <Red:fantasma di Lady Sorel>..."
  },
  AvgDialog_23356_Content_1 = {
    Text = "Rosafunebre"
  },
  AvgDialog_23356_Content_10 = {
    Text = "Hannah non è ancora riuscita a ottenere altre informazioni dalla stazione di polizia… Ma non importa, la reporter Hannah non si arrende mai! Ora sono tornata con nuove notizie!"
  },
  AvgDialog_23356_Content_11 = {
    Text = "Notizia 1: Si dice che il cimitero sia stato adornato oggi con migliaia di rose \"Red Celebration\" trasportate da Costantinopoli, per un costo totale di 10.000 Fang!"
  },
  AvgDialog_23356_Content_12 = {
    Text = "Notizia 2: Indovinate chi ho avvistato fuori poco fa?"
  },
  AvgDialog_23356_Content_13 = {
    Text = "La famiglia Cavendish, il Duca e la Duchessa di Windsor, e quelli a cui tutti tengono di più…"
  },
  AvgDialog_23356_Content_14 = {
    Text = "<Big:Lo stimato Duca Harold e il suo unico figlio, Nicholas Harold!>"
  },
  AvgDialog_23356_Content_15 = {
    Text = "A suo tempo, la notizia di padre e figlio che si sfidavano a duello per Lady Sorel fece scalpore in tutta la città…"
  },
  AvgDialog_23356_Content_16 = {
    Text = "Nel frattempo, all'interno del Cimitero di Woodlawn…"
  },
  AvgDialog_23356_Content_17 = {
    Text = "Oggi ci riuniamo per ricordare e onorare la vita di Sorel @1."
  },
  AvgDialog_23356_Content_18 = {
    Text = "Era la figlia più devota dell'Onnipotente, una donna di nobile carattere e degna di ammirazione…"
  },
  AvgDialog_23356_Content_19 = {
    Text = "Etciù… <Big:Etciù!>"
  },
  AvgDialog_23356_Content_2 = {
    Text = [[
Fuori dal Cimitero di Woodlawn
Tre settimane fa]]
  },
  AvgDialog_23356_Content_20 = {
    Text = "Vi siete preso un raffreddore, Vostra Grazia? Non avete smesso un attimo di starnutire."
  },
  AvgDialog_23356_Content_21 = {
    Text = "L'odore di questi fiori pacchiani è insopportabile... Devono essere costati almeno diverse migliaia di Fang per farli portare qui."
  },
  AvgDialog_23356_Content_22 = {
    Text = "Sorel ha mantenuto la sua attitudine da nuova ricca fino alla fine, il che è piuttosto ammirevole... Etciù!"
  },
  AvgDialog_23356_Content_23 = {
    Text = "Ammirevole davvero."
  },
  AvgDialog_23356_Content_24 = {
    Text = "Un comportamento del genere dà sicuramente ai cronisti di gossip e ai Cittadini là fuori di che parlare. Non c'è da stupirsi che sia diventata l'idolo pubblico di Londinium."
  },
  AvgDialog_23356_Content_25 = {
    Text = "Hmph. Un trucco rozzo."
  },
  AvgDialog_23356_Content_26 = {
    Text = "Dexter scrollò le spalle e si guardò intorno con un'espressione di totale noia."
  },
  AvgDialog_23356_Content_27 = {
    Text = "Mondane riccamente vestite si riunivano in piccoli capannelli davanti alla tomba, i loro pettegolezzi volutamente sussurrati giungevano all'orecchio insieme alle preghiere dell'officiante."
  },
  AvgDialog_23356_Content_28 = {
    Text = "<Gray:Una ragazza di campagna, eppure si spacciava per una nobildonna straniera…>"
  },
  AvgDialog_23356_Content_29 = {
    Text = "<Gray:L'abito con cui è stata sepolta... è flanella? Di una qualità così pregiata…>"
  },
  AvgDialog_23356_Content_3 = {
    Text = "<Italic:Shhhh... Shhhhh...>"
  },
  AvgDialog_23356_Content_30 = {
    Text = "<Gray:…l'amante del Re…e il Principe…eppure la Regina ha chiuso un occhio…>"
  },
  AvgDialog_23356_Content_31 = {Text = "..."},
  AvgDialog_23356_Content_32 = {
    Text = "Sembra che questa signora non fosse davvero molto benvoluta."
  },
  AvgDialog_23356_Content_33 = {
    Text = "Polvere alla polvere, cenere alla cenere.\nL'anima di Lady Sorel è entrata nell'Elisio, tornando nell'abbraccio del Padre..."
  },
  AvgDialog_23356_Content_34 = {
    Text = "Lord Dexter, a giudicare dalla vostra reazione, sembra che non condividiate del tutto le nostre opinioni su Lady Sorel?"
  },
  AvgDialog_23356_Content_35 = {
    Text = "Che siate anche voi uno dei suoi ammiratori? O meglio... lo eravate? O lo sarete presto?"
  },
  AvgDialog_23356_Content_36 = {
    Text = "Un'ondata di risate soffocate esplose dalla Folla, e Dexter aggrottò le sopracciglia."
  },
  AvgDialog_23356_Content_37 = {
    Text = "Non ho avuto molte interazioni personali con Lady Sorel quando era in vita, né mi interessano i conflitti tra lei e voi."
  },
  AvgDialog_23356_Content_38 = {
    Text = "Tuttavia, il mio buon senso mi dice che spettegolare sui defunti durante un funerale non è certo un comportamento da gentiluomo."
  },
  AvgDialog_23356_Content_39 = {
    Text = "State attenti: un fantasma di dama potrebbe venire a bussare al vostro Cancello nel cuore della notte."
  },
  AvgDialog_23356_Content_4 = {
    Text = "*Coff coff*… L'obiettivo e l'esposimetro sono pronti? Smettila di armeggiare e sbrigati!"
  },
  AvgDialog_23356_Content_40 = {
    Text = "…Che l'Onnipotente vi protegga, figlio mio."
  },
  AvgDialog_23356_Content_41 = {
    Text = "Al calar della notte, un'automobile Ferdinand Porsche nuova di zecca sobbalzava lungo un sentiero di ciottoli irregolari."
  },
  AvgDialog_23356_Content_42 = {
    Text = "Maledizione, quei reporter dei tabloid mi seguono ovunque vada."
  },
  AvgDialog_23356_Content_43 = {
    Text = "Le voci là fuori sostengono che io e Nicholas siamo venuti alle mani per Sorel... un'assoluta assurdità!"
  },
  AvgDialog_23356_Content_44 = {
    Text = "Come potrebbero mai i popolani comprendere ciò che occupa davvero la mente del Duca? Preferiscono credere a quelle banali e assurde storie d'amore."
  },
  AvgDialog_23356_Content_45 = {
    Text = "Amore, hmph. Nicholas mi disse la stessa cosa: che si trattava di \"amore\"."
  },
  AvgDialog_23356_Content_46 = {
    Text = "Avrei anche potuto chiudere un occhio su qualsiasi giochetto si facessero quei due, ma quella Donna ha avuto l'audacia di mettere gli occhi sulle riserve di caccia fuori Shoreditch."
  },
  AvgDialog_23356_Content_47 = {
    Text = "La Cupidigia finisce inevitabilmente per attirare sciagure... quindi non poteva prendersela che con sé stessa quando abbiamo smesso di essere cortesi..."
  },
  AvgDialog_23356_Content_48 = {Text = "—!!"},
  AvgDialog_23356_Content_49 = {
    Text = "L'auto si arrestò bruscamente con uno stridio, il suono acuto dei freni squarciò la tranquillità che apparteneva solo alla notte."
  },
  AvgDialog_23356_Content_5 = {Text = "*Bzzt*…"},
  AvgDialog_23356_Content_50 = {
    Text = "<Shake:Ahi!! La mia schiena...>"
  },
  AvgDialog_23356_Content_51 = {
    Text = "La tua guida è sempre più scellerata, Fred. Hai dimenticato come si frena?"
  },
  AvgDialog_23356_Content_52 = {
    Text = "<Shake:No, signore... c'è... qualcosa... là davanti...>"
  },
  AvgDialog_23356_Content_53 = {
    Text = "La Figura Oscura se ne stava sola sotto la fredda luce lunare, il ghigno insanguinato dipinto sulla maschera si estendeva fino agli angoli cavi degli occhi."
  },
  AvgDialog_23356_Content_54 = {
    Text = "In fondo al vicolo deserto, con le braccia spalancate, la figura canticchiava sommessamente un allegro inno da bevitori."
  },
  AvgDialog_23356_Content_55 = {
    Text = "<RedItalic:Leviamo in alto i calici del Banchetto, il vino pregiato inebria il cuore.>"
  },
  AvgDialog_23356_Content_56 = {
    Text = "<RedItalic:I tempi gioiosi sono davvero meravigliosi, ma la morte sincera è ancor più preziosa...>"
  },
  AvgDialog_23356_Content_57 = {
    Text = "Buonasera, signor Harold."
  },
  AvgDialog_23356_Content_6 = {
    Text = "Pronta a girare? Bene… 3, 2, 1, Via!"
  },
  AvgDialog_23356_Content_7 = {
    Text = "Buongiorno, amici di Mythag! Qui la reporter del giornale scolastico Hannah con un servizio e·sclu·si·vo!"
  },
  AvgDialog_23356_Content_8 = {
    Text = "Il <Blue:funerale di Lady Sorel>, una donna di mondo della sua generazione e amata dai cittadini di Londinium, si sta svolgendo nel Cimitero di Woodlawn, non lontano da dove mi trovo!"
  },
  AvgDialog_23356_Content_9 = {
    Text = "Come vola il tempo! È passata un'intera settimana dalla misteriosa morte di Lady Sorel al teatro dell'opera."
  },
  AvgDialog_23359_Content_10 = {
    Text = "Sei una ragazza intelligente, Sorel. Il signor Binder è il miglior partito che la nostra famiglia possa mai sperare di ottenere. Capisci?"
  },
  AvgDialog_23359_Content_11 = {
    Text = "Non importa se non ti piace. Una volta ottenuta la sua fortuna, potrai fare tutto ciò che vorrai e vedere chiunque ti piaccia."
  },
  AvgDialog_23359_Content_12 = {Text = "..."},
  AvgDialog_23359_Content_13 = {
    Text = "Non mi piace tutto questo, Padre."
  },
  AvgDialog_23359_Content_14 = {
    Text = "Le persone come noi non hanno il lusso di fare ciò che vogliono.\nGuarda il Malanno di tua Madre—puoi sopportare di vederLa soffrire così per sempre?"
  },
  AvgDialog_23359_Content_15 = {
    Text = "<Shake:*Coff coff*... Non preoccuparti per me, Sorel. Non sarò più qui ancora a lungo, ormai...>"
  },
  AvgDialog_23359_Content_16 = {Text = "Madre..."},
  AvgDialog_23359_Content_17 = {
    Text = "Sorel, tua Madre e io siamo ormai vecchi. Tu sei la nostra Unica speranza."
  },
  AvgDialog_23359_Content_18 = {
    Text = "Non abbiamo investito tutto quel denaro per crescerti per carità—l'abbiamo fatto affinché un giorno potessimo vederne il ritorno. Capisci?"
  },
  AvgDialog_23359_Content_19 = {
    Text = "Non fare nulla di cui potresti pentirti."
  },
  AvgDialog_23359_Content_2 = {
    Text = "245 anni prima del Diluvio, Constan meridionale"
  },
  AvgDialog_23359_Content_20 = {
    Text = "Nella notte silenziosa, la Fanciulla sedeva sul bordo del Suo letto, fissando con sguardo assente la luce brillante della luna fuori dalla finestra."
  },
  AvgDialog_23359_Content_21 = {
    Text = "Si strinse le ginocchia forte, incoraggiandoSi in silenzio nel Suo cuore, come aveva sempre fatto."
  },
  AvgDialog_23359_Content_22 = {
    Text = "Non avere paura, Sorel. Troverai una soluzione."
  },
  AvgDialog_23359_Content_23 = {
    Text = "<Red:Che peccato... È questo il prezzo che si deve pagare per la bellezza?>"
  },
  AvgDialog_23359_Content_24 = {
    Text = "<Red:Anche la luna più immacolata, cadendo nel mondo mortale, sarebbe gravata dalla polvere.>"
  },
  AvgDialog_23359_Content_25 = {
    Text = "La nebbia nell'angolo frusciò e si contorse, condensandosi in una sagoma Caotica."
  },
  AvgDialog_23359_Content_26 = {Text = "?!"},
  AvgDialog_23359_Content_27 = {
    Text = "Chi sei? Chiamerò aiuto—"
  },
  AvgDialog_23359_Content_28 = {
    Text = "Shh… Sono Solo uno spettro errante che vaga per il mondo mortale. La mia Identità è del tutto fittizia, e il mio aspetto non è che un travestimento."
  },
  AvgDialog_23359_Content_29 = {
    Text = "È un piacere conoscerti. Puoi chiamarmi <Red:\"N\">."
  },
  AvgDialog_23359_Content_3 = {
    Text = "Sorel, mia bella Sorel. Ti ho comprato un vestito nuovo, nel tuo colore preferito — bianco."
  },
  AvgDialog_23359_Content_30 = {
    Text = "Per un certo ineffabile diletto, colleziono storie e le riscrivo.\nQuando incontro esseri umani che mi interessano, non mi dispiace dar loro una mano—entro limiti ragionevoli."
  },
  AvgDialog_23359_Content_31 = {
    Text = "Perché dunque non mi racconti cosa ti affligge."
  },
  AvgDialog_23359_Content_32 = {
    Text = "La voce della nebbia oscura era profonda e gradevole, dotata di un misterioso potere capace di ammaliare il cuore.\nLa Fanciulla si calmò gradualmente."
  },
  AvgDialog_23359_Content_33 = {
    Text = "Mio padre non è abbastanza astuto, e il Signor Binder è tutt'altro che un partito adatto. È avido e amante delle Scommesse—dategli tre anni e dilapiderà l'intero patrimonio di famiglia."
  },
  AvgDialog_23359_Content_34 = {
    Text = "Ma sono troppo debole per oppormi a loro."
  },
  AvgDialog_23359_Content_35 = {
    Text = "Quanto a mia Madre… Lei piange sempre. Non può aiutarmi."
  },
  AvgDialog_23359_Content_36 = {
    Text = "La Fanciulla abbassò il capo, l'espressione offuscata dalla tristezza."
  },
  AvgDialog_23359_Content_37 = {
    Text = "Sono stanca di tutto. Stanca di vivere nella paura costante per il denaro, stanca della sensazione che il mio Destino sia nelle mani di qualcun altro."
  },
  AvgDialog_23359_Content_38 = {
    Text = "Dici che puoi aiutarmi — puoi darmi un sacco di soldi?"
  },
  AvgDialog_23359_Content_39 = {
    Text = "Temo di no, bambina mia."
  },
  AvgDialog_23359_Content_4 = {
    Text = "È bellissimo, grazie, Padre. Ma sembra fin troppo costoso..."
  },
  AvgDialog_23359_Content_40 = {
    Text = "E uccidere qualcuno per me?"
  },
  AvgDialog_23359_Content_41 = {
    Text = "Hahaha… Non è certo qualcosa che una signorina di 13 anni dovrebbe dire, ma è anche esattamente il motivo per cui ho scelto te."
  },
  AvgDialog_23359_Content_42 = {
    Text = [[
Purtroppo non posso uccidere nessuno per te.
Ma ti prometto che, se stipuleremo un contratto, riceverai una certa "assistenza necessaria".]]
  },
  AvgDialog_23359_Content_43 = {
    Text = "Questi mezzi non sono diretti, eppure sono più che sufficienti per essere letali."
  },
  AvgDialog_23359_Content_44 = {
    Text = "Ti aiuteranno a scalare vette che non hai mai raggiunto, ti mostreranno panorami che non hai mai visto, e non dovrai mai più sposare qualche vecchio giocatore d'azzardo calvo."
  },
  AvgDialog_23359_Content_45 = {
    Text = "La Fanciulla ascoltò in silenzio, mentre un sorriso si diffondeva lentamente sul suo volto freddo."
  },
  AvgDialog_23359_Content_46 = {
    Text = "Fin da piccola, ero una bambina graziosa e popolare. Molte persone si avvicinavano a me, volendo essere miei amici."
  },
  AvgDialog_23359_Content_47 = {
    Text = "Mi osservavano come sciacalli, ognuno desideroso di ottenere qualcosa da me con gli interessi — proprio come diceva sempre mio padre."
  },
  AvgDialog_23359_Content_48 = {
    Text = "Così ho capito presto che un Miracolo non sarebbe mai arrivato per me."
  },
  AvgDialog_23359_Content_49 = {
    Text = "Non sono una sciocca, Signor N. Hai esposto così tante condizioni allettanti, quindi..."
  },
  AvgDialog_23359_Content_5 = {
    Text = "Sì, piuttosto costoso. Mi è costato ben 200 sterline."
  },
  AvgDialog_23359_Content_50 = {
    Text = "Qual è il prezzo?"
  },
  AvgDialog_23359_Content_51 = {
    Text = [[
Periferia di Londinium
Tenuta Lambert]]
  },
  AvgDialog_23359_Content_52 = {
    Text = "Signor Lambert, siete accusato di essere coinvolto nell'omicidio di Lady Sorel. Vi preghiamo di seguirci."
  },
  AvgDialog_23359_Content_53 = {
    Text = "Il tempo sembrava essersi fermato da molto. Una luce diurna pallida si riversava giù, drappeggiando la sala vuota con un velo bianco."
  },
  AvgDialog_23359_Content_54 = {
    Text = "Un Vento desolato soffiava incessantemente attraverso le crepe delle finestre rotte, facendo frusciare le rose e le foglie appassite sparse sul pavimento."
  },
  AvgDialog_23359_Content_55 = {
    Text = "*coff coff* Finalmente siete qui... Vi aspettavo da molto tempo..."
  },
  AvgDialog_23359_Content_56 = {
    Text = "L'Anziano, decrepito e avvizzito, sedeva sprofondato in una lussuosa poltrona di velluto, facendo roteare delicatamente un bicchiere di vino rosso nella mano."
  },
  AvgDialog_23359_Content_57 = {
    Text = "Se vi dicessi che non sono stato io a ucciderla, mi credereste?"
  },
  AvgDialog_23359_Content_58 = {
    Text = "In quanto unico beneficiario del testamento di Sorel, e avendo recentemente accumulato enormi debiti di gioco, possedete un movente perfetto per il crimine."
  },
  AvgDialog_23359_Content_59 = {Text = "Inoltre..."},
  AvgDialog_23359_Content_6 = {
    Text = "200 sterline?! Il reddito annuale di Padre è solo... No, dobbiamo restituirlo subito."
  },
  AvgDialog_23359_Content_60 = {
    Text = "Ramona estrasse il raffinato Pugnale."
  },
  AvgDialog_23359_Content_61 = {
    Text = "Questo è ciò che abbiamo Rinvenuto sulla scena del crimine — una preziosa importazione dall'Estremo Oriente."
  },
  AvgDialog_23359_Content_62 = {
    Text = "Abbiamo rintracciato il venditore. Quel Mercante di antichità ha confermato che il Signor Lambert lo acquistò due mesi fa."
  },
  AvgDialog_23359_Content_63 = {
    Text = "Forse potrebbe spiegarci perché lo portò al teatro dell'opera quel giorno?"
  },
  AvgDialog_23359_Content_64 = {
    Text = "Il motivo? Hehehe..."
  },
  AvgDialog_23359_Content_65 = {
    Text = "Il cigolio di una sedia raggiunse le loro orecchie."
  },
  AvgDialog_23359_Content_66 = {
    Text = "Lambert si alzò a fatica e si trascinò laboriosamente verso Ramona."
  },
  AvgDialog_23359_Content_67 = {
    Text = "Perché meritava di morire.\nSono stato io a portarla in cima — ricchezza, status, fama… Ero io a tirare tutti i fili dietro le quinte."
  },
  AvgDialog_23359_Content_68 = {
    Text = "Ma lei? Dopo essere salita alla ribalta, non solo non mi ha ripagato, ma non vedeva l'ora di allontanarsi il più possibile da me."
  },
  AvgDialog_23359_Content_69 = {
    Text = "Guardate questa casa… Ho già impegnato tutto ciò che potevo. Tutto ciò che resta è questa stanza piena di rose."
  },
  AvgDialog_23359_Content_7 = {
    Text = "Meriti le cose più belle, Sorel."
  },
  AvgDialog_23359_Content_70 = {
    Text = [[
Erano i fiori preferiti di mia moglie quando era in vita.
Dopo la morte di mia moglie, l'unico legame tra Sorel e me era svanito.]]
  },
  AvgDialog_23359_Content_71 = {
    Text = "Così ho deciso di ucciderla…"
  },
  AvgDialog_23359_Content_72 = {
    Text = "Petali sparsi fluttuarono giù dall'aria."
  },
  AvgDialog_23359_Content_73 = {
    Text = "L'Anziano alzò il capo. La maggior parte del suo volto era già stata consumata dall'Erosione, e un fluido scuro e Vischioso gli colava dagli angoli degli occhi come lacrime."
  },
  AvgDialog_23359_Content_74 = {
    Text = "…Proprio come ho deciso di uccidere tutti voi."
  },
  AvgDialog_23359_Content_8 = {
    Text = "Tra tre giorni, il signor Binder verrà a Casa Nostra come ospite. Indossa questo vestito e trattalo bene."
  },
  AvgDialog_23359_Content_9 = {
    Text = "...Quell'arrogante vecchio? Non mi piace."
  },
  AvgDialog_23360_Content_1 = {
    Text = "Prigioniero del Destino"
  },
  AvgDialog_23360_Content_10 = {
    Text = "<Red:Hehe.>"
  },
  AvgDialog_23360_Content_11 = {
    Text = "<Red:Mi piace {Male=him,Female=her}.>"
  },
  AvgDialog_23360_Content_12 = {
    Text = "Sembra avere paura di qualcosa."
  },
  AvgDialog_23360_Content_13 = {
    Text = "...Vuoi davvero che giochi con te?"
  },
  AvgDialog_23360_Content_14 = {
    Text = "Lady Sorel esitò per un momento, poi annuì dolcemente."
  },
  AvgDialog_23360_Content_15 = {
    Text = "<Gray:Due bicchieri di champagne non dovrebbero essere un problema...>"
  },
  AvgDialog_23360_Content_16 = {
    Text = "Accetto la tua proposta. Togliamoci il pensiero — Risoluzione Rapida.\nQual è la prima domanda?"
  },
  AvgDialog_23360_Content_17 = {Text = "Ugh..."},
  AvgDialog_23360_Content_18 = {
    Text = "Sorel appoggia il mento su una mano, le dita affusolate che tamburellano leggermente sulla guancia."
  },
  AvgDialog_23360_Content_19 = {
    Text = "Prima domanda: come faceva Mythag a sapere che qualcuno sarebbe venuto a uccidermi stasera?"
  },
  AvgDialog_23360_Content_2 = {Text = "B-Bere?!"},
  AvgDialog_23360_Content_20 = {
    Text = "Se non potete rispondere a questa domanda, sarebbe ragionevole da parte mia sospettare che siate tutti coinvolti in qualche misura?"
  },
  AvgDialog_23360_Content_21 = {
    Text = "Non è una domanda a cui si possa rispondere con leggerezza..."
  },
  AvgDialog_23360_Content_22 = {
    Text = "Prendi lo champagne dal tavolo e lo mandi giù in un solo sorso."
  },
  AvgDialog_23360_Content_23 = {
    Text = "Con tua sorpresa, il liquido dorato pallido ha un gusto leggero e delicato, con un accenno di aroma agrumato."
  },
  AvgDialog_23360_Content_24 = {
    Text = "<Gray:Hmm... in effetti è piuttosto buono.>"
  },
  AvgDialog_23360_Content_25 = {
    Text = "Sorseggia piano, Custode. Quella bottiglia vale abbastanza da comprare un appartamento nel centro di Londinium."
  },
  AvgDialog_23360_Content_26 = {
    Text = "*Coff coff*... <Big:Cosa?!>"
  },
  AvgDialog_23360_Content_27 = {
    Text = "Ora passiamo alla seconda domanda. La pongo a nome delle dame e delle signore di Londinium..."
  },
  AvgDialog_23360_Content_28 = {
    Text = "Sorel ti rivolge un lieve sorriso. Per qualche ragione, hai un brutto presentimento."
  },
  AvgDialog_23360_Content_29 = {
    Text = "Chi è esattamente la madre biologica della figlia di Lord Dexter?"
  },
  AvgDialog_23360_Content_3 = {
    Text = "<Gray:La signorina Doll ha detto che non ho l'età per bere, e non mi è permesso bere nemmeno durante un'indagine...>"
  },
  AvgDialog_23360_Content_30 = {
    Text = "*Pfft—!!*"
  },
  AvgDialog_23360_Content_31 = {
    Text = "Sputi tutto il vino che non avevi ancora ingoiato. Sorel inarca un sopracciglio, e Karen si fa subito avanti per pulire il vino versato dal tavolo."
  },
  AvgDialog_23360_Content_32 = {
    Text = "<SmallShake:Tsk tsk, anche quel piccolo sorso costa una fortuna! Sarebbe bastato per comprarmi una nuova collana da Harrods...>"
  },
  AvgDialog_23360_Content_33 = {
    Text = "Non mi aspettavo che Lady Sorel fosse interessata a pettegolezzi così banali. Che sorpresa... Ha, haha."
  },
  AvgDialog_23360_Content_34 = {
    Text = "Ti svelo un segreto: noi \"mondane\" passiamo almeno metà della giornata a vivere di pettegolezzi."
  },
  AvgDialog_23360_Content_35 = {
    Text = "Cos'altro pensavi che mandasse avanti il <Blue:salotto di Lady Sorel>?"
  },
  AvgDialog_23360_Content_36 = {
    Text = "...Posso immaginare."
  },
  AvgDialog_23360_Content_37 = {
    Text = "Nessuno crede alla storia del padre e della figlia adottivi, sai. Secondo le voci nei nostri circoli, la madre biologica della bambina sarebbe l'amante di qualche lord..."
  },
  AvgDialog_23360_Content_38 = {
    Text = "N-Non dire sciocchezze.\nLord Dexter è un uomo retto e rispettabile. Non è assolutamente quello che tutti pensano..."
  },
  AvgDialog_23360_Content_39 = {
    Text = "%player%, il comunicatore è stato acceso tutto il tempo. Ho sentito tutto."
  },
  AvgDialog_23360_Content_4 = {
    Text = "Mi dispiace, Lady Sorel."
  },
  AvgDialog_23360_Content_40 = {
    Text = "Ti consiglio di non sprecare le tue energie. Nemmeno io so chi sia la mia madre biologica."
  },
  AvgDialog_23360_Content_41 = {Text = "..."},
  AvgDialog_23360_Content_42 = {
    Text = "Che sia l'alcol o meno, improvvisamente avverti un leggero capogiro."
  },
  AvgDialog_23360_Content_43 = {
    Text = "Non è quello che pensano tutti? E allora cos'è?"
  },
  AvgDialog_23360_Content_44 = {
    Text = "Scuoti la testa e prendi il bicchiere sul tavolo."
  },
  AvgDialog_23360_Content_45 = {
    Text = "Questa domanda è davvero così importante per te?"
  },
  AvgDialog_23360_Content_46 = {
    Text = "Non proprio. Volevo solo completare le tre domande."
  },
  AvgDialog_23360_Content_47 = {
    Text = "<Red:Molto bene, Sorel. E ora...>"
  },
  AvgDialog_23360_Content_48 = {
    Text = "Sorel preme delicatamente il bicchiere davanti a te. Per qualche ragione, hai l'impressione che i muscoli del suo viso sembrino contorcersi per un solo istante."
  },
  AvgDialog_23360_Content_49 = {
    Text = "I bambini non dovrebbero bere, lo sai. Diciamo che mi devi questo bicchiere. Quello che voglio davvero chiederti è..."
  },
  AvgDialog_23360_Content_5 = {
    Text = "E se ti dicessi che ho sempre saputo chi sta cercando di uccidermi?"
  },
  AvgDialog_23360_Content_50 = {
    Text = "Nel momento in cui quelle parole le uscirono dalle labbra, il volto di Lady Sorel iniziò improvvisamente a distorcersi, a sfumare..."
  },
  AvgDialog_23360_Content_51 = {
    Text = "E poi si trasformò completamente in un volto del tutto diverso."
  },
  AvgDialog_23360_Content_52 = {
    Text = "Buonasera, {Male=sir,Female=miss}. Permettimi di porgerti i miei saluti attraverso le parole di un'altra persona."
  },
  AvgDialog_23360_Content_53 = {
    Text = "Tra dieci minuti dimenticherai completamente l'intero contenuto di questa conversazione, quindi ti prego, non aver timore di rispondere alle mie domande."
  },
  AvgDialog_23360_Content_54 = {
    Text = "La mia domanda è piuttosto semplice..."
  },
  AvgDialog_23360_Content_55 = {
    Text = "Il suo volto è avvolto da una vasta nebbia nera. Non riesci a distinguerne i lineamenti, eppure avverti un inspiegabile senso di familiarità."
  },
  AvgDialog_23360_Content_56 = {
    Text = "Come se molto, molto tempo fa vi foste sfiorati da qualche parte, o come se un tempo lui fosse rimasto in un luogo lontano a osservarti, indugiando per un'eternità."
  },
  AvgDialog_23360_Content_57 = {
    Text = "Il tuo nome precedente era... @2?"
  },
  AvgDialog_23360_Content_58 = {Text = "..."},
  AvgDialog_23360_Content_59 = {
    Text = "Il mondo sembrò ritirarsi come una marea in un istante."
  },
  AvgDialog_23360_Content_6 = {Text = "?!"},
  AvgDialog_23360_Content_60 = {
    Text = "Tutti i suoni svanirono e tutte le immagini si dissolsero."
  },
  AvgDialog_23360_Content_61 = {
    Text = "Le labbra si aprono e si chiudono, pronunciando parole silenziose. Ma tu lo sai — ha pronunciato il tuo <Yellow:nome originale> con assoluta precisione."
  },
  AvgDialog_23360_Content_62 = {
    Text = "%player%? Perché è calato il silenzio totale dalla tua parte? Cos'è successo?"
  },
  AvgDialog_23360_Content_63 = {
    Text = "Schiudi le labbra secche, ma non riesci più a emettere alcun suono."
  },
  AvgDialog_23360_Content_64 = {
    Text = "Un ronzio denso e monotono si avvolge e risuona nelle profondità della tua coscienza, dilaniando furiosamente i tuoi nervi."
  },
  AvgDialog_23360_Content_65 = {
    Text = "<Change>Non lo so…"
  },
  AvgDialog_23360_Content_66 = {Text = "...?"},
  AvgDialog_23360_Content_67 = {
    Text = "Resta dove sei e non muoverti, %player%. Sto salendo—"
  },
  AvgDialog_23360_Content_68 = {Text = "Bang!"},
  AvgDialog_23360_Content_69 = {
    Text = "Le luci all'interno del teatro si spengono bruscamente."
  },
  AvgDialog_23360_Content_7 = {
    Text = "Gioca con me fino alla fine, e ti dirò la risposta."
  },
  AvgDialog_23360_Content_70 = {
    Text = "Lì, presso l'unica fonte di luce davanti al palco, quella Figura Oscura familiare eppure estranea appare ancora una volta."
  },
  AvgDialog_23360_Content_71 = {
    Text = "Tiene una rosa in mano, mentre ondate di canti sinistri e penetranti si riversano dalla nebbia nera che si contorce sul suo volto."
  },
  AvgDialog_23360_Content_72 = {
    Text = "<RedItalic:O Prigioniero del Fato.>"
  },
  AvgDialog_23360_Content_73 = {
    Text = "<RedItalic:Ti mascheri da Apostolo della luce per ingannare tutti gli esseri viventi. Ti introduci nei territori proibiti dell'Ignoto per implorare La Verità.>"
  },
  AvgDialog_23360_Content_74 = {
    Text = "<RedItalic:I tuoi ricordi perduti crescono e traboccano da occhi vuoti. Il tuo misero futuro perisce al suono del flauto.>"
  },
  AvgDialog_23360_Content_75 = {
    Text = "<RedItalic:Ora ti comando—>"
  },
  AvgDialog_23360_Content_76 = {
    Text = "<Red:Apri gli occhi.>"
  },
  AvgDialog_23360_Content_8 = {
    Text = [[
Una minaccia?
Aggrotti le sopracciglia, sul punto di rifiutare, ma poi noti qualcos'altro.]]
  },
  AvgDialog_23360_Content_9 = {
    Text = "Nascoste dietro le provocazioni disinvolte ci sono pupille costantemente contratte e nocche leggermente pallide."
  },
  AvgDialog_23361_Content_1 = {
    Text = "Canzone del Bere"
  },
  AvgDialog_23361_Content_10 = {
    Text = "Aah! Ch-chi siete? Questo è il palco privato di Lady Sorel!"
  },
  AvgDialog_23361_Content_11 = {
    Text = "Karen vi ordina di andarvene immediatamente e di non disturbare lo svago della signora... <Big:Ahi!>"
  },
  AvgDialog_23361_Content_12 = {
    Text = "Spingi da parte la cameriera ciarliera e ti avvicini a una donna vestita con eleganza."
  },
  AvgDialog_23361_Content_13 = {
    Text = "Avvolta in seta pregiata e gioielli, è come una Rosa in piena fioritura, che irradia un bagliore ammaliante sotto le luci."
  },
  AvgDialog_23361_Content_14 = {
    Text = "Un bagliore Fragile — uno che ti fa venire voglia di frantumarlo con le tue stesse mani."
  },
  AvgDialog_23361_Content_15 = {Text = "..."},
  AvgDialog_23361_Content_16 = {
    Text = "Non è il momento di ammirare una bellezza. Ci resta meno di mezz'ora, %player%."
  },
  AvgDialog_23361_Content_17 = {Text = "Eh? Ah...!"},
  AvgDialog_23361_Content_18 = {
    Text = "Buonasera, Lady Sorel. Dipartimento di Polizia di Londinium, Divisione Operazione @2, %player%."
  },
  AvgDialog_23361_Content_19 = {
    Text = "Divisione Operazione @2...?"
  },
  AvgDialog_23361_Content_2 = {
    Text = "Signore e signori, buonasera."
  },
  AvgDialog_23361_Content_20 = {
    Text = "Non provateci con me. Tutti nell'ambiente sanno che la Divisione Operazione @2 è solo una copertura creata da Mythag all'interno del dipartimento di polizia."
  },
  AvgDialog_23361_Content_21 = {
    Text = "Anche se il tuo volto non mi è familiare... L'ultima reclutina di Mythag?"
  },
  AvgDialog_23361_Content_22 = {
    Text = "Ancora Mythag! Ogni volta che voi venite a cercare la mia signora, non portate mai buone notizie! O sono cadaveri, Calamità, o soldi in prestito..."
  },
  AvgDialog_23361_Content_23 = {
    Text = "Sorel sollevò leggermente le ciglia e lanciò uno sguardo apparentemente noncurante verso Karen."
  },
  AvgDialog_23361_Content_24 = {
    Text = "Karen, questo non è un posto per chiunque. Come ha fatto {Male=he,Female=she} a entrare, c'entri tu per caso?"
  },
  AvgDialog_23361_Content_25 = {
    Text = "C-cosa? Mia signora, cosa dite! La lealtà di Karen è pura come il rubino <Blue:Cameo> sulla vostra corona!"
  },
  AvgDialog_23361_Content_26 = {
    Text = "<SmallShake:Naturalmente, vi prego di non fraintendere — non intendevo assolutamente bramare il rubino...>"
  },
  AvgDialog_23361_Content_27 = {
    Text = "In ogni caso, mia signora, Karen ve lo caverà fuori adesso per mostrarvelo — un cuore di lealtà!"
  },
  AvgDialog_23361_Content_28 = {
    Text = "Shh... Karen. Un'altra parola e ti multo di un Fang leoniano."
  },
  AvgDialog_23361_Content_29 = {
    Text = "Il suo tono gentile impartì un comando inconfutabile alla cameriera."
  },
  AvgDialog_23361_Content_3 = {
    Text = "La storia che vi narrerò stasera si svolge a Londinium, una città celebre per la sua nebbia."
  },
  AvgDialog_23361_Content_30 = {
    Text = "Cosa?! Un... <Small:Mmph!>"
  },
  AvgDialog_23361_Content_31 = {
    Text = "Karen si portò tardivamente le mani alla bocca, non osando pronunciare un'altra parola."
  },
  AvgDialog_23361_Content_32 = {
    Text = "Sorel sorseggiò delicatamente dello champagne, i suoi occhi rosso pallido che vi scrutavano con attenzione."
  },
  AvgDialog_23361_Content_33 = {
    Text = "Il mio pezzo preferito sta per iniziare, e non voglio perdermelo. Quindi..."
  },
  AvgDialog_23361_Content_34 = {
    Text = "Avete un minuto. Parlate. Cosa volete?"
  },
  AvgDialog_23361_Content_35 = {
    Text = "8:40, venti minuti rimasti."
  },
  AvgDialog_23361_Content_36 = {
    Text = [[
Capito.
Lady Sorel, vi prego di venire con me e lasciare questo luogo.]]
  },
  AvgDialog_23361_Content_37 = {
    Text = "<Red:Qualcuno sta cercando di assassinarvi.>"
  },
  AvgDialog_23361_Content_38 = {Text = "?!"},
  AvgDialog_23361_Content_39 = {
    Text = "Non appena quelle parole furono pronunciate, un fluido nero e viscoso iniziò a trasudare incessantemente dal pavimento e dal soffitto del palco, per poi coalescere in masse contorte."
  },
  AvgDialog_23361_Content_4 = {
    Text = "Nell'anno @1, una fanciulla di campagna giunse qui in carrozza e la trasformò in una città dove le rose sbocciavano in tutto il loro splendore."
  },
  AvgDialog_23361_Content_40 = {Text = "Mmm..."},
  AvgDialog_23361_Content_41 = {
    Text = "<Change>Awoooo—!!"
  },
  AvgDialog_23361_Content_5 = {
    Text = "Fiori meravigliosi crescevano senza sosta in ogni angolo della città, diventando il nutrimento perfetto per dare vita a storie."
  },
  AvgDialog_23361_Content_6 = {
    Text = "Amore, desiderio, odio. E naturalmente, naturalmente... ciò che voi e io amiamo più di ogni altra cosa..."
  },
  AvgDialog_23361_Content_7 = {
    Text = "<Red:L'omicidio.>"
  },
  AvgDialog_23361_Content_8 = {
    Text = "Ora, accomodatevi e godetevi lo spettacolo—"
  },
  AvgDialog_23361_Content_9 = {
    Text = "Scosti la tenda cremisi scura davanti a te."
  },
  AvgDialog_23362_Content_1 = {
    Text = "Dama delle Camelie"
  },
  AvgDialog_23362_Content_10 = {
    Text = "Hai il diritto di rifiutare. Lascia quelli di Sopra a me."
  },
  AvgDialog_23362_Content_100 = {
    Text = "E poi, avete usato un secondo Risveglio per compiere una grandiosa resurrezione davanti al pubblico, massimizzando le possibilità di scagionarvi da ogni sospetto."
  },
  AvgDialog_23362_Content_101 = {
    Text = "Dopotutto, nessuno sarebbe così folle da pensare che una persona morta sia l'assassina."
  },
  AvgDialog_23362_Content_102 = {
    Text = "Ho ragione, Lady Sorel?"
  },
  AvgDialog_23362_Content_103 = {
    Text = "Hehe... La vostra deduzione è adorabile. E allora come spiegate la Figura Oscura?"
  },
  AvgDialog_23362_Content_104 = {
    Text = "Ha ucciso qualcuno sotto gli occhi di tutti. Come intendete dimostrare il mio legame con essa?"
  },
  AvgDialog_23362_Content_105 = {
    Text = "Il profumo."
  },
  AvgDialog_23362_Content_106 = {
    Text = [[
L'ultima volta che vi siete gettata su di me, l'ho percepito. Entrambe portate lo stesso profumo...
<Red:Il profumo di rose in decomposizione>.]]
  },
  AvgDialog_23362_Content_107 = {
    Text = "In realtà è una specie di tuo doppelgänger, non è vero?"
  },
  AvgDialog_23362_Content_108 = {Text = "..."},
  AvgDialog_23362_Content_109 = {
    Text = "Come ci si aspetta da un Custode: il tuo Fiuto della Bestia è piuttosto acuto."
  },
  AvgDialog_23362_Content_11 = {
    Text = "Quelli di Sopra?"
  },
  AvgDialog_23362_Content_110 = {
    Text = "Sorel si sfilò il guanto rosso dalla mano destra, e un denso fetore putrido si diffuse immediatamente nell'aria."
  },
  AvgDialog_23362_Content_111 = {
    Text = "Sotto un intreccio di graffi e cicatrici orribili, delle lettere rosso scuro emersero debolmente."
  },
  AvgDialog_23362_Content_112 = {Text = "<Red:\"N\">"},
  AvgDialog_23362_Content_113 = {
    Text = "Sorel sollevò pigramente la mano sotto il naso e la annusò delicatamente."
  },
  AvgDialog_23362_Content_114 = {
    Text = "Vedi questa? La cicatrice sul dorso della mia mano. Finché esisterà, il mio patto con <Yellow:Lui> resterà in vigore."
  },
  AvgDialog_23362_Content_115 = {
    Text = "Devo ancora continuare a istigare conflitti e creare Caos per Suo volere… Quei nobili morti erano i Sacrifici che Gli ho offerto."
  },
  AvgDialog_23362_Content_116 = {
    Text = "Ma me ne sono stancata da tempo. Gli esseri umani e la maggior parte dei Risvegliatori bramano l'ordine per natura. Solo un folle troverebbe piacere nel Caos senza fine."
  },
  AvgDialog_23362_Content_117 = {
    Text = "Il prezzo per spezzare questo patto è semplice: la <Red:Morte>."
  },
  AvgDialog_23362_Content_118 = {
    Text = "…Quindi questo è il tuo vero obiettivo fin dall'inizio."
  },
  AvgDialog_23362_Content_119 = {
    Text = [[
Esatto. I cosiddetti nobili, incluso mio padre, erano solo un contorno.
Liberarsi di loro non richiedeva di pagare il prezzo della propria vita.]]
  },
  AvgDialog_23362_Content_12 = {Text = "..."},
  AvgDialog_23362_Content_120 = {
    Text = "Lui non si mostra mai di Sua volontà. In effetti, non mi risponde da molto, molto tempo."
  },
  AvgDialog_23362_Content_121 = {
    Text = "Ci sono state innumerevoli notti in cui strisciavo in ginocchio, piangendo e supplicandoLo di liberarmi dal patto."
  },
  AvgDialog_23362_Content_122 = {
    Text = "Eppure non sentivo nulla, non vedevo nulla. Solo un silenzio mortale mi rispondeva."
  },
  AvgDialog_23362_Content_123 = {
    Text = "Quindi ho smesso di aspettare. Questa volta, spezzerò questo patto con le mie stesse mani."
  },
  AvgDialog_23362_Content_124 = {
    Text = "…Anche se mi costerà la vita."
  },
  AvgDialog_23362_Content_13 = {
    Text = "Mi dispiace, non è qualcosa che ti è permesso sapere in questo momento."
  },
  AvgDialog_23362_Content_14 = {
    Text = "Va bene, signorina Doll."
  },
  AvgDialog_23362_Content_15 = {
    Text = "Ho ancora alcuni dubbi e sospetti. Sarebbe ideale se potessi entrare nel Dominio per verificarli."
  },
  AvgDialog_23362_Content_16 = {
    Text = "Doll annuì."
  },
  AvgDialog_23362_Content_17 = {
    Text = "L'informatrice che hai incontrato nel Dominio... te la ricordi? Abbiamo mandato qualcuno a indagare sui suoi contatti a monte, e guarda un po', abbiamo avuto una bella sorpresa."
  },
  AvgDialog_23362_Content_18 = {
    Text = "E poi ci sono i fascicoli d'identità e le reti di relazioni di quei nobili deceduti..."
  },
  AvgDialog_23362_Content_19 = {
    Text = "Questo è il rapporto d'indagine appena inviato dal dipartimento di polizia. Dagli un'occhiata."
  },
  AvgDialog_23362_Content_2 = {
    Text = "Infermeria dei Mythag"
  },
  AvgDialog_23362_Content_20 = {
    Text = "Prendi il rapporto d'indagine e cominci a sfogliarlo pagina per pagina."
  },
  AvgDialog_23362_Content_21 = {Text = "?!"},
  AvgDialog_23362_Content_22 = {
    Text = "Proprio come sospettavo..."
  },
  AvgDialog_23362_Content_23 = {
    Text = "Cosa hai bisogno che faccia lì dentro?"
  },
  AvgDialog_23362_Content_24 = {
    Text = "Doll ti porge una spessa busta di documenti."
  },
  AvgDialog_23362_Content_25 = {
    Text = "<Yellow:Semplice: una negoziazione.>"
  },
  AvgDialog_23362_Content_26 = {
    Text = [[
Terzo Dominio Artificiale: Teatro Covent
Giorno della rappresentazione de "Il Nome della Rosa"]]
  },
  AvgDialog_23362_Content_27 = {
    Text = "Il magnifico canto scorreva Come Se fosse una Corrente fluttuante senza fine, fluendo lentamente nel teatro."
  },
  AvgDialog_23362_Content_28 = {
    Text = "Il pubblico in basso osservava meravigliato, dondolandosi dolcemente al ritmo della melodia, già perso nel sogno tessuto dalle note."
  },
  AvgDialog_23362_Content_29 = {
    Text = "A pensarci bene, questo spettacolo un tempo aveva un altro nome: \"La Morte della Rosa\"."
  },
  AvgDialog_23362_Content_3 = {
    Text = "Ho sentito che le cose stanno procedendo bene da parte di Ramona. E tu? Come ti senti adesso?"
  },
  AvgDialog_23362_Content_30 = {
    Text = "La protagonista è una ragazza di campagna che si fa strada da sola nella Cité. A parte il suo giovane e grazioso viso, non ha nulla."
  },
  AvgDialog_23362_Content_31 = {
    Text = "Proprio come me, a quei tempi."
  },
  AvgDialog_23362_Content_32 = {
    Text = "Ma Madame, voi siete una principessa esiliata da una terra straniera! Come potrebbe una ragazza di campagna essere paragonata a voi!"
  },
  AvgDialog_23362_Content_33 = {
    Text = "Hehe… La cosiddetta principessa straniera non è altro che una falsa messinscena. Sono una ragazza di campagna nata e cresciuta a Constan."
  },
  AvgDialog_23362_Content_34 = {
    Text = "Ah… <Big:Ah!>"
  },
  AvgDialog_23362_Content_35 = {
    Text = "<Gray:Un segreto così colossale, e Madame me l'ha rivelato così, senza pensarci!>"
  },
  AvgDialog_23362_Content_36 = {
    Text = "<Gray:Che abbia scoperto che ho dato l'invito a quella riccia, e ora voglia farmi tacere per sempre…>"
  },
  AvgDialog_23362_Content_37 = {
    Text = "\"La Morte della Rosa\" era il mio spettacolo preferito da bambina."
  },
  AvgDialog_23362_Content_38 = {
    Text = "Visite ad amici, passeggiate per riprendermi da un malanno, uscite per fare acquisti…"
  },
  AvgDialog_23362_Content_39 = {
    Text = "Ho inventato così tante scuse, solo per avere la possibilità di stare fuori dal teatro e ascoltare di nascosto per cinque minuti."
  },
  AvgDialog_23362_Content_4 = {
    Text = "Mi sento molto meglio."
  },
  AvgDialog_23362_Content_40 = {
    Text = "Perché ero troppo impegnata. Pianoforte, ricamo ed etichetta…\nDovevo imparare ogni abilità che potesse compiacere la nobiltà."
  },
  AvgDialog_23362_Content_41 = {
    Text = "Il portamento di Madame farebbe vergognare persino una principessa reale! Non è quello che dice il proverbio, ehm, Chi dorme…"
  },
  AvgDialog_23362_Content_42 = {
    Text = "Ah, no, è la fortuna aiuta chi è preparato!"
  },
  AvgDialog_23362_Content_43 = {
    Text = "<Gray:Sono davvero una sciocca. Stasera sarà probabilmente la mia fine, hehe…>"
  },
  AvgDialog_23362_Content_44 = {
    Text = "In seguito riuscii ad ascoltare l'intera opera a pezzi e bocconi, ma il finale non mi piacque."
  },
  AvgDialog_23362_Content_45 = {
    Text = "La ragazza di campagna riuscì a infiltrarsi nell'alta società della Cité, solo per innamorarsi di un giovane nobile inetto, e alla fine morì per causa sua."
  },
  AvgDialog_23362_Content_46 = {
    Text = "Che, che finale triste… Neanche a Karen piace. Karen odia le tragedie!"
  },
  AvgDialog_23362_Content_47 = {
    Text = "In effetti, a nessuno piacciono le tragedie."
  },
  AvgDialog_23362_Content_48 = {
    Text = "Dopo aver investito nel teatro, la prima cosa che feci fu cambiare il nome e il finale de \"La Morte della Rosa\"."
  },
  AvgDialog_23362_Content_49 = {
    Text = "Finalmente potevo fare tutto ciò che volevo.\nO meglio, <Yellow:credevo> di poter finalmente fare tutto ciò che volevo."
  },
  AvgDialog_23362_Content_5 = {
    Text = "Sono contenta. Sembra che quelle tecnologie mediche con cui armeggia Winkle siano effettivamente utili."
  },
  AvgDialog_23362_Content_50 = {
    Text = "Sorel fissava con sguardo assente il liquido dorato nel suo bicchiere e le bollicine che gorgogliavano dal fondo."
  },
  AvgDialog_23362_Content_51 = {
    Text = "Ricchezza, fama, conoscenza… La gente vi accorre perché, una volta che le possiedi, possiedi la libertà."
  },
  AvgDialog_23362_Content_52 = {
    Text = "La libertà di cambiare il finale di un'opera che non ti piace, o la libertà di comprare un rubino a cammeo che ti ha colpito."
  },
  AvgDialog_23362_Content_53 = {
    Text = "Gli esseri umani sono creature così semplici."
  },
  AvgDialog_23362_Content_54 = {
    Text = "Madame, perché tirare fuori tutto questo all'improvviso? È un po' pesante, ahah…"
  },
  AvgDialog_23362_Content_55 = {
    Text = "Sei sempre stata una bambina sveglia. Anche senza di me, sono certa che te la caverai benissimo."
  },
  AvgDialog_23362_Content_56 = {
    Text = "Sorel accarezzò dolcemente la testa di Karen."
  },
  AvgDialog_23362_Content_57 = {
    Text = "M-My Lady..."
  },
  AvgDialog_23362_Content_58 = {
    Text = "Lo dite perché volete abbandonare Karen..."
  },
  AvgDialog_23362_Content_59 = {
    Text = "Nessuno ti abbandonerà, Karen. Sei sempre stata libera."
  },
  AvgDialog_23362_Content_6 = {
    Text = "Non girerò intorno alla questione. %player%, potresti doverti preparare a entrare nel Dominio Artificiale ancora una volta."
  },
  AvgDialog_23362_Content_60 = {Text = "Hss..."},
  AvgDialog_23362_Content_61 = {
    Text = "Un'ombra scura si sollevò lentamente dall'angolo, scivolando silenziosamente verso la schiena di Sorel."
  },
  AvgDialog_23362_Content_62 = {
    Text = "Sorel ascoltava attentamente il canto melodioso proveniente dal palcoscenico sottostante, apparentemente del tutto ignara del movimento alle sue spalle."
  },
  AvgDialog_23362_Content_63 = {Text = "Hss..."},
  AvgDialog_23362_Content_64 = {
    Text = "I fruscii si fecero gradualmente più deboli, e la Figura Oscura si immobilizzò completamente."
  },
  AvgDialog_23362_Content_65 = {Text = "Hmm...?"},
  AvgDialog_23362_Content_66 = {
    Text = "Sorel si voltò sorpresa."
  },
  AvgDialog_23362_Content_67 = {
    Text = "Buonasera, Lady Sorel. Sembra che abbiate perso qualcosa?"
  },
  AvgDialog_23362_Content_68 = {
    Text = "<Change>Mia Signora..."
  },
  AvgDialog_23362_Content_69 = {
    Text = "La Figura Oscura sembrava nient'altro che uno straccio floscio tra le tue mani, gettato dolcemente ai piedi di Sorel."
  },
  AvgDialog_23362_Content_7 = {Text = "Cosa...?!"},
  AvgDialog_23362_Content_70 = {
    Text = "Catturare questa cosa ha richiesto un bel po' di fatica. Grazie al nostro ultimo incontro, sono finalmente riuscito a capire i suoi schemi di combattimento."
  },
  AvgDialog_23362_Content_71 = {
    Text = "<Red:Sono tornati...>"
  },
  AvgDialog_23362_Content_72 = {
    Text = "Sorel non degnò di uno sguardo la Figura Oscura ai suoi piedi. La sua espressione era grave, gli occhi fissi intensamente su di te."
  },
  AvgDialog_23362_Content_73 = {
    Text = "Ancora tu... Perché sei tornato? La lezione che il Dominio ti ha impartito l'ultima volta non è stata sufficiente?"
  },
  AvgDialog_23362_Content_74 = {
    Text = "<Gray:Miss Doll ha indovinato — si è effettivamente resa conto di trovarsi all'interno di un Dominio.>"
  },
  AvgDialog_23362_Content_75 = {
    Text = "Sono venuto solo per confermare alcune cose."
  },
  AvgDialog_23362_Content_76 = {
    Text = "Hai strappato la maschera dal volto della Figura Oscura."
  },
  AvgDialog_23362_Content_77 = {
    Text = "L'istante successivo, la Figura Oscura si dissolse come inchiostro nell'acqua."
  },
  AvgDialog_23362_Content_78 = {
    Text = "Rimase solo una rosa cremisi, adagiata silenziosamente tra te e Sorel."
  },
  AvgDialog_23362_Content_79 = {
    Text = "Uova Bianche sui petali si contorcevano delicatamente, strisciando lentamente sull'orlo del vestito di Sorel, fondendosi con lei in un tutt'uno."
  },
  AvgDialog_23362_Content_8 = {
    Text = "Doll aggrottò le sopracciglia, allungando istintivamente la mano per toccare l'apparato di vetro contenente il cervello fresco."
  },
  AvgDialog_23362_Content_80 = {Text = "..."},
  AvgDialog_23362_Content_81 = {
    Text = "Il gioco è finito, Lady Sorel."
  },
  AvgDialog_23362_Content_82 = {
    Text = "<Yellow:Registro della Terza Operazione nel Dominio Artificiale>\n\n■ Numero Dominio: M-B04-003\n■ Periodo impostato: Dopo il Diluvio 315, giugno @1, 20:00-21:00 (il giorno della morte di Sorel).\n■ Luogo impostato: Teatro Covent"
  },
  AvgDialog_23362_Content_83 = {
    Text = "\n■ Proprietaria del Dominio: Sorel @2.\n■ Infiltrato nel Dominio: %player%.\n\n■ Obiettivo dell'infiltrazione: <Yellow:Svelare la cospirazione di Sorel e avviare una negoziazione \"necessaria\".>"
  },
  AvgDialog_23362_Content_84 = {
    Text = "Ancora tu! Lady Sorel, lasci questo tizio a Karen..."
  },
  AvgDialog_23362_Content_85 = {
    Text = "Sorel scosse la testa."
  },
  AvgDialog_23362_Content_86 = {
    Text = "Fatti indietro, Karen."
  },
  AvgDialog_23362_Content_87 = {
    Text = "%player%, hai fatto irruzione qui solo per mostrarmi questo?"
  },
  AvgDialog_23362_Content_88 = {
    Text = "Lady Sorel, che aveva sempre amato la grandiosità, il giorno della sua morte venne ad ascoltare lo spettacolo accompagnata soltanto dalla sua cameriera personale."
  },
  AvgDialog_23362_Content_89 = {
    Text = "Ma che discorsi sono? È forse sbagliato che la mia signora voglia godersi un po' di musica con me in pace e tranquillità!"
  },
  AvgDialog_23362_Content_9 = {
    Text = "Non è stata una mia direttiva. Se fosse per me, vorrei che restassi qui a riposarti finché non ti sarai ripresa del tutto."
  },
  AvgDialog_23362_Content_90 = {
    Text = "Non sia precipitosa, signorina Karen. Ricorda quei mercanti su Lincoln High Street che vendevano informazioni sugli spostamenti di Sorel?"
  },
  AvgDialog_23362_Content_91 = {
    Text = "Abbiamo già indagato. <Yellow:Le informazioni in loro possesso erano state diffuse nientemeno che da lei.>"
  },
  AvgDialog_23362_Content_92 = {
    Text = "Vendere le informazioni del proprio datore di lavoro è un'infrazione grave. Scommetterei che stava agendo su ordine della sua padrona."
  },
  AvgDialog_23362_Content_93 = {Text = "!!"},
  AvgDialog_23362_Content_94 = {
    Text = "<Shake:N-Non è possibile...> È stata Karen stessa a voler guadagnare qualche soldo extra. Non ha nulla a che fare con Lady Sorel!"
  },
  AvgDialog_23362_Content_95 = {
    Text = "Come osate incastrare la mia signora in questo modo!"
  },
  AvgDialog_23362_Content_96 = {
    Text = "Ignorando le proteste di Karen, ti volti a guardare Lady Sorel."
  },
  AvgDialog_23362_Content_97 = {
    Text = [[
E quei nobili deceduti... quasi tutti avevano avuto scontri con voi su questioni politiche o interessi commerciali.
Posso ragionevolmente dedurre che...]]
  },
  AvgDialog_23362_Content_98 = {
    Text = "<Yellow:Avete orchestrato la vostra stessa morte e l'avete usata per spazzare via ogni ostacolo sul vostro cammino, compreso vostro padre.>"
  },
  AvgDialog_23362_Content_99 = {
    Text = [[
Dichiarare pubblicamente il signor Lambert come unico beneficiario del testamento serviva solo ad attirarlo a compiere un gesto disperato.
Anche se non fosse riuscito, l'arma e il movente sarebbero bastati ad attirare l'attenzione della polizia.]]
  },
  AvgDialog_23363_Content_1 = {
    Text = "Armonia Mascherata"
  },
  AvgDialog_23363_Content_10 = {
    Text = "Ricevuto. Tutto nella norma al secondo piano finora."
  },
  AvgDialog_23363_Content_11 = {
    Text = "Mancano circa venti minuti allo spettacolo... Non avendo altro da fare, andrò prima a cercare Lady Sorel."
  },
  AvgDialog_23363_Content_12 = {
    Text = "Mm, stai attento/a. Che la Chiave d'argento illumini il tuo cammino."
  },
  AvgDialog_23363_Content_13 = {
    Text = "Lo stesso spettacolo, lo stesso corridoio."
  },
  AvgDialog_23363_Content_14 = {
    Text = "Scosti la tenda del palco di lusso con gesto esperto."
  },
  AvgDialog_23363_Content_15 = {
    Text = "Accompagnata dal ricco aroma del vino e dal tintinnio dei gioielli, una figura morbida ti cade improvvisamente tra le braccia."
  },
  AvgDialog_23363_Content_16 = {
    Text = "Finalmente sei qui. Ti ho aspettato per così tanto tempo..."
  },
  AvgDialog_23363_Content_17 = {
    Text = "Sorel si aggrappa a te con affetto, il suo respiro caldo ti fa arrossire il viso."
  },
  AvgDialog_23363_Content_18 = {
    Text = "<Shake:M-Mi aspettavi?>"
  },
  AvgDialog_23363_Content_19 = {
    Text = "Già, che fine ha fatto la discussione d'affari... Eh, ma lei non è Madame Bernard?"
  },
  AvgDialog_23363_Content_2 = {
    Text = [[
Secondo Dominio Artificiale: Teatro Covent
Il Giorno della Morte di Sorel]]
  },
  AvgDialog_23363_Content_20 = {
    Text = "Ehm. Dipartimento di Polizia di Londinium, @2 Divisione Operazione, %player%."
  },
  AvgDialog_23363_Content_21 = {
    Text = "Non provarci con me.\nTutti nell'ambiente sanno che la Divisione Operazione di @2 è solo una copertura per i Mythag che operano sotto il dipartimento di polizia~"
  },
  AvgDialog_23363_Content_22 = {
    Text = "Oh cielo, mi è appena sfuggito il vostro piccolo segreto... Scusate, mi sa che ho bevuto un po' troppo."
  },
  AvgDialog_23363_Content_23 = {
    Text = "Disse Sorel, toccandosi le guance arrossate."
  },
  AvgDialog_23363_Content_24 = {
    Text = "<Gray:Come ha fatto a ubriacarsi...? L'ultima volta era perfettamente sobria.>"
  },
  AvgDialog_23363_Content_25 = {
    Text = "È lui! Madame, questo tizio è un ladro, {Male=he,Female=she} ha rubato l'invito di Karen!"
  },
  AvgDialog_23363_Content_26 = {
    Text = "Non erano già stati spediti tutti gli inviti? Come mai ce ne sono ancora in avanzo?"
  },
  AvgDialog_23363_Content_27 = {Text = "!!"},
  AvgDialog_23363_Content_28 = {
    Text = "<Shake:Ehm, in realtà... il fatto è che, ecco...>"
  },
  AvgDialog_23363_Content_29 = {
    Text = "Karen iniziò a balbettare, come una macchina inceppata."
  },
  AvgDialog_23363_Content_3 = {
    Text = "<Yellow:Registro dell'Operazione nel Secondo Dominio Artificiale Ⅱ>\n\n■ Numero Dominio: M-B04-002\n■ Periodo Impostato: Dopo il Diluvio 315, Giugno @1, 20:00-21:00 (Il Giorno della Morte di Sorel).\n■ Luogo Impostato: Teatro Covent"
  },
  AvgDialog_23363_Content_30 = {
    Text = "Scusate per l'imbarazzo, {Male=Mr.,Female=Miss} %player%.\nLa mia cameriera non ha cattive intenzioni, è solo un po' sciocca."
  },
  AvgDialog_23363_Content_31 = {
    Text = "Oggi è un giorno che merita di essere celebrato. Il teatro in cui ho investito sta mettendo in scena il mio spettacolo preferito."
  },
  AvgDialog_23363_Content_32 = {
    Text = "Mandare qualcuno proprio in un momento come questo... quei vecchi bacchettoni di Mythag l'hanno fatto apposta?"
  },
  AvgDialog_23363_Content_33 = {
    Text = "Mi scusi per il disturbo, Lady Sorel. Abbiamo ricevuto informazioni secondo cui qualcuno tenterà di assassinarla stanotte."
  },
  AvgDialog_23363_Content_34 = {
    Text = "Non è sicuro qui. La prego, venga con me."
  },
  AvgDialog_23363_Content_35 = {Text = "Rifiuto."},
  AvgDialog_23363_Content_36 = {Text = "...?"},
  AvgDialog_23363_Content_37 = {
    Text = "Sorel sorseggiò delicatamente lo champagne dal suo bicchiere, le lunghe ciglia che ondeggiavano mentre ti rivolgeva un amichevole occhiolino."
  },
  AvgDialog_23363_Content_38 = {
    Text = "Sei tu quello che hanno mandato per proteggermi, vero? Dato che ho già un piccolo Cavaliere, perché dovrei andarmene?"
  },
  AvgDialog_23363_Content_39 = {
    Text = "Purtroppo la realtà non è rosea come un libro illustrato. Un Cavaliere solitario non può salvare la Principessa—può solo portarla in salvo."
  },
  AvgDialog_23363_Content_4 = {
    Text = "■Proprietario del Dominio: Sorel @2\n■Intrusi del Dominio: %player%, Ramona\n\n■Obiettivo: <Yellow:In base ai risultati della prima intrusione nel Dominio, trovare la fonte della fluttuazione dell'Argento al primo piano>"
  },
  AvgDialog_23363_Content_40 = {
    Text = "Fuga... fuggire dove? In un posto dove i cattivi non possono trovarmi?"
  },
  AvgDialog_23363_Content_41 = {
    Text = "Si potrebbe dire così..."
  },
  AvgDialog_23363_Content_42 = {
    Text = "Pfft. Esiste davvero un posto al mondo dove i cattivi non possono trovarti? Io non ne ho mai visto uno."
  },
  AvgDialog_23363_Content_43 = {
    Text = "Direzione ore dieci e trenta, un uomo si sta avvicinando di soppiatto. Dirigiti verso l'uscita a destra, lo metteremo alle strette insieme."
  },
  AvgDialog_23363_Content_44 = {Text = "?!"},
  AvgDialog_23363_Content_45 = {
    Text = "Mi scusi, Lady Sorel. Devo uscire un momento. Torno subito."
  },
  AvgDialog_23363_Content_5 = {
    Text = "Bene, questa volta siamo venuti preparati. Abbiamo schivato l'acqua del bagno di Karen e le abbiamo persino sottratto due inviti."
  },
  AvgDialog_23363_Content_6 = {
    Text = "Che soddisfazione!"
  },
  AvgDialog_23363_Content_7 = {
    Text = "Devo dire che le tue agili schivate mi hanno fatto una bella impressione."
  },
  AvgDialog_23363_Content_8 = {
    Text = "Ehm, torniamo al punto. Attività insolite al primo piano?"
  },
  AvgDialog_23363_Content_9 = {
    Text = "Tutto tranquillo per ora. Durante il nostro ultimo ingresso nel Dominio, è stata rilevata una debole attività di Argento nella direzione delle dieci. Questa volta terrò gli occhi più aperti."
  },
  AvgDialog_23364_Content_1 = {
    Text = [[
Secondo Dominio Artificiale: Teatro Covent
Ccorridoio del Secondo Piano]]
  },
  AvgDialog_23364_Content_10 = {
    Text = "Bene. Seconda operazione di cattura del Dominio Artificiale, inizio!"
  },
  AvgDialog_23364_Content_11 = {
    Text = "Stirasti le membra e caricasti verso l'uomo."
  },
  AvgDialog_23364_Content_2 = {
    Text = "Fai attenzione. È appena dietro l'angolo qui davanti."
  },
  AvgDialog_23364_Content_3 = {
    Text = "<Small:Shh... non parlare. Lo vedo.>"
  },
  AvgDialog_23364_Content_4 = {
    Text = "L'uomo si nascondeva non lontano dai palchi, quasi fuso con le ombre alle sue spalle. A giudicare dal suo respiro torbido e affannoso, si trattava dell'Anziano."
  },
  AvgDialog_23364_Content_5 = {
    Text = "Nel momento in cui finisti di parlare, l'ombra si contorse in modo quasi impercettibile per un istante."
  },
  AvgDialog_23364_Content_6 = {
    Text = "Chi va là?!"
  },
  AvgDialog_23364_Content_7 = {
    Text = "Eri ad almeno 10 metri di distanza da lui. Non ti saresti mai aspettato di essere scoperto."
  },
  AvgDialog_23364_Content_8 = {
    Text = "Sensi acuti, mi hai risparmiato la fatica di presentarmi. Ramona, sei pronta?"
  },
  AvgDialog_23364_Content_9 = {
    Text = "Pronta a combattere in qualsiasi momento."
  },
  AvgDialog_23365_Content_1 = {Text = "Mmph—!!"},
  AvgDialog_23365_Content_10 = {
    Text = "Cos'è quello—"
  },
  AvgDialog_23365_Content_11 = {
    Text = "Quando tornasti in te, non c'era già più nessuno in vista."
  },
  AvgDialog_23365_Content_12 = {Text = "..."},
  AvgDialog_23365_Content_13 = {
    Text = "Questo tizio non è la figura oscura mascherata. Potrebbe essere un Velo d'Illusione creato dal nemico."
  },
  AvgDialog_23365_Content_14 = {
    Text = "Lo inseguirò io. Tu torna di corsa a controllare la teca di Sorel."
  },
  AvgDialog_23365_Content_15 = {
    Text = "Ricevuto. Resta in contatto in ogni momento."
  },
  AvgDialog_23365_Content_16 = {
    Text = "Dopo che Ramona si allontanò di fretta, raccogliesti l'oggetto che l'uomo aveva lanciato."
  },
  AvgDialog_23365_Content_17 = {
    Text = "Era un pugnale squisitamente affilato, con l'elsa incisa di motivi intricati ed elaborati. Sembrava piuttosto costoso."
  },
  AvgDialog_23365_Content_18 = {
    Text = "Non poteva davvero pensare di uccidere Lady Sorel con questo aggeggio, vero?"
  },
  AvgDialog_23365_Content_19 = {
    Text = "Inoltre, per un anziano, i suoi movimenti erano fin troppo agili... Un Paziente della Dissoluzione?"
  },
  AvgDialog_23365_Content_2 = {
    Text = "L'anziano fu facilmente atterrato da te. Alzò rapidamente il braccio, usando la manica per coprirsi strettamente il volto."
  },
  AvgDialog_23365_Content_20 = {
    Text = "Se fosse stato un Paziente della Dissoluzione mutato, uccidere Sorel sarebbe stato effettivamente possibile..."
  },
  AvgDialog_23365_Content_21 = {
    Text = "Ti sei grattato la testa, confuso."
  },
  AvgDialog_23365_Content_23 = {
    Text = "Lo spettacolo sta per iniziare. In ogni caso, torniamo a controllare."
  },
  AvgDialog_23365_Content_3 = {
    Text = "Parla. Chi sei? Perché hai attaccato Lady Sorel?"
  },
  AvgDialog_23365_Content_4 = {
    Text = "Interrogarmi? Heh heh... Chi credi di essere? Dimmi, chi è il tuo capo?"
  },
  AvgDialog_23365_Content_5 = {
    Text = "François o Oliver @2? Devo... *cough* parlargli."
  },
  AvgDialog_23365_Content_6 = {Text = "?!"},
  AvgDialog_23365_Content_7 = {
    Text = "L'uomo nominò senza esitazione due alti funzionari dell'ufficio, con un tono che portava un'arroganza e un'indifferenza che riusciva a malapena a reprimere."
  },
  AvgDialog_23365_Content_8 = {
    Text = "Poi alzò improvvisamente la mano e scagliò con grande forza un oggetto luminoso."
  },
  AvgDialog_23366_Content_1 = {
    Text = [[
Primo Dominio Artificiale: Lincoln High Street
Il Giorno della Morte di Sorel]]
  },
  AvgDialog_23366_Content_10 = {
    Text = "Promemoria amichevole: sono già le 18:15. Dobbiamo ancora capire come ottenere l'invito per entrare nel teatro dell'opera."
  },
  AvgDialog_23366_Content_11 = {
    Text = "Per essere precisi, l'invito per la prima di stasera de <Blue:\"Il Nome della Rosa\">."
  },
  AvgDialog_23366_Content_12 = {
    Text = "Rivolgi a Ramona un sorriso sicuro."
  },
  AvgDialog_23366_Content_13 = {
    Text = "Non preoccuparti. Ho già fatto un po' di ricognizione in anticipo. Ottenere l'invito è semplice."
  },
  AvgDialog_23366_Content_14 = {
    Text = "Seguimi, Ramona."
  },
  AvgDialog_23366_Content_2 = {Text = "Ngh...!"},
  AvgDialog_23366_Content_3 = {
    Text = "Cough... Cough..."
  },
  AvgDialog_23366_Content_4 = {
    Text = "La città brulicante si dispiega davanti a te come un rotolo di pergamena. La notte si avvicina e i lampioni si accendono uno dopo l'altro, illuminando l'abbagliante serie di insegne dei negozi lungo la strada."
  },
  AvgDialog_23366_Content_5 = {
    Text = "La gente si affretta per le strade, le risate e il fragore delle carrozze si alzano e si abbassano, intrecciandosi in una vivace sinfonia."
  },
  AvgDialog_23366_Content_6 = {
    Text = "È passato un po' dall'ultima volta che sono venuta nel Distretto Ovest. Come sempre, non è cambiato nulla!"
  },
  AvgDialog_23366_Content_7 = {
    Text = "Penso che dovremmo andare lungo Lincoln Street. C'è una pasticceria lì con le tortine più buone del mondo intero!"
  },
  AvgDialog_23366_Content_8 = {
    Text = "Chissà che sapore hanno le tortine dentro un Dominio Artificiale..."
  },
  AvgDialog_23366_Content_9 = {
    Text = "Ramona alzò il polso senza espressione per controllare l'ora."
  },
  AvgDialog_23367_Content_1 = {
    Text = "Verdetto Caduto"
  },
  AvgDialog_23367_Content_10 = {
    Text = "Heh, quella gente è avida come sempre.\nSe accettassi tutto questo, tutti questi anni di sforzi non sarebbero stati vani?"
  },
  AvgDialog_23367_Content_11 = {
    Text = "Non sarebbe proprio accettabile, vero?"
  },
  AvgDialog_23367_Content_12 = {
    Text = "Ma se rifiutate, Mythag invocherà le clausole supplementari per terminare immediatamente il secondo Risveglio e rivelare al mondo tutto ciò che avete fatto."
  },
  AvgDialog_23367_Content_13 = {
    Text = "In effetti, temo che non abbiate altra scelta, Lady Sorel."
  },
  AvgDialog_23367_Content_14 = {
    Text = "Nessun'altra scelta? Non mi conosci ancora molto bene, Custode."
  },
  AvgDialog_23367_Content_15 = {
    Text = "Rivelarlo al mondo… Dimmi, dovrei rivelare al mondo l'esistenza della Dissoluzione, o l'esistenza dei Risvegliatori?"
  },
  AvgDialog_23367_Content_16 = {
    Text = "Perché non ne scegli uno tu?"
  },
  AvgDialog_23367_Content_17 = {
    Text = "Un sorriso le gioca sulle labbra, ma i suoi occhi sono gelidi. Sai benissimo di aver offeso questa signora."
  },
  AvgDialog_23367_Content_18 = {
    Text = "Per fortuna, la sua reazione era già stata prevista da quei superiori. Ti fai coraggio e presenti i punti di discussione preparati in anticipo."
  },
  AvgDialog_23367_Content_19 = {
    Text = "Le mie scuse, Lady Sorel. Vi prego di non considerare questa negoziazione come una minaccia. Si tratta di una partnership reciprocamente vantaggiosa, e i Superiori nutrono assoluta sincerità in questa questione…"
  },
  AvgDialog_23367_Content_2 = {
    Text = "Un patto… Capisco.\nLui ti ha concesso certe abilità speciali, e in cambio, dovevi eseguire i Suoi ordini."
  },
  AvgDialog_23367_Content_20 = {
    Text = "<Red:Che noia… Ho sonno.>"
  },
  AvgDialog_23367_Content_21 = {
    Text = "La musica si era fermata a un certo punto imprecisato, e l'intero teatro dell'opera era silenzioso come una vasta tomba."
  },
  AvgDialog_23367_Content_22 = {
    Text = "Tutti gli artisti, gli Ospiti, persino Karen—tutti immobili sul posto, a fissare te e Sorel con occhi scuri e vuoti."
  },
  AvgDialog_23367_Content_23 = {Text = "…Eh?"},
  AvgDialog_23367_Content_24 = {
    Text = "Sorel appoggiò il mento sulla mano, osservando uno a uno i volti rigidi, e lasciò sfuggire un sospiro sommesso e stanco."
  },
  AvgDialog_23367_Content_25 = {
    Text = "Dal momento in cui ti sei presentata di nuovo davanti a me, sapevo che sarebbe finita così."
  },
  AvgDialog_23367_Content_26 = {
    Text = "Il peggio si è avverato…\nProbabilmente non sai nulla dell'esistenza che hai evocato, vero, Custode."
  },
  AvgDialog_23367_Content_27 = {
    Text = "La sua voce era appena un sussurro, come se temesse di disturbare la presenza di Quell'Essere."
  },
  AvgDialog_23367_Content_28 = {
    Text = "L'immagine di quella Figura Oscura che hai visto l'ultima volta nel Dominio ti attraversa la mente in un istante."
  },
  AvgDialog_23367_Content_29 = {
    Text = "L'esistenza di cui parli... potrebbe essere...?!"
  },
  AvgDialog_23367_Content_3 = {
    Text = "Non c'è da stupirsi che il tuo doppelgänger Gli somigli tanto: stavi prendendo in prestito il Suo Potere."
  },
  AvgDialog_23367_Content_30 = {
    Text = "Cercare di usare i Mythag per tenermi sotto controllo — quelli Lassù sono astuti, ma anche loro hanno delle sviste. Non hanno tenuto conto della tua esistenza."
  },
  AvgDialog_23367_Content_31 = {Text = "...Io?"},
  AvgDialog_23367_Content_32 = {
    Text = "Tum-tum. Tum-tum."
  },
  AvgDialog_23367_Content_33 = {
    Text = "Da qualche luogo lontano giunge il suono cupo di tamburi, seguito dalle note flebili e monotone di un flauto."
  },
  AvgDialog_23367_Content_34 = {
    Text = "Poi senti un canto."
  },
  AvgDialog_23367_Content_35 = {
    Text = "<RedItalic:O ribellarsi al Fato.>"
  },
  AvgDialog_23367_Content_36 = {
    Text = "Una figura nata dall'Oscurità si erge sotto i riflettori. La nebbia che le scivola sul volto si contorce come Tentacoli nerissimi, dispiegandosi lentamente al ritmo del flauto."
  },
  AvgDialog_23367_Content_37 = {
    Text = "Il suo canto è rauco e di Profanazione, e in esso percepisci un lungo, persistente pulsare — come l'eterno fluire e rifluire delle maree."
  },
  AvgDialog_23367_Content_38 = {
    Text = "<RedItalic:Sbocciate di giovinezza nel fango marcescente, vi arrampicate su liane alte e rigogliose, calpestate le masse altrettanto insignificanti.>"
  },
  AvgDialog_23367_Content_39 = {
    Text = "<RedItalic:I vostri desideri si estendono oltre ogni limite, la vostra anima è da tempo in disfacimento.>"
  },
  AvgDialog_23367_Content_4 = {
    Text = "Non sono affari tuoi, piccolo Investigatore."
  },
  AvgDialog_23367_Content_40 = {
    Text = "<RedItalic:Nel vostro roseto malato, l'ho visto. Quel massacro silenzioso…>"
  },
  AvgDialog_23367_Content_41 = {
    Text = "<Red:Sta per Iniziare.>"
  },
  AvgDialog_23367_Content_5 = {
    Text = "Ora hai La Verità che volevi. Quindi cosa intendi fare adesso?"
  },
  AvgDialog_23367_Content_6 = {
    Text = "A essere sincero, non c'è molto che io possa fare."
  },
  AvgDialog_23367_Content_7 = {
    Text = "Sto solo seguendo gli ordini, inviato qui per negoziare con voi. Queste sono le condizioni redatte dai superiori. Vi prego di esaminarle, mia signora."
  },
  AvgDialog_23367_Content_8 = {
    Text = "Consegni i documenti preparati in anticipo a Lady Sorel."
  },
  AvgDialog_23367_Content_9 = {
    Text = "Sorel scorre rapidamente le clausole fitte in bianco e nero, un sorriso beffardo che le increspa l'angolo delle labbra."
  },
  AvgDialog_23368_Content_1 = {
    Text = "Non pensare nemmeno di scappare!!"
  },
  AvgDialog_23368_Content_10 = {
    Text = "Ooohhh——!!"
  },
  AvgDialog_23368_Content_11 = {
    Text = "Scagliasti via la rosa spaventata."
  },
  AvgDialog_23368_Content_12 = {
    Text = "È piena di uova."
  },
  AvgDialog_23368_Content_13 = {Text = "…Sì."},
  AvgDialog_23368_Content_14 = {
    Text = "È una prova importante. Vai a raccoglierla."
  },
  AvgDialog_23368_Content_15 = {
    Text = "Non voglio."
  },
  AvgDialog_23368_Content_16 = {
    Text = "D'accordo. Dato che nessuna di noi vuole andare—"
  },
  AvgDialog_23368_Content_17 = {
    Text = "Ramona si voltò a guardare Dexter."
  },
  AvgDialog_23368_Content_18 = {Text = "?"},
  AvgDialog_23368_Content_19 = {
    Text = "Qualcuno mi ha chiamata la carceriera alle mie spalle. Bene, la carceriera ora ti ordina di andare a raccogliere quel fiore."
  },
  AvgDialog_23368_Content_2 = {
    Text = "Fai un passo avanti, afferri la maschera della Figura Oscura e la strappi via."
  },
  AvgDialog_23368_Content_20 = {
    Text = "Per la cronaca, non l'ho mai detto io. È stato Nicholas, quel ragazzo era ubriaco…"
  },
  AvgDialog_23368_Content_21 = {
    Text = "Ma non l'hai negato, vero?"
  },
  AvgDialog_23368_Content_22 = {Text = "..."},
  AvgDialog_23368_Content_23 = {
    Text = "Va bene, va bene, va bene. Vado a raccoglierlo."
  },
  AvgDialog_23368_Content_24 = {
    Text = "Dexter armeggiò con i suoi eleganti gemelli da polso, si arrotolò le maniche e si trascinò là con aria abbattuta."
  },
  AvgDialog_23368_Content_25 = {
    Text = "<Gray:Che sorriso terrificante... Meglio non offenderla alla leggera in futuro.>"
  },
  AvgDialog_23368_Content_26 = {
    Text = "La signorina Doll dice che il Dominio Artificiale di Lady Sorel è stato ricalibrato. Possiamo entrarci di nuovo."
  },
  AvgDialog_23368_Content_27 = {
    Text = "Allora, sei sicuro di poter catturare il colpevole questa volta?"
  },
  AvgDialog_23368_Content_28 = {
    Text = "Hai annuito dolcemente."
  },
  AvgDialog_23368_Content_29 = {
    Text = "Ho percepito un odore molto particolare… Credo di sapere come usare i Ruoli di Traphase per rintracciarlo."
  },
  AvgDialog_23368_Content_3 = {
    Text = "Con tua sorpresa, sotto la maschera non c'era il volto che ti aspettavi di vedere — per essere precisi, all'interno non c'era proprio nulla."
  },
  AvgDialog_23368_Content_4 = {
    Text = "Si dissolse come un filo di nebbia."
  },
  AvgDialog_23368_Content_5 = {
    Text = "Eh, cos'è questo?"
  },
  AvgDialog_23368_Content_6 = {
    Text = "Una rosa rosso Sangue giaceva silenziosa ai tuoi piedi."
  },
  AvgDialog_23368_Content_7 = {
    Text = "Ancora una rosa? Ho sentito che anche sulle scene dei crimini precedenti sono state trovate delle rose..."
  },
  AvgDialog_23368_Content_8 = {
    Text = "Eri immersa nei tuoi pensieri quando un formicolio pruriginoso ti si insinuò improvvisamente sulla punta delle dita."
  },
  AvgDialog_23368_Content_9 = {
    Text = "Abbassando lo sguardo, scopristi diversi vermi bianchi e grassocci che strisciavano fuori da tra i petali arrampicandosi sulla tua mano."
  },
  AvgDialog_23369_Content_1 = {Text = "Mmph—!!"},
  AvgDialog_23369_Content_10 = {
    Text = "Apri gli occhi e guarda quanta acqua abbiamo addosso. Ci hai forse dato il tempo di spiegarci?"
  },
  AvgDialog_23369_Content_11 = {
    Text = "Ehm... Lasciamo questo spiacevole malinteso nel passato! Visto che siamo tutti qui per affari, Karen dovrebbe mostrare il suo atteggiamento professionale per rispetto."
  },
  AvgDialog_23369_Content_12 = {
    Text = "Detto ciò, tese verso di voi il suo piccolo palmo paffuto."
  },
  AvgDialog_23369_Content_13 = {
    Text = "Un invito costa dieci Fang, due inviti costano venti. Non si tratta."
  },
  AvgDialog_23369_Content_14 = {
    Text = "Lo spettacolo sta per iniziare, e non vorrete mica perdervelo, a-gen-ti?"
  },
  AvgDialog_23369_Content_15 = {
    Text = "Vi passaste le dita tra i capelli bagnati, ormai annodati, e lasciaste uscire un lungo sospiro."
  },
  AvgDialog_23369_Content_16 = {
    Text = "Ramona, la mia pazienza è completamente esaurita. Che ne dici se prima le diamo una bella lezione?"
  },
  AvgDialog_23369_Content_17 = {
    Text = "...Aspetta."
  },
  AvgDialog_23369_Content_18 = {
    Text = "Signorina Karen, non è un gran problema se non andiamo a questo spettacolo."
  },
  AvgDialog_23369_Content_19 = {
    Text = "Ma se Lady Sorel scoprisse che la sua cameriera più fidata rivende di nascosto l'acqua del bagno, come pensate che la prenderebbe?"
  },
  AvgDialog_23369_Content_2 = {
    Text = "Karen è stata messa all'angolo da te nel vicolo cieco, alzando freneticamente le mani per proteggersi."
  },
  AvgDialog_23369_Content_20 = {
    Text = "N-non ho paura! Con la vostra posizione, non riuscireste mai nemmeno a vedere Lady Sorel. State bluffando!"
  },
  AvgDialog_23369_Content_21 = {
    Text = "E se anche non riuscissimo a vederla? Vado al cancello del teatro dell'opera adesso stesso e annuncio a squarciagola tutto quello che hai combinato..."
  },
  AvgDialog_23369_Content_22 = {
    Text = "<Big:Aspettate!>"
  },
  AvgDialog_23369_Content_23 = {
    Text = "Karen si alzò in fretta, frugò nel grembiule per un po', poi vi porse due inviti stropicciati."
  },
  AvgDialog_23369_Content_24 = {
    Text = [[
Ecco, prendeteli, prendeteli tutti!
Hmph, non fate altro che vessare la gente comune. Attenti a non incontrare un fantasma durante una delle vostre passeggiate notturne!]]
  },
  AvgDialog_23369_Content_25 = {
    Text = "Grazie per le gentili parole, Signorina Karen. Staremo attenti."
  },
  AvgDialog_23369_Content_26 = {
    Text = "Allungate la mano con gioia. Proprio quando le vostre dita stanno per toccare l'invito, Karen alza lentamente la mano e lo ritira."
  },
  AvgDialog_23369_Content_27 = {
    Text = "È meglio che andiate solo a guardare lo spettacolo. Non vi vengano strane idee."
  },
  AvgDialog_23369_Content_28 = {
    Text = "Se dovesse succedere qualcosa a Lady Sorel, Karen non te la farà passare liscia."
  },
  AvgDialog_23369_Content_29 = {
    Text = "<Red:E nemmeno lui.>"
  },
  AvgDialog_23369_Content_3 = {
    Text = "Non afferratemi, non afferratemi... <Big:Ahhhhh!>"
  },
  AvgDialog_23369_Content_30 = {Text = "Lui...?"},
  AvgDialog_23369_Content_31 = {
    Text = "Oh cielo, sembra che a Karen sia sfuggito qualcosa per sbaglio. Che terribile!"
  },
  AvgDialog_23369_Content_32 = {
    Text = [[
In ogni caso, fai il tuo lavoro e non fare domande che non dovresti fare.
Alla prossima, mio caro agente~]]
  },
  AvgDialog_23369_Content_33 = {
    Text = "Karen ti fa un occhiolino malizioso, poi si china a fatica per raccogliere il secchio da terra e si allontana sbuffando."
  },
  AvgDialog_23369_Content_34 = {
    Text = [[
Sala di Riposo Mythag
Dopo il Primo Dominio Artificiale]]
  },
  AvgDialog_23369_Content_35 = {
    Text = "Hai ottenuto l'invito dalla cameriera. Cosa è successo dopo?"
  },
  AvgDialog_23369_Content_36 = {
    Text = "Come ho detto prima, siamo entrati nel teatro senza problemi e abbiamo trovato Lady Sorel al secondo piano."
  },
  AvgDialog_23369_Content_37 = {
    Text = "Ma non siamo comunque riusciti a fermare l'assassino..."
  },
  AvgDialog_23369_Content_38 = {
    Text = "Aiuto... aiutatemi... mi sta divorando viva—"
  },
  AvgDialog_23369_Content_39 = {Text = "Aiutami..."},
  AvgDialog_23369_Content_4 = {
    Text = "Non ho ancora fatto niente."
  },
  AvgDialog_23369_Content_40 = {
    Text = "L'ho vista cadere dal piano superiore, insieme ai fiori e allo champagne... Questo è tutto ciò che è accaduto nel primo Dominio."
  },
  AvgDialog_23369_Content_41 = {
    Text = "La tragica fine della bella dama è davvero deplorevole. Sembra che tu stia per piangere."
  },
  AvgDialog_23369_Content_42 = {
    Text = "Va tutto bene.\nLo scopo di entrare nel Dominio è solo ricostruire la scena del crimine, così le indagini successive avranno qualche pista da seguire."
  },
  AvgDialog_23369_Content_43 = {
    Text = "Sapere di ottenere l'invito da quella cameriera dalle mani lunghe... Niente male, hai fatto qualche progresso."
  },
  AvgDialog_23369_Content_5 = {
    Text = "Tranquilla, non siamo qui per afferrarti. Abbiamo solo bisogno di un piccolo favore."
  },
  AvgDialog_23369_Content_6 = {
    Text = "Ci servono due inviti per \"Il Nome della Rosa\". Immagino che la signorina Karen ne abbia ancora qualcuno in magazzino?"
  },
  AvgDialog_23369_Content_7 = {
    Text = "Il Nome della Rosa...?"
  },
  AvgDialog_23369_Content_8 = {
    Text = "Karen abbassò le mani che teneva strette al petto, i suoi grandi occhi rotondi che guizzavano qua e là."
  },
  AvgDialog_23369_Content_9 = {
    Text = "Oh, quindi gli agenti vogliono degli inviti! Perché non l'avete detto subito!\nVenirmi addosso così, afferrando la gente... Mi avete davvero spaventata..."
  },
  AvgDialog_23370_Content_10 = {
    Text = "Ti stavi divertendo così tanto con la tua esibizione che davvero non me la sentivo di interrompere."
  },
  AvgDialog_23370_Content_11 = {
    Text = "Chiamo le squadre B-01 e A-03, circondare l'obiettivo immediatamente."
  },
  AvgDialog_23370_Content_12 = {
    Text = "Fruscii provenivano da ogni direzione della strada, seguiti da un turbinio di passi."
  },
  AvgDialog_23370_Content_13 = {
    Text = "In poco tempo, gli agenti operativi di Mythag avevano completamente circondato la Figura Oscura."
  },
  AvgDialog_23370_Content_14 = {
    Text = "Capisco, travestirsi da ubriaco per attirarmi fuori."
  },
  AvgDialog_23370_Content_15 = {
    Text = "Che bella esibizione, signor Dexter, specialmente la parte del canto."
  },
  AvgDialog_23370_Content_16 = {
    Text = "Grazie per gli applausi. Ti svelo un segreto — il mio sogno d'infanzia era diventare un famoso cantante d'opera nel Distretto Ovest..."
  },
  AvgDialog_23370_Content_17 = {
    Text = "Prima che potesse finire, la Figura Oscura si dileguò all'improvviso, muovendosi con grazia fluida, senza un attimo di esitazione."
  },
  AvgDialog_23370_Content_18 = {Text = "..."},
  AvgDialog_23370_Content_19 = {
    Text = "Non avevo finito di parlare... Prendetelo!"
  },
  AvgDialog_23370_Content_2 = {
    Text = "Dexter crollò a terra in uno stato pietoso, stringendo il bastone e tenendolo inutilmente davanti al petto."
  },
  AvgDialog_23370_Content_3 = {
    Text = "Questo— signore, credo ci sia un piccolo malinteso tra noi..."
  },
  AvgDialog_23370_Content_4 = {
    Text = "Oh, quale malinteso? Inventane uno e fammelo sentire."
  },
  AvgDialog_23370_Content_5 = {
    Text = "La Figura Oscura si chinò, con la maschera a meno di un centimetro dalla punta del naso di Dexter."
  },
  AvgDialog_23370_Content_6 = {
    Text = "Ugh! N-Non c'è bisogno di avvicinarsi così tanto..."
  },
  AvgDialog_23370_Content_7 = {
    Text = "A Dexter si rizzarono i capelli in testa, e improvvisamente girò la testa urlando verso l'angolo dietro di sé."
  },
  AvgDialog_23370_Content_8 = {
    Text = "<Big:Voi là, vi siete goduti abbastanza lo spettacolo?!>"
  },
  AvgDialog_23370_Content_9 = {Text = "?!"},
  AvgDialog_23371_Content_1 = {
    Text = "Conduci Ramona in un vicolo appartato, gustando una fetta di torta lungo il cammino."
  },
  AvgDialog_23371_Content_10 = {
    Text = "Ah, che fragranza delicata! <Shake:Mi sento quasi mancare il respiro…>"
  },
  AvgDialog_23371_Content_11 = {
    Text = "Cosa significa questo, anche il mio ventaglio è un'edizione limitata che Lady Sorel ha portato da Remouahe!"
  },
  AvgDialog_23371_Content_12 = {
    Text = "Guardate, ha persino l'Occhio del Faraone incastonato!"
  },
  AvgDialog_23371_Content_13 = {
    Text = "Hahaha, hai mai visto com'è fatto davvero l'occhio di un Faraone? <Shake:Attenta a non beccarti una Maledizione~>"
  },
  AvgDialog_23371_Content_14 = {
    Text = "C-cosa intendi?! Stai mettendo in dubbio il gusto di Lady Sorel?"
  },
  AvgDialog_23371_Content_15 = {Text = "...?"},
  AvgDialog_23371_Content_16 = {
    Text = "Cosa stanno facendo queste persone?"
  },
  AvgDialog_23371_Content_17 = {
    Text = "Ehm… Silenzio, tutti silenzio! Il momento emozionante sta per arrivare!"
  },
  AvgDialog_23371_Content_18 = {
    Text = "Ora, permettetemi di presentare il nostro pezzo forte! Ed è—"
  },
  AvgDialog_23371_Content_19 = {
    Text = "<Big:L'acqua del bagno di Lady Sorel di appena la scorsa settimana!>"
  },
  AvgDialog_23371_Content_2 = {
    Text = "*Gnam gnam*... Mmm, questa tortina ha esattamente lo stesso sapore di quelle nella vita reale!\nRamona, perché non ne assaggi un po' anche tu?"
  },
  AvgDialog_23371_Content_3 = {
    Text = "Avvicini la tortina alle labbra di Ramona. Ramona sospira e ne prende un piccolo morso con riluttanza."
  },
  AvgDialog_23371_Content_4 = {
    Text = "Mm... Non male."
  },
  AvgDialog_23371_Content_5 = {
    Text = "*Ehm*, torniamo al dunque. Non dovevi portarmi a cercare l'invito?"
  },
  AvgDialog_23371_Content_6 = {
    Text = "Tranquilla, l'invito non scappa. È stato Hannah a insegnarmi questo metodo: la maggior parte delle persone non ci penserebbe mai."
  },
  AvgDialog_23371_Content_7 = {
    Text = "Guarda, laggiù."
  },
  AvgDialog_23371_Content_8 = {
    Text = "Indichi la fine del vicolo. Una folla si è radunata lì, chiacchierando ad alta voce e agitando le braccia con entusiasmo, in un'atmosfera festosa e vivace."
  },
  AvgDialog_23371_Content_9 = {
    Text = "Eheh, queste calze di nylon sono un'esclusiva della \"Guida della Dama\"! Ho sentito che Lady Sorel le ha comprate tutte, quindi non sono disponibili sul mercato..."
  },
  AvgDialog_23372_Content_1 = {
    Text = "Festa cremisi e oro"
  },
  AvgDialog_23372_Content_10 = {
    Text = "\"È ottenere un invito a 'Il Nome della Rosa'.\""
  },
  AvgDialog_23372_Content_11 = {
    Text = [[
Aspetta, smettila di leggere il Giornale.
Sono un cittadino di Londinium anch'io. Non conosco meno pettegolezzi di te.]]
  },
  AvgDialog_23372_Content_12 = {
    Text = "Ehm, quasi dimenticavo che una certa persona si alza presto ogni mattina per bere tè e leggere il Giornale, vivendo come una vecchietta nonostante sia così giovane."
  },
  AvgDialog_23372_Content_13 = {
    Text = "Tenersi aggiornati sugli affari mondiali e sulle notizie è molto utile anche per il lavoro investigativo."
  },
  AvgDialog_23372_Content_14 = {
    Text = "Visto che è tutto per lavoro… allora torniamo al lavoro."
  },
  AvgDialog_23372_Content_15 = {
    Text = "Lo spettacolo è domani. Perché dovevamo venire un giorno prima? La mia fragile forza mentale è già sull'orlo del collasso…"
  },
  AvgDialog_23372_Content_16 = {
    Text = "Dexter mi ha detto che Sorel è una Donna che ama la grandiosità. Spesso prenota l'intero secondo piano del teatro per il Suo divertimento e quello delle Sue amiche."
  },
  AvgDialog_23372_Content_17 = {
    Text = "Quindi il palco in cui appare non è mai fisso — naturalmente, ci sono anche considerazioni di sicurezza in gioco."
  },
  AvgDialog_23372_Content_18 = {
    Text = "Capisco.\nMa l'assassino sembrava molto sicuro della Sua posizione… Qualcuno vicino a Sorel potrebbe aver fatto trapelare l'informazione?"
  },
  AvgDialog_23372_Content_19 = {
    Text = "Mentre dicevi questo, l'immagine di Karen ti è affiorata nella mente."
  },
  AvgDialog_23372_Content_2 = {
    Text = [[
Secondo Dominio Artificiale: Lincoln High Street
Il giorno prima della morte di Sorel]]
  },
  AvgDialog_23372_Content_20 = {
    Text = "Quella Cameriera chiacchierona è molto sospetta…"
  },
  AvgDialog_23372_Content_21 = {Text = "BANG!!"},
  AvgDialog_23372_Content_22 = {
    Text = "Un passante ti ha urtato improvvisamente la spalla. Hai aggrottato le sopracciglia e ti sei voltata, ma il tuo polso è stato afferrato con forza."
  },
  AvgDialog_23372_Content_23 = {
    Text = "<SmallShake:Ehi, ho notato che stai davanti al poster di Lady Sorel da un bel po'. Devi essere una delle Sue ammiratrici, vero?>"
  },
  AvgDialog_23372_Content_24 = {
    Text = "<SmallShake:Vendo a basso prezzo il numero del palco di Lady Sorel per stasera, e anche il corridoio che percorrerà quando se ne andrà…>"
  },
  AvgDialog_23372_Content_25 = {
    Text = "<SmallShake:Vuoi vedere la dea da vicino? Stasera è il momento perfetto — non lasciarti sfuggire questa occasione!>"
  },
  AvgDialog_23372_Content_26 = {Text = "...?"},
  AvgDialog_23372_Content_27 = {
    Text = "Sapevo che Sorel era popolare, ma non avrei mai immaginato che si fosse arrivati a questo punto…"
  },
  AvgDialog_23372_Content_28 = {
    Text = "Ho solo una domanda: è davvero necessario tutto questo?"
  },
  AvgDialog_23372_Content_29 = {
    Text = "Tch, quindi non sei qui per quello, dopotutto.\nSmettila di bloccare il passaggio, questo è il punto d'incontro abituale per noi ammiratori di Sorel..."
  },
  AvgDialog_23372_Content_3 = {
    Text = "<Yellow:Registro dell'Operazione nel Secondo Dominio Artificiale Ⅰ>\n\n■ Numero Dominio: M-B04-002\n■ Periodo impostato: Dopo il Diluvio 315, giugno @1, 14:00-18:00 (il giorno prima della morte di Sorel).\n■ Luogo impostato: Lincoln High Street"
  },
  AvgDialog_23372_Content_30 = {
    Text = "Aspetta, chi ti ha passato le informazioni su Sorel? Dimmelo e ti pagherò il doppio."
  },
  AvgDialog_23372_Content_31 = {
    Text = "Come ci si aspettava da Ramona, sempre perspicace."
  },
  AvgDialog_23372_Content_32 = {
    Text = "Eh...? P-perché ti interessa così tanto! Non sarai mica della polizia?"
  },
  AvgDialog_23372_Content_33 = {
    Text = "In mezzo al trambusto, una carrozza sfarzosa si è fermata lentamente davanti a voi."
  },
  AvgDialog_23372_Content_34 = {
    Text = "Una mano pallida e sottile, adornata da anelli ingioiellati, si protende stringendo una mazzetta di Rosa dorata."
  },
  AvgDialog_23372_Content_35 = {
    Text = "*Coff coff*... Comprerò le tue informazioni, ragazzina."
  },
  AvgDialog_23372_Content_36 = {
    Text = "Una voce anziana e singolare proveniva dall'interno della carrozza. Il suo proprietario sembrava gravemente malato, tossiva incessantemente, come un mantice logoro che avrebbe dovuto essere riparato da tempo."
  },
  AvgDialog_23372_Content_37 = {
    Text = "Wow! T-tutti questi soldi? Tutti per me?"
  },
  AvgDialog_23372_Content_38 = {
    Text = "La persona all'interno della carrozza sembrava alquanto impaziente e fece il gesto di ritirare la mano."
  },
  AvgDialog_23372_Content_39 = {
    Text = "La ragazza spinse frettolosamente un bigliettino verso di lui, poi afferrò i buoni d'oro a tutta velocità, sorridendo così tanto che gli occhi le si strinsero in due fessure sottili."
  },
  AvgDialog_23372_Content_4 = {
    Text = "■Proprietario del Dominio: Sorel @2\n■Intrusi nel Dominio: %player%, Ramona\n\n■Obiettivo: <Yellow:Indagare nei dintorni del teatro per trovare ulteriori indizi.>"
  },
  AvgDialog_23372_Content_40 = {
    Text = "Ecco le informazioni che volevate! Nobilissimo e generosissimo signore, che possiate guarire presto e vivere cent'anni!"
  },
  AvgDialog_23372_Content_41 = {
    Text = "Prima che la ragazza potesse finire di parlare, la carrozza si allontanò rapidamente."
  },
  AvgDialog_23372_Content_42 = {
    Text = "Quel vecchio signore non sembra un ammiratore di Sorel. Seguiamolo."
  },
  AvgDialog_23372_Content_5 = {
    Text = "Nelle strade animate, pedoni e carrozze trainate da cavalli si intrecciavano avanti e indietro, con un'atmosfera festosa che permeava l'aria."
  },
  AvgDialog_23372_Content_6 = {
    Text = "Mancando solo un giorno allo spettacolo d'opera, i manifesti dello spettacolo erano già stati affissi in ogni strada e vicolo."
  },
  AvgDialog_23372_Content_7 = {
    Text = "Curiosamente, Lady Sorel, nella sua Identità di azionista del teatro, dominava la stragrande maggioranza dello spazio sui manifesti. A nessuno importava davvero di cosa trattasse lo spettacolo."
  },
  AvgDialog_23372_Content_8 = {
    Text = "\"'Il Nome della Rosa' fu la prima opera rappresentata dopo che Lady Sorel investì nel <Blue:Teatro Covent>.\""
  },
  AvgDialog_23372_Content_9 = {
    Text = "\"Al giorno d'oggi, il segno di appartenenza all'alta società non è indossare sete provenienti dall'Oriente, né possedere un antico vaso di ceramica proveniente da Remouahe...\""
  },
  AvgDialog_23841_Content_1 = {
    Text = "Mandasti via il conducente—molti rinforzi nemici?"
  },
  AvgDialog_23841_Content_10 = {
    Text = "Il loro assalto era deliberato—per intrappolarci qui al Terzo Molo, Ormeggio 2."
  },
  AvgDialog_23841_Content_11 = {
    Text = "Ma questo posto sembra ordinario..."
  },
  AvgDialog_23841_Content_12 = {
    Text = "Vero, l'Ormeggio 2 non ha alcun significato."
  },
  AvgDialog_23841_Content_13 = {
    Text = "Il problema è la <Yellow:nave> attraccata qui."
  },
  AvgDialog_23841_Content_14 = {Text = "Una nave?"},
  AvgDialog_23841_Content_15 = {
    Text = "Le parole di Ramona scatenarono una tempesta, disperdendo la nebbia nella tua mente."
  },
  AvgDialog_23841_Content_16 = {Text = "!"},
  AvgDialog_23841_Content_17 = {
    Text = "Un vascello colossale si materializzò alle tue spalle, eclissando la luna, avvolgendo ogni cosa nell'ombra."
  },
  AvgDialog_23841_Content_18 = {
    Text = "Dopo la manifestazione, gli uomini-pesce che vi accerchiavano eruppero in applausi, poi esibirono un comportamento bizzarro."
  },
  AvgDialog_23841_Content_19 = {
    Text = "Guardateli!"
  },
  AvgDialog_23841_Content_2 = {
    Text = "Troppi; la ritirata è tagliata."
  },
  AvgDialog_23841_Content_20 = {
    Text = "Gli uomini-pesce formarono una fila, balzando verso la nave come opossum suicidi incuranti della vita."
  },
  AvgDialog_23841_Content_21 = {
    Text = "Ancora più strano, quando le mani palmate si avvicinavano allo scafo, una tenue fluorescenza si increspava, respingendo ogni arrembante in acqua."
  },
  AvgDialog_23841_Content_22 = {
    Text = "Questa nave... sta respingendo gli uomini-pesce?"
  },
  AvgDialog_23841_Content_23 = {
    Text = "Lo scafo esterno era arrugginito e sbiadito, le iscrizioni originali illeggibili, il nome in vernice bianca a malapena distinguibile."
  },
  AvgDialog_23841_Content_24 = {Text = "Sona..."},
  AvgDialog_23841_Content_25 = {
    Text = [[
<Blue:Sona-Nyl>.
Erica, ci sono registrazioni nei Mythag?]]
  },
  AvgDialog_23841_Content_26 = {
    Text = "Sona-Nyl, già della <Blue:Black Star Shipping>, nave passeggeri per rotte transoceaniche."
  },
  AvgDialog_23841_Content_27 = {
    Text = "Dopo il fallimento della Black Star, acquisita anonimamente da privati, reimmatricolata e convertita a cargo."
  },
  AvgDialog_23841_Content_28 = {
    Text = "William, conosci questa nave?"
  },
  AvgDialog_23841_Content_29 = {
    Text = "Nel 288 D.F., la Sona-Nyl affondò in una tempesta. Anni dopo, le coste del Mare del Nord segnalarono avvistamenti di una \"<Blue:nave fantasma>\"."
  },
  AvgDialog_23841_Content_3 = {
    Text = "Onde increspate al chiaro di luna; negli angoli bui, chi sapeva quanti se ne celavano."
  },
  AvgDialog_23841_Content_30 = {
    Text = "Un investigatore Mythag salì a bordo una volta, ma non riportò alcuna informazione utilizzabile."
  },
  AvgDialog_23841_Content_31 = {
    Text = "Nessuna informazione utilizzabile..."
  },
  AvgDialog_23841_Content_32 = {
    Text = "Ma è tornato sano e salvo al campus, giusto?"
  },
  AvgDialog_23841_Content_33 = {
    Text = "Sì, a parte le lacune nella memoria, nessun'altra anomalia.\nBreve convalescenza, poi di nuovo in prima linea."
  },
  AvgDialog_23841_Content_34 = {
    Text = "Possiamo metterlo in collegamento?"
  },
  AvgDialog_23841_Content_35 = {
    Text = "...Purtroppo, no.\nÈ perito in una missione prima che tu entrassi a Mythag."
  },
  AvgDialog_23841_Content_36 = {
    Text = "Aspetta! Ramona, non vorrai dire che..."
  },
  AvgDialog_23841_Content_37 = {
    Text = "Sì, non ci lasceranno attendere i soccorsi."
  },
  AvgDialog_23841_Content_38 = {
    Text = "Gli uomini-pesce puntarono le armi verso di voi, cessando di assaltare la Sona-Nyl. Il cerchio si strinse; tu e Ramona indietreggiaste contro lo scafo."
  },
  AvgDialog_23841_Content_39 = {
    Text = "Ramona inspirò profondamente, toccando la passerella abbassata."
  },
  AvgDialog_23841_Content_4 = {
    Text = "Indietro @2—! @1! Ordine @1!"
  },
  AvgDialog_23841_Content_40 = {
    Text = [[
A differenza degli uomini-pesce respinti, le sue dita incontrarono lo scafo solido.
Vi scambiaste uno sguardo e premeste la mano sulla nave.]]
  },
  AvgDialog_23841_Content_41 = {
    Text = "Una lieve resistenza arrestò la vostra mano a mezz'aria, poi svanì; il gelo dell'acciaio penetrò il guanto, intorpidendovi il cuoio capelluto."
  },
  AvgDialog_23841_Content_42 = {
    Text = "La Sona-Nyl <Yellow:vi accetta>."
  },
  AvgDialog_23841_Content_43 = {
    Text = "Saliamo a bordo."
  },
  AvgDialog_23841_Content_5 = {
    Text = "Stringendo il cappio attorno a un certo ormeggio, gli uomini-pesce arrestarono la loro avanzata, mormorando un incomprensibile farfugliamento in uno stallo."
  },
  AvgDialog_23841_Content_6 = {
    Text = "Perché non attaccano?"
  },
  AvgDialog_23841_Content_7 = {Text = "..."},
  AvgDialog_23841_Content_8 = {
    Text = "Ramona, cos'è?"
  },
  AvgDialog_23841_Content_9 = {
    Text = "Dal sospingerci a nord al sigillare l'uscita, hanno sempre lasciato un sentiero."
  },
  AvgDialog_23842_Content_1 = {
    Text = "Il Capitano mi ha parlato di un rifugio dietro quella porta."
  },
  AvgDialog_23842_Content_10 = {
    Text = "Questo moccioso burbero con la corona è Tulu, e l'altro si chiama..."
  },
  AvgDialog_23842_Content_11 = {Text = "..."},
  AvgDialog_23842_Content_12 = {
    Text = "Io, ehm... non ti ho mai chiesto il nome..."
  },
  AvgDialog_23842_Content_13 = {
    Text = "Murphy si grattò la testa con aria imbarazzata, nascondendosi dietro il Capitano e lasciando la presentazione imbarazzante all'unico adulto presente."
  },
  AvgDialog_23842_Content_14 = {
    Text = "Sono %player%, uno studente dell'Università di Mythag."
  },
  AvgDialog_23842_Content_15 = {
    Text = "Lei è il Capitano, giusto? Dai nostri archivi risulta che un ex studente della nostra scuola si sia imbarcato sulla Sona-Nyl."
  },
  AvgDialog_23842_Content_16 = {
    Text = "Il Capitano estrasse un portasigarette dalla borsa, pizzicando l'ultimo residuo di tabacco, ma Murphy gli diede un leggero colpetto sulla mano."
  },
  AvgDialog_23842_Content_17 = {
    Text = "Non mi avevi promesso che avresti smesso di fumare?"
  },
  AvgDialog_23842_Content_18 = {
    Text = "Il Capitano abbozzò un sorriso amaro e ripose il portasigarette in tasca."
  },
  AvgDialog_23842_Content_19 = {
    Text = [[
Riconosco quell'uniforme. Peccato che non sia il momento migliore.
Se tornaste un altro giorno, vi offrirei da bere e potremmo fare una chiacchierata come si deve.]]
  },
  AvgDialog_23842_Content_2 = {
    Text = "Qual era la sequenza che avevamo concordato... tre leggeri, uno forte? Leggero leggero forte leggero?"
  },
  AvgDialog_23842_Content_20 = {
    Text = "Elton. Mi chiamo Elton."
  },
  AvgDialog_23842_Content_21 = {
    Text = "Mentre vi presentavate, Murphy vagava per la cabina in penombra. Quando riapparve nel vostro campo visivo, il suo volto era segnato dalla Confusione."
  },
  AvgDialog_23842_Content_22 = {
    Text = "Capitano, Celeste non è con te?"
  },
  AvgDialog_23842_Content_3 = {Text = "—Aaah!"},
  AvgDialog_23842_Content_4 = {
    Text = "Mentre Murphy si spremeva le meningi per ricordare il segnale, madida di sudore per l'urgenza, la porta si spalancò dall'interno. Una mano la afferrò e la trascinò dentro."
  },
  AvgDialog_23842_Content_5 = {
    Text = "Tulu puntellò rapidamente la porta per tenerla aperta. Vi scambiaste uno sguardo e scivolaste dentro insieme."
  },
  AvgDialog_23842_Content_6 = {
    Text = "C-Capitano! Grazie al cielo, sei qui ad aspettarmi..."
  },
  AvgDialog_23842_Content_7 = {
    Text = "Un uomo di mezza età dalla pelle scura, vestito con un'uniforme da marinaio, accarezzò la testa di Murphy con un gesto affettuoso."
  },
  AvgDialog_23842_Content_8 = {
    Text = "Mantenere la parola data è qualcosa a cui gli adulti devono attenersi."
  },
  AvgDialog_23842_Content_9 = {
    Text = "Allora, mi presenti i tuoi amici?"
  },
  AvgDialog_23843_Content_10 = {
    Text = "Ramona, attenta!"
  },
  AvgDialog_23843_Content_11 = {
    Text = "Estraesti la tua Chiave d'Argento, tentando di creare un legame e sopprimere il ragazzo Risvegliato in preda all'eruzione di potere."
  },
  AvgDialog_23843_Content_12 = {
    Text = "Ma percepisti l'anomalia all'istante: la sua mente era del tutto stabile, ancorata da una catena serpentina a qualcosa nelle vicinanze."
  },
  AvgDialog_23843_Content_13 = {
    Text = "—Al suo Connettore."
  },
  AvgDialog_23843_Content_14 = {
    Text = "Un'ombra contorta strisciò fuori dall'orda dei Navigatori, abbattendosi come un fulmine sulla mano che stringeva la Chiave d'Argento. La forza dell'impatto ti scaraventò contro la ringhiera."
  },
  AvgDialog_23843_Content_15 = {
    Text = "Caecus, basta così."
  },
  AvgDialog_23843_Content_16 = {
    Text = "S-Signora Miryam! Datemi un'altra possibilità — mi occuperò io di questi due."
  },
  AvgDialog_23843_Content_17 = {
    Text = "La donna coronata di spine gli rivolse uno sguardo, in silenzio. I suoi occhi si spostarono su Ramona, poi su di te, soffermandosi infine sulla Chiave d'Argento che brillava debolmente sul tuo petto."
  },
  AvgDialog_23843_Content_18 = {
    Text = "Una Chiave d'Argento..."
  },
  AvgDialog_23843_Content_19 = {
    Text = "L'istante successivo, un'ombra serpentina guizzò da sotto il suo velo, avvolgendosi attorno al tuo corpo."
  },
  AvgDialog_23843_Content_2 = {
    Text = "Ugh...! Semplici umani inferiori — come possono essere così tenaci..."
  },
  AvgDialog_23843_Content_20 = {
    Text = "Era davvero un \"serpente\" — un costrutto di energia violacea che ti stringeva saldamente il polso, le sue zanne minacciose protese verso di te in modo sinistro —"
  },
  AvgDialog_23843_Content_22 = {
    Text = "Giù le mani da {Male=lui,Female=lei}!"
  },
  AvgDialog_23843_Content_23 = {
    Text = "Ramona si voltò di scatto e scagliò il suo stocco, frantumando un'ombra-serpente che ti stava puntando."
  },
  AvgDialog_23843_Content_24 = {
    Text = "L'istante dopo, le sue gambe esplosero con una forza sorprendente. Balzò oltre i due come se volasse, raggiungendoti in un lampo. Ti afferrò trascinandoti in una rotolata, schivando il rinnovato assalto dell'ombra-serpente mentre sguainava la sua arma."
  },
  AvgDialog_23843_Content_25 = {
    Text = "Non siamo alla pari con quella donna — raggiungi la scialuppa!"
  },
  AvgDialog_23843_Content_26 = {
    Text = "Ramona non ti diede modo di ribattere, spingendoti dentro la scialuppa di salvataggio."
  },
  AvgDialog_23843_Content_27 = {
    Text = "Saltò sulla murata, ginocchia piegate per l'equilibrio, poi sferrò un fendente laterale con precisione.\nIl meccanismo di fissaggio della scialuppa si frantumò, e un'enorme ondata di assenza di gravità invase la tua mente."
  },
  AvgDialog_23843_Content_28 = {
    Text = "<Big:Ramona!>"
  },
  AvgDialog_23843_Content_29 = {
    Text = "Ramona penzolava per metà fuori dalla nave. Un'ombra-serpente le afferrò la caviglia, trascinandola indietro oltre la ringhiera."
  },
  AvgDialog_23843_Content_3 = {
    Text = "Il ragazzo fissò incredulo, gli occhi spalancati. Nella mischia, la raffica di colpi di spada di Ramona gli aveva ferito pinne e coda. Sangue grigio-rossastro scorreva copioso sul ponte, infiltrandosi tra le assi."
  },
  AvgDialog_23843_Content_30 = {
    Text = "La scialuppa si capovolse nella discesa. Oscurità e acqua marina gelida fino alle ossa ti inondarono la gola."
  },
  AvgDialog_23843_Content_31 = {
    Text = "Nel tuo ultimo sguardo, Ramona tese la mano verso di te."
  },
  AvgDialog_23843_Content_32 = {
    Text = "Ramona si accasciò sul ponte, massaggiandosi la caviglia con la fronte aggrottata."
  },
  AvgDialog_23843_Content_33 = {Text = "Crack—"},
  AvgDialog_23843_Content_34 = {
    Text = "Strinse i denti e rimise a posto l'articolazione lussata con uno scatto. Il suo volto si contrasse per un istante, prima di riprendere la consueta compostezza."
  },
  AvgDialog_23843_Content_35 = {
    Text = "La donna, con il portamento di una leader, avanzò a grandi passi verso Ramona e la guardò dall'alto in basso."
  },
  AvgDialog_23843_Content_36 = {
    Text = "Chiave d'Argento, Legame, Risvegliatore..."
  },
  AvgDialog_23843_Content_37 = {
    Text = "Ho ignorato le vostre apparizioni al porto. Ora è chiaro: la profezia del <Yellow:Nostro Signore> si avvera. Nessuno può arrestare l'allineamento delle stelle. Tutto in questo mondo mortale procede dove deve."
  },
  AvgDialog_23843_Content_38 = {
    Text = "Il porto... Sei tu che hai ordinato a questi Navigatori di inseguirci, usandoci per violare il confine del Dominio della nave."
  },
  AvgDialog_23843_Content_39 = {
    Text = "Miryam non oppose alcuna smentita; un sorriso devoto le illuminava il volto elegante."
  },
  AvgDialog_23843_Content_4 = {
    Text = "Si appoggiò alla sua arma per restare in piedi, chiaramente incapace di parare oltre i vostri attacchi."
  },
  AvgDialog_23843_Content_40 = {
    Text = "Studenti dell'Università di Mythag... come nutrimento per il <Yellow:Nostro Signore>, nessuno potrebbe essere più adatto."
  },
  AvgDialog_23843_Content_41 = {
    Text = "Miryam voltò le spalle a Ramona, incurante dell'arma ancora stretta nella sua mano. Sembrava assolutamente sicura di sé, come se la resistenza di Ramona fosse cessata."
  },
  AvgDialog_23843_Content_42 = {
    Text = "O meglio, era certa che non avrebbe costituito alcuna minaccia."
  },
  AvgDialog_23843_Content_43 = {
    Text = "Questa è la tua ultima possibilità, Caecus.\nPortala sotto. Proteggila bene."
  },
  AvgDialog_23843_Content_44 = {
    Text = "Sarà l'ultimo tassello del rito. Quando il <Yellow:Nostro Signore> rinascerà, divorerà la dolce carne del folle."
  },
  AvgDialog_23843_Content_45 = {
    Text = "<Yellow:Egli> farà risorgere la nostra città dal mare, restituirà il nostro regno a questo mondo caotico, forgiando un nuovo futuro per i Navigatori."
  },
  AvgDialog_23843_Content_5 = {
    Text = "Sei diverso da quei mostri dalla testa di pesce. E il tuo potere..."
  },
  AvgDialog_23843_Content_6 = {
    Text = "Ramona fece fiorire la spada in un gesto ampio, la punta tracciò un arco aggraziato eppure letale, puntando dritta verso il ragazzo inginocchiato."
  },
  AvgDialog_23843_Content_7 = {
    Text = "Sei un Risvegliatore... giusto?"
  },
  AvgDialog_23843_Content_8 = {
    Text = "Insolente! Il nostro sangue è di gran lunga superiore a voi miserabili umani — non avete alcun diritto di chiamare mostri i Navigatori!"
  },
  AvgDialog_23843_Content_9 = {
    Text = "Le parole di Ramona colpirono i nervi del ragazzo. Un'ondata di potere lo pervase, le spine dorsali si drizzarono mentre deviava la spada con un colpo."
  },
  AvgDialog_23844_Content_1 = {
    Text = "I tentacoli si abbatterono con violenza. Il corpo del Navigatore si sgretolò in frammenti, eppure miracolosamente risparmiò il punto in cui si trovava la bambina."
  },
  AvgDialog_23844_Content_10 = {
    Text = "Ah! A proposito di riti... Ti hanno fatto del male, signorina? Ti stringi il polso — è una distorsione?"
  },
  AvgDialog_23844_Content_11 = {
    Text = "Non sono una semplice bambina; ho un nome."
  },
  AvgDialog_23844_Content_12 = {
    Text = "Murphy. Chiamami Murphy."
  },
  AvgDialog_23844_Content_13 = {
    Text = "Murphy, ho seguito un addestramento di primo soccorso. Ti dispiace se ti controllo la mano?"
  },
  AvgDialog_23844_Content_14 = {
    Text = "La bambina ti osservò esitante, ma alla fine permise il tuo avvicinarsi, porgendo una mano."
  },
  AvgDialog_23844_Content_15 = {
    Text = "Le prendesti delicatamente la mano, sollevandole la manica. Indossava pesanti abiti invernali. A parte un lieve arrossamento dovuto agli strattoni, non mostrava altre ferite."
  },
  AvgDialog_23844_Content_16 = {
    Text = "Probabilmente una distorsione lieve. Qualche giorno di riposo e passerà."
  },
  AvgDialog_23844_Content_17 = {
    Text = "Avvertendo che l'umore di Murphy si distendeva leggermente, tralasciasti la ferita e le afferrasti d'improvviso il braccio con decisione."
  },
  AvgDialog_23844_Content_18 = {
    Text = "Che cosa stai facendo?!"
  },
  AvgDialog_23844_Content_19 = {
    Text = [[
Conosci Miryam, la leader dei Navigatori, eppure ti stanno dando la caccia.
Murphy, chi sei davvero?]]
  },
  AvgDialog_23844_Content_2 = {
    Text = "Tulu raccolse i propri arti, osservando la poltiglia grigio-verde e rosso-bianca che li ricopriva. Un lampo di disgusto gli attraversò il volto, svanendo mentre si detergeva discretamente la lordura sul ponte."
  },
  AvgDialog_23844_Content_20 = {
    Text = "Io... Io..."
  },
  AvgDialog_23844_Content_21 = {
    Text = "Fu in quel momento che Tulu terminò di esaminare le rune e si unì alla conversazione."
  },
  AvgDialog_23844_Content_22 = {
    Text = "Quella runa è un rito ipnotico dei Navigatori. Quei tizi volevano farla addormentare per evitare complicazioni..."
  },
  AvgDialog_23844_Content_23 = {
    Text = "Prima che Tulu finisse, il volto di Murphy divenne cinereo. I calci e i morsi con cui si divincolava cessarono, come se stesse riflettendo su qualcosa."
  },
  AvgDialog_23844_Content_24 = {Text = "Murphy?"},
  AvgDialog_23844_Content_25 = {Text = "—Thud!"},
  AvgDialog_23844_Content_26 = {
    Text = "Un dolore lancinante ti colpì la fronte. L'impatto fece roteare il mondo intorno a te. Murphy colse l'occasione per liberarsi, stringendosi la testa tra le mani mentre fuggiva nelle profondità della cabina."
  },
  AvgDialog_23844_Content_27 = {
    Text = "Lo sapevo che non eravate brava gente!!"
  },
  AvgDialog_23844_Content_28 = {
    Text = "A-aspetta... ascoltami..."
  },
  AvgDialog_23844_Content_29 = {
    Text = "Murphy ignorò palesemente la tua flebile supplica. La sua figura svanì ben presto dietro l'angolo."
  },
  AvgDialog_23844_Content_3 = {
    Text = "Huff... Huff..."
  },
  AvgDialog_23844_Content_30 = {
    Text = "...Tulu, perché non l'hai fermata?"
  },
  AvgDialog_23844_Content_31 = {Text = "..."},
  AvgDialog_23844_Content_32 = {
    Text = "Non guardarmi così. Non avevo previsto che la sua testa fosse così dura."
  },
  AvgDialog_23844_Content_4 = {
    Text = "La bambina si stringeva il polso, respirando affannosamente, visibilmente sconvolta."
  },
  AvgDialog_23844_Content_5 = {
    Text = "Tutto bene?"
  },
  AvgDialog_23844_Content_6 = {
    Text = "Stai indietro!!"
  },
  AvgDialog_23844_Content_7 = {
    Text = "Facesti appena mezzo passo avanti, e la bambina gridò con voce tesa, gli occhi colmi di diffidenza."
  },
  AvgDialog_23844_Content_8 = {
    Text = "Vedendo ciò, ti fermasti, alzando le mani per mostrare che eri innocuo."
  },
  AvgDialog_23844_Content_9 = {
    Text = "Non spaventarti — non siamo dei cattivi. Se non fosse stato per noi, quel mostro dalla faccia di serpente ti avrebbe usata in qualche rito, no?"
  },
  AvgDialog_23845_Content_1 = {
    Text = "Scivolasti furtivamente lungo il ponte, Murphy con le labbra serrate indicava il ponte di comando lì vicino, segnalando che la sala macchine si trovava all'interno."
  },
  AvgDialog_23845_Content_10 = {
    Text = "Una mannaia colossale fu scagliata brutalmente verso di te da lontano, la sua forza squarciava l'aria, scatenando una feroce onda d'urto."
  },
  AvgDialog_23845_Content_11 = {Text = "Attento!"},
  AvgDialog_23845_Content_12 = {
    Text = "Un robusto tentacolo si avvolse attorno alla tua vita, strappandoti dal punto d'impatto della lama."
  },
  AvgDialog_23845_Content_13 = {
    Text = "La maggior parte dei Navigatori è fragile e predilige armi leggere. Questa mannaia appartiene a qualcun altro—resta in guardia."
  },
  AvgDialog_23845_Content_14 = {
    Text = "Fragile... concordo con il tuo giudizio su questi sciocchi."
  },
  AvgDialog_23845_Content_15 = {
    Text = "Ma come carne da cannone in prima linea, dei droni privi di volontà non potrebbero essere più comodi."
  },
  AvgDialog_23845_Content_16 = {
    Text = "Un uomo massiccio e imponente trascinava una lunga pinna caudale, scostando a calci i Navigatori striscianti ai suoi piedi, avanzando pesantemente verso di te."
  },
  AvgDialog_23845_Content_17 = {
    Text = "Estrasse la lama dal ponte dove si era conficcata in profondità. Il suo tono era beffardo, il suo sguardo ti valutava con vivo interesse."
  },
  AvgDialog_23845_Content_18 = {
    Text = "Un Risvegliato di rango superiore ai Navigatori... Anche questo tizio è alleato di Miryam?!"
  },
  AvgDialog_23845_Content_19 = {
    Text = "\"Alleato di Miryam\"? Tch, che modo orribile di metterla."
  },
  AvgDialog_23845_Content_2 = {
    Text = "Se fossi riuscito a distrarre le Guardie del Navigatore alla porta, avresti potuto intrufolarti senza essere notato..."
  },
  AvgDialog_23845_Content_20 = {
    Text = "Io sono Golia.\nRicordatelo—il nome di colui che ha conquistato i mari!"
  },
  AvgDialog_23845_Content_3 = {
    Text = "Annuisti in segno di comprensione, frugando in tasca alla ricerca di qualcosa da lanciare, quando dei passi pesanti si avvicinarono."
  },
  AvgDialog_23845_Content_4 = {
    Text = "Murphy trattenne il fiato, il volto livido di paura. Si guardò intorno, poi strappò il telone da una cassa e vi si arrampicò dentro, scalciando con mani e piedi."
  },
  AvgDialog_23845_Content_5 = {
    Text = "<Small:Murphy?>"
  },
  AvgDialog_23845_Content_6 = {
    Text = "La cassa piombò nel silenzio e nell'immobilità, come un buco nero che l'avesse inghiottita intera."
  },
  AvgDialog_23845_Content_7 = {
    Text = "Silenzio... qualcuno sta arrivando."
  },
  AvgDialog_23845_Content_8 = {
    Text = [[
Colui che ha congedato le guardie dei Navigatori in lingua antica era senza dubbio un gigante.
La vostra angolazione ne nascondeva la forma, ma la sua ombra sul ponte incombeva enorme.]]
  },
  AvgDialog_23845_Content_9 = {
    Text = "Abbastanza vasto da calpestare catene montuose, divorare sole e luna—"
  },
  AvgDialog_23846_Content_1 = {
    Text = "Questo molo è enorme."
  },
  AvgDialog_23846_Content_10 = {
    Text = "Spero che non sia l'influenza del <Yellow:Cataclisma>..."
  },
  AvgDialog_23846_Content_2 = {
    Text = "Non mollate—ci stiamo avvicinando alla porta nord."
  },
  AvgDialog_23846_Content_3 = {
    Text = [[
Dopo le battaglie lungo il cammino, pochi nemici restavano sul vostro percorso.
Solo una manciata di pesci piccoli si frapponeva tra voi e la fuga.]]
  },
  AvgDialog_23846_Content_4 = {
    Text = "Questi nemici... potrebbe averli mandati la Chiesa della luce del tempio?\nSe non è così, è una coincidenza troppo grande."
  },
  AvgDialog_23846_Content_5 = {
    Text = "Non posso escluderlo.\nMa i membri della Chiesa della luce del tempio che abbiamo incontrato a Rye erano molto più raffinati."
  },
  AvgDialog_23846_Content_6 = {
    Text = "Ad assediarvi c'erano letteralmente dei \"pesci piccoli\" — umanoidi ricurvi, teste di pesce che spuntavano da cappucci laceri."
  },
  AvgDialog_23846_Content_7 = {
    Text = "Ogni assalto portava con sé il fetore della vita in decomposizione."
  },
  AvgDialog_23846_Content_8 = {
    Text = "Non si può escludere nemmeno l'Associazione degli Scultori — Herbert è un bastardo che gioca con la vita sotto la voce \"esperimento.\""
  },
  AvgDialog_23846_Content_9 = {
    Text = "Mi piace la tua opinione su Herbert. Ma ricorda, anche la Dissoluzione può causare mutazioni di massa."
  },
  AvgDialog_23847_Content_1 = {
    Text = "Tu e Tulu vi siete rifugiati in un angolo nascosto. Lui montava la guardia mentre tu ti immergevi nell'onirico Reame dello Spirito."
  },
  AvgDialog_23847_Content_10 = {
    Text = "Gli umani ordinari si manifestavano debolmente nel Reame dello Spirito. Senza questo Branco di Navigatori, individuare Murphy su una nave fantasma sarebbe stato semplice."
  },
  AvgDialog_23847_Content_11 = {
    Text = "I tuoi tentacoli mentali brancolavano tra il gruppo di Navigatori, scostando goffamente una particella dopo l'altra."
  },
  AvgDialog_23847_Content_12 = {
    Text = "<Gray:La mente di Murphy... qual è la sua...>"
  },
  AvgDialog_23847_Content_13 = {
    Text = "Mentre cantavi in silenzio il nome di Murphy, un'eterea voce femminile si sintonizzò improvvisamente sulla tua frequenza."
  },
  AvgDialog_23847_Content_14 = {
    Text = "Quando riapristi gli occhi, il Reame dello Spirito si era contorto in un panorama del tutto diverso."
  },
  AvgDialog_23847_Content_15 = {
    Text = "Ai confini dell'orizzonte, una città distorta e sghemba erompeva dal suolo. Il caotico clamore mentale non ti affliggeva più. Regnava un Silenzio assoluto, spezzato soltanto da una fioca luce solitaria che irradiava un freddo incessante."
  },
  AvgDialog_23847_Content_16 = {
    Text = "Chi... è costui?"
  },
  AvgDialog_23847_Content_17 = {
    Text = "Lady Miryam, quelle Squadre di Spedizione hanno distrutto l'altare di Elworth! L'allineamento è passato, e la cosa che abbiamo risvegliato..."
  },
  AvgDialog_23847_Content_18 = {
    Text = "<Gray:Lady Miryam... Questo è il Reame dello Spirito di Miryam?!>"
  },
  AvgDialog_23847_Content_19 = {
    Text = "Quella non è una Madre Divina degna di dare alla luce il Nostro Signore! Non è altro che una macchina di morte!"
  },
  AvgDialog_23847_Content_2 = {
    Text = "La familiare sensazione di annegamento si dissolse. Un vento intangibile attraversò la tua mente. Apristi gli occhi. Il Reame dello Spirito ti apparve al contempo familiare e stranamente estraneo."
  },
  AvgDialog_23847_Content_20 = {
    Text = "...Non importa. Attenderemo il prossimo allineamento stellare.\nHo sopportato cinquemila cicli—cos'è un altro giro?"
  },
  AvgDialog_23847_Content_21 = {
    Text = "Dite alla Chiesa dei Portatori di Luce di rimuovere quell'esemplare difettoso."
  },
  AvgDialog_23847_Content_22 = {Text = "S-sì..."},
  AvgDialog_23847_Content_23 = {
    Text = "Ma il nuovo vascello per dare alla luce il Nostro Signore... che ne sarà?"
  },
  AvgDialog_23847_Content_24 = {
    Text = "Non avevi detto che il vascello attuale, corrotto dalla Dissoluzione, non avrebbe resistito altri venticinque anni?"
  },
  AvgDialog_23847_Content_25 = {
    Text = "Non possiamo vedere la Dissoluzione, ma il vascello si indebolisce—è evidente a Tutti."
  },
  AvgDialog_23847_Content_26 = {
    Text = "La nuova Madre Divina..."
  },
  AvgDialog_23847_Content_27 = {
    Text = "Miryam abbassò lo sguardo sulla ragazza che sonnecchiava a bordo della vasca. Nella penombra della caverna di ghiaccio polare, i capelli rosa della ragazza risplendevano vividi, colmi di Vitalità."
  },
  AvgDialog_23847_Content_28 = {
    Text = "Circondata dai cultisti, cullava la ragazza addormentata."
  },
  AvgDialog_23847_Content_29 = {
    Text = "A piedi nudi, ascese alla sommità dell'altare, verso il gelido Trono di pietra che incarnava il sommo onore."
  },
  AvgDialog_23847_Content_3 = {
    Text = "<Gray:...Una nave?>"
  },
  AvgDialog_23847_Content_30 = {
    Text = "Assaporando il calore umano in un prolungato Silenzio, parlò sommessamente, eppure in modo udibile a tutti."
  },
  AvgDialog_23847_Content_31 = {
    Text = "La nuova Madre Divina... è già stata concessa dai cieli."
  },
  AvgDialog_23847_Content_32 = {
    Text = "I Deliri eruppero tra i cultisti prostrati."
  },
  AvgDialog_23847_Content_33 = {
    Text = "Murphy? La Fanciulla Divina? Ma non è forse..."
  },
  AvgDialog_23847_Content_34 = {
    Text = "Sì, è la figlia adottiva di Lady Miryam..."
  },
  AvgDialog_23847_Content_35 = {
    Text = "Anche se la Chiesa dei Portatori di Luce smettesse di fornire nuovi materiali di Risveglio, di certo Lady Miryam non sacrificherebbe Murphy..."
  },
  AvgDialog_23847_Content_36 = {
    Text = "La somma sacerdotessa non è troppo rigida? La dottrina dei Navigatori sostiene che il Reame Divino sia caduto decine di migliaia di anni fa."
  },
  AvgDialog_23847_Content_37 = {
    Text = "Murphy è un bambino che abbiamo visto crescere tutti quanti... La somma sacerdotessa ha atteso millenni—cos'è un po' più di tempo per trovare un nuovo ospite?"
  },
  AvgDialog_23847_Content_38 = {
    Text = "Ma si dice che la Fanciulla Divina sia nata durante l'ultimo allineamento. Nessuno è più adatto, giusto?"
  },
  AvgDialog_23847_Content_39 = {
    Text = "Il brusio di voci non suscitò alcuna reazione in Miryam. Fu piuttosto quel frastuono a destare Murphy, che si agitò svegliandosi."
  },
  AvgDialog_23847_Content_4 = {
    Text = "Un veliero bianco ondeggiava al limite dell'orizzonte—immacolato, fragile, alieno."
  },
  AvgDialog_23847_Content_40 = {Text = "Questo..."},
  AvgDialog_23847_Content_41 = {
    Text = "Miryam, c-cosa sta succedendo? Perché mi hai portata qui?"
  },
  AvgDialog_23847_Content_42 = {
    Text = "Miryam non rispose, e invece allungò la mano per lisciare i capelli arruffati di Murphy."
  },
  AvgDialog_23847_Content_43 = {
    Text = "Quando parlò di nuovo, le sue parole risuonarono con un tono definitivo."
  },
  AvgDialog_23847_Content_44 = {
    Text = "La Madre Divina è giunta! Egli si risveglierà da @1, inaugurando @2!"
  },
  AvgDialog_23847_Content_45 = {
    Text = "Altare di Elworth, Squadre di Spedizione..."
  },
  AvgDialog_23847_Content_46 = {
    Text = "Potrebbe essere Francis...!"
  },
  AvgDialog_23847_Content_47 = {
    Text = "Il pensiero si era appena formato quando un gelo tagliente ti afferrò la nuca. Uno sguardo serpentino si fissò su di te, scagliandoti fuori dal Reame dello Spirito di Miryam."
  },
  AvgDialog_23847_Content_48 = {Text = "Ngh...!"},
  AvgDialog_23847_Content_49 = {
    Text = "Novità? L'avete trovata?"
  },
  AvgDialog_23847_Content_5 = {
    Text = "<Gray:Dev'essere perché il Sona-Nyl si trova in un Dominio speciale. Sta effettivamente distorcendo il Reame dello Spirito.>"
  },
  AvgDialog_23847_Content_50 = {
    Text = "L'uscita irregolare ti lasciò stordito. Ti reggesti al Tentacolo di Tulu."
  },
  AvgDialog_23847_Content_51 = {
    Text = "Mi sono addentrato nel Reame dello Spirito di Miryam. Ora sa che sono vivo."
  },
  AvgDialog_23847_Content_52 = {Text = "!?"},
  AvgDialog_23847_Content_53 = {
    Text = "Piedi palmati martellavano il ponte, avvicinandosi. Che Miryam avesse invertito la traccia o meno, i Navigatori vi stavano accerchiando."
  },
  AvgDialog_23847_Content_54 = {
    Text = "Ehi! Che fai lì imbambolato — vieni con me!"
  },
  AvgDialog_23847_Content_55 = {
    Text = "Murphy fece cenno da una porta."
  },
  AvgDialog_23847_Content_56 = {
    Text = "Tu e Tulu vi scambiaste uno sguardo e vi lanciaste seguendo la sua guida."
  },
  AvgDialog_23847_Content_57 = {
    Text = "Miryam era appollaiata in cima alla plancia, occhi socchiusi, mano alla fronte, visibilmente stremata."
  },
  AvgDialog_23847_Content_58 = {
    Text = "Ehi, rara visione—vederti così. Che c'è, hai finito di giocare a fare finta con la nostra piccola Principessa?"
  },
  AvgDialog_23847_Content_59 = {
    Text = "Misura le parole, Golia."
  },
  AvgDialog_23847_Content_6 = {
    Text = "Miriadi di particelle luminose vorticavano attorno alla nave, come ritrovarsi in uno stagno boschivo d'estate, con il gracidare delle rane che si alzava e abbassava come colpi di tamburo... Ogni Navigatore portava con sé la propria Impronta distintiva."
  },
  AvgDialog_23847_Content_60 = {
    Text = "La Madre Divina... Nessun involucro mortale può sfuggire al destino che le ho decretato."
  },
  AvgDialog_23847_Content_61 = {
    Text = "Così sicura, eppure mi trascini quassù? Ero nel bel mezzo dell'inseguimento di quel Capitano."
  },
  AvgDialog_23847_Content_62 = {
    Text = "...L'altro Studente di Mythag, {Male=lui,Female=lei} respira ancora."
  },
  AvgDialog_23847_Content_63 = {
    Text = "Elimina{Male=lo,Female=la}. {Male=Lui,Female=Lei} non deve interferire con il Rito. Deve compiersi durante questo allineamento..."
  },
  AvgDialog_23847_Content_64 = {
    Text = "Il nostro Signore rinascerà questa notte."
  },
  AvgDialog_23847_Content_7 = {
    Text = "<Gray:Stai calma, stai calma... Tulu è la più vicina a me, Ramona è quella a cui sono legata...>"
  },
  AvgDialog_23847_Content_8 = {
    Text = "Nell'oscurità, una manciata di fonti luminose brillava intensamente, ma inseguirle si rivelò vano. Le presenze dei Navigatori sbarravano la tua mente come una Barriera di ferro."
  },
  AvgDialog_23847_Content_9 = {
    Text = "<Gray:Muoviti... togliti di mezzo.>"
  },
  AvgDialog_23848_Content_1 = {
    Text = "Una rigida suola di stivale si abbatté con forza sul Mutante da Dissoluzione, schizzando D-melma su tutto il pavimento."
  },
  AvgDialog_23848_Content_10 = {
    Text = "Insomma, hai finito con l'interrogatorio?"
  },
  AvgDialog_23848_Content_11 = {
    Text = "Murphy batté il piede, indicandoti alle spalle di Tulu."
  },
  AvgDialog_23848_Content_12 = {
    Text = "La {Male=sua,Female=sua} compagna è ancora nelle mani dei Navigatori, giusto? Se continuate a tergiversare e perdere tempo, e le succede qualcosa... non venite a incolpare me."
  },
  AvgDialog_23848_Content_13 = {Text = "..."},
  AvgDialog_23848_Content_14 = {
    Text = "Tulu ti lanciò un'occhiata di traverso per un istante, come a soppesare la tua espressione."
  },
  AvgDialog_23848_Content_15 = {
    Text = "La mia compagna è in pericolo e abbiamo combattuto senza sosta—Tulu è solo sotto pressione.\nSpero non vi offendiate per la nostra scortesia."
  },
  AvgDialog_23848_Content_16 = {
    Text = "Vi prego, portateci dal capitano... da qualcuno che possa aiutarci a trovare Ramona."
  },
  AvgDialog_23848_Content_2 = {
    Text = "Murphy abbassò la pala che aveva brandito, scuotendo la mano con disgusto, come per scrollarsi di dosso la D-melma che nemmeno l'aveva toccata."
  },
  AvgDialog_23848_Content_3 = {
    Text = "Uff... Meno male che non era un Navigatore, altrimenti non avrei osato colpire...\nSiete troppo lenti—muoviamoci."
  },
  AvgDialog_23848_Content_4 = {
    Text = "Un momento."
  },
  AvgDialog_23848_Content_5 = {
    Text = "Il tono di Tulu era glaciale, ma ricordando le sue parole sugli enigmi che circondavano Murphy, scegliesti il silenzio."
  },
  AvgDialog_23848_Content_6 = {
    Text = "Anche se le cabine attraverso cui ci hai guidato non mostrano tracce di Navigatori, più scendiamo in profondità, più mutanti incontriamo."
  },
  AvgDialog_23848_Content_7 = {
    Text = "Ci hai guidati dritti nel pericolo."
  },
  AvgDialog_23848_Content_8 = {
    Text = "Mutanti da Dissoluzione?... Oh, intendi questi mostri?"
  },
  AvgDialog_23848_Content_9 = {
    Text = "Il Capitano ha detto che sulla nave c'è stata un'epidemia di Cataclisma, una volta. Alcuni marinai si sono trasformati in mostri, ma lui non ha avuto il cuore di eliminarli, così li ha bloccati quasi tutti nella stiva."
  },
  AvgDialog_23849_Content_1 = {
    Text = "Il portello si aprì cigolando con uno scricchiolio, e una luce abbagliante si riversò nella stiva oscura."
  },
  AvgDialog_23849_Content_2 = {
    Text = "Senza i Navigatori in agguato in lontananza, la Sona-Nyl avrebbe potuto davvero essere un'utopia appartata..."
  },
  AvgDialog_23850_Content_1 = {
    Text = "Signorina Ramona, Custode! Qui!"
  },
  AvgDialog_23850_Content_10 = {
    Text = "Questi uomini-pesce ci stavano tendendo un'imboscata?!"
  },
  AvgDialog_23850_Content_11 = {
    Text = "Il conducente non è un combattente—fuori di qui, subito!"
  },
  AvgDialog_23850_Content_12 = {
    Text = "G-Giusto. Fate attenzione!"
  },
  AvgDialog_23850_Content_13 = {
    Text = "Il conducente si arrampicò dentro; il rombo del motore attirò gli occhi del nemico."
  },
  AvgDialog_23850_Content_14 = {
    Text = "Ehi! Occhi-di-pesce—qui!"
  },
  AvgDialog_23850_Content_2 = {
    Text = "È il conducente!"
  },
  AvgDialog_23850_Content_3 = {
    Text = "Più avanti, il familiare uomo di mezza età scuoteva ansiosamente il cancello incatenato, con aria turbata."
  },
  AvgDialog_23850_Content_4 = {
    Text = "La porta è bloccata—e adesso?"
  },
  AvgDialog_23850_Content_5 = {
    Text = "Nessun problema—reciderò la catena. Indietro."
  },
  AvgDialog_23850_Content_6 = {
    Text = "Il conducente indietreggiò per evitare la lama. Ramona sollevò l'arma all'altezza del petto, inspirando per raccogliere le forze —"
  },
  AvgDialog_23850_Content_8 = {
    Text = "Il fruscio crebbe; sagome emersero dalle ombre in successione, addensando l'aria di un'umida pesantezza."
  },
  AvgDialog_23850_Content_9 = {
    Text = "Nemici simili a pesci vi sbarrarono la strada verso il cancello; il conducente lanciò un grido, ruzzolando sul cofano."
  },
  AvgDialog_23851_Content_1 = {
    Text = "Una potenza così folle...! Terrificante persino per gli standard di un Risvegliato."
  },
  AvgDialog_23851_Content_10 = {
    Text = "La risata folle echeggiò attraverso il Dominio, facendo salire la tensione alle stelle."
  },
  AvgDialog_23851_Content_11 = {
    Text = "Tranquillo, non ti finisco qui."
  },
  AvgDialog_23851_Content_12 = {
    Text = "Quegli incompetenti del Portatore di Luce non riescono nemmeno a gestire la Sicurezza di base, lasciando intrufolare questo moccioso... Ma grazie al loro errore, questo Rito è diventato molto più divertente."
  },
  AvgDialog_23851_Content_13 = {
    Text = "Chiesa del Portatore di Luce... I Navigatori sono legati a loro?"
  },
  AvgDialog_23851_Content_14 = {
    Text = "Ha? Non mettermi insieme a quei pazzi. Le forme dei Navigatori rendono difficile mimetizzarsi, e loro bramano il nostro Potere... Mostri che si usano a vicenda, stringendosi per scaldarsi—tutto qui."
  },
  AvgDialog_23851_Content_15 = {
    Text = "Non solo legati al Portatore di Luce, ma questo <Blue:Rito> che menzioni..."
  },
  AvgDialog_23851_Content_16 = {
    Text = "Golia... chi sei esattamente?"
  },
  AvgDialog_23851_Content_17 = {
    Text = "Chi sono? Hahahahaha! Perché non lo chiedi alla tua spalla?"
  },
  AvgDialog_23851_Content_18 = {
    Text = "Da dove veniamo io—e questi Navigatori—... Non riesci a indovinare? Dopotutto, tu sei il supremo..."
  },
  AvgDialog_23851_Content_19 = {
    Text = "Che presunzione!"
  },
  AvgDialog_23851_Content_2 = {
    Text = "Questa forza..."
  },
  AvgDialog_23851_Content_20 = {
    Text = "Che paura, che paura—ma scusa, non sono un tuo suddito fedele."
  },
  AvgDialog_23851_Content_21 = {
    Text = "Devo occuparmi dei preparativi del Rito—non ho tempo per continuare a battibeccare con te."
  },
  AvgDialog_23851_Content_22 = {
    Text = "Vai pure, sgattaiola in giro con i tuoi Tentacoli nascosti. Ma lo sai—la cosa che quella Donna vuole, solo tu puoi fornirla."
  },
  AvgDialog_23851_Content_23 = {
    Text = "L'emissario che ha sottratto Potere a quel dio impotente... Ugh!"
  },
  AvgDialog_23851_Content_24 = {
    Text = "I suoi Scherni erano appena Terminati quando fantasmi violetti eruppero dalla cicatrice sul collo di Golia. Si avvolsero come sciarpe attorno alla sua gola, Solidificandosi infine in serpenti."
  },
  AvgDialog_23851_Content_25 = {
    Text = "Il volto di Golia si contorse all'Emersione dei fantasmi, i loro Fang che affondavano nella Ferita al collo."
  },
  AvgDialog_23851_Content_26 = {
    Text = "Pain e veleno si intrecciarono, torcendo i suoi lineamenti in un ghigno, denti da squalo che fremevano di eccitazione."
  },
  AvgDialog_23851_Content_27 = {
    Text = "Ha, ha... Stronza meschina—non sopporta una parola contro il suo dio Etereo."
  },
  AvgDialog_23851_Content_28 = {
    Text = "Un codardo senza fegato, senza cuore... hah!"
  },
  AvgDialog_23851_Content_29 = {
    Text = "I fantasmi tirarono bruscamente, piegando la spina dorsale del gigante ad arco, costringendolo alla prostrazione."
  },
  AvgDialog_23851_Content_3 = {
    Text = "Miryam ti ha conferito il potere che le era stato concesso."
  },
  AvgDialog_23851_Content_30 = {
    Text = "È tutto quello che sai fare!?"
  },
  AvgDialog_23851_Content_31 = {
    Text = "Controllarti con una fede imperscrutabile, lasciare che il Cataclisma rasi al suolo la tua civiltà—una fanatica... Ha, alla fine, Lui non è mai nemmeno esistito; è tutto un tuo Delirio!"
  },
  AvgDialog_23851_Content_32 = {
    Text = "I fantasmi si strinsero bruscamente. Golia tossì, sputando gocce di Sangue."
  },
  AvgDialog_23851_Content_33 = {
    Text = "L-lui è...?!"
  },
  AvgDialog_23851_Content_34 = {
    Text = "Un'antica Punizione... Usata a Lemuria per castigare e domare miscredenti e Prigionieri."
  },
  AvgDialog_23851_Content_35 = {
    Text = "Tulu rivolse lo Sguardo a Golia—che ancora sfoggiava il suo ghigno ferino—e sospirò."
  },
  AvgDialog_23851_Content_36 = {
    Text = [[
Opera di Miryam?
...Aspetta! Questo non significa che Miryam sa dove siamo?!]]
  },
  AvgDialog_23851_Content_37 = {
    Text = "Ha, non c'è bisogno di agitarsi."
  },
  AvgDialog_23851_Content_38 = {
    Text = "Golia puntellò la mannaia per rialzarsi.\nSi asciugò il sangue dal viso col dorso della mano—il tormento sembrava un semplice prurito."
  },
  AvgDialog_23851_Content_39 = {
    Text = "Solo un guinzaglio imposto da un'arrogante sciocca convinta di avere il controllo."
  },
  AvgDialog_23851_Content_4 = {
    Text = "Oh? Come potrebbe un moccioso come te..."
  },
  AvgDialog_23851_Content_40 = {
    Text = "Sparisci. Non farti ammazzare da qualche soldatuccio prima che io mi goda lo spettacolo fino in fondo."
  },
  AvgDialog_23851_Content_41 = {
    Text = "—Golia, aspetta!"
  },
  AvgDialog_23851_Content_42 = {
    Text = "Oh? Che c'è? Mi piacciono gli sfidanti con fegato. Hai una domanda prima che perda la pazienza."
  },
  AvgDialog_23851_Content_43 = {
    Text = "Ramona... com'è adesso la mia compagna? Cosa avete in mente per lei?"
  },
  AvgDialog_23851_Content_44 = {
    Text = "Ha... Prima di tutto: non mangio le donne.\nRisparmiarla per ora—è una decisione di Miryam."
  },
  AvgDialog_23851_Content_45 = {
    Text = "L'attuale Madre Divina... il ricettacolo per la nascita di un nuovo dio... non è che un'insignificante mocciosetta dai capelli rosa. Con quel corpo minuto della Madre Divina, non c'è modo che possa soffocare il primo grido del nuovo dio."
  },
  AvgDialog_23851_Content_46 = {
    Text = "I fantasmi svanirono quando smise di schernire il \"Dio\". Fece scrocchiare il collo da un lato all'altro, si mise la mannaia in spalla e se ne andò, incurante di mostrare le spalle."
  },
  AvgDialog_23851_Content_47 = {
    Text = "—Prima che si voltasse, lo vedesti distintamente lanciare un'occhiata alla cassa dove si nascondeva Murphy."
  },
  AvgDialog_23851_Content_5 = {
    Text = [[
L'esitazione di Tulu spinse il gigante a interrompere l'assalto, riflettendo.
Socchiuse gli occhi, squadrando Tulu dalla testa ai piedi, con lo sguardo che indugiava sulla corona vistosa.]]
  },
  AvgDialog_23851_Content_6 = {
    Text = "Il disegno di quella corona...!"
  },
  AvgDialog_23851_Content_7 = {
    Text = "Le pupille di Golia si contrassero, il suo sguardo crudo e penetrante fisso su entrambi. Poi, esplose in una risata sfrenata."
  },
  AvgDialog_23851_Content_8 = {
    Text = "Ha, hahahaha! Interessante... davvero interessante!"
  },
  AvgDialog_23851_Content_9 = {
    Text = "Se quella donna vedesse questo, che faccia farebbe? Impazzirebbe, vero? Hahahaha, non vedo l'ora che arrivi quel momento!"
  },
  AvgDialog_23852_Content_1 = {
    Text = "Occhio del Ciclone"
  },
  AvgDialog_23852_Content_10 = {
    Text = "Occhi aperti, testa pulsante, dintorni sconosciuti."
  },
  AvgDialog_23852_Content_100 = {
    Text = [[
Tulu scaglia un altro mostro dalla testa di pesce oltre la murata prima di lanciarti un'occhiata.
Afferra il telaio del boccaporto, ma la sua mossa successiva sfida ogni aspettativa.]]
  },
  AvgDialog_23852_Content_101 = {
    Text = "Non preoccuparti. Prosegui e ricongiungiti con gli altri.\nDevo capire perché si aggrappano al rituale."
  },
  AvgDialog_23852_Content_102 = {
    Text = "La botola si chiude con un tonfo, sprofondando te e la bambina nell'oscurità più totale."
  },
  AvgDialog_23852_Content_103 = {
    Text = "La bambina sbuffa in segno di sfida, azionando abilmente l'argano per assicurare il lucchetto."
  },
  AvgDialog_23852_Content_104 = {
    Text = "Uff—per ora dovremmo essere al sicuro."
  },
  AvgDialog_23852_Content_105 = {
    Text = "Preme un interruttore. L'antica lampadina tremola, poi inonda lo spazio di luce, scacciando le ombre."
  },
  AvgDialog_23852_Content_106 = {
    Text = "E finalmente scorgi le \"alghe\" che hanno attutito la tua caduta."
  },
  AvgDialog_23852_Content_107 = {
    Text = "Corpo e mente sprofondano nella lava più oscura dell'inferno—questa non è semplice alga.\nIl tuo palmo affonda in una melma cremisi di tessuti non identificati, ossa frastagliate che pungono dolorosamente."
  },
  AvgDialog_23852_Content_108 = {
    Text = "Rune arcane imbrattate da fluidi ricordano il tappeto pacchiano di una sala da ballo—chiaramente, un piccolo rito pagano si è consumato qui."
  },
  AvgDialog_23852_Content_109 = {
    Text = "La decomposizione permea la cabina; i soli resti di pesce non potrebbero produrre un simile fetore. Partecipanti più grandi e più grassi devono aver preso parte a questa macabra baldoria."
  },
  AvgDialog_23852_Content_11 = {
    Text = "Quante volte è già successo? Non esiste un modo più originale per cominciare?"
  },
  AvgDialog_23852_Content_110 = {Text = "Ugh..."},
  AvgDialog_23852_Content_111 = {
    Text = "Il solito disordine da Navigatore—non puliscono mai..."
  },
  AvgDialog_23852_Content_112 = {
    Text = "La bambina borbotta, osservando con disgusto il tuo corpo disteso sull'altare. Ti gira intorno, poi ti tira su afferrandoti per il braccio più pulito."
  },
  AvgDialog_23852_Content_113 = {
    Text = "Con Tulu lassù, non ci inseguiranno tanto presto...\nTroverò qualcosa per coprire quest'altare—la puzza è terribile."
  },
  AvgDialog_23852_Content_114 = {
    Text = "Le tempie pulsano a ritmo, l'agonia ti spacca il cranio. La bile sale, e ti pieghi in due, scosso da conati incontrollabili."
  },
  AvgDialog_23852_Content_115 = {
    Text = "Eh?! Che succede?! Non spaventarmi così!"
  },
  AvgDialog_23852_Content_116 = {
    Text = "Stai indietro!!"
  },
  AvgDialog_23852_Content_117 = {
    Text = "Non sono una semplice bambina; ho un nome."
  },
  AvgDialog_23852_Content_118 = {
    Text = "Murphy. Chiamami Murphy."
  },
  AvgDialog_23852_Content_119 = {
    Text = "Il suo volto ansioso si fonde con memorie frammentate, mescolando due scene simili eppure distinte in una sola."
  },
  AvgDialog_23852_Content_12 = {
    Text = "Ti costringi a sollevarti, e una visuale inaspettata ti inonda lo sguardo."
  },
  AvgDialog_23852_Content_120 = {Text = "Murphy...?"},
  AvgDialog_23852_Content_121 = {
    Text = "T-Tutto bene? L'Altare ti ha fatto così schifo?"
  },
  AvgDialog_23852_Content_122 = {
    Text = "Ti gira intorno ancora una volta, poi—nella luce fioca—si avvicina in punta di piedi per esaminare il tuo stato."
  },
  AvgDialog_23852_Content_123 = {Text = "—!"},
  AvgDialog_23852_Content_124 = {
    Text = [[
Brutta caduta...
Credo ci sia qualcosa di utile in questo carico...]]
  },
  AvgDialog_23852_Content_125 = {
    Text = "Murphy borbotta parole indistinte, frugando rigidamente tra le casse impilate."
  },
  AvgDialog_23852_Content_126 = {
    Text = "No... questi sono gioielli rotti."
  },
  AvgDialog_23852_Content_127 = {
    Text = "Lanci un'occhiata: un copricapo di corallo, perle e lapislazzuli giace lì, dall'aspetto costoso. Il suo design sinistro induce una vertigine nebbiosa."
  },
  AvgDialog_23852_Content_128 = {
    Text = "...Dannazione, tutta roba da Rito."
  },
  AvgDialog_23852_Content_129 = {
    Text = "La seconda cassa trabocca di stranezze: ciotole di pietra, salvia, polveri... Per un profano, potrebbe passare per la scorta di uno speziale."
  },
  AvgDialog_23852_Content_13 = {
    Text = "Un'enorme luna piena pende nel cielo notturno, una nebbia eterea avvolge il mare, l'aria densa di polvere da sparo e del sapore salmastro dell'acqua salata."
  },
  AvgDialog_23852_Content_130 = {
    Text = "Trovato! Tieni—accovacciati."
  },
  AvgDialog_23852_Content_131 = {
    Text = "Una pasta ti spalma il cuoio capelluto, fresca con un morso speziato, alleviando in parte il dolore. Ciocche di capelli si appiccicano sotto l'unguento, spingendoti a pettinarli—"
  },
  AvgDialog_23852_Content_132 = {
    Text = "Ehi! Non toccarlo ancora! Non è Veleno."
  },
  AvgDialog_23852_Content_133 = {
    Text = "Murphy ti porge il barattolo. Nessun ingrediente né nome sull'etichetta—solo un motivo bizzarro, chiaramente fatto in casa."
  },
  AvgDialog_23852_Content_134 = {
    Text = "...Déjà vu? Quel disegno sull'etichetta... l'hai già visto da qualche parte."
  },
  AvgDialog_23852_Content_135 = {
    Text = "Da piccoli, lo spalmavano su ogni graffio o livido."
  },
  AvgDialog_23852_Content_136 = {
    Text = "Allora? Ti senti già meglio, vero?"
  },
  AvgDialog_23852_Content_137 = {
    Text = "Ti osserva nervosamente, il senso di colpa evidente per la caduta dalle scale."
  },
  AvgDialog_23852_Content_138 = {
    Text = "Sì... ora non fa più male."
  },
  AvgDialog_23852_Content_139 = {
    Text = "Le tempie pulsano ancora debolmente, ma la nuca sembra lenita."
  },
  AvgDialog_23852_Content_14 = {
    Text = "Le onde lambiscono dolcemente lo scafo in una cadenza sommessa e ritmica, cullando il vascello mentre deriva verso una destinazione sconosciuta."
  },
  AvgDialog_23852_Content_140 = {
    Text = "Il tuo sguardo scivola verso l'\"altare\" in rovina; Murphy lo ha già coperto con un telo per risparmiarti un altro attacco di nausea."
  },
  AvgDialog_23852_Content_141 = {
    Text = "Ora, fluidi cremisi e grigio-verdastri trasudano attraverso la tela di iuta, formando una sagoma grottesca—come un pugnale peculiare, o un infante sul punto del suo primo vagito."
  },
  AvgDialog_23852_Content_142 = {
    Text = "Visto? Te l'avevo detto che funziona—"
  },
  AvgDialog_23852_Content_143 = {
    Text = "La conferma la rilassa, facendo affiorare un sorriso.\nOsservando la sua espressione distesa, una voce interiore sussurra—"
  },
  AvgDialog_23852_Content_144 = {
    Text = "Lei è l'occhio del ciclone. Lei detiene la chiave di tutto."
  },
  AvgDialog_23852_Content_15 = {
    Text = "Sono su una nave?!"
  },
  AvgDialog_23852_Content_16 = {
    Text = "Senza dubbio, vi trovate a bordo di un piroscafo in mare aperto. Di Ramona nessuna traccia, e nessun segno di vita si offre al vostro sguardo."
  },
  AvgDialog_23852_Content_17 = {
    Text = "Calma, calma.\nRagioniamo dall'inizio. Perché mi trovo su questa nave...?"
  },
  AvgDialog_23852_Content_18 = {
    Text = "Qualcosa su Herbert... lo schema... il diario di Francis... il porto..."
  },
  AvgDialog_23852_Content_19 = {
    Text = "Quando sarete pronta, partiremo. Sarò il vostro compagno, come sempre."
  },
  AvgDialog_23852_Content_2 = {
    Text = "Custode! Non lasciarmi la Mano!"
  },
  AvgDialog_23852_Content_20 = {
    Text = "Questa volta... la chiesa... segreti... devi—"
  },
  AvgDialog_23852_Content_21 = {Text = "...Ugh!"},
  AvgDialog_23852_Content_22 = {
    Text = "Frammenti di memoria affiorano, solo per essere lacerati da un dolore bruciante.\nLa bile sale, scorticando la gola—l'aria fresca diventa improvvisamente un lusso raro."
  },
  AvgDialog_23852_Content_23 = {
    Text = "Uff—Ramona e io abbiamo lasciato la scuola insieme... sì, Ramona.\nDevo trovare Ramona. Lei saprebbe cosa sta succedendo."
  },
  AvgDialog_23852_Content_24 = {
    Text = "Collegare il Comunicatore"
  },
  AvgDialog_23852_Content_25 = {
    Text = "Ramona, mi senti? Dove sei?"
  },
  AvgDialog_23852_Content_26 = {
    Text = "Ignorando quel dolore che vi penetra fino all'Anima, attivate il Comunicatore d'Argento come d'abitudine."
  },
  AvgDialog_23852_Content_27 = {
    Text = "È allora che scoprite che la <Yellow:spilla> — simbolo della vostra identità — è scomparsa dal bavero."
  },
  AvgDialog_23852_Content_28 = {
    Text = "Come è possibile?!"
  },
  AvgDialog_23852_Content_29 = {
    Text = "Piano, piano...\nC'è ancora un modo. Prova il Tracciamento Spirituale."
  },
  AvgDialog_23852_Content_3 = {
    Text = "Le narici ti bruciavano per l'odore acre del carbone combusto. Dopo un fugace istante di connessione, la gravità ti ha trascinato giù nell'abisso."
  },
  AvgDialog_23852_Content_30 = {
    Text = "Inspirate profondamente, scacciando il malessere con la volontà, e vi immergete ancora una volta nelle profondità del vostro spirito."
  },
  AvgDialog_23852_Content_31 = {
    Text = "Una costellazione di luci brilla tremula — ciascuna un'anima vibrante, assai più numerose di quanto avessi immaginato."
  },
  AvgDialog_23852_Content_32 = {
    Text = "Così tanta gente su questa nave? È strano..."
  },
  AvgDialog_23852_Content_33 = {
    Text = "Soffocando la curiosità e un timore infondato, ti concentri interiormente.\nIl legame agisce come un cordone ombelicale inflessibile, attirando verso di te due spiriti radianti."
  },
  AvgDialog_23852_Content_34 = {
    Text = "Due Legami? Oltre a Ramona, qualcun altro partecipava a questa missione?"
  },
  AvgDialog_23852_Content_35 = {
    Text = "Il tuo sondare genera increspature; una Gnosi sembra spaventata. Prima che tu possa percepire altro, Egli si volta pigramente, poi si fissa sulla tua posizione."
  },
  AvgDialog_23852_Content_36 = {
    Text = "Un brivido vi risale lungo la spina dorsale. Qualunque cosa sia collegata all'altro capo del Legame, sta venendo verso di voi!"
  },
  AvgDialog_23852_Content_37 = {
    Text = "Senza il tempo di riflettere sullo sconosciuto dall'altra parte, l'istinto ti strappa dal Reame dello Spirito e fuggi nella direzione opposta."
  },
  AvgDialog_23852_Content_38 = {Text = "—!"},
  AvgDialog_23852_Content_39 = {
    Text = "Come per crudele coincidenza, la nave emette un gemito lacerante nell'istante in cui il vostro piede tocca il ponte — il Grido mortale di una Bestia metallica, che sancisce la propria resa al mare."
  },
  AvgDialog_23852_Content_4 = {
    Text = "La voce familiare e il calore svanirono rapidamente, rimpiazzati da un freddo strisciante e un'umidità che artigliavano la spina dorsale."
  },
  AvgDialog_23852_Content_40 = {
    Text = "Tuffarsi nel regno spirituale così, ignari del pericolo.\nSconsiderato. Arrogante."
  },
  AvgDialog_23852_Content_41 = {
    Text = "Tentacoli morbidi e freschi, simili a polpa d'arancia, sostengono la vostra figura vacillante, tenendovi saldi."
  },
  AvgDialog_23852_Content_42 = {
    Text = "Non mi aspettavo una tale avventatezza da parte tua."
  },
  AvgDialog_23852_Content_43 = {Text = "Tulu?!"},
  AvgDialog_23852_Content_44 = {Text = "Tu..."},
  AvgDialog_23852_Content_45 = {
    Text = "Sei sveglio?"
  },
  AvgDialog_23852_Content_46 = {
    Text = "Il giovane Risvegliato vi lancia un'occhiata, lo Sguardo calmo eppure imperioso."
  },
  AvgDialog_23852_Content_47 = {
    Text = "Sorvolerò sulla tua impertinenza... per questa volta."
  },
  AvgDialog_23852_Content_48 = {
    Text = "Che ci fai qui?"
  },
  AvgDialog_23852_Content_49 = {
    Text = "Il giovane Risvegliato inarca un sopracciglio con lieve sorpresa, valutandovi con uno sguardo misurato."
  },
  AvgDialog_23852_Content_5 = {Text = "Custode!"},
  AvgDialog_23852_Content_50 = {
    Text = "Avete ancora lo spirito per scherzare. Allora non siete ferita."
  },
  AvgDialog_23852_Content_51 = {
    Text = "La breve interruzione nel nostro Legame dev'essere stata una semplice interferenza nella Gnosi."
  },
  AvgDialog_23852_Content_52 = {
    Text = "Come Lotan e Ogier, Tulu è uno dei tanti Risvegliatori sotto l'amministrazione di <Yellow:Mythag>.\nEppure, nel tuo anno di addestramento lì, lo hai intravisto solo una manciata di volte."
  },
  AvgDialog_23852_Content_53 = {
    Text = "Tulu trascorre la maggior parte dei suoi giorni nel Dormiveglia, i suoi risvegli rari come comete. Assegnarlo al lavoro sul campo con gli Investigatori? Impensabile."
  },
  AvgDialog_23852_Content_54 = {
    Text = "Eppure ora, un <Yellow:legame> invisibile vi stringe saldamente, la sua Gnosi tempestosa che scandaglia incessantemente il tuo Dominio mentale."
  },
  AvgDialog_23852_Content_55 = {
    Text = "Smarrimento del legame? No... aspetta, come siamo collegati? E perché sei fuori dalla scuola?"
  },
  AvgDialog_23852_Content_56 = {
    Text = "Domande sciocche. Non è il momento di giocare—il tempo della ragazza sta per scadere.\nI Navigatori proseguono con il Rituale della Discesa. <Yellow:Le stelle si stanno allineando nelle posizioni a loro destinate>."
  },
  AvgDialog_23852_Content_57 = {
    Text = "La Bambina? Il Rituale di Discesa?"
  },
  AvgDialog_23852_Content_58 = {
    Text = "La tensione si addensa tra te e Tulu. Dopo una pausa, sospira profondamente, il suo volto giovanile segnato da una gravità che non si addice a un bambino."
  },
  AvgDialog_23852_Content_59 = {
    Text = "Cosa ricordi?"
  },
  AvgDialog_23852_Content_6 = {
    Text = "Quello era... un Sogno?"
  },
  AvgDialog_23852_Content_60 = {
    Text = "Ramona e io siamo partiti per l'Indagine... quanto al resto..."
  },
  AvgDialog_23852_Content_61 = {
    Text = "Scuoti la testa. Che sia per una forza esterna o meno, una cosa è chiara: il tuo corpo resiste al ricordo."
  },
  AvgDialog_23852_Content_62 = {
    Text = "\"Le Stelle si levano nelle loro posizioni predestinate\" — conosci le condizioni del Rito."
  },
  AvgDialog_23852_Content_63 = {
    Text = "Il Rituale di Discesa — cosa sta succedendo? E chi sono questi uomini-pesce?"
  },
  AvgDialog_23852_Content_64 = {
    Text = "Non ricordo i dettagli, ma il legame non mente. Siamo alleati qui — Tulu, dimmi cos'è successo."
  },
  AvgDialog_23852_Content_65 = {
    Text = "La stanchezza adombra i lineamenti di Tulu. Chiude gli occhi, come per raccogliere i pensieri."
  },
  AvgDialog_23852_Content_66 = {
    Text = [[
Una mia negligenza, non aver notato il tuo malessere.
Per un umano essere intrappolato in tutto questo... ha lasciato il segno.]]
  },
  AvgDialog_23852_Content_67 = {
    Text = "Ma \"Il Rituale della Discesa\" è un termine troppo delicato per un Custode di Mythag.\nMentre insisti per saperne di più, i tentacoli di Tulu ti sbarrano la strada."
  },
  AvgDialog_23852_Content_68 = {
    Text = "Qualcuno si avvicina. Stai all'erta."
  },
  AvgDialog_23852_Content_69 = {Text = "Plop..."},
  AvgDialog_23852_Content_7 = {
    Text = "È già l'alba...?"
  },
  AvgDialog_23852_Content_70 = {
    Text = "Passi concitati si mescolano allo schiocco di piedi palmati, vibrazioni che rimbombano dal basso. Una figura si precipita dall'estremità opposta del ponte verso di te."
  },
  AvgDialog_23852_Content_71 = {
    Text = "Gur... gurgll..."
  },
  AvgDialog_23852_Content_72 = {
    Text = "Wah—aiuto—!"
  },
  AvgDialog_23852_Content_73 = {
    Text = "Aiutami!! %player%!"
  },
  AvgDialog_23852_Content_74 = {
    Text = "La ragazza corre al tuo fianco, ansimando, aggrappandosi al tuo mantello come a un'ancora di salvezza."
  },
  AvgDialog_23852_Content_75 = {
    Text = "Ridateci... @2... @1lei! @2!"
  },
  AvgDialog_23852_Content_76 = {
    Text = "Questi nemici Umanoidi dai tratti acquatici emettono gemiti inquietanti. I suoni sono caotici e stridenti, eppure il loro intento traspare chiaramente."
  },
  AvgDialog_23852_Content_77 = {
    Text = "Stanno dicendo... \"ridatecela\"?"
  },
  AvgDialog_23852_Content_78 = {
    Text = "I ruggiti disordinati si fanno più chiari nelle tue orecchie.\nAncora un po', e avresti afferrato ciò che volevano —"
  },
  AvgDialog_23852_Content_79 = {
    Text = "In quell'istante di distrazione, la ragazza ti pesta con forza lo stivale."
  },
  AvgDialog_23852_Content_8 = {
    Text = "Ogni osso del tuo corpo sembra essere stato frantumato e riassemblato, mentre una stanchezza prematura ti sopraffà.\nLe tempie pulsano, e gli occhi sono così secchi che ogni battito di ciglia sembra una puntura d'ago."
  },
  AvgDialog_23852_Content_80 = {Text = "Ssssh—"},
  AvgDialog_23852_Content_81 = {
    Text = "Te ne stai lì impalato? Fai qualcosa!"
  },
  AvgDialog_23852_Content_82 = {
    Text = "E tu! Smettila di fissarli — concentrati! Non lasciare che ci prendano."
  },
  AvgDialog_23852_Content_83 = {
    Text = "Tulu distoglie lo sguardo da entrambi. I suoi tentacoli sferzano con ferocia, spazzando fuoribordo uno a uno gli implacabili assalitori."
  },
  AvgDialog_23852_Content_84 = {
    Text = "Rinforzi in arrivo. Vengono per te."
  },
  AvgDialog_23852_Content_85 = {
    Text = "La bambina stringe le labbra, poi si illumina con una scintilla d'ispirazione."
  },
  AvgDialog_23852_Content_86 = {
    Text = "Dentro la cabina! Per ora possiamo seminarli."
  },
  AvgDialog_23852_Content_87 = {
    Text = "Indietreggia di qualche passo, e tu la schermi mentre la segui. Scostando le assi a calci, rivela una botola nel ponte."
  },
  AvgDialog_23852_Content_88 = {
    Text = "Una Porta nascosta?!"
  },
  AvgDialog_23852_Content_89 = {
    Text = "Una porta nascosta? Devi proprio prendermi in giro in un momento come questo!?"
  },
  AvgDialog_23852_Content_9 = {
    Text = "La gola sembra aver divorato un boccone di qualcosa di denso e acre, e ogni respiro porta un blocco soffocante e pain."
  },
  AvgDialog_23852_Content_90 = {
    Text = "Non è che tu non sia mai stato sottocoperta—smettila di tergiversare, preparati!"
  },
  AvgDialog_23852_Content_91 = {
    Text = "Tulu non solleva obiezioni. Sotto la sua silenziosa copertura, tu e la bambina spalancate la botola di ferro."
  },
  AvgDialog_23852_Content_92 = {
    Text = "Al di sotto, una scala metallica discende in profondità invisibili."
  },
  AvgDialog_23852_Content_93 = {
    Text = "Presto! Prima tu!"
  },
  AvgDialog_23852_Content_94 = {
    Text = "Non puoi combattere—devo proteggerti—ah!"
  },
  AvgDialog_23852_Content_95 = {
    Text = "Ignorando le tue proteste, la bambina—esile e agile—scivola alle tue spalle."
  },
  AvgDialog_23852_Content_96 = {
    Text = "—E con un calcio deciso, ti spedisce a ruzzolare nel vuoto nero."
  },
  AvgDialog_23852_Content_97 = {
    Text = "<SmallShake:Ahi, ahi...>"
  },
  AvgDialog_23852_Content_98 = {
    Text = "Atterri in qualcosa che sembra morbida alga marina, il tanfo di pesce e la salsedine pungente ti assaltano i sensi, facendo vorticare la tua testa già dolorante."
  },
  AvgDialog_23852_Content_99 = {
    Text = "Ehi! Tu! Non restare appeso lì—scendi!"
  },
  AvgDialog_23853_Content_1 = {
    Text = "Batti le palpebre e sparisce...\nCercarla così è inutile. Forse dovremmo trovare prima Ramona..."
  },
  AvgDialog_23853_Content_2 = {
    Text = "No, non possiamo lasciarla andare!"
  },
  AvgDialog_23853_Content_3 = {
    Text = "Ehm... voglio dire, potrebbe detenere la chiave per svelare il mistero dei Navigatori."
  },
  AvgDialog_23853_Content_4 = {
    Text = "A giudicare da quanto bene li conosce, deve essere al corrente dei loro obiettivi."
  },
  AvgDialog_23853_Content_5 = {Text = "..."},
  AvgDialog_23853_Content_6 = {
    Text = "D'accordo, proverò il Tracciamento Spirituale per trovarla.\nÈ la prima volta che lo uso per rintracciare un umano—non garantisco che funzioni."
  },
  AvgDialog_23854_Content_1 = {Text = "Pugnale"},
  AvgDialog_23854_Content_10 = {
    Text = "A dire il vero, mi sono appena ricordata del tuo nome."
  },
  AvgDialog_23854_Content_11 = {
    Text = "...Ah! Non dirmi che quel calcio giù dal boccaporto ti ha fatto saltare qualche rotella!\nDannazione, perché proprio adesso..."
  },
  AvgDialog_23854_Content_12 = {
    Text = "Murphy si gratta la testa frustrata, visibilmente in difficoltà."
  },
  AvgDialog_23854_Content_13 = {
    Text = "Tutta la Storia... è troppo complicata da spiegare. E questo posto non è esattamente sicuro. Dobbiamo prima riunirci con gli altri."
  },
  AvgDialog_23854_Content_14 = {Text = "Altri?"},
  AvgDialog_23854_Content_15 = {
    Text = "Il Capitano della Sona-Nyl e il suo equipaggio, e Ramona."
  },
  AvgDialog_23854_Content_16 = {
    Text = "Oh! Puoi riprovare quella cosa? Quella in cui ti immergi nel Reame dello Spirito per trovare le persone."
  },
  AvgDialog_23854_Content_17 = {
    Text = "Tracciamento Spirituale? Conosci Ramona, Tulu, e sai persino che posso fare il Tracciamento Spirituale...\nCos'è successo prima?"
  },
  AvgDialog_23854_Content_18 = {
    Text = "Smettila di tergiversare! Prima trova la posizione di Ramona—ti spiego lungo la strada."
  },
  AvgDialog_23854_Content_19 = {
    Text = "Sprofondare nel Reame dello Spirito si rivela agonizzante come mai prima d'ora: la tua coscienza raschia attraverso rovi, trafitta da dolori pungenti. E quando finalmente scorgi il bagliore familiare—"
  },
  AvgDialog_23854_Content_2 = {
    Text = "Tulu ha detto che dovremmo ricongiungerci con gli altri... Hmph, più facile a dirsi che a farsi."
  },
  AvgDialog_23854_Content_20 = {Text = "Crack—"},
  AvgDialog_23854_Content_21 = {Text = "Ngh...!"},
  AvgDialog_23854_Content_22 = {
    Text = "I tuoi viticci mentali sfiorano appena il confine della tua mente, per poi spezzarsi come tralci secchi."
  },
  AvgDialog_23854_Content_23 = {
    Text = "Un'Agonia lacerante per l'Anima ti Perfora le tempie, facendoti crollare ai piedi di Murphy."
  },
  AvgDialog_23854_Content_24 = {
    Text = "E-Ehi?! Non spaventarmi—non morirmi tra le braccia!"
  },
  AvgDialog_23854_Content_25 = {
    Text = "Io... sto bene..."
  },
  AvgDialog_23854_Content_26 = {
    Text = "Il Tracciamento Spirituale è di solito il tuo forte, ma ora il tuo corpo ostacola le tue peregrinazioni spirituali."
  },
  AvgDialog_23854_Content_27 = {
    Text = "Ne sei certo: è il tuo stesso corpo a espellerti dal Reame dello Spirito, non qualche entità misteriosa."
  },
  AvgDialog_23854_Content_28 = {
    Text = "@2... gorgoglio..."
  },
  AvgDialog_23854_Content_29 = {
    Text = "Sono i Navigatori—ci hanno trovati!\nNon possiamo restare qui. Seguimi."
  },
  AvgDialog_23854_Content_3 = {
    Text = [[
Murphy cammina avanti e indietro nella stiva, visibilmente agitata.
Fai un respiro profondo e la chiami.]]
  },
  AvgDialog_23854_Content_30 = {
    Text = "Murphy si sforza di tirarti su, il tuo peso le fa tremare le gambe. Sposti il tuo Equilibrio verso la paratia e, con il suo sostegno, barcolli più in profondità nella nave..."
  },
  AvgDialog_23854_Content_31 = {
    Text = "Ti fermi davanti a una pesante Porta di ferro, deturpata da sinistre ammaccature e rigonfiamenti. Dalle giunture mal combacianti si diffonde l'acre sentore di fumo."
  },
  AvgDialog_23854_Content_32 = {
    Text = "Murphy, entriamo?"
  },
  AvgDialog_23854_Content_33 = {
    Text = "Shh, fammi ascoltare..."
  },
  AvgDialog_23854_Content_34 = {
    Text = "Murphy ti lascia delicatamente, accosta l'orecchio alla Porta e ascolta attentamente a occhi chiusi."
  },
  AvgDialog_23854_Content_35 = {
    Text = "Sembra vuoto. Nascondiamoci qui dentro."
  },
  AvgDialog_23854_Content_36 = {
    Text = "Prima che Murphy la spalanchi, lanci un'occhiata alla targhetta—\"Sala Motori.\""
  },
  AvgDialog_23854_Content_37 = {
    Text = "Nessuna scena operosa vi attende: niente operai robusti, niente caldaie ruggenti—solo scintille che volano ovunque."
  },
  AvgDialog_23854_Content_38 = {
    Text = "Corpi freddi e rigidi ricoprono il pavimento—i Mostri dalla testa di pesce che vi inseguivano."
  },
  AvgDialog_23854_Content_39 = {
    Text = "Murphy e Tulu li chiamano \"<Yellow:Navigatori>.\""
  },
  AvgDialog_23854_Content_4 = {Text = "Murphy."},
  AvgDialog_23854_Content_40 = {
    Text = "Enormi squarci si aprono nelle paratie, lasciando entrare raffiche di Vento gelido. Murphy si strofina le orecchie arrossate, sostenendoti mentre scavalchi le fiamme per addentarti nelle rovine."
  },
  AvgDialog_23854_Content_41 = {
    Text = "Coff, coff... questo fetore è insopportabile."
  },
  AvgDialog_23854_Content_42 = {
    Text = "Questo posto... ha visto una battaglia feroce?"
  },
  AvgDialog_23854_Content_43 = {
    Text = "Battaglia feroce? È un eufemismo per quello che è successo qui."
  },
  AvgDialog_23854_Content_44 = {
    Text = "Oh... già, non ricordi."
  },
  AvgDialog_23854_Content_45 = {
    Text = "Tra le macerie, qualcosa luccica in modo vistoso."
  },
  AvgDialog_23854_Content_46 = {
    Text = "Prima ancora che tu riesca a identificarlo, il volto di Murphy si contorce—in parte Orrore, in parte Pianto."
  },
  AvgDialog_23854_Content_47 = {
    Text = "Non so quando si sia trasformata in questa pazza delirante..."
  },
  AvgDialog_23854_Content_48 = {
    Text = "Le sue labbra si increspano mentre racconta alla rinfusa il \"passato,\" avanzando verso il luccichio tra le macerie."
  },
  AvgDialog_23854_Content_49 = {
    Text = "Non voleva sentire ragione, per quanto la implorassi — insisteva per compiere questo rito..."
  },
  AvgDialog_23854_Content_5 = {
    Text = "Forse dovremmo rintanarci in un angolo..."
  },
  AvgDialog_23854_Content_50 = {
    Text = "— Il bagliore proviene da un pugnale dalla forma bizzarra, adagiato tra braci morenti. Nonostante la polvere, il suo filo grida affilatura."
  },
  AvgDialog_23854_Content_51 = {
    Text = "Era così gentile con me, un tempo..."
  },
  AvgDialog_23854_Content_52 = {
    Text = "Murphy fissa il pugnale per un istante, poi si getta carponi tra i rottami, allungando la mano per afferrarlo."
  },
  AvgDialog_23854_Content_53 = {
    Text = "Gur... gurgll..."
  },
  AvgDialog_23854_Content_54 = {
    Text = "Tra i Navigatori caduti, uno si solleva facendo leva su un'arma spezzata, barcollando in piedi, gli occhi sporgenti — quasi fuori dalle orbite — fissi con furia omicida su Murphy lassù."
  },
  AvgDialog_23854_Content_55 = {
    Text = "Perché... perché... dalla Somma Sacerdotessa... perché?"
  },
  AvgDialog_23854_Content_56 = {
    Text = "Madre Divina, Madre Divina... Gorgoglio, gorgoglio...! Ho trovato la Madre Divina!"
  },
  AvgDialog_23854_Content_57 = {
    Text = "Somma Sacerdotessa, Somma Sacerdotessa! Il rito si avvicina, <Big:IL RITO SI AVVICINA!>"
  },
  AvgDialog_23854_Content_58 = {
    Text = "La mascella da pesce del Navigatore si spalanca in modo impossibile, la membrana che la connette tesa fino alla trasparenza."
  },
  AvgDialog_23854_Content_59 = {
    Text = "Spinto dalla paura, dalla speranza e dalla fede, esplode con una vitalità inimmaginabile.\nIl Navigatore ti spinge da parte, strillando mentre si precipita verso l'uscita della sala macchine."
  },
  AvgDialog_23854_Content_6 = {
    Text = "<BigShake:Murphy! Devo dirti una cosa!>"
  },
  AvgDialog_23854_Content_60 = {
    Text = "No—sta scappando!"
  },
  AvgDialog_23854_Content_61 = {
    Text = "Shlkk——"
  },
  AvgDialog_23854_Content_62 = {
    Text = "Una punta affilata esplode dal petto grigio-azzurro, fluidi che sprizzano mentre il Navigatore si accascia."
  },
  AvgDialog_23854_Content_63 = {
    Text = "Murphy monta la guardia alla porta, inosservata fino a questo momento, icore grigio-verde che gocciola dalla punta del pugnale."
  },
  AvgDialog_23854_Content_64 = {
    Text = "Brandelli di tessuto vi aderiscono, le incisioni intasate di carne. Murphy trema visibilmente, eppure la sua presa resta un corpo d'acciaio."
  },
  AvgDialog_23854_Content_65 = {
    Text = "...Scusa, non posso lasciarti andare."
  },
  AvgDialog_23854_Content_66 = {
    Text = "Murphy osserva il pugnale ancora un momento, poi ne deterge il sangue del Navigatore."
  },
  AvgDialog_23854_Content_67 = {
    Text = "Stava per avvertire gli altri..."
  },
  AvgDialog_23854_Content_68 = {
    Text = "Appoggiata alla porta, Murphy scruta la devastazione della sala motori, le ciglia che fremono inquiete."
  },
  AvgDialog_23854_Content_69 = {
    Text = "Ma <Blue:Miryam> è già... perché non vogliono rinunciare..."
  },
  AvgDialog_23854_Content_7 = {
    Text = "Non urlare così! E se attirassi i Navigatori dritti verso di noi!"
  },
  AvgDialog_23854_Content_70 = {
    Text = "Murphy mormora quel nome, scatenando un capogiro inspiegabile. Sbatti le palpebre attraverso la nausea prima di formulare la tua domanda."
  },
  AvgDialog_23854_Content_71 = {
    Text = "Chi è Miryam?"
  },
  AvgDialog_23854_Content_72 = {
    Text = "È la leader dei Navigatori... del popolo-pesce."
  },
  AvgDialog_23854_Content_73 = {
    Text = "Allora questa \"Madre Divina\"..."
  },
  AvgDialog_23854_Content_74 = {
    Text = "La domanda innesca deglutizioni meccaniche, la tensione che cresce."
  },
  AvgDialog_23854_Content_75 = {
    Text = "Il tuo corpo conosce la risposta, eppure un terrore inconscio ne blocca il ricordo."
  },
  AvgDialog_23854_Content_76 = {Text = "..."},
  AvgDialog_23854_Content_77 = {
    Text = "Murphy alza lo sguardo, il dolore le vortica negli occhi."
  },
  AvgDialog_23854_Content_78 = {Text = "Sono io."},
  AvgDialog_23854_Content_79 = {
    Text = "Sono la misera disgraziata infestata dai mostri, il vascello predestinato alla rinascita dalla terra di un dio pagano."
  },
  AvgDialog_23854_Content_8 = {
    Text = "Bene, di che si tratta?"
  },
  AvgDialog_23854_Content_80 = {
    Text = "Io... sono la \"Madre Divina\" del culto dei Navigatori."
  },
  AvgDialog_23854_Content_81 = {
    Text = "Non appena l'ultima parola sfugge dalle labbra di Murphy, una luce bianca esplode davanti ai tuoi occhi, intrecciata all'agonia."
  },
  AvgDialog_23854_Content_82 = {
    Text = "Ehi?! Ehi! %player%?!"
  },
  AvgDialog_23854_Content_83 = {
    Text = "Il tuo corpo crolla all'indietro senza controllo, ronzii a bassa frequenza ti avvolgono le orecchie, le grida della ragazza sommerse nel torrente del dolore."
  },
  AvgDialog_23854_Content_84 = {
    Text = "Alla fine della luce, uno sguardo intangibile si fissa su di te."
  },
  AvgDialog_23854_Content_85 = {
    Text = "L'entità sconosciuta ti giudica — se il tuo cranio frantumato meriti di essere ricomposto, se la tua anima che si disfa possa essere ritessuta."
  },
  AvgDialog_23854_Content_86 = {
    Text = "Gli occhi spalancati, la coscienza scivola via dal tuo corpo..."
  },
  AvgDialog_23854_Content_9 = {
    Text = "Io... sono un po' confuso su cosa stia succedendo.\nPerché sono su questa nave? Come faccio a conoscerti...?"
  },
  AvgDialog_23855_Content_1 = {
    Text = "Murphy, smettila di correre! Non siamo cattive persone!"
  },
  AvgDialog_23855_Content_2 = {
    Text = "Come se un cattivo ammettesse mai di esserlo!"
  },
  AvgDialog_23855_Content_3 = {
    Text = "Ha persino decifrato lo scopo della runa, e tu insisti nel dire che non siete con i Navigatori!"
  },
  AvgDialog_23855_Content_4 = {
    Text = "È un'incantazione scritta in antico Lemuriano. Chiunque sia versato nel Lemuriano leggerebbe la runa senza difficoltà."
  },
  AvgDialog_23855_Content_5 = {
    Text = "E ti rendi conto che Lemuria era una civiltà perduta ancor prima che la storia umana avesse inizio, vero? Persino al Mythag esistono solo una manciata di studi su Lemuria."
  },
  AvgDialog_23855_Content_6 = {Text = "...Hmph."},
  AvgDialog_23855_Content_7 = {
    Text = "Sbrigatevi e basta."
  },
  AvgDialog_23856_Content_1 = {
    Text = "Realtà Distorta"
  },
  AvgDialog_23856_Content_10 = {
    Text = "C-cosa? Perché mi fissate così? Che avete voi due?"
  },
  AvgDialog_23856_Content_100 = {
    Text = "Golia... tu..."
  },
  AvgDialog_23856_Content_101 = {
    Text = "Perché... perché mi racconti questo?"
  },
  AvgDialog_23856_Content_102 = {
    Text = "Rimuginare non serve a nulla. Il tuo stato influenza la crescita del dio, lo sai."
  },
  AvgDialog_23856_Content_103 = {
    Text = "Il prossimo allineamento è tra venticinque anni. Scommetto che Miryam arriverà presto a metterti sotto."
  },
  AvgDialog_23856_Content_104 = {
    Text = "Fai qualcosa di divertente — distruggi roba, frusta i Navigatori, tormenta le tue ancelle... qualsiasi cosa."
  },
  AvgDialog_23856_Content_105 = {
    Text = "Golia troncò la conversazione unilateralmente, dandole una ruvida pacca sulla testa, priva di qualsiasi calore."
  },
  AvgDialog_23856_Content_106 = {
    Text = "Uscendo, lanciò un'occhiata all'intaglio di legno che Murphy aveva gettato in un angolo. La sua abilità era pessima — la forma tozza e grottesca in cima alla base di legno risultava repellente al primo sguardo."
  },
  AvgDialog_23856_Content_107 = {Text = "Heh."},
  AvgDialog_23856_Content_108 = {
    Text = "Dopo che Golia se ne fu andato, lo spazio piombò in un silenzio assoluto. Persino i sacrifici in gabbia in attesa del macello non emettevano alcun suono."
  },
  AvgDialog_23856_Content_109 = {
    Text = "Murphy rimase seduta accanto al fuoco per un tempo interminabile, finché la luce non si affievolì e le braci non si spensero. Solo allora si schiaffeggiò le guance, come riscuotendosi da un sogno."
  },
  AvgDialog_23856_Content_11 = {
    Text = "Hai riconosciuto Golia dai suoi passi. E prima, le tue parole hanno tradito la tua familiarità con Miryam."
  },
  AvgDialog_23856_Content_110 = {
    Text = "Sferrò un calcio violento a una gabbia, ricordando la donna che aveva rovinato il rito mesi prima... quella che era sfuggita a Miryam con pura forza di volontà."
  },
  AvgDialog_23856_Content_111 = {Text = "..."},
  AvgDialog_23856_Content_113 = {
    Text = [[
"Mi dispiace..."
"Io... non voglio morire..."]]
  },
  AvgDialog_23856_Content_114 = {Text = "..."},
  AvgDialog_23856_Content_115 = {
    Text = "Non voglio... finire così..."
  },
  AvgDialog_23856_Content_12 = {
    Text = "Sei addentro nell'organizzazione dei Navigatori — un membro, persino di alto rango. O meglio, sono qui per te."
  },
  AvgDialog_23856_Content_13 = {
    Text = "Sei la Madre Divina dei Navigatori, il ricettacolo per la nascita del nuovo dio... vero?"
  },
  AvgDialog_23856_Content_14 = {
    Text = "<Big:Non è vero!>"
  },
  AvgDialog_23856_Content_15 = {
    Text = "Allora spiega la tua familiarità con Golia e Miryam, e perché stai fuggendo dai Navigatori."
  },
  AvgDialog_23856_Content_16 = {
    Text = "Sono solo... un'ancella... una qualunque. Ragazze come me ce ne sono a bizzeffe alla base del culto."
  },
  AvgDialog_23856_Content_17 = {
    Text = "Le sembianze umane sono rare tra i Navigatori. Altrimenti, con la loro abilità in combattimento, non avrebbero bisogno di allearsi con la Chiesa dei Portatori di Luce."
  },
  AvgDialog_23856_Content_18 = {
    Text = "Se fossi solo un'irrilevante Ancella umana, perché questa caccia spietata per trovarti?"
  },
  AvgDialog_23856_Content_19 = {
    Text = "Tutto questo... è solo..."
  },
  AvgDialog_23856_Content_2 = {
    Text = "Murphy, Murphy?"
  },
  AvgDialog_23856_Content_20 = {
    Text = "Murphy, devo sapere cosa sta succedendo."
  },
  AvgDialog_23856_Content_21 = {
    Text = "Solo allora avremo una possibilità di sopravvivere. Solo allora potremo aiutarti."
  },
  AvgDialog_23856_Content_22 = {Text = "..."},
  AvgDialog_23856_Content_23 = {Text = "Va bene..."},
  AvgDialog_23856_Content_24 = {Text = "..."},
  AvgDialog_23856_Content_25 = {
    Text = "Un uccello implume dalle ali spezzate precipitò in una Pozza nera."
  },
  AvgDialog_23856_Content_26 = {
    Text = "Le Preghiere mormorate dalla somma sacerdotessa si diffondevano ferme e sfuggenti. Parole fanatiche trafissero la melma nera, tramutandosi in Lame che squarciarono il petto dell'implume."
  },
  AvgDialog_23856_Content_27 = {
    Text = "Un liquido Cremisi sgorgò dalla Ferita, sbocciando sinistro sulla superficie nera ormai immobile—"
  },
  AvgDialog_23856_Content_28 = {
    Text = "Eppure continuava a sprofondare, radici intrise di Sangue che si addentravano negli abissi, in un Abbraccio soffice e gelido."
  },
  AvgDialog_23856_Content_29 = {Text = "..."},
  AvgDialog_23856_Content_3 = {
    Text = "Puoi uscire ora... Golia se n'è andato."
  },
  AvgDialog_23856_Content_30 = {Text = "..."},
  AvgDialog_23856_Content_31 = {
    Text = "Lo vide.\nAlzando lo sguardo, la \"Madre\" abbassò tre paia di peduncoli oculari, incontrando il suo Sguardo."
  },
  AvgDialog_23856_Content_32 = {
    Text = "Era un'entità colossale cremisi, le cui parti intrise di sangue diventavano bianco traslucido.\nLa \"Madre\" emetteva un debole bagliore, illuminando brevemente una piccola porzione di spazio."
  },
  AvgDialog_23856_Content_33 = {
    Text = "A quella luce, vide innumerevoli Ferite nere, grandi e piccole, che sfregiavano la pelle liscia della \"Madre\"."
  },
  AvgDialog_23856_Content_34 = {
    Text = "\"Mi dispiace...\""
  },
  AvgDialog_23856_Content_35 = {
    Text = "Una melma nera ribollì, frantumando la quiete della vasca."
  },
  AvgDialog_23856_Content_36 = {
    Text = "La \"Madre\" emise un grido acuto e stridulo, i Tentacoli si contorcevano mentre depositavano qualcosa nel petto dell'implume."
  },
  AvgDialog_23856_Content_37 = {
    Text = "Tentacoli viscidi, gelidi e morbidi la avvolsero. La Pozza nera non le ostruiva più bocca e naso — al contrario, come liquido amniotico, sosteneva la sua vita."
  },
  AvgDialog_23856_Content_38 = {
    Text = [[
"Mi dispiace..."
"Io... non voglio ancora morire..."]]
  },
  AvgDialog_23856_Content_39 = {
    Text = "La superficie mantenne una calma prolungata. Neppure i venti polari ululanti riuscivano a increspare la pozza viscosa."
  },
  AvgDialog_23856_Content_4 = {Text = "D-davvero?"},
  AvgDialog_23856_Content_40 = {
    Text = "Lady Miryam, la Fanciulla Divina potrebbe già aver..."
  },
  AvgDialog_23856_Content_41 = {
    Text = "È nata durante l'ultimo <Blue:allineamento stellare> — una bambina che \"vede\"."
  },
  AvgDialog_23856_Content_42 = {
    Text = "Nessuno al mondo è più degno del riconoscimento della stirpe divina."
  },
  AvgDialog_23856_Content_43 = {
    Text = "La Donna emaciata stava in piedi al centro del cerchio, arroccata nel punto più alto a dominare ogni cosa.\nI veli ne celavano i lineamenti; neppure i più fidati collaboratori potevano scrutarne i pensieri."
  },
  AvgDialog_23856_Content_44 = {Text = "Murphy..."},
  AvgDialog_23856_Content_45 = {
    Text = "Con quel mormorio, come se un'energia geotermica fosse eruttata, la superficie prese a ribollire d'improvviso."
  },
  AvgDialog_23856_Content_46 = {
    Text = "L'acqua nera densa e viscosa traboccò dagli argini, lambendo i piedi, fluendo fino alle piante nude della Donna."
  },
  AvgDialog_23856_Content_47 = {
    Text = "Facendosi largo tra i sussulti sommessi dei giovani cultisti, percorse in silenzio il sentiero di liquido nero, immergendo le mani nel profondo della pozza—"
  },
  AvgDialog_23856_Content_48 = {Text = "—Splash"},
  AvgDialog_23856_Content_49 = {
    Text = "La ragazza si aggrappò alle sue mani, balzando fuori dalla vasca.\nIl liquido nero ne seguiva i contorni del volto, come due raccapriccianti scie di lacrime."
  },
  AvgDialog_23856_Content_5 = {
    Text = "Tutto bene. I Navigatori sul ponte l'hanno seguito fuori.\nDai, prendi la mia mano—ti aiuto a uscire."
  },
  AvgDialog_23856_Content_50 = {
    Text = "Heh, niente male. Sembra che <Blue:Dio> abbia accettato la nuova <Blue:Madre>."
  },
  AvgDialog_23856_Content_51 = {
    Text = "L'osservazione brusca di Golia grondava scherno, eppure nessuno badava più al suo sarcasmo."
  },
  AvgDialog_23856_Content_52 = {
    Text = "La Fanciulla Divina... ci è riuscita? Ce l'abbiamo fatta!"
  },
  AvgDialog_23856_Content_53 = {
    Text = "Le Preghiere si levavano a ondate, armonizzandosi nella caverna gelida — fanatiche, contorte, assordanti."
  },
  AvgDialog_23856_Content_54 = {
    Text = "Miryam, come desideravi, ho fatto ciò che mi hai chiesto."
  },
  AvgDialog_23856_Content_55 = {
    Text = "Lui... pulsa qui, adesso."
  },
  AvgDialog_23856_Content_56 = {
    Text = "Non solo Murphy—anche Miryam lo sentì.\nDue cuori con ritmi discordanti pulsavano nel petto della ragazza."
  },
  AvgDialog_23856_Content_57 = {
    Text = "Ora, rispondi alla mia domanda?"
  },
  AvgDialog_23856_Content_58 = {
    Text = "Chiedi pure."
  },
  AvgDialog_23856_Content_59 = {
    Text = "Mi hai cresciuta fin dall'inizio... solo per il giorno d'oggi?"
  },
  AvgDialog_23856_Content_6 = {
    Text = "Non appena Murphy si alzò, il tentacolo di Tulu le si avvolse stretto attorno alla caviglia, al tuo cenno silenzioso."
  },
  AvgDialog_23856_Content_60 = {Text = "..."},
  AvgDialog_23856_Content_61 = {Text = "No."},
  AvgDialog_23856_Content_62 = {
    Text = "Tu sei la mia \"Fanciulla Divina\", destinata a fare da ponte verso il reame divino... Dopodiché, la tua anima ascenderebbe lassù."
  },
  AvgDialog_23856_Content_63 = {
    Text = "Il rito di oggi non era previsto... ma non temere.\nDopo il rituale di nascita divina, preserverò la tua essenza—non vagherai nella notte eterna."
  },
  AvgDialog_23856_Content_64 = {
    Text = "Anima, essenza..."
  },
  AvgDialog_23856_Content_65 = {
    Text = "La mia morte era fissata per questo cosiddetto \"allineamento stellare\" fin dal principio, vero?"
  },
  AvgDialog_23856_Content_66 = {
    Text = "Miryam chiuse brevemente gli occhi, distogliendosi dalle domande per affrontare i seguaci in delirio.\nAlzò le braccia. Il liquido nero scivolò lungo le pieghe della sua pelle, tingendo istantaneamente il suo velo di un nero profondo."
  },
  AvgDialog_23856_Content_67 = {
    Text = "La Madre Divina è giunta!"
  },
  AvgDialog_23856_Content_68 = {
    Text = "Egli si risveglierà da @1, inaugurando @2!"
  },
  AvgDialog_23856_Content_69 = {
    Text = "Egli si risveglierà da @1, inaugurando @2!"
  },
  AvgDialog_23856_Content_7 = {
    Text = "C-cosa?! Lo so che mollarti per affrontare Golia da solo è stato meschino..."
  },
  AvgDialog_23856_Content_70 = {
    Text = "Tre mesi dopo"
  },
  AvgDialog_23856_Content_71 = {
    Text = "Stai dando altri grattacapi a quella donna. Non eri così brava qualche mese fa?\nCosa, non ascolti più la mamma?"
  },
  AvgDialog_23856_Content_72 = {
    Text = "La ragazza lanciò un'occhiata a Golia, conficcando il coltello con ferocia nel legno, gettando via attrezzo e materiale."
  },
  AvgDialog_23856_Content_73 = {
    Text = "Ma... mamma?"
  },
  AvgDialog_23856_Content_74 = {
    Text = "Tu... dove hai imparato quel termine?"
  },
  AvgDialog_23856_Content_75 = {
    Text = "Dizionario! Guarda: \"Donna adulta che si prende cura di un bambino, con legame affettivo.\""
  },
  AvgDialog_23856_Content_76 = {
    Text = "No... non sarò la tua mamma."
  },
  AvgDialog_23856_Content_77 = {
    Text = "Sei la Fanciulla Divina del culto, una predestinata alla gloria... Se lo desideri, chiamami per nome."
  },
  AvgDialog_23856_Content_78 = {
    Text = "Ehm... Miry... am?"
  },
  AvgDialog_23856_Content_79 = {
    Text = "Sì, Fanciulla Divina."
  },
  AvgDialog_23856_Content_8 = {
    Text = "M-ma se era me che cercava, farmi prendere significa che è finita per me! I-io..."
  },
  AvgDialog_23856_Content_80 = {
    Text = "...Non è mia madre, non lo è mai stata."
  },
  AvgDialog_23856_Content_81 = {
    Text = "Solo i vertici della Chiesa dei Portatori di Luce sanno da dove vengo. Non ho una mamma — sono solo il loro dono a Miryam."
  },
  AvgDialog_23856_Content_82 = {
    Text = "Eh? Ti ha raccontato anche quello?"
  },
  AvgDialog_23856_Content_83 = {
    Text = "Per un Prigioniero con una condanna a morte, i segreti non contano — finiranno tutti nella tomba con me."
  },
  AvgDialog_23856_Content_84 = {
    Text = "È il suo modo di farsi perdonare. Sai, il giorno in cui ti hanno impiantato il Dio dentro, la nostra somma sacerdotessa ha pianto Insonne."
  },
  AvgDialog_23856_Content_85 = {
    Text = "Addolorata? Che scherzo — lei non prova nulla del genere."
  },
  AvgDialog_23856_Content_86 = {
    Text = "Così fredda, piccola Principessa.\nLe bambine troppo glaciali fanno rattristare la mamma, lo sai."
  },
  AvgDialog_23856_Content_87 = {
    Text = "Stai zitto! Ho detto che non è mia madre!"
  },
  AvgDialog_23856_Content_88 = {
    Text = "Non esserne così sicuro. Vuoi sentire una storia?"
  },
  AvgDialog_23856_Content_89 = {
    Text = [[
<BigShake:No, e non voglio vederti!>
Se sei qui solo per deridermi, vattene!]]
  },
  AvgDialog_23856_Content_9 = {Text = "Murphy."},
  AvgDialog_23856_Content_90 = {
    Text = "No, invece sì."
  },
  AvgDialog_23856_Content_91 = {
    Text = "Il tono di Golia si fece grave, venato di un'Autorità da campo di Battaglia. I due cuori di Murphy quasi si fermarono per lo spavento."
  },
  AvgDialog_23856_Content_92 = {
    Text = [[
Si rese conto all'improvviso: il gigante non era mai stato un giocattolo con cui trastullarsi.
Aveva tirato troppo la corda con il suo status, e lui si era semplicemente goduto lo spettacolo.]]
  },
  AvgDialog_23856_Content_93 = {
    Text = "S-Sì, prego, continua pure."
  },
  AvgDialog_23856_Content_94 = {
    Text = "C'è questa setta segreta ossessionata dalla purezza del sangue — tutti i matrimoni decretati dal capo. Chiunque sposi degli estranei e si riproduca viene epurato, prima o poi."
  },
  AvgDialog_23856_Content_95 = {
    Text = "Nell'ultima epurazione, l'esecutore riportò una neonata — una bambina capace di vedere gli spiriti."
  },
  AvgDialog_23856_Content_96 = {
    Text = "Una bambina..."
  },
  AvgDialog_23856_Content_97 = {
    Text = "Era rimasta nascosta troppo a lungo in un vano segreto sotto sua madre. Quando i cultisti la trovarono, aveva quasi soffocato nel sangue della madre naturale."
  },
  AvgDialog_23856_Content_98 = {
    Text = "La più grande impresa di quella donna mediocre e insignificante? Mettere al mondo una figlia eccezionale e cercare di impedire alla setta di portarla via."
  },
  AvgDialog_23856_Content_99 = {
    Text = "—Che commovente amore tra madre e figlia. Mi viene da piangere."
  },
  AvgDialog_23857_Content_1 = {
    Text = "Seme del Destino"
  },
  AvgDialog_23857_Content_10 = {
    Text = "Quanto manca ancora?"
  },
  AvgDialog_23857_Content_11 = {
    Text = "Ancora per cosa?"
  },
  AvgDialog_23857_Content_12 = {
    Text = "Il Dio. Quanto manca alla Sua nascita?"
  },
  AvgDialog_23857_Content_13 = {
    Text = "...Non lo so. Perché non verifichi tu stessa? Dal modo in cui parli di Miryam e Golia, sei già invischiata fino al collo in questa faccenda, no?"
  },
  AvgDialog_23857_Content_14 = {
    Text = "La ragazza non esitò. Iniziò a sbottonarsi i vestiti con rapida determinazione.\nQuando l'ultimo bottone si aprì, vedeste il \"dio\" dentro di lei."
  },
  AvgDialog_23857_Content_15 = {
    Text = "Il suo torso sotto la camicia aperta era crudelmente trasparente, la pelle e i muscoli tesi allo spasimo, rendendo petto e addome di un bianco spettrale e putrescente."
  },
  AvgDialog_23857_Content_16 = {
    Text = "L'anomalia metteva a nudo i suoi organi: un cuore rosso pallido, giovane e pulsante, e un \"uovo\" lattiginoso."
  },
  AvgDialog_23857_Content_17 = {
    Text = "Innumerevoli filamenti sottili germogliavano dall'uovo, intrecciandosi con i vasi sanguigni di Murphy in una danza simbiotica."
  },
  AvgDialog_23857_Content_18 = {
    Text = "Se non fosse stato per il modo in cui premeva contro il suo cuore, sarebbe potuto sembrare una parte naturale del suo corpo traslucido, non un intruso estraneo."
  },
  AvgDialog_23857_Content_19 = {
    Text = "Caotico eppure silenzioso, recava un triangolo invertito e immobile di segni neri, come un'opera d'arte grottesca."
  },
  AvgDialog_23857_Content_2 = {
    Text = "La setta dei Navigatori, il rito distrutto dalle squadre di spedizione, l'ospite precedente contaminato dalla Dissoluzione... e il \"Dio\" dentro di te..."
  },
  AvgDialog_23857_Content_20 = {
    Text = "Dissoluzione... quella cosa è stata marchiata dalla Dissoluzione."
  },
  AvgDialog_23857_Content_21 = {
    Text = "Ti sei stancato di fissare?"
  },
  AvgDialog_23857_Content_22 = {
    Text = "Scusa... per favore, riabbottonati."
  },
  AvgDialog_23857_Content_23 = {
    Text = "Murphy abbassò il capo, sistemandosi i vestiti mentre ti lanciava un'occhiata."
  },
  AvgDialog_23857_Content_24 = {
    Text = "Continuavi a menzionare la \"Dissoluzione.\" È così che chiamate quelle ferite nere su di Esso?"
  },
  AvgDialog_23857_Content_25 = {
    Text = "Il ricettacolo precedente... colei che portava davvero questa cosa, era ricoperta di quei segni."
  },
  AvgDialog_23857_Content_26 = {
    Text = "Se la Dissoluzione non l'avesse indebolita, io non sarei stata..."
  },
  AvgDialog_23857_Content_27 = {
    Text = "La sua voce si spense.\nIngoiò il resto delle parole, premendosi una mano sul petto, l'espressione cupa."
  },
  AvgDialog_23857_Content_28 = {
    Text = [[
Tulu, hai visto che aspetto ha quel dio.
Quanto manca prima che sia completamente cresciuto?]]
  },
  AvgDialog_23857_Content_29 = {
    Text = "È straordinariamente robusto, quasi completo...\nManca solo la guida delle stelle per spingerlo a squarciare il corpo del suo involucro."
  },
  AvgDialog_23857_Content_3 = {
    Text = "Hai incontrato parecchie persone con corpi modificati — Aigis, la signorina Mason, Lily, Lisa..."
  },
  AvgDialog_23857_Content_30 = {
    Text = "Sono stupito che tu riesca ancora a muoverti liberamente, persino adesso."
  },
  AvgDialog_23857_Content_31 = {
    Text = "Quindi... è già così vicino..."
  },
  AvgDialog_23857_Content_32 = {
    Text = "Non ho ancora perso conoscenza perché <Blue:Celeste> mi ha aiutata."
  },
  AvgDialog_23857_Content_33 = {Text = "Celeste?"},
  AvgDialog_23857_Content_34 = {
    Text = "Murphy contemplò il cielo, un vortice di sfumature strane e luminescenti.\nGli uccelli volteggiavano sotto il velo scintillante, la luce soffusa e distorta, a proteggere la nave da qualsiasi tempesta al di là."
  },
  AvgDialog_23857_Content_35 = {
    Text = "Gli appunti del culto del Navigatore sono ossessionati dall'<Blue:allineamento stellare>, e insistono che il rito di nascita debba avvenire in un istante preciso. Ecco perché quella donna voleva farmi addormentare."
  },
  AvgDialog_23857_Content_36 = {
    Text = "Il Capitano ipotizzò che la crescita del dio potesse essere legata ai cicli celesti.\nCosì Celeste tessé questo Dominio Isolato attorno alla nave."
  },
  AvgDialog_23857_Content_37 = {
    Text = "Ci avevamo visto giusto — da quando abbiamo lasciato il vero cielo alle spalle, Esso è caduto in letargo. Se riusciamo a restare su questa nave per tutta la durata di questo <Blue:allineamento stellare>, forse dormirà per sempre."
  },
  AvgDialog_23857_Content_38 = {
    Text = "Quindi Celeste ha creato questo Dominio, ed è lei a governare la Sona-Nyl, quella che si credeva affondata."
  },
  AvgDialog_23857_Content_39 = {
    Text = "Sembra che anche lei sia una Risvegliatrice.\nAspetta... è lei quella che hai detto potrebbe aiutarci a trovare Ramona?"
  },
  AvgDialog_23857_Content_4 = {
    Text = "Ma trapiantare un <Blue:\"Dio\"> in una persona viva? Questo è semplicemente..."
  },
  AvgDialog_23857_Content_40 = {
    Text = "Esattamente. Nulla su questa nave sfugge al suo sguardo."
  },
  AvgDialog_23857_Content_41 = {
    Text = "Dev'essere con il Capitano, nascosta dai Navigatori. Se la troviamo, rintracciare la tua amica sarà un gioco da ragazzi."
  },
  AvgDialog_23857_Content_42 = {
    Text = "In altre parole, che si aiuti prima te o si salvi Ramona, Celeste è la chiave."
  },
  AvgDialog_23857_Content_43 = {
    Text = "Tulu tacque, inclinando il capo per osservarti, in attesa della tua decisione."
  },
  AvgDialog_23857_Content_44 = {
    Text = "In effetti, che si trattasse di riportare la nave a terra, fermare il rito di nascita o salvare Ramona, l'unico sentiero da percorrere era trovare Celeste."
  },
  AvgDialog_23857_Content_45 = {
    Text = [[
Murphy, facci strada.
Trova il capitano. Trova Celeste.]]
  },
  AvgDialog_23857_Content_5 = {
    Text = "Cos'è quello sguardo? Non mi credi? Va bene, non mi aspettavo che capissi subito."
  },
  AvgDialog_23857_Content_6 = {
    Text = "Scusa... è solo che tutto questo è troppo assurdo da comprendere."
  },
  AvgDialog_23857_Content_7 = {
    Text = "Murphy, posso vedere quel... \"Dio\"?"
  },
  AvgDialog_23857_Content_8 = {
    Text = "E dici che non stai dubitando!"
  },
  AvgDialog_23857_Content_9 = {
    Text = "I-Io stavo solo..."
  },
  AvgDialog_23858_Content_1 = {
    Text = "Imboscata da ogni lato"
  },
  AvgDialog_23858_Content_10 = {
    Text = "Siamo al <Blue:Terzo Molo> della <Blue:città di Bridgeport>, impegnati contro ostili sconosciuti."
  },
  AvgDialog_23858_Content_11 = {
    Text = "Ricerca degli investigatori sul campo più vicini in corso...\nL'Investigatore Delapore è atteso al Terzo molo tra trenta minuti."
  },
  AvgDialog_23858_Content_12 = {
    Text = "Trenta è troppo. La strada sud brulica di nemici — sfonderemo a nord."
  },
  AvgDialog_23858_Content_13 = {
    Text = "Conducente avvisato per il recupero all'uscita nord del Terzo Molo."
  },
  AvgDialog_23858_Content_14 = {
    Text = "Ostili sconosciuti? Non la <Yellow:Chiesa dei Portatori di Luce>?"
  },
  AvgDialog_23858_Content_15 = {
    Text = "Registrare nuove informazioni sul nemico?"
  },
  AvgDialog_23858_Content_16 = {
    Text = "Per favore, Erica—non ora."
  },
  AvgDialog_23858_Content_17 = {
    Text = "Umanoidi con tratti acquatici non documentati; rapporto in arrivo al ritorno."
  },
  AvgDialog_23858_Content_18 = {
    Text = "%player%, resta in guardia e preparati alla sortita."
  },
  AvgDialog_23858_Content_2 = {
    Text = "Tre ore prima\nCittà portuale di Bridgeport\nTerzo molo"
  },
  AvgDialog_23858_Content_3 = {
    Text = "%player%, attento dietro di te!"
  },
  AvgDialog_23858_Content_5 = {
    Text = [[
Rilevate onde ad alta frequenza non in stato di allerta; collegamento comunicazioni automatico.
Ancora una volta, buonasera, Custode, Ramona.]]
  },
  AvgDialog_23858_Content_6 = {
    Text = "Sembra che qualcuno sia terrorizzato a morte."
  },
  AvgDialog_23858_Content_7 = {
    Text = "Si prega di astenersi da interferenze verbali non necessarie con il personale operativo sul campo."
  },
  AvgDialog_23858_Content_8 = {
    Text = [[
Va bene, va bene.
Allora, serve una mano?]]
  },
  AvgDialog_23858_Content_9 = {
    Text = "Ci servono rinforzi!"
  },
  AvgDialog_23859_Content_1 = {
    Text = "Senza Scampo"
  },
  AvgDialog_23859_Content_10 = {
    Text = "Come pensavo—non ci stanno seguendo quassù..."
  },
  AvgDialog_23859_Content_11 = {
    Text = "Ramona abbassò la voce fino a un sussurro."
  },
  AvgDialog_23859_Content_12 = {
    Text = "Questi uomini-pesce sono bloccati dalla Sona-Nyl, ma per qualche ragione la nave ha lasciato salire noi."
  },
  AvgDialog_23859_Content_13 = {
    Text = "Siamo noi la chiave per entrare. Una volta che saranno a bordo anche loro, saremo sacrificabili."
  },
  AvgDialog_23859_Content_14 = {
    Text = "Esattamente. Quindi... ho un'idea."
  },
  AvgDialog_23859_Content_15 = {
    Text = "Hai posato il piede sull'ultimo gradino della passerella."
  },
  AvgDialog_23859_Content_16 = {
    Text = "I vostri occhi furono sfiorati da una brezza tiepida, delicata come la carezza del cielo su un uccello in volo, e il mondo sembrò capovolgersi davanti a voi."
  },
  AvgDialog_23859_Content_17 = {
    Text = "L'enorme luna piena svanì dal cielo. Aloni simili ad aurore si attorcigliarono attorno allo scafo della nave, proiettando tonalità sinistre sul ponte."
  },
  AvgDialog_23859_Content_18 = {
    Text = "Ramona, qualcosa non va!"
  },
  AvgDialog_23859_Content_19 = {
    Text = "La passerella tremò. Ora che eravate al sicuro sul ponte, gli uomini-pesce abbandonarono la sorveglianza, arrampicandosi con mani e piedi."
  },
  AvgDialog_23859_Content_2 = {
    Text = "Tre ore prima\nCittà portuale di Bridgeport\nTerzo molo"
  },
  AvgDialog_23859_Content_20 = {
    Text = "Troppo tardi—stanno salendo."
  },
  AvgDialog_23859_Content_21 = {
    Text = "Ramona calò la spada con tutta la sua forza, frantumando il fermo di sicurezza. La passerella precipitò nel vuoto, ma nessun tonfo riecheggiò dal basso."
  },
  AvgDialog_23859_Content_22 = {
    Text = "Il cuore vi martellava furiosamente. Le anomalie della nave vi inondavano la mente. Passò un istante prima che uno dei due riuscisse a parlare di nuovo."
  },
  AvgDialog_23859_Content_23 = {
    Text = "Almeno da questo lato non possono salire a bordo."
  },
  AvgDialog_23859_Content_24 = {
    Text = "Le cose che si vedono su questa nave... corrispondono decisamente alla mia idea di nave fantasma."
  },
  AvgDialog_23859_Content_25 = {
    Text = "Nessun suono quando la passerella è caduta — significa che probabilmente ci troviamo in uno spazio isolato. Interessante, no?"
  },
  AvgDialog_23859_Content_26 = {
    Text = "Questo è un <Yellow:Dominio> visibile."
  },
  AvgDialog_23859_Content_27 = {
    Text = "La nebbia attorno alla scuola funziona con la <Yellow:Tecnologia d'Argento>. Chissà quale forza alimenta questa nave?"
  },
  AvgDialog_23859_Content_28 = {
    Text = "Potrebbe essere un Risvegliatore?"
  },
  AvgDialog_23859_Content_29 = {
    Text = "Nessun documento simile nell'archivio, ma in teoria un Risvegliato potrebbe creare uno spazio isolato — vuoi i dettagli?"
  },
  AvgDialog_23859_Content_3 = {
    Text = "L'odore acre del ferro arrugginito vi assalì le narici. A ogni passo, la passerella gemeva sotto i piedi, sull'orlo del cedimento."
  },
  AvgDialog_23859_Content_30 = {
    Text = "Risparmiami..."
  },
  AvgDialog_23859_Content_31 = {
    Text = "Doll, mi senti?"
  },
  AvgDialog_23859_Content_32 = {
    Text = "Dai, cerca di capire la situazione!"
  },
  AvgDialog_23859_Content_33 = {
    Text = "Scusa, scusa. Perdona la mia curiosità."
  },
  AvgDialog_23859_Content_34 = {
    Text = "Doll, mi senti?"
  },
  AvgDialog_23859_Content_35 = {
    Text = "Ramona sfiorò la sua spilla. Un debole bagliore tremolò sulla superficie argentea del comunicatore."
  },
  AvgDialog_23859_Content_36 = {Text = "Hmm...?"},
  AvgDialog_23859_Content_37 = {
    Text = "Ramona si sporse e sfiorò il tuo comunicatore.\nConcentrasti la mente come al solito, ma non accadde nulla."
  },
  AvgDialog_23859_Content_38 = {
    Text = "La tua energia mentale si dissipò come lacrime nell'oceano, dissolvendosi nel silenzio."
  },
  AvgDialog_23859_Content_39 = {
    Text = "Dall'esterno sembra intatto, ma nessun segnale riesce a uscire."
  },
  AvgDialog_23859_Content_4 = {
    Text = "Nessun segno di manutenzione o riparazioni, ma a parte l'età, lo scafo sembra abbastanza solido.\nNessuna corrosione evidente da acqua salata, e niente attaccato sotto la linea di galleggiamento—né cirripedi, né ostriche..."
  },
  AvgDialog_23859_Content_40 = {
    Text = "<Small:Perché c'è sempre qualcosa che blocca le comunicazioni? Anche l'ultima volta al Museo delle Cere...>"
  },
  AvgDialog_23859_Content_41 = {
    Text = "La tecnologia Argento non è infallibile.\nE poi, stiamo solo scalfendo la superficie con l'Argento."
  },
  AvgDialog_23859_Content_42 = {
    Text = "Speriamo che quegli uomini-pesce non sbuchino da qualche altra parte..."
  },
  AvgDialog_23859_Content_43 = {
    Text = "Già. Resta in allerta, e prega che questa nave non spieghi le vele."
  },
  AvgDialog_23859_Content_44 = {
    Text = "<Big:Woo—>"
  },
  AvgDialog_23859_Content_45 = {
    Text = "Come un'allodola che risponde al trillo di un cantante d'opera, un lungo squillo di corno rispose alla preghiera di Ramona."
  },
  AvgDialog_23859_Content_46 = {Text = "..."},
  AvgDialog_23859_Content_47 = {Text = "..."},
  AvgDialog_23859_Content_48 = {
    Text = "So cosa stai pensando, ma per favore... non ora."
  },
  AvgDialog_23859_Content_49 = {
    Text = "Non possiamo salpare con la Sona-Nyl. Troppe anomalie su questa nave."
  },
  AvgDialog_23859_Content_5 = {
    Text = "Tu e Ramona saliste fianco a fianco lungo la passerella traballante. Il sentiero davanti a voi si dissolveva in una nebbia vorticosa, oscurando tutto ciò che si trovava oltre."
  },
  AvgDialog_23859_Content_50 = {
    Text = "Controlla l'altro lato del ponte! Vedo le cime di una scialuppa — proviamo a fuggire via mare."
  },
  AvgDialog_23859_Content_51 = {
    Text = "Aspetta... sento qualcosa."
  },
  AvgDialog_23859_Content_53 = {
    Text = "Volti simili a pesci emersero sul ponte. I responsabili che vi avevano inseguito a bordo si fecero più vicini."
  },
  AvgDialog_23859_Content_6 = {
    Text = "Trovato qualcosa?"
  },
  AvgDialog_23859_Content_7 = {
    Text = "La Sona-Nyl non corrisponde al profilo di una nave fantasma affondata. Contraddice i registri che la danno come inabissata durante una tempesta."
  },
  AvgDialog_23859_Content_8 = {
    Text = "Mi piacerebbe indagare sulla storia di questa nave, ma non è il momento."
  },
  AvgDialog_23859_Content_9 = {
    Text = "Si voltò a guardare. I nemici che vi avevano sospinto sulla passerella si ammassavano in basso, i loro vacui occhi di pesce fissi nei vostri."
  },
  AvgDialog_23860_Content_1 = {
    Text = "L'Indulgente"
  },
  AvgDialog_23860_Content_10 = {
    Text = "Finalmente, un volto al tempo stesso familiare e sconosciuto."
  },
  AvgDialog_23860_Content_11 = {
    Text = "*Coff, coff, coff...!*"
  },
  AvgDialog_23860_Content_12 = {
    Text = "L'aria secca si mescolò all'acqua marina ancora presente nella trachea, irritando le vie respiratorie come mai prima. I muscoli ebbero degli spasmi, scatenando colpi di tosse incontrollabili."
  },
  AvgDialog_23860_Content_13 = {
    Text = "Il ragazzo dai capelli verdi aggrottò leggermente le sopracciglia. Sotto il suo controllo, i tentacoli ti avvolsero ancora una volta, poi—"
  },
  AvgDialog_23860_Content_14 = {
    Text = "I tentacoli si contrassero con forza calibrata più volte, espellendo acqua marina e piccoli pesci dalla tua gola."
  },
  AvgDialog_23860_Content_15 = {
    Text = "*Coff, coff...* Grazie."
  },
  AvgDialog_23860_Content_16 = {
    Text = "Non c'è bisogno di ringraziare. La tua voce è troppo forte: attirerà gli altri Navigatori."
  },
  AvgDialog_23860_Content_17 = {
    Text = "...Intendo, per avermi tirato fuori dal mare."
  },
  AvgDialog_23860_Content_18 = {
    Text = "Sebbene diventare un Risvegliatore non fosse il mio desiderio, l'Università di Mythag ha posto fine al mio sonno millenario.\nPer ragione e sentimento, non abbandonerò un \"Custode\" alla morte."
  },
  AvgDialog_23860_Content_19 = {
    Text = [[
Ma... tu non dovresti essere qui, giusto?
Il registro per questa indagine include solo me e Ramona.]]
  },
  AvgDialog_23860_Content_2 = {
    Text = "L'acqua si riversava senza sosta nel tuo corpo.\nNarici, orecchie, gola, occhi... ogni orifizio della parte superiore del corpo si riempì di acqua marina."
  },
  AvgDialog_23860_Content_20 = {
    Text = "Senza l'approvazione del responsabile delle operazioni sul campo, e senza il vincolo di un Investigatore, ai Risveglio non è permesso oltrepassare i confini di Mythag. Pensavo lo sapessi..."
  },
  AvgDialog_23860_Content_21 = {
    Text = "Risveglio Tulu, Fascicolo N. 6291. Nome in codice: \"Sovrano Dormiente.\""
  },
  AvgDialog_23860_Content_22 = {
    Text = "Sai bene che quelle cosiddette \"Regole\" dell'Università di Mythag non significano nulla per me."
  },
  AvgDialog_23860_Content_23 = {
    Text = "E non usare quello stupido nome in codice con me."
  },
  AvgDialog_23860_Content_24 = {Text = "Tulu."},
  AvgDialog_23860_Content_25 = {
    Text = "Non sono uno di quei tipi rigidi del Comitato. Per me, i Risveglio non sono Bestie da incatenare."
  },
  AvgDialog_23860_Content_26 = {
    Text = "La mia preoccupazione è che non sei nella lista della missione sul campo, non collegato da nessuno.\nSe ti allontani troppo a lungo dalla <Yellow:Pozza Nera> di Mythag, cadrai in preda alla frenesia."
  },
  AvgDialog_23860_Content_27 = {
    Text = "Non importa. Non mi lascerò governare da cosiddetti istinti."
  },
  AvgDialog_23860_Content_28 = {
    Text = "Il Risveglio conservava le sembianze di un ragazzo, eppure ogni parola e ogni gesto trasudavano l'Autorità di un superiore.\nUn semplice sguardo fugace bastava a far rizzare i capelli."
  },
  AvgDialog_23860_Content_29 = {Text = "...Sigh."},
  AvgDialog_23860_Content_3 = {
    Text = "Il tuo sangue reagì in qualche modo con l'acqua marina. Le cellule venivano espulse dal tuo organismo, sostituite da quello che sembrava sale grossolano e graniglia che scorrevano nelle tue vene."
  },
  AvgDialog_23860_Content_30 = {
    Text = "—Voglio solo sapere cosa ci fai qui.\nDormi tutto l'anno, senza smuoverti nemmeno per l'anomalia alla <Yellow:cerimonia di conferimento delle chiavi>."
  },
  AvgDialog_23860_Content_31 = {
    Text = "Eppure rischi di perdere la ragione per venire qui... Qualunque cosa sia accaduta, deve significare molto per te."
  },
  AvgDialog_23860_Content_32 = {
    Text = "Tutto ciò che si sta svolgendo qui ha origine da me.\nQuanto ai dettagli, non ti riguardano."
  },
  AvgDialog_23860_Content_33 = {
    Text = "Davvero? Non mi riguarda, nemmeno quando io e Ramona ci siamo imbattuti in quella Donna, Miryam, e tu a malapena ti sei fatto vivo per aiutare?"
  },
  AvgDialog_23860_Content_34 = {
    Text = "Non ti devo alcuna spiegazione, ma se necessario, presterò il mio aiuto."
  },
  AvgDialog_23860_Content_35 = {
    Text = "L'atteggiamento ermetico di Tulu quasi accese la tua Rabbia, ma la realtà preservò la tua ragione."
  },
  AvgDialog_23860_Content_36 = {
    Text = "Le tue mani si strinsero, poi si rilassarono ancora una volta. Dopo qualche respiro profondo, ti voltasti infine verso il ragazzo Risveglio dinanzi a te."
  },
  AvgDialog_23860_Content_37 = {
    Text = "Ramona è nelle mani dei Navigatori. Tulu, ho bisogno del tuo aiuto."
  },
  AvgDialog_23860_Content_38 = {
    Text = "Tulu sollevò il capo, fissandoti negli occhi a lungo, come se stesse maturando parole di rifiuto."
  },
  AvgDialog_23860_Content_39 = {
    Text = "Proprio mentre le sue labbra fremevano, pronte a pronunciare una risposta, l'urlo lacerante di una Bambina riecheggiò dalle profondità della cabina."
  },
  AvgDialog_23860_Content_4 = {
    Text = "Raschiavano il tuo corpo e la tua anima dall'interno. I polmoni traboccavano di liquido. Mentre il corpo affondava, la coscienza svaniva, la preoccupazione per la tua compagna soffocata dal dolore e dal soffocamento..."
  },
  AvgDialog_23860_Content_40 = {
    Text = "Quella è Ramona!? Andiamo!"
  },
  AvgDialog_23860_Content_41 = {
    Text = "Non sappiamo quanti Navigatori ci siano a bordo. Lanciarsi senza Preparazione è davvero da stolti."
  },
  AvgDialog_23860_Content_42 = {Text = "Stupido?"},
  AvgDialog_23860_Content_43 = {
    Text = "Se, come dici, non abbandonerai un \"Custode\" alla morte..."
  },
  AvgDialog_23860_Content_44 = {
    Text = "Tulu, sto per andare incontro alla mia rovina."
  },
  AvgDialog_23860_Content_45 = {
    Text = "Tulu gli cullò il capo senza rispondere, ma mentre ti voltavi per lanciarti più in profondità nella cabina, colsi il sospiro flebile, quasi impercettibile, del ragazzo."
  },
  AvgDialog_23860_Content_5 = {Text = "..."},
  AvgDialog_23860_Content_6 = {
    Text = "Increspature agitarono la superficie del mare, infrangendosi contro i tuoi timpani. Lottasti per aprire gli occhi. Qualcosa si tuffò sotto le onde, stagliandosi contro la luce."
  },
  AvgDialog_23860_Content_7 = {
    Text = "Si avvolse agilmente attorno alla tua vita, come un'alga... no, non un'alga, ma un muscolo morbido eppure incredibilmente resistente..."
  },
  AvgDialog_23860_Content_8 = {Text = "Swish—"},
  AvgDialog_23860_Content_9 = {
    Text = "Il muscolo allungato ti trascinò verso l'alto. La luce rosata del cielo del Dominio entrò nel tuo campo visivo, seguita dalle travi del ponte inferiore, poi dalle lampade elettriche tremolanti nella cabina."
  },
  AvgDialog_23861_Content_1 = {
    Text = "I loro soli lineamenti grotteschi sembravano una bestemmia contro l'evoluzione."
  },
  AvgDialog_23861_Content_2 = {
    Text = "Si spintonavano a vicenda, le loro armi rozze cozzavano con fragore aspro. Nel caos, parevano raggrupparsi attorno a qualcosa..."
  },
  AvgDialog_23862_Content_1 = {
    Text = "Maledizione, maledizione, maledizione!"
  },
  AvgDialog_23862_Content_2 = {
    Text = "I Navigatori avrebbero dovuto essere fermati dal Dominio di Sona-Nyl. Se non fosse stato per questo inquietante piccolo bizzarro col mantello nero, avrei potuto sgattaiolare verso il nuovo continente senza preoccupazioni..."
  },
  AvgDialog_23862_Content_3 = {
    Text = "Ma... hanno abbattuto così tanti Navigatori... Che stiano davvero dicendo la verità?"
  },
  AvgDialog_23863_Content_1 = {
    Text = "Ma... da quando Miryam ha iniziato con questi trucchetti?\nMandare gente per attirarmi indietro... non è da lei."
  },
  AvgDialog_23863_Content_2 = {
    Text = "Murphy? Ci sei?"
  },
  AvgDialog_23863_Content_3 = {
    Text = "Tch, voi non mollate mai."
  },
  AvgDialog_23864_Content_1 = {
    Text = "Membro dell'Equipaggio"
  },
  AvgDialog_23864_Content_10 = {
    Text = "Hai usato quel trucchetto mentale per ficcanasare nella testa di Miryam, e ora lei sa che \"sei vivo\"... Persino un pesce morto sulla spiaggia capirebbe che non sei dalla loro parte."
  },
  AvgDialog_23864_Content_11 = {
    Text = "Qual è questo posto sicuro di cui parli?"
  },
  AvgDialog_23864_Content_12 = {
    Text = "Smettila di fare tante domande—stai zitto e seguimi."
  },
  AvgDialog_23864_Content_13 = {
    Text = "Murphy non si curò di verificare se tu e Tulu steste al passo. Con destrezza spinse un altro portello e vi scivolò attraverso con disinvoltura."
  },
  AvgDialog_23864_Content_14 = {
    Text = "Mentre ti preparavi a seguirla, Tulu allungò un tentacolo, sbarrandoti il passaggio tra te e la porta."
  },
  AvgDialog_23864_Content_15 = {
    Text = "Custode, non abbassare la guardia con questa bambina."
  },
  AvgDialog_23864_Content_16 = {Text = "Perché?"},
  AvgDialog_23864_Content_17 = {
    Text = "Tulu eluse la tua domanda con una delle sue."
  },
  AvgDialog_23864_Content_18 = {
    Text = "Dimmi, cosa pensi dei Navigatori?"
  },
  AvgDialog_23864_Content_19 = {
    Text = "Navigatori? Dita palmate, corpi simili a pesci sopra il coccige, che conservano una certa intelligenza."
  },
  AvgDialog_23864_Content_2 = {
    Text = "Murphy vi guidò attraverso le cabine, camminando in punta di piedi per eludere le pattuglie dei Navigatori."
  },
  AvgDialog_23864_Content_20 = {
    Text = "Forme sinuose e naturali—non come i pasticci dell'Associazione degli Scultori; quelli riducono sempre i loro esperimenti in orrori."
  },
  AvgDialog_23864_Content_21 = {
    Text = "Pensavo che il loro aspetto derivasse da mutazioni dopo l'esposizione al <Yellow:Cataclisma>, ma in questi scontri non ho individuato alcun <Yellow:D-segno> evidente su di loro."
  },
  AvgDialog_23864_Content_22 = {
    Text = "Navigatori... più che altro uno scherzo idiota dell'evoluzione sull'umanità."
  },
  AvgDialog_23864_Content_23 = {
    Text = "Venerano Miryam come somma sacerdotessa. Più che una tribù, un gruppo unito dalla fede."
  },
  AvgDialog_23864_Content_24 = {
    Text = "\"Uno scherzo idiota dell'evoluzione sull'umanità\"—apprezzo la tua metafora."
  },
  AvgDialog_23864_Content_25 = {
    Text = "Questa ragazza—Murphy. Quando l'abbiamo trovata, i Navigatori erano prostrati intorno a lei. E data la sua familiarità con Miryam, non è una semplice seguace."
  },
  AvgDialog_23864_Content_26 = {
    Text = "Dimmi, \"Murphy\" era presente nel Reame dello Spirito di Miryam?"
  },
  AvgDialog_23864_Content_27 = {
    Text = "Apristi la bocca, ma prima che le corde vocali vibrassero, un guaito soffocato e rumori confusi riecheggiarono da al di là della porta."
  },
  AvgDialog_23864_Content_3 = {
    Text = "Dove stiamo andando?"
  },
  AvgDialog_23864_Content_4 = {
    Text = "In un posto sicuro, a cercare qualcuno che possa aiutarci."
  },
  AvgDialog_23864_Content_5 = {
    Text = "La tua compagna non è stata rapita? Conosco una persona che conosce ogni angolo di questa nave."
  },
  AvgDialog_23864_Content_6 = {
    Text = "Trovala prima, poi falle localizzare la tua amica... Meglio che correre in giro come un pollo senza testa, no?"
  },
  AvgDialog_23864_Content_7 = {
    Text = "A proposito, non pensi più che siamo i cattivi?"
  },
  AvgDialog_23864_Content_8 = {
    Text = "Murphy ti lanciò un'occhiataccia, sbuffando come un gatto."
  },
  AvgDialog_23864_Content_9 = {
    Text = "Non sono mica un'idiota—ho sentito tutto quello che tu e il ragazzo-tentacolo vi siete detti."
  },
  AvgDialog_23865_Content_1 = {
    Text = "Basta. Sono insignificanti."
  },
  AvgDialog_23865_Content_2 = {
    Text = [[
Una figura se ne stava in silenzio dietro l'orda, e ora prese la parola.
Una donna adulta, il corpo avvolto in veli neri, spiccava nettamente tra gli orrendi e deformi uomini-pesce.]]
  },
  AvgDialog_23865_Content_3 = {
    Text = "L'allineamento si avvicina. Fedeli navigatori, credenti nel Reame Divino — ponete fine a questa farsa... Date il benvenuto alla <Blue:Madre Divina>. Accogliete il ritorno del Dio."
  },
  AvgDialog_23865_Content_4 = {
    Text = "Al suo comando, un ragazzo diverso dagli uomini-pesce circostanti si fece avanti.\nSi inchinò profondamente alla donna, il tono traboccante di lealtà e orgoglio non dissimulati."
  },
  AvgDialog_23865_Content_5 = {
    Text = "Come comandate, Lady Miryam."
  },
  AvgDialog_23866_Content_1 = {Text = "Laggiù!"},
  AvgDialog_23866_Content_10 = {
    Text = "Che state facendo!? Non avete il diritto di mettermi le mani addosso! Fatemi vedere Miryam, se ne avete il coraggio!"
  },
  AvgDialog_23866_Content_11 = {
    Text = "Miryam... è il nome della donna! Quindi questa bambina conosce il capo, ma perché questi Navigatori le danno la caccia..."
  },
  AvgDialog_23866_Content_12 = {
    Text = "Prima che potessi raccapezzarti, spessi tentacoli ti sfiorarono la spalla, avventandosi ferocemente sul Navigatore Serpentino."
  },
  AvgDialog_23866_Content_13 = {
    Text = "Quest'ultimo fu colto alla sprovvista ma reagì prontamente, sibilando con lingua biforcuta mentre si avvinghiava ai tentacoli di Tulu."
  },
  AvgDialog_23866_Content_2 = {
    Text = "@1Divina... Madre @2..."
  },
  AvgDialog_23866_Content_3 = {
    Text = "Diversi Navigatori formarono un cerchio, circondando un angolo della cabina. Intonavano una Cantilena con toni stridenti, quasi soffocando i singhiozzi della bambina."
  },
  AvgDialog_23866_Content_4 = {
    Text = "State... lontani da me! Non provate nemmeno a trascinarmi indietro!"
  },
  AvgDialog_23866_Content_5 = {
    Text = "Quella... non è Ramona."
  },
  AvgDialog_23866_Content_6 = {
    Text = "Il capo dei Navigatori si prostrò con reverenza dinanzi alla bambina, mentre gli altri le afferravano gli arti con palmi palmati."
  },
  AvgDialog_23866_Content_7 = {
    Text = "Il capo si alzò bruscamente. Solo allora vedesti che sotto il \"suo\" velo si contorcevano diverse teste di serpente danzanti, del tutto bizzarre."
  },
  AvgDialog_23866_Content_8 = {
    Text = "Quella dalla testa di serpente tracciò strane rune sul pavimento, poi accettò un sacco da un Navigatore. Un fetore nauseabondo emanava dall'interno."
  },
  AvgDialog_23866_Content_9 = {
    Text = "Le zanne squarciarono il sacco. Viscere putride ne fuoriuscirono come sardine, atterrando esattamente sulle rune. Un odore putrido permeò istantaneamente la cabina."
  },
  AvgDialog_23867_Content_1 = {
    Text = "Il Folle e la Grande Lama"
  },
  AvgDialog_23867_Content_10 = {
    Text = "Ma guarda cosa abbiamo davanti.\nSolo un muro sigillato—nemmeno una ventola in cui strisciare."
  },
  AvgDialog_23867_Content_11 = {
    Text = "Io... è solo che non scendo quaggiù da sola molto spesso. Di solito sono con il capitano e l'equipaggio."
  },
  AvgDialog_23867_Content_12 = {
    Text = "C'è una mappa del ponte sulla parete."
  },
  AvgDialog_23867_Content_13 = {
    Text = "Cosa vorresti dire? Metti in dubbio la mia memoria?"
  },
  AvgDialog_23867_Content_14 = {
    Text = "Ho detto che posso trovarlo, e lo troverò — il capitano dev'essere da questa parte!"
  },
  AvgDialog_23867_Content_15 = {
    Text = [[
La mia compagna aspetta il nostro aiuto.
La prego, Lady Murphy, controlli il piano.]]
  },
  AvgDialog_23867_Content_16 = {Text = "...Hmph!"},
  AvgDialog_23867_Content_17 = {
    Text = "Murphy batté il piede con forza, chinandosi con riluttanza a esaminare la planimetria della paratia."
  },
  AvgDialog_23867_Content_18 = {Text = "Hmm..."},
  AvgDialog_23867_Content_19 = {
    Text = "Fammi vedere."
  },
  AvgDialog_23867_Content_2 = {
    Text = "Strano... ricordo che il capitano disse di dirigersi verso la sala macchine in caso di problemi..."
  },
  AvgDialog_23867_Content_20 = {
    Text = "Per raggiungere la sala macchine, dobbiamo salire queste scale fino al ponte principale."
  },
  AvgDialog_23867_Content_21 = {
    Text = "S-sì! Ora ricordo — la sala macchine è sigillata ermeticamente, ma con un'unica via d'accesso è più sicura."
  },
  AvgDialog_23867_Content_22 = {
    Text = "Quindi dovremo tornare sul ponte."
  },
  AvgDialog_23867_Content_23 = {
    Text = "Ramona e io siamo stati vittima di un'imboscata dei Navigatori lassù... Il ponte è probabilmente infestato di pattuglie — dobbiamo stare attenti, evitare gli scontri se possibile."
  },
  AvgDialog_23867_Content_3 = {Text = "Murphy..."},
  AvgDialog_23867_Content_4 = {
    Text = "Shh, mi stai interrompendo i pensieri."
  },
  AvgDialog_23867_Content_5 = {
    Text = [[
Tacesti riguardo all'"interrompere i ragionamenti di Murphy."
Ma sapevi che dovevi impedirle di "ragionare" oltre.]]
  },
  AvgDialog_23867_Content_6 = {
    Text = "Sotto la guida di Murphy, il vostro trio raggiunse il fondo della stiva. Davanti a voi incombeva una fredda paratia d'acciaio, con solo una scala che saliva verso l'alto — nessun passaggio in avanti."
  },
  AvgDialog_23867_Content_7 = {
    Text = "Ti sei persa?"
  },
  AvgDialog_23867_Content_8 = {
    Text = "Ma figurati! Io non mi perdo!"
  },
  AvgDialog_23867_Content_9 = {
    Text = "Vivo su questa nave da mesi — conosco ogni condotto d'aerazione, ogni buco di topo."
  },
  AvgDialog_23872_Content_1 = {Text = "Apostolo"},
  AvgDialog_23880_Content_1 = {
    Text = "La nebbia nera allentò silenziosamente la presa su Sorel, dilagando senza meta in ogni direzione."
  },
  AvgDialog_23880_Content_10 = {
    Text = "Poi il mondo intorno a te iniziò a sgretolarsi."
  },
  AvgDialog_23880_Content_11 = {
    Text = "La cupola si staccava filo dopo filo come lanugine di salice. Il mondo visibile, come una vela travolta da un grande Vento, prima si deformò, poi fu lacerato e frantumato."
  },
  AvgDialog_23880_Content_12 = {
    Text = [[
20:58
Tempo al collasso del Dominio: <Red:2> minuti]]
  },
  AvgDialog_23880_Content_13 = {
    Text = "Il Dominio sta per collassare! Basta resistere fino all'ultimo secondo senza farci toccare da questa nebbia nera..."
  },
  AvgDialog_23880_Content_14 = {
    Text = "Avanzi barcollando fino al bordo della terrazza."
  },
  AvgDialog_23880_Content_15 = {
    Text = "No... Non abbiamo più nessun posto dove andare!"
  },
  AvgDialog_23880_Content_16 = {
    Text = "Alle tue spalle, la nebbia nera ruggente e vorticosa avanza come onde dell'oceano."
  },
  AvgDialog_23880_Content_17 = {
    Text = "E davanti si apre un abisso nero senza fine in vista."
  },
  AvgDialog_23880_Content_18 = {
    Text = [[
20:59
Tempo al collasso del Dominio: <Red:1> minuto]]
  },
  AvgDialog_23880_Content_19 = {
    Text = "Sorel ti prende dolcemente la mano."
  },
  AvgDialog_23880_Content_2 = {
    Text = "...Se n'è andato?"
  },
  AvgDialog_23880_Content_20 = {
    Text = "Tieni stretto stavolta, Custode."
  },
  AvgDialog_23880_Content_21 = {
    Text = "Un istante dopo, vi tuffate insieme nell'Oscurità profonda che si apre davanti a voi."
  },
  AvgDialog_23880_Content_22 = {
    Text = "L'Ululato del Vento ti riempie le orecchie, come se il dolce respiro degli dèi si rivoltasse nei loro Sogni."
  },
  AvgDialog_23880_Content_23 = {
    Text = "La mano di Sorel stringe forte la tua, i suoi capelli scompigliati si intrecciano con l'Oscurità. All'improvviso, le si apre un sorriso."
  },
  AvgDialog_23880_Content_24 = {
    Text = "Di cosa ridi?"
  },
  AvgDialog_23880_Content_25 = {
    Text = "...In questo momento sembri un vero Cavaliere."
  },
  AvgDialog_23880_Content_26 = {
    Text = "Un rispettabile, vero Cavaliere, costretto a salvare una falsa Principessa."
  },
  AvgDialog_23880_Content_27 = {
    Text = "Studi il Suo volto, così vicino al tuo. A differenza della perfezione impeccabile dei giorni passati, ora è coperto di ferite e colmo di stanchezza."
  },
  AvgDialog_23880_Content_28 = {
    Text = "Direi che... anche tu sembri una vera Principessa adesso."
  },
  AvgDialog_23880_Content_29 = {
    Text = "Gli occhi di Sorel si incurvano dolcemente, come un lago senza fondo, riflettendo al loro interno la tenue luce delle stelle."
  },
  AvgDialog_23880_Content_3 = {
    Text = "Sorel chiuse dolcemente gli occhi."
  },
  AvgDialog_23880_Content_30 = {
    Text = "È un onore, %player%."
  },
  AvgDialog_23880_Content_32 = {
    Text = "La nebbia nera sempre diffusa è rimasta lontana alle vostre spalle. Stringi forte Sorel e ti lasci cadere in caduta libera attraverso l'Oscurità a velocità vertiginosa."
  },
  AvgDialog_23880_Content_33 = {
    Text = [[
21:00
<Red:Collasso del Dominio>]]
  },
  AvgDialog_23880_Content_34 = {
    Text = "Dong— dong—"
  },
  AvgDialog_23880_Content_35 = {
    Text = "I rintocchi dell'ora si diffusero senza fretta, sprofondando fino nelle profondità dell'abisso."
  },
  AvgDialog_23880_Content_36 = {
    Text = "Poi senti il suono del Dominio che si frantuma, come un cuore che esplode in qualche luogo remoto dove nessuno se ne accorgerebbe."
  },
  AvgDialog_23880_Content_37 = {
    Text = "Senti anche il suono di ossa che si spezzano e di carne che vola in tutte le direzioni."
  },
  AvgDialog_23880_Content_38 = {
    Text = "Un tenue profumo di rose ti raggiunge il naso. Chiudi gli occhi e, per la prima volta, senti un peso sollevarsi dalle spalle."
  },
  AvgDialog_23880_Content_39 = {
    Text = "■<Yellow:Riepilogo della Terza Operazione nel Dominio Artificiale>\n\nAbbiamo respinto N e gli attacchi della nebbia nera prima che il Dominio collassasse.\nNon sono sicuro che abbia funzionato, ma dopo il secondo Risveglio di Lady Sorel, il dorso della sua mano era pulito, senza alcun residuo del contratto.\n\nSecondo Miss Doll, la prima cosa che Lady Sorel ha detto al suo risveglio è stata—"
  },
  AvgDialog_23880_Content_4 = {
    Text = "Non riesco più a percepire la Sua presenza. Dovrebbe essersene andato."
  },
  AvgDialog_23880_Content_40 = {
    Text = "<Yellow:Siamo fuggiti insieme.>"
  },
  AvgDialog_23880_Content_5 = {
    Text = "È sempre stato uno che detesta le seccature."
  },
  AvgDialog_23880_Content_6 = {
    Text = "Allora questa nebbia nera...?"
  },
  AvgDialog_23880_Content_7 = {
    Text = "Non toccarla, o potresti essere trasportato in una Dimensione inaspettata."
  },
  AvgDialog_23880_Content_8 = {
    Text = "Tum-tum. Tum-tum."
  },
  AvgDialog_23880_Content_9 = {
    Text = "Ti sembrò di udire un battito rapido dalle profondità del cosmo, la nebbia nera che si alzava e abbassava come in maree senza fine."
  },
  AvgDialog_23881_Content_1 = {
    Text = "Eh... Sembra essere svanito di nuovo?"
  },
  AvgDialog_23881_Content_10 = {
    Text = "Il mio piano... è stato scoperto... Ngh!"
  },
  AvgDialog_23881_Content_11 = {
    Text = "Sorel emise un gemito soffocato. Filamenti di fluido Appiccicoso trasudavano dalle lettere incise sul dorso della Sua mano, per poi risalire lentamente lungo il Suo corpo."
  },
  AvgDialog_23881_Content_13 = {
    Text = "Il coltello affilato tagliò le Spine senza esitazione, squarciando anche la Sua elegante gonna e rivelando la pelle segnata dalle cicatrici sottostante."
  },
  AvgDialog_23881_Content_14 = {
    Text = "Sorel impugnava la Lama, la Sua espressione fredda come la pietra, senza nemmeno battere ciglio."
  },
  AvgDialog_23881_Content_15 = {
    Text = "Questo coltello non è del signor Lambert...?"
  },
  AvgDialog_23881_Content_16 = {
    Text = "Sì. Sapevo fin dall'Inizio che era nascosto fuori, con questo coltello in mano."
  },
  AvgDialog_23881_Content_17 = {
    Text = "Ma ho aspettato, e aspettato... e alla fine, ha gettato il coltello ed è fuggito."
  },
  AvgDialog_23881_Content_18 = {
    Text = "Heh... il mio caro padre, cosa sa fare oltre a causarmi problemi?"
  },
  AvgDialog_23881_Content_19 = {
    Text = "Non è riuscito nemmeno a trovare il coraggio di uccidermi."
  },
  AvgDialog_23881_Content_2 = {
    Text = "Sta solo giocando a nascondino con noi. In agguato nell'ombra, assaporando la mia Paura, il mio dolore…"
  },
  AvgDialog_23881_Content_21 = {
    Text = "Sorel taglia i rampicanti in crescita selvaggia, asportando ogni pezzo di carne necrotica."
  },
  AvgDialog_23881_Content_22 = {
    Text = "Sollevò il capo e rivolse lo sguardo al soffitto nero pece che si estendeva oltre la vista."
  },
  AvgDialog_23881_Content_23 = {
    Text = "Devi essere piuttosto compiaciuto adesso, vero? Nel vedermi in uno stato così miserabile..."
  },
  AvgDialog_23881_Content_24 = {
    Text = "Come innumerevoli volte prima, non giunse alcuna risposta — nient'altro che la foschia Intrecciata attorno al Suo corpo."
  },
  AvgDialog_23881_Content_25 = {
    Text = "Quindi questa è la punizione per aver infranto il patto? Non cadrò qui..."
  },
  AvgDialog_23881_Content_26 = {
    Text = "Quando lasciai per la prima volta la campagna di Constan, ero completamente sola, senza denaro né un nome."
  },
  AvgDialog_23881_Content_27 = {
    Text = "Le bugie erano i miei abiti, le dicerie le mie armi, e le masse la mia scala per salire.\nOgni cosa in questo mondo — tutto esiste per il mio tornaconto."
  },
  AvgDialog_23881_Content_28 = {
    Text = "Se sono arrivata fin qui non è grazie a mio padre, né a N."
  },
  AvgDialog_23881_Content_29 = {
    Text = "Ciò su cui ho davvero fatto affidamento è sempre stata una cosa sola — me stessa."
  },
  AvgDialog_23881_Content_3 = {Text = "Mmph—!!"},
  AvgDialog_23881_Content_30 = {
    Text = "Sono stata io a scegliere di firmare il patto con Lui, sono stata io a scegliere di infrangerlo, e sono stata io a scegliere di..."
  },
  AvgDialog_23881_Content_31 = {
    Text = "Liberarmi di mio padre per sempre."
  },
  AvgDialog_23881_Content_32 = {
    Text = "Le sue dita si chiusero delicatamente attorno al tuo polso."
  },
  AvgDialog_23881_Content_33 = {
    Text = "Questa Figura Oscura è solo una Sua proiezione nel mondo mortale. Non è priva di contromisure."
  },
  AvgDialog_23881_Content_34 = {
    Text = "Finché riusciremo a <Yellow:resistere fino alla fine del Dominio>, sarò ancora la Sorel che è morta e tornata in vita, e il contratto sarà reso nullo."
  },
  AvgDialog_23881_Content_35 = {
    Text = "Aiutami a superare questa crisi, e prenderò in considerazione l'idea di accettare le condizioni che proponi."
  },
  AvgDialog_23881_Content_36 = {
    Text = "<Gray:Anche in un momento come questo, si limita a \"prendere in considerazione\" di accettare…?>"
  },
  AvgDialog_23881_Content_37 = {
    Text = [[
So cosa stai pensando.
Tranquillo. Se accetto anche solo il settanta percento di quei termini, quei vecchi bacucchi dovrebbero stappare lo champagne.]]
  },
  AvgDialog_23881_Content_38 = {
    Text = "Ma questo è solo un Dominio Artificiale. Non subirai alcun Danno nella realtà, quindi perché…"
  },
  AvgDialog_23881_Content_39 = {Text = "..."},
  AvgDialog_23881_Content_4 = {
    Text = "Sorel crolla a terra. Sotto di Lei, una pozza di Sangue rosso scuro si espande lentamente sotto la Sua gonna."
  },
  AvgDialog_23881_Content_40 = {
    Text = "Un sospiro compiaciuto aleggiò dall'alto sopra le vostre teste, come se si fosse saziato abbastanza della vostra paura e impotenza."
  },
  AvgDialog_23881_Content_41 = {
    Text = "Nebbia nera continuava a fuoriuscire dai suoi occhi, dal naso e dalla gola, per poi Divorare l'intero teatro dell'opera con sé."
  },
  AvgDialog_23881_Content_42 = {
    Text = "Una fenditura si aprì nell'oscurità, come se l'universo avesse spalancato le sue fauci, con pianeti che rotolavano senza meta al suo interno."
  },
  AvgDialog_23881_Content_43 = {
    Text = "Come se gli dèi avessero pigramente aperto gli occhi da un sogno."
  },
  AvgDialog_23881_Content_44 = {
    Text = "Nulla luce, Nulla appartenenza, Nulla sensazione."
  },
  AvgDialog_23881_Content_45 = {
    Text = "RRRUMBLE—"
  },
  AvgDialog_23881_Content_46 = {
    Text = "Con un violento rombo, il balcone su cui vi trovavate divenne l'unica Isola di Solitudine in un Abisso nero come la pece."
  },
  AvgDialog_23881_Content_47 = {
    Text = "Sorel era inginocchiata davanti a quella fenditura. Innumerevoli braccia formate da una fitta nebbia la stringevano saldamente, cercando di trascinarla nella fenditura alle sue spalle."
  },
  AvgDialog_23881_Content_48 = {
    Text = "Lady Sorel!!"
  },
  AvgDialog_23881_Content_49 = {
    Text = "Vedi… Lui è un'esistenza che sfida ogni legge.\nRealtà, Sogni— per Lui non c'è differenza."
  },
  AvgDialog_23881_Content_5 = {
    Text = "Mia signora, voi— state sanguinando!"
  },
  AvgDialog_23881_Content_50 = {
    Text = "La nebbia nera le trafisse il corpo, poi fuoriuscì sotto forma di Follia dai suoi occhi, dal naso e dalle orecchie."
  },
  AvgDialog_23881_Content_51 = {
    Text = "Sempre più Sangue colava dall'angolo della bocca di Sorel. Ti rivolse un debole sorriso."
  },
  AvgDialog_23881_Content_52 = {
    Text = "Aiutami. Ricacciamolo indietro insieme."
  },
  AvgDialog_23881_Content_53 = {Text = "..."},
  AvgDialog_23881_Content_54 = {
    Text = "Denaro, potere, o qualsiasi altra cosa tu desideri. Basta che tu riesca a tirarmi fuori di qui, e farò del mio meglio per esaudire i tuoi desideri."
  },
  AvgDialog_23881_Content_55 = {
    Text = "Si sforzò di avvicinarsi a te, eppure sul suo volto non c'era traccia di supplica."
  },
  AvgDialog_23881_Content_56 = {
    Text = "Somigliava più all'istinto di sopravvivenza disperato e senza scrupoli di un animale sull'orlo della morte."
  },
  AvgDialog_23881_Content_57 = {
    Text = "%player%...Mi devi ancora da bere, non ricordi?"
  },
  AvgDialog_23881_Content_58 = {
    Text = "Aiutare, o no?"
  },
  AvgDialog_23881_Content_59 = {
    Text = "Pur sapendo bene che avrebbe potuto infrangere la sua promessa in qualsiasi momento, decidesti comunque di accettare la Scommessa."
  },
  AvgDialog_23881_Content_6 = {
    Text = "Sorel si asciuga delicatamente il Sangue fresco che cola dall'angolo della Sua bocca. Anche in un momento come questo, non perderebbe mai un briciolo della Sua compostezza."
  },
  AvgDialog_23881_Content_60 = {Text = "Accetto"},
  AvgDialog_23881_Content_61 = {
    Text = "Per favore, non fraintendere, lo faccio solo per assicurarmi che le trattative procedano senza intoppi..."
  },
  AvgDialog_23881_Content_62 = {
    Text = "Gli angoli delle labbra di Sorel si incurvarono leggermente verso l'alto, i suoi occhi sorridenti come stelle, che illuminavano tutto ciò che era vicino nel silenzio della notte."
  },
  AvgDialog_23881_Content_63 = {
    Text = "Non sei solo un Cavaliere, ma un Cavaliere astuto per giunta."
  },
  AvgDialog_23881_Content_7 = {
    Text = "Si sforza di sollevare il capo, guardandoti dritto negli occhi."
  },
  AvgDialog_23881_Content_8 = {
    Text = "È molto interessato a te. Le tue ripetute intrusioni nella mia coscienza hanno finalmente attirato la Sua attenzione."
  },
  AvgDialog_23881_Content_9 = {
    Text = "Dove il Sangue scorreva, Rose grottesche sbocciavano lungo il Sentiero, le loro Spine affilate si trasformavano in una foschia nera come la pece, Intrecciandosi lentamente attorno al Suo corpo."
  },
  AvgDialog_23882_Content_1 = {
    Text = "Elisir di Lampreda"
  },
  AvgDialog_23882_Content_10 = {
    Text = "<Red:BANG—!!>"
  },
  AvgDialog_23882_Content_11 = {
    Text = "Bene, abbiamo una risposta. Preparazione della seconda scarica."
  },
  AvgDialog_23882_Content_12 = {
    Text = "<Red:BANG—!!>"
  },
  AvgDialog_23882_Content_13 = {Text = "..."},
  AvgDialog_23882_Content_14 = {
    Text = "Uff... Finalmente ce l'abbiamo fatta a riportarlo indietro."
  },
  AvgDialog_23882_Content_15 = {
    Text = "Bentornato a casa, %player%."
  },
  AvgDialog_23882_Content_16 = {
    Text = [[
Infermeria Mythag
Due ore dopo]]
  },
  AvgDialog_23882_Content_17 = {
    Text = "Signorina Sylvia, perché è qui anche lei..."
  },
  AvgDialog_23882_Content_18 = {
    Text = "Ho sentito che qualcuno è entrato nel Dominio Artificiale due volte di fila. Come consulente psicologica di Mythag, ovviamente dovevo venire a controllare il benessere mentale di tutti."
  },
  AvgDialog_23882_Content_19 = {
    Text = "Mi dispiace, Signorina Sylvia, per averle causato tutti questi problemi..."
  },
  AvgDialog_23882_Content_2 = {
    Text = "L'Adrenalina non funziona. Il Sangue continua a uscire dagli occhi e dal naso… anche dalle orecchie…"
  },
  AvgDialog_23882_Content_20 = {
    Text = "Sylvia scosse gentilmente la testa."
  },
  AvgDialog_23882_Content_21 = {
    Text = "Non preoccuparti, questa volta sono venuta preparata—"
  },
  AvgDialog_23882_Content_22 = {
    Text = "Questa volta ho portato la mia ultima creazione: <Blue:Tè Oolong alla Lampreda>. Ha un meraviglioso effetto rinvigorente per la mente~"
  },
  AvgDialog_23882_Content_23 = {
    Text = "Lampreda? Tè oolong? Come sono finiti insieme quei due..."
  },
  AvgDialog_23882_Content_24 = {
    Text = "Questo tè emana un'aura intensamente sinistra sia nel nome che nell'odore.\nFai un respiro profondo e ne bevi qualche sorso."
  },
  AvgDialog_23882_Content_25 = {
    Text = "Com'è? Sei il suo primissimo assaggiatore, sai."
  },
  AvgDialog_23882_Content_26 = {
    Text = "Quella ragazza, Ramona, ha rifiutato senza nemmeno guardarlo. Che cuore di pietra..."
  },
  AvgDialog_23882_Content_27 = {
    Text = "Amaro. Insopportabilmente amaro."
  },
  AvgDialog_23882_Content_28 = {
    Text = "Sylvia ti fissa con trepidante aspettativa. Non hai altra scelta che farti coraggio e prendere altri due sorsi."
  },
  AvgDialog_23882_Content_29 = {
    Text = "Non è... male... Devo dire che il sapore è davvero indimenticabile. Ti sveglia di sicuro."
  },
  AvgDialog_23882_Content_3 = {
    Text = "Arresto cardiaco. Forse dovremmo provare quello che ha suggerito Winkle… la scarica elettrica…"
  },
  AvgDialog_23882_Content_30 = {
    Text = "Tra mezz'ora"
  },
  AvgDialog_23882_Content_31 = {
    Text = "Cosa è successo esattamente all'interno del Dominio?"
  },
  AvgDialog_23882_Content_32 = {
    Text = "Ramona ha detto che stavi bevendo con Lady Sorel, scherzando su Dexter, e poi improvvisamente hai perso i contatti."
  },
  AvgDialog_23882_Content_33 = {
    Text = "...Sono stata scoperta."
  },
  AvgDialog_23882_Content_34 = {Text = "?!"},
  AvgDialog_23882_Content_35 = {
    Text = "La coscienza di Lady Sorel, o qualcos'altro del tutto diverso, ha scoperto che mi ero infiltrata nel Dominio."
  },
  AvgDialog_23882_Content_36 = {
    Text = "Quella Figura Oscura apparsa sul palco... era un'entità incredibilmente potente."
  },
  AvgDialog_23882_Content_37 = {
    Text = "Mi ha scoperta, poi mi ha espulsa."
  },
  AvgDialog_23882_Content_38 = {
    Text = "Capisco. Abbiamo sottovalutato Lady Sorel. La Figura Oscura potrebbe essere una parte della sua coscienza..."
  },
  AvgDialog_23882_Content_39 = {
    Text = "Per istinto protettivo, espelle tutti gli intrusi."
  },
  AvgDialog_23882_Content_4 = {
    Text = "No, il rischio è troppo grande."
  },
  AvgDialog_23882_Content_40 = {
    Text = "Forse... Sembra che mi manchi un frammento di memoria. Ho la sensazione che la Figura Oscura abbia detto qualcosa di molto importante..."
  },
  AvgDialog_23882_Content_41 = {
    Text = "Il processo di raffinazione dell'Argento di Lady Sorel sta procedendo senza intoppi. A queste domande si potrà rispondere solo chiedendo a lei di persona dopo il suo secondo Risveglio."
  },
  AvgDialog_23882_Content_42 = {
    Text = "Allora dobbiamo ancora entrare nel Dominio per indagare?"
  },
  AvgDialog_23882_Content_43 = {
    Text = "Il tè oolong ha fatto davvero effetto. Hai notato con acutezza che lo sguardo di Doll, per un raro istante, ha vacillato."
  },
  AvgDialog_23882_Content_44 = {
    Text = "...Non avere fretta. Prima fai un po' di Riposo."
  },
  AvgDialog_23882_Content_45 = {Text = "Toc toc."},
  AvgDialog_23882_Content_46 = {
    Text = "Un bussare ritmico risuonò alla porta, e Dexter entrò a grandi falcate sulle sue gambe lunghe."
  },
  AvgDialog_23882_Content_47 = {
    Text = "Meno male che ti sei finalmente svegliata. Ramona piangeva e faceva i capricci per venirti a trovare—ha quasi ridotto i miei vestiti a brandelli con le unghie."
  },
  AvgDialog_23882_Content_48 = {
    Text = "Vuoi assaggiarlo — questo mio tè oolong? Aiuta a rinfrescare la mente e a scacciare i Sintomo: Delirio superflui."
  },
  AvgDialog_23882_Content_49 = {
    Text = "Come potrei? Una miscela speciale preparata con cura dalla signorina Sylvia apposta per te — non potrei mai accettare."
  },
  AvgDialog_23882_Content_5 = {Text = "..."},
  AvgDialog_23882_Content_50 = {Text = "..."},
  AvgDialog_23882_Content_51 = {
    Text = "Così malmesso? Allora parliamo di qualcosa di allegro."
  },
  AvgDialog_23882_Content_52 = {
    Text = "Questa volta avete fatto una grande scoperta nel Dominio Artificiale."
  },
  AvgDialog_23882_Content_53 = {
    Text = "Ero molto curioso riguardo a quel nobiluomo che avete incontrato all'interno, così sono uscito a bere qualcosa con un amico del dipartimento di polizia."
  },
  AvgDialog_23882_Content_54 = {
    Text = "...Bere è il tuo vero obiettivo qui, vero."
  },
  AvgDialog_23882_Content_55 = {
    Text = "Ahem. In breve, mi hanno detto che il giorno in cui Lady Sorel è deceduta, c'era in realtà una persona che se n'è andata senza rilasciare una dichiarazione."
  },
  AvgDialog_23882_Content_56 = {Text = "?!"},
  AvgDialog_23882_Content_57 = {
    Text = "Non avevi detto che tutti avevano rilasciato le loro dichiarazioni?"
  },
  AvgDialog_23882_Content_58 = {
    Text = "Non hanno detto la verità. L'identità di questo ospite è estremamente illustre — non è qualcuno che potevano permettersi di contrariare."
  },
  AvgDialog_23882_Content_59 = {
    Text = "Dexter finì di parlare e sbatté un giornale davanti a te."
  },
  AvgDialog_23882_Content_6 = {Text = "..."},
  AvgDialog_23882_Content_60 = {
    Text = "Il giornale riportava un titolo sensazionalistico a caratteri cubitali: \"Un legame tra padre e figlia! Sorel nomina il padre unico erede nel suo testamento,\" accompagnato da una foto."
  },
  AvgDialog_23882_Content_61 = {
    Text = "Nella foto, Sorel è stretta in un tenero abbraccio con l'anziano conosciuto come <Blue:Lambert>. Naturalmente, mentre si asciugava le lacrime, non dimenticò di mostrare deliberatamente l'anello di turchese al dito."
  },
  AvgDialog_23882_Content_62 = {
    Text = "Quell'anello divenne rapidamente una moda di tendenza quell'anno, con ogni sorta di imitazioni che inondarono il mercato."
  },
  AvgDialog_23882_Content_63 = {
    Text = "Dai un'occhiata — questo signor Lambert è il padrone che hai visto nel Dominio Artificiale?"
  },
  AvgDialog_23882_Content_64 = {
    Text = "All'epoca ha mostrato solo una mano. Molto emaciato, come se fosse afflitto da una grave malattia, e portava molti anelli..."
  },
  AvgDialog_23882_Content_65 = {
    Text = "L'anziano nella foto è vestito in modo sfarzoso, il volto difficile da distinguere. Guardi le sue mani che stringono Sorel."
  },
  AvgDialog_23882_Content_66 = {
    Text = "Lo stesso stile appariscente, la corporatura emaciata, persino le macchie dell'età sono negli stessi punti...\nÈ lui."
  },
  AvgDialog_23882_Content_67 = {
    Text = "Abbiamo anche trovato una villa piena di rose all'interno. Sospetto che abbia qualcosa a che fare con Lady Sorel..."
  },
  AvgDialog_23882_Content_68 = {
    Text = "Dexter annuisce."
  },
  AvgDialog_23882_Content_69 = {
    Text = "Ho chiesto a un amico di indagare. Quella villa è attualmente registrata a nome del padre di Sorel, il signor Lambert."
  },
  AvgDialog_23882_Content_7 = {
    Text = "Facciamolo. Preparazione della prima scarica."
  },
  AvgDialog_23882_Content_70 = {
    Text = "Nel Dominio, qualcuno con un coltello in mano cammina avanti e indietro fuori dal palco di Lady Sorel. A giudicare dalla figura, è probabilmente il Sig. Lambert."
  },
  AvgDialog_23882_Content_71 = {
    Text = "Bene, ora tutto torna. <Yellow:Il Sig. Lambert è il principale sospettato.>"
  },
  AvgDialog_23882_Content_72 = {
    Text = "E quella Figura Oscura mascherata? L'abbiamo vista uccidere Sorel con i nostri occhi."
  },
  AvgDialog_23882_Content_73 = {
    Text = "Forse un complice — difficile a dirsi. Catturiamo prima Lambert."
  },
  AvgDialog_23882_Content_74 = {Text = "..."},
  AvgDialog_23882_Content_75 = {
    Text = "Ho sentito che il rapporto tra Sorel e il Sig. Lambert era molto stretto. Venivano visti spesso insieme a ogni tipo di evento mondano. Chi avrebbe mai immaginato che dietro a tutto ciò si celasse una storia simile."
  },
  AvgDialog_23882_Content_76 = {
    Text = "Un padre che uccide la propria figlia? Davvero inaudito."
  },
  AvgDialog_23882_Content_77 = {
    Text = "Dexter fece una scrollata di spalle apparentemente indifferente."
  },
  AvgDialog_23882_Content_78 = {
    Text = "Più ci si avvicina al potere e al denaro, più ci si allontana dall'umanità. Le persone di questo ambiente — ciò in cui eccellono è recitare una parte."
  },
  AvgDialog_23882_Content_79 = {
    Text = "E voi, Lord Dexter? Siete anche voi bravo a recitare?"
  },
  AvgDialog_23882_Content_8 = {Text = "..."},
  AvgDialog_23882_Content_80 = {
    Text = "Dexter si bloccò per un istante, poi scoppiò a ridere."
  },
  AvgDialog_23882_Content_81 = {
    Text = "La mia risposta non ha alcun valore di riferimento, ragazza mia. Dovresti fidarti del tuo giudizio."
  },
  AvgDialog_23882_Content_82 = {
    Text = "...Torniamo a noi. Dov'è andata Ramona?"
  },
  AvgDialog_23882_Content_83 = {
    Text = "Si è ripresa un po' più in fretta ed è andata con la polizia a catturare il Sig. Lambert."
  },
  AvgDialog_23882_Content_84 = {
    Text = "Quella vecchia volpe è estremamente astuta. Non possiamo dargli alcuna possibilità di fuga."
  },
  AvgDialog_23882_Content_85 = {
    Text = "Università di Mythag\nUfficio Amministrativo"
  },
  AvgDialog_23882_Content_86 = {
    Text = "Ora che siamo solo noi due, parliamoci con franchezza."
  },
  AvgDialog_23882_Content_87 = {
    Text = "%player% e Ramona forse non sanno cosa sta succedendo, ma io non mi lascio ingannare così facilmente."
  },
  AvgDialog_23882_Content_88 = {
    Text = "<Yellow:Sorel è una Risvegliatrice da centinaia di anni. Come potrebbe avere un padre?>"
  },
  AvgDialog_23882_Content_89 = {Text = "..."},
  AvgDialog_23882_Content_9 = {
    Text = "Sono... morto..."
  },
  AvgDialog_23882_Content_90 = {
    Text = "Faresti meglio a non chiedere di lei. Non servirebbe comunque a nulla — non sono io a prendere le decisioni finali su questa indagine."
  },
  AvgDialog_23882_Content_91 = {
    Text = "Beh, a quanto pare ci siamo davvero cacciati in un bel pasticcio."
  },
  AvgDialog_23882_Content_92 = {
    Text = "La situazione potrebbe essere più seria di quanto pensi. I <Yellow:Superiori> hanno mandato qualcuno oggi, chiedendomi di parlare con %player% da sola, per assegnare nuovi incarichi a {Male=him,Female=her}."
  },
  AvgDialog_23882_Content_93 = {
    Text = "Pensare che abbia attirato l'attenzione dei Superiori..."
  },
  AvgDialog_23882_Content_94 = {
    Text = "Sorel non è una Risvegliatore qualunque. Le forze che la sostengono e le risorse di cui può disporre non sono da sottovalutare — superano persino quelle della tua famiglia."
  },
  AvgDialog_23882_Content_95 = {
    Text = "Quando si tratta di questioni che la riguardano, i Superiori non permetteranno mai a Mythag di agire in modo indipendente."
  },
  AvgDialog_23882_Content_96 = {
    Text = "Non mi importa cosa stiano tramando quei vecchi. Ho un solo limite invalicabile —"
  },
  AvgDialog_23882_Content_97 = {
    Text = "La sicurezza di quei due ragazzi."
  },
  AvgDialog_23882_Content_98 = {
    Text = "Doll lasciò sfuggire un sospiro appena percettibile."
  },
  AvgDialog_23882_Content_99 = {
    Text = "Che tu ci creda o no, quello è anche il mio limite invalicabile."
  },
  AvgDialog_23883_Content_1 = {
    Text = "Non solo rosa, ma anche lavanda e agrumi..."
  },
  AvgDialog_23883_Content_2 = {
    Text = "Potrebbe davvero essere l'acqua del bagno di Lady Sorel?"
  },
  AvgDialog_23883_Content_3 = {Text = "..."},
  AvgDialog_23883_Content_4 = {
    Text = "È davvero così importante per te?"
  },
  AvgDialog_23883_Content_5 = {
    Text = "Se fosse davvero la sua acqua del bagno, cosa hai intenzione di fare?"
  },
  AvgDialog_23884_Content_1 = {Text = "Per Sorel"},
  AvgDialog_23884_Content_10 = {
    Text = "Quanto al suo povero padre, è stato dipinto come l'assassino che tormentava la propria figlia. Gli è stata persino attribuita l'accusa di aver assassinato dei nobili."
  },
  AvgDialog_23884_Content_100 = {
    Text = "L'intero corpo di Lambert tremava senza sosta, una risata acuta e sottile che sgorgava incessantemente dal profondo della sua gola."
  },
  AvgDialog_23884_Content_101 = {
    Text = "Ti avevo detto che solo la morte completa avrebbe potuto porre fine al nostro contratto, e tu ci hai creduto senza la minima esitazione."
  },
  AvgDialog_23884_Content_102 = {
    Text = "Le anime deboli ripongono sempre le loro speranze nella clemenza di chi sta sopra di loro, e credono incrollabilmente nelle regole che governano questo mondo."
  },
  AvgDialog_23884_Content_103 = {
    Text = "Ma tutto questo non è stato altro che il nostro gioco."
  },
  AvgDialog_23884_Content_104 = {
    Text = "<Shake:Tu non sei lui... Tu sei...>"
  },
  AvgDialog_23884_Content_105 = {
    Text = "Lambert si avvolse in una fitta nebbia oscura. La sua forma iniziò a torcersi e mutare al ritmo pulsante della foschia, subendo Distorsione e trasformazione..."
  },
  AvgDialog_23884_Content_106 = {
    Text = "<RedItalic:Io creo le regole, e io le rovescio.>"
  },
  AvgDialog_23884_Content_107 = {
    Text = "È da tanto che non ci vediamo, Sorel.\nMi sei mancata così tanto, così ho preso in prestito il corpo del signor Lambert per un po'."
  },
  AvgDialog_23884_Content_108 = {
    Text = "Che cosa davvero straziante... Non sembri molto felice di vedermi, e hai persino esaurito ogni mezzo possibile per liberarti di me."
  },
  AvgDialog_23884_Content_109 = {
    Text = "Un'infinita nebbia nera si riversò in avanti, trafiggendo il corpo di Sorel."
  },
  AvgDialog_23884_Content_11 = {
    Text = "A pensarci bene, Sorel dovrebbe davvero ringraziarti. Se non l'avessi riportata indietro nel Dominio Artificiale..."
  },
  AvgDialog_23884_Content_110 = {
    Text = "No, no... Il nostro contratto... L'ho già infranto..."
  },
  AvgDialog_23884_Content_111 = {
    Text = "Eppure ti sei voltata e hai firmato un accordo con quegli sciocchi.\nEri una mia proprietà—come potevo sopportare di vederti incatenata da loro?"
  },
  AvgDialog_23884_Content_112 = {
    Text = "Ma per convincerti a ravvederti, naturalmente. Il gioco di nascondino nel Dominio era solo un piccolo regalo di benvenuto. Ti è piaciuto?"
  },
  AvgDialog_23884_Content_113 = {
    Text = "Sorel crollò in ginocchio dall'agonia. Sul dorso pallido della sua mano, una lettera familiare balenò per un brevissimo istante prima di svanire altrettanto rapidamente."
  },
  AvgDialog_23884_Content_114 = {
    Text = "È fugace come una vita umana transitoria."
  },
  AvgDialog_23884_Content_115 = {
    Text = "Ho pianificato tutto questo per così tanto tempo... È stato tutto inutile..."
  },
  AvgDialog_23884_Content_116 = {
    Text = "<Gray:No, non ci credo... Deve esserci un modo...>"
  },
  AvgDialog_23884_Content_117 = {
    Text = "Un dolce Vento soffiò, facendo danzare delicatamente nell'aria petali cremisi di rosa. Sorel colse una fragranza tenue e delicata—una che apparteneva a un ricordo lontano."
  },
  AvgDialog_23884_Content_118 = {
    Text = "Sorel, sai qual è il linguaggio dei fiori delle rose?"
  },
  AvgDialog_23884_Content_119 = {
    Text = "Hmm... Amore eterno e fedele?"
  },
  AvgDialog_23884_Content_12 = {
    Text = "Scuoti la testa."
  },
  AvgDialog_23884_Content_120 = {
    Text = "Non è tutto. Ho sentito dire che nella lontana Londinium, le rose simboleggiano anche splendide aspirazioni."
  },
  AvgDialog_23884_Content_121 = {
    Text = [[
Aspirazioni per l'amore, per la famiglia e per tutte le cose belle di questo mondo.
Sorel, un giorno anche tu diventerai l'aspirazione di tutti.]]
  },
  AvgDialog_23884_Content_122 = {
    Text = "Diventare l'aspirazione di tutti...? Perché?"
  },
  AvgDialog_23884_Content_123 = {
    Text = "Perché sei proprio come questa rosa: bella e resiliente.\nTu non sarai mai come me, sempre a piangere."
  },
  AvgDialog_23884_Content_124 = {
    Text = "Mia figlia non piange facilmente e non si arrende facilmente.\nAfferrerà il proprio Destino con le sue stesse mani."
  },
  AvgDialog_23884_Content_125 = {
    Text = "Sorel si asciugò il Sangue che le colava dall'angolo delle labbra e strinse forte la stoffa della gonna. Non osava ancora guardare direttamente il volto di N, ma la sua voce non tremava più."
  },
  AvgDialog_23884_Content_126 = {
    Text = [[
Mio signore, voi avete paura.
Temete Mythag e temete quel Custode alle prime armi.]]
  },
  AvgDialog_23884_Content_127 = {
    Text = "La foschia scura sotto la tesa del cappello di N tremolò leggermente, e dall'interno emanò una risata rauca e divertita."
  },
  AvgDialog_23884_Content_128 = {
    Text = "Quella non si chiama paura, figlia mia. Voi umani non avete un detto: \"nostalgia venata di trepidazione\"?"
  },
  AvgDialog_23884_Content_129 = {
    Text = "Ho in effetti alcune ragioni inevitabili che mi costringono a mantenere le distanze da Mythag e da %player%."
  },
  AvgDialog_23884_Content_13 = {
    Text = "Ero solo uno strumento negoziale assegnato dai Superiori. Se fosse morta davvero, le trattative non sarebbero andate a monte?"
  },
  AvgDialog_23884_Content_130 = {
    Text = "Ecco perché non volevate indugiare troppo a lungo nel Dominio, e questo ci ha dato la possibilità di Fuga."
  },
  AvgDialog_23884_Content_131 = {
    Text = "Mio signore, avete camminato nel mondo degli umani per migliaia di anni. Sicuramente dovete capire—"
  },
  AvgDialog_23884_Content_132 = {
    Text = "Quando una persona è messa alle strette, non le resta più nulla da temere nel cuore."
  },
  AvgDialog_23884_Content_133 = {
    Text = "In effetti, oggi sono diventata di nuovo vostra prigioniera, a causa della mia debolezza e della mia stoltezza."
  },
  AvgDialog_23884_Content_134 = {
    Text = "Ma non importa.\nUna volta, due volte… Finché ci sarà la minima possibilità di Fuga, non me la lascerò mai sfuggire."
  },
  AvgDialog_23884_Content_135 = {
    Text = "Che quella possibilità venga da Mythag o da %player%, per me è lo stesso."
  },
  AvgDialog_23884_Content_136 = {
    Text = "Vi piace fare scommesse con le persone, non è vero? Perché non facciamo una Scommessa tutta nostra…"
  },
  AvgDialog_23884_Content_137 = {
    Text = "La tua crescita è davvero sempre più sorprendente. Dimmi, qual è la posta in gioco?"
  },
  AvgDialog_23884_Content_138 = {
    Text = "Sorel chiuse dolcemente gli occhi. Si vantava di essere razionale, il tipo di persona che ha sempre disprezzato il rischio."
  },
  AvgDialog_23884_Content_139 = {
    Text = "Ma la vita è diversa. La vita stessa è un'enorme scommessa, e nessuno può tirarsi fuori."
  },
  AvgDialog_23884_Content_14 = {
    Text = "Quindi... era solo lavoro di routine."
  },
  AvgDialog_23884_Content_140 = {
    Text = "La posta in gioco è… tutto ciò che ho."
  },
  AvgDialog_23884_Content_141 = {
    Text = "E così, la storia si ferma qui.\nQuanto al Destino futuro di quella fanciulla rosa, attendiamo e vediamo insieme."
  },
  AvgDialog_23884_Content_142 = {
    Text = "Per evitare che questo finale sembri troppo frettoloso, lasciatemi aggiungere qualche altra parola."
  },
  AvgDialog_23884_Content_143 = {
    Text = "Umani, Risvegliatori… credete sempre ingenuamente di potervi liberare da me, di poter forgiare il vostro futuro con il solo sforzo."
  },
  AvgDialog_23884_Content_144 = {
    Text = "<Red:Ma è tutto vano.>"
  },
  AvgDialog_23884_Content_145 = {
    Text = "Non potrete mai liberarvi da me, così come non potrete mai liberarvi dal <Yellow:Destino>."
  },
  AvgDialog_23884_Content_146 = {
    Text = "Ricordate…"
  },
  AvgDialog_23884_Content_147 = {
    Text = "Nel momento in cui cercate di schivare il <Yellow:Destino>, vi siete già scontrati con il <Red:Destino>."
  },
  AvgDialog_23884_Content_148 = {
    Text = "LA FI<Red:N>E"
  },
  AvgDialog_23884_Content_15 = {
    Text = "<Shake:Waaah! Lady Sorel è apparsa!!>"
  },
  AvgDialog_23884_Content_17 = {
    Text = "La folla si era radunata lungo le strade già da tempo. Questa è la prima apparizione pubblica di Lady Sorel dall'incidente della caduta."
  },
  AvgDialog_23884_Content_18 = {
    Text = "Vestita in abiti cerimoniali, ha accolto con calma l'ammirazione di tutti tra una pioggia di petali di rosa, sembrando una Doll squisitamente realizzata."
  },
  AvgDialog_23884_Content_19 = {
    Text = "I suoi lunghi capelli brillavano d'oro alla luce del sole, fluendo come nastri di seta."
  },
  AvgDialog_23884_Content_2 = {
    Text = "Città di Londinium\nUn mese dopo"
  },
  AvgDialog_23884_Content_20 = {
    Text = "Lady Sorel! <Big:Lady Sorel—!!>"
  },
  AvgDialog_23884_Content_21 = {
    Text = "Oh mio dio, ha appena guardato me, ha guardato me!"
  },
  AvgDialog_23884_Content_22 = {
    Text = "Tu e Ramona siete stati spinti da parte dalla folla rumorosa, potendo osservare Sorel solo da lontano."
  },
  AvgDialog_23884_Content_23 = {
    Text = "Stracciare contratti, eliminare rivali, e poi liberarsi comodamente del padre diventato un peso morto — in un solo breve mese, aveva più che realizzato le sue aspirazioni di lunga data."
  },
  AvgDialog_23884_Content_24 = {
    Text = "Non più vincolata da altri, né manipolata da nessuno."
  },
  AvgDialog_23884_Content_25 = {
    Text = "Sorel teneva la testa alta, attraversando con grazia il corridoio di fiori e applausi, camminando verso il futuro che le apparteneva."
  },
  AvgDialog_23884_Content_26 = {Text = "..."},
  AvgDialog_23884_Content_27 = {
    Text = "Mi è venuto in mente all'improvviso — è la prima volta che la vedo al di fuori di un Dominio."
  },
  AvgDialog_23884_Content_28 = {
    Text = "Il giorno in cui Sorel è stata Risvegliata con successo, è stato ordinato di impedire qualsiasi visita."
  },
  AvgDialog_23884_Content_29 = {
    Text = "Tutto ciò che sai è che in seguito ha intrapreso una settimana di ardue trattative con il cosiddetto <Yellow:alto comando>, e le due parti hanno infine firmato un accordo segreto."
  },
  AvgDialog_23884_Content_3 = {
    Text = "<BigShake:Ultime notizie!!>"
  },
  AvgDialog_23884_Content_30 = {
    Text = "Quanto al contenuto effettivo dell'accordo, non avevi il diritto di chiedere."
  },
  AvgDialog_23884_Content_31 = {
    Text = "Sembri un po' distratto. Hai qualcosa per la testa?"
  },
  AvgDialog_23884_Content_32 = {
    Text = "...Com'è adesso, l'ho quasi non riconosciuta."
  },
  AvgDialog_23884_Content_33 = {
    Text = "Sorel nel Dominio sembrava molto più vivace — ti abbracciava d'impulso, ti offriva costoso Champagne..."
  },
  AvgDialog_23884_Content_34 = {
    Text = "E senza esitazione, ti trascinava nell'abisso con lei."
  },
  AvgDialog_23884_Content_35 = {Text = "..."},
  AvgDialog_23884_Content_36 = {
    Text = "Forse non ricorda nulla di tutto ciò.\nSospetto persino che usarmi per mettere da parte N facesse tutto parte dei suoi calcoli..."
  },
  AvgDialog_23884_Content_37 = {
    Text = "Qualcosa di freddo ti sfiorò improvvisamente la guancia senza preavviso."
  },
  AvgDialog_23884_Content_38 = {
    Text = "<Shake:Sss—! Ma che...>"
  },
  AvgDialog_23884_Content_39 = {
    Text = "Ma come, sono passati solo pochi giorni e ti sei già dimenticato di me!"
  },
  AvgDialog_23884_Content_4 = {
    Text = "Non ci crederete! Lady Sorel, che di recente è caduta trovando la morte, è tornata in vita!"
  },
  AvgDialog_23884_Content_40 = {
    Text = "Signorina Karen..."
  },
  AvgDialog_23884_Content_41 = {
    Text = "Karen ti porge con un sorriso una bottiglia di Champagne legata con un nastro."
  },
  AvgDialog_23884_Content_42 = {
    Text = "La mia signora è molto grata per il vostro aiuto nel Dominio. Ha chiesto espressamente a Karen di consegnarvi un regalo speciale."
  },
  AvgDialog_23884_Content_43 = {
    Text = "Prendi lo champagne ghiacciato e lo esamini con curiosità."
  },
  AvgDialog_23884_Content_44 = {
    Text = "È la stessa bottiglia di Champagne che hai bevuto nel Dominio. Sotto la luce del sole, la bottiglia verde scuro dorata brilla di un tenue bagliore dorato, chiaramente di grande valore a prima vista."
  },
  AvgDialog_23884_Content_45 = {
    Text = "Conservala con cura — questa bottiglia è super incredibilmente costosa!"
  },
  AvgDialog_23884_Content_46 = {
    Text = "<SmallShake:Se fossi in te, la venderei sicuramente. Non dovresti più preoccuparti dei soldi!>"
  },
  AvgDialog_23884_Content_47 = {
    Text = "Quindi ricordava tutto fin dall'inizio..."
  },
  AvgDialog_23884_Content_48 = {
    Text = "Alzi lo sguardo leggermente sorpreso."
  },
  AvgDialog_23884_Content_5 = {
    Text = "Ho sentito dire che è sopravvissuta a un tentativo di assassinio da parte di suo padre @2: Lambert ed è stata erroneamente dichiarata morta da un medico incompetente!"
  },
  AvgDialog_23884_Content_50 = {
    Text = "Sorel si avvicina sempre di più a te, e nell'istante in cui vi incrociate, ti rivolge un lieve sorriso."
  },
  AvgDialog_23884_Content_51 = {
    Text = "Una fragranza floreale fresca ti raggiunge il naso, come rose che sbocciano all'alba nella luce del mattino, senza alcuna traccia di decadimento."
  },
  AvgDialog_23884_Content_52 = {
    Text = "Petali rossi vorticanti danzano con grazia nella luce del sole, ciocche dorate ondeggiano come onde dell'oceano, scintillando con lo splendore del Sole."
  },
  AvgDialog_23884_Content_53 = {
    Text = "Nell'istante in cui il suo sguardo incrocia il tuo, una piccola crepa sembra apparire nella sua impeccabile compostezza, riducendo appena la distanza tra voi."
  },
  AvgDialog_23884_Content_54 = {
    Text = "Attraverso la Folla animata, ti sembra di sentirla dire—"
  },
  AvgDialog_23884_Content_55 = {
    Text = "Mi devi ancora da bere, Custode."
  },
  AvgDialog_23884_Content_58 = {
    Text = [[
Periferia di Londinium
Tenuta Lambert]]
  },
  AvgDialog_23884_Content_59 = {
    Text = "L'Anziano siede solo nella sala vuota, osservando in silenzio l'Ospite Inatteso che varca il Cancello."
  },
  AvgDialog_23884_Content_6 = {
    Text = "Quasi un mese dopo essere stata sepolta nella sua bara, in una notte buia e ventosa, il guardaboschi Jacob ha improvvisamente sentito dei colpi provenire dall'interno della bara..."
  },
  AvgDialog_23884_Content_60 = {
    Text = "Buon pomeriggio, Padre."
  },
  AvgDialog_23884_Content_61 = {
    Text = "Che ospite raro, Sorel. Dopo la bancarotta, ho perso il conto di quante volte mi hai chiuso la porta in faccia."
  },
  AvgDialog_23884_Content_62 = {
    Text = "Pensavo ti fossi dimenticata da tempo di avere ancora un padre."
  },
  AvgDialog_23884_Content_63 = {
    Text = "È così che tratti la persona che ti ha salvato la vita? Tirarti fuori di prigione mi è costato un bel po' di fatica."
  },
  AvgDialog_23884_Content_64 = {
    Text = "Sei già diventato abbastanza scaltro da far trapelare deliberatamente la notizia di un testamento per attirarmi qui. Davvero ti aspetti che creda che mi hai fatto uscire per salvarmi la vita? *coff coff*..."
  },
  AvgDialog_23884_Content_65 = {Text = "..."},
  AvgDialog_23884_Content_66 = {
    Text = "Ho sentito che quando la polizia ti ha portata via, hai accettato le tue \"colpe\" senza alcuna protesta.\nPerché?"
  },
  AvgDialog_23884_Content_67 = {
    Text = "Dal momento in cui sei caduta da quell'edificio, l'ho capito. Non sono un tuo Rivale."
  },
  AvgDialog_23884_Content_68 = {
    Text = "Mia figlia è un diavolo abbastanza spietato da uccidere se stessa, e poi mandare il proprio padre al patibolo."
  },
  AvgDialog_23884_Content_69 = {
    Text = "Perché ho avuto un buon maestro — il mio carissimo padre."
  },
  AvgDialog_23884_Content_7 = {
    Text = "Spacciare il secondo Risveglio per una resurrezione dai morti. Una storia davvero creativa."
  },
  AvgDialog_23884_Content_70 = {
    Text = "L'Anziano rise di cuore, poi volse lo sguardo al ritratto appeso alla parete."
  },
  AvgDialog_23884_Content_71 = {
    Text = "Vattene, Sorel."
  },
  AvgDialog_23884_Content_72 = {
    Text = "Se tua Madre Rebecca fosse ancora viva, non vorrebbe mai vederci diventare queste creature miserabili."
  },
  AvgDialog_23884_Content_73 = {
    Text = "Sorel camminò tra i petali e le foglie appassite sparsi sul pavimento fino a fermarsi davanti a suo padre."
  },
  AvgDialog_23884_Content_74 = {
    Text = "Si inginocchiò e appoggiò delicatamente la testa contro le ginocchia logore e tremanti dell'Anziano."
  },
  AvgDialog_23884_Content_75 = {
    Text = "Non allontanarti da me, Padre. Questa dovrebbe essere l'ultima volta che ci vediamo."
  },
  AvgDialog_23884_Content_76 = {
    Text = "Ti ricordi quando ero piccola, quanto amavo appoggiarmi alle tue ginocchia proprio così…"
  },
  AvgDialog_23884_Content_77 = {
    Text = "Lambert non disse nulla, il suo corpo in decomposizione tremò impercettibilmente per un istante."
  },
  AvgDialog_23884_Content_78 = {
    Text = "Siamo la stessa specie di persona. Un'ambizione implacabile scorre nelle nostre vene, trasformandoci in demoni della fama e del potere."
  },
  AvgDialog_23884_Content_79 = {
    Text = "Non potrò mai disprezzarti, così come non potrò mai disprezzare me stessa."
  },
  AvgDialog_23884_Content_8 = {
    Text = "Ora la reputazione di Sorel tra la gente comune è ancora più grande. Ho sentito che nel Distretto Ovest sono già in programma sei o sette produzioni ispirate a lei."
  },
  AvgDialog_23884_Content_80 = {
    Text = "Lambert fissò il ritratto della sua defunta moglie, le lacrime che scorrevano incontenibili."
  },
  AvgDialog_23884_Content_81 = {
    Text = "Davvero… Ma quando guardo il volto di tua Madre, il cuore mi duole.\nNon sono come te, Sorel."
  },
  AvgDialog_23884_Content_82 = {
    Text = "Non voglio diventare come te. Non voglio…"
  },
  AvgDialog_23884_Content_83 = {
    Text = "Capisco. Capisco tutto… Riportarti in vita, poi lasciare che la Dissoluzione si diffondesse nel tuo corpo… è stata tutta un'idea del Nullo, vero?"
  },
  AvgDialog_23884_Content_84 = {
    Text = "Lo scopo era sorvegliarmi, disgustarmi. Il gusto di Quello è orribile come sempre."
  },
  AvgDialog_23884_Content_85 = {
    Text = "Come fai a saperlo?! Come osi pronunciare direttamente il nome di Quello…"
  },
  AvgDialog_23884_Content_86 = {
    Text = "Che ironia. Prima io e mio padre siamo diventati Schiavi del potere, e ora siamo entrambi diventati Schiavi di Quello."
  },
  AvgDialog_23884_Content_87 = {
    Text = "Consanguinei che massacrano consanguinei, simili che si divorano a vicenda… non è forse lo spettacolo che Quello ama di più?"
  },
  AvgDialog_23884_Content_88 = {
    Text = "Il mio contratto con Lui è terminato da tempo. Ora siamo entrambi liberi, Padre."
  },
  AvgDialog_23884_Content_89 = {
    Text = "Ti ho lasciato una somma di denaro e ti ho procurato una falsa Identità. D'ora in poi, puoi andare dove vuoi."
  },
  AvgDialog_23884_Content_9 = {
    Text = "Già. È diventata una leggenda vivente."
  },
  AvgDialog_23884_Content_90 = {
    Text = "A patto che tu non compaia mai più davanti a me per il resto della tua vita, puoi fare tutto ciò che desideri."
  },
  AvgDialog_23884_Content_91 = {
    Text = "Heh heh... Mi stai prendendo in giro?\nGuarda in che stato sono. Non posso più andare da nessuna parte..."
  },
  AvgDialog_23884_Content_92 = {
    Text = "Ti assumerò il miglior Dottore.\nSei mio padre. Finché ne avrai la volontà, potrai sicuramente aggrapparti alla vita fino al giorno in cui il mondo incontrerà la sua Distruzione."
  },
  AvgDialog_23884_Content_93 = {
    Text = "Disse Sorel, lasciando uscire un lungo, profondo respiro."
  },
  AvgDialog_23884_Content_94 = {
    Text = "Ho aspettato abbastanza a lungo per questo giorno. Ora finalmente ho abbastanza potere per recidere tutto questo con le mie stesse mani..."
  },
  AvgDialog_23884_Content_95 = {
    Text = "Addio, padre mio."
  },
  AvgDialog_23884_Content_96 = {
    Text = "<Red:Hehe.>"
  },
  AvgDialog_23884_Content_97 = {
    Text = "Una breve, familiare risata gelida le trafisse improvvisamente le orecchie."
  },
  AvgDialog_23884_Content_98 = {Text = "?!"},
  AvgDialog_23884_Content_99 = {
    Text = "Addio... bene? Oh Sorel, mia ingenua Sorel..."
  },
  AvgDialog_24075_Content_1 = {Text = "UUGHH!"},
  AvgDialog_24075_Content_10 = {
    Text = "Arrivando persino a uccidere sua figlia…"
  },
  AvgDialog_24075_Content_11 = {
    Text = "Lambert prese con calma il calice dal tavolo e sorseggiò un po' del vino rosso al suo interno."
  },
  AvgDialog_24075_Content_12 = {
    Text = "Heh heh… Ai vostri occhi, ovviamente non posso più gustare questo vino."
  },
  AvgDialog_24075_Content_13 = {
    Text = "Ma sapete? Quando lo ingoio, i miei ricordi, la mia immaginazione continuano a dirmi…"
  },
  AvgDialog_24075_Content_14 = {
    Text = "Questo è un vino rosso @2 Montrachet. All'inizio, dovrebbe avere un aroma di liquirizia. Due ore dopo, si percepisce una ricca fragranza di rose…"
  },
  AvgDialog_24075_Content_15 = {
    Text = "Lambert assaporò l'aroma del vino rosso nel suo calice, mentre un sorriso di assoluta soddisfazione si diffondeva sul suo volto."
  },
  AvgDialog_24075_Content_16 = {
    Text = "È solo immaginazione. Prima o poi, dovrà affrontare la realtà, signor Lambert."
  },
  AvgDialog_24075_Content_17 = {
    Text = "Sì, immaginazione! È una forza potente."
  },
  AvgDialog_24075_Content_18 = {
    Text = "L'immaginazione della ricchezza, l'immaginazione del potere, l'immaginazione del desiderio… Può far cadere in disgrazia il monaco più santo, e trasformare il ladro più vile in un profeta."
  },
  AvgDialog_24075_Content_19 = {
    Text = "E la mia adorata figlia? Ha osato privarmi del mio ultimo brandello di immaginazione."
  },
  AvgDialog_24075_Content_2 = {
    Text = "Signor Lambert, non le resta alcuna via di fuga. La prego di collaborare con noi."
  },
  AvgDialog_24075_Content_20 = {
    Text = "Ora l'unica cosa di valore che mi resta è questa bottiglia di vino. Davvero, questa è la cosa più crudele al mondo…"
  },
  AvgDialog_24075_Content_21 = {
    Text = "Così sono stato costretto a commettere questo crimine spregevole."
  },
  AvgDialog_24075_Content_22 = {
    Text = "Ora siete liberi di portarmi via e dare tutta la colpa a me solo."
  },
  AvgDialog_24075_Content_23 = {
    Text = [[
A differenza di certe persone, io sono solo un insignificante nessuno.
Per questo mondo, la mia vita o la mia morte non hanno alcun significato.]]
  },
  AvgDialog_24075_Content_24 = {
    Text = "Le sue parole nascondono più di quanto sembri… Sta forse insinuando qualcosa, signor Lambert?"
  },
  AvgDialog_24075_Content_25 = {
    Text = "Lambert non rispose. Sorrise debolmente e aprì le mani davanti a tutti."
  },
  AvgDialog_24075_Content_26 = {
    Text = "Portatemi via, agente."
  },
  AvgDialog_24075_Content_27 = {
    Text = "Fuori dalla villa, l'aria era piena di trambusto mentre i detective continuavano ad affaccendarsi nei dintorni."
  },
  AvgDialog_24075_Content_28 = {
    Text = "Guardando indietro verso la villa, le sue mura fatiscenti erano avvolte in una perenne oscurità, come un relitto incagliato sul fondo del mare."
  },
  AvgDialog_24075_Content_29 = {
    Text = "Ramona si tolse delicatamente il distintivo dal petto e aprì un canale di comunicazione con Dexter."
  },
  AvgDialog_24075_Content_3 = {
    Text = "Lambert, appoggiandosi al suo sottile bastone di faggio, scoppiò improvvisamente a ridere."
  },
  AvgDialog_24075_Content_30 = {
    Text = "L'obiettivo è stato catturato e ha confessato tutte le accuse a suo carico."
  },
  AvgDialog_24075_Content_31 = {
    Text = "Ben fatto. Questa è mia figlia, senza dubbio."
  },
  AvgDialog_24075_Content_32 = {Text = "..."},
  AvgDialog_24075_Content_33 = {
    Text = "Ma lei? Dopo essere salita alla ribalta, non solo non mi ha ripagato, ma non vedeva l'ora di allontanarsi il più possibile da me."
  },
  AvgDialog_24075_Content_34 = {
    Text = "Ripagare. Ramona rifletté in silenzio su quella parola nel suo cuore."
  },
  AvgDialog_24075_Content_35 = {
    Text = "Padre, c'è qualcosa che vorresti che facessi per te?"
  },
  AvgDialog_24075_Content_36 = {
    Text = "Fare qualcosa? È una nuova parola in codice che hai inventato con %player%? Non riesco nemmeno a capire cosa intendi."
  },
  AvgDialog_24075_Content_37 = {
    Text = "Ehm… Per esempio, aiutarti a guadagnare un sacco di soldi, o fare qualche lavoro di indagine o ricerca per te…"
  },
  AvgDialog_24075_Content_38 = {
    Text = "Smettila… Smettila! Non oserei mai fare una richiesta del genere. Resta viva e in salute, è tutto ciò che chiedo."
  },
  AvgDialog_24075_Content_39 = {
    Text = "Accompagnate da un lieve ronzio di corrente elettrica, le parole sconnesse di Dexter erano alquanto difficili da comprendere. Ramona non poté fare a meno di sorridere."
  },
  AvgDialog_24075_Content_4 = {
    Text = "C'è qualcosa di divertente in tutto questo?"
  },
  AvgDialog_24075_Content_40 = {
    Text = "Padre, grazie."
  },
  AvgDialog_24075_Content_41 = {
    Text = "Oggi sei davvero strana, così formale all'improvviso. Ringraziarmi per cosa?"
  },
  AvgDialog_24075_Content_42 = {
    Text = "Ramona abbassò lo sguardo, le punte delle scarpe che sfregavano delicatamente le foglie cadute ai suoi piedi. Anche quelle scarpe gliele aveva comprate Dexter."
  },
  AvgDialog_24075_Content_43 = {
    Text = "Vestitini, carillon, un cerambice… Dexter le aveva comprato tante cose. Ma non aveva mai chiesto nulla in cambio."
  },
  AvgDialog_24075_Content_44 = {Text = "Per tutto."},
  AvgDialog_24075_Content_5 = {
    Text = "Non abbia paura, signorina… Sto solo ridendo di me stesso."
  },
  AvgDialog_24075_Content_6 = {
    Text = "D-melma nero pece colava dalle sue orbite oculari, come lacrime nere."
  },
  AvgDialog_24075_Content_7 = {
    Text = "Sintomi dello stadio avanzato di Dissoluzione…\nSe non mi sbaglio, i suoi organi interni si sono trasformati in D-melma da tempo."
  },
  AvgDialog_24075_Content_8 = {
    Text = "Non riesce a sentire il profumo delle rose, non riesce a percepire il calore del Sole, e non riesce a gustare il sapore del vino rosso."
  },
  AvgDialog_24075_Content_9 = {
    Text = "Per una persona come lei, il denaro e il potere mondano hanno perso ogni significato da tempo. Allora perché continuare a inseguirli?"
  },
  AvgDialog_24078_Content_1 = {
    Text = "Un fetore di putrefazione ti si insinuò nelle narici."
  },
  AvgDialog_24078_Content_10 = {Text = "Ugh..."},
  AvgDialog_24078_Content_11 = {
    Text = "Investigatori dell'Università di Mythag, più il Risvegliatore che ha rubato il potere di Lemuria... È tutto qui quello che avete?"
  },
  AvgDialog_24078_Content_12 = {
    Text = "Tulu si parò davanti a te mentre Ramona si inginocchiava al tuo fianco, madida di sudore, lottando per estrarre la lama di Golia."
  },
  AvgDialog_24078_Content_13 = {
    Text = "Tulu, portali fuori."
  },
  AvgDialog_24078_Content_14 = {
    Text = "Hai perso il senno?"
  },
  AvgDialog_24078_Content_15 = {
    Text = "Ramona tirò con più forza l'arma, la lama le tagliò il guanto, sangue rosso scuro le inzuppò la manica."
  },
  AvgDialog_24078_Content_16 = {
    Text = "Starò bene. Miryam vuole qualcuno da dare in pasto al suo dio neonato, giusto? Proteggete Celeste e Murphy, fermate il rito... Troverò un modo per uscirne."
  },
  AvgDialog_24078_Content_17 = {
    Text = "La tua mente si svuotò, fabbricando scuse a cui nemmeno tu riuscivi a credere."
  },
  AvgDialog_24078_Content_18 = {Text = "Tu..."},
  AvgDialog_24078_Content_19 = {
    Text = "Portali fuori!"
  },
  AvgDialog_24078_Content_2 = {
    Text = "I Navigatori, convocati dal loro capo, si riversarono fuori da ogni cabina.\nA guidare l'inseguimento era il gigante che temevi di più."
  },
  AvgDialog_24078_Content_20 = {Text = "..."},
  AvgDialog_24078_Content_21 = {
    Text = "Tulu non discusse oltre. Ti rivolse un ultimo sguardo, come a confermare la tua determinazione."
  },
  AvgDialog_24078_Content_22 = {
    Text = "Tulu! Mettimi giù!"
  },
  AvgDialog_24078_Content_23 = {
    Text = "Due tentacoli robusti avvolsero Ramona e Celeste. In un istante, Tulu le trasportò in fondo al corridoio."
  },
  AvgDialog_24078_Content_24 = {
    Text = "Golia rise selvaggiamente, strappando via la sua lama. Si accovacciò davanti a te, afferrandoti il mento per forzare il tuo sguardo."
  },
  AvgDialog_24078_Content_25 = {
    Text = "Te l'avevo detto: non farti eliminare da qualche soldatuccio qualunque prima che io mi sia goduto lo spettacolo fino in fondo."
  },
  AvgDialog_24078_Content_26 = {
    Text = "Il suo tono era metà beffardo, metà sincero, le sue vere intenzioni impossibili da decifrare."
  },
  AvgDialog_24078_Content_27 = {
    Text = [[
Ma hai fegato, questo te lo concedo.
Peccato che Miryam sia decisa a trascinare qualcuno indietro per rispondere di tutto questo.]]
  },
  AvgDialog_24078_Content_28 = {
    Text = "Era semplice divertimento, o Golia covava una qualche slealtà verso Miryam..."
  },
  AvgDialog_24078_Content_3 = {
    Text = "Che nemico implacabile...!"
  },
  AvgDialog_24078_Content_4 = {
    Text = "Non affrontatelo! Tulu, coprici la fuga!"
  },
  AvgDialog_24078_Content_5 = {
    Text = "Trascinasti via Ramona, disperato di fuggire dalla cabina."
  },
  AvgDialog_24078_Content_6 = {
    Text = "Golia combatteva con la sua solita ferocia brutale, sogghignando mentre scagliava la sua enorme mannaia verso le vostre figure in fuga."
  },
  AvgDialog_24078_Content_7 = {Text = "Attento!"},
  AvgDialog_24078_Content_8 = {
    Text = "Spingesti Ramona in avanti, ma la lama ti trafisse il polpaccio, inchiodandoti al pavimento. Il comunicatore ti scivolò dal petto."
  },
  AvgDialog_24078_Content_9 = {
    Text = "L'agonia ti accecò, un rombo ronzante che soffocò l'urlo di Ramona."
  },
  AvgDialog_24079_Content_1 = {
    Text = "Inseguendo le Stelle"
  },
  AvgDialog_24079_Content_10 = {
    Text = "Ogni volta che Ramona si spostava, anche solo per alleviare il dolore, Caecus le lanciava uno sguardo diffidente, l'arma puntata su di lei."
  },
  AvgDialog_24079_Content_11 = {
    Text = "Caecus, tu..."
  },
  AvgDialog_24079_Content_12 = {
    Text = "State fermi!\nNon pensate di poter combinare qualcosa sotto il naso di Lady Miryam. Vi terrò a bada."
  },
  AvgDialog_24079_Content_13 = {
    Text = "<Gray:...Mi esclude completamente. Ha paura di Miryam?>"
  },
  AvgDialog_24079_Content_14 = {
    Text = "<Gray:Un Risveglio legato a un altro Risveglio... Miryam dev'essere qualcosa di straordinario...>"
  },
  AvgDialog_24079_Content_15 = {
    Text = "Ramona inspirò profondamente, sforzandosi di ignorare il dolore insistente alla caviglia mentre scrutava la sala motori in cerca di un'opportunità."
  },
  AvgDialog_24079_Content_16 = {
    Text = "Quando il Lucchetto scattò, i suoi muscoli si tesero."
  },
  AvgDialog_24079_Content_17 = {
    Text = "Coff, coff... Questo posto puzza di Decomposizione stantia."
  },
  AvgDialog_24079_Content_18 = {
    Text = "La figura aggraziata della donna contrastava nettamente con i Navigatori. Il suo volto era contratto dal disgusto, chiaramente riluttante a camminare al fianco del culto."
  },
  AvgDialog_24079_Content_19 = {
    Text = "Ehi! Dammi una mano, vuoi? Sto gestendo un Risveglio qui!"
  },
  AvgDialog_24079_Content_2 = {
    Text = [[
Cargo d'alto mare: Sona-Nyl
Sala motori]]
  },
  AvgDialog_24079_Content_20 = {
    Text = "Un Risvegliato?"
  },
  AvgDialog_24079_Content_21 = {
    Text = "Ramona voltò di scatto la testa verso la porta. Una ragazza in un vestito bianco, legata dal cultista in nero, incrociò il suo sguardo."
  },
  AvgDialog_24079_Content_22 = {
    Text = "Pura, immacolata, trascendente, fragile — innumerevoli aggettivi balenarono nella mente di Ramona."
  },
  AvgDialog_24079_Content_23 = {Text = "...Umano."},
  AvgDialog_24079_Content_24 = {
    Text = "Il cultista in nero spinse la ragazza Risveglio. Lei mascherò la sua lieve sorpresa, il volto che tornava a un vuoto privo di emozioni."
  },
  AvgDialog_24079_Content_25 = {
    Text = "Di cosa ti preoccupi? Se fosse più pericolosa di te, credi che Miryam ci avrebbe fatto trascinare lei all'avamposto?"
  },
  AvgDialog_24079_Content_26 = {
    Text = [[
Hmph... annidarsi in questa topaia lurida e fatiscente.
Questi selvaggi non hanno classe.]]
  },
  AvgDialog_24079_Content_27 = {
    Text = "Basta così. Una volta finito e tornati all'<Yellow:avamposto dei Portatori di Luce>, potrai lamentarti quanto vuoi.\nNon dimenticare, siamo nel loro territorio adesso."
  },
  AvgDialog_24079_Content_28 = {
    Text = "<Gray:Avamposto del Portatore di Luce... queste due vengono dalla Chiesa dei Portatori di Luce? Quindi sono legate ai Navigatori, dopotutto.>"
  },
  AvgDialog_24079_Content_29 = {
    Text = "La donna sbuffò, prese la corda che legava la ragazza Risveglio e la trascinò bruscamente verso Caecus."
  },
  AvgDialog_24079_Content_3 = {
    Text = "Scorie di carbone ammassate in cumuli, e i Navigatori dalla pelle umida si trascinavano per la sala macchine, le pinne caudali che lasciavano tracce nerastre e fangose sul pavimento."
  },
  AvgDialog_24079_Content_30 = {
    Text = "Lady Miryam mi ha chiesto di dirti: tieni d'occhio entrambe."
  },
  AvgDialog_24079_Content_31 = {
    Text = "Nonostante la scortesia del Portatore di Luce, Caecus rimase inquietantemente calmo. Tirò la ragazza Risveglio accanto a Ramona e riprese la sua silenziosa veglia."
  },
  AvgDialog_24079_Content_32 = {
    Text = "Un fenomeno da baraccone dopo l'altro, che cercano la\"Rinascita\"di un dio-re corrotto dalla Dissoluzione? Pura follia."
  },
  AvgDialog_24079_Content_33 = {
    Text = "Non so perché <Blue:Lady Lanterna> si disturbi ancora con questi pazzi. Avete già rovinato tutto venticinque anni fa."
  },
  AvgDialog_24079_Content_34 = {Text = "Silenzio!"},
  AvgDialog_24079_Content_35 = {
    Text = "Ehi, che bella compagnia."
  },
  AvgDialog_24079_Content_36 = {
    Text = "Una voce profonda e rude squarcia il silenzio, zittendo all'istante i Devoti del Portatore di Luce."
  },
  AvgDialog_24079_Content_37 = {
    Text = "Lord Golia."
  },
  AvgDialog_24079_Content_38 = {
    Text = "Caecus china il capo orgoglioso davanti al gigante, il tono carico di reverenza.\nGolia ignorò la sua lealtà, rivolgendosi ai Devoti della Chiesa della luce del tempio con vivo interesse."
  },
  AvgDialog_24079_Content_39 = {
    Text = "Perché fermarvi? Sono tutt'orecchi. Continuate a spettegolare su Lemuria."
  },
  AvgDialog_24079_Content_4 = {
    Text = "<Gray:C'è solo un'uscita. Dalla mia posizione, uno scatto a tutta velocità richiederebbe sette secondi, ma...>"
  },
  AvgDialog_24079_Content_40 = {
    Text = "Non diede loro alcuna possibilità di ritrattare, spostando bruscamente lo sguardo verso la porta."
  },
  AvgDialog_24079_Content_41 = {
    Text = "Scommetto che nessuno ha mai osato dire \"Reame Divino\" in quel tono davanti a te, eh, Miryam?"
  },
  AvgDialog_24079_Content_42 = {
    Text = "La figura di Miryam si dissolse nelle ombre sulla soglia. La sua espressione era imperscrutabile, ma un freddo agghiacciante emanava da lei."
  },
  AvgDialog_24079_Content_43 = {
    Text = "<Gray:Quand'è arrivata lì?! Non l'ho nemmeno vista avvicinarsi...>"
  },
  AvgDialog_24079_Content_44 = {
    Text = "Una brezza gelida strisciò sul pavimento, prosciugando il colore dai volti dei Portatori di Luce. Era tornata con Golia? Quanto aveva sentito?"
  },
  AvgDialog_24079_Content_45 = {
    Text = "Ma con sorpresa di Ramona — e dei Devoti del Portatore di Luce — Miryam non esplose di rabbia né mostrò il minimo segno di disappunto."
  },
  AvgDialog_24079_Content_46 = {
    Text = "Scrutò la stanza con altero disprezzo, come se il trambusto fosse un mero cinguettio d'uccelli."
  },
  AvgDialog_24079_Content_47 = {
    Text = "Golia, come procede il tuo Compito?"
  },
  AvgDialog_24079_Content_48 = {
    Text = "Ah... quei ratti dei Mythag sono bravi a sgattaiolare. Ve l'ho detto, a meno che non smontiamo questa nave pezzo per pezzo, non li troverò. E poi, abbiamo un ostaggio, no?"
  },
  AvgDialog_24079_Content_49 = {
    Text = "Golia indicò con la sua enorme mannaia in direzione di Ramona."
  },
  AvgDialog_24079_Content_5 = {
    Text = "Si chinò a massaggiarsi la caviglia. Sebbene avesse trattato l'articolazione lussata, il gonfiore era inevitabile. Anche un tocco leggero accendeva un dolore bruciante."
  },
  AvgDialog_24079_Content_50 = {
    Text = "Tenetevi stretta questa signora, e il suo compagno verrà a fiutare in giro abbastanza presto."
  },
  AvgDialog_24079_Content_51 = {
    Text = "A proposito, perché avete trascinato qui la Risvegliatrice di Elton? Dov'è Elton?"
  },
  AvgDialog_24079_Content_52 = {
    Text = "Il rito si avvicina. Le condizioni della Madre Divina sono critiche. I miei accoliti conoscono le rune del sonno, ma se possibile, non voglio che soffra."
  },
  AvgDialog_24079_Content_53 = {
    Text = "Finché Celeste è nelle nostre mani, Elton consegnerà la Madre Divina per impedire che il Sona-Nyl sfugga al controllo..."
  },
  AvgDialog_24079_Content_54 = {
    Text = [[
<Gray:Quindi questa Risvegliatrice controlla la nave fantasma Sona-Nyl.
Questo Dominio dev'essere opera sua.>]]
  },
  AvgDialog_24079_Content_55 = {
    Text = "<Gray:Aspetta... forse c'è un modo.>"
  },
  AvgDialog_24079_Content_56 = {
    Text = "Mentre tutti gli sguardi erano puntati su Miryam, Ramona sfiorò la mano della Risvegliatrice. Celeste alzò lo sguardo, il volto privo di ogni emozione."
  },
  AvgDialog_24079_Content_57 = {
    Text = "<Small:Celeste... potrei avere un modo per farci uscire di qui.>"
  },
  AvgDialog_24079_Content_58 = {
    Text = "Un tremolio di stupore trafisse la nebbia negli occhi di Celeste."
  },
  AvgDialog_24079_Content_59 = {
    Text = "<Small:Sei la padrona del Dominio. Se potessi farlo svanire per un istante, seminare il caos tra i Navigatori...>"
  },
  AvgDialog_24079_Content_6 = {
    Text = "<Gray:Livello di dolore intorno a quattro. In base alla valutazione di mobilità di questo semestre, la mia velocità è calata del venti per cento...>"
  },
  AvgDialog_24079_Content_60 = {
    Text = "Celeste non rispose, si limitò a sbattere le palpebre. Ramona non era sicura che avesse capito, ma i suoi guanti erano già scivolosi di sudore nervoso."
  },
  AvgDialog_24079_Content_61 = {
    Text = "<Small:Questo è... il tuo Desiderio?>"
  },
  AvgDialog_24079_Content_62 = {
    Text = "Ramona si bloccò, ma annuì d'istinto prima ancora che la sua mente potesse elaborare."
  },
  AvgDialog_24079_Content_63 = {
    Text = "Celeste sollevò la bussola in alto. Flussi radianti vorticarono attorno alla sua gonna, poi svanirono senza lasciare traccia."
  },
  AvgDialog_24079_Content_64 = {
    Text = "In quell'istante, la vera aria del Mare del Nord irruppe, fredda e umida. Grida esplosero dal ponte."
  },
  AvgDialog_24079_Content_65 = {
    Text = "Luna! La Luna!"
  },
  AvgDialog_24079_Content_66 = {
    Text = "In quello stesso istante, la sala macchine sprofondò nell'oscurità. Un silenzio alieno e profondo si propagò, inghiottendo ogni forma, ma l'adrenalina di Ramona esplose in un'ondata."
  },
  AvgDialog_24079_Content_67 = {
    Text = "<Small:Ora!>"
  },
  AvgDialog_24079_Content_68 = {
    Text = "Ramona afferrò la mano della Risvegliatrice, convogliando tutta la sua forza nelle gambe. Si lanciò attraverso i Navigatori, correndo verso l'uscita."
  },
  AvgDialog_24079_Content_7 = {
    Text = "<Gray:Non c'è abbastanza tempo. La sala macchine è il loro fortino adesso. Troppi nemici: verrei fermata dai Navigatori prima di raggiungere la porta.>"
  },
  AvgDialog_24079_Content_8 = {
    Text = "<Gray:E poi... questo tizio mi tiene d'occhio come un falco.>"
  },
  AvgDialog_24079_Content_9 = {
    Text = "I Navigatori si preparavano per il \"rito,\" mentre il ragazzo Risveglio adempiva lealmente al suo dovere, sorvegliandola senza muoversi di un passo."
  },
  AvgDialog_24080_Content_1 = {
    Text = "Scuotesti la testa, portando un dito alle labbra per imporre il silenzio. Ma quando il tuo sguardo scivolò sulla figura nell'ombra, quasi ti sfuggì un'esclamazione."
  },
  AvgDialog_24080_Content_2 = {
    Text = "<Small:Quella è Celeste, una Risvegliata...>"
  },
  AvgDialog_24080_Content_3 = {
    Text = "L'avevi vista nelle visioni a bordo della Sona-Nyl — un'ombra familiare eppure aliena. Era Celeste, colei che controllava il Dominio."
  },
  AvgDialog_24080_Content_4 = {
    Text = "La figura chiave, che si supponeva nelle grinfie di Miryam, era fuggita con Ramona. Sconvolgente, eppure in qualche modo prevedibile."
  },
  AvgDialog_24080_Content_5 = {
    Text = "La tua compagna non è mai stata il tipo da starsene con le mani in mano."
  },
  AvgDialog_24080_Content_6 = {
    Text = "<Small:...Aspetta, quello è Tulu, Fascicolo N. 6291?!>"
  },
  AvgDialog_24080_Content_7 = {
    Text = "<Small:Raggiungiamo prima il Capitano e Murphy. Vi spiegherò tutto.>"
  },
  AvgDialog_24081_Content_1 = {
    Text = "Un Altro Miracolo"
  },
  AvgDialog_24081_Content_10 = {
    Text = "Capitano, stai tremando tutto."
  },
  AvgDialog_24081_Content_11 = {
    Text = "...Vecchia abitudine. Non sono uno Studente selezionato dall'Università di Mythag come voi. Solo un tipo ordinario — nessuna forza mentale da Corpo d'Acciaio, nessuna Abilità di vedere la <Yellow:Dissoluzione>."
  },
  AvgDialog_24081_Content_12 = {
    Text = "Durante la Rinascita dalla Terra di un Risvegliato, la sua coscienza viene inevitabilmente contaminata da entità sconosciute. Quella contaminazione provoca la perdita di controllo."
  },
  AvgDialog_24081_Content_13 = {
    Text = "Un legame è un modo per effettuare la Soppressione, ma se il Connettore è una persona ordinaria priva del dono..."
  },
  AvgDialog_24081_Content_14 = {
    Text = "Di cosa state parlando? Cos'è questa \"perdita di controllo\"?"
  },
  AvgDialog_24081_Content_15 = {
    Text = "Elton prese il portasigarette che Murphy aveva raccolto, ridacchiando sommessamente mentre la sorprendeva a spingere con un calcio il tabacco sparso in un angolo."
  },
  AvgDialog_24081_Content_16 = {
    Text = "Significa che se non troviamo Celeste, questa nave potrebbe impazzire e affondare."
  },
  AvgDialog_24081_Content_17 = {
    Text = "Il volto di Murphy si contrasse, le labbra tremanti, incapace di trovare le parole."
  },
  AvgDialog_24081_Content_18 = {
    Text = "Piano, piano, non aver paura."
  },
  AvgDialog_24081_Content_19 = {
    Text = "Diede una pacca rassicurante sulla testa rigida di Murphy, poi si voltò verso di voi e Tulu."
  },
  AvgDialog_24081_Content_2 = {Text = "Celeste..."},
  AvgDialog_24081_Content_20 = {
    Text = "Riesco a percepire la direzione generale di Celeste. Voi avete portato Murphy da me. Confido che possiate aiutarmi a trovare Celeste, giusto?"
  },
  AvgDialog_24081_Content_21 = {
    Text = "Tulu, possiamo?"
  },
  AvgDialog_24081_Content_22 = {
    Text = "Tulu non rispose. Invece, spalancò la porta del rifugio, facendo segno che avrebbe guidato il cammino."
  },
  AvgDialog_24081_Content_3 = {
    Text = "Elton chiuse gli occhi e lasciò uscire un lungo sospiro, come se potesse esalare tutta la lordura che aveva dentro."
  },
  AvgDialog_24081_Content_4 = {
    Text = [[
Quando i Navigatori sono saliti a bordo, Celeste e io non eravamo insieme.
Ho aspettato in questo rifugio, e voi siete i primi a trovarmi.]]
  },
  AvgDialog_24081_Content_5 = {
    Text = "Come... come è possibile? Celeste non è fatta per combattere. E se lei..."
  },
  AvgDialog_24081_Content_6 = {
    Text = "Sta bene. Il Legame tra noi è stabile."
  },
  AvgDialog_24081_Content_7 = {
    Text = "Legame? Quindi Celeste è davvero una Risvegliatrice..."
  },
  AvgDialog_24081_Content_8 = {
    Text = "Elton abbozzò un sorriso amaro, allungando istintivamente la mano verso il portasigarette. Ma quando le sue dita sfiorarono il metallo freddo, la mano gli tremò violentemente, e il portasigarette cadde a terra con un tintinnio, spargendo tabacco ovunque."
  },
  AvgDialog_24081_Content_9 = {
    Text = "Notaste improvvisamente le mani di Elton tremare, che fosse per lo Shock residuo o per il puro Esaurimento."
  },
  AvgDialog_24082_Content_1 = {
    Text = "Tulu, cosa stai guardando?"
  },
  AvgDialog_24082_Content_10 = {
    Text = "La mente e il corpo del tramite faticano a sostenere il potere del Risvegliatore.\nMantenere un Dominio che scherma l'attrazione celeste—probabilmente ha spinto quella Risvegliatrice al limite."
  },
  AvgDialog_24082_Content_11 = {
    Text = "Schermare l'attrazione celeste... Murphy!"
  },
  AvgDialog_24082_Content_12 = {
    Text = "Tutti si voltarono verso Murphy al tuo grido. Stringeva il davanti del cappotto, le dita che fremevano in modo incontrollabile."
  },
  AvgDialog_24082_Content_13 = {
    Text = "Reclinò la testa all'indietro, la cartilagine della gola che si contorceva dal dolore. Ogni respiro le bruciava i polmoni, ogni cellula tremava sotto lo sforzo."
  },
  AvgDialog_24082_Content_14 = {Text = "Murphy?!"},
  AvgDialog_24082_Content_15 = {
    Text = "Qualcosa non va in lei. Eliminate quelle creature attirate dall'odore."
  },
  AvgDialog_24082_Content_2 = {
    Text = "Dopo aver eliminato un'altra ondata di nemici, Tulu si fermò presso la ringhiera della nave, aggrottando la fronte mentre studiava il confine del Dominio che avvolgeva l'imbarcazione."
  },
  AvgDialog_24082_Content_3 = {
    Text = "La presenza del Dominio si sta indebolendo."
  },
  AvgDialog_24082_Content_4 = {
    Text = "Per sfuggire all'aria opprimente della nave, stormi di uccelli marini si dispersero, lanciandosi verso la luce iridescente."
  },
  AvgDialog_24082_Content_5 = {
    Text = "Uno, due, tre — si schiantarono contro il cielo, disperati di liberarsi, solo per essere dolcemente respinti dalla Barriera del Dominio."
  },
  AvgDialog_24082_Content_6 = {
    Text = "Sotto le collisioni incessanti, il Dominio si fece trasparente, rivelando una luna piena, impossibilmente vicina e rotonda."
  },
  AvgDialog_24082_Content_7 = {
    Text = "Il momento tremolò e passò, eppure tutti lo colsero."
  },
  AvgDialog_24082_Content_8 = {
    Text = "Il Dominio è appena... svanito per un istante?"
  },
  AvgDialog_24082_Content_9 = {
    Text = "No, è impossibile! Celeste non farebbe mai..."
  },
  AvgDialog_24083_Content_1 = {
    Text = [[
Guidati da Celeste, si fecero strada tra le cabine labirintiche.
Ben presto, si infilarono in una stanza buia.]]
  },
  AvgDialog_24083_Content_10 = {
    Text = "La pesante porta si aprì con uno scricchiolio, e una luce ambrata si riversò nella cabina. I suoi nervi tesi si rilassarono quando intravide il mantello familiare."
  },
  AvgDialog_24083_Content_11 = {Text = "Custode."},
  AvgDialog_24083_Content_2 = {
    Text = "Passi pesanti rimbombavano sul ponte sopra di loro, ciascuno come un martello del destino, che incuteva terrore nelle loro anime."
  },
  AvgDialog_24083_Content_3 = {
    Text = "<Small:Passi così pesanti... Celeste, sai chi sta facendo quel rumore?>"
  },
  AvgDialog_24083_Content_4 = {
    Text = "Celeste scosse la testa, il volto nuovamente privo di espressione."
  },
  AvgDialog_24083_Content_5 = {
    Text = "<Small:Potrebbe essere qualcuno mandato dai Navigatori a darci la caccia? Spero che il Custode non si scontri con loro direttamente. Senza di me, {Male=non è all'altezza,Female=non è all'altezza}...>"
  },
  AvgDialog_24083_Content_6 = {
    Text = "...Sono qui."
  },
  AvgDialog_24083_Content_7 = {Text = "Cosa?"},
  AvgDialog_24083_Content_8 = {
    Text = "Prima che Celeste finisse, passi rapidi riecheggiarono sul loro ponte, avvicinandosi sempre più fino a fermarsi davanti alla loro cabina."
  },
  AvgDialog_24083_Content_9 = {
    Text = "Ramona fece segno a Celeste di restare immobile, impugnò la sua arma e si nascose dietro la porta."
  },
  AvgDialog_24084_Content_1 = {
    Text = "Adagiasti Murphy sulle tue ginocchia. I suoi muscoli erano rigidi, come stringere una statua di pietra."
  },
  AvgDialog_24084_Content_10 = {
    Text = "È rimasta in questo Dominio troppo a lungo, da qui la reazione intensa. Ora che il Dominio si sta stabilizzando, si riprenderà presto."
  },
  AvgDialog_24084_Content_11 = {
    Text = "Prima che Tulu finisse, Murphy si sollevò a sedere, madida di sudore. Si toccò il petto, il volto vuoto di Confusione."
  },
  AvgDialog_24084_Content_12 = {
    Text = "Io... sono ancora viva..."
  },
  AvgDialog_24084_Content_13 = {
    Text = "Dobbiamo rimuoverlo in fretta. Anche se questo Dominio blocca l'attrazione celeste, la Sua sola presenza è un fardello per te."
  },
  AvgDialog_24084_Content_14 = {
    Text = "Facile a dirsi..."
  },
  AvgDialog_24084_Content_15 = {
    Text = "Hai ricordato la Specie Parassita aggrappata al suo cuore."
  },
  AvgDialog_24084_Content_16 = {
    Text = "I Suoi vasi si sono fusi con la sua aorta. Nemmeno i migliori chirurghi di Londinium potrebbero garantire un'Operazione simile."
  },
  AvgDialog_24084_Content_17 = {
    Text = "Il Dominio della Sona-Nyl aveva arrestato l'influenza celeste. Poteva esserci un altro modo per guadagnare più tempo a Murphy?"
  },
  AvgDialog_24084_Content_18 = {
    Text = "Il tempo... il tempo... fermati..."
  },
  AvgDialog_24084_Content_19 = {Text = "Murphy..."},
  AvgDialog_24084_Content_2 = {
    Text = "Capitano, sai cosa le sta succedendo?"
  },
  AvgDialog_24084_Content_20 = {
    Text = "Il Capitano la sollevò con movimenti lenti e cauti, come se maneggiasse porcellana Fragile."
  },
  AvgDialog_24084_Content_21 = {
    Text = "Ragazzo, ti ho visto pensare. Hai una soluzione?"
  },
  AvgDialog_24084_Content_22 = {
    Text = "Non proprio una soluzione... ed è rischiosa."
  },
  AvgDialog_24084_Content_23 = {
    Text = "A questo punto, il rischio è l'ultimo dei nostri problemi.\nParla. Qualsiasi cosa per togliere Murphy dal pericolo..."
  },
  AvgDialog_24084_Content_24 = {
    Text = "L'Università di Mythag sta lavorando a una Ricerca sulla \"sospensione del tempo\"."
  },
  AvgDialog_24084_Content_25 = {
    Text = "Intendi la runa che hai riportato dal Sanatorio di Rye..."
  },
  AvgDialog_24084_Content_26 = {
    Text = "Esattamente. Doll e la Sig.ra Winkle la stanno studiando, sperando di creare uno spazio al sicuro dal <Red:Segugio Dimensionale> per gli esperimenti."
  },
  AvgDialog_24084_Content_27 = {
    Text = "La ricerca sta prendendo forma. Prima della nostra partenza, la signora Winkle stava già preparando i test sugli animali."
  },
  AvgDialog_24084_Content_28 = {
    Text = "Non preoccuparti."
  },
  AvgDialog_24084_Content_29 = {
    Text = "La tua scuola... non è sul mare, vero?\nTornare a terra, e poi alla tua scuola... non c'è tempo."
  },
  AvgDialog_24084_Content_3 = {
    Text = "Il dio... il dio dentro di lei..."
  },
  AvgDialog_24084_Content_30 = {
    Text = "Inoltre, Celeste... se è nelle mani di quella donna, che questa nave arrivi a riva o meno è tutto da vedere."
  },
  AvgDialog_24084_Content_31 = {
    Text = "Ecco perché dobbiamo muoverci più in fretta. Capitano, puoi indicarmi la posizione approssimativa di Celeste? Io e Tulu la troveremo. Tu e Murphy, tornate al rifugio."
  },
  AvgDialog_24084_Content_32 = {Text = "No!"},
  AvgDialog_24084_Content_33 = {Text = "Capitano?"},
  AvgDialog_24084_Content_34 = {
    Text = "Elton si rese conto del suo scatto d'ira e cercò il portasigarette, solo per ricordare, aprendo la scatola vuota, che il tabacco era finito da tempo."
  },
  AvgDialog_24084_Content_35 = {
    Text = "...Non andare dietro a Celeste."
  },
  AvgDialog_24084_Content_36 = {
    Text = "Perché? Capitano, sai qualcosa?"
  },
  AvgDialog_24084_Content_37 = {
    Text = "Elton si scostò dal fianco di Murphy, la sua figura alta per metà celata nell'ombra, mentre abbassava lo sguardo su di te."
  },
  AvgDialog_24084_Content_38 = {
    Text = "Celeste... è con Miryam."
  },
  AvgDialog_24084_Content_39 = {Text = "Cosa?!"},
  AvgDialog_24084_Content_4 = {
    Text = "L'Espressione di Tulu mutò impercettibilmente. Un Tentacolo, sotto il suo controllo, si avvolse attorno al braccio sinistro di Murphy."
  },
  AvgDialog_24084_Content_40 = {
    Text = "Quel gigante... Golia, ha trovato me e Celeste non appena è salito a bordo. Ci ha portate da Miryam..."
  },
  AvgDialog_24084_Content_41 = {
    Text = "Mossa da un destino comune di anime erranti, ti ho donato il mezzo per riportare il Defunto in questo mondo."
  },
  AvgDialog_24084_Content_42 = {
    Text = "La sua presenza ha esaudito il tuo desiderio più profondo. Sicuramente hai trovato conforto nei tuoi cari perduti..."
  },
  AvgDialog_24084_Content_43 = {
    Text = [[
Ma il mio desiderio, la grande speranza che Nostro Signore mi ha concesso, risiede in quella ragazza.
Restituitemi la Madre Divina.]]
  },
  AvgDialog_24084_Content_44 = {
    Text = "Come Somma Sacerdotessa, giuro: quando Nostro Signore rinascerà, quando il Reame Divino sorgerà... anche tu vi entrerai, trovando pace eterna."
  },
  AvgDialog_24084_Content_45 = {
    Text = "Alta Sacerdotessa, sono rimasto sconvolto nel sapere della scomparsa della Madre Divina.\nMa ve l'ho detto—non è su questa nave."
  },
  AvgDialog_24084_Content_46 = {
    Text = "Perché fingersi Il Folle con tanta ostentazione?"
  },
  AvgDialog_24084_Content_47 = {
    Text = "Un tempo ammiravo la tua astuzia e la tua risolutezza. Cosa ha cambiato la tua lealtà verso di me?\nQuesto fragile <Blue:Golem>?"
  },
  AvgDialog_24084_Content_48 = {
    Text = "È stata una mia decisione. Sono il padrone di questa nave. Celeste non ha quasi volontà propria... come potrebbe influenzarmi?"
  },
  AvgDialog_24084_Content_49 = {
    Text = "Davvero? Ti ho dato il potere di risvegliarla, e posso ridurla a un mucchio di polvere d'argento."
  },
  AvgDialog_24084_Content_5 = {Text = "Silenzio."},
  AvgDialog_24084_Content_50 = {Text = "Tu...!"},
  AvgDialog_24084_Content_51 = {
    Text = "Trova la Madre Divina. Portamela, integra e illesa."
  },
  AvgDialog_24084_Content_52 = {
    Text = "Questa è la tua ultima occasione, Elton."
  },
  AvgDialog_24084_Content_6 = {
    Text = "Tulu chiuse gli occhi, percependo attraverso il suo Tentacolo. Per un istante, il ponte fu colmato soltanto dal suono delle onde contro lo scafo e dai gemiti di dolore di Murphy."
  },
  AvgDialog_24084_Content_7 = {
    Text = "I secondi si dilatarono in modo straziante. Proprio quando la tua pazienza era prossima al punto di Rottura, Tulu ritirò il suo Tentacolo."
  },
  AvgDialog_24084_Content_8 = {Text = "Come sta?"},
  AvgDialog_24084_Content_9 = {
    Text = "Nel momento in cui il Dominio cedette, il \"falso dio\" dentro di lei avvertì un'attrazione potente."
  },
  AvgDialog_24091_Content_1 = {
    Text = "I Navigatori non provano molto dolore. Da bambina calpestavo le loro code—quasi nessuno reagiva."
  },
  AvgDialog_24091_Content_10 = {
    Text = "Solo questa volta. Disconnettiti quando torneremo al campus."
  },
  AvgDialog_24091_Content_11 = {
    Text = "Annuisti, stringendo forte la tua Chiave d'Argento. Chiudendo gli occhi, sprofondasti nell'oscurità."
  },
  AvgDialog_24091_Content_12 = {
    Text = "Inseguisti la scintilla più luminosa nella tua visuale, la mente compressa da innumerevoli presenze nel vuoto gremito, il cervello lacerato dall'agonia."
  },
  AvgDialog_24091_Content_13 = {
    Text = "Ti sei sforzato di \"protenderti,\" afferrando quella stella."
  },
  AvgDialog_24091_Content_14 = {
    Text = "Come se la tua anima avesse abbandonato il corpo, la tua visuale si levò in alto, trascinata da una forza irresistibile."
  },
  AvgDialog_24091_Content_15 = {
    Text = "Hai visto te stesso, hai visto Miryam, hai visto una città che si inclinava in un diluvio... e infine, un giovane re freddo e regale in cima a una montagna."
  },
  AvgDialog_24091_Content_16 = {
    Text = [[
Riaprendo gli occhi, un torrente di Gnosi scosse i tuoi nervi come una scarica elettrica.
Doloroso, eppure colmo di un potere senza precedenti.]]
  },
  AvgDialog_24091_Content_17 = {
    Text = "Heh... finalmente, il momento che stavo aspettando."
  },
  AvgDialog_24091_Content_18 = {
    Text = "Tulu colpì per primo Golia, negandogli la possibilità di agire."
  },
  AvgDialog_24091_Content_2 = {
    Text = "Significa che continueranno a rialzarsi... non possiamo garantire che ogni colpo sia mortale—questo scontro ci logorerà."
  },
  AvgDialog_24091_Content_20 = {
    Text = "I suoi tentacoli si abbatterono sulle scorie di carbone, sollevando una nube di polvere nera.\nQuando la polvere si posò, la figura di Miryam emerse."
  },
  AvgDialog_24091_Content_21 = {
    Text = "Miryam, hai visto? Quel moccioso fasullo è collegato a qualcuno—"
  },
  AvgDialog_24091_Content_22 = {
    Text = "Il serpente scatenò una tempesta di colpi su Golia, la cui forza lo scagliò contro la parete di ferro della sala macchine."
  },
  AvgDialog_24091_Content_23 = {
    Text = "Come una meteora che si schianta al suolo, Golia si conficcò nella paratia."
  },
  AvgDialog_24091_Content_24 = {
    Text = "Imperdonabile."
  },
  AvgDialog_24091_Content_25 = {
    Text = "Creatura immonda. Osi sfidare il Nostro Signore, rubando il potere divino di Lemuria..."
  },
  AvgDialog_24091_Content_26 = {
    Text = "Miryam avanzò, a capo chino, i suoi piedi nudi increspavano l'aria come foglie sull'acqua."
  },
  AvgDialog_24091_Content_27 = {
    Text = "Oltraggioso... nessuno, nessuno tranne me può risvegliare l'Inviato del Reame Divino!"
  },
  AvgDialog_24091_Content_28 = {
    Text = "Qualcosa... qualcosa non va in lei! Corsa!"
  },
  AvgDialog_24091_Content_29 = {
    Text = [[
In un istante, le ombre che avvolgevano la sala macchine si solidificarono.
Strutture indescrivibili e contorte si levarono dal suolo.]]
  },
  AvgDialog_24091_Content_3 = {
    Text = "Ci siamo solo io, Tulu e il Custode a poter combattere. Le nostre opzioni in battaglia sono limitate..."
  },
  AvgDialog_24091_Content_30 = {
    Text = "Re... Mio Signore... Murphy... Murphy..."
  },
  AvgDialog_24091_Content_32 = {
    Text = "Non è troppo tardi.\nTorna alla setta, e rimarrai la venerata Madre Divina."
  },
  AvgDialog_24091_Content_33 = {
    Text = "Il tuo funerale sarà il rito più grandioso nella storia del Reame Divino, venerato da migliaia di fedeli... il tuo nome inciso negli annali eterni."
  },
  AvgDialog_24091_Content_34 = {
    Text = "Torna da me. Insieme, noi... giustizieremo questo <Blue:blasfemo>."
  },
  AvgDialog_24091_Content_35 = {
    Text = "Punisci questa lordura che si spaccia per il Nostro Signore, restituisciGli il Suo potere.\nSolo allora il Nostro Signore sarà completo."
  },
  AvgDialog_24091_Content_36 = {
    Text = "Miryam, apri gli occhi e guarda chi sono!"
  },
  AvgDialog_24091_Content_37 = {Text = "Silenzio!"},
  AvgDialog_24091_Content_38 = {
    Text = "Il serpente si dissolse e si riformò, lo spazio si deformava sotto il potere di Miryam."
  },
  AvgDialog_24091_Content_39 = {
    Text = "Falso dio, contraffazione, ciarlatano, irriverente... miscredente... Non usare la forma di @2!"
  },
  AvgDialog_24091_Content_4 = {
    Text = "A metà frase, gli occhi di Ramona si illuminarono."
  },
  AvgDialog_24091_Content_40 = {
    Text = "<Change>▼▼▼▼femer... blasf▼▼▼▼... B▼▼▼▼▼▼▼▼▼!"
  },
  AvgDialog_24091_Content_41 = {
    Text = "La sua voce degenerò in un rumore stridulo e incoerente, le mani che artigliavano la gola mentre il corpo si stirava e contorceva."
  },
  AvgDialog_24091_Content_42 = {
    Text = "Attento! Sta perdendo il controllo!"
  },
  AvgDialog_24091_Content_5 = {
    Text = "Tulu e il Custode... non vi siete collegati, vero?"
  },
  AvgDialog_24091_Content_6 = {
    Text = "Non ancora. Stai dicendo che dovrei collegarmi con Tulu..."
  },
  AvgDialog_24091_Content_7 = {
    Text = "I collegamenti non si limitavano a sopprimere la follia innata di un Risvegliato—canalizzavano il suo Aliemus, potenziando le prestazioni in combattimento."
  },
  AvgDialog_24091_Content_8 = {
    Text = "In parole semplici, il collegamento poteva amplificare l'abilità combattiva di un Risvegliato."
  },
  AvgDialog_24091_Content_9 = {Text = "..."},
  AvgDialog_24092_Content_1 = {
    Text = "Occhi Aperti"
  },
  AvgDialog_24092_Content_10 = {Text = "Ospite?"},
  AvgDialog_24092_Content_100 = {
    Text = "Prima di allontanarti troppo, un violento tremore, abbastanza forte da squarciare la nave, emerse dal basso."
  },
  AvgDialog_24092_Content_101 = {
    Text = "Nell'immane esplosione, le fiamme ruggirono verso il cielo, e l'aria rovente ti scaraventò sul ponte."
  },
  AvgDialog_24092_Content_102 = {
    Text = "— Prima che la coscienza svanisse di nuovo, l'ultima visione fu quella di uccelli marini che sfrecciavano nel cielo della luna piena."
  },
  AvgDialog_24092_Content_11 = {
    Text = "Come hai dormito?"
  },
  AvgDialog_24092_Content_12 = {Text = "Doll?!"},
  AvgDialog_24092_Content_13 = {
    Text = "Niente panico. Non è il momento di farti una ramanzina per aver dormito sul prato durante l'orario di lavoro."
  },
  AvgDialog_24092_Content_14 = {
    Text = "<Gray:Quindi mi farai una ramanzina dopo...>"
  },
  AvgDialog_24092_Content_15 = {
    Text = "Ramona evitò il tuo sguardo, la sua schiena che praticamente urlava \"arrangiati da solo.\""
  },
  AvgDialog_24092_Content_16 = {
    Text = "Il diario di Francis menzionava alcuni dettagli sulla Chiesa dei Portatori di Luce... ah, giusto, non hai ancora completato quei tre corsi obbligatori."
  },
  AvgDialog_24092_Content_17 = {
    Text = "La Chiesa dei Portatori di Luce venera l'idea che \"l'estinzione sia salvezza divina e unica redenzione dell'umanità\", attirando pazienti malati ad unirsi e contrarre la Dissoluzione."
  },
  AvgDialog_24092_Content_18 = {
    Text = [[
Grazie per il riepilogo, Professor Dexter.
Ma dubito che Erica apprezzi che tu le pesti i piedi.]]
  },
  AvgDialog_24092_Content_19 = {
    Text = "Colpa mia, colpa mia. A te la parola."
  },
  AvgDialog_24092_Content_2 = {
    Text = "Perché dormi qui?"
  },
  AvgDialog_24092_Content_20 = {
    Text = "Francis ha lasciato numerosi indizi che conducono alla Chiesa dei Portatori di Luce, in particolare alla loro \"resurrezione dei morti\"."
  },
  AvgDialog_24092_Content_21 = {
    Text = "Con la comparsa di Lily, abbiamo motivo di sospettare che abbiano padroneggiato l'arte di evocare i Risvegliati."
  },
  AvgDialog_24092_Content_22 = {
    Text = "Gli Awakener non dovrebbero essere top secret?"
  },
  AvgDialog_24092_Content_23 = {
    Text = [[
A quanto pare non hai prestato attenzione nemmeno a storia dei Risvegliati.
Comincio a chiedermi come tu abbia superato i test iniziali.]]
  },
  AvgDialog_24092_Content_24 = {
    Text = "Mythag non è l'unica a possedere la Tecnologia di Risveglio a Nucleo d'Argento o qualcosa di simile."
  },
  AvgDialog_24092_Content_25 = {
    Text = "L'origine del Risvegliatore può essere fatta risalire a prima del periodo Pluviale. I murali rinvenuti nelle tombe della XIX Dinastia dell'antico Remouahe sembrano raffigurare l'evocazione del Risvegliatore."
  },
  AvgDialog_24092_Content_26 = {
    Text = "La tecnologia \"Golem\" più vicina ai Risvegliati di Mythag proviene dai clan di stregoni del Levante."
  },
  AvgDialog_24092_Content_27 = {
    Text = "Ora torniamo in argomento."
  },
  AvgDialog_24092_Content_28 = {
    Text = "In base alle credenze e ai dettagli rituali nel diario, la \"Chiesa dei Portatori di Luce\" incontrata da Francis non corrisponde del tutto alle nostre informazioni."
  },
  AvgDialog_24092_Content_29 = {
    Text = [[
Inoltre, quel dispositivo di imaging remoto che ho lasciato a Herbert ha restituito questa runa.
Sospettiamo che Herbert sia l'intermediario tra Francis e la Chiesa della luce del tempio.]]
  },
  AvgDialog_24092_Content_3 = {
    Text = "Svegliati. Ti prenderai un raffreddore qui fuori."
  },
  AvgDialog_24092_Content_30 = {
    Text = "La tua prossima missione sul campo è verificare il contenuto del diario — e indagare sul legame tra questa runa e la Chiesa."
  },
  AvgDialog_24092_Content_31 = {
    Text = "Francis ha documentato i suoi spostamenti prima di dirigersi verso la regione polare.\nAndremo al suo punto d'imbarco — Bridgeport. Potrebbero esserci indizi laggiù."
  },
  AvgDialog_24092_Content_32 = {
    Text = "Quando sarete pronta, partiremo. Sarò il vostro compagno, come sempre."
  },
  AvgDialog_24092_Content_33 = {
    Text = "Il mio equipaggiamento è sempre pronto."
  },
  AvgDialog_24092_Content_34 = {
    Text = "Non ti serve un altro pisolino?"
  },
  AvgDialog_24092_Content_35 = {
    Text = "Non c'è bisogno!"
  },
  AvgDialog_24092_Content_36 = {
    Text = "Allora muoviamoci."
  },
  AvgDialog_24092_Content_37 = {
    Text = "Vado a prendere il conducente. Ci vediamo al cancello della scuola."
  },
  AvgDialog_24092_Content_38 = {
    Text = "La figura di Ramona svanì dalla vista, e tu ti voltasti per tornare al dormitorio a prendere l'equipaggiamento."
  },
  AvgDialog_24092_Content_39 = {Text = "Custode."},
  AvgDialog_24092_Content_4 = {
    Text = "Ugh... Ramona?"
  },
  AvgDialog_24092_Content_40 = {
    Text = "Questa missione potrebbe portare a un contatto diretto con la Chiesa del Portatore di Luce."
  },
  AvgDialog_24092_Content_41 = {
    Text = "Scoprire i loro segreti è secondario. La tua priorità assoluta è restare in vita. Non saprei dove andare a scovare un altro Custode tra le macerie."
  },
  AvgDialog_24092_Content_42 = {
    Text = "Non essere così duro con i ragazzi."
  },
  AvgDialog_24092_Content_43 = {
    Text = "Ma Doll ha ragione. I cultisti che hai affrontato finora erano solo manovalanza dell'anello esterno. Il vero nucleo della Chiesa non è ancora emerso."
  },
  AvgDialog_24092_Content_44 = {
    Text = "Sembra che ne sappia parecchio su di loro, Professore?"
  },
  AvgDialog_24092_Content_45 = {
    Text = "Ha, haha... solo un vecchio coinvolgimento."
  },
  AvgDialog_24092_Content_46 = {
    Text = "Se necessario, Mythag invierà investigatori esperti o chiederà persino aiuto al Comitato del trattato di Mystia per gestire la situazione."
  },
  AvgDialog_24092_Content_47 = {
    Text = "Mi raccomando, tornate vivi."
  },
  AvgDialog_24092_Content_48 = {
    Text = "Ricevuto. Torneremo sani e salvi."
  },
  AvgDialog_24092_Content_49 = {Text = "..."},
  AvgDialog_24092_Content_5 = {
    Text = "Per quanto tempo sono rimasto svenuto?"
  },
  AvgDialog_24092_Content_50 = {
    Text = "Che fissi? Se ne sono già andati."
  },
  AvgDialog_24092_Content_51 = {
    Text = "Non preoccuparti. Sanno quello che fanno."
  },
  AvgDialog_24092_Content_52 = {
    Text = "Non sono preoccupata. Anche se dovessimo addestrare un nuovo Custode, i fondi vengono dal conto della famiglia Dexter."
  },
  AvgDialog_24092_Content_53 = {
    Text = "Preoccupati per te. Ho sentito che la figlia di qualcuno ha un appuntamento galante all'opera."
  },
  AvgDialog_24092_Content_54 = {
    Text = "Ha, haha... i giovani d'oggi..."
  },
  AvgDialog_24092_Content_55 = {
    Text = "Quella notte"
  },
  AvgDialog_24092_Content_56 = {
    Text = "Una nave di linea per la regione polare? Siete fuori di testa! Non esiste una nave del genere qui, e nemmeno chiese!"
  },
  AvgDialog_24092_Content_57 = {
    Text = "Smettetela di chiedere. Siamo solo semplici pescatori. Non sappiamo niente!"
  },
  AvgDialog_24092_Content_58 = {
    Text = "Signora, la prego, aspetti—"
  },
  AvgDialog_24092_Content_59 = {
    Text = "Voi pezzi grossi di città venite a vessare noi gente di campagna!"
  },
  AvgDialog_24092_Content_6 = {
    Text = "Chi lo sa? Ti sei persino perso il briefing pre-missione di questo pomeriggio."
  },
  AvgDialog_24092_Content_60 = {
    Text = "Non è nostra intenzione—ehi!"
  },
  AvgDialog_24092_Content_61 = {
    Text = "La donna sbatté la porta. Se Ramona non ti avesse tirato indietro, saresti tornato a scuola con il naso storto."
  },
  AvgDialog_24092_Content_62 = {
    Text = "Bridgeport... questa città è strana."
  },
  AvgDialog_24092_Content_63 = {
    Text = "È la terza porta a cui bussiamo, e nessuno è disposto a condividere il minimo frammento di informazione su questo posto."
  },
  AvgDialog_24092_Content_64 = {
    Text = "Stiamo solo chiedendo indicazioni. È innaturale il modo in cui stanno tutti nascondendo qualcosa."
  },
  AvgDialog_24092_Content_65 = {
    Text = "Controlliamo i moli. Forse troveremo una pista laggiù."
  },
  AvgDialog_24092_Content_66 = {Text = "..."},
  AvgDialog_24092_Content_67 = {
    Text = "Che succede?"
  },
  AvgDialog_24092_Content_68 = {
    Text = "Forse è solo la mia immaginazione, ma mi è parso di sentire delle voci nel vento."
  },
  AvgDialog_24092_Content_69 = {
    Text = [[
Ehi, che tempismo perfetto. Due forestieri appena entrati.
Li prendiamo? Ci risparmia la fatica di cercarne altri.]]
  },
  AvgDialog_24092_Content_7 = {Text = "Briefing?"},
  AvgDialog_24092_Content_70 = {
    Text = "Spingeteli verso la nave."
  },
  AvgDialog_24092_Content_71 = {
    Text = "Tch, bastardo subdolo."
  },
  AvgDialog_24092_Content_72 = {
    Text = "Vai, Caecus. È il tuo momento di brillare."
  },
  AvgDialog_24092_Content_73 = {
    Text = "Ai vostri ordini, Lord Golia."
  },
  AvgDialog_24092_Content_74 = {
    Text = "Conto alla rovescia: tre ore"
  },
  AvgDialog_24092_Content_75 = {Text = "—Thud!"},
  AvgDialog_24092_Content_76 = {
    Text = "Un dolore lancinante ti colpì la fronte. L'impatto fece roteare il mondo intorno a te. Murphy colse l'occasione per liberarsi, stringendosi la testa tra le mani mentre fuggiva nelle profondità della cabina."
  },
  AvgDialog_24092_Content_77 = {
    Text = "Lo sapevo che non eravate brava gente!!"
  },
  AvgDialog_24092_Content_78 = {
    Text = "A-aspetta... ascoltami..."
  },
  AvgDialog_24092_Content_79 = {
    Text = "Conto alla rovescia: @2 minuti"
  },
  AvgDialog_24092_Content_8 = {
    Text = "Riguarda Francis—"
  },
  AvgDialog_24092_Content_80 = {
    Text = "Saliamo a bordo."
  },
  AvgDialog_24092_Content_81 = {
    Text = "Ti sei stancato di fissare?"
  },
  AvgDialog_24092_Content_82 = {
    Text = "Nel momento in cui il Dominio cedette, il \"falso dio\" dentro di lei avvertì un'attrazione potente."
  },
  AvgDialog_24092_Content_83 = {
    Text = "Impostore... Muori!"
  },
  AvgDialog_24092_Content_84 = {
    Text = "Custode! Non lasciarmi la Mano!"
  },
  AvgDialog_24092_Content_86 = {
    Text = "L'abbraccio del mare si fece tagliente, l'acqua reagì con la tua pelle ustionata in una lotta soffocante.\nCecità caotica, come uno spettro nella notte, lacerò e spezzò il tuo corpo."
  },
  AvgDialog_24092_Content_87 = {
    Text = "Poi, quel caos generò un tremolio di calore. Nell'oscurità sconfinata, solitudine, impotenza e disperazione si ritrassero rapide, un bagliore misterioso che brillava nel cosmo gelido."
  },
  AvgDialog_24092_Content_88 = {
    Text = "Come sfiorato dalla clemenza dell'universo, la tua coscienza vacillò sul confine del Reame spirituale. Il tuo corpo si fuse con l'ossigeno del mare, e spalancasti gli Occhi, sentendo l'acqua irrompere dentro di te."
  },
  AvgDialog_24092_Content_89 = {
    Text = "Infine, una luce gentile squarciò l'oscurità dell'oceano. Una forza azzurra pallida si protese verso di te — una dea dell'Uscita di Sicurezza che ti tendeva la mano."
  },
  AvgDialog_24092_Content_9 = {
    Text = "Lascia stare. Lascia che sia l'ospite a metterti al corrente."
  },
  AvgDialog_24092_Content_90 = {
    Text = "Ora ricordo... L'agonia di Miryam ha innescato l'esplosione. Non sono riuscito ad afferrare la mano di Ramona e sono caduto in mare... ma no, questo è il ponte della Sona-Nyl."
  },
  AvgDialog_24092_Content_91 = {
    Text = "Quella forza finale che mi ha salvato... era Celeste? Mi ha strappato dagli abissi..."
  },
  AvgDialog_24092_Content_92 = {
    Text = "Allora anche gli altri devono stare bene!"
  },
  AvgDialog_24092_Content_93 = {
    Text = "Il calore onirico cedette il passo alla cruda luce lunare, il velo che avvolgeva la nave si frantumò, si dissolse e sprofondò nelle profondità."
  },
  AvgDialog_24092_Content_94 = {
    Text = "Il velo... è scomparso?!"
  },
  AvgDialog_24092_Content_95 = {
    Text = "Dense volute di fumo si levavano dalla poppa — dove si trovava la sala macchine."
  },
  AvgDialog_24092_Content_96 = {Text = "Oh no!"},
  AvgDialog_24092_Content_97 = {
    Text = "Ignorando il dolore lancinante che proveniva dalle profondità della tua anima, ti appoggiasti alla ringhiera, barcollando verso il fumo che si alzava."
  },
  AvgDialog_24092_Content_98 = {
    Text = "La gola era soffocata dal sangue e dalla polvere da sparo, ogni respiro una tortura."
  },
  AvgDialog_24092_Content_99 = {
    Text = "Ramona, Murphy, Celeste, Tulu... devo trovarli in fretta."
  },
  AvgDialog_24093_Content_1 = {
    Text = "Determinazione"
  },
  AvgDialog_24093_Content_10 = {
    Text = "Chi è là—Celeste!!"
  },
  AvgDialog_24093_Content_11 = {
    Text = "Elton fece diversi respiri profondi, voltandosi verso i tre che erano entrati barcollando."
  },
  AvgDialog_24093_Content_12 = {
    Text = "I tentacoli di Tulu sostenevano Ramona, il volto cupo, i muscoli tremanti per lo sforzo."
  },
  AvgDialog_24093_Content_13 = {
    Text = "Quella divisa... sei il partner di %player%."
  },
  AvgDialog_24093_Content_14 = {
    Text = "Ramona scrutò il gruppo. Oltre a Tulu, che aveva conosciuto a scuola, e Celeste, che era fuggita con lei, c'erano due volti sconosciuti."
  },
  AvgDialog_24093_Content_15 = {
    Text = "Erano Murphy e il capitano della Sona-Nyl — coloro che il Custode aveva rischiato tutto per proteggere."
  },
  AvgDialog_24093_Content_16 = {
    Text = [[
Ramona Dexter. Chiamami Ramona.
Salta i convenevoli. Devo sapere tutto quello che succede su questa nave, in breve e in fretta.]]
  },
  AvgDialog_24093_Content_17 = {
    Text = "Chi siete, perché i Navigatori vi danno la caccia, e cos'è questo \"rito\" di cui Miryam è ossessionata..."
  },
  AvgDialog_24093_Content_18 = {
    Text = "Io—io sono..."
  },
  AvgDialog_24093_Content_19 = {
    Text = "Elton interruppe il tentativo affrettato di Murphy di parlare, sapendo che la pressione avrebbe confuso la sua spiegazione."
  },
  AvgDialog_24093_Content_2 = {
    Text = [[
Cargo del Mare Esterno: Sona-Nyl
Terza Stiva]]
  },
  AvgDialog_24093_Content_20 = {
    Text = "Sono Elton, e quella è la mia compagna Celeste, l'unico altro membro dell'equipaggio di questa Sona-Nyl."
  },
  AvgDialog_24093_Content_21 = {
    Text = "In gioventù, Miryam mi aiutò a risvegliare Celeste. In cambio, navigammo con la Sona-Nyl tra i continenti e le regioni polari, trasportando rifornimenti per il culto dei Navigatori."
  },
  AvgDialog_24093_Content_22 = {
    Text = "Alla fine, siamo stati cacciati da Miryam per aver aiutato Murphy a fuggire dal culto."
  },
  AvgDialog_24093_Content_23 = {
    Text = "Murphy porta in sé il falso dio che Miryam intende richiamare. Non so se sia una vera divinità, ma se il rito avrà luogo, Murphy non sopravvivrà."
  },
  AvgDialog_24093_Content_24 = {
    Text = "Murphy condivise frammenti della sua storia — il suo corpo, i suoi legami con Miryam, il suo passato nel culto..."
  },
  AvgDialog_24093_Content_25 = {
    Text = "Sono successe tante cose..."
  },
  AvgDialog_24093_Content_26 = {
    Text = "Farò virare Celeste a tutta velocità verso terra, ma non posso promettere che riusciremo a salvare %player%."
  },
  AvgDialog_24093_Content_27 = {
    Text = "Prima che Elton finisse, tutti barcollarono quando la nave sbandò — Celeste la stava davvero spingendo più veloce."
  },
  AvgDialog_24093_Content_28 = {
    Text = "*Coff, coff...*"
  },
  AvgDialog_24093_Content_29 = {
    Text = "Capitano! Far andare la nave così veloce è troppo per te."
  },
  AvgDialog_24093_Content_3 = {
    Text = "Stivali dalla suola dura battevano ritmicamente sul ponte, ogni passo pesante e sordo."
  },
  AvgDialog_24093_Content_30 = {
    Text = "...Non è nulla."
  },
  AvgDialog_24093_Content_31 = {
    Text = "Ho chiuso un occhio cieco sulla tua sofferenza mentre ero complice del culto. I miei peccati sono già abbastanza gravi."
  },
  AvgDialog_24093_Content_32 = {
    Text = "La mia... sofferenza?"
  },
  AvgDialog_24093_Content_33 = {
    Text = "Sono io che ti ho consegnata a Miryam."
  },
  AvgDialog_24093_Content_34 = {Text = "..."},
  AvgDialog_24093_Content_35 = {
    Text = "Eri il \"carico\" più prezioso che abbia mai trasportato per il culto. Quella navigazione impeccabile mi valse il favore di Miryam."
  },
  AvgDialog_24093_Content_36 = {
    Text = "Ecco perché, alla base del culto, hai accettato di aiutarmi senza esitazione..."
  },
  AvgDialog_24093_Content_37 = {
    Text = "Quando saremo abbastanza vicini alla costa, farò sbarcare Celeste con voi da questa nave. Più vi allontanate dal mare, meglio è."
  },
  AvgDialog_24093_Content_38 = {
    Text = "Come in risposta, Celeste fece ruotare la sua bussola."
  },
  AvgDialog_24093_Content_39 = {
    Text = "Vuoi che Celeste venga con me?"
  },
  AvgDialog_24093_Content_4 = {
    Text = "Celeste, %player%..."
  },
  AvgDialog_24093_Content_40 = {
    Text = "Ramona colse per prima il significato del Capitano."
  },
  AvgDialog_24093_Content_41 = {
    Text = "Il Custode e io possiamo organizzare un trasporto. Se Celeste può estendere il suo Dominio al nostro veicolo..."
  },
  AvgDialog_24093_Content_42 = {
    Text = "Esatto. Vi farà guadagnare abbastanza tempo."
  },
  AvgDialog_24093_Content_43 = {
    Text = "Stai scherzando? Pensi di poter tenere a bada quei mostri? Non sei nemmeno un Navigatore — sei solo un comune essere umano!"
  },
  AvgDialog_24093_Content_44 = {
    Text = "No, lasciate fare a noi."
  },
  AvgDialog_24093_Content_45 = {
    Text = "Fermare rituali pagani, proteggere il mondo dall'ignoto...\nÈ il dovere di tutti all'Università di Mythag."
  },
  AvgDialog_24093_Content_46 = {
    Text = "Siete pazzi anche voi? Non sapete nemmeno se vi stiamo mentendo!"
  },
  AvgDialog_24093_Content_47 = {
    Text = "Il Custode ha scelto di fidarsi di te, quindi mi fiderò anch'io."
  },
  AvgDialog_24093_Content_48 = {
    Text = "Il capitano si riprese, poi allungò la mano verso Murphy—\narruffandole i capelli con gesto rude."
  },
  AvgDialog_24093_Content_49 = {
    Text = "<Small:Ehi! Non strofinare così forte! Mi stai rovinando i capelli!>"
  },
  AvgDialog_24093_Content_5 = {
    Text = "E Tulu... perché non sono ancora tornati?"
  },
  AvgDialog_24093_Content_50 = {
    Text = "Voglio che tu ti liberi da tutto questo. Che sia il mio ultimo desiderio."
  },
  AvgDialog_24093_Content_51 = {
    Text = "Al peggio affondo insieme alla Sona-Nyl. Avrei dovuto colare a picco con lei molto tempo fa."
  },
  AvgDialog_24093_Content_52 = {
    Text = "Murphy si aggrappò al cappotto del Capitano, rifiutando ostinatamente di lasciarlo andare."
  },
  AvgDialog_24093_Content_53 = {
    Text = "Ramona strinse il pugno, poi, con uno sguardo tenace, porse a Murphy un oggetto: un Comunicatore dell'Università di Mythag."
  },
  AvgDialog_24093_Content_54 = {
    Text = "Un... cimelio di famiglia?"
  },
  AvgDialog_24093_Content_55 = {
    Text = "È un Comunicatore. Potrebbe non funzionare in questo Dominio, ma la scuola deve star cercando di contattarci."
  },
  AvgDialog_24093_Content_56 = {
    Text = [[
Se riesci a vedere la Dissoluzione con i tuoi occhi, devi avere abbastanza forza mentale per usarla.
Concentrati quando la spilla si illumina, e ti connetterai con qualcuno dall'altra parte.]]
  },
  AvgDialog_24093_Content_57 = {
    Text = "Anche se il Custode e io non dovessimo tornare, i nostri colleghi ti aiuteranno."
  },
  AvgDialog_24093_Content_58 = {
    Text = "Murphy prese la spilla, fissando le sue intricate filigrane metalliche, gli occhi improvvisamente rossi."
  },
  AvgDialog_24093_Content_59 = {
    Text = "Ma che vi prende... sembra che stiate marciando verso la morte."
  },
  AvgDialog_24093_Content_6 = {
    Text = "Murphy camminava avanti e indietro con ansia, incapace di stare ferma. Prese a calci una cassa, poi tirò le funi che la assicuravano."
  },
  AvgDialog_24093_Content_60 = {
    Text = "Tulu, disinteressata alla discussione, si fermò sulla soglia, percependo il flusso del Potere, pronta a dirigersi verso la sala macchine."
  },
  AvgDialog_24093_Content_61 = {
    Text = "—Aspetta! Dove stai andando!"
  },
  AvgDialog_24093_Content_62 = {
    Text = "La ragazza spalancò la porta, afferrando un Tentacolo."
  },
  AvgDialog_24093_Content_63 = {
    Text = "Hai intenzione di salvare {Male=lui,Female=lei}?"
  },
  AvgDialog_24093_Content_64 = {
    Text = "Le mie azioni non spettano agli estranei metterle in discussione."
  },
  AvgDialog_24093_Content_65 = {
    Text = "Vengo anch'io."
  },
  AvgDialog_24093_Content_66 = {
    Text = "Murphy! Non essere avventato."
  },
  AvgDialog_24093_Content_67 = {
    Text = [[
Tu resta qui. Tulu e io aiuteremo il Custode a fuggire.
Se cadi nelle mani di Miryam, i nostri sforzi saranno stati vani.]]
  },
  AvgDialog_24093_Content_68 = {Text = "Lo so."},
  AvgDialog_24093_Content_69 = {
    Text = [[
Ma... non posso...
Non voglio morire, ma... e se non tornaste?]]
  },
  AvgDialog_24093_Content_7 = {
    Text = "Spero che non siano nei guai..."
  },
  AvgDialog_24093_Content_70 = {
    Text = "Io... non voglio... che accada..."
  },
  AvgDialog_24093_Content_71 = {
    Text = "Non posso restare in questo Dominio per sempre. Se voglio davvero fuggire, io... ho bisogno che voi garantiate per me."
  },
  AvgDialog_24093_Content_72 = {
    Text = "Non posso presentarmi alla vostra scuola e dire al preside che i suoi studenti sono morti per me.\nHo bisogno che mi presentiate voi. A nessuno dei due è permesso morire."
  },
  AvgDialog_24093_Content_73 = {
    Text = "Non sprecherò energie a proteggerti."
  },
  AvgDialog_24093_Content_74 = {
    Text = "Non ho bisogno della vostra protezione. Conosco a memoria le Debolezze dei Navigatori. So cavarmela da sola."
  },
  AvgDialog_24093_Content_75 = {
    Text = "D'accordo, se sei così determinato."
  },
  AvgDialog_24093_Content_76 = {
    Text = "Che sguardo è quello?"
  },
  AvgDialog_24093_Content_77 = {
    Text = [[
Pensavo che non fossi degno del loro sacrificio.
A quanto pare, mi sbagliavo sul tuo conto.]]
  },
  AvgDialog_24093_Content_78 = {
    Text = "Che sono questi enigmi? Muoversi, muoversi!"
  },
  AvgDialog_24093_Content_79 = {
    Text = "Murphy spinse Tulu con una mano, afferrò Ramona con l'altra, e svanirono nei corridoi bui della nave."
  },
  AvgDialog_24093_Content_8 = {
    Text = "Non riusciva a trovare pace, né per pregare né per riposare."
  },
  AvgDialog_24093_Content_80 = {
    Text = "Lei... va bene, se è la sua scelta."
  },
  AvgDialog_24093_Content_81 = {
    Text = "Celeste, mantienici a tutta velocità."
  },
  AvgDialog_24093_Content_9 = {Text = "Bang—!"},
  AvgDialog_24094_Content_1 = {
    Text = "Mentre la mente di Miryam vacillava, la coesione dei Navigatori veniva meno, e il caos si insinuava tra le loro fila."
  },
  AvgDialog_24094_Content_2 = {
    Text = "I Navigatori riconobbero Murphy, il vascello del loro Dio, e si scostarono istintivamente al suo avvicinarsi. Attraversasti le loro fila di corsa."
  },
  AvgDialog_24095_Content_1 = {
    Text = "I tentacoli di Tulu spazzarono via i Navigatori che si avvicinavano, proteggendo le retrovie."
  },
  AvgDialog_24095_Content_2 = {
    Text = "Benché ottusi, i Navigatori si fecero irrequieti.\nSussurri si diffusero tra le loro fila, antichi e oscuri, facendo aggrottare la fronte a Tulu."
  },
  AvgDialog_24095_Content_3 = {
    Text = "La loro diffidenza non farà che infuriare Miryam."
  },
  AvgDialog_24095_Content_4 = {
    Text = "Diffidenza? Capisci le loro parole?"
  },
  AvgDialog_24095_Content_5 = {
    Text = "Non c'era tempo per le spiegazioni di Tulu—Miryam tradusse la loro lingua arcaica con i fatti."
  },
  AvgDialog_24095_Content_6 = {
    Text = "Il suo pugnale squarciò la gola di diversi Navigatori, bagnandola di sangue grigio-azzurro mentre si faceva strada tra il loro assembramento."
  },
  AvgDialog_24095_Content_7 = {
    Text = "Il dio-re rinato? No...\nIl nostro Signore discenderà solo all'allineamento stellare—guidato dal rituale!"
  },
  AvgDialog_24095_Content_8 = {
    Text = "Solo il mio rito può portare il Dio-re, e il Reame Divino! Il MIO rito!"
  },
  AvgDialog_24095_Content_9 = {
    Text = "Navigatori... fate sì che questi blasfemi contemplino la maestà del Reame Divino!"
  },
  AvgDialog_24096_Content_1 = {
    Text = "Luce perduta"
  },
  AvgDialog_24096_Content_10 = {
    Text = "Gli arti contorti, i volti sfigurati cristallizzati nell'istante della morte, il sangue rappreso a formare rune incomprensibili, saturando l'aria con il fervore della morte."
  },
  AvgDialog_24096_Content_11 = {
    Text = "Al tuo \"Dio\" probabilmente non piaceranno offerte così macabre, eh?\nI loro emissari sono scomparsi sotto la nostra sorveglianza. Come lo spiegherai alla Chiesa della luce del tempio?"
  },
  AvgDialog_24096_Content_12 = {
    Text = "Prima che Golia finisse, la cicatrice sul suo collo si contrasse, bloccandogli i muscoli."
  },
  AvgDialog_24096_Content_13 = {
    Text = "Non ho forgiato la tua testa con il sangue di Lemuria perché tu bestemmiassi il mio Dio, Golia."
  },
  AvgDialog_24096_Content_14 = {
    Text = "Il mio grande, onnipotente Signore trae forza dalle mie preghiere e conosce la mia devozione attraverso i miei sacrifici."
  },
  AvgDialog_24096_Content_15 = {
    Text = "Quanto a quegli emissari del Portatore di Luce... feccia maleducata, sciocca e insignificante. Se i Portatori di Luce si lamentano, non avrò più bisogno di camminare al loro fianco."
  },
  AvgDialog_24096_Content_16 = {
    Text = "Miryam si pulì il sangue dalle dita e finalmente si voltò verso di te. Un persistente fetore di decomposizione la avvolgeva, e ogni centimetro in meno di distanza tormentava la tua sanità."
  },
  AvgDialog_24096_Content_17 = {
    Text = "Cosa gli hai... fatto?"
  },
  AvgDialog_24096_Content_18 = {
    Text = "Tu sei diverso da loro."
  },
  AvgDialog_24096_Content_19 = {
    Text = "Miryam ignorò la tua domanda. Ti guardò, i suoi occhi simili a un abisso immobile che custodiva ossa millenarie."
  },
  AvgDialog_24096_Content_2 = {
    Text = [[
Cargo d'alto mare: Sona-Nyl
Sala motori]]
  },
  AvgDialog_24096_Content_20 = {
    Text = "Possiedi l'anima più singolare che abbia visto da quando sono diventata una Risvegliatrice... più luminosa e più oscura di quella del tuo compagno."
  },
  AvgDialog_24096_Content_21 = {
    Text = "Un Custode dell'Università di Mythag... ho a cuore i dotati. Desidererei davvero che tu potessi crogiolarti nella luce divina del Nostro Signore."
  },
  AvgDialog_24096_Content_22 = {
    Text = "Le menti brillanti non dovrebbero essere sepolte nel mondano. Il Reame Divino, tessuto con sangue sacro, accoglie vene straniere."
  },
  AvgDialog_24096_Content_23 = {
    Text = "La tua speranza di salvare il mondo dalla corruzione non è in contrasto con la <Blue:Rinascita dalla Terra del Reame Divino>."
  },
  AvgDialog_24096_Content_24 = {
    Text = "Serviteci, unitevi alla Rinascita dalla Terra e alla Rinascita del Reame Divino, e camminate con me nella beatitudine eterna."
  },
  AvgDialog_24096_Content_25 = {
    Text = "Se la vostra cosiddetta Rinascita dalla Terra e Rinascita significano usare persone vive come sacrifici, trasformare gli innocenti in ricettacoli per i Mostri..."
  },
  AvgDialog_24096_Content_26 = {
    Text = "Mi dispiace, non posso farlo.\nIl tuo rituale è barbaro e crudele. Non vedo traccia di ragione o civiltà in esso."
  },
  AvgDialog_24096_Content_27 = {
    Text = "Essere il ricettacolo per la Rinascita dalla Terra di Dio, la pietra angolare del Ritorno del Reame Divino — questa è la gloria suprema!"
  },
  AvgDialog_24096_Content_28 = {
    Text = "Vi ho giudicato male. Inutile Sprecare parole con gli stolti... questa farsa finisce ora."
  },
  AvgDialog_24096_Content_29 = {
    Text = "Il Potere eruppe dalle ombre, energia informe che si condensò in un immenso serpente solido."
  },
  AvgDialog_24096_Content_3 = {
    Text = "Miryam era in piedi al centro della stanza, gli occhi socchiusi, composta come una statua sacra. Persino quando Golia ti gettò bruscamente ai suoi piedi, si limitò a volgere lo sguardo verso di te."
  },
  AvgDialog_24096_Content_30 = {
    Text = "Il serpente gigante si dibatteva furiosamente, i suoi occhi fissi su di te — si avvolse attorno alla tua vita, sollevandoti senza sforzo in aria."
  },
  AvgDialog_24096_Content_31 = {
    Text = "Fermati, Miryam."
  },
  AvgDialog_24096_Content_32 = {
    Text = "Chi va là!"
  },
  AvgDialog_24096_Content_33 = {
    Text = "Una Voce, dolorosamente familiare, balzò attraverso l'abisso della storia — lieve come una brezza al largo, eppure capace di scatenare un'ondata nel tuo cuore."
  },
  AvgDialog_24096_Content_34 = {
    Text = "Miryam, ho detto, lascia stare quello."
  },
  AvgDialog_24096_Content_35 = {
    Text = "E vero. Questa farsa finisce ora."
  },
  AvgDialog_24096_Content_36 = {
    Text = "Non conosco il tuo volto, ma la tua presenza... porta tracce del Nostro Signore."
  },
  AvgDialog_24096_Content_37 = {
    Text = "Un Tremolio di pietà attraversò il volto di Miryam. I Suoi Occhi, come fiori sferzati da una tempesta improvvisa, traboccavano di infinito Pianto e dolore."
  },
  AvgDialog_24096_Content_38 = {
    Text = "Scaglie fredde e viscide scivolarono sul tuo corpo, il serpente che stringeva come un predatore che strangola la sua preda."
  },
  AvgDialog_24096_Content_39 = {
    Text = "Le lacrime scavarono solchi indelebili sul suo volto. Fissava Tulu, come per Perforare la sua anima, per dipanare la storia condivisa attraverso gli eoni."
  },
  AvgDialog_24096_Content_4 = {
    Text = "Quello sguardo era freddo come quello di una vipera, emanava crudeltà e distacco — non eri né un suo pari né parte della sua catena alimentare."
  },
  AvgDialog_24096_Content_40 = {
    Text = [[
<Blue:Mio Signore>... mio glorioso <Blue:Re>...
Come avete potuto... sopportare la contaminazione di una Risvegliatrice?]]
  },
  AvgDialog_24096_Content_41 = {
    Text = "Chi ha profanato le Vostre sacre reliquie? Chi... ha infranto il nostro Patto?"
  },
  AvgDialog_24096_Content_42 = {
    Text = "Penzolavi a testa in giù nella morsa del serpente, il sangue che affluiva alla testa, la Visuale che svaniva nel nero."
  },
  AvgDialog_24096_Content_43 = {
    Text = "Ma nella tua confusione, intravedesti due ragazze... circondate da Navigatori, che si avvicinavano."
  },
  AvgDialog_24096_Content_44 = {
    Text = "Ramona! Adesso!"
  },
  AvgDialog_24096_Content_45 = {
    Text = "Ramona inspirò profondamente, piegò un ginocchio, incanalò energia sotto i piedi, e spiccò un balzo —"
  },
  AvgDialog_24096_Content_47 = {
    Text = "La punta del suo stocco perforò le scaglie del serpente, colpendone il punto vitale."
  },
  AvgDialog_24096_Content_48 = {
    Text = "Ehi, ehi! {Male=Sta,Female=Sta} per cadere!"
  },
  AvgDialog_24096_Content_49 = {
    Text = "Sei precipitato tra il ruggito del serpente..."
  },
  AvgDialog_24096_Content_5 = {
    Text = "Dove sono gli altri?"
  },
  AvgDialog_24096_Content_50 = {
    Text = "—in un abbraccio tremante e caldo."
  },
  AvgDialog_24096_Content_51 = {
    Text = "...Tutto bene, %player%?"
  },
  AvgDialog_24096_Content_52 = {
    Text = "Ramona... Io..."
  },
  AvgDialog_24096_Content_53 = {
    Text = "Scusa, non è il momento per un ricongiungimento."
  },
  AvgDialog_24096_Content_54 = {
    Text = "Ramona ti tenne stretta, allontanandosi di corsa da Miryam senza voltarsi indietro."
  },
  AvgDialog_24096_Content_55 = {
    Text = "Lanciasti uno sguardo verso Miryam. Il serpente si riformò, Il Suo Sguardo cadde su di te e Ramona."
  },
  AvgDialog_24096_Content_56 = {
    Text = "Uno sguardo predatorio, come una vipera che osserva la sua preda."
  },
  AvgDialog_24096_Content_57 = {
    Text = "Tulu! Non affrontarla. Porta fuori Murphy prima."
  },
  AvgDialog_24096_Content_6 = {
    Text = "Non te l'avevo detto? I topolini di Mythag sono bravi a sgattaiolare. Catturare questo è stato già abbastanza difficile."
  },
  AvgDialog_24096_Content_7 = {
    Text = "Ma gli altri non contano più, vero?\nSembra che tu abbia già costruito l'altare per il tuo \"Dio\"."
  },
  AvgDialog_24096_Content_8 = {
    Text = "Miryam si voltò lentamente, le sue ombre serpentine si dissolsero, avvolgendola in una luminescenza purpurea come una devota battezzata."
  },
  AvgDialog_24096_Content_9 = {
    Text = "L'altare dietro di lei apparve alla vista, la luce fioca della sala motori proiettava ombre sinistre sul suo volto. Al centro giacevano due corpi irriconoscibili."
  },
  AvgDialog_24097_Content_10 = {
    Text = "A proposito, ti fa ancora male la gamba? Non c'è più Salasso."
  },
  AvgDialog_24097_Content_11 = {
    Text = "Lo percepisco a malapena..."
  },
  AvgDialog_24097_Content_12 = {
    Text = "Mentre discutevate dei piani futuri, l'illusione di Miryam si dissolse come neve al sole.\nLa nemica riacquistò un po' di lucidità dalla sua frenesia, abbandonando la forma mostruosa."
  },
  AvgDialog_24097_Content_13 = {
    Text = "Miryam giaceva debole nella polvere nera, il Suo Sguardo vacuo, senza reagire neppure quando Tulu si avvicinò."
  },
  AvgDialog_24097_Content_14 = {
    Text = "Smettila di aggrapparti al delirio, Miryam."
  },
  AvgDialog_24097_Content_15 = {
    Text = "La nostra era, il nostro <Blue:Reame Eterno>, la sua caduta è segnata dal Sigillo."
  },
  AvgDialog_24097_Content_16 = {
    Text = "No... no... Me lo aveva promesso..."
  },
  AvgDialog_24097_Content_17 = {
    Text = "<Yellow:Tu> me lo avevi promesso."
  },
  AvgDialog_24097_Content_18 = {
    Text = "La donna emaciata mostrò finalmente una reazione. Alzò lo sguardo vacuo, mormorando tra sé."
  },
  AvgDialog_24097_Content_19 = {
    Text = "Il mio Dio onnipotente brandirà il Suo Potere... e giudicherà questi indegni eretici che hanno creato questa cosa falsa!"
  },
  AvgDialog_24097_Content_2 = {
    Text = "Queste strutture stanno svanendo. È... finita?"
  },
  AvgDialog_24097_Content_20 = {
    Text = "Estrasse un pugnale dalla cintura: fiamme nero-violacee, dense come nebbia, avvolgevano la lama, irradiando un gelo mortale."
  },
  AvgDialog_24097_Content_21 = {
    Text = "Impostore... Muori!"
  },
  AvgDialog_24097_Content_22 = {
    Text = "—Fiamme fredde e sinistre accesero la polvere di carbone."
  },
  AvgDialog_24097_Content_23 = {
    Text = "<BigShake:Aaahhh!>"
  },
  AvgDialog_24097_Content_24 = {
    Text = "Nella reazione a catena di fuoco e cenere, un'esplosione assordante inghiottì tutti, e la nave sbandò violentemente su un fianco."
  },
  AvgDialog_24097_Content_25 = {
    Text = "Le fiamme si gonfiarono davanti a te, la paratia alle tue spalle squarciata dall'esplosione."
  },
  AvgDialog_24097_Content_26 = {
    Text = "Custode! Non lasciarmi la Mano!"
  },
  AvgDialog_24097_Content_27 = {
    Text = "Le narici ti bruciavano per l'odore acre del carbone combusto. Dopo un fugace istante di connessione, la gravità ti ha trascinato giù nell'abisso."
  },
  AvgDialog_24097_Content_28 = {
    Text = "La voce familiare e il calore svanirono rapidamente, rimpiazzati da un freddo strisciante e un'umidità che artigliavano la spina dorsale."
  },
  AvgDialog_24097_Content_29 = {Text = "Custode!"},
  AvgDialog_24097_Content_3 = {
    Text = "Questa è l'illusione creata da Miryam, forse il suo cosiddetto <Blue:Reame Divino>..."
  },
  AvgDialog_24097_Content_30 = {
    Text = "Il tempo si cristallizzò in quell'istante. Il calore bruciante ti lacerava la pelle come mille lame, ogni tendine arso e fragile come ali di cicala."
  },
  AvgDialog_24097_Content_31 = {
    Text = "Un corno caotico e assordante squarciò il tuo Reame dello Spirito, frantumando la ragione e la pace che avevi conosciuto nell'ultimo anno. In quell'istante infinito, percepisti l'inquietudine e il tormento del caos."
  },
  AvgDialog_24097_Content_32 = {
    Text = "Ma alla fine, tutto fu divorato dalle fiamme, e la tua coscienza svanì in un'oscurità sconfinata..."
  },
  AvgDialog_24097_Content_4 = {
    Text = "Il Regno divino, l'eterna Lemuria."
  },
  AvgDialog_24097_Content_5 = {
    Text = "\"Lemuria\"... ricordo che alcuni storici dei Mythag ne dibattevano l'esistenza."
  },
  AvgDialog_24097_Content_6 = {
    Text = "Se la catastrofe non l'avesse colpita, sorgerebbe là dove..."
  },
  AvgDialog_24097_Content_7 = {
    Text = "Dato che è tutta storia, possiamo parlare di questa città dopo che saremo al sicuro? Occupiamoci prima di questa cosa."
  },
  AvgDialog_24097_Content_8 = {
    Text = [[
Ramona, una volta a terra, lasceremo il Dominio e contatteremo la scuola.
Tulu, resta sulla nave e prenditi cura di Murphy per un po'.]]
  },
  AvgDialog_24097_Content_9 = {
    Text = "Giusto, dovremo preparare un tavolo operatorio con la runa del tempo. L'estrazione della Specie Parassita potrebbe richiedere la Preside Vicaria Czort in persona."
  },
  AvgDialog_24260_Content_1 = {
    Text = "Si sta riprendendo di nuovo...? I nostri attacchi non hanno avuto effetto?"
  },
  AvgDialog_24260_Content_2 = {
    Text = "No... guarda quei due serpenti di energia. Sono densi dell'essenza di Miryam. Potremmo doverli abbattere prima..."
  },
  AvgDialog_24260_Content_3 = {
    Text = "Quando il Reame Divino era ancora in piedi, poteva evocare soltanto un'ombra di serpente. Dopo millenni di Dormienza, ora potrebbe comandare fino a <Yellow:otto> ombre vassalle."
  },
  AvgDialog_24260_Content_4 = {
    Text = "I riti segreti di Lemuria... non possiamo lasciare che la rabbia la consumi. Se perde completamente il controllo, diventerà un vero Mostro."
  },
  AvgDialog_24261_Content_1 = {
    Text = "Abbiamo abbattuto tutte le sue ombre, ma perché lei è ancora...!"
  },
  AvgDialog_24261_Content_2 = {
    Text = "Sta forzando il Rito, ma questa è solo la sua Illusione... senza la guida delle Stelle, non farà che bruciare le anime di Tutti."
  },
  AvgDialog_24261_Content_3 = {
    Text = "Alta Sacerdotessa Miryam! In nome dell'Inviato di @2, ti ordino di fermarti!"
  },
  AvgDialog_24261_Content_4 = {
    Text = "La mente divorata dalla furia, la creatura un tempo chiamata Miryam si arrestò solo un istante prima di riprendere il suo Assalto frenetico."
  },
  AvgDialog_24261_Content_5 = {
    Text = "Pensa che io sia un impostore... e così sia. L'affronterò alla maniera di Lemuria — sottometterla, o... ucciderla."
  },
  AvgDialog_24261_Content_6 = {
    Text = "Miryam... la mia vassalla più leale...\nPossa tu... non vagare più."
  },
  AvgDialog_24282_Content_1 = {
    Text = "Ora, test dello scuotimento schermo 2"
  },
  AvgDialog_24282_Content_2 = {
    Text = "In teoria, l'illustrazione del personaggio dovrebbe scuotersi insieme allo sfondo."
  },
  AvgDialog_24282_Content_3 = {
    Text = "Ora, test del movimento laterale 2"
  },
  AvgDialog_24282_Content_4 = {
    Text = "In teoria, l'illustrazione del personaggio dovrebbe muoversi insieme allo sfondo."
  },
  AvgDialog_24282_Content_5 = {
    Text = "Test completato"
  },
  AvgDialog_24296_Content_1 = {
    Text = "No, sono troppi... Le cose non faranno che peggiorare..."
  },
  AvgDialog_24296_Content_10 = {
    Text = "No, Lord Golia—!!"
  },
  AvgDialog_24296_Content_11 = {
    Text = "Sembra come se tutto davanti ai miei occhi fosse stato messo in pausa."
  },
  AvgDialog_24296_Content_12 = {
    Text = "L'istinto del tuo corpo prende il sopravvento. Si lancia in avanti, facendo disperatamente scudo a Golia."
  },
  AvgDialog_24296_Content_13 = {Text = "Huhhh—"},
  AvgDialog_24296_Content_14 = {
    Text = "Una lama ti squarcia la gola. Tremi mentre stringi la ferita sanguinante, la mente nel caos."
  },
  AvgDialog_24296_Content_15 = {
    Text = "Sei impazzita? Che ci fai qui?!"
  },
  AvgDialog_24296_Content_16 = {
    Text = "Non lo so... Il mio corpo si è mosso da solo..."
  },
  AvgDialog_24296_Content_17 = {
    Text = "Perdonatemi, Lord Golia..."
  },
  AvgDialog_24296_Content_2 = {
    Text = "Io... posso ancora... uccidere!"
  },
  AvgDialog_24296_Content_20 = {
    Text = "Una freccia avvelenata sibilò nell'aria, colpendo Golia alla spalla e facendolo cadere verso di te."
  },
  AvgDialog_24296_Content_21 = {
    Text = "Golia... Il gigante Golia è finalmente caduto!"
  },
  AvgDialog_24296_Content_22 = {
    Text = "La sua testa è mia! Nessuno me la porterà via!!!"
  },
  AvgDialog_24296_Content_23 = {
    Text = "Il mare emise un tremito profondo e furioso. Il gigante oscurò il sole ardente prima di crollare."
  },
  AvgDialog_24296_Content_24 = {
    Text = "Il vostro sangue confluisce, tingendo di cremisi il mare azzurro."
  },
  AvgDialog_24296_Content_25 = {
    Text = "Senti il vento, le onde, e in lontananza grida e scontri. Davanti a te non c'è altro che massacro e umiliazione senza fine."
  },
  AvgDialog_24296_Content_26 = {
    Text = "L'acqua salata del mare brucia la ferita sul tuo collo, facendoti sussultare dal dolore."
  },
  AvgDialog_24296_Content_27 = {
    Text = "Golia non sta molto meglio di te."
  },
  AvgDialog_24296_Content_28 = {
    Text = "Vedendoti in uno stato così pietoso, riesce comunque a rivolgerti un ghigno maligno."
  },
  AvgDialog_24296_Content_29 = {
    Text = "Direi... che dovresti davvero guardarti allo specchio e vedere quanto sei ridicolo in questo momento."
  },
  AvgDialog_24296_Content_3 = {
    Text = "Il suono cupo dei corni riecheggiò sul mare. Attirati da generose ricompense, i guerrieri accorsero in massa per unirsi alla caccia."
  },
  AvgDialog_24296_Content_30 = {
    Text = "Come previsto, sei un buono a nulla."
  },
  AvgDialog_24296_Content_4 = {
    Text = "Golia era vicino al limite. Brandì la sua lama gigantesca ancora una volta, ma nel suo movimento rallentato, qualcuno colse la Fessura."
  },
  AvgDialog_24296_Content_6 = {
    Text = "Cadde in ginocchio, la ferita che esponeva ossa bianche come il gesso, il sangue che scorreva come un fiume senza fine."
  },
  AvgDialog_24296_Content_8 = {
    Text = "Ora è il momento! Finiamolo in un colpo solo!!"
  },
  AvgDialog_24296_Content_9 = {
    Text = "I guerrieri che vi circondano sciamano come squali assetati di sangue."
  },
  AvgDialog_24297_Content_1 = {Text = "Mmph—!!"},
  AvgDialog_24297_Content_10 = {
    Text = "Dove c'è grande ricompensa, uomini coraggiosi non tarderanno a farsi avanti. I guerrieri lanciarono grida eccitate, le loro armi cozzarono tra loro risuonando con il fragore esaltante della battaglia."
  },
  AvgDialog_24297_Content_11 = {
    Text = "Già, di cosa dovremmo aver paura? Siamo in tanti!"
  },
  AvgDialog_24297_Content_12 = {
    Text = "Tagliategli prima la mano che impugna la lama!"
  },
  AvgDialog_24297_Content_13 = {
    Text = "I guerrieri che prima si rannicchiavano ruggirono e si lanciarono in avanti come locuste assetate di sangue."
  },
  AvgDialog_24297_Content_14 = {
    Text = "Heh... miei carissimi fratelli. Vi ho insegnato io a combattere, a uccidere e a sopravvivere."
  },
  AvgDialog_24297_Content_15 = {
    Text = "Ma non vi ho mai insegnato come fuggire di fronte a un nemico molto più forte di voi."
  },
  AvgDialog_24297_Content_16 = {
    Text = "Golia leccò il sangue dall'angolo della bocca, mostrando le zanne."
  },
  AvgDialog_24297_Content_17 = {
    Text = "...perché non avete più nessun posto dove fuggire."
  },
  AvgDialog_24297_Content_18 = {
    Text = "Detto ciò, afferrò con noncuranza le loro gole, sollevò le loro teste e le fracassò l'una contro l'altra—"
  },
  AvgDialog_24297_Content_19 = {Text = "BANG!!"},
  AvgDialog_24297_Content_2 = {
    Text = "Una mannaia impazzita fece a pezzi la nave, costringendo Glen a ritirarsi con una sola gamba rimasta."
  },
  AvgDialog_24297_Content_20 = {
    Text = "Fluidi gialli e bianchi mescolati a sangue frammentato schizzarono ovunque. Golia rise di gusto, le pupille ardenti di una ferocia sanguinaria."
  },
  AvgDialog_24297_Content_21 = {
    Text = "Hahaha! Ho sentito che qualcuno vuole prendersi la mia testa?"
  },
  AvgDialog_24297_Content_22 = {
    Text = "Se avete il fegato, mettetevi in fila e venite a prendervela uno alla volta!"
  },
  AvgDialog_24297_Content_3 = {
    Text = "<Shake:Non eri ferito? Come hai potuto...>"
  },
  AvgDialog_24297_Content_4 = {
    Text = "Scusa, per occuparmi di un lacchè come te non serve tutta la mia forza."
  },
  AvgDialog_24297_Content_5 = {
    Text = "Golia si erge fiero a prua, la sua lama massiccia traccia un arco davanti a sé, tenendo a bada i suoi ex compagni."
  },
  AvgDialog_24297_Content_6 = {
    Text = "C'è qualcun altro che vuole farsi avanti e giocare con me? Uno solo non mi basta per ammazzare!"
  },
  AvgDialog_24297_Content_7 = {
    Text = "Intimiditi dal terrore del gigante, i guerrieri si rannicchiarono come cuccioli, nessuno osava avventurarsi nella curva proibita davanti a loro, come se fosse un luogo tabù."
  },
  AvgDialog_24297_Content_8 = {
    Text = "Un branco di buoni a nulla! Con ferite così gravi, non è più il dominatore incontrastato dei mari di un tempo."
  },
  AvgDialog_24297_Content_9 = {
    Text = "Io, il guerriero Glen, giuro sulla mia vita: chiunque mi porti questa testa avrà le mie ricchezze, le mie terre e le mie donne!"
  },
  AvgDialog_24415_Content_1 = {
    Text = "Aspetta, Ramona!"
  },
  AvgDialog_24415_Content_10 = {
    Text = "Signorina Ramona!"
  },
  AvgDialog_24415_Content_11 = {
    Text = "Dalla tua posizione, vedi Ramona inclinare la testa e sussurrare qualcosa. Ogier impallidisce, sostenendo Doll mentre indietreggia di due passi."
  },
  AvgDialog_24415_Content_12 = {
    Text = "Ramona scuote la melma nera dalla spada e si dirige verso la torre dell'orologio, con un'espressione indecifrabile."
  },
  AvgDialog_24415_Content_13 = {
    Text = "Ramona, aspetta!"
  },
  AvgDialog_24415_Content_14 = {
    Text = "Questo non è un ricordo."
  },
  AvgDialog_24415_Content_15 = {
    Text = "Questa non è nemmeno la Ramona che conosci."
  },
  AvgDialog_24415_Content_16 = {
    Text = "Fredda, spietata e terrificante: la tua compagna non è mai stata così."
  },
  AvgDialog_24415_Content_17 = {
    Text = "Non avrebbe mai scavalcato i corpi dei suoi compagni, non avrebbe mai inferto il colpo mortale a Lotan, e non avrebbe mai... ignorato la tua chiamata."
  },
  AvgDialog_24415_Content_18 = {
    Text = "Ramona! Ramona!"
  },
  AvgDialog_24415_Content_19 = {
    Text = "La sua figura svanisce in lontananza. Non hai altra scelta che correrle dietro."
  },
  AvgDialog_24415_Content_3 = {
    Text = "Nella piazza della scuola, un Lotan impazzito sta facendo una strage. Ogier fatica a proteggere Doll, le sue forze si esauriscono rapidamente."
  },
  AvgDialog_24415_Content_4 = {
    Text = "Prima che tu possa raggiungerla, Ramona alza lo stocco e lo affonda senza pietà verso il volto di Lotan."
  },
  AvgDialog_24415_Content_5 = {
    Text = "Ramona, attenta—!"
  },
  AvgDialog_24415_Content_6 = {
    Text = "Mentre lo stocco si avvicina alla fronte di Lotan, un vuoto si apre sulla punta della lama. L'espressione feroce di Lotan si spegne per un istante."
  },
  AvgDialog_24415_Content_7 = {
    Text = "Un lampo d'acciaio segue. Il Nucleo d'Argento di Lotan si frantuma."
  },
  AvgDialog_24415_Content_8 = {
    Text = "Questo... non può... essere..."
  },
  AvgDialog_24415_Content_9 = {
    Text = "Ramona ritrae la lama senza pietà. La punta affilata traccia un arco agghiacciante che sfiora quasi Ogier."
  },
  AvgDialog_24422_Content_1 = {
    Text = "<Gray:La studentessa deceduta, il cimitero della scuola... questo dev'essere il ricordo di Ramona della Cerimonia.>"
  },
  AvgDialog_24422_Content_2 = {
    Text = "<Gray:Ma ricordo... a quel tempo...>"
  },
  AvgDialog_24422_Content_3 = {
    Text = "Grazie, Custode. Mi hai salvata di nuovo. Se non fosse per questo Legame, ora sarei in punto di morte."
  },
  AvgDialog_24422_Content_4 = {
    Text = "Indugiare è pericoloso. Dobbiamo finire in fretta."
  },
  AvgDialog_24422_Content_5 = {
    Text = "Uff. Mi dispiace, non c'è tempo perché tu possa abituarti a tutto questo come si deve."
  },
  AvgDialog_24422_Content_6 = {
    Text = "<Gray:Di chi è questo ricordo? Quella versione di Ramona... cosa è...?>"
  },
  AvgDialog_24422_Content_7 = {
    Text = "<Gray:Non c'è tempo. Devo raggiungerla.>"
  },
  AvgDialog_25177_Content_1 = {
    Text = "Tawil si è ripreso?! Come?"
  },
  AvgDialog_25177_Content_2 = {
    Text = "Nei miei ricordi di questo scontro, non ha mai mostrato una simile capacità."
  },
  AvgDialog_25177_Content_3 = {
    Text = "No... infatti."
  },
  AvgDialog_25177_Content_4 = {
    Text = "O meglio, non è mai esistita."
  },
  AvgDialog_25177_Content_5 = {
    Text = "Ramona abbassa lo sguardo sulla Chiave d'Argento sul tuo petto e mormora."
  },
  AvgDialog_25177_Content_6 = {
    Text = "L'unica variabile... alla fine si rivela essere..."
  },
  AvgDialog_25177_Content_7 = {
    Text = "Ramona maschera il suo sgomento e punta nuovamente la spada contro Tawil."
  },
  AvgDialog_25177_Content_8 = {
    Text = "Continua con i tuoi comandi. Metti fine a tutto questo... Custode."
  },
  AvgDialog_25186_Content_1 = {Text = "Pifferaio"},
  AvgDialog_25186_Content_10 = {
    Text = "Non abbiate paura. Troverò un modo per farvi uscire di qui."
  },
  AvgDialog_25186_Content_11 = {
    Text = "Gli abitanti del villaggio ricambiano lo sguardo in silenzio. Non c'è speranza nei loro occhi—ma nemmeno ostilità."
  },
  AvgDialog_25186_Content_12 = {
    Text = "Aspettate, l'ancella..."
  },
  AvgDialog_25186_Content_13 = {
    Text = "Mio padre e mio fratello sono rinchiusi Sotto. Devo salvarli—"
  },
  AvgDialog_25186_Content_14 = {
    Text = "Qualcuno di voi conosce un'ancella di nome Susanna?"
  },
  AvgDialog_25186_Content_15 = {
    Text = "Susanna? È la mia sorella maggiore!"
  },
  AvgDialog_25186_Content_16 = {
    Text = "Una voce limpida di bambino si leva dall'angolo."
  },
  AvgDialog_25186_Content_17 = {
    Text = "Alla luce tremolante di un'unica candela, noti un vecchio disteso nell'ombra con un ragazzo dagli occhi spalancati rannicchiato accanto a lui."
  },
  AvgDialog_25186_Content_18 = {
    Text = "Susanna è mia figlia... Le è successo qualcosa?"
  },
  AvgDialog_25186_Content_19 = {
    Text = "È profondamente preoccupata per voi. Stava cercando un modo per salvarvi."
  },
  AvgDialog_25186_Content_2 = {
    Text = [[
Castello Cambrian
Prigione Sotterranea]]
  },
  AvgDialog_25186_Content_20 = {
    Text = "Non possiamo lasciare questo posto..."
  },
  AvgDialog_25186_Content_21 = {
    Text = "Il corpo del vecchio è crivellato di cavità della Dissoluzione. L'icore nero che trasuda dalle sue ferite ha ormai macchiato da tempo la paglia sotto di lui."
  },
  AvgDialog_25186_Content_22 = {
    Text = "Siamo rimasti qui di nostra spontanea volontà. Una volta che il morbo ti prende, perdi la ragione... ti trasformi in un mostro."
  },
  AvgDialog_25186_Content_23 = {
    Text = "È vero. C'erano stati così tanti omicidi nei dintorni... Poi la Signora è passata casa per casa. Ha radunato i malati e li ha portati qui."
  },
  AvgDialog_25186_Content_24 = {
    Text = "Se qualcuno non voleva essere messo in quarantena, lo lasciava andare via dal feudo—a patto che giurasse di non tornare mai più."
  },
  AvgDialog_25186_Content_25 = {
    Text = "Ma qui riceviamo porridge e pane dolce ogni giorno!"
  },
  AvgDialog_25186_Content_26 = {
    Text = "<Gray:Capisco. L'abbiamo completamente fraintesa?>"
  },
  AvgDialog_25186_Content_27 = {
    Text = "Lady Wanda vi ha trattato bene da quando ha preso il controllo del feudo?"
  },
  AvgDialog_25186_Content_28 = {
    Text = "Bene? Non saprei. Non l'ho mai vista di persona. Ho solo sentito le storie—che è crudele, che ha ucciso i suoi quattro mariti, che è un diavolo in carne e ossa."
  },
  AvgDialog_25186_Content_29 = {
    Text = "Ma da quando è qui, ha fatto molto del bene. La vita è molto migliore di prima."
  },
  AvgDialog_25186_Content_3 = {
    Text = "La pesante porta di ferro si chiude con fragore alle tue spalle."
  },
  AvgDialog_25186_Content_30 = {
    Text = "Ci ha insegnato a coltivare come si deve e a pascolare le pecore. A ogni festa, porta la lana al mercato di <Blue:Charich> di persona. Frutta un bel po' di monete."
  },
  AvgDialog_25186_Content_31 = {
    Text = "Esatto, il Mercato di Charich le è stato strappato dal Conte Goodrich. Si contendono quel posto da quasi un anno..."
  },
  AvgDialog_25186_Content_32 = {
    Text = "Gli abitanti del villaggio cominciano tutti a parlare contemporaneamente, condividendo storie sulla gestione di Wanda: agricoltura, fonderia, allevamento, leggi del feudo..."
  },
  AvgDialog_25186_Content_33 = {
    Text = "Resti stupito da quanto profondamente Wanda sia coinvolta in ogni aspetto del feudo. Non è certo una nobile oziosa e dedita ai piaceri."
  },
  AvgDialog_25186_Content_34 = {
    Text = "È una buona governante. È solo una tragedia che la Dissoluzione l'abbia colpita."
  },
  AvgDialog_25186_Content_35 = {
    Text = "<Gray:Una Propagazione di queste dimensioni... dev'esserci una D-fessura nelle vicinanze.>"
  },
  AvgDialog_25186_Content_36 = {
    Text = "La porta di ferro alle vostre spalle si apre cigolando all'improvviso."
  },
  AvgDialog_25186_Content_37 = {
    Text = "Wanda è in piedi all'ingresso, la candela nella sua mano avvolge la sua silhouette in un caldo bagliore arancione."
  },
  AvgDialog_25186_Content_38 = {
    Text = "Lasciate uscire questo. Devo dirgli qualcosa in privato."
  },
  AvgDialog_25186_Content_39 = {
    Text = [[
Castello di Cambrian
Giardino]]
  },
  AvgDialog_25186_Content_4 = {
    Text = "Ti volti e ti ritrovi circondato da coppie di occhi luminescenti, che ti osservano come predatori nell'oscurità."
  },
  AvgDialog_25186_Content_40 = {
    Text = "Camminate insieme sull'erba soffice fino a raggiungere la riva del lago."
  },
  AvgDialog_25186_Content_41 = {
    Text = "A mezzanotte, il lago è uno specchio oscuro, che riflette i frammenti infranti della luna lassù."
  },
  AvgDialog_25186_Content_42 = {
    Text = "Credo che ormai tu l'abbia capito: Cambrian sta affrontando una catastrofe, e io sono impotente a fermarla."
  },
  AvgDialog_25186_Content_43 = {
    Text = "Ma tu... quando hai combattuto quei mostri nel castello, li hai affrontati come un veterano navigato."
  },
  AvgDialog_25186_Content_44 = {
    Text = "<Gray:È il mio mestiere, dopotutto...>"
  },
  AvgDialog_25186_Content_45 = {
    Text = "Non eravate nelle vostre stanze in quel momento, Mia Signora? Come fate a sapere così tanto di quello scontro?"
  },
  AvgDialog_25186_Content_46 = {
    Text = "Ho occhi e orecchie ovunque a Cambrian. Se una singola fresia vuole sbocciare, ha bisogno prima del mio permesso. Non c'è nulla che io non sappia."
  },
  AvgDialog_25186_Content_47 = {
    Text = "E quella ancella? Se sapevate che era una spia, perché tenerla al vostro fianco?"
  },
  AvgDialog_25186_Content_48 = {
    Text = "Wanda agita una mano con noncuranza."
  },
  AvgDialog_25186_Content_49 = {
    Text = "È solo una povera, comune mortale. Non potrebbe torcermi un capello nemmeno volendo."
  },
  AvgDialog_25186_Content_5 = {
    Text = "<Shake:Woaaahhh!!>"
  },
  AvgDialog_25186_Content_50 = {
    Text = "E poi è una serva competente. Trovare un essere umano che faccia davvero ciò che gli si dice non è impresa da poco."
  },
  AvgDialog_25186_Content_51 = {
    Text = "In breve, ho bisogno che tu ponga fine a questa Dissoluzione. Non affrettarti a rifiutare — il prezzo lo discuteremo dopo. Ti darò qualunque cosa tu desideri."
  },
  AvgDialog_25186_Content_52 = {
    Text = "Non lasceresti certo morire questi abitanti del villaggio di una morte così insensata, vero... mio caro \"monaco\"?"
  },
  AvgDialog_25186_Content_53 = {Text = "..."},
  AvgDialog_25186_Content_54 = {
    Text = "Continui a dire \"voi umani\", e poi ci sono quegli strani spuntoni d'osso... Lady Wanda, voi non siete affatto umana, vero?"
  },
  AvgDialog_25186_Content_55 = {
    Text = "Un essere proveniente da un mondo lontano che si preoccupa delle vite di comuni contadini. Cosa cercate davvero?"
  },
  AvgDialog_25186_Content_56 = {
    Text = "Di fronte al tuo interrogatorio, Wanda inarca un sopracciglio e scoppia improvvisamente a ridere."
  },
  AvgDialog_25186_Content_57 = {
    Text = "Ho forse detto qualcosa di divertente?"
  },
  AvgDialog_25186_Content_58 = {
    Text = "No... Ahahah! Sono semplicemente così felice. In tutti gli anni che ho trascorso qui, ho finalmente incontrato qualcun altro che non appartiene a \"questo luogo\"—proprio come me."
  },
  AvgDialog_25186_Content_59 = {
    Text = "Come avete—"
  },
  AvgDialog_25186_Content_6 = {
    Text = "Mentre la tua visuale si adatta alla penombra, finalmente scorgi la realtà della cella."
  },
  AvgDialog_25186_Content_60 = {
    Text = "Wanda posa delicatamente un dito sottile sulle tue labbra."
  },
  AvgDialog_25186_Content_61 = {
    Text = "Shh... Seguitemi. Voglio mostrarvi una cosa."
  },
  AvgDialog_25186_Content_62 = {
    Text = "Ti fai strada attraverso il bosco fino alla riva tranquilla del lago."
  },
  AvgDialog_25186_Content_63 = {
    Text = "A volte, ho queste meravigliose illusioni... come se potessi vedere la mia antica città riflessa nelle profondità di quest'acqua."
  },
  AvgDialog_25186_Content_64 = {
    Text = "Un'immensa città fatta di monoliti neri. I suoi confini erano in costante espansione, protesi verso un orizzonte invisibile..."
  },
  AvgDialog_25186_Content_65 = {
    Text = "Il lago blu profondo è quasi scrutabile. Mentre ascolti la sua descrizione, la sagoma aliena di quella città comincia a prendere forma nella tua mente."
  },
  AvgDialog_25186_Content_66 = {
    Text = "Guglie a spirale nere, strani muri ottusi..."
  },
  AvgDialog_25186_Content_67 = {
    Text = "A quei tempi, avevo un palazzo grandioso. Oltre un migliaio di servitori provvedevano a ogni mio bisogno."
  },
  AvgDialog_25186_Content_68 = {
    Text = "Proprio come hai detto, non mi è mai importato se quei servitori vivessero o morissero."
  },
  AvgDialog_25186_Content_69 = {
    Text = "Ho fatto esattamente ciò che volevo. I miei servitori, la mia città... non erano che manifestazioni della mia volontà e della mia ambizione."
  },
  AvgDialog_25186_Content_7 = {
    Text = "Seduti, distesi o appoggiati alle fredde pareti di pietra—la stanza è stipata di abitanti del villaggio laceri e cenciosi."
  },
  AvgDialog_25186_Content_70 = {
    Text = "Poi, il mio pianeta fu colpito dalla catastrofe che voi chiamate \"Dissoluzione\". Morirono tutti."
  },
  AvgDialog_25186_Content_71 = {
    Text = "Rimasi seduta sola in quella sala per molto, molto tempo, osservando il mio palazzo e la mia capitale ridursi in cenere."
  },
  AvgDialog_25186_Content_72 = {
    Text = "A dire il vero, fu una sensazione terribile. Nessuno vorrebbe viverla due volte."
  },
  AvgDialog_25186_Content_73 = {
    Text = "Lady Wanda... Mi dispiace, ma non posso aiutarvi."
  },
  AvgDialog_25186_Content_74 = {
    Text = "Non preoccuparti di questo. Dimmi cosa ti trattiene, e ti fornirò tutto ciò di cui hai bisogno."
  },
  AvgDialog_25186_Content_75 = {
    Text = "Scuoti la testa."
  },
  AvgDialog_25186_Content_76 = {
    Text = "Non è solo questo. Il nostro ambiente attuale... presenta alcune... peculiarità."
  },
  AvgDialog_25186_Content_77 = {
    Text = "Non puoi chiudere una D-fessura mentre ti trovi in uno stato onirico."
  },
  AvgDialog_25186_Content_78 = {
    Text = "<Gray:Come faccio anche solo a spiegarglielo?>"
  },
  AvgDialog_25186_Content_79 = {
    Text = "Poiché siamo in un sogno, non puoi aiutarmi... è così?"
  },
  AvgDialog_25186_Content_8 = {
    Text = "La loro pelle è costellata di cicatrici della Dissoluzione; alcuni hanno già perso metà del corpo a causa della putrefazione. L'aria è satura del fetore di malattia e di morte imminente."
  },
  AvgDialog_25186_Content_80 = {Text = "?!"},
  AvgDialog_25186_Content_81 = {
    Text = "Voi... ve ne siete accorto?"
  },
  AvgDialog_25186_Content_82 = {
    Text = "Wanda contempla la città nera nell'acqua, i suoi occhi scintillanti di frammentato chiaro di luna bianco."
  },
  AvgDialog_25186_Content_83 = {
    Text = "Da quando sono giunto qui, ho fatto molti sogni. Sulla guerra, sulle catastrofi, sul tempo... ma mai una volta sulla mia capitale."
  },
  AvgDialog_25186_Content_84 = {
    Text = "Proprio quando stavo per dimenticarlo, ho incontrato te, e poi l'ho rivisto sul fondo del lago."
  },
  AvgDialog_25186_Content_85 = {
    Text = "Lo sapevi? Quando un uomo morente vede il Pifferaio muoversi nella nebbia, non prova né terrore né curiosità."
  },
  AvgDialog_25186_Content_86 = {
    Text = "Semplicemente segue il Pifferaio in silenzio, dirigendosi verso un luogo tutto suo."
  },
  AvgDialog_25186_Content_87 = {
    Text = "Wanda lascia sfuggire un lieve sospiro."
  },
  AvgDialog_25186_Content_88 = {
    Text = "La mia capitale perduta... è bellissima, come il sogno di un uomo morente."
  },
  AvgDialog_25186_Content_89 = {
    Text = "Accarezza dolcemente l'attendente silenzioso e cieco al suo fianco."
  },
  AvgDialog_25186_Content_9 = {
    Text = "Wanda vi ha davvero rinchiusi tutti qui dentro..."
  },
  AvgDialog_25186_Content_90 = {
    Text = "<Change>Mia Signora..."
  },
  AvgDialog_25186_Content_91 = {
    Text = "Cambrian è il mio secondo focolare. Non ho trascorso molto tempo qui, eppure è già ora di dire addio."
  },
  AvgDialog_25186_Content_92 = {
    Text = "Mi dispiace, Lady Wanda..."
  },
  AvgDialog_25186_Content_93 = {
    Text = "Wanda agita una mano con noncuranza. Quando alza di nuovo lo sguardo, la malinconia è svanita dal suo volto."
  },
  AvgDialog_25186_Content_94 = {
    Text = "Non preoccuparti. Dal momento che ho scelto di essere la signora di questo feudo, devo assumermi la responsabilità per tutti."
  },
  AvgDialog_25186_Content_95 = {
    Text = "Non si tratta forse di morire insieme? Allora moriamo gloriosamente."
  },
  AvgDialog_25186_Content_96 = {
    Text = "Cosa avete intenzione di fare?"
  },
  AvgDialog_25186_Content_97 = {
    Text = "Wanda offre un sorriso enigmatico e vi fa l'occhiolino."
  },
  AvgDialog_25186_Content_98 = {
    Text = "Un magnifico banchetto d'addio."
  },
  AvgDialog_25187_Content_1 = {
    Text = "Quattro Matrimoni"
  },
  AvgDialog_25187_Content_10 = {
    Text = "Segui l'ancella, mentre il profumo pesante e stucchevole della cipria ti si aggrappa alla pelle."
  },
  AvgDialog_25187_Content_11 = {
    Text = "Questa è una classica fortezza del vecchio mondo, le sue mura erette con massicci blocchi di pietra per resistere a qualsiasi assedio."
  },
  AvgDialog_25187_Content_12 = {
    Text = "Sembra piena di spifferi. Dev'essere gelida d'inverno."
  },
  AvgDialog_25187_Content_13 = {
    Text = "Aspetta, cos'è quello...?"
  },
  AvgDialog_25187_Content_14 = {
    Text = "Un fango nero e corrosivo inizia a trasudare dalle crepe della muratura."
  },
  AvgDialog_25187_Content_15 = {
    Text = "Il liquido si raccoglie silenziosamente sul pavimento, pulsando mentre si intreccia in una forma fisica."
  },
  AvgDialog_25187_Content_16 = {Text = "Roar—!!"},
  AvgDialog_25187_Content_17 = {
    Text = "<Shake:Lo senti? Qualcosa è vicino...>"
  },
  AvgDialog_25187_Content_18 = {
    Text = "Sono qui... i mostri sono tornati!"
  },
  AvgDialog_25187_Content_19 = {
    Text = "Resta dietro di me."
  },
  AvgDialog_25187_Content_2 = {Text = "Splash—"},
  AvgDialog_25187_Content_20 = {
    Text = "Ma non sei forse un—"
  },
  AvgDialog_25187_Content_21 = {
    Text = "La cameriera fissa incredula le pesanti catene che vi legano polsi e caviglie."
  },
  AvgDialog_25187_Content_22 = {
    Text = "Chiudete gli occhi, immergendovi nelle profondità della vostra coscienza per afferrare i deboli legami con gli altri Risvegliatori."
  },
  AvgDialog_25187_Content_23 = {
    Text = "Sebbene il vostro potere sia soffocato dallo spirito fragile del monaco in questo sogno, e i vostri richiami siano indeboliti, eppure—"
  },
  AvgDialog_25187_Content_24 = {
    Text = "È più che sufficiente per occuparsi di quelli come voi."
  },
  AvgDialog_25187_Content_3 = {
    Text = "Un secchio d'acqua gelida ti viene rovesciato in testa."
  },
  AvgDialog_25187_Content_4 = {
    Text = "Un dolore sordo ti pulsa nel petto mentre qualcuno ti sferra due calci secchi sulle costole contuse."
  },
  AvgDialog_25187_Content_5 = {
    Text = "Ugh! Coff, coff..."
  },
  AvgDialog_25187_Content_6 = {
    Text = "<Change>La camera da letto. Dal Consorte."
  },
  AvgDialog_25187_Content_7 = {
    Text = "Hai perso il conto di quante volte ti hanno svegliato in questo modo..."
  },
  AvgDialog_25187_Content_8 = {
    Text = "Esali un sospiro esausto e lasci che gli inservienti ti trascinino in piedi e fuori dalla stanza."
  },
  AvgDialog_25187_Content_9 = {
    Text = "Bagno, vestizione, toeletta..."
  },
  AvgDialog_25188_Content_1 = {
    Text = [[
Castello di Cambria
Camera da letto di Wanda]]
  },
  AvgDialog_25188_Content_10 = {
    Text = "Perdonatemi... Non comprendo il vostro significato, Lady Wanda."
  },
  AvgDialog_25188_Content_11 = {
    Text = "Oh? Il tuo volto racconta una storia ben diversa."
  },
  AvgDialog_25188_Content_12 = {
    Text = "Wanda inclina il mento verso l'anello che giace sul pavimento."
  },
  AvgDialog_25188_Content_13 = {
    Text = "Quell'anello era un dono del mio <Blue:quarto marito>. Sapete perché alla fine... è svanito?"
  },
  AvgDialog_25188_Content_14 = {
    Text = "<Shake:N-no... Non saprei...>"
  },
  AvgDialog_25188_Content_15 = {
    Text = "Un tempo era conosciuto come il 'Plantageneto di Cambrian'. Un guerriero davvero magnifico."
  },
  AvgDialog_25188_Content_16 = {
    Text = "Ma in seguito cospirò con signori rivali per rovesciarmi. Si spinse persino ad avvelenare il mio vino e il mio cibo."
  },
  AvgDialog_25188_Content_17 = {
    Text = "Peccato. Non potrà mai più avvelenare nessuno..."
  },
  AvgDialog_25188_Content_18 = {
    Text = "Wanda allunga la mano e accarezza la guancia fredda della sua serva, gli occhi colmi di un finto, tenero affetto."
  },
  AvgDialog_25188_Content_19 = {
    Text = "Ho ragione, mio caro marito?"
  },
  AvgDialog_25188_Content_2 = {
    Text = "Finalmente siete qui, signor Vayne. Avvicinatevi e aiutatemi a togliere questi anelli."
  },
  AvgDialog_25188_Content_20 = {
    Text = "<Change>Mia Signora... Amore..."
  },
  AvgDialog_25188_Content_21 = {
    Text = "L'ancella cieca si abbandona sottomessa nell'abbraccio di Wanda, apparentemente deliziata dal suo tocco."
  },
  AvgDialog_25188_Content_22 = {
    Text = "?! Hai davvero trasformato tuo marito in..."
  },
  AvgDialog_25188_Content_23 = {
    Text = "Basta così. La mia storia della buonanotte è finita. Ora tocca a voi, piccolo monaco."
  },
  AvgDialog_25188_Content_24 = {
    Text = "Pensaci molto bene. Non c'è <Italic:davvero> nulla che vuoi dirmi?"
  },
  AvgDialog_25188_Content_25 = {
    Text = "Il sorriso di Wanda svanisce, sostituito da una maschera di fredda indifferenza. Emana una pressione schiacciante che rende quasi impossibile respirare."
  },
  AvgDialog_25188_Content_26 = {Text = "..."},
  AvgDialog_25188_Content_27 = {
    Text = "A questo punto, ogni ulteriore inganno è futile. Estrai il biglietto dalla tasca e glielo porgi."
  },
  AvgDialog_25188_Content_28 = {
    Text = "Lady Wanda, posso spiegare! Non è stata una mia idea!"
  },
  AvgDialog_25188_Content_29 = {
    Text = "Sei tu quella che gli ha dato questo biglietto, non è vero?"
  },
  AvgDialog_25188_Content_3 = {
    Text = "Wanda siede davanti a un'ampia specchiera. Tende verso di voi le sue dita affusolate, appesantite da una serie di anelli sontuosi."
  },
  AvgDialog_25188_Content_30 = {
    Text = "Wanda solleva pigramente lo sguardo verso l'ancella che le sta accanto."
  },
  AvgDialog_25188_Content_31 = {
    Text = "Sì... gliel'ho dato io."
  },
  AvgDialog_25188_Content_32 = {
    Text = "L'ancella tiene il capo chino, il corpo intero scosso dai tremiti. Poi, inspira bruscamente e raddrizza la schiena."
  },
  AvgDialog_25188_Content_33 = {
    Text = "Demonio! Sei un demonio senza cuore!"
  },
  AvgDialog_25188_Content_34 = {
    Text = "Mio padre e mio fratello sono rinchiusi laggiù, nell'oscurità. Devo salvarli—"
  },
  AvgDialog_25188_Content_35 = {Text = "BOOM—!"},
  AvgDialog_25188_Content_36 = {
    Text = "Spuntoni d'osso frastagliati erompono dal pavimento, formando una gabbia letale attorno alla bambina."
  },
  AvgDialog_25188_Content_37 = {
    Text = "Non ho il benché minimo interesse per la tua tragica storiella. Guardie! Buttatela fuori."
  },
  AvgDialog_25188_Content_38 = {
    Text = "Lady Wanda, è solo una pedina insignificante in tutto questo. Vi prego, non c'è bisogno di essere così spietata..."
  },
  AvgDialog_25188_Content_39 = {
    Text = "Prima ancora che tu possa completare il pensiero, Wanda ti afferra per la gola, sollevandoti finché i tuoi occhi non sono alla stessa altezza dei suoi."
  },
  AvgDialog_25188_Content_4 = {
    Text = "La serva cieca e priva di arti se ne sta come un fantasma alle sue spalle, sentinella silenziosa nel freddo chiaro di luna."
  },
  AvgDialog_25188_Content_40 = {
    Text = "Parli quando te lo concedo. È chiaro?"
  },
  AvgDialog_25188_Content_41 = {
    Text = "<Shake:Coff... gah...>"
  },
  AvgDialog_25188_Content_42 = {
    Text = "Sei così assuefatto a questa persona da 'monaco' da aver dimenticato chi sei? Osi fare il santo in mia presenza?"
  },
  AvgDialog_25188_Content_43 = {Text = "?!"},
  AvgDialog_25188_Content_44 = {
    Text = "Come hai... saputo...?"
  },
  AvgDialog_25188_Content_45 = {
    Text = "Wanda allenta la presa e tu crolli a terra in un groviglio. Lei accavalla pigramente le gambe, godendosi lo spettacolo di te che boccheggi in cerca d'aria."
  },
  AvgDialog_25188_Content_46 = {
    Text = "Mi sono annoiato dei giochi di prestigio umani già secoli fa. Tu non sei certo Vayne @2."
  },
  AvgDialog_25188_Content_47 = {
    Text = "Gettatelo nelle segrete. Non fatelo uscire finché non sarà pronto a dire la verità."
  },
  AvgDialog_25188_Content_48 = {
    Text = "<Change>Ai vostri ordini!"
  },
  AvgDialog_25188_Content_5 = {
    Text = "Vi avvicinate a lei con passi grevi. Mentre chinate il capo per sfilare gli anelli dalle sue dita uno a uno, la mente continua a tornare a quel biglietto nascosto."
  },
  AvgDialog_25188_Content_6 = {
    Text = "<Gray:Dove si trova esattamente questo \"solito posto\"...?>"
  },
  AvgDialog_25188_Content_7 = {
    Text = "Che c'è? Avete l'aria di chi ha qualcosa da dirmi."
  },
  AvgDialog_25188_Content_8 = {Text = "?!"},
  AvgDialog_25188_Content_9 = {
    Text = "La vostra mano trema. Un anello di opale vi sfugge dalla presa, tintinnando sul pavimento e rotolando verso il bordo del letto."
  },
  AvgDialog_25189_Content_1 = {
    Text = "Regina Solitaria"
  },
  AvgDialog_25189_Content_10 = {
    Text = "Ancora non si sveglia? Aiutiamolo a rinfrescarsi."
  },
  AvgDialog_25189_Content_11 = {Text = "Hmm...!!"},
  AvgDialog_25189_Content_12 = {
    Text = "Un gelo improvviso e tagliente ti colpisce il petto."
  },
  AvgDialog_25189_Content_13 = {
    Text = "<Change>Ancora nessuna reazione... Mia Signora..."
  },
  AvgDialog_25189_Content_14 = {
    Text = "Allora tagliatelo. Un colpo netto."
  },
  AvgDialog_25189_Content_15 = {Text = "!!"},
  AvgDialog_25189_Content_16 = {
    Text = "<Big:Tagliare? Tagliare cosa?!>"
  },
  AvgDialog_25189_Content_17 = {
    Text = "Sei legato a un freddo telaio di ferro. Una pesante lama di ghigliottina pende a meno di dieci pollici dalle tue cosce, pronta a cadere—"
  },
  AvgDialog_25189_Content_18 = {
    Text = "Aspettate, un momento... <Big:Gah!>"
  },
  AvgDialog_25189_Content_19 = {
    Text = "Un dolore acuto divampa nel tuo petto. Le tue vesti sono a brandelli, rivelando una mappa di cicatrici orrende e frastagliate."
  },
  AvgDialog_25189_Content_2 = {
    Text = "C'era una volta..."
  },
  AvgDialog_25189_Content_20 = {
    Text = "È evidente che questo corpo ha sopportato abusi orribili."
  },
  AvgDialog_25189_Content_21 = {
    Text = "Ti sei finalmente svegliato."
  },
  AvgDialog_25189_Content_22 = {
    Text = "Una voce bassa e vellutata — carica di autorità — riecheggia nella vasta sala."
  },
  AvgDialog_25189_Content_23 = {
    Text = "La Nobildonna Wanda si appoggia pigramente alla sua attendente, scrutandoti con freddo interesse attraverso gli occhi socchiusi."
  },
  AvgDialog_25189_Content_24 = {
    Text = "Che significa tutto questo?!"
  },
  AvgDialog_25189_Content_25 = {
    Text = "\"Abbandonarsi alla lascivia, arrendersi alle proprie brame...\""
  },
  AvgDialog_25189_Content_26 = {
    Text = "Qual è la riga successiva? Continua a recitare, piccolo monaco."
  },
  AvgDialog_25189_Content_27 = {Text = "...?"},
  AvgDialog_25189_Content_28 = {
    Text = "Che c'è? Hai passato settimane a recitare quelle scritture alle porte della mia città. Le hai dimenticate nel momento stesso in cui hai messo piede dentro?"
  },
  AvgDialog_25189_Content_29 = {
    Text = "Le porte della città... le scritture..."
  },
  AvgDialog_25189_Content_3 = {
    Text = "Ella regna su tutto ciò che i suoi occhi vedono."
  },
  AvgDialog_25189_Content_30 = {
    Text = "Dopo una Punizione così brutale, la coscienza di questo corpo è un groviglio frantumato. Concentri la mente, ricomponendo lentamente frammenti di memoria."
  },
  AvgDialog_25189_Content_31 = {
    Text = "<Blue:Vayne @2>, 23 anni. Nato nel sud dello Shropshire. È stato ordinato Monaco nella Diocesi di Cambrian tre mesi fa."
  },
  AvgDialog_25189_Content_32 = {
    Text = "Devoto e compassionevole, era disgustato dallo stile di vita decadente di Lady Wanda. Ogni mattina si presentava ai cancelli del castello per recitare versi sacri in segno di protesta."
  },
  AvgDialog_25189_Content_33 = {
    Text = "Vayne resistette ventitré giorni prima che le guardie perdessero finalmente la pazienza e lo trascinassero dentro."
  },
  AvgDialog_25189_Content_34 = {
    Text = "\"Abbandonarsi alla lussuria, arrendersi alle proprie brame...\" La parte successiva è..."
  },
  AvgDialog_25189_Content_35 = {
    Text = "Hmm. Davvero dimenticata? In tal caso, tagliamolo semplicemente in due."
  },
  AvgDialog_25189_Content_36 = {
    Text = "Wanda sbadiglia e agita languidamente la mano."
  },
  AvgDialog_25189_Content_37 = {
    Text = "Rilasciatelo!"
  },
  AvgDialog_25189_Content_38 = {
    Text = "Gli ingranaggi a cremagliera gemono mentre girano. La Lama inizia la sua discesa, e la vampata d'aria gelida accende il tuo Istinto di Sopravvivenza."
  },
  AvgDialog_25189_Content_39 = {
    Text = "Aspettate! Aspettate! Ricordo! Ricordo!"
  },
  AvgDialog_25189_Content_4 = {
    Text = "Di notte, siede sola su un'alta terrazza, osservando i pianeti che rotolano lentamente nel vuoto."
  },
  AvgDialog_25189_Content_40 = {
    Text = "<Shake: \"...subirà tale Punizione quale monito... un monito...\">"
  },
  AvgDialog_25189_Content_41 = {
    Text = "<Gray:Maledizione... se solo avessi la memoria di Ramona.>"
  },
  AvgDialog_25189_Content_42 = {
    Text = "<Change>Mia Signora... una spia..."
  },
  AvgDialog_25189_Content_43 = {
    Text = "La gola del silenzioso servitore sussulta mentre emette un gorgoglio denso e roco."
  },
  AvgDialog_25189_Content_44 = {
    Text = "Oh? Continua pure."
  },
  AvgDialog_25189_Content_45 = {
    Text = "<Change>Diocesi. Scritture Sacre."
  },
  AvgDialog_25189_Content_46 = {Text = "Capisco..."},
  AvgDialog_25189_Content_47 = {
    Text = "\"Il mio piccolo animale domestico mi dice che potreste essere una spia... Un monaco che non ricorda nemmeno i suoi versi base.\""
  },
  AvgDialog_25189_Content_48 = {
    Text = "Tuttavia—"
  },
  AvgDialog_25189_Content_49 = {Text = "BOOM!!"},
  AvgDialog_25189_Content_5 = {
    Text = "Canta tra sé, sussurra alle stelle, e talvolta scivola nel sonno senza nemmeno rendersene conto."
  },
  AvgDialog_25189_Content_50 = {
    Text = "Spuntoni rigidi, simili a ossa, erompono dal pavimento, fermandosi a pochi centimetri dalla gola del servitore cieco. Wanda alza lo Sguardo e gli rivolge un'occhiata glaciale."
  },
  AvgDialog_25189_Content_51 = {
    Text = "Parli quando te lo permetto. Quando non lo faccio, sei un muto. È chiaro?"
  },
  AvgDialog_25189_Content_52 = {
    Text = "<Change>Obbedisco. Compreso."
  },
  AvgDialog_25189_Content_53 = {
    Text = "Il servitore cieco ammutolisce all'istante, ritirandosi nelle Ombre dell'angolo."
  },
  AvgDialog_25189_Content_54 = {
    Text = "La sala piomba in un silenzio tale che si potrebbe sentire cadere uno spillo sulla Pietra fredda."
  },
  AvgDialog_25189_Content_55 = {
    Text = "Bicchiere in Mano, Wanda ti si avvicina con passi al contempo aggraziati e predatori."
  },
  AvgDialog_25189_Content_56 = {
    Text = "Allunga la mano, le sue unghie lunghe sfiorano il tuo petto prima di soffermarsi sulla Pulsazione del tuo collo."
  },
  AvgDialog_25189_Content_57 = {
    Text = "Dice che sei una spia. <Red:Quindi... lo sei?>"
  },
  AvgDialog_25189_Content_58 = {
    Text = "Wanda socchiude i suoi occhi giallo-cobalto. Nasconde bene la sua crudeltà, ma essa guizza pericolosamente dietro il suo Sguardo come una scintilla nel buio."
  },
  AvgDialog_25189_Content_59 = {
    Text = "Se la tua prossima risposta non la soddisferà, quelle unghie ti squarceranno sicuramente la gola."
  },
  AvgDialog_25189_Content_6 = {
    Text = "Ha sempre fatto esattamente ciò che le pareva.\nPrima dei Cladi, era la Regina; dopo i Cladi, è l'unica cosa rimasta."
  },
  AvgDialog_25189_Content_60 = {
    Text = "Fai un respiro profondo e ti costringi a guardarla dritta negli occhi."
  },
  AvgDialog_25189_Content_61 = {
    Text = "Se fossi una spia, non avrei scelto questa identità."
  },
  AvgDialog_25189_Content_62 = {
    Text = "Primo, è troppo appariscente. Attira fin troppa attenzione e guai."
  },
  AvgDialog_25189_Content_63 = {
    Text = "Secondo, è un suicidio. Tutti a Cambrian sanno che Lady Wanda detesta i monaci più di ogni altra cosa—agh!"
  },
  AvgDialog_25189_Content_64 = {
    Text = "Vino gelido si riversa sul tuo collo, bruciando mentre penetra nelle tue ferite vive."
  },
  AvgDialog_25189_Content_65 = {
    Text = "Wanda getta via il bicchiere vuoto e sfoggia un sorriso tagliente."
  },
  AvgDialog_25189_Content_66 = {
    Text = "Di certo non mi piacciono i monaci. E quindi? Continui, signor Vayne."
  },
  AvgDialog_25189_Content_67 = {Text = "..."},
  AvgDialog_25189_Content_68 = {
    Text = "<Shake:Se fossi un impostore... sarei già stato ucciso dieci volte... prima ancora di mettere piede in questa sala...>"
  },
  AvgDialog_25189_Content_69 = {
    Text = "Wanda scoppia a ridere, visibilmente deliziata dalla tua risposta."
  },
  AvgDialog_25189_Content_7 = {
    Text = "E così, continua a fare ciò che le aggrada."
  },
  AvgDialog_25189_Content_70 = {
    Text = "Che sorpresa. Sembra che tu non sia poi una creaturina così ottusa e noiosa, dopotutto."
  },
  AvgDialog_25189_Content_71 = {
    Text = "Mi piacciono le persone intelligenti. Ma adoro quelle che sono sia intelligenti che belle."
  },
  AvgDialog_25189_Content_72 = {
    Text = "Wanda ti dà un colpetto sulla guancia con finta tenerezza, poi alza la voce per chiamare i suoi servitori."
  },
  AvgDialog_25189_Content_73 = {
    Text = "Portatelo via. Lavatelo per bene e conducetelo nella mia camera da letto stanotte."
  },
  AvgDialog_25189_Content_74 = {
    Text = "La sua camera da letto? Per quale motivo...?"
  },
  AvgDialog_25189_Content_75 = {
    Text = [[
Nessuno si degna di risponderti.
Wanda sbadiglia e lascia la sala in una processione solenne, circondata dal suo seguito.]]
  },
  AvgDialog_25189_Content_76 = {
    Text = "Vedendo la tua espressione smarrita, un'ancella lì vicino alza gli occhi al cielo."
  },
  AvgDialog_25189_Content_77 = {
    Text = "Davvero non capisci? Stanotte dovrai servirla a letto. È un'opportunità per cui la maggior parte della gente sarebbe disposta a uccidere..."
  },
  AvgDialog_25189_Content_78 = {
    Text = "<Shake:Assistere al suo letto?!>"
  },
  AvgDialog_25189_Content_79 = {
    Text = "La tua visuale si annebbia e perdi conoscenza ancora una volta."
  },
  AvgDialog_25189_Content_8 = {
    Text = "Sì, tutto ciò che vede è suo da governare — sebbene sia ormai da tempo sgretolato in polvere cosmica."
  },
  AvgDialog_25189_Content_9 = {
    Text = "Una regina senza sudditi è ancora una regina?\nWanda non conosce la risposta."
  },
  AvgDialog_25190_Content_1 = {
    Text = "<Change>Aargh..."
  },
  AvgDialog_25190_Content_10 = {
    Text = [[
<Yellow:Incontriamoci al solito posto @1 alle 21 del 17> per discutere il piano.
Attenti @1 alla Donna delle @2 Spine.

Il tuo vecchio amico,
Guderian]]
  },
  AvgDialog_25190_Content_11 = {
    Text = "<Gray:Un \"piano\"? Che tipo di piano?>"
  },
  AvgDialog_25190_Content_12 = {
    Text = "\"Il mio piccolo animale domestico mi dice che potreste essere una spia... Un monaco che non ricorda nemmeno i suoi versi base.\""
  },
  AvgDialog_25190_Content_13 = {
    Text = "Quel servitore aveva ragione? Sono davvero una spia?"
  },
  AvgDialog_25190_Content_14 = {
    Text = "Non posso credere di aver tralasciato informazioni così cruciali nelle sue memorie... Dev'essere stato torturato oltre il limite della ragione."
  },
  AvgDialog_25190_Content_15 = {
    Text = "Nascondete il biglietto, la mente in fermento per nuove domande."
  },
  AvgDialog_25190_Content_16 = {
    Text = "Che state a fissare? La Signora non ha pazienza. L'ultimo che è arrivato in ritardo marcisce in una cella da due anni."
  },
  AvgDialog_25190_Content_17 = {Text = "...Ehi."},
  AvgDialog_25190_Content_18 = {
    Text = "Vi chinate verso la cameriera, mantenendo la voce appena sopra un sussurro."
  },
  AvgDialog_25190_Content_19 = {
    Text = "<SmallShake:Siete anche voi una delle talpe del Conte Guderian?>"
  },
  AvgDialog_25190_Content_2 = {
    Text = "Respingi i mostri incombenti con facilità."
  },
  AvgDialog_25190_Content_20 = {
    Text = "Ahem! Smettila di borbottare e continua a camminare!"
  },
  AvgDialog_25190_Content_21 = {
    Text = "La cameriera vi rimprovera aspramente, ma i suoi occhi guizzano verso di voi con un'inconfondibile impazienza e un significato segreto."
  },
  AvgDialog_25190_Content_22 = {
    Text = "<Gray:Mio caro, stai rendendo la cosa un po' troppo evidente.>"
  },
  AvgDialog_25190_Content_23 = {
    Text = "E ora? Portare a termine il piano originale di Vayne, o consegnare la verità a Wanda?"
  },
  AvgDialog_25190_Content_24 = {
    Text = "<Gray:A dire il vero, sono piuttosto curioso di scoprire cosa stia realmente tramando questo Conte...>"
  },
  AvgDialog_25190_Content_3 = {
    Text = "<Gray:L'icore corrosivo ha raggiunto il cuore del castello. Com'è possibile che Wanda non ne sia consapevole?>"
  },
  AvgDialog_25190_Content_4 = {
    Text = "Allora è vero. È davvero <Blue:\"quel gentiluomo\"> di cui parlava il Conte."
  },
  AvgDialog_25190_Content_5 = {
    Text = "Se è lui, allora sicuramente può..."
  },
  AvgDialog_25190_Content_6 = {
    Text = "Un frammento di carta vi viene improvvisamente premuto nel palmo della mano."
  },
  AvgDialog_25190_Content_7 = {
    Text = "Alzate lo sguardo e vedete la cameriera, che poco prima si rannicchiava dietro di voi, ergersi di nuovo con la sua consueta maschera di fredda arroganza."
  },
  AvgDialog_25190_Content_8 = {Text = "?"},
  AvgDialog_25190_Content_9 = {
    Text = "Spiegate il biglietto. È coperto di cifre scarabocchiate, ma usando le memorie di Vayne riuscite a decodificare il messaggio."
  },
  AvgDialog_25191_Content_1 = {
    Text = "Notte di Morte, Idromele e Canto"
  },
  AvgDialog_25191_Content_10 = {
    Text = "Ciò che questa donna pensa, nessuno può indovinarlo. Tuttavia—"
  },
  AvgDialog_25191_Content_11 = {
    Text = "La peste del Cambrian è incurabile. Se gli infetti venissero liberati, il cielo solo sa cosa accadrebbe."
  },
  AvgDialog_25191_Content_12 = {
    Text = "A prescindere dall'intenzione di Wanda, le sue azioni hanno effettivamente salvato i feudi circostanti..."
  },
  AvgDialog_25191_Content_13 = {
    Text = [[
Castello di Cambrian
Sala del Banchetto]]
  },
  AvgDialog_25191_Content_14 = {
    Text = "Spingete la pesante porta di legno della sala."
  },
  AvgDialog_25191_Content_15 = {
    Text = "Una luce abbagliante si riversa nella stanza come stelle cadute. L'aria è densa del dolce aroma di vino e cibi prelibati."
  },
  AvgDialog_25191_Content_16 = {
    Text = "I contadini del Cambrian hanno indossato i loro abiti migliori, danzando con gioia al ritmo della musica."
  },
  AvgDialog_25191_Content_17 = {
    Text = "Sebbene il mondo esterno sia sommerso dalla Dissoluzione, la sala resta colma di allegria."
  },
  AvgDialog_25191_Content_18 = {
    Text = "È questo il leggendario budino di mele? Non ho mai assaggiato nulla di così delizioso in vita mia..."
  },
  AvgDialog_25191_Content_19 = {
    Text = "Hahaha! Sono così felice! Se muoio stanotte, ne sarà valsa la pena!"
  },
  AvgDialog_25191_Content_2 = {
    Text = [[
Feudo di Guderian
Terreni di Caccia]]
  },
  AvgDialog_25191_Content_20 = {
    Text = "Danzate! Avanti, tutti danzate!"
  },
  AvgDialog_25191_Content_21 = {
    Text = "Ti fai strada tra la folla brulicante e trovi Wanda seduta all'estremità opposta."
  },
  AvgDialog_25191_Content_23 = {
    Text = "Si appoggia languidamente alle sue ancelle, il vino rosso nel suo calice cattura la luce come un rubino levigato."
  },
  AvgDialog_25191_Content_24 = {
    Text = "Buonasera, Maestro Monaco. Pensavo foste troppo pio per unirvi alla nostra assurda baldoria."
  },
  AvgDialog_25191_Content_25 = {
    Text = "A volte desidero soddisfare la mia curiosità."
  },
  AvgDialog_25191_Content_26 = {
    Text = "<Gray:E poi, con la D-melma ovunque là fuori, dove altro potrei mai andare...?>"
  },
  AvgDialog_25191_Content_27 = {
    Text = "Qualcuno tira delicatamente il lembo della vostra veste."
  },
  AvgDialog_25191_Content_28 = {
    Text = "Tu sei... il fratello di Susanna!"
  },
  AvgDialog_25191_Content_29 = {
    Text = "Ho un nome, sapete! Tutti mi chiamano Piccolo Beckman."
  },
  AvgDialog_25191_Content_3 = {
    Text = "Cosa? Mi stai dicendo che Wanda ha fuso i chiavistelli e sta tenendo un ballo per ogni contadino del Cambrian dentro quel castello?"
  },
  AvgDialog_25191_Content_30 = {
    Text = "Buonasera, Piccolo Beckman. Dov'è andata tua sorella?"
  },
  AvgDialog_25191_Content_31 = {
    Text = "La sorella maggiore e gli altri che non erano malati sono partiti insieme..."
  },
  AvgDialog_25191_Content_32 = {
    Text = "Il Piccolo Beckman china il capo, avvilito. Tira su col naso, poi alza lo sguardo verso di voi con occhi spalancati e lucidi."
  },
  AvgDialog_25191_Content_33 = {
    Text = "Buon signore, volete danzare con me? Non ho un compagno, sniff sniff..."
  },
  AvgDialog_25191_Content_34 = {
    Text = "Piccolo mio, ai monaci non è permesso danzare."
  },
  AvgDialog_25191_Content_35 = {
    Text = "Ora dichiaro che vi è concesso. Dimenticate quelle regole obsolete."
  },
  AvgDialog_25191_Content_36 = {
    Text = "A Cambrian, io—<Big:SONO LA LEGGE STESSA!>"
  },
  AvgDialog_25191_Content_37 = {
    Text = "Guardate negli occhi pieni di Speranza del Piccolo Beckman e ingoiate il vostro rifiuto."
  },
  AvgDialog_25191_Content_38 = {
    Text = "Temo di non aver mai imparato a danzare, ma posso certamente roteare un po' con voi."
  },
  AvgDialog_25191_Content_39 = {
    Text = "Prendete la Mano del Piccolo Beckman e lo conducete al centro della sala, unendovi al mare di Abitanti del villaggio che ondeggiano al ritmo della melodia."
  },
  AvgDialog_25191_Content_4 = {
    Text = "È la pura verità! Ho sentito che quelli non infetti se ne sono andati tutti. Gli unici rimasti a quella danza sono i malati terminali."
  },
  AvgDialog_25191_Content_40 = {
    Text = "Le gonne svolazzano e turbinano nella luce delle candele come un migliaio di dolcetti colorati che ruotano su se stessi."
  },
  AvgDialog_25191_Content_41 = {
    Text = "Vagate attraverso questo oceano dorato di luce e canto, infine sommersi dalle bolle crescenti di Gioia."
  },
  AvgDialog_25191_Content_42 = {
    Text = "I passi del Piccolo Beckman non sono migliori dei vostri. Si dimena senza meta a tempo di musica, il volto che si accende di un rosso vivo e felice."
  },
  AvgDialog_25191_Content_43 = {
    Text = "Ahahah! Che felicità! Questo è il giorno più bello della mia Vita!"
  },
  AvgDialog_25191_Content_44 = {
    Text = "Signore, prendete la mia mano! Giriamo insieme!"
  },
  AvgDialog_25191_Content_45 = {
    Text = "Sbrigatevi!"
  },
  AvgDialog_25191_Content_46 = {
    Text = "<BigShake:Più veloce!>"
  },
  AvgDialog_25191_Content_47 = {
    Text = "<Red:Più veloce...>"
  },
  AvgDialog_25191_Content_48 = {
    Text = "Più velo@2..."
  },
  AvgDialog_25191_Content_49 = {
    Text = "Piccolo Beckman, cosa sta succedendo alla tua faccia...?!"
  },
  AvgDialog_25191_Content_5 = {
    Text = "Hahaha! Mi sono dato tanta pena per piazzare una talpa al suo fianco... sembra che abbia sprecato le mie energie."
  },
  AvgDialog_25191_Content_50 = {
    Text = "<Change>Danzate con me..."
  },
  AvgDialog_25191_Content_51 = {
    Text = "D-melma nera come inchiostro comincia a colare dagli Occhi del Ragazzo, eppure continua a sorridere mentre allunga le mani verso di voi."
  },
  AvgDialog_25191_Content_52 = {
    Text = "Un'improvvisa umidità fredda vi sfiora il naso. Alzate lo sguardo e vedete un icore nero gocciolare lentamente dal lampadario di cristallo."
  },
  AvgDialog_25191_Content_53 = {
    Text = "Una goccia. Due."
  },
  AvgDialog_25191_Content_54 = {
    Text = "Vi guardate intorno in preda al panico, solo per rendervi conto che gli abiti, le braccia e i volti di molte persone stanno cominciando a marcire."
  },
  AvgDialog_25191_Content_55 = {
    Text = "Eppure continuano a danzare con gioia."
  },
  AvgDialog_25191_Content_56 = {
    Text = "Signore, perché mi ignorate? Non vi piaccio più...?"
  },
  AvgDialog_25191_Content_57 = {
    Text = "Il Ragazzo avvolge le sue mani appiccicose attorno a voi, Pianto che trabocca dalle sue orbite vuote."
  },
  AvgDialog_25191_Content_58 = {
    Text = "Resta con me... Resta con me..."
  },
  AvgDialog_25191_Content_6 = {
    Text = "Con una peste così orribile, non tenta nemmeno di fuggire. Li chiude tutti dentro ad aspettare la morte..."
  },
  AvgDialog_25191_Content_7 = {
    Text = "È vero, come dicono le voci, che è completamente impazzita?"
  },
  AvgDialog_25191_Content_8 = {
    Text = "Le vostre parole sono piuttosto intriganti. È mai stata una donna di sano intelletto, tanto per cominciare?"
  },
  AvgDialog_25191_Content_9 = {
    Text = "Ehm... beh..."
  },
  AvgDialog_25199_Content_1 = {
    Text = "Finalmente riuscite a divincolarvi dal Piccolo Beckman, solo per vedere l'intera sala mutare."
  },
  AvgDialog_25199_Content_10 = {
    Text = "Se siamo destinati alla tomba, perché non dovremmo congedarci con Gioia?"
  },
  AvgDialog_25199_Content_11 = {
    Text = "O dovremmo rannicchiarci nei nostri letti e piangere in solitudine, solo per soddisfare la tua idea di come i moribondi dovrebbero comportarsi?"
  },
  AvgDialog_25199_Content_12 = {
    Text = "Te l'ho detto. A Cambrian, la legge sono io."
  },
  AvgDialog_25199_Content_13 = {
    Text = [[
La Regina ordina: Danzate! Continuate a danzare!
Passato, presente e futuro: non temeremo mai la morte.]]
  },
  AvgDialog_25199_Content_14 = {
    Text = "Al comando di Wanda—"
  },
  AvgDialog_25199_Content_16 = {
    Text = "L'atmosfera nella sala raggiunge il suo apice."
  },
  AvgDialog_25199_Content_17 = {
    Text = "<Change> Danza, danza..."
  },
  AvgDialog_25199_Content_19 = {
    Text = "Pazzi. Sono tutti completamente impazziti..."
  },
  AvgDialog_25199_Content_2 = {
    Text = "La sala del Banchetto si è trasformata in un immenso cimitero. La D-melma che trasuda è come un Branco di pidocchi nascosti sotto una veste di seta."
  },
  AvgDialog_25199_Content_20 = {
    Text = "Osservi con sgomento tutto ciò che si dispiega davanti ai tuoi Occhi. Nemmeno nei tuoi deliri febbrili più sfrenati hai mai assistito a una scena così fantasmagorica."
  },
  AvgDialog_25199_Content_21 = {
    Text = "Tutti sono folli. Tutti sono segnati."
  },
  AvgDialog_25199_Content_22 = {
    Text = "Ma tutti sono felici."
  },
  AvgDialog_25199_Content_23 = {Text = "..."},
  AvgDialog_25199_Content_24 = {
    Text = "Una volta sentii qualcuno dire: Chi non riesce a udire la musica crede che le danzatrici siano pazze."
  },
  AvgDialog_25199_Content_25 = {
    Text = "Ti strappi il colletto e crolli al suolo, completamente esausto."
  },
  AvgDialog_25199_Content_26 = {
    Text = "È buffo, in un certo senso. Una volta giurai sulla tomba di Mythag di affrontare la vita e la morte senza Terrore... eppure non sono mai stato davvero pronto ad affrontare la morte."
  },
  AvgDialog_25199_Content_27 = {
    Text = "Mi hai offerto una nuova prospettiva — anche se spero di non dover mai affrontare un simile dilemma."
  },
  AvgDialog_25199_Content_28 = {
    Text = "Afferri un calice e brindi a Wanda attraverso il mare di icore nero, vino versato e fiori sparsi."
  },
  AvgDialog_25199_Content_29 = {
    Text = "Al coraggio."
  },
  AvgDialog_25199_Content_3 = {
    Text = "No. Troppe persone stanno mutando contemporaneamente..."
  },
  AvgDialog_25199_Content_30 = {
    Text = "Wanda ride di cuore e alza il calice verso di te."
  },
  AvgDialog_25199_Content_31 = {
    Text = "Alla morte. La nostra più magnifica e dolce dipartita."
  },
  AvgDialog_25199_Content_32 = {
    Text = "Il dolce fetore di cadaveri in decomposizione ti riempie le narici, accompagnato da una cacofonia di lamenti, singhiozzi e risate."
  },
  AvgDialog_25199_Content_33 = {
    Text = "Ma non smettono mai di danzare."
  },
  AvgDialog_25199_Content_34 = {
    Text = "La Regina non abbandona mai il suo popolo. Presto, marceranno insieme verso questo magnifico Festino di morte."
  },
  AvgDialog_25199_Content_36 = {
    Text = "Questa volta, finalmente, non è sola."
  },
  AvgDialog_25199_Content_37 = {
    Text = "Riesci ancora a ricordare quella Scrittura Divina? Quella che hai recitato alle porte?"
  },
  AvgDialog_25199_Content_38 = {
    Text = "...Ricordo."
  },
  AvgDialog_25199_Content_39 = {
    Text = "<Red:Indulgere nella lussuria e cedere a Desideri sfrenati sarà punito dal fuoco eterno, come monito.>"
  },
  AvgDialog_25199_Content_4 = {
    Text = "Istintivamente volgi lo sguardo verso Wanda."
  },
  AvgDialog_25199_Content_40 = {
    Text = "Allora sei pronto? Pronto per il fuoco eterno?"
  },
  AvgDialog_25199_Content_41 = {
    Text = "Nell'Oscurità che si addensa, odi soltanto una risata lontana e morente."
  },
  AvgDialog_25199_Content_42 = {
    Text = "Come Frammenti di meteora che cadono in un lago, i suoni sprofondano lentamente negli abissi della tua coscienza."
  },
  AvgDialog_25199_Content_43 = {
    Text = "Finché, alla fine di tutto, non resta che il Silenzio."
  },
  AvgDialog_25199_Content_5 = {
    Text = "Attraverso la Folla brulicante, Wanda sorride e alza il calice verso di voi."
  },
  AvgDialog_25199_Content_6 = {
    Text = "Hai già paura, piccolo Monaco?"
  },
  AvgDialog_25199_Content_7 = {
    Text = "Non capisco. Hai intenzione di restare lì a guardare mentre impazziscono e muoiono?"
  },
  AvgDialog_25199_Content_8 = {
    Text = "Wanda scoppia a ridere, lacrime nere che le rigano le guance. La sua stessa pelle è già crivellata di ferite causate dalla Dissoluzione."
  },
  AvgDialog_25199_Content_9 = {
    Text = "Nulla è eterno, piccolo Monaco. Nemmeno gli dèi che veneri."
  },
  AvgDialog_34830_Content_1 = {Text = "Pifferaio"},
  AvgDialog_34830_Content_10 = {
    Text = "Non abbiate paura. Troverò un modo per farvi uscire di qui."
  },
  AvgDialog_34830_Content_11 = {
    Text = "Gli abitanti del villaggio ricambiano lo sguardo in silenzio. Non c'è speranza nei loro occhi—ma nemmeno ostilità."
  },
  AvgDialog_34830_Content_12 = {
    Text = "Aspettate, l'ancella..."
  },
  AvgDialog_34830_Content_13 = {
    Text = "Mio padre e mio fratello sono rinchiusi Sotto. Devo salvarli—"
  },
  AvgDialog_34830_Content_14 = {
    Text = "Qualcuno di voi conosce un'ancella di nome Susanna?"
  },
  AvgDialog_34830_Content_15 = {
    Text = "Susanna? È la mia sorella maggiore!"
  },
  AvgDialog_34830_Content_16 = {
    Text = "Una voce cristallina di bambino giunse dall'angolo."
  },
  AvgDialog_34830_Content_17 = {
    Text = "Alla luce tremolante di un'unica candela, noti un vecchio disteso nell'ombra con un ragazzo dagli occhi spalancati rannicchiato accanto a lui."
  },
  AvgDialog_34830_Content_18 = {
    Text = "Susanna è mia figlia... Le è successo qualcosa?"
  },
  AvgDialog_34830_Content_19 = {
    Text = "È profondamente preoccupata per voi. Stava cercando un modo per salvarvi."
  },
  AvgDialog_34830_Content_2 = {
    Text = [[
Castello Cambrian
Prigione Sotterranea]]
  },
  AvgDialog_34830_Content_20 = {
    Text = "Non possiamo lasciare questo posto..."
  },
  AvgDialog_34830_Content_21 = {
    Text = "Il vecchio scosse la testa. Il suo corpo era coperto di fori della Dissoluzione, da cui colava una melma nera che macchiava la paglia sotto di lui."
  },
  AvgDialog_34830_Content_22 = {
    Text = "Siamo rimasti qui di nostra spontanea volontà. Una volta che il morbo ti prende, perdi la ragione... ti trasformi in un mostro."
  },
  AvgDialog_34830_Content_23 = {
    Text = "È vero. C'erano stati così tanti omicidi nei dintorni... Poi la Signora è passata casa per casa. Ha radunato i malati e li ha portati qui."
  },
  AvgDialog_34830_Content_24 = {
    Text = "Se qualcuno non voleva essere messo in quarantena, lo lasciava andare via dal feudo—a patto che giurasse di non tornare mai più."
  },
  AvgDialog_34830_Content_25 = {
    Text = "Ma qui riceviamo porridge e pane dolce ogni giorno!"
  },
  AvgDialog_34830_Content_26 = {
    Text = "<Gray:Capisco. L'abbiamo completamente fraintesa?>"
  },
  AvgDialog_34830_Content_27 = {
    Text = "Lady Wanda vi ha trattato bene da quando ha preso il controllo del feudo?"
  },
  AvgDialog_34830_Content_28 = {
    Text = "Bene? Non saprei. Non l'ho mai vista di persona. Ho solo sentito le storie—che è crudele, che ha ucciso i suoi quattro mariti, che è un diavolo in carne e ossa."
  },
  AvgDialog_34830_Content_29 = {
    Text = "Ma da quando è qui, ha fatto molto del bene. La vita è molto migliore di prima."
  },
  AvgDialog_34830_Content_3 = {
    Text = "La pesante porta di ferro si chiude ermeticamente alle tue spalle."
  },
  AvgDialog_34830_Content_30 = {
    Text = "Ci ha insegnato a coltivare e allevare pecore. Ogni anno durante la festa, portavamo la lana al mercato estivo e guadagnavamo una bella somma."
  },
  AvgDialog_34830_Content_31 = {
    Text = "Esatto, il Mercato di Charich le è stato strappato dal Conte Goodrich. Si contendono quel posto da quasi un anno..."
  },
  AvgDialog_34830_Content_32 = {
    Text = "Gli abitanti del villaggio cominciano tutti a parlare contemporaneamente, condividendo storie sulla gestione di Wanda: agricoltura, fonderia, allevamento, leggi del feudo..."
  },
  AvgDialog_34830_Content_33 = {
    Text = "Resti stupito da quanto profondamente Wanda sia coinvolta in ogni aspetto del feudo. Non è certo una nobile oziosa e dedita ai piaceri."
  },
  AvgDialog_34830_Content_34 = {
    Text = "È una buona governante. È solo una tragedia che la Dissoluzione l'abbia colpita."
  },
  AvgDialog_34830_Content_35 = {
    Text = "<Gray:Una Propagazione di queste dimensioni... dev'esserci una D-fessura nelle vicinanze.>"
  },
  AvgDialog_34830_Content_36 = {
    Text = "La porta di ferro alle vostre spalle si apre cigolando all'improvviso."
  },
  AvgDialog_34830_Content_37 = {
    Text = "Ti volti e trovi Wanda in piedi fuori dal cancello della prigione. La sua figura imponente blocca la luce delle candele nel corridoio, proiettando un caldo bagliore arancione sulla sua silhouette."
  },
  AvgDialog_34830_Content_38 = {
    Text = "Fate uscire questo tizio, devo dire qualcosa a {Male=lui,Female=lei} in privato."
  },
  AvgDialog_34830_Content_39 = {
    Text = [[
Castello di Cambrian
Giardino]]
  },
  AvgDialog_34830_Content_4 = {
    Text = "Ti volti e incontri inaspettatamente diversi paia di occhi luminosi, che ti circondano come bestie nell'oscurità più totale."
  },
  AvgDialog_34830_Content_40 = {
    Text = "Camminate insieme sull'erba soffice fino a raggiungere la riva del lago."
  },
  AvgDialog_34830_Content_41 = {
    Text = "A mezzanotte, il lago è uno specchio oscuro, che riflette i frammenti infranti della luna lassù."
  },
  AvgDialog_34830_Content_42 = {
    Text = "Dovresti capire che Cambrian sta attraversando gravi disastri di Dissoluzione, e io sono impotente nel fermarli."
  },
  AvgDialog_34830_Content_43 = {
    Text = "E tu, quando combattevi quei mostri nel castello, eri così abile—come se fossi un professionista."
  },
  AvgDialog_34830_Content_44 = {
    Text = "<Gray:In effetti sono un/una professionista in questo...>"
  },
  AvgDialog_34830_Content_45 = {
    Text = "Non eravate nelle vostre stanze in quel momento, Mia Signora? Come fate a sapere così tanto di quello scontro?"
  },
  AvgDialog_34830_Content_46 = {
    Text = "Ho occhi e orecchie ovunque a Cambrian. Se una singola fresia vuole sbocciare, ha bisogno prima del mio permesso. Non c'è nulla che io non sappia."
  },
  AvgDialog_34830_Content_47 = {
    Text = "E quella ancella? Se sapevate che era una spia, perché tenerla al vostro fianco?"
  },
  AvgDialog_34830_Content_48 = {
    Text = "Wanda agita una mano con noncuranza."
  },
  AvgDialog_34830_Content_49 = {
    Text = "È solo una povera, comune mortale. Non potrebbe torcermi un capello nemmeno volendo."
  },
  AvgDialog_34830_Content_5 = {
    Text = "<Shake:Woaaahhh!!>"
  },
  AvgDialog_34830_Content_50 = {
    Text = "E poi è una serva competente. Trovare un essere umano che faccia davvero ciò che gli si dice non è impresa da poco."
  },
  AvgDialog_34830_Content_51 = {
    Text = "In breve, ho bisogno che tu ponga fine a questa Dissoluzione. Non affrettarti a rifiutare — il prezzo lo discuteremo dopo. Ti darò qualunque cosa tu desideri."
  },
  AvgDialog_34830_Content_52 = {
    Text = "Non lasceresti certo morire questi abitanti del villaggio di una morte così insensata, vero... mio caro \"monaco\"?"
  },
  AvgDialog_34830_Content_53 = {Text = "..."},
  AvgDialog_34830_Content_54 = {
    Text = "Nell'ultimo incontro nei dormitori, la Signora ha menzionato \"voi umani\", e combinando questo con le vostre abilità speciali... Lady Wanda, voi non siete umana, vero?"
  },
  AvgDialog_34830_Content_55 = {
    Text = "Una presenza da una terra lontana, potente e brutale, eppure preoccupata per le vite dei villici. Qual è il vero scopo della Signora?"
  },
  AvgDialog_34830_Content_56 = {
    Text = "Di fronte al tuo interrogatorio, Wanda inarca un sopracciglio e scoppia improvvisamente a ridere."
  },
  AvgDialog_34830_Content_57 = {
    Text = "Ho forse detto qualcosa di divertente?"
  },
  AvgDialog_34830_Content_58 = {
    Text = "No... Ahahah! Sono semplicemente così felice. In tutti gli anni che ho trascorso qui, ho finalmente incontrato qualcun altro che non appartiene a \"questo luogo\"—proprio come me."
  },
  AvgDialog_34830_Content_59 = {
    Text = "Come avete—"
  },
  AvgDialog_34830_Content_6 = {
    Text = "Mentre la tua visuale si adatta alla penombra, finalmente scorgi la realtà della cella."
  },
  AvgDialog_34830_Content_60 = {
    Text = "Wanda posa delicatamente un dito sottile sulle tue labbra."
  },
  AvgDialog_34830_Content_61 = {
    Text = "Shh... Seguitemi. Voglio mostrarvi una cosa."
  },
  AvgDialog_34830_Content_62 = {
    Text = "Lo sapevi? Dal riflesso di questo lago, si può vedere la città dove vivevo un tempo."
  },
  AvgDialog_34830_Content_63 = {
    Text = "Ti sei avvicinato/a al lago. L'acqua blu profondo è quasi senza fondo, rivelando vagamente piante acquatiche e massi neri sfocati."
  },
  AvgDialog_34830_Content_64 = {
    Text = "La luce della luna illumina il fondale profondo del lago, e finalmente riesci a distinguere la guglia a spirale nera e le pareti ad angolo smussato sulla pietra."
  },
  AvgDialog_34830_Content_65 = {
    Text = "C'è... una città sott'acqua?!"
  },
  AvgDialog_34830_Content_66 = {
    Text = "A quei tempi, avevo un palazzo grandioso. Oltre un migliaio di servitori provvedevano a ogni mio bisogno."
  },
  AvgDialog_34830_Content_67 = {
    Text = "Proprio come hai detto, non mi sono mai curata delle vite dei miei sottoposti."
  },
  AvgDialog_34830_Content_68 = {
    Text = "Ho fatto esattamente ciò che volevo. I miei servitori, la mia città... non erano che manifestazioni della mia volontà e della mia ambizione."
  },
  AvgDialog_34830_Content_69 = {
    Text = "Poi, il mio pianeta fu colpito dalla catastrofe che voi chiamate \"Dissoluzione\". Morirono tutti."
  },
  AvgDialog_34830_Content_7 = {
    Text = "Seduti, distesi o appoggiati alle fredde pareti di pietra—la stanza è stipata di abitanti del villaggio laceri e cenciosi."
  },
  AvgDialog_34830_Content_70 = {
    Text = "Rimasi seduta sola in quella sala per molto, molto tempo, osservando il mio palazzo e la mia capitale ridursi in cenere."
  },
  AvgDialog_34830_Content_71 = {
    Text = "A dire il vero, fu una sensazione terribile. Nessuno vorrebbe viverla due volte."
  },
  AvgDialog_34830_Content_72 = {
    Text = "Signora Wanda..."
  },
  AvgDialog_34830_Content_73 = {
    Text = "Mi dispiace, questa volta non posso aiutarti. Chiudere la D-fessura è troppo complesso perché io possa gestirlo da sola."
  },
  AvgDialog_34830_Content_74 = {
    Text = "Non preoccuparti di questo. Dimmi cosa ti trattiene, e ti fornirò tutto ciò di cui hai bisogno."
  },
  AvgDialog_34830_Content_75 = {
    Text = "Scuoti la testa."
  },
  AvgDialog_34830_Content_76 = {
    Text = "Non è solo questo. Il nostro ambiente attuale... presenta alcune... peculiarità."
  },
  AvgDialog_34830_Content_77 = {
    Text = "Durante la Fase Onirica, non è possibile eseguire azioni complesse come la chiusura delle fessure."
  },
  AvgDialog_34830_Content_78 = {
    Text = "<Gray:Come faccio anche solo a spiegarglielo?>"
  },
  AvgDialog_34830_Content_79 = {
    Text = "Poiché siamo in un sogno, non puoi aiutarmi... è così?"
  },
  AvgDialog_34830_Content_8 = {
    Text = "La loro pelle è costellata di cicatrici della Dissoluzione; alcuni hanno già perso metà del corpo a causa della putrefazione. L'aria è satura del fetore di malattia e di morte imminente."
  },
  AvgDialog_34830_Content_80 = {Text = "?!"},
  AvgDialog_34830_Content_81 = {
    Text = "Voi... ve ne siete accorto?"
  },
  AvgDialog_34830_Content_82 = {
    Text = "Wanda contempla la città nera nell'acqua, i suoi occhi scintillanti di frammentato chiaro di luna bianco."
  },
  AvgDialog_34830_Content_83 = {
    Text = "Da quando sono giunto qui, ho fatto molti sogni. Sulla guerra, sulle catastrofi, sul tempo... ma mai una volta sulla mia capitale."
  },
  AvgDialog_34830_Content_84 = {
    Text = "Proprio quando stavo per dimenticarlo, ho incontrato te, e poi l'ho rivisto sul fondo del lago."
  },
  AvgDialog_34830_Content_85 = {
    Text = "Lo sapevi? Quando un uomo morente vede il Pifferaio muoversi nella nebbia, non prova né terrore né curiosità."
  },
  AvgDialog_34830_Content_86 = {
    Text = "Semplicemente segue il Pifferaio in silenzio, dirigendosi verso un luogo tutto suo."
  },
  AvgDialog_34830_Content_87 = {
    Text = "Wanda emise un sospiro profondo e malinconico."
  },
  AvgDialog_34830_Content_88 = {
    Text = "La mia capitale perduta... è bellissima, come il sogno di un uomo morente."
  },
  AvgDialog_34830_Content_89 = {
    Text = "Accarezza dolcemente l'attendente silenzioso e cieco al suo fianco."
  },
  AvgDialog_34830_Content_9 = {
    Text = "Wanda vi ha davvero rinchiusi tutti qui dentro..."
  },
  AvgDialog_34830_Content_90 = {
    Text = "<Change>Mia Signora..."
  },
  AvgDialog_34830_Content_91 = {
    Text = "Cambrian è il mio secondo focolare. Non ho trascorso molto tempo qui, eppure è già ora di dire addio."
  },
  AvgDialog_34830_Content_92 = {
    Text = "Mi dispiace, Lady Wanda..."
  },
  AvgDialog_34830_Content_93 = {
    Text = "Wanda agita una mano con noncuranza. Quando alza di nuovo lo sguardo, la malinconia è svanita dal suo volto."
  },
  AvgDialog_34830_Content_94 = {
    Text = "Non preoccuparti. Dal momento che ho scelto di essere la signora di questo feudo, devo assumermi la responsabilità per tutti."
  },
  AvgDialog_34830_Content_95 = {
    Text = "Non si tratta forse di morire insieme? Allora moriamo gloriosamente."
  },
  AvgDialog_34830_Content_96 = {
    Text = "Cosa avete intenzione di fare?"
  },
  AvgDialog_34830_Content_97 = {
    Text = "Wanda offre un sorriso enigmatico e vi fa l'occhiolino."
  },
  AvgDialog_34830_Content_98 = {
    Text = "Un magnifico banchetto d'addio."
  },
  AvgDialog_34831_Content_1 = {
    Text = "Finalmente riuscite a divincolarvi dal Piccolo Beckman, solo per vedere l'intera sala mutare."
  },
  AvgDialog_34831_Content_10 = {
    Text = "Se siamo destinati alla tomba, perché non dovremmo congedarci con Gioia?"
  },
  AvgDialog_34831_Content_11 = {
    Text = "O dovremmo rannicchiarci nei nostri letti, piangendo da soli, soddisfacendo tutte le vostre fantasie sui moribondi?"
  },
  AvgDialog_34831_Content_12 = {
    Text = "Te l'ho detto. A Cambrian, la legge sono io."
  },
  AvgDialog_34831_Content_13 = {
    Text = "La regina ordina: Danzate, continuate a danzare! Passato, presente e futuro, non temeremo mai la morte."
  },
  AvgDialog_34831_Content_14 = {
    Text = "Al comando di Wanda—"
  },
  AvgDialog_34831_Content_16 = {
    Text = "L'atmosfera nella sala raggiunge il suo apice."
  },
  AvgDialog_34831_Content_17 = {
    Text = "<Change> Danza, danza..."
  },
  AvgDialog_34831_Content_19 = {
    Text = "Pazzi. Sono tutti completamente impazziti..."
  },
  AvgDialog_34831_Content_2 = {
    Text = "La sala del banchetto un tempo gioiosa si è trasformata in un immenso cimitero, con la D-melma che trasuda come pidocchi sotto un abito lussuoso."
  },
  AvgDialog_34831_Content_20 = {
    Text = "Osservi con sgomento tutto ciò che si dispiega davanti ai tuoi Occhi. Nemmeno nei tuoi deliri febbrili più sfrenati hai mai assistito a una scena così fantasmagorica."
  },
  AvgDialog_34831_Content_21 = {
    Text = "Tutti sono folli. Tutti sono segnati."
  },
  AvgDialog_34831_Content_22 = {
    Text = "Ma tutti sono felici."
  },
  AvgDialog_34831_Content_23 = {Text = "..."},
  AvgDialog_34831_Content_24 = {
    Text = "Va bene, mi arrendo."
  },
  AvgDialog_34831_Content_25 = {
    Text = "Ti strappi il colletto e crolli al suolo, completamente esausto."
  },
  AvgDialog_34831_Content_26 = {
    Text = "Che ironia. Un tempo giurai sulla tomba di Mythag di non temere né la vita né la morte, eppure non sono mai stato davvero pronto ad affrontarla."
  },
  AvgDialog_34831_Content_27 = {
    Text = "Mi hai dato una lezione, Wanda."
  },
  AvgDialog_34831_Content_28 = {
    Text = "Afferri un calice e brindi a Wanda attraverso il mare di icore nero, vino versato e fiori sparsi."
  },
  AvgDialog_34831_Content_29 = {
    Text = "—Alla nostra morte più dolce e più splendida."
  },
  AvgDialog_34831_Content_3 = {
    Text = "No. Troppe persone stanno mutando contemporaneamente..."
  },
  AvgDialog_34831_Content_30 = {
    Text = "Il dolce profumo dei cadaveri in decomposizione ti raggiunge le narici, e odi i lamenti di innumerevoli grida di dolore."
  },
  AvgDialog_34831_Content_31 = {
    Text = "Ma non smettono mai di danzare."
  },
  AvgDialog_34831_Content_32 = {
    Text = "La Regina non abbandona mai il suo popolo. Presto, marceranno insieme verso questo magnifico Festino di morte."
  },
  AvgDialog_34831_Content_34 = {
    Text = "Questa volta, finalmente non è sola."
  },
  AvgDialog_34831_Content_35 = {
    Text = "Riesci ancora a ricordare quella Scrittura Divina? Quella che hai recitato alle porte?"
  },
  AvgDialog_34831_Content_36 = {Text = "..."},
  AvgDialog_34831_Content_37 = {
    Text = "<Red:Indulgere nella lussuria e cedere a Desideri sfrenati sarà punito dal fuoco eterno, come monito.>"
  },
  AvgDialog_34831_Content_38 = {
    Text = "Sei pronto?"
  },
  AvgDialog_34831_Content_39 = {
    Text = "Quando si subisce la punizione del Fuoco Eterno."
  },
  AvgDialog_34831_Content_4 = {
    Text = "Istintivamente volgi lo sguardo verso Wanda."
  },
  AvgDialog_34831_Content_40 = {Text = "..."},
  AvgDialog_34831_Content_41 = {
    Text = "Nell'Oscurità che si addensa, odi soltanto una risata lontana e morente."
  },
  AvgDialog_34831_Content_42 = {
    Text = "Come Frammenti di meteora che cadono in un lago, i suoni sprofondano lentamente negli abissi della tua coscienza."
  },
  AvgDialog_34831_Content_43 = {
    Text = "Finché, alla fine di tutto, non resta che il Silenzio."
  },
  AvgDialog_34831_Content_5 = {
    Text = "In mezzo alla folla vivace e festosa, Wanda sorride e alza il calice verso di te."
  },
  AvgDialog_34831_Content_6 = {
    Text = "Hai già paura, piccolo Monaco?"
  },
  AvgDialog_34831_Content_7 = {
    Text = "Non capisco. Hai intenzione di restare lì a guardare mentre impazziscono e muoiono?"
  },
  AvgDialog_34831_Content_8 = {
    Text = "Wanda rise di cuore, lacrime nere le scorrevano dagli occhi. Solo allora notasti che il suo corpo era coperto di ferite causate dalla Dissoluzione."
  },
  AvgDialog_34831_Content_9 = {
    Text = "Nulla è eterno, piccolo Monaco. Nemmeno gli dèi che veneri."
  },
  AvgDialog_34965_Content_1 = {
    Text = "Dopo aver abbattuto un'altra ondata attirata dal rumore, finalmente hai un attimo di respiro."
  },
  AvgDialog_34965_Content_10 = {
    Text = "Questi fluidi non sono corrosivi, ma alcune precauzioni base sono necessarie — meglio prevenire che curare."
  },
  AvgDialog_34965_Content_11 = {
    Text = "Prima che tu possa fermarla, Ramona strappa un lembo di tessuto dai vestiti del Navigatore, avvolge la punta della sua arma e sonda l'addome del cadavere, rimestando le viscere."
  },
  AvgDialog_34965_Content_12 = {
    Text = "...È sempre stata così?"
  },
  AvgDialog_34965_Content_13 = {
    Text = "Non restare sotto shock — è il suo spirito accademico in azione."
  },
  AvgDialog_34965_Content_14 = {
    Text = "Fatto. Ho reciso i vasi che ancoravano la Specie Parassita."
  },
  AvgDialog_34965_Content_15 = {
    Text = "Con un colpo di punta della spada, la Specie Parassita senza vita rotola fuori, e una fanghiglia torbida si propaga lungo le giunture del ponte in ogni direzione. Il Capitano trascina rapidamente Celeste in un altro punto."
  },
  AvgDialog_34965_Content_16 = {
    Text = "La Specie Parassita somiglia a una massa gelatinosa e tentacolare, eppure da vicino riecheggia un embrione di mammifero. Persino attraverso la pelle, irradia una profonda blasfemia."
  },
  AvgDialog_34965_Content_17 = {
    Text = "Ramona aggrotta la fronte, rinfodera lo stocco e raccoglie la lancia del Navigatore. Incide delicatamente la pelle gelatinosa della Specie Parassita—"
  },
  AvgDialog_34965_Content_18 = {
    Text = "Pus nero sgorga fuori. Murphy lancia un grido e balza indietro di diversi passi."
  },
  AvgDialog_34965_Content_19 = {
    Text = "Cosa? C'è qualcosa lì?"
  },
  AvgDialog_34965_Content_2 = {
    Text = "Perché questi Navigatori hanno tutti il ventre gonfio in quel modo?"
  },
  AvgDialog_34965_Content_20 = {
    Text = "Nero! Liquido nero! Capitano, non lo vedi?"
  },
  AvgDialog_34965_Content_21 = {
    Text = "Tu e Ramona vi scambiate un'occhiata—ciò che sgorga dalla Specie Parassita è inconfondibilmente la vostra \"vecchia amica\": la D-melma."
  },
  AvgDialog_34965_Content_22 = {
    Text = "Questi Navigatori non mostravano alcun segno di infestazione prima dell'esplosione..."
  },
  AvgDialog_34965_Content_23 = {
    Text = "Prima dell'esplosione... prima dell'esplosione... prima che il Dominio svanisse!"
  },
  AvgDialog_34965_Content_24 = {
    Text = "Il Dominio è svanito?! Celeste, non riesci più a sostenere il Dominio?"
  },
  AvgDialog_34965_Content_25 = {
    Text = "Dopo il cenno affermativo del Capitano, Ramona ricompone il quadro."
  },
  AvgDialog_34965_Content_26 = {
    Text = "Si volta con espressione grave verso Murphy, che trascina il Capitano qua e là, schivando la D-melma che scorre."
  },
  AvgDialog_34965_Content_27 = {
    Text = "Il \"dio\" non ancora nato è divenuto il nucleo del Cataclisma, influenzando ogni essere vivente a bordo."
  },
  AvgDialog_34965_Content_28 = {
    Text = "I Navigatori mentalmente fragili e confusi ne hanno subito il peso maggiore — questi parassiti sono probabilmente una forma di D-iperplasia che si manifesta."
  },
  AvgDialog_34965_Content_29 = {Text = "Un modulo?"},
  AvgDialog_34965_Content_3 = {
    Text = "Murphy si avvicina con cautela a un Navigatore sconfitto, con Ramona alle calcagna."
  },
  AvgDialog_34965_Content_30 = {
    Text = "Ti dirigi verso il punto in cui tu e Murphy avete sentito il rumore, e torni al ponte inferiore, lasciando la cabina dove vi eravate nascosti."
  },
  AvgDialog_34965_Content_31 = {
    Text = "La cabina invasa dalla D-iperplasia giace in silenzio, le escrescenze si estendono più selvagge e caotiche di quando l'avete lasciata."
  },
  AvgDialog_34965_Content_4 = {
    Text = "Si scambiano uno sguardo prima di unire le mani per rivoltare il corpo inerte del Navigatore."
  },
  AvgDialog_34965_Content_5 = {
    Text = "L'addome era rigonfiato in modo grottesco dal parassita all'interno, la pelle tesa e sottile fino alla trasparenza, gli organi quasi visibili."
  },
  AvgDialog_34965_Content_6 = {
    Text = "Si muove— si muove!"
  },
  AvgDialog_34965_Content_7 = {
    Text = "La Specie Parassita si contorce sotto gli occhi di tutti, gonfiando l'addome dell'ospite. La pelle tesa perde la sua consistenza —"
  },
  AvgDialog_34965_Content_8 = {Text = "Splat!"},
  AvgDialog_34965_Content_9 = {
    Text = "Il ventre del Navigatore si sgonfia come un palloncino. Il parassita smette di muoversi. Ramona fende il vuoto con la spada, scrollando il sudiciume dalla punta."
  },
  AvgDialog_34966_Content_1 = {
    Text = "Deprecato, in attesa di eliminazione"
  },
  AvgDialog_34967_Content_1 = {Text = "@2..."},
  AvgDialog_34967_Content_10 = {
    Text = "Questa volta entri nel Reame dello Spirito con successo, ma quando provi ad aprire gli occhi per attivare il collegamento, bizzarre immagini sfocate invadono la tua mente come diapositive confuse."
  },
  AvgDialog_34967_Content_11 = {
    Text = "Fissi il vuoto interiore, cercando di resistere alla strana pressione, ma il tuo spirito si schianta violentemente al suolo."
  },
  AvgDialog_34967_Content_12 = {Text = "Ngh...!"},
  AvgDialog_34967_Content_13 = {
    Text = "Ragazzino, ti esce sangue dal naso."
  },
  AvgDialog_34967_Content_14 = {
    Text = "Spaventato, ti volti di scatto per asciugarti il naso con il tessuto sulla spalla. Come previsto, il panno nero è macchiato di sangue scuro."
  },
  AvgDialog_34967_Content_15 = {
    Text = "Sei distrutto—lascia che porti io Murphy."
  },
  AvgDialog_34967_Content_16 = {
    Text = "Scuoti la testa, raccogliendo le forze per sostenere Murphy."
  },
  AvgDialog_34967_Content_17 = {
    Text = "Sto bene, continuiamo."
  },
  AvgDialog_34967_Content_2 = {
    Text = "Una disperazione senza fondo e un'angoscia cieca avvolgono la coscienza di Murphy, intrecciando i suoi mormorii in gabbia dopo gabbia."
  },
  AvgDialog_34967_Content_3 = {Text = "Tu...@1..."},
  AvgDialog_34967_Content_4 = {
    Text = "Stai invocando Tulu?"
  },
  AvgDialog_34967_Content_5 = {Text = "Perché..."},
  AvgDialog_34967_Content_6 = {
    Text = "Le sue mani si serrano involontariamente, il corpo che trema di paura."
  },
  AvgDialog_34967_Content_7 = {
    Text = "Tulu... già, se Tulu fosse qui, saprebbe come svegliarti.\nAnche se non ci riuscisse, almeno potrebbe farti stare meglio..."
  },
  AvgDialog_34967_Content_8 = {
    Text = "Aspetta... il legame. Posso provare a chiamarlo di nuovo attraverso il legame."
  },
  AvgDialog_34967_Content_9 = {
    Text = "Lanci un'occhiata a Ramona, ancora impegnata a respingere i Navigatori, poi inspiri profondamente, chiudendo gli occhi per immergerti nel Reame dello Spirito..."
  },
  AvgDialog_34968_Content_1 = {
    Text = "Protezione da Sovraccarico"
  },
  AvgDialog_34968_Content_10 = {
    Text = "Quando le stelle occuperanno le loro giuste posizioni, i cieli guideranno la rinascita dalla terra di Costui. In quell'ora, anche il Reame Divino ascenderà, e ancora una volta la luce dell'alba cadrà su Lemuria."
  },
  AvgDialog_34968_Content_100 = {
    Text = "Chi va là!"
  },
  AvgDialog_34968_Content_101 = {
    Text = "L'intruso alza una lancia d'osso e fugge — Ramona lo insegue, ma scorge solo una veste nera svanire lungo il corridoio."
  },
  AvgDialog_34968_Content_102 = {Text = "...Caecus."},
  AvgDialog_34968_Content_103 = {
    Text = "Quel ragazzo Risvegliatore non perde il controllo—e nemmeno Golia."
  },
  AvgDialog_34968_Content_104 = {
    Text = "Capitano, lei dice che Caecus è collegato a Miryam... ne è sicuro?"
  },
  AvgDialog_34968_Content_105 = {
    Text = "Per quanto ne so, sì."
  },
  AvgDialog_34968_Content_106 = {
    Text = "Doll, hai sentito?"
  },
  AvgDialog_34968_Content_107 = {
    Text = "Significa che la Somma Sacerdotessa dei Navigatori, Miryam, è ancora attiva."
  },
  AvgDialog_34968_Content_108 = {
    Text = "Quanto al coma del Custode... per tutto l'anno trascorso a Mythag, {Male=non ha mai avuto,Female=non ha mai avuto} improvvisi svenimenti."
  },
  AvgDialog_34968_Content_109 = {
    Text = "Non posso stabilire cosa {Male=gli,Female=le} succeda senza un esame completo."
  },
  AvgDialog_34968_Content_11 = {
    Text = "Questo è il patto tra il divino e questo umile vascello..."
  },
  AvgDialog_34968_Content_110 = {
    Text = "\"La squadra di William ha ripulito i moli; vi stiamo aspettando per il vostro ritorno... Tornate vivi, tutti quanti.\""
  },
  AvgDialog_34968_Content_111 = {
    Text = "\"Nel frattempo, Sona-Nyl, Sala Macchine\""
  },
  AvgDialog_34968_Content_112 = {
    Text = "Le fragili assi del ponte e le strutture d'acciaio non riescono a bloccare le onde di Gnosi—le onde d'urto energetiche spazzano la sala macchine devastata."
  },
  AvgDialog_34968_Content_113 = {
    Text = "Dai rottami carbonizzati e dalle rovine, si muove rigida — come una lupa attirata dall'odore del sangue, o una marionetta priva di pensiero."
  },
  AvgDialog_34968_Content_114 = {
    Text = "Ogni suo movimento guidato da una forza inconoscibile, il volto inespressivo, scosta lentamente le macerie, strisciando fuori dalle rovine."
  },
  AvgDialog_34968_Content_115 = {
    Text = "Nessuno sa quale cupa ossessione e quale potere la spingano—il suo bel volto è imbrattato di sporcizia, gli occhi vuoti e grigi, privi di scintilla, eppure tremolanti di una luce inquietante."
  },
  AvgDialog_34968_Content_116 = {
    Text = "Come terrore che sorge dall'abisso della disperazione."
  },
  AvgDialog_34968_Content_12 = {
    Text = "...No, questo è il nostro patto."
  },
  AvgDialog_34968_Content_13 = {
    Text = "Ora, abbandònati a un Dormiveglia Temporaneo."
  },
  AvgDialog_34968_Content_14 = {
    Text = "Somma Sacerdotessa Miryam."
  },
  AvgDialog_34968_Content_15 = {
    Text = "Inondazioni e onde seguono, sudditi annegati prima di avere la possibilità di dire addio ai propri cari, ridotti in polvere dalla possanza della natura."
  },
  AvgDialog_34968_Content_16 = {
    Text = "Avevamo promesso..."
  },
  AvgDialog_34968_Content_17 = {
    Text = "Non rinuncerò a lei."
  },
  AvgDialog_34968_Content_18 = {
    Text = "Quello è... %player%...?"
  },
  AvgDialog_34968_Content_19 = {
    Text = "Murphy si rialza a fatica, stordita, guardandosi intorno."
  },
  AvgDialog_34968_Content_2 = {
    Text = "La testa... mi fa male..."
  },
  AvgDialog_34968_Content_20 = {
    Text = "Il suo gruppo familiare si stringe lì vicino, mormorando. Alla sua voce, tutti si voltano."
  },
  AvgDialog_34968_Content_21 = {
    Text = "Murphy! Come ti senti adesso?"
  },
  AvgDialog_34968_Content_22 = {
    Text = "La sua visuale si schiarisce gradualmente. Murphy si strofina gli occhi, scorgendo %player% al centro del cerchio, immerso in un sonno profondo."
  },
  AvgDialog_34968_Content_23 = {
    Text = "C-cosa {Male=gli,Female=le} è successo?"
  },
  AvgDialog_34968_Content_24 = {
    Text = "Non saprei... non ci sono ferite evidenti—non {Male=avrebbe dovuto,Female=avrebbe dovuto} svenire così."
  },
  AvgDialog_34968_Content_25 = {
    Text = "Il nostro legame è stabile... innaturalmente stabile."
  },
  AvgDialog_34968_Content_26 = {
    Text = "Abbiamo fatto un controllo di routine prima di partire—%player% stava bene allora..."
  },
  AvgDialog_34968_Content_27 = {
    Text = "Murphy, hai notato segni anomali mentre eri con %player%?"
  },
  AvgDialog_34968_Content_28 = {
    Text = "Da dopo l'esplosione, prima di trovarti? Fammi pensare..."
  },
  AvgDialog_34968_Content_29 = {
    Text = "E-Ehi?! Non spaventarmi—non morirmi tra le braccia!"
  },
  AvgDialog_34968_Content_3 = {
    Text = "Dove... sono? %player%? Dove sei?"
  },
  AvgDialog_34968_Content_30 = {
    Text = "Io... sto bene..."
  },
  AvgDialog_34968_Content_31 = {
    Text = "Svegliati, %player%, forza, riprenditi!"
  },
  AvgDialog_34968_Content_32 = {
    Text = "Non... non spaventarmi così... Alzati, su!"
  },
  AvgDialog_34968_Content_33 = {
    Text = "Almeno due volte... la prima quando ha provato quel trucco di tracciamento per trovare le persone, poi quando è {Male=crollato,Female=crollata}—ma si è {Male=ripreso,Female=ripresa} in fretta."
  },
  AvgDialog_34968_Content_34 = {
    Text = "Starà... {Male=lui,Female=lei} bene?"
  },
  AvgDialog_34968_Content_35 = {
    Text = "Ramona guarda il suo compagno—%player% giace sereno accanto a lei, sprofondato in un coma, il volto arrossato e calmo, come se {Male=stesse,Female=stesse} assaporando un dolce sogno."
  },
  AvgDialog_34968_Content_36 = {
    Text = "Un'emozione difficile da definire le cresce dentro, lo sguardo indugia su quel volto sereno mentre il mondo ammutolisce."
  },
  AvgDialog_34968_Content_37 = {
    Text = "Io... non lo so...\nForse qualcuno a scuola può aiutare, ma..."
  },
  AvgDialog_34968_Content_38 = {
    Text = "Vuoi contattare la tua scuola? Magari provare la radio..."
  },
  AvgDialog_34968_Content_39 = {
    Text = "Il Capitano inghiotte il resto."
  },
  AvgDialog_34968_Content_4 = {
    Text = "Non riceve risposta — il flusso incessante dell'acqua riecheggia nel buio profondo."
  },
  AvgDialog_34968_Content_40 = {
    Text = "La radio è in plancia—e tornare indietro adesso è un suicidio."
  },
  AvgDialog_34968_Content_41 = {
    Text = "Ah, giusto! Voi avete quei comunicatori magici, no?"
  },
  AvgDialog_34968_Content_42 = {
    Text = "Gli occhi di Ramona si illuminano. Si rimprovera in silenzio per il panico, e preme il comunicatore sul distintivo della scuola."
  },
  AvgDialog_34968_Content_43 = {
    Text = "Sfrigolio—sfrigolio sfrigolio—"
  },
  AvgDialog_34968_Content_44 = {
    Text = "Ramo... *&..."
  },
  AvgDialog_34968_Content_45 = {
    Text = "Doll?! Sei tu!?"
  },
  AvgDialog_34968_Content_46 = {
    Text = "Cus... %#... nave**...?"
  },
  AvgDialog_34968_Content_47 = {
    Text = "Non ti sento. Siamo troppo lontani dalla terraferma—oltre la portata del comunicatore."
  },
  AvgDialog_34968_Content_48 = {
    Text = "Aspetta, forse posso amplificare il segnale per un momento."
  },
  AvgDialog_34968_Content_49 = {
    Text = "Ramona si strappa la spilla, forzando l'involucro del comunicatore con un ago che porta sempre con sé."
  },
  AvgDialog_34968_Content_5 = {
    Text = "Acqua, acqua senza fine."
  },
  AvgDialog_34968_Content_50 = {
    Text = "Dove... hai preso quell'ago?"
  },
  AvgDialog_34968_Content_51 = {
    Text = "Meglio prevenire che curare—prepara sempre più del necessario."
  },
  AvgDialog_34968_Content_52 = {
    Text = "Ramona armeggia con i componenti interni. Non passa molto prima che usi il semplice ago per bypassare l'ultimo strato di sicurezza del nucleo energetico del comunicatore."
  },
  AvgDialog_34968_Content_53 = {
    Text = "Una massa di Argento in silenzioso fermento appare davanti a tutti."
  },
  AvgDialog_34968_Content_54 = {
    Text = "Argento... quindi i Nuclei d'Argento al di sotto della soglia di risveglio della Gnosi vengono trasformati in strumenti?"
  },
  AvgDialog_34968_Content_55 = {
    Text = "Lascia i tecnicismi, e il dibattito etico, per quando saremo tornati a scuola."
  },
  AvgDialog_34968_Content_56 = {
    Text = "Ora metterò in cortocircuito il nucleo—un'ondata massiccia di fluttuazione di Gnosi dovrebbe amplificare temporaneamente il comunicatore."
  },
  AvgDialog_34968_Content_57 = {
    Text = "Solo in teoria, però... Dammi un po' di tempo. Ci provo."
  },
  AvgDialog_34968_Content_58 = {
    Text = "Due minuti dopo"
  },
  AvgDialog_34968_Content_59 = {
    Text = "Murphy, tieni questa parte, vuoi?"
  },
  AvgDialog_34968_Content_6 = {
    Text = "Onde nere si ergono più alte delle vette più elevate di Elworth. Si abbattono dritte sulla città, spazzando via storia e futuro, sommergendoli..."
  },
  AvgDialog_34968_Content_60 = {
    Text = "A cosa serve?"
  },
  AvgDialog_34968_Content_61 = {
    Text = "È uno Stabilizzatore per l'Argento. Rimuovilo, e il nucleo attivato mi permetterà di cortocircuitarlo."
  },
  AvgDialog_34968_Content_62 = {
    Text = "Tienilo fermo—devo reinstallarlo dopo. Senza, il nucleo non può raffreddarsi—potrebbe esplodere."
  },
  AvgDialog_34968_Content_63 = {Text = "Eek?!"},
  AvgDialog_34968_Content_64 = {
    Text = "Un minuto dopo"
  },
  AvgDialog_34968_Content_65 = {
    Text = "Ramona riorganizza le viscere del Comunicatore—ingranaggi e cavi misteriosi, tutti estratti e ricombinati."
  },
  AvgDialog_34968_Content_66 = {Text = "Fatto!"},
  AvgDialog_34968_Content_67 = {
    Text = "Murphy si accovaccia accanto a lei, reggendo timidamente il pezzo, ma sbircia comunque con curiosità."
  },
  AvgDialog_34968_Content_68 = {Text = "Tutto qui?"},
  AvgDialog_34968_Content_69 = {
    Text = "Un ultimo passaggio—tutti, chiudete gli occhi, non guardate da questa parte."
  },
  AvgDialog_34968_Content_7 = {
    Text = "Questa è la Vostra Profezia divina—nessuno può contestarla."
  },
  AvgDialog_34968_Content_70 = {
    Text = "Ramona copre gli occhi di Murphy con la mano."
  },
  AvgDialog_34968_Content_71 = {
    Text = "Un bagliore bianco accecante esplode dal Comunicatore, propagandosi verso l'esterno come un fulmine nel cielo, sbiancando la stiva di un pallore spettrale."
  },
  AvgDialog_34968_Content_72 = {
    Text = "L'energia si riversa come onde che si infrangono, propagandosi all'istante."
  },
  AvgDialog_34968_Content_73 = {
    Text = "La fluttuazione vibra, come tonalità stellari dalle profondità dello spazio; il Comunicatore risplende misteriosamente, come se collegasse galassie lontane."
  },
  AvgDialog_34968_Content_74 = {
    Text = "Ramona? Mi senti?"
  },
  AvgDialog_34968_Content_75 = {
    Text = "Non sono mai stata così felice di sentirti..."
  },
  AvgDialog_34968_Content_76 = {
    Text = "Per stabilizzare le comunicazioni, ho bruciato venti volte la dose giornaliera di Argento. Presto, qual è la vostra situazione? Come stanno tutti?"
  },
  AvgDialog_34968_Content_77 = {
    Text = "Ramona aggiorna Doll sugli eventi della nave: il rito della Discesa, il culto del Navigatore, Murphy, il coma del Custode..."
  },
  AvgDialog_34968_Content_78 = {
    Text = "Mi serviranno i risultati del laboratorio di Francis per fermare la crescita del \"dio\"... capito. Riportate quella ragazza—Winkle e io prepareremo la stanza."
  },
  AvgDialog_34968_Content_79 = {
    Text = "Winkle, hai due ore per potenziare le contromisure anti-segugio."
  },
  AvgDialog_34968_Content_8 = {
    Text = "Di chi... è quella Voce...?"
  },
  AvgDialog_34968_Content_80 = {
    Text = "L'esperimento è instabile, instabile... devo fare qualcosa adesso—immediatamente! O perderemo il controllo, e lo perderemo!"
  },
  AvgDialog_34968_Content_81 = {
    Text = "Erica, porta via Winkle."
  },
  AvgDialog_34968_Content_82 = {Text = "..."},
  AvgDialog_34968_Content_83 = {
    Text = "Erica ha trovato dati sul Navigatore nell'Archivio—non farti troppe illusioni, è solo un frammento."
  },
  AvgDialog_34968_Content_84 = {
    Text = "Epoca del Diluvio, avvistamenti di nuovi continenti segnalati: Un gruppo di rifugiati \"brutti, simili a pesci\" guadò i mari, scomparendo nelle inondazioni."
  },
  AvgDialog_34968_Content_85 = {
    Text = "Sostenevano di essere gli eredi di un'antica civiltà, con il sangue donato da \"Dio\" che scorreva nelle loro vene."
  },
  AvgDialog_34968_Content_86 = {
    Text = "Queste persone nacquero come esseri umani, ma il sangue divino li trasformò gradualmente in ciò che vedete ora."
  },
  AvgDialog_34968_Content_87 = {
    Text = "Quindi anche quel ragazzo finirà per diventare come un pesce..."
  },
  AvgDialog_34968_Content_88 = {
    Text = "Intendi Caecus? Se vuoi sapere di lui, posso raccontarti."
  },
  AvgDialog_34968_Content_89 = {
    Text = "Ramona annuisce, esortando il Capitano a proseguire."
  },
  AvgDialog_34968_Content_9 = {
    Text = "O, il più fedele devoto del reame divino, la mia eternità, il futuro del regno... lo affido a te."
  },
  AvgDialog_34968_Content_90 = {
    Text = "\"Caecus... quel ragazzo è un Golem anche lui—un Risvegliatore nei vostri termini. Legato a Miryam, probabilmente.\""
  },
  AvgDialog_34968_Content_91 = {
    Text = "Collegata a Miryam?! Un Risvegliato che si collega a un altro—è cosa inaudita..."
  },
  AvgDialog_34968_Content_92 = {
    Text = "Ha, quella donna è un mostro in tutto e per tutto."
  },
  AvgDialog_34968_Content_93 = {
    Text = "Il culto distribuisce stabilizzatori per mantenere la mia mente salda. Dopo che l'ultimo contatto è impazzito, Caecus è diventato il nuovo corriere."
  },
  AvgDialog_34968_Content_94 = {
    Text = "In quegli anni ci vedevamo ogni tre mesi... Gli ho insegnato a bere, a pescare, a individuare la stella del mattino d'estate, a staccare le squame secche d'inverno..."
  },
  AvgDialog_34968_Content_95 = {
    Text = "Haha... pensavo fossimo amici. Così quando mi manda un messaggio per un'ultima consegna, non esito."
  },
  AvgDialog_34968_Content_96 = {
    Text = "Ma... lui rivela la posizione della Sona-Nyl al culto."
  },
  AvgDialog_34968_Content_97 = {
    Text = "Nessuno gli ha mai insegnato a distinguere il bene dal male — non ha mai trovato un senso al di fuori dei Navigatori."
  },
  AvgDialog_34968_Content_98 = {
    Text = "Se tradirmi gli garantisce un posto nel culto... non gliene farò una colpa."
  },
  AvgDialog_34968_Content_99 = {
    Text = "Un clangore metallico risuona all'improvviso — Ramona scatta in postura di combattimento, facendo scudo al Capitano e a Murphy."
  },
  AvgDialog_34969_Content_1 = {
    Text = "La nave geme di nuovo, un lamento di Scricchiolio riecheggia mentre sbanda come un vascello in balia della tempesta. Lo scafo oscilla in modo erratico, detriti metallici tintinnano sul pavimento."
  },
  AvgDialog_34969_Content_10 = {
    Text = "No, grazie — non ho intenzione di farmi trascinare in giro da qualcuno che è ferito."
  },
  AvgDialog_34969_Content_11 = {
    Text = "Ti scruta da capo a piedi, poi distoglie lo sguardo, leggermente arrossita."
  },
  AvgDialog_34969_Content_12 = {
    Text = "Ma... grazie."
  },
  AvgDialog_34969_Content_13 = {
    Text = "Cos'era quello scuotimento? Celeste non ci avrà mica trascinati in qualche corrente...?"
  },
  AvgDialog_34969_Content_14 = {
    Text = [[
Credo che... Celeste stia perdendo il controllo sulla Sona-Nyl.
Trasportarci via da quell'esplosione deve averla sfinita.]]
  },
  AvgDialog_34969_Content_15 = {
    Text = "Era già debole, e adesso..."
  },
  AvgDialog_34969_Content_16 = {
    Text = "Murphy si preme il petto, forzando un sorriso impacciato."
  },
  AvgDialog_34969_Content_17 = {
    Text = "Va tutto bene. Abbiamo raggiunto la riva, siamo al sicuro..."
  },
  AvgDialog_34969_Content_18 = {
    Text = "Le luci tremolano al ritmo del vostro respiro. Mentre la stanza si oscura, dei nemici emergono dalle ombre..."
  },
  AvgDialog_34969_Content_2 = {Text = "Eek?!"},
  AvgDialog_34969_Content_3 = {
    Text = "Uno schiocco Grottesco, come ossa che si spezzano, riverbera da qualche parte. Prima che tu o Murphy possiate reagire, la nave ha un'Ondata, inclinandosi violentemente su un lato."
  },
  AvgDialog_34969_Content_4 = {Text = "Murphy!"},
  AvgDialog_34969_Content_5 = {
    Text = "Afferri un tubo metallico sporgente per tenerti in equilibrio, allungando la mano verso Murphy, ma lei è già inciampata fino all'estremità opposta della sala macchine."
  },
  AvgDialog_34969_Content_6 = {
    Text = "Sto bene! Non urlare come se stessi per tirare le cuoia!"
  },
  AvgDialog_34969_Content_7 = {
    Text = "La cabina si stabilizza, lasciando solo rottami sparsi come testimonianza della violenta scossa."
  },
  AvgDialog_34969_Content_8 = {
    Text = "Murphy, ancora scossa, si sostiene contro la paratia, le gambe tremanti mentre si avvicina."
  },
  AvgDialog_34969_Content_9 = {
    Text = "Hai urtato qualcosa? Ti serve aiuto?"
  },
  AvgDialog_34970_Content_1 = {
    Text = "Prima tu... io ti copro le spalle!"
  },
  AvgDialog_34970_Content_10 = {
    Text = "Cos'è questo...?"
  },
  AvgDialog_34970_Content_11 = {
    Text = "Ti avvicini a un corallo, il cui splendore è aggraziato e incantevole. Alle aste di Londinium, un pezzo simile frutterebbe migliaia di Fiorini Leoniani."
  },
  AvgDialog_34970_Content_12 = {
    Text = "—Se non fosse per le radici che affondano in profondità in un piccolo D-segno."
  },
  AvgDialog_34970_Content_13 = {
    Text = "È la D-iperplasia."
  },
  AvgDialog_34970_Content_14 = {
    Text = "In <Italic:Fondamenti dei Fenomeni di Dissoluzione>, Doll spiegava la D-iperplasia: a un certo punto, i D-segni potrebbero germogliare Dissoluzione."
  },
  AvgDialog_34970_Content_15 = {
    Text = "Non esiste uno schema su quando o di che tipo, ma una cosa è certa: la D-iperplasia appare solo dove si annida un Cataclisma."
  },
  AvgDialog_34970_Content_16 = {
    Text = "Queste urlano oceano. Un Cataclisma legato al Reame di Aequor è vicino."
  },
  AvgDialog_34970_Content_17 = {
    Text = "Un Cataclisma..."
  },
  AvgDialog_34970_Content_18 = {
    Text = "Murphy si avvicina a te, fissando il D-segno sotto il corallo. Con una mano sul petto, l'altra sfiora la superficie ruvida del corallo."
  },
  AvgDialog_34970_Content_19 = {
    Text = "Alle tue spalle, un forte tonfo. Voltandoti, incroci lo sguardo di un Navigatore intrappolato dalla D-iperplasia."
  },
  AvgDialog_34970_Content_2 = {
    Text = "Senza discutere, Murphy sguscia dietro la porta che stai trattenendo."
  },
  AvgDialog_34970_Content_20 = {
    Text = "Gorgoglio..."
  },
  AvgDialog_34970_Content_21 = {
    Text = "Murphy ammutolisce, senza reagire. Ti fai avanti, frapponendoti tra lei e il Navigatore."
  },
  AvgDialog_34970_Content_3 = {
    Text = "Mutanti e creature del mare, attratti dal vostro odore, si precipitano dentro. Artigli sfiorano il tuo mantello mentre ti infili oltre."
  },
  AvgDialog_34970_Content_4 = {
    Text = "Ti schianti contro la porta mentre Murphy la sbarra. La porta blocca odore e vista, e gli stridi di metallo graffiato presto si spengono."
  },
  AvgDialog_34970_Content_5 = {
    Text = "Huff, huff... Non si arrendono mai."
  },
  AvgDialog_34970_Content_6 = {
    Text = "Murphy, accendi la luce... eh?!"
  },
  AvgDialog_34970_Content_7 = {
    Text = "Un bagliore sinistro ti colpisce gli Occhi."
  },
  AvgDialog_34970_Content_8 = {
    Text = "Escrescenze ramificate erompono dalle crepe del ponte, contorcendosi e spingendo per farsi spazio. Con schiocchi costanti, il pavimento cede sotto di loro."
  },
  AvgDialog_34970_Content_9 = {
    Text = "Coralli, anemoni e creature marine senza nome, spesse e forti, forzano il ponte a separarsi centimetro dopo centimetro."
  },
  AvgDialog_34971_Content_1 = {
    Text = "Con Murphy sulle spalle, fuggite dal ponte insieme a Elton e Celeste, con Ramona alle calcagna."
  },
  AvgDialog_34971_Content_10 = {
    Text = "Golia, perché?"
  },
  AvgDialog_34971_Content_11 = {
    Text = "Perché cosa?"
  },
  AvgDialog_34971_Content_12 = {
    Text = "Hai sfidato Miryam apertamente, lasciandoci scappare più volte..."
  },
  AvgDialog_34971_Content_13 = {
    Text = "Non negarlo—è fin troppo evidente."
  },
  AvgDialog_34971_Content_14 = {
    Text = "Lo so che nella sala macchine hai provocato Miryam di proposito — non volevi uno scontro diretto con noi, o meglio... con Tulu."
  },
  AvgDialog_34971_Content_15 = {
    Text = "Al solo nominare Tulu il cervello torna a pulsare di dolore — quel Pain senza causa, come raffiche di mezzanotte che devastano la tua sanità, bruciando nervi e volontà."
  },
  AvgDialog_34971_Content_16 = {Text = "Ugh..."},
  AvgDialog_34971_Content_17 = {
    Text = "La familiare sensazione di cedimento ti travolge. È un Pain che affonda nell'anima, come ferite quasi rimarginate che vengono strappate e ricucite."
  },
  AvgDialog_34971_Content_18 = {
    Text = "Custode? Custode?"
  },
  AvgDialog_34971_Content_19 = {
    Text = "Ramona sembra percepire il tuo malessere: tiene d'occhio Golia mentre ti sfiora delicatamente il braccio che sorregge Murphy."
  },
  AvgDialog_34971_Content_2 = {
    Text = "Proprio mentre stai per scendere le scale, il gigante balza giù dall'alto."
  },
  AvgDialog_34971_Content_20 = {Text = "Sto bene."},
  AvgDialog_34971_Content_21 = {
    Text = "Sussurri in risposta alla premura di Ramona. Inspiri a fondo, e lasci che l'aria salmastra del mare ricacci giù il sapore di sangue che ti sale nel naso."
  },
  AvgDialog_34971_Content_22 = {
    Text = "Poi alzi di nuovo lo sguardo verso Golia. Ti osserva divertito, come se i tuoi spasmi di dolore lo intrattenessero, un ghigno compiaciuto e selvaggio stampato in volto."
  },
  AvgDialog_34971_Content_23 = {
    Text = "È evidente... non sei del tutto leale ai Navigatori, schernisci la loro fede, il loro dio..."
  },
  AvgDialog_34971_Content_24 = {
    Text = "Miryam è stata sconfitta—non c'è più motivo di ostilità tra noi.\nPerché... perché questa ossessione improvvisa per Murphy?"
  },
  AvgDialog_34971_Content_25 = {
    Text = "Se vuoi morire sapendo il perché, usa quel cervello fino che hai e ragionaci da solo."
  },
  AvgDialog_34971_Content_26 = {
    Text = "La somma sacerdotessa è Martire, i Navigatori senza guida..."
  },
  AvgDialog_34971_Content_27 = {
    Text = "Che io forgi un nuovo impero o conduca questi stolti verso l'eternità... cosa dovrei fare?"
  },
  AvgDialog_34971_Content_28 = {
    Text = "Per impossessarsi del Potere."
  },
  AvgDialog_34971_Content_29 = {
    Text = "Vuoi guidare i Navigatori e diventare l'unico nuovo capo del culto."
  },
  AvgDialog_34971_Content_3 = {Text = "Attento!"},
  AvgDialog_34971_Content_30 = {
    Text = "Per quello... ti serve la \"Madre Divina\", per completare il rito e solidificare la tua posizione..."
  },
  AvgDialog_34971_Content_31 = {
    Text = "Cuccioli universitari, ma abbastanza svegli."
  },
  AvgDialog_34971_Content_32 = {
    Text = "Consegnami Murphy.\nFallo in fretta, e quando le mie legioni schiacceranno la civiltà umana, non te la renderò difficile."
  },
  AvgDialog_34971_Content_33 = {
    Text = "Non preoccuparti."
  },
  AvgDialog_34971_Content_34 = {
    Text = "Io, ehm... non ti ho mai chiesto il nome..."
  },
  AvgDialog_34971_Content_35 = {
    Text = "Da piccoli, lo spalmavano su ogni graffio o livido."
  },
  AvgDialog_34971_Content_36 = {
    Text = "Allora? Ti senti già meglio, vero?"
  },
  AvgDialog_34971_Content_37 = {
    Text = "Il peso della ragazza grava su di te — schiena, braccia, gambe, tutto trema in modo incontrollabile."
  },
  AvgDialog_34971_Content_38 = {
    Text = "Avevamo promesso di riportarla indietro, di aiutarla a liberarsi di quel \"dio\" parassita."
  },
  AvgDialog_34971_Content_39 = {
    Text = "Stringi i denti, raccogliendo le forze per sostenere il peso della sua anima."
  },
  AvgDialog_34971_Content_4 = {
    Text = "Ramona ti sfreccia davanti."
  },
  AvgDialog_34971_Content_40 = {
    Text = "Non rinuncerò a lei."
  },
  AvgDialog_34971_Content_41 = {
    Text = "Un ronzio esplode nelle tue orecchie, flauti caotici che fischiano attraverso il brusio."
  },
  AvgDialog_34971_Content_42 = {
    Text = "Questa assurda sinfonia fa fremere le tue palpebre, il cervello invaso da inquietudine e disordine."
  },
  AvgDialog_34971_Content_43 = {
    Text = "Avverti una strana fatica — una fatica familiare, una fatica senza precedenti. I nervi si intorpidiscono gradualmente, gli arti si fanno molli e deboli."
  },
  AvgDialog_34971_Content_44 = {
    Text = "Il mondo davanti a te si oscura a ondate, pesanti cortine calano silenziosamente sulla tua realtà. Rumore e caos si ritirano, flauti silenziosi come piume invisibili sfiorano la tua mente."
  },
  AvgDialog_34971_Content_45 = {
    Text = "Non riesco a dormire... non riesco ad assopirmi."
  },
  AvgDialog_34971_Content_46 = {
    Text = "Lotti contro l'inspiegabile sonnolenza, ma invano. La voce di Ramona svanisce rapidamente. Prima di afferrare cosa stia accadendo, crolli pesantemente a terra."
  },
  AvgDialog_34971_Content_47 = {Text = "Tu..."},
  AvgDialog_34971_Content_49 = {
    Text = "Il tuo cervello fatica a elaborare ciò che sta accadendo, ma una cosa è certa: i tentacoli verde alga bloccano la lama del gigante, e probabilmente risultano morbidi come polpa d'arancia."
  },
  AvgDialog_34971_Content_5 = {
    Text = "Ammiro chi ha il fegato di reagire, ma detesto ancora di più gli idioti ostinati."
  },
  AvgDialog_34971_Content_7 = {
    Text = "Golia spezza le scale di ferro corroso e ti sbarra la strada con la sua enorme mannaia."
  },
  AvgDialog_34971_Content_8 = {
    Text = "Studenti del Mythag... Hah, così ingenui."
  },
  AvgDialog_34971_Content_9 = {
    Text = "Credi davvero di poter fuggire? Con questa nave sgangherata, questo Golem a malapena intatto, e la sua Connettore?"
  },
  AvgDialog_34972_Content_1 = {
    Text = "Falena Cacciatrice di Fiamme"
  },
  AvgDialog_34972_Content_10 = {
    Text = "Caecus china il capo, lanciando un'occhiata alla pinna caudale bruciata dalle fiamme, in silenzio."
  },
  AvgDialog_34972_Content_11 = {
    Text = "Quanto alla nostra cara somma sacerdotessa..."
  },
  AvgDialog_34972_Content_12 = {
    Text = "Lo sguardo di Golia scorre audacemente su tutti voi, soffermandosi su Celeste e il capitano."
  },
  AvgDialog_34972_Content_13 = {
    Text = "Dubito che l'abbiano gentilmente salvata dal cuore dell'esplosione... ho ragione, voi?"
  },
  AvgDialog_34972_Content_14 = {Text = "..."},
  AvgDialog_34972_Content_15 = {
    Text = "Avanti, Caecus.\nMostrami il tuo valore—dimostra di essere degno delle mie schiere."
  },
  AvgDialog_34972_Content_16 = {Text = "..."},
  AvgDialog_34972_Content_17 = {
    Text = "Sì, Lord Golia."
  },
  AvgDialog_34972_Content_18 = {
    Text = "Caecus, che stai facendo!"
  },
  AvgDialog_34972_Content_19 = {
    Text = [[
Caecus guarda il capitano, esitante.
Dopo qualche momento di silenzio, trae un respiro profondo, come se si fosse deciso.]]
  },
  AvgDialog_34972_Content_2 = {
    Text = "Golia si china per entrare nella plancia, la sua mole immensa sigilla quasi del tutto quel lato della porta."
  },
  AvgDialog_34972_Content_20 = {
    Text = "Mi perdoni, signor Elton."
  },
  AvgDialog_34972_Content_21 = {
    Text = "Brandisce la sua arma, colpendo la parete della cabina."
  },
  AvgDialog_34972_Content_22 = {
    Text = "Il metallo vibra con un'eco massiccia, come un furore che ruggisce da un abisso intrappolato—assordante persino per chi ha sferrato il colpo."
  },
  AvgDialog_34972_Content_23 = {
    Text = "Navigatori! L'Allineamento Stellare è vicino!"
  },
  AvgDialog_34972_Content_24 = {
    Text = "In nome di Lord Golia, strappate la Madre Divina a questi stolti! Il rituale deve procedere stanotte!"
  },
  AvgDialog_34972_Content_3 = {
    Text = "Sei più acuto di quegli osservatori del cielo. Quasi mi fa esitare a concederti il pieno potere degli abissi."
  },
  AvgDialog_34972_Content_4 = {
    Text = "Tenerti in questo stato mezzo umano, mezzo pesce sembra più utile."
  },
  AvgDialog_34972_Content_5 = {
    Text = "Mio signore! Il Vecchio Sommo Sacerdote mi ha promesso una forma completa..."
  },
  AvgDialog_34972_Content_6 = {
    Text = "Il respiro del giovane Navigatore si arresta: i suoi occhi da pesce si spalancano, tesi, fissi su Golia."
  },
  AvgDialog_34972_Content_7 = {
    Text = "Somma Sacerdotessa? Tsk..."
  },
  AvgDialog_34972_Content_8 = {
    Text = "Golia ignora lo sguardo del ragazzo—o meglio, il meschino zelo del moccioso non merita la sua attenzione."
  },
  AvgDialog_34972_Content_9 = {
    Text = "Eri nell'esplosione della sala macchine—entrambi abbiamo assistito a quella potenza. Senza di me, saresti polvere d'Argento ormai."
  },
  AvgDialog_34973_Content_1 = {
    Text = "Sotto la Copertura di Ramona, sali le scale. Elton ti aiuta a sostenere il peso di Murphy—ciononostante, raggiungere il ponte al quarto piano richiede uno sforzo notevole."
  },
  AvgDialog_34973_Content_10 = {
    Text = "Custode, puoi entrare."
  },
  AvgDialog_34973_Content_11 = {
    Text = "Annuisci. Con l'aiuto di Ramona, adagi Murphy a terra."
  },
  AvgDialog_34973_Content_12 = {
    Text = "Il suo respiro si stabilizza un po'. Non sembra più così affannoso come prima."
  },
  AvgDialog_34973_Content_13 = {
    Text = "Sembra che il suo corpo si sia adattato temporaneamente al consumo di ossigeno del parassita. Ma se dura troppo a lungo, temo che possa causare danni permanenti."
  },
  AvgDialog_34973_Content_14 = {
    Text = "Sì, dobbiamo portarla fuori in fretta."
  },
  AvgDialog_34973_Content_15 = {
    Text = "Capitano, com'è la plancia?"
  },
  AvgDialog_34973_Content_16 = {
    Text = "Alcune apparecchiature sono rotte—la sirena e gli interruttori della radio sono bloccati. Ma i controlli principali di Potere e il timone funzionano."
  },
  AvgDialog_34973_Content_17 = {
    Text = "Elton parla mentre gira abilmente la ruota centrale, tirando i pistoni uno a uno."
  },
  AvgDialog_34973_Content_18 = {
    Text = "Sporgi la testa dalla Schiusa, scrutando il lato opposto del ponte—camini simili a sfiatatoi emettono sottile fumo bianco. Poco dopo, rumori di acqua che scroscia giungono dalla poppa."
  },
  AvgDialog_34973_Content_19 = {
    Text = "È il timone che funziona, giusto? Stiamo virando."
  },
  AvgDialog_34973_Content_2 = {
    Text = "Huff, huff... finalmente qui."
  },
  AvgDialog_34973_Content_20 = {
    Text = "Elton annuisce, lasciando uscire un profondo respiro."
  },
  AvgDialog_34973_Content_21 = {
    Text = "La Sona-Nyl è una nave grande—vira lenta e goffa, ma una volta impostata la rotta, possiamo andare a tutta velocità."
  },
  AvgDialog_34973_Content_22 = {
    Text = "Come sta Murphy?"
  },
  AvgDialog_34973_Content_23 = {
    Text = "Per ora non peggiora, ma la Specie Parassita le sta comprimendo il cuore, alterando il flusso del Sangue..."
  },
  AvgDialog_34973_Content_24 = {
    Text = "E quella Specie Parassita è la fonte della Dissoluzione Catastrofica del Mondo—essere così vicini al <Yellow:\"nucleo del Cataclisma\">, temo che la Dissoluzione possa colpire anche Murphy..."
  },
  AvgDialog_34973_Content_25 = {
    Text = "Dissoluzione... ancora una volta."
  },
  AvgDialog_34973_Content_26 = {
    Text = "Quella maledetta cosa—quanto altro ancora Ruberà al mio mondo...!"
  },
  AvgDialog_34973_Content_27 = {
    Text = "Capitano, ricordate altre cose perdute a causa della Dissoluzione?"
  },
  AvgDialog_34973_Content_28 = {
    Text = "Elton chiude gli occhi, la pipa che scricchiola mentre la stringe tra i denti, e inspira profondamente alcune volte, placando il proprio tumulto."
  },
  AvgDialog_34973_Content_29 = {
    Text = "La silenziosa Risvegliatrice lancia un'occhiata a Elton, avanzando lentamente davanti a lui, tendendo le mani ormai semitrasparenti."
  },
  AvgDialog_34973_Content_3 = {
    Text = "Elton annuisce, pesca le chiavi dallo zaino, e insieme a Ramona forza la porta del ponte."
  },
  AvgDialog_34973_Content_30 = {
    Text = "Celeste... ti ha colpita? Scusa, terrò a freno il mio temperamento."
  },
  AvgDialog_34973_Content_31 = {
    Text = "Vi guarda, te e Ramona, con un tono più morbido."
  },
  AvgDialog_34973_Content_32 = {
    Text = "Dissoluzione... ho una lunga storia con essa."
  },
  AvgDialog_34973_Content_33 = {
    Text = "Il mio passato... l'ho perduto nella putrefazione."
  },
  AvgDialog_34973_Content_4 = {
    Text = "Dannazione! Questi coralli sono arrivati fin qui!"
  },
  AvgDialog_34973_Content_5 = {
    Text = "Capitano, aspetta—!"
  },
  AvgDialog_34973_Content_6 = {
    Text = "Elton si lancia dentro il ponte, con Ramona alle calcagna."
  },
  AvgDialog_34973_Content_7 = {
    Text = "Il ponte è più grande del previsto, con un raro layout su due livelli—è più imponente di qualsiasi ponte tu abbia mai visto in foto."
  },
  AvgDialog_34973_Content_8 = {
    Text = "Puoi immaginare che la Sona-Nyl fosse uno splendente Paradise sul mare, prima della sua conversione in nave da carico."
  },
  AvgDialog_34973_Content_9 = {
    Text = "Huff... per fortuna il Capitano l'ha Bloccato. A parte la D-iperplasia, nessun mutante o Navigatore è riuscito a entrare."
  },
  AvgDialog_34974_Content_1 = {Text = "Parassita"},
  AvgDialog_34974_Content_10 = {
    Text = "Un'esplosione del genere può farti fischiare le orecchie per giorni."
  },
  AvgDialog_34974_Content_11 = {
    Text = "Sì, almeno i timpani sembrano ancora intatti."
  },
  AvgDialog_34974_Content_12 = {
    Text = "Custode, come stai— aspetta..."
  },
  AvgDialog_34974_Content_13 = {
    Text = "Io... non sono riuscita ad afferrare la mano del Custode... {Male=Lui,Female=Lei}... {Male=lui,Female=lei}..."
  },
  AvgDialog_34974_Content_14 = {
    Text = "Piano, ora. Il Dominio della Sona-Nyl copre anche le acque circostanti — Celeste non se {Male=lo,Female=la} sarebbe lasciata sfuggire."
  },
  AvgDialog_34974_Content_15 = {
    Text = "Celeste batte le palpebre, come a confermare le parole del Capitano."
  },
  AvgDialog_34974_Content_16 = {
    Text = "Ma il nostro Legame si è interrotto per un istante..."
  },
  AvgDialog_34974_Content_17 = {
    Text = "È tornata in fretta, ma quella sensazione di galleggiamento in cui non riuscivo nemmeno a parlare — non ero solo io."
  },
  AvgDialog_34974_Content_18 = {
    Text = "L'ho raggunt{Male=o,Female=a}, ma..."
  },
  AvgDialog_34974_Content_19 = {
    Text = "Celeste si ferma a metà, bloccandosi come un ingranaggio fuori posto. Le labbra le tremano un paio di volte, ma non esce nulla."
  },
  AvgDialog_34974_Content_2 = {
    Text = "Nell'istante in cui la punta del suo dito sfiora la mano del Custode, un vento bianco, dolce e silenzioso, si abbatte sul punto zero dell'esplosione."
  },
  AvgDialog_34974_Content_20 = {
    Text = "Elton le accarezza la schiena con dolcezza, finendo la frase al posto suo."
  },
  AvgDialog_34974_Content_21 = {
    Text = "Ma non abbiamo mai provato a spostare nulla di più grande di un topo, prima d'ora."
  },
  AvgDialog_34974_Content_22 = {
    Text = "Spostare esseri viventi sulla nave dipende dalla presa di Celeste sul Dominio. Ma con me che mi indebolisco, la sua mira... potrebbe non essere così precisa."
  },
  AvgDialog_34974_Content_23 = {
    Text = "{Male=Lui,Female=Lei} e Murphy potrebbero essere nascosti in qualsiasi angolo di questo scafo."
  },
  AvgDialog_34974_Content_24 = {
    Text = "Grazie al cielo... Scusi, Capitano, mi sono agitata—spero di non essere sembrata maleducata."
  },
  AvgDialog_34974_Content_25 = {
    Text = "Comunque... la Sona-Nyl è un transatlantico convertito per il trasporto merci. Il numero di cabine è..."
  },
  AvgDialog_34974_Content_26 = {
    Text = "Sette ponti, 648 Stanze."
  },
  AvgDialog_34974_Content_27 = {
    Text = "Andare Porta a Porta richiederebbe un'eternità..."
  },
  AvgDialog_34974_Content_28 = {
    Text = "Capitano, lei e Celeste potete cavarvela da soli? Devo andare adesso per Tracciare il Custode e Murphy il prima possibile. La loro situazione si fa sempre più pericolosa."
  },
  AvgDialog_34974_Content_29 = {
    Text = "Elton incontra i suoi Occhi Tenaci, poi ridacchia."
  },
  AvgDialog_34974_Content_3 = {
    Text = "È una forza così lieve, eppure trascina Ramona in un vuoto bianco senza fine con una potenza sorprendente. Mentre le coordinate impazziscono, le sue viscere sembrano torcersi fino a prosciugarsi."
  },
  AvgDialog_34974_Content_30 = {
    Text = "Non c'è fretta, signorina. Celeste e io possiamo riprovare."
  },
  AvgDialog_34974_Content_31 = {
    Text = "Provare cosa?"
  },
  AvgDialog_34974_Content_32 = {
    Text = "Celeste, perlustra le loro posizioni."
  },
  AvgDialog_34974_Content_33 = {
    Text = "Celeste fissa il Capitano senza emozione per un istante, poi annuisce debolmente. Solleva la bussola—"
  },
  AvgDialog_34974_Content_34 = {
    Text = "La Risvegliatrice chiude gli occhi, luce bianca vortica nei suoi palmi, lontani richiami di gabbiani echeggiano fiochi..."
  },
  AvgDialog_34974_Content_35 = {Text = "Ngh...!"},
  AvgDialog_34974_Content_36 = {
    Text = "Capitano! Fermati!"
  },
  AvgDialog_34974_Content_37 = {
    Text = "Il gemito di Pain di Elton spegne la luce."
  },
  AvgDialog_34974_Content_38 = {
    Text = "Celeste guarda il Capitano, poi il volto ansioso di Ramona, e infine fissa le proprie dita con sguardo vacuo."
  },
  AvgDialog_34974_Content_39 = {
    Text = "Ramona sorregge il Capitano, le dita gli controllano il polso, la sua espressione si fa seria."
  },
  AvgDialog_34974_Content_4 = {
    Text = "*Coff, coff...*"
  },
  AvgDialog_34974_Content_40 = {
    Text = "Collegare una Risvegliatrice, creare Domini, preservare le Memorie di marinai annegati... ogni volta che spingi Celeste a usare i suoi poteri inumani, ti Prosciuga la Vita."
  },
  AvgDialog_34974_Content_41 = {
    Text = "Salvarci da quell'esplosione nella sala motori... ha consumato le tue ultime Riserve, vero?"
  },
  AvgDialog_34974_Content_42 = {
    Text = "Elton fa qualche respiro profondo, placando gli Spasmi del cuore."
  },
  AvgDialog_34974_Content_43 = {
    Text = "—Poi, porge una tazza di legno a Ramona.\nChissà da dove l'ha tirata fuori."
  },
  AvgDialog_34974_Content_44 = {
    Text = "Un sorso? Potrebbe alleviare il ronzio."
  },
  AvgDialog_34974_Content_45 = {
    Text = "...No, grazie. Le Regole di Mythag ci sconsigliano di bere."
  },
  AvgDialog_34974_Content_46 = {
    Text = "Il Capitano non sembra sorpreso. Si inclina all'indietro per scolare il liquore Forte in un sol colpo, e getta via il boccale."
  },
  AvgDialog_34974_Content_47 = {
    Text = "*Coff, coff, coff...!*"
  },
  AvgDialog_34974_Content_48 = {
    Text = "Questa roba è tremenda."
  },
  AvgDialog_34974_Content_49 = {
    Text = "Collegare una Risvegliatrice richiede un'enorme forza mentale. Persino gli Investigatori rigorosamente addestrati di Mythag si scollegano e si riprendono dopo le missioni—quindi una persona comune..."
  },
  AvgDialog_34974_Content_5 = {
    Text = "Celeste abbassa la bussola, ansimando. Con il sostegno del Capitano, si siede, le mani raccolte in grembo, apparendo ancora più fragile di prima."
  },
  AvgDialog_34974_Content_50 = {
    Text = "Capitano, le tue condizioni..."
  },
  AvgDialog_34974_Content_51 = {
    Text = "Non preoccuparti. Quando ho scelto di collegarmi con Celeste, sapevo che questo giorno sarebbe arrivato."
  },
  AvgDialog_34974_Content_52 = {
    Text = "Il sorriso di Elton ora racchiude un tocco di pace, come se fosse davvero pronto ad accogliere la morte."
  },
  AvgDialog_34974_Content_53 = {
    Text = "Anche Celeste chiude gli occhi. La sua forma si fa più trasparente, ma il legame con il Capitano risplende più intenso—abbastanza solido da vedersi a occhio nudo."
  },
  AvgDialog_34974_Content_54 = {Text = "..."},
  AvgDialog_34974_Content_55 = {
    Text = "Con il Risvegliatore che svanisce, la Sona-Nyl diventa legno alla deriva in balia della tempesta, sbattuta onda dopo onda verso altezze vertiginose."
  },
  AvgDialog_34974_Content_56 = {
    Text = "L'energia della cabina cede sotto l'Impatto. Un'ultima scintilla si inarca, sprofondando la stanza nell'Oscurità."
  },
  AvgDialog_34974_Content_57 = {
    Text = "Tutto svanisce, tranne i ringhi sommessi del nemico, taglienti come lame."
  },
  AvgDialog_34974_Content_58 = {
    Text = "Ramona prepara la sua arma, facendo segno ai due dietro di restare in silenzio. Si avvicina alla porta, in guardia, un Faint ticchettio d'Orologio che sale dalla sua Ondata di Gnosi."
  },
  AvgDialog_34974_Content_59 = {
    Text = "Il tempo sembra fermarsi in un limbo silenzioso. I suoi nervi sono così tesi che riesce a malapena a Tracciare il suo Passaggio — cinque secondi, venti, un minuto? O il flusso del tempo si è sospeso?"
  },
  AvgDialog_34974_Content_6 = {
    Text = "Come ti senti?"
  },
  AvgDialog_34974_Content_60 = {
    Text = "Mettetevi davanti a me. Io copro le spalle. Non lasciate che vi tocchino."
  },
  AvgDialog_34974_Content_61 = {
    Text = "Come se avessi bisogno che me lo dici tu! È buio pesto — Ramona non c'è, e non c'è segno di vita. Alla faccia del tuo presentimento..."
  },
  AvgDialog_34974_Content_62 = {
    Text = "No... è qui vicino. Ne sono certo."
  },
  AvgDialog_34974_Content_63 = {
    Text = "Un clangore metallico improvviso. Prima che tu possa reagire, la porta viene spalancata con forza e delle mani si protendono, trascinando dentro te e Murphy."
  },
  AvgDialog_34974_Content_64 = {
    Text = "I cavi nell'intelaiatura del ponte ronzano debolmente ancora una volta, le lampadine tremolano rapidamente prima di brillare fiocamente, infine."
  },
  AvgDialog_34974_Content_65 = {
    Text = "Ramona si lancia a recuperare lo stocco caduto, un sorriso sorpreso che le si allarga sul volto."
  },
  AvgDialog_34974_Content_66 = {
    Text = "Grazie al cielo, stai bene..."
  },
  AvgDialog_34974_Content_67 = {
    Text = "Pensavo... che avrei dovuto entrare nell'oceano per trovarvi..."
  },
  AvgDialog_34974_Content_7 = {
    Text = "Celeste scuote la testa in silenzio. Nella mente annebbiata di Ramona — ancora stordita dall'esplosione e dal Trauma — non riesce a capire se sia un segno positivo o meno."
  },
  AvgDialog_34974_Content_8 = {
    Text = "Quando i loro sguardi si posano su di lei, Ramona apre la bocca per parlare, ma un ronzio basso le riempie le orecchie, il cervello che lancia segnali d'allarme."
  },
  AvgDialog_34974_Content_9 = {
    Text = "Ugh... mi pulsano le orecchie..."
  },
  AvgDialog_34975_Content_1 = {
    Text = "Ramona, coprimi! Prendo Murphy—sfonderemo dall'altra parte!"
  },
  AvgDialog_34975_Content_2 = {
    Text = "Ramona è in piedi dandovi le spalle, interamente concentrata sull'assalto pressante e incessante dei Navigatori, ma la sua postura irremovibile è la sua risposta."
  },
  AvgDialog_34975_Content_3 = {Text = "Attento!"},
  AvgDialog_34975_Content_4 = {
    Text = "Scorgendo un Navigatore che striscia dalle ombre verso Ramona, il capitano strattona il timone bruscamente da un lato."
  },
  AvgDialog_34975_Content_5 = {
    Text = "L'inerzia fa sbandare la nave all'improvviso, come una bestia in preda al panico che si contorce. Il ciarpame della cabina sbatte da un lato, e il caos si propaga attraverso il campo di battaglia."
  },
  AvgDialog_34975_Content_6 = {
    Text = "Con l'aiuto di Celeste, riesci a caricarti Murphy sulla schiena. Come se fosse pronta per la virata, ti sorregge durante l'inclinazione."
  },
  AvgDialog_34975_Content_7 = {
    Text = "Ramona affonda la spada nel petto di un assalitore, si volta e ti rivolge un cenno del capo."
  },
  AvgDialog_34976_Content_1 = {
    Text = "Una fitta nebbia si aggrappa alla superficie del mare, ma il ponte risplende luminoso sotto la luna piena. Anche la più sottile Espressione è chiaramente visibile al chiaro di Luna."
  },
  AvgDialog_34976_Content_10 = {
    Text = "Bastano pochi passi, e un tonfo risuona alle loro spalle. Tutti si voltano e vedono Murphy in Ginocchio, il busto piegato in avanti, quasi distesa sul ponte."
  },
  AvgDialog_34976_Content_11 = {Text = "Murphy?!"},
  AvgDialog_34976_Content_12 = {
    Text = "Ti precipiti, sollevando Murphy crollata dal ponte. La sua coscienza svanisce, la frangia incollata dal sudore freddo, appiccicata disordinatamente alla fronte."
  },
  AvgDialog_34976_Content_13 = {
    Text = "@1... fa male..."
  },
  AvgDialog_34976_Content_14 = {
    Text = "Ugh... @1... @1..."
  },
  AvgDialog_34976_Content_15 = {
    Text = "Si aggrappa alla tua Mano che la sorregge, il dolore le fa affondare le dita a fondo—eppure avverti a malapena quella lieve fitta."
  },
  AvgDialog_34976_Content_16 = {
    Text = "Senti il battito crescente di un tamburo—non il cuore, ma una Specie Parassita nel petto della Bambina, che pulsa mentre Divora la sua forza vitale."
  },
  AvgDialog_34976_Content_17 = {
    Text = "Il \"Dio\"... le sta prosciugando la Vita."
  },
  AvgDialog_34976_Content_18 = {
    Text = "Mir... @2..."
  },
  AvgDialog_34976_Content_19 = {
    Text = "La Specie Parassita sul suo cuore è il nucleo del Cataclisma—se continua così, lei..."
  },
  AvgDialog_34976_Content_2 = {Text = "La Luna..."},
  AvgDialog_34976_Content_20 = {
    Text = "Alzi lo sguardo verso la finestra quadrata della plancia—nera come la pece, come le fauci di una balena che inghiottono la luce Da Lontano."
  },
  AvgDialog_34976_Content_21 = {
    Text = "Murphy, mi senti?"
  },
  AvgDialog_34976_Content_22 = {Text = "Murphy?"},
  AvgDialog_34976_Content_23 = {
    Text = "Nella Sua... @2"
  },
  AvgDialog_34976_Content_24 = {
    Text = "Il respiro di Murphy perde il ritmo. È intrappolata in Sogni inquieti e pericolosi—non risponde ai tuoi richiami."
  },
  AvgDialog_34976_Content_25 = {
    Text = "...Resisti."
  },
  AvgDialog_34976_Content_26 = {
    Text = "Lascia che la porti io, ragazzo."
  },
  AvgDialog_34976_Content_27 = {
    Text = "Sei più debole di me—lo faccio io. Ramona, fai la guardia. Mi sono allenato coi pesi. Posso portare Murphy."
  },
  AvgDialog_34976_Content_28 = {
    Text = "Elton non insiste. Con il suo aiuto, sollevi le ginocchia di Murphy, lasciandola accasciarsi sulla tua schiena."
  },
  AvgDialog_34976_Content_29 = {
    Text = "Raccogli tutte le forze per tenerla ferma, e fai un respiro profondo, pronto a salire le scale—"
  },
  AvgDialog_34976_Content_3 = {
    Text = "Che succede con la Luna?"
  },
  AvgDialog_34976_Content_30 = {
    Text = "La ragazza in stato comatoso giace sulla tua schiena, sussurri farfugliati ti sfiorano l'orecchio."
  },
  AvgDialog_34976_Content_31 = {
    Text = "Dio... @2... @4..."
  },
  AvgDialog_34976_Content_32 = {
    Text = "A parte gemiti di dolore, Murphy mormora solo parole senza senso. In mezzo a questo borbottio caotico, i nemici emergono dalle ombre."
  },
  AvgDialog_34976_Content_4 = {
    Text = "Si sta facendo più luminosa, e..."
  },
  AvgDialog_34976_Content_5 = {
    Text = "Murphy trattiene il resto, ma sai cosa intende—"
  },
  AvgDialog_34976_Content_6 = {
    Text = "Il suo tempo sta per scadere."
  },
  AvgDialog_34976_Content_7 = {
    Text = "Sbrighiamoci verso la plancia. Capitano, facci strada."
  },
  AvgDialog_34976_Content_8 = {
    Text = "Dobbiamo attraversare il ponte per raggiungere il piano superiore della plancia."
  },
  AvgDialog_34976_Content_9 = {
    Text = "Ramona annuisce, facendo da scudo al Capitano mentre avanza."
  },
  AvgDialog_34977_Content_1 = {
    Text = "Aaah! %player%, fa' qualcosa—mi stanno agguantando gli stivali!"
  },
  AvgDialog_34977_Content_2 = {
    Text = "Quella capanna... blocca l'ingresso con la Porta!"
  },
  AvgDialog_34978_Content_1 = {
    Text = "Annientamento"
  },
  AvgDialog_34978_Content_10 = {
    Text = "Orfanotrofio..."
  },
  AvgDialog_34978_Content_100 = {
    Text = "Perché urli così!"
  },
  AvgDialog_34978_Content_101 = {
    Text = "L'orlo della gonna di Celeste rivelò una bambina, che per poco non mi fece cadere dallo spavento."
  },
  AvgDialog_34978_Content_102 = {
    Text = "Sembrava... familiare. Giuro di averla vista da qualche parte."
  },
  AvgDialog_34978_Content_103 = {
    Text = "Hai fatto salire a bordo questa ragazza maleducata, Celeste?"
  },
  AvgDialog_34978_Content_104 = {
    Text = "Ti ho detto di smetterla di urlare! Vuoi che quei Navigatori ci sentano?"
  },
  AvgDialog_34978_Content_105 = {
    Text = "E chi stai chiamando maleducata?! Il mio nome è Murphy, Murphy!"
  },
  AvgDialog_34978_Content_106 = {
    Text = "L'ho ricordata — dalla Memoria Profonda, durante un Rito."
  },
  AvgDialog_34978_Content_107 = {
    Text = "Dopo che la \"Madre Divina\" fu colpita dalla Dissoluzione, Miryam scelse un nuovo \"vascello\" per l'embrione divino, facendola sprofondare in un sonno lungo decenni."
  },
  AvgDialog_34978_Content_108 = {
    Text = "Con l'Allineamento Stellare ormai prossimo, la sacerdotessa la risvegliò. Questo carico erano le provviste per il \"Rituale della Discesa Divina\"."
  },
  AvgDialog_34978_Content_109 = {
    Text = "Alla bambina che avevo nutrito col biberon durante le tempeste sarebbe stato negato per sempre il diritto di crescere."
  },
  AvgDialog_34978_Content_11 = {
    Text = "N-Non è possibile. La mia famiglia..."
  },
  AvgDialog_34978_Content_110 = {
    Text = "Vi conosco — non siete Navigatori, solo corrieri associati... Portatemi via di qui, il più lontano possibile — e questi tesori saranno vostri."
  },
  AvgDialog_34978_Content_111 = {
    Text = "Come per magia, estrae dalla borsa rozze statuette intagliate nel legno. Al primo sguardo fanno venire le vertigini, venerate dai Navigatori ma prive di valore per gli estranei."
  },
  AvgDialog_34978_Content_112 = {
    Text = "Murphy... vuole venire con noi."
  },
  AvgDialog_34978_Content_113 = {
    Text = "Lei... Dissoluzione..."
  },
  AvgDialog_34978_Content_114 = {Text = "..."},
  AvgDialog_34978_Content_115 = {
    Text = "Era una mia lontana antenata, vittima di usanze barbare in un'epoca passata — e l'unica prova che la mia \"Terra dei Bianchi Uccelli\" fosse mai esistita."
  },
  AvgDialog_34978_Content_116 = {
    Text = "Le esperienze della sua vita passata avevano sigillato il \"sé\" di Celeste nel profondo della sua anima. Non potevo negarle la sua prima richiesta."
  },
  AvgDialog_34978_Content_117 = {Text = "Inoltre..."},
  AvgDialog_34978_Content_118 = {
    Text = "Salpiamo, Celeste."
  },
  AvgDialog_34978_Content_119 = {
    Text = "Hai... accettato di portarmi con voi?"
  },
  AvgDialog_34978_Content_12 = {
    Text = "Hai davvero perso la testa? Giocavamo in queste strade da bambini. Scavalcavo il muro dell'orfanotrofio col cibo per te, e la suora mi inseguiva per tre isolati—hai dimenticato tutto?"
  },
  AvgDialog_34978_Content_120 = {
    Text = "Se Celeste lo vuole, ti porterò il più lontano possibile."
  },
  AvgDialog_34978_Content_121 = {
    Text = "Wow... la vizi così tanto?"
  },
  AvgDialog_34978_Content_122 = {
    Text = "Moccioso sfacciato. Potrei cambiare idea e gettarti nel mare ghiacciato in qualsiasi momento."
  },
  AvgDialog_34978_Content_123 = {
    Text = "Tirchio... va bene, non chiederò più nulla."
  },
  AvgDialog_34978_Content_124 = {
    Text = "E poi... sono stato io a mandare Murphy su questa strada."
  },
  AvgDialog_34978_Content_125 = {
    Text = "Una strada costellata di Dissoluzione, che conduce alla rovina e all'Oblio."
  },
  AvgDialog_34978_Content_126 = {
    Text = "Devo espiare per questo."
  },
  AvgDialog_34978_Content_13 = {Text = "..."},
  AvgDialog_34978_Content_14 = {
    Text = "Scusa, amico—dev'essere la confusione post-viaggio, sogni mescolati alla realtà. Non ci vediamo da anni—che ne dici di un drink al solito posto stasera?"
  },
  AvgDialog_34978_Content_15 = {
    Text = "Heh, il vecchio John ha inventato un nuovo gusto di whiskey—di prima qualità! Facciamo così—nessuno torna a casa sobrio!"
  },
  AvgDialog_34978_Content_16 = {
    Text = "Già... non si torna a casa da sobri."
  },
  AvgDialog_34978_Content_17 = {
    Text = "Non sapevo di alcun pozzo minerario, non ero mai stato in un orfanotrofio, e il vecchio John era il nome di uno sconosciuto."
  },
  AvgDialog_34978_Content_18 = {
    Text = "Tutto ciò che sapevo era che ogni cosa di quella città mi stava sfuggendo."
  },
  AvgDialog_34978_Content_19 = {
    Text = "La mia infanzia, i miei genitori, i miei fratelli—liquidati come un sogno assurdo."
  },
  AvgDialog_34978_Content_2 = {
    Text = "A.F. 21 Inizio Autunno Leonia Meridionale"
  },
  AvgDialog_34978_Content_20 = {
    Text = "Persino io stavo iniziando a crederci."
  },
  AvgDialog_34978_Content_21 = {
    Text = "Ma i sogni non sono poi così difficili da dimenticare."
  },
  AvgDialog_34978_Content_22 = {
    Text = "A.F. 22 Pieno Inverno Elworth, Santuario dei Navigatori"
  },
  AvgDialog_34978_Content_23 = {
    Text = "Questa spedizione contiene provviste giornaliere e... i corpi di diciannove esperimenti falliti, dalla... chiesa."
  },
  AvgDialog_34978_Content_24 = {
    Text = "I dati del mittente sono macchiati dall'acqua di mare—vuoi comunque firmare per la ricezione?"
  },
  AvgDialog_34978_Content_25 = {
    Text = "Confermo... tutto corretto..."
  },
  AvgDialog_34978_Content_26 = {
    Text = "Mentre parlavo, il contatto curvo mi strappò il manifesto di mano. Non sembrava importargli di ciò che dicevo, mormorando vagamente \"confermo\"."
  },
  AvgDialog_34978_Content_27 = {
    Text = "I venti polari strapparono il cappuccio dal capo del contatto, rivelando una testa del tutto grottesca."
  },
  AvgDialog_34978_Content_28 = {
    Text = "Occhi enormi e sporgenti, palpebre incapaci di chiudersi, e lembi simili a branchie che legavano la mascella alla clavicola—aveva il volto di un pesce."
  },
  AvgDialog_34978_Content_29 = {
    Text = "Inghiottendo ribrezzo e nausea, sollevai comunque il cappello in segno di saluto."
  },
  AvgDialog_34978_Content_3 = {
    Text = "Come puoi non conoscere quella città!?"
  },
  AvgDialog_34978_Content_30 = {
    Text = "Se è tutto, la Sona-Nyl salperà stanotte. La prossima consegna arriverà tra circa 114 giorni."
  },
  AvgDialog_34978_Content_31 = {
    Text = "@1... buon viaggio... a te..."
  },
  AvgDialog_34978_Content_32 = {
    Text = "...Aspetta."
  },
  AvgDialog_34978_Content_33 = {
    Text = "Mentre stavo per salire a bordo, la voce sconosciuta di una donna mi fermò."
  },
  AvgDialog_34978_Content_34 = {
    Text = "Era una donna adulta con un velo nero, vestita troppo leggera—persino scalza. Nel gelo polare di Elworth, risaltava in modo evidente."
  },
  AvgDialog_34978_Content_35 = {
    Text = "Somma Sacerdotessa, Somma Sacerdotessa..."
  },
  AvgDialog_34978_Content_36 = {
    Text = "Il contatto crollò a terra, il corpo che sbatteva sulla fredda roccia nera con un tonfo da far accapponare la pelle."
  },
  AvgDialog_34978_Content_37 = {
    Text = "Dopo dieci anni in mare—tra tenacia, fortuna e lavori loschi—possedevo la mia nave ed ero un capitano ormai. Ma essere un capitano non significava nulla in questo culto segreto."
  },
  AvgDialog_34978_Content_38 = {
    Text = "Non avevo mai incontrato i vertici, ma dalla reazione del Navigatore, capii che il suo rango era elevato."
  },
  AvgDialog_34978_Content_39 = {
    Text = "Così mi inginocchiai come lui, senza esitazione."
  },
  AvgDialog_34978_Content_4 = {
    Text = "Alla foce del fiume @2, ai piedi della @3 Catena Montuosa... è lì che siamo cresciuti!"
  },
  AvgDialog_34978_Content_40 = {
    Text = "Somma Sacerdotessa."
  },
  AvgDialog_34978_Content_41 = {
    Text = "Spiriti erranti turbinano intorno a te. Barcaiolo, porti reliquie dei morti?"
  },
  AvgDialog_34978_Content_42 = {
    Text = "Reliquie dei morti..."
  },
  AvgDialog_34978_Content_43 = {
    Text = "Al cenno della sacerdotessa, aprii di scatto l'orologio da tasca — il quadrante era ricoperto da un vortice d'argento."
  },
  AvgDialog_34978_Content_44 = {
    Text = "Sì, la Gnosi al suo interno è flebile... ma è un Nucleo d'Argento, senza dubbio."
  },
  AvgDialog_34978_Content_45 = {
    Text = "Ogni Nucleo d'Argento custodisce una memoria dimenticata... desideri risvegliare questa?"
  },
  AvgDialog_34978_Content_46 = {
    Text = "Una memoria dimenticata..."
  },
  AvgDialog_34978_Content_47 = {
    Text = "Il mio passato era negato da tutti. Questo fluido argenteo, pescato da <Yellow:quella che un tempo era la mia città natale>, potrebbe essere il mio ultimo indizio."
  },
  AvgDialog_34978_Content_48 = {
    Text = "Lo voglio...! Per favore, Somma Sacerdotessa, guidami."
  },
  AvgDialog_34978_Content_49 = {
    Text = "Completa la prossima navigazione... poi ti rivelerò il metodo per risvegliare un Nucleo d'Argento."
  },
  AvgDialog_34978_Content_5 = {
    Text = "Le sirene ti hanno rubato il cervello durante il tempo in mare? Quel posto è palude dal Diluvio."
  },
  AvgDialog_34978_Content_50 = {
    Text = "Portami la mia <Yellow:speranza>."
  },
  AvgDialog_34978_Content_51 = {
    Text = "La Somma Sacerdotessa dei Navigatori Miryam mi assegnò un nuovo incarico. Il carico di quel viaggio: una <Yellow:bambina>."
  },
  AvgDialog_34978_Content_52 = {
    Text = "Prima, avevo tenuto in braccio i miei fratellini solo in quei \"sogni\". Purtroppo, quei ricordi felici e sereni svanivano al risveglio."
  },
  AvgDialog_34978_Content_53 = {
    Text = "I venti di ponente allungarono il viaggio — nell'ultima settimana in mare, tutta l'acqua dolce andò a questa piccola."
  },
  AvgDialog_34978_Content_54 = {
    Text = "Non le importava della mia barba arruffata, ridacchiava tra le mie braccia."
  },
  AvgDialog_34978_Content_55 = {
    Text = "La affidai alla Somma Sacerdotessa."
  },
  AvgDialog_34978_Content_56 = {
    Text = "A.F. 31 Solstizio d'Estate Oceano Atlas"
  },
  AvgDialog_34978_Content_57 = {
    Text = "Tutte le bussole sono impazzite, le onde hanno sfondato il timone!"
  },
  AvgDialog_34978_Content_58 = {
    Text = "Le c-caldaie sono allagate! Siamo in panne!"
  },
  AvgDialog_34978_Content_59 = {
    Text = "Che avete fatto?! Non riesco più a governare — le correnti ci spingono dritti nella tempesta!"
  },
  AvgDialog_34978_Content_6 = {Text = "Palude?"},
  AvgDialog_34978_Content_60 = {
    Text = "Non è il momento di dare la colpa a qualcuno!"
  },
  AvgDialog_34978_Content_61 = {
    Text = "Primo ufficiale, porta l'equipaggio a calare le scialuppe. Stipatevi stretti e remate via prima che il vortice ci risucchi."
  },
  AvgDialog_34978_Content_62 = {
    Text = "E tu, Capitano?"
  },
  AvgDialog_34978_Content_63 = {
    Text = "...Uscite in fretta, e basta."
  },
  AvgDialog_34978_Content_64 = {
    Text = "Erano passati due anni, e avevo eseguito i metodi segreti della sacerdotessa innumerevoli volte—nessuno aveva fatto brillare quel Nucleo d'Argento."
  },
  AvgDialog_34978_Content_65 = {
    Text = "Infiniti fallimenti e sforzi mi avevano quasi fatto rinunciare a inseguire la verità... la verità sulla scomparsa della mia città natale."
  },
  AvgDialog_34978_Content_66 = {
    Text = "Mandai la maggior parte dell'equipaggio sulle scialuppe, poi affondai con la Sona-Nyl, aggrappandomi alle memorie del mio passato."
  },
  AvgDialog_34978_Content_67 = {
    Text = "Nella discesa senza fine, il vento mi sfiorava il volto."
  },
  AvgDialog_34978_Content_68 = {
    Text = "Il vento spremette l'acqua dai miei polmoni, spazzò via il sale che corrodeva le ferite, e sollevò un sogno che affondava negli abissi."
  },
  AvgDialog_34978_Content_69 = {
    Text = "Poi la vidi—una ragazza, avvolta da brezze gentili e bianchi uccelli."
  },
  AvgDialog_34978_Content_7 = {
    Text = "Già! Si dice che ci fosse un pozzo minerario, e un fiume ha deviato durante la grande inondazione, facendolo crollare. Un qualche lord ha comprato il terreno un paio d'anni fa, ha in progetto di costruirci un parco o qualcosa del genere."
  },
  AvgDialog_34978_Content_70 = {
    Text = "Il mio nome è Celeste. Finché avrai bisogno di me, sarò qui."
  },
  AvgDialog_34978_Content_71 = {
    Text = "Era una traccia dell'esistenza della mia terra natale, una fiaba sulle labbra degli anziani nella mia giovinezza. Dimostrava che il mio passato tormentato era reale."
  },
  AvgDialog_34978_Content_72 = {
    Text = "Il suo avvento dimostrò che non ero un folle senza radici."
  },
  AvgDialog_34978_Content_73 = {
    Text = "Tre Mesi Fa Elworth, Santuario dei Navigatori"
  },
  AvgDialog_34978_Content_74 = {
    Text = "Rifornimenti della filiale di Nuova Leonia: 135 casse. Sacrifici dell'Associazione: 12 corpi. Generi alimentari dell'Isola del Corno: 120 casse... tutto torna."
  },
  AvgDialog_34978_Content_75 = {
    Text = "*Coff, coff...*"
  },
  AvgDialog_34978_Content_76 = {
    Text = "Sei fondamentale per l'ordine — abbi cura di te."
  },
  AvgDialog_34978_Content_77 = {
    Text = "Oh, l'ordine ha completato in anticipo un nuovo lotto di <Blue:stabilizzatori>—ho qui la tua quota trimestrale. Te la conseg—"
  },
  AvgDialog_34978_Content_78 = {
    Text = "Shh—conservalo per il nostro incontro programmato, il solito posto: <Yellow:Brilpert, Terzo Molo, Ormeggio Nord 2>."
  },
  AvgDialog_34978_Content_79 = {
    Text = "Celeste e io ti aspetteremo là. Abbiamo in programma di raccogliere alcuni ingredienti speciali dal Mare interno. Che ne dici di una cena, poi?"
  },
  AvgDialog_34978_Content_8 = {
    Text = "Ma... il mio focolare..."
  },
  AvgDialog_34978_Content_80 = {
    Text = "Sarebbe... un onore."
  },
  AvgDialog_34978_Content_81 = {
    Text = "Ho sentito che Lady Miryam ha risvegliato la <Blue:Madre Divina> dal suo dormiveglia, così che Nostro Signore possa fare ritorno al prossimo Allineamento Stellare."
  },
  AvgDialog_34978_Content_82 = {
    Text = "I prossimi tre mesi saranno probabilmente estremamente impegnativi. Ma onorerò senz'altro il nostro appuntamento."
  },
  AvgDialog_34978_Content_83 = {
    Text = "D'accordo, è deciso allora. Ci vediamo tra tre mesi."
  },
  AvgDialog_34978_Content_84 = {
    Text = "Quel ragazzo, che un tempo portava il sangue di un Navigatore ma ora possedeva il corpo di un Golem, sorrise timidamente—Per me, Caecus era solo un bambino."
  },
  AvgDialog_34978_Content_85 = {
    Text = "Somigliava molto al fratello minore che esisteva nelle mie memorie—un ragazzo timido e sensibile."
  },
  AvgDialog_34978_Content_86 = {
    Text = "La tempesta sul Mare di Welde arriverà presto—dovresti partire in fretta."
  },
  AvgDialog_34978_Content_87 = {
    Text = "Già, niente navigare tra tempeste di ghiaccio."
  },
  AvgDialog_34978_Content_88 = {
    Text = "Salutato Caecus, sfiorai l'ultimo pezzo di \"carico\" in fase di scarico e salii sulla nave."
  },
  AvgDialog_34978_Content_89 = {
    Text = "Quella cosa respirava ancora, il panno bianco si sollevava appena. Melma nera ne gocciolava, qualcosa stava svanendo."
  },
  AvgDialog_34978_Content_9 = {
    Text = "Ti sei buttato in mare appena uscito dall'orfanotrofio—non torni da oltre un decennio, ma hai dimenticato così tanto? Sei malato o cosa?"
  },
  AvgDialog_34978_Content_90 = {
    Text = "Controlla la tua curiosità, Elton!\nNon <Red:guardare>.\nNon <Red:pensare>.\n<Big:Non>... <RedBig:AFFRONTARLO>."
  },
  AvgDialog_34978_Content_91 = {
    Text = "Celeste, sono tornato."
  },
  AvgDialog_34978_Content_92 = {Text = "..."},
  AvgDialog_34978_Content_93 = {
    Text = "È ora di salpare — come previsto."
  },
  AvgDialog_34978_Content_94 = {Text = "..."},
  AvgDialog_34978_Content_95 = {Text = "Celeste?"},
  AvgDialog_34978_Content_96 = {
    Text = "Bene, salpiamo... verso la Repubblica di Aglo."
  },
  AvgDialog_34978_Content_97 = {
    Text = "No, no—la destinazione è il <Blue:Mare Interno>, andiamo a prendere ingredienti locali. Perché sei nel vuoto? È successo qualcosa a bordo?"
  },
  AvgDialog_34978_Content_98 = {
    Text = "...Sì, Mare Interno, salpiamo."
  },
  AvgDialog_34978_Content_99 = {
    Text = "Celeste! Guardami!"
  },
  AvgDialog_34979_Content_1 = {
    Text = "Tutto chiaro dalla mia parte. Capitano, il Custode e io andremo in avanscoperta—voi potete seguire con Murphy e Celeste."
  },
  AvgDialog_34979_Content_10 = {
    Text = "Ma a te... non piaceva molto? Venivi spesso a regolare il motore—ti ho visto."
  },
  AvgDialog_34979_Content_11 = {
    Text = "Ehi, ehi! Cosa stai facendo—"
  },
  AvgDialog_34979_Content_12 = {
    Text = "Elton si china e pizzica le guance tese di Murphy."
  },
  AvgDialog_34979_Content_13 = {
    Text = "Se vuoi rimediare, resta in vita."
  },
  AvgDialog_34979_Content_14 = {
    Text = "Elton non dà a Murphy il tempo di rispondere. La spinge, dolcemente, da dietro, sospingendola, barcollante, fuori dalla cabina sinistra e abissale."
  },
  AvgDialog_34979_Content_15 = {
    Text = "Murphy resta ferma davanti alla porta della stiva successiva, osservando il Capitano dall'altro lato del corridoio largo un metro."
  },
  AvgDialog_34979_Content_16 = {
    Text = "Aiuta prima Celeste a uscire dalla Stanza piena di D-iperplasia, affidandola a Murphy, poi torna nell'oscurità per chiudere la Porta."
  },
  AvgDialog_34979_Content_17 = {
    Text = "Capitano..."
  },
  AvgDialog_34979_Content_18 = {
    Text = "Mi stai ancora guardando? Quei due si stanno portando avanti."
  },
  AvgDialog_34979_Content_19 = {
    Text = "Dici davvero? Tu e Celeste avete rischiato la vita per me—davvero... non volete nulla in cambio?"
  },
  AvgDialog_34979_Content_2 = {
    Text = "D'accordo, grazie."
  },
  AvgDialog_34979_Content_20 = {
    Text = "Dai, ragazzo, io..."
  },
  AvgDialog_34979_Content_21 = {
    Text = "Capitano—Murphy— Dove siete?"
  },
  AvgDialog_34979_Content_22 = {Text = "Arrivo!"},
  AvgDialog_34979_Content_23 = {
    Text = "Infine, chiude la Porta alle sue spalle, e la fluorescenza sul suo cappotto svanisce con essa."
  },
  AvgDialog_34979_Content_24 = {
    Text = "Beh, Murphy, promettimi solo che vivrai una bella vita. Cresci, trovati un lavoro, guadagna un po' di soldi. Poi potrai comprarmi l'ultimo modello di automobile. Affare fatto?"
  },
  AvgDialog_34979_Content_3 = {
    Text = "Elton sbircia dalla porta della cabina, confermando che Il Sentiero è sicuro per ora, poi si volta di lato e fa cenno a Murphy e Celeste di avvicinarsi."
  },
  AvgDialog_34979_Content_4 = {
    Text = "All'uscita della stiva, Elton si ferma. Si volta verso l'auto distrutta dalla D-iperplasia simile a corallo, con una nota di rammarico nella voce."
  },
  AvgDialog_34979_Content_5 = {
    Text = "Questo è un modello sperimentale di motore a quattro cilindri... questa bellezza non ha mai nemmeno toccato la strada. Un peccato."
  },
  AvgDialog_34979_Content_6 = {Text = "..."},
  AvgDialog_34979_Content_7 = {
    Text = "Murphy si morde il labbro, lanciando un'occhiata all'auto distrutta, poi sbircia di nascosto Elton qualche volta."
  },
  AvgDialog_34979_Content_8 = {
    Text = "Cos'è quello sguardo?"
  },
  AvgDialog_34979_Content_9 = {
    Text = "Hai paura? Tranquilla, non ti sto chiedendo di comprarmene una nuova."
  },
  AvgDialog_34980_Content_1 = {
    Text = "Luna della Crisi"
  },
  AvgDialog_34980_Content_10 = {
    Text = "Ti crediamo."
  },
  AvgDialog_34980_Content_11 = {
    Text = "Ragazzina..."
  },
  AvgDialog_34980_Content_12 = {
    Text = "L'Università di Mythag combatte la Dissoluzione da secoli, e innumerevoli investigatori hanno dato la vita."
  },
  AvgDialog_34980_Content_13 = {
    Text = "Molti ne sono stati divorati—il mondo li dimentica poco a poco, e persino le loro lettere germogliano D-segni."
  },
  AvgDialog_34980_Content_14 = {
    Text = "Voi due non avete paura?"
  },
  AvgDialog_34980_Content_15 = {
    Text = "Paura... certo. Certo che ne ho. Chi non sarebbe terrorizzato all'idea di essere cancellato dall'esistenza?"
  },
  AvgDialog_34980_Content_16 = {
    Text = "Ma qualcuno deve affrontarlo, no?"
  },
  AvgDialog_34980_Content_17 = {
    Text = "Se ci tiriamo indietro, i colleghi caduti durante le indagini, quelli cancellati dalla Dissoluzione..."
  },
  AvgDialog_34980_Content_18 = {
    Text = "Se ci tiriamo indietro, la loro esistenza perderà ogni significato."
  },
  AvgDialog_34980_Content_19 = {
    Text = "Per il nostro futuro, e per chi non c'è più, tratteremo anche la teoria più assurda come un fatto e indagheremo."
  },
  AvgDialog_34980_Content_2 = {
    Text = "La confessione di Elton lascia te e Ramona senza parole. La fissate in silenzio, leggendo lo stesso shock negli occhi dell'altra."
  },
  AvgDialog_34980_Content_20 = {Text = "Heh..."},
  AvgDialog_34980_Content_21 = {
    Text = "A quanto pare i pazzi sono ancora la maggioranza."
  },
  AvgDialog_34980_Content_22 = {Text = "Woo—"},
  AvgDialog_34980_Content_23 = {
    Text = [[
Il corno risuona, facendo trasalire tutti.
Elton reagisce per primo, lanciandosi sulla console per fermare manualmente il fischio.]]
  },
  AvgDialog_34980_Content_24 = {
    Text = "Dannazione! I tubi del fischio sono stati distrutti da quei coralli!\nQuel rumore—presto quelle cose capiranno che c'è qualcuno sul ponte."
  },
  AvgDialog_34980_Content_25 = {
    Text = "Ramona si precipita fuori dalla plancia, e tu la segui, entrambi sporgendovi dalla ringhiera per guardare giù—"
  },
  AvgDialog_34980_Content_26 = {
    Text = "Navigatori erranti sul ponte inferiore allungano il collo verso l'alto, puntando i loro occhi da pesce morto nei tuoi."
  },
  AvgDialog_34980_Content_27 = {
    Text = "Allora? I Navigatori non ci hanno avvistati, vero?"
  },
  AvgDialog_34980_Content_28 = {Text = "..."},
  AvgDialog_34980_Content_29 = {
    Text = "Capitano, concentrati sulla rotta."
  },
  AvgDialog_34980_Content_3 = {
    Text = "Una città natale cancellata dalla Dissoluzione, Celeste come unica prova della sua esistenza..."
  },
  AvgDialog_34980_Content_30 = {
    Text = "Quanto alle distrazioni esterne... il Custode e io ce ne occuperemo."
  },
  AvgDialog_34980_Content_4 = {
    Text = "Il senso di colpa per aver consegnato Murphy al culto con le tue stesse mani... è per questo che ti sei rivoltato contro i Navigatori?"
  },
  AvgDialog_34980_Content_5 = {
    Text = "Elton si accovaccia accanto a Murphy, scostando i capelli sudati incollati alla fronte. Dopo aver controllato le sue condizioni, sospira profondamente, poi si alza per affrontarti di nuovo."
  },
  AvgDialog_34980_Content_6 = {
    Text = "Se non l'avessi consegnata a Miryam, non sarebbe stata posseduta da quel cosiddetto \"Dio\". Non sarebbe qui distesa, in punto di morte."
  },
  AvgDialog_34980_Content_7 = {
    Text = "Sembra uno scherzo, vero?"
  },
  AvgDialog_34980_Content_8 = {
    Text = "Gli esseri umani sono bravissimi a documentare la storia—persino i giochi antichi hanno lasciato tracce. Com'è possibile che un'intera città svanisca senza lasciarne alcuna?"
  },
  AvgDialog_34980_Content_9 = {
    Text = "Dimentica le mie divagazioni—considerala una storia della buonanotte senza valore che mi sono inventato."
  },
  AvgDialog_34981_Content_1 = {
    Text = "Ramona, tu..."
  },
  AvgDialog_34981_Content_10 = {
    Text = "È sparita... Come?"
  },
  AvgDialog_34981_Content_11 = {
    Text = "Cos'è sparito?"
  },
  AvgDialog_34981_Content_12 = {
    Text = "Il taglio sul polpaccio è sparito.\nMa l'ho visto chiaramente... la lama del nemico ti aveva inchiodato lì."
  },
  AvgDialog_34981_Content_13 = {
    Text = "Ecco perché mi hai ordinato di portare via Celeste. Ecco perché ho dovuto lasciarti indietro..."
  },
  AvgDialog_34981_Content_14 = {
    Text = "Non puoi dimenticare quel Pain che ti penetra fino all'Osso."
  },
  AvgDialog_34981_Content_15 = {
    Text = "Come un boia indifferente al condannato, Golia estrasse l'arma con uno strattone, senza alcun riguardo per la tua agonia."
  },
  AvgDialog_34981_Content_16 = {
    Text = "Il sangue inzuppava la tua uniforme, brandelli di carne schizzavano sulla mano di Golia. Il tuo polpaccio era quasi reciso — solo il terrore e l'adrenalina ti tenevano cosciente."
  },
  AvgDialog_34981_Content_17 = {
    Text = "Sebbene il dolore tiri ancora i tuoi nervi... è sparita. Quella ferita orribile — svanita."
  },
  AvgDialog_34981_Content_18 = {
    Text = "Il tessuto è strappato con due enormi buchi, ma la pelle sottostante è liscia.\n\nPallida per la mancanza di luce, ma sana e integra."
  },
  AvgDialog_34981_Content_19 = {
    Text = "La tua Ferita è guarita? Dev'essere opera di Celeste."
  },
  AvgDialog_34981_Content_2 = {
    Text = "Shh... piano. I Navigatori sono ancora là fuori."
  },
  AvgDialog_34981_Content_20 = {
    Text = "Murphy trotta verso Celeste e afferra delicatamente un nastro bianco dalla sua spalla — ora sembra una benda."
  },
  AvgDialog_34981_Content_21 = {
    Text = "Alzi lo sguardo verso Celeste, incrociando il suo. Con il corpo da Connettore che cede, sta deteriorandosi, e sembra non avere nemmeno la forza di parlare."
  },
  AvgDialog_34981_Content_22 = {
    Text = "Le sue labbra si muovono, lasciando sfuggire un debole sussurro. Non hai mai studiato la lettura labiale, eppure vedi chiaramente —"
  },
  AvgDialog_34981_Content_23 = {
    Text = "Non sono stata io."
  },
  AvgDialog_34981_Content_24 = {
    Text = "Non è stata lei.\nNe sei assolutamente certo."
  },
  AvgDialog_34981_Content_25 = {
    Text = "Quell'ondata di energia era immensa, come un ammasso di stelle. Non poteva provenire da Celeste, ormai molto debole."
  },
  AvgDialog_34981_Content_3 = {
    Text = "Ramona ti stringe forte la mano, scrutandoti dalla testa ai piedi. Non c'è tempo di parlare — ti passa le mani sulle ferite..."
  },
  AvgDialog_34981_Content_4 = {
    Text = "Miryam e Golia ti hanno conciato per le feste. Devo controllare se ci sono infezioni o deterioramenti..."
  },
  AvgDialog_34981_Content_5 = {
    Text = "Il Potere di Miryam ti aveva schiacciato e contorto la vita — ma non senti dolore al tocco di Ramona."
  },
  AvgDialog_34981_Content_6 = {
    Text = [[
Ti gira dietro, annusando il medicinale, e solleva i capelli sulla nuca.

Dopo aver osservato il disastro per un po', cade in un silenzio insolito per un momento.]]
  },
  AvgDialog_34981_Content_7 = {
    Text = "...Chi ti ha spalmato Unguento dappertutto sulla testa? C'è Sangue, ma nessuna Ferita."
  },
  AvgDialog_34981_Content_8 = {
    Text = "Coff... Quindi non c'è nessuna Ferita? Ho visto del Sangue laggiù e pensavo..."
  },
  AvgDialog_34981_Content_9 = {
    Text = "Si accovaccia accanto a te, scrutando da vicino il tuo polpaccio."
  },
  AvgDialog_34982_Content_1 = {
    Text = "Sporgi la testa dalla porta della plancia—i Navigatori infestano il ponte. Alcuni dall'aspetto normale, altri gonfi di Specie Parassita, altri simili a serpenti..."
  },
  AvgDialog_34982_Content_10 = {
    Text = "Vieni a vedere questo qui."
  },
  AvgDialog_34982_Content_11 = {
    Text = "Ramona scosta alghe aggrovigliate e frammenti di corallo, rivelando il Navigatore sepolto sotto."
  },
  AvgDialog_34982_Content_12 = {
    Text = "È morto anche lui—occhi di un grigio torbido, pelle viscida raggrinzita e rapidamente disidratata. Eppure, lo riconosci chiaramente."
  },
  AvgDialog_34982_Content_13 = {
    Text = "La sua pelle è bianca, spicca tra i Navigatori dal colore spento—come un'oca tra i passeri, o un destriero bianco tra asini grigi."
  },
  AvgDialog_34982_Content_14 = {
    Text = "Me lo ricordo—nessun segno di infestazione parassitaria, e non ci siamo trattenuti... ma cosa ha di speciale? A me sembra normale."
  },
  AvgDialog_34982_Content_15 = {
    Text = "Pensaci bene—quando ci siamo scontrati con Navigatori dalla pelle bianca?"
  },
  AvgDialog_34982_Content_16 = {
    Text = "Hmm... quando Golia ci stava inseguendo?"
  },
  AvgDialog_34982_Content_17 = {
    Text = "Aspetta, Golia?!"
  },
  AvgDialog_34982_Content_18 = {
    Text = "Giusto — quelli bianchi... sono le guardie di Golia."
  },
  AvgDialog_34982_Content_19 = {
    Text = "Golia... qualcuno l'ha visto dopo lo scontro nella sala macchine?"
  },
  AvgDialog_34982_Content_2 = {
    Text = "Uff... è stata dura.\nSe Tulu fosse qui, gestire questi sarebbe stato più facile."
  },
  AvgDialog_34982_Content_20 = {
    Text = "Era sparito prima dell'esplosione."
  },
  AvgDialog_34982_Content_21 = {
    Text = "Abbiamo commesso un errore potenzialmente fatale: ignorare completamente Golia."
  },
  AvgDialog_34982_Content_22 = {
    Text = "Non appena Ramona finisce di parlare, un impatto devastante sfonda la porta."
  },
  AvgDialog_34982_Content_23 = {
    Text = "Il ragazzo dal Risveglio ittico ritrae la sua alabarda, abbassando lo sguardo sui Navigatori riversi a terra. L'ombra di un enorme tubo ne nasconde metà, oscurandone l'espressione."
  },
  AvgDialog_34982_Content_24 = {Text = "Caecus!"},
  AvgDialog_34982_Content_25 = {
    Text = [[
Caecus nota il capitano, poi si volta, ignorando tutti all'interno.
Si fa da parte, inchinandosi profondamente verso il ponte, dando il benvenuto al suo nuovo padrone.]]
  },
  AvgDialog_34982_Content_26 = {
    Text = "Mio signore, sono effettivamente sul ponte."
  },
  AvgDialog_34982_Content_27 = {
    Text = "Il gigante entra con passi pesanti, afferrando lo stipite della porta sopra di sé, bloccando tutta la luce lunare dall'esterno."
  },
  AvgDialog_34982_Content_28 = {
    Text = [[
Tempo all'Allineamento:
60 minuti]]
  },
  AvgDialog_34982_Content_3 = {
    Text = "Nessun rumore dalle scale sottostanti—dovremmo avere una tregua per ora."
  },
  AvgDialog_34982_Content_4 = {
    Text = "Spingi col piede il Navigatore senza vita ai tuoi piedi."
  },
  AvgDialog_34982_Content_5 = {
    Text = "Nello scontro, hai preso di mira la protuberanza parassitaria comparsa all'improvviso come punto debole—la sua pelle si è lacerata sotto il tuo attacco, riversando un groviglio di viscere appiccicose."
  },
  AvgDialog_34982_Content_6 = {
    Text = "Non so se questo sangue contaminato dalla Dissoluzione sia tossico—sembra mescolato con parecchia D-melma. Ramona, li buttiamo fuori bordo?"
  },
  AvgDialog_34982_Content_7 = {
    Text = "Aspetta... Doll ha detto che non dovremmo, mi pare."
  },
  AvgDialog_34982_Content_8 = {
    Text = "Il <Italic:Manuale Operativo per Investigatori dell'Università di Mythag> è chiaro: a causa dei meccanismi di propagazione ancora poco chiari, evitare per quanto possibile che la D-melma entri in contatto con gli ecosistemi naturali."
  },
  AvgDialog_34982_Content_9 = {
    Text = "Sono contento che ricordi le lezioni di Doll, ma l'ecologia non è la priorità adesso."
  },
  AvgDialog_34983_Content_1 = {
    Text = "Voi ragazzi siete ancora della partita?"
  },
  AvgDialog_34983_Content_2 = {
    Text = "Sono solo Navigatori storditi e qualche Mutante da Dissoluzione."
  },
  AvgDialog_34983_Content_3 = {
    Text = "Si muovono a caso—senza un capo che li comandi. Sembrano attirati dal corno—possiamo gestirli."
  },
  AvgDialog_34983_Content_4 = {
    Text = "Bene—se hai bisogno d'aiuto, prova a chiamare il nome di Celeste nella tua mente."
  },
  AvgDialog_34983_Content_5 = {
    Text = "Ha perso il controllo della nave ora, ma questa imbarcazione è stata il suo territorio per anni. Scommetto che il suo potere ha lasciato tracce che ti aiuteranno."
  },
  AvgDialog_34983_Content_6 = {
    Text = "Motori al massimo—tenetevi forte, attenti al mal di mare!"
  },
  AvgDialog_35167_Content_1 = {
    Text = "Notte di Morte, Idromele e Canto"
  },
  AvgDialog_35167_Content_10 = {
    Text = "Ciò che questa donna pensa, nessuno può indovinarlo. Tuttavia—"
  },
  AvgDialog_35167_Content_11 = {
    Text = "La peste del Cambrian è incurabile. Se gli infetti venissero liberati, il cielo solo sa cosa accadrebbe."
  },
  AvgDialog_35167_Content_12 = {
    Text = "A prescindere dall'intenzione di Wanda, le sue azioni hanno effettivamente salvato i feudi circostanti..."
  },
  AvgDialog_35167_Content_13 = {
    Text = [[
Castello di Cambrian
Sala del Banchetto]]
  },
  AvgDialog_35167_Content_14 = {
    Text = "Spingete la pesante porta di legno della sala."
  },
  AvgDialog_35167_Content_15 = {
    Text = "Una luce abbagliante si riversa nella stanza come stelle cadute. L'aria è densa del dolce aroma di vino e cibi prelibati."
  },
  AvgDialog_35167_Content_16 = {
    Text = "I contadini del Cambrian hanno indossato i loro abiti migliori, danzando con gioia al ritmo della musica."
  },
  AvgDialog_35167_Content_17 = {
    Text = "Sebbene il mondo esterno sia sommerso dalla Dissoluzione, la sala resta colma di allegria."
  },
  AvgDialog_35167_Content_18 = {
    Text = "È questo il leggendario budino di mele? Non ho mai assaggiato nulla di così delizioso in vita mia..."
  },
  AvgDialog_35167_Content_19 = {
    Text = "Hahaha! Sono così felice! Se muoio stanotte, ne sarà valsa la pena!"
  },
  AvgDialog_35167_Content_2 = {
    Text = [[
Feudo di Guderian
Terreni di Caccia]]
  },
  AvgDialog_35167_Content_20 = {
    Text = "Danzate! Avanti, tutti danzate!"
  },
  AvgDialog_35167_Content_21 = {
    Text = "Ti fai strada tra la folla brulicante e trovi Wanda seduta all'estremità opposta."
  },
  AvgDialog_35167_Content_23 = {
    Text = "Si appoggia pigramente al servitore non morto, tenendo un bicchiere di vino rosso e osservandoti con aria rilassata."
  },
  AvgDialog_35167_Content_24 = {
    Text = "Buonasera, Monaco. Pensavo che non avresti partecipato a questo banchetto."
  },
  AvgDialog_35167_Content_25 = {
    Text = "A volte desidero soddisfare la mia curiosità."
  },
  AvgDialog_35167_Content_26 = {
    Text = "<Gray:E poi, con la D-melma ovunque là fuori, dove altro potrei mai andare...?>"
  },
  AvgDialog_35167_Content_27 = {
    Text = "Qualcuno tira delicatamente il lembo della vostra veste."
  },
  AvgDialog_35167_Content_28 = {
    Text = "Tu sei... il fratello di Susanna!"
  },
  AvgDialog_35167_Content_29 = {
    Text = "Ho un nome, sapete! Tutti mi chiamano Piccolo Beckman."
  },
  AvgDialog_35167_Content_3 = {
    Text = "Cosa? Dici che Wanda ha fuso tutte le serrature e sta organizzando un sontuoso ballo nel castello con tutti i villici di Cambrian?"
  },
  AvgDialog_35167_Content_30 = {
    Text = "Buonasera, Piccolo Beckman. Dov'è andata tua sorella?"
  },
  AvgDialog_35167_Content_31 = {
    Text = "La sorella maggiore e gli altri che non erano malati sono partiti insieme..."
  },
  AvgDialog_35167_Content_32 = {
    Text = "Il Piccolo Beckman china il capo, avvilito. Tira su col naso, poi alza lo sguardo verso di voi con occhi spalancati e lucidi."
  },
  AvgDialog_35167_Content_33 = {
    Text = "Buon signore, volete danzare con me? Non ho un compagno, sniff sniff..."
  },
  AvgDialog_35167_Content_34 = {
    Text = "Piccolo mio, ai monaci non è permesso danzare."
  },
  AvgDialog_35167_Content_35 = {
    Text = "Ora dichiaro che potete danzare. Dimenticate quei vecchi cliché."
  },
  AvgDialog_35167_Content_36 = {
    Text = "A Cambrian, io—<Big:SONO LA LEGGE STESSA!>"
  },
  AvgDialog_35167_Content_37 = {
    Text = "Guardate negli occhi pieni di Speranza del Piccolo Beckman e ingoiate il vostro rifiuto."
  },
  AvgDialog_35167_Content_38 = {
    Text = "Mi dispiace, nemmeno io sono un gran ballerino, ma posso fare qualche giro con te."
  },
  AvgDialog_35167_Content_39 = {
    Text = "Prendete la Mano del Piccolo Beckman e lo conducete al centro della sala, unendovi al mare di Abitanti del villaggio che ondeggiano al ritmo della melodia."
  },
  AvgDialog_35167_Content_4 = {
    Text = "È la pura verità! Ho sentito che quelli non infetti se ne sono andati tutti. Gli unici rimasti a quella danza sono i malati terminali."
  },
  AvgDialog_35167_Content_40 = {
    Text = "Le gonne svolazzano e turbinano nella luce delle candele come un migliaio di dolcetti colorati che ruotano su se stessi."
  },
  AvgDialog_35167_Content_41 = {
    Text = "Vagate attraverso questo oceano dorato di luce e canto, infine sommersi dalle bolle crescenti di Gioia."
  },
  AvgDialog_35167_Content_42 = {
    Text = "I passi del Piccolo Beckman non sono migliori dei vostri. Si dimena senza meta a tempo di musica, il volto che si accende di un rosso vivo e felice."
  },
  AvgDialog_35167_Content_43 = {
    Text = "Ahahah! Che felicità! Questo è il giorno più bello della mia Vita!"
  },
  AvgDialog_35167_Content_44 = {
    Text = "Signore, prendete la mia mano! Giriamo insieme!"
  },
  AvgDialog_35167_Content_45 = {
    Text = "Più veloce, ancora più veloce!"
  },
  AvgDialog_35167_Content_46 = {
    Text = "<Red:Più veloce...>"
  },
  AvgDialog_35167_Content_47 = {
    Text = "Più velo@2..."
  },
  AvgDialog_35167_Content_48 = {
    Text = "Piccolo Beckman, la tua faccia?!"
  },
  AvgDialog_35167_Content_49 = {
    Text = "<Change>Danzate con me..."
  },
  AvgDialog_35167_Content_5 = {
    Text = "Hahaha! Mi sono dato tanta pena per piazzare una talpa al suo fianco... sembra che abbia sprecato le mie energie."
  },
  AvgDialog_35167_Content_50 = {
    Text = "D-melma nera come inchiostro comincia a colare dagli Occhi del Ragazzo, eppure continua a sorridere mentre allunga le mani verso di voi."
  },
  AvgDialog_35167_Content_51 = {
    Text = "Il tuo naso avverte improvvisamente un brivido di freddo. Alzi lo sguardo e una melma nera gocciola lentamente dal lampadario."
  },
  AvgDialog_35167_Content_52 = {
    Text = "Una goccia. Due."
  },
  AvgDialog_35167_Content_53 = {
    Text = "Ti guardi intorno in preda al panico e noti che i vestiti, le braccia e persino i volti di molte persone mostrano già vari gradi di decomposizione."
  },
  AvgDialog_35167_Content_54 = {
    Text = "Ma continuano a danzare felici."
  },
  AvgDialog_35167_Content_55 = {
    Text = "Signore, perché mi ignorate? Non vi piaccio più...?"
  },
  AvgDialog_35167_Content_56 = {
    Text = "Il ragazzo allunga le mani appiccicose per abbracciarti, il dolore trabocca dai suoi occhi vuoti."
  },
  AvgDialog_35167_Content_57 = {
    Text = "Resta con me... Resta con me..."
  },
  AvgDialog_35167_Content_6 = {
    Text = "Con una peste così orribile, non tenta nemmeno di fuggire. Li chiude tutti dentro ad aspettare la morte..."
  },
  AvgDialog_35167_Content_7 = {
    Text = "È vero, come dicono le voci, che è completamente impazzita?"
  },
  AvgDialog_35167_Content_8 = {
    Text = "Le vostre parole sono piuttosto intriganti. È mai stata una donna di sano intelletto, tanto per cominciare?"
  },
  AvgDialog_35167_Content_9 = {
    Text = "Ehm... beh..."
  },
  AvgDialog_35529_Content_1 = {
    Text = "Capitano, vi fidate davvero delle parole di quel pesciolino? Non è un semplice galoppino del culto."
  },
  AvgDialog_35529_Content_10 = {
    Text = "Caecus... brama semplicemente troppo il riconoscimento."
  },
  AvgDialog_35529_Content_11 = {
    Text = "So che potresti avere dei dubbi su di lui, ma conosco quel ragazzo abbastanza bene. Il fatto che venga da noi di sua spontanea volontà dimostra che nel suo cuore ha già preso una posizione."
  },
  AvgDialog_35529_Content_12 = {
    Text = "Entrerò prima io nella plancia per controllare la situazione. Se tutto è in ordine, vi chiamerò dentro."
  },
  AvgDialog_35529_Content_2 = {
    Text = "Se ricordo bene, il Potere spirituale di Caecus per restare razionale come Risvegliato gli è stato persino fornito da Miryam... L'avete confermato voi stesso."
  },
  AvgDialog_35529_Content_3 = {
    Text = "Inoltre, se non ci fossimo fidati del messaggio che ha inviato, non saremmo rimasti in quel porto..."
  },
  AvgDialog_35529_Content_4 = {
    Text = "Un messaggio?"
  },
  AvgDialog_35529_Content_5 = {
    Text = "Murphy lancia un'occhiata a Elton e, dopo aver ricevuto il suo silenzioso cenno di approvazione, si schiarisce la gola e prosegue."
  },
  AvgDialog_35529_Content_6 = {
    Text = "Il nostro piano iniziale era restare nel Dominio di Sona-Nyl per sei mesi interi, per evitare l'Allineamento."
  },
  AvgDialog_35529_Content_7 = {
    Text = "Dopodiché avremmo viaggiato per il mondo, sfuggendo alla Caccia dei Navigatori mentre cercavamo un modo per rimuovere la Specie Parassita, ma..."
  },
  AvgDialog_35529_Content_8 = {
    Text = [[
Ma durante una sosta per i rifornimenti, ho ricevuto un messaggio dall'intermediario.

Il messaggio diceva che Caecus era disposto a darmi la medicina per un'ultima volta.]]
  },
  AvgDialog_35529_Content_9 = {
    Text = "Il luogo stabilito è Bridgeport? È la città di Pesca dove i Navigatori ci hanno raggiunto sulla nave."
  },
  AvgDialog_35530_Content_1 = {
    Text = [[
Tulu, per favore proteggi Murphy e Celeste fuori dalla plancia.

Io e Ramona seguiremo il capitano all'interno per controllare la situazione.]]
  },
  AvgDialog_35530_Content_2 = {
    Text = "Tulu non obietta. Usando i suoi Tentacoli, impedisce a Murphy di seguirli e trascina lei e Celeste nelle Ombre accanto alla porta."
  },
  AvgDialog_35530_Content_3 = {
    Text = "Elton si avvicina a te e ti scosta la mano dal portello."
  },
  AvgDialog_35530_Content_4 = {
    Text = "Lascia che me ne occupi io."
  },
  AvgDialog_35530_Content_5 = {
    Text = "La plancia è effettivamente priva di Golia, con solo alcuni Navigatori che vagano intorno in stato confusionale."
  },
  AvgDialog_35530_Content_6 = {
    Text = [[
Nessun segno di un'imboscata.

Il capitano aveva ragione... Caecus non mentiva.]]
  },
  AvgDialog_35530_Content_7 = {
    Text = "Haha, te l'avevo detto, Caecus non è malvagio per natura... Semplicemente nessuno gli ha insegnato cosa sia giusto."
  },
  AvgDialog_35530_Content_8 = {
    Text = "Ora tocca a voi occuparvi dei pochi rimasti. Non lasciate che interferiscano ancora con il mio timone."
  },
  AvgDialog_35531_Content_1 = {
    Text = "Tu e Ramona fate una deviazione e finalmente arrivate alla porta sull'altro lato della sala macchine."
  },
  AvgDialog_35531_Content_10 = {
    Text = "Ramona sussurra e indica i Navigatori colpiti dal \"Cataclisma,\" dai cui ventri sono cresciute delle Specie Parassite."
  },
  AvgDialog_35531_Content_11 = {
    Text = "Evitiamoli il più possibile. Controllare le caldaie è la nostra priorità assoluta."
  },
  AvgDialog_35531_Content_2 = {
    Text = "Questa porta è rimasta coinvolta nel fuoco incrociato durante la vostra battaglia con Miryam. Il pannello è completamente deformato, appeso precariamente al telaio. Riesci a passare attraverso senza troppa fatica."
  },
  AvgDialog_35531_Content_3 = {Text = "Questo—"},
  AvgDialog_35531_Content_4 = {
    Text = "Ramona ti copre rapidamente la bocca e ti trascina dietro alcuni detriti di lamiera."
  },
  AvgDialog_35531_Content_5 = {
    Text = "Portatori di lance, spadaccini, figure gobbe, che strisciano sul pavimento..."
  },
  AvgDialog_35531_Content_6 = {
    Text = "Ovunque si posi lo sguardo, Navigatori in pose diverse. Si aggirano tra le rovine della sala macchine, ammassando materiali carbonizzati dalle esplosioni."
  },
  AvgDialog_35531_Content_7 = {
    Text = "Frugate nella vostra mente per un po' prima di trovare una parola per descrivere questo comportamento—"
  },
  AvgDialog_35531_Content_8 = {
    Text = "\"Nidificazione\"."
  },
  AvgDialog_35531_Content_9 = {
    Text = "In effetti... Mostrano un tipico comportamento di nidificazione. Forse influenzati dal nucleo del Cataclisma, tentano di generare quelle iperplasie..."
  },
  AvgDialog_35532_Content_1 = {Text = "Precipizio"},
  AvgDialog_35532_Content_10 = {
    Text = "Per l'impotenza, volgi lo sguardo alla luna fuori dalla finestra."
  },
  AvgDialog_35532_Content_11 = {
    Text = "La luna è troppo grande e troppo luminosa.\n\nMetodi come la Distanza Lunare e la Selezione Stellare sono inefficaci in queste condizioni."
  },
  AvgDialog_35532_Content_12 = {
    Text = "Guidata da Ramona, ti volti a guardare la luna piena straordinariamente grande."
  },
  AvgDialog_35532_Content_13 = {
    Text = "È anormalmente grande, e ricopre il cielo notturno e il mare di un bagliore identico a quello della luna piena."
  },
  AvgDialog_35532_Content_14 = {
    Text = "Ti rendi conto che si sta avvicinando. Così vicina che il tuo spirito sembra percepirne la radiazione anomala, al tempo stesso gelida e bruciante."
  },
  AvgDialog_35532_Content_15 = {
    Text = "Huff... Huff..."
  },
  AvgDialog_35532_Content_16 = {
    Text = "Allineamento..."
  },
  AvgDialog_35532_Content_17 = {
    Text = "Il respiro di Murphy si fa più pesante, e quando tutti gli occhi si volgono verso di lei, ogni respiro è accompagnato da un suono simile a un fischio, quasi come una perdita d'aria."
  },
  AvgDialog_35532_Content_18 = {
    Text = "Murphy? Stai bene? Lascia che ti aiuti a sederti e a fare un po' di riposo."
  },
  AvgDialog_35532_Content_19 = {
    Text = "Sto benissimo! Cough, cough..."
  },
  AvgDialog_35532_Content_2 = {
    Text = "Celeste, qual è la direzione del vento?"
  },
  AvgDialog_35532_Content_20 = {
    Text = "Murphy alza la voce per risponderti ma accidentalmente si strozza e inizia a tossire violentemente."
  },
  AvgDialog_35532_Content_21 = {
    Text = "Tutti vedono che si regge a malapena."
  },
  AvgDialog_35532_Content_22 = {Text = "..."},
  AvgDialog_35532_Content_23 = {
    Text = "Ma mi sento un po' \"a disagio.\""
  },
  AvgDialog_35532_Content_24 = {
    Text = "Le gambe non mi reggono più, e la testa mi duole ancora un po'."
  },
  AvgDialog_35532_Content_25 = {
    Text = "Mentre parli, ti siedi appoggiandoti alla parete della plancia."
  },
  AvgDialog_35532_Content_26 = {
    Text = "Con la tua \"caduta,\" Murphy smette di fingere che vada tutto bene. Perde istantaneamente le forze e si trascina lungo la parete fino al tuo fianco."
  },
  AvgDialog_35532_Content_27 = {
    Text = "Allora io... mi prendo una pausa... Un momento..."
  },
  AvgDialog_35532_Content_28 = {
    Text = "Si appoggia alla parete e scivola a terra, senza più curarsi che la sua postura sia composta o meno."
  },
  AvgDialog_35532_Content_29 = {
    Text = "Cerca un punto d'appoggio per impedirsi di crollare del tutto. Dopo qualche tentativo a tastoni, si appoggia alla tua spalla."
  },
  AvgDialog_35532_Content_3 = {
    Text = "Celeste sporge la mano oltre la porta, occhi chiusi, percependo la tua direzione e sentendo la brezza marina colpirle il polso sottile."
  },
  AvgDialog_35532_Content_30 = {
    Text = "Solo un momento..."
  },
  AvgDialog_35532_Content_31 = {
    Text = [[
In pochi secondi, un respiro rapido ma ritmico raggiunge le tue orecchie.

Murphy perde conoscenza ancora una volta.]]
  },
  AvgDialog_35532_Content_32 = {
    Text = "Orribili segni nero-bluastri compaiono sul volto di Murphy, simili a radici di pianta profondamente incastonate sotto la pelle, che prosciugano la sua fragile vita."
  },
  AvgDialog_35532_Content_33 = {
    Text = "Il Dio con cui comunico proviene da miriadi di stelle. Persino una mera replica è al di là della resistenza umana."
  },
  AvgDialog_35532_Content_34 = {
    Text = "Il flusso sanguigno dell'ospite viene reciso dal Feto."
  },
  AvgDialog_35532_Content_35 = {
    Text = "E se eseguissimo l'operazione adesso?"
  },
  AvgDialog_35532_Content_36 = {
    Text = "Custode, ci mancano semplicemente le condizioni necessarie per operarla in questo momento."
  },
  AvgDialog_35532_Content_37 = {
    Text = "La velocità massima è già stata raggiunta. Con la caldaia danneggiata, non possiamo andare più forte."
  },
  AvgDialog_35532_Content_38 = {
    Text = "Impossibile operare, e nessun modo di tornare a terra in tempo... Non esiste davvero alcuna soluzione?"
  },
  AvgDialog_35532_Content_39 = {
    Text = "Tulu volge lo sguardo all'enorme luna fuori dall'oblò e scuote il capo."
  },
  AvgDialog_35532_Content_4 = {
    Text = "Vento da ovest, 22 nodi."
  },
  AvgDialog_35532_Content_40 = {
    Text = "Anche tu sei in difficoltà? Non c'è nulla che tu possa fare, tu che hai pronunciato la profezia della rinascita degli dèi?"
  },
  AvgDialog_35532_Content_41 = {
    Text = "Come potresti saperlo..."
  },
  AvgDialog_35532_Content_42 = {
    Text = "Dall'atteggiamento di Miryam nei tuoi confronti e dalle sue parole frammentarie prima di sprofondare nella follia, la verità non è difficile da dedurre."
  },
  AvgDialog_35532_Content_43 = {
    Text = "Solo il tradimento della divinità potrebbe spingere una devota a un simile stato di follia."
  },
  AvgDialog_35532_Content_44 = {Text = "...Sì."},
  AvgDialog_35532_Content_45 = {
    Text = "In effetti, le ho consegnato una tale profezia, ma il cosiddetto \"oracolo\" non esiste."
  },
  AvgDialog_35532_Content_46 = {Text = "Cosa?"},
  AvgDialog_35532_Content_47 = {
    Text = "Molto prima che il diluvio arrivasse, avevo perso la capacità di intravedere il futuro nei Suoi sogni./nNon so dove sia andato; potrebbe essersi risvegliato, o potrebbe essersene andato."
  },
  AvgDialog_35532_Content_48 = {
    Text = "Allora, la tua profezia..."
  },
  AvgDialog_35532_Content_49 = {
    Text = "Miryam è una credente devota, consacrata al Reame Divino e mossa dalla mia volontà."
  },
  AvgDialog_35532_Content_5 = {
    Text = "Ricevuto, correggo la rotta."
  },
  AvgDialog_35532_Content_50 = {
    Text = "Speravo soltanto che le mie parole la confortassero nei suoi ultimi istanti, senza mai immaginare che le avrebbe prese come verità assoluta e avrebbe cercato di ricostruire il Reame Divino."
  },
  AvgDialog_35532_Content_51 = {
    Text = "Tutto quanto era..."
  },
  AvgDialog_35532_Content_52 = {
    Text = "La colpa è interamente mia."
  },
  AvgDialog_35532_Content_53 = {
    Text = "L'istante successivo, è come se il mondo avesse premuto il tasto di pausa: ogni suono svanisce."
  },
  AvgDialog_35532_Content_54 = {
    Text = "Se non fosse per il faint respiro di Murphy su di te, potresti pensare che persino il tempo si sia fermato."
  },
  AvgDialog_35532_Content_55 = {
    Text = "Aspettate... non sento più il rumore delle eliche che battono l'acqua."
  },
  AvgDialog_35532_Content_56 = {
    Text = "Elton torna in sé, cammina avanti e indietro attorno alla consolle e tenta ogni operazione che gli viene in mente, ma invano."
  },
  AvgDialog_35532_Content_57 = {
    Text = "La Sona-Nyl galleggia silenziosa tra le onde, come un gigante solitario abbracciato dal mare."
  },
  AvgDialog_35532_Content_58 = {
    Text = "L'alimentazione energetica ha dei problemi. Vado in sala macchine a controllare."
  },
  AvgDialog_35532_Content_59 = {
    Text = [[
Lascia fare a me. So qualcosa di strutture meccaniche.

Se si tratta solo di accensione e riparazioni semplici, posso farcela.]]
  },
  AvgDialog_35532_Content_6 = {
    Text = "Elton si posiziona nuovamente al timone. Senza nemici a interferire, governa la nave con una ritrovata sicurezza."
  },
  AvgDialog_35532_Content_60 = {
    Text = "Verrò con voi."
  },
  AvgDialog_35532_Content_61 = {
    Text = "Tulu, affido a te l'incolumità di tutti gli altri mentre Ramona e io andiamo a indagare."
  },
  AvgDialog_35532_Content_62 = {
    Text = "Tulu annuisce e protende un tentacolo per aiutarti ad adagiare delicatamente Murphy a terra."
  },
  AvgDialog_35532_Content_63 = {
    Text = "L'ultima volta che ho fatto manutenzione allo scafo, ho sostituito le candele di accensione in diverse caldaie. Se il fuoco si spegne, puoi riaccenderlo aggiungendo abbastanza carbone e usando il dispositivo."
  },
  AvgDialog_35532_Content_64 = {
    Text = "Bene, andiamo adesso."
  },
  AvgDialog_35532_Content_65 = {
    Text = "Fai un cenno a Ramona e stai per muoverti quando una mano gelida ti afferra delicatamente la caviglia."
  },
  AvgDialog_35532_Content_66 = {
    Text = "Murphy lotta per mettersi seduta; i segni neri sul suo volto si attenuano mentre l'ossigeno fluisce dentro e fuori."
  },
  AvgDialog_35532_Content_67 = {
    Text = "È debole come un fiore avvizzito, ora. La sua voce è un sussurro esausto, eppure porta ancora in sé un nucleo di sfida."
  },
  AvgDialog_35532_Content_68 = {
    Text = "Tornerete... vero?"
  },
  AvgDialog_35532_Content_69 = {
    Text = "Sì, torneremo."
  },
  AvgDialog_35532_Content_7 = {
    Text = "Lui e Celeste lavorano insieme per governare il grande mercantile, che normalmente richiederebbe almeno un equipaggio per essere manovrato."
  },
  AvgDialog_35532_Content_70 = {
    Text = "Ti accovacci accanto a lei, stringendole forte la mano, cercando di trasmetterle calore."
  },
  AvgDialog_35532_Content_71 = {
    Text = "Non avevamo promesso di riportarti sulla terraferma?"
  },
  AvgDialog_35532_Content_8 = {
    Text = "Raffiche di vento sollevano occasionalmente spruzzi d'acqua nell'aria, ma sotto il loro controllo, la Sona-Nyl resta stabile come un giocattolo che galleggia in una vasca da bagno."
  },
  AvgDialog_35532_Content_9 = {
    Text = "Sono così esperti. Sanno quale direzione prendere senza alcuno strumento."
  },
  AvgDialog_35533_Content_1 = {
    Text = "Vecchi Legami, Nuovi"
  },
  AvgDialog_35533_Content_10 = {
    Text = "Sono ancora me stessa?"
  },
  AvgDialog_35533_Content_11 = {
    Text = "Chi... sono io?"
  },
  AvgDialog_35533_Content_12 = {Text = "..."},
  AvgDialog_35533_Content_13 = {Text = "..."},
  AvgDialog_35533_Content_14 = {
    Text = "Perso in un luogo sconosciuto, non sai quanto tempo sia passato."
  },
  AvgDialog_35533_Content_15 = {
    Text = "Non avverti nulla se non il suono del flauto che si intensifica gradualmente."
  },
  AvgDialog_35533_Content_16 = {
    Text = "Basta... Basta! Non è il momento per la musica; ho ancora cose da fare!"
  },
  AvgDialog_35533_Content_17 = {
    Text = "Il suono del flauto si fa più forte, ma quando supera la soglia di tolleranza umana, si interrompe bruscamente, lasciando solo un rumore bianco indistinguibile a riecheggiare nel vuoto."
  },
  AvgDialog_35533_Content_18 = {
    Text = "<Change>Eterna..."
  },
  AvgDialog_35533_Content_19 = {
    Text = "Un suono persistente riecheggia dalle profondità dell'universo, simile a un farneticare caotico nel sonno o a un agitarsi inquieto che turba le stelle."
  },
  AvgDialog_35533_Content_2 = {
    Text = "La tua coscienza si distacca dal corpo, vagando e indugiando in un sogno illusorio."
  },
  AvgDialog_35533_Content_20 = {
    Text = "Un bagliore argenteo sboccia sul posto, e i tuoi nervi tesi cominciano a sciogliersi."
  },
  AvgDialog_35533_Content_21 = {
    Text = "Il tuo spazio di coscienza è luminoso come il giorno. Prima che tu possa reagire, avverti un improvviso precipitare—"
  },
  AvgDialog_35533_Content_22 = {
    Text = "{Male=Lui,Female=Lei} sta per risvegliarsi."
  },
  AvgDialog_35533_Content_23 = {
    Text = "Custode, %player%! Riesci a sentire la mia voce?"
  },
  AvgDialog_35533_Content_24 = {
    Text = "...Cos'è successo?"
  },
  AvgDialog_35533_Content_25 = {
    Text = "Con l'aiuto di Ramona, ti siedi e ti guardi intorno, scoprendo di trovarti in una stiva, circondato da D-iperplasia e dai tuoi compagni."
  },
  AvgDialog_35533_Content_26 = {
    Text = "Come ti senti?"
  },
  AvgDialog_35533_Content_27 = {
    Text = "Abbassi lo sguardo sulle mani, cercando di canticchiare la melodia appena udita, ma scopri che riesci solo a espirare a raffiche."
  },
  AvgDialog_35533_Content_28 = {
    Text = "Mi sento... bene."
  },
  AvgDialog_35533_Content_29 = {
    Text = "Sei svenuta tre volte ormai. Stai davvero bene? Non mentirmi."
  },
  AvgDialog_35533_Content_3 = {
    Text = "Dove... sono?"
  },
  AvgDialog_35533_Content_30 = {
    Text = "Svenimenti improvvisi e frequenti in un breve periodo... Potrebbe significare lesioni intracraniche o al sistema nervoso."
  },
  AvgDialog_35533_Content_31 = {
    Text = "Ramona parla mentre ti esamina meticolosamente la testa ancora una volta, premendo delicatamente con la punta delle dita quasi ogni centimetro del tuo cranio."
  },
  AvgDialog_35533_Content_32 = {
    Text = "Non si riscontrano fratture, ma se ci fosse un ematoma o un'altra infezione... dobbiamo tornare a scuola e farti esaminare da Doll prima di formulare una diagnosi."
  },
  AvgDialog_35533_Content_33 = {
    Text = "La priorità assoluta è tornare a terra e affrettarsi a rientrare a scuola.\n\nQuesto è fondamentale sia per te che per Murphy..."
  },
  AvgDialog_35533_Content_34 = {
    Text = "Murphy ti fissa in silenzio a lungo prima di scuotere la testa, l'espressione vuota."
  },
  AvgDialog_35533_Content_35 = {
    Text = "Sei già in questo stato, quindi non cercare di fare l'eroe.\n\nDovresti andartene."
  },
  AvgDialog_35533_Content_36 = {
    Text = "Prendete la scialuppa di salvataggio. Che remiate o vi lasciate trasportare dalla corrente, con Tulu e Ramona presenti, raggiungere la riva non sarà un problema. A patto che... A patto che..."
  },
  AvgDialog_35533_Content_37 = {
    Text = "<Small:Purché io non sia lì a causarti altri problemi...>"
  },
  AvgDialog_35533_Content_38 = {
    Text = "Non me ne andrò prima che la Specie Parassita nel tuo corpo sia stata eliminata."
  },
  AvgDialog_35533_Content_39 = {
    Text = "Murphy batte il piede, indica te e Ramona, poi il Capitano e Celeste."
  },
  AvgDialog_35533_Content_4 = {
    Text = "Avvolta dall'Oscurità, la piccola luce d'Argento intorno a te viene rapidamente divorata dal nero che avanza."
  },
  AvgDialog_35533_Content_40 = {
    Text = "E loro?\n\nE se questo \"Dio\" si schiudesse e fosse così grande da far affondare la nave?"
  },
  AvgDialog_35533_Content_41 = {
    Text = "Nemmeno noi ce ne andremo."
  },
  AvgDialog_35533_Content_42 = {Text = "Eh?!"},
  AvgDialog_35533_Content_43 = {
    Text = "Il giorno in cui siamo diventati ufficialmente Investigatori, abbiamo giurato sulla nostra esistenza di combattere la Dissoluzione a ogni costo."
  },
  AvgDialog_35533_Content_44 = {
    Text = "Siamo preparati a trascorrere il resto delle nostre vite in compagnia della morte e della Follia, anche se la nostra stessa fine ci attende più avanti..."
  },
  AvgDialog_35533_Content_45 = {
    Text = "Non farmi ridere! Se restate, morirete tutti!\n\nQuesto parassita dentro di me è un mostro, un dio!"
  },
  AvgDialog_35533_Content_46 = {
    Text = "Allora, se questa fosse l'ultima ora della mia vita, non la sprecherò in Preghiera."
  },
  AvgDialog_35533_Content_47 = {
    Text = "Credo che la pensi allo stesso modo, giusto? Altrimenti, perché ti saresti data tanta pena per fuggire dal culto?"
  },
  AvgDialog_35533_Content_48 = {Text = "Io..."},
  AvgDialog_35533_Content_49 = {
    Text = "Non è solo per te. Ricorda, anche noi siamo in Attesa di scendere dalla nave."
  },
  AvgDialog_35533_Content_5 = {
    Text = "Senti qualcosa scivolare via dal tuo Reame dello Spirito. Tendi la mano nell'Oscurità e scopri che si tratta di un Frammento della tua memoria."
  },
  AvgDialog_35533_Content_50 = {
    Text = "La Specie Parassita dentro di te è ora divenuta il nucleo della Dissoluzione Catastrofica del Mondo, il che significa che anche tu sei ormai una delle responsabilità degli Investigatori Mythag."
  },
  AvgDialog_35533_Content_51 = {
    Text = "Ho promesso di non Rinunciare a te... Non infrangerò la mia promessa."
  },
  AvgDialog_35533_Content_52 = {
    Text = "...Pazzi. Tutti quanti."
  },
  AvgDialog_35533_Content_53 = {
    Text = "Murphy tira su col naso, soffocando il singhiozzo nella voce."
  },
  AvgDialog_35533_Content_54 = {
    Text = "Dunque, che facciamo adesso? L'equipaggio di Golia ha preso il ponte di comando. Non possiamo governare la nave in queste condizioni."
  },
  AvgDialog_35533_Content_55 = {
    Text = "Celeste, quanto manca all'attracco?"
  },
  AvgDialog_35533_Content_56 = {
    Text = [[
Carico a vuoto, vento di nordest a 15 nodi.

...Ora standard di Kadath, 60 minuti.]]
  },
  AvgDialog_35533_Content_57 = {
    Text = "Quanto tempo ci resta..."
  },
  AvgDialog_35533_Content_58 = {
    Text = "C'è ancora tempo."
  },
  AvgDialog_35533_Content_59 = {
    Text = "Celeste fissa il Capitano con sguardo vacuo, come se cercasse di confermare qualcosa."
  },
  AvgDialog_35533_Content_6 = {
    Text = "Nei tuoi ricordi, Ramona ti riporta all'Università di Mythag. Doll ti accoglie nella piazza della scuola, mostrando preoccupazione per Ramona e nutrendo dubbi su di te."
  },
  AvgDialog_35533_Content_60 = {
    Text = "La sua forma è già divenuta traslucida, come se stesse svanendo dalla realtà. Il Capitano Elton allunga la mano per accarezzarle la testa, ma alla fine sfiora soltanto l'aria sopra di lei."
  },
  AvgDialog_35533_Content_61 = {
    Text = "Celeste, accelera."
  },
  AvgDialog_35533_Content_62 = {
    Text = "Capitano! Che cosa fate!? Tu e Celeste siete in condizioni così precarie, non potete più usare le vostre abilità per governare la nave!"
  },
  AvgDialog_35533_Content_63 = {
    Text = "La Risvegliatrice annuisce lievemente e alza entrambe le mani. La bussola nella sua mano si muove da sola, emanando deboli bagliori."
  },
  AvgDialog_35533_Content_64 = {
    Text = "Elton, fermati!"
  },
  AvgDialog_35533_Content_65 = {
    Text = "Caecus sfonda la porta della cabina. Non appena mette piede all'interno, Ramona e Tulu si alzano entrambi per sbarrargli il cammino."
  },
  AvgDialog_35533_Content_66 = {
    Text = "Celeste abbassa la mano con Confusione, guardando Elton, in attesa del prossimo comando dal suo Connettore."
  },
  AvgDialog_35533_Content_67 = {
    Text = "Non sono qui per combatterti."
  },
  AvgDialog_35533_Content_68 = {
    Text = "Io... ho qualcosa che voglio darti."
  },
  AvgDialog_35533_Content_69 = {
    Text = "Il suo sguardo spazza su Tutti e si posa sul Capitano Elton."
  },
  AvgDialog_35533_Content_7 = {Text = "Allora..."},
  AvgDialog_35533_Content_70 = {
    Text = "Elton ti fa un cenno con la mano, avvicinandosi a Caecus mentre segnala a Ramona e Tulu di abbassare le posizioni di Attacco."
  },
  AvgDialog_35533_Content_71 = {
    Text = "Non avvicinarti...!"
  },
  AvgDialog_35533_Content_72 = {
    Text = "Non avvicinarti troppo. Se percepisco troppo il tuo odore, gli altri Navigatori mi noteranno."
  },
  AvgDialog_35533_Content_73 = {
    Text = "Lancia una fiala di vetro sul ponte, lasciandola rotolare fino ai piedi di Elton con l'inclinazione della nave."
  },
  AvgDialog_35533_Content_74 = {
    Text = "Medicina per stabilizzare lo spirito... Me la stai dando di tua spontanea volontà?"
  },
  AvgDialog_35533_Content_75 = {
    Text = "Se ti preoccupi per la sicurezza..."
  },
  AvgDialog_35533_Content_76 = {
    Text = "Elton non dà a Caecus il tempo di finire. Estrae il tappo e ingoia una manciata di pillole senza esitazione."
  },
  AvgDialog_35533_Content_77 = {
    Text = [[
Non fraintendermi, ragazzo.

Sono solo preoccupato che tu possa subire una punizione interna dai Navigatori.]]
  },
  AvgDialog_35533_Content_78 = {Text = "..."},
  AvgDialog_35533_Content_79 = {
    Text = "Non lo scopriranno. Il responsabile di queste medicine è già morto durante questa Operazione."
  },
  AvgDialog_35533_Content_8 = {
    Text = "Poi le tue memorie svaniscono rapidamente, come acqua che scorre."
  },
  AvgDialog_35533_Content_80 = {
    Text = "Caecus chiude gli occhi, l'Espressione calma. Non si riesce a capire se pianga i compagni Decaduti."
  },
  AvgDialog_35533_Content_81 = {
    Text = "Capitano, se ancora ti fidi di me... per favore, fai una deviazione per tornare al ponte di comando."
  },
  AvgDialog_35533_Content_82 = {
    Text = "Tornerò indietro e cercherò di distrarre Lord Golia, ma se propongo di evacuare Tutti, sembrerà troppo intenzionale."
  },
  AvgDialog_35533_Content_83 = {
    Text = "Lord Golia lascerà sicuramente qualcuno a sorvegliare il ponte. Quanto ai Navigatori rimasti indietro, sono impotente."
  },
  AvgDialog_35533_Content_84 = {
    Text = "Caecus finisce di parlare e si volta per andarsene."
  },
  AvgDialog_35533_Content_85 = {
    Text = "Caecus, aspetta!"
  },
  AvgDialog_35533_Content_86 = {
    Text = "Non è il momento giusto per rimetterci in pari, ma..."
  },
  AvgDialog_35533_Content_87 = {
    Text = "Hai detto che non mi avresti portato rancore per il mio Tradimento. È vero?"
  },
  AvgDialog_35533_Content_88 = {Text = "..."},
  AvgDialog_35533_Content_89 = {
    Text = "Assolutamente."
  },
  AvgDialog_35533_Content_9 = {
    Text = "Un suono di flauto sinistro e lontano trafigge la tua mente come un uncino, sigillando istantaneamente tutti i tuoi sensi."
  },
  AvgDialog_35534_Content_1 = {
    Text = "Lo scivolo del carbone di questa caldaia è bloccato. Sembra che sia rotto da molto tempo."
  },
  AvgDialog_35534_Content_10 = {
    Text = "Ramona annuisce, si accovaccia nell'ombra proiettata dalla caldaia e inizia a ispezionare i macchinari."
  },
  AvgDialog_35534_Content_11 = {
    Text = "Il Capitano ha ragione; la candela è nuova."
  },
  AvgDialog_35534_Content_12 = {
    Text = "A occhio nudo, la parete esterna della caldaia appare intatta... Sembra nuova di zecca."
  },
  AvgDialog_35534_Content_13 = {
    Text = "Questo è un angolo riparato; il vento che soffia dalla breccia nello scafo non dovrebbe aver danneggiato la caldaia... Dove si è verificato il guasto?"
  },
  AvgDialog_35534_Content_14 = {
    Text = "Forse ha esaurito il carburante?"
  },
  AvgDialog_35534_Content_15 = {
    Text = "Ramona annuisce, gira davanti alla caldaia e apre lo sportello. Si blocca sotto shock."
  },
  AvgDialog_35534_Content_16 = {
    Text = "Che succede?"
  },
  AvgDialog_35534_Content_17 = {
    Text = "Prima che tu possa reagire, Ramona ti trascina rapidamente verso le porte della sala macchine, incurante che i suoi passi possano disturbare i Navigatori annidati."
  },
  AvgDialog_35534_Content_18 = {
    Text = "La fornace è bagnata! Qualcuno ha deliberatamente spento la caldaia di alimentazione!"
  },
  AvgDialog_35534_Content_19 = {
    Text = "Una Trappola?!"
  },
  AvgDialog_35534_Content_2 = {
    Text = "Sembra che tutto qui sia stato colpito dall'esplosione, e non c'è modo di accenderla."
  },
  AvgDialog_35534_Content_20 = {
    Text = "Incontri Caecus vicino all'uscita: la sua figura esile proietta un'ombra eccezionalmente grande sul terreno. Diversi Navigatori si ergono alle sue spalle, intensificando la tensione e il pericolo nell'aria gelida."
  },
  AvgDialog_35534_Content_21 = {Text = "Caecus..."},
  AvgDialog_35534_Content_22 = {
    Text = "Non guardarmi così..."
  },
  AvgDialog_35534_Content_23 = {
    Text = "Gli occhi di Caecus tremolano, le sue labbra fremono come se volesse dire qualcosa, ma alla fine distoglie il capo, sfuggendo al vostro sguardo indagatore, il tuo e quello di Ramona."
  },
  AvgDialog_35534_Content_24 = {
    Text = "Avevi pianificato tutto fin dall'inizio? Progettando con cura ogni passo per condurci in una trappola./nTutto quello che ci hai raccontato era solo una copertura?"
  },
  AvgDialog_35534_Content_25 = {Text = "Io..."},
  AvgDialog_35534_Content_26 = {
    Text = "Non hai vissuto ciò che ho passato io, quindi non puoi comprendere cosa significhi il potere dei Navigatori..."
  },
  AvgDialog_35534_Content_27 = {
    Text = "Non capireste, e <Yellow:non dovreste essere qui>... Fossi in voi, tenterei ogni mezzo possibile per <Yellow:fuggire da Lady Miryam>."
  },
  AvgDialog_35534_Content_28 = {
    Text = "Il tono, l'intonazione e persino la grammatica di Caecus diventano strani, non più simili al leoniano standard."
  },
  AvgDialog_35534_Content_29 = {
    Text = "Se qualcuno ti sta costringendo a fare qualcosa contro la tua volontà..."
  },
  AvgDialog_35534_Content_3 = {
    Text = "Tu e Ramona vi scambiate informazioni a bassa voce per non farvi scoprire."
  },
  AvgDialog_35534_Content_30 = {
    Text = "No! Fermati!"
  },
  AvgDialog_35534_Content_31 = {
    Text = "Caecus grida all'improvviso, il volto che muta rapidamente. Una paura soffocante emana dalle profondità dei suoi occhi."
  },
  AvgDialog_35534_Content_32 = {
    Text = "Con gesti rigidi porta la mano al collo, rivelando un anello scuro identico al marchio che avevi visto su Golia in precedenza."
  },
  AvgDialog_35534_Content_33 = {
    Text = "L'antica Punizione di Lemuria si stringe lentamente, rendendo il suo respiro affannoso e faticoso."
  },
  AvgDialog_35534_Content_34 = {
    Text = "Sebbene i Risvegliati non necessitino di ossigeno per respirare, il dolore lancinante gli contorce il volto in un'indicibile Espressione di agonia."
  },
  AvgDialog_35534_Content_35 = {
    Text = "Mi dispiace..."
  },
  AvgDialog_35534_Content_36 = {
    Text = "Perdonami... Io... non ho altra Scelta che..."
  },
  AvgDialog_35534_Content_4 = {
    Text = "Tutte le decine di caldaie nella sala macchine si sono spente. Tu e Ramona siete costretti a controllarle una per una."
  },
  AvgDialog_35534_Content_5 = {
    Text = "Tocchi una caldaia fredda dopo l'altra. I Navigatori tutt'intorno amplificano il tuo terrore all'estremo."
  },
  AvgDialog_35534_Content_6 = {
    Text = "È come se il cuore ti martellasse sotto il cranio, lasciandoti udire null'altro che il suo battito ritmico."
  },
  AvgDialog_35534_Content_7 = {
    Text = "Poi, l'intenso battito cardiaco si arresta all'improvviso."
  },
  AvgDialog_35534_Content_8 = {
    Text = "Ramona, l'ho trovato!"
  },
  AvgDialog_35534_Content_9 = {
    Text = "La parete esterna della caldaia appena spenta è ancora rovente, e sottili volute di vapore si alzano dai tuoi guanti quando la toccano.\n\nMa non hai tempo di preoccupartene. Con entusiasmo, chiami il tuo compagno a bassa voce."
  },
  AvgDialog_35535_Content_1 = {
    Text = "Caecus crolla pesantemente in ginocchio, la sua arma diventa una stampella che sorregge il corpo sconfitto. Con le ultime forze, stringe l'asta della lancia come se si aggrappasse all'ultimo raggio di luce."
  },
  AvgDialog_35535_Content_2 = {
    Text = "Caecus, tu..."
  },
  AvgDialog_35535_Content_3 = {
    Text = "Respira pesantemente, apparentemente mormorando qualche parola./nPer capire il suo discorso farfugliato, devi accovacciarti davanti a lui."
  },
  AvgDialog_35535_Content_4 = {
    Text = "Vai... <Big:CORSA!>"
  },
  AvgDialog_35535_Content_5 = {
    Text = "Caecus ti spinge all'improvviso, perde l'Equilibrio e cade pesantemente sul suolo freddo e duro."
  },
  AvgDialog_35535_Content_6 = {
    Text = "L'istante successivo, un familiare scalpitio di Passi si avvicina a te attraverso la Folla di Navigatori."
  },
  AvgDialog_35535_Content_7 = {
    Text = "Caecus, non avresti dovuto deludermi."
  },
  AvgDialog_35536_Content_1 = {
    Text = "Fuoco Cattura-Falene"
  },
  AvgDialog_35536_Content_10 = {
    Text = "Il suono del vento... Ricordo che un'ampia apertura era stata squarciata nella sala macchine."
  },
  AvgDialog_35536_Content_11 = {
    Text = "La Sona-Nyl ha navigato verso nord, e la temperatura sulla superficie del mare è molto bassa. Senza nessuno che aggiunga carbone alla fornace, il fuoco potrebbe essere spento dal vento marino."
  },
  AvgDialog_35536_Content_12 = {Text = "Phew..."},
  AvgDialog_35536_Content_13 = {
    Text = "Che succede?"
  },
  AvgDialog_35536_Content_14 = {
    Text = "Niente. È solo che... mi sento un po' irreale."
  },
  AvgDialog_35536_Content_15 = {
    Text = [[
L'imboscata al porto, l'incontro con Murphy e il capitano, il confronto con Miryam, poi l'esplosione...

Siamo partiti da scuola poco prima di cena, eppure sembra che siamo in mare da due mesi.]]
  },
  AvgDialog_35536_Content_16 = {
    Text = "Che notte movimentata. Se la professoressa Doll lo sapesse, loderebbe con freddo distacco la mia rara diligenza."
  },
  AvgDialog_35536_Content_17 = {
    Text = "\"Ben fatto, Custode. L'esperienza di stanotte sarà un punto saliente di rilievo nel tuo rapporto finale.\""
  },
  AvgDialog_35536_Content_18 = {
    Text = "Rispondi a Ramona con un tono volutamente disinvolto. Lei emette qualche suono nasale indistinto, sforzandosi con tutte le sue forze di non scoppiare a ridere."
  },
  AvgDialog_35536_Content_19 = {
    Text = "Non andrai a riferire tutto a Doll, vero?"
  },
  AvgDialog_35536_Content_2 = {
    Text = [[
Tempo all'Allineamento:

<Red:20 minuti>]]
  },
  AvgDialog_35536_Content_20 = {
    Text = "L'avrei fatto quando l'ho contattata prima, se avessi voluto."
  },
  AvgDialog_35536_Content_21 = {
    Text = "\"Oh, professoressa Doll! %player% si è {Male=messo,Female=messa} altruisticamente in pericolo, riportando gravi ferite e perdendo i sensi!\""
  },
  AvgDialog_35536_Content_22 = {
    Text = "Shh! Per favore, non—"
  },
  AvgDialog_35536_Content_23 = {
    Text = "Ma... Aspetta, le hai già parlato? Il comunicatore funziona adesso?"
  },
  AvgDialog_35536_Content_24 = {
    Text = "Sì. Quando il Dominio era ancora intatto, il segnale era inizialmente interrotto. Poi, dopo che il potere di Celeste ha cominciato a indebolirsi, le comunicazioni erano ancora ostacolate a causa della distanza."
  },
  AvgDialog_35536_Content_25 = {
    Text = "Ramona fruga in tasca e tira fuori un comunicatore rotto. Il pannello con inciso l'emblema dell'Università di Mythag viene rimosso, rivelando ingranaggi interni bruciati."
  },
  AvgDialog_35536_Content_26 = {
    Text = "Ho provato a regolare la frequenza di base del comunicatore per contattare la scuola. Anche se breve, è bastato per spiegare la situazione con chiarezza."
  },
  AvgDialog_35536_Content_27 = {
    Text = "Doll e la sua squadra si occuperanno di preparare l'intervento di Separazione del \"Sacro Infante\", e William è già arrivato al porto per aiutarci non appena attraccheremo."
  },
  AvgDialog_35536_Content_28 = {
    Text = "Ma durante questo tempo in mare... dovremo contare solo su noi stessi."
  },
  AvgDialog_35536_Content_29 = {
    Text = "Dobbiamo proteggere Murphy, tenere a bada Golia e aiutare il Capitano Elton a navigare fino a terra... Per fortuna Tulu ci sta aiutando, e anche Caecus sembra disposto a darci una mano..."
  },
  AvgDialog_35536_Content_3 = {
    Text = [[
Tu e Ramona tornate all'esterno della sala macchine.

La crescita della D-iperplasia sta peggiorando, diffondendosi visibilmente lungo il percorso.]]
  },
  AvgDialog_35536_Content_30 = {
    Text = "Altrimenti, solo noi due... probabilmente non saremmo arrivati fin qui."
  },
  AvgDialog_35536_Content_31 = {
    Text = "Dobbiamo impedire la nascita del \"Feto Divino\"."
  },
  AvgDialog_35536_Content_32 = {
    Text = "Se il rito proseguirà indisturbato, chi può sapere quale mostro si schiuderà dal corpo di Murphy."
  },
  AvgDialog_35536_Content_33 = {
    Text = "Esatto... Per Murphy e per il mondo intero, la nascita del \"Sacro Infante\" non porterà altro che disastro."
  },
  AvgDialog_35536_Content_34 = {
    Text = "Inoltre, è divenuta il nucleo di un Cataclisma. Non possiamo permetterci di Ignorare la cosa."
  },
  AvgDialog_35536_Content_35 = {
    Text = "È qualcosa che solo noi possiamo compiere."
  },
  AvgDialog_35536_Content_36 = {Text = "..."},
  AvgDialog_35536_Content_37 = {
    Text = "È corretto... Questo è qualcosa che solo noi possiamo compiere."
  },
  AvgDialog_35536_Content_38 = {
    Text = "Su col morale. C'è ancora molto da fare."
  },
  AvgDialog_35536_Content_4 = {
    Text = "Ramona accosta l'orecchio alla porta e resta in ascolto per un istante. Dopo aver confermato che all'interno non si sente alcun rumore, ti fa un cenno col capo."
  },
  AvgDialog_35536_Content_5 = {Text = "Crack—"},
  AvgDialog_35536_Content_6 = {
    Text = "La porta che un tempo permetteva a te e a Murphy di andare e venire liberamente è ora incastrata nel telaio a causa del corallo in rapida crescita. Per quanto tu e Ramona vi sforziate, non si muove di un millimetro."
  },
  AvgDialog_35536_Content_7 = {
    Text = "C'è un'altra porta per la sala macchine. Facciamo il giro."
  },
  AvgDialog_35536_Content_8 = {
    Text = "A parte il vento, non ho sentito nulla poco fa, ma è meglio non correre rischi."
  },
  AvgDialog_35536_Content_9 = {Text = "Bene."},
  AvgDialog_35537_Content_1 = {
    Text = "La\"Gloria\"di Lemuria"
  },
  AvgDialog_35537_Content_10 = {
    Text = "Gli aiutanti umani della Madre Divina non meritano menzione; la vera minaccia è..."
  },
  AvgDialog_35537_Content_11 = {
    Text = "<Yellow:\"Nostro Signore\"> è sulla punta della sua lingua, ma Caecus inspira profondamente e lo ricaccia giù."
  },
  AvgDialog_35537_Content_12 = {
    Text = "...La vera minaccia è quel dio contraffatto che Mythag ha evocato... È lui il vero nemico di noi Navigatori."
  },
  AvgDialog_35537_Content_13 = {
    Text = "Niente male. Sembra che quelle ridicole formalità non possano più vincolarti."
  },
  AvgDialog_35537_Content_14 = {
    Text = "Quando tutto questo sarà finito, mi collegherò personalmente con te e ti renderò il mio Risvegliatore."
  },
  AvgDialog_35537_Content_15 = {
    Text = [[
Ti manca un ultimo passo per raggiungere la vetta.

Non deludermi, ragazzo.]]
  },
  AvgDialog_35537_Content_16 = {
    Text = "S-Sì, signore. È un onore..."
  },
  AvgDialog_35537_Content_17 = {
    Text = "Abbassa obbedientemente la testa mentre Golia imperversa nella sala macchine, ormai indistinguibile da un cumulo di rovine."
  },
  AvgDialog_35537_Content_18 = {
    Text = "La lama gigantesca si trascina sulle cicatrici desolate, fendendo la cenere e la polvere dopo l'esplosione come un fiume appena scavato."
  },
  AvgDialog_35537_Content_19 = {
    Text = "Non avevi detto che c'era una situazione particolare nella sala macchine che solo io potevo risolvere?"
  },
  AvgDialog_35537_Content_2 = {
    Text = "Tsk, che sfortuna."
  },
  AvgDialog_35537_Content_20 = {
    Text = "S-sì... l'ho sentito, sentito... attraverso il legame..."
  },
  AvgDialog_35537_Content_21 = {
    Text = "Lady Miryam... Sì, ho percepito Lady Miryam."
  },
  AvgDialog_35537_Content_22 = {Text = "Ah—!"},
  AvgDialog_35537_Content_23 = {
    Text = "Il gigante sferra un calcio violento al retro del suo ginocchio, e il dolore della dislocazione ossea costringe Caecus a crollare in ginocchio tra le macerie."
  },
  AvgDialog_35537_Content_24 = {
    Text = "Caecus è pessimo nel mentire e inciampa sulle proprie parole. Le sue maldestre bugie non riescono a convincere nemmeno lui stesso, figurarsi Golia."
  },
  AvgDialog_35537_Content_25 = {
    Text = "Dimenticati di quella pazza! Non l'hai ancora capito? Non le importa nulla di voi uomini-pesce!"
  },
  AvgDialog_35537_Content_26 = {
    Text = "Lei desidera soltanto quel dio — la spregevole divinità che abbandonò lei e i Lemuriani in tempi preistorici, svanendo senza lasciare traccia!"
  },
  AvgDialog_35537_Content_27 = {
    Text = "<Italic:Io... Sto per morire...>"
  },
  AvgDialog_35537_Content_28 = {
    Text = "Golia afferra i capelli di Caecus e li strattona verso l'alto, costringendolo ad alzare lo sguardo e incontrare il suo. Il sudore freddo gli cola negli occhi, bruciando le sue fragili membrane mucose."
  },
  AvgDialog_35537_Content_29 = {
    Text = "<Italic:Morirò... Morirò per aver tradito Lord Golia...>"
  },
  AvgDialog_35537_Content_3 = {
    Text = "Dopo aver ignorato i Suoi sudditi per migliaia di anni, ora quel nano vuole seminare il caos."
  },
  AvgDialog_35537_Content_30 = {
    Text = "L'istante successivo, Caecus viene sbattuto a terra da Golia, come un albero maestro spezzato."
  },
  AvgDialog_35537_Content_31 = {
    Text = "Sparite, andate a radunare quegli stolti erranti."
  },
  AvgDialog_35537_Content_32 = {
    Text = "Caecus fugge dalla sala macchine.\nDopo che Caecus è ormai fuori vista da tempo, Golia monta la sua arma accanto alla fornace in fiamme."
  },
  AvgDialog_35537_Content_33 = {
    Text = "...Phew, come ci si aspetta dal \"Re Divino\"."
  },
  AvgDialog_35537_Content_34 = {
    Text = "Un semplice colpo di Tentacolo lascia una ferita spalancata nella parte bassa della schiena del gigante. Sangue di un colore innaturale trasuda silenziosamente, infiltrandosi nelle crepe della sua pelle scura."
  },
  AvgDialog_35537_Content_35 = {
    Text = "Non ti trattieni davvero... Heh."
  },
  AvgDialog_35537_Content_36 = {
    Text = "Non importa... Con il Feto Divino come mia marionetta, quegli stolti rimasti a Elworth si inginocchieranno davanti a me come loro re."
  },
  AvgDialog_35537_Content_37 = {
    Text = "Un'opportunità irripetibile. Nessuno potrà portarmela via."
  },
  AvgDialog_35537_Content_38 = {
    Text = "Golia recupera la sua arma dal fuoco e preme senza esitazione l'enorme lama contro la ferita."
  },
  AvgDialog_35537_Content_39 = {
    Text = "Sotto il calore intenso, i muscoli si atrofizzano rapidamente, accompagnati dall'odore di metallo bruciato. Dalla ferita non trasuda più il fluido nero-bluastro."
  },
  AvgDialog_35537_Content_4 = {
    Text = "Il giovane Navigatore segue il gigante da vicino, passo dopo passo, in silenzio."
  },
  AvgDialog_35537_Content_40 = {
    Text = "Lord Golia, la maggior parte dei Navigatori sulla nave è qui."
  },
  AvgDialog_35537_Content_41 = {
    Text = "Dopo essersi assentato per un po', Caecus ritorna visibilmente stanco, ma a Golia non importa."
  },
  AvgDialog_35537_Content_42 = {
    Text = "Sono rimasti solo questi?"
  },
  AvgDialog_35537_Content_43 = {
    Text = "Sì... e a causa della Propagazione della <Yellow:Dissoluzione>, molti non sono più in grado di combattere."
  },
  AvgDialog_35537_Content_44 = {Text = "Basta."},
  AvgDialog_35537_Content_45 = {
    Text = "Gurg... Lord Golia..."
  },
  AvgDialog_35537_Content_46 = {
    Text = "Somma Sacerdotessa... Gurrr... ritorno... @2..."
  },
  AvgDialog_35537_Content_47 = {
    Text = "Le parole che scivolano dalle bocche dei Navigatori fanno aggrottare la fronte a Golia. Sono irriconoscibili, incomprensibili, il loro significato lo respinge — respinge coloro nelle cui vene non scorre sangue divino."
  },
  AvgDialog_35537_Content_48 = {
    Text = "Basta...\n\nApri gli occhi e guarda la realtà!"
  },
  AvgDialog_35537_Content_49 = {
    Text = "La Somma Sacerdotessa è morta, ma la Madre Divina vive ancora!\n\nAbbiamo ancora una possibilità di continuare il rituale. Recuperate la Madre Divina! Fate nascere il Feto Divino!"
  },
  AvgDialog_35537_Content_5 = {
    Text = "Ragazzo, tu che ne pensi?"
  },
  AvgDialog_35537_Content_50 = {
    Text = "Questa grande lama non mancherà la sua missione... Diverrò la spada più affilata del nuovo dio!"
  },
  AvgDialog_35537_Content_51 = {
    Text = "Gur... Gurg... @2 Ritorno..."
  },
  AvgDialog_35537_Content_52 = {
    Text = "Farà ritorno... Farà ritorno!"
  },
  AvgDialog_35537_Content_54 = {
    Text = "Le preghiere sconnesse finiscono per fondersi in un flusso simile a un canto, irritando profondamente Golia."
  },
  AvgDialog_35537_Content_55 = {
    Text = "Nelle ferventi Preghiere dei Navigatori, flussi di energia amorfa si insinuano attraverso la breccia nello scafo, avvolgendosi attorno a Golia."
  },
  AvgDialog_35537_Content_56 = {
    Text = "Il dolore familiare e la stretta alla gola costringono Golia ad afferrarsi il collo; le vene pulsano alle tempie e i suoi occhi si spalancano, iniettati di sangue."
  },
  AvgDialog_35537_Content_57 = {
    Text = "Le Catene che lo vincolano da quando si è legato all'\"Apostolo del Mare\"... Catene dalle quali credeva di essersi liberato dopo quell'esplosione..."
  },
  AvgDialog_35537_Content_58 = {
    Text = "Lo puniscono ancora una volta per la sua blasfemia contro \"Dio.\""
  },
  AvgDialog_35537_Content_6 = {Text = "Io... Io?"},
  AvgDialog_35537_Content_60 = {
    Text = "Prima che il gigante possa reagire, la nebbia si è condensata in una melma densa e tangibile, trasformandosi in un Pugnale alieno premuto contro la ferita sul suo collo."
  },
  AvgDialog_35537_Content_61 = {
    Text = "Filistea..."
  },
  AvgDialog_35537_Content_62 = {Text = "Tu..."},
  AvgDialog_35537_Content_63 = {
    Text = "\"Filistea.\" C'è solo una persona che ora conosce Golia con quel nome."
  },
  AvgDialog_35537_Content_64 = {
    Text = "Lady Miryam?!"
  },
  AvgDialog_35537_Content_65 = {Text = "Miryam..."},
  AvgDialog_35537_Content_66 = {
    Text = "Dopo un breve istante di contemplazione e silenzio, i Navigatori esplodono in applausi gioiosi."
  },
  AvgDialog_35537_Content_67 = {
    Text = "Somma Sacerdotessa! <Big:Somma Sacerdotessa!> <BigShake:Sua Santità è tornata!>"
  },
  AvgDialog_35537_Content_68 = {
    Text = "Haha... Sono così felice che tu stia bene."
  },
  AvgDialog_35537_Content_69 = {
    Text = "Golia cerca di allontanare il pugnale ma finisce per tagliarsi il dito sulla punta improvvisamente affilata."
  },
  AvgDialog_35537_Content_7 = {
    Text = "Spaventato, Caecus spalanca gli occhi. È del tutto impreparato alla domanda."
  },
  AvgDialog_35537_Content_70 = {
    Text = "So cosa stai pensando, Filistea."
  },
  AvgDialog_35537_Content_71 = {Text = "..."},
  AvgDialog_35537_Content_72 = {
    Text = "Eliminate i traditori, sgombrate gli ostacoli per la discesa del nostro Signore... Rimuovete l'impostore e reclamate la Madre Divina."
  },
  AvgDialog_35537_Content_73 = {
    Text = "Allora, posso ancora concederti una morte dignitosa."
  },
  AvgDialog_35537_Content_74 = {
    Text = [[
Tempo all'Allineamento:

<Red:30 minuti>]]
  },
  AvgDialog_35537_Content_8 = {
    Text = "C'è qualche barriera comunicativa tra noi? O c'è una terza persona dotata di cervello qui presente?"
  },
  AvgDialog_35537_Content_9 = {
    Text = "S-Sì... Mi perdoni, Lord Golia."
  },
  AvgDialog_35538_Content_1 = {
    Text = "Il nostro Comunicatore è costoso?"
  },
  AvgDialog_35538_Content_2 = {
    Text = "L'Argento che contiene potrebbe essere scambiato al mercato nero per una proprietà nel centro di Londinium."
  },
  AvgDialog_35538_Content_3 = {
    Text = "Ma perché lo chiedi all'improvviso?"
  },
  AvgDialog_35538_Content_4 = {
    Text = "N-Niente..."
  },
  AvgDialog_35820_Content_1 = {
    Text = "Come sta Caecus?"
  },
  AvgDialog_35820_Content_2 = {
    Text = "Nessuna reazione, e non sembra intenzionato ad attaccarci."
  },
  AvgDialog_35820_Content_3 = {
    Text = "Concentriamoci prima sui Navigatori. Teniamo d'occhio Caecus."
  },
  AvgDialog_35821_Content_1 = {
    Text = "Il falso dio crolla e si disgrega tra le grida, polvere grigio-azzurra riempie il cielo e ricade lentamente."
  },
  AvgDialog_35821_Content_10 = {
    Text = "A Bridgeport, dove il Custode e io siamo saliti a bordo della nave. Siamo... tornati?"
  },
  AvgDialog_35821_Content_11 = {
    Text = "Siamo tornati."
  },
  AvgDialog_35821_Content_12 = {
    Text = "Il Custode, Tulu, il Capitano Elton, Celeste, Caecus... e Murphy."
  },
  AvgDialog_35821_Content_13 = {
    Text = "E c'è William Delapore."
  },
  AvgDialog_35821_Content_14 = {
    Text = "S-Senior William..."
  },
  AvgDialog_35821_Content_15 = {
    Text = "Quando avete lasciato la scuola, eravate solo in due. Ora, a quanto pare, l'auto che ho preparato non riesce a contenere tutti."
  },
  AvgDialog_35821_Content_16 = {
    Text = "Lo sguardo affilato di William scruta l'intero porto. Infine, lascia sfuggire un profondo sospiro e sorride."
  },
  AvgDialog_35821_Content_17 = {
    Text = "Bentornato, Custode."
  },
  AvgDialog_35821_Content_18 = {
    Text = "William si avvicina. Cerchi di dire qualcosa, ma il tuo sguardo si annebbia per un istante, senza che tu possa controllarlo."
  },
  AvgDialog_35821_Content_19 = {
    Text = "Ogni fatica, confusione e dolore svaniscono nel nulla. L'immagine del tuo compagno che corre ansiosamente verso di te diventa l'ultimo fotogramma nella tua memoria, seguito da un'ondata di oscura quiete..."
  },
  AvgDialog_35821_Content_2 = {
    Text = "Attento, non inalare questa polvere."
  },
  AvgDialog_35821_Content_3 = {
    Text = "Prima che le parole siano terminate, il ponte sotto i loro piedi inizia a tremare violentemente. La nave emette uno scricchiolio acuto, come l'ultimo grido d'aiuto di qualcuno che sta annegando."
  },
  AvgDialog_35821_Content_4 = {
    Text = "Oh no?! La nave... sta affondando?!"
  },
  AvgDialog_35821_Content_5 = {
    Text = "La nave oscilla caoticamente, e aggrapparsi alla ringhiera è inutile. Il mondo crolla intorno a te, e la polvere che cade oscura completamente la tua visuale."
  },
  AvgDialog_35821_Content_6 = {
    Text = "Non riesci più a vedere la luna, non riesci più a vedere il mare, e a malapena distingui i tuoi compagni."
  },
  AvgDialog_35821_Content_7 = {
    Text = "Un istante prima che la polvere contraffatta inghiotta ogni cosa, il mondo diventa straordinariamente nitido."
  },
  AvgDialog_35821_Content_8 = {
    Text = "L'incessante fragore delle onde si è placato, e sotto il cielo notturno limpido, la luce lunare appare particolarmente dolce e serena."
  },
  AvgDialog_35821_Content_9 = {
    Text = "Questo è... il porto?"
  },
  AvgDialog_35822_Content_1 = {
    Text = "Stelle distorte"
  },
  AvgDialog_35822_Content_10 = {
    Text = "Il serpente fantasma alza improvvisamente la testa, sollevando Murphy nella luce lunare."
  },
  AvgDialog_35822_Content_11 = {
    Text = "Coppie di piccole, delicate mani nere emergono dal petto della ragazza, contorcendosi e intrecciandosi tra loro, strato dopo strato, avvolgendo il suo corpo in un enorme bozzolo nero."
  },
  AvgDialog_35822_Content_12 = {
    Text = "Con un ringhio soffocato, mani e fili neri usano il serpente gigante come telaio, avvolgendo il bozzolo strettamente attorno al suo corpo massiccio."
  },
  AvgDialog_35822_Content_13 = {
    Text = "Il guscio del bozzolo diventa trasparente per il rigonfiamento. Innumerevoli mani si intrecciano a formare un trono, sollevando un cuore pallido."
  },
  AvgDialog_35822_Content_14 = {
    Text = "Ph@1...@1nafh @3..."
  },
  AvgDialog_35822_Content_15 = {
    Text = "Miryam si inginocchia a prua, inchinandosi davanti all'entità orribilmente contorta."
  },
  AvgDialog_35822_Content_16 = {
    Text = "Il vento porta sussurri lontani e sconosciuti, come il sibilo di un serpente nelle ombre, facendoti rizzare i capelli."
  },
  AvgDialog_35822_Content_17 = {
    Text = "Come... Come ha fatto Murphy a cadere sotto il controllo di Miryam?"
  },
  AvgDialog_35822_Content_18 = {
    Text = "Ramona e Caecus ti sostengono da entrambi i lati. Voi tre vi disponete in fila, alzando lo sguardo verso il gigantesco mostro che oscura la luce della luna."
  },
  AvgDialog_35822_Content_19 = {
    Text = "È troppo tardi... Ormai oltre ogni Redenzione."
  },
  AvgDialog_35822_Content_2 = {
    Text = "Segui la direzione in cui nuota Miryam e ti affretti verso il ponte principale."
  },
  AvgDialog_35822_Content_20 = {
    Text = "È di questo che volevo avvertirti... Lady Miryam mi ha ordinato di spegnere l'ultima caldaia di potere, con l'intenzione di attirarvi nella trappola che avevamo preparato e catturarvi tutti."
  },
  AvgDialog_35822_Content_21 = {
    Text = "Sebbene la Madre Divina... sebbene Lady Murphy non sia andata con voi, questo ha dato a Lord Golia l'opportunità di catturarla."
  },
  AvgDialog_35822_Content_22 = {
    Text = "Il collegamento con Caecus è come un'iniezione di adrenalina allo spirito, che ricompone gradualmente la sanità mentale attraverso il dolore."
  },
  AvgDialog_35822_Content_23 = {
    Text = "Lo stridulo suono di flauto e i sussurri nella tua mente cessano. Sbatti le palpebre, avvertendo chiarezza nel Reame dello Spirito per la prima volta dall'esplosione—"
  },
  AvgDialog_35822_Content_24 = {
    Text = "La formazione del bozzolo gigante porta un pesante inquinamento al Dominio circostante, rendendo difficile localizzare Murphy nel liquido torbido al suo interno. Ma senza dubbio, scorgi una scintilla di vita."
  },
  AvgDialog_35822_Content_25 = {
    Text = "No, c'è ancora tempo."
  },
  AvgDialog_35822_Content_26 = {
    Text = "È ancora viva. Abbiamo ancora una possibilità. A qualunque costo... Proviamo prima ad avvicinarci a loro."
  },
  AvgDialog_35822_Content_27 = {
    Text = "Ma sei ferito... No, andrò da solo.\n\nCaecus, potresti tenere d'occhio %player% per un po'?"
  },
  AvgDialog_35822_Content_28 = {
    Text = "Ramona raramente ti rifiuta con tanta fermezza. Rimuove la tua mano dal suo braccio e ti affida solennemente a Caecus."
  },
  AvgDialog_35822_Content_29 = {
    Text = "Sì... Farò del mio meglio."
  },
  AvgDialog_35822_Content_3 = {
    Text = "Nell'istante in cui l'ultimo passo è compiuto, un colosso sconosciuto si schianta contro il mercantile, facendolo inclinare e deviare dalla rotta."
  },
  AvgDialog_35822_Content_30 = {
    Text = "Aspetta, non ho mai detto che puoi andare da solo!"
  },
  AvgDialog_35822_Content_31 = {
    Text = "Caecus ti blocca a terra con una mano, fermando la tua resistenza senza alcuno sforzo."
  },
  AvgDialog_35822_Content_32 = {
    Text = "Ma Ramona ha fatto solo pochi passi quando la pinna auricolare di Caecus freme con sensibilità."
  },
  AvgDialog_35822_Content_33 = {
    Text = "L'istante dopo, lascia cadere la sua arma, ti afferra e rotola via dal punto in cui vi trovavate. Una lama gigante arriva da lontano, frantumando il ponte e facendo volare schegge ovunque."
  },
  AvgDialog_35822_Content_34 = {
    Text = "%player%! Caecus!"
  },
  AvgDialog_35822_Content_35 = {
    Text = "Caecus scuote la testa, indicando che sta bene. Dopo aver verificato che non hai riportato nuove ferite, raccoglie la sua arma e monta la guardia davanti a te."
  },
  AvgDialog_35822_Content_36 = {
    Text = "È allora che noti che la sua pinna dorsale è stata sfiorata dalla lama. Il tessuto, un tempo resistente quanto la pinna di un pesce spada, è ora lacerato senza pietà e pende storto sulla sua schiena."
  },
  AvgDialog_35822_Content_37 = {
    Text = "Con il volto contratto dal dolore, Caecus raddrizza comunque la schiena orgogliosa, fronteggiando il gigante beffardo in lontananza."
  },
  AvgDialog_35822_Content_38 = {
    Text = "Lord Golia, vi prego, non avvicinatevi oltre."
  },
  AvgDialog_35822_Content_39 = {
    Text = [[
Usa tutte le sue forze per spingerti verso Ramona.

Con il suo corpo esile, si frappone tra te e Golia.]]
  },
  AvgDialog_35822_Content_4 = {Text = "Attento!"},
  AvgDialog_35822_Content_40 = {
    Text = "Fidati di Caecus! Lascia che trattenga Golia mentre noi ci intrufiliamo attraverso la stiva per avvicinarci a quella cosa!"
  },
  AvgDialog_35822_Content_5 = {
    Text = "Caecus e Ramona ti sostengono da entrambi i lati, riuscendo finalmente a fermarsi insieme a te."
  },
  AvgDialog_35822_Content_6 = {
    Text = "L'istante successivo, accompagnata dal fragore delle onde, un'ombra immensa incombe su di voi."
  },
  AvgDialog_35822_Content_7 = {
    Text = "Guarda! Eccolo!"
  },
  AvgDialog_35822_Content_9 = {
    Text = "Quello è... Quello è Murphy!"
  },
  AvgDialog_35823_Content_1 = {
    Text = "Hai appena usato il Tracciamento Spirituale? Ma il tuo Corpo..."
  },
  AvgDialog_35823_Content_2 = {
    Text = "Sto bene... Ugh!"
  },
  AvgDialog_35823_Content_3 = {
    Text = "Quando l'effetto analgesico della scarica di adrenalina svanisce all'improvviso, le tue gambe cedono. Se Ramona non ti avesse sostenuta, probabilmente saresti distesa a terra in questo momento."
  },
  AvgDialog_35823_Content_4 = {
    Text = "Non provare a usare di nuovo il potere spirituale. Non finché non ti sarai sottoposto/a a un controllo approfondito."
  },
  AvgDialog_35824_Content_1 = {
    Text = "Sentiero Smarrito"
  },
  AvgDialog_35824_Content_10 = {
    Text = "Lady Miryam... Io... Io non ho..."
  },
  AvgDialog_35824_Content_11 = {
    Text = "Tenta la Fuga da questo tormento, ma più si dibatte, più il Potere antico si rafforza, beffandosi della sua impotenza e fragilità."
  },
  AvgDialog_35824_Content_12 = {
    Text = "Il suo sguardo periferico cade infine su di te e Ramona, un fugace lampo di disperazione che gli attraversa gli occhi."
  },
  AvgDialog_35824_Content_13 = {
    Text = "Basta! Miryam!"
  },
  AvgDialog_35824_Content_14 = {
    Text = "Ramona comprende e sfodera la spada per bloccare Miryam. La lama punta al collo esile della donna, mentre sangue scuro scorre lungo la superficie del metallo."
  },
  AvgDialog_35824_Content_15 = {
    Text = "Ma il dolore sul volto di Caecus non si attenua minimamente. Giace in ginocchio a terra in uno stato pietoso, incapace di sollevare il capo."
  },
  AvgDialog_35824_Content_16 = {
    Text = "Proteggeremo Murphy e fermeremo il rito. Finché saremo qui, il vostro grande piano è destinato a fallire."
  },
  AvgDialog_35824_Content_17 = {
    Text = "Puoi tormentare quanto vuoi questo Risvegliato legato al tuo spirito... Noi non ci arrenderemo."
  },
  AvgDialog_35824_Content_18 = {
    Text = "...Davvero?"
  },
  AvgDialog_35824_Content_19 = {
    Text = "Miryam alza lo sguardo, rivelando un sorriso enigmatico. I suoi occhi sono contaminati dalla follia, colmi di una minaccia indescrivibile."
  },
  AvgDialog_35824_Content_2 = {
    Text = "Miryam si erge in cima alle rovine, schegge di metallo frastagliate le feriscono i piedi, sangue scuro che cola."
  },
  AvgDialog_35824_Content_20 = {
    Text = "Voi che camminate con il falso re, voi che profanate il potere del mio Signore... I vostri sentimenti non sono mai stati una preoccupazione per questa misera esistenza."
  },
  AvgDialog_35824_Content_21 = {
    Text = "Il suo tono si alza, emanando una follia agghiacciante che sembra pronta a divorare ogni cosa."
  },
  AvgDialog_35824_Content_22 = {
    Text = "Miryam ritrae bruscamente la mano, e Caecus crolla come una marionetta gettata via."
  },
  AvgDialog_35824_Content_23 = {
    Text = "Si accascia in ginocchio, disteso a terra, i muscoli della gola che fremono, celebrando la sopravvivenza del proprio corpo con violenti colpi di tosse."
  },
  AvgDialog_35824_Content_24 = {
    Text = "Alzati e continua a combattere, Caecus."
  },
  AvgDialog_35824_Content_25 = {
    Text = "Attorno a lei, i Navigatori bramosi avanzano in un'ondata e vi circondano."
  },
  AvgDialog_35824_Content_26 = {
    Text = "Questa è la tua ultima occasione. Alzati e fai piazza pulita di questa gente... elimina i nemici del Reame Divino!"
  },
  AvgDialog_35824_Content_3 = {
    Text = "Ovunque posi i piedi, una raggelante scia di sangue la segue, emanando un terrore glaciale."
  },
  AvgDialog_35824_Content_4 = {Text = "Miryam..."},
  AvgDialog_35824_Content_5 = {
    Text = "Miryam ti rivolge un'occhiata, il suo contegno altero, senza mostrare alcun segno di sconfitta."
  },
  AvgDialog_35824_Content_6 = {
    Text = "Se non fosse per il dolore costante che il suo corpo le segnala, la scena in cui ha perso la sanità mentale trasformandosi nella Follia sembrerebbe frutto della tua immaginazione."
  },
  AvgDialog_35824_Content_7 = {
    Text = "Caecus, non avresti dovuto deludermi."
  },
  AvgDialog_35824_Content_8 = {
    Text = [[
Ignora completamente te e Ramona, avanzando passo dopo passo verso Caecus.

Man mano che si avvicina, l'anello nero attorno al collo di Caecus ricomincia a tremolare.]]
  },
  AvgDialog_35824_Content_9 = {
    Text = "L'anello nero, come un viticcio oscuro, stringe la sua presa Minacciosa a ogni battito del cuore di Caecus, consumando la sua forza vitale come ombre Al Crepuscolo che strisciano sulle strade."
  },
  AvgDialog_35825_Content_1 = {
    Text = "Tsk. Spero di non essere stato così insopportabile quand'ero neonato."
  },
  AvgDialog_35825_Content_10 = {
    Text = "Una barriera rosa pallido si frantuma con uno schianto, accompagnata dal suono di passi leggeri che si avvicinano. Il suono trafigge i tuoi timpani ovattati con una chiarezza senza precedenti."
  },
  AvgDialog_35825_Content_11 = {
    Text = "Per punire il piagnucolone, come potremmo dimenticare la grande \"Madre\"?"
  },
  AvgDialog_35825_Content_12 = {
    Text = "Murphy! La tua <Yellow:Trasformazione da Risvegliatrice>... È riuscita!"
  },
  AvgDialog_35825_Content_13 = {
    Text = "Hmph... Con te farò i conti dopo. Ora è il momento di regolare le cose con questo mostro!"
  },
  AvgDialog_35825_Content_2 = {
    Text = "Riesci ad addormentarti ovunque. Devi essere stato un neonato eccezionalmente tranquillo."
  },
  AvgDialog_35825_Content_3 = {
    Text = "Ramona risponde scherzando. La mano che impugna la spada trema in modo incontrollabile, segno evidente che ha raggiunto il suo limite fisico."
  },
  AvgDialog_35825_Content_4 = {
    Text = "Ma quando il tentacolo del \"Sacro Infante\" cala nuovamente, Ramona si lancia in avanti con risolutezza, deviando il tentacolo in movimento."
  },
  AvgDialog_35825_Content_5 = {
    Text = "La forza immensa colpisce la sua mano destra, quasi strappandole l'arma dalla presa. Ma lei si limita a inspirare profondamente e stringe ancora una volta l'impugnatura dello stocco."
  },
  AvgDialog_35825_Content_6 = {
    Text = "Dobbiamo occuparci di quella Cosa prima di raggiungere la riva."
  },
  AvgDialog_35825_Content_7 = {
    Text = "Nell'angolo della tua visuale, un freddo insolito si sta propagando. Quando ti rendi conto che si tratta di un altro tentacolo, è già scivolato alle tue spalle—"
  },
  AvgDialog_35825_Content_9 = {
    Text = "Questa cosa mi ha tormentata così a lungo... Pensi forse di sbarazzartene da solo? Non lo permetterò mai!"
  },
  AvgDialog_35826_Content_1 = {
    Text = "Fiamma Interiorizzata"
  },
  AvgDialog_35826_Content_10 = {
    Text = "Murphy, come ti senti?"
  },
  AvgDialog_35826_Content_11 = {
    Text = "Murphy siede in un angolo della plancia. La punta della sua coda di cavallo le ricade distrattamente sulla spalla. Appare pallida e trasandata, ben lontana dalla sua un tempo arrogante e viziata persona."
  },
  AvgDialog_35826_Content_12 = {
    Text = "Murphy, Murphy?"
  },
  AvgDialog_35826_Content_13 = {
    Text = "I Suoi Occhi sono vuoti e confusi, lo sguardo rivolto verso il basso, al proprio petto."
  },
  AvgDialog_35826_Content_14 = {
    Text = "Accarezzandosi dolcemente il petto, le punte delle dita tracciano piccoli cerchi sul cuore. Sotto si cela il suo fragile cuore umano, una bomba a orologeria che le consuma la vita."
  },
  AvgDialog_35826_Content_15 = {
    Text = "Ogni battito è colmo di dolore, un tormento per il suo corpo. Ma ciò che è davvero terrificante è l'orrore e l'inquietudine che le rodono lo spirito."
  },
  AvgDialog_35826_Content_16 = {
    Text = "Si fa più attivo... È in costante movimento."
  },
  AvgDialog_35826_Content_17 = {
    Text = "I pensieri di Murphy sprofondano gradualmente nella nebbia del suo cuore. Chiude gli occhi, tentando una conversazione silenziosa con la Specie Parassita che la consuma."
  },
  AvgDialog_35826_Content_18 = {
    Text = "Ma prima che Murphy possa attendere una risposta dal Feto, la sua attenzione viene attratta dal suono di qualcosa di pesante che colpisce il pavimento fuori dalla porta della plancia."
  },
  AvgDialog_35826_Content_19 = {
    Text = "Dopo aver sollevato ancora una volta i tentacoli in alto, un dolore acuto perfora l'anima di Tulu. L'improvviso soffocamento frantuma la forza accumulata, e i tentacoli si abbattono sul ponte."
  },
  AvgDialog_35826_Content_2 = {
    Text = "Quei due Studenti sono via da così tanto tempo..."
  },
  AvgDialog_35826_Content_20 = {
    Text = "È la Punizione segreta di Lemuria..."
  },
  AvgDialog_35826_Content_21 = {
    Text = "Tulu? Cosa sta succedendo?"
  },
  AvgDialog_35826_Content_22 = {
    Text = "Non uscire!"
  },
  AvgDialog_35826_Content_23 = {
    Text = "Le sue viscere sembrano squarciate da quella forza. Tulu ansima pesantemente mentre abbatte un altro Navigatore, poi non riesce più a reggersi in piedi."
  },
  AvgDialog_35826_Content_24 = {
    Text = "È il dolore trasmesso attraverso il nostro legame... il Custode è in pericolo."
  },
  AvgDialog_35826_Content_25 = {
    Text = "Altri Navigatori si riversano in un'ondata sulla piattaforma del ponte fuori dalla cabina. L'odore di alghe e plancton in putrefazione avvolge istantaneamente tutti."
  },
  AvgDialog_35826_Content_26 = {Text = "Golia..."},
  AvgDialog_35826_Content_27 = {
    Text = "Oh... non saprei dire se quella donna comprende le persone fin troppo bene, o se tutti voi siete semplicemente troppo ingenui."
  },
  AvgDialog_35826_Content_28 = {
    Text = "Volevo solo fare un tentativo, ma non mi aspettavo che vi sareste davvero divisi come quella donna aveva pianificato — pur sapendo che i Navigatori vi stanno ancora dando la caccia."
  },
  AvgDialog_35826_Content_29 = {
    Text = "Quella donna... Possibile che Miryam sia davvero ancora viva?!"
  },
  AvgDialog_35826_Content_3 = {
    Text = "Elton gira il timone alcune volte invano; come previsto, non c'è alcuna risposta dai comandi."
  },
  AvgDialog_35826_Content_30 = {
    Text = "Golia sputa sangue, il tono sprezzante e beffardo — beffardo verso sé stesso."
  },
  AvgDialog_35826_Content_31 = {
    Text = "In quanto <Yellow:\"Golem\">, non moriamo così facilmente, ma..."
  },
  AvgDialog_35826_Content_32 = {
    Text = [[
Golia si accovaccia davanti a Tulu. Anche su un ginocchio, sovrasta la piccola figura di Tulu.

Guarda in basso, osservando il sudore freddo gocciolare in quegli occhi arancione chiaro.]]
  },
  AvgDialog_35826_Content_33 = {
    Text = "Ma persino qualcuno di così supremo come te, in fin dei conti, non è che un'esistenza fragile, tenuta insieme da esili fili di sanità mentale."
  },
  AvgDialog_35826_Content_34 = {
    Text = [[
Qualunque cosa Miryam abbia fatto al tuo Custode... sembra aver colpito anche te.

Bene, questo gioca a mio favore.]]
  },
  AvgDialog_35826_Content_35 = {
    Text = "Golia si volta e oltrepassa Tulu, dirigendosi verso il lato interno della plancia."
  },
  AvgDialog_35826_Content_36 = {
    Text = "Elton fa un passo avanti per fare scudo a Murphy, ma Golia non si degna nemmeno di rivolgergli uno sguardo."
  },
  AvgDialog_35826_Content_37 = {
    Text = "Con cosa pensi di fermarmi? Con questa ragazza semitrasparente?"
  },
  AvgDialog_35826_Content_38 = {
    Text = "Elton lancia istintivamente un'occhiata a Celeste, cercando incoraggiamento dalla Risvegliatrice solitamente silenziosa."
  },
  AvgDialog_35826_Content_39 = {
    Text = "Ma non riceve la risposta consueta. Anche dopo aver preso la medicina da Caecus, la presenza di Celeste resta precaria."
  },
  AvgDialog_35826_Content_4 = {
    Text = "Speranza che non si siano cacciati nei guai..."
  },
  AvgDialog_35826_Content_40 = {
    Text = "Elton esita."
  },
  AvgDialog_35826_Content_41 = {
    Text = "Vengo con te. Non rendergli le cose Difficile."
  },
  AvgDialog_35826_Content_42 = {Text = "Murphy?!"},
  AvgDialog_35826_Content_43 = {
    Text = "Tulu sembra sconvolto nell'udire queste parole. Lotta per rialzarsi, ma il dolore lancinante del legame spirituale frantuma la sua concentrazione, disperdendo la razionalità fino agli angoli più remoti delle sue membra."
  },
  AvgDialog_35826_Content_44 = {
    Text = "Va tutto bene... Non c'è bisogno di fare tutto questo per me..."
  },
  AvgDialog_35826_Content_45 = {
    Text = [[
Oh? Hai finalmente riacquistato i sensi, nostra Fanciulla Divina?

Non fare sciocchezze, o trascinerai tutti con te.]]
  },
  AvgDialog_35826_Content_46 = {
    Text = "So... cosa fare..."
  },
  AvgDialog_35826_Content_47 = {
    Text = "Murphy avanza di due passi, si ferma nella luce lunare e si volta a guardare coloro a cui tiene e coloro che hanno tenuto a lei. La sua figura appare solitaria e sfocata."
  },
  AvgDialog_35826_Content_48 = {
    Text = "Che si tratti di un rito o di qualcos'altro... questa volta, so cosa fare."
  },
  AvgDialog_35826_Content_5 = {
    Text = "Il mare si gonfia sotto la pallida luce lunare. La nave oscilla tra le onde, e il ponte scricchiola al ritmo del suo movimento."
  },
  AvgDialog_35826_Content_6 = {
    Text = "Tulu, come un'inamovibile statua di una divinità, si erge fuori dalla porta, bloccando quei Navigatori che sembrano non stancarsi mai."
  },
  AvgDialog_35826_Content_7 = {
    Text = "So cosa stai pensando. Il legame tra me e %player% è ancora intatto."
  },
  AvgDialog_35826_Content_8 = {
    Text = "Mentre parla, i suoi tentacoli scagliano abilmente un altro nemico in mare."
  },
  AvgDialog_35826_Content_9 = {
    Text = "Che {Male=lui,Female=lei} sia al sicuro..."
  },
  AvgDialog_35827_Content_1 = {
    Text = "I Navigatori portano sangue divino, la chiave per il passaggio del nostro signore attraverso innumerevoli calamità...\nLe stelle si stanno allineando; la rinascita del nostro signore è imminente... I codardi non meritano di camminare al nostro fianco nel Regno divino."
  },
  AvgDialog_35827_Content_10 = {
    Text = "Caecus, a capo chino, usa la sua arma per sorreggersi."
  },
  AvgDialog_35827_Content_11 = {
    Text = "Sì... questa è la tua ultima occasione, l'ultima opportunità di dimostrare la tua lealtà al Reame Divino."
  },
  AvgDialog_35827_Content_13 = {
    Text = "Fa roteare abilmente la lancia e infine la punta verso Miryam... Verso la sua \"padrona.\""
  },
  AvgDialog_35827_Content_14 = {
    Text = "Caecus non osa incrociare lo Sguardo di Miryam, ma si erge tra te e lei, come un muro fragile ma affidabile."
  },
  AvgDialog_35827_Content_15 = {
    Text = "Perdonatemi, Lady Miryam. Io..."
  },
  AvgDialog_35827_Content_16 = {
    Text = "Non ce n'è bisogno. Tu non sei un Navigatore... Lo sapevo fin dall'inizio."
  },
  AvgDialog_35827_Content_17 = {
    Text = "Miryam ridacchia, i suoi occhi di un viola insolito si volgono verso te e Ramona, apparentemente perdendo ogni interesse per Caecus."
  },
  AvgDialog_35827_Content_18 = {
    Text = "Caecus rilascia il respiro trattenuto, e l'istante dopo, mentre l'esalazione gli sfiora la pelle, sente il corpo sprofondare."
  },
  AvgDialog_35827_Content_19 = {
    Text = "Le sue gambe non riescono più a sostenere la parte superiore del corpo e crolla a terra. Il suo addome si gonfia come un pallone.\n\nDelle spine gli crescono improvvisamente, sfondando i vestiti, rivelando pinne dorsali simili a quelle di un pesce."
  },
  AvgDialog_35827_Content_2 = {
    Text = "Alza la testa, Caecus."
  },
  AvgDialog_35827_Content_20 = {
    Text = "<Change>Lady... Miryam..."
  },
  AvgDialog_35827_Content_21 = {
    Text = "I suoi bulbi oculari si trasformano rapidamente in un grigio-bianco putrescente, schiacciati dai muscoli che si deformano. Piccole squame iniziano a comparire sulla pelle, trasformando i gemiti di dolore in una lugubre nenia proveniente dall'abisso."
  },
  AvgDialog_35827_Content_22 = {
    Text = "Miryam ha reciso il suo Legame con Caecus!"
  },
  AvgDialog_35827_Content_23 = {
    Text = "Shh... Mantieni la calma. Niente panico."
  },
  AvgDialog_35827_Content_24 = {
    Text = "Miryam si china e tocca il volto di Caecus. Le sue mani si ricoprono ben presto di un liquido viscido e scivoloso, prova della trasformazione di Caecus."
  },
  AvgDialog_35827_Content_25 = {
    Text = "Questa è la tua prova... Solo abbracciando davvero il potere del mare profondo potrai ricevere la chiamata del Nostro Signore..."
  },
  AvgDialog_35827_Content_26 = {
    Text = "A differenza della precedente trasformazione mostruosa, selvaggia e completa, Miryam appare ora eccezionalmente calma e padrona di sé, pericolosa eppure elegante."
  },
  AvgDialog_35827_Content_27 = {
    Text = "Ma l'ombra alle sue spalle, sussurrante e deforme, e la D-melma rimasta sulle sue labbra a ogni incontro, rivelano pienamente l'oscurità che si propaga dentro di lei."
  },
  AvgDialog_35827_Content_28 = {
    Text = "Questa... è... la Sua prova per me..."
  },
  AvgDialog_35827_Content_29 = {
    Text = "È l'Effetto \"Cataclisma\"! Ha davvero permesso alla Dissoluzione di erodere il suo Spirito..."
  },
  AvgDialog_35827_Content_3 = {
    Text = "Continuare a combattere i Navigatori è inutile. Non possiamo trattenerli ancora. Se rimane in stato di Trance, dovremo lasciarlo nelle mani di Miryam."
  },
  AvgDialog_35827_Content_30 = {
    Text = "@2 blasfemo! Questa è la prova del mio Signore! Egli ha purificato il mio Nucleo d'Argento e mi ha concesso una seconda possibilità!"
  },
  AvgDialog_35827_Content_31 = {
    Text = "Questa è la Sua grazia concessa a me!"
  },
  AvgDialog_35827_Content_4 = {
    Text = "Svegliati! Caecus!"
  },
  AvgDialog_35827_Content_5 = {
    Text = "Come può un ragazzo come te frequentare i Navigatori?"
  },
  AvgDialog_35827_Content_6 = {
    Text = "Dici di essere già un Golem? Scusa, non volevo tirare fuori l'argomento..."
  },
  AvgDialog_35827_Content_7 = {
    Text = "Penso solo che tu non sia fragile come credi di essere./nScegli di fuggire da un ambiente doloroso. Non significa forse che hai un cuore più forte della maggior parte delle persone?"
  },
  AvgDialog_35827_Content_8 = {
    Text = "Sono tuo amico, Caecus.\nNon importa come ti vedi, ti incoraggerò a compiere il passo giusto."
  },
  AvgDialog_35827_Content_9 = {Text = "..."},
  AvgDialog_35828_Content_1 = {
    Text = "Questo è..."
  },
  AvgDialog_35828_Content_10 = {
    Text = "Elton ridacchia e saluta con la mano il gruppo che sta quasi uscendo dall'area del molo."
  },
  AvgDialog_35828_Content_11 = {
    Text = "I bambini non dovrebbero immischiarsi nelle faccende degli adulti. Che io non ritrovi mai la mia Terra dei Bianchi Uccelli perduta o che Celeste svanisca poco a poco, lo accetterò se questo è il nostro destino."
  },
  AvgDialog_35828_Content_12 = {
    Text = "Vai con loro, ragazzina. Non sentire troppo la nostra mancanza."
  },
  AvgDialog_35828_Content_13 = {
    Text = "Non sono una bambina!"
  },
  AvgDialog_35828_Content_14 = {
    Text = "Andate. Non voltarti indietro."
  },
  AvgDialog_35828_Content_15 = {
    Text = "Vai dove vuoi e fai ciò che ti piace."
  },
  AvgDialog_35828_Content_16 = {
    Text = "Qualcosa non Quadra. Il Capitano sembra fin troppo calmo."
  },
  AvgDialog_35828_Content_17 = {
    Text = "Per svelare il passato dimenticato, ha barattato metà della sua vita per Celeste."
  },
  AvgDialog_35828_Content_18 = {
    Text = "La lascerà correre così facilmente?"
  },
  AvgDialog_35828_Content_19 = {Text = "..."},
  AvgDialog_35828_Content_2 = {
    Text = "Sì. Siamo sulla terraferma."
  },
  AvgDialog_35828_Content_20 = {
    Text = "Un'automobile a quattro ruote sfreccia per la campagna, corre lungo le strade di Londinium, si lancia nelle lande deserte e infine si ferma in una piazza."
  },
  AvgDialog_35828_Content_21 = {
    Text = "È qui il posto."
  },
  AvgDialog_35828_Content_22 = {
    Text = "È passato molto tempo. Pensavo che questa volta non saresti tornato.\nIl mio cervello mi dice che hai riportato con te dei guai seri."
  },
  AvgDialog_35828_Content_23 = {Text = "Cervello?"},
  AvgDialog_35828_Content_24 = {
    Text = "Lei... È il Professor Doll?"
  },
  AvgDialog_35828_Content_25 = {
    Text = "Mi conosce già?"
  },
  AvgDialog_35828_Content_26 = {
    Text = "Ramona e %player% mi hanno parlato di te... e del tuo esperimento di stasi temporale in corso."
  },
  AvgDialog_35828_Content_27 = {
    Text = "Oh? Come le hanno parlato di me?"
  },
  AvgDialog_35828_Content_28 = {
    Text = "Murphy lancia istintivamente un'occhiata a %player%, che le fa l'occhiolino, chiaramente non volendo che dica la verità."
  },
  AvgDialog_35828_Content_29 = {
    Text = "Chiude gli occhi, cercando di ricordare i racconti del Custode sull'Università di Mythag. Tuttavia, tutto scorre via come acqua, le immagini le sfuggono tra le dita non appena prendono forma."
  },
  AvgDialog_35828_Content_3 = {
    Text = "Certo che lo so!"
  },
  AvgDialog_35828_Content_30 = {
    Text = "Murphy diventa eccezionalmente docile in presenza di Doll..."
  },
  AvgDialog_35828_Content_31 = {
    Text = "Probabilmente non ha mai frequentato una scuola, il che potrebbe spiegare la sua profonda reverenza per la Conoscenza."
  },
  AvgDialog_35828_Content_32 = {
    Text = "Ehi! Ho sentito!"
  },
  AvgDialog_35828_Content_33 = {
    Text = "Saltiamo le formalità."
  },
  AvgDialog_35828_Content_34 = {
    Text = "Il progetto di stasi temporale è ancora in fase di ricerca e non è stato verificato attraverso test sugli animali.\n\nUna volta entrato in quella stanza, non si potrà più tornare indietro."
  },
  AvgDialog_35828_Content_35 = {
    Text = "Allora, hai fatto la tua scelta?"
  },
  AvgDialog_35828_Content_36 = {Text = "Scelta...?"},
  AvgDialog_35828_Content_37 = {
    Text = "Non dovrò più farmi trascinare dalle decisioni altrui?"
  },
  AvgDialog_35828_Content_38 = {
    Text = "Posso... fare una scelta?"
  },
  AvgDialog_35828_Content_39 = {
    Text = "No... no, non è giusto... Non dovrei essere qui... Ero preparata..."
  },
  AvgDialog_35828_Content_4 = {
    Text = "Non agitarti troppo. Se la pressione sanguigna sale, l'attività della Specie Parassita aumenterà.\nImmagino che non vorresti essere sventrata a metà strada, vero?"
  },
  AvgDialog_35828_Content_40 = {
    Text = "È un altro Incubo che sfida la mia volontà, Correggere?"
  },
  AvgDialog_35828_Content_41 = {
    Text = "\"Esso\" è nato?"
  },
  AvgDialog_35828_Content_42 = {
    Text = "È tutto finito? Eppure io chiaramente... avevo trovato la mia <Yellow:determinazione.>"
  },
  AvgDialog_35828_Content_43 = {
    Text = "I ricordi e la coscienza di Murphy vagano nell'illusione, mentre il mondo sotto di lei si sgretola e si dissolve. In preda al panico, tende la mano verso %player%, ma afferra solo una manciata di polvere."
  },
  AvgDialog_35828_Content_44 = {
    Text = "%player%...? Dove sei?"
  },
  AvgDialog_35828_Content_45 = {
    Text = "Sprofonda in un'oscurità caotica. L'udito si acuisce, ma riesce a percepire solo il proprio battito cardiaco assordante. Le stelle precipitano attraverso lo spazio profondo, sfiorando la Barriera Dimensionale e lasciando dietro di sé una scia di pianto."
  },
  AvgDialog_35828_Content_46 = {
    Text = "Non avevi promesso... che non mi avresti abbandonata?"
  },
  AvgDialog_35828_Content_47 = {
    Text = "Poco fa hai quasi \"perso il controllo\", vero? È successo qualcosa a quei due?"
  },
  AvgDialog_35828_Content_48 = {
    Text = "Tulu si stringe il petto, rivelando una rara espressione di shock persistente."
  },
  AvgDialog_35828_Content_49 = {
    Text = "......Non importa. Golia ha preso Murphy. Il Custode ora combatte una battaglia al di là delle proprie forze — necessiterà dell'intervento di Questo Essere."
  },
  AvgDialog_35828_Content_5 = {
    Text = [[
Custode, smettila di prenderla in giro.
Non preoccuparti. La signorina Celeste ci ha fatto guadagnare del tempo, e torneremo a Londinium sani e salvi.]]
  },
  AvgDialog_35828_Content_50 = {
    Text = "Andate pure. Celeste e io staremo bene."
  },
  AvgDialog_35828_Content_51 = {
    Text = "...C'è qualcosa che non va? Stanno tutti bene?"
  },
  AvgDialog_35828_Content_52 = {
    Text = "Sembra che Miryam ti abbia completamente abbandonato, Caecus."
  },
  AvgDialog_35828_Content_53 = {
    Text = "Caecus lotta per rialzarsi ancora e ancora, gli scherni di Golia non più in grado di scuotere la sua determinazione."
  },
  AvgDialog_35828_Content_54 = {
    Text = "Nemmeno voi siete davvero leale verso Lady Miryam... non è così, Lord Golia?"
  },
  AvgDialog_35828_Content_55 = {
    Text = "Mi dispiace, ma non vi lascerò passare."
  },
  AvgDialog_35828_Content_56 = {
    Text = "Perché... perché? Perché hai deciso di nuovo al posto mio?"
  },
  AvgDialog_35828_Content_57 = {
    Text = "La parete esterna del bozzolo è troppo spessa e il fluido interno è torbido. Non riusciamo a vedere lo stato di Murphy all'interno."
  },
  AvgDialog_35828_Content_58 = {
    Text = "Caecus non potrà trattenere Golia a lungo. Lasciatemi tentare di nuovo il Tracciamento Spirituale."
  },
  AvgDialog_35828_Content_59 = {
    Text = "No! Il tuo reame spirituale non può sopportarlo di nuovo! Una volta che collassa, nessuna riparazione del corpo potrà salvarti!"
  },
  AvgDialog_35828_Content_6 = {
    Text = "Grazie, Ramona... Parlare con te mi fa davvero sentire tranquilla."
  },
  AvgDialog_35828_Content_60 = {
    Text = "Ma Murphy, lei—"
  },
  AvgDialog_35828_Content_61 = {
    Text = "Tutti voi... Siete tutti uguali. Un branco di egoisti."
  },
  AvgDialog_35828_Content_62 = {
    Text = [[
Nessuno ha mai chiesto la mia opinione... Hmph.
Sopravvivere al prezzo dei vostri sacrifici... Ho mai detto di volerlo?]]
  },
  AvgDialog_35828_Content_63 = {
    Text = "Per fortuna... <Yellow:Quella cosa> è ancora qui..."
  },
  AvgDialog_35828_Content_64 = {
    Text = "Il cargo oscilla tra le onde gigantesche, ogni ondata solleva la nave dalla superficie del mare. Esci dalla cabina, alzi lo sguardo verso il bozzolo nero in alto e scuoti la testa verso Ramona."
  },
  AvgDialog_35828_Content_65 = {
    Text = "—Poi, ignorando la sua resistenza, afferri la tremante Chiave d'Argento e sprofondi ancora una volta nel Reame dello Spirito."
  },
  AvgDialog_35828_Content_66 = {
    Text = "Nello spazio buio e vuoto ricoperto dalla D-Melma, una minuscola scintilla che simboleggia vita e intelligenza brilla con ancor più fulgore."
  },
  AvgDialog_35828_Content_67 = {
    Text = "—Una lama sacrificale risplende, riflettendo la fredda, spettrale luce lunare."
  },
  AvgDialog_35828_Content_68 = {Text = "—AAGH!!"},
  AvgDialog_35828_Content_7 = {
    Text = "Hmph, qualcuno dovrebbe proprio imparare da te."
  },
  AvgDialog_35828_Content_70 = {
    Text = "Un'esplosione di luce erutta all'improvviso, scaraventandoti con forza fuori dal Reame dello Spirito."
  },
  AvgDialog_35828_Content_71 = {
    Text = "La luce abbagliante ti ferisce gli occhi, provocando lacrime incontenibili."
  },
  AvgDialog_35828_Content_73 = {
    Text = "Il liquido torbido defluisce, e i tuoi occhi finalmente tornano a mettere a fuoco la bambina."
  },
  AvgDialog_35828_Content_74 = {
    Text = "La lama affonda nel suo petto, e la bambina illuminata dalla luna apre gli occhi."
  },
  AvgDialog_35828_Content_75 = {
    Text = "La luna piena, simbolo di morte, incombe vicina, eppure non vi è traccia di terrore sul suo volto giovane."
  },
  AvgDialog_35828_Content_76 = {
    Text = "Ce l'ho fatta... Ce l'ho fatta davvero."
  },
  AvgDialog_35828_Content_77 = {
    Text = "L'ho... trafitto... Non nascerà..."
  },
  AvgDialog_35828_Content_78 = {
    Text = "Allora... Loro possono..."
  },
  AvgDialog_35828_Content_79 = {
    Text = "La mano che stringe il coltello cade debolmente, mentre un liquido cremisi, viscoso e scuro cola dalla lama, gocciolando tra le sue dita nel mare."
  },
  AvgDialog_35828_Content_8 = {
    Text = "Murphy si volta a guardare il molo dove Elton e Celeste sono rimasti accanto alla barca, osservandola da lontano."
  },
  AvgDialog_35828_Content_80 = {
    Text = "Il sangue defluisce rapidamente dal suo corpo; la pelle di Murphy diventa di un pallore cadaverico, eppure emana un'insolita vitalità."
  },
  AvgDialog_35828_Content_82 = {
    Text = "No... No, <Big:NONONO> <BigShake:AHHHHH—>"
  },
  AvgDialog_35828_Content_83 = {
    Text = "Oh Signore, perdonami, perdona questa bambina, perdona la Tua devota credente..."
  },
  AvgDialog_35828_Content_84 = {
    Text = "L'Allineamento Stellare, è vicino... È vicino..."
  },
  AvgDialog_35828_Content_86 = {
    Text = "La \"placenta\" si frantuma, e anche il \"cuore\" collassa—innumerevoli mani erompono dal corpo, sfondando la cavità toracica."
  },
  AvgDialog_35828_Content_87 = {
    Text = "Una mano deforme afferra le spoglie irriconoscibili, sovrapponendosi e gonfiandosi, sovrapponendosi e gonfiandosi—"
  },
  AvgDialog_35828_Content_88 = {
    Text = "Ah... Mi avete udito... Mi avete risposto..."
  },
  AvgDialog_35828_Content_9 = {
    Text = "Celeste, Capitano? Non venite con noi?"
  },
  AvgDialog_35828_Content_90 = {
    Text = "Spingono un'entità deforme nella luce lunare."
  },
  AvgDialog_35828_Content_91 = {
    Text = "<Big:Mio Onnipotente Signore...!>"
  },
  AvgDialog_35829_Content_1 = {
    Text = "Tu e Ramona, esausti e malconci, riuscite finalmente a trascinarvi vicino al \"Neonato\"."
  },
  AvgDialog_35829_Content_10 = {
    Text = "Non scusarti con me. Non è colpa tua... non è colpa di nessuno."
  },
  AvgDialog_35829_Content_11 = {
    Text = "Al contrario, noi siamo l'ultima barriera in grado di impedire a questa cosa di entrare nella società umana."
  },
  AvgDialog_35829_Content_12 = {
    Text = "Non preoccuparti, con il grave inquinamento atmosferico di Londinium, non troverà mai la strada per la città."
  },
  AvgDialog_35829_Content_13 = {
    Text = "Facendo una battuta per allentare la tensione, scambi un ultimo sguardo con Ramona e muovi un passo tenace—"
  },
  AvgDialog_35829_Content_14 = {
    Text = [[
Tempo all'Allineamento:
0 minuti]]
  },
  AvgDialog_35829_Content_2 = {
    Text = "Il \"Neonato\" nel bozzolo nero traslucido ha una forma contorta, simile a un gigantesco e fragile embrione di primate."
  },
  AvgDialog_35829_Content_3 = {
    Text = "La testa è grande e rotonda, con arti goffi che si contraggono come cercando una direzione in cui crescere."
  },
  AvgDialog_35829_Content_4 = {
    Text = "Emana un'aura maligna indescrivibile, inducendo te e Ramona a scambiarvi uno sguardo — questa entità potrebbe essere in grado di comandare l'Aequor, ma non è in alcun modo la genesi del potere di Tulu."
  },
  AvgDialog_35829_Content_5 = {
    Text = "Questa cosa... Abbiamo davvero una possibilità?"
  },
  AvgDialog_35829_Content_6 = {Text = "Non lo so."},
  AvgDialog_35829_Content_7 = {
    Text = "Afferri la mano di Ramona, i muscoli rigidi e stanchi, forzando un sorriso tirato."
  },
  AvgDialog_35829_Content_8 = {
    Text = "Scusa... non so se riusciremo a fare ritorno a Mythag questa volta."
  },
  AvgDialog_35829_Content_9 = {
    Text = "Ramona ti afferra con decisione, senza esitare."
  },
  AvgDialog_35830_Content_1 = {
    Text = "Ancora nessuna risposta da Caecus?"
  },
  AvgDialog_35830_Content_10 = {
    Text = "La mia nave è attraccata al molo. Perché non salire a bordo a scaldarti?"
  },
  AvgDialog_35830_Content_11 = {
    Text = "Caecus si immobilizzò sul posto, e dopo un lungo istante, parlò infine in tono rigido."
  },
  AvgDialog_35830_Content_12 = {
    Text = "Non c'è bisogno di adularmi se vuoi mantenere i rapporti con l'ordine."
  },
  AvgDialog_35830_Content_13 = {
    Text = "Adularti? No. Non sono il tipo che sta a guardare qualcuno morire congelato nella neve."
  },
  AvgDialog_35830_Content_14 = {
    Text = "Elton colse l'attimo di distrazione di Caecus, avanzò di due passi e gli afferrò saldamente il braccio freddo e sottile."
  },
  AvgDialog_35830_Content_15 = {
    Text = "Facciamoci amici, che ne dici? Io sono Elton. Hai un nome, ragazzo?"
  },
  AvgDialog_35830_Content_16 = {Text = "..."},
  AvgDialog_35830_Content_17 = {
    Text = "Caecus. Chiamami semplicemente Caecus."
  },
  AvgDialog_35830_Content_2 = {
    Text = "Sembra che sia perso nel vuoto..."
  },
  AvgDialog_35830_Content_3 = {
    Text = "In un momento così cruciale?!"
  },
  AvgDialog_35830_Content_4 = {
    Text = "Ecco le medicine di questo trimestre. Prendetele ogni sette giorni, se non volete impazzire e diventare uno zombie."
  },
  AvgDialog_35830_Content_5 = {
    Text = "Caecus posò la medicina a terra e la spinse delicatamente, lasciando che la boccetta rotolasse verso l'uomo fermo a tre metri di distanza."
  },
  AvgDialog_35830_Content_6 = {
    Text = "Il vento della notte invernale ululava. Si strinse nel grande mantello nero e si affrettò nell'oscurità."
  },
  AvgDialog_35830_Content_7 = {
    Text = "Aspetta... sta per nevicare. Questo porto naturale non è la fermata abituale del Navigatore. Dove andrai a ripararti dalla neve?"
  },
  AvgDialog_35830_Content_8 = {
    Text = "La coda delle parole di Elton fu divorata da una raffica di vento particolarmente feroce e gelida fino alle ossa. Il cappuccio del mantello nero di Caecus fu improvvisamente spinto all'indietro, rivelando un paio di pinne auricolari simili a quelle di un pesce che tremavano nel vento freddo."
  },
  AvgDialog_35830_Content_9 = {
    Text = "Il cuore gli si strinse, e si risistemò goffamente il cappuccio, allontanandosi in modo ancora più frettoloso e maldestro."
  },
  AvgDialog_35831_Content_1 = {
    Text = "Immondo@2... Ugh!"
  },
  AvgDialog_35831_Content_10 = {
    Text = "All'improvviso, tutto tace. I Navigatori che fino a poco prima vociavano per cacciarlo via fissano attoniti la donna sulla piattaforma, in Attesa dei prossimi ordini della loro padrona."
  },
  AvgDialog_35831_Content_11 = {
    Text = "Alza la testa."
  },
  AvgDialog_35831_Content_12 = {
    Text = "Finalmente trovò il coraggio di alzare lo sguardo, contemplandola con reverenza come se fosse la sua Dea predestinata."
  },
  AvgDialog_35831_Content_13 = {
    Text = "Lady Miryam... Io..."
  },
  AvgDialog_35831_Content_14 = {
    Text = "Non c'è dubbio, siete un discendente della famiglia Ornn... Avete una certa somiglianza con i vostri antenati."
  },
  AvgDialog_35831_Content_15 = {
    Text = "Ma... sei troppo debole."
  },
  AvgDialog_35831_Content_16 = {
    Text = "Il suo cuore sprofondò. Il solo guardare Miryam prosciugò tutto il suo coraggio, rendendo impossibile confutare la sua conclusione."
  },
  AvgDialog_35831_Content_17 = {
    Text = "Dal momento che ti ho già risvegliato, per rispetto verso la famiglia Ornn, posso mantenere la tua esistenza come Golem... D'ora in poi, sarà tua responsabilità sorvegliare i Navigatori e i loro collaboratori umani."
  },
  AvgDialog_35831_Content_18 = {
    Text = "In quanto \"mezzosangue,\" dovreste sapere meglio di chiunque come comunicare con gli esseri umani."
  },
  AvgDialog_35831_Content_2 = {
    Text = "I Navigatori brandiscono le loro armi; l'acciaio freddo riflette un bagliore argenteo sotto la luce lunare, costringendo Caecus a socchiudere gli occhi involontariamente."
  },
  AvgDialog_35831_Content_3 = {
    Text = "Attraverso la visuale offuscata, scorge i piedi di Miryam. La sua memoria torna a un tempo in cui giaceva prostrato sotto un freddo altare."
  },
  AvgDialog_35831_Content_4 = {
    Text = "Estraneo... Gorgoglio..."
  },
  AvgDialog_35831_Content_5 = {
    Text = "Finalmente... finalmente raggiunge questo luogo."
  },
  AvgDialog_35831_Content_6 = {
    Text = "Via... @1... FUORI!"
  },
  AvgDialog_35831_Content_7 = {
    Text = "La sua Ossessione per le sue origini e per i Navigatori lo conduce qui."
  },
  AvgDialog_35831_Content_8 = {
    Text = "Mezzosangue... Immondo! <Big:IMMONDO!>"
  },
  AvgDialog_35831_Content_9 = {Text = "Silenzio."},
  AvgDialog_35832_Content_1 = {
    Text = "Basta... Il Filistea ha portato a termine il suo Compito."
  },
  AvgDialog_35832_Content_10 = {
    Text = "Sopporti il dolore e, con razionalità, guidi i tuoi filamenti spirituali nella mente di Caecus."
  },
  AvgDialog_35832_Content_11 = {
    Text = "La casa nel suo Reame dello Spirito crolla. Se smetti di muoverti, voci beffarde e sprezzanti sgorgano da ogni angolo, rodendo la volontà dell'intruso come specie parassite."
  },
  AvgDialog_35832_Content_12 = {
    Text = "Segui i gemiti di sofferenza e trovi Caecus rannicchiato in un angolo."
  },
  AvgDialog_35832_Content_13 = {
    Text = "Il suo spirito è compresso e marginalizzato, confinato in una stanza che ricorda la cabina di una nave. Se non fosse per quei suoni ritmici simili a segnali di soccorso, potresti quasi non notare la sua presenza."
  },
  AvgDialog_35832_Content_14 = {Text = "Caecus..."},
  AvgDialog_35832_Content_15 = {
    Text = "Tendi la mano verso di lui, e nell'istante in cui le vostre coscienze si connettono, una forte sensazione di soffocamento ti risale lungo la gola."
  },
  AvgDialog_35832_Content_16 = {
    Text = "La reazione da ipossia riporta ancora una volta le vertigini e il dolore che credevi ormai passati, provocando una smorfia momentanea sui volti di tutti coloro che sono connessi al tuo spirito."
  },
  AvgDialog_35832_Content_17 = {
    Text = "Ramona è la prima a subirne il contraccolpo, scoppiando immediatamente in un sudore freddo e crollando in ginocchio."
  },
  AvgDialog_35832_Content_18 = {
    Text = "Tendi la mano per aiutarla, ma senti un capogiro e barcollando fai due passi prima di crollare a terra—"
  },
  AvgDialog_35832_Content_19 = {
    Text = "Fa' attenzione."
  },
  AvgDialog_35832_Content_2 = {
    Text = "Miryam indietreggia fino al bordo della crepa nello scafo, afferrando l'acciaio tagliente. La sua espressione è celata nell'ombra proiettata dalla sua corona, e riesci solo a vedere le sue labbra muoversi appena, come se stesse dicendo qualcosa."
  },
  AvgDialog_35832_Content_20 = {
    Text = "Huff... huff... Per un istante, ho sentito la morte dietro l'angolo..."
  },
  AvgDialog_35832_Content_21 = {
    Text = "Custode, cosa è accaduto al vostro Corpo?"
  },
  AvgDialog_35832_Content_22 = {
    Text = "Riprendete fiato e scuotete il capo, ritrovando l'equilibrio con l'aiuto di Caecus."
  },
  AvgDialog_35832_Content_23 = {
    Text = "Non c'è tempo per spiegare, noi, dobbiamo—"
  },
  AvgDialog_35832_Content_24 = {
    Text = "Dobbiamo raggiungere il ponte! È una trappola ordita da Lady Miryam e Lord Golia!"
  },
  AvgDialog_35832_Content_25 = {
    Text = "Ramona non fa altre domande, né vi segue immediatamente, te e Caecus.\n\nRaschia i residui di carbone umido dalla caldaia e aggiunge rapidamente del carbone asciutto."
  },
  AvgDialog_35832_Content_26 = {
    Text = "La candela d'accensione ruota, facendo evaporare rapidamente l'umidità residua, e l'odore di bruciato riempie ancora una volta la sala macchine."
  },
  AvgDialog_35832_Content_27 = {
    Text = "Usciamo di qui, prima di tutto. Caecus, facci strada."
  },
  AvgDialog_35832_Content_3 = {
    Text = "—E poi, lei lascia la presa, cadendo in mare."
  },
  AvgDialog_35832_Content_4 = {
    Text = "La superficie del mare illuminata dalla luce lunare viene improvvisamente perturbata, creando una scia di schiuma che fende le onde e si estende fino all'altra sponda della nave."
  },
  AvgDialog_35832_Content_5 = {
    Text = "Andate a controllare Caecus!"
  },
  AvgDialog_35832_Content_6 = {
    Text = "Caecus non riesce più a parlare; ogni tentativo produce soltanto sempre più muco, come se i suoi organi in eccesso fossero già stati assimilati."
  },
  AvgDialog_35832_Content_7 = {
    Text = "Ha quasi perso del tutto la sua forma umana. Per fortuna, rimane lucido, limitandosi a rannicchiarsi dal dolore invece di sprofondare nella follia come Helot."
  },
  AvgDialog_35832_Content_8 = {
    Text = "Ti accovacci davanti a Caecus e gli afferri la mano senza esitazione."
  },
  AvgDialog_35832_Content_9 = {
    Text = "Legame con Caecus."
  },
  AvgDialog_35984_Content_1 = {
    Text = "Patto del Grande Slam"
  },
  AvgDialog_35984_Content_10 = {Text = "Bang!"},
  AvgDialog_35984_Content_11 = {
    Text = "Il vaso sfrecciò rapidamente accanto al viso di George."
  },
  AvgDialog_35984_Content_12 = {
    Text = "Sto impazzendo dalla noia al museo delle cere ogni giorno. Non ho nemmeno la libertà di cantare?!"
  },
  AvgDialog_35984_Content_13 = {
    Text = "Qualcuno continua a cantare, e George continua a imprecare, hehe."
  },
  AvgDialog_35984_Content_14 = {
    Text = "Lord Rogers, tenete a freno il vostro amato animale domestico; si è trasformato in un vero demonio!"
  },
  AvgDialog_35984_Content_15 = {
    Text = "Hmm... Botticelli... Primavera..."
  },
  AvgDialog_35984_Content_16 = {
    Text = "Dove troverò la modella questa volta...?"
  },
  AvgDialog_35984_Content_17 = {Text = "..."},
  AvgDialog_35984_Content_18 = {
    Text = "Visto che non c'è nient'altro da fare, perché non giocare a carte?"
  },
  AvgDialog_35984_Content_19 = {
    Text = "Pandia estrasse abilmente un mazzo di carte dal cassetto e lo sbatté sul tavolo."
  },
  AvgDialog_35984_Content_2 = {
    Text = "Dominio Artificiale: Museo delle Cere di Rogers"
  },
  AvgDialog_35984_Content_20 = {
    Text = "Ancora bridge? A George non piace giocare a bridge. \nInoltre, senza il servo vampiro, ci manca ancora una persona—"
  },
  AvgDialog_35984_Content_21 = {
    Text = "Pandia indicò l'angolo. Accanto al mobile trascurato, \"24\" stava pulendo gli oggetti esposti all'interno."
  },
  AvgDialog_35984_Content_22 = {
    Text = "Contala, e siamo al completo."
  },
  AvgDialog_35984_Content_23 = {
    Text = "Hmm... Sono chiare tutte le regole adesso?"
  },
  AvgDialog_35984_Content_24 = {Text = "Capito."},
  AvgDialog_35984_Content_25 = {
    Text = "Questo tizio porta persino gli occhiali. È un poveraccio del Distretto Est che finge di essere colto? Che imbarazzo!"
  },
  AvgDialog_35984_Content_26 = {
    Text = "Ne sei davvero sicuro? È piuttosto complesso—"
  },
  AvgDialog_35984_Content_27 = {
    Text = "52 carte, 13 per giocatore. Si vince ogni mano con @21 prese. Il contratto è fissato con una base di 6 prese. Solo le prese oltre @16 contano come prese vincenti."
  },
  AvgDialog_35984_Content_28 = {
    Text = "Ehm... niente male."
  },
  AvgDialog_35984_Content_29 = {
    Text = "Vedo improvvisamente del potenziale in te. Che ne dici di fare squadra?"
  },
  AvgDialog_35984_Content_3 = {
    Text = "Ah! Il principe sul cavallo bianco che scende dal cielo~"
  },
  AvgDialog_35984_Content_30 = {
    Text = "Lord Rogers, se vinco, mi concederete una richiesta?"
  },
  AvgDialog_35984_Content_31 = {
    Text = "Hehe, qualcuno sta per essere rimesso al suo posto!"
  },
  AvgDialog_35984_Content_32 = {
    Text = "Dimmi, qual è la tua richiesta?"
  },
  AvgDialog_35984_Content_33 = {
    Text = "Non vi serve ancora un modello per la vostra collezione di sculture di cera? Posso fare da modello."
  },
  AvgDialog_35984_Content_34 = {
    Text = "Wow~ Signorina 24, ti offri volontaria per correre incontro alla morte?"
  },
  AvgDialog_35984_Content_35 = {
    Text = "\"24\" abbassò silenziosamente la testa, le nocche che stringevano la scopa diventarono leggermente bianche."
  },
  AvgDialog_35984_Content_36 = {
    Text = "<Gray:\"Primavera\" è un'opera che Rogers intende esporre alla fiera. Essere scelta come modella ne aumenterà la visibilità e permetterà a più persone di vederla.>"
  },
  AvgDialog_35984_Content_37 = {
    Text = "<Gray:Jenkin...>"
  },
  AvgDialog_35984_Content_38 = {
    Text = "Certo. Signorina 24, la tua struttura ossea è liscia ed elegante, il che ti rende perfetta per questo ruolo."
  },
  AvgDialog_35984_Content_39 = {
    Text = "Sono così, così felice che tu ti sia unita volontariamente alla mia grande arte."
  },
  AvgDialog_35984_Content_4 = {
    Text = "Ha varcato questa porta e mi ha rubato il cuore—"
  },
  AvgDialog_35984_Content_40 = {
    Text = "Due ore dopo"
  },
  AvgDialog_35984_Content_41 = {Text = "Tsk..."},
  AvgDialog_35984_Content_42 = {Text = "Ah..."},
  AvgDialog_35984_Content_43 = {
    Text = "Wow, grande slam! 24, fare squadra con te porta una fortuna incredibile, la la la~"
  },
  AvgDialog_35984_Content_44 = {
    Text = "Voi due, pagate!"
  },
  AvgDialog_35984_Content_45 = {
    Text = "Rogers sorrise e lanciò alcune monete d'argento."
  },
  AvgDialog_35984_Content_46 = {
    Text = "Chi l'avrebbe mai detto che avevamo un'esperta nascosta qui? Davvero impressionante."
  },
  AvgDialog_35984_Content_47 = {
    Text = "Com'è possibile... Questo tizio non aveva nemmeno capito le regole poco fa!"
  },
  AvgDialog_35984_Content_48 = {
    Text = "George ha osservato segretamente 24 per un mese, confermando che è una vera sciocca. Come può essere così intelligente..."
  },
  AvgDialog_35984_Content_49 = {
    Text = "Grazia, George. Grazia. I cattivi pagatori non crescono mai~"
  },
  AvgDialog_35984_Content_5 = {Text = "Il,"},
  AvgDialog_35984_Content_50 = {
    Text = "Il volto di George divenne rosso cremisi dalla rabbia."
  },
  AvgDialog_35984_Content_51 = {
    Text = "Sta barando, deve per forza star barando!"
  },
  AvgDialog_35984_Content_52 = {
    Text = "Sono solo semplici problemi di matematica. In base alle informazioni attuali del tavolo, le probabilità calcolate della distribuzione delle 4 picche sono 0,023, 0,183 e 0,412..."
  },
  AvgDialog_35984_Content_53 = {Text = "..."},
  AvgDialog_35984_Content_54 = {
    Text = "Wow, non ci capisco assolutamente nulla."
  },
  AvgDialog_35984_Content_55 = {
    Text = "...0,314, 0,069. Pertanto, darò priorità a @1 e @2 nella chiusura del round, ed eseguirò il calcolo basandomi sulla sequenza delle tue carte..."
  },
  AvgDialog_35984_Content_56 = {
    Text = "Ascoltando il meticoloso riepilogo di \"24\", George abbassò la testa e iniziò a contare sulle sue dita paffute."
  },
  AvgDialog_35984_Content_57 = {
    Text = "Non è possibile. Perché non riesco a capirlo...?"
  },
  AvgDialog_35984_Content_58 = {
    Text = "Obiezione! Sono tutte scuse! Pensi che sputare cose che non capiamo ti permetterà di sfuggire alla punizione?!"
  },
  AvgDialog_35984_Content_59 = {
    Text = "George si avventò su \"24\"."
  },
  AvgDialog_35984_Content_6 = {Text = "Mio,"},
  AvgDialog_35984_Content_60 = {
    Text = "Fammi vedere se stai nascondendo qualcosa—"
  },
  AvgDialog_35984_Content_61 = {Text = "Zing—!!"},
  AvgDialog_35984_Content_62 = {
    Text = "Il tetto del museo delle cere si aprì misteriosamente con un enorme squarcio, e qualcosa di pesante si schiantò su George, riducendolo in poltiglia."
  },
  AvgDialog_35984_Content_63 = {Text = "Awoo!!"},
  AvgDialog_35984_Content_64 = {
    Text = "Prima che potesse pronunciare una frase completa, George tacque per sempre."
  },
  AvgDialog_35984_Content_65 = {
    Text = "Ahem... Cos'è questa sostanza appiccicosa sul mio sedere...?"
  },
  AvgDialog_35984_Content_66 = {
    Text = "Eh, non dovevo tornare indietro? Come sono finito al museo delle cere?"
  },
  AvgDialog_35984_Content_67 = {
    Text = "{Male=Signor,Female=Signorina} %player%, state bene?"
  },
  AvgDialog_35984_Content_68 = {
    Text = "Signorina Mason, anche lei è qui?! Sono ancora nel Dominio..."
  },
  AvgDialog_35984_Content_69 = {
    Text = "Ahhh! È... è caduto dal cielo..."
  },
  AvgDialog_35984_Content_7 = {
    Text = "<Big:Cuore!>"
  },
  AvgDialog_35984_Content_70 = {
    Text = "Joe, George?"
  },
  AvgDialog_35984_Content_71 = {
    Text = "Rogers fissò sconvolto il corpo straziato di George sotto di te, gli occhi colmi di rabbia e dolore infiniti."
  },
  AvgDialog_35984_Content_72 = {
    Text = "Pandia... Prendili!"
  },
  AvgDialog_35984_Content_8 = {
    Text = "Tsk tsk, qualcuno ha passato troppo tempo con gli schiavi vampiri e ha imparato a cantare."
  },
  AvgDialog_35984_Content_9 = {
    Text = "Orribile, semplicemente orribile!"
  },
  AvgDialog_35985_Content_1 = {Text = "Mmph—!!"},
  AvgDialog_35985_Content_10 = {
    Text = "No, le mie sculture di cera..."
  },
  AvgDialog_35985_Content_11 = {
    Text = "Prima che tu possa reagire, il tuo polso viene afferrato con forza."
  },
  AvgDialog_35985_Content_12 = {
    Text = "Sbrigati e seguimi per uscire di qui."
  },
  AvgDialog_35985_Content_13 = {
    Text = "Nella notte silenziosa, tre persone corsero mano nella mano attraverso un incrocio dopo l'altro."
  },
  AvgDialog_35985_Content_14 = {
    Text = "Uff... Signorina, ehm, Occhiali-24, per quanto ancora dobbiamo continuare a correre...?"
  },
  AvgDialog_35985_Content_15 = {
    Text = "Qui andrà bene. Rogers non vorrebbe venire in un cimitero così sgradevole."
  },
  AvgDialog_35985_Content_16 = {
    Text = "Questa volta è tutto merito vostro."
  },
  AvgDialog_35985_Content_17 = {
    Text = "Quel piccoletto tiene gli occhi incollati su di me, e le loro spie sono ovunque nel museo delle cere. Tutti i miei 23 piani di fuga sono falliti."
  },
  AvgDialog_35985_Content_18 = {
    Text = "È stato solo un incidente... Non capiamo nemmeno noi come siamo finiti qui."
  },
  AvgDialog_35985_Content_19 = {
    Text = "Eh, non siete sorpresi? Trovarvi faccia a faccia con un'altra versione di voi stessi."
  },
  AvgDialog_35985_Content_2 = {
    Text = "Niente male. Sembra che i <Red:piccoli> sottoterra dovrebbero svegliarsi e mettersi al lavoro..."
  },
  AvgDialog_35985_Content_20 = {
    Text = "\"24\" e Mason ti guardano all'unisono, come se avessi fatto una domanda molto strana."
  },
  AvgDialog_35985_Content_21 = {
    Text = "Non capisco cosa intendi... Ci sono molti 24 nel mondo, e li incontreremo sempre."
  },
  AvgDialog_35985_Content_22 = {
    Text = "<Gray:Che siano le strane regole di questo Dominio...?>"
  },
  AvgDialog_35985_Content_23 = {
    Text = "Lascia perdere, non importa."
  },
  AvgDialog_35985_Content_24 = {
    Text = "Devo andare a casa adesso; Jenkin deve essere preoccupato per me."
  },
  AvgDialog_35985_Content_25 = {
    Text = "Aspetta, Signorina 24!!"
  },
  AvgDialog_35985_Content_26 = {
    Text = "\"24\" avanza a grandi passi; ha cose più importanti da fare. Tuttavia—"
  },
  AvgDialog_35985_Content_27 = {Text = "Toc toc."},
  AvgDialog_35985_Content_28 = {
    Text = "Sento come se i miei organi interni fossero tirati da fili invisibili, staccandosi rapidamente dalle loro posizioni originali."
  },
  AvgDialog_35985_Content_29 = {Text = "Mmph—!!"},
  AvgDialog_35985_Content_3 = {
    Text = "I piccoli di sotto..."
  },
  AvgDialog_35985_Content_30 = {
    Text = "Qualcosa qui vicino... Chi c'è?!"
  },
  AvgDialog_35985_Content_31 = {
    Text = "\"24\" si strinse il petto e si piegò dal dolore."
  },
  AvgDialog_35985_Content_32 = {
    Text = "Un istante dopo, il terreno sotto le sue ginocchia divenne rapidamente bianco, e il mondo intero si trasformò in una vasta distesa di bianco."
  },
  AvgDialog_35985_Content_33 = {
    Text = "Quando riapre gli occhi, il cielo e la terra innevata si fondono in un vuoto imperscrutabile, con solo le montagne ininterrotte che si ergono davanti a lei."
  },
  AvgDialog_35985_Content_34 = {
    Text = "Tutto è immerso nella pallida luce azzurra del sole polare, fredda e tagliente, priva di gioia o dolore."
  },
  AvgDialog_35985_Content_35 = {
    Text = "Si inginocchiò ai piedi della montagna innevata."
  },
  AvgDialog_35985_Content_4 = {
    Text = "Probabilmente si riferiscono alle sculture di cera che abbiamo visto nel seminterrato del museo delle cere."
  },
  AvgDialog_35985_Content_5 = {
    Text = "Se sono loro, allora sarà sicuramente una battaglia estenuante..."
  },
  AvgDialog_35985_Content_6 = {Text = "Splash"},
  AvgDialog_35985_Content_7 = {
    Text = "In un angolo trascurato, qualcuno usò una candela per dare fuoco ai resti di George."
  },
  AvgDialog_35985_Content_8 = {
    Text = "In un attimo, il museo delle cere fu avvolto da fiamme furiose."
  },
  AvgDialog_35985_Content_9 = {
    Text = "Oh no, ha preso fuoco!"
  },
  AvgDialog_35987_Content_1 = {Text = "\"Origine\""},
  AvgDialog_35987_Content_10 = {
    Text = "Eh? La signorina Winkle ha detto che il mio Dominio è terrificante, pieno di mostri feroci..."
  },
  AvgDialog_35987_Content_11 = {
    Text = "È tutta solo immaginazione sua.\nMa ho visto qualcosa di speciale, come \"te\"."
  },
  AvgDialog_35987_Content_12 = {Text = "Me...?"},
  AvgDialog_35987_Content_13 = {
    Text = "Ridacchi sommessamente e le fai l'occhiolino."
  },
  AvgDialog_35987_Content_14 = {
    Text = "Questo è un segreto tra \"lei\" e me. Te ne parlerò più avanti."
  },
  AvgDialog_35987_Content_15 = {Text = "Sorel—!!"},
  AvgDialog_35987_Content_16 = {
    Text = "Jenkin salta fuori all'improvviso dai fiori lì vicino."
  },
  AvgDialog_35987_Content_17 = {
    Text = "Sono tornato dal mio girovagare con Aigis. Indovina cosa abbiamo trovato?"
  },
  AvgDialog_35987_Content_18 = {
    Text = "Jenkin agitò un nastro rosso nella mano.\nA differenza di quelli che Mason usava di solito, questo aveva un campanellino ingiallito attaccato all'estremità."
  },
  AvgDialog_35987_Content_19 = {
    Text = "Una brezza leggera passa, e il campanellino tintinna limpido, come uno spiritello gioioso."
  },
  AvgDialog_35987_Content_2 = {
    Text = "Università di Mythag, Campus \n Tre giorni dopo"
  },
  AvgDialog_35987_Content_20 = {
    Text = "Questo è qualcosa che ho visto nel Dominio..."
  },
  AvgDialog_35987_Content_21 = {
    Text = "Eh, l'hai vista anche tu nel Dominio? Allora devi aver incontrato la sorella che si è trasformata in gatto!"
  },
  AvgDialog_35987_Content_22 = {
    Text = "Non... non dirlo..."
  },
  AvgDialog_35987_Content_23 = {
    Text = "Come puoi dire così? Questo nastro è un ricordo estremamente, assolutamente e incredibilmente importante!"
  },
  AvgDialog_35987_Content_24 = {
    Text = "In quel periodo, mi prendevo cura di te e giocavo con te ogni giorno. È stato così divertente!"
  },
  AvgDialog_35987_Content_25 = {
    Text = "Jenkin posò delicatamente il nastro nella mano di Mason."
  },
  AvgDialog_35987_Content_26 = {
    Text = "Ricordo che qualcuno una volta disse di voler essere un gatto nella prossima vita."
  },
  AvgDialog_35987_Content_27 = {
    Text = "Se solo potessimo restare spensierati così, potrei continuare a prendermi cura di te!"
  },
  AvgDialog_35987_Content_28 = {
    Text = "Tutti gli snack di pesce e l'erba gatta, lascia fare a me!"
  },
  AvgDialog_35987_Content_29 = {
    Text = "Mason sorrise, le dita che sfioravano il nastro fresco e morbido."
  },
  AvgDialog_35987_Content_3 = {
    Text = "Capisco. Poco dopo aver ucciso Albino, sei stato portato via dall'Associazione degli Scultori."
  },
  AvgDialog_35987_Content_30 = {
    Text = "Essere un gatto? Quello è qualcosa per la prossima vita."
  },
  AvgDialog_35987_Content_31 = {
    Text = "In questo momento, voglio solo vivere bene come \"Mason\", insieme a tutti."
  },
  AvgDialog_35987_Content_32 = {
    Text = "Hmm... Sembra che questo Dominio abbia cambiato molto Sorella. Non era così prima."
  },
  AvgDialog_35987_Content_33 = {
    Text = "Testimonio che la Signorina Mason sta dicendo la verità."
  },
  AvgDialog_35987_Content_34 = {
    Text = "Tu e Mason vi scambiate un sorriso, i pensieri tornano al momento appena prima del collasso del Dominio..."
  },
  AvgDialog_35987_Content_35 = {
    Text = "Capito... d'accordo."
  },
  AvgDialog_35987_Content_36 = {
    Text = "Tu sei l'origine di ogni cosa, e anche la fine di ogni cosa..."
  },
  AvgDialog_35987_Content_37 = {
    Text = "Mentre l'ultimo barlume di luce stellare svanisce, il mondo sembra essere inghiottito dall'inchiostro nero."
  },
  AvgDialog_35987_Content_38 = {
    Text = "Senti delle campane in lontananza, come ruggiti del caos dalle profondità del mantello terrestre."
  },
  AvgDialog_35987_Content_39 = {
    Text = "Il Dominio... sta collassando?!"
  },
  AvgDialog_35987_Content_4 = {
    Text = "Questa è la storia di ciò che accadde in seguito."
  },
  AvgDialog_35987_Content_40 = {
    Text = "Afferrate la mia mano, {Male=Signor,Female=Signorina} %player%!"
  },
  AvgDialog_35987_Content_41 = {
    Text = "Stringi forte la mano di Mason."
  },
  AvgDialog_35987_Content_42 = {
    Text = "In quel momento, il tuo sangue sembra fluire nel suo corpo senza sforzo, e le vostre coscienze si fondono in una sola."
  },
  AvgDialog_35987_Content_43 = {
    Text = "Senti di scivolare lentamente nel sonno, innumerevoli sogni che si susseguono uno dopo l'altro, trascinandoti nelle profondità dell'oscurità."
  },
  AvgDialog_35987_Content_44 = {
    Text = "Quando riapri gli occhi, ti ritrovi in piedi da solo in una caverna. Sotto i tuoi piedi scorre un fiume dorato e scintillante, simile alle vene della terra."
  },
  AvgDialog_35987_Content_45 = {
    Text = "È questa la luce stellare che ho visto prima... Si è tutta raccolta qui?"
  },
  AvgDialog_35987_Content_46 = {
    Text = "<Red:Ritorna, ritorna...>"
  },
  AvgDialog_35987_Content_47 = {
    Text = "Segui il flusso di luce stellare più in profondità nella caverna."
  },
  AvgDialog_35987_Content_48 = {
    Text = "Questo è...?!"
  },
  AvgDialog_35987_Content_49 = {
    Text = "Questo luogo sembra essere la fonte ultima di tutte le cose contorte, deformi e immonde."
  },
  AvgDialog_35987_Content_5 = {
    Text = "Hmm. Ora ricordo tutto. Non era un ricordo piacevole..."
  },
  AvgDialog_35987_Content_50 = {
    Text = "La massa grigio chiaro tremava e si espandeva, generando per fissione mostri deformi e contorcenti, come uno stomaco in costante agitazione."
  },
  AvgDialog_35987_Content_51 = {
    Text = "Tuttavia, prima di raggiungere la riva, ricadevano nella pozza e venivano divorati dalle bocche spalancate sulla massa."
  },
  AvgDialog_35987_Content_52 = {
    Text = "Le sagome di questi mostri sembrano in qualche modo familiari... Potrebbe essere che..."
  },
  AvgDialog_35987_Content_53 = {
    Text = "All'improvviso hai una forte intuizione. Guadi attraverso la melma grigia e ti avvicini all'ammasso."
  },
  AvgDialog_35987_Content_54 = {
    Text = "Mason... sei tu?"
  },
  AvgDialog_35987_Content_55 = {
    Text = "La massa si fermò per un istante, poi ricominciò a contorcersi dolcemente."
  },
  AvgDialog_35987_Content_56 = {
    Text = "Emette un suono frusciante, come un saluto amichevole."
  },
  AvgDialog_35987_Content_57 = {
    Text = "Osservi i mostri inginocchiati accanto alla pozza. Si sforzano di muoversi, contorcendosi nella melma, bramando di tornare nell'abbraccio della massa."
  },
  AvgDialog_35987_Content_58 = {
    Text = "Come quei pellegrini che cercano miracoli nel vento e nella neve"
  },
  AvgDialog_35987_Content_59 = {
    Text = "<Red:La radice di ogni impurità, lordura e sventura...>"
  },
  AvgDialog_35987_Content_6 = {
    Text = "Stringi delicatamente la mano di Mason."
  },
  AvgDialog_35987_Content_60 = {
    Text = "<Red:Ritornate...>"
  },
  AvgDialog_35987_Content_62 = {
    Text = "Perché è il luogo dove tutti i fiumi finiscono, non importa quanto distanti possano essere, alla fine convergeranno qui."
  },
  AvgDialog_35987_Content_63 = {
    Text = "Capisco... Quindi sei la destinazione a cui anelano tornare. È questo che fai ogni giorno?"
  },
  AvgDialog_35987_Content_64 = {
    Text = "Con un corpo fragile, riunendo quelle personalità disperse e sforzandosi di mantenere l'apparenza che le \"persone normali\" dovrebbero avere."
  },
  AvgDialog_35987_Content_65 = {
    Text = "Come una madre stanca che attende il ritorno del figlio errante, ha persino dimenticato la propria identità di madre dopo aver sopportato lunghi periodi di divisione e fusione."
  },
  AvgDialog_35987_Content_66 = {
    Text = "...Non c'è da stupirsi che abbia sognato quegli eventi passati."
  },
  AvgDialog_35987_Content_67 = {
    Text = "L'ultima volta che ho visto queste stelle, ho improvvisamente sentito di essere molto simile a loro."
  },
  AvgDialog_35987_Content_68 = {
    Text = "...ci sono anche delle differenze. Loro sanno dov'è la loro casa, ma io ho persino perso i miei ricordi"
  },
  AvgDialog_35987_Content_69 = {
    Text = "Il tuo naso improvvisamente pizzica un po'. Tocchi delicatamente la carne, sentendo il suo tranquillo pulsare."
  },
  AvgDialog_35987_Content_7 = {
    Text = "È tutto passato, signorina Mason. Le assicuro che non accadrà mai più."
  },
  AvgDialog_35987_Content_70 = {
    Text = "Mason... Anch'io troverò la mia casa un giorno? Proprio come stai facendo tu adesso..."
  },
  AvgDialog_35987_Content_71 = {
    Text = "La carne si contorce, dividendosi all'estremità per formare un morbido tentacolo viscido che ti asciuga delicatamente le lacrime dall'angolo dell'occhio."
  },
  AvgDialog_35987_Content_72 = {
    Text = "<Change>Sicuramente sì...</Change>"
  },
  AvgDialog_35987_Content_73 = {
    Text = "<Change>Non versare lacrime..."
  },
  AvgDialog_35987_Content_74 = {Text = "Rombo..."},
  AvgDialog_35987_Content_75 = {
    Text = "Un lieve tremore si alza dalle profondità, spaccando le pareti rocciose con delle crepe."
  },
  AvgDialog_35987_Content_76 = {
    Text = "Tempo al collasso del Dominio: <Red:0> minuti"
  },
  AvgDialog_35987_Content_77 = {
    Text = "Ti volti e lasci la caverna."
  },
  AvgDialog_35987_Content_78 = {
    Text = "Raggiunta l'entrata della caverna, non puoi fare a meno di voltarti a guardarla un'ultima volta."
  },
  AvgDialog_35987_Content_79 = {
    Text = "Addio, signorina Mason."
  },
  AvgDialog_35987_Content_8 = {
    Text = "Grazie... {Male=Signor,Female=Signorina} %player%."
  },
  AvgDialog_35987_Content_80 = {
    Text = "Gioia, dolore, sofferenza... Personalità ed emozioni diverse vanno e vengono, ma lei rimane in quella caverna."
  },
  AvgDialog_35987_Content_81 = {
    Text = "—È viva."
  },
  AvgDialog_35987_Content_9 = {
    Text = "\nDovrei essere io a ringraziarti.\nQuando il Dominio è crollato, mi hai dato molto incoraggiamento e conforto."
  },
  AvgDialog_35988_Content_1 = {
    Text = "Serpente insonne"
  },
  AvgDialog_35988_Content_10 = {
    Text = "Tremava, alzando le mani al cielo, fissando la volta nera come la pece, mormorando parole indistinte."
  },
  AvgDialog_35988_Content_11 = {
    Text = "La radice di ogni impurità, lordura e sventura..."
  },
  AvgDialog_35988_Content_12 = {
    Text = "Tornate... <Big:Tornate!>"
  },
  AvgDialog_35988_Content_13 = {
    Text = "Ugh... Mi fa male la testa..."
  },
  AvgDialog_35988_Content_14 = {
    Text = "I mormorii si propagano verso l'esterno come onde. Mason si stringe la testa dal dolore e si inginocchia dietro \"24\"."
  },
  AvgDialog_35988_Content_15 = {
    Text = "Smetti di parlare... <Big:Smetti di parlare>!"
  },
  AvgDialog_35988_Content_16 = {
    Text = "Si lanciò in avanti e abbracciò da dietro \"24\", coperta di sangue."
  },
  AvgDialog_35988_Content_17 = {
    Text = "Ti prego, smetti di parlare..."
  },
  AvgDialog_35988_Content_18 = {
    Text = "Mason lottò per afferrare le mani alzate di \"24\", il loro sangue e le loro lacrime si mescolavano insieme. Eppure, fu tutto inutile."
  },
  AvgDialog_35988_Content_19 = {
    Text = "<Red:Ritorna, ritorna...>"
  },
  AvgDialog_35988_Content_2 = {
    Text = "La donna scalza striscia in avanti."
  },
  AvgDialog_35988_Content_20 = {
    Text = "<Red:Condividete questo banchetto lurido e immondo!!>"
  },
  AvgDialog_35988_Content_21 = {
    Text = "Signorina 24, non—!!"
  },
  AvgDialog_35988_Content_22 = {
    Text = "Braccia contorte e deformi spuntano dal corpo di \"24\". Immerse nel sangue e nella luce lunare, poi—"
  },
  AvgDialog_35988_Content_23 = {
    Text = "Delicatamente ma con fermezza torsero il collo di \"24\"."
  },
  AvgDialog_35988_Content_24 = {Text = "..."},
  AvgDialog_35988_Content_25 = {
    Text = "Non ci fu lo spargimento di sangue previsto. Il corpo di \"24\" si trasformò in minuscole luci stellari dorate, come lucciole danzanti nella notte oscura."
  },
  AvgDialog_35988_Content_26 = {
    Text = "Eh... Cos'è questo..."
  },
  AvgDialog_35988_Content_27 = {
    Text = "La luce stellare circonda dolcemente Mason, alcune entrano nel suo corpo, altre danzano sulle punte delle sue dita, per poi disperdersi lievemente."
  },
  AvgDialog_35988_Content_28 = {
    Text = "...Ho già visto queste luci stellari."
  },
  AvgDialog_35988_Content_29 = {
    Text = "Nei sogni, nella realtà... sono venute a portare via \"noi\"."
  },
  AvgDialog_35988_Content_3 = {
    Text = "I suoi lunghi capelli strascicano sul terreno, aggrovigliati con erba secca, neve e sangue rappreso, ormai privi del loro antico splendore."
  },
  AvgDialog_35988_Content_30 = {
    Text = "Allunghi la mano per toccare la luce stellare. Una sensazione calda fluisce attraverso le punte delle dita, come se esistesse una connessione nascosta tra te e le stelle."
  },
  AvgDialog_35988_Content_31 = {
    Text = "<Gray:Strano, all'improvviso mi sento un po' triste...>"
  },
  AvgDialog_35988_Content_32 = {Text = "Zing—!!"},
  AvgDialog_35988_Content_33 = {
    Text = "Dopo che l'ultima luce stellare scomparve, avvertisti un tremito familiare e furioso provenire dalle profondità del sottosuolo."
  },
  AvgDialog_35988_Content_34 = {
    Text = "Dannazione, il Dominio sta collassando di nuovo?"
  },
  AvgDialog_35988_Content_35 = {
    Text = "Afferri la mia mano, Signorina Mason!"
  },
  AvgDialog_35988_Content_36 = {
    Text = "<Yellow:Registro Operazione Dominio Artificiale II>\n\n■ ID Dominio: M-C06\n■ Data Collasso: Anno 315, 17 Dicembre\n■ Sito Collasso: Southwark St @2"
  },
  AvgDialog_35988_Content_37 = {
    Text = "<Yellow:■Risultati dell'Operazione>\n\nCaccia alle altre ombre di \"24\" / Tendenze suicide poco chiare / Religione @2?\nQual è il collegamento tra di loro?\n\n...Servono più indizi."
  },
  AvgDialog_35988_Content_38 = {
    Text = "Nel frattempo, fuori dal Dominio Artificiale..."
  },
  AvgDialog_35988_Content_39 = {
    Text = "All'ingresso del Dominio, ricercatori in camice bianco vanno e vengono indaffarati."
  },
  AvgDialog_35988_Content_4 = {
    Text = "Vicino a lei, sepolti nella neve e appesi agli alberi, giacevano i cadaveri essiccati di \"24\"."
  },
  AvgDialog_35988_Content_40 = {
    Text = "È passato un giorno e %player% non si è ancora svegliato/a. Vuole richiedere un'interruzione forzata del Dominio?"
  },
  AvgDialog_35988_Content_41 = {
    Text = "I segni vitali di %hisorher% sono stabili, apparentemente non influenzati da cambiamenti drastici."
  },
  AvgDialog_35988_Content_42 = {
    Text = "Osservate ancora per un periodo più lungo."
  },
  AvgDialog_35988_Content_43 = {
    Text = "E la Signorina 24 se ritardiamo ancora? Il Comitato vuole da tempo usare questo caso come opportunità per intervenire nella gestione dei Risvegliatori..."
  },
  AvgDialog_35988_Content_44 = {
    Text = "Winkle si strinse disperatamente la testa."
  },
  AvgDialog_35988_Content_45 = {
    Text = "<Shake:È tutta colpa mia per aver voluto studiare troppo in fretta il suo Dominio. Ora il nostro Custode è diventato la Bella Addormentata. Che facciamo...>"
  },
  AvgDialog_35988_Content_46 = {
    Text = "Non preoccuparti, abbiamo già un piano per questo. William è in viaggio per condurre un'operazione nel Distretto Est."
  },
  AvgDialog_35988_Content_47 = {
    Text = "Quanto a %player%... concedia{Male=mogli,Female=mole} ancora un po' di tempo."
  },
  AvgDialog_35988_Content_48 = {
    Text = [[
Clinica Bernard
Londinium Est]]
  },
  AvgDialog_35988_Content_49 = {
    Text = "Ai sensi del Capitolo 3, Articolo 2, Comma 13 del Trattato di Mystia, i Risvegliatori che violano le leggi secolari devono essere prima sottoposti a indagine da parte del Comitato."
  },
  AvgDialog_35988_Content_5 = {
    Text = "Nessuno ha mai spiegato cosa fossero venuti a cercare a tali altezze."
  },
  AvgDialog_35988_Content_50 = {
    Text = "Capitolo 3, Articolo 3, Sezione 2: Se il comportamento del sospettato suggerisce evasione o fuga, il Comitato di Revisione ha l'autorità di procedere alla detenzione immediata."
  },
  AvgDialog_35988_Content_51 = {
    Text = "Capitolo 4, Articolo 1: Qualsiasi organizzazione o individuo che dia rifugio ai Risvegliatori..."
  },
  AvgDialog_35988_Content_52 = {Text = "..."},
  AvgDialog_35988_Content_53 = {
    Text = "Signor William, mi sta ascoltando?"
  },
  AvgDialog_35988_Content_54 = {
    Text = "<Small:... sto ascoltando.>"
  },
  AvgDialog_35988_Content_55 = {Text = "..."},
  AvgDialog_35988_Content_56 = {
    Text = "Non sprechi le sue energie. I corpi e le prove sono stati rimossi da tempo. Non troverà nulla qui."
  },
  AvgDialog_35988_Content_57 = {
    Text = "Davvero? Posso chiedere cos'è questo?"
  },
  AvgDialog_35988_Content_58 = {
    Text = "William raccolse con cura un grumo di materiale essiccato e traslucido con delle pinzette."
  },
  AvgDialog_35988_Content_59 = {
    Text = "Sembra una specie di muta di serpente. Ma cosa c'entra con questo caso?"
  },
  AvgDialog_35988_Content_6 = {
    Text = "Sa solo che @2 la sta aspettando, nel luogo dove il ghiaccio e la luce svaniscono."
  },
  AvgDialog_35988_Content_60 = {
    Text = "Siamo già a dicembre. Come potrebbe esserci un serpente che fa la muta?"
  },
  AvgDialog_35988_Content_61 = {
    Text = "RRRRIIIPP—!"
  },
  AvgDialog_35988_Content_62 = {
    Text = "Un improvviso fragore di attrezzature provenì dalla stanza interna della clinica."
  },
  AvgDialog_35988_Content_63 = {
    Text = "Che rumore è?! Questo posto è stato sigillato da tempo..."
  },
  AvgDialog_35988_Content_64 = {
    Text = "Vieni fuori."
  },
  AvgDialog_35988_Content_65 = {
    Text = "Il suono di passi calmi si avvicinò, e un uomo insolitamente pallido uscì dalla stanza interna."
  },
  AvgDialog_35988_Content_66 = {
    Text = "Buonasera, agente."
  },
  AvgDialog_35988_Content_67 = {
    Text = "Sono un collega del Dott. Bernard, inviato dai superiori per recuperare i suoi materiali di ricerca..."
  },
  AvgDialog_35988_Content_68 = {
    Text = "L'uomo aveva gli occhi socchiusi, apparentemente un po' assonnato. Porse un biglietto da visita con un sorriso."
  },
  AvgDialog_35988_Content_69 = {
    Text = "Medico Iscritto alla Reale Associazione Medica, Pierce @2..."
  },
  AvgDialog_35988_Content_7 = {
    Text = "<Red:Impuro. Contaminato. Infausto.>"
  },
  AvgDialog_35988_Content_70 = {
    Text = "Mi dispiace, abbiamo già indagato sulla cerchia sociale del Dott. Bernard. Se ricordo bene, questo Pierce è un uomo sulla cinquantina."
  },
  AvgDialog_35988_Content_71 = {
    Text = "Allora, chi sei esattamente?"
  },
  AvgDialog_35988_Content_72 = {
    Text = "Hehe... Davvero impressionante, Comitato. La vostra memoria fotografica è davvero ammirevole."
  },
  AvgDialog_35988_Content_73 = {
    Text = "Spalancò improvvisamente gli occhi, le pupille verticali giallo cobalto brillavano fredde nell'oscurità."
  },
  AvgDialog_35988_Content_74 = {
    Text = "Va bene, giocherò un po' con voi."
  },
  AvgDialog_35988_Content_75 = {Text = "Hss..."},
  AvgDialog_35988_Content_76 = {
    Text = "Una sensazione gelida e viscida mi sfiora il viso."
  },
  AvgDialog_35988_Content_77 = {
    Text = "Il soffitto è ora ricoperto di piccoli serpenti pallidi, che si contorcono silenziosamente e cadono come gocce di pioggia."
  },
  AvgDialog_35988_Content_78 = {
    Text = "Serpenti... Sono ovunque!"
  },
  AvgDialog_35988_Content_79 = {
    Text = "Soffitto, pavimento, pareti... I serpenti strisciavano ovunque, come innumerevoli alghe pallide alla deriva in un silenzioso fiume nero."
  },
  AvgDialog_35988_Content_8 = {
    Text = "La radice di ogni impurità, lordura e sventura..."
  },
  AvgDialog_35988_Content_80 = {
    Text = "Chiamata alle squadre A-2 e B-1, pericolo rilevato all'interno. In posizione, ora."
  },
  AvgDialog_35988_Content_81 = {
    Text = "William estrasse rapidamente la Chiave d'argento, ma l'uomo davanti a lui era già svanito senza lasciare traccia."
  },
  AvgDialog_35988_Content_82 = {
    Text = "So che sei ancora qui. Vieni fuori."
  },
  AvgDialog_35988_Content_83 = {
    Text = "L'aria densa intorno tremò leggermente per un istante, poi si distese piacevolmente."
  },
  AvgDialog_35988_Content_84 = {
    Text = "Un debole \"ssss\" sussurra vicino al tuo orecchio, come una brezza fredda che ti sfiora delicatamente la guancia."
  },
  AvgDialog_35988_Content_85 = {
    Text = "Solo un piccolo segno della mia gratitudine. Prendetevi cura di loro, Investigatore."
  },
  AvgDialog_35988_Content_86 = {
    Text = "Buonanotte."
  },
  AvgDialog_35988_Content_9 = {
    Text = "\"24\" si inginocchiò improvvisamente a terra."
  },
  AvgDialog_35989_Content_1 = {
    Text = "In Attesa della Commedia"
  },
  AvgDialog_35989_Content_10 = {
    Text = "L'ho visto anch'io! Voi due mano nella mano, i capelli al vento, belli come bambole!"
  },
  AvgDialog_35989_Content_11 = {
    Text = "Shh! Fate silenzio e non disturbate chi guarda lo spettacolo!"
  },
  AvgDialog_35989_Content_12 = {
    Text = "Su un palco improvvisato, un pagliaccio con il trucco pesante si esibisce per il pubblico."
  },
  AvgDialog_35989_Content_13 = {
    Text = "Tanto tempo fa, tra le montagne innevate dell'Infinito Nord, alla fine di un antico fiume, un mostro grigio sonnecchia~~~"
  },
  AvgDialog_35989_Content_14 = {
    Text = "Salve a tutti, io sono quel mostro. <BigShake:Roar—>"
  },
  AvgDialog_35989_Content_15 = {
    Text = "<Shake:Waaah—> Eh, ma quello non è Jenkin?"
  },
  AvgDialog_35989_Content_16 = {
    Text = "Nessuno conosce l'origine o il nome del mostro, se non il suo appetito vorace—ogni inverno, gli abitanti ai piedi della montagna innevata riempiono cesti con cibo delizioso e vino pregiato..."
  },
  AvgDialog_35989_Content_17 = {
    Text = "Accendete una candela d'argento e posate il cesto nel fiume più vicino a casa vostra, così il mostro potrà ricevere le offerte."
  },
  AvgDialog_35989_Content_18 = {
    Text = [[
H-Ho una domanda!
I mostri non dovrebbero vivere sulla montagna innevata? Come possono ricevere le offerte dal fiume?]]
  },
  AvgDialog_35989_Content_19 = {
    Text = "Perché la fine di tutti i fiumi si trova ai piedi della montagna innevata, non importa quanto siano distanti, alla fine confluiranno tutti qui."
  },
  AvgDialog_35989_Content_2 = {
    Text = "Dominio Artificiale: Ospizio Lily, Distretto Est"
  },
  AvgDialog_35989_Content_20 = {
    Text = "Oh... e poi cosa succede?"
  },
  AvgDialog_35989_Content_21 = {
    Text = "Gnam gnam gnam, ho ricevuto le offerte di tutti! Sono molto contento e ho deciso di ricompensarvi!"
  },
  AvgDialog_35989_Content_22 = {
    Text = "Dopo aver finito di parlare, Jenkin abbassò la testa e i suoi capelli iniziarono a tremare violentemente come un motore."
  },
  AvgDialog_35989_Content_23 = {
    Text = "Smettila di scuoterti, stanno cadendo tutte le pulci... Eh, sta nevicando?"
  },
  AvgDialog_35989_Content_24 = {
    Text = "Wow, sta nevicando davvero!"
  },
  AvgDialog_35989_Content_25 = {
    Text = "Fiocchi di neve di carta argentata svolazzano verso il basso. Aigis si nasconde dietro di te, spargendo silenziosamente i piccoli pezzetti di carta."
  },
  AvgDialog_35989_Content_26 = {
    Text = "<Small:Shh... Signore, per favore faccia finta di non aver visto Aigis...>"
  },
  AvgDialog_35989_Content_27 = {
    Text = "In poco tempo, candele di vari colori si accesero silenziosamente, avvolgendo dolcemente i volti dei bambini in un caldo bagliore arancione."
  },
  AvgDialog_35989_Content_28 = {
    Text = "Ogni anno, quando cade la prima neve, candele d'argento e cesti colmi di doni scendono lungo il fiume."
  },
  AvgDialog_35989_Content_29 = {Text = "Squiiik—"},
  AvgDialog_35989_Content_3 = {
    Text = "<Shake:Cough, cough, la mia schiena...>"
  },
  AvgDialog_35989_Content_30 = {
    Text = "Ecco il cesto pieno di regali!"
  },
  AvgDialog_35989_Content_31 = {
    Text = "Sarah uscì con un sorriso, spingendo il piccolo carrello del cibo."
  },
  AvgDialog_35989_Content_32 = {
    Text = "Wow!! Budino di prugne, insalata di salmone e... maialino arrosto!!"
  },
  AvgDialog_35989_Content_33 = {
    Text = "Un momento. Cosa si dice prima di mangiare?"
  },
  AvgDialog_35989_Content_34 = {
    Text = "I bambini si scambiarono uno sguardo e risposero all'unisono—"
  },
  AvgDialog_35989_Content_35 = {
    Text = "<BigShake:Buona Festa della Brina d'Argento—!!>"
  },
  AvgDialog_35989_Content_36 = {
    Text = "Non avevo idea che ci fosse una leggenda simile dietro la Festa della Brina d'Argento. È la prima volta che ne sento parlare."
  },
  AvgDialog_35989_Content_37 = {
    Text = "<Gray:Il Dominio della Signorina Mason è come un sogno. Posso muovermi liberamente tra le scene senza che nessuno metta in dubbio la mia presenza.>"
  },
  AvgDialog_35989_Content_38 = {
    Text = "<Gray:Tutte le scene e i personaggi possono essere combinati liberamente. Uno spettacolo simile probabilmente non è mai apparso nella realtà...>"
  },
  AvgDialog_35989_Content_39 = {
    Text = "<Gray:Forse questo è il desiderio più profondo della Signorina Mason?>"
  },
  AvgDialog_35989_Content_4 = {
    Text = "Mi dispiace davvero, {Male=Sig.,Female=Sig.na} %player%! Sembra che di recente sia ingrassata un po'..."
  },
  AvgDialog_35989_Content_40 = {
    Text = "Signorina Mason, non vuole unirsi a loro?"
  },
  AvgDialog_35989_Content_41 = {
    Text = "Hai indicato un punto poco distante. I bambini erano ancora radunati attorno al pagliaccio, ad ascoltare le sue storie elaborate e fantastiche."
  },
  AvgDialog_35989_Content_42 = {
    Text = "Sono una persona noiosa; le mie battute fanno solo venire sonno."
  },
  AvgDialog_35989_Content_43 = {Text = "Waaah..."},
  AvgDialog_35989_Content_44 = {
    Text = "Sorella Mason, Jenkin... mi ha fatto i dispetti...!"
  },
  AvgDialog_35989_Content_45 = {
    Text = "Hmph, non sai vincere e allora vai a fare la spia? Che vergogna! Chi ti ha detto di dire che avevo le pulci poco fa!"
  },
  AvgDialog_35989_Content_46 = {
    Text = "Shh— Mike è un piccolo cavaliere coraggioso, e i piccoli cavalieri non devono piangere."
  },
  AvgDialog_35989_Content_47 = {
    Text = "Mason asciugò delicatamente le lacrime e il moccio del piccolo Mike, consolando dolcemente il bambino singhiozzante."
  },
  AvgDialog_35989_Content_48 = {
    Text = "Sorella Mason, l'Orsetto Bobby ha perso gli occhi..."
  },
  AvgDialog_35989_Content_49 = {
    Text = "Aigis si avvicinò, stringendo la bambola."
  },
  AvgDialog_35989_Content_5 = {
    Text = "<Shake:Solo qualcuno? Signorina Mason, potrebbe per favore scendere da me prima...>"
  },
  AvgDialog_35989_Content_50 = {
    Text = "Fammi vedere... Oh no, sembra che si siano davvero persi. Che ne dici se te ne cucio di nuovi stasera, sorellina?"
  },
  AvgDialog_35989_Content_51 = {Text = "Mmh~!"},
  AvgDialog_35989_Content_52 = {Text = "..."},
  AvgDialog_35989_Content_53 = {
    Text = "Hmph, sempre a creare problemi a mia sorella!"
  },
  AvgDialog_35989_Content_54 = {
    Text = "Ma anche la Signorina Mason era molto felice, cosa che raramente le si vede."
  },
  AvgDialog_35989_Content_55 = {
    Text = "Sarah si siede accanto a te, con il mento appoggiato sulle mani, sorridendo mentre osserva Mason circondata dai bambini."
  },
  AvgDialog_35989_Content_56 = {
    Text = "Essere necessari è anch'essa una forma di felicità."
  },
  AvgDialog_35989_Content_57 = {Text = "..."},
  AvgDialog_35989_Content_58 = {
    Text = "A poco a poco, sempre più bambini si radunarono attorno a Mason, lasciando il pagliaccio trascurato."
  },
  AvgDialog_35989_Content_59 = {
    Text = "C'è qualcuno che vuole ancora ascoltare una storia? Tanto, tanto tempo fa..."
  },
  AvgDialog_35989_Content_6 = {
    Text = "Eh, sono entrato in un nuovo Dominio?"
  },
  AvgDialog_35989_Content_60 = {
    Text = "Tanto tempo fa..."
  },
  AvgDialog_35989_Content_61 = {
    Text = "È notte fonda, e i bambini sono tutti tornati nelle loro stanze. L'orfanotrofio è sprofondato nuovamente nella sua consueta tranquillità."
  },
  AvgDialog_35989_Content_62 = {
    Text = "Lo spettacolo finisce, la folla si disperde—\nEhi!"
  },
  AvgDialog_35989_Content_63 = {
    Text = "Lasciando solo il pagliaccio solitario a ripulire il disordine, accompagnato dal suo riflesso solitario."
  },
  AvgDialog_35989_Content_64 = {
    Text = "Il pagliaccio mormorò scuotendo la testa e lanciò un'occhiata all'ombra nell'angolo."
  },
  AvgDialog_35989_Content_65 = {
    Text = "È davvero triste, non trovi?"
  },
  AvgDialog_35989_Content_66 = {Text = "..."},
  AvgDialog_35989_Content_67 = {
    Text = "Ah, ho sentito parlare di te da tempo: il famigerato \"Killer 24\", che va e viene senza lasciare traccia, e si diletta nella caccia alla personalità."
  },
  AvgDialog_35989_Content_68 = {
    Text = "La personalità che hai preso di mira non durerà più di tre giorni—<BigShake:Whoa!>"
  },
  AvgDialog_35989_Content_69 = {
    Text = "Terrificante! Ma perché il pagliaccio davanti a te non ha paura e non si scansa?"
  },
  AvgDialog_35989_Content_7 = {
    Text = "Siete degli angeli?"
  },
  AvgDialog_35989_Content_70 = {
    Text = "Hmph, tutto misterioso."
  },
  AvgDialog_35989_Content_71 = {
    Text = "Il giullare scoppiò a ridere, un lampo brillò nel suo occhio."
  },
  AvgDialog_35989_Content_72 = {
    Text = "Perché l'assassino non lo sa: quelle personalità inferiori e instabili non riescono a sopravvivere nemmeno un solo giorno."
  },
  AvgDialog_35989_Content_73 = {
    Text = "Nascono da innumerevoli momenti casuali e dovrebbero svanire per sempre dopo aver compiuto la missione a loro destinata."
  },
  AvgDialog_35989_Content_74 = {
    Text = "Qual è la missione del \"Pagliaccio 24\"? Ovviamente, portare gioia a Jenkin e a tutti durante la Festa della Brina d'Argento."
  },
  AvgDialog_35989_Content_75 = {
    Text = "Il pagliaccio sfoggia un ampio sorriso, il trucco del viso si trasforma in granelli di polvere di stelle dorata."
  },
  AvgDialog_35989_Content_76 = {
    Text = "Ho già superato di gran lunga la mia missione, è ora di tornare~"
  },
  AvgDialog_35989_Content_77 = {
    Text = "Tornare dove?"
  },
  AvgDialog_35989_Content_78 = {
    Text = "Ovviamente, torniamo là dove tutto è <Yellow:iniziato>."
  },
  AvgDialog_35989_Content_79 = {
    Text = "Lascia che ti sveli un segreto: ogni personalità è come un'erbaccia alla deriva, e il nostro desiderio comune è tornare a essere un tutt'uno."
  },
  AvgDialog_35989_Content_8 = {
    Text = "La ragazza ti fissò con i suoi grandi occhi, indicando il grosso buco che avevi sfondato nel soffitto."
  },
  AvgDialog_35989_Content_80 = {
    Text = "Ridere insieme, piangere insieme, e sentire l'amore e la fiducia di Jenkin..."
  },
  AvgDialog_35989_Content_81 = {
    Text = "Heh, come osi nominare Jenkin. Sai qual è la mia missione?"
  },
  AvgDialog_35989_Content_82 = {
    Text = "<Red:Uccidere tutti coloro che cercano di ottenere senza sforzo. Non lasciarne vivo nessuno.>"
  },
  AvgDialog_35989_Content_84 = {
    Text = "Nel cielo notturno nero pece, uno stormo di corvi si levò improvvisamente in volo, sbattendo le ali e allontanandosi dalle cime degli alberi."
  },
  AvgDialog_35989_Content_85 = {
    Text = "È una tranquilla notte d'inverno."
  },
  AvgDialog_35989_Content_9 = {
    Text = "Aigis ha visto tutto. Siete volati giù dal cielo."
  },
  AvgDialog_35990_Content_1 = {
    Text = "Fuga dorata"
  },
  AvgDialog_35990_Content_10 = {
    Text = "Siete stati separati per troppo tempo."
  },
  AvgDialog_35990_Content_11 = {Text = "..."},
  AvgDialog_35990_Content_12 = {
    Text = "Sembra che sia la prima volta che sogno il passato."
  },
  AvgDialog_35990_Content_13 = {
    Text = "Ti stringi la testa, sentendo come se un filo invisibile stesse trascinando la tua coscienza lontano dal letto."
  },
  AvgDialog_35990_Content_14 = {
    Text = "Poi hai aperto la finestra e hai visto la prima nevicata dell'Anno Nuovo."
  },
  AvgDialog_35990_Content_15 = {
    Text = "Wow, sta nevicando!!"
  },
  AvgDialog_35990_Content_16 = {
    Text = "Le grida eccitate dei bambini echeggiavano nel cielo notturno silenzioso. Accompagnati da passi caotici, gli orfani si radunarono al piano di sotto."
  },
  AvgDialog_35990_Content_17 = {
    Text = "Quanta neve, luccicante e bellissima."
  },
  AvgDialog_35990_Content_18 = {
    Text = "Aigis vuole costruire un pupazzo di neve, proprio come il piccolo Bobby."
  },
  AvgDialog_35990_Content_19 = {
    Text = "È facile, ci penso io—"
  },
  AvgDialog_35990_Content_2 = {
    Text = "Hai fatto un sogno incredibilmente lungo."
  },
  AvgDialog_35990_Content_20 = {
    Text = "Ta-da! Date un'occhiata al mio capolavoro!"
  },
  AvgDialog_35990_Content_21 = {
    Text = "Hmm... non assomiglia proprio all'Orsetto Bobby. Sembra, sembra..."
  },
  AvgDialog_35990_Content_22 = {
    Text = "Sembra un cane! Un carlino!"
  },
  AvgDialog_35990_Content_23 = {
    Text = "<Big:Hahahaha!>"
  },
  AvgDialog_35990_Content_24 = {
    Text = "Assurdo! Come potrei mai sembrare un cane?!"
  },
  AvgDialog_35990_Content_25 = {Text = "Squeak!"},
  AvgDialog_35990_Content_26 = {
    Text = "I bambini ridono e giocano nei vicoli. Mason, già sveglia, è in piedi accanto a te."
  },
  AvgDialog_35990_Content_27 = {
    Text = "Ha teso la mano e ha raccolto qualche delicato fiocco di neve nel palmo."
  },
  AvgDialog_35990_Content_28 = {
    Text = "Il fiocco di neve giaceva silenzioso nel suo palmo, sciogliendosi rapidamente in acqua fredda, scintillante di luce stellare dorata."
  },
  AvgDialog_35990_Content_29 = {
    Text = "Oh, è la luce che abbiamo visto l'altra volta..."
  },
  AvgDialog_35990_Content_30 = {
    Text = "Innumerevoli luci stellari volano fuori dalle finestre del corridoio accanto, fondendosi in un fiume dorato nel cielo notturno."
  },
  AvgDialog_35990_Content_31 = {
    Text = "Scorrono con grazia, estendendosi fino alle lontane montagne illuminate dalla luna."
  },
  AvgDialog_35990_Content_32 = {
    Text = "È il profumo di quella signora pagliaccio. Ci ha lasciati."
  },
  AvgDialog_35990_Content_33 = {
    Text = "Ma non mi sento triste... Sembra che se ne sia andata di sua volontà, come se stesse tornando a casa."
  },
  AvgDialog_35990_Content_34 = {
    Text = "Tornare a casa..."
  },
  AvgDialog_35990_Content_35 = {
    Text = "L'ho sentito anch'io... il loro desiderio di tornare a casa."
  },
  AvgDialog_35990_Content_36 = {
    Text = "Questi desideri sono così intensi che mi hanno fatto sognare eventi passati."
  },
  AvgDialog_35990_Content_37 = {
    Text = "Non oso più sperare di tornare a casa; mi accontenterei di recuperare qualche ricordo del passato."
  },
  AvgDialog_35990_Content_38 = {
    Text = "Lasci sfuggire un leggero sospiro e ti strofini la testa con un po' di imbarazzo."
  },
  AvgDialog_35990_Content_39 = {
    Text = "Non parliamo di cose deprimenti. Parlami di te, signorina Mason."
  },
  AvgDialog_35990_Content_4 = {
    Text = "Nel sogno, il cielo era come un cimitero squarciato, con sostanze nere che si riversavano come inchiostro."
  },
  AvgDialog_35990_Content_40 = {
    Text = "Ho sentito che hai iniziato a guadagnarti da vivere a Londinium in giovane età. Ti manca ancora casa?"
  },
  AvgDialog_35990_Content_41 = {
    Text = "Mason guardò Jenkins e il piccolo Mike che lottavano al piano di sotto, e sorrise dolcemente."
  },
  AvgDialog_35990_Content_42 = {
    Text = "Ho una memoria terribile. Quando ero piccola, le suore della scuola parrocchiale dicevano che non ero portata per lo studio."
  },
  AvgDialog_35990_Content_43 = {
    Text = "Genitori, città natale... non riesco davvero a ricordare, né voglio farlo.\nI ricordi servono a preservare la gioia."
  },
  AvgDialog_35990_Content_44 = {
    Text = [[
Nelle fiabe che ho letto, solo i luoghi felici e accoglienti possono essere chiamati casa.
Voglio essere una casa per Jenkin e Brown.]]
  },
  AvgDialog_35990_Content_45 = {
    Text = "Capisco.\nSignorina Mason, sei molto più forte di quanto immaginassi."
  },
  AvgDialog_35990_Content_46 = {
    Text = "Non eri così quando ci siamo incontrati per la prima volta al museo delle cere."
  },
  AvgDialog_35990_Content_47 = {
    Text = "<Gray:Sembra che la \"Terapia di Super Stabilizzazione alla Menofina\" della signorina Winkle sia davvero efficace.>"
  },
  AvgDialog_35990_Content_48 = {
    Text = "Tutti stanno facendo del loro meglio per aiutarmi. Come potrei non cambiare affatto?"
  },
  AvgDialog_35990_Content_49 = {
    Text = "Spero di poter essere d'aiuto a tutti."
  },
  AvgDialog_35990_Content_5 = {
    Text = "Giaci a faccia in su sotto la fenditura, il cuore il più vicino possibile alla terra."
  },
  AvgDialog_35990_Content_50 = {
    Text = "Ti stiracchi pigramente, osservando distrattamente la tranquilla zona residenziale sottostante."
  },
  AvgDialog_35990_Content_51 = {
    Text = "Non sai se sia la tua immaginazione, ma ti sembra di vedere un'ombra in piedi alla fine del vicolo buio, che contempla insieme a te il fiume di luce nel cielo."
  },
  AvgDialog_35990_Content_52 = {Text = "..."},
  AvgDialog_35990_Content_53 = {
    Text = "Era la luce delle stelle di quel tempo..."
  },
  AvgDialog_35990_Content_54 = {
    Text = "Ecco un segreto: ogni persona è come un'erba alla deriva, e diventare interi è il nostro desiderio comune."
  },
  AvgDialog_35990_Content_55 = {
    Text = "Ridere insieme, piangere insieme, e sentire l'amore e la fiducia di Jenkin..."
  },
  AvgDialog_35990_Content_56 = {
    Text = "...non sono altro che pietose illusioni."
  },
  AvgDialog_35990_Content_57 = {
    Text = "Il vento soffia dolcemente, e i fiocchi di neve fluttuano nell'aria come soffice cotone, vagando senza meta."
  },
  AvgDialog_35990_Content_58 = {
    Text = "La luce delle stelle svanisce gradualmente, e la tua coscienza sembra allontanarsi con essa."
  },
  AvgDialog_35990_Content_59 = {
    Text = "Chissà come sarà il prossimo Dominio che ti attende?"
  },
  AvgDialog_35990_Content_6 = {Text = "..."},
  AvgDialog_35990_Content_60 = {
    Text = "In realtà, non vedi l'ora."
  },
  AvgDialog_35990_Content_61 = {
    Text = "<Yellow:Registro dell'Operazione nel Dominio Artificiale III>\n\n■ID Dominio: M-C06\n■Ora del Collasso: 24 dicembre, 315 d.F.\n■Luogo del Collasso: Orfanotrofio di Lily"
  },
  AvgDialog_35990_Content_62 = {
    Text = "<Yellow:■Risultati dell'Operazione>\n\nHo visto la neve e la luce dorata delle stelle danzare al suo interno.\nPer qualche ragione, mi ricordano sempre il passato. La nebbia si alza, la luce cala, le risate svaniscono.\nÈ una tranquilla notte d'inverno.\n\n<Yellow:Buon Anno.>\n\nP.S. I cupcake glassati della signorina Sarah sono deliziosi."
  },
  AvgDialog_35990_Content_7 = {
    Text = "Chiudi gli occhi, percependo i tremori provenienti dalle profondità del mantello terrestre. È un ritmo malinconico e antico che ti ricorda la tua casa."
  },
  AvgDialog_35990_Content_8 = {
    Text = [[
Dopo un tempo imprecisato, senti una debole risata e qualcuno ti prende per mano.
Ricambi quel calore a lungo perduto con una leggera stretta.]]
  },
  AvgDialog_35990_Content_9 = {
    Text = "Madre.\nPrima ancora di riuscire a gridare, le lacrime avevano già iniziato a scorrerti sul viso."
  },
  AvgDialog_35992_Content_1 = {
    Text = "Finisce Qui"
  },
  AvgDialog_35992_Content_10 = {
    Text = "<Red:Impuro. Contaminato. Infausto.>"
  },
  AvgDialog_35992_Content_100 = {
    Text = "Luce stellare dorata continua a sgorgare dalla ferita, tremolando fragilmente nell'aria prima di fluire infine nel corpo di Mason."
  },
  AvgDialog_35992_Content_101 = {
    Text = "Solo insieme... siamo la vera Mason Miao..."
  },
  AvgDialog_35992_Content_102 = {
    Text = "La vera Mason..."
  },
  AvgDialog_35992_Content_103 = {
    Text = "Quello è il luogo dove tutti i fiumi finiscono. Non importa la distanza, alla fine convergeranno tutti qui."
  },
  AvgDialog_35992_Content_104 = {
    Text = "Ho sentito... il loro desiderio di tornare a casa."
  },
  AvgDialog_35992_Content_105 = {
    Text = "Ecco un segreto: ogni persona è come un'erba alla deriva, e diventare interi è il nostro desiderio comune."
  },
  AvgDialog_35992_Content_106 = {
    Text = "Mason chiuse dolcemente gli occhi, sentendo la circolazione dorata della luce stellare al suo interno."
  },
  AvgDialog_35992_Content_107 = {
    Text = "Vide il suo volto e le sue viscere, il pagliaccio, lo studioso e innumerevoli volti di sé stessa."
  },
  AvgDialog_35992_Content_108 = {
    Text = "Il suo volto si rifletteva nello specchio infranto, tutti gli occhi rivolti verso di lei, infinita tranquillità, infinita tristezza."
  },
  AvgDialog_35992_Content_109 = {
    Text = "Quelle erano le sue ombre, le sue lacrime e le sue crepe, così come la sua carne e le sue ossa che scorrevano nelle profondità della terra."
  },
  AvgDialog_35992_Content_11 = {
    Text = "Devo andare... Devo attraversare..."
  },
  AvgDialog_35992_Content_110 = {
    Text = "Furono costretti a dilaniare il suo corpo, a nascere, a vagare, e infine tornarono con corpi esausti."
  },
  AvgDialog_35992_Content_111 = {
    Text = "<Red:Finisce qui, finisce con me.>"
  },
  AvgDialog_35992_Content_12 = {
    Text = "Ehi, non scappare. Ti sto ancora spazzolando.\nAhi, perché mordi!?\n\n<Gray:Onestamente, rispetto ai gatti di Mythag, tua sorella è piuttosto docile...>"
  },
  AvgDialog_35992_Content_13 = {
    Text = "Faint risate risuonano da lontano, portando con sé il calore e l'affetto familiari che lei brama, come se fossero proprio accanto a lei."
  },
  AvgDialog_35992_Content_14 = {
    Text = "Jenkin miao?!"
  },
  AvgDialog_35992_Content_15 = {
    Text = "La gattina si drizzò in piedi, sforzandosi di individuare la fonte del suono."
  },
  AvgDialog_35992_Content_16 = {
    Text = "<Red:Ritorna.>"
  },
  AvgDialog_35992_Content_17 = {
    Text = "Hmm—no, non vado là, miao!"
  },
  AvgDialog_35992_Content_18 = {
    Text = "Jenkin, voglio tornare da Jenkin... da tutti..."
  },
  AvgDialog_35992_Content_19 = {
    Text = "Indietro... <Big:Indietro, miao!!>"
  },
  AvgDialog_35992_Content_2 = {
    Text = "La gattina addormentata fece molti sogni."
  },
  AvgDialog_35992_Content_20 = {
    Text = "Va bene, va bene, non ti toccheremo.\nPerché hai fatto un balzo così alto all'improvviso? Hai avuto un incubo?"
  },
  AvgDialog_35992_Content_21 = {
    Text = "\"24\" scrutò vigile i dintorni, con le \"Pupille\" e la punta del naso in costante fremito."
  },
  AvgDialog_35992_Content_22 = {
    Text = "Sniff sniff... Ci sono dei cattivi qui vicino..."
  },
  AvgDialog_35992_Content_23 = {
    Text = "Balzò in alto, avventandosi verso l'angolo. Tuttavia—"
  },
  AvgDialog_35992_Content_25 = {Text = "Mmm..."},
  AvgDialog_35992_Content_26 = {
    Text = "\"24\" giace a terra, gemendo. Sangue rosso scuro trasuda lentamente dalla ferita aperta."
  },
  AvgDialog_35992_Content_27 = {
    Text = "Niente male, sei vigile. Peccato che tu abbia scelto l'avversario sbagliato."
  },
  AvgDialog_35992_Content_28 = {
    Text = "Sei tu?! La signorina Mason è scomparsa da un po', potrebbe essere che—"
  },
  AvgDialog_35992_Content_29 = {
    Text = "L'ombra rise e gettò la malconcia Mason davanti a te."
  },
  AvgDialog_35992_Content_3 = {
    Text = "Le chiazze di luce che fluttuavano lentamente sotto le grondaie nel pomeriggio, la zuppa di riso bianca fumante che emanava fili di vapore, vecchi campanelli e involucri di caramelle colorati..."
  },
  AvgDialog_35992_Content_30 = {
    Text = "{Male=Sig.,Female=Sig.na} %player%... coff coff, mi dispiace..."
  },
  AvgDialog_35992_Content_31 = {
    Text = "L'ombra sollevò il piede e lo premette lentamente nella ferita di Mason."
  },
  AvgDialog_35992_Content_32 = {
    Text = "Hmm... Aaaah!!"
  },
  AvgDialog_35992_Content_33 = {
    Text = "Te l'avevo detto, vi eliminerò uno per uno."
  },
  AvgDialog_35992_Content_34 = {
    Text = "Mentre Mason gemeva di dolore, il vento cessò, la polvere si posò, e persino la luce del sole si cristallizzò in un istante eterno."
  },
  AvgDialog_35992_Content_35 = {
    Text = "Persino Jenkin accanto a te resta immobile e silenzioso come una scultura."
  },
  AvgDialog_35992_Content_36 = {
    Text = "Nel frattempo, lo spazio circostante tremò improvvisamente alcune volte, e il cielo iniziò a sfaldarsi."
  },
  AvgDialog_35992_Content_37 = {
    Text = "Il vasto cielo precipita dall'alto, frantumandosi in pezzi."
  },
  AvgDialog_35992_Content_38 = {
    Text = "Collasso del Dominio...? No, è peggio di così. Cosa sta succedendo?!"
  },
  AvgDialog_35992_Content_39 = {
    Text = "L'ombra ghignò e prese a calci la Mason a malapena respirante sotto di sé."
  },
  AvgDialog_35992_Content_4 = {
    Text = "E la montagna innevata."
  },
  AvgDialog_35992_Content_40 = {
    Text = "Non lo sapevi, vero? Questa è la nostra <Yellow:personalità centrale>. Se muore, qui regnerà il caos."
  },
  AvgDialog_35992_Content_41 = {
    Text = "Quello che stai facendo equivale a un suicidio. Perché?"
  },
  AvgDialog_35992_Content_42 = {
    Text = "Questo è un mondo dove il forte divora il debole. Nessuno ha stabilito che debba essere lei la personalità dominante.\nHo ragione, signorina Mason?"
  },
  AvgDialog_35992_Content_43 = {
    Text = "Non fate del male a %player%{Male=signore,Female=signora}... {Male=lui,Female=lei} è il salvatore di Jenkin..."
  },
  AvgDialog_35992_Content_44 = {
    Text = "Heh... Una codarda debole e incompetente."
  },
  AvgDialog_35992_Content_45 = {
    Text = "Non hai notato le loro menzogne maldestre."
  },
  AvgDialog_35992_Content_46 = {
    Text = "Il bisturi ti incide il corpo, e tu non opponi resistenza."
  },
  AvgDialog_35992_Content_47 = {
    Text = "Costretta ad aiutarli, non opponi resistenza."
  },
  AvgDialog_35992_Content_48 = {
    Text = "Guardi la tua famiglia più cara entrare nell'ospizio dei poveri senza cercare di fermarli."
  },
  AvgDialog_35992_Content_49 = {Text = "..."},
  AvgDialog_35992_Content_5 = {
    Text = "Eh, dove mi trovo?"
  },
  AvgDialog_35992_Content_50 = {
    Text = "Alla fine, non hai nemmeno adempiuto al tuo dovere di \"sorella\"."
  },
  AvgDialog_35992_Content_51 = {Text = "..."},
  AvgDialog_35992_Content_52 = {
    Text = "Hai scaricato tutti i ricordi su di noi come spazzatura. Tu cammini per il campus, sotto il sole, lasciando noi a masticare il dolore nell'oscurità."
  },
  AvgDialog_35992_Content_53 = {
    Text = [[
Tu sei la causa principale della sofferenza di tutti.
Ora, credi davvero di potermi trattenere?]]
  },
  AvgDialog_35992_Content_54 = {
    Text = "<Red:Non sei degna di questo corpo.>"
  },
  AvgDialog_35992_Content_55 = {
    Text = "Non spetta a te decidere se siamo all'altezza—hmph!!"
  },
  AvgDialog_35992_Content_56 = {
    Text = "Ti inginocchi a terra, con le vertigini. Dall'altra parte, l'ombra respira con calma, avvicinandosi lentamente a te."
  },
  AvgDialog_35992_Content_57 = {
    Text = "No... Non riesco nemmeno a stare in piedi adesso. Devo prima stabilizzare lo spirito della personalità principale."
  },
  AvgDialog_35992_Content_58 = {
    Text = "Ti trascini fino a Mason e le prendi la mano."
  },
  AvgDialog_35992_Content_59 = {
    Text = "Signorina Mason, non lasci che la influenzi—"
  },
  AvgDialog_35992_Content_6 = {
    Text = "Jenkin—Miao—Miao—"
  },
  AvgDialog_35992_Content_60 = {
    Text = "È... perché sono troppo debole...?"
  },
  AvgDialog_35992_Content_61 = {
    Text = "Se solo fossi stata un po' più forte..."
  },
  AvgDialog_35992_Content_62 = {
    Text = "Se fosse stata lei, il destino di Mason oggi sarebbe stato diverso..."
  },
  AvgDialog_35992_Content_63 = {
    Text = "Heh, doloroso, vero? Moltiplica il tuo dolore attuale per dieci, per cento volte—ecco come ci sentiamo noi!"
  },
  AvgDialog_35992_Content_64 = {
    Text = "Sì, sì, sì."
  },
  AvgDialog_35992_Content_65 = {
    Text = "Non sei degna di usare questo corpo, corpo, cor, cor, corpo."
  },
  AvgDialog_35992_Content_66 = {
    Text = "Scusa, scusa, scusa, scusa..."
  },
  AvgDialog_35992_Content_67 = {
    Text = "Non sono Mason, non posso essere Mason—"
  },
  AvgDialog_35992_Content_68 = {Text = "Miao."},
  AvgDialog_35992_Content_69 = {
    Text = "La gatta ferita si spostò accanto a Mason, leccando delicatamente la sua ferita sanguinante."
  },
  AvgDialog_35992_Content_7 = {
    Text = [[
Il debole miagolio di un gatto fu rapidamente sommerso dal vento e dalla neve.
Montagne maestose e spoglie si ergevano davanti a lei, proiettando una tenue luce bluastra sulla terra.]]
  },
  AvgDialog_35992_Content_70 = {
    Text = "Poi abbassò di nuovo la testa, armeggiando con qualcosa."
  },
  AvgDialog_35992_Content_71 = {
    Text = "Tieni, non piangere, miao."
  },
  AvgDialog_35992_Content_72 = {
    Text = "In mezzo al vuoto, qualcosa viene premuto nel palmo della sua mano."
  },
  AvgDialog_35992_Content_73 = {
    Text = "Un tessuto morbido e fresco con un campanellino arrugginito attaccato a un'estremità."
  },
  AvgDialog_35992_Content_74 = {
    Text = "Nessuna delle \"24\" è superflua, perché..."
  },
  AvgDialog_35992_Content_75 = {
    Text = "Sei uno studioso intelligente e agile"
  },
  AvgDialog_35992_Content_76 = {
    Text = "Lord Rogers, se vinco, mi concederete una richiesta?"
  },
  AvgDialog_35992_Content_77 = {
    Text = "Non vi serve ancora un modello per la vostra collezione di sculture di cera? Posso fare da modello."
  },
  AvgDialog_35992_Content_78 = {
    Text = "<Gray:\"Primavera\" è l'opera di Rogers pianificata per l'esposizione. Se selezionata come modello, aumenterà la visibilità e permetterà a più persone di vederla.>"
  },
  AvgDialog_35992_Content_79 = {
    Text = "<Gray:Jenkin...>"
  },
  AvgDialog_35992_Content_8 = {
    Text = "Sniff sniff... Hmm?!"
  },
  AvgDialog_35992_Content_80 = {
    Text = "Sei la fonte di gioia di tutti."
  },
  AvgDialog_35992_Content_81 = {
    Text = "Tanto tempo fa, tra le montagne innevate dell'Infinito Nord, alla fine di un antico fiume, un mostro grigio sonnecchia~~~"
  },
  AvgDialog_35992_Content_82 = {
    Text = "Salve a tutti, io sono quel mostro. <Shake:Roar—>"
  },
  AvgDialog_35992_Content_83 = {
    Text = "<Shake:Waaah—>"
  },
  AvgDialog_35992_Content_84 = {
    Text = "Sei un gatto adorabile"
  },
  AvgDialog_35992_Content_85 = {
    Text = "Che sonno, awoo..."
  },
  AvgDialog_35992_Content_86 = {
    Text = "Glu, glu..."
  },
  AvgDialog_35992_Content_87 = {
    Text = "Fa davvero le fusa come un gatto... proprio come quei gatti nel campus di Mythag."
  },
  AvgDialog_35992_Content_88 = {
    Text = "Ehi, cosa ti fa ridere!"
  },
  AvgDialog_35992_Content_89 = {
    Text = "Ora sembra felice, davvero come una gattina spensierata."
  },
  AvgDialog_35992_Content_9 = {
    Text = "Sentì l'odore dei suoni. Fluttuavano nell'aria, senza parole e senza ritmo, come il dolce richiamo di una madre."
  },
  AvgDialog_35992_Content_90 = {
    Text = "Già... Sono tutti dei grandi \"24\".\nRispetto a loro, io sono completamente inutile..."
  },
  AvgDialog_35992_Content_91 = {
    Text = "Hai scosso delicatamente la testa."
  },
  AvgDialog_35992_Content_92 = {
    Text = "Al contrario, sei più forte e più coraggiosa di loro perché—"
  },
  AvgDialog_35992_Content_93 = {
    Text = "Sei la migliore sorella del mondo."
  },
  AvgDialog_35992_Content_94 = {
    Text = "Padrone, tutto questo è colpa mia."
  },
  AvgDialog_35992_Content_95 = {
    Text = "È solo una ragazzina dei bassifondi, non sa nulla e non rappresenterà alcuna minaccia per voi..."
  },
  AvgDialog_35992_Content_96 = {
    Text = "<Shake:L-Lasciatela andare... Vi prego...>"
  },
  AvgDialog_35992_Content_97 = {
    Text = "<Shake:Lasciatela andare...>"
  },
  AvgDialog_35992_Content_98 = {
    Text = "Il gatto allungò la sua zampa morbida per tenere la mano di Mason."
  },
  AvgDialog_35992_Content_99 = {
    Text = "Ci sono Mason coraggiosi e Mason codardi. Ci sono Mason intelligenti e Mason sciocchi.\nNiente di tutto questo conta perché —"
  },
  AvgDialog_35993_Content_1 = {
    Text = "Canto del pellegrino"
  },
  AvgDialog_35993_Content_10 = {
    Text = "<Yellow:Emaciata, con capelli lunghi e probabilmente in possesso di più di un paio di arti superiori.>"
  },
  AvgDialog_35993_Content_11 = {
    Text = "Secondo il <Blue:'Rapporto sull'Evento di Dissoluzione di Southwark Street: C06'>, creature corrispondenti all'aspetto e al raggio d'azione esistono qui"
  },
  AvgDialog_35993_Content_12 = {
    Text = "\nQuesto rapporto è stato archiviato negli Archivi Unificati dall'Università di Mythag.\nState forse tentando di negarne l'autenticità?"
  },
  AvgDialog_35993_Content_13 = {
    Text = "È un po' esagerato mettere in dubbio l'affidabilità delle testimonianze oculari, signori."
  },
  AvgDialog_35993_Content_14 = {
    Text = "Invece di perdere tempo a giocare con le parole, perché non chiedere direttamente alla persona coinvolta?"
  },
  AvgDialog_35993_Content_15 = {
    Text = "Signorina 24, ricorda cosa stava facendo alle 21:15 del 17 dicembre nella <Blue:Clinica del Dottor Bernard>?"
  },
  AvgDialog_35993_Content_16 = {Text = "Eh? Io..."},
  AvgDialog_35993_Content_17 = {
    Text = "Solo un promemoria: secondo le cartelle cliniche del <Blue:Dottor Bernard>, lei è stata l'ultima paziente da lui visitata prima della sua morte."
  },
  AvgDialog_35993_Content_18 = {Text = "..."},
  AvgDialog_35993_Content_19 = {
    Text = "Cosa ho fatto?"
  },
  AvgDialog_35993_Content_2 = {
    Text = "La pellegrina scalza avanza strisciando."
  },
  AvgDialog_35993_Content_20 = {
    Text = "<Red:...Ovviamente, ucciderlo.>"
  },
  AvgDialog_35993_Content_21 = {
    Text = "Signorina 24? Mi sta ascoltando?"
  },
  AvgDialog_35993_Content_22 = {
    Text = "Un pugno, due pugni, tre pugni... Gli ho fracassato quel bel viso in mille pezzi, senza lasciare nemmeno un osso."
  },
  AvgDialog_35993_Content_23 = {
    Text = "Il sapore del sangue è rimasto su di me per un'intera settimana."
  },
  AvgDialog_35993_Content_24 = {
    Text = "<Small:Purtroppo, il sospettato ha mostrato comportamenti di Schivare; in base alle clausole del \"Trattato\", il Comitato ha il diritto di riportarlo indietro immediatamente.>"
  },
  AvgDialog_35993_Content_25 = {
    Text = "<Small:No. La Signorina 24 è diversa dagli altri Risvegliatori. Lei—>"
  },
  AvgDialog_35993_Content_26 = {
    Text = "<Small:Soffre di isteria; è una pazza, come tutti sappiamo. Ma questo significa che una pazza può uccidere un rispettato dottore a suo piacimento?>"
  },
  AvgDialog_35993_Content_27 = {
    Text = "<Small:Questo è irragionevole, Signorina Doll.>"
  },
  AvgDialog_35993_Content_28 = {
    Text = "<Red:Sono un'assassina.>"
  },
  AvgDialog_35993_Content_29 = {
    Text = "Signorina 24...? <Big:Signorina 24!>"
  },
  AvgDialog_35993_Content_3 = {
    Text = "Il vento e la neve dell'Estremo Nord celano il volto della pellegrina. Le dita dei piedi sono screpolate, la vista è offuscata, e il suo sangue lascia una lunga scia nella neve."
  },
  AvgDialog_35993_Content_30 = {
    Text = "Si svegli! Non ho ancora nemmeno iniziato l'iniezione! Non è il momento di dormire..."
  },
  AvgDialog_35993_Content_31 = {
    Text = "Eh... Cos'è questo..."
  },
  AvgDialog_35993_Content_32 = {
    Text = "Grazie al cielo, finalmente si è svegliata!"
  },
  AvgDialog_35993_Content_33 = {
    Text = "Sala di Mythag"
  },
  AvgDialog_35993_Content_34 = {
    Text = "Ho sentito che la sua memoria è stata piuttosto confusa ultimamente. Le spiego un po'."
  },
  AvgDialog_35993_Content_35 = {
    Text = "L'ultima indagine sulla <Yellow:Morte del Dottor Bernard> ha causato una disputa piuttosto spiacevole con il Comitato di Revisione."
  },
  AvgDialog_35993_Content_36 = {
    Text = "La conclusione finale è: sette giorni. Abbiamo solo sette giorni per scoprire la verità."
  },
  AvgDialog_35993_Content_37 = {
    Text = "Se ricordo bene, questo è successo prima che lei fosse mandata al museo delle cere, quindi non ne sapevamo nulla"
  },
  AvgDialog_35993_Content_38 = {
    Text = "I fascicoli sono stati sigillati per mesi; chissà dove sono riusciti a scovarli. Inoltre, condurre un'indagine in un posto caotico come il Distretto Est è pura utopia..."
  },
  AvgDialog_35993_Content_39 = {
    Text = "Quindi, abbiamo deciso di far entrare %player% nel suo Dominio Artificiale per le indagini. Abbiamo bisogno della sua leggera collaborazione..."
  },
  AvgDialog_35993_Content_4 = {
    Text = "Ma continua a marciare risoluta e incrollabile verso la vetta."
  },
  AvgDialog_35993_Content_40 = {
    Text = "Capisco. Mi scusi, ultimamente mi sento assonnata..."
  },
  AvgDialog_35993_Content_41 = {
    Text = "Sembra che una terribile tempesta si stia preparando all'interno del Corpo, eppure il suo ospite ne è del tutto ignaro."
  },
  AvgDialog_35993_Content_42 = {Text = "Aspetta."},
  AvgDialog_35993_Content_43 = {
    Text = "\"Sono davvero io il padrone di questo corpo?\""
  },
  AvgDialog_35993_Content_44 = {Text = "Ding—!"},
  AvgDialog_35993_Content_45 = {
    Text = "Winkle tira fuori rapidamente una siringa già preparata."
  },
  AvgDialog_35993_Content_46 = {
    Text = "Non preoccuparti, sono qui per questo. \nUna puntura e il tuo cervello confuso si schiarirà..."
  },
  AvgDialog_35993_Content_47 = {
    Text = "<Shake:Così, %player% soffrirà meno là dentro. Dopotutto, nessuno sa cosa potrebbe esserci. E se dovesse accadere un disastro...>"
  },
  AvgDialog_35993_Content_48 = {
    Text = "O incontrare di nuovo un essere terrificante come \"N\"—<Big:Ah!!>"
  },
  AvgDialog_35993_Content_49 = {
    Text = "Winkle si grattò ansiosamente la testa, sussultando per lo spavento."
  },
  AvgDialog_35993_Content_5 = {
    Text = "Sì—\nSotto quelle montagne bianche, nelle profondità della caverna oscura, giace la fonte di tutte le impurità, la <Red:Sorgente>."
  },
  AvgDialog_35993_Content_50 = {
    Text = "<Shake:Maledizione! Perché sto perdendo di nuovo così tanti capelli...>"
  },
  AvgDialog_35993_Content_51 = {
    Text = "La signorina 24 ha bisogno di calma, non della tua ansia e dei tuoi capelli. Winkle, per favore esci subito dopo l'iniezione."
  },
  AvgDialog_35993_Content_52 = {
    Text = "Tra 10 minuti"
  },
  AvgDialog_35993_Content_53 = {
    Text = "Si sente meglio ora, signorina 24?"
  },
  AvgDialog_35993_Content_54 = {
    Text = "Sto bene, solo un po' di vertigini... Dov'è %player%?"
  },
  AvgDialog_35993_Content_55 = {
    Text = "Già nel Passaggio del Dominio Artificiale.\nStia tranquilla, questa volta abbiamo impostato la durata a soli trenta minuti e non ci tratterremo troppo a lungo."
  },
  AvgDialog_35993_Content_56 = {
    Text = "E la signorina Ramona? Non vi ha accompagnato durante l'Operazione?"
  },
  AvgDialog_35993_Content_57 = {
    Text = "Dato lo stato mentale piuttosto... instabile dei proprietari dei Domini, non possiamo immaginare cosa potrebbe apparire all'interno del Dominio."
  },
  AvgDialog_35993_Content_58 = {
    Text = "Il potere spirituale di Ramona potrebbe non essere in grado di resistere."
  },
  AvgDialog_35993_Content_59 = {
    Text = "24 abbassò la testa con frustrazione e strinse in silenzio l'angolo della coperta."
  },
  AvgDialog_35993_Content_6 = {
    Text = "Quella è la sua paura, il suo incubo."
  },
  AvgDialog_35993_Content_60 = {
    Text = "Signorina Doll, e se dicessi che... l'assassina sono davvero io?"
  },
  AvgDialog_35993_Content_61 = {
    Text = "Ricordo. Quel giorno, sono andata alla clinica, e poi—"
  },
  AvgDialog_35993_Content_62 = {
    Text = "Shh... Non posso garantire che non ci siano spie piazzate dal Comitato qui."
  },
  AvgDialog_35993_Content_63 = {
    Text = "Doll richiama alla mente l'immagine di Sylvia, cercando di abbozzare un sorriso rassicurante."
  },
  AvgDialog_35993_Content_64 = {
    Text = "Signorina 24, probabilmente non si conosce così bene come crede."
  },
  AvgDialog_35993_Content_65 = {
    Text = "La cosiddetta \"verità\" che vede potrebbe non essere reale."
  },
  AvgDialog_35993_Content_66 = {
    Text = "Non capisco... Non reale...?"
  },
  AvgDialog_35993_Content_67 = {
    Text = "È a Mythag da diversi mesi ormai, ma non sappiamo nulla delle sue condizioni o delle sue esperienze passate."
  },
  AvgDialog_35993_Content_68 = {
    Text = "Considera questa indagine nel Dominio come un'opportunità per conoscerti di nuovo, Miss 24."
  },
  AvgDialog_35993_Content_69 = {
    Text = "Vogliamo tutti conoscerti meglio."
  },
  AvgDialog_35993_Content_7 = {
    Text = "È anche la sua destinazione finale."
  },
  AvgDialog_35993_Content_8 = {
    Text = "Non accetto le vostre cosiddette \"prove\"."
  },
  AvgDialog_35993_Content_9 = {
    Text = "Questa cosiddetta testimonianza oculare dimostra soltanto che il colpevole è un'entità non umana e non può identificare alcun individuo specifico."
  },
  AvgDialog_35994_Content_1 = {
    Text = "Fiaba d'Ombra"
  },
  AvgDialog_35994_Content_10 = {
    Text = "<Red:Sssss...>"
  },
  AvgDialog_35994_Content_11 = {
    Text = "Nell'oscurità emergono deboli suoni, come il sibilo di una vipera in un angolo deserto."
  },
  AvgDialog_35994_Content_12 = {
    Text = "Un serpente... Chi c'è?!"
  },
  AvgDialog_35994_Content_13 = {
    Text = "Toc, toc, toc."
  },
  AvgDialog_35994_Content_14 = {
    Text = "I passi affrettati si avvicinano, e lunghi capelli ti sfiorano rapidamente il viso."
  },
  AvgDialog_35994_Content_15 = {
    Text = "Signorina Mason?!"
  },
  AvgDialog_35994_Content_16 = {
    Text = "Lasciami... Ehi, chi sei? Sei con <Yellow:quella donna>?"
  },
  AvgDialog_35994_Content_17 = {
    Text = "Eh, non ti ricordi di me?"
  },
  AvgDialog_35994_Content_18 = {
    Text = "<Gray:Ora ricordo. L'omicidio è avvenuto prima che la signorina Mason entrasse nel museo delle cere, quando ancora non ci eravamo incontrati...>"
  },
  AvgDialog_35994_Content_19 = {
    Text = "Toc, toc, toc."
  },
  AvgDialog_35994_Content_2 = {
    Text = "<Yellow:Registro Operazione Dominio Artificiale>\n\n■ID Dominio: M-C06\n■Ora di Configurazione: 17 Dicembre, A.F. 315, 21:00-21:30\n■Luogo di Configurazione: Clinica del Dottor Bernard"
  },
  AvgDialog_35994_Content_20 = {
    Text = "A differenza dei passi affrettati di prima, questi sono più stabili."
  },
  AvgDialog_35994_Content_21 = {
    Text = "<Shake:Sta arrivando... Sta arrivando...>"
  },
  AvgDialog_35994_Content_22 = {
    Text = "Chi sta arrivando?"
  },
  AvgDialog_35994_Content_23 = {
    Text = "Lei... no, \"io\" sono arrivata!"
  },
  AvgDialog_35994_Content_24 = {
    Text = "<Big:\"Sto venendo a uccidermi!\">"
  },
  AvgDialog_35994_Content_25 = {Text = "?"},
  AvgDialog_35994_Content_26 = {
    Text = "Pugni che fischiano nel vento si abbattono su di te."
  },
  AvgDialog_35994_Content_28 = {
    Text = "<Big:Morite tutti!>"
  },
  AvgDialog_35994_Content_29 = {
    Text = "Tra 10 minuti"
  },
  AvgDialog_35994_Content_3 = {
    Text = "■Proprietaria del Dominio: Mason @2\n■Infiltrato nel Dominio: %player%\n■Obiettivo: <Yellow:Indagare sulla morte del Dott. Bernard>"
  },
  AvgDialog_35994_Content_31 = {
    Text = "Si calmi, per favore, Signorina... \"24\"."
  },
  AvgDialog_35994_Content_32 = {
    Text = "Ti metti davanti a Mason, trattenendo a malapena i feroci assalti delle ombre."
  },
  AvgDialog_35994_Content_33 = {
    Text = "Fai un altro passo e non avrò alcuna pietà."
  },
  AvgDialog_35994_Content_34 = {
    Text = "Heh, sembra che la piagnucolona si sia trovata un aiutante."
  },
  AvgDialog_35994_Content_35 = {
    Text = "La luce fioca delinea una figura snella e familiare: capelli lunghi, un vestito bianco e iridi rosso sangue."
  },
  AvgDialog_35994_Content_36 = {
    Text = "È un'altra \"24\"."
  },
  AvgDialog_35994_Content_37 = {
    Text = "Non c'è più tempo... Non preoccuparti, mi occuperò di ciascuno di voi, uno alla volta."
  },
  AvgDialog_35994_Content_38 = {
    Text = "Presto toccherà a te."
  },
  AvgDialog_35994_Content_39 = {
    Text = "Senza aggiungere altro, \"24\" se ne andò prontamente."
  },
  AvgDialog_35994_Content_4 = {
    Text = "<Shake:Coff coff... che puzza...>"
  },
  AvgDialog_35994_Content_40 = {
    Text = "Aspettate—"
  },
  AvgDialog_35994_Content_41 = {
    Text = "Smetti di inseguirla. Non possiamo sconfiggerla..."
  },
  AvgDialog_35994_Content_42 = {
    Text = "Cosa sta succedendo? Perché c'è un'altra te qui?"
  },
  AvgDialog_35994_Content_43 = {
    Text = "Non lo so... È apparsa all'improvviso e ha detto che voleva uccidermi..."
  },
  AvgDialog_35994_Content_44 = {
    Text = "Anche quel dottore è stato ucciso da lei?"
  },
  AvgDialog_35994_Content_45 = {
    Text = "Quindi è stata lei a ucciderlo?! No, non solo quello... c'è anche il serpente in letargo..."
  },
  AvgDialog_35994_Content_46 = {
    Text = "Migliaia di serpenti @2 uccidono i propri fratelli, con le dita in bocca... Mmm..."
  },
  AvgDialog_35994_Content_47 = {
    Text = "Signorina Mason? Sa quello che sta dicendo?"
  },
  AvgDialog_35994_Content_48 = {
    Text = "Cosa? Non conta quello che dici, ma quello che fai! È quello che mi ha insegnato il Signor @2..."
  },
  AvgDialog_35994_Content_49 = {
    Text = "Mason è completamente immersa nel suo mondo, mormorando una serie di farneticazioni caotiche."
  },
  AvgDialog_35994_Content_5 = {
    Text = "La clinica è avvolta in un denso fetore di sangue, con attrezzature mediche, libri e cartelle cliniche sparsi ovunque sul pavimento."
  },
  AvgDialog_35994_Content_50 = {
    Text = "Tu... ho la sensazione di averti già visto da qualche parte..."
  },
  AvgDialog_35994_Content_51 = {
    Text = "%player%... Voi siete il Custode!"
  },
  AvgDialog_35994_Content_52 = {Text = "..."},
  AvgDialog_35994_Content_53 = {
    Text = "Come hai fatto a ricordarti improvvisamente chi sono?"
  },
  AvgDialog_35994_Content_54 = {
    Text = "All'improvviso senti un mal di testa."
  },
  AvgDialog_35994_Content_55 = {
    Text = "Non avere fretta; non ho ancora finito di parlare."
  },
  AvgDialog_35994_Content_56 = {
    Text = "Il Dominio di 24 è diverso da quelli di Ramona e Sorel. Le manca una personalità stabile, e questo si rifletterà inevitabilmente nel suo Dominio."
  },
  AvgDialog_35994_Content_57 = {
    Text = "Le diverse personalità sono isolate eppure intrecciate. Potresti persino vedere molte 24 al loro interno."
  },
  AvgDialog_35994_Content_58 = {
    Text = "Tutto quanto—persone, luoghi, tempo... forse niente di tutto ciò è reale."
  },
  AvgDialog_35994_Content_59 = {
    Text = "Se è tutto falso, ha senso la mia indagine?"
  },
  AvgDialog_35994_Content_6 = {
    Text = "Il corpo del Dott. Bernard giaceva accasciato contro il muro. La sua testa era mutilata oltre ogni riconoscimento."
  },
  AvgDialog_35994_Content_60 = {
    Text = "Certo. Anche se c'è solo l'un percento di possibilità che sia vero, dobbiamo coglierla."
  },
  AvgDialog_35994_Content_61 = {
    Text = "Sappiamo tutti che la Signorina 24 non è una che uccide indiscriminatamente."
  },
  AvgDialog_35994_Content_62 = {
    Text = "Niente di tutto questo è reale... Mantieni la calma, %player%. Prima di tutto, chiarisci gli obiettivi della tua indagine."
  },
  AvgDialog_35994_Content_63 = {
    Text = "Esamini il dito di Mason. È molto pulito, senza segni di ferite o colluttazione."
  },
  AvgDialog_35994_Content_64 = {
    Text = "Signorina Mason, ha qualche rancore nei confronti del Dottor Bernard?"
  },
  AvgDialog_35994_Content_65 = {
    Text = "Lui... mi curava, ma ultimamente sento prurito dappertutto. È davvero strano..."
  },
  AvgDialog_35994_Content_66 = {
    Text = "Mason parlava con noncuranza, grattando il bulbo oculare bianco che cresceva dalla sua ferita da Dissoluzione."
  },
  AvgDialog_35994_Content_67 = {
    Text = "Naturalmente, era del tutto inconsapevole del proprio comportamento."
  },
  AvgDialog_35994_Content_68 = {
    Text = "L'ha guarita. Poi, avete iniziato a litigare?"
  },
  AvgDialog_35994_Content_69 = {
    Text = "Dopo... dopo, non riuscivo a ricordare più nulla..."
  },
  AvgDialog_35994_Content_7 = {
    Text = "\"Maschio di 30 anni, alto un metro e ottanta, laureatosi con lode alla facoltà di medicina dell'Università di Londinium...\""
  },
  AvgDialog_35994_Content_70 = {
    Text = "Capisco, ho compreso."
  },
  AvgDialog_35994_Content_71 = {
    Text = "<Gray:La perdita di memoria è un segno chiave della personalità multipla. Qualcosa potrebbe essere accaduto durante il trattamento, causando l'emergere della personalità ombra che ha ucciso il dottore...>"
  },
  AvgDialog_35994_Content_72 = {
    Text = "<Gray:Ora dobbiamo solo riavvolgere il tempo del Dominio di un'ora e vedere cosa è successo allora...>"
  },
  AvgDialog_35994_Content_73 = {
    Text = "Hai alzato la mano e dato un'occhiata all'orologio."
  },
  AvgDialog_35994_Content_74 = {
    Text = "Il Dominio sta per terminare. Concludiamo l'indagine per ora."
  },
  AvgDialog_35994_Content_75 = {
    Text = "La Signorina Doll forse si preoccupa troppo; questo Dominio è molto più semplice di quello della Signora Sorel..."
  },
  AvgDialog_35994_Content_76 = {
    Text = "Ti stiracchi pigramente, poi ti accovacci davanti a Mason, guardandola dritta negli occhi."
  },
  AvgDialog_35994_Content_77 = {
    Text = "Signorina Mason, la sua malattia non è una cosa ordinaria. Non è qualcosa che un dottore qualsiasi con un diploma prestigioso possa curare."
  },
  AvgDialog_35994_Content_78 = {
    Text = "La prossima volta, si ricordi di cercarci a Mythag, capito?"
  },
  AvgDialog_35994_Content_79 = {
    Text = "Mi, Sa, Ge..."
  },
  AvgDialog_35994_Content_8 = {
    Text = "\"Noto per la sua generosità, ha fornito servizi medici volontari in varie zone del Distretto Est per molti anni...\""
  },
  AvgDialog_35994_Content_80 = {
    Text = "Sì, Università di Mythag. Siamo dei professionisti."
  },
  AvgDialog_35994_Content_81 = {Text = "Oh..."},
  AvgDialog_35994_Content_82 = {
    Text = "Plop. Plop."
  },
  AvgDialog_35994_Content_83 = {
    Text = "Le pareti sopra iniziano a sgretolarsi poco a poco, il Dominio non è più stabile."
  },
  AvgDialog_35994_Content_84 = {
    Text = "Addio, signorina Mason."
  },
  AvgDialog_35994_Content_85 = {Text = "..."},
  AvgDialog_35994_Content_86 = {
    Text = [[
Sono le 21:30.
Un vento gelido ulula fuori, e oltre la finestra, alcuni corvi emettono grida solitarie.]]
  },
  AvgDialog_35994_Content_87 = {
    Text = "Sei ancora saldamente in piedi nella clinica, con Mason inginocchiato accanto a te, con un'espressione sconcertata."
  },
  AvgDialog_35994_Content_88 = {
    Text = "Hmm... {Male=Sig.,Female=Sig.na} Custode, non ha intenzione di partire di nuovo?"
  },
  AvgDialog_35994_Content_89 = {
    Text = "<Shake:Ehm, l'attrezzatura sta funzionando male?>"
  },
  AvgDialog_35994_Content_9 = {
    Text = "Un curriculum impeccabile, non c'è da stupirsi che la polizia e il Comitato gli attribuiscano tanta importanza."
  },
  AvgDialog_35994_Content_90 = {Text = "Zing—!!"},
  AvgDialog_35994_Content_91 = {
    Text = "Un istante dopo, il mondo crolla rapidamente e precipiti in un abisso senza fondo."
  },
  AvgDialog_35994_Content_92 = {
    Text = "<Big:Aaaaaaa—!!!>"
  },
  AvgDialog_35994_Content_93 = {
    Text = "<Yellow:Registro dell'Operazione nel Dominio Artificiale I>\n\n■ID Dominio: M-C06\n■Orario di configurazione: 17 dicembre, AF 315, 21:00-21:30\n■Luogo di configurazione: Clinica del Dr. Bernard"
  },
  AvgDialog_35994_Content_94 = {
    Text = "<Yellow:■Risultati dell'Operazione>\n\n—Custode scomparso."
  },
  AvgDialog_35996_Content_1 = {
    Text = "Perché... perché..."
  },
  AvgDialog_35996_Content_10 = {
    Text = "Spinti dalla disperazione e senza nessuno a cui rivolgersi, questo è \"24\"."
  },
  AvgDialog_35996_Content_11 = {
    Text = "Coloro che trovano la felicità in una vita semplice sono \"24\"."
  },
  AvgDialog_35996_Content_12 = {
    Text = "Tormentati dagli scultori, anche questo è \"24\"."
  },
  AvgDialog_35996_Content_13 = {
    Text = "No... Se non fosse stato per la tua codardia, non saremmo stati catturati da quel dottore..."
  },
  AvgDialog_35996_Content_14 = {Text = "Shh..."},
  AvgDialog_35996_Content_15 = {
    Text = "Mason coprì delicatamente le labbra dell'ombra. Si chinò e le sussurrò all'orecchio."
  },
  AvgDialog_35996_Content_16 = {
    Text = "Ti svelo un segreto: <Red:Quel dottore l'ho ucciso io.>"
  },
  AvgDialog_35996_Content_17 = {
    Text = "Impossibile. Come hai osato...?!"
  },
  AvgDialog_35996_Content_18 = {
    Text = "Uccidere non è difficile. Non avevo un'arma, quindi ho usato le mie mani per—"
  },
  AvgDialog_35996_Content_19 = {
    Text = "Alla fine, le mie mani erano intorpidite e tutto ciò che riuscivo a vedere era sangue."
  },
  AvgDialog_35996_Content_2 = {
    Text = "L'Ombra è sconfitta da te. Crolla a terra, con minuscole particelle di luce che si staccano dal suo corpo."
  },
  AvgDialog_35996_Content_20 = {
    Text = "Dovevo assicurarmi che fosse completamente morto. Finché avesse ancora respirato, avrebbe sicuramente fatto del male ai bambini dell'orfanotrofio e a Jenkin..."
  },
  AvgDialog_35996_Content_21 = {
    Text = "Era proprio come quelle persone degli scultori, no — era ancora più terrificante..."
  },
  AvgDialog_35996_Content_22 = {
    Text = "Era un vero demone."
  },
  AvgDialog_35996_Content_23 = {
    Text = "Quindi eri tu... Eri davvero tu..."
  },
  AvgDialog_35996_Content_24 = {
    Text = "Cosa stavo facendo allora... Non sapevo nulla..."
  },
  AvgDialog_35996_Content_25 = {
    Text = "Mason scosse delicatamente la testa."
  },
  AvgDialog_35996_Content_26 = {
    Text = "È stato il coraggio che mi avete prestato tu e gli altri \"24\"."
  },
  AvgDialog_35996_Content_27 = {
    Text = "Tutti i \"24\" si combinano per formare un'unica \"Mason\".\nNessun \"24\" può esistere in isolamento."
  },
  AvgDialog_35996_Content_28 = {
    Text = "Proprio come tutti i fiumi convergono in un unico luogo, anche tutti i \"24\" convergeranno in un unico luogo..."
  },
  AvgDialog_35996_Content_29 = {
    Text = "Mason baciò delicatamente la fronte dell'Ombra."
  },
  AvgDialog_35996_Content_3 = {
    Text = "Come ha potuto qualcuno potente e furioso come me... perdere contro di te, perdere contro questa codarda..."
  },
  AvgDialog_35996_Content_30 = {
    Text = "Mi appartiene."
  },
  AvgDialog_35996_Content_32 = {
    Text = "Il corpo dell'ombra si trasforma in luce stellare, disperdendosi attorno a Mason e fondendosi nella sua pelle."
  },
  AvgDialog_35996_Content_33 = {
    Text = "Capito... d'accordo."
  },
  AvgDialog_35996_Content_34 = {
    Text = "Tu sei l'origine di ogni cosa, e anche la fine di ogni cosa..."
  },
  AvgDialog_35996_Content_35 = {
    Text = "Perse gradualmente la voce in quel caldo abbraccio."
  },
  AvgDialog_35996_Content_36 = {
    Text = "La luce stellare brilla come lucciole nella notte, apparendo e scomparendo, fino a svanire del tutto."
  },
  AvgDialog_35996_Content_37 = {
    Text = "Buonanotte, mio \"ventiquattresimo\"."
  },
  AvgDialog_35996_Content_38 = {
    Text = "<Yellow:Registro dell'Operazione Dominio Artificiale IV>\n\n■ID Dominio: M-C06\n■Ora della caduta: Anno 315 del Diluvio, dicembre @1\n■Luogo della caduta: Camberwell Street, Distretto Est"
  },
  AvgDialog_35996_Content_39 = {
    Text = "<Yellow:■Risultati dell'Operazione>\n\nIl Dominio si è concluso silenziosamente.\nDopo di ciò, le condizioni della Signorina Mason si sono stabilizzate notevolmente, portando immensa gioia a tutti.\n\n<Yellow:Ci stiamo gradualmente avvicinando alla vera Signorina Mason.>"
  },
  AvgDialog_35996_Content_4 = {Text = "Perché..."},
  AvgDialog_35996_Content_40 = {
    Text = "Università di Mythag, Segreteria Scolastica\nUn giorno dopo"
  },
  AvgDialog_35996_Content_41 = {
    Text = "Cosa? Il Comitato ha ritirato l'accusa?"
  },
  AvgDialog_35996_Content_42 = {
    Text = "Mentre eri via, sono successe molte cose interessanti. Ora sono impegnati a gestire l'infestazione di serpenti insieme al dipartimento ambientale della città."
  },
  AvgDialog_35996_Content_43 = {
    Text = "Infestazione di serpenti...?"
  },
  AvgDialog_35996_Content_44 = {
    Text = "Doll stende davanti a te un numero del \"Londinium Post\" di qualche giorno fa."
  },
  AvgDialog_35996_Content_45 = {
    Text = "\"Di recente, un improvviso afflusso di serpenti albini di specie sconosciuta è emerso dalla clinica del defunto Dott. Bernard, causando gravi disagi al trasporto locale e alla vita quotidiana...\""
  },
  AvgDialog_35996_Content_46 = {
    Text = "\"Testimoni oculari affermano che questa sia stata la scena più terrificante a cui abbiano mai assistito. Se anche i lettori ne sono stati testimoni, si prega di contattare uno psicologo al @2...\""
  },
  AvgDialog_35996_Content_47 = {
    Text = "\"Numero@4...\""
  },
  AvgDialog_35996_Content_48 = {
    Text = "Accanto alla notizia, c'è una foto in cui sembri riconoscere alcuni volti familiari del Comitato."
  },
  AvgDialog_35996_Content_49 = {
    Text = "Tengono in mano delle reti, ripulendo instancabilmente i piccoli serpenti che continuano a emergere, con volti che tradiscono stanchezza e impazienza."
  },
  AvgDialog_35996_Content_5 = {Text = "..."},
  AvgDialog_35996_Content_50 = {
    Text = "Quel cosiddetto \"Dottor Bernard\" ha seri problemi."
  },
  AvgDialog_35996_Content_51 = {
    Text = "Abbiamo trovato i membri della Royal Medical Society, ma le foto da loro fornite sono completamente diverse dalle descrizioni date dai residenti della zona."
  },
  AvgDialog_35996_Content_52 = {
    Text = "In altre parole, il defunto aveva rubato l'identità di questo Dott. Bernard. Tuttavia, non è ancora chiaro se questo falso dottore sia davvero morto."
  },
  AvgDialog_35996_Content_53 = {
    Text = "Dopotutto, sulla scena non è stata trovata nemmeno una traccia del corpo..."
  },
  AvgDialog_35996_Content_54 = {
    Text = [[
17 dicembre, il giorno dell'incidente
Clinica del Dott. Bernard]]
  },
  AvgDialog_35996_Content_55 = {
    Text = "Il trattamento di oggi è terminato. Signorina Mason, sta guarendo bene."
  },
  AvgDialog_35996_Content_56 = {
    Text = "Davvero? Ma tutti dicono che le mie condizioni stanno peggiorando..."
  },
  AvgDialog_35996_Content_57 = {
    Text = [[
Temo che la mia comprensione di "grave" differisca da quella degli altri esseri umani.
Ha preso tutte le tinture che le ho prescritto nei tempi stabiliti?]]
  },
  AvgDialog_35996_Content_58 = {Text = "Splash!!"},
  AvgDialog_35996_Content_59 = {
    Text = "Il dottore urtò accidentalmente i fascicoli a portata di mano, sparpagliando le pagine ingiallite su tutto il pavimento."
  },
  AvgDialog_35996_Content_6 = {
    Text = "Lascia fare a me."
  },
  AvgDialog_35996_Content_60 = {
    Text = "Mi scusi, il Distretto Est è stato colpito da frequenti epidemie di recente, e i documenti della clinica si stanno accumulando—"
  },
  AvgDialog_35996_Content_61 = {
    Text = "Non si preoccupi! Lei è un dottore impegnato che lavora giorno e notte. Lasci il piccolo compito di raccogliere le cose a..."
  },
  AvgDialog_35996_Content_62 = {Text = "Beh..."},
  AvgDialog_35996_Content_63 = {
    Text = "La mano si fermò a meno di 5 centimetri dal fascicolo. Era una pila di documenti d'identità, e Mason riuscì a malapena a distinguere alcune parole vagamente familiari."
  },
  AvgDialog_35996_Content_64 = {
    Text = "Rapporto dell'esperimento, registro dei trasferimenti...?"
  },
  AvgDialog_35996_Content_65 = {
    Text = "<Shake:Questi sono... i bambini scomparsi dall'orfanotrofio! No, è anche peggio...>"
  },
  AvgDialog_35996_Content_66 = {
    Text = "Nell'angolo del fascicolo esposto in fondo, Mason vide il volto leggermente ostinato di Jenkin."
  },
  AvgDialog_35996_Content_67 = {
    Text = "È tua sorella? L'ho vista. È sempre preoccupata per te e ha persino provato a intrufolarsi."
  },
  AvgDialog_35996_Content_68 = {
    Text = "Sorrise debolmente, la sua espressione si fece gentile."
  },
  AvgDialog_35996_Content_69 = {
    Text = "Un tempo avevo molti fratelli e sorelle... Mi temevano soltanto, così li ho divorati tutti."
  },
  AvgDialog_35996_Content_70 = {
    Text = "Tutti quanti... mangiati?"
  },
  AvgDialog_35996_Content_71 = {
    Text = "Non si preoccupi, Signorina Mason. Non ho mangiato i suoi amici; li ho solo mandati in un <Red:posto sicuro>."
  },
  AvgDialog_35996_Content_72 = {
    Text = "Quindi, lei è la mente dietro queste sparizioni..."
  },
  AvgDialog_35996_Content_73 = {
    Text = "<Shake:Questo scherzo non è affatto divertente, signor Bernard...>"
  },
  AvgDialog_35996_Content_74 = {
    Text = "Signor Bernard... Si riferisce a questo?"
  },
  AvgDialog_35996_Content_75 = {
    Text = "L'uomo parlò, facendo fuoriuscire dalla bocca una lunga lingua che si avvolse attorno a un dito mozzato e insanguinato."
  },
  AvgDialog_35996_Content_76 = {
    Text = "È troppo grande; non riesco ancora a digerirlo."
  },
  AvgDialog_35996_Content_77 = {
    Text = "Ripresentiamoci. Sono <Yellow:Albino>, il farmacista de Gli scultori."
  },
  AvgDialog_35996_Content_78 = {
    Text = "Aaaaaah—!!"
  },
  AvgDialog_35996_Content_79 = {
    Text = "Le gambe di Mason cedettero e crollò pesantemente a terra."
  },
  AvgDialog_35996_Content_8 = {
    Text = "Mason si sedette accanto all'ombra, stringendo tra le braccia l'ombra immobile."
  },
  AvgDialog_35996_Content_80 = {
    Text = "<Shake:Sei una persona cattiva... Vuoi portarmi via anche Jenkin...>"
  },
  AvgDialog_35996_Content_81 = {
    Text = "L'uomo si sistemò gli occhiali e annotò rapidamente delle note sulla cartella clinica."
  },
  AvgDialog_35996_Content_82 = {
    Text = "Pupille dilatate, corpo che trema violentemente, battito cardiaco accelerato... Devi essere estremamente terrorizzato in questo momento. Hai freddo?"
  },
  AvgDialog_35996_Content_83 = {
    Text = "No... Stai indietro..."
  },
  AvgDialog_35996_Content_84 = {
    Text = "Presto, svenirai per l'insufficiente afflusso di sangue al cervello, proprio come gli altri ottusi esseri umani."
  },
  AvgDialog_35996_Content_85 = {
    Text = "Sollevò lo sguardo dalla cartella clinica, un debole bagliore di eccitazione che tremolava nelle sue pupille verticali dorate."
  },
  AvgDialog_35996_Content_86 = {
    Text = "Oppure... reagirai in modo diverso?"
  },
  AvgDialog_35996_Content_87 = {
    Text = "20 minuti dopo"
  },
  AvgDialog_35996_Content_88 = {
    Text = "Ho ucciso qualcuno... Ho davvero ucciso un dottore... Non mi crederanno..."
  },
  AvgDialog_35996_Content_89 = {
    Text = "No, perché l'ho ucciso...?"
  },
  AvgDialog_35996_Content_9 = {
    Text = "Perché... non hai accettato tutti i \"24\"."
  },
  AvgDialog_35996_Content_90 = {
    Text = "Mason si riscosse dal suo torpore e lasciò frettolosamente la scena."
  },
  AvgDialog_35996_Content_91 = {
    Text = "Il corpo dell'uomo era accasciato contro il muro. La sua testa era già in frantumi e il sangue continuava a fuoriuscire."
  },
  AvgDialog_35996_Content_92 = {
    Text = "Dopo un tempo imprecisato, una serie di segni maledetti neri si illuminarono improvvisamente sul collo del cadavere."
  },
  AvgDialog_35996_Content_93 = {
    Text = "I legami della maledizione ruotano lentamente come serpenti, e la carne ridotta in poltiglia inizia a convergere e a ricomporsi..."
  },
  AvgDialog_35996_Content_94 = {
    Text = "Alla fine, il \"cadavere\" si sollevò lentamente a sedere."
  },
  AvgDialog_35996_Content_95 = {
    Text = "Phew... Niente male, quelle tinture hanno funzionato. Il suo potenziale è stato completamente liberato."
  },
  AvgDialog_35996_Content_96 = {
    Text = "Albino estese la sua lunga lingua da serpente e si leccò pigramente il sangue dal viso, pulendolo del tutto."
  },
  AvgDialog_35996_Content_97 = {
    Text = "La preda è maturata. È ora di riferire al nostro Maestro della Gilda."
  },
  AvgDialog_35996_Content_98 = {
    Text = "Raccolse la cartella clinica ai suoi piedi e se ne andò con passo tranquillo."
  },
  AvgDialog_35997_Content_1 = {
    Text = "Il Gatto Sa Tutto"
  },
  AvgDialog_35997_Content_10 = {
    Text = "Tsk, Brown e io siamo più che sufficienti per occuparci di voi marmocchi."
  },
  AvgDialog_35997_Content_11 = {
    Text = "Cosa hai detto?!"
  },
  AvgDialog_35997_Content_12 = {
    Text = "Il piccolo Mac agitò la mano, e i bambini indisciplinati si zittirono immediatamente."
  },
  AvgDialog_35997_Content_13 = {
    Text = "Conosci le regole, vero? Se perdi contro di noi, devi cedere il controllo di Camberwell Street."
  },
  AvgDialog_35997_Content_14 = {
    Text = "—Per sempre."
  },
  AvgDialog_35997_Content_15 = {
    Text = "Smettila di tergiversare! Se vuoi combattere, fatti avanti!"
  },
  AvgDialog_35997_Content_16 = {
    Text = "Squeak! Squeak! Squeak!"
  },
  AvgDialog_35997_Content_17 = {
    Text = "Molto bene, dichiaro ufficialmente che la 13ª \"Battaglia di Camberwell\" ha ora inizio.\nFratelli—"
  },
  AvgDialog_35997_Content_18 = {
    Text = "<Big:Carica!!>"
  },
  AvgDialog_35997_Content_2 = {
    Text = "Dominio Artificiale: Camberwell Street, Distretto Est"
  },
  AvgDialog_35997_Content_20 = {
    Text = "Ahi! Ahi... Sono troppi..."
  },
  AvgDialog_35997_Content_21 = {
    Text = "<Shake:Scricch...>"
  },
  AvgDialog_35997_Content_22 = {
    Text = "Hmph! Questo è quello che vi meritate per aver seminato guai ovunque. Ora sapete quanto siamo forti!"
  },
  AvgDialog_35997_Content_23 = {
    Text = "Avanti tutti! La vittoria è a portata di mano—"
  },
  AvgDialog_35997_Content_24 = {Text = "Miao~"},
  AvgDialog_35997_Content_25 = {
    Text = "Un grido arrabbiato con una punta di infantilità interruppe la piccola scaramuccia davanti a loro."
  },
  AvgDialog_35997_Content_26 = {
    Text = "Non fate del male a Jenkin!"
  },
  AvgDialog_35997_Content_27 = {
    Text = "Gatto... persona-gatto? No, è Sorella Mason?!"
  },
  AvgDialog_35997_Content_29 = {
    Text = "Prima che potesse reagire, tre graffi rossi apparvero sul viso del piccolo Mike."
  },
  AvgDialog_35997_Content_3 = {
    Text = "Un vento freddo e desolato soffia, sollevando le foglie secche."
  },
  AvgDialog_35997_Content_30 = {Text = "..."},
  AvgDialog_35997_Content_31 = {
    Text = "<BigShake:Buaaahhhh!!>"
  },
  AvgDialog_35997_Content_32 = {
    Text = "I bambini si dispersero in tutte le direzioni. Le urla assordanti riecheggiarono fino agli angoli più nascosti dei vicoli."
  },
  AvgDialog_35997_Content_33 = {
    Text = "Non mi sarei mai aspettato di vedere un 24 simile a un gatto... Signorina Mason, usciamo a dare un'occhiata?"
  },
  AvgDialog_35997_Content_34 = {
    Text = "Nessuno rispose alla tua richiesta. Durante la recente scaramuccia, Mason era svanita senza lasciare traccia."
  },
  AvgDialog_35997_Content_35 = {
    Text = "Signorina Mason...? Andarsene senza nemmeno salutare?"
  },
  AvgDialog_35997_Content_36 = {Text = "Slurp."},
  AvgDialog_35997_Content_37 = {
    Text = "Una sensazione umida sfiora il lato del tuo viso."
  },
  AvgDialog_35997_Content_38 = {
    Text = "Ti giri incredulo, solo per vedere \"24\" aggrappato a te come un pupazzo gigante, rivolgendoti un sorriso adulatorio."
  },
  AvgDialog_35997_Content_39 = {
    Text = "Miao, miao?"
  },
  AvgDialog_35997_Content_4 = {
    Text = "Il piccolo Mike stava in piedi alla fine del vicolo con un gruppo di bambini. Con le mani sui fianchi, la sua espressione era estremamente seria."
  },
  AvgDialog_35997_Content_40 = {Text = "...?"},
  AvgDialog_35997_Content_41 = {
    Text = "Sniff sniff... C'è un topo, miao!"
  },
  AvgDialog_35997_Content_43 = {Text = "Squiiit@3!"},
  AvgDialog_35997_Content_44 = {
    Text = "Un urlo agghiacciante squarcia il cielo. Abbassi lo sguardo e vedi \"24\" che tiene Brown in bocca."
  },
  AvgDialog_35997_Content_45 = {
    Text = "<BigShake:Squit Squit Squit Auuuu!>"
  },
  AvgDialog_35997_Content_46 = {
    Text = "Brown agitava vigorosamente il suo corpo morbido, con i baffi che fremevano rapidamente."
  },
  AvgDialog_35997_Content_47 = {Text = "..."},
  AvgDialog_35997_Content_48 = {
    Text = "Presto, presto! Guarda, cos'è quello?"
  },
  AvgDialog_35997_Content_49 = {
    Text = "Jenkin raccolse abilmente un frammento di specchio da terra e lo riflesse verso il muro opposto."
  },
  AvgDialog_35997_Content_5 = {
    Text = "Tap. Tap. Tap."
  },
  AvgDialog_35997_Content_50 = {
    Text = "In un istante, intensi punti di luce tremolanti apparvero sul muro di pietra, catturando con successo l'attenzione di \"24\"."
  },
  AvgDialog_35997_Content_51 = {
    Text = "Miao lucente!"
  },
  AvgDialog_35997_Content_52 = {
    Text = "\"24\" schizzò via con un fruscio, lasciando Brown a singhiozzare inconsolabilmente sul posto."
  },
  AvgDialog_35997_Content_53 = {
    Text = "Sniff... Squiii..."
  },
  AvgDialog_35997_Content_54 = {
    Text = "*sigh* Da quando abbiamo consultato quel ciarlatano, le condizioni di mia sorella sono peggiorate."
  },
  AvgDialog_35997_Content_55 = {
    Text = "Ciarlatano? Intendi il Dottore Bernard?"
  },
  AvgDialog_35997_Content_56 = {
    Text = "Chi altri potrebbe essere? \"Dottore dei miracoli\" o \"Salvatore dei poveri del lato est\"? Bah!"
  },
  AvgDialog_35997_Content_57 = {
    Text = "Nessuno fa niente per niente. Scommetto che ha secondi fini..."
  },
  AvgDialog_35997_Content_58 = {
    Text = "Il Dott. Bernard è una brava persona, miao!"
  },
  AvgDialog_35997_Content_59 = {
    Text = "Mentre inseguiva il puntino di luce, \"24\" improvvisamente spuntò da dietro Jenkin."
  },
  AvgDialog_35997_Content_6 = {
    Text = "La ragazza avanzava con passo sicuro, il vento sollevava il suo mantello logoro."
  },
  AvgDialog_35997_Content_60 = {
    Text = "Va bene, va bene, è davvero bravo. È il miglior dottore del mondo."
  },
  AvgDialog_35997_Content_61 = {
    Text = "Jenkin lisciò abilmente i capelli di \"24\".\n\"24\" socchiuse gli occhi, con un'aria piuttosto soddisfatta."
  },
  AvgDialog_35997_Content_62 = {
    Text = "Anche il piccolo Jenkin è una brava persona, miao."
  },
  AvgDialog_35997_Content_63 = {
    Text = "Quando ha iniziato la signorina Mason a manifestare questi... sintomi peculiari?"
  },
  AvgDialog_35997_Content_64 = {
    Text = "Dopo aver visto quel ciarlatano tre o quattro volte, un giorno mi ha detto all'improvviso che in realtà era un merluzzo argentato."
  },
  AvgDialog_35997_Content_65 = {
    Text = "In seguito, ha escogitato un piano per distruggere la friggitoria di pesce, sostenendo che fosse per salvare i suoi compagni."
  },
  AvgDialog_35997_Content_66 = {
    Text = "<Gray:Capisco. Ho riposto troppa fiducia nel Comitato e ho trascurato le reali qualifiche del Dottore.>"
  },
  AvgDialog_35997_Content_67 = {
    Text = "<Gray:Potrebbe essere un lacchè dell'Associazione degli Scultori, come il Dott. Miller...>"
  },
  AvgDialog_35997_Content_68 = {
    Text = "Che sonno, awoo..."
  },
  AvgDialog_35997_Content_69 = {
    Text = "\"24\" si stiracchiò, facendo un lungo e pigro allungamento, poi si appoggiò naturalmente sulla spalla di Jenkin."
  },
  AvgDialog_35997_Content_7 = {
    Text = "Sei arrivata, come promesso. Da sola?"
  },
  AvgDialog_35997_Content_70 = {
    Text = "Glu, glu..."
  },
  AvgDialog_35997_Content_71 = {
    Text = "Si è addormentata."
  },
  AvgDialog_35997_Content_72 = {
    Text = "Fa davvero le fusa come un gatto... proprio come quei gatti nel campus di Mythag."
  },
  AvgDialog_35997_Content_73 = {
    Text = "Ti accovacci curiosamente davanti a \"24\"."
  },
  AvgDialog_35997_Content_74 = {
    Text = "La luce del sole le bagnava uniformemente il viso, tingendo d'oro la sottile peluria."
  },
  AvgDialog_35997_Content_75 = {
    Text = "Ehi, cosa ti fa ridere!"
  },
  AvgDialog_35997_Content_76 = {
    Text = "Ora sembra felice, davvero come una gattina spensierata."
  },
  AvgDialog_35997_Content_77 = {Text = "..."},
  AvgDialog_35997_Content_78 = {
    Text = "Mia sorella diceva sempre che la vita era troppo dura. Se avesse potuto reincarnarsi, avrebbe voluto diventare un gatto."
  },
  AvgDialog_35997_Content_79 = {
    Text = "Jenkin tirò improvvisamente fuori dalla tasca un nastro rosso. Era il solito nastro di Mason, con un campanellino arrugginito appeso all'estremità."
  },
  AvgDialog_35997_Content_8 = {Text = "Squeak!"},
  AvgDialog_35997_Content_80 = {
    Text = "Non preoccuparti. Che sia un gatto o un merluzzo argentato, è sempre mia sorella."
  },
  AvgDialog_35997_Content_81 = {
    Text = "Però, per evitare che tu scappi via, devo legarti un campanellino."
  },
  AvgDialog_35997_Content_82 = {
    Text = "Jenkin legò delicatamente il nastro attorno al polso di \"24\".\n\"24\", ancora addormentata, arricciò appena il naso."
  },
  AvgDialog_35997_Content_83 = {
    Text = "Ecco, questo l'ho preso dal piccolo Mac e dalla sua banda. Assicurati di indossarlo bene."
  },
  AvgDialog_35997_Content_84 = {
    Text = "Il sole pomeridiano, come tempo che trabocca, scorre dolcemente oltre di voi. Jenkin contempla l'ombra screziata della casa tagliata dal sole e chiude piano gli occhi."
  },
  AvgDialog_35997_Content_85 = {
    Text = "Mia sorella è molto impegnata. Si prende cura di me e di Brown, fa più lavori contemporaneamente, come una macchina che non si guasta mai."
  },
  AvgDialog_35997_Content_86 = {
    Text = "Ora che questa macchina è crollata, finalmente tocca a me prendermene cura."
  },
  AvgDialog_35997_Content_87 = {
    Text = "Ha bisogno di me."
  },
  AvgDialog_35997_Content_9 = {
    Text = "Notevole, hai osato venire da sola. Sei un'avversaria degna."
  },
  AvgDialog_35999_Content_1 = {
    Text = "Vincolo Maledetto"
  },
  AvgDialog_35999_Content_10 = {
    Text = "Ricordo tutto..."
  },
  AvgDialog_35999_Content_2 = {
    Text = "I ricordi affluiscono insieme alla luce delle stelle."
  },
  AvgDialog_35999_Content_4 = {
    Text = "Quei ricordi, creati artificialmente e frantumati dalla violenza, irruppero nella mente di Mason per poi ritirarsi rapidamente come la marea."
  },
  AvgDialog_35999_Content_5 = {
    Text = "Fino alla fine, giunse ai piedi della montagna innevata, all'ingresso di una caverna buia come la pece."
  },
  AvgDialog_35999_Content_6 = {
    Text = "Segui il fiume che scorre sotto i tuoi piedi per raggiungere la tana della bestia addormentata."
  },
  AvgDialog_35999_Content_7 = {
    Text = "Tum-tum. Tum-tum."
  },
  AvgDialog_35999_Content_8 = {
    Text = "Era un battito cardiaco simile a quello di un vecchio orologio, il battito condiviso tra lei e la bestia."
  },
  AvgDialog_35999_Content_9 = {Text = "Capisco..."},
  AvgDialog_36227_Content_1 = {
    Text = "Il \"Falso Dio\" si libera completamente dalla Sua fragile eppure tenace madre. Murphy viene scaraventata dall'alto e infine si schianta pesantemente sul ponte."
  },
  AvgDialog_36227_Content_10 = {
    Text = "Un Nucleo d'Argento."
  },
  AvgDialog_36227_Content_11 = {
    Text = "Murphy non è morta, ma un Nucleo d'Argento si è già formato dentro di lei. Questo contraddice ciò che hai appreso a lezione."
  },
  AvgDialog_36227_Content_12 = {
    Text = "Ma non c'è tempo per pensare. Spinta da un impulso quasi istintivo, afferri la mano di Murphy."
  },
  AvgDialog_36227_Content_13 = {
    Text = "La Chiave d'Argento appesa al tuo petto emette un tintinnio tremante. Una luce argentea abbagliante esplode dalle vostre mani intrecciate, abbastanza intensa da illuminare ogni angolo, avvolgendo tutti."
  },
  AvgDialog_36227_Content_14 = {
    Text = "Il tempo diviene sconfinato nella luce, e le anime vengono ripetutamente compresse e ripiegate nel tempo infinito."
  },
  AvgDialog_36227_Content_15 = {
    Text = "In questo istante eterno, il dolore ti accompagna sempre, esortandoti a lasciar andare il Nucleo d'Argento che ti trafigge il palmo."
  },
  AvgDialog_36227_Content_16 = {
    Text = "—Rifiuti. Il dolore lancinante invade senza pietà la tua coscienza, frantumando i tessuti all'interno del tuo cranio. Sangue rappreso in grumi sgorga dalla bocca, dal naso e dalle orecchie."
  },
  AvgDialog_36227_Content_17 = {
    Text = "Stringi forte l'anima di Murphy."
  },
  AvgDialog_36227_Content_18 = {
    Text = "La luce collassa verso l'origine, e l'inquietante suono di flauto che induce sonnolenza riemerge, catturando con forza la tua attenzione."
  },
  AvgDialog_36227_Content_19 = {
    Text = "Senti la mano svuotarsi."
  },
  AvgDialog_36227_Content_2 = {
    Text = "Tutte le sue ossa si frantumano all'impatto, la cavità toracica è squarciata da lei stessa, e ulteriormente distrutta dal \"Falso Dio\" che emerge."
  },
  AvgDialog_36227_Content_20 = {
    Text = "Dopo che la luce argentea svanisce, il ponte davanti a te è vuoto, e restano solo schizzi di sangue."
  },
  AvgDialog_36227_Content_21 = {Text = "Custode!?"},
  AvgDialog_36227_Content_22 = {
    Text = "Ramona trema mentre asciuga il sangue che cola dall'angolo del tuo occhio, ma non fa che spalmarlo, lasciandoti il volto coperto di schizzi di sangue."
  },
  AvgDialog_36227_Content_23 = {Text = "Murphy..."},
  AvgDialog_36227_Content_24 = {
    Text = "Lo shock e le domande di Ramona stanno appena prendendo forma quando un suono grave proviene dalla prua, simile al mormorio di una creatura dell'Abisso nel dormiveglia, carico di un'atmosfera minacciosa."
  },
  AvgDialog_36227_Content_25 = {
    Text = "Entrambi volgete istintivamente lo sguardo e vedete l'entità chiamata \"Miryam\" fissare il Dio con devozione quasi fanatica. È inginocchiata a prua della nave, le braccia protese verso il falso dio."
  },
  AvgDialog_36227_Content_26 = {
    Text = "E quelle innumerevoli mani nere le aprono il loro abbraccio. Le cingono delicatamente la vita, sollevando la devota seguace verso le loro bocche."
  },
  AvgDialog_36227_Content_27 = {
    Text = "—<Red:SNAP>."
  },
  AvgDialog_36227_Content_28 = {
    Text = "L'istante successivo, i suoni del masticare e del deglutire si levano in successione."
  },
  AvgDialog_36227_Content_29 = {
    Text = "Come se si fosse finalmente liberato da qualche sconosciuto confine di terrore, il neonato emette un suono soddisfatto, simile a un ronzio, come se stesse digerendo il raro banchetto di \"Miryam\"."
  },
  AvgDialog_36227_Content_3 = {
    Text = "Le onde si infrangono incessantemente sul ponte, lavando via le pozze di sangue sotto di lei, come a voler cancellare completamente ogni traccia della sua esistenza."
  },
  AvgDialog_36227_Content_30 = {
    Text = "Il \"Neonato\" nel bozzolo nero traslucido somiglia a un grande e fragile embrione di primate. I suoi arti si contraggono goffamente, come cercando una direzione in cui crescere—"
  },
  AvgDialog_36227_Content_31 = {
    Text = [[
Tempo all'Allineamento: 
<Red:0> minuti]]
  },
  AvgDialog_36227_Content_4 = {
    Text = "Questo tipo di ferita... non siamo in grado di gestirla."
  },
  AvgDialog_36227_Content_5 = {
    Text = [[
Il labbro inferiore di Murphy trema ancora, ma i suoi occhi hanno iniziato a perdere messa a fuoco.

Incapace di sopportare la vista di questa scena tragica, Ramona stringe i denti e alza lo sguardo verso il "Falso Dio".]]
  },
  AvgDialog_36227_Content_6 = {
    Text = "Basta. Se un nucleo del Cataclisma così massiccio non viene neutralizzato sulla nave e raggiunge la terraferma... le conseguenze saranno inimmaginabili."
  },
  AvgDialog_36227_Content_7 = {
    Text = "Custode, è ora di agire. Per il bene di Murphy."
  },
  AvgDialog_36227_Content_8 = {
    Text = "Aspettate un momento! Potrei avere una soluzione."
  },
  AvgDialog_36227_Content_9 = {
    Text = "Fissi intensamente il tessuto straziato sotto le costole di Murphy. Vedi quella cosa."
  },
  AvgDialog_36276_Content_1 = {
    Text = "La parte esterna... non è la Sua vera forma?!"
  },
  AvgDialog_36276_Content_2 = {
    Text = "Questo è ciò che Miryam persegue. Ciò che brama è il \"Dio\" capace di portarle la rinascita del passato..."
  },
  AvgDialog_36276_Content_3 = {
    Text = "Non possiamo permetterci di abbassare la guardia adesso, nemmeno per un singolo istante!"
  },
  AvgDialog_36276_Content_4 = {
    Text = "Quella cosa orrenda è completamente sveglia... Lo sento."
  },
  AvgDialog_36277_Content_1 = {Text = "Custode!"},
  AvgDialog_36277_Content_2 = {
    Text = "Tulu! Finalmente sei qui."
  },
  AvgDialog_36277_Content_3 = {
    Text = "Occuparmi dei nemici di Elton ha richiesto del tempo... <Small:Aspetta, Murphy?>"
  },
  AvgDialog_36277_Content_4 = {
    Text = "Gli occhi di Tulu scivolano oltre il \"Sacro Infante\" e si posano infine su Murphy. Lei, ora una Risvegliatrice, ha i tentacoli sulla gonna che ondeggiano selvaggiamente nell'aria."
  },
  AvgDialog_36277_Content_5 = {
    Text = "......Il potere del Feto ha la stessa origine del mio, il che significa che è anche mio consanguineo. Sebbene non possa comandarlo direttamente, la mia Autorità Regale, venerata da decine di migliaia di sudditi Lemuriani, non ha eguali in alcuna divinità contraffatta."
  },
  AvgDialog_36277_Content_6 = {
    Text = "L'occasione si presenta una sola volta. Usa il mio potere di Re di Lemuria... e scatena la punizione divina su di Esso!"
  },
  AvgDialog_37962_Content_1 = {
    Text = "Prossimo test: Effetto Schermo - Rosso Continuo"
  },
  AvgDialog_37962_Content_10 = {
    Text = "Prossimo test: Effetto Schermo - Luce Stellare"
  },
  AvgDialog_37962_Content_14 = {Text = "Fine"},
  AvgDialog_37962_Content_15 = {
    Text = "Prossimo test: Effetti Schermo - Illuminazione"
  },
  AvgDialog_37962_Content_19 = {Text = "Fine"},
  AvgDialog_37962_Content_20 = {
    Text = "Prossimo test: Testo Scorrevole Tipo 9"
  },
  AvgDialog_37962_Content_21 = {
    Text = "Primavera, l'alba più propizia. La cima della montagna che gradualmente imbianca inizia a mostrare la luce, con nubi lilla che fluttuano dolcemente sopra.\nL'estate giunge di notte. Quando c'è la luna, non c'è bisogno di dire altro, e durante la notte buia senza luna, ci sono anche sciami di lucciole. Se piove, diventa ancora più suggestivo.\nL'autunno presenta il crepuscolo. Il tramonto risplende vicino al bordo della montagna, i corvi tornano ai loro nidi, volando in gruppi di tre, quattro o due, aggiungendo malinconia. A volte si può scorgere la sagoma di un piccolo stormo di oche selvatiche, che attraversano il cielo lontano, il che è altrettanto affascinante. Inoltre, dopo il tramonto, persistono ancora il suono del vento e il canto degli insetti.\nL'inverno presenta l'alba. Quando nevica, non c'è bisogno di dire altro; a volte la brina è spessa, anche senza neve o brina, l'aria fredda è pungente abbastanza da accendere un braciere e portare carboni attraverso il corridoio, il che sembra piuttosto appropriato; è solo un peccato che a mezzogiorno i carboni nel braciere si coprano di cenere, lasciando poco da apprezzare."
  },
  AvgDialog_37962_Content_22 = {Text = "Fine"},
  AvgDialog_37962_Content_5 = {Text = "Fine"},
  AvgDialog_37962_Content_6 = {
    Text = "Prossimo test: Effetto zoom sull'illustrazione del personaggio"
  },
  AvgDialog_37962_Content_7 = {
    Text = "Ingrandisci illustrazione (1.5, 0.3)"
  },
  AvgDialog_37962_Content_8 = {
    Text = "Ingrandimento e Ripristino Illustrazione Personaggio"
  },
  AvgDialog_37962_Content_9 = {
    Text = "Test completato, cip~"
  },
  AvgDialog_38725_Content_1 = {
    Text = "Un tenue bagliore blu ti avvolge, dissipando ogni fatica e dolore."
  },
  AvgDialog_38725_Content_2 = {
    Text = "Il Padre Dio ti conferisce \"La benedizione\"."
  },
  AvgDialog_38725_Content_3 = {
    Text = "Vescovo Salvador!"
  },
  AvgDialog_38725_Content_4 = {
    Text = "Tu sei il messaggero pallido, la fiamma che dissolve l'oscurità."
  },
  AvgDialog_38725_Content_5 = {
    Text = "Porrai fine a tutta questa sofferenza, e io ti fornirò tutto l'aiuto di cui avrai bisogno."
  },
  AvgDialog_38727_Content_1 = {
    Text = "Sigillo di Sangue"
  },
  AvgDialog_38727_Content_10 = {
    Text = "In effetti. Forse... forse si tratta di un culto?"
  },
  AvgDialog_38727_Content_11 = {
    Text = "Scene balenano nella tua mente — una bambina con un pugnale, una donna con un velo nero, e una stanza nel profondo dell'Ospedale Rye che non potrà mai essere aperta..."
  },
  AvgDialog_38727_Content_12 = {
    Text = "Quante organizzazioni come quella dei <Yellow:Navigatori> e della <Yellow:Chiesa dei Portatori di Luce> esistono in questo mondo, e quante altre persone diventeranno loro sacrifici?"
  },
  AvgDialog_38727_Content_13 = {
    Text = [[
Eccellenza, Edward vi ha mai accennato qualcosa?
Che si tratti di altre religioni, credenze antiche, o persino leggende popolari?]]
  },
  AvgDialog_38727_Content_14 = {
    Text = "Salvador posa il fazzoletto, voltandosi verso di voi. Nonostante i suoi occhi siano coperti da una garza nera, riuscite ancora a percepire il suo sguardo penetrante."
  },
  AvgDialog_38727_Content_15 = {
    Text = "Se così fosse... Intendete indagare sulla questione?"
  },
  AvgDialog_38727_Content_16 = {
    Text = "Sì. Io... ho avuto contatti con organizzazioni simili, so quanto possano essere pericolose.\nPreferirei non vedere altre vittime in casi come questi."
  },
  AvgDialog_38727_Content_17 = {
    Text = [[
Avete un'anima luminosa, %player%, calda, forte... ammirevole.
Possa la luce del Padre risplendere su di voi, come risplende su tutti i membri di <Yellow:Mythag>.]]
  },
  AvgDialog_38727_Content_18 = {
    Text = "Come avete—"
  },
  AvgDialog_38727_Content_19 = {
    Text = "Il precedente vescovo era un mio amico. Ha amministrato la Chiesa per decenni. Conosceva moltissime cose."
  },
  AvgDialog_38727_Content_2 = {
    Text = "La porta di legno si chiude lentamente alle tue spalle, escludendo le grida dei mercanti e il clamore della folla indaffarata. Non puoi fare a meno di respirare il conforto del silenzio."
  },
  AvgDialog_38727_Content_20 = {
    Text = "Farò del mio meglio per assistere, ma temo di sapere ben poco d'altro."
  },
  AvgDialog_38727_Content_21 = {
    Text = "...A pensarci bene, Edward non è stato la prima vittima di questo genere di... culto."
  },
  AvgDialog_38727_Content_22 = {
    Text = "Sei mesi fa, un giovane uomo di nome Philip nel Quartiere della Chiesa fu condannato a morte per l'omicidio della moglie."
  },
  AvgDialog_38727_Content_23 = {
    Text = [[
Quando fu imprigionato, lo visitai su invito del guardiano.
Era pallido, estremamente emaciato, e rifiutava di comunicare con chiunque.]]
  },
  AvgDialog_38727_Content_24 = {
    Text = "Rimasi seduto con lui tutto il giorno, e mentre me ne andavo, pronunciò le uniche parole che avesse detto quel giorno."
  },
  AvgDialog_38727_Content_25 = {
    Text = "\"Vedete tutto questo <Red:sangue> nero?\""
  },
  AvgDialog_38727_Content_26 = {
    Text = "Prima che la sua esecuzione avesse luogo, si tolse la vita."
  },
  AvgDialog_38727_Content_27 = {
    Text = "L'intera stanza era ricoperta di sangue — sul pavimento, sulle pareti e sul soffitto. Il solo starvi in piedi bastava a sentirsi soffocare da quell'orrore. Eppure, sotto tutti quegli atroci schizzi di sangue, scoprii uno strano simbolo."
  },
  AvgDialog_38727_Content_28 = {
    Text = "Superficiale e piccolo, come se fosse stato graffiato da una semplice unghia. Se non fosse stato per il sangue che filtrava nella fessura, forse non l'avrei nemmeno notato."
  },
  AvgDialog_38727_Content_29 = {
    Text = "Accanto al simbolo, c'era un segno ancora più tenue."
  },
  AvgDialog_38727_Content_3 = {
    Text = "Eccellenza, l'acqua che avevate richiesto."
  },
  AvgDialog_38727_Content_30 = {
    Text = "Il segno era storto, come se fosse stato inciso da qualcuno che aveva perso ogni forza o era ebbro nel delirium della follia. Guidato dal Padre, lo riconobbi — era in effetti una parola."
  },
  AvgDialog_38727_Content_31 = {
    Text = "<Red:Purificazione.>"
  },
  AvgDialog_38727_Content_32 = {
    Text = "Quel culto che ipotizzate è cauto e straordinariamente abile nel celarsi. Se Edward non avesse menzionato la \"purificazione\" durante quell'incidente, non avrei saputo che era caduto nelle loro grinfie."
  },
  AvgDialog_38727_Content_33 = {
    Text = "Ricordate per caso che aspetto avesse quel simbolo? Mythag potrebbe avere degli archivi che potrebbero rivelarsi utili."
  },
  AvgDialog_38727_Content_34 = {
    Text = "Certamente. Prego, porgete la mano."
  },
  AvgDialog_38727_Content_35 = {
    Text = "Egli protende un dito, tracciando lievemente un semplice simbolo sul palmo della vostra mano."
  },
  AvgDialog_38727_Content_36 = {Text = "Questo...!"},
  AvgDialog_38727_Content_37 = {
    Text = "Estraete in fretta il taccuino dalla tasca, copiando frettolosamente il disegno tracciato da Salvador."
  },
  AvgDialog_38727_Content_38 = {
    Text = "Mio Signore, cosa succede? Cosa sono quei simboli?"
  },
  AvgDialog_38727_Content_39 = {
    Text = "Un triangolo rovesciato, un punto al centro—"
  },
  AvgDialog_38727_Content_4 = {
    Text = "Grazie, Ogier."
  },
  AvgDialog_38727_Content_40 = {
    Text = "Questo... Questo è il simbolo della Chiesa dei Portatori di Luce..."
  },
  AvgDialog_38727_Content_41 = {Text = "Bang!"},
  AvgDialog_38727_Content_42 = {
    Text = "All'improvviso, la Porta della Chiesa viene spalancata con violenza. Sophia si aggrappa alla porta con forza, i capelli in disordine, ansimante. Sta in piedi, immersa nella luce del sole che filtra dall'esterno, eppure le sue grida risuonano forti e chiare."
  },
  AvgDialog_38727_Content_43 = {
    Text = "Vescovo Salvador, qualcosa non va! La gente fuori—"
  },
  AvgDialog_38727_Content_44 = {
    Text = "Non bloccate il passaggio, fateci entrare!"
  },
  AvgDialog_38727_Content_45 = {
    Text = "Una Mano spinge Sophia di lato, riempiendo la Chiesa, un tempo pacifica, di grida laceranti e imprecazioni."
  },
  AvgDialog_38727_Content_46 = {
    Text = "Più di una dozzina di Cittadini irrompe all'interno, alcuni armati di scope, altri con mattarelli. Uno di loro agita il pugno, che reca ancora i segni del Morso di Edward."
  },
  AvgDialog_38727_Content_47 = {
    Text = "Tirate fuori quel farabutto di Edward! Abbiamo un conto in sospeso con lui!"
  },
  AvgDialog_38727_Content_5 = {
    Text = "Salvador estrae dalla tasca un fazzoletto pulito e lo inumidisce nel secchio d'acqua, iniziando a detergere con cura la polvere dalla pelle danneggiata di Edward."
  },
  AvgDialog_38727_Content_6 = {
    Text = "Un panno leggermente umido gli sfiora il petto, attirando il tuo sguardo sulle costole fin troppo visibili — è terribilmente magro, come se fosse appena sopravvissuto a una grande carestia."
  },
  AvgDialog_38727_Content_7 = {
    Text = "<Small:...Peccaminoso... sangue... purificazione...>"
  },
  AvgDialog_38727_Content_8 = {
    Text = "Sangue, peccato... Sebbene tu non abbia familiarità con le <Blue:\"Sacre Scritture\"> della <Blue:Cattedrale della Vita>, questi concetti sanguinari non sembrano corrispondere alle tue prime impressioni su questa religione."
  },
  AvgDialog_38727_Content_9 = {
    Text = "Questo \"Rifugio degli Innocenti\" e la \"Purificazione\"... non sembrano provenire dalla \"Scrittura Divina\"?"
  },
  AvgDialog_38729_Content_1 = {
    Text = "Speranza Bianca Accesa"
  },
  AvgDialog_38729_Content_10 = {
    Text = "Vi prego, alleviate il loro dolore e lenite i loro cuori."
  },
  AvgDialog_38729_Content_100 = {
    Text = "Concedere il perdono al peccatore, elargire \"La benedizione\"... Dopo tutti questi anni, non sei davvero cambiato per nulla, Vescovo Salvador."
  },
  AvgDialog_38729_Content_101 = {
    Text = "Il rogo non può cambiarti, né la resurrezione. Quando vedrai finalmente la realtà? Forse—"
  },
  AvgDialog_38729_Content_102 = {
    Text = "Protende la mano nell'aria, come se toccasse qualcosa di invisibile."
  },
  AvgDialog_38729_Content_103 = {
    Text = "Il <Yellow:Custode> dall'anima pallida ma calda di cui parla la profezia può introdurre più variabili.\nPensi che {Male=he,Female=she} sarebbe disposto/a a unirsi a noi?"
  },
  AvgDialog_38729_Content_104 = {
    Text = "Un cane gigante emerse dalle ombre accanto alla donna, i suoi arti contorti ricordavano vagamente la Sophia mutata. Sbuffa in risposta alle parole della donna."
  },
  AvgDialog_38729_Content_105 = {
    Text = "Beh, domani è sempre un nuovo giorno."
  },
  AvgDialog_38729_Content_106 = {
    Text = "Andiamo, cara. Se ne avremo l'occasione, li incontreremo di nuovo."
  },
  AvgDialog_38729_Content_11 = {
    Text = "Gli occhi della gente si fanno vacui, i corpi si rilassano. Il panico e il terrore si dissolvono, sostituiti da calma e tranquillità."
  },
  AvgDialog_38729_Content_12 = {
    Text = "Liberali dal tormento della sofferenza. Concedi loro \"La benedizione\"."
  },
  AvgDialog_38729_Content_13 = {
    Text = "La luce di marea si propaga verso l'esterno, e tutti chiudono gli occhi, come immersi nella quiete."
  },
  AvgDialog_38729_Content_14 = {
    Text = "Il sole tiepido sovrasta ogni cosa. Tutto sembra perfettamente normale, se non fosse per la piazza caotica che reca testimonianza della recente follia."
  },
  AvgDialog_38729_Content_15 = {
    Text = [[
La tavola scatta dolcemente, dissolvendosi nelle ombre invisibili della notte.
Salvador si sistema i vestiti e si avvicina a Sophia.]]
  },
  AvgDialog_38729_Content_16 = {
    Text = "...Non avresti dovuto salvarmi."
  },
  AvgDialog_38729_Content_17 = {
    Text = "\"Tutti coloro che ritrovano la via del ritorno possono tornare al mio abbraccio.\""
  },
  AvgDialog_38729_Content_18 = {
    Text = "\"Perché siete tutti miei fanciulli, e vi amo tutti.\"\nMa ti sbagli, Vescovo, e così la \"Scrittura Divina\"."
  },
  AvgDialog_38729_Content_19 = {
    Text = "Certe persone non cambiano mai."
  },
  AvgDialog_38729_Content_2 = {
    Text = "La tavoletta si solleva ancora una volta."
  },
  AvgDialog_38729_Content_20 = {
    Text = "Cosa ti porta qui?"
  },
  AvgDialog_38729_Content_21 = {
    Text = "Sophia, io—"
  },
  AvgDialog_38729_Content_22 = {
    Text = "Taci! Non ti basta aver causato la morte di mia sorella e di mia madre? Ora vieni sulle loro tombe a gongolare?!"
  },
  AvgDialog_38729_Content_23 = {
    Text = "Sono qui per scusarmi. Non mi aspettavo..."
  },
  AvgDialog_38729_Content_24 = {
    Text = "Sophia rise in modo tagliente."
  },
  AvgDialog_38729_Content_25 = {
    Text = "Ti sei scusato così con <Blue:Thompson> dopo aver causato la morte del suo unico familiare e di <Blue:Millie>?"
  },
  AvgDialog_38729_Content_26 = {
    Text = "Mi fai venire la nausea, Edward Bailey."
  },
  AvgDialog_38729_Content_27 = {
    Text = "Mi pento davvero di ciò che ho fatto, Sophia. So di non poter ottenere il tuo perdono—"
  },
  AvgDialog_38729_Content_28 = {
    Text = "Se te ne penti davvero, non saresti dovuto andare a trovare il Vescovo Salvador il giorno in cui Thompson ti ha ucciso."
  },
  AvgDialog_38729_Content_29 = {
    Text = "Sì, so come sei sopravvissuto, codardo. <Yellow:Il Portatore di Luce> me l'ha detto."
  },
  AvgDialog_38729_Content_30 = {
    Text = "La decisione del Vescovo di concederti \"<Yellow:La benedizione>\" è stato il suo errore più stolto. Meriti di morire, Bailey, con una tortura crudele e brutale."
  },
  AvgDialog_38729_Content_31 = {
    Text = "Nemmeno io volevo tutto questo. Ho cercato di controllarmi, davvero! Dopo che il Vescovo mi ha salvato, mi presentavo alla Chiesa ogni giorno e facevo volontariato alla vostra opera di carità ogni settimana. Te lo ricordi?"
  },
  AvgDialog_38729_Content_32 = {
    Text = "Voglio migliorare, davvero. È stato quel tizio, Aglo — ha detto che era un affare sicuro e mi ha chiesto di presentare un garante. Sono una vittima anch'io!"
  },
  AvgDialog_38729_Content_33 = {
    Text = "Anche adesso, continui a sfuggire alle tue responsabilità. Anche adesso... non ti sei davvero pentito."
  },
  AvgDialog_38729_Content_34 = {
    Text = "Estrae dalla tasca interna della gonna un oggetto argenteo. La sua superficie liscia brillava debolmente alla luce del sole, proiettando un bagliore rossastro minaccioso."
  },
  AvgDialog_38729_Content_35 = {Text = "Sophia...?"},
  AvgDialog_38729_Content_36 = {Text = "Pentiti."},
  AvgDialog_38729_Content_37 = {
    Text = [[
Segui gli insegnamenti del giusto Portatore di Luce, e purifica i peccati nella tua anima.
Solo allora potrai ottenere il perdono.]]
  },
  AvgDialog_38729_Content_38 = {Text = "Cosa sei?"},
  AvgDialog_38729_Content_39 = {
    Text = "Io... Io sono Edward..."
  },
  AvgDialog_38729_Content_4 = {
    Text = "Nel mezzo della folla brulicante, Salvador alza la mano, il flusso incessante di sangue dal suo corpo scorre sulle tavolette davanti a lui. Una luce azzurra percorre intricati disegni, luminosa e fioca, pulsando dolcemente."
  },
  AvgDialog_38729_Content_40 = {
    Text = [[
Lo specchio lampeggia, e gli occhi del giovane uomo inginocchiato si fanno nuovamente vacui.
Tremando, solleva il bastone nella sua mano e si colpisce con forza.]]
  },
  AvgDialog_38729_Content_41 = {
    Text = "Te lo chiedo ancora una volta: cosa sei?"
  },
  AvgDialog_38729_Content_42 = {
    Text = "Sono un peccatore."
  },
  AvgDialog_38729_Content_43 = {
    Text = "Quale peccato hai commesso?"
  },
  AvgDialog_38729_Content_44 = {
    Text = "Avidità... Desiderio... Ho permesso al male di contaminare la mia anima, e poi di infliggere dolore agli innocenti."
  },
  AvgDialog_38729_Content_45 = {
    Text = "Cosa dovresti fare?"
  },
  AvgDialog_38729_Content_46 = {
    Text = "Pentimento verso gli dèi e verso coloro a cui ho fatto del male...\nDevo Sopportare la frusta, sanguinare finché il nero peccato non defluisca, finché la <Red:Purificazione> non sia raggiunta."
  },
  AvgDialog_38729_Content_47 = {
    Text = "Il Giorno del Giudizio si avvicina. Solo le anime pure potranno entrare nel Rifugio degli Innocenti."
  },
  AvgDialog_38729_Content_48 = {
    Text = "<Red:Che la Lanterna resti accesa>."
  },
  AvgDialog_38729_Content_49 = {
    Text = "Proprio come te, anche dopo due vite, hai commesso gli stessi errori."
  },
  AvgDialog_38729_Content_5 = {
    Text = "Padre Supremo della Genesi, nostro misericordioso Creatore, ascolta la mia preghiera."
  },
  AvgDialog_38729_Content_50 = {
    Text = "...Come facevi a saperlo?"
  },
  AvgDialog_38729_Content_51 = {
    Text = "È importante?\nIl tuo peccato di arroganza è così profondo, Vescovo. La tua anima dev'essere del tutto lurida."
  },
  AvgDialog_38729_Content_52 = {
    Text = "Dimmi, peccatore, perché non ti penti dei peccati contro cui predichi?"
  },
  AvgDialog_38729_Content_53 = {
    Text = "...perché quello non è un crimine."
  },
  AvgDialog_38729_Content_54 = {
    Text = "Le Reliquie del Padre portano sempre la Sua luce. Chiunque può essere accecato, ma con altrettanta facilità, chiunque può riscoprire la luce del Padre."
  },
  AvgDialog_38729_Content_55 = {
    Text = "Non possiamo privare qualcuno dell'intera vita per l'azione di un singolo istante."
  },
  AvgDialog_38729_Content_56 = {
    Text = "Lo dici tu, ma hai mai pensato a coloro che ne sono stati feriti?"
  },
  AvgDialog_38729_Content_57 = {
    Text = "Quando quegli Edward ritrovano la luce, quante Millie devono essere sacrificate? Quante Olivia?"
  },
  AvgDialog_38729_Content_58 = {
    Text = "Il peccato è peccato, e il torto è torto. Una volta commesso, non si può più tornare indietro."
  },
  AvgDialog_38729_Content_59 = {
    Text = "Lei rivolge lo sguardo verso di te."
  },
  AvgDialog_38729_Content_6 = {
    Text = "Tenui filamenti azzurri si irradiano dalla tavoletta, attraversando la folla e dissipando la fragranza residua di sangue, lasciando un tenue profumo."
  },
  AvgDialog_38729_Content_60 = {
    Text = "Portatemi via, gettatemi nelle vostre leggi corrotte. Ma ricordate, il Giorno del Giudizio verrà."
  },
  AvgDialog_38729_Content_61 = {
    Text = "In quel momento, sarete tutti banditi dal Rifugio degli Innocenti."
  },
  AvgDialog_38729_Content_62 = {
    Text = "Il Riflesso è stato messo in sicurezza, Custode. I civili colpiti sono stati trasferiti negli ospedali maggiori e saranno dimessi dopo gli accertamenti."
  },
  AvgDialog_38729_Content_63 = {
    Text = "La versione ufficiale è che si è trattato di un evento di allucinazione collettiva causato da una fuga di gas tossico dalla fabbrica. Il governo cittadino emetterà domani delle scuse pubbliche e adotterà provvedimenti disciplinari nei confronti dei responsabili."
  },
  AvgDialog_38729_Content_64 = {
    Text = "Capisco. Grazie per il vostro duro lavoro."
  },
  AvgDialog_38729_Content_65 = {
    Text = "Questo è ciò che dovremmo fare."
  },
  AvgDialog_38729_Content_66 = {
    Text = "Il giovane in uniforme esita un istante, poi parla:"
  },
  AvgDialog_38729_Content_67 = {
    Text = "Come sei riuscito a farlo?"
  },
  AvgDialog_38729_Content_68 = {Text = "Cosa?"},
  AvgDialog_38729_Content_69 = {
    Text = "La situazione era così caotica, eppure con solo te e un Risvegliato, siete riusciti a limitare le vittime a una dozzina circa — quasi un miracolo."
  },
  AvgDialog_38729_Content_7 = {
    Text = "Le persone in piedi lentamente si sedettero."
  },
  AvgDialog_38729_Content_70 = {
    Text = "Tu e Ogier vi scambiate un rapido sguardo. Il giovane cavaliere tossisce leggermente con le mani dietro la schiena."
  },
  AvgDialog_38729_Content_71 = {
    Text = "Questa è probabilmente l'intesa tacita tra il mio signore e me."
  },
  AvgDialog_38729_Content_72 = {
    Text = [[
In ogni caso, porgo la mia gratitudine a voi a nome della Squadra di Prima Risposta del Comitato. 
Nel pieno della crisi, non avete abbandonato la nostra gente, permettendo loro di tornare a casa sani e salvi. Inoltre...]]
  },
  AvgDialog_38729_Content_73 = {
    Text = [[
Molti di noi sono cresciuti qui; il Quartiere della Chiesa significa molto per noi.
Grazie per tutto quello che avete fatto.]]
  },
  AvgDialog_38729_Content_74 = {
    Text = "È quello che dovremmo fare."
  },
  AvgDialog_38729_Content_75 = {
    Text = "La gratitudine non è mai troppa."
  },
  AvgDialog_38729_Content_76 = {
    Text = "Signorina Sophia... Che ne sarà di lei?"
  },
  AvgDialog_38729_Content_77 = {
    Text = "Interrogatela. Emetteremo il Giudizio su di lei dopo aver scoperto da dove proviene lo specchio."
  },
  AvgDialog_38729_Content_78 = {
    Text = "Il Rito eretico ha causato caos diffuso e numerose vittime... Il Vescovo spera che non venga condannata a morte, ma non sono ottimista."
  },
  AvgDialog_38729_Content_79 = {
    Text = "Ciò che la attende non sarà un esito favorevole."
  },
  AvgDialog_38729_Content_8 = {
    Text = "Coloro che sedevano lì, a bocca spalancata, fissavano attoniti la scena miracolosa dinanzi a loro."
  },
  AvgDialog_38729_Content_80 = {
    Text = "Vescovo Salvador."
  },
  AvgDialog_38729_Content_81 = {
    Text = "Ve ne andate?"
  },
  AvgDialog_38729_Content_82 = {
    Text = "Sì. Grazie per il vostro aiuto in questo evento."
  },
  AvgDialog_38729_Content_83 = {
    Text = "Tutto questo è iniziato per causa mia, e voi avete persino tenuto segreta la mia identità. Dovrei essere io a ringraziarvi."
  },
  AvgDialog_38729_Content_84 = {
    Text = "Davvero non tornerete con noi?"
  },
  AvgDialog_38729_Content_85 = {
    Text = "Non preoccupatevi per la parrocchia. Finché le condizioni lo permettono, consentiamo ai Risvegliati di agire liberamente."
  },
  AvgDialog_38729_Content_86 = {
    Text = "Vi ringrazio per la vostra gentilezza, ma preferisco restare qui."
  },
  AvgDialog_38729_Content_87 = {
    Text = "Padre Dio mi ha fatto risorgere qui, probabilmente sperando che potessi aiutare più persone.\nSe avete bisogno, <Yellow:Il Fuoco Pallido>, venite da me in qualsiasi momento. Vi darò tutto me stesso."
  },
  AvgDialog_38729_Content_88 = {
    Text = "Mi perdonate, ma... Cosa sono esattamente il <Yellow:Messaggero Pallido> e il <Yellow:Fuoco Pallido>?"
  },
  AvgDialog_38729_Content_89 = {
    Text = "È la Profezia del Padre nella Scrittura Divina."
  },
  AvgDialog_38729_Content_9 = {
    Text = "Coloro che avevano perso conoscenza, o persino cessato di respirare, aprirono lentamente gli occhi nella brezza gentile."
  },
  AvgDialog_38729_Content_90 = {
    Text = "Un'Oscurità sconfinata calerà sul mondo, l'Anima pallida e calda è l'emissaria della Speranza, {Male=egli,Female=ella} accenderà la fiamma bianca per illuminare il Sentiero da percorrere."
  },
  AvgDialog_38729_Content_91 = {
    Text = "Non posso essere io, vero? Ci sono così tante persone al mondo."
  },
  AvgDialog_38729_Content_92 = {
    Text = "Anche se i miei occhi sono coperti, non posso confondere lo splendore di un'anima.\nLa vostra è così calda e luminosa. In tutti questi anni, non ne ho mai vista un'altra simile."
  },
  AvgDialog_38729_Content_93 = {
    Text = "Il giovane Custode si volta e si allontana. Salvador osserva il Bagliore, sussurrando una Preghiera mentre la porta si apre per l'ultima volta."
  },
  AvgDialog_38729_Content_94 = {
    Text = "Possiate illuminare l'Oscurità con una flebile Speranza."
  },
  AvgDialog_38729_Content_95 = {
    Text = "<Yellow:Rapporto sugli eventi anomali nel Distretto della Chiesa di Londinium>\n\nA.F. 315 @2@3, Distretto della Grande Chiesa di Londinium, un'improvvisa esplosione di violenza si è verificata nella piazza antistante la Chiesa delle Eterne Benedizioni del Padre di Londinium. I cittadini presenti hanno manifestato gravi comportamenti violenti e autolesionistici, rendendo impossibile una comunicazione normale.\n...\nIl comportamento anomalo è peggiorato dopo il contatto con una fonte di luce sconosciuta, degenerando in atti di cannibalismo su larga scala. Le indagini hanno rivelato che la fonte di luce sconosciuta era in realtà uno specchio portatile in Argento puro lucidato. Questo specchio accumula energia riflettendo la luce solare e lunare. Gli individui esposti ai riflessi dello specchio vengono spinti dai loro desideri interiori più potenti, inclusi ma non limitati a: violenza, voracità e sonnolenza, portando ad azioni ancora più estreme.\nLo specchio è stato recuperato dal Custode %player% e dal Risvegliatore Ogier. L'analisi preliminare indica che contiene Argento o componenti simili all'Argento. Per ulteriori dettagli, si prega di consultare il rapporto speciale di ricerca sulle attrezzature fornito dal Dipartimento di Ricerca sulle Attrezzature Speciali dell'Università di Mythag.\n..."
  },
  AvgDialog_38729_Content_96 = {
    Text = "Sotto interrogatorio da parte del comitato del trattato di Mystia, <Yellow:Sophia Chastain> ha ammesso di essersi unita alla Chiesa della luce del tempio tre anni fa e di aver ottenuto uno specchio rituale dalla leader della chiesa, Luce del Tempio (ovvero <Yellow:la Sig.ra Eve>), durante l'ultima Messa.\nQuando l'agente l'ha interrogata ulteriormente, Sophia Chastain ha iniziato a pregare e non ha più risposto.\n..."
  },
  AvgDialog_38729_Content_97 = {
    Text = "Il sole al tramonto dissipa la foschia persistente nel cielo. La campana della chiesa rintocca, e il fischio della nave risuona al molo sul fiume."
  },
  AvgDialog_38729_Content_98 = {
    Text = "Sul tetto di un edificio alto, una figura ammantata se ne sta sola, di spalle al sole."
  },
  AvgDialog_38729_Content_99 = {
    Text = "Anche dopo aver sacrificato i peccatori mutati, nessuno <Red:Stigmata> è apparso.\nSembra che il valore di <Yellow:quello specchio> sia solo questo."
  },
  AvgDialog_38841_Content_1 = {Text = "Ugh!"},
  AvgDialog_38841_Content_10 = {
    Text = "Mio Signore!"
  },
  AvgDialog_38841_Content_12 = {
    Text = "Un istante dopo, una tavola gigante cade proprio davanti a te."
  },
  AvgDialog_38841_Content_13 = {
    Text = "Persone spinte dalla follia si avventano su di te, sangue ovunque, urla caotiche e strazianti... Tutto questo viene isolato dietro la tavola."
  },
  AvgDialog_38841_Content_14 = {
    Text = "Una mano rivestita da un guanto nero si posa sul tuo avambraccio, il tessuto fresco allevia il dolore e asciuga il sangue che scorre lungo il tuo braccio."
  },
  AvgDialog_38841_Content_15 = {
    Text = "La persona che ti ha morso è svanita. Accanto a te, stringendoti l'avambraccio, c'è un vescovo vestito con una veste nera."
  },
  AvgDialog_38841_Content_16 = {
    Text = "Quattro tavole di pietra fluttuano dietro di lui, ciascuna incisa con rune intricate che brillano di una luce blu fluente, come galassie in miniatura."
  },
  AvgDialog_38841_Content_17 = {
    Text = "Un filo di luce blu fluì dal suo braccio verso di te. Abbassasti lo sguardo, e il morso sul tuo avambraccio aveva smesso di sanguinare e si stava rimarginando davanti ai tuoi occhi."
  },
  AvgDialog_38841_Content_18 = {
    Text = "Vescovo... Salvador?"
  },
  AvgDialog_38841_Content_2 = {
    Text = "Denti smussati mordono i vestiti, tirando con ferocia. La persona, impazzita dalla fame, sta ora rosicchiando il tuo braccio con tutte le sue forze."
  },
  AvgDialog_38841_Content_3 = {
    Text = "Mio Signore!"
  },
  AvgDialog_38841_Content_4 = {
    Text = "Vedendo i tuoi movimenti limitati, le persone altrettanto affamate intorno a te rivolgono lo sguardo verso di te."
  },
  AvgDialog_38841_Content_5 = {
    Text = "Uccidili! Altrimenti continueranno a venire. Sbrigati e uccidili!"
  },
  AvgDialog_38841_Content_6 = {
    Text = "Coppie di occhi cremisi ti fissano, mani che si protendono, seguite da bocche spalancate con denti bianchi e affilati."
  },
  AvgDialog_38841_Content_7 = {
    Text = "L'urlo di Ogier si prolungò all'infinito."
  },
  AvgDialog_38841_Content_8 = {
    Text = "Senti il suono del tessuto che si strappa."
  },
  AvgDialog_38841_Content_9 = {
    Text = "Il calore colpisce di nuovo, seguito da una fitta acuta — sai che l'aggressore ha finalmente affondato i denti nella tua mano."
  },
  AvgDialog_38842_Content_1 = {
    Text = "Il Nostro Fallimento"
  },
  AvgDialog_38842_Content_10 = {
    Text = "M-Mio Signore..."
  },
  AvgDialog_38842_Content_11 = {
    Text = "Così rosso, perché è così rosso? Ovunque c'è un rosso profondo e opprimente che ti soffoca. Devi uscire da questa luce... devi andartene..."
  },
  AvgDialog_38842_Content_12 = {
    Text = "Fresco, poi l'incenso della Chiesa."
  },
  AvgDialog_38842_Content_13 = {
    Text = "Una luce blu illumina parte dell'oscurità. Spalanchi gli occhi e vedi Ogier inginocchiato davanti a te, un rivolo di liquido nero che gli cola dall'angolo della bocca."
  },
  AvgDialog_38842_Content_14 = {
    Text = "Esattamente come durante l'addestramento alla rottura delle catene con lui."
  },
  AvgDialog_38842_Content_15 = {Text = "Ogier!"},
  AvgDialog_38842_Content_16 = {
    Text = "Concentra la mente rapidamente; la Chiave d'Argento trema sul tuo petto. Dopo un breve lampo argenteo, Ogier si rialza."
  },
  AvgDialog_38842_Content_17 = {
    Text = "Purificare, <Big:Purificare!>"
  },
  AvgDialog_38842_Content_18 = {
    Text = "Lo specchio nella tua mano diventa sempre più luminoso. Proprio mentre stai per coprirti gli occhi, un'ombra cade davanti a te."
  },
  AvgDialog_38842_Content_19 = {
    Text = "Un'enorme tavola fluttua davanti a te. Rune complesse brillano debolmente di blu, più fioche di prima."
  },
  AvgDialog_38842_Content_2 = {
    Text = "La luna di sangue pende alta nel cielo, la sua luce cremisi funge da Catalizzatore più potente."
  },
  AvgDialog_38842_Content_20 = {
    Text = "Ti volti, solo per scoprire che Salvador non si vede da nessuna parte."
  },
  AvgDialog_38842_Content_21 = {
    Text = "Ogier, afferra quello specchio."
  },
  AvgDialog_38842_Content_22 = {
    Text = "Ma, mio signore, voi—"
  },
  AvgDialog_38842_Content_23 = {
    Text = "So badare a me stesso. Il Vescovo ci ha concesso poco tempo, sbrigati!"
  },
  AvgDialog_38842_Content_24 = {Text = "Sì!"},
  AvgDialog_38842_Content_3 = {
    Text = "Le risse degenerano in pestaggi brutali, l'autolesionismo sfocia nel suicidio, e coloro che cercano attivamente la morte pongono fine alle proprie vite in modi violenti e inimmaginabili."
  },
  AvgDialog_38842_Content_4 = {
    Text = "L'odore metallico del sangue sovrasta completamente il persistente aroma d'incenso. Sotto la luce rossa, il sangue sparso appare nero come inchiostro, e coloro spinti alla Follia sembrano rassomigliare a diavoli mostruosi visibili solo negli Incubi."
  },
  AvgDialog_38842_Content_5 = {
    Text = "In questo inferno sulla terra, solo il vestito di Sophia rimane pulito. Si asciuga il sangue schizzatole sul viso e scoppia a ridere."
  },
  AvgDialog_38842_Content_6 = {
    Text = "Scorrete, lasciate scorrere il male dentro i vostri corpi! Lasciate che il nero peccato fuoriesca!"
  },
  AvgDialog_38842_Content_7 = {
    Text = "Pentitevi, peccatori! Purificate le vostre anime immonde prima che il severo Portatore di Luce pronunci il Giudizio!"
  },
  AvgDialog_38842_Content_8 = {
    Text = "Mentre regge lo specchio, una luce cremisi guizza, penetrando e trafiggendo i tuoi occhi direttamente nella tua mente e nel tuo Spirito."
  },
  AvgDialog_38842_Content_9 = {
    Text = "Qualcosa continua a stringere sempre di più. Cos'è? È così sgradevole, così doloroso... Mi viene da vomitare."
  },
  AvgDialog_38843_Content_1 = {
    Text = "Purifica il Peccato"
  },
  AvgDialog_38843_Content_10 = {
    Text = "*Tosse, rantoli*, una pozza di liquido schizza al suolo.\nL'odore di sangue si fa ancora più intenso."
  },
  AvgDialog_38843_Content_11 = {
    Text = "Ora è morta... <Blue:Millie> è morta...! <Blue:Thompson> Quel pazzo vuole che la segua nella morte. Io... io non voglio morire, Vescovo, ma anche io..."
  },
  AvgDialog_38843_Content_12 = {
    Text = "Mi dispiace, mi dispiace... Perdonatemi, Vostra Grazia. Solo il Padre può perdonarmi, solo il Padre..."
  },
  AvgDialog_38843_Content_13 = {
    Text = "\"...Egli è disposto ad abbracciare coloro che hanno errato, purché si pentano sinceramente.\""
  },
  AvgDialog_38843_Content_14 = {
    Text = "Una tenue luce azzurra risplende verso l'alto, illuminando parti della vetrata. Il Padre Divino sulla finestra osserva in silenzio dall'alto, come ha fatto per secoli."
  },
  AvgDialog_38843_Content_15 = {
    Text = "Sotto la mano di Salvador, le ferite del giovane uomo guariscono rapidamente, come se non fosse mai stato ferito."
  },
  AvgDialog_38843_Content_16 = {
    Text = "Apri gli occhi, Edward, e abbi cara l'opportunità che il Padre ti ha concesso."
  },
  AvgDialog_38843_Content_17 = {
    Text = "Una luce blu si è insinuata su di te, cancellando ogni dolore e fatica.\nTi sei sentito più leggero, colmo di un'energia senza precedenti."
  },
  AvgDialog_38843_Content_18 = {
    Text = "Il Vescovo Salvador... è..."
  },
  AvgDialog_38843_Content_19 = {
    Text = "Le rune sulla tavola pulsavano ritmicamente come un respiro, con altra luce blu che si diffondeva in ogni direzione come le radici di un albero gigantesco. Innumerevoli ferite e morti, pianti e lamenti, furono alleviati da questo miracolo improvviso."
  },
  AvgDialog_38843_Content_2 = {
    Text = "Vescovo... Vescovo Salvador..."
  },
  AvgDialog_38843_Content_20 = {
    Text = "Il profumo dell'incenso della Chiesa ti sfiora lievemente il naso, tenue e sottile, quasi inesistente, eppure copre completamente l'odore del sangue."
  },
  AvgDialog_38843_Content_21 = {
    Text = "...un Risvegliato."
  },
  AvgDialog_38843_Content_22 = {
    Text = "Si contorce all'improvviso, aprendo la bocca per morderti la mano. Denti e alito caldo si avvicinano al tuo braccio, facendoti rizzare i peli. Ti irrigidisci, preparandoti al dolore."
  },
  AvgDialog_38843_Content_23 = {
    Text = "All'improvviso, una mano rivestita da un guanto nero copre il tuo braccio."
  },
  AvgDialog_38843_Content_24 = {
    Text = "Il tessuto fresco e il profumo calmante e rassicurante dell'incenso della Chiesa si diffondono."
  },
  AvgDialog_38843_Content_25 = {
    Text = "Mi hai guarito così anche quella volta?\nQuesta è... la tua Abilità?"
  },
  AvgDialog_38843_Content_26 = {
    Text = "Salvador ti guarda, il suo sguardo ancora gentile e persino compassionevole attraverso le bende bianche."
  },
  AvgDialog_38843_Content_27 = {
    Text = "Avete salvato quei peccatori ancora una volta."
  },
  AvgDialog_38843_Content_28 = {
    Text = "Una voce fredda interrompe le tue parole. Ti volti e, senza sorpresa, vedi la figura di Sophia."
  },
  AvgDialog_38843_Content_29 = {
    Text = "Sei stato dotato di una <Yellow:\"Benedizione\">, possiedi un potere che la gente comune non ha, eppure ti limiti ad assecondare queste anime peccatrici, permettendo loro di diffondere sofferenza."
  },
  AvgDialog_38843_Content_3 = {Text = "Edward?"},
  AvgDialog_38843_Content_30 = {
    Text = "Sei il più grande peccatore qui, Salvador. Giuro che ti farò affrontare i tuoi peccati."
  },
  AvgDialog_38843_Content_31 = {
    Text = "Signorina Sophia, di cosa state parlando?"
  },
  AvgDialog_38843_Content_32 = {
    Text = "Non hai ancora capito? Il vescovo che hai davanti, questo ipocrita che abusa del potere divino, nasconde la sua vera identità e salva ripetutamente quegli individui malvagi dall'orlo della morte."
  },
  AvgDialog_38843_Content_33 = {
    Text = "In nome della misericordia, ha dato loro occasione dopo occasione, facendo soffrire ripetutamente i giusti — non può continuare così."
  },
  AvgDialog_38843_Content_34 = {
    Text = "La <Yellow:Lanterna> mi ha guidata, e la <Yellow:Portatrice della Lanterna d'Argento Puro> mi ha affidato una missione, spingendomi a iniziare il processo della luce."
  },
  AvgDialog_38843_Content_35 = {
    Text = "Alzò la mano, puntando uno specchio portatile dalla forma strana verso il cielo notturno. La luce solare divenne cremisi nel momento in cui vi entrò."
  },
  AvgDialog_38843_Content_36 = {
    Text = "Oggi <Red:purificherò> il peccato e accoglierò un paradiso innocente."
  },
  AvgDialog_38843_Content_37 = {
    Text = "Il cielo si oscurò all'improvviso e il sole scomparve dalla vista. Nel frattempo, un fantasma rosso crebbe sempre di più.\nEra la luna — una luna enorme, rosso sangue."
  },
  AvgDialog_38843_Content_38 = {
    Text = "L'oscurità divorò l'intero cielo, e la luce lunare si riversò giù, tingendo tutto di un rosso accecante."
  },
  AvgDialog_38843_Content_39 = {
    Text = "Peccatori, squarciatevi le carni, lasciate che i vostri peccati defluiscano—"
  },
  AvgDialog_38843_Content_4 = {
    Text = "Il dolce profumo metallico si faceva più intenso a ogni passo. Salvador aveva da tempo abbandonato la sua visuale ordinaria, ma al risveglio poté nuovamente scorgere la luce gentile delle anime intorno a sé."
  },
  AvgDialog_38843_Content_40 = {
    Text = "Coloro che stavano combattendo tra loro volgono il capo verso l'ordine, incidendo la propria carne con lame e denti."
  },
  AvgDialog_38843_Content_41 = {
    Text = "Eliminate coloro che rifiutano di essere purificati!"
  },
  AvgDialog_38843_Content_43 = {
    Text = "Si voltano verso di te uno a uno, i loro occhi riflettono la luce della luna rossa."
  },
  AvgDialog_38843_Content_5 = {
    Text = "L'anima dinanzi a lui fluttua su e giù nell'oscurità, quasi del tutto spenta."
  },
  AvgDialog_38843_Content_6 = {
    Text = "Oh cielo, Edward! Appoggiati a me, ti porto all'ospedale!"
  },
  AvgDialog_38843_Content_7 = {
    Text = "No! Io... No. È opera mia."
  },
  AvgDialog_38843_Content_8 = {
    Text = "L'anima tremola ancora, facendosi sempre più fioca.\nIl suo tempo sta per scadere."
  },
  AvgDialog_38843_Content_9 = {
    Text = "Mi avevi avvertito di non prosperare sul dolore altrui, di non ingannare. Avrei dovuto cambiare, ma non ho mai ascoltato... *cough*!"
  },
  AvgDialog_38844_Content_1 = {
    Text = "Una lancia spazzò il terreno, colpendo il polpaccio del giovane. Il ragazzo, spinto alla follia, barcollò e cadde. Hai colto l'occasione per immobilizzarlo e bloccargli le braccia dietro la schiena."
  },
  AvgDialog_38844_Content_10 = {
    Text = "Sophia, Sophia, so di aver sbagliato, Sophia. Ti prego, mondami dal mio peccato!"
  },
  AvgDialog_38844_Content_11 = {
    Text = "E-Edward? Amore, sei tu—"
  },
  AvgDialog_38844_Content_12 = {
    Text = "Sono io, sono io! Non avrei dovuto ingannare tua sorella. Me ne pento, me ne pento davvero!"
  },
  AvgDialog_38844_Content_13 = {
    Text = "Avanza strisciando sulle ginocchia, un groviglio maldestro di pianto e inchini verso di lei."
  },
  AvgDialog_38844_Content_14 = {
    Text = "Il demonio mi ha accecato gli occhi e corrotto l'anima. Ti prego, puniscimi, purificami! Il Giudizio si avvicina, e non voglio essere espulso dalla terra degli innocenti!"
  },
  AvgDialog_38844_Content_15 = {
    Text = "Calmati, Edward. Di cosa diavolo stai parlando, esattamente?"
  },
  AvgDialog_38844_Content_16 = {
    Text = "Ti prego, Sophia!"
  },
  AvgDialog_38844_Content_17 = {
    Text = "Edward, basta."
  },
  AvgDialog_38844_Content_18 = {
    Text = "Il giovane uomo, ancora chinato, alza il capo e guarda verso Salvador con aria stordita."
  },
  AvgDialog_38844_Content_19 = {
    Text = "Vescovo...?"
  },
  AvgDialog_38844_Content_2 = {
    Text = "Lasciatemi! Devo essere purificato! Devo essere purificato!"
  },
  AvgDialog_38844_Content_20 = {
    Text = "Un bagliore accecante di luce attraversa i margini della tua visuale. Prima ancora che tu possa sbattere le palpebre per dissipare le macchie residue, odi la voce di Edward vacillare sull'orlo della follia."
  },
  AvgDialog_38844_Content_21 = {
    Text = [[
No... no... anche tu sei un <Red:peccatore>, siamo tutti peccatori!
Pentitevi e purificatevi! Altrimenti bruceremo tutti in un tormento senza fine!]]
  },
  AvgDialog_38844_Content_23 = {
    Text = "Il corpo del giovane vacillò e cadde dritto a terra. Ogier ripose in silenzio la lancia usata per tramortirlo e si voltò a guardarti."
  },
  AvgDialog_38844_Content_24 = {
    Text = "Portatelo in salvo prima che faccia del male a qualcun altro. Chiamate la polizia e lasciate che se ne occupino i professionisti."
  },
  AvgDialog_38844_Content_25 = {
    Text = "Tutti nella Chiesa se ne sono andati; dovrebbe essere vuota ora."
  },
  AvgDialog_38844_Content_26 = {
    Text = "Facciamolo.\nSperiamo che sia più lucido quando si sveglierà."
  },
  AvgDialog_38844_Content_27 = {
    Text = "Si accovaccia, aiutandoti a sollevare Edward da terra e a caricarselo in spalla."
  },
  AvgDialog_38844_Content_28 = {
    Text = "Lasciate fare a me, {Male=Signor,Female=Signorina} %player%."
  },
  AvgDialog_38844_Content_29 = {
    Text = "Non preoccuparti, sono abituato a incassare i colpi. Stare in piedi renderebbe in realtà più difficile contrattaccare."
  },
  AvgDialog_38844_Content_3 = {
    Text = "Che sta succedendo?"
  },
  AvgDialog_38844_Content_30 = {
    Text = "Questo... lo lascio a te.\nResterò qui ancora un po' per vedere se qualcuno ha bisogno di aiuto dopo essere stato spaventato o ferito da Edward."
  },
  AvgDialog_38844_Content_31 = {
    Text = "Annuisci, ma prima che tu possa voltarti, quella stessa luce di prima torna a bruciare i margini della tua visuale."
  },
  AvgDialog_38844_Content_32 = {Text = "?"},
  AvgDialog_38844_Content_33 = {
    Text = [[
Vi sentite bene, %player%?
Se non state bene, posso occuparmene da solo.]]
  },
  AvgDialog_38844_Content_34 = {
    Text = "Non è niente, probabilmente solo la luce riflessa dal vetro negli occhi.\nAndiamo."
  },
  AvgDialog_38844_Content_4 = {
    Text = "Una voce ferma risuona alle vostre spalle, e il clamore circostante sfuma nel silenzio. La folla si apre, facendo largo a un vescovo in una nera veste clericale."
  },
  AvgDialog_38844_Content_5 = {
    Text = "Il vescovo Salvador, con gli occhi bendati, avanza verso di voi con una grazia e una precisione inquietanti. Sophia, nel frattempo, il volto colmo di preoccupazione, lo segue da vicino."
  },
  AvgDialog_38844_Content_6 = {
    Text = "Sophia... Sophia!"
  },
  AvgDialog_38844_Content_7 = {
    Text = "Il giovane si agitò improvvisamente. Con una forza inaspettata, si liberò dalla tua presa e si lanciò verso Sophia—"
  },
  AvgDialog_38844_Content_8 = {Text = "Attento!"},
  AvgDialog_38844_Content_9 = {
    Text = "Si inginocchia bruscamente."
  },
  AvgDialog_38845_Content_1 = {
    Text = "Ogier scaglia la sua lancia con grande forza, trafiggendo il riflesso d'argento."
  },
  AvgDialog_38845_Content_10 = {
    Text = "Dove sono? Come ho..."
  },
  AvgDialog_38845_Content_11 = {
    Text = "Eccellenza, siete voi? Cosa vi è accaduto?"
  },
  AvgDialog_38845_Content_12 = {
    Text = "Per favore... aspetta..."
  },
  AvgDialog_38845_Content_13 = {
    Text = "La luce blu si dissolve completamente senza che nessuno se ne accorga..."
  },
  AvgDialog_38845_Content_14 = {
    Text = "Salvador si inginocchiò tra le tavole, alzando il capo verso di te, con due rivoli di lacrime di sangue che scorrevano sotto le sue bende bianche."
  },
  AvgDialog_38845_Content_15 = {
    Text = "Mio signore, che succede al Vescovo?"
  },
  AvgDialog_38845_Content_16 = {
    Text = "Il legame è privo di potere, ma con un'instabilità così grave... Non ho mai visto nulla di simile."
  },
  AvgDialog_38845_Content_17 = {
    Text = "Il mio Legame... era... il precedente vescovo di qui... Non posso... pretendere troppo da lui..."
  },
  AvgDialog_38845_Content_18 = {
    Text = "Pallido Messaggero... ti prego... ti prego..."
  },
  AvgDialog_38845_Content_19 = {
    Text = [[
Trema, alzando la mano e posandola delicatamente sulla tua spalla.
Eppure riesci a malapena a percepirne il peso, ormai.]]
  },
  AvgDialog_38845_Content_2 = {
    Text = "Frammenti del riflesso d'argento cadono come stelle, e con essi la luna cremisi, percorsa da crepe, si frantuma completamente."
  },
  AvgDialog_38845_Content_20 = {
    Text = "Sta svanendo rapidamente, a meno che —"
  },
  AvgDialog_38845_Content_21 = {
    Text = "Stringi la mano di Salvador, chiudendo gli occhi..."
  },
  AvgDialog_38845_Content_22 = {
    Text = "Oscurità.\n L'oscurità è così serena, come un abbraccio, come un sonno profondo."
  },
  AvgDialog_38845_Content_23 = {
    Text = "Punti di luce sparsi emersero nella tua mente: i cittadini in preda al panico intorno, il determinato Ogier, e il debole vescovo che emanava una luce blu fioca, quasi invisibile."
  },
  AvgDialog_38845_Content_24 = {
    Text = "Ti avvicini, udendo voci flebili e soffocate."
  },
  AvgDialog_38845_Content_25 = {
    Text = "La mia famiglia si è sempre dedicata a eliminare la sofferenza e a propagare la benedizione del Padre... Come si è arrivati a questo?"
  },
  AvgDialog_38845_Content_26 = {
    Text = "Taci! Come osi calunniare mio padre in questo modo! Lui non è quel genere di persona! Assolutamente no!"
  },
  AvgDialog_38845_Content_27 = {
    Text = "Eccellenza, perché il mondo è sempre colmo di sofferenza?"
  },
  AvgDialog_38845_Content_28 = {
    Text = "Se non ci fossero peccatori al mondo... persone come mia sorella, mia madre e i bambini dell'orfanotrofio non soffrirebbero più per mano altrui?"
  },
  AvgDialog_38845_Content_29 = {
    Text = "È possibile sfuggire alla sofferenza e vivere per sempre felici?"
  },
  AvgDialog_38845_Content_3 = {
    Text = "Il mostro emette un grido straziante e crolla con un tonfo. Il suo corpo massiccio si dissolve rapidamente in una pozza di sangue scuro, lasciando solo una figura dall'aspetto umano che striscia a terra."
  },
  AvgDialog_38845_Content_30 = {
    Text = "Questa è una mia responsabilità..."
  },
  AvgDialog_38845_Content_31 = {
    Text = [[
La figura di Salvador apparve accanto a te.
I ricordi scorrevano davanti a te; sembrava non avere espressione, ma potevi percepire un accenno di tristezza.]]
  },
  AvgDialog_38845_Content_32 = {
    Text = "Ho sempre saputo che covava risentimento nel cuore. Pensavo l'avrebbe lasciato andare, ma invece ha permesso che marcisse."
  },
  AvgDialog_38845_Content_33 = {
    Text = "Ha detto che quel giorno lo avete salvato voi, Vescovo Salvador. È vero? Ma perché?\nHa commesso tante cose terribili, ha ingannato così tante persone... Perché lo avete aiutato?"
  },
  AvgDialog_38845_Content_34 = {
    Text = "Una seconda possibilità? Chi può dare una seconda possibilità alla mia famiglia? Chi può dare una seconda possibilità a mia sorella e a mia madre?\nSono morte, Vescovo Salvador. Sono tornate nell'abbraccio del Padre, lasciando solo me..."
  },
  AvgDialog_38845_Content_35 = {
    Text = "Rimango solo io..."
  },
  AvgDialog_38845_Content_36 = {
    Text = "Padre Iddio, abbi pietà e concedimi un'altra possibilità di vita. Avrei dovuto fare meglio, ma ora sto ripetendo i miei errori."
  },
  AvgDialog_38845_Content_37 = {
    Text = "Quei ladri, giocatori d'azzardo e tossicodipendenti non vengono da voi cercando perdono o una seconda possibilità, ma per autoconsolazione! Una scusa per continuare a fare del male!"
  },
  AvgDialog_38845_Content_38 = {
    Text = "Il peccatore non mostra rimorso e non si pentirà mai. Una tolleranza infinita non fa che scoraggiare i giusti e incoraggiare i malvagi.\nSe si continua così, non riuscirete a salvare nessuno."
  },
  AvgDialog_38845_Content_39 = {
    Text = "Li perdono e offro loro conforto, così come perdono tutti e offro conforto a tutti.\nOgnuno è benedetto dall'amore del Padre, e ognuno ha la capacità di smarrirsi e tornare sulla retta via."
  },
  AvgDialog_38845_Content_4 = {
    Text = [[
La luna di sangue svanisce, e la luce del sole torna a risplendere sul terreno, illuminando il corpo disteso in una pozza di sangue.
Sophia fissa il cielo con sguardo vacuo, mormorando sottovoce.]]
  },
  AvgDialog_38845_Content_40 = {
    Text = "La sofferenza è ciò che il Padre Supremo non desidera vedere, ciò che Egli spera di risolvere, e ciò che io, in qualità di Suo emissario, devo dissipare."
  },
  AvgDialog_38845_Content_41 = {
    Text = "La sofferenza che ho causato deve essere espiata da me solo."
  },
  AvgDialog_38845_Content_42 = {
    Text = "Protende la mano, sfiorandogli delicatamente il dorso. Le memorie ingiallite si increspano come acqua, raccogliendosi in punti di luce del suo spirito."
  },
  AvgDialog_38845_Content_43 = {
    Text = "Si volta verso di te, porgendoti la luce splendente tra le mani."
  },
  AvgDialog_38845_Content_44 = {
    Text = "Per favore... Aiutami, Pallido Messaggero.\nAllevia la loro sofferenza affinché possano completare in pace il loro viaggio."
  },
  AvgDialog_38845_Content_45 = {
    Text = "Accetta la Luce"
  },
  AvgDialog_38845_Content_46 = {
    Text = "Una luce azzurra ondeggia come il filo di un ragno. Un'estremità è legata a uno Spirito anziano ma gentile, l'altra si immerge nel punto di luce davanti a te."
  },
  AvgDialog_38845_Content_47 = {
    Text = "Recidi con cura il filo sottile, tingendolo del tuo stesso colore."
  },
  AvgDialog_38845_Content_48 = {
    Text = "Una luce bianca segue il filo di seta sempre più in profondità, mentre appaiono macchie luminose che dissipano gradualmente l'oscurità."
  },
  AvgDialog_38845_Content_49 = {Text = "Grazie..."},
  AvgDialog_38845_Content_5 = {
    Text = [[
<Yellow:Eve>... Vi ho delusa, ho deluso il <Yellow:Portatore di Luce>...
Non sono riuscita a purificarli, non sono riuscita a mondare i loro peccati...]]
  },
  AvgDialog_38845_Content_6 = {
    Text = "Portatore della luce... Tu, plasmato dall'argento puro... Ti imploro..."
  },
  AvgDialog_38845_Content_7 = {
    Text = "Inspira un respiro tremante, e un ultimo sospiro abbandona il suo corpo fragile."
  },
  AvgDialog_38845_Content_8 = {
    Text = "La piazza è nel caos — i feriti giacciono al suolo; molti hanno perso la vita. Altri gemono in agonia, incapaci di comprendere gli orrendi eventi appena trascorsi."
  },
  AvgDialog_38845_Content_9 = {
    Text = "Ugh... Mi fa male la testa..."
  },
  AvgDialog_38846_Content_1 = {
    Text = "Speranza Bianca Accesa"
  },
  AvgDialog_38846_Content_10 = {
    Text = "Coloro che avevano perso conoscenza, o persino cessato di respirare, aprirono lentamente gli occhi nella brezza gentile."
  },
  AvgDialog_38846_Content_11 = {
    Text = "Vi prego, alleviate il loro dolore e lenite i loro cuori."
  },
  AvgDialog_38846_Content_12 = {
    Text = "Gli occhi della gente si fecero vacui, i loro corpi si rilassarono. Panico e paura si dissiparono, sostituiti da calma e tranquillità."
  },
  AvgDialog_38846_Content_13 = {
    Text = "Sollevali dalla sofferenza e concedi loro la benedizione."
  },
  AvgDialog_38846_Content_14 = {
    Text = "La luce di marea si propagò verso l'esterno, e tutti chiusero gli occhi, come immersi nella quiete."
  },
  AvgDialog_38846_Content_15 = {
    Text = "La luna luminosa osserva tutto come sempre; solo la piazza caotica serve da prova della follia appena avvenuta."
  },
  AvgDialog_38846_Content_16 = {
    Text = "La tavoletta scattò dolcemente e si dissolse nelle ombre invisibili della notte. Salvador si sistemò i vestiti e si avvicinò a Sofia."
  },
  AvgDialog_38846_Content_17 = {
    Text = "...Non avresti dovuto salvarmi."
  },
  AvgDialog_38846_Content_18 = {
    Text = "\"Tutti coloro che ritrovano la via del ritorno possono tornare al mio abbraccio.\""
  },
  AvgDialog_38846_Content_19 = {
    Text = "\"Perché siete tutti miei fanciulli, e vi amo tutti.\"\nMa ti sbagli, Vescovo, e così la \"Scrittura Divina\"."
  },
  AvgDialog_38846_Content_2 = {
    Text = "La tavoletta si solleva ancora una volta."
  },
  AvgDialog_38846_Content_20 = {
    Text = "Certe persone non cambiano mai."
  },
  AvgDialog_38846_Content_21 = {
    Text = "Cosa ti porta qui?"
  },
  AvgDialog_38846_Content_22 = {
    Text = "Sophia, io—"
  },
  AvgDialog_38846_Content_23 = {
    Text = "Taci! Non ti basta aver causato la morte di mia sorella e di mia madre? Ora vieni sulle loro tombe a gongolare?!"
  },
  AvgDialog_38846_Content_24 = {
    Text = "Sono qui per scusarmi. Non mi aspettavo..."
  },
  AvgDialog_38846_Content_25 = {
    Text = "Sophia rise in modo tagliente."
  },
  AvgDialog_38846_Content_26 = {
    Text = "Ti sei scusato con <Blue:Thompson> così, dopo aver causato la morte del suo unico parente e di <Blue:Millie>?\nMi disgusti, Edward Bailey."
  },
  AvgDialog_38846_Content_27 = {
    Text = "Mi pento davvero di ciò che ho fatto, Sophia. So di non poter ottenere il tuo perdono—"
  },
  AvgDialog_38846_Content_28 = {
    Text = "Se te ne penti davvero, non saresti dovuto andare a trovare il Vescovo Salvador il giorno in cui Thompson ti ha ucciso."
  },
  AvgDialog_38846_Content_29 = {
    Text = "Sì, so come sei sopravvissuto, codardo. <Yellow:Lamp> me l'ha detto.\nDarti la \"<Yellow:Benedizione>\" è stata la decisione più stupida del vescovo. Dovresti morire, Bailey, morire nell'agonia."
  },
  AvgDialog_38846_Content_30 = {
    Text = "Nemmeno io volevo tutto questo. Ho cercato di controllarmi, davvero! Dopo che il Vescovo mi ha salvato, mi presentavo alla Chiesa ogni giorno e facevo volontariato alla vostra opera di carità ogni settimana. Te lo ricordi?"
  },
  AvgDialog_38846_Content_31 = {
    Text = "Voglio migliorare, davvero. È stato quel tizio, Aglo — ha detto che era un affare sicuro e mi ha chiesto di presentare un garante. Sono una vittima anch'io!"
  },
  AvgDialog_38846_Content_32 = {
    Text = "Anche adesso, continui a sfuggire alle tue responsabilità. Anche adesso... non ti sei davvero pentito."
  },
  AvgDialog_38846_Content_33 = {
    Text = "Estrasse un oggetto d'argento dalla tasca interna del suo vestito. La sua superficie liscia brillava debolmente alla luce del sole, trasformando il riflesso in un rosso minaccioso."
  },
  AvgDialog_38846_Content_34 = {Text = "Sophia...?"},
  AvgDialog_38846_Content_35 = {Text = "Pentiti."},
  AvgDialog_38846_Content_36 = {
    Text = [[
Segui gli insegnamenti del giusto Portatore di Luce, e purifica i peccati nella tua anima.
Solo allora potrai ottenere il perdono.]]
  },
  AvgDialog_38846_Content_37 = {Text = "Cosa sei?"},
  AvgDialog_38846_Content_38 = {
    Text = "Io... Io sono Edward..."
  },
  AvgDialog_38846_Content_39 = {
    Text = [[
Lo specchio lampeggia, e gli occhi del giovane uomo inginocchiato si fanno nuovamente vacui.
Tremando, solleva il bastone nella sua mano e si colpisce con forza.]]
  },
  AvgDialog_38846_Content_4 = {
    Text = "Salvador alzò la mano, e il sangue fluì incessantemente dal suo corpo e dai dintorni verso la tavoletta."
  },
  AvgDialog_38846_Content_40 = {
    Text = "Te lo chiedo ancora una volta: cosa sei?"
  },
  AvgDialog_38846_Content_41 = {
    Text = "Sono un peccatore."
  },
  AvgDialog_38846_Content_42 = {
    Text = "Quale peccato hai commesso?"
  },
  AvgDialog_38846_Content_43 = {
    Text = "Avidità... Desiderio... Ho permesso al male di contaminare la mia anima, e poi di infliggere dolore agli innocenti."
  },
  AvgDialog_38846_Content_44 = {
    Text = "Cosa dovresti fare?"
  },
  AvgDialog_38846_Content_45 = {
    Text = "Pentimento verso gli dèi e verso coloro a cui ho fatto del male...\nDevo Sopportare la frusta, sanguinare finché il nero peccato non defluisca, finché la <Red:Purificazione> non sia raggiunta."
  },
  AvgDialog_38846_Content_46 = {
    Text = "Il Giorno del Giudizio si avvicina. Solo le anime pure potranno entrare nel Rifugio degli Innocenti."
  },
  AvgDialog_38846_Content_47 = {
    Text = "<Red:Che la Lanterna resti accesa>."
  },
  AvgDialog_38846_Content_48 = {
    Text = "I peccatori non cambiano. Finché esistono, la sofferenza non scomparirà mai.\nSolo eliminandoli tutti il mondo potrà raggiungere la pace."
  },
  AvgDialog_38846_Content_49 = {
    Text = "...La Reliquia del Padre custodisce sempre la Sua luce. Tutti possono essere fuorviati, ma anche riscoprire la Sua luce."
  },
  AvgDialog_38846_Content_5 = {
    Text = "Una luce azzurra fluiva lungo intricati motivi, luminosa e fioca, respirando dolcemente."
  },
  AvgDialog_38846_Content_50 = {
    Text = "Non possiamo privare qualcuno dell'intera vita per l'azione di un singolo istante."
  },
  AvgDialog_38846_Content_51 = {
    Text = "Lo dici tu, ma hai mai pensato a coloro che sono stati feriti da loro? Per ogni Edward che trova la luce, quante Millie devono essere sacrificate? Quante Olivia?"
  },
  AvgDialog_38846_Content_52 = {
    Text = "Il peccato è peccato, e il torto è torto. Una volta commesso, non si può più tornare indietro."
  },
  AvgDialog_38846_Content_53 = {
    Text = "Lei rivolge lo sguardo verso di te."
  },
  AvgDialog_38846_Content_54 = {
    Text = "Portatemi via, consegnatemi alle vostre leggi corrotte. Ma ricordate, il giorno del giudizio arriverà.\nQuel giorno, sarete tutti banditi dalla terra degli innocenti."
  },
  AvgDialog_38846_Content_55 = {
    Text = "Il Riflesso è stato messo in sicurezza, Custode. I civili colpiti sono stati trasferiti negli ospedali maggiori e saranno dimessi dopo gli accertamenti."
  },
  AvgDialog_38846_Content_56 = {
    Text = "La versione ufficiale è che si è trattato di un evento di allucinazione collettiva causato da una fuga di gas tossico dalla fabbrica. Il governo cittadino emetterà domani delle scuse pubbliche e adotterà provvedimenti disciplinari nei confronti dei responsabili."
  },
  AvgDialog_38846_Content_57 = {
    Text = "Capisco. Grazie per il vostro duro lavoro."
  },
  AvgDialog_38846_Content_58 = {
    Text = "Questo è ciò che dovremmo fare."
  },
  AvgDialog_38846_Content_59 = {
    Text = "Il giovane in uniforme esita un istante, poi parla:"
  },
  AvgDialog_38846_Content_6 = {
    Text = "Padre Supremo della Genesi, nostro misericordioso Creatore, ascolta la mia preghiera."
  },
  AvgDialog_38846_Content_60 = {
    Text = "Come sei riuscito a farlo?"
  },
  AvgDialog_38846_Content_61 = {Text = "Cosa?"},
  AvgDialog_38846_Content_62 = {
    Text = "La situazione era così caotica, eppure con solo te e un Risvegliato, siete riusciti a limitare le vittime a una dozzina circa — quasi un miracolo."
  },
  AvgDialog_38846_Content_63 = {
    Text = "Tu e Ogier vi scambiate un rapido sguardo. Il giovane cavaliere tossisce leggermente con le mani dietro la schiena."
  },
  AvgDialog_38846_Content_64 = {
    Text = "Questa è probabilmente l'intesa tacita tra il mio signore e me."
  },
  AvgDialog_38846_Content_65 = {
    Text = [[
In ogni caso, porgo la mia gratitudine a voi a nome della Squadra di Prima Risposta del Comitato. 
Nel pieno della crisi, non avete abbandonato la nostra gente, permettendo loro di tornare a casa sani e salvi. Inoltre...]]
  },
  AvgDialog_38846_Content_66 = {
    Text = [[
Molti di noi sono cresciuti qui; il Quartiere della Chiesa significa molto per noi.
Grazie per tutto quello che avete fatto.]]
  },
  AvgDialog_38846_Content_67 = {
    Text = "È quello che dovremmo fare."
  },
  AvgDialog_38846_Content_68 = {
    Text = "La gratitudine non è mai troppa."
  },
  AvgDialog_38846_Content_69 = {
    Text = "Signorina Sophia... Che ne sarà di lei?"
  },
  AvgDialog_38846_Content_7 = {
    Text = "Delicati filamenti azzurri si irradiavano dalla tavoletta, attraversando la folla e dissipando la fragranza residua di sangue, lasciando un tenue aroma d'incenso."
  },
  AvgDialog_38846_Content_70 = {
    Text = "Interrogatela. Emetteremo il Giudizio su di lei dopo aver scoperto da dove proviene lo specchio."
  },
  AvgDialog_38846_Content_71 = {
    Text = "Il Rito eretico ha causato caos diffuso e numerose vittime... Il Vescovo spera che non venga condannata a morte, ma non sono ottimista."
  },
  AvgDialog_38846_Content_72 = {
    Text = "Vescovo Salvador."
  },
  AvgDialog_38846_Content_73 = {
    Text = "Ve ne andate?"
  },
  AvgDialog_38846_Content_74 = {
    Text = "Sì. Grazie per il vostro aiuto in questo evento."
  },
  AvgDialog_38846_Content_75 = {
    Text = "Tutto questo è iniziato per causa mia, e voi avete persino tenuto segreta la mia identità. Dovrei essere io a ringraziarvi."
  },
  AvgDialog_38846_Content_76 = {
    Text = "Davvero non tornerete con noi?"
  },
  AvgDialog_38846_Content_77 = {
    Text = "Non preoccupatevi per la parrocchia. Finché le condizioni lo permettono, consentiamo ai Risvegliati di agire liberamente."
  },
  AvgDialog_38846_Content_78 = {
    Text = "Vi ringrazio per la vostra gentilezza, ma preferisco restare qui."
  },
  AvgDialog_38846_Content_79 = {
    Text = "Salvador si voltò verso l'altare, rivelando un sorriso gentile."
  },
  AvgDialog_38846_Content_8 = {
    Text = "Le persone in piedi lentamente si sedettero."
  },
  AvgDialog_38846_Content_80 = {
    Text = "Dio Padre mi ha fatto rinascere qui, probabilmente sperando che potessi aiutare più persone.\nSe ne hai bisogno, <Yellow:Fuoco Pallido>, vieni da me in qualsiasi momento. Ti darò tutto me stesso."
  },
  AvgDialog_38846_Content_81 = {
    Text = "Mi perdonate, ma... Cosa sono esattamente il <Yellow:Messaggero Pallido> e il <Yellow:Fuoco Pallido>?"
  },
  AvgDialog_38846_Content_82 = {
    Text = "È la profezia di Dio Padre nella <Yellow:\"Sacra Scrittura\">"
  },
  AvgDialog_38846_Content_83 = {
    Text = "Un'Oscurità sconfinata calerà sul mondo, l'Anima pallida e calda è l'emissaria della Speranza, {Male=egli,Female=ella} accenderà la fiamma bianca per illuminare il Sentiero da percorrere."
  },
  AvgDialog_38846_Content_84 = {
    Text = "Non posso essere io, vero? Ci sono così tante persone al mondo."
  },
  AvgDialog_38846_Content_85 = {
    Text = "Anche se i miei occhi sono coperti, non posso confondere lo splendore di un'anima.\nLa vostra è così calda e luminosa. In tutti questi anni, non ne ho mai vista un'altra simile."
  },
  AvgDialog_38846_Content_86 = {
    Text = "[Vedi come è progettata la linea principale qui, vedi se è necessario menzionare informazioni relative alla lanterna]"
  },
  AvgDialog_38846_Content_87 = {
    Text = "Il giovane Custode si volta e si allontana. Salvador osserva il Bagliore, sussurrando una Preghiera mentre la porta si apre per l'ultima volta."
  },
  AvgDialog_38846_Content_88 = {
    Text = "Possiate illuminare l'Oscurità con una flebile Speranza."
  },
  AvgDialog_38846_Content_89 = {
    Text = "<Yellow:Rapporto Anomalie del Distretto Ecclesiastico di Londinium>\n\nA.F. 315 @2@3, Distretto della Cattedrale di Londinium, scoppia un'improvvisa rivolta davanti alla piazza della Chiesa delle Eterne Benedizioni del Padre. La folla manifesta gravi comportamenti violenti e autolesionistici, incapace di comunicare normalmente.\n...\nIl comportamento anomalo si intensifica dopo il lampeggiare di una fonte di luce sconosciuta, evolvendosi in un diffuso comportamento cannibalistico. A seguito delle indagini, la fonte di luce sconosciuta è stata identificata come uno specchio a mano fatto di argento speculare. Lo specchio assorbe energia tramite la luce solare e lunare; gli individui esposti al riflesso dello specchio vengono spinti dai loro desideri interiori più forti, inclusi ma non limitati a violenza, gola e sonnolenza, portando ad azioni estreme.\nQuesto specchio è stato recuperato dal Custode %player% e dal Risvegliatore Ogier, inizialmente determinato a contenere componenti di Argento o simili. Per dettagli, fare riferimento al rapporto di ricerca emesso dal Dipartimento di Ricerca Equipaggiamenti Speciali dell'Università di Mythag.\n...\nDurante l'interrogatorio da parte del Comitato, <Blue:Sophia Chatzan> ha ammesso di essersi unita alla Chiesa della luce del tempio tre anni fa e di aver ottenuto lo specchio rituale dalla leader della chiesa, Lantern (ovvero la signora <Yellow:Yves>) durante l'ultima attività della chiesa.\nQuando gli agenti hanno chiesto ulteriori informazioni, Sophia Chatzan ha abbassato la voce per pregare, senza fornire ulteriori risposte.\n..."
  },
  AvgDialog_38846_Content_9 = {
    Text = "Coloro che sedevano lì, a bocca spalancata, fissavano attoniti la scena miracolosa dinanzi a loro."
  },
  AvgDialog_38846_Content_90 = {
    Text = "Il sole al tramonto dissipa la foschia persistente nel cielo. La campana della chiesa rintocca, e il fischio della nave risuona al molo sul fiume."
  },
  AvgDialog_38846_Content_91 = {
    Text = "Sul tetto di un edificio alto, una figura ammantata se ne sta sola, di spalle al sole."
  },
  AvgDialog_38846_Content_92 = {
    Text = "Anche dopo aver sacrificato i peccatori mutati, nessuno <Red:Stigmata> è apparso.\nSembra che il valore di <Yellow:quello specchio> sia solo questo."
  },
  AvgDialog_38846_Content_93 = {
    Text = "Concedere il perdono al peccatore, conferirgli \"La Benedizione\"... Non sei davvero cambiato per niente, Vescovo Salvador."
  },
  AvgDialog_38846_Content_94 = {
    Text = "Il rogo non può cambiarti, né la resurrezione. Quando vedrai finalmente la realtà? Forse—"
  },
  AvgDialog_38846_Content_95 = {
    Text = "Protende la mano nell'aria, come se toccasse qualcosa di invisibile."
  },
  AvgDialog_38846_Content_96 = {
    Text = "Il <Yellow:Custode> dall'Anima pallida eppure calda di cui parla la profezia può introdurre più variabili. Credi che {Male=lui,Female=lei} sarebbe disposto a unirsi a noi?"
  },
  AvgDialog_38846_Content_97 = {
    Text = "Un cane gigante emerse dalle ombre accanto alla donna, i suoi arti contorti ricordavano vagamente la Sophia mutata. Sbuffa in risposta alle parole della donna."
  },
  AvgDialog_38846_Content_98 = {
    Text = "Beh, domani è sempre un nuovo giorno."
  },
  AvgDialog_38846_Content_99 = {
    Text = "Andiamo, cara. Se ne avremo l'occasione, li incontreremo di nuovo."
  },
  AvgDialog_43774_Content_1 = {
    Text = "Ben presto, chiazze di verde rigoglioso spuntarono dietro le dune implacabili."
  },
  AvgDialog_43774_Content_2 = {
    Text = "La stagione secca non concedeva pietà, rendendo il titolo di \"Oasi\" una caritatevole indulgenza per quel flebile rigagnolo—eppure bastò a riempire le vostre sacche d'acqua."
  },
  AvgDialog_43774_Content_3 = {
    Text = "Dell'acqua me ne occupo io. %player%, tieni d'occhio Ramona."
  },
  AvgDialog_43774_Content_4 = {
    Text = "Il Custode protegge Ramona, io proteggo il Custode.\nPerché quest'oasi non è solo per viandanti di passaggio..."
  },
  AvgDialog_43774_Content_5 = {
    Text = "Abbiamo anche dei \"nativi\", no?"
  },
  AvgDialog_43775_Content_1 = {Text = "Oasi"},
  AvgDialog_43775_Content_10 = {
    Text = "Quella Lady Daffodil... il suo stile non è esattamente qualcosa che approverei."
  },
  AvgDialog_43775_Content_11 = {
    Text = "Le rilevazioni di Alistair mostrano che la Pozza nera è instabile dalla Cerimonia di consegna della chiave di quest'anno."
  },
  AvgDialog_43775_Content_12 = {
    Text = "Potrebbe significare che la stabilità di Tawil sta tornando. Suggerirei di intensificare il monitoraggio..."
  },
  AvgDialog_43775_Content_13 = {
    Text = "Un momento."
  },
  AvgDialog_43775_Content_14 = {
    Text = "Ha un suggerimento, Professoressa Doll?"
  },
  AvgDialog_43775_Content_15 = {
    Text = "Vi consiglierei, umani, di affinare i vostri sensi per evitare di rivelare segreti sui Mythag quando degli estranei stanno origliando."
  },
  AvgDialog_43775_Content_16 = {
    Text = "Il cenno di Doll portò con sé un sottile profumo di violetta, mentre una donna elegante si alzava con grazia dal divano degli ospiti."
  },
  AvgDialog_43775_Content_17 = {
    Text = "Niente panico: il Mare di Nebbia Grigia mi ha fornito le rilevazioni della Pozza nera giorni prima che voi ci ficcaste dentro i vostri aggeggi."
  },
  AvgDialog_43775_Content_18 = {
    Text = "Ma saltiamo le chiacchiere. Passo di qui con informazioni cruciali da un'altra organizzazione, una consegna speciale per il signor William qui presente."
  },
  AvgDialog_43775_Content_19 = {
    Text = "Tutto riguarda l'Eone del Desiderio: l'<Yellow:\"Albero Madre.\">"
  },
  AvgDialog_43775_Content_2 = {
    Text = "Anch'io un tempo dormivo, ma ora sono desto.\nLe bestie del deserto berranno dal ▼▼ fiume, riposeranno sulle sue sponde, poiché nessuno le spaventerà."
  },
  AvgDialog_43775_Content_20 = {
    Text = "Quindi, per un pugno di chiacchiere da \"Lady Daffodil,\" siamo bloccati in questo deserto dimenticato da Dio, fermi all'età della pietra."
  },
  AvgDialog_43775_Content_21 = {
    Text = "I pezzi grossi di Mythag scommettono forte quanto me."
  },
  AvgDialog_43775_Content_22 = {
    Text = "Settimane di questa sabbiatura, e il mio cappotto preferito si sta sfilacciando a pezzi. C'è qualche possibilità di un budget per il Potenziamento del vestiario?"
  },
  AvgDialog_43775_Content_23 = {
    Text = "Se davvero compri un cappotto nuovo e non lo butti in qualche scommessa clandestina, fai pure, signor Ryker."
  },
  AvgDialog_43775_Content_24 = {
    Text = "Una notte ai tavoli mi frutta un cappotto nuovo più il capitale iniziale per la partita successiva. Tutti vincono, no?"
  },
  AvgDialog_43775_Content_25 = {
    Text = "William si schiarì la voce, stroncando le chiacchiere oziose."
  },
  AvgDialog_43775_Content_26 = {
    Text = "Tawil, l'<Yellow:Eone della Sagacia>, dorme nella Pozza nera dei Mythag. L'<Yellow:Eone dell'Estasi> vaga per il mondo sotto mentite spoglie. Ma la posizione dell'<Yellow:Eone del Desiderio> è sempre rimasta un mistero."
  },
  AvgDialog_43775_Content_27 = {
    Text = "L'intelligence di Daffodil conferma che il sito dell'Albero Madre è stato sigillato dal <Yellow:Muro della Tempesta> nell'anno 225 d.F. Sono passati novant'anni dall'ultimo accesso all'area."
  },
  AvgDialog_43775_Content_28 = {
    Text = "Gli Aramiti stanno preparando un enorme Sacrificio per corrompere l'Albero Madre e scatenare un'ondata di Dissoluzione su scala mondiale."
  },
  AvgDialog_43775_Content_29 = {
    Text = "L'obiettivo della vostra missione è semplice: seguire gli Aramiti nomadi locali e neutralizzare il nucleo del Rito, l'Albero Madre."
  },
  AvgDialog_43775_Content_3 = {
    Text = "Due settimane fa, Operazione Remouahe"
  },
  AvgDialog_43775_Content_30 = {
    Text = "Sì, sì. Ma lascia perdere i grandi discorsi: occuparsi dei problemi che abbiamo davanti è la priorità, giusto?"
  },
  AvgDialog_43775_Content_31 = {
    Text = "Guarda la ragazza: è bianca come un cencio per la disidratazione. Se non troviamo acqua al più presto, moriremo tutti di sete."
  },
  AvgDialog_43775_Content_32 = {
    Text = "Smettila di esagerare, sto bene!"
  },
  AvgDialog_43775_Content_33 = {
    Text = "Dai, ragazza. Abbiamo tutti appena finito le nostre scorte, ma tu non hai toccato la tua borraccia da ieri, vero?"
  },
  AvgDialog_43775_Content_34 = {
    Text = "Cos'è che sciaguatta lì dentro?"
  },
  AvgDialog_43775_Content_35 = {Text = "!"},
  AvgDialog_43775_Content_36 = {
    Text = "Hai afferrato la sacca di Ramona: era pesante, con forme scure che vorticavano all'interno."
  },
  AvgDialog_43775_Content_37 = {
    Text = "Ryker la rovesciò, e una densa melma nera ne fuoriuscì."
  },
  AvgDialog_43775_Content_38 = {Text = "D-melma."},
  AvgDialog_43775_Content_39 = {
    Text = "Ramona, quando hai iniziato a portare quella sacca..."
  },
  AvgDialog_43775_Content_4 = {
    Text = "Questo doveva essere l'<Yellow:Albero Madre>—nessuno aveva menzionato queste cose!"
  },
  AvgDialog_43775_Content_40 = {
    Text = [[
Un paio di giorni fa.
Ho tenuto d'occhio la situazione: sembra che solo la mia sia stata colpita.]]
  },
  AvgDialog_43775_Content_41 = {
    Text = "Per esserti azzuffata da vicino con quei mostri?"
  },
  AvgDialog_43775_Content_42 = {
    Text = "Al perché ci penseremo dopo. Ora è urgente rifornirsi.\nRyker?"
  },
  AvgDialog_43775_Content_43 = {
    Text = "Certo, certo. Ma la fortuna non è fatta per le cacce al tesoro, mi spiego?\nSe avessi saputo che questo lavoretto era il motivo per cui mi avete tirato fuori, avrei finto di star male..."
  },
  AvgDialog_43775_Content_44 = {
    Text = "Ryker borbottò, fiutando l'aria rovente in cerca di tracce d'umidità."
  },
  AvgDialog_43775_Content_45 = {
    Text = "Direzione ovest—l'acqua dev'essere da quella parte, senza dubbio."
  },
  AvgDialog_43775_Content_6 = {
    Text = "Ramona affondò la lama nella bestia che le si avventava contro. I suoi tentacoli ebbero un breve spasmo, poi si afflosciarono sulla duna. Gli arti straziati si dissolsero nella sabbia, sprofondando sotto le onde mutevoli in pochi istanti."
  },
  AvgDialog_43775_Content_7 = {
    Text = "Dopotutto, la cosiddetta leggenda dell'Albero Madre ha solo vaghi riferimenti nella biblioteca di Mythag."
  },
  AvgDialog_43775_Content_8 = {
    Text = "La maggior parte del Regno di Remouahe resta ancora inesplorata nella storia umana — a parte gli Aramiti che compaiono di tanto in tanto nei mercati, nessuno sa cosa si celi in quelle tempeste di sabbia."
  },
  AvgDialog_43775_Content_9 = {
    Text = "Ma il signor Alistair ha confermato le informazioni sull'Albero Madre ricevute da Lady Daffodil."
  },
  AvgDialog_43776_Content_1 = {Text = "Attento!"},
  AvgDialog_43776_Content_10 = {
    Text = "La cosa emise un ululato da incubo, i suoi arti viscidi di melma si agitarono debolmente prima che un ultimo spasmo la percorresse e si sgretolasse nel nulla."
  },
  AvgDialog_43776_Content_11 = {
    Text = "Una carovana di cammelli apparve sulla duna lontana; il segugio abbaiò felice, lanciandosi verso la donna che la guidava."
  },
  AvgDialog_43776_Content_12 = {
    Text = "Bravo ragazzo, bravo ragazzo."
  },
  AvgDialog_43776_Content_13 = {
    Text = "Sì, ho capito tutto. Sei stato bravissimo: ti meriterai il premio che ti spetta."
  },
  AvgDialog_43776_Content_14 = {
    Text = "Smontò dal cammello, incontrando il tuo sguardo senza esitazione."
  },
  AvgDialog_43776_Content_15 = {
    Text = "Il vostro equipaggiamento grida \"forestieri\". Sembrate distrutti; dovete aver attraversato Remouahe a fatica."
  },
  AvgDialog_43776_Content_16 = {
    Text = "Bere dal Fiume sacro degli Aram? È il destino. Vi va un po' di ospitalità al nostro accampamento?"
  },
  AvgDialog_43776_Content_17 = {
    Text = [[
Nel frattempo
Pozza Nera Sotterranea di Mythag]]
  },
  AvgDialog_43776_Content_18 = {
    Text = "Le informazioni gratuite non fanno per te, e non anticipi mai il conto. Se Mythag non ha pagato, qualcun altro l'ha fatto."
  },
  AvgDialog_43776_Content_19 = {
    Text = "Chi sta tirando i fili per portare il Custode dei Segreti di Mythag in quel deserto?"
  },
  AvgDialog_43776_Content_20 = {
    Text = "Sembra che sia inutile cercare di far leva su una menzogna con voi."
  },
  AvgDialog_43776_Content_21 = {
    Text = "Peccato, l'affare è storia antica ormai. Non riesco più a ricordare il volto dell'acquirente."
  },
  AvgDialog_43776_Content_22 = {
    Text = "...Capisco."
  },
  AvgDialog_43776_Content_23 = {
    Text = [[
Remouahe
Fiume sacro]]
  },
  AvgDialog_43776_Content_24 = {
    Text = "Allora, Julie, le linee telluriche di Remouahe ti hanno risvegliata? I sogni ti hanno chiamata a guidare gli Aramiti?"
  },
  AvgDialog_43776_Content_25 = {
    Text = "Sembra decisamente leggendario!"
  },
  AvgDialog_43776_Content_26 = {
    Text = "All'inizio li ho ignorati, ovviamente, ma i sogni persistevano, notte dopo notte. Un intero popolo là fuori ad aspettare... come Inviato Divino, come potevo voltare le spalle?"
  },
  AvgDialog_43776_Content_27 = {
    Text = "Per fortuna hai risposto alla chiamata, altrimenti saremmo ancora lì a brancolare come idioti in eterno!"
  },
  AvgDialog_43776_Content_28 = {
    Text = "È un onore per gli Aramiti ospitare illustri visitatori come voi, signor Ryker."
  },
  AvgDialog_43776_Content_29 = {
    Text = "Adagi Ramona sul cammello; più avanti, le risate e i fischiettii di Juliette e Ryker fluttuano verso di te."
  },
  AvgDialog_43776_Content_3 = {
    Text = "Ramona barcollò, il suo stocco riuscì a malapena a bloccare gli artigli fendenti del mostro."
  },
  AvgDialog_43776_Content_30 = {
    Text = "Nonostante gli altri Aramiti la esortino a cavalcare, Juliette insiste per camminare, cedendo la sua cavalcatura a te."
  },
  AvgDialog_43776_Content_31 = {
    Text = "Non è troppo per uno stratagemma?"
  },
  AvgDialog_43776_Content_32 = {
    Text = "Qualcuno nel vostro gruppo dovrà pur fare amicizia con la gente del posto."
  },
  AvgDialog_43776_Content_33 = {
    Text = "Ahimè, il signor Ryker ha un talento con le carte e un fascino pari al mio."
  },
  AvgDialog_43776_Content_34 = {
    Text = [[
Spero che Vostra Signoria non stia storpiando la parola "sfida".
Ricordo ancora il vostro broncio dopo che Ryker vi ha spennato a poker quella sera.]]
  },
  AvgDialog_43776_Content_35 = {
    Text = "Come il miglior squalo da tavolo di Londinium, una rara sconfitta merita un po' di malumore — del tutto legittimo."
  },
  AvgDialog_43776_Content_36 = {
    Text = "Hai sperperato ogni centesimo e il giorno dopo hai saltato la colazione."
  },
  AvgDialog_43776_Content_37 = {
    Text = "Litigare non è da pazienti—riposatevi."
  },
  AvgDialog_43776_Content_38 = {
    Text = "La voce roca di Ramona echeggia nella tua stretta, la sua febbre innaturale che pulsa attraverso di te a ogni sobbalzo."
  },
  AvgDialog_43776_Content_39 = {
    Text = "Il calore arriva stranamente in fretta; una brutta sensazione ti colpisce i nervi."
  },
  AvgDialog_43776_Content_4 = {
    Text = "Dietro di te—"
  },
  AvgDialog_43776_Content_40 = {
    Text = "Guardate un po'."
  },
  AvgDialog_43776_Content_41 = {
    Text = "Battiti inquieti pulsano nelle raffiche di sabbia, la polvere soffoca i tuoi respiri con un'opprimente stretta."
  },
  AvgDialog_43776_Content_42 = {
    Text = "I campanacci dei cammelli risuonano lontani e prolungati; il calore distorce il tramonto in distorsioni. L'orlo dell'orizzonte germoglia puntini di tende come illusioni sfocate."
  },
  AvgDialog_43776_Content_43 = {
    Text = "Dopo settimane di marcia estenuante, trovate finalmente l'obiettivo di questa indagine: Aram."
  },
  AvgDialog_43776_Content_44 = {
    Text = "Il campo degli Aramiti è poco più avanti. Per sicurezza, proseguirò da sola."
  },
  AvgDialog_43776_Content_45 = {
    Text = "Tempismo perfetto—ho una pista che voglio seguire..."
  },
  AvgDialog_43776_Content_5 = {
    Text = "Ramona non riuscì a girarsi abbastanza in fretta. Una bestia eruppe dalla sabbia, i suoi tentacoli si fusero in una lancia, scagliandosi contro la sua schiena—"
  },
  AvgDialog_43776_Content_6 = {Text = "Ding—"},
  AvgDialog_43776_Content_7 = {
    Text = "Un segugio massiccio balzò dal fianco, schiantando la creatura a terra."
  },
  AvgDialog_43776_Content_8 = {
    Text = "Il mostro colto alla sprovvista scagliò filamenti sanguinolenti, pronto a soffocare il cane a metà del morso."
  },
  AvgDialog_43776_Content_9 = {
    Text = "Ramona rotolò all'indietro, conficcando lo stocco dritto nel suo occhio."
  },
  AvgDialog_43777_Content_10 = {
    Text = "L'Albero Madre funge da Emissario terreno di uno dei <Yellow:tre Eoni>—<Yellow:Tifere Yesod, l'Eone del Desiderio>."
  },
  AvgDialog_43777_Content_11 = {
    Text = "Studiare queste spoglie potrebbe rivelarsi cruciale per decifrare il Fenomeno di Dissoluzione."
  },
  AvgDialog_43777_Content_12 = {
    Text = "Ora, che il rito di apertura abbia inizio."
  },
  AvgDialog_43777_Content_13 = {
    Text = "Chiamiamo qualche studente per assistere?"
  },
  AvgDialog_43777_Content_14 = {
    Text = "Non ce n'è bisogno. Si tratta solo di sollevare il coperchio."
  },
  AvgDialog_43777_Content_15 = {
    Text = "Si dice che i giovani del Regno di Elke si misurino con gli orsi fin dall'infanzia. Anche la nostra preside ad interim Czort deve possedere una formidabile prodezza, senza dubbio."
  },
  AvgDialog_43777_Content_16 = {
    Text = "Czort avanza, inspira profondamente, pianta i piedi a terra e scatena tutta la sua forza in un possente affondo—"
  },
  AvgDialog_43777_Content_17 = {
    Text = "Il coperchio non cede."
  },
  AvgDialog_43777_Content_18 = {
    Text = "Fai finta di essere ancora nel tuo periodo d'oro?\nQuand'è l'ultima volta che hai messo piede nella sala d'addestramento?"
  },
  AvgDialog_43777_Content_19 = {
    Text = "Oh, ma il carico di lavoro della preside ad interim è implacabile. Sono sicura che la signora Czort avrebbe voluto allenarsi di più."
  },
  AvgDialog_43777_Content_2 = {Text = "Thais"},
  AvgDialog_43777_Content_20 = {
    Text = "Ci provo io."
  },
  AvgDialog_43777_Content_21 = {
    Text = "Il tuo sguardo percorre l'intera superficie della bara: la vernice screpolata nera e dorata, le incisioni elaborate che ne circondano la forma, le gemme splendenti incastonate in ogni angolo."
  },
  AvgDialog_43777_Content_22 = {
    Text = "Premi contro il coperchio, ma non cede di un millimetro."
  },
  AvgDialog_43777_Content_23 = {
    Text = "Stringendo i denti, ti trafiggi la punta del dito con un morso deciso e — sfidando il dolore — tracci una striscia sanguinolenta sul legno."
  },
  AvgDialog_43777_Content_24 = {
    Text = "Un rombo fragoroso echeggia mentre la bara cede lentamente."
  },
  AvgDialog_43777_Content_25 = {
    Text = "Ciò che dormiva all'interno un tempo era una mummia..."
  },
  AvgDialog_43777_Content_26 = {
    Text = "Ora ridotto a brandelli di lino sbiadito, bende aggrovigliate e una pozza ribollente di melma nerastra."
  },
  AvgDialog_43777_Content_27 = {
    Text = "Inviate il legno e il tessuto al laboratorio per un'analisi di composizione."
  },
  AvgDialog_43777_Content_28 = {
    Text = "Un'analisi di datazione potrebbe rivelare l'identità della mummia."
  },
  AvgDialog_43777_Content_29 = {
    Text = "Non è necessario."
  },
  AvgDialog_43777_Content_3 = {
    Text = "Una settimana dopo l'Operazione Remouahe"
  },
  AvgDialog_43777_Content_30 = {Text = "So chi è."},
  AvgDialog_43777_Content_31 = {
    Text = "Le tue dita sfiorano le rune incise che rivestono l'interno della bara; i loro rilievi compongono un nome impresso a fuoco nella tua memoria."
  },
  AvgDialog_43777_Content_32 = {Text = "Thais."},
  AvgDialog_43777_Content_33 = {
    Text = "Che possa finalmente riposare in pace."
  },
  AvgDialog_43777_Content_4 = {
    Text = "Il sontuoso feretro giace nelle profondità sotterranee di Mythag. La sua lacca nera e oro evoca origini antiche e la storia oscura che stai per portare alla luce."
  },
  AvgDialog_43777_Content_5 = {
    Text = "Giace in solenne magnificenza, sussurrando dello splendore svanito di una civiltà perduta e della saga epica che hai vissuto."
  },
  AvgDialog_43777_Content_6 = {
    Text = "Stiamo esaminando il bottino ottenuto da %player% durante l'Operazione Remouahe."
  },
  AvgDialog_43777_Content_7 = {
    Text = "I nomadi aramiti chiamano ciò che giace al suo interno le \"Spoglie dell'Albero Madre.\""
  },
  AvgDialog_43777_Content_8 = {
    Text = "Il tuo sguardo indugia sull'intricata incisione al centro del feretro."
  },
  AvgDialog_43777_Content_9 = {
    Text = "L'emblema dell'albero è inciso sulla superficie enigmatica del coperchio. I suoi rami si estendono rigogliosi, e le sue radici si avvolgono come serpenti, emanando bagliori fiochi e sfuggenti in tonalità cupe."
  },
  AvgDialog_43788_Content_1 = {
    Text = "Oh, giusto—Ryker, un momento per favore."
  },
  AvgDialog_43788_Content_10 = {
    Text = "Bene, bene... che trucco ingegnoso."
  },
  AvgDialog_43788_Content_100 = {
    Text = [[
Ah, capisco!
Quindi sei solo un visitatore di Remouahe!]]
  },
  AvgDialog_43788_Content_101 = {
    Text = "Remouahe aspettava volti nuovi da troppo tempo!\nFarò preparare a tutti il più grandioso banchetto attorno al falò: dovete divertirvi come non mai!"
  },
  AvgDialog_43788_Content_102 = {
    Text = "Un festino?"
  },
  AvgDialog_43788_Content_103 = {
    Text = "Esatto! Agli Aramiti mancherà la Conoscenza del mondo, ma i nostri cuori sono spalancati."
  },
  AvgDialog_43788_Content_104 = {
    Text = "Sopravvivete al festino e sarete uno di noi!"
  },
  AvgDialog_43788_Content_105 = {
    Text = "Come famiglia, nessuna Punizione per te, purché tu giuri di non rivelare ciò che hai visto in questa tenda."
  },
  AvgDialog_43788_Content_106 = {
    Text = "Assaporate l'ospitalità aramita al festino!"
  },
  AvgDialog_43788_Content_11 = {
    Text = "Non fate in tempo a raggiungere il campo che una folla di Aramiti in abiti tradizionali si riversa sulla carovana di cammelli di Juliette."
  },
  AvgDialog_43788_Content_12 = {
    Text = "La signorina Juliette è tornata — portate le offerte preparate!"
  },
  AvgDialog_43788_Content_13 = {
    Text = "La signorina Juliette ha portato degli ospiti?"
  },
  AvgDialog_43788_Content_14 = {
    Text = "Signorina Juliette, abbiamo avvistato un gruppo di Nubia ottocento metri a sud — sono circa trenta!"
  },
  AvgDialog_43788_Content_15 = {
    Text = "Capito. Me ne occuperò uno alla volta. Alva è nella tenda della Regina?"
  },
  AvgDialog_43788_Content_16 = {
    Text = "Il capo ha preso una squadra per esplorare la Nubia."
  },
  AvgDialog_43788_Content_17 = {
    Text = "Capito. Accompagnerò prima i nostri ospiti a riposare. Vi prego di attendermi nella tenda del capo."
  },
  AvgDialog_43788_Content_18 = {
    Text = "Gli Aramiti si disperdono in un turbinio mentre Juliette tira le redini, voltandosi verso di voi."
  },
  AvgDialog_43788_Content_19 = {
    Text = "Come potete vedere, gli affari di Aram ci tengono occupati. In qualità di inviata, mi occupo di alcuni dei loro lavori saltuari di tanto in tanto."
  },
  AvgDialog_43788_Content_2 = {Text = "Hm?"},
  AvgDialog_43788_Content_20 = {
    Text = "Detto ciò, per passare la notte serve l'approvazione della Regina e del capo tribù. Sentitevi liberi di riposare nella mia tenda o di parlare con gli Aram."
  },
  AvgDialog_43788_Content_21 = {Text = "..."},
  AvgDialog_43788_Content_22 = {Text = "..."},
  AvgDialog_43788_Content_23 = {
    Text = "Mettiamo insieme ciò che sappiamo."
  },
  AvgDialog_43788_Content_24 = {
    Text = "Secondo Juliette, l'<Yellow:Albero Madre> si è inaridito molto prima della comparsa del <Yellow:Muro della Tempesta>."
  },
  AvgDialog_43788_Content_25 = {
    Text = "Con il declino dell'Albero Madre, gli affluenti del Fiume sacro si stanno prosciugando, la desertificazione peggiora — non c'è più modo per i villaggi di sopravvivere qui."
  },
  AvgDialog_43788_Content_26 = {
    Text = "Questa squadra trasporta i Resti dell'Albero Madre, cercando un varco attraverso il Muro della Tempesta per rianimarlo."
  },
  AvgDialog_43788_Content_27 = {
    Text = "Quei mostri — i Nubia — sono una peste recente a Remouahe."
  },
  AvgDialog_43788_Content_28 = {
    Text = "La società degli Aramiti è piuttosto primitiva; Juliette, la Risvegliatrice che ha sbaragliato gli attacchi dei Nubia, è considerata un'inviata divina dotata di potere soprannaturale."
  },
  AvgDialog_43788_Content_29 = {
    Text = "Fermi... qualcuno sta arrivando."
  },
  AvgDialog_43788_Content_3 = {
    Text = "Prima di entrare nell'insediamento, dovremmo occuparci della vostra... presentazione."
  },
  AvgDialog_43788_Content_30 = {
    Text = "Riposate bene, tutti?"
  },
  AvgDialog_43788_Content_31 = {
    Text = "Quando sarete pronti, uno di voi incontrerà la Regina come rappresentante."
  },
  AvgDialog_43788_Content_32 = {Text = "..."},
  AvgDialog_43788_Content_33 = {
    Text = "Mentre il crepuscolo si fa più fitto, il tramonto stria il cielo di cremisi. I falchi del deserto volteggiano ancora una volta, il loro ultimo grido riecheggia prima che si posino sui rami spogli."
  },
  AvgDialog_43788_Content_34 = {
    Text = "Sotto la guida di Juliette, giungi dinanzi a una tenda dal disegno singolare."
  },
  AvgDialog_43788_Content_35 = {
    Text = "Questa è la tenda della Regina. Secondo le usanze aramite, ogni ospite d'onore deve ottenere il permesso del capo tribù sotto lo sguardo della Regina."
  },
  AvgDialog_43788_Content_36 = {
    Text = "Vi prego, attendete qui il capo—ho faccende di cui occuparmi."
  },
  AvgDialog_43788_Content_37 = {
    Text = "Ricordate: non entrare."
  },
  AvgDialog_43788_Content_38 = {
    Text = "Offendere la Regina va oltre le mie capacità di rimedio."
  },
  AvgDialog_43788_Content_39 = {Text = "..."},
  AvgDialog_43788_Content_4 = {
    Text = "Tenete sempre con voi questo sacchetto d'incenso — infilato nella cravatta, appeso al bastone, o anche dietro l'orecchio, come preferite."
  },
  AvgDialog_43788_Content_40 = {
    Text = "Una brezza solleva il lembo, lasciando intravedere scorci dell'interno attraverso lo spiraglio."
  },
  AvgDialog_43788_Content_41 = {
    Text = "Un'inspiegabile sete ti sale alla gola, spingendoti a sbirciare all'interno."
  },
  AvgDialog_43788_Content_42 = {
    Text = "In qualche modo, un sussurro nell'etere insiste: questa tenda custodisce tutto ciò che cerchi in questo viaggio. Solleva la tenda, e le risposte ti attendono."
  },
  AvgDialog_43788_Content_43 = {
    Text = "I venti ululano solitari, trascinando granelli di sabbia. Nessuno osserva."
  },
  AvgDialog_43788_Content_44 = {
    Text = "Entra nella tenda"
  },
  AvgDialog_43788_Content_45 = {
    Text = "Sbircia dentro la tenda"
  },
  AvgDialog_43788_Content_46 = {
    Text = "Non fare nulla"
  },
  AvgDialog_43788_Content_47 = {
    Text = "Sai ben poco degli usi degli Aramiti; perdi questa occasione, e chissà quando potrai avvicinarti di nuovo a questa tenda."
  },
  AvgDialog_43788_Content_48 = {
    Text = "Niente mezze misure—scosti il lembo senza farti notare e ti introduci all'interno."
  },
  AvgDialog_43788_Content_49 = {
    Text = [[
Solo un'occhiata veloce: se ti beccano, puoi cavartela a parole.
Dicendoti questo, sollevi la tenda per sbirciare furtivamente.]]
  },
  AvgDialog_43788_Content_5 = {
    Text = "Ryker prende il piccolo sacchetto d'incenso e lo infila nel guanto sinistro."
  },
  AvgDialog_43788_Content_50 = {
    Text = "Un'ondata di vertigine ti travolge; passano alcuni istanti prima che il mondo torni a fuoco."
  },
  AvgDialog_43788_Content_51 = {
    Text = [[
Non sai quasi nulla degli Aram, ancora.
Per sicurezza, meglio non fare nulla.]]
  },
  AvgDialog_43788_Content_52 = {
    Text = [[
Come perle che rotolano, una risata maliziosa e invitante giunge da dietro.
Da sotto il lembo della tenda si estende un lembo di velo immacolato e setoso.]]
  },
  AvgDialog_43788_Content_53 = {
    Text = "Un'ondata di vertigine ti travolge; passano alcuni istanti prima che il mondo torni a fuoco."
  },
  AvgDialog_43788_Content_54 = {
    Text = "La tua visuale si schiarisce sull'interno della tenda: al centro giace una bara."
  },
  AvgDialog_43788_Content_55 = {
    Text = "Un impulso inspiegabile ti spinge a camminare verso di essa. Quando torni in te, le tue dita sfiorano già i bordi dorati tempestati di gemme."
  },
  AvgDialog_43788_Content_56 = {
    Text = "<Gray:Questo è—>"
  },
  AvgDialog_43788_Content_57 = {
    Text = "Ti immergi nella visuale dell'albero."
  },
  AvgDialog_43788_Content_58 = {
    Text = "Un seme si insinua nel ricco terriccio nero, le sue fragili radici frantumano l'involucro per violare la terra."
  },
  AvgDialog_43788_Content_59 = {
    Text = "Innumerevoli viticci erompono come tentacoli guizzanti, artigliando il cielo lungo pioli invisibili, foglie frementi che ululano in furia ferina."
  },
  AvgDialog_43788_Content_6 = {Text = "..."},
  AvgDialog_43788_Content_60 = {
    Text = "Nodi gonfi dell'albero si squarciano in fiotti di pus nero, schizzando nel fiume cristallino come lastroni di ghiaccio in frantumi."
  },
  AvgDialog_43788_Content_61 = {Text = "Boom!"},
  AvgDialog_43788_Content_62 = {
    Text = "L'albero crolla nel fragore del tuono, un tronco marcio che deriva a valle—la sua forma inquietantemente simile a una bara..."
  },
  AvgDialog_43788_Content_63 = {
    Text = "...Quindi queste sono... le spoglie dell'Albero Madre."
  },
  AvgDialog_43788_Content_64 = {
    Text = "L'obiettivo della vostra missione è semplice: seguire gli Aramiti nomadi locali e neutralizzare il nucleo del Rito, l'Albero Madre."
  },
  AvgDialog_43788_Content_65 = {
    Text = "Secondo Juliette, l'Albero Madre si inaridì molto prima che il Muro della Tempesta apparisse."
  },
  AvgDialog_43788_Content_66 = {
    Text = "Questa squadra trasporta i Resti dell'Albero Madre, cercando un varco attraverso il Muro della Tempesta per rianimarlo."
  },
  AvgDialog_43788_Content_67 = {
    Text = "In altre parole, fare irruzione e dare fuoco ai Resti dell'Albero Madre in quella bara, e la missione sarebbe compiuta."
  },
  AvgDialog_43788_Content_68 = {
    Text = "Ma fuggire dagli Aramiti dopo? Ci sarà anche solo il tempo di pianificare?"
  },
  AvgDialog_43788_Content_69 = {
    Text = "Il cuore ti martella nel petto, certezza e dubbio si attorcigliano in nodi inestricabili."
  },
  AvgDialog_43788_Content_7 = {
    Text = "Ramona, che succede?"
  },
  AvgDialog_43788_Content_70 = {
    Text = "Una Cantilena si leva come una Preghiera."
  },
  AvgDialog_43788_Content_71 = {
    Text = "La morte si avvicina. La Dissoluzione albeggia."
  },
  AvgDialog_43788_Content_72 = {
    Text = "Le Spoglie della Madre svaniscono, sangue e seme vagano per la Terra, divorati da bestie appena nate."
  },
  AvgDialog_43788_Content_73 = {
    Text = "Cieli e dèi si ammantano di tenebra, finché giunge l'inviato straniero."
  },
  AvgDialog_43788_Content_74 = {
    Text = [[
L'Albero Madre risorge: le sue radici bevono a fondo il fluire del Fiume sacro.
Incorona di luce i caduti e richiama il loro sangue a quello di Aram.]]
  },
  AvgDialog_43788_Content_75 = {
    Text = "Perché i tuoi occhi sono velati dall'oscurità?"
  },
  AvgDialog_43788_Content_76 = {
    Text = "E chi sta cantando?"
  },
  AvgDialog_43788_Content_77 = {
    Text = "Viaggiatore da lontano..."
  },
  AvgDialog_43788_Content_78 = {
    Text = "Una risatina frantuma la tua fantasticheria. Alzi lo sguardo: in cima al feretro si staglia la sagoma di una donna, giunta senza invito."
  },
  AvgDialog_43788_Content_79 = {
    Text = "Sorride con occhi colmi di allegria, le mani che sollevano le gonne come una sposa in riverenza, chinandosi a osservarti."
  },
  AvgDialog_43788_Content_8 = {
    Text = "Guarda la faccia di Ryker."
  },
  AvgDialog_43788_Content_80 = {
    Text = "Sono Thais, Regina di Aram. Viaggiatore da lontano, hai portato un tributo?"
  },
  AvgDialog_43788_Content_81 = {
    Text = "Balza giù e si avvicina ancheggiando, il suo sguardo malizioso che ti gira intorno."
  },
  AvgDialog_43788_Content_82 = {
    Text = "Che sorpresa mi porti, {Male=ragazzo,Female=ragazza}?"
  },
  AvgDialog_43788_Content_83 = {Text = "..."},
  AvgDialog_43788_Content_84 = {
    Text = "Juliette ha scelto te per incontrarmi sotto lo sguardo della Regina—devi essere tenuto in grande considerazione."
  },
  AvgDialog_43788_Content_85 = {
    Text = "Non ti ha avvertito delle punizioni per chi disturba la Regina?"
  },
  AvgDialog_43788_Content_86 = {
    Text = "Il lembo della tenda si scosta e una donna aramita dall'aria severa, sulla trentacinquina, entra a passo deciso."
  },
  AvgDialog_43788_Content_87 = {
    Text = "Thais si arrampica di nuovo in cima al feretro, assumendo una posa regale come un Sovrano altero sul suo Trono."
  },
  AvgDialog_43788_Content_88 = {
    Text = "Oh, nostro stimato ospite..."
  },
  AvgDialog_43788_Content_89 = {
    Text = "La voce tagliente dell'intrusa tronca di netto il suo tono affettato."
  },
  AvgDialog_43788_Content_9 = {
    Text = "L-Lord Dexter!"
  },
  AvgDialog_43788_Content_90 = {
    Text = "Alva, Capo di Aram."
  },
  AvgDialog_43788_Content_91 = {
    Text = "Juliette mi ha informato sul vostro passato."
  },
  AvgDialog_43788_Content_92 = {
    Text = "Ma ha tralasciato la parte cruciale — giovane, qual è il tuo scopo a Remouahe?"
  },
  AvgDialog_43788_Content_93 = {
    Text = "La domanda improvvisa ti scuote; l'istinto prende il sopravvento —"
  },
  AvgDialog_43788_Content_94 = {
    Text = "Condurre un'indagine scientifica"
  },
  AvgDialog_43788_Content_95 = {Text = "Turismo"},
  AvgDialog_43788_Content_96 = {
    Text = "...Nessun altro motivo?"
  },
  AvgDialog_43788_Content_97 = {
    Text = "Il suo sguardo penetrante si conficca nel tuo, come a strappare via la menzogna."
  },
  AvgDialog_43788_Content_98 = {
    Text = "Rinsaldi i nervi, mascherando l'inquietudine per reggere la sua Sonda."
  },
  AvgDialog_43788_Content_99 = {Text = "..."},
  AvgDialog_43789_Content_1 = {
    Text = "Insediamento"
  },
  AvgDialog_43789_Content_2 = {
    Text = "Un cavallo veloce galoppa dalle tende, frenando bruscamente davanti a Juliette."
  },
  AvgDialog_43789_Content_3 = {
    Text = "Temo ci sia una questione urgente, tutti quanti."
  },
  AvgDialog_43789_Content_4 = {
    Text = "Quei mostri che abbiamo appena respinto — i locali li chiamano Nubia — un intero contingente sta puntando il campo in questo momento."
  },
  AvgDialog_43789_Content_5 = {
    Text = "Per la sicurezza del campo, devo eliminarli."
  },
  AvgDialog_43789_Content_6 = {
    Text = "Vi dispiace se veniamo con voi?"
  },
  AvgDialog_43789_Content_7 = {
    Text = "Non vorrei essere di peso per voi."
  },
  AvgDialog_43789_Content_8 = {
    Text = "Julie, i tuoi problemi sono i nostri problemi. Non ti preoccupare! Qualche Nubia non è certo una scommessa."
  },
  AvgDialog_43802_Content_1 = {
    Text = "Questo luogo..."
  },
  AvgDialog_43802_Content_2 = {
    Text = [[
Il mare di coscienza de L'albero madre.
Risalendo dalla sua bara, eccoci qui.]]
  },
  AvgDialog_43802_Content_3 = {
    Text = "Questo bambino... Si è avvicinato troppo alle radici dell'Albero Madre, alla deriva dal nostro mondo. Non riesce più ad adattarsi."
  },
  AvgDialog_43802_Content_4 = {
    Text = "Fanghiglia d'Argento ribolle in un'Ondata, trascinandoti verso rive lontane."
  },
  AvgDialog_43802_Content_5 = {
    Text = "Senti quei suoni?"
  },
  AvgDialog_43802_Content_6 = {
    Text = "Gocce d'acqua. Nuclei d'Argento che vibrano in Risonanza."
  },
  AvgDialog_43802_Content_7 = {
    Text = "Ascolta più attentamente."
  },
  AvgDialog_43802_Content_8 = {
    Text = "Odi vari gridi di vita: il vagito di un neonato, l'ultima lacrima di un anziano prima della morte..."
  },
  AvgDialog_43802_Content_9 = {
    Text = "Quelle lacrime si trasformano in un istante in vuoti triangolari di escrescenze della Dissoluzione, eruttando verso di te con velocità feroce e Furia."
  },
  AvgDialog_43803_Content_1 = {Text = "Banchetto"},
  AvgDialog_43803_Content_10 = {
    Text = "Dovreste riposare."
  },
  AvgDialog_43803_Content_100 = {
    Text = "Un rintocco di campana risuona dal nulla; la lucidità irrompe."
  },
  AvgDialog_43803_Content_101 = {
    Text = [[
Un terrore travolgente ti invade mentre ti liberi dalla presa di Thais.
Voltandoti, la trovi ancora a fissarti con brama febbrile.]]
  },
  AvgDialog_43803_Content_102 = {
    Text = "Ramona si drizza di scatto, il suo sguardo gelido si fissa sull'ardore di Thais."
  },
  AvgDialog_43803_Content_103 = {
    Text = "<Change>{Male=Lui,Female=Lei} non è un vostro suddito."
  },
  AvgDialog_43803_Content_104 = {
    Text = "<Change>Non potete costringer{Male=lo,Female=la}..."
  },
  AvgDialog_43803_Content_105 = {
    Text = "<Change>Shu...-Ni...urath..."
  },
  AvgDialog_43803_Content_106 = {
    Text = "Sebbene filtrata dalla gola di Ramona, lo sai d'istinto: questa lingua non è affatto la sua.\nAppartiene all'Essere Superiore che dimora in lei."
  },
  AvgDialog_43803_Content_107 = {
    Text = "Va bene, sei proprio un guastafeste.\nChe peccato, lasciar andare sprecato un così bell'alberello..."
  },
  AvgDialog_43803_Content_108 = {
    Text = "Thais rilascia il tuo braccio con riluttanza persistente, abbandonando la tenda tra un mormorio canzonatorio."
  },
  AvgDialog_43803_Content_109 = {
    Text = [[
Ci rivedremo.
La prossima volta, non tirarti indietro.]]
  },
  AvgDialog_43803_Content_11 = {
    Text = "No—per qualche ragione, una voce continua a dirmi che questa indagine... devo essere io a condurla."
  },
  AvgDialog_43803_Content_12 = {
    Text = "Il tono di Ramona non ammette repliche, e tu condividi la stessa Diffidenza; logica e sentimento impediscono parimenti ogni obiezione."
  },
  AvgDialog_43803_Content_13 = {
    Text = "Dov'è Ryker?"
  },
  AvgDialog_43803_Content_14 = {
    Text = "È là fuori davanti, in gran confidenza con quegli Aram.\nGrazie a lui, almeno siamo riusciti a ricostruire la loro situazione."
  },
  AvgDialog_43803_Content_15 = {
    Text = "Come sappiamo, l'Albero Madre svanì da un giorno all'altro anni fa. Poco dopo, il Muro della Tempesta ne velò le rovine—la sorgente del Fiume sacro."
  },
  AvgDialog_43803_Content_16 = {
    Text = "Non molto tempo fa, Juliette giunse come l'inviata della leggenda. Guidata dai sogni, disperse i branchi di Nubia per gli Aramiti, avvicinandosi al Muro della Tempesta."
  },
  AvgDialog_43803_Content_17 = {
    Text = "Eppure non sono riusciti a violarlo."
  },
  AvgDialog_43803_Content_18 = {
    Text = "Tutto questo sopravvive nei canti tradizionali degli Aramiti."
  },
  AvgDialog_43803_Content_19 = {
    Text = "Il pallore di Ramona si approfondisce a ogni parola."
  },
  AvgDialog_43803_Content_2 = {
    Text = "Festino del falò?"
  },
  AvgDialog_43803_Content_20 = {
    Text = "Lasciate che Doll spieghi il testo."
  },
  AvgDialog_43803_Content_21 = {
    Text = "Non reciterò quelle sciocchezze.\nPer una recitazione stabile, c'è uno specialista migliore."
  },
  AvgDialog_43803_Content_22 = {
    Text = "Erica, al vostro servizio—"
  },
  AvgDialog_43803_Content_23 = {
    Text = "La morte si avvicina. La Dissoluzione albeggia."
  },
  AvgDialog_43803_Content_24 = {
    Text = "Aspettate—"
  },
  AvgDialog_43803_Content_25 = {
    Text = "Erica prosegue, sorda al tuo comando, la sua voce un ronzio meccanico."
  },
  AvgDialog_43803_Content_26 = {
    Text = "Le Spoglie della Madre svaniscono, sangue e seme vagano per la Terra, divorati da bestie appena nate."
  },
  AvgDialog_43803_Content_27 = {
    Text = "Cieli e dèi si ammantano di tenebra, finché giunge l'inviato straniero."
  },
  AvgDialog_43803_Content_28 = {
    Text = "Inviata—discende—scricchiolio—discende—scricchiolio—hee hee, inviata—"
  },
  AvgDialog_43803_Content_29 = {
    Text = "Il timbro stridulo e privo di emozione riecheggia in modo innaturale nella tenda."
  },
  AvgDialog_43803_Content_3 = {
    Text = "Il volto di Juliette si vela di esitazione."
  },
  AvgDialog_43803_Content_30 = {
    Text = "Un momento."
  },
  AvgDialog_43803_Content_31 = {
    Text = "Un allarme risuona, seguito da un fruscio di pagine, viti che girano, metallo che cozza."
  },
  AvgDialog_43803_Content_32 = {
    Text = "Mi scuso. Ho appena controllato la diagnostica di Erica, ma non è ancora emersa alcuna fonte del guasto."
  },
  AvgDialog_43803_Content_33 = {
    Text = "Non importa. L'ultimo verso del canto... me ne occupo io."
  },
  AvgDialog_43803_Content_34 = {
    Text = "...L'Albero Madre rianima il Fiume sacro, coronando il Defunto. La sua stirpe farà ritorno ad Aram."
  },
  AvgDialog_43803_Content_35 = {
    Text = "Dal punto di vista dell'efficienza, menzionare prima che l'avevi già sentito ci avrebbe risparmiato tempo."
  },
  AvgDialog_43803_Content_36 = {
    Text = "Cosa avete visto nella tenda della Regina?"
  },
  AvgDialog_43803_Content_37 = {
    Text = "Prima che tu possa rispondere, richiami ferventi risuonano dall'esterno."
  },
  AvgDialog_43803_Content_38 = {
    Text = "Onorevoli ospiti, il festino vi attende!"
  },
  AvgDialog_43803_Content_39 = {
    Text = "Ti fermi un istante, poi ti chini all'orecchio di Ramona, sussurrando la verità cruciale."
  },
  AvgDialog_43803_Content_4 = {
    Text = "Come dicevo prima, gli Aramiti, essendo una tribù primitiva, custodiscono molte tradizioni \"peculiari\" che un Estraneo potrebbe faticare a comprendere."
  },
  AvgDialog_43803_Content_40 = {
    Text = "I Resti dell'Albero Madre giacciono nella tenda della Regina."
  },
  AvgDialog_43803_Content_41 = {
    Text = "Con il tuo fascino e il tuo ingegno, conquisteresti persino il Capo Alva!"
  },
  AvgDialog_43803_Content_42 = {
    Text = "Troppo gentile—ho sentito che la vera narratrice qui è la signorina Juliette."
  },
  AvgDialog_43803_Content_43 = {
    Text = "Intendete l'inviato?"
  },
  AvgDialog_43803_Content_44 = {
    Text = "Le sue storie forse non reggono il confronto con la tua filastrocca della \"Scommessa Finale\", ma chiacchierare con lei è come una brezza di primavera."
  },
  AvgDialog_43803_Content_45 = {
    Text = "E quell'\"Occhio Invertito Senza Pupilla\"... risveglia qualcosa di profondo, che proviene direttamente dall'anima..."
  },
  AvgDialog_43803_Content_46 = {
    Text = "Oh? Parlate di me?"
  },
  AvgDialog_43803_Content_47 = {
    Text = "Medinet non fa che decantare il vostro dono per i racconti."
  },
  AvgDialog_43803_Content_48 = {
    Text = "Vi dispiace se mi unisco?"
  },
  AvgDialog_43803_Content_49 = {
    Text = "Il piacere è tutto mio, mia signora."
  },
  AvgDialog_43803_Content_5 = {
    Text = "Il festino del falò ne è l'esempio più emblematico."
  },
  AvgDialog_43803_Content_50 = {
    Text = "Le incursioni dei Nubia si sono intensificate ultimamente. Dovremmo celebrare il rito del falò."
  },
  AvgDialog_43803_Content_51 = {
    Text = [[
Non fare il musone! Ospiti nuovi sono di buon auspicio.
Su, bevine un po'!]]
  },
  AvgDialog_43803_Content_52 = {
    Text = [[
Anche tu, ospite d'onore! Prendine ancora!
Goditi il banchetto; ti offriremo il meglio che abbiamo!]]
  },
  AvgDialog_43803_Content_53 = {Text = "Applausi!"},
  AvgDialog_43803_Content_54 = {
    Text = "Non bevo..."
  },
  AvgDialog_43803_Content_55 = {
    Text = "Alzi il calice, brindando con i chiassosi Aramiti."
  },
  AvgDialog_43803_Content_56 = {
    Text = "Quando la loro Guardia cala, rovesci il contenuto con discrezione."
  },
  AvgDialog_43803_Content_57 = {
    Text = "Le Spoglie dell'Albero Madre riposano a pochi passi dai festeggiamenti. Non è certo il momento per l'Indulgenza."
  },
  AvgDialog_43803_Content_58 = {
    Text = "Che peccato! Solo un Rito con gli spiriti raggiunge la perfezione!"
  },
  AvgDialog_43803_Content_59 = {
    Text = "Per quanto insistano a farti assaggiare la loro bevanda, declini cortesemente."
  },
  AvgDialog_43803_Content_6 = {
    Text = "I dettagli... li scoprirete stanotte."
  },
  AvgDialog_43803_Content_60 = {
    Text = "Le Spoglie dell'Albero Madre riposano a pochi passi dai festeggiamenti. Non è certo il momento per l'Indulgenza."
  },
  AvgDialog_43803_Content_61 = {Text = "..."},
  AvgDialog_43803_Content_62 = {Text = "..."},
  AvgDialog_43803_Content_63 = {
    Text = "Mentre lo Spirito degli Aramiti si accende, il Festino sfocia nella Frenesia."
  },
  AvgDialog_43803_Content_64 = {
    Text = "I guerrieri sollevano le donne aramite come palanchini, sfilandole in parata tra la calca."
  },
  AvgDialog_43803_Content_65 = {
    Text = "Donne dallo sguardo velato colgono grappoli d'uva lucente, lanciandoli tra la Folla ridendo."
  },
  AvgDialog_43803_Content_66 = {
    Text = "Oh, bene! Qui, lanciatene un paio anche a me!"
  },
  AvgDialog_43803_Content_67 = {
    Text = "Come se lo avesse udito, la Donna guida i suoi portatori verso Ryker, poi si tuffa tra le sue braccia."
  },
  AvgDialog_43803_Content_68 = {
    Text = "Piano, signorina! Temo che il mio Corpo non regga il vostro peso..."
  },
  AvgDialog_43803_Content_69 = {
    Text = "Prima che Ryker finisca, la scena ti gela di Shock."
  },
  AvgDialog_43803_Content_7 = {
    Text = "...Quindi la migrazione degli Aramiti punta anche al vecchio sito dell'Albero Madre?"
  },
  AvgDialog_43803_Content_70 = {
    Text = "Lei si strappa la veste, la pelle nuda premuta contro di lui."
  },
  AvgDialog_43803_Content_71 = {
    Text = "Il suo gesto incendia l'aria: tutti gli Aramiti si spogliano di abiti e armature, e il raduno si dissolve in un mare di abbandono carnale."
  },
  AvgDialog_43803_Content_72 = {
    Text = "Con Ryker pietrificato sul posto, lei non perde un istante — si lancia dritta verso il guerriero aramita al suo fianco, i suoi gemiti osceni echeggianti nel frastuono."
  },
  AvgDialog_43803_Content_73 = {Text = "?!"},
  AvgDialog_43803_Content_74 = {
    Text = "Avanti, unitevi a noi — assaporate l'estasi più profonda del falò!"
  },
  AvgDialog_43803_Content_75 = {
    Text = "Corsa! Tornate alla tenda di Ramona!"
  },
  AvgDialog_43803_Content_76 = {
    Text = "La mente vuota, dai retta al grido di Ryker, correndo — no, fuggendo — verso Ramona con tutta la fretta possibile..."
  },
  AvgDialog_43803_Content_77 = {
    Text = "Fuori dalla tenda, la donna che si prendeva cura di Ramona è svanita."
  },
  AvgDialog_43803_Content_78 = {
    Text = "Ramona giace in preda al delirio febbrile, risparmiata dalla follia del rito—forse una grazia."
  },
  AvgDialog_43803_Content_79 = {
    Text = "Quello è..."
  },
  AvgDialog_43803_Content_8 = {
    Text = "Esatto—e nemmeno loro riescono a perforare il Muro della Tempesta."
  },
  AvgDialog_43803_Content_80 = {
    Text = "Il rito del falò. Già...\nIl rito del falò degli Aram è un rituale di accoppiamento primordiale."
  },
  AvgDialog_43803_Content_81 = {
    Text = "Ci siamo allontanati abbastanza dal caos qui—monterò la guardia fuori, terrò lontani gli sbandati."
  },
  AvgDialog_43803_Content_82 = {
    Text = "Tu resta con Ramona."
  },
  AvgDialog_43803_Content_83 = {
    Text = "Questi primitivi... folli."
  },
  AvgDialog_43803_Content_84 = {
    Text = "Contro il frastuono che giunge da fuori, la tenda piomba in una quiete inquietante, rotta solo dai respiri affannosi di Ramona per il calore."
  },
  AvgDialog_43803_Content_85 = {
    Text = "Gemiti e grida soffocate filtrano attraverso la pesante tela, suscitando in te un tumulto sgradito."
  },
  AvgDialog_43803_Content_86 = {Text = "...Ryker?"},
  AvgDialog_43803_Content_87 = {
    Text = "Che peccato — speravate in qualcun altro?"
  },
  AvgDialog_43803_Content_88 = {
    Text = "La Regina di Aram—Thais—scosta il lembo della tenda ed entra, premendosi contro di te senza ritegno. Il suo velo diafano si avvinghia al tuo braccio, un invito sfrontato."
  },
  AvgDialog_43803_Content_89 = {
    Text = "Venite — abbracciate la stirpe di Aram, diventate uno di noi."
  },
  AvgDialog_43803_Content_9 = {
    Text = "Ah, Custode. Doll e io stavamo analizzando i prossimi passi."
  },
  AvgDialog_43803_Content_90 = {
    Text = "Vieni da me, abbracciami... dammi il tuo sangue, il tuo seme..."
  },
  AvgDialog_43803_Content_91 = {
    Text = "Il fuoco danza nei suoi occhi ferventi, le guance arrossate tradiscono una brama febbrile."
  },
  AvgDialog_43803_Content_92 = {
    Text = "Solo una goccia — una volta che la nostra carne si mescola, Lei ci concederà il futuro che bramiamo..."
  },
  AvgDialog_43803_Content_93 = {
    Text = "Lascia che... generiamo eredi per la tribù, e condividiamo un'eternità di..."
  },
  AvgDialog_43803_Content_94 = {
    Text = "Il tuo cervello urla rifiuto. Non sai nulla delle usanze aramite, e questa follia potrebbe trascinarti nell'abisso."
  },
  AvgDialog_43803_Content_95 = {
    Text = "Eppure le tue membra non obbediscono; il richiamo della sirena comanda carne e spirito, destando impulsi primordiali a lungo sopiti dentro di te."
  },
  AvgDialog_43803_Content_96 = {
    Text = "Per quanto lucido tu sia, il mondo nuota in una foschia d'ebbrezza: bellezza sfocata, leggerezza eterea, ossessionata soltanto dal richiamo primordiale della vita."
  },
  AvgDialog_43803_Content_97 = {
    Text = "Riprodursi, riprodursi."
  },
  AvgDialog_43803_Content_98 = {
    Text = "<RedBig:Propagarsi, propagarsi!>"
  },
  AvgDialog_43803_Content_99 = {
    Text = "<Big:Disperdi i semi sulla terra, lascia che la nostra <Red:stirpe> inondi Kadath!>"
  },
  AvgDialog_43804_Content_1 = {
    Text = "Non preoccupatevi. Lady Alva è severa, ma giusta."
  },
  AvgDialog_43804_Content_2 = {
    Text = [[
Parleremo con calma nella mia tenda dopo.
Prima, liberiamoci di questi Nubia.]]
  },
  AvgDialog_43804_Content_3 = {
    Text = "Ti ho visto in azione. Sbrigare queste creature immonde non dovrebbe essere un problema per te, giusto?"
  },
  AvgDialog_43805_Content_1 = {
    Text = "Proliferazione"
  },
  AvgDialog_43805_Content_10 = {
    Text = "Il rumore fuori è cessato."
  },
  AvgDialog_43805_Content_11 = {
    Text = "Visitare la Capotribù Alva"
  },
  AvgDialog_43805_Content_12 = {
    Text = "Consultarsi con Juliette"
  },
  AvgDialog_43805_Content_13 = {
    Text = "Già, girare in tondo non servirà a nulla."
  },
  AvgDialog_43805_Content_14 = {
    Text = "Ryker scosta il lembo della tenda, il corpo che si irrigidisce a metà del passo."
  },
  AvgDialog_43805_Content_15 = {
    Text = "Che succede, Ryker?"
  },
  AvgDialog_43805_Content_16 = {
    Text = "Ryker non risponde. La curiosità ti spinge a seguirlo."
  },
  AvgDialog_43805_Content_17 = {
    Text = "Trae un respiro rauco, forzando un sussurro roco dalla gola."
  },
  AvgDialog_43805_Content_18 = {
    Text = "Voi due... restate indietro."
  },
  AvgDialog_43805_Content_19 = {
    Text = "Andiamo, Ryker. Non possiamo restare rintanati in questa tenda per sempre..."
  },
  AvgDialog_43805_Content_2 = {
    Text = "Quando mi sono... addormentato?"
  },
  AvgDialog_43805_Content_20 = {
    Text = "Le vostre parole vacillano."
  },
  AvgDialog_43805_Content_21 = {
    Text = "Ryker aveva ragione. Ti penti di aver posato gli occhi su questo.\nMa l'atrocità ti impedisce di distogliere lo sguardo."
  },
  AvgDialog_43805_Content_22 = {
    Text = "Vedi un inferno di Sangue. Un orribile strascico di procreazione. Un Incubo blasfemo che sfida i legami umani e le leggi della natura."
  },
  AvgDialog_43805_Content_23 = {
    Text = "Persino una tana di parassiti non regge il confronto con la carneficina: arti di neonati e placente si contorcono in gusci deformi, un liquame Cremisi che filtra nella trama del deserto."
  },
  AvgDialog_43805_Content_24 = {
    Text = "L'aria puzza di fluidi intrisi di ferro che corrode l'anima, rivoltandoti le viscere."
  },
  AvgDialog_43805_Content_25 = {
    Text = "Una raffica solleva il lembo della tenda della Regina, e Thais emerge languidamente."
  },
  AvgDialog_43805_Content_26 = {
    Text = "Il primo raggio dell'alba perfora il cielo mentre lei indica l'orizzonte squarciato dalle dune."
  },
  AvgDialog_43805_Content_27 = {
    Text = "In quell'istante, lamenti erompono da innumerevoli tende — vagiti di neonati che intrecciano una sinfonia di vita Fragile."
  },
  AvgDialog_43805_Content_28 = {
    Text = "Eppure nessuna gioia si desta in te, solo un gelo dalla Corona dei capelli alla punta dei piedi."
  },
  AvgDialog_43805_Content_29 = {
    Text = "Le incursioni dei Nubia si sono intensificate ultimamente. Dovremmo celebrare il rito del falò."
  },
  AvgDialog_43805_Content_3 = {
    Text = "Il Silenzio avvolge la tenda; la distorta, febbrile baldoria della notte scorsa svanisce come un Incubo che si dissolve."
  },
  AvgDialog_43805_Content_30 = {
    Text = [[
Quello non era un discorso motivazionale, ma un raduno di riproduzione per ingrossare le fila.
Cosa vedono nella vita? Un semplice strumento di sopravvivenza?]]
  },
  AvgDialog_43805_Content_31 = {
    Text = "I documenti legano l'Autorità dell'Eone del Desiderio alla riproduzione e alla propagazione."
  },
  AvgDialog_43805_Content_32 = {
    Text = "L'Albero Madre radicato alla sorgente del fiume Karage — il Fiume sacro — ne arricchisce le rive e le sponde, donando agli Aramiti una fertilità fuori dall'ordinario."
  },
  AvgDialog_43805_Content_33 = {
    Text = "Sostenuto dal nutrimento del Fiume sacro, il Sangue di Aram sopporta le aspre distese desolate di Remouahe attraverso le generazioni."
  },
  AvgDialog_43805_Content_34 = {
    Text = "Nutrimento, fertilità, resistenza... queste parole tenere si manifestano in tanta lordura e crudeltà."
  },
  AvgDialog_43805_Content_35 = {
    Text = "Le nostre opzioni sono chiare."
  },
  AvgDialog_43805_Content_36 = {
    Text = "Restare con la marcia degli Aramiti, o staccarsi e improvvisare il nostro obiettivo."
  },
  AvgDialog_43805_Content_37 = {
    Text = "Scartare feti malformati per massimizzare i tassi di allevamento? Agli occhi della civiltà, è un massacro — so che non puoi ignorarlo."
  },
  AvgDialog_43805_Content_38 = {
    Text = "E poi, gli enigmi abbondano in questo caos. Hai notato il tasso di deformità?"
  },
  AvgDialog_43805_Content_39 = {
    Text = "Il dono dell'Albero Madre — concepimento e nascita in una sola notte — perché produce a malapena un neonato sano su dieci?"
  },
  AvgDialog_43805_Content_4 = {
    Text = "Non ne ho idea — mi sono svegliata e vi ho trovato privo di sensi."
  },
  AvgDialog_43805_Content_40 = {
    Text = "Visto? Dal punto di vista di un investigatore o di un detective, la prima pista è certa.\nDobbiamo restare vicini all'obiettivo e alla verità, giusto?"
  },
  AvgDialog_43805_Content_41 = {
    Text = "Prima che tu decida, la carovana si agita — dalla tenda del capo, gli Aramiti corrono tra i rifugi, urlando ordini. Tutti escono dalle tende, preparando l'equipaggiamento."
  },
  AvgDialog_43805_Content_42 = {
    Text = "Che è successo?"
  },
  AvgDialog_43805_Content_43 = {
    Text = "Nubia! Un enorme branco di Nubia sta colpendo il campo! Le guardie in prima linea stanno cedendo!"
  },
  AvgDialog_43805_Content_44 = {
    Text = "Proprio al momento giusto. Hanno appena concluso il festino, e i Nubia colpiscono immediatamente?"
  },
  AvgDialog_43805_Content_45 = {
    Text = "Chi lo sa? È sempre così; quelle bestie maledette non danno mai tregua!"
  },
  AvgDialog_43805_Content_46 = {
    Text = "Anche voi dovreste scappare! Nessuno ha tempo di proteggervi!"
  },
  AvgDialog_43805_Content_47 = {
    Text = "Dobbiamo vedere Alva. Dov'è?"
  },
  AvgDialog_43805_Content_48 = {
    Text = "La Capotribù è in prima linea, al comando!"
  },
  AvgDialog_43805_Content_49 = {
    Text = "Fianco sinistro, in formazione! La migrazione non è finita — non lasciate passare nessun Nubia!"
  },
  AvgDialog_43805_Content_5 = {
    Text = "Dov'è Ryker?"
  },
  AvgDialog_43805_Content_50 = {
    Text = "Naen, tieni la tua posizione! Se le tue membra tremano, arretra — Vajet, prendi il comando!"
  },
  AvgDialog_43805_Content_51 = {
    Text = "Cosa ci fai qui?\nNon vedi che il fronte è un caos?"
  },
  AvgDialog_43805_Content_52 = {
    Text = "Non diamo il benvenuto agli ospiti che rifiutano di dare alla luce il nostro \"Seme.\" Ora toglietevi dai piedi!"
  },
  AvgDialog_43805_Content_53 = {
    Text = "Capotribù Alva, una parola, vi prego?"
  },
  AvgDialog_43805_Content_54 = {
    Text = "L'intrusione di %player% nella tenda della Regina è stata solo un incidente. La Regina non si è offesa, correggere?"
  },
  AvgDialog_43805_Content_55 = {
    Text = "Se dobbiamo attribuire colpe, ne condivido metà per aver{Male=lo,Female=la} lasciat{Male=o,Female=a} sol{Male=o,Female=a} senza spiegare le regole."
  },
  AvgDialog_43805_Content_56 = {
    Text = "Fissi Juliette, e lei ti rivolge un bagliore con un sottile scuotimento del capo, avvertendoti di tenere la lingua a freno."
  },
  AvgDialog_43805_Content_57 = {
    Text = "Non riesci a comprendere perché ti abbia difeso, ma non c'è ragione di rifiutare."
  },
  AvgDialog_43805_Content_58 = {
    Text = "Con i colpi dei Nubia che si intensificano, potrebbero dare una mano contro queste abominazioni."
  },
  AvgDialog_43805_Content_59 = {Text = "..."},
  AvgDialog_43805_Content_6 = {
    Text = "Ramona accenna con un cenno verso il lembo della tenda."
  },
  AvgDialog_43805_Content_60 = {
    Text = "Possono seguirvi, allora."
  },
  AvgDialog_43805_Content_61 = {
    Text = [[
Devi tenerli lontani dalla vista della tenda principale.
O le conseguenze saranno peggiori dell'esilio.]]
  },
  AvgDialog_43805_Content_7 = {
    Text = "Ryker è accasciato contro l'ingresso in Sonno Profondo, e si scuote al tuo movimento. Le sue orecchie vellutate fremono, le ciglia hanno un Battito d'Ali prima che i suoi occhi lupeschi a fessura si socchiudano."
  },
  AvgDialog_43805_Content_8 = {
    Text = "Il... rito di ieri — non era un sogno, vero?"
  },
  AvgDialog_43805_Content_9 = {
    Text = "Per il decoro di un gentiluomo di Londinium, non giudicherei mai alla leggera le usanze altrui, ma il rito di quei primitivi... ha oltrepassato ogni limite."
  },
  AvgDialog_43806_Content_1 = {
    Text = "Se questi bruti arrivano a ondate, le mie vecchie ossa sono spacciate."
  },
  AvgDialog_43806_Content_10 = {
    Text = "Un momento, quello è—"
  },
  AvgDialog_43806_Content_11 = {
    Text = "Una figura trascina la Nubia attraverso le sabbie; il cappuccio scivola nel vento, rivelando riccioli dorati che brillano al chiaro di luna."
  },
  AvgDialog_43806_Content_12 = {Text = "William!"},
  AvgDialog_43806_Content_2 = {
    Text = "Alva dice che questi sono solo capi di piccoli branchi—la vera minaccia è ben peggiore."
  },
  AvgDialog_43806_Content_3 = {
    Text = "Basta—lasciami nell'ignoranza e nella spensieratezza finché non li vedremo."
  },
  AvgDialog_43806_Content_4 = {
    Text = "Non è il momento di rilassarsi! %player%, laggiù!"
  },
  AvgDialog_43806_Content_5 = {
    Text = "Le sagome grottesche a cui ormai ti sei assuefatto emergono dalle dune avvolte nella notte, avanzando barcollanti verso di te."
  },
  AvgDialog_43806_Content_6 = {
    Text = "Altri sbandati?"
  },
  AvgDialog_43806_Content_7 = {
    Text = "Venite avanti! Vi mostrerò cos'è una serie di vittorie!"
  },
  AvgDialog_43806_Content_8 = {
    Text = "Aspetta. Qualcosa non torna..."
  },
  AvgDialog_43806_Content_9 = {
    Text = "A guardarla da vicino, i movimenti di questa Nubia sono trascinati, innaturalmente rigidi."
  },
  AvgDialog_43807_Content_1 = {Text = "Sentiero"},
  AvgDialog_43807_Content_10 = {
    Text = "Proprio come in battaglia..."
  },
  AvgDialog_43807_Content_11 = {
    Text = "Un fallimento."
  },
  AvgDialog_43807_Content_12 = {
    Text = "Scommetto che voi due non vedete l'ora di sentire l'analisi del veterano."
  },
  AvgDialog_43807_Content_13 = {
    Text = "William si sistema gli occhiali, annuendo nella tua direzione."
  },
  AvgDialog_43807_Content_14 = {
    Text = "Questo è l'unico esemplare intatto di Nubia che siamo riusciti a recuperare finora."
  },
  AvgDialog_43807_Content_15 = {
    Text = "Prima di quest'anno, gli avvistamenti erano quasi leggenda. La sua emersione nel Deserto di Remouahe è recente, eppure ha invaso le distese desolate in pochissimo tempo, sconfinando nelle terre di Aram."
  },
  AvgDialog_43807_Content_16 = {
    Text = "La sola mutazione non spiega la sua ascesa; un'origine ingegnerizzata si adatta meglio alla tempistica e alle caratteristiche."
  },
  AvgDialog_43807_Content_17 = {
    Text = "Stai dicendo che qualcuno sta creando queste Nubia?"
  },
  AvgDialog_43807_Content_18 = {
    Text = "William annuisce, un lampo di approvazione nel tuo calcolo deduttivo."
  },
  AvgDialog_43807_Content_19 = {
    Text = "E anche a coprire le tracce. Taglia una parte qualsiasi, e i viticci ricuciono la ferita dall'interno, nascondendo le cicatrici."
  },
  AvgDialog_43807_Content_2 = {
    Text = "Nel cuore della tenda grezza e primitiva, la forma inerte della Nubia incombe come una montagna nera di carne; la luce fioca della lampada torce persino le ombre in minacce grottesche."
  },
  AvgDialog_43807_Content_20 = {
    Text = "Il danno fatale innesca un'evaporazione rapida: nessuna traccia da studiare.\nNota che la D-melma standard non svanisce così in fretta."
  },
  AvgDialog_43807_Content_21 = {
    Text = "Il loro \"creatore\" nasconde qualcosa."
  },
  AvgDialog_43807_Content_22 = {
    Text = "La struttura è intrigante, ma sono più affascinato dai loro schemi comportamentali."
  },
  AvgDialog_43807_Content_23 = {
    Text = "In questi giorni ho messo sotto torchio gli Aramiti. Mi hanno detto che gli sciami di Nubia attaccano ogni volta che restano troppo a lungo nello stesso posto, o celebrano un rito."
  },
  AvgDialog_43807_Content_24 = {
    Text = "L'istinto mi dice che queste creature stanno spingendo gli Aramiti da qualche parte."
  },
  AvgDialog_43807_Content_25 = {
    Text = "William spiega una mappa, segnando i focolai di Nubia."
  },
  AvgDialog_43807_Content_26 = {
    Text = "Considera le rotte migratorie degli Aram."
  },
  AvgDialog_43807_Content_27 = {
    Text = "Ryker fissa fili rossi con delle puntine, tracciando il percorso dai racconti degli Aramiti."
  },
  AvgDialog_43807_Content_28 = {
    Text = "Presagi neri inseguono la linea cremisi, premendo inesorabili, sospingendola verso le sorgenti del Fiume sacro."
  },
  AvgDialog_43807_Content_29 = {
    Text = "Il tuo istinto raramente sbaglia."
  },
  AvgDialog_43807_Content_3 = {
    Text = "William estrae un kit chirurgico dal rivestimento dei suoi schinieri: bisturi, forbici, pinze a denti fini, emostatiche schierate come un plotone d'acciaio."
  },
  AvgDialog_43807_Content_30 = {
    Text = "La sorgente del Fiume sacro. Avvolta nel Muro della Tempesta."
  },
  AvgDialog_43807_Content_31 = {
    Text = "Qualcuno non tollera che gli Aramiti indugino al di fuori — ne restringe il raggio d'azione, costringendoli a una breccia."
  },
  AvgDialog_43807_Content_32 = {
    Text = "L'Enigma prende forma: il perché e il come sono ora evidenti."
  },
  AvgDialog_43807_Content_33 = {
    Text = "Ora, la questione cruciale: chi?"
  },
  AvgDialog_43807_Content_34 = {
    Text = [[
Per ora gli indizi sono troppo pochi.
Sincronizziamo prima gli avvistamenti recenti; ci aiuteranno a decidere meglio.]]
  },
  AvgDialog_43807_Content_35 = {Text = "..."},
  AvgDialog_43807_Content_36 = {Text = "..."},
  AvgDialog_43807_Content_37 = {
    Text = "Ci servono più informazioni sulle Nubia."
  },
  AvgDialog_43807_Content_38 = {
    Text = "La missione principale resta invariata: indagare sui Resti dell'Albero Madre nella tenda della Regina e sabotare quando i tempi saranno maturi."
  },
  AvgDialog_43807_Content_39 = {
    Text = "Proseguirò la mia Ricerca sulle Nubia."
  },
  AvgDialog_43807_Content_4 = {
    Text = "Non mi aspettavo che portassi tutto questo con te, William. Stai pensando di cambiare carriera e diventare guaritore?"
  },
  AvgDialog_43807_Content_40 = {
    Text = "Qualcosa mi dice che gli Aramiti e la verità sull'Albero Madre si celano dietro le origini di queste creature."
  },
  AvgDialog_43807_Content_41 = {
    Text = "William si volta, indossando il mantello."
  },
  AvgDialog_43807_Content_42 = {
    Text = "Te ne vai già, William?"
  },
  AvgDialog_43807_Content_43 = {
    Text = [[
Prima dell'alba.
Attento: non farlo sapere a Juliette.]]
  },
  AvgDialog_43807_Content_44 = {
    Text = "William si china sotto il lembo della tenda, quasi scontrandosi con Il Nuovo Arrivato."
  },
  AvgDialog_43807_Content_45 = {
    Text = "Dal nostro primo incontro presso il Fiume sacro, ho spianato il vostro cammino senza arrecarvi danno. Allora perché tanta diffidenza, signor William?"
  },
  AvgDialog_43807_Content_46 = {
    Text = "La tensione si avvolge nella tenda angusta; il Silenzio incombe, e la brezza del deserto, un tempo rovente, si fa gelida."
  },
  AvgDialog_43807_Content_47 = {
    Text = "Juliette rompe il Silenzio dopo qualche secondo."
  },
  AvgDialog_43807_Content_48 = {
    Text = "Scherzavo — non c'è bisogno di irrigidirsi."
  },
  AvgDialog_43807_Content_49 = {
    Text = "Signorina Juliette, esagerate. Ci siamo divertiti un mondo insieme; William è solo un lupo solitario, detesta mescolarsi con gli estranei..."
  },
  AvgDialog_43807_Content_5 = {
    Text = "William ignora la battuta, le sopracciglia aggrottate per la concentrazione mentre pratica la prima incisione accurata."
  },
  AvgDialog_43807_Content_50 = {
    Text = "Ryker tesse frottole con disinvoltura; scorgi Ramona che alza gli occhi al cielo dalla sua branda."
  },
  AvgDialog_43807_Content_51 = {
    Text = "Ehm — dunque, comunque, la visita notturna della signorina Juliette immagino significhi qualcosa di urgente?"
  },
  AvgDialog_43807_Content_52 = {
    Text = "Nulla di sconvolgente — venite, vi racconterò i dettagli nella mia tenda."
  },
  AvgDialog_43807_Content_6 = {
    Text = "La lama affonda nella massa della Nubia—nessun fiotto atteso di melma nera."
  },
  AvgDialog_43807_Content_7 = {
    Text = "Teso come un filo, William spinge il taglio più in profondità, poi trascina verso il basso—"
  },
  AvgDialog_43807_Content_8 = {
    Text = "Sfrigolìo—"
  },
  AvgDialog_43807_Content_9 = {
    Text = "La Nubia perforata si scioglie in fanghiglia in un istante, evaporando nel nulla; il tavolo risplende immacolato, come se nessuna abominazione lo avesse mai corrotto."
  },
  AvgDialog_43808_Content_1 = {
    Text = "Questo spazio mentale raccoglie ogni Anima aramita dai tempi antichi a oggi."
  },
  AvgDialog_43808_Content_10 = {
    Text = "Juliette si inginocchia accanto alla Culla, intonando un Inno senza parole."
  },
  AvgDialog_43808_Content_11 = {
    Text = "Non ha parole, eppure conosci la melodia."
  },
  AvgDialog_43808_Content_12 = {
    Text = "Culla le fasce tra le braccia, immergendole nel fiume."
  },
  AvgDialog_43808_Content_13 = {
    Text = "Le sabbie seppelliscono in fretta la fragile vita."
  },
  AvgDialog_43808_Content_14 = {
    Text = "La morte si avvicina. La Dissoluzione albeggia."
  },
  AvgDialog_43808_Content_15 = {
    Text = "Il canto bello e malinconico è intessuto di Pianto, e si snoda con il Fiume sacro verso la lontananza."
  },
  AvgDialog_43808_Content_16 = {
    Text = "4:00, Tenda dell'Ospite"
  },
  AvgDialog_43808_Content_17 = {
    Text = "Rivediamo i fatti."
  },
  AvgDialog_43808_Content_18 = {
    Text = "Per gli Aramiti, senza la Rinascita dell'Albero Madre, il Fiume sacro si prosciuga—l'intera Remouahe si trasforma in una distesa desolata senza fine."
  },
  AvgDialog_43808_Content_19 = {
    Text = "Juliette mira a far rinascere l'albero e a integrare gli Aramiti nel mondo moderno."
  },
  AvgDialog_43808_Content_2 = {
    Text = "Gli Aramiti... stanno piangendo?"
  },
  AvgDialog_43808_Content_20 = {
    Text = "Ma le fonti di Daffodil ci hanno avvertito del rischio di una Dissoluzione su scala globale una volta che l'Albero Madre rinasce."
  },
  AvgDialog_43808_Content_21 = {
    Text = "I Resti dell'Albero Madre si trovano nella tenda della Regina. Distruggeteli prima di oltrepassare il Muro della Tempesta, e potremo chiudere la questione con un costo minimo."
  },
  AvgDialog_43808_Content_22 = {
    Text = "Quindi, la Domanda: quanto è affidabile Daffodil? La sua fonte è solida?"
  },
  AvgDialog_43808_Content_23 = {
    Text = "Alistair ha fatto del suo meglio—ha confermato una fuga di notizie deliberata, ma l'accuratezza è tutta da verificare."
  },
  AvgDialog_43808_Content_24 = {
    Text = "Ma bruciare le Spoglie avventatamente potrebbe togliere agli Aramiti l'ultima possibilità di sopravvivenza..."
  },
  AvgDialog_43808_Content_25 = {
    Text = "Nessuno ha alcuna possibilità di sopravvivere alla Dissoluzione.\nNon lasciare che una pietà mal riposta offuschi il tuo giudizio."
  },
  AvgDialog_43808_Content_26 = {
    Text = "Calma, Doll. Farei irruzione nel loro rito sacro per bruciare quell'albero, se me lo chiedessi."
  },
  AvgDialog_43808_Content_27 = {
    Text = "Sono con %player%. Sappiamo troppo poco sugli Aramiti; colpire ora sarebbe avventato."
  },
  AvgDialog_43808_Content_28 = {
    Text = "Continuerò a studiare i Nubia.\n%player%, Ryker: vi affido i resti de L'albero madre."
  },
  AvgDialog_43808_Content_3 = {
    Text = "Sì: i loro spiriti gemono.\nPer il peccato nella nascita, per il terrore nella morte."
  },
  AvgDialog_43808_Content_4 = {
    Text = [[
Se riuscissi a guidare gli Aram oltre il Muro della Tempesta e a reclamare L'albero madre...
Mi incoroneranno come nuovo leader.]]
  },
  AvgDialog_43808_Content_5 = {
    Text = "Allora porrò fine a questo Rito maledetto e libererò per sempre gli Aramiti da questo arido Inferno."
  },
  AvgDialog_43808_Content_6 = {
    Text = "Tutti dimoreranno in un Paradise incontaminato, liberi dal peso dei peccati."
  },
  AvgDialog_43808_Content_7 = {
    Text = "%player%, ti prego, prestami la tua forza."
  },
  AvgDialog_43808_Content_8 = {
    Text = "Ti risvegli dal Sogno. L'Infante tra le braccia di Juliette ha smesso di respirare."
  },
  AvgDialog_43808_Content_9 = {
    Text = "Lascia che ritorni al Fiume sacro."
  },
  AvgDialog_43809_Content_1 = {
    Text = "Flusso delle Origini"
  },
  AvgDialog_43809_Content_10 = {
    Text = "Juliette arruffa la testa lanosa del Ragazzo."
  },
  AvgDialog_43809_Content_11 = {
    Text = "Va bene. Se avete bisogno di qualcosa..."
  },
  AvgDialog_43809_Content_12 = {
    Text = "Il Ragazzo ti osserva con diffidenza."
  },
  AvgDialog_43809_Content_13 = {
    Text = "Svegliatemi pure."
  },
  AvgDialog_43809_Content_14 = {
    Text = "Il ragazzo se ne va; Juliette ti rivolge un sorriso di scuse."
  },
  AvgDialog_43809_Content_15 = {
    Text = "Scusate — a volte diventa troppo protettivo."
  },
  AvgDialog_43809_Content_16 = {
    Text = "Hai indovinato: è quello che cresce più in fretta in questo gruppo."
  },
  AvgDialog_43809_Content_17 = {
    Text = "Al contrario..."
  },
  AvgDialog_43809_Content_18 = {
    Text = "Juliette ti conduce a una semplice Culla."
  },
  AvgDialog_43809_Content_19 = {
    Text = "Guarda questo."
  },
  AvgDialog_43809_Content_2 = {
    Text = "2:00, Tenda dell'Inviato"
  },
  AvgDialog_43809_Content_20 = {
    Text = "È un Infante in fasce; vene scure simili a rami gli serpeggiano sulla pelle."
  },
  AvgDialog_43809_Content_21 = {
    Text = "Non vi è alcuna deformità esteriore, ma il morbo dell'Albero Madre ha già fatto il suo corso."
  },
  AvgDialog_43809_Content_22 = {
    Text = "Prova a toccargli la pelle."
  },
  AvgDialog_43809_Content_23 = {
    Text = "Tocchi la pelle del bambino come ti è stato indicato. Non è la pelle morbida e liscia di un neonato che ti aspettavi, ma la ruvida aridità di corteccia screpolata."
  },
  AvgDialog_43809_Content_3 = {
    Text = "La tenda dell'inviato è piena di giacigli, dove i bambini dormono raggomitolati.\nUn ragazzino vivace si avvicina quando entri."
  },
  AvgDialog_43809_Content_4 = {
    Text = "Lady Juliette, siete tornata."
  },
  AvgDialog_43809_Content_5 = {
    Text = [[
Neferure, mio bravo bambino.
Si sono sistemati tutti?]]
  },
  AvgDialog_43809_Content_6 = {
    Text = "Sì, Lady Juliette."
  },
  AvgDialog_43809_Content_7 = {
    Text = "Questi Fanciulli..."
  },
  AvgDialog_43809_Content_8 = {
    Text = "Fino a oggi, non avevi visto alcun minore tra gli Aramiti."
  },
  AvgDialog_43809_Content_9 = {
    Text = "Neferure, a letto.\nMetterli tutti a nanna non è stato facile: il capo tribù Alva ti ricompenserà domani."
  },
  AvgDialog_43816_Content_1 = {
    Text = "Fiamme inattese"
  },
  AvgDialog_43816_Content_10 = {
    Text = "L'uomo dalla lingua tagliente vi abbaia contro — stordita, che vi dibattete goffamente sotto i riflettori."
  },
  AvgDialog_43816_Content_11 = {
    Text = "Le ragazze intorno a voi ruotano come cigni, ogni movimento aggraziato e sincronizzato, la loro compostezza una danza in sé."
  },
  AvgDialog_43816_Content_12 = {
    Text = "Ma qualcuno si muove come un'anatra selvatica tra i cigni. Voi siete quella sfortunata qualcuno."
  },
  AvgDialog_43816_Content_13 = {
    Text = "Vi rendete subito conto che questo è il corpo di una danzatrice — ma non ricorda nulla. Persino restare in piedi risulta instabile, figurarsi richiamare alla mente i passi intricati."
  },
  AvgDialog_43816_Content_14 = {
    Text = "Sempre un problema... All'altezza della tua reputazione di nostra \"prima ballerina.\""
  },
  AvgDialog_43816_Content_15 = {
    Text = "La prima ballerina? Quella sono... io?"
  },
  AvgDialog_43816_Content_16 = {
    Text = "Nessuno risponde. Le danzatrici scivolano oltre senza fermarsi — finché un gomito non vi urta."
  },
  AvgDialog_43816_Content_17 = {
    Text = "Barcollate di due passi, perdete il ritmo e venite sospinta al bordo del palco. Ma non c'è scampo dagli sguardi critici dal basso —"
  },
  AvgDialog_43816_Content_18 = {
    Text = "Non ci sono file di poltrone sotto il palco. Solo coppie di tavoli e sedie disposti su un pavimento aperto."
  },
  AvgDialog_43816_Content_19 = {
    Text = "Tovaglie di seta con frange luccicano sotto gioielli sparsi; i volti del pubblico mascherato brillano sinistramente sotto le luci."
  },
  AvgDialog_43816_Content_2 = {
    Text = "Un, deux, trois. Un, deux, trois... Molto bene. Preciso ed elegante!"
  },
  AvgDialog_43816_Content_20 = {
    Text = "Che ha quel ragazzino davanti? Ha messo un piede in fallo?"
  },
  AvgDialog_43816_Content_21 = {
    Text = "Hmph... A loro non importa nulla della danza. Non capisci che razza di gente sono?"
  },
  AvgDialog_43816_Content_22 = {
    Text = "Vero. Ah, quel corpo davvero è..."
  },
  AvgDialog_43816_Content_23 = {
    Text = "<Small:Queste persone non sono semplici spettatori...>"
  },
  AvgDialog_43816_Content_24 = {
    Text = "Che fai lì impalato?"
  },
  AvgDialog_43816_Content_25 = {
    Text = "Una mano grassoccia e viziata vi afferra il braccio nudo, trascinandovi nelle ombre dietro il sipario."
  },
  AvgDialog_43816_Content_26 = {
    Text = "Hai quasi rovinato tutto! Questa è la prova generale prima del vero spettacolo! A cosa stavi pensando?!"
  },
  AvgDialog_43816_Content_27 = {
    Text = "Scusate, io, io..."
  },
  AvgDialog_43816_Content_28 = {
    Text = "La musica si infrange a ondate contro le vostre orecchie, la visuale si oscura a ogni battito. I passi di danza svaniscono nella nebbia. Il suo strattone vi offre un'occasione — cercate di lasciare il palco —"
  },
  AvgDialog_43816_Content_29 = {
    Text = [[
Non muoverti. Ho bisogno di qualcuno che mantenga l'equilibrio della formazione quando salgo sul palco.

Vai in fondo a sinistra e colma il vuoto. Rifletti i miei passi.]]
  },
  AvgDialog_43816_Content_3 = {
    Text = "Gli archi e i legni mormorano in sottofondo, intrecciandosi con il battito ritmico dei piedi per formare un'armonia ordinata e aggraziata—una danza di suoni che scuote l'anima."
  },
  AvgDialog_43816_Content_30 = {
    Text = "Viene spinto da parte — sostituito da una mano esile e pallida che vi tira in avanti. Nei suoi occhi spaventati: sorpresa... poi gioia."
  },
  AvgDialog_43816_Content_31 = {
    Text = "I passi della nuova arrivata sono leggeri e sicuri, separano dolcemente il gruppo scomposto, guidandovi nella formazione."
  },
  AvgDialog_43816_Content_32 = {
    Text = "Le danzatrici si scambiano occhiate ma non dicono nulla. Si limitano a sogghignare, abbassare il capo e riprendere la danza."
  },
  AvgDialog_43816_Content_33 = {
    Text = "Presto! Riflettore su di lei! Elizabeth è tornata sul palco! Prima apparizione in tre mesi!"
  },
  AvgDialog_43816_Content_34 = {Text = "Elizabeth?"},
  AvgDialog_43816_Content_35 = {
    Text = "Articolate silenziosamente quel nome familiare, sforzandovi di scorgere la ragazza che vi ha trascinata nella luce."
  },
  AvgDialog_43816_Content_36 = {
    Text = "Alzate lo sguardo, e una detonazione di luce accecante dal balcone vi abbaglia."
  },
  AvgDialog_43816_Content_37 = {
    Text = "—Quando la vista ti si schiarisce, lei è già balzata in prima fila."
  },
  AvgDialog_43816_Content_38 = {
    Text = "Le danzatrici si aprono, lasciando spazio al suo abito ampio e sinuoso.\n\nSu questo modesto palcoscenico, lei è l'unica stella, un'ammaliante strega al centro di tutto."
  },
  AvgDialog_43816_Content_39 = {
    Text = "Quella è Elizabeth, la stella della Compagnia di danza Yadri... È magnifica."
  },
  AvgDialog_43816_Content_4 = {
    Text = "Cosa sta succedendo..."
  },
  AvgDialog_43816_Content_40 = {
    Text = "Direttore, pensavo che la signorina Elizabeth stesse male. Non era stata esclusa dallo spettacolo?"
  },
  AvgDialog_43816_Content_41 = {
    Text = "Signore e Signori, la nostra amata Elizabeth vi presenta... uno spettacolo a Sorpresa! Sì, una Sorpresa!"
  },
  AvgDialog_43816_Content_42 = {
    Text = "Anche se malata, in quanto direttrice della produzione, non permetterà che un solo passo falso rovini il palcoscenico!"
  },
  AvgDialog_43816_Content_43 = {
    Text = "Il Direttore di compagnia gonfia il petto, il suo sguardo scruta intorno come un gallo impettito."
  },
  AvgDialog_43816_Content_44 = {
    Text = "Le punte della danzatrice battono come tamburi. Alzi lo sguardo — e freddi occhi verdi incontrano i tuoi."
  },
  AvgDialog_43816_Content_45 = {
    Text = "Il tuo corpo reagisce all'istante, la minaccia pulsa in ogni arto. In due battute, sei rientrata nella formazione."
  },
  AvgDialog_43816_Content_46 = {
    Text = "Hai capito... Bene."
  },
  AvgDialog_43816_Content_47 = {
    Text = "Sii una foglia sull'albero. Nasconditi dal loro sguardo."
  },
  AvgDialog_43816_Content_48 = {
    Text = "Non lasciare mai che quegli occhi immondi... ti trovino di nuovo."
  },
  AvgDialog_43816_Content_5 = {
    Text = "Destato da un sonno profondo dalla musica, le tue membra si distendono d'istinto, sebbene le tue palpebre restino insopportabilmente pesanti."
  },
  AvgDialog_43816_Content_6 = {
    Text = "Le tue palpebre premono l'una contro l'altra—qualunque cosa accada, si rifiutano di aprirsi. Nemmeno un filo di luce riesce a filtrare."
  },
  AvgDialog_43816_Content_7 = {
    Text = "Ugh... Questa sensazione... Il sogno di qualcun altro, di nuovo..."
  },
  AvgDialog_43816_Content_8 = {
    Text = "Nel fragore assordante della musica, riacquisti gradualmente il controllo del tuo corpo. Ma proprio quando i tuoi occhi iniziano a percepire la luce, le tue membra si bloccano."
  },
  AvgDialog_43816_Content_9 = {
    Text = "Ottimo lavoro, ragazze. Mantenete il ritmo costante... ehi! Restate concentrate!"
  },
  AvgDialog_44435_Content_1 = {
    Text = "Vincolo Maledetto"
  },
  AvgDialog_44435_Content_2 = {
    Text = "I ricordi affluiscono insieme alla luce delle stelle."
  },
  AvgDialog_44435_Content_3 = {
    Text = "Quei ricordi, creati artificialmente e frantumati dalla violenza, irruppero nella mente di Mason per poi ritirarsi rapidamente come la marea."
  },
  AvgDialog_44435_Content_4 = {
    Text = "Fino alla fine, giunse ai piedi della montagna innevata, all'ingresso di una caverna buia come la pece."
  },
  AvgDialog_44435_Content_5 = {
    Text = "Segui il fiume che scorre sotto i tuoi piedi per raggiungere la tana della bestia addormentata."
  },
  AvgDialog_44435_Content_6 = {
    Text = "Tum-tum. Tum-tum."
  },
  AvgDialog_44435_Content_7 = {
    Text = "Il battito del cuore era come quello di un vecchio orologio, condiviso tra lei e la grande bestia."
  },
  AvgDialog_44435_Content_8 = {Text = "Capisco..."},
  AvgDialog_44435_Content_9 = {
    Text = "Capisco tutto..."
  },
  AvgDialog_44436_Content_1 = {
    Text = "Perché... perché..."
  },
  AvgDialog_44436_Content_10 = {
    Text = "Coloro che trovano la felicità in una vita semplice sono \"24\"."
  },
  AvgDialog_44436_Content_11 = {
    Text = "Tormentati dagli scultori, anche questo è \"24\"."
  },
  AvgDialog_44436_Content_12 = {
    Text = "No... Se non fosse stato per la tua codardia, quel dottore non avrebbe..."
  },
  AvgDialog_44436_Content_13 = {Text = "Shh..."},
  AvgDialog_44436_Content_14 = {
    Text = "Mason coprì delicatamente le labbra dell'ombra. Si chinò e le sussurrò all'orecchio."
  },
  AvgDialog_44436_Content_15 = {
    Text = "Ti svelo un segreto: <Red:Quel dottore l'ho ucciso io.>"
  },
  AvgDialog_44436_Content_16 = {
    Text = "Come osi...?!"
  },
  AvgDialog_44436_Content_17 = {
    Text = "Uccidere non è difficile. Non avevo un'arma, così gli ho spaccato la testa come una noce a mani nude."
  },
  AvgDialog_44436_Content_18 = {
    Text = "Alla fine, le mie mani erano intorpidite e tutto ciò che riuscivo a vedere era sangue."
  },
  AvgDialog_44436_Content_19 = {
    Text = "Dovevo assicurarmi che fosse completamente morto. Finché avesse ancora respirato, avrebbe sicuramente fatto del male ai bambini dell'orfanotrofio e a Jenkin..."
  },
  AvgDialog_44436_Content_2 = {
    Text = "Ombra è stata sconfitta da te. Nel paesaggio mentale, giace prostrata a terra, con minuscole particelle di luce che si staccano dal suo corpo."
  },
  AvgDialog_44436_Content_20 = {
    Text = "Era proprio come quelle persone degli scultori, no — era ancora più terrificante..."
  },
  AvgDialog_44436_Content_21 = {
    Text = "Era un vero demone."
  },
  AvgDialog_44436_Content_22 = {
    Text = "Cosa stavo facendo allora... Non sapevo nulla..."
  },
  AvgDialog_44436_Content_23 = {
    Text = "Mason scosse delicatamente la testa."
  },
  AvgDialog_44436_Content_24 = {
    Text = "Quello che in realtà conosci è il coraggio che tu e gli altri \"24\" mi avete prestato."
  },
  AvgDialog_44436_Content_25 = {
    Text = "Tutti i \"24\" si combinano per formare un unico \"Mason\". Nessun \"24\" può esistere in isolamento."
  },
  AvgDialog_44436_Content_26 = {
    Text = "Proprio come tutti i fiumi convergono in un unico luogo, anche tutti i \"24\" convergeranno in un unico luogo..."
  },
  AvgDialog_44436_Content_27 = {
    Text = "Mason baciò delicatamente la fronte dell'Ombra."
  },
  AvgDialog_44436_Content_28 = {
    Text = "Mi appartiene."
  },
  AvgDialog_44436_Content_29 = {
    Text = "Il corpo dell'ombra si trasforma in luce stellare, disperdendosi attorno a Mason e fondendosi nella sua pelle."
  },
  AvgDialog_44436_Content_3 = {
    Text = "Come ha potuto qualcuno potente e furioso come me... perdere contro di te, perdere contro questa codarda..."
  },
  AvgDialog_44436_Content_30 = {
    Text = "Capito... d'accordo."
  },
  AvgDialog_44436_Content_31 = {
    Text = "Tu sei l'origine di ogni cosa, e anche la fine di ogni cosa..."
  },
  AvgDialog_44436_Content_32 = {
    Text = "Perse gradualmente la voce in quel caldo abbraccio."
  },
  AvgDialog_44436_Content_33 = {
    Text = "La luce stellare brilla come lucciole nella notte, apparendo e scomparendo, fino a svanire del tutto."
  },
  AvgDialog_44436_Content_34 = {
    Text = "...Buonanotte, mio \"ventiquattresimo\"."
  },
  AvgDialog_44436_Content_35 = {
    Text = "<Yellow:Registro dell'Operazione Dominio Artificiale IV>\n\n■ID Dominio: M-C06\n■Ora della caduta: Anno 315 del Diluvio, dicembre @1\n■Luogo della caduta: Camberwell Street, Distretto Est"
  },
  AvgDialog_44436_Content_36 = {
    Text = "<Yellow:Risultati dell'Operazione I>\n\nIl Dominio si è concluso in modo ordinario.\nIn seguito, le condizioni della Signorina Mason sono migliorate notevolmente, portando grande gioia a tutti.\nCi stiamo gradualmente avvicinando alla vera Signorina Mason."
  },
  AvgDialog_44436_Content_37 = {
    Text = "Università di Mythag, Segreteria Scolastica\nUn giorno dopo"
  },
  AvgDialog_44436_Content_38 = {
    Text = "Cosa? Il Comitato ha ritirato l'accusa?"
  },
  AvgDialog_44436_Content_39 = {
    Text = "Già. Ora sono impegnati a gestire il problema dei serpenti insieme al Dipartimento Ambientale della Città."
  },
  AvgDialog_44436_Content_4 = {Text = "Perché..."},
  AvgDialog_44436_Content_40 = {
    Text = "Infestazione di serpenti...?"
  },
  AvgDialog_44436_Content_41 = {
    Text = "Winkle stende davanti a te il \"Londinium Post\" di qualche giorno fa."
  },
  AvgDialog_44436_Content_42 = {
    Text = "\"Di recente, un improvviso afflusso di serpenti albini di specie sconosciuta è emerso dalla clinica del defunto Dott. Bernard, causando gravi disagi al trasporto locale e alla vita quotidiana...\""
  },
  AvgDialog_44436_Content_43 = {
    Text = "\"I testimoni oculari affermano che si sia trattato della scena più terrificante a cui abbiano mai assistito. Se anche i lettori ne sono stati testimoni, si prega di contattare uno psicologo al @2...\""
  },
  AvgDialog_44436_Content_44 = {
    Text = "\"Numero@4...\""
  },
  AvgDialog_44436_Content_45 = {
    Text = "Accanto alla notizia, c'è una foto in cui sembri riconoscere alcuni volti familiari del Comitato."
  },
  AvgDialog_44436_Content_46 = {
    Text = "Indossando maschere e impugnando reti, eliminano instancabilmente l'interminabile flusso di piccoli serpenti, con volti che tradiscono stanchezza e impazienza."
  },
  AvgDialog_44436_Content_47 = {
    Text = "Quel cosiddetto \"Dottor Bernard\" è un grosso problema."
  },
  AvgDialog_44436_Content_48 = {
    Text = "Abbiamo trovato qualcuno della Royal Medical Society, ma la loro descrizione dell'uomo è completamente diversa da ciò che ha visto William."
  },
  AvgDialog_44436_Content_49 = {
    Text = "In altre parole, il defunto aveva rubato l'identità di questo Dott. Bernard. Tuttavia, non è ancora chiaro se questo falso dottore sia davvero morto."
  },
  AvgDialog_44436_Content_5 = {Text = "..."},
  AvgDialog_44436_Content_50 = {
    Text = "Dopotutto, sulla scena non è stata trovata nemmeno una traccia del corpo..."
  },
  AvgDialog_44436_Content_51 = {
    Text = [[
17 dicembre, il giorno dell'incidente
Clinica del Dott. Bernard]]
  },
  AvgDialog_44436_Content_52 = {
    Text = "Il trattamento di oggi è terminato. Signorina Mason, sta guarendo bene."
  },
  AvgDialog_44436_Content_53 = {
    Text = "Davvero? Ma tutti dicono che le mie condizioni stanno peggiorando..."
  },
  AvgDialog_44436_Content_54 = {
    Text = "Temo che la mia idea di \"serio\" sia diversa dalla loro. Ha preso le tinture prescritte in orario?"
  },
  AvgDialog_44436_Content_55 = {Text = "CRASH—!!"},
  AvgDialog_44436_Content_56 = {
    Text = "L'uomo urtò accidentalmente i fascicoli accanto a sé, spargendo pagine ingiallite su tutto il pavimento."
  },
  AvgDialog_44436_Content_57 = {
    Text = "Lei è un dottore diligente che lavora giorno e notte; lasci il piccolo compito di raccogliere le cose a..."
  },
  AvgDialog_44436_Content_58 = {Text = "Beh..."},
  AvgDialog_44436_Content_59 = {
    Text = "La sua mano si fermò a meno di 5 centimetri dal fascicolo. Era una pila di registri d'identità, e Mason riuscì a malapena a distinguere alcune parole vagamente familiari."
  },
  AvgDialog_44436_Content_6 = {
    Text = "Lascia che me ne occupi io."
  },
  AvgDialog_44436_Content_60 = {
    Text = "Rapporto dell'esperimento, registro dei trasferimenti...?"
  },
  AvgDialog_44436_Content_61 = {
    Text = "<Shake:Questi sono... i bambini scomparsi dall'orfanotrofio! No, è anche peggio...>"
  },
  AvgDialog_44436_Content_62 = {
    Text = "Nell'angolo del fascicolo esposto in fondo, Mason vide il volto leggermente ostinato di Jenkin."
  },
  AvgDialog_44436_Content_63 = {
    Text = "È tua sorella? L'ho vista. È sempre preoccupata per te e ha persino provato a intrufolarsi."
  },
  AvgDialog_44436_Content_64 = {
    Text = "Sorrise debolmente, la sua espressione si fece gentile."
  },
  AvgDialog_44436_Content_65 = {
    Text = "Un tempo avevo molti fratelli e sorelle... Mi temevano soltanto, così li ho divorati tutti."
  },
  AvgDialog_44436_Content_66 = {
    Text = "Tutti quanti... mangiati?"
  },
  AvgDialog_44436_Content_67 = {
    Text = "Non si preoccupi, Signorina Mason. Non ho mangiato quei bambini. Li ho solo mandati in un <Red:posto sicuro>."
  },
  AvgDialog_44436_Content_68 = {
    Text = "Quindi sei tu la mente dietro queste sparizioni..."
  },
  AvgDialog_44436_Content_69 = {
    Text = "<Shake:Questo scherzo non è affatto divertente, signor Bernard...>"
  },
  AvgDialog_44436_Content_7 = {
    Text = "Mason si sedette accanto all'ombra, stringendo tra le braccia l'ombra immobile."
  },
  AvgDialog_44436_Content_70 = {
    Text = "Signor Bernard... Si riferisce a questo?"
  },
  AvgDialog_44436_Content_71 = {
    Text = "L'uomo parlò, facendo fuoriuscire dalla bocca una lunga lingua che si avvolse attorno a un dito mozzato e insanguinato."
  },
  AvgDialog_44436_Content_72 = {
    Text = "È troppo grande; non riesco ancora a digerirlo."
  },
  AvgDialog_44436_Content_73 = {
    Text = "Ripresentiamoci. Sono <Yellow:Albino>, il farmacista de Gli scultori."
  },
  AvgDialog_44436_Content_74 = {
    Text = "Aaaaaah—!!"
  },
  AvgDialog_44436_Content_75 = {
    Text = "Le gambe di Mason cedettero e crollò pesantemente a terra."
  },
  AvgDialog_44436_Content_76 = {
    Text = "Tu... devi portare anche Jenkin..."
  },
  AvgDialog_44436_Content_77 = {
    Text = "L'uomo si sistemò gli occhiali e annotò rapidamente delle note sulla cartella clinica."
  },
  AvgDialog_44436_Content_78 = {
    Text = "Pupille dilatate, corpo che trema violentemente, battito cardiaco accelerato... Devi essere estremamente terrorizzato in questo momento. Hai freddo?"
  },
  AvgDialog_44436_Content_79 = {
    Text = "No... Stai indietro..."
  },
  AvgDialog_44436_Content_8 = {
    Text = "Perché... non hai accettato tutti i \"24\"."
  },
  AvgDialog_44436_Content_80 = {
    Text = "Presto, svenirai per insufficiente afflusso di sangue al cervello, proprio come gli altri ottusi esseri umani."
  },
  AvgDialog_44436_Content_81 = {
    Text = "Sollevò lo sguardo dalla cartella clinica, un debole bagliore di eccitazione che tremolava nelle sue pupille verticali dorate."
  },
  AvgDialog_44436_Content_82 = {
    Text = "Oppure... reagirai in modo diverso?"
  },
  AvgDialog_44436_Content_83 = {
    Text = "20 minuti dopo"
  },
  AvgDialog_44436_Content_84 = {
    Text = "Ho ucciso qualcuno... Ho davvero ucciso un dottore... Non mi crederanno..."
  },
  AvgDialog_44436_Content_85 = {
    Text = "No, perché l'ho ucciso...?"
  },
  AvgDialog_44436_Content_86 = {
    Text = "Mason si riscosse dal suo torpore e lasciò frettolosamente la scena."
  },
  AvgDialog_44436_Content_87 = {
    Text = "Il corpo dell'uomo era accasciato contro il muro. La sua testa era già in frantumi e il sangue continuava a fuoriuscire."
  },
  AvgDialog_44436_Content_88 = {
    Text = "Dopo un tempo imprecisato, una serie di segni maledetti neri si illuminarono improvvisamente sul collo del cadavere."
  },
  AvgDialog_44436_Content_89 = {
    Text = "I legami della maledizione ruotano lentamente come serpenti, e la carne ridotta in poltiglia inizia a convergere e a ricomporsi..."
  },
  AvgDialog_44436_Content_9 = {
    Text = "Spinti dalla disperazione e senza nessuno a cui rivolgersi, questo è \"24\"."
  },
  AvgDialog_44436_Content_90 = {
    Text = "Alla fine, il \"cadavere\" si sollevò lentamente a sedere."
  },
  AvgDialog_44436_Content_91 = {
    Text = "Phew... Niente male, quelle tinture hanno funzionato. Il suo potenziale è stato completamente liberato."
  },
  AvgDialog_44436_Content_92 = {
    Text = "Albino estese la sua lunga lingua da serpente e si leccò pigramente il sangue dal viso, pulendolo del tutto."
  },
  AvgDialog_44436_Content_93 = {
    Text = "La preda è maturata. È ora di riferire al nostro Maestro della Gilda."
  },
  AvgDialog_44436_Content_94 = {
    Text = "Raccolse la cartella clinica ai suoi piedi e se ne andò con passo tranquillo."
  },
  AvgDialog_44437_Content_1 = {
    Text = "Ritornello dorato"
  },
  AvgDialog_44437_Content_10 = {
    Text = "La pallida calma del mare si spezza quando un serpente marino dal colore scuro violaceo-nero balza fuori all'improvviso, avvolgendo tutti in una stretta mortale."
  },
  AvgDialog_44437_Content_11 = {
    Text = "Hmm... Aaaahhh!!"
  },
  AvgDialog_44437_Content_12 = {
    Text = "Con un debole sibilo, il corpo del serpente si trasforma in una lama nera come la pece, trafiggendo completamente la persona."
  },
  AvgDialog_44437_Content_13 = {
    Text = "<Big:Stai Indietro>... Eh?"
  },
  AvgDialog_44437_Content_15 = {
    Text = "Una sensazione morbida e gelida emana dal collo dove il serpente nero si avvolge, guarendo gradualmente la ferita."
  },
  AvgDialog_44437_Content_16 = {
    Text = "Le mie ferite... sono tutte guarite?"
  },
  AvgDialog_44437_Content_17 = {
    Text = "Il serpente nero ti abbandona senza esitazione e si avvolge rapidamente e strettamente attorno a Glen."
  },
  AvgDialog_44437_Content_18 = {
    Text = "Scappa, la strega sta... arrivando..."
  },
  AvgDialog_44437_Content_19 = {
    Text = "I serpenti neri come la pece strisciarono fuori dagli occhi e dalla bocca di Glen. Crollò a terra prima di riuscire a pronunciare una frase completa."
  },
  AvgDialog_44437_Content_2 = {
    Text = [[
Lamento per l'Apostolo del mare.
Lamento per la nostra luce, la nostra speranza.

Piangiamo, singhiozziamo e versiamo lacrime per il nostro destino di esiliati nell'oceano.]]
  },
  AvgDialog_44437_Content_20 = {Text = "..."},
  AvgDialog_44437_Content_21 = {
    Text = "In poco tempo, innumerevoli cadaveri dilaniati galleggiavano sul mare."
  },
  AvgDialog_44437_Content_22 = {
    Text = "Questo è un massacro silenzioso."
  },
  AvgDialog_44437_Content_23 = {
    Text = "<Gray:È finita? Impressionante, come ci si aspettava da Miryam.>"
  },
  AvgDialog_44437_Content_24 = {
    Text = "Ci hai aiutato... Chi sei?"
  },
  AvgDialog_44437_Content_25 = {
    Text = "La donna dal velo nero resta in silenzio. Si trova a prua, con una fitta nebbia che vi separa da lei."
  },
  AvgDialog_44437_Content_26 = {
    Text = "Sembra così vicina, eppure così lontana."
  },
  AvgDialog_44437_Content_27 = {
    Text = "La donna osservò Golia, rimasto attonito, con un lieve sorriso sulle labbra. Puntò il dito verso la distanza, come a rivolgere un invito silenzioso."
  },
  AvgDialog_44437_Content_28 = {
    Text = "Poi virò la prua e se ne andò con calma."
  },
  AvgDialog_44437_Content_29 = {
    Text = "Aspetta, non andare...<Big:Non andartene!>"
  },
  AvgDialog_44437_Content_3 = {
    Text = "La vista si oscura improvvisamente; la luce accecante del sole svanisce gradualmente, e una fitta nebbia avvolge l'intera superficie del mare."
  },
  AvgDialog_44437_Content_30 = {
    Text = "La nebbia si dissipa e un raggio di sole squarcia le nuvole, tingendo le onde di una tonalità dorata."
  },
  AvgDialog_44437_Content_31 = {
    Text = "Hai sbattuto le palpebre, e la fine del mare era già vuota."
  },
  AvgDialog_44437_Content_32 = {
    Text = "La tempesta si placa, e tu e Golia vi aggrappate all'unica tavola intatta, ansimando per riprendere fiato."
  },
  AvgDialog_44437_Content_33 = {
    Text = "Il mare un tempo azzurro è ormai tinto di rosso sangue, e voi andate alla deriva come lenticchie d'acqua."
  },
  AvgDialog_44437_Content_34 = {
    Text = "Non sono riuscito a prendere la nave... Ora non so nemmeno come tornare a casa."
  },
  AvgDialog_44437_Content_35 = {
    Text = "Non si torna a casa."
  },
  AvgDialog_44437_Content_36 = {
    Text = "Golia si appoggiò su una gamba, fissando con sguardo assente la direzione in cui Miryam se n'era andata."
  },
  AvgDialog_44437_Content_37 = {
    Text = "Ho deciso. Andrò a cercare quella strega. Verrai con me?"
  },
  AvgDialog_44437_Content_38 = {
    Text = "Ehm, \"Solo uno stolto affiderebbe la propria vita a qualcun altro.\""
  },
  AvgDialog_44437_Content_39 = {
    Text = "Abbassi deliberatamente la voce, imitando il tono che Golia aveva usato prima e ripetendo le sue parole."
  },
  AvgDialog_44437_Content_4 = {
    Text = [[
Oh, proteggi coloro che sono afflitti dalla sventura.
Posa il tuo sguardo compassionevole su di noi...]]
  },
  AvgDialog_44437_Content_40 = {
    Text = "Hmph, è perché la posta in gioco non era abbastanza alta. Non avevo mai visto un potere capace di annientare tutto in un istante."
  },
  AvgDialog_44437_Content_41 = {
    Text = "Inoltre, ci ha appena aiutati e ha persino rivolto un invito a me..."
  },
  AvgDialog_44437_Content_42 = {
    Text = "Ma se fosse... una trappola?"
  },
  AvgDialog_44437_Content_43 = {
    Text = "Trappola..."
  },
  AvgDialog_44437_Content_44 = {
    Text = "Ricordi la domanda che mi hai fatto prima?"
  },
  AvgDialog_44437_Content_45 = {
    Text = "...L'importante è che, grazie a voi, mio signore, siamo entrambi vivi adesso."
  },
  AvgDialog_44437_Content_46 = {
    Text = "Perché pensi che sia così?"
  },
  AvgDialog_44437_Content_47 = {
    Text = "Ora conosco la risposta."
  },
  AvgDialog_44437_Content_48 = {
    Text = "Qual è la risposta?"
  },
  AvgDialog_44437_Content_49 = {
    Text = "Uno stormo di uccelli marini si levò improvvisamente in volo. Le loro ali bianche battevano come nuvole in movimento, fluttuando liberamente nella brezza marina."
  },
  AvgDialog_44437_Content_5 = {
    Text = "Canti antichi e inquietanti si diffondono. La sagoma di una donna appare e scompare a prua, come un fantasma errante nella nebbia."
  },
  AvgDialog_44437_Content_50 = {
    Text = "Golia non si lasciò disturbare dallo stormo di uccelli. Fissava davanti a sé, gli occhi brillanti di eccitazione."
  },
  AvgDialog_44437_Content_51 = {
    Text = "Perché io sono Golia."
  },
  AvgDialog_44437_Content_52 = {
    Text = "Golia, il condottiero più longevo nella storia dei Perishita, un gigante indomabile e un leggendario eroe tribale."
  },
  AvgDialog_44437_Content_53 = {
    Text = "Anche se restasse un solo seguace, finché c'è un barlume di speranza, posso rialzarmi."
  },
  AvgDialog_44437_Content_54 = {
    Text = "Quella strega è la mia ultima possibilità. Solo lei può concedermi il Potere assoluto."
  },
  AvgDialog_44437_Content_55 = {
    Text = "Anche se fosse una trappola, ci andrò."
  },
  AvgDialog_44437_Content_56 = {
    Text = "Allora perché salvarmi? Un \"buono a nulla\" come me probabilmente non potrà esserti di alcun aiuto..."
  },
  AvgDialog_44437_Content_57 = {
    Text = "Hai deliberatamente enfatizzato la pronuncia di una parola, facendo scoppiare Golia in una risata."
  },
  AvgDialog_44437_Content_58 = {
    Text = "La luce del sole squarcia le nuvole, proiettando un bagliore dorato. Ciocche di capelli danzano dolcemente sotto il cielo azzurro."
  },
  AvgDialog_44437_Content_59 = {
    Text = "Non c'è modo che un comandante senza truppe possa avere successo in questo mondo."
  },
  AvgDialog_44437_Content_6 = {
    Text = "Eh, qualcuno sta cantando?"
  },
  AvgDialog_44437_Content_60 = {
    Text = "Piccola, non sei inutile. Sei l'unica seguace del gigante Golia, e nessuno può sostituirti."
  },
  AvgDialog_44437_Content_61 = {
    Text = "Quando avrò raggiunto il mio dominio, come minimo ti nominerò capo tribù!"
  },
  AvgDialog_44437_Content_62 = {
    Text = "...Non è necessario."
  },
  AvgDialog_44437_Content_63 = {
    Text = "Il cielo si oscurò gradualmente. Il bagliore del crepuscolo somigliava a fiumi dorati e scintillanti che scorrevano lungo l'orizzonte."
  },
  AvgDialog_44437_Content_64 = {
    Text = "Ehi, lo sai? Gli eroi possono essere eroi solo grazie a persone come noi."
  },
  AvgDialog_44437_Content_65 = {
    Text = "<Small:Quindi anch'io sono importante, capito...>"
  },
  AvgDialog_44437_Content_66 = {
    Text = "<Small:Hmm...>"
  },
  AvgDialog_44437_Content_67 = {
    Text = "Parole frammentate si disperdono come soffioni nella brezza marina, portate lontano, lontanissimo."
  },
  AvgDialog_44437_Content_68 = {
    Text = "Tu e Golia eravate seduti su una sottile tavola di legno, simili a minuscole foglie alla deriva in un mare dorato."
  },
  AvgDialog_44437_Content_69 = {
    Text = "Nessuno sa dove alla fine approderete."
  },
  AvgDialog_44437_Content_7 = {
    Text = "<Shake:La strega, è la strega!>"
  },
  AvgDialog_44437_Content_8 = {
    Text = "Come è possibile... La leggenda potrebbe essere vera davvero..."
  },
  AvgDialog_44437_Content_9 = {
    Text = "<Red:Pietà. Pietà. Pietà...>"
  },
  AvgDialog_44438_Content_1 = {Text = "\"Origine\""},
  AvgDialog_44438_Content_10 = {
    Text = "Eh? La signorina Winkle ha detto che il mio Dominio è terrificante, pieno di mostri feroci..."
  },
  AvgDialog_44438_Content_11 = {
    Text = "Era tutta una sua immaginazione. Tuttavia, ho visto qualcosa di speciale, come \"te\"."
  },
  AvgDialog_44438_Content_12 = {Text = "Me...?"},
  AvgDialog_44438_Content_13 = {
    Text = "Ridacchi sommessamente e le fai l'occhiolino."
  },
  AvgDialog_44438_Content_14 = {
    Text = "Questo è un segreto tra \"lei\" e me. Te ne parlerò più avanti."
  },
  AvgDialog_44438_Content_15 = {Text = "Sorel—!!"},
  AvgDialog_44438_Content_16 = {
    Text = "Jenkin salta fuori all'improvviso dai fiori lì vicino."
  },
  AvgDialog_44438_Content_17 = {
    Text = "Sono tornato dal mio girovagare con Aigis. Indovina cosa abbiamo trovato?"
  },
  AvgDialog_44438_Content_18 = {
    Text = "Jenkin agitò un nastro rosso, diverso da quello che Mason usa di solito, con un campanellino ingiallito all'estremità."
  },
  AvgDialog_44438_Content_19 = {
    Text = "Una brezza leggera passa, e il campanellino tintinna limpido, come uno spiritello gioioso."
  },
  AvgDialog_44438_Content_2 = {
    Text = "Università di Mythag, Campus \n Tre giorni dopo"
  },
  AvgDialog_44438_Content_20 = {
    Text = "Questo è qualcosa che ho visto nel Dominio..."
  },
  AvgDialog_44438_Content_21 = {
    Text = "Eh, l'hai vista anche tu nel Dominio? Allora devi aver incontrato la sorella che si è trasformata in gatto!"
  },
  AvgDialog_44438_Content_22 = {
    Text = "Non... non dirlo..."
  },
  AvgDialog_44438_Content_23 = {
    Text = "Perché non posso dirlo? Questo nastro è un ricordo importante!"
  },
  AvgDialog_44438_Content_24 = {
    Text = "In quel periodo, mi prendevo cura di te e giocavo con te ogni giorno. Ero così felice."
  },
  AvgDialog_44438_Content_25 = {
    Text = "Jenkin posò delicatamente il nastro nella mano di Mason."
  },
  AvgDialog_44438_Content_26 = {
    Text = "Ricordo che una volta hai detto che nella prossima vita volevi essere un gatto."
  },
  AvgDialog_44438_Content_27 = {
    Text = "Se solo potessimo restare spensierati così, potrei continuare a prendermi cura di te!"
  },
  AvgDialog_44438_Content_28 = {
    Text = "Mason sorrise, le dita che sfioravano il nastro fresco e morbido."
  },
  AvgDialog_44438_Content_29 = {
    Text = "Essere un gatto? Quello è qualcosa per la prossima vita."
  },
  AvgDialog_44438_Content_3 = {
    Text = "Capisco. Poco dopo aver ucciso Albino, sei stato portato via dall'Associazione degli Scultori."
  },
  AvgDialog_44438_Content_30 = {
    Text = "In questo momento, voglio solo vivere bene come \"Mason\"."
  },
  AvgDialog_44438_Content_31 = {
    Text = "Jenkin ti guarda con una certa sorpresa."
  },
  AvgDialog_44438_Content_32 = {
    Text = "Hmm... Sembra che questo Dominio abbia cambiato molto Sorella. Non era così prima."
  },
  AvgDialog_44438_Content_33 = {
    Text = "Testimonio che la Signorina Mason sta dicendo la verità."
  },
  AvgDialog_44438_Content_34 = {
    Text = "Tu e Mason vi scambiate un sorriso, i pensieri tornano al momento appena prima del collasso del Dominio..."
  },
  AvgDialog_44438_Content_35 = {
    Text = "Capito... d'accordo."
  },
  AvgDialog_44438_Content_36 = {
    Text = "Tu sei l'origine di ogni cosa, e anche la fine di ogni cosa..."
  },
  AvgDialog_44438_Content_37 = {
    Text = "Mentre l'ultimo barlume di luce stellare svanisce, il mondo sembra essere inghiottito dall'inchiostro nero."
  },
  AvgDialog_44438_Content_38 = {
    Text = "Senti il suono lontano di campane. Dong— Dong—"
  },
  AvgDialog_44438_Content_39 = {
    Text = "Il Dominio... sta collassando?!"
  },
  AvgDialog_44438_Content_4 = {
    Text = "Questa è la storia di ciò che accadde in seguito."
  },
  AvgDialog_44438_Content_40 = {
    Text = "Afferrate la mia mano, {Male=Signor,Female=Signorina} %player%!"
  },
  AvgDialog_44438_Content_41 = {
    Text = "Stringi forte la mano di Mason."
  },
  AvgDialog_44438_Content_42 = {
    Text = "In quel momento, il tuo sangue sembra fluire nel suo corpo senza sforzo, e le vostre coscienze si fondono in una sola."
  },
  AvgDialog_44438_Content_43 = {
    Text = "Senti di scivolare lentamente nel sonno, innumerevoli sogni che si susseguono uno dopo l'altro, trascinandoti nelle profondità dell'oscurità."
  },
  AvgDialog_44438_Content_44 = {Text = "..."},
  AvgDialog_44438_Content_45 = {
    Text = "Ti trovi nella caverna, con un fiume dorato e scintillante che scorre sotto di te, come le vene della terra."
  },
  AvgDialog_44438_Content_46 = {
    Text = "È questa la luce stellare che ho visto prima... Si è tutta raccolta qui?"
  },
  AvgDialog_44438_Content_47 = {
    Text = "<Red:Ritorna, ritorna...>"
  },
  AvgDialog_44438_Content_48 = {
    Text = "Segui il flusso di luce stellare più in profondità nella caverna."
  },
  AvgDialog_44438_Content_49 = {Text = "..."},
  AvgDialog_44438_Content_5 = {
    Text = "Hmm. Ora ricordo tutto. Non era un ricordo piacevole..."
  },
  AvgDialog_44438_Content_50 = {
    Text = "Questo è...?!"
  },
  AvgDialog_44438_Content_51 = {
    Text = "Questo luogo sembra essere la fonte ultima di tutte le cose contorte, deformi e immonde."
  },
  AvgDialog_44438_Content_52 = {
    Text = "La massa grigio chiaro tremava e si espandeva, generando per fissione mostri deformi e contorcenti, come uno stomaco in costante agitazione."
  },
  AvgDialog_44438_Content_53 = {
    Text = "Tuttavia, prima di raggiungere la riva, ricadevano nella pozza e venivano divorati dalle bocche spalancate sulla massa."
  },
  AvgDialog_44438_Content_54 = {
    Text = "Le sagome di questi mostri sembrano in qualche modo familiari... Potrebbe essere che..."
  },
  AvgDialog_44438_Content_55 = {
    Text = "All'improvviso hai una forte intuizione. Guadi attraverso la melma grigia e ti avvicini all'ammasso."
  },
  AvgDialog_44438_Content_56 = {
    Text = "Mason... sei tu?"
  },
  AvgDialog_44438_Content_57 = {
    Text = "La massa si fermò per un istante, poi iniziò a ondeggiare dolcemente. Emise un fruscio, come un saluto amichevole."
  },
  AvgDialog_44438_Content_58 = {
    Text = "Osservi i mostri inginocchiati accanto alla pozza. Si sforzano di muoversi, contorcendosi nella melma, bramando di tornare nell'abbraccio della massa."
  },
  AvgDialog_44438_Content_59 = {
    Text = "Come quei pellegrini che cercano miracoli nel vento e nella neve"
  },
  AvgDialog_44438_Content_6 = {
    Text = "Stringi delicatamente la mano di Mason."
  },
  AvgDialog_44438_Content_60 = {
    Text = "<Change>La radice di ogni impurità, lordura e sventura..."
  },
  AvgDialog_44438_Content_61 = {
    Text = "<Change>Ritorna!"
  },
  AvgDialog_44438_Content_62 = {
    Text = "Perché è il luogo dove tutti i fiumi finiscono, non importa quanto distanti possano essere, alla fine convergeranno qui."
  },
  AvgDialog_44438_Content_63 = {
    Text = "Capisco... Quindi è questo che fai ogni giorno?"
  },
  AvgDialog_44438_Content_64 = {
    Text = "Con un corpo fragile, riunendo quelle personalità disperse e sforzandosi di mantenere l'apparenza che le \"persone normali\" dovrebbero avere."
  },
  AvgDialog_44438_Content_65 = {
    Text = "...Non c'è da stupirsi che abbia sognato quegli eventi passati."
  },
  AvgDialog_44438_Content_66 = {
    Text = "L'ultima volta che ho visto queste stelle, ho improvvisamente sentito di essere molto simile a loro."
  },
  AvgDialog_44438_Content_67 = {
    Text = "...ci sono anche delle differenze. Loro sanno dov'è la loro casa, ma io ho persino perso i miei ricordi"
  },
  AvgDialog_44438_Content_68 = {
    Text = "Il tuo naso improvvisamente pizzica un po'. Tocchi delicatamente la carne, sentendo il suo tranquillo pulsare."
  },
  AvgDialog_44438_Content_69 = {
    Text = "Mason... Anch'io troverò la mia casa un giorno? Proprio come stai facendo tu adesso..."
  },
  AvgDialog_44438_Content_7 = {
    Text = "È tutto nel passato. Ti assicuro che non accadrà mai più."
  },
  AvgDialog_44438_Content_70 = {
    Text = "La carne si contorce, dividendosi all'estremità per formare un morbido tentacolo viscido che ti asciuga delicatamente le lacrime dall'angolo dell'occhio."
  },
  AvgDialog_44438_Content_71 = {
    Text = "<Change>Sicuramente lo farà."
  },
  AvgDialog_44438_Content_72 = {
    Text = "<Change>Non versare lacrime."
  },
  AvgDialog_44438_Content_73 = {Text = "Rombo..."},
  AvgDialog_44438_Content_74 = {
    Text = "Dal profondo del mantello terrestre giunge un debole tremore, che apre crepe nelle pareti rocciose."
  },
  AvgDialog_44438_Content_75 = {
    Text = "Tempo al collasso del Dominio: <Red:0> minuti"
  },
  AvgDialog_44438_Content_76 = {
    Text = "Ti allontani dalla caverna. Raggiunta l'entrata, non puoi fare a meno di voltarti un'ultima volta a guardarla."
  },
  AvgDialog_44438_Content_77 = {
    Text = "Addio, signorina Mason."
  },
  AvgDialog_44438_Content_78 = {
    Text = "Gioia, dolore, sofferenza... Personalità ed emozioni diverse vanno e vengono, ma lei rimane in quella caverna."
  },
  AvgDialog_44438_Content_79 = {Text = "È viva."},
  AvgDialog_44438_Content_8 = {
    Text = "Grazie... {Male=Signor,Female=Signorina} %player%."
  },
  AvgDialog_44438_Content_9 = {
    Text = "Dovrei essere io a ringraziarti. Quando il Dominio è crollato, mi hai dato molto incoraggiamento e conforto."
  },
  AvgDialog_44439_Content_1 = {
    Text = "Fuga dorata"
  },
  AvgDialog_44439_Content_10 = {Text = "..."},
  AvgDialog_44439_Content_11 = {
    Text = "Sembra che sia la prima volta che sogno il passato."
  },
  AvgDialog_44439_Content_12 = {
    Text = "Ti stringi la testa, sentendo come se un filo invisibile stesse trascinando la tua coscienza lontano dal letto."
  },
  AvgDialog_44439_Content_13 = {
    Text = "Poi hai aperto la finestra e hai visto la prima nevicata dell'Anno Nuovo."
  },
  AvgDialog_44439_Content_14 = {
    Text = "Wow, sta nevicando!!"
  },
  AvgDialog_44439_Content_15 = {
    Text = "Le grida eccitate dei bambini echeggiavano nel cielo notturno silenzioso. Accompagnati da passi caotici, gli orfani si radunarono al piano di sotto."
  },
  AvgDialog_44439_Content_16 = {
    Text = "Quanta neve, luccicante e bellissima."
  },
  AvgDialog_44439_Content_17 = {
    Text = "Aigis vuole costruire un pupazzo di neve, proprio come il piccolo Bobby."
  },
  AvgDialog_44439_Content_18 = {
    Text = "È facile, ci penso io—"
  },
  AvgDialog_44439_Content_19 = {
    Text = "Ta-da! Date un'occhiata al mio capolavoro!"
  },
  AvgDialog_44439_Content_2 = {
    Text = "Hai fatto un sogno incredibilmente lungo."
  },
  AvgDialog_44439_Content_20 = {
    Text = "Hmm... non assomiglia proprio all'Orsetto Bobby. Sembra, sembra..."
  },
  AvgDialog_44439_Content_21 = {
    Text = "Sembra un cane! Un carlino!"
  },
  AvgDialog_44439_Content_22 = {
    Text = "<Big:Hahahaha!>"
  },
  AvgDialog_44439_Content_23 = {
    Text = "Assurdo! Come potrei mai sembrare un cane?!"
  },
  AvgDialog_44439_Content_24 = {Text = "Squeak!"},
  AvgDialog_44439_Content_25 = {
    Text = "I bambini ridono e giocano nei vicoli. Mason, già sveglia, è in piedi accanto a te."
  },
  AvgDialog_44439_Content_26 = {
    Text = "Ha teso la mano e ha raccolto qualche delicato fiocco di neve nel palmo."
  },
  AvgDialog_44439_Content_27 = {
    Text = "Il fiocco di neve giaceva silenzioso nel suo palmo, sciogliendosi rapidamente in acqua fredda, scintillante di luce stellare dorata."
  },
  AvgDialog_44439_Content_28 = {
    Text = "Oh, è la luce che abbiamo visto l'altra volta..."
  },
  AvgDialog_44439_Content_29 = {
    Text = "Innumerevoli luci stellari volano fuori dalle finestre del corridoio accanto, fondendosi in un fiume dorato nel cielo notturno."
  },
  AvgDialog_44439_Content_3 = {
    Text = "Nel sogno, il cielo era come un cimitero squarciato, con sostanze nere che si riversavano come inchiostro."
  },
  AvgDialog_44439_Content_30 = {
    Text = "Scorrono con grazia, estendendosi fino alle lontane montagne illuminate dalla luna."
  },
  AvgDialog_44439_Content_31 = {
    Text = "Mason chiuse dolcemente gli occhi."
  },
  AvgDialog_44439_Content_32 = {
    Text = "È il profumo di quella signora pagliaccio. Ci ha lasciati."
  },
  AvgDialog_44439_Content_33 = {
    Text = "Ma non mi sento triste... Sembra che se ne sia andata di sua volontà, come se stesse tornando a casa."
  },
  AvgDialog_44439_Content_34 = {
    Text = "Tornare a casa..."
  },
  AvgDialog_44439_Content_35 = {
    Text = "Signorina Mason, ho sentito che sei andata a lavorare in città da giovane. Senti ancora la mancanza di casa?"
  },
  AvgDialog_44439_Content_36 = {
    Text = "Mason guardò Jenkins e il piccolo Mike che lottavano al piano di sotto, e sorrise dolcemente."
  },
  AvgDialog_44439_Content_37 = {
    Text = "Ho una memoria terribile. Quando ero piccola, le suore della scuola parrocchiale dicevano che non ero portata per lo studio."
  },
  AvgDialog_44439_Content_38 = {
    Text = "Genitori, paese natale... Non ricordo bene, e nemmeno voglio farlo. I ricordi dovrebbero servire a preservare la felicità."
  },
  AvgDialog_44439_Content_39 = {
    Text = "Nelle fiabe che ho letto, solo i luoghi felici e accoglienti possono essere chiamati casa. Voglio essere una casa per Jenkin e Brown."
  },
  AvgDialog_44439_Content_4 = {
    Text = "Giaci a faccia in su sotto la fenditura, il cuore il più vicino possibile alla terra."
  },
  AvgDialog_44439_Content_40 = {
    Text = "Capisco. Signorina Mason, sei molto più forte di quanto immaginassi."
  },
  AvgDialog_44439_Content_41 = {
    Text = "Non eri così quando ci siamo incontrati per la prima volta al museo delle cere."
  },
  AvgDialog_44439_Content_42 = {
    Text = "<Gray:Sembra che la \"Terapia di Super Stabilizzazione alla Menofina\" della signorina Winkle sia davvero efficace.>"
  },
  AvgDialog_44439_Content_43 = {
    Text = "Mason sorrise, con gli occhi socchiusi."
  },
  AvgDialog_44439_Content_44 = {
    Text = "Tutti stanno facendo del loro meglio per aiutarmi. Come potrei non cambiare affatto?"
  },
  AvgDialog_44439_Content_45 = {
    Text = "Spero di poter essere d'aiuto a tutti."
  },
  AvgDialog_44439_Content_46 = {
    Text = "Ti stiracchi pigramente, fissando senza meta la zona residenziale immersa nel buio sottostante."
  },
  AvgDialog_44439_Content_47 = {
    Text = "Non sai se sia solo la tua immaginazione, ma ti sembra di vedere \"Ombra 24\" in piedi alla fine del vicolo buio, che contempla il fiume di luce nel cielo insieme a te."
  },
  AvgDialog_44439_Content_48 = {Text = "..."},
  AvgDialog_44439_Content_49 = {
    Text = "Ecco un segreto: ogni persona è come un'erba alla deriva, e diventare interi è il nostro desiderio comune."
  },
  AvgDialog_44439_Content_5 = {
    Text = "Tum-tum. Tum-tum."
  },
  AvgDialog_44439_Content_50 = {
    Text = "Ridere insieme, piangere insieme, e sentire l'amore e la fiducia di Jenkin..."
  },
  AvgDialog_44439_Content_51 = {
    Text = "Sono tutte solo pietose illusioni."
  },
  AvgDialog_44439_Content_52 = {
    Text = "Il vento soffia dolcemente, e i fiocchi di neve fluttuano nell'aria come soffice cotone, vagando senza meta."
  },
  AvgDialog_44439_Content_53 = {
    Text = "La luce delle stelle svanisce gradualmente, e la tua coscienza sembra allontanarsi con essa."
  },
  AvgDialog_44439_Content_54 = {
    Text = "Chissà come sarà il prossimo Dominio che ti attende?"
  },
  AvgDialog_44439_Content_55 = {
    Text = "In realtà, non vedi l'ora."
  },
  AvgDialog_44439_Content_56 = {
    Text = "<Yellow:Registro dell'Operazione nel Dominio Artificiale III>\n\n■ID Dominio: M-C06\n■Ora del Collasso: 24 dicembre, 315 d.F.\n■Luogo del Collasso: Orfanotrofio di Lily"
  },
  AvgDialog_44439_Content_57 = {
    Text = "<Yellow:Risultati dell'Operazione>\n\nHo visto la neve, e la luce dorata delle stelle danzare al suo interno.\nPer qualche ragione, mi ricordano sempre il passato. La nebbia si alza, la luce cala e le risate svaniscono gradualmente.\nÈ una tranquilla notte d'inverno.\n\n<Yellow:Buon Anno.>\n\nP.S.: I cupcake glassati della Signorina Sarah sono deliziosi."
  },
  AvgDialog_44439_Content_6 = {
    Text = "Chiudi gli occhi, percependo i tremori provenienti dalle profondità del mantello terrestre. È un ritmo malinconico e antico che ti ricorda la tua casa."
  },
  AvgDialog_44439_Content_7 = {
    Text = "Non sai quanto tempo sia passato quando senti una debole risata e qualcuno ti prende la mano. Ricambi la stretta, aggrappandoti a questo calore perduto da tempo."
  },
  AvgDialog_44439_Content_8 = {
    Text = "Mamma. Prima ancora di poter gridare, le lacrime ti scorrevano già sul viso."
  },
  AvgDialog_44439_Content_9 = {
    Text = "Siete stati separati per troppo tempo."
  },
  AvgDialog_44440_Content_1 = {
    Text = "No, sono troppi... Le cose non faranno che peggiorare..."
  },
  AvgDialog_44440_Content_10 = {
    Text = "No, Lord Golia—!!"
  },
  AvgDialog_44440_Content_11 = {
    Text = "Sembra come se tutto davanti ai miei occhi fosse stato messo in pausa."
  },
  AvgDialog_44440_Content_12 = {
    Text = "L'istinto di questo corpo supera il tuo controllo. Si lancia in avanti, facendo disperatamente scudo a Golia."
  },
  AvgDialog_44440_Content_13 = {Text = "Huhhh—"},
  AvgDialog_44440_Content_16 = {
    Text = "Una lama ti squarcia la gola. Tremi mentre stringi la ferita sanguinante, la mente nel caos."
  },
  AvgDialog_44440_Content_17 = {
    Text = "Sei impazzita? Che ci fai qui?!"
  },
  AvgDialog_44440_Content_18 = {
    Text = "Non lo so... Il mio corpo si è mosso da solo..."
  },
  AvgDialog_44440_Content_19 = {
    Text = "Perdonatemi, Lord Golia..."
  },
  AvgDialog_44440_Content_2 = {
    Text = "Io... posso ancora... uccidere!"
  },
  AvgDialog_44440_Content_22 = {
    Text = "Una freccia avvelenata sibilò nell'aria, colpendo Golia alla spalla e facendolo cadere verso di te."
  },
  AvgDialog_44440_Content_23 = {
    Text = "Golia... Il gigante Golia è finalmente caduto!"
  },
  AvgDialog_44440_Content_24 = {
    Text = "La sua testa è mia! Nessuno me la porterà via!!!"
  },
  AvgDialog_44440_Content_25 = {
    Text = "Il mare emise un tremito profondo e furioso. Il gigante oscurò il sole ardente prima di crollare."
  },
  AvgDialog_44440_Content_26 = {
    Text = "Il vostro sangue confluisce, tingendo di cremisi il mare azzurro."
  },
  AvgDialog_44440_Content_27 = {
    Text = "Senti il vento, le onde, e in lontananza grida e scontri. Davanti a te non c'è altro che massacro e umiliazione senza fine."
  },
  AvgDialog_44440_Content_28 = {
    Text = "L'acqua salata del mare brucia la ferita sul tuo collo, facendoti sussultare dal dolore."
  },
  AvgDialog_44440_Content_29 = {
    Text = "Golia non sta molto meglio di te."
  },
  AvgDialog_44440_Content_3 = {
    Text = "Il suono cupo dei corni riecheggiò sul mare. Attirati da generose ricompense, i guerrieri accorsero in massa per unirsi alla caccia."
  },
  AvgDialog_44440_Content_30 = {
    Text = "Vedendoti in uno stato così pietoso, ti rivolge un ghigno malvagio."
  },
  AvgDialog_44440_Content_32 = {
    Text = "...Inutile."
  },
  AvgDialog_44440_Content_4 = {
    Text = "Golia era vicino al limite. Brandì la sua lama gigantesca ancora una volta, ma nel suo movimento rallentato, qualcuno colse la Fessura."
  },
  AvgDialog_44440_Content_6 = {
    Text = "Golia si inginocchiò, le ossa bianche esposte attraverso le ferite, il sangue che scorreva come un fiume inarrestabile."
  },
  AvgDialog_44440_Content_8 = {
    Text = "Ora è il momento! Finiamolo in un colpo solo!!"
  },
  AvgDialog_44440_Content_9 = {
    Text = "I guerrieri che vi circondano sciamano come squali assetati di sangue."
  },
  AvgDialog_44441_Content_1 = {
    Text = "Cronache dei Giganti"
  },
  AvgDialog_44441_Content_10 = {
    Text = "Golia emise uno sbuffo sprezzante dalla gola."
  },
  AvgDialog_44441_Content_11 = {
    Text = "Che sciocchezze sulle streghe? Non puoi davvero credere alle loro bugie, vero?"
  },
  AvgDialog_44441_Content_12 = {
    Text = "Solo gli sciocchi affiderebbero la propria vita ad altri."
  },
  AvgDialog_44441_Content_13 = {
    Text = "<Gray:Strega...>"
  },
  AvgDialog_44441_Content_14 = {
    Text = "Secondo il fascicolo del Risvegliatore di Golia, questa cosiddetta \"strega\" è senza dubbio Miryam."
  },
  AvgDialog_44441_Content_15 = {
    Text = "Sebbene gli sviluppi successivi non fossero quelli previsti, Miryam salvò effettivamente la vita di Golia."
  },
  AvgDialog_44441_Content_16 = {
    Text = "Siete gravemente ferito, mio signore. Temo che non ci sia altro modo—"
  },
  AvgDialog_44441_Content_17 = {Text = "BANG!!"},
  AvgDialog_44441_Content_18 = {
    Text = "Con una forza tremenda, la tua fragile gola viene stretta in una morsa, sollevandoti da terra fino a trovarti faccia a faccia con il gigante."
  },
  AvgDialog_44441_Content_19 = {
    Text = "Lo dirò una sola volta: non guardarmi con quello sguardo e non rivolgerti a me con quel tono."
  },
  AvgDialog_44441_Content_2 = {
    Text = "Il sole brucia il mare, come se volesse far appassire ogni forma di vita in questo calore senza fine."
  },
  AvgDialog_44441_Content_20 = {
    Text = "L'ultima cosa di cui io, Golia, ho bisogno è la pietà dei deboli."
  },
  AvgDialog_44441_Content_21 = {
    Text = "Golia parlava con calma, la sua espressione immutata, come se stesse discutendo del tempo con te."
  },
  AvgDialog_44441_Content_22 = {
    Text = "Ma sei così vicino che puoi vedere chiaramente i suoi occhi, arrossati dal dolore e dalla frustrazione."
  },
  AvgDialog_44441_Content_23 = {
    Text = "In quel momento, sembrava essersi spogliato della sua gloria di signore dei mari, diventando solo un altro pesce sperduto nell'oceano sconfinato, proprio come te."
  },
  AvgDialog_44441_Content_24 = {
    Text = "Mi scusi... ehm, mio signore..."
  },
  AvgDialog_44441_Content_25 = {
    Text = "<Shake:Woo—>"
  },
  AvgDialog_44441_Content_26 = {
    Text = "Il suono profondo di un corno giunge da lontano."
  },
  AvgDialog_44441_Content_27 = {
    Text = "Il peso sul collo si alleggerì improvvisamente. Golia allentò la presa e volse lo sguardo nella direzione da cui proveniva il suono del corno."
  },
  AvgDialog_44441_Content_28 = {
    Text = "<Gray:Coff... Uff, sono salvo...>"
  },
  AvgDialog_44441_Content_29 = {
    Text = "Interessante... Temete che non muoia abbastanza in fretta, e così siete venuti tutti insieme a darmi l'addio?"
  },
  AvgDialog_44441_Content_3 = {
    Text = "Tu e Golia vi aggrappate all'asse, l'unica isola nel vasto mare. Sotto il sole cocente, senti di nuovo le vertigini."
  },
  AvgDialog_44441_Content_30 = {
    Text = "In poco tempo, l'immensa flotta vi circondò, lasciando le assi di legno ondeggianti come unica isola in questo vasto mare."
  },
  AvgDialog_44441_Content_31 = {
    Text = "Siete già circondati."
  },
  AvgDialog_44441_Content_32 = {
    Text = "Permettetemi di presentare a tutti il condottiero più valoroso nella storia dei Perishita! L'indomabile gigante dalla forza immensa! Il temibile, impareggiabile eroe tribale—"
  },
  AvgDialog_44441_Content_33 = {
    Text = "<BigShake:Lord Golia!>"
  },
  AvgDialog_44441_Content_34 = {
    Text = "La luce del sole riflessa dal mare è troppo intensa; riesci solo a intravedere una figura nera in piedi a prua, che ti osserva dall'alto."
  },
  AvgDialog_44441_Content_35 = {
    Text = "I fratelli appena arrivati forse non lo sanno, ma questo signore è stato gravemente ferito in un duello e quasi catturato, spingendo l'intero nostro clan sull'orlo di una crisi senza precedenti!"
  },
  AvgDialog_44441_Content_36 = {
    Text = "L'imminente rovina ha divorato la maggior parte della nostra gente! Lode a voi, mio carissimo Lord Golia!"
  },
  AvgDialog_44441_Content_37 = {
    Text = "Hehe... Come potrei osare prendermi tutto il merito di un'impresa così grande, Glen?"
  },
  AvgDialog_44441_Content_38 = {
    Text = "Chi si nascondeva dietro di me, troppo spaventato per combattere, e chi è stato il primo a gettare l'arma e correre a casa piangendo?"
  },
  AvgDialog_44441_Content_39 = {Text = "Tu...!"},
  AvgDialog_44441_Content_4 = {
    Text = "<Shake:Scusa, non mi sento bene... Riposerò un attimo...>"
  },
  AvgDialog_44441_Content_40 = {
    Text = "Il volto di Glen divenne rosso cremisi, i suoi occhi torbidi tremarono prima di fissarsi finalmente su di te."
  },
  AvgDialog_44441_Content_41 = {
    Text = "Oh, anche se la tribù si disperde, il capo ha ancora un... seguace molto adorabile."
  },
  AvgDialog_44441_Content_42 = {
    Text = "La vergogna dei Perishiti — un buono a nulla che non riesce nemmeno a reggere un singolo pugno nella tribù, eppure cerca di seguirti per diventare un guerriero..."
  },
  AvgDialog_44441_Content_43 = {
    Text = "Hahaha...!!"
  },
  AvgDialog_44441_Content_44 = {
    Text = "Golia alza lo sguardo, sorpreso di vederti tra le risate della folla."
  },
  AvgDialog_44441_Content_45 = {
    Text = "Ehi, piccolo, sei venuto a seguirmi di tua spontanea volontà?"
  },
  AvgDialog_44441_Content_46 = {
    Text = "<Gray:Ehm... È così che me lo ricordo...>"
  },
  AvgDialog_44441_Content_47 = {
    Text = "Non è commovente? Ho solo menzionato la strega di sfuggita, e questo piccolo sciocco l'ha presa sul serio, desideroso di seguirti fin qui..."
  },
  AvgDialog_44441_Content_48 = {
    Text = "Non c'è stato verso di fermarlo, haha—"
  },
  AvgDialog_44441_Content_49 = {Text = "Splash!!"},
  AvgDialog_44441_Content_5 = {Text = "Bang!"},
  AvgDialog_44441_Content_50 = {
    Text = "Le risate si interruppero bruscamente. Un vento feroce ululò, e una gamba mozzata rotolò davanti a tutti."
  },
  AvgDialog_44441_Content_51 = {
    Text = "Aaaah... la mia gamba, la mia gamba!!"
  },
  AvgDialog_44441_Content_52 = {
    Text = "Il signore dei mari un tempo dominante si erge come una montagna davanti a Glen, emanando un'aura che gela il cuore."
  },
  AvgDialog_44441_Content_53 = {
    Text = "Quella mosca mi ronza intorno all'orecchio da un po' ormai..."
  },
  AvgDialog_44441_Content_54 = {
    Text = "Golia pulì con calma il sangue dalla lama, poi alzò lo sguardo e rivolse a Glen un sorriso gelido."
  },
  AvgDialog_44441_Content_55 = {
    Text = "Glenn, ti ho forse rivolto una domanda?"
  },
  AvgDialog_44441_Content_6 = {
    Text = "Una camicia macchiata di sudore e sangue ti viene gettata sulla testa, facendoti balzare immediatamente in piedi a causa del fetore."
  },
  AvgDialog_44441_Content_7 = {
    Text = "Cough... Ugh!"
  },
  AvgDialog_44441_Content_8 = {
    Text = "Hai un colpo di calore. Mettitela sulla testa per ripararti dal sole, e non toglierla."
  },
  AvgDialog_44441_Content_9 = {
    Text = "Grazie, mio signore... Dove dovremmo andare ora? A cercare la strega?"
  },
  AvgDialog_44442_Content_1 = {Text = "Mmph—!!"},
  AvgDialog_44442_Content_10 = {
    Text = "Io, il guerriero Glen, giuro sulla mia vita: chiunque mi porti questa testa avrà le mie ricchezze, le mie terre e le mie donne!"
  },
  AvgDialog_44442_Content_11 = {
    Text = "Dove c'è grande ricompensa, uomini coraggiosi non tarderanno a farsi avanti. I guerrieri lanciarono grida eccitate, le loro armi cozzarono tra loro risuonando con il fragore esaltante della battaglia."
  },
  AvgDialog_44442_Content_12 = {
    Text = "Già, di cosa dovremmo aver paura? Siamo in tanti!"
  },
  AvgDialog_44442_Content_13 = {
    Text = "Tagliategli prima la mano che impugna la lama!"
  },
  AvgDialog_44442_Content_14 = {
    Text = "I guerrieri che prima si rannicchiavano ruggirono e si lanciarono in avanti come locuste assetate di sangue."
  },
  AvgDialog_44442_Content_15 = {
    Text = "Heh... miei carissimi fratelli. Vi ho insegnato io a combattere, a uccidere e a sopravvivere."
  },
  AvgDialog_44442_Content_16 = {
    Text = "Ma non vi ho mai insegnato come fuggire di fronte a nemici molto più forti di voi."
  },
  AvgDialog_44442_Content_17 = {
    Text = "Golia leccò il sangue dall'angolo della bocca, mostrando le zanne."
  },
  AvgDialog_44442_Content_18 = {
    Text = "...perché non avete più nessun posto dove fuggire."
  },
  AvgDialog_44442_Content_19 = {
    Text = "Detto ciò, afferrò con noncuranza le loro gole, sollevò le loro teste e le fracassò l'una contro l'altra—"
  },
  AvgDialog_44442_Content_2 = {
    Text = "Una mannaia impazzita fece a pezzi la nave, costringendo Glen a ritirarsi con una sola gamba rimasta."
  },
  AvgDialog_44442_Content_20 = {Text = "Splash!!"},
  AvgDialog_44442_Content_21 = {
    Text = "Fluidi gialli e bianchi mescolati a sangue frammentato schizzarono ovunque. Golia rise di gusto, le pupille ardenti di una ferocia sanguinaria."
  },
  AvgDialog_44442_Content_22 = {
    Text = "Hahaha! Ho sentito che qualcuno vuole prendersi la mia testa?"
  },
  AvgDialog_44442_Content_23 = {
    Text = "Se ne hai il coraggio, vieni a prendertelo @1!"
  },
  AvgDialog_44442_Content_3 = {
    Text = "<Shake:Non eri ferito? Come hai potuto...>"
  },
  AvgDialog_44442_Content_4 = {
    Text = "Scusa, per occuparmi di un lacchè come te non serve tutta la mia forza."
  },
  AvgDialog_44442_Content_5 = {
    Text = "Golia si erge fiero a prua, la sua lama massiccia traccia un arco davanti a sé, tenendo a bada i suoi ex compagni."
  },
  AvgDialog_44442_Content_6 = {
    Text = "C'è qualcun altro che vuole farsi avanti e giocare con me? Uno solo non mi basta per ammazzare!"
  },
  AvgDialog_44442_Content_7 = {
    Text = "Glen si guardò intorno in preda al panico."
  },
  AvgDialog_44442_Content_8 = {
    Text = "Intimiditi dal terrore del gigante, i guerrieri si rannicchiarono come cuccioli, nessuno osava avventurarsi nella curva proibita davanti a loro, come se fosse un luogo tabù."
  },
  AvgDialog_44442_Content_9 = {
    Text = "Un branco di buoni a nulla! Con ferite così gravi, non è più il dominatore incontrastato dei mari di un tempo."
  },
  AvgDialog_44811_Content_1 = {
    Text = "Ghiaccio Ardente"
  },
  AvgDialog_44811_Content_10 = {
    Text = "Se n'è andato? Ha mollato a metà?"
  },
  AvgDialog_44811_Content_11 = {
    Text = "Questo corpo che abiti al momento continua a non rispondere alle tue domande. Le sue memorie giacciono nascoste in qualche angolo sconosciuto."
  },
  AvgDialog_44811_Content_12 = {
    Text = "Ti fai largo tra la folla di danzatrici che cinguettano come uccelli eccitati, protendendoti verso la bambina che si sta voltando per andarsene."
  },
  AvgDialog_44811_Content_13 = {
    Text = "Liz, dove stai andando?"
  },
  AvgDialog_44811_Content_14 = {
    Text = "Esatto. Liz."
  },
  AvgDialog_44811_Content_15 = {
    Text = "La danzatrice vestita di nero che ti ha salvata non è altri che Liz, la Risvegliatrice che conosci."
  },
  AvgDialog_44811_Content_16 = {
    Text = "Questo sogno appartiene a lei. La bambina che si chiude sempre nello studio di danza di Mythag."
  },
  AvgDialog_44811_Content_17 = {Text = "..."},
  AvgDialog_44811_Content_18 = {
    Text = "Liz si volta, le labbra le tremano come se volesse parlare—"
  },
  AvgDialog_44811_Content_19 = {
    Text = "Elizabeth, cara Elizabeth. Sapevo che non potevi abbandonare il palcoscenico—"
  },
  AvgDialog_44811_Content_2 = {
    Text = "<Small:Huff... Huff... Finalmente, è finita.>"
  },
  AvgDialog_44811_Content_20 = {
    Text = "Il Direttore di compagnia si insinua al suo fianco con un sorriso untuoso, la voce quasi strisciante."
  },
  AvgDialog_44811_Content_21 = {
    Text = "Liz arretra con grazia, come una farfalla che svolazza fuori dalla sua portata."
  },
  AvgDialog_44811_Content_22 = {
    Text = "Nessuno osa fermarla. Possono solo guardarla mentre scompare lungo il passaggio. Il sorriso del direttore si congela, poi si inacidisce."
  },
  AvgDialog_44811_Content_23 = {
    Text = "Darsi delle arie? Tch! Me la sarei spassata con quella piccola sgualdrina se non fosse stato per—"
  },
  AvgDialog_44811_Content_24 = {
    Text = "Che state a guardare?! Preparatevi per la prossima danza! Fate arrabbiare quei signori e sarete voi a pagare!"
  },
  AvgDialog_44811_Content_25 = {
    Text = "Le ragazze trasaliscono, ma alla fine nessuna osa protestare. Scendono tutte obbedienti e tornano in formazione."
  },
  AvgDialog_44811_Content_26 = {
    Text = "E tu. Come ti chiamavi...? Non importa, non è importante."
  },
  AvgDialog_44811_Content_27 = {
    Text = "Il direttore sceglie una bella danzatrice con un pigro gesto del dito. Lei si fa avanti con un sorriso raggiante."
  },
  AvgDialog_44811_Content_28 = {
    Text = "Manager, sono Caroline..."
  },
  AvgDialog_44811_Content_29 = {
    Text = "Caroline, Carol, non importa. Farai tu il Cala il Sipario."
  },
  AvgDialog_44811_Content_3 = {
    Text = "La musica finisce. Ti blocchi, mantenendo la posa insieme alle altre, pronta per un applauso fragoroso."
  },
  AvgDialog_44811_Content_30 = {
    Text = "Alla tua età, non calcherai il palcoscenico ancora a lungo. Questa è la tua ultima occasione di stabilità."
  },
  AvgDialog_44811_Content_31 = {
    Text = "Grazie, Direttore!"
  },
  AvgDialog_44811_Content_32 = {
    Text = "Accumula insulto su insulto, ma lei china il capo, la dignità gettata ai suoi piedi. La scena è soffocante."
  },
  AvgDialog_44811_Content_33 = {
    Text = "...Ma non puoi restare qui. Non sei venuta nel sogno di qualcuno per diventare una stella del balletto."
  },
  AvgDialog_44811_Content_34 = {
    Text = "Cogliendo l'attimo, fai un inchino e cerchi di svanire tra la folla."
  },
  AvgDialog_44811_Content_35 = {
    Text = "La porta del backstage di Liz è a portata di mano, ma una mano tozza ti afferra il polso e ti trascina dietro le quinte."
  },
  AvgDialog_44811_Content_36 = {
    Text = "Ahi, ouch... Manager, tu..."
  },
  AvgDialog_44811_Content_37 = {
    Text = "—SCHIAFFO!"
  },
  AvgDialog_44811_Content_38 = {
    Text = "Il colpo ti rimbomba nelle orecchie. La guancia avvampa e si gonfia all'istante, il dolore fiorisce sulla pelle."
  },
  AvgDialog_44811_Content_39 = {
    Text = "(Prova a restituirgli lo schiaffo)"
  },
  AvgDialog_44811_Content_4 = {
    Text = "Ma dal basso salgono solo sussurri sommessi."
  },
  AvgDialog_44811_Content_40 = {
    Text = "Le danzatrici seguono una dieta vegetariana e routine estenuanti. Fuori dal palco, questo corpo è fragile."
  },
  AvgDialog_44811_Content_41 = {
    Text = "Ma tu no. Anche nei sogni, i tuoi Risvegliatori possono stendere questo verme con un pugno—"
  },
  AvgDialog_44811_Content_42 = {
    Text = "I pugni si serrano, ma ricacci giù la rabbia che monta."
  },
  AvgDialog_44811_Content_43 = {
    Text = "(Trattieni la rabbia)"
  },
  AvgDialog_44811_Content_44 = {
    Text = "...No. Non ne vale la pena. Non era comunque il tuo volto."
  },
  AvgDialog_44811_Content_45 = {
    Text = "Non sei la protagonista di questo sogno. Reagire con violenza potrebbe recidere il legame con il suo proprietario — forse per sempre."
  },
  AvgDialog_44811_Content_46 = {
    Text = "Ti rendi anche conto di quello che hai fatto?! Ti ho nominata prima ballerina — e mi ripaghi rovinando una prova generale cruciale?!"
  },
  AvgDialog_44811_Content_47 = {
    Text = "Sai quanto è umiliante? Hai dimenticato i passi, hai quasi distrutto la nostra reputazione!"
  },
  AvgDialog_44811_Content_48 = {
    Text = "Io? Ma se io sono la preside, allora Liz..."
  },
  AvgDialog_44811_Content_49 = {
    Text = "Liz? Hah! Se non si fosse ritirata, non avresti mai nemmeno annusato questo titolo!"
  },
  AvgDialog_44811_Content_5 = {
    Text = "...Prezzo...?"
  },
  AvgDialog_44811_Content_50 = {
    Text = "Ha lasciato... Liz era il principio originale? Allora perché..."
  },
  AvgDialog_44811_Content_51 = {
    Text = "Troppe domande! Vai in camera tua, subito!"
  },
  AvgDialog_44811_Content_52 = {
    Text = "Il direttore ha perso la pazienza. Ti afferra e ti spinge in una stanza angusta e oscura."
  },
  AvgDialog_44811_Content_53 = {
    Text = "La porta sbatte. Lui urla dall'altro lato:"
  },
  AvgDialog_44811_Content_54 = {
    Text = "Prega di ricordare i passi di Elizabeth — o verrai venduta alla Casa della Beatitudine!"
  },
  AvgDialog_44811_Content_55 = {
    Text = "Che... che razza di posto è quello?"
  },
  AvgDialog_44811_Content_56 = {Text = "—Click."},
  AvgDialog_44811_Content_57 = {
    Text = "Il lucchetto scatta, freddo. Sai che stanotte non otterrai risposta. Se n'è andato."
  },
  AvgDialog_44811_Content_58 = {
    Text = "Bastardo viscido! Che tu possa passare la notte inchiodato al cesso!"
  },
  AvgDialog_44811_Content_59 = {
    Text = "Sfoghi la frustrazione con un calcio alla porta. Il legno antico non cede e resta silenziosamente incastrato nel telaio."
  },
  AvgDialog_44811_Content_6 = {
    Text = "Che fretta c'è? Comunque... spettacolo... asta..."
  },
  AvgDialog_44811_Content_60 = {Text = "UGH!"},
  AvgDialog_44811_Content_61 = {
    Text = "Hai sopravvalutato la resistenza delle punte. Un dolore lancinante ti trafigge l'alluce, come se il letto ungueale si fosse sollevato sotto il colpo."
  },
  AvgDialog_44811_Content_62 = {
    Text = "Guaisci, crolli sul letto, ti rannicchi e gemi."
  },
  AvgDialog_44811_Content_63 = {
    Text = "Qualcuno bussa alla finestra."
  },
  AvgDialog_44811_Content_64 = {
    Text = "Non l'avevi chiusa a chiave. Il visitatore si arrampica dentro con facilità."
  },
  AvgDialog_44811_Content_65 = {
    Text = "Così fiera per la maggior parte del tempo, eppure tutta impacciata quando si tratta di rimproverare qualcuno?"
  },
  AvgDialog_44811_Content_66 = {
    Text = "Sta in piedi accanto al letto, chinata in avanti con le mani dietro la schiena. I suoi capelli grigio cenere ti sfiorano la guancia."
  },
  AvgDialog_44811_Content_67 = {Text = "Liz—!"},
  AvgDialog_44811_Content_68 = {
    Text = "Shh. Silenzio. Le pareti del dormitorio sono sottili. Quando la musica si ferma, il pubblico potrebbe sentire."
  },
  AvgDialog_44811_Content_69 = {
    Text = "Ti preme un panno freddo sulla guancia."
  },
  AvgDialog_44811_Content_7 = {
    Text = "Prima che tu riesca a distinguere le parole degli ospiti, il sipario scende — separando il palcoscenico dal pubblico come la notte dal giorno."
  },
  AvgDialog_44811_Content_70 = {
    Text = "Ssss—Freddo!"
  },
  AvgDialog_44811_Content_71 = {
    Text = "Ci hanno schiaffeggiato da questo lato, giusto?"
  },
  AvgDialog_44811_Content_72 = {
    Text = "Si siede e passa delicatamente il panno sul tuo viso, la tua smorfia che sussulta a ogni passaggio."
  },
  AvgDialog_44811_Content_73 = {
    Text = "Cubetti di ghiaccio...? Dove li hai trovati?"
  },
  AvgDialog_44811_Content_74 = {
    Text = "Dalla cantina privata di quel vecchio porco."
  },
  AvgDialog_44811_Content_75 = {
    Text = "Vecchio porco? Intendi il direttore? —Ahi, più piano!"
  },
  AvgDialog_44811_Content_76 = {
    Text = "È piena estate — il ghiaccio è raro. Non te lo darebbe mai."
  },
  AvgDialog_44811_Content_77 = {
    Text = "Lei preme più forte."
  },
  AvgDialog_44811_Content_78 = {
    Text = "Non l'ho chiesto. L'ho preso."
  },
  AvgDialog_44811_Content_79 = {
    Text = "Liz lascia la presa, tirandoti su a sedere. Fruga in un semplice impacco di ghiaccio e ne estrae un piccolo cubetto, posandotelo in bocca."
  },
  AvgDialog_44811_Content_8 = {
    Text = "Così bello... il vero finale dell'\"Elegia del Cigno\"... Se lei non fosse intervenuta, non riesco a immaginare..."
  },
  AvgDialog_44811_Content_80 = {
    Text = "Una strana dolcezza si diffonde insieme al freddo, lenendo la bruciatura sul tuo viso. Premi di nuovo il panno sulla pelle."
  },
  AvgDialog_44811_Content_81 = {
    Text = "Hai saltato il palco oggi perché hai origliato qualcosa?"
  },
  AvgDialog_44811_Content_82 = {Text = "Cosa?"},
  AvgDialog_44811_Content_83 = {
    Text = "Il Suo Sguardo si indurisce. Ti prende le guance tra le mani e fissa i suoi occhi nei tuoi."
  },
  AvgDialog_44811_Content_84 = {
    Text = "Hai scoperto La Verità sulla compagnia? Il direttore o gli agenti ti hanno costretta a—"
  },
  AvgDialog_44811_Content_85 = {
    Text = "Rabbia e preoccupazione affiorano nei suoi occhi di smeraldo. I suoi palmi diventano più freddi del ghiaccio."
  },
  AvgDialog_44811_Content_86 = {
    Text = "Posi il fagotto e incroci il suo sguardo."
  },
  AvgDialog_44811_Content_87 = {
    Text = "E tu, Liz? Cosa hanno costretto TE a fare?"
  },
  AvgDialog_44811_Content_88 = {
    Text = "Distoglie lo sguardo con inquietudine, gli occhi attratti dalla luce delle stelle oltre la finestra."
  },
  AvgDialog_44811_Content_89 = {
    Text = "La città dorme; solo lo scalpiccio delle ruote di una carrozza riecheggia nella strada."
  },
  AvgDialog_44811_Content_9 = {
    Text = "In nostro soccorso? Le dai troppo credito! Se non se ne fosse andata, non avremmo dovuto sostituirla con una prima ballerina improvvisata..."
  },
  AvgDialog_44811_Content_90 = {
    Text = "Ma quelle voci crudeli e ridenti perforano la parete, ancora persistenti dal palcoscenico."
  },
  AvgDialog_44812_Content_1 = {
    Text = "Sogno di una Notte di Mezza Estate"
  },
  AvgDialog_44812_Content_10 = {
    Text = "Elizabeth Salle... Salle, Salle, ricordo che è il nome di una compagnia di danza reale."
  },
  AvgDialog_44812_Content_100 = {
    Text = "Stai piangendo..."
  },
  AvgDialog_44812_Content_101 = {
    Text = "Liz si avvicinò bruscamente a te, prendendoti il viso tra le mani e asciugando con i pollici le lacrime cadute."
  },
  AvgDialog_44812_Content_102 = {
    Text = "Questo significa che sei d'accordo con me, giusto?"
  },
  AvgDialog_44812_Content_103 = {
    Text = "Gli occhi grigio-verdi erano a pochi centimetri di distanza, e questa volta vedesti chiaramente la lotta e il dolore che li abitavano. Ti attendeva quasi disperatamente, in attesa della tua risposta affermativa."
  },
  AvgDialog_44812_Content_104 = {
    Text = "...Sì. Avete perfettamente ragione."
  },
  AvgDialog_44812_Content_105 = {
    Text = "Ricordi la conversazione con Liz nell'archivio dell'Università di Mythag."
  },
  AvgDialog_44812_Content_106 = {
    Text = "Danzare... dovrebbe essere puro. Un vero danzatore dovrebbe esprimere il proprio cuore attraverso i passi, non solo attraverso il corpo."
  },
  AvgDialog_44812_Content_107 = {
    Text = "Gli occhi di Liz si illuminarono, la sua gioia evidente."
  },
  AvgDialog_44812_Content_108 = {
    Text = "Siamo davvero uguali; tu puoi comprendermi..."
  },
  AvgDialog_44812_Content_109 = {
    Text = "Quindi, potresti aiutarmi?"
  },
  AvgDialog_44812_Content_11 = {
    Text = "Sì, il fondatore della Compagnia di danza Salle era mio nonno."
  },
  AvgDialog_44812_Content_110 = {
    Text = "Aiutarti? Liz, hai qualche piano?"
  },
  AvgDialog_44812_Content_111 = {
    Text = "Non voglio che il loro male continui a propagarsi... Porrò fine a tutto qui. Con le mie stesse mani."
  },
  AvgDialog_44812_Content_112 = {
    Text = "D'accordo. Ti aiuterò. Cosa devo fare?"
  },
  AvgDialog_44812_Content_113 = {
    Text = "Liz ti sfiorò il viso, il tono si addolcì, con una sfumatura di tristezza e senso di colpa nei suoi occhi."
  },
  AvgDialog_44812_Content_114 = {
    Text = "Il direttore è diffidente nei miei confronti; di certo non crederà che salirei sul palco..."
  },
  AvgDialog_44812_Content_115 = {
    Text = "Sollevò con due dita il panno dell'impacco di ghiaccio improvvisato; la maggior parte del ghiaccio si era sciolta, e il tessuto era così bagnato da poterlo strizzare."
  },
  AvgDialog_44812_Content_116 = {
    Text = "Un'ondata di sonnolenza inattesa lo travolse all'improvviso, persino il respiro gli si bloccò in gola —"
  },
  AvgDialog_44812_Content_117 = {
    Text = "Liz... Elizabeth... Cosa hai fatto..."
  },
  AvgDialog_44812_Content_118 = {
    Text = "Sei tu il titolare che ha scelto. Si rivolgerebbe a me solo in tua assenza..."
  },
  AvgDialog_44812_Content_119 = {
    Text = "Liz ti coprì bocca e naso con un panno, e un profumo dolce, familiare eppure sgradevole si propagò nelle tue narici."
  },
  AvgDialog_44812_Content_12 = {
    Text = "Oh... capisco. Elizabeth, posso chiamarti Liz? Ti piace danzare?"
  },
  AvgDialog_44812_Content_120 = {
    Text = "Il ghiaccio... è adulterato..."
  },
  AvgDialog_44812_Content_121 = {
    Text = "...Non riesco a credere che tu sia riuscito a tenere quel cubetto di ghiaccio tra i denti così a lungo. Alla fine si è sciolto."
  },
  AvgDialog_44812_Content_122 = {
    Text = "Starai bene. Ho visto il direttore usare questo farmaco per far obbedire le \"Bambine indisciplinate\"... È come un sonno profondo."
  },
  AvgDialog_44812_Content_123 = {
    Text = "Esatto, dopo il risveglio, tutto giungerà alla fine..."
  },
  AvgDialog_44812_Content_13 = {
    Text = "Amo davvero danzare, signore. Mi basta uno sguardo per ricordare i passi. E a dodici anni ho coreografato un intero balletto."
  },
  AvgDialog_44812_Content_14 = {
    Text = "Oh? Sai anche creare coreografie? Come ha reagito il pubblico?"
  },
  AvgDialog_44812_Content_15 = {
    Text = "Mi dispiace, Direttore. Il mio dramma di danza non è mai andato in scena. I miei genitori hanno sempre detto che mi avrebbero ripudiata se avessi continuato a danzare, e persino mio nonno mi ha picchiata diverse volte per questo..."
  },
  AvgDialog_44812_Content_16 = {
    Text = "<Small:Non sapevo che il vecchio Salle fosse un tale maestro della finzione...>"
  },
  AvgDialog_44812_Content_17 = {
    Text = "Direttore? Ha appena detto qualcosa?"
  },
  AvgDialog_44812_Content_18 = {
    Text = "Ehm... voglio dire, il vecchio Salle ha davvero sprecato il tuo talento!"
  },
  AvgDialog_44812_Content_19 = {
    Text = "Il direttore girò intorno a Liz, scrutandola con uno sguardo come se fosse una preziosa opera d'arte."
  },
  AvgDialog_44812_Content_2 = {
    Text = "Attraverso un corridoio, i sussurri di persone che conversavano nel teatro non si udivano chiaramente. Percepivi soltanto che quei suoni erano intrisi di scherno sprezzante e altezzoso."
  },
  AvgDialog_44812_Content_20 = {
    Text = "I muscoli delle tue braccia sono più belli di quelli di qualsiasi altra ragazza del gruppo. Saranno anche esili, ma dalla tua audizione di danza si vede che sono decisamente forti!"
  },
  AvgDialog_44812_Content_21 = {
    Text = "E il rapporto tra la tua vita e le tue gambe... Liz, sei una danzatrice nata! Nascondere te e il tuo talento in casa è semplicemente una profanazione dell'arte!"
  },
  AvgDialog_44812_Content_22 = {
    Text = "Vuol dire che la Compagnia di danza Yadri mi accetterà?"
  },
  AvgDialog_44812_Content_23 = {
    Text = "Esatto! Assolutamente. Non solo entrerai nella compagnia di danza, ma diventerai anche la nuova prima ballerina, la mia nuova stella! Il tuo balletto debutterà nel più grande teatro di Londinium!"
  },
  AvgDialog_44812_Content_24 = {
    Text = "La nuova direttrice? Ma se dovessi diventare la direttrice, che ne sarebbe di Mademoiselle Deneuve, l'attuale prima ballerina della compagnia... Ho sentito dire che è particolarmente orgogliosa e straordinariamente abile..."
  },
  AvgDialog_44812_Content_25 = {
    Text = "Ora abbiamo te, ed è questo che conta!\nFirma questo contratto per unirti al gruppo, e ti garantisco che ti renderò una star di prima categoria!"
  },
  AvgDialog_44812_Content_26 = {
    Text = "Il direttore strinse la mano di Liz, e quest'ultima, colma di gioia e determinazione, appose solennemente il proprio nome sul foglio."
  },
  AvgDialog_44812_Content_27 = {
    Text = "E gli occhi delle ragazze, pieni di disprezzo o di pietà, furono tutti interpretati da lei come invidia per il riconoscimento ottenuto."
  },
  AvgDialog_44812_Content_28 = {
    Text = "Tre mesi fa"
  },
  AvgDialog_44812_Content_29 = {
    Text = "L'ultimo giro di frusta. Un, deux, trois, ben fatto."
  },
  AvgDialog_44812_Content_3 = {
    Text = "...Non ascoltare quelle voci."
  },
  AvgDialog_44812_Content_30 = {
    Text = "La fronte di Liz si imperlò di sudore freddo per la tensione. Solo dopo che le danzatrici ebbero completato con precisione i loro movimenti, Liz lasciò finalmente sfuggire un sospiro di sollievo, sorridendo alle artiste con cui aveva lavorato giorno e notte."
  },
  AvgDialog_44812_Content_31 = {
    Text = "Fantastico... Incredibile! Manca solo mezza scena e la mia \"Elegia del Cigno\" sarà completa."
  },
  AvgDialog_44812_Content_32 = {
    Text = "Liz voleva stringere le mani delle danzatrici e abbracciare le ragazze, ma queste si scansarono una a una per evitare il suo entusiasmo."
  },
  AvgDialog_44812_Content_33 = {
    Text = "Tutti... che succede? Ancora un piccolo sforzo e potremo portare \"L'Elegia del Cigno\" in scena il mese prossimo."
  },
  AvgDialog_44812_Content_34 = {
    Text = "Oh... scusate, mi sono lasciata trasportare. Grazie a tutti, \"L'Elegia del Cigno\" ha potuto nascere; è la creazione collettiva della nostra Compagnia di danza Yadri—"
  },
  AvgDialog_44812_Content_35 = {
    Text = "Basta, Liz! Abbiamo sopportato per così tanto tempo, e quel direttore non è altro che—"
  },
  AvgDialog_44812_Content_36 = {
    Text = "Smettila di parlare! Pensa al fato di Deneuve!"
  },
  AvgDialog_44812_Content_37 = {
    Text = "Un'altra danzatrice trattenne l'amica agitata. La prima mostrò un'espressione di terrore residuo mentre il suo sguardo guizzava intorno."
  },
  AvgDialog_44812_Content_38 = {
    Text = "Il... destino della signorina Deneuve? Il direttore ha detto che si è ritirata per tornare a casa a prendersi cura degli anziani... Non è così?"
  },
  AvgDialog_44812_Content_39 = {
    Text = "Prendersi cura degli anziani, eh? Il posto che il direttore ha scelto per lei è davvero ottimo; il Conte Geoffrey è molto vecchio, dopotutto."
  },
  AvgDialog_44812_Content_4 = {
    Text = "Liz sollevò le mani e ti coprì delicatamente le orecchie."
  },
  AvgDialog_44812_Content_40 = {
    Text = "Immagino che adori davvero Deneuve, scegliendo per lei solo anziani gentiluomini con un piede nella fossa... Forse non passerà molto prima che ottenga un'enorme eredità e viaggi per il mondo."
  },
  AvgDialog_44812_Content_41 = {
    Text = "Ehi! Il direttore non ci ha forse detto esplicitamente di non parlarne con lei!"
  },
  AvgDialog_44812_Content_42 = {
    Text = "Il Vecchio Conte, la scelta, l'Eredità..."
  },
  AvgDialog_44812_Content_43 = {
    Text = "Di cosa... stai parlando?"
  },
  AvgDialog_44812_Content_44 = {
    Text = "Per il bene del tuo amore sincero per la danza... lascia la compagnia. Non posso dirti altro."
  },
  AvgDialog_44812_Content_45 = {
    Text = "Shh, non dire nulla! Nascondetevi subito dietro le quinte, il direttore è qui!"
  },
  AvgDialog_44812_Content_46 = {
    Text = "Il suono di scarpe di cuoio echeggiò dall'altro lato del palcoscenico, e le danzatrici più legate tra loro si spinsero rapidamente dietro le quinte, lasciando Liz sola sotto i riflettori."
  },
  AvgDialog_44812_Content_47 = {
    Text = "Ricevette un lungo e solenne applauso: dal direttore che l'aveva introdotta nella compagnia di danza. I suoi occhi brillavano di quella che si poteva descrivere solo come una luce fanatica, suscitando in Liz un lieve disagio."
  },
  AvgDialog_44812_Content_48 = {
    Text = "Liz, sei un vero genio. Questo balletto eleverà la compagnia — e il tuo valore — a vette ineguagliabili!"
  },
  AvgDialog_44812_Content_49 = {
    Text = "Il mio... valore?"
  },
  AvgDialog_44812_Content_5 = {
    Text = "Non eri sempre curiosa di sapere il motivo per cui ho abbandonato l'esibizione?"
  },
  AvgDialog_44812_Content_50 = {
    Text = "Il Conte Geoffrey è disposto a coprire i costi operativi della compagnia di danza per tre mesi solo per incontrarti. È una notizia fantastica."
  },
  AvgDialog_44812_Content_51 = {
    Text = "Manager, non capisco... Chi è questo Conte? Perché si darebbe tanto da fare per me?"
  },
  AvgDialog_44812_Content_52 = {
    Text = "Il Conte Geoffrey è il più grande benefattore della nostra compagnia. Apprezza enormemente le danzatrici di talento."
  },
  AvgDialog_44812_Content_53 = {
    Text = "Ascoltami, la Contessa è venuta a mancare inaspettatamente dieci giorni fa. Questa è la tua occasione perfetta."
  },
  AvgDialog_44812_Content_54 = {
    Text = "Conte Geoffrey..."
  },
  AvgDialog_44812_Content_55 = {
    Text = "Smettila di parlare! Pensa al fato di Deneuve!"
  },
  AvgDialog_44812_Content_56 = {
    Text = "Il... destino della signorina Deneuve? Il direttore ha detto che si è ritirata per tornare a casa a prendersi cura degli anziani... Non è così?"
  },
  AvgDialog_44812_Content_57 = {
    Text = "Prendersi cura degli anziani, eh? Il posto che il direttore ha scelto per lei è davvero ottimo; il Conte Geoffrey è molto vecchio, dopotutto."
  },
  AvgDialog_44812_Content_58 = {
    Text = "Immagino che adori davvero Deneuve, scegliendo per lei solo anziani gentiluomini con un piede nella fossa... Forse non passerà molto prima che ottenga un'enorme eredità e viaggi per il mondo."
  },
  AvgDialog_44812_Content_59 = {
    Text = "La moglie del defunto Conte era la signorina Deneuve, l'ex prima ballerina, giusto?"
  },
  AvgDialog_44812_Content_6 = {
    Text = "Poi, con un tono sommesso e misurato, attraverso le sue mani, la voce profonda si fece strada nelle tue orecchie."
  },
  AvgDialog_44812_Content_60 = {
    Text = "...Chi te l'ha detto?"
  },
  AvgDialog_44812_Content_61 = {
    Text = "Manager, per favore sii sincero con me.\n\"Un incontro con il Conte\"... È davvero così semplice?"
  },
  AvgDialog_44812_Content_62 = {
    Text = "Liz fissò intensamente il manager panciuto, il suo sguardo penetrante, costringendolo a distogliere istintivamente lo sguardo dai suoi occhi."
  },
  AvgDialog_44812_Content_63 = {
    Text = "Mi dica, ha venduto la signorina Deneuve al Conte Geoffrey?"
  },
  AvgDialog_44812_Content_64 = {Text = "Vendere?"},
  AvgDialog_44812_Content_65 = {
    Text = "Sembrando aver colto una falla nelle parole di Liz, il manager acquisì sicurezza, gonfiò il petto e parlò con certezza."
  },
  AvgDialog_44812_Content_66 = {
    Text = "Deneuve ha sposato il Conte di sua spontanea volontà! Quanto a ciò che è accaduto dopo il matrimonio, non è qualcosa su cui un umile Manager di Compagnia di Danza come me possa commentare con leggerezza — sono nobili!"
  },
  AvgDialog_44812_Content_67 = {Text = "..."},
  AvgDialog_44812_Content_68 = {
    Text = "Quindi, la compagnia di danza è sempre stata il tuo strumento per cercare fama e riconoscimento—una scala per ingraziarti i potenti..."
  },
  AvgDialog_44812_Content_69 = {
    Text = "Sì. Esatto!"
  },
  AvgDialog_44812_Content_7 = {
    Text = "La Compagnia di danza Yadri ha una lunga storia ed è rinomata in tutta la Federazione, spesso invitata da nobili e persino da famiglie reali... Quando ero molto giovane, avevo già sentito parlare della compagnia."
  },
  AvgDialog_44812_Content_70 = {
    Text = "Lo sai come il pubblico ci vede, come vede te? I poveri ti ammirano, mentre i ricchi ti scelgono! Guarda in tutto il continente — ogni compagnia è uguale."
  },
  AvgDialog_44812_Content_71 = {
    Text = "La mia famiglia no! Anche loro sono membri della compagnia di danza, loro..."
  },
  AvgDialog_44812_Content_72 = {
    Text = "Il vecchio Salle ti ha davvero tessuto un bel sogno. Non sai nulla degli affari della Compagnia di Danza Salle? Tuo nonno era il più famigerato protettore dell'intera Federazione Constante!"
  },
  AvgDialog_44812_Content_73 = {
    Text = "Mi segui adesso? In questo mondo, l'arte pura non esiste!"
  },
  AvgDialog_44812_Content_74 = {
    Text = "Il contratto che hai firmato quando sei entrata dimostra che ho pieno controllo su di te — quindi non puoi andare da nessuna parte finché non sarai disposta a \"vedere\" il Conte!"
  },
  AvgDialog_44812_Content_75 = {
    Text = "D'accordo, non lascerò il teatro."
  },
  AvgDialog_44812_Content_76 = {
    Text = "Ti riconosco il merito di sapere quando cedere, purché tu—"
  },
  AvgDialog_44812_Content_77 = {
    Text = "Ma di conseguenza, non continuerò a partecipare alle prove generali de \"L'Elegia del Cigno\". Non vi insegnerò i passi dell'atto finale."
  },
  AvgDialog_44812_Content_78 = {Text = "Tu—!"},
  AvgDialog_44812_Content_79 = {
    Text = "Non permetterò che continuiate a macchiare la mia opera; non sarà il vostro strumento per trattare con la nobiltà."
  },
  AvgDialog_44812_Content_8 = {
    Text = "Un anno fa, in una notte di mezza estate, fuggii dal Focolare e mi unii alla Compagnia di danza Yadri."
  },
  AvgDialog_44812_Content_80 = {
    Text = "Voglio abbandonare lo spettacolo."
  },
  AvgDialog_44812_Content_81 = {Text = "Ora"},
  AvgDialog_44812_Content_82 = {
    Text = "La dura realtà ti fa sudare e ti fa rizzare i capelli. L'impacco di ghiaccio nella tua mano si scioglie senza che tu te ne accorga, l'acqua scorre lungo il braccio e inzuppa il tuo vestito da danza."
  },
  AvgDialog_44812_Content_83 = {
    Text = "In realtà, la Responsabile del Gruppo di Danza... è coinvolta in tali attività."
  },
  AvgDialog_44812_Content_84 = {
    Text = "Tu... non ti sei accorto della loro malvagità?"
  },
  AvgDialog_44812_Content_85 = {
    Text = "Sei il nuovo talento dissotterrato dalla massa da quel porco, proprio come me un anno fa. Pensavo che anche tu avessi scoperto qualcosa, e che per questo tu..."
  },
  AvgDialog_44812_Content_86 = {
    Text = "No, ero solo molto nervoso..."
  },
  AvgDialog_44812_Content_87 = {
    Text = "Tutto ciò che Liz ha detto ti turbina nella mente, e d'istinto vorresti crederle, ma..."
  },
  AvgDialog_44812_Content_88 = {
    Text = "Hai lanciato un'occhiata al calendario accanto al letto; questo sogno era molto vicino alla tua \"realtà\". Meno di trent'anni fa. Elizabeth Salle era viva."
  },
  AvgDialog_44812_Content_89 = {
    Text = "Nella tua epoca, gli spettacoli di balletto erano occasioni assolutamente eleganti. Sotto il patrocinio di Lord Dexter, accompagnavi Ramona a diversi spettacoli di varie compagnie."
  },
  AvgDialog_44812_Content_9 = {Text = "un anno fa"},
  AvgDialog_44812_Content_90 = {
    Text = "Se le compagnie di danza erano così corrotte, cosa ha portato a un cambiamento così drastico?"
  },
  AvgDialog_44812_Content_91 = {
    Text = "Ma perché sei salita sul palco per salvare lo spettacolo stasera? Voglio dire, dato che te n'eri già andata..."
  },
  AvgDialog_44812_Content_92 = {
    Text = "Liz alzò lo sguardo verso di te, come un'anziana che osserva una bambina sciocca — nonostante fosse tecnicamente ancora minorenne."
  },
  AvgDialog_44812_Content_93 = {
    Text = "Perché non riesco a farlo."
  },
  AvgDialog_44812_Content_94 = {
    Text = "Prima ancora di imparare a camminare, sapevo già come muovere le braccia nei gesti del balletto. Mentre gli altri fanciulli della mia età giocavano a nascondino, io mi esercitavo di nascosto a camminare sulle punte nel magazzino, ed ero così felice."
  },
  AvgDialog_44812_Content_95 = {
    Text = "Non posso rinunciare a danzare, né posso lasciar andare il mio lavoro... Non sopporto vedere il direttore riempire l'\"Elegia del Cigno\" di passi goffi e volgari."
  },
  AvgDialog_44812_Content_96 = {
    Text = "Lo sta usando per umiliarmi... per umiliare la mia arte."
  },
  AvgDialog_44812_Content_97 = {
    Text = "Liz ti strinse le mani sempre più forte, con una tale intensità che sentivi di stare per dissolverti nel suo dolore."
  },
  AvgDialog_44812_Content_98 = {
    Text = "In quell'istante, la tua anima sembrò comprendere la sua rabbia e il suo pianto — e così anche quel corpo."
  },
  AvgDialog_44812_Content_99 = {
    Text = "Sbattesti le palpebre senza controllo, le lacrime aggrappate alle ciglia, rendendo il mondo davanti ai tuoi occhi sfocato."
  },
  AvgDialog_44833_Content_1 = {
    Text = "Elegia del cigno"
  },
  AvgDialog_44833_Content_10 = {
    Text = "Cos'è questo odore... È così familiare."
  },
  AvgDialog_44833_Content_11 = {
    Text = "Nel momento in cui la tua mano tocca la porta, avverti il calore che permea il corridoio del backstage, e volute di fumo si insinuano nella stanza attraverso le fessure."
  },
  AvgDialog_44833_Content_12 = {
    Text = "È un incendio?!"
  },
  AvgDialog_44833_Content_13 = {
    Text = "Il buon senso ti dice che la porta della stanza non reggerà a lungo. Se la struttura di questo teatro è fatta di semplice legno, l'intero edificio sarà presto divorato dalle fiamme."
  },
  AvgDialog_44833_Content_14 = {
    Text = "Per lasciare la stanza, ma non attraverso la porta, il tuo sguardo si sposta sull'unica finestra.\nSe Liz è riuscita a entrare dalla finestra... allora puoi farlo anche tu."
  },
  AvgDialog_44833_Content_15 = {
    Text = "Come previsto, una carrozza è parcheggiata sotto la finestra. Ti arrampichi fuori e sali sul tetto della carrozza, lasciando agevolmente la stanza al secondo piano."
  },
  AvgDialog_44833_Content_16 = {
    Text = "Segui il rumore fino alla piazza antistante il teatro. La piazza è colma di un caos di voci, e gli ospiti in abiti eleganti si spintonano nella fuga precipitosa dal teatro —"
  },
  AvgDialog_44833_Content_17 = {
    Text = "Fuori dai piedi! Sono il Maggiordomo del Conte Geoffrey. Fatemi passare per primo!"
  },
  AvgDialog_44833_Content_18 = {
    Text = "È impazzita! Ha perso il senno!"
  },
  AvgDialog_44833_Content_19 = {
    Text = "Afferri prontamente la Nobildonna il cui chignon si è disfatto a forza di correre."
  },
  AvgDialog_44833_Content_2 = {Text = "Crepitio."},
  AvgDialog_44833_Content_20 = {
    Text = "Mi scusi, cos'è successo nel teatro?"
  },
  AvgDialog_44833_Content_21 = {
    Text = "Sei una Danzatrice?! Non toccarmi! Sei con quella pazza del Secondo Teatro, vero?"
  },
  AvgDialog_44833_Content_22 = {
    Text = "Secondo Teatro... è Liz? Potrebbe essere Elizabeth? La ragazza con l'abito da danza nero?"
  },
  AvgDialog_44833_Content_23 = {
    Text = "Tu conosci quella folle! E pretendi di non essere sua complice! Qualcuno ammazzi di botte quella Danzatrice per me!"
  },
  AvgDialog_44833_Content_24 = {
    Text = "I lacchè e alcuni astanti si scambiano occhiate, chiaramente restii a infrangere la legge per il volere del Nobile."
  },
  AvgDialog_44833_Content_25 = {
    Text = "Darò 100 Fiorini Leoniani al primo che taglierà una testa! No, facciamo 300!"
  },
  AvgDialog_44833_Content_26 = {
    Text = "Una grossa somma di denaro viene scagliata verso i lavoratori tremanti, spingendoli ad alzare i loro attrezzi e lanciarsi alla Carica contro di te—"
  },
  AvgDialog_44833_Content_3 = {
    Text = "Tenendoti la testa, ti svegli lentamente. Non sai quanto tempo sia passato; fuori dalla finestra è ancora notte.\nPotrebbe essere passata solo mezz'ora, o potrebbe essere trascorso un giorno intero."
  },
  AvgDialog_44833_Content_4 = {
    Text = "È l'odore di Etere altamente concentrato... Il responsabile ha davvero congelato una sostanza così pericolosa in blocchi di ghiaccio."
  },
  AvgDialog_44833_Content_5 = {Text = "..."},
  AvgDialog_44833_Content_6 = {
    Text = "Liz mi ha dato dei cubetti di ghiaccio non appena sono entrata, quindi... non importa come le abbia risposto, aveva già deciso di drogarmi il drink fin dall'inizio..."
  },
  AvgDialog_44833_Content_7 = {
    Text = "Elizabeth Salle. Liz... Cosa vuoi davvero fare?"
  },
  AvgDialog_44833_Content_8 = {Text = "Crepitio."},
  AvgDialog_44833_Content_9 = {
    Text = "Un aroma primitivo, carbonizzato e naturale ti invade le narici, precipitandosi nelle profondità del cervello e scacciando con forza gli effetti residui del farmaco."
  },
  AvgDialog_44835_Content_1 = {
    Text = "Raccogli il coraggio per spalancare la porta del Primo Teatro. Sebbene le fiamme non siano ancora arrivate fin qui, una coltre di fumo denso e calore ti colpisce in pieno volto, bruciandoti gli occhi."
  },
  AvgDialog_44835_Content_10 = {
    Text = "La Danzatrice trema violentemente, come se avesse udito il nome di un demone."
  },
  AvgDialog_44835_Content_11 = {
    Text = "Elizabeth è impazzita! Ha drogato il cibo per il pubblico e per Tutti gli altri! Sono svenuti Tutti!"
  },
  AvgDialog_44835_Content_12 = {
    Text = "Solo quelli come me, in sovrappeso e a cui è vietato mangiare, e alcune signore che avevano saltato i pasti per restare snelle, sono riusciti a cavarsela..."
  },
  AvgDialog_44835_Content_13 = {
    Text = "Ehi! Ehi, non correre! Ho detto di non entrare!"
  },
  AvgDialog_44835_Content_14 = {
    Text = "Ignori l'avvertimento della Danzatrice e ti precipiti verso il Secondo Teatro."
  },
  AvgDialog_44835_Content_15 = {
    Text = "@2 Giardino, Secondo Teatro"
  },
  AvgDialog_44835_Content_16 = {Text = "Liz!"},
  AvgDialog_44835_Content_17 = {
    Text = "Spalancando la porta del Secondo Teatro, la scena ti gela il Sangue nelle vene. Ospiti e Danzatrici in preda al Faint giacciono sparsi sul pavimento."
  },
  AvgDialog_44835_Content_18 = {
    Text = "L'atrio un tempo brulicante è ora silenzioso, con le fiamme che si propagano ovunque. Solo le aree contrassegnate dal D-segno sono state risparmiate — alcune cose in questo mondo nemmeno il fuoco può consumare."
  },
  AvgDialog_44835_Content_19 = {
    Text = "Non saresti dovuto venire."
  },
  AvgDialog_44835_Content_2 = {
    Text = "*Coff, coff...*"
  },
  AvgDialog_44835_Content_20 = {
    Text = "Liz è in piedi nell'angolo del palcoscenico. Non riesci a vederla; solo la sua Voce giunge dall'altra metà del teatro."
  },
  AvgDialog_44835_Content_21 = {
    Text = "Liz, sei stata tu ad appiccare questo incendio?"
  },
  AvgDialog_44835_Content_22 = {
    Text = "Una risata amara giunge dal palcoscenico, e sai che la domanda è troppo debole.\nChe Liz abbia appiccato il fuoco o meno, il destino suo e \"tuo\" è già segnato."
  },
  AvgDialog_44835_Content_23 = {
    Text = "█A.F.29@1 @2 Il Secondo Teatro del Giardino ha preso fuoco durante una rappresentazione del balletto \"Elegia del Cigno\".\n█Tra cui il Conte Geoffrey, membro della nobiltà reale, e altri, un totale di 13 nobili, 25 servitori, 12 danzatrici e 1 manager del gruppo di danza perirono tra le fiamme.\n█Dopo le indagini, la responsabile dell'incendio è stata identificata nella defunta prima ballerina \"Elizabeth Salle\"."
  },
  AvgDialog_44835_Content_24 = {
    Text = "Liz non risponde. È ancora voltata di spalle, e muove una mano avanti e indietro, come se stesse avvolgendo qualcosa."
  },
  AvgDialog_44835_Content_25 = {Text = "D'accordo."},
  AvgDialog_44835_Content_26 = {
    Text = "Avanza di due passi e si ferma immobile al centro del palcoscenico. Poi una musica fluida si riversa nell'aria, fondendosi con il crepitio delle fiamme."
  },
  AvgDialog_44835_Content_27 = {
    Text = "Questo sarà il vero Cala il Sipario di \"Elegia del cigno\". Anche se dovrò accontentarmi del Fonografo per la musica."
  },
  AvgDialog_44835_Content_28 = {
    Text = "Hai lasciato andare i musicisti perché erano Innocenti, vero?"
  },
  AvgDialog_44835_Content_29 = {
    Text = "Anche tu sei Innocente. Puoi ancora andartene. Ti osservo da un po'. So che non sei con loro."
  },
  AvgDialog_44835_Content_3 = {
    Text = "Strappi un pezzo di tovaglia, rovesci un vaso decorativo e usi l'acqua dei fiori per inumidire il tessuto."
  },
  AvgDialog_44835_Content_30 = {
    Text = "Io... No, ho profanato la vostra arte. Ho quasi rovinato la vostra \"Elegia del cigno\", ricordate?"
  },
  AvgDialog_44835_Content_31 = {
    Text = "Liz si inginocchia sul palcoscenico, tendendo la Mano per invitarti ad avvicinarti. Solo ora noti che il palcoscenico è ricoperto di melma nera — potrebbe essere D-melma?"
  },
  AvgDialog_44835_Content_32 = {
    Text = "Hai appena mosso due passi verso di lei quando una raffica di Vento spalanca le finestre del teatro. Le fiamme silenziose vengono improvvisamente ravvivate, lanciandosi a Mordere i tendoni del palcoscenico."
  },
  AvgDialog_44835_Content_33 = {
    Text = "Liz! Scendi, il fuoco si sta propagando!"
  },
  AvgDialog_44835_Content_34 = {
    Text = "L'architrave crolla con un fragore assordante, travi carbonizzate si schiantano al suolo sollevando Nuvole di cenere e scintille, e incendiando il tappeto di cashmere."
  },
  AvgDialog_44835_Content_35 = {
    Text = "Liz, Elizabeth! Non fare sciocchezze! Andiamocene via insieme. C'è ancora tempo!"
  },
  AvgDialog_44835_Content_36 = {
    Text = "Vi prego, date a questo mondo un'altra possibilità... Tra trent'anni, il balletto sarà considerato una delle più nobili forme d'arte! Concedetegli solo un po' di tempo..."
  },
  AvgDialog_44835_Content_37 = {
    Text = "Liz giace al bordo del palcoscenico e tende la Mano verso di te ancora una volta."
  },
  AvgDialog_44835_Content_38 = {
    Text = "Il suo palmo è imbrattato di D-melma, eppure quando sfiora la tua guancia, porta con sé il calore di una persona viva."
  },
  AvgDialog_44835_Content_39 = {
    Text = "So che oggi non posso porre fine a tutto il male di questo mondo... L'ho sempre saputo."
  },
  AvgDialog_44835_Content_4 = {
    Text = "Coprendoti bocca e naso con il panno umido, l'aria densa, ricca di un sentore terroso e radicoso, ti riempie i polmoni. Ti abbassi e avanzi a tentoni lentamente sul tappeto."
  },
  AvgDialog_44835_Content_40 = {
    Text = "Tutto ciò che voglio è accendere un fuoco. Un fuoco che riveli l'Oscurità, che lasci risplendere la Giustizia. Non ho altra Scelta."
  },
  AvgDialog_44835_Content_41 = {
    Text = "Detto questo, ti spinge via con tutta la sua Possanza."
  },
  AvgDialog_44835_Content_42 = {
    Text = "Scusa, ti ho drogato senza il tuo consenso."
  },
  AvgDialog_44835_Content_43 = {
    Text = "Sei sicuro di non volertene andare? Puoi ancora saltare dalla finestra."
  },
  AvgDialog_44835_Content_44 = {
    Text = "Scuoti la testa e ti siedi al bordo del palcoscenico, le braccia strette attorno alle gambe."
  },
  AvgDialog_44835_Content_45 = {
    Text = "Conti le persone in abiti da Danza nel teatro, Liz compresa, e sono solo 11."
  },
  AvgDialog_44835_Content_46 = {
    Text = "Il che fa di te il dodicesimo a perire tra le fiamme."
  },
  AvgDialog_44835_Content_47 = {
    Text = "Bene. Allora ti renderò il mio unico spettatore di oggi."
  },
  AvgDialog_44835_Content_48 = {
    Text = "Elizabeth Salle, in un'esibizione solista di \"Elegia del cigno\"."
  },
  AvgDialog_44835_Content_49 = {
    Text = "Liz si inchina verso di te e solleva con noncuranza il sipario in fiamme; la D-melma sulle sue mani e sul suo Corpo si incendia all'istante — no, è catrame."
  },
  AvgDialog_44835_Content_5 = {Text = "—Ahi!"},
  AvgDialog_44835_Content_50 = {
    Text = "Fuochi d'artificio Cremisi sbocciano silenziosi lungo l'orlo, come ali di cigno tremanti che si levano dalle Ceneri."
  },
  AvgDialog_44835_Content_51 = {
    Text = "Liz volteggia con grazia, e ogni giro la avvicina alla meteora di fuoco che solca il cielo notturno."
  },
  AvgDialog_44835_Content_52 = {
    Text = "La figlia dell'arte grida il suo capitolo finale, le fiamme si riversano sul palcoscenico — eppure non vi è terrore nei suoi occhi."
  },
  AvgDialog_44835_Content_53 = {
    Text = "Il fonografo è consumato, ridotto in braci. Mentre l'ultima nota svanisce nella luce del fuoco, la sua silhouette si dissolve nel rogo."
  },
  AvgDialog_44835_Content_54 = {
    Text = "Nel suo ultimo balzo attraverso le fiamme, alcuni trovarono pace, mentre altri intravidero una nuova era."
  },
  AvgDialog_44835_Content_6 = {
    Text = "La ragazza in corsa si scontra con te, e cadete entrambi a Terra."
  },
  AvgDialog_44835_Content_7 = {
    Text = "Perché stai ancora entrando?! Corsa, presto!"
  },
  AvgDialog_44835_Content_8 = {
    Text = "Ricordi questa Danzatrice. Secondo la descrizione di Liz, sembrava particolarmente calorosa e gentile."
  },
  AvgDialog_44835_Content_9 = {
    Text = "Liz è dentro?"
  },
  AvgDialog_45413_Content_1 = {Text = "..."},
  AvgDialog_45413_Content_10 = {Text = "N..."},
  AvgDialog_45413_Content_11 = {
    Text = "Perché ricordo solo adesso come ho ottenuto questa forma?"
  },
  AvgDialog_45413_Content_12 = {
    Text = "È perché ho sentito il nome di quell'uomo, o sto avendo un flashback in punto di morte?"
  },
  AvgDialog_45413_Content_13 = {
    Text = "Vecchie Memorie di molto, molto tempo fa stanno riaffiorando."
  },
  AvgDialog_45413_Content_14 = {
    Text = "Prima di diventare \"la Bestia,\" ero solo un detective qualunque—il tipo che dopo aver incassato la paga si concedeva un paio di drink e una partita."
  },
  AvgDialog_45413_Content_15 = {
    Text = "La mia fortuna mostruosa mi aveva fruttato parecchi incarichi dall'ispettore di Londinium—indizi o covi di sospettati."
  },
  AvgDialog_45413_Content_16 = {
    Text = "Non c'è motivo di rifiutare denaro facile."
  },
  AvgDialog_45413_Content_17 = {
    Text = "Finché un giorno, il criminale che avevo arrestato svanì dalla cella, lasciando manette d'argento perfettamente intatte a dondolare nel vento."
  },
  AvgDialog_45413_Content_18 = {
    Text = "Non erano affari miei, ovviamente. Mi limitai ad andare al solito casinò clandestino per sperperare la commissione appena incassata."
  },
  AvgDialog_45413_Content_19 = {
    Text = "Tu sei... quel sospettato in fuga!"
  },
  AvgDialog_45413_Content_2 = {
    Text = "Un enorme Artiglio trasparente si materializza in alto, sbattendo Ryker contro il muro."
  },
  AvgDialog_45413_Content_20 = {
    Text = "Oh, tu devi essere quello che mi ha catturato?"
  },
  AvgDialog_45413_Content_21 = {
    Text = "Non mi sarebbe dispiaciuto farmi riaccompagnare in gattabuia per un paio di giorni—"
  },
  AvgDialog_45413_Content_22 = {
    Text = "Agitò il bussolotto dei dadi che aveva in mano."
  },
  AvgDialog_45413_Content_23 = {
    Text = "Ma prima devi battermi."
  },
  AvgDialog_45413_Content_24 = {
    Text = "Non pensavo di perdere."
  },
  AvgDialog_45413_Content_25 = {
    Text = "Avevo venticinque anni, non avevo mai assaporato la sconfitta."
  },
  AvgDialog_45413_Content_26 = {
    Text = "Una volta che mi concentrai a fondo e lasciai che le luci del casinò, il rotolare dei dadi e il voltare delle carte mi penetrassero dentro..."
  },
  AvgDialog_45413_Content_27 = {
    Text = "Il mio istinto mi dava la risposta."
  },
  AvgDialog_45413_Content_28 = {Text = "Tira."},
  AvgDialog_45413_Content_29 = {
    Text = "Un momento — non hai detto la tua posta."
  },
  AvgDialog_45413_Content_3 = {
    Text = "Il Sangue cola dalla bocca di Ryker; l'aria viene spremuta dai suoi polmoni, ogni respiro una lotta."
  },
  AvgDialog_45413_Content_30 = {Text = "Cosa vuoi?"},
  AvgDialog_45413_Content_31 = {
    Text = [[
Non avevo intenzione di scommettere nulla.
Qualunque cosa fosse, avrei vinto comunque.]]
  },
  AvgDialog_45413_Content_32 = {
    Text = "Avanti — puoi chiedere qualsiasi cosa."
  },
  AvgDialog_45413_Content_33 = {
    Text = "Hmm... Che ne dici di quel sigaro?"
  },
  AvgDialog_45413_Content_34 = {
    Text = "Indicò quello che avevo in bocca."
  },
  AvgDialog_45413_Content_35 = {Text = "..."},
  AvgDialog_45413_Content_36 = {
    Text = "Spiacente, ma il tuo sigaro adesso è mio."
  },
  AvgDialog_45413_Content_37 = {
    Text = "Mi strappò il sigaro acceso dalla mano, sogghignò e tirò una boccata profonda. Ignorando il mio shock, soffiò anelli di fumo bianchi con aria beffarda."
  },
  AvgDialog_45413_Content_38 = {
    Text = "Un altro giro?"
  },
  AvgDialog_45413_Content_39 = {
    Text = "Quel giorno persi il portafoglio, il bastone, il deerstalker, la cravatta e il completo."
  },
  AvgDialog_45413_Content_4 = {
    Text = "Prima o poi finirai i proiettili. Che senso ha trascinare ancora la cosa?"
  },
  AvgDialog_45413_Content_40 = {
    Text = "Giocammo a alto-basso, blackjack, Texas hold'em."
  },
  AvgDialog_45413_Content_41 = {
    Text = "Centinaia di partite, zero vittorie."
  },
  AvgDialog_45413_Content_42 = {
    Text = "Alla fine, tirò fuori un revolver."
  },
  AvgDialog_45413_Content_43 = {
    Text = "Roulette russa — un gioco brutale in cui si scommette la vita."
  },
  AvgDialog_45413_Content_44 = {
    Text = "I giocatori d'azzardo sparano a turno contro sé stessi finché l'unico proiettile non colpisce la tempia di qualcuno."
  },
  AvgDialog_45413_Content_45 = {
    Text = "Premetti il grilletto senza pensarci due volte; il proiettile mi reclamò la vita senza pietà."
  },
  AvgDialog_45413_Content_46 = {
    Text = "Inseguii quell'uomo chiamato \"N,\" scommettendo 316 round per farlo confessare."
  },
  AvgDialog_45413_Content_47 = {
    Text = "Non ti avrei preso per il tipo da Giustizia."
  },
  AvgDialog_45413_Content_48 = {
    Text = "No, niente a che fare con la giustizia—semplicemente, non perdo mai."
  },
  AvgDialog_45413_Content_49 = {
    Text = "Ma quel giorno hai perso contro di lui. Perché dici \"mai\"?"
  },
  AvgDialog_45413_Content_5 = {
    Text = "Ogni tuo respiro affannoso, ogni battito del cuore... non fa che alimentare il mio spettacolo."
  },
  AvgDialog_45413_Content_50 = {
    Text = "Questo non è un quiz di vocabolario, amico mio."
  },
  AvgDialog_45413_Content_51 = {
    Text = "Io semplicemente... non avevo mai, mai perso prima. Chiaro e semplice."
  },
  AvgDialog_45413_Content_52 = {
    Text = "Il mio fato è vincere, qualunque cosa accada. Perciò ero curioso di sapere come quel tizio fosse riuscito a piegare il fato."
  },
  AvgDialog_45413_Content_53 = {
    Text = "Inseguire la curiosità a costo della vita? La gente mi dà del pazzo, ma ora non sono sicuro chi sia il più folle tra noi due."
  },
  AvgDialog_45413_Content_54 = {
    Text = "Esageri. C'è gente che passa la vita intera a cercare cure per la Dissoluzione. Herbert insegue l'ascensione umana; gli Aramiti cercano linee di sangue eterne."
  },
  AvgDialog_45413_Content_55 = {
    Text = "Tutti spendono la propria vita in ricerche forse infruttuose—la mia curiosità non è diversa, quindi non è un vero costo."
  },
  AvgDialog_45413_Content_56 = {
    Text = "E poi, quel tizio mi ha dato un nuovo corpo. Siamo in una nuova scommessa—ora ho tempo infinito per esplorare nuovi mondi. Potrebbe essere una benedizione sotto mentite spoglie."
  },
  AvgDialog_45413_Content_57 = {
    Text = "Prenderò questo singolo proiettile e un dolore momentaneo. Lui si farà vivo e scommetterà contro di me, ne sono certo. E so che farà in modo di vincere."
  },
  AvgDialog_45413_Content_58 = {
    Text = "Questa volta, N, scommetto che riuscirai a impedire a %player% di raggiungere il luogo del rito."
  },
  AvgDialog_45413_Content_59 = {
    Text = "Ryker preme il revolver contro la tempia."
  },
  AvgDialog_45413_Content_6 = {
    Text = "Più ti dibatti, più la mia gabbia si stringe."
  },
  AvgDialog_45413_Content_60 = {
    Text = "Hai troppa sicurezza. È da incoscienti."
  },
  AvgDialog_45413_Content_61 = {
    Text = [[
E se ti dicessi che N ha tirato i fili dietro ogni cosa?
Pensi ancora che ti aiuterebbe?]]
  },
  AvgDialog_45413_Content_62 = {
    Text = "Ryker sospira sommessamente."
  },
  AvgDialog_45413_Content_63 = {
    Text = "Da amante del brivido quale sei, non afferri mai le emozioni umane — perciò la tua idea di gioia non è mai davvero al culmine."
  },
  AvgDialog_45413_Content_64 = {
    Text = "Ci scommetto la vita — scommetto che onorerà il patto."
  },
  AvgDialog_45413_Content_65 = {
    Text = "Bam. Risuona un colpo di fucile."
  },
  AvgDialog_45413_Content_66 = {
    Text = "Seguito da secondi di silenzio."
  },
  AvgDialog_45413_Content_67 = {
    Text = "Ma che... Non puoi avvisarmi prima di spararti?"
  },
  AvgDialog_45413_Content_68 = {
    Text = "Una risata allegra esplode da un punto alto e lontano, dietro le quinte della realtà."
  },
  AvgDialog_45413_Content_69 = {
    Text = "Splendido, splendido! Audace come sempre—non ho sbagliato a donarti questa forma perfetta.\nBenissimo! Assaporerò le ultime gocce della tua vita ed esaudirò il tuo desiderio."
  },
  AvgDialog_45413_Content_7 = {
    Text = "Colui che ti ha dato quella forma—il suo nome è \"N,\" giusto? È così avaro?"
  },
  AvgDialog_45413_Content_70 = {
    Text = "Due dadi neri come la pece, bordati d'oro, compaiono nel palmo di Ryker."
  },
  AvgDialog_45413_Content_71 = {
    Text = "Lancia i dadi — un 1 naturale, e divorerò il tuo nemico."
  },
  AvgDialog_45413_Content_72 = {
    Text = "Ryker ride, tossendo sangue che si sparge sotto i riflettori."
  },
  AvgDialog_45413_Content_73 = {
    Text = "Non potevo chiedere di più."
  },
  AvgDialog_45413_Content_74 = {
    Text = "Ryker lancia i due dadi."
  },
  AvgDialog_45413_Content_75 = {
    Text = "Tintinnano e rotolano."
  },
  AvgDialog_45413_Content_76 = {
    Text = "Quando si tratta di fortuna..."
  },
  AvgDialog_45413_Content_77 = {
    Text = "Un dado si ferma sullo 0."
  },
  AvgDialog_45413_Content_78 = {
    Text = "Non perdo mai."
  },
  AvgDialog_45413_Content_79 = {
    Text = "L'altro si arresta sull'1."
  },
  AvgDialog_45413_Content_8 = {
    Text = "L'Artiglio si apre; Ryker precipita, tossendo violentemente, accasciandosi debole a terra."
  },
  AvgDialog_45413_Content_80 = {
    Text = "L'istante dopo — la risata sfrenata dell'essere superiore, e l'urlo straziante del mago."
  },
  AvgDialog_45413_Content_81 = {
    Text = "La D-melma nera corrode l'intero drappo, lasciando due brandelli a mezzaluna che svolazzano sulla sabbia."
  },
  AvgDialog_45413_Content_82 = {
    Text = "Come gli occhi allegri e increspati di un certo uomo."
  },
  AvgDialog_45413_Content_9 = {
    Text = "Sei a malapena materiale da Risveglio—l'Indice di Gnosi supera già il 21?"
  },
  AvgDialog_45414_Content_1 = {
    Text = "U-Un Mostro!"
  },
  AvgDialog_45414_Content_10 = {
    Text = "Le S-Spoglie sono... nella camera segreta più avanti!"
  },
  AvgDialog_45414_Content_11 = {
    Text = "Nel frattempo—Condotti della Fabbrica Abbandonata"
  },
  AvgDialog_45414_Content_12 = {
    Text = "Un ragazzo striscia attraverso i condotti della Fabbrica, ruggine e carbone che gli imbrattano i lineamenti fini di un nero chiazzato."
  },
  AvgDialog_45414_Content_13 = {
    Text = "Avanza furtivo, seguendo il gruppo sottostante."
  },
  AvgDialog_45414_Content_14 = {
    Text = "Avevo avvertito Lady Juliette fin dall'Inizio: quei viaggiatori non sono gente per bene..."
  },
  AvgDialog_45414_Content_15 = {Text = "..."},
  AvgDialog_45414_Content_16 = {Text = "..."},
  AvgDialog_45414_Content_17 = {
    Text = "Sulla soglia della camera segreta, l'uomo dalla testa di lupo sfonda il portone di ferro con un calcio, sollevando nubi di polvere. Lascia un Soldato di Aram legato all'ingresso; gli altri sfilano oltre le macerie."
  },
  AvgDialog_45414_Content_18 = {
    Text = "Il ragazzo scivola fuori dal condotto, liberando il cappuccio e le corde della Guardia."
  },
  AvgDialog_45414_Content_19 = {
    Text = "Shh, non metterli in Allerta. Va' ad avvisare il Capo Alva mentre io li pedino..."
  },
  AvgDialog_45414_Content_2 = {
    Text = "Combatti Nubia ogni giorno, eppure il mio aspetto ti fa impazzire di paura?"
  },
  AvgDialog_45414_Content_3 = {
    Text = "Ora parla. Dove avete nascosto i Resti dell'Albero Madre?"
  },
  AvgDialog_45414_Content_4 = {
    Text = "Per l'Albero Madre, non vi diremo nulla—"
  },
  AvgDialog_45414_Content_5 = {
    Text = "Oh? Davvero?"
  },
  AvgDialog_45414_Content_6 = {
    Text = "Ryker si accovaccia, un soffio lupesco che raschia in un Ringhio basso; le zanne scattano secche nel silenzio della Fabbrica."
  },
  AvgDialog_45414_Content_7 = {
    Text = "Sai cosa si prova a essere dilaniato da un lupo? Lascia che te lo descriva: zanne che affondano in profondità, strappando carne e nervi in brandelli sanguinolenti..."
  },
  AvgDialog_45414_Content_8 = {
    Text = "<Shake:N-No, non mangiarmi—parlo!>"
  },
  AvgDialog_45414_Content_9 = {Text = "Ehi, tu—"},
  AvgDialog_45415_Content_1 = {
    Text = "La tempesta infuria più violenta; i soldati di Aram urlano, si fanno prendere dal panico, gridano, implorano, maledicono."
  },
  AvgDialog_45415_Content_10 = {
    Text = "Innumerevoli Aramiti si volgono verso Thais, inginocchiandosi in solenne Devozione."
  },
  AvgDialog_45415_Content_11 = {
    Text = "Gli spiriti di sabbia impazziti si placano sotto il conforto della Preghiera; la tempesta si dissolve gradualmente."
  },
  AvgDialog_45415_Content_12 = {
    Text = "È la Regina! È la Regina!"
  },
  AvgDialog_45415_Content_13 = {
    Text = "Sia lodata la Regina!"
  },
  AvgDialog_45415_Content_14 = {
    Text = "Gli occhi della Regina vegliano ancora su di noi!"
  },
  AvgDialog_45415_Content_15 = {
    Text = "Ce... Ce l'abbiamo fatta!"
  },
  AvgDialog_45415_Content_2 = {
    Text = "Finalmente, scorgi una figura familiare su una duna."
  },
  AvgDialog_45415_Content_3 = {
    Text = "Riconosci la sagoma. È Thais."
  },
  AvgDialog_45415_Content_4 = {
    Text = "La tempesta... si sta placando?"
  },
  AvgDialog_45415_Content_5 = {
    Text = "Con il vento ululante che le sferza i veli, intona una Preghiera sconosciuta, avanzando lenta e sicura nella scura tempesta di sabbia."
  },
  AvgDialog_45415_Content_6 = {
    Text = "Il rombo assordante toglie l'udito, eppure la Preghiera lo trafigge nitida, echeggiando dentro il vostro cranio."
  },
  AvgDialog_45415_Content_7 = {
    Text = "Nella bufera che divora il cielo, conversa con calma con un'entità in agguato tra le sabbie del deserto."
  },
  AvgDialog_45415_Content_8 = {
    Text = "È la Regina! È venuta a salvarci... a salvare Aram!"
  },
  AvgDialog_45415_Content_9 = {
    Text = "Il gruppo di Aram, frenetico nella Fuga solo un istante prima, si arresta all'improvviso."
  },
  AvgDialog_45416_Content_1 = {
    Text = "Li conosci questi mostri, piccola?"
  },
  AvgDialog_45416_Content_10 = {
    Text = "Sotto la grazia dell'Albero Madre, gli Aramiti sono riusciti a contrastare l'alta mortalità infantile con un'innaturale velocità di allevamento."
  },
  AvgDialog_45416_Content_11 = {
    Text = "Ecco perché il festino del falò... non possiamo sopravvivere senza."
  },
  AvgDialog_45416_Content_12 = {
    Text = "Chiedile di Nubia."
  },
  AvgDialog_45416_Content_13 = {
    Text = "Non ho idea delle loro origini, ma portano un odore familiare."
  },
  AvgDialog_45416_Content_14 = {
    Text = "A volte, quei Nubia sembrano parenti degli Aramiti."
  },
  AvgDialog_45416_Content_15 = {
    Text = "...Dite che stanno spingendo gli Aramiti a varcare il Muro della Tempesta?"
  },
  AvgDialog_45416_Content_16 = {
    Text = "Lo immaginavo. Anche gli Aramiti bramano il passaggio oltre quel Muro della Tempesta. Per trovare l'Albero Madre."
  },
  AvgDialog_45416_Content_17 = {
    Text = "Ma è comunque futile. Il Muro della Tempesta cede solo agli inviati riconosciuti."
  },
  AvgDialog_45416_Content_18 = {
    Text = "Altre domande?"
  },
  AvgDialog_45416_Content_19 = {
    Text = "Chiedile di Juliette."
  },
  AvgDialog_45416_Content_2 = {
    Text = "Hmm, no—rispetto a queste bestie, il più strano sei tu. Il vero mostro."
  },
  AvgDialog_45416_Content_20 = {
    Text = "Ancora una cosa: quella \"inviata\", Juliette. Parlami di lei."
  },
  AvgDialog_45416_Content_21 = {
    Text = "L'Inviata Straniera?"
  },
  AvgDialog_45416_Content_22 = {
    Text = "Questa è la mia domanda per te."
  },
  AvgDialog_45416_Content_23 = {
    Text = "%player%, ti fidi di quell'inviata?"
  },
  AvgDialog_45416_Content_24 = {Text = "Sì."},
  AvgDialog_45416_Content_25 = {Text = "No."},
  AvgDialog_45416_Content_26 = {
    Text = "Prima che tu possa parlare, Thais si avvicina, la punta del dito che ti sfiora le labbra."
  },
  AvgDialog_45416_Content_27 = {
    Text = "Non c'è fretta. Prenditi il tuo tempo."
  },
  AvgDialog_45416_Content_28 = {
    Text = "Abbiamo ancora... tutto il tempo del mondo."
  },
  AvgDialog_45416_Content_3 = {
    Text = "Ora, piccolo mostro, cosa vorresti sapere?"
  },
  AvgDialog_45416_Content_4 = {
    Text = "Chiedile del Festino del Falò."
  },
  AvgDialog_45416_Content_5 = {
    Text = "Sigh. Sono ancora triste per quella notte."
  },
  AvgDialog_45416_Content_6 = {
    Text = "Non avrei mai pensato che qualcuno rifiutasse di generare un erede per la Regina di Aram."
  },
  AvgDialog_45416_Content_7 = {
    Text = "In una parola: pensate che questo deserto sia adatto alla prosperità umana?"
  },
  AvgDialog_45416_Content_8 = {
    Text = "Ricordi le raffiche sferzanti, le sorgenti prosciugate, i predatori notturni, le creature velenose striscianti e le riserve d'acqua contaminate dalla Dissoluzione. Scuoti il capo."
  },
  AvgDialog_45416_Content_9 = {
    Text = "Ma non possiamo andarcene."
  },
  AvgDialog_45417_Content_1 = {
    Text = "I rami dell'Albero Madre sembrano senzienti, protendendosi avidamente in ogni direzione; sagome umane tremolano al loro interno, i movimenti goffi e sofferenti."
  },
  AvgDialog_45417_Content_10 = {
    Text = "Ramona! Incendia l'Albero Madre con le Fiamme d'Argento! Solo tu puoi farlo!"
  },
  AvgDialog_45417_Content_11 = {
    Text = "Fantasmi d'Argento assaltano le radici dell'Albero Madre; fiamme argentee erompono, trasformandosi in un incendio di Distruzione."
  },
  AvgDialog_45417_Content_12 = {
    Text = "Lingue di fuoco strisciano lungo il tronco come serpenti d'argento; i rami si contorcono e urlano nella furia, sibilando acuti—come se l'Albero Madre gemesse in un tormento straziante."
  },
  AvgDialog_45417_Content_13 = {
    Text = "Aspettate—l'albero sta crollando, e il Custode è ancora lassù!"
  },
  AvgDialog_45417_Content_14 = {
    Text = "Non preoccuparti, cara—lo riporterò {Male=sano e salvo,Female=sana e salva}."
  },
  AvgDialog_45417_Content_15 = {
    Text = "L'albero colossale si scuote; la terra trema."
  },
  AvgDialog_45417_Content_16 = {
    Text = "Perdi l'equilibrio, precipitando in verticale—"
  },
  AvgDialog_45417_Content_17 = {
    Text = "Quanto in alto? Mille piedi? Di più?"
  },
  AvgDialog_45417_Content_18 = {
    Text = "Poi, un Abbraccio caldo e morbido ti accoglie."
  },
  AvgDialog_45417_Content_19 = {
    Text = "Brava creatura, sei stata meravigliosa."
  },
  AvgDialog_45417_Content_2 = {
    Text = "Il primo a formare una gola geme, liberandosi a fatica dalla presa dell'Albero Madre, precipitando dall'alto nel Fiume sacro."
  },
  AvgDialog_45417_Content_20 = {
    Text = "Sul suo petto, la giada bianca che le hai allacciato risplende contro la sua pelle serica."
  },
  AvgDialog_45417_Content_21 = {
    Text = "Thais lo sgancia, lo ingoia, mordendo delicatamente."
  },
  AvgDialog_45417_Content_22 = {
    Text = "Farò Ritorno al Fiume sacro, nutrendo l'intera Terra.\nQuesto è il mio dono d'addio per te."
  },
  AvgDialog_45417_Content_23 = {
    Text = "Nell'istante in cui ti tuffi nel Fiume sacro in tumulto, le sue labbra incontrano le tue."
  },
  AvgDialog_45417_Content_24 = {
    Text = "I vostri respiri si intrecciano. Le vostre anime si fondono in uno."
  },
  AvgDialog_45417_Content_25 = {
    Text = "La sua lingua scivola dentro—calda, umida, tenera eppure insistente."
  },
  AvgDialog_45417_Content_26 = {
    Text = "Il bacio mescola la dolcezza dell'amore, il sapore metallico del Sangue, e qualcosa di piccolo, rotondo... indefinito."
  },
  AvgDialog_45417_Content_27 = {
    Text = "Il Seme dell'albero."
  },
  AvgDialog_45417_Content_28 = {Text = "..."},
  AvgDialog_45417_Content_29 = {Text = "..."},
  AvgDialog_45417_Content_3 = {Text = "...Splash!"},
  AvgDialog_45417_Content_30 = {Text = "..."},
  AvgDialog_45417_Content_31 = {
    Text = "È finita... Anche se non nel modo in cui immaginavo."
  },
  AvgDialog_45417_Content_32 = {
    Text = "In quanto discendenti dell'Eone del Desiderio, gli Aramiti erano ossessionati dalla continuità della stirpe.."
  },
  AvgDialog_45417_Content_33 = {
    Text = "Veneravamo l'Albero Madre, fondendo la sua essenza nelle nostre ossa, alla ricerca di una fertilità sovrumana."
  },
  AvgDialog_45417_Content_34 = {
    Text = "La nostra convinzione era che, se anche un solo discendente fosse sopravvissuto alla rovina nera, la nostra civiltà avrebbe potuto Sopportare fino al ciclo successivo."
  },
  AvgDialog_45417_Content_35 = {
    Text = "Ma ci sbagliavamo."
  },
  AvgDialog_45417_Content_36 = {
    Text = "Il loro vero sostentamento non era un singolo discendente; erano completamente schiavi della riproduzione, incatenati da un incontrollabile impulso di Allevamento attraverso le ere."
  },
  AvgDialog_45417_Content_37 = {
    Text = "In secoli di Esilio... solo Alva ha davvero fatto progredire Aram."
  },
  AvgDialog_45417_Content_38 = {
    Text = "Tawil, avevi ragione. Dovremmo fidarci della volontà umana."
  },
  AvgDialog_45417_Content_39 = {
    Text = "Anche nell'Oscurità senza fine, anche se la Luce della Speranza è Faint... Gli esseri umani non cedono mai; quello Spirito da solo può mutare i futuri segnati dal Fato."
  },
  AvgDialog_45417_Content_4 = {Text = "Splash!"},
  AvgDialog_45417_Content_40 = {
    Text = "Ora, ho trovato una nuova risposta."
  },
  AvgDialog_45417_Content_41 = {
    Text = "Quindi, Tawil, prestami il tuo successore prescelto. Sii generoso, vuoi?"
  },
  AvgDialog_45417_Content_42 = {
    Text = "Affiderò il mio seme a {Male=lui,Female=lei}."
  },
  AvgDialog_45417_Content_43 = {
    Text = "Il seme metterà radici, germoglierà, crescerà in un albero magnifico—"
  },
  AvgDialog_45417_Content_44 = {
    Text = "Come nacque il primo Albero Madre."
  },
  AvgDialog_45417_Content_45 = {Text = "..."},
  AvgDialog_45417_Content_46 = {
    Text = "Quest'ultimo seme — lo pianto dentro di te."
  },
  AvgDialog_45417_Content_47 = {
    Text = "Finché non spargerà il mio sangue sulla terra, tu non devi morire..."
  },
  AvgDialog_45417_Content_48 = {
    Text = "Ti ricorderai di me. Non dimenticarmi mai."
  },
  AvgDialog_45417_Content_49 = {
    Text = "Le maree si sollevano."
  },
  AvgDialog_45417_Content_5 = {
    Text = "Splash! Splash!"
  },
  AvgDialog_45417_Content_50 = {
    Text = "Quel caldo abbraccio ti respinge."
  },
  AvgDialog_45417_Content_51 = {
    Text = "Nell'assalto tumultuoso della corrente, la vedi scivolare più in profondità nel fiume."
  },
  AvgDialog_45417_Content_52 = {Text = "..."},
  AvgDialog_45417_Content_53 = {
    Text = "Una Mano pallida e sottile ti afferra—familiare, salda."
  },
  AvgDialog_45417_Content_54 = {Text = "%player%!"},
  AvgDialog_45417_Content_6 = {
    Text = "Gli Aramiti cadono, uno dopo l'altro."
  },
  AvgDialog_45417_Content_7 = {
    Text = "Pochi istanti dopo, piccole teste emergono, lottando per raggiungere la riva."
  },
  AvgDialog_45417_Content_8 = {
    Text = "Il ramo sotto i tuoi piedi trema."
  },
  AvgDialog_45417_Content_9 = {
    Text = "È il momento!"
  },
  AvgDialog_45418_Content_1 = {
    Text = "Coff, coff... Eravate in superiorità numerica. Che vergogna!"
  },
  AvgDialog_45418_Content_10 = {
    Text = "Non ce n'è bisogno.\nIl seme dell'Albero madre non è all'interno."
  },
  AvgDialog_45418_Content_11 = {
    Text = "Non avrei mai immaginato che i Resti dell'Albero Madre degli Aramiti fossero stati Dissolti a tal punto..."
  },
  AvgDialog_45418_Content_12 = {
    Text = "Herbert e Casiah svaniscono tra le dune lontane, concedendo finalmente a voi tre un momento per respirare."
  },
  AvgDialog_45418_Content_13 = {
    Text = "Possiamo dire ad Alva di recuperare le spoglie adesso."
  },
  AvgDialog_45418_Content_14 = {
    Text = "Nessuna fretta... è la nostra migliore occasione per esaminare le Spoglie, no?"
  },
  AvgDialog_45418_Content_15 = {
    Text = "Inoltre... date un'occhiata all'angolo dove si trovava Casiah."
  },
  AvgDialog_45418_Content_16 = {
    Text = "Dalla fenditura delle Spoglie, una melma nera trasuda lentamente, fluendo in scanalature deliberatamente scolpite nel pavimento."
  },
  AvgDialog_45418_Content_17 = {
    Text = "Aspetta... l'ho visto nella tenda della Regina..."
  },
  AvgDialog_45418_Content_18 = {
    Text = "Il che significa che non è opera di Casiah. È una struttura costruita dagli Aram.\nStanno estraendo D-melma dai resti per qualche scopo."
  },
  AvgDialog_45418_Content_19 = {
    Text = "Permettimi di soddisfare la tua curiosità."
  },
  AvgDialog_45418_Content_2 = {Text = "Ma..."},
  AvgDialog_45418_Content_20 = {
    Text = "Nessuno ha notato il ritorno di Juliette. Appare dietro il cancello di ferro, camminando verso di voi sui gradini di pietra."
  },
  AvgDialog_45418_Content_21 = {
    Text = "Dato che siamo tutti invischiati in misteri, andrò dritto al punto: Mythag sa dei tre Eoni?"
  },
  AvgDialog_45418_Content_22 = {
    Text = [[
Ramona e Ryker si voltano entrambi verso di te.
Esiti, valutando il comportamento di Juliette, poi annuisci.]]
  },
  AvgDialog_45418_Content_23 = {
    Text = "Dato che avete sentito parlare dell'Eone del Desiderio, sarà più facile da spiegare."
  },
  AvgDialog_45418_Content_24 = {
    Text = "I cosiddetti Resti dell'Albero Madre... sono in realtà il cadavere mummificato di <Yellow:Tifere Yesod>, l'Eone del Desiderio."
  },
  AvgDialog_45418_Content_25 = {
    Text = "Per gli Aramiti, la parte più cruciale è il fluido accumulato in questo feretro."
  },
  AvgDialog_45418_Content_26 = {
    Text = "Trasuda senza sosta dalla mummia."
  },
  AvgDialog_45418_Content_27 = {
    Text = "Sappiamo entrambi cos'è... è D-melma."
  },
  AvgDialog_45418_Content_28 = {
    Text = "Il potere divino di Tifere Yesod rallenta drasticamente l'Erosione della Dissoluzione, e da esso gli Aramiti traggono il loro potere di fertilità."
  },
  AvgDialog_45418_Content_29 = {
    Text = "Aspetta, vuoi dire..."
  },
  AvgDialog_45418_Content_3 = {
    Text = "Il livello di Casiah è pronto!"
  },
  AvgDialog_45418_Content_30 = {
    Text = "Ramona comincia a vomitare."
  },
  AvgDialog_45418_Content_31 = {
    Text = "Voi... Voi preparate <Yellow:bevande> dalla <Yellow:D-melma> dell'Albero Madre... Liquido da un cadavere..."
  },
  AvgDialog_45418_Content_32 = {
    Text = "Ecco perché sono caduti in preda alla Frenesia, ecco perché hanno ottenuto quella fertilità anormale..."
  },
  AvgDialog_45418_Content_33 = {
    Text = "Non dal loro lignaggio, ma da questa mummia."
  },
  AvgDialog_45418_Content_34 = {
    Text = "Con l'Albero Madre scomparso e il suo Potere in declino, le deformità continuano ad aumentare."
  },
  AvgDialog_45418_Content_35 = {
    Text = "L'avete notato anche voi, vero? La nebbia nera della Dissoluzione che emana da quegli Aramiti."
  },
  AvgDialog_45418_Content_36 = {
    Text = "Gli Aramiti differiscono dagli esseri umani ordinari; nella loro essenza, sono tutti progenie dell'Albero Madre."
  },
  AvgDialog_45418_Content_37 = {
    Text = "Se l'Albero Madre viene completamente Dissolto, non è solo la loro fertilità a svanire — ogni Aramita esistente perirà."
  },
  AvgDialog_45418_Content_38 = {
    Text = "Ecco perché gli Aramiti devono varcare il Muro della Tempesta e rianimare l'Albero Madre."
  },
  AvgDialog_45418_Content_39 = {
    Text = "Non so perché Mythag vi abbia mandato a Remouahe, ma sulla base della fiducia che abbiamo costruito, condividerò con voi il Segreto più profondo degli Aramiti."
  },
  AvgDialog_45418_Content_4 = {
    Text = "Un gigantesco artiglio trasparente squarcia l'aria, sfondando la fragile parete. Casiah balza in cima e cavalca via verso il deserto lontano."
  },
  AvgDialog_45418_Content_40 = {
    Text = "Se fermate il Rito, ogni Aramita che avete visto a Remouahe morirà — senza eccezione."
  },
  AvgDialog_45418_Content_41 = {
    Text = "Ricevuto il messaggio, William giunge di nuovo alla tenda nel cuore della notte."
  },
  AvgDialog_45418_Content_42 = {
    Text = "Ramona si è addormentata?"
  },
  AvgDialog_45418_Content_43 = {
    Text = "Sì, ha una febbre terribile."
  },
  AvgDialog_45418_Content_44 = {
    Text = "Riguardo all'Eone del Desiderio... Ditemi cosa pensate delle scoperte di Juliette."
  },
  AvgDialog_45418_Content_45 = {Text = "Non lo so."},
  AvgDialog_45418_Content_46 = {
    Text = "Avremmo dovuto capirlo quando abbiamo sentito parlare di quel perverso Festino del falò."
  },
  AvgDialog_45418_Content_47 = {
    Text = "Questo metodo di riproduzione non ha nulla a che vedere con quello dei comuni Kadathiani."
  },
  AvgDialog_45418_Content_48 = {
    Text = "Inoltre, Ramona ha la febbre da quando è arrivata a Remouahe."
  },
  AvgDialog_45418_Content_49 = {
    Text = "Si è ammalata a causa di questo?"
  },
  AvgDialog_45418_Content_5 = {
    Text = "Ci vediamo in giro!"
  },
  AvgDialog_45418_Content_50 = {
    Text = "Ho una teoria..."
  },
  AvgDialog_45418_Content_51 = {
    Text = "Avete incontrato Tawil e sapete di <Blue:Ramona: Timeworn>. A questo punto dovreste conoscere il suo legame con Tawil."
  },
  AvgDialog_45418_Content_52 = {
    Text = "I poteri dei tre Eoni si respingono a vicenda. L'acqua di Remouahe proviene dalla stirpe dell'Eone del Desiderio: è Veleno per Ramona."
  },
  AvgDialog_45418_Content_53 = {
    Text = "Più ci si avvicina alla sorgente del Fiume sacro, più forte diventa questa repulsione."
  },
  AvgDialog_45418_Content_54 = {
    Text = "Gli Aramiti tenteranno di varcare il Muro della Tempesta di nuovo domani."
  },
  AvgDialog_45418_Content_55 = {
    Text = "Ramona deve restare fuori dal Muro della Tempesta."
  },
  AvgDialog_45418_Content_56 = {
    Text = "Noi tre ci occuperemo del resto."
  },
  AvgDialog_45418_Content_57 = {
    Text = "Non se ne parla—faccio parte dei Mythag anch'io, non posso..."
  },
  AvgDialog_45418_Content_58 = {
    Text = "Ramona si alza a fatica dal giaciglio, oscillando instabile, quasi ricadendo a terra."
  },
  AvgDialog_45418_Content_59 = {
    Text = "Ramona, non sei in condizione di farcela."
  },
  AvgDialog_45418_Content_6 = {Text = "Ehi—"},
  AvgDialog_45418_Content_60 = {
    Text = "Le rimbocchi la coperta. La ragazza, assalita dal calore, ti fissa tremante ma non dice nulla."
  },
  AvgDialog_45418_Content_61 = {
    Text = "Non mi lascerete indietro da sola..."
  },
  AvgDialog_45418_Content_7 = {
    Text = "Lasciali andare. Potrebbe essere un diversivo — i Resti dell'Albero Madre sono ancora qui."
  },
  AvgDialog_45418_Content_8 = {
    Text = "Casiah agita la fiala che tiene in mano, ribollente di melma nera."
  },
  AvgDialog_45418_Content_9 = {
    Text = "Tutto qui? Potrei arraffare anche la bara."
  },
  AvgDialog_45419_Content_1 = {
    Text = "L'enorme creatura da laboratorio dell'Associazione degli Scultori si abbatte al suolo, l'aria densa di ruggine acre."
  },
  AvgDialog_45419_Content_10 = {
    Text = "Nelle terre di Aram, le priorità non spetta a voi stabilirle, estranei."
  },
  AvgDialog_45419_Content_11 = {
    Text = [[
La sua rabbia rimbomba vuota nei meandri della fabbrica.
La comandante di Aram ordina a decine di soldati di bloccarvi la via d'uscita.]]
  },
  AvgDialog_45419_Content_12 = {
    Text = "Il soldato che avevate nascosto fuori — ora libero, in qualche modo — la segue, indicando la vostra posizione."
  },
  AvgDialog_45419_Content_13 = {
    Text = "Ora basta. La tregua è finita, Estranei."
  },
  AvgDialog_45419_Content_2 = {
    Text = "...Non è qui."
  },
  AvgDialog_45419_Content_3 = {
    Text = "No, era qui."
  },
  AvgDialog_45419_Content_4 = {
    Text = [[
La punta del dito di Ryker sfiora il pavimento, poi si alza per pizzicare e soffiare.
La polvere si disperde dai suoi guanti neri, danzando nella luce della finestra.]]
  },
  AvgDialog_45419_Content_5 = {
    Text = "Riesco a distinguere delle impronte sbiadite."
  },
  AvgDialog_45419_Content_6 = {
    Text = "Le ombre della finestra rotta rigano la lastra di cemento incisa con il profilo di una bara.\nMa la bara non c'è."
  },
  AvgDialog_45419_Content_7 = {
    Text = "Avremmo dovuto saperlo. Lady Daffodil non venderebbe informazioni a un solo acquirente."
  },
  AvgDialog_45419_Content_8 = {
    Text = "Forse avrei dovuto chiedere un'esclusiva a pagamento?"
  },
  AvgDialog_45419_Content_9 = {
    Text = "Basta arguzie. I Resti dell'Albero Madre restano la nostra priorità."
  },
  AvgDialog_45420_Content_1 = {
    Text = "Lady Alva, vi prego, permettetemi di scambiare qualche parola con {Male=lui,Female=lei}."
  },
  AvgDialog_45420_Content_10 = {
    Text = "La sua Espressione si contorce in uno zelo innaturale; le parole sgorgano frenetiche, il corpo proteso in avanti, gli Occhi spettrali."
  },
  AvgDialog_45420_Content_11 = {
    Text = "Ci rivedremo, Occhio Senza Pupilla."
  },
  AvgDialog_45420_Content_12 = {Text = "..."},
  AvgDialog_45420_Content_13 = {
    Text = "No, non è finita. Perché lei ti ha implorato, con la massima sincerità, di chiamare il suo nome."
  },
  AvgDialog_45420_Content_14 = {
    Text = "Rievocando lo Sguardo di Thais, attivi la Chiave d'Argento."
  },
  AvgDialog_45420_Content_15 = {
    Text = "Fili d'Argento oscillano, tirano, cercano..."
  },
  AvgDialog_45420_Content_16 = {
    Text = "Al termine del filo — il nulla."
  },
  AvgDialog_45420_Content_17 = {
    Text = "La Dissoluzione l'ha divorata interamente. Nemmeno tu puoi trovarla, ormai."
  },
  AvgDialog_45420_Content_18 = {
    Text = "Speri ancora che faccia Ritorno? Gli Aramiti obbediscono solo a me, adesso."
  },
  AvgDialog_45420_Content_19 = {
    Text = "Thais... Thais!"
  },
  AvgDialog_45420_Content_2 = {
    Text = "Le parole di Juliette spezzano lo stallo."
  },
  AvgDialog_45420_Content_20 = {
    Text = "Se lei potesse apparire, se potesse rivelare il futuro di Aram ad Alva..."
  },
  AvgDialog_45420_Content_21 = {
    Text = "Basterebbe una sua sola parola, e non dovresti affrontare Alva Lama contro Lama."
  },
  AvgDialog_45420_Content_22 = {
    Text = "Thais... THAIS!"
  },
  AvgDialog_45420_Content_23 = {
    Text = "Le tue grida sono vane. Le tue Ultime volontà per lei sono state accuse."
  },
  AvgDialog_45420_Content_24 = {
    Text = "La sua esistenza è stata Dissolta. Senza un Nucleo d'Argento, non puoi raggiungerla in alcun modo."
  },
  AvgDialog_45420_Content_25 = {Text = "..."},
  AvgDialog_45420_Content_26 = {
    Text = "Hmm? Questo viaggio ti ha reso troppo arrogante per chiedere aiuto?"
  },
  AvgDialog_45420_Content_27 = {
    Text = "O sei solo una piagnucolona inutile senza di me?"
  },
  AvgDialog_45420_Content_28 = {
    Text = "In ogni caso, sei giunto fin qui da solo dopo aver perso tutti i compagni. Quella Tenacia merita lode."
  },
  AvgDialog_45420_Content_29 = {
    Text = "Dunque, presterò la mia Autorità a lei — e a te."
  },
  AvgDialog_45420_Content_3 = {
    Text = "Se insistete."
  },
  AvgDialog_45420_Content_30 = {
    Text = "La quiete del deserto si frantuma con una raffica improvvisa; l'orizzonte si oscura rapido, come se ogni luce soccombesse alla Furia incombente."
  },
  AvgDialog_45420_Content_31 = {
    Text = "Una tempesta di sabbia ruggisce come un behemoth infuriato, trascinando tonnellate di sabbia, oscurando sole e cielo."
  },
  AvgDialog_45420_Content_32 = {
    Text = "In questa furia scatenata, una sagoma colossale tremola, mutando forma tra la polvere."
  },
  AvgDialog_45420_Content_33 = {
    Text = "Il Muro della Tempesta..."
  },
  AvgDialog_45420_Content_34 = {
    Text = "Il Muro della Tempesta... L'ho evocato con la mia Autorità."
  },
  AvgDialog_45420_Content_35 = {
    Text = "Tu sei... Thais...?"
  },
  AvgDialog_45420_Content_36 = {
    Text = "Trabocca di Potere infinito; mentre la polvere danza selvaggia, l'Ombra balza, si deforma — come un antico Mostro del deserto a caccia nella bufera."
  },
  AvgDialog_45420_Content_37 = {
    Text = "La sua forma, immensa e terrificante: un capo massiccio e avvolto su sé stesso, artigli affilati come rasoi, zoccoli possenti — tutto intravisto nel turbinio di sabbia."
  },
  AvgDialog_45420_Content_38 = {
    Text = "Non hai del tutto torto a chiamarmi così."
  },
  AvgDialog_45420_Content_39 = {
    Text = "Ma non sono la Regina che vi aspettate."
  },
  AvgDialog_45420_Content_4 = {
    Text = "Guardie, non permettete che facciano del male all'inviato."
  },
  AvgDialog_45420_Content_40 = {
    Text = "Per brandire il mio potere, intona ad alta voce il mio nome sacro.\nIo sono il Corpo del Desiderio—"
  },
  AvgDialog_45420_Content_41 = {
    Text = "La vasta, bizzarra Ombra svanisce; la figura che cerchi emerge dalla tempesta urlante."
  },
  AvgDialog_45420_Content_42 = {
    Text = "La sabbia le turbina intorno senza pietà, eppure i suoi passi restano incrollabili."
  },
  AvgDialog_45420_Content_43 = {
    Text = "<Change>Tifere Yesod."
  },
  AvgDialog_45420_Content_44 = {
    Text = "La Regina! La Regina è tornata!"
  },
  AvgDialog_45420_Content_45 = {
    Text = "Gli Occhi della Regina vegliano sempre su di noi!"
  },
  AvgDialog_45420_Content_46 = {
    Text = "Ha sempre vegliato su Aram, passato e futuro scorrono nel suo Sangue."
  },
  AvgDialog_45420_Content_47 = {
    Text = "Lady Thais..."
  },
  AvgDialog_45420_Content_48 = {
    Text = "Aramiti, ascoltatemi! L'antica Profezia si è compiuta! L'Albero Madre fa Ritorno, incoronando il Defunto!"
  },
  AvgDialog_45420_Content_49 = {
    Text = "La Regina cammina di nuovo sulle sabbie, reclamando il suo Trono!"
  },
  AvgDialog_45420_Content_5 = {Text = "Sì!"},
  AvgDialog_45420_Content_50 = {
    Text = "L'unica vera Regina di Aram, Lady Thais —"
  },
  AvgDialog_45420_Content_51 = {
    Text = "avrà la vostra volontà e la vostra Lealtà!"
  },
  AvgDialog_45420_Content_6 = {
    Text = "Juliette si avvicina, sussurrando a un palmo di distanza."
  },
  AvgDialog_45420_Content_7 = {
    Text = "Ritornare al Fiume Sacro è il destino di Aram. Io sto semplicemente... accelerandolo un poco."
  },
  AvgDialog_45420_Content_8 = {
    Text = "Quando il Suo Sguardo avvolgerà tutta Kadath, si fonderanno con il fiume in un nuovo mondo."
  },
  AvgDialog_45420_Content_9 = {
    Text = "Non è forse anche la vostra volontà?"
  },
  AvgDialog_45421_Content_1 = {
    Text = "Chi va là?!"
  },
  AvgDialog_45421_Content_2 = {
    Text = "Imboscata davanti e inseguitori alle spalle... delizioso."
  },
  AvgDialog_45421_Content_3 = {
    Text = "Non possiamo farci avvistare dai soldati di Aram."
  },
  AvgDialog_45421_Content_4 = {
    Text = "Quindi ci addentriamo ancora di più?"
  },
  AvgDialog_45422_Content_1 = {
    Text = "Complicato. Non conosciamo la posizione esatta dei resti.\nLa fabbrica è un labirinto. Ci sono troppe stanze; non possiamo perquisirle tutte."
  },
  AvgDialog_45422_Content_10 = {
    Text = "Tu nasconditi da qualche parte e coprimi! Resta invisibile. Li benderò io!"
  },
  AvgDialog_45422_Content_2 = {
    Text = "Ho un piano."
  },
  AvgDialog_45422_Content_3 = {
    Text = "Catturiamo una Guardia di Aram, la leghiamo e la facciamo parlare."
  },
  AvgDialog_45422_Content_4 = {
    Text = "E poi? Lo mettiamo a tacere seppellendolo nella sabbia, o lo lasciamo andare e finiamo nella lista dei ricercati?"
  },
  AvgDialog_45422_Content_5 = {
    Text = "Ops... non ci avevo pensato. Errore da principiante."
  },
  AvgDialog_45422_Content_6 = {
    Text = [[
Lo dice con disinvoltura, del tutto indifferente.
Quel tono furbo lascia intendere un piano di riserva.]]
  },
  AvgDialog_45422_Content_7 = {
    Text = "C'è un modo per estorcere indizi senza far saltare la nostra copertura?"
  },
  AvgDialog_45422_Content_8 = {
    Text = "Facile come bere un bicchier d'acqua."
  },
  AvgDialog_45422_Content_9 = {
    Text = "Ryker stacca il cerotto d'incenso dal guanto, i suoi occhi dal bagliore verde che lampeggiano nell'oscurità."
  },
  AvgDialog_45423_Content_1 = {
    Text = "Non, non può essere! Il Muro della Tempesta non ha fine!"
  },
  AvgDialog_45423_Content_2 = {
    Text = "Non riusciamo a sfondarlo—la Regina ci ha abbandonati!"
  },
  AvgDialog_45423_Content_3 = {
    Text = "Ci ha abbandonati da tempo!"
  },
  AvgDialog_45423_Content_4 = {
    Text = "Urla e lamenti riempiono l'aria."
  },
  AvgDialog_45424_Content_1 = {
    Text = "La Regina ci proteggerà!"
  },
  AvgDialog_45424_Content_2 = {
    Text = "La Regina proteggerà Aram!"
  },
  AvgDialog_45424_Content_3 = {
    Text = "<Small:Thais non è nemmeno qui...>"
  },
  AvgDialog_45424_Content_4 = {
    Text = "Il branco della Nubia continua a crescere!"
  },
  AvgDialog_45424_Content_5 = {
    Text = "Basta così—dobbiamo andare avanti con questi folli!"
  },
  AvgDialog_45425_Content_1 = {Text = "Scommessa"},
  AvgDialog_45425_Content_10 = {
    Text = "Spalanchi gli occhi. A parte la luce dell'alba fuori, tutto è rimasto com'era quando ti sei coricato."
  },
  AvgDialog_45425_Content_11 = {
    Text = "Ho capito. È il movente."
  },
  AvgDialog_45425_Content_12 = {
    Text = "Se tutto questo fosse opera della Chiesa dei Portatori di Luce, non ci sarebbe motivo di lasciare quella Lanterna all'interno della Nubia."
  },
  AvgDialog_45425_Content_13 = {
    Text = "Mettendo insieme ciò che abbiamo visto in questo viaggio, il vero colpevole dev'essere—"
  },
  AvgDialog_45425_Content_14 = {
    Text = "Ryker squarcia il tessuto della tenda con i suoi artigli, e una subdola maga Emerge insieme alle dune sconfinate."
  },
  AvgDialog_45425_Content_15 = {
    Text = "Voi due, dell'Associazione degli Scultori."
  },
  AvgDialog_45425_Content_16 = {
    Text = "Ehilà, scoperta? Speravo di origliare ancora un po'."
  },
  AvgDialog_45425_Content_17 = {
    Text = "Il suo tono è vivace, senza la minima traccia di nervosismo per essere stata colta in flagrante."
  },
  AvgDialog_45425_Content_18 = {
    Text = "Casiah, tu—!"
  },
  AvgDialog_45425_Content_19 = {
    Text = "Ehi, i debiti al debitore! Non sono stata io a uccidere il vostro Senior William, quindi niente vendetta su di me!"
  },
  AvgDialog_45425_Content_2 = {
    Text = "Ti trascini fino alla tenda, dove Ryker siede in silenzio nell'angolo, il mento In Mano, perso nei suoi pensieri."
  },
  AvgDialog_45425_Content_20 = {
    Text = "Il mio lavoro è semplice: acciuffare questa qui..."
  },
  AvgDialog_45425_Content_21 = {Text = "Indica te."},
  AvgDialog_45425_Content_22 = {
    Text = "E portare {Male=lui,Female=lei} da colui che servo."
  },
  AvgDialog_45425_Content_3 = {
    Text = "Domani sarà sicuramente un combattimento duro. Perché non stai riposando?"
  },
  AvgDialog_45425_Content_4 = {
    Text = "Vai pure a dormire.\nIl mio istinto mi dice che... c'è ancora un ultimo enigma irrisolto in questa \"scena del crimine\"."
  },
  AvgDialog_45425_Content_5 = {
    Text = "Ti lavi e crolli per la stanchezza."
  },
  AvgDialog_45425_Content_6 = {
    Text = "Nel Sogno caotico, innumerevoli volti — familiari eppure estranei — balenano nella tua Memoria, sfocati, rochi, grotteschi, ognuno che chiama il tuo nome a turno."
  },
  AvgDialog_45425_Content_7 = {
    Text = "Voglio vivere..."
  },
  AvgDialog_45425_Content_8 = {
    Text = "<RedBig:Voglio vivere...>"
  },
  AvgDialog_45425_Content_9 = {Text = "Basta!"},
  AvgDialog_45426_Content_1 = {
    Text = "Bacio d'Addio"
  },
  AvgDialog_45426_Content_10 = {
    Text = "Trai un respiro profondo, pronta a tornare alla tenda, quando Thais ti fa cenno da dietro di essa."
  },
  AvgDialog_45426_Content_100 = {
    Text = "Ma gli Aramiti dipendono troppo dal Potere dell'Albero Madre."
  },
  AvgDialog_45426_Content_101 = {
    Text = "Quella dipendenza è come una fragile torre di sabbia: apparentemente solida, ma basta un'Ondata di marea a spazzarla via."
  },
  AvgDialog_45426_Content_102 = {
    Text = "Ma non posso permettere loro di abbandonare con leggerezza nemmeno il più esile, il più Faint filo di speranza."
  },
  AvgDialog_45426_Content_103 = {
    Text = "Non capisco..."
  },
  AvgDialog_45426_Content_104 = {
    Text = "Per rendere gli addii meno dolorosi, i ricongiungimenti sono preziosi... non è necessario che tu capisca. Per ora."
  },
  AvgDialog_45426_Content_105 = {
    Text = "Ma un giorno, tutti affronteremo lo stesso destino."
  },
  AvgDialog_45426_Content_106 = {
    Text = "Resti senza parole."
  },
  AvgDialog_45426_Content_107 = {
    Text = "Quando quel giorno inevitabile verrà... ricorda di chiamare il mio nome."
  },
  AvgDialog_45426_Content_108 = {
    Text = "Ti posa un bacio lieve sulla fronte."
  },
  AvgDialog_45426_Content_109 = {
    Text = "La tua mente vacilla, e lei ondeggia all'indietro. Tendi la mano, ma è fuori dalla tua Portata."
  },
  AvgDialog_45426_Content_11 = {
    Text = "Domani è il Rituale di Nascita dell'Albero Madre.\nCosa vorreste da me, adesso, Vostra Maestà?"
  },
  AvgDialog_45426_Content_110 = {
    Text = "Osservi la sua figura che si allontana, si fa sempre più piccola, fino a dissolversi in un granello, svanendo nella luce lunare immacolata."
  },
  AvgDialog_45426_Content_12 = {
    Text = "Le parole escono più taglienti di quanto volessi."
  },
  AvgDialog_45426_Content_13 = {
    Text = "Io... l'ho visto.\nQuello che è successo al vostro compagno... mi dispiace tanto."
  },
  AvgDialog_45426_Content_14 = {
    Text = "Un inevitabile Silenzio aleggia tra voi."
  },
  AvgDialog_45426_Content_15 = {
    Text = "Questo non ha nulla a che fare con Aram."
  },
  AvgDialog_45426_Content_16 = {
    Text = "Non è colpa di Thais, ti ricordi — ma le tue parole pungono come un riccio guardingo tra le dune."
  },
  AvgDialog_45426_Content_17 = {
    Text = "Il Rituale di Nascita... anche voi avrete dei preparativi, giusto?"
  },
  AvgDialog_45426_Content_18 = {
    Text = "Cerchi di addolcire il tono, ma suona comunque come un freddo congedo."
  },
  AvgDialog_45426_Content_19 = {
    Text = "Dove pensate che andranno gli Aramiti una volta che l'Albero Madre rinascerà?"
  },
  AvgDialog_45426_Content_2 = {
    Text = "In questo viaggio, hai assistito a molte dipartite.\nMa mai la morte è sembrata così soffocantemente sommessa."
  },
  AvgDialog_45426_Content_20 = {
    Text = "Resti in silenzio."
  },
  AvgDialog_45426_Content_21 = {
    Text = "So perché Mythag è venuto a Remouahe, e so perché non hai ancora agito."
  },
  AvgDialog_45426_Content_22 = {
    Text = "Ti sono grata — hai dato ad Aram una possibilità."
  },
  AvgDialog_45426_Content_23 = {
    Text = "Ma quella possibilità non esiste più."
  },
  AvgDialog_45426_Content_24 = {
    Text = "Thais, lo sai che l'Albero Madre è contaminato dalla Dissoluzione, vero?"
  },
  AvgDialog_45426_Content_25 = {Text = "..."},
  AvgDialog_45426_Content_26 = {
    Text = "Lo so, io... l'ho sempre saputo."
  },
  AvgDialog_45426_Content_27 = {
    Text = "Allora dovresti capire che Mythag non resterà a guardare mentre la Dissoluzione si propaga."
  },
  AvgDialog_45426_Content_28 = {
    Text = "Fermerò la Rinascita dell'Albero Madre.\nThais, ora siamo nemici."
  },
  AvgDialog_45426_Content_29 = {
    Text = "Il mare di sabbia un tempo limpido si fa denso e vischioso; la polvere inalata graffia la gola, lasciando un dolore sordo."
  },
  AvgDialog_45426_Content_3 = {
    Text = [[
Fra tutte le persone, doveva essere proprio William.
L'investigatore leggendario di Mythag, il tuo mentore su questo cammino.]]
  },
  AvgDialog_45426_Content_30 = {
    Text = "Con tua sorpresa, Thais non si ritrae — si avvicina, avvolgendoti nel suo abbraccio."
  },
  AvgDialog_45426_Content_31 = {
    Text = "Dolce creatura, capisco."
  },
  AvgDialog_45426_Content_32 = {
    Text = "Non ho alcuna intenzione di nuocere a te o ai tuoi compagni, né agirei mai contro gli interessi di Aram."
  },
  AvgDialog_45426_Content_33 = {
    Text = "Ma gli Aramiti non hanno altra via. Molto tempo fa, il potere della Regina si affievolì — riusciva a malapena a proteggere l'Albero Madre."
  },
  AvgDialog_45426_Content_34 = {
    Text = "Fu necessario attingere alle linee telluriche di Remouahe, evocando il Muro della Tempesta per celarne la posizione."
  },
  AvgDialog_45426_Content_35 = {
    Text = "Vuoi dire... che il Muro della Tempesta è stato evocato dal potere della Regina?"
  },
  AvgDialog_45426_Content_36 = {
    Text = "Sì. Il Muro della Tempesta... respinge i falsi emissari."
  },
  AvgDialog_45426_Content_37 = {
    Text = "Ma ogni Rito costa così tante vite aramite!"
  },
  AvgDialog_45426_Content_38 = {
    Text = "Finché la nostra fertilità sopporta, gli Aramiti non si estingueranno."
  },
  AvgDialog_45426_Content_39 = {
    Text = "E così permetti loro di aggrapparsi a questo rito maledetto, lasciando che cadano vittime del Muro della Tempesta, ancora e ancora?"
  },
  AvgDialog_45426_Content_4 = {
    Text = "Chi potrebbe mai uccidere una leggenda come lui, in silenzio, a pochi passi di distanza?"
  },
  AvgDialog_45426_Content_40 = {
    Text = "Questo è il Fato di ogni Aramita. Siamo nati qui e qui siamo cresciuti."
  },
  AvgDialog_45426_Content_41 = {
    Text = "La vostra fede distorta ha ucciso innumerevoli persone!"
  },
  AvgDialog_45426_Content_42 = {
    Text = "Non solo la vostra gente... e ora anche William..."
  },
  AvgDialog_45426_Content_43 = {
    Text = "La tua voce si incrina appena; a stento la riconosci come tua."
  },
  AvgDialog_45426_Content_44 = {
    Text = "Dimmi, Thais — tu non credi davvero in tutto questo, vero?"
  },
  AvgDialog_45426_Content_45 = {
    Text = "Thais non offre risposta."
  },
  AvgDialog_45426_Content_46 = {
    Text = "Si limita a stringere la presa."
  },
  AvgDialog_45426_Content_47 = {
    Text = "So che sei esausta, furiosa..."
  },
  AvgDialog_45426_Content_48 = {
    Text = "So che provi rancore verso di me. Non capisci il perché.\nMa ho le mie ragioni."
  },
  AvgDialog_45426_Content_49 = {
    Text = "Lascia che ti racconti una Storia — una molto lunga."
  },
  AvgDialog_45426_Content_5 = {
    Text = "Barcollando debolmente all'indietro, crolli contro una figura slanciata."
  },
  AvgDialog_45426_Content_50 = {
    Text = "Molto, molto tempo fa — millenni prima del Diluvio — una civiltà venerava una divinità chiamata l'Albero Madre."
  },
  AvgDialog_45426_Content_51 = {
    Text = "Ma la volontà dell'Albero era troppo sfuggente per stabilizzare il loro dominio. Per rimediare, l'impero ordì un piano terribile:"
  },
  AvgDialog_45426_Content_52 = {
    Text = "Selezionarono molte bambine, costringendole a bere la linfa cremisi dell'Albero Madre e a bagnarsi nei suoi succhi, finché una bambina non si fuse con successo con l'entità."
  },
  AvgDialog_45426_Content_53 = {
    Text = "Da quel momento, si disse che questa \"bambina fantoccio\" incarnasse la volontà divina dell'Albero."
  },
  AvgDialog_45426_Content_54 = {
    Text = "Ma nessuno l'ascoltò mai né obbedì alle sue parole. La bambina non aveva volontà propria; era soltanto un portavoce, che ripeteva i comandi recitati dal Re di Ninive."
  },
  AvgDialog_45426_Content_55 = {
    Text = "Aveva quindici anni quando per la prima volta alzò la voce in segno di ribellione."
  },
  AvgDialog_45426_Content_56 = {
    Text = "Perché? Perché ucciderlo? È il padre di Amayet!"
  },
  AvgDialog_45426_Content_57 = {
    Text = "Ha violato il tabù, Thais. È fuggito dal campo di battaglia."
  },
  AvgDialog_45426_Content_58 = {
    Text = "La battaglia era perduta! Era l'unico sopravvissuto — non poteva combattere da solo contro tutti quei nemici!"
  },
  AvgDialog_45426_Content_59 = {
    Text = "Sei troppo giovane per capire la guerra, Thais."
  },
  AvgDialog_45426_Content_6 = {
    Text = "Capisco come ti senti, ma non è il momento di crollare."
  },
  AvgDialog_45426_Content_60 = {
    Text = "Avrebbe dovuto caricare in avanti e morire con onore."
  },
  AvgDialog_45426_Content_61 = {
    Text = "Non è meglio un sopravvissuto? Con lui in vita... Amayet potrebbe diventare un guerriero, anche suo fratello, e i futuri figli di Amayet..."
  },
  AvgDialog_45426_Content_62 = {
    Text = "La mia decisione è definitiva."
  },
  AvgDialog_45426_Content_63 = {
    Text = "Proclama il volere dell'Albero Madre: il peccatore sarà divorato vivo dagli insetti."
  },
  AvgDialog_45426_Content_64 = {
    Text = "NON HO DETTO QUESTO!"
  },
  AvgDialog_45426_Content_65 = {
    Text = "Proclama il volere dell'Albero Madre: il peccatore sarà divorato vivo dagli insetti."
  },
  AvgDialog_45426_Content_66 = {
    Text = "NON HO DETTO QUESTO!"
  },
  AvgDialog_45426_Content_67 = {
    Text = "Proclamate la volontà dell'Albero Madre..."
  },
  AvgDialog_45426_Content_68 = {
    Text = "No, non...!"
  },
  AvgDialog_45426_Content_69 = {
    Text = "Il peccatore sarà divorato vivo dagli insetti."
  },
  AvgDialog_45426_Content_7 = {
    Text = "Ci ha... lasciato le informazioni Chiave."
  },
  AvgDialog_45426_Content_70 = {
    Text = "Le grida disperate e laceranti della bambina rimasero inascoltate."
  },
  AvgDialog_45426_Content_71 = {
    Text = "C-chi sei tu?"
  },
  AvgDialog_45426_Content_72 = {
    Text = "Shh, piccola — tieni la voce bassa. E seguimi, presto."
  },
  AvgDialog_45426_Content_73 = {
    Text = "Non sei la prima marionetta. Ogni volta che una bambina tenta di opporsi a loro, viene sacrificata al Fiume Sacro."
  },
  AvgDialog_45426_Content_74 = {
    Text = "Sono nata bagnandomi nella linfa dell'Albero Madre — sono immortale!"
  },
  AvgDialog_45426_Content_75 = {
    Text = "Sciocca bambina, è una menzogna. Tutti annegano nell'acqua."
  },
  AvgDialog_45426_Content_76 = {
    Text = "Non lo farò."
  },
  AvgDialog_45426_Content_77 = {
    Text = "E tu chi saresti? Non ti ho mai visto prima."
  },
  AvgDialog_45426_Content_78 = {
    Text = "Pulisco il tuo giardino, andandomene prima dell'alba — così non mi hai mai vista."
  },
  AvgDialog_45426_Content_79 = {
    Text = "Ma conosci mio nipote. Si chiamava... Amayet."
  },
  AvgDialog_45426_Content_8 = {
    Text = "La Chiesa della luce del tempio è dietro ai Nubia.\nDaffodil non bluffava: fermare il rituale è ormai indispensabile."
  },
  AvgDialog_45426_Content_80 = {
    Text = "La bambina è fuggita?"
  },
  AvgDialog_45426_Content_81 = {Text = "No."},
  AvgDialog_45426_Content_82 = {
    Text = "In quel momento, la bambina comprese molte cose."
  },
  AvgDialog_45426_Content_83 = {
    Text = "Che i giardini insozzati non si puliscono da soli."
  },
  AvgDialog_45426_Content_84 = {
    Text = "Che certe cose esistono senza essere viste."
  },
  AvgDialog_45426_Content_85 = {
    Text = "Essere costretti al silenzio... è una tale agonia."
  },
  AvgDialog_45426_Content_86 = {
    Text = "...Il giorno del sacrificio, si gettò nel Fiume Sacro di sua volontà."
  },
  AvgDialog_45426_Content_87 = {
    Text = "In quell'istante, la volontà della bambina risuonò con quella dell'Albero."
  },
  AvgDialog_45426_Content_88 = {
    Text = "Allora, l'Albero le chiese:"
  },
  AvgDialog_45426_Content_89 = {
    Text = "Diventerai il mio vascello, dando alla luce la mia carne e la mia anima?"
  },
  AvgDialog_45426_Content_9 = {
    Text = "Le stelle brillano nel vasto cielo notturno; la brezza del deserto placa infine i tuoi respiri affannosi."
  },
  AvgDialog_45426_Content_90 = {
    Text = "Attraverso la prodigiosa armonia dell'anima, la bambina udì la voce dell'albero.\nQuella notte, apprese la conoscenza legata alla <Red:Fine Nera>."
  },
  AvgDialog_45426_Content_91 = {
    Text = "Fine Nera... intendi la Dissoluzione?"
  },
  AvgDialog_45426_Content_92 = {
    Text = "La bambina tornò al fianco dell'Albero, non più vincolata dai comandi del re. Tutto il popolo obbediva solo a lei, soggiogato dalla stirpe condivisa."
  },
  AvgDialog_45426_Content_93 = {
    Text = "Divenne un tutt'uno con l'Albero. Più che la propria sopravvivenza, il suo fardello era garantire che l'intera stirpe sfuggisse all'imminente rovina."
  },
  AvgDialog_45426_Content_94 = {
    Text = "Quando l'Impero di Ninive cadde, guidò un gruppo nel cuore profondo del deserto, attraverso tempeste mai calpestate, per preservare gli ultimi del suo popolo."
  },
  AvgDialog_45426_Content_95 = {
    Text = "E quelle persone divennero... i nomadi Aramiti?"
  },
  AvgDialog_45426_Content_96 = {
    Text = "Molto tempo dopo, la bambina svanì di nuovo."
  },
  AvgDialog_45426_Content_97 = {
    Text = "Nessuno udì la sua voce; nessuno cantò il suo nome."
  },
  AvgDialog_45426_Content_98 = {
    Text = "Ma tutti seguirono la sua volontà, riproducendosi disperatamente per sfuggire alla fine..."
  },
  AvgDialog_45426_Content_99 = {
    Text = "Per preservare il seme della loro stirpe quando l'inevitabile catastrofe si abbatterà su di loro."
  },
  AvgDialog_45427_Content_1 = {Text = "Danza"},
  AvgDialog_45427_Content_10 = {
    Text = "Non temere, Czort. I giovani si apriranno il proprio sentiero."
  },
  AvgDialog_45427_Content_100 = {
    Text = "Segui il suo sguardo: Ramona accorre verso di te, con Ryker alle calcagna — rapido eppure composto, l'eleganza intatta."
  },
  AvgDialog_45427_Content_101 = {
    Text = "Ricorda: stanotte è il nostro segreto."
  },
  AvgDialog_45427_Content_102 = {
    Text = "Ti volti — Thais è svanita, e solo il vento geme sulle dune."
  },
  AvgDialog_45427_Content_103 = {
    Text = "Davanti a te, le sabbie recano una macchia nera di D-melma, che si fonde con la Terra."
  },
  AvgDialog_45427_Content_11 = {Text = "..."},
  AvgDialog_45427_Content_12 = {
    Text = "Emergi dalla foschia, l'immensa volta stellata che arde limpida e sconfinata sopra di te."
  },
  AvgDialog_45427_Content_13 = {
    Text = "Come ho fatto a... addormentarmi?"
  },
  AvgDialog_45427_Content_14 = {
    Text = "Le lunghe marce nel deserto logorano l'anima. Non è nulla di insolito."
  },
  AvgDialog_45427_Content_15 = {
    Text = "Ho altre domande..."
  },
  AvgDialog_45427_Content_16 = {
    Text = "Il sogno senza fine ti strappa dalla fatica del cammino; domande si riversano a cascata nella tua mente."
  },
  AvgDialog_45427_Content_17 = {
    Text = "Perché l'acqua di Ramona si è trasformata in D-melma?"
  },
  AvgDialog_45427_Content_18 = {
    Text = "Chi sta scatenando questi Nubia?"
  },
  AvgDialog_45427_Content_19 = {
    Text = "Cosa si cela oltre il Muro della Tempesta?"
  },
  AvgDialog_45427_Content_2 = {
    Text = "▼▼ dimora nel caos; nessuno prevede la fine.\nCiò che deve avvenire giace nelle mie parole, ma orecchie e occhi tradiscono la moltitudine,\nsolo i silenziosi invadono la terra."
  },
  AvgDialog_45427_Content_20 = {
    Text = "Cosa muove l'enigmatica inviata Juliette?"
  },
  AvgDialog_45427_Content_21 = {
    Text = "Cosa si nasconde dietro il rito aramita?"
  },
  AvgDialog_45427_Content_22 = {
    Text = "E Thais — questa Thais davanti a te — ci si può davvero fidare di lei?"
  },
  AvgDialog_45427_Content_23 = {
    Text = "Da quando sei giunto a Remouahe, le anomalie si susseguono senza sosta, enigmi che ti inseguono fino a toglierti il respiro."
  },
  AvgDialog_45427_Content_24 = {
    Text = "Devi restare calma. Devi ragionare."
  },
  AvgDialog_45427_Content_25 = {
    Text = "Inutile rimuginare — sei già esausto. È tempo di riposare."
  },
  AvgDialog_45427_Content_26 = {
    Text = "Ti volti e vedi la luna piena bagnare la pelle immacolata di Thais di una luce traslucida."
  },
  AvgDialog_45427_Content_27 = {
    Text = "Oltre il Muro della Tempesta... tutte le tue domande troveranno risposta da sé."
  },
  AvgDialog_45427_Content_28 = {
    Text = "Oltre il Muro della Tempesta."
  },
  AvgDialog_45427_Content_29 = {
    Text = "Juliette lo ha detto chiaramente — devi davvero seguire il capriccio di un'ombra fin nel suo cuore?"
  },
  AvgDialog_45427_Content_3 = {
    Text = "I dati di monitoraggio di Tawil si stabilizzano finalmente."
  },
  AvgDialog_45427_Content_30 = {
    Text = "O forse una forza cosmica sospinge tutti verso il Centro della Tempesta, pellegrini in balìa del suo richiamo?"
  },
  AvgDialog_45427_Content_31 = {
    Text = "I pensieri turbinano incontrollati, seminando dubbio e terrore nelle profondità della tua mente."
  },
  AvgDialog_45427_Content_32 = {
    Text = "Non riesci a dormire?"
  },
  AvgDialog_45427_Content_33 = {
    Text = "Chiudi gli occhi."
  },
  AvgDialog_45427_Content_34 = {
    Text = "Il respiro di Thais sfiora il tuo, a pochi centimetri di distanza."
  },
  AvgDialog_45427_Content_35 = {
    Text = "Chiudi gli occhi."
  },
  AvgDialog_45427_Content_36 = {
    Text = "Rifiuti di chiudere gli occhi."
  },
  AvgDialog_45427_Content_37 = {
    Text = "I tuoi occhi sono così luminosi... non offuscati dal peso del cammino."
  },
  AvgDialog_45427_Content_38 = {
    Text = "Thais ti posa la punta di un dito sulle labbra."
  },
  AvgDialog_45427_Content_39 = {
    Text = "Il suo volto si libra vicino, il chiaro di luna che le dora la pelle in un tenue alone."
  },
  AvgDialog_45427_Content_4 = {
    Text = "Hai fatto bene."
  },
  AvgDialog_45427_Content_40 = {
    Text = "Senti il suo avvicinarsi: un'esalazione dolce, calda."
  },
  AvgDialog_45427_Content_41 = {
    Text = "Un profumo che risveglia echi lontani."
  },
  AvgDialog_45427_Content_42 = {
    Text = "Quanto tempo è passato da quando ci siamo avvicinati così?"
  },
  AvgDialog_45427_Content_43 = {
    Text = "Un brivido fresco ti sfiora le labbra."
  },
  AvgDialog_45427_Content_44 = {
    Text = [[
Apri gli occhi: il dito di Thais si posa sulle tue labbra.
Il suo volto aleggia vicino, la luce lunare le dora la pelle in un tenue alone.]]
  },
  AvgDialog_45427_Content_45 = {
    Text = "Lo sapevi? Nei tuoi occhi vedo calamità, braci dei giorni passati, il respiro del cosmo."
  },
  AvgDialog_45427_Content_46 = {
    Text = [[
Il viaggio ti ha consumato, vero?
Eppure il tuo sguardo resta saldo, incontaminato.]]
  },
  AvgDialog_45427_Content_47 = {
    Text = "Le Stelle distorte non hanno potuto piegarti; le sabbie del deserto forse nemmeno."
  },
  AvgDialog_45427_Content_48 = {
    Text = "Non capisco."
  },
  AvgDialog_45427_Content_49 = {
    Text = "Non devi — non ancora."
  },
  AvgDialog_45427_Content_5 = {
    Text = "Non possiamo ancora abbassare la guardia.\nIn tre secoli, la Pozza Nera non si è mai agitata con tanta insistenza."
  },
  AvgDialog_45427_Content_50 = {
    Text = "Thais si alza e passeggia lungo la duna."
  },
  AvgDialog_45427_Content_51 = {
    Text = "Sotto simili stelle, restare seduti è uno spreco della notte."
  },
  AvgDialog_45427_Content_52 = {
    Text = "Il vento solleva il suo velo diafano; lei ondeggia sulla sabbia cedevole."
  },
  AvgDialog_45427_Content_53 = {
    Text = "Lascia che ti presenti la danza di Aram."
  },
  AvgDialog_45427_Content_54 = {
    Text = "Tintinnano campanelli; alza un braccio, oscillando nell'alba del movimento."
  },
  AvgDialog_45427_Content_55 = {
    Text = "Si piega, si dischiude — selvaggia, poi trattenuta."
  },
  AvgDialog_45427_Content_56 = {
    Text = "Ho atteso a lungo colui che verrà."
  },
  AvgDialog_45427_Content_57 = {
    Text = "Il suo corpo si piega senz'ossa, i suoi passi grazia serpentina."
  },
  AvgDialog_45427_Content_58 = {
    Text = "Un guardiano che guidi Aram verso il futuro."
  },
  AvgDialog_45427_Content_59 = {
    Text = "Volteggia e ondeggia. Persino la scia sfumata dei suoi movimenti sussurra una grazia Innata, una flessuosità soprannaturale."
  },
  AvgDialog_45427_Content_6 = {
    Text = "Non c'è bisogno di preoccuparsi troppo; è inevitabile.\nChe \"Loro\" scelgano di nascondersi nel passato o nel futuro... non può durare per sempre."
  },
  AvgDialog_45427_Content_60 = {
    Text = "Non è forse Alva?"
  },
  AvgDialog_45427_Content_61 = {
    Text = "Thais lancia un'occhiata obliqua, ciglia basse, la punta delle dita sfiora come un bocciolo le labbra sospiranti."
  },
  AvgDialog_45427_Content_62 = {
    Text = "Alva è in gamba, ma non è pronta a tracciare nuovi sentieri."
  },
  AvgDialog_45427_Content_63 = {
    Text = "E Juliette? Non è lei l'Inviata Straniera?"
  },
  AvgDialog_45427_Content_64 = {
    Text = "Hai detto che Juliette vuole permettere agli Aramiti di lasciare il deserto, giusto?"
  },
  AvgDialog_45427_Content_65 = {
    Text = "Thais distende le braccia, il suo sguardo scivola verso le dita lambite dalla luna, come se liberasse uccelli invisibili."
  },
  AvgDialog_45427_Content_66 = {
    Text = "Chi poteva andarsene l'ha già fatto. Aram non vincola nessuno. È il richiamo della terra e il ritmo del deserto; chi è rimasto può sopravvivere solo qui."
  },
  AvgDialog_45427_Content_67 = {
    Text = "E poi, non è quella la risposta che bramo."
  },
  AvgDialog_45427_Content_68 = {
    Text = "La risposta che brami... qual è?"
  },
  AvgDialog_45427_Content_69 = {
    Text = "Scritta nei canti molto tempo fa."
  },
  AvgDialog_45427_Content_7 = {
    Text = "Non sono \"Loro\" a preoccuparmi. È {Male=il ragazzo,Female=la ragazza}."
  },
  AvgDialog_45427_Content_70 = {
    Text = [[
L'Albero Madre risorge: le sue radici bevono a fondo il fluire del Fiume sacro.
Incorona di luce i caduti e richiama il loro sangue a quello di Aram.]]
  },
  AvgDialog_45427_Content_71 = {
    Text = "Rivitalizzare il Fiume sacro ha senso — chi sono i defunti? Come riportiamo le stirpi ad Aram?"
  },
  AvgDialog_45427_Content_72 = {Text = "Shh—"},
  AvgDialog_45427_Content_73 = {
    Text = "I dettagli si aggrovigliano troppo in profondità; la profezia di @1 non offre una mappa completa."
  },
  AvgDialog_45427_Content_74 = {
    Text = "Tutto ciò che devi fare è fidarti completamente di me.\nTi fiderai della Regina di Aram."
  },
  AvgDialog_45427_Content_75 = {
    Text = "Fiori del deserto si schiudono nell'oscurità lunare; lei si solleva, volteggia, avanza — incidendo ritmi intricati e antichi nella sabbia."
  },
  AvgDialog_45427_Content_76 = {
    Text = "Credi in me, e sarò tua soltanto — la tua arma segreta, assoluta e unica."
  },
  AvgDialog_45427_Content_77 = {
    Text = "Il chiaro di luna ne sfuma i contorni in enigma, i suoi occhi avvolti in un desiderio muto."
  },
  AvgDialog_45427_Content_78 = {
    Text = "Se questo sogno deve finire —\nle stelle lontane ne sono testimoni."
  },
  AvgDialog_45427_Content_79 = {
    Text = "Aspetta, Thais — i tuoi piedi —"
  },
  AvgDialog_45427_Content_8 = {
    Text = "Allora sarebbe al di là del nostro intervento."
  },
  AvgDialog_45427_Content_80 = {
    Text = "Gridi in preda al panico."
  },
  AvgDialog_45427_Content_81 = {
    Text = "Cammina su increspature — no, nere increspature si aprono a ventaglio dalle sue dita dei piedi."
  },
  AvgDialog_45427_Content_82 = {
    Text = "L'orlo del velo ondeggia come ninfee, disperdendo perle d'ossidiana."
  },
  AvgDialog_45427_Content_83 = {
    Text = "Quella è... D-melma...?"
  },
  AvgDialog_45427_Content_84 = {
    Text = "Danza nella sognante pozza di Dissoluzione, posando i piedi ancora e ancora sulla superficie d'ebano."
  },
  AvgDialog_45427_Content_85 = {Text = "..."},
  AvgDialog_45427_Content_86 = {Text = "..."},
  AvgDialog_45427_Content_87 = {
    Text = "Sorda alle tue suppliche, oscilla al ritmo di una cadenza inudibile."
  },
  AvgDialog_45427_Content_88 = {
    Text = "Si volta verso di te, la sua figura sboccia; la collana che hai allacciato brilla alla sua gola."
  },
  AvgDialog_45427_Content_89 = {
    Text = "Ti invita a danzare; d'istinto, il tuo palmo incontra il suo."
  },
  AvgDialog_45427_Content_9 = {
    Text = "Mythag ha scommesso tre secoli su questo; colui che è stato scelto per portare la fiaccola non può deviare dall'obiettivo."
  },
  AvgDialog_45427_Content_90 = {
    Text = "Ti prende la mano, guidando le tue dita verso la giada pulsante del pendente — come un battito vivente."
  },
  AvgDialog_45427_Content_91 = {
    Text = "Una meteora solca il firmamento.\nI Suoi Occhi brillano più delle Stelle."
  },
  AvgDialog_45427_Content_93 = {
    Text = "Le labbra si schiudono; la brezza notturna porta il suo mormorio."
  },
  AvgDialog_45427_Content_94 = {
    Text = "Posso affidarli a te?"
  },
  AvgDialog_45427_Content_95 = {
    Text = "Il richiamo del Festino stringe di nuovo; senza volerlo, sussurri."
  },
  AvgDialog_45427_Content_96 = {
    Text = "Sì — senza alcun dubbio."
  },
  AvgDialog_45427_Content_97 = {Text = "Bene."},
  AvgDialog_45427_Content_98 = {
    Text = "Thais sorride."
  },
  AvgDialog_45427_Content_99 = {
    Text = "I tuoi amici sono arrivati."
  },
  AvgDialog_45429_Content_1 = {
    Text = "Le sete rosse di Casiah vorticano ovunque, frantumando tazze e piatti nella tenda."
  },
  AvgDialog_45429_Content_10 = {
    Text = "Strappa via l'enorme Cappello Arcano, rivelando una persona inaspettata al suo interno."
  },
  AvgDialog_45429_Content_11 = {
    Text = "Sei tu? Perché?!"
  },
  AvgDialog_45429_Content_12 = {
    Text = "Oh, solo un pizzico di fortuna."
  },
  AvgDialog_45429_Content_13 = {
    Text = "Casiah guarda freneticamente fuori dalla finestra; la sagoma di %player% si allontana rimbalzando in groppa a un cammello."
  },
  AvgDialog_45429_Content_14 = {
    Text = "Tre dadi perforano il drappo, sfiorando la guancia di Casiah."
  },
  AvgDialog_45429_Content_15 = {
    Text = "Oh, quindi resti nei paraggi?"
  },
  AvgDialog_45429_Content_16 = {
    Text = "Bene, rifletti sui tuoi errori nella Dimensione del vuoto!"
  },
  AvgDialog_45429_Content_17 = {
    Text = "Le Illusioni inghiottono l'ambiente circostante; Colori simili a vernice inondano la vista. Quando il Caos vibrante si placa, l'area si trasforma nel palco del mago."
  },
  AvgDialog_45429_Content_18 = {
    Text = "Avvicinatevi al Miracoloso Carnevale Magico di Casiah!"
  },
  AvgDialog_45429_Content_2 = {
    Text = "Tu e Ryker vi scambiate uno sguardo.\nOra la priorità è liberarsi per fermare quel rituale sacrificale di Aram corrotto dalla Chiesa della luce del tempio."
  },
  AvgDialog_45429_Content_3 = {
    Text = "Il Cilindro di Casiah sfreccia verso di te; tu e Ryker vi separate come pianificato, ma il cappello insegue dritto verso—"
  },
  AvgDialog_45429_Content_4 = {
    Text = "Hmph, indovina sotto quale cappello c'è il Custode?"
  },
  AvgDialog_45429_Content_5 = {
    Text = "Quello a sinistra è vuoto, anche quello a destra!"
  },
  AvgDialog_45429_Content_6 = {
    Text = "Ta-da! In realtà, nessuno dei due—guarda, {Male=è nel,Female=è nel} drappo di Casiah!"
  },
  AvgDialog_45429_Content_7 = {
    Text = "Un drappo di seta rossa erutta da una fenditura nel vuoto, vorticando in onde instabili, avvolgendoti stretto come una mummia cremisi."
  },
  AvgDialog_45429_Content_8 = {
    Text = "Come ti piace il {Male=suo,Female=suo} nuovo look? Ha quel tocco alla Aram, eh?"
  },
  AvgDialog_45429_Content_9 = {
    Text = "È telecinesi! Ora, è il momento di ritirare il premio."
  },
  AvgDialog_45430_Content_1 = {
    Text = "Punto di Convergenza"
  },
  AvgDialog_45430_Content_10 = {
    Text = "L'Albero Madre... Non è proprio lì?"
  },
  AvgDialog_45430_Content_100 = {
    Text = "Corri verso l'accampamento ai piedi delle dune."
  },
  AvgDialog_45430_Content_101 = {
    Text = "Nell'istante in cui le tue dita sfiorano il lembo, il terrore ti sopraffà."
  },
  AvgDialog_45430_Content_103 = {
    Text = "Questo Terrore è diverso dall'affrontare il Segugio o il Feto Sacro..."
  },
  AvgDialog_45430_Content_104 = {
    Text = "È radicato nelle ossa, ineludibile, irreparabile — un Orrore indicibile."
  },
  AvgDialog_45430_Content_105 = {
    Text = "Un Incubo alla deriva, un Delirio deforme, una realtà insopportabile e soffocante."
  },
  AvgDialog_45430_Content_106 = {
    Text = "Un Mostro enorme e ferino ondeggia i suoi tentacoli viscidi, l'esile figura di William che penzola da essi come un giunco solitario."
  },
  AvgDialog_45430_Content_108 = {
    Text = "La cicatrice sulla sua fronte — lasciata dalla bruciatura inflittagli dalla madre folle — ora è un solco poco profondo, da cui trasuda una fanghiglia cremisi."
  },
  AvgDialog_45430_Content_109 = {
    Text = "La Chiave d'Argento si frantuma sul suo petto, i guanti standard di Mythag intrisi di sangue, una melma minacciosa che sgocciola verso l'alto in spregio alla gravità."
  },
  AvgDialog_45430_Content_11 = {
    Text = "All'orizzonte lontano, dove la terra incontra il cielo."
  },
  AvgDialog_45430_Content_110 = {
    Text = "Dietro quell'Incubo ondeggiante—"
  },
  AvgDialog_45430_Content_111 = {
    Text = "Un colossale cumulo di carne spalanca le sue fauci come una dionea."
  },
  AvgDialog_45430_Content_112 = {
    Text = "Le pieghe di placente e infanti deformi, nitide come marchi rosso sangue nella tua mente."
  },
  AvgDialog_45430_Content_113 = {
    Text = "Al centro della massa gonfia e contorta giace ciò che ha inseguito senza sosta, cercato — l'ultimo dono per il tuo viaggio."
  },
  AvgDialog_45430_Content_114 = {
    Text = "Ecco il nucleo di Nubia rivelato—"
  },
  AvgDialog_45430_Content_115 = {
    Text = "Una piccola Lanterna."
  },
  AvgDialog_45430_Content_12 = {
    Text = "L'Albero Madre si erge fino alle nuvole, come se fosse al di là del mondo."
  },
  AvgDialog_45430_Content_13 = {
    Text = "Vuoi dire che riesci a vedere l'Albero Madre?"
  },
  AvgDialog_45430_Content_14 = {
    Text = "Inclini il capo verso il cielo, tendendo la mano per tracciarne il profilo."
  },
  AvgDialog_45430_Content_15 = {
    Text = "Un albero rinsecchito, scheletrico... imponente, eppure così solo..."
  },
  AvgDialog_45430_Content_16 = {
    Text = "Forse... l'Albero Madre è svanito a causa della Dissoluzione."
  },
  AvgDialog_45430_Content_17 = {
    Text = "Ricordi? %player% conserva le Memorie di ciò che è stato cancellato dalla Dissoluzione."
  },
  AvgDialog_45430_Content_18 = {
    Text = "Srotoli il giornale di Jenkin, solo per scoprire che l'inchiostro sembra vivo, e si dissolve gradualmente—"
  },
  AvgDialog_45430_Content_19 = {
    Text = "Finché non riesci più a decifrare l'articolo su \"Primavera\"."
  },
  AvgDialog_45430_Content_2 = {
    Text = "Allora, ▼▼▼ tornerà al suo trono,\nIl Caos sarà bandito.\nColoro che ne saranno testimoni gioiranno,\nE coloro che serviranno la Regina gioiranno."
  },
  AvgDialog_45430_Content_20 = {
    Text = "Le filigrane danneggiate e le Macchie d'Inchiostro sembrano determinate a cancellare del tutto l'esistenza di Mason."
  },
  AvgDialog_45430_Content_21 = {Text = "..."},
  AvgDialog_45430_Content_22 = {
    Text = "Che stregoneria è questa? Ho letto questo giornale migliaia di volte."
  },
  AvgDialog_45430_Content_23 = {
    Text = "Ma ora... non riesco a ricordare una sola parola."
  },
  AvgDialog_45430_Content_24 = {
    Text = "Aspetta, non ricordi proprio nulla?"
  },
  AvgDialog_45430_Content_25 = {
    Text = "\"L'eccezionale difensore del Cubismo, la reincarnazione dell'anima di Botticelli, si nasconde ora in un Museo delle Cere all'angolo di Via Southwark...\""
  },
  AvgDialog_45430_Content_26 = {
    Text = "Vedi? Riesco persino a citare quell'articolo parola per parola."
  },
  AvgDialog_45430_Content_27 = {
    Text = "Il giornale è stato Dissolto. Probabilmente un evento di <Yellow:amnesia di massa>, eppure..."
  },
  AvgDialog_45430_Content_28 = {
    Text = "Ramona e Jenkin si voltano verso di te nello stesso istante."
  },
  AvgDialog_45430_Content_29 = {
    Text = "A quanto pare non funziona su qualcuno in particolare."
  },
  AvgDialog_45430_Content_3 = {
    Text = "Quella squadra... solo in tre sono tornati, inclusa Neferure."
  },
  AvgDialog_45430_Content_30 = {Text = "..."},
  AvgDialog_45430_Content_31 = {
    Text = "Che tu ci creda o no, qualcosa non torna affatto..."
  },
  AvgDialog_45430_Content_32 = {
    Text = "Sembra che, senza che nessuno se ne accorga, il passato venga alterato, e la storia devii dal suo corso prestabilito."
  },
  AvgDialog_45430_Content_33 = {
    Text = "E tu sei l'unico testimone di questi cambiamenti."
  },
  AvgDialog_45430_Content_34 = {
    Text = "In quanto ricettacolo dell'Eone del Desiderio, l'Albero Madre deve aver lasciato un segno profondo sul Pianeta."
  },
  AvgDialog_45430_Content_35 = {
    Text = "La sua tenace vitalità rallenta l'erosione della Dissoluzione di mille volte."
  },
  AvgDialog_45430_Content_36 = {
    Text = "Quindi, per te, non è ancora del tutto svanita."
  },
  AvgDialog_45430_Content_37 = {
    Text = "Concedi un altro secolo o millennio, e gli Aramiti probabilmente dimenticheranno che l'Albero Madre sia mai esistito."
  },
  AvgDialog_45430_Content_38 = {
    Text = "Ma il loro Rito potrebbe catturare quel tenue Frammento Residuo della sua presenza."
  },
  AvgDialog_45430_Content_39 = {
    Text = "Come la Cerimonia di risveglio?"
  },
  AvgDialog_45430_Content_4 = {
    Text = "Ma gli Aram sembrano comunque entusiasti. Questo tipo di sacrificio... probabilmente per loro è ormai routine."
  },
  AvgDialog_45430_Content_40 = {
    Text = "Esattamente. La Cerimonia di Risveglio utilizza la forza mentale di un Investigatore per manifestare nuovamente uno Spirito dall'Argento. La \"Rinascita\" dell'Albero Madre dovrebbe funzionare in modo simile."
  },
  AvgDialog_45430_Content_41 = {
    Text = "%player%, che aspetto ha l'Albero Madre ai tuoi occhi?"
  },
  AvgDialog_45430_Content_42 = {
    Text = "Hmm... come dire... Ho visto un tronco spoglio che cresceva in un terreno arido... non c'era nulla di \"Materno\" o \"Rigoglioso\" in esso."
  },
  AvgDialog_45430_Content_43 = {
    Text = "Sembrava quasi come se... l'Albero Madre fosse ai suoi ultimi istanti."
  },
  AvgDialog_45430_Content_44 = {
    Text = "Il rito di Aram è domani. Non andate ancora a dormire?"
  },
  AvgDialog_45430_Content_45 = {
    Text = "La mia dissezione è quasi terminata."
  },
  AvgDialog_45430_Content_46 = {
    Text = "Ancora con la tua autopsia, anche in un momento come questo...\nPerò hai ragione: ci manca un ultimo pezzo."
  },
  AvgDialog_45430_Content_47 = {
    Text = "%player%, questa è la nostra ultima occasione."
  },
  AvgDialog_45430_Content_48 = {
    Text = "Lui è sveglio a dissezionare; e tu, cosa ti tiene sveglio?"
  },
  AvgDialog_45430_Content_49 = {
    Text = "Io... sto rievocando un sogno."
  },
  AvgDialog_45430_Content_5 = {
    Text = "Osservate la Folla un tempo silenziosa; i loro occhi brillano come oasi."
  },
  AvgDialog_45430_Content_50 = {
    Text = "Uno di quei sogni ricorrenti che fai."
  },
  AvgDialog_45430_Content_51 = {
    Text = "Nero pesto, solo il fragore delle maree crescenti che si infrangono sulla riva."
  },
  AvgDialog_45430_Content_52 = {
    Text = "Il tuo cuore batte al ritmo dell'acqua. Innumerevoli cuori battono all'unisono."
  },
  AvgDialog_45430_Content_53 = {
    Text = "Quegli innumerevoli battiti si fondono in un fiume nero, la marea oscura che si riversa incontrollata verso la foce del mare, tingendo l'intero oceano di un nero d'inchiostro..."
  },
  AvgDialog_45430_Content_54 = {
    Text = "Ho sentito dire che i tuoi sogni contengono spesso profezie."
  },
  AvgDialog_45430_Content_55 = {
    Text = "A volte memorie, a volte presagi."
  },
  AvgDialog_45430_Content_56 = {
    Text = "In ogni caso, significa che quelle vite sono state davvero divorate dalla Dissoluzione..."
  },
  AvgDialog_45430_Content_57 = {
    Text = "Non pensarci troppo. Anche senza la Dissoluzione, gli esseri umani continuano a marciare—e a svanire—lungo il cammino."
  },
  AvgDialog_45430_Content_58 = {
    Text = "A parlare così, viene voglia di trascinare qui William, stappare qualche bottiglia."
  },
  AvgDialog_45430_Content_59 = {
    Text = "Il leggendario investigatore di Mythag—ha visto più stranezze di quante scommesse io abbia vinto."
  },
  AvgDialog_45430_Content_6 = {
    Text = "O Albero Madre lassù, ti preghiamo, arricchisci il suolo e le acque di Aram, proteggi le nostre generazioni."
  },
  AvgDialog_45430_Content_60 = {
    Text = "Tocchi la spilla sul petto, chiamando William."
  },
  AvgDialog_45430_Content_61 = {
    Text = "Avrei dovuto... avrei dovuto capirlo prima."
  },
  AvgDialog_45430_Content_62 = {
    Text = [[
Al centro della tenda, il cadavere del Nubia giace sventrato, le incisioni lisce e precise.
Guardando attentamente, si percepisce il suo debole, affannoso respiro.]]
  },
  AvgDialog_45430_Content_63 = {
    Text = "Quello è l'apice di innumerevoli esperimenti—il pulsare sul confine tra la vita e la morte."
  },
  AvgDialog_45430_Content_64 = {
    Text = "Sono in grado di controllare il progresso della Dissoluzione, facendo svanire i Nubia in modi insoliti."
  },
  AvgDialog_45430_Content_65 = {
    Text = "Il nostro nemico possiede una comprensione e un dominio innaturali sulla Dissoluzione."
  },
  AvgDialog_45430_Content_66 = {
    Text = "Posa il bisturi, inspira profondamente—il fetore nauseante simile a sangue lo colpisce, scatenando un violento attacco di tosse."
  },
  AvgDialog_45430_Content_67 = {
    Text = "E quell'inno..."
  },
  AvgDialog_45430_Content_68 = {
    Text = "Le Spoglie della Madre svaniscono, sangue e seme vagano per la Terra, divorati da bestie appena nate."
  },
  AvgDialog_45430_Content_69 = {
    Text = "Cieli e dèi si ammantano di tenebra, finché giunge l'inviato straniero."
  },
  AvgDialog_45430_Content_7 = {
    Text = "Quando ti rianimerai, ti offriremo le nostre acque più dolci..."
  },
  AvgDialog_45430_Content_70 = {
    Text = "Le bestie vengono prima dell'Inviato."
  },
  AvgDialog_45430_Content_71 = {
    Text = "Ecco perché Juliette si aggirava fuori dal Muro della Tempesta, ecco perché era così sicura che l'avremmo oltrepassato quella volta."
  },
  AvgDialog_45430_Content_72 = {
    Text = "Juliette non è il leggendario Inviato Straniero..."
  },
  AvgDialog_45430_Content_73 = {
    Text = "È della Chiesa della luce del tempio, ha fabbricato quella convocazione onirica per guadagnarsi la fiducia degli Aram.\nIl suo obiettivo... probabilmente unirsi a loro e contaminare l'Albero madre e il Fiume sacro."
  },
  AvgDialog_45430_Content_74 = {
    Text = "Il vero Inviato Straniero...\nNon c'è bisogno di indovinare. Dovresti essere tu, Custode, senza alcun dubbio."
  },
  AvgDialog_45430_Content_75 = {
    Text = "No. Deve esserci dell'altro."
  },
  AvgDialog_45430_Content_76 = {
    Text = "Una strana sensazione di terrore spinge William a portare la sua conclusione oltre."
  },
  AvgDialog_45430_Content_77 = {
    Text = "E questi legami anomali...\nSono Gli scultori. È opera di Herbert."
  },
  AvgDialog_45430_Content_78 = {
    Text = "Se il tuo ragionamento si fosse fermato un passo prima, avresti potuto lasciare Remouahe in pace."
  },
  AvgDialog_45430_Content_79 = {
    Text = "Bisogna riconoscerlo al leggendario investigatore di Mythag — sempre un passo avanti, sempre pronto a centrare la risposta."
  },
  AvgDialog_45430_Content_8 = {
    Text = "Non fanno che cantare dell'Albero Madre—chissà quanto è davvero magnifico."
  },
  AvgDialog_45430_Content_80 = {Text = "Herbert!"},
  AvgDialog_45430_Content_81 = {
    Text = "Calma, ora. Ho sempre avuto fiducia nelle tue capacità, più di chiunque altro."
  },
  AvgDialog_45430_Content_82 = {
    Text = "Anche loro sembrano fidarsi parecchio di te. Altrimenti perché lasciarti qui da solo, senza nemmeno un Risveglio al seguito?"
  },
  AvgDialog_45430_Content_83 = {
    Text = "Chi si somiglia si piglia.\nSe ricordo bene, il tuo Risvegliatore si è disconnesso da te a Rye."
  },
  AvgDialog_45430_Content_84 = {
    Text = "Quanto a quella che hai assoldato... dubito che Lady Daffodil si opporrebbe apertamente all'Università di Mythag."
  },
  AvgDialog_45430_Content_85 = {
    Text = "Quindi pensi che non possa ucciderti qui."
  },
  AvgDialog_45430_Content_86 = {
    Text = "Non sottovaluto mai i miei nemici — specialmente chi ha assassinato il Professor Crowley."
  },
  AvgDialog_45430_Content_87 = {
    Text = "Lo so, certo che lo so."
  },
  AvgDialog_45430_Content_88 = {
    Text = "Durante l'indagine nello studio, al rituale della Cresta della Sentinella...\nNessuno dei servitori della volontà superiore ha potuto fermarti, figuriamoci dei semplici Risvegliatori."
  },
  AvgDialog_45430_Content_89 = {
    Text = "Così, quando ho saputo che Mythag aveva mandato te, ho capito che dovevo prepararmi a fondo."
  },
  AvgDialog_45430_Content_9 = {
    Text = "Ryker... di cosa stai parlando...?"
  },
  AvgDialog_45430_Content_90 = {
    Text = "Ramona: Logorato dal tempo, giusto?"
  },
  AvgDialog_45430_Content_91 = {
    Text = "Canalizzare mondi in qualche modo, poi ospitare uno Spirito di un altro mondo più vicino alle esistenze superiori in un Corpo consanguineo."
  },
  AvgDialog_45430_Content_92 = {
    Text = "Herbert accarezza le due teste dello strano gatto sulla sua spalla."
  },
  AvgDialog_45430_Content_93 = {
    Text = "Bravo micetto, vi voglio bene a entrambi allo stesso modo."
  },
  AvgDialog_45430_Content_94 = {
    Text = "<Blue:Helot: Catena>. Tocca a te."
  },
  AvgDialog_45430_Content_95 = {
    Text = "Pronto? William?"
  },
  AvgDialog_45430_Content_96 = {
    Text = "Cinque secondi."
  },
  AvgDialog_45430_Content_97 = {
    Text = "Dieci secondi."
  },
  AvgDialog_45430_Content_98 = {
    Text = "William è a soli cento passi nella tenda, ma la comunicazione resta in un silenzio di morte."
  },
  AvgDialog_45430_Content_99 = {
    Text = "L'inquietudine dilaga, il Terrore martella la tua mente."
  },
  AvgDialog_45431_Content_1 = {Text = "Resti"},
  AvgDialog_45431_Content_10 = {
    Text = "Meglio ora. William non c'è, e non posso lasciarvi soli voi due."
  },
  AvgDialog_45431_Content_11 = {
    Text = "Le sue guance sono ancora lievemente arrossate; le sfiori la fronte, ed è più fresca di prima."
  },
  AvgDialog_45431_Content_12 = {
    Text = "Questo luogo..."
  },
  AvgDialog_45431_Content_13 = {
    Text = "A differenza della distesa primordiale e grezza degli Aramiti, queste sono rovine della civiltà umana: una Fabbrica abbandonata da tempo."
  },
  AvgDialog_45431_Content_14 = {
    Text = "Dopo il Diluvio, il regime di Remouahe spinse l'industrializzazione qui — fabbriche, scuole."
  },
  AvgDialog_45431_Content_15 = {
    Text = "Ma gli Aramiti, inclini alla vita nomade, offrirono scarso sostegno all'industrializzazione del deserto. Questi edifici finirono per crollare con la desertificazione e i cambi di regime."
  },
  AvgDialog_45431_Content_16 = {
    Text = "Non hanno però sprecato questi tetti. Hanno usato la Fabbrica abbandonata per conservare Beni che richiedevano ventilazione, protezione dall'umidità e alta Sicurezza — come i Resti dell'Albero Madre."
  },
  AvgDialog_45431_Content_17 = {
    Text = "Attenzione! Qualcosa si avvicina!"
  },
  AvgDialog_45431_Content_2 = {
    Text = [[
Sei sparito in un batter d'occhio.
Con chi stavi parlando?]]
  },
  AvgDialog_45431_Content_3 = {Text = "..."},
  AvgDialog_45431_Content_4 = {
    Text = "Tutto ciò che devi fare è fidarti completamente di me.\nTi fiderai della Regina di Aram."
  },
  AvgDialog_45431_Content_5 = {
    Text = "Ricorda: stanotte è il nostro segreto."
  },
  AvgDialog_45431_Content_6 = {
    Text = "La tua esitazione non sfugge all'occhio del detective."
  },
  AvgDialog_45431_Content_7 = {
    Text = "Il nostro piccolo amico nasconde un segreto.\nNiente paura! Da uomo adulto e comprensivo quale sono, non indagherò."
  },
  AvgDialog_45431_Content_8 = {
    Text = "Ramona e io abbiamo pedinato gli Aram prima, e abbiamo individuato i resti dell'Albero madre.\nNon c'è tempo da perdere: dobbiamo intrufolarci a mezzanotte."
  },
  AvgDialog_45431_Content_9 = {
    Text = "Ramona, come ti senti?"
  },
  AvgDialog_45432_Content_1 = {
    Text = "Muro della Tempesta"
  },
  AvgDialog_45432_Content_10 = {
    Text = "Il Muro della Tempesta non è una Barriera fisica... è un velo che l'Albero Madre tesse attorno a sé per occultarsi."
  },
  AvgDialog_45432_Content_11 = {
    Text = "Senza l'intenzione di affrontarla, non riuscirai nemmeno a scorgerlo, tanto meno a sfondarlo."
  },
  AvgDialog_45432_Content_12 = {
    Text = "Ecco perché hanno bisogno dell'Inviato Straniero."
  },
  AvgDialog_45432_Content_13 = {
    Text = "La Formazione si apre a ventaglio su entrambi i lati, distanziandosi ogni cinque o dieci passi, formando un lungo serpente di corpi umani."
  },
  AvgDialog_45432_Content_14 = {
    Text = "Tutti prendono posizione, saldi e risoluti."
  },
  AvgDialog_45432_Content_15 = {
    Text = "Alva innalza lo stendardo, e all'unisono trascinano le lance sulla sabbia arida, sollevando polvere accecante, intonando un inno lontano e inquietante."
  },
  AvgDialog_45432_Content_16 = {
    Text = "La morte si avvicina. La Dissoluzione albeggia."
  },
  AvgDialog_45432_Content_17 = {
    Text = "Le Spoglie della Madre svaniscono, sangue e seme vagano per la Terra, divorati da bestie appena nate."
  },
  AvgDialog_45432_Content_18 = {
    Text = "Cieli e dèi si ammantano di tenebra, finché giunge l'inviato straniero."
  },
  AvgDialog_45432_Content_19 = {
    Text = [[
L'Albero Madre risorge: le sue radici bevono a fondo il fluire del Fiume sacro.
Incorona di luce i caduti e richiama il loro sangue a quello di Aram.]]
  },
  AvgDialog_45432_Content_2 = {
    Text = "Sto bene. Alva sta già radunando la squadra. Raggiungiamoli."
  },
  AvgDialog_45432_Content_20 = {
    Text = "Restituisce i lignaggi... ad Aram..."
  },
  AvgDialog_45432_Content_21 = {
    Text = "Il sole del deserto svanisce inavvertito, il cielo si fa plumbeo, il vento muta la sua voce."
  },
  AvgDialog_45432_Content_22 = {
    Text = "Un terrore inspiegabile ti attanaglia; per un istante perdi lucidità, poi un urlo ti riporta in te."
  },
  AvgDialog_45432_Content_23 = {
    Text = "È—è qui!"
  },
  AvgDialog_45432_Content_24 = {
    Text = "In quell'istante di concentrazione, comprendi cosa significhi davvero il \"Muro della Tempesta\"."
  },
  AvgDialog_45432_Content_25 = {
    Text = "Una cortina grigia inghiotte cielo e Terra, avanzando per oscurare i cieli."
  },
  AvgDialog_45432_Content_26 = {
    Text = "Imita un'onda di marea eppure non lo è — vasta e priva di vita, in movimento eppure apparentemente immobile."
  },
  AvgDialog_45432_Content_27 = {
    Text = "Il suo margine lambisce il suolo come la lingua di una Bestia colossale, divorando la linea di Aram nella nebbia, dilaniandoli e digerendoli nelle fauci della tempesta."
  },
  AvgDialog_45432_Content_28 = {
    Text = "Continuate a danzare! Non fermatevi!"
  },
  AvgDialog_45432_Content_29 = {
    Text = "L'Inviato Straniero è con noi; la Regina ci aprirà il cammino verso l'Albero Madre!"
  },
  AvgDialog_45432_Content_3 = {
    Text = "Oggi partiamo alla volta del Muro della Tempesta."
  },
  AvgDialog_45432_Content_30 = {
    Text = "Cogli Juliette con un ghigno sulle labbra."
  },
  AvgDialog_45432_Content_31 = {
    Text = "Capo, Capo... questa tempesta è troppo feroce! Non possiamo permetterci altre perdite... ritiriamoci!"
  },
  AvgDialog_45432_Content_32 = {Text = "No!"},
  AvgDialog_45432_Content_33 = {
    Text = "La sua voce risuona con autorità, eppure il vento la fa tremare."
  },
  AvgDialog_45432_Content_34 = {
    Text = "Le deformità del rito del falò si intensificano ogni volta. Di questo passo, la stirpe di Aram svanirà nell'Oblio prima che raggiungiamo l'Albero Madre."
  },
  AvgDialog_45432_Content_35 = {
    Text = "Juliette piega le dita a formare un anello e soffia un fischio limpido e squillante, la cui nota persistente viene trasportata dalla tempesta verso orizzonti invisibili."
  },
  AvgDialog_45432_Content_36 = {
    Text = "Sono l'Inviata Juliette. Ho udito la volontà della Regina... oggi sfonderemo il Muro della Tempesta!"
  },
  AvgDialog_45432_Content_37 = {
    Text = "Tutti, avanzate! Nessuna ritirata!"
  },
  AvgDialog_45432_Content_38 = {
    Text = "Agli ordini dell'inviato—avanzate! Nessuna ritirata!"
  },
  AvgDialog_45432_Content_39 = {
    Text = "<Small:Non si... torna... indietro...>"
  },
  AvgDialog_45432_Content_4 = {
    Text = "Guerrieri, siete pronti?"
  },
  AvgDialog_45432_Content_40 = {
    Text = "Fermi, Custode! Un enorme branco di Nubia in arrivo da dietro... Almeno duecento!"
  },
  AvgDialog_45432_Content_41 = {
    Text = "Guardate! Questo è il decreto della Regina. L'unica via è davanti a voi!"
  },
  AvgDialog_45432_Content_42 = {
    Text = "La Nubia ruggisce, caricando dritta verso di te."
  },
  AvgDialog_45432_Content_5 = {
    Text = "Noti i soldati che seguono Alva. Le loro espressioni solenni rivelano la determinazione ad affrontare la morte."
  },
  AvgDialog_45432_Content_6 = {
    Text = "Il giovane in testa ha lineamenti affilati e una postura rigida come una lancia — ti sembra familiare."
  },
  AvgDialog_45432_Content_7 = {
    Text = "Il Muro della Tempesta?"
  },
  AvgDialog_45432_Content_8 = {
    Text = "Scruti l'orizzonte: cieli azzurri e limpidi, vista sgombra, nessun segno di tempesta di sabbia."
  },
  AvgDialog_45432_Content_9 = {
    Text = "Juliette fa un passo avanti."
  },
  AvgDialog_45433_Content_1 = {Text = "Epilogo"},
  AvgDialog_45433_Content_10 = {
    Text = "Ma almeno abbiamo scongiurato il peggio."
  },
  AvgDialog_45433_Content_11 = {
    Text = "Se l'Albero Madre fosse rinato sotto il controllo della Chiesa, la contaminazione si sarebbe diffusa ben oltre i deserti settentrionali di Remouahe."
  },
  AvgDialog_45433_Content_12 = {
    Text = "Ciononostante, abbiamo subito il colpo più duro dalla fondazione di Mythag."
  },
  AvgDialog_45433_Content_13 = {
    Text = "Il Corpo di William... non ha prodotto alcun Nucleo d'Argento."
  },
  AvgDialog_45433_Content_14 = {
    Text = "Abbiamo perso per sempre il miglior investigatore di Mythag. Non c'è alcuna possibilità di rianimare neppure parzialmente la sua coscienza."
  },
  AvgDialog_45433_Content_15 = {
    Text = "Oggi, le sue Spoglie saranno deposte qui, in Riposo."
  },
  AvgDialog_45433_Content_16 = {
    Text = "William era l'investigatore più dotato che io conosca. La sua acuta intuizione, l'atteggiamento impavido e le abilità eccezionali lo distinguevano fra tutti noi."
  },
  AvgDialog_45433_Content_17 = {
    Text = "Professor Alistair!"
  },
  AvgDialog_45433_Content_18 = {
    Text = "Tra lo scricchiolio della sedia a rotelle, la folla si aprì al passaggio di Alistair."
  },
  AvgDialog_45433_Content_19 = {
    Text = "In vita, William fu avvolto dal mistero, ma le sue gesta brillanti risplenderanno come stelle eterne."
  },
  AvgDialog_45433_Content_2 = {
    Text = "Su Keygrave cade una pioggia sottile, proprio come il giorno della Cerimonia di consegna della chiave."
  },
  AvgDialog_45433_Content_20 = {
    Text = "La morte ci bracca tutti. Di fronte alla Dissoluzione, abbiamo poco tempo per il lutto."
  },
  AvgDialog_45433_Content_21 = {
    Text = "%player%, vieni con me. Su Tawil, i tre Eoni, la Dissoluzione... c'è molto che devi sapere."
  },
  AvgDialog_45433_Content_22 = {
    Text = "Non avrei mai pensato che la tua indifferenza verso i colleghi arrivasse al punto di saltare il suo funerale."
  },
  AvgDialog_45433_Content_23 = {
    Text = "Non sopporto quell'atmosfera."
  },
  AvgDialog_45433_Content_24 = {
    Text = "Inoltre, con l'Eone della Sagacia che si risveglia, l'Eone del Desiderio che sprofonda, l'Eone dell'Estasi che appare... William non c'è più, quindi tocca a me sudare."
  },
  AvgDialog_45433_Content_25 = {
    Text = "Un Eone dell'Estasi in arrivo?"
  },
  AvgDialog_45433_Content_26 = {
    Text = "Le tracce rinvenute sulla scena della morte di William non sono state vane."
  },
  AvgDialog_45433_Content_27 = {
    Text = "Un Nucleo d'Argento del Reame Ultra — le analisi indicano che appartiene a Casiah."
  },
  AvgDialog_45433_Content_28 = {
    Text = "Inoltre, abbiamo rilevato segni dell'attività dell'Eone dell'Estasi —"
  },
  AvgDialog_45433_Content_29 = {
    Text = "Chi vi ha permesso di trattare il mio giocattolo con tanta noncuranza, costringendomi a recuperarlo di persona?"
  },
  AvgDialog_45433_Content_3 = {
    Text = "Tutti stanno solennemente dinanzi alla lapide incisa, testimoni di un vero funerale."
  },
  AvgDialog_45433_Content_30 = {
    Text = "Grazie per il salvataggio, Signor N."
  },
  AvgDialog_45433_Content_31 = {
    Text = "La prossima volta che ci incontreremo, dirai: grazie, caro Lord N, per la vostra magnanima clemenza, la generosità sconfinata e la grazia indulgente..."
  },
  AvgDialog_45433_Content_32 = {
    Text = "Ryker si gratta la testa pelosa."
  },
  AvgDialog_45433_Content_33 = {
    Text = "Nah, non torna—avevamo concordato che finché non ti avessi battuto almeno una volta, mi avresti fatto rivivere il dolore del fallimento e della morte ancora e ancora, giusto?"
  },
  AvgDialog_45433_Content_34 = {
    Text = "Morire di nuovo significa prima risorgere—quindi mi riporterai sicuramente indietro."
  },
  AvgDialog_45433_Content_35 = {
    Text = "Oh, sei bravo a trovare scappatoie.\nPensi che starò sempre al tuo gioco?"
  },
  AvgDialog_45433_Content_36 = {
    Text = "Beh, sei un pezzo grosso dalla misericordia magnanima, dalla generosità sconfinata e dalla grazia clemente... Quindi sì. Lo farai."
  },
  AvgDialog_45433_Content_37 = {
    Text = "Hmm. Dipende da che spettacolo mi metti in scena la prossima volta."
  },
  AvgDialog_45433_Content_38 = {
    Text = [[
Con quella battuta finale, la sagoma di N svanisce.
Ryker si rivolge al gruppo.]]
  },
  AvgDialog_45433_Content_39 = {
    Text = [[
Comunque, sono tornato.
Lord Dexter, pronto per un altro round?]]
  },
  AvgDialog_45433_Content_4 = {
    Text = "Oggi, un nuovo compagno si unisce ai nostri ranghi."
  },
  AvgDialog_45433_Content_40 = {
    Text = "Nel frattempo, Deserto di Remouahe"
  },
  AvgDialog_45433_Content_41 = {
    Text = "Piano, piano—con calma, ora."
  },
  AvgDialog_45433_Content_42 = {
    Text = "Mio fedele, obbediente segugio—fiuta la traiettoria di quei due per me."
  },
  AvgDialog_45433_Content_43 = {
    Text = "Solo allora potrò riferire al Faraone."
  },
  AvgDialog_45433_Content_44 = {
    Text = "Il ragazzo si rannicchia nell'angolo della fabbrica, sbirciando di tanto in tanto verso la distanza."
  },
  AvgDialog_45433_Content_45 = {
    Text = "Siamo arrivati fin qui—dovremmo essere al sicuro per ora..."
  },
  AvgDialog_45433_Content_46 = {
    Text = "Ora devo capire come fargli comprendere il mondo esterno."
  },
  AvgDialog_45433_Content_47 = {
    Text = "Prima che quello ci trovi."
  },
  AvgDialog_45433_Content_48 = {
    Text = "Non si accorge che la sua ombra si allunga nella luce che filtra dalla finestra."
  },
  AvgDialog_45433_Content_49 = {
    Text = "Quell'ombra allungata sfoggia all'improvviso un ghigno sinistro."
  },
  AvgDialog_45433_Content_5 = {
    Text = "È un onore far parte di Mythag.\nLotterò al vostro fianco per salvare il futuro dell'umanità."
  },
  AvgDialog_45433_Content_6 = {
    Text = "Il giorno in cui lasciò Remouahe, Alva si fermò presso il Fiume sacro, raccolse un pugno d'acqua e la bevve."
  },
  AvgDialog_45433_Content_7 = {
    Text = "Nessuno osò chiederle cosa si provasse a guardare l'intera tribù dissolversi nel torrente davanti ai suoi occhi."
  },
  AvgDialog_45433_Content_8 = {
    Text = "Ma sotto questo diluvio, l'espressione tenace di Alva ti convince che ha scelto il suo nuovo cammino."
  },
  AvgDialog_45433_Content_9 = {
    Text = "In questa indagine abbiamo affrontato il nemico più arduo. Non siamo riusciti a impedire alla Chiesa dei Portatori di Luce di contaminare l'Albero Madre. Gli Aramiti sono stati cancellati dalla storia."
  },
  AvgDialog_45434_Content_1 = {
    Text = "Vi infilate nei passaggi angusti della fabbrica, schivando macchinari antichi che gemono di ruggine."
  },
  AvgDialog_45434_Content_10 = {
    Text = "Ma scelgo di fidarmi del Custode, proprio come fa Mythag."
  },
  AvgDialog_45434_Content_11 = {
    Text = "Aspetta—è quello che ha detto il soldato!"
  },
  AvgDialog_45434_Content_12 = {
    Text = "Aggirando macchinari pesanti, una finestra in frantumi incombe; sotto di essa si annida il vostro vecchio nemico —"
  },
  AvgDialog_45434_Content_2 = {
    Text = "Persino a Londinium, gruppi di queste dimensioni sono rari."
  },
  AvgDialog_45434_Content_3 = {
    Text = "Qualche decennio, e non resta che ruggine."
  },
  AvgDialog_45434_Content_4 = {
    Text = "308 d.F., il Regno di Remouahe invitò apertamente gli Aram a stabilirsi a <Blue:Nasha>, la capitale.\nOvviamente, nessuno accettò l'offerta."
  },
  AvgDialog_45434_Content_5 = {
    Text = "Agli Aramiti mancano la volontà e i mezzi per una società industriale — venerano poteri più grezzi e trascendenti."
  },
  AvgDialog_45434_Content_6 = {
    Text = "Pensavo che gente come noi potesse comprenderli meglio di chiunque altro."
  },
  AvgDialog_45434_Content_7 = {
    Text = "Credi che la <Yellow:Tecnologia d'Argento> possa cambiare il futuro dell'umanità?"
  },
  AvgDialog_45434_Content_8 = {
    Text = "Il futuro dell'Umanità? Cieco a esso — tre secoli di indagini non hanno sfiorato il nucleo della Dissoluzione."
  },
  AvgDialog_45434_Content_9 = {
    Text = "Ogni sentiero può condurre alla meta... o alla fine di ogni cosa."
  },
  AvgDialog_45435_Content_1 = {Text = "Magia"},
  AvgDialog_45435_Content_10 = {Text = "..."},
  AvgDialog_45435_Content_11 = {
    Text = "Le parole da sole non provano nulla. Recupereremo i Resti dell'Albero Madre e li restituiremo ad Aram."
  },
  AvgDialog_45435_Content_12 = {
    Text = "Alva rimugina, soppesando le tue parole."
  },
  AvgDialog_45435_Content_13 = {
    Text = "Infine, sembra giungere a una conclusione."
  },
  AvgDialog_45435_Content_14 = {
    Text = "Il convoglio partirà verso il Muro della Tempesta domani pomeriggio."
  },
  AvgDialog_45435_Content_15 = {
    Text = "Ci restituirete le Spoglie prima di allora..."
  },
  AvgDialog_45435_Content_16 = {
    Text = "...oppure sarete banditi per sempre."
  },
  AvgDialog_45435_Content_17 = {
    Text = "Alva e i soldati escono uno a uno, lasciando la vasta Fabbrica vuota, con solo voi tre al suo interno."
  },
  AvgDialog_45435_Content_18 = {
    Text = "Niente male—hai tessuto una bella storia."
  },
  AvgDialog_45435_Content_19 = {
    Text = "Alva non ci ha creduto davvero; aveva solo bisogno di una spiegazione."
  },
  AvgDialog_45435_Content_2 = {
    Text = "<Small:Beh, dovrei dire che c'è sempre un imprevisto? Questo tizio è più tosto di quanto pensassimo.>"
  },
  AvgDialog_45435_Content_20 = {
    Text = "Ha chiaramente notato che non avevamo ancora le Spoglie — che ci costringa a consegnarle o che sfrutti la nostra forza per trovarle, le conviene più che scontrarsi apertamente con noi."
  },
  AvgDialog_45435_Content_21 = {
    Text = "Quindi dobbiamo trovare i Resti dell'Albero Madre in un giorno. Hai un piano?"
  },
  AvgDialog_45435_Content_22 = {
    Text = "Diciamo che ho un'idea che vale la pena tentare."
  },
  AvgDialog_45435_Content_23 = {
    Text = "Chiudi gli occhi, sprofondando negli abissi della mente."
  },
  AvgDialog_45435_Content_24 = {
    Text = "Una Cantilena si leva come una Preghiera."
  },
  AvgDialog_45435_Content_25 = {
    Text = "La morte si avvicina. La Dissoluzione albeggia."
  },
  AvgDialog_45435_Content_26 = {
    Text = "Le Spoglie della Madre svaniscono, sangue e seme vagano per la Terra, divorati da bestie appena nate."
  },
  AvgDialog_45435_Content_27 = {
    Text = "Una risatina frantuma la tua fantasticheria. Alzi lo sguardo: in cima al feretro si staglia la sagoma di una donna, giunta senza invito."
  },
  AvgDialog_45435_Content_28 = {
    Text = "Posso affidarli a te?"
  },
  AvgDialog_45435_Content_29 = {Text = "..."},
  AvgDialog_45435_Content_3 = {
    Text = [[
Ryker si gratta la nuca.
Il robusto soldato di Aram lo fissa con ferocia, ma indietreggia quando Ryker mostra i denti.]]
  },
  AvgDialog_45435_Content_30 = {
    Text = "Pensieri tumultuosi tremolano, si intrecciano, si fondono nel tuo cranio."
  },
  AvgDialog_45435_Content_31 = {
    Text = "Un tenue, etereo filo di guida incolore prende forma, indicando la risposta finale."
  },
  AvgDialog_45435_Content_32 = {
    Text = "I Resti dell'Albero Madre sono proprio qui."
  },
  AvgDialog_45435_Content_33 = {
    Text = "Sfiori delicatamente il muro, poi chiudi gli occhi e affondi la mano senza esitazione, afferrando un morbido pezzo di tessuto, quindi lo strappi fuori—"
  },
  AvgDialog_45435_Content_34 = {
    Text = "Ehi—fermo, fermo—"
  },
  AvgDialog_45435_Content_35 = {
    Text = "Il \"muro\" crolla; il falso bagliore cede alla luce accecante del sole."
  },
  AvgDialog_45435_Content_36 = {
    Text = "Ehi, mi hai rovinato il mantello!"
  },
  AvgDialog_45435_Content_37 = {
    Text = "Dovrei dire che i nemici si incontrano su una strada stretta, o che il legame tra Alumni continua ad attrarci l'un l'altro?"
  },
  AvgDialog_45435_Content_38 = {
    Text = "La Ricerca di Francis si limitava alla Dissoluzione. Il cifrario in quel Sanatorio era opera tua."
  },
  AvgDialog_45435_Content_39 = {
    Text = "Questi soggetti sperimentali potrebbero sfuggire alle guardie ed entrare nella Fabbrica inosservati, ma spostare le Spoglie è un lavoro impegnativo — non poteva avvenire in silenzio."
  },
  AvgDialog_45435_Content_4 = {
    Text = "Capo Alva, li ho reclutati per sorvegliare i Resti dell'Albero Madre..."
  },
  AvgDialog_45435_Content_40 = {
    Text = "Non potevamo vedere le Spoglie a causa di un'<Blue:Illusione> — hai spostato questo muro verso l'interno di due metri."
  },
  AvgDialog_45435_Content_41 = {
    Text = "Impressionante. Hai fatto molta strada da {Male=quel tipo,Female=quella ragazza} che ha abbandonato {Male=i suoi,Female=le sue} alleati ed è fuggito l'ultima volta che ci siamo incontrati."
  },
  AvgDialog_45435_Content_42 = {
    Text = "Quindi, Casiah, le tue illusioni sono fin troppo facili da infrangere."
  },
  AvgDialog_45435_Content_43 = {
    Text = "Hmph, hai quel che paghi. Gli agenti di campo di Mythag sono tutti così emotivamente stabili... non valgono neanche un soldo."
  },
  AvgDialog_45435_Content_44 = {
    Text = "Ho trucchi ben più raffinati nella manica. Far aprire un portale a Lady Daffodil e spedire fuori questa maledetta bara per voi non sarebbe difficile, ma..."
  },
  AvgDialog_45435_Content_45 = {Text = "Hmm?"},
  AvgDialog_45435_Content_46 = {
    Text = "Costerà di più!"
  },
  AvgDialog_45435_Content_47 = {
    Text = "Lady Daffodil sa che le mie finanze non sono granché. Se mi dissangua, perderà un cliente fedele, no?"
  },
  AvgDialog_45435_Content_48 = {
    Text = "Chi va piano va sano e lontano, dopotutto."
  },
  AvgDialog_45435_Content_49 = {
    Text = "Ehm! Forse voi due potreste contrattare sui prezzi dopo che avremo finito qui?"
  },
  AvgDialog_45435_Content_5 = {
    Text = "E questo dà loro il diritto di legare il mio soldato e interrogarlo sulla posizione della reliquia?"
  },
  AvgDialog_45435_Content_50 = {
    Text = "Ryker lancia in aria il dado che tiene in mano, poi lo scaglia con forza—"
  },
  AvgDialog_45435_Content_51 = {
    Text = [[
Il suo cilindro vola in alto, raccogliendo al volo il dado in corsa, poi torna alla proprietaria.
Casiah tira la tesa e lo scuote, lasciando cadere a cascata la polvere del dado polverizzato.]]
  },
  AvgDialog_45435_Content_52 = {
    Text = "Visto? Non ti lasceranno andare facilmente."
  },
  AvgDialog_45435_Content_53 = {
    Text = "Miei Alumni di Mythag... che ne dite se entrambi facciamo un passo indietro, per i vecchi tempi?"
  },
  AvgDialog_45435_Content_54 = {
    Text = "Sono qui per i Resti dell'Albero Madre; e Mythag... scommetto che volete <Yellow:eliminarne la contaminazione> per impedire che inquini il Fiume sacro."
  },
  AvgDialog_45435_Content_55 = {
    Text = "Facciamo un patto: le Spoglie sono mie, l'Albero Madre resta morto, e ce ne torniamo tutti a casa. Non è una vittoria per entrambi?"
  },
  AvgDialog_45435_Content_56 = {
    Text = "<Yellow:Contaminazione>? A quanto pare Daffodil ha dato agli Scultori più informazioni che a noi."
  },
  AvgDialog_45435_Content_57 = {
    Text = "Se è così, non possiamo consegnare le Spoglie."
  },
  AvgDialog_45435_Content_58 = {
    Text = "Allora anticipiamo un po' lo spettacolo di magia di Casiah!"
  },
  AvgDialog_45435_Content_6 = {
    Text = "L'Ispirazione ti colpisce mentre ricordi il Mostro incontrato in precedenza."
  },
  AvgDialog_45435_Content_7 = {
    Text = "Poco fa abbiamo avvistato Herbert, il capo dell'Associazione degli Scultori, entrare nella Fabbrica dove sono custodite le Spoglie — ecco perché siamo qui."
  },
  AvgDialog_45435_Content_8 = {
    Text = "Herbert è un uomo mosso da desideri egoisti, che cerca ovunque reliquie dotate di poteri speciali. Sospettiamo che miri al potere dei Resti dell'Albero Madre."
  },
  AvgDialog_45435_Content_9 = {
    Text = "Non avevamo altra scelta che agire d'urgenza e strappare le informazioni al soldato, ma purtroppo eravamo ancora un passo indietro."
  },
  AvgDialog_45436_Content_1 = {Text = "Brace"},
  AvgDialog_45436_Content_2 = {
    Text = "Perché... i Resti dell'Albero Madre sono ancora intatti..."
  },
  AvgDialog_45436_Content_3 = {
    Text = "Non l'hai ancora capito? I cosiddetti Resti dell'Albero Madre erano solo un'esca."
  },
  AvgDialog_45436_Content_4 = {
    Text = "Tutto ciò di cui abbiamo davvero bisogno è l'\"Inviato Straniero\" e la carne degli Aramiti."
  },
  AvgDialog_45436_Content_5 = {
    Text = "Ora, quello sciocco inviato—vale a dire, tu—ha aperto il Muro della Tempesta per me, e gli Aramiti hanno bevuto l'acqua del fiume intrisa di cenere di Lanterna."
  },
  AvgDialog_45436_Content_6 = {
    Text = "La mia grande visione è in corso. Non resta che attendere la crescita dell'Albero Madre."
  },
  AvgDialog_45436_Content_7 = {
    Text = "Ah, non vedo l'ora di vedere la Dissoluzione ricoprire la terra, i cancelli del Reame divino spalancati..."
  },
  AvgDialog_45437_Content_1 = {Text = "Collana"},
  AvgDialog_45437_Content_10 = {
    Text = "La folla indugia."
  },
  AvgDialog_45437_Content_11 = {
    Text = "Bene, tutti quanti, tornate ai vostri compiti."
  },
  AvgDialog_45437_Content_12 = {
    Text = "Partiremo per il Muro della Tempesta tra due giorni; anch'io ho bisogno del mio sonno di bellezza!"
  },
  AvgDialog_45437_Content_13 = {
    Text = "Abbiamo tenuto le vostre stanze immacolate, in Attesa del vostro Ritorno. L'Incenso Calmante è acceso—per l'Albero Madre, che dolci sogni vi avvolgano."
  },
  AvgDialog_45437_Content_14 = {
    Text = "In un angolo trascurato, Thais balza giù dalla bara, confondendosi senza sforzo tra La Folla."
  },
  AvgDialog_45437_Content_15 = {
    Text = "Avvistate i Resti dell'Albero Madre?"
  },
  AvgDialog_45437_Content_16 = {
    Text = "Il Custode li tiene d'occhio senza sosta."
  },
  AvgDialog_45437_Content_17 = {
    Text = "Aspetta. Dov'è il Custode?"
  },
  AvgDialog_45437_Content_18 = {
    Text = "Permesso! Fate largo, per favore."
  },
  AvgDialog_45437_Content_19 = {
    Text = "Svoltate qualche curva, facendovi largo tra la calca, cercando Thais con lo sguardo."
  },
  AvgDialog_45437_Content_2 = {
    Text = "Quel mercato è davvero uno spettacolo!"
  },
  AvgDialog_45437_Content_20 = {
    Text = "La frustrazione per aver perso la traccia vi sale nel petto. Sospirando, vi voltate indietro, solo per trovare Thais nell'Ombra dell'edificio, che vi fa cenno con un sorriso."
  },
  AvgDialog_45437_Content_21 = {
    Text = "Mi stavi cercando?"
  },
  AvgDialog_45437_Content_22 = {
    Text = "Seguite Thais mentre scivola tra i vicoli in un Silenzio insolito per lei."
  },
  AvgDialog_45437_Content_23 = {
    Text = "A una bancarella traboccante di cianfrusaglie, si ferma, avvicinandosi per Sussurrare al vostro orecchio."
  },
  AvgDialog_45437_Content_24 = {
    Text = "Potresti comprarmi questo?"
  },
  AvgDialog_45437_Content_25 = {
    Text = "Il tuo sguardo segue il suo dito fino a un collare di metallo."
  },
  AvgDialog_45437_Content_26 = {
    Text = "Occhio acuto, {Male=signore,Female=signorina}! Volete vederlo da vicino?"
  },
  AvgDialog_45437_Content_27 = {
    Text = "È opera di mia figlia! Ha scelto lei stessa i materiali. Quel lapislazzuli al centro? Tessitura uniforme, tonalità intensa, si riconosce la qualità!"
  },
  AvgDialog_45437_Content_28 = {
    Text = "Niente lapislazzuli."
  },
  AvgDialog_45437_Content_29 = {
    Text = "Niente lapislazzuli?"
  },
  AvgDialog_45437_Content_3 = {
    Text = "L'inviata! La carovana dell'inviata è tornata!"
  },
  AvgDialog_45437_Content_30 = {
    Text = "Eh? Il lapislazzuli è il Gioiello della Corona—siete sicuro di non volerlo?"
  },
  AvgDialog_45437_Content_31 = {
    Text = "Aggiungendo quel lapislazzuli, i fondi che Mythag ti ha affidato saranno ridotti all'osso."
  },
  AvgDialog_45437_Content_32 = {
    Text = "Sì, lascia perdere il lapislazzuli."
  },
  AvgDialog_45437_Content_33 = {
    Text = "Certo. Te lo incarto."
  },
  AvgDialog_45437_Content_34 = {
    Text = "Tu e Thais raggiungete il limitare del villaggio; sabbie sferzate dal vento si estendono all'infinito, avvoltoi tracciano archi pigri con grida di maturità."
  },
  AvgDialog_45437_Content_35 = {
    Text = "Artigianato Kara, tramandato di generazione in generazione—ancora impeccabile."
  },
  AvgDialog_45437_Content_36 = {
    Text = "Lei percorre con le dita le incisioni del collare, rivolgendo verso di te l'incastonatura della gemma."
  },
  AvgDialog_45437_Content_37 = {
    Text = "Questo motivo è l'emblema dell'Albero Madre—un mio disegno."
  },
  AvgDialog_45437_Content_38 = {
    Text = "Ora, mio inviato Da Lontano... me lo allaccerete?"
  },
  AvgDialog_45437_Content_39 = {
    Text = "Prendi il collare; Thais inclina il capo, il tuo braccio le cinge il collo e la fronte, i respiri si mescolano."
  },
  AvgDialog_45437_Content_4 = {
    Text = "Gli Abitanti del villaggio intasano i vicoli stretti, levando in alto nelle mani i Tributi per Juliette."
  },
  AvgDialog_45437_Content_40 = {
    Text = "Una gemma simile a giada bianca corona il pendente, il suo bagliore latteo vela il faint rossore della vita—come il pudico arrossire di una fanciulla, che sboccia appena."
  },
  AvgDialog_45437_Content_41 = {
    Text = "Mmm, mi piace. Per questo dono, risponderò alle tue domande.\nNe hai parecchie, credo?"
  },
  AvgDialog_45437_Content_42 = {
    Text = "Ma prima—ospiti sgraditi si avvicinano. Puniamo insieme questi seccatori stonati?"
  },
  AvgDialog_45437_Content_5 = {
    Text = "Signora Inviata, questo è per voi!"
  },
  AvgDialog_45437_Content_6 = {
    Text = "In coda al corteo, Thais se ne stava sdraiata sopra una bara portata da quattro Guerrieri di Aram."
  },
  AvgDialog_45437_Content_7 = {
    Text = "Rispetto al fragoroso Benvenuto per Juliette, gli sparuti Applausi che Thais riceve rendono il suo titolo di Regina un'eco vuota."
  },
  AvgDialog_45437_Content_8 = {
    Text = "Grazie. Il sole cocente dev'essere una prova per voi, eppure siete qui ad accoglierci. Il vostro calore è indimenticabile."
  },
  AvgDialog_45437_Content_9 = {
    Text = "Devi essere stanco. Per favore, riposa ora e goditi la pace della notte."
  },
  AvgDialog_45438_Content_1 = {
    Text = "Juliette... Perché..."
  },
  AvgDialog_45438_Content_2 = {
    Text = "Inutile nascondersi, ormai."
  },
  AvgDialog_45438_Content_3 = {
    Text = "Gli Aramiti barattano il sangue dei loro deformi per la proliferazione—la loro stessa esistenza è lordura e peccato."
  },
  AvgDialog_45438_Content_4 = {
    Text = "Nati portando il peccato originale, sono adatti solo come esca per le fondamenta della Terra Pura."
  },
  AvgDialog_45438_Content_5 = {
    Text = "E il più prezioso tra loro, quel fanciullo inestimabile è già mio. Egli è degno del nuovo mondo."
  },
  AvgDialog_45438_Content_6 = {
    Text = "Un segugio dal volto umano si accuccia ai piedi di Alva."
  },
  AvgDialog_45438_Content_7 = {
    Text = "Via, via. Che bravo fanciullo. Tu sei il mio prescelto."
  },
  AvgDialog_45438_Content_8 = {
    Text = "Nefe...rure..."
  },
  AvgDialog_45438_Content_9 = {
    Text = "Va', fanciullo—custodisci la Rinascita dalla Terra dell'Albero Madre. Squarcia i tuoi nemici."
  },
  AvgDialog_45439_Content_1 = {
    Text = "Cos'è tutto questo trambusto?"
  },
  AvgDialog_45439_Content_10 = {
    Text = "Quali prove avete?"
  },
  AvgDialog_45439_Content_11 = {
    Text = [[
Ricordi la morte orribile di William.
Fu ucciso da un vile mostro legato alla Chiesa della luce del tempio.]]
  },
  AvgDialog_45439_Content_12 = {
    Text = "Ma al momento non hai nulla di concreto contro Juliette."
  },
  AvgDialog_45439_Content_13 = {
    Text = "Vi prego, ripensate ai giorni che abbiamo condiviso."
  },
  AvgDialog_45439_Content_14 = {
    Text = "Credi davvero alle {Male=sue,Female=sue} affermazioni deliranti?"
  },
  AvgDialog_45439_Content_15 = {
    Text = "Dubbi si propagano tra la Folla. Non si fidano di te."
  },
  AvgDialog_45439_Content_16 = {
    Text = "%player%, ho il cuore spezzato. Fino ad ora mi sono fidata di te, ho chiuso un occhio sulla tua scortesia ad Aram, ho persino perorato la tua causa presso il capo."
  },
  AvgDialog_45439_Content_17 = {
    Text = "A quanto pare vi avevo giudicato male."
  },
  AvgDialog_45439_Content_18 = {
    Text = "Lady Alva, vi prego, perdonate il mio errore."
  },
  AvgDialog_45439_Content_19 = {
    Text = "I tuoi rancori personali sono irrilevanti. Oggi il Rito deve giungere a compimento."
  },
  AvgDialog_45439_Content_2 = {
    Text = "La Folla apre un sentiero."
  },
  AvgDialog_45439_Content_20 = {
    Text = "Chiunque interferisca con la Rinascita dalla Terra dell'Albero Madre diventerà un Sacrificio!"
  },
  AvgDialog_45439_Content_3 = {Text = "Voi?"},
  AvgDialog_45439_Content_4 = {
    Text = "Sì — abbiamo notizie urgenti."
  },
  AvgDialog_45439_Content_5 = {
    Text = "Juliette... vi ha ingannato per tutto questo tempo."
  },
  AvgDialog_45439_Content_6 = {
    Text = "Non è l'inviata leggendaria, e non possiede alcun Potere per far rinascere l'Albero Madre."
  },
  AvgDialog_45439_Content_7 = {
    Text = "Non è riuscita nemmeno a oltrepassare il Muro della Tempesta, perché è una creazione di Thais — della Regina, una Barriera contro i senza fede!"
  },
  AvgDialog_45439_Content_8 = {
    Text = "Ti guardi intorno; Juliette è in testa alla Folla, le tue parole non suscitano in lei la minima increspatura."
  },
  AvgDialog_45439_Content_9 = {
    Text = "Avete prove per queste accuse?"
  },
  AvgDialog_45440_Content_1 = {
    Text = "Lady Juliette... mi... ricompenserà... vero..."
  },
  AvgDialog_45440_Content_2 = {
    Text = "Ma certo, cara. Sei stata di grande aiuto."
  },
  AvgDialog_45440_Content_3 = {
    Text = "L'Albero Madre... sta prendendo forma."
  },
  AvgDialog_45441_Content_1 = {Text = "Rivale"},
  AvgDialog_45441_Content_2 = {
    Text = "Ryker spalanca con un calcio il portone di ferro arrugginito, sollevando vortici di polvere."
  },
  AvgDialog_45441_Content_3 = {
    Text = "Ringhi sinistri e familiari, e lo Scricchiolio di giunture echeggiano da ogni lato."
  },
  AvgDialog_45441_Content_4 = {
    Text = "Non scherzo. Sono quei mostri da laboratorio dell'Associazione degli Scultori?"
  },
  AvgDialog_45441_Content_5 = {
    Text = "Li vedo anch'io."
  },
  AvgDialog_45441_Content_6 = {
    Text = "Che rissa. Sento puzza di marcio."
  },
  AvgDialog_45441_Content_7 = {
    Text = "I Resti dell'Albero Madre sono là! V-vicino alla finestra!"
  },
  AvgDialog_45441_Content_8 = {
    Text = "Andiamo. Se perdiamo altro tempo, se la farà addosso."
  },
  AvgDialog_45442_Content_1 = {Text = "Sogno"},
  AvgDialog_45442_Content_10 = {
    Text = "Non va bene così, Alva."
  },
  AvgDialog_45442_Content_100 = {Text = "..."},
  AvgDialog_45442_Content_101 = {
    Text = "Un lungo sospiro echeggia nell'aria."
  },
  AvgDialog_45442_Content_102 = {
    Text = "Sei un burattino difettoso, dopotutto. Richiedi fin troppo sforzo per essere controllato."
  },
  AvgDialog_45442_Content_103 = {
    Text = "Più Forte è la tua Devozione nel Sacrificarti per Aram... più feroce sarà la tua Resistenza quando scoprirai La Verità."
  },
  AvgDialog_45442_Content_104 = {
    Text = "Per fortuna, l'avevo previsto."
  },
  AvgDialog_45442_Content_105 = {
    Text = "I tempi sono quasi maturi. Tutti voi, il vostro amato Albero Madre..."
  },
  AvgDialog_45442_Content_106 = {
    Text = "reclamerà la vostra carne e le vostre vite."
  },
  AvgDialog_45442_Content_107 = {
    Text = [[
Apro la bocca, sconvolto nello scoprire che nessun suono ne Emerge.
Il mondo si arresta in modo terrificante.]]
  },
  AvgDialog_45442_Content_108 = {
    Text = "No, non è il mondo; i miei sensi si arrestano, ogni faint bagliore si estende per secoli."
  },
  AvgDialog_45442_Content_109 = {
    Text = "In questa stasi interminabile, solo i miei vecchi compagni—un Soldato di Aram dopo l'altro—si lanciano incuranti verso il Fiume sacro."
  },
  AvgDialog_45442_Content_11 = {
    Text = "Che ne dici di questo: <Blue:Haleman> ha appena mandato un invito, chiedendomi di assaggiare i suoi vini pregiati."
  },
  AvgDialog_45442_Content_110 = {Text = "Splash—"},
  AvgDialog_45442_Content_111 = {
    Text = "Suono e colore tornano d'un tratto."
  },
  AvgDialog_45442_Content_112 = {
    Text = "Uno dopo l'altro, si gettano imperterriti nella corrente del fiume, le braccia protese, abbracciando il tronco avvizzito dell'Albero Madre."
  },
  AvgDialog_45442_Content_113 = {
    Text = "Gridano e ululano in una folle, indescrivibile frenesia."
  },
  AvgDialog_45442_Content_114 = {
    Text = "La loro pelle si affloscia come fango; i fluidi si prosciugano dai loro corpi, unendosi alla corrente del fiume."
  },
  AvgDialog_45442_Content_115 = {
    Text = "Le ossa si ammorbidiscono come carne; gli arti si torcono in modo disumano, si allungano, si intrecciano—fondendo sangue e carne nei rami gonfi dell'albero sacro."
  },
  AvgDialog_45442_Content_116 = {
    Text = "Lentamente, in modo straziante, si fondono con l'albero sacro."
  },
  AvgDialog_45442_Content_12 = {
    Text = "Vieni con me. Berremo fino all'alba. Che ne dici?"
  },
  AvgDialog_45442_Content_13 = {
    Text = "Lady Thais, temo che..."
  },
  AvgDialog_45442_Content_14 = {
    Text = "I soldati eseguono gli ordini — l'avete detto voi stessa."
  },
  AvgDialog_45442_Content_15 = {
    Text = "Ora, ecco il mio ordine: berremo fino all'alba. Insieme."
  },
  AvgDialog_45442_Content_16 = {
    Text = "Dunque volete un'utopia senza spargimento di Sangue né lacrime?"
  },
  AvgDialog_45442_Content_17 = {
    Text = "Chi l'avrebbe mai detto! La nostra rigida capotribù nasconde sogni così ingenui nel profondo del cuore."
  },
  AvgDialog_45442_Content_18 = {
    Text = "Lady Thais, vi prego, non scherzate così con me..."
  },
  AvgDialog_45442_Content_19 = {
    Text = "No, non sto scherzando."
  },
  AvgDialog_45442_Content_2 = {
    Text = "Alva, sei stata richiamata già da parecchio tempo ormai. Ma hai passato tutta la giornata tra esercitazioni e faccende! Hai persino rifiutato il Banchetto di Karune."
  },
  AvgDialog_45442_Content_20 = {
    Text = "Nutro tutta Remouahe con la mia carne e il mio sangue, affinché la stirpe degli Aramiti scorra in eterno."
  },
  AvgDialog_45442_Content_21 = {
    Text = "Li faccio procreare senza sosta, sperando che almeno uno possa sfuggire al Suo Sguardo e portare la mia volontà attraverso i cicli di inizio e fine..."
  },
  AvgDialog_45442_Content_22 = {
    Text = "Non siamo forse ugualmente ingenui e sciocchi, tu ed io?"
  },
  AvgDialog_45442_Content_23 = {Text = "..."},
  AvgDialog_45442_Content_24 = {
    Text = "Già addormentato?"
  },
  AvgDialog_45442_Content_25 = {
    Text = "E sia. Non sei nata ad Aram, del resto. Non dovresti restare intrappolata in questo deserto desolato, Alva."
  },
  AvgDialog_45442_Content_26 = {
    Text = "Quando la mia vita giungerà al termine, lascerai Remouahe e ti legherai a qualcun altro."
  },
  AvgDialog_45442_Content_27 = {
    Text = "Quel giorno... si avvicina."
  },
  AvgDialog_45442_Content_28 = {
    Text = "Sedevo nella tenda della Regina; fuori, lamenti funebri laceravano l'aria con dolore crudo, sofferenza e diniego."
  },
  AvgDialog_45442_Content_29 = {
    Text = "Piangere per qualcuno di cui ti fidavi—è una sorta di fortuna.\nSul campo di battaglia, raramente avevamo tempo per versare lacrime sui compagni caduti."
  },
  AvgDialog_45442_Content_3 = {
    Text = "Non desideri nulla da me? Qualche ricompensa che vorresti?"
  },
  AvgDialog_45442_Content_30 = {
    Text = "Per me, la questione cruciale era il futuro di Aram, ora che la Regina non c'era più.\nSe gli Aram avessero smesso di pensare, paralizzati dal dolore, allora avrei pensato io per loro."
  },
  AvgDialog_45442_Content_31 = {
    Text = "Lady Thais non si è mai fidata di me. L'ho sempre saputo."
  },
  AvgDialog_45442_Content_32 = {
    Text = "Per gli Aramiti, il sangue definiva la parentela; con vene straniere, sarei stata per sempre un'estranea."
  },
  AvgDialog_45442_Content_33 = {
    Text = "Ma Aram aveva bisogno di un leader — nello spirito e nella carne."
  },
  AvgDialog_45442_Content_34 = {
    Text = "Assumerò il ruolo di capotribù, a guardia della bara di Lady Thais."
  },
  AvgDialog_45442_Content_35 = {
    Text = "Ogni passo di Aram sarà sotto lo sguardo vigile di <Red:Lady Thais>."
  },
  AvgDialog_45442_Content_36 = {
    Text = "Ogni passo di Aram sarà sotto lo sguardo vigile <Red:della Regina>."
  },
  AvgDialog_45442_Content_37 = {
    Text = "Ogni passo di Aram sarà sotto lo sguardo vigile di <Red:@1>."
  },
  AvgDialog_45442_Content_38 = {Text = "..."},
  AvgDialog_45442_Content_39 = {
    Text = "Perché sono qui?"
  },
  AvgDialog_45442_Content_4 = {
    Text = "Finché Aram prospera in pace, quella è ricompensa sufficiente per me, Lady Thais."
  },
  AvgDialog_45442_Content_40 = {
    Text = "Quella bara contiene... già, i Resti dell'Albero Madre."
  },
  AvgDialog_45442_Content_41 = {
    Text = "Perché conserviamo i Resti dell'Albero Madre nella tenda della Regina?"
  },
  AvgDialog_45442_Content_42 = {
    Text = "...Non importa. Non ricordo."
  },
  AvgDialog_45442_Content_43 = {
    Text = "Ma va bene così."
  },
  AvgDialog_45442_Content_44 = {
    Text = "<Big:Quando l'Albero Madre tornerà in vita, <Red:tutto> andrà bene.>"
  },
  AvgDialog_45442_Content_45 = {Text = "..."},
  AvgDialog_45442_Content_46 = {
    Text = "In secoli di servizio, ho addestrato molti successori."
  },
  AvgDialog_45442_Content_47 = {
    Text = "Credevo che un eroe avrebbe portato l'alba ad Aram."
  },
  AvgDialog_45442_Content_48 = {
    Text = "Il primo morì per il morso di un serpente."
  },
  AvgDialog_45442_Content_49 = {
    Text = "Il secondo morì nella tempesta."
  },
  AvgDialog_45442_Content_5 = {
    Text = "Non ti piace nemmeno Aram, vero? Non ti avvicini ai Festini del falò."
  },
  AvgDialog_45442_Content_50 = {
    Text = "Il terzo per la gelosia di qualcun altro."
  },
  AvgDialog_45442_Content_51 = {
    Text = "I pericoli e le insidie del deserto sono infiniti; i più longevi non sono le fiere aquile crestate né le vipere velenose, ma le formiche d'argento attive solo dieci minuti al giorno."
  },
  AvgDialog_45442_Content_52 = {
    Text = "Riporre la speranza in una sola persona è da stolti."
  },
  AvgDialog_45442_Content_53 = {
    Text = "E il nostro numero si stava riducendo troppo in fretta.\nUna sola tempesta imprevista può spazzare via intere squadre."
  },
  AvgDialog_45442_Content_54 = {
    Text = "Nel nostro momento peggiore, gli Aramiti si ridussero a meno di cento."
  },
  AvgDialog_45442_Content_55 = {
    Text = "<Red:Di questo passo, Aram si sarebbe estinta sotto il mio comando.>"
  },
  AvgDialog_45442_Content_56 = {
    Text = "Domani notte... riprenderemo il rito del falò."
  },
  AvgDialog_45442_Content_57 = {
    Text = [[
Al rito, cantavano e bevevano liberamente.
All'alba, innumerevoli neonati erano venuti al mondo durante la notte.]]
  },
  AvgDialog_45442_Content_58 = {
    Text = "Stringendo un neonato in lacrime, le lacrime mi salirono agli occhi."
  },
  AvgDialog_45442_Content_59 = {
    Text = "La grazia dell'Albero Madre era un Miracolo divino per Aram — e io l'avevo liquidata come Eresia, dalla mia visione ristretta."
  },
  AvgDialog_45442_Content_6 = {
    Text = "Inutile negarlo—è evidente.\nQuesto posto è pieno di festaioli sfrenati; tu non c'entri nulla."
  },
  AvgDialog_45442_Content_60 = {Text = "Ma..."},
  AvgDialog_45442_Content_61 = {
    Text = "Il Potere dell'Albero Madre stava svanendo."
  },
  AvgDialog_45442_Content_62 = {
    Text = "Le deformità tra gli Infanti aumentavano."
  },
  AvgDialog_45442_Content_63 = {
    Text = "Mi arrabattai finché un'anziana donna non menzionò—"
  },
  AvgDialog_45442_Content_64 = {
    Text = "Ricordi quell'inno?"
  },
  AvgDialog_45442_Content_65 = {
    Text = "La morte si avvicina. La Dissoluzione albeggia."
  },
  AvgDialog_45442_Content_66 = {
    Text = "Le Spoglie della Madre svaniscono, sangue e seme vagano per la Terra, divorati da bestie appena nate."
  },
  AvgDialog_45442_Content_67 = {
    Text = "Cieli e dèi si ammantano di tenebra, finché giunge l'inviato straniero."
  },
  AvgDialog_45442_Content_68 = {
    Text = [[
L'Albero Madre risorge: le sue radici bevono a fondo il fluire del Fiume sacro.
Incorona di luce i caduti e richiama il loro sangue a quello di Aram.]]
  },
  AvgDialog_45442_Content_69 = {
    Text = "Trova l'<Yellow:Inviato Straniero>, e potremmo assistere alla Rinascita dalla Terra dell'Albero Madre!"
  },
  AvgDialog_45442_Content_7 = {
    Text = "Ma vivere unicamente per il dovere — non ti sembra soffocante?"
  },
  AvgDialog_45442_Content_70 = {
    Text = "Thais, Thais!"
  },
  AvgDialog_45442_Content_71 = {
    Text = "Lo sento. Sento qualcuno che invoca il nome di una certa persona."
  },
  AvgDialog_45442_Content_72 = {
    Text = "La testa mi si spacca. Innumerevoli aghi d'Argento mi trafiggono il cervello, un rumore stridulo mi lacera le orecchie, e il sangue mi rimbomba udibilmente nelle vene."
  },
  AvgDialog_45442_Content_73 = {
    Text = "<Big:THAIS! THAIS—!>"
  },
  AvgDialog_45442_Content_74 = {
    Text = "Thais. Chi è?"
  },
  AvgDialog_45442_Content_75 = {
    Text = "Ignora quelle distrazioni — non faranno che annebbiare la tua concentrazione."
  },
  AvgDialog_45442_Content_76 = {
    Text = "L'Albero Madre è prossimo al suo Ritorno. Non ti riempie di gioia?"
  },
  AvgDialog_45442_Content_77 = {
    Text = "Thais — ho sicuramente sentito quel nome da qualche parte."
  },
  AvgDialog_45442_Content_78 = {Text = "Ma dove?"},
  AvgDialog_45442_Content_79 = {
    Text = "È stato sui campi di battaglia, quando ero vivo e in carne e ossa? Ricordo i sorrisi morenti dei miei compagni, le fredde risposte del comandante...\nNo. Non allora."
  },
  AvgDialog_45442_Content_8 = {
    Text = [[
Lady Thais, lo sapete bene.
In vita ero un soldato. I soldati eseguono gli ordini.]]
  },
  AvgDialog_45442_Content_80 = {
    Text = "Fatiche, Festini, difese dalle bestie dopo il mio Risveglio..."
  },
  AvgDialog_45442_Content_81 = {
    Text = "Dopo il mio Risveglio...?"
  },
  AvgDialog_45442_Content_82 = {
    Text = "Chi mi ha Risvegliato?"
  },
  AvgDialog_45442_Content_83 = {Text = "..."},
  AvgDialog_45442_Content_84 = {
    Text = "<Red:Thais.>"
  },
  AvgDialog_45442_Content_85 = {
    Text = "Perché ho dimenticato il suo nome?"
  },
  AvgDialog_45442_Content_86 = {
    Text = "La chiamavo ogni giorno, ancora e ancora..."
  },
  AvgDialog_45442_Content_87 = {
    Text = "Nel mezzo della tempesta di sabbia infuriante, finalmente scorgo la persona che ho tanto agognato."
  },
  AvgDialog_45442_Content_88 = {
    Text = "Ogni passo si incide a fondo nella Terra consumata dal vento, sollevando onde di lacrime nel mio petto."
  },
  AvgDialog_45442_Content_89 = {
    Text = "Lady Thais..."
  },
  AvgDialog_45442_Content_9 = {
    Text = "Sei il mio tramite.\nProteggere Aram è il tuo desiderio—e quindi il mio."
  },
  AvgDialog_45442_Content_90 = {
    Text = [[
Ti stavo aspettando.
Sapevo che saresti tornato. Sapevo che non avevi mai abbandonato Aram.]]
  },
  AvgDialog_45442_Content_91 = {
    Text = "Aramiti, ascoltatemi! L'antica Profezia si è compiuta! L'Albero Madre fa Ritorno, incoronando il Defunto!"
  },
  AvgDialog_45442_Content_92 = {
    Text = "La Regina cammina di nuovo sulle sabbie, reclamando il suo Trono!"
  },
  AvgDialog_45442_Content_93 = {
    Text = "L'unica vera Regina di Aram, Lady Thais —"
  },
  AvgDialog_45442_Content_94 = {
    Text = "avrà la vostra volontà e la vostra Lealtà!"
  },
  AvgDialog_45442_Content_95 = {
    Text = "Finalmente, finalmente. Ho sopportato fino a questo momento."
  },
  AvgDialog_45442_Content_96 = {
    Text = "Quindi, per favore... Mi loderete ora, mia Regina?"
  },
  AvgDialog_45442_Content_97 = {
    Text = "Lodami per i secoli di moderazione, per la mia perseveranza senza fine, per aver finalmente trovato l'inviato che porta la tua Rinascita dalla Terra..."
  },
  AvgDialog_45442_Content_98 = {
    Text = "Insieme, faremo di Aram un'utopia senza spargimento di sangue né lacrime, un Paradise perfetto."
  },
  AvgDialog_45442_Content_99 = {
    Text = "Ah, Lady Thais. Perché scuotete il capo verso di me?"
  },
  AvgDialog_45443_Content_1 = {Text = "Ritorno"},
  AvgDialog_45443_Content_10 = {
    Text = "Ora sei solo, hai bisogno di un alleato. Ricordi il volto di Thais."
  },
  AvgDialog_45443_Content_11 = {
    Text = "Tutto ciò che devi fare è fidarti completamente di me.\nTi fiderai della Regina di Aram."
  },
  AvgDialog_45443_Content_12 = {
    Text = "E sai che lei ricambierà con la stessa fiducia."
  },
  AvgDialog_45443_Content_13 = {
    Text = "Thais? Chi?"
  },
  AvgDialog_45443_Content_14 = {
    Text = "Chi altri? Thais, la vostra Regina!"
  },
  AvgDialog_45443_Content_15 = {
    Text = "Sei fuori di testa? Vuoi vedere la Regina? Allora tagliati la gola con questa lama!"
  },
  AvgDialog_45443_Content_16 = {
    Text = "La Regina... cosa le è successo?"
  },
  AvgDialog_45443_Content_17 = {
    Text = "\"Che è successo?\" Sua Maestà è morta da secoli — continua a mancarle di rispetto, e morirai anche tu!"
  },
  AvgDialog_45443_Content_18 = {
    Text = "La sua espressione seria ti gela fino al midollo."
  },
  AvgDialog_45443_Content_19 = {Text = "..."},
  AvgDialog_45443_Content_2 = {
    Text = "Quasi un migliaio di Aramiti si radunano presso il Fiume sacro, le loro cantilene sommesse si propagano in onde, intrecciandosi in una sinfonia caotica con gli ululati lontani delle bestie."
  },
  AvgDialog_45443_Content_20 = {
    Text = "Fissi il cuore del Rito in lontananza."
  },
  AvgDialog_45443_Content_21 = {
    Text = [[
La bara riposa quieta sull'alto telaio dell'altare.
Naturalmente, nessuna traccia della Thais che conosci.]]
  },
  AvgDialog_45443_Content_22 = {
    Text = "Non solo lì.\nNon c'è traccia di lei da nessuna parte."
  },
  AvgDialog_45443_Content_23 = {
    Text = "Il lembo della tenda si scosta e una donna aramita dall'aria severa, sulla trentacinquina, entra a passo deciso."
  },
  AvgDialog_45443_Content_24 = {
    Text = "Thais si arrampica di nuovo in cima al feretro, assumendo una posa regale come un Sovrano altero sul suo Trono."
  },
  AvgDialog_45443_Content_25 = {
    Text = "Oh, nostro stimato ospite..."
  },
  AvgDialog_45443_Content_26 = {
    Text = "<Red:La voce cristallina dell'intruso tronca bruscamente il suo tono affettato.>"
  },
  AvgDialog_45443_Content_27 = {
    Text = "Avresti dovuto saperlo. Alva non interromperebbe mai il discorso della sua Regina... <Red:Se potesse sentire Thais parlare.>"
  },
  AvgDialog_45443_Content_28 = {
    Text = "L'inviata! La carovana dell'inviata è tornata!"
  },
  AvgDialog_45443_Content_29 = {
    Text = "Gli Abitanti del villaggio intasano i vicoli stretti, levando in alto nelle mani i Tributi per Juliette."
  },
  AvgDialog_45443_Content_3 = {
    Text = "Un imponente altare di legno si erge in mezzo alla folla, la bara incisa con simboli criptici esposta sulla sua sommità, circondata da sguardi colmi di paura, fervore e attesa."
  },
  AvgDialog_45443_Content_30 = {
    Text = "In coda al corteo, Thais se ne stava sdraiata sopra una bara portata da quattro Guerrieri di Aram."
  },
  AvgDialog_45443_Content_31 = {
    Text = "Rispetto alla fragorosa accoglienza riservata a Juliette, <Red:i radi Applausi ricevuti da Thais rendono il suo titolo di Regina un'eco vuota.>"
  },
  AvgDialog_45443_Content_32 = {
    Text = "Il popolo di Aram non vedeva la propria Regina seduta sulla bara."
  },
  AvgDialog_45443_Content_33 = {
    Text = "Potresti comprarmi questo?"
  },
  AvgDialog_45443_Content_34 = {
    Text = "Il tuo sguardo segue il suo dito fino a un collare di metallo."
  },
  AvgDialog_45443_Content_35 = {
    Text = "Occhio acuto, {Male=signore,Female=signorina}! Volete vederlo da vicino?"
  },
  AvgDialog_45443_Content_36 = {
    Text = "È opera di mia figlia! Ha scelto lei stessa i materiali. Quel lapislazzuli al centro? Tessitura uniforme, tonalità intensa, si riconosce la qualità!"
  },
  AvgDialog_45443_Content_37 = {
    Text = "Niente lapislazzuli."
  },
  AvgDialog_45443_Content_38 = {
    Text = "Niente lapislazzuli?"
  },
  AvgDialog_45443_Content_39 = {
    Text = "Eh? Sei sicuro di non volerlo?"
  },
  AvgDialog_45443_Content_4 = {
    Text = "Nel momento in cui metti piede all'interno, ti imbatti in una dura resistenza."
  },
  AvgDialog_45443_Content_40 = {
    Text = "Aggiungendo quel lapislazzuli, i fondi che Mythag ti ha affidato saranno ridotti all'osso."
  },
  AvgDialog_45443_Content_41 = {
    Text = "Sì, lascia perdere il lapislazzuli."
  },
  AvgDialog_45443_Content_42 = {
    Text = "Certo. Lo impacchetto per <Red:te.>"
  },
  AvgDialog_45443_Content_43 = {
    Text = "Il Mercante stava solo rispondendo alle tue parole."
  },
  AvgDialog_45443_Content_44 = {
    Text = "Finalmente, scorgi una figura familiare su una duna."
  },
  AvgDialog_45443_Content_45 = {
    Text = "Riconosci la sagoma. È Thais."
  },
  AvgDialog_45443_Content_46 = {
    Text = "La tempesta... si sta placando?"
  },
  AvgDialog_45443_Content_47 = {
    Text = "Con il vento ululante che le sferza i veli, intona una Preghiera sconosciuta, avanzando lenta e sicura nella scura tempesta di sabbia."
  },
  AvgDialog_45443_Content_48 = {
    Text = "Il rombo assordante toglie l'udito, eppure la Preghiera lo trafigge nitida, echeggiando dentro il vostro cranio."
  },
  AvgDialog_45443_Content_49 = {
    Text = "Nella bufera che divora il cielo, conversa con calma con un'entità in agguato tra le sabbie del deserto."
  },
  AvgDialog_45443_Content_5 = {
    Text = "Chi va là!"
  },
  AvgDialog_45443_Content_50 = {
    Text = "È la Regina! È venuta a salvarci... a salvare Aram!"
  },
  AvgDialog_45443_Content_51 = {
    Text = "Il gruppo di Aram, frenetico nella Fuga solo un istante prima, si arresta all'improvviso."
  },
  AvgDialog_45443_Content_52 = {
    Text = "Innumerevoli Aramiti si volgono verso Thais, inginocchiandosi in solenne Devozione."
  },
  AvgDialog_45443_Content_53 = {
    Text = "Ma si stanno inginocchiando verso il vuoto... Solo tu puoi vedere l'abito di Thais svolazzare nel vento sabbioso."
  },
  AvgDialog_45443_Content_54 = {
    Text = "In quanto ricettacolo dell'Eone del Desiderio, l'Albero Madre deve aver lasciato un segno profondo sul Pianeta."
  },
  AvgDialog_45443_Content_55 = {
    Text = "La sua tenace vitalità rallenta l'erosione della Dissoluzione di mille volte."
  },
  AvgDialog_45443_Content_56 = {
    Text = "Quindi, <Red:per te, lei non è ancora del tutto svanita.>"
  },
  AvgDialog_45443_Content_57 = {
    Text = "Dategli un altro paio di secoli, <Red:e gli Aramiti probabilmente dimenticheranno che l'Albero Madre sia mai esistito.>"
  },
  AvgDialog_45443_Content_58 = {Text = "..."},
  AvgDialog_45443_Content_59 = {
    Text = "Non hanno mai visto una Regina di nome Thais; ciò che venerano, davanti a cui si inginocchiano, è solo un sentito dire—un fantasma vuoto."
  },
  AvgDialog_45443_Content_6 = {
    Text = "Questo è il momento cruciale del rito — nessun estraneo è ammesso!"
  },
  AvgDialog_45443_Content_60 = {
    Text = "La Thais che ti ha fatto da guida, ha danzato per te e si è messa in posa sulla bara <Red:non è mai esistita ai loro occhi>."
  },
  AvgDialog_45443_Content_61 = {
    Text = "Ma tu sei certo, assolutamente certo che lei esista."
  },
  AvgDialog_45443_Content_62 = {
    Text = "Ricordi quelle memorie al chiaro di luna."
  },
  AvgDialog_45443_Content_63 = {
    Text = "Ricordi il Calore Residuo sulla punta delle dita."
  },
  AvgDialog_45443_Content_64 = {
    Text = "Ricordi i suoi dolci sussurri."
  },
  AvgDialog_45443_Content_65 = {
    Text = "Lo sapevi? Nei tuoi occhi vedo calamità, braci dei giorni passati, il respiro del cosmo."
  },
  AvgDialog_45443_Content_66 = {
    Text = "Il viaggio ti ha consumato, non è vero? Eppure il tuo sguardo resta saldo, incontaminato."
  },
  AvgDialog_45443_Content_67 = {
    Text = "Le Stelle distorte non hanno potuto piegarti; le sabbie del deserto forse nemmeno."
  },
  AvgDialog_45443_Content_68 = {
    Text = "Il suo respiro si mescola al tuo.\nMari di stelle ardono nelle sue profondità."
  },
  AvgDialog_45443_Content_69 = {
    Text = "Devo porre fine al rito aramita."
  },
  AvgDialog_45443_Content_7 = {
    Text = "Devo vedere Thais!"
  },
  AvgDialog_45443_Content_70 = {
    Text = "Thais... deve essere là ad aspettarmi."
  },
  AvgDialog_45443_Content_8 = {
    Text = "Non fraintenderai gli indizi che William ti ha lasciato: Nubia, il falso inviato, la contaminazione dell'Albero Madre... tutto punta agli intrighi della Chiesa del Portatore di Luce."
  },
  AvgDialog_45443_Content_9 = {
    Text = "Ramona, William, Ryker... nessuno dei tuoi compagni Mythag è al tuo fianco."
  },
  AvgDialog_45444_Content_1 = {
    Text = "Sotto l'Albero Madre, Alva si inginocchia in lacrime, impotente."
  },
  AvgDialog_45444_Content_10 = {
    Text = "Solo attraverso strette fessure potevo intravedere la luce dall'altro mondo."
  },
  AvgDialog_45444_Content_11 = {
    Text = "In quegli spiragli fugaci, ho seguito il cammino nomade di Aram."
  },
  AvgDialog_45444_Content_12 = {
    Text = "Ho assistito alla tua Determinazione di assumerti il peso della guida nel Caos."
  },
  AvgDialog_45444_Content_13 = {
    Text = "Ho assistito alla tua volontà di abolire il rito del falò, alla tua Agonia per la fine prematura di quei successori, alla tua riluttanza nel ripristinare il rito."
  },
  AvgDialog_45444_Content_14 = {
    Text = "Ho assistito ai tuoi sforzi per procurare acqua e provviste, alle tue estenuanti resistenze contro orde di bestie."
  },
  AvgDialog_45444_Content_15 = {
    Text = "Alva, hai fatto bene."
  },
  AvgDialog_45444_Content_16 = {
    Text = "Nemmeno io avrei potuto fare di meglio."
  },
  AvgDialog_45444_Content_17 = {
    Text = "Lascia il resto a me."
  },
  AvgDialog_45444_Content_18 = {
    Text = "Thais accarezza il capo di Alva, poi si volta ad affrontare gli innumerevoli soldati aramiti."
  },
  AvgDialog_45444_Content_19 = {
    Text = "Io sono la Madre della Terra, l'Emissario dell'Eone del Desiderio."
  },
  AvgDialog_45444_Content_2 = {
    Text = "Mia Signora... ho... fallito... Aram..."
  },
  AvgDialog_45444_Content_20 = {
    Text = "Io sono Thais. Udite il mio nome sacro: <Yellow:Tifere Yesod>."
  },
  AvgDialog_45444_Content_21 = {
    Text = "In nome dell'unica vera Regina di Aram, ti sfido — Divoratore di vita, seminatore di morte, falso Albero Madre."
  },
  AvgDialog_45444_Content_22 = {
    Text = "Dalle tue profondità, libererò il popolo di Aram, forgiando il loro cammino verso la sopravvivenza."
  },
  AvgDialog_45444_Content_23 = {
    Text = "Fanciulli di Aram—se potete ancora udirmi, risvegliatevi!"
  },
  AvgDialog_45444_Content_24 = {
    Text = "Il mondo si congela per un istante."
  },
  AvgDialog_45444_Content_25 = {
    Text = "Eppure pochi istanti dopo, le schiere di Aram riprendono a gettarsi nel Fiume sacro come lemming instancabili e incuranti."
  },
  AvgDialog_45444_Content_26 = {
    Text = "Inutile. Tu e l'Albero Madre condividete le stesse radici, entrambi corrotti dalla Sua volontà. Nel tuo Stato, non puoi scalfire la Determinazione dell'Albero Madre corrotto."
  },
  AvgDialog_45444_Content_27 = {
    Text = "Certo che lo so."
  },
  AvgDialog_45444_Content_28 = {
    Text = "Senza quello, perché secoli di peregrinazione?"
  },
  AvgDialog_45444_Content_29 = {
    Text = "Ho celato la forma dell'Albero Madre nel Fiume sacro, ho portato la Dissoluzione nella mia carne per occultarne il seme — non era forse tutto per questo momento?"
  },
  AvgDialog_45444_Content_3 = {
    Text = "Non preoccuparti. Ti ascolto, Alva."
  },
  AvgDialog_45444_Content_30 = {
    Text = "Il momento è giunto!"
  },
  AvgDialog_45444_Content_31 = {
    Text = "In nome di Tifere Yesod, Eone del Desiderio, invoco <Yellow:Tawil> — onora il nostro patto millenario."
  },
  AvgDialog_45444_Content_32 = {
    Text = "Quando il messaggero Da Lontano giungerà, usa il tuo avatar come Guida per dissipare temporaneamente le Ombre su Lemoah per me."
  },
  AvgDialog_45444_Content_33 = {
    Text = "Un lamento lacerante riecheggia nel cielo."
  },
  AvgDialog_45444_Content_34 = {
    Text = "Thais apre la bara; all'interno, Ramona, arrossata dalla febbre, rotola fuori."
  },
  AvgDialog_45444_Content_35 = {
    Text = "Finalmente... Il mio momento è giunto..."
  },
  AvgDialog_45444_Content_36 = {
    Text = "Nascondersi qui dentro per venire di nascosto... furba, ragazza."
  },
  AvgDialog_45444_Content_37 = {
    Text = "Meno male che l'hai fatto. Tornare là fuori a cercarti ci sarebbe costato tempo prezioso e innumerevoli vite."
  },
  AvgDialog_45444_Content_38 = {
    Text = "La voce nella mia testa... mi diceva... che dovevo resistere..."
  },
  AvgDialog_45444_Content_39 = {
    Text = "Ma anche senza di lei...\nSono l'assistente di %player%—nei momenti più disperati, devo essere al fianco di {Male=his,Female=her}."
  },
  AvgDialog_45444_Content_4 = {
    Text = "Perché nessuno comprende il dolore di non essere ascoltati meglio di me."
  },
  AvgDialog_45444_Content_40 = {
    Text = "È il mio dovere in quanto loro unica e sola, giusto?"
  },
  AvgDialog_45444_Content_41 = {
    Text = "Calca con forza su <Bold:unica e sola.>"
  },
  AvgDialog_45444_Content_42 = {
    Text = "Risvegliare il Loro Potere su questa terra intensifica lo sforzo sul tuo corpo."
  },
  AvgDialog_45444_Content_43 = {
    Text = "Non ricorrerei a questo se restasse un'altra via."
  },
  AvgDialog_45444_Content_44 = {
    Text = "Siamo venuti qui per fermare il Rito, e porterò tutto questo a compimento fino alla fine!"
  },
  AvgDialog_45444_Content_45 = {
    Text = "Bene! Ramona, Soppressione dell'Eone del Desiderio—%player% e io distruggeremo l'Albero Madre!"
  },
  AvgDialog_45444_Content_46 = {
    Text = "Un lamento assordante squarcia il cielo; fantasmi d'Argento sfreciano attraverso le alture del deserto."
  },
  AvgDialog_45444_Content_47 = {Text = "—"},
  AvgDialog_45444_Content_48 = {
    Text = "Il tuo corpo si fa leggero; un istante dopo, vieni scaraventato davanti a un tumore fetido e nauseabondo."
  },
  AvgDialog_45444_Content_49 = {
    Text = "Gli Aramiti divorati dall'Albero Madre si ammassano qui in forme simili a uova; pori traslucidi rivelano volti contorti e sfocati, melma rosso-nera sgorga senza sosta dai fori, alimentando il Fiume sacro un tempo limpido."
  },
  AvgDialog_45444_Content_5 = {
    Text = "Ho seguito la carovana di Aram, vagando per secoli."
  },
  AvgDialog_45444_Content_6 = {
    Text = "Nessuno mi ha vista. Nessuno mi ha sentita."
  },
  AvgDialog_45444_Content_7 = {
    Text = "Un tempo ero la danzatrice più bella delle feste, la Regina più amata di Aram.\nMa le mie danze restavano invisibili, i miei decreti inascoltati."
  },
  AvgDialog_45444_Content_8 = {
    Text = "Nella Dissoluzione si celava un altro mondo."
  },
  AvgDialog_45444_Content_9 = {
    Text = "Nero pece, senza vita, disperante."
  },
  AvgDialog_46539_Content_1 = {
    Text = "Dopo un anno di addestramento e le recenti indagini sul campo, ora sei qualificato per gli addestramenti Traphase."
  },
  AvgDialog_46539_Content_10 = {
    Text = "Naturalmente, le battaglie sono combattute dai Risvegliati—sebbene durante il Traphase, alcune entità subiranno una <Yellow:distorsione> dei confini fisici."
  },
  AvgDialog_46539_Content_11 = {
    Text = "<Yellow:Le abilità di combattimento dei Risvegliati>, <Yellow:le Barriere del Reame> e persino <Yellow:le Regole di Battaglia> differiscono enormemente dalla realtà."
  },
  AvgDialog_46539_Content_12 = {
    Text = "I <Yellow:progressi di sviluppo> dei tuoi Risvegliati andranno perduti, ma <Yellow:lo stesso vale per il tuo avversario>. In un certo senso, si può dire che il \"Traphase\" sia un <Yellow:duello equo>."
  },
  AvgDialog_46539_Content_13 = {
    Text = "Attiva il dispositivo Traphase e sfida te stesso in battaglia. Tutte le domande troveranno risposta attraverso il combattimento. Che la Chiave d'Argento Illumini il Cammino."
  },
  AvgDialog_46539_Content_2 = {
    Text = "A proposito, hai mai sentito parlare del \"Traphase\"?"
  },
  AvgDialog_46539_Content_3 = {
    Text = "Ne so qualcosa."
  },
  AvgDialog_46539_Content_4 = {
    Text = "Molto bene, ma secondo il regolamento della scuola, devo fornirti una spiegazione più esaustiva dei rischi e delle regole."
  },
  AvgDialog_46539_Content_5 = {
    Text = "Non ne ho mai sentito parlare."
  },
  AvgDialog_46539_Content_6 = {
    Text = "Allora comincerò dall'inizio e ti spiegherò tutto."
  },
  AvgDialog_46539_Content_7 = {
    Text = "Nelle nostre ricerche sulla sostanza denominata Argento, abbiamo scoperto che le onde vibratorie prodotte dall'Argento durante l'oscillazione possono occasionalmente oltrepassare i confini fisici. Ci riferiamo al luogo in cui si manifestano queste onde vibratorie come <Yellow:Fasi>."
  },
  AvgDialog_46539_Content_8 = {
    Text = "E il \"Traphase\" è un metodo di addestramento specializzato che utilizza le fasi per ingaggiare <Yellow:battaglie simulate> con te stesso proveniente da un'altra dimensione, ottenendo così l'effetto di migliorare lo spirito e la consapevolezza in battaglia."
  },
  AvgDialog_46539_Content_9 = {
    Text = "Me stessa da un'altra dimensione..."
  },
  AvgDialog_46700_Content_1 = {
    Text = "Indice di Gnosi 89,8, Frequenza di Marea 762Hz, ancora in salita..."
  },
  AvgDialog_46700_Content_2 = {
    Text = "\"È la <Yellow:D-marea>, senza dubbio. Tutti i reparti, ai posti. Squadra di monitoraggio, riportate l'Indice di Gnosi in tempo reale. Squadra Strategia, elaborate i piani di emergenza immediatamente. Squadra operativa, il Dominio Artificiale è attivo—preparatevi a infiltrare la Zona D-Effetto attraverso la dimensione spirituale."
  },
  AvgDialog_46700_Content_3 = {Text = "D-marea?"},
  AvgDialog_46700_Content_4 = {
    Text = "Le ondate periodiche nella dimensione della coscienza all'interno della Pozza nera, influenzate dalle forze di marea, potrebbero scatenare gravi disastri nelle <Yellow:Zone D-Effetto regionali> collegate se non gestite adeguatamente."
  },
  AvgDialog_46700_Content_5 = {
    Text = "L'anomalia fluttuante menzionata da Lady Czort durante la cerimonia di conferimento della chiave è un segno dell'esplosione della D-marea."
  },
  AvgDialog_46700_Content_6 = {
    Text = "Maree mentali sconosciute destabilizzano il Dominio. L'ambiente all'interno delle Zone D-Effetto muta rapidamente. <Yellow:Risvegliati e nemici saranno ugualmente colpiti>..."
  },
  AvgDialog_46700_Content_7 = {
    Text = "Le spiegazioni possiamo lasciarle per dopo, a lezione. La prima ondata di D-marea è qui. Concentratevi e combattete!"
  },
  AvgDialog_46700_Content_8 = {
    Text = "Possa la Chiave d'Argento guidarvi tutti."
  },
  AvgDialog_46733_Content_1 = {
    Text = "Anche se è solo un'altra notte ordinaria sul campo, ti senti sempre a disagio a dormire quando sei lontano dalla scuola."
  },
  AvgDialog_46733_Content_10 = {
    Text = "Ogier, non ti senti bene?"
  },
  AvgDialog_46733_Content_11 = {
    Text = "Mio signore, io... io non... Sono stati loro..."
  },
  AvgDialog_46733_Content_12 = {
    Text = "Ogier si sforza di sollevare gli incontrollabili Formless Spawn intorno a lui. Quello che un tempo aleggiava attorno a lui come il suo potere diventa ora insolitamente attivo—"
  },
  AvgDialog_46733_Content_13 = {Text = "Slurp."},
  AvgDialog_46733_Content_14 = {
    Text = "Abbastanza attivo che, quando ti avvicini per dare un'occhiata, ti \"leccano\" il viso come la lingua di un gatto."
  },
  AvgDialog_46733_Content_15 = {
    Text = "Mio Signore—?!"
  },
  AvgDialog_46733_Content_16 = {
    Text = "Io... non intendevo..."
  },
  AvgDialog_46733_Content_17 = {
    Text = "Spingi via il Formless Spawn che ti si struscia addosso come un gatto, le tue dita affondano nei morbidi capelli dorati di Ogier e li accarezzano dolcemente."
  },
  AvgDialog_46733_Content_18 = {
    Text = "Va tutto bene, prenditi il tuo tempo."
  },
  AvgDialog_46733_Content_19 = {
    Text = "Io... non so perché, ma oggi desidero disperatamente restare al vostro fianco. Questo sentimento è così forte che persino i Formless Spawn sfuggono al mio controllo..."
  },
  AvgDialog_46733_Content_2 = {
    Text = "I suoni del mondo diventano particolarmente intensi nell'oscurità, specialmente quei respiri giovani eppure pesanti—"
  },
  AvgDialog_46733_Content_20 = {
    Text = "<Small:Potrebbe essere l'influenza del Fiume sacro e dell'Albero Madre?>"
  },
  AvgDialog_46733_Content_21 = {
    Text = "Se vi ho disturbato, mio signore..."
  },
  AvgDialog_46733_Content_22 = {
    Text = "Non fa niente."
  },
  AvgDialog_46733_Content_23 = {
    Text = "D-Davvero?!"
  },
  AvgDialog_46733_Content_24 = {
    Text = "Trascini Ogier nella stanza, lo spingi con forza sul letto, poi trascini una sedia per sederti accanto al capezzale."
  },
  AvgDialog_46733_Content_25 = {
    Text = "Resta con me stanotte. Così potrai dormire come si deve."
  },
  AvgDialog_46733_Content_26 = {
    Text = "Come potrei passare la notte nel letto del mio signore? Non è decoroso—"
  },
  AvgDialog_46733_Content_27 = {
    Text = "Avvolgi Ogier in una coperta, e lui si dimena come un bruco finché non gli posi la mano sulla fronte."
  },
  AvgDialog_46733_Content_28 = {
    Text = "Dormi, dormi..."
  },
  AvgDialog_46733_Content_29 = {
    Text = "Non hai ascoltato molte ninne nanne, e la melodia che canticchi inconsciamente ora è solo una delle tante inquietanti filastrocche di Londinium."
  },
  AvgDialog_46733_Content_3 = {
    Text = "Ancora sveglio, Ogier? Abbiamo ancora compiti d'indagine che ci attendono dopo l'alba."
  },
  AvgDialog_46733_Content_30 = {
    Text = "Ma gli occhi luminosi di Ogier si fanno gradualmente più oscuri, come la stella della sera che sprofonda nella nebbia prima dell'alba."
  },
  AvgDialog_46733_Content_31 = {
    Text = "Zzz... M-Mio Signore..."
  },
  AvgDialog_46733_Content_32 = {
    Text = "Resti a lungo accanto al suo letto, osservandolo finché il suo respiro non si fa regolare e le stelle fuori si affievoliscono. Solo allora sfiori delicatamente le ciocche ribelli sulla sua fronte e esci dalla stanza in punta di piedi."
  },
  AvgDialog_46733_Content_33 = {
    Text = "Dormi bene, buona creatura."
  },
  AvgDialog_46733_Content_4 = {
    Text = "M-mio signore! Ogier non intende disturbare il vostro riposo. È solo... è solo..."
  },
  AvgDialog_46733_Content_5 = {
    Text = "Ogier impugna la sua arma, appoggiato al corridoio, montando la guardia fuori dalla tua porta come una scultura di cavaliere."
  },
  AvgDialog_46733_Content_6 = {
    Text = "Non sai da quanto tempo sia rimasto stupidamente in piedi nel corridoio. Quando apri la porta, istintivamente cerca di salutarti ma barcolla debolmente."
  },
  AvgDialog_46733_Content_7 = {
    Text = "—Attento!"
  },
  AvgDialog_46733_Content_8 = {
    Text = "Sorreggi il ragazzo che quasi inciampa, ma questo non fa che agitare ancora di più Ogier."
  },
  AvgDialog_46733_Content_9 = {
    Text = "Il suo volto avvampa, e armeggia goffamente, come se cercasse di contenere un traboccamento invisibile e al tempo stesso volesse fuggire dal tuo fianco."
  },
  AvgDialog_46734_Content_1 = {
    Text = "Perdonami, Custode, ti prego non guardarmi adesso."
  },
  AvgDialog_46734_Content_10 = {
    Text = "La mano della donna stringe il tuo braccio. Le sue nocche sono lunghe e forti; persino attraverso il tessuto, puoi percepire i sottili calli lasciati da anni di maneggio di armi da fuoco."
  },
  AvgDialog_46734_Content_11 = {
    Text = "Nel corso di questi lunghi anni, mi sono abituata a sopportare l'influenza del Fiume sacro... Sì, Lei è divina e misericordiosa, e assicura la continuità del nostro popolo. Eppure ciò che cerco non si trova nel Suo fervore."
  },
  AvgDialog_46734_Content_12 = {
    Text = "Mentre pronunci un discorso così retto, Alva... le tue azioni non sembrano corrispondere alle parole, vero?!"
  },
  AvgDialog_46734_Content_13 = {
    Text = "Quello che intendo è che sono perfettamente calma in questo momento. Le mie azioni non derivano dal Fiume sacro, né da alcuna forza esterna."
  },
  AvgDialog_46734_Content_14 = {
    Text = "<LightGray:<Italic:(No, sembri tutto fuorché calma.)>>"
  },
  AvgDialog_46734_Content_15 = {
    Text = "\"Sembri\" potrebbe essere impreciso; anche con la vista oscurata, sai che queste azioni non sono certo quelle che la solita Alva compirebbe."
  },
  AvgDialog_46734_Content_16 = {
    Text = "...Ma la diretta interessata chiaramente non è d'accordo."
  },
  AvgDialog_46734_Content_17 = {
    Text = "Perché so già cosa dovrei proteggere e chi dovrei servire per realizzare la visuale a cui aspiro."
  },
  AvgDialog_46734_Content_18 = {
    Text = "Pertanto, mi chiedo — se, proprio adesso, posso scegliere di seguire il mio istinto ed esplorare cose che non ho mai sfiorato prima."
  },
  AvgDialog_46734_Content_19 = {
    Text = "L'esposizione di Alva è straordinariamente ferma, come se stesse semplicemente riferendo su un piano di addestramento."
  },
  AvgDialog_46734_Content_2 = {
    Text = "Alva, sei sicura di stare bene? Non sembri in forma."
  },
  AvgDialog_46734_Content_20 = {
    Text = "Ma il suo battito cardiaco tradisce la sua padrona; quel clamore non può essere facilmente celato, a differenza della luce davanti ai tuoi occhi."
  },
  AvgDialog_46734_Content_21 = {
    Text = "Questa ex devota della Giustizia è chiaramente impegnata in un'altra guerra contro se stessa."
  },
  AvgDialog_46734_Content_22 = {
    Text = "Puoi allontanarmi in qualsiasi momento, o rendermi priva di sensi."
  },
  AvgDialog_46734_Content_23 = {
    Text = "Oppure — guidami."
  },
  AvgDialog_46734_Content_24 = {
    Text = "Sul sentiero di questa Caccia senza fine, ti dedicherò eterna Lealtà..."
  },
  AvgDialog_46734_Content_25 = {
    Text = "Desidero stare sempre di Guardia al tuo fianco."
  },
  AvgDialog_46734_Content_3 = {
    Text = "La voce di questa donna solitamente tenace e irremovibile è ora bassa e tremante. La sua fronte preme contro la parte posteriore della tua testa, la sua mano occultando la tua visuale nell'oscurità totale."
  },
  AvgDialog_46734_Content_4 = {
    Text = "Dopo la sessione di addestramento, Alva è entrata nella tua stanza in modo del tutto insolito, ha sostenuto una sfida di trenta secondi cercando di riprendere fiato, e poi ha distolto con forza il tuo sguardo disorientato."
  },
  AvgDialog_46734_Content_5 = {
    Text = "...Sto pensando, %player%, sto pensando."
  },
  AvgDialog_46734_Content_6 = {
    Text = "Non sai cosa stia pensando, ma la ragione ti dice che, oltre a una singola sillaba di confusione, è meglio non emettere alcun altro suono."
  },
  AvgDialog_46734_Content_7 = {
    Text = "Così fai, e Alva risponde alla tua goffa rigidità con una risata consapevole."
  },
  AvgDialog_46734_Content_8 = {
    Text = "So da dove proviene l'influenza del Fiume sacro, e cosa significa."
  },
  AvgDialog_46734_Content_9 = {
    Text = "Ho servito molti esseri, ma ho sempre perseguito soltanto la Giustizia. Anche se, agli occhi di molti, la cosiddetta Giustizia potrebbe essere solo un'illusione fugace."
  },
  AvgDialog_46735_Content_1 = {
    Text = "Amica! Vieni con me!!"
  },
  AvgDialog_46735_Content_10 = {
    Text = "Nuovi amici! Le ghiandole di Aurita si sono divise in tanti, tantissimi nuovi amici oggi!"
  },
  AvgDialog_46735_Content_11 = {
    Text = "Ride eccitata, rovesciandoti in mano tutte le meduse tossiche in un colpo solo."
  },
  AvgDialog_46735_Content_12 = {
    Text = "Tutti dicono che vogliono stare con te, quindi anche Aurita vuole essere qui!"
  },
  AvgDialog_46735_Content_13 = {
    Text = "<Small:Così tante meduse… per fortuna la mia COS non è così facilmente soggetta ad allergie.>"
  },
  AvgDialog_46735_Content_14 = {
    Text = "<Italic:Eppure, anche se lo fossi, sarei disposto a sopportare qualche iniezione di adrenalina al cuore pur di vedere il sorriso felice di Aurita.>"
  },
  AvgDialog_46735_Content_2 = {
    Text = "<Small:Questa voce... possibile che sia...?>"
  },
  AvgDialog_46735_Content_3 = {
    Text = "Un momento, vado ad aprire la porta—"
  },
  AvgDialog_46735_Content_4 = {
    Text = "L'intruso irrompe nella stanza senza preavviso, sbattendo contro di te con un tonfo pesante."
  },
  AvgDialog_46735_Content_5 = {
    Text = "Barcollando all'indietro cerchi di sostenere la bambina, ma la gravità ha la meglio: cadi a terra con lei tra le braccia, mentre il mondo ti vortica intorno."
  },
  AvgDialog_46735_Content_6 = {Text = "Guardate!"},
  AvgDialog_46735_Content_7 = {
    Text = "Prima ancora che tu riesca a rialzarti, Aurita ti ficca le sue \"mani\" davanti al viso."
  },
  AvgDialog_46735_Content_8 = {
    Text = "Le sue braccia a forma di ombrello sono unite a coppa, e cullano un grappolo di meduse grandi quanto un pollice."
  },
  AvgDialog_46735_Content_9 = {
    Text = "Cosa sono questi?"
  },
  AvgDialog_47150_Content_1 = {
    Text = "<Italic:Tante lacrime stanotte, una visione indimenticabile~>"
  },
  AvgDialog_47150_Content_10 = {
    Text = "La tua ancella avrà sicuramente preparato del tè per smaltire la sbornia. Vuoi che vada a prenderlo?"
  },
  AvgDialog_47150_Content_11 = {Text = "Non—"},
  AvgDialog_47150_Content_12 = {
    Text = "Sorel ti tira per il braccio, e insieme cadete sulla morbida chaise longue. Persino in quello scompiglio, il calice nella sua mano resta perfettamente stabile."
  },
  AvgDialog_47150_Content_13 = {
    Text = "La tenuta è avvolta nell'oscurità; solo il liquore dorato nel suo bicchiere rifrange la luce lunare, proiettando un bagliore tenue e intimo tra voi."
  },
  AvgDialog_47150_Content_14 = {
    Text = "Non sono ubriaca. Non ho bisogno di tè per rinsavire."
  },
  AvgDialog_47150_Content_15 = {
    Text = "Il mio salone... non è mai stato così silenzioso, eppure mi dona una pace così profonda."
  },
  AvgDialog_47150_Content_16 = {
    Text = "A ogni grande ricevimento in passato, contavo sempre mentalmente i miei ospiti: quelli che avevano accettato il mio invito, quelli che si erano comprati l'ingresso, quelli che si erano intrufolati... Mi assicuravo di ricordare ogni volto."
  },
  AvgDialog_47150_Content_17 = {
    Text = "Se qualcuno accettava l'invito ma non si presentava, ricordavo anche quello... Quelle persone dovevano custodire segreti che non avevo ancora colto."
  },
  AvgDialog_47150_Content_18 = {
    Text = "Non posso fare a meno di sentirmi inquieta per queste minacce celate, ansiosa per un futuro che non riesco a controllare..."
  },
  AvgDialog_47150_Content_19 = {
    Text = "Mentre parla, ti solleva il mento con un solo dito, impedendo al tuo sguardo di vagare altrove."
  },
  AvgDialog_47150_Content_2 = {
    Text = "Lady Sorel? Karen mi ha riferito che volevate vedermi?"
  },
  AvgDialog_47150_Content_20 = {
    Text = "Ma riguardo al \"te\" sconosciuto, provo soltanto curiosità."
  },
  AvgDialog_47150_Content_21 = {
    Text = "Forse... tu e io possiamo coltivare insieme il bocciolo più splendido, più tenace."
  },
  AvgDialog_47150_Content_22 = {
    Text = "E restare fianco a fianco... dove nessun altro potrà mai arrivare..."
  },
  AvgDialog_47150_Content_23 = {Text = "Phew..."},
  AvgDialog_47150_Content_24 = {
    Text = "Le sue parole si spengono incompiute. Il suo corpo si abbandona, tutto il suo peso che si adagia dolcemente sul tuo."
  },
  AvgDialog_47150_Content_25 = {
    Text = "Il calice le scivola dalle dita e rotola sul pavimento di marmo, il liquore si insinua all'istante nelle fughe delle piastrelle. Il suo respiro profumato di vino, morbido e inebriante, inonda silenziosamente la tua mente ormai quasi dissolta."
  },
  AvgDialog_47150_Content_3 = {
    Text = "Ah... mio piccolo Custode, sei qui."
  },
  AvgDialog_47150_Content_4 = {
    Text = "P-Piccolo Custode?"
  },
  AvgDialog_47150_Content_5 = {
    Text = "Prima che tu possa reagire, Sorel porta un calice di vino alle tue labbra."
  },
  AvgDialog_47150_Content_6 = {
    Text = "Mentre si avvicina, un aroma inebriante di vino si leva dalle punte dei suoi capelli e dall'orlo del suo abito. Spiriti inebrianti mescolati a fiori e frutti, trasportati dal suo respiro caldo."
  },
  AvgDialog_47150_Content_7 = {
    Text = "Lady Sorel, siete ubriaca di nuovo."
  },
  AvgDialog_47150_Content_8 = {
    Text = "Ubriaca? Forse. Suppongo di essere in effetti un po' alticcia."
  },
  AvgDialog_47150_Content_9 = {
    Text = "Vedendo che ti sei rifiutato di bere anche solo un sorso, Sorel scuote la testa con finta irritazione, ritirando il calice e concedendosi qualche delicato sorso."
  },
  AvgDialog_47164_Content_1 = {
    Text = "Ascoltate, o Stelle"
  },
  AvgDialog_47164_Content_10 = {
    Text = "Sono qui, Deborah. Sono qui."
  },
  AvgDialog_47164_Content_100 = {
    Text = "...Dove sono le guardie?"
  },
  AvgDialog_47164_Content_101 = {
    Text = "Mentre voi brindevate e bevevate, noi stavamo già massacrando le vostre guardie personali."
  },
  AvgDialog_47164_Content_102 = {
    Text = "Quanto ai vostri eserciti fuori dalla città... non disturbatevi a cercare di contattarli."
  },
  AvgDialog_47164_Content_103 = {
    Text = "Il sangue macchia ogni angolo della sala. Le urla riecheggiano sulle pareti come una sinfonia dall'Inferno."
  },
  AvgDialog_47164_Content_104 = {
    Text = "Coloro che non hanno bevuto il vino contaminato tremano, i corpi troppo deboli persino per sguainare una spada o fuggire."
  },
  AvgDialog_47164_Content_105 = {
    Text = "Golia ammira il capolavoro sanguinario, assaporando il terrore sui loro volti. Sospira con soddisfazione e solleva la sua lama immensa."
  },
  AvgDialog_47164_Content_106 = {
    Text = "Bevete il vino e diventate uomini-pesce, o perite qui. Fate la vostra scelta."
  },
  AvgDialog_47164_Content_107 = {Text = "..."},
  AvgDialog_47164_Content_108 = {
    Text = "AAAHHHH!!—"
  },
  AvgDialog_47164_Content_109 = {
    Text = "Un urlo lacerante colpisce le tavolette di pietra, producendo un'eco cupa e greve."
  },
  AvgDialog_47164_Content_11 = {
    Text = "Miryam? Cosa stai... facendo?"
  },
  AvgDialog_47164_Content_110 = {
    Text = "Tenta di divincolarsi, di fuggire, ma Miryam la tiene salda. Non riesce a muoversi di un solo passo."
  },
  AvgDialog_47164_Content_111 = {
    Text = "Vorrebbe svenire, ma la sua mente resta dolorosamente lucida, costretta ad affrontare l'agonia e la paura."
  },
  AvgDialog_47164_Content_112 = {
    Text = "Ripeti dopo di me: \"I devoti saranno abbracciati — poiché il Signore contempla la loro devozione.\""
  },
  AvgDialog_47164_Content_113 = {
    Text = "Il sangue di Deborah schizza sulla figura di Miryam. Ricorda di aver fatto lo stesso a suo padre sull'altare del tempio, molti anni fa."
  },
  AvgDialog_47164_Content_114 = {
    Text = "L'addio non è che il preludio a un più grandioso ricongiungimento, non è vero, mio Signore?"
  },
  AvgDialog_47164_Content_115 = {
    Text = "Fissa intensamente l'addome di Deborah mentre la sua lama si muove per completare l'ultimo tratto del diagramma."
  },
  AvgDialog_47164_Content_116 = {
    Text = "Avanti, Deborah. Parla. 'Le anime anelanti...'"
  },
  AvgDialog_47164_Content_117 = {
    Text = "La mano di Miryam affondò nel ventre di Deborah, frugando e lacerando."
  },
  AvgDialog_47164_Content_118 = {
    Text = "La voce rauca di Deborah stride nell'agonia. I suoi occhi iniettati di sangue si spalancano nella follia, fissi sulle proprie viscere."
  },
  AvgDialog_47164_Content_119 = {
    Text = "\"...sarà esaudita — poiché il Signore ode le loro preghiere.\""
  },
  AvgDialog_47164_Content_12 = {
    Text = "Questo scherzo non è affatto divertente, Miryam... Mettimi giù..."
  },
  AvgDialog_47164_Content_120 = {
    Text = "Miryam strappa qualcosa via. Dovrebbe essere doloroso, ma Deborah non lo sente più."
  },
  AvgDialog_47164_Content_121 = {
    Text = "La sua mente si è intorpidita; le emozioni e i sensi l'hanno abbandonata."
  },
  AvgDialog_47164_Content_122 = {
    Text = "Vede vagamente Miryam estrarre una massa sanguinolenta dal suo addome aperto."
  },
  AvgDialog_47164_Content_123 = {
    Text = "Sa... Sa..."
  },
  AvgDialog_47164_Content_124 = {
    Text = "Sarah. Miryam le aveva detto che era il nome della sua sorella minore."
  },
  AvgDialog_47164_Content_125 = {
    Text = "Lei e Nord avevano concordato di chiamare così la loro figlia, ma non ebbe mai l'occasione di dirlo a Miryam."
  },
  AvgDialog_47164_Content_126 = {
    Text = "<Italic:Chiamatela Sarah...> Le labbra di Deborah si muovono, ma non riesce più a trovare la voce."
  },
  AvgDialog_47164_Content_127 = {
    Text = "\"Signore, possano i nostri inni perforare le tenebre abissali, affinché possiamo ascendere con Te — nel vuoto eterno, dove silenzio e follia regnano come un'unica cosa.\""
  },
  AvgDialog_47164_Content_128 = {
    Text = "Miryam bacia teneramente la sua figlioccia, le labbra macchiate dal sangue dell'infante. Mentre chiude gli occhi di Deborah, il sangue le cola dall'angolo della bocca."
  },
  AvgDialog_47164_Content_129 = {Text = "..."},
  AvgDialog_47164_Content_13 = {
    Text = "No, Deborah, questo non è uno scherzo. Nulla al mondo è più solenne di questo."
  },
  AvgDialog_47164_Content_130 = {
    Text = "Toc, toc, toc..."
  },
  AvgDialog_47164_Content_131 = {
    Text = "Faint passi risuonano dall'interno della casa."
  },
  AvgDialog_47164_Content_132 = {
    Text = "Questa umile capanna, costruita con oscure Tavolette, appare identica alla casa in cui Miryam un tempo viveva."
  },
  AvgDialog_47164_Content_133 = {
    Text = "In questa casa, lei disse addio a sua madre, suo padre, sua sorella e ai suoi amici."
  },
  AvgDialog_47164_Content_134 = {
    Text = "In questa casa, lei si ricongiungerà con loro."
  },
  AvgDialog_47164_Content_135 = {
    Text = "I passi si sono fermati sulla soglia."
  },
  AvgDialog_47164_Content_136 = {
    Text = "Sia lode alla Somma Sacerdotessa!"
  },
  AvgDialog_47164_Content_137 = {
    Text = "Sia lode alla Somma Sacerdotessa!"
  },
  AvgDialog_47164_Content_138 = {
    Text = "Golia cade in ginocchio. Dietro di lui, una moltitudine di uomini-pesce ruggisce le stesse parole all'unisono mentre si prostra a terra."
  },
  AvgDialog_47164_Content_139 = {
    Text = "Circondano la baracca come una marea senza fine, in attesa di un comando dal profondo."
  },
  AvgDialog_47164_Content_14 = {
    Text = "Cosa vuoi, Miryam... Non avevi detto che ero la tua migliore amica?"
  },
  AvgDialog_47164_Content_140 = {
    Text = "Miryam avanza verso la folla, cullando l'infante coperto di sangue. Gli uomini-pesce si aprono per farle strada."
  },
  AvgDialog_47164_Content_141 = {
    Text = "Le Stelle Sono Allineate. Il Feto Divino del Re è stato impiantato nel Sacro Fanciullo. Presto, il Re farà ritorno in questo mondo."
  },
  AvgDialog_47164_Content_142 = {
    Text = "Il re proteggerà i suoi sudditi virtuosi, dando vita al Reame Divino!"
  },
  AvgDialog_47164_Content_143 = {
    Text = "Il Reame Divino! Il Reame Divino!"
  },
  AvgDialog_47164_Content_144 = {
    Text = "Gli uomini-pesce esultano e danzano in una frenesia di follia. Miryam resta al centro, la luce delle stelle a illuminarle il volto, rigato di sangue e lacrime."
  },
  AvgDialog_47164_Content_145 = {
    Text = "La parola del Nostro Signore si propagherà per il mondo. Somma Sacerdotessa, dona un nome a questo gregge."
  },
  AvgDialog_47164_Content_146 = {
    Text = "Occhi freddi e ardenti si volgono lentamente. Miryam scruta i suoi soldati, i suoi sudditi. Offre loro il sorriso di una sacerdotessa."
  },
  AvgDialog_47164_Content_147 = {
    Text = [[
Navighiamo verso il mare, seguendo le Sue orme.
Navighiamo attraverso il mare, riportando il Suo Regno divino...]]
  },
  AvgDialog_47164_Content_148 = {
    Text = "Il mondo ci chiamerà... Navigatori."
  },
  AvgDialog_47164_Content_149 = {
    Text = "Navigatori! Navigatori!!"
  },
  AvgDialog_47164_Content_15 = {
    Text = "Tu... anche tu una volta avevi un'amica di nome Deborah... Non è forse il fato, Miryam? Ti prego... ti prego, non farmi del male..."
  },
  AvgDialog_47164_Content_150 = {
    Text = "Tra il coro assordante degli uomini-pesce, Miryam solleva il neonato in alto con entrambe le mani."
  },
  AvgDialog_47164_Content_151 = {
    Text = "Al posto del suo cuore, il Feto Divino emette un candido bagliore sotto le stelle."
  },
  AvgDialog_47164_Content_152 = {Text = "Waaahhh—"},
  AvgDialog_47164_Content_153 = {
    Text = "Cala il Silenzio. L'infante insanguinato che si dimena tra le rovine emette il suo primo, tardivo vagito."
  },
  AvgDialog_47164_Content_154 = {
    Text = "Le stelle ascoltano in silenzio quel grido oracolare. Una singola stella cade, tracciando una scia dolente nel cielo notturno."
  },
  AvgDialog_47164_Content_155 = {
    Text = "—Un altro racconto delle stelle sta per avere inizio."
  },
  AvgDialog_47164_Content_16 = {
    Text = "No, Deborah. Come potrei sopportare di farti del male? Sei la mia migliore amica, la mia unica amica..."
  },
  AvgDialog_47164_Content_17 = {
    Text = "Le accarezza il volto, asciugandole le lacrime di terrore. Quel tocco freddo e viscido fa rabbrividire Deborah."
  },
  AvgDialog_47164_Content_18 = {
    Text = "Non ti farò mai, mai del male, Deborah. Ti sto semplicemente facendo un dono."
  },
  AvgDialog_47164_Content_19 = {
    Text = "Un... un dono?"
  },
  AvgDialog_47164_Content_2 = {
    Text = "Territorio della Famiglia Ornn, Altare"
  },
  AvgDialog_47164_Content_20 = {
    Text = "Desideravo tanto poter essere io a portare in grembo il Sacro Feto. Ma mi hai vista tentare di impiantarlo; non ne sono degna."
  },
  AvgDialog_47164_Content_21 = {
    Text = "Questo onore non è qualcosa che tutti possono ottenere. Il mio rammarico è non poterne assaporare la grazia..."
  },
  AvgDialog_47164_Content_22 = {
    Text = "Deborah, sono la madrina di tua figlia. Conferirò questo onore supremo alla mia figlioccia, e anche a te, mia carissima e unica amica."
  },
  AvgDialog_47164_Content_23 = {
    Text = "Miryam, sono disposta... sono disposta a lasciare che mia figlia diventi un ricettacolo, ad abbracciare questo onore..."
  },
  AvgDialog_47164_Content_24 = {
    Text = "Ma non nascerà prima di altri tre mesi... Non c'è nulla che io possa fare."
  },
  AvgDialog_47164_Content_25 = {
    Text = "È troppo tardi, Deborah. È troppo tardi."
  },
  AvgDialog_47164_Content_26 = {
    Text = "Miryam guardò Deborah con affetto, il suo tono si fece ancora più dolce."
  },
  AvgDialog_47164_Content_27 = {
    Text = "È la scelta perfetta. Deve nascere oggi."
  },
  AvgDialog_47164_Content_28 = {Text = "..."},
  AvgDialog_47164_Content_29 = {
    Text = "Territorio della Famiglia Edmond, Sala del Banchetto"
  },
  AvgDialog_47164_Content_3 = {Text = "Tic-tac—"},
  AvgDialog_47164_Content_30 = {
    Text = "E ora, diamo il benvenuto all'ospite delle festività di questa sera — Golia degli Ornn!"
  },
  AvgDialog_47164_Content_31 = {
    Text = "Gli Applausi echeggiarono nella sala. Golia salì sul Livello, scrutando lentamente la stanza."
  },
  AvgDialog_47164_Content_32 = {
    Text = "Edmond, Pappas, Enom... I membri di tutte le famiglie più illustri si sono riuniti qui."
  },
  AvgDialog_47164_Content_33 = {
    Text = "I loro abiti sfarzosi raccontano una storia di massacri, e i loro occhi ridenti brillano di Bramosia."
  },
  AvgDialog_47164_Content_34 = {
    Text = "Sono i padroni della terra e della storia. Sono gli Schiavi del Potere e del Desiderio."
  },
  AvgDialog_47164_Content_35 = {
    Text = "Golia sorrise loro."
  },
  AvgDialog_47164_Content_36 = {
    Text = "Signore e signori, oggi segna la fondazione ufficiale dell'Alleanza delle Sette Famiglie. Gli accordi dettagliati vi saranno comunicati a breve."
  },
  AvgDialog_47164_Content_37 = {
    Text = "Ora, godiamoci questo meraviglioso Festino. Un brindisi alla terra, al denaro e al Potere!"
  },
  AvgDialog_47164_Content_38 = {
    Text = "La Folla esultò e alzò i calici. Piatti squisiti e abbondanti furono serviti uno dopo l'altro."
  },
  AvgDialog_47164_Content_39 = {
    Text = "Il Banchetto ebbe inizio, e i Nobili alzarono i calici per celebrare i profitti imminenti. Il clamore soffocò ogni suono proveniente dall'esterno."
  },
  AvgDialog_47164_Content_4 = {
    Text = "Il suono di acqua che gocciolava raggiunse chiaramente le orecchie di Deborah. Aprì lentamente gli occhi."
  },
  AvgDialog_47164_Content_40 = {
    Text = "Fuori dalla Porta."
  },
  AvgDialog_47164_Content_41 = {Text = "Ah—"},
  AvgDialog_47164_Content_42 = {
    Text = "Tu sei... Ugh!..."
  },
  AvgDialog_47164_Content_43 = {
    Text = "Abisha estrae il coltello conficcato nel corpo della Guardia."
  },
  AvgDialog_47164_Content_44 = {
    Text = "Uff... Se non riuscissi a capire il gorgoglio di questi mostri-pesce, non sarei qui a fare il loro lavoro sporco."
  },
  AvgDialog_47164_Content_45 = {
    Text = "Guarda il soldato Abissale accanto a lui e sospira."
  },
  AvgDialog_47164_Content_46 = {
    Text = "Tutte le altre uscite sono state messe in sicurezza? Le guardie personali portate da quelle famiglie sono state uccise?"
  },
  AvgDialog_47164_Content_47 = {
    Text = "Bene... Mettete in sicurezza tutte le uscite del castello. Stanziate una squadra con me vicino alla sala del Banchetto e attendete i prossimi ordini di Lord Golia."
  },
  AvgDialog_47164_Content_48 = {
    Text = "Il loro grosso delle forze impiegherà probabilmente un'ora o due per venire a conoscenza dell'anomalia qui. Pregate che Lord Golia risolva la questione entro allora..."
  },
  AvgDialog_47164_Content_49 = {Text = "..."},
  AvgDialog_47164_Content_5 = {
    Text = "Una stanza circondata da tavolette scure, con la luce delle stelle che cadeva da un'apertura in alto, illuminandole il ventre."
  },
  AvgDialog_47164_Content_50 = {
    Text = "No...Miryam...non farlo!"
  },
  AvgDialog_47164_Content_51 = {
    Text = "Vi prego... vi prego... in nome del nostro legame... risparmiatemi..."
  },
  AvgDialog_47164_Content_52 = {
    Text = "Ti conferisco l'Onore Supremo, eppure insulti questa amicizia, Deborah."
  },
  AvgDialog_47164_Content_53 = {
    Text = "Non importa. Il mio Signore comprende il tuo terrore. Il nostro legame non sarà spezzato da queste meschine grida."
  },
  AvgDialog_47164_Content_54 = {
    Text = "Con reverenza, posa l'idolo di Tulu accanto all'altare e si inchina dinanzi ad esso."
  },
  AvgDialog_47164_Content_55 = {
    Text = "Sia lodato il Signore... Lemuria, il Grande Re... Stanotte, do il benvenuto al tuo ritorno."
  },
  AvgDialog_47164_Content_56 = {
    Text = "Abbi pazienza. Le stelle si stanno muovendo verso l'allineamento."
  },
  AvgDialog_47164_Content_57 = {
    Text = "Si alza e cammina verso Deborah con passo gentile. Un bizzarro pugnale cerimoniale brilla nella sua mano pallida."
  },
  AvgDialog_47164_Content_58 = {
    Text = "No! Miryam! Ti supplico... ti prego... non farlo..."
  },
  AvgDialog_47164_Content_59 = {
    Text = "Guardami, Deborah. Guardami negli occhi."
  },
  AvgDialog_47164_Content_6 = {
    Text = "Il suo corpo era nudo, il ventre gonfio, con le vene chiaramente visibili sotto la luce delle stelle."
  },
  AvgDialog_47164_Content_60 = {
    Text = "So che hai paura. Ho visto molti credenti tremare quando giungono alla fine di questa vita."
  },
  AvgDialog_47164_Content_61 = {
    Text = "Ma non temere. Tu sei una delle persone supreme del Reame Divino; tutto ciò che hai sopportato ti sarà ripagato nel Reame Divino."
  },
  AvgDialog_47164_Content_62 = {
    Text = "Vieni, prega con me, Deborah."
  },
  AvgDialog_47164_Content_63 = {
    Text = "No... Miryam... ti prego..."
  },
  AvgDialog_47164_Content_64 = {
    Text = "Ripeti con me: \"La sofferenza sarà ricompensata...\""
  },
  AvgDialog_47164_Content_65 = {
    Text = "La... la Sofferenza... no, Miryam..."
  },
  AvgDialog_47164_Content_66 = {
    Text = "Ripeti con me: \"Gli empi saranno flagellati — poiché il Signore giudica la loro iniquità.\""
  },
  AvgDialog_47164_Content_67 = {
    Text = "Miryam recita le preghiere mentre si avvicina al fianco della sua amica."
  },
  AvgDialog_47164_Content_68 = {
    Text = "Lasciami dire una cosa a Nord! Miryam... solo una parola per lui..."
  },
  AvgDialog_47164_Content_69 = {
    Text = "<Big:Ah!!!—>"
  },
  AvgDialog_47164_Content_7 = {
    Text = "Cosa sta succedendo... Miryam?!"
  },
  AvgDialog_47164_Content_70 = {
    Text = "L'agonia divampa nel suo addome. Alza lo sguardo e vede la mano pallida e serpentina di Miryam affondare il pugnale in profondità, tracciando un sentiero cremisi attraverso il suo ventre."
  },
  AvgDialog_47164_Content_71 = {
    Text = "Miryam è sorda alle urla laceranti. Non vede il volto stravolto dal terrore e dal dolore."
  },
  AvgDialog_47164_Content_72 = {
    Text = "Il pugnale si muoveva con fermezza, spruzzando sangue caldo sul volto di Miryam. Lei cantava devotamente, incamminandosi sul sentiero verso il Reame Divino."
  },
  AvgDialog_47164_Content_73 = {Text = "..."},
  AvgDialog_47164_Content_74 = {
    Text = "Uccidete Miryam! Dividete la famiglia Ornn! Lunga vita alla nostra alleanza! Applausi!"
  },
  AvgDialog_47164_Content_75 = {
    Text = "I bicchieri tintinnano mentre la bramosia sfrenata si mescola all'aroma di vino e carne."
  },
  AvgDialog_47164_Content_76 = {
    Text = "Golia si lecca le labbra, assaporando quel sapore inebriante."
  },
  AvgDialog_47164_Content_77 = {
    Text = "Avanti, continua. Che ti prende?"
  },
  AvgDialog_47164_Content_78 = {
    Text = "Il... il tuo volto..."
  },
  AvgDialog_47164_Content_79 = {
    Text = "La mia faccia?"
  },
  AvgDialog_47164_Content_8 = {
    Text = "Tentò di alzarsi, solo per scoprire che il corpo e gli arti erano legati a un altare di pietra, impossibilitata a muoversi."
  },
  AvgDialog_47164_Content_80 = {
    Text = "Guarda le piastrelle simili a specchi accanto a sé e scorge un volto che somiglia a un pesce."
  },
  AvgDialog_47164_Content_81 = {Text = "ARGH!!"},
  AvgDialog_47164_Content_82 = {
    Text = "Ferite si aprono sul suo petto come intagliate da pugnali invisibili. Le orecchie e le sopracciglia svaniscono; i bulbi oculari si gonfiano e migrano ai lati della testa."
  },
  AvgDialog_47164_Content_83 = {
    Text = "L'agonia trafigge la nebbia dell'alcol e dell'adrenalina. Crolla a terra, vomitando dal dolore, le mani che graffiano freneticamente il volto."
  },
  AvgDialog_47164_Content_84 = {
    Text = "Cos'è questo? Ah!!"
  },
  AvgDialog_47164_Content_85 = {
    Text = "Uno, due, tre... nella lussuosa sala del banchetto, i nobili cadono a terra uno dopo l'altro."
  },
  AvgDialog_47164_Content_86 = {
    Text = "Squarci cremisi compaiono sui loro corpi, sangue e carne che formano antichi, grotteschi disegni."
  },
  AvgDialog_47164_Content_87 = {
    Text = "I loro lamenti d'agonia convergono in una grandiosa sinfonia. Il sangue spruzza, colmando ogni calice."
  },
  AvgDialog_47164_Content_88 = {
    Text = "Questo è... questo è... un rito degli Abissali!"
  },
  AvgDialog_47164_Content_89 = {
    Text = "Precisamente. Un rito Abissale. Avete tutti sentito della tragedia che si abbatté sulla famiglia Ornn, non è vero?"
  },
  AvgDialog_47164_Content_9 = {
    Text = "Un paio di mani si protesero e afferrarono le sue. Erano fredde e viscide, come un pallido serpente."
  },
  AvgDialog_47164_Content_90 = {
    Text = "Perché... Golia?"
  },
  AvgDialog_47164_Content_91 = {Text = "Perché?"},
  AvgDialog_47164_Content_92 = {
    Text = "Golia sembra udire una battuta esilarante. Si alza dal seggio e impugna la sua lama."
  },
  AvgDialog_47164_Content_93 = {
    Text = "Collaborando con voi avrei ottenuto un misero lembo di territorio degli Ornn."
  },
  AvgDialog_47164_Content_94 = {
    Text = "Ma collaborando con Miryam, ottengo un potere che va oltre la vostra comprensione. Posso trasformare le vostre intere casate in uomini-pesce e impossessarmi di tutte le vostre ricchezze."
  },
  AvgDialog_47164_Content_95 = {
    Text = "Ditemi, signor Edmond, se foste al mio posto, cosa scegliereste?"
  },
  AvgDialog_47164_Content_96 = {
    Text = "Noi... non ci arrenderemo senza combattere!"
  },
  AvgDialog_47164_Content_97 = {
    Text = "Esatto! Golia, sull'onore della famiglia Enom, noi—ugh!"
  },
  AvgDialog_47164_Content_98 = {
    Text = "Una lama immensa cala, scindendo in due il giovane nobile. Il suo onore muore con lui."
  },
  AvgDialog_47164_Content_99 = {
    Text = "Le porte si spalancano e una marea di uomini-pesce inonda la sala."
  },
  AvgDialog_47165_Content_1 = {
    Text = "Amico del Cuore"
  },
  AvgDialog_47165_Content_10 = {
    Text = "Non siate nervoso, signor Edmund. Miryam mi ha privato della libertà; condividiamo un Nemico Comune."
  },
  AvgDialog_47165_Content_100 = {
    Text = "Miryam, non angosciarti troppo. Possiamo cercare insieme altre soluzioni..."
  },
  AvgDialog_47165_Content_101 = {
    Text = "Non c'è altra via, Deborah. Resta una sola possibilità..."
  },
  AvgDialog_47165_Content_102 = {
    Text = "Alzò lo sguardo, si asciugò le lacrime e accarezzò dolcemente il volto di Deborah."
  },
  AvgDialog_47165_Content_103 = {
    Text = "Le tornarono alla mente domande dimenticate da tempo. Quelle domande, sepolte dal trascorrere del tempo, riaffiorarono ora, colmandole la mente di una foschia polverosa."
  },
  AvgDialog_47165_Content_104 = {
    Text = "Deborah, credi nel Re?"
  },
  AvgDialog_47165_Content_105 = {Text = "Certo..."},
  AvgDialog_47165_Content_106 = {
    Text = "Deborah, sai cos'è la fede?"
  },
  AvgDialog_47165_Content_107 = {
    Text = "Il mio maestro mi disse un tempo che la fede è tutta una questione di responsabilità e significato, e non lascia spazio per null'altro."
  },
  AvgDialog_47165_Content_108 = {
    Text = "Hmm... La stai rendendo così complicata..."
  },
  AvgDialog_47165_Content_109 = {
    Text = "In realtà è molto semplice. Deborah, tu sei stata la mia unica vera amica da molto, molto tempo..."
  },
  AvgDialog_47165_Content_11 = {
    Text = "Miryam possiede un Potere immenso. Avete molti valorosi guerrieri, ma eliminarla comporterà un costo estremamente gravoso."
  },
  AvgDialog_47165_Content_110 = {
    Text = "Ti promisi un onore supremo, di fare di te la prima Cittadina del Reame Divino. Promisi di rendere il tuo Focolare la famiglia più felice del Reame Divino."
  },
  AvgDialog_47165_Content_111 = {
    Text = "Lo farò, Deborah. Ricorderò le tue speranze per il futuro. Ora, ti conferisco questo onore."
  },
  AvgDialog_47165_Content_112 = {
    Text = "Il Reame Divino giungerà, e Il Sentiero che conduce ad esso porterà il tuo nome. Ogni Credente, ogni Cittadino, ti ricorderà."
  },
  AvgDialog_47165_Content_113 = {Text = "!!!"},
  AvgDialog_47165_Content_114 = {
    Text = "Aspetta, Miryam, io..."
  },
  AvgDialog_47165_Content_115 = {
    Text = "Deborah non ebbe il tempo di provare Terrore. Prima che finisse di parlare, una foschia nera e serpentina le penetrò nel corpo. Avvertì un capogiro e crollò sulla spalla di Miryam."
  },
  AvgDialog_47165_Content_116 = {
    Text = "Non puoi farlo..."
  },
  AvgDialog_47165_Content_117 = {
    Text = "Devo farlo."
  },
  AvgDialog_47165_Content_118 = {
    Text = "Tuo padre e il Re non vorrebbero vederti così!"
  },
  AvgDialog_47165_Content_119 = {
    Text = "Sei solo una bambina di nove anni, Miryam. Non capisci."
  },
  AvgDialog_47165_Content_12 = {
    Text = "Sono disposto a collaborare con voi. Questa è la mia sincerità."
  },
  AvgDialog_47165_Content_120 = {
    Text = "Padre e il Re desiderano vedere l'Avvento del Reame Divino."
  },
  AvgDialog_47165_Content_121 = {
    Text = "Non sto forse esaudendo i loro desideri?"
  },
  AvgDialog_47165_Content_122 = {
    Text = "Ma... questo non è corretto..."
  },
  AvgDialog_47165_Content_123 = {
    Text = "Solo il Reame Divino è giusto."
  },
  AvgDialog_47165_Content_124 = {
    Text = "La Voce di Miryam è calma, come se stesse enunciando una Conoscenza comune che Tutti dovrebbero conoscere."
  },
  AvgDialog_47165_Content_125 = {
    Text = "La piccola Miryam fissa il suo sé futuro. Sicura, determinata e potente — l'indiscussa Somma Sacerdotessa di Lemuria e la solitaria emissaria del Reame Divino."
  },
  AvgDialog_47165_Content_126 = {
    Text = "La figlia che un tempo tremava sotto le rovine, invocando suo padre, non ha più alcun legame con lei."
  },
  AvgDialog_47165_Content_127 = {
    Text = "Capisco... Suppongo sia giunto il momento per me di andare."
  },
  AvgDialog_47165_Content_128 = {
    Text = "La guardò con uno sguardo colmo di Pianto."
  },
  AvgDialog_47165_Content_129 = {
    Text = "Possa tu trovare il tuo Reame Divino, Miryam."
  },
  AvgDialog_47165_Content_13 = {
    Text = "Le Guardie trasportarono diversi forzieri nel salotto. Quando i coperchi furono sollevati, l'abbagliante luce dorata si riversò sul volto del vecchio Edmond, lasciando il suo Spirito momentaneamente stordito."
  },
  AvgDialog_47165_Content_130 = {Text = "Lo farò."},
  AvgDialog_47165_Content_131 = {
    Text = "Sapeva che era l'ultima Benedizione e l'ultimo addio. La piccola Miryam se ne andò, come se non fosse mai esistita. Miryam non rivolse neppure uno sguardo al punto in cui era scomparsa."
  },
  AvgDialog_47165_Content_132 = {
    Text = "Abbraccia Deborah, accarezzandole dolcemente la schiena mentre canticchia sommessamente una ninnananna lemuriana, come se cullasse una bambina per farla addormentare."
  },
  AvgDialog_47165_Content_133 = {
    Text = "Fuori dalla finestra, il sole è tramontato, e le stelle cominciano a percorrere i rispettivi sentieri."
  },
  AvgDialog_47165_Content_134 = {
    Text = "—Il momento dell'Allineamento celeste si avvicina."
  },
  AvgDialog_47165_Content_14 = {
    Text = "Posso percepire la vostra sincerità, signor Golia... Qual è il vostro piano?"
  },
  AvgDialog_47165_Content_15 = {
    Text = "Ho già fatto visita ai Pappas, agli Enom e a diverse altre famiglie di spicco, una dopo l'altra."
  },
  AvgDialog_47165_Content_16 = {
    Text = "Gli eserciti delle varie famiglie hanno iniziato a radunarsi. Prima che entrino in azione, credo sia necessario tenere un consiglio."
  },
  AvgDialog_47165_Content_17 = {
    Text = "Ti dirò tutto sulla famiglia Ornn e ti offrirò il mio consiglio."
  },
  AvgDialog_47165_Content_18 = {
    Text = "Mi assicurerò che tu uccida Miryam al minimo costo. E..."
  },
  AvgDialog_47165_Content_19 = {
    Text = "Si avvicinò all'orecchio del vecchio Edmond."
  },
  AvgDialog_47165_Content_2 = {
    Text = "Prego, sedete, Golia della famiglia Ornn."
  },
  AvgDialog_47165_Content_20 = {
    Text = "A essere sincero con voi, signor Edmund, sto cercando la persona giusta con cui collaborare in profondità."
  },
  AvgDialog_47165_Content_21 = {
    Text = "A dire il vero, la forza della famiglia Edmond non è considerata particolarmente forte tra le famiglie maggiori. Ed è proprio per questo che sono disposto a cooperare con voi."
  },
  AvgDialog_47165_Content_22 = {
    Text = "Le ricchezze e le terre degli Ornn, persino il potere di Miryam: posso offrirvi una parte di tutto ciò."
  },
  AvgDialog_47165_Content_23 = {
    Text = "Ciò che cerco è un'alleanza profonda. Dopotutto, il nostro obiettivo non è semplicemente sconfiggere Miryam e la famiglia Ornn, non è vero?"
  },
  AvgDialog_47165_Content_24 = {
    Text = "Il vecchio guardò Golia con un sorriso complice."
  },
  AvgDialog_47165_Content_25 = {
    Text = "Hehehe, piccola ambiziosa..."
  },
  AvgDialog_47165_Content_26 = {
    Text = "La vostra visuale è lungimirante, signor Golia. In effetti, la caduta della famiglia Ornn non è che il prologo."
  },
  AvgDialog_47165_Content_27 = {
    Text = "La nostra alleanza porterà senza dubbio una nuova dinastia su questa terra..."
  },
  AvgDialog_47165_Content_28 = {Text = "..."},
  AvgDialog_47165_Content_29 = {
    Text = "Sorella... Padre... Ah!..."
  },
  AvgDialog_47165_Content_3 = {
    Text = "Le parole del vecchio conservavano ancora una raffinatezza aristocratica di base, ma il tono di disprezzo non era occultato in alcun modo."
  },
  AvgDialog_47165_Content_30 = {
    Text = "Miryam? Miryam, stai bene?"
  },
  AvgDialog_47165_Content_31 = {
    Text = "Miryam si svegliò sudata, la schiena fradicia."
  },
  AvgDialog_47165_Content_32 = {
    Text = "Suo padre e sua sorella svanirono dalla sua vista, sostituiti dal volto preoccupato di Deborah."
  },
  AvgDialog_47165_Content_33 = {
    Text = "Hai sognato la tua famiglia?"
  },
  AvgDialog_47165_Content_34 = {
    Text = "Ho visto mio padre e mia sorella; avevano entrambi volti simili a pesci... Mio padre ha detto che vivono così da decine di migliaia di anni..."
  },
  AvgDialog_47165_Content_35 = {
    Text = "Mi ha chiesto: \"Quanto ancora dovrò aspettare...\""
  },
  AvgDialog_47165_Content_36 = {
    Text = "Deborah, io... non riesco più a ricordare che aspetto abbia mio padre..."
  },
  AvgDialog_47165_Content_37 = {
    Text = "Miryam non riuscì più a continuare a parlare. Si appoggiò debolmente alla sponda del letto."
  },
  AvgDialog_47165_Content_38 = {
    Text = "Deborah posò un fazzoletto sulla fronte di Miryam e le accarezzò dolcemente la schiena."
  },
  AvgDialog_47165_Content_39 = {
    Text = "Ultimamente hai avuto degli incubi... Le tue ferite non sono ancora del tutto guarite, smettila di tormentarti con quei pensieri."
  },
  AvgDialog_47165_Content_4 = {
    Text = "Signor Edmond, comprendo perfettamente la vostra ostilità verso la famiglia Ornn."
  },
  AvgDialog_47165_Content_40 = {
    Text = "Andrà tutto bene. Una volta che avrai recuperato il corpo e portato qui il Reame Divino, presto ti ricongiungerai con la tua famiglia."
  },
  AvgDialog_47165_Content_41 = {
    Text = "Scusa, Deborah... Sia a Lemuria che adesso, mi hai aiutata così tanto..."
  },
  AvgDialog_47165_Content_42 = {
    Text = "Stai dicendo di nuovo cose che non riesco a capire... C'è forse bisogno di scusarsi per questo?"
  },
  AvgDialog_47165_Content_43 = {
    Text = "Miryam scosse il capo, senza offrire ulteriori spiegazioni. Posò lo sguardo sul ventre gonfio di Deborah con un'espressione complessa."
  },
  AvgDialog_47165_Content_44 = {
    Text = "Le mie ferite sono quasi guarite. Presto diventerai madre, prenditi cura di te stessa prima di tutto."
  },
  AvgDialog_47165_Content_45 = {
    Text = "Sono sana quanto lei..."
  },
  AvgDialog_47165_Content_46 = {
    Text = "Ah! Miryam! Miryam, ascolta... Mi sta scalciando!"
  },
  AvgDialog_47165_Content_47 = {
    Text = "Davvero? Fammi sentire..."
  },
  AvgDialog_47165_Content_48 = {
    Text = "Miryam si chinò e avvicinò il viso al ventre di Deborah."
  },
  AvgDialog_47165_Content_49 = {
    Text = "Ah, è vero... L'ho sentito..."
  },
  AvgDialog_47165_Content_5 = {
    Text = "La famiglia Ornn ha intrapreso un... insolito Sentiero."
  },
  AvgDialog_47165_Content_50 = {
    Text = "Piccola, guarda, questa è la tua madrina, la nostra Somma Sacerdotessa, Miryam. Ti ha percepita, così abbiamo saputo presto che eri una bambina e abbiamo preparato dei doni per la tua nascita."
  },
  AvgDialog_47165_Content_51 = {
    Text = "Un giorno, porterà tutta la nostra famiglia nel leggendario Reame Divino!"
  },
  AvgDialog_47165_Content_52 = {
    Text = "A quel punto, tuo padre sarà ancora il conducente del Vecchio Sommo Sacerdote, e io sarò ancora l'ancella del Vecchio Sommo Sacerdote..."
  },
  AvgDialog_47165_Content_53 = {
    Text = "Non c'è bisogno di cocchieri e ancelle nel Reame Divino."
  },
  AvgDialog_47165_Content_54 = {
    Text = "Non se ne parla; non sarebbe altrettanto piacevole come stare con te."
  },
  AvgDialog_47165_Content_55 = {
    Text = "Miryam fissò lo sguardo sul ventre di Deborah, lasciando trasparire un sorriso complesso."
  },
  AvgDialog_47165_Content_56 = {
    Text = "Deborah, sei la mia unica amica. C'è qualcosa che voglio dirti..."
  },
  AvgDialog_47165_Content_57 = {
    Text = "Somma Sacerdotessa, Lord Golia vi attende alla porta."
  },
  AvgDialog_47165_Content_58 = {
    Text = "... Fatelo entrare."
  },
  AvgDialog_47165_Content_59 = {
    Text = "A quanto pare dovrò aspettare ancora un po' per sentire questa sorpresa~"
  },
  AvgDialog_47165_Content_6 = {
    Text = "Un Sentiero insolito? Voi mostri... La vostra stessa esistenza è una blasfemia per tutti coloro che abitano questo continente."
  },
  AvgDialog_47165_Content_60 = {
    Text = "Deborah fece una smorfia a Miryam e si ritirò nella stanza accanto. Golia entrò, osservando pensieroso la figura di Deborah."
  },
  AvgDialog_47165_Content_61 = {
    Text = "Come procedono le comunicazioni con le altre famiglie?"
  },
  AvgDialog_47165_Content_62 = {
    Text = "I popoli della terraferma sono senz'altro più astuti dei Filistei, ma finché restano umani, i loro desideri rimangono pressoché gli stessi."
  },
  AvgDialog_47165_Content_63 = {
    Text = "Ho detto a ciascuna famiglia che sarebbero diventati i nostri alleati più stretti. Insieme vi uccideremo, distruggeremo la famiglia Ornn, e poi dividerò terre, ricchezze e potere tra loro."
  },
  AvgDialog_47165_Content_64 = {
    Text = "Questa promessa è piena di falle, ma quei tizi sono abbastanza arroganti da credere che sia il loro destino ergersi al vertice del mondo, senza il minimo dubbio."
  },
  AvgDialog_47165_Content_65 = {
    Text = "Il loro esercito si sta radunando. Il giorno dell'Allineamento è tra pochi giorni, e allora terremo un festino."
  },
  AvgDialog_47165_Content_66 = {
    Text = "Quello sarà di certo un Festino davvero meraviglioso."
  },
  AvgDialog_47165_Content_67 = {
    Text = "Golia ghignò con malizia, rivelando i suoi denti aguzzi simili a quelli di uno squalo."
  },
  AvgDialog_47165_Content_68 = {
    Text = "Hai fatto un ottimo lavoro."
  },
  AvgDialog_47165_Content_69 = {
    Text = "E tu? Come procede la preparazione per trovare il Bambino Sacro?"
  },
  AvgDialog_47165_Content_7 = {
    Text = "Fidatevi di me, signor Edmund, è stato un incidente. Quella strega, Miryam, ha causato tutto questo."
  },
  AvgDialog_47165_Content_70 = {
    Text = "Ho cercato tra tutti coloro che ricadono sotto l'influenza della famiglia Ornn."
  },
  AvgDialog_47165_Content_71 = {
    Text = "Ho trovato alcuni neonati che stanno per nascere nel momento dell'allineamento stellare, ma le loro famiglie non credono nel Reame Divino."
  },
  AvgDialog_47165_Content_72 = {
    Text = "Una persona simile non è degna di essere il ricettacolo per nutrire il Re."
  },
  AvgDialog_47165_Content_73 = {
    Text = "Nascere in quell'istante preciso e avere una famiglia di credenti è davvero una condizione ardua."
  },
  AvgDialog_47165_Content_74 = {
    Text = "Il territorio della famiglia Ornn è attualmente molto limitato, e la tua fede deve ancora propagarsi. Le persone che possiamo trovare sono pochissime..."
  },
  AvgDialog_47165_Content_75 = {
    Text = "È un peccato che il figlio di Deborah non nascerà prima di altri tre mesi. Altrimenti, sarebbe stata una candidata perfetta."
  },
  AvgDialog_47165_Content_76 = {
    Text = "Dunque, che facciamo? Dovremmo lasciare che coloro nati sotto le stelle dell'Allineamento facciano un tentativo?"
  },
  AvgDialog_47165_Content_77 = {
    Text = "Se l'impianto fallisce di nuovo, il Sacro Feto potrebbe subire un danno... Non posso permettere che il Re corra un rischio simile."
  },
  AvgDialog_47165_Content_78 = {
    Text = "È complicato... Non riesco a pensare ad alcun altro modo per aiutarti."
  },
  AvgDialog_47165_Content_79 = {
    Text = "Golia si appoggiò allo schienale della sedia. Vedendo dove Miryam stava guardando, e la sua espressione, Golia si raddrizzò di colpo."
  },
  AvgDialog_47165_Content_8 = {
    Text = "So che voi e diverse altre famiglie state segretamente discutendo piani per assediare la famiglia Ornn..."
  },
  AvgDialog_47165_Content_80 = {
    Text = "Aspetta un momento... Non starai mica pensando di..."
  },
  AvgDialog_47165_Content_81 = {
    Text = "Miryam volta leggermente la testa, guardando Golia. Il Suo Sguardo manda un brivido lungo la spina dorsale di Golia fino al cervello."
  },
  AvgDialog_47165_Content_82 = {
    Text = "Questo è proprio da te, Miryam. Sei davvero @2 una folle."
  },
  AvgDialog_47165_Content_83 = {
    Text = "Non preoccuparti, non mi dà alcun fastidio. La mia scelta era corretta. Solo collaborando con qualcuno folle quanto te possiamo compiere ciò che altri non possono."
  },
  AvgDialog_47165_Content_84 = {
    Text = "Va' a prepararti... Devo iniziare a preparare anche il mio rito."
  },
  AvgDialog_47165_Content_85 = {
    Text = "Heh... il momento dell'allineamento stellare sarà di certo una notte splendida. A presto, Somma Sacerdotessa."
  },
  AvgDialog_47165_Content_86 = {Text = "..."},
  AvgDialog_47165_Content_87 = {
    Text = "La porta fu spalancata, e la luce gentile del sole al tramonto cadde su Deborah."
  },
  AvgDialog_47165_Content_88 = {
    Text = "Canticchia una melodia locale accarezzando dolcemente il ventre gonfio, forse pensando a cosa preparare per il bambino o quale nome scegliere."
  },
  AvgDialog_47165_Content_89 = {
    Text = "Vedendo Miryam entrare, le fa un cenno con la mano."
  },
  AvgDialog_47165_Content_9 = {
    Text = "Il Corpo del vecchio Edmond si irrigidì d'improvviso, e si sollevò leggermente a sedere. Golia notò ogni cosa e gli rivolse un sorriso."
  },
  AvgDialog_47165_Content_90 = {
    Text = "Miryam, hai finito di parlare? Com'è andata?!"
  },
  AvgDialog_47165_Content_91 = {
    Text = "Tutto liscio, Golia era ben preparato."
  },
  AvgDialog_47165_Content_92 = {
    Text = "Magnifico! Significa che presto daremo il benvenuto al Reame Divino!"
  },
  AvgDialog_47165_Content_93 = {
    Text = "Miryam le sorrise. Deborah, conoscendola da così tanto tempo, colse facilmente la fatica nel sorriso di Miryam."
  },
  AvgDialog_47165_Content_94 = {
    Text = "Miryam, ho l'impressione che il tuo spirito sia un po' turbato."
  },
  AvgDialog_47165_Content_95 = {
    Text = "Hai detto che le cose sono andate bene con Golia... E dalla nostra parte? C'è un problema?"
  },
  AvgDialog_47165_Content_96 = {
    Text = "Non riesco a trovare la persona giusta, Deborah... La nostra fede non si è ancora propagata, e non c'è un Sacro Fanciullo qualificato..."
  },
  AvgDialog_47165_Content_97 = {
    Text = "Volevo attendere il prossimo Allineamento stellare, ma mio padre e il Re mi incalzano... Non posso più aspettare, Deborah."
  },
  AvgDialog_47165_Content_98 = {
    Text = "Abbracciò Deborah, seppellendo il viso nel suo ventre. Le lacrime caddero, inzuppando le vesti di Deborah."
  },
  AvgDialog_47165_Content_99 = {
    Text = "Oh, se solo la mia creatura fosse nata due o tre mesi prima, avrei potuto aiutarti..."
  },
  AvgDialog_47166_Content_1 = {
    Text = "Miraggio dei Giorni Passati"
  },
  AvgDialog_47166_Content_10 = {
    Text = "Avevo in programma di tornare quando ne avessi avuto il tempo, ma prima di riuscirci, fui trascinato nel caos della ribellione di Iglenn."
  },
  AvgDialog_47166_Content_100 = {
    Text = "Heh, ragazzo, cominci a capirmi meglio."
  },
  AvgDialog_47166_Content_101 = {
    Text = "Lord Golia, perché non avete ucciso Miryam?"
  },
  AvgDialog_47166_Content_102 = {
    Text = "Ucciderla, e sarei davvero libero. Ma a che serve la libertà?"
  },
  AvgDialog_47166_Content_103 = {
    Text = "Golia fissò lo Sguardo sullo stormo di uccelli sopra il mare e chiuse gli occhi, appagato."
  },
  AvgDialog_47166_Content_104 = {
    Text = "Potrei regolare i conti con le tribù che sconfissero i Filistei, o continuare a saccheggiare la costa con la mia tribù. Ma è tutto qui."
  },
  AvgDialog_47166_Content_105 = {
    Text = "Miryam mi ha dato Potere, ma non è abbastanza. Tutt'altro che abbastanza."
  },
  AvgDialog_47166_Content_106 = {
    Text = "Solo forza bruta. Contro quelle potenti truppe del regno, continueremo a essere Cacciati, in fuga come cani randagi in queste acque."
  },
  AvgDialog_47166_Content_107 = {
    Text = "Desidero un Potere più grande di quello che Miryam mi ha conferito."
  },
  AvgDialog_47166_Content_108 = {
    Text = "—Si chiama Potere, Abisha. Rispetto al Potere, la libertà è insignificante."
  },
  AvgDialog_47166_Content_109 = {
    Text = "Un bagliore Cremisi tremolò nei suoi Occhi mentre si leccava le labbra, sorridendo con delizia."
  },
  AvgDialog_47166_Content_11 = {
    Text = "Questo è il tuo Focolare?"
  },
  AvgDialog_47166_Content_110 = {
    Text = "Miryam ora controlla Casa Ornn. Posso usarla per amplificare quell'influenza mille volte."
  },
  AvgDialog_47166_Content_111 = {
    Text = "A quel tempo, riprenderò questi poteri dalle sue mani."
  },
  AvgDialog_47166_Content_112 = {
    Text = "Ma Miryam è così potente... il rischio è troppo grande..."
  },
  AvgDialog_47166_Content_113 = {
    Text = "Abisha, io sono il capo dei Filistei, ricordi? Non abbiamo fatto che fallire e fuggire. Io condurrò i Filistei alla vittoria."
  },
  AvgDialog_47166_Content_114 = {
    Text = "Quanto ai rischi... cosa credi che mi resti da perdere?"
  },
  AvgDialog_47166_Content_115 = {
    Text = "Il gigante batté delicatamente sulla spalla di Abisha, poi si alzò e si avvicinò al capezzale di Miryam."
  },
  AvgDialog_47166_Content_116 = {Text = "..."},
  AvgDialog_47166_Content_117 = {
    Text = "Mio Re... mio Signore... Mi avete abbandonata... Perché..."
  },
  AvgDialog_47166_Content_118 = {
    Text = "Il Sangue filtra attraverso le bende sul suo petto, ma Miryam non se ne accorge. Giace sul letto in preda alla Debolezza, fissando con sguardo vuoto il mare sconfinato."
  },
  AvgDialog_47166_Content_119 = {
    Text = "Da quando ti sei svegliata, non hai fatto che ripetere questa frase per tutto il tragitto. Non potresti cambiare un po'?"
  },
  AvgDialog_47166_Content_12 = {
    Text = "L'aspetto dell'isola è cambiato notevolmente. Potrebbe essere Lemuria, o forse qualcos'altro; non ne sono certo."
  },
  AvgDialog_47166_Content_120 = {
    Text = "Sembri un pesce morto appeso."
  },
  AvgDialog_47166_Content_121 = {
    Text = "Quell'Embrione Sacro può sicuramente essere sostenuto da un corpo. L'ho percepito con estrema chiarezza... Il mio metodo è Correggere!"
  },
  AvgDialog_47166_Content_122 = {
    Text = "Ma il re mi ha respinta... Il re mi ha respinta!"
  },
  AvgDialog_47166_Content_123 = {
    Text = "Golia vide chiaramente il Pain e la Confusione di Miryam. Balenarono per un istante."
  },
  AvgDialog_47166_Content_124 = {
    Text = "Il Re mi disse che quando le Stelle si allineano, Egli riapparirà, e Lemuria farà Ritorno..."
  },
  AvgDialog_47166_Content_125 = {
    Text = "Stelle, Stelle... Potrebbe essere legato alle Stelle..."
  },
  AvgDialog_47166_Content_126 = {
    Text = "Ho capito, ho capito! Il Potere del Re proviene dalle Stelle. Forse solo coloro che nascono sotto il giusto Allineamento possono nutrire il Sacro Feto del Re..."
  },
  AvgDialog_47166_Content_127 = {
    Text = "Il prossimo Allineamento stellare arriverà presto. Posso trovare un neonato... *cough*..."
  },
  AvgDialog_47166_Content_128 = {
    Text = "L'eccitazione divampa negli Occhi di Miryam. Si alza di scatto, aggravando le sue Ferite, e inizia a tossire violentemente."
  },
  AvgDialog_47166_Content_129 = {
    Text = "Prenditi il tempo per riprenderti. Se muori qui, nemmeno il tuo re sopravviverà."
  },
  AvgDialog_47166_Content_13 = {
    Text = "In decine di migliaia di anni, molte cose possono cambiare..."
  },
  AvgDialog_47166_Content_130 = {
    Text = "Che si tratti di cercare il Sacro Infante, nutrire il Sacro Feto, o radunare Seguaci... tutto ciò che devi fare d'ora in poi richiede una grande quantità di denaro, Potere, manodopera e Autorità."
  },
  AvgDialog_47166_Content_131 = {
    Text = "Non ho tempo di preoccuparmi di queste cose..."
  },
  AvgDialog_47166_Content_132 = {
    Text = "È proprio per questo che collaboriamo. Ho tempo — in abbondanza."
  },
  AvgDialog_47166_Content_133 = {
    Text = "Il Potere della famiglia Ornn da solo non basta per ciò che ci attende. Abbiamo bisogno del sostegno di altre famiglie in tutto il continente."
  },
  AvgDialog_47166_Content_134 = {
    Text = "Tutte le risorse di Casa Ornn sono a vostra disposizione. Occupatevi di queste faccende."
  },
  AvgDialog_47166_Content_135 = {
    Text = "Prima del prossimo Allineamento celeste, troverò un ricettacolo adatto per il sacro feto del re."
  },
  AvgDialog_47166_Content_136 = {
    Text = "Miryam voltò leggermente il capo e lanciò un'occhiata a Golia."
  },
  AvgDialog_47166_Content_137 = {
    Text = "Potere, Autorità, ricchezza, dignità... So cosa cerchi di fare, Filistea. E non m'importa."
  },
  AvgDialog_47166_Content_138 = {
    Text = "Se ti tengo in vita è perché sei abbastanza intelligente. Non fare sciocchezze."
  },
  AvgDialog_47166_Content_139 = {
    Text = "Golia mostra un sorriso malvagio."
  },
  AvgDialog_47166_Content_14 = {
    Text = "Miryam lascia scorrere la sabbia fine tra le dita. Le Memorie la sommergono — la caduta della sua terra natale, l'istante in cui si trovò in mezzo al popolo-pesce, osservando impotente il mare divorare ogni cosa in Lemuria."
  },
  AvgDialog_47166_Content_140 = {
    Text = "Come desiderate, Vostra Grazia."
  },
  AvgDialog_47166_Content_141 = {
    Text = "Miryam, siamo a casa!"
  },
  AvgDialog_47166_Content_142 = {
    Text = "Lungo la sinuosa costa dei territori di Casa Ornn, i Grotteschi uomini-pesce, richiamati dal Ritorno della loro signora, si schierano fitti lungo le rive per darle il Benvenuto."
  },
  AvgDialog_47166_Content_143 = {
    Text = "Golia osservò con soddisfazione le loro forme bizzarre, la Lama nella sua Mano, e i loro Occhi leali eppure stolti."
  },
  AvgDialog_47166_Content_144 = {
    Text = "Il suo sguardo li oltrepassa, posandosi sulle infinite terre fertili oltre di loro, come uno squalo che adocchia una balena morente."
  },
  AvgDialog_47166_Content_15 = {
    Text = "Ora è riapparsa qui. Presto riporterà Lemuria in queste acque."
  },
  AvgDialog_47166_Content_16 = {
    Text = "Dove hai trovato la Statua? Portami là."
  },
  AvgDialog_47166_Content_17 = {Text = "Seguimi."},
  AvgDialog_47166_Content_18 = {
    Text = "Cos'hai detto che cercavi prima? La Reliquia del Re? A cosa serve?"
  },
  AvgDialog_47166_Content_19 = {
    Text = "Risveglio del Re: devi trovare la sostanza d'argento lasciata dopo la morte del Re. È essenziale per il rito."
  },
  AvgDialog_47166_Content_2 = {
    Text = "Il fondo della nave raschia la sabbia fine, arrestandosi sulla riva. Miryam scende dalla nave, rivolgendo lo sguardo all'isola solitaria davanti a sé."
  },
  AvgDialog_47166_Content_20 = {
    Text = "In cosa consiste esattamente quel Rito? È simile a quello che hai usato per trasformarci in popolo-pesce?"
  },
  AvgDialog_47166_Content_21 = {
    Text = "Quindi, hai intenzione di dissotterrare il cadavere del tuo re e flagellarlo? È morto da decine di migliaia di anni; il suo corpo probabilmente andrebbe in pezzi al solo toccarlo..."
  },
  AvgDialog_47166_Content_22 = {Text = "Ssssh—"},
  AvgDialog_47166_Content_23 = {
    Text = "Il bagliore purpureo sul suo collo tremolò, e il dolore lancinante fece boccheggiare Golia."
  },
  AvgDialog_47166_Content_24 = {
    Text = "Mostra ancora una mancanza di rispetto al Re, e la Punizione sarà ben peggiore. Fai strada come si deve."
  },
  AvgDialog_47166_Content_25 = {Text = "..."},
  AvgDialog_47166_Content_26 = {
    Text = "Le erbacce e la fitta Foresta furono separate dalla nebbia nera, rivelando una piccola baia davanti a Tutti."
  },
  AvgDialog_47166_Content_27 = {
    Text = "Eh? Quando ho guardato dall'altra direzione poco fa, non vedevo questa baia? E la baia stessa sembra così strana..."
  },
  AvgDialog_47166_Content_28 = {
    Text = "Esatto, il suo aspetto cambia o addirittura svanisce quando la si osserva da direzioni diverse. Quindi suppongo debba trattarsi di qualche tipo di stregoneria o qualcosa del genere..."
  },
  AvgDialog_47166_Content_29 = {
    Text = "È un Sogno. Un Sogno creato dal re per proteggere Lemuria dagli invasori!"
  },
  AvgDialog_47166_Content_3 = {
    Text = "L'isola è estremamente piccola, simile a uno scoglio frastagliato. Una vegetazione antica e intricata la ricopre, narrando una lunga storia di solitudine."
  },
  AvgDialog_47166_Content_30 = {
    Text = "Lo Sguardo di Miryam inizia a colmarsi di eccitazione."
  },
  AvgDialog_47166_Content_31 = {Text = "\"Sogno\"?"},
  AvgDialog_47166_Content_32 = {
    Text = "Dove è stata trovata quella Statua?"
  },
  AvgDialog_47166_Content_33 = {
    Text = "Proprio lì."
  },
  AvgDialog_47166_Content_34 = {
    Text = "Golia indicò un Altare poco distante. L'Altare era ricoperto di erbacce, quasi irriconoscibile."
  },
  AvgDialog_47166_Content_35 = {
    Text = "Deborah estrasse la Statua di Tulu e la posò sull'Altare. La base combaciava perfettamente con l'Altare."
  },
  AvgDialog_47166_Content_36 = {
    Text = "Sembra che... non sia cambiato nulla... L'ho posizionata in modo sbagliato?"
  },
  AvgDialog_47166_Content_37 = {
    Text = "Se posizionarla lì avesse provocato qualche cambiamento, sarei entrato da tempo e avrei preso tutti gli oggetti di valore."
  },
  AvgDialog_47166_Content_38 = {
    Text = "Guardò Miryam con aria interrogativa. Lei si avvicinò all'Altare, estrasse un Pugnale e si tagliò un dito."
  },
  AvgDialog_47166_Content_39 = {
    Text = "Una goccia di Sangue Cremisi cadde dalle candide punte delle dita, posandosi sulla Statua."
  },
  AvgDialog_47166_Content_4 = {
    Text = "La perduta civiltà di Lemuria è un'antica leggenda tramandata tra le tribù di Filistea."
  },
  AvgDialog_47166_Content_40 = {Text = "Whoosh—"},
  AvgDialog_47166_Content_41 = {
    Text = "Un'increspatura sembrò propagarsi nell'aria, facendo tremare l'isola Isolata sotto i piedi di Tutti."
  },
  AvgDialog_47166_Content_42 = {Text = "Cosa...?"},
  AvgDialog_47166_Content_43 = {
    Text = "La forma della baia iniziò a sfumare mentre l'acqua marina vorticava e si innalzava verticalmente, formando un immenso Vortice, come un portale gigantesco che rivolgeva un invito a Tutti."
  },
  AvgDialog_47166_Content_44 = {
    Text = "Re, questa è la tomba che avete preparato per voi stesso... Il fuoco che avete lasciato per Lemuria è là dentro, non è vero?"
  },
  AvgDialog_47166_Content_45 = {
    Text = "Ehi, aspetta! Hai forse un desiderio di morte?!"
  },
  AvgDialog_47166_Content_46 = {
    Text = "Miryam si incamminò eccitata verso il centro del Vortice, ignorando i richiami di Golia. Golia imprecò e la seguì."
  },
  AvgDialog_47166_Content_47 = {
    Text = "Questo è... sott'acqua?"
  },
  AvgDialog_47166_Content_48 = {
    Text = "Possiamo respirare e parlare qui... È davvero un Miracolo!"
  },
  AvgDialog_47166_Content_49 = {
    Text = "Apparve una stretta scalinata di Pietra che conduceva verso il fondale marino insondabile. Seguirono Miryam nella discesa."
  },
  AvgDialog_47166_Content_5 = {
    Text = "Dopo una razzia costiera, la mia flotta fu colta da una tempesta e finì qui per caso."
  },
  AvgDialog_47166_Content_50 = {
    Text = "Cos'è quello... là davanti?"
  },
  AvgDialog_47166_Content_51 = {
    Text = "Dopo aver percorso i gradini di Pietra per un tempo imprecisato, una magnifica rovina apparve davanti a Tutti."
  },
  AvgDialog_47166_Content_52 = {
    Text = "Le scure colonne di Pietra si ergono solenni come guardie decapitate, reggendo le loro alabarde su entrambi i lati."
  },
  AvgDialog_47166_Content_53 = {
    Text = "Mura e strade di pietra colossale si sono spaccate e consumate dalla Decomposizione, con alghe luride che strisciano sui loro resti, narrando racconti di gloria passata e millenni di solitario Fato."
  },
  AvgDialog_47166_Content_54 = {
    Text = "Un gruppo di persone avanzava a fatica tra l'acqua marina e la ghiaia, arrampicandosi su gradini in rovina."
  },
  AvgDialog_47166_Content_55 = {
    Text = "Questo è... il Trono di Lemuria?"
  },
  AvgDialog_47166_Content_56 = {
    Text = "Un Trono di Pietra in frantumi si erge alla fine del Sentiero. Su di esso, uno Scheletro da lungo tempo defunto riposa il mento, contemplando con stanchezza i resti di Sogni passati."
  },
  AvgDialog_47166_Content_57 = {
    Text = "Siete voi, mio Signore... Sono le vostre spoglie! Vi ho trovato!"
  },
  AvgDialog_47166_Content_58 = {
    Text = "Sono passate decine di migliaia di anni, decine di migliaia di anni dall'ultima volta che vi ho visto..."
  },
  AvgDialog_47166_Content_59 = {
    Text = "Miryam si inchina devotamente e si inginocchia dinanzi alle ossa."
  },
  AvgDialog_47166_Content_6 = {
    Text = "La Statua è stata trovata proprio qui."
  },
  AvgDialog_47166_Content_60 = {
    Text = "Si alzò, affondando le mani in quel Corpo immondo. Quando le ritrasse, una Faint luce d'Argento apparve tra le rovine in penombra."
  },
  AvgDialog_47166_Content_61 = {
    Text = "Un globo d'Argento riposava nella Mano di Miryam, la sua superficie scintillava di luce fluente, proiettando riflessi onirici sott'acqua. Miryam si avvicinò, ascoltandone il respiro."
  },
  AvgDialog_47166_Content_62 = {
    Text = "Questa è quella che chiamate... materia d'Argento?"
  },
  AvgDialog_47166_Content_63 = {
    Text = "È diverso da ciò che diceva Talis... ma dev'essere quello che sto cercando!"
  },
  AvgDialog_47166_Content_64 = {
    Text = "Ne sei certa...? Questa cosa non sembra nulla di buono..."
  },
  AvgDialog_47166_Content_65 = {
    Text = "Se parlerai ancora male del re, ti concederò la morte più atroce."
  },
  AvgDialog_47166_Content_66 = {
    Text = "Scherzavo, perché così seria..."
  },
  AvgDialog_47166_Content_67 = {
    Text = "Hai detto che ciò che Talis ha descritto è diverso, quindi il suo metodo probabilmente non funzionerà. Qual è la tua prossima mossa?"
  },
  AvgDialog_47166_Content_68 = {
    Text = "Ho udito un battito su di esso... È il battito del re..."
  },
  AvgDialog_47166_Content_69 = {
    Text = "La sua Vita si sta spegnendo, lo sento... Fornirgli Vita resusciterà il re! Sì, dev'essere così!"
  },
  AvgDialog_47166_Content_7 = {
    Text = "C'è qualcos'altro?"
  },
  AvgDialog_47166_Content_70 = {
    Text = "Sguainò il suo Pugnale."
  },
  AvgDialog_47166_Content_71 = {
    Text = "Miryam! Cosa intendi fare?"
  },
  AvgDialog_47166_Content_72 = {
    Text = "Nutrire la Rinascita dalla Terra del re con la mia stessa Vita... Quale supremo onore... Questa è la mia missione!"
  },
  AvgDialog_47166_Content_73 = {
    Text = "Beneditemi, Deborah..."
  },
  AvgDialog_47166_Content_74 = {Text = "Puf—"},
  AvgDialog_47166_Content_75 = {
    Text = "Il Pugnale Rituale si conficcò nel petto di Miryam, torcendosi per scavare un Vuoto sanguinante."
  },
  AvgDialog_47166_Content_76 = {
    Text = "Innumerevoli spruzzi di Sangue si mescolarono all'acqua marina, vorticando attorno al Trono in rovina. Gli Scheletri, immersi nel Sangue caldo, osservavano freddamente la scena dinanzi a loro."
  },
  AvgDialog_47166_Content_77 = {
    Text = "Miryam sembrava del tutto indifferente al dolore, il suo sorriso si faceva sempre più fervente."
  },
  AvgDialog_47166_Content_78 = {
    Text = "Strinse il globo d'Argento fuso e lo inserì nel Vuoto nel suo petto."
  },
  AvgDialog_47166_Content_79 = {Text = "Ugh—"},
  AvgDialog_47166_Content_8 = {
    Text = "Ce ne sono alcune sparse qua e là; la maggior parte te le ho mostrate poco fa."
  },
  AvgDialog_47166_Content_80 = {
    Text = "Nell'istante in cui entrò nel Corpo di Miryam, il globo di luce emise un bagliore intenso e si contorse in preda alla Follia. Resisteva."
  },
  AvgDialog_47166_Content_81 = {
    Text = "La Vita di Miryam fluisce in esso, viene consumata e poi scartata."
  },
  AvgDialog_47166_Content_82 = {
    Text = "Le fiamme bruciavano ogni centimetro della sua pelle, le lame laceravano ogni brandello della sua Caro. Un dolore senza fine sopraffaceva Miryam, che lottava per mantenere il suo sorriso contorto."
  },
  AvgDialog_47166_Content_83 = {
    Text = "Mio Signore... vi prego... accettatemi..."
  },
  AvgDialog_47166_Content_84 = {Text = "Bang—"},
  AvgDialog_47166_Content_85 = {Text = "Miryam!"},
  AvgDialog_47166_Content_86 = {
    Text = "Miryam non riuscì più a resistere e perse i sensi."
  },
  AvgDialog_47166_Content_87 = {
    Text = "Rimuovete quella cosa Minacciosa dal suo Corpo e portatela a bordo della nave."
  },
  AvgDialog_47166_Content_88 = {
    Text = "Ma Miryam ha detto..."
  },
  AvgDialog_47166_Content_89 = {
    Text = "Se vuoi che viva, fallo adesso."
  },
  AvgDialog_47166_Content_9 = {
    Text = "Ho perlustrato l'intera isola e non ho trovato rovine, solo queste cianfrusaglie."
  },
  AvgDialog_47166_Content_90 = {Text = "..."},
  AvgDialog_47166_Content_91 = {
    Text = "La Nebbia e le onde si erano dissipate, lasciando l'isola come un solitario punto nero in lontananza."
  },
  AvgDialog_47166_Content_92 = {
    Text = "Golia si appoggiò alla ringhiera della nave, godendosi il dolce dondolio dell'imbarcazione."
  },
  AvgDialog_47166_Content_93 = {
    Text = "Lord Golia, sembrate di buon umore. Questo Sole vi ricorda forse la costa della vostra terra natale, la Filistea?"
  },
  AvgDialog_47166_Content_94 = {
    Text = "La costa del mio Focolare? Ha. Stavo solo pensando che, se uccidessi Miryam adesso, potrei andare ovunque."
  },
  AvgDialog_47166_Content_95 = {
    Text = "Eh? Maestro, questo... non mi sembra giusto..."
  },
  AvgDialog_47166_Content_96 = {
    Text = "Il Potere di Miryam supera di gran lunga il mio. Ora è gravemente ferita; se perdo l'occasione oggi, potrei non averne mai un'altra."
  },
  AvgDialog_47166_Content_97 = {
    Text = "Voi non fareste mai una cosa del genere."
  },
  AvgDialog_47166_Content_98 = {
    Text = "Cosa? Pensate che io sia una specie di cuore tenero?"
  },
  AvgDialog_47166_Content_99 = {
    Text = "Non è quello... Se aveste davvero intenzione di ucciderla, lo avreste già fatto, invece di stare qui a fare Chiacchiere con me."
  },
  AvgDialog_47167_Content_1 = {
    Text = "Avvolto nella Nebbia"
  },
  AvgDialog_47167_Content_10 = {
    Text = "Che miseria. Il gigante rivolge un ultimo Sguardo della Fine al suo Seguace morente lì accanto, accenna un sorriso cupo, poi chiude gli occhi."
  },
  AvgDialog_47167_Content_100 = {
    Text = "Avete già i mezzi per controllarmi. La mia Lealtà verso di voi dovrebbe essere ancor più Irremovibile."
  },
  AvgDialog_47167_Content_101 = {
    Text = "La nostra alleanza resta in vigore. Nessuno è un partner migliore di me. Accettate il mio servizio, e che la nostra cooperazione prosegua."
  },
  AvgDialog_47167_Content_102 = {
    Text = "Come sai, non sono una persona leale, ma ciò di cui hai bisogno è la mia abilità, non la mia lealtà, giusto?"
  },
  AvgDialog_47167_Content_103 = {
    Text = "Miryam guardò Golia con sorpresa e, dopo un istante, sorrise."
  },
  AvgDialog_47167_Content_104 = {
    Text = "La tua astuzia e la tua bassezza mi sorprendono... Hai ragione, Golia. Una persona come te può fare molte cose che io non posso."
  },
  AvgDialog_47167_Content_105 = {
    Text = "Proseguiamo la nostra collaborazione?"
  },
  AvgDialog_47167_Content_106 = {
    Text = "Golia sorrise e tese la mano, ma Miryam la ignorò e si voltò per dirigersi verso il baldacchino della nave."
  },
  AvgDialog_47167_Content_107 = {
    Text = "D'ora in poi, chiamami Vecchio Sommo Sacerdote."
  },
  AvgDialog_47167_Content_108 = {
    Text = "Golia ritirò la mano, sfiorando il marchio sul collo. Sorrise mentre contemplava il mare, le sue nuove zanne che brillavano affilate alla luce del sole."
  },
  AvgDialog_47167_Content_109 = {
    Text = "È un piacere fare affari con voi, Somma Sacerdotessa."
  },
  AvgDialog_47167_Content_11 = {
    Text = "Piangiamo la nostra luce, la nostra speranza."
  },
  AvgDialog_47167_Content_12 = {
    Text = "Esiliati verso il mare dal Fato, piangiamo, ci lamentiamo, e versiamo tutte le nostre lacrime..."
  },
  AvgDialog_47167_Content_13 = {
    Text = "<Italic:Un'allucinazione in punto di morte>, pensa il gigante confusamente."
  },
  AvgDialog_47167_Content_14 = {
    Text = "Una Cantilena antica e inquietante gli giunge alle orecchie. Attraverso la fitta nebbia, la figura di una Donna emerge nella sua Visuale che si oscura."
  },
  AvgDialog_47167_Content_15 = {
    Text = "Ah, Miryam, è lui, quel gigante Filisteo! La costa è piena di leggende su di lui..."
  },
  AvgDialog_47167_Content_16 = {
    Text = "Ma... sta morendo?"
  },
  AvgDialog_47167_Content_17 = {
    Text = "Non morirà."
  },
  AvgDialog_47167_Content_18 = {
    Text = "Una sensazione morbida e gelida proviene dal punto in cui i serpenti d'onice gli si intrecciano attorno al collo. Gli occhi torbidi e scuri del gigante si fanno gradualmente limpidi."
  },
  AvgDialog_47167_Content_19 = {
    Text = "La strega, è la strega!"
  },
  AvgDialog_47167_Content_2 = {Text = "@2—"},
  AvgDialog_47167_Content_20 = {
    Text = "Ciò che la Casa Ornn ha incontrato si è propagato attraverso i mari. Ora lei emerge dalla nebbia delle dicerie, ergendosi dinanzi a loro."
  },
  AvgDialog_47167_Content_21 = {
    Text = "Le iene Filistee infine tornano in sé. Cominciano a fuggire o a lanciarsi sulla sua piccola imbarcazione per un ultimo, disperato scontro."
  },
  AvgDialog_47167_Content_22 = {
    Text = "Miryam guarda il gigante attonito, sorride debolmente e indica in lontananza. Poi dà una pacca sulla spalla a Deborah, e cominciano a virare la barca."
  },
  AvgDialog_47167_Content_23 = {
    Text = "Non ha alcun interesse per la fuga e le contorsioni delle iene."
  },
  AvgDialog_47167_Content_24 = {
    Text = "I serpenti d'onice strisciano, cacciano, mordono e divorano. Nella fitta nebbia sul mare, sempre più corpi dilaniati cominciano ad affiorare in superficie."
  },
  AvgDialog_47167_Content_25 = {
    Text = "La silenziosa carneficina si concluse rapidamente, lasciando un mare macchiato di sangue e l'espressione attonita del gigante."
  },
  AvgDialog_47167_Content_26 = {Text = "..."},
  AvgDialog_47167_Content_27 = {
    Text = "Miryam, perché andartene ora che l'hai trovato?"
  },
  AvgDialog_47167_Content_28 = {
    Text = "Cercare il nostro Signore è una missione sacra. Egli non vorrebbe che ne discutessi in un luogo così immondo."
  },
  AvgDialog_47167_Content_29 = {
    Text = "Ma non hai detto una parola a quel colosso... Verrà a cercarti?"
  },
  AvgDialog_47167_Content_3 = {
    Text = "Con un grugnito sommesso, il gigante estrae la freccia acuminata conficcata nella sua spalla."
  },
  AvgDialog_47167_Content_30 = {
    Text = "Signore, attendete un momento!"
  },
  AvgDialog_47167_Content_31 = {
    Text = "Una Voce perfora la fitta nebbia. Deborah fa la linguaccia a Miryam, portando gradualmente la barca a fermarsi."
  },
  AvgDialog_47167_Content_32 = {
    Text = "Ben presto, un'imbarcazione di legno malconcia si ferma davanti al loro vascello."
  },
  AvgDialog_47167_Content_33 = {
    Text = "Il Veleno non è stato ancora del tutto eliminato dal tuo organismo. Considerata la velocità di navigazione dei Filistei, puoi concederti un po' di Riposo prima di tornare da me."
  },
  AvgDialog_47167_Content_34 = {
    Text = "Un graffio come questo non è nulla in confronto alla posta in gioco dell'accordo che intendo proporre."
  },
  AvgDialog_47167_Content_35 = {
    Text = "Non ho mai detto di voler fare un accordo con te."
  },
  AvgDialog_47167_Content_36 = {
    Text = [[
Non voglio farti perdere tempo, Signora Strega.
So di Lemuria, e credo sia per questo che mi hai cercato.]]
  },
  AvgDialog_47167_Content_37 = {
    Text = "Sai cosa voglio?"
  },
  AvgDialog_47167_Content_38 = {
    Text = "Ciò che hai fatto al Filisteo al maniero degli Ornn si è propagato attraverso i mari. Francamente, non ho mai dato molto credito a simili leggende."
  },
  AvgDialog_47167_Content_39 = {
    Text = "Ma ora vi siete avvicinata a me. Deve esserci una ragione per questo."
  },
  AvgDialog_47167_Content_4 = {
    Text = "Sangue avvelenato schizza dalla sua spalla sul ponte, macchiandolo come una palude di nero immondo sotto la luce del sole."
  },
  AvgDialog_47167_Content_40 = {
    Text = "Si vocifera che siate molto interessata a quelle statue nere. Le ho trovate, e so cosa rappresentano."
  },
  AvgDialog_47167_Content_41 = {
    Text = "Dimmi ciò che sai."
  },
  AvgDialog_47167_Content_42 = {
    Text = "Prima di ciò, Signora Strega, forse possiamo raggiungere un accordo di cooperazione."
  },
  AvgDialog_47167_Content_43 = {
    Text = "Ho assistito al tuo grande potere... Credo che dovresti essere in grado di conferire questo potere anche a me, non è vero?"
  },
  AvgDialog_47167_Content_44 = {
    Text = "Ho molti modi per farti parlare, Filistea. Cosa ti fa credere di essere nella posizione di trattare?"
  },
  AvgDialog_47167_Content_45 = {
    Text = "Mi fraintendete, Signora Strega... Voi mi avete salvato la vita. Anche se non desiderate trattare con me, vi offrirò comunque ogni informazione in mio possesso, senza riserve."
  },
  AvgDialog_47167_Content_46 = {
    Text = "Ciò che voglio scambiare con voi non è questa informazione."
  },
  AvgDialog_47167_Content_47 = {
    Text = "Cos'altro puoi offrirmi?"
  },
  AvgDialog_47167_Content_48 = {
    Text = "La mia Lealtà."
  },
  AvgDialog_47167_Content_49 = {
    Text = "Non mi interessa la tua lealtà, Golia."
  },
  AvgDialog_47167_Content_5 = {
    Text = "Ben giocato, Iglenn... I Filistei... ricorrono a questi trucchi, ormai..."
  },
  AvgDialog_47167_Content_50 = {
    Text = "Davvero? Ho sentito del vostro controllo sulla famiglia Ornn, davvero impressionante... Signora Strega, avete bisogno di manodopera per un certo grande compito, non è così?"
  },
  AvgDialog_47167_Content_51 = {
    Text = "Quante persone potete comandare dopo tutti i vostri estenuanti sforzi? Chi può assistervi nella gestione della vostra caccia a ciò che desiderate?"
  },
  AvgDialog_47167_Content_52 = {
    Text = "Parlando con franchezza, mia signora, siete potente, ma le questioni del cuore, il potere e la vera arte di uccidere non sono il vostro forte."
  },
  AvgDialog_47167_Content_53 = {
    Text = "Non so quale sia la vostra grande impresa. Ma avrete sicuramente bisogno del mio aiuto."
  },
  AvgDialog_47167_Content_54 = {
    Text = "Vi prego, accettate la mia lealtà! Vi recherà grande beneficio e nessun danno."
  },
  AvgDialog_47167_Content_55 = {
    Text = "Miryam lo fissò in silenzio. Dopo un istante, annuì."
  },
  AvgDialog_47167_Content_56 = {
    Text = "La tua persuasione mi ha convinta, Golia. Hai dimostrato la tua abilità."
  },
  AvgDialog_47167_Content_57 = {
    Text = "Ora, getta la tua lama nel mare."
  },
  AvgDialog_47167_Content_58 = {
    Text = "Il mio coltello..."
  },
  AvgDialog_47167_Content_59 = {
    Text = "Golia lanciò un'occhiata alla lama gigante che lo aveva accompagnato per anni, strinse i denti e la gettò in mare."
  },
  AvgDialog_47167_Content_6 = {
    Text = "La sua Visuale si offusca e la mente si fa torpida. Non riesce più a reggersi in piedi. Con un fragore di tuono, crolla sul ponte."
  },
  AvgDialog_47167_Content_60 = {
    Text = "La nave tremò, come se qualcosa stesse agitando il mare sotto di essa."
  },
  AvgDialog_47167_Content_61 = {
    Text = "Miryam tese la mano. La lama gigante balzò fuori dal mare, emanando un bagliore oscuro mai visto prima."
  },
  AvgDialog_47167_Content_62 = {
    Text = "La lama immensa cadde nella mano di Miryam, retta con la leggerezza di una piuma dalle sue dita sottili."
  },
  AvgDialog_47167_Content_63 = {
    Text = "Hai paura del dolore?"
  },
  AvgDialog_47167_Content_64 = {
    Text = "Assaporo il dolore, mia signora strega."
  },
  AvgDialog_47167_Content_65 = {
    Text = "Golia sorrise, inginocchiandosi dinanzi a Miryam."
  },
  AvgDialog_47167_Content_66 = {
    Text = "Miryam accostò la lama gigante al collo di Golia."
  },
  AvgDialog_47167_Content_67 = {
    Text = "Maestro Golia!"
  },
  AvgDialog_47167_Content_68 = {Text = "Puf—"},
  AvgDialog_47167_Content_69 = {
    Text = "La lama immensa si abbatté sul collo di Golia, recidendolo in due con facilità, e il sangue sgorgò a fiotti."
  },
  AvgDialog_47167_Content_7 = {
    Text = "Golia... Il gigante Golia è finalmente caduto!"
  },
  AvgDialog_47167_Content_70 = {
    Text = "Prima che chiunque nei paraggi potesse reagire, una faint luce nero-purpurea tremolò sulla ferita al collo di Golia."
  },
  AvgDialog_47167_Content_71 = {
    Text = "Si muove, incidendo un motivo intricato e antico sulla pelle scura."
  },
  AvgDialog_47167_Content_72 = {Text = "Ugh!!!—"},
  AvgDialog_47167_Content_73 = {
    Text = "Un dolore intenso si propagò come un'ondata attraverso Golia. Non proveniva soltanto dalla ferita, ma percorreva il suo corpo intero."
  },
  AvgDialog_47167_Content_74 = {
    Text = "Il sudore colava sulla fronte del gigante. Digrignava i denti, il corpo intero scosso dai tremiti mentre lottava contro il dolore."
  },
  AvgDialog_47167_Content_75 = {
    Text = "Tra dolori lancinanti, lame simili a pinne spuntarono dalle orecchie di Golia, i suoi denti divennero affilati e stratificati, e i suoi occhi si tinsero di cremisi."
  },
  AvgDialog_47167_Content_76 = {
    Text = "Signore Golia... voi... voi adesso..."
  },
  AvgDialog_47167_Content_77 = {
    Text = "Fu un processo incredibilmente lungo. Golia ebbe l'impressione di aver sopportato un anno di dolore lancinante. In quel periodo interminabile, morì nel dolore e rinacque nell'Agonia."
  },
  AvgDialog_47167_Content_78 = {
    Text = "Quando la coscienza di Golia tornò limpida, si rese conto che il Rito era terminato da tempo. Giaceva bocconi sulla nave, il sudore del dolore aveva inzuppato il ponte."
  },
  AvgDialog_47167_Content_79 = {
    Text = "Contemplò il proprio riflesso sul mare. I tratti di un uomo-pesce erano chiaramente visibili sul suo corpo gigantesco. Un feroce squalo si rivelò davanti a Tutti."
  },
  AvgDialog_47167_Content_8 = {
    Text = "La sua testa è mia! Nessuno me la porterà via!!!"
  },
  AvgDialog_47167_Content_80 = {
    Text = "La profondità della tua trasformazione è determinata dal tuo potenziale. Hai molto talento, Golia."
  },
  AvgDialog_47167_Content_81 = {
    Text = "Godi della tua forza."
  },
  AvgDialog_47167_Content_82 = {
    Text = "Un'Ondata di Potere senza precedenti percorse il corpo di Golia. Sollevò senza sforzo la Lama gigantesca accanto a sé e la fendette verso l'acqua."
  },
  AvgDialog_47167_Content_83 = {Text = "Boom—"},
  AvgDialog_47167_Content_84 = {
    Text = "Il mare calmo si sollevò in onde massicce, sballottando due piccole imbarcazioni e facendole oscillare violentemente."
  },
  AvgDialog_47167_Content_85 = {
    Text = "Hehehehe... Hahahaha!!!"
  },
  AvgDialog_47167_Content_86 = {
    Text = "Nel mezzo del violento scuotimento, Golia scoppiò in una fragorosa risata. Si voltò verso Miryam, la luce rossa che lampeggiava feroce nei suoi occhi."
  },
  AvgDialog_47167_Content_87 = {
    Text = "Grazie, Signora Strega. Mi godrò immensamente il Potere che mi avete concesso."
  },
  AvgDialog_47167_Content_88 = {
    Text = "Mi perdoni, non ho tempo di giurarle la mia Lealtà. I traditori e i nemici di Filistea attendono che io li abbatta."
  },
  AvgDialog_47167_Content_89 = {
    Text = "Non incolpi me. Incolpi se stessa per aver abbassato la Guardia. D'ora in poi, la onorerò col sangue dei nostri nemici!"
  },
  AvgDialog_47167_Content_9 = {
    Text = "I Filistei, che solo pochi istanti fa si rannicchiavano al cospetto di Golia, ora gli si avventano addosso come iene frenetiche e rapaci che fiutano la carcassa di un leone."
  },
  AvgDialog_47167_Content_90 = {
    Text = "Golia scagliò improvvisamente la sua Lama contro Miryam. Tuttavia, quando la possente Lama la raggiunse, si bloccò di colpo, perdendo tutto il suo Potere."
  },
  AvgDialog_47167_Content_91 = {Text = "Hmm—ah!!"},
  AvgDialog_47167_Content_92 = {
    Text = "La cicatrice sul collo di Golia si illuminò di una luce purpurea serpentina. Crollò in Agonia mentre il dolore lancinante e agghiacciante tornava con furia vendicativa, e il Potere dentro di lui svanì senza lasciare traccia."
  },
  AvgDialog_47167_Content_93 = {
    Text = "Cosa... hai... fatto..."
  },
  AvgDialog_47167_Content_94 = {
    Text = "Sono la Somma Sacerdotessa di Lemuria. Non sono davvero esperta nelle questioni che hai menzionato, ma conosco molto bene la natura umana, filisteo."
  },
  AvgDialog_47167_Content_95 = {
    Text = "Dolore e Potere, ti concedo entrambi. Ovunque tu sia, per quanto Forte tu diventi, posso privarti del Potere e riportare il tuo dolore a mio piacimento."
  },
  AvgDialog_47167_Content_96 = {
    Text = "Ti piace, non è vero?"
  },
  AvgDialog_47167_Content_97 = {
    Text = "Impressionante... Signora Strega..."
  },
  AvgDialog_47167_Content_98 = {
    Text = "Dimmi ciò che sai, e ti concederò una morte indolore."
  },
  AvgDialog_47167_Content_99 = {
    Text = "È solo un piccolo incidente... Perché preoccuparsi, Signora Strega?"
  },
  AvgDialog_47168_Content_1 = {
    Text = "Banchetto di Sangue"
  },
  AvgDialog_47168_Content_10 = {
    Text = "Non fa niente, non fa niente, è solo un ritrovo di famiglia. Il tuo corpo sta bene?"
  },
  AvgDialog_47168_Content_100 = {
    Text = "Hahaha, non è così semplice!"
  },
  AvgDialog_47168_Content_101 = {
    Text = "Incantesimi, corpi, e..."
  },
  AvgDialog_47168_Content_102 = {
    Text = "I suoi occhi annebbiati si spalancarono di colpo, e d'un tratto mormorò un'aspra, silenziosa formula rituale."
  },
  AvgDialog_47168_Content_103 = {Text = "Ah!—"},
  AvgDialog_47168_Content_104 = {
    Text = "Miryam si inginocchia a terra. Un dolore acuto come aghi assale il suo spirito, travolgendola con un'immensa sofferenza."
  },
  AvgDialog_47168_Content_105 = {
    Text = "@2, credi che non sappia cosa stai pensando?"
  },
  AvgDialog_47168_Content_106 = {
    Text = "Chiamami \"Padre\" e fa' cose per me... Ma ciò che desideri davvero è altro, non è vero?"
  },
  AvgDialog_47168_Content_107 = {
    Text = "Miryam, non so com'è la tua terra natale, ma è evidente che non hai idea di cosa significhi lottare."
  },
  AvgDialog_47168_Content_108 = {
    Text = "Se fossi stato uno sciocco, mi avrebbero annegato nella stalla quando avevo sei anni e non sarei mai arrivato a oggi."
  },
  AvgDialog_47168_Content_109 = {
    Text = "Come una corda invisibile tirata sempre più stretta, il dolore spirituale di Miryam si fa più intenso."
  },
  AvgDialog_47168_Content_11 = {
    Text = "Quasi finito. Ah, c'è anche il fratello maggiore?"
  },
  AvgDialog_47168_Content_110 = {
    Text = "Sei forte, e allora? Non sei che un Cane da Caccia; fai quello che ti dico!"
  },
  AvgDialog_47168_Content_111 = {
    Text = "Il mio scopo è ormai Completo, e al momento non ho bisogno di te. Risvegliarti sarebbe problematico, ma tenere un'arma dotata di pensiero proprio lo è ancora di più."
  },
  AvgDialog_47168_Content_112 = {
    Text = "Quindi, muori ancora una volta. Non preoccuparti, ti farò rivedere il sole quando avrò bisogno di te..."
  },
  AvgDialog_47168_Content_113 = {
    Text = "Talis fulminò Miryam con lo sguardo, intonando un incantesimo. La corda invisibile si strinse in un cappio attorno al collo di Miryam."
  },
  AvgDialog_47168_Content_114 = {
    Text = "Talis stringe improvvisamente la presa sul cappio..."
  },
  AvgDialog_47168_Content_115 = {
    Text = "??! Che cosa... sta succedendo?!"
  },
  AvgDialog_47168_Content_116 = {
    Text = "Il cappio era ancora lì, ma Talis non riusciva più a percepirne il controllo. Per quanti incantesimi lanciasse, la corda restava inerte, immobile."
  },
  AvgDialog_47168_Content_117 = {Text = "Whoosh—"},
  AvgDialog_47168_Content_118 = {Text = "Ah!!—"},
  AvgDialog_47168_Content_119 = {
    Text = "Un dolore acuto attraversò il corpo di Talis. Una lunga Ferita rettilinea apparve sul suo petto, come se qualcuno l'avesse incisa con cura e deliberatamente usando un Pugnale."
  },
  AvgDialog_47168_Content_12 = {
    Text = "Talis sorrise e gli fece un inchino."
  },
  AvgDialog_47168_Content_120 = {
    Text = "Gli Ospiti nella sala ammutolirono in fretta, restando immobili mentre le guardie li circondavano con le armi puntate, senza tuttavia osare avvicinarsi ulteriormente a Miryam."
  },
  AvgDialog_47168_Content_121 = {
    Text = "Questo... Che cos'è...?"
  },
  AvgDialog_47168_Content_122 = {
    Text = "È il rito di conversione degli uomini-pesce."
  },
  AvgDialog_47168_Content_123 = {
    Text = "Prima dovevo usare un Pugnale per aprire il corpo di una persona e infondere il Sangue divino nel suo organismo. Ma ora non è più necessario."
  },
  AvgDialog_47168_Content_124 = {
    Text = "Basta bere il mio Sangue e catalizzarlo con il mio Potere, e il Rito sarà Completo."
  },
  AvgDialog_47168_Content_125 = {
    Text = "Il vostro Sangue... è stato aggiunto, aggiunto a..."
  },
  AvgDialog_47168_Content_126 = {
    Text = "Nel vino, esatto. A questo Banchetto, ne avete già bevuto."
  },
  AvgDialog_47168_Content_127 = {
    Text = "Miryam si alza e si spolvera il corpo."
  },
  AvgDialog_47168_Content_128 = {
    Text = "Voi... avevate già pensato a tutto..."
  },
  AvgDialog_47168_Content_129 = {
    Text = "La gente di questo mondo è cambiata. Fede, famiglia, dignità... nulla di tutto ciò ha valore ai vostri occhi. Lo so fin troppo bene, Talis."
  },
  AvgDialog_47168_Content_13 = {
    Text = "Sono appena arrivato anch'io e stavo per presentare un dono a nostro padre."
  },
  AvgDialog_47168_Content_130 = {
    Text = "Non temere, porterò un mondo migliore. Aiutarti a diventare il capofamiglia della Casa Ornn farà della famiglia il mio strumento in questa sacra impresa."
  },
  AvgDialog_47168_Content_131 = {
    Text = "Avete cuori vili, indegni del Reame Divino. Ma avete portato a compimento la missione della mia Rinascita dalla Terra — considerate dunque questo il mio dono in cambio."
  },
  AvgDialog_47168_Content_132 = {
    Text = "Potete... trattare con me... Non dovete per forza..."
  },
  AvgDialog_47168_Content_133 = {
    Text = "I Cani da Caccia non hanno diritto al Baratto. Perciò, non posso che diventare la vostra padrona. Ora, credo di averne i requisiti."
  },
  AvgDialog_47168_Content_134 = {
    Text = "Voglio rianimare qualcuno. Dimmi, cosa devo fare?"
  },
  AvgDialog_47168_Content_135 = {
    Text = "Ho detto: \"Potete lasciarmi vivere?\""
  },
  AvgDialog_47168_Content_136 = {Text = "Ah!!—"},
  AvgDialog_47168_Content_137 = {
    Text = "Miryam non disse nulla. Una profonda Ferita apparve su Talis, e il Sangue sgorgò copioso."
  },
  AvgDialog_47168_Content_138 = {
    Text = "Parlo! Parlo!"
  },
  AvgDialog_47168_Content_139 = {
    Text = "Nel mio studio... dentro la scrivania... c'è un libro che raccoglie tutti i risultati della mia Ricerca."
  },
  AvgDialog_47168_Content_14 = {
    Text = "Bene, ora tutti voi fratelli siete presenti."
  },
  AvgDialog_47168_Content_140 = {
    Text = "Tutto sul Golem è scritto qui dentro!"
  },
  AvgDialog_47168_Content_141 = {
    Text = "Miryam gli lancia un'occhiata e annuisce."
  },
  AvgDialog_47168_Content_142 = {
    Text = "So che stai dicendo la verità."
  },
  AvgDialog_47168_Content_143 = {
    Text = "Hai ragione, i Lemuriani non conoscono simili conflitti."
  },
  AvgDialog_47168_Content_144 = {
    Text = "Tuttavia, quando si ha una missione divina da compiere, apprendere queste cose non è più difficile."
  },
  AvgDialog_47168_Content_145 = {
    Text = "Esatto, esatto... Quindi posso andarmene adesso?"
  },
  AvgDialog_47168_Content_146 = {Text = "ARGH!!"},
  AvgDialog_47168_Content_147 = {
    Text = "Le ferite continuavano a comparire su di lui. Le linee di sangue e carne si intrecciavano, formando un motivo di un'antica civiltà."
  },
  AvgDialog_47168_Content_148 = {
    Text = "Nel frattempo, quelle stesse linee apparvero sulla maggior parte degli ospiti e delle guardie. Urla miste a sangue schizzarono in ogni angolo della sala."
  },
  AvgDialog_47168_Content_149 = {
    Text = "La lussuosa sala si trasformò in un inferno di sangue e carne, colma dei lamenti della famiglia Ornn."
  },
  AvgDialog_47168_Content_15 = {
    Text = "Il banchetto è in preparazione. Prima di ciò, vi sono alcune questioni importanti di cui devo discutere con voi. Riguardano le mie ultime volontà."
  },
  AvgDialog_47168_Content_150 = {
    Text = "Il volto di Talis cominciò a deformarsi, scaglie di pesce affiorarono sulla sua pelle. Le sue grida laceranti si fecero rauche e flebili, intrise del sentore di Aequor."
  },
  AvgDialog_47168_Content_151 = {
    Text = "Questa terra è in Decomposizione... Mostrerò loro un Reame Divino perfetto."
  },
  AvgDialog_47168_Content_152 = {
    Text = "Il Re diceva la verità. Il Reame Divino sta arrivando... So già dove trovarLo. Aspetta ancora un poco, e presto saremo riuniti."
  },
  AvgDialog_47168_Content_153 = {
    Text = "Le grida strazianti di Talis sono quasi cessate. Sotto la potente influenza di Miryam, la sua trasformazione in creatura marina è ancora più completa di quella degli antichi Lemuriani."
  },
  AvgDialog_47168_Content_154 = {
    Text = "Si chinò, sfiorando il volto deforme di Talis e le sue braccia squamose. Tra il sangue e le grida che riempivano la stanza, pianse e sorrise."
  },
  AvgDialog_47168_Content_155 = {
    Text = "È da tanto che non ci vediamo, Padre."
  },
  AvgDialog_47168_Content_156 = {
    Text = "Rivolge il suo saluto più tenero alla creatura che si contorce e soffre dinanzi a lei."
  },
  AvgDialog_47168_Content_16 = {
    Text = "Padre! Vi prego, non dite così..."
  },
  AvgDialog_47168_Content_17 = {
    Text = "Il secondogenito avanzò di due passi e sorresse il braccio dell'anziano. L'anziano gli accarezzò dolcemente il dorso della mano."
  },
  AvgDialog_47168_Content_18 = {
    Text = "Lasciatemi finire. Conosco abbastanza bene le mie condizioni. Alcune cose devono essere disposte in anticipo, se la Casa Ornn vuole prosperare."
  },
  AvgDialog_47168_Content_19 = {
    Text = "Dopo il banchetto di stasera, cederò la posizione di Capo della Famiglia Ornn al mio secondogenito. Ho intenzione di godermi qualche anno di tranquillità."
  },
  AvgDialog_47168_Content_2 = {
    Text = "I miei omaggi a voi, Padre, eterno condottiero della famiglia Ornn."
  },
  AvgDialog_47168_Content_20 = {
    Text = "Padre, ma... è così improvviso. Non sono ancora pronto..."
  },
  AvgDialog_47168_Content_21 = {
    Text = "Sei il più nobile erede della Casa Ornn, con il lignaggio più puro e la migliore educazione. Questa fu la mia promessa a tua madre, e la manterrò."
  },
  AvgDialog_47168_Content_22 = {
    Text = "Stai tranquillo, ho già informato i vecchi amici di famiglia. Anche i tuoi fratelli ti aiuteranno."
  },
  AvgDialog_47168_Content_23 = {
    Text = "Lanciò un'occhiata agli altri figli."
  },
  AvgDialog_47168_Content_24 = {
    Text = "Il tuo territorio resta invariato. Comprendo il tuo legame con il secondo anziano. Il titolo di capoclan non è che un nome; siamo tutti una sola famiglia e dobbiamo restare uniti."
  },
  AvgDialog_47168_Content_25 = {
    Text = "Quanto a voi..."
  },
  AvgDialog_47168_Content_26 = {
    Text = "Alzò lo sguardo, fissando Talis."
  },
  AvgDialog_47168_Content_27 = {
    Text = "Nemmeno il tuo territorio cambierà. Tuttavia, ultimamente ti sei preoccupato di troppe cose."
  },
  AvgDialog_47168_Content_28 = {
    Text = "Stai invecchiando. Cedi il comando del tuo esercito a tuo fratello. Credo che anche tu, come me, dovresti goderti una vita più tranquilla."
  },
  AvgDialog_47168_Content_29 = {Text = "..."},
  AvgDialog_47168_Content_3 = {
    Text = "Talis si inchinò, e Miryam, in piedi dietro di lui, rivolse un lieve cenno del capo all'anziano uomo seduto al posto d'onore."
  },
  AvgDialog_47168_Content_30 = {
    Text = "È un comando a cui non ci si può opporre, giusto?"
  },
  AvgDialog_47168_Content_31 = {
    Text = "Il vecchio sembrava aver previsto quella risposta, e si adagiò contro lo schienale della sedia."
  },
  AvgDialog_47168_Content_32 = {
    Text = "Tre giorni fa, ho inviato truppe verso la vostra base."
  },
  AvgDialog_47168_Content_33 = {
    Text = "Sono sempre stato consapevole della tua ambizione, ma sei pur sempre mio figlio. Ti darò la possibilità di scegliere."
  },
  AvgDialog_47168_Content_34 = {
    Text = "Questa è una decisione che ho preso per il bene a lungo termine della famiglia Ornn. Spero che non me ne vorrai."
  },
  AvgDialog_47168_Content_35 = {
    Text = "...Come potrebbe essere, Padre? Devo ringraziarvi."
  },
  AvgDialog_47168_Content_36 = {
    Text = "Talis lasciò trasparire un sorriso sollevato."
  },
  AvgDialog_47168_Content_37 = {
    Text = "Lungo il cammino fin qui, al solo pensiero di ciò che devo fare, non puoi immaginare quanto ne sia stato tormentato..."
  },
  AvgDialog_47168_Content_38 = {
    Text = "Grazie, e grazie a tutti voi, fratelli miei. Ora sono libero da ogni fardello."
  },
  AvgDialog_47168_Content_39 = {
    Text = "Il vecchio batté le dita sulla sedia, e una squadra di guardie irruppe da dietro la tenda, circondando Thaïs e Miryam."
  },
  AvgDialog_47168_Content_4 = {
    Text = "Il vecchio agitò la mano con impazienza."
  },
  AvgDialog_47168_Content_40 = {
    Text = "Accanto a lui, il secondogenito spalancò gli occhi, la voce resa roca dalla tensione."
  },
  AvgDialog_47168_Content_41 = {
    Text = "\"Padre? Che cosa state...\""
  },
  AvgDialog_47168_Content_42 = {
    Text = "Hai davvero preparato ogni cosa con tale meticolosità, Padre. Stanziare le mie guardie fuori dalla città e confiscare le mie armi mi ha privato di ogni possibilità."
  },
  AvgDialog_47168_Content_43 = {
    Text = "Un bastardo nato da un'ancella, senza istruzione, a sprecare le giornate con la tua ridicola alchimia e le tue assurde ambizioni... Non provi alcun sentimento per la tua famiglia; tutto ciò che desideri è il potere."
  },
  AvgDialog_47168_Content_44 = {
    Text = "Ti ho sopportato fin troppo a lungo; ho fatto il mio dovere."
  },
  AvgDialog_47168_Content_45 = {
    Text = "I soldati sguainano le spade e avanzano. Talis fa un cenno, e Miryam si fa avanti. Dietro di lei, una nebbia nera si addensa e si attorciglia."
  },
  AvgDialog_47168_Content_46 = {
    Text = "Questa Ancella? ..."
  },
  AvgDialog_47168_Content_47 = {
    Text = "Sono d'accordo, Padre. Mi hai tollerato, forse fin troppo."
  },
  AvgDialog_47168_Content_48 = {
    Text = "Ammirate gli assurdi risultati della mia Alchimia, Padre!"
  },
  AvgDialog_47168_Content_49 = {
    Text = "Il soldato avvertì il pericolo e si lanciò contro i due."
  },
  AvgDialog_47168_Content_5 = {
    Text = "\"In quanto fratello maggiore, dovresti dare l'esempio agli altri. Non sei nemmeno capace di insegnare le buone maniere a un servitore?\""
  },
  AvgDialog_47168_Content_50 = {Text = "Swish—"},
  AvgDialog_47168_Content_51 = {
    Text = "Una nebbia serpentina gli sfiorò il volto. L'istante seguente, un corpo senza testa crollò al suolo."
  },
  AvgDialog_47168_Content_52 = {
    Text = "Q-Questo è..."
  },
  AvgDialog_47168_Content_53 = {
    Text = "Prima che gli altri soldati potessero reagire, una nebbia nera serpentiforme apparve accanto a ciascuno di loro."
  },
  AvgDialog_47168_Content_54 = {
    Text = "La nebbia nera si intreccia ai loro corpi, guizzando la lingua e ammirandoli."
  },
  AvgDialog_47168_Content_55 = {
    Text = "No... non..."
  },
  AvgDialog_47168_Content_56 = {
    Text = "Qualche voluta di fumo nero indugiava nell'aria. I serpenti neri affondavano i denti nelle loro prede, e la stanza si riempì di urla in rapida successione."
  },
  AvgDialog_47168_Content_57 = {
    Text = "Presto le urla cessano. I membri della Casa Ornn crollano tra il sangue e gli arti mozzati, la gola strozzata da gemiti soffocati."
  },
  AvgDialog_47168_Content_58 = {
    Text = "Spalancate gli occhi e osservate bene il risultato della mia alchimia... la mia \"figlia.\""
  },
  AvgDialog_47168_Content_59 = {
    Text = "In questi ultimi mesi, ho usato ogni mezzo possibile per occultare la sua esistenza, tutto per questo giorno."
  },
  AvgDialog_47168_Content_6 = {
    Text = "*Sigh*... Lascia perdere, probabilmente non capiresti queste cose comunque."
  },
  AvgDialog_47168_Content_60 = {
    Text = "Ecco un generoso dono che ho preparato per voi. Vi piace, vecchio?"
  },
  AvgDialog_47168_Content_61 = {
    Text = "Talis osservava il vecchio tremante e ammutolito con un sorriso soddisfatto."
  },
  AvgDialog_47168_Content_62 = {
    Text = "Avete perfettamente ragione; solo con una pianificazione accurata la famiglia Ornn può prosperare e fiorire."
  },
  AvgDialog_47168_Content_63 = {
    Text = "Non preoccupatevi, Padre. Ho sempre amato profondamente la famiglia Ornn e i miei cari..."
  },
  AvgDialog_47168_Content_64 = {
    Text = "Lasciate la famiglia Ornn a me, e la farò prosperare—"
  },
  AvgDialog_47168_Content_65 = {Text = "Puf—"},
  AvgDialog_47168_Content_66 = {
    Text = "La lama affilata si conficcò nel petto emaciato del vecchio. L'ultima cosa che vide fu il sorriso trionfante del bastardo."
  },
  AvgDialog_47168_Content_67 = {Text = "..."},
  AvgDialog_47168_Content_68 = {Text = "Tutti."},
  AvgDialog_47168_Content_69 = {
    Text = "BANG BANG BANG!!"
  },
  AvgDialog_47168_Content_7 = {
    Text = "...È ciò che mi ha insegnato il Padre."
  },
  AvgDialog_47168_Content_70 = {
    Text = "Un cucchiaio d'argento tintinna contro un calice finemente intagliato, producendo un suono cristallino."
  },
  AvgDialog_47168_Content_71 = {
    Text = "La rumorosa sala del banchetto piombò nel silenzio. Tutti rivolsero lo sguardo verso il posto d'onore."
  },
  AvgDialog_47168_Content_72 = {
    Text = "Gli schizzi di sangue sul seggio non si sono ancora completamente asciugati. Talis, assaporando la fragranza residua del sangue, osservava soddisfatto gli sguardi rivolti verso di lui."
  },
  AvgDialog_47168_Content_73 = {
    Text = "Lo so, lo so, avreste dovuto partecipare al banchetto di compleanno di mio padre. Ma vi sono sinceramente grato della vostra presenza."
  },
  AvgDialog_47168_Content_74 = {
    Text = "Un grande spettacolo sarebbe del tutto noioso senza un pubblico."
  },
  AvgDialog_47168_Content_75 = {
    Text = "Grazie a tutti per essere venuti. Oggi, la famiglia Ornn si riunisce per assistere al momento più importante della mia vita."
  },
  AvgDialog_47168_Content_76 = {
    Text = "Specialmente i miei fratelli più cari..."
  },
  AvgDialog_47168_Content_77 = {
    Text = "Si alzò in piedi, sollevò il calice e lo agitò verso l'angolo."
  },
  AvgDialog_47168_Content_78 = {
    Text = "Sotto la sorveglianza di una squadra di soldati armati fino ai denti, i fratelli minori di Talis sedevano al tavolo, impauriti e in silenzio."
  },
  AvgDialog_47168_Content_79 = {
    Text = "Con il loro aiuto, oggi, assisterete a un grande momento."
  },
  AvgDialog_47168_Content_8 = {
    Text = "Una serie di passi affrettati riecheggiò fuori dalla porta. Un giovane uomo che somigliava a Talis apparve nella sala."
  },
  AvgDialog_47168_Content_80 = {
    Text = "La storia della famiglia Ornn verrà completamente riscritta oggi."
  },
  AvgDialog_47168_Content_81 = {
    Text = "Sguainò la spada e la conficcò nel tavolo di legno."
  },
  AvgDialog_47168_Content_82 = {
    Text = "Io, Talis, un bastardo, un figlio illegittimo. Da oggi in avanti, sono il capofamiglia di Casa Ornn, il dittatore assoluto!"
  },
  AvgDialog_47168_Content_83 = {
    Text = "Signore e signori, diventerete i miei nuovi amici a Talis. Forgeremo un'alleanza potente, e tutti i nemici ne saranno schiacciati!"
  },
  AvgDialog_47168_Content_84 = {
    Text = "Gli ospiti potevano essere amici del precedente capoclan, ma non più. Ora stringono amicizia solo con il vincitore."
  },
  AvgDialog_47168_Content_85 = {
    Text = "Durante il generoso discorso di Talis, gli ospiti alzarono i calici."
  },
  AvgDialog_47168_Content_86 = {
    Text = "Lunga vita a Talis!"
  },
  AvgDialog_47168_Content_87 = {
    Text = "Hahaha... A voi, amici miei! Alla nostra grande alleanza! Al radioso futuro della famiglia Ornn!"
  },
  AvgDialog_47168_Content_88 = {Text = "Applausi!"},
  AvgDialog_47168_Content_89 = {Text = "..."},
  AvgDialog_47168_Content_9 = {
    Text = "Padre! Perdonatemi, ieri ero malato e mi sono appena alzato..."
  },
  AvgDialog_47168_Content_90 = {
    Text = "Calici che tintinnano, chiacchiere vivaci. Le persone, sincere o semplicemente di facciata, si fondono nel banchetto, divenendone parte."
  },
  AvgDialog_47168_Content_91 = {
    Text = "Miryam restava in disparte, sorridente, osservando gli ospiti e le regole di questa nuova era."
  },
  AvgDialog_47168_Content_92 = {
    Text = "Talis, ebbro di gioia, si adagiò nel posto d'onore. Alzò il calice verso tutti, bevve con ardore e assaporò quell'istante di immensa felicità nella sua vita."
  },
  AvgDialog_47168_Content_93 = {
    Text = "Miryam, anche a te... sei il mio orgoglio!"
  },
  AvgDialog_47168_Content_94 = {
    Text = "Non hai idea di quanto ho fatto per trovarti, per Risvegliarti..."
  },
  AvgDialog_47168_Content_95 = {
    Text = "Quelle \"sostanze argentee\" che hai menzionato prima..."
  },
  AvgDialog_47168_Content_96 = {
    Text = "Sì, esatto, quelle sostanze argentee... Oro? Gemme? Hahaha, sono tutte spazzatura!"
  },
  AvgDialog_47168_Content_97 = {
    Text = "Cos'è la materia d'argento? Cos'è l'alchimia? È potere! Di fronte al potere, cos'è la ricchezza? Non è che un sottoprodotto del potere."
  },
  AvgDialog_47168_Content_98 = {
    Text = "L'alchimia è potere... Miryam, tu sei l'incarnazione del potere! Applausi!"
  },
  AvgDialog_47168_Content_99 = {
    Text = "È vero che per rianimare qualcuno basta quella sostanza argentea?"
  },
  AvgDialog_47169_Content_1 = {
    Text = "Vecchio Amico"
  },
  AvgDialog_47169_Content_10 = {
    Text = "Talis mi ha riportata in vita; deve sapere qualcosa. Troverò il modo di riportarvi indietro attraverso di lui!"
  },
  AvgDialog_47169_Content_100 = {
    Text = "Pagherà il prezzo della sua esitazione."
  },
  AvgDialog_47169_Content_101 = {
    Text = "Le nostre scorte di cibo e acqua dureranno solo due o tre giorni..."
  },
  AvgDialog_47169_Content_102 = {
    Text = "Anche se sei piccolo, se si trattasse di sopravvivenza, non mi dispiacerebbe mangiarti."
  },
  AvgDialog_47169_Content_103 = {
    Text = "Non temere. Per ringraziarti della tua lealtà, ti concederò una fine rapida nei tuoi sogni."
  },
  AvgDialog_47169_Content_104 = {
    Text = "Lord Golia, sono un vostro seguace. Vi prego, non mi spaventate..."
  },
  AvgDialog_47169_Content_105 = {
    Text = "Ma, mio signore, non rinunciamo così presto. Iglenn ci ha mandati a trovare la strega che ha ucciso i nostri compagni di clan. Se riusciremo e torneremo con lei, forse sarà soddisfatto e ci lascerà vivere."
  },
  AvgDialog_47169_Content_106 = {
    Text = "Ingenuo piccolo, Iglenn non è così magnanimo. E poi, non esiste alcuna strega—solo una menzogna per ingannare la tribù."
  },
  AvgDialog_47169_Content_107 = {
    Text = "Ma ora che le cose sono arrivate a questo punto, spero che questa leggenda sia vera..."
  },
  AvgDialog_47169_Content_108 = {
    Text = "Il gigante aprì gli occhi e contemplò il mare sconfinato."
  },
  AvgDialog_47169_Content_109 = {
    Text = "Se una persona simile esiste, forse posso davvero compiere qualcosa."
  },
  AvgDialog_47169_Content_11 = {
    Text = "\"Quando le Stelle si allineano, Lemuria riapparirà nel mondo.\""
  },
  AvgDialog_47169_Content_12 = {
    Text = "Vi riporterò indietro, a Lemuria... È ciò che mi avete detto. State tranquillo, porterò sicuramente a Completo la mia missione!"
  },
  AvgDialog_47169_Content_13 = {
    Text = "Fissò con ansia l'ombra."
  },
  AvgDialog_47169_Content_14 = {
    Text = "L'Ombra rimase in silenzio. Il suo volto era celato dalla luce e dai viticci, rendendo la sua Espressione illeggibile. Abbassò il capo e lasciò sfuggire un lieve sospiro."
  },
  AvgDialog_47169_Content_15 = {
    Text = "Un Faint sospiro riecheggiò come un tuono nell'Illusione, mentre la luce iniziava a disperdersi e svanire."
  },
  AvgDialog_47169_Content_16 = {
    Text = "Padrona? Padrona? ..."
  },
  AvgDialog_47169_Content_17 = {
    Text = "MIO SIGNORE!!..."
  },
  AvgDialog_47169_Content_18 = {
    Text = "La luce intensa fece bruciare gli occhi a Miryam."
  },
  AvgDialog_47169_Content_19 = {
    Text = "Mentre la visione passava dalla sfocatura alla nitidezza, la Statua venne posata con cura sul davanzale della finestra."
  },
  AvgDialog_47169_Content_2 = {
    Text = "Silenzio assoluto. Oscurità assoluta."
  },
  AvgDialog_47169_Content_20 = {
    Text = "La pietra scura è intagliata con minuzia. Il re, il mento appoggiato sulla mano, siede adagiato su un trono intrecciato di tentacoli, osservando Miryam in silenzio."
  },
  AvgDialog_47169_Content_21 = {
    Text = "Il sole sorgeva alle sue spalle, proiettando una sagoma sfocata."
  },
  AvgDialog_47169_Content_22 = {
    Text = "Miryam sorrise e si inchinò devotamente alla statua."
  },
  AvgDialog_47169_Content_23 = {
    Text = "Abbiate pazienza, mio signore."
  },
  AvgDialog_47169_Content_24 = {
    Text = "Miryam, ti ho appena sentita parlare di nuovo nel sonno... Stai bene?"
  },
  AvgDialog_47169_Content_25 = {
    Text = "Hmm... Sto bene, Deborah."
  },
  AvgDialog_47169_Content_26 = {
    Text = "Perché continui a parlare nel sonno? Ti ho sentita così tante volte."
  },
  AvgDialog_47169_Content_27 = {
    Text = "L'ancella si fece avanti, sfiorandole delicatamente la fronte. Miryam la fissò con sguardo vacuo."
  },
  AvgDialog_47169_Content_28 = {
    Text = "Perché mi guardate così?"
  },
  AvgDialog_47169_Content_29 = {
    Text = "Stavo pensando che il nome Deborah ha un suono davvero bello."
  },
  AvgDialog_47169_Content_3 = {
    Text = "Lei si erge nell'Oscurità, e da qualunque direzione la si guardi, si può scorgere soltanto l'eterna Illusione."
  },
  AvgDialog_47169_Content_30 = {
    Text = "Eh eh, vero? La figlia di una schiava non dovrebbe avere un nome, ma alla vecchia padrona piacevo e me lo ha dato lei. Lo adoro!"
  },
  AvgDialog_47169_Content_31 = {
    Text = "Il volto di quell'amica nella mia memoria si sovrappone a quello dell'ancella."
  },
  AvgDialog_47169_Content_32 = {
    Text = "La Sacerdotessa Deborah un tempo aiutò Miryam a diventare Vecchio Sommo Sacerdote, e forse l'Ancella Deborah aiuterà Miryam a inaugurare il Reame Divino."
  },
  AvgDialog_47169_Content_33 = {
    Text = "Che meravigliosa coincidenza. Che fato divino. Miryam la guardò e sorrise senza rendersene conto."
  },
  AvgDialog_47169_Content_34 = {
    Text = "La tua fronte non scotta? Perché sembri un po' stordita..."
  },
  AvgDialog_47169_Content_35 = {
    Text = "Se ti succedesse qualcosa, il signor Talis non me lo perdonerebbe mai."
  },
  AvgDialog_47169_Content_36 = {
    Text = "Anche se ci chiamano tutte ancelle, tu sei molto più preziosa di noi altre!"
  },
  AvgDialog_47169_Content_37 = {
    Text = "Non siamo diverse. Tutti in questo mondo non sono che servi della grande esistenza."
  },
  AvgDialog_47169_Content_38 = {
    Text = "Sigh, stai farneticando di nuovo..."
  },
  AvgDialog_47169_Content_39 = {
    Text = "Deborah, ultimamente mi hai parlato di molte cose. Questo luogo mi è estraneo, e sono grata di avere qualcuno con cui parlare."
  },
  AvgDialog_47169_Content_4 = {
    Text = "Miryam si sentiva come una stella priva di luce, la sua energia si raccoglieva in qualche luogo — una sensazione al tempo stesso familiare e nostalgica."
  },
  AvgDialog_47169_Content_40 = {
    Text = "Sei la mia migliore amica. È sempre stato così."
  },
  AvgDialog_47169_Content_41 = {
    Text = "Sorrise e prese la mano dell'ancella."
  },
  AvgDialog_47169_Content_42 = {
    Text = "Andiamo. Lord Talis dovrebbe essere in attesa."
  },
  AvgDialog_47169_Content_43 = {Text = "..."},
  AvgDialog_47169_Content_44 = {
    Text = "Ti dico una cosa, ma non devi dirlo a nessun altro!"
  },
  AvgDialog_47169_Content_45 = {
    Text = "State tranquillo, non dirò una parola."
  },
  AvgDialog_47169_Content_46 = {
    Text = "Non devi premettere ogni segreto con quella frase. È la quinta volta che lo dici oggi."
  },
  AvgDialog_47169_Content_47 = {
    Text = "E poi, non credo sia un segreto che tu abbia qualcuno che ti piace. Probabilmente tutti nella tenuta sanno chi sia."
  },
  AvgDialog_47169_Content_48 = {
    Text = "Impossibile! L'ho nascosto così bene... Non riuscirai mai a farmelo confessare!"
  },
  AvgDialog_47169_Content_49 = {
    Text = "Oh, beh, è comunque una cosa grave... Credo che Lord Talis stia tramando qualcosa di serio."
  },
  AvgDialog_47169_Content_5 = {
    Text = "Fissò lo sguardo in quella direzione. La luce si levò in un'Ondata, formando un contorno sfocato laggiù."
  },
  AvgDialog_47169_Content_50 = {
    Text = "Quel vecchio è molto astuto. Fate attenzione!"
  },
  AvgDialog_47169_Content_51 = {Text = "Davvero?"},
  AvgDialog_47169_Content_52 = {
    Text = "Miryam disse questo, ma il suo sorriso rimase immutato, senza la minima traccia di sorpresa."
  },
  AvgDialog_47169_Content_53 = {
    Text = "Esatto! Guardalo, di recente ha ucciso parecchie persone. Quelle persone erano amiche della famiglia Ornn e avevano un rapporto stretto con il padre di Lord Talis..."
  },
  AvgDialog_47169_Content_54 = {
    Text = "Ogni volta sembra andare d'accordo con queste persone come fossero cari amici, ma poi si volta e ordina di ucciderle tutte."
  },
  AvgDialog_47169_Content_55 = {
    Text = "So che sicuramente non vuoi farlo, ma non c'è alternativa: devi seguire gli ordini di Lord Talis."
  },
  AvgDialog_47169_Content_56 = {
    Text = "In questo mondo non esistono calamità naturali, ma il cuore degli uomini è più terrificante di qualsiasi catastrofe."
  },
  AvgDialog_47169_Content_57 = {
    Text = "In un mondo così imperfetto, l'uccidere esisterà sempre. È qualcosa che non possiamo evitare."
  },
  AvgDialog_47169_Content_58 = {
    Text = "Sigh, proprio non capisco... Perché i regni e le famiglie devono combattersi di continuo? Ci sono ancora così tante persone che non riescono nemmeno a vivere dignitosamente."
  },
  AvgDialog_47169_Content_59 = {
    Text = "Spero solo di trovare in futuro un posticino tranquillo, costruire una casa, e stare con Nord..."
  },
  AvgDialog_47169_Content_6 = {
    Text = "Mio signore... Siete voi?"
  },
  AvgDialog_47169_Content_60 = {Text = "Oops! ..."},
  AvgDialog_47169_Content_61 = {
    Text = "Rendendosi conto di essersi lasciata sfuggire troppo, il volto di Deborah si fece rosso, e si coprì rapidamente la bocca."
  },
  AvgDialog_47169_Content_62 = {
    Text = "Non preoccuparti. Tutti sanno che provi qualcosa per quel giovane cocchiere. Persino Lord Talis me ne ha parlato."
  },
  AvgDialog_47169_Content_63 = {
    Text = "Sorrise e accarezzò il viso arrossato di Deborah."
  },
  AvgDialog_47169_Content_64 = {
    Text = "Stai tranquilla, Deborah. In futuro, ci sarà un mondo perfetto."
  },
  AvgDialog_47169_Content_65 = {
    Text = "Davvero? Come l'avete scoperto?"
  },
  AvgDialog_47169_Content_66 = {
    Text = "È vero, Deborah. Ci sono cose che ti racconterò poco a poco. Farò di te la prima Credente di questa nuova era e la prima Cittadino del Reame Divino."
  },
  AvgDialog_47169_Content_67 = {
    Text = "Porterò alla luce un Reame Divino perfetto... Questa è la mia missione."
  },
  AvgDialog_47169_Content_68 = {
    Text = "Mi lasci qui. Tu chiacchieri con Miryam lungo la strada, felice, vero?"
  },
  AvgDialog_47169_Content_69 = {
    Text = "La voce cupa di Talis interruppe la loro conversazione."
  },
  AvgDialog_47169_Content_7 = {
    Text = "La figura composta di luce raccolta sedeva obliquamente sul Trono, con una mano appoggiata al mento, osservando Miryam in silenzio."
  },
  AvgDialog_47169_Content_70 = {
    Text = "È così che vi adoperate per invitare la Signorina Miryam?"
  },
  AvgDialog_47169_Content_71 = {
    Text = "Chiamarli per nome e camminare fianco a fianco... Soldato, trascina fuori questa cosa indisciplinata e occupatene."
  },
  AvgDialog_47169_Content_72 = {
    Text = "Lord Talis! Vi prego, risparmiatemi... Io... Io stavo solo..."
  },
  AvgDialog_47169_Content_73 = {
    Text = "La colpa è mia, e non ha nulla a che fare con Deborah. Ti prego, \"Padre,\" perdonala."
  },
  AvgDialog_47169_Content_74 = {
    Text = "Talis lanciò un'occhiata a Deborah e agitò la mano con impazienza."
  },
  AvgDialog_47169_Content_75 = {
    Text = "Dal momento che Miryam ha interceduto per te, lascerò correre questa volta. La prossima, nessuno potrà aiutarti. Sparisci."
  },
  AvgDialog_47169_Content_76 = {
    Text = "Figlia mia, vieni, vieni da questa parte..."
  },
  AvgDialog_47169_Content_77 = {
    Text = "Deborah si inchina davanti a lui, fa un discreto occhiolino a Miryam, poi esce e chiude la porta dietro di sé."
  },
  AvgDialog_47169_Content_78 = {
    Text = "La voce di Talis si fece immediatamente più calda non appena iniziò a parlare con Miryam."
  },
  AvgDialog_47169_Content_79 = {
    Text = "Te la sei cavata eccezionalmente bene in questi ultimi mesi, davvero straordinario."
  },
  AvgDialog_47169_Content_8 = {
    Text = "Mio signore... Sono morta nutrendo dubbi su di voi. Questo è il mio peccato..."
  },
  AvgDialog_47169_Content_80 = {
    Text = "Un tempo studiai l'alchimia, e mio padre diceva sempre che stavo perdendo tempo. Ma in quanto figlio di un'ancella, qualunque cosa faccia, lui non approverebbe mai... Ancella, hm."
  },
  AvgDialog_47169_Content_81 = {
    Text = "La sua presa sull'elsa si strinse, le vene pulsanti, per poi rilassarsi lentamente."
  },
  AvgDialog_47169_Content_82 = {
    Text = "Ora è diverso, Miryam. Con te, ho un esercito... No, qualcosa di ancora più forte!"
  },
  AvgDialog_47169_Content_83 = {
    Text = "Possiamo creare altri Golem come me. Il Rito richiede un'enorme quantità di potere spirituale; posso Assisterti."
  },
  AvgDialog_47169_Content_84 = {
    Text = "Anche io ci ho riflettuto. Tuttavia, quella sostanza argentea non è qualcosa che si trova ovunque."
  },
  AvgDialog_47169_Content_85 = {
    Text = "\"Sostanza d'Argento...\""
  },
  AvgDialog_47169_Content_86 = {
    Text = "Te lo spiegherò più tardi, quando avrò tempo. Non c'è bisogno di affrettarsi per ora. Con te al mio fianco, mi basta per realizzare ciò che desidero."
  },
  AvgDialog_47169_Content_87 = {
    Text = "Inspirò profondamente, strinse il coltello e rivolse lo sguardo all'oceano oltre la finestra."
  },
  AvgDialog_47169_Content_88 = {
    Text = "Non manca molto al settantesimo compleanno di mio padre. Porterò dei doni alla città principale del territorio della famiglia Ornn per celebrare il suo compleanno."
  },
  AvgDialog_47169_Content_89 = {
    Text = "I nostri preparativi sono quasi completi. Quando verrà il momento, gli offriremo un dono prezioso. Giusto, Miryam?"
  },
  AvgDialog_47169_Content_9 = {
    Text = "Non chiedo il vostro perdono... Porterò il peso dei miei peccati! Fino ad allora, farò ciò che devo!"
  },
  AvgDialog_47169_Content_90 = {
    Text = "Certo, \"Padre.\" Sarà un Dono inestimabile per l'intera Casa Ornn."
  },
  AvgDialog_47169_Content_91 = {Text = "..."},
  AvgDialog_47169_Content_92 = {
    Text = "Alcuni giorni dopo."
  },
  AvgDialog_47169_Content_93 = {
    Text = "Sul mare, un vascello di legno vaga solitario."
  },
  AvgDialog_47169_Content_94 = {
    Text = "Lord Golia, le navi dei membri della tribù sono scomparse dalla vista."
  },
  AvgDialog_47169_Content_95 = {
    Text = "Una cosa buona."
  },
  AvgDialog_47169_Content_96 = {
    Text = "Il gigante lasciò cadere il coltello, si appoggiò all'albero maestro e chiuse gli occhi per riposare."
  },
  AvgDialog_47169_Content_97 = {
    Text = "Ferite riportate in battaglia, tradimento e macchinazioni dei miei consanguinei dopo essere stato ferito... È stata una mia disattenzione. Non posso incolpare altri."
  },
  AvgDialog_47169_Content_98 = {
    Text = "Ma persino lui avvertiva una certa stanchezza."
  },
  AvgDialog_47169_Content_99 = {
    Text = "Heh, Iglenn il codardo. Vuole Uccidermi ma teme di macchiare la sua reputazione. Esiliarmi col pretesto di dare la caccia a una strega — che tattica meschina."
  },
  AvgDialog_47170_Content_1 = {
    Text = "Statua Oscura"
  },
  AvgDialog_47170_Content_10 = {
    Text = "\"Svegliati, torna all'Abbraccio della tua famiglia...\""
  },
  AvgDialog_47170_Content_100 = {
    Text = "In breve, le voci dei Filistei vengono messe a tacere per sempre."
  },
  AvgDialog_47170_Content_101 = {
    Text = "Miryam sembrava ignara di tutto ciò che accadeva intorno a lei. Si diresse verso le Spoglie all'interno, raccogliendo devotamente la Statua Oscura per osservarla più da vicino."
  },
  AvgDialog_47170_Content_102 = {
    Text = "\"È una Statua di Lemuria... Sì, è una Statua di Lemuria...\""
  },
  AvgDialog_47170_Content_103 = {
    Text = "\"Questo è un Golem... Questo è il Potere di un Golem!!\""
  },
  AvgDialog_47170_Content_104 = {Text = "@2@3..."},
  AvgDialog_47170_Content_105 = {
    Text = "Talis si alzò in piedi, il volto arrossato dall'eccitazione. Intonò una Cantilena e agitò la Mano."
  },
  AvgDialog_47170_Content_106 = {
    Text = "Miryam avvertì un Potere Forte dall'altra estremità del Legame, ma svanì prima di causare alcun Danno reale."
  },
  AvgDialog_47170_Content_107 = {
    Text = "\"Golem, io sono il tuo Legame, ti ho donato la Vita. D'ora in poi, io sono il tuo padre.\""
  },
  AvgDialog_47170_Content_108 = {
    Text = "\"Le tue capacità sono formidabili, ma se lo desidero, posso sempre ridurti a un semplice cadavere.\""
  },
  AvgDialog_47170_Content_109 = {
    Text = "\"Il tuo Fato è legato al mio. Se io muoio, nemmeno tu potrai sopravvivere.\""
  },
  AvgDialog_47170_Content_11 = {
    Text = "\"Padre!...\""
  },
  AvgDialog_47170_Content_110 = {
    Text = "\"Quindi, non nutrire pensieri inappropriati. Dedicati ad assistermi e diventa il leader della famiglia Ornn.\""
  },
  AvgDialog_47170_Content_111 = {
    Text = "\"Padre\"? \"Padre\"... Il Re aveva ragione; sono io colei che deve portare il Fato! Ora so cosa fare. Posso compiere così tante cose...\""
  },
  AvgDialog_47170_Content_112 = {
    Text = "\"Stai tranquillo, Padre. Miryam ti riporterà sicuramente nel Reame Divino!\""
  },
  AvgDialog_47170_Content_113 = {
    Text = "Miryam fissò Talis con uno sguardo avido e inquietante. Era come se I Suoi Occhi lo trapassassero, concentrandosi su qualcosa di molto al di là della sua comprensione."
  },
  AvgDialog_47170_Content_114 = {
    Text = "È ardente come il sole, eppure oscuro e gelido come l'Aequor."
  },
  AvgDialog_47170_Content_115 = {
    Text = "\"Quale Reame Divino? Intendi le terre della Casa Ornn? Un'abitudine bizzarra, ma non importa. Fa' come desideri.\""
  },
  AvgDialog_47170_Content_116 = {
    Text = "\"Quei Filistei si stanno ancora godendo il mio castello e le mie proprietà. Miryam, uccidili. Mostrami cosa sai fare.\""
  },
  AvgDialog_47170_Content_117 = {
    Text = "\"Come desiderate, 'Padre'.\""
  },
  AvgDialog_47170_Content_118 = {
    Text = "Miryam si inchinò a Talis e uscì."
  },
  AvgDialog_47170_Content_119 = {
    Text = "Il Sangue gocciola dalla Statua Oscura. Dietro Miryam, un serpente nero si estende come ali, rivelando zanne affilate."
  },
  AvgDialog_47170_Content_12 = {
    Text = "Spalancò gli occhi di colpo e balzò fuori dal mare."
  },
  AvgDialog_47170_Content_13 = {
    Text = "\"Si è svegliata! Maestro Talis, si è svegliata!\""
  },
  AvgDialog_47170_Content_14 = {
    Text = "\"Dove mi trovo?...\""
  },
  AvgDialog_47170_Content_15 = {
    Text = "Miryam si ritrova in una sala spaziosa e lussuosa, inginocchiata al centro di un Cerchio magico rituale."
  },
  AvgDialog_47170_Content_16 = {
    Text = "Le persone intorno a lei avevano volti che non aveva mai visto prima, vestite con abiti a lei sconosciuti, e gridavano con eccitazione."
  },
  AvgDialog_47170_Content_17 = {
    Text = "Un Uomo di Mezza Età si trova fuori dal Cerchio magico, e la osserva con un misto di Esaurimento ed eccitazione."
  },
  AvgDialog_47170_Content_18 = {
    Text = "\"Ha funzionato... Ho evocato il golem! Ho dedicato tutta la mia vita alla Ricerca... e finalmente ci sono riuscito!!\""
  },
  AvgDialog_47170_Content_19 = {
    Text = "\"Dove... dov'è andato il Re? Questa non è Lemuria?\""
  },
  AvgDialog_47170_Content_2 = {
    Text = "\"Nel nome di @3, ti invoco, figlia mia...\""
  },
  AvgDialog_47170_Content_20 = {
    Text = "La domestica, il cui volto le pareva vagamente familiare, la fissava con Confusione."
  },
  AvgDialog_47170_Content_21 = {
    Text = "\"Lemuria? Che cos'è?\""
  },
  AvgDialog_47170_Content_22 = {
    Text = "\"Probabilmente una qualche civiltà antica... Chi può dirlo?\""
  },
  AvgDialog_47170_Content_23 = {
    Text = "\"A giudicare dal suo Vestito, dev'essere qualcuno di importante... I miei sforzi non sono stati vani!\""
  },
  AvgDialog_47170_Content_24 = {
    Text = "Il suo sguardo su Miryam si fece sempre più intenso. Le si avvicinò e allungò la mano per posarla sulla sua fronte."
  },
  AvgDialog_47170_Content_25 = {
    Text = "\"Io sono il tuo Legame... Ora, apri gli occhi e contempla ogni cosa...\""
  },
  AvgDialog_47170_Content_26 = {
    Text = "La realtà scomparve per un istante. Innumerevoli frammenti di informazioni inondarono la mente di Miryam, sommergendola come un oceano."
  },
  AvgDialog_47170_Content_27 = {
    Text = "Vide la sua terra natale sprofondare, fu testimone del mutare dei mari e osservò l'isola congiungersi alla terraferma."
  },
  AvgDialog_47170_Content_28 = {
    Text = "Vide nuove civiltà nascere, nuove nazioni fondarsi, nuovi seguaci intonare nuove preghiere e nuovi re ascendere nuovi troni."
  },
  AvgDialog_47170_Content_29 = {
    Text = "Osservò i lunghi anni scorrere rapidi con innumerevoli giorni e notti, e Lemuria svanì dalla memoria del mondo senza lasciare traccia."
  },
  AvgDialog_47170_Content_3 = {
    Text = "\"Lascia che l'Abbraccio della famiglia lenisca il tuo corpo stanco, e che il profumo di casa guarisca la tua anima errante.\""
  },
  AvgDialog_47170_Content_30 = {
    Text = "\"Ho dormito... per diecimila anni?\""
  },
  AvgDialog_47170_Content_31 = {
    Text = "\"Dormito? Hahaha... No, no. Sei morta una volta.\""
  },
  AvgDialog_47170_Content_32 = {
    Text = "\"Sono stato io! Ti ho risvegliata e ti ho ridato la Vita!\""
  },
  AvgDialog_47170_Content_33 = {
    Text = "\"Presto, dimmi quali abilità possiedi e come puoi aiutarmi.\""
  },
  AvgDialog_47170_Content_34 = {
    Text = "\"Lemuria... è svanita senza lasciare traccia...\""
  },
  AvgDialog_47170_Content_35 = {
    Text = "Ignorando le domande pressanti di Talis, Miryam rimase persa nei propri pensieri."
  },
  AvgDialog_47170_Content_36 = {
    Text = "I mutamenti del mondo, la scomparsa della sua terra natale e il passaggio di diecimila anni — tutto ciò lasciò la sua mente appena ridestata incapace di formulare pensieri."
  },
  AvgDialog_47170_Content_37 = {
    Text = "L'Ancella si batté la fronte e sospirò."
  },
  AvgDialog_47170_Content_38 = {
    Text = "\"Oh no, Lord Talis... non sembra molto sveglia, vero?\""
  },
  AvgDialog_47170_Content_39 = {
    Text = "\"Ma non preoccupatevi. Dopo che me ne sarò preso cura per un po', potrebbe...\""
  },
  AvgDialog_47170_Content_4 = {
    Text = "\"Padre?...\""
  },
  AvgDialog_47170_Content_40 = {Text = "\"Ah!—\""},
  AvgDialog_47170_Content_41 = {
    Text = "Il trambusto proviene da fuori la Casa, in lontananza."
  },
  AvgDialog_47170_Content_42 = {
    Text = "\"Che suono è?\""
  },
  AvgDialog_47170_Content_43 = {
    Text = "\"Filistei... Invasione filistea! I soldati stanno proteggendo la Cerimonia di risveglio; le difese costiere sono state sfondate!\""
  },
  AvgDialog_47170_Content_44 = {
    Text = "\"Attenzione! Filistea... Ah!...\""
  },
  AvgDialog_47170_Content_45 = {
    Text = "Una guardia correva gridando. Prima che potesse finire, un gigantesco arpione volò da lontano, perforandogli il cuore."
  },
  AvgDialog_47170_Content_46 = {
    Text = "Un gruppo di guerrieri stranieri dalla pelle scura, privi di armatura, urlando strani gridi di battaglia, ci circondò da ogni lato."
  },
  AvgDialog_47170_Content_47 = {
    Text = "\"Presto... Golem! Uccideteli per me!\""
  },
  AvgDialog_47170_Content_48 = {Text = "\"...\""},
  AvgDialog_47170_Content_49 = {
    Text = "Miryam crollò a terra, chinando il capo in uno stato confuso, e non rispose."
  },
  AvgDialog_47170_Content_5 = {
    Text = "Coscienza e percezione tornarono gradualmente a Miryam. In Dormiveglia, le sembrava di essere avvolta da acqua marina tiepida."
  },
  AvgDialog_47170_Content_50 = {
    Text = "\"@2! Non posso credere che abbiamo risvegliato un'inutile...\""
  },
  AvgDialog_47170_Content_51 = {
    Text = "\"Ecco come appare l'interno del castello della famiglia Ornn. Davvero lussuoso.\""
  },
  AvgDialog_47170_Content_52 = {
    Text = "\"Selvaggi! Questo è il territorio della famiglia Oren. Se non volete essere massacrati dall'esercito della famiglia Oren, andatevene di qui!\""
  },
  AvgDialog_47170_Content_53 = {Text = "Ssssh—"},
  AvgDialog_47170_Content_54 = {Text = "\"Ah!!\""},
  AvgDialog_47170_Content_55 = {
    Text = "L'arpione gli trafisse la spalla, e lui emise un urlo, stringendosi la ferita dal dolore."
  },
  AvgDialog_47170_Content_56 = {
    Text = "\"Se abbai ancora, la prossima volta ti perforerà il bulbo oculare, poi la gola.\""
  },
  AvgDialog_47170_Content_57 = {
    Text = "Tutti all'interno della stanza sono controllati, mentre le guardie all'esterno vengono uccise dagli arpioni. Il filisteo passeggia all'interno, osservando ogni cosa con avidità."
  },
  AvgDialog_47170_Content_58 = {
    Text = "\"Golia era solito ripetere: non puntate mai lo sguardo sul castello della famiglia Ornn; è una cosa estremamente pericolosa. Ma ora? Ci troviamo proprio all'interno del castello della famiglia Ornn.\""
  },
  AvgDialog_47170_Content_59 = {
    Text = "\"Tutto ciò che è qui presto sarà nostro!\""
  },
  AvgDialog_47170_Content_6 = {
    Text = "Il suono riecheggia debolmente, e il profilo del sole perfora la superficie dell'acqua, apparendo vagamente in alto."
  },
  AvgDialog_47170_Content_60 = {
    Text = "Accanto a lui, un altro Guerriero Filisteo sollevò con impazienza il suo tridente."
  },
  AvgDialog_47170_Content_61 = {
    Text = "\"Esatto, Golia è un codardo! Avremmo dovuto dare ascolto a Iglenn. Dovrebbe essere lui a sostituire Golia come nostro capo!\""
  },
  AvgDialog_47170_Content_62 = {
    Text = "\"Capo, una volta conquistato il castello degli Ornn, Iglenn vi apprezzerà sicuramente al nostro ritorno!\""
  },
  AvgDialog_47170_Content_63 = {
    Text = "\"Se non fossi stato nel mezzo della Cerimonia di risveglio, la vostra imboscata non sarebbe riuscita... Selvaggi spregevoli!\""
  },
  AvgDialog_47170_Content_64 = {
    Text = "\"Golem! Ti ho salvato! Se muoio io, non ce la farai nemmeno tu! Presto... riprenditi, aiutami!...\""
  },
  AvgDialog_47170_Content_65 = {
    Text = "\"Lei? Riponi le tue speranze in una donna? Hahaha...\""
  },
  AvgDialog_47170_Content_66 = {
    Text = "Le beffe dei filistei echeggiano nella stanza. Il Capitano Filisteo scuote il capo, afferra Talis per i capelli e tira fuori un pugnale."
  },
  AvgDialog_47170_Content_67 = {
    Text = "Si volta verso Miryam. Una statuetta gli penzola dalla cintura. Lei spalanca improvvisamente gli occhi."
  },
  AvgDialog_47170_Content_68 = {
    Text = "\"Dove hai trovato quella statuetta?\""
  },
  AvgDialog_47170_Content_69 = {
    Text = "\"Ehi... Quindi sai parlare, eh? Ti credevo una mezza deficiente.\""
  },
  AvgDialog_47170_Content_7 = {
    Text = "È un Dormiveglia senza sogni. Miryam non sa per quanto abbia dormito — forse un giorno? O una settimana?"
  },
  AvgDialog_47170_Content_70 = {
    Text = "\"La statuetta, da dove viene?\""
  },
  AvgDialog_47170_Content_71 = {
    Text = "Il capitano posa il coltello e abbassa lo sguardo sulla statuetta appesa alla cintura."
  },
  AvgDialog_47170_Content_72 = {
    Text = "La statua è fatta di un antico materiale di pietra opaca e raffigura una figura assisa su un trono. Strani tentacoli si protendono caoticamente, oscurandone il volto."
  },
  AvgDialog_47170_Content_73 = {
    Text = "\"Heh... Questa? L'ha trovata Golia e me l'ha data in premio per il mio coraggio.\""
  },
  AvgDialog_47170_Content_74 = {
    Text = "\"Ho rischiato la vita per lui, e questa è la ricompensa che mi ha dato. Cianfrusaglie inutili lasciate da chissà quale stupida civiltà.\""
  },
  AvgDialog_47170_Content_75 = {Text = "\"...Oh?\""},
  AvgDialog_47170_Content_76 = {
    Text = "Il Capitano Filisteo stava ancora parlando quando improvvisamente notò la donna davanti a sé alzarsi in piedi."
  },
  AvgDialog_47170_Content_77 = {
    Text = "Esaminò con curiosità il suo strano abbigliamento e quegli accessori bizzarri eppure preziosi."
  },
  AvgDialog_47170_Content_78 = {
    Text = "\"Cos'avete detto che fosse questa statua?\""
  },
  AvgDialog_47170_Content_79 = {
    Text = "\"Dico a te, sei inutile quanto un rifiuto. Che c'è? Hai le orecchie marce come la bocca?\""
  },
  AvgDialog_47170_Content_8 = {
    Text = "A poco a poco, la sua coscienza si fece più limpida, reintegrandosi con il corpo. Vagamente, vide un gruppo di persone che le tendevano le mani dal mare."
  },
  AvgDialog_47170_Content_80 = {
    Text = "\"Capitano, smettila di perdere tempo con lei. Un solo fendente... Ah!!!!...\""
  },
  AvgDialog_47170_Content_81 = {
    Text = "La nebbia nera apparve quasi in un istante."
  },
  AvgDialog_47170_Content_82 = {
    Text = "La nebbia nera si condensa in diversi enormi serpenti che si avventano famelici sul Guerriero Filisteo."
  },
  AvgDialog_47170_Content_83 = {
    Text = "Il coltello si allontanò dal collo di Miryam. La mano che lo impugnava fu mozzata dal morso di un serpente nero, e il sangue schizzò inzuppando le vesti di Miryam."
  },
  AvgDialog_47170_Content_84 = {
    Text = "I serpenti neri si riversano come un'ondata sul filisteo, divorandolo prima che possa emettere altre urla."
  },
  AvgDialog_47170_Content_85 = {
    Text = "Sul pavimento non restano che poche spoglie e una pozza di sangue."
  },
  AvgDialog_47170_Content_86 = {
    Text = "\"Questo... questo è...\""
  },
  AvgDialog_47170_Content_87 = {
    Text = "Tutti nella stanza rimasero attoniti di fronte a quella scena improvvisa, iniziando a dubitare della propria Visuale."
  },
  AvgDialog_47170_Content_88 = {
    Text = "Miryam abbassò lo sguardo sulle proprie mani. Un sorriso via via più luminoso le apparve sul volto."
  },
  AvgDialog_47170_Content_89 = {
    Text = [[
Volse lo sguardo verso il Capitano Filisteo, non verso di lui, ma verso la Statua alla sua cintura.
Le lacrime le riempirono gli occhi]]
  },
  AvgDialog_47170_Content_9 = {
    Text = "Padre, Madre, Sorella, Anziano Sacerdote, Re, Deborah... Tutti le tendevano le mani, invitandola."
  },
  AvgDialog_47170_Content_90 = {
    Text = "\"Vostra Maestà, vi rivedo... Dunque tutto ciò che avevate detto era vero...\""
  },
  AvgDialog_47170_Content_91 = {
    Text = "\"Sono davvero rinata! Ora possiedo un Potere più grande di quanto abbia mai avuto!\""
  },
  AvgDialog_47170_Content_92 = {
    Text = "\"Mio Signore... vi chiedo perdono per i miei dubbi... Non mi avete mai mentito...\""
  },
  AvgDialog_47170_Content_93 = {Text = "\"Ah!!!\""},
  AvgDialog_47170_Content_94 = {
    Text = "La temibile strega è immersa in emozioni contrastanti. Anni di incendi, saccheggi e massacri hanno conferito al filisteo un istinto quasi animale per il pericolo. Sa che questa è la sua unica occasione."
  },
  AvgDialog_47170_Content_95 = {
    Text = "Ruggì, impugnando un coltello, e si lanciò alla Carica contro Miryam con tutta la sua velocità."
  },
  AvgDialog_47170_Content_96 = {Text = "Ssssh—"},
  AvgDialog_47170_Content_97 = {
    Text = "Il serpente nero apparve dal nulla in una forma che non riusciva a comprendere, trapassandogli il corpo"
  },
  AvgDialog_47170_Content_98 = {
    Text = "Dentro e fuori, alcuni Filistei si lanciano in avanti con le armi, altri fuggono in ogni direzione, altri ancora si inginocchiano implorando pietà."
  },
  AvgDialog_47170_Content_99 = {
    Text = "A Miryam non importava delle loro Scelte coraggiose o spregevoli. Il serpente nero appariva e svaniva, giocando, mordendo e dando la caccia a quelle vite miserabili."
  },
  AvgDialog_47171_Content_1 = {
    Text = "La Virtù delle Menzogne"
  },
  AvgDialog_47171_Content_10 = {
    Text = "Notando l'espressione di Deborah, i credenti annuiscono con comprensione."
  },
  AvgDialog_47171_Content_100 = {
    Text = "Le parole del mio maestro... erano tutte menzogne, vero?"
  },
  AvgDialog_47171_Content_101 = {
    Text = "Tutte le calamità sono state scongiurate negli ultimi anni... Lemuria è sempre più vicina al Reame Divino... A un passo, siamo solo a un passo..."
  },
  AvgDialog_47171_Content_102 = {
    Text = "Sicuramente porterai il Reame Divino, mio Signore! Sono il tuo fedele servitore, e sempre..."
  },
  AvgDialog_47171_Content_103 = {
    Text = "Ho cercato così a lungo... Ma la presenza di Dio non si trova in alcun Sogno."
  },
  AvgDialog_47171_Content_104 = {
    Text = "Tulu distoglie lo sguardo dal volto di Miryam."
  },
  AvgDialog_47171_Content_105 = {
    Text = "La nostra civiltà perirà — è destino, è inevitabile... Questo è l'ultimo messaggio di Dio."
  },
  AvgDialog_47171_Content_106 = {
    Text = "Il bel tempo e i mari calmi non sono che L'ultima alba di Lemuria."
  },
  AvgDialog_47171_Content_107 = {
    Text = "Affrontare questa catastrofe è la Punizione sentenziata sul Re e la sua Somma Sacerdotessa."
  },
  AvgDialog_47171_Content_108 = {
    Text = "Quindi... quindi intendete dire che... i Lemuriani, con tutte le loro preghiere, speranze e offerte, erano un inganno..."
  },
  AvgDialog_47171_Content_109 = {
    Text = "Tutti, dalla nascita alla morte, vivono sotto questo inganno, vero, mio Signore?"
  },
  AvgDialog_47171_Content_11 = {
    Text = "Si inginocchiano dinanzi a Miryam in silenzio. Reverenza e aspettativa brillano nei loro occhi, tutti fissi sulla Somma Sacerdotessa."
  },
  AvgDialog_47171_Content_110 = {
    Text = "Il tuo maestro te l'ha già detto."
  },
  AvgDialog_47171_Content_111 = {
    Text = "Voglio udirlo dalle Vostre parole, mio Signore..."
  },
  AvgDialog_47171_Content_112 = {
    Text = "Ti prego, dimmi con la Tua stessa voce che le nostre Preghiere sono prive di significato. Ti prego, confermalo come una Profezia, che quei pionieri che hanno sacrificato tutto — intelletto, emozioni, dignità, che si sono ammassati in questa vasca, non attendono altro che una menzogna lontana..."
  },
  AvgDialog_47171_Content_113 = {
    Text = "Ti prego, dimmi con la Tua stessa voce... che il Reame Divino... non arriverà mai..."
  },
  AvgDialog_47171_Content_114 = {
    Text = "Nessun grido dirompente, nessuna folle Isteria. Lei guarda negli occhi Tulu e pronuncia tutte le sue Domande. Tra le sue parole, si dipana il Silenzio. Nel Silenzio, vi è un crollo inespresso."
  },
  AvgDialog_47171_Content_115 = {
    Text = "Fissa senza battere ciglio, come i popoli-pesce intorno a lei — senza pensieri, senza emozioni."
  },
  AvgDialog_47171_Content_116 = {
    Text = "Come fuochi d'artificio che svaniscono nel loro spegnersi, anelando, ardendo, bramando l'alba lontana con la sua ultima scintilla."
  },
  AvgDialog_47171_Content_117 = {
    Text = "Tulu chiude gli occhi e inspira profondamente. In quell'istante, quegli sguardi gli riportarono alla mente molti passati."
  },
  AvgDialog_47171_Content_118 = {
    Text = "Forse ricorda quei mortali che hanno vissuto nell'inganno per generazioni."
  },
  AvgDialog_47171_Content_119 = {
    Text = "Forse ricorda i Credenti che sacrificarono il loro intelletto, le emozioni e la dignità, e coloro che consacrarono le proprie anime solo per vederle distorte."
  },
  AvgDialog_47171_Content_12 = {
    Text = "Fedeli seguaci del nostro Signore, che Egli vi benedica per sempre."
  },
  AvgDialog_47171_Content_120 = {
    Text = "Forse ricorda soltanto che, prima di questo inganno di Riposo Eterno, lui, come ogni Lemuriano, un tempo credeva di poter portare una nuova alba a questa terra."
  },
  AvgDialog_47171_Content_121 = {
    Text = "Offrire speranza al suo popolo è il dovere naturale di un Sovrano, l'unico significato di questo inganno. E così sia. Che continui."
  },
  AvgDialog_47171_Content_122 = {
    Text = "Tulu apre gli occhi e si fa innanzi a Miryam."
  },
  AvgDialog_47171_Content_123 = {
    Text = "Non avvisto il Dio da molto tempo... ma so che è ancora là, nel profondo dei sogni."
  },
  AvgDialog_47171_Content_124 = {
    Text = "Il Reame Divino attende ancora."
  },
  AvgDialog_47171_Content_125 = {
    Text = "Miryam solleva di scatto il capo."
  },
  AvgDialog_47171_Content_126 = {
    Text = "Ma... ma il mio maestro ha detto..."
  },
  AvgDialog_47171_Content_127 = {
    Text = "Il Reame Divino non giungerà fino alla caduta di Lemuria. Tutti periranno in questa catastrofe."
  },
  AvgDialog_47171_Content_128 = {
    Text = "Mio Signore, cosa intendete..."
  },
  AvgDialog_47171_Content_129 = {
    Text = "... Ma le Stelle un tempo mi predissero che Lemuria sarebbe rinata."
  },
  AvgDialog_47171_Content_13 = {
    Text = "Serpenti d'onice danzano dietro il suo orlo. La sua mano sfiora dolcemente le loro fronti, una ad una."
  },
  AvgDialog_47171_Content_130 = {
    Text = "I suoi occhi sfuggono Miryam. Voltandosi, muove i passi verso il Trono."
  },
  AvgDialog_47171_Content_131 = {
    Text = "Quando le Stelle Sono Allineate, Lemuria porrà fine al suo letargo e risorgerà nel mondo."
  },
  AvgDialog_47171_Content_132 = {
    Text = "Non sarò io a risvegliare Lemuria. Sarai tu."
  },
  AvgDialog_47171_Content_133 = {Text = "?!!"},
  AvgDialog_47171_Content_134 = {
    Text = "Miryam, Somma Sacerdotessa di Lemuria. Rinascerai. Mi riporterai indietro, e riporterai indietro Lemuria."
  },
  AvgDialog_47171_Content_135 = {
    Text = "Quando quel momento giungerà, innalzerò il Reame Divino, assicurando l'eternità di Lemuria sotto il Mio Sovrano regno."
  },
  AvgDialog_47171_Content_136 = {
    Text = "Tulu torna a sedersi sul suo Trono. Si sorregge il mento, appoggiandosi stancamente"
  },
  AvgDialog_47171_Content_137 = {
    Text = "Evita di guardare l'espressione sul volto di Miryam, un misto di stupore e tormento. Sa che Miryam non crede fino in fondo alle sue parole. Nessuno potrebbe davvero crederci."
  },
  AvgDialog_47171_Content_138 = {
    Text = "Cosa è più crudele, la menzogna o la verità? Vi ha riflettuto a lungo, ma non è riuscito a trovare risposta."
  },
  AvgDialog_47171_Content_139 = {
    Text = "Se ha fatto le scelte sbagliate, che sia questa la fine."
  },
  AvgDialog_47171_Content_14 = {
    Text = "Lode al nostro Signore... Lode alla Somma Sacerdotessa!"
  },
  AvgDialog_47171_Content_140 = {
    Text = "Ma... mio Signore, cosa... cosa dovrei fare?"
  },
  AvgDialog_47171_Content_141 = {
    Text = "Attendi. Cammina con Lemuria fino alla sua fine, finché non giungerà il tuo momento."
  },
  AvgDialog_47171_Content_142 = {
    Text = "Quando Lemuria...?"
  },
  AvgDialog_47171_Content_143 = {
    Text = "Tre giorni. Tra tre giorni, Lemuria incontrerà la sua fine."
  },
  AvgDialog_47171_Content_144 = {
    Text = "Qual è il Vostro piano... mio Signore?"
  },
  AvgDialog_47171_Content_145 = {
    Text = "Un grande rito, una cerimonia sontuosa... che intonino preghiere, invocando il mio nome. Manderò tutti i Lemuriani in un dormiveglia senza sogni."
  },
  AvgDialog_47171_Content_146 = {
    Text = "Tesserò il sogno più magnifico."
  },
  AvgDialog_47171_Content_147 = {
    Text = "Il Vecchio Sommo Sacerdote ha detto che rifiuta di addormentarsi. Desidera assistere con i propri occhi all'inabissamento di Lemuria."
  },
  AvgDialog_47171_Content_148 = {Text = "E tu?"},
  AvgDialog_47171_Content_149 = {Text = "..."},
  AvgDialog_47171_Content_15 = {
    Text = "Sollecitati dal suo seguito, i seguaci che recano la benedizione della Somma Sacerdotessa si allontanano colmi di gioia incontenibile."
  },
  AvgDialog_47171_Content_150 = {
    Text = "...Sono disposta ad affrontare la fine con lucidità, mio Signore."
  },
  AvgDialog_47171_Content_151 = {
    Text = "Miryam se ne va. Tulu si accascia sul trono, fissando la stanza vuota, gli uomini-pesce che si contorcono e la figura di Miryam, avvolta nell'esitazione."
  },
  AvgDialog_47171_Content_152 = {
    Text = "La conversazione tra il Signore e la Somma Sacerdotessa di Lemuria giunge al termine. Negli innumerevoli giorni e notti dei millenni a venire, questo sarà il loro unico incontro."
  },
  AvgDialog_47171_Content_16 = {
    Text = "Guardandoli allontanarsi, Deborah lascia sfuggire un sospiro di soddisfazione."
  },
  AvgDialog_47171_Content_17 = {
    Text = "Da quando siete divenuta Somma Sacerdotessa, Lemuria non ha patito calamità per lungo tempo."
  },
  AvgDialog_47171_Content_18 = {
    Text = "Avete governato la nostra terra con saggezza. Guardate questi credenti! Vi venerano davvero!"
  },
  AvgDialog_47171_Content_19 = {
    Text = "Io sono soltanto il messaggero del Signore. I Lemuriani dovrebbero venerare unicamente il Signore."
  },
  AvgDialog_47171_Content_2 = {
    Text = "Diversi anni dopo."
  },
  AvgDialog_47171_Content_20 = {
    Text = "Prima dell'Ascensione del nostro Signore, non avevo mai visto una Lemuria simile. Mai avrei immaginato che una tale Lemuria potesse davvero esistere..."
  },
  AvgDialog_47171_Content_21 = {
    Text = "Miryam e Deborah stanno insieme sugli scogli in riva al mare. Campi rigogliosi e città splendide, e l'antico grande tempio che conoscono così bene, si fondono in uno spettacolo maestoso dinanzi a loro."
  },
  AvgDialog_47171_Content_22 = {
    Text = "Quando parla, la sua voce è dolce e calma, ma i suoi occhi brillano di un fervore che supera di gran lunga quello di qualsiasi credente."
  },
  AvgDialog_47171_Content_23 = {
    Text = "Prega per il nostro Signore, Deborah... Ci stiamo avvicinando al Reame Divino."
  },
  AvgDialog_47171_Content_24 = {Text = "..."},
  AvgDialog_47171_Content_25 = {
    Text = "\"Nel lontano abisso privo di sole, la grande anima ancestrale è nel dormiveglia...\""
  },
  AvgDialog_47171_Content_26 = {
    Text = "\"...La Sua volontà si intreccia come una ragnatela di stelle; nel vuoto eterno, Egli attende che tu entri nel Suo sogno...\""
  },
  AvgDialog_47171_Content_27 = {
    Text = "Miryam si inginocchia sola ai piedi della statua. Le preghiere fluiscono dalla sua bocca con limpida scioltezza, come un ruscello che sgorga dalle verdi colline."
  },
  AvgDialog_47171_Content_28 = {
    Text = "Il ruscello vortica e scorre nella stanza, formando una cortina opaca che la separa dalla realtà."
  },
  AvgDialog_47171_Content_29 = {
    Text = "Il vuoto eterno della dimensione spirituale accoglie la sua anima. Nessun disagio ormai, dopo tutti questi anni: resta soltanto un calore che toglie il respiro."
  },
  AvgDialog_47171_Content_3 = {
    Text = "Dopo una lieve pioggerella, il cielo è limpido come uno smeraldo azzurro. Il sole tesse i suoi raggi tra le sabbie dorate, intrecciando calore su alcuni Fanciulli che giocano in riva al mare."
  },
  AvgDialog_47171_Content_30 = {
    Text = "Granelli di luce brillano nell'Oscurità. Fili si intrecciano dal bagliore come viticci."
  },
  AvgDialog_47171_Content_31 = {
    Text = "Là dove i fiumi scintillanti convergono, un immenso profilo luminoso incide una regione di avorio eterno e traslucido, come la pallida luna che arde nel cielo vuoto."
  },
  AvgDialog_47171_Content_32 = {
    Text = "Signore nostro, eterno padrone che regna nei sogni... Vogliate perdonare la mia intrusione nel Vostro grande territorio."
  },
  AvgDialog_47171_Content_33 = {
    Text = "Le Vostre profezie hanno portato salvezza ai Lemuriani. La Vostra maestà ha scacciato ogni calamità. A nome del Vostro popolo, Vi prego, concedetemi di esprimere la nostra reverenza verso di Voi..."
  },
  AvgDialog_47171_Content_34 = {
    Text = "Voi siete l'inviata del Signore, la salvatrice di Lemuria. Siamo pronti a dedicare ogni cosa alla realizzazione della profezia e all'avvento del Reame Divino."
  },
  AvgDialog_47171_Content_35 = {
    Text = "Possa Tu elargire la Tua guida. Possa Tu riconoscere la Devozione della Tua più fedele credente..."
  },
  AvgDialog_47171_Content_36 = {
    Text = "La sua coscienza fluttua oltre la barriera del reame spirituale, avvicinandosi alla statua formata da luminosa luce stellare. Protende le mani verso quei raggi con devozione…"
  },
  AvgDialog_47171_Content_37 = {Text = "Boom! —"},
  AvgDialog_47171_Content_38 = {
    Text = "Un istante prima che tocchi i raggi, la statua si frantuma. I fasci di luce collidono, vorticano e si disperdono in ogni direzione."
  },
  AvgDialog_47171_Content_39 = {
    Text = "Una Forte raffica sospinge Miryam all'indietro, facendola cadere a terra."
  },
  AvgDialog_47171_Content_4 = {
    Text = "Alcuni Residenti siedono sulle scale di Pietra che si affacciano sul mare, canticchiando un inno antico e gioioso."
  },
  AvgDialog_47171_Content_40 = {
    Text = "L'oscurità si dissipa. Miryam si alza, stordita, gli occhi velati dalla polvere turbinante. Prima che riesca a ritrovare l'equilibrio, un macigno colossale precipita dal nulla, squarcia il tetto del tempio e si schianta contro la statua del Re con un rombo di tuono."
  },
  AvgDialog_47171_Content_41 = {
    Text = "No! Che il Signore abbia pietà di noi! Questo... questo è..."
  },
  AvgDialog_47171_Content_42 = {
    Text = "Pietre che un tempo erano tentacoli e la testa della figura giacciono in frantumi al suolo. Solo metà del corpo resta sul trono. Gocce di pioggia filtrano attraverso la voragine nel muro, inzuppando le rovine un tempo sacre."
  },
  AvgDialog_47171_Content_43 = {
    Text = "Miryam si inginocchia davanti alle Spoglie della Statua, in preda al panico."
  },
  AvgDialog_47171_Content_44 = {
    Text = "Ho... ho commesso qualche errore? Vi prego, ditemelo..."
  },
  AvgDialog_47171_Content_45 = {
    Text = "Cough... Cough..."
  },
  AvgDialog_47171_Content_46 = {
    Text = "La tosse del vecchio sacerdote riecheggia nella sala di preghiera. Per un uomo della sua età, pochi anni sembrano decenni. Avanza barcollando tra le rovine sudice, le dita tremanti mentre scaccia la polvere soffocante."
  },
  AvgDialog_47171_Content_47 = {
    Text = "Maestra? Perché siete venuta qui da sola...?"
  },
  AvgDialog_47171_Content_48 = {
    Text = "Oggi desidero passeggiare da solo. È da molto tempo che non esco per una camminata."
  },
  AvgDialog_47171_Content_49 = {
    Text = "Si avvicina alla statua distrutta e si inchina lentamente in segno di reverenza."
  },
  AvgDialog_47171_Content_5 = {
    Text = "La musica si leva sulle acque indaco, fondendosi con i richiami dei gabbiani prima di raggiungere le orecchie di Miryam."
  },
  AvgDialog_47171_Content_50 = {
    Text = "Miryam incrocia il suo sguardo. Gli occhi del vecchio restano acuti, eppure colmi di qualcosa che lei non riesce a comprendere."
  },
  AvgDialog_47171_Content_51 = {
    Text = "Sconcertante, intricato, ambivalente. Uno sguardo simile a quello di un neonato che contempla questo mondo estraneo, o di un traditore che affronta l'amata Terra dei Bianchi Uccelli, o qualcosa nel mezzo."
  },
  AvgDialog_47171_Content_52 = {
    Text = "Maestro... Che cosa sta accadendo? Un presagio simile... Dovremmo celebrare una grande cerimonia sacrificale?"
  },
  AvgDialog_47171_Content_53 = {
    Text = "Miryam, inchinati al Signore e ascolta il Suo decreto."
  },
  AvgDialog_47171_Content_54 = {Text = "Sì!"},
  AvgDialog_47171_Content_55 = {
    Text = "Si inchina profondamente dinanzi alla statua in segno di reverenza, poi alza lo sguardo verso il suo maestro, in attesa col fiato sospeso."
  },
  AvgDialog_47171_Content_56 = {
    Text = "\"La traccia di Dio si è dissipata nel Suo sogno. La terra di Lemuria è stata abbandonata dal suo Dio.\""
  },
  AvgDialog_47171_Content_57 = {
    Text = "\"Il momento finale è sulla soglia. Il regno sprofonderà nel mare profondo. La civiltà incontrerà la sua fine.\""
  },
  AvgDialog_47171_Content_58 = {
    Text = "\"Il Reame Divino non giungerà mai.\""
  },
  AvgDialog_47171_Content_59 = {
    Text = "Maestro... cosa... cosa state dicendo? Queste parole... queste parole blasfeme..."
  },
  AvgDialog_47171_Content_6 = {
    Text = "Quella è... Sua Grazia, la Somma Sacerdotessa?"
  },
  AvgDialog_47171_Content_60 = {
    Text = "È una prova, vero? Stia tranquillo, maestro, io sono interamente devota a Lui! Lo assisterò! Insieme, porteremo il Reame Divino a Lemuria..."
  },
  AvgDialog_47171_Content_61 = {
    Text = "Queste parole furono pronunciate dal Signore in persona."
  },
  AvgDialog_47171_Content_62 = {
    Text = "Prima della Sua ascensione, Egli vide questo nel Suo sogno e me ne informò... Da allora cercò la presenza di Dio, finché alla fine vide il futuro con chiarezza."
  },
  AvgDialog_47171_Content_63 = {
    Text = "Il nostro Signore non può salvare Lemuria."
  },
  AvgDialog_47171_Content_64 = {
    Text = "Si volta, il volto severo, irremovibile."
  },
  AvgDialog_47171_Content_65 = {
    Text = "Egli fissa Miryam, osservando la luce svanire lentamente dai suoi occhi. La guarda immobile, le mani da tempo avvezze alla preghiera ora tremanti, incerte su dove posarsi."
  },
  AvgDialog_47171_Content_66 = {
    Text = "Altrettanto sconvolto come quando apprese per la prima volta di queste profezie."
  },
  AvgDialog_47171_Content_67 = {
    Text = "Miryam, sai qual è il dovere più importante della Somma Sacerdotessa di Lemuria?"
  },
  AvgDialog_47171_Content_68 = {
    Text = "Ascoltare le Sue profezie? Assisterlo nell'avvento del Reame Divino? Organizzare i credenti per il rito? No, niente di tutto questo."
  },
  AvgDialog_47171_Content_69 = {
    Text = "Il dovere più importante della Somma Sacerdotessa è l'inganno."
  },
  AvgDialog_47171_Content_7 = {
    Text = "Vostra Grazia!"
  },
  AvgDialog_47171_Content_70 = {
    Text = "Ingannare il popolo di Lemuria. Donare loro un bagliore di speranza, affinché possano vivere con meno sofferenza fino alla fine…"
  },
  AvgDialog_47171_Content_71 = {
    Text = "Condividiamo questo segreto con il nostro Signore. Siamo i Suoi portavoce e complici. Siamo i sublimi peccatori di Lemuria…"
  },
  AvgDialog_47171_Content_72 = {
    Text = "E questo include te."
  },
  AvgDialog_47171_Content_73 = {
    Text = "Maestro... intendi dire... heh, no... io..."
  },
  AvgDialog_47171_Content_74 = {
    Text = "Un sorriso inconsapevole affiora sulla guancia di Miryam."
  },
  AvgDialog_47171_Content_75 = {
    Text = "Uno scherzo? O ancora una sorta di prova? Dovrebbe esserlo. Deve esserlo."
  },
  AvgDialog_47171_Content_76 = {
    Text = "Dev'essere la Sua diffidenza, sorta dopo che la mia devozione ha cessato di soddisfarLo..."
  },
  AvgDialog_47171_Content_77 = {
    Text = "Devo essere più devota. Mi basta essere più devota..."
  },
  AvgDialog_47171_Content_78 = {
    Text = "Miryam si sforza di pensarla così. Le sue mani stringono la base della statua con forza, come fosse l'unico filo d'erba alla deriva nel mare in tempesta."
  },
  AvgDialog_47171_Content_79 = {
    Text = "Il bordo tagliente della statua spezzata le incide il palmo, e il sangue gocciola senza che lei se ne avveda."
  },
  AvgDialog_47171_Content_8 = {
    Text = "Scorgendo quella veste purpurea, alcuni Residenti Lemuriani accorrono e si radunano attorno a Miryam."
  },
  AvgDialog_47171_Content_80 = {
    Text = "Accanto a lei, il sacerdote anziano scuote lentamente il capo. I suoi occhi, velati da emozioni complesse, perforano la statua infranta e le pesanti lastre di pietra, fissandosi sul cielo lontano."
  },
  AvgDialog_47171_Content_81 = {
    Text = "Le stelle mi predissero che il destino di Lemuria doveva essere affidato a te. Questo era il mio dovere. Ma ora, questo fardello diventa tuo..."
  },
  AvgDialog_47171_Content_82 = {
    Text = "Non è giusto nei tuoi confronti, ragazza. Per niente. Ma per le stelle, il fato o gli dèi... l'equità non ha significato dinanzi a simili esistenze."
  },
  AvgDialog_47171_Content_83 = {
    Text = "Non posso offrirti alcuna equità, né altre lezioni."
  },
  AvgDialog_47171_Content_84 = {
    Text = "Perciò, fa' ciò che vuoi. Come vittima dell'ingiustizia e peccatrice di Lemuria, ne hai il diritto."
  },
  AvgDialog_47171_Content_85 = {
    Text = "Acutezza e severità svaniscono dagli occhi dell'ex sommo sacerdote. Fatica e vuoto prendono il sopravvento. Curvo e barcollante, esce solo."
  },
  AvgDialog_47171_Content_86 = {
    Text = "Il Signore si è destato. Vi attende."
  },
  AvgDialog_47171_Content_87 = {
    Text = "Immagino che vorrai incontrarlo."
  },
  AvgDialog_47171_Content_88 = {Text = "..."},
  AvgDialog_47171_Content_89 = {
    Text = "Fissa lo sguardo sulla vasca."
  },
  AvgDialog_47171_Content_9 = {
    Text = "Shh! Non fatevi scoprire!"
  },
  AvgDialog_47171_Content_90 = {
    Text = "Innumerevoli teste viscide emergono, poi risprofondano. Salgono, e affondano. Luride increspature turbano la superficie."
  },
  AvgDialog_47171_Content_91 = {
    Text = "Occhi prodigiosi sporgenti su entrambi i lati, che ruotano vacui protendendosi verso di lui. Le loro bocche dalle labbra sottili si aprono e chiudono, mormorando sillabe inesplicabili, come se tentassero di chiedergli qualcosa."
  },
  AvgDialog_47171_Content_92 = {
    Text = "Alle sue spalle, le porte d'ardesia si aprono scorrendo."
  },
  AvgDialog_47171_Content_93 = {
    Text = "Lode al nostro Signore... Lode al grande Re di Lemuria..."
  },
  AvgDialog_47171_Content_94 = {
    Text = "Sento sempre questo sarcasmo quando ti incontro."
  },
  AvgDialog_47171_Content_95 = {
    Text = "Nella stanza cupa, solo la corona di Lemuria riluce ancora. Le sue dimensioni imponenti creano una proporzione distorta con il Suo corpo adolescente."
  },
  AvgDialog_47171_Content_96 = {
    Text = "Eppure, la corona non appare minimamente inadatta, ma calza alla perfezione come se fosse parte di Lui."
  },
  AvgDialog_47171_Content_97 = {
    Text = "I Suoi occhi in dormiveglia percorrono il volto di Miryam, le sopracciglia che fremono come l'esalazione del mare. La quiete maschera il Suo volto giovanile, occultando ogni emozione fanciullesca."
  },
  AvgDialog_47171_Content_98 = {
    Text = "Nelle mie congetture, potresti piangere, impazzire, o tentare di uccidermi."
  },
  AvgDialog_47171_Content_99 = {
    Text = "Ma tu resti calma. Non posso speculare se questa sia una Benedizione o una Maledizione."
  },
  AvgDialog_47172_Content_1 = {
    Text = "Sotto la pioggia"
  },
  AvgDialog_47172_Content_10 = {
    Text = "\"Miryam... dovresti davvero preoccuparti più di me. Non puoi continuare così, vero?\""
  },
  AvgDialog_47172_Content_100 = {
    Text = "\"Il Signore ci ha protetti. Non sono che un misero reietto, eppure Egli ha scelto comunque di darmi riparo...\""
  },
  AvgDialog_47172_Content_101 = {
    Text = "\"Tu non sei come me, Miryam. Puoi diventare una sacerdotessa, puoi essere il nostro orgoglio. La tua vita ha un significato...\""
  },
  AvgDialog_47172_Content_102 = {
    Text = "\"Puoi aiutare il Signore a salvare Lemuria, fino all'avvento del Reame Divino...\""
  },
  AvgDialog_47172_Content_103 = {
    Text = "\"Padre... Padre!!!\""
  },
  AvgDialog_47172_Content_104 = {
    Text = "Il sangue quasi si secca nella sua ferita. La pioggia gelida scorre col rivolo cremisi, macchiando il vestito di Miryam."
  },
  AvgDialog_47172_Content_105 = {
    Text = "Enos mantiene la sua postura ricurva, facendo scudo alle tempeste implacabili per la figlia defunta."
  },
  AvgDialog_47172_Content_106 = {
    Text = "Il suo corpo si china lentamente, come per abbracciare la figlia, congedare le fatiche del giorno e abbandonarsi al dolce dormiveglia della notte."
  },
  AvgDialog_47172_Content_107 = {
    Text = "\"Padre... io... mi dispiace... ho fallito...\""
  },
  AvgDialog_47172_Content_108 = {
    Text = "Rimorso e dolore si levano come una nebbia nera senza fine, opprimente, soffocando Miryam. Stringe forte i corpi del padre e della sorella."
  },
  AvgDialog_47172_Content_109 = {
    Text = "La pioggia sembra attenuarsi un poco. Alza lo sguardo e nota un ombrello nero che le scherma il cielo."
  },
  AvgDialog_47172_Content_11 = {
    Text = "\"Sei fortunata che oggi è solo un'esercitazione senza un sacerdote a sorvegliare, altrimenti ti saresti beccata un altro rimprovero.\""
  },
  AvgDialog_47172_Content_110 = {
    Text = "Miryam si volta. Una fila di guardie si erge alle sue spalle, con il sacerdote anziano in sacre vesti al centro."
  },
  AvgDialog_47172_Content_111 = {
    Text = "Scorgendo un'ancora di salvezza, si inginocchia e striscia verso il vecchio."
  },
  AvgDialog_47172_Content_112 = {
    Text = "\"Vostra Eminenza! Vostra Eminenza, vi prego, salvate mio padre!\""
  },
  AvgDialog_47172_Content_113 = {
    Text = "\"Guardie, portatela via.\""
  },
  AvgDialog_47172_Content_114 = {
    Text = "\"Confesserò i miei peccati! Ma mio padre, lui è sempre stato il più devoto Credente del Signore... Vi prego, salvatelo!\""
  },
  AvgDialog_47172_Content_115 = {
    Text = "\"Tu non capisci, Miryam.\""
  },
  AvgDialog_47172_Content_116 = {
    Text = "\"A Lemuria non importa della vita di un Credente, né dei tuoi peccati.\""
  },
  AvgDialog_47172_Content_117 = {
    Text = "\"A Lemuria importa solo del futuro preannunciato nei sogni — il futuro del Reame Divino.\""
  },
  AvgDialog_47172_Content_118 = {
    Text = "\"Tu potresti far parte di quel futuro, ma... dipende dalla tua Scelta.\""
  },
  AvgDialog_47172_Content_119 = {
    Text = "Il sacerdote anziano alza lo sguardo verso il cielo moribondo. Il suo sguardo affilato sembra penetrare le nuvole, intavolando una negoziazione silenziosa con qualcosa di lontano."
  },
  AvgDialog_47172_Content_12 = {
    Text = "\"Essere sgridata è l'ultimo dei miei problemi. Se fossi il Sacerdote, mi sarei già espulsa dalle file delle apprendiste sacerdote.\""
  },
  AvgDialog_47172_Content_120 = {
    Text = "\"Miryam, sei disposta a consacrarti al Signore?\""
  },
  AvgDialog_47172_Content_121 = {
    Text = "\"Sono disposta, Vostra Grazia, sono disposta a offrire la mia devozione! Sono una Sua credente... sono disposta a offrirGli ogni cosa!\""
  },
  AvgDialog_47172_Content_122 = {
    Text = "\"Dunque, uccideresti tuo padre per il Signore?\""
  },
  AvgDialog_47172_Content_123 = {
    Text = "\"Cosa... io...\""
  },
  AvgDialog_47172_Content_124 = {
    Text = "\"Miryam, sei disposta a consacrarti a Lui?!\""
  },
  AvgDialog_47172_Content_125 = {
    Text = "Il Vecchio Sommo Sacerdote le si avvicina d'improvviso, i suoi occhi la fissano affilati come una Lama."
  },
  AvgDialog_47172_Content_126 = {
    Text = "Miryam si immobilizza. La domanda improvvisa e il suo tono quasi tramortiscono la sua mente, al punto che dimentica di implorare per suo padre."
  },
  AvgDialog_47172_Content_127 = {
    Text = "\"C'è un modo per tenere in vita tuo padre.\""
  },
  AvgDialog_47172_Content_128 = {
    Text = "\"Vostra Eminenza?!!!\""
  },
  AvgDialog_47172_Content_129 = {
    Text = "\"Ora rispondimi. Cos'è la devozione?\""
  },
  AvgDialog_47172_Content_13 = {
    Text = "\"Lo sai, eh? Come fai a sorridere ancora! Sono passati quasi sei mesi e non sei ancora riuscita a portare a termine il rito di conversione dei popoli-pesce nemmeno una volta — sarà pericoloso per te!\""
  },
  AvgDialog_47172_Content_130 = {
    Text = "\"Io... non lo so... Vostra Grazia...\""
  },
  AvgDialog_47172_Content_131 = {
    Text = "\"La devozione è il luogo in cui tutte le vostre offerte trovano il loro merito, dove ogni vostro significato si aggrappa. La devozione è l'esclusione di qualsiasi altro pensiero impuro.\""
  },
  AvgDialog_47172_Content_132 = {
    Text = "\"Solo attraverso la devozione al Signore potrai salvare tuo padre. Ma per raggiungere tale devozione, devi prima uccidere tuo padre.\""
  },
  AvgDialog_47172_Content_133 = {
    Text = "\"Vostra Eminenza... Non capisco...\""
  },
  AvgDialog_47172_Content_134 = {
    Text = "Il Vecchio Sommo Sacerdote avanza lentamente verso Miryam. I suoi occhi si fissano sul volto di lei, scrutando ogni increspatura della sua espressione."
  },
  AvgDialog_47172_Content_135 = {
    Text = "\"L'unica possibilità per tuo padre risiede nel rito di conversione in uomini-pesce.\""
  },
  AvgDialog_47172_Content_136 = {
    Text = "\"Dimentica tuo padre. Dimentica la tua famiglia. Consacrati al Signore di Lemuria, lodaLo, obbedisciGli. Ascolta la Sua guida, celebra il rito di conversione come ogni sacerdote.\""
  },
  AvgDialog_47172_Content_137 = {
    Text = "\"Per salvare tuo padre e espiare i tuoi peccati, questa è l'unica via.\""
  },
  AvgDialog_47172_Content_138 = {
    Text = "Fissa lo sguardo direttamente sulla figura fragile e sgretolata di Miryam, riversa a terra. La sua esitazione si scioglie nella risolutezza, sfumata dalla pioggia battente, come se stesse contemplando una profezia di distruzione e rinascita dalla terra, di abisso e speranza."
  },
  AvgDialog_47172_Content_139 = {
    Text = "\"Dunque, Miryam, sei pronta a uccidere tuo padre?\""
  },
  AvgDialog_47172_Content_14 = {
    Text = "\"Impari quelle complesse teorie erboristiche più velocemente di chiunque altro. Perché non riesci a gestire questo rito allo stesso modo...\""
  },
  AvgDialog_47172_Content_15 = {
    Text = "\"Scusa, io... non riesco a infliggere loro una tale crudeltà... non ci riesco...\""
  },
  AvgDialog_47172_Content_16 = {
    Text = "\"Dici che non puoi fare una cosa simile con il tuo incredibile talento? Dai, segui le parole del nostro Vecchio Sommo Sacerdote, prega con tutto il cuore per il Signore e dimentica tutto il resto. Ce la puoi fare!\""
  },
  AvgDialog_47172_Content_17 = {
    Text = "\"Deborah, davvero non ci riesco... Ogni volta che vedo quelle Preghiere e quelle creature simili a pesci, non posso fare a meno di pensare alla mia famiglia.\""
  },
  AvgDialog_47172_Content_18 = {
    Text = "\"Coloro che mi hanno sempre protetta sono la mia famiglia, non il Signore...\""
  },
  AvgDialog_47172_Content_19 = {
    Text = "\"Shh! Che sciocchezze stai dicendo?!\""
  },
  AvgDialog_47172_Content_2 = {
    Text = "Diversi mesi dopo."
  },
  AvgDialog_47172_Content_20 = {
    Text = "\"Mio Signore, vi prego, perdonate Miryam; la sua mente è stata completamente terrorizzata dai popoli-pesce... Vi prego, perdonatela, vi prego...\""
  },
  AvgDialog_47172_Content_21 = {
    Text = "Deborah si inchina con reverenza verso la Statua nella stanza di Preghiera, poi si volta e lancia a Miryam un'occhiata feroce."
  },
  AvgDialog_47172_Content_22 = {
    Text = "\"Misura le tue parole! Se Egli le udisse, saresti punita!\""
  },
  AvgDialog_47172_Content_23 = {
    Text = "\"Scusa... non avrei dovuto dirlo...\""
  },
  AvgDialog_47172_Content_24 = {
    Text = "\"Non dovresti pensare così! Ah, lascia perdere. Non c'è fretta per queste cose. Faremo con calma.\""
  },
  AvgDialog_47172_Content_25 = {
    Text = "\"La maggior parte dei Lemuriani dedica la propria mente al nostro Signore, ma tu sembri preoccuparti più della tua famiglia. Eppure, non ti ho mai sentita parlare di loro, vero?\""
  },
  AvgDialog_47172_Content_26 = {
    Text = "\"Siete separati da sei mesi, devi sentire molto la loro mancanza... Ti va di parlarmene?\""
  },
  AvgDialog_47172_Content_27 = {
    Text = "\"Davvero? Non ti dispiace? Potrebbe volerci molto tempo, e sono solo un mucchio di piccole cose senza senso...\""
  },
  AvgDialog_47172_Content_28 = {
    Text = "\"Va bene, va bene. Adesso abbiamo tempo, no?"
  },
  AvgDialog_47172_Content_29 = {
    Text = "\"Fammi pensare da dove cominciare... Hmm, tanto tempo fa, vivevo con mio padre, mia Madre e la mia sorellina.\""
  },
  AvgDialog_47172_Content_3 = {
    Text = "Miryam fissa la creatura metà umana, metà pesce sull'altare di pietra, un Pugnale Rituale tra le mani."
  },
  AvgDialog_47172_Content_30 = {
    Text = "\"Poi una terribile calamità si abbatté su di noi, portandoci via nostra madre. Da allora nostro padre ci ha cresciute da solo. È un uomo straordinario, che ha sempre protetto con fermezza la nostra famiglia sotto le sue spalle.\""
  },
  AvgDialog_47172_Content_31 = {
    Text = "\"Quanto a mia sorella, è senza dubbio una dolcezza. Anche se a volte un po' sbadata, è intelligente e molto premurosa...\""
  },
  AvgDialog_47172_Content_32 = {
    Text = "\"In effetti, ora riesco a vedere alcune somiglianze tra te e lei. Dovrei davvero considerare di prendere un'altra sorellina oggi... che ne dici?\""
  },
  AvgDialog_47172_Content_33 = {
    Text = "\"Beh, Miryam, tu sì che sai come approfittarti di me!\""
  },
  AvgDialog_47172_Content_34 = {
    Text = "Miryam condivide raramente i dettagli della sua famiglia con gli altri. All'inizio la sua voce è spezzata dalla timidezza, le frasi intermittenti. Ma presto diventa loquace."
  },
  AvgDialog_47172_Content_35 = {
    Text = "Elenca le memorie della sua famiglia con dettagli vividi, riversandole su Deborah. Un sorriso caldo all'angolo della bocca, come se stesse esibendo i suoi tesori più amati."
  },
  AvgDialog_47172_Content_36 = {
    Text = "Tra il rombo lontano del tuono, camminano lungo il corridoio lungo e tranquillo, suoni di gioco colmano le pause tra i racconti eloquenti, risate gioiose si riversano sugli stagni silenziosi."
  },
  AvgDialog_47172_Content_37 = {
    Text = "\"...Il giorno prima di venire qui, mi ha preparato un tavolo intero di pesce. Ho finto che mi piacesse moltissimo e ho mangiato tutto il pesce nel piatto che mi aveva dato. Sembrava così felice in quel momento.\""
  },
  AvgDialog_47172_Content_38 = {
    Text = "\"Ahahah... Se tuo padre scoprisse la verità, diventerebbe sicuramente una furia!\""
  },
  AvgDialog_47172_Content_39 = {
    Text = "\"Io e mia sorella abbiamo stretto un patto: non farglielo mai scoprire. Quando torno a casa, senza dubbio dovrò mangiare di nuovo i suoi piatti di pesce... Ugh, solo a pensarci mi viene mal di testa.\""
  },
  AvgDialog_47172_Content_4 = {
    Text = "Il Ringhio del vento furioso e della pioggia scrosciante penetra le spesse mura di pietra del santuario. Tuoni lontani gettano vaghi Echi nel Tempio."
  },
  AvgDialog_47172_Content_40 = {
    Text = "\"Mal di testa? Mi sembri piuttosto contenta, no? Soffri ma ti diverti~ Te lo meriti~\""
  },
  AvgDialog_47172_Content_41 = {
    Text = "Clang! Clang! Clang!—"
  },
  AvgDialog_47172_Content_42 = {
    Text = "Il fragore di armi che cozzano e passi affrettati irrompe bruscamente nella sala interna. I suoi echi minacciosi interrompono la loro conversazione."
  },
  AvgDialog_47172_Content_43 = {Text = "\"Alt!\""},
  AvgDialog_47172_Content_44 = {
    Text = "\"Emergenza! ... Calamità ... Valle Meridionale ... Vittime ... Squadra di Soccorso ... Attenzione alla Peste ...\""
  },
  AvgDialog_47172_Content_45 = {
    Text = "Alcune parole raggiungono le orecchie di Miryam mentre le guardie si affrettano nelle profondità del santuario interno. Lei si ferma di colpo."
  },
  AvgDialog_47172_Content_46 = {
    Text = "\"Valle Meridionale... Miryam, hai appena detto che casa tua si trova da quelle parti...\""
  },
  AvgDialog_47172_Content_47 = {
    Text = "\"Deborah, devo tornare indietro!\""
  },
  AvgDialog_47172_Content_48 = {
    Text = "Miryam annuisce rapidamente, i suoi occhi scrutano ansiosamente intorno."
  },
  AvgDialog_47172_Content_49 = {
    Text = "\"Sei impazzita? È un crimine grave per un'apprendista sacerdote lasciare il tempio senza permesso!\""
  },
  AvgDialog_47172_Content_5 = {
    Text = "\"Seguace del nostro signore, apri il tuo cuore al nostro signore...\""
  },
  AvgDialog_47172_Content_50 = {
    Text = "\"Non preoccuparti, Miryam... La tua famiglia starà bene...\""
  },
  AvgDialog_47172_Content_51 = {
    Text = "\"No, Deborah... Il terreno nella Valle Meridionale è insidioso... è già successo a mia madre...\""
  },
  AvgDialog_47172_Content_52 = {
    Text = "\"Ho un presentimento... devo tornare indietro!\""
  },
  AvgDialog_47172_Content_53 = {
    Text = "\"Ma... la convocazione di tutti gli apprendisti sta per iniziare, e non posso aiutarti in questo...\""
  },
  AvgDialog_47172_Content_54 = {
    Text = "\"Ah! Miryam... tu...\""
  },
  AvgDialog_47172_Content_55 = {
    Text = "Una forte sonnolenza sopraffà la sua mente. È l'effetto di qualche erba ipnotica usata nei riti sacrificali. I sacerdoti la portano sempre con sé."
  },
  AvgDialog_47172_Content_56 = {
    Text = "Aiuta i devoti a cercare la tranquillità. Aiuta anche il sacerdote ad alleviare il peso dei propri peccati."
  },
  AvgDialog_47172_Content_57 = {
    Text = "È sempre stata la più dotata nell'erboristeria tra tutti gli apprendisti. Deborah lo sa sempre."
  },
  AvgDialog_47172_Content_58 = {
    Text = "\"Non voglio trascinarti in tutto questo. Riposati un po'.\""
  },
  AvgDialog_47172_Content_59 = {
    Text = "\"Devo tornare indietro... perdonami, Deborah.\""
  },
  AvgDialog_47172_Content_6 = {
    Text = "\"Scusate... urgh—\""
  },
  AvgDialog_47172_Content_60 = {
    Text = "Adagia delicatamente Deborah in un angolo nascosto. Prima che le guardie tornino, si volta e corre verso l'esterno."
  },
  AvgDialog_47172_Content_61 = {Text = "..."},
  AvgDialog_47172_Content_62 = {
    Text = "\"Ascoltate il nostro Signore. Sottomettetevi al nostro Signore.\""
  },
  AvgDialog_47172_Content_63 = {
    Text = "Tempesta. Raffiche. Tuoni."
  },
  AvgDialog_47172_Content_64 = {
    Text = "\"Ai devoti, il Signore elargirà la Sua grazia.\""
  },
  AvgDialog_47172_Content_65 = {
    Text = "Le case crollano. La folla sommersa dalla pioggia — o dalle lacrime. Le pietre precipitano dai fianchi della montagna inghiottendo la città, come mattoncini giocattolo spinti giù da una mano invisibile."
  },
  AvgDialog_47172_Content_66 = {
    Text = "\"Gli anelanti, Egli risponde.\""
  },
  AvgDialog_47172_Content_67 = {
    Text = "Il mondo si tinge di rosso nei suoi occhi. Lo scenario di morte è offuscato da grida stigie."
  },
  AvgDialog_47172_Content_68 = {
    Text = "Dopo aver corso sotto la pioggia per ore, non riesce a capire se il luogo in cui è arrivata sia davvero la sua città natale."
  },
  AvgDialog_47172_Content_69 = {
    Text = "Perché tutte quelle strade e quegli edifici familiari sono scomparsi?"
  },
  AvgDialog_47172_Content_7 = {
    Text = "Corre verso il lato del santuario, coprendosi la bocca. Lo stomaco le si contrae così forte che riesce a malapena a reggersi appoggiandosi al muro."
  },
  AvgDialog_47172_Content_70 = {
    Text = "Perché tanti di quei vicini familiari non ci sono più?"
  },
  AvgDialog_47172_Content_71 = {
    Text = "Ha impiegato ogni sua forza per arrivare fin qui. Ma ora la sua sanità mentale urla di fuggire. Eppure le sue gambe la trascinano ancora verso casa."
  },
  AvgDialog_47172_Content_72 = {
    Text = "—La casa incisa di innumerevoli risate e lacrime. La casa devastata da un disastro dopo l'altro, ricostruita ancora e ancora."
  },
  AvgDialog_47172_Content_73 = {
    Text = "Il focolare sepolto tra le rovine, sotto i suoi occhi."
  },
  AvgDialog_47172_Content_74 = {
    Text = "\"A chi soffre, il Signore porterà rimedio.\""
  },
  AvgDialog_47172_Content_75 = {
    Text = "Tra le rovine di pietre aguzze e schegge, è inginocchiato l'uomo su cui ha sempre fatto affidamento."
  },
  AvgDialog_47172_Content_76 = {
    Text = "La schiena curva, piegata in un arco che imita un riparo logoro contro la pioggia sferzante."
  },
  AvgDialog_47172_Content_77 = {
    Text = "Ma la calamità non ha risparmiato nemmeno un brandello di quel rifugio. Per quanto si sia sforzato, la pioggia spietata continua a filtrare attraverso il suo esile torso, gocciolando sul corpo senza vita della bambina tra le sue braccia."
  },
  AvgDialog_47172_Content_78 = {
    Text = "Può solo sfiorarle il viso con le sue mani ruvide, ancora e ancora, asciugando l'acqua piovana dalla sua pelle, sentendo sotto le dita tremanti il calore e il colore svanire."
  },
  AvgDialog_47172_Content_79 = {
    Text = "\"Sa... Sarah... no...\""
  },
  AvgDialog_47172_Content_8 = {
    Text = "\"Miryam, stai bene?\""
  },
  AvgDialog_47172_Content_80 = {
    Text = "La gola di Miryam si serra, la sua voce quasi un sussurro. Avanza, inciampa, cade in ginocchio, striscia. Le sue mani tremano d'incredulità mentre toccano il corpo della sorella."
  },
  AvgDialog_47172_Content_81 = {
    Text = "\"Dormiva quando è successo. Lo sai, Sarah ha sempre avuto il sonno pesante. Niente poteva svegliarla.\""
  },
  AvgDialog_47172_Content_82 = {
    Text = "\"Se n'è andata in pace... nessun terrore, nessun dolore, nessun indugio... non mi ha lasciato nulla.\""
  },
  AvgDialog_47172_Content_83 = {
    Text = "\"Me lo sono detto quando tua madre è venuta a mancare.\""
  },
  AvgDialog_47172_Content_84 = {
    Text = "\"Non potevo fare altro che ripetermelo, Miryam... Non sono riuscito a proteggerle. Non sono riuscito...\""
  },
  AvgDialog_47172_Content_85 = {
    Text = "L'uomo crede che le sue lacrime si siano prosciugate da tempo, ma non appena mormora poche parole, si mescolano di nuovo alla pioggia. Le sue labbra pallide tremano, forse per il freddo e la stanchezza, forse per il dolore."
  },
  AvgDialog_47172_Content_86 = {
    Text = "Una serie di colpi di tosse dolorosi gli esplode dal petto. Solo allora Miryam nota che la carne di Enos su una gamba e sull'addome si è aperta come carta crespa. Le ultime gocce del suo sangue stanno stillando fuori."
  },
  AvgDialog_47172_Content_87 = {
    Text = "\"Padre! Siete... siete ferito?...\""
  },
  AvgDialog_47172_Content_88 = {
    Text = "Fruga tra un fascio di erbe. Con la mente annebbiata dalla confusione, le applica tutte sulle ferite del padre. Il suo sguardo saccheggia selvaggiamente le rovine circostanti, in cerca di qualsiasi cosa utile."
  },
  AvgDialog_47172_Content_89 = {
    Text = "\"Miryam, è inutile.\""
  },
  AvgDialog_47172_Content_9 = {
    Text = "\"Sto bene... Scusa, Deborah, ti ho fatto aspettare...\""
  },
  AvgDialog_47172_Content_90 = {
    Text = "\"Posso salvarvi... posso salvarvi, Padre!\""
  },
  AvgDialog_47172_Content_91 = {
    Text = "\"Ho fatto tutto ciò che potevo, Miryam. Ma è stato inutile... Se ne sono andate lo stesso. Tua madre, tua sorella...\""
  },
  AvgDialog_47172_Content_92 = {
    Text = "\"Uno come me è insignificante a Lemuria, qualunque cosa faccia...\""
  },
  AvgDialog_47172_Content_93 = {
    Text = "Si sforza di sollevare il capo, fissando la Catena Montuosa crollata, le rovine tutt'intorno e il cielo freddo e distante, rimasto indifferente dopo aver riversato tale catastrofe sull'isola."
  },
  AvgDialog_47172_Content_94 = {
    Text = "Seguendo il suo Sguardo, Miryam osserva le montagne su entrambi i lati."
  },
  AvgDialog_47172_Content_95 = {
    Text = "\"Padre, quella è...\""
  },
  AvgDialog_47172_Content_96 = {
    Text = "Enormi massi si staccano dalla montagna, inghiottendo completamente l'intera città in un istante."
  },
  AvgDialog_47172_Content_97 = {
    Text = "Diversi tentacoli enormi si protendono dal terreno, bloccando la maggior parte delle rocce devastanti."
  },
  AvgDialog_47172_Content_98 = {
    Text = "Enos abbassa il capo. I suoi occhi che si spengono contemplano la figlia, la sua unica speranza e il suo unico orgoglio rimasti."
  },
  AvgDialog_47172_Content_99 = {
    Text = "\"È la manifestazione del Signore...\""
  },
  AvgDialog_47173_Content_1 = {
    Text = "Offerta al Re"
  },
  AvgDialog_47173_Content_10 = {
    Text = "Ricordo, Padre... Ricordo sempre."
  },
  AvgDialog_47173_Content_100 = {
    Text = "Se non riuscirai ad accedere al Suo sogno, ne risulterà una morte atroce."
  },
  AvgDialog_47173_Content_101 = {
    Text = "Altrimenti, indossa questi abiti. Ti guiderò a diventare una vera sacerdotessa di Lemuria."
  },
  AvgDialog_47173_Content_102 = {
    Text = "Il sacerdote anziano emette un profondo sospiro, lasciando la stanza di preghiera. La schiena curva, come se avesse portato a termine un compito gravoso, o come se la sua anima stesse soffrendo per un crimine efferato appena commesso."
  },
  AvgDialog_47173_Content_103 = {
    Text = "Miryam si avvicina alla statua meccanicamente e solleva il calice di vino."
  },
  AvgDialog_47173_Content_104 = {
    Text = "Hai ucciso tuo padre."
  },
  AvgDialog_47173_Content_105 = {
    Text = "Una bambina siede accanto a Miryam. Ha un volto che Miryam non potrebbe conoscere meglio, eppure avverte un totale senso di estraneità."
  },
  AvgDialog_47173_Content_106 = {
    Text = "Miryam, diciottenne, volge il capo, osservando la sé stessa di nove anni fissare la statua dinanzi a loro."
  },
  AvgDialog_47173_Content_107 = {
    Text = "No, ho salvato nostro padre... Ci ha protette innumerevoli volte. Ora tocca a noi proteggerlo."
  },
  AvgDialog_47173_Content_108 = {
    Text = "Ma tuo padre non vorrebbe vederti così..."
  },
  AvgDialog_47173_Content_109 = {
    Text = "Lo farà. Mio padre soffrirà, piangerà, ma mi sosterrà."
  },
  AvgDialog_47173_Content_11 = {
    Text = "Il selciato qui è così simile a quello che portava al Focolare."
  },
  AvgDialog_47173_Content_110 = {
    Text = "Solo allora potrò davvero assistere nella riforma di Lemuria, portando il Reame Divino a lui..."
  },
  AvgDialog_47173_Content_111 = {
    Text = "Pochi riescono a sopportare una tale quantità di sangue di Hydra. Brami la morte, non è vero?"
  },
  AvgDialog_47173_Content_112 = {
    Text = "Miryam... credi nel Reame Divino?"
  },
  AvgDialog_47173_Content_113 = {
    Text = "Miryam fissa gli occhi della bambina come se guardasse una divinità ingenua. Una quantità incommensurabile di inconsolabile pianto si cela negli occhi della bambina di nove anni, inondando la vista della diciottenne Miryam."
  },
  AvgDialog_47173_Content_114 = {
    Text = "...In cos'altro potrei credere?"
  },
  AvgDialog_47173_Content_115 = {
    Text = "Miryam le sorride, alza il calice e rivolge uno sguardo devoto alla statua dinanzi a sé."
  },
  AvgDialog_47173_Content_116 = {
    Text = "Ti offrirò ogni cosa. Esaudisci le mie brame, mio Signore."
  },
  AvgDialog_47173_Content_117 = {
    Text = "Il sangue di suo padre le cola dal viso, mescolandosi a quello dell'hydra in silenziose increspature."
  },
  AvgDialog_47173_Content_118 = {
    Text = "Senza la minima esitazione, reclina il capo all'indietro e ingoia il liquido in un solo sorso. Un forte odore di pesce la avvolge nell'abisso dell'oscurità."
  },
  AvgDialog_47173_Content_12 = {
    Text = "Mia figlia è cresciuta, ormai. Quando sono stanco, ho finalmente qualcuno a cui appoggiarmi."
  },
  AvgDialog_47173_Content_13 = {
    Text = "Suo padre, l'uomo che un tempo si ergeva dinanzi a lei come un guardiano divino, colui che non ha mai cessato di proteggerla e sostenere l'intera famiglia, ora si rannicchia accanto a lei, invecchiato e debole."
  },
  AvgDialog_47173_Content_14 = {
    Text = "È come un'ostrica che si camuffa da pietra solida per occultare il suo cuore fragile — immobile finché il suo guscio non si frantuma in mille pezzi."
  },
  AvgDialog_47173_Content_15 = {
    Text = "Siamo arrivati. Puoi scendere ora."
  },
  AvgDialog_47173_Content_16 = {
    Text = "Il carro si ferma. Nella penombra della camera rituale, le lampade a olio ardono fioche. Il candelabro ruota lentamente, la sua superficie incisa con tentacoli guizzanti e occhi sporgenti — tutti intenti a osservare le persone che si muovono indaffarate in basso."
  },
  AvgDialog_47173_Content_17 = {
    Text = "Un solitario letto di pietra attende al centro di un cerchio magico, circondato da antichi glifi tracciati col sangue."
  },
  AvgDialog_47173_Content_18 = {
    Text = "Miryam aiuta suo padre a distendersi sull'altare di pietra."
  },
  AvgDialog_47173_Content_19 = {
    Text = "La Vitalità di Enos sembra prosciugarsi con quei pochi passi soltanto. Tossisce dolorosamente, raggiungendo la soglia dello Svenimento."
  },
  AvgDialog_47173_Content_2 = {
    Text = "Ecco com'è all'interno del Tempio..."
  },
  AvgDialog_47173_Content_20 = {
    Text = "Va tutto bene, Padre, va tutto bene... Starai meglio presto..."
  },
  AvgDialog_47173_Content_21 = {
    Text = "Hai fallito il rito qui, in questa stanza. Molte volte."
  },
  AvgDialog_47173_Content_22 = {
    Text = "Io... ricordo, Vostra Eminenza."
  },
  AvgDialog_47173_Content_23 = {
    Text = "Il tuo Rito fallirà ancora, a meno che tu non offra una Devozione incondizionata ai decreti del Signore e non ottenga la Sua approvazione."
  },
  AvgDialog_47173_Content_24 = {
    Text = "Puoi rinunciare. Mi assicurerò che la sua morte sia indolore."
  },
  AvgDialog_47173_Content_25 = {Text = "Io..."},
  AvgDialog_47173_Content_26 = {
    Text = "Questo è il tuo destino. Riflettici bene, e poi prendi la tua decisione."
  },
  AvgDialog_47173_Content_27 = {
    Text = "Le Guardie posano gli strumenti e i materiali necessari per il Rito e lasciano la stanza insieme al Vecchio Sommo Sacerdote."
  },
  AvgDialog_47173_Content_28 = {
    Text = "La fioca luce delle candele avvolge gli ultimi due occupanti della stanza."
  },
  AvgDialog_47173_Content_29 = {
    Text = "Miryam si inginocchia accanto all'altare di pietra, seppellendo il viso nel petto di suo padre."
  },
  AvgDialog_47173_Content_3 = {
    Text = "Sarah qualche giorno fa ha detto che le mancava sua sorella. Ha detto che voleva venire qui a vedere la dimora della sorella."
  },
  AvgDialog_47173_Content_30 = {
    Text = "Cosa dovrei fare... Padre..."
  },
  AvgDialog_47173_Content_31 = {
    Text = "Stai piangendo, bambina... Cosa rende la nostra piccola Miryam così triste?"
  },
  AvgDialog_47173_Content_32 = {
    Text = "Un paio di mani sfiora delicatamente la testa di Miryam, accarezzandole piano i capelli. Come sempre. Come in ogni occasione in cui il Pianto l'aveva trovata. Sempre, e per sempre."
  },
  AvgDialog_47173_Content_33 = {
    Text = "Miryam non riesce più a trattenere le lacrime. Cadono sul corpo madido di Enos, mentre il suo corpo trema scosso da singhiozzi strazianti."
  },
  AvgDialog_47173_Content_34 = {
    Text = "Stringe forte le mani di suo padre, come se quella presa serrata potesse trattenerlo al suo fianco."
  },
  AvgDialog_47173_Content_35 = {
    Text = "Miryam, senti? Tua madre ci chiama a Casa per cena. E Sarah al suo fianco, che ci saluta con la mano..."
  },
  AvgDialog_47173_Content_36 = {
    Text = "Li vedo... Padre, li vedo..."
  },
  AvgDialog_47173_Content_37 = {
    Text = "Ho detto a tua madre che oggi mangeremo pesce. Papà sa che è il tuo preferito."
  },
  AvgDialog_47173_Content_38 = {
    Text = "Tua madre ancora non sa che la nostra Miryam è diventata Apprendista sacerdote. Sarà senza dubbio sorpresa quando glielo diremo."
  },
  AvgDialog_47173_Content_39 = {
    Text = "Presto diventerai una sacerdotessa, vero?"
  },
  AvgDialog_47173_Content_4 = {
    Text = "Enos accarezza dolcemente il viso della sua figlioletta."
  },
  AvgDialog_47173_Content_40 = {
    Text = "...Sì, Padre, presto diventerò una sacerdotessa..."
  },
  AvgDialog_47173_Content_41 = {
    Text = "Lo so. Il tuo Talento è stupefacente, l'ho sempre saputo."
  },
  AvgDialog_47173_Content_42 = {
    Text = "La vita è sempre stata dura per i Lemuriani. Non mi è mai piaciuta Lemuria, figlia mia, eppure non posso andarmene... perché tu sei qui, la mia Casa è qui..."
  },
  AvgDialog_47173_Content_43 = {
    Text = "Sono capace di molte cose: costruire Case, pescare per vivere, cucinare per te... ma non posso cambiare nulla."
  },
  AvgDialog_47173_Content_44 = {
    Text = "Ma tu sei diversa, Miryam. Tu sarai la Sua Seguace più devota, Lo aiuterai a compiere la Profezia e a innalzare Lemuria nel Reame Divino della leggenda..."
  },
  AvgDialog_47173_Content_45 = {
    Text = "Ci saranno Festini senza fine e vino soave profumato di rose in fiore. Una brezza tiepida increspa la pioggia sussurrante, la luce del sole risplende verso il vasto orizzonte. Nessuna calamità, e nessuno che muoia per esse."
  },
  AvgDialog_47173_Content_46 = {
    Text = "Avremo una solida Casa di Pietra... Enos, Paya, Miryam, Sarah, insieme come una famiglia, vivremo lì felici per sempre..."
  },
  AvgDialog_47173_Content_47 = {
    Text = "Sì, Padre... ci rincontreremo nel Reame Divino! La nostra famiglia vivrà insieme nel Reame Divino..."
  },
  AvgDialog_47173_Content_48 = {
    Text = "Si asciuga le lacrime e si alza lentamente. La sua mano raggiunge il Pugnale accanto al letto."
  },
  AvgDialog_47173_Content_49 = {
    Text = "La Lama del Pugnale si piega in un arco bizzarro, incisa con intricati geroglifici che condividono una sconcertante somiglianza con quelli delle Preghiere."
  },
  AvgDialog_47173_Content_5 = {
    Text = "Erbe preziose hanno temporaneamente preservato la sua vita. Per la prima volta, questo devoto credente entra nel sacro sancta sanctorum, avvicinandosi così tanto al Signore."
  },
  AvgDialog_47173_Content_50 = {
    Text = "Sotto la luce tremolante delle candele, la Lama riflette la superficie Cremisi nel bacile di Pietra lì accanto. Il sangue sacro, omologo al Dio, ondeggia al suo interno, velato da un bagliore cupo e sinistro."
  },
  AvgDialog_47173_Content_51 = {
    Text = "Un grave Delirium ha fatto perdere a Enos gran parte della coscienza. Osserva Miryam con curiosità, come un neonato che vede il mondo per la prima volta."
  },
  AvgDialog_47173_Content_52 = {
    Text = "Miryam, ora sei una sacerdotessa... Hai chiesto al re? Il re ti ha detto quando il Reame Divino giungerà a Lemuria?"
  },
  AvgDialog_47173_Content_53 = {
    Text = "Sì, ho pregato per la Sua guida... Ha predetto che sarà presto, molto presto..."
  },
  AvgDialog_47173_Content_54 = {
    Text = "Un debole, pallido sorriso si forma tra le tracce aggrovigliate di lacrime. Si avvicina a Enos, si china e gli sfiora la guancia."
  },
  AvgDialog_47173_Content_55 = {
    Text = "Non ti deluderò, Padre."
  },
  AvgDialog_47173_Content_56 = {
    Text = "Il Reame Divino sta arrivando, Padre. Presto, la nostra famiglia si riunirà..."
  },
  AvgDialog_47173_Content_57 = {Text = "Puf—"},
  AvgDialog_47173_Content_58 = {
    Text = "Il pugnale affonda nel petto di Enos. Un ululato di agonia bruciante prorompe. Il suo sangue sprizza incontrollabile, macchiando la guancia destra di Miryam."
  },
  AvgDialog_47173_Content_59 = {
    Text = "Gli occhi di Miryam si spalancano mentre si concentra sulle ferite dove il pugnale incontra la carne, come se stesse osservando un capolavoro."
  },
  AvgDialog_47173_Content_6 = {
    Text = "Odio per la calamità, dolore per la perdita della figlia, paura della morte e la gioia del pellegrinaggio... Emozioni tumultuose dilaniano il suo corpo fragile. Si appoggia debolmente alla spalla di Miryam."
  },
  AvgDialog_47173_Content_60 = {
    Text = "Lacerando la pelle, perforando le vene, separando le ossa. Gli ululati di Enos non cessano mai, come una bestia moribonda dilaniata."
  },
  AvgDialog_47173_Content_61 = {
    Text = "Il sangue urla con ruggiti distorti. Spuntoni cremisi di violenza montante. Traboccando, perforano il volto e la pelle di Miryam prima di conficcarsi nei suoi visceri."
  },
  AvgDialog_47173_Content_63 = {
    Text = "\"Seguace del nostro signore, apri il tuo cuore al nostro signore...\""
  },
  AvgDialog_47173_Content_64 = {
    Text = "Sangue e lacrime inondano il volto stravolto di Miryam. Cantando preghiere, muove le mani sempre più velocemente."
  },
  AvgDialog_47173_Content_65 = {
    Text = "Quando il pugnale si ferma, i sigilli di felicità e speranza sono già incisi sul corpo di Enos, tra la sua carne tremante."
  },
  AvgDialog_47173_Content_66 = {
    Text = "\"Ai devoti, il Signore elargirà la Sua grazia...\""
  },
  AvgDialog_47173_Content_67 = {
    Text = "<Big:\"A chi anela, il Signore concederà...\">"
  },
  AvgDialog_47173_Content_68 = {
    Text = "Solleva il bacile contenente il sangue sacro e lo versa nelle ferite simili a sigilli sul corpo di Enos."
  },
  AvgDialog_47173_Content_69 = {
    Text = "Nel momento in cui il sangue sacro tocca quei sigilli, sembra acquisire vitalità. Vorticando sul corpo di Enos come un serpente, un senso di eccitazione nel percepire il calore della preda sembra propagarsi attraverso le sue tracce sinuose."
  },
  AvgDialog_47173_Content_7 = {
    Text = "Quando eri una bambina, venivi a pescare con me. Quando eri stanca, ti appoggiavi a me così mentre tornavamo a casa."
  },
  AvgDialog_47173_Content_70 = {
    Text = "Non c'è bisogno della guida di Miryam; seguono la fonte di calore, penetrando nel corpo di Enos attraverso le ferite."
  },
  AvgDialog_47173_Content_71 = {
    Text = "Man mano che il sangue fluisce, i ringhi di Enos diventano insopportabilmente intensi, mentre le sue ferite si rimarginano a velocità visibile."
  },
  AvgDialog_47173_Content_72 = {
    Text = "Nel frattempo, i suoi lineamenti iniziano a degenerare; gli occhi diventano enormi e sporgenti, le labbra si fanno viscide e la testa si allunga, appiattendosi."
  },
  AvgDialog_47173_Content_73 = {
    Text = "Un organo simile a branchie appare sul suo collo. Squame scivolose sostituiscono i capelli, crescendo da varie parti del corpo."
  },
  AvgDialog_47173_Content_74 = {
    Text = "Geme ancora di dolore, ma i suoi suoni si trasformano gradualmente in stridii colmi dell'aria umida e stagnante di acqua salmastra..."
  },
  AvgDialog_47173_Content_75 = {
    Text = "Ce l'ho fatta, Padre... Non ti ho deluso, vero?"
  },
  AvgDialog_47173_Content_76 = {
    Text = "Il sibilo si interrompe. Il mostro metà pesce, metà umano la fissa con sguardo vacuo. I suoi occhi enormi sporgono pallidamente, la sua intelligenza dissolta."
  },
  AvgDialog_47173_Content_77 = {
    Text = "Miryam si avvicina all'altare di pietra, accarezzando il mostro. Il denso odore di pesce le invade le narici, la pelle sotto le sue mani appiccicosa e scivolosa."
  },
  AvgDialog_47173_Content_78 = {
    Text = "Quell'odore e quella sensazione un tempo la disgustava. Ma ora li trova più confortanti che mai."
  },
  AvgDialog_47173_Content_79 = {
    Text = "Adoro il pesce. Quando ci rincontreremo nel Reame Divino, mangerò il pesce che cucini ogni giorno..."
  },
  AvgDialog_47173_Content_8 = {
    Text = "Ti addormentavi al dolce dondolio della barca. Quando ti svegliavi, eravamo già a casa. Tua madre era incinta di tua sorella, all'epoca, eppure percorse un lungo cammino per venirci incontro sulla riva."
  },
  AvgDialog_47173_Content_80 = {
    Text = "Aspettami, Padre."
  },
  AvgDialog_47173_Content_81 = {
    Text = "Si china verso la creatura e le bacia la guancia. Viscida, umida, inconfondibilmente calda."
  },
  AvgDialog_47173_Content_82 = {Text = "..."},
  AvgDialog_47173_Content_83 = {
    Text = "La porta d'ardesia scorre aperta. Le guardie si fanno da parte, aprendo un varco."
  },
  AvgDialog_47173_Content_84 = {
    Text = "Passi fermi avanzano lentamente verso la stanza e si arrestano alle spalle di Miryam."
  },
  AvgDialog_47173_Content_85 = {
    Text = "Se desideri trasformarti in uno degli uomini-pesce e vivere con tuo padre, posso assisterti."
  },
  AvgDialog_47173_Content_86 = {
    Text = "Miryam scuote dolcemente la testa."
  },
  AvgDialog_47173_Content_87 = {
    Text = "Per qualcuno come te, conservare la sanità mentale sarebbe assai più doloroso che abbandonarla."
  },
  AvgDialog_47173_Content_88 = {
    Text = "In effetti, Vostra Grazia, ma io non ho paura del dolore..."
  },
  AvgDialog_47173_Content_89 = {
    Text = "Si inginocchia dinanzi al Vecchio Sommo Sacerdote."
  },
  AvgDialog_47173_Content_9 = {
    Text = "Insistevo perché riposasse a casa, ma non mi ascoltava mai... Te lo ricordi, Miryam?"
  },
  AvgDialog_47173_Content_90 = {
    Text = "Vi prego, concedetemi un'altra possibilità... Diventerò la migliore sacerdotessa di Lemuria. Vi prego, permettetemi di dimostrarvelo."
  },
  AvgDialog_47173_Content_91 = {
    Text = "Mi unirò a voi nell'assistere il nostro Signore e nel portare il Reame Divino a Lemuria!"
  },
  AvgDialog_47173_Content_92 = {
    Text = "Dunque, uccideresti tuo padre per il Signore?"
  },
  AvgDialog_47173_Content_93 = {
    Text = "Sì, Vostra Grazia. Lo farò. Offrirò ogni cosa per il Signore."
  },
  AvgDialog_47173_Content_94 = {
    Text = "Questo è l'unico modo per salvare il mio focolare e mio padre."
  },
  AvgDialog_47173_Content_95 = {
    Text = "Il Signore è mio padre. Il Signore è il mio focolare... Egli è l'unica verità di Lemuria."
  },
  AvgDialog_47173_Content_96 = {
    Text = "Metà del volto di Miryam è imbrattata di cremisi dal sangue di suo padre, come una splendida maschera rossa che non potrà mai essere lavata via."
  },
  AvgDialog_47173_Content_97 = {
    Text = "Lo sguardo tagliente del Vecchio Sommo Sacerdote si addolcì infine per un istante."
  },
  AvgDialog_47173_Content_98 = {
    Text = "Indica il tavolo lì accanto. Vi sono stati posati un calice di vino e un abito."
  },
  AvgDialog_47173_Content_99 = {
    Text = "Bevi il sangue dell'Hydra, intona la preghiera e prega il Signore."
  },
  AvgDialog_47174_Content_1 = {
    Text = "Rito della Sacerdotessa"
  },
  AvgDialog_47174_Content_10 = {
    Text = "La sua storia si è propagata in ogni angolo della terra. Si narra che abbia scorto la presenza umbratile del Signore durante la sua prima preghiera come apprendista sacerdote."
  },
  AvgDialog_47174_Content_11 = {
    Text = "Mentre gli altri sacerdoti trascorrono di solito almeno una settimana a letto dopo aver bevuto il sangue dell'hydra, lei ne è rimasta del tutto immune."
  },
  AvgDialog_47174_Content_12 = {
    Text = "Così giovane, eppure così vicina al Signore e capace di tanto per Lemuria. È davvero invidiabile."
  },
  AvgDialog_47174_Content_13 = {
    Text = "Se potessi prendere il suo posto, sacrificherei qualsiasi cosa..."
  },
  AvgDialog_47174_Content_14 = {
    Text = "Ah! Guardate, è la Somma Sacerdotessa Ascendente!"
  },
  AvgDialog_47174_Content_15 = {
    Text = "Una brezza attraversa la sala; la luce delle candele trema. Un gruppo di guardie esce in fila e si dispone su entrambi i lati dell'altare."
  },
  AvgDialog_47174_Content_16 = {
    Text = "Nel Suo sogno sul trono, il Re udì la rivelazione divina:"
  },
  AvgDialog_47174_Content_17 = {
    Text = "Le tempeste di Lemuria si placheranno. L'abisso di Lemuria svanirà."
  },
  AvgDialog_47174_Content_18 = {
    Text = "Il Re farà scudo al suo popolo benevolo e darà vita al Reame Divino."
  },
  AvgDialog_47174_Content_19 = {
    Text = "Sia lode al nostro Signore."
  },
  AvgDialog_47174_Content_2 = {
    Text = "Guarda, un altro acquazzone sta per arrivare... Il tempo sta davvero peggiorando."
  },
  AvgDialog_47174_Content_20 = {
    Text = "Sia lode al nostro Signore!"
  },
  AvgDialog_47174_Content_21 = {
    Text = "La voce sembra giungere da una distanza immensa, sommessa eppure cristallina."
  },
  AvgDialog_47174_Content_22 = {
    Text = "Accolta dagli sguardi degli apprendisti sacerdoti, una figura purpurea emerge lentamente dal tempio interno."
  },
  AvgDialog_47174_Content_23 = {
    Text = "Il suo aspetto è celato sotto un velo di maglia viola pallido. Due viticci di nebbia nera si avvolgono dietro di lei, come due serpenti striscianti privi di forma definita."
  },
  AvgDialog_47174_Content_24 = {
    Text = "Eppure sotto quello sguardo pacato si cela un potere immenso. La quiete che emana da dietro il suo velo fluttuante costringe il respiro di tutti a rallentare."
  },
  AvgDialog_47174_Content_25 = {
    Text = "Sua Grazia non è stato bene di recente. Condurrò io il rito di conversione dei popoli-pesce."
  },
  AvgDialog_47174_Content_26 = {
    Text = "Portate qui i pionieri."
  },
  AvgDialog_47174_Content_27 = {
    Text = "Scortati dalle guardie, un uomo e sua figlia entrano nella sala."
  },
  AvgDialog_47174_Content_28 = {
    Text = "La fioca luce delle candele trema su un candeliere umido. Tutto sembra esattamente come tre anni fa."
  },
  AvgDialog_47174_Content_29 = {
    Text = "Il padre semicosciente viene adagiato sull'altare di pietra. La figlia adolescente si dimena e piange sotto la presa delle guardie."
  },
  AvgDialog_47174_Content_3 = {
    Text = "Ogni sorta di calamità, grandi e piccole, si è fatta assai più frequente negli ultimi anni. Specialmente quella nella Valle Meridionale, tre anni fa, che ha mietuto molte vite..."
  },
  AvgDialog_47174_Content_30 = {
    Text = "Signora Sacerdotessa! Vi prego, vi prego, abbiate pietà di lui..."
  },
  AvgDialog_47174_Content_31 = {
    Text = "Mio padre ha rubato solo un poco... Mia madre è morta nella calamità, e poiché mio padre non aveva denaro, è stato costretto a rubare..."
  },
  AvgDialog_47174_Content_32 = {
    Text = "Sono disposta a offrire tutto, vi prego, risparmiate mio padre..."
  },
  AvgDialog_47174_Content_33 = {
    Text = "Disposta a offrire tutto... Dunque, uccideresti tuo padre per il Signore?"
  },
  AvgDialog_47174_Content_34 = {
    Text = "...Signora Sacerdotessa?"
  },
  AvgDialog_47174_Content_35 = {
    Text = "Lo smarrimento sul volto della ragazza risulta familiare a Miryam. Tutti devono attraversare una fase come questa. Nessuno lo sa meglio di lei."
  },
  AvgDialog_47174_Content_36 = {
    Text = "Si fa avanti e sfiora delicatamente il capo della ragazza."
  },
  AvgDialog_47174_Content_37 = {
    Text = "Non temere, devoto del nostro Signore."
  },
  AvgDialog_47174_Content_38 = {
    Text = "Vieni, vieni qui."
  },
  AvgDialog_47174_Content_39 = {
    Text = "Prende la mano della ragazza, guidandola verso la guancia del padre, accarezzandola con dolcezza."
  },
  AvgDialog_47174_Content_4 = {
    Text = "In effetti... Ma da quando la nuova Vice Somma Sacerdotessa Ascendente ha assunto l'incarico, vi sono stati anche molti miglioramenti. La ristrutturazione delle case dei seguaci, le ampie selezioni sacerdotali e le cerimonie rituali sono state tutte organizzate da lei."
  },
  AvgDialog_47174_Content_40 = {
    Text = "Dimmi, tu e tuo padre anelate al Reame Divino?"
  },
  AvgDialog_47174_Content_41 = {
    Text = "Noi... aneliamo al Reame Divino..."
  },
  AvgDialog_47174_Content_42 = {
    Text = "Bene. I Lemuriani dovrebbero anelare al Reame Divino."
  },
  AvgDialog_47174_Content_43 = {
    Text = "Là giace tutto ciò che desideri. Nessuna calamità. Nessun dolore... Il Reame Divino dovrebbe essere la prima e unica cosa a cui aneliamo."
  },
  AvgDialog_47174_Content_44 = {
    Text = "Pone il Pugnale Rituale nelle mani tremanti della ragazza e le avvolge delicatamente con le proprie."
  },
  AvgDialog_47174_Content_45 = {
    Text = "Voi non siete criminali. L'amore che vi lega — l'amore familiare — è sincero e davvero encomiabile. Ciò che avete fatto non dovrebbe essere considerato un crimine."
  },
  AvgDialog_47174_Content_46 = {
    Text = "Ecco perché potete venire qui. Siete degni di offrire il vostro Potere per l'Avvento del Regno Divino."
  },
  AvgDialog_47174_Content_47 = {
    Text = "No... Signora Sacerdotessa, vi prego, non puniteci se non siamo stati giudicati colpevoli di alcun crimine... Vi prego, vi supplichiamo, mostrate la vostra misericordia..."
  },
  AvgDialog_47174_Content_48 = {
    Text = "Punire? No, mia pia devota del Signore, questa non è una Punizione. Questa è la grazia del Signore su di voi —"
  },
  AvgDialog_47174_Content_49 = {Text = "Puf—"},
  AvgDialog_47174_Content_5 = {
    Text = "E un simile rito di conversione non era mai stato celebrato in pubblico prima d'oggi."
  },
  AvgDialog_47174_Content_50 = {Text = "ARGH!!"},
  AvgDialog_47174_Content_51 = {
    Text = "La presa di Miryam sulla mano della ragazza si stringe, costringendole a colpire verso il basso. La Lama del Pugnale Rituale affonda completamente nel petto dell'uomo."
  },
  AvgDialog_47174_Content_52 = {
    Text = "Il sangue schizza, ricoprendo il volto della ragazza. Le urla strazianti del padre e le grida acute della figlia echeggiano nella stanza."
  },
  AvgDialog_47174_Content_53 = {
    Text = "Non temere, nostra devota Seguace. La gloria della conversione giungerà a te dopo che il Rito di tuo padre sarà Completo."
  },
  AvgDialog_47174_Content_54 = {
    Text = "Potrai ancora vivere con tuo padre. Pagherò io il prezzo di una vita lucida per te."
  },
  AvgDialog_47174_Content_55 = {
    Text = "Il Pugnale passeggia sul corpo del padre al ritmo della sua voce. Un tale Rito è stato celebrato innumerevoli volte nel corso degli anni."
  },
  AvgDialog_47174_Content_56 = {
    Text = "Un sapore di felicità si gonfia, avvolgendola nell'estasi. Il sangue schizzato e le Espressioni contorte costituiscono le scale che conducono al Reame Divino. I Lemuriani dovrebbero Abbracciarlo nella più assoluta felicità."
  },
  AvgDialog_47174_Content_57 = {
    Text = "Mostra la tua Devozione al Signore come me. Attendi con pazienza come me. Anela al Ricongiungimento che si avvicina nel Reame Divino come me."
  },
  AvgDialog_47174_Content_58 = {Text = "..."},
  AvgDialog_47174_Content_59 = {Text = "Splash—"},
  AvgDialog_47174_Content_6 = {
    Text = "Ho sentito dire che viene dalla Valle Meridionale. È vero?"
  },
  AvgDialog_47174_Content_60 = {
    Text = "Il Rito può sembrare lungo per gli apprendisti sacerdoti, ma per Miryam si conclude in fretta."
  },
  AvgDialog_47174_Content_61 = {
    Text = "Due Mostri metà umani, metà pesci vengono gettati nella vasca. Miryam si ferma accanto alla vasca, chinandosi. La sua mano sfiora delicatamente la loro pelle viscida."
  },
  AvgDialog_47174_Content_62 = {
    Text = "Il fetore denso le riempie i polmoni, l'acqua lurida della vasca le inzuppa il vestito, ma a lei non importa."
  },
  AvgDialog_47174_Content_63 = {
    Text = "Le conversioni di quegli uomini-pesce sono più complete che mai. La vostra Abilità nel Rito si fa sempre più raffinata, Somma Sacerdotessa Ascendente."
  },
  AvgDialog_47174_Content_64 = {
    Text = "Deborah, te l'ho detto tante volte, non chiamarmi così."
  },
  AvgDialog_47174_Content_65 = {
    Text = "Si volta e rivolge un sorriso caloroso alla sua unica amica."
  },
  AvgDialog_47174_Content_66 = {
    Text = "Come vola il tempo. Ricordo ancora la tua Espressione terrorizzata quando vedesti quei pionieri per la prima volta. E guardati ora, sei diventata un pezzo grosso a Lemuria~"
  },
  AvgDialog_47174_Content_67 = {
    Text = "La salute del Vecchio Sommo Sacerdote è preoccupante. Potresti diventare la nostra Somma Sacerdotessa quando il nostro nuovo Signore ascenderà!"
  },
  AvgDialog_47174_Content_68 = {
    Text = "Chi serve là non fa differenza, Deborah. La maestra ci guiderà, e insieme consacreremo ogni cosa al Re. Presto il Reame Divino giungerà."
  },
  AvgDialog_47174_Content_69 = {
    Text = "La data dell'incoronazione del nostro nuovo Signore si avvicina. Molte questioni attendono la nostra attenzione. Mi sto dirigendo verso la sala di preghiera ora…"
  },
  AvgDialog_47174_Content_7 = {
    Text = "Sì! Solo tre anni fa era un'apprendista sacerdote. Eppure le è bastato meno di un anno per diventare la più giovane Somma Sacerdotessa Ascendente di Lemuria..."
  },
  AvgDialog_47174_Content_70 = {Text = "Miryam..."},
  AvgDialog_47174_Content_71 = {
    Text = "Indica gli abiti di Miryam. Miryam abbassa lo sguardo e nota di essere coperta di sangue."
  },
  AvgDialog_47174_Content_72 = {
    Text = "Ah, scusa... Ho dimenticato di aver appena terminato il rito."
  },
  AvgDialog_47174_Content_73 = {
    Text = "Miryam, stai bene?"
  },
  AvgDialog_47174_Content_74 = {
    Text = "Io? Sto bene... Perché lo chiedi?"
  },
  AvgDialog_47174_Content_75 = {
    Text = "Non lo so nemmeno io. Forse è solo il mio intuito, che tu sia cambiata molto da quando... è successo..."
  },
  AvgDialog_47174_Content_76 = {
    Text = "Non sono cambiata. Sono cresciuta. Le persone devono crescere, prima o poi."
  },
  AvgDialog_47174_Content_77 = {
    Text = "Ricordi il nostro desiderio, Deborah? Mi dicesti che avremmo servito insieme come Sue sacerdotesse e trasformato Lemuria nel Reame Divino."
  },
  AvgDialog_47174_Content_78 = {
    Text = "Certo. A quei tempi, eri solo un'apprendista che non riusciva nemmeno a intonare bene le preghiere~"
  },
  AvgDialog_47174_Content_79 = {
    Text = "Vedi, ho mantenuto le nostre promesse. Dovresti essere felice per me, no?"
  },
  AvgDialog_47174_Content_8 = {
    Text = "La salute del Vecchio Sommo Sacerdote si sta deteriorando, e la maggior parte dei compiti è stata affidata a lei. Forse presto diverrà la più giovane Somma Sacerdotessa di Lemuria."
  },
  AvgDialog_47174_Content_80 = {
    Text = "Sono sinceramente felice per te ogni giorno! È solo che... a volte, quando ti guardo, sembri così stanca. Sono un po' preoccupata..."
  },
  AvgDialog_47174_Content_81 = {
    Text = "Non preoccuparti, Deborah. Sto bene. Non mi sono mai sentita così bene prima d'ora."
  },
  AvgDialog_47174_Content_82 = {
    Text = "Dà un colpetto sulla spalla di Deborah, sorridendo, poi si dirige verso i suoi alloggi."
  },
  AvgDialog_47174_Content_83 = {
    Text = "La cerimonia dell'incoronazione richiede un'ampia preparazione. Un periodo intenso ci attende."
  },
  AvgDialog_47174_Content_84 = {
    Text = "Lungo il cammino, intravede la camera da letto del nuovo Signore, nella quale non ha diritto di entrare."
  },
  AvgDialog_47174_Content_85 = {
    Text = "Tutti i Lemuriani hanno udito qualche leggenda sul nuovo Signore."
  },
  AvgDialog_47174_Content_86 = {
    Text = "Con l'ascesa del nuovo Signore al Suo trono, l'avvento del Reame Divino è più vicino. Immersa nella speranza, porge distrattamente il fazzoletto di seta alla guardia dopo aver asciugato il sangue."
  },
  AvgDialog_47174_Content_9 = {
    Text = "Ha solo vent'anni, che cosa sorprendente..."
  },
  AvgDialog_47175_Content_1 = {Text = "Nuovo Re"},
  AvgDialog_47175_Content_10 = {Text = "..."},
  AvgDialog_47175_Content_11 = {
    Text = "Fuori dal Tempio di Lemuria."
  },
  AvgDialog_47175_Content_12 = {
    Text = "Il nuovo Re! Il nostro Signore!"
  },
  AvgDialog_47175_Content_13 = {
    Text = "Lode al nostro Signore! Lode al Reame Divino!"
  },
  AvgDialog_47175_Content_14 = {
    Text = "Il grande Tempio di Lemuria si erge maestoso, simile a una montagna sull'immensa costa."
  },
  AvgDialog_47175_Content_15 = {
    Text = "I seguaci si accalcano, affollandosi nella piazza antistante il Tempio, con lo sguardo rivolto al grande santuario che risplende di una luce cupa."
  },
  AvgDialog_47175_Content_16 = {
    Text = "La gente si alza in punta di piedi, guardando oltre le congregazioni clamorose e i gruppi di guardie, sforzandosi di scorgere il nuovo re all'interno del santuario."
  },
  AvgDialog_47175_Content_17 = {
    Text = "Dietro il santuario, le massicce porte d'ardesia del tempio sono spalancate — uno spettacolo raro per i fedeli. Un vento che porta il profondo, gelido sentore dell'abisso soffia dall'interno, facendo ondeggiare i veli traslucidi."
  },
  AvgDialog_47175_Content_18 = {
    Text = "Miryam si erge dinanzi alle file dei sacerdoti fuori dal santuario, le mani strette l'una all'altra, lo sguardo fisso sul retro del velo."
  },
  AvgDialog_47175_Content_19 = {
    Text = "Una figura vaga è adagiata contro il trono dietro il velo, apparentemente addormentata. La sagoma inconfondibile della corona del Re scuote Miryam, il suo respiro si fa corto e affannoso."
  },
  AvgDialog_47175_Content_2 = {
    Text = "Thud... Thud..."
  },
  AvgDialog_47175_Content_20 = {Text = "Boom—"},
  AvgDialog_47175_Content_21 = {Text = "Ah!—"},
  AvgDialog_47175_Content_22 = {
    Text = "Il tuono improvviso fece ammutolire i Seguaci. La paura della calamità scorse nelle loro vene, e alzarono lo sguardo in preda al panico."
  },
  AvgDialog_47175_Content_23 = {
    Text = "Il cielo, un tempo velato dalle nuvole, si fece sempre più cupo. I lampi guizzavano, il tuono ruggiva, e l'oceano si sollevava in onde che simboleggiavano calamità e morte."
  },
  AvgDialog_47175_Content_24 = {
    Text = "Una calamità... È una calamità! La calamità si avvicina!"
  },
  AvgDialog_47175_Content_25 = {
    Text = "E se colpisse il tempio... Come potremmo..."
  },
  AvgDialog_47175_Content_26 = {
    Text = "Come può accadere proprio ora... nel Giorno dell'Incoronazione..."
  },
  AvgDialog_47175_Content_27 = {
    Text = "Potrebbe essere... il nostro nuovo Signore..."
  },
  AvgDialog_47175_Content_28 = {
    Text = "Segni minacciosi fanno sì che l'ansia si propaghi rapidamente tra i credenti attorno al tempio. Discussioni, congetture, persino lamentele iniziano a crescere nella folla."
  },
  AvgDialog_47175_Content_29 = {
    Text = "Dietro il Velo, un lieve sospiro si diffonde. Una piccola figura si alza dal trono."
  },
  AvgDialog_47175_Content_3 = {
    Text = "Una grande campana rintocca nel tempio di Lemuria. Il suo suono grave e sonoro echeggia per tutta l'isola come un decreto divino."
  },
  AvgDialog_47175_Content_30 = {
    Text = "Nessuna calamità giungerà."
  },
  AvgDialog_47175_Content_31 = {
    Text = "Nel profondo del nostro sogno, ho udito la rivelazione divina:"
  },
  AvgDialog_47175_Content_32 = {
    Text = "Oggi, Lemuria accoglie il suo nuovo re."
  },
  AvgDialog_47175_Content_33 = {
    Text = "Oggi, ogni calamità si piega alla mia autorità."
  },
  AvgDialog_47175_Content_34 = {
    Text = "Quella voce giovanile era calma, eppure risuonava nitida nelle orecchie di Tutti come una campana."
  },
  AvgDialog_47175_Content_35 = {
    Text = "Quello è... il Nuovo Re? È la voce del Nuovo Re!"
  },
  AvgDialog_47175_Content_36 = {
    Text = "Guardate! Guardate il cielo!"
  },
  AvgDialog_47175_Content_37 = {
    Text = "Quasi non appena Tulu ebbe finito di parlare, le nuvole nel cielo cominciarono a dissiparsi a velocità visibile."
  },
  AvgDialog_47175_Content_38 = {
    Text = "I ruggiti dell'oceano cominciarono a placarsi, e la luce intensa del sole si riversò dall'alto, illuminando i volti di tutti i credenti."
  },
  AvgDialog_47175_Content_39 = {
    Text = "Miracolo... Questo è un Miracolo!"
  },
  AvgDialog_47175_Content_4 = {
    Text = "Il suono rotola verso la costa, riecheggia nelle valli, risveglia le genti di città e villaggi."
  },
  AvgDialog_47175_Content_40 = {
    Text = "Sul sipario dietro l'altare, la luce del sole proietta una silhouette nitida."
  },
  AvgDialog_47175_Content_41 = {
    Text = "Un corpo giovane giunge al bordo del sipario e solleva delicatamente un braccio."
  },
  AvgDialog_47175_Content_42 = {Text = "Boom..."},
  AvgDialog_47175_Content_43 = {
    Text = "Seguendo i suoi movimenti, enormi tentacoli perforarono l'oceano, le pianure e la catena montuosa, apparendo dinanzi a tutti."
  },
  AvgDialog_47175_Content_44 = {
    Text = "Una luce faint emana dai tentacoli. La luce gradualmente si connette e si intreccia in un grandioso dipinto dinanzi a tutti i credenti."
  },
  AvgDialog_47175_Content_45 = {
    Text = "Questo... questo è..."
  },
  AvgDialog_47175_Content_46 = {
    Text = "Gli occhi di Miryam si spalancano mentre osserva il paesaggio che si trasforma davanti a lei."
  },
  AvgDialog_47175_Content_47 = {
    Text = "Il mondo nei suoi occhi muta. La Catena Montuosa non è più deforme, il mare non è più in tempesta. La luce del sole bagna l'isola serena, illuminando un paese paradisiaco."
  },
  AvgDialog_47175_Content_48 = {Text = "Sorella!"},
  AvgDialog_47175_Content_49 = {
    Text = "La voce di un bambino raggiunge le orecchie di Miryam. Lei alza di scatto la testa, scorgendo quella figura familiare davanti a sé."
  },
  AvgDialog_47175_Content_5 = {
    Text = "Il nuovo Signore di Lemuria... L'Incoronazione sta per avere luogo!!"
  },
  AvgDialog_47175_Content_50 = {
    Text = "Sa...Sarah? Come è possibile..."
  },
  AvgDialog_47175_Content_51 = {
    Text = "Sorella, è passato così tanto tempo. Come hai fatto a non cambiare per niente? Guardami, sono cresciuto!"
  },
  AvgDialog_47175_Content_52 = {
    Text = "Miryam... stai bene al Tempio?"
  },
  AvgDialog_47175_Content_53 = {
    Text = "È passato così tanto tempo da quando ci siamo separati... La mamma sente la tua mancanza."
  },
  AvgDialog_47175_Content_54 = {
    Text = "Madre... mamma... tu..."
  },
  AvgDialog_47175_Content_55 = {
    Text = "Miryam resta attonita nel vedere quelle due figure avvicinarsi, mentre dei passi risuonano alle sue spalle. Si volta lentamente."
  },
  AvgDialog_47175_Content_56 = {
    Text = "Ah, la mia sacerdotessa è tornata!"
  },
  AvgDialog_47175_Content_57 = {Text = "Padre..."},
  AvgDialog_47175_Content_58 = {
    Text = "Le lacrime le offuscano la visuale. Le parole svaniscono nella sua gola roca."
  },
  AvgDialog_47175_Content_59 = {
    Text = "Una mano le sfiora delicatamente la testa, accarezzandole piano i capelli."
  },
  AvgDialog_47175_Content_6 = {
    Text = "Grida di giubilo si uniscono al coro delle campane, risuonando nelle orecchie di ogni persona di questo vasto regno."
  },
  AvgDialog_47175_Content_60 = {
    Text = "Non essere triste, Miryam. Ce l'hai fatta... Hai aiutato il Signore a inaugurare il Reame Divino!"
  },
  AvgDialog_47175_Content_61 = {
    Text = "Ora non abbiamo più nulla da temere. La nostra famiglia vivrà felice nel Reame Divino. Le nostre vite e la nostra felicità non avranno mai fine..."
  },
  AvgDialog_47175_Content_62 = {
    Text = "Io... ce l'ho fatta? Ce l'ho fatta..."
  },
  AvgDialog_47175_Content_63 = {
    Text = "Sua sorella corre al suo fianco e la abbraccia. Sua madre viene al suo fianco e la abbraccia. Suo padre le accarezza la testa al suo fianco e la abbraccia."
  },
  AvgDialog_47175_Content_64 = {
    Text = "Gli abbracci si sciolgono intorno a lei, lasciando fluire il ritmo dei battiti. Contatto di pelle. Borsa di scambio di calore. Un simbolo di ricongiungimento, che sfida la separazione. Un festino senza assenze."
  },
  AvgDialog_47175_Content_65 = {
    Text = "La sua nostalgia appagata, il suo desiderio soddisfatto, in quell'unico abbraccio. Per sempre, e in eterno."
  },
  AvgDialog_47175_Content_66 = {
    Text = "Le lacrime le sgorgano dagli occhi, rigandole le guance. Alza la testa."
  },
  AvgDialog_47175_Content_67 = {
    Text = "L'abbraccio svanisce, lo splendore illusorio si dissolve. Torna alla sua posizione nel tempio. Davanti a lei, innumerevoli credenti versano anch'essi lacrime."
  },
  AvgDialog_47175_Content_68 = {
    Text = "Lo splendore del Reame Divino, il desiderio più profondo celato nei loro cuori, si dispiega ora dinanzi ai credenti in una visuale vivida e radiosa."
  },
  AvgDialog_47175_Content_69 = {
    Text = "L'ho visto... L'ho visto nella Sua gloria!"
  },
  AvgDialog_47175_Content_7 = {
    Text = "Milioni di Lemuriani inondano le strade e le piazze, gridando e fremendo in fervente attesa."
  },
  AvgDialog_47175_Content_70 = {
    Text = "Questo è il Reame Divino... Questo è il Reame Divino, che si avvicina come Egli ha promesso!"
  },
  AvgDialog_47175_Content_71 = {
    Text = "Mio signore... L'ho visto!"
  },
  AvgDialog_47175_Content_72 = {
    Text = "Miryam mormora quelle parole senza sosta, inginocchiata dinanzi al Nuovo Re Dietro il Velo."
  },
  AvgDialog_47175_Content_73 = {
    Text = "Senza una sola parola di comando, gli innumerevoli credenti dietro di lei cadono in ginocchio. Un'ondata di profonda reverenza spazza la folla."
  },
  AvgDialog_47175_Content_74 = {
    Text = "Attraverso occhi velati di lacrime, la moltitudine rivolge lo sguardo al santuario con fervore, le aspettative crescenti verso la piccola silhouette dall'altro lato del velo."
  },
  AvgDialog_47175_Content_75 = {
    Text = "Contemplate lo splendore del Reame Divino. Omaggio alla maestà del nostro Signore."
  },
  AvgDialog_47175_Content_76 = {
    Text = "Sono vecchia, ormai. Per ordine del Signore, Miryam è qui per accogliere il Suo grazioso favore. Da oggi ascenderà come Somma Sacerdotessa e assisterà il nostro nuovo Signore."
  },
  AvgDialog_47175_Content_77 = {
    Text = "Mio Signore."
  },
  AvgDialog_47175_Content_78 = {
    Text = "Il precedente Vecchio Sommo Sacerdote si fa da parte e abbassa la voce."
  },
  AvgDialog_47175_Content_79 = {
    Text = "Lemuria ha contemplato la vostra maestà, mio Signore. Vi prego, fate risplendere la vostra gloria sul suo popolo. Vi prego, donate loro speranza."
  },
  AvgDialog_47175_Content_8 = {
    Text = "Forse il vecchio Signore ha abdicato. Forse è spirato. Nessuno lo sa, né gli importa."
  },
  AvgDialog_47175_Content_80 = {
    Text = "Si inchina dinanzi a Tulu, facendo un gesto d'invito."
  },
  AvgDialog_47175_Content_81 = {
    Text = "Il giovane Nuovo Re tace per un istante, poi avanza di un passo."
  },
  AvgDialog_47175_Content_82 = {
    Text = "Io sono l'inviato divino. Il Re di Lemuria."
  },
  AvgDialog_47175_Content_83 = {
    Text = "Il mio regno... donerà il Reame Divino a Lemuria."
  },
  AvgDialog_47175_Content_84 = {
    Text = "Dio... Che Dio protegga Lemuria!"
  },
  AvgDialog_47175_Content_85 = {
    Text = "Il nostro Signore! Sia lode al nostro Signore!"
  },
  AvgDialog_47175_Content_86 = {
    Text = "Sia lode al nostro Signore!!"
  },
  AvgDialog_47175_Content_87 = {
    Text = "Migliaia di credenti si inginocchiano al suolo. Migliaia di applausi echeggiano tra le montagne e risuonano con le onde. Migliaia di lodi fioriscono in ogni angolo del regno."
  },
  AvgDialog_47175_Content_88 = {
    Text = "Tulu si volta stancamente."
  },
  AvgDialog_47175_Content_89 = {
    Text = "Ho pronunciato le parole che Lemuria si aspettava."
  },
  AvgDialog_47175_Content_9 = {
    Text = "Esausti dalla lunga lotta contro le calamità, hanno imparato a non piangere il passato. Ogni cuore, invece, anela al regno del Nuovo Re — un futuro intriso della gloria del Reame Divino."
  },
  AvgDialog_47175_Content_90 = {
    Text = "Sono esausta. Fermate i vostri passi."
  },
  AvgDialog_47175_Content_91 = {
    Text = "Agita la mano, impedendo alle guardie e al Vecchio Sommo Sacerdote di seguirlo."
  },
  AvgDialog_47175_Content_92 = {
    Text = "Tra le grida fanatiche dei seguaci, il giovane re resta in silenzio, incamminandosi solo nelle profondità del tempio deserto."
  },
  AvgDialog_47176_Content_1 = {Text = "Profezia"},
  AvgDialog_47176_Content_10 = {
    Text = "La casa è quasi del tutto crollata; le macerie la imprigionano in una stretta fessura tra i detriti. Una pioggia torrenziale si riversa tra gli interstizi delle pietre, inzuppandola fino alle ossa."
  },
  AvgDialog_47176_Content_100 = {
    Text = "\"Ma — ma mio padre è un credente devoto. Il Re ha a cuore il suo popolo; non mi chiederebbe mai di...\""
  },
  AvgDialog_47176_Content_101 = {
    Text = "\"Tu non dovresti diventare sacerdotessa. Non saresti dovuta nascere a Lemuria. Dovresti essere esiliata, o giustiziata.\""
  },
  AvgDialog_47176_Content_102 = {
    Text = "\"Miryam, Sua Eminenza non intendeva dire questo...\""
  },
  AvgDialog_47176_Content_103 = {
    Text = "\"Vostra Grazia! Vi prego, perdonatela, Miryam semplicemente non è molto brava a esprimersi... siamo disposti a sacrificare tutto per il Re!\""
  },
  AvgDialog_47176_Content_104 = {
    Text = "\"Dio mi ha guidato fin qui. Dunque questo dev'essere il fato predetto dalle stelle... Fato. Hah.\""
  },
  AvgDialog_47176_Content_105 = {
    Text = "Il Vecchio Sommo Sacerdote non presta attenzione alle parole di Enos e Miryam. Senza rivolgere un altro sguardo, sospira profondamente e si ritira nelle profondità del tempio."
  },
  AvgDialog_47176_Content_106 = {
    Text = "Ben presto, una sacerdotessa accorre, i suoi passi riecheggiano nella sala silenziosa."
  },
  AvgDialog_47176_Content_107 = {
    Text = "Si ferma davanti a Miryam, le sorride e le porge un distintivo."
  },
  AvgDialog_47176_Content_108 = {
    Text = "\"Fra sette giorni, porta questo al tempio e unisciti all'addestramento.\""
  },
  AvgDialog_47176_Content_109 = {
    Text = "\"Congratulazioni, Miryam. Ora sei un'apprendista sacerdotessa di Lemuria.\""
  },
  AvgDialog_47176_Content_11 = {
    Text = "Sopra la sua testa, enormi frammenti di rovine pendono — sorretti soltanto da un unico pilastro percorso da crepe, che trema sotto l'assalto della pioggia."
  },
  AvgDialog_47176_Content_110 = {Text = "!!!"},
  AvgDialog_47176_Content_111 = {
    Text = "Sorella è stata scelta! Sorella è stata scelta!"
  },
  AvgDialog_47176_Content_112 = {
    Text = "Sarah saltella in giro tutta eccitata. Enos si volge verso la statua sopra l'altare, le mani giunte che tremano lievemente davanti a sé."
  },
  AvgDialog_47176_Content_113 = {
    Text = "Grazie, Vostra Grazia, grazie!"
  },
  AvgDialog_47176_Content_114 = {
    Text = "\"Il Signore ha udito la nostra voce... rendiamo la più profonda gratitudine al Signore... gratitudine...\""
  },
  AvgDialog_47176_Content_115 = {
    Text = "\"Paya, hai sentito? Nostra figlia è diventata un'apprendista sacerdotessa!\""
  },
  AvgDialog_47176_Content_116 = {
    Text = "\"Se solo potessi vedere tutto questo, saresti così felice, Paya...\""
  },
  AvgDialog_47176_Content_117 = {
    Text = "Miryam resta immobile, stordita, senza ancora comprendere appieno ciò che è accaduto."
  },
  AvgDialog_47176_Content_118 = {
    Text = "Gli applausi sfrenati di sua sorella, suo padre che si asciuga le lacrime di nascosto, il misto di congratulazioni sincere e invidiose dalla folla."
  },
  AvgDialog_47176_Content_119 = {
    Text = "Nel palmo della sua mano giace un distintivo scuro, inciso con tentacoli sinuosi e tempeste furiose. Riposa freddo e immobile, indifferente al clamore circostante, come un'altera profezia."
  },
  AvgDialog_47176_Content_12 = {
    Text = "\"O... O venerato Re...\""
  },
  AvgDialog_47176_Content_120 = {
    Text = "\"Tu adori il pesce — quando faremo ritorno, ti preparerò un intero festino con i tuoi piatti preferiti!\""
  },
  AvgDialog_47176_Content_121 = {
    Text = "\"Vado a dirlo a tutti; devo raccontare loro questa meravigliosa notizia!\""
  },
  AvgDialog_47176_Content_122 = {
    Text = "\"La mia Miryam diventerà una sacerdotessa di Lemuria!\""
  },
  AvgDialog_47176_Content_123 = {
    Text = "Sono ancora solo un'apprendista..."
  },
  AvgDialog_47176_Content_124 = {
    Text = "\"Sua Grazia, il Vecchio Sommo Sacerdote in persona, ti ha prestato particolare attenzione — questo significa che il talento della nostra Miryam è davvero straordinario! Sono certo che andrà tutto bene!"
  },
  AvgDialog_47176_Content_125 = {
    Text = "Miryam ancora non comprende cosa intendesse il Vecchio Sommo Sacerdote, né capisce perché le sia stata concessa questa qualifica. Guarda suo padre e sua sorella. È da molto tempo che non vede espressioni così gioiose sui loro volti."
  },
  AvgDialog_47176_Content_126 = {
    Text = "Miryam accarezza il distintivo, e un sorriso le affiora sul volto."
  },
  AvgDialog_47176_Content_127 = {
    Text = "Finalmente, anche lei ha portato il sorriso alla sua famiglia, proprio come suo padre. Allora, che quei sorrisi durino, pensa. Che questa gioia si possa sopportare."
  },
  AvgDialog_47176_Content_13 = {
    Text = "\"Vi prego... salvate il vostro fedele seguace...\""
  },
  AvgDialog_47176_Content_14 = {
    Text = "Con gli occhi fissi sulle macerie precarie sopra di lei, si rannicchia più a fondo nell'angolo. Le dita intrecciate strette, premute contro il petto, mentre rivolge una Preghiera al suo re."
  },
  AvgDialog_47176_Content_15 = {
    Text = "Tempeste. Tuoni. Terremoti. Tsunami."
  },
  AvgDialog_47176_Content_16 = {
    Text = "A Lemuria, il popolo dorme accanto alle calamità; per questo, la preghiera è la prima cosa che impara."
  },
  AvgDialog_47176_Content_17 = {
    Text = "\"Tu sei l'Inviato Divino, la fede del popolo di Lemuria... Ti consacro tutto ciò che ho...\""
  },
  AvgDialog_47176_Content_18 = {
    Text = "\"Vi imploro di aiutarmi... salvatemi...\""
  },
  AvgDialog_47176_Content_19 = {
    Text = "Suo padre le disse che il loro dio e il loro re avrebbero salvato il popolo di Lemuria. Lei non sa cosa sia un dio, né cosa sia un re. Eppure, gridò ancora e ancora."
  },
  AvgDialog_47176_Content_2 = {
    Text = "\"Nel Suo sogno sul trono, il Re udì la rivelazione divina:\""
  },
  AvgDialog_47176_Content_20 = {
    Text = "Dio non è apparso; Dio non è mai apparso dinanzi a lei. E tuttavia, al di fuori della preghiera, non vi è nulla che possa fare."
  },
  AvgDialog_47176_Content_21 = {
    Text = "Le crepe nel pilastro di pietra si allargano. Non riesce più a sostenere il peso schiacciante che grava dall'alto."
  },
  AvgDialog_47176_Content_22 = {
    Text = "\"O Signore... vi prego, salvatemi...\""
  },
  AvgDialog_47176_Content_23 = {
    Text = "Miryam ricorda quando il corpo di sua madre fu estratto da sotto le macerie — quel corpo sporco, spezzato."
  },
  AvgDialog_47176_Content_24 = {
    Text = "In quegli ultimi istanti di disperazione, anche lei aveva provato questo freddo? Questo terrore? Questo abbandono totale?"
  },
  AvgDialog_47176_Content_25 = {
    Text = "Le sue lacrime si sciolgono inermi nella pioggia. La sua voce si fa più debole, tremando insieme al suo corpo..."
  },
  AvgDialog_47176_Content_26 = {Text = "Boom—"},
  AvgDialog_47176_Content_27 = {Text = "\"Ah!!!...\""},
  AvgDialog_47176_Content_28 = {Text = "\"Miryam!\""},
  AvgDialog_47176_Content_29 = {
    Text = "La colonna di pietra si frantuma. Un istante prima che l'enorme lastra possa precipitare, una figura familiare accorre, stringendo Miryam nel suo abbraccio."
  },
  AvgDialog_47176_Content_3 = {
    Text = "\"Le tempeste di Lemuria si placheranno. L'abisso di Lemuria svanirà.\""
  },
  AvgDialog_47176_Content_30 = {
    Text = "\"P-Padre!...\""
  },
  AvgDialog_47176_Content_31 = {
    Text = "Miryam abbassa lentamente il braccio che aveva istintivamente alzato per proteggersi gli occhi."
  },
  AvgDialog_47176_Content_32 = {
    Text = "\"Waaahhhh...\""
  },
  AvgDialog_47176_Content_33 = {
    Text = "Si aggrappa a lui, stringendo forte quella figura familiare."
  },
  AvgDialog_47176_Content_34 = {
    Text = "\"Non avere paura, Miryam. Non avere paura. Sono qui.\""
  },
  AvgDialog_47176_Content_35 = {
    Text = "\"Agh... attenta, bambina... Non toccare la spalla...\""
  },
  AvgDialog_47176_Content_36 = {
    Text = "\"Stai sanguinando?!\""
  },
  AvgDialog_47176_Content_37 = {
    Text = "Pietre si schiantano, ghiaia schizza ovunque. Lui si erge tra lei e le macerie che crollano — la sua pelle segnata dalle intemperie e scurita dal sole è lacerata da innumerevoli nuove ferite causate da calcinacci e tegole."
  },
  AvgDialog_47176_Content_38 = {
    Text = "Le sue mani, già ruvide per una vita di fatiche, sono straziate e insanguinate per aver scavato freneticamente tra le macerie."
  },
  AvgDialog_47176_Content_39 = {
    Text = "La pioggia cade, scorrendo sul corpo dell'uomo; il suo sangue fresco tinge il terreno spezzato di un cremisi cupo."
  },
  AvgDialog_47176_Content_4 = {
    Text = "\"Il Re proteggerà il suo gentile popolo e porterà il Regno divino.\nAcque dolci bagneranno ogni palmo di terra, donando vita a ogni filo d'erba e a ogni albero.\""
  },
  AvgDialog_47176_Content_40 = {
    Text = "\"Padre... io... È tutta colpa mia se siete ferito...\""
  },
  AvgDialog_47176_Content_41 = {
    Text = "Una mano larga e callosa si posa delicatamente sulla sua testa, accarezzandole piano i capelli."
  },
  AvgDialog_47176_Content_42 = {
    Text = "\"Sciocca bambina, cosa dici? Finché tu sei salva, nessuna ferita può davvero farmi del male.\""
  },
  AvgDialog_47176_Content_43 = {
    Text = "\"Grazie al cielo, grazie al cielo... Sono arrivato in tempo, dopotutto...\""
  },
  AvgDialog_47176_Content_44 = {
    Text = "\"Grazie, mio Signore! Grazie per aver protetto la mia famiglia...\""
  },
  AvgDialog_47176_Content_45 = {
    Text = "\"Ma sei stato tu, Padre... sei tu che mi hai protetta...\""
  },
  AvgDialog_47176_Content_46 = {
    Text = "\"Noi di Lemuria sopravviviamo alle calamità solo per grazia del Re. Solo attraverso la devota adorazione del Re si può proteggere la propria famiglia. Sei ancora giovane; quando sarai più grande, capirai.\""
  },
  AvgDialog_47176_Content_47 = {
    Text = "Enos sorride, accarezzandole dolcemente la testa. Conduce Miryam a inchinarsi devotamente verso il tempio."
  },
  AvgDialog_47176_Content_48 = {
    Text = "\"Ora venite, recitate con me.\nPer i perduti, il Signore guiderà...\""
  },
  AvgDialog_47176_Content_49 = {Text = "..."},
  AvgDialog_47176_Content_5 = {Text = "Boom—"},
  AvgDialog_47176_Content_50 = {
    Text = "...A chi anela, il Signore concederà..."
  },
  AvgDialog_47176_Content_51 = {Text = "\"Miryam?\""},
  AvgDialog_47176_Content_52 = {
    Text = "...Ai devoti, il Signore elargirà la Sua grazia..."
  },
  AvgDialog_47176_Content_53 = {
    Text = "\"Miryam? Ti sei addormentata?\""
  },
  AvgDialog_47176_Content_54 = {
    Text = "\"Ah, Padre! Mi dispiace... Stavo solo ripensando a qualcosa del passato...\""
  },
  AvgDialog_47176_Content_55 = {
    Text = "\"Miryam, sei sicura di voler diventare sacerdotessa apprendista?\""
  },
  AvgDialog_47176_Content_56 = {
    Text = "\"Sì, Padre.\""
  },
  AvgDialog_47176_Content_57 = {
    Text = "\"Bene, bene. Sembravi distante, e raramente parli di queste cose — temevo che non ti interessassero...\""
  },
  AvgDialog_47176_Content_58 = {
    Text = "\"Quando l'altro giorno hai detto che desideravi aspirare al sacerdozio, ne sono stato felicissimo. Mia figlia è cresciuta...\""
  },
  AvgDialog_47176_Content_59 = {
    Text = "\"Dato che siamo qui, ascoltiamo con attenzione ciò che il sacerdote ha da dire. Il Re è la persona più vicina a Dio; egli vede ogni cosa. Chi manca di devozione non può ricevere la Sua grazia.\""
  },
  AvgDialog_47176_Content_6 = {Text = "\"Ah!...\""},
  AvgDialog_47176_Content_60 = {
    Text = "\"Mm... Capisco, Padre.\""
  },
  AvgDialog_47176_Content_61 = {
    Text = "<Italic:Ma non è mai stato il Re a vegliare su di me>, pensò Miryam, ingoiando quelle parole."
  },
  AvgDialog_47176_Content_62 = {
    Text = "\"Papà, la sorella verrà scelta?\""
  },
  AvgDialog_47176_Content_63 = {
    Text = "\"Certo! I sacerdoti della città hanno tutti detto che il talento spirituale di tua sorella è persino superiore al loro!\""
  },
  AvgDialog_47176_Content_64 = {
    Text = "\"Non solo può diventare sacerdotessa; in futuro potrebbe persino diventare il Vecchio Sommo Sacerdote!\""
  },
  AvgDialog_47176_Content_65 = {
    Text = "\"Un onore così grande... Se dovesse accadere, tua madre nell'altro mondo ne sarebbe sicuramente felice...\""
  },
  AvgDialog_47176_Content_66 = {
    Text = "\"Ah! La sacerdotessa sta arrivando!\""
  },
  AvgDialog_47176_Content_67 = {
    Text = "Tra le grida eccitate di Sarah, tutti volgono lo sguardo in avanti."
  },
  AvgDialog_47176_Content_68 = {
    Text = "La sacerdotessa, con un velo viola, avanza lentamente tra i fedeli recitando preghiere. Oltrepassa le giovani candidate in prima fila, poi si ferma davanti a Miryam e alla sua famiglia."
  },
  AvgDialog_47176_Content_69 = {
    Text = "\"O Signore, Ti prego, ascolta la mia devota supplica. Ti prego, accogli mia figlia, Miryam...\""
  },
  AvgDialog_47176_Content_7 = {
    Text = "Un tuono squarcia violento il cielo sopra l'isola. Sotto le macerie, una piccola figura trema."
  },
  AvgDialog_47176_Content_70 = {
    Text = "La preghiera sussurrata di suo padre, insieme alla solenne maestosità della sacerdotessa, impedirono a Miryam di parlare oltre."
  },
  AvgDialog_47176_Content_71 = {
    Text = "Abbassa il capo e attende. La sacerdotessa alza la mano e la posa sulla fronte di Miryam."
  },
  AvgDialog_47176_Content_72 = {
    Text = "\"Vostra Grazia, posso chiedervi se la mia bambina...\""
  },
  AvgDialog_47176_Content_73 = {
    Text = "Suo padre alza lo sguardo verso la sacerdotessa con umiltà. Lei non risponde; non mostra alcuna espressione. Ha visto troppe storie simili — il muggito delle bestie non suscita più in lei neppure il più tenue interesse."
  },
  AvgDialog_47176_Content_74 = {
    Text = "Quelle mani ben curate non si soffermano nemmeno un istante. La sacerdotessa si voltò e se ne andò con le sue ancelle, facendo ritorno all'altare."
  },
  AvgDialog_47176_Content_75 = {
    Text = "Non sono stata scelta, dunque..."
  },
  AvgDialog_47176_Content_76 = {
    Text = "\"Padre, mi dispiace... Non sono ancora riuscita ad aiutare la nostra famiglia in alcun modo...\""
  },
  AvgDialog_47176_Content_77 = {
    Text = "\"Ma cosa dici, sciocca bambina? Le stelle hanno già deciso il nostro fato. Non sono stato anch'io giudicato indegno?\""
  },
  AvgDialog_47176_Content_78 = {
    Text = "\"Finché potrai vivere una vita sana e felice, papà sarà contento. Sacerdotessa o meno, sarai sempre la mia bambina.\""
  },
  AvgDialog_47176_Content_79 = {
    Text = "Papà, e io?"
  },
  AvgDialog_47176_Content_8 = {
    Text = "Non lontano, l'oceano infuria con tale ferocia da quasi inghiottire il tuono stesso. Come una foglia avvizzita e inerme alla deriva sull'oceano sconfinato, la grande isola di Lemuria trema."
  },
  AvgDialog_47176_Content_80 = {
    Text = "\"Hahaha, sarete sempre le mie care figlie!\""
  },
  AvgDialog_47176_Content_81 = {
    Text = "Miryam scorge la delusione negli occhi di suo padre, eppure la sua mano ruvida e larga le riposa ancora sul capo, dolce come sempre."
  },
  AvgDialog_47176_Content_82 = {
    Text = "Fin dall'infanzia, quella mano appariva sempre — ogni volta che aveva paura, ogni volta che si sentiva persa, ogni volta che era triste; quella stessa mano la trovava sempre, accarezzandole la testa proprio così, cullandola fino a calmarla."
  },
  AvgDialog_47176_Content_83 = {
    Text = "Eppure, fin dall'infanzia, quanti fardelli ha sopportato il proprietario di quella mano? E lei, cosa aveva fatto per aiutarlo?"
  },
  AvgDialog_47176_Content_84 = {
    Text = "Miryam abbassa di nuovo il capo, cercando di nascondere i suoi occhi arrossati."
  },
  AvgDialog_47176_Content_85 = {
    Text = "\"Ehi, sorella, guarda! C'è un vecchio nonno che sta salendo sull'altare!\""
  },
  AvgDialog_47176_Content_86 = {
    Text = "Quell'abito... una veste purpurea!..."
  },
  AvgDialog_47176_Content_87 = {
    Text = "Un seguace si fa largo con impazienza tra la folla, mettendosi in punta di piedi accanto a Enos per vedere meglio."
  },
  AvgDialog_47176_Content_88 = {
    Text = "\"Quello è il Vecchio Sommo Sacerdote? Il Vecchio Sommo Sacerdote ha davvero lasciato il sancta sanctorum?! Nessuno aveva detto nulla a riguardo...\""
  },
  AvgDialog_47176_Content_89 = {
    Text = "Una figura anziana emerge dalla camera dietro l'altare. Il suo volto è segnato dalla maturità, ma i suoi passi restano fermi; i suoi abiti sono impeccabilmente curati, senza una sola piega."
  },
  AvgDialog_47176_Content_9 = {
    Text = "Sebbene le violente scosse fossero cessate, un persistente capogiro le annebbia ancora i sensi."
  },
  AvgDialog_47176_Content_90 = {
    Text = "Il Vecchio Sommo Sacerdote — l'unica persona in Lemuria a cui è concessa udienza presso il Re. Fatta eccezione per il Re stesso, che possiede l'abilità di comunicare con Dio, il Vecchio Sommo Sacerdote detiene il rango più elevato in tutta Lemuria."
  },
  AvgDialog_47176_Content_91 = {
    Text = "Lo sguardo severo del vecchio compie una spazzata attraverso l'intera sala. Pur senza pronunciare una sola parola, il tempio prima rumoroso si acquieta immediatamente sotto il suo sguardo."
  },
  AvgDialog_47176_Content_92 = {
    Text = "Presto, quello sguardo si volge verso Miryam. Seguendo la guida di una sacerdotessa, il vecchio le si avvicina e posa la sua mano rugosa sulla fronte di lei."
  },
  AvgDialog_47176_Content_93 = {
    Text = "I sacerdoti prima arroganti ora stanno chinati dinanzi al vecchio. Ogni cosa nel tempio sembra immobilizzarsi alla sua presenza; lei si ritrova senza fiato, incapace di percepire persino lo scorrere del tempo."
  },
  AvgDialog_47176_Content_94 = {
    Text = "Uccideresti tuo padre per il Re?"
  },
  AvgDialog_47176_Content_95 = {
    Text = "Una voce gelida proviene dal Vecchio Sommo Sacerdote, frantumando l'istante congelato come un tuono."
  },
  AvgDialog_47176_Content_96 = {
    Text = "Miryam alza il capo smarrita, scorgendo il volto severo e imponente del Vecchio Sommo Sacerdote."
  },
  AvgDialog_47176_Content_97 = {
    Text = "C-... Cosa avete appena detto, Vostra Grazia...?"
  },
  AvgDialog_47176_Content_98 = {
    Text = "Dimmi: cos'è la fede?"
  },
  AvgDialog_47176_Content_99 = {
    Text = "La fede è... offrire tutto al Re..."
  },
  AvgDialog_47177_Content_1 = {
    Text = "Carne di Pesce"
  },
  AvgDialog_47177_Content_10 = {
    Text = "Sorella, il pesce è così buono. Perché non ti piace?"
  },
  AvgDialog_47177_Content_11 = {
    Text = "Forse è perché ne ho mangiato troppo da bambina. Forse non riesco proprio ad abituarmi a quell'odore di pesce. O forse..."
  },
  AvgDialog_47177_Content_12 = {
    Text = "Sarah, non ti ho mai raccontato come è morta la mamma, vero?"
  },
  AvgDialog_47177_Content_13 = {
    Text = "Sarah scuote la testa e si rannicchia in silenzio tra le braccia di Miryam, ascoltando."
  },
  AvgDialog_47177_Content_14 = {
    Text = "Eri appena nata, e la mamma era costretta a letto dalla malattia. Quando le rocce caddero dalla montagna, non riuscì a mettersi in salvo in tempo."
  },
  AvgDialog_47177_Content_15 = {
    Text = "Quel giorno, il vento era impetuoso. Pesci caddero dal cielo, ricoprendole tutto il corpo."
  },
  AvgDialog_47177_Content_16 = {
    Text = "I suoi occhi erano spalancati, sporgenti—proprio come quei pesci..."
  },
  AvgDialog_47177_Content_17 = {
    Text = "Miryam non prosegue, e Sarah non chiede altro. La sorella minore si stringe forte alla sorella maggiore e le accarezza dolcemente la schiena."
  },
  AvgDialog_47177_Content_18 = {
    Text = "Ma se lo detesti, perché non lo dici a papà?"
  },
  AvgDialog_47177_Content_19 = {
    Text = "Quando non mi piace qualcosa, lo dico e basta."
  },
  AvgDialog_47177_Content_2 = {
    Text = "Sfrigolìo—"
  },
  AvgDialog_47177_Content_20 = {
    Text = "Dopo la morte della mamma, papà ci ha cresciute da solo. Ha avuto una vita dura."
  },
  AvgDialog_47177_Content_21 = {
    Text = "E il pesce è il cibo più economico di Lemuria."
  },
  AvgDialog_47177_Content_22 = {
    Text = "Non sono capace di molto... Non riesco davvero ad aiutare la famiglia. Il minimo che posso fare è non essere un peso..."
  },
  AvgDialog_47177_Content_23 = {
    Text = "Sarah, devi ricordartelo—quando sarai grande, prenditi cura di papà, d'accordo?"
  },
  AvgDialog_47177_Content_24 = {
    Text = "D'accordo! Ma sorella, hai detto che volevi diventare sacerdotessa. È come quando dici che ti piace mangiare il pesce?"
  },
  AvgDialog_47177_Content_25 = {
    Text = "A tavola! Mie piccole principesse, l'ultimo piatto è servito!"
  },
  AvgDialog_47177_Content_26 = {
    Text = "La voce del padre giunge dalla cucina, interrompendo la domanda di Sarah. Miryam sorride e cambia argomento."
  },
  AvgDialog_47177_Content_27 = {
    Text = "Sarah, non devi dire a nessun altro quello che ti ho raccontato, d'accordo?"
  },
  AvgDialog_47177_Content_28 = {
    Text = "Lo so! Nemmeno Sarah causerà problemi alla sorella o al papà~"
  },
  AvgDialog_47177_Content_29 = {
    Text = "Miryam sorride e accarezza la testa della sorellina, guidandola verso la cucina per accogliere il festino che il padre ha preparato."
  },
  AvgDialog_47177_Content_3 = {
    Text = "Il pesce fresco colpisce la padella; uno sfrigolio delizioso e un profumo si levano dalla loro modesta cucina."
  },
  AvgDialog_47177_Content_30 = {
    Text = "In breve, vari piatti di pesce ricoprono il loro piccolo tavolo."
  },
  AvgDialog_47177_Content_31 = {
    Text = "Mentre voi due eravate fuori a fare compere, l'ho detto alla gente in paese. Ho persino scritto lettere a quei parenti che vivono lontano—tra qualche giorno, lo sapranno anche loro."
  },
  AvgDialog_47177_Content_32 = {
    Text = "Tutti gli zii e le zie che ti hanno vista crescere sono felici per te. Hanno mandato così tanto cibo e bevande."
  },
  AvgDialog_47177_Content_33 = {
    Text = "Quanto alla sacerdotessa del nostro villaggio, è venuta a parlarmi dopo aver saputo che sei stata scelta dal Vecchio Sommo Sacerdote. Era così cortese!"
  },
  AvgDialog_47177_Content_34 = {
    Text = "Non è nulla di speciale... non c'è bisogno di dirlo a tanta gente..."
  },
  AvgDialog_47177_Content_35 = {
    Text = "È un grande affare, eccome! Se la sorella diventa sacerdotessa, guadagnerà un sacco di soldi, e potrà persino assumere qualcuno che mi aiuti a spazzare il pavimento..."
  },
  AvgDialog_47177_Content_36 = {
    Text = "Non dire queste cose, Sarah. Il sacerdozio è una vocazione sacra. Non lo si abbraccia per simili ragioni."
  },
  AvgDialog_47177_Content_37 = {
    Text = "E allora cosa fa un sacerdote?"
  },
  AvgDialog_47177_Content_38 = {
    Text = "Il dovere di un sacerdote... questo risale a molto, molto tempo fa. È una storia che ogni lemuriano dovrebbe conoscere."
  },
  AvgDialog_47177_Content_39 = {
    Text = "Enos prende Sarah tra le braccia, la posa sulle ginocchia e le accarezza dolcemente la testa."
  },
  AvgDialog_47177_Content_4 = {
    Text = "Questi sono i piatti preferiti delle sue figlie. Enos li prepara da oltre un decennio — riesce a dosare ogni spezia alla perfezione persino a occhi chiusi."
  },
  AvgDialog_47177_Content_40 = {
    Text = "Il nostro paese, Lemuria, vanta una storia gloriosa e una civiltà radiosa. In quei tempi, il Potere di Dio proteggeva questa terra, donandoci felicità e pace eterne."
  },
  AvgDialog_47177_Content_41 = {
    Text = "Non vi erano calamità, né malattie. Tutti avevano cibo e vino pregiato in abbondanza. Persino i Defunti, con l'aiuto di Dio, potevano ricongiungersi ai vivi."
  },
  AvgDialog_47177_Content_42 = {
    Text = "Ma a un certo punto, il nostro popolo non riuscì più a udire la Voce di Dio. Le calamità presero a Colpire con frequenza sempre maggiore..."
  },
  AvgDialog_47177_Content_43 = {
    Text = "Il nostro paese è circondato da mari sconfinati — nessuno è mai riuscito ad andarsene. Solo Dio può cambiare tutto questo."
  },
  AvgDialog_47177_Content_44 = {
    Text = "E il nostro Re è l'unico in grado di comunicare con Dio. Il Re ascolta gli oracoli di Dio e ci porterà ancora una volta le Sue benedizioni."
  },
  AvgDialog_47177_Content_45 = {
    Text = "Quando quel giorno verrà, tutte le calamità cesseranno, i Defunti torneranno in Vita, e vivremo su questa terra in pace eterna... Lemuria diverrà ancora una volta il perfetto Reame Divino!"
  },
  AvgDialog_47177_Content_46 = {
    Text = "Il suo pomo d'Adamo sussulta per l'eccitazione mentre distoglie il suo Sguardo colmo di Speranza dalla direzione del Tempio."
  },
  AvgDialog_47177_Content_47 = {
    Text = "Tuttavia, il suo Potere non è illimitato. Necessita dell'aiuto del suo popolo. Perciò coloro che possiedono un Forte Potere spirituale vengono scelti come Sacerdoti, al fine di trasmettere la sua volontà e Assisterlo."
  },
  AvgDialog_47177_Content_48 = {
    Text = "I comuni mortali come me non hanno Talento per simili grandi imprese... Posso solo guardare impotente mentre tua Madre..."
  },
  AvgDialog_47177_Content_49 = {
    Text = "Lascia perdere, lascia perdere. Oggi è un bel giorno; festeggiamo e non parliamo di quello."
  },
  AvgDialog_47177_Content_5 = {Text = "Huhhh—"},
  AvgDialog_47177_Content_50 = {
    Text = "Si asciuga l'umidità dagli angoli degli occhi. Poi, la sua Espressione si scioglie in un sorriso volutamente caloroso mentre accarezza entrambe le figlie sulla testa."
  },
  AvgDialog_47177_Content_51 = {
    Text = "Diventare sacerdotessa, servire il nostro Signore, portare la salvezza a Lemuria. Il più grande onore per tutti noi."
  },
  AvgDialog_47177_Content_52 = {
    Text = "Ringraziamo il Signore per aver concesso alla nostra umile famiglia una simile opportunità..."
  },
  AvgDialog_47177_Content_53 = {
    Text = "Enos alza il suo calice. Il liquido torbido vortica all'interno. Miryam avverte l'odore aspro e pungente dell'alcol scadente che taglia l'aria polverosa."
  },
  AvgDialog_47177_Content_54 = {
    Text = "È la bevanda prediletta dai poveri di Lemuria. Economica e Forte. Un breve sollievo a basso costo."
  },
  AvgDialog_47177_Content_55 = {
    Text = "Le impurità nell'alcol provocano forti mal di testa il giorno seguente. Ma i postumi e gli Spasmi di Pain sono doni per gli indigenti, quasi una sorta di Benedizione."
  },
  AvgDialog_47177_Content_56 = {
    Text = "Lo beve tutto d'un fiato."
  },
  AvgDialog_47177_Content_57 = {
    Text = "Sarah, tuo padre è un incapace, ma tua sorella è l'orgoglio di tutta la nostra famiglia!"
  },
  AvgDialog_47177_Content_58 = {
    Text = "Ecco, Miryam, questo è il tuo filetto di pesce fritto preferito. Il vecchio Ona l'ha pescato proprio oggi! Dopo avergli dato la tua bella notizia, gli ho chiesto di metterne da parte un po' per noi."
  },
  AvgDialog_47177_Content_59 = {
    Text = "Papà non vuole metterti troppo stress addosso. Segui il tuo cuore. So che ce la farai!"
  },
  AvgDialog_47177_Content_6 = {
    Text = "Sorella, ti fa male lo stomaco di nuovo? Ti viene sempre la nausea con l'odore del pesce..."
  },
  AvgDialog_47177_Content_60 = {
    Text = "Papà spera solo che tu possa prenderti cura di te stessa in futuro. Se qualcosa ti turba, scrivimi."
  },
  AvgDialog_47177_Content_61 = {
    Text = "Domani lascerai casa. Chissà quando potrai assaggiare di nuovo il pesce di papà..."
  },
  AvgDialog_47177_Content_62 = {
    Text = "Un piatto colmo di pesce viene posato davanti a Miryam. I filetti sono avvolti in una crosta croccante e dorata. Un aroma ricco e caldo riempie l'aria."
  },
  AvgDialog_47177_Content_63 = {
    Text = "Sua sorella sorride. Anche suo padre sorride, sebbene le lacrime gli tornino a velare gli occhi. Nella vista di Miryam offuscata dal vapore che si leva, la sagoma di sua Madre sembra seduta lì accanto anche lei, con un sorriso sommesso."
  },
  AvgDialog_47177_Content_64 = {
    Text = "I suoi vestiti sono laceri, il suo corpo un ammasso devastato. I Suoi Occhi sono spalancati, con un'inquietante somiglianza con gli occhi del pesce nel suo piatto."
  },
  AvgDialog_47177_Content_65 = {
    Text = "Diventerò una sacerdotessa... Non ti deluderò, padre."
  },
  AvgDialog_47177_Content_66 = {
    Text = "Miryam taglia un pesce, ne prende un Morso. Il sapore le esplode in bocca, forzandole un sorriso sulle labbra. In parte risposta, in parte partecipazione."
  },
  AvgDialog_47177_Content_7 = {
    Text = "Fuori dalla cucina, la sorella minore dà dei colpetti sulla schiena di Miryam scuotendo la testa e sospirando."
  },
  AvgDialog_47177_Content_8 = {
    Text = "Miryam non può fare a meno di sorridere vedendo quell'espressione da nonnina sul suo visetto di dieci anni."
  },
  AvgDialog_47177_Content_9 = {
    Text = "Sto bene, Sarah."
  },
  AvgDialog_47178_Content_1 = {
    Text = "Preghiera Abissale"
  },
  AvgDialog_47178_Content_10 = {Text = "Swish—"},
  AvgDialog_47178_Content_100 = {
    Text = "Ma né i devoti nel santuario né quelle imponenti porte di ardesia sfuggono al suo sguardo. Sembra osservare tutta Lemuria, scrutarne il popolo, contemplarne la civiltà."
  },
  AvgDialog_47178_Content_101 = {
    Text = "La remota emozione incisa in quegli occhi è al di là della sua comprensione. Forse è fede. Forse è compassione. Forse è solo stanchezza."
  },
  AvgDialog_47178_Content_11 = {
    Text = "<Shake:Mmmrrrr!!!...>"
  },
  AvgDialog_47178_Content_12 = {
    Text = "Una creatura fradicia balza fuori dall'acqua, radi capelli umani le pendono dal capo coprendo il suo volto da pesce."
  },
  AvgDialog_47178_Content_13 = {
    Text = "Le branchie sul suo collo si schiudono appena; le labbra sottili e viscide tremano mentre emette sillabe incomprensibili e torbide."
  },
  AvgDialog_47178_Content_14 = {
    Text = "I suoi arti un tempo umani, ora ricoperti di squame, si agitano freneticamente in superficie, riflettendo la luce del santuario con un luccichio oleoso e impuro."
  },
  AvgDialog_47178_Content_15 = {
    Text = "Slap slap slap slap..."
  },
  AvgDialog_47178_Content_16 = {
    Text = "Al suo seguito, innumerevoli creature dal volto di pesce e identiche fattezze emergono dalle vasche, i loro arti che battono l'acqua freneticamente mentre suoni strani sfuggono tra i loro denti da squalo."
  },
  AvgDialog_47178_Content_17 = {
    Text = "In un istante, affollano la vasca, la loro pelle scivolosa e luccicante che sfrega l'una contro l'altra. Quegli enormi occhi sporgenti fissano Miryam spalancati, senza battere ciglio e privi di qualsiasi emozione."
  },
  AvgDialog_47178_Content_18 = {Text = "Huhhh—"},
  AvgDialog_47178_Content_19 = {
    Text = "Miryam impiegò tutte le sue forze per trattenersi dal vomitare."
  },
  AvgDialog_47178_Content_2 = {
    Text = "Un ronzio basso, come un richiamo da tempi antichi, rompe il solenne Silenzio."
  },
  AvgDialog_47178_Content_20 = {
    Text = "Questi sono..."
  },
  AvgDialog_47178_Content_21 = {
    Text = "Oh, sono i grandi pionieri! È la prima volta che li vedo faccia a faccia. Ecco dunque che aspetto hanno!"
  },
  AvgDialog_47178_Content_22 = {
    Text = "L'apprendista sacerdotessa di nome Deborah si trova accanto a Miryam, battendole le braccia con entusiasmo — nonostante sia il loro Primo Incontro."
  },
  AvgDialog_47178_Content_23 = {
    Text = "La leggenda narra che il nostro Signore ricevette una Rivelazione Divina: prima che Lemuria si trasformi nel Reame Divino, egli userà il sangue sacro per trasformare il suo popolo, concedendogli l'abilità di resistere alle calamità."
  },
  AvgDialog_47178_Content_24 = {
    Text = "Questi pionieri hanno coraggiosamente compiuto questo passo avanti per il futuro di Lemuria."
  },
  AvgDialog_47178_Content_25 = {
    Text = "Una volta diventate sacerdotesse, saremo noi a compiere il rito della trasformazione. Sarò così eccitata che non riuscirò a dormire!"
  },
  AvgDialog_47178_Content_26 = {
    Text = "Deborah saluta quelle creature-pesce con gioia, accarezzando dolcemente i loro volti lucidi."
  },
  AvgDialog_47178_Content_27 = {
    Text = "Le altre apprendiste si inchinano a loro volta, porgendo i propri omaggi ai pionieri. Miryam resta immobile, a osservare."
  },
  AvgDialog_47178_Content_28 = {
    Text = "\"I grandi pionieri\"... mi chiedo se le loro famiglie penserebbero lo stesso, vedendoli così..."
  },
  AvgDialog_47178_Content_29 = {
    Text = "La sala di Preghiera è appena più avanti. Tutti, seguitemi."
  },
  AvgDialog_47178_Content_3 = {
    Text = "Due imponenti porte di ardesia dai fregi intricati si aprono scorrendo. Oscurità pura e informe attende all'interno, divorando la luce dall'esterno."
  },
  AvgDialog_47178_Content_30 = {Text = "..."},
  AvgDialog_47178_Content_31 = {
    Text = "Le porte di ardesia si chiudono in silenzio, soffocando le urla delle creature-pesce e il clamore all'esterno."
  },
  AvgDialog_47178_Content_32 = {
    Text = "Le apprendiste si inginocchiano ai loro seggi di preghiera, rivolgendo lo sguardo verso l'altare e la grande statua dietro di esso. Quest'ultima è un manufatto mozzafiato composto da un essere umano, un trono e tentacoli."
  },
  AvgDialog_47178_Content_33 = {
    Text = "Il suo volto è alquanto indistinguibile; il corpo umanoide, assiso tra un immenso trono e una miriade di tentacoli, crea un contrasto stridente."
  },
  AvgDialog_47178_Content_34 = {
    Text = "Questa è una statua che rappresenta il Signore."
  },
  AvgDialog_47178_Content_35 = {
    Text = "L'Anziano sacerdote emerge dal lato destro della sala della statua. Con un cenno della mano, impedisce alle apprendiste di alzarsi per salutarlo."
  },
  AvgDialog_47178_Content_36 = {
    Text = "Le preghiere giacciono dinanzi a voi. Leggetele. Cantilenate. E soprattutto, credete in esse."
  },
  AvgDialog_47178_Content_37 = {
    Text = "Vostra Grazia, se porteremo a termine questi compiti, saremo in grado di assistere il nostro Signore?"
  },
  AvgDialog_47178_Content_38 = {
    Text = "Il Vecchio Sommo Sacerdote le rivolge un breve sguardo."
  },
  AvgDialog_47178_Content_39 = {
    Text = "Il Signore te lo dirà. Ora, prega."
  },
  AvgDialog_47178_Content_4 = {
    Text = "Sembra rivolgere un invito a chiunque incroci il suo sguardo."
  },
  AvgDialog_47178_Content_40 = {
    Text = "Egli lascia la stanza, lasciando con gli apprendisti soltanto un sacerdote e alcune guardie."
  },
  AvgDialog_47178_Content_41 = {
    Text = "La luce nella sala di Preghiera si affievolisce. Un bagliore misterioso e tenue inizia a manifestarsi sulla superficie della Statua."
  },
  AvgDialog_47178_Content_42 = {
    Text = "Miryam raccoglie il foglio di preghiera davanti a sé."
  },
  AvgDialog_47178_Content_43 = {Text = "Ah..."},
  AvgDialog_47178_Content_44 = {
    Text = "I testi sulla carta sono scritti in una lingua diversa dal lemuriano comune. Gremiti di geroglifici complessi, possiedono più dimensioni dello spazio reale."
  },
  AvgDialog_47178_Content_45 = {
    Text = "Miryam si domanda se quei glifi misteriosi provengano da iscrizioni antiche o persino da un altro mondo. Eppure, il loro significato penetra nella sua mente automaticamente non appena li legge."
  },
  AvgDialog_47178_Content_46 = {
    Text = "Innumerevoli scritture divine inondano la mente di Miryam. Mentre i loro significati si dipanano con una vastità soverchiante, la sua fragile mente giunge sull'orlo del collasso."
  },
  AvgDialog_47178_Content_47 = {
    Text = "<Shake:La mia testa... mi fa male...>"
  },
  AvgDialog_47178_Content_48 = {
    Text = "Le persone intorno continuano a cadere a terra. Sopportando il dolore, Miryam recita le preghiere scritte sulla carta."
  },
  AvgDialog_47178_Content_49 = {
    Text = "\"Nel lontano abisso privo di sole, la grande anima ancestrale è nel dormiveglia...\""
  },
  AvgDialog_47178_Content_5 = {
    Text = "La parte esterna del Tempio è aperta ai fedeli comuni, ma solo coloro ritenuti degni di diventare Sacerdoti possono accedere qui."
  },
  AvgDialog_47178_Content_50 = {
    Text = "Miryam pronuncia queste parole in lemuriano ordinario, ma mentre le pronuncia, le parole prendono vita. Le lettere si distorcono come tentacoli, l'inchiostro nero danza nell'aria, finché non si tramuta in un'altra lingua."
  },
  AvgDialog_47178_Content_51 = {
    Text = "La sua voce si sovrappone e si intreccia in quell'unico istante. Le vocali si agganciano alle consonanti, le desinenze si fondono con gli inizi, proprio come quei simboli. Ciò che fuoriesce dalla sua gola forma una struttura complessa entro una dimensione superiore, come se riecheggiasse da uno spazio-tempo inimmaginabile."
  },
  AvgDialog_47178_Content_52 = {
    Text = "\"...La Sua volontà si intreccia come una ragnatela di stelle; nel vuoto eterno, Egli attende che tu entri nel Suo sogno...\""
  },
  AvgDialog_47178_Content_53 = {
    Text = "Miryam continua a intonare la cantilena con tutte le sue forze."
  },
  AvgDialog_47178_Content_54 = {
    Text = "Mentre le sue parole risuonano e si accumulano su se stesse senza sosta, la realtà che la circonda si offusca, si dissolve."
  },
  AvgDialog_47178_Content_55 = {
    Text = "Si ritrova sommersa in un mare profondo. Acque sinuose fluiscono in ogni direzione, simili a un'illusione."
  },
  AvgDialog_47178_Content_56 = {
    Text = "Risplende di un bagliore argenteo. Stelle luminose si disperdono ovunque, alla deriva, in un tremolio."
  },
  AvgDialog_47178_Content_57 = {
    Text = "Miryam sente di essersi in qualche modo unita alla costellazione. La sua luce di falena viene attratta verso un luogo preciso. Volge lo sguardo in quella direzione."
  },
  AvgDialog_47178_Content_58 = {
    Text = "Innumerevoli flussi di luce vorticano con schiuma luminosa, rincorrendosi verso una sagoma sfocata e lontana. Una sagoma composta da un corpo umano, un trono e innumerevoli tentacoli."
  },
  AvgDialog_47178_Content_59 = {
    Text = "Quello è... il Signore?"
  },
  AvgDialog_47178_Content_6 = {
    Text = "Benvenuto nel sancta sanctorum, Seguaci. Benvenuto nella Casa del nostro Signore."
  },
  AvgDialog_47178_Content_60 = {Text = "Pop—"},
  AvgDialog_47178_Content_61 = {
    Text = "La sagoma si desta di soprassalto, apparentemente disturbata da qualche voce. L'intero spazio illusorio si oscura per un istante quando apre gli occhi."
  },
  AvgDialog_47178_Content_62 = {
    Text = "Una vaga sagoma di un uomo anziano appare dietro di lui."
  },
  AvgDialog_47178_Content_63 = {
    Text = "Avete udito la sua voce, mio Signore."
  },
  AvgDialog_47178_Content_64 = {
    Text = "Il Signore di Lemuria regna ancora sul trono, e io non sono che un successore. Non dovreste rivolgervi a me in questo modo."
  },
  AvgDialog_47178_Content_65 = {
    Text = "Il Signore di Lemuria non è definito da chi siede sul trono. Noi veneriamo come nostro Signore colui che è più vicino al Dio."
  },
  AvgDialog_47178_Content_66 = {
    Text = "Non mi piace questo titolo."
  },
  AvgDialog_47178_Content_67 = {
    Text = "Il vecchio Signore di Lemuria ha udito una sola frase di profezia in tutta la sua vita. Quella frase gli assicura il posto sul trono, legittima la venerazione del suo popolo."
  },
  AvgDialog_47178_Content_68 = {
    Text = "Le profezie che avete ricevuto superano di gran lunga quelle concesse a tutti i re di Lemuria prima di voi. E voi... siete ancora una bambina."
  },
  AvgDialog_47178_Content_69 = {
    Text = "Voi siete la Speranza di Lemuria. I giorni del vecchio Signore sono contati, e ha già reso chiara la sua volontà. Presto il trono sarà vostro. Dovete abituarvi a questo titolo, mio Signore."
  },
  AvgDialog_47178_Content_7 = {
    Text = "Una folata di vento li accoglie dall'oscuro santuario, portando con sé il denso, salmastro sentore del mare profondo."
  },
  AvgDialog_47178_Content_70 = {
    Text = "Il ragazzino si appoggia stancamente allo schienale della sedia, rinunciando a discutere oltre con il vecchio."
  },
  AvgDialog_47178_Content_71 = {
    Text = "Connettersi con me e scorgere la mia presenza alla sua primissima preghiera... È lei colei predetta dalle stelle?"
  },
  AvgDialog_47178_Content_72 = {
    Text = "Sì, ho verificato. A meno che le stelle non si sbaglino, lei... è il futuro di Lemuria."
  },
  AvgDialog_47178_Content_73 = {
    Text = "Non lo pensi davvero."
  },
  AvgDialog_47178_Content_74 = {
    Text = "Talento sufficiente, ma Devozione insufficiente. Non può servirvi davvero, mio Signore."
  },
  AvgDialog_47178_Content_75 = {
    Text = "Non crede nelle preghiere, in voi, né nel futuro di Lemuria. Crede soltanto nella sua famiglia."
  },
  AvgDialog_47178_Content_76 = {
    Text = "Miryam vive nella realtà. Una persona simile non può portare il fato della nazione."
  },
  AvgDialog_47178_Content_77 = {
    Text = "Dimorare nella verità, non nel Delirio... questo è il credo di Questa Persona."
  },
  AvgDialog_47178_Content_78 = {
    Text = "Il destino di Lemuria... non dovrebbe gravare sulle spalle di nessuno."
  },
  AvgDialog_47178_Content_79 = {
    Text = "Un Nobile desiderio, mio Signore. Tuttavia, nati a Lemuria, ciascuno di noi ha i propri doveri da adempiere."
  },
  AvgDialog_47178_Content_8 = {
    Text = "Mentre le apprendiste seguono la sacerdotessa nel santuario interno, l'oscurità si ritrae in modo innaturale. La luce si riversa dal nulla, illuminando il sentiero lastricato apparentemente senza fine."
  },
  AvgDialog_47178_Content_80 = {
    Text = "Lei non ha Scelta. Io non ho Scelta. E voi, mio Signore... non avete Scelta neppure voi."
  },
  AvgDialog_47178_Content_81 = {
    Text = "...Noioso. Desidero riposare, ora."
  },
  AvgDialog_47178_Content_82 = {
    Text = "Agita una mano. L'Anziano si inchina dinanzi a lui e svanisce."
  },
  AvgDialog_47178_Content_83 = {
    Text = "Prima di tornare ai suoi sogni, il ragazzo contempla i milioni di bagliori e le anime che glieli consacrano. Un sospiro evanescente si dissolve nell'immenso vuoto, inudito, senza risposta."
  },
  AvgDialog_47178_Content_84 = {Text = "SQUEAK!"},
  AvgDialog_47178_Content_85 = {
    Text = "Segue una sensazione di caduta che mozza il fiato, poi un dolore acuto."
  },
  AvgDialog_47178_Content_86 = {
    Text = "Il dolore non dura a lungo. Miryam lascia quello spazio spirituale. Apre gli occhi, guardandosi attorno smarrita."
  },
  AvgDialog_47178_Content_87 = {
    Text = "Coloro che non sono riusciti a leggere o a intonare le Preghiere sono stati condotti fuori. Tra i rimasti, alcuni giacciono a terra doloranti, mentre altri, con gli occhi chiusi in Preghiera, portano sorrisi beati."
  },
  AvgDialog_47178_Content_88 = {
    Text = "Deborah siede accanto a lei, un dolce sorriso che le si propaga sul volto mentre apre lentamente gli occhi. Tuttavia, la sua Espressione si annuvola quando il suo sguardo incrocia quello di Miryam."
  },
  AvgDialog_47178_Content_89 = {
    Text = "Ehi, Miryam? Stai bene?"
  },
  AvgDialog_47178_Content_9 = {
    Text = "Su entrambi i lati del sentiero si trovano due enormi vasche. Miryam si avvicina a una di esse e sbircia all'interno."
  },
  AvgDialog_47178_Content_90 = {
    Text = "Mi fa male la testa... un momento fa andava tutto bene. Perché sono stata respinta? Qualcosa è andato storto...?"
  },
  AvgDialog_47178_Content_91 = {
    Text = "A quanto pare... hai fallito. Il Suo sogno ti ha esclusa."
  },
  AvgDialog_47178_Content_92 = {
    Text = "Ma perché... ho visto chiaramente una sagoma. Com'è possibile che all'improvviso..."
  },
  AvgDialog_47178_Content_93 = {
    Text = "Coloro che servono il Signore possono entrare nel Suo sogno attraverso le preghiere. Ma solo i sacerdoti più dotati possono scorgere la Sua sagoma. Questo dimostra che sei straordinario!"
  },
  AvgDialog_47178_Content_94 = {
    Text = "Non so cosa ti sia successo... ma è solo il tuo primo tentativo! Forse è solo questione di abituarsi. Andrà bene!"
  },
  AvgDialog_47178_Content_95 = {Text = "Grazie..."},
  AvgDialog_47178_Content_96 = {
    Text = "Non c'è bisogno di ringraziare~ Continua così! Questa Preghiera è essenziale per ogni Sacerdote o sacerdotessa. Come ponte tra le nostre anime mortali e il Signore, è indispensabile nelle altre Preghiere e nel Rito di conversione del popolo-pesce."
  },
  AvgDialog_47178_Content_97 = {
    Text = "In futuro, resteremo nel Tempio e serviremo come Sue sacerdotesse, e restaureremo Lemuria come Reame Divino!"
  },
  AvgDialog_47178_Content_98 = {
    Text = "La gentilezza dell'amica allevia la Debolezza di Miryam. Mentre si prepara ad andarsene, getta un altro sguardo alla Statua. La sagoma che ha visto nella Dimensione spirituale si sovrappone lentamente ai suoi contorni."
  },
  AvgDialog_47178_Content_99 = {
    Text = "Una figura vaga è adagiata sul Trono, il volto celato da Tentacoli di immenso Potere."
  },
  AvgDialog_47232_Content_1 = {
    Text = "Area riservata. Vietato l'accesso al personale non autorizzato. Si prega di esibire un documento d'identificazione."
  },
  AvgDialog_47232_Content_10 = {
    Text = "Che la Chiave d'Argento ci Guidi."
  },
  AvgDialog_47232_Content_2 = {
    Text = "Investigatore dell'Università di Mythag, William Delapore, Chiave d'Argento ID I-2083."
  },
  AvgDialog_47232_Content_3 = {
    Text = "%player%, K-0617."
  },
  AvgDialog_47232_Content_4 = {
    Text = "Ramona, I-3017."
  },
  AvgDialog_47232_Content_5 = {
    Text = "Ha lo sguardo di chi osserva qualcuno marciare verso la propria morte..."
  },
  AvgDialog_47232_Content_6 = {
    Text = "La Dimensione spirituale nella Zona D-Effetto regionale è caoticamente instabile. Spesso è necessario <Yellow:affrontare molteplici battaglie spirituali simultaneamente>, e il danno mentale supera di gran lunga quello fisico."
  },
  AvgDialog_47232_Content_7 = {
    Text = "Molti Investigatori sono impazziti nel tentativo di sopprimere la Zona D-Effetto Regionale. Bilancia le risorse tra i campi di battaglia per evitare l'esito peggiore."
  },
  AvgDialog_47232_Content_8 = {
    Text = "Nello specchietto retrovisore, la guardia di turno solleva il cappello in segno di saluto."
  },
  AvgDialog_47232_Content_9 = {
    Text = "Che la Chiave d'Argento Illumini il Cammino."
  },
  AvgDialog_47798_Content_1 = {
    Text = "Possiamo davvero intrufolarci qui? Questo è l'ufficio della Signora Sylvia..."
  },
  AvgDialog_47798_Content_10 = {
    Text = "Vorresti assaggiarne uno?"
  },
  AvgDialog_47798_Content_11 = {
    Text = "Murphy prende un pezzo di cioccolato al latte. Resta in silenzio, a capo chino. La stanza di consulenza sprofonda in un silenzio terrificante, facendoti correre un brivido lungo la schiena."
  },
  AvgDialog_47798_Content_12 = {
    Text = "Uhh... N-non ti piace il cioccolato? Sei allergica alle fave di cacao?"
  },
  AvgDialog_47798_Content_13 = {
    Text = "Andiamo al caffè della scuola e troviamo qualcos'altro! Lo chef non c'è, ma possiamo provare a preparare qualcosa noi stessi—hmm!"
  },
  AvgDialog_47798_Content_14 = {
    Text = "Prima che tu possa reagire, un pezzo di cioccolato al latte ti viene ficcato in bocca."
  },
  AvgDialog_47798_Content_15 = {
    Text = "Mentre ritrae la mano, i polpastrelli freddi delle sue dita ti sfiorano la lingua. Un intenso sapore di cacao esplode nella tua bocca, scivolando giù per la gola."
  },
  AvgDialog_47798_Content_16 = {
    Text = "Non ho mai detto che non voglio il cioccolato!"
  },
  AvgDialog_47798_Content_17 = {
    Text = "Dice Murphy, scegliendo dalla scatola il cioccolato più scuro e meno zuccherato."
  },
  AvgDialog_47798_Content_18 = {
    Text = "Bleah...! È così aspro! Aspro e amaro..."
  },
  AvgDialog_47798_Content_19 = {
    Text = "Vedendo il suo viso contorcersi, le porgi in fretta un altro pezzo di cioccolato al latte."
  },
  AvgDialog_47798_Content_2 = {
    Text = "Non preoccuparti. La signorina Sylvia ha detto che posso prendere i dolci dalla stanza di consulenza quando voglio."
  },
  AvgDialog_47798_Content_20 = {
    Text = "G-grazie..."
  },
  AvgDialog_47798_Content_21 = {
    Text = "La stanza di consulenza è dotata di un servizio da tè completo. Prepari una teiera di tè nero leggero e chiacchierate del più e del meno."
  },
  AvgDialog_47798_Content_22 = {
    Text = "Solo dopo che Murphy finisce l'ultimo pezzo di cioccolato al latte e si lecca le dita con gusto, lanci finalmente un'occhiata all'orologio a parete."
  },
  AvgDialog_47798_Content_23 = {
    Text = "Più tardi devo andare in missione. Visto che abbiamo mangiato dolci oltre la mezzanotte, ricordati di lavarti i denti prima di dormire."
  },
  AvgDialog_47798_Content_24 = {
    Text = "Una missione? A quest'ora?"
  },
  AvgDialog_47798_Content_25 = {
    Text = "È a causa della mutazione di Remouahe. L'intera università è in fermento. Andiamo. Prima ti riaccompagno in camera."
  },
  AvgDialog_47798_Content_26 = {
    Text = "Fai un passo avanti e, un istante dopo, inciampi inaspettatamente e cadi a terra."
  },
  AvgDialog_47798_Content_27 = {
    Text = "Ah?! S-scusa."
  },
  AvgDialog_47798_Content_28 = {
    Text = "Murphy ti aiuta in fretta a rialzarti. Abbassi lo sguardo e vedi un tentacolo rosso scuro che ti stringe saldamente la gamba."
  },
  AvgDialog_47798_Content_29 = {
    Text = "Non fa parte del suo abbigliamento, ma del suo vero \"corpo\"."
  },
  AvgDialog_47798_Content_3 = {
    Text = "Se fosse vero, non avremmo avuto bisogno di arrampicarci dalla finestra, non credi?"
  },
  AvgDialog_47798_Content_30 = {
    Text = "Devi... davvero andartene adesso?"
  },
  AvgDialog_47798_Content_31 = {
    Text = "A causa dell'influenza del Fiume sacro di Remouahe, sono comparse anomalie nei Domini di tutto il mondo."
  },
  AvgDialog_47798_Content_32 = {
    Text = "La squadra di Investigatori del secondo anno ha pattugliato tutta la notte. Ci siamo accordati per rilevare il pattugliamento del Dominio del Distretto Est alle 8 di mattina."
  },
  AvgDialog_47798_Content_33 = {
    Text = "Anomalia..."
  },
  AvgDialog_47798_Content_34 = {
    Text = "Io... mi sento... anch'io mi sento anormale..."
  },
  AvgDialog_47798_Content_35 = {
    Text = "Non ti senti bene? Hai la febbre?"
  },
  AvgDialog_47798_Content_36 = {
    Text = "Mentre parli, ti sfili i guanti e allunghi la mano per tastarle la fronte. Murphy arretra di colpo, schivando la tua mano — eppure i suoi tentacoli restano avvolti stretti attorno alla tua gamba."
  },
  AvgDialog_47798_Content_37 = {
    Text = "Mi ricordo che il tragitto in auto fino al Distretto Est dura solo mezz'ora. Non c'è bisogno di partire così presto."
  },
  AvgDialog_47798_Content_38 = {
    Text = "Come ricompensa... ti accompagnerò nel pattugliamento diurno..."
  },
  AvgDialog_47798_Content_39 = {
    Text = "I-insomma... resta con me fino all'alba."
  },
  AvgDialog_47798_Content_4 = {
    Text = "...Va bene. La signorina Sylvia non è a scuola comunque. Ha formato una squadra con altri investigatori e si è diretta a Londinium per arginare l'Incidente di Remouahe."
  },
  AvgDialog_47798_Content_5 = {Text = "Trovato."},
  AvgDialog_47798_Content_6 = {
    Text = "Dall'armadietto dei dolci nella stanza di consulenza, tiri fuori un'elegante confezione regalo."
  },
  AvgDialog_47798_Content_7 = {
    Text = "Questa marca di cioccolato..."
  },
  AvgDialog_47798_Content_8 = {
    Text = "L'involucro in foglia d'oro è liscio e ordinato, stretto da un nastro d'argento ricamato, a testimonianza dell'alto valore del cioccolato."
  },
  AvgDialog_47798_Content_9 = {
    Text = "L'aroma amaro del cacao si sprigiona impaziente nell'istante in cui il nastro viene sciolto."
  },
  AvgDialog_47803_Content_1 = {
    Text = "Eheh... Il piccolo Custode di Mythag ha onorato la mia umile dimora con la sua presenza. Il mio modesto studio è onorato dal vostro arrivo."
  },
  AvgDialog_47803_Content_10 = {
    Text = "Signorina Sanga!"
  },
  AvgDialog_47803_Content_11 = {
    Text = "Shh, shh... stai ferma e lasciami guardare."
  },
  AvgDialog_47803_Content_12 = {
    Text = "Smette di far roteare il coltello e invece ne preme la punta contro la tua guancia, sfregandola avanti e indietro sulla pelle."
  },
  AvgDialog_47803_Content_13 = {
    Text = "Lo sapevi? Ogni artista ha una musa unica."
  },
  AvgDialog_47803_Content_14 = {
    Text = "Catullo aveva la sua Lesbia, Petrarca la sua amata Laura..."
  },
  AvgDialog_47803_Content_15 = {
    Text = "Non c'è traccia di ferocia o violenza in quegli occhi insondabili; al contrario, sono colmi di un'emozione che ti è impossibile nominare."
  },
  AvgDialog_47803_Content_16 = {
    Text = "E ora, la mia personalissima <Blue:Camille> è proprio qui davanti a me. Non sei d'accordo, {Male=Signor,Female=Signorina} Custode?"
  },
  AvgDialog_47803_Content_2 = {
    Text = "Spingi da parte i materiali da scultura ammassati accanto alla porta, infilandoti a fatica nello studio di Sanga nell'Ala Ovest."
  },
  AvgDialog_47803_Content_3 = {
    Text = "La scultrice siede in cima alla sua base di corallo, il coltello da intaglio che danza tra le dita. La vista è snervante: la Lama è abbastanza affilata da recidere un dito al minimo errore."
  },
  AvgDialog_47803_Content_4 = {
    Text = "Non avevi detto agli investigatori di turno che volevi vedermi?"
  },
  AvgDialog_47803_Content_5 = {
    Text = "I Risvegliati godono di assoluta libertà nell'ambito del regolamento scolastico, ma Sanga è l'eccezione. A causa dei crimini commessi in passato all'ospizio, le è vietato agire da sola."
  },
  AvgDialog_47803_Content_6 = {
    Text = "Ah... esatto. Vedi, una totale mancanza di Ispirazione mi ha lasciato la testa come se fosse imbottita di corallo."
  },
  AvgDialog_47803_Content_7 = {
    Text = "Per favore, avvicinati un poco. Lasciami vedere ancora una volta i tuoi occhi... Lascia che un'anima infelice che non può lasciare questa stanza veda il mondo attraverso di essi."
  },
  AvgDialog_47803_Content_8 = {
    Text = "Il suo ragionamento è così grandioso e poetico che ti è impossibile rifiutare. Non hai altra scelta che muovere un passo verso di lei—"
  },
  AvgDialog_47803_Content_9 = {
    Text = "Sanga afferra all'improvviso il tuo mantello, trascinandoti il viso in basso finché non si trova a pochi centimetri dal suo."
  },
  AvgDialog_47807_Content_1 = {
    Text = "Una nebbia persistente avvolge i sensi nel Dormiveglia. L'Oscurità apparentemente calma è una facciata; in verità, onde nere già si sollevano e si infrangono contro i bastioni del tuo Spirito."
  },
  AvgDialog_47807_Content_10 = {
    Text = "Celeste spazza via la bussola, inchiodandoti contro il letto."
  },
  AvgDialog_47807_Content_11 = {
    Text = "Indica la luna piena sospesa alta fuori dalla finestra, poi punta il dito verso di te—"
  },
  AvgDialog_47807_Content_12 = {Text = "...Incubo."},
  AvgDialog_47807_Content_13 = {
    Text = "Finché sarò qui, gli incubi non ti tormenteranno."
  },
  AvgDialog_47807_Content_14 = {
    Text = "Il tuo respiro si sincronizza gradualmente con il ritmo dolce delle sue mani che lisciano le coperte; ogni respiro sembra un duetto con il vento. La tua coscienza ricomincia a vagare, sprofondando in un altro sogno."
  },
  AvgDialog_47807_Content_15 = {
    Text = "Un altro sogno gentile, tenero — uno che naviga verso un'alba tranquilla."
  },
  AvgDialog_47807_Content_2 = {
    Text = "Ancora oggi, l'influenza del Fiume sacro e dell'Albero Madre resta avvinghiata intorno a te."
  },
  AvgDialog_47807_Content_3 = {
    Text = "Memorie passate si condensano in bolle Fragili all'interno del Sogno. A ogni movimento inquieto, si frantumano come riflessi nell'acqua, svanendo al minimo tocco."
  },
  AvgDialog_47807_Content_4 = {
    Text = "Un'Oscurità caotica ti trascina verso i recessi più profondi della tua coscienza. Un istante prima di sentirti precipitare verso il totale Annientamento, una brezza leggera si insinua nel tuo Sogno."
  },
  AvgDialog_47807_Content_5 = {
    Text = "Il vento sembra possedere un Colore — impossibile da Ignorare, eppure mai ostentato. Come un Guardiano fragile, la sua sola presenza è la prova che non ti perderai nell'oscuro."
  },
  AvgDialog_47807_Content_6 = {
    Text = "Nell'istante in cui apri gli occhi, ti ritrovi a fissare direttamente Lo Sguardo del \"Custode dei Sogni.\""
  },
  AvgDialog_47807_Content_7 = {
    Text = "Celeste... cosa ci fai qui?"
  },
  AvgDialog_47807_Content_8 = {
    Text = "La silenziosa Risvegliata accenna un lieve cenno del capo e si siede sul bordo del letto, il materasso che cede leggermente sotto il suo peso."
  },
  AvgDialog_47807_Content_9 = {
    Text = "È andato storto qualcosa in una missione? Mi alzo sub—"
  },
  AvgDialog_47808_Content_1 = {
    Text = "Faros, cosa stai guardando?"
  },
  AvgDialog_47808_Content_10 = {
    Text = "La luce che emana da Faros tremola più volte."
  },
  AvgDialog_47808_Content_11 = {
    Text = "Mai. Quando fui abbastanza grande per unirmi a loro, Lemuria era già assediata dalla calamità."
  },
  AvgDialog_47808_Content_12 = {Text = "..."},
  AvgDialog_47808_Content_13 = {
    Text = "Custode, resteresti qui con me stanotte?"
  },
  AvgDialog_47808_Content_14 = {
    Text = "Consideralo come... ascoltare le storie di una folle. Solo una notte. Una notte è tutto ciò che chiedo..."
  },
  AvgDialog_47808_Content_2 = {
    Text = "Scorgi Faros da lontano; è fin troppo \"brillante\" per passare inosservata nella notte. Nel silenzio delle sabbie del deserto, la sua è l'unica luce che non appartiene alle stelle."
  },
  AvgDialog_47808_Content_3 = {Text = "Custode."},
  AvgDialog_47808_Content_4 = {
    Text = "Con il suo aiuto, scali la duna. Il vento notturno del deserto — freddo e disseccante — ti colpisce come il graffio di una lama sul volto."
  },
  AvgDialog_47808_Content_5 = {
    Text = "In quanto Risvegliatrice del Reame di Aequor, le vesti di Faros portano di solito una traccia di umidità. Ora, tuttavia, persino i suoi tentacoli sembrano avvizziti e spossati dalla secchezza."
  },
  AvgDialog_47808_Content_6 = {
    Text = "Sto osservando... questo fiume."
  },
  AvgDialog_47808_Content_7 = {
    Text = "Mi ricorda Lemuria. La mia terra natale era un tempo nutrita da un grande fiume proprio come questo."
  },
  AvgDialog_47808_Content_8 = {
    Text = "Prima che le catastrofi avessero inizio, i giovani si radunavano sulle rive del fiume ogni notte d'estate... in cerca di compagni per la vita, sperando di fondare nuove famiglie."
  },
  AvgDialog_47808_Content_9 = {
    Text = "Sembra fosse piuttosto vivace. E tu, Faros? Hai mai partecipato a quei raduni estivi?"
  },
  AvgDialog_47977_Content_1 = {Text = "..."},
  AvgDialog_47977_Content_10 = {
    Text = "Ora, torniamo all'argomento. Questa operazione mira a osservare l'attività della coscienza cerebrale della Signorina \"24\", fornendo dati di riferimento per i trattamenti futuri."
  },
  AvgDialog_47977_Content_11 = {
    Text = "Non andare dove non dovresti, a meno che tu non voglia restare intrappolato nella testa di qualcun altro per sempre."
  },
  AvgDialog_47977_Content_12 = {
    Text = "Non rallentare, e non addormentarti!"
  },
  AvgDialog_47977_Content_13 = {
    Text = "<Shake:Diversi miei compagni sono svaniti in questo modo e sono passati migliaia di anni e ancora non so se siano vivi o meno...>"
  },
  AvgDialog_47977_Content_14 = {
    Text = "...Lo terrò a mente."
  },
  AvgDialog_47977_Content_15 = {
    Text = "Non preoccuparti, monitoreremo attentamente le tue condizioni. L'operazione verrà interrotta immediatamente se qualcosa dovesse andare storto."
  },
  AvgDialog_47977_Content_16 = {
    Text = "Sei pronto, %player%?"
  },
  AvgDialog_47977_Content_17 = {
    Text = "Fissi le camere labirintiche che si aprono davanti a te. Si espandono e si contraggono in una pulsazione ritmica, le loro sezioni rigonfie si sollevano e si abbassano a ogni respiro, evocando la vastità di un mare senza fine."
  },
  AvgDialog_47977_Content_18 = {
    Text = "E tu sei un navigatore solitario in piedi sul ponte della nave."
  },
  AvgDialog_47977_Content_19 = {Text = "Pronti"},
  AvgDialog_47977_Content_2 = {
    Text = "Ti sei svegliato? Segui le istruzioni: procedi dritto per 100 micrometri, poi gira a destra, poi a sinistra, salta in alto ed entra nel terzo ventricolo..."
  },
  AvgDialog_47977_Content_20 = {
    Text = "Cominciamo, allora. La Signorina \"24\" e noi attendiamo con impazienza i tuoi risultati."
  },
  AvgDialog_47977_Content_21 = {
    Text = "Buon Viaggio, Custode."
  },
  AvgDialog_47977_Content_3 = {
    Text = "Aspetta, quale terzo ventricolo—<ShakeBig:UWAHH, cosa è successo alle mie mani?!>"
  },
  AvgDialog_47977_Content_4 = {
    Text = "Cerchi di strofinarti gli occhi, solo per scoprire che i tuoi arti si sono trasformati in morbide sinapsi, che fluttuano dolcemente in un tiepido mare cremisi di carne."
  },
  AvgDialog_47977_Content_5 = {
    Text = "Non avere paura. Winkle ha apportato alcune piccole iterazioni all'esperienza di <Yellow:Immersione Psichica>. La tua coscienza sta ora fluttuando nella mente di \"24\", e tutto ciò che percepirai verrà trasmesso al terminale remoto."
  },
  AvgDialog_47977_Content_6 = {
    Text = "Il mio corpo si è trasformato in un cono, e ho persino delle antenne sulla testa!"
  },
  AvgDialog_47977_Content_7 = {
    Text = "Giù le mani! Queste antenne sono fondamentali per percepire l'ambiente circostante. Sul mio pianeta natale, sono simbolo di rango: più lunghe sono le antenne, più elevata è la posizione."
  },
  AvgDialog_47977_Content_8 = {
    Text = "Capisco. Quindi aveva lunghe antenne, signorina Winkle?"
  },
  AvgDialog_47977_Content_9 = {
    Text = "Ehm... C-Certo che sì!"
  },
  AvgDialog_48091_Content_1 = {Text = "!"},
  AvgDialog_48091_Content_10 = {Text = "Certo."},
  AvgDialog_48091_Content_11 = {
    Text = "Dopo aver riposato per un po', noti che Lily continua a lanciare occhiate furtive al tuo petto, il volto pieno di parole che ha paura di pronunciare."
  },
  AvgDialog_48091_Content_12 = {
    Text = "Per qualche ragione, quella scintillante chiave d'argento sembra esercitare sulla bambina un'attrazione strana e irresistibile."
  },
  AvgDialog_48091_Content_13 = {
    Text = "<Gray:Dovrebbe andare bene finché siamo a scuola...>"
  },
  AvgDialog_48091_Content_14 = {
    Text = "Esiti un istante prima di slacciare infine la Chiave d'Argento e riporla nel suo piccolo, fragile palmo."
  },
  AvgDialog_48091_Content_15 = {
    Text = "Che freddo..."
  },
  AvgDialog_48091_Content_16 = {
    Text = "Hai troppo freddo?"
  },
  AvgDialog_48091_Content_17 = {
    Text = "No... è un fresco piacevole... si sta bene..."
  },
  AvgDialog_48091_Content_18 = {
    Text = "Tanto, tanto tempo fa, quando mi ammalavo, la mamma mi teneva in braccio e mi raccontava le storie della buonanotte..."
  },
  AvgDialog_48091_Content_19 = {
    Text = "Lascia che ti racconti."
  },
  AvgDialog_48091_Content_2 = {
    Text = "Lily si rannicchia contro il tuo petto, proprio come quella mattina in cui ti svegliasti per la prima volta nel piccolo negozio di Daffodil."
  },
  AvgDialog_48091_Content_20 = {
    Text = "C'era una volta, in una torre lontana lontana, una Principessa con i capelli lunghissimi, lunghissimi..."
  },
  AvgDialog_48091_Content_21 = {
    Text = "Le accarezzi dolcemente la schiena, osservandola mentre scivola gradualmente in un placido Dormiveglia."
  },
  AvgDialog_48091_Content_22 = {Text = "Madre..."},
  AvgDialog_48091_Content_23 = {
    Text = "Lily giace cullata tra le tue braccia, profondamente addormentata con un respiro lieve e regolare. Le tiri delicatamente addosso una coperta leggera, rimboccandola insieme ai suoi piccoli amici pustolosi."
  },
  AvgDialog_48091_Content_24 = {
    Text = "<Gray:Mi sta venendo un po' di sonno anche a me...>"
  },
  AvgDialog_48091_Content_25 = {
    Text = "Ma ora, proteggere la sua serena felicità viene prima di tutto."
  },
  AvgDialog_48091_Content_3 = {
    Text = "Ma a differenza di quel giorno, il suo corpicino è raggomitolato stretto, e il suo viso è arrossato di un rosso intenso e febbrile."
  },
  AvgDialog_48091_Content_4 = {
    Text = "Padrone... credo di avere la febbre..."
  },
  AvgDialog_48091_Content_5 = {
    Text = "Ti porto in infermeria."
  },
  AvgDialog_48091_Content_6 = {
    Text = "Lily scuote la testa ostinatamente. Accanto a lei, diverse pustole oscillano seguendo i suoi movimenti, come un grappolo di palloncini che si urtano tra loro nella mano di un mercante ambulante."
  },
  AvgDialog_48091_Content_7 = {
    Text = "No... niente punturine."
  },
  AvgDialog_48091_Content_8 = {
    Text = "Allora... vuoi sdraiarti e riposare?"
  },
  AvgDialog_48091_Content_9 = {
    Text = "Ti sposti di lato, ricavando un piccolo spazio per lei sul letto."
  },
  AvgDialog_48092_Content_1 = {
    Text = "Aspetta, Custode. Ho qualcosa di cruciale da discutere con te."
  },
  AvgDialog_48092_Content_10 = {
    Text = "Doll ti prende la mano e la porta direttamente alla sua vita."
  },
  AvgDialog_48092_Content_11 = {
    Text = "Insufficiente. Devo catalizzare l'intensità del desiderio per ottenere la localizzazione e il tracciamento in tempo reale del pensiero invasivo.\nIn altre parole, non fermarti finché non registro una sensazione."
  },
  AvgDialog_48092_Content_12 = {
    Text = "Questo... non è un po' inappropriato?"
  },
  AvgDialog_48092_Content_13 = {
    Text = "Non c'è nulla di più inappropriato che permettere a un pensiero aberrante di persistere nella mia rete neurale. Credo sia un'esperienza interessante e nuova anche per te."
  },
  AvgDialog_48092_Content_14 = {
    Text = "I Suoi Occhi sono fissi intensamente su di te, facendoti sentire come un coniglio indifeso messo all'angolo da un leopardo."
  },
  AvgDialog_48092_Content_15 = {
    Text = "È solo un compito, è solo un compito..."
  },
  AvgDialog_48092_Content_16 = {
    Text = "Convincendoti, premi le labbra sulla sua testa. Il tocco gelido dell'unità di contenimento cranica ti mozza il respiro."
  },
  AvgDialog_48092_Content_17 = {
    Text = "Fiamme tremolano nelle pupille di Doll, e puoi sentire il suo corpo tremare per l'eccitazione."
  },
  AvgDialog_48092_Content_18 = {
    Text = "Localizzazione dell'intrusione mentale completa."
  },
  AvgDialog_48092_Content_19 = {
    Text = "Ora avviamo la procedura di completamento."
  },
  AvgDialog_48092_Content_2 = {
    Text = "Qualcuno sta invadendo i miei pensieri."
  },
  AvgDialog_48092_Content_20 = {
    Text = "%player%. Non disimpegnarti finché il processo non è completo."
  },
  AvgDialog_48092_Content_3 = {
    Text = "Come hai scoperto di..."
  },
  AvgDialog_48092_Content_4 = {
    Text = "Noi, gli Alaemyces, abbiamo da tempo abbandonato i corpi fisici e i desideri riproduttivi. Pensieri così decadenti e primitivi che affiorano nella mia mente devono derivare da un'intrusione esterna."
  },
  AvgDialog_48092_Content_5 = {
    Text = "Cosa posso fare per te?"
  },
  AvgDialog_48092_Content_6 = {
    Text = "Vieni qui. Abbracciami."
  },
  AvgDialog_48092_Content_7 = {Text = "??"},
  AvgDialog_48092_Content_8 = {
    Text = "Pur provando disagio, segui le istruzioni e abbracci il corpo minuto di Doll. I suoi morbidi capelli arricciati ti sfiorano il naso, provocando un leggero, persistente prurito."
  },
  AvgDialog_48092_Content_9 = {
    Text = "Non riesci nemmeno a svolgere un compito così semplice? Avvicinati."
  },
  AvgDialog_48093_Content_1 = {Text = "Cus~to~de~"},
  AvgDialog_48093_Content_10 = {
    Text = "La candela nel suo basso ventre arde con vigore eccezionale, apparentemente pronta a infiammare il fuoco nei suoi Occhi, mentre la sua lucida frusta di cuoio fende l'aria con uno schiocco."
  },
  AvgDialog_48093_Content_11 = {
    Text = "Così va bene, vero, Custode? Siamo già così intimi, e percepisco tanto, tanto—tanto amore da te~"
  },
  AvgDialog_48093_Content_12 = {
    Text = "Mmph! Pan—dia! Ptuh, calmati!"
  },
  AvgDialog_48093_Content_13 = {
    Text = "Il tuo dibatterti quasi frenetico ti concede un barlume di opportunità. Sputi frettolosamente il bavaglio, chiudendo istintivamente gli Occhi, preparandoti a schivare la frustata immaginata..."
  },
  AvgDialog_48093_Content_14 = {
    Text = "Ma la frusta si ferma dolcemente sulla punta del tuo naso."
  },
  AvgDialog_48093_Content_15 = {
    Text = "Gli Occhi di Pandia perdono messa a fuoco, si disperdono nella Confusione. Si gratta il viso, irritata e contrariata."
  },
  AvgDialog_48093_Content_16 = {
    Text = "No, no, la sensazione che voglio non è questa~!"
  },
  AvgDialog_48093_Content_17 = {
    Text = "Devo frustare il viso del Custode, o forse schiacciare @3 del Custode con il piede? No, no, no, niente di tutto questo è g-i-u-s-t-o!"
  },
  AvgDialog_48093_Content_18 = {
    Text = "La rapitrice fallita è mortificata e furiosa. L'influenza del Fiume sacro la spinge ad agitare freneticamente la frusta tutt'intorno."
  },
  AvgDialog_48093_Content_19 = {
    Text = "Perché quando immagino di fare @2 e @2 al Custode, non provo assolutamente nulla di quel calore rovente e dolce~?"
  },
  AvgDialog_48093_Content_2 = {
    Text = "Mmmph! Mmmph!"
  },
  AvgDialog_48093_Content_20 = {
    Text = "Avendo fallito nella lotta contro le corde, il tuo cervello si spegne completamente, riversando automaticamente battute intorpidite e difensive."
  },
  AvgDialog_48093_Content_21 = {
    Text = "Se colpire me non ti sembra giusto, che ne dici se colpisco io te?"
  },
  AvgDialog_48093_Content_22 = {
    Text = "Prima che tu possa morderti la lingua per averlo detto, le Pupille di Pandia si dilatano improvvisamente."
  },
  AvgDialog_48093_Content_23 = {
    Text = "Esatto! Come ho fatto a non pensarci? Ciò che davvero~ davvero, davvero desidero...!"
  },
  AvgDialog_48093_Content_24 = {
    Text = "Il suo Corpo comincia a tremare leggermente per l'estrema eccitazione."
  },
  AvgDialog_48093_Content_25 = {
    Text = "Ogni luce nella Stanza si spegne, tranne la candela che arde ancora ferocemente dentro di lei."
  },
  AvgDialog_48093_Content_26 = {
    Text = "Alla luce della Luna, Pandia rovescia la frusta, stringe il manico tra i denti, e la sua Voce si fa densa e impastata, come glassa che implora di essere assaggiata... o un'Oscurità greve, umida e agghiacciante."
  },
  AvgDialog_48093_Content_27 = {
    Text = "Con un tonfo sordo, le corde che ti legano le braccia cadono."
  },
  AvgDialog_48093_Content_28 = {
    Text = "Puniscimi. Frustami. Maltrattami..."
  },
  AvgDialog_48093_Content_29 = {
    Text = "Così come lo dono agli altri, concedi quel dolce pain anche a me~!"
  },
  AvgDialog_48093_Content_3 = {
    Text = "Sono così sola~ Così vuota~ La piccola fiamma dentro di me continua a bruciare~"
  },
  AvgDialog_48093_Content_4 = {
    Text = "Mi sta praticamente consumando del tutto~! Perché non mi rispondi~"
  },
  AvgDialog_48093_Content_5 = {
    Text = "<Italic:(Non sarà mica perché mi hai imbavagliato?!)>"
  },
  AvgDialog_48093_Content_6 = {
    Text = "Nessuna lezione nel Curriculum di Mythag ha mai insegnato come gestire un Risvegliatore che \"brucia di passione\" letteralmente in questo modo."
  },
  AvgDialog_48093_Content_7 = {
    Text = "Ed è praticamente seduta del tutto sul tuo petto, schiacciandoti con una coscia che sembra liscia come Olio di Cera."
  },
  AvgDialog_48093_Content_8 = {
    Text = "<Italic:(Pandia, se non ti alzi, soffocherò sotto il tuo peso prima ancora di soffocare sotto la tua passione.)>"
  },
  AvgDialog_48093_Content_9 = {
    Text = "Cerchi di trasmettere questo messaggio complesso con gli Occhi, ma chiaramente la Bambina è interamente concentrata su qualsiasi cosa tranne che migliorare le tue probabilità di sopravvivenza."
  },
  AvgDialog_48094_Content_1 = {
    Text = "Aigis? Dicono che ti sei chiusa nella tua Stanza da tre giorni."
  },
  AvgDialog_48094_Content_10 = {
    Text = "Va tutto bene, va tutto bene. Non è colpa tua."
  },
  AvgDialog_48094_Content_11 = {
    Text = "La conforti mentre ti avvicini, la mente che vaglia freneticamente possibili soluzioni—"
  },
  AvgDialog_48094_Content_12 = {
    Text = "Non avvicinarti! Ti farò del male..."
  },
  AvgDialog_48094_Content_13 = {
    Text = "Va tutto bene. Dopotutto, sono il Custode. All'Ospizio dei Poveri non mi hai trasformato in Pietra. Ricordi?"
  },
  AvgDialog_48094_Content_14 = {
    Text = "Per permettere alle emozioni instabili dei Risvegliati di trovare \"sfogo,\" devi guidare Aigis ad aprire i suoi occhi—"
  },
  AvgDialog_48094_Content_15 = {
    Text = "La giovane Bambina tentenna, le palpebre che si schiudono appena di una fessura — ma nell'istante successivo, uno sciroppo denso, vischioso, color ambra-Brown inizia a trasudare dalla tua pelle esposta."
  },
  AvgDialog_48094_Content_16 = {
    Text = "Waaah!! Custode!!"
  },
  AvgDialog_48094_Content_17 = {
    Text = "Sniff... È tutta colpa mia... Non avrei dovuto aprire gli occhi..."
  },
  AvgDialog_48094_Content_18 = {
    Text = "Va tutto bene. Vedi? È solo un po' di zucchero. Nessun danno."
  },
  AvgDialog_48094_Content_19 = {
    Text = "Aigis sbatte le palpebre. Avvertendo un calore bruciante in gola, mormora qualcosa sottovoce."
  },
  AvgDialog_48094_Content_2 = {
    Text = "Bussi alla sua porta, e dall'interno risuona immediatamente un fragore — il suono di qualcosa di pesante, come Pietra, che si rovescia e si frantuma in mille pezzi."
  },
  AvgDialog_48094_Content_20 = {
    Text = "Sei troppo silenzioso. Non riesco a sentirti."
  },
  AvgDialog_48094_Content_21 = {Text = "Ugh..."},
  AvgDialog_48094_Content_22 = {
    Text = "P-potresti trovarmi della cioccolata calda, per favore? Un solo sorso e starò subito meglio... È quello che mi diceva sempre la signorina Sarah."
  },
  AvgDialog_48094_Content_3 = {
    Text = "Cos'è stato? Aigis, sto entrando."
  },
  AvgDialog_48094_Content_4 = {
    Text = "Non incontri alcuna Resistenza mentre spingi la porta aperta. Ti volti istintivamente: la serratura si è trasformata in sottile e friabile scisto, che si sbriciola a terra al tuo tocco."
  },
  AvgDialog_48094_Content_5 = {
    Text = "C-Custode... sto bene... Aigis sta bene..."
  },
  AvgDialog_48094_Content_6 = {
    Text = "Aigis siede al centro di una Stanza che sembra una rovina romana, con gli occhi serrati."
  },
  AvgDialog_48094_Content_7 = {
    Text = "Credo di avere la febbre... L'occhio grande non mi obbedisce più. Ogni volta che lo apro, tutto si trasforma in Pietra..."
  },
  AvgDialog_48094_Content_8 = {
    Text = "La febbre. Un altro caso di febbre misteriosa tra i Risvegliati."
  },
  AvgDialog_48094_Content_9 = {
    Text = "La Verità ti colpisce: queste sono le conseguenze dell'Incidente di Remouahe."
  },
  AvgDialog_48095_Content_1 = {
    Text = "Un'appendice, tre stomaci di mucca, sedici denti di specie diverse e un grosso mucchio di ossa rotte..."
  },
  AvgDialog_48095_Content_10 = {
    Text = "Uvhash ti porge una mandibola luccicante come fosse un tesoro segreto. Sotto la luce della luna, gli interstizi tra i denti brillano di una luce verde spettrale."
  },
  AvgDialog_48095_Content_11 = {
    Text = "Allora? Divertente, vero? AHAHAHA!"
  },
  AvgDialog_48095_Content_12 = {
    Text = "<Shake:EEEEKKKK—!!>"
  },
  AvgDialog_48095_Content_13 = {
    Text = "Schiaffeggi via la mano di Uvhash. La mandibola cade a terra e si frantuma istantaneamente in due pezzi."
  },
  AvgDialog_48095_Content_14 = {
    Text = "@3! L'avevo a malapena comprata da quell'ancella..."
  },
  AvgDialog_48095_Content_15 = {
    Text = "Un'ancella? Era Karen...? Quanto hai speso?"
  },
  AvgDialog_48095_Content_16 = {
    Text = "Non conosco il suo nome, solo una tizia bizzarra coperta di verde. Mi è costato circa 100 Fiorini Leoniani."
  },
  AvgDialog_48095_Content_17 = {
    Text = "Ha detto che era un tesoro supremo della 108ª Dinastia di Remouahe."
  },
  AvgDialog_48095_Content_18 = {Text = "..."},
  AvgDialog_48095_Content_19 = {
    Text = "Sei stato truffato. La Dinastia Remouahe è durata solo fino alla 30ª generazione, e quell'osso dev'essere stato incollato insieme; altrimenti non si spezzerebbe così facilmente."
  },
  AvgDialog_48095_Content_2 = {
    Text = "Sbatti con violenza un sacco macchiato di sangue davanti a Uvhash."
  },
  AvgDialog_48095_Content_20 = {
    Text = "Ha osato imbrogliarmi... Heh. Dammi dieci minuti; ucciderò quella tizia verde."
  },
  AvgDialog_48095_Content_21 = {
    Text = "Aspetta, Uvhash."
  },
  AvgDialog_48095_Content_22 = {
    Text = "Raccogli i frammenti da terra e li posi delicatamente nella mano di Uvhash."
  },
  AvgDialog_48095_Content_23 = {
    Text = "Grazie per il dono. Ma la prossima volta, ho bisogno che tu chieda la mia opinione prima di regalarmi qualsiasi cosa."
  },
  AvgDialog_48095_Content_24 = {
    Text = "Uvhash abbassa il capo, la sua figura imponente che blocca la luce lunare alle sue spalle, simile a un leone docile."
  },
  AvgDialog_48095_Content_25 = {
    Text = "Pensavo ti sarebbe piaciuto. Posso chiaramente percepire dal tuo odore che sei mio consanguineo, specialmente di recente—"
  },
  AvgDialog_48095_Content_26 = {
    Text = "Anche i membri della stessa specie non ameranno necessariamente le stesse identiche cose. Se la pensi così, significa che non ci conosciamo abbastanza bene, giusto?"
  },
  AvgDialog_48095_Content_27 = {
    Text = "Uvhash aggrotta le sopracciglia con disagio. Questa non è un'atmosfera di conversazione a lui familiare."
  },
  AvgDialog_48095_Content_28 = {
    Text = "...Oh. Va bene. Allora dimmi una cosa che ti piace."
  },
  AvgDialog_48095_Content_29 = {
    Text = "<Small:Se parliamo di preferenze, la torta al limone della Sam's Bread Workshop in Lincoln High Street è ottima, ricordati di dirle di mettere più glassa e gelatina, ah, non mettere troppa panna altrimenti Ramona si lamenterà…>"
  },
  AvgDialog_48095_Content_3 = {
    Text = "Se non mi sbaglio, ieri sei stato tu a intrufolarti nel mio dormitorio e a buttarci dentro tutta quella spazzatura."
  },
  AvgDialog_48095_Content_30 = {Text = "..."},
  AvgDialog_48095_Content_31 = {
    Text = "Va bene, te la comprerò. Ma prima devo regolare i conti con quella tizia verde che ha osato prendermi in giro..."
  },
  AvgDialog_48095_Content_32 = {
    Text = "Fai quello che vuoi, basta che non uccidi nessuno."
  },
  AvgDialog_48095_Content_33 = {
    Text = "Uvhash si dirige furioso verso la finestra, poi sembra ricordarsi improvvisamente di qualcosa. Si volta con un'espressione goffa e imbarazzata."
  },
  AvgDialog_48095_Content_34 = {
    Text = "Abbi cura di te... Verrò a trovarti domani."
  },
  AvgDialog_48095_Content_35 = {
    Text = "Dopo aver detto ciò, spicca un salto, e la sua figura esile svanisce nella luce lunare."
  },
  AvgDialog_48095_Content_36 = {
    Text = "A domani, Uvhash."
  },
  AvgDialog_48095_Content_37 = {
    Text = "La mia stanza ha una porta! <Big:Per favore, usa l'ingresso principale la prossima volta—!!>"
  },
  AvgDialog_48095_Content_4 = {
    Text = "Uvhash, vuoi spiegare le tue azioni?"
  },
  AvgDialog_48095_Content_5 = {Text = "...Hmph."},
  AvgDialog_48095_Content_6 = {
    Text = "Grazie a te, nessuno vuole più avvicinarsi al mio dormitorio. Puzzo di cavolo marcio ormai."
  },
  AvgDialog_48095_Content_7 = {
    Text = "A quanto pare non apprezzi i miei doni. Heh, pensavo avessimo gusti simili..."
  },
  AvgDialog_48095_Content_8 = {
    Text = "<Gray:Padre Supremo, che cosa ho fatto per dargli un'idea simile?>"
  },
  AvgDialog_48095_Content_9 = {
    Text = "Sei sicuro di non volere questa mandibola? C'è una sorpresa che ti attende stanotte."
  },
  AvgDialog_48096_Content_1 = {
    Text = "Sigh... Doll ha fatto di nuovo straordinario, e la prossima lezione è dall'altra parte del campus, nell'Edificio F. Come faccio ad arrivarci?"
  },
  AvgDialog_48096_Content_10 = {
    Text = "Se solo aggiungo te—se ti inserisco in ogni equazione—il Disastro Nero resta lontano, lontanissimo. Devo restare con te, altrimenti accadrà qualcosa di brutto. Qualcosa di nero e terribile..."
  },
  AvgDialog_48096_Content_11 = {
    Text = "Luminosa, così luminosa... la tua anima... brilli così tanto. Dev'essere così sicuro stare vicino a te..."
  },
  AvgDialog_48096_Content_12 = {
    Text = "I suoi deliri frammentati ti sibilano accanto all'orecchio, ma hai smesso di ascoltare. La tua mente è altrove, perché—"
  },
  AvgDialog_48096_Content_13 = {
    Text = "Winkle, lasciami! La campana sta suonando e farò tardi! <BigShake:Winkle!>"
  },
  AvgDialog_48096_Content_2 = {Text = "<Big:AHH!>"},
  AvgDialog_48096_Content_3 = {
    Text = "Un'improvvisa, violenta forza alle tue spalle ti fa barcollare in avanti; riesci a malapena a restare in piedi."
  },
  AvgDialog_48096_Content_4 = {
    Text = "Winkle? Cosa sta succedendo...?"
  },
  AvgDialog_48096_Content_5 = {
    Text = "Scusa, scusa! N-non l'ho fatto apposta! È solo che... devo stare con te. Devo!"
  },
  AvgDialog_48096_Content_6 = {Text = "...Winkle?"},
  AvgDialog_48096_Content_7 = {
    Text = "Stavo cercando di usare la Formula @3 e la Congettura @1@4 per calcolare la distanza tra noi e il Disastro Nero, ma non riesco a ottenere il risultato giusto. Qualunque cosa faccia, i calcoli sono sbagliati..."
  },
  AvgDialog_48096_Content_8 = {
    Text = "Poi ho capito che mi mancava una variabile. Una singola, splendente anima—"
  },
  AvgDialog_48096_Content_9 = {
    Text = "E quello sei tu!"
  },
  AvgDialog_48139_Content_1 = {Text = "—Clang."},
  AvgDialog_48139_Content_10 = {
    Text = "Se avevi bisogno di aiuto, potevi semplicemente venire a cercarmi al Mythag—GAH?!"
  },
  AvgDialog_48139_Content_11 = {
    Text = "Ti afferra la gola con una mano mentre la melma intorno a lei si trasforma in lame affilate, squarciando il colletto della tua uniforme. Il filo gelido preme contro il tuo collo, rendendo ogni respiro una scommessa."
  },
  AvgDialog_48139_Content_12 = {
    Text = "Shh... silenzio. Queste spore non vanno spaventate."
  },
  AvgDialog_48139_Content_13 = {
    Text = "Un dito si posa sulle tue labbra. Al suo segnale, volgi lo sguardo verso le pustole pulsanti dietro di lei—"
  },
  AvgDialog_48139_Content_14 = {
    Text = "Queste nuove si sono scisse dal mio stesso corpo, ma sono prive di autocoscienza... Non possono ancora servire la mia vendetta."
  },
  AvgDialog_48139_Content_15 = {
    Text = "Non sono abbastanza autocoscienti?"
  },
  AvgDialog_48139_Content_16 = {
    Text = "Le pustole sono innaturalmente attive. Si ammassano ai tuoi piedi, producendo strani rumori viscidi e gorgoglianti mentre si urtano l'una con l'altra."
  },
  AvgDialog_48139_Content_17 = {
    Text = "Non abbastanza. Ecco perché ho bisogno di te."
  },
  AvgDialog_48139_Content_18 = {Text = "Io?"},
  AvgDialog_48139_Content_19 = {
    Text = "Helot afferra con forza la tua mano, premendola contro la sua coscia nuda. Una sensazione fredda e appiccicosa scivola silenziosamente sotto il tuo colletto strappato."
  },
  AvgDialog_48139_Content_2 = {
    Text = "Alzarsi tira le catene; il suono del metallo che cozza riecheggia implacabile nell'oscurità."
  },
  AvgDialog_48139_Content_20 = {
    Text = "Ehi?! Helot, cosa stai facendo?!"
  },
  AvgDialog_48139_Content_21 = {
    Text = "Scivolano umide su ogni centimetro di pelle come acqua che traccia il letto di un fiume, seguendo i contorni dei tuoi muscoli verso il basso."
  },
  AvgDialog_48139_Content_22 = {
    Text = "La loro padrona stringe la presa sulla tua mano. I suoi occhi cremisi ardono con un'intensità così feroce da sembrare sul punto di consumarsi del tutto."
  },
  AvgDialog_48139_Content_23 = {
    Text = "Ho bisogno dei tuoi qualia... per concedere loro una vera \"coscienza.\""
  },
  AvgDialog_48139_Content_3 = {
    Text = "Sei sveglio. Non c'è tempo da perdere. Cominciamo."
  },
  AvgDialog_48139_Content_4 = {
    Text = "Quella voce... Helot?! Che stai facendo? Pensavo avessimo superato quei malintesi."
  },
  AvgDialog_48139_Content_5 = {
    Text = "Perché sono legato in questo modo?"
  },
  AvgDialog_48139_Content_6 = {
    Text = "Sì... non c'è più un conflitto di interessi tra noi."
  },
  AvgDialog_48139_Content_7 = {
    Text = "Helot si inginocchia davanti a te, usando la melma nella sua mano per corrodere le catene che ti vincolano le gambe."
  },
  AvgDialog_48139_Content_8 = {
    Text = "Sei libero, ma non pensare di fuggire. Questo tunnel sotterraneo è stato abbandonato dopo la nostra battaglia. Non troverai nessuno che possa aiutarti qui."
  },
  AvgDialog_48139_Content_9 = {
    Text = "Ho bisogno di un favore."
  },
  AvgDialog_48142_Content_1 = {
    Text = "È un onore che dedichiate il vostro prezioso tempo alla Chiesa, nonostante i vostri impegni. Porterò questa gentilezza sempre con me."
  },
  AvgDialog_48142_Content_10 = {
    Text = [[
...Capisco.
Il crollo dell'Albero Sacro di Remouahe ha sottoposto i Risvegliatori di tutto il mondo a un'intensa...]]
  },
  AvgDialog_48142_Content_11 = {
    Text = "Ahem... intenso... uuhhh..."
  },
  AvgDialog_48142_Content_12 = {
    Text = "Capisco. È l'intenso, innaturalmente amplificato \"desiderio di proliferazione\" che mi chiama."
  },
  AvgDialog_48142_Content_13 = {
    Text = "Vi prego, perdonate questo mio Smarrimento di decoro."
  },
  AvgDialog_48142_Content_14 = {
    Text = "...No, niente affatto. Io... ti assolvo dai tuoi peccati. Si fa così?"
  },
  AvgDialog_48142_Content_15 = {
    Text = "Una mia svista. Dimenticavo che non hai esperienza con le confessioni."
  },
  AvgDialog_48142_Content_16 = {
    Text = "Salvador apre la piccola finestra del confessionale. Posa entrambe le mani guantate sul davanzale, i palmi rivolti verso l'alto, verso di te."
  },
  AvgDialog_48142_Content_17 = {
    Text = "Se voleste... per favore, prendete le mie mani."
  },
  AvgDialog_48142_Content_18 = {
    Text = "(Tendi le mani)"
  },
  AvgDialog_48142_Content_19 = {
    Text = "Persino attraverso i guanti, il suo calore innaturale filtra — come l'ardore di un'anima in Fiamma Divina, che brucia le tue vene con un'intensità irresistibile."
  },
  AvgDialog_48142_Content_2 = {
    Text = "Non è nulla. Sono lieto di essere stato d'aiuto."
  },
  AvgDialog_48142_Content_20 = {
    Text = "La Chiave d'Argento sul tuo petto diventa rovente; strappa via ogni cortese velo finché non resta che il nucleo nudo e tremante di ciascuno di voi."
  },
  AvgDialog_48142_Content_21 = {
    Text = "Ora, per favore, ripetete dopo di me."
  },
  AvgDialog_48142_Content_22 = {
    Text = "Il peccato è una catena, eppure su quella stessa catena giace la chiave dell'assoluzione e della salvezza."
  },
  AvgDialog_48142_Content_23 = {
    Text = "Il peccato è una catena, eppure su quella stessa catena giace la chiave dell'assoluzione e della salvezza."
  },
  AvgDialog_48142_Content_24 = {
    Text = "Il suo cuore, consumato dal tormento della virtù, ne ha assaporato l'amaro frutto."
  },
  AvgDialog_48142_Content_25 = {
    Text = "Il suo cuore, consumato dal tormento della virtù, ne ha assaporato l'amaro frutto."
  },
  AvgDialog_48142_Content_26 = {
    Text = "Un lampo di Intuizione fonde i Frammenti nella tua mente in una Rivelazione. Un istinto ti spinge a parlare per primo, prima che Salvador prosegua:"
  },
  AvgDialog_48142_Content_27 = {
    Text = "...Padre misericordioso, concedigli la luce per camminare. Perdona i suoi peccati."
  },
  AvgDialog_48142_Content_28 = {
    Text = "Anche tu hai udito la guida del Padre di Tutto..."
  },
  AvgDialog_48142_Content_29 = {
    Text = "Pallido Messaggero, grazie per aver dissipato la mia Oscurità ancora una volta."
  },
  AvgDialog_48142_Content_3 = {
    Text = "Il confessionale è buio e angusto. Siedi rigidamente sul sedile di quercia, ma la curiosità sul motivo per cui sei stato convocato qui supera di gran lunga qualsiasi disagio."
  },
  AvgDialog_48142_Content_4 = {
    Text = "Di solito è Salvador a occupare il confessionale. Ma nel momento in cui sei arrivato alla Chiesa, ti ha condotto in questa cabina. Deve esserci una ragione particolare."
  },
  AvgDialog_48142_Content_5 = {
    Text = "Vi prego, permettetemi di tralasciare ulteriori formalità, Fuoco Pallido, e consentitemi di offrire la mia Confessione."
  },
  AvgDialog_48142_Content_6 = {
    Text = "Devo confessare... di recente, indicibili bramosie si sono destate in me."
  },
  AvgDialog_48142_Content_7 = {
    Text = "La sua voce si diffonde come un'eco proveniente da una Catena Montuosa lontana, sprofondando lentamente, infiltrandosi nelle antiche pareti di legno del confessionale. Quel timbro profondo e risonante sembra trattenere una bestia senza nome al suo interno, affinché non oltrepassi soglie invisibili e proibite."
  },
  AvgDialog_48142_Content_8 = {
    Text = "Ho conosciuto questi desideri in teoria, eppure non li avevo mai realmente provati prima, né so come possano eclissare la gloria del Padre di Tutto e macchiare il mio cuore."
  },
  AvgDialog_48142_Content_9 = {
    Text = "Ma come il guaritore stesso talvolta necessita di guarigione, temo che persino io, Suo Emissario, debba confessarmi al messaggero del Padre di Tutto per ottenere guida e assoluzione."
  },
  AvgDialog_48238_Content_1 = {
    Text = "Ti senti un po' meglio, Liz?"
  },
  AvgDialog_48238_Content_10 = {
    Text = "Una mano sottile si protende dal palcoscenico in un grazioso invito."
  },
  AvgDialog_48238_Content_11 = {
    Text = "Io? Ma non ho mai... Ehi..."
  },
  AvgDialog_48238_Content_12 = {
    Text = "Prima che tu potessi finire, la sua mano afferra la tua e ti trascina sul palcoscenico."
  },
  AvgDialog_48238_Content_13 = {
    Text = "...Posa la mano sulla mia vita, Custode."
  },
  AvgDialog_48238_Content_14 = {
    Text = "Provo ancora riluttanza a danzare da sola. Ma forse posso insegnarti quei movimenti così belli."
  },
  AvgDialog_48238_Content_15 = {
    Text = "Avevi detto che mi avresti aiutata a gestire l'influenza del Fiume sacro, ricordi...?"
  },
  AvgDialog_48238_Content_16 = {
    Text = "Nel momento in cui la tua mano si posa sulla sua vita, il suo corpo agile trema leggermente."
  },
  AvgDialog_48238_Content_17 = {
    Text = "I polpastrelli delle tue dita incontrano raso fresco e scivoloso. Sotto di esso, la curva morbida e soda della sua vita si alza e si abbassa dolcemente a ogni respiro."
  },
  AvgDialog_48238_Content_18 = {
    Text = "Non ho mai provato il balletto prima d'ora... Va davvero bene così?"
  },
  AvgDialog_48238_Content_19 = {
    Text = "Segui la musica e muoviti come preferisci."
  },
  AvgDialog_48238_Content_2 = {
    Text = "Nel teatro deserto, Liz scuote leggermente il capo. Puoi udire il suo respiro irregolare, scorgere il tenue rossore che le affiora sulle guance nella luce fioca."
  },
  AvgDialog_48238_Content_20 = {
    Text = "Ricorda, il Segreto del balletto è la giravolta."
  },
  AvgDialog_48238_Content_21 = {
    Text = "Dal tocco delle mani al sostegno della vita, e attraverso l'estensione delle gambe, la danzatrice ti guida..."
  },
  AvgDialog_48238_Content_22 = {
    Text = "Calcio. Arco. Salto."
  },
  AvgDialog_48238_Content_23 = {
    Text = "Una musica eterea riecheggia nel teatro vuoto, un fascio di luce fredda traccia le vostre sagome sul palco."
  },
  AvgDialog_48238_Content_24 = {
    Text = "Girate insieme. Le guance di Liz si fanno sempre più rosee, i suoi occhi smeraldini ti lanciano sguardi con un velo di timidezza."
  },
  AvgDialog_48238_Content_25 = {
    Text = "Come me la cavo?"
  },
  AvgDialog_48238_Content_26 = {
    Text = "Terribile. Ma questa sarà la mia esibizione di danza preferita, Custode."
  },
  AvgDialog_48238_Content_27 = {
    Text = "Rallentiamo un po'? Comincio a sentirmi un po'..."
  },
  AvgDialog_48238_Content_28 = {
    Text = "I suoi occhi smeraldini si chiudono dolcemente. Labbra fresche si posano sulle tue."
  },
  AvgDialog_48238_Content_29 = {
    Text = "Gira. E gira ancora."
  },
  AvgDialog_48238_Content_3 = {
    Text = "Pensavo che il teatro potesse calmarti e attenuare l'influenza del Fiume Sacro."
  },
  AvgDialog_48238_Content_30 = {
    Text = "Ciocche bianche di capelli fluttuano nell'aria; fiamme color veronese si avvolgono attorno a entrambi, ardendo senza calore, danzando con la musica. Il suo costume nero e verde traccia archi da cigno nell'aria."
  },
  AvgDialog_48238_Content_31 = {
    Text = "Vertigine. È la parola che stai cercando."
  },
  AvgDialog_48238_Content_32 = {
    Text = "I respiri sempre più pesanti di Liz ti sfiorano il viso. D'istinto, stringi la presa attorno alla sua vita; la pressione intensa la fa trasalire leggermente. Eppure, continuate a girare insieme."
  },
  AvgDialog_48238_Content_33 = {
    Text = "Ricorda, mio Custode. Il segreto del balletto è la rotazione..."
  },
  AvgDialog_48238_Content_34 = {
    Text = "Stanotte, sotto le luci scintillanti del teatro, una coppia di danzatori si perde in una piroetta senza fine."
  },
  AvgDialog_48238_Content_4 = {
    Text = "Forse possiamo fare qualcos'altro per distrarti. Lasciami pensare..."
  },
  AvgDialog_48238_Content_5 = {
    Text = "I suoi occhi color smeraldo tremolano. L'orlo nero del suo Vestito traccia un arco aggraziato davanti a te mentre sale agilmente sul Livello."
  },
  AvgDialog_48238_Content_6 = {
    Text = "Pensavo esitassi ancora riguardo al ballare..."
  },
  AvgDialog_48238_Content_7 = {
    Text = "Non ho mai detto che avrei ballato."
  },
  AvgDialog_48238_Content_8 = {
    Text = "E allora—?"
  },
  AvgDialog_48238_Content_9 = {
    Text = "Lascia che ti insegni a danzare, Custode."
  },
  AvgDialog_48555_Content_1 = {
    Text = "Mentre svolti un altro angolo nel blocco didattico, il peso opprimente che ti perseguita fin dal mattino si intensifica, schiacciandoti l'aria dai polmoni."
  },
  AvgDialog_48555_Content_10 = {
    Text = "La sfera emette una tenue luminescenza nella tua mano, pulsando con una forza vitale profonda e ritmica."
  },
  AvgDialog_48555_Content_11 = {
    Text = "All'interno delle pareti traslucide, ramificazioni a forma di ali di cicala sono ripiegate l'una sull'altra. Vibrano irregolarmente, come intrappolate in un lungo, profondo dormiveglia."
  },
  AvgDialog_48555_Content_12 = {
    Text = "Questo è...?"
  },
  AvgDialog_48555_Content_13 = {
    Text = "Vedendo che non hai rifiutato il suo dono, Faint lascia sfuggire un lungo sospiro di sollievo, mentre un sorriso appagato le si disegna sul volto."
  },
  AvgDialog_48555_Content_14 = {
    Text = "È un neonato della mia specie. Una volta raggiunta la maturità, tutte noi portiamo frutti come questo."
  },
  AvgDialog_48555_Content_15 = {
    Text = "Per così tanto, tanto tempo, non ho mai germogliato... Credevo davvero che non sarei mai diventata una @2 completamente matura."
  },
  AvgDialog_48555_Content_16 = {
    Text = "<Small:Sviluppo anomalo... un'altra conseguenza dell'Incidente di Remouahe.>"
  },
  AvgDialog_48555_Content_17 = {
    Text = "Come ti senti? Ci sono altri... cambiamenti insoliti da quando hai germogliato?"
  },
  AvgDialog_48555_Content_18 = {
    Text = "Faint scuote la testa, il suo volto dall'aspetto giovanile raggiante di gioia."
  },
  AvgDialog_48555_Content_19 = {
    Text = "Sento caldo... la testa e gli arti mi sembrano così caldi. Forse è questo che intendeva Tintura quando parlava di diventare adulta?"
  },
  AvgDialog_48555_Content_2 = {
    Text = "Ti accasci contro il muro in cerca di sostegno, cogliendo un fugace scorcio di un'ombra familiare che guizza oltre."
  },
  AvgDialog_48555_Content_3 = {
    Text = "...Faint? Sei tu?"
  },
  AvgDialog_48555_Content_4 = {
    Text = "L'ombra bianca si ferma un istante prima di uscire dal suo nascondiglio. L'esile struttura bianca che trasporta la sua padrona scivola lentamente verso di te."
  },
  AvgDialog_48555_Content_5 = {
    Text = "...Custode."
  },
  AvgDialog_48555_Content_6 = {
    Text = "Si protende verso di te come se volesse strisciare fuori dalla \"Culla\" — ma abbandonare quel limitatore non farebbe che far spirare fuori controllo i suoi istinti."
  },
  AvgDialog_48555_Content_7 = {
    Text = "Rendendosi conto che qualcosa non va, esita. Stringendo le labbra, stacca una delle sfere luminose dalla Culla, quella più vicina al suo corpo."
  },
  AvgDialog_48555_Content_8 = {
    Text = "Per favore... accetta questo."
  },
  AvgDialog_48555_Content_9 = {
    Text = "Allunghi la mano. Mentre afferri la sfera, le punte delle tue dita sfiorano il suo palmo morbido. Faint trasale all'istante, rannicchiandosi più a fondo nella sicurezza della Culla."
  },
  AvgDialog_48556_Content_1 = {
    Text = "Custode, se non è un disturbo... potresti dedicarmi un momento?"
  },
  AvgDialog_48556_Content_10 = {
    Text = "Non è una melodia conosciuta a Kadath. Il suono che trafigge il tuo giro temporale trasverso è ossessionante come il cosmo profondo, eppure brilla della tenerezza delle stelle del mattino."
  },
  AvgDialog_48556_Content_11 = {
    Text = "La tua mente diventa una nave senza timone, trascinata verso le rive del Desiderio dal richiamo del canto di Tintura."
  },
  AvgDialog_48556_Content_12 = {
    Text = "Una sensazione fredda e umida preme contro le tue labbra, e un fuoco oscuro senza nome si accende nella tua gola."
  },
  AvgDialog_48556_Content_13 = {
    Text = "Quando riapri gli occhi, Tintura ti guarda dal basso, le sue labbra appaiono particolarmente carnose e umide."
  },
  AvgDialog_48556_Content_14 = {
    Text = "Una consapevolezza incredibile ti siede sulla punta della lingua, ma la ragione viene rapidamente travolta di nuovo quando la Cantilena torna sulle tue labbra."
  },
  AvgDialog_48556_Content_15 = {
    Text = "Il canto gioca con le tue brame più profonde e oscure, sfumando il confine tra realtà e fantasia. Sei impotente a resistere, e impotente a fuggire."
  },
  AvgDialog_48556_Content_16 = {
    Text = "Shh... solo per stanotte, ti prego, resta prigioniero del mio canto..."
  },
  AvgDialog_48556_Content_2 = {
    Text = "Certo. È successo qualcosa a scuola ultimamente che ti ha turbata?"
  },
  AvgDialog_48556_Content_3 = {
    Text = "No, no... non è quello."
  },
  AvgDialog_48556_Content_4 = {
    Text = "È solo che ho una canzone. A qualunque costo... devo assolutamente cantarla per te."
  },
  AvgDialog_48556_Content_5 = {
    Text = "Annuisci e ti accomodi sulla chaise longue nell'Area di Riposo — in fondo è solo una canzone."
  },
  AvgDialog_48556_Content_6 = {
    Text = "L'inquietudine negli occhi della Risvegliatrice svanisce all'istante. Un sorriso indecifrabile si dispiega su un volto così squisito da sembrare ultraterreno."
  },
  AvgDialog_48556_Content_7 = {
    Text = "Questa è una canzone nata solo da te... ed è una canzone che canterò solo per te."
  },
  AvgDialog_48556_Content_8 = {
    Text = "Nel momento in cui la musica raggiunge le tue orecchie, la tua coscienza viene travolta, trascinata nel profondo di una fantasmagoria sfocata."
  },
  AvgDialog_48556_Content_9 = {
    Text = "La Voce di Tintura aggira i bastioni della ragione, insinuandosi tra le crepe della carne per sommergere l'anima."
  },
  AvgDialog_48596_Content_1 = {
    Text = "Secondo gli indizi di Erica, il mio mantello di riserva è stato visto l'ultima volta fuori dagli alloggi del vecchio Risveglio..."
  },
  AvgDialog_48596_Content_10 = {
    Text = "Un fantasma... un fantasma?!"
  },
  AvgDialog_48596_Content_11 = {
    Text = "Brown, andiamo — cosa stai aspettando!"
  },
  AvgDialog_48596_Content_12 = {
    Text = "Jenkin afferra freneticamente la tua mano, cercando di trascinarti fuori dalla \"Casa della Strega\". Ma il calore insolito del suo palmo ti fa immediatamente percepire che qualcosa non va."
  },
  AvgDialog_48596_Content_13 = {
    Text = "<Small:L'Influenza di Remouahe...>"
  },
  AvgDialog_48596_Content_14 = {
    Text = "Ignorando l'espressione nervosa di Jenkin, ti sei fatto avanti e hai aperto il guardaroba. Vari tessuti sono rotolati fuori, seppellendoti completamente."
  },
  AvgDialog_48596_Content_15 = {
    Text = "%player%?! Ehi! Non morirmi tra le braccia!"
  },
  AvgDialog_48596_Content_16 = {Text = "Squeak!!!"},
  AvgDialog_48596_Content_17 = {
    Text = "Jenkin e Brown hanno unito le forze per salvarti da sotto il tuo mantello scomparso, la tua camicia appena acquistata, le tue coperte invernali accuratamente riposte e altri vestiti."
  },
  AvgDialog_48596_Content_18 = {Text = "..."},
  AvgDialog_48596_Content_19 = {Text = "..."},
  AvgDialog_48596_Content_2 = {
    Text = "*Cough, cough,* è tutta polvere... Questo posto sembra essere stato abbandonato da anni. C'è davvero qualcuno—?"
  },
  AvgDialog_48596_Content_20 = {
    Text = "Stai... bene?"
  },
  AvgDialog_48596_Content_21 = {
    Text = "Perché stai rubando... perché stai raccogliendo i miei vestiti?"
  },
  AvgDialog_48596_Content_22 = {
    Text = "Jenkin mormorò qualcosa sottovoce, il corpo pronto a fuggire in qualsiasi momento."
  },
  AvgDialog_48596_Content_23 = {
    Text = "Ti accovacci impotente, prendendo un \"ostaggio\". Brown emette uno strano verso stridulo, i suoi occhi spalancati particolarmente innocenti."
  },
  AvgDialog_48596_Content_24 = {
    Text = "Brown—Va bene! Lo dirò!"
  },
  AvgDialog_48596_Content_25 = {
    Text = "Perché sono entrata nella mia pubblicità. Mia sorella una volta ha detto che durante la pubblicità, pensieri strani potrebbero saltarmi in testa."
  },
  AvgDialog_48596_Content_26 = {
    Text = "È la pubertà."
  },
  AvgDialog_48596_Content_27 = {
    Text = "Esatto! La pubertà! Per me si manifesta come un forte desiderio di rubare le tue cose. È la prova che tengo a te!"
  },
  AvgDialog_48596_Content_28 = {
    Text = "Le hai tirato giù il cappuccio, scuotendo la testa con un sorriso mentre lei esclamava: \"Ahi!\""
  },
  AvgDialog_48596_Content_29 = {
    Text = "La tua pubertà non è arrivata così presto. Riposati in questi giorni e tornerai alla normalità in poco tempo."
  },
  AvgDialog_48596_Content_3 = {
    Text = "Due serie di impronte si estendono dalle scale fino alla stanza in fondo. Quelle più piccole sembrano appartenere a un certo amico roditore."
  },
  AvgDialog_48596_Content_30 = {
    Text = "Ma se mai volessi \"collezionare\" di nuovo le mie cose, assicurati di farmelo sapere in anticipo."
  },
  AvgDialog_48596_Content_4 = {Text = "..."},
  AvgDialog_48596_Content_5 = {
    Text = "Cammini con passo leggero e respiri piano, seguendo la direzione delle impronte finché non spingi una porta in fondo al corridoio."
  },
  AvgDialog_48596_Content_6 = {Text = "Squeak—!"},
  AvgDialog_48596_Content_7 = {
    Text = "<Shake:WOAH!>\nMa q-questo non è il grande Custode? Cosa ti porta qui all'improvviso?"
  },
  AvgDialog_48596_Content_8 = {
    Text = "Jenkin sbatté l'armadio chiuso, quasi prendendo la coda di Brown nel caos. La piccola stanza fu istantaneamente gettata nel disordine."
  },
  AvgDialog_48596_Content_9 = {
    Text = "Dovrei chiederti come sei finita qui. Questo edificio è inutilizzato da anni, e ho sentito dire che un tempo era infestato dai fantasmi, perciò gli studenti lo chiamano anche \"Casa della Strega\"..."
  },
  AvgDialog_48597_Content_1 = {
    Text = "Ti sei calmato, adesso?"
  },
  AvgDialog_48597_Content_10 = {
    Text = "Voglio... stringerti di nuovo. Come prima."
  },
  AvgDialog_48597_Content_11 = {Text = "Annuisci."},
  AvgDialog_48597_Content_12 = {
    Text = "Poi, il suo torso gelido si preme contro di te."
  },
  AvgDialog_48597_Content_13 = {
    Text = "Durante i miei giorni al sanatorio, non ho mai conosciuto un calore simile. Se solo potessi restare al mio fianco per sempre..."
  },
  AvgDialog_48597_Content_14 = {
    Text = "Questo calore è come un veleno diverso, che lentamente mi divora. Spesso mi chiedo... se il mare alla fine ci separasse, quanto sarebbe solitario?"
  },
  AvgDialog_48597_Content_15 = {
    Text = "Puoi restare qui quanto vuoi."
  },
  AvgDialog_48597_Content_16 = {
    Text = "Il silenzio si protrae per un lungo minuto, finché il suo respiro superficiale non riprende un ritmo normale. Solo allora ti lascia andare dolcemente."
  },
  AvgDialog_48597_Content_17 = {
    Text = "Andiamo. È ora del tuo \"trattamento.\""
  },
  AvgDialog_48597_Content_18 = {
    Text = "Nymphaea prende la tua mano, guidandoti passo dopo passo nell'abbraccio del mare. L'acqua solleva dolcemente il suo orlo, cullandola come se fosse una ninfea viola pallido che sboccia lentamente sulle onde."
  },
  AvgDialog_48597_Content_19 = {
    Text = "La sua mano è gelida, eppure il suo sguardo è abbastanza intenso da lasciare un'ustione."
  },
  AvgDialog_48597_Content_2 = {
    Text = "Ah... sì. Mi dispiace..."
  },
  AvgDialog_48597_Content_20 = {
    Text = "Non preoccuparti. Il mare laverà via il veleno che ho lasciato nel tuo corpo."
  },
  AvgDialog_48597_Content_21 = {
    Text = "Quanto al \"veleno\" che hai lasciato nel mio cuore... lo custodirò per sempre."
  },
  AvgDialog_48597_Content_3 = {
    Text = "Non preoccuparti. Ultimamente tutti sono stati colpiti dalla piena del Fiume sacro. Qualche sfogo fuori dall'ordinario è solo da aspettarsi."
  },
  AvgDialog_48597_Content_4 = {
    Text = "Capisco, è solo che... se ti avvicini troppo a me, il \"veleno\" dentro il mio corpo comincerà a contaminarti."
  },
  AvgDialog_48597_Content_5 = {
    Text = "Abbassi lo sguardo sul palmo. Dove hai sfiorato poco fa l'inquietante struttura scheletrica di Nymphaea, un tenue livido bluastro-violaceo ha già iniziato a fiorire."
  },
  AvgDialog_48597_Content_6 = {
    Text = "Lo so... So come curarlo. Per favore, seguimi."
  },
  AvgDialog_48597_Content_7 = {
    Text = "La marea ruggisce, e una brezza marina salata scompiglia i capelli morbidi sulle tempie di Nymphaea. Lei alza una mano per fermare il cappello, mentre i fiori di seta nera ondeggiano con il movimento."
  },
  AvgDialog_48597_Content_8 = {
    Text = "Le tossine concentrate in questo mio scheletro si dissolveranno nell'acqua di mare."
  },
  AvgDialog_48597_Content_9 = {
    Text = "Dato che l'\"antidoto\" è proprio qui davanti a noi... posso farti una richiesta egoista?"
  },
  AvgDialog_48598_Content_1 = {
    Text = "Riconosci questo luogo; una volta fosti accolto in questo spazio dalla sua proprietaria, durante un evento passato."
  },
  AvgDialog_48598_Content_10 = {
    Text = "Vedi l'essenza primordiale aderire a una testa inquietante, pezzo dopo pezzo, strato dopo strato, torcendosi e delineando un volto che conosci fin troppo bene."
  },
  AvgDialog_48598_Content_11 = {
    Text = "Lady Daffodil..."
  },
  AvgDialog_48598_Content_12 = {
    Text = "La strega che attraversa le dimensioni rivela un sorriso enigmatico. Solleva il capo, allontanando le labbra di un viola fumoso dalla tua bocca affamata d'aria."
  },
  AvgDialog_48598_Content_13 = {
    Text = "Ti ho salvato dal pericolo ancora una volta, mio dolce piccolo Ospite."
  },
  AvgDialog_48598_Content_14 = {
    Text = "Hmm... Ma non entro in questo Mare per caso. Sei stato tu..."
  },
  AvgDialog_48598_Content_15 = {
    Text = "Shh... Ascolta. Ascolta cosa dicono le teste."
  },
  AvgDialog_48598_Content_16 = {
    Text = "Ti bramano. Senza di me, tesoro, saresti stato divorato vivo."
  },
  AvgDialog_48598_Content_17 = {
    Text = "Bene... e tu? Senza il tuo consenso, queste teste non avrebbero potuto trascinarmi qui."
  },
  AvgDialog_48598_Content_18 = {
    Text = "...Certo, voglio che ci sia anche tu."
  },
  AvgDialog_48598_Content_19 = {
    Text = "Quindi questa volta, il prezzo della nostra transazione... lo stabilirò io..."
  },
  AvgDialog_48598_Content_2 = {
    Text = "Disteso supino sull'acqua scura e viscosa, i tuoi occhi incontrano il sole bianco cenere che pende in alto come una moneta morta. Le teste intorno a te ondeggiano e cianciano, ridono, si maledicono a vicenda, o piangono sole in sussurri."
  },
  AvgDialog_48598_Content_3 = {
    Text = "Arrivano a ondate, urtando contro le tue braccia, quasi rovesciandoti a faccia in giù nell'acqua."
  },
  AvgDialog_48598_Content_4 = {
    Text = "Questo è il Mare dell'Essenza Primordiale, la tana della Strega Dimensionale, il santuario più prezioso di Daffodil."
  },
  AvgDialog_48598_Content_5 = {
    Text = "Perché sei qui? È un altro invito di Daffodil? O potrebbe essere soltanto un sogno assurdo..."
  },
  AvgDialog_48598_Content_6 = {
    Text = "Le tue membra si aprono alla deriva, lasciando che il Mare ti sospinga verso una riva inesistente. Innumerevoli teste si accalcano tra le onde grigie; il suono delle ossa che cozzano è nitido, vuoto e sinistro."
  },
  AvgDialog_48598_Content_7 = {
    Text = "L'acqua marina primordiale sgorga dagli angoli dei tuoi occhi, inondando il tuo corpo intero. Schiacciato sotto la moltitudine incalzante di teste, sprofondi sotto la superficie — e in pochi istanti, la folla che oscura il cielo eclissa ogni luce."
  },
  AvgDialog_48598_Content_8 = {
    Text = "— E poi, le teste del caos si avvicinano. Volti freddi e umidi sfiorano la tua guancia, e labbra afferrano le tue."
  },
  AvgDialog_48598_Content_9 = {
    Text = "Aria fredda e umida scivola nella tua bocca. Un profumo di violetta emana da tutti i tuoi organi, dispiegandosi dal tuo centro verso l'esterno."
  },
  AvgDialog_4870_Content_1 = {
    Text = "Tch, portarsi dietro questa qui è solo una seccatura."
  },
  AvgDialog_4870_Content_2 = {
    Text = "Casiah non si è ancora ripresa dal suo stato di Svenimento, quindi Lotan non ha altra scelta che portarla con sé durante l'operazione."
  },
  AvgDialog_4870_Content_3 = {
    Text = "Lasciate i combattimenti a me, per favore!"
  },
  AvgDialog_4871_Content_1 = {
    Text = "Il comunicatore sul tuo petto si scalda leggermente, e una limpida voce femminile risuona nella tua mente, venata di urgenza e preoccupazione."
  },
  AvgDialog_4871_Content_10 = {
    Text = "La pellicola e le fotocamere sono entrambe invenzioni recenti, scarsamente disponibili sul mercato, quindi naturalmente non sono economiche.\nE la pellicola che è stata <Yellow:trattata dai Mythag> è ancora più costosa."
  },
  AvgDialog_4871_Content_11 = {
    Text = "Trattata? La pellicola dei grandi magazzini non può essere usata direttamente?"
  },
  AvgDialog_4871_Content_12 = {
    Text = "L'Argento causa un'esposizione anomala sulla pellicola. Solo la pellicola trattata dal <Blue:Laboratorio dell'Argento dei Mythag> può Registrare l'aspetto dei Risvegliatori."
  },
  AvgDialog_4871_Content_13 = {
    Text = "Il prototipo di bobina nelle tue mani è un pezzo unico, e probabilmente può Registrare solo circa 20 minuti di riprese… Allora, le riprese sono finite?"
  },
  AvgDialog_4871_Content_14 = {
    Text = "Ehm…probabilmente…ci serve ancora un po' di tempo… Tutti stanno…facendo un brainstorming!"
  },
  AvgDialog_4871_Content_15 = {
    Text = "Giusto. Dopotutto, testare l'Effetto della fotocamera è solo un obiettivo secondario — divertirsi è ciò che conta di più, no?"
  },
  AvgDialog_4871_Content_16 = {
    Text = "Bene allora, vi auguro a tutti una splendida vacanza. Non vedo l'ora di vedere il vostro lavoro."
  },
  AvgDialog_4871_Content_17 = {
    Text = "Ramona chiuse la chiamata, lasciandoti con un'espressione completamente sconvolta."
  },
  AvgDialog_4871_Content_2 = {
    Text = "Ho percepito fluttuazioni psichiche... Avete incontrato dei nemici? Non siete feriti, vero?"
  },
  AvgDialog_4871_Content_3 = {
    Text = "Abbiamo solo incontrato alcuni Mutanti, tutto qui. Tutti stanno bene."
  },
  AvgDialog_4871_Content_4 = {
    Text = "Meno male. Sta andando tutto liscio?"
  },
  AvgDialog_4871_Content_5 = {
    Text = "Più o meno... liscio, direi."
  },
  AvgDialog_4871_Content_6 = {
    Text = "Ti sei ritrovato di fronte a diversi paia di occhi ansiosi. Quei giovani volti mostravano tutti gradi diversi di paura verso la \"proprietaria della fotocamera\"."
  },
  AvgDialog_4871_Content_7 = {
    Text = "Oh, a proposito, avevo una domanda — la pellicola per le fotocamere è costosa? Aurita è molto curiosa."
  },
  AvgDialog_4871_Content_8 = {
    Text = "Aurita non è poi così— mmph!"
  },
  AvgDialog_4871_Content_9 = {
    Text = "Casiah, che a un certo punto era scesa dalla spalla di Lotan, coprì la bocca di Aurita e trascinò da parte la Ragazza imbarazzata."
  },
  AvgDialog_4872_Content_1 = {
    Text = "Sento l'odore del negozio di scambi. Da questa parte."
  },
  AvgDialog_4872_Content_2 = {
    Text = "Sniff, sniff..."
  },
  AvgDialog_4872_Content_3 = {
    Text = "Aurita non riesce a sentire nessun odore tranne Brown!"
  },
  AvgDialog_4872_Content_4 = {
    Text = "Voi due non siete cuccioli!"
  },
  AvgDialog_4873_Content_1 = {
    Text = "Conosco Daffodil meglio di chiunque altro. Non è il tipo che si interessa alle sciocchezze dei bambini."
  },
  AvgDialog_4873_Content_10 = {
    Text = "La storia. Non vuoi filmare la tua storia?"
  },
  AvgDialog_4873_Content_11 = {
    Text = "Il mio compito è riportarvi tutti a scuola sani e salvi.\nNon contate su di me per scrivere copioni o fare film."
  },
  AvgDialog_4873_Content_13 = {
    Text = "La forma del Mutante si dissolse tra il suono di uno spadone che fendeva il Vento. Lotan pulì il fango nero dalla sua lama e si girò per regalarti un sorriso."
  },
  AvgDialog_4873_Content_14 = {
    Text = "Questo è ciò che devo fare."
  },
  AvgDialog_4873_Content_2 = {
    Text = "Solo le emozioni più intense ed estreme... possono far emergere il suo vero sorriso."
  },
  AvgDialog_4873_Content_3 = {
    Text = "Quello è dolore! Deve desiderare una storia profondamente intrisa di dolore, una che faccia <Red:sanguinare> tutti!"
  },
  AvgDialog_4873_Content_4 = {
    Text = "È davvero la sua personalità dietro quell'aspetto così calmo?\nAllora la mia storia... potrebbe non attirare la sua attenzione."
  },
  AvgDialog_4873_Content_5 = {
    Text = "Non dare retta alle sciocchezze di questo qui.\nDaffodil può apprezzare il dramma, ma la sua personalità non è così malevola."
  },
  AvgDialog_4873_Content_6 = {
    Text = "A cosa stai pensando? Ti va di condividere?"
  },
  AvgDialog_4873_Content_7 = {
    Text = "L'ho letto in un libro. Narra la storia di un sognatore che viaggia con aspirazioni cavalleresche in un'epoca in cui i cavalieri erano scomparsi."
  },
  AvgDialog_4873_Content_8 = {
    Text = "Mi sembra di aver letto anch'io quel libro... Lotan, e tu?"
  },
  AvgDialog_4873_Content_9 = {Text = "Io cosa?"},
  AvgDialog_4874_Content_1 = {
    Text = "Stavolta non possiamo assolutamente far scrivere la storia al mago!"
  },
  AvgDialog_4874_Content_10 = {
    Text = "Squiit squiit!!"
  },
  AvgDialog_4874_Content_11 = {
    Text = "Brown, aspetta! Il tuo turno arriva presto!"
  },
  AvgDialog_4874_Content_12 = {
    Text = "Cosa? Intendi il nemico?"
  },
  AvgDialog_4874_Content_13 = {
    Text = "Ahhh—! Quando sono spuntati fuori questi tipi strani?!"
  },
  AvgDialog_4874_Content_2 = {
    Text = "Perché no? Tempo, luogo, personaggi, conflitto, suspense — la mia storia non ha forse tutto questo? E ho introdotto tutto fin dall'inizio — non è così che si fa?"
  },
  AvgDialog_4874_Content_3 = {
    Text = "Con... conflitto cosa? Parlavi troppo in fretta, non ho capito."
  },
  AvgDialog_4874_Content_4 = {
    Text = "Ugh, il punto è che è troppo banale! Persino Aurita la troverebbe noiosa."
  },
  AvgDialog_4874_Content_5 = {
    Text = "Hm? Aurita pensa che siano tutte fantastiche!"
  },
  AvgDialog_4874_Content_6 = {
    Text = "Sciocchina...!"
  },
  AvgDialog_4874_Content_7 = {
    Text = "Comunque, se dipendesse da me, scriverei sicuramente \"<Blue:Il Vigilante di Mezzanotte di Londinium>\"!"
  },
  AvgDialog_4874_Content_8 = {
    Text = "Squi— Squiit!"
  },
  AvgDialog_4874_Content_9 = {
    Text = "In un hotel cremisi, sotto il tavolo della sua sontuosa sala da pranzo, la mano del ladro giusto puntò dritta al portafoglio del malvagio magnate..."
  },
  AvgDialog_4875_Content_1 = {
    Text = "Solo una pellicola speciale può Registrare i Risvegliatori, e noi abbiamo appena rovinato l'unico campione di prova…"
  },
  AvgDialog_4875_Content_10 = {
    Text = "Trucchi?! Questa è Magia, <Big:Magia!!>"
  },
  AvgDialog_4875_Content_11 = {
    Text = "Lotan, smettila di prenderla in giro per ora."
  },
  AvgDialog_4875_Content_12 = {
    Text = "Signorina Casiah, il modo che hai menzionato è..."
  },
  AvgDialog_4875_Content_13 = {
    Text = "Andate a cercare Madame Narcissus. Avrà sicuramente una soluzione.\nUna donna che ama così tanto guardare l'azione non può non essere interessata a una macchina che <Yellow:può registrare i Risvegliatori>."
  },
  AvgDialog_4875_Content_14 = {
    Text = "Tch... Dobbiamo avere a che fare di nuovo con quella donna?"
  },
  AvgDialog_4875_Content_15 = {
    Text = "Chiedere l'aiuto di Lady Daffodil? È una soluzione praticabile, purché ciò che vuole in cambio non sia troppo eccessivo..."
  },
  AvgDialog_4875_Content_16 = {
    Text = "Un leggero strattone ti tira il mantello. Abbassi lo sguardo e vedi Lily in punta di piedi, aggrappata all'orlo, con gli occhi che ti fissano dal basso."
  },
  AvgDialog_4875_Content_17 = {
    Text = "Lily, vuoi andare a trovare Lady Daffodil?"
  },
  AvgDialog_4875_Content_18 = {
    Text = "Madame Narcissus... L'amica della mamma, mm-hm!"
  },
  AvgDialog_4875_Content_19 = {
    Text = "Beh, se anche Lily lo dice, andiamo, Custode."
  },
  AvgDialog_4875_Content_2 = {
    Text = "Il test di ricerca della Signorina Doll… Maestro, credo che noi…"
  },
  AvgDialog_4875_Content_3 = {
    Text = "Il volto di Ogier assunse un colorito malsano, sprofondando nella stessa angoscia e Paura che provavi tu."
  },
  AvgDialog_4875_Content_4 = {
    Text = "Verremo giustiziati, vero."
  },
  AvgDialog_4875_Content_5 = {
    Text = "Maestro, non…lascerò…che accada…"
  },
  AvgDialog_4875_Content_6 = {
    Text = "Le parole di Ogier mancavano della loro solita convinzione. Di fronte alla potenziale ira di Doll, persino lui sembrava incerto e titubante."
  },
  AvgDialog_4875_Content_7 = {
    Text = "Perché avete tutti quell'aria così cupa?\nSu — fatemi un sorriso!"
  },
  AvgDialog_4875_Content_8 = {
    Text = "È solo pellicola speciale, giusto? Ho un'idea."
  },
  AvgDialog_4875_Content_9 = {
    Text = "Conosci anche trucchi per aggiustare le cose?"
  },
  AvgDialog_4876_Content_10 = {
    Text = "Figlia... Figlia mia!"
  },
  AvgDialog_4876_Content_11 = {
    Text = "È tutta colpa mia. Non sono riuscito a proteggerti, e ora ti sei persa nell'oscurità!"
  },
  AvgDialog_4876_Content_12 = {
    Text = "{Male=Lui,Female=Lei} si è comportat{Male=o,Female=a} come una scimmia a cui hanno pestato una zampa."
  },
  AvgDialog_4876_Content_13 = {
    Text = "Dove l'hai vista quella scimmia? Allo zoo di Londinium?"
  },
  AvgDialog_4876_Content_14 = {
    Text = "Silenzio, silenzio!!"
  },
  AvgDialog_4876_Content_15 = {
    Text = "Calmati, signorina Casiah! Sta arrivando un altro Corpo Aberrante!"
  },
  AvgDialog_4876_Content_2 = {
    Text = "Mamma, mamma, dove sei?"
  },
  AvgDialog_4876_Content_3 = {
    Text = "Mi dispiace, mamma. Non volevo perdermi. Mi dispiace."
  },
  AvgDialog_4876_Content_4 = {
    Text = "Lily... Non sono una bambina cattiva, per favore non abbandonarmi..."
  },
  AvgDialog_4876_Content_5 = {
    Text = "La voce della ragazza svanì nel vento, le sue lacrime caddero sul suolo scuro."
  },
  AvgDialog_4876_Content_6 = {
    Text = "Piangeva in silenzio nella stanza buia come la pece, un altro pugno di lacrime addolorate ad annaffiare i gigli bianchi puri accanto al suo letto."
  },
  AvgDialog_4876_Content_7 = {
    Text = "%player%, sbrigati! Tocca a te!"
  },
  AvgDialog_4876_Content_8 = {
    Text = "Non fare chiasso! Abbassa la voce!"
  },
  AvgDialog_4876_Content_9 = {
    Text = "Ti sei sistemato il colletto, cercando di apparire affranto dal dolore, e hai zoppicato davanti alla telecamera."
  },
  AvgDialog_4877_Content_10 = {
    Text = "L'espressione preoccupata sul volto della ragazza."
  },
  AvgDialog_4877_Content_11 = {
    Text = "Mamma...! Mamma!"
  },
  AvgDialog_4877_Content_12 = {
    Text = "Una piccola mano scavò nella neve. Un corpo fragile e minuto la protesse, affrontando la bufera urlante a viso aperto—"
  },
  AvgDialog_4877_Content_2 = {
    Text = "Una donna avvolta in pesanti abiti invernali avanza faticosamente nella neve, il suo carico pesante le appesantisce i passi e lascia impronte profonde dietro di sé."
  },
  AvgDialog_4877_Content_3 = {
    Text = "Aspettami... figlia mia, la mamma sarà al tuo fianco presto..."
  },
  AvgDialog_4877_Content_4 = {
    Text = "Dalla lontana montagna innevata, riecheggiò il forte fragore di qualcosa che crollava."
  },
  AvgDialog_4877_Content_5 = {Text = "Valanga?!"},
  AvgDialog_4877_Content_6 = {
    Text = "Aspetta, la valanga in <Yellow:Miraggio Magico> non è davvero pericolosa, giusto?"
  },
  AvgDialog_4877_Content_7 = {
    Text = "Cos'è il Miraggio Magico? È la grande immaginazione di questa solitaria avventuriera e il capolavoro di una grande maga. Incarna freddo, paura, incubi e crisi, tutto in uno!"
  },
  AvgDialog_4877_Content_8 = {
    Text = "Inseguita da blocchi di neve in crollo, l'avventuriera si addentrò nel campo innevato. Ma come possono i fragili esseri umani sconfiggere la natura? In un momento di distrazione, cadde in una caverna di ghiaccio senza fondo."
  },
  AvgDialog_4877_Content_9 = {
    Text = "La neve spessa premeva contro la trachea dell'avventuriera, offuscandole la vista. I ricordi le scorrevano davanti agli occhi: le ferite nere della malattia, la pioggia battente il giorno del funerale, e—"
  },
  AvgDialog_4878_Content_10 = {
    Text = "Conflitto! Questo deve essere uno dei momenti culminanti della storia; ci deve essere conflitto!"
  },
  AvgDialog_4878_Content_2 = {
    Text = "Ho sentito la tua voce, calda e umida... Mamma, stai piangendo?"
  },
  AvgDialog_4878_Content_3 = {
    Text = "Mamma... Mamma? Perché piangi?"
  },
  AvgDialog_4878_Content_4 = {
    Text = [[
Una madre stava davanti a una lapide, piangendo, mentre le grida della ragazza erano soffocate da un miscuglio di terra e legno.
Sebbene separate da un solo passo, non riusciva a sentire le suppliche della sua amata figlia.]]
  },
  AvgDialog_4878_Content_5 = {
    Text = "Mamma, per favore non piangere. Sarò una brava bambina... Per favore non ignorarmi..."
  },
  AvgDialog_4878_Content_6 = {
    Text = "Mamma... Sono così stanca... Mi troverai quando mi sveglierò?"
  },
  AvgDialog_4878_Content_7 = {
    Text = "Come una candela sul punto di spegnersi, la sua voce si fece sempre più debole e flebile.\nAlla fine, non riusciva più a sentire nemmeno la propria voce..."
  },
  AvgDialog_4878_Content_8 = {
    Text = "Mentre la ragazza cade in un sonno profondo, l'oscurità in agguato nel cimitero avanza impetuosa! Si scaglia verso la madre ignara e addolorata!"
  },
  AvgDialog_4878_Content_9 = {
    Text = "Aspetta! Il copione non prevedeva una battaglia?"
  },
  AvgDialog_4879_Content_1 = {Text = "Eccola."},
  AvgDialog_4879_Content_10 = {
    Text = "Tu e Nymphaea osservaste in silenzio la ragazza da lontano. I suoi occhi erano chiusi, ma un sorriso felice e sereno le illuminava il volto."
  },
  AvgDialog_4879_Content_11 = {
    Text = "Esiti a disturbare la quiete, ma i pazienti nel cortile non lasciano spazio a una tranquillità prolungata."
  },
  AvgDialog_4879_Content_12 = {
    Text = "Sorella Nymphaea... maestro..."
  },
  AvgDialog_4879_Content_13 = {
    Text = "Mi dispiace, mi sono allontanata senza permesso..."
  },
  AvgDialog_4879_Content_14 = {
    Text = "Va tutto bene, Lily. Vuoi restare ancora un po' con tua madre?"
  },
  AvgDialog_4879_Content_15 = {
    Text = "Lily ti stringe la mano, si volta a guardare la porta silenziosa e scuote la testa con decisione."
  },
  AvgDialog_4879_Content_16 = {
    Text = "Lily sa quale storia raccontare. Torniamo in fretta."
  },
  AvgDialog_4879_Content_17 = {
    Text = "Dopo aver salutato Nymphaea, lasciate il sanatorio e vi mettete in viaggio per tornare a Londinium."
  },
  AvgDialog_4879_Content_18 = {
    Text = "La luce lunare filtra attraverso l'aria nebbiosa e i vetri opachi del sanatorio."
  },
  AvgDialog_4879_Content_19 = {
    Text = "In un angolo dove il tempo si è fermato, una luce nascosta scorre attraverso il cerchio magico viola scuro."
  },
  AvgDialog_4879_Content_2 = {
    Text = "La ragazza che stai cercando è seduta in fondo al corridoio, appoggiata a una porta che ti è fin troppo familiare."
  },
  AvgDialog_4879_Content_3 = {
    Text = "Motivi intricati e misteriosi attraversano la porta, emanando una luce viola scuro."
  },
  AvgDialog_4879_Content_4 = {Text = "Madre..."},
  AvgDialog_4879_Content_5 = {
    Text = "Riesci a sentire Lily parlare?"
  },
  AvgDialog_4879_Content_6 = {
    Text = "I mormorii simili a quelli di un cucciolo non ricevettero risposta, forse perché la porta era troppo spessa, o forse perché dietro di essa non c'era più alcuna vita."
  },
  AvgDialog_4879_Content_7 = {
    Text = "Scusa... Lily ha accidentalmente dimenticato le storie che Mamma e Lily raccontavano."
  },
  AvgDialog_4879_Content_8 = {
    Text = "Lily vuole raccontare storie ai suoi amici... Mamma può insegnarle?"
  },
  AvgDialog_4879_Content_9 = {Text = "..."},
  AvgDialog_4880_Content_10 = {
    Text = "Voi siete i leggendari di Londinium —!"
  },
  AvgDialog_4880_Content_11 = {
    Text = "Sì! Vagando per Londinium di notte, vegliando sulle notti ordinarie dell'East End, parlando per i lavoratori, gridando per i bisognosi—"
  },
  AvgDialog_4880_Content_12 = {
    Text = "Noi siamo i <Blue:Ranger di Endnight> e i loro fedeli assistenti!"
  },
  AvgDialog_4880_Content_13 = {
    Text = "Il Grande Ranger della Notte balzò giù dalla spalla dell'assistente e, con pochi movimenti rapidi, usò la sua arma innata per mordere la corda di canapa!"
  },
  AvgDialog_4880_Content_14 = {
    Text = "Squeak, squeak!"
  },
  AvgDialog_4880_Content_15 = {
    Text = "Brown ha detto... *coff coff*, il Ranger della Notte ha detto: Questa corda è davvero dura da rosicchiare!\nMa ce l'abbiamo fatta! La luce della libertà ci sta chiamando!"
  },
  AvgDialog_4880_Content_16 = {
    Text = "Grazie, Ranger della Notte e compagni..."
  },
  AvgDialog_4880_Content_17 = {
    Text = "La ragazza si fermò dopo aver parlato e indicò la gentaglia attirata dal Ranger della Notte."
  },
  AvgDialog_4880_Content_2 = {
    Text = "Detective, ho sentito un rumore di denti che si spezzano."
  },
  AvgDialog_4880_Content_3 = {
    Text = "Un momento... Ci sono quasi..."
  },
  AvgDialog_4880_Content_4 = {
    Text = "Il coraggioso e affascinante detective giaceva a terra come un cane, con le mani legate dietro la schiena. Rifiutandosi di arrendersi, stava cercando di mordere la corda che legava i polsi della ragazza."
  },
  AvgDialog_4880_Content_5 = {
    Text = "In un angolo nascosto ai due, un paio di occhi feroci brillano nell'oscurità! Qualcosa sta per squarciare le ombre, portando la prima luce dell'alba!"
  },
  AvgDialog_4880_Content_6 = {
    Text = "Squeak, squeak squeak!"
  },
  AvgDialog_4880_Content_7 = {
    Text = "<Blue:Ranger della Notte> dice: Suggerisce di smettere di mordere. La corda magica del Maestro Houdini è dura come l'acciaio."
  },
  AvgDialog_4880_Content_8 = {
    Text = "Una persona..."
  },
  AvgDialog_4880_Content_9 = {Text = "Un topo..."},
  AvgDialog_4881_Content_1 = {
    Text = "Abbiamo vinto... Abbiamo vinto!"
  },
  AvgDialog_4881_Content_10 = {
    Text = "L'assistente sollevò in alto il Ranger Notturno, proteggendo temporaneamente la splendida pelliccia del ranger."
  },
  AvgDialog_4881_Content_11 = {
    Text = "Ehi!! Cadavere, smettila di parlare! Custode! Lotan! Fate qualcosa!!"
  },
  AvgDialog_4881_Content_12 = {
    Text = "Lotan scosse la testa, e il fantasma di una creatura simile a una balena apparve dietro di lei. Proprio mentre stava per tirare tutti fuori dall'acqua, una figura luminosa si tuffò dentro."
  },
  AvgDialog_4881_Content_13 = {
    Text = "Acqua! È acqua~ Il mare preferito di Aurita!"
  },
  AvgDialog_4881_Content_14 = {
    Text = "Esprimete un desiderio, voi che ne avete bisogno! L'oceano risponderà a tutte le vostre aspettative!"
  },
  AvgDialog_4881_Content_15 = {
    Text = "Il Detective G e il Ranger Notturno si scambiarono uno sguardo e contemporaneamente spinsero la ragazza in bianco, rimasta a lungo in silenzio, verso l'Elfa dell'Oceano."
  },
  AvgDialog_4881_Content_16 = {Text = "...?!"},
  AvgDialog_4881_Content_17 = {
    Text = "Per favore, per favore portateci via da qui."
  },
  AvgDialog_4881_Content_18 = {
    Text = "Casiah, con metà del corpo già sommerso dall'acqua, curvò le labbra in un sorriso soddisfatto."
  },
  AvgDialog_4881_Content_19 = {
    Text = "Le illusioni magiche si spostano e si trasformano con un gesto della sua mano."
  },
  AvgDialog_4881_Content_2 = {
    Text = "La perfida strega fu sconfitta dagli sforzi congiunti di tutti. Crollò a terra, allungando debolmente la mano verso un pulsante."
  },
  AvgDialog_4881_Content_20 = {
    Text = "In un batter d'occhio, tutti erano fradici d'acqua."
  },
  AvgDialog_4881_Content_21 = {
    Text = "Nessuno è stato risparmiato."
  },
  AvgDialog_4881_Content_22 = {
    Text = "Dici sul serio!?"
  },
  AvgDialog_4881_Content_23 = {
    Text = "L'elfa è tornata alla libertà del mare, e tutti sono fuggiti dal laboratorio di Houdini. Non è forse questo l'esaudimento del desiderio della ragazza?"
  },
  AvgDialog_4881_Content_24 = {
    Text = "Hai ragione, ma... come può questa storia raggiungere il finale che Lily desidera?"
  },
  AvgDialog_4881_Content_25 = {
    Text = "\"La ragazza visse per sempre felice e contenta con sua madre.\""
  },
  AvgDialog_4881_Content_26 = {
    Text = "\"Tsk, questa è l'ultima volta che faccio la babysitter per te.\nNon chiedermi più favori così fastidiosi.\""
  },
  AvgDialog_4881_Content_27 = {
    Text = "Lily, agente, guardate! Cos'è quello nell'acqua laggiù?!"
  },
  AvgDialog_4881_Content_29 = {
    Text = "Una colonna vertebrale massiccia emerge dall'acqua—la grande bestia che ha dimorato nei mari profondi di Kadath sin dalla nascita del pianeta. Risponde al richiamo della vita, attraversando il velo del tempo!"
  },
  AvgDialog_4881_Content_3 = {
    Text = "Vedendo questo, Lotan ti lanciò un altoparlante.\nSi avvicinò a grandi passi a Casiah e iniziò a sussurrarle all'orecchio."
  },
  AvgDialog_4881_Content_30 = {Text = "Lotan...?"},
  AvgDialog_4881_Content_31 = {
    Text = "Siete pronti a partire? In caso contrario, la vostra storia finirà in queste acque."
  },
  AvgDialog_4881_Content_32 = {
    Text = "Wow! Un pesce enorme!"
  },
  AvgDialog_4881_Content_33 = {
    Text = "Non abbiate fretta, uno alla volta. La schiena della signorina Lotan è piuttosto spaziosa."
  },
  AvgDialog_4881_Content_34 = {
    Text = "Puoi smetterla di rubare la scena, tu, spiritello marino mezzo cotto? È chiaro che Bru... No, il Ranger della Notte e io siamo i veri eroi qui!"
  },
  AvgDialog_4881_Content_35 = {Text = "Ehm..."},
  AvgDialog_4881_Content_36 = {
    Text = "Il pesce grande è il compagno di Aurita! Quindi Aurita deve sedersi davanti!"
  },
  AvgDialog_4881_Content_37 = {Text = "Um...!"},
  AvgDialog_4881_Content_38 = {
    Text = "Lily, Lili... Io..."
  },
  AvgDialog_4881_Content_39 = {
    Text = "Posso sedermi davanti?"
  },
  AvgDialog_4881_Content_4 = {
    Text = "Che cosa stai tramando adesso? Non rendere impossibile a tutti ripulire questo casino."
  },
  AvgDialog_4881_Content_40 = {
    Text = "Considerando che sei più piccola di me... Fai attenzione! Non ci sono sedili sulla schiena del bestione."
  },
  AvgDialog_4881_Content_41 = {
    Text = "Aurita vuole stare con i suoi compagni!"
  },
  AvgDialog_4881_Content_42 = {
    Text = "Ehi! Perché sei così scivolosa!? Se sai nuotare, non arrampicarti quassù!"
  },
  AvgDialog_4881_Content_43 = {
    Text = "Il behemoth muggisce attraverso le sue vie respiratorie, balzando fuori dall'acqua con risate e speranza."
  },
  AvgDialog_4881_Content_44 = {
    Text = "La luce dell'alba trafigge le nuvole e la foschia, drappeggiando il mare, le bestie colossali e gli avventurieri di sfumature rosse e rosa."
  },
  AvgDialog_4881_Content_45 = {
    Text = "Così, così in alto—!"
  },
  AvgDialog_4881_Content_47 = {
    Text = "Il Detective G, lo Spirito dell'Oceano e l'assistente del Ranger della Notte unirono le forze per afferrare la ragazza, impedendole di scivolare giù dalla schiena della bestia gigante."
  },
  AvgDialog_4881_Content_48 = {
    Text = "Alcune persone risero e giocarono, spruzzandosi acqua a vicenda sui vestiti."
  },
  AvgDialog_4881_Content_49 = {
    Text = "Forse per questi fortunati sopravvissuti, il finale originariamente previsto della storia non ha più importanza."
  },
  AvgDialog_4881_Content_5 = {
    Text = "Ops, solo un piccolo test—"
  },
  AvgDialog_4881_Content_50 = {
    Text = "In quel momento, la ragazza coraggiosa fissò improvvisamente lo sguardo su di te, seduto in silenzio sullo scoglio."
  },
  AvgDialog_4881_Content_51 = {
    Text = "Scintille di luce danzano nei suoi occhi, e su quel volto giovane sboccia un sorriso straordinariamente radioso."
  },
  AvgDialog_4881_Content_52 = {
    Text = "Un giglio intrappolato dal tempo, che ha mancato la sua stagione—"
  },
  AvgDialog_4881_Content_53 = {
    Text = "Il momento della fioritura è finalmente giunto."
  },
  AvgDialog_4881_Content_54 = {
    Text = "Clap, clap, clap."
  },
  AvgDialog_4881_Content_55 = {
    Text = "Un applauso riecheggia da oltre il set, e il profumo di violette riempie gradualmente l'aria. Qualcuno si avvicina con eleganza, trascinando un abito fluente."
  },
  AvgDialog_4881_Content_56 = {Text = "Daffodil!"},
  AvgDialog_4881_Content_57 = {
    Text = "Daffodil sorrise mentre rimuoveva la pellicola speciale, soffiando elegantemente via della polvere inesistente."
  },
  AvgDialog_4881_Content_58 = {
    Text = "In effetti, una bella storia. Accetto questo scambio."
  },
  AvgDialog_4881_Content_59 = {
    Text = [[
Aspetta! Non avevi mai detto che avresti portato via la pellicola.
Ora non possiamo fare rapporto a Doll.]]
  },
  AvgDialog_4881_Content_6 = {
    Text = "Mentre il sorriso sul volto di Casiah si allarga lentamente, il suono di una corrente sotterranea raggiunge le orecchie di tutti."
  },
  AvgDialog_4881_Content_60 = {
    Text = "Sei sempre impulsivo come al solito, Spadaccino Nero.\nPensa bene al compito della Signorina Doll—"
  },
  AvgDialog_4881_Content_61 = {
    Text = "\"Testare le macchine modificate\"... non testare la pellicola speciale, giusto?"
  },
  AvgDialog_4881_Content_62 = {
    Text = "Ma non ho ancora visto il film! È diverso dal fumetto, vero?"
  },
  AvgDialog_4881_Content_63 = {
    Text = "\nLa macchina ha registrato fedelmente la vostra storia, e la pellicola è solo il mezzo di questo momento meraviglioso...\nIl compito assegnato dal \"cervello in un barattolo\" è stato completato da voi già da tempo, non è vero?"
  },
  AvgDialog_4881_Content_64 = {
    Text = "Per quanto riguarda il film finito, do il benvenuto a tutti voi al Negozio di Scambio per guardarlo insieme."
  },
  AvgDialog_4881_Content_65 = {
    Text = "Proprio mentre stavi per convincere il mercante a tenere la pellicola, il tuo comunicatore ha vibrato nel momento meno opportuno."
  },
  AvgDialog_4881_Content_66 = {
    Text = "Ci hai messo così tanto a rispondere, ti stai divertendo un mondo? Spero che tu possa essere altrettanto concentrato quando completi i tuoi compiti scolastici."
  },
  AvgDialog_4881_Content_67 = {
    Text = "Saltiamo le formalità. Ho perso qualcosa—ti ho consegnato solo una scatola di pellicola speciale quando ho lasciato il laboratorio di ricerca, corretto?"
  },
  AvgDialog_4881_Content_68 = {
    Text = "Hmm... In effetti, solo una macchina fotografica e un rullino di pellicola."
  },
  AvgDialog_4881_Content_69 = {
    Text = "La voce priva di emozioni di Doll fluì nelle menti di tutto il personale Mythag presente, facendo trattenere il respiro alla folla che prima rideva e chiacchierava, per paura di perdere qualsiasi informazione."
  },
  AvgDialog_4881_Content_7 = {
    Text = "Venite, acque! Assistete al gran finale del Maestro Houdini — la fuga definitiva dalla vasca d'acqua!"
  },
  AvgDialog_4881_Content_70 = {
    Text = "Bene, dato che non c'è nessun registro di uscita da Erica, chiederti è inutile."
  },
  AvgDialog_4881_Content_71 = {
    Text = "Torna presto. Sei stato fuori abbastanza a lungo."
  },
  AvgDialog_4881_Content_72 = {
    Text = "Doll interruppe bruscamente la comunicazione. Quando la corrente lasciò i loro cervelli, tutti tirarono un sospiro di sollievo."
  },
  AvgDialog_4881_Content_73 = {
    Text = "Lady Daffodil! La pellicola che ci avete dato potrebbe essere—"
  },
  AvgDialog_4881_Content_74 = {
    Text = "Dov'è quella donna malvagia?! Quand'è che è sparita?!"
  },
  AvgDialog_4881_Content_75 = {
    Text = "Lily osservò il Mare Grigio scomparire dietro l'angolo del set. Notando il tuo sguardo, si voltò e camminò verso di te."
  },
  AvgDialog_4881_Content_76 = {
    Text = "Che succede, Lily?"
  },
  AvgDialog_4881_Content_77 = {
    Text = "Lily è molto felice..."
  },
  AvgDialog_4881_Content_78 = {
    Text = "Stringe forte l'orlo del tuo mantello, alza lo sguardo e ti regala un sorriso radioso."
  },
  AvgDialog_4881_Content_79 = {
    Text = "Grazie... \"Mamma\"."
  },
  AvgDialog_4881_Content_8 = {
    Text = "Il livello dell'acqua salì rapidamente, coprendo prima i piedi dei bambini, poi i polpacci... Infine raggiunse le cosce, rendendo difficile ogni movimento."
  },
  AvgDialog_4881_Content_80 = {Text = "La Fine"},
  AvgDialog_4881_Content_9 = {
    Text = "Casiah!!! Che stai facendo?! Vuoi farci annegare?!"
  },
  AvgDialog_4882_Content_1 = {
    Text = [[
Il mutante emise un ultimo grido, disperdendo scintille argentate. 
Presto, lei e la sua tristezza saranno dimenticate dal mondo.]]
  },
  AvgDialog_4882_Content_10 = {
    Text = "L'ho guardata appassire giorno dopo giorno, da un sole a una pozza senza vita che nemmeno il vento poteva increspare."
  },
  AvgDialog_4882_Content_11 = {
    Text = "Alla fine, solo il liquido nero e viscoso gocciolava dalle sue dita, fondendosi nel terreno."
  },
  AvgDialog_4882_Content_12 = {
    Text = "A differenza della poesia, le storie nascono sempre dalle persone. Mercanti e ricchi uomini d'affari, studenti e soldati, nobili e servitori... sono tutti storie."
  },
  AvgDialog_4882_Content_13 = {
    Text = "Ma il mio approccio... l'approccio della tristezza porterà solo la storia allo stesso finale."
  },
  AvgDialog_4882_Content_14 = {
    Text = "Signorina Horla..."
  },
  AvgDialog_4882_Content_15 = {
    Text = "Maestro, non è colpa della signorina Horla, vero?"
  },
  AvgDialog_4882_Content_16 = {Text = "..."},
  AvgDialog_4882_Content_17 = {
    Text = "Va tutto bene, piccola Lily, ho già accettato questa situazione."
  },
  AvgDialog_4882_Content_18 = {
    Text = "No, non è colpa tua."
  },
  AvgDialog_4882_Content_19 = {
    Text = "Perché... dici una cosa del genere?"
  },
  AvgDialog_4882_Content_2 = {
    Text = "L'ombra della tristezza... La conoscevi da prima, vero?"
  },
  AvgDialog_4882_Content_20 = {
    Text = "Ho sentito la voce del Mutante. Almeno il Sintomo: Collasso di questo fiorista non ha nulla a che fare con te."
  },
  AvgDialog_4882_Content_21 = {Text = "Cosa?"},
  AvgDialog_4882_Content_22 = {
    Text = "Dalle scarne parole lasciate dai Dissoluti, ho dedotto che lei manifestava già Sintomi di Dissoluzione ben prima che tu facessi richiesta di lasciare Mythag."
  },
  AvgDialog_4882_Content_23 = {
    Text = "Malata... Sono malata.\nNon riesco più a ricordare le cose, e a volte vedo cose strane.\nIl dottore dice che è un fantasma, un sintomo di isteria.\nSintomo: Isteria... sembra così distante."
  },
  AvgDialog_4882_Content_24 = {
    Text = "Ho sentito dire da altri che la nuova vicina in fondo alla strada è piuttosto talentuosa..."
  },
  AvgDialog_4882_Content_25 = {
    Text = "Ha comprato un mazzo di fiori da me e mi ha regalato una poesia. Che meraviglia! La mamma ha ricamato la poesia sulle tende!"
  },
  AvgDialog_4882_Content_26 = {Text = "..."},
  AvgDialog_4882_Content_27 = {
    Text = "Mi sto ammalando sempre di più, e la mamma sta diventando smemorata.\nCosa dovrei fare? Se me ne vado, chi si prenderà cura di lei? Chi baderà a questo negozio?"
  },
  AvgDialog_4882_Content_28 = {
    Text = "Non voglio lasciare casa... La mia famiglia ha ancora bisogno di me."
  },
  AvgDialog_4882_Content_29 = {
    Text = "La morte... No, non voglio ancora..."
  },
  AvgDialog_4882_Content_3 = {
    Text = "Prima della visita della <Yellow:Pestilenza>, Reni era la fioraia del paese."
  },
  AvgDialog_4882_Content_30 = {
    Text = "La sua tristezza nasce dal dolore di separarsi dalla famiglia e dalla paura di lasciare questo mondo."
  },
  AvgDialog_4882_Content_31 = {
    Text = "Davvero... non ha nulla a che fare con me?"
  },
  AvgDialog_4882_Content_32 = {
    Text = "Ha... lasciato qualche messaggio?"
  },
  AvgDialog_4882_Content_33 = {Text = "Disse..."},
  AvgDialog_4882_Content_34 = {
    Text = "\"La nuova vicina merita i fiori più belli.\""
  },
  AvgDialog_4882_Content_35 = {
    Text = "<Italic:Una volta in piena fioritura, per sempre radiosa...>"
  },
  AvgDialog_4882_Content_36 = {
    Text = "Grazie per il messaggio... Comporrò il poema finale per la sua storia."
  },
  AvgDialog_4882_Content_37 = {
    Text = "Horla si chinò, le punte delle dita sfiorarono la fronte di Lily, portando con sé il profumo di ricchi petali e la freschezza dell'acqua."
  },
  AvgDialog_4882_Content_38 = {
    Text = "Portala a cercare le storie, nella città, nella natura, nel suo futuro, nel suo passato..."
  },
  AvgDialog_4882_Content_39 = {
    Text = "Le storie ti troveranno quando meno te lo aspetti."
  },
  AvgDialog_4882_Content_4 = {
    Text = "Horla si accovaccia accanto alla D-melma lasciata dal Mutante, allungando la mano e passandola nell'aria sopra di essa."
  },
  AvgDialog_4882_Content_5 = {
    Text = "Suo padre e suo fratello perirono entrambi in un incidente minerario, ma lei continuò coraggiosamente a tenere unita la famiglia."
  },
  AvgDialog_4882_Content_6 = {
    Text = "La rosa si solidifica nel fango, sbocciando silenziosamente nel palmo della sua mano rivolta verso l'alto."
  },
  AvgDialog_4882_Content_7 = {
    Text = "Ereditò il negozio di fiori della nonna, mantenendo sé stessa e la madre malata... Meritava un finale felice e sereno."
  },
  AvgDialog_4882_Content_8 = {
    Text = "Se... non avesse incontrato me..."
  },
  AvgDialog_4882_Content_9 = {
    Text = "Horla abbassò lo sguardo, osservando il fiore di Dissoluzione appassire e cadere..."
  },
  AvgDialog_4883_Content_1 = {
    Text = "Anche Aurita può raccontare storie? Aurita ha delle storie!"
  },
  AvgDialog_4883_Content_10 = {Text = "Il mare..."},
  AvgDialog_4883_Content_11 = {
    Text = "L'ultima volta che ho visto il mare è stato sul Sentiero, quando lasciavo il Campo di Neve con la mamma..."
  },
  AvgDialog_4883_Content_12 = {
    Text = "Anche Lily ha delle storie? Aurita vuole sentire le tue!"
  },
  AvgDialog_4883_Content_13 = {
    Text = "Storie... Prima che la mamma si ammalasse, lei mi raccontava spesso delle storie della buonanotte."
  },
  AvgDialog_4883_Content_14 = {
    Text = "Ma io... non riesco a ricordarle nemmeno io."
  },
  AvgDialog_4883_Content_15 = {
    Text = "Lily, imbrogliona—!"
  },
  AvgDialog_4883_Content_16 = {
    Text = "Devi provare! Sforzati di più per ricordare!"
  },
  AvgDialog_4883_Content_17 = {Text = "Ma..."},
  AvgDialog_4883_Content_18 = {
    Text = "Lily, che cattiva. Non è che stai cercando di svignartela, vero?"
  },
  AvgDialog_4883_Content_19 = {
    Text = "Quando Aurita se la svigna e salta le lezioni, le danno il doppio dei compiti. Se Lily se la svigna, deve raccontare il doppio delle storie!"
  },
  AvgDialog_4883_Content_2 = {
    Text = "Tanto—tanto tempo fa, la nonna disse che Aurita era una bambina del mare!"
  },
  AvgDialog_4883_Content_20 = {Text = "?!"},
  AvgDialog_4883_Content_21 = {
    Text = "Beh, mi sembra un'ottima idea! Stai sempre con Lotan e {Male=Mr.,Female=Miss} \"Ashe\", senza mai giocare con noi."
  },
  AvgDialog_4883_Content_22 = {
    Text = "Cogli l'occasione per far familiarizzare tutti con il tuo odore!"
  },
  AvgDialog_4883_Content_23 = {
    Text = "Squeak! Squeak, squeak!"
  },
  AvgDialog_4883_Content_24 = {
    Text = "Un copione! Un copione! Lily, scrivi un copione!"
  },
  AvgDialog_4883_Content_25 = {
    Text = "Un copione! Un copione! Lily, scrivi un copione!"
  },
  AvgDialog_4883_Content_3 = {
    Text = "I genitori di Aurita sono tornati nel regno sottomarino. Quando Aurita crescerà, si riunirà con loro."
  },
  AvgDialog_4883_Content_4 = {
    Text = "Devono essere preoccupati per Aurita, quindi Aurita porterà tantissimi amici con sé!\nPorterà cagnolini, gattini, corvi, Custodi... e le meduse preferite di Aurita!"
  },
  AvgDialog_4883_Content_5 = {
    Text = "Così sapranno che Aurita vive felicemente anche sulla terraferma!"
  },
  AvgDialog_4883_Content_6 = {
    Text = "Ho la sensazione che molte di queste creature non siano proprio adatte a essere portate in mare..."
  },
  AvgDialog_4883_Content_7 = {
    Text = "Anch'io sono tra quelli che verranno portati in mare?"
  },
  AvgDialog_4883_Content_8 = {
    Text = "Sì! Sì sì! Il Custode è il compagno di Aurita! Anche Lily deve venire!"
  },
  AvgDialog_4883_Content_9 = {Text = "...!"},
  AvgDialog_4884_Content_1 = {
    Text = "Guidati da Casiah, vi fermate tutti davanti al più grande grande magazzino di Londinium, circondati da una folla brulicante di clienti."
  },
  AvgDialog_4884_Content_10 = {
    Text = "Quasi dimenticavo... fanno due barattoli chiusi ermeticamente."
  },
  AvgDialog_4884_Content_11 = {
    Text = "Casiah si mise dietro a tutti e spinse in avanti Lily, sempre silenziosa."
  },
  AvgDialog_4884_Content_12 = {
    Text = "Buongiorno, Lady Daffodil."
  },
  AvgDialog_4884_Content_13 = {
    Text = "Buongiorno, mia piccola ospite. Lascia che indovini cosa ti porta qui questa volta…"
  },
  AvgDialog_4884_Content_14 = {
    Text = "\"Pellicola in grado di registrare l'immagine di un Risvegliatore\"… Posso certamente trovare un simile articolo per i miei ospiti."
  },
  AvgDialog_4884_Content_15 = {
    Text = "Come facevi a saperlo? Non dirmi che hai mandato qualcuno a seguirci di nuovo?!"
  },
  AvgDialog_4884_Content_16 = {
    Text = "Come avrei potuto prevedere che avreste accidentalmente danneggiato una pellicola così preziosa?"
  },
  AvgDialog_4884_Content_17 = {
    Text = "Con un sorriso enigmatico, Daffodil posò sul bancone esattamente l'oggetto che desideravate."
  },
  AvgDialog_4884_Content_18 = {
    Text = "Trattata con Argento primordiale ad alta purezza, questa pellicola è in grado di catturare correttamente l'aspetto di un Risvegliatore. Estremamente preziosa. Il mio negozio ne ha solo un pezzo in magazzino."
  },
  AvgDialog_4884_Content_19 = {
    Text = "La pellicola speciale non doveva essere <Yellow:una nuova ricerca di Doll>? Dove l'hai trovata?"
  },
  AvgDialog_4884_Content_2 = {
    Text = "Questo posto è decisamente troppo affollato. Perché quella donna ha aperto bottega in un posto del genere?"
  },
  AvgDialog_4884_Content_20 = {
    Text = [[
Una Mercante che attraversa le Dimensioni ha i suoi canali speciali.
Non guardarmi con quegli occhi sospettosi... mi ferisci, sai.]]
  },
  AvgDialog_4884_Content_21 = {
    Text = "Allora? Se non vi serve, la rimetto via."
  },
  AvgDialog_4884_Content_22 = {
    Text = "Affare fatto. La prendiamo."
  },
  AvgDialog_4884_Content_23 = {
    Text = "Lily ti strinse la mano, i suoi occhi tradivano un accenno di inquietudine."
  },
  AvgDialog_4884_Content_24 = {
    Text = "Negozio di scambio… Dobbiamo dare qualcosa in cambio alla Signora."
  },
  AvgDialog_4884_Content_25 = {
    Text = "Oh, Lily ricorda ancora le regole del mio negozio."
  },
  AvgDialog_4884_Content_26 = {
    Text = "Non preoccupatevi, questa volta non chiedo molto... voglio vedere una \"storia\"."
  },
  AvgDialog_4884_Content_27 = {
    Text = "Una storia meravigliosa, completa e senza rimpianti.\nÈ questo che voglio in cambio."
  },
  AvgDialog_4884_Content_3 = {
    Text = "\"Se vuoi nascondere un sei di quadri, mischialo in un mazzo di carte.\""
  },
  AvgDialog_4884_Content_4 = {
    Text = [[
Casiah vi ha condotti tutti sul lato del grande magazzino e ha preso l'iniziativa di aprire la porta del negozio.
Una voluta di fumo viola ha trascinato tutti all'interno.]]
  },
  AvgDialog_4884_Content_5 = {
    Text = "Bentornati nel mio \"Negozio di Scambi,\" miei stimati ospiti, e anche..."
  },
  AvgDialog_4884_Content_6 = {
    Text = "E la mia adorabile \"impiegata.\"\nCom'è la vita a Mythag? Hai imparato qualche emozione autentica?"
  },
  AvgDialog_4884_Content_7 = {
    Text = "Grazie per la vostra generosità, Signora, ma davvero non c'è nulla da imparare da un topolino stridulo, un organismo unicellulare che non sa nulla, un'egocentrica violenta e un paio di barattoli chiusi ermeticamente."
  },
  AvgDialog_4884_Content_8 = {
    Text = "Chi stai chiamando stridulo?!"
  },
  AvgDialog_4884_Content_9 = {
    Text = "Barattolo chiuso ermeticamente… Stai parlando di me?"
  },
  AvgDialog_4885_Content_2 = {
    Text = "Fermo! Rilascia quella ragazza!"
  },
  AvgDialog_4885_Content_3 = {
    Text = "Oh? Potresti essere il famoso... <Blue:Detective G della Divisione Giardini della Polizia di Londinium>?"
  },
  AvgDialog_4885_Content_4 = {
    Text = "S-Sì, io sono il <Blue:Capo Hua del Dipartimento di Polizia di Londinium... mmph!>"
  },
  AvgDialog_4885_Content_5 = {
    Text = "Il titolo contorto fece mordere la lingua al detective, ma non intaccherà la sua determinazione a salvare i cittadini innocenti."
  },
  AvgDialog_4885_Content_6 = {
    Text = "La salverò dai tuoi piani malvagi! Affronta la giustizia, strega Houdini!"
  },
  AvgDialog_4886_Content_1 = {Text = "Ah...!"},
  AvgDialog_4886_Content_2 = {
    Text = "<Small:Si è rotta...>"
  },
  AvgDialog_4886_Content_3 = {
    Text = "Ancora, ancora! Anche Casiah si sta divertendo un mondo, vero!"
  },
  AvgDialog_4886_Content_4 = {
    Text = "Che maleducati! Vi faccio a pezzi! Mi assicurerò che non abbiate mai più un posto nel mondo del cinema!"
  },
  AvgDialog_4886_Content_5 = {
    Text = "Shh, shh! Smettetela di provocare la signorina Casiah."
  },
  AvgDialog_4886_Content_6 = {
    Text = "L'attenzione di tutti era catturata dalla Confusione della battaglia, e la sommessa esclamazione passò inosservata."
  },
  AvgDialog_4886_Content_7 = {
    Text = "Lily fece un respiro profondo e gridò con tutte le sue forze."
  },
  AvgDialog_4886_Content_8 = {
    Text = "Si è rotta... <BigShake:La macchina si è rotta!>"
  },
  AvgDialog_4887_Content_1 = {
    Text = "L'inserviente sottomise abilmente il paziente in preda alla frenesia, immobilizzandogli rapidamente gli arti con cinghie di cuoio.\nSolo dopo aver finito si accorse della presenza di un estraneo, e si grattò la testa con aria imbarazzata."
  },
  AvgDialog_4887_Content_10 = {
    Text = "Ci sono grandi quantità di D-melma invisibile — forse, la fonte della follia."
  },
  AvgDialog_4887_Content_2 = {
    Text = "Fate attenzione. I pazienti sono particolarmente instabili oggi. Non lasciate che vi facciano del male."
  },
  AvgDialog_4887_Content_3 = {
    Text = "Follia collettiva? Succede spesso?"
  },
  AvgDialog_4887_Content_4 = {
    Text = "Coloro che vengono abbandonati nell'ospedale hanno spiriti fragili come carta lasciata al sole per sette giorni e sette notti, che si frantumano alla minima brezza. Improvvise esplosioni di follia collettiva non sono nulla di insolito qui."
  },
  AvgDialog_4887_Content_5 = {
    Text = "Andiamo. Il responsabile dovrebbe essere su questo piano."
  },
  AvgDialog_4887_Content_6 = {
    Text = "Ehi! Attenzione!"
  },
  AvgDialog_4887_Content_7 = {
    Text = "Spintonasti improvvisamente l'inserviente, che barcollò indietro di un paio di passi e ti guardò con espressione perplessa."
  },
  AvgDialog_4887_Content_8 = {
    Text = "C'è un po' d'acqua; camminiamo lungo il bordo del corridoio."
  },
  AvgDialog_4887_Content_9 = {
    Text = "L'inserviente non fece troppe domande e evitò la direzione che avevi indicato. Solo tu tirasti segretamente un sospiro di sollievo."
  },
  AvgDialog_4888_Content_1 = {
    Text = [[
Squadra di Sicurezza, assistete la Sig.ra Ellie nel riportare i pazienti dal cortile nelle loro stanze.
Daisy, prepara gli oggetti di conforto e gli articoli da toilette dei pazienti.]]
  },
  AvgDialog_4888_Content_10 = {
    Text = "Grazie per avermi portato un'amica perduta da tempo da così lontano."
  },
  AvgDialog_4888_Content_11 = {
    Text = "Dire \"grazie\" è troppo formale. Andiamo prima a occuparci dell'incidente nel reparto."
  },
  AvgDialog_4888_Content_12 = {
    Text = "I medici fecero un cenno a Nymphaea e, dopo aver ricevuto il suo assenso, lasciarono l'ufficio uno alla volta."
  },
  AvgDialog_4888_Content_13 = {
    Text = "Sembra che tu te la sia cavata bene qui dopo l'Evento del Segugio infernale."
  },
  AvgDialog_4888_Content_14 = {
    Text = "Grazie a te e alla signorina Ramona, il sanatorio ha potuto funzionare senza intoppi."
  },
  AvgDialog_4888_Content_15 = {
    Text = "C'è qualcosa che ti ha portato qui così tardi nella notte?"
  },
  AvgDialog_4888_Content_16 = {
    Text = "Hai spiegato alla ragazza dal volto pallido delle riprese, della sceneggiatura e di Lily..."
  },
  AvgDialog_4888_Content_17 = {
    Text = [[
Capisco... Vuoi creare una storia?
Non so scrivere poesie o sceneggiature, ma ho letto molte storie.]]
  },
  AvgDialog_4888_Content_18 = {
    Text = "Nymphaea chiuse gli occhi e parlò dolcemente, come se stesse recitando."
  },
  AvgDialog_4888_Content_19 = {
    Text = "La cosa più importante è <Yellow:ascoltare>, giusto?\nAscolta la voce interiore, segui il flusso delle emozioni... Ti condurranno alla risposta."
  },
  AvgDialog_4888_Content_2 = {
    Text = "Sig. Jackson, per favore... aiuti a tagliare le patate nel curry. Non le sprechi."
  },
  AvgDialog_4888_Content_20 = {
    Text = "Lily ascolta e riflette, cercando di dare un senso alle parole di Nymphaea."
  },
  AvgDialog_4888_Content_21 = {
    Text = "Nel mezzo della conversazione, un lamento soffocato giunse dal piano di sotto. Lily, che era immersa nei suoi pensieri, si spaventò e urtò la gamba di Nymphaea."
  },
  AvgDialog_4888_Content_22 = {
    Text = "Sembra che stia soffrendo..."
  },
  AvgDialog_4888_Content_23 = {
    Text = [[
I pazienti qui subiscono peggioramenti improvvisi e imprevedibili delle loro condizioni, ma di solito si riprendono entro mezza giornata...
Mi scuso per il disturbo.]]
  },
  AvgDialog_4888_Content_24 = {
    Text = "Puoi contattare l'Università di Mythag per assistenza nelle indagini. Il Nobile Dexter dovrebbe aver lasciato i suoi recapiti."
  },
  AvgDialog_4888_Content_25 = {
    Text = "Conosco la ragione della mutazione, e temo che sia un problema che nemmeno Mythag può risolvere."
  },
  AvgDialog_4888_Content_26 = {
    Text = "Vado ad aiutare con la \"bonifica\". Vuoi unirti a me?"
  },
  AvgDialog_4888_Content_3 = {
    Text = "Qualcuno ha visto il Sig. Robert? Qualcuno è andato a cercarlo? Mi ricordo che è responsabile del secondo reparto stasera..."
  },
  AvgDialog_4888_Content_4 = {
    Text = "Sono qui, Signorina Nymphaea."
  },
  AvgDialog_4888_Content_5 = {
    Text = "Colei che organizza sistematicamente il lavoro medico è Nymphaea, che hai già incontrato in precedenza.\nVedendoti al sanatorio, il suo volto mostra un'espressione di sorpresa."
  },
  AvgDialog_4888_Content_6 = {
    Text = "Sei tu... e Lily."
  },
  AvgDialog_4888_Content_7 = {
    Text = "Sorella Nymphaea."
  },
  AvgDialog_4888_Content_8 = {
    Text = "Perché non avete detto prima che conoscevate la signorina Polonaise? Ho quasi pensato che fosse una truffatrice."
  },
  AvgDialog_4888_Content_9 = {
    Text = "Nymphaea ridacchiò sommessamente e prese la mano di Lily."
  },
  AvgDialog_4889_Content_1 = {
    Text = "Il finale perfetto"
  },
  AvgDialog_4889_Content_10 = {
    Text = "Visitò la mostra d'arte, andò allo zoo, prese la metropolitana e il treno. Navigarono persino lungo Il Fiume Isis, lanciandosi nel vasto oceano meridionale!"
  },
  AvgDialog_4889_Content_11 = {
    Text = "Dopo aver vissuto ogni sorta di avventure, le due iniziarono una vita pacifica e tranquilla... Tuttavia, la ragazza conservava ancora la sua curiosità e il desiderio per l'ignoto."
  },
  AvgDialog_4889_Content_12 = {
    Text = "La curiosità... È una cosa negativa?"
  },
  AvgDialog_4889_Content_13 = {
    Text = "No, no, no, è decisamente una cosa positiva. La curiosità è la forza motrice eterna che spinge la civiltà in avanti—"
  },
  AvgDialog_4889_Content_14 = {
    Text = "Sfortunatamente, questa volta, la ragazza si incuriosì per una misteriosa Zanna..."
  },
  AvgDialog_4889_Content_15 = {
    Text = "Uno sguardo significativo verso Casiah"
  },
  AvgDialog_4889_Content_16 = {
    Text = "Fai l'occhiolino a Casiah, facendo uscire la maga dal suo torpore dopo che le hai preso l'altoparlante."
  },
  AvgDialog_4889_Content_17 = {
    Text = "Perché devo fare di nuovo il grande signore dei demoni?"
  },
  AvgDialog_4889_Content_18 = {
    Text = "Per supportare il tuo lavoro—o semplicemente per fare uno scherzo—borbottò ma collaborò comunque per evocare nuovamente l'illusione magica."
  },
  AvgDialog_4889_Content_19 = {
    Text = "Il laboratorio magico fu illuminato da una luce inquietante e sinistra. Lo strano bagliore prosciugava la vitalità dal mondo dei vivi, facendo sentire come se ci si trovasse negli inferi."
  },
  AvgDialog_4889_Content_2 = {Text = "Sssss—!"},
  AvgDialog_4889_Content_20 = {
    Text = "Io sono Houdini, la Grande Maga dal mondo dei morti. Questa bella bambina è il mio oggetto di scena magico preferito. Coraggiosi avventurieri, avete il coraggio di sfidarmi?"
  },
  AvgDialog_4889_Content_21 = {
    Text = "Signorina Casiah...?"
  },
  AvgDialog_4889_Content_22 = {
    Text = "Houdini! Maestra Maga Houdini! Dovresti tremare di paura, perdere il senno!"
  },
  AvgDialog_4889_Content_23 = {
    Text = "Sotto il tuo e lo sguardo aspettante di Casiah, Lily deglutì meccanicamente un paio di volte—"
  },
  AvgDialog_4889_Content_24 = {
    Text = "Avanti, avanti..."
  },
  AvgDialog_4889_Content_25 = {
    Text = "Parla! Grida! Fammi sentire la paura dal profondo della tua anima!"
  },
  AvgDialog_4889_Content_26 = {
    Text = "<BigShake:Aiuto! Qualcuno, aiutatemi—Madre!>"
  },
  AvgDialog_4889_Content_3 = {
    Text = "Cos'è quel rumore?!"
  },
  AvgDialog_4889_Content_4 = {
    Text = "Lotan si mise istintivamente a protezione dei piccoli Risvegliatori, impugnando l'elsa della spada con cautela a due mani."
  },
  AvgDialog_4889_Content_5 = {
    Text = "Scusate, è la prima volta che uso questo altoparlante."
  },
  AvgDialog_4889_Content_6 = {
    Text = "Volete giocare ancora un po'?"
  },
  AvgDialog_4889_Content_7 = {
    Text = "Hai scosso la testa, premuto di nuovo l'interruttore dell'altoparlante e puntato la luce al centro del set."
  },
  AvgDialog_4889_Content_8 = {
    Text = "La coraggiosa ragazza e l'avventuriera tornarono in città. L'avventuriera trattò la ragazza come una figlia, condividendo con lei innumerevoli esperienze di vita—"
  },
  AvgDialog_4889_Content_9 = {
    Text = "Gli occhi di Lily si illuminarono all'improvviso. Li spalancò, mostrando un'espressione incredula."
  },
  AvgDialog_4890_Content_1 = {
    Text = "<Change>Non voglio... andarmene... da casa..."
  },
  AvgDialog_4890_Content_2 = {
    Text = "<Change>La morte... no..."
  },
  AvgDialog_4890_Content_3 = {
    Text = "Un'emozione opprimente ti afferra le caviglie, trascinandoti in un abisso invisibile, rendendo persino il respiro difficile."
  },
  AvgDialog_4890_Content_4 = {
    Text = "Lily sente un peso sul petto, e la fa sentire terribilmente..."
  },
  AvgDialog_4890_Content_5 = {
    Text = "Mi dispiace avervi messo a disagio."
  },
  AvgDialog_4890_Content_6 = {
    Text = "Custode, per favore aiutami a sconfiggerla."
  },
  AvgDialog_4891_Content_1 = {
    Text = "La giovane poetessa scosse la testa, il tono afflitto e desolato. Senza rendersene conto, si era ritratta dietro la lettera, rivelando una traccia di tristezza."
  },
  AvgDialog_4891_Content_2 = {
    Text = "Avvolta nelle ombre della tristezza, la mia poesia e la mia ispirazione... potrebbero non essere di alcuna utilità per i Custodi e Lily."
  },
  AvgDialog_4891_Content_3 = {
    Text = "Un'ombra... di tristezza?"
  },
  AvgDialog_4891_Content_4 = {
    Text = "Di fronte all'espressione perplessa di Lily, Horla emise un sospiro appena percettibile."
  },
  AvgDialog_4891_Content_5 = {
    Text = "Se possibile, permettetemi di mostrarvi..."
  },
  AvgDialog_4891_Content_6 = {
    Text = "Horla spinse la porta, non tenendo più il mondo esterno a distanza, mentre un'aria densa e stagnante invadeva la stanza."
  },
  AvgDialog_4891_Content_7 = {
    Text = "Cos'è \"l'ombra della tristezza\"?"
  },
  AvgDialog_4892_Content_1 = {
    Text = "<Change>La nuova vicina in fondo alla strada... talentuosa..."
  },
  AvgDialog_4892_Content_2 = {
    Text = "<Change>Il fiore più bello... Lei..."
  },
  AvgDialog_4892_Content_3 = {
    Text = "<Change>Il mio fiore... una poesia..."
  },
  AvgDialog_4892_Content_4 = {
    Text = "<Gray:La città di Renny un tempo subì una grave Dissoluzione Catastrofica del Mondo; forse le voci dei Residenti perduti aleggiano ancora qui...>"
  },
  AvgDialog_4893_Content_1 = {
    Text = "<Change>Sono... sono malata..."
  },
  AvgDialog_4893_Content_2 = {
    Text = "Chi va là?!"
  },
  AvgDialog_4893_Content_3 = {
    Text = "Non c'era nulla dietro, solo il vento che portava un pesante suono lugubre."
  },
  AvgDialog_4893_Content_4 = {
    Text = "Avete sentito qualcosa?"
  },
  AvgDialog_4893_Content_5 = {
    Text = "No... forse un Fantasma."
  },
  AvgDialog_4894_Content_1 = {
    Text = "Inutili sciocchi! Incompetenti! Avete fatto scappare tutte le comparse di Casiah!"
  },
  AvgDialog_4894_Content_10 = {
    Text = "All'ultimo istante, Ogier brandì la sua lancia e disperse il coniglio impazzito, riducendolo a un flebile alone di ombra fantasmatica."
  },
  AvgDialog_4894_Content_11 = {
    Text = "Odioso! Odioso! Chi non collabora non ha il diritto di restare sul set della regista Casiah!"
  },
  AvgDialog_4894_Content_12 = {
    Text = "A quanto pare non smetterà con la sua \"mimica emotiva\" finché non gliele suoniamo un po'.\nQuesta volta non puoi chiamarmi \"maniaca dei combattimenti\", vero?"
  },
  AvgDialog_4894_Content_13 = {
    Text = "Dobbiamo davvero smetterla di lasciarle leggere tutte quelle rivistacce..."
  },
  AvgDialog_4894_Content_2 = {
    Text = "Comparse? Aurita sa, Aurita sa!"
  },
  AvgDialog_4894_Content_3 = {
    Text = "Aurita da sola vale un'intera folla di attori!"
  },
  AvgDialog_4894_Content_4 = {
    Text = "Mocciosa, tu davvero sei—"
  },
  AvgDialog_4894_Content_5 = {
    Text = "La \"regista\" agitò furiosamente la sua bacchetta Magica. Carte da gioco di scena volarono in ogni direzione, lasciando graffi vistosi su numerosi oggetti."
  },
  AvgDialog_4894_Content_6 = {Text = "Iiih—!"},
  AvgDialog_4894_Content_7 = {
    Text = "I conigli Fantasma si schiantarono anche contro gli elementi scenografici, facendoli volare da tutte le parti. Infine, puntarono Aurita come bersaglio e caricarono dritti verso di lei."
  },
  AvgDialog_4894_Content_8 = {Text = "Attento!"},
  AvgDialog_4895_Content_1 = {
    Text = "Ciò che Manca di Più"
  },
  AvgDialog_4895_Content_10 = {
    Text = "Una volta aperta la stanza, il cane dimensionale intrappolato all'interno romperà il sigillo temporale.\nLo stato attuale di Francis all'interno è completamente sconosciuto"
  },
  AvgDialog_4895_Content_11 = {
    Text = "Non puoi fare alcuna promessa a Lily, né desideri fare promesse che non possono essere mantenute."
  },
  AvgDialog_4895_Content_2 = {
    Text = "È passato un po' di tempo dalla tua ultima visita. Sebbene il paesaggio sia rimasto invariato, l'aria non porta più un'aura di tensione e trepidazione."
  },
  AvgDialog_4895_Content_3 = {
    Text = "Questo luogo, un tempo avvolto nell'ombra dei \"Segugi infernali\", sembra aver ritrovato la vera pace."
  },
  AvgDialog_4895_Content_4 = {
    Text = "Lily, stai bene?"
  },
  AvgDialog_4895_Content_5 = {
    Text = "Sebbene Lily sia di solito una bambina silenziosa, non ha detto una parola da quando è entrata nella città di Lai."
  },
  AvgDialog_4895_Content_6 = {
    Text = "Senti un'ondata di disagio nel petto. Ansia, gioia, paura... Un miscuglio di emozioni che scorre attraverso i tuoi nervi tramite il legame."
  },
  AvgDialog_4895_Content_7 = {
    Text = "Padrone... Lily riuscirà a vedere la sua mamma questa volta?"
  },
  AvgDialog_4895_Content_8 = {
    Text = "Anche se Lily non è cresciuta... siamo stati lontani per così tanto tempo. La riconoscerà ancora?"
  },
  AvgDialog_4895_Content_9 = {
    Text = "Guardando gli occhi di Lily, che brillavano debolmente di aspettativa, le accarezzasti dolcemente i capelli, morbidi come seta, e la conducesti all'altra estremità del ponte ferroviario—"
  },
  AvgDialog_4896_Content_1 = {
    Text = "Questo tizio ha finalmente smesso di essere rigido come un pezzo di legno."
  },
  AvgDialog_4896_Content_2 = {
    Text = "Il maestro non è mai stato di legno, {Male=lui,Female=lei} è solo, solo un po'..."
  },
  AvgDialog_4896_Content_3 = {
    Text = "Posato? Maturo? O intendi dire noioso?"
  },
  AvgDialog_4896_Content_4 = {
    Text = "Non intendevo quello!"
  },
  AvgDialog_4896_Content_5 = {
    Text = "Vedendo il volto di Ogier arrossire per poche parole, Lotan rise di gusto e spinse improvvisamente il giovane cavaliere sotto i riflettori."
  },
  AvgDialog_4896_Content_6 = {
    Text = "Unisciti a loro adesso; questa videocassetta non sarà completa senza di te."
  },
  AvgDialog_4897_Content_1 = {
    Text = "Avete insultato il copione Magico di Casiah!! Tutti quanti voi... <Big:Ascoltate la regista e collaborate con me come bravi attorini!>"
  },
  AvgDialog_4897_Content_2 = {
    Text = "<Yellow:\"La guida di Daffodil per andare d'accordo con Casiah\"> riporta nella prima pagina che Casiah soffre di <Yellow:distacco emotivo>, e tutte le sue espressioni emotive sono solo imitazioni di quelle altrui."
  },
  AvgDialog_4897_Content_3 = {
    Text = "Se è così, da dove viene tutta questa furia?"
  },
  AvgDialog_4897_Content_4 = {
    Text = "<Big:Provate un po' — il potere della <Red:Possanza di Andy Johnson>!>"
  },
  AvgDialog_4897_Content_5 = {
    Text = "Andy Johnson? Quel nome mi suona così familiare. Dove l'ho già sentito..."
  },
  AvgDialog_4897_Content_6 = {
    Text = "Conosco quel nome!! È un regista famoso di Oakwood ne La Repubblica di Aglo!"
  },
  AvgDialog_4897_Content_7 = {
    Text = "Ho sentito le signore al mercato chiacchierare di lui. Dicevano che l'anno scorso ha picchiato il suo assistente fotografo così forte che il poveretto è finito in ospedale!!"
  },
  AvgDialog_4897_Content_8 = {
    Text = "Beh, almeno ora sappiamo chi sta imitando..."
  },
  AvgDialog_4898_Content_1 = {
    Text = "Il fiore più bello"
  },
  AvgDialog_4898_Content_10 = {
    Text = "Lily, tu... non sai leggere?"
  },
  AvgDialog_4898_Content_11 = {
    Text = "Lily... Io..."
  },
  AvgDialog_4898_Content_12 = {
    Text = "Lily abbassò la testa, esitò per un momento e infine annuì, con il volto pieno di inquietudine."
  },
  AvgDialog_4898_Content_13 = {
    Text = "A scrivere, me lo ha insegnato la Mamma. Ma... Lily non se lo ricorda più.\nStorie e copioni, Lily non riesce a scriverli."
  },
  AvgDialog_4898_Content_14 = {
    Text = [[
Non aver paura; non ti sto mettendo fretta.
Facciamolo insieme.]]
  },
  AvgDialog_4898_Content_15 = {
    Text = "Lily, puoi dirmi di cosa parla questa storia?"
  },
  AvgDialog_4898_Content_16 = {
    Text = "La storia della Mamma, di Koom e di Lily."
  },
  AvgDialog_4898_Content_17 = {
    Text = "Con quale evento inizia la storia? Hmm... In altre parole, da quando vuole iniziare a raccontarla Lily?"
  },
  AvgDialog_4898_Content_18 = {Text = "..."},
  AvgDialog_4898_Content_19 = {
    Text = "Non lo so..."
  },
  AvgDialog_4898_Content_2 = {
    Text = "Lily era seduta alla toeletta, con i piedi penzoloni sopra il pavimento, che dondolavano avanti e indietro con impegno."
  },
  AvgDialog_4898_Content_20 = {
    Text = "Custode, vieni un momento con me."
  },
  AvgDialog_4898_Content_21 = {
    Text = "Lotan ti trascinò al bordo del set e ti guardò con disapprovazione."
  },
  AvgDialog_4898_Content_22 = {
    Text = "Il passato di quella bambina non vale la pena di essere rievocato. Farle scrivere una storia su quello non ti sembra inappropriato?"
  },
  AvgDialog_4898_Content_23 = {
    Text = "Siete stati seduti qui mezza giornata senza scrivere nulla. Se vuoi il mio parere, perché non porti Lily a fare una passeggiata e cerchi qualche altra ispirazione?"
  },
  AvgDialog_4898_Content_24 = {
    Text = "Le orecchie acute di Lily colsero il suo nome. Saltò giù dalla sedia con la penna in mano e sgattaiolò al tuo fianco come un piccolo animale."
  },
  AvgDialog_4898_Content_25 = {
    Text = "Lotan arruffò i capelli della ragazzina e ti porse il pastello."
  },
  AvgDialog_4898_Content_26 = {
    Text = "Uscite a godervi il panorama, falla chiacchierare con qualcuno che sa scrivere. Quanto a te..."
  },
  AvgDialog_4898_Content_27 = {
    Text = "Seguila e annota le sue ispirazioni."
  },
  AvgDialog_4898_Content_28 = {
    Text = "Maestro, dove andiamo?"
  },
  AvgDialog_4898_Content_29 = {
    Text = "Quando si parla di \"qualcuno che sa scrivere\"... dovresti davvero andare a incontrare quella persona."
  },
  AvgDialog_4898_Content_3 = {
    Text = "Storie... storie..."
  },
  AvgDialog_4898_Content_30 = {
    Text = "\"Quella persona\"?"
  },
  AvgDialog_4898_Content_31 = {
    Text = "Una sorella maggiore di grande talento. Lotan ha organizzato un incontro con lei al capolinea dell'autobus."
  },
  AvgDialog_4898_Content_32 = {
    Text = "Lily annuisce con innocenza, tenendoti per mano e restando in silenzio."
  },
  AvgDialog_4898_Content_33 = {
    Text = "È la seconda volta che prende la metropolitana. A differenza dell'entusiasmo e della curiosità della prima volta, questa volta ti resta vicina, ubbidiente ma cauta, proprio come un piccolo animale aggrappato all'abbraccio della madre."
  },
  AvgDialog_4898_Content_4 = {
    Text = "Mormorava tenendo la penna, la cui punta scivolava producendo un fruscio sulla carta."
  },
  AvgDialog_4898_Content_5 = {
    Text = "Con un'espressione seria e solenne, i tratti sono decisi e vigorosi, penetrano la carta—"
  },
  AvgDialog_4898_Content_6 = {
    Text = "Ma ciò che appare sulla carta non è testo; è semplicemente un disegnino infantile e ingenuo."
  },
  AvgDialog_4898_Content_7 = {
    Text = "Questi sono... Koom e Francis?"
  },
  AvgDialog_4898_Content_8 = {Text = "Ah...!"},
  AvgDialog_4898_Content_9 = {
    Text = "M-Maestro..."
  },
  AvgDialog_4899_Content_1 = {
    Text = "Tu e Lily bussaste a una porta anonima all'angolo della strada."
  },
  AvgDialog_4899_Content_10 = {
    Text = "No, no, la Sig.na Horla ha frainteso."
  },
  AvgDialog_4899_Content_11 = {
    Text = "Siete venuti a trovarmi per il copione, non è vero?"
  },
  AvgDialog_4899_Content_12 = {
    Text = "Sì, ma non esattamente."
  },
  AvgDialog_4899_Content_13 = {
    Text = "Abbassi lo sguardo su Lily, che è quasi appesa alla tua gamba, e la spingi delicatamente verso Horla."
  },
  AvgDialog_4899_Content_14 = {
    Text = "<Italic:Una vita inaspettata, che sboccia oltre i confini del tempo...>"
  },
  AvgDialog_4899_Content_15 = {
    Text = "Ciao, Lily."
  },
  AvgDialog_4899_Content_16 = {
    Text = "Ciao, un saluto a te!"
  },
  AvgDialog_4899_Content_17 = {
    Text = "Vorremmo chiederti un consiglio su come creare storie."
  },
  AvgDialog_4899_Content_2 = {
    Text = "Benvenuti da lontano. Mi scuso per non avervi accolto prima..."
  },
  AvgDialog_4899_Content_3 = {
    Text = "Era una fragranza di rose con un tocco di rugiada mattutina, che filtrava dalla fessura della porta aperta, fluendo segretamente e senza sosta."
  },
  AvgDialog_4899_Content_4 = {
    Text = "È passato molto tempo, <Blue:Sig.ra Horla>."
  },
  AvgDialog_4899_Content_5 = {
    Text = "Buongiorno, Custode."
  },
  AvgDialog_4899_Content_6 = {
    Text = "Chi è questa piccola ospite...?"
  },
  AvgDialog_4899_Content_7 = {
    Text = "Hai spiegato alla poetessa delle riprese, del copione e di Lily..."
  },
  AvgDialog_4899_Content_8 = {
    Text = "Capisco. Per testare la cinepresa modificata dalla Sig.na Doll, dovete girare un film..."
  },
  AvgDialog_4899_Content_9 = {
    Text = "Ma forse ricordate, sono solo un'insignificante poetessa... Quando si tratta di scrivere sceneggiature cinematografiche, sono ben lontana dall'essere \"qualificata\"."
  },
  AvgDialog_4900_Content_1 = {
    Text = "Il grande miraggio"
  },
  AvgDialog_4900_Content_10 = {
    Text = "Cosa succede altrimenti?"
  },
  AvgDialog_4900_Content_11 = {
    Text = "Vi ritroverete pieni di lividi per esservi schiantati contro il vero set nascosto nell'illusione!"
  },
  AvgDialog_4900_Content_12 = {
    Text = "Qualcuno di voi ha visto la donna che è medico e psicologa dell'Università di Mythag?"
  },
  AvgDialog_4900_Content_13 = {
    Text = "Quello è l'insidioso, astuto e malvagio Re dei Demoni. Si dice che chi va da lei ferito finisca per essere portato via in barella."
  },
  AvgDialog_4900_Content_14 = {
    Text = "Q-Questa parte non è stata registrata, vero?"
  },
  AvgDialog_4900_Content_15 = {
    Text = "Ogier ti guarda nervosamente, tenendo la telecamera, e si rilassa solo dopo aver ricevuto un cenno di conferma."
  },
  AvgDialog_4900_Content_16 = {
    Text = "La signorina Sylvia è sempre gentile con gli studenti che si feriscono accidentalmente..."
  },
  AvgDialog_4900_Content_17 = {
    Text = "Dato che sono tutti pronti, iniziamo le riprese."
  },
  AvgDialog_4900_Content_18 = {
    Text = "Evviva—Si gira~Si gira~"
  },
  AvgDialog_4900_Content_19 = {
    Text = "Aurita, vieni qui! Non dobbiamo essere sul palco per questa scena. Aspettiamo fuori campo prima—"
  },
  AvgDialog_4900_Content_2 = {
    Text = "Giovani attori, siete pronti!"
  },
  AvgDialog_4900_Content_20 = {
    Text = "I Risvegliatori trovarono ciascuno un posto dove nascondersi fuori campo. Hai dato un'ultima occhiata al \"copione\", su cui erano scritte solo poche righe, e ti sei diretto al punto prestabilito."
  },
  AvgDialog_4900_Content_3 = {
    Text = "Custode, sei pronto?!"
  },
  AvgDialog_4900_Content_4 = {
    Text = "Non battete le palpebre, trattenete il respiro... anzi, potete respirare adesso."
  },
  AvgDialog_4900_Content_5 = {
    Text = "La magia illusoria di Casiah vi lascerà sicuramente senza fiato—!"
  },
  AvgDialog_4900_Content_6 = {
    Text = "Lo scenario si distorce e sfoca. Dopo un istante di frammentazione, i frammenti si ricompongono in una realtà che vi è estremamente familiare."
  },
  AvgDialog_4900_Content_7 = {
    Text = "Che... Che tipo di magia è questa?!"
  },
  AvgDialog_4900_Content_8 = {
    Text = "Squeak, squeak squeak!"
  },
  AvgDialog_4900_Content_9 = {
    Text = "Tieni d'occhio il tuo compagno ladro. Le illusioni di Casiah sono solo trucchi... Fate attenzione a non entrarci davvero dentro, altrimenti..."
  },
  AvgDialog_4901_Content_1 = {
    Text = "Generosità del Mercante"
  },
  AvgDialog_4901_Content_10 = {
    Text = "La scatola nera contenente la pellicola è rotolata di lato, e la luce vi penetra attraverso una crepa che si è aperta con l'urto."
  },
  AvgDialog_4901_Content_11 = {
    Text = "Doll ci ha avvertiti espressamente che la pellicola non deve mai essere esposta alla luce... Questo è un guaio!"
  },
  AvgDialog_4901_Content_12 = {
    Text = "<Shake:L'intera missione di questa volta era testare la fotocamera modificata da Doll!>"
  },
  AvgDialog_4901_Content_13 = {
    Text = "E che sarà mai? Basta andare a comprare un altro rullino al grande magazzino."
  },
  AvgDialog_4901_Content_14 = {
    Text = "Il tuo portafoglio non sarà più così sottile come prima, vero, {Male=Mr.,Female=Miss} \"Ashe\"?"
  },
  AvgDialog_4901_Content_15 = {
    Text = "Dai un colpetto al tuo povero portafoglio, contando mentalmente i giorni che mancano al prossimo compenso per le indagini..."
  },
  AvgDialog_4901_Content_16 = {
    Text = "Hai un buco in tasca o cosa? Che ne dici se vado a \"procurare\" un rullino di questa pellicola-qualcosa?"
  },
  AvgDialog_4901_Content_17 = {
    Text = "Per favore, lascia alla legge almeno un po' di dignità."
  },
  AvgDialog_4901_Content_18 = {
    Text = "Andiamo subito al grande magazzino."
  },
  AvgDialog_4901_Content_2 = {Text = "Cosa?!"},
  AvgDialog_4901_Content_3 = {
    Text = "Tch, che seccatura."
  },
  AvgDialog_4901_Content_4 = {
    Text = "Lotan si disimpegnò dal combattimento, stese Casiah con un colpo di rovescio del pomolo della spada, e si avvicinò a Lily mentre rinfoderà agilmente la lama."
  },
  AvgDialog_4901_Content_5 = {
    Text = "La macchina era rimasta coinvolta nel fuoco incrociato durante la battaglia ed era crollata tra i rottami degli oggetti di scena."
  },
  AvgDialog_4901_Content_6 = {
    Text = "Cosa cosa? Cos'è successo alla macchina? È stanca?"
  },
  AvgDialog_4901_Content_7 = {
    Text = "Qualcosa è caduto da dentro! Si è rotta?"
  },
  AvgDialog_4901_Content_8 = {
    Text = "Raddrizzi la macchina. La fotocamera non sembra avere altri danni: solo un componente a forma di rotella si è staccato."
  },
  AvgDialog_4901_Content_9 = {
    Text = "Oh no! La pellicola!"
  },
  AvgDialog_4902_Content_1 = {
    Text = "Fermi, fermi! Non correte!"
  },
  AvgDialog_4902_Content_10 = {
    Text = "Chi siete venuti a trovare? L'orario di visita dell'ospedale è finito da un pezzo!"
  },
  AvgDialog_4902_Content_11 = {
    Text = "<Small:La sicurezza fornita dalla Fondazione Dexter è inutile...>\nLasciate perdere, non potete restare qui. Farò venire la sicurezza per accompagnarvi fuori."
  },
  AvgDialog_4902_Content_12 = {
    Text = "Dopo l'incidente del Segugio infernale, la famiglia Dexter ha generosamente donato all'Ospedale di Lai. In un certo senso, è diventato proprietà privata del professore."
  },
  AvgDialog_4902_Content_13 = {
    Text = "Sono uno studente del Nobile Dexter"
  },
  AvgDialog_4902_Content_14 = {
    Text = "Sono uno studente del Nobile a Londinium. Di passaggio a Lai durante i miei viaggi, spero di poter trascorrere una notte all'ospedale."
  },
  AvgDialog_4902_Content_15 = {
    Text = "Uno studente del Nobile? Venuto fin da Londinium?"
  },
  AvgDialog_4902_Content_16 = {
    Text = [[
Anche se conosceste davvero il Nobile, nella nostra situazione attuale, come potremmo mai ospitare qualcuno per la notte!
Che seccatura... Va bene, vi porto dal responsabile.]]
  },
  AvgDialog_4902_Content_17 = {
    Text = "Sono Ramona Dexter"
  },
  AvgDialog_4902_Content_18 = {Text = "?!"},
  AvgDialog_4902_Content_19 = {
    Text = "Premesti la spalla di Lily, facendole segno di non farsi prendere dal panico."
  },
  AvgDialog_4902_Content_2 = {
    Text = "I pazienti del terzo piano stanno facendo una battaglia d'acqua in cortile, quelli del primo piano stanno giocando con patate e curry in cucina, e quelli del secondo piano stanno ululando—Oh mio Dio!!"
  },
  AvgDialog_4902_Content_20 = {
    Text = "Sono l'unica erede della famiglia Dexter, ed è mio legittimo dovere ispezionare le attività della nostra famiglia."
  },
  AvgDialog_4902_Content_21 = {
    Text = "...Una volta ho visto la signorina Dexter a una cena — una signora con splendidi capelli argentati."
  },
  AvgDialog_4902_Content_22 = {
    Text = "Voi... lasciamo perdere, lasciamo perdere.\n<Small:Robert, mantieni la calma. Di pazzi ne hai visti abbastanza qui; uno in più non farà differenza.>"
  },
  AvgDialog_4902_Content_23 = {
    Text = "Che si tratti di una visita o di un ricovero, è necessaria l'approvazione del responsabile.\nVi porto da lei."
  },
  AvgDialog_4902_Content_3 = {
    Text = "Mi licenzio! Me ne vado!!"
  },
  AvgDialog_4902_Content_4 = {
    Text = "Gli allarmi suonano, le luci rosse lampeggiano. L'Ospedale di Lai è nel caos dentro e fuori. I pazienti sono fuori controllo e gli inservienti disperati li rincorrono."
  },
  AvgDialog_4902_Content_5 = {Text = "...!"},
  AvgDialog_4902_Content_6 = {
    Text = "L'ospedale... Mamma!"
  },
  AvgDialog_4902_Content_7 = {
    Text = "Lily, non avere fretta, mantieni la calma."
  },
  AvgDialog_4902_Content_8 = {
    Text = "Sebbene il personale medico sembrasse sopraffatto, le loro azioni metodiche rivelavano che stavano semplicemente sfogando lamentele sul lavoro frenetico e tedioso."
  },
  AvgDialog_4902_Content_9 = {
    Text = "Salve, posso chiedere se c'è qualche problema all'ospedale?"
  },
  AvgDialog_4903_Content_1 = {
    Text = "Cosa sta succedendo con questi Mutanti?"
  },
  AvgDialog_4903_Content_10 = {
    Text = "Quando è sparita?!"
  },
  AvgDialog_4903_Content_11 = {
    Text = "Non preoccuparti, questa è la casa di Lily. Non sarà in pericolo.\nElimiamo questi mutanti mentre la cerchiamo."
  },
  AvgDialog_4903_Content_2 = {
    Text = "Ricordi il guerriero che tu e la signorina Lotan avete sconfitto?"
  },
  AvgDialog_4903_Content_3 = {
    Text = "Dammela... a me!"
  },
  AvgDialog_4903_Content_4 = {
    Text = "Helot... La liberatrice originale dei Tilos, lo spirito vendicativo."
  },
  AvgDialog_4903_Content_5 = {
    Text = "Esatto.\nSecondo i desideri del Preside Oswald, il Legame della signorina Helot è ogni paziente del sanatorio."
  },
  AvgDialog_4903_Content_6 = {
    Text = "Le sue azioni all'esterno hanno provocato anomalie al sanatorio, che di solito tornano alla normalità entro mattina...\nData la confusione di questa notte, chiederti di rintracciarla è davvero un'impresa ardua."
  },
  AvgDialog_4903_Content_7 = {
    Text = "Esiste una debole connessione tra Risvegliatori della stessa origine. Lily potrebbe percepire dove si trova Helot. Se la situazione al sanatorio dovesse peggiorare, ti prego di contattarci immediatamente."
  },
  AvgDialog_4903_Content_8 = {
    Text = "Grazie per la tua gentilezza. Lo farò... Eh?"
  },
  AvgDialog_4903_Content_9 = {Text = "Lily?"},
  AvgDialog_4904_Content_1 = {
    Text = "El@1...@4...!"
  },
  AvgDialog_4904_Content_2 = {
    Text = "Il paziente emise un grido di dolore dal letto, bruscamente interrotto, come se il mondo si rifiutasse di lasciarlo emettere un suono."
  },
  AvgDialog_4904_Content_3 = {
    Text = "Shh, shh... Ascolta il suono del mare che scorre..."
  },
  AvgDialog_4904_Content_4 = {
    Text = "Nymphaea consolò dolcemente il paziente, correnti invisibili lo avvolsero. Presto, si zittì, accasciandosi pacificamente tra le braccia di Nymphaea."
  },
  AvgDialog_4904_Content_5 = {
    Text = "Quello è..."
  },
  AvgDialog_4904_Content_6 = {
    Text = "Nymphaea fece un gesto di silenzio, rimboccò la coperta del paziente e poi ti condusse nel corridoio."
  },
  AvgDialog_4904_Content_7 = {
    Text = "Non preoccuparti, è solo una traccia di tossina oceanica. Il tuo corpo la metabolizzerà durante il sonno."
  },
  AvgDialog_4904_Content_8 = {
    Text = "Continua ad avanzare lungo questo corridoio. Lily potrebbe trovarsi più in profondità nel sanatorio."
  },
  AvgDialog_4904_Content_9 = {
    Text = "Guardi il passaggio familiare e profondo e annuisci in segno di assenso."
  },
  AvgDialog_4905_Content_1 = {
    Text = "Andy: Potenza di Johnson"
  },
  AvgDialog_4905_Content_10 = {
    Text = "Passi leggeri giunsero da un angolo del set. Lotan inarcò un sopracciglio verso Aurita, che capì immediatamente e diresse le luci verso quell'angolo."
  },
  AvgDialog_4905_Content_11 = {
    Text = "La luce intensa fece socchiudere involontariamente gli occhi alla ragazza. Camminò a piedi nudi fino al centro del set, rischiando di urtare più volte gli oggetti di scena ammucchiati alla rinfusa."
  },
  AvgDialog_4905_Content_12 = {
    Text = "— Il \"Segugio infernale\"!"
  },
  AvgDialog_4905_Content_13 = {
    Text = "Koo… Awoo…"
  },
  AvgDialog_4905_Content_14 = {
    Text = "Artigli più affilati dei migliori coltelli da portata di un grande magazzino, occhi più luminosi dei riflettori di una torre di sorveglianza. Senza volto, si aggira negli angoli della città, cercando vittime per un sacrificio malvagio…"
  },
  AvgDialog_4905_Content_15 = {
    Text = "No… non è così…"
  },
  AvgDialog_4905_Content_16 = {
    Text = "Koum… non è così…"
  },
  AvgDialog_4905_Content_17 = {
    Text = "*Tosse*, *tosse tosse*!"
  },
  AvgDialog_4905_Content_18 = {
    Text = "Ad ogni modo, cercando vittime per un sacrificio malvagio…"
  },
  AvgDialog_4905_Content_19 = {
    Text = "Ma che razza di copione terribile è questo? Londinium non è così pericol— *tosse*."
  },
  AvgDialog_4905_Content_2 = {
    Text = "Molto, molto tempo fa, un'alluvione catastrofica colpì la città."
  },
  AvgDialog_4905_Content_20 = {
    Text = "Londinium sarà anche pericolosa, ma non ci sono Segugi infernali che corrono per le strade!"
  },
  AvgDialog_4905_Content_21 = {
    Text = "Jenkin, il copione della signorina Casiah è solo una storia…"
  },
  AvgDialog_4905_Content_22 = {
    Text = "Anche una storia non dovrebbe essere scritta con tanta superficialità! Ve l'avevo detto che non avremmo dovuto affidare qualcosa di così importante come la sceneggiatura a un'estranea."
  },
  AvgDialog_4905_Content_23 = {
    Text = "E anche tu, Custode. Non hai sofferto abbastanza per mano di quella madama o come si chiama? Come puoi fidarti così di qualcuno che lei ha piazzato nella scuola?"
  },
  AvgDialog_4905_Content_24 = {Text = "Squeak!"},
  AvgDialog_4905_Content_25 = {
    Text = "Va bene, va bene, calmatevi, calmatevi tutti un attimo."
  },
  AvgDialog_4905_Content_26 = {
    Text = "Lady Daffodil ha stretto un accordo con i vertici della scuola. Casiah è ora un'ospite che risiede temporaneamente a Mythag."
  },
  AvgDialog_4905_Content_27 = {
    Text = "Il topolino ha ragione. La storia del Segugio infernale è abbastanza affascinante, purché venga raccontata così come è realmente accaduta. Inoltre..."
  },
  AvgDialog_4905_Content_28 = {
    Text = "Lotan si interruppe, lanciando un'occhiata a Lily. La Ragazza era ancora in piedi sotto il riflettore, il capo leggermente chino, rendendo impossibile leggere la Sua Espressione."
  },
  AvgDialog_4905_Content_29 = {
    Text = "Mostrate un po' di riguardo per i sentimenti delle persone coinvolte, signorina Maga."
  },
  AvgDialog_4905_Content_3 = {
    Text = "Le strade furono sommerse, le torri abbattute. Dalle persone agli averi, l'intera città di Londinium subì un completo e radicale \"Grande Rimescolamento\"!"
  },
  AvgDialog_4905_Content_30 = {
    Text = "Mmph... Mmmmph!"
  },
  AvgDialog_4905_Content_31 = {
    Text = "Le ombre si riversarono sul terreno. I fili lungo la tesa del Cilindro si spezzarono uno dopo l'altro, squarciando una fenditura fluorescente che somigliava esattamente al ghigno beffardo di un criminale."
  },
  AvgDialog_4905_Content_32 = {
    Text = "Un bastone fu lanciato fuori dallo squarcio, poi una mano strisciò fuori e, infine, una Maiden."
  },
  AvgDialog_4905_Content_33 = {
    Text = "La maga sembrava contrariata. Si rialzò da terra, si spolverò di dosso la polvere, poi recuperò il suo cilindro e se lo rimise in testa."
  },
  AvgDialog_4905_Content_34 = {
    Text = "Avanti e indietro, avanti e indietro... <Big:Voi non avete alcun rispetto per l'arte dello spettacolo!>"
  },
  AvgDialog_4905_Content_35 = {
    Text = "In un angolo appena percettibile, la \"Rabbia\" di Casiah aprì lo Spazio Ultra, e un familiare fruscio si agitò nell'oscurità..."
  },
  AvgDialog_4905_Content_36 = {
    Text = "Questa gita fuori dalla scuola doveva solo servire a testare la nuova invenzione di Doll... Com'è possibile che siamo di nuovo al punto di dover combattere?"
  },
  AvgDialog_4905_Content_37 = {
    Text = "Parlare non servirà a nulla. Datti una regolata."
  },
  AvgDialog_4905_Content_4 = {
    Text = "Cos'è il \"Grande Rimescolamento\"?"
  },
  AvgDialog_4905_Content_5 = {
    Text = "Shh, te lo spiego dopo che questa scena sarà girata."
  },
  AvgDialog_4905_Content_6 = {Text = "..."},
  AvgDialog_4905_Content_7 = {
    Text = "Dopo che le acque si ritirarono, il tumulto si levò ancora una volta lungo le rive del Fiume Aethis! La sventura si abbatte su questa città sfortunata ancora una volta!"
  },
  AvgDialog_4905_Content_8 = {
    Text = "Una fitta nebbia si diffonde sulla superficie del Fiume Aethis, così densa che non si riesce a vedere la propria mano davanti al viso, né il cielo sopra!\nE in questa nebbia, qualcosa si nasconde, in attesa di colpire…"
  },
  AvgDialog_4905_Content_9 = {
    Text = "Non è altri che la creatura dell'antica leggenda, \"nata da Echidna come madre e Tifone come padre, con tre teste, <Yellow:e coloro che vengono cacciati tre volte da essa avranno le loro anime consegnate agli inferi>\" —"
  },
  AvgDialog_4906_Content_1 = {
    Text = "Cercatore di Storie"
  },
  AvgDialog_4906_Content_10 = {
    Text = "Che tipo di storia racconteremo? Avete qualche idea, mio sovrano?"
  },
  AvgDialog_4906_Content_11 = {Text = "Ugh..."},
  AvgDialog_4906_Content_12 = {
    Text = "Restare qui impalati a fissare il vuoto non servirà a nulla. Torniamo al luogo dell'evento e riflettiamoci strada facendo."
  },
  AvgDialog_4906_Content_2 = {
    Text = "Finalmente fuori da lì. Quel negozio puzzava di un odore strano — mi ha quasi rovinato il naso."
  },
  AvgDialog_4906_Content_3 = {Text = "Squeak!"},
  AvgDialog_4906_Content_4 = {
    Text = "Se ti avesse sentito dire una cosa del genere, oggi non ce la saremmo cavata così facilmente."
  },
  AvgDialog_4906_Content_5 = {
    Text = "Siamo già a dieci metri dal negozio! Non ha mica tre paia di orecchie — impossibile che ci abbia sentito."
  },
  AvgDialog_4906_Content_6 = {
    Text = "Hai soppesato la pellicola nella mano — pesava esattamente quanto la scatola che avete rovinato.\nHai ripensato al pagamento che Daffodil voleva riscuotere..."
  },
  AvgDialog_4906_Content_7 = {
    Text = "Una storia meravigliosa, completa e senza rimpianti.\nÈ questo che voglio in cambio."
  },
  AvgDialog_4906_Content_8 = {
    Text = "Stavolta non possiamo riprendere quello che ci pare. Ci serve un piano."
  },
  AvgDialog_4906_Content_9 = {
    Text = "Un piano~ Un piano per raccontare una storia~"
  },
  AvgDialog_4907_Content_1 = {
    Text = "Cosa sta succedendo là dietro...?"
  },
  AvgDialog_4907_Content_10 = {
    Text = "Lily strinse le labbra e trascinò il foglio tra le braccia come un topolino protettivo. Non si capiva se fosse timida, spaventata o triste."
  },
  AvgDialog_4907_Content_11 = {
    Text = "Mi dispiace... ma quando penso alla mia mamma..."
  },
  AvgDialog_4907_Content_12 = {
    Text = "Non hai fatto niente di sbagliato, dopotutto, questo finale..."
  },
  AvgDialog_4907_Content_13 = {
    Text = "Per oggi basta. Abbiamo girato abbastanza. Se Doll ha qualche problema, può venire da me."
  },
  AvgDialog_4907_Content_14 = {
    Text = "Eh—? Ma Aurita non è ancora apparsa!"
  },
  AvgDialog_4907_Content_15 = {
    Text = "Non eri dietro le quinte a sgranocchiare con Brown per un sacco di tempo? Perché adesso vuoi stare davanti alla telecamera?"
  },
  AvgDialog_4907_Content_16 = {
    Text = "Aurita vuole dipingere un quadro a olio anche lei!"
  },
  AvgDialog_4907_Content_17 = {
    Text = "Il tuo mantello viene tirato con forza. Abbassi lo sguardo verso la gamba e vedi Lily, con gli occhi pieni di inquietudine e senso di colpa."
  },
  AvgDialog_4907_Content_18 = {
    Text = "La giovane ragazza si rifiuta di ricordare di essere stata costretta a separarsi dalla madre, e nessuno può biasimarla per questo."
  },
  AvgDialog_4907_Content_19 = {
    Text = "Ma c'è un modo per farle dimenticare questo dolore, anche solo temporaneamente...?"
  },
  AvgDialog_4907_Content_2 = {
    Text = "Clic! Clic!"
  },
  AvgDialog_4907_Content_20 = {
    Text = "Davanti a te si staglia un abbozzo approssimativo, ma grazie alle eccellenti capacità di progettazione del Gran Mago, le tue assurdità sono a malapena gestibili."
  },
  AvgDialog_4907_Content_21 = {
    Text = "<Yellow:Sciocchezze>..."
  },
  AvgDialog_4907_Content_3 = {
    Text = "Casiah interrompe bruscamente le riprese; l'illusione magica svanisce, e lei agita furiosamente il copione."
  },
  AvgDialog_4907_Content_4 = {
    Text = "Perché hai interrotto all'improvviso? Stavolta non è colpa mia. Né Brown né io abbiamo detto una parola!"
  },
  AvgDialog_4907_Content_5 = {
    Text = "Davanti a te si staglia un abbozzo approssimativo, ma grazie alle eccellenti capacità di progettazione del Gran Mago, le tue assurdità sono a malapena gestibili."
  },
  AvgDialog_4907_Content_6 = {
    Text = "Ma guardate questo copione dell'Atto IV, non è nemmeno una bozza. Come dovrebbe fare Lady Casiah a scrivere partendo da questo!"
  },
  AvgDialog_4907_Content_7 = {
    Text = "Casiah ti lancia il copione addosso, e le pagine volano fuori dal raccoglitore."
  },
  AvgDialog_4907_Content_8 = {
    Text = "Un foglio quasi bianco cadde ai piedi di tutti, coperto solo da alcuni scarabocchi infantili:"
  },
  AvgDialog_4907_Content_9 = {
    Text = "\"La ragazza visse per sempre felice e contenta con sua madre.\""
  },
  AvgDialog_49091_Content_1 = {Text = "Thais..."},
  AvgDialog_49091_Content_10 = {
    Text = "Solleva il braccio, e l'immenso fiume di stelle si apre attorno al suo arto liscio e lucente, eppure continua a scorrere, inarrestabile, incessante."
  },
  AvgDialog_49091_Content_11 = {
    Text = "Mi ricordi te, la gioia che balza, il brivido fugace."
  },
  AvgDialog_49091_Content_12 = {
    Text = "Una meteora solca il cielo, la sua lunga scia si dissolve nell'oscurità."
  },
  AvgDialog_49091_Content_13 = {
    Text = "Avanti, continuiamo..."
  },
  AvgDialog_49091_Content_14 = {
    Text = "Esplorami, immergiti nel mio profondo, finché non raggiungeremo quel paradiso di estasi..."
  },
  AvgDialog_49091_Content_15 = {
    Text = "Il suo calore, il suo desiderio ardente ti consuma — non tra le fiamme, ma nel rodere incessante di termiti brulicanti, che divorano la tua ragione granello dopo granello."
  },
  AvgDialog_49091_Content_16 = {
    Text = "L'impatto del traboccamento del Fiume sacro è troppo intenso. Non voglio... Non dovrei... farlo adesso..."
  },
  AvgDialog_49091_Content_17 = {
    Text = "È questo che ti preoccupa? Che bravo bambino."
  },
  AvgDialog_49091_Content_18 = {
    Text = "Thais ridacchia. Il suo suono sommesso è intessuto di un fascino provocante, una grazia consapevole che porta quel tanto di malizia sufficiente a perforare lo scafo dei tuoi pensieri inespressi, affondando la piccola imbarcazione della tua esitazione prima ancora che raggiunga la riva."
  },
  AvgDialog_49091_Content_19 = {
    Text = "Il potere del Fiume sacro è il mio potere. Non ne sono prigioniera."
  },
  AvgDialog_49091_Content_2 = {
    Text = "Thais si solleva da te con riluttanza persistente, un filo tenue e scintillante ancora vi lega l'uno all'altra, eco delicata di ciò che è appena accaduto."
  },
  AvgDialog_49091_Content_20 = {
    Text = "Ogni scelta che compio... sgorga dal mio stesso desiderio."
  },
  AvgDialog_49091_Content_21 = {
    Text = "L'acqua del fiume filtra attraverso la falla nello scafo, traboccando oltre le murate della tua volontà, sommergendo lentamente le dita dei piedi, le ginocchia, il petto, il collo, la bocca e il naso..."
  },
  AvgDialog_49091_Content_22 = {
    Text = "Ora tocca a te rispondere... Affonderai con me... nella marea infinita del mio desiderio?"
  },
  AvgDialog_49091_Content_23 = {
    Text = "La domanda restò sospesa nell'aria, e prima che tu potessi rispondere, le sue labbra calde e la sua lingua sigillarono le tue, mettendo a tacere ogni parola."
  },
  AvgDialog_49091_Content_24 = {
    Text = "In un momento come questo, le parole sono fin troppo pallide."
  },
  AvgDialog_49091_Content_25 = {
    Text = "Lascia che il tuo corpo... risponda per te."
  },
  AvgDialog_49091_Content_3 = {
    Text = "Il Suo Sguardo, velato e tumultuoso, scivola su di te come una fiamma lenta e liquida, tracciando ogni ciocca dei tuoi capelli, ogni tua curva, fino alla punta stessa delle dita dei piedi."
  },
  AvgDialog_49091_Content_4 = {
    Text = "Le sue dita, intrecciate alle tue, si stringono possessive, come temendo che tu possa sfuggirle. Ti trascina più a fondo in quel reame febbrile e appassionato dove il desiderio si raccoglie come miele caldo."
  },
  AvgDialog_49091_Content_5 = {
    Text = "Dinanzi a te, la vasta distesa di dune bianche incontra un cielo di velluto nero in fiamma divina di stelle. Ti ritrovi perduta in quello splendore immenso, radioso, vertiginoso."
  },
  AvgDialog_49091_Content_6 = {
    Text = "Cosa suscita in te questa distesa cosparsa di stelle?"
  },
  AvgDialog_49091_Content_7 = {
    Text = "Nulla. Le tue memorie giacciono infrante come vetro, disperse, frammentate; solo la luce scintillante delle stelle riflessa nelle pupille di Thais permane, vivida e inalterata."
  },
  AvgDialog_49091_Content_8 = {
    Text = "Mi ricorda Aram."
  },
  AvgDialog_49091_Content_9 = {
    Text = "Mi ricorda come i semi della vita convergano nel fiume possente, impetuoso e scrosciante, a colmare ogni capillare del deserto."
  },
  AvgDialog_49092_Content_1 = {
    Text = "Un panno nero viene sfilato via dalla tua testa. Sbatti le palpebre e ti strofini gli occhi."
  },
  AvgDialog_49092_Content_10 = {
    Text = "E ora... godetevi l'ultimo capolavoro di Casiah: \"Una Notte che il Custode Non Dovrà Dimenticare Mai\"..."
  },
  AvgDialog_49092_Content_11 = {
    Text = "I suoi occhi maliziosi brillano davanti ai tuoi. Per un fugace istante, vedi questa grande maga apparentemente senza cuore arrossire per la primissima volta."
  },
  AvgDialog_49092_Content_12 = {Text = "Cosa...?"},
  AvgDialog_49092_Content_13 = {
    Text = "Prima che tu possa reagire, il panno nero ricade su entrambi, avvolgendovi nell'oscurità. Sotto la fioca luce delle stelle, un corpo caldo e morbido si appoggia al tuo petto."
  },
  AvgDialog_49092_Content_14 = {
    Text = "Aspetta... Casiah, aspetta..."
  },
  AvgDialog_49092_Content_15 = {
    Text = "Shh, Custode. Lo spettacolo è già iniziato..."
  },
  AvgDialog_49092_Content_16 = {
    Text = "Provi a parlare, ma qualcosa di morbido e fresco si posa sulle tue labbra, riducendoti al silenzio."
  },
  AvgDialog_49092_Content_17 = {
    Text = "Chiudi gli occhi. Nessun livello, nessun pubblico. In questa piega di un'altra dimensione, ci sono solo le stelle e voi due."
  },
  AvgDialog_49092_Content_18 = {
    Text = "Nella tua memoria, resta il numero di magia più riuscito che Casiah abbia mai eseguito."
  },
  AvgDialog_49092_Content_2 = {
    Text = "Dove... dove siamo?"
  },
  AvgDialog_49092_Content_3 = {
    Text = "Un'altra dimensione, ovviamente! Non la riconosci, Custode?"
  },
  AvgDialog_49092_Content_4 = {
    Text = "Ehi, Casiah — ho accettato di aiutarti con il numero della \"dislocazione corporea\", ma non ho mai detto che potevi teletrasportarmi <Italic:qui.>"
  },
  AvgDialog_49092_Content_5 = {
    Text = "Torniamo indietro e finiamo lo spettacolo. È il modo migliore per stabilizzare l'influenza del Fiume sacro su di te..."
  },
  AvgDialog_49092_Content_6 = {
    Text = "Ma lo spettacolo è ancora in corso! Hai promesso di giocare al mio gioco di magia, ed è troppo tardi per ripensamenti."
  },
  AvgDialog_49092_Content_7 = {
    Text = "Ma il pubblico è ancora in attesa..."
  },
  AvgDialog_49092_Content_8 = {
    Text = "Lo spettacolo di magia per il pubblico ha già calato il sipario. Questa esibizione è un dono speciale, solo per il Custode."
  },
  AvgDialog_49092_Content_9 = {
    Text = "Casiah saltella verso di te, le mani nascoste dietro la schiena e la testa inclinata con aria giocosa."
  },
  AvgDialog_49093_Content_10 = {
    Text = "Basta soffiarlo via, giusto?"
  },
  AvgDialog_49093_Content_11 = {Text = "Woosh—"},
  AvgDialog_49093_Content_12 = {
    Text = "Ti è piaciuto?"
  },
  AvgDialog_49093_Content_13 = {
    Text = "Mi sento meglio; la polvere sembra essere sparita. Continuiamo."
  },
  AvgDialog_49093_Content_14 = {
    Text = "No, per oggi è tutto."
  },
  AvgDialog_49093_Content_15 = {
    Text = "Interrompere l'addestramento prima di essere pienamente soddisfatta? Non è da te..."
  },
  AvgDialog_49093_Content_16 = {
    Text = "Ha... grazie a Remouahe, questo non basta a farmi davvero divertire adesso."
  },
  AvgDialog_49093_Content_17 = {
    Text = "Ti scosta le ciocche di capelli dalla fronte e posa un bacio condiscendente sulla tua tempia."
  },
  AvgDialog_49093_Content_18 = {Text = "Lotan?!"},
  AvgDialog_49093_Content_19 = {
    Text = "Lotan ti dà un colpetto sulla guancia, poi ti prende la mano e ti tira su dal pavimento freddo e duro."
  },
  AvgDialog_49093_Content_2 = {
    Text = "Non basta. Ancora non basta!"
  },
  AvgDialog_49093_Content_20 = {
    Text = [[
Non preoccuparti. Quando sono lucida, quei desideri caotici non possono controllarmi.
Non dimenticare, sono un antico artefatto.]]
  },
  AvgDialog_49093_Content_21 = {
    Text = "Ora torna in dormitorio. Piccolo monello."
  },
  AvgDialog_49093_Content_3 = {
    Text = "È questa la tua vera forza? Dopo un anno di addestramento e diverse missioni..."
  },
  AvgDialog_49093_Content_4 = {
    Text = "Gli attacchi si abbattono come un torrente, frantumando senza pietà le piastrelle del campo d'addestramento."
  },
  AvgDialog_49093_Content_5 = {
    Text = "La polvere ti vola negli occhi, provocando una reazione involontaria che te li fa chiudere."
  },
  AvgDialog_49093_Content_6 = {
    Text = "Lotan! Fermati, io—"
  },
  AvgDialog_49093_Content_7 = {
    Text = "La guerriera ti spalanca le palpebre con forza; il tessuto dei suoi guanti sfrega contro la tua pelle sensibile e fragile, facendoti sbattere ripetutamente gli occhi."
  },
  AvgDialog_49093_Content_8 = {
    Text = "Non muoverti."
  },
  AvgDialog_49093_Content_9 = {
    Text = "Lotan posa semplicemente la sua arma, bloccandoti la testa con una mano, impedendo al tuo corpo di indietreggiare o fuggire d'istinto."
  },
  AvgDialog_49094_Content_1 = {
    Text = "Dadi, bulloni, barre di ferro... Già, è proprio come riparare il telaio di una motocicletta."
  },
  AvgDialog_49094_Content_2 = {
    Text = "Eh? Non è rotto. E allora perché {Male=lui,Female=lei} mi ha chiesto di venire in corsia? Che la cosa rotta non sia questo letto?"
  },
  AvgDialog_49094_Content_3 = {
    Text = "Nautila alza lo sguardo confusa, le mani coperte di grasso, a indicare che ha completato alla perfezione un'ispezione meccanica completa della corsia."
  },
  AvgDialog_49094_Content_4 = {
    Text = "Sniff... sniff sniff..."
  },
  AvgDialog_49094_Content_5 = {
    Text = "Questa persona porta il mio odore..."
  },
  AvgDialog_49094_Content_6 = {
    Text = "Nautila si china sullo studente addormentato nel letto d'ospedale, persa nei suoi pensieri."
  },
  AvgDialog_49094_Content_7 = {
    Text = "{Male=Lui,Female=Lei} ha evidenti macchie nere agli angoli della bocca e sul volto. Nautila le riconosce immediatamente come tracce lasciate dal suo olio meccanico appositamente formulato."
  },
  AvgDialog_49094_Content_8 = {
    Text = "Hmm... Lo conosco di sicuro. {Male=Il suo,Female=Il suo} nome è..."
  },
  AvgDialog_49094_Content_9 = {
    Text = "%player%... Esatto, ora ricordo. %player%."
  },
  AvgDialog_49095_Content_1 = {
    Text = "Sprofondi sempre più nel sogno."
  },
  AvgDialog_49095_Content_10 = {
    Text = "Smetti di respirare. Ti guiderò di ritorno alla realtà."
  },
  AvgDialog_49095_Content_11 = {
    Text = "Tulu?! Cough, cough..."
  },
  AvgDialog_49095_Content_12 = {
    Text = "La presenza del Risvegliatore aiuta a chiarire la situazione. Chiami il suo nome con fervore, ma quelle strane idee si riversano istantaneamente nelle tue vie respiratorie, come una marea."
  },
  AvgDialog_49095_Content_13 = {
    Text = "...Te l'ho appena detto: smetti di respirare."
  },
  AvgDialog_49095_Content_14 = {
    Text = "L'istante successivo, un tentacolo pieno e freddo ti penetra con forza nella bocca, spingendo da parte memorie caotiche e scacciando quei suoni ormai privi di significato."
  },
  AvgDialog_49095_Content_15 = {
    Text = "La brezza monsonica del mondo reale ti accarezza il volto, e il tuo corpo si abbandona a una fatica senza precedenti, come se stesse per sprofondare in un sonno profondo senza sogni..."
  },
  AvgDialog_49095_Content_16 = {
    Text = "Sopravvissuta al mio sogno e subito osi addormentarti di nuovo? Un tale coraggio mi impressiona."
  },
  AvgDialog_49095_Content_17 = {Text = "Tu-Tulu..."},
  AvgDialog_49095_Content_18 = {
    Text = "Hai appena detto che quello era il tuo sogno?"
  },
  AvgDialog_49095_Content_19 = {
    Text = "Distoglie lo sguardo, un po' imbarazzato."
  },
  AvgDialog_49095_Content_2 = {
    Text = "L'inondazione infranse bruscamente le travi del sogno, colmando il confine tra sogno e realtà di urla, che poi si tramutano in innumerevoli pietre umide e oscure."
  },
  AvgDialog_49095_Content_20 = {
    Text = "Quando riposo, i sogni traboccanti incitano la frenesia degli spiriti... L'anomalia del mio corpo ti ha trascinato nel sogno. La colpa è mia."
  },
  AvgDialog_49095_Content_21 = {
    Text = "Questa anomalia ha fatto sì che i miei sogni invadessero i tuoi senza invito. Se dovessi nutrire del risentimento, ti concedo il diritto di provarlo."
  },
  AvgDialog_49095_Content_22 = {
    Text = "R-risentimento? Certo che no. Non era intenzionale da parte tua. E poi, non sei forse arrivato appena in tempo quando le voci di Lemuria mi stavano sopraffacendo?"
  },
  AvgDialog_49095_Content_23 = {Text = "Tu..."},
  AvgDialog_49095_Content_24 = {
    Text = "Al ritorno a scuola, mi recherò immediatamente alla Pozza Nera. Forse l'ambiente là potrà temporaneamente sopprimere l'... anomalia dentro di me."
  },
  AvgDialog_49095_Content_25 = {
    Text = "Trattiene i suoi tentacoli in un angolo della carrozza, lanciando uno sguardo obliquo alla notte profonda e oscura oltre il finestrino."
  },
  AvgDialog_49095_Content_26 = {
    Text = "Ma le occhiate frequenti che cadono sull'angolo delle tue labbra non sembrano affatto involontarie."
  },
  AvgDialog_49095_Content_3 = {
    Text = "Questo non è il mio sogno... Questo non è mio..."
  },
  AvgDialog_49095_Content_4 = {
    Text = "Mormori, bramando di svegliarti. I tuoi alveoli colmi d'acqua si gonfiano come l'addome di un paziente in fase terminale; il tuo corpo si adatta all'oceano dimenticato."
  },
  AvgDialog_49095_Content_5 = {
    Text = "Ma la corrente silenziosa ti tira indietro la testa per un ultimo sguardo."
  },
  AvgDialog_49095_Content_6 = {
    Text = "Musica, dipinti, storie scritte in lingue sconosciute — innumerevoli idee bizzarre inondano i tuoi sogni nell'istante in cui ti volti a guardare."
  },
  AvgDialog_49095_Content_7 = {
    Text = "Cerchi di parlare, ma dalle labbra escono solo farfugliamenti insensati — eppure portano un significato."
  },
  AvgDialog_49095_Content_8 = {
    Text = "Hanno davvero un significato. Molto tempo fa, un tempo erano—"
  },
  AvgDialog_49095_Content_9 = {
    Text = "Non ingoiare quest'acqua."
  },
  AvgDialog_49261_Content_1 = {
    Text = "La mia testa... mi fa male. Cosa mi è successo?"
  },
  AvgDialog_49261_Content_10 = {
    Text = "<Small:Ugh... Lo sapevo. Una come me non è altro che un'ombra, un topo di fogna in camicia nera, una goccia di rugiada destinata a svanire al sole...>"
  },
  AvgDialog_49261_Content_11 = {
    Text = "Signorina Mason! Signorina Mason, mi ascolti!"
  },
  AvgDialog_49261_Content_12 = {
    Text = "La afferri per le spalle e la scuoti, cercando di strapparla dalla spirale dei suoi dubbi."
  },
  AvgDialog_49261_Content_13 = {
    Text = "Nessuno ti sta rifiutando. Sei una di noi."
  },
  AvgDialog_49261_Content_14 = {
    Text = "Nessuno... mi sta rifiutando..."
  },
  AvgDialog_49261_Content_15 = {
    Text = "Lei scatta a guardarti, la bocca che si torce in un ghigno distorto e frastagliato."
  },
  AvgDialog_49261_Content_16 = {
    Text = "Esatto. Allora diventa parte di me — diamo nascita a una nuova \"24\"!"
  },
  AvgDialog_49261_Content_17 = {
    Text = "Una fessura orrifica le squarcia la spalla, ma all'interno non vi sono muscoli né ossa. Una massa grigio pallido pulsa e si gonfia sotto la pelle, come un universo nelle doglie della nascita."
  },
  AvgDialog_49261_Content_18 = {
    Text = "Il muco si contorce fuori dalla crepa, avvolgendosi attorno alle tue dita. La sensazione umida e viscida trascina istantaneamente la tua mente al momento in cui ti sei svegliato per la prima volta dal tuo torpore."
  },
  AvgDialog_49261_Content_19 = {
    Text = "Le sue pupille sono dilatate e prive di fuoco. Ti brama — anela a consumarti, a riassorbirti nella fine di ogni cosa."
  },
  AvgDialog_49261_Content_2 = {
    Text = "Ti ritrovi disteso sul tuo fin troppo familiare letto morbido, il pulsare alla base del cranio altrettanto familiare."
  },
  AvgDialog_49261_Content_20 = {
    Text = "Non importa quale Mason tu sia... torna in te!"
  },
  AvgDialog_49261_Content_21 = {
    Text = "Lotti per raggiungere la Chiave d'Argento sul tuo petto, ma prima che la tua mano possa muoversi di un centimetro, quella forza travolgente ti afferra di nuovo."
  },
  AvgDialog_49261_Content_22 = {
    Text = "Perché resisti? Non avevi detto che avresti accettato tutto di me? L'ospite ti ama così tanto... So che anche lei lo desidera..."
  },
  AvgDialog_49261_Content_23 = {
    Text = "Mentre le sue labbra gelide si premono contro l'angolo della tua bocca, ti rendi conto che i suoi occhi sono stati interamente divorati dalla follia. Questa non è la Mason che conosci."
  },
  AvgDialog_49261_Content_24 = {Text = "Ugh!"},
  AvgDialog_49261_Content_25 = {
    Text = "\"24\" comincia a tremare violentemente, il suo respiro rantolante come un mantice rotto. Allenta la presa su di te e inizia a graffiare freneticamente il proprio collo esile."
  },
  AvgDialog_49261_Content_26 = {
    Text = "Perché! Perché <Italic:tu> puoi stare in primo piano per questo—!"
  },
  AvgDialog_49261_Content_27 = {
    Text = "No... no, no! Basta, BASTA BASTA BASTA BASTA BASTA—"
  },
  AvgDialog_49261_Content_28 = {
    Text = "Con uno strido lacerante, i suoi arti si contorcono e si ripiegano all'indietro oltre le spalle. Infine, la sua testa ricade, e cala un silenzio greve."
  },
  AvgDialog_49261_Content_29 = {
    Text = "Signorina... Mason? Sei tu?"
  },
  AvgDialog_49261_Content_3 = {
    Text = "Punti le mani per sollevarti, solo per scoprire che affondano in una massa di tessuto umido e viscido."
  },
  AvgDialog_49261_Content_30 = {
    Text = "Custode! Io... mi dispiace così, così tanto... Non so cosa sia successo. Questa nuova me... sembra aver sviluppato dei... sentimenti insoliti per te..."
  },
  AvgDialog_49261_Content_31 = {
    Text = "Mason agita freneticamente le braccia completamente lussate; oscillano dalle spalle come molli trecce di pasta."
  },
  AvgDialog_49261_Content_32 = {
    Text = "Non c'è bisogno di scusarsi. Sei solo sotto l'influenza del Fiume sacro."
  },
  AvgDialog_49261_Content_33 = {
    Text = "Le prendi la mano — la sua mano umana — e con cautela guidi le articolazioni dislocate nelle loro sedi."
  },
  AvgDialog_49261_Content_34 = {
    Text = "Sono un tale peso..."
  },
  AvgDialog_49261_Content_35 = {
    Text = "La sua Voce è appena un Sussurro, eppure sotto la vergogna, un Tremolio di gioia genuina attraversa il suo tono."
  },
  AvgDialog_49261_Content_4 = {
    Text = "Custode... Custode..."
  },
  AvgDialog_49261_Content_5 = {
    Text = "Vedendoti sveglio, la giovane donna arrossisce profondamente, e la sua voce assume un tono delicato e civettuolo che non le hai mai sentito prima."
  },
  AvgDialog_49261_Content_6 = {
    Text = "Si-Signorina Mason?!"
  },
  AvgDialog_49261_Content_7 = {
    Text = "\"Mason\"è distesa accanto a te, le punte annerite delle dita posate sul tuo petto. Sebbene le sue mani appaiano fragili, ti inchiodano al letto con una forza impossibile."
  },
  AvgDialog_49261_Content_8 = {
    Text = "Non andartene... perché vorresti andartene?"
  },
  AvgDialog_49261_Content_9 = {
    Text = "O forse tutte quelle dolci promesse di accettare \"24\" erano solo i deliri della mia mente spezzata?"
  },
  AvgDialog_49398_Content_1 = {
    Text = "La tempesta infuria più violenta; i soldati di Aram urlano, si fanno prendere dal panico, gridano, implorano, maledicono."
  },
  AvgDialog_49398_Content_10 = {
    Text = "Innumerevoli Aramiti si volgono verso Thais, inginocchiandosi in solenne Devozione."
  },
  AvgDialog_49398_Content_11 = {
    Text = "Gli spiriti di sabbia impazziti si placano sotto il conforto della Preghiera; la tempesta si dissolve gradualmente."
  },
  AvgDialog_49398_Content_12 = {
    Text = "È la Regina! È la Regina!"
  },
  AvgDialog_49398_Content_13 = {
    Text = "Sia lodata la Regina!"
  },
  AvgDialog_49398_Content_14 = {
    Text = "Gli occhi della Regina vegliano ancora su di noi!"
  },
  AvgDialog_49398_Content_15 = {
    Text = "Ce... Ce l'abbiamo fatta!"
  },
  AvgDialog_49398_Content_2 = {
    Text = "Finalmente, scorgi una figura familiare su una duna."
  },
  AvgDialog_49398_Content_3 = {
    Text = "Riconosci la sagoma. È Thais."
  },
  AvgDialog_49398_Content_4 = {
    Text = "La tempesta... si sta placando?"
  },
  AvgDialog_49398_Content_5 = {
    Text = "Con il vento ululante che le sferza i veli, intona una Preghiera sconosciuta, avanzando lenta e sicura nella scura tempesta di sabbia."
  },
  AvgDialog_49398_Content_6 = {
    Text = "Il rombo assordante toglie l'udito, eppure la Preghiera lo trafigge nitida, echeggiando dentro il vostro cranio."
  },
  AvgDialog_49398_Content_7 = {
    Text = "Nella bufera che divora il cielo, conversa con calma con un'entità in agguato tra le sabbie del deserto."
  },
  AvgDialog_49398_Content_8 = {
    Text = "È la Regina! È venuta a salvarci... a salvare Aram!"
  },
  AvgDialog_49398_Content_9 = {
    Text = "Il gruppo di Aram, frenetico nella Fuga solo un istante prima, si arresta all'improvviso."
  },
  AvgDialog_49399_Content_1 = {
    Text = "Muro della Tempesta"
  },
  AvgDialog_49399_Content_10 = {
    Text = "È—è qui!"
  },
  AvgDialog_49399_Content_11 = {
    Text = "In quell'istante di concentrazione, comprendi cosa significhi davvero il \"Muro della Tempesta\"."
  },
  AvgDialog_49399_Content_12 = {
    Text = "Una cortina grigia inghiotte cielo e Terra, avanzando per oscurare i cieli."
  },
  AvgDialog_49399_Content_13 = {
    Text = "Imita un'onda di marea eppure non lo è — vasta e priva di vita, in movimento eppure apparentemente immobile."
  },
  AvgDialog_49399_Content_14 = {
    Text = "Il suo margine lambisce il suolo come la lingua di una Bestia colossale, divorando la linea di Aram nella nebbia, dilaniandoli e digerendoli nelle fauci della tempesta."
  },
  AvgDialog_49399_Content_15 = {
    Text = "Continuate a danzare! Non fermatevi!"
  },
  AvgDialog_49399_Content_16 = {
    Text = "L'Inviato Straniero è con noi; la Regina ci aprirà il cammino verso l'Albero Madre!"
  },
  AvgDialog_49399_Content_17 = {
    Text = "Cogli Juliette con un ghigno sulle labbra."
  },
  AvgDialog_49399_Content_18 = {
    Text = "Capo, Capo... questa tempesta è troppo feroce! Non possiamo permetterci altre perdite... ritiriamoci!"
  },
  AvgDialog_49399_Content_19 = {Text = "No!"},
  AvgDialog_49399_Content_2 = {
    Text = "Alva innalza lo stendardo, e all'unisono trascinano le lance sulla sabbia arida, sollevando polvere accecante, intonando un inno lontano e inquietante."
  },
  AvgDialog_49399_Content_20 = {
    Text = "La sua voce risuona con autorità, eppure il vento la fa tremare."
  },
  AvgDialog_49399_Content_21 = {
    Text = "Le deformità del rito del falò si intensificano ogni volta. Di questo passo, la stirpe di Aram svanirà nell'Oblio prima che raggiungiamo l'Albero Madre."
  },
  AvgDialog_49399_Content_22 = {
    Text = "Juliette piega le dita a formare un anello e soffia un fischio limpido e squillante, la cui nota persistente viene trasportata dalla tempesta verso orizzonti invisibili."
  },
  AvgDialog_49399_Content_23 = {
    Text = "Sono l'Inviata Juliette. Ho udito la volontà della Regina... oggi sfonderemo il Muro della Tempesta!"
  },
  AvgDialog_49399_Content_24 = {
    Text = "Tutti, avanzate! Nessuna ritirata!"
  },
  AvgDialog_49399_Content_25 = {
    Text = "Agli ordini dell'inviato—avanzate! Nessuna ritirata!"
  },
  AvgDialog_49399_Content_26 = {
    Text = "<Small:Non si... torna... indietro...>"
  },
  AvgDialog_49399_Content_27 = {
    Text = "Fermi, Custode! Un enorme branco di Nubia in arrivo da dietro... Almeno duecento!"
  },
  AvgDialog_49399_Content_28 = {
    Text = "Guardate! Questo è il decreto della Regina. L'unica via è davanti a voi!"
  },
  AvgDialog_49399_Content_29 = {
    Text = "La Nubia ruggisce, caricando dritta verso di te."
  },
  AvgDialog_49399_Content_3 = {
    Text = "La morte si avvicina. La Dissoluzione albeggia."
  },
  AvgDialog_49399_Content_4 = {
    Text = "Le Spoglie della Madre svaniscono, sangue e seme vagano per la Terra, divorati da bestie appena nate."
  },
  AvgDialog_49399_Content_5 = {
    Text = "Cieli e dèi si ammantano di tenebra, finché giunge l'inviato straniero."
  },
  AvgDialog_49399_Content_6 = {
    Text = [[
L'Albero Madre risorge: le sue radici bevono a fondo il fluire del Fiume sacro.
Incorona di luce i caduti e richiama il loro sangue a quello di Aram.]]
  },
  AvgDialog_49399_Content_7 = {
    Text = "Restituisce i lignaggi... ad Aram..."
  },
  AvgDialog_49399_Content_8 = {
    Text = "Il sole del deserto svanisce inavvertito, il cielo si fa plumbeo, il vento muta la sua voce."
  },
  AvgDialog_49399_Content_9 = {
    Text = "Un terrore inspiegabile ti attanaglia; per un istante perdi lucidità, poi un urlo ti riporta in te."
  },
  AvgDialog_49400_Content_1 = {
    Text = "Lady Alva, vi prego, permettetemi di scambiare qualche parola con {Male=lui,Female=lei}."
  },
  AvgDialog_49400_Content_10 = {
    Text = "La sua Espressione si contorce in uno zelo innaturale; le parole sgorgano frenetiche, il corpo proteso in avanti, gli Occhi spettrali."
  },
  AvgDialog_49400_Content_11 = {
    Text = "Ci rivedremo, Occhio Senza Pupilla."
  },
  AvgDialog_49400_Content_12 = {Text = "..."},
  AvgDialog_49400_Content_13 = {
    Text = "No, non è finita. Perché lei ti ha implorato, con la massima sincerità, di chiamare il suo nome."
  },
  AvgDialog_49400_Content_14 = {
    Text = "Rievocando lo Sguardo di Thais, attivi la Chiave d'Argento."
  },
  AvgDialog_49400_Content_15 = {
    Text = "Fili d'Argento oscillano, tirano, cercano..."
  },
  AvgDialog_49400_Content_16 = {
    Text = "Al termine del filo — il nulla."
  },
  AvgDialog_49400_Content_17 = {
    Text = "La Dissoluzione l'ha divorata interamente. Nemmeno tu puoi trovarla, ormai."
  },
  AvgDialog_49400_Content_18 = {
    Text = "Speri ancora che faccia Ritorno? Gli Aramiti obbediscono solo a me, adesso."
  },
  AvgDialog_49400_Content_19 = {
    Text = "Thais... Thais!"
  },
  AvgDialog_49400_Content_2 = {
    Text = "Le parole di Juliette spezzano lo stallo."
  },
  AvgDialog_49400_Content_20 = {
    Text = "Se lei potesse apparire, se potesse rivelare il futuro di Aram ad Alva..."
  },
  AvgDialog_49400_Content_21 = {
    Text = "Basterebbe una sua sola parola, e non dovresti affrontare Alva Lama contro Lama."
  },
  AvgDialog_49400_Content_22 = {
    Text = "Thais... THAIS!"
  },
  AvgDialog_49400_Content_23 = {
    Text = "Le tue grida sono vane. Le tue Ultime volontà per lei sono state accuse."
  },
  AvgDialog_49400_Content_24 = {
    Text = "Un essere già annientato dalla Dissoluzione, senza alcuna traccia residua di contatto con l'Argento. Non puoi sfiorare minimamente la sua esistenza."
  },
  AvgDialog_49400_Content_25 = {Text = "..."},
  AvgDialog_49400_Content_26 = {
    Text = "Hmm? Questo viaggio ti ha reso troppo arrogante per chiedere aiuto?"
  },
  AvgDialog_49400_Content_27 = {
    Text = "O sei solo una piagnucolona inutile senza di me?"
  },
  AvgDialog_49400_Content_28 = {
    Text = "La quiete del deserto si frantuma con una raffica improvvisa; l'orizzonte si oscura rapido, come se ogni luce soccombesse alla Furia incombente."
  },
  AvgDialog_49400_Content_29 = {
    Text = "Una tempesta di sabbia ruggisce come un behemoth infuriato, trascinando tonnellate di sabbia, oscurando sole e cielo."
  },
  AvgDialog_49400_Content_3 = {
    Text = "Se insistete."
  },
  AvgDialog_49400_Content_30 = {
    Text = "In questa furia scatenata, una sagoma colossale tremola, mutando forma tra la polvere."
  },
  AvgDialog_49400_Content_31 = {
    Text = "Il Muro della Tempesta..."
  },
  AvgDialog_49400_Content_32 = {
    Text = "Il Muro della Tempesta... L'ho evocato con la mia Autorità."
  },
  AvgDialog_49400_Content_33 = {
    Text = "Tu sei... Thais...?"
  },
  AvgDialog_49400_Content_34 = {
    Text = "Trabocca di Potere infinito; mentre la polvere danza selvaggia, l'Ombra balza, si deforma — come un antico Mostro del deserto a caccia nella bufera."
  },
  AvgDialog_49400_Content_35 = {
    Text = "La sua forma, immensa e terrificante: un capo massiccio e avvolto su sé stesso, artigli affilati come rasoi, zoccoli possenti — tutto intravisto nel turbinio di sabbia."
  },
  AvgDialog_49400_Content_36 = {
    Text = "Non hai del tutto torto a chiamarmi così."
  },
  AvgDialog_49400_Content_37 = {
    Text = "Ma non sono la Regina che vi aspettate."
  },
  AvgDialog_49400_Content_38 = {
    Text = "Se desideri prendere in prestito il mio potere, grida ad alta voce il mio nome sacro—"
  },
  AvgDialog_49400_Content_39 = {
    Text = "La vasta, bizzarra Ombra svanisce; la figura che cerchi emerge dalla tempesta urlante."
  },
  AvgDialog_49400_Content_4 = {
    Text = "Guardie, non permettete che facciano del male all'inviato."
  },
  AvgDialog_49400_Content_40 = {
    Text = "La sabbia le turbina intorno senza pietà, eppure i suoi passi restano incrollabili."
  },
  AvgDialog_49400_Content_42 = {
    Text = "La Regina! La Regina è tornata!"
  },
  AvgDialog_49400_Content_43 = {
    Text = "Gli Occhi della Regina vegliano sempre su di noi!"
  },
  AvgDialog_49400_Content_44 = {
    Text = "Ha sempre vegliato su Aram, passato e futuro scorrono nel suo Sangue."
  },
  AvgDialog_49400_Content_45 = {
    Text = "Lady Thais..."
  },
  AvgDialog_49400_Content_46 = {
    Text = "Aramiti, ascoltatemi! L'antica Profezia si è compiuta! L'Albero Madre fa Ritorno, incoronando il Defunto!"
  },
  AvgDialog_49400_Content_47 = {
    Text = "La Regina cammina di nuovo sulle sabbie, reclamando il suo Trono!"
  },
  AvgDialog_49400_Content_48 = {
    Text = "L'unica vera Regina di Aram, Lady Thais —"
  },
  AvgDialog_49400_Content_49 = {
    Text = "avrà la vostra volontà e la vostra Lealtà!"
  },
  AvgDialog_49400_Content_5 = {Text = "Sì!"},
  AvgDialog_49400_Content_6 = {
    Text = "Juliette si avvicina, sussurrando a un palmo di distanza."
  },
  AvgDialog_49400_Content_7 = {
    Text = "Ritornare al Fiume Sacro è il destino di Aram. Io sto semplicemente... accelerandolo un poco."
  },
  AvgDialog_49400_Content_8 = {
    Text = "Quando il Suo Sguardo avvolgerà tutta Kadath, si fonderanno con il fiume in un nuovo mondo."
  },
  AvgDialog_49400_Content_9 = {
    Text = "Non è forse anche la vostra volontà?"
  },
  AvgDialog_49401_Content_1 = {
    Text = "I rami dell'Albero Madre sembrano senzienti, protendendosi avidamente in ogni direzione; sagome umane tremolano al loro interno, i movimenti goffi e sofferenti."
  },
  AvgDialog_49401_Content_10 = {
    Text = "Ramona! Incendia l'Albero Madre con le Fiamme d'Argento! Solo tu puoi farlo!"
  },
  AvgDialog_49401_Content_11 = {
    Text = "Fantasmi d'Argento assaltano le radici dell'Albero Madre; fiamme argentee erompono, trasformandosi in un incendio di Distruzione."
  },
  AvgDialog_49401_Content_12 = {
    Text = "Lingue di fuoco strisciano lungo il tronco come serpenti d'argento; i rami si contorcono e urlano nella furia, sibilando acuti—come se l'Albero Madre gemesse in un tormento straziante."
  },
  AvgDialog_49401_Content_13 = {
    Text = "Aspettate—l'albero sta crollando, e il Custode è ancora lassù!"
  },
  AvgDialog_49401_Content_14 = {
    Text = "Non preoccuparti, cara—lo riporterò {Male=sano e salvo,Female=sana e salva}."
  },
  AvgDialog_49401_Content_15 = {
    Text = "L'albero colossale si scuote; la terra trema."
  },
  AvgDialog_49401_Content_16 = {
    Text = "Perdi l'equilibrio, precipitando in verticale—"
  },
  AvgDialog_49401_Content_17 = {
    Text = "Quanto in alto? Mille piedi? Di più?"
  },
  AvgDialog_49401_Content_18 = {
    Text = "Poi, un Abbraccio caldo e morbido ti accoglie."
  },
  AvgDialog_49401_Content_19 = {
    Text = "Brava creatura, sei stata meravigliosa."
  },
  AvgDialog_49401_Content_2 = {
    Text = "Il primo a formare una gola geme, liberandosi a fatica dalla presa dell'Albero Madre, precipitando dall'alto nel Fiume sacro."
  },
  AvgDialog_49401_Content_20 = {
    Text = "Sul suo petto, la giada bianca che le hai allacciato risplende contro la sua pelle serica."
  },
  AvgDialog_49401_Content_21 = {
    Text = "Thais lo sgancia, lo ingoia, mordendo delicatamente."
  },
  AvgDialog_49401_Content_22 = {
    Text = "Farò Ritorno al Fiume sacro, nutrendo l'intera Terra.\nQuesto è il mio dono d'addio per te."
  },
  AvgDialog_49401_Content_23 = {
    Text = "Nell'istante in cui ti tuffi nel Fiume sacro in tumulto, le sue labbra incontrano le tue."
  },
  AvgDialog_49401_Content_24 = {
    Text = "I vostri respiri si intrecciano. Le vostre anime si fondono in uno."
  },
  AvgDialog_49401_Content_25 = {
    Text = "La sua lingua scivola dentro—calda, umida, tenera eppure insistente."
  },
  AvgDialog_49401_Content_26 = {
    Text = "Il bacio mescola la dolcezza dell'amore, il sapore metallico del Sangue, e qualcosa di piccolo, rotondo... indefinito."
  },
  AvgDialog_49401_Content_27 = {
    Text = "Il Seme dell'albero."
  },
  AvgDialog_49401_Content_28 = {Text = "..."},
  AvgDialog_49401_Content_29 = {Text = "..."},
  AvgDialog_49401_Content_3 = {Text = "...Splash!"},
  AvgDialog_49401_Content_30 = {Text = "..."},
  AvgDialog_49401_Content_31 = {
    Text = "È finita... Anche se non nel modo in cui immaginavo."
  },
  AvgDialog_49401_Content_32 = {
    Text = "In quanto discendenti dell'Eone del Desiderio, gli Aramiti erano ossessionati dalla continuità della stirpe.."
  },
  AvgDialog_49401_Content_33 = {
    Text = "Veneravamo l'Albero Madre, fondendo la sua essenza nelle nostre ossa, alla ricerca di una fertilità sovrumana."
  },
  AvgDialog_49401_Content_34 = {
    Text = "La nostra convinzione era che, se anche un solo discendente fosse sopravvissuto alla rovina nera, la nostra civiltà avrebbe potuto Sopportare fino al ciclo successivo."
  },
  AvgDialog_49401_Content_35 = {
    Text = "Ma ci sbagliavamo."
  },
  AvgDialog_49401_Content_36 = {
    Text = "La continuazione della tribù di Aram non dipende da alcun lignaggio specifico. Col tempo, sono divenuti Schiavi del concetto di \"discendenza\", eccessivamente dipendenti dal Desiderio di riprodursi."
  },
  AvgDialog_49401_Content_37 = {
    Text = "In secoli di Esilio... solo Alva ha davvero fatto progredire Aram."
  },
  AvgDialog_49401_Content_38 = {
    Text = "Tawil, avevi ragione. Dovremmo fidarci della volontà umana."
  },
  AvgDialog_49401_Content_39 = {
    Text = "Anche nell'Oscurità senza fine, anche se la Luce della Speranza è Faint... Gli esseri umani non cedono mai; quello Spirito da solo può mutare i futuri segnati dal Fato."
  },
  AvgDialog_49401_Content_4 = {Text = "Splash!"},
  AvgDialog_49401_Content_40 = {
    Text = "Ora, ho trovato una nuova risposta."
  },
  AvgDialog_49401_Content_41 = {
    Text = "Quindi, Tawil, prestami il tuo successore prescelto. Sii generoso, vuoi?"
  },
  AvgDialog_49401_Content_42 = {
    Text = "Affiderò il mio seme a {Male=lui,Female=lei}."
  },
  AvgDialog_49401_Content_43 = {
    Text = "Il seme metterà radici, germoglierà, crescerà in un albero magnifico—"
  },
  AvgDialog_49401_Content_44 = {
    Text = "Come nacque il primo Albero Madre."
  },
  AvgDialog_49401_Content_45 = {Text = "..."},
  AvgDialog_49401_Content_46 = {
    Text = "Quest'ultimo seme — lo pianto dentro di te."
  },
  AvgDialog_49401_Content_47 = {
    Text = "Finché non spargerà il mio sangue sulla terra, tu non devi morire..."
  },
  AvgDialog_49401_Content_48 = {
    Text = "Ti ricorderai di me. Non dimenticarmi mai."
  },
  AvgDialog_49401_Content_49 = {
    Text = "Le maree si sollevano."
  },
  AvgDialog_49401_Content_5 = {
    Text = "Splash! Splash!"
  },
  AvgDialog_49401_Content_50 = {
    Text = "Quel caldo abbraccio ti respinge."
  },
  AvgDialog_49401_Content_51 = {
    Text = "Nell'assalto tumultuoso della corrente, la vedi scivolare più in profondità nel fiume."
  },
  AvgDialog_49401_Content_52 = {Text = "..."},
  AvgDialog_49401_Content_53 = {
    Text = "Una Mano pallida e sottile ti afferra—familiare, salda."
  },
  AvgDialog_49401_Content_54 = {Text = "%player%!"},
  AvgDialog_49401_Content_6 = {
    Text = "Gli Aramiti cadono, uno dopo l'altro."
  },
  AvgDialog_49401_Content_7 = {
    Text = "Pochi istanti dopo, piccole teste emergono, lottando per raggiungere la riva."
  },
  AvgDialog_49401_Content_8 = {
    Text = "Il ramo sotto i tuoi piedi trema."
  },
  AvgDialog_49401_Content_9 = {
    Text = "È il momento!"
  },
  AvgDialog_49402_Content_1 = {Text = "Danza"},
  AvgDialog_49402_Content_10 = {
    Text = "Cosa si cela oltre il Muro della Tempesta?"
  },
  AvgDialog_49402_Content_11 = {
    Text = "Cosa muove l'enigmatica inviata Juliette?"
  },
  AvgDialog_49402_Content_12 = {
    Text = "Cosa si nasconde dietro il rito aramita?"
  },
  AvgDialog_49402_Content_13 = {
    Text = "E Thais — questa Thais davanti a te — ci si può davvero fidare di lei?"
  },
  AvgDialog_49402_Content_14 = {
    Text = "Da quando sei giunto a Remouahe, le anomalie si susseguono senza sosta, enigmi che ti inseguono fino a toglierti il respiro."
  },
  AvgDialog_49402_Content_15 = {
    Text = "Devi restare calma. Devi ragionare."
  },
  AvgDialog_49402_Content_16 = {
    Text = "Inutile rimuginare — sei già esausto. È tempo di riposare."
  },
  AvgDialog_49402_Content_17 = {
    Text = "Ti volti e vedi la luna piena bagnare la pelle immacolata di Thais di una luce traslucida."
  },
  AvgDialog_49402_Content_18 = {
    Text = "Oltre il Muro della Tempesta... tutte le tue domande troveranno risposta da sé."
  },
  AvgDialog_49402_Content_19 = {
    Text = "Oltre il Muro della Tempesta."
  },
  AvgDialog_49402_Content_2 = {
    Text = "▼▼ dimora nel caos; nessuno prevede la fine.\nCiò che deve avvenire giace nelle mie parole, ma orecchie e occhi tradiscono la moltitudine,\nsolo i silenziosi invadono la terra."
  },
  AvgDialog_49402_Content_20 = {
    Text = "Juliette lo ha detto chiaramente — devi davvero seguire il capriccio di un'ombra fin nel suo cuore?"
  },
  AvgDialog_49402_Content_21 = {
    Text = "O forse una forza cosmica sospinge tutti verso il Centro della Tempesta, pellegrini in balìa del suo richiamo?"
  },
  AvgDialog_49402_Content_22 = {
    Text = "I pensieri turbinano incontrollati, seminando dubbio e terrore nelle profondità della tua mente."
  },
  AvgDialog_49402_Content_23 = {
    Text = "Non riesci a dormire?"
  },
  AvgDialog_49402_Content_24 = {
    Text = "Chiudi gli occhi."
  },
  AvgDialog_49402_Content_25 = {
    Text = "Il respiro di Thais sfiora il tuo, a pochi centimetri di distanza."
  },
  AvgDialog_49402_Content_26 = {
    Text = "Chiudi gli occhi."
  },
  AvgDialog_49402_Content_27 = {
    Text = "Rifiuti di chiudere gli occhi."
  },
  AvgDialog_49402_Content_28 = {
    Text = "I tuoi occhi sono così luminosi... non offuscati dal peso del cammino."
  },
  AvgDialog_49402_Content_29 = {
    Text = "Thais posa il dito indice sulle tue labbra."
  },
  AvgDialog_49402_Content_3 = {
    Text = "Apri gli occhi intontito e contempli un cielo stellato straordinariamente limpido e abbagliante."
  },
  AvgDialog_49402_Content_30 = {
    Text = "Il suo volto si libra vicino, il chiaro di luna che le dora la pelle in un tenue alone."
  },
  AvgDialog_49402_Content_31 = {
    Text = "Senti il suo avvicinarsi: un'esalazione dolce, calda."
  },
  AvgDialog_49402_Content_32 = {
    Text = "Un profumo che risveglia echi lontani."
  },
  AvgDialog_49402_Content_33 = {
    Text = "Quanto tempo è passato da quando ci siamo avvicinati così?"
  },
  AvgDialog_49402_Content_34 = {
    Text = "Un brivido fresco ti sfiora le labbra."
  },
  AvgDialog_49402_Content_35 = {
    Text = [[
Apri gli occhi: il dito di Thais si posa sulle tue labbra.
Il suo volto aleggia vicino, la luce lunare le dora la pelle in un tenue alone.]]
  },
  AvgDialog_49402_Content_36 = {
    Text = "Lo sapevi? Nei tuoi occhi vedo calamità, braci dei giorni passati, il respiro del cosmo."
  },
  AvgDialog_49402_Content_37 = {
    Text = "Il viaggio ti ha consumato, non è vero? Eppure il tuo sguardo resta saldo, incontaminato."
  },
  AvgDialog_49402_Content_38 = {
    Text = "Le Stelle distorte non hanno potuto piegarti; le sabbie del deserto forse nemmeno."
  },
  AvgDialog_49402_Content_39 = {
    Text = "Non capisco."
  },
  AvgDialog_49402_Content_4 = {
    Text = "Come ho fatto a... addormentarmi?"
  },
  AvgDialog_49402_Content_40 = {
    Text = "Non devi — non ancora."
  },
  AvgDialog_49402_Content_41 = {
    Text = "Thais si alza e passeggia lungo la duna."
  },
  AvgDialog_49402_Content_42 = {
    Text = "Sotto simili stelle, restare seduti è uno spreco della notte."
  },
  AvgDialog_49402_Content_43 = {
    Text = "Il vento solleva il suo velo diafano; lei ondeggia sulla sabbia cedevole."
  },
  AvgDialog_49402_Content_44 = {
    Text = "Lascia che ti presenti la danza di Aram."
  },
  AvgDialog_49402_Content_45 = {
    Text = "Tintinnano campanelli; alza un braccio, oscillando nell'alba del movimento."
  },
  AvgDialog_49402_Content_46 = {
    Text = "Si piega, si dischiude — selvaggia, poi trattenuta."
  },
  AvgDialog_49402_Content_47 = {
    Text = "Ho atteso a lungo colui che verrà."
  },
  AvgDialog_49402_Content_48 = {
    Text = "Il suo corpo si piega senz'ossa, i suoi passi grazia serpentina."
  },
  AvgDialog_49402_Content_49 = {
    Text = "Un guardiano che guidi Aram verso il futuro."
  },
  AvgDialog_49402_Content_5 = {
    Text = "Le lunghe marce nel deserto logorano l'anima. Non è nulla di insolito."
  },
  AvgDialog_49402_Content_50 = {
    Text = "Volteggia e ondeggia. Persino la scia sfumata dei suoi movimenti sussurra una grazia Innata, una flessuosità soprannaturale."
  },
  AvgDialog_49402_Content_51 = {
    Text = "Non è forse Alva?"
  },
  AvgDialog_49402_Content_52 = {
    Text = "Thais lancia un'occhiata obliqua, ciglia basse, la punta delle dita sfiora come un bocciolo le labbra sospiranti."
  },
  AvgDialog_49402_Content_53 = {
    Text = "Alva è in gamba, ma non è pronta a tracciare nuovi sentieri."
  },
  AvgDialog_49402_Content_54 = {
    Text = "E Juliette? Non è lei l'Inviata Straniera?"
  },
  AvgDialog_49402_Content_55 = {
    Text = "Hai detto che Juliette vuole permettere agli Aramiti di lasciare il deserto, giusto?"
  },
  AvgDialog_49402_Content_56 = {
    Text = "Thais distende le braccia, il suo sguardo scivola verso le dita lambite dalla luna, come se liberasse uccelli invisibili."
  },
  AvgDialog_49402_Content_57 = {
    Text = "Chi poteva andarsene l'ha già fatto. Aram non vincola nessuno. È il richiamo della terra e il ritmo del deserto; chi è rimasto può sopravvivere solo qui."
  },
  AvgDialog_49402_Content_58 = {
    Text = "E poi, non è quella la risposta che bramo."
  },
  AvgDialog_49402_Content_59 = {
    Text = "La risposta che brami... qual è?"
  },
  AvgDialog_49402_Content_6 = {
    Text = "Ho altre domande..."
  },
  AvgDialog_49402_Content_60 = {
    Text = "Scritta nei canti molto tempo fa."
  },
  AvgDialog_49402_Content_61 = {
    Text = [[
L'Albero Madre risorge: le sue radici bevono a fondo il fluire del Fiume sacro.
Incorona di luce i caduti e richiama il loro sangue a quello di Aram.]]
  },
  AvgDialog_49402_Content_62 = {
    Text = "Rivitalizzare il Fiume sacro ha senso — chi sono i defunti? Come riportiamo le stirpi ad Aram?"
  },
  AvgDialog_49402_Content_63 = {Text = "Shh—"},
  AvgDialog_49402_Content_64 = {
    Text = "I dettagli si aggrovigliano troppo in profondità; la profezia di @1 non offre una mappa completa."
  },
  AvgDialog_49402_Content_65 = {
    Text = "Tutto ciò che devi fare è fidarti completamente di me.\nTi fiderai della Regina di Aram."
  },
  AvgDialog_49402_Content_66 = {
    Text = "Fiori del deserto si schiudono nell'oscurità lunare; lei si solleva, volteggia, avanza — incidendo ritmi intricati e antichi nella sabbia."
  },
  AvgDialog_49402_Content_67 = {
    Text = "Credi in me, e sarò tua soltanto — la tua arma segreta, assoluta e unica."
  },
  AvgDialog_49402_Content_68 = {
    Text = "Il chiaro di luna ne sfuma i contorni in enigma, i suoi occhi avvolti in un desiderio muto."
  },
  AvgDialog_49402_Content_69 = {
    Text = "Se questo sogno deve finire —\nle stelle lontane ne sono testimoni."
  },
  AvgDialog_49402_Content_7 = {
    Text = "Il sogno senza fine ti strappa dalla fatica del cammino; domande si riversano a cascata nella tua mente."
  },
  AvgDialog_49402_Content_70 = {
    Text = "Aspetta, Thais — i tuoi piedi —"
  },
  AvgDialog_49402_Content_71 = {
    Text = "Gridi in preda al panico."
  },
  AvgDialog_49402_Content_72 = {
    Text = "Cammina su increspature — no, nere increspature si aprono a ventaglio dalle sue dita dei piedi."
  },
  AvgDialog_49402_Content_73 = {
    Text = "L'orlo del velo ondeggia come ninfee, disperdendo perle d'ossidiana."
  },
  AvgDialog_49402_Content_74 = {
    Text = "Quella è... D-melma...?"
  },
  AvgDialog_49402_Content_75 = {
    Text = "Danza nella sognante pozza di Dissoluzione, posando i piedi ancora e ancora sulla superficie d'ebano."
  },
  AvgDialog_49402_Content_76 = {Text = "..."},
  AvgDialog_49402_Content_77 = {Text = "..."},
  AvgDialog_49402_Content_78 = {
    Text = "Sorda alle tue suppliche, oscilla al ritmo di una cadenza inudibile."
  },
  AvgDialog_49402_Content_79 = {
    Text = "Si volta verso di te, la sua figura sboccia; la collana che hai allacciato brilla alla sua gola."
  },
  AvgDialog_49402_Content_8 = {
    Text = "Perché l'acqua di Ramona si è trasformata in D-melma?"
  },
  AvgDialog_49402_Content_80 = {
    Text = "Ti invita a danzare; d'istinto, il tuo palmo incontra il suo."
  },
  AvgDialog_49402_Content_81 = {
    Text = "Ti prende la mano, guidando le tue dita verso la giada pulsante del pendente — come un battito vivente."
  },
  AvgDialog_49402_Content_82 = {
    Text = "Una meteora solca il firmamento.\nI Suoi Occhi brillano più delle Stelle."
  },
  AvgDialog_49402_Content_84 = {
    Text = "Le labbra si schiudono; la brezza notturna porta il suo mormorio."
  },
  AvgDialog_49402_Content_85 = {
    Text = "Posso affidarli a te?"
  },
  AvgDialog_49402_Content_86 = {
    Text = "Il richiamo del Festino stringe di nuovo; senza volerlo, sussurri."
  },
  AvgDialog_49402_Content_87 = {
    Text = "Sì — senza alcun dubbio."
  },
  AvgDialog_49402_Content_88 = {Text = "Bene."},
  AvgDialog_49402_Content_89 = {
    Text = "Thais sorride."
  },
  AvgDialog_49402_Content_9 = {
    Text = "Chi sta scatenando questi Nubia?"
  },
  AvgDialog_49402_Content_90 = {
    Text = "I tuoi amici sono arrivati."
  },
  AvgDialog_49402_Content_91 = {
    Text = "Segui il suo sguardo: Ramona accorre verso di te, con Ryker alle calcagna — rapido eppure composto, l'eleganza intatta."
  },
  AvgDialog_49402_Content_92 = {
    Text = "Ricorda: stanotte è il nostro segreto."
  },
  AvgDialog_49402_Content_93 = {
    Text = "Ti volti — Thais è svanita, e solo il vento geme sulle dune."
  },
  AvgDialog_49402_Content_94 = {
    Text = "Davanti a te, le sabbie recano una macchia nera di D-melma, che si fonde con la Terra."
  },
  AvgDialog_49414_Content_1 = {
    Text = "Custode, la funzione Rievocazione della Storia è stata attivata. Per procedere, tocca il tuo Comunicatore e chiama \"Erica\" dopo il segnale."
  },
  AvgDialog_49414_Content_2 = {
    Text = "Ricordare... Cos'è questo?"
  },
  AvgDialog_49414_Content_3 = {
    Text = "Un archivio temporaneo dei tuoi registri di memoria. La funzione Rievocazione della Storia ti aiuta a rivisitare le indagini passate."
  },
  AvgDialog_49414_Content_4 = {
    Text = "Presta attenzione ai dettagli che ti sono sfuggiti, alle connessioni che non hai colto. Perché gli esseri umani imparano guardando indietro... prima di poter andare avanti."
  },
  AvgDialog_49440_Content_1 = {
    Text = "(Anf... anf...)"
  },
  AvgDialog_49440_Content_2 = {
    Text = "Karen...? Cosa stai facendo?"
  },
  AvgDialog_49440_Content_3 = {
    Text = "Il tuo mondo è nero pece. Qualcosa è stato legato sui tuoi Occhi, accecandoti."
  },
  AvgDialog_49440_Content_4 = {
    Text = "Provi a sollevare le mani, ma morbide strisce di tessuto ti legano i polsi, limitandoti ai movimenti più impercettibili."
  },
  AvgDialog_49440_Content_5 = {
    Text = "Non è ovvio? È ora delle... pulizie di Primavera!"
  },
  AvgDialog_49440_Content_6 = {
    Text = "Perché vengo legata per le pulizie di primavera?"
  },
  AvgDialog_49440_Content_7 = {
    Text = "Un senso di presagio cresce dentro di te. Sotto l'influenza del Fiume sacro, i capricci imprevedibili di questa sfuggente Ancella sono impossibili da decifrare."
  },
  AvgDialog_49440_Content_8 = {
    Text = "La chiave per una pulizia accurata è essere meticolosi! E questo significa che anche il Custode fa parte della pulizia!"
  },
  AvgDialog_49440_Content_9 = {
    Text = "Qui, là... ogni singola parte deve essere strofinata fino a brillare~!"
  },
  AvgDialog_49441_Content_1 = {
    Text = "Erica, riesci a trovare su quale scaffale si trova la Lettera A-617?"
  },
  AvgDialog_49441_Content_10 = {Text = "Eri—"},
  AvgDialog_49441_Content_11 = {
    Text = "La tua Voce viene risospinta in gola da una corrente fantasma. La sensazione nel punto in cui le vostre mani si incontrano è uno Shock ben oltre ciò che un corpo umano dovrebbe Sopportare."
  },
  AvgDialog_49441_Content_12 = {
    Text = "Una breve, abbagliante Ondata di elettricità risveglia ogni senso nel tuo corpo. Questo impossibile \"Legame\" invia una Pulsazione attraverso le tue vene, destando nel tuo Sangue una strana, indescrivibile bramosia."
  },
  AvgDialog_49441_Content_13 = {Text = "..."},
  AvgDialog_49441_Content_14 = {
    Text = "Erica sbatte le palpebre e infine ritrae la mano."
  },
  AvgDialog_49441_Content_15 = {
    Text = "Compreso. La Lettera A-617 si trova nell'Archivio ristretto. Sto conducendo il Custode là ora."
  },
  AvgDialog_49441_Content_16 = {
    Text = "Senza voltarsi, inizia a camminare verso l'area ristretta, il suo telaio che emette un Faint e ritmico crepitio di statica mentre si muove."
  },
  AvgDialog_49441_Content_17 = {
    Text = "...Gli automi non dovrebbero essere influenzati dalle anomalie del Fiume sacro, giusto?"
  },
  AvgDialog_49441_Content_18 = {Text = "È così?"},
  AvgDialog_49441_Content_2 = {Text = "..."},
  AvgDialog_49441_Content_3 = {Text = "Erica?"},
  AvgDialog_49441_Content_4 = {
    Text = "L'automa resta immobile nell'angolo della Stanza. Indossa il suo solito sorriso, ma in questo pesante Silenzio, quell'Espressione Pietrificata risulta profondamente inquietante."
  },
  AvgDialog_49441_Content_5 = {
    Text = "Agiti la Mano davanti al suo viso, ma i Suoi Occhi non seguono affatto il movimento."
  },
  AvgDialog_49441_Content_6 = {
    Text = "Strano. Erica non si assenta mai con la mente... c'è forse un guasto meccanico?"
  },
  AvgDialog_49441_Content_7 = {
    Text = "Mormori tra te, girando attorno al suo involucro metallico per controllare eventuali Danni."
  },
  AvgDialog_49441_Content_8 = {
    Text = "—Crepitio."
  },
  AvgDialog_49441_Content_9 = {
    Text = "Un Faint scoppiettio di statica attira la tua attenzione. D'istinto guardi verso la fonte, solo per sentirti afferrare improvvisamente la Mano."
  },
  AvgDialog_49442_Content_1 = {Text = "Sogno"},
  AvgDialog_49442_Content_10 = {Text = "Splash—"},
  AvgDialog_49442_Content_11 = {
    Text = "Suono e colore tornano d'un tratto."
  },
  AvgDialog_49442_Content_12 = {
    Text = "Uno dopo l'altro, si gettano imperterriti nella corrente del fiume, le braccia protese, abbracciando il tronco avvizzito dell'Albero Madre."
  },
  AvgDialog_49442_Content_13 = {
    Text = "Gridano e ululano in una folle, indescrivibile frenesia."
  },
  AvgDialog_49442_Content_14 = {
    Text = "La loro pelle si affloscia come fango; i fluidi si prosciugano dai loro corpi, unendosi alla corrente del fiume."
  },
  AvgDialog_49442_Content_15 = {
    Text = "Le ossa si ammorbidiscono come carne; gli arti si torcono in modo disumano, si allungano, si intrecciano—fondendo sangue e carne nei rami gonfi dell'albero sacro."
  },
  AvgDialog_49442_Content_16 = {
    Text = "Lentamente, in modo straziante, si fondono con l'albero sacro."
  },
  AvgDialog_49442_Content_2 = {
    Text = "Sei un burattino difettoso, dopotutto. Richiedi fin troppo sforzo per essere controllato."
  },
  AvgDialog_49442_Content_3 = {
    Text = "Più Forte è la tua Devozione nel Sacrificarti per Aram... più feroce sarà la tua Resistenza quando scoprirai La Verità."
  },
  AvgDialog_49442_Content_4 = {
    Text = "Per fortuna, l'avevo previsto."
  },
  AvgDialog_49442_Content_5 = {
    Text = "I tempi sono quasi maturi. Tutti voi, il vostro amato Albero Madre..."
  },
  AvgDialog_49442_Content_6 = {
    Text = "reclamerà la vostra carne e le vostre vite."
  },
  AvgDialog_49442_Content_7 = {
    Text = [[
Apro la bocca, sconvolto nello scoprire che nessun suono ne Emerge.
Il mondo si arresta in modo terrificante.]]
  },
  AvgDialog_49442_Content_8 = {
    Text = "No, non è il mondo; i miei sensi si arrestano, ogni faint bagliore si estende per secoli."
  },
  AvgDialog_49442_Content_9 = {
    Text = "In questa stasi interminabile, solo i miei vecchi compagni—un Soldato di Aram dopo l'altro—si lanciano incuranti verso il Fiume sacro."
  },
  AvgDialog_49443_Content_1 = {
    Text = "Sotto l'Albero Madre, Alva si inginocchia in lacrime, impotente."
  },
  AvgDialog_49443_Content_10 = {
    Text = "Meno male che l'hai fatto. Tornare là fuori a cercarti ci sarebbe costato tempo prezioso e innumerevoli vite."
  },
  AvgDialog_49443_Content_11 = {
    Text = "La voce nella mia testa... mi diceva... che dovevo resistere..."
  },
  AvgDialog_49443_Content_12 = {
    Text = "Ma anche senza di lei...\nSono l'assistente di %player%—nei momenti più disperati, devo essere al fianco di {Male=his,Female=her}."
  },
  AvgDialog_49443_Content_13 = {
    Text = "È il mio dovere in quanto loro unica e sola, giusto?"
  },
  AvgDialog_49443_Content_14 = {
    Text = "Calca con forza su <Bold:unica e sola.>"
  },
  AvgDialog_49443_Content_15 = {
    Text = "Risvegliare il Loro Potere su questa terra intensifica lo sforzo sul tuo corpo."
  },
  AvgDialog_49443_Content_16 = {
    Text = "Non ricorrerei a questo se restasse un'altra via."
  },
  AvgDialog_49443_Content_17 = {
    Text = "Siamo venuti qui per fermare il Rito, e porterò tutto questo a compimento fino alla fine!"
  },
  AvgDialog_49443_Content_18 = {
    Text = "Bene! Ramona, Soppressione dell'Eone del Desiderio—%player% e io distruggeremo l'Albero Madre!"
  },
  AvgDialog_49443_Content_19 = {
    Text = "Un lamento assordante squarcia il cielo; fantasmi d'Argento sfreciano attraverso le alture del deserto."
  },
  AvgDialog_49443_Content_2 = {
    Text = "Ho celato la forma dell'Albero Madre nel Fiume sacro, ho portato la Dissoluzione nella mia carne per occultarne il seme — non era forse tutto per questo momento?"
  },
  AvgDialog_49443_Content_20 = {Text = "—"},
  AvgDialog_49443_Content_21 = {
    Text = "Il tuo corpo si fa leggero; un istante dopo, vieni scaraventato davanti a un tumore fetido e nauseabondo."
  },
  AvgDialog_49443_Content_22 = {
    Text = "Gli Aramiti divorati dall'Albero Madre si ammassano qui in forme simili a uova; pori traslucidi rivelano volti contorti e sfocati, melma rosso-nera sgorga senza sosta dai fori, alimentando il Fiume sacro un tempo limpido."
  },
  AvgDialog_49443_Content_3 = {
    Text = "Il momento è giunto!"
  },
  AvgDialog_49443_Content_4 = {
    Text = "In nome di Tifere Yesod, Eone del Desiderio, invoco <Yellow:Tawil> — onora il nostro patto millenario."
  },
  AvgDialog_49443_Content_5 = {
    Text = "Quando il messaggero Da Lontano giungerà, usa il tuo avatar come Guida per dissipare temporaneamente le Ombre su Lemoah per me."
  },
  AvgDialog_49443_Content_6 = {
    Text = "Un lamento lacerante riecheggia nel cielo."
  },
  AvgDialog_49443_Content_7 = {
    Text = "Thais apre la bara; all'interno, Ramona, arrossata dalla febbre, rotola fuori."
  },
  AvgDialog_49443_Content_8 = {
    Text = "Finalmente... Il mio momento è giunto..."
  },
  AvgDialog_49443_Content_9 = {
    Text = "Nascondersi qui dentro per venire di nascosto... furba, ragazza."
  },
  AvgDialog_49476_Content_1 = {
    Text = "La porta si apre piano, e la luce riflette una sagoma familiare."
  },
  AvgDialog_49476_Content_10 = {
    Text = "Sembra che l'influenza del Fiume sacro abbia raggiunto anche la tua dimensione... Stai bene?"
  },
  AvgDialog_49476_Content_11 = {
    Text = "Puoi farmi compagnia, Custode?"
  },
  AvgDialog_49476_Content_12 = {
    Text = "Certo, certo. È solo che non so come aiutarti..."
  },
  AvgDialog_49476_Content_13 = {
    Text = "Voglio portarti in un posto."
  },
  AvgDialog_49476_Content_14 = {Text = "Dove?"},
  AvgDialog_49476_Content_15 = {
    Text = "Ramona si siede accanto a te. Il rossore si fonde naturalmente con la luce e la sua pelle chiara, facendoti mancare il respiro."
  },
  AvgDialog_49476_Content_16 = {
    Text = "Nell'istante in cui ti prende la mano, lo spazio intorno a voi inizia a mutare. Innumerevoli immagini si condensano in una scena caotica che risulta inquietantemente familiare."
  },
  AvgDialog_49476_Content_17 = {
    Text = "Sembra caotico... Sto vedendo le tue memorie?"
  },
  AvgDialog_49476_Content_18 = {
    Text = "Mi scuso... Ho vissuto gli stessi scenari troppe volte. Le mie memorie sono troppo complesse... Ma credo che tu possa vedere chiaramente questo luogo."
  },
  AvgDialog_49476_Content_19 = {
    Text = "Quelle immagini e quegli odori sfocati sono molto familiari... Come le rovine dopo un'esplosione devastante... Che questo posto sia?!"
  },
  AvgDialog_49476_Content_2 = {
    Text = "Ramona? Non avevi detto che domani hai una valutazione e che stasera dovevi andare a letto presto?"
  },
  AvgDialog_49476_Content_20 = {
    Text = "Sì. Questa è Yakutsk, il luogo dove le tue memorie hanno avuto inizio... e dove mi hai incontrata per la prima volta in questo mondo."
  },
  AvgDialog_49476_Content_21 = {Text = "!!!"},
  AvgDialog_49476_Content_22 = {
    Text = "Custode, ci sono cose che hai dimenticato da tempo, ma io le ricordo ancora tutte."
  },
  AvgDialog_49476_Content_23 = {
    Text = "Qui ti ho perso, ancora e ancora. Ogni volta, è inciso vivido nella mia Memoria."
  },
  AvgDialog_49476_Content_24 = {
    Text = "Solo quell'unica volta sei disceso, muovendoti verso una Distruzione infinita, verso l'unico Bagliore di speranza... ma quel solo Bagliore non aveva nulla a che fare con me."
  },
  AvgDialog_49476_Content_25 = {
    Text = "Un dolore acuto ti trafigge il cuore come una Lama. Tendi le braccia e la stringi nel tuo Abbraccio."
  },
  AvgDialog_49476_Content_26 = {
    Text = "Questa volta, la tranquilla Giovane Donna che ha combattuto attraverso innumerevoli linee temporali non si sottrae."
  },
  AvgDialog_49476_Content_27 = {
    Text = "Si rannicchia docilmente tra le tue braccia, strofinando piano la testa contro il tuo petto, come un gatto che finalmente torna dal suo padrone dopo essere stato ferito."
  },
  AvgDialog_49476_Content_28 = {
    Text = "In questa Dimensione, hai molti compagni al tuo fianco. Doll, Czort, Alistair... e colei che è sempre stata con te, la me di questo mondo."
  },
  AvgDialog_49476_Content_29 = {
    Text = "Credo che procederai senza ostacoli e porterai a compimento ciò che intendi fare."
  },
  AvgDialog_49476_Content_3 = {
    Text = "Tempismo perfetto! Il professor Dexter mi ha appena detto che domani prepara il pranzo a casa. Possiamo andare direttamente da lui dopo la valutazione."
  },
  AvgDialog_49476_Content_30 = {
    Text = "Non avrei dovuto apparire così. Con l'esperienza di tante linee temporali, avrei dovuto essere più matura."
  },
  AvgDialog_49476_Content_31 = {
    Text = "Ma non voglio perderti di nuovo, Custode."
  },
  AvgDialog_49476_Content_32 = {
    Text = "Un liquido cristallino scivola dalla sua benda sull'occhio, scorrendo tra i capelli pallidi e lungo la guancia arrossata."
  },
  AvgDialog_49476_Content_33 = {
    Text = "La sua fronte preme contro la tua, i suoi capelli sfiorano dolcemente la tua guancia. Il tuo respiro si arresta mentre attraverso la morbida benda scorgi i suoi occhi assenti, vacillanti, colmi di lacrime."
  },
  AvgDialog_49476_Content_34 = {
    Text = "La sua voce fresca, lievemente tremante, sussurra al tuo orecchio, un alito caldo che ti sfiora, come innumerevoli teneri, flebili Deliri provenienti da tempi e spazi diversi."
  },
  AvgDialog_49476_Content_35 = {
    Text = "L'uniforme da Studente del Mythag, danneggiata da innumerevoli Battaglie, scivola dolcemente tra le tue mani."
  },
  AvgDialog_49476_Content_36 = {
    Text = "Possiamo semplicemente attribuire tutto questo all'influenza del Fiume sacro?"
  },
  AvgDialog_49476_Content_37 = {
    Text = "Oggi, lascia che sia capriccioso. Per l'ultima volta."
  },
  AvgDialog_49476_Content_4 = {
    Text = "Mi piacerebbe molto, Custode. È passato tanto tempo dall'ultima volta che ho visto mio padre... Tuttavia, temo di non essere adatta a presentarmi a casa sua."
  },
  AvgDialog_49476_Content_5 = {
    Text = "La stessa figura, la stessa voce, eppure priva di ogni traccia di ingenuità. Ciò che resta è una calma temprata da innumerevoli prove, e un accenno di inspiegabile, dissonante inquietudine."
  },
  AvgDialog_49476_Content_6 = {
    Text = "Seguendo quella voce, sotto la luce appare l'indimenticabile benda sull'occhio."
  },
  AvgDialog_49476_Content_7 = {Text = "Sei tu?"},
  AvgDialog_49476_Content_8 = {
    Text = "Perdonami. Avevo detto che non ti avrei disturbato, ma..."
  },
  AvgDialog_49476_Content_9 = {
    Text = "Sotto la sua benda nera, un rossore insolito affiora sul viso prima pallido."
  },
  AvgDialog_49742_Content_1 = {
    Text = "Hai chiesto a Tutti: Bambola, Erica, Sylvia, Czort, Hannah..."
  },
  AvgDialog_49742_Content_10 = {Text = "Custode..."},
  AvgDialog_49742_Content_11 = {
    Text = "Ramona arretra di un impercettibile mezzo passo, la sua Espressione improvvisamente distante e guardinga."
  },
  AvgDialog_49742_Content_12 = {
    Text = "Mi dispiace, per favore non avvicinarti per ora, io..."
  },
  AvgDialog_49742_Content_13 = {
    Text = "Il turbamento del Fiume sacro ha colpito molti Risvegliati. Pensavo... che sarei stata un'eccezione, dato che sono di Tawil..."
  },
  AvgDialog_49742_Content_14 = {
    Text = "Ramona è Ramona. Questo non cambierà mai."
  },
  AvgDialog_49742_Content_15 = {
    Text = "Io sono chi sono..."
  },
  AvgDialog_49742_Content_16 = {
    Text = "Sì. Esatto!"
  },
  AvgDialog_49742_Content_17 = {
    Text = "Avanzi di due passi decisi, ti fermi davanti a lei, poi le prendi la mano."
  },
  AvgDialog_49742_Content_18 = {
    Text = "Che sia a Rye o nei miei sogni, non importa quante volte me lo chiederai, la mia risposta resterà sempre la stessa."
  },
  AvgDialog_49742_Content_19 = {
    Text = "Una forza irresistibile ti attrae verso Ramona. Lei ti afferra mentre inciampi in avanti, le sue braccia si avvolgono attorno alla tua schiena, il mento appoggiato lievemente sulla tua spalla sinistra."
  },
  AvgDialog_49742_Content_2 = {
    Text = "Tutti ti hanno indicato la stessa direzione: attraversare il cortile del campus, spingere l'elaborato cancello di ferro alla fine del sentiero di Pietra."
  },
  AvgDialog_49742_Content_20 = {
    Text = "Mi hai calmata con sole due semplici frasi... Sono stata forse troppo tesa, ultimamente?"
  },
  AvgDialog_49742_Content_21 = {
    Text = "Sei solo troppo stanca. Lo siamo entrambi."
  },
  AvgDialog_49742_Content_22 = {
    Text = "Le tue mani si avvolgono istintivamente attorno alla sua vita. Il mondo ammutolisce intorno a voi; tutto ciò che potete udire è il respiro l'uno dell'altra, mentre traete un calore intimo dall'abbraccio."
  },
  AvgDialog_49742_Content_23 = {
    Text = "...Grazie, %player%."
  },
  AvgDialog_49742_Content_24 = {
    Text = "Ramona è la prima a sottrarsi a quell'abbraccio protettivo. Ti tiene per la spalla, vorrebbe dire qualcosa ma esita."
  },
  AvgDialog_49742_Content_25 = {
    Text = "C'è qualcos'altro che vuoi dirmi?"
  },
  AvgDialog_49742_Content_26 = {
    Text = "Niente. Non ancora."
  },
  AvgDialog_49742_Content_27 = {
    Text = "Ti dà un colpetto sulla spalla e indica il sentiero verso l'uscita."
  },
  AvgDialog_49742_Content_28 = {
    Text = "Torniamo indietro, per ora, va bene? Ti prometto: domani rivedrai la me di sempre."
  },
  AvgDialog_49742_Content_29 = {
    Text = "Per ora ha bisogno di più tempo e spazio, e tu lo comprendi perfettamente."
  },
  AvgDialog_49742_Content_3 = {
    Text = "Mentre entri nel Keygrave, le nubi temporalesche che covavano sopra di te scatenano finalmente il loro primo ruggito. Un lampo aspro e gelido guizza dal cielo, balzando verso l'orizzonte lontano."
  },
  AvgDialog_49742_Content_30 = {
    Text = "Ramona lascia sfuggire un pesante sospiro mentre osserva la figura del suo compagno svanire tra i monumenti di pietra."
  },
  AvgDialog_49742_Content_31 = {
    Text = "La gola le brucia come fuoco; ogni respiro simile al rantolo doloroso di un paziente — ma davanti al suo compagno, ha teso ogni nervo per celare il proprio tormento."
  },
  AvgDialog_49742_Content_32 = {
    Text = "Lentamente, si accascia dinanzi a una tomba a forma di chiave. Come guidata dal fato, preme le dieci dita delicatamente contro il nome inciso."
  },
  AvgDialog_49742_Content_33 = {
    Text = "Inclina il capo, le labbra si avvicinano lentamente alla fredda superficie della tavoletta di pietra, percependo il gelo del fato con il proprio calore."
  },
  AvgDialog_49742_Content_34 = {
    Text = "%player%..."
  },
  AvgDialog_49742_Content_35 = {
    Text = "Questo è il nome che non avrebbe mai dimenticato. Mai."
  },
  AvgDialog_49742_Content_4 = {
    Text = "Sta per piovere... Perché mai verrebbe al Keygrave con questo tempo?"
  },
  AvgDialog_49742_Content_5 = {
    Text = "È sempre stata astuta — \"Preparazione\" potrebbe essere il suo secondo nome. Rendere omaggio ai predecessori proprio quando inizia un acquazzone? Non è da lei."
  },
  AvgDialog_49742_Content_6 = {
    Text = "Ti fai strada tra le varie lapidi a forma di chiave e finalmente scorgi quella figura familiare in lontananza."
  },
  AvgDialog_49742_Content_7 = {
    Text = [[
Si trova al centro del gruppo di lapidi a forma di chiave erette nell'anno 315 D.F., chinando il capo davanti a una di esse.
Sembra immersa in un'emozione sconosciuta, ignara del tuo arrivo.]]
  },
  AvgDialog_49742_Content_8 = {
    Text = "Il vento freddo e umido che precede la pioggia spazza via ogni suono di vita; il Keygrave è una vasta tomba silenziosa. E Ramona resta lì, il suo mantello nero serrato stretto al corpo dalla bufera, come una solitaria e lugubre Custode di tombe."
  },
  AvgDialog_49742_Content_9 = {
    Text = "Ramona, sono io."
  },
  AvgDialog_49825_Content_1 = {
    Text = "Non è stato il sole mattutino di Mythag a strapparti dal sonno, ma una sensazione lacerante che ti percorreva il Sangue stesso."
  },
  AvgDialog_49825_Content_10 = {
    Text = "<Big:Come osi ribattere!>"
  },
  AvgDialog_49825_Content_11 = {
    Text = "Hmph... Si dice \"non c'è due senza tre.\" Oggi mi assicurerò che tu impari bene la lezione."
  },
  AvgDialog_49825_Content_2 = {
    Text = "Sembra di avere Mille aghi che pungono dall'interno — o le zampe frenetiche di artropodi che strisciano lungo le pareti interne delle tue vene. Il formicolio denso e pungente morde i tuoi nervi, costringendo il tuo Corpo a Spasmi incontrollabili."
  },
  AvgDialog_49825_Content_3 = {
    Text = "Smettila di far@2 finta di dormire! Lo so che sei sveglio!"
  },
  AvgDialog_49825_Content_4 = {
    Text = "Lotti per aprire gli Occhi, e la vista che ti si para davanti ti mozza il respiro in gola—"
  },
  AvgDialog_49825_Content_5 = {
    Text = "Un labirinto senza fine, la tana della Signora Cinerea. Una Giovane Donna con doppie pupille regna nel mezzo della sua Covata brulicante."
  },
  AvgDialog_49825_Content_6 = {
    Text = "Ammutolito? Non pensavo che queste piccole creature avessero il Potere di far marcire il cervello alla gente."
  },
  AvgDialog_49825_Content_7 = {
    Text = "Lascia stare, basta con le chiacchiere inutili... Ti ricordi? Prima di oggi, mi hai già rifiutato due volte."
  },
  AvgDialog_49825_Content_8 = {
    Text = "Ti è stata offerta la grande occasione di unirti alla propagazione della Signora Cinerea... E hai osato rifiutarmi!"
  },
  AvgDialog_49825_Content_9 = {
    Text = "Questo mio Corpo umano non è esattamente in grado di sopportare il \"tormento\" dei tuoi ragnetti..."
  },
  AvgDialog_49826_Content_1 = {
    Text = "Custode, sei stato tu?"
  },
  AvgDialog_49826_Content_10 = {
    Text = "E lo condividerò con te... Devi solo chiedere."
  },
  AvgDialog_49826_Content_11 = {
    Text = "Possiamo brandire questo Potere insieme. Unisciti a me, e abbraccia questa Evoluzione trascendente."
  },
  AvgDialog_49826_Content_2 = {
    Text = "Opera mia? Non affrettarti a puntarmi l'arma contro. Qualunque cosa stia accadendo, possiamo parlarne con calma..."
  },
  AvgDialog_49826_Content_3 = {
    Text = "Nel momento in cui varchi la soglia della stanza, Caecus si precipita verso di te con impazienza."
  },
  AvgDialog_49826_Content_4 = {
    Text = "La mia pinna dorsale brucia... e anche le pinne auricolari."
  },
  AvgDialog_49826_Content_5 = {
    Text = "Ti afferra il polso e guida la tua mano verso le sue pinne auricolari tremanti."
  },
  AvgDialog_49826_Content_6 = {
    Text = "Le pinne auricolari grigio-rosate, solitamente ricoperte da un muco idratante, dovrebbero risultare fredde e viscide al tatto, ma le tue dita percepiscono ora un'ondata rovente di calore."
  },
  AvgDialog_49826_Content_7 = {
    Text = "Hai la febbre? Vado subito a chiamare Lady Sylvia... e dato che sei un Risvegliato, dovremmo chiamare anche Doll per una diagnosi..."
  },
  AvgDialog_49826_Content_8 = {
    Text = "Prima che tu possa finire di parlare, Caecus fa scivolare la sua arma lungo il vano della porta, sbarrandola alle tue spalle. Il suo respiro, ora più vicino che mai, si fa pesante, saturo di umidità oceanica."
  },
  AvgDialog_49826_Content_9 = {
    Text = "No... Questa è la prova che mi sto evolvendo verso il vero Potere di Aequor."
  },
  AvgDialog_49836_Content_1 = {
    Text = "Bacio d'Addio"
  },
  AvgDialog_49836_Content_10 = {
    Text = "Ma innumerevoli persone hanno sacrificato le loro vite per una credenza morbosa."
  },
  AvgDialog_49836_Content_11 = {
    Text = "Questo è il Fato di ogni Aramita. Siamo nati qui e qui siamo cresciuti."
  },
  AvgDialog_49836_Content_12 = {
    Text = "E così permetti loro di aggrapparsi a questo rito maledetto, lasciando che cadano vittime del Muro della Tempesta, ancora e ancora?"
  },
  AvgDialog_49836_Content_13 = {
    Text = "Thais non offre risposta."
  },
  AvgDialog_49836_Content_14 = {
    Text = "Si è semplicemente avvicinata e ti ha abbracciato dolcemente."
  },
  AvgDialog_49836_Content_15 = {
    Text = "So che sei esausta, furiosa..."
  },
  AvgDialog_49836_Content_16 = {
    Text = "So che provi rancore verso di me. Non capisci il perché.\nMa ho le mie ragioni."
  },
  AvgDialog_49836_Content_17 = {
    Text = "Lascia che ti racconti una Storia — una molto lunga."
  },
  AvgDialog_49836_Content_18 = {
    Text = "Molto, molto tempo fa — millenni prima del Diluvio — una civiltà venerava una divinità chiamata l'Albero Madre."
  },
  AvgDialog_49836_Content_19 = {
    Text = "Ma la volontà dell'Albero era troppo sfuggente per stabilizzare il loro dominio. Per rimediare, l'impero ordì un piano terribile:"
  },
  AvgDialog_49836_Content_2 = {
    Text = "È calata la notte, e William si è ritirato."
  },
  AvgDialog_49836_Content_20 = {
    Text = "Selezionarono molte bambine, costringendole a bere la linfa cremisi dell'Albero Madre e a bagnarsi nei suoi succhi, finché una bambina non si fuse con successo con l'entità."
  },
  AvgDialog_49836_Content_21 = {
    Text = "Da quel momento, si disse che questa \"bambina fantoccio\" incarnasse la volontà divina dell'Albero."
  },
  AvgDialog_49836_Content_22 = {
    Text = "Ma nessuno l'ascoltò mai né obbedì alle sue parole. La bambina non aveva volontà propria; era soltanto un portavoce, che ripeteva i comandi recitati dal Re di Ninive."
  },
  AvgDialog_49836_Content_23 = {
    Text = "Un ministro gentile la salvò da quelle grinfie e le disse che poteva essere se stessa."
  },
  AvgDialog_49836_Content_24 = {
    Text = "La ragazza è riuscita a fuggire?"
  },
  AvgDialog_49836_Content_25 = {
    Text = "È fuggita."
  },
  AvgDialog_49836_Content_26 = {
    Text = "Ma la storia non finì lì."
  },
  AvgDialog_49836_Content_27 = {
    Text = "La ragazza fuggitiva si mescolò alla folla. Rannicchiata in un angolo e timorosa che qualcuno si avvicinasse, ricevette solo un pezzo di pane."
  },
  AvgDialog_49836_Content_28 = {
    Text = "Le diedero del pane, non perché fosse l'Imperatrice, non perché fosse l'agente dell'Albero Madre... ma semplicemente perché era una bambina."
  },
  AvgDialog_49836_Content_29 = {
    Text = "In quell'istante, la volontà della bambina risuonò con quella dell'Albero."
  },
  AvgDialog_49836_Content_3 = {
    Text = "Trai un respiro profondo, pronta a tornare alla tenda, quando Thais ti fa cenno da dietro di essa."
  },
  AvgDialog_49836_Content_30 = {
    Text = "Allora, l'Albero le chiese:"
  },
  AvgDialog_49836_Content_31 = {
    Text = "Diventerai il mio vascello, dando alla luce la mia carne e la mia anima?"
  },
  AvgDialog_49836_Content_32 = {
    Text = "Attraverso la prodigiosa armonia dell'anima, la bambina udì la voce dell'albero.\nQuella notte, apprese la conoscenza legata alla <Red:Fine Nera>."
  },
  AvgDialog_49836_Content_33 = {
    Text = "Fine Nera... intendi la Dissoluzione?"
  },
  AvgDialog_49836_Content_34 = {
    Text = "La bambina tornò al fianco dell'Albero, non più vincolata dai comandi del re. Tutto il popolo obbediva solo a lei, soggiogato dalla stirpe condivisa."
  },
  AvgDialog_49836_Content_35 = {
    Text = "Divenne un tutt'uno con l'Albero. Più che la propria sopravvivenza, il suo fardello era garantire che l'intera stirpe sfuggisse all'imminente rovina."
  },
  AvgDialog_49836_Content_36 = {
    Text = "Quando l'Impero di Ninive cadde, guidò un gruppo nel cuore profondo del deserto, attraverso tempeste mai calpestate, per preservare gli ultimi del suo popolo."
  },
  AvgDialog_49836_Content_37 = {
    Text = "E quelle persone divennero... i nomadi Aramiti?"
  },
  AvgDialog_49836_Content_38 = {
    Text = "Molto tempo dopo, la bambina svanì di nuovo."
  },
  AvgDialog_49836_Content_39 = {
    Text = "Nessuno udì la sua voce; nessuno cantò il suo nome."
  },
  AvgDialog_49836_Content_4 = {
    Text = "Vostra Maestà... Di cosa avete bisogno da me?"
  },
  AvgDialog_49836_Content_40 = {
    Text = "Ma tutti seguirono la sua volontà, riproducendosi disperatamente per sfuggire alla fine..."
  },
  AvgDialog_49836_Content_41 = {
    Text = "Per preservare il seme della loro stirpe quando l'inevitabile catastrofe si abbatterà su di loro."
  },
  AvgDialog_49836_Content_42 = {
    Text = "Ma gli Aramiti dipendono troppo dal Potere dell'Albero Madre."
  },
  AvgDialog_49836_Content_43 = {
    Text = "Quella dipendenza è come una fragile torre di sabbia: apparentemente solida, ma basta un'Ondata di marea a spazzarla via."
  },
  AvgDialog_49836_Content_44 = {
    Text = "Forse non lo capisci ancora; gli Aram non avevano altra scelta."
  },
  AvgDialog_49836_Content_45 = {
    Text = "Ma un giorno, tutti affronteremo lo stesso destino."
  },
  AvgDialog_49836_Content_46 = {
    Text = "Resti senza parole."
  },
  AvgDialog_49836_Content_47 = {
    Text = "Quando quel giorno inevitabile verrà... ricorda di chiamare il mio nome."
  },
  AvgDialog_49836_Content_48 = {
    Text = [[
Ti bacia dolcemente la fronte.
La tua mente vacilla, lei indietreggia di qualche passo, e tu allunghi la mano, ma non riesci a toccarla.]]
  },
  AvgDialog_49836_Content_49 = {
    Text = "Osservi la sua figura che si allontana, si fa sempre più piccola, fino a dissolversi in un granello, svanendo nella luce lunare immacolata."
  },
  AvgDialog_49836_Content_5 = {
    Text = "Domani c'è la cerimonia di rinascita dell'Albero madre, così sono venuta a trovarti.\nMio piccolo mostro, sei pronto?"
  },
  AvgDialog_49836_Content_6 = {
    Text = "Invece di chiedermi se sono pronto... non dovrebbe essere Sua Maestà a fare i preparativi adeguati?"
  },
  AvgDialog_49836_Content_7 = {
    Text = "O forse, avete fatto abbastanza preparativi?"
  },
  AvgDialog_49836_Content_8 = {
    Text = "Il volto fragile e malaticcio di Ramona appare davanti a te, alimentando la rabbia nel tuo petto."
  },
  AvgDialog_49836_Content_9 = {
    Text = "Non ho alcuna intenzione di nuocere a te o ai tuoi compagni, né agirei mai contro gli interessi di Aram."
  },
  AvgDialog_49837_Content_1 = {
    Text = "Punto di Convergenza"
  },
  AvgDialog_49837_Content_11 = {
    Text = "La cicatrice sulla sua fronte — lasciata dalla bruciatura inflittagli dalla madre folle — ora è un solco poco profondo, da cui trasuda una fanghiglia cremisi."
  },
  AvgDialog_49837_Content_12 = {
    Text = "La Chiave d'Argento si frantuma sul suo petto, i guanti standard di Mythag intrisi di sangue, una melma minacciosa che sgocciola verso l'alto in spregio alla gravità."
  },
  AvgDialog_49837_Content_13 = {
    Text = "Dietro quell'Incubo ondeggiante—"
  },
  AvgDialog_49837_Content_14 = {
    Text = "Un colossale cumulo di carne spalanca le sue fauci come una dionea."
  },
  AvgDialog_49837_Content_15 = {
    Text = "Le pieghe di placente e infanti deformi, nitide come marchi rosso sangue nella tua mente."
  },
  AvgDialog_49837_Content_16 = {
    Text = "Al centro della massa gonfia e contorta giace ciò che ha inseguito senza sosta, cercato — l'ultimo dono per il tuo viaggio."
  },
  AvgDialog_49837_Content_17 = {
    Text = "Ecco il nucleo di Nubia rivelato—"
  },
  AvgDialog_49837_Content_18 = {
    Text = "Una piccola Lanterna."
  },
  AvgDialog_49837_Content_2 = {
    Text = "L'inquietudine dilaga, il Terrore martella la tua mente."
  },
  AvgDialog_49837_Content_3 = {
    Text = "Corri verso l'accampamento ai piedi delle dune."
  },
  AvgDialog_49837_Content_4 = {
    Text = "Nell'istante in cui le tue dita sfiorano il lembo, il terrore ti sopraffà."
  },
  AvgDialog_49837_Content_6 = {
    Text = "Questo Terrore è diverso dall'affrontare il Segugio o il Feto Sacro..."
  },
  AvgDialog_49837_Content_7 = {
    Text = "È radicato nelle ossa, ineludibile, irreparabile — un Orrore indicibile."
  },
  AvgDialog_49837_Content_8 = {
    Text = "Un Incubo alla deriva, un Delirio deforme, una realtà insopportabile e soffocante."
  },
  AvgDialog_49837_Content_9 = {
    Text = "Un Mostro enorme e ferino ondeggia i suoi tentacoli viscidi, l'esile figura di William che penzola da essi come un giunco solitario."
  },
  AvgDialog_49838_Content_1 = {
    Text = "Punto di Convergenza"
  },
  AvgDialog_49838_Content_10 = {
    Text = "Trai un respiro profondo, pronta a tornare alla tenda, quando Thais ti fa cenno da dietro di essa."
  },
  AvgDialog_49838_Content_100 = {
    Text = "Ma un giorno, tutti affronteremo lo stesso destino."
  },
  AvgDialog_49838_Content_101 = {
    Text = "Resti senza parole."
  },
  AvgDialog_49838_Content_102 = {
    Text = "Quando quel giorno inevitabile verrà... ricorda di chiamare il mio nome."
  },
  AvgDialog_49838_Content_103 = {
    Text = "Ti posa un bacio lieve sulla fronte."
  },
  AvgDialog_49838_Content_104 = {
    Text = "La tua mente vacilla, e lei ondeggia all'indietro. Tendi la mano, ma è fuori dalla tua Portata."
  },
  AvgDialog_49838_Content_105 = {
    Text = "Osservi la sua figura che si allontana, si fa sempre più piccola, fino a dissolversi in un granello, svanendo nella luce lunare immacolata."
  },
  AvgDialog_49838_Content_11 = {
    Text = "Domani è il Rituale di Nascita dell'Albero Madre.\nCosa vorreste da me, adesso, Vostra Maestà?"
  },
  AvgDialog_49838_Content_12 = {
    Text = "Le parole escono più taglienti di quanto volessi."
  },
  AvgDialog_49838_Content_13 = {
    Text = "Io... l'ho visto.\nQuello che è successo al vostro compagno... mi dispiace tanto."
  },
  AvgDialog_49838_Content_14 = {
    Text = "Un inevitabile Silenzio aleggia tra voi."
  },
  AvgDialog_49838_Content_15 = {
    Text = "Questo non ha nulla a che fare con Aram."
  },
  AvgDialog_49838_Content_16 = {
    Text = "Non è colpa di Thais, ti ricordi — ma le tue parole pungono come un riccio guardingo tra le dune."
  },
  AvgDialog_49838_Content_17 = {
    Text = "Il Rituale di Nascita... anche voi avrete dei preparativi, giusto?"
  },
  AvgDialog_49838_Content_18 = {
    Text = "Cerchi di addolcire il tono, ma suona comunque come un freddo congedo."
  },
  AvgDialog_49838_Content_19 = {
    Text = "Dove pensate che andranno gli Aramiti una volta che l'Albero Madre rinascerà?"
  },
  AvgDialog_49838_Content_2 = {
    Text = "In questo viaggio, hai assistito a molte dipartite.\nMa mai la morte è sembrata così soffocantemente sommessa."
  },
  AvgDialog_49838_Content_20 = {
    Text = "Resti in silenzio."
  },
  AvgDialog_49838_Content_21 = {
    Text = "So perché Mythag è venuto a Remouahe, e so perché non hai ancora agito."
  },
  AvgDialog_49838_Content_22 = {
    Text = "Ti sono grata — hai dato ad Aram una possibilità."
  },
  AvgDialog_49838_Content_23 = {
    Text = "Ma quella possibilità non esiste più."
  },
  AvgDialog_49838_Content_24 = {
    Text = "Thais, lo sai che l'Albero Madre è contaminato dalla Dissoluzione, vero?"
  },
  AvgDialog_49838_Content_25 = {Text = "..."},
  AvgDialog_49838_Content_26 = {
    Text = "Lo so, io... l'ho sempre saputo."
  },
  AvgDialog_49838_Content_27 = {
    Text = "Allora dovresti capire che Mythag non resterà a guardare mentre la Dissoluzione si propaga."
  },
  AvgDialog_49838_Content_28 = {
    Text = "Fermerò la Rinascita dell'Albero Madre.\nThais, ora siamo nemici."
  },
  AvgDialog_49838_Content_29 = {
    Text = "Il mare di sabbia un tempo limpido si fa denso e vischioso; la polvere inalata graffia la gola, lasciando un dolore sordo."
  },
  AvgDialog_49838_Content_3 = {
    Text = [[
Fra tutte le persone, doveva essere proprio William.
L'investigatore leggendario di Mythag, il tuo mentore su questo cammino.]]
  },
  AvgDialog_49838_Content_30 = {
    Text = "Con tua sorpresa, Thais non si ritrae — si avvicina, avvolgendoti nel suo abbraccio."
  },
  AvgDialog_49838_Content_31 = {
    Text = "Dolce creatura, capisco."
  },
  AvgDialog_49838_Content_32 = {
    Text = "Non ho alcuna intenzione di nuocere a te o ai tuoi compagni, né agirei mai contro gli interessi di Aram."
  },
  AvgDialog_49838_Content_33 = {
    Text = "Ma gli Aramiti non hanno altra via. Molto tempo fa, il potere della Regina si affievolì — riusciva a malapena a proteggere l'Albero Madre."
  },
  AvgDialog_49838_Content_34 = {
    Text = "Fu necessario attingere alle linee telluriche di Remouahe, evocando il Muro della Tempesta per celarne la posizione."
  },
  AvgDialog_49838_Content_35 = {
    Text = "Vuoi dire... che il Muro della Tempesta è stato evocato dal potere della Regina?"
  },
  AvgDialog_49838_Content_36 = {
    Text = "Sì. Il Muro della Tempesta... respinge i falsi emissari."
  },
  AvgDialog_49838_Content_37 = {
    Text = "Ma ogni Rito costa così tante vite aramite!"
  },
  AvgDialog_49838_Content_38 = {
    Text = "Finché la nostra fertilità sopporta, gli Aramiti non si estingueranno."
  },
  AvgDialog_49838_Content_39 = {
    Text = "E così permetti loro di aggrapparsi a questo rito maledetto, lasciando che cadano vittime del Muro della Tempesta, ancora e ancora?"
  },
  AvgDialog_49838_Content_4 = {
    Text = "Chi potrebbe mai uccidere una leggenda come lui, in silenzio, a pochi passi di distanza?"
  },
  AvgDialog_49838_Content_40 = {
    Text = "Questo è il Fato di ogni Aramita. Siamo nati qui e qui siamo cresciuti."
  },
  AvgDialog_49838_Content_41 = {
    Text = "La vostra fede distorta ha ucciso innumerevoli persone!"
  },
  AvgDialog_49838_Content_42 = {
    Text = "Non solo la vostra gente... e ora anche William..."
  },
  AvgDialog_49838_Content_43 = {
    Text = "La tua voce si incrina appena; a stento la riconosci come tua."
  },
  AvgDialog_49838_Content_44 = {
    Text = "Dimmi, Thais — tu non credi davvero in tutto questo, vero?"
  },
  AvgDialog_49838_Content_45 = {
    Text = "Thais non offre risposta."
  },
  AvgDialog_49838_Content_46 = {
    Text = "Si limita a stringere la presa."
  },
  AvgDialog_49838_Content_47 = {
    Text = "So che sei esausta, furiosa..."
  },
  AvgDialog_49838_Content_48 = {
    Text = "So che provi rancore verso di me. Non capisci il perché.\nMa ho le mie ragioni."
  },
  AvgDialog_49838_Content_49 = {
    Text = "Lascia che ti racconti una Storia — una molto lunga."
  },
  AvgDialog_49838_Content_5 = {
    Text = "Barcollando debolmente all'indietro, crolli contro una figura slanciata."
  },
  AvgDialog_49838_Content_50 = {
    Text = "Molto, molto tempo fa — millenni prima del Diluvio — una civiltà venerava una divinità chiamata l'Albero Madre."
  },
  AvgDialog_49838_Content_51 = {
    Text = "Ma la volontà dell'Albero era troppo sfuggente per stabilizzare il loro dominio. Per rimediare, l'impero ordì un piano terribile:"
  },
  AvgDialog_49838_Content_52 = {
    Text = "Selezionarono molte bambine, costringendole a bere la linfa cremisi dell'Albero Madre e a bagnarsi nei suoi succhi, finché una bambina non si fuse con successo con l'entità."
  },
  AvgDialog_49838_Content_53 = {
    Text = "Da quel momento, si disse che questa \"bambina fantoccio\" incarnasse la volontà divina dell'Albero."
  },
  AvgDialog_49838_Content_54 = {
    Text = "Ma nessuno l'ascoltò mai né obbedì alle sue parole. La bambina non aveva volontà propria; era soltanto un portavoce, che ripeteva i comandi recitati dal Re di Ninive."
  },
  AvgDialog_49838_Content_55 = {
    Text = "Aveva quindici anni quando per la prima volta alzò la voce in segno di ribellione."
  },
  AvgDialog_49838_Content_56 = {
    Text = "Perché? Perché ucciderlo? È il padre di Amayet!"
  },
  AvgDialog_49838_Content_57 = {
    Text = "Ha violato il tabù, Thais. È fuggito dal campo di battaglia."
  },
  AvgDialog_49838_Content_58 = {
    Text = "La battaglia era perduta! Era l'unico sopravvissuto — non poteva combattere da solo contro tutti quei nemici!"
  },
  AvgDialog_49838_Content_59 = {
    Text = "Sei troppo giovane per capire la guerra, Thais."
  },
  AvgDialog_49838_Content_6 = {
    Text = "Capisco come ti senti, ma non è il momento di crollare."
  },
  AvgDialog_49838_Content_60 = {
    Text = "Avrebbe dovuto caricare in avanti e morire con onore."
  },
  AvgDialog_49838_Content_61 = {
    Text = "Non è meglio un sopravvissuto? Con lui in vita... Amayet potrebbe diventare un guerriero, anche suo fratello, e i futuri figli di Amayet..."
  },
  AvgDialog_49838_Content_62 = {
    Text = "La mia decisione è definitiva."
  },
  AvgDialog_49838_Content_63 = {
    Text = "Proclama il volere dell'Albero Madre: il peccatore sarà divorato vivo dagli insetti."
  },
  AvgDialog_49838_Content_64 = {
    Text = "NON HO DETTO QUESTO!"
  },
  AvgDialog_49838_Content_65 = {
    Text = "Proclama il volere dell'Albero Madre: il peccatore sarà divorato vivo dagli insetti."
  },
  AvgDialog_49838_Content_66 = {
    Text = "NON HO DETTO QUESTO!"
  },
  AvgDialog_49838_Content_67 = {
    Text = "Proclama il volere dell'Albero Madre: il peccatore sarà divorato vivo dagli insetti."
  },
  AvgDialog_49838_Content_68 = {
    Text = "Le grida disperate e laceranti della bambina rimasero inascoltate."
  },
  AvgDialog_49838_Content_69 = {
    Text = "C-chi sei tu?"
  },
  AvgDialog_49838_Content_7 = {
    Text = "Ci ha... lasciato le informazioni Chiave."
  },
  AvgDialog_49838_Content_70 = {
    Text = "Shh, piccola — tieni la voce bassa. E seguimi, presto."
  },
  AvgDialog_49838_Content_71 = {
    Text = "Non sei la prima marionetta. Ogni volta che una bambina tenta di opporsi a loro, viene sacrificata al Fiume Sacro."
  },
  AvgDialog_49838_Content_72 = {
    Text = "Sono nata bagnandomi nella linfa dell'Albero Madre — sono immortale!"
  },
  AvgDialog_49838_Content_73 = {
    Text = "Sciocca bambina, è una menzogna. Tutti annegano nell'acqua."
  },
  AvgDialog_49838_Content_74 = {
    Text = "Non lo farò."
  },
  AvgDialog_49838_Content_75 = {
    Text = "E tu chi saresti? Non ti ho mai visto prima."
  },
  AvgDialog_49838_Content_76 = {
    Text = "Pulisco il tuo giardino, andandomene prima dell'alba — così non mi hai mai vista."
  },
  AvgDialog_49838_Content_77 = {
    Text = "Ma conosci mio nipote. Si chiamava... Amayet."
  },
  AvgDialog_49838_Content_78 = {
    Text = "La bambina è fuggita?"
  },
  AvgDialog_49838_Content_79 = {Text = "No."},
  AvgDialog_49838_Content_8 = {
    Text = "La Chiesa della luce del tempio è dietro ai Nubia.\nDaffodil non bluffava: fermare il rituale è ormai indispensabile."
  },
  AvgDialog_49838_Content_80 = {
    Text = "La ragazza comprese molte cose in quell'istante. Un giardino contaminato non si pulisce da solo, e non riuscire a emettere un suono... è così doloroso."
  },
  AvgDialog_49838_Content_81 = {
    Text = "Si gettò volontariamente nel Fiume sacro."
  },
  AvgDialog_49838_Content_82 = {
    Text = "In quell'istante, la volontà della bambina risuonò con quella dell'Albero."
  },
  AvgDialog_49838_Content_83 = {
    Text = "Allora, l'Albero le chiese:"
  },
  AvgDialog_49838_Content_84 = {
    Text = "Diventerai il mio vascello, dando alla luce la mia carne e la mia anima?"
  },
  AvgDialog_49838_Content_85 = {
    Text = "Attraverso la prodigiosa armonia dell'anima, la bambina udì la voce dell'albero.\nQuella notte, apprese la conoscenza legata alla <Red:Fine Nera>."
  },
  AvgDialog_49838_Content_86 = {
    Text = "Fine Nera... intendi la Dissoluzione?"
  },
  AvgDialog_49838_Content_87 = {
    Text = "La bambina tornò al fianco dell'Albero, non più vincolata dai comandi del re. Tutto il popolo obbediva solo a lei, soggiogato dalla stirpe condivisa."
  },
  AvgDialog_49838_Content_88 = {
    Text = "Divenne un tutt'uno con l'Albero. Più che la propria sopravvivenza, il suo fardello era garantire che l'intera stirpe sfuggisse all'imminente rovina."
  },
  AvgDialog_49838_Content_89 = {
    Text = "Quando l'Impero di Ninive cadde, guidò un gruppo nel cuore profondo del deserto, attraverso tempeste mai calpestate, per preservare gli ultimi del suo popolo."
  },
  AvgDialog_49838_Content_9 = {
    Text = "Le stelle brillano nel vasto cielo notturno; la brezza del deserto placa infine i tuoi respiri affannosi."
  },
  AvgDialog_49838_Content_90 = {
    Text = "E quelle persone divennero... i nomadi Aramiti?"
  },
  AvgDialog_49838_Content_91 = {
    Text = "Molto tempo dopo, la bambina svanì di nuovo."
  },
  AvgDialog_49838_Content_92 = {
    Text = "Nessuno udì la sua voce; nessuno cantò il suo nome."
  },
  AvgDialog_49838_Content_93 = {
    Text = "Ma tutti seguirono la sua volontà, riproducendosi disperatamente per sfuggire alla fine..."
  },
  AvgDialog_49838_Content_94 = {
    Text = "Per preservare il seme della loro stirpe quando l'inevitabile catastrofe si abbatterà su di loro."
  },
  AvgDialog_49838_Content_95 = {
    Text = "Ma gli Aramiti dipendono troppo dal Potere dell'Albero Madre."
  },
  AvgDialog_49838_Content_96 = {
    Text = "Quella dipendenza è come una fragile torre di sabbia: apparentemente solida, ma basta un'Ondata di marea a spazzarla via."
  },
  AvgDialog_49838_Content_97 = {
    Text = "Ma non posso permettere loro di abbandonare con leggerezza nemmeno il più esile, il più Faint filo di speranza."
  },
  AvgDialog_49838_Content_98 = {
    Text = "Non capisco..."
  },
  AvgDialog_49838_Content_99 = {
    Text = "Per rendere gli addii meno dolorosi, i ricongiungimenti sono preziosi... non è necessario che tu capisca. Per ora."
  },
  AvgDialog_49865_Content_1 = {
    Text = "L'Albero Madre incombe irraggiungibile, graffiando il cielo."
  },
  AvgDialog_49865_Content_2 = {
    Text = "Tumori gonfi generano innumerevoli progenie; miriadi di Nubia si strappano dal grembo dell'albero, venendo alla luce."
  },
  AvgDialog_49865_Content_3 = {
    Text = "L'Albero Madre... sta producendo Nubia."
  },
  AvgDialog_49865_Content_4 = {
    Text = "Nati dalla carne degli Aramiti, con la Lanterna come nucleo... Fanciulli miei, miei poveri fanciulli corrotti..."
  },
  AvgDialog_49865_Content_5 = {
    Text = "Accarezza dolcemente una Nubia indebolita, tenera come una madre che culla un neonato addormentato."
  },
  AvgDialog_49865_Content_6 = {
    Text = "Poi, la testa della Nubia esplode nella sua stretta, schizzandole fanghiglia sulla guancia, aggiungendo un tocco di ferocia."
  },
  AvgDialog_49865_Content_7 = {
    Text = "Ritorno al mio grembo, al Fiume sacro — i vostri futuri incompiuti... sopravvivranno attraverso il sangue fino alla fine del mondo."
  },
  AvgDialog_49865_Content_8 = {
    Text = "Questo, ve lo prometto."
  },
  AvgDialog_49869_Content_1 = {
    Text = "Huff... huff..."
  },
  AvgDialog_49869_Content_10 = {Text = "...?"},
  AvgDialog_49869_Content_11 = {
    Text = "MIRYAM! Devono essere le sue macchinazioni alle mie spalle, che mi rendono incapace di... incapace di..."
  },
  AvgDialog_49869_Content_12 = {
    Text = "...Incapace di cosa?"
  },
  AvgDialog_49869_Content_13 = {
    Text = "Incapace di impedirmi di volerti stare più vicino... e..."
  },
  AvgDialog_49869_Content_14 = {
    Text = "RRRRIIIPP—!"
  },
  AvgDialog_49869_Content_15 = {
    Text = "Un istante dopo, il tuo pigiama viene strappato in due da cima a fondo."
  },
  AvgDialog_49869_Content_16 = {Text = "..."},
  AvgDialog_49869_Content_17 = {
    Text = "<Shake:Oh diavolo, non può essere quello che penso...>"
  },
  AvgDialog_49869_Content_18 = {
    Text = "Esatto! Voglio strapparti i vestiti di dosso, e poi..."
  },
  AvgDialog_49869_Content_19 = {
    Text = "Golia ti stringe il polso con forza, il suo volto arrossato quasi premuto contro il tuo."
  },
  AvgDialog_49869_Content_2 = {
    Text = "Un'altra notte tranquilla. Sprofondi nel morbido cuscino di piume, il tuo respiro regolare e sereno."
  },
  AvgDialog_49869_Content_20 = {
    Text = "Un respiro rovente ti sfiora l'orecchio, tingendo le tue guance di un rosa delicato."
  },
  AvgDialog_49869_Content_21 = {
    Text = "Non c'è più tempo! L'unico rimedio adesso è lasciarmi @4. Una volta finito, domani, faremo i conti con quella donna insieme."
  },
  AvgDialog_49869_Content_22 = {
    Text = "Dovrai accontentarti per stanotte... No. Dovresti ringraziarmi. Questo è un tuo onore!"
  },
  AvgDialog_49869_Content_23 = {
    Text = "@4?? Signor Golia, la prego, si contenga... non si avvicini!"
  },
  AvgDialog_49869_Content_24 = {
    Text = "<Big:Ramona! Doll! AIUTO—!!>"
  },
  AvgDialog_49869_Content_4 = {
    Text = "WAAAAAAGH!!"
  },
  AvgDialog_49869_Content_5 = {
    Text = "Una Lama pesante spacca in due il tuo lettino. Atterri di schiena sul pavimento, ogni briciola di Sonnolenza frantumata."
  },
  AvgDialog_49869_Content_6 = {
    Text = "Che sta succedendo?! È di nuovo l'Associazione degli Scultori?"
  },
  AvgDialog_49869_Content_7 = {
    Text = "Dall'Oscurità giunge un respiro roco e tremante. Una sagoma imponente incombe sulla testiera scheggiata."
  },
  AvgDialog_49869_Content_8 = {
    Text = "Così Forte, e così strano... questo afflusso di Potere..."
  },
  AvgDialog_49869_Content_9 = {
    Text = "Custode, potrei essere stato avvelenato da quella pazza."
  },
  AvgDialog_49870_Content_1 = {
    Text = "Il vento impetuoso e la pioggia battente là fuori non ti destano dal tuo tranquillo Sogno; nell'Oscurità, solo il tuo respiro sereno riecheggia."
  },
  AvgDialog_49870_Content_10 = {
    Text = "Meraviglioso... Stupefacente! Sì, proprio così!"
  },
  AvgDialog_49870_Content_11 = {
    Text = "Uno strumento dalla consistenza perfetta, morbido eppure saldo, che non lacera la mia pelle. Una forza calibrata alla perfezione, che non mi lascia segni sgradevoli... Squisito, il modo in cui mi hai colpita sulla testa, è davvero squisito."
  },
  AvgDialog_49870_Content_12 = {
    Text = "Le lodi di Leigh si fanno così teatrali che sembra quasi una cantante d'opera. Non nota nemmeno una Traiettoria di Sangue che le scivola lungo l'attaccatura dei capelli."
  },
  AvgDialog_49870_Content_13 = {
    Text = "...Ti porto a curare quella Ferita prima."
  },
  AvgDialog_49870_Content_14 = {
    Text = "La Ferita della signorina Leigh non è grave; si sarebbe rimarginata in pochi istanti."
  },
  AvgDialog_49870_Content_15 = {
    Text = "Ma io voglio davvero..."
  },
  AvgDialog_49870_Content_16 = {
    Text = "...Falle consumare una quantità moderata di Sangue."
  },
  AvgDialog_49870_Content_17 = {
    Text = "Davvero? È davvero permesso? Sei veramente così, così gentile—"
  },
  AvgDialog_49870_Content_18 = {
    Text = "...Tramite trasfusione endovenosa. Non viziarla."
  },
  AvgDialog_49870_Content_19 = {
    Text = "Sebbene abbia ricevuto l'amato Sangue, Leigh, confinata nel letto di degenza dall'ago della flebo e dalla sacca di Sangue, appare ancora languida, come una dalia appassita."
  },
  AvgDialog_49870_Content_2 = {
    Text = "Un lampo pallido squarcia la notte un istante prima che il tuono esploda, illuminando l'Ombra accanto alla finestra."
  },
  AvgDialog_49870_Content_20 = {
    Text = "Incapace di sostenere i Suoi Occhi colmi di Pianto, alla fine chiedi."
  },
  AvgDialog_49870_Content_21 = {
    Text = "Perché hai fatto irruzione nella mia Stanza stanotte?"
  },
  AvgDialog_49870_Content_22 = {
    Text = "...Io... Volevo..."
  },
  AvgDialog_49870_Content_23 = {
    Text = "Leigh balza in piedi all'improvviso, l'ago si strappa via, schizzando il suo stesso Sangue e quello della sacca ovunque su di lei."
  },
  AvgDialog_49870_Content_24 = {
    Text = "Affonda il viso nel tuo collo, il suo respiro gelido ti fa rabbrividire incontrollabilmente."
  },
  AvgDialog_49870_Content_25 = {
    Text = "Volevo il Sangue del Custode... Volevo te."
  },
  AvgDialog_49870_Content_3 = {
    Text = "Appare all'improvviso, muovendosi lentamente attraverso la camera da letto, sfruttando l'Oscurità. Nell'istante in cui si avvicina al tuo capezzale, portando un odore freddo e salmastro che rende il tuo cuscino umido e gelido—"
  },
  AvgDialog_49870_Content_4 = {Text = "—Bang!"},
  AvgDialog_49870_Content_5 = {
    Text = "Afferri la lampada da scrivania e la schianti con forza sulla testa dell'intruso."
  },
  AvgDialog_49870_Content_6 = {
    Text = "Mmm... Mm-hmm..."
  },
  AvgDialog_49870_Content_7 = {Text = "Leigh?!"},
  AvgDialog_49870_Content_8 = {
    Text = "Che ci fai nella mia Stanza?"
  },
  AvgDialog_49870_Content_9 = {Text = "Io..."},
  AvgDialog_49871_Content_1 = {
    Text = "Custode, avrai notato i recenti disordini nel campus."
  },
  AvgDialog_49871_Content_2 = {
    Text = "Ehm, in realtà non ho notato nulla... Ero impegnato con il rapporto sull'Evento Remouahe."
  },
  AvgDialog_49871_Content_3 = {
    Text = "Ma ora che lo menzioni, parecchi Risvegliati sono stati mandati in infermeria ultimamente... È successo qualcosa?"
  },
  AvgDialog_49871_Content_4 = {
    Text = "A causa dell'<Yellow:Evento Remouahe>, quasi tutti i Risvegliati stanno manifestando una sorta di... turbamento emotivo."
  },
  AvgDialog_49871_Content_5 = {
    Text = "Immagino che avrò altro da aggiungere al mio rapporto... Posso fare qualcosa?"
  },
  AvgDialog_49871_Content_6 = {
    Text = "La maggior parte dei Risvegliati ne è stata colpita, inclusa Doll. I Ricercatori stanno cercando modi per calmare tutti."
  },
  AvgDialog_49871_Content_7 = {
    Text = "Finché l'impatto non si sarà completamente placato, non abbassare la guardia con i Risvegliati. Potrebbero diventare una <Red:fonte di pericolo>."
  },
  AvgDialog_49880_Content_1 = {
    Text = "Una mano, rivestita di affilati copri-unghie, si muove tra la tua guancia e il collo. La sua punta acuminata slaccia infine la fibbia dell'uniforme scolastica, premendo un polpastrello contro la clavicola scoperta."
  },
  AvgDialog_49880_Content_10 = {
    Text = "Wanda strappa via bruscamente la tua benda. Socchiude gli occhi, un'aura di pressione insolita, ben diversa dalla mera brutalità, emana da lei."
  },
  AvgDialog_49880_Content_11 = {
    Text = "L'Ago Spinale sfiora la tua clavicola, gli Spuntoni ruvidi lacerano la pelle. Wanda chiude gli occhi, assaporando il profumo del Sangue fresco nell'aria, la sua Espressione è di totale sazietà."
  },
  AvgDialog_49880_Content_12 = {
    Text = "Poco dopo aver ucciso il mio quarto consorte, il mio regno su questo Pianeta incontrò la sua fine."
  },
  AvgDialog_49880_Content_13 = {
    Text = "A pensarci bene, è passato così tanto, tanto tempo dall'ultima volta che ho avuto uno sposo."
  },
  AvgDialog_49880_Content_14 = {
    Text = "L'Ago Spinale è sollevato in alto, un liquido vischioso si condensa sulla sua punta, sospeso vicino alla tua Ferita esposta."
  },
  AvgDialog_49880_Content_15 = {
    Text = "Ora è un buon momento, non credi?"
  },
  AvgDialog_49880_Content_16 = {
    Text = "Lontano da tumulti e Peste, libera da preoccupazioni e responsabilità... solo persone fidate intorno. Questa è davvero l'era migliore!"
  },
  AvgDialog_49880_Content_17 = {
    Text = "Wanda, è davvero questo che pensi?"
  },
  AvgDialog_49880_Content_18 = {
    Text = "Cosa intendi?"
  },
  AvgDialog_49880_Content_19 = {
    Text = "Nessuna preoccupazione, nessuna responsabilità..."
  },
  AvgDialog_49880_Content_2 = {
    Text = "Tu sei... una Risvegliatrice, giusto?"
  },
  AvgDialog_49880_Content_20 = {
    Text = "Scegliendo di affrontare la fine con Cambrian, non hai mai considerato la responsabilità come un fardello."
  },
  AvgDialog_49880_Content_21 = {
    Text = "Come fai a sapere del Cambrian —"
  },
  AvgDialog_49880_Content_22 = {
    Text = "Regina della stella aliena, prima di fare di me il tuo nuovo consorte, esamina attentamente il tuo cuore."
  },
  AvgDialog_49880_Content_23 = {
    Text = "L'influenza del Fiume sacro Remouahe non dovrebbe cambiarti."
  },
  AvgDialog_49880_Content_24 = {Text = "..."},
  AvgDialog_49880_Content_25 = {
    Text = "Hai ragione, piccolo animale domestico."
  },
  AvgDialog_49880_Content_26 = {
    Text = "L'atmosfera ammaliante si dissipa; l'Ago Spinale si raccoglie come la Marea che si ritira, oscillando inquieto dietro Wanda."
  },
  AvgDialog_49880_Content_27 = {
    Text = "Ora puoi andare. Stanotte non è ancora il momento."
  },
  AvgDialog_49880_Content_28 = {
    Text = "Non è ancora il momento?"
  },
  AvgDialog_49880_Content_29 = {
    Text = "I suoi servitori non-morti sciamano e ti spingono via, mentre Wanda emette uno sbuffo compiaciuto."
  },
  AvgDialog_49880_Content_3 = {
    Text = "Accecato dalla seta nera, i tuoi sensi sono amplificati all'estremo dall'Oscurità. Il suono dei copridita artigliati che scivolano sulla tua pelle si fonde con il respiro, inviando un brivido dal profondo della tua Anima."
  },
  AvgDialog_49880_Content_30 = {
    Text = "Una Regina non perde il senno né ritira le proprie parole, ma è davvero troppo presto per fare di te il mio successore."
  },
  AvgDialog_49880_Content_31 = {
    Text = "Va', mio piccolo animale. Ma sii preparato — ti richiamerò quando sarà il momento giusto."
  },
  AvgDialog_49880_Content_4 = {
    Text = "Ehi? Riesci a capire quello che dico?"
  },
  AvgDialog_49880_Content_5 = {
    Text = "Una risata lieve giunge dall'alto. Proprio mentre ti chiedi a chi appartenga, un Ago Spinale si avvolge attorno alla tua vita."
  },
  AvgDialog_49880_Content_6 = {
    Text = "È come un pitone gigante dal temperamento imprevedibile: quando è in preda alla Rabbia, i suoi speroni ossei ti trafiggono il corpo senza pietà; altre volte, si drappeggia pigramente sulla tua spalla."
  },
  AvgDialog_49880_Content_7 = {
    Text = "Ora scivola lungo il tuo corpo, la sua punta preme contro la tua gola — come un animale in un corteggiamento gentile, eppure simile a un Pugnale pericoloso."
  },
  AvgDialog_49880_Content_8 = {
    Text = "Wanda... sei proprio tu!"
  },
  AvgDialog_49880_Content_9 = {
    Text = "Hmph... Ci hai messo tutto questo tempo per riconoscere la tua padrona? Che animaletto incompetente."
  },
  AvgDialog_50760_Content_1 = {
    Text = "Fissi con sguardo vuoto i resti neri e appiccicosi davanti a te. Il tuo compagno, che poco fa era al tuo fianco, ora giace qui, per sempre a riposo su questo ghiacciaio perennemente coperto di neve."
  },
  AvgDialog_50760_Content_10 = {
    Text = "Alzi lo sguardo. Come una nube che oscura il sole, un'ombra immensa si erge dal fianco della scogliera, incombendo su di te."
  },
  AvgDialog_50760_Content_11 = {
    Text = "Sul corpo del mostro colossale è inciso un enorme simbolo— lo hai già visto nei tuoi sogni."
  },
  AvgDialog_50760_Content_12 = {
    Text = "Quella è... la Chiesa dei Portaluce!!!"
  },
  AvgDialog_50760_Content_13 = {Text = "BOOM!"},
  AvgDialog_50760_Content_14 = {
    Text = "<Shake:AHHHH—>"
  },
  AvgDialog_50760_Content_15 = {
    Text = "Grande {Male=Sig. Custode,Female=Sig.na Custode}!!!"
  },
  AvgDialog_50760_Content_16 = {
    Text = "Un oggetto colossale si libra nell'aria e si schianta al suolo. Con un boato assordante che squarcia la cima della montagna, polverizza la roccia sotto i tuoi piedi."
  },
  AvgDialog_50760_Content_17 = {
    Text = "Hai mancato un appoggio e sei caduto nella valle profonda insieme a Helot."
  },
  AvgDialog_50760_Content_18 = {
    Text = "—Tra le tue grida di terrore, Helot sorrise e rise per la prima volta."
  },
  AvgDialog_50760_Content_2 = {Text = "Ugh—"},
  AvgDialog_50760_Content_3 = {
    Text = "Innumerevoli esploratori sono morti sulla montagna innevata, ma morti così tragiche e un numero così elevato di vittime sono senza precedenti per la guida."
  },
  AvgDialog_50760_Content_4 = {
    Text = "Non riusciva più a resistere, le spalle che tremavano mentre conati violenti lo scuotevano."
  },
  AvgDialog_50760_Content_5 = {
    Text = "Anche loro sono stati Dissolti... La Dissoluzione qui sta progredendo così rapidamente..."
  },
  AvgDialog_50760_Content_6 = {
    Text = "Quei mostri in fuga, insieme alle reazioni di questi membri del team, sono decisamente troppo anomali..."
  },
  AvgDialog_50760_Content_7 = {
    Text = "Ora siamo solo noi. Dobbiamo scendere dalla montagna in fretta, altrimenti..."
  },
  AvgDialog_50760_Content_8 = {Text = "Boom—"},
  AvgDialog_50760_Content_9 = {
    Text = "Prima che potesse finire la frase, tutto divenne nero."
  },
  AvgDialog_50761_Content_1 = {
    Text = "Il ghiacciaio ruggisce di nuovo, iniziando a mutare la sua posizione a un ritmo estremamente lento."
  },
  AvgDialog_50761_Content_10 = {
    Text = "Andarcene... Non abbiamo mai avuto il diritto di andarcene."
  },
  AvgDialog_50761_Content_11 = {
    Text = "L'ossessione e la follia negli occhi dell'altra \"Helot\" svanirono all'improvviso."
  },
  AvgDialog_50761_Content_12 = {
    Text = "Guardò Helot con un senso di compostezza e calma senza precedenti."
  },
  AvgDialog_50761_Content_13 = {
    Text = "Hai dimenticato le cose che un tempo ti hanno ferita, l'odio radicato, \"Helot\"?"
  },
  AvgDialog_50761_Content_14 = {
    Text = "Non ho mai dimenticato... È solo che io..."
  },
  AvgDialog_50761_Content_15 = {
    Text = "Sei disorientata, \"Helot\"."
  },
  AvgDialog_50761_Content_16 = {
    Text = "Solo con un Potere sufficiente potremo compiere la nostra vendetta. La vendetta è il nostro unico scopo."
  },
  AvgDialog_50761_Content_17 = {
    Text = "Vendetta... ma contro chi?"
  },
  AvgDialog_50761_Content_18 = {Text = "Il destino"},
  AvgDialog_50761_Content_19 = {
    Text = "Quelle due parole calme fecero tremare violentemente il corpo di Helot."
  },
  AvgDialog_50761_Content_2 = {
    Text = "Questa volta, il Lago di Ghiaccio a lungo celato rivelò la sua vera forma. Scorgi una figura esile ricoperta di pustole nere sulla superficie del lago."
  },
  AvgDialog_50761_Content_20 = {
    Text = "Non importa dove siamo, questa montagna ci chiama e ci divora."
  },
  AvgDialog_50761_Content_21 = {
    Text = "Questo è il nostro destino, proprio come le cose immonde che abbiamo vissuto..."
  },
  AvgDialog_50761_Content_22 = {
    Text = "Conoscevi la risposta fin dall'inizio, ma hai scelto di ignorarla, vero?"
  },
  AvgDialog_50761_Content_23 = {
    Text = "Rispetto alle persone e alle cose che odi, il destino è un avversario ben più terrificante..."
  },
  AvgDialog_50761_Content_24 = {
    Text = "Non meriti di essere chiamato \"guerriero,\" codardo."
  },
  AvgDialog_50761_Content_25 = {
    Text = "Il tuo corpo non può più resistere... Morirai qui."
  },
  AvgDialog_50761_Content_26 = {
    Text = "Anche così... e allora?"
  },
  AvgDialog_50761_Content_27 = {
    Text = "Volge il viso verso di te, rivelando un paio di zanne astute con un ghigno."
  },
  AvgDialog_50761_Content_28 = {
    Text = "La luce della lanterna mi ha ingannata facendomi venire qui, con l'intenzione di usarmi per risvegliare @3. La montagna mi sta chiamando, cercando di divorarmi. Lo sapevo fin dall'inizio, eppure sono venuta lo stesso."
  },
  AvgDialog_50761_Content_29 = {
    Text = "Se la montagna desidera vedermi, andrò da lei."
  },
  AvgDialog_50761_Content_3 = {
    Text = "La fessura nel lago ghiacciato si sta allargando, come una lunga ferita che si estende sulla superficie sotto l'infinito ghiacciaio."
  },
  AvgDialog_50761_Content_30 = {
    Text = "Devo ringraziare la lanterna per avermi dato l'occasione di affrontarLo..."
  },
  AvgDialog_50761_Content_31 = {
    Text = "Sei una tale codarda, eppure sei venuta lo stesso, non è vero?"
  },
  AvgDialog_50761_Content_32 = {
    Text = "Io sono il tuo futuro, \"Helot.\" Quando avrai il coraggio di alzare la spada contro il destino, diventerai me."
  },
  AvgDialog_50761_Content_33 = {
    Text = "Le pustole nere si moltiplicarono, come uno sciame di creature primordiali affamate, che inghiottivano avidamente il suo corpo e le risalivano sulle guance."
  },
  AvgDialog_50761_Content_34 = {
    Text = "Rise come una bestia che sbrana avidamente carne cruda, come un re in procinto di ascendere al Trono."
  },
  AvgDialog_50761_Content_35 = {
    Text = "Guarda, \"Helot\"... Lo divorerò, diventerò più forte, e nessun destino potrà più ostacolarmi!"
  },
  AvgDialog_50761_Content_36 = {
    Text = "Niente più catene... niente più... tradimenti..."
  },
  AvgDialog_50761_Content_37 = {
    Text = "Le pustole nere si diffondono e si accumulano su di lei, scavando nel suo corpo tormentato, coprendole il volto con un misto di calma e follia..."
  },
  AvgDialog_50761_Content_38 = {
    Text = "Mi... <Big:Vendicherò!!!>"
  },
  AvgDialog_50761_Content_39 = {Text = "Bang—"},
  AvgDialog_50761_Content_4 = {
    Text = "Le pustole nere continuano a fuoriuscire, ricoprendo un'altra \"Helot\"."
  },
  AvgDialog_50761_Content_40 = {
    Text = "Come una pustola scoppiata, fluidi neri e rossi schizzano ovunque."
  },
  AvgDialog_50761_Content_41 = {
    Text = [[
L'ultimo ruggito della bestia riecheggia ancora nella valle.
Dove un tempo si ergeva, non resta che una pozza di liquido.]]
  },
  AvgDialog_50761_Content_42 = {
    Text = "\"Vendetta\"... eh..."
  },
  AvgDialog_50761_Content_43 = {
    Text = "Helot alza la testa confuso, fissando il cielo bianco-grigiastro."
  },
  AvgDialog_50761_Content_44 = {
    Text = "Fiocchi di neve grossolani scivolarono sulla sua pelle, sciogliendosi in piccole macchie d'acqua."
  },
  AvgDialog_50761_Content_45 = {
    Text = "È stata... inghiottita dalla montagna?"
  },
  AvgDialog_50761_Content_46 = {Text = "@2...@3..."},
  AvgDialog_50761_Content_47 = {
    Text = "Prima che Helot potesse parlare, la tua domanda aveva già trovato risposta—"
  },
  AvgDialog_50761_Content_48 = {
    Text = "Il terreno sotto i piedi inizia a tremare. Dalle profondità delle montagne giunge un richiamo basso e immondo..."
  },
  AvgDialog_50761_Content_5 = {
    Text = "Riesco a sentirlo... ancora, datemi ancora!"
  },
  AvgDialog_50761_Content_6 = {
    Text = "Quelle strane pustole percepirono il suo richiamo, ronzando eccitate, precipitandosi verso la sua bocca, cercando attivamente di farsi divorare."
  },
  AvgDialog_50761_Content_7 = {
    Text = "Sembrano godere nell'essere tagliate, venerare l'essere inghiottite e bramare di essere divorate."
  },
  AvgDialog_50761_Content_8 = {
    Text = "Ti avvicini a un'altra \"Helot\". Il suo corpo è sommerso in una vescica oscura, la sua forma così eterea da sembrare un filo di nebbia, facilmente dissipabile."
  },
  AvgDialog_50761_Content_9 = {
    Text = "Vattene ora, finché ne hai ancora la possibilità..."
  },
  AvgDialog_50762_Content_1 = {
    Text = "Non c'è tempo per pensare. Spinto dall'istinto di sopravvivenza, strisci attraverso la melma secreta dalla caverna, dirigendoti verso l'uscita che si restringe lentamente."
  },
  AvgDialog_50762_Content_10 = {
    Text = "Polvere mista a granelli di neve si disperde davanti ai tuoi occhi."
  },
  AvgDialog_50762_Content_11 = {
    Text = "Una crepa squarciò il tunnel completamente buio, e una luce bianca abbagliante si riversò sulle mie spalle."
  },
  AvgDialog_50762_Content_12 = {
    Text = "Tieniti forte, ti tiro fuori io."
  },
  AvgDialog_50762_Content_13 = {
    Text = "Frantumò le rocce della caverna e ti estrasse dalle macerie."
  },
  AvgDialog_50762_Content_14 = {
    Text = "Il debito che avevo con te è ora ripagato..."
  },
  AvgDialog_50762_Content_15 = {Text = "...Ah!!"},
  AvgDialog_50762_Content_16 = {Text = "Helot!!..."},
  AvgDialog_50762_Content_17 = {
    Text = "Prima che potesse finire la frase, inciampò all'improvviso."
  },
  AvgDialog_50762_Content_18 = {
    Text = "—Il terreno che un tempo era un pendio svanì nel nulla, trasformandosi in un abisso senza fondo in un istante."
  },
  AvgDialog_50762_Content_2 = {
    Text = "Ci sei quasi, ancora un po' —"
  },
  AvgDialog_50762_Content_3 = {
    Text = "<Big:Boom—>"
  },
  AvgDialog_50762_Content_4 = {
    Text = "L'intera montagna viene capovolta, l'angolazione del tunnel cambia improvvisamente e precipita rapidamente verso il basso."
  },
  AvgDialog_50762_Content_5 = {
    Text = "La melma sotto di te è scivolosa, rendendo difficile trovare un appiglio. Lotti per avvicinarti all'ingresso illuminato della caverna mentre il tunnel si contorce sempre più violentemente."
  },
  AvgDialog_50762_Content_6 = {
    Text = "Le lastre di roccia tiepide continuano a contrarsi, comprimendoti il petto e rendendo sempre più difficile respirare. Persino il corpo di Lily è incastrato nella fessura, incapace di muoversi."
  },
  AvgDialog_50762_Content_7 = {
    Text = "L'unica uscita viene gradualmente divorata da rocce nere, tagliando il sentiero vicino e sprofondandoti nell'oscurità totale."
  },
  AvgDialog_50762_Content_8 = {
    Text = "Non posso... restare qui..."
  },
  AvgDialog_50762_Content_9 = {Text = "BOOM!"},
  AvgDialog_50763_Content_1 = {
    Text = "Helot si accovaccia, imitando la tua postura, accarezzando goffamente i morbidi capelli di Lily."
  },
  AvgDialog_50763_Content_10 = {
    Text = "Conficcò la spada nella roccia. Ciocche di capelli bagnati le caddero sul viso, ghiacciandosi rapidamente in stalattiti, tremando insieme alle sue spalle."
  },
  AvgDialog_50763_Content_11 = {
    Text = "Il vento gelido della montagna innevata infuria senza sosta, con rombi che echeggiano incessantemente."
  },
  AvgDialog_50763_Content_12 = {
    Text = "Ondata dopo ondata di dolore acuto la attraversava, ma in quel momento, la voce nella sua mente era cristallina."
  },
  AvgDialog_50763_Content_13 = {
    Text = "Ci sono molte cose che non voglio fare, molte... cose a cui sono costretta e spinta a fare."
  },
  AvgDialog_50763_Content_14 = {
    Text = "<Change>Consegnala... a... me!"
  },
  AvgDialog_50763_Content_15 = {
    Text = "Hai perso persino la capacità di parlare?"
  },
  AvgDialog_50763_Content_16 = {
    Text = [[
In tal caso, metti le tue parole e i tuoi sentimenti nella tua spada.
Fammi sentire la tua rabbia in battaglia!]]
  },
  AvgDialog_50763_Content_17 = {
    Text = "Sono stata tradita molte, molte volte."
  },
  AvgDialog_50763_Content_18 = {
    Text = "Perché? Perché? Devo vedere la Signora!"
  },
  AvgDialog_50763_Content_19 = {
    Text = "Non provarci. Credi ancora di essere la nobile figlia adottiva del magistrato?"
  },
  AvgDialog_50763_Content_2 = {
    Text = "Lily era mezza sepolta nella montagna, le sue lacrime nere scorrevano senza sosta, i suoi occhi vacui fissi su Helot."
  },
  AvgDialog_50763_Content_20 = {
    Text = "Il sangue corrotto può generare solo una <Blue:traditrice> come te."
  },
  AvgDialog_50763_Content_21 = {
    Text = [[
<BigShake:RISPONDIMI!>
Sono stata abbandonata?!]]
  },
  AvgDialog_50763_Content_22 = {
    Text = "In termini di risultato, sì, ma..."
  },
  AvgDialog_50763_Content_23 = {
    Text = "La sua mano tremante non riusciva più a reggere l'elsa; la spada lunga emetteva un ronzio metallico per i tremori della roccia."
  },
  AvgDialog_50763_Content_24 = {
    Text = "Un tempo pensavo che la vendetta fosse tutto per me... Ma oggi mi rendo conto di averne frainteso il significato e di aver preso di mira l'avversario sbagliato."
  },
  AvgDialog_50763_Content_25 = {
    Text = "Solo con un Potere sufficiente potremo compiere la nostra vendetta. La vendetta è il nostro unico scopo."
  },
  AvgDialog_50763_Content_26 = {
    Text = "Se la montagna desidera vedermi, andrò da lei."
  },
  AvgDialog_50763_Content_27 = {
    Text = "Io sono il tuo futuro, \"Helot.\" Quando avrai il coraggio di alzare la spada contro il destino, diventerai me."
  },
  AvgDialog_50763_Content_28 = {
    Text = [[
Quindi, vuoi vendicarti del traditore e proteggere Francis, giusto?
Ma la battaglia non riguarda questo.]]
  },
  AvgDialog_50763_Content_29 = {
    Text = "Non per protezione, non per vendetta, non per conferme.\nCombattere è solo combattere."
  },
  AvgDialog_50763_Content_3 = {
    Text = "Ha sopportato abbastanza sofferenze. Lascia che me ne occupi io."
  },
  AvgDialog_50763_Content_30 = {
    Text = "Il tuo mondo è troppo piccolo, sempre a inseguire il faint bagliore della luce altrui come una falena."
  },
  AvgDialog_50763_Content_31 = {
    Text = "Se ne avrai l'occasione, vai a esplorare un mondo più vasto."
  },
  AvgDialog_50763_Content_32 = {
    Text = "Lascia la presa! Non resisterai a lungo."
  },
  AvgDialog_50763_Content_33 = {
    Text = "Io... non..."
  },
  AvgDialog_50763_Content_34 = {
    Text = "Lascia la presa... Morirai se continui così!"
  },
  AvgDialog_50763_Content_35 = {
    Text = "Non abbandonerò mai nessun compagno, a qualunque costo... Mai!"
  },
  AvgDialog_50763_Content_36 = {Text = "..."},
  AvgDialog_50763_Content_38 = {
    Text = "Lotan disse: \"La battaglia è solo battaglia, non per protezione né per vendetta.\""
  },
  AvgDialog_50763_Content_39 = {
    Text = "Ci ho riflettuto a lungo, e finalmente capisco perché tu e il tuo Risvegliatore siete così potenti..."
  },
  AvgDialog_50763_Content_4 = {
    Text = "No... No, non può finire così... Deve esserci un altro modo..."
  },
  AvgDialog_50763_Content_40 = {
    Text = "Credo che Lotan si sbagliasse. Forse, non se ne rendeva conto nemmeno lei."
  },
  AvgDialog_50763_Content_41 = {
    Text = "Lotan, Lily, tu... tutti voi avete qualcosa da proteggere."
  },
  AvgDialog_50763_Content_42 = {
    Text = "Custodire è il ruolo a cui sono destinata."
  },
  AvgDialog_50763_Content_43 = {
    Text = "Questa lezione me l'hai insegnata tu, Custode."
  },
  AvgDialog_50763_Content_44 = {Text = "\"Boom—\""},
  AvgDialog_50763_Content_45 = {
    Text = "La montagna tremò violentemente ancora una volta, e lo spesso ghiaccio sul lago si incrinò centimetro dopo centimetro."
  },
  AvgDialog_50763_Content_46 = {
    Text = "Sotto i frammenti infranti, pustole nere emergono e si diffondono come una zuppa in ebollizione."
  },
  AvgDialog_50763_Content_47 = {
    Text = "Helot, non abbandonerò mai i miei compagni!"
  },
  AvgDialog_50763_Content_48 = {
    Text = "Non mi piace essere in debito con gli altri. Tu mi hai salvata, quindi dopo oggi saremo pari."
  },
  AvgDialog_50763_Content_49 = {
    Text = "Riesco a percepire un'altra \"Helot\"... Mi sta aspettando tra le montagne. Vuole unirsi a me per vendicarsi del destino."
  },
  AvgDialog_50763_Content_5 = {
    Text = "Non c'è più tempo, Custode."
  },
  AvgDialog_50763_Content_50 = {
    Text = "Non hai abbandonato nessuno. Percorriamo il resto del cammino da soli."
  },
  AvgDialog_50763_Content_51 = {
    Text = "Siamo guerrieri. I guerrieri sono nati per combattere."
  },
  AvgDialog_50763_Content_52 = {
    Text = "Questo è il destino che abbiamo scelto per noi stessi... Questa è la nostra battaglia con la montagna."
  },
  AvgDialog_50763_Content_53 = {
    Text = "Helot estrae la spina nera."
  },
  AvgDialog_50763_Content_54 = {
    Text = "Nubi dense avvolgono la montagna innevata, impedendo alla luce del sole di raggiungere il suolo."
  },
  AvgDialog_50763_Content_55 = {
    Text = "Il corpo di Helot è avviluppato da un muco nero, legato dalle catene di una follia inconscia, imprigionandola in strati di ceppi."
  },
  AvgDialog_50763_Content_56 = {Text = "..."},
  AvgDialog_50763_Content_58 = {
    Text = "Con le catene sulle fragili spalle, avanzava a fatica. Il suo corpo, oppresso da pesanti ceppi, faticava a respirare e crollò sulla neve."
  },
  AvgDialog_50763_Content_59 = {Text = "Helot..."},
  AvgDialog_50763_Content_6 = {
    Text = "L'unico modo per lasciare Elworth vivi e non trasformarvi di nuovo in mostri davanti a me è questo..."
  },
  AvgDialog_50763_Content_60 = {
    Text = "Infiniti sussurri di tabù riempiono le loro orecchie. Nel suono viscoso e oscuro, Helot ode la risonanza delle montagne e dei battiti del cuore."
  },
  AvgDialog_50763_Content_61 = {
    Text = "Tum, tum, tum..."
  },
  AvgDialog_50763_Content_62 = {
    Text = "Sotto lo strato di roccia gelata e dura, il gigante risvegliato mormora con impazienza, bramandola."
  },
  AvgDialog_50763_Content_63 = {
    Text = "Si ergeva sulla vetta."
  },
  AvgDialog_50763_Content_64 = {
    Text = "Le cime frenetiche si agitarono, il suolo tremò violentemente e il vento gelido e feroce strappava i vestiti sottili di Helot, ma lei rimase immobile."
  },
  AvgDialog_50763_Content_65 = {
    Text = "Un'ondata di melma nera sgorga dalla cima della montagna innevata, circondandola come un'onda imponente—"
  },
  AvgDialog_50763_Content_66 = {
    Text = "@3Ritorna... Distruggi @2... Dimentica @3@2... Vieni... Torna a @3..."
  },
  AvgDialog_50763_Content_67 = {
    Text = "...Ritorna@3"
  },
  AvgDialog_50763_Content_68 = {
    Text = "Se vinceremo, il ghiaccio e la neve di Elworth si scioglieranno. Allora, riappariremo insieme."
  },
  AvgDialog_50763_Content_69 = {
    Text = "Aspetta, Custode."
  },
  AvgDialog_50763_Content_7 = {
    Text = "Morirai qui!"
  },
  AvgDialog_50763_Content_70 = {
    Text = "Helot gira brevemente la testa. Ti sembra di vedere un fugace sorriso attraversarle il volto."
  },
  AvgDialog_50763_Content_71 = {
    Text = "Si voltò, sollevando la spina nera verso l'eterna fiamma blu—"
  },
  AvgDialog_50763_Content_72 = {
    Text = "Battaglia, inizio."
  },
  AvgDialog_50763_Content_74 = {
    Text = "Fu al contempo una dichiarazione e un comando. Innumerevoli melme nere caddero all'improvviso, inghiottendo tutto sulla vetta."
  },
  AvgDialog_50763_Content_75 = {
    Text = "Le Montagne di Elworth tremarono. La catena montuosa continua sollevò una nebbia di ghiaccio lattiginosa, con masse rigide e goffe che si dibattevano e contorcevano disperatamente, come se lottassero contro qualcosa."
  },
  AvgDialog_50763_Content_76 = {
    Text = "Le nubi infuocate vengono spazzate da venti furiosi, e un vortice immenso inghiotte l'intera vetta. Un potere terrificante erutta in modo incontrollabile, come se stesse squarciando il cielo..."
  },
  AvgDialog_50763_Content_77 = {Text = "..."},
  AvgDialog_50763_Content_78 = {
    Text = "Il tempo passò senza che nessuno se ne accorgesse. La polvere finalmente si posò, e il terreno sotto i piedi smise di tremare."
  },
  AvgDialog_50763_Content_79 = {
    Text = "Lily, tornata alla normalità, si avvicina e ti prende per mano."
  },
  AvgDialog_50763_Content_8 = {
    Text = "\"Anche così... che importa?\""
  },
  AvgDialog_50763_Content_80 = {
    Text = "Helot... se n'è andato."
  },
  AvgDialog_50763_Content_81 = {
    Text = "Le montagne respirano con ritmo costante. Alzi la testa e guardi il cielo."
  },
  AvgDialog_50763_Content_82 = {
    Text = "Grossi fiocchi di neve cadono, accumulandosi sulla tua testa e tingendo i tuoi capelli di grigio."
  },
  AvgDialog_50763_Content_83 = {
    Text = "Elworth è inquietantemente silenziosa, come se nulla fosse mai accaduto."
  },
  AvgDialog_50764_Content_1 = {
    Text = "Vino e notizie, amerai entrambi. Buon Riposo, Custode."
  },
  AvgDialog_50764_Content_2 = {
    Text = "Dexter ti rivolse con grazia un lieve inchino e chiuse delicatamente la porta."
  },
  AvgDialog_50764_Content_3 = {
    Text = "A volte, trovandomi di fronte al Professor Dexter, rimpiango di non aver studiato la retorica più a fondo."
  },
  AvgDialog_50764_Content_4 = {
    Text = "Raccolse il giornale che Dexter aveva lasciato."
  },
  AvgDialog_50764_Content_5 = {
    Text = "\"Recentemente, una grande valanga si è verificata nelle montagne perennemente innevate di Elworth. Strani segni di disgelo hanno ora iniziato a manifestarsi...\""
  },
  AvgDialog_50764_Content_6 = {
    Text = "Girasti rapidamente la testa e afferrasti il giornale."
  },
  AvgDialog_50764_Content_7 = {
    Text = "L'immagine sfocata stampata a inchiostro mostra che la tempesta di neve sulle montagne si è fermata."
  },
  AvgDialog_50764_Content_8 = {
    Text = "Un minuscolo dente di leone spunta attraverso la neve perenne, facendo capolino."
  },
  AvgDialog_50764_Content_9 = {
    Text = "Ad accogliere la prima primavera di Elworth."
  },
  AvgDialog_50895_Content_1 = {
    Text = "Non... riesco più a resistere..."
  },
  AvgDialog_50895_Content_10 = {
    Text = "Un lamento familiare risuona ancora su Remouahe, ma più sommesso questa volta, come una brezza gentile."
  },
  AvgDialog_50895_Content_11 = {
    Text = "Nella foschia, intravedi quella figura familiare davanti al Portale, che si volta a guardarti..."
  },
  AvgDialog_50895_Content_2 = {
    Text = "Ramona tossisce sangue. Colpisce il suolo e diventa nero pece."
  },
  AvgDialog_50895_Content_3 = {
    Text = "Due forze taglienti si scontrano nella sua mente; Stridi d'argento e Impeti del Sangue flagellano la sua coscienza nel caos."
  },
  AvgDialog_50895_Content_4 = {
    Text = "È questa la fine...?"
  },
  AvgDialog_50895_Content_5 = {
    Text = "Ansimi, la Visuale offuscata dal sangue e dal sudore che colano, solo la forza di volontà ti tiene in piedi."
  },
  AvgDialog_50895_Content_6 = {
    Text = "È finita così? Sei allo stremo, eppure l'Embrione dell'Albero Madre si gonfia, si deforma, si riproduce senza fine..."
  },
  AvgDialog_50895_Content_7 = {Text = "Click—"},
  AvgDialog_50895_Content_8 = {
    Text = "Piume fredde e soffici si sciolgono in gocce d'argento, rotolando silenziosamente lungo la tua guancia macchiata di sangue, lasciando tracce simili a lacrime di Argento Puro."
  },
  AvgDialog_50895_Content_9 = {
    Text = "Per Mythag, per il futuro dell'Umanità... Ti prego, resisti ancora un po'."
  },
  AvgDialog_50896_Content_1 = {
    Text = "L'enorme tumore dell'Albero Madre esplode per un sottile Affondo di Spada; il plasma sprizza, inzuppandoti in una pioggia stillante di Sangue."
  },
  AvgDialog_50896_Content_10 = {Text = "Juliette!"},
  AvgDialog_50896_Content_11 = {
    Text = "Juliette si appollaia su un ramo, sospirando dall'alto. Accarezza i rami simili a braccia dell'Albero Madre mentre oscillano selvaggiamente, come per calmare una bestia in preda alla frenesia."
  },
  AvgDialog_50896_Content_12 = {
    Text = "O grande Albero Madre, ti prego, emergi dal flusso della vita."
  },
  AvgDialog_50896_Content_13 = {
    Text = "Disperdi le tue nere benedizioni nel deserto, e costruisci scale verso il nuovo mondo."
  },
  AvgDialog_50896_Content_14 = {
    Text = "Nessuna pietà per i peccatori! In cerca di Redenzione, gli Aramiti hanno deciso da tempo di offrirti tutto ciò che possiedono."
  },
  AvgDialog_50896_Content_15 = {
    Text = "Crac, crac — le ossa si spezzano in Coro; la carne degli Aramiti si fonde visibilmente nei rami, tumori pulsanti si agitano, si dissolvono, si ricombinano."
  },
  AvgDialog_50896_Content_16 = {
    Text = "Innumerevoli progenie e carni si coagulano in un riproduttore deforme; il tronco tremante si stabilizza gradualmente."
  },
  AvgDialog_50896_Content_17 = {
    Text = "Che la Lanterna Brilli Eterna."
  },
  AvgDialog_50896_Content_2 = {
    Text = "*Coff, coff...*"
  },
  AvgDialog_50896_Content_3 = {
    Text = "La pioggia di Sangue selvaggia colpisce Ramona più duramente di te; si asciuga il sangue rappreso dai capelli, tossendo violentemente."
  },
  AvgDialog_50896_Content_4 = {
    Text = "Ramona, tu..."
  },
  AvgDialog_50896_Content_5 = {
    Text = "Sto bene—posso resistere. Guarda il tumore!"
  },
  AvgDialog_50896_Content_6 = {
    Text = "Il tumore squarciato si affloscia come carne dissanguata; il tronco un tempo fiero trema, come se esprimesse un terrore e un disagio innaturali."
  },
  AvgDialog_50896_Content_7 = {
    Text = "L'Albero Madre... sta crollando?"
  },
  AvgDialog_50896_Content_8 = {
    Text = "No, non ancora..."
  },
  AvgDialog_50896_Content_9 = {
    Text = "Che tragedia—perché sprecare energie in tanta futilità?"
  },
  AvgDialog_50897_Content_1 = {
    Text = "L'Albero Madre sta ancora producendo Nubia...!"
  },
  AvgDialog_50897_Content_2 = {
    Text = "Perdonami—la contaminazione causata da Juliette è profonda. Finché la Purificazione di Tawil non sarà completa, non posso controllare le azioni dell'Albero Madre."
  },
  AvgDialog_50897_Content_3 = {
    Text = "In quanto Eone del Desiderio, è un mio fallimento. Per questo, ti presterò la mia Autorità."
  },
  AvgDialog_50897_Content_4 = {
    Text = "Ora hai la possibilità di brandire il Potere di Tifere Yesod. Non è un'occasione che capita facilmente."
  },
  AvgDialog_50897_Content_5 = {
    Text = "Usalo quanto vuoi. Non Sprecare nemmeno una goccia, intesi?"
  },
  AvgDialog_51150_Content_1 = {Text = "Horla?"},
  AvgDialog_51150_Content_10 = {
    Text = "Tutte queste cose sono apparse nella mia raccolta di poesie. Ogni cosa qui è esattamente come l'avevo immaginata nei miei poemi..."
  },
  AvgDialog_51150_Content_11 = {
    Text = "{Male=Sig.,Female=Sig.na} Custode, questa non è la vera Cité."
  },
  AvgDialog_51150_Content_12 = {
    Text = "Questa è la <Yellow:Cité della mia immaginazione>..."
  },
  AvgDialog_51150_Content_13 = {
    Text = "Sotto il cielo stellato di Via March, Horla girava lentamente su se stessa, contemplando tutto ciò che era descritto nelle sue poesie."
  },
  AvgDialog_51150_Content_14 = {
    Text = "La luce del sole cadeva come un velo, illuminando il suo viso curioso, malinconico e perplesso."
  },
  AvgDialog_51150_Content_15 = {
    Text = "Capisco... Non c'è da stupirsi che vi siano tante cose bizzarre qui."
  },
  AvgDialog_51150_Content_16 = {
    Text = "Ma come ha fatto Cité a ridursi così..."
  },
  AvgDialog_51150_Content_17 = {
    Text = "Non lo so nemmeno io... E alcune cose qui non corrispondono esattamente alla mia poesia. Quel pittore avrebbe dovuto essere un vecchietto molto adorabile..."
  },
  AvgDialog_51150_Content_18 = {
    Text = "Ma credo che, se vogliamo risolvere la questione qui, potremmo dover trovare prima quel Poema."
  },
  AvgDialog_51150_Content_19 = {
    Text = "Ricordi ancora la strada?"
  },
  AvgDialog_51150_Content_2 = {
    Text = "Ah, mi scusi, {Male=Sig.,Female=Sig.na} Custode, ero solo sovrappensiero..."
  },
  AvgDialog_51150_Content_20 = {
    Text = "Nella mia poesia, via March è vicina al Focolare. Ricordo sempre la via del ritorno."
  },
  AvgDialog_51150_Content_21 = {
    Text = "Sorrise in direzione dei bassifondi."
  },
  AvgDialog_51150_Content_22 = {
    Text = "Andiamo, {Male=Sig.,Female=Sig.na} Custode, ci dirigiamo al Giardino di rose... là dove sono morta."
  },
  AvgDialog_51150_Content_3 = {
    Text = "Ho un'ipotesi... No, ne sono certo."
  },
  AvgDialog_51150_Content_4 = {
    Text = "Questa non è Cité!"
  },
  AvgDialog_51150_Content_5 = {
    Text = "...Horla, cosa stai dicendo?"
  },
  AvgDialog_51150_Content_6 = {
    Text = "Ah, intendo dire, questa non è la vera Cité."
  },
  AvgDialog_51150_Content_7 = {
    Text = "Questa non è la vera Cité...?"
  },
  AvgDialog_51150_Content_8 = {
    Text = "Il Treno Bruco che richiede un Poema come biglietto, Madame Farfalla, solo il numero 99 di via March, il Pittore, le Stelle di Daisy..."
  },
  AvgDialog_51150_Content_9 = {
    Text = "Ho sempre trovato queste cose così familiari. Solo poco fa ho finalmente ricordato."
  },
  AvgDialog_51254_Content_1 = {
    Text = "Purifica la tua anima; la Fatica si dissolve, uno Spirito indomito arde nel tuo petto."
  },
  AvgDialog_51254_Content_2 = {
    Text = "Grazie, Tawil..."
  },
  AvgDialog_51254_Content_3 = {
    Text = "Porterò la tua volontà fino alla fine.\nPossa la Chiave d'argento illuminare il tuo cammino."
  },
  AvgDialog_51254_Content_4 = {
    Text = "Che la Chiave d'Argento ci Guidi."
  },
  AvgDialog_51998_Content_1 = {
    Text = "Le beffe dei filistei echeggiano nella stanza. Il Capitano Filisteo scuote il capo, afferra Talis per i capelli e tira fuori un pugnale."
  },
  AvgDialog_51998_Content_10 = {
    Text = "\"Mi hai fatto ricordare. Dovrei buttare via tutto ciò che appartiene a Golia per non destare i sospetti di Glenn.\""
  },
  AvgDialog_51998_Content_11 = {
    Text = "\"Per questo, posso rendere la tua morte meno dolorosa... Oh?\""
  },
  AvgDialog_51998_Content_2 = {
    Text = "Si volta verso Miryam. Una statuetta gli penzola dalla cintura. Lei spalanca improvvisamente gli occhi."
  },
  AvgDialog_51998_Content_3 = {
    Text = "\"Dove hai trovato quella statuetta?\""
  },
  AvgDialog_51998_Content_4 = {
    Text = "\"Ehi... Quindi sai parlare, eh? Ti credevo una mezza deficiente.\""
  },
  AvgDialog_51998_Content_5 = {
    Text = "\"La statuetta, da dove viene?\""
  },
  AvgDialog_51998_Content_6 = {
    Text = "Il capitano posa il coltello e abbassa lo sguardo sulla statuetta appesa alla cintura."
  },
  AvgDialog_51998_Content_7 = {
    Text = "La statua è fatta di un antico materiale di pietra opaca, raffigurante un giovane seduto su un trono. Alcuni strani tentacoli si estendono caoticamente, oscurando il volto del giovane."
  },
  AvgDialog_51998_Content_8 = {
    Text = "\"Heh... questo? È stato trovato dal precedente capo, Golia. Mi ha ricompensato per il mio coraggio.\""
  },
  AvgDialog_51998_Content_9 = {
    Text = "\"Ho rischiato la vita per lui, e questa è la ricompensa che mi ha dato. Cianfrusaglie inutili lasciate da chissà quale stupida civiltà.\""
  },
  AvgDialog_51999_Content_1 = {Text = "Boom—"},
  AvgDialog_51999_Content_10 = {
    Text = "\"Anche tu sei inseguita e braccata da una Volontà Superiore — proprio come Questa Persona. Un'anima senza padrone, senza più alcun luogo a cui appartenere.\""
  },
  AvgDialog_51999_Content_11 = {
    Text = "\"I Lemuriani venerano dèi spietati e re deboli. Il Reame Divino... Hah, che noia.\""
  },
  AvgDialog_51999_Content_2 = {
    Text = "Un suono soffocato penetra attraverso numerose spesse pareti di pietra, echeggiando nella camera da letto del Tempio."
  },
  AvgDialog_51999_Content_3 = {
    Text = "Tulu siede sul Trono, il mento appoggiato su una mano, le palpebre pesanti di Esaurimento."
  },
  AvgDialog_51999_Content_4 = {
    Text = "I Lemuriani sono caduti nel Riposo Eterno. Egli ha consumato tutto il suo potere per concedere loro un bel sogno, un miraggio della sua promessa."
  },
  AvgDialog_51999_Content_5 = {
    Text = "\"Le tempeste di Lemuria si placheranno. L'abisso di Lemuria svanirà.\""
  },
  AvgDialog_51999_Content_6 = {
    Text = "\"Il Re farà da scudo al suo popolo gentile e porterà il Reame Divino.\""
  },
  AvgDialog_51999_Content_7 = {
    Text = "\"Che ironia. È questa la tua volontà, 'Dio di Lemuria'?\""
  },
  AvgDialog_51999_Content_8 = {
    Text = "Alza il capo. Il suo sguardo penetra le lastre del tetto, la pioggia battente e le nuvole che si fondono, raggiungendo il cielo stellato profondo e il sogno profondo delle costellazioni."
  },
  AvgDialog_51999_Content_9 = {
    Text = "\"Sei già morto. Non ti è mai importato di Lemuria.\""
  },
  AvgDialog_52000_Content_1 = {
    Text = "La Virtù delle Menzogne"
  },
  AvgDialog_52000_Content_10 = {
    Text = "Questo re, lodato innumerevoli volte dai Lemuriani, si trovava davanti a Miryam per la prima volta."
  },
  AvgDialog_52000_Content_11 = {
    Text = "Dopo aver varcato questa porta, alcuni piangeranno, alcuni impazziranno, e alcuni hanno persino tentato di uccidermi."
  },
  AvgDialog_52000_Content_2 = {
    Text = "Fissa lo sguardo sulla vasca."
  },
  AvgDialog_52000_Content_3 = {
    Text = "Innumerevoli teste viscide emergono, poi risprofondano. Salgono, e affondano. Luride increspature turbano la superficie."
  },
  AvgDialog_52000_Content_4 = {
    Text = "Occhi prodigiosi sporgenti su entrambi i lati, che ruotano vacui protendendosi verso di lui. Le loro bocche dalle labbra sottili si aprono e chiudono, mormorando sillabe inesplicabili, come se tentassero di chiedergli qualcosa."
  },
  AvgDialog_52000_Content_5 = {
    Text = "Alle sue spalle, le porte d'ardesia si aprono scorrendo."
  },
  AvgDialog_52000_Content_6 = {
    Text = "Lode al nostro Signore... Lode al grande Re di Lemuria..."
  },
  AvgDialog_52000_Content_7 = {
    Text = "Ogni volta che incontro un sommo sacerdote per la prima volta, sento sempre questa battuta sarcastica."
  },
  AvgDialog_52000_Content_8 = {
    Text = "L'imponente corona di Lemuria rifletteva un debole bagliore da una fonte sconosciuta nella stanza, apparendo sproporzionata sul corpo del ragazzo, eppure non sembrava fuori posto sulla sua testa, come se fosse naturalmente parte di lui."
  },
  AvgDialog_52000_Content_9 = {
    Text = "I Suoi occhi in dormiveglia percorrono il volto di Miryam, le sopracciglia che fremono come l'esalazione del mare. La quiete maschera il Suo volto giovanile, occultando ogni emozione fanciullesca."
  },
  AvgDialog_52001_Content_1 = {
    Text = "Ma non importa, il mio signore comprende la vostra paura. La nostra amicizia non cambierà a causa di questi insulti."
  },
  AvgDialog_52001_Content_10 = {
    Text = "Vieni, prega con me, Deborah."
  },
  AvgDialog_52001_Content_11 = {
    Text = "No... Miryam... ti prego..."
  },
  AvgDialog_52001_Content_12 = {
    Text = "Ripeti con me: \"La sofferenza sarà ricompensata...\""
  },
  AvgDialog_52001_Content_13 = {
    Text = "La... la Sofferenza... no, Miryam..."
  },
  AvgDialog_52001_Content_14 = {
    Text = "Ripeti con me: \"Gli empi saranno flagellati — poiché il Signore giudica la loro iniquità.\""
  },
  AvgDialog_52001_Content_15 = {
    Text = "Miryam recita le preghiere mentre si avvicina al fianco della sua amica."
  },
  AvgDialog_52001_Content_16 = {
    Text = "Lasciami dire una cosa a Nord! Miryam... solo una parola per lui..."
  },
  AvgDialog_52001_Content_17 = {
    Text = "AAAHHHH!!—"
  },
  AvgDialog_52001_Content_18 = {
    Text = "L'agonia divampa nel suo addome. Alza lo sguardo e vede la mano pallida e serpentina di Miryam affondare il pugnale in profondità, tracciando un sentiero cremisi attraverso il suo ventre."
  },
  AvgDialog_52001_Content_19 = {
    Text = "Miryam è sorda alle urla laceranti. Non vede il volto stravolto dal terrore e dal dolore."
  },
  AvgDialog_52001_Content_2 = {
    Text = "Con reverenza, posa l'idolo di Tulu accanto all'altare e si inchina dinanzi ad esso."
  },
  AvgDialog_52001_Content_20 = {
    Text = "Il pugnale si muoveva con fermezza, spruzzando sangue caldo sul volto di Miryam. Lei cantava devotamente, incamminandosi sul sentiero verso il Reame Divino."
  },
  AvgDialog_52001_Content_21 = {Text = "..."},
  AvgDialog_52001_Content_22 = {
    Text = "Uccidete Miryam! Dividete la famiglia Ornn! Lunga vita alla nostra alleanza! Applausi!"
  },
  AvgDialog_52001_Content_23 = {
    Text = "I bicchieri tintinnano mentre la bramosia sfrenata si mescola all'aroma di vino e carne."
  },
  AvgDialog_52001_Content_24 = {
    Text = "Golia si lecca le labbra, assaporando quel sapore inebriante."
  },
  AvgDialog_52001_Content_25 = {
    Text = "Avanti, continua. Che ti prende?"
  },
  AvgDialog_52001_Content_26 = {
    Text = "Il... il tuo volto..."
  },
  AvgDialog_52001_Content_27 = {
    Text = "La mia faccia?"
  },
  AvgDialog_52001_Content_28 = {
    Text = "Guarda le piastrelle simili a specchi accanto a sé e scorge un volto che somiglia a un pesce."
  },
  AvgDialog_52001_Content_29 = {Text = "ARGH!!"},
  AvgDialog_52001_Content_3 = {
    Text = "Sia lodato il Signore... Lemuria, il Grande Re... Stanotte, do il benvenuto al tuo ritorno."
  },
  AvgDialog_52001_Content_30 = {
    Text = "Ferite si aprono sul suo petto come intagliate da pugnali invisibili. Le orecchie e le sopracciglia svaniscono; i bulbi oculari si gonfiano e migrano ai lati della testa."
  },
  AvgDialog_52001_Content_31 = {
    Text = "L'agonia trafigge la nebbia dell'alcol e dell'adrenalina. Crolla a terra, vomitando dal dolore, le mani che graffiano freneticamente il volto."
  },
  AvgDialog_52001_Content_32 = {
    Text = "Cos'è questo? Ah!!"
  },
  AvgDialog_52001_Content_33 = {
    Text = "Uno, due, tre... nella lussuosa sala del banchetto, i nobili cadono a terra uno dopo l'altro."
  },
  AvgDialog_52001_Content_34 = {
    Text = "Squarci cremisi compaiono sui loro corpi, sangue e carne che formano antichi, grotteschi disegni."
  },
  AvgDialog_52001_Content_35 = {
    Text = "I loro lamenti d'agonia convergono in una grandiosa sinfonia. Il sangue spruzza, colmando ogni calice."
  },
  AvgDialog_52001_Content_36 = {
    Text = "Questo è... questo è... un rito degli Abissali!"
  },
  AvgDialog_52001_Content_37 = {
    Text = "Certo, il Rituale dei Murloc. Dovreste tutti sapere della tragedia che colpì la famiglia Ornn."
  },
  AvgDialog_52001_Content_38 = {
    Text = "Perché... Golia?"
  },
  AvgDialog_52001_Content_39 = {Text = "Perché?"},
  AvgDialog_52001_Content_4 = {
    Text = "Abbi pazienza. Le stelle si stanno muovendo verso l'allineamento."
  },
  AvgDialog_52001_Content_40 = {
    Text = "Golia sembra udire una battuta esilarante. Si alza dal seggio e impugna la sua lama."
  },
  AvgDialog_52001_Content_41 = {
    Text = "Collaborando con voi avrei ottenuto un misero lembo di territorio degli Ornn."
  },
  AvgDialog_52001_Content_42 = {
    Text = "Ma collaborando con Miryam, ottengo un potere che va oltre la vostra comprensione. Posso trasformare le vostre intere casate in uomini-pesce e impossessarmi di tutte le vostre ricchezze."
  },
  AvgDialog_52001_Content_43 = {
    Text = "Ditemi, signor Edmond, se foste al mio posto, cosa scegliereste?"
  },
  AvgDialog_52001_Content_44 = {
    Text = "Noi... non ci arrenderemo senza combattere!"
  },
  AvgDialog_52001_Content_45 = {
    Text = "Esatto! Golia, sull'onore della famiglia Enom, noi—ugh!"
  },
  AvgDialog_52001_Content_46 = {
    Text = "Una lama immensa cala, scindendo in due il giovane nobile. Il suo onore muore con lui."
  },
  AvgDialog_52001_Content_47 = {
    Text = "Le porte si spalancano e una marea di uomini-pesce inonda la sala."
  },
  AvgDialog_52001_Content_48 = {
    Text = "...Dove sono le guardie?"
  },
  AvgDialog_52001_Content_49 = {
    Text = "Mentre voi brindevate e bevevate, noi stavamo già massacrando le vostre guardie personali."
  },
  AvgDialog_52001_Content_5 = {
    Text = "Si alza e cammina verso Deborah con passo gentile. Un bizzarro pugnale cerimoniale brilla nella sua mano pallida."
  },
  AvgDialog_52001_Content_50 = {
    Text = "Quanto ai vostri eserciti fuori dalla città... non disturbatevi a cercare di contattarli."
  },
  AvgDialog_52001_Content_51 = {
    Text = "Il sangue macchia ogni angolo della sala. Le urla riecheggiano sulle pareti come una sinfonia dall'Inferno."
  },
  AvgDialog_52001_Content_52 = {
    Text = "Coloro che non hanno bevuto il vino contaminato tremano, i corpi troppo deboli persino per sguainare una spada o fuggire."
  },
  AvgDialog_52001_Content_53 = {
    Text = "Golia ammira il capolavoro sanguinario, assaporando il terrore sui loro volti. Sospira con soddisfazione e solleva la sua lama immensa."
  },
  AvgDialog_52001_Content_54 = {
    Text = "Bevete il vino e diventate uomini-pesce, o perite qui. Fate la vostra scelta."
  },
  AvgDialog_52001_Content_55 = {Text = "..."},
  AvgDialog_52001_Content_56 = {
    Text = "AAAHHHH!!—"
  },
  AvgDialog_52001_Content_57 = {
    Text = "Un urlo lacerante colpisce le tavolette di pietra, producendo un'eco cupa e greve."
  },
  AvgDialog_52001_Content_58 = {
    Text = "Tenta di divincolarsi, di fuggire, ma Miryam la tiene salda. Non riesce a muoversi di un solo passo."
  },
  AvgDialog_52001_Content_59 = {
    Text = "Vorrebbe svenire, ma la sua mente resta dolorosamente lucida, costretta ad affrontare l'agonia e la paura."
  },
  AvgDialog_52001_Content_6 = {
    Text = "No! Miryam! Ti supplico... ti prego... non farlo..."
  },
  AvgDialog_52001_Content_60 = {
    Text = "Ripeti dopo di me: \"I devoti saranno abbracciati — poiché il Signore contempla la loro devozione.\""
  },
  AvgDialog_52001_Content_61 = {
    Text = "Il sangue di Deborah schizza sulla figura di Miryam. Ricorda di aver fatto lo stesso a suo padre sull'altare del tempio, molti anni fa."
  },
  AvgDialog_52001_Content_62 = {
    Text = "L'addio non è che il preludio a un più grandioso ricongiungimento, non è vero, mio Signore?"
  },
  AvgDialog_52001_Content_63 = {
    Text = "Fissa intensamente l'addome di Deborah mentre la sua lama si muove per completare l'ultimo tratto del diagramma."
  },
  AvgDialog_52001_Content_64 = {
    Text = "Avanti, Deborah. Parla. 'Le anime anelanti...'"
  },
  AvgDialog_52001_Content_65 = {
    Text = "La mano di Miryam affonda nel proprio ventre, rimestando e lacerando."
  },
  AvgDialog_52001_Content_66 = {
    Text = "La voce rauca di Deborah stride nell'agonia. I suoi occhi iniettati di sangue si spalancano nella follia, fissi sulle proprie viscere."
  },
  AvgDialog_52001_Content_67 = {
    Text = "\"...sarà esaudita — poiché il Signore ode le loro preghiere.\""
  },
  AvgDialog_52001_Content_68 = {
    Text = "Miryam strappa qualcosa via. Dovrebbe essere doloroso, ma Deborah non lo sente più."
  },
  AvgDialog_52001_Content_69 = {
    Text = "La sua mente si è intorpidita; le emozioni e i sensi l'hanno abbandonata."
  },
  AvgDialog_52001_Content_7 = {
    Text = "Guardami, Deborah. Guardami negli occhi."
  },
  AvgDialog_52001_Content_70 = {
    Text = "Vede vagamente Miryam estrarre una massa sanguinolenta dal suo addome aperto."
  },
  AvgDialog_52001_Content_71 = {
    Text = "Sa... Sa..."
  },
  AvgDialog_52001_Content_72 = {
    Text = "Sarah. Miryam le aveva detto che era il nome della sua sorella minore."
  },
  AvgDialog_52001_Content_73 = {
    Text = "Lei e Nord avevano concordato di chiamare così la loro figlia, ma non ebbe mai l'occasione di dirlo a Miryam."
  },
  AvgDialog_52001_Content_74 = {
    Text = "<Italic:Chiamatela Sarah...> Le labbra di Deborah si muovono, ma non riesce più a trovare la voce."
  },
  AvgDialog_52001_Content_75 = {
    Text = "\"Signore, possano i nostri inni perforare le tenebre abissali, affinché possiamo ascendere con Te — nel vuoto eterno, dove silenzio e follia regnano come un'unica cosa.\""
  },
  AvgDialog_52001_Content_76 = {
    Text = "Miryam bacia teneramente la sua figlioccia, le labbra macchiate dal sangue dell'infante. Mentre chiude gli occhi di Deborah, il sangue le cola dall'angolo della bocca."
  },
  AvgDialog_52001_Content_77 = {Text = "..."},
  AvgDialog_52001_Content_8 = {
    Text = "So che hai paura. Ho visto molti credenti tremare quando giungono alla fine di questa vita."
  },
  AvgDialog_52001_Content_9 = {
    Text = "Ma non temere. Tu sei una delle persone supreme del Reame Divino; tutto ciò che hai sopportato ti sarà ripagato nel Reame Divino."
  },
  AvgDialog_52002_Content_1 = {
    Text = "Le Stelle Sono Allineate. Il Feto Divino del Re è stato impiantato nel Sacro Fanciullo. Presto, il Re farà ritorno in questo mondo."
  },
  AvgDialog_52002_Content_10 = {
    Text = "Tra il coro assordante degli uomini-pesce, Miryam solleva il neonato in alto con entrambe le mani."
  },
  AvgDialog_52002_Content_11 = {
    Text = "Al posto del suo cuore, il Feto Divino emette un candido bagliore sotto le stelle."
  },
  AvgDialog_52002_Content_12 = {Text = "Waaahhh—"},
  AvgDialog_52002_Content_13 = {
    Text = "Cala il Silenzio. L'infante insanguinato che si dimena tra le rovine emette il suo primo, tardivo vagito."
  },
  AvgDialog_52002_Content_14 = {
    Text = "Le stelle ascoltano in silenzio quel grido oracolare. Una singola stella cade, tracciando una scia dolente nel cielo notturno."
  },
  AvgDialog_52002_Content_15 = {
    Text = "—Un altro racconto delle stelle sta per avere inizio."
  },
  AvgDialog_52002_Content_2 = {
    Text = "Il re proteggerà i suoi sudditi virtuosi, dando vita al Reame Divino!"
  },
  AvgDialog_52002_Content_3 = {
    Text = "Il Reame Divino! Il Reame Divino!"
  },
  AvgDialog_52002_Content_4 = {
    Text = "Gli uomini-pesce esultano e danzano in una frenesia di follia. Miryam resta al centro, la luce delle stelle a illuminarle il volto, rigato di sangue e lacrime."
  },
  AvgDialog_52002_Content_5 = {
    Text = "La parola del Nostro Signore si propagherà per il mondo. Somma Sacerdotessa, dona un nome a questo gregge."
  },
  AvgDialog_52002_Content_6 = {
    Text = "Occhi freddi e ardenti si volgono lentamente. Miryam scruta i suoi soldati, i suoi sudditi. Offre loro il sorriso di una sacerdotessa."
  },
  AvgDialog_52002_Content_7 = {
    Text = "Ci mettemmo in mare, seguendo le orme del re. Tornammo dal mare, portando con noi il Dominio del re..."
  },
  AvgDialog_52002_Content_8 = {
    Text = "Il mondo ci chiamerà... Navigatori."
  },
  AvgDialog_52002_Content_9 = {
    Text = "Navigatori! Navigatori!!"
  },
  AvgDialog_52003_Content_1 = {
    Text = "Il Signore te lo dirà. Ora, prega."
  },
  AvgDialog_52003_Content_10 = {
    Text = "Le persone intorno continuano a cadere a terra. Sopportando il dolore, Miryam recita le preghiere scritte sulla carta."
  },
  AvgDialog_52003_Content_11 = {
    Text = "\"Nel lontano abisso privo di sole, la grande anima ancestrale è nel dormiveglia...\""
  },
  AvgDialog_52003_Content_12 = {
    Text = "Miryam pronuncia queste parole in lemuriano ordinario, ma mentre le pronuncia, le parole prendono vita. Le lettere si distorcono come tentacoli, l'inchiostro nero danza nell'aria, finché non si tramuta in un'altra lingua."
  },
  AvgDialog_52003_Content_13 = {
    Text = "La sua voce si sovrappone e si intreccia in quell'unico istante. Le vocali si agganciano alle consonanti, le desinenze si fondono con gli inizi, proprio come quei simboli. Ciò che fuoriesce dalla sua gola forma una struttura complessa entro una dimensione superiore, come se riecheggiasse da uno spazio-tempo inimmaginabile."
  },
  AvgDialog_52003_Content_14 = {
    Text = "\"...La Sua volontà si intreccia come una ragnatela di stelle; nel vuoto eterno, Egli attende che tu entri nel Suo sogno...\""
  },
  AvgDialog_52003_Content_15 = {
    Text = "Miryam continua a intonare la cantilena con tutte le sue forze."
  },
  AvgDialog_52003_Content_16 = {
    Text = "Mentre le sue parole risuonano e si accumulano su se stesse senza sosta, la realtà che la circonda si offusca, si dissolve."
  },
  AvgDialog_52003_Content_17 = {
    Text = "Si ritrova sommersa in un mare profondo. Acque sinuose fluiscono in ogni direzione, simili a un'illusione."
  },
  AvgDialog_52003_Content_18 = {
    Text = "Risplende di un bagliore argenteo. Stelle luminose si disperdono ovunque, alla deriva, in un tremolio."
  },
  AvgDialog_52003_Content_19 = {
    Text = "Miryam sente di essersi in qualche modo unita alla costellazione. La sua luce di falena viene attratta verso un luogo preciso. Volge lo sguardo in quella direzione."
  },
  AvgDialog_52003_Content_2 = {
    Text = "Egli lascia la stanza, lasciando con gli apprendisti soltanto un sacerdote e alcune guardie."
  },
  AvgDialog_52003_Content_20 = {
    Text = "Innumerevoli flussi di luce vorticano con schiuma luminosa, rincorrendosi verso una sagoma sfocata e lontana. Una sagoma composta da un corpo umano, un trono e innumerevoli tentacoli."
  },
  AvgDialog_52003_Content_21 = {
    Text = "Quello è... il Signore?"
  },
  AvgDialog_52003_Content_22 = {Text = "Pop—"},
  AvgDialog_52003_Content_23 = {
    Text = "Come se fosse stato svegliato da un suono, si ridesta dal suo trono. Con il suo risveglio, l'intero vuoto sembra oscurarsi per un istante."
  },
  AvgDialog_52003_Content_24 = {
    Text = "Una vaga sagoma di un uomo anziano appare dietro di lui."
  },
  AvgDialog_52003_Content_25 = {
    Text = "Avete udito la sua voce, mio Signore."
  },
  AvgDialog_52003_Content_26 = {
    Text = "È lei quella rivelata dalle stelle?"
  },
  AvgDialog_52003_Content_27 = {
    Text = "Sì, ho verificato. A meno che le stelle non si sbaglino, lei... è il futuro di Lemuria."
  },
  AvgDialog_52003_Content_28 = {
    Text = "Non lo pensi davvero."
  },
  AvgDialog_52003_Content_29 = {
    Text = "Talento sufficiente, ma Devozione insufficiente. Non può servirvi davvero, mio Signore."
  },
  AvgDialog_52003_Content_3 = {
    Text = "La luce nella sala di Preghiera si affievolisce. Un bagliore misterioso e tenue inizia a manifestarsi sulla superficie della Statua."
  },
  AvgDialog_52003_Content_30 = {
    Text = "Non crede nelle preghiere, in voi, né nel futuro di Lemuria. Crede soltanto nella sua famiglia."
  },
  AvgDialog_52003_Content_31 = {
    Text = "Miryam vive nella realtà. Una persona simile non può portare il fato della nazione."
  },
  AvgDialog_52003_Content_32 = {
    Text = "Dimorare nella verità, non nel Delirio... questo è il credo di Questa Persona."
  },
  AvgDialog_52003_Content_33 = {
    Text = "Un Nobile desiderio, mio Signore. Tuttavia, nati a Lemuria, ciascuno di noi ha i propri doveri da adempiere."
  },
  AvgDialog_52003_Content_34 = {
    Text = "Lei non ha Scelta. Io non ho Scelta. E voi, mio Signore... non avete Scelta neppure voi."
  },
  AvgDialog_52003_Content_35 = {
    Text = "...Noioso. Desidero riposare, ora."
  },
  AvgDialog_52003_Content_36 = {
    Text = "Agita una mano. L'Anziano si inchina dinanzi a lui e svanisce."
  },
  AvgDialog_52003_Content_37 = {
    Text = "Prima di tornare ai suoi sogni, il ragazzo contempla i milioni di bagliori e le anime che glieli consacrano. Un sospiro evanescente si dissolve nell'immenso vuoto, inudito, senza risposta."
  },
  AvgDialog_52003_Content_38 = {Text = "SQUEAK!"},
  AvgDialog_52003_Content_39 = {
    Text = "Segue una sensazione di caduta che mozza il fiato, poi un dolore acuto."
  },
  AvgDialog_52003_Content_4 = {
    Text = "Miryam raccoglie il foglio di preghiera davanti a sé."
  },
  AvgDialog_52003_Content_40 = {
    Text = "Il dolore non dura a lungo. Miryam lascia quello spazio spirituale. Apre gli occhi, guardandosi attorno smarrita."
  },
  AvgDialog_52003_Content_41 = {
    Text = "Coloro che non sono riusciti a leggere o a intonare le Preghiere sono stati condotti fuori. Tra i rimasti, alcuni giacciono a terra doloranti, mentre altri, con gli occhi chiusi in Preghiera, portano sorrisi beati."
  },
  AvgDialog_52003_Content_42 = {
    Text = "Deborah siede accanto a lei, un dolce sorriso che le si propaga sul volto mentre apre lentamente gli occhi. Tuttavia, la sua Espressione si annuvola quando il suo sguardo incrocia quello di Miryam."
  },
  AvgDialog_52003_Content_5 = {Text = "Ah..."},
  AvgDialog_52003_Content_6 = {
    Text = "I testi sulla carta sono scritti in una lingua diversa dal lemuriano comune. Gremiti di geroglifici complessi, possiedono più dimensioni dello spazio reale."
  },
  AvgDialog_52003_Content_7 = {
    Text = "Miryam si domanda se quei glifi misteriosi provengano da iscrizioni antiche o persino da un altro mondo. Eppure, il loro significato penetra nella sua mente automaticamente non appena li legge."
  },
  AvgDialog_52003_Content_8 = {
    Text = "Innumerevoli scritture divine inondano la mente di Miryam. Mentre i loro significati si dipanano con una vastità soverchiante, la sua fragile mente giunge sull'orlo del collasso."
  },
  AvgDialog_52003_Content_9 = {
    Text = "<Shake:La mia testa... mi fa male...>"
  },
  AvgDialog_52004_Content_1 = {
    Text = "Finché crederete nel Re, il Re risponderà alla vostra fede..."
  },
  AvgDialog_52004_Content_10 = {
    Text = "Che la Sua Intuizione preveda le calamità,\nche la Sua saggezza sia Guida al Suo popolo."
  },
  AvgDialog_52004_Content_11 = {
    Text = "\"Possa la tua perspicacia prevedere le calamità,\nE la tua saggezza guidare il popolo.\""
  },
  AvgDialog_52004_Content_12 = {
    Text = "La tempesta giace dormiente, le acque indisturbate;\nI tremori si placano, e la terra riposa in tranquillità."
  },
  AvgDialog_52004_Content_13 = {
    Text = [[
Che ogni sciagura si dissolva nei Suoi placidi sogni,
che il Reame Divino giunga sotto la Sua protezione.]]
  },
  AvgDialog_52004_Content_14 = {
    Text = "\"Che ogni sciagura si dissolva nei Suoi placidi sogni!\""
  },
  AvgDialog_52004_Content_15 = {
    Text = [[
"Che il Reame Divino giunga,
sotto la Sua protezione..."]]
  },
  AvgDialog_52004_Content_16 = {Text = "Boom..."},
  AvgDialog_52004_Content_17 = {
    Text = "Enormi tentacoli si protendono dal suolo sotto il Tempio, tra Echi rimbombanti."
  },
  AvgDialog_52004_Content_18 = {
    Text = "È il nostro Signore! Il Miracolo del nostro Signore si è manifestato!!!"
  },
  AvgDialog_52004_Content_19 = {
    Text = "I Seguaci alzano le braccia, esultando in estasi."
  },
  AvgDialog_52004_Content_2 = {
    Text = "Dunque, dimmi, credi nel Re? Sei disposto a donare tutto al Re?"
  },
  AvgDialog_52004_Content_20 = {
    Text = "I Tentacoli ondeggiano dolcemente nel vento e nella pioggia, e tutti a Lemuria credono fermamente che queste grandi divinità Lemuriane possiedano il potere di resistere a ogni catastrofe."
  },
  AvgDialog_52004_Content_21 = {
    Text = "Nostro Signore, Tulu—"
  },
  AvgDialog_52004_Content_22 = {
    Text = "Mio Signore, Tulu!! Tulu!!!"
  },
  AvgDialog_52004_Content_23 = {
    Text = "Lei si volta, rivolgendo lo sguardo verso l'interno del Tempio, e si inginocchia."
  },
  AvgDialog_52004_Content_24 = {
    Text = "Ma nessuno può vedere che nei Suoi Occhi non vi è traccia delle aspettative o della dignità della somma sacerdotessa, solo Confusione."
  },
  AvgDialog_52004_Content_25 = {
    Text = "Ascolta l'invocazione dei tuoi Seguaci. Portaci il Reame Divino."
  },
  AvgDialog_52004_Content_26 = {
    Text = "Portateci il Reame Divino!"
  },
  AvgDialog_52004_Content_27 = {
    Text = "Mio signore! Il Reame Divino! Hahaha... Sta arrivando!"
  },
  AvgDialog_52004_Content_28 = {
    Text = "Accompagnati da grida di follia, i tentacoli iniziano a danzare. L'aura serena del mare profondo emana da loro, infiltrandosi nei sensi di ogni Lemuriano."
  },
  AvgDialog_52004_Content_29 = {Text = "Boom—"},
  AvgDialog_52004_Content_3 = {
    Text = "Credo nel Re, Vostra Grazia! Sono disposto a offrire tutto al Re!"
  },
  AvgDialog_52004_Content_30 = {
    Text = "Nel rombo del tuono, gli Applausi svaniscono. Il fulmine squarcia il cielo, illuminando la terra solitaria di Lemuria."
  },
  AvgDialog_52004_Content_31 = {
    Text = "In questo momento di giubilo, i movimenti dei credenti si arrestano. Restano sospesi nella loro somma lode e fede nel Re, intrappolati per sempre nell'ambra delle loro sconfinate visioni e aneliti per il futuro."
  },
  AvgDialog_52004_Content_32 = {
    Text = "Sotto la pioggia battente, il popolo di Lemuria sprofonda in un sonno profondo."
  },
  AvgDialog_52004_Content_4 = {
    Text = "Sono il più leale seguace del Re!"
  },
  AvgDialog_52004_Content_5 = {
    Text = "Sì! Vostra Grazia, sì!"
  },
  AvgDialog_52004_Content_6 = {
    Text = "E ora, unitevi a me nel cantare il nome del Re—"
  },
  AvgDialog_52004_Content_7 = {
    Text = "Scruta tutti i presenti nella piazza."
  },
  AvgDialog_52004_Content_8 = {
    Text = "Nella tempesta furiosa, Tutti si inginocchiano, allargano le braccia e volgono lo sguardo verso la direzione del Trono nel Tempio."
  },
  AvgDialog_52004_Content_9 = {
    Text = "Sotto il firmamento stellato, su un'isola solitaria nel mare profondo, preghiamo con devozione il nostro Signore:"
  },
  AvgDialog_52005_Content_1 = {
    Text = "Sì, Padre... ci rincontreremo nel Reame Divino! La nostra famiglia vivrà insieme nel Reame Divino..."
  },
  AvgDialog_52005_Content_10 = {
    Text = "Il Reame Divino sta arrivando, Padre. Presto, la nostra famiglia si riunirà..."
  },
  AvgDialog_52005_Content_11 = {Text = "Puf—"},
  AvgDialog_52005_Content_12 = {
    Text = "Il pugnale affonda nel petto di Enos. Un ululato di agonia bruciante prorompe. Il suo sangue sprizza incontrollabile, macchiando la guancia destra di Miryam."
  },
  AvgDialog_52005_Content_13 = {
    Text = "Gli occhi di Miryam si spalancano mentre si concentra sulle ferite dove il pugnale incontra la carne, come se stesse osservando un capolavoro."
  },
  AvgDialog_52005_Content_14 = {
    Text = "Lacerando la pelle, perforando le vene, separando le ossa. Gli ululati di Enos non cessano mai, come una bestia moribonda dilaniata."
  },
  AvgDialog_52005_Content_15 = {
    Text = "Il sangue urla con ruggiti distorti. Spuntoni cremisi di violenza montante. Traboccando, perforano il volto e la pelle di Miryam prima di conficcarsi nei suoi visceri."
  },
  AvgDialog_52005_Content_17 = {
    Text = "\"Seguace del nostro signore, apri il tuo cuore al nostro signore...\""
  },
  AvgDialog_52005_Content_18 = {
    Text = "Sangue e lacrime inondano il volto stravolto di Miryam. Cantando preghiere, muove le mani sempre più velocemente."
  },
  AvgDialog_52005_Content_19 = {
    Text = "Quando il pugnale si ferma, i sigilli di felicità e speranza sono già incisi sul corpo di Enos, tra la sua carne tremante."
  },
  AvgDialog_52005_Content_2 = {
    Text = "Si asciuga le lacrime e si alza lentamente. La sua mano raggiunge il Pugnale accanto al letto."
  },
  AvgDialog_52005_Content_20 = {
    Text = "\"Ai devoti, il Signore elargirà la Sua grazia...\""
  },
  AvgDialog_52005_Content_21 = {
    Text = "<Big:\"A chi anela, il Signore concederà...\">"
  },
  AvgDialog_52005_Content_22 = {
    Text = "Solleva il bacile contenente il sangue sacro e lo versa nelle ferite simili a sigilli sul corpo di Enos."
  },
  AvgDialog_52005_Content_23 = {
    Text = "Nel momento in cui il sangue sacro tocca quei sigilli, sembra acquisire vitalità. Vorticando sul corpo di Enos come un serpente, un senso di eccitazione nel percepire il calore della preda sembra propagarsi attraverso le sue tracce sinuose."
  },
  AvgDialog_52005_Content_24 = {
    Text = "Non c'è bisogno della guida di Miryam; seguono la fonte di calore, penetrando nel corpo di Enos attraverso le ferite."
  },
  AvgDialog_52005_Content_25 = {
    Text = "Man mano che il sangue fluisce, i ringhi di Enos diventano insopportabilmente intensi, mentre le sue ferite si rimarginano a velocità visibile."
  },
  AvgDialog_52005_Content_26 = {
    Text = "Nel frattempo, i suoi lineamenti iniziano a degenerare; gli occhi diventano enormi e sporgenti, le labbra si fanno viscide e la testa si allunga, appiattendosi."
  },
  AvgDialog_52005_Content_27 = {
    Text = "Un organo simile a branchie appare sul suo collo. Squame scivolose sostituiscono i capelli, crescendo da varie parti del corpo."
  },
  AvgDialog_52005_Content_28 = {
    Text = "Geme ancora di dolore, ma i suoi suoni si trasformano gradualmente in stridii colmi dell'aria umida e stagnante di acqua salmastra..."
  },
  AvgDialog_52005_Content_29 = {
    Text = "Ce l'ho fatta, Padre... Non ti ho deluso, vero?"
  },
  AvgDialog_52005_Content_3 = {
    Text = "La Lama del Pugnale si piega in un arco bizzarro, incisa con intricati geroglifici che condividono una sconcertante somiglianza con quelli delle Preghiere."
  },
  AvgDialog_52005_Content_30 = {
    Text = "Il sibilo si interrompe. Il mostro metà pesce, metà umano la fissa con sguardo vacuo. I suoi occhi enormi sporgono pallidamente, la sua intelligenza dissolta."
  },
  AvgDialog_52005_Content_31 = {
    Text = "Miryam si avvicina all'altare di pietra, accarezzando il mostro. Il denso odore di pesce le invade le narici, la pelle sotto le sue mani appiccicosa e scivolosa."
  },
  AvgDialog_52005_Content_32 = {
    Text = "Quell'odore e quella sensazione un tempo la disgustava. Ma ora li trova più confortanti che mai."
  },
  AvgDialog_52005_Content_33 = {
    Text = "Adoro il pesce. Quando ci rincontreremo nel Reame Divino, mangerò il pesce che cucini ogni giorno..."
  },
  AvgDialog_52005_Content_34 = {
    Text = "Aspettami, Padre."
  },
  AvgDialog_52005_Content_35 = {
    Text = "Si china verso la creatura e le bacia la guancia. Viscida, umida, inconfondibilmente calda."
  },
  AvgDialog_52005_Content_4 = {
    Text = "Vicino al pugnale, il sangue del dio ondeggia leggermente nel bacino di pietra, riflettendo un inquietante bagliore rosso-verde dalla luce delle candele."
  },
  AvgDialog_52005_Content_5 = {
    Text = "Un grave Delirium ha fatto perdere a Enos gran parte della coscienza. Osserva Miryam con curiosità, come un neonato che vede il mondo per la prima volta."
  },
  AvgDialog_52005_Content_6 = {
    Text = "Miryam, ora sei una sacerdotessa... Hai chiesto al re? Il re ti ha detto quando il Reame Divino giungerà a Lemuria?"
  },
  AvgDialog_52005_Content_7 = {
    Text = "Sì, ho pregato per la Sua guida... Ha predetto che sarà presto, molto presto..."
  },
  AvgDialog_52005_Content_8 = {
    Text = "Un debole, pallido sorriso si forma tra le tracce aggrovigliate di lacrime. Si avvicina a Enos, si china e gli sfiora la guancia."
  },
  AvgDialog_52005_Content_9 = {
    Text = "Non ti deluderò, Padre."
  },
  AvgDialog_54067_Content_1 = {
    Text = "Sogno di Lemuria"
  },
  AvgDialog_54067_Content_10 = {
    Text = "Il clamore turbina come un banco di pesci attorno a lei. Tra lei e il branco scorre una silenziosa distesa di mare vuoto, e lì, in quel vuoto inondato di luce, la sua voce si leva con cristallina chiarezza."
  },
  AvgDialog_54067_Content_100 = {
    Text = "La pioggia martellava il suo corpo avvizzito, e il vento quasi lo abbatteva. Nel punto più alto di Lemuria, il vecchio contemplava la vasta isola."
  },
  AvgDialog_54067_Content_101 = {
    Text = "L'acutezza e la decrepitezza nei loro occhi svanirono. Erano limpidi, rinvigoriti e curiosi, come quelli di un neonato, intenti a fissare la terra sfregiata."
  },
  AvgDialog_54067_Content_102 = {
    Text = "\"Hehehe... Lemuria, che posto meraviglioso.\""
  },
  AvgDialog_54067_Content_103 = {
    Text = "\"A cosa state pensando ora, Mio Signore?\""
  },
  AvgDialog_54067_Content_104 = {
    Text = "\"Hai sempre detto di non avere alcun interesse a salvare Lemuria, di provare solo stanchezza. Eppure per il bene di Lemuria, ti sei confinato sul trono, intrappolato nei tuoi stessi sogni.\""
  },
  AvgDialog_54067_Content_105 = {
    Text = "\"Gli dèi sono svaniti, eppure tu ancora persegui... Io non sono che un impostore. Tu sei il più grande Guardiano di Lemuria.\""
  },
  AvgDialog_54067_Content_106 = {
    Text = "\"Un ultimo sguardo, mio signore. Un ultimo sguardo. <Lemuria>, la nostra <Home>...\""
  },
  AvgDialog_54067_Content_107 = {
    Text = "Il vecchio alzò il capo, lo sguardo che si spostava dagli isolani addormentati al mare in tumulto all'orizzonte, poi al tuono incessante e alla pioggia nel cielo."
  },
  AvgDialog_54067_Content_108 = {
    Text = "Si alzò barcollando, un calore che si scioglieva nei suoi occhi profondi. La barba e la veste ondeggiavano nel vento, e i suoi occhi, ora nuovamente affilati, trafiggevano il cielo come lame."
  },
  AvgDialog_54067_Content_109 = {
    Text = "\"Intrighi complicati, missioni tediose, promesse solenni — che vadano tutti all'inferno.\""
  },
  AvgDialog_54067_Content_11 = {
    Text = "\"...Nel nome di Tulu, nostro Signore, giuro:\""
  },
  AvgDialog_54067_Content_110 = {
    Text = "Gettò via il bastone, aprì le braccia e abbracciò la tempesta. Ruggì."
  },
  AvgDialog_54067_Content_111 = {
    Text = "\"Vieni, Cataclisma! Vieni, miserabile Dio!\""
  },
  AvgDialog_54067_Content_112 = {
    Text = "\"Sono il tuo complice. Seppelliamo Lemuria insieme!\""
  },
  AvgDialog_54067_Content_113 = {Text = "..."},
  AvgDialog_54067_Content_114 = {Text = "Boom—"},
  AvgDialog_54067_Content_115 = {
    Text = "Un suono soffocato penetra attraverso numerose spesse pareti di pietra, echeggiando nella camera da letto del Tempio."
  },
  AvgDialog_54067_Content_116 = {
    Text = "Tulu siede sul Trono, il mento appoggiato su una mano, le palpebre pesanti di Esaurimento."
  },
  AvgDialog_54067_Content_117 = {
    Text = "I Lemuriani sono caduti nel Riposo Eterno. Egli ha consumato tutto il suo potere per concedere loro un bel sogno, un miraggio della sua promessa."
  },
  AvgDialog_54067_Content_118 = {
    Text = "\"Le tempeste di Lemuria si placheranno. L'abisso di Lemuria svanirà.\""
  },
  AvgDialog_54067_Content_119 = {
    Text = "\"Il Re farà da scudo al suo popolo gentile e porterà il Reame Divino.\""
  },
  AvgDialog_54067_Content_12 = {
    Text = "\"Sono una serva di Lemuria. Servo alla destra del Re.\""
  },
  AvgDialog_54067_Content_120 = {
    Text = "\"Che ironia. È questa la tua volontà, 'Dio di Lemuria'?\""
  },
  AvgDialog_54067_Content_121 = {
    Text = "Alza il capo. Il suo sguardo penetra le lastre del tetto, la pioggia battente e le nuvole che si fondono, raggiungendo il cielo stellato profondo e il sogno profondo delle costellazioni."
  },
  AvgDialog_54067_Content_122 = {
    Text = "\"Te ne sei andato da tempo... Non ti è mai importato di Lemuria, vero?\""
  },
  AvgDialog_54067_Content_123 = {
    Text = "\"Anche tu sei braccato, cacciato e abbandonato da una Volontà Superiore. Sei un'anima perduta e isolata, in nulla diversa da me.\""
  },
  AvgDialog_54067_Content_124 = {
    Text = "\"I Lemuriani venerano dèi spietati e re deboli. Il Reame Divino... Hah, che noia.\""
  },
  AvgDialog_54067_Content_125 = {
    Text = "\"Mi dispiace. Ma questa volta sono davvero esausta.\""
  },
  AvgDialog_54067_Content_126 = {
    Text = "Si accascia sul trono, mantenendo la postura di una mano a sorreggersi il mento. Un sonno profondo lo avvolge."
  },
  AvgDialog_54067_Content_127 = {
    Text = "Scivola nello stesso sogno del suo popolo. Là, il sole bagna i loro volti rivolti al cielo di un bagliore divino, e la fragranza melodica delle risate si propaga nella brezza gentile."
  },
  AvgDialog_54067_Content_128 = {
    Text = "Ha portato il tanto atteso Reame Divino a Lemuria. Ha portato le tanto attese menzogne a Lemuria."
  },
  AvgDialog_54067_Content_129 = {
    Text = "Dice addio alla sua terra natale con un'ultima menzogna — questo, come Re di Lemuria, è il suo ultimo esercizio di Potere e il suo estremo atto di misericordia."
  },
  AvgDialog_54067_Content_13 = {
    Text = "\"Guiderò il popolo di Lemuria. Udrò la Sua voce e obbedirò al Suo comando.\""
  },
  AvgDialog_54067_Content_130 = {Text = "..."},
  AvgDialog_54067_Content_131 = {Text = "Pop—"},
  AvgDialog_54067_Content_132 = {
    Text = "Macerie cadono dalla Statua. La Statua silenziosa, un tempo grandiosa e splendida, è ora sull'orlo di frantumarsi."
  },
  AvgDialog_54067_Content_133 = {
    Text = "\"Padre, guarda... quelle sono le Sue lacrime. Il nostro Signore piange per Lemuria.\""
  },
  AvgDialog_54067_Content_134 = {
    Text = "Tiene tra le braccia uno degli uomini-pesce. Quello sbatte i suoi occhi enormi, guardandosi intorno con aria vacua."
  },
  AvgDialog_54067_Content_135 = {
    Text = "Non riesce a trovare Enos. Perciò tutti gli uomini-pesce sono Enos."
  },
  AvgDialog_54067_Content_136 = {
    Text = "La pioggia torrenziale ruggisce contro le mura del Tempio con un ritmo impaziente; eppure, le sue mani restano gentili, accarezzando le scaglie luccicanti degli uomini-pesce. Un denso fetore salmastro riempie ogni angolo della Stanza."
  },
  AvgDialog_54067_Content_137 = {
    Text = "\"Maestro, il Signore... Sembra che entrambi abbiano rinunciato.\""
  },
  AvgDialog_54067_Content_138 = {
    Text = "\"Ma io... io non rinuncerò... Posso salvare Lemuria, e posso riportarla com'era. Il Signore me l'ha detto.\""
  },
  AvgDialog_54067_Content_139 = {
    Text = "\"La Madre non c'è più, la sorella non c'è più, il padre... non c'è più nemmeno lui.\""
  },
  AvgDialog_54067_Content_14 = {
    Text = "\"Io, insieme a tutti i credenti, attenderò il Reame Divino.\""
  },
  AvgDialog_54067_Content_140 = {
    Text = "\"Ho paura, Miryam. Ho paura che tutto ciò che abbiamo fatto si rivelerà privo di significato...\""
  },
  AvgDialog_54067_Content_141 = {
    Text = "\"Nostro padre era un comune mortale, eppure non ha mai avuto Terrore né ha mai rinunciato, nemmeno di fronte a calamità così frequenti.\""
  },
  AvgDialog_54067_Content_142 = {
    Text = "\"Noi siamo le Somme Sacerdotesse di Lemuria. Non rinunceremo mai... Questo è ciò che il padre mi ha insegnato.\""
  },
  AvgDialog_54067_Content_143 = {
    Text = "Sorride, sussurrando piano. Le lacrime scorrono, mescolandosi a parole di cui non sa se siano verità o disperata Speranza. Gocciolano sulle scaglie degli uomini-pesce, brillando di una luce fioca."
  },
  AvgDialog_54067_Content_144 = {Text = "Boom—"},
  AvgDialog_54067_Content_145 = {
    Text = "Il suolo trema violentemente sotto di lei. Le colonne del Tempio lottano per reggere, ma le lastre del tetto cominciano a sgretolarsi, a crollare, poi si frantumano al suolo."
  },
  AvgDialog_54067_Content_146 = {
    Text = "Anche i resti della Statua cadono in pezzi sotto un Potere così selvaggio. I ruggiti della tempesta e del terremoto martellano le orecchie di Miryam come tamburi di guerra implacabili."
  },
  AvgDialog_54067_Content_147 = {
    Text = "Chiude gli Occhi, si inginocchia davanti alla Statua spezzata e stringe la Mano della piccola Miryam."
  },
  AvgDialog_54067_Content_148 = {
    Text = "\"Ascoltate il nostro Signore. Sottomettetevi al nostro Signore. Sia lode al nostro Signore.\""
  },
  AvgDialog_54067_Content_149 = {
    Text = "\"Per i sofferenti, il Signore risanerà.\nPer i peccatori, il Signore giudicherà...\""
  },
  AvgDialog_54067_Content_15 = {Text = "Boom—"},
  AvgDialog_54067_Content_150 = {
    Text = "Lo Scuotimento non accenna a cessare. L'oscurità si addensa sotto le enormi Nuvole ribollenti, scacciando la luce del sole; una muraglia imponente si erge dall'oceano lontano, il suo indaco macchia il cielo —"
  },
  AvgDialog_54067_Content_151 = {
    Text = "L'oceano si erge come un gigante che si desta, avanzando a grandi passi verso Lemuria."
  },
  AvgDialog_54067_Content_152 = {
    Text = "Di fronte all'oceano, questo glorioso regno trema come una foglia avvizzita."
  },
  AvgDialog_54067_Content_153 = {
    Text = "\"Ai devoti, il Signore elargirà la Sua grazia.\""
  },
  AvgDialog_54067_Content_154 = {
    Text = "\"Per gli anelanti, il Signore concederà... concederà...\""
  },
  AvgDialog_54067_Content_155 = {
    Text = "Raffiche furiose e minacciose colpiscono il tempio come una falce tra le erbacce. Sollevano le pesanti lastre d'ardesia e lacerano le fondamenta, esponendo il suolo sepolcrale sottostante."
  },
  AvgDialog_54067_Content_156 = {
    Text = "L'oceano, un tempo curvo sotto il cielo, ora si erge a cancellare l'ultimo barlume di luce funesta. Tra le cupe rovine della sua fede, lei stringe a sé una delle creature-pesce e la abbraccia forte. Le ombre si espandono; i flutti precipitano."
  },
  AvgDialog_54067_Content_157 = {
    Text = "Miasmi stigei le si riversano addosso. Le lacrime le inondano gli occhi prima che l'acqua oscura la raggiunga."
  },
  AvgDialog_54067_Content_158 = {Text = "..."},
  AvgDialog_54067_Content_159 = {
    Text = "\"Mio signore... vi offro tutta la mia Devozione, vi servo finché le Stelle non si estingueranno negli abissi del tempo...\""
  },
  AvgDialog_54067_Content_16 = {
    Text = "Un fulmine esplose nei cieli di Lemuria."
  },
  AvgDialog_54067_Content_160 = {
    Text = "\"Non mi hai mentito, il Reame Divino arriverà, vero, mio Signore?\""
  },
  AvgDialog_54067_Content_161 = {
    Text = "Per l'ultima volta, alza lo sguardo, fissando disperatamente il punto in cui un tempo sorgeva la Statua del Signore."
  },
  AvgDialog_54067_Content_162 = {
    Text = "Non c'è nessuna Statua. Non c'è nessun Signore."
  },
  AvgDialog_54067_Content_163 = {Text = "..."},
  AvgDialog_54067_Content_164 = {
    Text = "<Big:Boom—>"
  },
  AvgDialog_54067_Content_165 = {
    Text = "L'oceano raggiunge la foglia avvizzita."
  },
  AvgDialog_54067_Content_166 = {Text = "..."},
  AvgDialog_54067_Content_167 = {
    Text = "Nell'Anno @3 del Vecchio Calendario, Lemuria sprofondò nell'abisso. Nessuno sopravvisse."
  },
  AvgDialog_54067_Content_17 = {
    Text = "Il fragore fece ammutolire la Folla."
  },
  AvgDialog_54067_Content_18 = {
    Text = "La calamità... La calamità ricomincia?"
  },
  AvgDialog_54067_Content_19 = {
    Text = "Vostra Grazia... È questa... la calamità che si avvicina?"
  },
  AvgDialog_54067_Content_2 = {
    Text = "Il vento ululante sospinge la pioggia torrenziale, inzuppando la gente nella piazza."
  },
  AvgDialog_54067_Content_20 = {
    Text = "I cataclismi non sono mai cessati. Lemuria dorme accanto a essi."
  },
  AvgDialog_54067_Content_21 = {
    Text = "Ma Lemuria è sempre esistita, non è vero?"
  },
  AvgDialog_54067_Content_22 = {
    Text = "Esatto... Esatto..."
  },
  AvgDialog_54067_Content_23 = {
    Text = "Vostra Grazia, quando giungerà... il Reame Divino?"
  },
  AvgDialog_54067_Content_24 = {
    Text = "Ci siamo quasi, amico mio."
  },
  AvgDialog_54067_Content_25 = {
    Text = "Così presto?!"
  },
  AvgDialog_54067_Content_26 = {
    Text = "Sì, molto presto..."
  },
  AvgDialog_54067_Content_27 = {
    Text = "Miryam lascia la protezione delle Guardie e si avvicina all'Altare."
  },
  AvgDialog_54067_Content_28 = {
    Text = "Innumerevoli mani si protendono, i Credenti si riversano verso di lei, cercando la Benedizione del Vecchio Sommo Sacerdote di Lemuria."
  },
  AvgDialog_54067_Content_29 = {
    Text = "Si guardò intorno, gli occhi calmi e sorridenti, ma quello Sguardo ridusse rapidamente al Silenzio i Seguaci rumorosi."
  },
  AvgDialog_54067_Content_3 = {
    Text = "Un acquazzone simile non si vedeva da molto tempo. Le grida della gente risuonano sempre più forti e chiare, sovrastando il ruggito furioso della tempesta."
  },
  AvgDialog_54067_Content_30 = {
    Text = "Nel fragore della tempesta, protese la mano e toccò la fronte del Credente."
  },
  AvgDialog_54067_Content_31 = {
    Text = "Il Credente strinse le mani al petto e si inginocchiò."
  },
  AvgDialog_54067_Content_32 = {
    Text = "Finché crederete nel Re, il Re risponderà alla vostra fede..."
  },
  AvgDialog_54067_Content_33 = {
    Text = "Dunque, dimmi, credi nel Re? Sei disposto a donare tutto al Re?"
  },
  AvgDialog_54067_Content_34 = {
    Text = "Credo nel Re, Vostra Grazia! Sono disposto a offrire tutto al Re!"
  },
  AvgDialog_54067_Content_35 = {
    Text = "Sono il più leale seguace del Re!"
  },
  AvgDialog_54067_Content_36 = {
    Text = "Sì! Vostra Grazia, sì!"
  },
  AvgDialog_54067_Content_37 = {
    Text = "E ora, unitevi a me nel cantare il nome del Re—"
  },
  AvgDialog_54067_Content_38 = {
    Text = "Scruta tutti i presenti nella piazza."
  },
  AvgDialog_54067_Content_39 = {
    Text = "Nella tempesta furiosa, Tutti si inginocchiano, allargano le braccia e volgono lo sguardo verso la direzione del Trono nel Tempio."
  },
  AvgDialog_54067_Content_4 = {
    Text = "Sua Grazia! Sua Grazia ci porta la profezia del Signore!"
  },
  AvgDialog_54067_Content_40 = {
    Text = "Sotto il firmamento stellato, sopra l'antico Reame dei mari lontani, preghiamo il nostro Signore con la più profonda Devozione:"
  },
  AvgDialog_54067_Content_41 = {
    Text = "Che la Sua Intuizione preveda le calamità,\nche la Sua saggezza sia Guida al Suo popolo."
  },
  AvgDialog_54067_Content_42 = {
    Text = "\"Che la Sua lungimiranza preveda le calamità,\nChe la Sua saggezza guidi il Suo popolo!\""
  },
  AvgDialog_54067_Content_43 = {
    Text = [[
Che le tempeste si plachino, le acque si calmino;
Che i terremoti cessino, la terra riposi in pace.]]
  },
  AvgDialog_54067_Content_44 = {
    Text = [[
Che ogni sciagura si dissolva nei Suoi placidi sogni,
che il Reame Divino giunga sotto la Sua protezione.]]
  },
  AvgDialog_54067_Content_45 = {
    Text = "\"Che ogni sciagura si dissolva nei Suoi placidi sogni!\""
  },
  AvgDialog_54067_Content_46 = {
    Text = [[
"Che il Reame Divino giunga,
sotto la Sua protezione..."]]
  },
  AvgDialog_54067_Content_47 = {Text = "Boom..."},
  AvgDialog_54067_Content_48 = {
    Text = "Enormi tentacoli si protendono dal suolo sotto il Tempio, tra Echi rimbombanti."
  },
  AvgDialog_54067_Content_49 = {
    Text = "È il nostro Signore! Il Miracolo del nostro Signore si è manifestato!!!"
  },
  AvgDialog_54067_Content_5 = {
    Text = "Sia lode al nostro Signore! Sia lode alla Somma Sacerdotessa!"
  },
  AvgDialog_54067_Content_50 = {
    Text = "I Seguaci alzano le braccia, esultando in estasi."
  },
  AvgDialog_54067_Content_51 = {
    Text = "I Tentacoli ondeggiano dolcemente nel vento e nella pioggia, e tutti a Lemuria credono fermamente che queste grandi divinità Lemuriane possiedano il potere di resistere a ogni catastrofe."
  },
  AvgDialog_54067_Content_52 = {
    Text = "Nostro Signore, Tulu—"
  },
  AvgDialog_54067_Content_53 = {
    Text = "Mio Signore, Tulu!! Tulu!!!"
  },
  AvgDialog_54067_Content_54 = {
    Text = "Lei si volta, rivolgendo lo sguardo verso l'interno del Tempio, e si inginocchia."
  },
  AvgDialog_54067_Content_55 = {
    Text = "Ma nessuno può vedere che nei Suoi Occhi non vi è traccia delle aspettative o della dignità della somma sacerdotessa, solo Confusione."
  },
  AvgDialog_54067_Content_56 = {
    Text = "Ascolta l'invocazione dei tuoi Seguaci. Portaci il Reame Divino."
  },
  AvgDialog_54067_Content_57 = {
    Text = "Portateci il Reame Divino!"
  },
  AvgDialog_54067_Content_58 = {
    Text = "Mio signore! Il Reame Divino! Hahaha... Sta arrivando!"
  },
  AvgDialog_54067_Content_59 = {
    Text = "Tra grida folli, i tentacoli presero a danzare. L'aura silenziosa di Aequor si propagò dai tentacoli, fluendo dal Tempio fino a ogni angolo di Lemuria, penetrando i sensi di ogni Lemuriano."
  },
  AvgDialog_54067_Content_6 = {
    Text = "Sua Grazia ci condurrà al Reame Divino!"
  },
  AvgDialog_54067_Content_60 = {Text = "Boom—"},
  AvgDialog_54067_Content_61 = {
    Text = "Nel rombo del tuono, gli Applausi svaniscono. Il fulmine squarcia il cielo, illuminando la terra solitaria di Lemuria."
  },
  AvgDialog_54067_Content_62 = {
    Text = "In questo momento di giubilo, i movimenti dei credenti si arrestano. Restano sospesi nella loro somma lode e fede nel Re, intrappolati per sempre nell'ambra delle loro sconfinate visioni e aneliti per il futuro."
  },
  AvgDialog_54067_Content_63 = {
    Text = "Sotto la pioggia battente, il popolo di Lemuria sprofonda in un sonno profondo."
  },
  AvgDialog_54067_Content_64 = {Text = "..."},
  AvgDialog_54067_Content_65 = {
    Text = "Le porte d'ardesia si chiudono con un suono prolungato e greve."
  },
  AvgDialog_54067_Content_66 = {
    Text = "Un odore denso e pungente di pesce avvolge la stanza di preghiera. Lo spazio un tempo ampio ora appare insopportabilmente affollato."
  },
  AvgDialog_54067_Content_67 = {
    Text = "Tutte le creature-pesce sono state estratte dalla vasca e adagiate sul pavimento."
  },
  AvgDialog_54067_Content_68 = {
    Text = "Le guardie non hanno idea di cosa intenda fare la loro Somma Sacerdotessa, e non avranno mai l'occasione di scoprirlo."
  },
  AvgDialog_54067_Content_69 = {
    Text = "Miryam si avvicina all'angolo della stanza, si accovaccia e accarezza dolcemente la creatura più vicina."
  },
  AvgDialog_54067_Content_7 = {
    Text = "Applausi zealanti si riversano verso l'Altare come onde."
  },
  AvgDialog_54067_Content_70 = {
    Text = "\"Padre... sei tu?\""
  },
  AvgDialog_54067_Content_71 = {
    Text = "\"Sono Miryam, tua figlia.\""
  },
  AvgDialog_54067_Content_72 = {
    Text = "\"Se puoi sentirmi, ti prego rispondimi... Padre...\""
  },
  AvgDialog_54067_Content_73 = {
    Text = "\"...Woo...Woo...\""
  },
  AvgDialog_54067_Content_74 = {
    Text = "Le sue branchie fremono, le labbra tremano in gemiti privi di senso, come sempre."
  },
  AvgDialog_54067_Content_75 = {
    Text = "Miryam si sposta verso il secondo, si china e lo tocca."
  },
  AvgDialog_54067_Content_76 = {
    Text = "\"Padre, sono diventata la Somma Sacerdotessa di Lemuria, ho fatto meglio di quanto avessi immaginato...\""
  },
  AvgDialog_54067_Content_77 = {
    Text = "\"Non ti ho deluso, Padre... Ti prego, apri gli occhi e guardami...\""
  },
  AvgDialog_54067_Content_78 = {
    Text = "I grandi occhi della creatura vagano per questo ambiente sconosciuto, senza mostrare alcun interesse per la Somma Sacerdotessa che le sta dinanzi."
  },
  AvgDialog_54067_Content_79 = {
    Text = "Si avvicina al terzo."
  },
  AvgDialog_54067_Content_8 = {
    Text = "La folla in tumulto ricorda a Miryam gli uomini-pesce nello stagno — occhi spalancati e fissi, che affiorano e sprofondano."
  },
  AvgDialog_54067_Content_80 = {
    Text = "\"Ho visto il Signore, il Signore a cui dedichiamo ogni cosa... ma Egli mi ha detto che Lemuria è condannata.\""
  },
  AvgDialog_54067_Content_81 = {
    Text = "\"Ha detto che potrei salvare Lemuria, che potrei riportarla in vita...\""
  },
  AvgDialog_54067_Content_82 = {
    Text = "\"Non posso credere alle Sue parole. Ma se dubito di Lui, devo accettare che abbiamo vissuto in un grandioso inganno. Tutto ciò che abbiamo fatto, tutto ciò che ho fatto a te... non ha alcun significato.\""
  },
  AvgDialog_54067_Content_83 = {
    Text = "\"Non lo so, non lo so... Padre, cosa dovrei fare?\""
  },
  AvgDialog_54067_Content_84 = {
    Text = "\"Ti prego... apri gli occhi e guardami, Padre... Parlami, e accarezzami la testa, solo un'ultima volta...\""
  },
  AvgDialog_54067_Content_85 = {
    Text = "La fissa con occhi vuoti e vacui, come se contemplasse un filo d'alga purpurea ondeggiante."
  },
  AvgDialog_54067_Content_86 = {
    Text = "Miryam si volge alla creatura successiva, poi a quella dopo... Si china, accarezzando e baciando ciascuna di esse."
  },
  AvgDialog_54067_Content_87 = {
    Text = "Il suo maestro le aveva imposto il dovere; il suo Signore le aveva offerto una speranza vuota. Ma colui che poteva ascoltare il suo terrore, la sua angoscia e il suo pianto, colui la cui mano ruvida e larga le accarezzava dolcemente i capelli per confortarla... è ormai da tempo perduto nell'oscurità."
  },
  AvgDialog_54067_Content_88 = {
    Text = "Si avvicina a ciascuna delle creature-pesce, sussurrando il suo disperato anelito, cercando tra loro la minima traccia di lui."
  },
  AvgDialog_54067_Content_89 = {
    Text = "Suo padre è ancora vivo? Ciò che è sopravvissuto può ancora essere considerato suo padre?"
  },
  AvgDialog_54067_Content_9 = {
    Text = "Si sente come se stesse sprofondando negli abissi; l'acqua marina sembra colmare ogni suo senso. Le immagini si offuscano, i suoni si dissolvono nel caos."
  },
  AvgDialog_54067_Content_90 = {
    Text = "Non sa. Non le importa."
  },
  AvgDialog_54067_Content_91 = {
    Text = "Il fragore della pioggia battente riecheggia tra le mura. Nella vasta stanza di preghiera, innumerevoli creature-pesce giacciono al suolo, agitando arti e pinne."
  },
  AvgDialog_54067_Content_92 = {
    Text = "Una figura purpurea si muove tra loro, cercando, liberandosi del proprio fardello."
  },
  AvgDialog_54067_Content_93 = {
    Text = "Una statua semidistrutta siede su un trono spezzato, osservandola in silenzio."
  },
  AvgDialog_54067_Content_94 = {Text = "..."},
  AvgDialog_54067_Content_95 = {Text = "Boom—"},
  AvgDialog_54067_Content_96 = {
    Text = "Il tuono ruggì sopra la testa del vecchio. Egli lo ignorò e salì l'ultimo gradino di pietra."
  },
  AvgDialog_54067_Content_97 = {
    Text = "\"Huff... huff...\""
  },
  AvgDialog_54067_Content_98 = {
    Text = "È troppo vecchio, scalare questa montagna da solo è un compito così arduo per lui."
  },
  AvgDialog_54067_Content_99 = {
    Text = "Crollò sulla cima spoglia della montagna, ansimando, i polmoni sibilanti come mulini a vento arrugginiti, emettendo un gemito decrepito."
  },
  AvgDialog_54802_Content_1 = {Text = "Ah!—"},
  AvgDialog_54802_Content_10 = {
    Text = "Là... là c'è..."
  },
  AvgDialog_54802_Content_100 = {
    Text = "Quella mano sfregiata porse a Horla una rosa leggermente danneggiata, ma ancora di un rosso vivido."
  },
  AvgDialog_54802_Content_101 = {
    Text = "Un bel poema, Horla... In futuro, scambierò i miei fiori con i tuoi poemi!"
  },
  AvgDialog_54802_Content_11 = {
    Text = "Vi trovate al margine della piazza del giardino. D-fessure visibili si propagano verso l'alto da sotto il piccolo edificio, avvolgendo lo spazio aperto al centro del giardino."
  },
  AvgDialog_54802_Content_12 = {
    Text = "Quello è... il nostro giardino... no... Colette, no..."
  },
  AvgDialog_54802_Content_13 = {
    Text = "Horla abbassò il capo. Colette le si avvicinò, le sollevò il mento e diresse il suo sguardo verso il centro del giardino."
  },
  AvgDialog_54802_Content_14 = {
    Text = "Sai, Horla... Molti anni fa, ho guardato quel grande incendio divampare proprio qui."
  },
  AvgDialog_54802_Content_15 = {
    Text = "Ho trasformato questo luogo in una piazza e vi ho eretto la mia statua... Vedi, anch'io comprendo il simbolismo."
  },
  AvgDialog_54802_Content_16 = {
    Text = "Guarda attentamente. Guarda bene. Quello è il luogo in cui viviamo... Quello è il nostro giardino. Presto, tutto ciò che vi si trova scomparirà."
  },
  AvgDialog_54802_Content_17 = {
    Text = "La mia vita è davvero iniziata il giorno in cui sei morta. Oggi, si avvierà nuovamente verso lo splendore..."
  },
  AvgDialog_54802_Content_18 = {
    Text = "La fessura nera si propaga rapidamente. In breve, l'intera villa lussuosa viene inghiottita."
  },
  AvgDialog_54802_Content_19 = {
    Text = "Giardino, ceneri, scarabocchi, poesia, memorie, risate, giuramenti... Tutto è sprofondato nell'oscurità senza fine."
  },
  AvgDialog_54802_Content_2 = {
    Text = "La vostra imboscata ha abbattuto con successo Colette, ma quando vi siete avvicinati, innumerevoli tralci fioriti sono spuntati dal terreno intorno a lei."
  },
  AvgDialog_54802_Content_20 = {Text = "Tic-tac—"},
  AvgDialog_54802_Content_21 = {
    Text = "Eh? Cosa hanno i miei occhi...?"
  },
  AvgDialog_54802_Content_22 = {
    Text = "Era... dolore al cuore, poco fa? Perché..."
  },
  AvgDialog_54802_Content_23 = {
    Text = "Una lacrima scivolò lungo il volto di Horla."
  },
  AvgDialog_54802_Content_24 = {
    Text = "Le lacrime cadono a terra, come gocce in un lago immobile. Increspature silenziose si propagano, sfiorando ogni cuore pallido in questo mondo illusorio."
  },
  AvgDialog_54802_Content_25 = {
    Text = "!! No... questa sensazione..."
  },
  AvgDialog_54802_Content_26 = {
    Text = "Colette notò il cambiamento nelle proprie emozioni. Guardò Horla accanto a sé con sorpresa."
  },
  AvgDialog_54802_Content_27 = {
    Text = "<LightGray:Questa è... la capacità di Horla di diffondere emozioni?!>"
  },
  AvgDialog_54802_Content_28 = {
    Text = "<LightGray:Questo Dominio si basa sulla poesia di Horla... La sua Abilità potrebbe entrare in gioco!>"
  },
  AvgDialog_54802_Content_29 = {
    Text = "Vuoi uccidermi e usare la poesia per ottenere la vita che desideri... Qualunque cosa tu abbia fatto, non ti ho mai odiata, Colette."
  },
  AvgDialog_54802_Content_3 = {
    Text = "Le spine sui tralci fioriti hanno trafitto i vostri corpi, legandovi saldamente."
  },
  AvgDialog_54802_Content_30 = {
    Text = "La Colette che conoscevo un tempo era la mia migliore amica. Ma se distruggi questo luogo... rimarrà soltanto la Colette di adesso."
  },
  AvgDialog_54802_Content_31 = {
    Text = "Non posso... permettere che la Colette che conoscevo un tempo venga cancellata da te..."
  },
  AvgDialog_54802_Content_32 = {
    Text = "Guardati, Horla... Cos'altro sai fare, oltre a scrivere poesie?"
  },
  AvgDialog_54802_Content_33 = {
    Text = "Hai ragione... A parte scrivere poesie, non sono brava in nient'altro..."
  },
  AvgDialog_54802_Content_34 = {
    Text = "Cité è una città di fiori e poesia, la nostra casa... ma le rose sono tutte morte, Colette..."
  },
  AvgDialog_54802_Content_35 = {
    Text = "Queste rose sono quelle che un tempo mi donasti. Oggi te le restituisco."
  },
  AvgDialog_54802_Content_36 = {
    Text = "Fa un passo avanti."
  },
  AvgDialog_54802_Content_37 = {Text = "Horla!!!"},
  AvgDialog_54802_Content_38 = {
    Text = "Un'enorme spina di rosa le trafisse il cuore."
  },
  AvgDialog_54802_Content_39 = {
    Text = "Il suo sangue scorre lungo i tralci neri."
  },
  AvgDialog_54802_Content_4 = {
    Text = "Tu... mi hai sporcato i vestiti..."
  },
  AvgDialog_54802_Content_40 = {
    Text = "I fiori neri appassiscono rapidamente sui rami."
  },
  AvgDialog_54802_Content_41 = {
    Text = "Un bocciolo di rosa rossa emerge dal ramo, si schiude e fiorisce."
  },
  AvgDialog_54802_Content_42 = {
    Text = "Il sangue scorre lungo i rami, come le venature delle foglie, propagandosi in ogni angolo della città."
  },
  AvgDialog_54802_Content_43 = {
    Text = "Dove passa, il nero oscuro svanisce."
  },
  AvgDialog_54802_Content_44 = {
    Text = "Restituisce colore ed emozioni, fiori e poesia a Cité."
  },
  AvgDialog_54802_Content_45 = {
    Text = "Così... tanto dolore..."
  },
  AvgDialog_54802_Content_46 = {
    Text = "Il cuore... sembra trafitto..."
  },
  AvgDialog_54802_Content_47 = {
    Text = "Quella è... la Madre! Madre..."
  },
  AvgDialog_54802_Content_48 = {
    Text = "Il bambino... il mio bambino è nato..."
  },
  AvgDialog_54802_Content_49 = {
    Text = "Mentre il sangue si propaga, visioni si dispiegano davanti agli occhi della gente."
  },
  AvgDialog_54802_Content_5 = {
    Text = "Sai quanto è costato questo abito?"
  },
  AvgDialog_54802_Content_50 = {
    Text = "È la rinascita dalla terra del neonato, la ninnananna della madre e l'addio degli amanti."
  },
  AvgDialog_54802_Content_51 = {
    Text = "Quello è stato il momento più prezioso delle vostre vite."
  },
  AvgDialog_54802_Content_53 = {
    Text = "L'immenso dolore che Horla sopportò si propagò per tutta Cité, increspandosi con il suo sangue."
  },
  AvgDialog_54802_Content_54 = {
    Text = "Spuntoni di rosa perforano innumerevoli cuori. Fiori cremisi sbocciano in ognuno di essi."
  },
  AvgDialog_54802_Content_55 = {
    Text = "Questa è... la poesia che hai scritto...?"
  },
  AvgDialog_54802_Content_56 = {
    Text = "Le lacrime lavarono via il suo trucco delicato, ma non le importava, lasciando che tracciassero segni disordinati sul suo viso."
  },
  AvgDialog_54802_Content_57 = {
    Text = "Colette non ricordava quando le sue lacrime avessero cominciato a scorrere."
  },
  AvgDialog_54802_Content_58 = {
    Text = "—Scene del passato si dispiegano nitide davanti a lei. Per la prima volta, comprese davvero la poesia di Horla. Finalmente capì ciò che custodiva nel profondo del cuore."
  },
  AvgDialog_54802_Content_59 = {
    Text = "Non solo lei. Tutti a Cité compresero le poesie di Horla."
  },
  AvgDialog_54802_Content_6 = {
    Text = "La rabbia di Colette svanì rapidamente. Riprese il suo sorriso nobile e composto."
  },
  AvgDialog_54802_Content_60 = {
    Text = "Il desiderio di potere svanisce, le emozioni ritornano. Le fondamenta su cui questo mondo era stato costruito sono scomparse in questa poesia."
  },
  AvgDialog_54802_Content_61 = {
    Text = "Sentiva il suo Potere affievolirsi. Sentiva la sconfitta avvicinarsi. Evocò lame simili a spine e si incamminò verso Horla."
  },
  AvgDialog_54802_Content_62 = {
    Text = "\"Colette,\" vittoria... Quando il cane della vecchia signora morì e lei mi diede il suo nome, tu eri proprio accanto a me."
  },
  AvgDialog_54802_Content_63 = {
    Text = "Non ho mai cambiato questo nome, perché non voglio perdere di nuovo, Horla..."
  },
  AvgDialog_54802_Content_64 = {
    Text = "Colette singhiozzò di dolore, barcollando verso Horla."
  },
  AvgDialog_54802_Content_65 = {
    Text = "Il Dominio sta svanendo. Il tuo piano è fallito, Colette!"
  },
  AvgDialog_54802_Content_66 = {
    Text = "Anche se la attacchi ora, non cambierà nulla!"
  },
  AvgDialog_54802_Content_67 = {
    Text = "Lottate per avvicinarvi a Horla, ma spine e dolore vi circondano, lasciandovi immobilizzati."
  },
  AvgDialog_54802_Content_68 = {
    Text = "Lo spuntone si protende verso la testa di Horla."
  },
  AvgDialog_54802_Content_69 = {Text = "Aspetta!!"},
  AvgDialog_54802_Content_7 = {
    Text = "Va tutto bene, va tutto bene..."
  },
  AvgDialog_54802_Content_70 = {Text = "*Snap*—"},
  AvgDialog_54802_Content_71 = {
    Text = "Una rosa fu tagliata. Colette la prese e la porse a Horla."
  },
  AvgDialog_54802_Content_72 = {
    Text = "Una bella poesia, Horla... Scambierò i miei fiori con i tuoi versi..."
  },
  AvgDialog_54802_Content_73 = {Text = "Bang—"},
  AvgDialog_54802_Content_74 = {
    Text = "Forse la dissoluzione del Dominio ha cambiato la giardiniera."
  },
  AvgDialog_54802_Content_75 = {
    Text = "O forse è stata la trasformazione della giardiniera a causare la Dissoluzione del Dominio."
  },
  AvgDialog_54802_Content_76 = {
    Text = "La Cité nei poemi sta gradualmente scomparendo, e anche il potere che sosteneva Colette è svanito."
  },
  AvgDialog_54802_Content_77 = {
    Text = "Il suo corpo si trasformò in una pozza di melma nera, mescolata a petali sparsi, sprofondando nel terreno davanti a Horla."
  },
  AvgDialog_54802_Content_78 = {
    Text = "Colette, Colette, hai finito di leggere?"
  },
  AvgDialog_54802_Content_79 = {
    Text = "Hmm... Ho finito di leggere... ma non lo capisco del tutto."
  },
  AvgDialog_54802_Content_8 = {
    Text = "Affrontarmi nel mio giardino... dovete essere tanto coraggiosi quanto sciocchi."
  },
  AvgDialog_54802_Content_80 = {
    Text = "Ah, davvero...? Questo è il mio primo poema. Non è molto buono..."
  },
  AvgDialog_54802_Content_81 = {
    Text = "Non sei tu, Horla. In realtà non capisco la poesia di nessuno."
  },
  AvgDialog_54802_Content_82 = {
    Text = "Ho chiesto a molte persone intorno a me, e nemmeno loro riuscivano a dargli un senso."
  },
  AvgDialog_54802_Content_83 = {
    Text = "Non capisco... Che senso ha qualcosa che nessuno riesce a comprendere?"
  },
  AvgDialog_54802_Content_84 = {
    Text = "Hmm... Credo che la poesia non sia solo parole o immagini; è come una chiave."
  },
  AvgDialog_54802_Content_85 = {
    Text = "Una... chiave?"
  },
  AvgDialog_54802_Content_86 = {
    Text = "Sì! Il cuore di una persona è come uno scrigno colmo di emozioni. Questo scrigno è chiuso a chiave, e queste emozioni di solito restano dentro, difficili da tirare fuori."
  },
  AvgDialog_54802_Content_87 = {
    Text = "La poesia è la chiave per aprire questo scrigno."
  },
  AvgDialog_54802_Content_88 = {
    Text = "In realtà, la poesia non ha bisogno di essere compresa, e nemmeno letta."
  },
  AvgDialog_54802_Content_89 = {
    Text = "Tutti, che leggano poesia o meno, prima o poi, troveranno questa chiave in qualche momento della loro vita."
  },
  AvgDialog_54802_Content_9 = {
    Text = "Avete sprecato la vostra ultima possibilità di fuga... Questa celebrazione, dovrete vederla fino in fondo con me."
  },
  AvgDialog_54802_Content_90 = {
    Text = "Diventerai sicuramente la migliore fabbra di chiavi!"
  },
  AvgDialog_54802_Content_91 = {
    Text = "Bugiarda... Hai appena detto che non capivi."
  },
  AvgDialog_54802_Content_92 = {
    Text = "Non capisco cosa stai dicendo, ma mi fido di te, Horla."
  },
  AvgDialog_54802_Content_93 = {
    Text = "Questo poema, \"La Dimora delle Rose\", è la tua prima opera. Da oggi in poi, ti aiuterò a custodire tutti i tuoi poemi."
  },
  AvgDialog_54802_Content_94 = {
    Text = "Li terrò insieme con degli spilli, e quando avrò i soldi, stamperò una bella raccolta di poesie!"
  },
  AvgDialog_54802_Content_95 = {
    Text = "Tese la mano, che aveva tenuto nascosta dietro la schiena. Le mani erano coperte di ferite di spine, scure e ruvide, del tutto irriconoscibili come quelle di una bambina."
  },
  AvgDialog_54802_Content_96 = {
    Text = "Questo... questo è..."
  },
  AvgDialog_54802_Content_97 = {
    Text = "I nuovi nobili dicono che Cité sia una città di fiori e poesia. Un buon poema può farti guadagnare un bouquet di rose..."
  },
  AvgDialog_54802_Content_98 = {
    Text = "Le mie rose sono fiorite oggi. Non molte, e sono state tutte usate per pagare l'affitto e il canone del terreno."
  },
  AvgDialog_54802_Content_99 = {
    Text = "Ma mentre non prestavano attenzione, ho tenuto un fiore di nascosto..."
  },
  AvgDialog_56163_Content_1 = {
    Text = "A causa dei recenti incidenti anomali legati ai Risvegliati, la scuola ha rafforzato il monitoraggio e programmato ispezioni regolari per prevenire incidenti."
  },
  AvgDialog_56163_Content_10 = {
    Text = "Sei grat{Male=o,Female=a} di non dover avere a che fare con quella donna consumata dalla follia."
  },
  AvgDialog_56163_Content_11 = {
    Text = "Tuttavia, il tuo istinto da investigatore avverte improvvisamente qualcosa di insolito. Ti fermi e osservi attentamente la luce della candela."
  },
  AvgDialog_56163_Content_12 = {
    Text = "Le ombre che tremolano sulla parete, proiettate dalla fiamma, non sono semplici forme, ma sagome sinuose e striscianti, simili a serpenti."
  },
  AvgDialog_56163_Content_13 = {
    Text = "Ombre serpentine si contorcono attorno alla luce della candela, tentando di ghermire l'unico calore della stanza."
  },
  AvgDialog_56163_Content_14 = {
    Text = "Miryam si volta. Il suo viso è acceso da un rossore insolito e ipnotico, e la sua voce è dolce e felice, come se avesse appena raggiunto la grazia suprema."
  },
  AvgDialog_56163_Content_15 = {
    Text = "Sei tu, Custode. Sei venuto qui in risposta al richiamo del Reame Divino?"
  },
  AvgDialog_56163_Content_16 = {
    Text = "Sebbene le sue membra pallide e sottili siano intrecciate con ombre serpentine guizzanti, le sue mani restano fisse in una postura di preghiera, come una suora vincolata a una missione eterna."
  },
  AvgDialog_56163_Content_17 = {
    Text = "Il tuo cervello urla PERICOLO, ma è troppo tardi per ritirarsi. L'ombra serpentina, fredda e umida, è già strisciata attraverso l'oscurità, avvolgendosi stretta attorno alle tue gambe e arrampicandosi lungo la tua schiena."
  },
  AvgDialog_56163_Content_18 = {
    Text = "Il tuo Corpo è così caldo..."
  },
  AvgDialog_56163_Content_19 = {
    Text = "Hai chiaramente sostituito la debole candela, diventando la principale fonte di calore in questa stanza."
  },
  AvgDialog_56163_Content_2 = {
    Text = "Per gestire potenziali crisi, i controlli delle stanze vengono assegnati a rotazione tra gli Investigatori disponibili. Oggi tocca a te come supervisore del dormitorio."
  },
  AvgDialog_56163_Content_20 = {
    Text = "No, no! Dev'essere un malinteso! Non ho udito alcun richiamo del Reame Divino! Sono qui solo per un controllo di sicurezza!"
  },
  AvgDialog_56163_Content_21 = {
    Text = "La tua spiegazione frenetica è vana. L'ombra serpentina ti trascina al tavolo di preghiera, costringendoti a sederti accanto a Miryam davanti alla statua dai tentacoli guizzanti."
  },
  AvgDialog_56163_Content_22 = {
    Text = "Non provavo una tale gioia ed esaltazione da tempo immemore! Il Reame Divino mi ha risposto!"
  },
  AvgDialog_56163_Content_23 = {
    Text = "Vorresti negare la situazione, ma vedendo la sua espressione beata, saggiamente tieni la lingua a freno."
  },
  AvgDialog_56163_Content_24 = {
    Text = "Il Reame Divino mi esorta ad agire. Dovrei seguire questa direttiva."
  },
  AvgDialog_56163_Content_25 = {
    Text = "Ora, questo decreto vi è stato consegnato."
  },
  AvgDialog_56163_Content_26 = {
    Text = "Volge il capo, le dita tremanti accarezzano dolcemente il tuo viso, stringendoti le guance come per confortarti, come per invitarti."
  },
  AvgDialog_56163_Content_27 = {
    Text = "Vieni, prega con me. Insieme, offriremo ogni cosa per la continuazione del Reame Divino."
  },
  AvgDialog_56163_Content_28 = {
    Text = "Il tocco gelido dell'ombra del serpente ti fa rabbrividire d'ipotermia. La tua resistenza viene schiacciata dalle spire serrate, costringendo il tuo corpo in una postura di reverenza."
  },
  AvgDialog_56163_Content_29 = {
    Text = "E fu così che tu e la fervente Somma Sacerdotessa iniziaste un rito di preghiera... per placare il suo Dio."
  },
  AvgDialog_56163_Content_3 = {
    Text = "Dopo essere stat{Male=o,Female=a} disturbat{Male=o,Female=a} più volte, bussi nervosamente a ogni porta e annoti lo stato normale di ogni studente."
  },
  AvgDialog_56163_Content_4 = {
    Text = "Infine, bussi a una porta, e solo il silenzio risponde. Il cuore ti sprofonda, e realizzi: \"È arrivato il momento.\""
  },
  AvgDialog_56163_Content_5 = {
    Text = "Guardi il nome \"Miryam\" sulla targhetta, apri la porta con espressione seria e sbirci cautamente all'interno."
  },
  AvgDialog_56163_Content_6 = {
    Text = "Miryam? Sei lì?"
  },
  AvgDialog_56163_Content_7 = {
    Text = "Nella stanza buia, un'unica candela tremolante illumina un angolo in penombra, rischiarando una suora immersa in devota preghiera."
  },
  AvgDialog_56163_Content_8 = {
    Text = "La sua postura è di una pace e una serenità assolute, segno di anni di intensa pratica ascetica."
  },
  AvgDialog_56163_Content_9 = {
    Text = "Quindi stavi solo pregando. Scusa per l'interruzione. Dato che stai bene, continuo il mio giro."
  },
  AvgDialog_56308_Content_1 = {
    Text = "Fa così caldo..."
  },
  AvgDialog_56308_Content_10 = {
    Text = "È Difficile capire se stai chiedendo per genuina curiosità o semplicemente per distrarti. Ti guardi intorno."
  },
  AvgDialog_56308_Content_11 = {
    Text = "I fiori sono più rigogliosi, l'aria più soffocante, e l'architettura e la musica più inebrianti e belle che mai."
  },
  AvgDialog_56308_Content_12 = {
    Text = "In questo mondo evocato dal testo, ogni angolo è una Metafora; ogni Ombra è un suggerimento nascosto."
  },
  AvgDialog_56308_Content_13 = {
    Text = "Mi dispiace tanto, Custode... Non so perché, ma i versi che ho scritto oggi... sono sempre... sempre..."
  },
  AvgDialog_56308_Content_14 = {
    Text = "Le sue emozioni si propagano nell'aria come onde. La tua gola si stringe d'istinto."
  },
  AvgDialog_56308_Content_15 = {
    Text = "Allunghi la mano e sollevi delicatamente la pergamena dalla testa di Horla."
  },
  AvgDialog_56308_Content_16 = {Text = "SQUEAK!"},
  AvgDialog_56308_Content_17 = {
    Text = "Reagisce come un coniglio spaventato. Sebbene la maggior parte della sua figura resti invisibile, è chiaramente irrequieta, e le parti del viso che riesci a scorgere sono avvampate di un cremisi intenso fino alle orecchie."
  },
  AvgDialog_56308_Content_18 = {
    Text = "Horla... mi piace questo poema."
  },
  AvgDialog_56308_Content_19 = {
    Text = "Ma... ma non è ancora finito..."
  },
  AvgDialog_56308_Content_2 = {
    Text = "Un'ondata di Irrequietezza inspiegabile ti costringe ad aprire gli Occhi."
  },
  AvgDialog_56308_Content_20 = {
    Text = "Allora finiamolo insieme."
  },
  AvgDialog_56308_Content_21 = {
    Text = "Il... il verso successivo... quale dovrebbe essere..."
  },
  AvgDialog_56308_Content_22 = {
    Text = "Il sol è tramontato, e ogni occhio indiscreto è avvolto dalle tenebre..."
  },
  AvgDialog_56308_Content_23 = {
    Text = "Sia il sole che le stelle si sono affrettati al riposo..."
  },
  AvgDialog_56308_Content_24 = {
    Text = "...Tranne le rose, celate nel segreto profondo del muro del suo giardino."
  },
  AvgDialog_56308_Content_25 = {
    Text = "Parole invisibili iniziano a manifestarsi intorno a lei, e il giardino del poema si dissolve nel crepuscolo."
  },
  AvgDialog_56308_Content_26 = {
    Text = "La voce gentile di Horla si avvicina sempre di più. Odi i suoi respiri sommessi e affrettati; avverti il calore tremante della sua pelle."
  },
  AvgDialog_56308_Content_27 = {
    Text = "—Là, nel giardino immerso nell'oscurità, apprendesti il segreto di una rosa."
  },
  AvgDialog_56308_Content_3 = {Text = "!!!"},
  AvgDialog_56308_Content_4 = {
    Text = "Non stavo dormendo nel mio dormitorio...? Dove mi trovo?"
  },
  AvgDialog_56308_Content_5 = {
    Text = "M-Mi dispiace... Custode..."
  },
  AvgDialog_56308_Content_6 = {
    Text = "Oh, sei tu... questo spiega tutto."
  },
  AvgDialog_56308_Content_7 = {
    Text = "Il Potere di proiettare emozioni, combinato con l'influenza del Fiume sacro... una combinazione pericolosa."
  },
  AvgDialog_56308_Content_8 = {
    Text = "Sotto l'influenza di Horla, finalmente comprendi cosa significhi essere davvero toccati dal Fiume sacro."
  },
  AvgDialog_56308_Content_9 = {
    Text = "Il tuo \"mondo poetico\" sembra diverso dal solito, non è vero?"
  },
  AvgDialog_57563_Content_1 = {
    Text = "Sulla via del ritorno da una missione sul campo, vieni sorpreso da un acquazzone torrenziale che ti lascia bloccato nella periferia desolata della città."
  },
  AvgDialog_57563_Content_10 = {
    Text = "Fissi un volto familiare sopra di te, lottando per gracchiare il suo nome tra lo shock e la mancanza d'aria."
  },
  AvgDialog_57563_Content_11 = {
    Text = "Ghak... He... Helot!"
  },
  AvgDialog_57563_Content_12 = {
    Text = "Il sopracciglio della donna sussulta, ma i suoi occhi cremisi non mostrano alcun calore di ricongiungimento—solo uno sguardo freddo e senza fondo."
  },
  AvgDialog_57563_Content_13 = {
    Text = "Proprio quando credi che la tua vita sia perduta, le sue labbra si incurvano in un debole ghigno, e la morsa schiacciante sulla tua gola svanisce d'un tratto."
  },
  AvgDialog_57563_Content_14 = {
    Text = "Quindi sei tu. Mi pare di averti detto che se ti avessi rivisto, ti avrei fatto a pezzi."
  },
  AvgDialog_57563_Content_15 = {
    Text = "Crolli in ginocchio, tossendo con tale violenza da sembrare sul punto di sputare un polmone. Passa un lungo minuto prima che tu riesca anche solo a rotolarti sulla schiena."
  },
  AvgDialog_57563_Content_16 = {
    Text = "Non lo faresti... coff... perché siamo... amici..."
  },
  AvgDialog_57563_Content_17 = {
    Text = "Ora che riesci a vederla chiaramente, ti blocchi. I vestiti le aderiscono al corpo, grondanti di pioggia. L'odore del sangue si mescola all'aria umida, e il suo viso pallido è arrossato da un calore febbrile e malsano."
  },
  AvgDialog_57563_Content_18 = {
    Text = "Massicce catene sono fuse direttamente nel suo corpo; gli arti, avvinti da catene, pulsano di una mescolanza minacciosa di nero e rosso."
  },
  AvgDialog_57563_Content_19 = {
    Text = "Ricordi il vostro incontro sulla montagna innevata e istintivamente deglutisci un nodo in gola."
  },
  AvgDialog_57563_Content_2 = {
    Text = "Per fortuna, ti ricordi di una fabbrica abbandonata nelle vicinanze—un riparo sufficiente per un viaggiatore sfortunato come te."
  },
  AvgDialog_57563_Content_20 = {
    Text = "Mi sa che hai frainteso qualcosa. Non confondermi con quella debole."
  },
  AvgDialog_57563_Content_21 = {
    Text = "Vedendo l'intento omicida riaccendersi nei suoi occhi, ti affretti a offrire la premura di un \"amico\"."
  },
  AvgDialog_57563_Content_22 = {
    Text = "No, no! Non importa quale delle due tu sia, sei comunque mia amica!"
  },
  AvgDialog_57563_Content_23 = {
    Text = "Metti da parte quello un momento — sei ferito?"
  },
  AvgDialog_57563_Content_24 = {
    Text = "Un tremolio strano e complesso le attraversa il volto: freddezza, irritazione, e una traccia di autentico sconcerto."
  },
  AvgDialog_57563_Content_25 = {
    Text = "La ferita non è nulla, ma credo di essere stata avvelenata. Il mio corpo... lo sento strano."
  },
  AvgDialog_57563_Content_26 = {
    Text = "L'attimo di vulnerabilità svanisce con la stessa rapidità con cui è apparso, sostituito da un'ondata di brutalità pura."
  },
  AvgDialog_57563_Content_27 = {
    Text = "Se trovo chi mi ha fatto questo, gli schiaccerò gli organi vitali, uno per uno."
  },
  AvgDialog_57563_Content_28 = {
    Text = "Rendendoti conto che sta avvertendo gli effetti del Fiume sacro, decidi di tenere per te quella spiegazione e ti limiti ad annuire."
  },
  AvgDialog_57563_Content_29 = {Text = "Hmm..."},
  AvgDialog_57563_Content_3 = {
    Text = "Ti appoggi a un angolo, ascoltando la pioggia martellare ritmicamente sul tetto di lamiera ondulata della fabbrica."
  },
  AvgDialog_57563_Content_30 = {
    Text = "In ogni caso, io non ho cose come gli \"amici\"."
  },
  AvgDialog_57563_Content_31 = {
    Text = "Il tuo battito accelera."
  },
  AvgDialog_57563_Content_32 = {
    Text = "Ma la tua aura è pulita. Nessuna malizia. Non hai l'odore di un bugiardo."
  },
  AvgDialog_57563_Content_33 = {
    Text = "Ti studia ancora una volta, apparentemente decisa a concederti un frammento della sua fiducia."
  },
  AvgDialog_57563_Content_34 = {
    Text = "Si siede contro il muro, occupando il posto esatto che avevi appena lasciato."
  },
  AvgDialog_57563_Content_35 = {
    Text = "Dato che prima sei stato di qualche utilità, ora mi riposo. Tu... monta la guardia."
  },
  AvgDialog_57563_Content_36 = {
    Text = "Se ti becco a fare una mossa..."
  },
  AvgDialog_57563_Content_37 = {
    Text = "Scuoti la testa freneticamente, facendo del tuo meglio per sembrare l'incarnazione della lealtà."
  },
  AvgDialog_57563_Content_38 = {
    Text = "I suoi occhi si chiudono lentamente. Il suo corpo bagnato si raggomitola istintivamente, come una bestia ferita in cerca di riparo dalla notte."
  },
  AvgDialog_57563_Content_39 = {Text = "Aspetta!"},
  AvgDialog_57563_Content_4 = {
    Text = "Darei qualsiasi cosa per essere nel mio dormitorio in questo momento..."
  },
  AvgDialog_57563_Content_40 = {
    Text = "Quegli occhi rossi e feroci si spalancano di colpo, fulminandoti con un'impazienza letale."
  },
  AvgDialog_57563_Content_41 = {
    Text = "Ti sfili il cappotto e glielo posi delicatamente sulle spalle."
  },
  AvgDialog_57563_Content_42 = {
    Text = "Lei abbassa lo sguardo sull'indumento per un istante, ma non lo scosta."
  },
  AvgDialog_57563_Content_43 = {
    Text = "Mentre sprofonda in un sonno profondo e sfinito, l'Helot esausta stringe l'orlo del tuo cappotto. L'Odio radicato e la Sete di Sangue impressi sulla sua fronte iniziano finalmente ad attenuarsi."
  },
  AvgDialog_57563_Content_44 = {
    Text = "Fuori, la Pioggia comincia a diradarsi, tamburellando sommessa sul tetto."
  },
  AvgDialog_57563_Content_45 = {
    Text = "Nel silenzio della Fabbrica, risuona soltanto il vostro respiro, che si accorda lentamente al suo."
  },
  AvgDialog_57563_Content_46 = {
    Text = "Due viaggiatori solitari, in Riposo nella lunga notte di Pioggia."
  },
  AvgDialog_57563_Content_5 = {
    Text = "Proprio mentre chiudi gli occhi per addormentarti, uno scricchiolio agghiacciante riecheggia nello spazio. È il suono delle porte arrugginite della fabbrica forzate ad aprirsi."
  },
  AvgDialog_57563_Content_6 = {
    Text = "Incerto su chi—o cosa—sia entrato, trattieni il respiro e ti alzi lentamente in piedi."
  },
  AvgDialog_57563_Content_7 = {
    Text = "Prima che tu possa indagare, un fischio acuto squarcia il silenzio."
  },
  AvgDialog_57563_Content_8 = {
    Text = "Ti getti di lato appena in tempo. Un'enorme sfera chiodata si schianta nel punto in cui ti trovavi, scavando un profondo cratere nel cemento."
  },
  AvgDialog_57563_Content_9 = {
    Text = "Prima ancora che tu possa elaborare l'attacco, una mano alimentata da puro istinto omicida ti afferra la gola, inchiodandoti al suolo."
  },
  AvgDialog_57592_Content_1 = {
    Text = "Quando oggi Ryker ha spennato il diciassettesimo studente al tavolo da gioco, qualcuno ha finalmente fatto la spia, correndo in lacrime dal Custode."
  },
  AvgDialog_57592_Content_10 = {
    Text = "Non essere così spietato. Mi fermo, promesso! Ma solo se giochi <Yellow:un> ultimo round con me. Solo uno. Scommetteremo... la cosa più preziosa..."
  },
  AvgDialog_57592_Content_11 = {
    Text = "La coda canina di Ryker scodinzola allegramente. Il suo naso umido si strofina contro di te, annusando avidamente, come un predatore a caccia del boccone più succulento. Sfiora persino accidentalmente il lobo del tuo orecchio."
  },
  AvgDialog_57592_Content_12 = {
    Text = "La Scommessa, eh..."
  },
  AvgDialog_57592_Content_13 = {
    Text = "Ti irrigidisci come una lastra d'acciaio inflessibile, osservando con diffidenza l'uomo-bestia fin troppo eccitato."
  },
  AvgDialog_57592_Content_14 = {
    Text = "Nessuno a scuola è ancora riuscito a battere Ryker al tavolo da gioco; la cosiddetta scommessa non è diversa da una rapina in piena regola. Cominci a elaborare strategie di negoziazione, preparandoti a contrattare."
  },
  AvgDialog_57592_Content_15 = {
    Text = "La Scommessa, eh..."
  },
  AvgDialog_57592_Content_16 = {
    Text = "Sembra essere una bella Domanda. Ryker ti gira intorno, mormorando qualcosa sottovoce, le sue parole appena udibili."
  },
  AvgDialog_57592_Content_17 = {
    Text = "Ah, sei davvero speciale. Lo sento; il tuo profumo è delizioso. Se solo potessi dare un morso, se solo potessi assaggiare..."
  },
  AvgDialog_57592_Content_18 = {Text = "Cosa?"},
  AvgDialog_57592_Content_19 = {
    Text = "Ben presto, il suo respiro caldo indugia al tuo orecchio. La bestia bramosa scopre le zanne, la voce densa di Desiderio:"
  },
  AvgDialog_57592_Content_2 = {
    Text = "Ryker! Smettila subito con il tuo gioco d'azzardo illegale!"
  },
  AvgDialog_57592_Content_20 = {
    Text = "La Scommessa. Facciamo che sia... un bacio."
  },
  AvgDialog_57592_Content_3 = {
    Text = "Spalanchi la porta con un <Italic:BANG>, gridando come un integerrimo agente di polizia."
  },
  AvgDialog_57592_Content_4 = {
    Text = "Il grande tavolo da gioco al centro della stanza è circondato da studenti storditi e tremanti. Alcuni hanno persino lacrime di disperazione che rigano i loro volti, come se qualche zampa diabolica avesse strappato loro la cosa più importante della vita."
  },
  AvgDialog_57592_Content_5 = {
    Text = "Noioso, così noioso! Poste così misere non rendono davvero giustizia al vostro presunto spirito audace!"
  },
  AvgDialog_57592_Content_6 = {
    Text = "L'audace bestia martella il tavolo, seduta con aria compiaciuta in mezzo a una montagna di bizzarri bottini. Chiaramente, non mostra il benché minimo rimorso."
  },
  AvgDialog_57592_Content_7 = {
    Text = "Oh, sei tu, mio Watson! Sei venuto a giocare qualche mano anche tu?"
  },
  AvgDialog_57592_Content_8 = {
    Text = "Gli occhi del lupo, di solito così indolente, si accendono all'improvviso. Nel momento in cui ti scorge, si avvicina, le orecchie pelose dritte per l'eccitazione."
  },
  AvgDialog_57592_Content_9 = {
    Text = "Ti consiglio di fermarti ora, prima che le autorità scolastiche arrivino e sigillino questo posto."
  },
  AvgDialog_57723_Content_1 = {
    Text = "Di recente, voci di Eventi soprannaturali si sono diffuse per il campus: nel cuore della notte, dalla sala musica vuota risuona spesso una musica spontanea."
  },
  AvgDialog_57723_Content_10 = {
    Text = "I tasti bianchi e neri del pianoforte ti attraggono come un vortice."
  },
  AvgDialog_57723_Content_11 = {
    Text = "Che meraviglia..."
  },
  AvgDialog_57723_Content_12 = {
    Text = "Posi le mani sui tasti, cedendo a un Desiderio istintivo, e cominci a giocare, affidandoti alla tua mediocre Abilità musicale."
  },
  AvgDialog_57723_Content_13 = {
    Text = "Iniziando con esitazione, la melodia prende lentamente forma. La musica, raccogliendosi da rivoli, confluisce in una corrente fluida che attraversa la sala da concerto vuota."
  },
  AvgDialog_57723_Content_14 = {Text = "..."},
  AvgDialog_57723_Content_15 = {
    Text = "Qualcosa nell'aria sembra gradualmente rapprendersi. Mantieni la tua lucidità, continuando a suonare senza Espressione, il tuo contegno solenne, come un pellegrino della musica."
  },
  AvgDialog_57723_Content_16 = {
    Text = "Infine, un sospiro risuona da un luogo sconosciuto, apparentemente dal confine del cielo, eppure proprio accanto al tuo orecchio."
  },
  AvgDialog_57723_Content_17 = {
    Text = "L'hai suonato nel modo sbagliato."
  },
  AvgDialog_57723_Content_18 = {
    Text = "Un paio di mani invisibili si posa sulle tue. Sembra una presa intima, eppure mantiene una prossimità che sfiora appena."
  },
  AvgDialog_57723_Content_19 = {
    Text = "Senti una forza guidare delicatamente le tue dita, Correggere una nota sbagliata dopo l'altra."
  },
  AvgDialog_57723_Content_2 = {
    Text = "Ripetute Indagini non sono riuscite a trovare alcuna persona, e coloro che sono entrati nella sala musica per ascoltare la composizione hanno sviluppato vari gradi di Follia."
  },
  AvgDialog_57723_Content_20 = {
    Text = "Un brivido vertiginoso si propaga dai tuoi timpani attraverso tutto il Corpo. L'esecuzione quasi perfetta rivela immediatamente la bellezza Completa della partitura."
  },
  AvgDialog_57723_Content_21 = {
    Text = "Il tuo respiro si arresta istintivamente, come se stessi annegando in un torrente di musica, sprofondando gradualmente in onde che ora si innalzano impetuose come l'acciaio, ora si fanno morbide come il cotone."
  },
  AvgDialog_57723_Content_22 = {
    Text = "Sta diventando un po'... sfocato..."
  },
  AvgDialog_57723_Content_23 = {
    Text = "Fissi lo sguardo sulla partitura, i tasti nella tua visione periferica danzano in modo abbagliante, il busto si protende in avanti inconsciamente."
  },
  AvgDialog_57723_Content_24 = {
    Text = "Striature di Sangue trasudano lentamente attraverso la partitura. Senti un Desiderio Innato di vedere la partitura più chiaramente, di inciderla nella tua mente."
  },
  AvgDialog_57723_Content_25 = {
    Text = "La tua testa si avvicina alla partitura, sempre più vicina."
  },
  AvgDialog_57723_Content_26 = {
    Text = "Il sospiro riappare ancora una volta. Una forza irresistibile afferra le tue mani."
  },
  AvgDialog_57723_Content_27 = {Text = "Fermati."},
  AvgDialog_57723_Content_28 = {
    Text = "Un clangore dissonante si abbatte sui tasti, e tutta la musica cessa bruscamente."
  },
  AvgDialog_57723_Content_29 = {
    Text = "Il sudore ti cola addosso; ansimi senza sosta."
  },
  AvgDialog_57723_Content_3 = {
    Text = "Vedendo che nessuno Studente o insegnante osa restare nell'edificio di notte, tu, portando l'ultima speranza, giungi infine in questa misteriosa sala musica nel cuore della notte."
  },
  AvgDialog_57723_Content_30 = {
    Text = "A un certo punto, il paio di mani che ricopriva le tue si manifesta fisicamente."
  },
  AvgDialog_57723_Content_31 = {
    Text = "Sono mani avvolte in guanti bianchi, lunghe ed eleganti."
  },
  AvgDialog_57723_Content_32 = {
    Text = "Volti la testa e vedi il proprietario di quelle mani dietro di te — un lampo di impotenza attraversa il volto gelido di Hameln."
  },
  AvgDialog_57723_Content_33 = {Text = "Sei tu!"},
  AvgDialog_57723_Content_34 = {
    Text = "Tenti di alzarti, ma un'ondata di vertigini ti ferma."
  },
  AvgDialog_57723_Content_35 = {
    Text = "Le mani guantate di bianco premono delicatamente sulla tua spalla e traggono un flauto dall'aria."
  },
  AvgDialog_57723_Content_36 = {
    Text = "La forma del flauto è vaga e difficile da discernere, eppure inspiegabilmente ti infonde un senso di sicurezza."
  },
  AvgDialog_57723_Content_37 = {
    Text = "Per favore, riposati. Veglierò su di te."
  },
  AvgDialog_57723_Content_38 = {
    Text = "Hameln porta il flauto alle labbra. Il suono etereo avvolge le tue orecchie, come braccia che ti stringono dolcemente."
  },
  AvgDialog_57723_Content_39 = {
    Text = "Una sonnolenza irresistibile ti travolge. Ti accasci sul pianoforte, sprofondando in un sonno dolce e profondo."
  },
  AvgDialog_57723_Content_4 = {
    Text = "Oltre la pesante porta insonorizzata, regna il Silenzio, come la notte impone, con solo i tuoi Passi che risuonano sommessamente."
  },
  AvgDialog_57723_Content_40 = {
    Text = "Lo sguardo di Hameln si posa sul tuo volto addormentato e sereno. Un mormorio vago si disperde nella notte silenziosa, inudito da chiunque."
  },
  AvgDialog_57723_Content_41 = {
    Text = "Per sempre, e in eterno..."
  },
  AvgDialog_57723_Content_5 = {
    Text = "Strano, non ci sono tracce di Dissoluzione nemmeno qui..."
  },
  AvgDialog_57723_Content_6 = {
    Text = "Dopo un giro infruttuoso di Indagine, ti avvicini al pianoforte al centro della stanza e, come posseduto, raccogli alcuni fogli di musica posati sul leggio."
  },
  AvgDialog_57723_Content_7 = {
    Text = "Qualcuno ha lasciato il suo spartito?"
  },
  AvgDialog_57723_Content_8 = {
    Text = "Sembra essere una partitura musicale incompiuta, eppure la melodia esistente è già sufficiente per essere un capolavoro storico."
  },
  AvgDialog_57723_Content_9 = {
    Text = "I tuoi occhi si fissano intensamente sulle singole note. Quasi ossessivamente, ti siedi."
  },
  AvgDialog_57804_Content_1 = {
    Text = "Si può udire la voce di Hameln"
  },
  AvgDialog_57804_Content_2 = {
    Text = "Chiaramente fuori controllo! Abbasserò prima il suo livello di fusione!"
  },
  AvgDialog_57813_Content_1 = {
    Text = "Custode... zzzz... l'altra \"Doll\" si è liberata... Pozza nera... tu... pericolo... zzzz..."
  },
  AvgDialog_57813_Content_10 = {
    Text = "Ti rialzi lentamente e indietreggi, sforzandoti di porre una domanda."
  },
  AvgDialog_57813_Content_11 = {
    Text = "Sei venuta a trovarmi all'improvviso perché hai visto un nuovo futuro?"
  },
  AvgDialog_57813_Content_12 = {
    Text = "\"Doll\" ti osserva, seguendo i tuoi passi, colmando la distanza come se foste impegnati in una danza silenziosa e intima."
  },
  AvgDialog_57813_Content_13 = {
    Text = "Il futuro non può essere cambiato, ma di recente ho avuto un'improvvisa ispirazione e ho finalmente capito il modo più rapido per raggiungere la fine."
  },
  AvgDialog_57813_Content_14 = {
    Text = "...E cosa intendi fare?"
  },
  AvgDialog_57813_Content_15 = {
    Text = "Chiedi con fare collaborativo della sua affermazione incompiuta mentre indietreggi, finché non urti il muro alle tue spalle."
  },
  AvgDialog_57813_Content_16 = {
    Text = "Naturalmente... eliminerò la variabile più grande di tutto Mythag."
  },
  AvgDialog_57813_Content_17 = {
    Text = "Nell'istante in cui finisce di parlare, ti lanci di lato senza esitazione, le braccia a proteggere la testa, e ti scagli verso la finestra sulla parete."
  },
  AvgDialog_57813_Content_18 = {
    Text = "Il vetro si frantuma con un fragore, innumerevoli frammenti scintillanti che riflettono il tuo volto e quello di \"Doll\". Atterri al suolo in una postura ammortizzata standard, ignori i tagli sulla pelle e cominci a correre disperatamente."
  },
  AvgDialog_57813_Content_19 = {Text = "Il Campus."},
  AvgDialog_57813_Content_2 = {
    Text = "L'improvvisa comunicazione Argento tremola e svanisce, rivelando una crisi che ti fa rizzare i capelli in testa."
  },
  AvgDialog_57813_Content_20 = {Text = "Corridoio."},
  AvgDialog_57813_Content_21 = {
    Text = "Il Passaggio Sotterraneo."
  },
  AvgDialog_57813_Content_22 = {
    Text = "Ancora e ancora, schivi per un soffio quella coppia di falci. Sbatti contro i muri e cadi dietro gli angoli, eppure non osi mai fermarti, fuggendo per la vita tra respiri pesanti e affannosi."
  },
  AvgDialog_57813_Content_23 = {
    Text = "Davvero il mio miglior studente! Lascia che ti impartisca la più bella lezione pratica di combattimento."
  },
  AvgDialog_57813_Content_24 = {
    Text = "Una risata sfacciata, traboccante di follia, ti insegue come uno spettro. L'intento omicida quasi ti trafigge la schiena mentre ti getti a terra per un soffio ancora una volta, sentendo la falce cozzare contro i tubi metallici dietro di te."
  },
  AvgDialog_57813_Content_25 = {
    Text = "Vapore non identificato fuoriesce dai tubi, riempiendo lo spazio angusto di vapore rovente e oscurando la tua visuale."
  },
  AvgDialog_57813_Content_26 = {
    Text = "Percepisci qualcosa con acutezza e ti nascondi immediatamente in un laboratorio, seguendo la direzione del condotto."
  },
  AvgDialog_57813_Content_27 = {
    Text = "Poco dopo, la porta sigillata del laboratorio si spalanca con fragori violenti, e una voce familiare si avvicina gradualmente."
  },
  AvgDialog_57813_Content_28 = {
    Text = "Poniamo fine al nostro gioco del nascondino. Essere arrivata fin qui ti vale dieci punti in più sul voto finale."
  },
  AvgDialog_57813_Content_29 = {
    Text = "La sua falce raschia il pavimento, emettendo un suono acuto e stridulo."
  },
  AvgDialog_57813_Content_3 = {
    Text = "L'altra \"Doll\" ha violato il contenimento dalla Pozza nera?"
  },
  AvgDialog_57813_Content_30 = {
    Text = "Non avere paura. Una volta che ti avrò uccisa, conserverò il tuo corpo in una bara di ghiaccio, come un ricordo prezioso."
  },
  AvgDialog_57813_Content_31 = {
    Text = "Sarai la mia ricerca più preziosa, la più straordinaria. Abbiamo ancora così tanto tempo insieme..."
  },
  AvgDialog_57813_Content_32 = {
    Text = "Attraverso il fumo denso, scorge un lembo di stoffa accanto al grande macchinario al centro della stanza, e l'angolo delle sue labbra si incurva appena."
  },
  AvgDialog_57813_Content_33 = {
    Text = "Dove sei, piccolo cucciolo? Fammi sentire il tuo guaito."
  },
  AvgDialog_57813_Content_34 = {
    Text = "Lo stridore metallico lacerante svanisce all'improvviso, e il laboratorio sprofonda in un silenzio mortale."
  },
  AvgDialog_57813_Content_35 = {
    Text = "Il tempo quasi si congela durante l'attesa straziante; la sua voce riappare infine, sommessa come un sussurro."
  },
  AvgDialog_57813_Content_36 = {
    Text = "Ti ho trovato."
  },
  AvgDialog_57813_Content_38 = {
    Text = "La falce colpisce il macchinario con forza letale, eppure tutto ciò che crolla è una leggera uniforme scolastica."
  },
  AvgDialog_57813_Content_39 = {
    Text = "Cogliendo l'istante in cui la falce resta incastrata nel dispositivo, premi il pulsante rosso stretto nel pugno. I portelli di caricamento del meccanismo della fornace si aprono rapidamente, rivelando l'infernale scena di metallo fuso al suo interno."
  },
  AvgDialog_57813_Content_4 = {
    Text = "Ricordi quegli occhi colmi di follia che ti fissavano. Spinto dall'intuito, ti prepari immediatamente a spingere la porta e raggrupparti in fretta con gli altri Risvegliati."
  },
  AvgDialog_57813_Content_40 = {
    Text = "Compari alle spalle di \"Doll\" e la spingi con tutta la tua possanza verso la fornace."
  },
  AvgDialog_57813_Content_41 = {
    Text = "Avvolta dalle fiamme,\"Doll\" si volta sorpresa, i suoi occhi ancora velati da un vago senso di apprezzamento e da uno strano, consapevole sorriso."
  },
  AvgDialog_57813_Content_42 = {
    Text = "Abbassando lo sguardo con un brutto presentimento, vedi che l'altra mano della bambola stringe l'ultimo lembo dei tuoi vestiti."
  },
  AvgDialog_57813_Content_43 = {
    Text = "Le tue mani si puntellano istintivamente contro il telaio del macchinario. Il calore residuo ustiona all'istante la pelle dei palmi. Uno sfrigolio accompagna il dolore intenso mentre stringi i denti e resisti alla tremenda forza che ti trascina verso l'interno."
  },
  AvgDialog_57813_Content_44 = {
    Text = "Il profilo del corpo della bambola si sfuma nella luce abbagliante del fuoco, lasciando solo i suoi occhi, più luminosi delle fiamme, ancora fissi su di te."
  },
  AvgDialog_57813_Content_45 = {
    Text = "Docenti e studenti del Mythag arrivano finalmente, allertati dal tuo segnale di soccorso, e ti trascinano via in fretta dalla fornace."
  },
  AvgDialog_57813_Content_46 = {
    Text = "Scrutando attraverso le fiamme, cogli l'ultimo messaggio sulle sue labbra un istante prima che il suo volto si riduca in ceneri."
  },
  AvgDialog_57813_Content_47 = {
    Text = "Ci rivedremo... alla Fine Ultima del mondo."
  },
  AvgDialog_57813_Content_5 = {
    Text = "Nell'istante in cui la tua mano afferra la maniglia, ogni pelo del tuo corpo si rizza in un avvertimento istintivo, e il cuore ti martella nel petto mentre ti abbassi bruscamente."
  },
  AvgDialog_57813_Content_7 = {
    Text = "In quello stesso momento, una raffica tagliente ti sfiora la testa, recidendo qualche ciocca di capelli, e la porta del dormitorio crolla con un boato ritardato e fragoroso."
  },
  AvgDialog_57813_Content_8 = {
    Text = "Peccato. Non mi aspettavo che il cucciolo se ne stesse a terra, ad aspettarmi. Su, ci stringiamo la mano?"
  },
  AvgDialog_57813_Content_9 = {
    Text = "Alzi lo sguardo, e quegli occhi si sovrappongono tra memoria e realtà, osservandoti dall'alto con lo stesso sorriso gioioso di sempre."
  },
  AvgDialog_57890_Content_1 = {
    Text = "Accelererò la fusione del Tawil Oscuro. Come risponderai, Custode?"
  },
  AvgDialog_58289_Content_1 = {
    Text = "Ospite Inatteso"
  },
  AvgDialog_58289_Content_10 = {
    Text = "No. E se fosse già sera?!"
  },
  AvgDialog_58289_Content_11 = {
    Text = "Rotoli giù dal letto in fretta, individuando con precisione la penna, i fogli per le bozze e la gomma, e li infili nella borsa."
  },
  AvgDialog_58289_Content_12 = {
    Text = "Una volta che tutto è pronto, fai un respiro profondo e apri la porta del dormitorio—"
  },
  AvgDialog_58289_Content_13 = {
    Text = "Eh...? Questa non è la scuola che conosco."
  },
  AvgDialog_58289_Content_14 = {Text = "..."},
  AvgDialog_58289_Content_15 = {
    Text = "Capisco, deve essere un sogno! Bene, torno a dormire..."
  },
  AvgDialog_58289_Content_16 = {
    Text = "Ti giri rapidamente, ma la porta del dormitorio—anzi, l'intero edificio—è scomparso."
  },
  AvgDialog_58289_Content_17 = {Text = "..."},
  AvgDialog_58289_Content_18 = {
    Text = "Non ti restava che voltarti di nuovo e guardare la strada davanti a te."
  },
  AvgDialog_58289_Content_19 = {
    Text = "C'è qualcuno—Salve—"
  },
  AvgDialog_58289_Content_2 = {
    Text = "Vari animali dimorano qui, e occasionalmente appaiono alcune entità demoniache."
  },
  AvgDialog_58289_Content_20 = {
    Text = "Buongiorno, buon pomeriggio, buonasera—"
  },
  AvgDialog_58289_Content_21 = {
    Text = "Glug, glug!"
  },
  AvgDialog_58289_Content_22 = {
    Text = "Meno male, finalmente qualcosa mi ha risposto!"
  },
  AvgDialog_58289_Content_23 = {
    Text = "Corri entusiasta verso la fonte del suono, solo per trovare una piccola cassetta postale rossa."
  },
  AvgDialog_58289_Content_24 = {
    Text = "Glug glug, indigestione, aiuto... aiuto..."
  },
  AvgDialog_58289_Content_25 = {
    Text = "<BigShake:Whoa, ugh!!>"
  },
  AvgDialog_58289_Content_26 = {
    Text = "La cassetta postale ebbe un sussulto nervoso, poi sputò fuori una lettera umida."
  },
  AvgDialog_58289_Content_27 = {
    Text = "È per me? Sembra un po' disgustosa..."
  },
  AvgDialog_58289_Content_28 = {
    Text = "È una notte senza vento. Gli edifici sono immersi nella luce rosso scuro della luna, e le porte serrate impediscono a chiunque di entrare."
  },
  AvgDialog_58289_Content_29 = {
    Text = "Sei l'unico essere vivente nel raggio di cento miglia."
  },
  AvgDialog_58289_Content_3 = {
    Text = "Drin-drin—"
  },
  AvgDialog_58289_Content_30 = {
    Text = "Apri la busta"
  },
  AvgDialog_58289_Content_31 = {
    Text = "Cerchi di ignorare la sensazione appiccicosa sulle punte delle dita mentre apri con cura la busta."
  },
  AvgDialog_58289_Content_32 = {
    Text = "Al lontano destinatario:\n\nSi prega di arrivare al Maniero Ferle prima di mezzanotte.\n<Red:Siate puntuali, o subirete le conseguenze (cervello@2 esploso in @3)!>\nIndirizzo del maniero: Riservato.\n\n-▼-"
  },
  AvgDialog_58289_Content_33 = {
    Text = "Il Maniero Ferland? Mi ricordo che è la residenza del Sig. Dexter. Da quando ha iniziato a fare scherzi anche lui...?"
  },
  AvgDialog_58289_Content_34 = {
    Text = "In più, non ho portato l'orologio, quindi non riesco nemmeno a capire che ore sono—"
  },
  AvgDialog_58289_Content_35 = {
    Text = "Tic tac. Tic tac."
  },
  AvgDialog_58289_Content_36 = {
    Text = "Un enorme orologio era apparso nel cielo a un certo punto, con le lancette delle ore e dei minuti ferme esattamente sulle 11."
  },
  AvgDialog_58289_Content_37 = {
    Text = "La sottile lancetta dei secondi continua ad avanzare a un ritmo costante, fredda e meticolosa."
  },
  AvgDialog_58289_Content_38 = {
    Text = "Cosa... sta succedendo..."
  },
  AvgDialog_58289_Content_39 = {
    Text = "Oh, hai ricevuto la stessa lettera che ho ricevuto io?"
  },
  AvgDialog_58289_Content_4 = {
    Text = "Mm... che sonno, non disturbarmi."
  },
  AvgDialog_58289_Content_40 = {
    Text = "Chi va là?!"
  },
  AvgDialog_58289_Content_41 = {
    Text = "Scusi, {Male=Sig.,Female=Sig.na} Custode! Sembrava molto concentrato. L'ho chiamata diverse volte..."
  },
  AvgDialog_58289_Content_42 = {
    Text = "Non ti ricordi di me? Sono Elsa. Abbiamo seguito insieme il corso di Introduzione alla Dissoluzione della Sig.na Doll."
  },
  AvgDialog_58289_Content_43 = {
    Text = "Elsa... Ora ricordo, era quella che prendeva spesso in prestito gli appunti da Ramona."
  },
  AvgDialog_58289_Content_44 = {
    Text = "<Small:Scusa, continuo a essere bocciata ai corsi...>"
  },
  AvgDialog_58289_Content_45 = {
    Text = "Elsa abbassò la testa, stringendo forte il cuscino a forma di cuore in preda alla disperazione."
  },
  AvgDialog_58289_Content_46 = {
    Text = "Non sia triste, Sig.na Elsa. Essere bocciati al corso della Sig.na Doll è un rito di passaggio per la maggior parte degli investigatori."
  },
  AvgDialog_58289_Content_47 = {
    Text = "A proposito, hai detto che hai ricevuto la stessa lettera. Riesci a vederlo anche tu?"
  },
  AvgDialog_58289_Content_48 = {
    Text = "Indichi il gigantesco orologio sospeso sopra la luna piena."
  },
  AvgDialog_58289_Content_49 = {
    Text = "Riesco a vederlo. Ma sono persa, incapace di trovare la direzione giusta, e mi resta meno di un minuto."
  },
  AvgDialog_58289_Content_5 = {Text = "..."},
  AvgDialog_58289_Content_50 = {
    Text = "Strano, il mio conto alla rovescia segna ancora un'ora. Potrebbe essere perché sei entrata in questo mondo prima di me?"
  },
  AvgDialog_58289_Content_51 = {
    Text = "Non lo so... È solo uno scherzo, vero, {Male=Sig.,Female=Sig.na} %player%?"
  },
  AvgDialog_58289_Content_52 = {
    Text = "Non sono mai stata in missioni sul campo, quindi non ho esperienza con eventi anomali..."
  },
  AvgDialog_58289_Content_53 = {
    Text = "Ad essere sinceri, è la prima volta che mi trovo in una situazione del genere anch'io."
  },
  AvgDialog_58289_Content_54 = {
    Text = "Il conto alla rovescia termina tra: <Red:5> secondi"
  },
  AvgDialog_58289_Content_55 = {
    Text = "Prendi delicatamente la mano di Elsa."
  },
  AvgDialog_58289_Content_56 = {
    Text = "Con solo un minuto rimasto, nemmeno una macchina del tempo può aiutare. Ma non avere paura."
  },
  AvgDialog_58289_Content_57 = {
    Text = "Tempo alla fine del conto alla rovescia: <Red:0> secondi"
  },
  AvgDialog_58289_Content_58 = {
    Text = "Non importa cosa accadrà, io proteggerò —"
  },
  AvgDialog_58289_Content_59 = {Text = "La tua..."},
  AvgDialog_58289_Content_6 = {
    Text = "Oh no, oggi c'è l'esame di Introduzione agli Studi sulla Dissoluzione. Che ore sono..."
  },
  AvgDialog_58289_Content_60 = {
    Text = "La testa di Elsa esplose in una massa calda di materia cerebrale. Il liquido viscoso ti schizzò sul volto, saturando l'aria con l'odore metallico del sangue."
  },
  AvgDialog_58289_Content_61 = {
    Text = "%player%@2, salva @3..."
  },
  AvgDialog_58289_Content_62 = {
    Text = "Fanghiglia scura continua a fuoriuscire dal collo spezzato, formando rapidamente un altro volto pallido e sconosciuto."
  },
  AvgDialog_58289_Content_63 = {
    Text = "<Change>Salvami, salvami..."
  },
  AvgDialog_58289_Content_64 = {
    Text = "Sig.na Elsa?! Cosa... sta succedendo..."
  },
  AvgDialog_58289_Content_66 = {
    Text = "La lama della bestia fendette l'aria, tagliando \"Elsa\" a metà. Melma-D nera sgorgò come sangue."
  },
  AvgDialog_58289_Content_67 = {
    Text = "È inutile. Ha perso la ragione molto tempo fa."
  },
  AvgDialog_58289_Content_68 = {
    Text = "Sig. Ryker?!"
  },
  AvgDialog_58289_Content_69 = {
    Text = "Ryker ritrasse i suoi artigli bestiali e si avvicinò a te con passo leggero."
  },
  AvgDialog_58289_Content_7 = {
    Text = "6:37, è ancora presto..."
  },
  AvgDialog_58289_Content_70 = {
    Text = "Perché hai quell'espressione in lacrime? Non preoccuparti, questo posto è probabilmente il Dominio di qualcuno."
  },
  AvgDialog_58289_Content_71 = {
    Text = "Dominio...?"
  },
  AvgDialog_58289_Content_72 = {
    Text = "Mm. In altre parole, questa Elsa molto probabilmente è ancora viva nella realtà."
  },
  AvgDialog_58289_Content_73 = {
    Text = "Come ci si aspetta dal detective, l'hai notato subito. Qual è il tuo ragionamento?"
  },
  AvgDialog_58289_Content_74 = {
    Text = "Fu in una notte come questa che incontrai Elsa per la prima volta."
  },
  AvgDialog_58289_Content_75 = {
    Text = "A quel tempo, era inseguita da un branco di mostri della Dissoluzione. Ero appena uscito dalla taverna, le indicai una via e uccisi i mostri che la inseguivano."
  },
  AvgDialog_58289_Content_76 = {
    Text = "Ci siamo incontrati di nuovo poco fa. Stessa ora, stesso posto, ma le ho dato le indicazioni sbagliate, facendola ferire. Quindi questo significa—"
  },
  AvgDialog_58289_Content_77 = {
    Text = "In altre parole?"
  },
  AvgDialog_58289_Content_78 = {
    Text = "La mia buona sorte è svanita! Questa è una cosa che non può assolutamente accadere, quindi deduco logicamente che questa non è la realtà."
  },
  AvgDialog_58289_Content_79 = {
    Text = "Oppure potresti darmi due schiaffi per verificare se questo è un sogno? Io me ne sono già dati parecchi poco fa, ma non è servito a nulla."
  },
  AvgDialog_58289_Content_8 = {
    Text = "Hai armeggiato a tentoni e premuto il pulsante della sveglia, ripiombando in un sonno profondo."
  },
  AvgDialog_58289_Content_80 = {Text = "..."},
  AvgDialog_58289_Content_81 = {
    Text = "Tutto quello che so è che non voglio che la mia testa esploda, né nel Dominio né nella realtà."
  },
  AvgDialog_58289_Content_82 = {
    Text = "Hai disperatamente bisogno del mio aiuto! Lungo la strada, ho incontrato parecchi ritardatari come Elsa. Meglio prendere la via aerea."
  },
  AvgDialog_58289_Content_83 = {
    Text = "Ryker parlò e indicò il tetto di un edificio vicino."
  },
  AvgDialog_58289_Content_84 = {
    Text = "Vuoi dire volare da un tetto all'altro?"
  },
  AvgDialog_58289_Content_85 = {
    Text = "Scusa, sono solo un Custode ordinario e non posso unirmi alle tue avventure acrobatiche—"
  },
  AvgDialog_58289_Content_86 = {
    Text = "Un istante dopo, Ryker ti lanciò sulla sua schiena e spiccò un balzo in aria."
  },
  AvgDialog_58289_Content_87 = {
    Text = "Tenetevi forte, {Male=Signor,Female=Signorina} %player%!"
  },
  AvgDialog_58289_Content_88 = {
    Text = "<Shake:Wahhh!!>"
  },
  AvgDialog_58289_Content_89 = {
    Text = "Ti aggrappi al colletto di Ryker per la paura. Il detective accovacciato balza agilmente da un tetto all'altro, grande o piccolo, zigzagando tra gli edifici fittamente ammassati di Londinium."
  },
  AvgDialog_58289_Content_9 = {Text = "..."},
  AvgDialog_58289_Content_90 = {
    Text = "Un uomo e un lupo si lanciano all'assalto sotto la luna silenziosa."
  },
  AvgDialog_58289_Content_91 = {
    Text = "Senti solo il suono puro del vento. Ti abbassi e ti stringi al soffice pelo sotto di te."
  },
  AvgDialog_58289_Content_92 = {
    Text = "Com'è stato? Ti sei divertito?"
  },
  AvgDialog_58289_Content_93 = {
    Text = "Non mi sarei mai aspettato che avessi questo tipo di abilità...<Big:Rallenta, richiesta di rallentare!>"
  },
  AvgDialog_58289_Content_94 = {
    Text = "Ryker rise di gusto, il petto che vibrava come se ogni cellula del suo corpo stesse esultando e saltando di gioia."
  },
  AvgDialog_58289_Content_95 = {
    Text = "Ecco cosa dovrebbe fare un lupo! Sto solo tornando alle mie vecchie abitudini, capito?"
  },
  AvgDialog_58289_Content_96 = {
    Text = "Ti ho detto, <BigShake:Rallenta!!>"
  },
  AvgDialog_58289_Content_97 = {
    Text = "Piano, non scompigliarmi il pelo!"
  },
  AvgDialog_58290_Content_1 = {
    Text = "Casa dei Fantasmi"
  },
  AvgDialog_58290_Content_10 = {
    Text = "La partita al tavolo è nel pieno del suo svolgimento, e nessuno presta attenzione alla tua piccola domanda."
  },
  AvgDialog_58290_Content_11 = {
    Text = "<BigShake:Scusate se interrompo il vostro divertimento!>"
  },
  AvgDialog_58290_Content_12 = {
    Text = "Qualcuno si ricorda che siamo intrappolati nel Dominio di una maledetta divinità folle?"
  },
  AvgDialog_58290_Content_13 = {
    Text = "Correzione: una divinità folle e smemorata. Quello che dobbiamo fare ora è conservare le energie finché non si ricorderà la domanda da porre, giusto?"
  },
  AvgDialog_58290_Content_14 = {
    Text = "Scala reale, fantastico!"
  },
  AvgDialog_58290_Content_15 = {Text = "..."},
  AvgDialog_58290_Content_16 = {
    Text = "Va bene, farò un'indagine nei dintorni."
  },
  AvgDialog_58290_Content_17 = {
    Text = [[
Villa Ferland
Studio al primo piano]]
  },
  AvgDialog_58290_Content_18 = {
    Text = "Mm... Tutti i libri di questo tizio sono edizioni rilegate di lusso che non sono mai state aperte. Come diavolo è diventato professore al Mythag?"
  },
  AvgDialog_58290_Content_19 = {
    Text = "Eh, cos'è questo?"
  },
  AvgDialog_58290_Content_2 = {
    Text = [[
Villa Ferland
Due ore dopo]]
  },
  AvgDialog_58290_Content_20 = {
    Text = "In un angolo trascurato, una bara nera attira la tua attenzione."
  },
  AvgDialog_58290_Content_21 = {
    Text = "Motivi complessi e simboli sono dipinti in oro sui lati della bara, con una densa nebbia nera che filtra debolmente dalla fessura centrale."
  },
  AvgDialog_58290_Content_22 = {
    Text = "Mm—non riesco ad aprirla in nessun modo."
  },
  AvgDialog_58290_Content_23 = {
    Text = "Sembra qualcosa nello stile di Remouahe. Dove l'ha trovato Dexter?"
  },
  AvgDialog_58290_Content_24 = {
    Text = "Incuriosito, hai allungato la mano e sfiorato delicatamente i motivi dorati sul lato della bara, ma poi—"
  },
  AvgDialog_58290_Content_25 = {
    Text = "Apophis, il Faraone Nero, è Karnahk.\nTu lo onori; egli vive, egli vive, egli vive."
  },
  AvgDialog_58290_Content_26 = {
    Text = "Apophis, non è morto, non è morto, Apophis."
  },
  AvgDialog_58290_Content_27 = {Text = "..."},
  AvgDialog_58290_Content_28 = {
    Text = "Che succede, Nobile? Sei così pallido in viso."
  },
  AvgDialog_58290_Content_29 = {
    Text = "Scusate, ho una questione urgente da sbrigare. Torno subito."
  },
  AvgDialog_58290_Content_3 = {
    Text = "Sembra che la Dea Fortuna non vi abbia sorriso stasera, signor Ryker."
  },
  AvgDialog_58290_Content_30 = {
    Text = "Un altro che se n'è andato, sembra che stia per andare in pari... Dove sono l'assistente robotica e la maga?"
  },
  AvgDialog_58290_Content_31 = {
    Text = "Mm, ho appena visto la signorina Erica salire al piano di sopra. Quanto alla signorina Casiah, nessuno l'ha più vista da quando è tornata."
  },
  AvgDialog_58290_Content_32 = {
    Text = "Sono un po' stanca anch'io. Voglio prendere una boccata d'aria fresca."
  },
  AvgDialog_58290_Content_33 = {
    Text = "Ma fuori nevica copiosamente. Vi prenderete un malanno, Lady Sorel!"
  },
  AvgDialog_58290_Content_34 = {
    Text = "Questo non è il mondo reale. Non c'è bisogno di attenersi alle convenzioni. E poi, è bello prendersi un momento per ammirare il paesaggio innevato, non trovi?"
  },
  AvgDialog_58290_Content_35 = {
    Text = "Sorel se ne andò con passi aggraziati, e la sala un tempo vivace divenne improvvisamente silenziosa."
  },
  AvgDialog_58290_Content_36 = {
    Text = "<SmallShake:Boss, la partita a carte era solo una copertura, vero? Lo sapevo che avevi un piano!>"
  },
  AvgDialog_58290_Content_37 = {Text = "Ehm..."},
  AvgDialog_58290_Content_38 = {
    Text = "Esatto! La reazione del signor Dexter era strana poco fa. Andiamo a controllare la sua camera da letto."
  },
  AvgDialog_58290_Content_39 = {
    Text = "Wow! Il gioco investigativo è finalmente iniziato!"
  },
  AvgDialog_58290_Content_4 = {
    Text = "Il piatto ha superato i 10.000 Zanne di Leo. Volete rilanciare?"
  },
  AvgDialog_58290_Content_40 = {
    Text = [[
Villa Ferland
Scalinata]]
  },
  AvgDialog_58290_Content_41 = {
    Text = "Boss, sei sicuro che il signor Dexter sia nella sua camera? Mi sembrava di averlo visto dirigersi verso lo studio."
  },
  AvgDialog_58290_Content_42 = {
    Text = "Mm... È difficile spiegare il mio processo di ragionamento. Consideralo una strana intuizione."
  },
  AvgDialog_58290_Content_43 = {
    Text = "Capisco! Questa dev'essere la leggendaria intuizione di un famoso detective!!"
  },
  AvgDialog_58290_Content_44 = {
    Text = "Non preoccuparti, boss. Non metterò in dubbio una sola parola."
  },
  AvgDialog_58290_Content_45 = {
    Text = "Hannah si batte il petto, poi tira fuori la sua lente d'ingrandimento per ispezionare i dintorni."
  },
  AvgDialog_58290_Content_46 = {
    Text = "L'Operazione 215 ha ufficialmente inizio! Per prima cosa, la scalinata intagliata in ebano si presenta davanti a noi—modesta eppure lussuosa, distaccata dalle preoccupazioni mondane..."
  },
  AvgDialog_58290_Content_47 = {
    Text = "Stai pensando di cambiare carriera, signorina Hannah? All'improvviso, sento che saresti perfetta per vendere pubblicità alla <Blue:Heinz Co.>"
  },
  AvgDialog_58290_Content_48 = {
    Text = "Per favore, non interrompere le indagini altrui! Infine, c'è la finestra intagliata accanto alle scale—"
  },
  AvgDialog_58290_Content_49 = {Text = "..."},
  AvgDialog_58290_Content_5 = {Text = "...Certo."},
  AvgDialog_58290_Content_50 = {
    Text = "Non lontano da dove puntava la lente, una figura oscura guizzò oltre la finestra."
  },
  AvgDialog_58290_Content_51 = {
    Text = "Aah! Un-un-un fantasma!!"
  },
  AvgDialog_58290_Content_52 = {
    Text = "Parli in modo comprensibile, signorina Hannah."
  },
  AvgDialog_58290_Content_53 = {
    Text = "<Shake:Il fantasma del signor Dexter! Proprio sulla scalinata! Fluttuava su, su, sempre più su!>"
  },
  AvgDialog_58290_Content_54 = {
    Text = "Ryker si fece avanti e aprì la finestra. Il vento ululava e i fiocchi di neve turbinavano senza meta, cadendo in tutte le direzioni."
  },
  AvgDialog_58290_Content_55 = {
    Text = "Alzò lo sguardo: la luce calda della stanza al secondo piano proiettava un tenue bagliore arancione sui fiocchi di neve."
  },
  AvgDialog_58290_Content_56 = {
    Text = "Interessante, più di una stanza ha le luci accese... andiamo a dare un'occhiata."
  },
  AvgDialog_58290_Content_57 = {
    Text = [[
Villa Ferland
Ccorridoio del Secondo Piano]]
  },
  AvgDialog_58290_Content_58 = {
    Text = "Hmm, la porta è chiusa a chiave."
  },
  AvgDialog_58290_Content_59 = {
    Text = "Signor Dexter, è lì dentro? Si sente meglio?"
  },
  AvgDialog_58290_Content_6 = {
    Text = "Lieto di sentirlo, signor Ryker. Una volta usciti dal Dominio, farò mandare dal maggiordomo tutti i conti."
  },
  AvgDialog_58290_Content_60 = {
    Text = "La stanza era avvolta in un silenzio di tomba. Dopo un po', la voce soffocata di Dexter giunse dall'interno."
  },
  AvgDialog_58290_Content_61 = {
    Text = "Scusate, non mi sento bene. Posso fare una breve pausa?"
  },
  AvgDialog_58290_Content_62 = {
    Text = "Hai indovinato. È davvero lì dentro. Qual è il piano adesso?"
  },
  AvgDialog_58290_Content_63 = {
    Text = "Ritiriamoci. Questa è la dimora di un nobile signore; dovremmo osservare un minimo di etichetta."
  },
  AvgDialog_58290_Content_64 = {
    Text = "Ryker parlò mentre faceva qualche passo indietro."
  },
  AvgDialog_58290_Content_65 = {
    Text = "Poi improvvisamente accelerò e balzò in avanti, sferrando un calcio alla porta—"
  },
  AvgDialog_58290_Content_66 = {Text = "Splash!!"},
  AvgDialog_58290_Content_67 = {
    Text = "La robusta porta di quercia fu sfondata con un calcio, lasciando un grosso buco. Ryker infilò la mano, trovò facilmente la maniglia e aprì la porta con calma."
  },
  AvgDialog_58290_Content_68 = {
    Text = "Prima le signore, prego—"
  },
  AvgDialog_58290_Content_69 = {Text = "..."},
  AvgDialog_58290_Content_7 = {
    Text = "Mandate anche il nostro conto a lui, eheheh~"
  },
  AvgDialog_58290_Content_70 = {
    Text = "<Shake:Ma che fine hanno fatto l'etichetta e le buone maniere?>"
  },
  AvgDialog_58290_Content_71 = {
    Text = "Scusa, le mie limitate buone maniere ed etichetta si applicano solo agli esseri umani. Apri bene gli occhi, cos'è quello?"
  },
  AvgDialog_58290_Content_72 = {
    Text = "Seguendo lo sguardo di Ryker, Hannah vede un grammofono nero accanto alla scrivania. Il disco nero sta girando lentamente."
  },
  AvgDialog_58290_Content_73 = {
    Text = "Scusate, non mi sento bene. Posso fare una breve pausa?"
  },
  AvgDialog_58290_Content_74 = {
    Text = "Scusate @2... Non mi sento bene... Devo riposare..."
  },
  AvgDialog_58290_Content_75 = {
    Text = "Riposo riposo@2 riposo..."
  },
  AvgDialog_58290_Content_76 = {
    Text = "Per favore, uscite tutti il prima possibile e non disturbate il riposo del Signor Dexter."
  },
  AvgDialog_58290_Content_77 = {
    Text = "<Shake:Whoa!! Quando hai...>"
  },
  AvgDialog_58290_Content_78 = {
    Text = "Signorina Erica, anche se quel tizio ti ha trasformata in un'idiota, devo comunque ricordarti..."
  },
  AvgDialog_58290_Content_79 = {
    Text = "Non si trova nemmeno un singolo capello di Dexter qui."
  },
  AvgDialog_58290_Content_8 = {
    Text = "Dannazione! Quel tizio, N, deve avermi fatto qualcosa..."
  },
  AvgDialog_58290_Content_80 = {
    Text = "Per favore, uscite tutti il prima possibile, e non..."
  },
  AvgDialog_58290_Content_81 = {
    Text = "Lasciala perdere per ora. Cosa succede con questo grammofono?"
  },
  AvgDialog_58290_Content_82 = {
    Text = "Semplice. Qualcuno ha fabbricato un alibi, ma io l'ho smascherato immediatamente."
  },
  AvgDialog_58290_Content_83 = {
    Text = "Capisco. Ho capito! Nei romanzi gialli, dove c'è un alibi, c'è un omicidio—"
  },
  AvgDialog_58290_Content_84 = {Text = "Bang!"},
  AvgDialog_58290_Content_85 = {
    Text = "Uno sparo improvviso squarcia la notte silenziosa."
  },
  AvgDialog_58290_Content_86 = {
    Text = "<Shake:Quello era... dal piano di sotto...>"
  },
  AvgDialog_58290_Content_87 = {
    Text = "Andate a controllare. Il gioco... potrebbe essere già iniziato."
  },
  AvgDialog_58290_Content_9 = {Text = "Scusate..."},
  AvgDialog_58291_Content_1 = {
    Text = "Nessun Sopravvissuto"
  },
  AvgDialog_58291_Content_10 = {
    Text = [[
Villa Ferland
23:45]]
  },
  AvgDialog_58291_Content_100 = {
    Text = "Va bene, va bene, come dici tu—"
  },
  AvgDialog_58291_Content_101 = {
    Text = "Bene, Erica vi intratterrà d'ora in poi. Ho ancora 1124 creature in attesa di firmare contratti demoniaci con me."
  },
  AvgDialog_58291_Content_102 = {
    Text = "Ricordate…"
  },
  AvgDialog_58291_Content_103 = {
    Text = "<Red:Il cattivo si nasconde tra noi. Non fidarti di nessuno.>"
  },
  AvgDialog_58291_Content_104 = {Text = "?!"},
  AvgDialog_58291_Content_105 = {Text = "..."},
  AvgDialog_58291_Content_106 = {
    Text = "Cosa guardate? Non ho ancora avuto modo di fare nulla!"
  },
  AvgDialog_58291_Content_107 = {
    Text = "Oh? Racconta, cosa avevi intenzione di fare?"
  },
  AvgDialog_58291_Content_108 = {
    Text = "Eccellente, ragazzi! Continuate così con lo spirito del dibattito. Non lasciate che la mia presenza vi freni!"
  },
  AvgDialog_58291_Content_109 = {
    Text = "La nostra prima regola di condotta: caos! Seconda regola: caos! Terza regola..."
  },
  AvgDialog_58291_Content_11 = {
    Text = "La pesante porta di legno viene spalancata. Ryker entra nella sala a braccia aperte, con un entusiasmo esagerato."
  },
  AvgDialog_58291_Content_110 = {
    Text = "Fammi indovinare, ancora caos?"
  },
  AvgDialog_58291_Content_111 = {
    Text = "Sbagliato! È <Red:Caos Infinito>!"
  },
  AvgDialog_58291_Content_112 = {Text = "..."},
  AvgDialog_58291_Content_113 = {
    Text = "Quindi, divertitevi tutti~"
  },
  AvgDialog_58291_Content_114 = {
    Text = "Dopo aver parlato, N svanì in una densa nebbia nera, lasciando tutti a guardarsi l'un l'altro con sconcerto."
  },
  AvgDialog_58291_Content_115 = {
    Text = "%player%, da dove è saltato fuori questo tipo fastidioso? Sembra che tu Lo conosca bene."
  },
  AvgDialog_58291_Content_116 = {
    Text = "Hai esitato, chiedendoti se raccontare a Hannah tutto ciò che sapevi. Ma presto ti sei reso conto che non era necessario."
  },
  AvgDialog_58291_Content_117 = {
    Text = "Non sai nulla nemmeno tu riguardo a N."
  },
  AvgDialog_58291_Content_118 = {
    Text = "Scusa, non so molto nemmeno io su questa persona. Dopo aver cambiato aspetto, la sua personalità è diventata più..."
  },
  AvgDialog_58291_Content_119 = {
    Text = "Volevi dire \"vivace\", ma hai ingoiato la parola."
  },
  AvgDialog_58291_Content_12 = {
    Text = "Dexter, vecchio amico! Sono passati solo pochi giorni e ci inviti già nella tua tenuta per una rimpatriata?"
  },
  AvgDialog_58291_Content_120 = {
    Text = "Ancora più fastidioso."
  },
  AvgDialog_58291_Content_121 = {
    Text = "Se non sbaglio, dobbiamo risolvere l'enigma per scoprire <Yellow:la verità finale>, giusto?"
  },
  AvgDialog_58291_Content_122 = {
    Text = "Mm... Esatto."
  },
  AvgDialog_58291_Content_123 = {
    Text = "Un piccolo problema. Questa persona sembra essersi dimenticata di menzionare l'argomento."
  },
  AvgDialog_58291_Content_124 = {
    Text = "In effetti, uno stato di caos senza fine."
  },
  AvgDialog_58291_Content_125 = {
    Text = "Hai fissato il ponte completamente distrutto davanti a te. La valle buia come la pece sembrava un abisso senza fondo, tagliandoti completamente fuori dall'isola lontana."
  },
  AvgDialog_58291_Content_126 = {
    Text = "Signor Dexter, è sicuro che questo sia l'unico sentiero che porta al mondo esterno?"
  },
  AvgDialog_58291_Content_127 = {
    Text = "Dexter alza le spalle con aria impotente."
  },
  AvgDialog_58291_Content_128 = {
    Text = "Ho scelto questo posto perché è isolato, proteggendomi da molte interazioni sociali inutili e attenzioni indesiderate."
  },
  AvgDialog_58291_Content_129 = {
    Text = "Le cose hanno preso una piega inaspettata."
  },
  AvgDialog_58291_Content_13 = {
    Text = "Naturalmente, devo farti notare che questo metodo di invito è alquanto estremo."
  },
  AvgDialog_58291_Content_130 = {
    Text = "La neve cadeva fitta e veloce, coprendo rapidamente il ponte di legno danneggiato."
  },
  AvgDialog_58291_Content_131 = {
    Text = "Etciù! Bufere di neve, ville isolate in montagna e persone misteriosamente riunite insieme..."
  },
  AvgDialog_58291_Content_132 = {
    Text = "Ho un brutto presentimento."
  },
  AvgDialog_58291_Content_14 = {
    Text = "<Small:Ehi, e l'imboscata?!>"
  },
  AvgDialog_58291_Content_15 = {
    Text = "So cosa stai insinuando — non sono stato io."
  },
  AvgDialog_58291_Content_16 = {
    Text = "Dexter sedeva in fondo al lungo tavolo, arruffandosi i capelli disordinati con impazienza."
  },
  AvgDialog_58291_Content_17 = {
    Text = "<Gray:Ramona ha detto che il Signor Dexter diventa estremamente irritabile quando il suo sonno viene interrotto...>"
  },
  AvgDialog_58291_Content_18 = {
    Text = "Stavo dormendo profondamente a casa quando all'improvviso un gruppo di persone ha bussato alla porta, e tutta la servitù è svanita."
  },
  AvgDialog_58291_Content_19 = {
    Text = "Ancora non capisco cosa sia successo."
  },
  AvgDialog_58291_Content_2 = {
    Text = [[
Villa Ferland
23:30]]
  },
  AvgDialog_58291_Content_20 = {
    Text = "Un gruppo di persone...?"
  },
  AvgDialog_58291_Content_21 = {Text = "Snap!"},
  AvgDialog_58291_Content_22 = {
    Text = "Un lampo bianco, e la stanza tornò immediatamente al suo silenzio originale."
  },
  AvgDialog_58291_Content_23 = {
    Text = "Mm, ancora non riesco a catturare nulla. Questo posto è davvero strano..."
  },
  AvgDialog_58291_Content_24 = {
    Text = "Hannah?! Cosa ci fai qui?"
  },
  AvgDialog_58291_Content_25 = {
    Text = "Hmph, il titolo di Vicepresidente della Società di Calcolo Deduttivo non è solo di facciata! Sono la migliore a trovare percorsi."
  },
  AvgDialog_58291_Content_26 = {
    Text = "Buonasera, {Male=Sig.,Female=Sig.na} %player%, buonasera, capo!"
  },
  AvgDialog_58291_Content_27 = {Text = "Mm-hmm."},
  AvgDialog_58291_Content_28 = {
    Text = "Capo...? Non mi aspettavo che voi due vi conosceste."
  },
  AvgDialog_58291_Content_29 = {
    Text = "Il Signor Ryker è un detective rinomato nel Distretto Est. Quando facciamo squadra, i criminali fanno di tutto per evitarci!"
  },
  AvgDialog_58291_Content_3 = {
    Text = "Yoho! Atterraggio riuscito~"
  },
  AvgDialog_58291_Content_30 = {
    Text = "Coff, coff. Frena i tuoi istinti giornalistici; questo non è un servizio di cronaca."
  },
  AvgDialog_58291_Content_31 = {
    Text = "Ryker ti fece un gesto di rassegnazione alzando le spalle."
  },
  AvgDialog_58291_Content_32 = {
    Text = "A volte le chiedo di fare delle commissioni per me, e in cambio, è riuscita a estorcermi parecchie informazioni. È un accordo vantaggioso per entrambi."
  },
  AvgDialog_58291_Content_33 = {
    Text = "A proposito di beneficio reciproco, non c'era un'altra persona che aveva stretti legami con i Mythag?"
  },
  AvgDialog_58291_Content_34 = {
    Text = "Seguendo lo sguardo di Ryker, noti una donna riccamente vestita che tiene un calice di vino, sorridendoti dall'ombra."
  },
  AvgDialog_58291_Content_35 = {
    Text = "Ci rivediamo, {Male=Sig.,Female=Sig.na} Custode."
  },
  AvgDialog_58291_Content_36 = {
    Text = "Lady Sorel?! Voi, come avete potuto anche..."
  },
  AvgDialog_58291_Content_37 = {
    Text = "Peccato, speravo che ci saremmo rincontrati in circostanze più formali."
  },
  AvgDialog_58291_Content_38 = {
    Text = "Ma qui c'è solo una villa isolata e un calice vuoto. Cosa dovrei fare per passare il tempo?"
  },
  AvgDialog_58291_Content_39 = {
    Text = "Ma certo, riempi i bicchieri e beviamo tutta la notte~!"
  },
  AvgDialog_58291_Content_4 = {
    Text = "Sei sicuro che Dexter viva in questa catapecchia? È andato in bancarotta?"
  },
  AvgDialog_58291_Content_40 = {
    Text = "Con una voce femminile allegra, il calice di vino nella mano di Sorel si riempì magicamente."
  },
  AvgDialog_58291_Content_41 = {
    Text = "Sorprendente, sa di Chardonnay... Com'è possibile?"
  },
  AvgDialog_58291_Content_42 = {
    Text = "Eheh, e questo cos'è? Guardate un po'—"
  },
  AvgDialog_58291_Content_43 = {
    Text = "Casiah batte delicatamente il bordo del calice con il suo bastone, facendo sbocciare istantaneamente rose rosse fresche, tremolanti nella luce."
  },
  AvgDialog_58291_Content_44 = {
    Text = "Colse il fiore più delicato e vivace e lo infilò delicatamente dietro l'orecchio di Sorel."
  },
  AvgDialog_58291_Content_45 = {
    Text = "La rosa più splendente, per la più bella bellezza di Londinium."
  },
  AvgDialog_58291_Content_46 = {
    Text = "Meraviglioso, Signorina Maga! Le interesserebbe una posizione a corte? Devo raccomandarla a Sua Maestà la Regina."
  },
  AvgDialog_58291_Content_47 = {
    Text = "Se il prezzo è giusto, tutto si può organizzare..."
  },
  AvgDialog_58291_Content_48 = {
    Text = "Hmm, ma non sono il nostro {Male=Sig.,Female=Sig.na} Custode e il Sig. Detective?"
  },
  AvgDialog_58291_Content_49 = {
    Text = "Casiah sembra sorpresa, come se ti avesse appena notato."
  },
  AvgDialog_58291_Content_5 = {
    Text = "Scusa, questa è la più discreta delle sue oltre cinquanta proprietà."
  },
  AvgDialog_58291_Content_50 = {
    Text = "Da quando ci siamo separati ad Aram, ho pensato a te ogni giorno."
  },
  AvgDialog_58291_Content_51 = {Text = "..."},
  AvgDialog_58291_Content_52 = {Text = "..."},
  AvgDialog_58291_Content_53 = {
    Text = "Aspetta! Non ho ucciso William. Casiah è solo una povera lavoratrice. Non vorrai causare un massacro nella casa di questo gentiluomo, vero?"
  },
  AvgDialog_58291_Content_54 = {
    Text = "Nessun problema, non mi dispiace fare una bella chiacchierata fuori."
  },
  AvgDialog_58291_Content_55 = {
    Text = "Sss... Lasciami chiarire: conosco questo terreno come le mie tasche."
  },
  AvgDialog_58291_Content_56 = {
    Text = "Se non puoi vincere, scappa..."
  },
  AvgDialog_58291_Content_57 = {
    Text = "Dong— dong—"
  },
  AvgDialog_58291_Content_58 = {
    Text = "Un orologio gigante apparve improvvisamente sopra tutti, con le lancette che indicavano la mezzanotte."
  },
  AvgDialog_58291_Content_59 = {
    Text = "Signore e signori, buonasera! Benvenuti nel mio paradiso!"
  },
  AvgDialog_58291_Content_6 = {
    Text = "Hmm... mi è appena venuta un'idea geniale—"
  },
  AvgDialog_58291_Content_60 = {
    Text = "Aah! Perché questo bambino non ha un volto?!"
  },
  AvgDialog_58291_Content_61 = {
    Text = "Questo abbigliamento e questa sensazione familiare... Potrebbe essere..."
  },
  AvgDialog_58291_Content_62 = {
    Text = "Congratulazioni a tutti per aver usato la vostra intelligenza e spirito di cooperazione per superare con successo la prima sfida che ho preparato."
  },
  AvgDialog_58291_Content_63 = {
    Text = "Il riscaldamento è finito; ora passiamo al tema principale—"
  },
  AvgDialog_58291_Content_64 = {Text = "Bang!"},
  AvgDialog_58291_Content_65 = {
    Text = "Il proiettile trafisse il volto della figura misteriosa, lasciando un grande buco al centro."
  },
  AvgDialog_58291_Content_66 = {
    Text = "Scusa, il colpo è partito per sbaglio. Ti stai divertendo a giocare a fare le casette, N?"
  },
  AvgDialog_58291_Content_67 = {
    Text = "Quindi è Lui..."
  },
  AvgDialog_58291_Content_68 = {
    Text = "La nebbia nera residua sul volto di N continuava a contorcersi e allungarsi, colmando rapidamente il vuoto."
  },
  AvgDialog_58291_Content_69 = {
    Text = "Che noia, mi avete riconosciuto così in fretta."
  },
  AvgDialog_58291_Content_7 = {
    Text = "Tanto per essere chiari, non pensare nemmeno di approfittarti del Signor Dexter. Non ha alcun interesse per qualsiasi forma di gioco d'azzardo, investimenti speculativi o imprese rischiose."
  },
  AvgDialog_58291_Content_70 = {
    Text = "Il Signor Ryker era piuttosto entusiasta durante l'assalto sotto la luna. Ti è piaciuto il gioco di ruolo che ho creato su misura per te?"
  },
  AvgDialog_58291_Content_71 = {
    Text = "Hah... Piuttosto ordinario. Questo è il tuo Dominio?"
  },
  AvgDialog_58291_Content_72 = {
    Text = "Certo. Se volete uscire, restate in questa casa e risolvete gli enigmi che ho preparato."
  },
  AvgDialog_58291_Content_73 = {
    Text = "Ehi, questa è casa mia. A nessuno importa della mia opinione?"
  },
  AvgDialog_58291_Content_74 = {
    Text = "<Italic:Shhhh... Shhhhh...>"
  },
  AvgDialog_58291_Content_75 = {Text = "BOOM!!"},
  AvgDialog_58291_Content_76 = {
    Text = "Perfetto, il mio piccolo assistente ha segato l'unico ponte verso il mondo esterno."
  },
  AvgDialog_58291_Content_77 = {
    Text = "Ora non potete andare da nessuna parte!"
  },
  AvgDialog_58291_Content_78 = {
    Text = "Cosa?! Sbrigatevi ad andare a controllare—"
  },
  AvgDialog_58291_Content_79 = {
    Text = "Tutto intorno è silenzio. Sei in piedi sul bordo del ponte spezzato sulla scogliera, senza parole."
  },
  AvgDialog_58291_Content_8 = {
    Text = "Il detective, bruscamente interrotto, ritirò a malincuore la mano e annuì ostinatamente verso la villa in lontananza."
  },
  AvgDialog_58291_Content_80 = {
    Text = "A un certo punto, una fitta neve iniziò a cadere dal cielo, vorticando e fluttuando nell'aria."
  },
  AvgDialog_58291_Content_81 = {
    Text = "Stringesti la chiave d'argento opaco al petto. Da quando hai messo piede su questa terra, la tua connessione con essa si è spezzata"
  },
  AvgDialog_58291_Content_82 = {
    Text = "È inutile. Ho reciso la tua connessione con @2. Ora non possiedi alcuna abilità speciale oltre a quelle della gente comune."
  },
  AvgDialog_58291_Content_83 = {
    Text = "Quindi eri tu fin dall'inizio..."
  },
  AvgDialog_58291_Content_84 = {
    Text = "Non preoccuparti, anche se ti fai uscire gli occhi dalle orbite, non servirà a nulla."
  },
  AvgDialog_58291_Content_85 = {
    Text = "I veri eroi risolvono i problemi come la gente comune—ho ragione, Erica?"
  },
  AvgDialog_58291_Content_86 = {Text = "Erica...?"},
  AvgDialog_58291_Content_87 = {
    Text = "Passi meccanici risuonano dall'angolo."
  },
  AvgDialog_58291_Content_88 = {
    Text = "Erica brandisce un'enorme motosega, estendendo rapidamente il braccio. Il cavo di collegamento del suo arto protesico si allunga a una distanza estrema, arrivando persino a segare il ponte davanti."
  },
  AvgDialog_58291_Content_89 = {Text = "...?"},
  AvgDialog_58291_Content_9 = {
    Text = "Coff, coff... Ma cosa stai pensando? Intendevo dire che dovremmo entrare e preparare un'imboscata per raccogliere informazioni..."
  },
  AvgDialog_58291_Content_90 = {
    Text = "Il braccio meccanico di questo tizio è davvero interessante. Devo trovare un modo per ottenerlo..."
  },
  AvgDialog_58291_Content_91 = {
    Text = "Erica spense la motosega, camminò dietro N e si inchinò persino rispettosamente."
  },
  AvgDialog_58291_Content_92 = {
    Text = "Rapporto, Maestro. L'unico passaggio che collega Ferrand al mondo esterno è stato distrutto. Tempo totale trascorso: 5 minuti e 40 secondi. Energia consumata..."
  },
  AvgDialog_58291_Content_93 = {
    Text = "Tu... Cosa hai fatto alla signorina Erica?!"
  },
  AvgDialog_58291_Content_94 = {
    Text = "N saltò con leggerezza sulla spalla di Erica, accavallando le gambe con disinvoltura."
  },
  AvgDialog_58291_Content_95 = {
    Text = "Non preoccuparti, ho solo leggermente influenzato i suoi pensieri con il mio carisma. Lasciate che vi presenti la mia nuova assistente, Erica."
  },
  AvgDialog_58291_Content_96 = {
    Text = "Erica, su, dai la buonasera a tutti."
  },
  AvgDialog_58291_Content_97 = {
    Text = "Buonasera. Per il momento, Erica sarà responsabile di supervisionare e prendersi cura di tutti. Seguitemi alla villa, per favore."
  },
  AvgDialog_58291_Content_98 = {
    Text = "Un piccolo avvertimento: se qualcuno osa disobbedire alla mia assistente appena assunta..."
  },
  AvgDialog_58291_Content_99 = {
    Text = "N premette delicatamente l'interruttore della sega elettrica nella mano di Erica, e il rumore assordante costrinse tutti a tapparsi immediatamente le orecchie."
  },
  AvgDialog_58292_Content_1 = {
    Text = "Primo Incontro"
  },
  AvgDialog_58292_Content_10 = {
    Text = "Ma, ma io sono stata con il signor Ryker tutto il tempo, vero, capo?"
  },
  AvgDialog_58292_Content_11 = {
    Text = "Nessuno risponde al richiamo un po' colpevole di Hannah."
  },
  AvgDialog_58292_Content_12 = {
    Text = "Dall'altra parte della casa, il detective e il suo assistente temporaneo hanno iniziato l'indagine sul posto."
  },
  AvgDialog_58292_Content_13 = {
    Text = "Entrambe le scarpe mancano. Ci sono anche due solchi sul collo, strano."
  },
  AvgDialog_58292_Content_14 = {
    Text = "Esamini attentamente con una lente d'ingrandimento i due segni di legatura sul collo del signor Dexter. Sono quasi identici, con solo lievi variazioni nell'angolazione."
  },
  AvgDialog_58292_Content_15 = {
    Text = "Anche i segni delle due impronte sono diversi. Quella interna ha una struttura a diamante regolare, mentre quella esterna è più grezza..."
  },
  AvgDialog_58292_Content_16 = {
    Text = "Forse la corda si è spezzata a metà, o si è sporcata di sangue, e l'assassino l'ha sostituita."
  },
  AvgDialog_58292_Content_17 = {
    Text = "In ogni caso, entrambi i segni sul collo passavano oltre la mascella, si estendevano dietro le orecchie e scomparivano gradualmente verso la nuca..."
  },
  AvgDialog_58292_Content_18 = {
    Text = "Sono segni di legatura causati da un'impiccagione."
  },
  AvgDialog_58292_Content_19 = {
    Text = "No, non è corretto... I graffi vicino ai segni di legatura suggeriscono una lotta violenta."
  },
  AvgDialog_58292_Content_2 = {
    Text = [[
Studio di Villa Ferland
90 minuti rimanenti alla conclusione del caso <Red:90>]]
  },
  AvgDialog_58292_Content_20 = {
    Text = "O forse ha iniziato a pentirsi dopo essersi impiccato? Ho sentito di casi simili."
  },
  AvgDialog_58292_Content_21 = {
    Text = "Senza quel disco in vinile, nove poliziotti su dieci avrebbero archiviato il caso come suicidio."
  },
  AvgDialog_58292_Content_22 = {
    Text = "E io sono l'ultimo di quel decimo vigile!"
  },
  AvgDialog_58292_Content_23 = {
    Text = "Disco in vinile?"
  },
  AvgDialog_58292_Content_24 = {
    Text = "{Male=Il Sig.,Female=La Sig.na} Custode non era sulla scena allora! C'era un Disco in Vinile che ripeteva in Ciclo la Voce del Sig. Dexter, come un fantasma..."
  },
  AvgDialog_58292_Content_25 = {
    Text = "Hannah interviene improvvisamente, descrivendo con vivacità e incapace di trattenere un brivido."
  },
  AvgDialog_58292_Content_26 = {
    Text = "Capo, abbiamo perquisito ovunque ma non siamo riusciti a trovare Lady Sorel. Potrebbe essere già..."
  },
  AvgDialog_58292_Content_27 = {
    Text = "Ryker fece un gesto sicuro con la mano."
  },
  AvgDialog_58292_Content_28 = {
    Text = "Scoprirai presto dove si trova. Questo caso è quasi identico al primo caso di omicidio che ho investigato."
  },
  AvgDialog_58292_Content_29 = {
    Text = "Quindi questa è l'origine della cosiddetta \"intuizione\" del capo di prima..."
  },
  AvgDialog_58292_Content_3 = {
    Text = "Ero fuori dalla casa, a girovagare, cercando un modo per andarmene."
  },
  AvgDialog_58292_Content_30 = {
    Text = "Ehm, ehm. Scusate. Proprio così."
  },
  AvgDialog_58292_Content_31 = {
    Text = "Il disco del fonografo, la villa desolata, l'uomo misterioso che si è impiccato... Anche Hannah se lo ricorda!"
  },
  AvgDialog_58292_Content_32 = {
    Text = "\"Il misterioso uomo dalla testa di cane svela lo scandalo dell'alta società.\" Ricordo ancora quel titolo!"
  },
  AvgDialog_58292_Content_33 = {
    Text = "Una testa di cane? Te lo sei inventato? Fuori mi presento sempre come un gentiluomo di classe."
  },
  AvgDialog_58292_Content_34 = {
    Text = "Alla menzione del passato di Ryker, ti interessi immediatamente e tiri Hannah da parte."
  },
  AvgDialog_58292_Content_35 = {
    Text = "<Small:A pensarci bene, ho sempre trovato sospetto il suo status di detective.>"
  },
  AvgDialog_58292_Content_36 = {
    Text = "<Small:Devi capire che a Londinium, la ricompensa per risolvere un caso è di gran lunga inferiore a quello che potresti guadagnare in dieci minuti al tavolo da gioco.>"
  },
  AvgDialog_58292_Content_37 = {
    Text = "<Small:Forse l'identità di detective è solo una copertura...>"
  },
  AvgDialog_58292_Content_38 = {
    Text = "Ritira il tuo attacco personale nei miei confronti, Custode %player%. Anche i giocatori d'azzardo possono avere i propri hobby e le proprie carriere."
  },
  AvgDialog_58292_Content_39 = {
    Text = "Eh, perché c'è una bara qui? Il gusto di Dexter è davvero discutibile."
  },
  AvgDialog_58292_Content_4 = {
    Text = "Quindi stai dicendo che non hai un alibi. Annotato... Sei riuscita a trovare la via, Miss Casiah?"
  },
  AvgDialog_58292_Content_40 = {Text = "!!!"},
  AvgDialog_58292_Content_41 = {
    Text = "Non toccarla!"
  },
  AvgDialog_58292_Content_42 = {
    Text = "Prima che potesse finire di parlare, il detective diede due calci disinvolti alla bara. La risposta fu un silenzio di tomba."
  },
  AvgDialog_58292_Content_43 = {
    Text = "Strano... Non reagisce al tuo tocco?"
  },
  AvgDialog_58292_Content_44 = {
    Text = "Oh? Allora dimmi, che tipo di reazione dovrebbe avere?"
  },
  AvgDialog_58292_Content_45 = {
    Text = "Hai raccontato a Ryker tutto quello che avevi incontrato prima."
  },
  AvgDialog_58292_Content_46 = {
    Text = "Capisco... Ora ho capito!"
  },
  AvgDialog_58292_Content_47 = {
    Text = "Deve esserci una mummia misteriosa e supremamente potente all'interno!"
  },
  AvgDialog_58292_Content_48 = {
    Text = "Ryker si accovacciò improvvisamente, parlando in una \"lingua straniera\" che non capivi affatto."
  },
  AvgDialog_58292_Content_49 = {
    Text = "Mudchoke! Racoonmire @3!"
  },
  AvgDialog_58292_Content_5 = {
    Text = "Usa quel cervellino, Detective. Se l'avessi trovata, sarei ancora qui in piedi?"
  },
  AvgDialog_58292_Content_50 = {
    Text = "...Cosa stai dicendo?"
  },
  AvgDialog_58292_Content_51 = {
    Text = "È la lingua Lemouahe. 'Waxylaik klu, nedkesanmin zy?'"
  },
  AvgDialog_58292_Content_52 = {
    Text = "La bara nera rimase solenne e silenziosa, imperturbata dai saluti amichevoli ma alquanto sconcertanti."
  },
  AvgDialog_58292_Content_53 = {
    Text = "Va bene, basta così. Ho sentito l'antica lingua di Aram, e non somiglia per niente alla tua."
  },
  AvgDialog_58292_Content_54 = {
    Text = "Tsk, che noia. Torniamo al lavoro."
  },
  AvgDialog_58292_Content_55 = {
    Text = "Ryker si alzò, si stiracchiò pigramente e schioccò le dita due volte in aria."
  },
  AvgDialog_58292_Content_56 = {
    Text = "Bene, tutti quanti, so chi è l'assassino. Per risparmiare tempo, salterò le deduzioni e vi porterò direttamente dal colpevole."
  },
  AvgDialog_58292_Content_57 = {Text = "...?"},
  AvgDialog_58292_Content_58 = {
    Text = "Pfft. Se un romanziere cercasse di far avanzare la trama come fa il signor Ryker, probabilmente verrebbe appeso ai lampioni dai lettori infuriati."
  },
  AvgDialog_58292_Content_59 = {
    Text = "Non vuoi condividere nemmeno il più piccolo indizio?"
  },
  AvgDialog_58292_Content_6 = {
    Text = "Ehm... Ha senso."
  },
  AvgDialog_58292_Content_60 = {
    Text = "Ryker si grattò la testa con irritazione."
  },
  AvgDialog_58292_Content_61 = {
    Text = "Disco in vinile. La sua presenza indica probabilmente che l'assassino ha tentato di fabbricare un alibi posticipando l'ora del crimine."
  },
  AvgDialog_58292_Content_62 = {
    Text = "In altre parole, mentre il disco in vinile riproduceva la voce della vittima, il colpevole si trovava in realtà sulla scena del crimine."
  },
  AvgDialog_58292_Content_63 = {
    Text = "Un trucco astuto, ma sfortunatamente non ho seguito il percorso pianificato dall'assassino. Sentendo quel suono, invece di andarmene, ho sfondato la porta con un calcio."
  },
  AvgDialog_58292_Content_64 = {
    Text = "Un detective competente smonta l'alibi; un detective eccezionale stronca l'alibi sul nascere!"
  },
  AvgDialog_58292_Content_65 = {
    Text = "Hai annotato quella frase profonda, Hannah?"
  },
  AvgDialog_58292_Content_66 = {
    Text = "Eh? Capito, capo!"
  },
  AvgDialog_58292_Content_67 = {
    Text = "Ma capo, hai appena detto che il colpevole era sulla scena del crimine... Quindi..."
  },
  AvgDialog_58292_Content_68 = {
    Text = "Ryker estrasse una pistola e avanzò con fare disinvolto."
  },
  AvgDialog_58292_Content_69 = {
    Text = "Ora, presentiamo la giovane assassina che non si è fatta vedere dall'inizio dell'incidente e ha potuto solo nascondersi in preda al panico nell'ombra."
  },
  AvgDialog_58292_Content_7 = {
    Text = "Cucina al primo piano. Il padrone di casa ha dato istruzioni di preparare il cibo per tutti."
  },
  AvgDialog_58292_Content_70 = {
    Text = "Il detective si ferma davanti all'armadio e dà due leggeri colpi sulla porta."
  },
  AvgDialog_58292_Content_71 = {
    Text = "Pensi ancora di nasconderti fino all'ultimo momento? Allora basta con le buone maniere—"
  },
  AvgDialog_58292_Content_72 = {
    Text = "Il detective, con aria turbata, si strofina la tempia con la canna della pistola prima di spalancare la porta dell'armadio."
  },
  AvgDialog_58292_Content_73 = {Text = "Sorel..."},
  AvgDialog_58292_Content_74 = {Text = "?!"},
  AvgDialog_58292_Content_75 = {
    Text = "Lady Sorel!!!"
  },
  AvgDialog_58292_Content_76 = {
    Text = "Nessuna scusa patetica, nessun nascondiglio vergognoso, nessuna confessione in lacrime."
  },
  AvgDialog_58292_Content_77 = {
    Text = "Solo il corpo di Sorel giaceva silenzioso nell'angolo, il foro di proiettile sulla fronte fin troppo evidente, come a deridere la presunzione del detective."
  },
  AvgDialog_58292_Content_78 = {
    Text = "No... Non può essere..."
  },
  AvgDialog_58292_Content_79 = {
    Text = "Clang clang clang!"
  },
  AvgDialog_58292_Content_8 = {
    Text = "Nessuno è andato in cucina durante questo periodo, il che significa che anche la signorina Erica non ha un alibi..."
  },
  AvgDialog_58292_Content_80 = {
    Text = "Sembra che qualcuno abbia fatto una deduzione sbagliata!"
  },
  AvgDialog_58292_Content_81 = {
    Text = "Incastrare un umano innocente è un peccato imperdonabile; è tempo della Punizione!"
  },
  AvgDialog_58292_Content_82 = {
    Text = "N era pensieroso, reggendosi il mento rotondo. Quando pensa, la nebbia attorno al Suo volto rallenta."
  },
  AvgDialog_58292_Content_83 = {
    Text = "Punizione, Punizione... Chi dovrei uccidere?"
  },
  AvgDialog_58292_Content_9 = {
    Text = "Mi dispiace, detective. Dal nostro punto di vista, lei, il Custode e il signor Ryker siete tutti sospetti~"
  },
  AvgDialog_58293_Content_1 = {
    Text = "Muro nella Bara"
  },
  AvgDialog_58293_Content_10 = {
    Text = "Questo dovrebbe essere il nostro ultimo incontro, eppure il tuo cuore resta imperturbabile."
  },
  AvgDialog_58293_Content_11 = {Text = "..."},
  AvgDialog_58293_Content_12 = {
    Text = "Karnahk, il mio nome è Karnahk."
  },
  AvgDialog_58293_Content_13 = {Text = "!!"},
  AvgDialog_58293_Content_14 = {
    Text = "Mm... che sogno strano. Perché mi trovo in questo corridoio... Da quando ho toccato quella bara, la mia mente è in subbuglio."
  },
  AvgDialog_58293_Content_15 = {
    Text = "Tump, tump, tump."
  },
  AvgDialog_58293_Content_16 = {
    Text = "Con un turbinio di passi frettolosi, ti scontri con un'ombra scura."
  },
  AvgDialog_58293_Content_17 = {
    Text = "Ahi! Non bloccare il passaggio... Hmm, ma è {Male=il Sig.,Female=la Sig.na} Custode!"
  },
  AvgDialog_58293_Content_18 = {
    Text = "Uff... Meno male che stai bene. Pensavo..."
  },
  AvgDialog_58293_Content_19 = {
    Text = "Perché siete qui voi due? È successo qualcosa?"
  },
  AvgDialog_58293_Content_2 = {Text = "..."},
  AvgDialog_58293_Content_20 = {
    Text = "In segreto, il gioco della caccia è iniziato~"
  },
  AvgDialog_58293_Content_21 = {
    Text = "Un corpo esile si mosse nell'oscurità; Casiah atterrò leggera davanti a te come per magia."
  },
  AvgDialog_58293_Content_22 = {
    Text = "So da dove proveniva lo sparo. Vuoi venire a controllare con me? Ho un po' paura ad andare da sola."
  },
  AvgDialog_58293_Content_23 = {
    Text = "Da dove sei spuntata..."
  },
  AvgDialog_58293_Content_24 = {
    Text = "Casiah stava dormendo sul lampadario poco fa. Come si suol dire, più in alto stai, più lontano vedi..."
  },
  AvgDialog_58293_Content_25 = {
    Text = "Ho visto tutto, sai~"
  },
  AvgDialog_58293_Content_26 = {
    Text = "Casiah ti fa un occhiolino malizioso e ride allegramente."
  },
  AvgDialog_58293_Content_27 = {Text = "..."},
  AvgDialog_58293_Content_28 = {
    Text = "Cosa state lì impalati? Non volete essere i primi a vedere la scena del crimine?"
  },
  AvgDialog_58293_Content_29 = {
    Text = [[
Villa Ferland
Studio al primo piano]]
  },
  AvgDialog_58293_Content_3 = {
    Text = "Fermiamoci qui. Le nostre strade si dividono. Stai ancora cercando il <Yellow:Muro della Verità>?"
  },
  AvgDialog_58293_Content_30 = {
    Text = "Hai aperto la porta dello studio."
  },
  AvgDialog_58293_Content_31 = {
    Text = "Q-Questo è..."
  },
  AvgDialog_58293_Content_32 = {
    Text = "Signor Dexter?!"
  },
  AvgDialog_58293_Content_33 = {
    Text = "Un uomo pende dalle travi appeso a una corda, come una foglia che ondeggia nel vento. Il suo volto è avvolto da un pallore bluastro-verdognolo, e i suoi occhi sporgono dalle orbite."
  },
  AvgDialog_58293_Content_34 = {
    Text = "Per favore, mantenete tutti la calma per evitare di contaminare la scena del crimine."
  },
  AvgDialog_58293_Content_35 = {
    Text = "Scena... del crimine?"
  },
  AvgDialog_58293_Content_36 = {
    Text = "Non guardare, quel tizio è completamente morto. Fammi indovinare, è questo l'enigma lasciato per noi?"
  },
  AvgDialog_58293_Content_37 = {
    Text = "Una specie di gioco investigativo e di deduzione?"
  },
  AvgDialog_58293_Content_38 = {
    Text = "Bingo! Esatto~!"
  },
  AvgDialog_58293_Content_39 = {
    Text = "Dunque chi, in una notte così nevosa, ha crudelmente assassinato un gentiluomo di tale raffinatezza?"
  },
  AvgDialog_58293_Content_4 = {
    Text = "\"Tu\" annuisti."
  },
  AvgDialog_58293_Content_40 = {
    Text = "Cercate di scoprire la verità, cari detective."
  },
  AvgDialog_58293_Content_41 = {
    Text = "Che strano, non dovresti essere tu il principale sospettato, caro Signor N?"
  },
  AvgDialog_58293_Content_42 = {
    Text = "Coff, coff, permettetemi di essere più preciso—Trovate l'assassino che si finge uno dei miei cloni!"
  },
  AvgDialog_58293_Content_43 = {
    Text = "Proprio in mezzo a voi!"
  },
  AvgDialog_58293_Content_44 = {
    Text = "Un silenzio di morte."
  },
  AvgDialog_58293_Content_45 = {
    Text = "Paura e inquietudine si diffusero silenziosamente tra la folla. Gli sguardi scrutavano furtivamente gli altri, ponderando in silenzio la veridicità delle parole di N."
  },
  AvgDialog_58293_Content_46 = {
    Text = "E se rifiutassimo questo gioco?"
  },
  AvgDialog_58293_Content_47 = {
    Text = "Sapete cosa è più importante per un game designer come me, traboccante di ideali e passione?"
  },
  AvgDialog_58293_Content_48 = {
    Text = "Ovviamente, il coinvolgimento dei giocatori! Se nessuno è interessato, dovrò annunciare con rammarico la fine del gioco!"
  },
  AvgDialog_58293_Content_49 = {
    Text = "Nessuna risposta. Tutti stanno aspettando il \"ma\"—"
  },
  AvgDialog_58293_Content_5 = {
    Text = "Allora non cercherò di convincerti. A dire il vero, non sono mai riuscito a capirti... Sembri giovane, ma è come se avessi vissuto per migliaia di anni."
  },
  AvgDialog_58293_Content_50 = {Text = "Ma!"},
  AvgDialog_58293_Content_51 = {
    Text = "Addio per sempre, povero Mr. Dexter e Miss Elsa."
  },
  AvgDialog_58293_Content_52 = {
    Text = [[
Infermeria di Mythag
Nel frattempo...]]
  },
  AvgDialog_58293_Content_53 = {
    Text = "Com'è la situazione?"
  },
  AvgDialog_58293_Content_54 = {
    Text = "La situazione non è ottimistica. Elsa ha una grave emorragia intracranica, la pressione del liquido cerebrospinale è in aumento e la temperatura corporea resta sopra i 38°C."
  },
  AvgDialog_58293_Content_55 = {
    Text = "Il Custode e Hanna sono caduti in uno stato delirante. Sebbene rimangano in un sonno costante, i loro parametri fisici sono normali."
  },
  AvgDialog_58293_Content_56 = {
    Text = "Capito. E... che ne è di lui?"
  },
  AvgDialog_58293_Content_57 = {
    Text = "La ragazza non fece alcun nome, ma tutti i presenti sapevano a chi si stesse riferendo."
  },
  AvgDialog_58293_Content_58 = {
    Text = "Mr. Dexter... La diagnosi preliminare è che la pressione neurale ha causato un arresto cardiaco riflesso, simile all'asfissia meccanica."
  },
  AvgDialog_58293_Content_59 = {
    Text = "Arresto cardiaco?"
  },
  AvgDialog_58293_Content_6 = {
    Text = "Comunque, grazie. Ho trovato un modo per spezzare il sigillo. Prossimo passo: dirigermi a Roma e liberare la bestia..."
  },
  AvgDialog_58293_Content_60 = {
    Text = "Winkle annuisce."
  },
  AvgDialog_58293_Content_61 = {
    Text = "La rianimazione è fallita. La respirazione si è fermata cinque minuti fa. Teoricamente..."
  },
  AvgDialog_58293_Content_62 = {Text = "È morto."},
  AvgDialog_58293_Content_63 = {
    Text = [[
Villa Ferland
Studio al primo piano]]
  },
  AvgDialog_58293_Content_64 = {
    Text = "In altre parole, se non seguiamo le tue regole, le persone che muoiono qui non si risveglieranno nemmeno nel mondo reale?"
  },
  AvgDialog_58293_Content_65 = {
    Text = "N annuì con soddisfazione."
  },
  AvgDialog_58293_Content_66 = {
    Text = "Come previsto, sei tu quello che mi conosce meglio!"
  },
  AvgDialog_58293_Content_67 = {
    Text = "...Heh, non ne vado affatto fiero."
  },
  AvgDialog_58293_Content_68 = {
    Text = "E se fosse solo un bluff? Come puoi dimostrare che non stai mentendo?"
  },
  AvgDialog_58293_Content_69 = {
    Text = "Certo che posso dimostrarlo—ma non voglio, hehe."
  },
  AvgDialog_58293_Content_7 = {
    Text = "Il mago preparò faticosamente i bagagli e, dopo aver fatto qualche passo, si voltò indietro."
  },
  AvgDialog_58293_Content_70 = {
    Text = "Oppure potreste rischiare e terminare il gioco immediatamente, tornando al vostro grazioso piccolo mondo dove nulla è cambiato."
  },
  AvgDialog_58293_Content_71 = {
    Text = "Il calore del letto resta costante, gli esami continuano come al solito, e tutti rimangono sani e salvi."
  },
  AvgDialog_58293_Content_72 = {
    Text = "N guardò Ryker, aprendo con passione le sue piccole braccia."
  },
  AvgDialog_58293_Content_73 = {
    Text = "Vuoi scommettere? È ciò in cui sei più bravo."
  },
  AvgDialog_58293_Content_74 = {
    Text = "Mi dispiace, non gioco mai d'azzardo con la vita degli altri."
  },
  AvgDialog_58293_Content_75 = {
    Text = "Il gioco è appena iniziato. Finirlo adesso sarebbe fin troppo noioso!"
  },
  AvgDialog_58293_Content_76 = {
    Text = "Casiah si raddrizza e alza rapidamente la mano destra."
  },
  AvgDialog_58293_Content_77 = {
    Text = "Bip bip! Io voto per continuare a giocare~!"
  },
  AvgDialog_58293_Content_78 = {
    Text = "Dopo lunga discussione, per ragioni diverse, tutti raggiunsero sorprendentemente un consenso."
  },
  AvgDialog_58293_Content_79 = {
    Text = "Sono davvero commosso! Grazie a tutti per aver rispettato incondizionatamente il mio progetto!"
  },
  AvgDialog_58293_Content_8 = {
    Text = "Ehi, non mi hai ancora detto il tuo nome."
  },
  AvgDialog_58293_Content_80 = {
    Text = "Ora, dichiaro ufficialmente: <Red:La seconda prova ha inizio!>"
  },
  AvgDialog_58293_Content_81 = {
    Text = "Avete ben due ore intere per risolvere l'enigma~"
  },
  AvgDialog_58293_Content_82 = {
    Text = "Solo due ore... non sono sufficienti."
  },
  AvgDialog_58293_Content_83 = {
    Text = "Oh oh oh, mentre qualcuno dubitava del grande Lord N, altri dieci secondi sono scivolati via."
  },
  AvgDialog_58293_Content_84 = {
    Text = "Bene allora, divertitevi tutti~"
  },
  AvgDialog_58293_Content_85 = {
    Text = "Dopo aver parlato, N si trasformò in fumo nero e svanì senza un suono."
  },
  AvgDialog_58293_Content_86 = {Text = "..."},
  AvgDialog_58293_Content_87 = {
    Text = "Ryker rifletté per un momento prima di pizzicarti improvvisamente la guancia."
  },
  AvgDialog_58293_Content_88 = {
    Text = "Fa male... Ehi, che stai facendo?!"
  },
  AvgDialog_58293_Content_89 = {
    Text = "Rilassati. Verifichiamo se sei un impostore."
  },
  AvgDialog_58293_Content_9 = {
    Text = "Il vento trasportava onde di fine sabbia dorata. Il mago cencioso si stagliava contro il cielo azzurro, un raro accenno di gentilezza sul suo volto arrossato."
  },
  AvgDialog_58293_Content_90 = {
    Text = "Mm, un livello moderato di cautela è necessario. Quindi—"
  },
  AvgDialog_58293_Content_91 = {
    Text = "Hai afferrato una manciata del soffice pelo di Ryker e ne hai strappato qualche ciuffo."
  },
  AvgDialog_58293_Content_92 = {Text = "Hiss!!"},
  AvgDialog_58293_Content_93 = {
    Text = "Sniff... Ha un odore autentico."
  },
  AvgDialog_58293_Content_94 = {
    Text = "\"Prego. Sono tutti tuoi. Ricordati di lavarli, farli asciugare all'aria e conservarli per bene.\""
  },
  AvgDialog_58294_Content_1 = {
    Text = "Sotto la Realtà"
  },
  AvgDialog_58294_Content_10 = {
    Text = "Avanzò con passo deciso fino a trovarsi davanti a N."
  },
  AvgDialog_58294_Content_11 = {
    Text = "Deduzione sbagliata? Impossibile. Devi aver manomesso qualcosa."
  },
  AvgDialog_58294_Content_12 = {
    Text = "Ti sei completamente dimenticato dei due diversi segni di strangolamento e delle scarpe mancanti?"
  },
  AvgDialog_58294_Content_13 = {
    Text = "Potrei elencare dozzine di possibilità adesso, ma contano davvero? O forse non avrebbero contato, se non fosse per la tua manipolazione—"
  },
  AvgDialog_58294_Content_14 = {
    Text = "\"Originale\"? Strano. Se il mio compito è svelare la verità del <Red:Dominio>, allora il Dominio è la vostra unica realtà e riferimento attuale."
  },
  AvgDialog_58294_Content_15 = {
    Text = "Perché qualcuno continua a soffermarsi sul cosiddetto \"passato\"?"
  },
  AvgDialog_58294_Content_16 = {Text = "!!"},
  AvgDialog_58294_Content_17 = {
    Text = "Forse una volta hai risolto questo caso brillantemente, guadagnando un misero briciolo di vanità e importanza, e da allora non hai fatto altro che rivivere quel momento."
  },
  AvgDialog_58294_Content_18 = {
    Text = "Ma sfortunatamente, qui hai combinato un disastro totale, Detective."
  },
  AvgDialog_58294_Content_19 = {
    Text = "N alzò lentamente la mano e schioccò leggermente le dita."
  },
  AvgDialog_58294_Content_2 = {
    Text = "Chi dovrei uccidere..."
  },
  AvgDialog_58294_Content_20 = {Text = "...Eh?"},
  AvgDialog_58294_Content_21 = {
    Text = "L'istante dopo, volute di nebbia nera iniziarono improvvisamente a fuoriuscire dal corpo di Casiah, che fino a quel momento aveva osservato da parte."
  },
  AvgDialog_58294_Content_22 = {
    Text = "È deciso. La Punizione comincia da te."
  },
  AvgDialog_58294_Content_23 = {
    Text = "Ehi... non era quel tizio a dover fallire la deduzione? Perché Casiah ne paga le conseguenze al posto suo!"
  },
  AvgDialog_58294_Content_24 = {
    Text = "No... È così doloroso..."
  },
  AvgDialog_58294_Content_25 = {
    Text = "Vedi? Ogni decisione stupida che prendi ha un costo per qualcun altro, proprio come nella vita reale."
  },
  AvgDialog_58294_Content_26 = {Text = "?!"},
  AvgDialog_58294_Content_27 = {
    Text = "Sniff, sniff... Non mi sono ancora divertita abbastanza... Perché dovrebbe importarmi..."
  },
  AvgDialog_58294_Content_28 = {
    Text = "Casiah fulmina Ryker con lo sguardo e scaglia il bastone con rabbia."
  },
  AvgDialog_58294_Content_29 = {
    Text = "È tutta colpa tua! Così stupido — ahi!"
  },
  AvgDialog_58294_Content_3 = {
    Text = "<Shake:Ci, ci scusi tanto, Signor N!> La deduzione di poco fa erano sciocchezze di quel tizio. Siamo tutti in disaccordo!"
  },
  AvgDialog_58294_Content_30 = {
    Text = "Prima ancora di finire la frase, Casiah scomparve completamente davanti a te, come cancellata dal progetto con una gomma."
  },
  AvgDialog_58294_Content_31 = {
    Text = "Signorina Casiah!!"
  },
  AvgDialog_58294_Content_32 = {
    Text = "Sniff... Mi aveva promesso di insegnarmi qualche trucco di magia..."
  },
  AvgDialog_58294_Content_33 = {
    Text = "Bene, a tutti voi resta un'ora. Se non ci sono altre domande, allora—"
  },
  AvgDialog_58294_Content_34 = {
    Text = "...Aspetta."
  },
  AvgDialog_58294_Content_35 = {
    Text = "Il detective ti dà una pacca sulla spalla e poi fa un passo avanti."
  },
  AvgDialog_58294_Content_36 = {
    Text = "%player%, tu continua le indagini. Devo scambiare due parole con questo tizio."
  },
  AvgDialog_58294_Content_37 = {Text = "...Capito."},
  AvgDialog_58294_Content_38 = {
    Text = "La folla radunata si disperse ancora una volta mentre un'oscurità viscosa avanzava, divorando rapidamente l'intero Dominio."
  },
  AvgDialog_58294_Content_39 = {
    Text = "Bene, ora possiamo parlare liberamente. Che ne pensi del mio nuovo avatar?"
  },
  AvgDialog_58294_Content_4 = {
    Text = "Volevo contraddirlo fin dall'inizio, ma non ne ho mai avuto l'occasione..."
  },
  AvgDialog_58294_Content_40 = {
    Text = "Sono più abituato a come sei adesso."
  },
  AvgDialog_58294_Content_41 = {
    Text = "Che peccato. Ultimamente ho riflettuto sul fatto che il mio aspetto sia troppo spaventoso, facendo sì che tutti abbiano paura di me."
  },
  AvgDialog_58294_Content_42 = {
    Text = "Fidati, saresti più popolare se rinunciassi a quei giochi oscuri e contorti... non c'è bisogno di scambiarsi la testa."
  },
  AvgDialog_58294_Content_43 = {
    Text = "Non se ne parla. Tu rinunceresti a respirare?"
  },
  AvgDialog_58294_Content_44 = {Text = "..."},
  AvgDialog_58294_Content_45 = {
    Text = "Va bene, torniamo al punto."
  },
  AvgDialog_58294_Content_46 = {
    Text = "Hai detto prima... che tutti pagheranno per il mio scarso giudizio, proprio come accadrebbe nel mondo reale."
  },
  AvgDialog_58294_Content_47 = {
    Text = "Potresti spiegarmelo?"
  },
  AvgDialog_58294_Content_48 = {
    Text = "N inclinò la testa, e la nebbia oscura Lo avvolse rapidamente."
  },
  AvgDialog_58294_Content_49 = {
    Text = "Un istante dopo, cambiò nuovamente forma."
  },
  AvgDialog_58294_Content_5 = {
    Text = "Signorina Hannah, presumo che anche lei sia in disaccordo con il ragionamento del Signor Ryker di poco fa?"
  },
  AvgDialog_58294_Content_50 = {
    Text = "Vuoi davvero saperlo? Basta che poi non vieni a piangere da me. Odio le lacrime umane!"
  },
  AvgDialog_58294_Content_51 = {
    Text = "Ryker incrociò le braccia, fissando N con un'espressione impassibile."
  },
  AvgDialog_58294_Content_52 = {
    Text = "Hmph, non posso rifiutarti. Da dove dovrei cominciare... Ah, ti ricordi quella ragazza di nome Elsa?"
  },
  AvgDialog_58294_Content_53 = {
    Text = "Nella storia, il coraggioso detective indicò la strada alla ragazza e poi la aiutò a respingere i mostri della Dissoluzione."
  },
  AvgDialog_58294_Content_54 = {
    Text = "Ma nella realtà, la ragazza seguì le indicazioni del detective, entrò in un vicolo cieco e fu uccisa dal mostro della Dissoluzione che la inseguiva."
  },
  AvgDialog_58294_Content_55 = {Text = "?!"},
  AvgDialog_58294_Content_56 = {
    Text = "Shh... Silenzio, ascoltami. Nella storia, un giocatore d'azzardo di passaggio risolve un omicidio in una villa misteriosa e si trasforma in un grande detective."
  },
  AvgDialog_58294_Content_57 = {
    Text = "Ma nella realtà, il giocatore d'azzardo incolpò un innocente, permettendo al vero assassino di farla franca."
  },
  AvgDialog_58294_Content_58 = {
    Text = "Potrei fare innumerevoli esempi come questi. Detective, hai mai considerato che la tua \"buona fortuna\" non è la ragione per cui sei arrivato fin qui, ma piuttosto il risultato?"
  },
  AvgDialog_58294_Content_59 = {
    Text = "Risultato...?"
  },
  AvgDialog_58294_Content_6 = {
    Text = "Ah... Io, neanch'io sono d'accordo! Solo un pazzo potrebbe inventarsi una cosa del genere!"
  },
  AvgDialog_58294_Content_60 = {
    Text = "Un esito alterato. Il dio concede fortuna ai mortali, e il prezzo è che tutti gli altri debbano sopportare la sofferenza al suo posto."
  },
  AvgDialog_58294_Content_61 = {
    Text = "Come ho detto prima, il Dominio è la tua realtà."
  },
  AvgDialog_58294_Content_62 = {
    Text = "Vuoi dire che tutto ciò che ho ottenuto grazie alla fortuna e le persone che ho aiutato in passato... era tutto falso?"
  },
  AvgDialog_58294_Content_63 = {
    Text = "Ehi, perché quello sguardo con gli occhi lucidi? Ricorda, vivere nella menzogna può essere anche una forma di felicità."
  },
  AvgDialog_58294_Content_64 = {
    Text = "Se non mi credi, dai un'occhiata alla vera forma di Aram, che un tempo hai salvato—"
  },
  AvgDialog_58294_Content_65 = {
    Text = "Le fiamme lambiscono il cielo, il suono delle grida e l'odore di carne bruciata ti fanno girare la testa."
  },
  AvgDialog_58294_Content_66 = {
    Text = "Vene cremisi di sangue coagulato germogliavano dalla base dell'Albero Madre, allungandosi gioiosamente verso un orizzonte che sembrava non avere fine."
  },
  AvgDialog_58294_Content_67 = {
    Text = "Cumuli di carne e arti sono ammassati come giganteschi santuari sotto un cielo giallo spento, che divora persino la luce del sole."
  },
  AvgDialog_58294_Content_68 = {
    Text = "Al centro del santuario, Ryker vide il proprio volto. Era grigio e spento, con le palpebre cadenti, dall'aspetto estremamente docile."
  },
  AvgDialog_58294_Content_69 = {
    Text = "Se non fosse stato per metà della testa mozzata, che esponeva un tronco encefalico brulicante di larve, quello sarebbe stato il volto impeccabile di un santo."
  },
  AvgDialog_58294_Content_7 = {Text = "...Follia?"},
  AvgDialog_58294_Content_70 = {
    Text = "<Red:La Vera Storia>: Non sei riuscito a fermare Casiah, e non sei riuscito a fermare nemmeno Herbert. Non sei nemmeno arrivato all'accampamento di Aram."
  },
  AvgDialog_58294_Content_71 = {
    Text = "La verità è che non hai ottenuto nulla. E per questo, Aram è finita così."
  },
  AvgDialog_58294_Content_72 = {
    Text = "È questa la realtà che desideri, mio caro Signor Giocatore d'Azzardo?"
  },
  AvgDialog_58294_Content_73 = {Text = "..."},
  AvgDialog_58294_Content_74 = {
    Text = "La \"realtà\" si ritira, lasciando Ryker solo nell'oscurità."
  },
  AvgDialog_58294_Content_75 = {
    Text = "Hah. Quindi ti sei dato tutto questo disturbo per progettare un gioco solo per ricordarmi i miei fallimenti?"
  },
  AvgDialog_58294_Content_76 = {
    Text = "Non ce n'era bisogno. Se c'è una verità che questo mondo mi ha insegnato, è questa: non valgo nulla. Mi dispiace. Che peccato."
  },
  AvgDialog_58294_Content_77 = {
    Text = "Solo un piccolo avvertimento. Non voglio che si ripeta quello che è successo durante il tuo periodo ad Aram."
  },
  AvgDialog_58294_Content_78 = {
    Text = "Se fai un'altra bravata inutile che mette a rischio delle vite, altre persone scompariranno. Capito?"
  },
  AvgDialog_58294_Content_79 = {Text = "...Capito."},
  AvgDialog_58294_Content_8 = {
    Text = "Stai zitto."
  },
  AvgDialog_58294_Content_80 = {
    Text = "\"Il detective abbassò la testa e rispose svogliatamente.\""
  },
  AvgDialog_58294_Content_81 = {
    Text = "Quando il sipario di oscurità si sollevò, si ritrovò nel suo familiare studio."
  },
  AvgDialog_58294_Content_82 = {
    Text = "Phew... Finalmente sveglio! All'improvviso sei rimasto lì immobile, ci hai fatto morire di paura!"
  },
  AvgDialog_58294_Content_83 = {
    Text = "Che è successo, Signor Ryker? Hai un aspetto terribile."
  },
  AvgDialog_58294_Content_84 = {
    Text = "Niente. Ho bisogno di un po' di tempo da solo. Torno subito."
  },
  AvgDialog_58294_Content_85 = {
    Text = "\"Il detective rimase calmo e vi rivolse persino un caloroso sorriso.\""
  },
  AvgDialog_58294_Content_86 = {
    Text = "Se ne andò quasi senza nemmeno voltarsi a guardarvi."
  },
  AvgDialog_58294_Content_87 = {
    Text = "Signor Ryker...?"
  },
  AvgDialog_58294_Content_9 = {
    Text = "Pesti il piede al detective, ma il detective dal forte spirito competitivo ignora il tuo suggerimento aggressivo."
  },
  AvgDialog_58326_Content_1 = {
    Text = "Deduzione Inversa"
  },
  AvgDialog_58326_Content_10 = {
    Text = "Un colpo per sì, due colpi per no. Riesci a farlo?"
  },
  AvgDialog_58326_Content_11 = {
    Text = "Attraverso la spessa tavola di legno di sandalo, la voce di Ryker portava una qualità insolitamente dolce e irreale."
  },
  AvgDialog_58326_Content_12 = {
    Text = "Dai un leggero colpo."
  },
  AvgDialog_58326_Content_13 = {
    Text = "Ottimo! In realtà è semplice. Ho solo tre domande."
  },
  AvgDialog_58326_Content_14 = {
    Text = "Prima domanda, sei intrappolato dentro qualcosa?"
  },
  AvgDialog_58326_Content_15 = {
    Text = "<Yellow:Tonf.>"
  },
  AvgDialog_58326_Content_16 = {
    Text = "Seconda domanda, sei uno di noi? Con \"noi\" intendo quelli che sono entrati nel Dominio di quel tizio."
  },
  AvgDialog_58326_Content_17 = {
    Text = "<Yellow:Tonf.>"
  },
  AvgDialog_58326_Content_18 = {
    Text = "Ottimo, il mio istinto non mente mai. La terza domanda..."
  },
  AvgDialog_58326_Content_19 = {
    Text = "Sei %player%?"
  },
  AvgDialog_58326_Content_2 = {
    Text = "Il bussare continua."
  },
  AvgDialog_58326_Content_20 = {
    Text = "Colpisci la bara con forza, poi senti una risatina sommessa."
  },
  AvgDialog_58326_Content_21 = {
    Text = "Sei davvero tu. Non avere paura; risolverò tutti gli enigmi e ti salverò. Resta qui e stai al sicuro, capito?"
  },
  AvgDialog_58326_Content_22 = {
    Text = "<Yellow:Tonf.>"
  },
  AvgDialog_58326_Content_23 = {
    Text = "Molto bene, amico mio. Addio."
  },
  AvgDialog_58326_Content_24 = {
    Text = "Il fruscio di vestiti e il suono di passi che si allontanano gradualmente giungono alle tue orecchie."
  },
  AvgDialog_58326_Content_25 = {
    Text = "Emetti un profondo sospiro e chiudi gli occhi. Tuttavia, poco dopo, il suono dei passi ritorna."
  },
  AvgDialog_58326_Content_26 = {
    Text = "Scusa, in realtà ho dimenticato la domanda più importante. È fondamentale per i miei prossimi passi."
  },
  AvgDialog_58326_Content_27 = {
    Text = "Attendi in silenzio quella \"domanda importante\"."
  },
  AvgDialog_58326_Content_28 = {
    Text = "Ti fidi di me?"
  },
  AvgDialog_58326_Content_29 = {
    Text = "<Gray:Che razza di domanda è...>"
  },
  AvgDialog_58326_Content_3 = {
    Text = "Ehi, amico nella bara, stai bene?"
  },
  AvgDialog_58326_Content_30 = {
    Text = "Sorridi e tocchi delicatamente la superficie interna liscia della bara."
  },
  AvgDialog_58326_Content_31 = {Text = "—Tump."},
  AvgDialog_58326_Content_32 = {
    Text = "Mi fido di te."
  },
  AvgDialog_58326_Content_33 = {
    Text = "Capisco. Il tuo intuito è sempre stato acuto."
  },
  AvgDialog_58326_Content_34 = {
    Text = "Purtroppo...{Male=lui,Female=lei} è intrappolat{Male=o,Female=a} nella coscienza di <Yellow:quell'individuo>, anche se scoprissi la verità ultima, sarebbe inutile."
  },
  AvgDialog_58326_Content_35 = {
    Text = "La realtà è che {Male=lui,Female=lei} resterà per sempre intrappolat{Male=o,Female=a} nella coscienza meticolosamente selezionata del contenitore."
  },
  AvgDialog_58326_Content_36 = {Text = "?!"},
  AvgDialog_58326_Content_37 = {
    Text = "Hai detto: \"Una volta che tutte le verità saranno rivelate...\""
  },
  AvgDialog_58326_Content_38 = {
    Text = "La nebbia nera che fluiva lentamente sul volto di N si arricciò con soddisfazione, come se stesse assaporando una rara prelibatezza."
  },
  AvgDialog_58326_Content_39 = {
    Text = "Heh... è la prima volta che vedo quell'espressione su di te. Peccato, la rabbia non risolverà nulla."
  },
  AvgDialog_58326_Content_4 = {
    Text = "Una voce leggera e gioiosa giunge, come se fosse intrisa di un potere magico, fermando istantaneamente le tue lacrime."
  },
  AvgDialog_58326_Content_40 = {
    Text = "Ho solo promesso di dissolvere il Dominio, non che tutti sarebbero stati al sicuro."
  },
  AvgDialog_58326_Content_41 = {
    Text = "Di' addio al tuo amichetto, Detective."
  },
  AvgDialog_58326_Content_42 = {
    Text = "N alzò un dito, ma l'istante dopo—"
  },
  AvgDialog_58326_Content_43 = {
    Text = "<Red:L'incubo è finito. Apri gli occhi.>"
  },
  AvgDialog_58326_Content_44 = {Text = "Rombo..."},
  AvgDialog_58326_Content_45 = {
    Text = "Il pavimento sotto di loro si spacca improvvisamente, e un serpente reale nero emerge dall'abisso senza fondo, trafiggendo rapidamente il corpo di N."
  },
  AvgDialog_58326_Content_46 = {Text = "...?"},
  AvgDialog_58326_Content_47 = {
    Text = "Per chiarire: l'80% del mio corpo è composto da nebbia, e il restante 20% è anch'esso nebbia. Questi trucchetti inutili—"
  },
  AvgDialog_58326_Content_48 = {
    Text = "Il bagliore argenteo si accende all'improvviso, come il riflettore che segnala l'inizio di uno spettacolo."
  },
  AvgDialog_58326_Content_49 = {
    Text = "Uno studente dai capelli ricci si massaggiò una spalla rigida con una mano, tenendo nell'altra una chiave d'argento, emergendo dalle ombre."
  },
  AvgDialog_58326_Content_5 = {
    Text = "Scusa se prima sono stato un po' scortese con te."
  },
  AvgDialog_58326_Content_50 = {
    Text = "Phew... Ce l'ho fatta finalmente."
  },
  AvgDialog_58326_Content_51 = {
    Text = "Come ci si aspettava dalla persona di cui mi fido! Sapevo che non ti saresti fatto intrappolare così facilmente."
  },
  AvgDialog_58326_Content_52 = {
    Text = "Hmm, naturalmente."
  },
  AvgDialog_58326_Content_53 = {
    Text = "Grazie ai nuovi amici che ho incontrato nella bara."
  },
  AvgDialog_58326_Content_54 = {Text = "Hss..."},
  AvgDialog_58326_Content_55 = {
    Text = "Serpente...?"
  },
  AvgDialog_58326_Content_56 = {Text = "..."},
  AvgDialog_58326_Content_57 = {
    Text = "È passato tanto tempo, Apophis."
  },
  AvgDialog_58326_Content_6 = {
    Text = "Ma ora ho molte domande e vorrei parlartene. Non puoi parlare in questo momento?"
  },
  AvgDialog_58326_Content_7 = {
    Text = "<Change>Sì!!"
  },
  AvgDialog_58326_Content_8 = {
    Text = "Raccogli tutte le tue forze per parlare, ma le parole si trasformano in mormorii incoerenti."
  },
  AvgDialog_58326_Content_9 = {
    Text = "Questo complica le cose... Oh, riesci ancora a muovere la mano?"
  },
  AvgDialog_58327_Content_1 = {
    Text = "Buona fortuna!"
  },
  AvgDialog_58327_Content_10 = {
    Text = "Dexter alza le spalle con aria innocente."
  },
  AvgDialog_58327_Content_11 = {
    Text = "Vorrei saperlo anch'io. Prima di interrogarmi, per favore distingui tra la realtà e il Dominio."
  },
  AvgDialog_58327_Content_12 = {
    Text = "Dopotutto, nella realtà, nessun caso criminale è mai avvenuto nella mia famiglia, giusto?"
  },
  AvgDialog_58327_Content_13 = {Text = "..."},
  AvgDialog_58327_Content_14 = {
    Text = "Qualcuno ha visto Ryker? Elsa si è appena svegliata e vuole il suo autografo."
  },
  AvgDialog_58327_Content_15 = {
    Text = "Non mi sarei mai aspettato che il Sig. Ryker avesse delle ammiratrici... Davvero sorprendente."
  },
  AvgDialog_58327_Content_16 = {
    Text = "Dopotutto, sono stato io a salvarla da quel mostro. Se proprio devo dire..."
  },
  AvgDialog_58327_Content_17 = {
    Text = "Elsa ha scelto di studiare nel Mythag sperando che un giorno avrebbe potuto essere come il signor Ryker—"
  },
  AvgDialog_58327_Content_18 = {
    Text = "Diventare una ludopatica?"
  },
  AvgDialog_58327_Content_19 = {
    Text = "Andare ad aiutare gli altri."
  },
  AvgDialog_58327_Content_2 = {
    Text = [[
Campus Mythag 
 Una settimana dopo]]
  },
  AvgDialog_58327_Content_20 = {
    Text = "Il signor Ryker non ama restare a scuola. Quanto a %player%... {Male=lui,Female=lei} è uscit{Male=o,Female=a} di prima mattina, dicendo che c'era qualcosa di urgente."
  },
  AvgDialog_58327_Content_21 = {
    Text = "Inoltre... qualcosa non torna. N ha davvero creato questo Dominio solo per infastidire Ryker?"
  },
  AvgDialog_58327_Content_22 = {
    Text = "Forse sì, forse no. È difficile quanto l'esperimento della doppia fenditura. Dovremmo concentrarci su questioni più pratiche."
  },
  AvgDialog_58327_Content_23 = {
    Text = "Ad esempio, cosa dovremmo fare per il brutto raffreddore di Hanna?"
  },
  AvgDialog_58327_Content_24 = {
    Text = "In una caverna buia e senza fine, innumerevoli occhi si aprono e si chiudono lentamente, come luci spettrali tremolanti nell'oscurità."
  },
  AvgDialog_58327_Content_25 = {
    Text = "Un vento gelido soffiò, e una tenue nebbia nera si contorceva al centro della caverna, condensandosi a malapena in un'eterea forma umanoide."
  },
  AvgDialog_58327_Content_26 = {
    Text = "<Change>Ugh... Padrone... ferito..."
  },
  AvgDialog_58327_Content_27 = {
    Text = "È da tanto che non ci vediamo, miei detestabili eppure amati figli. Sono passati secoli dalla mia ultima visita."
  },
  AvgDialog_58327_Content_28 = {
    Text = "Fatemi vedere se siete cresciuti... Oh, scusate. Dimenticavo che vi restano solo gli occhi."
  },
  AvgDialog_58327_Content_29 = {
    Text = "<Change>Padrone... Amore..."
  },
  AvgDialog_58327_Content_3 = {Text = "..."},
  AvgDialog_58327_Content_30 = {
    Text = "Bene, le chiacchiere le facciamo dopo. Ho confermato qualcosa di interessante."
  },
  AvgDialog_58327_Content_31 = {
    Text = "Quel Custode riesce davvero a entrare in risonanza con la coscienza di Karnahk... interessante."
  },
  AvgDialog_58327_Content_32 = {
    Text = "<Change>Hihihi... Lalala..."
  },
  AvgDialog_58327_Content_33 = {
    Text = "Basta... La mia proiezione è ferita e ha bisogno di un po' di guarigione."
  },
  AvgDialog_58327_Content_34 = {
    Text = "Tutti quanti, silenzio."
  },
  AvgDialog_58327_Content_35 = {Text = "—!!"},
  AvgDialog_58327_Content_36 = {
    Text = "Con un lamento lacerante, tutti gli occhi furono schiacciati, e il sangue iniziò a gocciolare sul terreno."
  },
  AvgDialog_58327_Content_37 = {
    Text = "La nebbia nera si espanse rapidamente, divorando avidamente la foschia di sangue nell'aria. Gradualmente, la forma umana un tempo eterea divenne finalmente concreta."
  },
  AvgDialog_58327_Content_38 = {
    Text = "Sapore orribile..."
  },
  AvgDialog_58327_Content_39 = {
    Text = [[
Cimitero di Highgate
Londinium Est, Kent]]
  },
  AvgDialog_58327_Content_4 = {
    Text = "Ti senti meglio? La Sig.ra Sylvia ha detto che hai poco appetito."
  },
  AvgDialog_58327_Content_40 = {
    Text = "Vedi quello? Il primo sfortunato che ho mandato in prigione è sepolto qui."
  },
  AvgDialog_58327_Content_41 = {
    Text = "Ti sei fermato davanti a una lapide solitaria nell'angolo."
  },
  AvgDialog_58327_Content_42 = {
    Text = "In base alle deduzioni nel Dominio, probabilmente hai mandato dentro la persona sbagliata. Dopotutto, non riesci ancora a spiegare i due segni e la scarpa mancante."
  },
  AvgDialog_58327_Content_43 = {
    Text = "Non credo. Come fai a sapere che la corda non è stata sostituita in fretta perché macchiata dal sangue dell'assassino?"
  },
  AvgDialog_58327_Content_44 = {
    Text = "Quanto alle scarpe mancanti—è strano, ma andare scalzi in casa a tarda notte non sembra così insolito."
  },
  AvgDialog_58327_Content_45 = {
    Text = "Inoltre, quanta forza e precisione servono per appendere qualcuno dalla finestra del primo piano? Ricorda, a parte la vittima, quella notte c'erano solo donne e bambini."
  },
  AvgDialog_58327_Content_46 = {
    Text = "Mm-hmm, posso accettare questa spiegazione."
  },
  AvgDialog_58327_Content_47 = {Text = "Quindi—"},
  AvgDialog_58327_Content_48 = {
    Text = "Ryker ti diede una pacca sulla testa con un sorriso allegro."
  },
  AvgDialog_58327_Content_49 = {
    Text = "Il mondo reale non è un romanzo giallo, Custode. Nessuno ucciderebbe usando metodi così contorti."
  },
  AvgDialog_58327_Content_5 = {
    Text = "Essere strangolato e poi resuscitato non è affatto piacevole. Ho sempre la sensazione di avere la gola piena di sassi adesso."
  },
  AvgDialog_58327_Content_50 = {
    Text = "Tch. Non è un romanzo giallo, è la tua fortuna?"
  },
  AvgDialog_58327_Content_51 = {
    Text = "Forse. Che coincidenza essermi imbattuto in questi indizi. Avranno mica messo le gambe?"
  },
  AvgDialog_58327_Content_52 = {
    Text = "La gente si meraviglia sempre della genialità di un matematico quando risolve un problema. Ma la genialità è semplicemente essere un passo avanti rispetto alla persona comune."
  },
  AvgDialog_58327_Content_53 = {
    Text = "Ryker rise e fece un gesto di vittoria verso la distanza invisibile."
  },
  AvgDialog_58327_Content_54 = {
    Text = "Immagino che tu sia come me, no?"
  },
  AvgDialog_58327_Content_55 = {
    Text = "Nessuno risponde al gesto ingenuo del detective. Una brezza leggera soffia, facendo frusciare le foglie, e l'oscurità cala gradualmente."
  },
  AvgDialog_58327_Content_56 = {
    Text = "Che noia. Sembra che stia per piovere. Andiamo."
  },
  AvgDialog_58327_Content_57 = {
    Text = "Tu e Ryker attraversaste il cimitero, con lo scricchiolio delle foglie cadute sotto i piedi. Nessuno parlava."
  },
  AvgDialog_58327_Content_58 = {
    Text = "A proposito... Ne abbiamo passate tante insieme. Non è ora che mi racconti il tuo passato, come nei romanzi?"
  },
  AvgDialog_58327_Content_59 = {
    Text = "Tipo da dove vieni, e come ti sei dato al gioco d'azzardo"
  },
  AvgDialog_58327_Content_6 = {
    Text = "Coff, coff..."
  },
  AvgDialog_58327_Content_60 = {Text = "Ehi..."},
  AvgDialog_58327_Content_61 = {
    Text = "Purtroppo, il mio passato, come quel caso, è piuttosto insignificante. Raccontarlo potrebbe rovinare il mistero che rappresento ai tuoi occhi."
  },
  AvgDialog_58327_Content_62 = {
    Text = "Heh, la tua autoconsapevolezza è ancora un tale disastro. È proprio per questo che sono sempre stato curioso."
  },
  AvgDialog_58327_Content_63 = {
    Text = "Va bene, se insisti, troviamo un caffè e parliamone con calma..."
  },
  AvgDialog_58327_Content_64 = {
    Text = "Le risate svaniscono gradualmente, e il cimitero torna al silenzio."
  },
  AvgDialog_58327_Content_65 = {
    Text = "Una tenue nebbia nera fluttua nell'aria, simile ad antiche particelle invisibili celate per millenni."
  },
  AvgDialog_58327_Content_66 = {
    Text = "La nebbia osservò il detective e il Custode allontanarsi, poi si espanse felicemente per un istante prima di disperdersi a malincuore."
  },
  AvgDialog_58327_Content_67 = {
    Text = "Come se non fosse mai apparsa."
  },
  AvgDialog_58327_Content_7 = {
    Text = "Dexter tossisce in modo esagerato dopo aver parlato."
  },
  AvgDialog_58327_Content_8 = {
    Text = "Sembra che vada tutto bene. Allora, parliamo della questione principale: cos'è quella bara a casa tua?"
  },
  AvgDialog_58327_Content_9 = {
    Text = "Se non mi sbaglio, appartiene all'ultimo faraone di Remouahe — Kanak."
  },
  AvgDialog_58328_Content_1 = {
    Text = "Lunedì Prossimo, Signore"
  },
  AvgDialog_58328_Content_10 = {
    Text = "Perché è il famoso \"Detective Fortunato\" dell'East Side."
  },
  AvgDialog_58328_Content_11 = {
    Text = "Finché è lui a occuparsi del caso, gli indizi sembrano apparire dal nulla, e il colpevole non riesce a sfuggire alle indagini per più di tre giorni!"
  },
  AvgDialog_58328_Content_12 = {
    Text = "Alcuni dicono che basta seguire il Sig. Ryker per un solo giorno per trovare dieci Leofang. Insomma, è il portafortuna di tutti."
  },
  AvgDialog_58328_Content_13 = {
    Text = "Ma la sua fortuna qui non regge..."
  },
  AvgDialog_58328_Content_14 = {
    Text = "Ho sentito che questo caso è molto simile a uno gestito dal Sig. Ryker?"
  },
  AvgDialog_58328_Content_15 = {
    Text = "Sì. Anche se il Sig. Ryker non lo dice, in realtà quel caso gli sta molto a cuore."
  },
  AvgDialog_58328_Content_16 = {
    Text = "Dovresti sapere che aveva un altro soprannome: <Blue:Sig. Lunedì Prossimo>."
  },
  AvgDialog_58328_Content_17 = {
    Text = "Lunedì prossimo, signore...?"
  },
  AvgDialog_58328_Content_18 = {
    Text = "Hannah si schiarisce la gola e inizia a parlare con un tono esagerato."
  },
  AvgDialog_58328_Content_19 = {
    Text = "\"Ryker, quando ripagherai i tuoi debiti di gioco?\" \"Lunedì prossimo!\""
  },
  AvgDialog_58328_Content_2 = {
    Text = [[
Esterno del Maniero Ferland
60 minuti rimanenti alla conclusione del caso <Red:60>]]
  },
  AvgDialog_58328_Content_20 = {
    Text = "\"Ryker, quando hai intenzione di trovarti un lavoro?\" \"Lunedì prossimo!\""
  },
  AvgDialog_58328_Content_21 = {
    Text = "\"Ryker, quando hai intenzione di morire?\" \"Lunedì prossimo!\""
  },
  AvgDialog_58328_Content_22 = {
    Text = "Ecco, così. A quei tempi, tutti ridevano di lui; i bambini gli facevano le smorfie alle spalle, e il proprietario del bar prendeva una sedia quando lo vedeva..."
  },
  AvgDialog_58328_Content_23 = {
    Text = "Insomma, nessuno lo rispettava."
  },
  AvgDialog_58328_Content_24 = {
    Text = "...Finché non risolse quel caso."
  },
  AvgDialog_58328_Content_25 = {
    Text = "Esattamente! Da quel momento in poi, la sua vita sembrò essere incantata. La buona sorte lo accompagnava sempre, e tutti lo apprezzavano sempre di più."
  },
  AvgDialog_58328_Content_26 = {
    Text = "Che strano. Esiste davvero una magia simile al mondo?"
  },
  AvgDialog_58328_Content_27 = {
    Text = "Chi lo sa, di questi tempi nulla sorprende più—Aspetta, cos'è quello?"
  },
  AvgDialog_58328_Content_28 = {
    Text = "Nell'angolo vicino al muro, una scarpa di pelle nera da uomo era semi-sepolta nella soffice neve bianca."
  },
  AvgDialog_58328_Content_29 = {
    Text = "Wow, che intagli raffinati. Sembra qualcosa che non potrei mai permettermi..."
  },
  AvgDialog_58328_Content_3 = {
    Text = "Etciù... Etciù!"
  },
  AvgDialog_58328_Content_30 = {Text = "!!!"},
  AvgDialog_58328_Content_31 = {
    Text = "È la scarpa di pelle del Sig. Dexter."
  },
  AvgDialog_58328_Content_32 = {
    Text = "Alzi lo sguardo. Le fredde mura grigie si innalzano verso il cielo, e le luci fioche fluttuano come fari."
  },
  AvgDialog_58328_Content_33 = {
    Text = "Lassù c'è la camera da letto di Dexter."
  },
  AvgDialog_58328_Content_34 = {
    Text = "Abbassi lo sguardo; lo studio è proprio davanti a te. Attraverso la finestra intagliata, l'ombra appesa di Dexter ti fissa in silenzio."
  },
  AvgDialog_58328_Content_35 = {
    Text = "Le due stanze sono allineate verticalmente."
  },
  AvgDialog_58328_Content_36 = {
    Text = "Hannah... Ho improvvisamente un'ipotesi."
  },
  AvgDialog_58328_Content_37 = {
    Text = "Spingi le scarpe nelle mani di Hannah."
  },
  AvgDialog_58328_Content_38 = {
    Text = "Andiamo a controllare lo studio."
  },
  AvgDialog_58328_Content_39 = {
    Text = [[
Studio del Maniero Ferland
30 minuti rimanenti alla conclusione del caso <Red:30>]]
  },
  AvgDialog_58328_Content_4 = {
    Text = "Hannah tiene una lampada a cherosene, rannicchiandosi accanto a te."
  },
  AvgDialog_58328_Content_40 = {
    Text = "Hai afferrato la maniglia e aperto la porta."
  },
  AvgDialog_58328_Content_41 = {
    Text = "Cosa succede? Siete andati a fare shopping fuori, voi due?"
  },
  AvgDialog_58328_Content_42 = {
    Text = "Sig. Ryker?! Non stava..."
  },
  AvgDialog_58328_Content_43 = {
    Text = "Sì, poco fa ero molto scosso e mi sono fatto un bel pianto in un angolo."
  },
  AvgDialog_58328_Content_44 = {
    Text = "Dai un'occhiata alla sua posa spensierata e improvvisamente gli dai una pacca sulla spalla."
  },
  AvgDialog_58328_Content_45 = {
    Text = "Sono felice di sapere che stai bene."
  },
  AvgDialog_58328_Content_46 = {
    Text = "Tsk. Che espressione disgustosa è quella..."
  },
  AvgDialog_58328_Content_47 = {
    Text = "Bene, non c'è tempo per borbottare! Sig. Ryker, abbiamo appena fatto una scoperta importante al piano di sotto!"
  },
  AvgDialog_58328_Content_48 = {
    Text = "Hai raccontato a Ryker le tue osservazioni fatte al piano di sotto."
  },
  AvgDialog_58328_Content_49 = {
    Text = "...Capisco."
  },
  AvgDialog_58328_Content_5 = {
    Text = "Dannazione, non è rimasta una sola impronta! Siamo usciti troppo tardi."
  },
  AvgDialog_58328_Content_50 = {
    Text = "Ryker si avvicinò alla finestra dello studio, dove una debole impronta di scarpa era appena visibile sul telaio bianco."
  },
  AvgDialog_58328_Content_51 = {
    Text = "Si sporse e guardò in alto."
  },
  AvgDialog_58328_Content_52 = {Text = "Ugh..."},
  AvgDialog_58328_Content_53 = {
    Text = "Se non mi sbaglio, l'altra scarpa è molto probabilmente in questa stanza."
  },
  AvgDialog_58328_Content_54 = {Text = "?!"},
  AvgDialog_58328_Content_55 = {
    Text = "Ma prima di quello, c'è una cosa che voglio confermare..."
  },
  AvgDialog_58328_Content_56 = {
    Text = "Il detective si avvicina al corpo di Sorel ed esamina attentamente la ferita da proiettile sulla sua fronte."
  },
  AvgDialog_58328_Content_57 = {
    Text = "I bordi presentano spessi residui di fuliggine e segni di bruciatura — l'assassino le ha sparato in faccia da distanza ravvicinata."
  },
  AvgDialog_58328_Content_58 = {
    Text = "Hmm... Cosa potrebbe significare?"
  },
  AvgDialog_58328_Content_59 = {
    Text = "Il detective scoppia improvvisamente a ridere. È la prima volta da quando è entrato nella villa che ride così di cuore."
  },
  AvgDialog_58328_Content_6 = {
    Text = "La stanza è stata perquisita a fondo. Possiamo solo tentare la fortuna fuori, adesso."
  },
  AvgDialog_58328_Content_60 = {
    Text = "Tutte le spiegazioni sono complete. Procediamo. È il momento dello spettacolo della deduzione."
  },
  AvgDialog_58328_Content_7 = {
    Text = "Sigh... Se solo il Sig. Ryker fosse qui, saprebbe cosa fare."
  },
  AvgDialog_58328_Content_8 = {
    Text = "\"Ha detto che voleva stare un po' da solo, e poi è sparito.\""
  },
  AvgDialog_58328_Content_9 = {
    Text = "A proposito, conoscevo il Sig. Ryker solo come giocatore d'azzardo. Non mi aspettavo che se la cavasse bene anche come detective..."
  },
  AvgDialog_58329_Content_1 = {
    Text = "Una Verità"
  },
  AvgDialog_58329_Content_10 = {Text = "!!"},
  AvgDialog_58329_Content_11 = {
    Text = "\"Eri così ansioso di interrompermi prima che rivelassi la verità sulla morte di Sorel. Non pensare che la tua comparsa mi farà abbassare la guardia nei tuoi confronti.\""
  },
  AvgDialog_58329_Content_12 = {
    Text = "<Red:Caro signor N?>"
  },
  AvgDialog_58329_Content_13 = {Text = "..."},
  AvgDialog_58329_Content_14 = {
    Text = "Il sangue smise di scorrere. Si trasformò in una nebbia nera come la pece, avvolgendo \"te\"."
  },
  AvgDialog_58329_Content_15 = {
    Text = "Infine, lo studente dai capelli ricci scompare, e la nebbia oscura si riversa nel corpo di N."
  },
  AvgDialog_58329_Content_16 = {
    Text = "Sembra che ti stia godendo lo spettacolo, vecchio amico."
  },
  AvgDialog_58329_Content_17 = {
    Text = "Solo un po' di ispirazione che ho tratto da te. Siamo due facce della stessa medaglia."
  },
  AvgDialog_58329_Content_18 = {
    Text = "Interessante... molto interessante. Come sei riuscito a capirlo?"
  },
  AvgDialog_58329_Content_19 = {
    Text = "Non l'hai detto tu fin dall'inizio: \"Non fidarti di nessuno.\" Ho molti difetti, ma la mia naturale diffidenza è qualcosa che non cambierò in tutta la vita."
  },
  AvgDialog_58329_Content_2 = {
    Text = "No... Perché..."
  },
  AvgDialog_58329_Content_20 = {
    Text = "Il primo sospetto è sorto quando ho visto il corpo di Sorel. Era stata colpita frontalmente e non aveva altre ferite."
  },
  AvgDialog_58329_Content_21 = {
    Text = "La ferita da proiettile sulla fronte presentava pesanti residui di fuliggine e bruciature da polvere da sparo, il che indica due cose."
  },
  AvgDialog_58329_Content_22 = {
    Text = "Primo: l'assassino le ha sparato da distanza molto ravvicinata."
  },
  AvgDialog_58329_Content_23 = {
    Text = "E il secondo punto?"
  },
  AvgDialog_58329_Content_24 = {
    Text = "Suggerisce che il colpevole è qualcuno di cui la vittima si fidava e con cui aveva abbassato la guardia. L'unica persona qui che corrisponde a questa descrizione è %player%."
  },
  AvgDialog_58329_Content_25 = {
    Text = "Ti sei affrettato a ucciderla perché avevo scoperto il segreto del disco in vinile."
  },
  AvgDialog_58329_Content_26 = {
    Text = "E non volevi che il gioco finisse in anticipo, vero?"
  },
  AvgDialog_58329_Content_27 = {
    Text = "N scrollò le spalle con noncuranza."
  },
  AvgDialog_58329_Content_28 = {
    Text = "Solo qualche sospetto infondato, eppure hai avuto il coraggio di sparare al Custode? Sei davvero il giocatore d'azzardo che ho scelto."
  },
  AvgDialog_58329_Content_29 = {
    Text = "Se io fossi {Male=quel Sig.,Female=quella Sig.na} %player%, in questo momento verserei lacrime per la vostra spietatezza."
  },
  AvgDialog_58329_Content_3 = {
    Text = "Crolli in ginocchio. Un dolore tenue si irradia dal petto, il sangue rosso scuro impregna la giacca della tua uniforme."
  },
  AvgDialog_58329_Content_30 = {
    Text = "Hehe, non scherzerei mai sulla vita di %hisorher%. C'è solo un motivo per cui ho osato spararti..."
  },
  AvgDialog_58329_Content_31 = {
    Text = "<Yellow:So da tempo dove si trova {Male=lui,Female=lei}.>"
  },
  AvgDialog_58329_Content_32 = {Text = "?!"},
  AvgDialog_58329_Content_33 = {
    Text = "Solo un'ora fa."
  },
  AvgDialog_58329_Content_34 = {
    Text = [[
Tenuta Farlander - Bara
Un'ora fa]]
  },
  AvgDialog_58329_Content_35 = {
    Text = "Un caos primordiale e caldo."
  },
  AvgDialog_58329_Content_36 = {
    Text = "Chiudi gli occhi, lasciando sprofondare la tua coscienza al livello più profondo."
  },
  AvgDialog_58329_Content_37 = {
    Text = "Alla fine, \"tu\" arrivi finalmente ai piedi dell'alto muro."
  },
  AvgDialog_58329_Content_38 = {
    Text = "Questo è il <Yellow:Muro della Verità>. Coperto dal sipario davanti ai tuoi occhi, solo un angolo viene svelato durante una cerimonia che si tiene ogni pochi anni."
  },
  AvgDialog_58329_Content_39 = {
    Text = "Sigilla il passato, registra il presente e predice il futuro."
  },
  AvgDialog_58329_Content_4 = {
    Text = "Sciocco... Che stai dicendo..."
  },
  AvgDialog_58329_Content_40 = {
    Text = "Il sacerdote parla e si inginocchia davanti a te con reverenza."
  },
  AvgDialog_58329_Content_41 = {
    Text = "Incluso il tuo arrivo, Karnahk."
  },
  AvgDialog_58329_Content_42 = {
    Text = "Sta piovendo."
  },
  AvgDialog_58329_Content_43 = {
    Text = "Ti inginocchi davanti al vasto dipinto, gemendo come una bestia in trappola che finalmente trova liberazione. L'acqua piovana si mescola alle tue lacrime, scorrendo dalle sopracciglia e dagli occhi."
  },
  AvgDialog_58329_Content_44 = {
    Text = "Dopo migliaia di anni, sei finalmente diventato il Faraone di Remouahe."
  },
  AvgDialog_58329_Content_45 = {
    Text = "Hai incontrato il tuo destino."
  },
  AvgDialog_58329_Content_46 = {
    Text = "Più tardi..."
  },
  AvgDialog_58329_Content_47 = {
    Text = "Fatti da parte. Farò a brandelli quelle maledette tende!"
  },
  AvgDialog_58329_Content_48 = {
    Text = "Nobile Figlio di Amon, non dovreste essere qui. Chiunque sfidi il Muro della Verità vedrà la morte calare sul proprio capo."
  },
  AvgDialog_58329_Content_49 = {
    Text = "Heh. Pestilenza, carestia, e ora l'esercito di Apophis è fuori dalle mura della città. Apri gli occhi e guarda il mondo, Sacerdote cieco — la Morte è già arrivata."
  },
  AvgDialog_58329_Content_5 = {
    Text = "Ryker esaminò la pistola finemente lavorata nella sua mano, poi soffiò con calma sulla canna."
  },
  AvgDialog_58329_Content_50 = {
    Text = "Ho seguito devotamente le istruzioni del Muro, ma ho portato calamità al popolo che viveva lungo le rive del fiume da generazioni. Questa è la conseguenza dell'obbedienza cieca."
  },
  AvgDialog_58329_Content_51 = {
    Text = "Siate paziente, giovane signore di Remouahe. Ciò che è stato fatto riguarda l'aldilà; ciò che sarà fatto riguarda l'eternità. L'aldilà non è che luce del giorno, mentre l'eternità è la notte."
  },
  AvgDialog_58329_Content_52 = {
    Text = "Il Muro della Verità porta sia miele e papiro, sia veleno e pestilenza."
  },
  AvgDialog_58329_Content_53 = {
    Text = "Solo seguendo la sua volontà le nostre anime potranno attraversare in sicurezza il fiume notturno dopo la morte, divenendo eterne sulla riva lontana—"
  },
  AvgDialog_58329_Content_54 = {
    Text = "Non mi importa dell'\"eternità\" che voi vampiri bugiardi sputate fuori. Io vedo solo le mie terre conquistate con fatica svanire in una notte, la mia gente morire uno dopo l'altro."
  },
  AvgDialog_58329_Content_55 = {
    Text = "Persino il mio subordinato più fidato, <Blue:Apophis>, ha rivolto la lama contro di me. È là fuori ora, in attesa di prendere la mia testa e appenderla in alto sulle mura."
  },
  AvgDialog_58329_Content_56 = {
    Text = "Ho perso tutto, Sacerdote. Se questa è la disposizione del mio misero destino da parte del Muro della Verità, terrò gli occhi ben aperti e lo guarderò morire."
  },
  AvgDialog_58329_Content_57 = {
    Text = "\"Tu\" spingi da parte l'anziano Sacerdote e strappi via il velo."
  },
  AvgDialog_58329_Content_58 = {
    Text = "Da questo momento in poi, le verità del mondo si dispiegano davanti a \"te\"."
  },
  AvgDialog_58329_Content_59 = {
    Text = "Uno, due..."
  },
  AvgDialog_58329_Content_6 = {
    Text = "Vedendo il tuo stato pietoso, sfoggiò un sorriso sinistro."
  },
  AvgDialog_58329_Content_60 = {
    Text = "Innumerevoli graffiti rozzi di faccine sorridenti, dipinti in rosso mattone, con bocche spalancate, ridono beffardamente della \"tua\" disperazione."
  },
  AvgDialog_58329_Content_61 = {
    Text = "Capisco, questa è la cosiddetta verità. Hehe...hahahaha..."
  },
  AvgDialog_58329_Content_62 = {
    Text = "Assurdità. Disprezzo. Questa è la verità del mondo."
  },
  AvgDialog_58329_Content_63 = {Text = "!!!"},
  AvgDialog_58329_Content_64 = {
    Text = "Un istante dopo, il dipinto su pergamena svanì, e l'oscurità tornò ancora una volta."
  },
  AvgDialog_58329_Content_65 = {
    Text = "Nessun deserto, nessun Sacerdote, nessuna pergamena; sei solo in una bara buia."
  },
  AvgDialog_58329_Content_66 = {
    Text = "I tuoi pensieri sono ancora intrappolati nei ricordi di Karnahk; un'ondata infinita di dolore ti avvolge."
  },
  AvgDialog_58329_Content_67 = {
    Text = "Le lacrime non potevano più essere trattenute, come un'interminabile cortina di pioggia."
  },
  AvgDialog_58329_Content_68 = {
    Text = "<Change>No... Io..."
  },
  AvgDialog_58329_Content_69 = {
    Text = "<Change>Voglio solo restare in vita..."
  },
  AvgDialog_58329_Content_7 = {
    Text = "Il motivo per cui non ti ho impedito di mandare via Hannah era il timore che non potesse reggere la verità. Dopotutto, è solo una studentessa qualunque."
  },
  AvgDialog_58329_Content_70 = {
    Text = "Toc. Toc toc."
  },
  AvgDialog_58329_Content_71 = {
    Text = "Un bussare lontano interrompe il ritmo eterno di questo oceano di dolore. Poi, senti una voce familiare—"
  },
  AvgDialog_58329_Content_72 = {
    Text = "Ehi, amico nella bara, stai bene?"
  },
  AvgDialog_58329_Content_8 = {
    Text = "E tu, amico mio—"
  },
  AvgDialog_58329_Content_9 = {
    Text = "Sapevo che non avresti resistito alla tentazione di esibirti. Ehi, recitare è divertente?"
  },
  AvgDialog_58330_Content_1 = {
    Text = "Spettacolo Tragico"
  },
  AvgDialog_58330_Content_10 = {
    Text = "Ho un'opinione diversa su questo punto, ma per ora lasciamolo da parte. Cosa è successo dopo che il Signor Dexter è uscito?"
  },
  AvgDialog_58330_Content_100 = {
    Text = "Perché non avete identificato il vero assassino di Lady Sorel. Le vostre deduzioni evitano deliberatamente la sua morte, non è vero?"
  },
  AvgDialog_58330_Content_101 = {
    Text = "Di cosa hai paura?"
  },
  AvgDialog_58330_Content_102 = {Text = "..."},
  AvgDialog_58330_Content_103 = {
    Text = "È un peccato che abbiate perso un altro amico. Forse la fortuna in questo mondo è limitata."
  },
  AvgDialog_58330_Content_104 = {
    Text = "Avete ottenuto buona sorte, la vostra vita è migliorata notevolmente, ma altri hanno subito grandi sventure a causa di ciò."
  },
  AvgDialog_58330_Content_105 = {
    Text = "Riesci davvero ad accettare le leggi invisibili che incombono sulle teste delle persone?"
  },
  AvgDialog_58330_Content_106 = {
    Text = "Heh... Che mucchio di sciocchezze, è solo il tuo piccolo gioco personale."
  },
  AvgDialog_58330_Content_107 = {
    Text = "La vostra ostilità nei miei confronti resta così genuina, adorabile, eppure deplorevole."
  },
  AvgDialog_58330_Content_108 = {
    Text = "Sebbene non siate riusciti a risolvere tutti gli enigmi, io sono sempre stato molto indulgente..."
  },
  AvgDialog_58330_Content_109 = {
    Text = "N alzò un dito, scagliando una densa nebbia nera verso di te, avvolgendoti in una morsa stretta."
  },
  AvgDialog_58330_Content_11 = {Text = "...!!"},
  AvgDialog_58330_Content_110 = {Text = "No... Ugh!"},
  AvgDialog_58330_Content_111 = {Text = "!!"},
  AvgDialog_58330_Content_112 = {
    Text = "Signor N, so che le mie azioni ad Aram vi hanno fatto adirare, e me ne scuso sinceramente."
  },
  AvgDialog_58330_Content_113 = {
    Text = "Potete punirmi come volete, ma non c'è bisogno di prendervela con {Male=lui,Female=lei}."
  },
  AvgDialog_58330_Content_114 = {
    Text = "Detective impaziente, ascoltami. Ho un'ultima domanda preparata per te."
  },
  AvgDialog_58330_Content_115 = {
    Text = "...Va bene, ti ascolto."
  },
  AvgDialog_58330_Content_116 = {
    Text = "Una scelta semplice: <Red:Uccidi %player%, e io resusciterò tutti coloro che sono morti finora.>"
  },
  AvgDialog_58330_Content_117 = {
    Text = "Tutto tornerà alla normalità, tranne che per questo sfortunato qui accanto a te. Nessun altro verrà ferito."
  },
  AvgDialog_58330_Content_118 = {
    Text = "Oppure potresti scegliere di non uccidere %player%, e entrambi potrete lasciare il Dominio in sicurezza."
  },
  AvgDialog_58330_Content_119 = {
    Text = "Era davvero così semplice?"
  },
  AvgDialog_58330_Content_12 = {
    Text = "Ricordate il fantasma che ho visto prima nel vano scale? Fluttuava a mezz'aria, il fantasma, l'impiccagione... Potrebbe essere che..."
  },
  AvgDialog_58330_Content_120 = {Text = "?!"},
  AvgDialog_58330_Content_121 = {Text = "..."},
  AvgDialog_58330_Content_122 = {
    Text = "Hai ancora la tua pistola con te? Il conto alla rovescia inizia ora. 10."
  },
  AvgDialog_58330_Content_123 = {
    Text = "No, non puoi..."
  },
  AvgDialog_58330_Content_124 = {Text = "9"},
  AvgDialog_58330_Content_125 = {
    Text = "Ryker ti guardò con aria stordita, come un bambino che avesse fatto qualcosa di sbagliato."
  },
  AvgDialog_58330_Content_126 = {
    Text = "Non preoccuparti per me, cough... Forse mi trasformeranno in un Risvegliatore se muoio."
  },
  AvgDialog_58330_Content_127 = {
    Text = "Contrai tutti i muscoli del viso per rivolgere a Ryker un sorriso forzato."
  },
  AvgDialog_58330_Content_128 = {Text = "... Fallo."},
  AvgDialog_58330_Content_129 = {Text = "6"},
  AvgDialog_58330_Content_13 = {
    Text = "Esatto. La verità è: qualcuno ha distratto il Signor Dexter, poi gli ha infilato un cappio al collo nel momento in cui si è sporto, e lo ha stretto con forza —"
  },
  AvgDialog_58330_Content_130 = {
    Text = "Ryker camminò lentamente verso di te, lo sguardo calmo e imperturbabile."
  },
  AvgDialog_58330_Content_131 = {
    Text = "Mentre la vista si offuscava gradualmente, fissasti i suoi occhi, e i ricordi dei momenti trascorsi insieme ti balenarono nella mente."
  },
  AvgDialog_58330_Content_132 = {
    Text = "Ci sono momenti trascorsi a inseguirsi giocosamente nel deserto, a fuggire insieme dalla ■■ raccolta degli Aram, e lui che usa la sua vita come esca per contaminare Casiah..."
  },
  AvgDialog_58330_Content_133 = {
    Text = "Ci sono troppi ricordi tra voi due."
  },
  AvgDialog_58330_Content_134 = {
    Text = "Senza che te ne accorgessi, Ryker era già in piedi davanti a te. Non riuscivi a vedere il suo volto, ma sapevi che il suo dolore non era inferiore al tuo."
  },
  AvgDialog_58330_Content_135 = {
    Text = "Un istante dopo, alzò la pistola."
  },
  AvgDialog_58330_Content_136 = {
    Text = "Sai una cosa... non ho mai dubitato di te. Quindi—"
  },
  AvgDialog_58330_Content_137 = {
    Text = "Lo sparo risuona, colpendo esattamente dove si trova il tuo cuore, in pieno centro."
  },
  AvgDialog_58330_Content_138 = {Text = "Cosa...?"},
  AvgDialog_58330_Content_139 = {
    Text = "Ryker era in piedi sopra di te, un sorriso beffardo sulle labbra."
  },
  AvgDialog_58330_Content_14 = {
    Text = "Ryker alzò il viso, indicando la camera da letto al secondo piano."
  },
  AvgDialog_58330_Content_140 = {
    Text = "Aspettavo questo momento da molto tempo, Custode."
  },
  AvgDialog_58330_Content_15 = {
    Text = "<Yellow:L'assassino era nella camera da letto del Signor Dexter.> Le due stanze sono in linea retta."
  },
  AvgDialog_58330_Content_16 = {
    Text = "Brillante! Questo spiega l'evento del fantasma e le impronte sul telaio della finestra: sono dovute ai tentativi di divincolarsi del Sig. Dexter dopo essere stato legato."
  },
  AvgDialog_58330_Content_17 = {
    Text = "Ma serve una grande forza nelle braccia e precisione nell'angolazione, e tutti qui avevano le loro abilità sigillate, come"
  },
  AvgDialog_58330_Content_18 = {
    Text = "Hannah si interrompe a metà frase, mentre un sospetto prende forma nella sua mente."
  },
  AvgDialog_58330_Content_19 = {
    Text = "Ma... dopo l'evento del fantasma, siamo saliti rapidamente al piano di sopra in camera da letto. Non abbiamo sentito altri rumori in quel lasso di tempo. L'assassino deve essere ancora nella camera da letto"
  },
  AvgDialog_58330_Content_2 = {
    Text = "Etciù... Etciù!"
  },
  AvgDialog_58330_Content_20 = {
    Text = "A parte quel grammofono, nient'altro sembrava insolito... ETCIÙ! ETCIÙ!"
  },
  AvgDialog_58330_Content_21 = {
    Text = "Hannah si asciuga due fili luccicanti di muco dal naso."
  },
  AvgDialog_58330_Content_22 = {
    Text = "Padre celeste, com'è possibile prendersi un raffreddore persino in un Dominio!"
  },
  AvgDialog_58330_Content_23 = {Text = "..."},
  AvgDialog_58330_Content_24 = {
    Text = "Abbiamo già discusso dell'esterno. Sbrighiamoci ad andare dentro..."
  },
  AvgDialog_58330_Content_25 = {
    Text = "Pensaci bene. Cosa è successo dopo che abbiamo sfondato la porta?"
  },
  AvgDialog_58330_Content_26 = {
    Text = "Cosa è successo..."
  },
  AvgDialog_58330_Content_27 = {
    Text = "Scusate, non mi sento bene. Posso fare una breve pausa?"
  },
  AvgDialog_58330_Content_28 = {
    Text = "Scusate @2... Non mi sento bene... Devo riposare..."
  },
  AvgDialog_58330_Content_29 = {
    Text = "Riposo riposo@2 riposo..."
  },
  AvgDialog_58330_Content_3 = {
    Text = "L'effetto refrigerante di questo Dominio è davvero impressionante. Capo, non possiamo ragionare davanti a un camino al chiuso?"
  },
  AvgDialog_58330_Content_30 = {
    Text = "Per favore, uscite tutti il prima possibile e non disturbate il riposo del Signor Dexter."
  },
  AvgDialog_58330_Content_31 = {
    Text = "<Shake:Whoa!! Quando hai...>"
  },
  AvgDialog_58330_Content_32 = {
    Text = "Proprio come sospettavo..."
  },
  AvgDialog_58330_Content_33 = {
    Text = "Hannah alza improvvisamente la testa, fissando lo sguardo direttamente su Erica dietro la folla."
  },
  AvgDialog_58330_Content_34 = {
    Text = "Non eri una ritardataria. Eri nella stanza fin dall'inizio... Forse nascosta dietro la porta, attirando la nostra attenzione mentre eravamo tutti concentrati sul grammofono."
  },
  AvgDialog_58330_Content_35 = {
    Text = "Respinto. Erica non ha la capacità di trovarsi in due posti contemporaneamente, rendendo impossibile spiegare perché il defunto sia apparso nello studio."
  },
  AvgDialog_58330_Content_36 = {
    Text = "Sì, ti manca la capacità di essere in due posti contemporaneamente. Quindi, hai un complice."
  },
  AvgDialog_58330_Content_37 = {Text = "!!"},
  AvgDialog_58330_Content_38 = {
    Text = "Strangolare un uomo adulto a mezz'aria con un braccio meccanico retrattile è un gioco da ragazzi per la Signorina Erica."
  },
  AvgDialog_58330_Content_39 = {
    Text = "Proprio come hai allungato il braccio per segare il ponte di legno prima."
  },
  AvgDialog_58330_Content_4 = {
    Text = "State tranquilli, non ruberò troppo tempo a nessuno."
  },
  AvgDialog_58330_Content_40 = {
    Text = "Dopo che il Sig. Dexter smette di respirare, lo getti da parte, e il complice che era in attesa trascina il corpo nello studio."
  },
  AvgDialog_58330_Content_41 = {
    Text = "Questo spiega anche perché sul cadavere siano presenti due segni di strangolamento, così come l'umidità sui vestiti — poiché il corpo era stato trascinato nella neve."
  },
  AvgDialog_58330_Content_42 = {
    Text = "Il complice deve essere l'unica persona senza un alibi dallo sparo al momento del crimine..."
  },
  AvgDialog_58330_Content_43 = {
    Text = "Ryker guarda verso l'armadio nell'angolo dello studio mentre parla."
  },
  AvgDialog_58330_Content_44 = {
    Text = "Lady Sorel."
  },
  AvgDialog_58330_Content_45 = {
    Text = "Capisco. Pensavo che il Sig. Dexter fosse stato strangolato a mezz'aria, ma non mi sarei mai aspettato che ci fosse un complice."
  },
  AvgDialog_58330_Content_46 = {
    Text = "Respinto. Tutte le deduzioni sopra esposte sono speculative e prive di prove concrete."
  },
  AvgDialog_58330_Content_47 = {
    Text = "Vuoi delle prove? È abbastanza semplice."
  },
  AvgDialog_58330_Content_48 = {
    Text = "Ricordi i segni dei due solchi di strangolamento sul collo?"
  },
  AvgDialog_58330_Content_49 = {
    Text = "Anche i segni delle due impronte sono diversi. Quella interna ha una struttura a diamante regolare, mentre quella esterna è più grezza..."
  },
  AvgDialog_58330_Content_5 = {
    Text = "Prima di tutto, le scarpe all'esterno. Domanda: in quali circostanze delle scarpe finirebbero fuori?"
  },
  AvgDialog_58330_Content_50 = {
    Text = "Forse la corda si è spezzata a metà, o si è sporcata di sangue, e l'assassino l'ha sostituita."
  },
  AvgDialog_58330_Content_51 = {Text = "!!"},
  AvgDialog_58330_Content_52 = {
    Text = "Forme a rombo ben definite. Signorina Erica, potrebbe estendere il suo braccio meccanico per mostrarci la fune retrattile al suo interno?"
  },
  AvgDialog_58330_Content_53 = {Text = "..."},
  AvgDialog_58330_Content_54 = {
    Text = "Catturare al collo con una corda un uomo adulto e guardingo al secondo piano è praticamente impossibile."
  },
  AvgDialog_58330_Content_55 = {
    Text = "Ma se la corda fa parte del tuo corpo, allora tutto ha senso."
  },
  AvgDialog_58330_Content_56 = {
    Text = "Quindi siete stata voi, Signorina Erica..."
  },
  AvgDialog_58330_Content_57 = {
    Text = "Erica estende lentamente il braccio destro. Sotto la luce, il cavo di collegamento tra l'avambraccio e la mano brilla in modo inquietante"
  },
  AvgDialog_58330_Content_58 = {
    Text = "Quei motivi a forma di diamante sono disposti in file ordinate, come le scaglie di un pesce del mare profondo."
  },
  AvgDialog_58330_Content_59 = {
    Text = "Proprio come mi aspettavo... esattamente uguali..."
  },
  AvgDialog_58330_Content_6 = {
    Text = "Mm... il defunto è uscito e poi ha avuto un incidente?"
  },
  AvgDialog_58330_Content_60 = {
    Text = "Erica non risponde. Una nebbia nera fuoriesce da lei, rivelando un'altra figura familiare."
  },
  AvgDialog_58330_Content_61 = {
    Text = "Ragionamento eccellente!"
  },
  AvgDialog_58330_Content_62 = {
    Text = "Quindi questa cosiddetta Signorina Erica è la tua sosia... il che significa che in realtà la Signorina Erica è sana e salva!"
  },
  AvgDialog_58330_Content_63 = {
    Text = "Voi non capireste il divertimento dei giochi di ruolo, hehe."
  },
  AvgDialog_58330_Content_64 = {
    Text = "Il ragionamento che hai appena presentato è la tua risposta definitiva?"
  },
  AvgDialog_58330_Content_65 = {Text = "...Sì."},
  AvgDialog_58330_Content_66 = {Text = "..."},
  AvgDialog_58330_Content_67 = {
    Text = "Heh... Che peccato. Mancava solo un passo."
  },
  AvgDialog_58330_Content_68 = {
    Text = "Questa non è la verità definitiva, quindi—"
  },
  AvgDialog_58330_Content_69 = {
    Text = "N schioccò le dita, e una nebbia oscura iniziò a fuoriuscire dal corpo di Hannah, riempiendo lo studio."
  },
  AvgDialog_58330_Content_7 = {
    Text = "È effettivamente una possibilità. Dal confronto, abbiamo scoperto che il disegno della suola di questa scarpa corrisponde perfettamente all'impronta lasciata sul telaio della finestra."
  },
  AvgDialog_58330_Content_70 = {
    Text = "Afferrò il cappotto di Ryker in preda al panico."
  },
  AvgDialog_58330_Content_71 = {
    Text = "Com'è possibile? Nemmeno la Signorina Erica ha negato?!"
  },
  AvgDialog_58330_Content_72 = {Text = "..."},
  AvgDialog_58330_Content_73 = {
    Text = "Tsk, tsk, tsk, il tuo compagno Custode è troppo impulsivo, ricordati di parlare prima di {Male=lui,Female=lei} la prossima volta~"
  },
  AvgDialog_58330_Content_74 = {
    Text = "Scusa, Hanna. Io..."
  },
  AvgDialog_58330_Content_75 = {
    Text = "Salvami...! Non ho ancora sentito la verità finale, non..."
  },
  AvgDialog_58330_Content_76 = {
    Text = "Un istante dopo, anche Hannah svanì davanti ai tuoi occhi."
  },
  AvgDialog_58330_Content_77 = {Text = "Hanna—!"},
  AvgDialog_58330_Content_78 = {
    Text = "Cosa ho fatto..."
  },
  AvgDialog_58330_Content_79 = {
    Text = "No, è tutta colpa mia... Sono stata troppo impaziente."
  },
  AvgDialog_58330_Content_8 = {
    Text = "Il Nobile Dexter, che tiene sempre all'etichetta, si arrampicherebbe fuori di casa dalla finestra, specialmente quando la serratura della porta è in perfette condizioni?"
  },
  AvgDialog_58330_Content_80 = {
    Text = "Mm, ora siamo rimasti solo noi tre. Quanto agli altri, devono star soffrendo nel mondo reale."
  },
  AvgDialog_58330_Content_81 = {
    Text = "Hehehe, interessante, molto interessante!"
  },
  AvgDialog_58330_Content_82 = {
    Text = [[
Infermeria di Mythag
Nel frattempo...]]
  },
  AvgDialog_58330_Content_83 = {
    Text = "Com'è la situazione?"
  },
  AvgDialog_58330_Content_84 = {
    Text = "Anche la Signorina Hannah e il Custode stanno peggiorando. Gli organi interni della Signorina Hannah hanno subito rotture multiple per cause ignote, con segni di emorragia."
  },
  AvgDialog_58330_Content_85 = {
    Text = "Il Custode sta manifestando gravi sintomi di asfissia. Se continuiamo a temporeggiare..."
  },
  AvgDialog_58330_Content_86 = {
    Text = "Abbiamo interrogato molti studenti e il nostro team tecnico ha ispezionato tutte le strutture senza trovare anomalie."
  },
  AvgDialog_58330_Content_87 = {
    Text = "Fare tutto questo trambusto proprio sotto gli occhi di tutti..."
  },
  AvgDialog_58330_Content_88 = {Text = "...N？"},
  AvgDialog_58330_Content_89 = {
    Text = "Alistair e io siamo d'accordo. Se si tratta di Lui, tutto ha senso."
  },
  AvgDialog_58330_Content_9 = {
    Text = "Ha visto qualcosa fuori dalla finestra e si è precipitato fuori?"
  },
  AvgDialog_58330_Content_90 = {
    Text = "Che facciamo? Non abbiamo alcuna contromisura..."
  },
  AvgDialog_58330_Content_91 = {
    Text = "Doll accarezzò la testa rotonda che teneva in mano e lasciò sfuggire un lieve sospiro."
  },
  AvgDialog_58330_Content_92 = {
    Text = "Una cosa è certa: non sembra ancora intenzionato a togliere la vita al Custode."
  },
  AvgDialog_58330_Content_93 = {
    Text = "Per il resto... ti suggerisco di pregare insieme a me."
  },
  AvgDialog_58330_Content_94 = {
    Text = "Bene, ora che gli estranei se ne sono andati, possiamo essere sinceri."
  },
  AvgDialog_58330_Content_95 = {
    Text = "Una nebbia agghiacciante si levò dal corpo di N, sovrapponendosi al Suo volto strato dopo strato fino a oscurarne completamente l'aspetto originale."
  },
  AvgDialog_58330_Content_96 = {
    Text = "Non solo, ma la stanza in cui vi trovate svanisce all'improvviso, sostituita dal familiare teatro dell'opera."
  },
  AvgDialog_58330_Content_97 = {
    Text = "Scusate, non amo gli spazi angusti."
  },
  AvgDialog_58330_Content_98 = {
    Text = "È da tanto che non ci vediamo, miei vecchi amici."
  },
  AvgDialog_58330_Content_99 = {
    Text = "Cosa intendevi prima? Questa non è la verità ultima...?"
  },
  AvgDialog_58331_Content_1 = {
    Text = "Ora, Apophis!"
  },
  AvgDialog_58331_Content_10 = {
    Text = "Ryker avanzò passo dopo passo verso N."
  },
  AvgDialog_58331_Content_11 = {
    Text = "Sembra che la fortuna finalmente mi abbia sorriso."
  },
  AvgDialog_58331_Content_12 = {
    Text = "Stai attento, Detective. Per un giocatore d'azzardo incorreggibile, la cosa più spaventosa in una scommessa non è perdere, ma vincere."
  },
  AvgDialog_58331_Content_13 = {
    Text = "Se non mi credi, potresti chiedere al padrone di questo serpente nero."
  },
  AvgDialog_58331_Content_14 = {
    Text = "Sembra che tu ancora non mi conosca bene, ma hai ragione su una cosa."
  },
  AvgDialog_58331_Content_15 = {
    Text = "Ryker alzò la pistola, puntandola verso il volto nebbioso di N."
  },
  AvgDialog_58331_Content_16 = {
    Text = "Sono davvero un giocatore d'azzardo senza speranza. A prescindere dalla fortuna, anche sapendo che perderò tutto, punterò comunque il tutto per tutto."
  },
  AvgDialog_58331_Content_17 = {
    Text = "Solo coloro che sono benedetti dal destino osano correre rischi; sono persone comuni, non giocatori d'azzardo. Quando mi scegliesti allora, non fu forse perché vedesti questo in me?"
  },
  AvgDialog_58331_Content_18 = {
    Text = "Hah... Hahaha... Sei davvero un pazzo. Cedere ai tuoi istinti primordiali, che sciocco e ingenuo, Signor Giocatore d'Azzardo."
  },
  AvgDialog_58331_Content_19 = {
    Text = "Lo stesso vale per me. Il mio più grande vantaggio rispetto agli altri giocatori d'azzardo è —"
  },
  AvgDialog_58331_Content_2 = {
    Text = "Al tuo comando, il serpente re oscuro scattò in avanti rapidamente, trafiggendo il corpo di N e avvolgendosi strettamente attorno ad esso."
  },
  AvgDialog_58331_Content_21 = {
    Text = "Accetto la mia sconfitta con onore."
  },
  AvgDialog_58331_Content_22 = {
    Text = "Il grilletto viene premuto delicatamente."
  },
  AvgDialog_58331_Content_23 = {
    Text = "Risuonò uno sparo, e la testa di N si inclinò dolcemente di lato."
  },
  AvgDialog_58331_Content_24 = {
    Text = "Hai davvero fretta, vero? Stavo già pensando di accompagnarti all'uscita."
  },
  AvgDialog_58331_Content_25 = {
    Text = "Prima di andarmene, lascia che ti riveli un segreto—"
  },
  AvgDialog_58331_Content_26 = {
    Text = "In realtà, non ho mai riscritto il tuo destino. Barare in un gioco così interessante non avrebbe portato alcuna gioia."
  },
  AvgDialog_58331_Content_27 = {
    Text = "Addio, Detective."
  },
  AvgDialog_58331_Content_3 = {
    Text = "La nebbia nera emanata dal Serpente Re si fonde con la nebbia nera di N, conferendoGli gradualmente una forma fisica."
  },
  AvgDialog_58331_Content_4 = {
    Text = "Da quanto tempo, piccolo animale domestico di Kanak. Il tuo padrone è ancora arrabbiato?"
  },
  AvgDialog_58331_Content_5 = {
    Text = "Il padrone non nutre alcun odio verso di te. Le sue azioni sono state sancite da te. Noi ci limitiamo a seguire fedelmente il copione."
  },
  AvgDialog_58331_Content_6 = {
    Text = "Davvero... interessante. Nemmeno io me ne ero reso conto."
  },
  AvgDialog_58331_Content_7 = {
    Text = "La lingua sottile del serpente re guizzò, portando la sua voce bassa e suadente alle tue orecchie."
  },
  AvgDialog_58331_Content_8 = {
    Text = "Posso intrappolare la Sua proiezione nel Dominio solo per un po'. Una volta che la proiezione si ritirerà, il Dominio verrà dissolto."
  },
  AvgDialog_58331_Content_9 = {
    Text = "Poi... sta a te."
  },
  AvgDialog_58332_Content_1 = {
    Text = "L'ultimo saluto"
  },
  AvgDialog_58332_Content_10 = {
    Text = "Come lacrime."
  },
  AvgDialog_58332_Content_11 = {
    Text = "Cosa è successo dopo? Dopo che hai visto... la cosiddetta verità."
  },
  AvgDialog_58332_Content_12 = {
    Text = "Dopo... ho soppresso la ribellione e trasformato Apophis in un serpente, avvolto ai miei piedi per l'eternità."
  },
  AvgDialog_58332_Content_13 = {
    Text = "Ho ordinato che il Muro della Verità fosse completamente sigillato, e poi ho iniziato il mio regno."
  },
  AvgDialog_58332_Content_14 = {
    Text = "Nessuna ideologia, nessun sistema, nessun parlamento... Semplicemente stilo una lista di nomi, li esilio uno per uno e confisco i loro beni."
  },
  AvgDialog_58332_Content_15 = {
    Text = "Ho conferito medaglie ai cittadini che hanno visitato il casinò più di 50 volte e ordinato la costruzione di una piramide di vetro perennemente incompiuta nella capitale..."
  },
  AvgDialog_58332_Content_16 = {
    Text = "Beffato dal destino, hai scelto di diventare un tiranno. In seguito, sei stato rovesciato?"
  },
  AvgDialog_58332_Content_17 = {
    Text = "Tutto il contrario, la mia nazione prospera. Sai perché?"
  },
  AvgDialog_58332_Content_18 = {
    Text = "Scuotesti la testa. La nebbia nera ridacchiò compiaciuta."
  },
  AvgDialog_58332_Content_19 = {
    Text = "Anche la più piccola guerra condotta da un tiranno razionale costa mille volte di più del prezzo pagato dal popolo per i miei capricci."
  },
  AvgDialog_58332_Content_2 = {
    Text = "In precedenza..."
  },
  AvgDialog_58332_Content_20 = {Text = "..."},
  AvgDialog_58332_Content_21 = {
    Text = "Ma tu non sei felice, e il tuo popolo non sarà soddisfatto di azioni così capricciose. Che senso ha?"
  },
  AvgDialog_58332_Content_22 = {
    Text = "Senso? Inseguire la cosiddetta felicità e uno scopo significa cadere nella trappola di quell'adulto. Non sono né felice né triste."
  },
  AvgDialog_58332_Content_23 = {
    Text = "Mi limito a interpretare fedelmente il ruolo che il Destino mi richiede di giocare."
  },
  AvgDialog_58332_Content_24 = {Text = "Esso...?"},
  AvgDialog_58332_Content_25 = {
    Text = "Fissando i graffiti malevoli eppure stranamente familiari, all'improvviso hai capito tutto."
  },
  AvgDialog_58332_Content_26 = {
    Text = "Quindi sei tu, N..."
  },
  AvgDialog_58332_Content_27 = {
    Text = "Quindi sei diventato un sacrificio per il capriccio di quella persona. Ora siamo entrambi bloccati qui, incapaci di fare qualsiasi cosa..."
  },
  AvgDialog_58332_Content_28 = {
    Text = "L'hai sentito? Il suono dello sparo: il tuo amico non si è ancora arreso."
  },
  AvgDialog_58332_Content_29 = {
    Text = "Mentre leggevo i miei ricordi, ho letto anche i tuoi. Per Lui, tu e quel detective... siete diversi."
  },
  AvgDialog_58332_Content_3 = {Text = "Bang—!"},
  AvgDialog_58332_Content_30 = {
    Text = "Quindi non mi dispiace farGli una sorpresa."
  },
  AvgDialog_58332_Content_31 = {
    Text = "La nebbia oscura vorticò attorno a Karnahk, condensandosi gradualmente in un cobra reale nero come la pece."
  },
  AvgDialog_58332_Content_32 = {
    Text = "Spero che tu non stia disturbando il mio sonno per noia, mio vecchio amico."
  },
  AvgDialog_58332_Content_33 = {
    Text = "È da tanto che non ci vediamo, Apophis. Quest{Male=o,Female=a} è un{Male=,Female='} nuov{Male=o amico,Female=a amica}, {Male=lui,Female=lei} ha bisogno del tuo aiuto."
  },
  AvgDialog_58332_Content_34 = {
    Text = "Apophis si erge con grazia, il collo dolcemente ricurvo, le pupille verticali color smeraldo che ti osservano in silenzio."
  },
  AvgDialog_58332_Content_35 = {
    Text = "Il segreto della vita eterna non è altro che il dimenticare. Il mio maestro ti ha dimenticato ancora una volta, proprio come non ricorda il suo passato a Taranto."
  },
  AvgDialog_58332_Content_36 = {
    Text = "Ma io conosco il tuo spirito, il pallido Occhio Cieco."
  },
  AvgDialog_58332_Content_37 = {
    Text = "Mi hai... già incontrato?"
  },
  AvgDialog_58332_Content_38 = {
    Text = "Porta %player% via da qui, Apophis."
  },
  AvgDialog_58332_Content_39 = {
    Text = "Il serpente nero avvolge delicatamente il tuo corpo, mentre la nebbia fluisce dentro di te."
  },
  AvgDialog_58332_Content_4 = {
    Text = "Il suono degli spari sembra provenire da lontano."
  },
  AvgDialog_58332_Content_40 = {
    Text = "Hai chiuso gli occhi. Il tuo corpo vuoto si è riempito di una coscienza inespressa, e il bagliore della chiave d'argento ha brillato ancora una volta."
  },
  AvgDialog_58332_Content_41 = {
    Text = "Un istante dopo, la bara era già svanita, e ti sei ritrovato nell'angolo del teatro, di fronte a Ryker e N al centro del palco."
  },
  AvgDialog_58332_Content_42 = {
    Text = "Un sussurro gentile e razionale riecheggia nel profondo della mia mente."
  },
  AvgDialog_58332_Content_43 = {
    Text = "Ho seguito gli ordini del mio Signore e ti ho portato qui."
  },
  AvgDialog_58332_Content_44 = {
    Text = "L'incubo è finito. Apri gli occhi."
  },
  AvgDialog_58332_Content_5 = {
    Text = "Apri gli occhi e vedi lo stesso muro coperto di caratteri distorti."
  },
  AvgDialog_58332_Content_6 = {
    Text = "A un certo punto aveva iniziato a piovere."
  },
  AvgDialog_58332_Content_7 = {
    Text = "Una nebbia nera aleggia accanto a te. Non riesci a distinguerne i contorni, eppure provi una strana sensazione di familiarità: è Karnahk."
  },
  AvgDialog_58332_Content_8 = {
    Text = "La pioggia continuava a cadere, con il silenzio che scorreva tra voi due."
  },
  AvgDialog_58332_Content_9 = {
    Text = "Strano. Pioveva sia la prima che l'ultima volta che ho visto questo muro."
  },
  AvgDialog_58879_Content_1 = {
    Text = "Ora, Apophis!"
  },
  AvgDialog_58879_Content_10 = {
    Text = "Ryker avanzò passo dopo passo verso N."
  },
