  },
  AvgDialog_98293_Content_2 = {
    Text = "Questa è... la costa di Londinium?"
  },
  AvgDialog_98293_Content_20 = {
    Text = "Non ti muovesti, perché sapevi fin troppo bene che né Murphy né Thais avrebbero dovuto trovarsi lì."
  },
  AvgDialog_98293_Content_21 = {
    Text = "Appartengono a \"quel mondo\" in cui non potrai mai più fare ritorno."
